    [54] = {
        {
            id = 6254544,
            score = 25,
            author = "Stigma666",
            text = "If you're here in 2025 for the housing decor, then go to /way 33,5 52,9\nin Northshire. (For Horde players: Just east of Stormwind ;) )\n\nThere you wanna talk with https://www.wowhead.com/npc=197. Accept the quest https://www.wowhead.com/quest=28757 and take it from there. About 5 super lowie quests later you will receive the https://www.wowhead.com/item=248798 and also an (unexpected) https://www.wowhead.com/item=248621 just before that. :)",
            date = "2025-12-27T14:54:11-06:00",
            sourceUrl = "https://www.wowhead.com/quest=54#comments:id=6254544",
        },
        {
            id = 655091,
            score = 10,
            author = "332449",
            text = "Hey, if you're doing this quest just for the fancy shield? Don't. I found out the hard way that in the building by where this quest ends there's an armorer that sells one with 161 armor 3 block. That's more than a little improvement over 55 armor (if you have the cash).\n\nDull Heater Shield (http://www.wowhead.com/?item=1201) sells for 4s 73c in Goldshire.\n\nIf, however, you still intend to do this quest for the shield.. you can skip most of the quests in the starter area. It doesn't list this quest as part of a chain of quests but it is. You need to do all the quests Marshal McBride gives (from inside the abbey), all the kobald quests and possibly a class specific quest.",
            date = "2009-03-25T11:23:37-05:00",
            sourceUrl = "https://www.wowhead.com/quest=54#comments:id=655091",
        },
        {
            id = 671047,
            score = 5,
            author = "Onarenth",
            text = "Does anyone find it almost ironic that in the report Marshal McBride talks about a \"Criminal at large\" named Garrick Padfoot, even though you killed him already?",
            date = "2009-04-09T15:42:08-05:00",
            sourceUrl = "https://www.wowhead.com/quest=54#comments:id=671047",
        },
        {
            id = 2239995,
            score = 1,
            author = "1384687",
            text = "I once took this quest and travelled to Northshire... then entered the Inn to set my HS there...\n...I ran... ran and ran and ran... ...now I live as a hermit in the mountains. Even now sometimes the horrors come back to haunt my nightmares...",
            date = "2015-08-27T14:54:17-05:00",
            sourceUrl = "https://www.wowhead.com/quest=54#comments:id=2239995",
        },
        {
            id = 223658,
            score = -2,
            author = "Awesomeman",
            text = "Simply travel by road to Goldshire.\nIf you see any enemies lower than your current level kill them to get some xp.\n\nThere's also a crazy cat lady selling cats in her house.\nStop by to get a cat pet if you ever wanted one.",
            date = "2008-01-24T23:18:57-06:00",
            sourceUrl = "https://www.wowhead.com/quest=54#comments:id=223658",
        },
    },
