    [76] = {
        {
            id = 210631,
            score = 12,
            author = "LilithuZ",
            text = "Entrance is at 61,53 or north of Tower of Azora for those who doesn't have a coordinate addon, there's no other quest to do at the same location, however... there is a rare inside the cave, a spider called Mother Fang (http://www.wowhead.com/?npc=471)",
            date = "2007-12-31T18:44:19-06:00",
            sourceUrl = "https://www.wowhead.com/quest=76#comments:id=210631",
        },
        {
            id = 1845299,
            score = 9,
            author = "945326",
            text = "I've never quite understood the point of this quest....if it even has one.\n\nIt doesn't lead to any other quests (that you wouldn't be offered if you hadn't completed this one).\n\nIt doesn't advance the story line in any way.\n\nNobody ever does anything about the kobolds \"infesting\" this mine.\n\nI guess this was just so that if you were going for the Loremaster achievement/ title, this is one more quest in Elwynn Forest.\n\nAnd maybe if you skipped a bunch of other newbie quests, this is a chance to pick up some extra XP killing kobolds to catch you up.  Or something.\n\nOh, and also, if you do all the other Elwynn quests, dropping by the Jasperlode will get you your \"Explore Elwynn Forest\" achievement.  Which, by this point in time is kinda dumb because who even cares at this level?  Wait until you get your flying mount and then you can \"explore\" everything on the continent in about 15 minutes.\n\nProblem is that you'll get it practically as soon as you get to Goldshire and nobody in their right mind is going to go running down the road for this before they go do the Eastvale Logging Camp quests.  By the time you're high enough level to do Eastvale, stopping off at Jasperlode on the way back to Goldshire is almost a waste of time.\n\nConclusion:  a good \"time waster\" quests.",
            date = "2013-04-20T17:00:20-05:00",
            sourceUrl = "https://www.wowhead.com/quest=76#comments:id=1845299",
        },
        {
            id = 104906,
            score = 8,
            author = "Tirlimpams",
            text = "Leads to [10] Westbrook Garrison Needs Help!  ( http://www.wowhead.com/?quest=239 )",
