    [192] = {
        {
            id = 5264,
            score = 37,
            author = "1651",
            text = "These panthers can stealth, so they're a big pain to track down, especially so if you're sitting about the same level as them and your stealth detection kicks in at just about aggro range.\n\nThere's two main areas of them, but they're pretty spread out. Try East of the main road, just as you cross the second bridge heading south, around 47, 23. Another good place is along the main road just North of the Gurubashi Arena; just head off either side of the road and see if any pop up. From about 37, 44 to 40, 34.",
            date = "2006-11-30T22:32:26-06:00",
            sourceUrl = "https://www.wowhead.com/quest=192#comments:id=5264",
        },
        {
            id = 71622,
            score = 10,
            author = "16379",
            text = "These are really spread out, but generally stick close to the main roads.  They're stealthed, so you need to be almost on top of them to see them.  If you're not a hunter who can track beasts, then just set a macro to /target Shadowmaw and spam the hell out of it as you walk a few feet off the side of the road.\n\nAs far as I've explored, I've never found a cluster of them exclusively, so be patient and prepare for a lot of walking.",
            date = "2007-04-23T13:01:30-05:00",
            sourceUrl = "https://www.wowhead.com/quest=192#comments:id=71622",
        },
        {
            id = 71783,
            score = 10,
            author = "45812",
            text = "I found these panthers in the same place as the Jungle Stalker Raptors of this q:\nhttp://www.wowhead.com/?quest=196\n\nCoords: 32, 37\n\nJust near and around the coast.\n\nI posted a screenshot of the area too. The pic just needs to be approved to show up.",
            date = "2007-04-23T18:17:20-05:00",
            sourceUrl = "https://www.wowhead.com/quest=192#comments:id=71783",
        },
        {
            id = 1194903,
            score = 7,
            author = "64801",
            text = "For Cataclysm you will want to hunt the ones that stretch between the Mosh' ogg Ogre mound area North to the steps of Zul' Gurub. The numbers and concentrations are much higher. When you are done Bag' thera is right there to complete the next quest.",
            date = "2010-11-29T03:32:00-06:00",
            sourceUrl = "https://www.wowhead.com/quest=192#comments:id=1194903",
        },
        {
            id = 74539,
            score = 5,
            author = "gwiz665",
            text = "I've found most in the area between (45,25) and (46,28). Where I also found Bag'thera. If you only see lots of Tigresses, then kill them. They take up spots where Panthers can be, and it seems that they switch between spawning.",
            date = "2007-04-28T18:12:49-05:00",
            sourceUrl = "https://www.wowhead.com/quest=192#comments:id=74539",
        },
    },
