        {
            id = 1933966,
            score = 21,
            author = "Farzeer",
            text = "Quests you have to complete to get this one;\n\nhttps://www.wowhead.com/quest=583\n\nThat one starts the chain;\n\nhttps://www.wowhead.com/quest=194\nhttps://www.wowhead.com/quest=195\nhttps://www.wowhead.com/quest=196\nhttps://www.wowhead.com/quest=197\n\nAfter you finish Raptor Mastery, you get two new quest chains;\n\nhttps://www.wowhead.com/quest=190\nhttps://www.wowhead.com/quest=191\nhttps://www.wowhead.com/quest=192\nhttps://www.wowhead.com/quest=193\n\nand\n\nhttps://www.wowhead.com/quest=185\nhttps://www.wowhead.com/quest=186\nhttps://www.wowhead.com/quest=187\nhttps://www.wowhead.com/quest=188\n\nAfter you have completed ALL of the above quests, you'll unlock this one. Good luck and have fun killing tons of mobs :)",
            date = "2014-01-12T15:34:45-06:00",
            sourceUrl = "https://www.wowhead.com/quest=208#comments:id=1933966",
        },
