    [314] = {
        {
            id = 211229,
            score = 22,
            author = "99303",
            text = "Vagash no longer does that frost breath attack. He now does a Frost Nova type of spell. Also, you don't need to go up the path to get to him. From the left side of the porch, facing the house, look slightly to your left. You'll see a small incline going up the hill. There is a tree there. Run up that part of the hill, behind the tree. Once you're past it, turn around and run up another incline and you'll be right at the cliffs edge where Vagash's cave is. This saves time from having to run around the mountain.",
