    [333] = {
        {
            id = 781960,
            score = 17,
            author = "Aros",
            text = "This quest triggers a small event. It doesn't seem to lead to any more quests but it can be fun to watch. If you skip the event here's a short write-up of it:\n\nRema Schneider says: Corbett, you there? Harlan needs another load of knitted goods. Can you take it to him?\nCorbett Schneider says: Business must be good down at the bazaar. I'll get him resupplied right away!\n[Corbett starts walking.]\nCorbett Schneider says: I should have a few extra coins from this sale. Maybe I'll buy myself some lunch...\n[Corbett arrives at the Lionheart Armory.]\nCorbett Schneider says: Hey, Harlan. Here's a load of knitted cloth for you.\nHarlan Bagley says: Ahh, much appreciated, Corbett. We'll get these on the racks immediately.\nCorbett Schneider says: Glad to see you're doing so well, Harlan. And I hope to see you again soon.\n[Corbett leaves.]\nCorbett Schneider says: Now for that snack...\n[Corbett walks to Trias' Cheese.]\nCorbett Schneider says: Hullo, Trias clan! A ball of your smoked mozzarella, if you please!\nElaine Trias says: Good day, Corbett. Here's your cheese, fresh made this morning! And how are things at your shop?\nCorbett Schneider says: Yes ma'am, business is brisk!\nCorbett Schneider says: Thank you kindly!\n[Corbett leaves.]\nCorbett Schneider says: Time to get back to the shop...\n[Corbett walks back to the Canal Tailor and Fit Shop.]\nCorbett Schneider says: I'm back!\n[Corbett walks up the stairs and despawns.]",
            date = "2009-07-18T14:45:09-05:00",
            sourceUrl = "https://www.wowhead.com/quest=333#comments:id=781960",
        },
        {
            id = 865006,
            score = 3,
            author = "451821",
            text = "Coord for starting NPC are 62, 67 inside the Lionheart armory. Click on you map to search low level quests to help you. The turn in NPC's coords are correctly listed above.",
            date = "2009-10-12T11:38:57-05:00",
            sourceUrl = "https://www.wowhead.com/quest=333#comments:id=865006",
        },
        {
            id = 904357,
            score = 3,
            author = "Rislyn",
            text = "This quest DOES count for Loremaster of Eastern Kingdoms.\n\nSeriously simple quest, don't pass it up.",
            date = "2009-12-01T16:23:53-06:00",
            sourceUrl = "https://www.wowhead.com/quest=333#comments:id=904357",
        },
        {
            id = 823734,
            score = 2,
            author = "202055",
            text = "Confirm on the coords. For those using Jame's online tour guide, the coords that are listed is wrong. You'll find yourself searching around the Cathedral Square which is way north of where you really want to be. Tour guide lists the coords as (49.58, 55.64). I must say I was a bit shocked, this is the first time I've found Tour guide not on the exact spot (within a nat's you-know-what).",
            date = "2009-08-26T19:58:36-05:00",
            sourceUrl = "https://www.wowhead.com/quest=333#comments:id=823734",
        },
        {
            id = 1162171,
            score = 2,
            author = "686430",
            text = "You turn in the quest to Rema Schneider, which I believe to be a reference to either Tilman Riemanschneider, a great German sculptor, or Albert Riemanschneider, who catalogued and set figure bass to all 371 Chorales of J.S. Bach.",
            date = "2010-11-04T19:26:32-05:00",
            sourceUrl = "https://www.wowhead.com/quest=333#comments:id=1162171",
        },
    },
