    [351] = {
        {
            id = 1564165,
            score = 108,
            author = "sandyra",
            text = "For those trying to hunt down:\n\nhttps://www.wowhead.com/item=8704 from The Hinterlands (Personal stats: Killed some stalkers, some trolls, some owlbeasts (about 20 all told)... Then killed my first ooze at Skulk Rock, and it dropped)\nhttps://www.wowhead.com/item=8623 from Tanaris (Personal stats:  Went into Zul'Farrak like all other posters recommend, killed some twenty or thirty trolls and scarabs, and it dropped from one of the troll corpses)\nhttps://www.wowhead.com/item=8705 from Feralas  (Personal stats:  As recommended by many other posters, Feral Scar Yetis - dropped on my first kill)\n\nOnly available if you have not already completed the quest.\nYes these still drop in Mists of Pandaria.\nYes it can drop off ANY mob in the respective zone, however https://www.wowhead.com/item=8705 has the highest drop rate from https://www.wowhead.com/npc=5292 IF you haven't already done the quest.\nIt WILL eventually drop - some days RNG is your best friend, other days you want to repeatedly punch a kitten (or other obscenely fluffy creature) just to illustrate how cruel the universe can be.\nThe command to check if you have completed ANY of the distress beacon quests is here (special thanks to MrsSushi (http://www.wowhead.com/user=MrsSushi) for locating the updated version of this as of 5.0.3):\n\n/run local z={\"Tanaris\",\"Hinterlands\",\"Feralas\"}for k,v in pairs({{351,648},{485,836},{25475,25476}})do print(z[k])for i,q in pairs(v)do print(\" #\"..i,\"\\124Hquest:\"..q..\"\\124h[\"..q..\"]\\124h\" ,IsQuestFlaggedCompleted(q)and COMPLETE or INCOMPLETE)end end\n\nYou will see lines of dialogue that look like this:\nTanaris\n#1 [351] Complete\n#2 [648] Complete\nHinterlands\n#1 [485] Complete\n#2 [836] Complete\nFeralas\n#1 [25475] Incomplete\n#2 [25476] Incomplete\n\nAfter completing all three escorts, you can then acquire the quest https://www.wowhead.com/quest=3721 and get your https://www.wowhead.com/item=10398.\n\nHappy hunting!",
            date = "2011-11-06T00:07:01-05:00",
            sourceUrl = "https://www.wowhead.com/quest=351#comments:id=1564165",
        },
        {
            id = 44395,
            score = 87,
            author = "29076",
            text = "The location of the chicken is 60, 64.",
            date = "2007-03-01T06:23:03-06:00",
            sourceUrl = "https://www.wowhead.com/quest=351#comments:id=44395",
        },
        {
            id = 63937,
            score = 66,
            author = "11563",
            text = "I'm going to post this message on all three of these \"Find\" quests, just in case someone doesn't see it on one of the other two.\n\nIf you plan to do these quests in a group (which is very helpful, as any escort quest) everyone must first have completed the \"Find\" part of the quest, which means you have to find the chicken, choose \"Complete\" and then be *offered* the next part of the quest, which is the actual escort part. But do not accept this part until everyone has done the \"Find\" part, otherwise it won't be offered to them as escort quests normally are, because technically you are not on the same stage of the quest yet.\n\nSo just complete the \"Find\" part, then when the next part is offered, decline it until everyone is ready to accept it.",
            date = "2007-04-08T15:18:20-05:00",
            sourceUrl = "https://www.wowhead.com/quest=351#comments:id=63937",
        },
        {
            id = 2163,
            score = 44,
            author = "PhogHawk",
            text = "This leads to a rescue quest. The actual thing you need to find is the southermost \"dot\" on this map: http://www.wowhead.com/?npc=7784. Make sure you have another person if you're around the level that this quest is designed for, several adds are spawned at once in some cases and as a 46 mage I cannot take four scorpids with 2500 health each at once.",
            date = "2006-10-23T03:33:58-05:00",
            sourceUrl = "https://www.wowhead.com/quest=351#comments:id=2163",
        },
        {
            id = 1713549,
            score = 21,
            author = "Vlad",
            text = "If you got lost and not sure what you did, or have to do, use this macro to figure out where you currently stand:\n/run local z={\"Tanaris\",\"Hinterlands\",\"Feralas\"}for k,v in pairs({{351,648},{485,836},{25475,25476}})do print(z[k])for i,q in pairs(v)do print(\"  #\"..i,\"\\124Hquest:\"..q..\"\\124h[\"..q..\"]\\124h\",IsQuestFlaggedCompleted(q)and COMPLETE or INCOMPLETE)end end",
            date = "2012-09-14T11:16:32-05:00",
            sourceUrl = "https://www.wowhead.com/quest=351#comments:id=1713549",
        },
    },
    [353] = {
        {
            id = 106916,
            score = 27,
            author = "63649",
            text = "To get to Loch Modan from SW you have to take the deeprun tram in Dwarven District. That way you get to Ironforge. Then you go out of Ironforge. When you've gone down the hill from the city you turn left. You go over the bridge and then you make another left. That road you follow east all the way to the mountains, and there you can chose between two roads that both lead to Loch Modan.",
            date = "2007-06-19T06:35:13-05:00",
            sourceUrl = "https://www.wowhead.com/quest=353#comments:id=106916",
        },
        {
            id = 1198562,
            score = 17,
            author = "167214",
            text = "after you get this quest take the deep-run tram to iron forge and pick up [quest=26131 domain=www] for a flight to loch modon this should shave off a couple minutes on the run",
            date = "2010-11-30T18:29:36-06:00",
            sourceUrl = "https://www.wowhead.com/quest=353#comments:id=1198562",
