            text = "This quest, though exists since vanilla, is still available in Cataclysm.",
            date = "2011-07-07T20:20:49-05:00",
            sourceUrl = "https://www.wowhead.com/quest=384#comments:id=1463829",
        },
    },
    [412] = {
        {
            id = 2051598,
            score = 35,
            author = "1383112",
            text = "As of 6.0.3 only Frostmane Scavengers drop the quest item.",
            date = "2014-11-28T01:37:45-06:00",
            sourceUrl = "https://www.wowhead.com/quest=412#comments:id=2051598",
        },
        {
            id = 2282022,
            score = 27,
            author = "Chicken",
            text = "I must say that on the quest suckage scale, this one is right up there near the top. The quest area is very small, the mobs that drop the quest items are very specific and on a somewhat long respawn timer. If you're unlucky to be doing this quest on a realm that's even remotely active you'll be running back and forth A LOT.\n\nIt took me almost 30 minutes to do this... every class that had a distance closer or instant ranged attack pretty much sniped them right in front of me.\n\nStupid, stupid quest...",
            date = "2015-11-29T15:51:47-06:00",
            sourceUrl = "https://www.wowhead.com/quest=412#comments:id=2282022",
        },
        {
            id = 1188643,
            score = 7,
            author = "680335",
            text = "Changed again in 4.0.3a. Now drops off trolls in a field southeast of Kharanos.",
            date = "2010-11-26T19:22:46-06:00",
            sourceUrl = "https://www.wowhead.com/quest=412#comments:id=1188643",
        },
        {
            id = 275955,
            score = 5,
            author = "146147",
            text = "Every time i draft a new gnome or dwarf I do this quest and zomfg i must say without a doubt after several lvl 70s with full t6 gear it is by far the most annoying quest i have ever done in my life along side aswell any of the achindoun quests b/ the spirit healer is ALWAYS on the complete opposite end of the zone. Normally im not one to wish harm onto anyone but If by some fluke of luck the blizzard designer for these zone's sprite placement should befall a heart attack and fall to the ground in silent agony to be only a fraction of an inch out of reach of altering someone to his duress I'd probably lean in and say \"poetic justice is a beautiful thing\".",
            date = "2008-04-22T22:34:49-05:00",
            sourceUrl = "https://www.wowhead.com/quest=412#comments:id=275955",
        },
        {
            id = 2169864,
            score = 5,
            author = "1466622",
            text = "For those struggling to find these items:\n\nThey're NOT on the ground. You have to kill Frostmane Scavengers to get the gears.\n\nI've found that drops are more frequent if the Scavengers have had a second or two to reach down to one of the broken down machines (instead of just post-spawn), however I may be overinterpreting the facts.",
            date = "2015-04-21T09:01:52-05:00",
            sourceUrl = "https://www.wowhead.com/quest=412#comments:id=2169864",
        },
    },
    [432] = {
        {
            id = 281037,
            score = 3,
            author = "GoGoGodzilla",
            text = "This quest can be completed by killing any troggs in or around the quarry, as long as they are called \"Rockjaw Skullthumpers.\"  This area is packed with them, so completing this quest isn't terribly time consuming.\n\nBe aware that the troggs have a moderate respawn time, so be careful should you go into the cave - it's very likely that you will have to fight your way out, which can be frustrating if you run out of water or food.",
            date = "2008-05-02T10:07:50-05:00",
            sourceUrl = "https://www.wowhead.com/quest=432#comments:id=281037",
        },
        {
            id = 345164,
            score = 3,
            author = "165182",
            text = "and try to stay alive too, respawn point is all the way back at kharanos",
            date = "2008-08-05T12:04:17-05:00",
            sourceUrl = "https://www.wowhead.com/quest=432#comments:id=345164",
