            text = "If he's dead, he'll spawn at 39 / 70 every 5 minutes (just wait in front of Wailing Caverns entrance)  he'll come to you.  Otherwise he walks clockwise around the oasis w/two buddies.",
            date = "2015-08-02T12:30:43-05:00",
            sourceUrl = "https://www.wowhead.com/quest=852#comments:id=2224204",
        },
    },
    [855] = {
        {
            id = 1076360,
            score = 12,
            author = "447186",
            text = "As of Cataclysm these now drop off the Kolkar Marauders and Stormseers that occur around the Lushwater Oasis to the south of the quest giver. Easy kills and close to 100% drop rate.\n\n Lance\nBeta tester for;\nWrath of the Litch King\nCataclysm",
            date = "2010-07-08T22:11:57-05:00",
            sourceUrl = "https://www.wowhead.com/quest=855#comments:id=1076360",
        },
        {
            id = 239955,
            score = 4,
            author = "malfuries",
            text = "they have very low droprate...\nit took me at least +40 min",
            date = "2008-02-20T06:12:20-06:00",
            sourceUrl = "https://www.wowhead.com/quest=855#comments:id=239955",
        },
        {
            id = 254402,
            score = 4,
            author = "ranmoor",
            text = "Very low drop rate , I slayed about 40 before i got all 15 drops.. took about 45 mins in all ... Bad Slow Quest ...",
            date = "2008-03-16T16:57:51-05:00",
            sourceUrl = "https://www.wowhead.com/quest=855#comments:id=254402",
        },
        {
            id = 290192,
            score = 4,
            author = "133091",
            text = "Centaur bracers can drop from any of the centaurs that wander the three oases in the Barrens. Though the drop rate is a bit low, doing this quest alongside the other quests that Regthar Deathgate gives you makes it more bearable.\n\nThis quest pairs especially well with Verog the Dervish (http://www.wowhead.com/?quest=851); it requires you to kill centaurs in order to force them to summon Verog, and oftentimes you must kill quite a few of them before they finally do summon him. All of the centaurs you slay for this quest, of course, can drop the bracers.",
            date = "2008-05-18T03:08:49-05:00",
            sourceUrl = "https://www.wowhead.com/quest=855#comments:id=290192",
        },
        {
            id = 1192922,
            score = 4,
            author = "Konraddo",
            text = "Don't bother farming these bracers from centaurs on the world map. Simply wait till you do the quest Counterattack! (http://www.wowhead.com/quest=4021) as many centaurs are spawned for the event. If you fail to gather sufficient bracers, abandon your quest and start over.",
            date = "2010-11-28T09:25:01-06:00",
            sourceUrl = "https://www.wowhead.com/quest=855#comments:id=1192922",
        },
    },
    [858] = {
        {
            id = 811055,
            score = 85,
            author = "433116",
            text = "Without a doubt, one of these most annoying quests in the game. After fighting through all the way to get the key, then fighting all the way back down.....Blizzard decided to put an insane respawn on the quest giver after someone else does the quest...Simply a horrible design and implementation",
            date = "2009-08-14T03:54:52-05:00",
            sourceUrl = "https://www.wowhead.com/quest=858#comments:id=811055",
        },
        {
            id = 1763,
            score = 23,
            author = "1651",
            text = "Fairly straight forward. Go up the ramp of the big structure in the water. Be careful of roamers, there's 2-3 of them that go back and forth, so keep an eye out.\n\nThe key is on Supervisor Lugwizzle. He roams up and down the ramp and around a bit of the shore of the water. He even passes by Wizzlecrank, so if you're lucky, you can finish this quest fairly quickly.",
            date = "2006-10-11T12:43:46-05:00",
            sourceUrl = "https://www.wowhead.com/quest=858#comments:id=1763",
        },
        {
            id = 1219595,
            score = 22,
            author = "Rhynchelma",
            text = "Not obtainable as alliance now.",
            date = "2010-12-09T19:23:57-06:00",
            sourceUrl = "https://www.wowhead.com/quest=858#comments:id=1219595",
        },
        {
            id = 2555564,
            score = 12,
            author = "cass420",
            text = "Completed this quest on 03/01/2018. Can definitely attest to the fact that if someone gets there before you do, the respawn timer is about 7-8 minutes. I would recommend going to complete the quest where you kill 6 Heyenas, then grab yourself a drink and a snack and watch a quick youtube vid while you stand on the quest marker spot on the map so that you can be the first one up to complete the quest when he spawns again. Happy waiting!",
            date = "2018-03-01T04:39:44-06:00",
            sourceUrl = "https://www.wowhead.com/quest=858#comments:id=2555564",
        },
        {
            id = 20008,
            score = 9,
            author = "mulder",
            text = "Follow-up: http://www.wowhead.com/?quest=863",
            date = "2007-01-10T07:00:50-06:00",
            sourceUrl = "https://www.wowhead.com/quest=858#comments:id=20008",
        },
    },
    [863] = {
        {
            id = 1951157,
            score = 27,
            author = "plaguespree",
            text = "If you fail this quest for whatever reason, the only way to gain access to it again is to kill Supervisor Lugwizzle once more.\n\nIf you don't, you won't be able to interact with the shredder at all.",
            date = "2014-03-15T01:41:26-05:00",
            sourceUrl = "https://www.wowhead.com/quest=863#comments:id=1951157",
        },
        {
            id = 1764,
            score = 23,
            author = "1651",
            text = "Easy escort quest. Make it easier and quicker by clearing out the guys to the West of the shredder so he has to stop less.\n\nAfter you make it to the top of the ramp, you'll get attacked by two more Venture Company guys. They're no harder than the other ones you just fought, so they should go down quickly.\n\nThe quest gets turned in at Ratchet, so don't be alarmed when he disappears after you're done.",
            date = "2006-10-11T12:54:35-05:00",
            sourceUrl = "https://www.wowhead.com/quest=863#comments:id=1764",
        },
