    [871] = {
        {
            id = 51554,
            score = 23,
            author = "32233",
            text = "Loc: 55,26",
            date = "2007-03-15T10:21:29-05:00",
            sourceUrl = "https://www.wowhead.com/quest=871#comments:id=51554",
        },
        {
            id = 1074520,
            score = 7,
            author = "447186",
            text = "This quest has changed a bit with Cataclysm. Location of mobs required to complete this quest is at 67,49. You will see three large bonfires with the Hunters and Plunderers patrolling around them.\n\nLance\nBeta tester for;\nWrath of the Litch King\nCataclysm",
            date = "2010-07-06T13:03:09-05:00",
            sourceUrl = "https://www.wowhead.com/quest=871#comments:id=1074520",
        },
        {
            id = 80189,
            score = 6,
            author = "49938",
            text = "The Razormane Water Seekers, Razormane Thornweavers, and Razormane Hunters that are needed for this quest can be found at Thorn Hill just north-east of the Crossroads at 55,26.\n\nWaterseekers can cast Creeping Mould disease. Hunters come with a pet wolf add and Thornweavers are casters who can farie fire you.\n\nAlso at 55,27 there is a barrel which you can loot to pick up the quest item Chen's Empty Keg which starts a quest of the same name --> http://www.wowhead.com/?quest=819  (note: this item can be found at more than one place in the barrens and may not be here)",
            date = "2007-05-09T04:50:18-05:00",
            sourceUrl = "https://www.wowhead.com/quest=871#comments:id=80189",
        },
        {
            id = 332387,
            score = 5,
            author = "83931",
            text = "Make sure to be on guard so you don't get caught by a Razormane Hunter (http://www.wowhead.com/?npc=3265) while doing the quest. It's easy to be overwhelmed and die since they have a pet plus ranged attacks. They patrol the area and can come across your combat zone.",
            date = "2008-07-21T19:53:43-05:00",
            sourceUrl = "https://www.wowhead.com/quest=871#comments:id=332387",
        },
        {
            id = 71633,
            score = 4,
            author = "45737",
            text = "I thinks bestplay meant north east. there is a place just north east of crossroads called thorn hill. you cant miss it.\n\n-tdog.",
            date = "2007-04-23T13:22:03-05:00",
            sourceUrl = "https://www.wowhead.com/quest=871#comments:id=71633",
        },
    },
    [872] = {
        {
            id = 1074537,
            score = 50,
            author = "447186",
            text = "Completely changed in Cataclysm. All mobs for quest are now found in a new cave in Northern Barrens. Cave entrance is at 66,51. Just enter the cave, go down then up till you get to the underground lake. Turn left and follow the spiral path. Kreenig is at the top with one Defender and a couple of supply crates. Easy fight, in fact a lot easier than the old version.\n\nI suggest you make sure you get \"Supplies for the Crossroads (http://cata.wowhead.com/quest=5041)\" and complete that at the same time.\n\nLance\nBeta tester for;\nWrath of the Litch King\nCataclysm",
            date = "2010-07-06T13:18:32-05:00",
            sourceUrl = "https://www.wowhead.com/quest=872#comments:id=1074537",
        },
        {
            id = 12695,
            score = 24,
            author = "danyjr",
            text = "Kreenig can be found at: 58, 26. Pulling guards are easy and you can avoid getting aggro'd by Kreenig.",
            date = "2006-12-10T10:21:43-06:00",
            sourceUrl = "https://www.wowhead.com/quest=872#comments:id=12695",
        },
        {
            id = 854664,
            score = 9,
            author = "377639",
            text = "Solo'd as lvl 12 mage. Climbed the mountain between the two camps and droped down behind his patrol route. Only one guard to take out. Simple.",
            date = "2009-09-28T19:15:36-05:00",
            sourceUrl = "https://www.wowhead.com/quest=872#comments:id=854664",
        },
        {
            id = 1005430,
            score = 9,
            author = "Fondell",
            text = "To clarify: There are three camps. If you come from Crossroads, the camps are placed at these coordinates:\n\n1) 55,4 - 26,6\n\n2) 57,0 - 27,0\n\n3) 58,5 - 26,5\n\nKreenig (http://www.wowhead.com/?npc=3438) paces in a circle within the camp farthest to the east (camp number three in the list). His \"patrols\" are stationary so you can drop down from behind if you are lucky enough not to take too much falling damage. If you can't make the fall, there's another way to clear this quest:\n\nRun past camp number 1 and 2 (in the list) and position yourself by the tree at the foot of the ridge leading up to the top of the mountain at 58,5 - 25,5. From here it's just to kill the mobs while hugging the ridge wall (note that there's also a patrol with one Razormane Hunter and Razormane Wolf patrolling inside and adjacent to this area. Keep a look out for Defenders roaming this area too). Important Note: In case you are a Druid or other caster with limited survivability, do not attack Elder Mystic Razorsnout (have NOT tried this in Bear form). He is the guard standing directly in front of the stacked boxes that Kreenig (http://www.wowhead.com/?npc=3438) is patrolling! He is lethal and very hard to kill, especially if you're a cloth armor only caster!\n\nNow that we got that out of the way you should concentrate on the mobs in the middle/outer area of the camp and work your way toward the other side of the camp, yet still keeping the gap to Elder Mystic Razorsnout as big as possible. Kill off the mobs here and you'll be left with only Elder Mystic Razorsnout and Kreenig (http://www.wowhead.com/?npc=3438). Attack Kreenig (http://www.wowhead.com/?npc=3438) when he is as far from Elder Mystic Razorsnout as possible and you should be fine. I cleared this with my level 13 Resto Druid so it is doable.",
            date = "2010-03-26T00:51:42-05:00",
            sourceUrl = "https://www.wowhead.com/quest=872#comments:id=1005430",
        },
        {
            id = 1183905,
            score = 8,
            author = "Oliver90909",
            text = "I thought we already killed this guy before Deathwing went on his little vandalism spree. He's obviously been taking lessons from Zalazane! (http://www.wowwiki.com/Zalazane)",
            date = "2010-11-25T04:57:39-06:00",
            sourceUrl = "https://www.wowhead.com/quest=872#comments:id=1183905",
        },
    },
    [875] = {
        {
            id = 14888,
            score = 9,
            author = "TheOnyx",
            text = "The Witchwing Slayers (?npc=3278) do not drop the quest item 100% of the time, so a bit of grinding will be involved. To compound things, there will be stealthed harpies roaming the area, so watch out for unexpected adds.\n\nAlso, a random elite patrols the area, so if you are soloing, be certain you don't run into her.",
            date = "2006-12-13T14:26:32-06:00",
            sourceUrl = "https://www.wowhead.com/quest=875#comments:id=14888",
        },
        {
            id = 164067,
            score = 7,
            author = "Isherie",
            text = "40, 15 like the previous quest. :D\n\nAlso watch out for a rare elite lvl 19 harpy: Sister Rathtalon (?npc=5830). She paths around the area and packs quite a punch.",
            date = "2007-10-07T03:00:09-05:00",
            sourceUrl = "https://www.wowhead.com/quest=875#comments:id=164067",
        },
        {
            id = 207725,
            score = 3,
            author = "82099",
            text = "Just a warning, the slayers can Execute u when u are around 20% or so health and it usually hits for around 110.",
            date = "2007-12-26T16:40:50-06:00",
            sourceUrl = "https://www.wowhead.com/quest=875#comments:id=207725",
        },
        {
            id = 859242,
            score = 3,
            author = "datgrl",
            text = "This is the 1st of three harpy quests.  You can get to them all by climbing the Dry Hills and running along the plateau near the top.  Ridges lead down to the 3 areas where each quest takes place.   This allows you to fight with the mountains to your back and once you clear the area where you descended, the respawn rate is low and you don't have to worry about what's behind you.  The easiest path to climb is near Honor's Stand.  There are 2 towers, one near the road and one that is off the road, smoldering.  Just turn off the road and run toward the north at the base of the mountains a few more yards away.  The ridge to follow up is near this site.  There is nothing to clear up here except the occasional strider.  You will have to avoid raptors and cats at the base of the mountain.",
            date = "2009-10-04T15:59:53-05:00",
            sourceUrl = "https://www.wowhead.com/quest=875#comments:id=859242",
        },
        {
            id = 12664,
            score = 2,
            author = "9221",
            text = "This is quite an easy Quest just go there with a friend at lvl 15-19 and you should be fine.",
            date = "2006-12-10T08:16:04-06:00",
            sourceUrl = "https://www.wowhead.com/quest=875#comments:id=12664",
        },
    },
