    [877] = {
        {
            id = 5457,
            score = 28,
            author = "Bestplay3",
            text = "The fissure is at the bottom of the lake at coordinates 55.95, 80.56 (updated from comments for Cataclysm)",
            date = "2006-12-03T19:26:55-06:00",
            sourceUrl = "https://www.wowhead.com/quest=877#comments:id=5457",
        },
        {
            id = 124620,
            score = 10,
            author = "72210",
            text = "you gotta go underwater, then go to the bubbling fissure( the clamb like thingy )..thats where you gonna plant the seeds..=p",
            date = "2007-07-21T17:28:03-05:00",
            sourceUrl = "https://www.wowhead.com/quest=877#comments:id=124620",
        },
        {
            id = 1388154,
            score = 8,
            author = "HazardousPizza",
            text = "-VERY EASY WAY TO GET FOOD-\n\n1. Plant the seed in the bubbles thing (see above comments for more information on where it is located).\n\n2. Right click the bushes that appear around it (pointer will become a cogwheel when you mouseover it). You will receive https://www.wowhead.com/item=5066 for each bush collected.\n\n3. Go to the quests menu (Default keybind is \"L\") and click \"abandon\" button, its in the lower left corner (MAKE SURE YOU HAVE SELECTED THE RIGHT QUEST! Name has to be \"The Stagnant Oasis\").\n\nYou will keep the food.\n\n4. Go up the mountain to the guy you got the quest from (Jerrik Highmountain) and accept it again.\n\nRepeat the above steps until you have the desired amount of food.\n\nThis will save you some money, as this is completely free to do!\n\nYou can also sell the food to a merchant for some money, but it will not be a significant amount.\n\nHope this helps!",
            date = "2011-04-10T06:03:33-05:00",
            sourceUrl = "https://www.wowhead.com/quest=877#comments:id=1388154",
        },
        {
            id = 1221230,
            score = 4,
            author = "725535",
            text = "Plant the seed under the water where the bubbles are.",
            date = "2010-12-10T08:15:36-06:00",
            sourceUrl = "https://www.wowhead.com/quest=877#comments:id=1221230",
        },
        {
            id = 366796,
            score = 3,
            author = "65960",
            text = "The seeds will grow into some fern lookng plants, about six or eight of them. If you're looking for cheap food, you can pick the plants, and later eat them as a buffless (HP only) food. But they disappear fairly quickly, so you have to pick fast.\n\nLast time I did this quest, I planted my seeds, and got eight. Then someone else came by and planted his seeds and then swam off. I picked his six and had some extra food in the bag that lasted until Camp Taurajo.",
            date = "2008-09-01T12:52:07-05:00",
            sourceUrl = "https://www.wowhead.com/quest=877#comments:id=366796",
        },
    },
    [880] = {
        {
            id = 33102,
            score = 27,
            author = "17329",
            text = "The above post by Lailoken is correct. The Snapjaws are both at The Stagnant Oasis (55,42) or if you don't have coords Southeast of Crossroads and The Lushwater Oasis (46,38) Southwest of Crossroads. The Drop Rate is 100% Levels of the Oasis Snapjaws are 15-16. The also do a debuff called Sling Dirt that decresses your chance to hit by 40% for 10 Seconds.",
            date = "2007-02-09T09:52:17-06:00",
