            sourceUrl = "https://www.wowhead.com/quest=880#comments:id=4375",
        },
        {
            id = 368642,
            score = 3,
            author = "133862",
            text = "If you travel to Lushwater Oasis, be careful. There is a lvl 20 elite named Gesharahan. He swims in the middle of the water.",
