    [881] = {
        {
            id = 1918092,
            score = 76,
            author = "Tirrimas",
            text = "Since Garrosh decided to turn Echeyakee's former Lair into a meat processing plant, it seems the white lion has moved house to 47.8, 44.0. You're looking for a couple of large skeletons near the intersection of the road from Org and the North Gold Road leading to the Crossroads, just south of Dreadmist Camp. They're within sight of the guard tower there.\n\nClear any hostile huntresses, stand within those skeletons and use the horn. Echeyakee will leap at you.\n\nWhen you turn the quest in, the questgiver now gives a zone-wide shout congratulating you.",
            date = "2013-11-14T00:02:18-06:00",
            sourceUrl = "https://www.wowhead.com/quest=881#comments:id=1918092",
        },
        {
            id = 1181357,
            score = 47,
            author = "PocketFox",
            text = "After the Shattering, this quest has changed. Now you can \"slay OR subdue\" Echeyakee... meaning young hunters wanting their white lion pet will be able to kill two birds with one stone! I tested this myself while working on Loremaster on my 80, and yes, taming Echeyakee will give you credit for the quest. :)",
            date = "2010-11-24T11:46:15-06:00",
            sourceUrl = "https://www.wowhead.com/quest=881#comments:id=1181357",
        },
        {
            id = 84969,
            score = 44,
            author = "12927",
            text = "Be careful\nIf the Mob is already summoned by some else, dont use your horn or u will loose it, and u will have to re take the Q",
            date = "2007-05-18T04:52:13-05:00",
            sourceUrl = "https://www.wowhead.com/quest=881#comments:id=84969",
        },
        {
            id = 1933595,
            score = 44,
            author = "1210111",
            text = "Important to note you must do \"Hunting the Huntress\" https://www.wowhead.com/quest=903 and \"The Zhevra\" https://www.wowhead.com/quest=845 before you will see this quest - they are short and easy to do.\n\nand as of Jan 11, 2014, the correct coords are 47,44 NOT 44,47 as some others have posted.",
            date = "2014-01-11T07:07:40-06:00",
            sourceUrl = "https://www.wowhead.com/quest=881#comments:id=1933595",
        },
        {
