            author = "131000",
            text = "http://www.wowhead.com/?maps=17:559172\n\nFor people who dont have the coordinates add-on\n^_^\nHope it Helps",
            date = "2008-02-25T01:41:32-06:00",
            sourceUrl = "https://www.wowhead.com/quest=881#comments:id=242978",
