            score = 16,
            author = "17301",
            text = "Solod as a level 13 mage with only minor difficulty.  Might be hard as other classes until level 14 or 15.  He was located at 64, 47 near a tent.  Human wearing a red long-coat.",
            date = "2007-02-04T14:44:00-06:00",
