        },
        {
            id = 1075399,
            score = 11,
            author = "447186",
            text = "As you enter Frey Island from the western side and looking east there is a two story building to your left (north). Co-ords for the building are 77,89. There are 3 pirates as you enter and an additional one on the stair who will join the fight.\n\nCap'n Garvey is in the second room behind the small stairs and has two guards. The room is set up like a pirate lecture hall. Probably where they teach Pirating 101. Easy fight but you will have to come back here to grab the guns on the gun racks for another quest.\n\nLance\nBeta tester for;\nWrath of the Litch King\nCataclysm",
            date = "2010-07-07T14:57:28-05:00",
            sourceUrl = "https://www.wowhead.com/quest=895#comments:id=1075399",
        },
        {
            id = 768481,
