            author = "332173",
            text = "need to be at least neutral to turn in the quest, just an fyi for the people with low rep due to blood sail grind.",
            date = "2009-07-05T11:59:21-05:00",
            sourceUrl = "https://www.wowhead.com/quest=895#comments:id=768481",
        },
        {
            id = 997254,
