        },
    },
    [899] = {
        {
            id = 4400,
            score = 54,
            author = "TheOnyx",
            text = "The quest items have at least a 100% drop rate off of the appropriate mobs when you have this quest. Each mob will drop 1 or 2 of these at a time, so it's not as dauntign a task as it first seems.\n\nTo save some time, this quest can easily be done with \"Tribes At War\" (http://www.wowhead.com/?quest=878), as the mobs for that quest drop the quest items for this quest.",
            date = "2006-11-25T15:24:35-06:00",
            sourceUrl = "https://www.wowhead.com/quest=899#comments:id=4400",
        },
        {
            id = 1433799,
            score = 27,
            author = "57893",
            text = "Finding his wife seems to have calmed Mankrik down. This quest isn't nearly as ridiculous as it once was, but given how many quests you get to kill Quilboar it doesn't seem that implausible to collect 60 of them like you used to.",
            date = "2011-06-04T02:03:54-05:00",
            sourceUrl = "https://www.wowhead.com/quest=899#comments:id=1433799",
        },
        {
            id = 56892,
            score = 23,
            author = "thekid808",
            text = "around 44,54",
            date = "2007-03-25T09:58:20-05:00",
            sourceUrl = "https://www.wowhead.com/quest=899#comments:id=56892",
        },
        {
            id = 752611,
            score = 11,
            author = "Airman",
            text = "you can end up with one left in your bag... after you have completed the q you can throw it away",
            date = "2009-06-20T18:46:58-05:00",
            sourceUrl = "https://www.wowhead.com/quest=899#comments:id=752611",
        },
        {
            id = 1919791,
            score = 11,
            author = "1194084",
            text = "Pre-Cataclysm version of this quest as from http://www.wowwiki.com/Quest:Consumed_by_Hatred\nObjectives\nBring 60 https://www.wowhead.com/item=5085 to Mankrik at the Crossroads.\nDescription\nPerhaps you know the pain of uncertainty, perhaps not, . But know this: I stand here every day, from the sun's rising till its decline, scouring the horizon for more of those monsters. I've killed every pig man I've come across since, but my thirst for their blood is far from quenched. Perhaps instead of heading north to the Crossroads I should have headed to Taurajo. You, --you could help me. Kill them. Kill as many as you can. Bring me their tusks, and we will celebrate their deaths together.\nProgress\n\nThe quilboar will pay for this, . I swear it.\n\nCompletion\n, you take my task seriously, and for that I thank you. Although my desire for revenge remains, I can at least smile seeing that the quilboars have felt pain themselves.\n\nRewards\n\nChoose one from:https://www.wowhead.com/item=6477https://www.wowhead.com/item=5314\n1950 XP (or 12 silver at level 70)\n350 reputation with Orgrimmar",
            date = "2013-11-20T04:19:13-06:00",
            sourceUrl = "https://www.wowhead.com/quest=899#comments:id=1919791",
        },
    },
