    [931] = {
        {
            id = 2073171,
            score = 58,
            author = "Deadspear",
            text = "IMPORTANT:\nA bug prevents the spawn of Sprouted Frond (http://www.wowhead.com/object=7510). After picking up the quest, The Shimmering Frond, do NOT turn in the quest to Denalan (43.8, 44.2) at the Wellspring Hovel, but to the Denalan who is next to Lake Al'Ameth, as Denalan at the Wellsping Hovel wont spawn the Sprouted Frond (http://www.wowhead.com/object=7510) in the long plant stand after completing the quest and you will be unable to get the next quest. The Denalan (http://www.wowhead.com/npc=2080) (59.8, 59.6) that is to the east of Lake Al'Ameth (59.8, 59.6) he will spawn the Sprouted Frond (http://www.wowhead.com/object=7510) and you can pick up the next quest The Shimmering Frond (http://www.wowhead.com/quest=931). If like me you turned it in to Denalan at the Wellspring Hovel, just travel to the one near the lake and log out and go onto another character who hasnt done the quest yet and turn it in to Denalan at the lake and log out, the plants should spawn and give you enough time to re-log back to your previous character and do the quest.",
            date = "2014-12-20T16:44:43-06:00",
            sourceUrl = "https://www.wowhead.com/quest=931#comments:id=2073171",
        },
        {
            id = 465957,
            score = 37,
            author = "162363",
            text = "Did anyone notice this?\nI haven't seen a plant like this since a sojourn I made to the Swamp of Sorrows... decades ago!\nEvidence of Night Elves having influence in the Eastern Kingdoms years before the 3rd War.",
            date = "2008-11-23T21:18:00-06:00",
            sourceUrl = "https://www.wowhead.com/quest=931#comments:id=465957",
        },
        {
            id = 151156,
            score = 10,
            author = "82",
            text = "After \"picking\" the frond and bringing it to Denalan he will plant the specimen in his planter. Stick around for a second and you will be able to harvest the newly grown frond, giving you 5x Sprouted Frond ( http://www.wowhead.com/?item=5205 ), which can be used to heal yourself or someone else for a nice amount at that level.",
            date = "2007-09-10T04:34:49-05:00",
            sourceUrl = "https://www.wowhead.com/quest=931#comments:id=151156",
        },
        {
            id = 1258287,
            score = 6,
            author = "Moofle",
            text = "For who know what reason, I was able to pick up this quest as a horde undead when I was working on BB King. I wasn't able to turn it in, sadly, since Denalan is hostile, but still...",
            date = "2010-12-25T13:32:17-06:00",
            sourceUrl = "https://www.wowhead.com/quest=931#comments:id=1258287",
        },
        {
            id = 704845,
            score = 5,
            author = "154195",
            text = "Counts towards Loremaster of Kalimdor.",
            date = "2009-05-04T07:22:30-05:00",
            sourceUrl = "https://www.wowhead.com/quest=931#comments:id=704845",
        },
    },
    [932] = {
        {
            id = 13644,
            score = 49,
            author = "9167",
            text = "You can find the entrance to the cave with the coordinates 54, 52.  Melenas is a level 8 Satyr that is just inside up on a ledge.  There are many Grells inside the cave, so get a party if you are around level 6 and don't want a lot of hardship.",
            date = "2006-12-11T18:39:44-06:00",
            sourceUrl = "https://www.wowhead.com/quest=932#comments:id=13644",
        },
        {
            id = 526095,
            score = 9,
            author = "bobahop",
            text = "I also waited around for quite a while as grells respawned and Melenas didn't. And I left and came back and checked and still no Melenas. I did see him the very first time I went in... when he killed me! Someone else came in, killed him, and that was the last I saw of him.\n\nThe grells drop a lot of linen, so I was glad I had picked up First Aid before going in. Between killls I made bandages, which was a productive way to wait for mana. It's not a bad idea to kill the nearest grell and then the next nearest, loot the closest, kill the next nearest, loot the closest, etc. Otherwise you may be attacked while looting.\n\nTo find Melenas, keep to the right on going into the cave. The cave seems identical to the one in the Orc/Troll starting area. After crossing the water, he's the first ledge on the left. He'll probably be hidden and will emerge when you attack the grell. The second ledge on the left had a treasure chest, so you might do that one first.",
            date = "2008-12-23T05:24:39-06:00",
            sourceUrl = "https://www.wowhead.com/quest=932#comments:id=526095",
        },
        {
            id = 1910517,
            score = 8,
            author = "945326",
            text = "Just a reminder, after you've killed your 12 sprites and the Ironroot seeds have disappeared from your quest info on the right of your screen, they are still in your bags and will be until you turn the quest in.  So no need to ever actually fight the sprites.\n\nThere is also a named rare called Thregill in the cave with the sprites.  He looks just like any other sprite and your Ironwood seeds have no effect on him.  You're probably concentrating more on targeting your Ironwood seeds than targeting the sprites and he hits rather hard if you're doing this  quest at level, so it's quite possible that he'll have you down to 3/4 or 2/3 health by the time you realize he's different and actually start fighting him.",
            date = "2013-10-20T17:22:44-05:00",
            sourceUrl = "https://www.wowhead.com/quest=932#comments:id=1910517",
        },
        {
            id = 732419,
            score = 6,
            author = "77073",
            text = "Anyone know the full story behind this guy?  I know night elves and satyr and trolls have somewhat of a common history? But I'm curious how a satyr became a druid. Probably what the embarrassment is about (mentioned in the quest text).",
            date = "2009-05-30T18:27:40-05:00",
            sourceUrl = "https://www.wowhead.com/quest=932#comments:id=732419",
        },
        {
            id = 1040201,
            score = 5,
            author = "585980",
            text = "His respawn Rate sucks. I came down to kill him and someone all ready killed him before I got down to him",
            date = "2010-05-16T21:15:19-05:00",
            sourceUrl = "https://www.wowhead.com/quest=932#comments:id=1040201",
        },
    },
    [933] = {
        {
            id = 1203235,
            score = 10,
            author = "Polegara",
            text = "The moonwell is now at (43,58).\n\nAs you approach it, the Shade of the Kaldorei (http://www.wowhead.com/npc=34585) will spawn to finish his story.\n\nShade of the Kaldorei rests on the side of the moonwell in peaceful contemplation.\nShade of the Kaldorei says: In weeks past, all of those living atop Teldrassil have found their memories blurry, as if time itself seized a portion of their lives.\nShade of the Kaldorei says: We break from this haze to find that Fandral Staghelm and many of his closest followers have disappeared without a word.\nShade of the Kaldorei says: But in his place, Shan'do Stormrage awoke from the dream and returned to his beloved Tyrande Whisperwind.\nShade of the Kaldorei says: And with his return came Alexstrasza and Ysera, to at long last offer their blessings upon Teldrassil\nShade of the Kaldorei says: Though a small corruption lingers, desperately longing to be cleansed, the boughs of Teldrassil itself seem changed.  Growth has begun anew.\nShade of the Kaldorei says: None know what to expect next, but with Malfurion and Tyrande reunited, a new hope dawns on the Kaldorei.\nShade of the Kaldorei says: Hope for lasting relief from the shadow that has been cast on our people for so long.\nThe Shade of the Kaldorei closes its eyes and fades away.\n\nThere are five of these lore quests in total.\n\nTeldrassil: Crown of Azeroth (http://www.wowhead.com/quest=28729)\nTeldrassil: Passing Awareness (http://www.wowhead.com/quest=28731)\nTeldrassil: The Refusal of the Aspects (http://www.wowhead.com/quest=929)\nTeldrassil: The Burden of the Kaldorei (http://www.wowhead.com/quest=7383)\nTeldrassil: The Coming Dawn",
            date = "2010-12-03T00:43:04-06:00",
            sourceUrl = "https://www.wowhead.com/quest=933#comments:id=1203235",
        },
        {
            id = 1197550,
            score = 4,
            author = "714009",
            text = "The moonwell was moved to 43.90, 58.57 in Cataclysm",
            date = "2010-11-30T10:02:06-06:00",
            sourceUrl = "https://www.wowhead.com/quest=933#comments:id=1197550",
        },
        {
