        },
        {
            id = 1428451,
            score = 70,
            author = "drchango",
            text = "You can turn in this quest while in the phase event. Do not go to where the boats are usually as the npc is phased out. Instead go where the big broken goblin statue is located on the little island. The boat along with the npc will be inside the phased event.",
            date = "2011-05-27T02:10:00-05:00",
