    [1133] = {
        {
            id = 954119,
            score = 4,
            author = "Danyi",
            text = "I also could not see this quest, and was confused about it.\n\nHowever, I believe this quest was removed and replaced, by the following: Onward to Ashenvale (http://www.wowhead.com/?quest=10752), which was added in TBC.\n\nIt's basically the same thing, 'Hey, here's a new quest hub, go there and have fun!'\n\nYou can grab it at Thundris Windweaver (http://www.wowhead.com/?npc=3649) in Auberdine, northern building, 37,41 - 40,17.",
