    [1201] = {
        {
            id = 157599,
            score = 22,
            author = "Epoch1",
            text = "41.25 is a great location, I found 3 at once there.\n\nI also noticed, if you look around, youll see  campsites that consist of;\nA Barrel\nA Crate\nA Lantern\nAn Open box\n\nThese guys are all over these places, so keep an eye out and youll find em no problem",
            date = "2007-09-24T11:40:20-05:00",
            sourceUrl = "https://www.wowhead.com/quest=1201#comments:id=157599",
        },
        {
            id = 5438,
            score = 15,
            author = "4618",
            text = "The Theramore Infiltrators are stealthed, non-aggressive elves and can be found in the swamp surrounding Brackenwall. They're not difficult to kill but they can be hard to spot if you attempt this quest in the low to mid 30's. The hardest part is avoiding the wandering Mire Beasts, Snappers, Crocolisks and other assorted nasties.",
            date = "2006-12-03T12:36:46-06:00",
            sourceUrl = "https://www.wowhead.com/quest=1201#comments:id=5438",
        },
        {
            id = 148861,
            score = 12,
            author = "83684",
            text = "Make a macro /target Theramore Infiltrator, and spam it :)\nhope it helps you. (If its still hard to locate them, just inv some1 to your party. then mark the Theramore Infiltrator with an Icon, like skull or Triangle. then you will see the Theramore Infiltrator 100%!)\nBkob @ Ahn Qiraj",
            date = "2007-09-04T05:07:01-05:00",
            sourceUrl = "https://www.wowhead.com/quest=1201#comments:id=148861",
        },
        {
            id = 122691,
            score = 11,
            author = "71099",
            text = "I just did this quest today, and i find it very similiar to the horde quest in Ashenvale, where you hunt the \"Ashenvale Outrunners\".\n\nIt's not hard, the mobs spawn all around Brackenwall Village, but i hunted them mostly in the northern end. I usually don't play with sound on, but on this quest i turned it on in order to hear the stealth sound of the mobs.\n\nNOTE: The mobs are stealthed around at random positions, they're not in a camp or something like that, which humanoids tend to be. Very much like the ones in Ashenvale, i mentioned before.\n\nIf you're a class with beneficials towards stealthed mobs, use the abilities in order to detect these mobs.\n\nIt took me like 10 minutes to do the quest, and it gives some nice xp, so in my oppinion its definately worth doing.\n\nTips:\n- Turn on your sound in order to detect the stealthed spies. There's other mobs in the area that makes stealth sounds, the lurker-spiders. Avoid those.\n- Use whatever you got to detect the spies. For hunters it could be \"track hidden\", warlocks should use \"Detect invisibility\" etc. etc.\n- Avoid the other creatures as much as possible. They're annoying and you should be able to get your quest targets killed without too much hassle and without wasting to much time.\n\nHave fun doing the quest.",
            date = "2007-07-18T09:05:17-05:00",
            sourceUrl = "https://www.wowhead.com/quest=1201#comments:id=122691",
        },
        {
            id = 147816,
            score = 11,
            author = "84244",
            text = "Listening for the stealth sound that these spies make does help. However, the lurkers make the same sound.\n\nSound or not, they were failry easy to find.  Usually if I found one spy, there were two other spies fairly near.\n\nLooking closely you could see the spies stalking about ~ this helped with pickpocketing. I was able to snag a few boxes to practice on and some trash cash items to vend.\n\n38.21\n38.22\n38.23\n40.25\n40.33\n41.25\n41.26\n42.25\n42.31\n43.27\n43.30",
            date = "2007-09-01T19:07:25-05:00",
            sourceUrl = "https://www.wowhead.com/quest=1201#comments:id=147816",
        },
    },
    [1202] = {
        {
            id = 1715117,
            score = 109,
            author = "Langmans",
            text = "If you do the Theramore scenario, you will not be able to loot the quest item.\n\nEdit: You will have to talk to Zidormie (http://www.wowhead.com/npc=63546)(keepers of time) and select the option to go to old theramore. That way you can still loot it.",
            date = "2012-09-17T14:41:58-05:00",
            sourceUrl = "https://www.wowhead.com/quest=1202#comments:id=1715117",
        },
        {
            id = 1919097,
            score = 46,
            author = "Zurnagos",
            text = "Note: YOU MUST SPEAK TO Zidormi before you can see the chest!\nIf you didn't read the quest like me and spent 30min searching for it, this will hopefully save you some time..\n\nZidormi is standing infront of the bridge to Theramore.",
            date = "2013-11-17T11:26:04-06:00",
            sourceUrl = "https://www.wowhead.com/quest=1202#comments:id=1919097",
        },
        {
            id = 194470,
            score = 24,
            author = "88783",
            text = "I just did this quest and I think the shark was removed, now there is a bunch of non-agressive 34-35 Young Murk Threshers.",
            date = "2007-12-01T14:56:13-06:00",
            sourceUrl = "https://www.wowhead.com/quest=1202#comments:id=194470",
        },
        {
            id = 2539535,
            score = 18,
            author = "Wyr3d",
            text = "For those of you still leveling, most of the top voted comments are in reference to a scenario that can be played through at a higher level. So you can safely ignore those. Here's what you need to do:\n\nSave your Hearth at Brackenwall if you haven't already. Now, just ride east from Brackenwall, then drop off the coast into the sea. Swim down towards Theramore, keeping to the north, and east of the island. Judge yourself about equidistant between Theramore, and the lighthouse island, and you should be fine.\n\nOnce you get closer to your destination, dive down and collect the item from the chest. You should have no trouble, and aggro nothing. After looting, just hearth back to the village and save yourself the walk.",
            date = "2017-12-08T20:07:43-06:00",
            sourceUrl = "https://www.wowhead.com/quest=1202#comments:id=2539535",
        },
        {
            id = 78821,
            score = 15,
            author = "25728",
            text = "Chest/Documents spawned at 71,51 for me.",
            date = "2007-05-06T19:25:31-05:00",
            sourceUrl = "https://www.wowhead.com/quest=1202#comments:id=78821",
        },
    },
    [1204] = {
        {
            id = 5328,
            score = 18,
            author = "1651",
            text = "Head up and down the coast North of Theramore. The turtles are level 36-37, and the droprate is fairly low, so you'll be killing a lot of them.\n\nThey do drop the Thick Scaly Tails and Speckled Shell Fragments, though, so it's not all that bad of a grind. They're gray, but they sell for a decent amount to vendors.",
            date = "2006-12-01T17:58:04-06:00",
            sourceUrl = "https://www.wowhead.com/quest=1204#comments:id=5328",
        },
        {
            id = 950813,
            score = 10,
            author = "Federalagent",
            text = "Before you pick up this quest, Go see Angus Stern (http://www.wowhead.com/?npc=1141) in Stormwind City, for the quest called \"Morgan Stern\" (http://www.wowhead.com/?quest=1260).  It is a prequest to this one.",
            date = "2010-01-18T15:52:20-06:00",
            sourceUrl = "https://www.wowhead.com/quest=1204#comments:id=950813",
        },
        {
            id = 269634,
            score = 4,
            author = "silkfire",
            text = "The drop rate for me was very low, took 2 hours to complete. ~10% chance to drop.",
            date = "2008-04-10T11:15:16-05:00",
            sourceUrl = "https://www.wowhead.com/quest=1204#comments:id=269634",
        },
        {
            id = 1334693,
            score = 4,
            author = "ziggy29",
            text = "Put me into the \"lousy drop rate\" camp.  I probably had to kill 30 of them to get the 8 drops, and maybe a little more.",
            date = "2011-02-13T12:57:57-06:00",
            sourceUrl = "https://www.wowhead.com/quest=1204#comments:id=1334693",
        },
        {
            id = 188857,
            score = 3,
            author = "77852",
            text = "Patience is the key to this easy quest. You can find the Mudrock Spikeshell along the coast East of Theramore. They go almost all the way up to the Barrens! Defias Rummagers and murlocs will probably get in your way, but being a druid, (DRUID POWER!!!) I could easily prowl around them. They dropped a Forked Mudrock Tongue about every 5-7 kills. Extremely easy at level 44. . . (LOL) The turtles are normally 35-36. I saw one 37. Again, patience is the key.",
            date = "2007-11-21T11:47:30-06:00",
            sourceUrl = "https://www.wowhead.com/quest=1204#comments:id=188857",
        },
    },
    [1205] = {
        {
            id = 4035,
            score = 74,
            author = "Ormriss",
            text = "Look for a large white crocolisk roaming the rivers of the Quagmire or the Dragonmurk.  He has a pretty big patrol route, so you will likely be doing some running.  He's level 45, non-elite, so finding him is the hardest part of the quest.\n\nAnd if you forget where to turn this in, the guy is on Hunter Rise in Thunder Bluff.",
            date = "2006-11-22T23:42:44-06:00",
            sourceUrl = "https://www.wowhead.com/quest=1205#comments:id=4035",
        },
        {
            id = 33732,
            score = 41,
            author = "10251",
            text = "The stretch of river leading north/northeast from STONEMAUL RUINS on your map is where you need to be, he swims up and down that. He is a huge brute, a dull white crocodile that is unmistakable, just check the screen and you'll not miss him. Easily found with Track Beasts as a Hunter.\n\n47, 56 is where he met his end for me.",
            date = "2007-02-10T18:51:15-06:00",
            sourceUrl = "https://www.wowhead.com/quest=1205#comments:id=33732",
        },
        {
            id = 887680,
            score = 23,
            author = "484195",
            text = "No one has mentioned it yet, but the quest text is superb.",
            date = "2009-11-10T16:08:16-06:00",
            sourceUrl = "https://www.wowhead.com/quest=1205#comments:id=887680",
        },
        {
            id = 187530,
            score = 12,
            author = "101180",
            text = "Deadmire is level 41 now after patch 2.3 even though the quest stays red.  He is a pushover.\n\nThe quest now gives 5550 exp.",
            date = "2007-11-19T08:37:26-06:00",
            sourceUrl = "https://www.wowhead.com/quest=1205#comments:id=187530",
        },
        {
            id = 1194451,
