            text = "This quest counts towards the achievement for Dustwallow Marsh Quests.\n\n[achievement=4978 domain=www]",
            date = "2010-11-28T21:24:22-06:00",
            sourceUrl = "https://www.wowhead.com/quest=1205#comments:id=1194451",
        },
    },
    [1222] = {
        {
            id = 185936,
            score = 29,
            author = "entropicdragon",
            text = "Leads to Feast at the Blue Recluse (http://www.wowhead.com/?quest=1271) from Angus Stern (http://www.wowhead.com/?npc=1141) in Stormwind -- he wasn't joking about the feast!",
            date = "2007-11-16T18:51:16-06:00",
            sourceUrl = "https://www.wowhead.com/quest=1222#comments:id=185936",
        },
        {
            id = 1791376,
            score = 7,
            author = "TakingMocha",
            text = "Trying to find Morgan Stern to hand in my completed quest, but due to whatever scenario/quest progress I've done, Theramore is in Ruins!  No NPC's at all.  Will this be a problem for \"Loremaster\"?\n\nEDIT:  oops.  Found the answer under \"Loremaster of Kalimdor / Dustwallow Marsh Quests\" - speak to Zidormi the time-phaser at bridge leading out of city :).",
            date = "2013-01-02T17:06:50-06:00",
            sourceUrl = "https://www.wowhead.com/quest=1222#comments:id=1791376",
        },
        {
            id = 1145955,
            score = 6,
            author = "Auben",
            text = "\"Thank you, .  I will ask my uncle to treat you to a feast the next time you visit the Blue Recluse in Stormwind. \"\n\nTrue to his word, after completing this quest you can visit Angus Stern and complete: [quest=1271 domain=www]",
            date = "2010-10-18T01:37:50-05:00",
            sourceUrl = "https://www.wowhead.com/quest=1222#comments:id=1145955",
        },
        {
            id = 238491,
            score = 5,
            author = "vexis58",
            text = "Tried to do this quest today. I had cleared all of the raptors nearby for another quest, and talked to Stinky, accepted his quest. He stood there for a minute without moving, then disappeared.\n\nI abandoned the quest, waited for him to reappear, accepted the quest again, and the same thing happened.\n\nWaited for him to respawn again without abandoning the quest, and he reappeared 3-4 minutes later, said something like \"Ah, there's one! Come, (someone who isn't me)! Let's go over there and collect it!\" and a minute after that, he despawned again.\n\nDefinitely not fixed yet.",
            date = "2008-02-18T05:10:55-06:00",
            sourceUrl = "https://www.wowhead.com/quest=1222#comments:id=238491",
        },
        {
            id = 5352742,
            score = 5,
            author = "Troo",
            text = "As I've been leveling alts in the last few weeks, I've been finding odd holes in the world in bodies of water. Stinky seems to find another one at one point and completely disappears for a bit. Just kinda hang out in the area he disappeared and wait for an animal to attack him and pull him back into being. I had to wait for a croc and a spider to do so before he rejoined us permanently. Rather annoying.",
            date = "2022-04-06T15:21:27-05:00",
            sourceUrl = "https://www.wowhead.com/quest=1222#comments:id=5352742",
        },
    },
    [1258] = {
        {
            id = 631511,
            score = 22,
            author = "284662",
            text = "This counts for Loremaster of Kalimdor",
            date = "2009-03-04T20:11:41-06:00",
            sourceUrl = "https://www.wowhead.com/quest=1258#comments:id=631511",
        },
        {
            id = 276263,
            score = 17,
            author = "144775",
            text = "Whether it's easy to accomplish this quest, which as I remember from the last time one of my characters did it, involves gathering of the quest items on the east coast of the area and your recommendation is to come in from the west side of the area, depends entirely on one's level and abilities when attempting to navigate to the appropriate area to perform the requisite activities.  If you are just finding out that you need to follow those directions to access the Swamp of Sorrows, you are probably unaware that Alliance players will almost immediately encounter Stoneard Scouts (http://www.wowhead.com/?npc=861) and Stonard Explorers (http://www.wowhead.com/?npc=862), marked PVP, patrolling the paths on the west side of the Swamp of Sorrows.  If you don't want to be flagged for PVP for fighting them, they need to be avoided.  And that's just the first of your worries for taking this path to the quest area.  The path soon branches into paths leading southeasterly and northeasterly.  The southeasterly path will take you smack dab into Stonard.  If you get too near it one or more level 65 Stonard Grunt (http://www.wowhead.com/?npc=866) (Bosses) will come out and attack and you'll be quickly dead.  Again if you attempt to fight them, you'll be flagged for PVP (and dead).  As soon as you spy it, detour to the northeast.  The northeastern path leads into Fallow Sanctuary. which you'll also want to avoid as you'll get mobbed on your way through.  So in either case you will be traveling off of the pathways and across country and likely agroing one battle after another with Swamp Jaguars (http://www.wowhead.com/?npc=767), and Sorrow Spinners (http://www.wowhead.com/?npc=858) in the jungle, and Sawtooth Crocolisks (http://www.wowhead.com/?npc=1082), Snappers (http://www.wowhead.com/?npc=1087), and Tangled Horrors (http://www.wowhead.com/?npc=766) in the waterways.  You may encounter the Pool of Tears in east central Swamp of Sorrows, which is generally quite safe to swim across the top, skirting the Temple of Atal' Hakkar in the center of the water.  Once you reach the Misty Reed Strand, which forms the northeastern coast of the Swamp of Sorrows,  be careful of the level 43 Monstrous Crawlers (http://www.wowhead.com/?npc=1088) if you decide to attack them, as they can be problematic for lower level characters on this quest.  So bottom line is if the quest is red or orange to you, tread very carefully when going this way.  If it's green or gray to you, then it should be relatively easy to get across the area (and you probably already have the map filled in for this area, having been there before...).",
            date = "2008-04-23T12:16:11-05:00",
            sourceUrl = "https://www.wowhead.com/quest=1258#comments:id=276263",
        },
        {
            id = 15438,
            score = 15,
            author = "kanaxya",
            text = "You have to kill \"silt crawlers\" http://www.wowhead.com/?npc=922\nor \"monsterous crawlers\" http://www.wowhead.com/?npc=1088\nlocated along the eastern coast of Swamp of Sorrows.\nI found the most around 95, 48  but they can be found anywhere along the water, they have a good drop rate.",
            date = "2006-12-14T09:14:33-06:00",
            sourceUrl = "https://www.wowhead.com/quest=1258#comments:id=15438",
        },
        {
            id = 14094,
            score = 12,
            author = "Tankme",
            text = "Go to Darkshire in Duskwood, take the road East out of town.\n\nThat leads to Deadwind Pass.\n\nEast across this zone leads to the Swamp of Sorrows.\n\neasy to have this done under 5 min!",
            date = "2006-12-12T12:10:54-06:00",
            sourceUrl = "https://www.wowhead.com/quest=1258#comments:id=14094",
        },
        {
            id = 62388,
            score = 7,
            author = "38883",
            text = "Nice, each Crawler I killed dropped 1 and some even dropped 2!",
            date = "2007-04-05T06:31:04-05:00",
            sourceUrl = "https://www.wowhead.com/quest=1258#comments:id=62388",
        },
    },
    [1270] = {
        {
            id = 26083,
            score = 21,
            author = "13910",
            text = "You can find Stinky at 45,17. He wanders around the swamp a bit until he finds the Bogbean Leaves. There aren't any ambushes, but there will be some mobs in the area unless you've already killed them. He gets onto a road at 49,25 and the quest is completed.\nThen head over to 62,37 in The Barrens to turn-in.",
            date = "2007-01-28T00:50:18-06:00",
            sourceUrl = "https://www.wowhead.com/quest=1270#comments:id=26083",
        },
        {
            id = 1850771,
            score = 9,
            author = "error10",
            text = "This is the Horde version of the quest. The Alliance version is https://www.wowhead.com/quest=1222.\n\nOnly the Horde version grants reputation with Ratchet and the other goblin towns.",
            date = "2013-05-07T00:48:10-05:00",
            sourceUrl = "https://www.wowhead.com/quest=1270#comments:id=1850771",
        },
        {
            id = 214033,
            score = 7,
            author = "jaxsonbateman",
            text = "From what I can tell, if someone failed the quest after the Bogbean Plant spawns, but before he interracts with it (and thus despawns it), the plant remains perma-spawned, and bugs the quest out for everyone else who tries to start it. After talking to Stinky to start the quest he disappears, only to reappear on the main road nearby the Bogbean Plant, and run off as though you had completed the quest.\n\nI have just petitioned a GM, and am awaiting their response - but I believe to fix the problem they need to despawn the Bogbean Plant.",
            date = "2008-01-06T22:18:36-06:00",
            sourceUrl = "https://www.wowhead.com/quest=1270#comments:id=214033",
        },
        {
            id = 313902,
            score = 5,
            author = "62608",
            text = "Just to be clear. This quest is to be completed in Ratchet!",
            date = "2008-06-26T13:44:51-05:00",
            sourceUrl = "https://www.wowhead.com/quest=1270#comments:id=313902",
        },
        {
            id = 819299,
            score = 4,
            author = "Neutralagent",
            text = "Counts for loremaster of Kalimdor",
            date = "2009-08-22T04:38:06-05:00",
            sourceUrl = "https://www.wowhead.com/quest=1270#comments:id=819299",
        },
    },
    [1271] = {
        {
            id = 323978,
            score = 43,
            author = "hypehuman",
            text = "If you won the Nobel prize and someone threw you a reception after the event, would you yell at all the people who ate and drank in your honor?  Would you quickly gobble it all up before anyone could \"ninja\" it?\n\nI know this is a game and you can sell it for cash, but it just sounds funny if you put it in a RL context :)\n\nEDIT:  This post was in response to people complaining that other people were taking their food.  Those posts are now gone.",
            date = "2008-07-10T17:04:34-05:00",
            sourceUrl = "https://www.wowhead.com/quest=1271#comments:id=323978",
        },
        {
            id = 75641,
            score = 39,
            author = "43758",
            text = "After speaking to and completing the quest with Angus Stern (41,89) don't forget to loot all the food and drinks off the tables they have put out in your honor.",
            date = "2007-04-30T17:01:13-05:00",
