    [1453] = {
        {
            id = 1338799,
            score = 11,
            author = "724683",
            text = "Just completed this quest and was not offered the followup:  [quest=1454 domain=www]",
            date = "2011-02-16T16:46:31-06:00",
            sourceUrl = "https://www.wowhead.com/quest=1453#comments:id=1338799",
        },
        {
            id = 52916,
            score = 3,
            author = "34440",
            text = "entrance found at 67, 15",
            date = "2007-03-17T22:48:52-05:00",
            sourceUrl = "https://www.wowhead.com/quest=1453#comments:id=52916",
        },
        {
            id = 808213,
            score = 3,
            author = "Wark",
            text = "The Karnitol Shipwreck (http://www.wowhead.com/?quest=1454) and Reagents for Reclaimers Inc. (http://www.wowhead.com/?quest=1458) become available after turning this in.",
            date = "2009-08-11T19:12:30-05:00",
            sourceUrl = "https://www.wowhead.com/quest=1453#comments:id=808213",
        },
        {
            id = 1654213,
            score = 3,
            author = "Maldonai",
            text = "OK, I'm confused. I gathered that this quest was supposed to open several others. However I turned it in to Kreldig and there's not an exclamation point in sight now. I even tracked down Vahlarriel, thinking I might have to do Elune's Gifts (http://www.wowhead.com/quest=14354) in order to unlock the Karnitol quest, but he's got nothing for me.\n\nI should be of the appropriate level (Dwarf Shaman 30), and I exited and restarted the game just in case it was a bug. But still nothing. Is there some other quest that I need to unlock the Desolace quest chains?",
            date = "2012-04-15T06:07:50-05:00",
            sourceUrl = "https://www.wowhead.com/quest=1453#comments:id=1654213",
        },
        {
            id = 1665469,
            score = 3,
            author = "Satyrkarma",
            text = "It is important to note that this quest is not the beginning of a chain of quests but rather leads to a chain of quests.  Completing this quest will not provide a follow-up.  It will simply lead you to Desolace.  Once you complete Elune's Gifts https://www.wowhead.com/quest=14354, several more questgivers will become available including https://www.wowhead.com/quest=1454.\n\nIt should also be noted that if you are already in Desolace and completed Elune's Gifts and then picked up The Karnitol Shipwreck, you will no longer be able to acquire and complete this quest.  If you are an achievement hunter, make sure you pick this quest up in Ironforge before you travel to Desolace and do any quests there.",
            date = "2012-05-11T08:56:22-05:00",
            sourceUrl = "https://www.wowhead.com/quest=1453#comments:id=1665469",
        },
    },
    [1454] = {
        {
            id = 25937,
            score = 19,
            author = "mashby",
            text = "For those with add-ons such as Cosmos, Wowhead Looter and Titan Panel, the coordinates are 36, 30.",
            date = "2007-01-27T19:06:19-06:00",
            sourceUrl = "https://www.wowhead.com/quest=1454#comments:id=25937",
        },
        {
            id = 3072,
            score = 16,
            author = "token",
            text = "The chest is on the shore near some floating debris in the water.  There's also a journal lying beside it.  Pick that up for another part of the quest.   Also if you go up high on the mountainside where the ruins are there's an Argent Dawn guy there with another quest for you.",
            date = "2006-11-07T08:30:57-06:00",
            sourceUrl = "https://www.wowhead.com/quest=1454#comments:id=3072",
        },
        {
            id = 1342014,
            score = 16,
            author = "724683",
            text = "This chain will now not become available until you have completed [quest=14354 domain=www]",
            date = "2011-02-19T09:19:45-06:00",
            sourceUrl = "https://www.wowhead.com/quest=1454#comments:id=1342014",
        },
        {
            id = 1582014,
            score = 8,
            author = "621699",
            text = "Ok.\n\nAfter being misinformed and misdirected, i searched around.\nTo unlock this quest and have the darned question mark appear on top of the casket, follow this:\n\n1- Reach level 27.\n2- Visit Roetten Stonehammer (http://www.wowhead.com/npc=5637) in the Hall of Explorers in Ironforge, and obtain his quest Reclaimers' Buziness (http://www.wowhead.com/quest=1453). When you have it, head to Stonetalon Mountains.\n3- Obtain the quest Help for Desolace (http://www.wowhead.com/quest=25938) from Hyerophant Malyk (http://www.wowhead.com/npc=41487) in Farwatcher's Glen located in Stonetalon Mountains.\n4- Reach Officer Jankie (http://www.wowhead.com/npc=36410) in Desolace (check your ingame map!) and obtain the quest Rerouted! (http://www.wowhead.com/quest=14384) before jumping on her gryphon. When you hit Nijel's Point, search for Corporal Melkins (http://www.wowhead.com/npc=5752).\n5- Obtain the quest Lay of the Land (http://www.wowhead.com/quest=14387) from Captain Pentigast (http://www.wowhead.com/npc=5396) right next to him.\n6- Obtain the quest Elune's Gifts (http://www.wowhead.com/quest=14354) from Vahlarriel Demonslayer (http://www.wowhead.com/npc=5642) standing nearby.\n7- Visit all three relics, come back and turn in the quest.\n8- And finally, search for Kreldig Ungor (http://www.wowhead.com/npc=5638) to obtain the quest The Karnitol Shipwreck (http://www.wowhead.com/quest=1454).\n\nSo, special thanks to snelton\nThis chain will now not become available until you have completed Elune's Gifts (http://www.wowhead.com/quest=14354)\netherfrog\nYou need to get this quest to trigger the rest :\nhttp://www.wowhead.com/?quest=1453\n\nYou can start the chain from this guys in Iron Forge :\nhttp://www.wowhead.com/?npc=5637\nand Tzarynn\nIn order, the quest line for this is:\n\n1. Help for Desolace (http://www.wowhead.com/quest=25938)\n-------------or----------------\n1a. Hero's Call: Desolace! (http://www.wowhead.com/quest=28531)\n\nThen continues with:\n\n2. Rerouted! (http://www.wowhead.com/quest=14384)\n\nFrom here you should be able to seamlessly make your way through Desolace.\n\nGood luck and Happy Questing :-)\nfor their useful informations.",
            date = "2011-11-27T16:49:58-06:00",
            sourceUrl = "https://www.wowhead.com/quest=1454#comments:id=1582014",
        },
        {
            id = 1571191,
            score = 4,
            author = "909946",
            text = "The quest item is available from killing nagas around Ranazjar Island...thanks for thr outdated info, but this is now confirmed !",
            date = "2011-11-13T11:58:14-06:00",
            sourceUrl = "https://www.wowhead.com/quest=1454#comments:id=1571191",
        },
    },
