    [2399] = {
        {
            id = 2073166,
            score = 95,
            author = "Deadspear",
            text = "IMPORTANT:\nA bug prevents the spawn of Sprouted Frond (http://www.wowhead.com/object=7510). After picking up the quest, The Shimmering Frond, do NOT turn in the quest to Denalan (43.8, 44.2) at the Wellspring Hovel, but to the Denalan who is next to Lake Al'Ameth, as Denalan at the Wellsping Hovel wont spawn the Sprouted Frond (http://www.wowhead.com/object=7510) in the long plant stand after completing the quest and you will be unable to get the next quest. The Denalan (http://www.wowhead.com/npc=2080) (59.8, 59.6) that is to the east of Lake Al'Ameth (59.8, 59.6) he will spawn the Sprouted Frond (http://www.wowhead.com/object=7510) and you can pick up the next quest The Shimmering Frond (http://www.wowhead.com/quest=931). If like me you turned it in to Denalan at the Wellspring Hovel, just travel to the one near the lake and log out and go onto another character who hasnt done the quest yet and turn it in to Denalan at the lake and log out, the plants should spawn and give you enough time to re-log back to your previous character and do the quest.",
            date = "2014-12-20T16:39:09-06:00",
            sourceUrl = "https://www.wowhead.com/quest=2399#comments:id=2073166",
        },
        {
            id = 3170873,
            score = 49,
            author = "skulxen",
            text = "This quest is still bugged almost 10 years later. Come on, Blizzard. You really messed up with Cataclysm.",
            date = "2019-11-10T20:03:21-06:00",
            sourceUrl = "https://www.wowhead.com/quest=2399#comments:id=3170873",
        },
        {
            id = 2273826,
            score = 16,
            author = "SoloEverything",
            text = "Bugged still. Denalan just sits there at the lake staring at Greenspyre.",
            date = "2015-11-10T04:59:08-06:00",
            sourceUrl = "https://www.wowhead.com/quest=2399#comments:id=2273826",
        },
        {
            id = 178986,
            score = 13,
            author = "31085",
            text = "This quest is one that starts in Denalan's planter after you've completed The Shimmering Frond (http://www.wowhead.com/?quest=931), by activating one of the Shimmering Fronds that appears.",
            date = "2007-11-04T10:15:40-06:00",
            sourceUrl = "https://www.wowhead.com/quest=2399#comments:id=178986",
        },
        {
            id = 885997,
            score = 13,
            author = "flawlessa",
            text = "The quest requires fast action.\n\nAfter handing in Shimmering Frond and Denalan goes to plant, hover the mouse over the planter and you should be able to pick up this quest.   If not, it despawns in a bit and you will be unable to grab it.  You also won't be able to go back to the shimmering frond tree to grab the prereq item again.   Lastly, should any other player hand in a quest requiring the planter, that's another possibility for the despawn.\n\nTo make matters worse, this quest is an 'Accept and Complete' in one step.  Because of this, the quest completion may not be noted by an addon like QuestHistory or EveryQuest.   You should get 5 Sprouted Fronds in your bags, and that's your cue that it's done.\n\nI had a long conversation with a GM about this, after being unsure my character received it.    This was with game version 3.2.2.",
            date = "2009-11-08T15:10:03-06:00",
            sourceUrl = "https://www.wowhead.com/quest=2399#comments:id=885997",
        },
    },
