    [2499] = {
        {
            id = 2349107,
            score = 29,
            author = "Stabbingjoo",
            text = "As of WoD i am trying to get the belt for my Transmog set. When I first went to Denalan there were no quests available.I went back to town and starting doing the main quest-line (only the quests starting in the city of Dolanaar). This eventually led me to talk to Denalan. That's how its done folks.\n\nQuests i did in order:\nhttps://www.wowhead.com/quest=475\nhttps://www.wowhead.com/quest=2438\nhttps://www.wowhead.com/quest=476\nhttps://www.wowhead.com/quest=483\nhttps://www.wowhead.com/quest=13945\nhttps://www.wowhead.com/quest=2459\nhttps://www.wowhead.com/quest=486\nhttps://www.wowhead.com/quest=997\nhttps://www.wowhead.com/quest=919\nhttps://www.wowhead.com/quest=918\nhttps://www.wowhead.com/quest=923\nThen you get https://www.wowhead.com/quest=2499.\n\nGood luck hope this helped",
            date = "2016-07-07T18:12:49-05:00",
