    [2518] = {
        {
            id = 2586468,
            score = 93,
            author = "BorkyB",
            text = "If you picked up this quest in Darnassus during 8.0 when you were trying to finish the rescue mission during the burning of Teldrassil, and realized you could not leave the city - turn off your low level quests.  This is a low leveling quest that just happened to be active during the evacuation.  Feel free to pick it up and complete it once Zordami is able to reverse time.\n\nIt has no effect on the burning of Teldrassil questline.",
            date = "2018-07-31T12:42:13-05:00",
            sourceUrl = "https://www.wowhead.com/quest=2518#comments:id=2586468",
        },
        {
            id = 13419,
            score = 42,
            author = "9167",
            text = "Lady Sathrah is a level 12 large grey spider that can be found at multiple coordinates.  A few to try are 39, 25 and 48, 25.  Search the general area east or west of the river at the top of the map of Teldrassil and you should find her.\n\nIf you are level 10 or 11, you can kill her by waiting until she is off by herself because she spawns minions. If you are level 12 or higher, killing her and the minions should be no problem.",
            date = "2006-12-11T11:23:41-06:00",
            sourceUrl = "https://www.wowhead.com/quest=2518#comments:id=13419",
        },
        {
            id = 253793,
            score = 14,
            author = "111195",
            text = "If you have QuestHelper, it will probably tell you to go around 39, 26. But after looking here on Wowhead, I found out Lady Sathrah can actually go past the lake, to around 48, 25. Believe it or not, that's where I finally found her.\n\nHere is the general range of where Lady Sathrah will be: Map (http://www.wowhead.com/?maps=141:409262395262424262457260470262)\n\nEdit: After patch Patch 2.4, QuestHelper is now fixed and tells you Lady Sathrah can be on either side of the river.",
            date = "2008-03-15T12:54:33-05:00",
            sourceUrl = "https://www.wowhead.com/quest=2518#comments:id=253793",
        },
        {
            id = 119707,
            score = 11,
            author = "matty",
            text = "There's a Horde quest with nearly the same name \"The Tear of the Moons\" given by Feegly the Exiled\n\nhttp://www.wowhead.com/?quest=857",
            date = "2007-07-12T21:35:30-05:00",
            sourceUrl = "https://www.wowhead.com/quest=2518#comments:id=119707",
        },
        {
            id = 1450737,
            score = 10,
            author = "452400",
            text = "Before Cataclysm this quest was the second in a chain of three. The first was a breadcrumb quest, the third and last one was called \"Sathrah's Sacrifice\", in which you had to travel to the Temple of the Moon in Darnassus and sacrifice the Silvery Spinnerets from this quest before the statue of Elune. The (friendly) Spirit of Sathrah would appear, walk a lap around the statue and then despawn. Now that the quest is gone, the Spirit of Sathrah appears directly when you turn in this quest, along with a message in your chatlog stating \"Spirit of Sathrah is once again at peace\". This time, too, the Spirit of Sathrah will walk around for a few seconds and then despawn.",
            date = "2011-06-26T00:47:53-05:00",
            sourceUrl = "https://www.wowhead.com/quest=2518#comments:id=1450737",
        },
    },
    [2523] = {
        {
            id = 434978,
            score = 37,
            author = "28451",
            text = "The Cenarion Plant Salve quests do not add up for the Loremaster of Kalimdor achievement.\n\nNot even on the first turn-in.",
            date = "2008-11-08T04:45:11-06:00",
            sourceUrl = "https://www.wowhead.com/quest=2523#comments:id=434978",
        },
        {
            id = 284656,
            score = 6,
            author = "mrdummy",
            text = "One strange warning. If you have full bags, and you want do the plant quest, you got strange error that you need some room in the bags, when you loot the cleansed plant.\n\nIt happens me with full bags. It goes normally for a buff, but because the looting, it use for short time one bag room and then immediately it buffs you.\n\nWith full bags, you lose the loot, and you cannot loot plant again. The loot indicator is gone.\nBut the plant is not gone! It's still there.\nI think it's a bug, because you can loot always again even with full bags. Only here with plants it goes really wrong.\n\nWhy it use one bag room, it's still unfair and unlogic. Because it gives always the buff.\n\nSecond warning: don't loot next plant if you have already same buff. Dismiss the buff first, so you can get a new one from the plant.\nBecause you cannot loot again (same problem with full bags) the plant.",
            date = "2008-05-08T15:11:49-05:00",
            sourceUrl = "https://www.wowhead.com/quest=2523#comments:id=284656",
        },
        {
            id = 269624,
            score = 5,
            author = "144008",
            text = "After healing the plant, right click on it to receive a rather nice buff...  Song of Starflower  +70 Crit and +10 to all resistances for 1 hour.",
            date = "2008-04-10T10:47:39-05:00",
            sourceUrl = "https://www.wowhead.com/quest=2523#comments:id=269624",
        },
        {
            id = 284290,
            score = 5,
            author = "138745",
            text = "After cleansing, the flower gears up.  Picked it for \"Songflower serenade\" = Increases critical strike rating and spell critical strike rating by 70 and all attributes by 15.    Duration  60 minutes.",
            date = "2008-05-08T01:02:38-05:00",
            sourceUrl = "https://www.wowhead.com/quest=2523#comments:id=284290",
        },
        {
            id = 835637,
            score = 4,
            author = "Renesemee28",
            text = "i was wondering wher or how you come across the The Cenarion Plant Salve. i would like to do the quest but i dont know where to get the stuff.",
            date = "2009-09-08T19:39:18-05:00",
            sourceUrl = "https://www.wowhead.com/quest=2523#comments:id=835637",
        },
    },
    [2541] = {
        {
            id = 68120,
            score = 47,
            author = "Flitzy",
            text = "Easy enough quest (was able to solo as a level 9 druid), but the drop rate is awful so expect to be down here for a while - you should kill enough to level, at least. Careful, however, some pulls will net you two or three mobs.",
            date = "2007-04-16T12:29:47-05:00",
            sourceUrl = "https://www.wowhead.com/quest=2541#comments:id=68120",
        },
        {
            id = 334276,
            score = 34,
            author = "Travy",
            text = "You walk into this cave a boy, and you come out a man. I am sure some people do get the charm quickly, but I was one of the unfortunate few to get a few levels grinded out of it. Not that I mind terribly slow, just you are in for a long trip T_T",
            date = "2008-07-23T19:50:00-05:00",
            sourceUrl = "https://www.wowhead.com/quest=2541#comments:id=334276",
        },
        {
            id = 1807457,
            score = 19,
            author = "capnbiff",
            text = "Yes, it's a horribly low drop rate.  Yes, you'll gain 1-2 levels grinding this out.  But, this quest and the followup are worth about 2000XP at level 9-10.  The really big problem is, once you've found the charm, how do you get back to Oben Rageclaw to turn in the blasted quest?  If you follow the map to the northern bridge where the yellow question mark says he should be...he's not there.\n\nRemember that this is a two-level cave complex.  From that northern bridge with the misleading question mark, go up the entrance tunnel and you'll be back at the upper level.  The side-by-side bridges are right there.  Oben is on the right, his spirit (which you have to kill for the followon quest) is on the left.  For a better picture, hit your M key to bring up the map, then scroll between the two levels to orient yourself.",
            date = "2013-01-31T23:11:11-06:00",
            sourceUrl = "https://www.wowhead.com/quest=2541#comments:id=1807457",
        },
        {
            id = 178091,
            score = 18,
            author = "peeweesweden",
            text = "Walked in as lvl 9, got out as lvl 12. Terrible droprate indeed. If there are more people in here, make sure that you at least try to team up with them, or you could very well end up in here forever.",
            date = "2007-11-02T11:06:51-05:00",
            sourceUrl = "https://www.wowhead.com/quest=2541#comments:id=178091",
        },
        {
            id = 947933,
            score = 16,
            author = "lra01",
            text = "I could not find the charm in the cave.  After exiting the cave I checked the map (map with quests in Patch 3.3) and it sent me to an area east of the cave and mountains surrounding it.  Found the charm on the first shaman I killed.",
            date = "2010-01-15T06:57:41-06:00",
            sourceUrl = "https://www.wowhead.com/quest=2541#comments:id=947933",
        },
    },
    [2561] = {
