        },
        {
            id = 250317,
            score = 3,
            author = "127395",
            text = "For those of you that don't have TomTom or any other coordinate AddOn the Box, Chest, and Bolts are as follows:\n\nFelix's Bolt's are to the immediate right of the entrance to the troll cave SSW of Anvilmar in front of the Gong. Then head due west until you reach a troll camp, by the campfire you should see a box glittering like most quest items, that is the chest. Finally head northeast until you reach another troll camp to the right of the camp fire you will find Felix's Box\n**NOTE** ~The cave entrance has usually 3-4 lvl 3's and each camp has 3-4 lvl 4's by it so be careful and you cannot stealth and loot the box at the same time so be ready to take on atleast 2 trolls or pull 1 at a time~",
            date = "2008-03-08T18:24:33-06:00",
            sourceUrl = "https://www.wowhead.com/quest=3361#comments:id=250317",
