    [3721] = {
        {
            id = 638089,
            score = 325,
            author = "335052",
            text = "OOX-17/TN <- TN shows that it is in Tanaris\nOOX-09/HL <- HL shows that it is in Hinterlands\nOOX-22/FE <- FE shows that it is in Feralas",
            date = "2009-03-10T16:26:32-05:00",
            sourceUrl = "https://www.wowhead.com/quest=3721#comments:id=638089",
        },
        {
            id = 1564176,
            score = 183,
            author = "sandyra",
            text = "Want a chicken for vanity or big profits?  You need to start by grabbing each of these:\n\nhttps://www.wowhead.com/item=8704 from The Hinterlands (Personal stats: Killed some stalkers, some trolls, some owlbeasts (about 20 all told)... Then killed my first ooze at Skulk Rock, and it dropped)\nhttps://www.wowhead.com/item=8623 from Tanaris (Personal stats:  Went into Zul'Farrak like all other posters recommend, killed some twenty or thirty trolls and scarabs, and it dropped from one of the troll corpses)\nhttps://www.wowhead.com/item=8705 from Feralas  (Personal stats:  As recommended by many other posters, Feral Scar Yetis - dropped on my first kill)\n\nOnly available if you have not already completed the quest.\nYes these still drop in Mists of Pandaria.\nYes it can drop off ANY mob in the respective zone, however https://www.wowhead.com/item=8705 has the highest drop rate from https://www.wowhead.com/npc=5292 IF you haven't already done the quest.\nIt WILL eventually drop - some days RNG is your best friend, other days you want to repeatedly punch a kitten (or other obscenely fluffy creature) just to illustrate how cruel the universe can be.\nThe command to check if you have completed ANY of the distress beacon quests is here (special thanks to MrsSushi (http://www.wowhead.com/user=MrsSushi) for locating the updated version which is still working as of patch 5.3):\n\n/run local z={\"Tanaris\",\"Hinterlands\",\"Feralas\"}for k,v in pairs({{351,648},{485,836},{25475,25476}})do print(z[k])for i,q in pairs(v)do print(\" #\"..i,\"\\124Hquest:\"..q..\"\\124h[\"..q..\"]\\124h\" ,IsQuestFlaggedCompleted(q)and COMPLETE or INCOMPLETE)end end\n\nYou will see lines of dialogue that look like this:\nTanaris\n#1 [351] Complete\n#2 [648] Complete\nHinterlands\n#1 [485] Complete\n#2 [836] Complete\nFeralas\n#1 [25475] Incomplete\n#2 [25476] Incomplete\n\nAfter completing all three escorts, you can then acquire the quest https://www.wowhead.com/quest=3721 and get your https://www.wowhead.com/item=10398.\n\nHappy hunting!",
            date = "2011-11-06T00:28:17-05:00",
            sourceUrl = "https://www.wowhead.com/quest=3721#comments:id=1564176",
        },
        {
            id = 3225,
            score = 129,
            author = "osuracnaes",
            text = "In order to get this quest, you must have completed all the OOX escort quests in Tanaris (https://www.wowhead.com/quest=351 -> https://www.wowhead.com/quest=648), Hinterlands (https://www.wowhead.com/quest=485 -> https://www.wowhead.com/quest=836), and Feralas (https://www.wowhead.com/quest=25475 -> https://www.wowhead.com/quest=25476).",
            date = "2006-11-08T19:37:14-06:00",
            sourceUrl = "https://www.wowhead.com/quest=3721#comments:id=3225",
        },
        {
            id = 1524010,
            score = 48,
            author = "840475",
            text = "Here's a kicker for you....if you do a race change (I went from Blood Elf to Goblin) ... you must do the quests over again.  I ran the macros mentioned in this thread and they reported that I had completed the quests, but the Questgiver for 'An OOX of your own' would not give me the quest, so I opened a ticket.  The GM indicated it showed yes, I had completed the quests, but due to the race change, it caused issues.  He said this happens quite a lot.  I wish he had just granted me the new quest, but he indicated I had to go back and do them again.  So...I'm off to do that.\n\nI hope this helps someone else with this type of trouble.",
            date = "2011-09-21T13:31:49-05:00",
            sourceUrl = "https://www.wowhead.com/quest=3721#comments:id=1524010",
        },
        {
            id = 190628,
            score = 43,
            author = "6100",
            text = "Note that the reward is not bind on pickup, so you can try selling it on the auction house since this pet isn't that common.",
            date = "2007-11-24T21:24:53-06:00",
            sourceUrl = "https://www.wowhead.com/quest=3721#comments:id=190628",
        },
    },
    [4021] = {
        {
            id = 123304,
            score = 79,
            author = "VitaDoden",
            text = "If you're lazy as me and have a higher leveled character beside the one you're doing the quest on you can just go with the quest-char to the place of the event and start it. then you log on your higher char and kill the centaurs.  log on the questchar again and loot the banner piece. Presto :)",
            date = "2007-07-19T10:43:19-05:00",
            sourceUrl = "https://www.wowhead.com/quest=4021#comments:id=123304",
        },
        {
            id = 4377,
            score = 73,
            author = "4618",
            text = "This is the last in a line of quests that had you killing centaur and centaur leaders the Barrens over. This final quest spawns a battle between Horde forces and Centaur forces. The Horde forces are typically overrun by the Centaur, unless you help.\n\nIn order to get Warlord Krom'zar to spawn, a number of centaur must be defeated. Krom'zar is no pushover though, he's a level 20 elite and comes with a pair of bodyguards, and there's also the rest of the centaur to worry about. Best to do this with others, and the Horde forces can also be counted on to help.",
            date = "2006-11-25T12:56:09-06:00",
            sourceUrl = "https://www.wowhead.com/quest=4021#comments:id=4377",
        },
        {
            id = 101762,
            score = 42,
            author = "Arx4",
            text = "For those who didn't do the quest right away.\n\nTo start the event, just simply talk to him(Quest Giver) and ask \"Where is Warlord Krom'zar?\"\n\nAnd you'll see couple of Horde Defenders and Kolkar starting to appear. West of the bunker your at, to be more specific.",
            date = "2007-06-10T08:10:24-05:00",
            sourceUrl = "https://www.wowhead.com/quest=4021#comments:id=101762",
        },
        {
            id = 54088,
            score = 31,
            author = "35226",
            text = "This quest can be very deceiving. It is yellow at like lvl 19, but even at a level as high as 22 it cannot be soloed without immense trouble.\n\nWarlord Krom'zar appears on the southern side as far as I can tell, and he comes with his two buddies. The best strategy is to fight only in the south battle so as to get the upper hand with the NPC's on your team. If the Kolkar are outnumbered when Krom'zar appears, then the NPCs can help you with damage and aggro.\n\nThe biggest thing to watch out for is the casters that cast Lightning Cloud. It is an aoe attack that will completely destroy any kind of upper had that you can have by wasting your NPC's. If you are careful of that then getting the upper hand is possible.\n\nOverall the best strategy is to just get another lvl 20 or so to help you with the quest. No matter what happens, usually 2 people can DPS him down before he kills them both.",
            date = "2007-03-20T05:58:43-05:00",
            sourceUrl = "https://www.wowhead.com/quest=4021#comments:id=54088",
        },
        {
            id = 1919376,
            score = 26,
            author = "Grayy",
            text = "So, I had to do a little looking into this one in order to unlock it.\n\nHere's a list of the quests I did in the order I did them to unlock Counterattack (http://www.wowhead.com/quest=4021).\n\n1. I did Kolkar Leaders (http://www.wowhead.com/quest=850) but was unable to find Ta'jari for A Little Diversion (http://www.wowhead.com/quest=13992) after finishing it. I suspect that this quest is not needed to unlock anything.\n\n2. Then I did King of Centaur Mountain (http://www.wowhead.com/quest=13995/) and the follow ups: Flushing Out Verog (http://www.wowhead.com/quest=14072) and Verog the Dervish (http://www.wowhead.com/quest=851)\n\n3. That unlocked Deathgate's Reinforcements (http://www.wowhead.com/quest=14073) from Thork in the x roads. Followed by Hezrul Bloodmark (http://www.wowhead.com/quest=852) and then finaly, Counterattack! (http://www.wowhead.com/quest=4021)!\n\nThe only other quests I did in the barrens were:\nTake it up with Tony (http://www.wowhead.com/quest=14052)\nGlomp is Sitting On It (http://www.wowhead.com/quest=14056)\nGuns. We Need Guns. (http://www.wowhead.com/quest=14057)\nMutiny, Mon! (http://www.wowhead.com/quest=14063)\n\nHope this saves hours of looking it up! :)",
            date = "2013-11-18T10:01:48-06:00",
            sourceUrl = "https://www.wowhead.com/quest=4021#comments:id=1919376",
        },
    },
    [4083] = {
        {
            id = 1854743,
            score = 155,
            author = "parkerj316",
            text = "Ok here is a very detailed account of what to do to be able to learn the ability Smelt Dark Iron (http://www.wowhead.com/spell=14891).  I am creating this one detailed as possible because it is annoying to get bits and pieces by reading through several posts to get all of the info needed.\n1. Before heading to Blackrock Mountain (http://www.wowhead.com/maps=46:205328) to go into Blackrock Depths (http://www.wowhead.com/zone=1584) you should gather these items in these amounts for the quest  Spectral Chalice (http://www.wowhead.com/quest=4083).\nGold Bar (http://www.wowhead.com/item=3577) x20\nTruesilver (http://www.wowhead.com/item=6037) x 10\nStar Ruby (http://www.wowhead.com/item=7910) x 2\n2. Next you head to Blackrock Mountain (http://www.wowhead.com/maps=46:205328) to go into Blackrock Depths (http://www.wowhead.com/zone=1584).\n3. Once inside the instance Blackrock Depths (http://www.wowhead.com/zone=1584), turn to your right and you will see a bullet like drilling machine(aka digger) sticking out of the ground. When you click on it choose the option \"take me just past The Grim Guzzler\".  When you load back in from taking the digger there is a mob, after the mob you will turn right, go down a flight of stairs, turn right again and bypass Ambassador Flamelash (http://www.wowhead.com/npc=9156) by turning left in his chamber. Follow the little hallway to the Mold Foundry, once in the Mold Foundry you will follow the room around to the right where you will enter the Summoner's Tomb.\n4 . You will speak to  Gloom'rel (http://www.wowhead.com/npc=9037) which is the second dwarf on the right upon entering the Summoner's Tomb.\n5. When you speak to him you will ask him to tell you all his secrets and he will summon the  Spectral Chalice (http://www.wowhead.com/quest=4083) to the right of him that will have an exclamation indicating a quest. Pick up the quest and if you have brought the above mentioned items you will be greeted with a lit up question mark signaling you are able to turn it in.\n6. Be sure you speak to him again after you have turned in the quest and you will tell him \"I have paid the price now tell me your secrets\" and he will grant you the ability to smelt Dark Iron.\nWhen you get or if you have already aquired the Dark Iron you wish to smelt, then you can either kill the seven and the door will open.  Once you have gone through the door there is a door to your immediate right that leads you to the bridge that takes you to the Molten Core. To the left and just before the bridge is a set of train tracks leading to where you actually smelt the Dark Iron.\n\nHope this helped!",
            date = "2013-05-20T14:19:43-05:00",
            sourceUrl = "https://www.wowhead.com/quest=4083#comments:id=1854743",
        },
        {
            id = 33113,
            score = 82,
            author = "Rahvin616",
            text = "This is the quest to be able to smelt Dark Iron.  More information can be found at http://www.wowhead.com/?spell=14891.",
            date = "2007-02-09T10:07:03-06:00",
            sourceUrl = "https://www.wowhead.com/quest=4083#comments:id=33113",
        },
        {
            id = 54143,
            score = 72,
            author = "BlackZam",
            text = "If I drop mining.\nCan I do this quest again if I decide to pick up mining again?",
            date = "2007-03-20T07:52:19-05:00",
            sourceUrl = "https://www.wowhead.com/quest=4083#comments:id=54143",
        },
        {
            id = 71298,
            score = 65,
            author = "45548",
            text = "The quest is only offered if you're a miner.  I think you might also need to be 230, not positive but I dont remember being offered the quest til 230+",
            date = "2007-04-22T22:36:47-05:00",
            sourceUrl = "https://www.wowhead.com/quest=4083#comments:id=71298",
        },
        {
            id = 825942,
            score = 35,
            author = "448732",
            text = "This is the quickest route but requires either BS made keys, or a Rogue. You enter the instance and open the door to your left. Go until you see a door to your right and open that as well. Go through and there is a door on your left. Open it and watch for the patrolling Fireguards. There are stairs to your right, you want to go to the left. You will see Shadowforge Lock and you need to click on it to unlock it. Be careful not to aggro any of the mobs. After unlocking it go back to the stairs and then go up them. Take the path to the left and continue until you find a door. Go through it and continue bypassing all mobs that you can. Watch out for Fireguard Destroyer's that patrol the area. You will come upon an open area, you will want to go right, down to the room with the lamps.\n\nGo away down a bit and turn right to the last path before the dead end room. If you have gone right way you will see a passage with some Fireguard Destroyers on left and right. Go straight through and you will be in 'The Bar'. Go right up to the stairs. At the end of the room you will see Plugger Spazzring. Pick pocket him to get Grim Guzzler Key. After this he will yell and aggro the area to you!. Go back just after the stairs there is a door behind Phalanx. Open it with the key.\n\nYou will find yourself in a large circlular room. Bypass as many mobs as you can then on your left there is an entrance. Go down and you will see Ambassador Flamelash. Ignore him and go to the left. There is an entrance here. Take it and go down to a large room with Moltem War Golems. Go through them and keep going straight. You will see a stairs leading down, take them and go through the door. Congratulations you are in the 'Summoners Tomb'.\n\nTalk to Gloom'Rel (2nd ghost dwarf on your right). Talk to him and a Spectral Chalice will appear. Click on it and turn in the required materials to complete the quest and talk to Gloom'Rel again who will now you know teach you how to smell dark iron!",
            date = "2009-08-29T04:28:37-05:00",
            sourceUrl = "https://www.wowhead.com/quest=4083#comments:id=825942",
        },
    },
    [4103] = {
        {
            id = 22440,
            score = 26,
            author = "entropicdragon",
            text = "In order to loot the Corrupted Soul Shards, you must be carrying a Cenarion Beacon (http://www.wowhead.com/?item=11511) in your inventory. You can receive this beacon from Maybess or Arathandris, as appropriate to your faction, once you have completed their Cleansing Felwood quest.",
            date = "2007-01-21T15:00:40-06:00",
            sourceUrl = "https://www.wowhead.com/quest=4103#comments:id=22440",
        },
        {
            id = 2279,
            score = 19,
            author = "Kimera",
            text = "Give 'em to Maybess Riverbreeze, she can be found around 46,83 in Felwood.",
            date = "2006-10-26T14:59:39-05:00",
            sourceUrl = "https://www.wowhead.com/quest=4103#comments:id=2279",
        },
        {
            id = 430436,
            score = 12,
            author = "Quibus",
            text = "This quest counts for Loremaster of Kalimdor (http://www.wowhead.com/?achievement=1678).",
            date = "2008-11-04T05:58:02-06:00",
            sourceUrl = "https://www.wowhead.com/quest=4103#comments:id=430436",
        },
        {
            id = 272872,
            score = 6,
            author = "133110",
            text = "I also found the ooze dropping Corrupted Soul Shards. Decent rate too. But I found mine around Bloodvenom Falls. The Tainted Ooze around the lake and river (better drop rate near the river tho on both sides of road) drop Corrupted Soul Shards. This is by far the easiest (IMO) way to get the Salves.\n\n\"And suddenly there came a tapping, as if someone gently rapping, rapping at my chamber door. You heard me rapping, RIGHT?\"\nBrandon Lee - 'Eric Draven' - \"The Crow\"\n\n**Edit**\nI went back (to farm more ><) and found the Tainted Ooze in Jaedenar had good drop rates too. Real slow respawn rate tho. No worries. A quick ride north to Bloodvenom Falls will quickly round out what you need. 8D",
            date = "2008-04-16T17:34:03-05:00",
            sourceUrl = "https://www.wowhead.com/quest=4103#comments:id=272872",
        },
        {
            id = 132553,
            score = 5,
            author = "38821",
            text = "i got them from all the oze that are around jaedenar wather at 40-48 both side of the little path to the jaedenar caves, is a relly good rop rate almost 100% and i got a nice epic mace too  [Taran Icebreaker] , don;t forget to ask for the  [Cenarion Beacon] from Maybass (the man with the q) before u go for the Corrupted Soul Shard , good luck",
            date = "2007-08-05T09:47:41-05:00",
            sourceUrl = "https://www.wowhead.com/quest=4103#comments:id=132553",
        },
    },
