        {
            id = 1086811,
            score = 2,
            author = "526021",
            text = "Anybody know about the status of any of the Felwood quests as they relate to Loremaster?\n\nEdit: I can confirm that the first time turnin does count toward Loremaster.  I have not turned in a second time, I would assume it doesn't count as it is a repeatable version of the same quest.",
            date = "2010-07-22T20:34:14-05:00",
