    [4621] = {
        {
            id = 1635436,
            score = 120,
            author = "IMissThottbot",
            text = "For those who did the PHASED grind, and then realized that Fleet Master Firallon is also PHASED and thus cannot give you the Avast, Ye Admiral quest, he is still available.\n\nHe is just outside Booty Bay, on the boat near the big goblin statue, on a ship.  Not only that, but also the phased versions of Fleet Master Seahorn & Baron Revilgaz count toward the quest!\n\nThank you to Playfellow for pointing this out on the Bloodsail Buccaneers page.",
            date = "2012-03-05T13:48:20-06:00",
            sourceUrl = "https://www.wowhead.com/quest=4621#comments:id=1635436",
        },
        {
            id = 3590,
            score = 70,
            author = "DrDre",
            text = "Take note that you MUST be hated with Booty Bay in order to get this quest. There is a bug/exploit you can do to get to Friendly with Bloodsail and still be friendly with Booty Bay, but you will be unable to get this quest.\n\nDont waste your time on the exploit. But get this hat, its very worth it for the novelty! Dont be afraid of goblin rep. You can reobtain that within hours with just about 200 gold by buying cloth and turning it in (or farm instances for it)\n\nYARR MATEYS!",
            date = "2006-11-13T02:55:36-06:00",
            sourceUrl = "https://www.wowhead.com/quest=4621#comments:id=3590",
        },
        {
            id = 3180202,
            score = 31,
            author = "LaffiBoozegnome",
            text = "Here is how you do all 3 quests for Bloodsail Buccaneers:\n\n-Get to friendly with Bloodsail Buccaneers, by killing guards in Booty Bay.\n-Get to hated with Booty Bay\n\nGo to \"Good-Boy\" Bruce at\n\n/way 41.6 61.2 \"Good-Boy\" Bruce\n\nand take the quest \"Avast Ye, Scallywag\". Avast Ye, Scallywag will lead you to the next quest to Fleet Master Firallon at\n\n/way 46.6 95.2 Fleet Master Firallon\n\nHe will then offer you two quests:\n-Avast Ye, Admiral  <-- Completing this before Avast Ye, Scallywag will make you unable to take it after.\n-Dressing the Part\n\nThese are the 3 quests available to Bloodsail Buccaneers.",
            date = "2020-01-06T09:37:22-06:00",
            sourceUrl = "https://www.wowhead.com/quest=4621#comments:id=3180202",
        },
        {
            id = 306157,
            score = 27,
            author = "163475",
            text = "For those that looked for more then just basic info on the quest Avast Ye, Admiral!\n\nI have 2 warnings you should heed.\n\n1.  On the way to the Inn is nasty business,  many times along the way there are 'check points' where your presence will spawn bruisers who will immediatly aggro you.  If you kill them, then try to eat, or even just take a breather, they will spawn ontop of you again, within a window of oh, lets say 5 seconds.  With that in mind you need to KEEP MOVING.\n\n2.  You won't just get aggro from the Bruisers, I was also attacked by other NPCS on the way up.\n\nI was able to solo this but I died several times.   You can spirit rez but most locations bring you right into combat.  The one spot I found you could rez in without immediate aggro was the clear spot in the Inn, where there are 2 rooms , right after the bridge, and right before going up to a bruiser room and your intended targets.\n\nIf you have died in the general area, and would like a place to not get instant aggro, this is it.\n\nThe targets themselves were a joke, the bruisers are what is fierce.  Remember keep in melee range, those guns will drop you in the ocean,  send you to more bruisers.  Very deadly.\n\nI recommend you bring pots and sat food because if your going to solo this every bit helps.",
            date = "2008-06-17T00:09:20-05:00",
            sourceUrl = "https://www.wowhead.com/quest=4621#comments:id=306157",
        },
        {
            id = 380228,
            score = 22,
            author = "Cuphat",
            text = "After the release of 3.0.2, completing this quest will finally grant us the title \"Bloodsail Admiral\"! Pirates, rejoice, for the battle has been won!",
            date = "2008-09-18T18:35:24-05:00",
            sourceUrl = "https://www.wowhead.com/quest=4621#comments:id=380228",
        },
    },
