    [5501] = {
        {
            id = 1195356,
            score = 33,
            author = "Stryker666",
            text = "For those of you redoing quests to get steamwheedle reputation back after 4.0.3a this quest has not reset.",
            date = "2010-11-29T09:46:09-06:00",
            sourceUrl = "https://www.wowhead.com/quest=5501#comments:id=1195356",
        },
        {
            id = 4489,
            score = 17,
            author = "Ormriss",
            text = "The bones are found in the Kodo Graveyard.  Mouse over the solitary kodo skulls and you'll see that you can use them.  Once you open a skull, grab the bone but be ready to either fight or run.  There's a better than 50% chance that a Kodo Apparation will spawn and attack you.  They are level 38 and not too hard.  Just watch your back, as the birds in the graveyard patrol and aggro easy.",
            date = "2006-11-25T21:14:09-06:00",
            sourceUrl = "https://www.wowhead.com/quest=5501#comments:id=4489",
        },
        {
            id = 1636056,
            score = 7,
            author = "Seegtease",
            text = "\"I'll give you something in return\" he tells me, as I stand there with my palm open expectantly. It remains empty.\n\nFilthy lying goblins.",
            date = "2012-03-07T00:04:57-06:00",
            sourceUrl = "https://www.wowhead.com/quest=5501#comments:id=1636056",
        },
        {
            id = 55499,
            score = 6,
            author = "27005",
            text = "If you can stealth, you can \"open\" the skull, and stealth before picking it up to avoid fighting the apparition.",
            date = "2007-03-22T16:27:48-05:00",
            sourceUrl = "https://www.wowhead.com/quest=5501#comments:id=55499",
        },
        {
            id = 119461,
            score = 5,
            author = "6571",
            text = "As a horde player, just open the skulls nearest to the back entrance of the horde camp. When an apparition spawns, run back and let the guards take it down. You can even dig up another bone when they are still fighting with it.",
            date = "2007-07-12T09:34:37-05:00",
            sourceUrl = "https://www.wowhead.com/quest=5501#comments:id=119461",
        },
    },
    [5545] = {
        {
            id = 12868,
            score = 23,
            author = "8714",
            text = "The bundles of wood are easily gathered northwest of the outpost.  Watchout for the prowlers and bears though, they can give you quite the trouble while doing this quest.  If you have the Defend the Frontier quest you can complete that while collecting the wood with ease.",
            date = "2006-12-10T16:54:30-06:00",
            sourceUrl = "https://www.wowhead.com/quest=5545#comments:id=12868",
        },
        {
            id = 83125,
            score = 16,
            author = "43040",
            text = "Although the two quests above go together really well. Should you have already completed \"Protect the Frontier\". Take the time to kill the Prowlers. They are pretty good at yielding \"Stringy Wolf Meat\". Which is good for cooking.\n\nThe Bundles themselves respawn pretty quick. They are really close to each other. So you don't have to go all out looking for these. Making this a really quick quest for 775 XP.\n\nFor instance. I found them by trees at these coordinates:\n\n76,62 (2 bundles)\n77,60 (Near Murloc Camp - be wary)\n77,63\n77,64\n78,62\n79,61\n79,63\n\nYou only need 8 bundles. So as you can see, there isn't that much searching to complete this quest.\n\n~Lie",
            date = "2007-05-14T20:00:43-05:00",
            sourceUrl = "https://www.wowhead.com/quest=5545#comments:id=83125",
        },
        {
            id = 281662,
            score = 7,
            author = "148610",
            text = "Also good to do this quest with bounty on the murlocks as there are a few bundles of wood near the murlock village ^_^",
            date = "2008-05-03T12:39:54-05:00",
            sourceUrl = "https://www.wowhead.com/quest=5545#comments:id=281662",
        },
        {
            id = 483225,
            score = 7,
            author = "204053",
            text = "It appears that this quest doesn't grant any reputation gains any longer.",
            date = "2008-12-01T17:28:37-06:00",
            sourceUrl = "https://www.wowhead.com/quest=5545#comments:id=483225",
        },
        {
            id = 674242,
            score = 7,
            author = "260764",
            text = "No more rep from this quest, give it a miss if that's all you're after as there's no follow up.",
            date = "2009-04-12T17:30:35-05:00",
            sourceUrl = "https://www.wowhead.com/quest=5545#comments:id=674242",
        },
    },
    [5561] = {
        {
            id = 61013,
            score = 72,
            author = "Asmodoues",
            text = "Note that when you bring the kodos to the goblin camp, you need to talk to it before you recieve quest credit.",
            date = "2007-04-02T11:22:06-05:00",
            sourceUrl = "https://www.wowhead.com/quest=5561#comments:id=61013",
        },
        {
            id = 11202,
            score = 43,
            author = "Orik",
            text = "The easiest way to round up the kodos are in the graveyard near by. A faster way is when a kodo pack comes, get them and return to Smeed fast so you can get the other kodos.",
            date = "2006-12-08T13:58:35-06:00",
            sourceUrl = "https://www.wowhead.com/quest=5561#comments:id=11202",
        },
        {
            id = 1195345,
            score = 33,
            author = "Stryker666",
            text = "For those of you redoing quests to get steamwheedle reputation back after 4.0.3a this quest has not reset",
            date = "2010-11-29T09:41:25-06:00",
            sourceUrl = "https://www.wowhead.com/quest=5561#comments:id=1195345",
        },
        {
            id = 724847,
            score = 25,
            author = "anaamika",
            text = "If you're like me and need to be hit over the head with more detail than is already available on this page, here are the details of what I did after I made a bunch of mistakes and finally figured it out:\n- find any of the kodo specified\n- when you're within range, click on the item provided to channel the taming spell\n- once kodo is tamed, run back to the quest giver who will say his spiel; note that the 5 minute timer is basically the amount of time you have in which to get back to quest giver with this particular kodo. Given how close you'll be to him, you shouldn't need all 5 minutes. If, like me, you wasted those 5 minutes picking up kodo bones for the other quest (http://www.wowhead.com/?quest=5501), and the timer ran out, the tamed kodo will despawn.\n- once you get back to quest giver, and quest giver has said his piece, mousing over the kodo will show that kodo has something to say\n- right click, read text (or not) and click on goodbye, counter will indicate one kodo tamed\n- lather, rinse, repeat until you have the number you need\n\nWhat confused me was not knowing what the timer was about, not realizing you had to kite the tamed kodos back to the quest giver one at a time (unlike those rats in Deeprun Tram that you can drag back all at once after you've tamed the number you need), and especially not knowing you had to wait for quest giver to finish talking, and then \"talk\" to the kodo yourself in order for it to count as a taming. Not the clearest of quests I've done so far.\n\nHope this helped at least one other person out there :)",
            date = "2009-05-23T02:36:01-05:00",
            sourceUrl = "https://www.wowhead.com/quest=5561#comments:id=724847",
        },
        {
            id = 3204224,
            score = 22,
            author = "Arheia",
            text = "Bring tamed Kodo's to /way 60.8, 61.8\nIt's not labeled on the map, I always forget where I retrieved the quest so I hope this helps someone! :P",
            date = "2020-05-04T13:35:13-05:00",
            sourceUrl = "https://www.wowhead.com/quest=5561#comments:id=3204224",
        },
    },
    [5581] = {
        {
            id = 4488,
            score = 30,
            author = "Ormriss",
            text = "Run to Mannoroc Coven and use the big ring portals near the road.  A level 38 Doomguard appears and attacks you.  Defeat him to seal the portal.  The portals respawn after about five minutes, so if you don't want to explore the coven, locate three portals and make a loop.  Be careful of patrols, several Infernos, Summoners and Doomguards have long patrol routes that take them right next to several portals.",
            date = "2006-11-25T21:11:08-06:00",
            sourceUrl = "https://www.wowhead.com/quest=5581#comments:id=4488",
        },
        {
            id = 150681,
            score = 15,
            author = "Nappa",
            text = "And for all the fisherman out there, the discoloration in the purple water does not fish anything special ;) .... yes I actually tried haha",
            date = "2007-09-08T18:30:25-05:00",
            sourceUrl = "https://www.wowhead.com/quest=5581#comments:id=150681",
        },
        {
            id = 51259,
            score = 8,
            author = "30210",
            text = "Pretty easy quest i completed it as a lvl 36 warlock.  Its easier if u just find 3 portals and loop and they spawn in maybe about 2-3 min. The coordinates for the 3 portals r 50,74/50,70/49,77.  u dont really need to kill the mobs there but just make sure u dont get aggro by them just pull the portal guard sumwhere isolated from the mobs.",
            date = "2007-03-14T19:20:19-05:00",
            sourceUrl = "https://www.wowhead.com/quest=5581#comments:id=51259",
        },
        {
            id = 126749,
            score = 6,
            author = "59050",
            text = "More portals: 54,79 / 55,79 / 53,80",
            date = "2007-07-25T17:14:06-05:00",
            sourceUrl = "https://www.wowhead.com/quest=5581#comments:id=126749",
        },
        {
            id = 43233,
            score = 5,
            author = "26388",
            text = "Pretty easy to solo. I finished this quest as a level 35 fire mage with no problem. Just make sure you pull them out of the portal and into the lake in the middle of the area to avoid getting aggro from other mobs and patrols.\nIf you do aggro, remember that Infernos are immune to fire, killing them with frost bolts was painful since it doesn't do as much damage. But the fire ward is really helpful, I didn't really take that much damage from them with the fire ward/mana shield combo, just took longer to kill them than I would have liked.",
            date = "2007-02-27T07:01:56-06:00",
            sourceUrl = "https://www.wowhead.com/quest=5581#comments:id=43233",
        },
    },
