    [6134] = {
        {
            id = 4484,
            score = 88,
            author = "Ormriss",
            text = "When the ghosts show up, they are not hostile.  The ghosts with a blue aura can be pulled without worrying about aggroing more ghosts.  The ghosts with the green aura act as normal though, so if you pull one of them, you will pull all the nearby green aura-ed ghosts.\n\nFor every ghost you kill, another will show up, walking towards the magnet.  Use that to your advantage by pulling new ghosts before they get too close to the magnet.  If ghosts aren't showing up or if all the existing ghosts have the green aura, just wait for your magnet to decay.  All the ghosts will disappear and you can place a fresh magnet.",
            date = "2006-11-25T21:02:05-06:00",
            sourceUrl = "https://www.wowhead.com/quest=6134#comments:id=4484",
        },
        {
            id = 2454,
            score = 36,
            author = "5583",
            text = "Place the provided crate atop the little hill at about 63,89 to use the crate and summon the ghosts.",
            date = "2006-10-31T16:45:50-06:00",
            sourceUrl = "https://www.wowhead.com/quest=6134#comments:id=2454",
        },
        {
            id = 16715,
            score = 20,
            author = "Fedris",
            text = "Be warned they curse you with \"Curse of the Fallen Magram\" which increases all damage taken by 15%.",
            date = "2006-12-18T03:52:42-06:00",
            sourceUrl = "https://www.wowhead.com/quest=6134#comments:id=16715",
        },
        {
            id = 19504,
            score = 18,
            author = "dezmond",
            text = "Note that the ghosts that spawn are lvl 38-40 and there are a couple of lvl 40 patrolling centaur that summon lvl 38-39 skeletons, so while you can get the quest at 34, you might want to go in either with a party, or after you've achieved a couple more levels.  (Or be ready to die a few times.)  --36 demonology spec warlock--",
            date = "2007-01-06T00:53:55-06:00",
            sourceUrl = "https://www.wowhead.com/quest=6134#comments:id=19504",
        },
        {
            id = 2552533,
            score = 8,
            author = "Habu64",
            text = "This quest just got a bit harder with scaling in 7.3.5.  Use \"old school\" techniques to complete it.  Range damage can still pull one at a time if you're careful.  Otherwise, be prepared for the 54 second walk back from the graveyard.",
            date = "2018-02-13T17:26:49-06:00",
            sourceUrl = "https://www.wowhead.com/quest=6134#comments:id=2552533",
        },
    },
