    [6646] = {
        {
            id = 1006816,
            score = 19,
            author = "Malicii",
            text = "It's a bad idea to turn these in for Thorium Brotherhood rep since they're so rare, with the only ways of getting them being Molten Destroyers and mining Dark Iron Deposits, both with epically low drop rates.\n\nI just finished [Sulfuras, Hand of Ragnaros] (http://www.wowhead.com/?item=17182), but I had to work HARD farming Molten Destroyers and literally soft reset MC 20+ times to get enough Bloods to finish it that week. That was on top of trying hours of Dark Iron farming in BRD without a single Blood, and already having 1 hidden on a bank alt. There were never any in the AH or sellers through trade either, probably due to the fact that most people skip as much trash as they can, including Molten Destroyers.\n\nThe [Sulfuron Ingot] (http://www.wowhead.com/?item=17203)s took way less effort to acquire. Even though they aren't farmable, the drop rate is pretty high off Golemagg(~30%), so there's a good chance you'll see them on the AH, being traded or dropping for you while doing rep runs. You can easily sell Bloods of the Mountain for as much, or more, than Sulfuron Ingots.\n\ntl;dr: Sell/Save any Bloods of the Mountain you find and use only Lava/Fiery Cores for turn-ins, since they have good drop rates on pretty much all the elementals and giants in the instance, especially bosses.",
            date = "2010-03-27T23:38:48-05:00",
            sourceUrl = "https://www.wowhead.com/quest=6646#comments:id=1006816",
        },
        {
            id = 1223050,
            score = 15,
            author = "kite1099",
            text = "As of today, patch 4.0.3 i guess\nI received 2000 reputation upon handing in this quest.",
            date = "2010-12-10T21:50:33-06:00",
            sourceUrl = "https://www.wowhead.com/quest=6646#comments:id=1223050",
        },
        {
            id = 155615,
