    [6781] = {
        {
            id = 1172428,
            score = 14,
            author = "Stonehearth",
            text = "Once he receives 500 armor scraps, he will upgrade your units:\n\nSeasoned Units (500 armor scraps):\n- Increases certain NPC efficiency (graveyard guards, mine guards and patrolling guards)\n- Gives players a 10% damage and size increase buff periodically for 2 minutes (Vanndar Stormpike will yell when it is given) General's Warcry (http://www.wowhead.com/spell=28418)\n\nVeteran Units (1000 armor scraps):\n- Increases certain NPC efficiency further\n- Gives players a 20% damage and size increase buff periodically for 2 minutes General's Warcry (http://www.wowhead.com/spell=28419)\n\nChampion Units (1500 armor scraps):\n- Increases NPC efficiency by the most it can be increased\n- Gives players a 30% damage and size increase buff periodically for 2 minutes General's Warcry (http://www.wowhead.com/spell=28420)\n\nThese are rarely utilised these days but they are very powerful: reaching champion can turn the tide of battle due to the 30% damage buff. In Cataclysm, it appears that upgrading units will provide around a 100% increase in efficiency. For example, a caster mine guardian has 10,000 hitpoints and Fireball's for 5k. When upgraded, the caster mine guardian will have 22,000 hitpoints and Fireball for an average of 13,000.",
            date = "2010-11-16T08:20:22-06:00",
            sourceUrl = "https://www.wowhead.com/quest=6781#comments:id=1172428",
        },
        {
            id = 10988,
            score = 3,
            author = "8805",
            text = "Keep on bringing in the armor scraps and upgrade them troops to make winning this AV a piece of cake =)",
            date = "2006-12-08T11:42:06-06:00",
            sourceUrl = "https://www.wowhead.com/quest=6781#comments:id=10988",
        },
