            date = "2008-07-23T04:53:21-05:00",
            sourceUrl = "https://www.wowhead.com/quest=7026#comments:id=333656",
        },
    },
    [7027] = {
        {
            id = 1540510,
            score = 12,
            author = "691546",
            text = "Just post this here so everyone sees this.\n\nToday it worked to tame a ram but only after doing this\n\nStand close to the ram\nTurn off any damage on attack buffs (like Retribution Aura (spell=7294))\nClick the collar then WAIT. (so NO moving / casting / turning more then your field of view of the ram)\nWhen you use it there will be hearts above both you and the ram and you WILL be attacked (the ram doesn't hit hard) and it will take some time for the taming to be complete. There will be NO casting/channeling bar however.\nAt a certain point the mount will become Friendly (not neutral) and you can go back to the stables.\n\nYou can mount up and ride ahead, when it gets back to far it will teleport to you.",
            date = "2011-10-11T13:43:13-05:00",
            sourceUrl = "https://www.wowhead.com/quest=7027#comments:id=1540510",
        },
        {
            id = 325666,
            score = 9,
            author = "Vlad",
            text = "#showtooltip\n/use Stormpike Training Collar\n/click GossipTitleButton3\n/click GossipTitleButton1\n/click QuestFrameAcceptButton\n/click QuestFrameCompleteQuestButtonUse this macro to:Accept the quest\nTame the Ram\nTurn in the tamed Ram\nDeliver the quest\n(loop)",
            date = "2008-07-13T12:41:43-05:00",
            sourceUrl = "https://www.wowhead.com/quest=7027#comments:id=325666",
        },
