    [7081] = {
        {
            id = 136584,
            score = 25,
            author = "68342",
            text = "To complete this quest you don't even have to interact with anything, you just have to be in the general area of a graveyard when somebody assaults it. The graveyard does not have to change hands, just be assaulted once.",
            date = "2007-08-12T16:22:15-05:00",
            sourceUrl = "https://www.wowhead.com/quest=7081#comments:id=136584",
        },
        {
            id = 438233,
            score = 19,
            author = "Vlad",
            text = "Only valid when taking over horde graveyards. Neutral once or those \"in-conflict\" wont suffice.",
            date = "2008-11-11T04:33:25-06:00",
            sourceUrl = "https://www.wowhead.com/quest=7081#comments:id=438233",
        },
        {
            id = 942220,
            score = 9,
            author = "masterprogram",
            text = "One of several \"scaling\" quests which grants more exp as you level up, instead of less.\n\n For example, most quests are red at one point, turn orange, yellow, green and then eventually gray as you outlevel it, and slowly decreasing the amount of exp you earn. This quest starts out yellow, and remains that color no matter what level you are. As such, it grants a gradually increasing amount of exp depending on what level you turn it in which is seemingly based on the amount of exp a \"typical\" yellow quest at that level would give.\n\n8460 exp @ level 51 with the 20% heirloom exp bonus\n8820 exp @ level 52\n9120 exp @ level 53",
            date = "2010-01-08T20:15:04-06:00",
            sourceUrl = "https://www.wowhead.com/quest=7081#comments:id=942220",
        },
        {
            id = 1927400,
            score = 3,
            author = "1091478",
            text = "You need to join to the instance of pvp battle \"Alterac Valley (http://www.wowhead.com/zone=2597)\" to do this quest, by going inside the cave in front of you and talking to Grumbol Grimhammer (http://www.wowhead.com/npc=19907/grumbol-grimhammer).\nChoose to join the \"Alterac Valley (40v40) Raid battle\" from a Battlegrounds list. It will pull you into the battleground.\nThere is an opposite faction flag surrounded by 4 enemy NPC closer to the enemy base and they are standing right next to the main road. You need to capture the flag by helping each other for killing them all.\nEven after finishing your quest, you need to stay until the entire battle finishes. Once you come back from the battle, you need to talk to the quest giver to complete the quest.\n\nBefore join the battle, you can learn some of the basics from \"Basic Guide to Alterac Valley (http://www.blizzardguides.com/alterac_valley_av_guide.html)\"..",
            date = "2013-12-19T15:32:25-06:00",
            sourceUrl = "https://www.wowhead.com/quest=7081#comments:id=1927400",
        },
        {
            id = 5905945,
            score = 2,
            author = "jewelkingquests",
            text = "as of 11.0 accepting this quest is bugged, we have a bug report going for it and the other broken quests:\nhttps://us.forums.blizzard.com/en/wow/t/broken-quests-incompletable-list/1903553",
            date = "2024-07-26T21:46:48-05:00",
            sourceUrl = "https://www.wowhead.com/quest=7081#comments:id=5905945",
        },
    },
