        {
            id = 942211,
            score = 3,
            author = "masterprogram",
            text = "One of several \"scaling\" quests which grants more exp as you level up, instead of less.\n\n For example, most quests are red at one point, turn orange, yellow, green and then eventually gray as you outlevel it, and slowly decreasing the amount of exp you earn. This quest starts out yellow, and remains that color no matter what level you are. As such, it grants a gradually increasing amount of exp depending on what level you turn it in which is seemingly based on the amount of exp a \"typical\" yellow quest at that level would give.\n\n8460 exp @ level 51 with the 20% heirloom exp bonus\n8820 exp @ level 52\n9120 exp @ level 53",
            date = "2010-01-08T20:10:22-06:00",
            sourceUrl = "https://www.wowhead.com/quest=7124#comments:id=942211",
        },
    },
