    [7167] = {
        {
            id = 2223,
            score = 29,
            author = "1699",
            text = "In order to be offered this quest, I believe you need to have your rep with Frostwolf maxed at the Exalted level (999/1000).",
            date = "2006-10-24T15:21:29-05:00",
            sourceUrl = "https://www.wowhead.com/quest=7167#comments:id=2223",
        },
        {
            id = 2863031,
            score = 9,
            author = "CertainlyNobody",
            text = "edit: You can now get the toy https://www.wowhead.com/item=169298 from AV.\n\nAt the time of writing this, it is not possible to upgrade your insignia to https://www.wowhead.com/item=17909. Opening a ticket won't help you either.\n\nI've done some research, and it seems the 999/1000* reputation pre-requisite for the upgrade quest was broken in Legion when Blizzard added the reputation bonus caches. The bonus cache patch changed the way reputation works at exalted, and thus the pre-requisite never triggers. The only thing you can do is to submit a bug report or suggestion to Blizzard, and hope they fix the quest in the future.\n\n* To be exact, the reputation trigger was apparently slightly lower than 999, possibly 900?",
            date = "2018-12-30T13:36:26-06:00",
            sourceUrl = "https://www.wowhead.com/quest=7167#comments:id=2863031",
        },
        {
            id = 148848,
