    [7172] = {
        {
            id = 6299,
            score = 10,
            author = "1410",
            text = "This trinket is not only a \"hearthstone\" while you're inside AV but it's a great trinket to farm with, because of it's dodge and health regen, also great for tanks (especially druid tanks) and rogues who are trying to stack up their dodge %age",
            date = "2006-12-05T14:35:56-06:00",
