        },
        {
            id = 545209,
            score = 9,
            author = "87701",
            text = "Korrak the Bloodrager, once the ruler of the Field of Strife where he killed many-a Horde and Alliance player alike later moved his throne to Snowfall Graveyard where he wouldn't go away without a fight surpassing Ragnaros in epicness. After some time he tired of toying around with the warring factions and went away, silently to a place no one knew - until now!\n\nShould you see yourself face to face with Korrak, beware that no matter the outcome of the fight: he'll be sure to rise - stronger yet again.",
            date = "2009-01-03T18:41:28-06:00",
            sourceUrl = "https://www.wowhead.com/quest=7202#comments:id=545209",
