    [7224] = {
        {
            id = 228116,
            score = 5,
            author = "364",
            text = "If one is attempting to use Alterac Valley as a way to increase your rep for any of the Horde factions, then doing the repeatable turn in quests like this one are a must.\n\nThis particular quest leads into the \"More Booty!\" (\"http://www.wowhead.com/?quest=6741\") repeatable version.  The rep reward for that is 10 rep with Orgrimmar per 20 armor scraps (\"http://www.wowhead.com/?item=17422\") turned in.  This might not seem like a lot of rep at first, but keep in mind that armor scraps are some of the most abundant drops off of your fallen enemies, often dropping ~20 armor scraps apiece.  If you are constantly in the heat of battle and remember to loot the ones who are killed, you can quite easily pick up several hundred armor scraps to turn in.\n\nAdditionally, turning in numerous stacks of armor scraps to Smith Regzar (\"http://www.wowhead.com/?npc=13176\") will allow him to upgrade the guards that protect your territory and graveyards from veterans to champions all the way to elite.  Turning in armor scraps also will reward you with a 30 minute \"Polished armor\" buff that increases your armor by 10%\n\nOne last thing to remember.  Getting \"Orgrimmar\" rep from any of these quests also gives rep across the faction board, so if you are looking to get to exalted with everyone in the faction, Alterac Valley is your most cost-and-time effective option as opposed to buying/farming runecloth and turning them in at 75 rep/stack of 20\n\nTonight while AVing off and on over a four hour period netted an increase of 1200 points of rep from this and the other repeatable turn ins",
            date = "2008-02-02T03:00:05-06:00",
            sourceUrl = "https://www.wowhead.com/quest=7224#comments:id=228116",
        },
        {
            id = 358084,
            score = 4,
            author = "NoSmoking",
            text = "If you do this quest for the first time, it grants 250 Frost Wolf rep. It only grants 1 rep AFTER its first turn in.",
            date = "2008-08-20T21:48:04-05:00",
            sourceUrl = "https://www.wowhead.com/quest=7224#comments:id=358084",
        },
        {
            id = 199948,
            score = 2,
            author = "sneakygnome",
            text = "I was awarded 9700xp for this simple quest in patch 2.3. Level 57 at the time of completion. Just loot enemy bodies all over AV for the armor scraps.",
            date = "2007-12-12T00:55:12-06:00",
            sourceUrl = "https://www.wowhead.com/quest=7224#comments:id=199948",
        },
        {
            id = 211766,
            score = 1,
            author = "35868",
            text = "I was Awarded 9550 exp at lvl 53",
            date = "2008-01-02T18:08:07-06:00",
            sourceUrl = "https://www.wowhead.com/quest=7224#comments:id=211766",
