    [7402] = {
        {
            id = 137736,
            score = 7,
            author = "SilentJ",
            text = "For those who aren't old enough to remember this quest, this was one of four Collection Quests that were available at the time of Alterac Valley's debut. Each time you killed an Orc player, you would collect his/her tooth and return it to Corporal Noreg Stormpike in Dun Baldar. Each turn-in would reward you with rep.\n\nBlizzard eventually did away with the Collection Quests in AV, though their respective NPC's can still be found in Dun Baldar.",
            date = "2007-08-14T09:32:21-05:00",
            sourceUrl = "https://www.wowhead.com/quest=7402#comments:id=137736",
        },
    },
