    [7493] = {
        {
            id = 5206101,
            score = 45,
            author = "concordantnexus",
            text = "Circa 9.0\n\nThis quest is NOW granted by Overlord Natoj (https://www.wowhead.com/npc=14392/overlord-natoj), a troll with a blue mohawk hanging around just inside the front gate of Orgrimmar, on the right side, in front of the Orgrimmar General Store.\n\nAlternatively: /way 52.65, 82.48 Overlord Natoj\n\nHaving had to Google around to figure out how to learn the pattern, I can relate that once you learn this pattern, DO NOT DROP LEATHERWORKING as it will be lost. This pattern is awarded by completing the quest and GMs can't reinstate it, nor can the relearn options in Oribos et cetera.",
            date = "2021-06-28T19:35:48-05:00",
            sourceUrl = "https://www.wowhead.com/quest=7493#comments:id=5206101",
        },
        {
            id = 5569257,
            score = 25,
            author = "Taliesen",
            text = "Can confirm that you still need 300 skill in Classic LW in order to pick up this quest (after turning in the quest from Onyxia's head).",
            date = "2023-03-18T00:36:10-05:00",
            sourceUrl = "https://www.wowhead.com/quest=7493#comments:id=5569257",
        },
        {
            id = 1382053,
            score = 19,
            author = "789746",
            text = "For the curious, this quest is still in the game and works as of patch 4.0.6. I was able to get it on my druid after turning in the Head of Onyxia to Neeru Fireblade (you don't bring it to Thrall anymore on account of him not being in Orgrimmar) and then going to Overlord Runthak near the entrance of Ogrimmar.",
            date = "2011-04-01T23:35:20-05:00",
            sourceUrl = "https://www.wowhead.com/quest=7493#comments:id=1382053",
        },
        {
            id = 754003,
            score = 12,
            author = "Jimmayx",
            text = "To get the pattern you must get the Head of Onyxia and turn in the quest from it to Thrall. He leads you to Overlord Runthak to finish it. After you turn in the quest for Onyxia's head to Overlord Runthak, if you have 300 leatherworking, you will get a quest that you instantly turn into him. That gives you the pattern for the Onyxia Scale Cloak.",
            date = "2009-06-21T16:45:10-05:00",
            sourceUrl = "https://www.wowhead.com/quest=7493#comments:id=754003",
        },
        {
            id = 812989,
            score = 10,
            author = "Sedirex",
            text = "If I've already done the Head quest and then level LW, will I be able to take this quest?\n\nUpdate for the curious: I leveled LW and was able to take this quest, even post-3.2.2.",
            date = "2009-08-16T00:45:50-05:00",
            sourceUrl = "https://www.wowhead.com/quest=7493#comments:id=812989",
        },
    },
    [7495] = {
        {
            id = 289796,
            score = 48,
            author = "120564",
            text = "The funny thing is that when you bring Onyxia's head to Bolvar, Katrana Prestor is probably going to be standing right next to him, and she is Onyxia.\n\nGotta love WoW game mechanics.",
            date = "2008-05-17T10:58:04-05:00",
            sourceUrl = "https://www.wowhead.com/quest=7495#comments:id=289796",
        },
        {
            id = 14386,
            score = 26,
            author = "9167",
            text = "To complete the entire quest up to this point, you need to do the following:\n\n1.  You begin in the Burning Steppes with the quest Dragonkin Menace, which is pretty easy.\n\n2. \"The True Master\" chain comes right after step 1.  You:\na. Talk to Salomon in Lakeshire\nb. Talk to Highlord Bolvar Fordragon in Stormwind\nc. Talk to Lady Katrana Prestor who is just across from Fordragon\nd. Talk to Salomon in Lakeshire again\ne. Talk to Marshal Maxwell back in the Burning Steppes\nf. Talk to Ragged John at the Flame Crest\ng. Talk to Marshal Maxwell again\n\nFrom here you need to go to Blackrock Depths and talk to Marshal Windsor.  He will tell you to return to Marshal Maxwell again with the quest Abandoned Hope.\n\nAt this point, it seems the quest just runs into a dead end because Marshal Maxwell does not give you any further quests.  You need to go back to Blackrock Depths and kill mobs there for a random drop called A Crumpled Up Note.  Right-clicking the item will set you back on a quest to Marshal Windsor.\n\nWindsor gives you the quest A Shred of Hope, which is to retrieve lost information from Golem Lord Argelmach and General Angerforge.  You return this to Marshal Windsor.\n\nThe next part is a bit hard - you need to escort Windsor from his jail cell.  Make sure the area is cleared of mobs before you do this.  The quest is called Jail break!\n\nAfter escorting Windsor out, go talk to Marshal Maxwell.  He will give you a quest called Stormwind Rendezvous, which can be done solo if you stay away from the battle.\n\nTalk to Bolvar just after the fight.  He will give you The Dragon's Eye.  This means you have to go to Winterspring to find Haleh.\n\nAfter this, go to Upper Blackrock Spire and kill Drakkisath for the Drakefire Amulet.  Kill Drakk and loot the blood.\n\nReturn the blood to Haleh in Winterspring and she will give you the key to Onyxia.  The Drakefire Amulet attunes you to Onyxia's lair, which allows you to kill Onyxia and return the head to Bolvar in Stormwind.",
            date = "2006-12-12T19:02:09-06:00",
            sourceUrl = "https://www.wowhead.com/quest=7495#comments:id=14386",
        },
        {
            id = 425763,
            score = 9,
            author = "183632",
            text = "Now King Varian Wrynn ends the quest.",
            date = "2008-10-30T17:27:23-05:00",
            sourceUrl = "https://www.wowhead.com/quest=7495#comments:id=425763",
        },
