    [7604] = {
        {
            id = 1565534,
            score = 390,
            author = "Whoofer",
            text = "You can get this quest from Lokhtos Darkbargainer (http://www.wowhead.com/npc=12944/lokhtos-darkbargainer) in the Grim Guzzler (Blackrock Depths) if you have  https://www.wowhead.com/item=17203x1 in your inventory.",
            date = "2011-11-07T09:35:51-06:00",
            sourceUrl = "https://www.wowhead.com/quest=7604#comments:id=1565534",
        },
        {
            id = 6235986,
            score = 384,
            author = "Tchali",
            text = "If you are here because you need to complete this quest for the Stormwind Forge decor item, purchase a Sulfuron Ingot through the AH, get to the Grim Guzzler through the Blackrock Depths dungeon OR by using Direbrew's Remote. You do not need to have Thorium Brotherhood rep maxed out, nor do you need to be a blacksmith.\n\nThis is not offered as a typical quest, no exclamation point; it's in his dialogue options. As long as you have the Sulfuron Ingot in your inventory, he will have a dialogue and you click along and then offer him the ingot in exchange for the pattern. The decor item will then be unlocked for your future purchase.\n\nThe Plans: Sulfuron Hammer can then be sent to an alt or sold on the AH. You cannot acquire a second one of these on the same character, so don't try returning with another Ingot.",
            date = "2025-12-01T17:18:38-06:00",
            sourceUrl = "https://www.wowhead.com/quest=7604#comments:id=6235986",
        },
        {
            id = 1511448,
