    [7761] = {
        {
            id = 1783563,
            score = 233,
            author = "Rocknight",
            text = "To complete this quest:\n1. Enter Blackrock Spire instance\n2. In first room you come to, go up the left set of stairs and turn left up a shorter flight of stairs into Dragonspire Hall\n3. You must kill everything in this hall - mobs are in groups in small rooms on the sides.\n4. When everything is dead, a door opens at the north end of the hall. Go through it and follow the stairs up and around.\n5. Now you enter the Hall of Binding and another locked door blocks your path.\n6. Click on the Blackrock Altar on the left side, kill all adds.\n7. Wait until the elemental on the platform in the middle reaches full power and he then becomes attackable.  Kill him and the door at the Southern end of the room will open.\n8. Go through the door into The Rookery (this is the room where you get the Jenkins achievement, incidentally)\n9. Go right and double back on yourself up a slope. Take the first set of steps up, into the Hall of Blackhand.\n10. Turn right, go through the hall and up one of the sets of stairs at the East end.  You're now at Blackrock Stadium.  Jump down into the pit to start the boss encounter here.\n11. Kill waves of adds and finally kill a boss (Warchief Rend).\n12. A small gate on the South Side of the pit opens up when Rend dies.  Go through it.\n13. Left. Up a slope. Right. Down a slope. Right again. Over a bridge.\n14. Enter a room called Spire Throne.  You'll find General Drakkisath in this room.  Kill him and loot the orb that appears behind him.\n\nQuest complete.",
            date = "2012-12-18T11:09:43-06:00",
            sourceUrl = "https://www.wowhead.com/quest=7761#comments:id=1783563",
        },
        {
            id = 1133,
            score = 99,
            author = "4602",
            text = "All you need to do is get the letter from the quartermaster who is near the UBRS/LBRS entrance.\n\nOnce you have the letter you start the quest and you need to go through UBRS and kill General Drakkisath and touch the orb to finish the quest.\n\nYou will then be attuned to BWL and able to use the outside orb to enter BWL.\n\nGood Luck\n\n-SolarFusion",
            date = "2006-09-28T10:15:28-05:00",
            sourceUrl = "https://www.wowhead.com/quest=7761#comments:id=1133",
        },
        {
            id = 212489,
            score = 71,
            author = "114441",
            text = "This is without doubt the best quest in the game. If you don't usually have a full quest log I suggest keeping it just to read so you can fall in love with Rend Blackhand...",
            date = "2008-01-03T22:08:33-06:00",
            sourceUrl = "https://www.wowhead.com/quest=7761#comments:id=212489",
        },
        {
