        {
            id = 257340,
            score = 17,
            author = "91657",
            text = "Gains\nUpon completion of this quest you will gain:\n\n    *\n      550 experience (or a 4 80 compensation at level 70)\n\nMy 23 warlock got 825 xp for turning this in - anyone who is budgeting xp should know that it's not 550 anymore.",
            date = "2008-03-22T04:08:50-05:00",
