    [7905] = {
        {
            id = 1589380,
            score = 28,
            author = "462295",
            text = "If you did this quest before 4.3 patch You can obtain Darkmoon Adventurer's Guide by talking to Selina Dourman @ 55.55, 54.75 in Darkmoon Faire Island.",
            date = "2011-12-04T13:43:10-06:00",
            sourceUrl = "https://www.wowhead.com/quest=7905#comments:id=1589380",
        },
        {
            id = 1588772,
            score = 25,
            author = "Treekachu",
            text = "This quest is currently not available to players who completed the version of this quest that existed prior to patch 4.3, and thus, you lose out on 5 Darkmoon Faire tickets.\n\n---\n\nOfficial update (01/08/12) from Blizzard on the matter:\n\"Unfortunately, “The Darkmoon Faire” quest cannot be made available for characters that previously completed the quest. This is due to the fact that this quest is not a new quest, but reuses the old quest ID. We realize this was an error and will be taking steps to not repeat it for future quests, but it does mean that characters that completed it before will not be able to complete the new version with the ticket reward.\"",
            date = "2011-12-04T03:30:02-06:00",
            sourceUrl = "https://www.wowhead.com/quest=7905#comments:id=1588772",
        },
        {
            id = 302321,
