            text = "intrestingly i was raiding IF the other day on my horde and the person had the quest so i grabbed it\nalso iv done it on horde side on the before",
            date = "2008-06-09T17:16:48-05:00",
            sourceUrl = "https://www.wowhead.com/quest=7905#comments:id=302321",
        },
        {
