    [8271] = {
        {
            id = 118873,
            score = 32,
            author = "57336",
            text = "This is the second part of a 2-part quest:\n\n\"The Battle of Alterac\" (win AV bg)\n\"Hero of Stormpike\" (get the reward)",
            date = "2007-07-11T02:43:17-05:00",
            sourceUrl = "https://www.wowhead.com/quest=8271#comments:id=118873",
        },
        {
            id = 307794,
            score = 10,
            author = "143805",
            text = "I'd advise getting these weapons, most of these will last you from 51 till outland.",
            date = "2008-06-19T15:52:53-05:00",
            sourceUrl = "https://www.wowhead.com/quest=8271#comments:id=307794",
        },
        {
            id = 627244,
            score = 5,
            author = "111622",
            text = "Choice for class:\n\nIce Barbed Spear (http://www.wowhead.com/?item=19106) - Warrior, Paladin, Druid, Hunter, Death Knight\nCold Forged Hammer (http://www.wowhead.com/?item=20648) - Paladin, Shaman, Priest, Druid\nWand of Biting Cold (http://www.wowhead.com/?item=19108) - Mage, Priest, Warlock\nBloodseeker (http://www.wowhead.com/?item=19107) - Rogue, Warrior\n\nDPS only classes are limited to only 1 weapon. Hunters should go with the Polearm, as the Crossbow has strength on it, which is melee only. If you plan on Vendoring your reward, choose the Polearm, as it sells for the most amount.\n\nEach weapon is level 63, allowing Wrath of the Lich King enchants, but only the Polearm and Mace can be enchanted.",
            date = "2009-03-01T08:53:23-06:00",
            sourceUrl = "https://www.wowhead.com/quest=8271#comments:id=627244",
        },
        {
            id = 1830906,
            score = 3,
            author = "gbalkam",
            text = "just a note.. As of MoP, Hunters can no longer use melee weapons as \"stat sticks\".  It's ranged only.  So for a hunter, the cross bow is the obvious choice.  For a druid the stave, monk, same.Rogue.. got shafted... again....",
            date = "2013-03-18T23:27:23-05:00",
            sourceUrl = "https://www.wowhead.com/quest=8271#comments:id=1830906",
        },
        {
            id = 3248407,
            score = 3,
            author = "r00flr00fl1",
            text = "This quest is no longer obtainable since BFA, this was just confirmed to me by a GM ingame.",
            date = "2020-11-12T13:05:01-06:00",
            sourceUrl = "https://www.wowhead.com/quest=8271#comments:id=3248407",
        },
    },
    [8272] = {
        {
            id = 17965,
            score = 46,
            author = "entropicdragon",
            text = "This quest becomes available immediately upon completion of http://www.wowhead.com/?quest=7142 The Battle For Alterac which requires that you be present at the end of a battleground which Horde wins.",
            date = "2006-12-25T14:17:44-06:00",
            sourceUrl = "https://www.wowhead.com/quest=8272#comments:id=17965",
        },
        {
            id = 252185,
            score = 18,
            author = "73945",
            text = "if u want some xtra exp before heading for the AV cave... frostwolf ambassador rokh (http://www.wowhead.com/?npc=13842) outside the bank in orgrimmar will give you a quest that leads you to the AV cave. great reminder if u have forgotten all about this great quest :D",
            date = "2008-03-12T09:30:27-05:00",
            sourceUrl = "https://www.wowhead.com/quest=8272#comments:id=252185",
        },
        {
            id = 373479,
            score = 6,
            author = "169529",
            text = "This quest is turned in immediately after accepting it.  You do not have to go back into av and win again.  You simply accept the quest and turn it in for great loot.",
            date = "2008-09-10T23:54:28-05:00",
            sourceUrl = "https://www.wowhead.com/quest=8272#comments:id=373479",
        },
        {
            id = 447045,
            score = 6,
            author = "241670",
            text = "You'll usually lack a good weapon around 50 anyway. The rewards are great; Rather easy to get,  and last for that 8-10 levels before you get to Outland and replace all the rest of the shait you have on you.\n\nWorth the effort. If there is any effort at all.",
            date = "2008-11-16T07:05:34-06:00",
            sourceUrl = "https://www.wowhead.com/quest=8272#comments:id=447045",
        },
        {
            id = 84316,
            score = 2,
            author = "33180",
            text = "No reason for a hunter to get the spear over the xbow unless they already have some boe epic ranged weapon. Bloodseeker is so amazingly overpowered at lvl 51 it's not even funny.",
            date = "2007-05-16T23:51:33-05:00",
            sourceUrl = "https://www.wowhead.com/quest=8272#comments:id=84316",
        },
    },
