    [8280] = {
        {
            id = 84002,
            score = 14,
            author = "39280",
            text = "66.35 is where I'm finding them, but they are all over, non-tameable and have a brutal dash if you are knocked off guard. Be careful if you are under lvl 55, as the mobs are 54-60+ it's also a Battleground PVP area, so becareful of Stealth pvp'ers.\n\nA Great Tactic if you don't mind waiting is, there are 4 Level 60 Cenarion Outriders sitting on Cat Mounts. Hit the critter then run back to them and they will kill it for you. Be watchful, there is a group of 10 lvl 60 bad guys that ride on the same path/patrol, that kill all 4 of these guys and will kill you if you aren't 60+.",
            date = "2007-05-16T10:39:22-05:00",
            sourceUrl = "https://www.wowhead.com/quest=8280#comments:id=84002",
        },
