    [8282] = {
        {
            id = 48715,
            score = 52,
            author = "radszuweit",
            text = "respawn IS slow almost 10 min",
            date = "2007-03-09T12:40:55-06:00",
            sourceUrl = "https://www.wowhead.com/quest=8282#comments:id=48715",
        },
        {
            id = 3811,
            score = 30,
            author = "sjonkel",
            text = "Located up the path south of Bronzebeard Encampment, near Deathclasp.\n\nCoordinates: 44, 91 (http://www.wowhead.com/?object=180435)",
            date = "2006-11-17T15:27:20-06:00",
            sourceUrl = "https://www.wowhead.com/quest=8282#comments:id=3811",
        },
        {
            id = 25577,
            score = 15,
            author = "11311",
            text = "The respawn on this is kinda slow! My guildies and I had to wait through 2 more respawns of Deathclasp before the satchel reappeared.",
            date = "2007-01-27T08:49:47-06:00",
            sourceUrl = "https://www.wowhead.com/quest=8282#comments:id=25577",
        },
        {
            id = 48779,
            score = 13,
            author = "sketched",
            text = "This quest is relatively simple.  The only trick is to opening it without aggroing the elite & two adds.  If you follow them up the mountain, just behind their aggro radius, you can open the satchel from max range without any problems.  Make sure you shift-click while opening, though, just in case.  That way you can open it, then get out of there.",
            date = "2007-03-09T15:32:31-06:00",
            sourceUrl = "https://www.wowhead.com/quest=8282#comments:id=48779",
        },
        {
            id = 227645,
            score = 12,
            author = "111406",
            text = "This quest can be done with the quest to kill Deathclasp.\n\nhttp://www.wowhead.com/?quest=8283\nSave's having to go down there twice\n\nCo'ords are 41,91\nOr look at the map\n\nhttp://www.wowhead.com/?maps=1377:410910\nThere is a path just behind the camp that leads up to Deathclasp.",
            date = "2008-02-01T01:51:07-06:00",
            sourceUrl = "https://www.wowhead.com/quest=8282#comments:id=227645",
        },
    },
    [8283] = {
        {
            id = 155645,
            score = 42,
            author = "76386",
            text = "btw Deathclasp is at 43.89 :)",
            date = "2007-09-20T11:45:08-05:00",
            sourceUrl = "https://www.wowhead.com/quest=8283#comments:id=155645",
        },
        {
            id = 28725,
            score = 22,
            author = "15940",
            text = "Soloed as a level 55 hunter, you can do it too! Set your pet's autocast of growl to OFF, put keep bite/claw/poison or whatever else does damage ON.  Put on aspect of the cheetah, pull with distracting shot + serpent sting, and kite with jump arcane shots and serpent stings, send pet in right away for extra dps.  DO NOT use conc. shot, because then the adds will be ahead of Deathclasp, and if Deathclasp falls behind, you need to slowdown and the guards will hit you.  I use a wide circular pattern to kite him, he has pretty low hp and moves slow so he is quite easy :).\n\nAlso adds respawn instantly if you kill them and reset him.",
            date = "2007-02-01T04:49:15-06:00",
            sourceUrl = "https://www.wowhead.com/quest=8283#comments:id=28725",
        },
        {
            id = 192858,
            score = 15,
            author = "97764",
            text = "I found her very near the bronzebeard camp, just up a little path to the mountains, for me she had 2 guards with her and also, once you've killed her be sure to get the satchel for the sick guy (this is another quest, the last in a chain-the one of getting poison realated drops)",
            date = "2007-11-28T15:53:09-06:00",
            sourceUrl = "https://www.wowhead.com/quest=8283#comments:id=192858",
        },
        {
            id = 1253160,
            score = 8,
            author = "FrightKing",
            text = "Path is now at 47, 81 behind Bronzebeard Encampment.",
            date = "2010-12-22T19:08:59-06:00",
            sourceUrl = "https://www.wowhead.com/quest=8283#comments:id=1253160",
        },
        {
            id = 213784,
            score = 7,
            author = "115081",
            text = "Deathclasp isnt immune to scare beast, so i assume he's also fearable by locks/priests. Trapped one, feared deathclasp, killed both adds then onto deathclasp. The paralyse poison is quite deadly, watch out for it. Easy as 58 hunter.",
            date = "2008-01-06T11:02:28-06:00",
            sourceUrl = "https://www.wowhead.com/quest=8283#comments:id=213784",
        },
    },
    [8284] = {
        {
            id = 1417882,
            score = 21,
            author = "DArcMattr",
            text = "Is there a reputation requirement before I can even see this quest? Geologist Larksbane isn't showing any quests available from her.\n\nEdit: I had to complete https://www.wowhead.com/quest=8321 and accept https://www.wowhead.com/quest=8304 before this became available.",
