    [8287] = {
        {
            id = 48907,
            score = 21,
            author = "23383",
            text = "A terrible purpose.. Jom Gabbar.. The Silithyst Must Flow.. Bliz likes their Dune. Along with referencing every other pop culture phenomenon. :D",
            date = "2007-03-09T22:42:38-06:00",
            sourceUrl = "https://www.wowhead.com/quest=8287#comments:id=48907",
        },
        {
            id = 108395,
            score = 16,
            author = "44538",
            text = "A while after completing this quest, you will get a letter in the mail:\n\n'Esteemed ,\n\nThe information you brought to my attention earlier has turned out to be extremely valuable. Already I am calling fo the changes to our battle plans to account for the new importance we attribute to the Twilight's Hammer presence.\n\nPlease accept this item as a small token of our gratitude. I hope we can continue to count on you as a valiant ally in our fight in Silithus.\n\nSincerely,\n\nCommander Mar'alith'\n\nAttached to this letter is Nature's Whisper (http://www.wowhead.com/?item=20645).",
            date = "2007-06-21T04:30:45-05:00",
            sourceUrl = "https://www.wowhead.com/quest=8287#comments:id=108395",
        },
        {
            id = 1983377,
            score = 10,
            author = "drpimento",
            text = "Don't be like me and discard  the DTT! I thought it was more trash or useless junk. Only had to abandon quest, and require thru Hermit Ortell, np.",
            date = "2014-07-22T21:48:46-05:00",
            sourceUrl = "https://www.wowhead.com/quest=8287#comments:id=1983377",
        },
        {
            id = 714390,
            score = 8,
            author = "Itami",
            text = "The note says:\nDay 1\nOur pilgrimage is over. We've finally reached Silithus where we're to establish contact. We have come from many places to collabroate in what is to be a monumental undertaking.\n\nThere is a tremendous sense of excitement in the air. Tomorrow we shall devote all our energy to building that which will allow communcation with THEM.\n\nTomorrow we shall construct a wind stone!\n\nDay 2\nThe location of the wind stone has been a subject of great debate. Not even the wisest among us can determine with great certainty where the place mentioned in the old prophecy actually refers to.\n\nI've stayed with the orginal northern group and time will undoubtedly prove us right. The argument that the energy lines intersect at detrimental angles at this location are foolish and naive.\n\nAlready we are gathering the necessary building materials at great speed.\n\nDay 15\nOur dedication has paid off. We are the first camp to finish the construction of a wind stone. If the other fools had stayed with us we would completed the task in less than a week!\n\nTomorrow we shall begin the rituals involved in summon Baron Kazum himself. He demanded to be the first to test the system and we couldn't contradict him as he's quick to anger.\n\nI expect he will be most pleased with us.",
            date = "2009-05-12T21:40:17-05:00",
            sourceUrl = "https://www.wowhead.com/quest=8287#comments:id=714390",
        },
        {
            id = 1672746,
            score = 5,
            author = "Karazzat",
            text = "Is it just me or is this the last quest in Sitilhus? I'm horde. The quests only got me to lvl 57! (with heirloom)",
            date = "2012-06-02T14:18:10-05:00",
            sourceUrl = "https://www.wowhead.com/quest=8287#comments:id=1672746",
        },
    },
    [8304] = {
        {
            id = 299920,
            score = 34,
            author = "entropicdragon",
            text = "The questioning proceeds as follows ((SPOILER ALERT!))\n---------------------------------------------------------------------------\n\nRutgar's Questioning\n\nBronzebeard's gone missing again! That dwarf sure didn't get any of his brother's good senses.\n\nHello, Rutgar. The Commander has sent me here to gather some information about his missing wife.\nYou best have a seat then, this is gonna be a long one.\n\nWhen we initially arrived in Silithus, Mistress Mar'alith was the first of the night elves from Cenarion Hold to join the expedition. Our routine was nothing out of the ordinary: Form a party to venture into the various hives and search for lost artifacts.\n\nThat sounds dangerous.\n\nIt sure is! Those hives were abuzz with various silithid that were none too happy to see us.\n\nEverything was going fine until we came across a glyphed crystal in Hive'Regal. She was drawn to it like a moth to a flame! She put her pretty little cheek up against the crystal and instantly entered a trance-like state. Naturally, this worried my crew. We picked her up and carried her out of there with a quickness!\n\nWhat happened to her after that?\nWe took her to the Commander with hopes that the druids of the Circle could fix her up. Sure enough, they were able to wake her up. We figured our business with the Circle was done and we could get back to work.\n\nA few weeks passed and everything was going fine. Brann was still around back then so we had a bit of order in our work structure. Then one day, out of the blue, she appeared back at our camp.\n\nNatalia?\nAre you daft? Who else would I be talking about? Yes, the girl - Mistress Mar-alith. Anyhow, she was back and not in too good of a mood. That's when the demands started flowing.\n\nWhat demands?\nShe demanded that we immediately head back to Hive'Regal! Brann would have none of that sass. He told her that there's no way we would go back into those hives without an army backing us up. It had gotten far too dangerous. The number of those stinking insects seemed to have tripled from when we first ventured into 'em.\n\nThat's when Natalia lost it!\n\nLost it? What do you mean?\nWhat do you mean what do I mean? She went nutso! The girl went straight crazy on us. Now ordinarily I don't hit girls but after I recovered from the blackout I was pretty damned angry. Brann, Rutgar, me and the monkey went positively orc on her!*  It's a miracle we were able to fend her off. She seemed almost possessed!\n\nPossessed by what?\n*Note that Rutgar speaks here as if he is, presumably, Frankal. This is an error in the game text.\nWho knows? Anyhow, that was the last I saw of her. Maybe Frankal can give you better information.\n\nNot to steer off topic here as I'm sure the work you're doing for the Commander is important, but we're on to something huge here. HUGE! Our requests to Ironforge for an army have so far fallen on deaf ears. Apparently we're stretched too thin in protecting the realm or some such nonsense. Once you take your report back to the Commander, come back down here with some friends. We need your help!\n\nI'll be back once I straighten this mess out.\n\n---------------------------------------------------------------------------\n\nFrankal's Questioning\n\nLook up to the heavens, . The Dragonflights have not been seen in this area for a thousand years! Those Qiraji are up to something, I just know it!\n\nHello, Frankal. I've heard that you might have some information as to the whereabouts of Mistress Natalia Mar'alith.\nOh brother, not this again... Have a seat [missy/sonny]*.\n\nI'm sure Rutgar has told you some of this story already so I'll spare you the boring details and get right down to the nitty gritty.\n\nThat's what I like to hear.\n* Thanks Linkcisco (\"/user=Linkcisco\") for male character term info!\nRight then! So the Mistress had come back for a second go at the hives but Brann was having none of that nonsense! Before the melee began, she started talking to something or someone. Crazier still, she started chanting in a language none of us had ever heard.\n\nThat's odd.\nYou're telling me! It's even stranger considering between Brann, Rutgar, me and the monkey, we know 38 different languages including a touch of Titan - both Vanir and Aesir.\n\nSo anyway, whatever she was click clacking about, it definitely wasn't with anyone \"present.\" She then nodded and went on the offensive! Attacked us outright!\n\nYou couldn't handle a lone night elf priestess?\n\nListen [missy/sonny], I'll have you know that whatever attacked us was no priestess of nothin'! Her eyes were aglow with something evil and she was genuinely frothing at the mouth! She came in, did some kind of  crazy scream that sent us all runnin' in separate directions then started flayin' our minds one by one. I'd be hearin' shadowy words in my head, watchin' the other's periodically black out here and there. It was madness! We would have been done for if not for the damned monkey.\n\nI've been meaning to ask out about that monkey.\nWhat's there to ask? He's a monkey you crazy fool. Anyhow, so yea, the monkey went into a frenzy after seein' ol' Brann flop into the sand face first. Nothin' the night elf could do was stopping Glibb here from poundin' on her noggin.\n\nThen what?\nI'll tell you 'then what.' She went runnin' straight for the hive. And you know what's crazier? Not a single damned bug got in her way or tried to stop her. She ran through them all as if she'd been best friends with 'em for centuries.\n\nWhat a story! So she went into Hive'Regal and that was the last you saw of her?\nYep.\n\nThanks for the information, Frankal.",
            date = "2008-06-05T04:22:45-05:00",
            sourceUrl = "https://www.wowhead.com/quest=8304#comments:id=299920",
        },
        {
            id = 14831,
            score = 17,
            author = "tokelazor",
            text = "Really easy quest, just go down to 41,88 and talk to both Frank and Rutgar.   Run through a small conversation, then return to Cenarion Hold.\n\nDon't have to kill them.\n\nAlso I recieved 6600 XP and instead of 100 rep I got 250 Rep with Cenarion Circle, maybe because I was neutral.",
            date = "2006-12-13T12:36:28-06:00",
            sourceUrl = "https://www.wowhead.com/quest=8304#comments:id=14831",
        },
        {
            id = 664323,
            score = 9,
            author = "265365",
            text = "DOES count towards Loremaster of Kalimdor.",
            date = "2009-04-03T04:02:11-05:00",
            sourceUrl = "https://www.wowhead.com/quest=8304#comments:id=664323",
        },
        {
            id = 1417905,
            score = 8,
            author = "DArcMattr",
            text = "As of 4.1.0, this quest requires you complete https://www.wowhead.com/quest=8321 before it's available.",
            date = "2011-05-13T17:28:48-05:00",
            sourceUrl = "https://www.wowhead.com/quest=8304#comments:id=1417905",
        },
