    [8309] = {
        {
            id = 1182721,
            score = 81,
            author = "708320",
            text = "As of Patch 4.0.3a Locations to openings are:\n\nHive'Regal: 58.3,78.5\nHive'Zora: 34.8, 59.8\nHive'Ashi: 53.0, 25.2",
            date = "2010-11-24T19:18:35-06:00",
            sourceUrl = "https://www.wowhead.com/quest=8309#comments:id=1182721",
        },
        {
            id = 1309835,
            score = 35,
            author = "735166",
            text = "Did this today and its the most annoying q ive ever done. I guess Blizz keeps changing the locations just for the fak of it.\n\nThis is what i found:\n\nHive Ashi:\nentrance at 52,25. go all the way to the bottom enter and keep right\nglyph at 54,25.\n\nHive Zora:\nentrance at 34,59\nglyph at 42,57 look out for the groups of wasps\n\nHive Regal\nentrance at 58,78\nglyph at 55,90",
            date = "2011-01-25T19:47:53-06:00",
            sourceUrl = "https://www.wowhead.com/quest=8309#comments:id=1309835",
        },
        {
            id = 1385050,
            score = 24,
            author = "779436",
            text = "THIS IS WRONG!  Entrance to Hive Regal is 58,78.  After searching forever trying to find a way into the mountains, which is where 55,87 is located, finally went to the quest write-up on \"Into the Maw...\" to see what they said, since Natalie is at the glyph.  Thank God!\n\nFound the following comment there...\n\n  The cave entrance is at 58,78. It is part of Hive'Regal.\n\nNatalie herself is as far south in as you can go. It's a long, linear, winding hive cave unlike the others. She is at 55,90.\n\nMake sure to get Hive'Regal's glyph, which she is staring at, for the Glyph Chasing quest.\n\nthen saw comment below by Gopem\n\n As of Patch 4.0.3a Locations to openings are:\n\nHive'Regal: 58.3,78.5\nHive'Zora: 34.8, 59.8\nHive'Ashi: 53.0, 25.2\n\nAlso note ...  kill the Slavemasters quickly, they cast the spell which makes you kill your pet instead of them!",
            date = "2011-04-05T21:34:06-05:00",
            sourceUrl = "https://www.wowhead.com/quest=8309#comments:id=1385050",
        },
        {
            id = 2544,
            score = 19,
            author = "5617",
            text = "Leads to Unraveling the Mystery (http://www.wowhead.com/?quest=8314).",
            date = "2006-11-02T07:03:42-06:00",
            sourceUrl = "https://www.wowhead.com/quest=8309#comments:id=2544",
        },
        {
            id = 1427729,
            score = 16,
            author = "765496",
            text = "I see nobody mentioned it, but since patch you only need to do 1 hive - regal, same place where you do Into the Maw of Madness (should be the hardest)\n\nDid it just while leveling rogue (and I did it old way when I was going after loremaster title with my main).",
            date = "2011-05-26T02:56:36-05:00",
            sourceUrl = "https://www.wowhead.com/quest=8309#comments:id=1427729",
        },
    },
    [8310] = {
        {
            id = 149071,
            score = 21,
            author = "Mordrus",
            text = "Get a \"brain\" from each of the three hives by killing any of the elite mobs at each one.  Drop rate is very high; I didn't have to kill more than 10 mobs at each place before the brain dropped.\n\nRecommend having one other person with you, but the mobs are soloable, though difficult.\n\nRecommend doing Glyph Chasing (http://www.wowhead.com/?quest=8309) and Into the Maw of Madness (http://www.wowhead.com/?quest=8306) in conjunction with this quest.\n\nOnce this quest and Glyph Chasing are completed, leads to Unraveling the Mystery (http://www.wowhead.com/?quest=8314).",
            date = "2007-09-04T15:27:35-05:00",
            sourceUrl = "https://www.wowhead.com/quest=8310#comments:id=149071",
        },
