    [8314] = {
        {
            id = 1428683,
            score = 26,
            author = "Nulgar",
            text = "It actually lead to the quest https://www.wowhead.com/quest=8315, which was related to Ahn'Qiraj in that it initiated the Ahn'Qiraj War Effort (http://www.wowpedia.org/Gates_of_Ahn%27Qiraj#Gathering_war_supplies) when someone first completed that quest on a server.\nThat quest was removed in 4.0.3a as well, true, so this quest trying to unlock its old followup causes the error message.",
            date = "2011-05-27T10:30:40-05:00",
            sourceUrl = "https://www.wowhead.com/quest=8314#comments:id=1428683",
        },
        {
            id = 1406851,
            score = 21,
            author = "503166",
            text = "For now for some reason when you finish this one in, you get a message \"You are not eligable for this quest\" which means we are blizzard and just break it here since it was once the start of the Shifting sands quest line which was pretty epic.\n\nSo for now nothing and the quests that are said to be following up according to wowhead aren't immplented in live I think.",
