    [8350] = {
        {
            id = 103478,
            score = 12,
            author = "Aurora",
            text = "From the quest giver, travel directly southeast. Be careful not to fall off of the bridge or explore the grounds if you do not wish to engage any more enemies just yet. When you arrive in Falconwing Square, enter the building with the blue curtains; that is the inn. Inside, speak to Innkeeper Delaniel to complete the quest.",
            date = "2007-06-13T04:47:47-05:00",
            sourceUrl = "https://www.wowhead.com/quest=8350#comments:id=103478",
        },
        {
            id = 25228,
            score = 9,
            author = "13761",
            text = "Just follow the road to the southeast till you find a town.\n48,47",
            date = "2007-01-26T16:51:23-06:00",
            sourceUrl = "https://www.wowhead.com/quest=8350#comments:id=25228",
        },
        {
            id = 743165,
            score = 5,
            author = "205721",
            text = "Just making fun of blizz here but, the quest giver says things about hearthstones when you complete it or when you can click complete after continue. And she says you can use a hearthstone ''Once every hour''. But currently you can use it ''Once every half hour'' just a fact noticed when i lvled my belf alt :P",
            date = "2009-06-10T20:22:03-05:00",
            sourceUrl = "https://www.wowhead.com/quest=8350#comments:id=743165",
        },
        {
            id = 785380,
            score = 3,
            author = "258919",
            text = "First of all, the bridge is not dangerous whatsoever. At all.\n\nSecondly, I reccommend all classes, after training for them at the trainer in the Square, buy Gladius. Seeing as even casters don't get much bonuses from staves until later on, this is probably the best weapon you can get for a couple levels. At this level, casters even melee some.",
            date = "2009-07-22T11:31:41-05:00",
            sourceUrl = "https://www.wowhead.com/quest=8350#comments:id=785380",
        },
        {
            id = 2098800,
            score = 3,
            author = "Khayos",
            text = "most boring quest of the Blood Elf area",
            date = "2015-02-03T06:31:23-06:00",
            sourceUrl = "https://www.wowhead.com/quest=8350#comments:id=2098800",
        },
    },
    [8376] = {
        {
            id = 955295,
            score = 4,
            author = "526868",
            text = "Counts towards Loremaster of Kalimdor (http://www.wowhead.com/?achievement=1680)",
            date = "2010-01-24T03:26:25-06:00",
            sourceUrl = "https://www.wowhead.com/quest=8376#comments:id=955295",
        },
        {
            id = 956481,
            score = 3,
            author = "VanCleef",
            text = "This quest does count for the Loremaster of Kalimdor achievement, but it is only available to paladins.\n\nOther classes:\nRogue (http://www.wowhead.com/?quest=8378)\nMage and Warlock (http://www.wowhead.com/?quest=8381)\nPriest (http://www.wowhead.com/?quest=8379)\nHunter (http://www.wowhead.com/?quest=8377)\nShaman (http://www.wowhead.com/?quest=8380)\nDruid (http://www.wowhead.com/?quest=8382)\nWarrior (http://www.wowhead.com/?quest=8316)",
            date = "2010-01-25T13:37:06-06:00",
            sourceUrl = "https://www.wowhead.com/quest=8376#comments:id=956481",
        },
        {
            id = 1045961,
            score = 2,
            author = "457614",
            text = "This quest is a part of the quest chain starting with Dearest Natalia (http://www.wowhead.com/quest=8304).\n\nThe order of completion on the quest chain is:\n\nDearest Natalia (http://www.wowhead.com/quest=8304)\nGlyph Chasing (http://www.wowhead.com/quest=8309) and Breaking the Code (http://www.wowhead.com/quest=8310). Into the Maw of Madness (http://www.wowhead.com/quest=8306), which is the direct follow-up from Dearest Natalia (http://www.wowhead.com/quest=8304) is done in the same area, but is not part of the quest chain.\nUnraveling the Mystery (http://www.wowhead.com/quest=8314)\nThe Calling (http://www.wowhead.com/quest=8315)\nThe different versions of this quest (Druid (http://www.wowhead.com/quest=8382), Hunter (http://www.wowhead.com/quest=8377), Mage/Warlock (http://www.wowhead.com/quest=8381), Shaman (http://www.wowhead.com/quest=8380), Paladin (http://www.wowhead.com/quest=8376), Priest (http://www.wowhead.com/quest=8379), Rogue (http://www.wowhead.com/quest=8378), Warrior (http://www.wowhead.com/quest=8316)) Naturally, there is no Death Knight quest reward since Death Knights didn't exist in-game when these quests were made.",
            date = "2010-05-25T12:50:00-05:00",
            sourceUrl = "https://www.wowhead.com/quest=8376#comments:id=1045961",
        },
        {
            id = 134048,
            score = 1,
            author = "77411",
            text = "This quest is the last step of \"The Calling\"\nhttp://www.wowhead.com/?quest=8315\n\nBut it's the Paladin Reward",
            date = "2007-08-07T22:25:43-05:00",
            sourceUrl = "https://www.wowhead.com/quest=8376#comments:id=134048",
        },
    },
