    [8463] = {
        {
            id = 103556,
            score = 14,
            author = "Aurora",
            text = "The Unstable Mana Crystals are found in small crates located throughout the Ruins of Silvermoon. They are often lying next to walls, broken doors, or along roads. Keep an eye out for Arcane Patrollers and Wretched Urchins as you move about collecting the Crystals!",
            date = "2007-06-13T08:14:55-05:00",
            sourceUrl = "https://www.wowhead.com/quest=8463#comments:id=103556",
        },
        {
            id = 24013,
            score = 9,
            author = "4800",
            text = "Alongside the bridge you cross as you come into Falconwing Square.  I found the 6 that I gathered at 45,43; 46,42; 45,41; 44,40; 44,38; 43,37.",
            date = "2007-01-24T20:39:21-06:00",
            sourceUrl = "https://www.wowhead.com/quest=8463#comments:id=24013",
        },
        {
            id = 137454,
            score = 8,
            author = "15585",
            text = "Take this quest along with\n\nMajor Malfunction - http://www.wowhead.com/?quest=8472\nand\nWanted: Thaelis the Hungerer - http://www.wowhead.com/?quest=8468\n\nIf you start out on the road at around 44, 45 and follow that north you can pick up the amount of Mana Crystals required for Unstable Mana Crystals and kill the Arcane Patrollers along the way for the Major Malfunction quest. The road will bring you under the bridge and right up too the side door of the house at 45, 38 where Thaelis is located. You will have to kill maybe two Urchins outside, and one inside and then you can pull Thaelis by himself. Turn around and take the same road back the way you came in.\n\nOne trip and you should have 3 quests complete.",
            date = "2007-08-13T23:17:50-05:00",
            sourceUrl = "https://www.wowhead.com/quest=8463#comments:id=137454",
        },
        {
            id = 691285,
            score = -2,
            author = "356103",
            text = "I've tried to dothis quest with my paladin and mage but i ahve the same problem each time... i get close to the crates to open them start opening them and then i get \"challenged\" and sparks fly and i cant open the crates? is there something im doing wrong?",
            date = "2009-04-23T20:32:57-05:00",
            sourceUrl = "https://www.wowhead.com/quest=8463#comments:id=691285",
        },
    },
    [8468] = {
        {
            id = 137456,
            score = 10,
            author = "15585",
            text = "Take this quest along with\n\nMajor Malfunction - http://www.wowhead.com/?quest=8472\nand\nUnstable Mana Crystals - http://www.wowhead.com/?quest=8463\n\nIf you start out on the road at around 44, 45 and follow that north you can pick up the amount of Mana Crystals required for Unstable Mana Crystals and kill the Arcane Patrollers along the way for the Major Malfunction quest. The road will bring you under the bridge and right up too the side door of the house at 45, 38 where Thaelis is located. You will have to kill maybe two Urchins outside, and one inside and then you can pull Thaelis by himself. Turn around and take the same road back the way you came in.\n\nOne trip and you should have 3 quests complete.",
            date = "2007-08-13T23:18:33-05:00",
            sourceUrl = "https://www.wowhead.com/quest=8468#comments:id=137456",
        },
        {
            id = 413456,
            score = 8,
            author = "232592",
            text = "In easier terms if you don't have /wl loc / maplock:\n\nAs you are walking from \"Dawning Lane\" to \"Ruins of Silvermoon\", just take a left as soon as you walk into \"Ruins of Silvermoon\" (from DL) and walk towards the big building. You'll find \"Feths' Way\" which gives you exp and just look for the biggest building and Thaelis will be in the center of the 1st floor. Careful, he'll aggro / mobs will.",
            date = "2008-10-20T12:23:43-05:00",
            sourceUrl = "https://www.wowhead.com/quest=8468#comments:id=413456",
        },
        {
            id = 543907,
            score = 8,
            author = "295748",
            text = "When you are fighting Thaelis and the Wretched Urchins come with her, focus all your attack on her not the Wretched Urchins so if you kill her and then you die you will still have completed the quest.",
            date = "2009-01-03T01:09:51-06:00",
            sourceUrl = "https://www.wowhead.com/quest=8468#comments:id=543907",
        },
        {
            id = 256648,
            score = 7,
            author = "138902",
            text = "In the Ruins of Silvermoon, there is a big chapel-type building, he is in there, you may want to take out the enemies around him, or otherwise, you will aggro the other enemies around him.",
            date = "2008-03-20T21:41:12-05:00",
            sourceUrl = "https://www.wowhead.com/quest=8468#comments:id=256648",
        },
        {
            id = 279312,
            score = 7,
            author = "129488",
            text = "Yeah hes in the big building on the left when you first come in, i took him down fast and easy\nlvl 6 Blood Elf Hunter",
            date = "2008-04-29T15:30:02-05:00",
            sourceUrl = "https://www.wowhead.com/quest=8468#comments:id=279312",
        },
    },
