        {
            id = 103481,
            score = 4,
            author = "Aurora",
            text = "Arcane Patrollers can be found wandering throughout the Ruins of Silvermoon (usually along the side roads). Kill them to collect the six Arcane Cores. Be careful; they often join in combat with Wretched Urchins. A group of Urchins and a Patroller or two can really ruin a day!",
            date = "2007-06-13T04:54:51-05:00",
            sourceUrl = "https://www.wowhead.com/quest=8472#comments:id=103481",
        },
