    [8481] = {
        {
            id = 495,
            score = 70,
            author = "Tetris",
            text = "I did this quest the other day.  You will recieve the quest from Gore One Eye in the crossroad section of Timbermaw Hold.  He will send you to Winterspring where you will have to go to the Wintermaw village to the east of Everlook.  You will have to go to the top of the path where the Chief usually is.  Clear the area of Wintermaw, especially in the lower section so you can have room to fight with out interference.  You will have to place the torch in the cave entrance, and the demon will spawn down the hill from where you are standing.  He is a 62 Elite, and can see through stealth and emits a poison cloud that does 200-300 damage.  He is nearly impossible to solo mostly because his range attack will get you over time.  He can be stunned and rooted and has alot of hitpoints.  Did this with 2 rouges, 1 stunned and the other did most of the damage and switched agro so we could utilize evasion.  Good news is anyone can loot him once he is dead because he drops a chest similar to Araj that is lootable by everyone on the quest, whether they are in the group or not.",
            date = "2006-09-15T22:35:58-05:00",
            sourceUrl = "https://www.wowhead.com/quest=8481#comments:id=495",
        },
        {
            id = 984030,
            score = 30,
            author = "540613",
            text = "Killed 7 Alliance players by summoning him. I summoned him as a lvl 60 Orc Hunter, ran for my life, came back when the alliance players were all dead and just knocked off his final 2000 health. Then waited for the CD to finish before summoning him again and leaving. I'm so nice.",
            date = "2010-02-24T00:24:41-06:00",
            sourceUrl = "https://www.wowhead.com/quest=8481#comments:id=984030",
        },
