    [8488] = {
        {
            id = 1869549,
            score = 21,
            author = "Aeliren85",
            text = "I don't get it.\n\nMirverda says that the taint is irreversible. But the Plaguelands are being healed right now. Heck, if it were just me, I'd have the Western Plaguelands renamed to \"Darrowmere Forest\" or something similar - There's barely any sign of the plaguelands anymore! And the Eastern Plaguelands are in the process of being healed. Light's Hope and the five towers are full of healthy grass, and so is Tyr's Hand.\n\nSo if something as plagued (And plagued for so long) as the Plaguelands can be healed, who says the Dead Scar can't be healed as well?",
            date = "2013-06-22T22:22:37-05:00",
            sourceUrl = "https://www.wowhead.com/quest=8488#comments:id=1869549",
        },
        {
            id = 34423,
            score = 14,
            author = "Dith",
            text = "When doing this quest is best to step back a bit from her because there will be about 3-4 mobs coming from the direction of the undeads.\n\nIf you're standing to close they'll all start attacking you instead of her. Most of you will not be able to take the beating of all the mobs :)",
            date = "2007-02-12T01:52:45-06:00",
            sourceUrl = "https://www.wowhead.com/quest=8488#comments:id=34423",
        },
        {
            id = 110294,
            score = 10,
            author = "Nystedt",
            text = "Soloed as a level 8 Rogue, too easy quest, since if you talk to her, then stealth, then accept the quest they wont aggro. After a few seconds they will despawn and you will get \"Completed\" at the quest log.\n\nAnyway, im sure even a bad skilled player would complete this quest at level 8+ with any class, since its not hard.",
            date = "2007-06-24T10:48:02-05:00",
            sourceUrl = "https://www.wowhead.com/quest=8488#comments:id=110294",
        },
        {
            id = 42574,
            score = 9,
            author = "26608",
            text = "Easily completed this with my lvl 8 pally.  3mobs attacked ranging from lvl 7-9.  Surprisingly the NPC actually does a lot of the attacking, for a scientist she fights really well.  She killed one and I took the other two.  Very fun and easy.",
            date = "2007-02-26T07:08:58-06:00",
            sourceUrl = "https://www.wowhead.com/quest=8488#comments:id=42574",
        },
        {
            id = 44809,
            score = 6,
            author = "14000",
            text = "Solo'd on my Mage @ lvl 9. Just accept the quest stand back about 30 yards and attack them one at a time. NP! :)",
            date = "2007-03-01T22:16:37-06:00",
            sourceUrl = "https://www.wowhead.com/quest=8488#comments:id=44809",
        },
    },
    [8490] = {
        {
