            score = 6,
            author = "136874",
            text = "I had to kill about a dozen springpaws until I got my first pelt to drop.  I then got 4 pelts in a row and one every other kill after that.  My pelts only dropped from the Elder Springpaws although the quest suggests they will drop from any.  My suggestion is to just keep the quest in your log and kill any Springpaws while your traversing to and from other quest locations.  If you focus on just killing Springpaws you will get fustrated quickly.  I have done this quest with several characters now and the drop rate was terrible everytime.",
            date = "2008-03-13T13:52:56-05:00",
            sourceUrl = "https://www.wowhead.com/quest=8491#comments:id=252818",
        },
        {
            id = 256901,
            score = 3,
            author = "138902",
            text = "Go northeast of the quest-giver until you find the springpaws, the drop-rate is OK but not great. It might take a few kills until you get one.",
            date = "2008-03-21T09:43:45-05:00",
            sourceUrl = "https://www.wowhead.com/quest=8491#comments:id=256901",
        },
        {
            id = 42570,
            score = 2,
            author = "26608",
            text = "I had a low drop rate from the springpaw but almost a 100% drop from the elder springpaw",
            date = "2007-02-26T07:00:44-06:00",
            sourceUrl = "https://www.wowhead.com/quest=8491#comments:id=42570",
        },
    },
