    [8556] = {
        {
            id = 282238,
            score = 11,
            author = "Miyari",
            text = "This quest is available to warriors only and awards the ring piece of the Battlegear of Unyielding Strength (?itemset=495).\n\nBattlegear of Unyielding Strength\n\nHonored: Ring - Signet of Unyielding Strength (?item=21393) (quest (?quest=8556))\nRevered:  Cloak - Drape of Unyielding Strength (?item=21394) (quest (?quest=8557))\nExalted: Weapon - Sickle of Unyielding Strength (?item=21392) (quest (?quest=8558))\n\nThis quest requires the Qiraji Magisterial Ring (?item=20884), which can drop from any boss in the Ruins of Ahn'Qiraj (?zone=3429), as well as idols and scarabs which can either drop off trash or can be found inside Scarab Coffers (?object=180691).\n\nEven though it is obtainable at any reputation level, players must reach Honored with the Cenarion Circle (?faction=609) before being able to complete this quest.",
            date = "2008-05-04T12:47:14-05:00",
            sourceUrl = "https://www.wowhead.com/quest=8556#comments:id=282238",
        },
        {
            id = 2336891,
            score = 3,
            author = "Raggarns",
            text = "Now gives 500 rep for Cenarion Circle",
            date = "2016-06-04T03:11:38-05:00",
            sourceUrl = "https://www.wowhead.com/quest=8556#comments:id=2336891",
        },
    },
