    [8579] = {
        {
            id = 325933,
            score = 36,
            author = "mattous",
            text = "Completing this quest gives 500 reputation with the Brood of Nozdormu (http://www.wowhead.com/?faction=910) and the Cenarion Circle (http://www.wowhead.com/?faction=609).\n\nThe can be handed into one of the NPC's just up the stairs from the first boss in the Temple of Ahn'Qiraj (http://www.wowhead.com/?zone=3428); The Prophet Skeram (http://www.wowhead.com/?npc=15263).\n\nThe item required for completion drops off every boss in Temple of Ahn'Qiraj except the final boss C'Thun ( http://www.wowhead.com/?npc=15727).",
            date = "2008-07-13T20:18:38-05:00",
            sourceUrl = "https://www.wowhead.com/quest=8579#comments:id=325933",
        },
        {
            id = 530260,
