    [9076] = {
        {
            id = 248993,
            score = 6,
            author = "70100",
            text = "Could be a reference to Aldarion (Tar-Aldarion), the sixth king of Númenor. He was a great sailor and mariner and his romance with Erendis ended tragically, which could also referr to his 'wretched'-state. Although since the spelling isn't identical (like it's in other references) I could be wrong, which I probably am.\n\nAnyways that was a sidetrack, he is pretty hard to pull solo (tryed all BE classes) unless you're like level 10 and then it's still hard to pull just him since he got alot of adds, or atleast alot of mobs around him that also aggros if you pull him. But in return he doesn't seem to use any special abilities, just normal 'white' attacks.\n\nGl\nFortuna/Apotekarn of Genjuros",
            date = "2008-03-06T11:23:04-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9076#comments:id=248993",
        },
        {
            id = 66779,
            score = 5,
            author = "31730",
            text = "if you dont use coords...wretched ringleader done in sunsail anchorage, (south of the west santum island)in eversong woods. when i first got this quest i couldn't find how to get to the top floor of the big building because the ramp is kinda hidden, in case anyone else has that same problem: go up the little ramp at the south of the building marked by two red flags.  kill the few mobs inside the bottom floor then go thru the funny shaped doorway north of the entrance ramp.  then turn to your left (look for a tattered chest too!) and go up the other ramp there.  Follow the ramp on up, up, up and you will find the named mob you need to kill at the very top.  the guards can be pulled individually and the named mob is not tough to kill.  GL!\n~Angelsrage, blood elf priest, dragonblight server",
            date = "2007-04-13T17:43:22-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9076#comments:id=66779",
        },
        {
            id = 26408,
            score = 4,
            author = "pfilias",
            text = "Aldaron is at 33,70.\nVelendris is at 36,67.",
            date = "2007-01-28T13:40:57-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9076#comments:id=26408",
        },
        {
            id = 353777,
            score = 4,
            author = "Oznerol",
            text = "Indeed there were 2 thugs with Aldaron at the top of the tower. I was able to clear one, but the other was too close to pull separately. If you're a blood elf, just be sure to have 3/3 Mana Taps up to silence one of his Fireballs. Of course if you're a rogue or a mage, you won't have a problem with the 2nd add. Whereas for me being a warlock, I used a Minor Healing Potion just before Aldaron died.",
            date = "2008-08-15T14:15:18-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9076#comments:id=353777",
        },
        {
            id = 354081,
            score = 4,
            author = "194016",
            text = "soloed as a lvl 10 lock, if you dont have coords he is on the 3rd story of the building, i almost missed the ramp myself, just go out onto the balcony on the second teir and turn around, you will see it.  Wasnt able to pull one alone, al came with him, but with my imp and shadow bolt i was able to take em both out without dying.",
            date = "2008-08-15T22:27:39-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9076#comments:id=354081",
        },
    },
    [9119] = {
        {
            id = 249998,
            score = 16,
            author = "111622",
            text = "Go here (http://www.wowhead.com/?npc=15401)",
            date = "2008-03-08T05:34:28-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9119#comments:id=249998",
        },
        {
            id = 242500,
            score = 9,
            author = "105800",
            text = "About this time in the game you who are new are wondering where people are getting their cords.  It is a download from Curse.com called  Cartiographer (http://wow.curse.com/downloads/details/4947/).  It will change your in game map so it displays cords.\n\nIf you would rather use a macro instead of downloading here it is, just copy and paste into macos in game:\n\n/script px,py=GetPlayerMapPosition(\"player\")\n/script DEFAULT_CHAT_FRAME:AddMessage(format(\"( %s ) %i,%i\",GetZoneText(),px *100,py *100));",
            date = "2008-02-24T08:31:39-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9119#comments:id=242500",
        },
        {
            id = 84882,
            score = 3,
            author = "33173",
            text = "There's an outer balcony on the second floor with wraiths and a chest on it but no visible way up.  Anyone have any idea how to get up there?  Some teleport trick somewhere?",
            date = "2007-05-18T01:17:37-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9119#comments:id=84882",
        },
        {
            id = 120780,
            score = 3,
            author = "62450",
            text = "How do you get up there? I have tried every way I could think of nor can I find a teleport crystal. Last time I made a blood elf there was a mob up there  but I thought it might be a bug after BC came out. This time there were 2 mobs and  a CHEST so there must be a way somewhere.",
            date = "2007-07-14T22:37:13-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9119#comments:id=120780",
        },
        {
            id = 176649,
            score = 3,
