    [9139] = {
        {
            id = 21859,
            score = 25,
            author = "13096",
            text = "You can find these mobs in Goldenmist Village (27, 17).\n\nThe Ghosts/Wraiths become \"intangible\" at around 50-40% - very similar to a Rogue's \"Evasion\" skill - for about 15 seconds. You can still kill them with spells (Judgement of Righteousness, for example).\n\nThis quest leads to \"Windrunner Village.\"",
            date = "2007-01-20T02:06:25-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9139#comments:id=21859",
        },
        {
            id = 291393,
            score = 20,
            author = "Verydarklord",
            text = "By the way, anyone noticed that ghosts in this village using old (pre-BC) high elf models? Kinda strange, isnt it?",
            date = "2008-05-20T06:18:48-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9139#comments:id=291393",
        },
