            text = "this quest is also in the area http://www.wowhead.com/?quest=9160",
            date = "2007-04-04T23:19:16-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9139#comments:id=62261",
        },
        {
            id = 821750,
            score = 6,
            author = "390657",
            text = "Be careful standing on the tower walkway at 26.45, 15.60.  It can bring you within the aggro range of mob wandering under the bridge, and they will be able to hit you.  If you move up the walkway it will take you outside of their range forcing them to run up there after you, thereby pulling each and every mob along their path.\n\nI found this out coming down from the top level of the tower after clearing the ground level earlier, and was able to reproduce this twice (once on purpose) and at one point had 6 mobs on me at the same time.",
            date = "2009-08-24T19:28:16-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9139#comments:id=821750",
        },
    },
