    [9152] = {
        {
            id = 21478,
            score = 44,
            author = "5097",
            text = "Crate is located at 33,26. It's surrounded by some mobs ranging from 10-12 You probably have to kill 4-5 to get to the car where the crate is",
            date = "2007-01-18T20:18:46-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9152#comments:id=21478",
        },
        {
            id = 226935,
            score = 24,
            author = "76394",
            text = "No one has mentioned that completing this quest allows you to buy stuff from him? ><\n\nThat´s the important part!",
            date = "2008-01-30T14:34:04-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9152#comments:id=226935",
        },
        {
            id = 178411,
            score = 15,
            author = "95798",
            text = "Just take the road leading west from Tranq. You can't miss it.\n\nDo this quest in conjunction with Goldenmist vollage (http://www.wowhead.com/?quest=9139), Salvaging the Past (http://www.wowhead.com/?quest=9150), and Investigate An'daroth (http://www.wowhead.com/?quest=9160), as they're all within the same area.\n\nThe spiders in the area also drop the quest items for Culinary Crunch (http://www.wowhead.com/?quest=9171).\n\nAll together this run is a nice big fat chunk of xp.",
            date = "2007-11-03T04:03:43-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9152#comments:id=178411",
        },
        {
            id = 266430,
            score = 8,
            author = "107365",
            text = "As a little side note, 'Tomber' is the French verb meaning \"To fall\".",
            date = "2008-04-04T17:45:24-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9152#comments:id=266430",
        },
        {
            id = 163705,
            score = 6,
            author = "84244",
            text = "33.26 are the correct coord's.\n\nNot far from the fork in the road that leads to the Sanctum of the Moon, a bit in from the trail is a large tree and near the tree is a wagon. The supplies are on the back of the wagon cart.\n\nThe wagon blends in, so may be hard to spot right off the bat.  A few Gangled  Flesheater's and Spindleweb spider mobs are near. Kill what you need, click on the supplies.",
            date = "2007-10-06T10:59:14-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9152#comments:id=163705",
        },
    },
    [9155] = {
        {
            id = 21524,
            score = 15,
            author = "9582",
            text = "These mobs are south of the road going west out of Tranquillien in the Dead Scar. They'll start at about 40,28 - all the way down too 39,39 and beyond.",
            date = "2007-01-18T23:17:09-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9155#comments:id=21524",
        },
        {
            id = 466012,
            score = 4,
            author = "241164",
            text = "Watch out for Luzran (http://www.wowhead.com/?npc=16245) as you are doing this quest. I saw him coming in time fortunately (level 13 rogue).",
            date = "2008-11-23T22:15:39-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9155#comments:id=466012",
        },
        {
            id = 1065602,
            score = 3,
            author = "526868",
            text = "Counts towards the Loremaster of Eastern Kingdoms (http://www.wowhead.com/?achievement=1677) achievement.",
            date = "2010-06-25T01:01:36-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9155#comments:id=1065602",
        },
        {
            id = 614549,
            score = 2,
            author = "purko87",
            text = "http://www.wowhead.com/?maps=3433:401281391390400304400322391335386355386368397357",
            date = "2009-02-18T15:25:43-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9155#comments:id=614549",
        },
        {
            id = 1915445,
            score = 1,
            author = "louied777",
            text = "This quest is naught but fodder for a geared BoA character - most can clear this quest in less than 3 minutes if they are geared. However, if you're making a trial account char, or have a hankering to level the \"old way,\" the greys and white gear will possibly make this tricky.\n\nWhen I first started WoW and when I just recently leveled a Trial Acct. alt, I would stay along the easternmost edge of the Dead Scar (around the \"T\" in Tranquilien on the map). From here, tag your targets and let them come to you - the https://www.wowhead.com/npc=16301 hit pretty hard; you don't want to pull 2-3 of any mobs here, if you're undergeared.\n\nStanding to the side like this means you can pull 1 at a time if you're taking a lot of damage or are newer, and 2+ mobs at a time if you feel as though you're doing okay. Also, all the mobs for this quest both drop a fair amount of https://www.wowhead.com/item=4605 and https://www.wowhead.com/item=1179, so if you're getting hurt a bunch, you will have some munchies to heal you up between :]\n\nLastly, the biggest advantage to pulling mobs here are the patrols: https://www.wowhead.com/npc=16245 and https://www.wowhead.com/npc=16311. Luzran (obviously) will annihilate any low level character with poor gear, but you may not see him very often. The Watchers, however, move fast and are a little higher in level. They will move in oblong patrol paths along the edges of the Dead Scar...where you are. If you see one coming, wait to pull it until it is close to you and it is far from other mobs. If it sees you or you pull it by other mobs, it will bring them with it!\nIf you see Luzran lumbering towards you, RUN. RUN FAST up the hill by Tranquilien until he passes.\n\nAnd if you die? Don't worry too much, the graveyard is only about 15 seconds walk away! :]",
            date = "2013-11-06T16:14:16-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9155#comments:id=1915445",
        },
    },
    [9156] = {
        {
            id = 129094,
            score = 78,
            author = "14000",
            text = "Knucklerot spawns at \"The Howling Ziggurat\" @ aprox. 40.5,46.1\nHe then paths West along the road to \"Windrunner Village\" then heads across the river to the road and makes his way to \"Goldenmist Village\".\nHe then turns around and backtracks along this path.\n\nAs of this writing once he is killed he respawns quite quickly. Hybrid classes(Paladin, Shaman, Druid) should be able to solo him @ lvl 20. Other classes will want to have a healer handy.\n\nAbilities noticed during the fight were a stun at which point he turns and attacks the second person on the agro list.\n\nLuzran spawns at \"The Bleeding Ziggurat\" @ aprox. 34,50\nHe then paths South to North in the scar walking back and forth.\n\nAs of this writing once he is killed he respawns quite quickly. Hybrid classes(Paladin, Shaman, Druid) should be able to solo him @ lvl 20. Other classes will want to have a healer handy.\n\nAbilities noticed during the fight were a knockback.",
            date = "2007-07-30T08:18:18-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9156#comments:id=129094",
        },
        {
            id = 21590,
            score = 20,
            author = "Echo",
            text = "Luzran patrols the Dead Scar between the road and Deatholme - he's easy to spot.\n\nKnucklerot is tougher to track down. He patrols the road in a large circle around Sanctum of the Sun, and also makes frequent detours to Goldenmist Village and Windrunner Village.\n\nDid both of them without any big trouble with a 19 rogue and 19 paladin.",
            date = "2007-01-19T14:30:05-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9156#comments:id=21590",
        },
        {
            id = 21703,
            score = 16,
            author = "8277",
            text = "Luzran spawns at the top of the stairs of the Bleeding Ziggurat.\n\nKnucklerot spawns at the top of the stairs of the Howling Ziggurat.",
            date = "2007-01-19T17:56:36-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9156#comments:id=21703",
        },
        {
            id = 169224,
            score = 11,
            author = "92549",
            text = "Luzan will occasionally \"punt\" the player far (50 yards +), the either attack the second person attacking him, or chase after the \"puntee\"\nBeware that if you are punted, you might get agro from a creature you landed next to. This is no big deal if you are in a group, but solo, you might wanna run depending on your level.",
            date = "2007-10-15T16:22:22-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9156#comments:id=169224",
        },
        {
            id = 840165,
            score = 5,
            author = "430926",
            text = "Pretty easy to solo on a lvl 20 demonology lock.  Send in Voidwalker, dot em up, health funnel as needed, rinse and repeat.  If you run low on health throw in a Drain Life as needed.",
            date = "2009-09-14T13:10:47-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9156#comments:id=840165",
        },
    },
