    [9167] = {
        {
            id = 3848,
            score = 68,
            author = "JackOnTheMap",
            text = "He's got an AoE fear and adds. Don't bother trying to solo.\n\nRemember to use your AoE silence racial when you see him casting it. Just try to remind everyone not to use all of them at once. Keep him from fearing and you'll be fine.\n\nHe's in the building in the middle way down in the basement.",
            date = "2006-11-18T13:22:45-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9167#comments:id=3848",
        },
        {
            id = 1085939,
            score = 37,
            author = "435011",
            text = "If you are a higher level doing it for rep, offer your help on general channel, as you can ease someone's trouble. Did it today, helped a company of three. It's good to be nice to people, isn't it?",
            date = "2010-07-21T15:18:51-05:00",
