        {
            id = 48093,
            score = 11,
            author = "Skulver",
            text = "Nice rewards but like all world quests that require a group it can be an absolute pain to get a group for. It was fine just after release but now you can spend a lot of time just waiting around for someone who needs the quest to log on. One of those awful decisions, skip it and don't get the rewards for all the work so far, wait around for an hour or two and hope someone shows up or waste an hour coming back later and hope someone is around.",
            date = "2007-03-08T07:18:49-06:00",
