    },
    [9169] = {
        {
            id = 20800,
            score = 76,
            author = "Teer",
            text = "I had some trouble with this quest as it didn't tell the location of An'owyn, but it is right south of where you pickup the quest. Crystal Controlling Orb (?item=23191) drops from the Sentinel Infiltrators (?npc=16333) that guard the crystal, it took me around 15 kills to get it.",
            date = "2007-01-16T10:24:31-06:00",
