    [9170] = {
        {
            id = 22876,
            score = 48,
            author = "13011",
            text = "Coordinates:\n\nMidoran The Fallen: 37, 79\nJurion: 32, 74\nBorgoth: 32, 89 or 40, 83\nMasophet: 29, 89 or 35, 88",
            date = "2007-01-22T16:27:01-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9170#comments:id=22876",
        },
        {
            id = 27658,
            score = 41,
            author = "17264",
            text = "\"When you first enter Deatholme, stick left.\n\n1) Mirdoran the Fallen is in the center of the Gazebo (first building on your left) 37,34\n\n2) Borgoth the Bloodletter is just South of there in the Slaughter House located at the top of the hill: 32, 89\n\n3) Continue to follow around in a clockwise circle. Masophet the Black is in the center of the Ziggurat in the SE corner. 29,88\n\n4) Finaly, just to the west of the entrence is a crypt. Jurion the Deceiver is in the basement. 32, 73\n\nHope that helps.\"\n\nThanks to Bouhb.",
            date = "2007-01-30T10:27:59-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9170#comments:id=27658",
        },
        {
            id = 23343,
            score = 38,
            author = "14658",
            text = "Don't spend too much time waiting for borgoth or masophet to respawn from where it was last killed. They alternate in locations so make sure to check them both.",
            date = "2007-01-23T15:22:21-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9170#comments:id=23343",
        },
        {
            id = 41582,
            score = 30,
            author = "1184",
            text = "Make sure you have the quest Captives of Deatholme (http://www.wowhead.com/?quest=9164) before heading in since the objectives' locations overlap.",
            date = "2007-02-24T12:49:06-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9170#comments:id=41582",
        },
        {
            id = 3242105,
            score = 29,
            author = "Kazi12",
            text = "If you're looking to do this quest for Transmog and you haven't done Ghostlands at ALL: here's the minimum of what you need to do:\n\n The Forsaken (https://www.wowhead.com/quest=9329/the-forsaken)\n Return to Arcanist Vandril (https://www.wowhead.com/quest=9758/return-to-arcanist-vandril)\n Suncrown Village (https://www.wowhead.com/quest=9138/suncrown-village)\nSalvaging the Past (https://www.wowhead.com/quest=9150/salvaging-the-past)\n Goldenmist Village (https://www.wowhead.com/quest=9139/goldenmist-village)\n Windrunner Village (https://www.wowhead.com/quest=9140/windrunner-village)\n\nThis unlocks  The Sanctum of the Sun (https://www.wowhead.com/quest=9151/the-sanctum-of-the-sun). (When you hand it in, expect to hear the low \"error noise\" chime.)\n\nGo upstairs and pick up The Farstrider Enclave (https://www.wowhead.com/quest=9282/the-farstrider-enclave), there you'll learn about  The Traitor's Shadow (https://www.wowhead.com/quest=9161/the-traitors-shadow), which leads you to a book to the north. The book reveals Hints of the Past (https://www.wowhead.com/quest=9162/hints-of-the-past). Bring it back to the enclave and you will be instructed to  Report to Magister Kaendris (https://www.wowhead.com/quest=9172/report-to-magister-kaendris). After that, you can complete  The Twin Ziggurats. (https://www.wowhead.com/quest=9176/the-twin-ziggurats)\n\nThis unlocks Dar'Khan's Lieutenants (https://www.wowhead.com/quest=9170/darkhans-lieutenants) and  The Traitor's Destruction (https://www.wowhead.com/quest=9167/the-traitors-destruction), which offer the cosmetic rewards  you're looking for.",
            date = "2020-10-25T04:26:43-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9170#comments:id=3242105",
        },
    },
    [9171] = {
        {
            id = 238697,
            score = 29,
            author = "27402",
            text = "I spoke with a GM regarding this quest and why Undead couldn't see it.  Apparently as a Blood elf you would have done this other quest that basically \"Unlocks\" this quest from being available so follow the requirements here:\n\nYour reputation must be Friendly or above with Tranquillien, and you must have completed - the Pre-Requisite if you will is \"The Forsaken\"  (http://www.wowhead.com/?quest=9327)  from  Arcanist Vandril (http://www.wowhead.com/?npc=16197), he will then want you to talk with High Executor Mavren (http://www.wowhead.com/?npc=16252) who is about 30 yards away, then return.  This quest chain when complete will do the needful, which unlocks this quest (Culinary Crunch).  I just confirmed it and completed the quest gaining my recipe for cooking (As an Undead Rogue).\n\nEnjoy Ladies...",
            date = "2008-02-18T12:11:23-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9171#comments:id=238697",
        },
        {
            id = 45183,
            score = 22,
            author = "pezz",
            text = "You can get them from the lower level spiders (or just buy them if you feel lazy) as well, but I don't know if the drop rate is as good. The lurkers (the recommended spiders) start at around 34,38 if you come at them from Tranquillen.",
            date = "2007-03-02T14:04:36-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9171#comments:id=45183",
        },
        {
            id = 575722,
            score = 15,
            author = "FarseerLolotea",
            text = "As Crazyville stated, you have to be friendly with Tranquilien (http://www.wowhead.com/?faction=922) and have completed the short quest chain starting here (http://www.wowhead.com/?quest=9327) for this to become available.  Completing Suncrown Village (http://www.wowhead.com/?quest=9138) and either Anok'suten (http://www.wowhead.com/?quest=9315) or Tomber's Supplies (http://www.wowhead.com/?quest=9152) should get you the necessary rep.\n\nAnd for anyone doing this quest on an alt:  Crunchy Spider Legs drop from quite a long list of mobs (http://www.wowhead.com/?item=22644#dropped-by:0-9+2+1).",
            date = "2009-01-23T03:16:53-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9171#comments:id=575722",
        },
        {
            id = 126955,
            score = 11,
            author = "66800",
            text = "around 33, 22 thats a good spot the mobs are level 11 and it has a good drop rate took me about 3 mins to get the legs",
            date = "2007-07-26T03:17:33-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9171#comments:id=126955",
        },
        {
