    [9173] = {
        {
            id = 3846,
            score = 21,
            author = "JackOnTheMap",
            text = "The Spire can be found at 12, 55.",
            date = "2006-11-18T13:11:27-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9173#comments:id=3846",
        },
        {
            id = 94522,
            score = 13,
            author = "Dissonance",
            text = "The Fallen Rangers have a spell called \"Banshee Wail\" that they spam over and over.  As a 17 BE Priest, the lvl15 Fallen Rangers were doing about 40 damage per-cast, which was about on par with lvl17-18 melee mobs at this time.\n\nI can endlessly grind against mobs my level, but these guys do entirely too much damage for their level.  Then again, it's not insane, so let's just say they're not the best grinding mobs.\n\nOn another note, this quest was (for the most part) easily soloed.  These Acoltes were not immune to fear effects, yet the Rangers were.  Keep in mind these mobs also have a chance to drop a quest-starting item called [The Lady's Necklace] (http://www.wowhead.com/?item=22597), which is basically a \"Take this item to this guy and get some experience\" quest. (http://www.wowhead.com/?quest=9175)  Worth killing a few extra guys if it hasn't dropped for you by the time you're done with this quest.\n\nLevel 17, Blood Elf Priest",
            date = "2007-05-31T06:19:38-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9173#comments:id=94522",
        },
        {
            id = 49217,
            score = 10,
            author = "27357",
            text = "Location confirmed, started this with Windrunner Village as well, just follow the road from Tranquillien 17, 59 is the first mob.",
            date = "2007-03-10T16:19:23-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9173#comments:id=49217",
        },
        {
            id = 70687,
            score = 8,
            author = "Ruben",
            text = "Kind of hard quest, easy to get adds up in the spire.. Be carefull :)",
            date = "2007-04-21T21:05:29-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9173#comments:id=70687",
        },
        {
            id = 262914,
            score = 6,
            author = "childofnewlight",
            text = "Requires level 15...but these Fallen Rangers are ridiculous. I had a tough time on my rogue and I'm having an equally tough time (if not worse) on my paladin. Bubble. Torrent. Bandage. Potion. Scrolls. Ugh. Better to be left until 17 or 18 unless you are a pet class and have good control of it.",
            date = "2008-03-29T22:14:53-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9173#comments:id=262914",
        },
    },
    [9174] = {
        {
            id = 44681,
            score = 19,
            author = "25921",
