    [9176] = {
        {
            id = 22450,
            score = 34,
            author = "13731",
            text = "Stone of Flame @ (40, 49)\nStone of Sun @ (34, 47)\n\nThe ziggurats are southwest of Tranquillien. Both stones are inside the ziggurats, within a black chest in the center. Be prepared to fight two or more level 17-18 casters.\n\nI was able to solo as a 17 paladin. I used mana tap and line of sight to pull.\n\nThe Traitor's Shadow (http://www.wowhead.com/?quest=9161) precedes this and The Traitor's Destruction (http://www.wowhead.com/?quest=9167) follows.",
            date = "2007-01-21T15:24:20-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9176#comments:id=22450",
        },
        {
            id = 32656,
            score = 19,
            author = "19244",
            text = "I am just clearing up what the above poster said as \"line of sight to pull\".\n\nBy that he means to stand at the top of the stairs and agro one of the mobs, then back up so they have to run to the top of the stairs. Then attack them there.\nBeware, they will try and run away once you get their life low enough.\n\nThe stairs splits to the left and right. There is a caster at the bottom of each set of stairs, a third caster in the middle of the room on the far side and fourth caster right by the chest. (he's right behind the wall at the top of the stairs)",
            date = "2007-02-08T10:22:07-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9176#comments:id=32656",
        },
        {
            id = 83653,
            score = 14,
            author = "g0jack",
            text = "Beware, as I ran into a level 18 rare spawn called Dr. Witherlimb. He destroyed me :D",
            date = "2007-05-15T19:31:25-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9176#comments:id=83653",
        },
        {
            id = 227180,
            score = 5,
            author = "Josieftw",
            text = "Goethe has good coord.. so I wont repost, but I got an easier way to do it.\n\nFirst, you will have to agro a caster on either side ( only 1 side.. you may choose which one it does not matter ).\n\nSecond, walk very slowly to the side of the chest without going down the path and move your camera around so you can open the chest.\n\n(Here is a screenshot of me opening, the quality is pretty much crappy.. but you get the idea http://i53.photobucket.com/albums/g78/Selee0/hehe.jpg )",
            date = "2008-01-31T01:48:40-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9176#comments:id=227180",
        },
        {
            id = 267360,
            score = 5,
            author = "143126",
            text = "Try to kill the Stonewing Trackers outside if thats where you're going to pull the casters.",
            date = "2008-04-06T11:39:41-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9176#comments:id=267360",
        },
    },
