    [9193] = {
        {
            id = 20850,
            score = 48,
            author = "peeweesweden",
            text = "Also, note that you are supposed to burn UNANIMATED remains, not the mummified trolls you've clubbed down. You'll find them inside the ruins, neatly wrapped up, awaiting the torch.",
            date = "2007-01-16T16:38:12-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9193#comments:id=20850",
        },
        {
            id = 21934,
            score = 35,
            author = "13297",
            text = "58, 28 are the co-ord's.",
            date = "2007-01-20T05:44:01-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9193#comments:id=21934",
        },
        {
            id = 3847,
            score = 31,
            author = "JackOnTheMap",
            text = "Just to the west of Farstrider Enclave. There are two entrances but this one is the more direct to the quest objective. Make sure you visit the round room in the middle to get the \"objective\" part.",
            date = "2006-11-18T13:19:10-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9193#comments:id=3847",
        },
        {
            id = 2549624,
            score = 22,
            author = "MGoblin256",
            text = "As of 7.3.5, this quest seems to have been moved from Tranquilien to the Farstrider Enclave, and is now given out by https://www.wowhead.com/npc=16203. Likewise, the quest https://www.wowhead.com/quest=9199 is now given out by https://www.wowhead.com/npc=16464 at Farstrider Enclave as well. A good move on Blizzard's part, IMHO.",
            date = "2018-01-31T14:39:32-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9193#comments:id=2549624",
        },
        {
            id = 21158,
            score = 19,
            author = "wolf",
            text = "The Amani Catacombs - when looking on your map - is located in the left cave within the mountains, north of Sanctum of the Sun, east of Traquillien, west of Eastrider Enclave, and south of Suncrown Village. The mummies are interactable objects on the ground near the walls. Get to the circular shaped room for the investigation objective, and in the back of the room is a cage with a Blood Elf waiting with an escort quest.",
            date = "2007-01-17T20:54:14-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9193#comments:id=21158",
        },
    },
    [9199] = {
        {
            id = 41499,
            score = 19,
            author = "6221",
            text = "Confirmed: They drop off the trolls at the Amani Catacombs (Entrance: 57, 27).\n\n50% (approx) Drop Rate.\n\nPer the previous poster, I did this quest whilst completing:\nInvestigate the Amani Catacombs (http://www.wowhead.com/?quest=9193)",
            date = "2007-02-24T09:16:14-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9199#comments:id=41499",
        },
        {
            id = 20925,
            score = 12,
            author = "rsanders",
            text = "You can get them off the mobs found in Amani Catacombs. I assume other mobs drop them, but  I done this quest while I was doing the Investigate the Amani Catacombs quest.\n\nAlso, dont forget to pick up the Escape from the Catacombs quest from the Blood Elf inside the cage in the \"circle room\"",
            date = "2007-01-17T00:36:07-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9199#comments:id=20925",
        },
        {
            id = 2547090,
            score = 12,
            author = "Arbeter",
            text = "You now take this quest from Apothecary Venustus in Farstrider Enclave Ghostlands same with the Quest Investigate the Amani Catacombs wich you take from Ranger Vynna.",
            date = "2018-01-19T17:12:11-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9199#comments:id=2547090",
        },
        {
            id = 592298,
            score = 11,
            author = "107365",
            text = "Fast respawns, AoE-on-death mobs, frequent patrols and close-pulls make this quest a bit tricky.  Pair it with Investigate the Amani Catacombs, (http://www.wowhead.com/?quest=9193) since they're both in the same spot. While you're in there, you should do Escape from the Catacombs,  (http://www.wowhead.com/?quest=9212)if you can. Go as fast as you can, and move away from Mummified Headhunters as they die- they put out an AoE poison cloud called Cloud of Disease.  Headhunters don't run away in fear, but the Amani Oracles do, and this could pull more mobs if you dont kill them quickly.",
            date = "2009-02-02T10:56:16-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9199#comments:id=592298",
        },
        {
            id = 482354,
            score = 10,
            author = "223216",
            text = "Above poster is right, wowhead info is wrong. The quest gives no Tranquilien nor any other rep. So for u grinding Tranquilien rep on ur twinks and avoiding exp, ignore this quest.",
            date = "2008-12-01T09:53:35-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9199#comments:id=482354",
        },
    },
    [9207] = {
        {
            id = 137429,
            score = 17,
            author = "TheOnyx",
            text = "Consider doing this quest in tandem with Trouble at the Underlight Mines (http://www.wowhead.com/?quest=9192), especially if you are not a miner. The mobs you have to kill to get the ore are the same mobs you need to kill for the linked quest.",
            date = "2007-08-13T21:37:42-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9207#comments:id=137429",
        },
        {
            id = 38312,
            score = 7,
            author = "19957",
            text = "you do this by killing the guys at the Underlight mines, (29,47)\nthe drop rate is a huge pain.  if your lucky you will get them quick\nthey also aggro realy easily and they are in packs.\ntry to have a group for this quest otherwise youll find yourself dying quite often",
            date = "2007-02-18T18:32:45-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9207#comments:id=38312",
        },
        {
