    [9212] = {
        {
            id = 243892,
            score = 26,
            author = "86508",
            text = "One of the more aggravating quests.  Come in the backside of the catacombs (northside close to Farstrider Retreat).  Be sure to clear all of the trolls down the hall, in the antechamber on the left, and in the main room.  Once she opens the cage, just move a little ahead of her in case of respawns, and these trolls respawn fairly quickly.  What makes this quest aggravating (like all escort quests) is she walks very slowly.  If a troll respawns along the path, she will run up to help you fight it, then run back to where she was when you entered combat.  Once you get outside, 2 trolls spawn to attack you, take care of them quickly and stay with her as she finally runs to Farstrider Retreat.  If you stray to far away from her, you can fail the quest.\n\nThe mobs are level 16-17, not too tough except for the Amani type trolls that will run when you get them close to death, aggroing any mobs around them you haven't already cleared.",
            date = "2008-02-26T13:07:15-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9212#comments:id=243892",
        },
        {
            id = 31998,
            score = 22,
            author = "17844",
            text = "you don't need to pick the lock, if she doesn't get up and open it herself, drop the quest and pick it up again and it should work, happened to me in a group\n\nshe's in the big circular room that triggers the \"investigate the amani catacombs\" from the other quest, fairly easy to do as long as you can handle the adds, done it solo and with another now",
            date = "2007-02-07T01:53:37-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9212#comments:id=31998",
        },
        {
            id = 306293,
            score = 17,
            author = "156120",
            text = "Since after each fight, her hp heals itself, I casted blessing on might on her and let her solo the quest. :D\n\nWatch out she doesn't take on two mobs though, then you'll have to intervene. :P\n\nDon't expect much xp or loot, but still it's pretty funny to watch.",
            date = "2008-06-17T07:17:08-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9212#comments:id=306293",
        },
        {
            id = 2301588,
            score = 15,
            author = "Gershuun",
            text = "If someone else is on the quest, the cage will appear empty. Just wait there until whoever is done finishes, and she will respawn.",
            date = "2016-01-25T18:56:21-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9212#comments:id=2301588",
        },
        {
            id = 218238,
            score = 14,
            author = "pat728uk",
            text = "I just did this, she walked into farstrider retreat and it failed! I can only assume it was because i was not close enough to her when she walked in, so stay close!",
            date = "2008-01-14T16:13:18-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9212#comments:id=218238",
        },
    },
    [9214] = {
        {
            id = 111346,
            score = 20,
            author = "5027",
            text = "Do this quest along with Attack on Zeb'Tela (http://www.wowhead.com/?quest=9276) and its follow up Assault on Zeb'Nowa (http://www.wowhead.com/?quest=9277). They require you to kill the same mobs.",
            date = "2007-06-26T14:54:16-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9214#comments:id=111346",
