            author = "98756",
            text = "They have a very low drop rate it took me forever to get all of them. Outside Deatholme, just south of it in the Dead Scar is a nice place to grind them this quest is good with Spinal Dust because they are at the same place as the mobs for Rotting Hearts, easily done with a level 16-18 hunter.",
            date = "2007-11-17T04:53:30-06:00",
