    [9217] = {
        {
            id = 100953,
            score = 15,
            author = "60275",
            text = "It's worth menioning that it is possible to get to exalted status with Tranquillien without doing this repeatable quest even once. There is more than enough reputation from all the other quests in that area.",
            date = "2007-06-08T19:09:32-05:00",
