        },
        {
            id = 123852,
            score = 7,
            author = "65960",
            text = "Only repeat this and the More Spinal Dust quest if you really need the potions. You get more from the vendor for the rotting hearts and the spinal dust than you get for the potions. I think it's a 3s difference, so if you're going to grind for these, just sell them.",
            date = "2007-07-20T10:23:05-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9217#comments:id=123852",
        },
        {
            id = 1865696,
            score = 6,
            author = "1128270",
            text = "Just to add an update (it has been several years since anyone has posted here.)\n\nYou should definitely get Exalted with Tranquillien long before having to repeat this quest.  The quest for killing Dar'khar awards 8,000 rep points by itself.\n\nI would say that if you focus on finishing 50 quest achievement for this zone you will end up with the rep you need.",
            date = "2013-06-12T11:21:05-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9217#comments:id=1865696",
        },
