        {
            id = 165838,
            score = 20,
            author = "Wezagred",
            text = "This quest is for people who have farmed (or tryied) Bloodsail Buccanears reputation. As you kill the guards in Booty bay, you also lose rep at the other steamwheedle factions, and Blizzard made some Friendly NPC's without factions outside each of Steamwheedle place, where you can do hand ins of cloths etc.\nAs you hand in, you get 500 rep with Gadgetzan, but lose 500 rep with Bloodsail, so only do this if you've given up, or already got the clothings of Bloodsail.",
            date = "2007-10-11T04:17:26-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9268#comments:id=165838",
        },
    },
    [9272] = {
        {
            id = 5547913,
            score = 33,
            author = "Eddafred",
            text = "If you're like me and completed this quest back before the rewards became learnable cosmetics, submit a ticket to have the quest reward restored.\nWaiting a couple days for a response from a GM definitely beats having to grind out Bloodsail rep on another character.\n\n[Screenshot] (https://i.imgur.com/oKAg4Gt.png)",
            date = "2023-02-10T10:43:28-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9272#comments:id=5547913",
        },
        {
            id = 217483,
            score = 20,
            author = "Cuphat",
            text = "0/36000 hated with all goblin factions, 0/3000 neutral with Bloodsail, and unable to receive this quest.\n\nEDIT: Able to pick it up at 791/3000 neutral, so I assume it just requires more than 0/3000.",
            date = "2008-01-12T22:43:05-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9272#comments:id=217483",
        },
        {
            id = 68323,
            score = 18,
            author = "29438",
            text = "Hated - 1,440 Booty Bay Bruiser\nHostile - 120 Booty Bay Bruiser\nUnfriendly   -      120 Booty Bay Bruiser\nNeutral - 120 Booty Bay Bruiser\nFriendly - 420 Booty Bay Bruiser",
            date = "2007-04-16T19:22:02-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9272#comments:id=68323",
        },
        {
            id = 1668600,
            score = 17,
            author = "Etreum",
            text = "If you are phased in to the Brashtide Invasion , Fleet Master Firallon and or The Crimson Veil will still appear at their old location but will phase out when you get there.  Go instead to 35,8 - 66.7 right by the island off Booty Bay and you will get the quest.",
            date = "2012-05-19T10:33:47-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9272#comments:id=1668600",
        },
        {
            id = 3180203,
            score = 15,
            author = "LaffiBoozegnome",
            text = "Here is how you do all 3 quests for Bloodsail Buccaneers:\n\n-Get to friendly with Bloodsail Buccaneers, by killing guards in Booty Bay.\n-Get to hated with Booty Bay\n\nGo to \"Good-Boy\" Bruce at\n\n/way 41.6 61.2 \"Good-Boy\" Bruce\n\nand take the quest \"Avast Ye, Scallywag\". Avast Ye, Scallywag will lead you to the next quest to Fleet Master Firallon at\n\n/way 46.6 95.2 Fleet Master Firallon\n\nHe will then offer you two quests:\n-Avast Ye, Admiral  <-- Completing this before Avast Ye, Scallywag will make you unable to take it after.\n-Dressing the Part\n\nThese are the 3 quests available to Bloodsail Buccaneers.",
            date = "2020-01-06T09:38:16-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9272#comments:id=3180203",
        },
    },
    [9274] = {
        {
            id = 22579,
            score = 10,
            author = "12560",
            text = "There is a small island at 72, 20.  In the waters to the South East (73,22) there are three wrecked boats on the lake floor. Most of the spirits are around these boats but a few wander in the waters all around the island.",
            date = "2007-01-21T22:13:27-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9274#comments:id=22579",
        },
        {
            id = 116744,
            score = 10,
            author = "52261",
            text = "Can be done effectively with http://www.wowhead.com/?quest=9157",
            date = "2007-07-07T00:09:54-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9274#comments:id=116744",
        },
        {
            id = 356594,
            score = 3,
            author = "193663",
            text = "These are Blood Elves who were betrayed by their beloved water spirit and now haunt span of Lake Eldrendar because of it. They are very weak mobs with no real surprise abilities. Just a normal speed, physical attack. The only tricky thing with these mobs is that they are found in the deepest part of the lake around the island with the quest giver on it. This makes attacking them a little frustrating.\n\nMy advice is to pull them to the surface where you can fight and breathe, instead of swimming all the way down, killing one, coming back up. Its quicker. Those of you who don't have a bow or something to pull with, you can always ask a local warlock to give you underwater breathing. You can get most, if not, all of it done in the 10 minutes of breathe that you have. Also, in the southern part of the riverbed, there are some apparitions that have made it onto the shore. Those are easily killed outside of the water, but I doubt they will give you the kills you need. Best to fight the hundreds of ghosts in the water.\n\nHappy hunting!",
            date = "2008-08-19T00:30:38-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9274#comments:id=356594",
        },
        {
            id = 2493748,
            score = 3,
            author = "Boxofbeer",
