    [9276] = {
        {
            id = 21944,
            score = 17,
            author = "13297",
            text = "Co-Ord's - 79, 36\n\n17-19 Troll's, nothing too hard.",
            date = "2007-01-20T06:19:23-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9276#comments:id=21944",
        },
        {
            id = 111337,
            score = 9,
            author = "5027",
            text = "When you start this quest, get Shadowpine Weaponry (http://www.wowhead.com/?quest=9214) as well. It's a good chance to do a couple quests at the same time since half the mobs you need to kill are the same for this quest, and the other half you need to kill are with the follow up.",
            date = "2007-06-26T14:41:09-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9276#comments:id=111337",
        },
        {
            id = 3118683,
            score = 8,
            author = "Kimiya",
            text = "For those who didn't go through Ghostlands and want to do these quests (long story), the NPC won't have them for you until you fulfill a certain few others in the zone.\n\n1. Pick up the quest https://www.wowhead.com/quest=9329 from https://www.wowhead.com/npc=16197 in Tranquilien, and turn it in to open up some other questgivers in town.\n2. Talk to https://www.wowhead.com/npc=16213 right outside and pick up https://www.wowhead.com/quest=9145 to get started on fighting the trolls. Do her quest to kill a few trolls and she'll next send you to Farstrider Enclave with https://www.wowhead.com/quest=9146.\n3. Once you've turned that in to https://www.wowhead.com/npc=16220 other NPCs at the enclave will offer quests, including https://www.wowhead.com/npc=16463 who then gives you these quests!",
            date = "2019-04-15T20:34:05-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9276#comments:id=3118683",
        },
        {
            id = 41602,
            score = 0,
            author = "6221",
            text = "Found them at 73,45.",
            date = "2007-02-24T13:25:45-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9276#comments:id=41602",
        },
    },
    [9277] = {
        {
            id = 22923,
            score = 15,
            author = "zenma",
            text = "Located at 67, 50",
            date = "2007-01-22T19:02:53-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9277#comments:id=22923",
        },
        {
            id = 111345,
            score = 13,
            author = "5027",
            text = "Do this quest along with Shadowpine Weaponry (http://www.wowhead.com/?quest=9214). This quest and the one before it in the chain require you to kill the same mobs so it is a good way to get them both done at the same time.",
            date = "2007-06-26T14:53:15-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9277#comments:id=111345",
        },
        {
            id = 302261,
            score = 4,
            author = "91244",
            text = "As a Rogue, Sap the Catlords and take out their pets. It makes it a whole lot easier than trying to tank both as you damage. If you need to, bandage after the cat; you should be able to finish off a bandage just before Sap wears off.\n\nAlso, it's a good idea to Garrote the Hexxars if you want to minimize your work. They like to run about half of the time, and getting that bleed on them will help get them down if you lag behind them.\n\nAlso note that the Catlords' pets can run as fast as you during Sprint, so be extra careful when fighting around them, because you won't always be able to escape.",
            date = "2008-06-09T15:01:11-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9277#comments:id=302261",
        },
        {
            id = 1814775,
            score = 3,
            author = "JezebelJay",
            text = "The Catlords were definitely posing a problem for me as a l19 blood elf mage. Although once the solution clicked with me, I had great fun turning the shadow lynxes into sheep whilst I killed the catlords. Try it! :)",
            date = "2013-02-17T12:49:46-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9277#comments:id=1814775",
        },
        {
            id = 814759,
            score = 1,
            author = "krynge",
            text = "I experienced good drop rate on hexxer and catlords.",
            date = "2009-08-17T14:41:40-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9277#comments:id=814759",
        },
    },
