        },
        {
            id = 37729,
            score = 4,
            author = "vexis58",
            text = "Didn't Blizzard remove the ranged weapon rewards from similar starting quests in other zones in order to force hunters to focus on their melee weapons, since they are more important before getting a pet? I wonder why they kept this one.\n\nSimilar Blood Elf quests have a bow as a reward, but don't make you choose between a bow and a melee weapon.",
            date = "2007-02-17T19:29:03-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9311#comments:id=37729",
        },
        {
            id = 136567,
            score = 4,
            author = "78730",
            text = "Accepted: 72,60\nTarget Mob: 69,65\nTurned In: 79,51\n\nYou should also pick up the Blood Elf Plans (http://www.wowhead.com/?item=24414) to begin the quest Blood Elf Plans (http://www.wowhead.com/?quest=9798) while you are completing this quest.",
            date = "2007-08-12T15:57:33-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9311#comments:id=136567",
        },
    },
