    [9355] = {
        {
            id = 333254,
            score = 35,
            author = "90373",
            text = "Im suprized no one has said this after all this time i guess im the only nerd that noticed but the quest name is a line from a movie in the early 90s called Tremors (http://images.google.com/imgres?imgurl=http://www.filmsy.com/wp-content/uploads/2007/10/tremors1.jpg&imgrefurl=http://www.filmsy.com/reviews/tremors-review/&h=436&w=300&sz=20&hl=en&start=11&um=1&tbnid=qCQVHilng8AWnM:&tbnh=126&tbnw=87&prev=/images%3Fq%3Dtremors%26um%3D1%26hl%3Den%26safe%3Doff%26sa%3DN) about underground worms that attack a town. Anyway at the start of the movie the two main characters are puting up a barbwire fence and one says.......\n\nEarl:\"I ask you... is this a job for intelligent men?\"\n\nThen the other (Keven Bacon) says...\n\nVal:\"Well show me one, I'll ask him.\"\n\nSound clip from the movie\nhttp://www.moviesoundclips.net/movies1/tremors/intelligent.wav",
            date = "2008-07-22T16:58:17-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9355#comments:id=333254",
        },
        {
            id = 21409,
            score = 31,
            author = "9875",
            text = "The Co-ords are 46-64, near where u get the quest, They are worms lvl 59-60, u`ll see rocks move just stand next them they will appare ....",
            date = "2007-01-18T15:47:10-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9355#comments:id=21409",
        },
        {
            id = 7221,
            score = 15,
            author = "tigress",
            text = "I found a mess of these things a few yards to the southwest of Honor Hold - spawning up and around the gray Deranged Hellboars that wander around out there. You spawn them by getting near the mound of dirt they kick up as they travel around below the surface.",
            date = "2006-12-06T09:58:26-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9355#comments:id=7221",
        },
        {
            id = 93913,
            score = 12,
            author = "44989",
            text = "They drop a Eroded Leather Bag that starts this quest: http://www.wowhead.com/?quest=9373",
            date = "2007-05-30T21:13:28-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9355#comments:id=93913",
        },
        {
            id = 283167,
            score = 9,
            author = "143590",
            text = "Pity the worms don't have a taste for pork as well :D  Might help with the hellboar infestation..",
            date = "2008-05-06T02:13:37-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9355#comments:id=283167",
        },
    },
    [9356] = {
        {
            id = 275400,
            score = 60,
            author = "8763",
            text = "Drop rate is about 15-20%.  It's amazing that so many of these buzzards manage to live without wings.",
            date = "2008-04-21T16:26:37-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9356#comments:id=275400",
        },
        {
            id = 17226,
            score = 53,
            author = "7344",
            text = "The Bonestripper Buzzards can be found just to the South East of Honour Hold.\n\nThese guy have a little trick you might want to watch out for. They can smell death. When you kill one of them, another will attack you, then another, then another. It seems they smell the dead corpse and fly towards it, as they approch you aggro them.",
            date = "2006-12-19T06:19:42-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9356#comments:id=17226",
        },
        {
            id = 220095,
            score = 33,
            author = "Kiayateo",
            text = "I'm sure everyone has noticed but no one has said anything:\n\nThe NPC for this and the Other cooking quests is named Legassi, and this is undoubtly a reference to Emeril Legassi the TV cook from Louisiana.",
            date = "2008-01-18T09:19:31-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9356#comments:id=220095",
        },
        {
            id = 427459,
            score = 15,
            author = "haoma",
            text = "This recipe is needed for The Outland Gourmet (http://www.wowhead.com/?achievement=1800) achievement.",
            date = "2008-11-01T12:46:56-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9356#comments:id=427459",
        },
        {
            id = 23950,
            score = 11,
            author = "14130",
            text = "The goblin NPC right next to the one that gives this quest ,\"Screaming\" Screed Luckheed, also gives a quest to collect Zeppelin Debris (In Case of Emergency...http://www.wowhead.com/?quest=10161). The area just South-East of Honor Hold where there is a large amount of the Bonestripper Buzzards also had a much larger concentration of the parts needed compared to most places that I saw running about. Fairly east to knock them both out at once.",
            date = "2007-01-24T18:44:15-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9356#comments:id=23950",
        },
    },
