    [9360] = {
        {
            id = 144555,
            score = 15,
            author = "82635",
            text = "The Amani Invasion plans are NOT a random drop off the Berserkers or the Axe Throwers or the Shadowpriests. I know this because I killed like 30 of them and the plans did not drop at all.  I had to kill Chieftain Zul'marosh before I was able to find them",
            date = "2007-08-26T22:50:12-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9360#comments:id=144555",
        },
        {
            id = 434166,
            score = 4,
            author = "222832",
            text = "\"The trolls have been keeping us pinned here while planning an attack on Fairbreeze Village.  We were not expecting this at all.\"\nWhy do i think the last bit looks sarcastic?",
            date = "2008-11-07T10:09:06-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9360#comments:id=434166",
        },
        {
