            author = "trispri",
            text = "The Amani Invasion Plans only seem to drop if exactly one person kills the chief, they must also be ungrouped. We farmed the chief for a while and got no drops, but out of curiosity we ungrouped and the plans dropped.",
            date = "2026-04-19T14:46:52-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9360#comments:id=6334064",
