            author = "10100_",
            text = "Just a little note on killing these guys: When you see them start to cast \"Fel Flames\", turn tail and run. It's a cone breath attack that deals 300+ damage per second for 3 seconds and it hurts if you get caught in it. He will rotate to keep the attack on you, but otherwise they remain stationary while casting. It has a 1.5 or 2 second cast, so if you have the enemy casting bar on, you'll have plenty of warning to run out of range and avoid the damage.",
            date = "2007-03-20T16:26:18-05:00",
