        },
        {
            id = 21302,
            score = 32,
            author = "8700",
            text = "Altar is at the south end of the pools of Aggonar, its in the water, alot of blobs around.\nAfter you use the signaling gems, 3 draeni walk toward the altar, a lvl 62 is the quest target, and 2 paladins 57-58.\n\npretty easy if you're a caster, 1 chain lightning crit was enough for me to kill the quest target",
            date = "2007-01-18T10:03:01-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9370#comments:id=21302",
        },
        {
            id = 852180,
            score = 19,
            author = "425699",
            text = "This quest insn't very accurate.\nWhile the paladins did bubble when they started losing, they did not hearth.\nI was suprised by the lack of authenticity.",
            date = "2009-09-26T05:42:01-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9370#comments:id=852180",
        },
        {
            id = 812870,
            score = 9,
            author = "lazarethrites",
            text = "Funny thing. I received the quest but not the gem.  I went to the altar and it was not in my bag.  So I did the normal thing and abandoned the quest and went and accepted it again.  But again no gem in my beg.\n\nHas anyone experienced this?  Seems like a bug in the game.  Thus I am unable to complete the quest.\n\nThank you,\n\nLazareth Rites",
            date = "2009-08-15T21:14:24-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9370#comments:id=812870",
        },
    },
    [9371] = {
        {
