    [9372] = {
        {
            id = 149913,
            score = 22,
            author = "81838",
            text = "This quest, like so many others, is a menace, but can be made less so by keeping the following in mind:\n• The Helboar (http://www.wowhead.com/?npc=16880) can be found around 26,40 in a large group. Watch out for the Fel Reaver (http://www.wowhead.com/?npc=18733)\n• Pairing these quests: Helboar, The Other White Meat (http://www.wowhead.com/?quest=9361) and Demonic Contamination (http://www.wowhead.com/?quest=9372) spares the lives of about a thousand additional Helboars.",
            date = "2007-09-06T15:04:17-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9372#comments:id=149913",
        },
        {
            id = 44667,
            score = 11,
            author = "19037",
            text = "You can do this quest and http://www.wowhead.com/?quest=9361 at the same time, I'm getting drops for both quests off the hulking helboars.",
            date = "2007-03-01T15:57:43-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9372#comments:id=44667",
        },
        {
            id = 24468,
            score = 9,
            author = "15537",
            text = "Coords: 24, 58",
            date = "2007-01-25T14:17:34-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9372#comments:id=24468",
        },
        {
            id = 667620,
            score = 7,
            author = "310921",
            text = "If you havn't had a good drop rate, it might be that your not killing the 'Hulking Helboars' that the quests asks for. They are found up by temple of telhamat and when i did the quest with my Death Knight, it took me about 5-10 minutes. Really simple quest.\n\nGood luck :)",
            date = "2009-04-06T10:43:27-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9372#comments:id=667620",
        },
        {
            id = 1416533,
            score = 3,
            author = "146544",
            text = "Velamatu has it right. Do both quests, Quest: Helboar, The Other White Meat and Quest: Demonic Contamination at the same time. Killing hulking helboars near the Quest Giver of Demonic Contamination they drop both, blood and meat for both these quests. Level up.",
            date = "2011-05-12T04:26:22-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9372#comments:id=1416533",
        },
    },
    [9373] = {
        {
            id = 21163,
            score = 27,
            author = "6665",
            text = "Hand in is at 15,52 (Thiah Redmane)",
            date = "2007-01-17T21:14:28-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9373#comments:id=21163",
        },
        {
            id = 20962,
            score = 25,
            author = "12409",
            text = "Drops off worms just south of honor hold. You will almost certainly get it while doing the quest A job for an Intelligent Man",
            date = "2007-01-17T03:28:28-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9373#comments:id=20962",
        },
        {
            id = 198633,
            score = 10,
            author = "theoy",
            text = "Warning, this does not give Cenarion Circle rep anymore, under patch level 2.3.\n\nI went to snatch this quest as I was farming Cenarion Circle rep (for the 24 slot herb bag pattern), and was disappointed to find that out - though Cenarion Expedition definitely makes more sense :)",
            date = "2007-12-09T16:54:04-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9373#comments:id=198633",
        },
        {
            id = 28890,
            score = 9,
            author = "10904",
            text = "The other quests Thiah Redmane gives you need to be 61 to accept, so wait to turn in if you are 58-60.",
            date = "2007-02-01T11:44:15-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9373#comments:id=28890",
        },
        {
            id = 1675399,
            score = 9,
            author = "paularcher24",
            text = "I was stuck on 85 quests and needed 86 to complete achievement i found out it was this quest i was missing . If you go to the strip to the left of Honor Hold  on your map ( coords 45.5 - 61.6 ) . There are lots of Marauding Crust Bursters which is the mob that drops this item (It has better drop rate than the Tunnelers) . They are underground but you can clearly see the rubble above them as they're moving, just stand in the middle to aggro them and they will pop their heads above ground.  Once you finish one side the other side has respawned again. Took me around 40 kills then it dropped. Goodluck",
            date = "2012-06-10T22:27:46-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9373#comments:id=1675399",
        },
    },
    [9374] = {
        {
            id = 20875,
            score = 107,
            author = "10734",
            text = "The journal did not drop for me it was inside a brown bag hanging in a tree at 40, 37. I will post a screenshot of the satchel.",
            date = "2007-01-16T19:35:59-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9374#comments:id=20875",
        },
        {
            id = 165012,
            score = 23,
            author = "rzzr",
            text = "Be slightly careful on this one. I read the comments and saw the bag on the tree, next to the corpse. The cog came on on my mouse pointer and I looted the bag and then shot back to turn in the quest and couldn't understand why it wouldn't let me do it. I looked through my bags and found that I had looted a knapsack with some worthless stuff in it. Had auto-loot on and never checked!\nHad to go back and kill loads of slimes. The journal dropped from one of the small oozlings rather than the big one so check them all!",
            date = "2007-10-09T03:55:45-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9374#comments:id=165012",
        },
        {
            id = 530515,
            score = 7,
            author = "290318",
            text = "The tree it may or may not be hanging from is about halfway up the pools of Aggonar, in the middle of the pool (basically dead centre of the whole area). Just keep your eyes peeled for the corpse of a Blood Elf.\n\nAlso, this is my first wowhead post. Grats to me!",
            date = "2008-12-25T22:13:14-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9374#comments:id=530515",
        },
        {
            id = 22628,
            score = 4,
            author = "12719",
            text = "I could not find it in the tree on the esat bank at those coords - but go to the middle of stream directly west of that tree is a stump where I found the bag with the journal.",
            date = "2007-01-22T00:15:33-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9374#comments:id=22628",
        },
        {
            id = 23257,
            score = 3,
            author = "12690",
            text = "I ran around thinking it was on the edge like the poster above me, but as they note, it is not on the edge of the place, it's in the middle, hanging from a stump, next to a dead blood elf's corpse. Hope that helps.",
            date = "2007-01-23T12:43:13-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9374#comments:id=23257",
        },
    },
    [9375] = {
        {
            id = 160363,
            score = 25,
            author = "Nain",
            text = "A neat little trick if you're priest, you can mind sooth all the mobs that she might run into and they won't hit her.",
            date = "2007-09-29T14:00:58-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9375#comments:id=160363",
        },
        {
            id = 165515,
            score = 24,
            author = "bornhj",
            text = "Just watched someone do this quest, accompanied by a couple of Alliance who were helping to clear the mobs. The escort, after killing the 2 spawned mobs, aggroed the Alliance and they couldn't shake her off. Once they died (they ended up just letting her beat on them), she just despawned.\n\nBe careful doing this quest if there are Alliance around.",
            date = "2007-10-10T08:39:27-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9375#comments:id=165515",
        },
        {
            id = 2556069,
            score = 22,
            author = "kerrymayall",
            text = "You know how in most escort quests you usually get to a point well before the end where the NPC says \"Thanks for the help, I'll find my way from here.\"?\n\nWell, this isn't one of those.",
            date = "2018-03-04T02:24:19-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9375#comments:id=2556069",
        },
        {
            id = 431390,
            score = 14,
            author = "sydnese",
            text = "If alliance kill the npc while you're doing the quest, go do something else, because it will be hard for them to resist doing it repeatedly.  It's just too easy for them to waste your time.  Not sure why they made the NPC flagged for PvP but decided not to call this a PvP quest.",
            date = "2008-11-04T21:23:41-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9375#comments:id=431390",
        },
        {
            id = 22108,
            score = 12,
            author = "shofixti",
            text = "When I finished this quest, I returned to Falcon Watch, where the pilgrim disappeared after delivering some information for a follow-up quest. It gave me credit for returning her, but the quest did not complete.\n\nTaleris Dawngazer is the person to speak with, but you can only talk to him about this quest when he's at the little camp to the right of the main entry road. If he's over by the wounded pilgrims having his argument with one of the named NPCs, you won't be able to talk to him. Wait until he gets back.",
            date = "2007-01-20T14:29:40-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9375#comments:id=22108",
        },
    },
    [9376] = {
        {
            id = 21203,
            score = 60,
            author = "12696",
            text = "22, 68\n\nOn a purple rug.",
            date = "2007-01-18T00:43:03-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9376#comments:id=21203",
        },
        {
            id = 950754,
            score = 16,
            author = "Jaeza",
            text = "The Road to Falcon Watch (http://www.wowhead.com/?quest=9375) IS a pre-requisite for thie quest.  Once you escort the chick back she asks where her pack is, which opens up this quest.",
            date = "2010-01-18T14:55:31-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9376#comments:id=950754",
        },
        {
            id = 605848,
            score = 5,
            author = "321739",
            text = "If you stand at the exit of Falcon Watch and look across to the raven you will see a single thorn tree shaped like a \"t\" or a cross with a thorn bulb/ball on each side branch (it is the only one with bulbs of any sort) the pack is sitting under that.",
            date = "2009-02-12T07:16:31-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9376#comments:id=605848",
        },
        {
            id = 103427,
            score = 4,
            author = "tatterdemalion",
            text = "There are two kinds of mobs there, skitterers and ravagers. The skitterers seem to have a random patrol and can come out of nowhere. They also move hella fast. ._.\n\nNo aggro while opening pack either.",
            date = "2007-06-13T02:31:45-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9376#comments:id=103427",
        },
        {
            id = 467503,
            score = 4,
            author = "234013",
            text = "After doing the escort, you might think it is over by where the pilgrim was. Do not be fooled like I was. Her purple rug is over by the Insect Ravager things, and a small brown sack sits upon it, waiting for you. Good luck, nice exp, VERY fast if you know where it is.",
            date = "2008-11-24T16:20:26-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9376#comments:id=467503",
        },
    },
    [9377] = {
    },
    [9381] = {
        {
            id = 21369,
            score = 17,
            author = "Arx4",
            text = "You'll mostly find them around 25,46.\n\nThey sometimes do a debuff called Gut Rip, which is reduced stamina by 13.",
            date = "2007-01-18T13:21:43-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9381#comments:id=21369",
        },
        {
            id = 144850,
            score = 15,
            author = "73150",
            text = "Keep in mind that these drop off of Bonestripper Vultures only; NOT the Bonestripper Buzzards.",
            date = "2007-08-27T12:57:07-05:00",
