    [9385] = {
        {
            id = 26041,
            score = 16,
            author = "10386",
            text = "Note that there are two types of ravager near Falcon's Watch -- the quillfang ravager and the quillfang skitterer. You do not receive credit for killing the skitterers, which is unfortunate because they outnumber the ravagers by a pretty healthy margin, and they are very fast, and very aggressive. Also, they're colored differently than the ravagers -- they're mostly blue while the ravagers are a uniform drab green.\n\nThat being the case, when you do this quest, chances are you'll have a lot of company, and all you can really do is wait for the ravagers to respawn.",
            date = "2007-01-27T23:01:54-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9385#comments:id=26041",
        },
        {
            id = 21334,
            score = 12,
            author = "Amberley",
            text = "South eastish of Falcon's Watch. Around 22, 65.",
            date = "2007-01-18T11:47:59-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9385#comments:id=21334",
        },
        {
            id = 233380,
            score = 7,
            author = "126728",
            text = "It seemed to me that the Quillfang Skitterer's and the Ravager's have a lot of armour, therefor increasing the difficulty of this quest for melee type classes. Just to point that out.",
            date = "2008-02-11T09:29:25-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9385#comments:id=233380",
        },
        {
            id = 619952,
            score = 5,
            author = "trucktech68801",
            text = "Did this quest tonight on my lvl 64 BM/Surv hunter and found that the skitterers count towards completion now as all i killed were skitterers.  Anyone wishing to complete this quest can now complete it without waiting on the titled ravagers to repop.",
            date = "2009-02-22T23:26:36-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9385#comments:id=619952",
        },
        {
            id = 194416,
            score = 4,
            author = "104398",
            text = "While the Skitterers are pretty much useless...they do have a small purpose...I had the quest Ravager Egg roundup from Legassi at the crashed zeppelin, and I got 3 or 4 of the eggs from the skitterers.\n\nWhile the Ravager egg roundup quest itself says you have to go all the way to Terokkar Forest to collect them. The drop rates from the skitterers are probably very small as far as the eggs are concerned..but still if you had both quests and if you do the ravager quest 1st, why not have a use for the skitterers, because you will end up killing a few to get to the ravagers.",
            date = "2007-12-01T12:53:47-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9385#comments:id=194416",
        },
    },
    [9387] = {
        {
            id = 814011,
            score = 33,
            author = "339106",
            text = "According to a comment on the Draenei Prisoner page, he says\n\n\"I pity you Forsaken, your soul is devoid of light.\"\nand then he dies",
            date = "2009-08-16T22:26:03-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9387#comments:id=814011",
        },
        {
            id = 6782,
            score = 27,
            author = "6934",
            text = "Took about 20 kills to collect all 5. Taskmasters have 1-2 weak minions with them.  Minions will flee once taskmaster dies.",
            date = "2006-12-05T21:52:57-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9387#comments:id=6782",
        },
        {
            id = 381009,
