            sourceUrl = "https://www.wowhead.com/quest=9390#comments:id=47370",
        },
        {
            id = 360904,
            score = 6,
            author = "201004",
            text = "Perhaps a reference to Aes Sedai from Robert Jordan's \"Wheel of Time\" series?",
            date = "2008-08-24T15:10:36-05:00",
