    [9391] = {
        {
            id = 20971,
            score = 76,
            author = "10501",
            text = "West = 29,60\nCentral = 34,59\nSouthern = 36,65",
            date = "2007-01-17T04:23:23-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9391#comments:id=20971",
        },
        {
            id = 29893,
            score = 8,
            author = "19750",
            text = "The beacons are pretty easy to find. Each of them are in the middle of four square stones. Just be careful, becouse the second you light a beacon, all the mobs near it will check it out!",
            date = "2007-02-03T06:21:21-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9391#comments:id=29893",
        },
        {
            id = 136943,
            score = 6,
            author = "51192",
            text = "Rogues, as long as your stealth isn't on cooldown (i.e. you have to unstealth before right-clicking the beacons), you can avoid getting aggro by simply stealthing RIGHT after right-clicking the beacon. You may need to be a bit quick, but it'll keep you from losing a single HP in this quest. No [Flash Powder] (http://www.wowhead.com/?item=5140) used either.",
            date = "2007-08-13T06:59:21-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9391#comments:id=136943",
        },
        {
            id = 110349,
            score = 5,
            author = "58847",
            text = "As a 60 warlock, I simply ran past, right-clicking the torch, and did not aggro a single one of the whelps.  When you do run past, try to do it on the side of the torch opposite of where most of the whelps are.  If your timing is good, you can finish this quest in only a few minutes without taking any damage.",
            date = "2007-06-24T12:35:05-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9391#comments:id=110349",
        },
        {
            id = 907224,
            score = 4,
            author = "489273",
            text = "realy easy for druid just throw it & realy fast do flight form & run :)",
            date = "2009-12-05T19:59:07-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9391#comments:id=907224",
        },
    },
    [9394] = {
