    [9396] = {
        {
            id = 21468,
            score = 14,
            author = "12977",
            text = "Around 25,75   on the half-bird guys.",
            date = "2007-01-18T19:46:46-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9396#comments:id=21468",
        },
        {
            id = 100653,
            score = 9,
            author = "17716",
            text = "I recommend saving this quest until you are level 61, as there is an escort NPC in the area where you get the scrolls that requires you to be level 61 to accept.",
            date = "2007-06-08T09:33:20-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9396#comments:id=100653",
        },
        {
            id = 119070,
            score = 4,
            author = "33042",
            text = "Here are the actual mobs with their drop rates.  The drop rates are slightly higher than what is shown because they will not drop for people who are not on the quest or have it completed.\n\nhttp://www.wowhead.com/?item=23483\n\nAnd yes, they are around 25,75",
            date = "2007-07-11T12:52:08-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9396#comments:id=119070",
        },
        {
            id = 121515,
            score = 2,
