    [9410] = {
        {
            id = 332012,
            score = 317,
            author = "Vlad",
            text = "Some important facts:\n\nYou can not just ride up to deliver the quest.\nYou can not just spawn the Wolf Spirit and run up to deliver it.\nYou are at 7500 Unfriendly with [faction=941] before completing this quest (rendering you unable to interact with the faction).\n You need to follow the Wolf.\n\nYou need to go to 33.6, 43.6 (/npc=17062) and spawn the https://www.wowhead.com/npc=17077 using https://www.wowhead.com/item=23669. Then follow it because it gives you https://www.wowhead.com/spell=29938, a buff that makes you Friendly with [faction=941]. Once you deliver the quest you gain 700 reputation, that makes you 200/8000 Neutral with the faction, thus making you able to continue questing for them in Nagrand (/quests=8.3518&filter=si=2;cr=1;crs=941;crv=0#0-3+2+1) later on.",
            date = "2008-07-21T10:52:35-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9410#comments:id=332012",
        },
        {
            id = 24581,
            score = 171,
            author = "3685",
            text = "On subsequent characters, you may be tempted to ride ahead to the Mag'har Post.  Well, don't.  :-)\nThe spirit wolf gives off an aura that you need to speak to Gorkan.",
            date = "2007-01-25T17:41:55-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9410#comments:id=24581",
        },
        {
            id = 2314024,
            score = 77,
            author = "WokkaD",
            text = "Summary & tips :\n1. The corpse is at 33.62 43.53\n2. You have to activate the totem from your bags.\n3. This is an escort quest with a slow moving NPC (Spirit Wolf).\n4. Stay within range of the Spirit Wolf or it will despawn and you'll have to start again from placing the totem.\n5. You can only hand in while the Spirit Wolf is near Gorkan Bloodfist (@ 32.01 27.79)\n6. If you don't hand in and the Spirit Wolf despawns, you will have to restart (placing the totem).\n7. I suggest a target marker on the Spirit Wolf to help keep track of it. I use the moon as it contrasts with Hellfire Peninsula's red scenery.",
            date = "2016-03-13T18:09:21-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9410#comments:id=2314024",
        },
        {
            id = 2275296,
            score = 75,
            author = "Califree",
            text = "Dear Blizzard:\n\nPlease drag that dead fel orc body up the hill, nearer the quest destination. Slow escort quests are soooo 2004.",
            date = "2015-11-14T10:56:18-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9410#comments:id=2275296",
