    [9427] = {
        {
            id = 20814,
            score = 60,
            author = "9538",
            text = "North-west part of the Pools of Aggonar is a giant demonic skeleton. You can even see the skeleton on your mini-map. At the foot of the ribcage, while standing near poisoned waters, use your cleansing vial and Aggonar will appear. Defeat him and return to the Temple of Telhamat.\n\nI was standing at the front of his rib cage and on land when I did it.",
            date = "2007-01-16T12:23:13-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9427#comments:id=20814",
        },
        {
            id = 25534,
            score = 46,
            author = "5892",
            text = "40,30 there is a burned spot on the ground just at the end of the hammer hilt, stand there, right click the vial and move back!  mob spawns there and you have to kill it. I'd clear the surrounding mobs first though",
            date = "2007-01-27T06:38:55-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9427#comments:id=25534",
        },
        {
            id = 39221,
            score = 22,
            author = "24017",
            text = "Let me sum this up for you in a very easy way step by step.\n\n1. fight your way to 39, 30.\n2. use the potions on a small island/pininciola infront of a huge skeloton.\n3. Once the item is used u spawn a 63, the NPC is almost like a pally, with a claymore, but uses warlock spells, and cannot heal.\n4. kill the 63 spawn and go home a hero.",
            date = "2007-02-20T09:46:52-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9427#comments:id=39221",
        },
        {
            id = 253987,
            score = 14,
            author = "doown",
            text = "The quest item has probably the smallest activation area in all of WoW.",
            date = "2008-03-15T20:26:04-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9427#comments:id=253987",
        },
        {
            id = 54427,
            score = 11,
            author = "35470",
            text = "For me it was 40, 30. But check this out, I submitted a SCREENSHOT ABOVE, of exactly where I was standing. Check it out!",
            date = "2007-03-20T17:11:18-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9427#comments:id=54427",
        },
    },
