    [9436] = {
        {
            id = 26878,
            score = 23,
            author = "14509",
            text = "Pick up all quest from Booty Bay as well. This way you can do 4 quest at once and gets it done quicker so you don't have to go back.\n\nThis a a ramdon drop from a Bloodscalp Sharman. They can be found at a few cords. 29,20  31,14  19,13.\n\nThese guys also drop stuff that you need for the follow quest:\n- Hunt For Yenniku\n- Bloody Bone Necklaces\n- Headhunting (pick up at BB)\n\nGood hunting Guys",
            date = "2007-01-29T03:58:54-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9436#comments:id=26878",
        },
        {
            id = 1429706,
            score = 16,
            author = "20436",
            text = "I had to do the first two quests from Commander Aggro'gosh before this opened up.",
            date = "2011-05-28T23:02:18-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9436#comments:id=1429706",
        },
        {
            id = 72489,
            score = 15,
            author = "45595",
            text = "You can get this done at the Bal'lal Ruins (29,19) right ouside Grom'Gol Base Camp.\n\nYou should attempt the following quests together,\n\n1) [34] Bloodscalp Insight\n2) [34] Hunt for Yenniku\n3) [35] Bloodscalp Ears\n4) [37] Bloody Bone Necklaces\n\n4 quests done at once.",
            date = "2007-04-25T04:19:46-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9436#comments:id=72489",
        },
        {
            id = 115586,
            score = 12,
            author = "67531",
            text = "This and several other quests can be completed at or near 30,15.\n\nFrom Hunter's Camp:\nTiger Mastery - http://www.wowhead.com/?quest=186\nPanther Mastery - http://www.wowhead.com/?quest=191\nRaptor Mastery - http://www.wowhead.com/?quest=194\n\nFrom Booty Bay:\nSinging Blue Shards - http://www.wowhead.com/?quest=605\nBloodscalp Ears - http://www.wowhead.com/?quest=189\n\nFrom Grom'Gol Base Camp (Horde only):\nBloody Bone Necklaces - http://www.wowhead.com/?quest=596\nBloodscalp Insight - http://www.wowhead.com/?quest=9436\nHunt for Yenniku - http://www.wowhead.com/?quest=581\n\nAdrenis",
            date = "2007-07-04T15:49:02-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9436#comments:id=115586",
        },
        {
            id = 1479554,
            score = 11,
            author = "Sergijus",
            text = "I had small problem with this quest.\nAs there was 0 shaman around, i couldnt complete quest. All you need to do is to keep killing other mobs until shaman is spawned.\nI had to kill like 10 other mobs till one shammy spawned for me.\nGot it on first kill.\n\nSergijus the Insane",
            date = "2011-07-25T19:25:31-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9436#comments:id=1479554",
        },
    },
    [9437] = {
        {
            id = 26077,
            score = 46,
            author = "13910",
            text = "Starts and ends at 35,31.\nThe tower is at 47,25.\nIn the building there are: 2 Sentries atop, 4 Sentries on the stairwell, 3 Sentries on the main floor, 2 Sentries stationary outside, 2 Sentries patrolling outside. All levels ranged 35-36.\nThe girl you rescue is at the bottom, the crates are at the very top.\nYou do NOT have to escort the girl, just save her from the place.",
            date = "2007-01-28T00:32:32-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9437#comments:id=26077",
        },
        {
            id = 203791,
            score = 7,
            author = "Goldving",
            text = "This quest was pretty hard for me as a 37 Frost Mage.  The guards respawned faster than I could clear.  Eventually I gave up trying to clear up to the top and ran to the top, died up there, resurrected, polymorphed one of the two guys, chugged a health potion, then went to town on the other.  Grabbed the cargo and slowfalled off the tower.  It was really a lot harder than it should've been.  By the way, there is a third guard that patrols up to the top, so if you're going to use my method wait for him to come to the top and then head back down to resurrect.",
            date = "2007-12-19T07:33:53-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9437#comments:id=203791",
        },
        {
            id = 1331996,
            score = 5,
            author = "781224",
            text = "I'm on a PvE server so there's no risk of being attacked by an Alliance player while doing this quest. However, my presence must have confused one poor guy...\n\nI figured if I CCed as many things as I could and used my Water Elemental intelligently while taking my time, this quest would go relatively okay. So I make my way inside and notice a Night Elf Druid sitting up above Ithania. I ignore him - it's not like he can do anything to me - and talk to her to set her free. She begins running out like planned. The guards start shouting - part of the quest, totally normal - and this Druid takes off after her in Cat form. O.o\n\nOh well, I keep on going. I get like one guy down when the Druid comes back in flagged for PvP. He proceeds to follow me the entiiiiire way up the tower flagged and he even puts on Thorns (http://www.wowhead.com/spell=467) to prepare for battle! After I finished, he followed me back down the tower, too. I don't think he was starting trouble, I think he thought I was killing allies of his and was probably confused about why I wasn't flagged for PvP. xD\n\nIt was pretty amusing and it reminded me of what it was like to be a confused newbie once. ^.^",
            date = "2011-02-11T14:51:41-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9437#comments:id=1331996",
        },
        {
            id = 183922,
            score = 4,
            author = "bigworm2",
            text = "this quest now has item rewards, too. A caster dagger (+int and spirit), leather bracers or mail chest piece (pally or starter shaman gear)-+12strength and +7 int.",
            date = "2007-11-14T02:40:37-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9437#comments:id=183922",
        },
        {
            id = 206612,
            score = 4,
            author = "Tyristrasz",
            text = "Once I talked to the NPC and got that objective ticked off the quest, I just took the deaths as I ran toward the top of the tower (once I found out that that was indeed where the crates were).  Died, but was able to resurrect at the top.  Went to an edge of the tower farthest from the crates, resurrected, used Frost Nova on the guards, grabbed the goods, and then jumped off.  Given the compensation for the quest completion, a 5s34c repair bill was moot.",
            date = "2007-12-24T14:31:22-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9437#comments:id=206612",
        },
    },
