    [9454] = {
        {
            id = 1478829,
            score = 33,
            author = "429386",
            text = "Tips for horde grinding this recipe:\n\nBe a Draenei (duh?)\nUse mage\nIgnore quests\nKill everything you see between your starting point and the questgiver. You need to be lev 4 for turning in this quest.\nYou can kill the Moongrazers before the quest, and just turn in when you arrive.\n\nI'm at about 9.5 minutes from creation to mailing the recipe to a toon to transfer it across to horde.",
            date = "2011-07-25T01:58:06-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9454#comments:id=1478829",
        },
        {
            id = 1696145,
            score = 23,
            author = "Agathos11",
            text = "For upper level toons who have never done this quest, all you have to do is go to Acteon (53,43) in the main quest giver and profession trainer area of Azuremyst Isle and pick up the quest.  No prequests.  Just do it and get your recipe!  As mentioned above, it is a 100% drop rate so it's quite painless.  Only element of tedium is you can't use your flying mount.",
