    [9457] = {
        {
            id = 24597,
            score = 27,
            author = "Battosai",
            text = "You can find the altar at around 19:20-19:23\n\nOnce you're close to the altar use the \"Gift of Naias\" to summon Naias and once summoned you can kill him to get Heart of Naias.",
            date = "2007-01-25T18:22:44-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9457#comments:id=24597",
        },
        {
            id = 142852,
            score = 12,
            author = "hawke",
            text = "Frost mage, beware. All the elementals are immune to Ice magic, wich make it really hard to quest. You have to either use Arcane or Fire magic, and even then , at level 35, it was taking me around 75% of my mana to kill a single mobs, and they hit for a lot of damage.\n\nSo you may want to party with someone before trying to do it, or be patient.",
            date = "2007-08-23T12:39:30-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9457#comments:id=142852",
        },
        {
