    [9498] = {
        {
            id = 76576,
            score = 23,
            author = "45315",
            text = "You need to take the Orb to get to him",
            date = "2007-05-02T12:23:19-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9498#comments:id=76576",
        },
        {
            id = 1666119,
            score = 10,
            author = "RichardA",
            text = "If you are a blood elf he says something different. He says:\n\n\"What are you still doing here, (Name)? Didn't you hear we built a proper sin'dorei outpost here in Hellfire Peninsula?\n\nSurely you'd rather be among fellow blood elves and away from all this....smell. You'll find Falcon Watch in the southwest, beyond Hellfire Citadel. Report to Ranger Captain Venn'ren; he will take care of you.\n\nThe road ahead is dangerous and heavily patrilled by Alliance scouts. I would recommend travelling woth companions. Blood elves, preferably.",
            date = "2012-05-12T19:14:26-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9498#comments:id=1666119",
        },
        {
            id = 257565,
            score = 4,
            author = "139298",
            text = "All you need to do is just to speak with the elf named \"Ranger Captain Venn'ren” (28.60)\n\nHe is at the 2nd floor of the Falcon Watch.\nTo get there just use the teleport “Orb of Translocation” and you will be there! ;-)",
            date = "2008-03-22T15:48:56-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9498#comments:id=257565",
        },
        {
            id = 774589,
            score = 3,
            author = "fishy23",
            text = "If you can't get this quest at level 60+, that's because another quest is preventing you (Not sure which one). Clear your quest book from Hellfire Peninsula quests  and you should be able to get it.\n\nQuestgiver - 55, 39 (Thrallmar)\nRanger Captain Venn'ren - 28, 60 (Falcon Watch)",
            date = "2009-07-11T08:46:07-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9498#comments:id=774589",
        },
        {
            id = 5854663,
            score = 3,
            author = "Tyrsenus",
            text = "This quest became available after completing https://www.wowhead.com/quest=10123. I also completed https://www.wowhead.com/quest=10450 and https://www.wowhead.com/quest=10086 prior; those may or may not also be prerequisities.\n\nNote that there is a unique version of this quest for blood elves: https://www.wowhead.com/quest=9499",
            date = "2024-05-13T09:19:08-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9498#comments:id=5854663",
