    [9506] = {
        {
            id = 21139,
            score = 31,
            author = "12698",
            text = "Map (?object=181674) is at 58.6, 66.5\nCompass (?object=181675) is at 59.5, 67.6",
            date = "2007-01-17T19:51:26-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9506#comments:id=21139",
        },
        {
            id = 1566184,
            score = 26,
            author = "sandyra",
            text = "Chasing the Kalimdor Loremaster Achievement or more specifically https://www.wowhead.com/achievement=4926?  Then you must do this one quest!\n\nNo, it's not on Bloodmyst Isle, and unless you're a draenei or levelled in these areas when you were a tiny tacker, you will need to go to a different zone - Azuremyst Isle.  And don't worry about the follow-up quests after this one.  Just do the one, it's all you need.\n\nIt is a pre-requisite for https://www.wowhead.com/quest=9671 that you will eventually need to get from Messenger Hermesius (http://www.wowhead.com/npc=17703) in Bloodmyst Isles - and without this [stupid filthy little] quest, you cannot unlock the final chain (of five quests in Bloodmyst Isle) to get your https://www.wowhead.com/achievement=4926 achievement.\n\nAlso note that this 'final chain' you will unlock includes a quest you will receive by mail.  It is the second step straight after https://www.wowhead.com/quest=9671.  Don't forget to check your mailbox for the next quest!\n\nNow...  Quit gouging out your eyes, get your butt down to Odeysus' Landing in Azuremyst Isle, hit up Admiral Odeysus (http://www.wowhead.com/npc=17240) and knock this puppy out!",
            date = "2011-11-08T04:53:58-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9506#comments:id=1566184",
        },
        {
            id = 21268,
            score = 17,
            author = "11299",
            text = "East of Odesyus' Landing is a goblin camp. There are actually two subcamps there.\n\nThe one where there's a small campfire you will find the Nautical Map (it looks like some scrolls on top of a cage).\n\nThe one nearest to the water has only a big crystal in its center and there you will find the compass on a chest.",
            date = "2007-01-18T07:31:09-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9506#comments:id=21268",
        },
        {
            id = 1539167,
            score = 1,
            author = "jostor",
            text = "It is a good idea to complete this quest if you want to get all quests out of Bloodmyst Isle (and get the Bloodmyst Isle Quests (http://www.wowhead.com/achievement=4926) achievement), since having done this quest is a pre-requirement to do several quest up in bloodmyst.\n\nThe quest is simple and straightforward anyway, just collecting 2 items in the camps to the east (the blizzard quest tracker shows the way excellent).",
            date = "2011-10-09T17:59:13-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9506#comments:id=1539167",
        },
        {
            id = 1633514,
            score = 1,
            author = "Morvass",
            text = "You need this in order to get the drop item to start [quest=9515 domain=www]",
            date = "2012-02-29T21:13:59-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9506#comments:id=1633514",
        },
    },
