    [9514] = {
        {
            id = 960336,
            score = 11,
            author = "204017",
            text = "Ok I were just handing a quest here and here is what happened to me, read carefully it's just hillarious xD\n____________________________________________________________________________________________________\nWhat says admiral:\n\nAdmiral: Hey, Cookie! What's for dinner tonight? And don't say chicken!\nCookie: Yarr, Admiral. Let me think about it... Arrr... It be comin' into focus.\nCookie: It looks like it be succulent pork ribs basted with its own delectable juices and a side o' Captain Sander's Secret Sauce - fer dippin'.\nCookie: And fer dessert we be havin' cheesecake, flown in fresh from Stormwind on the wings o' angels...\nAdmiral: Wow! Really?\nCookie: No. Not really...\n\nCookie: It be chicken...\nAdmiral: I hate you so much, Cookie.\n____________________________________________________________________________________________________\nWhen handing in the  [Rune Covered Tablet]\n\nPriestess: Adamant, could you please take a look at this tablet and try to decipher the runes?\nArchaeologist: Of course! Anything for you, darling!\nArchaeologist: Alright, let me take a look at that tablet.\nArchaeologist Adamant Ironheart slowly reads the tablet, mouthing the words in their native tongue.\nArchaeologist: Naga warlord! Oh dear...\nArchaeologist: Well, you aren't going to like what I have to tell you, young missy. This tablet is a naga communication. Their leader, Warlord Sriss'tiz, has ordered his naga to take the rest of the island by force.\nArchaeologist: And it looks like he's got reinforcements comin' from Nazjatar!\nArchaeologist: We've got to do something about this!\nPriestess: Thank you, Adamant. I think I know just the person for the job.\n____________________________________________________________________________________________________\nAnd together! xDDD\n\nPriestess: Adamant, could you please take a look at this tablet and try to decipher the runes?\nArchaeologist: Of course! Anything for you, darling!\nAdmiral: Hey, Cookie! What's for dinner tonight? And don't say chicken!\nArchaeologist: Alright, let me take a look at that tablet.\nArchaeologist Adamant Ironheart slowly reads the tablet, mouthing the words in their native tongue.\nCookie: Yarr, Admiral. Let me think about it... Arrr... It be comin' into focus.\nArchaeologist: Naga warlord! Oh dear...\nCookie: It looks like it be succulent pork ribs basted with its own delectable juices and a side o' Captain Sander's Secret Sauce - fer dippin'...\nCookie: ...And fer dessert we be havin' cheesecake, flown in fresh from Stormwind on the wings o' angels.\nArchaeologist: Well, you aren't going to like what I have to tell you, young missy. This tablet is a naga communication. Their leader, Warlord Sriss'tiz, has ordered his naga to take the rest of the island by force.\nArchaeologist: And it looks like he's got reinforcements comin' from Nazjatar!\nArchaeologist: We've got to do something about this!\nPriestess: Thank you, Adamant. I think I know just the person for the job.\nAdmiral: Wow! Me? Really?\nCookie: No. Not really...\n\nCookie: It be chicken...\nAdmiral: I hate you so much, Cookie.",
            date = "2010-01-30T03:37:34-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9514#comments:id=960336",
        },
        {
            id = 1115553,
            score = 10,
            author = "Crystallyne",
            text = "The item that starts this quest will only drop AFTER you have at least accepted the quest A Small Start (http://www.wowhead.com/quest=9506).\n\nI was trying to get this quest for quite awhile, and had read the comments for the quest, but failed to read the comments for the quest item itself.  So I thought I'd share this here as well in case anyone else makes my mistake.  heheh",
            date = "2010-09-07T17:34:11-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9514#comments:id=1115553",
        },
        {
            id = 69151,
            score = 9,
            author = "Swallow",
            text = "Follow up quest: http://www.wowhead.com/?quest=9515",
            date = "2007-04-18T12:04:53-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9514#comments:id=69151",
        },
        {
            id = 812481,
            score = 6,
            author = "Sellanor",
            text = "If you deliver the Rune Covered Tablet (http://www.wowhead.com/?item=23759) to Priestess Kyleen Il'dinare (http://www.wowhead.com/?npc=17241), Adamant Ironheart (http://www.wowhead.com/?npc=17242), Archaeologist of the Explorer's league will decipher it:\n\nPriestess Kyleen Il'dinare says: Adamant, could you please take a look at this tablet and try to decipher the runes?\nArchaeologist Adamant Ironheart says: Of course! Anything for you, darling!\nArchaeologist Adamant Ironheart says: Alright, let me take a look at that tablet.\n\nArchaeologist Adamant Ironheart says: Naga warlord! Oh dear...\nArchaeologist Adamant Ironheart says: Well, you aren't going to like what I have to tell you, young missy. This tablet is a naga communication. Their leader, Warlord Sriss'tiz, has ordered his naga to take the rest of the island by force.\nArchaeologist Adamant Ironheart says: And it looks like he's got reinforcements comin' from Nazjatar!\nArchaeologist Adamant Ironheart says: We've got to do something about this!\nPriestess Kyleen Il'dinare says: Thank you, Adamant. I think I know just the person for the job.",
            date = "2009-08-15T12:53:28-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9514#comments:id=812481",
        },
        {
            id = 2280503,
            score = 3,
            author = "Aurleis1",
            text = "Video Guide: https://www.youtube.com/watch?v=Qptcq7UKVeI\n\n1.  https://www.wowhead.com/quest=9514\n•\009Travel to Wrathscale Point in the vicinity of coords 40.2, 75.9, and locate a https://www.wowhead.com/npc=17194 on the beach.\n•\009Defeat the https://www.wowhead.com/npc=17194 and loot the https://www.wowhead.com/item=23759.\n•\009Accept the quest, https://www.wowhead.com/quest=9514, by clicking the https://www.wowhead.com/item=23759 in your inventory.\n•\009Travel northeast to coords 47, 70.2.\n•\009Turn in the quest to https://www.wowhead.com/npc=17241.",
            date = "2015-11-25T23:32:29-06:00",
