    [9528] = {
        {
            id = 263719,
            score = 59,
            author = "smoo",
            text = "Dont friggin die there. You spawn at azure watch.",
            date = "2008-03-31T05:18:49-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9528#comments:id=263719",
        },
        {
            id = 1075183,
            score = 40,
            author = "549316",
            text = "How can I ever repay you for this, ? Please, take this heirloom. It symbolizes a sacred bond of friendship, trust and love amongst night elves. You are a brother to me - from this day until the end of time...\n\n*Inventory is full*\n\nThe bracers were lost forever and never found,",
            date = "2010-07-07T08:53:29-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9528#comments:id=1075183",
        },
        {
            id = 662675,
            score = 36,
            author = "344286",
            text = "Soloed with ease as a lvl 9 priest.  I don't know why this has a Suggested 2 Players tag on it, but, as one pster said if you can kill a single owlbeast at a time you can do this quest NP.  And, Magwin is actually not a completely stupid AI escort for once, she never aggros more then one mob and moves in a straight line.\n\nMagwin's Lines:\n\nHelp me! (Only phrase she said while attacking the Owlbeasts)\n\nMy poor family.  Everything has been destroyed. (Upon seeing the wrecked house)\n\nFather! Father! You're alive!\n\nCowlen: Daughter!\n\nMagwin hugs her father.\n\nYou can thank  for getting me back here safely, father.\n\nSweet ending to a pretty sad quest cluster.\n\nEDIT:\n\nAs of 4/1/09 a Draenei priest received all of the rep listed at the top (63s with the various factions etc)",
            date = "2009-04-01T12:45:54-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9528#comments:id=662675",
        },
        {
            id = 30923,
            score = 28,
            author = "cjrubin",
            text = "Very easily soloed at level 8. Magwin walks slowly, aggros one mob at a time and no additional mobs are spawned on the way. Trivial.",
            date = "2007-02-04T23:22:31-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9528#comments:id=30923",
        },
        {
