    [9531] = {
        {
            id = 438719,
            score = 105,
            author = "Furkel",
            text = "Ok, I've done this quest several times on various alts, and I've always had fun with the fact that you can still talk while in disguise. I've been standing there, saying stuff like \"I'm sure you're wondering if this tree was here the last time you met, eh?\" or \"Dum de dum, just a tree\".\n\nAaanyway, this kept building and building, until the third or fourth time I did the quest, when I suddenly realized I'd created a poetic masterpiece:\n\n\"Just a Tree\"\n\nI'm a tree, just a tree\nPlease stop staring at me\nThere ain't nothing to see\nhere, quite obviously\n\nJust a big lump of wood\nNot a spy, you'll agree\nAnd I'm thinking you should\njust forget about me\n\nI've got bark, I've got leaves\nI've got branches galore\nI bet no one conceives\nme as anything more\nthan a tree! Just a plant!\nJust a motionless stick!\nThink I'll hear you? I can't,\nI'm as deaf as a brick!\n\nSo return to your schemes\nBecause, quite honestly\nIn your wildest of dreams\nyou can't think me to be\nanything... but a tree.\nI'm a tree. Just a tree.\n\n*holds for applause and/or massive downrating*",
            date = "2008-11-11T13:32:07-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9531#comments:id=438719",
        },
        {
            id = 18456,
            score = 51,
            author = "9193",
            text = "The naga flag is located on the eastern coast of Silvermyst Isle.  The grey arrow on the screenshot I uploaded is in the exact location of the naga flag.",
            date = "2006-12-29T13:41:13-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9531#comments:id=18456",
        },
        {
