    [9538] = {
        {
            id = 135368,
            score = 14,
            author = "Nicklaus32780",
            text = "You must read the book to also understand the furbolgs at stillpine hold",
            date = "2007-08-10T10:06:02-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9538#comments:id=135368",
        },
        {
            id = 61314,
            score = 10,
            author = "Reeku",
            text = "This is pretty much a no-brainer quest, if you are looking here for comments on the coordinates for completion; then, I laugh in your direction. Because this quest is completed by simply reading the book that was put gently in to your inventory.",
            date = "2007-04-02T22:33:41-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9538#comments:id=61314",
        },
        {
            id = 1472463,
            score = 7,
            author = "849666",
            text = "The book you have to read is simply in your Backpack. o.e",
            date = "2011-07-17T13:21:16-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9538#comments:id=1472463",
        },
        {
            id = 859994,
            score = 6,
            author = "191835",
            text = "This begins a chain quest. Warning: If you remove the quest buffs at any point in the chain, you cannot continue or restart these quests!\n\nGo to your Inventory and right click the book. It'll take a few seconds but then you've completed the quest. Turn it the quest.\n\nThis leads to the Totem quests. You have to follow a spirit to a totem, not to far away. There are Blood Elf Bandits in that area, and if you kill and loot the bandit it begins a simple quest. Anyway, you click the totem, start the next totem quest. You gain wings which allow you to walk on water(not fly!). Any combat will take the wing buff off (true for all buffs given in this chain).  You simply go across the lake, and you'll see the totem's ? hovering over it\n\nNext totem quest you go East down the river to the next totem. The buff given will allow you to breathe underwater and swim really fast. This totem is at the bottom of the lake.\n\nFrom there you follow a spirit guide to the next totem. This buff allows you to turn into a cat and run faster. You continue to follow the cat to the next totem. Try to avoid combat at all costs or you have to start the entire thing over.\n\nYou reach the final totem where you must kill and loot keys to unlock prisoners, in the camp just behind the totem. One key for each lock. So you have to kill quite a bit, the drop rate is about 80%\n\nAfter you've unlocked 8 cages you return to Azure Watch. I recommend getting the shield as your reward, shamans. But it's up to you :)",
            date = "2009-10-05T17:42:33-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9538#comments:id=859994",
        },
        {
            id = 221746,
            score = 5,
            author = "82616",
            text = "this is a really fun quest if i say myself i would give blizz 5starz and make this my favorite quest",
            date = "2008-01-21T13:28:33-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9538#comments:id=221746",
        },
    },
    [9539] = {
        {
            id = 1512159,
            score = 9,
            author = "metalkeys404",
            text = "I just did this quest on my newly created paladin, and as i touched down on the ground I earned https://www.wowhead.com/achievement=964.\n\nApparently, the slow fall doesn't prevent you from getting the achievement.",
            date = "2011-09-07T14:28:17-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9539#comments:id=1512159",
        },
        {
            id = 198688,
            score = 4,
            author = "66148",
            text = "I've done this quest twice before.  Today, though, I was not given the slow fall buff.  I assumed I had been given the buff, as I had before, and jumped after the NPC motioned me to follow.  Fell like a rock.  On the way down, I noticed that I never actually received the buff.  Died.\n\nReported it to the GMs and the answer I received is that the quest was \"...functioning normally. If you feel that the functionality should be different, then please visit the Suggestion Forum...\"\n\nSo, have they removed the slowfall as of the last patch?  Or should that still be functioning?",
            date = "2007-12-09T18:52:02-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9539#comments:id=198688",
        },
        {
