    [9545] = {
        {
            id = 30005,
            score = 39,
            author = "19837",
            text = "The vision was bugged as well for me the first time, but on my second character, his ghost wasn't standing there at the beginning and it worked.  It's a little disjointed at the end though, so I'm not sure it's working quite as intended.\n\nSedai is being escorted from the Mag'har Camp by two brown Mag'har orcs: \"Do not return, draenei scum. Next time we won't spare your life, unarmed or not!\"\n\nSedai says, \"I've failed... peace is impossible.\"\n\nThe orcs start to return but are attacked by two fel orcs, Laughing Skull Ambushers.  Sedai intervenes.  One of the Mag'har orcs is killed, as are the two ambushers.  Sedai goes and kneels on the place where his corpse is, saying \"The cycle of bloodshed is unending.  Is there nothing I can do?\"\n\nAnother fel orc, Krun Spinebreaker, shows up and kills the last Mag'har orc, saying \"You can die!\"  He doesn't kill Sedai, though, who just disappears where he was kneeling on his corpse.",
            date = "2007-02-03T11:42:42-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9545#comments:id=30005",
        },
        {
            id = 22206,
            score = 20,
            author = "13524",
            text = "Coords: 27, 37\nUse Seer's Relic on Sedal's Corpse.",
            date = "2007-01-20T17:58:40-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9545#comments:id=22206",
        },
        {
            id = 24466,
            score = 18,
            author = "15799",
            text = "What happened in the vision? I think the quest was bugged as the Sedai ghost just stood there. I got credit for completing it anyways.",
            date = "2007-01-25T14:14:38-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9545#comments:id=24466",
        },
        {
            id = 2373815,
            score = 15,
            author = "Kreffy",
            text = "The fastest way to begin this quest is to follow these steps:\n\nThe begin quest can be found at The Temple of Telhamat.\n\n1. Search for the NPC Anchorite Obadai and accept his quest https://www.wowhead.com/quest=9390.\n2. When you found Sedai's corpse (a little outside the village), you can click on him and turn in the quest.\n3. Accept https://www.wowhead.com/quest=9423 from Sedai's corpse.\n4. Go back to Anchorite Obadai and turn in the quest.\n5. A little next to him stands Makuru who provides the quest: https://www.wowhead.com/quest=9424.\n6. After you've accepted, completed and turned in Makuru's quest, a little dialogue start between Anchorite Obadai and Makuru.\n7. After the dialogue you can accept another quest from Anchorite Obadai: https://www.wowhead.com/quest=9543.\n8. This is just speaking to another NPC; Amaan the Wise.\n9. Accept Amaan the Wise's quest: https://www.wowhead.com/quest=9430\n10. When you've completed the quest turn it in and accept the next (and last) quest: https://www.wowhead.com/quest=9545.",
            date = "2016-08-26T11:41:31-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9545#comments:id=2373815",
        },
        {
            id = 20810,
            score = 12,
            author = "11591",
            text = "Position 26.9, 37.5",
            date = "2007-01-16T11:48:28-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9545#comments:id=20810",
        },
    },
