    [9549] = {
        {
            id = 47786,
            score = 16,
            author = "30522",
            text = "The idols are dropped by the Seers, but otherwise, avoid those pesky things at all costs. The knives are dropped by both the Warriors and Shorestrikers.",
            date = "2007-03-07T16:33:15-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9549#comments:id=47786",
        },
        {
            id = 41101,
            score = 8,
            author = "6833",
            text = "I found the drop rate from the Seers to be utterly terrible. Stacking at 10 killed before one dropped...and then a further 15 kills before I got another. I dread to think how long it would take to get the 3rd.\n\nKnives was easy to get, just focused on killing the warriors and have a drop every 2 kills.",
            date = "2007-02-23T12:39:44-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9549#comments:id=41101",
        },
        {
            id = 30718,
            score = 6,
            author = "Henryk",
            text = "As a reward, you receive a weathered treasure map (http://www.wowhead.com/?item=23837) which will start the quest \"A Map to Where?\" http://www.wowhead.com/?quest=9550",
            date = "2007-02-04T17:03:39-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9549#comments:id=30718",
        },
        {
            id = 266530,
            score = 5,
            author = "111397",
            text = "The knives drop from both the Warriors and Shorestrikers - basically, both of the orange murlocs.  I got my 3 idols after killing only 4 Seers.  Murlocs are always annoying as hell, but this quest wasn't so bad (level 16 priest).",
            date = "2008-04-04T21:24:56-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9549#comments:id=266530",
        },
        {
            id = 86034,
            score = 4,
            author = "Aisenfaire",
            text = "The drop rate was indeed miserably low.\n\nI found that when I killed murlocs all along the shore/ in the sea, they never dropped any of the quest items.\n\nHowever, when I killed murlocs close to the turtle shell where the questgiver is, they seemed to be much more likely to drop the quest items.   In fact, all the quest items I got were dropped from murlocs near the questgiver.  I'm not sure if it's coincidence or it's really that way.\n\nIdols --> drop from Oracles\nKnives --> drop from Warriors/ Paladins (the blackstrikers never dropped any for me)",
            date = "2007-05-20T03:08:23-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9549#comments:id=86034",
        },
    },
    [9550] = {
        {
            id = 21187,
            score = 50,
            author = "12698",
            text = "Ends at a Battered Book at 61, 41.",
            date = "2007-01-17T23:11:47-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9550#comments:id=21187",
        },
        {
            id = 25722,
            score = 22,
            author = "6020",
            text = "The above comments are great,\nbut just to emphasize it's a \"Journal\" you are looking for,\nand it's located up on the stone Gazebo at the coordinates listed above on Trimak's comment.",
            date = "2007-01-27T12:27:57-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9550#comments:id=25722",
        },
        {
            id = 68152,
            score = 22,
            author = "43753",
            text = "This is a Quest Reward from the Gnome in the turtle shell by the Blacksilt Shore that begins a Quest to start \"A Map to Where?\". When you've read the map and accepted the Quest, head east to the Naga Ruins of Loreth'Aran. If you open your Map, you'll be heading to the northern ruins, not the southern ruins.\n\nGo on top of the circular structure and locate a Battered Ancient Book by one of the Columns. Pick this up and return to Blood Watch to claim your reward.",
            date = "2007-04-16T13:27:43-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9550#comments:id=68152",
        },
        {
            id = 22136,
            score = 15,
            author = "13451",
            text = "Just to add: Its northeast of Blood Watch on top of the northern most piece of ruins with all the naga around it.\n\nTrimak's loc is correct.",
            date = "2007-01-20T16:05:36-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9550#comments:id=22136",
        },
        {
            id = 194713,
            score = 9,
            author = "70404",
            text = "I know this doesn't come under \"Informative or Useful\", but I just wanted to express my thanks for those who have taken the time to clarify exactly where this is, so:\n\nThank you all :)",
            date = "2007-12-02T04:11:01-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9550#comments:id=194713",
        },
    },
    [9557] = {
