    [9564] = {
        {
            id = 226947,
            score = 33,
            author = "53403",
            text = "I have done this on my NE priest so yes non-Draenei can do this quest. You need to do the Firbolg quest chains first to learn the language",
            date = "2008-01-30T15:02:01-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9564#comments:id=226947",
        },
        {
            id = 1652849,
            score = 27,
            author = "Bluefin",
            text = "To clear up any confusion with this quest, all you need to do is the Azure Watch quest chain to learn to speak the Furbolg language and are on (but not necessarily finished with \"Murlocs...Why here? Why Now?).\n\nMurgurgula will drop the quest starter item as long as you speak Furbolg and are on Gurf's first quest.",
            date = "2012-04-12T12:27:13-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9564#comments:id=1652849",
        },
        {
            id = 21164,
            score = 21,
            author = "12698",
            text = "You get Gurf's Dignity by killing Murgugula, a named Murlock who wanders along the Silting Shore.",
            date = "2007-01-17T21:22:47-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9564#comments:id=21164",
        },
        {
            id = 2869772,
            score = 14,
            author = "moneybiz",
            text = "The only way I could get this quest to show up having never done the area was to get https://www.wowhead.com/quest=9538 from https://www.wowhead.com/npc=17232. then going through the quests to get the totems.\nhttps://www.wowhead.com/quest=9539\nhttps://www.wowhead.com/quest=9540\nhttps://www.wowhead.com/quest=9541\nhttps://www.wowhead.com/quest=9542\nhttps://www.wowhead.com/quest=9544\n\nOnce I handed in https://www.wowhead.com/quest=9544 then https://www.wowhead.com/quest=9562 became available from https://www.wowhead.com/npc=17441 at stillpine hold but not until then.\n\nOnce you have https://www.wowhead.com/quest=9562 from you can head over to the beach around 35.4 11.8 and find https://www.wowhead.com/npc=17475. Kill https://www.wowhead.com/npc=17475 and it will drop https://www.wowhead.com/item=23850 Once you have https://www.wowhead.com/item=23850 it will start a quest. Head back over to Stillpine hold and turn it in.",
            date = "2019-02-04T15:23:03-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9564#comments:id=2869772",
        },
        {
            id = 662803,
            score = 9,
            author = "344286",
            text = "It appears that you must complete the ravager hide quest that Gurf gives you before this quest will drop.\n\nJust want to make sure people know that this is partially correct.  The ravager quest is NOT given by Gurf; at the very most the Ravager quest is a \"one triggers the other\" type of thing.  However, since you can get the Murlocs... Why Here? Why Now? quest at the same time as the Ravager, it would seem counterintuitive that the drop would be dependent on a different chain.\n\nI can confirm, however, that the Ravager quest IS necessary for the other Stillpine quests to open up, so,I guess anything is possible.",
            date = "2009-04-01T14:49:44-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9564#comments:id=662803",
        },
    },
