    [9570] = {
        {
            id = 41950,
            score = 29,
            author = "13905",
            text = "just for the record.. hes INSIDE the cave, spend freaking 10min running around outside >.<",
            date = "2007-02-25T06:31:36-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9570#comments:id=41950",
        },
        {
            id = 226489,
            score = 14,
            author = "Steelhammer",
            text = "The trick to easy-mode is: After completing \"Chief Oomooroo\" (http://www.wowhead.com/?quest=9573)  Chief yells \"Stillpine raiders,the time to strike is at hand, Charge!\" and a bunch of Stillpine run from his side to inside the cave to fight the owlbests inside.\n\nRun along with them and cross the small bridge of Chief Oomooroo and go to the path down and jump on the water, wait til the stillpines engage the owlbests so u dont have to fight them and pull  Kurken without any adds :>",
            date = "2008-01-29T19:36:09-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9570#comments:id=226489",
        },
        {
            id = 1942891,
            score = 13,
            author = "1222123",
            text = "To get this quest you need to first do [quest=9538 domain=www] (from Azure watch) until you get [quest=9559 domain=www] which will send you to stillpine hold.\nthen you will need to complete all the other quests apart from Murlocks...why Here? Why Now?\nthen you will be offered this quest.",
            date = "2014-02-13T06:40:05-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9570#comments:id=1942891",
        },
        {
            id = 406675,
            score = 11,
            author = "64235",
            text = "He is tamable as of patch 3.0 with the 51-point BM talent.  He shrinks considerably in size, but is still larger than non-exotic pets. He has a ranged attack \"Lava Breath\" which \"shoots out a double gout of molten lava for fire damage, and reduces the target's casting speed by 50% for 10 seconds. \" - Petopia.com\n\nHe makes a roaring animation, but there is no corresponding roar - love that fixed - and when he runs, he rumbles and shakes the ground, like the Devilsaurs in Un'goro Crater.",
            date = "2008-10-15T09:10:46-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9570#comments:id=406675",
        },
        {
            id = 59146,
            score = 6,
            author = "32526",
            text = "To get the Quest you have to turn in the quest to kill Chieftain Oomooroo. (http://www.wowhead.com/?quest=9573)\n\nI'd do The Kurken is Lurkin' and and Search Stillpine Hold together because they are in the same room in the back of the cave.",
            date = "2007-03-29T11:46:33-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9570#comments:id=59146",
        },
    },
