    [9574] = {
        {
            id = 24180,
            score = 116,
            author = "6311",
            text = "There's a heap of corrupted Treants that drop this bark around 50,74.",
            date = "2007-01-25T03:54:32-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9574#comments:id=24180",
        },
        {
            id = 1881122,
            score = 23,
            author = "Hoplowe",
            text = "This quest has one of the most obnoxiously low drop rates in the entire zone, if not the most. I've levelled several characters through this zone for gear, and it was common to kill ten of the treants and not see a single piece of bark.\n\nMy theory is the quest is psychic because whenever I think 'I need to go check the droprates on wowhead again' two of the damn bark pieces drop in a row.\n\nThe only saving grace is that the treants respawn quickly, but don't bother trying this quest in any other area than Middenvale.",
            date = "2013-07-26T19:56:40-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9574#comments:id=1881122",
        },
        {
            id = 1924508,
            score = 15,
            author = "580934",
            text = "I've done this quest many times but never so fast as today. At coords of 36, 75 (in the Nazzivian area) there is a huge red crystal in the ground. It looks like a giant red pineapple. Surrounding it are four of the diseased treants. They respawn quickly. By the time you kill the four, four more appear. I got all six of the Crystallized Bark in about ten minutes. Normally it takes hours of wandering the map.",
            date = "2013-12-08T16:05:34-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9574#comments:id=1924508",
        },
        {
            id = 37323,
            score = 7,
            author = "10939",
            text = "50,74 confirmed.",
            date = "2007-02-17T01:15:19-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9574#comments:id=37323",
        },
        {
            id = 273639,
            score = 6,
            author = "Archaeic",
            text = "For this quest, I didn't specifically go out and look for treants - for me, just the few that spawned when I was doing other quests seemed to be enough for the drop. Your results may differ, but I'm just throwing my two copper into the conversation.\n\n-Aliziana, Draenei Mage (Fire)\n(Moonglade, EU)",
            date = "2008-04-18T09:27:03-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9574#comments:id=273639",
        },
    },
    [9576] = {
