    [9580] = {
        {
            id = 322619,
            score = 21,
            author = "Viisven",
            text = "29% drop rate for me\n\nApparently 71% of bears don't have asses.",
            date = "2008-07-08T12:51:49-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9580#comments:id=322619",
        },
        {
            id = 303159,
            score = 13,
            author = "161465",
            text = "You know....I can understand not finding a \"Pristine Pelt\" on every animal. That's a specific condition of the pelt, and not all of them will be pristine. Same thing with, say, an uncracked scarab shell. Or an undamaged murloc eye. Whatever. But I don't recall seeing a bunch of bears wandering around northern Bloodmyst with their entrails dragging behind them because they didn't have FLANKS.\n\nAt last count, 36 bears killed. Two flanks looted. Abandoning this absurd, annoying quest.",
            date = "2008-06-11T09:31:24-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9580#comments:id=303159",
        },
        {
            id = 159590,
            score = 11,
            author = "85708",
            text = "The name of the quest of course is a song from the disney movie The Jungle Book.",
            date = "2007-09-27T20:03:48-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9580#comments:id=159590",
        },
