        },
        {
            id = 2358762,
            score = 2,
            author = "270768",
            text = "Because the level 40 requirement to wear mail armor for mail-users has been removed in Legion, Shard-Linked Greaves (http://www.wowhead.com/item=131262/shard-linked-greaves) has been added as a quest reward. As far as looks go, it's the mail counterpart to the leather version of Shard-Covered Leggings (http://www.wowhead.com/item=26020/shard-covered-leggings).\n\nEven though the quest is Alliance-only, once you have completed this quest on a mail user, the transmog will be available on both factions.",
            date = "2016-07-30T03:47:42-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9581#comments:id=2358762",
        },
