        {
            id = 154615,
            score = 18,
            author = "62056",
            text = "Human version : A Swift Message (http://www.wowhead.com/?quest=6181)\nDwarven version : Honor Students (http://www.wowhead.com/?quest=6387)\nNight Elf version : Nessa Shadowsong (http://www.wowhead.com/?quest=6344)\nDraenei version : Beds, Bandages, and Beyond (http://www.wowhead.com/?quest=9603)",
            date = "2007-09-18T09:54:26-05:00",
