        },
        {
            id = 176196,
            score = 14,
            author = "93865",
            text = "This quest's name is a reference to the popular American houseware chain, \"Bed, Bath, And Beyond\".",
            date = "2007-10-28T22:26:01-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9603#comments:id=176196",
        },
        {
            id = 276098,
            score = 11,
            author = "FarseerLolotea",
            text = "Something rather funny.  Caregiver Topher Loaal says:  \"Nurguni at the Exodar has offered to put together a package to help with our most immediate needs, but I need someone to deliver this list to him.\"\n\nIs it Nurguni (http://www.wowhead.com/?npc=16768) to whom Loaal is referring in the masculine?  If so, that's a rather odd error:  Nurguni is female, and draenei are glaringly dimorphic.",
            date = "2008-04-23T06:21:34-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9603#comments:id=276098",
        },
        {
            id = 2283764,
            score = 3,
            author = "Aurleis1",
            text = "Video Guide: https://www.youtube.com/watch?v=iieISnICew0\n\n1.  https://www.wowhead.com/quest=9603\n•\009Accept https://www.wowhead.com/quest=9603 from https://www.wowhead.com/npc=16553 at coords 48.4, 49.2 (inside the Inn at Azure Watch, [zone=3524]).\n•\009Exit the Inn and turn left, traveling to coords 49.6, 49.2.\n•\009Turn in the quest to https://www.wowhead.com/npc=43991 (Flight Master).",
            date = "2015-12-04T17:55:34-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9603#comments:id=2283764",
        },
    },
