    [9612] = {
        {
            id = 216347,
            score = 133,
            author = "72",
            text = "For Clarity, to get this quest:\n1)You must be a Draenei.\n2)Find a Draenei Youngling, there is a link to a few are in the quick info box.\n3)Get them to engage in combat, either by them naturally pathing into an aggressive creature, or by dragging one to them. Non-aggressive will not work.\n4)They must take damage, if you brought a creature to them you must let them pull aggro.\n5)Use Gift of the Naaru on the Draenei Youngling.\n6)Kill the creature, when the Draenei Youngling resets they will offer this quest.",
            date = "2008-01-10T17:52:07-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9612#comments:id=216347",
        },
        {
            id = 46506,
            score = 11,
            author = "tale",
            text = "It does appear this quest is Draenei only, requiring Gift of the Naaru to activate.  I foung a Youngling just east of the pond at 58, 42 on my 62 Gnome Mage and here are the various things I tried:\n\n1) Agged a nearby yellow mob (Root Trapper) with level 1 frost bolt and pulled it over to him.  He would not fight the mob.\n\n2) Agged a nearby red mob (Timberstrider Fledgling) with level 1 forst bolt and pulled it over to him.  He fought the mob and eventually agg transfered to him.  I healed him with a bandage, which immediately transferred agg back to me, then patiently waited for him to finally kill it.  When the mob was dead, he did not have a quest for me.\n\n3) Killed yellow mobs in the area where he wandered until finally a red mob spawned (Timberstrider Fledgling, again), which he agged on his own when he wandered near it.  I watched them fight their tediously slow fight until the mob was under 10% health and he was at around 35%, then hit him with a bandage.  This ticked him up to about 65% health before the mob interrupted the bandaging, and I let him finish killing the mob.  Still no quest.\n\nLame.",
            date = "2007-03-05T11:24:46-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9612#comments:id=46506",
        },
        {
            id = 2178335,
            score = 8,
            author = "Laeleiweyn",
            text = "For TomTom-users:\n\n/way 55.4, 29.0 Draenei Youngling\n/way 37.4, 19.4 Draenei Youngling\n/way 58.0, 41.6 Draenei Youngling\n/way 53.6, 43.8 Draenei Youngling\n/way 55.6, 47.8 Draenei Youngling\n/way 56.8, 59.6 Draenei Youngling\n/way 42.0, 57.4 Draenei Youngling\n/way 39.6, 71.4 Draenei Youngling\n/cway",
            date = "2015-05-05T15:02:19-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9612#comments:id=2178335",
        },
        {
            id = 290051,
            score = 7,
            author = "152835",
            text = "I found him northwest of Odesyus' Landing.  Either wait for him to aggro and aggressive (\"red\") creature or pull one over to him and he'll start attacking it.  I pulled a Timberstrider Fledgling over near him.  When he gets down to about 60% of his health, he'll say \"Help! I think this creature might be too tough for me to handle alone.\"  Then use Gift of the Naaru on him (obviously, that means you have to be a Draenei).  He will then say \"Thanks for the heal, !\"  Kill the creature, and the quest will become available.",
            date = "2008-05-17T19:37:18-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9612#comments:id=290051",
        },
        {
            id = 1022779,
            score = 6,
            author = "tutti",
            text = "This really is Draenei only - even if a Draenei causes the quest to become active, only they and other Draenei can pick up the quest.",
            date = "2010-04-19T19:56:50-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9612#comments:id=1022779",
        },
    },
