        },
        {
            id = 2005024,
            score = 9,
            author = "andirhyme",
            text = "I checked for my self after reading comments here (The Bear Necessities) is not required for this quest but infact https://www.wowhead.com/quest=9643 is definitely Required to pickup this quest. Glad to be of some help for those after the this quest in the future. :-)",
            date = "2014-09-22T09:07:54-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9647#comments:id=2005024",
        },
        {
            id = 779718,
            score = 5,
            author = "367569",
            text = "These mobs roam a LOT, so if you see one, get to it as quick as possible, or you might mis it. They are usually surrounded by lots of aggressive mobs, including but not limited to, Elder brown bear, Grizzled brown bear, and Mutated constrictor, so expect to be swarmed if you arent careful. Despite the dangers, a lot of the mobs in the area have quest drops, so getting those quests before hand will save you some time. Also, in the nearby cryo-core, Sunhawk Reclaimers hang out and on rare occasion, they drop the Sunhawk Missive. If you don't have luck there, head over to the Sunhawk Spies.",
            date = "2009-07-16T07:26:38-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9647#comments:id=779718",
        },
    },
    [9648] = {
        {
            id = 21305,
            score = 123,
            author = "LumiyaSpellsong",
            text = "Aquatic Stinkhorn are large plants and can be found growing underwater in the red blood-looking river that splits the lower and upper parts of the island.  I hear you can also find them as drops from the fish that inhabit the red river.\n\nBlood mushrooms are at the base of the trees found along the southern border of the main/larger part of the island - between Kessel's Crossing and Blacksilt Shore (where the murlocs are)... so basically, go west from Kessel's Crossing and search the bases of the trees that are along the southern border.  They are small and glow red.\n\nRuinous Polyspore can be found all over the ruins of Loreth'Aran, east of Blood Watch.  They are black/grey and tan.\n\nFel Cone fungus was found at the base of the trees just south of Nazzivian (as well as all over Nazzivian)- look for a large group of reddish pink mushrooms growing together in large clumps, and you'll find the fel cone fungus there.  They're kind of hard to find amongst the other 'shrooms, so drag your mouse over the group until you see the cog wheel.  They're kind of grey brown in comparison to the rest of the mushrooms they're with.",
            date = "2007-01-18T10:09:00-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9648#comments:id=21305",
        },
        {
            id = 50107,
            score = 50,
            author = "18629",
            text = "65,54 - Blood Mushroom (looks like a red, upward pointing torch)\n64,47 - Ruinous Polyspore (blue/brown circle halo top)\n66,59 - Aquatic Stinkhorn (just a couple tips sticking out of the water - top of waterfall - also at the top of the southern waterfall)\n43,83 - Fel Cone Mushrooms (around a lot of other mushrooms)",
            date = "2007-03-12T13:32:37-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9648#comments:id=50107",
        },
        {
            id = 32266,
            score = 22,
            author = "TedBundy",
            text = "All 4 type of mushrooms are detectable with the Find Herbs skill on the minimap.",
            date = "2007-02-07T13:29:11-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9648#comments:id=32266",
        },
        {
            id = 21562,
            score = 10,
            author = "12268",
            text = "I was at the red blood-looking river and I killed one Stinkhorn Striker fish who dropped the Aquatic Stinkhorn!",
            date = "2007-01-19T03:46:53-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9648#comments:id=21562",
        },
        {
            id = 76085,
            score = 8,
