    [9663] = {
        {
            id = 52962,
            score = 123,
            author = "4256",
            text = "If you didn't know, the quest name is a reference to Star Wars where there actually is a Kessel run. Han Solo did it in less than twelve parsecs.",
            date = "2007-03-18T01:40:06-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9663#comments:id=52962",
        },
        {
            id = 50176,
            score = 84,
            author = "749",
            text = "Be sure to turn in the quest before the timer runs out, else it fails, even if you have warned the NPC's.",
            date = "2007-03-12T16:32:21-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9663#comments:id=50176",
        },
        {
            id = 620767,
            score = 73,
            author = "313896",
            text = "I completed this quest in less than twelve parsecs.",
            date = "2009-02-23T15:15:09-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9663#comments:id=620767",
        },
        {
            id = 63478,
            score = 71,
            author = "Vlad",
            text = "Who (and where) to talk to:\n*******************************\n1) High Chief Stillpine - [ 47.2,21.2 ] - The leader Furbolg in Stillpine Hold.\n2) Exarch Menelaous - [ 47.0,50.8 ] - Leader at Azure Watch, west edge of the village.\n3) Admiral Odesyus - [ 47.1,70.1 ] - The admiral at Odesyus Landing.\nNote: Can't miss them, quested many times for these guys. Here is a map (http://www.wowhead.com/maps?data=3524:472212470508471701), just in case. ;)\n\nOther information\n********************\na) You use around 5 minutes in total if you don't slack.\nb) The mount is 100% and lasts 15 minutes.\nc) Abandon and retake quest if you dismount somehow.\nd) Yes the mount is indeed bugged (model wise) for Draenei female.\nPic: http://i13.tinypic.com/43vzvw6.jpg",
            date = "2007-04-07T19:43:35-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9663#comments:id=63478",
        },
        {
            id = 1346050,
            score = 42,
            author = "190376",
            text = "You can easily Solo this quest in less than twelve parsecs.",
            date = "2011-02-22T12:26:09-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9663#comments:id=1346050",
        },
    },
