    [9693] = {
        {
            id = 59796,
            score = 11,
            author = "VipSaran",
            text = "This one has no prerequisite. I got it as lvl 13 Draenei  Shammy and I haven't finished the Declaration of Power yet.",
            date = "2007-03-30T16:59:35-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9693#comments:id=59796",
        },
        {
            id = 2194554,
            score = 7,
            author = "941150",
            text = "When you turn in the quest, Vindicator Boros says \"I've heard about you. You're the one that made the Kessel Run in under 15 minutes, right?\". This is a reference to the same phrase https://www.wowhead.com/quest=9663 quest name comes from. In the original Star Wars movie, Han Solo says \"You've never heard of the Millennium Falcon?…It's the ship that made the Kessel Run in less than twelve parsecs.\"\n\nThe follow-up statement \"Bah, probably not,\" could be in-universe (the player probably isn't that famous person Boros has heard about), or it could be reference to the fact that making the Kessel Run in \"less than twelve parsecs\" has caused a long-standing argument about whether that statement even makes sense. It's pretty clear Han was supposed to be talking about time, but parsecs are a unit of distance. Still, people have found ways to make the nonsense phrase \"correct\". So we could answer \"did he make the run in under 12 parsecs\" with \"probably not\".",
            date = "2015-06-16T07:14:59-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9693#comments:id=2194554",
        },
        {
            id = 2493478,
            score = 1,
            author = "1031604",
            text = "This guy is on BLOODMYST ISLE, not on AZUREMYST ISLE, that's why if you type this coord     /way 52.6 53.2 you don't find, thats cuz u on the wrong isle. Hope it help!",
            date = "2017-05-10T03:01:00-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9693#comments:id=2493478",
        },
        {
            id = 6261010,
            score = 1,
            author = "Cavie06",
            text = "We get a Kessel Run reference!",
            date = "2026-01-13T05:01:03-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9693#comments:id=6261010",
        },
        {
            id = 569015,
            score = -2,
            author = "43970",
            text = "seems to be draenei only\n\nedit: but the follow-up isn't, so you can just continue with Blood Watch (http://www.wowhead.com/?quest=9694)",
            date = "2009-01-19T05:09:28-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9693#comments:id=569015",
        },
    },
    [9694] = {
        {
            id = 906508,
            score = 21,
            author = "492890",
            text = "Something Important to know:\n\nBefore this quest becomes available you have to complete the quests at Kessel's Crossing (62,88), you will then be sent to talk to Exarch Admetius (52,53) and he will send you to talk to Vindicator Boros. If you skip Kessel's Crossing Boros will only give you the repeatable Irradiated Crystals quest.\n\nTook me a few to figure this out. Hope it helps.\n\n(And for anyone out there still making twinks like myself: doing all these quests is irrelevant as far as XP goes, because now you can turn off ALL XP for BGs, Quests, and Exploration)",
            date = "2009-12-04T18:03:11-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9694#comments:id=906508",
        },
        {
            id = 25530,
            score = 19,
            author = "14920",
            text = "The spies are all over Bladewood north of Blood Watch. One camp is at 47,50.",
