    [9711] = {
        {
            id = 1194663,
            score = 70,
            author = "whquaint",
            text = "If you are a very high character, do not hit him at all.  You will one-shot him.  He is not to be killed, only captured.  Just stand there and watch.  Maybe heal NPC if needed.",
            date = "2010-11-28T23:52:41-06:00",
