    [9759] = {
        {
            id = 54917,
            score = 75,
            author = "Rann",
            text = "Ok, after extensive travel and testing all sorts of quests to see what the prereq for this is i found it.  What We Know http://www.wowhead.com/?quest=9753 starts it off, then after you turn in Vindicator's Rest you will gain access to Ending Their World.",
            date = "2007-03-21T16:15:58-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9759#comments:id=54917",
        },
        {
            id = 65989,
            score = 25,
            author = "sparvath",
            text = "on a sidenote. If he is not at 23 54 someone is doing the quest. So wait for him to return",
            date = "2007-04-12T10:34:49-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9759#comments:id=65989",
        },
        {
            id = 93861,
            score = 23,
            author = "Nicklaus32780",
            text = "At the end they throw a big party for u and they have some peeps from Azuremyst Isle like the Injured Night Elf Priestess,Cookie \"McWeaksauce\",Kellek the Ellek Lord etc.\n\nAnd you get Tabard of the Hand http://www.wowhead.com/?item=24344\n\nAnd you get to choose a nice tanking ring http://www.wowhead.com/?item=24349 or a nice spell-casting ring http://www.wowhead.com/?item=24350\n\nThe ending is soooo awesome! Hope u all enjoy being Hero of the Hand!",
            date = "2007-05-30T19:02:32-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9759#comments:id=93861",
        },
        {
            id = 22324,
            score = 22,
            author = "13451",
            text = "Loc 23, 54. Not that you really need it, you just follow the guy that gives it to you.\nI was able to solo this quest with my level 18 shaman. It was not TOO difficult, but i wouldnt say easy either. Just stay behind the guy that gave you the quest and let him tank get all the aggro and tank everything.",
            date = "2007-01-20T23:08:25-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9759#comments:id=22324",
        },
        {
            id = 42062,
