            text = "Any healing class can solo this quest!\n\nWas able to solo with a level 19 priest, just kept the NPC alive while he tanked it all.",
            date = "2007-02-25T11:07:15-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9759#comments:id=42062",
        },
    },
