    [9779] = {
        {
            id = 1040225,
            score = 118,
            author = "299678",
            text = "BE CAREFUL!\n\nIf you are working on Loremaster, and have already done Irradiated Crystal Shards (http://www.wowhead.com/quest=9641), the symbol above his head will be a large blue arrow for the repeatable quest (as is usual), and the yellow exclamation mark WILL NOT show for this quest on the mini map even if you have low level tracking on.\n\nThis means that if, like myself, you are relying on the minimap to show you the quests you still need, you might overlook this one if you didn't take it earlier. I was sitting on 698/700 for Loremaster of Kalimdor (http://www.wowhead.com/achievement=1678) and this little quest chain put me over the700 mark. I could have saved half an hour if I'd thought about this earlier.",
            date = "2010-05-16T22:41:46-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9779#comments:id=1040225",
