        },
        {
            id = 2437330,
            score = 21,
            author = "EmperorsFinest",
            text = "It looks like the quest is bugged at the moment of writing. Southern and Eastern hut are working as intended, you can easily burn them. While the Larger hut and Western hut are bugged, there are around 15 players trying to set fire to these two huts for 15mins now, and no one managed.\n\nEdit: Open a ticket for this, and the GM will mark it as complete, it may take a day or so depending on how much you must wait for a gm in your region/realm.",
            date = "2016-10-30T07:52:19-05:00",
