    [9806] = {
        {
            id = 102581,
            score = 82,
            author = "43146",
            text = "there is an AWESOME spot to get these off greater spore bats, around 18,18 northwest corner of the map just before you cross the bridge... there are a bunch of greater spore bats, no other mobs... i found it annoying to run around looking for mobs that drop these and found this area later.. hope it helps!",
            date = "2007-06-11T16:55:27-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9806#comments:id=102581",
        },
        {
            id = 22954,
