            author = "Hyle",
            text = "Young sporebats do not drop this. Any other sporebat or fen strider/marsh walker will drop them inculding the quest mobs Sporewing and Borlash.",
            date = "2007-01-22T20:46:47-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9806#comments:id=22954",
        },
        {
            id = 29274,
