    [9812] = {
        {
            id = 5770576,
            score = 4,
            author = "RicochetUK",
            text = "It's possible to get this quest and be stuck in the wrong phase in Tirisfal Glades, with no access to Zidormi to switch you back. If this happens, do the following.\n\n1) Travel to Orgrimmar and accept Battle For Azeroth: Mission Statement (https://www.wowhead.com/quest=51443/battle-for-azeroth-mission-statement)\n2) Skip the cinematic and head to the inn to meet your NPC group.\n3) Accept the next quest, The Stormwind Extraction. (https://www.wowhead.com/quest=50769/the-stormwind-extraction)\n4) Once this quest has started, abandon it through the map screen. This will drop you back into the Inn in Orgrimmar.\n5) Travel back to Tirisfal Glades, where Zidormi will give you the option of phasing to the correct version of Undercity.\n\nI discovered this method thanks to YouTuber DaggersWow, from here: https://www.youtube.com/watch?v=3ZR76nymLEw. Cheers mate!",
            date = "2024-01-23T07:58:44-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9812#comments:id=5770576",
        },
        {
            id = 1417969,
            score = 3,
            author = "768334",
            text = "As you go through The Canals to The Apothecarium, look for the signpost that says ROYAL QUARTERS. Coords are (53.08, 62.85). The sign is a skeleton head with an arrow pointing a direction. This sign points to the beginning of a long passageway with two guards standing at the entrance. If you travel down the passageway to the end, you will see her.",
            date = "2011-05-13T19:30:00-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9812#comments:id=1417969",
        },
        {
            id = 5452855,
            score = 3,
            author = "Tommyboypsp",
            text = "Progress text:\n\"I was told a visitor from Quel'Thalas was coming. I was expecting a blood elf, to tell you the truth.\"\n\nWhat does this say if you do the quest as a blood elf?",
            date = "2022-10-17T04:09:08-05:00",
