        {
            id = 7465,
            score = 35,
            author = "6934",
            text = "Rajis is immune to snare/rooting and will put out frost/physical damage.  She will also summon 4 normal 62 water elementals ~ they're very easy to kill.  Took her out with a 62 shaman, 62 warrior, and a 62 mage.",
            date = "2006-12-06T14:39:39-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9817#comments:id=7465",
