    [9839] = {
        {
            id = 29117,
            score = 57,
            author = "Jackyl",
            text = "There is a floating island in the very NW corner of the map. As soon as you cross the bridge to the island, turn right and go up the path, not straight into the cave. The path winds around to the left and you'll see 2 guards standing outside of a small cave entrance (loc 19.8). They can be pulled without Gorefist (lvl 64 non-elite), who is standing right inside the cave entrance. Easy solo for a 63 warrior, so anyone should be able to do it :)",
            date = "2007-02-01T19:44:56-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9839#comments:id=29117",
        },
        {
            id = 21022,
            score = 52,
            author = "Edcel",
            text = "Gorefist is up top in the hut, not in the cave below.",
            date = "2007-01-17T11:06:42-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9839#comments:id=21022",
        },
        {
            id = 91542,
            score = 38,
            author = "10315",
            text = "A note on the item if your heavy into +spell damage: If you're wondering whether to choose the cloth wrist or the trinket, take the trinket as there won't be another quest after this that rewards an equip +spell damage trinket (plenty from isntance/raid loots, but do you want to wait that long after reaching 70?), even though there will be ~3 more different types of +spell damage cloth bracers before you leave Nagrand (~lvl67). I made the oversight of choosing the wrists due to the reason I started my mage post-BC and had *very* bad gear, without checking wowhead first =S. Plenty of my post-70 and kara raiding friends still occasionally use this trinket unless they had better",
            date = "2007-05-27T05:48:28-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9839#comments:id=91542",
        },
        {
            id = 21856,
            score = 22,
            author = "12897",
            text = "Lvl 64 non elite... you can catch him by himself but he does have spawns infront of the hit.\nLocation confirmed 19,8",
            date = "2007-01-20T01:43:44-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9839#comments:id=21856",
        },
        {
            id = 1817623,
            score = 13,
            author = "jostor",
            text = "Gorefist spawns in the building on top of the floating island (not inside the cave).\n\nHis respawn timer is quite long like many other quest mobs in Outland. If he's recently been killed just hang around and be patient.",
            date = "2013-02-24T08:49:41-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9839#comments:id=1817623",
        },
    },
