    [9851] = {
        {
            id = 12558,
            score = 29,
            author = "6934",
            text = "You'll probably need to find a buddy to run this one.  He roams the area North of Oshu'gun and is immune to rooting/snaring.\n\nI thought these clefthooves looked a bit like Banthas when I first saw em.  Star Wars reference for the win.",
            date = "2006-12-10T03:32:29-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9851#comments:id=12558",
        },
        {
            id = 124567,
            score = 29,
            author = "breuger",
            text = "I love how every comment refers to her as a 'he'\nwhen the quest states it's a she",
            date = "2007-07-21T15:09:08-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9851#comments:id=124567",
        },
        {
            id = 63063,
            score = 18,
            author = "bebbe",
            text = "Completing Talbuk mastery, Windroc mastery and Clefthoof mastery will unlock the quest The Ultimate Bloodsport (http://www.wowhead.com/?quest=9852).",
            date = "2007-04-06T19:46:22-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9851#comments:id=63063",
        },
        {
            id = 25144,
            score = 12,
            author = "CelesseDruid",
            text = "Just find the herd of Clefthooves in the area. If he's dead, he'll eventually spawn with his herd.",
            date = "2007-01-26T14:44:04-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9851#comments:id=25144",
        },
        {
            id = 29181,
            score = 9,
            author = "19286",
            text = "Hard to give proper Co-ords since he moves around quite a bit.  Spawns NW of the ruins and walks along to the NE.  He is relatively slow when in combat so can be kited.\n\nImmune to fear however.\n\nAs a shadow priest, he hit me for around 400-500 per hit and had over 20k health, not too easy to solo, bring a friend.",
            date = "2007-02-01T22:26:11-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9851#comments:id=29181",
        },
    },
    [9852] = {
        {
            id = 23597,
            score = 146,
            author = "mmixan",
            text = "To open up this quest you must first do the 9 'Mastery' quests where you kill 30 of each type of animal and their named Elite bosses.\n\n-- round 1 --\nhttp://www.wowhead.com/?quest=9789\nhttp://www.wowhead.com/?quest=9857\nhttp://www.wowhead.com/?quest=9854\n\n-- round 2 --\nhttp://www.wowhead.com/?quest=9850\nhttp://www.wowhead.com/?quest=9858\nhttp://www.wowhead.com/?quest=9855\n\n-- round 3 --\nhttp://www.wowhead.com/?quest=9851\nhttp://www.wowhead.com/?quest=9859\nhttp://www.wowhead.com/?quest=9856",
            date = "2007-01-24T09:12:26-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9852#comments:id=23597",
        },
        {
            id = 15723,
            score = 28,
            author = "6934",
            text = "Tusker is on the bluff to the Northeast of Oshu'gun(the bluff is actually visable on your map).  Was able to trio this with three level 66's, though it is likely duoable with two level 68's as the quest log says.  She was not snarable or rootable.",
            date = "2006-12-15T00:58:04-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9852#comments:id=15723",
        },
        {
            id = 74706,
            score = 27,
            author = "20436",
            text = "Immune to cyclone now.",
            date = "2007-04-29T02:11:25-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9852#comments:id=74706",
        },
        {
            id = 443054,
            score = 7,
            author = "forgottenone",
            text = "Doing all the mastery quests net's you about 129,200 experience.",
            date = "2008-11-14T13:53:52-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9852#comments:id=443054",
        },
        {
            id = 1366882,
            score = 6,
            author = "gothnate",
            text = "All of these relics are now identical which sucks for any melee specs. Seems like the developers are getting a tad lazy on the refurbishes. You'd think while adding gem sockets and stats to relics, they could make them all different.",
            date = "2011-03-14T15:04:29-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9852#comments:id=1366882",
        },
    },
    [9853] = {
        {
            id = 15703,
            score = 173,
            author = "6934",
            text = "For this quest you're going to need to kill the various ogres in Warmaul Hill and collect 7 of their skulls. Use these Skulls at coords 28, 24 in the summoning circle to summon Gurok(it's on top fo the mountain/hill). You'll want a group of 2 or more for him.",
            date = "2006-12-15T00:08:47-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9853#comments:id=15703",
        },
        {
            id = 24938,
            score = 104,
            author = "cregor",
            text = "Be forewarned, he has a nasty knockback that will knock you clear off the mountain and kill you when you finally land.",
            date = "2007-01-26T09:14:45-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9853#comments:id=24938",
        },
        {
            id = 344632,
            score = 25,
            author = "140590",
            text = "Since no one's mentioned it, these are the skulls (http://www.wowhead.com/?item=24502) you are looking for. Drop rate isn't the greatest.",
