            author = "TEH6824",
            text = "Has anyone else here had the issue with not getting the achievement \"Throne of Elements\" from the \"Nagrand Slam\" achievement? Even though I have completed \"Gurok The Usurper\" I'm not getting it for some reason, am I missing something?",
            date = "2018-03-25T11:03:46-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9853#comments:id=2559598",
        },
        {
            id = 27613,
            score = 9,
            author = "11299",
            text = "3 is enough to down him, indeed, beware of his knockback.\n\nRogue, Lock, Shadowpriest. No potions, just dps + vampiric embrace is enough, not a very tough fight even. Probably doable with 2. Rogue + Lock managed to down him to 2%.",
            date = "2007-01-30T06:14:14-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9853#comments:id=27613",
        },
    },
