    [9861] = {
        {
            id = 2578288,
            score = 52,
            author = "jumbles",
            text = "This quest is required for the Throne of the Elements subsection of the https://www.wowhead.com/achievement=1273 Achievement.\n\nTo get this quest, you have to pick up a https://www.wowhead.com/item=24504\n\nThey are predominately dropped from https://www.wowhead.com/npc=17158, https://www.wowhead.com/npc=17159 and https://www.wowhead.com/npc=17160 in Nagrand.\n\nTake this to Elementalist Morgh at the Throne of the Elements and he will give you the follow up quest https://www.wowhead.com/quest=9862",
            date = "2018-07-03T22:01:28-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9861#comments:id=2578288",
        },
        {
            id = 23396,
            score = 31,
            author = "14266",
            text = "The NPC you are looking for is named Elementalist Morgh, which is found at 60:22 if you have the coordinate mod. If you do not have it however, he can be found, if you've been to Garadar, directly north of it at the Throne of Elements. Good Luck and Happy Adventures!\n-Owninator of Kalecgos Alliance\n\n-------------------------------\nCurrent Level : 65",
            date = "2007-01-23T17:43:23-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9861#comments:id=23396",
        },
        {
            id = 3248138,
            score = 5,
            author = "UltraPwnie",
            text = "I have killed prob 20+ of the mobs required, and yet no quest drops? Same with the Murkblood Plans.... can anyone help?",
            date = "2020-11-11T18:15:18-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9861#comments:id=3248138",
        },
        {
            id = 2460411,
            score = 4,
            author = "Nemesisra",
