    [9872] = {
        {
            id = 23675,
            score = 39,
            author = "12816",
            text = "This drops off the 3 wandering murkblood invaders in Nagrand.",
            date = "2007-01-24T11:41:56-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9872#comments:id=23675",
        },
        {
            id = 780403,
            score = 36,
            author = "133694",
            text = "I just want to smack Garrosh upside the head.\n\nFirst he's irritatingly depressed.\n\nSkreeran: Murkblood Broken are planning to attack! What do I do?\nGarrosh: *sucks on thumb* I dunno. We're all gonna die someday anyway, what's the point? *cuts wrist*\n\nAnd now he's got Roid Rage...\n\nSkreeran: Awesome, we've got the Lich King on the run, the Alliance have the south covered, we have the north, he has no escape!\nGarrosh: *Punches human* We deserve all this land! The Alliance must die for what they've done to us!\nSkreeran: Well, what'd they do to us?\nGarrosh: Well... uh... They kinda... Y'know... Won't let us chop down their forests? I guess? Ahem... Well... The Alliance Pigs must die!",
            date = "2009-07-16T23:06:25-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9872#comments:id=780403",
        },
        {
            id = 1508013,
            score = 17,
            author = "Fiyn",
            text = "Note, that you must be either nuetral or above with the Maghar to complete this quest. If you, like me, skipped off on meeting them in Hellfire, you must go back to Hellfire and complete those quests.",
            date = "2011-09-01T08:29:01-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9872#comments:id=1508013",
        },
        {
            id = 55175,
