    [9879] = {
        {
            id = 51657,
            score = 80,
            author = "11636",
            text = "The captive will not offer the quest until the two brutes in the room with him have been killed.  If he happens to respawn when no brutes are present, it may look the like quest is bugged.  Simply wait for the brutes to respawn, kill them, and then the captive should offer the quest.\n\nKeep in mind also that your escort is only level 62, so keeping aggro off him is vital.",
            date = "2007-03-15T14:26:03-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9879#comments:id=51657",
        },
        {
            id = 938206,
            score = 17,
            author = "230138",
            text = "The captive is in the hut at 33,42.",
            date = "2010-01-05T08:22:52-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9879#comments:id=938206",
        },
        {
            id = 25504,
            score = 16,
            author = "11660",
            text = "So I finished this quest and he says, basically, that there is more to this whole totem of kar'dash thing but it's not something I can know about.\n\nWhat's up with that?  Rep requirement before the next step?",
            date = "2007-01-27T04:38:30-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9879#comments:id=25504",
        },
        {
            id = 1903042,
            score = 15,
