            text = "33.42 inside the hut. You wont see the quest until you kill the guards surrounding him.",
            date = "2013-09-26T15:59:34-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9879#comments:id=1903042",
        },
        {
