    [9882] = {
        {
            id = 18341,
            score = 63,
            author = "6513",
            text = "I've not seen this quest available from Gezhe, though I was Friendly with Consortium the first time I checked... perhaps it's not available above Neutral?",
            date = "2006-12-28T19:17:13-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9882#comments:id=18341",
        },
        {
            id = 12780,
            score = 37,
            author = "6934",
            text = "Head South to Oshu'gun and look for the large white crystal deposits. Around them you'll find ethereal raiders and arcanists. Both of these mobs can drop the crystals, but you can also loot them off the ground in these areas.\n\ntloc 34, 63 is an excellent example of one of these areas.\n\nThis quest becomes repeatable once completed.",
            date = "2006-12-10T13:49:23-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9882#comments:id=12780",
        },
        {
            id = 139335,
            score = 11,
            author = "79797",
            text = "Combine this quest with\nhttp://www.wowhead.com/?quest=9925\nhttp://www.wowhead.com/?quest=9900",
            date = "2007-08-17T04:21:40-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9882#comments:id=139335",
        },
        {
            id = 37047,
            score = 8,
            author = "Split",
            text = "if you get this at neutral, you can still turn in when u are friendly.",
            date = "2007-02-16T14:07:37-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9882#comments:id=37047",
        },
        {
            id = 764601,
            score = 7,
            author = "410692",
            text = "Definitely worth doing. Do it with :\nhttp://www.wowhead.com/?quest=9925\nhttp://www.wowhead.com/?quest=9900\n\nIt's much easier to pick them up rather than kill for them. Earns you experience and money while killing 3 birds with one stone. Plus, it's repeatable until 'Friendly' with The Consortium. As easy as Obsidian War Beads but much higher chance of getting it done. Definitely easier than Oshu'gun Powder Samples.\n\nAnother quest to do while killing VoidSpawns:\nhttp://www.wowhead.com/?quest=9914",
            date = "2009-07-01T12:11:33-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9882#comments:id=764601",
        },
    },
    [9883] = {
        {
            id = 32721,
            score = 63,
            author = "9388",
            text = "Stops at Friendly.  So don't go wasting time by farming the Ivory tusks as well as these fragments like I did.",
            date = "2007-02-08T15:01:06-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9883#comments:id=32721",
        },
        {
            id = 24516,
            score = 51,
            author = "15842",
            text = "The quest is only available aslong as you are neutral with The Consortium.",
            date = "2007-01-25T15:55:52-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9883#comments:id=24516",
        },
        {
            id = 946756,
            score = 10,
            author = "Zephyras",
            text = "Please note that Add-ons (Such as EveryQuest) and the Wowhead Profiler do not count this quest as completed even if you have done it. This is because it is one of the ~Pick up and hand in with one click~ style quests, or one of the special repeatables which are scattered around the world which don't actually seem to treat themselves as real repeatables. Even if you query the blizzard servers for your completed quests, this quest registers as incomplete.\n\nMaybe this will change in future, but is valid as of the posting date.",
            date = "2010-01-13T19:49:12-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9883#comments:id=946756",
        },
    },
    [9884] = {
        {
            id = 90548,
            score = 25,
            author = "31174",
            text = "Note, there are four different \"Membership Benefits\" quest entries on Wowhead. These are all the same quest, the only difference is the rewards given. These are related to your reputation level with the consortium. You receive a sack of gems that increases in value and number with each higher rep level.\n\nGem Stuffed Envelope appears to be for Friendly\nhttp://www.wowhead.com/?item=25424#00zc\n\nUnmarked Sack of Gems appears to be for Honored\nhttp://www.wowhead.com/?item=25419\n\nBulging Sack of Gems appears to be for Revered\nhttp://www.wowhead.com/?item=25422\n\nBag of Premium Gems appears to be for Exalted\nhttp://www.wowhead.com/?item=25423",
            date = "2007-05-25T19:58:34-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9884#comments:id=90548",
        },
        {
            id = 169300,
            score = 11,
            author = "moose",
            text = "resets first of the month.\n\nGot a star of elune and a flame spessarite",
            date = "2007-10-15T18:53:32-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9884#comments:id=169300",
        },
        {
            id = 99380,
            score = 9,
            author = "Hotorihanzo",
            text = "This quest is repeatable. You can go back monthly to recieve another pack of gems. I have gotten 2 so far and have lots of greens and a couple blues in my bank right now.",
            date = "2007-06-06T10:18:51-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9884#comments:id=99380",
        },
        {
            id = 427141,
            score = 4,
            author = "78922",
            text = "Counts towards your total quests in the achievements every single time! Its probably a bug though.\n\nI just did it a couple of days ago and today (since its the beggining of the month now) and my total quests increased.",
            date = "2008-11-01T06:08:40-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9884#comments:id=427141",
        },
        {
            id = 108077,
            score = 1,
            author = "12854",
            text = "\"resets every month\"\nThe first of the month or 1 month form the day you complete the quest? I'll assume the latter.",
            date = "2007-06-20T15:47:35-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9884#comments:id=108077",
        },
    },
    [9885] = {
        {
            id = 90547,
            score = 15,
            author = "31174",
            text = "Note, there are four different \"Membership Benefits\" quest entries on Wowhead. These are all the same quest, the only difference is the rewards given. These are related to your reputation level with the consortium. You receive a sack of gems that increases in value and number with each higher rep level.\n\nGem Stuffed Envelope appears to be for Friendly\nhttp://www.wowhead.com/?item=25424#00zc\n\nUnmarked Sack of Gems appears to be for Honored\nhttp://www.wowhead.com/?item=25419\n\nBulging Sack of Gems appears to be for Revered\nhttp://www.wowhead.com/?item=25422\n\nBag of Premium Gems appears to be for Exalted\nhttp://www.wowhead.com/?item=25423",
            date = "2007-05-25T19:57:30-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9885#comments:id=90547",
        },
        {
            id = 102617,
            score = 6,
            author = "Decker",
            text = "As far as i know the timer for the pickup resets the 1st of every month.",
            date = "2007-06-11T18:18:11-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9885#comments:id=102617",
        },
        {
            id = 134424,
            score = 5,
            author = "CharlzO",
            text = "The NPC in Nagrand, is named Gezhe , of The Consortium faction. He stands at 31, 57 for those with coords, or just inside the little arch doorway, on the right, in the Aeris Landing camp, which is located due South of Sunspring Post, on the other side of the lake along the road.",
            date = "2007-08-08T14:08:53-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9885#comments:id=134424",
        },
        {
            id = 1687453,
            score = 5,
            author = "belhaven",
            text = "As of the Cataclysm expansion, the green-level gems appear to be more salable since they are useful for leveling (and the https://www.wowhead.com/item=23112 are especially valuable since they are needed by tailors).\n\nThe lower level rep rewards (Friendly & Honored) are therefore more profitable than the higher level ones since they have a better percentage of giving you green-level gems; the blue-level gems are essentially vendor trash on most servers.",
            date = "2012-07-12T19:55:26-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9885#comments:id=1687453",
        },
        {
            id = 35215,
            score = 3,
            author = "haus",
            text = "I got the first envelope of gems back a few days after the release of the expansion.  I have heard this is repeatable once a month for another gem reward pouch.  Is that true?  Is it the same NPC in Nagrand? Or do you have to find one in Stormspire?",
            date = "2007-02-13T11:02:57-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9885#comments:id=35215",
        },
    },
