        },
        {
            id = 21916,
            score = 6,
            author = "8508",
            text = "All the information here is excellent, the only thing to really add is that it's on a pretty slow respawn timer. I waited for it twice at about five minutes each time. Also, beware the mudfin snappers that are all around the area.",
            date = "2007-01-20T04:16:42-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9903#comments:id=21916",
        },
        {
            id = 12443,
            score = 5,
            author = "Hazelluna",
            text = "For those of you w/o the location mod that is just off the edge of the west island from Coilfang Reserve.  He spawns directly on the Reserve side and usually underwater and is a large orange Hydra.",
            date = "2006-12-09T21:24:10-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9903#comments:id=12443",
        },
        {
