    [9916] = {
        {
            id = 16629,
            score = 22,
            author = "6934",
            text = "They're placed all over the caves in Northwind/Southwind Clefts in great quantities.  Pair this up with An Audacious Advancehttp://www.wowhead.com/?quest=9907) if you want to save a little time.",
            date = "2006-12-17T17:54:18-06:00",
