        },
        {
            id = 1800635,
            score = 7,
            author = "yarko",
            text = "While leveling, I skipped from Hellfire Peninsula straight to Terokkar Forest and then flew to Telaar to continue questing in Nagrand. I soon realized that the NPCs in Telaar were unavailable because I was unfriendly with Kurenai reputation. After some investigation, I learned that players can get neutral doing some quests in Zangarmarsh, and then the NPC there will send the player to Telaar with a breadcrumb quest. Well, I really didn't want to have to go up to Zang to do those quests. Then I noticed that the Nesingwary breadcrumb quest was available there and also this quest. So I did this quest and the followup and it gave me enough rep to be able to interact with the other Telaar NPCs. So glad it worked out this way.",
            date = "2013-01-18T16:39:05-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9917#comments:id=1800635",
        },
        {
            id = 267299,
            score = 6,
