    [9927] = {
        {
            id = 16941,
            score = 32,
            author = "6934",
            text = "These banners can be placed on any dead Kil'sorrow mobs found in Kil'sorrow Fotress.  Don't forget to pick up Armaments for Deception(http://www.wowhead.com/?quest=9928) and run it while you do this quest(same quest giver).",
