        {
            id = 38091,
            score = 23,
            author = "16421",
            text = "Pair this quest with not only Armaments for Deception (http://www.wowhead.com/?quest=9928), but the Alliance quest Wanted: Giselda the Crone (http://www.wowhead.com/?quest=9936).",
            date = "2007-02-18T10:58:35-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9927#comments:id=38091",
        },
