            sourceUrl = "https://www.wowhead.com/quest=9935#comments:id=52344",
        },
        {
            id = 19436,
            score = 25,
            author = "1987",
            text = "A \"Kil'sorrow Agent\" is just any Kil'sorrow mob in the area, it's not a specific mob.",
            date = "2007-01-05T07:39:13-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9935#comments:id=19436",
