    [9946] = {
        {
            id = 407228,
            score = 31,
            author = "124529",
            text = "Quick note that I don't think anyone has mentioned:\n\nIf you have your flying mount, you can easily fly around all the mobs and past the first part of the cave and save a whole lot of time.\n\nThe entrance is at (27.6,11.3) on the Nagrand map, just a stone's throw from the Zangar border.",
            date = "2008-10-15T18:36:58-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9946#comments:id=407228",
        },
        {
            id = 41287,
            score = 19,
            author = "mehwh34d",
            text = "Another useful note, he's on a fast respawn. 2 mins at the most so loot his head and leave ASAP.\n\nRepop while refuelling isn't fun :)",
            date = "2007-02-23T19:41:42-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9946#comments:id=41287",
        },
        {
            id = 29563,
            score = 16,
            author = "Aernath",
            text = "well, i'm 68 feral dru and he's not that easy to solo...\nabout 45k hp, but if you clear area and nuke with a friend you can kill him i guess. not any extra attacks.\nand when you jump down he resets even if you moonfire him.\n\nand he's in the cave where you climb from the upper cave enterance at warmaul hill.\nmob tloc: 26,13 inside the cave. 27,18 cave enterance.",
            date = "2007-02-02T16:45:55-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9946#comments:id=29563",
        },
        {
            id = 111038,
            score = 14,
            author = "23118",
            text = "Immune to fear!",
            date = "2007-06-25T14:49:09-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9946#comments:id=111038",
        },
        {
            id = 225617,
            score = 11,
            author = "118464",
            text = "CHO'WAR'S HP REGENS WHEN YOU DIE.\n\nPeople above are posting the alleged strategy that claims if you die, and run back, Cho'war will not have regened his HP.  Well, I just tested that claim and it is FALSE.  These people who are able to do it either used Feign Death, Soulstone, or some other means to rez immediately after he resets.\n\nI ran back as fast as possible, and he was back at 100% from 43% when I died.\n\nSo consider this strategy unreliable.\n\nJanuary 28th 2007\nPatch 2.3\n\nBuffy\nNer'zhul",
            date = "2008-01-28T10:19:11-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9946#comments:id=225617",
        },
    },
