    [9962] = {
        {
            id = 12506,
            score = 90,
            author = "6934",
            text = "This is the first of a 6 boss \"event\" quest series. The quest requires level 65 to pick up and can be found at The Ring of Blood, just west of the Laughing Skull ruins. You will need a group of 4-5 for this, the more the better. Note that the first person to pick up the quest WILL have intial agro, have the tank pick it up first.\n\nThis first fight is against a level 65 elite clefthoof and really isn't a very tough fight. It's a single mob: tank, dps, heal, win.\n\nProceed to part two: http://www.wowhead.com/?quest=9967\n\nNote: Make sure all quest members have turned in previous quest before starting.",
            date = "2006-12-10T00:27:48-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9962#comments:id=12506",
        },
        {
            id = 30848,
            score = 45,
            author = "14735",
            text = "Be aware that all the Ring of Blood quests behave like escort quests, and you have to turn them in before you die or log off otherwise they'll come back as failed.",
            date = "2007-02-04T20:37:41-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9962#comments:id=30848",
        },
        {
            id = 87294,
            score = 12,
            author = "54118",
            text = "I got a little inpsired, so i tried to solo this as a warlock:\n\nFirst, I enslaved Felguard Legionnaire in Forge Camp:Hate(don't forget to use Curse of Shadows when enslaving). Then I accepted the quest and let the felguard tank the Brokentoe. I used about every cooldown I had(didn't have to use SS/HS though, did it on my first try) I got him down to around 8%, when the Felguard died, so I had to quickly finish him. Luckily, I took about 2 hits.\n\nAlso, you don't have to worry about aggro, as Felguard creates extreme amounts of threat. :) Trinket + Amp. Curse + Curse of Doom work great here.",
            date = "2007-05-22T08:03:39-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9962#comments:id=87294",
        },
        {
            id = 28142,
            score = 6,
            author = "18544",
            text = "this is a fairly easy set of quests if you have a good tank.  You definitely need 5 people.  One nice thing is there are often tons of other people waiting around and will help you take down the boss.  The 5th boss the War Champion is by far the hardest, you basically need to just non-stop spam heal the tank.  But over all, very easy, 20 minutes for 80k xp, 90g, and a great quest reward.  Definitely worth doing",
            date = "2007-01-31T08:01:01-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9962#comments:id=28142",
        },
        {
            id = 2016708,
            score = 5,
            author = "AlphaRomeo",
            text = "You can tame this guy as of 6.0. Unique skin on him, very cool-looking!",
            date = "2014-10-20T22:44:58-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9962#comments:id=2016708",
        },
    },
    [9967] = {
        {
            id = 12511,
            score = 41,
            author = "6934",
            text = "Part two of the Ring of Blood series. From this point on you're going to need a well rounded group of 5 -- tank, healer and dps.\n\nThis event will spawn two humanoid mobs simultaneously inside the ring. They're melee mobs and very easy to tank, kill them one at a time.  Make sure your tank picks the quest up first.\n\nProceed to part three: http://www.wowhead.com/?quest=9970",
            date = "2006-12-10T00:50:28-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9967#comments:id=12511",
        },
        {
            id = 30852,
            score = 21,
            author = "14735",
            text = "Be aware that the Ring of Blood quests behave like escort quests, and you have to turn them in before you die or log off otherwise they'll come back as failed.",
            date = "2007-02-04T20:41:50-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9967#comments:id=30852",
        },
        {
            id = 756958,
            score = 19,
            author = "biefking",
            text = "It's 106 miles to Ironforge, we've got a full tank of healing potions (http://www.wowhead.com/?item=929), half a pack of  smoke flares (http://www.wowhead.com/?item=23768), it's dark and we're wearing sunglasses (http://www.wowhead.com/?spell=50009).\n\nHit it. (http://www.wowhead.com/?quest=9967)",
            date = "2009-06-24T08:47:30-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9967#comments:id=756958",
        },
        {
            id = 17353,
            score = 18,
            author = "9387",
            text = "These mobs are immune to sheep, so don't even think about it.",
            date = "2006-12-19T13:18:10-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9967#comments:id=17353",
        },
        {
            id = 644856,
            score = 15,
            author = "105588",
            text = "\"We're on a mission from Gurgthock.\"",
            date = "2009-03-16T21:14:34-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9967#comments:id=644856",
        },
    },
    [9968] = {
        {
            id = 120760,
            score = 14,
            author = "28508",
            text = "You also need to complete the quest \"Clues in the Thicket\" http://www.wowhead.com/?quest=9971\ngiven by Earthbinder Tavgren to continue the questline.",
            date = "2007-07-14T21:40:57-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9968#comments:id=120760",
        },
        {
            id = 90265,
            score = 9,
            author = "Eleora",
            text = "Only killed these for this particular quest.\n\nDrop rate from Vicious Teromoths\nLevel 62 - 50%\nLevel 63 - 29%\n\nDrop rate from Teromoths\nLevel 62 - 40%\nLevel 63 - 40%\n\nWarning, both these creatures pacify, silence and prevent attacks. Not so much fun for clothwearers.\n\nIt may help to pull the moths away from the ruins, as once out of them you lose the debuff aura.",
            date = "2007-05-25T12:54:53-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9968#comments:id=90265",
        },
        {
            id = 11125,
            score = 8,
            author = "6934",
            text = "The vicious teromoths are just north of quest giver, in the town.  The teromoths are located on the outskirts of the town, but I suggest going south of the road for them.  They have an aura reducing stats by 5% and will occassional throw out a debuff that stops all attacks/spells - kind of annoying.",
            date = "2006-12-08T13:29:09-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9968#comments:id=11125",
        },
        {
            id = 40942,
            score = 7,
            author = "Dreamworks",
            text = "46.29 plenty of normal Termoth ..",
            date = "2007-02-23T06:14:27-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9968#comments:id=40942",
        },
        {
            id = 127714,
            score = 7,
            author = "51610",
            text = "Warriors can still shout at them while pacified. It's satisfying on some level.",
            date = "2007-07-27T11:15:25-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9968#comments:id=127714",
        },
    },
