    [9972] = {
        {
            id = 12529,
            score = 51,
            author = "6934",
            text = "Part four of the Ring of Blood quest series. This event will spawn a voidwalker mob inside the arena. He will stun from time to time(AE I believe) and do a knock back which reduces your tank's agro, but doesn't do much else. Not a difficult fight, but again remember to have your tank start the quest first.\n\nProceed to part five: http://www.wowhead.com/?quest=9973\n\nNote: Make sure all quest members have turned in previous quest before starting.",
            date = "2006-12-10T01:12:02-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9972#comments:id=12529",
        },
        {
            id = 72869,
            score = 20,
            author = "DarkFerret",
            text = "Mages beware.  This guy is resistant to the first school you hit him with.",
            date = "2007-04-25T17:01:41-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9972#comments:id=72869",
        },
        {
            id = 30850,
            score = 17,
            author = "14735",
            text = "Be aware that the Ring of Blood quests behave like escort quests, and you have to turn them in before you die or log off otherwise they'll come back as failed.",
            date = "2007-02-04T20:41:18-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9972#comments:id=30850",
        },
        {
            id = 78430,
            score = 11,
            author = "49067",
            text = "If your tank has some shadow res gear (for Pandemonius or otherwise) it'd be smart to wear it for this fight. His melee hits pretty hard but its all shadow damage so some resist goes a long way.",
            date = "2007-05-06T00:55:42-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9972#comments:id=78430",
        },
        {
            id = 1359072,
            score = 6,
            author = "thecomicrelief",
            text = "For other paladins trying to solo this guy\nEz-Thro Dynamite II (http://www.wowhead.com/item=18588)\n\nIf you hit him with this first he will gain resistance to fire not holy, making this fight much quicker.\nCan be obtained from a quest in Hellfire, or have an engineer make it up for you. You do not need to be an engineer to use.\n\nBlood elves can ignore all this and simply arcane torrent him.",
            date = "2011-03-06T08:44:50-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9972#comments:id=1359072",
        },
    },
    [9973] = {
        {
            id = 12530,
            score = 36,
            author = "6934",
            text = "Part five of the Ring of Blood quest series. This is definitely the hardest part in the whole quest line. This mob spawns OUTSIDE of the arena, and walks into it via the only entrance. Have your group inside the arena and your tank positioned facing the entrance. This boss will Mortal Strike, randomly charge group members, and hits extremely hard. Healers are going to have to be on the ball for this one. If you can take this one down, the next portion will be yours.\n\nProceed to final boss: http://www.wowhead.com/?quest=9977\n\nNote: Make sure all quest members have turned in previous quest before starting.",
            date = "2006-12-10T01:18:12-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9973#comments:id=12530",
        },
        {
            id = 30855,
            score = 14,
            author = "14735",
            text = "Be aware that the Ring of Blood quests behave like escort quests, and you have to turn them in before you die or log off otherwise they'll come back as failed.",
            date = "2007-02-04T20:44:31-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9973#comments:id=30855",
        },
        {
            id = 39114,
            score = 10,
            author = "Ansi",
            text = "I can confirm you fail the quest if you log out.\n\nhttp://img412.imageshack.us/my.php?image=ringofbloodzt7.jpg",
            date = "2007-02-20T06:04:03-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9973#comments:id=39114",
        },
        {
            id = 957456,
            score = 5,
            author = "Aletto",
            text = "I dunno if this has always been possible, but when I did these quests earlier today, the Warmaul champion was a really tall ethereal.\n\nKind of cool-looking, but really odd.",
            date = "2010-01-26T17:37:16-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9973#comments:id=957456",
        },
        {
            id = 39281,
            score = 4,
            author = "Spectrezh",
            text = "He spawns in the middle of the arena. only the last boss comes down from the side.\nHe hits extremely hard. extremely. im a 68 pally and had 10K armor with over 7000 health and he killed me in two hits. one for roughly 2000 and another for 5200. you defintely need the other group paying attention or your 5-man will wipe. he is the hardest out of all the npcs you have to fight.",
            date = "2007-02-20T11:14:09-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9973#comments:id=39281",
        },
    },
    [9977] = {
        {
            id = 5466,
            score = 157,
            author = "InfinityX",
            text = "This questline involves usually a group of 5 people of at least level 65. There are about five total fights you need to win in the Ring of Blood in order to get to this end quest. The fights are rather simple, but will definitely be a challenge to a group of all level 65 players. Be sure to have a solid healer and tank. Others can help without being on the quest by damaging the creature that's summoned for these quests, but you cannot get credit for this if you're in a raid.\n\nHope this helps.",
            date = "2006-12-03T20:25:24-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9977#comments:id=5466",
        },
        {
            id = 31833,
            score = 95,
            author = "3500",
            text = "We did this chain in one sitting.  At lvl 66 I recieved a total of:\n\n85050 XP\n66G 60S\n10 Super Healing Potions\n10 Super Mana Potions\n20 Netherweave Bandages\nand 1 freakin awesome weapon....\n\n....not bad for about 10 mins of work",
            date = "2007-02-06T17:59:05-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9977#comments:id=31833",
        },
        {
            id = 75349,
            score = 86,
            author = "29939",
            text = "These rewards are very good, and is it very easy to do with good group.\n\nThe yelling can give funny names like this happened to my guild mate\nhttp://img253.imageshack.us/img253/10/wowscrnshot020107194313lg9.jpg\n\"Searing Totem VI has defeated the hero of the Warmaul, Mogor! All Hail Searing Totem VI!\"",
            date = "2007-04-30T07:49:01-05:00",
            sourceUrl = "https://www.wowhead.com/quest=9977#comments:id=75349",
        },
        {
            id = 25680,
            score = 79,
            author = "1775",
            text = "A note to any rogues doing this quest:\n\nIf you use the new Wound Poison (reduces healing by 10%, stacking), it will affect the amount of health that he ankhs with. My group had 5 stacks of Wound Poison on him and he ankhed with 50% hp.",
            date = "2007-01-27T11:36:56-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9977#comments:id=25680",
        },
        {
            id = 12532,
            score = 71,
            author = "6934",
            text = "This is the final quest in the Ring of Blood series.  He is quite a bit easier than the previous boss, but that's no reason to slack off.  He will walk into the arena via the entrance, so position your group accordingly.  His special abilities include Chain Lightning, dropping totems, and Healing Wave.  Designate a group member take out his totems when they spawn.\n\nAfter killing him he will ANKH BACK TO LIFE.  After his second death the fight is over.  The rewards from this series (both xp and items) are VERY nice -- well worth the effort and time.",
            date = "2006-12-10T01:23:19-06:00",
            sourceUrl = "https://www.wowhead.com/quest=9977#comments:id=12532",
        },
    },
    [9978] = {
