            author = "Valdan",
            text = "This chain begins when you are friendly with http://www.wowhead.com/?faction=942 Cenarion Expedition.\n\nThen You do the following Quest/Quest Chains:\n\nhttp://www.wowhead.com/?quest=9957\nWhat's Wrong With Cenarion Thicket? (6 Parter)\n- Then -\nhttp://www.wowhead.com/?quest=9994\nWhat Are These Things? (4 Parter)\n- Then -\nhttp://www.wowhead.com/?quest=10005\nLetting Earthbinder Tavgren Know\n\nEnjoy and as always Happy Questing!",
            date = "2008-11-30T15:22:57-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10005#comments:id=480673",
        },
