    [10008] = {
        {
            id = 41461,
            score = 19,
            author = "gerwim",
            text = "Coords 67,53 for Bonechewer Ruins",
            date = "2007-02-24T06:07:56-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10008#comments:id=41461",
        },
        {
            id = 11869,
            score = 14,
            author = "6934",
            text = "Back to Bonechewer ruins for this one.  The Backbreakers and Devestaters are littered throughout the center of the camp, so you'll have to fight your way through the peons to get to em.  Easy kills, non elites.\n\nSuggestion:  Pair this quest up with The Firewing Liaison (http://www.wowhead.com/?quest=10003 ). Both quest objectives are located in this general area.",
            date = "2006-12-08T23:46:57-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10008#comments:id=11869",
        },
        {
            id = 83223,
            score = 11,
            author = "33397",
            text = "There's a back entrance to the Bonechewer Ruins at 68,55.  Less mobs to fight through to get into the ruins itself.",
            date = "2007-05-15T01:22:38-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10008#comments:id=83223",
        },
        {
            id = 135516,
            score = 7,
            author = "adamb10",
            text = "Watch out for the pats on wolfs.  I was killing a devestator when 5 of them came and killed me.",
            date = "2007-08-10T16:19:12-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10008#comments:id=135516",
        },
        {
            id = 237774,
            score = 6,
            author = "Rasztra",
            text = "Here's a warning for you...\n\nWARNING:  The Bonechewer Backbreakers (the casters) have a nasty little spell called \"Shadow Shock\" that hits for around 750.  The problem isn't the damage, but rather the fact that it's an instant cast (so you don't know it's coming, and can't interrupt it).\n\nIf you're like me, and like to go from mob to mob quickly and/or pull several at a time, be careful!  I nearly died because I pulled a few Bonechewers (before knowing about this spell) and the Shadow Shocks hit me before I had a chance to counterspell/silence.",
            date = "2008-02-17T02:10:26-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10008#comments:id=237774",
        },
    },
    [10009] = {
        {
            id = 17889,
            score = 159,
            author = "9877",
            text = "Raliq is found inside the same tavern as Sal'salabim.\n\nCoosh'coosh is found in the very southeastern corner of Zangarmarsh by the entrance from Terokkar Forest.\n\nFloon is found on the western side of The Bone Wastes in Terokkar Forest at (27, 58).",
            date = "2006-12-24T07:32:46-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10009#comments:id=17889",
        },
        {
            id = 21737,
            score = 44,
            author = "11279",
            text = "Raliq hits for about 500 on cloth and has an uppercut knockback.\n\nCoosh'coosh is at 80,91 in Zangarmarsh\nhe has a weak lighting bolt spell that hits for 300ish\n\nFloon can silence you but his frostbolts were only hitting me for about 200\n\nI was able to solo this quest as a mage.",
            date = "2007-01-19T19:00:44-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10009#comments:id=21737",
        },
        {
            id = 1798718,
            score = 18,
            author = "1038539",
            text = "Raliq the Drunk - Shattrath City (Worlds End Tavern) 75,31\nFloon - Terokkar Forest (The Bone Wastes) wandering around 27,58\nCoosh'coosh - Zangarmarsh (On the border of Terokkar) 81,91",
            date = "2013-01-14T21:23:54-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10009#comments:id=1798718",
        },
        {
            id = 1028205,
            score = 17,
            author = "183433",
            text = "I felt kind of sorry about killing Coosh'coosh. He didn't mean to cheat on anybody. Glowcaps actually have the same weight for him as the gold has for us! That stupid Sal-guy has no idea of Sporeggar culture! I definitely wouldn't ask for the money in the give-it-to-me-or-die way. Though... this quest line was too interesting to be just abandoned so... My apologies, Coosh. x)",
            date = "2010-04-28T10:33:50-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10009#comments:id=1028205",
        },
        {
            id = 117177,
            score = 15,
            author = "Paegan",
            text = "These 3 mobs are much, much easier than the guy that they owe money to (that you fought in the previous quest). Easily soloable.",
            date = "2007-07-07T23:43:30-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10009#comments:id=117177",
        },
    },
