    [10011] = {
        {
            id = 291159,
            score = 130,
            author = "Miyari",
            text = "At Forge Camp: Fear (located around 19,51) players must kill Xirkos, Overseer of Fear (?npc=18536) to obtain the Fel Cannon Activator (?item=25771) to use on the nearby Fel Cannon: Fear (?npc=19210) to destroy the camp.\n\nAt Forge Camp: Hate (located around 24,35) players must kill Demos, Overseer of Hate (?npc=18535) to obtain the Fel Cannon Activator (?item=25770) to use on the nearby Fel Cannon: Hate (?npc=19067) to destroy the camp.",
            date = "2008-05-19T18:49:39-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10011#comments:id=291159",
        },
        {
            id = 39492,
            score = 112,
            author = "25427",
            text = "In case none found it:\n\nThe cannons are next to the Overlords!",
            date = "2007-02-20T18:04:25-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10011#comments:id=39492",
        },
        {
            id = 21815,
            score = 22,
            author = "11279",
            text = "The named mobs you have to kill are in the middle of each camp. You cannot snare/stun/root them so it makes it hard to solo. After you kill the named you use the key they drop at the Fel Cannon in the middle of the camp.\n\nAlthough I was able to solo both demons at each camp, my movement speed was slightly faster than theirs with minor speed enchanted on my boots. I had to kite them all the way to Zangarmarsh but I did it :P\n\nThey have no ranged attack. I can imagine a Hunter or Warlock soloing these, possibly even a Priest. It was tough for me as a Mage, I had some help at the end when people saw me kiting the demon in Zangarmarsh they started shooting it.",
            date = "2007-01-19T22:35:39-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10011#comments:id=21815",
        },
        {
            id = 289537,
            score = 15,
            author = "136440",
            text = "I'm pretty sure this quest chain is required for the Mag'har chain that starts with \"A Visit to the Greatmother\".",
            date = "2008-05-16T23:17:47-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10011#comments:id=289537",
        },
        {
            id = 60531,
            score = 14,
            author = "6090",
            text = "Note to warriors: Xirkos, Overseer of Fear is immune to taunt.\n\nDidn't test this on Demos, Overseer of Hate though. - EDIT: Tested it, he's immune too.\n\n(Sorry if this has been posted already, didn't take the time to read though)",
            date = "2007-04-01T11:24:57-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10011#comments:id=60531",
        },
    },
    [10012] = {
        {
            id = 33344,
            score = 16,
            author = "CaptainPhatty",
            text = "The Fel Orc Plans can be found on the ground at 67,53, in the same building where Lisaile Fireweaver is, needed for quest http://www.wowhead.com/?quest=10002.",
