            sourceUrl = "https://www.wowhead.com/quest=10012#comments:id=33344",
        },
        {
            id = 288603,
            score = 9,
            author = "Temes",
            text = "In order to be able to take this quest, you have to complete the quest Unruly Neighbors or An Unwelcome Presence, depending on if you are horde or alliance.\n\nQuest links: http://www.wowhead.com/?quest=10000\nhttp://www.wowhead.com/?quest=9998",
            date = "2008-05-15T10:00:23-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10012#comments:id=288603",
