    [10025] = {
        {
            id = 1579605,
            score = 55,
            author = "111707",
            text = "To expand on these calculations given the following facts:\n\nThe base gain is 250 reputation per 8 https://www.wowhead.com/item=25744.\nIt takes 36000 reputation to reach Hostile from 0 Hated.\nIt takes 3000 reputation to reach Unfriendly from Hostile.\nIt takes 3000 reputation to reach Neutral from Unfriendly.\nThe human racial https://www.wowhead.com/spell=20599 increases reputation gains by 10%.\n\nFrom this, the following is the number of https://www.wowhead.com/item=25744 required to go from 0/36000 Hated to 0/3000 Neutral:\n\nFor non-humans without https://www.wowhead.com/spell=78634 or https://www.wowhead.com/spell=78635, it will take 1344 https://www.wowhead.com/item=25744.\nFor non-humans with https://www.wowhead.com/spell=78634, it will take 1280 https://www.wowhead.com/item=25744.\nFor humans OR non-humans with https://www.wowhead.com/spell=78635, it will take 1224 https://www.wowhead.com/item=25744.\nFor humans with https://www.wowhead.com/spell=78634, it will take 1176 https://www.wowhead.com/item=25744.\nFor humans with https://www.wowhead.com/spell=78635, it will take 1120 https://www.wowhead.com/item=25744.\n\nTaking into account holiday buffs such as https://www.wowhead.com/spell=61849 or https://www.wowhead.com/spell=95987:\n\nFor non-humans without https://www.wowhead.com/spell=78634 or https://www.wowhead.com/spell=78635, it will take 1224 https://www.wowhead.com/item=25744.\nFor non-humans with https://www.wowhead.com/spell=78634, it will take 1176 https://www.wowhead.com/item=25744.\nFor humans OR non-humans with https://www.wowhead.com/spell=78635, it will take 1120 https://www.wowhead.com/item=25744.\nFor humans with https://www.wowhead.com/spell=78634, it will take 1080 https://www.wowhead.com/item=25744.\nFor humans with https://www.wowhead.com/spell=78635, it will take 960 https://www.wowhead.com/item=25744.",
            date = "2011-11-24T03:24:34-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10025#comments:id=1579605",
        },
        {
            id = 23089,
            score = 28,
            author = "Ranoc",
            text = "Can be repeated up to Neutral reputation",
            date = "2007-01-23T04:49:57-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10025#comments:id=23089",
        },
        {
            id = 703319,
            score = 21,
            author = "39891",
            text = "To complete all the turn-ins quickly (168 of them going from full hated) do the first non repeatable quest once (yellow exclamation mark). Then target Arcanist Adyria, right click her and start mashing the following macro:\n\n/script SelectGossipAvailableQuest(1)\n/script CompleteQuest()\n/script GetQuestReward()\n\nYou'll have to right click Adyria once for each turn-in.",
            date = "2009-05-03T01:39:55-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10025#comments:id=703319",
        },
        {
            id = 1387374,
            score = 20,
            author = "261861",
            text = "After getting myself 1334 eyes to switch from Aldor to Scryers, I realised as I was handing them in that I had forgotten all about my guild perks.\n\nNon humans with no guild perks should still need 1334 eyes.\nNon humans with the level 4 guild perk need 1289 eyes.\nNon humans with the level 12 guild perk need 1224 eyes.\n\nMight save you at least some time farming, and imo, in this case, every damn minute counts. And oh, if my math turns out to be wrong, try telling it to me nicely. Thanks.",
            date = "2011-04-09T03:55:51-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10025#comments:id=1387374",
        },
        {
            id = 5147823,
            score = 18,
            author = "Mostunknown",
            text = "During the https://www.wowhead.com/spell=335148 50% (Outland Time walking) and being a human with https://www.wowhead.com/spell=2059910% and https://www.wowhead.com/spell=46668 for another 10%. May be im missing another buff?\n+70% rep.\n\nAs a human I was getting 425 each turn in.\n____________This is with Timewalking Outland AND Darkmoon Faire AND Human_____425rep per turn-in__________\n\nIt takes 36000 reputation to reach Hostile from 0 Hated.          85 x Turn-ins 36,125          680 x https://www.wowhead.com/item=25744\nIt takes 3000 reputation to reach Unfriendly from Hostile.          7 x Turn-ins 2,975             56 x https://www.wowhead.com/item=25744\nIt takes 3000 reputation to reach Neutral from Unfriendly.          7 x Turn-ins 2,975              56 x https://www.wowhead.com/item=25744\n\n----------------------------------------------------------------------Total ----99 x Turn-ins--42,075rep ---792 x https://www.wowhead.com/item=25744\n\n_____________This is just win Timewalking Outland AND Human_______400rep per turn-in__________\n\nIt takes 36000 reputation to reach Hostile from 0 Hated.          90 x Turn-ins 36,000          720 x https://www.wowhead.com/item=25744\nIt takes 3000 reputation to reach Unfriendly from Hostile.         8  x Turn-ins   3,200            64 x https://www.wowhead.com/item=25744\nIt takes 3000 reputation to reach Neutral from Unfriendly.         7 x Turn-ins    2,800            56 x https://www.wowhead.com/item=25744\n\n------------------------------------------------------------------Total -------105 x Turn-ins--42,000--------840 x https://www.wowhead.com/item=25744\n\n___________________This is just win Timewalking Outland_______375rep per turn-in__________\n\nIt takes 36000 reputation to reach Hostile from 0 Hated.          96 x Turn-ins 36,000          768 x https://www.wowhead.com/item=25744\nIt takes 3000 reputation to reach Unfriendly from Hostile.         8  x Turn-ins   3,000            64 x https://www.wowhead.com/item=25744\nIt takes 3000 reputation to reach Neutral from Unfriendly.         8 x Turn-ins    3,000            64 x https://www.wowhead.com/item=25744\n\n------------------------------------------------------------------Total -------112 x Turn-ins--42,000--------896 x https://www.wowhead.com/item=25744\n___I dont have anyone who is exalted with Aldor or Scryers except human characters, im assuming its 375 rep based on 50% of 250 is 125(125+250=375)___",
            date = "2021-04-07T11:57:35-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10025#comments:id=5147823",
        },
    },
