    [10040] = {
        {
            id = 193757,
            score = 87,
            author = "104079",
            text = "DO NOT be mounted when talking to the quest giver, or you will not receive your disguise.\n\nShadowy Initiate at 39,39\nShadowy Laborer at 39,41\nShadowy Advisor at 40,38",
            date = "2007-11-30T05:03:20-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10040#comments:id=193757",
