    [10085] = {
        {
            id = 25289,
            score = 95,
            author = "14232",
            text = "Even though the website says you need things slain, you don't. All you do is run through the cities until you see a Vision of the Forgotten. To see them, go to...\n\nSunspring Post: 32, 43 (I think) you'll hit it running from the water to the big central building\nLaughing Skull Ruins: 45, 23 just inside the entrance\nGaradar: 54, 36 near the bridge\nBleeding Hollow Clan Ruins (in Terokkar): 20, 62 head towards Unkor from the north.\n\nWith some luck, you can probably stay mounted for all of these.",
            date = "2007-01-26T18:46:44-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10085#comments:id=25289",
        },
        {
            id = 24667,
            score = 59,
            author = "Wihl",
            text = "Just a quick thing about this quest.. The Bleeding Hollow Ruins is not in Nagrand, it's in Terrokar. Just exit Nagrand from the south-east exit and you'll find it.",
            date = "2007-01-25T20:49:24-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10085#comments:id=24667",
        },
        {
            id = 344511,
            score = 14,
            author = "starsword",
            text = "Vision of the Forgotten whispers: It is a beacon. A remnant of a forgotten era.\nVision of the Forgotten whispers: They lack control... Oshu'gun calls to them...\nVision of the Forgotten whispers: Turn back, mortal... This is not your battle.\nVision of the Forgotten whispers: We are infinite... eternal.\nVision of the Forgotten whispers: You cannot stop them.",
            date = "2008-08-04T17:24:19-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10085#comments:id=344511",
        },
        {
            id = 346102,
            score = 4,
            author = "galacticlore",
            text = "Doing this will complete the quest, but will not trigger the Visions appearing and whispering things. So if you happen to care about those \"flavor\" things, dismount and enter the area on foot\n\nThis is not so. I've done all the areas by flying over them, and each time I've gotten the Visions' whispering. I was low to the ground, but not even close to being landed nor dismounted.\n\nThis is true as of right now, because as I type I'm doing the Bleeding Hollow ruins. I just now flew ove them, maybe 20 or so feet up (kind of hard to tell) and the visions both appeared and whispered.",
            date = "2008-08-06T13:33:26-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10085#comments:id=346102",
        },
        {
            id = 1037695,
            score = 3,
            author = "588924",
            text = "Now gives 500 rep with  The Mag'har",
            date = "2010-05-12T17:41:27-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10085#comments:id=1037695",
        },
    },
