        {
            id = 163274,
            score = 19,
            author = "87883",
            text = "just to know ;)\n\nThe Overlook is at 39,48.\nThe Stadium is at 35,50.\nBroken Hill is at 40,57.",
            date = "2007-10-05T11:12:59-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10106#comments:id=163274",
