    [10107] = {
        {
            id = 41727,
            score = 30,
            author = "Unbarc",
            text = "Follow-up quests:\nArmaments for Deception (http://www.wowhead.com/?quest=9928)\nRuthless Cunning (http://www.wowhead.com/?quest=9927)",
            date = "2007-02-24T18:24:49-06:00",
