        {
            id = 18080,
            score = 26,
            author = "Lustral",
            text = "Mummaki is located on the top floor of the largest structure, just east of the Ango'rosh Grounds.\n\nMummaki has 2 guards, each with only a few thousand HP.  I believe this quest is recommended to be done with a group of 2, but if you can output any amount of burst damage, it's very easy to do solo.",
            date = "2006-12-27T09:33:11-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10116#comments:id=18080",
        },
        {
            id = 61446,
            score = 20,
            author = "22655",
            text = "Daggerfen Poison Manual for the quest \"Secrets of the Daggerfen\" (http://www.wowhead.com/?quest=9848) lies on the same floor that  Mummaki resides, so make sure to pick that up.",
            date = "2007-04-03T07:30:24-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10116#comments:id=61446",
