    [10144] = {
        {
            id = 62930,
            score = 73,
            author = "40437",
            text = "The portals can be found east of Forward Commander Kingston (71,62).  You must collect 4 stones (Demonic Rune Stones) for EACH portal.  The stones are dropped from the demons that surround the portals, and because of their low hit points, they are easy kills.  Also, go inside of the portal to destroy it.\nThe alliance portals are located at:\nKaalez portal - (73,58)\nGrimh portal - (71,55)\nThe Horde locations are located at:\nXilus portal - (71,46)\nKruul portal - (73,38)\n\n*Caution - a level 60 Elite spawns randomly from the portals, so travel carefully.",
            date = "2007-04-06T13:20:16-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10144#comments:id=62930",
        },
        {
            id = 20892,
            score = 40,
            author = "301",
            text = "I might want to add that there are TWO pairs of portals. One south of the main road, one north. The ones north are for horde and the ones south are for alliance, they look the same, and the quest doesn't really mention this, so be aware of this.",
            date = "2007-01-16T20:47:27-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10144#comments:id=20892",
        },
        {
            id = 20795,
            score = 34,
            author = "RagingSage",
            text = "With Kingston's Primers in your inventory, simply kill the various mobs that spawn in the area around and between the two portals until you obtain enough Demonic Rune Stones.  You need 4 for each portal.  When you have 4 stones, just get close enough to click a portal, and when it \"opens\" it is disabled. Repeat for the other portal, with another 4 Stones.  (Keep Kingston's Primers for the turn-in.)",
            date = "2007-01-16T09:04:29-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10144#comments:id=20795",
        },
