    [10180] = {
        {
            id = 1574204,
            score = 47,
            author = "406368",
            text = "In case anyone is somewhat confused, he is NOT in some special side room near the entrance to the lobby.  Go INSIDE of the main lobby room which is the entrance to the [zone=3791] and then enter INSIDE the dungeon portal itself to find https://www.wowhead.com/npc=18933 for the turn-in.  The coordinates above are accurate to locate the lobby entrance.  If coordinates confuse some people, go into the eastern entrance in the Ring of Observance (outside area) and you will find it.\n\n*Update for patch 4.3",
            date = "2011-11-17T09:13:06-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10180#comments:id=1574204",
        },
        {
            id = 50492,
