    [10201] = {
        {
            id = 77178,
            score = 20,
            author = "Zentoph",
            text = "Definitely worth it for the quick easy experience, or gold if your 70.  Also, this is the only result I got while typing in \"mom\" in the search here.",
            date = "2007-05-03T14:40:17-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10201#comments:id=77178",
        },
        {
            id = 34285,
            score = 17,
            author = "22576",
            text = "Confirmed. Grek is immedately opposite Rakoria and does NOT have a yellow question mark above his head.\n\nTalk to him and ask him to try the oil. Once he's done talking, turn around and return to Rakoria.\n\nSimple enough once you realize there's no 'quest icon' over Grek's head.",
            date = "2007-02-11T19:56:17-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10201#comments:id=34285",
        },
        {
            id = 22472,
            score = 14,
            author = "apparentbliss",
            text = "Prereq/leadin: \"Olemba Seed Oil\" (http://www.wowhead.com/?quest=9993).\n\nNote that Grek is directly across the street from Rakoria, but does not have a yellow question mark above his head.",
            date = "2007-01-21T16:43:24-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10201#comments:id=22472",
        },
        {
            id = 51710,
            score = 7,
            author = "Zugzugx",
            text = "I actually forgot where I took this quest and by the time i went to do it i had no dea the person was across the quest giver.. for those who forgot also coords are 50,45 in stonebreaker hold.",
            date = "2007-03-15T16:14:32-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10201#comments:id=51710",
        },
        {
            id = 262850,
            score = 6,
            author = "76224",
            text = "For those looking to stockpile these without making innumerable alts or overpaying for them on the AH (at least on my server), find an enchanter who is honored with the Zandalar Tribe (Zul'Gurub Rep). They can make these, even though they're a tad expensive.\n\nHealing: http://www.wowhead.com/?item=20757\nDamage: http://www.wowhead.com/?item=20756\n\nFor the mats, the shards will come from virtually any blue above level 51, before being replaced by Small Prismatic Shards around 58ish. The fastest way to farm these would most likely be in Scholomance. Jump off the bridge in the beginning of the instances, kill Rattlegore, kill Ras, unequip your gear, die, run in, run out, then reset. For those that have Fire Resistance gear, Blackrock Depths offer an alternative, given Incendius will always drop something that will disenchant into these and he and his adds are exclusively fire damage...\n\nAs for the flowers, Firebloom is best farmed in Tanaris and Purple Lotus in Azshara. If you're looking to make some good cash, I'd recommend farming the Purple Lotus in Hinterlands, and making a dash over to snatch up the Ghost Mushrooms while they're on the respawn timer.\n\nEdit: the healing recipe requires friendly, and the damage requires honored. Forgot to differentiate.",
            date = "2008-03-29T19:26:10-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10201#comments:id=262850",
        },
    },
