        {
            id = 89546,
            score = 18,
            author = "53461",
            text = "Unyielding Footmen are lined up in a nice row at 58,78.\n\nUnyielding Sorcerers are congregated around the area 54,79.\n\nUnyielding Knights patrol the entire area including behind the row of Unyielding Footmen so it shouldn't be too hard to find 8 of them while doing the rest.\n\nNOTE: Try to pull the Unyielding Knights away from other mobs as they call for help.",
            date = "2007-05-24T12:51:55-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10220#comments:id=89546",
        },
        {
