    [10231] = {
        {
            id = 22493,
            score = 73,
            author = "13785",
            text = "He and his friends are at 43,29",
            date = "2007-01-21T17:37:45-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10231#comments:id=22493",
        },
        {
            id = 11977,
            score = 67,
            author = "6934",
            text = "Dirty Larry is the NPC you'll need to find and talk to for this quest. He can be found in the northwesternmost point of lower Shattrath with two of his buddies. Upon asking for the book he'll say a few lines and give you a countdown till he attacks you. During this countdown you are allowed to get the first shot. Dirty Larry himself is a 66 elite and his friends are 66 non elites. They are NOT immune to snaring/rooting, so kiting is a definite option if you're looking to solo this. If you kite him too far(past the nearby bank) he will reset.\n\nI was able to solo this guy at 64 as a frost mage, here's how I did it:\n1. Start the event.\n2. Sheep one of his friends instantly after talking to Larry.\n3. After one is sheeped, kill the other.\n4. Larry should be on you now kite him around. I used my water elemental to put up a little DPS and to help with frost nova'ing him. Keep up the kiting/dpsing till he dies -- remember to keep the other mob sheeped. I had to use cold snap and 3 frost shields.\n\nThis may be extremely tough to solo for certain classes.",
            date = "2006-12-09T03:24:38-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10231#comments:id=11977",
        },
        {
            id = 23768,
            score = 35,
            author = "10621",
            text = "It is possible to complete the quest if a different group defeats Dirty Harry.  I happened to ride up as an alliance group (im horde) just finished him up, and I got the \"Complete\" thing to pop up, and was able to talk to Harry and have him give me the next quest.",
            date = "2007-01-24T14:25:10-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10231#comments:id=23768",
        },
        {
            id = 230975,
            score = 31,
            author = "95411",
            text = "Now that we've heard like 15 people say they've soloed it, you might find yourself asking: \"But what if i can't?\"\n\nI just went to the nearby battlemasters and asked someone to help me. People waiting for BG's are often so bored they'll do it gladly and free of charge.",
            date = "2008-02-07T07:48:32-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10231#comments:id=230975",
        },
        {
            id = 202493,
            score = 6,
            author = "Zurr",
            text = "if it takes you too long to beat him then you will not get a complete.",
            date = "2007-12-16T18:56:27-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10231#comments:id=202493",
        },
    },
    [10232] = {
        {
            id = 5180,
            score = 38,
            author = "zutroy",
            text = "The Scrap Fields are located at 48, 57.",
            date = "2006-11-29T17:42:09-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10232#comments:id=5180",
        },
        {
            id = 51255,
            score = 11,
            author = "33478",
            text = "Quick note to take this quest: http://www.wowhead.com/?quest=10333\n\nBefore you start this, can get them both done at the same time.",
            date = "2007-03-14T19:12:24-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10232#comments:id=51255",
        },
        {
            id = 479977,
            score = 4,
            author = "53205",
            text = "Don't try to AoE too many of these. I've been AoEing everything for loremaster at 80, and these guys just tore me apart with their dynamite.",
            date = "2008-11-30T09:00:25-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10232#comments:id=479977",
        },
        {
            id = 354949,
            score = 3,
            author = "138722",
            text = "When fighting the Mo'arg Doomsmith it would be a good idea to sidestep them as soon as they cast \"Doomsaw\". It will go through you in a straight path and return to the mob in a straight line. You can avoid the damage if you move out of the way.\n\nThe Gan'arg Engineer will \"Throw Dynamite\". You can dodge the 2nd and 3rd throw if you sidestep them as well. Occasionally I could avoid damage from all three throws, but I started strafing before they started throwing.\n\nAlso, it would be a good idea to pick up http://www.wowhead.com/?quest=10234, before starting this quest.\n\nEdit: If two Mo'arg Doomsmiths are fighting near other, the \"Doomsaw\" will return to the nearest Mo'arg Doomsmith. It was pretty funny when my Mo'arg Doomsmith killed a druid that accidently ate the \"Doomsaw\" from both mobs.",
            date = "2008-08-17T01:34:26-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10232#comments:id=354949",
        },
        {
            id = 486393,
            score = 3,
            author = "262842",
            text = "When fighting the Gan'arg Engineers it's best to run large circles around them, i.e. hold down \"a\" and \"e\" at the same time.  If you're anything like me, this is gonna make you SUPER dizzy and give you a headache, but it keeps you from dieing.  They won't lead their target so all the bombs will land behind you.  If you try running smaller circles they luck out and hit you every so often, especially if you get two or more at a time. Worked for me great, 0 bomb damage using this method.",
            date = "2008-12-03T02:37:44-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10232#comments:id=486393",
        },
    },
    [10233] = {
        {
            id = 22666,
            score = 63,
            author = "13008",
            text = "You only need one torch which drops from the Sunfury Flamekeepers that patrol around the camp.",
            date = "2007-01-22T03:20:50-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10233#comments:id=22666",
        },
        {
            id = 26674,
            score = 25,
            author = "15416",
            text = "You dont' have to run around to all of the tents.  Just clear your way to one, torch it, wait a few seconds for it to stop burning, and torch it again.  Worked for me x 4.",
            date = "2007-01-28T21:03:49-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10233#comments:id=26674",
        },
        {
            id = 25423,
            score = 20,
            author = "15528",
            text = "Tents are the tent-looking things. (Durr!)  These are scattered throughout, and both dome-shaped and flap tents count.\n\nBallista are the arrow-firing contraptions near archers.  I found these near the upper levels of the base.",
            date = "2007-01-27T00:04:27-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10233#comments:id=25423",
        },
        {
