            date = "2007-02-01T07:18:33-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10233#comments:id=28768",
        },
        {
            id = 27056,
            score = 14,
            author = "14704",
            text = "You can torch two objects with one throw if you stand between the two.",
            date = "2007-01-29T10:35:14-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10233#comments:id=27056",
        },
    },
    [10234] = {
        {
            id = 36433,
            score = 5,
            author = "11267",
            text = "I got this quest last night, at level 68.  Check the comments area for Papa Wheeler; you have to complete some quests from the ethereal to his right before he'll give you anything.",
            date = "2007-02-15T12:05:38-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10234#comments:id=36433",
        },
        {
            id = 428845,
            score = 5,
            author = "Ergates",
            text = "Be warned that the Gan'arg engineers have a dynamite attack at low health that does a ridiculous amount of fire damage; watch out if you get more than one on you, and be ready with any interrupts.",
            date = "2008-11-02T18:07:55-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10234#comments:id=428845",
        },
        {
            id = 67089,
