    [10247] = {
        {
            id = 27635,
            score = 22,
            author = "15174",
            text = "He is around 37,63",
            date = "2007-01-30T07:39:22-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10247#comments:id=27635",
        },
        {
            id = 824479,
            score = 12,
            author = "392114",
            text = "So as i went to solo this quest i found some difficulties. ELITE ELITES EVERYWHERE! As i raised my axe to kill them they disarmed me, they took me into prison, wanting to turn me into a demon! As i escaped i was able to use chains of ice to slow down the guards and run away. About one day later i remember very little i only remember walking into a jungle, seeing a giant flower and passing out. I woke up with my clothes ripped and seing lots of animals walking nearby. i saw a electrical beacon on top of a slope. I walked and walked, untill i got ambushed by a tiger. I fought and i killed it, but i was mortally wounded. I struggled to stay alive long enough to exit what seemed to be a dome. I tore the rest of my shirt and used it as a bandage so i did not die from the bleeding. Then a sign of hope....i saw a sign directing me to the way to area 52. I tried to walk, but a few hundred feet later i fell down. I was trying to crawl to the city...but it was of no use, then i remembered how i was thaught to extract healing ingredients out of the rocks in neatherstorm, so with my last of strengt i got some of them, poured some of the liquid i carry around on it and i got a healing potion, when i drank it the pain stopped and i regained some of my strenght, i stood up looking around, then i saw a neather ray. I used a nearby stick to pummel it as hard as i could, but then it stung me. After a few second a medium sized wound opened up and the poison started to spread, i immedatley fell dying along with the neather ray. Then i got a feeling to puke, but my time was out and i died. Awaikening i found I WAS DREAMING, as i logged into WoW i found i very easely soloed a 3-man talking quest.",
            date = "2009-08-27T14:23:46-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10247#comments:id=824479",
        },
