    [10252] = {
        {
            id = 39911,
            score = 146,
            author = "20623",
            text = "Stop posting kill results and specific coords, that info isn't very useful as the mobs are wide-spread.  Click on the item to see what the recorded drop percentage is.  According to the current percentages, the items should all drop within around 5 kills, if not, then make sure you are killing the right mobs, otherwise just keep killing and it will drop soon enough.\n\nHere are the maps for recorded mob locations:\nMountain Gronn: http://www.wowhead.com/?npc=19201\nGreater Windroc: http://www.wowhead.com/?npc=17129\nAged Clefthoof: http://www.wowhead.com/?npc=17133",
            date = "2007-02-21T12:24:09-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10252#comments:id=39911",
        },
        {
            id = 33781,
            score = 63,
            author = "skywalk",
            text = "To make the Mountain Gronn portion of the quest extremely easy, try to find one fighting ogre(s) up the path starting @ 28,31. The ogres will get the Gronn down a bit before they die, so just engage the elite before he finishes off the ogre.\n\nI found one fighting 2 ogres and he wound up @ 41% before he aggrod to me after finishing the ogres off.",
            date = "2007-02-10T21:03:32-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10252#comments:id=33781",
        },
        {
            id = 13246,
            score = 52,
            author = "6934",
            text = "This quest is only elite because of the mountain gronn eyeball.  The mountain gronn itself is easily solable(I did it at 64) and the eye dropped on kill #1.  The windrocs you need are located in the Northwestern portion of the zone and the Aged Clefthooves(the hardest part) are located mianly in the Southwest.  It took me an hour of farming these clefthooves to get the blubber to drop, as they aren't as populated as most mobs in the zone ~ very unenjoyable hour.",
            date = "2006-12-11T02:39:52-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10252#comments:id=13246",
        },
        {
            id = 55214,
            score = 33,
            author = "Ambushed",
            text = "The drop rate is inaccurate, because it is counting the total kills... ever... for any reason, and comparing it to the number of times this particular quest item has dropped",
            date = "2007-03-22T05:38:01-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10252#comments:id=55214",
        },
        {
            id = 121758,
