    [10255] = {
        {
            id = 21405,
            score = 45,
            author = "Amberley",
            text = "The antidote is an insta-cast item. So just walk up to a hulking helboar, say hi, shove the anti dote thru his throat.\n\nAnd then just watch him grow and get stronger. Of course this will leave you no choice but to kill him, which will complete the quest.\n\nSo dont try to chain nova him as a frost mage ( like i did ) for 45 seconds, rather just click the anti dote, kill the boar, walk back to misses Redmane and claim your reward",
            date = "2007-01-18T15:22:32-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10255#comments:id=21405",
        },
        {
            id = 28161,
            score = 25,
            author = "Caffi",
            text = "About the Dreadtusk:\n\nIt isnt a spawn at all, you use the antidote on a Hulking Helboar, and it turns into a Dreadtusk.",
            date = "2007-01-31T08:41:28-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10255#comments:id=28161",
        },
        {
            id = 386867,
