            author = "Blackraptor",
            text = "A good idea would be to lower the Helboar's HP before applying the antidote.  As a paladin, I stunned the helboar at 10% and applied the antidote for an extremely easy kill.",
            date = "2008-09-24T18:16:41-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10255#comments:id=386867",
        },
        {
            id = 483786,
