    [10256] = {
        {
            id = 23825,
            score = 165,
            author = "15241",
            text = "Coordinates above (53, 67) are confirmed.\n\nHe is a large rock demon with approximately 22.7k health. Screenshot submitted.",
            date = "2007-01-24T15:48:31-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10256#comments:id=23825",
        },
        {
            id = 23194,
            score = 87,
            author = "MrGorun",
            text = "Find Apex at 53, 67 (http://www.wowhead.com/?npc=19940), drop Crystal, then go back and use orb.",
            date = "2007-01-23T09:54:21-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10256#comments:id=23194",
        },
        {
            id = 1863582,
            score = 37,
            author = "1127104",
            text = "Since most comments here are entirely irrelevant to his location. I'll post the area I found him at. 51.85/61.34, North of the bridge that is west of sunfury hold.\n\nEDIT: for typos",
            date = "2013-06-06T20:02:36-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10256#comments:id=1863582",
        },
        {
            id = 31322,
            score = 33,
            author = "19634",
            text = "Solo'd as a 70 feral druid. I ended up going bear form and slowly backing him up down the road closest to him all the while dpsing with maul and mangle. When I kept moving, the adds he spawned did not aggro on me, they just sat in the middle of the road. (might have just been bugged though)\n\nA couple of side notes:\nApex hit me (with 11k armor (53% mitigation) in bear) for around 200 so it was very managable and could heal through it.\n\nHe was not immune to Bash nor Cyclone. I did not try roots as I only needed Cyclone to get heal off.\n\nHe does a Thunder Clap type move that slows your movement speed (might have done something else as well, but i can't recall). So if you are trying to simply kite him around, try not to get to close.\n\nLastly, I cannot confirm this as I did not engage his adds, but other druids have told me that his adds are rootable.",
            date = "2007-02-05T15:30:34-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10256#comments:id=31322",
        },
        {
            id = 2298507,
            score = 31,
            author = "Aurleis1",
            text = "Video Guide: https://www.youtube.com/watch?v=OzpcZN9FAaQ\n\n1.  https://www.wowhead.com/quest=10256\n•\009Accept the quest, https://www.wowhead.com/quest=10256, from https://www.wowhead.com/npc=19481 at coords 58.4, 86.6 (Top level inside a Violet Tower at Kirin'Var Village).\n•\009Exit the Mage Tower and travel north to the area of coords 53, 67.\n•\009Kill https://www.wowhead.com/npc=19940, and loot https://www.wowhead.com/item=28786 from its corpse.\n•\009Travel south, back to the Violet Tower, and enter it at coords 57.8, 86.2.\n•\009Go to the top of the tower.\n•\009Use https://www.wowhead.com/item=28786 near Archmage Vargoth's Orb.\n•\009Once the identity of the key master is discovered to be https://www.wowhead.com/npc=17976, turn in the quest to https://www.wowhead.com/npc=19481.",
            date = "2016-01-15T15:21:19-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10256#comments:id=2298507",
        },
    },
