        },
        {
            id = 24016,
            score = 48,
            author = "mrgamer",
            text = "This quest is damn hard, the power-pack is IN A MINE, so you've to find the entrance. Outside the mine there is a guy that will give you a quest for burn corpses (it helps a lot if you can't stealth), and by the power pack you will find another consortium guy that will ask you to slain an easy mob inside the cave.\n\nDone that, you can use your powerpack at position 71, 39 in celestial ridge.",
            date = "2007-01-24T20:45:18-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10270#comments:id=24016",
        },
        {
            id = 34129,
            score = 45,
            author = "Rumpelstiltz",
            text = "The [Teleporter Power Pack] is at 60,41 inside the cave. To get to it, stay left all the way down after entering the cave - follow the green crystals (Protectorate Tracer).\n\nUse [Protectorate Igniter] you got from the quest The Flesh Lies (59,45) on Withered corpses to avoid them turning into Parasitic Fleshbests, which are extremly annoying.\n\nYou get the quest Arconus the Insatiable from the NPC just infront of the Power Pack. Arconus the Insatiable is at 60,39 in the very same cave.",
            date = "2007-02-11T14:38:52-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10270#comments:id=34129",
        },
    },
    [10271] = {
