        {
            id = 1401792,
            score = 23,
            author = "717646",
            text = "As of 4.1.0, to use the item given to you, you don't have to kill the drakes/dragons. Use the device outside of their aggro range and you'll get the essence.\nThe drake/dragon will shrink and then disappear.\n\nIf you try to use it while fighting one, you'll get \"You're in combat\".\nThe use for this needs to be confirmed, but that's how it worked for my 69 Rogue, on Alexstrasza.",
            date = "2011-04-27T16:58:46-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10271#comments:id=1401792",
