        },
        {
            id = 26743,
            score = 24,
            author = "17446",
            text = "No exclamation point over the guy's head, just start a dialogue with him at 58, 31.\n\nSpawns 2 58 nether-stalkers, then he himself (lvl 69) turns hostile. Quite easy though.",
            date = "2007-01-28T23:36:42-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10273#comments:id=26743",
