        {
            id = 68678,
            score = 4,
            author = "MelindiAgamaggan",
            text = "You actually need to go to 60 30 to speak to him and kill him not the place where you speak to his image.",
            date = "2007-04-17T13:18:59-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10273#comments:id=68678",
        },
        {
            id = 263236,
            score = 4,
            author = "Fyurae",
            text = "It should be noted that after you open the dialog with him, he will lead you to the fringes of the watch post to speak with you 'privately'. If you stay close to him you can run past him and up against or even behind the rocks he stands in front of, as previously suggested, to stay out of the range of his guards. He turns hostile quickly, but does not actually attack you for some time (longer than I gave him).",
            date = "2008-03-30T12:19:27-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10273#comments:id=263236",
        },
        {
            id = 2298433,
            score = 3,
            author = "Aurleis1",
            text = "Video Guide: https://www.youtube.com/watch?v=wrYKF-nyQPc\n\n1.  https://www.wowhead.com/quest=10273\n•\009Accept the quest, https://www.wowhead.com/quest=10273, from https://www.wowhead.com/npc=20110 at coords 71.2, 35.2 (Celestial Ridge).\n•\009Travel west, to the Protectorate Watch Post, located at coords 58.2, 31.4.\n•\009Speak with https://www.wowhead.com/npc=20071, and select the dialogue text.\n•\009Follow https://www.wowhead.com/npc=20071 east to coords 60.0, 39.9.\n•\009After https://www.wowhead.com/npc=20071 turns hostile, kill it.\n•\009Travel west, back to Celestial Ridge, to coords 71.2, 35.2.\n•\009Turn in the quest to https://www.wowhead.com/npc=20110.",
            date = "2016-01-15T14:35:12-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10273#comments:id=2298433",
        },
    },
    [10274] = {
        {
            id = 29137,
            score = 632,
            author = "plasmasnakemg",
            text = "If you're neutral with the Netherwing from the Shadowmoon Valley quest line, make sure to click \"At War\" before you use the item to summon him. It'll put you right in combat, you won't be able to attack him and he'll rip you a new one and you can't click \"At War\" while in combat.\n\nSolo'd as a level 70 mage, 40 fire and 21 frost. He can be slowed and frost nova'd, fairly easy to kite around, kind of fast if not slowed, have a healing pot ready just incase.\n\nAlso, killing the nether dragons in the area does not decrease your rep with Netherwing, so don't worry about doing this quest and the ones before after the Shadowmoon Valley quest line. :)",
            date = "2007-02-01T20:25:48-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10274#comments:id=29137",
        },
        {
            id = 1647663,
            score = 155,
            author = "Blaix",
            text = "If you cannot attack this NPC when you summon him (he will just rest on the ground, looks like he is friendly) change your reputation with Netherwing to \"At War\". You should be able to call him again and he will attack you. I can confirm I did not gain/lose any rep by killing this NPC (started and ended at 999/1000 exalted with Netherwing).",
            date = "2012-04-01T21:43:23-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10274#comments:id=1647663",
        },
        {
            id = 2298430,
            score = 100,
            author = "Aurleis1",
            text = "Video Guide: https://www.youtube.com/watch?v=2ew2H9JkazM\n\n1.  https://www.wowhead.com/quest=10274\n•\009Accept the quest, https://www.wowhead.com/quest=10274, from https://www.wowhead.com/npc=20110 at coords 71.2, 35.2 (Celestial Ridge).\n•\009Go to your character's reputation to ensure that you are not Neutral or higher reputation with the [faction=1015] faction.  If you are, click [faction=1015] and check the box \"At War.\"\n•\009Travel south to coords 72.2, 43.4, near a pile of bones, and click on the https://www.wowhead.com/item=29101, you were provided.\n•\009https://www.wowhead.com/npc=18544 will be summoned, and come from the south.  When this happens, kill https://www.wowhead.com/npc=18544.\n•\009Travel north to coords 71.2, 35.2.\n•\009Turn in the quest to https://www.wowhead.com/npc=20110.",
            date = "2016-01-15T14:33:05-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10274#comments:id=2298430",
        },
        {
            id = 6062907,
            score = 64,
            author = "geekySmurfer",
            text = "Go to /way 72.30 43.58\nHit C > Reputation Tab > Scroll down to the Burning Crusade section\nClick on Netherwing > hit checkbox for At War\nUse the horn Challenge of the blue flight\nKill Veraku\nSwitch the reputation so you are not at war",
            date = "2025-02-11T06:20:01-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10274#comments:id=6062907",
        },
        {
            id = 45419,
            score = 45,
            author = "Mayday",
            text = "For all you Druids here, remember it's a dragon!\n\nThis one can also be sleeped, use Starfire > Sleep, Starfire > Sleep, etc.\nNot a single healthpoint lost during this fight.",
            date = "2007-03-03T03:13:56-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10274#comments:id=45419",
        },
    },
