    [10289] = {
        {
            id = 76459,
            score = 16,
            author = "Reversion",
            text = "I recieved a \"You do not meet the requirements for this quest.\" error when I tried to do it at 58. Strange.\n\nEDIT: I figured out what the problem was. I did this quest (http://www.wowhead.com/?quest=10291) before trying to do this one. You can start the chain with the linked quest.  You don't necessarily have to do these first three quests. However, I would suggest doing it for good rep/XP rewards if you have the option.",
            date = "2007-05-02T08:15:38-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10289#comments:id=76459",
        },
        {
            id = 1462862,
            score = 9,
            author = "Sagentine",
            text = "If this quest doesn't work for you then you need to abandon it, dismount, and accept it again.",
            date = "2011-07-06T20:05:53-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10289#comments:id=1462862",
        },
        {
            id = 1580508,
            score = 6,
            author = "406368",
            text = "A problem still persists in patch 4.2.2 if you have already completed the subsequent quest https://www.wowhead.com/quest=10291 (Horde) / https://www.wowhead.com/quest=10140 (Alliance).  Either via flying yourself there, or starting that quest in each faction's main fortress before seeing this quest.  This usually occurs by reverse questing in this zone (IE: coming out of Shattrath and questing INTO Hellfire, instead of the old Blizzard method of questing through the Dark Portal into Hellfire and then OUT towards other zones.\n\nUnfortunately this will become an Uncompleted (yet completed) quest if players are trying to do the https://www.wowhead.com/achievement=1271 (Horde) / https://www.wowhead.com/achievement=1189 (Alliance).",
            date = "2011-11-25T11:45:31-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10289#comments:id=1580508",
        },
        {
            id = 646676,
            score = 2,
            author = "41236",
            text = "If you try to do this quest coming from Thrallmar it will say \"quest has already been completed.\" I came in at 56 and grinded  out a level and a half. But I did get to complete one quest while I was there and it was the next one \"report to Nazgrel\". Though I couldn't go on because I wasn't 58.\n\nStrange indeed.",
            date = "2009-03-18T09:39:32-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10289#comments:id=646676",
        },
        {
            id = 821667,
            score = 0,
            author = "299967",
            text = "If you're a deathknight and went through the Dark Portal and got the quest Through the Dark Portal (see above, it's the beginning of the chain), then completing this quest will give you the 50 quests completed achievement http://www.wowhead.com/?achievement=503).",
            date = "2009-08-24T17:35:24-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10289#comments:id=821667",
        },
    },
    [10290] = {
        {
            id = 30869,
            score = 24,
            author = "Auriella",
            text = "Also found at 44,21",
            date = "2007-02-04T21:29:30-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10290#comments:id=30869",
        },
        {
            id = 168537,
            score = 20,
            author = "72155",
            text = "Soloed with a level 70 Protection specced Paladin with average gear. This is how:\n\nUsed Improved Righteous Fury, (http://www.wowhead.com/?spell=20470) Holy Shield (http://www.wowhead.com/?spell=27179) and Blessing of Sanctuary (http://www.wowhead.com/?spell=27168).\nOpened with Avenging Wrath (http://www.wowhead.com/?spell=31884) so that Forbearance (http://www.wowhead.com/?spell=25771) would have faded in case I needed to bubble (http://www.wowhead.com/?spell=1020). If you're with the Alliance, proccing the DoT from Seal of Vengenace (http://www.wowhead.com/?spell=31801) while AW (http://www.wowhead.com/?spell=31884) is active will cause it to keep the 30% bonus damage even after it expires.\nJudged (http://www.wowhead.com/?spell=20271) a Seal of Wisdom (http://www.wowhead.com/?spell=27166) to regen mana, then used Seal of Vengenace (http://www.wowhead.com/?spell=31801) for the rest of the fight.\n\nWhen the big one (http://www.wowhead.com/?npc=18885) died, I usually had 30-50% Health and ~10% mana left. The small ones were relatively easy to kill with a judged (http://www.wowhead.com/?spell=20271) and an active Seal of Wisdom (http://www.wowhead.com/?spell=27166) (they do around 100 damage to someone with 10k armor, which was fully blocked each time). Of course, it's not necessary to kill them, since they don't drop anything, and despawn shortly after leaving combat.\n\nI've seen Hunters solo this as well, by just nuking them, spam healing (http://www.wowhead.com/?spell=27046) their pets, then running out of range to Feign Death (http://www.wowhead.com/?spell=5384).\n\nHope it helped :)",
            date = "2007-10-14T17:28:25-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10290#comments:id=168537",
        },
        {
            id = 23959,
            score = 19,
            author = "Prozen",
            text = "Giants around 40,66 (68 elites)",
            date = "2007-01-24T19:03:48-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10290#comments:id=23959",
        },
        {
            id = 32765,
            score = 16,
            author = "20276",
            text = "Key to fewer adds seems to be stunning them.",
            date = "2007-02-08T17:00:15-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10290#comments:id=32765",
        },
        {
            id = 247589,
            score = 6,
            author = "Terc",
            text = "Hehe, solo'd by a 100% PvE healing spec Priest (0 points shadow) by SW:P kiting them back to Area 52 and fearing them every time they caught up. When the guards netted them, smitespam!\n\nTook a while, but I couldn't find anybody to group with and I couldn't kill them any other way.",
            date = "2008-03-03T23:30:44-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10290#comments:id=247589",
        },
    },
