    [10293] = {
        {
            id = 24092,
            score = 36,
            author = "WaddoWaddy",
            text = "Cragskaar paths around with the other Farahlite Giants (roughly 48, 19). He's killable with just two people, though, like the other giants, he splits into smaller Cragskaar fragments, so you'll want to clear the area to avoid unnecessary adds.",
            date = "2007-01-24T23:44:39-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10293#comments:id=24092",
        },
        {
            id = 36982,
            score = 35,
            author = "24402",
            text = "This can be done as a Warlock without kiting with any spec.  Enslave the named elite demon at Forge Base Gehenna and use it to tank Crag.  Leave the fire attack on autocast but save the AoE ability for when he spawns an add.  If you let the demon engauge and fire off two attacks he should maintain aggro the entire fight and you can unload on Crag.",
            date = "2007-02-16T12:05:45-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10293#comments:id=36982",
        },
        {
            id = 225075,
            score = 17,
            author = "118228",
            text = "As Gape pointed out earlier, the absolute essential is to stun just before 75%, 50 % and 25%. If you do that and damage him through 75, 50 and 25%, then YOU WON'T GET ANY ADDS AT ALL. Naturally, that makes it dramatically easier.",
            date = "2008-01-27T12:30:22-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10293#comments:id=225075",
        },
        {
            id = 402621,
            score = 6,
            author = "Menjina",
            text = "The level requirement of Level 67 is wrong. Because the pre-quest\nhttp://www.wowhead.com/?quest=10290 requires Level 68.\nSo it is not possible to do this quest @ 67.",
            date = "2008-10-11T06:52:11-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10293#comments:id=402621",
        },
        {
            id = 335049,
            score = 4,
            author = "Mairin",
            text = "Enslaving Silroth at Forge Base: Gehenna still works as of 2.4.3, even accidently got another giant add (should have pulled him out of the area) and still killed Cragskaar before I looted and left the demon to his fate by running away =) Barely even healed him either, Silroth is just imba.",
            date = "2008-07-24T13:55:04-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10293#comments:id=335049",
        },
    },
    [10294] = {
        {
            id = 20835,
            score = 52,
            author = "5883",
            text = "There are two types of mobs you can kill to get the specified quest item.\n\n1.) Collapsing Voidwalker\n\n- These will self destruct at 10% hp, or simply blow up if you kill them yourself. If you are in melee range you will take roughly 1500 damage. Killing them or getting them to 10% with a ranged attack is your best bet. As a rogue, I dps'd them to around 20%, then gouged fired a couple arrows at them causing them to self destruct, safely away from me.\n\n2.) Vacillating Voidwalker\n\n- These ones just have a shadowbolt spam attack for roughly 500 damage per hit. Kill them asap.\n\nBoth kinds can be stuunned, incapacitated, and bleed effects work as well.",
            date = "2007-01-16T14:57:59-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10294#comments:id=20835",
        },
        {
            id = 29489,
            score = 22,
            author = "19523",
            text = "Yeah, Vacillating Voidwalker absorbs your first school of magic so use something that's not your main spell school (for casters ofc) Blood Elf Palaidn can use Mana Tap then they will absorb arcane school, so your holy is good :) Don't ever use holy spell first!",
            date = "2007-02-02T14:11:03-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10294#comments:id=29489",
        },
        {
            id = 21321,
            score = 21,
            author = "Arx4",
            text = "Cursor 76,64.and all the way through the edge you can find more.",
            date = "2007-01-18T10:52:52-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10294#comments:id=21321",
        },
        {
            id = 200708,
            score = 16,
            author = "95798",
            text = "Void Ridge is just south-east of the Dark Portal, it's center is 80, 67.\n\nThe best way to get there (horde) is to ride east from Spinebreaker Post, through a path in the mountains that begins at 70, 67. Alliance has a FP right next to the mountain pass, GG.\n\nTwo kinds of mobs to deal with. They're a pain in the butt imo, but a little knowledge goes a long way:\n\nCOLLAPSING voidwalkers: When they have low health, they blow themselves up. If you kill them yourself, they still blow up. Not a small amount either, 1500 damage. If you're a melee class, keep your health up, if you land a last-second crit you could kill yourself. Best bet is to just run when you see them start casting \"collapse.\"\n\nVACILLATING voidwalkers: They will use and gain resistance to whatever magic you FIRST attack them with.  For blood elves this means if you open up with Mana Tap, they will gain resistance to arcane and spam arcane missiles. This is A Good Thing, as it  means you are free to then use fire, shadow, frost, holy, whatever magic you please.\n\nAnd yeah, 1-3 quest items per kill = about 20 kills.",
            date = "2007-12-13T12:42:17-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10294#comments:id=200708",
        },
        {
            id = 301423,
            score = 7,
            author = "cruelwarlock",
            text = "If you are a rogue don't use kidney shot while they are collapsing, or just before the reach 10%. If you do they won't re-cast self destruct and you kill to either melee them down (taking 1500 damage) or try and range them down.",
            date = "2008-06-08T01:50:03-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10294#comments:id=301423",
        },
    },
    [10295] = {
        {
            id = 20945,
            score = 43,
            author = "10501",
            text = "Void Stones are at 80,79. the purple crystals.\n\nhe has 2 adds so be careful",
            date = "2007-01-17T02:36:38-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10295#comments:id=20945",
        },
        {
            id = 20979,
            score = 42,
            author = "12521",
            text = "The best way to handle this guy is to take his 2 adds out first. He consumes one when he drops to 20% or so and it restores him back to 100% health. Him doing this twice could = your death.",
            date = "2007-01-17T05:35:00-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10295#comments:id=20979",
        },
        {
            id = 22126,
            score = 18,
            author = "Farmbuyer",
            text = "The only problem I had was that his corpse vanishes in about 8 seconds, so loot it quickly.",
            date = "2007-01-20T15:46:19-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10295#comments:id=22126",
        },
        {
            id = 197368,
            score = 2,
            author = "100154",
            text = "For those who do not have co ords, the void stones are all the way in, on the south east cliff, just before you fall off. Good luck with him!",
            date = "2007-12-07T09:35:26-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10295#comments:id=197368",
        },
        {
            id = 385566,
            score = 2,
            author = "213403",
            text = "Level 61 Subtlety Rogue\n~4k health\n\nDid this quest today.  Easiest thing to do is make sure there are no other voidwalkers patrolling, then use the warp device, THEN stealth.\n\nWhen you hit him, open with a Cheap Shot, the stun kept him from spawning adds, although when I did kill him he was still off the ground, so I had to reach up pretty high to loot him! ;)",
            date = "2008-09-23T16:03:26-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10295#comments:id=385566",
        },
    },
    [10296] = {
        {
            id = 32425,
            score = 40,
            author = "Pedala",
            text = "You need to save thralls on Old Hillsbrad Foothills to get access to this quest, and this instance.",
            date = "2007-02-07T20:34:34-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10296#comments:id=32425",
        },
        {
            id = 14464,
            score = 38,
            author = "9110",
            text = "The Black Morass is the old Blasted Lands, back when the Swamp of Sorrows contained the Blasted Lands area. In this instance you must defend Medivh while he opens the Dark Portal or your world will end. The Dark Portal is of the same model of that from Warcraft 2.",
            date = "2006-12-12T21:48:48-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10296#comments:id=14464",
        },
        {
            id = 52229,
            score = 24,
            author = "34072",
            text = "Prereq:\nhttp://www.wowhead.com/?quest=10285",
            date = "2007-03-16T16:12:58-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10296#comments:id=52229",
        },
        {
            id = 1203228,
            score = 13,
            author = "75768",
            text = "This quest chain is no longer necessary to enter Black Morass, tested 12/3/10",
            date = "2010-12-03T00:37:47-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10296#comments:id=1203228",
        },
        {
            id = 36679,
            score = 7,
            author = "17222",
            text = "notice there are 2 Andormu and they are both outside the instance in caverns of time. The child is the one that actually gives the quest. You should be able to get it after u save thrall.",
            date = "2007-02-15T23:20:17-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10296#comments:id=36679",
        },
    },
    [10297] = {
        {
            id = 28865,
            score = 144,
            author = "14245",
            text = "The Black Morass [Instance]\n\nStrategy\n\nAs you enter the instance you will encounter three types of mobs (Spiders, Crocs, and Stealthed Cats) and all of these mobs are non-elites. As you move forward in the instance you will see Medivh surrounded by a red casting effect. The event will start the minute you get near Medivh, so avoid him until your group has cleared a good distance around Medivh of all three types of mobs. This gives you and your party room to move safely about during the event.\n\nOnce cleared of crocs, spiders, and cats make sure you are full-buffed and have your consumeables ready. Move close to Medivh to start the event. On the top center of your screen you will see a percentage of remaining shield left on Medivh and a Rift Status Counter. Your objective is to keep Medivh's shield from reaching zero percent and destroy what comes through each of the 18 Rifts.\n\nRift 1/18 will spawn somewhere in the woods surrounding Medivh. First, an elite Rift Keeper will come out and channel a spell near the Rift to keep it open. As long as the Rift Keeper is alive, the Rift stays open. As long as the rift stays open, more non-elite dragonflight will spawn from the Rift and head towards Medivh. One person in your party is to crowd control the non-elites and prevent them from hitting Medivh. Your main tank is always on the Rift Keeper until it dies. The Rift Keeper is channeling, mind you, so your party moves to each Rift as they spawn and tanks them there. Slay the Rift Keeper and finish the non-elites. There is time to drink between each Rift if you do this efficiently and quickly.\n\nEach Rift will spawn somewhere in the woods surrounding Medivh. Rinse repeat with the elite Rift Keeper and non-elites.\n\nHowever, there will be Bosses on Rift number 6, 12, and finally Rift 18. Non-elites will continue to spawn from the rifts as these are open so continue preventing them from reaching Medivh. After each boss kill there is a significantly longer time to res dead, drink, or prepare.\n\nBoss explanation\n\n1st Boss - Casts a magical slowing debuff (dispellable). Aoe knockback. Spank and tank.\n2nd Boss - Puts a debuff on your main tank (much like Kurinaxx) that reduces healing effects by 10% each stack. Obviously, this is a very heavy dps fight so you burn him as fast as possible. This is the only time when your crowdcontrol does not crowdcontrol and instead does damage to the boss.\n3rd Boss - Hits like a truck and uses Time Stop (Much like Chromaggus). If you are a healer, you will get time-stopped and your tank will drop health fast. Shielding when time-stop wears off is efficient and as are HoT's (Heal over Time [renew, rejuv, regrowth]). No non-elites come out of the 18th Rift so your crowdcontrol should be dps'ing.\n\nAfter the 3rd boss is down, you are done with Black Morass. Talk to Medivh, complete your quest, and get your Karazhan key. Good luck.",
            date = "2007-02-01T10:59:27-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10297#comments:id=28865",
        },
        {
            id = 29543,
            score = 9,
            author = "Tetris",
            text = "Each person in your party will also get a Chrono-becon, make sure everyone has one.  We saved ours for the bosses.  And only had to pop 1 of them around the 10th rift to get mana back up and help cc the mobs.  We had a priest, rogue, warrior, shaman, mage.  The Rogue and Shaman burned down the elite Rift Keepers, while the mage took care of the assassins.  Also the Rift Keepers do reset if you drag them to far from the portals, and I beleive that the Rifts are on a timer so if you take to long on 1 Rift Keeper another portal will spawn no matter what.\nSoemthing to note if you fail or wipe during the event and Medivh dies then you can not complete the quest, and you will have to reset the instance in order to complete the quest.  Have an order planed out on who will be poping their Chrono-becon at what ever time.  If you can save one for the 2nd and the last boss you will have no problem with either of them.  The summoned dragons don't last very long but they keep agro very well when they do appear.",
            date = "2007-02-02T15:56:47-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10297#comments:id=29543",
        },
        {
            id = 107420,
            score = 5,
            author = "59882",
            text = "You can wait at the 16th rift not taking rift mob and just doing adds until the 18th rift when the 16 and 17 will despawn.",
            date = "2007-06-19T19:09:38-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10297#comments:id=107420",
        },
        {
            id = 75821,
            score = 4,
            author = "42449",
            text = "Playing as a warlock.. get a sense of the timing of when the whelps come out of the rift.  Dump a seed of corruption on the elite (rift lord), and immediately start casting a second seed.\n\nWith the elite taking as much dps as it should be, the seed will explode almost immediately, and your second one will wipe out all three whelps easily before they have any chance to cause any trouble.\n\nWorked beautifully for me in our run.",
            date = "2007-05-01T00:22:15-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10297#comments:id=75821",
        },
        {
            id = 1047806,
            score = 4,
            author = "486275",
            text = "Solo'd it with my unholy DK at level 80. It was a bit of a chore to have to heal so fast between rifts but the long pause inbetween the bosses and the next set of mobs really helped. *One trick, mount up after each rift keeper, boss and adds are dead, then run towards the next one. This made things quicker as the rift keepers are pretty far apart. You can usually heal using some sort of food or potion at these times but you might not get that far before the rift keeper starts sprouting those annoying mobs from their rifts. I think I used just about every type of selfhealing buff, potion and spell on myself including that neat little trinket you get when accepting the quest not to mention the 6 dalaran brownies I munched down inbetween bosses and mobs.",
            date = "2010-05-28T16:08:48-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10297#comments:id=1047806",
        },
    },
    [10299] = {
        {
            id = 36227,
            score = 81,
            author = "zacke10",
            text = "Overseer Theredis is at 23,70 (South room inside the building).\nWalk back inside and use the item he dropped on the machine.\nBefore doing so you should kill all the blood elves inside.\nWhen you do it, blood elves will try to repiar it, kill them to stop them.",
            date = "2007-02-15T03:08:53-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10299#comments:id=36227",
        },
        {
            id = 24844,
            score = 57,
            author = "Darsh",
            text = "After you get the key and use the Console, don't leave yet.  You have to stick around for it to complete, while killing Sunfury Technicians (non-elite, only about 2000 HP, one at a time).  Just don't let them repair it or you won't get quest credit.",
            date = "2007-01-26T05:05:01-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10299#comments:id=24844",
        },
        {
            id = 29160,
            score = 23,
            author = "16148",
            text = "btw the overseer is in the door and to the left in the hallway.",
            date = "2007-02-01T21:43:34-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10299#comments:id=29160",
        },
        {
            id = 37475,
            score = 11,
            author = "23774",
            text = "This is an extremely easy quest, easily soloable by any class..\n\nTip: Clear the Sunfury Warp-Engineers before you begin the shutdown, just makes your life a bit easier.\n\n-Avoril\n-Firetree 70 Druid",
            date = "2007-02-17T11:05:42-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10299#comments:id=37475",
        },
        {
            id = 36128,
            score = 10,
            author = "14687",
            text = "The shutdown takes 2 minutes. During the 2 minutes the technicians will spawn and try to fix it. Kill them to prevent any repairs.",
            date = "2007-02-14T21:57:47-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10299#comments:id=36128",
        },
    },
