    [10308] = {
        {
            id = 38426,
            score = 68,
            author = "21247",
            text = "This gives rep all the way to Exalted",
            date = "2007-02-18T23:51:02-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10308#comments:id=38426",
        },
        {
            id = 199899,
            score = 48,
            author = "101351",
            text = "I tried grinding for beads on the ogres last nite and ended up with 180+ netherweave, 83 Runecloth, 3 greens and 80 beads in 65 minutes. Thats 2000 rep.\n\nToday I decided to do Zaxxis to test the higher drop rate. I ended up with 127 Netherweave, 1 green, 91 zaxxis insignia and 5 prison keys in 65 minutes. Thats 3500 rep.\n\nSo to me in only one trial at each, the Zaxxis drop rate and possibility of keys made it a much better choice for straight rep, but the ogres definately balanced out the time with the additional amount of cloths. Plus I had no competition for the ogres, I still ran Zaxxis without having to search for mobs but there were 2 other people farming there.",
            date = "2007-12-11T21:43:13-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10308#comments:id=199899",
        },
        {
            id = 183021,
            score = 28,
            author = "InfernoMan",
            text = "It all depends on what you are going for.  If you just want strictly Consortium rep, then grind the Heap in netherstorm for these insignias, they also drop a fair amount of netherweave for bandages/tailoring along with some pretty good amounts of silver.  If you want Consortium rep, Kurenai rep, plus netherweave for bandages/tailoring, as well as crystal powder to turn-ins for the research tokens (say going for the riding war talbuk: http://www.wowhead.com/?item=29228) then farm the ogres in Nagrand.  True the drop rate on the beads isn't the best, but as said previously, they are lower level, easier to kill, and you gain three things at once.  Hope this",
            date = "2007-11-12T16:40:13-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10308#comments:id=183021",
        },
        {
            id = 134493,
            score = 26,
            author = "Oozebull",
            text = "\"Another Heap of Ethereals\" is a repeatable quest",
            date = "2007-08-08T16:31:08-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10308#comments:id=134493",
        },
        {
            id = 162830,
            score = 10,
            author = "91630",
            text = "cords 30.6 76.6",
            date = "2007-10-04T12:13:08-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10308#comments:id=162830",
        },
    },
    [10309] = {
        {
            id = 74290,
            score = 130,
            author = "Jamzo",
            text = "Everyone can do this, even if you are holy priest.\nStart the event, get on your flying mount, wait until the ads gets away (it takes some time, so be patient)\nWhen they are gone, you can land and start killing the fel reaver and no ads will come. When he is dead you can loot and turn in the quest =)",
            date = "2007-04-28T07:20:08-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10309#comments:id=74290",
        },
        {
            id = 142334,
            score = 73,
            author = "phatb",
            text = "This can be solo'd by anyone.\n\nFirst, obtain the quest.\n\nSecond, run over to the fel reaver and shock it to start the event.\n\nThird, after you start the event run over to the tent where you obtained the quest\n\nFourth, just sit and wait.  If you get into combat and get out from either attacking the fel reaver or the adds, the fel reaver will despawn and you will have to restart.\n\nFinally after about a few minutes the adds do respawn but the fel reaver is attackable.  You can then attack the fel reaver without any adds coming.",
            date = "2007-08-22T15:04:35-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10309#comments:id=142334",
        },
        {
            id = 7592,
            score = 30,
            author = "ra2phoenix",
            text = "Do not be alarmed that the damaged Fel Reaver is elite, it does not fight back as you try to kill it.  There are however several adds, so a group of 2-3 at least is suggested to deal with them.",
            date = "2006-12-06T15:51:44-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10309#comments:id=7592",
        },
        {
            id = 25497,
            score = 29,
            author = "16577",
            text = "Make sure to just focus on killing it as the ambushers will keep spawning.  Me and a druid killed 50 ambushers before we realized we needed to kill the reaver.",
            date = "2007-01-27T04:16:40-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10309#comments:id=25497",
        },
        {
            id = 227496,
            score = 22,
            author = "Sinborn",
            text = "51 posts and not a single one with coords of the scrapped reaver.\n\nSince I'm trying to do this with a prot pally and I have alot of time to kill, it's at 26.6, 78.8",
            date = "2008-01-31T17:09:08-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10309#comments:id=227496",
        },
    },
    [10310] = {
        {
            id = 1951221,
            score = 101,
            author = "datundra",
            text = "Transmog Hunting: (As Of March 15, 2014)\n\n     OK, I know there are LOTS of posts \"I SOLO'd.......\". This isn't one of those type posts :)  Congrats on your solo......  This is for all those looking for the Netherstorm Eyepatch or the other two quest rewards for the use of Transmogging.  Doing this on a \"Boosted Level 90 Character\" so she has a clean slate and no quests have been done, no flight paths, nothing......\n\n1. Get to Outland, don't matter how you do it, I used the portal in Orgrimmar to the blasted lands and then went through the gate, flew up to Netherstorm from Hellfire Peninsula and went to location 48.11, 63.43 and accept the quest \"Sabotage the Warp-Gate!\" from Drijya.\n\n2. Follow Drijya and protect him while he does his thing.  Mobs will come running out of the center gate. Kill Them.\n\n3. When he says \"Ok, let's get out of here!\", follow him to the safe spot, then he will ask you to let Gahruj know.\n\n4. Fly up to location 46.62, 56,90, talk to Gahruj, select your reward and complete the quest.\n\n5. Rejoice, you have your Transmog Piece.",
            date = "2014-03-15T09:06:21-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10310#comments:id=1951221",
        },
        {
            id = 433728,
            score = 36,
            author = "25371",
            text = "When the NPC says \"lets get out of here\" don't haul ass and leave. You will fail the quest instantly, even if the gate has been destroyed.",
            date = "2008-11-06T22:44:03-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10310#comments:id=433728",
        },
        {
            id = 290219,
            score = 34,
            author = "46061",
            text = "Many people fail to mention that you gotta let the mobs hit Drijya first. If you get aggro first, Drijya will just keep on moving even though you are fighting! Thus making the quest much harder than it has to be.\n\nSo make sure Drijya takes a hit first. He will then stay and fight with you the whole time.",
            date = "2008-05-18T05:23:45-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10310#comments:id=290219",
        },
        {
            id = 1924076,
            score = 7,
            author = "jerodast",
            text = "This quest did not show up as complete in the API for me, but when I visited the NPC his talk text clearly said the warp gate had been taken down. Not sure why that was but fair warning for you completionists.",
            date = "2013-12-06T22:28:05-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10310#comments:id=1924076",
        },
        {
            id = 192835,
            score = 6,
            author = "psxchelly",
            text = "Solo'd as a lvl 70 enhancement shaman.  some decent greens, 8500 health, 6800 mana - duel wield\n1. first wave... as soon as you start to fight the lvl 68 guy, throw your Fire Elemental totem.. the fire guy will help you fight the 9 little demons.  they are lvl 68, don't hit all that hard.  there is a 2 min cooldown before you can throw your Earth elemental, so timing is crucial.\n\nHeal a little bit you have a couple seconds..\n\n2. second pylon, attack the lvl 68 guy, and then after you kill him the 3 demons come, throw your Earth elemental totem... he wont be able to help you all the way through cause these guys hit a little harder.. but he will buy enough time for you to get yourself a more even fight.  then kill them.\n\n3. last pylon, kill the 2 lvl 68s.  the demon comes right after, fight him.  hes a pushover.\n\nBam!  done!",
            date = "2007-11-28T15:01:03-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10310#comments:id=192835",
        },
    },
