        {
            id = 143837,
            score = 4,
            author = "31213",
            text = "The elite here, Culuthas, is for the quest \"Full Triangle\" (http://www.wowhead.com/?quest=10276), obtained after Triangulation Point One and Two.",
            date = "2007-08-25T13:00:15-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10336#comments:id=143837",
        },
        {
            id = 241026,
            score = 4,
            author = "85428",
            text = "for those of you with stealth, the Eye of Culuthas mobs seem to see you when they're firing the beam from their eyes. But, if you can get them when they're not, you can do your stealth move, which for a feral kitty is Ravage or the rogue equivalent Ambush (I believe). They go down pretty fast and have some weak channeling spell called \"Fiery Glare\" or \"Arcane Glare\" and shows up on his cast bar as \"Focused Bursts\" which can be stopped or ignored and dps'd down",
            date = "2008-02-21T19:16:46-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10336#comments:id=241026",
        },
        {
            id = 268652,
            score = 3,
            author = "Oathmaker",
            text = "These monsters in themselves are no trouble for even one a few levels below. The hounds may have a good amount of HP but they really dont do that much damage..a 66 could EASILY blow through these mobs. Just watch out for Culuthas himself!\n\nJust yeah. The hounds have quite a bit of HP. :(",
            date = "2008-04-08T15:09:15-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10336#comments:id=268652",
        },
    },
    [10337] = {
        {
            id = 35666,
            score = 29,
            author = "humungus",
            text = "To make this quest available you need to speak to the farmer Thadell and get the quest from him to actually find Bessy.",
            date = "2007-02-14T03:51:01-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10337#comments:id=35666",
        },
        {
            id = 616367,
            score = 28,
            author = "287953",
            text = "Thank you for bringing back my Bessy, . I couldn't live without her!\n\nIronic, since you're dead....",
            date = "2009-02-20T02:40:42-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10337#comments:id=616367",
        },
        {
            id = 51755,
            score = 14,
            author = "Kamano",
            text = "Oddly enough, this doesn't work like most escort quests. You can stray as far away from Bessy as you want, and even if you die, you won't fail. I actually got ambushed by 3 mobs at once and died, but Bessy decided to keep moving on while I was fighting, so some of them left her alone. Anyway, I ran back to my corpse and ressed and she was still there and I took down the last mob beating on her and continued on.\n\nNice little trick, just be real quick about getting back so she doesn't get killed, though as was said, she can take a good beating.\n\nEdit: Actually, now that I think about it, my not failing might have just been pure luck... like Bessy being out of combat when I died or something of that nature.",
            date = "2007-03-15T18:00:05-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10337#comments:id=51755",
        },
        {
            id = 1157747,
            score = 11,
            author = "673266",
            text = "I did this with my tauren,and used /flirt on her",
            date = "2010-10-31T15:11:37-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10337#comments:id=1157747",
        },
        {
            id = 57489,
            score = 10,
            author = "28360",
            text = "Umm Coords are standard in at least one of your comments. It's all fine and dandy pointing out your encounter, but if you really want to help out more people, List Coords, Zone, and any other special instructions you can think of. =D\n\nBessy is at 59,78",
            date = "2007-03-26T11:40:15-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10337#comments:id=57489",
        },
    },
    [10338] = {
        {
            id = 33520,
            score = 19,
            author = "19013",
            text = "Coords for Manaforge Duro 59,66",
