    [10349] = {
        {
            id = 52638,
            score = 6,
            author = "1138",
            text = "This leads to: [64+] Natural Remedies http://www.wowhead.com/?quest=10351",
            date = "2007-03-17T11:43:59-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10349#comments:id=52638",
        },
        {
            id = 26345,
            score = 4,
            author = "dadicus",
            text = "Located at 15,51",
            date = "2007-01-28T11:45:56-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10349#comments:id=26345",
        },
        {
            id = 30310,
            score = 4,
            author = "4725",
            text = "A level 62 elite will spawn, but the NPC helps you fight him off, so this is easily soloable.\n\nLeads to the \"Natural Remedies\" quest.",
            date = "2007-02-04T00:31:44-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10349#comments:id=30310",
        },
        {
            id = 522322,
            score = 4,
            author = "258124",
            text = "The spawn is Lured Colossus (http://www.wowhead.com/?npc=20599), lvl 62 elite.\nDifferent from Raging Colossus (http://www.wowhead.com/?npc=19188), this one doesn't spawn non-elite small replicas, so it's not difficult to get rid of him.",
            date = "2008-12-21T03:57:18-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10349#comments:id=522322",
        },
        {
            id = 192823,
            score = 3,
            author = "96827",
            text = "A person in my group turned this quest in before I could get it, and I assisted her in completing her quest. When I went to turn in my quest and get ready to kill the elite again...to my surprise I didn't have to kill the elite again! The NPC simply gave me the next quest without having to kill any elite mob. Buggy? I'm not complaining.",
            date = "2007-11-28T14:40:40-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10349#comments:id=192823",
        },
    },
    [10351] = {
        {
            id = 21080,
            score = 82,
            author = "12639",
            text = "Coords are 13,39 for those with Addons\nFor those who do not have Coordinates, the location is on the north side of the big \"red glowing bug thing\" you'll find a green circle. The \"red glowing bug thing\" is due west of the Temple of Telhamat\n\nClear the area of the 63 elite Colossi first,so you don't have any unwanted adds.\n\nPlant the seed in the summoning circle, and go take a piss because it's a 40 second summon... so make your grilled cheese sandwiches and get back to your computer for the boss.\n\nI took him down at level 61 as a Warlock with the help of a 62 shadow priest. Fairly easy fight.\n\nAt 50% HP he will spawn three minions that attack whoever has aggro. Take the boss down first so you finish your quest and poof done.\n\nTurn it in at the Cenarion outpost and be prepared to fight one more Colossi that is summoned there for your next quest.",
            date = "2007-01-17T15:34:08-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10351#comments:id=21080",
        },
        {
            id = 40841,
            score = 43,
            author = "26303",
            text = "follows from http://www.wowhead.com/?item=29477 which drops from a colossus.",
            date = "2007-02-23T00:07:39-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10351#comments:id=40841",
        },
        {
            id = 6814,
            score = 34,
            author = "1633",
            text = "Be sure to clear out the Raging Colosus mobs around the area.  The guy that spawns knocks back and will pull adds.",
            date = "2006-12-05T23:04:58-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10351#comments:id=6814",
        },
        {
            id = 20801,
            score = 25,
            author = "11591",
            text = "Coords: 13, 40",
            date = "2007-01-16T10:34:26-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10351#comments:id=20801",
        },
        {
            id = 6812,
            score = 22,
            author = "6934",
            text = "You will have to summon/fight a level 64 elite that acts similar to a Raging Colossus.  Trioed this with 2 63 mages and a 63 shaman.",
            date = "2006-12-05T22:54:19-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10351#comments:id=6812",
        },
    },
    [10353] = {
        {
            id = 36498,
            score = 86,
            author = "13448",
            text = "Note:  To find Arconus, return to the entrance of the cave and take the right passage and you should be able to find him alot easier.  If you stay in the lower portion (left) you won't find him and probably get highly frustrated running in circles.",
            date = "2007-02-15T14:47:45-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10353#comments:id=36498",
        },
        {
            id = 160457,
            score = 45,
            author = "NeonGenesis",
            text = "If you're doing this quest, you are probably also doing the quest The Flesh Lies... (http://www.wowhead.com/?quest=10345). If not, you should pick it up. It's just outside, a little bit west of the entrance of the cave.\nThe item you get from the quest, Protectorate Igniter (http://www.wowhead.com/?item=29473), is very helpful in burning the corpses, so you won't get parasites to appear when you're too close to a Withered Corpse (http://www.wowhead.com/?npc=20561).\nYou can keep using the item, even if you already completed burning the 12 Corpses for the quest.\n\nAlso the quest item Teleporter Power Pack (http://www.wowhead.com/?item=28969) for the quest A Not-So-Modest Proposal (http://www.wowhead.com/?quest=10270) is located behind the questgiver of the \"Arconus the Insatiable\" quest.",
            date = "2007-09-29T17:28:42-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10353#comments:id=160457",
        },
        {
            id = 33155,
            score = 25,
            author = "1841",
            text = "Note that you must return to Commander Ameer at the Protectorate Watch Post in Netherstorm, and not Agent Ya-six (quest giver). Took me a while to figure out and then I read the quest log. ;)",
            date = "2007-02-09T12:16:10-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10353#comments:id=33155",
        },
        {
            id = 2298464,
            score = 15,
            author = "Aurleis1",
            text = "Video Guide: https://www.youtube.com/watch?v=CCm8qNA3bms\n\n1.  https://www.wowhead.com/quest=10353\n•\009Enter Access Shaft Zeon, at coords 61.1, 45.5.\n•\009Turn left (northwest) at coords 61.1, 44.6, and follow that passage.\n•\009Go left (west) when you reach 60.4, 43.4, and follow that a fork at 60.1, 42.4.\n•\009Take the path to the left, and https://www.wowhead.com/npc=20552, should be standing in front of you.\n•\009Accept the quest, https://www.wowhead.com/quest=10353, from https://www.wowhead.com/npc=20552 at coords 60.8, 41.6 (Access Shaft Zeon).\n•\009Turn around and follow the path to the fork at 60.1, 42.4 where you will take a right (southwest).\n•\009When you reach 60.4, 43.4, take a right (north), and follow that path to a fork at 60.8, 41.5, where you will make a left.  Follow this passage around to coords 60.0, 39.7.\n•\009Kill https://www.wowhead.com/npc=20554.\n•\009Turn around, take the fork to the right, and follow this path to the mine exit at 61.1, 45.5.\n•\009Travel north, to the Protectorate Watch Post, at coords 59.4, 32.2.\n•\009Turn in the quest to https://www.wowhead.com/npc=20448.",
            date = "2016-01-15T15:00:14-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10353#comments:id=2298464",
        },
        {
            id = 26710,
            score = 14,
            author = "17446",
            text = "Inside the cave at aproxmiately 60,40",
            date = "2007-01-28T22:17:35-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10353#comments:id=26710",
        },
    },
    [10355] = {
        {
            id = 21556,
            score = 25,
            author = "13072",
            text = "They're both at around 82, 36. I got my 5 Withered Bog Lord Sample in about 10-15 mins, but the Parched Hydra Sample took over 30 mins to get all five. Parched Hydra got a lower drop rate.\n\nPS they only from the Withered Bog Lord and Parched Hydra don't waste your time with the other mobs there :)",
            date = "2007-01-19T03:09:25-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10355#comments:id=21556",
        },
        {
            id = 22854,
            score = 8,
            author = "Landon",
            text = "Confirm low drop rate.  Good to team up on this as the area is heavily farmed.  Skinners and Herbalists make out like bandits in this area.",
            date = "2007-01-22T15:11:06-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10355#comments:id=22854",
        },
        {
            id = 35569,
            score = 8,
            author = "21835",
            text = "Same spot, just took me longer for the bog lord samples and shorter for the hydra. But both have a fairly low drop rate.",
            date = "2007-02-13T23:48:26-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10355#comments:id=35569",
        },
        {
            id = 123338,
            score = 4,
            author = "63332",
            text = "This is a good quest to do if you later want to get reputation with the Sporeggar.\nAnd in that case, kill everything you see, even the smaller Withered Giants.",
            date = "2007-07-19T11:49:25-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10355#comments:id=123338",
        },
        {
            id = 906497,
            score = 4,
            author = "ihateblizzdev",
            text = "Considering the atrocious drop rate, you'd think there would be a decent reward for the grind.  The tendrils and motes are nice, but don't justify the amount of time spent grinding vs. reward.\n\nI'd say skip this - it's classic Blizz time-waste.  If you do it, do it later (as stated above) for rep with Sporereggar.",
            date = "2009-12-04T17:33:29-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10355#comments:id=906497",
        },
    },
    [10365] = {
        {
            id = 32287,
            score = 34,
            author = "18893",
            text = "Note that the tanking necklace has the exact same stats as the tanking necklace obtained from the Hound-Master quest in Blades Edge.\n\nHowever, http://www.wowhead.com/?item=31696 (Natasha's Battle Chain) vendors for 3G +, and this only vendors for 70 S.\n\nEvery little bit helps when saving up for the Epic Flyer.",
