    [10385] = {
        {
            id = 25239,
            score = 156,
            author = "dantae",
            text = "If you're doing the Triangulation series of quests (I'm on Triangulation Point Two so it may not work for the others), you can use the Triangulation Device to give yourself a 1 minute buff that will allow you to see the Ethereum Relays.\n\nIt makes the quest much less of a pain because you don't have to bother with the intermediary killing of Ethereals for essence.",
            date = "2007-01-26T17:21:47-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10385#comments:id=25239",
        },
        {
            id = 19797,
            score = 77,
            author = "11597",
            text = "You have to pick up Etherium Essence off the Ethereals at the Staging Grounds and drink it to allow you to see the Data Wyrmlings. Kill those and they drop the data you need.",
            date = "2007-01-08T10:22:43-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10385#comments:id=19797",
        },
        {
            id = 29610,
            score = 20,
            author = "vigilant",
            text = "Be careful not to engage any of them if your buff is about to run out as they will keep hitting you after they go invisible again, giving you a free corpse-run.\n\nBlizz and their well thought-out implementations :P",
            date = "2007-02-02T18:20:01-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10385#comments:id=29610",
        },
        {
            id = 34225,
            score = 12,
            author = "brian",
            text = "A somewhat quicker way to do this, because the bodies disappear when you lose the buff, is to kill as many as you can without worrying about looting when you have the buff - you can probably kill 6 or 7. The bodies will re-appear and still be lootable next time you apply the buff, so spend that time looting all the bodies and you probably only need to collect 3 Essences.",
            date = "2007-02-11T17:40:29-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10385#comments:id=34225",
        },
        {
            id = 2298439,
            score = 12,
            author = "Aurleis1",
            text = "Video Guide: https://www.youtube.com/watch?v=R8uRUgJjTvw\n\n1.  https://www.wowhead.com/quest=10385\n•\009Accept the quest, https://www.wowhead.com/quest=10385, from the https://www.wowhead.com/npc=20482 (summon him first by clicking on the Ethereum Transponder Zeta) at coords 56.8, 38.6 (Ethereum Staging Grounds).\n•\009Travel south, and kill Ethereals.\n•\009If you receive an https://www.wowhead.com/item=29482, from their corpse, click on it to receive the https://www.wowhead.com/spell=35409 buff.  This will allow you to see https://www.wowhead.com/npc=20619 mobs.\n•\009Kill https://www.wowhead.com/npc=20619, and loot 15 https://www.wowhead.com/item=29459 from their corpse.\n•\009If you lose your https://www.wowhead.com/spell=35409 buff, kill more Ethereal for another https://www.wowhead.com/item=29482.\n•\009Travel back to coords 56.8, 38.6.\n•\009Turn in the quest to the https://www.wowhead.com/npc=20482.",
            date = "2016-01-15T14:39:33-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10385#comments:id=2298439",
        },
    },
