            score = 9,
            author = "100453",
            text = "when you have killed the illidari taskmaster dont attack his helpers they will become friendly with you when you killed him.",
            date = "2008-01-02T14:58:06-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10403#comments:id=211661",
        },
        {
            id = 75311,
            score = 8,
            author = "38982",
            text = "Naladu is at the back of the Ruins, up the stairs then turn left... coords are 16,65... avoid the elite - you can run through the ruins on mount to where Naladu is and then run to the back of his location and un-aggro the mobs then hand in the quest and you're done :)",
            date = "2007-04-30T06:21:29-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10403#comments:id=75311",
        },
        {
            id = 126492,
            score = 8,
            author = "54423",
