    [10419] = {
        {
            id = 34437,
            score = 30,
            author = "15940",
            text = "This quest is for Scryers rep in shattrah city, the arcane tome itself drops off different mobs mostly in The Botanica, The Mechnar, Netherstorm, and Shadowmoon Valley only off certain mobs, check to see what mobs it drops off first before going to grind for it.  It is recommended that you do the Firewing Signet quest up to Honored with the scryers before handing these in, for max rep gain.",
            date = "2007-02-12T02:38:49-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10419#comments:id=34437",
        },
        {
            id = 151021,
            score = 29,
            author = "TheOnyx",
            text = "This quest turn-in will also give you an amount of rep with The Sha'tar (http://wowhead.com/?faction=935) equal to half of the rep gained for The Scryers. However, you will only be able to reach 1 point from Honored in this manner.",
            date = "2007-09-09T20:53:13-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10419#comments:id=151021",
        },
        {
            id = 147517,
            score = 12,
            author = "57185",
            text = "confirmed, does not require lvl 70 to turn in, i did it at 65 for the first time.",
            date = "2007-09-01T07:19:00-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10419#comments:id=147517",
        },
        {
            id = 321576,
            score = 9,
            author = "109381",
            text = "This item also drop in the Isle of Quel'danas off of the Dawnblade elves west of Sun's Reach, and most likely others as well.",
            date = "2008-07-07T00:41:20-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10419#comments:id=321576",
        },
        {
            id = 5818707,
            score = 9,
            author = "Haduj",
            text = "As of Dragonflight, the old macro was broken because SelectAvailableQuest takes an ID instead of an index, so the updated macro is as follows:\n\n#showtooltip Arcane Tome\n/script C_GossipInfo.SelectAvailableQuest(10419)\n/script CompleteQuest()\n/script GetQuestReward()",
            date = "2024-04-05T13:14:30-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10419#comments:id=5818707",
        },
    },
    [10420] = {
        {
            id = 1482523,
            score = 73,
            author = "850725",
            text = "ok, if you were like me, none of these comments really helped. That's why i'm writing this one. As everybody says, if you just go kill the Cabal mobs(37.6, 58), then it's gonna take you like an hour just to get one drop, and it's not worth the time for 15000 xp. The faster way is to either buy it off the ah, OR, do a bc dungeon. I did the Shadow labyrinth, and it came up as need or greed 3 times throughout the dungeon.  not only are you getting tons of xp while doing the dungeon, but you get 15000 bonus xp if u need one of these. Simple as that!",
            date = "2011-07-29T14:40:02-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10420#comments:id=1482523",
        },
        {
            id = 28104,
            score = 25,
            author = "11299",
            text = "You can turn Fel Armaments in for reputation and the Holy Dust (currency for Aldor shoulder enchantments.) No max rep restrictions, you can keep turning these in even when you hit max Exalted",
            date = "2007-01-31T06:25:17-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10420#comments:id=28104",
        },
        {
            id = 1568456,
            score = 9,
            author = "907994",
            text = "I did not get this in my first kill, or my first ten kills. Over the course of two and a half episodes of Law & Order on Netflix - that's about 2 full hours - I killed countless Cabal mobs, farmed five and a half stacks of Netherweave cloth, and at the end of that got one Fel Armament. Woohoo. If it doesn't drop incidentally when you're doing quests that involve killing these guys, I suggest finding another way.",
            date = "2011-11-10T04:46:46-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10420#comments:id=1568456",
        },
        {
            id = 194922,
            score = 6,
            author = "75300",
            text = "Is this a repeatable quest?",
            date = "2007-12-02T14:22:28-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10420#comments:id=194922",
        },
        {
            id = 377403,
            score = 6,
            author = "169039",
            text = "Don't let the \"level 70\" quest level fool you; this quest is very doable at lower levels. As soon as I got it I tucked it away in my log, thinking that I wouldn't have a chance to complete it. But I ended up receiving the Fel Armament by complete accident as I was doing \"Before Darkness Falls\" (http://wotlk.wowhead.com/?quest=10878) as a level 64 hunter. It dropped as I was killing Cabal Spell-Weavers near Auchindoun. A very easy 15,800 experience.",
            date = "2008-09-15T19:07:17-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10420#comments:id=377403",
        },
    },
    [10421] = {
        {
            id = 28742,
            score = 48,
            author = "11162",
            text = "Here is a list of items which you can hand in and up until which level (for aldor rep):\n\nDreadfang Venom Sac per 8 until Neutral (http://www.wowhead.com/?quest=10019)\n\nMark of Kil'jaeden per 10 until Honored (http://www.wowhead.com/?quest=10326)\n\nMark of Sargeras per 10 until Exalted (http://www.wowhead.com/?quest=10654)\n\nFel Armament per 1 until Exalted (http://www.wowhead.com/?quest=10421) You will also receive dust for which you can buy items.",
            date = "2007-02-01T05:38:08-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10421#comments:id=28742",
        },
        {
            id = 151023,
            score = 12,
            author = "TheOnyx",
            text = "This quest turn-in will also give you an amount of rep with The Sha'tar (http://wowhead.com/?faction=935) equal to half of the rep gained for The Aldor. However, you will only be able to reach 1 point from Honored in this manner.",
            date = "2007-09-09T20:54:44-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10421#comments:id=151023",
        },
        {
            id = 1981989,
            score = 9,
            author = "Nopeace",
            text = "showtooltip Fel Armament\n/script SelectGossipAvailableQuest(1)\n/script CompleteQuest()\n/script GetQuestReward()\nRight click on the NPC who you turn the  https://www.wowhead.com/item=29740 into and press whatever button you have this bound to. This makes turning in any rep item a breeze. I suggest binding it to the mouse wheel for nearly instant turn ins.",
            date = "2014-07-18T21:40:17-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10421#comments:id=1981989",
        },
        {
            id = 58139,
            score = 6,
            author = "15885",
            text = "No, you do not have to be exalted to turn in Fel Armaments.",
            date = "2007-03-27T14:04:27-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10421#comments:id=58139",
        },
        {
            id = 429118,
            score = 4,
            author = "195600",
            text = "Helpfull Hint:\n\nFel Arnament = Mark of Sargeras x 14 (rep wise)\n\nOn most servers Arnaments can be purchased on the AH for around the price of 10 Marks. So by buying these instead of Marks, not only are you saving up for Aldor inscriptions, but you're saving money on Aldor Rep too.",
            date = "2008-11-02T22:42:29-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10421#comments:id=429118",
        },
    },
    [10422] = {
        {
            id = 25714,
            score = 164,
            author = "16527",
            text = "You need to first get the Warden's Key from the Warden, near the pink spheres section. (55,40) Then use the Key on Captain Tyralius's Prison at 52,42.",
            date = "2007-01-27T12:20:29-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10422#comments:id=25714",
        },
        {
            id = 2298456,
            score = 32,
            author = "Aurleis1",
            text = "Video Guide: https://www.youtube.com/watch?v=4rqSmIsiTZs\n\n1.  https://www.wowhead.com/quest=10422\n•\009Accept the quest, https://www.wowhead.com/quest=10422, from https://www.wowhead.com/npc=20450 at coords 59.2, 32.0 (Protectorate Watch Post).\n•\009Travel southwest, into the Ethereum Staging Grounds, to coords 54.4, 41.2.\n•\009Kill https://www.wowhead.com/npc=20770, and loot https://www.wowhead.com/item=29742 from its corpse.\n•\009Travel southwest to coords 53.3, 41.4.\n•\009Click on Captain Tyralius' Prison to free https://www.wowhead.com/npc=20787.\n•\009Travel northeast, to Protectorate Watch Post, to coords 59.2, 32.0\n•\009Turn in the quest to https://www.wowhead.com/npc=20450.",
            date = "2016-01-15T14:51:59-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10422#comments:id=2298456",
        },
        {
            id = 27250,
