            author = "10501",
            text = "the leather bracers are some of the best dps bracers for a feral cat. Dont vendor!",
            date = "2007-03-15T14:15:21-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10425#comments:id=51655",
