    [10427] = {
        {
            id = 2019152,
            score = 40,
            author = "whecks",
            text = "Like a lot of these quests where high-level players have to weaken (not kill) low-level mobs, just suck it up and:\n\n1. find a nice high ledge to stand on\n2. disarm your weapons\n3. jump off ledge and die\n4. take the resurrection sickness\n5. return to mob area\n6. punch mobs into weakness\n7. apply tag/net/lasso/etc.\n\nYes, it will cost you to repair your armor. Yes, you will be sick for 10 minutes.\nIt is however, a repeatable, reliable process.",
            date = "2014-10-25T23:07:35-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10427#comments:id=2019152",
        },
        {
            id = 2360499,
            score = 20,
            author = "Wesi",
            text = "Another Quest where https://www.wowhead.com/item=137663 come in handy",
            date = "2016-08-02T12:58:58-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10427#comments:id=2360499",
        },
        {
            id = 26391,
            score = 14,
            author = "17248",
            text = "This quest has another bug. Depending on what pack of stags you fight, you will or will not get credit for tagging.\n\nThe stags near the spire seem to work, however, the further away they are, they do not give credit.",
            date = "2007-01-28T13:11:05-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10427#comments:id=26391",
        },
        {
            id = 31354,
            score = 13,
            author = "12535",
            text = "There is a perfect spot for this at 40.35. There is 5 of those talbuks ( 1 hostile and 4 neutral ) that keep 'respawning' very very fast. You can do this in 5 mins. Good luck.",
            date = "2007-02-05T17:05:55-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10427#comments:id=31354",
        },
        {
            id = 1646912,
            score = 12,
            author = "Lukahna",
            text = "Here are some specific tips for doing this quest at lv 90 (the difficulty being, you must \"tag\" them when they are below 20% health):\n\nThe talbuks have ~6.7k health. Most classes will one-shot them at lv90.\nStrip nekkid!\nUse PvP trinkets, racials, etc., to come out of the males' stuns so they don't die to your DoTs while stunned.\nAoE DoTs (Consecration) work; cast Consc, taunt nearby talbuks, and tag them all when they're low enough.\nIf all else fails, passive damage (shield spikes, thorns, Retribution Aura) will very gradually and safely bring them below 20% health.\nDo not autoattack ( /stopattack , or just turn around ).\nPetition Blizz for humane tranquilizer darts rather than beating wildlife to within an inch of its life just to tag it.\n\nEdit: Updated for level 90.",
            date = "2012-03-31T05:46:43-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10427#comments:id=1646912",
        },
    },
    [10428] = {
        {
            id = 21419,
            score = 19,
            author = "12940",
            text = "Coords: 16, 94 (Silvermyst Isle)",
            date = "2007-01-18T16:17:29-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10428#comments:id=21419",
        },
        {
            id = 21003,
            score = 17,
            author = "LumiyaSpellsong",
            text = "Cowlen is on the end of a dock that protrudes from the far south eastern corner of Silvermyst Isle.  If you've been to Traitor's Cove, just continue following the island south down along that east side, and you can't miss it or him.  Technically he is in the Veiled Sea because you switch zones at the furthest point on the dock.",
            date = "2007-01-17T09:25:50-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10428#comments:id=21003",
        },
        {
            id = 151493,
            score = 11,
            author = "SubjectV",
            text = "Make sure you pick up the \"A Cry For Help\" quest before you head there.  The quest recommends two people, however, is easily soloable by one person.\n\nhttp://www.wowhead.com/?quest=9528\n\nThe NPC who begins this quest is located at 13,73 next to a large piece of wood/log.  The escort leads you right to her father, who ends this quest and begins the next.",
            date = "2007-09-11T01:16:06-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10428#comments:id=151493",
        },
        {
            id = 1384201,
            score = 4,
            author = "715936",
            text = "The first time I looked at the map link above, the extra quest looked like it was in Exodar city, or next to it!  Silly me, when it didn't show outside I went down inside, though it did seem an odd call that a log would be placed in the hall of light.  Then I discovered that every time I looked at the map listed above, the positions were in a different place.\n\nSimply put: Silvermyst Isle is off the southwestern-most corner of Azuremyst. Swimming is easy - nothing bad in the water either direction to shore.\n\nThe alternate quest giver (A Cry for Help) is on the northern side of Silvermyst Isle, and she is in the curve of a huge log next to the water.  13.6, 73.3.  She leads you right to him - it's a pretty easy quest for one person to protect her, even if you are double-teamed by the defense.  Maybe a back up healing potion or two would be good.\n\nBut that girl's a troublemaker all right!  She ran right over to a beast and practically hit him over the head when we were almost by him without a peep! Don't trust her.  LOL",
            date = "2011-04-04T18:59:32-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10428#comments:id=1384201",
        },
        {
            id = 1855758,
            score = 3,
            author = "furianXO",
            text = "here is the things, both coordinates are somewhat right, however, the accurate cords are 28,32 Veiled Sea.  if you go to the 16,94 cords, YOU WILL NOT SEE HIM.  You have to walk all they way to the end of the pier before he will shows up, and those cords are indeed, 28,32.",
            date = "2013-05-22T09:11:51-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10428#comments:id=1855758",
        },
    },
