            author = "33195",
            text = "I didn't even realize I could've used the drake - but I completed it anyways by using the Rocket Helmet I got in a previous quest to complete it. I launched up in the air and just bombed the Void Conduit as hard as I could, and mission success :)",
            date = "2007-03-16T13:11:04-05:00",
