    [10446] = {
        {
            id = 17835,
            score = 53,
            author = "10162",
            text = "Entrance of the tower - (tloc 73,36) Head upstairs and touch the orb to teleport to the top of tower.\nSharth Voldoun - top of tower (tloc 73,35). He has roughly about 10k hp (lvl 65). I soloed him with my fire mage at lvl 63.",
            date = "2006-12-23T04:42:39-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10446#comments:id=17835",
        },
        {
            id = 378496,
            score = 43,
            author = "SixTwoSixFour",
            text = "Word of advice- I know no one else is this stupid, but all the same, hear my tale, and be warned.\n\nI climbed my way up the tower, and managed to, after an epic fight, drop the boss (fellow Priests- Mana Burn him til he cries!). I had taken so long up there that I knew for sure that there had been respawn below, and I really didn't feel like dealing with it. So I hit levitation, and jumped out the back way, to avoid landing on any mobs. Yeah, that gave me a good 30 seconds to contemplate how idiotic that was as I drifted very slowly into the abyss and died. Don't do that.",
            date = "2008-09-16T23:58:54-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10446#comments:id=378496",
        },
        {
            id = 72569,
            score = 19,
            author = "Kioti",
            text = "The Mana Bomb is located at 71, 37 in the middle of the courtyard with all the Warlocks surrounding it.  You only need to kill enough locks to get access to the bomb.",
