    [10447] = {
        {
            id = 11847,
            score = 90,
            author = "6934",
            text = "First thing you want to do is head to the Northeastern part of the Firewing Point, head up the tower, use the translocation orb, and find/kill Sharth Voldoun. He'll drop The Final Code( http://www.wowhead.com/?item=29912 ) which you'll need to activate the mana bomb. Snag this and then head towards the middle of the base. Kill all the warlocks and other mobs guarding the mana bomb, click it, and viola, the bomb is triggered.",
            date = "2006-12-08T23:14:31-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10447#comments:id=11847",
        },
        {
            id = 23907,
            score = 42,
            author = "6877",
            text = "At the loc 73, 35 you need to use the Orb on the ledge.  That will take you up top, continue up to the left and you'll find him standing there.\n\nHe does pretty good damage and heals himself when low.",
            date = "2007-01-24T17:36:46-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10447#comments:id=23907",
        },
        {
            id = 391872,
            score = 18,
            author = "171369",
            text = "Am I the only one thinking of Star Wars?\nSharth Valdroun = Darth Vader\nPathaleon the Calculator = Palpatine (the Emperor)\nI mean as kesenaie wrote (the whole dialogue) even sound somewhat like Vader talking to Palpatine, especially due to Pathaleon/Palpatine are images talking to Vauldron/Vader...\nMana Bomb = Death Star (sorta), it kinda looks like it and the explosion is similar lol\nThere are probably more similarities but i cant find/remember em\n\nAm i completely off?",
            date = "2008-09-29T12:55:51-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10447#comments:id=391872",
        },
        {
            id = 160146,
            score = 16,
            author = "8714",
            text = "One REALLY important detail: exploding the mana bomb has a CASTING TIME.  SO you can't just fear and use it, fear runs out before you get it off.  You have to kill all the mobs around it.",
            date = "2007-09-29T03:36:43-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10447#comments:id=160146",
        },
        {
            id = 289459,
            score = 14,
            author = "Phurox",
            text = "Dont die you cant get your corpse back...",
            date = "2008-05-16T18:41:07-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10447#comments:id=289459",
        },
    },
