    [10476] = {
        {
            id = 1043324,
            score = 29,
            author = "114762",
            text = "I'd like to note that if you didn't quest in Zangarmarsh (I healed instances till I started to quest in Nagrand) You'll need to finish Do My Eyes Deceive Me? and Not On My Watch! before you can pick up this quest. (Those two quests will get you neutral with the Kurenai, which will in turn open up the quests in Telaar.)",
