    [10506] = {
        {
            id = 29113,
            score = 24,
            author = "speak",
            text = "If you're a mage, sheep the wolf and then use the Diminution Powder on the sheep.",
            date = "2007-02-01T19:41:51-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10506#comments:id=29113",
        },
        {
            id = 25703,
            score = 17,
            author = "16693",
            text = "They are araund the area of 45, 75.",
            date = "2007-01-27T12:02:17-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10506#comments:id=25703",
        },
        {
            id = 27380,
            score = 9,
            author = "15689",
            text = "Bloodmaul Dire Wolf : http://www.wowhead.com/?npc=20058",
            date = "2007-01-29T20:36:46-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10506#comments:id=27380",
        },
        {
            id = 75542,
            score = 7,
            author = "47669",
            text = "Another way (won't stop you from getting attacked) is to just stay near the same wolf the whole time. The Powder wares off after about 30-45 sec and you can just reapply it to the same wolf. Wolf near 45,67 in the middle drew no extra aggro from ogres at any time while I did this.",
            date = "2007-04-30T15:01:27-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10506#comments:id=75542",
        },
        {
            id = 23787,
            score = 6,
