            text = "Bound for Glory-Rose tatoo.good song glad to see blizz is keepin up with there rock. :D",
            date = "2008-10-01T04:10:34-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10509#comments:id=393455",
