    [10510] = {
        {
            id = 34384,
            score = 33,
            author = "21004",
            text = "Just to clarify you do NOT need mining to obtain said crystals. - Location spot on.",
            date = "2007-02-12T00:10:26-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10510#comments:id=34384",
        },
        {
            id = 19473,
            score = 26,
            author = "Lustral",
            text = "These are listed to drop off of Bloodmaul Drudgers, however they're literally mined from large, teal crystal veins that are scattered throughout the southern cave (43, 85).",
            date = "2007-01-05T16:34:51-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10510#comments:id=19473",
        },
        {
            id = 37659,
            score = 15,
            author = "11874",
            text = "You do not need to be a miner to obtain these crystals, anyone can just \"use\" the crystals to obtain them.\n\nThey are located in Draenethyst Mine. Entrance is at 42,84.",
            date = "2007-02-17T17:05:11-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10510#comments:id=37659",
        },
        {
            id = 125326,
            score = 14,
            author = "47965",
            text = "Do these two quests at the same time, save you running around.\n\nStrange Brew: http://www.wowhead.com/?quest=10511\nBloodmaul Ogres: http://www.wowhead.com/?quest=10502",
            date = "2007-07-23T04:48:24-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10510#comments:id=125326",
        },
        {
            id = 24461,
            score = 11,
            author = "10603",
            text = "These crystals can be picked up either off the ogres in the cave, or from the large crystal formations there.  Very easy to get, i barely had to enter the cave and i was done.",
            date = "2007-01-25T14:11:28-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10510#comments:id=24461",
        },
    },
    [10511] = {
        {
            id = 3788,
            score = 12,
            author = "zutroy",
            text = "Located inside Brutebane kegs. Also drops off Bloodmaul Brewmaster.",
            date = "2006-11-17T08:23:43-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10511#comments:id=3788",
        },
        {
            id = 152182,
            score = 11,
            author = "SaintStryfe",
            text = "The name is in reference to a movie of the same name:\n\nhttp://imdb.com/title/tt0086373/",
            date = "2007-09-12T17:04:15-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10511#comments:id=152182",
        },
        {
            id = 33356,
            score = 10,
            author = "18459",
            text = "Found the brew at Bloodmaul outpost (45, 75).\nA good quest to pair with is: The Bloodmaul Ogres: http://www.wowhead.com/?quest=10502",
            date = "2007-02-09T22:36:27-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10511#comments:id=33356",
        },
        {
            id = 54523,
            score = 8,
            author = "creed",
            text = "Also a small hut with a brewmaster and keg at (44,68).  This is outside the outpost and easier to get to if you want to get some brew there while doing the other quest.",
            date = "2007-03-20T21:38:38-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10511#comments:id=54523",
        },
        {
            id = 41922,
            score = 5,
            author = "Jamzo",
            text = "Take this quest at the same time!\nhttp://www.wowhead.com/?quest=10510",
            date = "2007-02-25T05:01:59-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10511#comments:id=41922",
        },
    },
    [10512] = {
        {
            id = 23834,
            score = 53,
            author = "Phaleux",
            text = "The part that isn't obvious about this quest is that the ogres have to walk towards the beer for it to count.  I (a priest) was doing this with my rogue friend and at first we were sapping and dropping it at their feet -- this didn't work.  We found a couple of ways of getting it to work\n\n1.  Place one in front of a patrolling Brute and wait for him to walk up to it.  This is how most people will need to do this quest.\n2.  Sap and drop one a few yards away.  Wait for sap to break, or sap something else and he'll notice it and get drunk.\n3.  This was the best way:  Mind soothe!  Use this oft-forgotten priest skill and walk up close, drop the mug and run away.\n\nWe found the Brutes and Cooks were the best to try to get drunk for this quest.  Brutes seemed to be the only kind that were patrolling.",
            date = "2007-01-24T15:59:37-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10512#comments:id=23834",
        },
        {
            id = 25286,
            score = 22,
            author = "4828",
            text = "Apparently you don't have to wait for one to patrol into the booze.  The range at which the ogres will detect the stout is larger than their aggro range.  Figure out how far you have to be for them to just barely not aggro and drop it there.",
            date = "2007-01-26T18:41:23-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10512#comments:id=25286",
        },
        {
            id = 164742,
            score = 22,
            author = "redback",
            text = "You should be able to gather more brew from the bloodmauls if you use up all the charges before you finish",
            date = "2007-10-08T12:33:27-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10512#comments:id=164742",
        },
        {
            id = 256827,
            score = 19,
            author = "111622",
            text = "I've seen Orges walk OVER these things like on top of them, and nothing happened. 6 Screenshots proven.\n\nRate this comment + if you're having trouble too",
            date = "2008-03-21T06:37:47-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10512#comments:id=256827",
        },
        {
            id = 59154,
            score = 18,
            author = "36164",
            text = "Enter \"Bladespire Grounds\" @ 45.50 and start getting them drunk around that place. Enough room to avoid any Ogre.",
            date = "2007-03-29T12:05:20-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10512#comments:id=59154",
        },
    },
    [10513] = {
        {
            id = 30559,
            score = 106,
            author = "marskid2",
            text = "The Cipher of Damnation is an extremely long quest line in Shadowmoon Valley.  It is a prerequisite for attunement to The Eye in Tempest Keep and Mount Hyjal in Caverns of time.\n\"*\" Indicates quests with rewards.\n\nQuest Line\n1[A] - http://www.wowhead.com/?quest=10680 - \"The Hand of Gul'Dan\"\n1[H] - http://www.wowhead.com/?quest=10681 - \"The Hand of Gul'Dan\"\n2 - http://www.wowhead.com/?quest=10458 - \"Enraged Spirits of Fire and Earth\"\n3 - http://www.wowhead.com/?quest=10480 - \"Enraged Spirits of Water\"\n4* - http://www.wowhead.com/?quest=10480 - \"Enraged Spirits of Air\"\n5 - http://www.wowhead.com/?quest=10513 - \"Oronok Torn-Heart\"\n6* - http://www.wowhead.com/?quest=10514 - \"I Was A Lot Of Things...\" - Most annoying quest ever implemented in World of Warcraft.\n7 - http://www.wowhead.com/?quest=10515 - \"A Lesson Learned\"\n8 - http://www.wowhead.com/?quest=10519 - \"The Cipher of Damnation - Truth and History\"\n\nAt this point, the quests diverge into three separate lines (which can be done in any order) for each of Oronok's three sons who will in turn help you obtain the three Fragments of Damnation.\n\nQuest Line I - First Fragment of Damnation\n1 - http://www.wowhead.com/?quest=10521 - \"Grom'tor, Son of Oronok\"\n2 - http://www.wowhead.com/?quest=10522 - \"The Cipher of Damnation - Grom'tor's Charge\"\n3* - http://www.wowhead.com/?quest=10523 - \"The Cipher of Damnation - The First Fragment Recovered\"\n\nQuest Line II - Second Fragment of Damnation\n1 - http://www.wowhead.com/?quest=10527 \"Ar'tor, Son of Oronok\"\n2 - http://www.wowhead.com/?quest=10528 - \"Demonic Crystal Prisons\"\n3 - http://www.wowhead.com/?quest=10537 - \"Lohn'goron, Bow of the Torn-heart\"\n4 - http://www.wowhead.com/?quest=10540 - \"The Cipher of Damnation - Ar'tor's Charge\"\n5* - http://www.wowhead.com/?quest=10541 - \"The Cipher of Damnation - The Second Fragment Recovered\"\n\nQuest Line III - Third Fragment of Damnation\n1 - http://www.wowhead.com/?quest=10546 \"Borak, Son of Oronok\"\n2 - http://www.wowhead.com/?quest=10547 - \"Of Thistleheads and Eggs...\"\n3 - http://www.wowhead.com/?quest=10550 - \"The Bundle of Bloodthistle\"\n4 - http://www.wowhead.com/?quest=10570 - \"To Catch A Thistlehead\"\n5 - http://www.wowhead.com/?quest=10576 - \"The Shadowmoon Shuffle\"\n6 - http://www.wowhead.com/?quest=10577 - \"What Illidan Wants, Illidan Gets...\"\n7 - http://www.wowhead.com/?quest=10578 - \"The Cipher of Damnation - Borak's Charge\"\n8* - http://www.wowhead.com/?quest=10579 \"The Cipher of Damnation - The Third Fragment Recovered\"\n\nAfter completing the quests for the three Fragments of Damnation, the lines converge and you need to kill one last boss.\nFinal* - http://www.wowhead.com/?quest=10588 - \"The Cipher of Damnation\"\n\nRewards:\n\nEveryone gets http://www.wowhead.com/?item=31074 - Fire Resist Neck\n\nChoose one of the following:\nhttp://www.wowhead.com/?item=31036 - Caster Staff\nhttp://www.wowhead.com/?item=31038 - Healer Staff\nhttp://www.wowhead.com/?item=31062 - Paladin/Shaman 2H Axe\nhttp://www.wowhead.com/?item=31071 - Tanking 1H Axe\nhttp://www.wowhead.com/?item=31072 - Bow\nhttp://www.wowhead.com/?item=31073 - Melee Dagger\n\nAfter completing the quest, you will get a message in the mail from Khadgar.  If you go to Shattrath, he will tell you to talk to A'Dal, who unlocks the the three Trials.  These are prerequisites for attunement to The Eye in Tempest Keep and Mount Hyjal in Caverns of time.",
            date = "2007-02-04T11:58:49-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10513#comments:id=30559",
        },
        {
            id = 436477,
            score = 56,
            author = "104901",
            text = "Just remember, he's not IN the cave, he's a top of it!\n\nI ran around in the cave for 10 minutes to get to him, and realised he wasn't there.",
            date = "2008-11-09T15:30:48-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10513#comments:id=436477",
        },
        {
            id = 23179,
            score = 51,
            author = "13988",
            text = "He's at 53, 23.",
            date = "2007-01-23T09:22:01-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10513#comments:id=23179",
        },
        {
            id = 32404,
            score = 19,
            author = "Omnia",
            text = "For those of you who dont have an addon to show you, you can just look him up at\nhttp://www.wowhead.com/?npc=21183 (For Oronok Torn-Heart)",
            date = "2007-02-07T19:27:08-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10513#comments:id=32404",
        },
        {
            id = 2300261,
            score = 1,
            author = "Aurleis1",
            text = "Video Guide: https://www.youtube.com/watch?v=pdj5CpkI1ZU\n\n1.  https://www.wowhead.com/quest=10513\n•\009Accept the quest, https://www.wowhead.com/quest=10513, from https://www.wowhead.com/npc=21024 at coords 42.2, 45.0 (Altar of Damnation).\n•\009Travel northeast, to Oronok's Farm, at coords 53.8, 23.4.\n•\009Turn in the quest to https://www.wowhead.com/npc=21183.",
            date = "2016-01-20T14:32:05-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10513#comments:id=2300261",
        },
    },
    [10514] = {
        {
            id = 30561,
            score = 156,
            author = "marskid2",
            text = "The Cipher of Damnation is an extremely long quest line in Shadowmoon Valley.  It is a prerequisite for attunement to The Eye in Tempest Keep and Mount Hyjal in Caverns of time.\n\"*\" Indicates quests with rewards.\n\nQuest Line\n1[A] - http://www.wowhead.com/?quest=10680 - \"The Hand of Gul'Dan\"\n1[H] - http://www.wowhead.com/?quest=10681 - \"The Hand of Gul'Dan\"\n2 - http://www.wowhead.com/?quest=10458 - \"Enraged Spirits of Fire and Earth\"\n3 - http://www.wowhead.com/?quest=10480 - \"Enraged Spirits of Water\"\n4* - http://www.wowhead.com/?quest=10480 - \"Enraged Spirits of Air\"\n5 - http://www.wowhead.com/?quest=10513 - \"Oronok Torn-Heart\"\n6* - http://www.wowhead.com/?quest=10514 - \"I Was A Lot Of Things...\" - Most annoying quest ever implemented in World of Warcraft.\n7 - http://www.wowhead.com/?quest=10515 - \"A Lesson Learned\"\n8 - http://www.wowhead.com/?quest=10519 - \"The Cipher of Damnation - Truth and History\"\n\nAt this point, the quests diverge into three separate lines (which can be done in any order) for each of Oronok's three sons who will in turn help you obtain the three Fragments of Damnation.\n\nQuest Line I - First Fragment of Damnation\n1 - http://www.wowhead.com/?quest=10521 - \"Grom'tor, Son of Oronok\"\n2 - http://www.wowhead.com/?quest=10522 - \"The Cipher of Damnation - Grom'tor's Charge\"\n3* - http://www.wowhead.com/?quest=10523 - \"The Cipher of Damnation - The First Fragment Recovered\"\n\nQuest Line II - Second Fragment of Damnation\n1 - http://www.wowhead.com/?quest=10527 \"Ar'tor, Son of Oronok\"\n2 - http://www.wowhead.com/?quest=10528 - \"Demonic Crystal Prisons\"\n3 - http://www.wowhead.com/?quest=10537 - \"Lohn'goron, Bow of the Torn-heart\"\n4 - http://www.wowhead.com/?quest=10540 - \"The Cipher of Damnation - Ar'tor's Charge\"\n5* - http://www.wowhead.com/?quest=10541 - \"The Cipher of Damnation - The Second Fragment Recovered\"\n\nQuest Line III - Third Fragment of Damnation\n1 - http://www.wowhead.com/?quest=10546 \"Borak, Son of Oronok\"\n2 - http://www.wowhead.com/?quest=10547 - \"Of Thistleheads and Eggs...\"\n3 - http://www.wowhead.com/?quest=10550 - \"The Bundle of Bloodthistle\"\n4 - http://www.wowhead.com/?quest=10570 - \"To Catch A Thistlehead\"\n5 - http://www.wowhead.com/?quest=10576 - \"The Shadowmoon Shuffle\"\n6 - http://www.wowhead.com/?quest=10577 - \"What Illidan Wants, Illidan Gets...\"\n7 - http://www.wowhead.com/?quest=10578 - \"The Cipher of Damnation - Borak's Charge\"\n8* - http://www.wowhead.com/?quest=10579 \"The Cipher of Damnation - The Third Fragment Recovered\"\n\nAfter completing the quests for the three Fragments of Damnation, the lines converge and you need to kill one last boss.\nFinal* - http://www.wowhead.com/?quest=10588 - \"The Cipher of Damnation\"\n\nRewards:\n\nEveryone gets http://www.wowhead.com/?item=31074 - Fire Resist Neck\n\nChoose one of the following:\nhttp://www.wowhead.com/?item=31036 - Caster Staff\nhttp://www.wowhead.com/?item=31038 - Healer Staff\nhttp://www.wowhead.com/?item=31062 - Paladin/Shaman 2H Axe\nhttp://www.wowhead.com/?item=31071 - Tanking 1H Axe\nhttp://www.wowhead.com/?item=31072 - Bow\nhttp://www.wowhead.com/?item=31073 - Melee Dagger\n\nAfter completing the quest, you will get a message in the mail from Khadgar.  If you go to Shattrath, he will tell you to talk to A'Dal, who unlocks the the three Trials.  These are prerequisites for attunement to The Eye in Tempest Keep and Mount Hyjal in Caverns of time.",
            date = "2007-02-04T12:00:14-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10514#comments:id=30561",
        },
        {
            id = 26528,
            score = 142,
            author = "1410",
            text = "In order to loot a Shadowmoon Tuber you first have to find a Shadowmoon Tuber Mound, a tooltip will pop up when you hover over it, then you have to use Oronok's Boar Whistle when a boar is nearby and the boar will come dig up the tuber, then a lootable Shadowmoon Tuber appears and you loot the tuber from that.\n\nThe only real difficulty in this is finding a spawn that is near a felboar, and also keeping the felboars alive because the Ravenous Flayers all around the are are constantly killing the boars.\n\nNote: aggroing one of the felboars to make it follow you and then using the whistle while standing on a tuber, Does NOT work, just means you have to kill the felboar, which is pointless.",
            date = "2007-01-28T17:08:15-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10514#comments:id=26528",
        },
        {
            id = 26933,
            score = 121,
            author = "Darsh",
            text = "If you can get one where two boars come over simultaneously (or more I suppose) you can loot multiple tuber's per mound.",
            date = "2007-01-29T06:42:12-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10514#comments:id=26933",
        },
        {
            id = 28691,
            score = 76,
            author = "Kavan",
            text = "What you can also do is find a tuber, then pull a Flayer that is attacking some boar over to the tuber. Boar will follow him and when you kill the Flayer use the whistle.",
            date = "2007-02-01T02:30:46-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10514#comments:id=28691",
        },
        {
            id = 283278,
            score = 71,
            author = "147055",
            text = "High on my list of \"Most Irritating Quests\"",
            date = "2008-05-06T07:37:30-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10514#comments:id=283278",
        },
    },
    [10515] = {
        {
            id = 30566,
            score = 52,
            author = "marskid2",
            text = "The Cipher of Damnation is an extremely long quest line in Shadowmoon Valley.  It is a prerequisite for attunement to The Eye in Tempest Keep and Mount Hyjal in Caverns of time.\n\"*\" Indicates quests with rewards.\n\nQuest Line\n1[A] - http://www.wowhead.com/?quest=10680 - \"The Hand of Gul'Dan\"\n1[H] - http://www.wowhead.com/?quest=10681 - \"The Hand of Gul'Dan\"\n2 - http://www.wowhead.com/?quest=10458 - \"Enraged Spirits of Fire and Earth\"\n3 - http://www.wowhead.com/?quest=10480 - \"Enraged Spirits of Water\"\n4* - http://www.wowhead.com/?quest=10480 - \"Enraged Spirits of Air\"\n5 - http://www.wowhead.com/?quest=10513 - \"Oronok Torn-Heart\"\n6* - http://www.wowhead.com/?quest=10514 - \"I Was A Lot Of Things...\" - Most annoying quest ever implemented in World of Warcraft.\n7 - http://www.wowhead.com/?quest=10515 - \"A Lesson Learned\"\n8 - http://www.wowhead.com/?quest=10519 - \"The Cipher of Damnation - Truth and History\"\n\nAt this point, the quests diverge into three separate lines (which can be done in any order) for each of Oronok's three sons who will in turn help you obtain the three Fragments of Damnation.\n\nQuest Line I - First Fragment of Damnation\n1 - http://www.wowhead.com/?quest=10521 - \"Grom'tor, Son of Oronok\"\n2 - http://www.wowhead.com/?quest=10522 - \"The Cipher of Damnation - Grom'tor's Charge\"\n3* - http://www.wowhead.com/?quest=10523 - \"The Cipher of Damnation - The First Fragment Recovered\"\n\nQuest Line II - Second Fragment of Damnation\n1 - http://www.wowhead.com/?quest=10527 \"Ar'tor, Son of Oronok\"\n2 - http://www.wowhead.com/?quest=10528 - \"Demonic Crystal Prisons\"\n3 - http://www.wowhead.com/?quest=10537 - \"Lohn'goron, Bow of the Torn-heart\"\n4 - http://www.wowhead.com/?quest=10540 - \"The Cipher of Damnation - Ar'tor's Charge\"\n5* - http://www.wowhead.com/?quest=10541 - \"The Cipher of Damnation - The Second Fragment Recovered\"\n\nQuest Line III - Third Fragment of Damnation\n1 - http://www.wowhead.com/?quest=10546 \"Borak, Son of Oronok\"\n2 - http://www.wowhead.com/?quest=10547 - \"Of Thistleheads and Eggs...\"\n3 - http://www.wowhead.com/?quest=10550 - \"The Bundle of Bloodthistle\"\n4 - http://www.wowhead.com/?quest=10570 - \"To Catch A Thistlehead\"\n5 - http://www.wowhead.com/?quest=10576 - \"The Shadowmoon Shuffle\"\n6 - http://www.wowhead.com/?quest=10577 - \"What Illidan Wants, Illidan Gets...\"\n7 - http://www.wowhead.com/?quest=10578 - \"The Cipher of Damnation - Borak's Charge\"\n8* - http://www.wowhead.com/?quest=10579 \"The Cipher of Damnation - The Third Fragment Recovered\"\n\nAfter completing the quests for the three Fragments of Damnation, the lines converge and you need to kill one last boss.\nFinal* - http://www.wowhead.com/?quest=10588 - \"The Cipher of Damnation\"\n\nRewards:\n\nEveryone gets http://www.wowhead.com/?item=31074 - Fire Resist Neck\n\nChoose one of the following:\nhttp://www.wowhead.com/?item=31036 - Caster Staff\nhttp://www.wowhead.com/?item=31038 - Healer Staff\nhttp://www.wowhead.com/?item=31062 - Paladin/Shaman 2H Axe\nhttp://www.wowhead.com/?item=31071 - Tanking 1H Axe\nhttp://www.wowhead.com/?item=31072 - Bow\nhttp://www.wowhead.com/?item=31073 - Melee Dagger\n\nAfter completing the quest, you will get a message in the mail from Khadgar.  If you go to Shattrath, he will tell you to talk to A'Dal, who unlocks the the three Trials.  These are prerequisites for attunement to The Eye in Tempest Keep and Mount Hyjal in Caverns of time.",
            date = "2007-02-04T12:04:01-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10515#comments:id=30566",
        },
        {
            id = 28621,
            score = 18,
            author = "14235",
            text = "Pretty easy, just go directly north and a bit to the east, u will see the eggs on the floor.\n\nJust be aware of the Ravenous Flayer Matriarch, a lvl 70 elite Beast that wanders the area.",
            date = "2007-01-31T22:39:05-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10515#comments:id=28621",
        },
        {
            id = 37536,
            score = 15,
            author = "Flyv",
            text = "Druids can break the eggs while flying in Crow form. I was able to hover out of aggro range and avoid fighting any mobs.",
            date = "2007-02-17T13:38:42-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10515#comments:id=37536",
        },
        {
            id = 59502,
            score = 6,
            author = "Siggy",
            text = "Hadn't read the comment about breaking while in crow form but i just flew from egg to egg and only aggroed a mob once, so with a flying mount you should be able to do the same thing. As long as you keep an eye out for the elite you should be fine, and priests can use soothe humanoid as well to get even closer w/o aggroing.",
            date = "2007-03-30T02:39:02-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10515#comments:id=59502",
        },
        {
            id = 653231,
            score = 5,
            author = "215071",
            text = "While doing this quest I noticed that some of the eggs glowed much brighter than others, one was just a big ball of light. So I decided to see what made them different. Turns out that the eggs often spawn on top of eachother, I found one egg that was actually 5+ eggs in one!\nI attacked it 4 times and there was still an egg there when I was done, so it was at least 5 piled up. Target these and you can get the quest done a lot faster.\nThe brighter they glow the more that are stacked up. Definitely worth knowing about.",
            date = "2009-03-23T19:03:41-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10515#comments:id=653231",
        },
    },
    [10516] = {
        {
            id = 14630,
            score = 210,
            author = "psonica",
            text = "This quest is not marked 'elite' because you really don't have to kill the 2 elite guards to get the named ogre. Notice that the guards have \"sober\" in their names? So what I did was this:\n\n1. kill the 2 non-elites but pulling them out of the tent/hut.\n2. go as close as you can get without pulling the elites and place a \"Bloodmaul Butebane Brew\" on the floor. This will pull the named but not the two sober guards.\n3. Kill named ogre.\n4. Profit :)\n\n...easy as cake when you remember that most ogres are not able to resist the smell of some brew.",
            date = "2006-12-13T04:22:50-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10516#comments:id=14630",
        },
        {
            id = 18574,
            score = 63,
            author = "10162",
            text = "Mugdorg - 41, 59\nDroggam - 38, 54\nzutroy's coordinates are 100% wrong.",
            date = "2006-12-30T02:10:52-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10516#comments:id=18574",
        },
        {
            id = 18859,
            score = 27,
            author = "10835",
            text = "Actually, you don't even need the brew. The named ogres will pull solo without the guards, even though that seems highly unlikely.",
            date = "2006-12-31T17:42:42-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10516#comments:id=18859",
        },
        {
            id = 159249,
            score = 13,
            author = "Phoeps",
            text = "Useful Information for patch 2.2:\n\nAs of Patch WoW patch 2.2 you can't pull the boss away from his elite bodyguards the usual way anymore using a weapon pull, this will make his bodyguards come for you.\nOBS! As it might have been mentioned in above comments however, you can still use the \"Bloodmaul Brutebane Kegs\" to lure the ogres out - this includes him!\n\nHow to:\n\nKill the front 2 guards, usually a brute and a shaman - these can be pulled one by one and is easy to kill. Next go exactly far enough in to stand halfway between the bonfire and the entrance, inside the room, plant a \"Brutemaul Brutebane Keg Brew\" on the floor and back up. The Boss will react immidiatly but if its too far away he won't notice. If u accedently place it to far away wait for the CD and try place one closer in. Once he reaches the brew you can freely pull and kill him without having to deal with his bodyguards!\nRemember! - It might be adviseable to bring more then 2 brews incase u accedently place one wrong, and its annoying having to run out and find anther in the middle of the quest!\n\nEntrance coords:\n\nDroggam: 39,52\nMugdorg: 42,57",
            date = "2007-09-27T07:16:55-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10516#comments:id=159249",
        },
        {
            id = 106020,
            score = 11,
            author = "13228",
            text = "this gets easier still if you are friendly with ogri'la - the ogres are all yellow and will not auto-aggro... zoiks!",
            date = "2007-06-17T13:49:20-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10516#comments:id=106020",
        },
    },
    [10517] = {
        {
            id = 25977,
            score = 20,
            author = "15586",
            text = "Same as the quests before it, you don't need to kill the sober guys, or even use the beer, they just don't pull.\n\nHell you don't even have to loot him for credit.",
            date = "2007-01-27T20:47:23-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10517#comments:id=25977",
        },
        {
            id = 59128,
            score = 9,
            author = "36077",
            text = "the correct coordinates are 40, 50.\n\nfor those that don't have a map coordinate add-on, if you look on your map, it is the picture of the big building to the left of the letters bladespire hold.\n\nto kill gorr'dim, just kill off the non-elites inside the building. then pull the gorr'dim. do not worry about the two elites on his side. they do not attack if pulled correctly.",
            date = "2007-03-29T11:25:06-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10517#comments:id=59128",
        },
        {
            id = 438689,
            score = 5,
            author = "235097",
            text = "Note that you can pull Gorr'Dim with a ranged spell or weapon without attracting the elite guards. Just make sure to kill the two non-elites first.",
            date = "2008-11-11T13:04:07-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10517#comments:id=438689",
        },
        {
            id = 116916,
            score = 4,
            author = "60905",
            text = "Very easy quest. Just use Bloodmaul Brutebane Keg to pull Gorr'Dim forward, then pull him further away from the elites and kill him. Very simple, good XP.",
            date = "2007-07-07T11:11:32-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10517#comments:id=116916",
        },
        {
            id = 304723,
            score = 3,
            author = "83130",
            text = "As a Priest you can easily solo that quest. Just Mind Soothe the Elite guards and pull the boss away with Mind Control.\nIt won't aggro the guards. :)",
            date = "2008-06-14T05:50:32-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10517#comments:id=304723",
        },
    },
    [10518] = {
        {
            id = 1933611,
            score = 213,
            author = "Zwolzy",
            text = "Getting the flag\nTo get the https://www.wowhead.com/item=30416, you will need to kill a Bladespire Champion (http://www.wowhead.com/npc=21296).\nThe Bladespire Champion (http://www.wowhead.com/npc=21296) can be found in Bladespire Hold (http://www.wowhead.com/maps?data=3522:452481).\n\nWaypoints for the Bladespire Champion (http://www.wowhead.com/npc=21296):\n/way 41.2 47\n/way 48 50.8\n/way 38.8 58\n/way 40.2 50.2\nMap for the Bladespire Champion (http://www.wowhead.com/npc=21296):\nhttp://www.wowhead.com/maps?data=3522:415469471506402584391578\n\nAfter you've looted the https://www.wowhead.com/item=30416, you will have to go to Bloodmaul Outpost (http://www.wowhead.com/maps?data=3522:468755).\nWhen you're there, you will see two towers. One is called ''Northmaul Tower'', and the other one is called ''Southmaul Tower''. You will need to go to the ''Northmaul Tower''. Once there, plant your banner.\nThere will be 3 waves of Bloodmaul Ogres, and then the final boss.\n- Bloodmaul Goon (http://www.wowhead.com/npc=21294) x2\n- Bloodmaul Goon (http://www.wowhead.com/npc=21294) x1, Bloodmaul Geomancer (http://www.wowhead.com/npc=19952) x1\n- Bloodmaul Goon (http://www.wowhead.com/npc=21294) x1,                                      Bloodmaul Brute (http://www.wowhead.com/npc=19991) x1\n- Gurn Grubnosh (http://www.wowhead.com/npc=20116) x1\n\nDon't forget to loot Gurn Grubnosh (http://www.wowhead.com/npc=20116)!",
            date = "2014-01-11T08:15:15-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10518#comments:id=1933611",
        },
        {
            id = 24149,
            score = 132,
            author = "Borric",
            text = "To get the banner you have to kill the champion at 42,46. Really simple. Also It goes\n\n-2 Orcs\n-3 Orcs\n-4 Orcs\n- Gurn Grubnosh",
            date = "2007-01-25T02:24:09-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10518#comments:id=24149",
        },
        {
            id = 49983,
            score = 110,
            author = "30548",
            text = "Despite what most people seem to think, all of the mobs in this event are ogres, not orcs.",
            date = "2007-03-12T07:33:25-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10518#comments:id=49983",
        },
        {
            id = 13773,
            score = 83,
            author = "1633",
            text = "Tough to solo, but do-able.  The tower you're looking for is at 46, 74.  Plant the banner on top of the tower to start the event.\n\nYou'll face several waves of ogre baddies, starting with just two.  The waves spawn at the foot of the tower, run all the way to the top, and then turn aggressive towards you.  You can get to about midtower and drink without them aggroing if you run through them as they go up.\n\nThe mobs themselves are pretty standard orcs, no elites.  As a mage, I polymorphed one mob, and then used the circular ramp to frostnova and kite the remaining ones until they're dead.  Then, I can kill the last poly no problem.\n\nThere are four waves.  I'm not sure if the waves are the same each time.  These are the waves I got.\n\n- 2 orcs\n- 3 orcs\n- 3 orcs\n- Gurn Grubnosh\n\nGurn himself is no big deal - he hits kinda hard, but some good crowd control/roots will take care of that.\n\nThe quest text talks like the quest is an elite, my guess is that it will be come BC release.",
            date = "2006-12-12T03:06:57-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10518#comments:id=13773",
        },
        {
            id = 956159,
            score = 65,
            author = "501568",
            text = "Bladespire Clan Banner (http://www.wowhead.com/?item=30416) is obtained from Bladespire Champion (http://www.wowhead.com/?npc=21296)",
            date = "2010-01-25T04:16:18-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10518#comments:id=956159",
        },
    },
    [10519] = {
        {
            id = 30567,
            score = 264,
            author = "marskid2",
            text = "The Cipher of Damnation is an extremely long quest line in Shadowmoon Valley.  It is a prerequisite for attunement to The Eye in Tempest Keep and Mount Hyjal in Caverns of time.\n\"*\" Indicates quests with rewards.\n\nQuest Line\n1[A] - http://www.wowhead.com/?quest=10680 - \"The Hand of Gul'Dan\"\n1[H] - http://www.wowhead.com/?quest=10681 - \"The Hand of Gul'Dan\"\n2 - http://www.wowhead.com/?quest=10458 - \"Enraged Spirits of Fire and Earth\"\n3 - http://www.wowhead.com/?quest=10480 - \"Enraged Spirits of Water\"\n4* - http://www.wowhead.com/?quest=10480 - \"Enraged Spirits of Air\"\n5 - http://www.wowhead.com/?quest=10513 - \"Oronok Torn-Heart\"\n6* - http://www.wowhead.com/?quest=10514 - \"I Was A Lot Of Things...\" - Most annoying quest ever implemented in World of Warcraft.\n7 - http://www.wowhead.com/?quest=10515 - \"A Lesson Learned\"\n8 - http://www.wowhead.com/?quest=10519 - \"The Cipher of Damnation - Truth and History\"\n\nAt this point, the quests diverge into three separate lines (which can be done in any order) for each of Oronok's three sons who will in turn help you obtain the three Fragments of Damnation.\n\nQuest Line I - First Fragment of Damnation\n1 - http://www.wowhead.com/?quest=10521 - \"Grom'tor, Son of Oronok\"\n2 - http://www.wowhead.com/?quest=10522 - \"The Cipher of Damnation - Grom'tor's Charge\"\n3* - http://www.wowhead.com/?quest=10523 - \"The Cipher of Damnation - The First Fragment Recovered\"\n\nQuest Line II - Second Fragment of Damnation\n1 - http://www.wowhead.com/?quest=10527 \"Ar'tor, Son of Oronok\"\n2 - http://www.wowhead.com/?quest=10528 - \"Demonic Crystal Prisons\"\n3 - http://www.wowhead.com/?quest=10537 - \"Lohn'goron, Bow of the Torn-heart\"\n4 - http://www.wowhead.com/?quest=10540 - \"The Cipher of Damnation - Ar'tor's Charge\"\n5* - http://www.wowhead.com/?quest=10541 - \"The Cipher of Damnation - The Second Fragment Recovered\"\n\nQuest Line III - Third Fragment of Damnation\n1 - http://www.wowhead.com/?quest=10546 \"Borak, Son of Oronok\"\n2 - http://www.wowhead.com/?quest=10547 - \"Of Thistleheads and Eggs...\"\n3 - http://www.wowhead.com/?quest=10550 - \"The Bundle of Bloodthistle\"\n4 - http://www.wowhead.com/?quest=10570 - \"To Catch A Thistlehead\"\n5 - http://www.wowhead.com/?quest=10576 - \"The Shadowmoon Shuffle\"\n6 - http://www.wowhead.com/?quest=10577 - \"What Illidan Wants, Illidan Gets...\"\n7 - http://www.wowhead.com/?quest=10578 - \"The Cipher of Damnation - Borak's Charge\"\n8* - http://www.wowhead.com/?quest=10579 \"The Cipher of Damnation - The Third Fragment Recovered\"\n\nAfter completing the quests for the three Fragments of Damnation, the lines converge and you need to kill one last boss.\nFinal* - http://www.wowhead.com/?quest=10588 - \"The Cipher of Damnation\"\n\nRewards:\n\nEveryone gets http://www.wowhead.com/?item=31074 - Fire Resist Neck\n\nChoose one of the following:\nhttp://www.wowhead.com/?item=31036 - Caster Staff\nhttp://www.wowhead.com/?item=31038 - Healer Staff\nhttp://www.wowhead.com/?item=31062 - Paladin/Shaman 2H Axe\nhttp://www.wowhead.com/?item=31071 - Tanking 1H Axe\nhttp://www.wowhead.com/?item=31072 - Bow\nhttp://www.wowhead.com/?item=31073 - Melee Dagger\n\nAfter completing the quest, you will get a message in the mail from Khadgar.  If you go to Shattrath, he will tell you to talk to A'Dal, who unlocks the the three Trials.  These are prerequisites for attunement to The Eye in Tempest Keep and Mount Hyjal in Caverns of time.",
            date = "2007-02-04T12:05:48-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10519#comments:id=30567",
        },
        {
            id = 24131,
            score = 48,
            author = "Trapordie",
            text = "Follow-ups:\n\nFirst Fragment of Damnation: http://www.wowhead.com/?quest=10527\nSecond Fragment of Damnation: http://www.wowhead.com/?quest=10546\nThird Fragment of Damnation: http://www.wowhead.com/?quest=10521",
            date = "2007-01-25T01:27:31-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10519#comments:id=24131",
        },
        {
            id = 371314,
            score = 32,
            author = "entropicdragon",
            text = "The Cipher of Damnation - History and Truth - Oronok's Story\n((SPOILER ALERT!))\n\nAre you ready to hear the story of the Cipher of Damnation, ?\n\nI am ready to hear your story, Oronok.\nVery well. The words you seek have a name, . They are know as the Cipher of Damnation: The words uttered by Gul'dan himself to shatter this land. The very spell that severed the last remaining tie the orcs had with the elements of Draenor.\n\nAye, it is the cipher that you must reconstruct and ultimately the words of the cipher that you must call.\n\nHow do I find the cipher?\nThe Cipher of Damnation was kept in Gul'dan's private quarters inside Karabor for twenty years. Ah, that's right, you have no idea what Karabor is, do you?\n\nThe Black Temple...\n\nAye, now home to Illidan Stormrage.\n\nWhen Illidan took control of the Black Temple, he discovered the cipher. He recognized that the damage to this world had already been done but thought it wise to keep the cipher secure for later use.\n\nHow do you know all of this?\nWhen you stand at the Altar of Damnation and see the spirits of the damned, kneeling in prayer, what you do not see is me, standing next to Gul'dan.\n\nI told you that I was a lot of things, did I not? One of those 'things' was a lieutenant of Gul'dan.\n\nI have done many terrible things in my life. I have slaughtered man, woman, and  child alike. Danced in the blood of innocent draenei... yet...\n\nYet what? What is it, Oronok?\nI will never forget that day, draenei. Never. Even though I had long since abandoned shamanism in favor of shadow magic, I felt the cut. A sense of loss so profound...I could not explain it to you with mere words.\n\nWhen the tie to the elements was severed, all orcs on Draenor changed. If there was ever any doubt in the power of the shadows, it was washed away with the cresting of the molten lava over the shattered earth.\n\nContinue, please.\nA wave of sickness rushed through me. After the ritual was over I ran home to my children. I gathered what belongings I could carry in my arms and left with my boys. We ran to the hills and hid. There really was no other option...\n\nNot a day goes by that I don't think of the cut. It has taken 20 years to reconnect with the elements. it has taken 20 years for the elements to even begin to heal.\n\nSo what of the cipher now? And your boys?\nAs I said, the cipher was found by Illidan when he took over the Black Temple. He divided the tome into three parts and charged their care to his minions.\n\nMy boys... My boys are grown now. When I got word of what Illidan had done with the cipher, I sent my boys to recover the pieces.\n\nYou must find my boys, . You must find them and recover the Cipher of Damnation.\n\nI will find your boys and the cipher, Oronok.",
            date = "2008-09-07T21:59:22-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10519#comments:id=371314",
        },
        {
            id = 1360693,
            score = 3,
            author = "777044",
            text = "From what I know, this quest line is ONLY for the lore now... Attunement is void.",
            date = "2011-03-07T22:34:12-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10519#comments:id=1360693",
        },
        {
            id = 2300245,
            score = -1,
            author = "Aurleis1",
            text = "Video Guide: https://www.youtube.com/watch?v=7Hxm5s-3vP8\n\n1.  https://www.wowhead.com/quest=10519\n•\009Accept the quest, https://www.wowhead.com/quest=10519, from https://www.wowhead.com/npc=21183 at coords 53.8, 23.4 (Oronok's Farm).\n•\009Speak with https://www.wowhead.com/npc=21183, and select the further dialogue boxes, as they come up.\n•\009Turn in the quest to https://www.wowhead.com/npc=21183.",
            date = "2016-01-20T14:14:58-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10519#comments:id=2300245",
        },
    },
    [10521] = {
        {
            id = 30573,
            score = 85,
            author = "marskid2",
            text = "The Cipher of Damnation is an extremely long quest line in Shadowmoon Valley.  It is a prerequisite for attunement to The Eye in Tempest Keep and Mount Hyjal in Caverns of time.\n\"*\" Indicates quests with rewards.\n\nQuest Line\n1[A] - http://www.wowhead.com/?quest=10680 - \"The Hand of Gul'Dan\"\n1[H] - http://www.wowhead.com/?quest=10681 - \"The Hand of Gul'Dan\"\n2 - http://www.wowhead.com/?quest=10458 - \"Enraged Spirits of Fire and Earth\"\n3 - http://www.wowhead.com/?quest=10480 - \"Enraged Spirits of Water\"\n4* - http://www.wowhead.com/?quest=10480 - \"Enraged Spirits of Air\"\n5 - http://www.wowhead.com/?quest=10513 - \"Oronok Torn-Heart\"\n6* - http://www.wowhead.com/?quest=10514 - \"I Was A Lot Of Things...\" - Most annoying quest ever implemented in World of Warcraft.\n7 - http://www.wowhead.com/?quest=10515 - \"A Lesson Learned\"\n8 - http://www.wowhead.com/?quest=10519 - \"The Cipher of Damnation - Truth and History\"\n\nAt this point, the quests diverge into three separate lines (which can be done in any order) for each of Oronok's three sons who will in turn help you obtain the three Fragments of Damnation.\n\nQuest Line I - First Fragment of Damnation\n1 - http://www.wowhead.com/?quest=10521 - \"Grom'tor, Son of Oronok\"\n2 - http://www.wowhead.com/?quest=10522 - \"The Cipher of Damnation - Grom'tor's Charge\"\n3* - http://www.wowhead.com/?quest=10523 - \"The Cipher of Damnation - The First Fragment Recovered\"\n\nQuest Line II - Second Fragment of Damnation\n1 - http://www.wowhead.com/?quest=10527 \"Ar'tor, Son of Oronok\"\n2 - http://www.wowhead.com/?quest=10528 - \"Demonic Crystal Prisons\"\n3 - http://www.wowhead.com/?quest=10537 - \"Lohn'goron, Bow of the Torn-heart\"\n4 - http://www.wowhead.com/?quest=10540 - \"The Cipher of Damnation - Ar'tor's Charge\"\n5* - http://www.wowhead.com/?quest=10541 - \"The Cipher of Damnation - The Second Fragment Recovered\"\n\nQuest Line III - Third Fragment of Damnation\n1 - http://www.wowhead.com/?quest=10546 \"Borak, Son of Oronok\"\n2 - http://www.wowhead.com/?quest=10547 - \"Of Thistleheads and Eggs...\"\n3 - http://www.wowhead.com/?quest=10550 - \"The Bundle of Bloodthistle\"\n4 - http://www.wowhead.com/?quest=10570 - \"To Catch A Thistlehead\"\n5 - http://www.wowhead.com/?quest=10576 - \"The Shadowmoon Shuffle\"\n6 - http://www.wowhead.com/?quest=10577 - \"What Illidan Wants, Illidan Gets...\"\n7 - http://www.wowhead.com/?quest=10578 - \"The Cipher of Damnation - Borak's Charge\"\n8* - http://www.wowhead.com/?quest=10579 \"The Cipher of Damnation - The Third Fragment Recovered\"\n\nAfter completing the quests for the three Fragments of Damnation, the lines converge and you need to kill one last boss.\nFinal* - http://www.wowhead.com/?quest=10588 - \"The Cipher of Damnation\"\n\nRewards:\n\nEveryone gets http://www.wowhead.com/?item=31074 - Fire Resist Neck\n\nChoose one of the following:\nhttp://www.wowhead.com/?item=31036 - Caster Staff\nhttp://www.wowhead.com/?item=31038 - Healer Staff\nhttp://www.wowhead.com/?item=31062 - Paladin/Shaman 2H Axe\nhttp://www.wowhead.com/?item=31071 - Tanking 1H Axe\nhttp://www.wowhead.com/?item=31072 - Bow\nhttp://www.wowhead.com/?item=31073 - Melee Dagger\n\nAfter completing the quest, you will get a message in the mail from Khadgar.  If you go to Shattrath, he will tell you to talk to A'Dal, who unlocks the the three Trials.  These are prerequisites for attunement to The Eye in Tempest Keep and Mount Hyjal in Caverns of time.",
            date = "2007-02-04T12:08:28-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10521#comments:id=30573",
        },
        {
            id = 22646,
            score = 30,
            author = "13156",
            text = "He is at 44,23",
            date = "2007-01-22T02:30:47-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10521#comments:id=22646",
        },
        {
            id = 1904461,
            score = 27,
            author = "Lannipants",
            text = "I just tried to do this whole quest chain so I could get transmog from the last quest: [quest=10588 domain=www] and realised I couldn't.\n\nPLEASE BE AWARE;  That if you are on the warlock class quest for green fire ([quest=32295 domain=www]) you will be unable to complete this quest.\n\nFor some reason the naga areas (including where Grom'tor is) are phased, during this warlock quest. Some people have also been saying that, even after completing the warlock quest, the areas are still phased.\n\n(Read more here on wow forums http://eu.battle.net/wow/en/forum/topic/7391389909, http://us.battle.net/wow/en/forum/topic/9309341235)\n\nI wasn't aware of this problem until I tried to find Grom'tor and realised I was phased. Please upvote for awareness! ^^",
            date = "2013-10-01T04:44:01-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10521#comments:id=1904461",
        },
        {
            id = 590355,
            score = 9,
            author = "Valdan",
            text = "Ok folks.. Let me bring some reality checks for everyone who takes this quest truly understands the lore/insight on how truly long it is and how the \"Entire\" chain begins and ends.  I noticed the link and some though GREAT input on the chains but there not the entire chains accordingly.  They leave out where its supposed to be picked up, and in truth most of the time you \"cannot\" pick up the quest due to not doing the prior quest chains so if your on this quest below is what you may want to do or of course quit at any moment.  But the story doesn't end here clearly.\n\nQuest chain 1 (8 Parts) : (this one of course)\nHorde: The Hand of Gul'dan (http://www.wowhead.com/?quest=10681)\nAlliance: The Hand of Gul'dan (http://www.wowhead.com/?quest=10680)\nEnraged Spirits of Fire and Earth (http://www.wowhead.com/?quest=10458)\nEnraged Spirits of Water (http://www.wowhead.com/?quest=10480)\nEnraged Spirits of Air (http://www.wowhead.com/?quest=10481)\nOronok Torn-heart (http://www.wowhead.com/?quest=10513)\nI Was A Lot Of Things... (http://www.wowhead.com/?quest=10514)\nA Lesson Learned (http://www.wowhead.com/?quest=10515)\nThe Cipher of Damnation - Truth and History (http://www.wowhead.com/?quest=10519)\n\nThen as mentioned before there are the 3 quest in any order but MUST be completed in order to proceed to the next chain\n\n- These are the Fragment of Damnation Quest Series (3 Parts Totalling 16 Quest + 1 Final but not end of Chain = 17 Quest in all):\n(Part 1)\nGrom'tor, Son of Oronok (http://www.wowhead.com/?quest=10521)\nThe Cipher of Damnation - Grom'tor's Charge (http://www.wowhead.com/?quest=10522)\nThe Cipher of Damnation - The First Fragment Recovered (http://www.wowhead.com/?quest=10523)\n(Part 2)\nAr'tor, Son of Oronok (http://www.wowhead.com/?quest=10527)\nDemonic Crystal Prisons (http://www.wowhead.com/?quest=10528)\n- The NPC ghost will appear - The chain continues:\nLohn'goron, Bow of the Torn-heart (http://www.wowhead.com/?quest=10537)\nThe Cipher of Damnation - Ar'tor's Charge (http://www.wowhead.com/?quest=10540)\nThe Cipher of Damnation - The Second Fragment Recovered (http://www.wowhead.com/?quest=10541)\n(Part 3)\nBorak, Son of Oronok (http://www.wowhead.com/?quest=10546)\nOf Thistleheads and Eggs... (http://www.wowhead.com/?quest=10547)\nThe Bundle of Bloodthistle (http://www.wowhead.com/?quest=10550)\nTo Catch A Thistlehead (http://www.wowhead.com/?quest=10570)\nThe Shadowmoon Shuffle (http://www.wowhead.com/?quest=10576)\nWhat Illidan Wants, Illidan Gets... (http://www.wowhead.com/?quest=10577)\nThe Cipher of Damnation - Borak's Charge (http://www.wowhead.com/?quest=10578)\nThe Cipher of Damnation - The Third Fragment Recovered (http://www.wowhead.com/?quest=10579)\n\nNow mind you \"MUST\" complete the above 3 Parts & also turn them into Oronok before carrying forward.\n\n1 Quest\nThe Cipher of Damnation (http://www.wowhead.com/?quest=10588)\n\nNow also as mentioned before you will get a letter in the mail from\nKhadgar to go to Shattrath and speak with A'Dal.\n\nThis has unlocked your future chains not mentioned linking them together is what I think people should understand the can of worms your about to open:\n\n(4 Part Chain)\n4 Trials total however only 3 can be accepted at first.  They are 3 seperate quest given all at once so you can carry all 3 and complete and run back to turn in all together.  The 4th is after the original 3 are completed.\nThe first 3 are:\nTrial of the Naaru: Tenacity (http://www.wowhead.com/?quest=10886#comments) (HEROIC MODE) - Arcatraz (http://www.wowhead.com/?zone=3846) of Tempest Keep. - Note: Here your saving the mage who will be friendly but you kill this boss: Harbinger Skyriss (http://www.wowhead.com/?npc=20912)\nTrial of the Naaru: Strength (http://www.wowhead.com/?quest=10885) (HEROIC MODE) - Warlord Kalithresh (http://www.wowhead.com/?npc=17798) (Steamvault (http://www.wowhead.com/?zone=3715)) & Murmur (http://www.wowhead.com/?npc=18708) (Shadow Labyrinth (http://www.wowhead.com/?zone=3789)) in any order but both in Heroic Modes.\nTrial of the Naaru: Mercy (http://www.wowhead.com/?quest=10884) (HEROIC MODE) - Shattered Hand Executioner (http://www.wowhead.com/?npc=17301) (Shattered Halls of Hellfire Citadel (http://www.wowhead.com/?zone=3714))\n\nNow before we get to the fourth part do note after completing the initial 3 there is a mini chain the unlocks and continues on.  You can have both the 4th trial and this chain at the same time:\n\nTrial of the Naaru: Magtheridon (http://www.wowhead.com/?quest=13430) (Raid) - Magtheridon (http://www.wowhead.com/?npc=17257)\n\n(2 Part Chain)\nThe Mark of Vashj (http://www.wowhead.com/?quest=10900) - You talk to: Skar'this the Heretic (http://www.wowhead.com/?npc=22421#comments) (He is only found in Heroic Mode and is after the first boss)  in The Slave Pens (http://www.wowhead.com/?quests=2.3717) (Heroic Mode)\nThe Cudgel of Kar'desh (http://www.wowhead.com/?quest=10901)\n- Gruul the Dragonkiller (http://www.wowhead.com/?npc=19044) (Gruul's Lair (http://www.wowhead.com/?zone=3618)) & Nightbane (http://www.wowhead.com/?npc=17225) (Karazhan (http://www.wowhead.com/?zone=2562))\nDo note they can be completed in any order for the 2 dungeons on the last part of this quest chain.\n\nThat is all folks.\n\nQuest Grand Total: 31\nHeroic Dungeons: 5 (Slave Pens twice so technically 6)\nGold rewards/Items/Reputation and Experience gained I didn't do the math on sorry.\nNormal Difficulty Dungeons: 0\n\nNow there is a much longer chain in Ironforge but we wont go there.\n\nEdited for spelling issues",
            date = "2009-02-01T02:51:35-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10521#comments:id=590355",
        },
        {
            id = 190752,
