    [10524] = {
        {
            id = 17361,
            score = 188,
            author = "6934",
            text = "The arrow is up a stone ramp near the large bonfire in central Bladespire Hold(tloc 41,52).\n\nThe drum is in a small building guarded by a single mob in the Southern portion of Bladespire Hold(tloc 40,58)\n\nThe tablet is in North Bladespire Hold in a hut guarded by a single mob(tloc 41,46)",
