            text = "[Thunderlord Clan Tablet] and  [Thunderlord Clan Drum] are on the ground you can loot , but  [Thunderlord Clan Arrow] is on top of rock !",
            date = "2012-06-05T12:32:00-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10524#comments:id=1673661",
