    [10542] = {
        {
            id = 21960,
            score = 86,
            author = "11170",
            text = "Bewmasters drop the Brutebane brew, but they can also be found in barrels all around the outpost\n\nThe hookah being refered to is a \"waterpipe\" or a shisha, which can be found next to the fireplace at 42,81",
