            text = "Hookah is the middle-east/Indian (where I'm from) name for it. But yes, nice quest name.\n\nTroll quest names ftw.",
            date = "2007-01-26T13:51:01-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10542#comments:id=25113",
