            score = 10,
            author = "87150",
            text = "Keep an eye out for their kegs,it also contains their brew. Found one at the end of the Draenethys mine.",
            date = "2008-03-02T06:59:43-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10542#comments:id=246594",
        },
        {
            id = 523716,
            score = 6,
            author = "mapleshosho",
            text = "Brewmaster's drop the brew/beer. The kegs (They can be found all around the outpost of bloodmaul) also drop 1 or 2 at a time though, so what I would recommend is that you should try and loot the kegs. The \"Hookah\" is found at 42,81. And for those who don't have the cord's. . . Just go south of Dragon's end road, go to Bloodmaul Post, and you should go a little bit further south. You should a see a camp like thing of bloodmaul ogre's. At the back of the camp thing, You'll see 2 ogre's sitting down. Kill them, and the \"Hookah\" is right beneath them.",
            date = "2008-12-21T22:28:56-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10542#comments:id=523716",
        },
    },
    [10543] = {
        {
            id = 18093,
            score = 82,
            author = "9387",
            text = "Go south first and kill Grimnok. Make sure to take at least one mug of the brew from the camp (either in the barrels or kill a brewmaster). Then go north, place the mug at the entrance with Korgaah and the elites there, this will single pull Korgaah out.",
            date = "2006-12-27T11:35:17-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10543#comments:id=18093",
        },
