            text = "This is Son's of Oronok locatinon map:\nhttp://www.wowhead.com/?maps=3520:480570444234296506\n\n48, 57 Borak\n44,23 Grom'tor\n29, 50 Ar'tor",
            date = "2007-11-25T02:12:08-06:00",
