        {
            id = 1269163,
            score = 3,
            author = "Esilenna",
            text = "To \"undo\" your Aldor allegiance, you have to first do the quest Voren'thal's Visions (http://www.wowhead.com/quest=10024  ), and then grind your reputation up doing the repeatable quest More Basilisk Eyes (http://www.wowhead.com/quest=10025).",
            date = "2010-12-31T05:09:06-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10552#comments:id=1269163",
        },
        {
            id = 1691149,
            score = 3,
            author = "g0rg0n",
            text = "If you accidentally choose Aldor, your can de-rep Aldor and rep up Scryers. There is an NPC in Shattrath Arcanist Adyria (http://www.wowhead.com/npc=18596). She has a Quest https://www.wowhead.com/quest=10025.\n\nWhen I completed this turn in with both Aldor and Scryers unfriendly (immediately after choosing the wrong faction) in 4.3 I received:\n\n+275 Scryers\n-303 Aldor\n+137 Sha'tar",
            date = "2012-07-22T18:36:40-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10552#comments:id=1691149",
        },
    },
    [10553] = {
        {
            id = 22396,
            score = 10,
            author = "13062",
            text = "This quests changes your reputation to friendly with the Scryers and hostile with the Aldor. You will be unable to interact with any of the NPCs of the latter faction. It is possible to 'swap' your reputation later, but it takes up alot of time. For information about the differences between the two factions, see WoWWiki (http://www.wowwiki.com/Aldor_vs._Scryer).",
            date = "2007-01-21T03:53:24-06:00",
