    [10555] = {
        {
            id = 22238,
            score = 42,
            author = "freak",
            text = "Plucked Feather's drop from mobs in Veil Lash. Entrance around 35, 73.\n\nOnce you have 18, go up the bridge (34, 76) and complete quest at the book on the right side of the top part.",
            date = "2007-01-20T19:25:36-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10555#comments:id=22238",
        },
        {
            id = 64472,
            score = 15,
            author = "41639",
            text = "Make sure you do the second step and read the book i went back and then wondered why quests was not completed!",
            date = "2007-04-09T14:30:26-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10555#comments:id=64472",
        },
        {
            id = 84247,
            score = 11,
            author = "Salali",
            text = "I can't confirm this 100%, however I am pretty sure if you get more than 18 feathers, the quest completion only removes the 18 required (the rest remain in your inventory).\n\nThe reason I say this is because I did all the Sylvannar quests to my knowledge includin' a few at the Arakkoa camp...and this feather, after searching Wowhead, has no other links to it. Personally, I'm deletin' this last feather, as I am pretty sure I did the quest.\n\nConfirm extra feathers remain inventoried?",
            date = "2007-05-16T20:26:17-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10555#comments:id=84247",
        },
        {
            id = 24370,
            score = 6,
            author = "Wikki",
            text = "The feathers drops from the birdmen, named Lashh'an, they are not at the cave entrance but in the woods at 35, 76.",
            date = "2007-01-25T11:55:36-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10555#comments:id=24370",
        },
        {
            id = 249487,
            score = 6,
            author = "Christor",
            text = "The drop rate is said to be around 50% and often the feathers drop two at a time.",
            date = "2008-03-07T07:55:55-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10555#comments:id=249487",
        },
    },
    [10556] = {
        {
            id = 23541,
            score = 178,
            author = "Mayday",
            text = "Location 35,77 for the circle, use one of the feathers you've collected.\nAfter using the feather you will get a (Pet bird) totem witch last for 10 minutes, before that time you have to see Daranelle at 37,65 to finish the quest (3,50 Gold and 8550 XP)",
            date = "2007-01-24T07:07:47-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10556#comments:id=23541",
        },
        {
            id = 1814168,
            score = 117,
            author = "Cakechart",
            text = "Summary of the most useful information I found in the comments:\n\n1. Use the quest item (\"Fistful of Feathers\") at a summoning circle in the southern Arrakoa village\n2. A grey bird will be summoned and follow you around (like a pet) and you'll receive a buff called \"Lashh'an Channeling\"\n3. Do NOT mount to prevent it from bugging / despawning\n4. Walk back to Sylvanaar (the Alliance base to the north) with the bird still following you\n5. As soon as you come close to the NPC, Daranelle, the quest objective will be completed. She's at the right side of the road as you enter Sylvanaar, after the crossing and hidden behind a small hill if you're walking through the main \"gate\".\n\nPS: Do not dawdle while the bird is following you, it will despawn after 10 minutes and you'll have to summon it again.",
            date = "2013-02-16T02:16:03-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10556#comments:id=1814168",
        },
        {
            id = 2134034,
            score = 87,
            author = "CandyKills",
            text = "To be crystal clear ...use the feathers at one  circle...it summons the bird and you do not need to do the other circle then. Run (not fly or you will lose the bird) back to the camp THO the quest shows up as tho you have not done enough to turn the quest in. As soon as you get near to the NPC Daranelle  the yellow  question mark pops up and you can turn it in.",
            date = "2015-03-10T03:34:46-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10556#comments:id=2134034",
        },
        {
            id = 43519,
            score = 59,
            author = "27662",
            text = "After you finish the quest and she says that she must analyze it first, then she will talk. She doesn't actually give you another quest so don't wait around like I did. ^.^",
            date = "2007-02-27T16:59:53-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10556#comments:id=43519",
        },
        {
            id = 211823,
            score = 39,
            author = "112222",
            text = "Daranelle does not appear on the Minimap with a ? sign, you must walk past Daranelle, she will talk and you can complete the quest.\n\nRewarded me 8550 experience, aswell as 3 gold 50 silver.",
            date = "2008-01-02T20:52:24-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10556#comments:id=211823",
        },
    },
    [10557] = {
        {
            id = 27389,
            score = 26,
            author = "15689",
            text = "Rally Zapnabber will not show up on your minimap, but he's only a few steps south-west of Tally (under the platform).\n\nTalking to him will send you soaring back down the hill to R-3DO.",
            date = "2007-01-29T20:57:01-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10557#comments:id=27389",
        },
        {
            id = 24779,
