    [10562] = {
        {
            id = 215795,
            score = 11,
            author = "Amoa",
            text = "If I shot any of the infernals with under 30% hp then I did NOT receive any quest credit. Even if I critted high and 1 hit them from 29% or lower I would still not get credit. As long at the HP said 30% or more when I started shoting them then I would get the credit.",
            date = "2008-01-09T18:46:19-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10562#comments:id=215795",
        },
        {
            id = 524808,
            score = 3,
            author = "210916",
            text = "This couldn't be easier (depending on your level - your mileage may vary). Pick the infernal closest to the gate and whack it. Chances are it won't count toward the total as others have described. A new one spawns in about 10 sec, though, so you just camp on the same spot and in five minutes you're done.",
            date = "2008-12-22T13:20:46-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10562#comments:id=524808",
        },
        {
            id = 178995,
