            author = "97610",
            text = "The above comments only seem to work on some of the infernals, not others. The one directly outside would not work for me, I had to go farther away, north.",
            date = "2007-11-04T10:38:32-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10562#comments:id=178995",
        },
        {
            id = 1377882,
