    [10563] = {
        {
            id = 25181,
            score = 55,
            author = "14181",
            text = "To clarify the above post..\n\nCoordinates are correct (23,36) but when you see the field of infernals, turn right...the communications crystal is on the platform there.\n\nClick the box in your inventory and you will turn into a box...a scripted event will occur and you will get the objective complete texxt.",
            date = "2007-01-26T15:47:10-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10563#comments:id=25181",
        },
        {
            id = 32501,
            score = 45,
            author = "15530",
            text = "With a /nod to the Metal Gear series.. Your disguise is very Solid.",
            date = "2007-02-08T01:00:34-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10563#comments:id=32501",
        },
        {
            id = 50155,
            score = 25,
            author = "25831",
            text = "Rather easy quest to complete at lvl 70, with a flying mount.  The communicator is on a balconey, it's green with a pink hologram of an infernal, nestled in between two fel cannons and two fel demons.  If you swoop down and land right next to the communication device with your flying mount you will not agro the fel cannons/demons.  Once you get there just turn into a box and after 1 minute of dialogue you will get your quest complete.\n\nAlso, it did not bug for me so perhaps they fixed it in the last patch. LOL oh who am I kidding, I probably just got lucky.",
            date = "2007-03-12T15:33:20-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10563#comments:id=50155",
        },
        {
            id = 880803,
            score = 15,
            author = "444500",
            text = "Deathbringer Jovaan says: It shall be as you say, warbringer. One last question, if I may...\n\nImage of Warbringer Razuun says: Yes?\n\nDeathbringer Jovaan says: What's in the crate?\n\nMe Thinks: *OH CRAP*\n\nImage of Warbringer Razuun says: Crate? I didn't send you a crate, Jovaan. Don't you have more important things to worry about? Go see to them!\n\nI was cracking up at that",
            date = "2009-11-01T20:01:46-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10563#comments:id=880803",
        },
        {
            id = 151551,
            score = 11,
            author = "55557",
            text = "For those with flying mounts:\n\nExact coords: 23.6, 36.8\n\nLocation is on the ledge beside the pink \"Legion Communication Device\"\n\nLand on the ledge, click the disguise \"Box o' Tricks\" and wait to complete quest after the dialogue finishes.",
            date = "2007-09-11T06:35:44-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10563#comments:id=151551",
        },
    },
    [10564] = {
        {
            id = 22058,
            score = 43,
            author = "ubermonkey",
            text = "Green Glyph - 22.6, 39.9\n\nThe Glyph pulses in and out so if you don't see it right away wait about 5 seconds.",
            date = "2007-01-20T12:30:19-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10564#comments:id=22058",
        },
        {
            id = 92315,
            score = 24,
            author = "13060",
            text = "Tip. You don't have to stand in middle to complete. I stood about 7-10 yards away from the outer tip of circle, didn't have to aggro anything.\n\nProphet is non elite for the record as well, so if you choose to kill, should be simple.",
            date = "2007-05-28T08:09:42-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10564#comments:id=92315",
