        {
            id = 784009,
            score = 7,
            author = "Karang",
            text = "Text after handing in quest:\n\nDertrok: Cansis, hold still. I'm going to try to use this crystal.\nDertrok: *waves crystal around, putting Cansis under a concussive (hypnosis) spell*\nDertrok: Interesting... Let me try something.\nCansis. You are a chicken.\nCansis: *flaps arms like a chicken*\nDertrok: Fascinating.\nCansis: *breaks out of trance*\nCansis: If you ever do that again, I will break your neck.\n\nI found it funny :D",
            date = "2009-07-21T00:03:52-05:00",
