        },
        {
            id = 690195,
            score = 12,
            author = "125137",
            text = "alright, so apparently, u need to complete either Alleigence to Aldor, or Alleigence to Scryers quest, prior  to taking this one, as Anchorite Ceyla doesn't offer me dat q, even when im neutral wit aldor and unfriendly wit scryers.\n\nso heads up.",
            date = "2009-04-23T03:04:09-05:00",
