            author = "Wolfspider",
            text = "35,32 confirmed, theres more than enough mobs here, and the drop rate for the pages is very high. Aside from the fears mentioned earlier, watch out for the owls flying around; they're full-blown monsters, not just pets, and can do a lot of damage if you're already in the middle of a fight.",
            date = "2007-02-07T09:52:04-06:00",
