            text = "You will need to have completed all 3 parallels of The Cipher series then turn in to Oronok in order to begin the reunified chain.",
            date = "2007-04-30T10:57:40-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10579#comments:id=75418",
        },
