    [10582] = {
        {
            id = 63938,
            score = 10,
            author = "41184",
            text = "Just enter in cave at 40.39",
            date = "2007-04-08T15:19:52-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10582#comments:id=63938",
        },
        {
            id = 39206,
            score = 6,
            author = "24017",
            text = "when you go to the tower get the quest and stair in the direction of the quest giving NPC, align him with the deathforge.  when you start walking along that line jump into the pit (not sure all classes will survive this jump).  once you fall into the pit immediatly on your left there is a cave, theres plenty of each in there, but be carful if you begin pulling them make sure there pulls, sorry rogues you cant pick them off by stealth, u must pull, or the place can become an agro haven.",
            date = "2007-02-20T09:26:09-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10582#comments:id=39206",
        },
        {
            id = 1489995,
            score = 6,
            author = "Grukam",
            text = "Just north of the tower where the quest giver is there are some guardians strewn about in the fields all lonely and looking to die, very easy. At 41.46 35.82 is a bridge type structure that has 1 summoner w/imp and guardians at each end. They respawn pretty quick so kill these first the work the next brige/path area at 40.33 34.02 for another summoner/imp combo further up are a couple more guardians. Another path at 38.89 35.12 has another summoner/imp. By this time the first set should have respawned, rinse and repeat, no cave, no gang rapes with no place to go. Unless you like being gang raped then go to the cave.",
            date = "2011-08-08T09:02:35-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10582#comments:id=1489995",
        },
        {
            id = 30243,
            score = 5,
            author = "19108",
            text = "You can find tons of these around 38,35.  The Summoners are a bit harder to find.  Venture down the \"alley\" and you'll find an underground area with more.\n\nGL.",
            date = "2007-02-03T19:37:18-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10582#comments:id=30243",
        },
        {
            id = 735877,
            score = 1,
            author = "383831",
            text = "Easy way in is a path starting around  39.5, 36,2. There are a few guardians to kill in the immediate area, the remaining mobs in the cave. Avoid the elites whenever possible. Easy at lvl 71 paladin.",
            date = "2009-06-03T08:10:24-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10582#comments:id=735877",
        },
    },
    [10583] = {
        {
            id = 26375,
            score = 61,
            author = "12782",
            text = "Enter the cave at 40.38, then rich 34.39. You need to speak with dead dwarf.",
            date = "2007-01-28T12:49:20-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10583#comments:id=26375",
        },
        {
            id = 189827,
            score = 38,
            author = "83931",
            text = "Better than having any exact coordinates for the corpse, simply go to 40,38 as stated above, take the tunnel to the right. Move to the very end of this tunnel, it will be quite a lot of mobs to fight on the way and the the fact that newly made elementals to craft infernals are being escorted from the summoning room into the \"factory\" and they are being spawned regulary. When you reach a door requiring Deathforge Key you've reached a milestone, skip the door and keep moving. Next into the narrow tunnel, keep in the middle and fight the newly made infermals and after those you will meet two deathforge guardians. Behind them stands a summoner with his demon, kill him and you've free passage to the corpse of Flanis.\n\nIf you're a ranged class the corpse of the summoner might drop down over Flanis, so you don't do the mistake of not being able to find him like I did (went back out again thinking where the heck this guy could be), so I was there twice. Fortunatly I checked extra carefully and his corpse was under the summoner :-)",
            date = "2007-11-23T06:29:47-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10583#comments:id=189827",
        },
        {
            id = 1817850,
            score = 18,
            author = "989011",
            text = "Can't be emphasized enough: There are two entrances to cages. The one you used before in earlier quests, all the way down the ramp, is the wrong one. The right one is half way down the ramp, easily to be missed, particularly if you're flying to the one \"you know to be the right one\".\n\nIf you're in the right one, make your way all the way to the (half way right) end. You don't need to get through the gate on your left.",
            date = "2013-02-24T20:07:33-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10583#comments:id=1817850",
        },
        {
            id = 2300260,
            score = 15,
            author = "Aurleis1",
            text = "Video Guide: https://www.youtube.com/watch?v=kDHpEA18Zc4\n\n1.  https://www.wowhead.com/quest=10583\n•\009Accept the quest, https://www.wowhead.com/quest=10583, from https://www.wowhead.com/npc=21471 at coords 40.4, 41.2 (Deathforge).\n•\009Travel north, and enter the Deathforge at coords 40.1, 38.3.\n•\009Follow the passage to 37.2, 41.7, and then turn right (west).\n•\009Follow the path to coords 34.6, 39.8.\n•\009Loot https://www.wowhead.com/npc=21711 from https://www.wowhead.com/npc=21727, a dead dwarf laying on the ground.\n•\009Exit the Deathforge.\n•\009Travel south to coords 40.4, 41.2.\n•\009Turn in the quest to https://www.wowhead.com/npc=21471.",
            date = "2016-01-20T14:31:24-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10583#comments:id=2300260",
        },
        {
            id = 242358,
            score = 12,
            author = "34211",
            text = "The three quests inside Deathforge; The Fate of Flanis, The Summoning Chamber and the followup, Bring Down the Warbringer! are admittedly quite tough to solo for anyone who can't stealth in or handle at least 3-4 mobs at range.  As a BM Hunter I had a few close calls but after the third trip in to get the Warbringer I had a good strat.\n\nMove down the ramp killing the guards, wait for the pathing fire elemental and escorting tinkerers, send pet on elemental, the two tinkerers will head for you in short order and as soon as the elemental drops about 25%.  They will plant a bomb near you, so trap one, move away from bomb, feign death, burn down the elemental have pet intimidate the untrapped tinkerer, burn it down and by that time the trapped one will be ready.\n\nFor the warlocks my normal strat is send pet on Warlock, kill imp and finish up warlock.  The bridge  you cross to reach the room with the infernals will have 4 warlock/imp mobs and one pathing in the centre.  You can take out the guards at the start of bridge, take out the pathing one and then move across safely taking out the others.  If you've killed the pathing fire elemental before the bridge, chances are it will be coming through again by the time you get through the warlocks, so watch your back.\n\nAfter the bridge you'll see the portcullis door to the left (go back to here for Warbringer), hug wall and move forward to the right.  The tinkerers here will likely bring one to help so watch the adds.  Don't kill the dormant infernals (suspended orbs), they won't aggro you.  At the end of the hall in a room is Flanis.  Like mentioned above, the mob I killed landed on his body and I had a hard time seeing him on the floor.\n\nAs an aside, sure corpse runs are fine, stealthing is fine, but It is really worth clearing the mobs in the area to complete quest if you can handle it or have a friend to help.  After the three quests I had 3x Fel Armaments, 25 Marks of Sargeras, 6 Greens, almost 3 stacks of cloth and the coin drops from mobs.  Add the gold reward for quests at 70 and your getting close to 150g.  Not bad for about an hour of work. To be honest with some better gear I'd be tempted to farm this area in the future.\n\nGood luck.",
            date = "2008-02-24T02:07:52-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10583#comments:id=242358",
        },
    },
    [10584] = {
        {
            id = 44291,
            score = 102,
            author = "24372",
            text = "Not related to the quest at all, but this is a reference to Star Wars: A New Hope. Luke Skywalker's uncle asks him to clean the droids he just bought, and Luke's whiney protest was: \"But I was headed to Toshley's station to pick up some power converters!\"\n\nThese guys at Blizz are fun.  Keep on truckin!",
            date = "2007-03-01T00:57:35-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10584#comments:id=44291",
        },
        {
            id = 23055,
            score = 80,
            author = "13645",
            text = "You will find them on the ground in the encampment located at approximately 57, 57.  Open the power converter, use your item on it, then kill it. See screenshots for a visual.",
            date = "2007-01-23T02:30:58-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10584#comments:id=23055",
        },
        {
            id = 24710,
            score = 64,
            author = "6859",
            text = "When you click the Electroelemental, don't use the quest item on it immediately.  Their damage goes up quite a bit once encased in the bubble.  Instead, take them down to 50% health, THEN use the quest item.\n\nMuch easier and quicker that way.",
            date = "2007-01-25T22:19:24-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10584#comments:id=24710",
        },
        {
            id = 69853,
            score = 27,
            author = "Deckard",
            text = "The power converters are scattered all over the ogre camp. Here are the ones I found:\n\n56.7, 56.4\n57.0, 55.0\n57.3, 54.4\n57.5, 55.8\n57.7, 57.0\n57.7, 57.2\n57.5, 60.7\n58.1, 55.2\n58.5, 54.2\n59.0, 55.8\n59.8, 54.6",
            date = "2007-04-19T22:31:32-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10584#comments:id=69853",
        },
        {
            id = 2023163,
            score = 13,
            author = "eszetela",
            text = "For 90 and above players going for the toy at the end of the chain:\n\nClick ground item, use quest item immediately.  You don't have to soften them up to use it, thankfully.  Then kill them.  Simple.",
            date = "2014-11-02T18:15:46-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10584#comments:id=2023163",
        },
    },
    [10585] = {
        {
