            author = "16133",
            text = "As you go down the ramp towards the caves, take the first one to your right.  Kill mobs in here until you get the displacer, then go outside and head to the next cave.  Kill the summoners in there and follow the rest of the quest",
            date = "2007-01-26T13:52:22-06:00",
