        {
            id = 32674,
            score = 34,
            author = "WitchKing",
            text = "Correct link for the Alliance quest is:\n\nhttp://www.wowhead.com/?quest=10586\n\nThe link above is for the Horde quest.",
            date = "2007-02-08T13:44:06-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10585#comments:id=32674",
        },
        {
            id = 2300259,
            score = 29,
            author = "Aurleis1",
            text = "Video Guide: https://www.youtube.com/watch?v=d2tPNhoTWuw\n\n1.  https://www.wowhead.com/quest=10585\n•\009Accept the quest, https://www.wowhead.com/quest=10585, from https://www.wowhead.com/npc=21471 at coords 40.4, 41.2 (The Deathforge).\n•\009Travel north, and enter the Deathforge at coords 40.1, 38.3.\n•\009Follow the passage, and kill https://www.wowhead.com/npc=19756 or https://www.wowhead.com/npc=19754, then loot the https://www.wowhead.com/item=30672 from their corpse.\n•\009Turn around, and head to coords 38.9, 38.6.\n•\009Jump off the edge and go to 37.8, 38.2.\n•\009Kill the https://www.wowhead.com/npc=20872 which is present, and use the https://www.wowhead.com/item=30672.\n•\009Kill the https://www.wowhead.com/npc=21735 that spawns.\n•\009Exit the Deathforge through the passage at 39.6, 39.8.\n•\009Travel to coords 40.4, 41.2.\n•\009Turn in the quest to https://www.wowhead.com/npc=21471.",
            date = "2016-01-20T14:30:37-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10585#comments:id=2300259",
        },
        {
