        },
        {
            id = 100594,
            score = 6,
            author = "59599",
            text = "25, 35 easy quest",
            date = "2007-06-08T07:05:42-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10589#comments:id=100594",
        },
        {
            id = 44865,
            score = 5,
            author = "26387",
            text = "Dropped by Mo'arg Weaponsmiths: http://www.wowhead.com/?npc=19755\n\nWas the first drop for me.",
            date = "2007-03-02T01:18:04-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10589#comments:id=44865",
        },
        {
            id = 2300247,
            score = 4,
            author = "Aurleis1",
            text = "Video Guide: https://www.youtube.com/watch?v=N1rWXViPYyw\n\n1.  https://www.wowhead.com/quest=10589\n•\009Accept the quest, https://www.wowhead.com/quest=10589, from https://www.wowhead.com/npc=21357 at coords 39.4, 53.6 (Wildhammer Stronghold).\n•\009Travel northeast, to Legion Hold, in the vicinity of coords 22, 30.\n•\009Kill https://www.wowhead.com/npc=19755, until you loot the https://www.wowhead.com/item=30695, from its corpse.\n•\009Travel southeast, back to Wildhammer Stronghold, to coords 39.4, 53.6.\n•\009Turn in the quest to https://www.wowhead.com/npc=21357.",
            date = "2016-01-20T14:15:37-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10589#comments:id=2300247",
        },
    },
    [10594] = {
        {
            id = 633924,
            score = 222,
            author = "106847",
            text = "Something exactly you need to know.\nMake any shape that produces five or more beams.\nRun ACROSS five beams  (not along them) quickly. It's done.\nWith eacn beam you ran across, you get a buff which lasts only 2 seconds.\nYou need to collect all these five buffs before they fade and that will complete the quest objective.\nIt took me an hour before I figure out what it means, since no one here mention that.",
            date = "2009-03-07T02:57:20-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10594#comments:id=633924",
        },
        {
            id = 27888,
            score = 86,
            author = "Flyv",
            text = "To do this quest you need to be in Singing Ridge, in the vicinity of 60, 76. Clear a large area (5-6 mobs worth) and then start dropping scanners. Every time you drop a scanner there's a chance a Wyrm from Beyond (http://www.wowhead.com/?npc=21796) will spawn. Not too hard to solo, but keep an eye out.\n\nYou have to work fairly quickly, the scanners are on a short timeout. The scanners have some restrictions on where they can be placed, but it's not simply distance; I've put two within five yeards of each other Look to your buffs for plus-sign shaped buffs showing you the scanners in range, and a minus-sign shaped debuff if you can't drop a scanner where you're staying.",
            date = "2007-01-30T20:08:18-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10594#comments:id=27888",
        },
        {
            id = 26952,
            score = 46,
            author = "13265",
            text = "The quest is easy. Clear out an area, and lay five scanners in a star formation. The overlap point will be the centre of the star.",
            date = "2007-01-29T07:22:19-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10594#comments:id=26952",
        },
        {
            id = 1436446,
            score = 31,
            author = "838943",
            text = "The easiest way to complete this quest is to drop a scanner, then mount up on your flying mount and fly straight up. After you loose your debuff, dismount (in mid air) and drop a new scanner. It will still appear on the ground even though it is dropped in mid air. rinse and repeat and you will have 5 scanners on top of each other.",
            date = "2011-06-07T15:39:46-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10594#comments:id=1436446",
        },
        {
            id = 326535,
            score = 18,
            author = "bleiddyn",
            text = "Also, if you're a druid who happens to have flight form, this becomes trivial.  Just drop the scanner, pop into flight form, and take off, fly to next, and repeat.  You might summon worms, but they get very sad when you fly away.  They don't hang around after, either.",
            date = "2008-07-14T21:24:24-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10594#comments:id=326535",
        },
    },
    [10595] = {
        {
            id = 26750,
            score = 6,
            author = "16172",
            text = "Right outside of town kill the guys with the infernals at 34, 34 and make sure you pickup the ashes on the ground they are for another quest.",
            date = "2007-01-28T23:48:17-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10595#comments:id=26750",
        },
        {
            id = 26779,
            score = 5,
            author = "17301",
            text = "Infernals are right outside, but don't bother killing the ones that are halfway dead.  Most of the time they don't count towards your quest goal.  Pick the ones that have over half of their health left at least and kill them.  It's also handy to stand near or drag them back to the guards around that are killing them.",
            date = "2007-01-29T00:34:51-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10595#comments:id=26779",
        },
    },
    [10596] = {
        {
            id = 21963,
            score = 44,
            author = "ubermonkey",
            text = "23.6, 36.9 - Legion Communication Device",
            date = "2007-01-20T07:42:51-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10596#comments:id=21963",
        },
        {
            id = 30040,
            score = 29,
            author = "Stagen",
            text = "Ok, the trick to this quest is to do as little as possible. The mobs have short aggro range so you can actually bypass a lot of them. They also have low health so they are easy to kill. The different mobs do however have some nasty abilities, like fear and a steady ticking fire blast. All easily avoided if you kill them quickly.\n\nIf you're on foot, you have to take the ramp up. The communication device is on a big platform in the center of the camp, flanked by two great walls. Inside there's 4 guards and 2 cannons. There's also a big mammoth of a demon, an elite, but he patrols in a counter clockwise path so you can wait for him to move and then go to action. You only need to kill 2 guards and a cannon on one side to get to the device. Run to the device and use the box while standing on the ledge. (best view) Observe, and jump down afterwards. Easy peasy, tbh.",
            date = "2007-02-03T12:45:15-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10596#comments:id=30040",
        },
        {
            id = 133640,
            score = 14,
            author = "75781",
            text = "Very funny quest. \"What's in the crate?\"\nBrings me back to the days of Metal Gear Solid :)",
            date = "2007-08-07T05:09:14-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10596#comments:id=133640",
        },
        {
            id = 27057,
            score = 7,
            author = "16172",
            text = "ok quest is not that badrun all the way up the hill  it's at 23 36 little hard to see. The guys drop good loot and they are easy. I liked this quest... you also pickup a illidari bane shard which starts another quest and does increased damage and attack power... ap by 45 spell damage by 185 to demons as a quest item to use. Not bad overall and a little of a pain like allforcarrie said if you die. Never got feared once either... hmmm... good quest. not sure how the heck you do this without dying...",
            date = "2007-01-29T10:35:38-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10596#comments:id=27057",
        },
        {
            id = 250919,
            score = 7,
            author = "129177",
            text = "It is definitely possible to complete this quest without dying and still not having a flying mount. I managed without much problems as a prot pally at 68, by just taking on one mob at a time and making sure that Makazradon (http://www.wowhead.com/?npc=21501) (the elite mob) isn't around while I'm hacking around to get to the communication station.\n\nThat said, the Terrormasters can cause problems as they can fear you into running into some of the mobs around (including Makazradon (http://www.wowhead.com/?npc=21501)). It is vital you are in control of the situation at any given time and stun the Terrormasters and kill them off before you are feared.\n\nI nearly did die when I was feared and ran into Makazradon (http://www.wowhead.com/?npc=21501) (who wasn't pleased to see me). Somehow I managed to stun the Terrormaster, run for my life and get out with 1 HP left =D, as the elite mob won't chase you that far.\n\nPS: I'd strongly recommend you to kill Overseer Ripsaw (http://www.wowhead.com/?npc=21499) who is in this area (a non-elite) to get the  Illidari-Bane Shard (http://www.wowhead.com/?item=30579) that leads to a quest (http://www.wowhead.com/?quest=10623).",
            date = "2008-03-09T22:05:20-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10596#comments:id=250919",
        },
    },
    [10597] = {
        {
            id = 29201,
            score = 75,
            author = "16172",
            text = "26, 41 under water great info for the core\n22, 35 next to the big guy for the armor spot on guys.",
            date = "2007-02-01T23:07:53-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10597#comments:id=29201",
        },
        {
            id = 100665,
            score = 49,
            author = "djcsliepx",
            text = "What happen ?\nSomebody set up us the bomb!\nWe get signal.\nWhat !",
            date = "2007-06-08T10:00:44-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10597#comments:id=100665",
        },
        {
            id = 201271,
            score = 11,
            author = "108286",
            text = "FYI: A named mob called Ripsaw walks around near the Fel Reaver Armor Plate.  If you kill him, a quest item drops that you can turn in for 9 gold 65 silver (at level 70).  It then leads to: http://www.wowhead.com/?quest=10627",
            date = "2007-12-14T17:16:34-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10597#comments:id=201271",
        },
        {
            id = 102690,
            score = 4,
            author = "61292",
            text = "Coordinates cofirmed.\n\nDwarves can use treasure finding to spot them on the mini-map.",
            date = "2007-06-11T20:53:19-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10597#comments:id=102690",
        },
        {
            id = 1391348,
            score = 2,
            author = "801529",
            text = "It's a good idea to use a flying mount to maneuver through all the enemies",
            date = "2011-04-14T16:24:59-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10597#comments:id=1391348",
        },
    },
    [10598] = {
        {
            id = 24379,
            score = 39,
            author = "Delusionary",
            text = "23,39 is the glyph location\nMorgroron, 68 Elite paths near the glyph be sure to wait until he is away to attempt this.",
            date = "2007-01-25T12:22:42-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10598#comments:id=24379",
        },
        {
            id = 113540,
            score = 15,
            author = "13128",
            text = "If you have a flying mount and are level 70 you can do this quest without killing anything.  Just land at exactly 22, 39 (just NE of the glyph) and use the bomb and then take back off.  Make sure the Elite is not too close.  The demon and the orc do not aggro if you're in the correct position.",
            date = "2007-06-30T21:00:17-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10598#comments:id=113540",
        },
        {
            id = 26777,
            score = 14,
            author = "17301",
            text = "There is also a mob standing inside the glyph you have to kill, after you kill her stand inside, it's a glowing green circle.  You should be pretty much between both fields of infernals, make sure Morg, the big 69 elite demon is nowhere near you, and set it off.  Fairly simple quest. Getting out without being knocked off of your mount and killed is another story..",
            date = "2007-01-29T00:32:50-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10598#comments:id=26777",
        },
        {
            id = 100672,
            score = 11,
            author = "djcsliepx",
            text = "If you're on a flying mount, you can land in the group of infernals and clear the mobs near the glyph. The infernals will not attack.",
            date = "2007-06-08T10:14:42-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10598#comments:id=100672",
        },
        {
            id = 334665,
            score = 9,
            author = "149600",
            text = "Easy for lv 69 druid, just land there kill the red women in thong and activate the bomb and fly up!",
            date = "2008-07-24T06:47:05-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10598#comments:id=334665",
        },
    },
    [10599] = {
        {
            id = 24483,
