    [10600] = {
        {
            id = 26784,
            score = 18,
            author = "17301",
            text = "Might want to get a friend to help with this one, it is soloable, but once you get down inside the cave the respawns tend to get a litle nasty.  It's fairly crowded in there too so the locks and imps wreak havoc.  I find it easier to kill the imp first since it has little HP and outputs quite a bit of damage.  Find a nice AOE mage and you're good =p",
            date = "2007-01-29T00:37:59-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10600#comments:id=26784",
        },
        {
            id = 29236,
            score = 17,
            author = "11612",
            text = "Follow ups are:\nhttp://www.wowhead.com/?quest=10601\nand\nhttp://www.wowhead.com/?quest=10602",
            date = "2007-02-02T00:48:39-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10600#comments:id=29236",
        },
