    [10601] = {
        {
            id = 38116,
            score = 146,
            author = "22271",
            text = "Just to clarify the above comments, there's a cavern on the bottom with lava, and a tunnel on the top with Demons. If you're in the cavern, go back to the entrance and follow the ramp up to the tunnel. Pass the Demons until you reach the Dormant Elementals. It is just before the last pair of Dormant Elementals that you will find Korgash's body (which can be looted for his backpack).\n\nIf you find Flanis Swiftwing at the end of the tunnel, move back to where the final Dormant Elementals are; Korgash's body should be lying next to them.",
            date = "2007-02-18T11:48:09-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10601#comments:id=38116",
        },
        {
            id = 22086,
            score = 29,
            author = "11005",
            text = "Coords are 35, 40 he's near the end of one of the Deathforge tunnels.",
            date = "2007-01-20T13:32:39-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10601#comments:id=22086",
        },
        {
            id = 27892,
            score = 29,
            author = "17446",
            text = "Coords are correct.  He's just a corpse on the ground, by the way.",
            date = "2007-01-30T20:15:27-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10601#comments:id=27892",
        },
        {
            id = 33540,
            score = 25,
            author = "21355",
            text = "There are two tunnel entrances.  The top one is the one you want for this quest.  Yes, spawn time is crazy, but if you watch your surroundings and move through methodically, it isn't that difficult.\n\nTwo things to note:  First, every few minutes there is a pack of three mobs that enters the tunnel behind you and goes halfway down it.  Don't let them jump you.  Second, don't get close to the infernal stones.",
            date = "2007-02-10T10:15:21-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10601#comments:id=33540",
        },
        {
            id = 43835,
            score = 19,
            author = "Sergius",
            text = "follow-up: Bring Down the Warbringer!\nH: http://www.wowhead.com/?quest=10603\nA: http://www.wowhead.com/?quest=10586",
            date = "2007-02-28T07:51:20-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10601#comments:id=43835",
        },
    },
    [10602] = {
        {
            id = 219675,
            score = 37,
            author = "28508",
            text = "For those who dosn't bother to read the whole quest.\n\n1. Get the Elemental Displacer (http://www.wowhead.com/?item=30672) from the Deathforge Smith (http://www.wowhead.com/?npc=19756) or the Deathforge Tinkerer (http://www.wowhead.com/?npc=19754) on the 2nd floor (first entrance to the right).\n2. Go to the 1st floor (second entrance) and use the Elemental Displacer to disrupt the ritual in the summoning chamber.\n3. After you have used the Elemental Displacer (http://www.wowhead.com/?item=30672), it will spawn Infernal Oversoul (http://www.wowhead.com/?npc=21735), kill this one and return to Scout Zagran and complete the quest.\n\nEdit: Corrected the links, thanks Mefirst.",
            date = "2008-01-17T13:00:43-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10602#comments:id=219675",
        },
        {
            id = 48313,
            score = 23,
            author = "Aidama",
            text = "Do this quest simutaneously with \"The Fate of Kagrosh\" [http://www.wowhead.com/?quest=10601].\n\nWhen walking back from the end of the tunnel where Kagrosh's body is, you will see two orcs guarding the entrance to all the Tinkerers. Kill the left one (back facing tinkerers), and there is a ledge to the side where you can walk onto. Walk to the very end and you will see the summoner. As a 68 Shadow Priest I just mind blasted him until he died without aggroing the other summoners behind him. Jumped into the pool and completed quest with very little aggro.",
            date = "2007-03-08T16:09:17-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10602#comments:id=48313",
        },
        {
            id = 22076,
            score = 13,
            author = "ubermonkey",
            text = "37.8, 38.8",
            date = "2007-01-20T13:16:42-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10602#comments:id=22076",
        },
        {
            id = 43837,
            score = 8,
            author = "Sergius",
            text = "follow-up: Bring Down the Warbringer!\nH: http://www.wowhead.com/?quest=10603\nA: http://www.wowhead.com/?quest=10586",
            date = "2007-02-28T07:52:06-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10602#comments:id=43837",
        },
        {
            id = 26121,
            score = 6,
            author = "15213",
            text = "Underneath you'll see a fire elemental. Use the displacer and it summons a bigger fire elemental. Easily solo-able.",
            date = "2007-01-28T02:00:59-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10602#comments:id=26121",
        },
    },
    [10603] = {
        {
            id = 26713,
            score = 103,
            author = "13233",
            text = "When you were searching for Kagrosh's body/backpack a corner before his body there was a locked \"gate\". You go through there and into the small tunnel and you shall find the Warbringer. Soloable.",
            date = "2007-01-28T22:23:28-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10603#comments:id=26713",
        },
        {
            id = 27747,
            score = 58,
            author = "12320",
            text = "to clarify:\nafter you cross the large bridge you enter what looks like a lab room filled with deathforge smiths and tinkerers. There is a heavy iron portcullis on the left side of this room. That is what you are looking for, head through and at the end of the tunnel is the boss. Easy solo",
            date = "2007-01-30T15:15:19-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10603#comments:id=27747",
        },
        {
            id = 1650674,
            score = 52,
            author = "718302",
            text = "The complete quest chain:\n\nhttps://www.wowhead.com/quest=11048 (breadcrumb, optional)\n\nThe breadcrumb leads you to https://www.wowhead.com/npc=21359, who gives the first set of quests in Shadowmoon Village:\nhttps://www.wowhead.com/quest=10595\nhttps://www.wowhead.com/quest=10596\nhttps://www.wowhead.com/quest=10597\nhttps://www.wowhead.com/quest=10598\nhttps://www.wowhead.com/quest=10599\n\nAt this point, you are sent to https://www.wowhead.com/npc=21475, for the second set of quests at Slag Watch:\nhttps://www.wowhead.com/quest=10600\nhttps://www.wowhead.com/quest=10601 and https://www.wowhead.com/quest=10602 (can be obtained and completed simultaneously)\nhttps://www.wowhead.com/quest=10603\n\nYou are now sent back to https://www.wowhead.com/npc=21359 in Shadowmoon Village for the final portion of the chain:\nhttps://www.wowhead.com/quest=10604\nhttps://www.wowhead.com/quest=10767\nhttps://www.wowhead.com/quest=10611\nhttps://www.wowhead.com/quest=10613\nhttps://www.wowhead.com/quest=10745\n\nNote that other than https://www.wowhead.com/quest=11048, no quests are optional; all must be completed in the order specified to advance.",
            date = "2012-04-08T13:02:56-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10603#comments:id=1650674",
        },
        {
            id = 29548,
            score = 24,
            author = "edessa",
            text = "Cave: 40,38\nGo through the locked gate on the left after the bridge (key provided)\nRazuun + Orders = 38,46",
            date = "2007-02-02T16:09:02-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10603#comments:id=29548",
        },
        {
            id = 2309519,
            score = 11,
            author = "cephadex",
            text = "If you've had a hard time finding him or you're bad with caves in general, here (http://www.tegmentum.net/warbringer.html) are some screenshots to show you where to go. I hope this helps.",
            date = "2016-02-23T08:38:20-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10603#comments:id=2309519",
        },
    },
    [10604] = {
