    [10606] = {
        {
            id = 32395,
            score = 16,
            author = "15366",
            text = "Coords 39, 19 bottom of ramp for key use key in box next to doctor.",
            date = "2007-02-07T19:00:54-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10606#comments:id=32395",
        },
        {
            id = 49273,
            score = 16,
            author = "15689",
            text = "Kill Doctor Gutrick (39, 19)  to get The Doctor's Key.\nOpen the box next to Gutrick to loot the manual.",
            date = "2007-03-10T18:23:27-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10606#comments:id=49273",
        },
        {
            id = 60093,
            score = 15,
            author = "3036",
            text = "The quest name is a reference to Robert M. Pirsig's book called 'Zen and the Art of Motorcycle Maintenance'. It is a fictionalized road trip in which Pirsig explores \"Quality\" and other philosophical topics.\n\nhttp://en.wikipedia.org/wiki/Zen_and_the_art_of_motorcycle_maintenance",
            date = "2007-03-31T10:55:07-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10606#comments:id=60093",
        },
        {
            id = 1660484,
            score = 6,
            author = "894609",
            text = "If you're Horde, you'll want to kill https://www.wowhead.com/npc=21779 at 29, 20 in SMV. The box next to him contains the manual. The other doctor (https://www.wowhead.com/npc=21778) listed in the comments by smanjo and marine325 are for Alliance.",
            date = "2012-04-29T16:28:26-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10606#comments:id=1660484",
        },
        {
            id = 859318,
            score = 5,
            author = "464923",
            text = "You want to kill  Doctor Gutrick if your alliance. He is  southeast of the quest giver near the edge. He dropped the key right away for me",
            date = "2009-10-04T19:15:52-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10606#comments:id=859318",
        },
    },
    [10607] = {
        {
            id = 22357,
            score = 225,
            author = "13088",
            text = "First Prophecy: (39, 17) - On top of one of the tree towers.\nSecond Propecy: (42, 22) - On top of one of the tree towers.\nThird Prophecy: (41,19) - On the ground by the swamp.\nFourth Prophecy: (40, 23) - Back of the camp on the ground.",
            date = "2007-01-21T00:32:25-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10607#comments:id=22357",
        },
        {
            id = 25791,
            score = 76,
            author = "Thunderfury",
            text = "This quest can be done with ONLY one kill. You don't have to dismount to get the prophecy's as you'll get them automaticly by standing at the totem.\n-----\nStep 1: Find out where the totems are located nad make yourself known by how to reach them.\n-----\nStep 2: Kill a Grishna Falconwing\n-----\nStep 3: Ride through the camp and visit ALL the totems. I recommend doing them in this cycle:\n-\nFourth(On the left side of the hut),\n-\nThird (By the swamp),\n-\nFirst (In the northern towers, last tower)\n-\nSecond (Last tower on the lower floor at the southern towers).\n\nI hope this help some of you! =)",
            date = "2007-01-27T15:05:11-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10607#comments:id=25791",
        },
        {
            id = 352642,
            score = 39,
            author = "blupache",
            text = "For anyone who's curious but was in too much of a rush to read them during the quest...\n\nFirst Prophecy: \"From the darkest night shall rise again the raven, shall take flight in the shadows, shall reveal the nature of its kind. Prepare yourself for its coming, for the faithful shall be elevated to take flight with the raven, the rest be forgotten to walk upon the ground, clipped wings and shame.\"\n\nSecond Prophecy: \"Steel your minds and guard your thoughts. The dark wings will cloud and consume the minds of the weak, a flock of thralls whose feet may never leave the ground.\"\n\nThird Prophecy: \"The old blood will flow once again with the coming of the raven, the return of the darkness in the skies. Scarlet night, and the rise of the old.\"\n\nFourth Prophecy: \"The raven was struck down once for flying too high, unready. The aeons have prepared the Dark Watcher for its ascent, to draw the dark cloak across the horizon.\"",
            date = "2008-08-14T10:52:01-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10607#comments:id=352642",
        },
        {
            id = 31056,
            score = 33,
            author = "20522",
            text = "A trick that worked for me to get the buff, was to be within melee range of the Falconwing's when they die. I am a hunter and it took me quite some time to figure that out.",
            date = "2007-02-05T05:05:18-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10607#comments:id=31056",
        },
        {
            id = 22714,
            score = 22,
            author = "13603",
            text = "2. prop is not on the top, its on 2. floor",
            date = "2007-01-22T05:56:04-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10607#comments:id=22714",
        },
    },
