    [10609] = {
        {
            id = 26268,
            score = 88,
            author = "3007",
            text = "Here's a useful tip if you're stuck on one type of dragon - keep your enemy alive, and keep using the Phase Modulator until it finally turns into the type of dragon you need.",
            date = "2007-01-28T08:54:08-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10609#comments:id=26268",
        },
        {
            id = 24450,
            score = 36,
            author = "tehdark",
            text = "63.76 (around here.. (south of death's door))\n\n1.) click on the nether drake egg\n2.) use the Temporal Phase Modulator\n\nu get either\nProto-Nether Drake\n   -or-\nAdolescent Nether Drake\n\nto get one of these u need to use the modulator twice.\nMature Nether Drake  (arcane blast is really deadly, so watch out!)",
            date = "2007-01-25T13:55:20-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10609#comments:id=24450",
        },
        {
            id = 37201,
            score = 31,
            author = "11547",
            text = "here's another trick i found helpful.\n\nwhen you click on the egg, a nether whelp will spawn -- knock the whelp down to 1/2 or less health before using the modulator on him, makes the final dragon much easier to kill (they inherit the amount of health).  This works well until you need to get a specific type, then sometimes the cooldown on the modulator doesn't have time to run out.  I ended up standing there letting the dragon hit me until i could hit the modulator again.",
            date = "2007-02-16T19:20:12-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10609#comments:id=37201",
        },
        {
            id = 66234,
            score = 18,
            author = "gendry",
            text = "As of April 12, 2007, players attempting this quest DO NOT lose Netherwing rep if they have completed the Shadowmoon Valley quest line that ultimately results in reaching neutral reputation level with the Netherwing.\n\nI was hesitant to try this quest out of fear I would lose rep with no way to get it back.  Happily, I suffered no rep loss.",
            date = "2007-04-12T19:05:51-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10609#comments:id=66234",
        },
        {
            id = 25092,
            score = 15,
            author = "Boshi",
            text = "Just one click for all three types.",
            date = "2007-01-26T13:16:00-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10609#comments:id=25092",
        },
    },
    [10611] = {
        {
            id = 28899,
            score = 31,
            author = "14677",
            text = "I doubt the quest is bugged.\n\nThe one located at 28.20 is for the hordes (Just outside our start place)\nThe one located at 39,19 is for the alliance\n\nAs a horde, trying to pick up the one at the alliance area it just wouldn´t drop. Being a level 70 i started to realize that it would be hell to go there without a flying mount so I decided to go back to my own area and just as i presumed it dropped the first kill.",
            date = "2007-02-01T11:53:12-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10611#comments:id=28899",
        },
        {
            id = 278386,
            score = 18,
            author = "138722",
            text = "He is at the bottom of the hill where the quest giver stands. Hopefully this helps some people out. I passed this guy up and flew all the way to the ally side on accident.",
            date = "2008-04-27T16:13:06-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10611#comments:id=278386",
        },
        {
            id = 108573,
