        {
            id = 42082,
            score = 24,
            author = "27300",
            text = "takes a while to kill them, but do it with the other quest \"The Softest Wings\"",
            date = "2007-02-25T11:48:56-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10617#comments:id=42082",
        },
        {
            id = 155755,
            score = 9,
            author = "8035",
            text = "My best lucked seemed to be with letting the Larva metamorph and split open.  Not only did the drop rate for the cocoons seem higher for me then, but the Silkwings that emerge in this event drop the Iridescent Wings for http://www.wowhead.com/?quest=10618, allowing you to complete both quests with more efficiency .",
            date = "2007-09-20T15:48:29-05:00",
