    [10618] = {
        {
            id = 2546917,
            score = 27,
            author = "1580695",
            text = "As of patch 7.3.5 Mature Silkwings no longer drop Iridescent Wings. This quest is now a 50 minute grind. God speed.\n\nEDIT: This issue has been resolved with the February 20th batch of hotfixes.",
            date = "2018-01-19T04:34:56-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10618#comments:id=2546917",
        },
        {
            id = 25804,
            score = 14,
            author = "14748",
            text = "Around 75, 69.",
            date = "2007-01-27T15:23:42-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10618#comments:id=25804",
        },
        {
            id = 35006,
            score = 8,
            author = "5889",
            text = "Couple things about this quest - stacks of 20 Hardened Carapace are 2.37g and its roughly the same for a stack of the Barbed Legs.\n\nNow, the larvae will metamorph always at 25% health, but not every larvae will morph. And the droprate off the Silkwings is not 100%. Be prepared for what could be a very long (albeit easy) grind.",
            date = "2007-02-13T01:29:04-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10618#comments:id=35006",
        },
        {
            id = 196128,
            score = 4,
            author = "104667",
            text = "Be sure to do this quest in conjunction with http://www.wowhead.com/?quest=10617 you'll beat yourself silly if you dont.",
            date = "2007-12-04T21:07:35-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10618#comments:id=196128",
        },
        {
            id = 510071,
