    [10619] = {
        {
            id = 28474,
            score = 11,
            author = "15864",
            text = "The coordinates here are wrong.  Proper Coordinates are 59.37 or so.",
            date = "2007-01-31T18:13:31-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10619#comments:id=28474",
        },
        {
            id = 3179771,
            score = 5,
            author = "goldenpaww",
            text = "As this is a quest that rewards rep with Aldor, you will not see the quest until you've made your choice between the Aldor and Scryers. I started a DK, and skipped Shattrath as I've done it enough, but wanted my Loremaster for a couple of the others like Shadowmoon. Lo and behold, I couldn't find the flightpoint here, nor any quests until I went back and did the A'Dal (https://www.wowhead.com/quest=10210/adal) /City of Light (https://www.wowhead.com/quest=10211/city-of-light)/ Allegiance chain.",
            date = "2020-01-04T00:46:06-06:00",
