    [10620] = {
        {
            id = 25220,
            score = 26,
            author = "Detonite",
            text = "Stealthed spiders hiding around Razor Ridge. Start @ 67,73 and work your way north.\n\n:D\n\nDetonite",
            date = "2007-01-26T16:43:02-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10620#comments:id=25220",
        },
        {
            id = 27257,
            score = 21,
            author = "Unrequit3d",
            text = "The spiders mainly hide along the edges of the little hills and such. You won't find too many in the open, just ride along the sides on your mount and they will aggro you.",
            date = "2007-01-29T16:23:19-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10620#comments:id=27257",
        },
        {
            id = 147567,
            score = 6,
            author = "19050",
            text = "Leads to More than a Pound of Flesh (http://www.wowhead.com/?quest=10671)",
            date = "2007-09-01T09:08:24-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10620#comments:id=147567",
        },
        {
            id = 1670369,
            score = 6,
            author = "574361",
            text = "Be careful if you are going back for this at high level, they have very small aggro area if you are 85 and they blend in with the ground well. Some are hidden under the edge of the rocks. As a hunter with track hidden, you can fly past them without detecting if you have any lag.",
            date = "2012-05-25T20:07:22-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10620#comments:id=1670369",
        },
        {
