            date = "2020-01-08T12:40:40-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10623#comments:id=3180529",
        },
    },
    [10624] = {
        {
            id = 38579,
            score = 55,
            author = "16691",
            text = "This is the start of the Teron Gorefiend quest chain, for the Horde.\n\nThis chain begins differently depending on whether you're Alliance (A) or Horde (H):\n\nAlliance - starts in Wildhammer Stronghold from Zorus the Judicator (http://www.wowhead.com/?npc=21774):\n1. (A) [69] A Ghost in the Machine (http://www.wowhead.com/?quest=10642)\n2. (A) [69] Harbingers of Shadowmoon (http://www.wowhead.com/?quest=10643)\n3. (A) [70] Teron Gorefiend - Lore and Legend (http://www.wowhead.com/?quest=10644)\n\nHorde - starts in Shadowmoon Village from Chief Apothecary Hildagard (http://www.wowhead.com/?npc=21772):\n1. (H) [69] A Haunted History (http://www.wowhead.com/?quest=10624)\n2. (H) [69] Spectrecles (http://www.wowhead.com/?quest=10625)\n3. (H) [70] Teron Gorefiend - Lore and Legend (http://www.wowhead.com/?quest=10633)\n\nAt this point the chain splits into three parts which can be done in any order (and by both factions):\n4a. [70] Divination: Gorefiend's Cloak (http://www.wowhead.com/?quest=10635)\n4b. [70] Divination: Gorefiend's Truncheon [2 players] (http://www.wowhead.com/?quest=10636)\n4c. [70] Divination: Gorefiend's Armor [5 players] (http://www.wowhead.com/?quest=10634)\n\nAfter collected Gorefiend's stuff and returned it to the spirit (http://www.wowhead.com/?npc=21797), you will get:\n5. (A) [70] Teron Gorefiend, I am... (http://www.wowhead.com/?quest=10645)\n5. (H) [70] Teron Gorefiend, I am... (http://www.wowhead.com/?quest=10639)\n\nFor this final quest, Gorefiend becomes your \"pet\" and you control him using a pet bar.  Having used him to kill Karsius, you return to Zorus or Hildagard to claim your reward.  Choose from:\nEvoker's Helmet of Second Sight (http://www.wowhead.com/?item=31104) (cloth DPS headpiece)\nStealther's Helmet of Second Sight (http://www.wowhead.com/?item=31109) (leather melee headpiece)\nDruidic Helmet of Second Sight (http://www.wowhead.com/?item=31110) (leather magical headpiece)\nStalker's Helmet of Second Sight (http://www.wowhead.com/?item=31106) (mail +AP headpiece)\nShamanistic Helmet of Second Sight (http://www.wowhead.com/?item=31107) (mail +dmg headpiece)\nOverlord's Helmet of Second Sight (http://www.wowhead.com/?item=31105) (plate DPS headpiece)\n\nEdit: converted to new tag format (http://www.wowhead.com/?help=comment-formatting) to fix URL overload problem.",
            date = "2007-02-19T07:49:51-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10624#comments:id=38579",
        },
        {
            id = 24673,
            score = 21,
            author = "13573",
            text = "This stuff is pretty much everywhere near the base, mostly near the green lava",
            date = "2007-01-25T21:10:04-06:00",
