    [10629] = {
        {
            id = 21687,
            score = 166,
            author = "Flyv",
            text = "Took me about 10 tries to find the right pile of poo. What a crappy quest!",
            date = "2007-01-19T17:24:10-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10629#comments:id=21687",
        },
        {
            id = 13740,
            score = 74,
            author = "7629",
            text = "This is one of the funniest quests so far progressing into Outlands. You are required to summon a fel hound (provided) and kill a boar. Then the fel hound eats it and poopies on the ground and you click on it to find the key. Got mine on the first try.\n\nLater you get a debuffed \"Stinky; You smell funny.\" which gives you a green smoke cloud around you.",
            date = "2006-12-12T00:03:30-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10629#comments:id=13740",
        },
        {
            id = 21430,
            score = 60,
            author = "Landon",
            text = "Tip:  The Hound will eat pigs killed by other players if you walk him over to the corpses.  Save some time.",
            date = "2007-01-18T16:57:29-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10629#comments:id=21430",
        },
        {
            id = 248088,
            score = 50,
            author = "74015",
            text = "How to get the key in one try (99% sure)\nIt looks like the quest is even funnier than one would think, because you get faulty information from Foreman Razelcraz (http://www.wowhead.com/?npc=16915). The thing is that the Fel Guard Hound (http://www.wowhead.com/?npc=21847) you get, is not the hound that has the key - though it will drop because I guess Blizzard had to add a drop-rate.\n\nHere's my trick, that has worked three times now.\n\nGet the quest, and summon your Fel Guard Hound (http://www.wowhead.com/?npc=21847) with the whistle you get.\nKite a Deranged Helboar back to where Foreman Razelcraz (http://www.wowhead.com/?npc=16915) is standing, and kill the Helboar next to the Fel Guard Hound (http://www.wowhead.com/?npc=21847) standing within the fence, to the north.\nThe hound will eat the dead boar and poo.\nThe key is in the poo.\n\nThis has now worked three out of three trys for me. Good luck.",
            date = "2008-03-04T18:35:44-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10629#comments:id=248088",
        },
        {
            id = 728169,
            score = 21,
            author = "335007",
            text = "they need to add some hand sanitizer as a quest reward!",
            date = "2009-05-26T12:15:08-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10629#comments:id=728169",
        },
    },
    [10630] = {
        {
            id = 20815,
            score = 34,
            author = "Arx4",
            text = "He is in the cave right next to him( the quest Giver), just note that mobs around him has a fast(not extreme fast) respawn.",
            date = "2007-01-16T12:32:36-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10630#comments:id=20815",
        },
        {
            id = 439455,
            score = 18,
            author = "164644",
            text = "available to Alliance too",
            date = "2008-11-12T00:58:26-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10630#comments:id=439455",
        },
        {
            id = 1378007,
            score = 17,
            author = "702755",
            text = "For those disappointed by the \"choose one\" problem, a list of items that look the same:\nUnderworld Helm (http://www.wowhead.com/item=30856):\nExpert Goldminer's Helmet (http://www.wowhead.com/item=9375#), dropped by Digmaster Shovelphlange (http://www.wowhead.com/npc=7057) in Uldaman (outside the instance) looks the same, and is usable by any leather-, mail-, or plate-wearing class. For clothies, Miner's Hat of the Deep (http://www.wowhead.com/item=9429#.) is similar, but gray instead of yellow, and is dropped by troggs outside the Uldaman instance (in the same location as the Digmaster). There are also several Engin (http://www.wowhead.com/item=23839)eering (http://www.wowhead.com/item=23838)-specific (http://www.wowhead.com/item=10543) options (http://www.wowhead.com/item=10542) that look the same or similar. Complete listing here (http://www.wowhead.com/item=30856#same-model-as).\n\nShatterstone Pick (http://www.wowhead.com/item=30855):\nPerhaps unsurprisingly, this looks identical to most other mining pick items in the game. Complete listing here (http://www.wowhead.com/item=30855#same-model-as).\nIf you're going for the easiest one to get, and the one usable by any class, you want Mining Pick (http://www.wowhead.com/item=2901), available wherever trade goods or mining goods are sold.\nIt should be noted that Cold Iron Pick (http://www.wowhead.com/item=1959), Miner's Revenge (http://www.wowhead.com/item=1893), Tunnel Pick (http://www.wowhead.com/item=756), and Rock Chipper (http://www.wowhead.com/item=6206) are all two-handed weapons and cannot be equipped at the same time as the Deep Core Lantern.\nThe most \"prestigious\" and/or hardest to obtain of the look-alike items is probably the Digmaster 5000 (http://www.wowhead.com/item=9465#), an extraordinarily rare zone drop in Uldaman.\nMarcus' Pickaxe (http://www.wowhead.com/item=54991) is available only to worgen and is a reward from the worgen starting zone.\nRyedol's Lucky Pick (http://www.wowhead.com/item=4616#comments) is a zone drop in the Badlands. It is the only \"Unique\" pick (Shovelphlange's Mining Axe (http://www.wowhead.com/item=9378) is Unique-Equipped).\nBrann's Trusty Pick (http://www.wowhead.com/item=20723) is a reward from a quest in Silithus that begins with Brann Bronzebeard's Lost Letter (http://www.wowhead.com/item=20461).\n\nDeep Core Lantern (http://www.wowhead.com/item=30857#same-model-as):\nThere is only one look-alike item in the game for the Deep Core Lantern. It is the Everglow Lantern (http://www.wowhead.com/item=5323#comments), which was formerly a quest reward from Supplies to Auberdine (http://www.wowhead.com/quest=976/supplies-to-auberdine) (Alliance) or Weapons of Choice (http://www.wowhead.com/quest=893/weapons-of-choice) (Horde). Neither quest is presently available in-game, and so the Everglow Lantern is no longer obtainable. Thus, it is most advisable to select the Deep Core Lantern (http://www.wowhead.com/item=30857#same-model-as) as your quest reward if you hope to obtain this set look in its entirety.\n\nTL;DR:\nBoth the Underworld Helm and the Shatterstone Pick have look-alike items that can be obtained in order to match the look of the full set. The Deep Core Lantern does not. Therefore, to obtain the entire \"set\" look of this quest's rewards, you should choose the Deep Core Lantern.",
            date = "2011-03-28T01:52:59-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10630#comments:id=1378007",
        },
        {
            id = 45289,
            score = 15,
            author = "29676",
            text = "Another easy quest. The cave is to the left of quest giver.\n\nIt's a small cave and the boss is at the very end of it.",
            date = "2007-03-02T18:44:35-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10630#comments:id=45289",
        },
