    [10634] = {
        {
            id = 25154,
            score = 576,
            author = "ruck",
            text = "Be sure to equip your \"Spectrecles\" before trying to find Vhel'kur (http://www.wowhead.com/?npc=21801)",
            date = "2007-01-26T14:57:21-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10634#comments:id=25154",
        },
        {
            id = 26112,
            score = 118,
            author = "17025",
            text = "If youre having trouble finding him make sure you're wearing your \"Spectrecles\" and make sure you're looking up.  He doesnt patrol along the ground, he flies high over the island as the quest says.\n\nWe had a hunter stand on one of the higher hills on the island and pull him down to the ground.  tank and spank kinda fight.",
            date = "2007-01-28T01:32:05-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10634#comments:id=26112",
        },
        {
            id = 31446,
            score = 81,
            author = "Amethyst",
            text = "There is a mountain peak at 69.8, 85.9 that your group can stand on and pull him when he flies towards you.\n\nHe doesn't cleave, or knockback or anything special at all, just melee dmg.\n\nAs a 70 warrior with 12k armour, he was hitting me for about 1,000 dmg a time.",
            date = "2007-02-05T22:09:34-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10634#comments:id=31446",
        },
        {
            id = 301962,
            score = 61,
            author = "66111",
            text = "Theres been a bug, that allows your healer to drink when ever they feel like.\n\nBasically keep your goggles off, and heal like normal. When your low on mana, just sit and drink (You may have to wait 5-10 seconds between agro drops), but your be able to drink, and when hes down to maybe 10-15% HP left, just throw them on and bingo, easy lazy healing fight, and you still win.\n\nEDIT- Why the heck was this rated down? I didn't see it at all above.",
            date = "2008-06-09T02:40:42-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10634#comments:id=301962",
        },
        {
            id = 5374741,
            score = 48,
            author = "mill5034",
            text = "Hopefully this will save someone else a headache. First of all, you need spectacles to see the mob. I didn't have any and looked for a replacement. At first, I couldn't figure out why I Zorus wasn't giving me the option for a new pair of spectacles. It was because my original pair was in my bank! I had to fly to my bank and get them out. So if he doesn't give you the option, check your bank!",
            date = "2022-05-17T17:13:36-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10634#comments:id=5374741",
        },
    },
    [10635] = {
        {
            id = 10763,
            score = 167,
            author = "252",
            text = "The Clerics of Karabor are located just south of the entrance to the Black Temple and you have to wear the Spectrecles to see them.\n\nThe Cloak seems to be a fairly rare drop, I farmed the clerics for about 40 min before I got mine to drop.",
            date = "2006-12-08T09:23:21-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10635#comments:id=10763",
        },
        {
            id = 26562,
            score = 79,
            author = "8620",
            text = "64, 48 is the general area.",
            date = "2007-01-28T18:03:31-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10635#comments:id=26562",
        },
        {
            id = 46299,
            score = 36,
            author = "17987",
            text = "Before you can do the \"Divination: Gorefiend's Cloak/Truncheon/Armor\" quests, you need to do the prerequisite chains.  After you do the appropriate prereq chain (they're pretty quick), then you can do the three Divination quests in any order you want.\n\nAlliance:\nhttp://www.wowhead.com/?quest=10642\n\nHorde:\nhttp://www.wowhead.com/?quest=10624",
            date = "2007-03-05T02:01:03-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10635#comments:id=46299",
        },
        {
            id = 42470,
            score = 31,
            author = "27631",
            text = "Thanks to everyone here, I got the cloak in my first kill at 64, 52. Remember to wear the Spectrecles.",
            date = "2007-02-26T02:49:37-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10635#comments:id=42470",
        },
        {
            id = 344003,
            score = 18,
            author = "181676",
            text = "ok i started these quests a while ago. usually i get bored and then come back way later. well i forgot what the goggles were for and i deleted them. if you come to the same problem i did you can pick up a new pair from Chief Apothecary Hildagard next to the inn in shadowmoon village.",
            date = "2008-08-04T02:24:00-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10635#comments:id=344003",
        },
    },
    [10636] = {
        {
            id = 28659,
            score = 644,
            author = "10411",
            text = "Remember to wear the specticles.",
            date = "2007-02-01T00:19:19-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10636#comments:id=28659",
        },
        {
            id = 26574,
            score = 194,
            author = "8620",
            text = "The best way to do this quest is to go clockwise along the major road. As a 68 Shaman I soloed it by popping my fire elemental and taking one down. First mob dropped it. They move counter-clockwise and come as a group of four (possibly five, was a bit rushed). If you can CC a few you're fine. Melle classes should group up for it.",
            date = "2007-01-28T18:30:14-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10636#comments:id=26574",
