    [10643] = {
        {
            id = 23378,
            score = 60,
            author = "14319",
            text = "Wear the goggles the quest giver provides and you can see quest mobs all around him.",
            date = "2007-01-23T16:24:39-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10643#comments:id=23378",
        },
        {
            id = 46518,
            score = 12,
            author = "28384",
            text = "Easy grind is right. The are six of these that spawn inside the Inn alone! Kinda hilarious to grind XP while earning rested XP at the same time.",
            date = "2007-03-05T11:48:19-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10643#comments:id=46518",
        },
        {
            id = 1686386,
            score = 9,
            author = "1013225",
            text = "I did not receive any googles from Zorus and when I tried to abandon the quest and pick it back up to see if he will give me a pair I still don't get a pair. Am I supposed to get the googles from someone else or from another quest?",
            date = "2012-07-09T14:34:48-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10643#comments:id=1686386",
        },
        {
            id = 37914,
            score = 7,
            author = "20647",
            text = "anyone who wanted to grind all the way to 70, here is the easiest possible way to do it. Coin plus Netherweave cloth and the occasional green item. Grinding doesn't get any easier than this!\n\n.",
            date = "2007-02-18T03:50:25-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10643#comments:id=37914",
        },
        {
            id = 5935714,
            score = 7,
            author = "Netrunner",
            text = "If you're here to add the Spectrecles to your transmog collection, don't be like me and think that you need to do 41 quests out of a 116 chain. Just go to Wildhammer Stronghold in Shadowmoon Valley, talk to Zorus the Judicator who patrols along a circular path in the middle of the stronghold, complete [A Ghost in the Machine], pick up the next quest [Harbingers of Shadowmoon], and you're done.\n\nAt least I only did 32 quests before I realized... 😅",
            date = "2024-08-29T02:35:08-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10643#comments:id=5935714",
        },
    },
    [10644] = {
        {
