        {
            id = 60803,
            score = 4,
            author = "14690",
            text = "Unless you take the really long way around it's not possible to kite him down the road to Shattrah. He'll evade and reset once he hits the first bridge.",
            date = "2007-04-02T00:09:34-05:00",
