    [10654] = {
        {
            id = 614057,
            score = 50,
            author = "Tural",
            text = "A quick macro for turning these in is as follows:\n\n/script SelectGossipAvailableQuest(2)\n/script CompleteQuest()\n/script GetQuestReward()\n\nThis assumes you only have two quest listings from the NPC, Single Mark of Sargeras (http://www.wowhead.com/?quest=10655) and More Marks of Sargeras (http://www.wowhead.com/?quest=10654). If you have any other quests available, you may need to adjust the first line with the appropriate number for the quest you're turning in.\n\nTo use the macro, simply right-click the NPC to open the dialog window, press the macro a few times, and repeat. Makes it very fast for turning in a bulk of these at once.",
            date = "2009-02-18T07:20:17-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10654#comments:id=614057",
        },
        {
            id = 28746,
            score = 38,
            author = "11162",
            text = "Here is a list of items which you can hand in and up until which level (for aldor rep):\n\nDreadfang Venom Sac per 8 until Neutral (http://www.wowhead.com/?quest=10019)\n\nMark of Kil'jaeden per 10 until Honored (http://www.wowhead.com/?quest=10326)\n\nMark of Sargeras per 10 until Exalted (http://www.wowhead.com/?quest=10654)\n\nFel Armament per 1 until Exalted (http://www.wowhead.com/?quest=10421) You will also receive dust for which you can buy items.",
            date = "2007-02-01T05:39:11-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10654#comments:id=28746",
        },
        {
            id = 36873,
            score = 30,
            author = "cosa",
            text = "For honored to revered if you only turning marks in\n\n480 marks in total = 12000 rep\n437 marks in total = 12018 rep (human)\n\nRevered to Exalted:\n840 marks in total = 21000 rep\n764 marks in total = 21010 rep (human)",
            date = "2007-02-16T09:11:47-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10654#comments:id=36873",
        },
        {
            id = 151025,
