    [10656] = {
        {
            id = 242398,
            score = 74,
            author = "102644",
            text = "Before you can do this quest or turn in future marks you must first complete the City of Light quest and choose the Scryer side. If you have yet to do that quest it starts at the Haggered War Veteran by accepting the Quest A'dal",
            date = "2008-02-24T04:04:32-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10656#comments:id=242398",
        },
        {
            id = 1962843,
            score = 19,
            author = "Neza1337",
            text = "If you're stuck like i was, with nowhere to turn in the quest. follow this short quest line: [quest=10210 domain=www]",
            date = "2014-05-03T04:56:42-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10656#comments:id=1962843",
        },
        {
            id = 68791,
            score = 18,
            author = "OneFreeMan",
            text = "Honored reputation is not a requirement, but it is highly recommended as Sunfury Signets will continue to give you reputation all the way to Exalted while the Firewing Signet quests disappear once you hit Honored.\n\nIn other words, it makes more sense to use Firewing Signets (which you can farm much faster) to get to Honored, and save all of your Sunfury Signets for the grind from Honored to Exalted.\n\nThe same is true of the extensive quest lines available in Netherstorm and Shadowmoon Valley. These are best saved until after you are past Honored.",
            date = "2007-04-17T17:45:21-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10656#comments:id=68791",
        },
        {
            id = 1981980,
            score = 14,
            author = "Nopeace",
            text = "Macros\n10x https://www.wowhead.com/item=30810\n\n#showtooltip Sunfury Signet\n/script SelectGossipAvailableQuest(1)\n/script CompleteQuest()\n/script GetQuestReward()\n\nSingle https://www.wowhead.com/item=30810\n\n#showtooltip Sunfury Signet\n/script SelectGossipAvailableQuest(2)\n/script CompleteQuest()\n/script GetQuestReward()\n\nRight click on the NPC who you turn the https://www.wowhead.com/item=30810 into and press whatever button you have this bound to. This makes turning in any rep item a breeze. I suggest binding it to the mouse wheel for nearly instant turn ins.",
            date = "2014-07-18T21:29:45-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10656#comments:id=1981980",
        },
        {
            id = 35319,
            score = 12,
            author = "RaZZoR",
            text = "The quest giver is at 45,82 in Shattrath City in Scryer's Tier.\nYou can find the mobs in Shadowmoon Valley around 69,52\nand in Netherstorm around 25,70.\nAs I can see from your posts you can take the quest when you reach to a lvl (it seems that it is 67+ dunno)",
            date = "2007-02-13T15:20:51-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10656#comments:id=35319",
        },
    },
    [10657] = {
        {
            id = 70604,
            score = 59,
            author = "149",
            text = "This quest is clearly a reference to the Metallica song \"Ride the Lightning\". I love these little things Blizzard throws in.",
            date = "2007-04-21T17:35:47-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10657#comments:id=70604",
        },
        {
            id = 25623,
            score = 50,
            author = "Mendo",
            text = "Use the item, and let the Scalewing Serpent's Lightning strike you, very easy quest if your a healer, just put the bubble up and heal yourself.",
            date = "2007-01-27T10:27:15-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10657#comments:id=25623",
        },
        {
            id = 25715,
            score = 30,
            author = "14687",
            text = "Scalewing Serpents are around 67, 73.",
            date = "2007-01-27T12:20:39-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10657#comments:id=25715",
        },
        {
            id = 26091,
            score = 25,
            author = "15586",
            text = "Easy as a mage, get at 30+ range, let him hit you, sheep, get 30+ again, let him hit you resheep, etc. Bandage when needed. If you can get to something where the can't get you, aka where melee mobs would evade, they'll just constanty lightning strike you.\n\nHunters can just ping/pong him, with a pet 30 yds away. Have the pet hit him a few times, distrcting shot while your 30+ yards, let him strike you ones, then FD, and repeat.\n\nDruids just root and heal.",
            date = "2007-01-28T01:02:54-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10657#comments:id=26091",
        },
        {
            id = 239662,
            score = 12,
            author = "101774",
            text = "Just remember that Maggoc patrols around this area and that the shield slows you\n\nSo if you see him deactivate the shield and run, run like the wind XD",
            date = "2008-02-19T17:26:22-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10657#comments:id=239662",
        },
    },
    [10658] = {
        {
            id = 276224,
            score = 30,
            author = "tolbarath",
            text = "The following macro (posted by Troodi of Maelstrom on the US forums) can be spammed to expediate the turn-in process if you've got a lot of Sunfury Signets (this will also work with pretty much any repeatable turn-in quests). You still have to click the quest giver every time, but at least you don't have to keep moving your mouse around the screen back and forth :-p\n\n/script SelectGossipAvailableQuest(1)\n/script CompleteQuest()\n/script GetQuestReward()\n\nJust put that macro in your action bar and press it three times each time you click the quest giver.\n\nThanks to Troodi of Maelstrom for posting it in the first place.",
            date = "2008-04-23T11:17:08-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10658#comments:id=276224",
        },
        {
            id = 151022,
            score = 21,
            author = "TheOnyx",
            text = "This quest turn-in will also give you an amount of rep with The Sha'tar (http://wowhead.com/?faction=935) equal to half of the rep gained for The Scryers. However, you will only be able to reach 1 point from Honored in this manner.",
            date = "2007-09-09T20:53:41-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10658#comments:id=151022",
        },
        {
            id = 5670237,
            score = 10,
            author = "bitti09",
            text = "if the other macros doesn't work\n this one worked for me:\n\n10x  Sunfury Signet\n\n#showtooltip Sunfury Signet\n/run C_GossipInfo.SelectAvailableQuest(10658)\n/run CompleteQuest()\n/script GetQuestReward()",
            date = "2023-08-21T15:39:14-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10658#comments:id=5670237",
        },
        {
            id = 40897,
            score = 8,
            author = "17656",
            text = "This rewards 250 Scryer faction. Turning in only one Signet at a time gives 25 faction.",
            date = "2007-02-23T03:00:40-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10658#comments:id=40897",
        },
        {
            id = 3250197,
            score = 8,
            author = "Tyrick",
            text = "Since 9.0.1 patch, some scripts has changed, so the macros found on this article may not work.\nUse this if you are reading this in BfA or Shadowlands.\n\n/script C_GossipInfo.SelectAvailableQuest(2)\n/click QuestFrameCompleteButton\n/click QuestFrameCompleteQuestButton\n\nJust click on the NPC so you see all the options and spam this button until you turn all those Signets.\nOnly works with the x10 quest, not the single one.",
            date = "2020-11-17T09:28:15-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10658#comments:id=3250197",
        },
    },
    [10659] = {
        {
            id = 40896,
            score = 2,
            author = "17656",
            text = "This rewards 25 Scryer faction. Turning in 10 at once gives 250.",
            date = "2007-02-23T02:59:58-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10659#comments:id=40896",
        },
        {
            id = 3233909,
            score = 2,
            author = "Jackimooz",
            text = "You must complete the quest City of Light (https://www.wowhead.com/quest=10211/city-of-light), which opens up for the quests Allegiance to the Scryers (https://www.wowhead.com/quest=10552/allegiance-to-the-scryers) and Allegiance to the Aldor (https://www.wowhead.com/quest=10551/allegiance-to-the-aldor). Completing either of these quests opens up for the repeatable quests for the faction you chose.",
            date = "2020-09-29T06:41:48-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10659#comments:id=3233909",
        },
        {
            id = 714425,
            score = 1,
            author = "sorcereo",
            text = "Take this info if you do not already know...\nIf you are a Human who is going back to get old factions to exalted, like myself, it is more profitable to turn in 10 of these as compared to 1 of \"More Sunfury Signets\" (http://www.wowhead.com/?quest=10658).  Simply: (30~31)x10 > 275!",
            date = "2009-05-12T22:40:46-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10659#comments:id=714425",
        },
        {
            id = 1918945,
            score = 1,
            author = "363016",
            text = "Interesting note, and I'm not entirely certain if it still even applies, but this quest is easily used for accumulating a large amount of guild experience.\n\nFor small guilds that need to find an easier outlet for leveling than just dailies and alt-leveling, a character within levels 68-82 is able to grant a maximum of 93.6million GXP (Horde) or 100.8million GXP (Alliance), considering that they have not completed any other quests for this faction and only turn in the signets one at a time.\n\nThis translates into requiring about 9 characters (9.03 Horde) (8.37 Alliance) to use this technique to reach level 25 for a brand new guild.\nThis is by far the fastest technique I have personally used to finish leveling a guild.\n\nFor obvious reasons, https://www.wowhead.com/quest=10414 may also be used for this purpose, but is not as easily farmed without the possibility of disrupting questers. (levels 64-82)\n\nThis quest makes it possible for 1 person to level a guild to 25 when utilizing 9 extra character slots for this purpose. (If leveling to 68 is required for all toons, less slots are required due to leveling quest turn-in GXP)",
            date = "2013-11-17T01:28:07-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10659#comments:id=1918945",
        },
        {
            id = 1981977,
            score = 1,
            author = "Nopeace",
            text = "Macros\n10x https://www.wowhead.com/item=30810\n\n#showtooltip Sunfury Signet\n/script SelectGossipAvailableQuest(1)\n/script CompleteQuest()\n/script GetQuestReward()\n\nSingle https://www.wowhead.com/item=30810\n\n#showtooltip Sunfury Signet\n/script SelectGossipAvailableQuest(2)\n/script CompleteQuest()\n/script GetQuestReward()\n\nRight click on the NPC who you turn the https://www.wowhead.com/item=30810 into and press whatever button you have this bound to. This makes turning in any rep item a breeze. I suggest binding it to the mouse wheel for nearly instant turn ins.",
            date = "2014-07-18T21:26:01-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10659#comments:id=1981977",
        },
    },
    [10660] = {
        {
            id = 24674,
            score = 11,
            author = "13573",
            text = "Right outside the base near the lava pools",
            date = "2007-01-25T21:10:51-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10660#comments:id=24674",
        },
        {
            id = 27009,
            score = 5,
            author = "Chudz",
            text = "55,88 is WRONG! location.\n\nCorrect loction can been seen here http://www.wowhead.com/?npc=21408",
            date = "2007-01-29T09:14:52-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10660#comments:id=27009",
        },
        {
            id = 41033,
            score = 5,
            author = "6460",
            text = "The location for killing these mobs doesn't matter in relation to the droprate.  The most important thing is to ensure you are killing the correct mob.   The droprate is not too bad since you only need 8 of them.   I found the droprate to be higher than what was on the site, but that may be due to people killing these things when they are not on the quest - thus 0% drop rate for those kills.  This quest realistically can be finished in 20 kills.",
            date = "2007-02-23T10:22:31-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10660#comments:id=41033",
        },
        {
            id = 32934,
            score = 2,
            author = "21888",
            text = "In 15 minutes I got all that was required. Pulling from the green lake had the best luck to getting the spleens. Also start on the NW side of the green lake. Anywhere else I went, the drop rate was non-existent.",
            date = "2007-02-09T02:24:11-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10660#comments:id=32934",
        },
        {
            id = 276895,
            score = 2,
            author = "66167",
            text = "Sigh. 68 kills for eight of these. Crazy.",
            date = "2008-04-24T15:48:38-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10660#comments:id=276895",
        },
    },
    [10661] = {
        {
            id = 26398,
            score = 10,
            author = "16137",
            text = "Diemetradons are arround 31 39.",
            date = "2007-01-28T13:27:51-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10661#comments:id=26398",
        },
        {
            id = 32033,
            score = 7,
            author = "21278",
            text = "The drop rate is very low as mentioned above. Sometimes you might get lucky. I killed about 30 before I got my first one. There's another quest you can in the same area: \"A Ghost in the Machine.\" which are around the Felfires.",
            date = "2007-02-07T04:01:19-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10661#comments:id=32033",
        },
        {
            id = 117531,
            score = 7,
            author = "53468",
            text = "They drop the spleen after their backs start the green fire. It makes a little bit of sense since they are supposed to be almost fully cooked according to the quest. I took my time killing them until they were on fire and then they dropped the spleen about every other one.",
            date = "2007-07-08T15:33:10-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10661#comments:id=117531",
        },
        {
            id = 174976,
            score = 4,
            author = "LoKHor",
            text = "There is never a correlation between a mob's action and an item dropping. Items have a set drop rate percentage. On another note, does anyone know if these drop off the Greater Felfire Diemetradons? I killed a few but none of the spleens dropped.",
            date = "2007-10-26T02:16:32-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10661#comments:id=174976",
        },
        {
            id = 24659,
            score = 3,
            author = "13105",
            text = "You can find a large camp of felfire diemetradons in between Legion Hold and The Deathforge.  However, these seem to have a really low drop rate.",
            date = "2007-01-25T20:26:48-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10661#comments:id=24659",
        },
    },
    [10662] = {
        {
            id = 40395,
            score = 51,
            author = "marskid2",
            text = "The Illidari-Bane questline is a series of quests that leads to some cool anti-demon weapons.  It involves entering many level-70 instances, so you probably want to do the prerequisites before then.  David Wayne is also rumored to be Mograine of the Ashbringer.\n\nQuest Line\n1 - http://www.wowhead.com/?quest=10621 - Illidari-Bane Shard - Drops from Overseer Ripsaw.\n2 - http://www.wowhead.com/?quest=10626 - Capture the Weapons - Soloable as a warlock with banish.\n3[A] - http://www.wowhead.com/?quest=10662 - The Hermit Smith\n3[H] - http://www.wowhead.com/?quest=10663 - The Hermit Smith\n4 - http://www.wowhead.com/?quest=10664 - Additional Materials\n\nAfter returning Additional Materials, he offers you two quests which can be completed in any order.\n5 - http://www.wowhead.com/?quest=10665 - Fresh From the Mechanar - The Mechanar in Tempest Keep\n6 - http://www.wowhead.com/?quest=10666 - The Lexicon Demonica - Shadow Labyrinth in Auchindoun\n\nAfter returning both of these quests, he offers you the second pair which can be completed in any order.\n7 - http://www.wowhead.com/?quest=10670 - Tear of the Earthmother - Shattered Halls in Hellfire Citadel\n8 - http://www.wowhead.com/?quest=10667 - Underworld Loam - The Steamvault in Coilfang Reservoir\n\nAfter finishing all these, you can get your new weapon!\n9 - http://www.wowhead.com/?quest=10676 - Bane of the Illidari\n10 - http://www.wowhead.com/?quest=10679 - Quenching the Blade\n\nThe rewards are:\nhttp://www.wowhead.com/?item=30788 - Melee 1H Sword\nhttp://www.wowhead.com/?item=30789 - Melee 2H Sword\nhttp://www.wowhead.com/?item=30787 - Caster Dagger\nhttp://www.wowhead.com/?item=31745 - Melee Dagger\n\nCombined with the http://www.wowhead.com/?item=30756 that started the quest chain, you will have a lot of extra attack power or spell damage versus demons.",
            date = "2007-02-22T08:04:58-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10662#comments:id=40395",
        },
        {
            id = 38000,
            score = 19,
            author = "17706",
            text = "Coordinates are 77.6, 38.7\n\nMight be more efficient to bring the mats with you for the next quest in the chain. 4 heavy knothide leather, and adamantite frame, and a demon warding totem",
            date = "2007-02-18T08:29:59-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10662#comments:id=38000",
        },
        {
            id = 1078328,
            score = 9,
            author = "217387",
            text = "This quest DOES count towards \"Shadow of the betrayer\" achievement.",
            date = "2010-07-11T17:00:41-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10662#comments:id=1078328",
        },
        {
            id = 56928,
            score = -9,
            author = "17627",
            text = "hey. This Q is really easy ;)",
            date = "2007-03-25T11:25:19-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10662#comments:id=56928",
        },
    },
    [10663] = {
