    [10664] = {
        {
            id = 40400,
            score = 147,
            author = "marskid2",
            text = "The Illidari-Bane questline is a series of quests that leads to some cool anti-demon weapons.  It involves entering many level-70 instances, so you probably want to do the prerequisites before then.  David Wayne is also rumored to be Mograine of the Ashbringer.\n\nQuest Line\n1 - http://www.wowhead.com/?quest=10621 - Illidari-Bane Shard - Drops from Overseer Ripsaw.\n2 - http://www.wowhead.com/?quest=10626 - Capture the Weapons - Soloable as a warlock with banish.\n3[A] - http://www.wowhead.com/?quest=10662 - The Hermit Smith\n3[H] - http://www.wowhead.com/?quest=10663 - The Hermit Smith\n4 - http://www.wowhead.com/?quest=10664 - Additional Materials\n\nAfter returning Additional Materials, he offers you two quests which can be completed in any order.\n5 - http://www.wowhead.com/?quest=10665 - Fresh From the Mechanar - The Mechanar in Tempest Keep\n6 - http://www.wowhead.com/?quest=10666 - The Lexicon Demonica - Shadow Labyrinth in Auchindoun\n\nAfter returning both of these quests, he offers you the second pair which can be completed in any order.\n7 - http://www.wowhead.com/?quest=10670 - Tear of the Earthmother - Shattered Halls in Hellfire Citadel\n8 - http://www.wowhead.com/?quest=10667 - Underworld Loam - The Steamvault in Coilfang Reservoir\n\nAfter finishing all these, you can get your new weapon!\n9 - http://www.wowhead.com/?quest=10676 - Bane of the Illidari\n10 - http://www.wowhead.com/?quest=10679 - Quenching the Blade\n\nThe rewards are:\nhttp://www.wowhead.com/?item=30788 - Melee 1H Sword\nhttp://www.wowhead.com/?item=30789 - Melee 2H Sword\nhttp://www.wowhead.com/?item=30787 - Caster Dagger\nhttp://www.wowhead.com/?item=31745 - Melee Dagger\n\nCombined with the http://www.wowhead.com/?item=30756 that started the quest chain, you will have a lot of extra attack power or spell damage versus demons.",
            date = "2007-02-22T08:07:10-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10664#comments:id=40400",
        },
        {
            id = 38591,
            score = 94,
            author = "10938",
            text = "You can buy the \"Adamantite Frame\" from two vendors in the Netherstorm (limited supply).\n\nPrice is ~4G, way cheaper than AH.",
            date = "2007-02-19T08:10:31-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10664#comments:id=38591",
        },
        {
            id = 31864,
            score = 49,
            author = "20146",
            text = "The Demon Warding Totem costs 30g from Fantei, so if you're 70 and doing this quest FOR gold.. it's a bit ironic, so you might want to skip it unless you like the rewards (http://www.wowhead.com/?quest=10679)\n\nAlthough the rewards are very situational and in most cases useless, they might be 'vital' for fighting Illidan and other raid boss demons.",
            date = "2007-02-06T19:15:22-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10664#comments:id=31864",
        },
        {
            id = 796598,
            score = 41,
            author = "60430",
            text = "Counts towards the Shadow of the Betrayer achievement. You're looking at the Loremaster of Outlands here baby :)",
            date = "2009-08-03T05:50:51-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10664#comments:id=796598",
        },
        {
            id = 30369,
            score = 30,
            author = "b1mmer",
            text = "Actually the quest enables two more quests (Horde side):\n\nhttp://www.wowhead.com/?quest=10665\nhttp://www.wowhead.com/?quest=10666",
            date = "2007-02-04T03:25:59-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10664#comments:id=30369",
        },
    },
    [10665] = {
        {
            id = 40401,
            score = 102,
            author = "marskid2",
            text = "The Illidari-Bane questline is a series of quests that leads to some cool anti-demon weapons.  It involves entering many level-70 instances, so you probably want to do the prerequisites before then.  David Wayne is also rumored to be Mograine of the Ashbringer.\n\nQuest Line\n1 - http://www.wowhead.com/?quest=10621 - Illidari-Bane Shard - Drops from Overseer Ripsaw.\n2 - http://www.wowhead.com/?quest=10626 - Capture the Weapons - Soloable as a warlock with banish.\n3[A] - http://www.wowhead.com/?quest=10662 - The Hermit Smith\n3[H] - http://www.wowhead.com/?quest=10663 - The Hermit Smith\n4 - http://www.wowhead.com/?quest=10664 - Additional Materials\n\nAfter returning Additional Materials, he offers you two quests which can be completed in any order.\n5 - http://www.wowhead.com/?quest=10665 - Fresh From the Mechanar - The Mechanar in Tempest Keep\n6 - http://www.wowhead.com/?quest=10666 - The Lexicon Demonica - Shadow Labyrinth in Auchindoun\n\nAfter returning both of these quests, he offers you the second pair which can be completed in any order.\n7 - http://www.wowhead.com/?quest=10670 - Tear of the Earthmother - Shattered Halls in Hellfire Citadel\n8 - http://www.wowhead.com/?quest=10667 - Underworld Loam - The Steamvault in Coilfang Reservoir\n\nAfter finishing all these, you can get your new weapon!\n9 - http://www.wowhead.com/?quest=10676 - Bane of the Illidari\n10 - http://www.wowhead.com/?quest=10679 - Quenching the Blade\n\nThe rewards are:\nhttp://www.wowhead.com/?item=30788 - Melee 1H Sword\nhttp://www.wowhead.com/?item=30789 - Melee 2H Sword\nhttp://www.wowhead.com/?item=30787 - Caster Dagger\nhttp://www.wowhead.com/?item=31745 - Melee Dagger\n\nCombined with the http://www.wowhead.com/?item=30756 that started the quest chain, you will have a lot of extra attack power or spell damage versus demons.",
            date = "2007-02-22T08:08:45-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10665#comments:id=40401",
        },
        {
            id = 32619,
            score = 54,
            author = "21687",
            text = "Right before Mechano-Lord Capacitus in a box at the wall.",
            date = "2007-02-08T08:50:16-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10665#comments:id=32619",
        },
        {
            id = 44506,
            score = 48,
            author = "23617",
            text = "Soloed as a level 70 rogue.\n\nWhen you walk in, take the right hallway. You will need to stealth very close to some high level mobs, so, you can:\n(a) have Master of Deception\n(b) use a Sneaking Potion (this is what I did, I'm combat spec)\n(c) sprint like a madman and then vanish.\n\nGet to the ramp that Gatewatcher Iron-Hand patrols on. He walks up to the top of the ramp, walks down and says hi to Capacitus, and then walks back up. If you stand on the edge of the ramp he will not see you.\n\nLooking over the edge of the ramp you can see your prize-- there should be 4 Overcharged Manacells there. Closest to you there is a group of 2 Sunfury Engineers, and 2 Mechanar Tinkerers. Don't even think about fighting any of them, you'd die-- we have something much more roguish planned.\n\nWait until Iron-Hand is at the bottom of the ramp, and then throw/shoot at one of the engineers. They will start to path all the way around the pillar and up the ramp towards you. When they are about to get to you, jump off the ramp landing right next to one of the manacells. Vanish, and grab it. You should have enough time to get it with a couple seconds to spare, before they kindly come back and kill you, porting you out of the instance.\n\nThis would have been easy to get in a group, since you only have to clear to the first boss, but if you're up for an exciting challenge, you can try this method.\n\nEnjoy the rest of this excessively long quest chain. ^_^",
            date = "2007-03-01T10:52:00-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10665#comments:id=44506",
        },
        {
            id = 1086873,
            score = 26,
            author = "632565",
            text = "This quest counts towards the Shadow of the Betrayer achievement if you are trying for Loremaster.",
            date = "2010-07-22T22:31:45-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10665#comments:id=1086873",
        },
        {
            id = 56403,
            score = 8,
            author = "Duodecimal",
            text = "Mages can also solo this very similarly. Timing is extremely tight, so you'll be better off waiting for Invisibility to cool down.\n\n1. Go invisible and run through the corridor on the right, sticking to the left as you head up through the first hall. There will be a barrier on the left. Head to it and let Invisibility wear off there.\n\n2. Gatewatcher Ironhand's patrol path takes approximately 55 seconds. Once the cooldown has finished for Invisibility, wait for him to come up to the top of the ramp, behind the mo'arg and blood elfs. When he turns to head back down, cast Invisibility, wait for the fade, and then head to the ramp.\n\n3. Once you're on the ramp, climb up onto the left side of it and cast Mana Shield to dispel invisibility. There is a guard at the top of the ramp and a group of mobs at the bottom of the ramp, so you will need to space yourself midway between the two ends of the ramp as you stand on the ledge.\n\nYou will see the mana cells down below you, a short drop away.\n\n4. As soon as you can target them, fireblast any of the four mobs (two non-elites, two elites). They will start pathing around the column, aggroing two other groups on the way. Wait until they almost on top of you or about to hit you with ranged attacks, then jump down next to a mana cell.\n\n5. This apparently breaks line of sight. Immediately loot the nearest mana cell and prepare to die. You did disrobe prior to this exercise, correct?\n\nYoutube video (http://youtu.be/OeH-oHz_UhM) I dug up from 7.5 years ago.",
            date = "2007-03-24T14:29:07-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10665#comments:id=56403",
        },
    },
    [10666] = {
        {
            id = 40402,
            score = 67,
            author = "marskid2",
