        },
        {
            id = 29689,
            score = 23,
            author = "19022",
            text = "The Demon has around 5400 health, and does a magic attack which is disruptable. He hits very weak, and can be found as listed above at 15, 41.",
            date = "2007-02-02T21:02:56-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10669#comments:id=29689",
        },
        {
            id = 37138,
            score = 23,
            author = "16947",
            text = "Once you complete this and the other two \"Against\" quests, the next quest in the chain is\nhttp://www.wowhead.com/?quest=10646\n\nIt leads to a quest that requires you to kill the second boss in Shadow Labyrinth.",
            date = "2007-02-16T17:31:46-06:00",
