    [10671] = {
        {
            id = 27766,
            score = 37,
            author = "16588",
            text = "Okay, for this quest you need to kill the \"blobs\" at 67,44. The drop rate is not terrible, but it's not that great either. When these blobs are small with a yellow name tag, they won't attack you unless you make the first move. But when they get beamed by some device, they will turn big and hostile.\n\nThey do NOT have to be big (hostile) in order to drop the quest item.",
            date = "2007-01-30T15:40:20-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10671#comments:id=27766",
        },
        {
            id = 24030,
            score = 26,
            author = "Sizzla",
            text = "Location 67,44",
            date = "2007-01-24T21:16:44-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10671#comments:id=24030",
        },
        {
            id = 51285,
            score = 13,
            author = "3036",
            text = "Hah! I like the Shakespeare reference to The Merchant of Venice. Good job, Blizzard :D",
            date = "2007-03-14T20:26:15-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10671#comments:id=51285",
        },
        {
            id = 27978,
            score = 12,
            author = "18420",
            text = "i noticed that when i waited for them to get small, i had a very high drop rate, about 60-80%. When they were larger and red, i did not get a single one to drop.",
            date = "2007-01-30T23:04:22-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10671#comments:id=27978",
        },
        {
            id = 66793,
            score = 8,
            author = "26548",
            text = "Coordinates: likes others say, around 67, 44 in that camp.\n\nI killed so many and none dropped until I noticed that the drop is called \"ether energized flesh\" - so it makes sense that it has something to do with energy. Basically, go around to where the pink energizers are, and monitor when the fiendlings go to it, you have a guarantee drop if you attack the fiendling *while* it is being energized. It is yellow and then it goes to one of the energizers, pink lightning comes out and then the fiendling becomes enraged. I had no trouble once I figured that out! While you go around monitoring when they are being energized, just kill mobs in the area so they don't zerg you.",
            date = "2007-04-13T18:18:30-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10671#comments:id=66793",
        },
    },
    [10672] = {
        {
            id = 22262,
            score = 92,
            author = "Kotik",
            text = "The Acrano-Scorp are located at 62,40. You gain control of them using the Arcano Control Unit just behind them. You now gain control of the Arcano-Scorp and can tag them using the first ability from your pet bar.",
            date = "2007-01-20T20:26:12-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10672#comments:id=22262",
        },
        {
            id = 30419,
            score = 34,
            author = "Stagen",
            text = "If you're a hunter or a warlock, be aware that using this device will overwrite your current pet.",
            date = "2007-02-04T05:08:03-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10672#comments:id=30419",
        },
        {
            id = 2863985,
            score = 29,
            author = "dearg",
            text = "If the mechnical scorpid is not next to its Arcano Control Unit, you will not be able to interact with the Arcano Control Unit.\n\nWhen I arrived to do this quest, all of the scorpids were away, and I could not use the control units. However, I came back later and a couple of the scorpids had returned - I was then able to do the quest.\n\nI hope this helps someone!",
            date = "2019-01-04T10:17:06-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10672#comments:id=2863985",
        },
        {
            id = 45136,
            score = 25,
            author = "5883",
            text = "The arcanoscorps have other abilities besides tagging the Diemetradons. It's basically a mini-game you can play with 2 other friends, if you were really that bored.\n\na.) Arcano-Cloak, makes your scorp untargettable by other scorps\nb.) Arcano-pince, does a weak melee attack to other scorps\nc.) Arcano-dismantle, does a powerful attack to other scorps as well as stuns them for a short duration.\n\nThey cannot be used against other players or mobs, but I suppose it could be a few minutes of fun if you see someone doing the quest, and feel like murdering their arcanoscorp with yours.",
            date = "2007-03-02T12:56:35-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10672#comments:id=45136",
        },
        {
            id = 36133,
            score = 24,
            author = "20418",
            text = "Coords : 62, 40\n\nExplanation: Get there, click on a \"Arcano Control Unit\" next to the Arcano-Scorps. This will give you control of an Arcano-Scorp. You walk around as the Arcano-Scorp using the \"Tag Greater Felfire Diemetradon\" spell on the pet bar. Obviously on the Greater Felfire Diemetradon's. Once you have tagged 8, you have finished :D.",
            date = "2007-02-14T22:19:23-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10672#comments:id=36133",
        },
    },
    [10673] = {
        {
            id = 235631,
            score = 19,
            author = "127976",
            text = "56, 44 now.  As of last patch he doesn't spawn under the bridge anymore. (Would become evade/stuck)  Now he is on the cliff on the side of the lava flow.",
            date = "2008-02-13T23:55:33-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10673#comments:id=235631",
        },
        {
            id = 50916,
            score = 12,
            author = "33236",
            text = "I get a cut of the technology? Liar! All he does is raise his hands as if he's giving you a buff, but then he does nothing. Then gives you nothing! Damn you shifty blood elves.",
            date = "2007-03-14T06:21:28-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10673#comments:id=50916",
        },
        {
            id = 30993,
