            text = "Has 12,502 hitpoints according to my Mob-Info after the kill, not your average 70, but not elite either.",
            date = "2007-02-05T02:09:21-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10673#comments:id=30993",
        },
        {
            id = 839318,
