    [10674] = {
        {
            id = 22732,
            score = 67,
            author = "Nuke",
            text = "Just use Multi-spectrum Light-trap at the 67,43. Small lights are flying in the air,you need to place light trap under it.",
            date = "2007-01-22T06:50:56-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10674#comments:id=22732",
        },
        {
            id = 1812818,
            score = 35,
            author = "1086754",
            text = "If you go to 65.43 you will not have to move once you get ride of the mob it will take only minutes to get all 15.\nSee screen shot.",
            date = "2013-02-12T16:10:25-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10674#comments:id=1812818",
        },
        {
            id = 67748,
            score = 15,
            author = "43524",
            text = "64,46 works well for this. It's out of the aggro radius of any of the ethereal guys (at least as a lvl 67), and the big pink entrance thingy keeps spawning the balls.\n\nYou can basically get them as fast as the item recharges, without any aggro.",
            date = "2007-04-15T17:07:54-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10674#comments:id=67748",
        },
        {
            id = 664621,
            score = 10,
            author = "345009",
            text = "Who ya gonna call?",
            date = "2009-04-03T11:28:26-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10674#comments:id=664621",
        },
        {
            id = 2585872,
            score = 10,
            author = "TegoZanduba",
            text = "Don't be confused by the giant yellow balls of light that leave the ethereals when you kill them.  These are not the balls of light you are trying to trap.  See the other comments about the tiny pink balls of light.",
            date = "2018-07-29T14:58:39-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10674#comments:id=2585872",
        },
    },
    [10675] = {
        {
            id = 23295,
            score = 125,
            author = "1410",
            text = "After killing a few mobs around 66,43 (I killed 10 or so) Nexus-Prince Razaan spawns and after you kill him the Collection of Souls appears over his body, simply loot that and the quest is done",
            date = "2007-01-23T14:04:44-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10675#comments:id=23295",
        },
        {
            id = 100468,
            score = 87,
            author = "50592",
            text = "Theres actually a tube behind the \"circle\" to gauge how many more you need to kill before  he is summoned. The tube will \"suck\" the souls of the dead energy-men, and what looks like electricity will fill the tube from bottom to the brim, then the prince will be summoned.",
            date = "2007-06-08T00:42:01-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10675#comments:id=100468",
        },
        {
            id = 2194628,
            score = 53,
            author = "1486325",
            text = "Might seem obvious, but it's worth mentioning. Since this is an Alliance only quest, you cannot obtain the toy [Power Core] on a Horde character. However, once you  have it, Horde can use it.",
            date = "2015-06-16T13:43:56-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10675#comments:id=2194628",
        },
        {
            id = 152628,
            score = 36,
            author = "Rituido",
            text = "Just to elaborate a bit more on the summoning process here... The tube near the transporter in the middle of this area needs to fill up with (5-6, can't remember) yellow balls, which appear when you kill any of the Ethereals in the area.You need to kill two Ethereals to get one of the yellow balls to pop up. The large yellow blobs that hover from the corpse of the Ethereal toward the tube have some travel time: so don't get frustrated if the tube isn't filling up at a rate you're happy with.\n\nAlliance and Horde both have a quest to summon the Nexus-Prince, so if run you into a Orc/Night Elf and you're a Human/Forsaken(depending on the situation, many combinations of inter-racial meetings could happen here, let's have fun naming them all!), you might want to consider not killing each other, because both of your kills add toward filling the tube, and in the end you both get to grab your Collection of Souls.",
            date = "2007-09-13T19:35:55-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10675#comments:id=152628",
        },
        {
            id = 2009012,
            score = 29,
            author = "Attackr00t",
            text = "Macro to show if you have completed the quest or not for those looking to get the toy.\n\n/run local id=10675 print((\"The quest with ID %s is %scomplete.\"):format(id, IsQuestFlaggedCompleted(id) and \"\" or \"not \"))",
            date = "2014-10-01T14:22:30-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10675#comments:id=2009012",
        },
    },
    [10676] = {
        {
            id = 40405,
            score = 79,
            author = "marskid2",
            text = "The Illidari-Bane questline is a series of quests that leads to some cool anti-demon weapons.  It involves entering many level-70 instances, so you probably want to do the prerequisites before then.  David Wayne is also rumored to be Mograine of the Ashbringer.\n\nQuest Line\n1 - http://www.wowhead.com/?quest=10621 - Illidari-Bane Shard - Drops from Overseer Ripsaw.\n2 - http://www.wowhead.com/?quest=10626 - Capture the Weapons - Soloable as a warlock with banish.\n3[A] - http://www.wowhead.com/?quest=10662 - The Hermit Smith\n3[H] - http://www.wowhead.com/?quest=10663 - The Hermit Smith\n4 - http://www.wowhead.com/?quest=10664 - Additional Materials\n\nAfter returning Additional Materials, he offers you two quests which can be completed in any order.\n5 - http://www.wowhead.com/?quest=10665 - Fresh From the Mechanar - The Mechanar in Tempest Keep\n6 - http://www.wowhead.com/?quest=10666 - The Lexicon Demonica - Shadow Labyrinth in Auchindoun\n\nAfter returning both of these quests, he offers you the second pair which can be completed in any order.\n7 - http://www.wowhead.com/?quest=10670 - Tear of the Earthmother - Shattered Halls in Hellfire Citadel\n8 - http://www.wowhead.com/?quest=10667 - Underworld Loam - The Steamvault in Coilfang Reservoir\n\nAfter finishing all these, you can get your new weapon!\n9 - http://www.wowhead.com/?quest=10676 - Bane of the Illidari\n10 - http://www.wowhead.com/?quest=10679 - Quenching the Blade\n\nThe rewards are:\nhttp://www.wowhead.com/?item=30788 - Melee 1H Sword\nhttp://www.wowhead.com/?item=30789 - Melee 2H Sword\nhttp://www.wowhead.com/?item=30787 - Caster Dagger\nhttp://www.wowhead.com/?item=31745 - Melee Dagger\n\nCombined with the http://www.wowhead.com/?item=30756 that started the quest chain, you will have a lot of extra attack power or spell damage versus demons.",
            date = "2007-02-22T08:14:26-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10676#comments:id=40405",
        },
        {
            id = 1779099,
            score = 37,
            author = "Cynwise",
            text = "David Wayne says in Demonic:\n\nInto this blade, I imbue the power to strike down the strongest of demons! No demon shall stand before the wielder of this weapon!",
            date = "2012-12-10T14:58:28-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10676#comments:id=1779099",
        },
