        {
            id = 157789,
            score = 5,
            author = "55495",
            text = "the poison reward can be used during an arena and wont be taken off at start or during",
            date = "2007-09-24T18:40:02-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10715#comments:id=157789",
        },
        {
            id = 303222,
            score = 5,
            author = "90701",
            text = "Drop rates are drop rates.  Some people will get 7 from their first 7 kills, some people will not even get a drop in their frist 7 kills.  People always think that if they get 7/7 they've discovered some 'magic' or 'hidden' drop rate.  They haven't.\n\nJust grind the snakes until you get 7.  There are no shortcuts, only the luck of the draw.",
            date = "2008-06-11T11:44:46-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10715#comments:id=303222",
        },
    },
