    [10720] = {
        {
            id = 23656,
            score = 294,
            author = "15053",
            text = "I know it might be dumb but you are not supposed to click the kegs, there is a \"poison kegs\" action in the pet bar you get.\nJust thought I would mention this since I had the pet bar disabled because of my addons, which took me a while to figure out!",
            date = "2007-01-24T11:03:27-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10720#comments:id=23656",
        },
        {
            id = 21526,
            score = 292,
            author = "ubermonkey",
            text = "The marmot cave is at 56.5,29.3. The Kegs you need to poison are in the camp just to the right.",
            date = "2007-01-18T23:23:37-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10720#comments:id=21526",
        },
        {
            id = 29800,
            score = 94,
            author = "15038",
            text = "I spent half an hour looking in the wrong spot for these kegs. To save future fellow questers from this embarrassment...\n\nUse drum at:\nMarmot Cave - 56,29\n\nPoision kegs at:\nGreen Spot Grog Keg - 55,25\nRipe Moonshine Keg - 55,28\nFermented Seed Beer Keg - 55,23\n\nI just went through the camp and KILLED EVERYTHING THAT WOULD GET IN MY WAY FIRST and then quickly morphed into a critter and went after the kegs. No acorns necessary.",
            date = "2007-02-03T01:38:40-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10720#comments:id=29800",
        },
        {
            id = 24116,
            score = 45,
            author = "4814",
            text = "This was a fun quest, Few notes.  Make sure your pet bar is working because you will need it.\n\nWhat you need to do is travel to 56,29 and look to the left near the ground there is a small cave, and use the kodohide drum.  Once you do that your guy turns stealth it seems but still can be seen by mobs and possible ally so put yourself close to the cave as possible.\n\nOnce you are the pet you need to run into the camp which is right beside you if you are facing the cave.  You have to watch out because the mobs can see your pet so you need to run around them carefully.",
            date = "2007-01-25T00:52:00-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10720#comments:id=24116",
        },
        {
            id = 34781,
            score = 36,
            author = "sunshine",
            text = "pet action bar nr. 4 is stealth, nr. 5 is distract, nr. 6 is poison, in case you cant see the pet bar. you can use ctrl+4,5,6",
            date = "2007-02-12T16:23:53-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10720#comments:id=34781",
        },
    },
