    [10722] = {
        {
            id = 24936,
            score = 275,
            author = "15629",
            text = "Step 1. Collect 5 Disguse scrapes from wyrmcult members in the wyrmskull tunnel Entrance 50,36\nStep 2. Right click the 5 scrapes that makes the disguse\nStep 3. Go through the tunnel to Ravenswood and follow the path to the end. Blackwing coven (cave) 31,33 .Just get close enough to the cave to put on the costume.\nStep 4. Run into the cave and keep right. @ 32,37 .Kolphis is in a nook on the right near the end of the cave.\nStep 5. Don't read the text just scroll through it till the quest objective is meet then exit the cave. ( you only have 3 minute round trip ) If you die, it's a long walk from the graveyard.\n\ngl",
            date = "2007-01-26T09:11:39-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10722#comments:id=24936",
