    [10723] = {
        {
            id = 40566,
            score = 58,
            author = "26463",
            text = "This was a funny quest for me. If you're horde and you summon Misha when there's alliance nearby the altar, Misha will go and attack them.\n\nPoor poor Gnome, Misha was hungry :(",
            date = "2007-02-22T13:56:05-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10723#comments:id=40566",
        },
        {
            id = 22510,
            score = 51,
            author = "13796",
            text = "Altar is at 31,22. 100% drop rate on the totems\n\nJust spam click totems after clicking on the altar",
            date = "2007-01-21T18:28:37-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10723#comments:id=22510",
        },
        {
            id = 103939,
            score = 36,
            author = "23824",
            text = "All you have to do is:\n(1) Kill three of the orges to get the totems.\n(2) go to the altar (30.22).\n(3) Right click on it and then a Friendly elite Bear will be standing on top of it and then behind you Gorgrom (70 elite) will spawn. (dont worrie he wont hurt you) then the bear blows up and Gorgrom will die, then with hast lay the totems on his corpse.\n\nHelps to think that your not equipt with the totem.",
            date = "2007-06-13T22:07:04-05:00",
