    [10724] = {
        {
            id = 51629,
            score = 78,
            author = "30341",
            text = "** IMPORTANT **\n\nYou do not need 1 key per person. If everybody is near the cage, you all get credit for the release.\n\nTested on Lethon 3/15/07",
            date = "2007-03-15T13:07:27-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10724#comments:id=51629",
        },
        {
            id = 39833,
            score = 48,
            author = "briyan",
            text = "You need to kill the elite ogres in the north east part of the valley (by Gruul's Lair) until you get the key to drop, then use the key on the hanging cage inside the camp, then use the whistle to summon Spirit. It's not entirely clear, but once you have the key, you right click the cage first, then after the door opens right click the whistle in your inventory to complete the quest.\n\nCage Location: 65.7, 20.1 (walk up the long spike to get to it)\n\nI did this quest solo as a 70 hunter today (Feb 21, 2007) and the key dropped on my third elite ogre. In response to all the droprate concerns above, I am not sure if the droprate was changed, or if it just looks low on the stats because it only drops if you have the quest.\n\nThe elite ogres have approximately 25,000 health and hit for around 400-600 damage. They do a Thunderclap in melee range, and go berserk (with slow movement speed) when at low health so they can be kited with relative ease.",
            date = "2007-02-21T10:02:30-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10724#comments:id=39833",
        },
        {
            id = 22678,
            score = 30,
            author = "virulence",
            text = "Once you reach the northern ogre camp containing elites right outside of Gruul's Lair you can begin killing any of said ogres for the key for the cage. The cage can be found by walking straight forward into the camp and just looking up and to the left a little. On a side note, the raptors and ogres paired on patrol are not linked pulls; this leaves alot of possibilites open for solo kiting.",
            date = "2007-01-22T03:54:31-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10724#comments:id=22678",
        },
        {
            id = 1853690,
            score = 25,
            author = "princessv",
            text = "OK I just have to log on and post this...\n\nBlizzard should consider how painful it is to kill them, these large ugly cumbersome ogres, as their queen.. ~>,<~\n\nThey died hailing me..\n\n\"Queen, me die now..\"\n\"Me honored, queen kill me...\"\n\"Queen think...there really is... Ogri'la?\"\n\"Puny blood elf... you were a... horrible queen...\"\n\nI am a horrible queen indeed Q,Q..\n\n(and I think everyone knows how many ogres you have to kill before you get the quest item.. IT'S RIDICULOUS!)",
            date = "2013-05-16T21:59:07-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10724#comments:id=1853690",
        },
        {
            id = 28656,
            score = 22,
            author = "18408",
            text = "Coords are 64, 21.",
            date = "2007-02-01T00:11:04-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10724#comments:id=28656",
        },
    },
    [10742] = {
        {
            id = 40672,
            score = 247,
            author = "7553",
            text = "64,18 is the cooridinates..seems nobody has mentioned it",
            date = "2007-02-22T16:55:51-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10742#comments:id=40672",
        },
        {
            id = 44412,
            score = 155,
            author = "4634",
            text = "The quest chain:\n1. Thunderlord Clan Artifact - http://www.wowhead.com/?item=30431 (Drops from the Bladespires)\n2. Thunderlord Clan Artifacts - http://www.wowhead.com/?quest=10524 (Get the Arrow, Drum and Tablet)\n3. Vision Guide - http://www.wowhead.com/?quest=10525 (Right-click the fragment and see where the last artifact is.)\n4. The Thunderspike - http://www.wowhead.com/?quest=10526 (Go to the place show in the vision. Kill the guy guarding the spike)\n---Rewards:\n---Thunderlord Scalpel - http://www.wowhead.com/?item=31475\n---Slow Death Dirk - http://www.wowhead.com/?item=31476\n---Wand of the Ancestors - http://www.wowhead.com/?item=31474\n5. The Spirits Have Voices - http://www.wowhead.com/?quest=10718 (Talk to the ghost leader)\n6. Whispers on the Wind - http://www.wowhead.com/?quest=10614 (Talk with Leoroxx)\n7. Reunion - http://www.wowhead.com/?quest=10709 (alk with Rexxar)\n8. On Spirit's Wings - http://www.wowhead.com/?quest=10714 (Go to the ogres and use the whistle)\n9. Baron Sablemane - http://www.wowhead.com/?quest=10783 (He's at the arena)\n10. Into the Churning Gulch - http://www.wowhead.com/?quest=10715 (Kill random crust bursters for poison)\n---Rewards:\n---Bloodboil Poison - http://www.wowhead.com/?item=31535\n11. Baron Sablemane's Poison - http://www.wowhead.com/?quest=10749 (Take the poison to Rexxar)\n12. The Smallest Creatures - http://www.wowhead.com/?quest=10720 (drum up a marmot to poison the kegs)\n......Side Quest......\n...Crush the Bloodmaul Camp (From Tor'chunk Twoclaws) - http://www.wowhead.com/?quest=10784 (Kill ogres while you're poisoning kegs)\n......Side Quest......\n13. A Boaring Time for Grulloc - http://www.wowhead.com/?quest=10721 (Use the whistle, grab the sack, laugh)\n14. It's a Trap! - http://www.wowhead.com/?quest=10785 (We can't stop here! This is bat country!...Talk to rexxar, again.)\n15. Gorgrom the Dragon-Eater - http://www.wowhead.com/?quest=10723 (Use the trap at the altar)\n---Rewards:\n---Fanged Axe - http://www.wowhead.com/?item=31542\n---Whistling Sword - http://www.wowhead.com/?item=31541\n---Adjucator's Staff - http://www.wowhead.com/?item=31543\n......Side Quest......\n...Slaughter at Boulder'mok (From Tor'chunk Twoclaws) - http://www.wowhead.com/?quest=10786 (Kill more ogres)\n......side Quest......\n16. Prisoner of the Bladespire - http://www.wowhead.com/?quest=10724 (Kill more ogres, Use the whistle, profit)\n17. Showdown - http://www.wowhead.com/?quest=10742 (Summon Rexxar at the altar and kill Goc)\n---Rewards:\n---Tourmaline Crown - http://www.wowhead.com/?item=31546\n---Oilcloth Breeches - http://www.wowhead.com/?item=31545\n---Leonine Breasplate - http://www.wowhead.com/?item=31549\n---Clefthoof Leggings - http://www.wowhead.com/?item=31544\n---Malefactor's Eyepatch - http://www.wowhead.com/?item=31547\n---Blackened Chestplate - http://www.wowhead.com/?item=31548\n\nIf someone wants to go through all that and calculate the XP involved...I'm guessing about 1/4 of a level at 69.",
            date = "2007-03-01T06:58:33-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10742#comments:id=44412",
        },
        {
            id = 1597616,
            score = 65,
            author = "871488",
            text = "A guide to completing the whole chain detailed in the first comment:\n\n1) First of all fly straight to Bladespire Hold and kill ogres here. They will drop https://www.wowhead.com/item=30431, use this to\nbegin the first part of the chain.\n\n2) Collect the artifacts described. They can be found at the following co-ordinates:\n/way 41, 52\n/way 40, 58\n/way 41, 46\n\n3) Fly to Rokgah Bloodgrip (/way 51.8, 58.4) and hand that in. He will give you then give you\nhttps://www.wowhead.com/quest=10525 and an item called https://www.wowhead.com/item=30481. Use this while standing beside him and just wait for it\nto do it's thing. Hand it in and take the quest https://www.wowhead.com/quest=10526.\n\n4) Fly to the cave (entrance co-ordinates are /way 42.5, 83.4) and run to the end of it. Click the shiny\nspear and kill the ogre that spawns on top of you. Return to Rokgah. When you hand it in a Garm\nWolfbrother will appear beside you and offer you https://www.wowhead.com/quest=10718. Take it and hand it into Rexxar who\nis just a few yards away (/way 51, 58).\n\n5) Rexxar will then give you https://www.wowhead.com/quest=10614. Fly east to Leoroxx (/way 75.2, 60.9) and hand it in.\nCollect https://www.wowhead.com/quest=10709 and return to Rexxar. He will then give you https://www.wowhead.com/quest=10714, accept it and fly\nnorth (/way 58.11, 33.53). Use https://www.wowhead.com/item=31128 in your bag and summon the spying bird right on top of\nthe Taskmaster and Soothsayer. Return to Rexxar.\n\n6) After handing that in, he will offer you https://www.wowhead.com/quest=10783. Fly north again and hand that in (/way 53.3,\n41). Accept the Baron's quest and travel over to the Burning Gultch (/way 49, 43). Kill https://www.wowhead.com/npc=21381s\nand loot them. Return to Baron Sablemane and accept his next quest https://www.wowhead.com/quest=10749.\n\n7) This is more or less the second half of the chains leading up to https://www.wowhead.com/quest=10742. Deliver the Baron's\npoison to Rexxar back at the Thunderlord Stronghold and then accept https://www.wowhead.com/quest=10720. For this, fly\nnorth and use https://www.wowhead.com/item=31141 at the Marmot Den (/way 56.46, 29.24). After taking control of one of\nthese little creatures, use it to poison the barrels of alcohol found at:\n\n/way 55.36, 28.27\n/way 55.25, 25.95\n/way 55.96, 23.04\n\n  *Remember that the Marmots can aggro mobs, so avoid them. Use stealth on your pet's action\nbarand you should be able to sneak around everything. The Drum has a 6 minute cooldown so it's a\npain if your marmot dies.\n\n8) Hand that in to Rexxar and collect https://www.wowhead.com/quest=10721. Fly over to /way 60, 47 and let \"Huffer\" loose by\nclicking on https://www.wowhead.com/item=31350 in your bags. When Grulloc has been distracted by the Huffer collect\nhttps://www.wowhead.com/item=31349. Take this to Baron Sablemane.\n\n9) Accept https://www.wowhead.com/quest=10785 and take the trap to Rexxar. After handing that in he will give you the quest\nhttps://www.wowhead.com/quest=10723. Fly northeast to /way 30, 22 and kill 3 ogres, loot their heads and place them at the\nalter in the middle of that open area. Set the trap (found in your bags) on top of the alter and wait for\nGorgrom. Once this is done, return to Rexxar.\n\n10) Second last quest! Pick https://www.wowhead.com/quest=10724 up from Rexxar and fly north again to /way 66, 22 and kill\nogres and loot the https://www.wowhead.com/item=31755. Then use https://www.wowhead.com/item=31144 and the spirit will fly up and release the\nWyvern from its cage. Return to Rexxar to collect the quest you've been waiting for...\n\n11) Collect https://www.wowhead.com/quest=10806 and head to /way 64.15, 18.5 . Use https://www.wowhead.com/item=31146 here at the Alter of Goc\nthen kill him. Finally, return to Rexxar at Thunderlord Stronghold and collect your well deserved\nreward!",
            date = "2011-12-17T01:27:28-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10742#comments:id=1597616",
        },
        {
            id = 1612831,
            score = 59,
            author = "Mathaylla",
            text = "My biggest problem with this quest was finding the altar, since the quest location did not show up on the map. As usual, Wowhead was incredibly helpful with exact coordinates! The altar is at 64,18 - but if you don't have an addon to show coordinates, here are the directions:\n\nThe altar is northwest of the entrance to Gruul's Lair. If you stand under Leokk's cage (the wyvern that you freed in a previous quest), and facing the rock wall (so approximately north), turn to your left, there's a building there with a Bladespire Enforcer in front of it. The altar is going to be to the left of the building and a bit toward the back.",
            date = "2012-01-17T21:04:10-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10742#comments:id=1612831",
        },
        {
            id = 22589,
            score = 36,
            author = "13511",
            text = "Not a hard quest if you were able to handle the previous step, collecting the key. The altar is up the left and up the hill from inside the elite outpost area.\n\nRexxar actually tanks him the whole time, so finding a healer is not necessarily. Just dps and avoid his AE damage as best you can. He has a few AEs that were hitting our pets, one that I saw in my combat log was \"Ground Smash\", that hit my pet for 1700ish (pet has 9k armor). So it hurts if you get hit, but you can always back out and bandage around the fight as Rexxar keeps him quite busy.\n\nFinished the quest tonight: warlock, mage, hunter, hunter.. all 66ish",
            date = "2007-01-21T22:34:11-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10742#comments:id=22589",
        },
    },
    [10744] = {
        {
            id = 32577,
            score = 44,
            author = "Mysteeq",
            text = "Before you get GRRRRR like I did, the quest ends inside the main keep at 35.57 he is downstairs",
            date = "2007-02-08T06:42:07-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10744#comments:id=32577",
        },
        {
            id = 1380524,
            score = 30,
            author = "Hairband",
            text = "If you came here looking for the location of this quest turn-in dwarf for the chain quest in Shadowmoon Valley, these comments aren't so helpful.  Hopefully this will clarify.\n\nYou enter the large Dwarven keep.  You can either go left or right inside the structure, up a short flight of stairs.  It's a mirror image deal, so take your pick.  Follow whichever path you chose to the absolute end until you can go no farther, and you will see another staircase down.  Take it all the way down (it's actually two staircases, but you will end up in a tiny room with a doorway down.\n\nAgain go down, and you will see the questgiver in the middle of the room.  There are similar forts in the game such as Bael Modan in Southern Barrens and Angor Fortress in Badlands.\n\nIf you are by some dwarven airplanes, just exit completely and come back in again.  If you're in that middle area means you're basically lost.",
            date = "2011-03-31T00:51:36-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10744#comments:id=1380524",
        },
        {
            id = 49990,
            score = 27,
            author = "32701",
            text = "Haven't you people ever been to any of the 10s of other dwarven made keeps in the game?  They're all the exact same.\n\nAnyway, really easy quest chain for a decent ring reward.  Well worth doing.",
            date = "2007-03-12T07:47:19-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10744#comments:id=49990",
        },
        {
            id = 33533,
            score = 21,
            author = "Flyv",
            text = "This quest is at the end of a long chain that for Alliance, starts at \"Besieged!\" (http://www.wowhead.com/?quest=10562).",
            date = "2007-02-10T10:00:19-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10744#comments:id=33533",
        },
        {
            id = 76067,
