            author = "Stecors",
            text = "You need to use the flare gun to summon the quest giver. If you lost your flare gun, you can get another one from Thane Yoregar (https://www.wowhead.com/npc=21773/thane-yoregar). He is standing in front of the Wildhammer Stronghold entrance.",
            date = "2019-12-10T12:43:09-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10751#comments:id=3175971",
        },
