    [10758] = {
        {
            id = 30612,
            score = 55,
            author = "20264",
            text = "The Fel Reaver passes very close to the eastern side of Thrallmar. I managed to kite it to the NPCs that fight the infernal bombarment and they took it down in about one minute. Also if anyone in the area has killed one, you only need to be able to target the corpse and you'll be able to use the mold.",
            date = "2007-02-04T12:55:57-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10758#comments:id=30612",
        },
        {
            id = 31440,
            score = 42,
            author = "20479",
            text = "Notice that you only need a dead fel reaver in order to finish this.  If you see someone else fighting one, you might as well help them out.",
            date = "2007-02-05T22:02:04-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10758#comments:id=31440",
        },
        {
            id = 27002,
            score = 30,
            author = "17682",
            text = "this is for the key to the shattered halls. to start the very first part of this chain u must kill this guy http://www.wowhead.com/?npc=22037 and he drops the quest item to start the first part. there are a lot of mobs around him so its better if u go to him with a flying mount. other than that he is reachable without one as well.",
            date = "2007-01-29T09:06:47-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10758#comments:id=27002",
        },
        {
            id = 32855,
            score = 24,
            author = "11467",
            text = "Confirmed... When he passes by Thrallmar, just kite him to the group of elites who normally kill the spawning infernals, they downed him in about 2 minutes, completed the quest by myself.",
            date = "2007-02-08T22:04:29-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10758#comments:id=32855",
        },
        {
            id = 39935,
            score = 7,
            author = "dangermouse777",
            text = "Not sure if they changed this or not, but here's my experience with it:\n\nStanding by the group of mages, he comes out of the southeast, walks north by them, then heads northeast.  About 2 minutes later, he comes back from the northeast, down, and out to the southeast.  About 20 minutes later he comes back around.\n\nThe first time I tried to kite him the mages didn't pick him up.  I ran him right through them, and he continued to pound me.  After I died he just ran off.\n\nThe second time, however, the mages were dropping blizzards, fighting the infernals.  I ran him through the fight there, and ice blocked on the other side.  After my iceblock popped he killed me, but then ran over to the mages.  I released, rezzed, and ran over to watch the show.  So it may be that they changed it so that the mages won't pick him up, but if they hit him with the blizzard he'll return the favor.",
            date = "2007-02-21T13:05:42-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10758#comments:id=39935",
        },
    },
