    [10764] = {
        {
            id = 33025,
            score = 121,
            author = "21817",
            text = "When I wanted to do this quest I was told that the Fel Reaver had been killed recently. I said to myself, oh well, gotta wait for him to respawn.\n\nBut then I realized that the quest didn't need me to kill him, so I just went for his body and used the item while standing on it, and got the quest completed.\n\nSo there you have it. You don't need to actually kill the Fel Reaver, if you see his body just stand on it and use the item.",
            date = "2007-02-09T07:34:28-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10764#comments:id=33025",
        },
        {
            id = 20281,
            score = 40,
            author = "11945",
            text = "Fel Reaver: http://www.wowhead.com/?npc=18733\n\nPrereq: http://www.wowhead.com/?quest=10763",
            date = "2007-01-11T22:33:30-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10764#comments:id=20281",
        },
        {
            id = 58393,
            score = 38,
            author = "19652",
            text = "If you stand around 59, 41 in Hellfire Penninsula, there is a Fel Reaver that pats by. If you are patient and wait for him, you can pull the fell reaver to the right into a pack of elite mobs. They'll kill it for ya. If you're alliance, they're Thrallmar guards, so you will most likely die. If you can have a friend do the pull and you stay alive, that's fine. Or you can have an SS or whatever so you can complete the quest after the guards kill the fel reaver.",
            date = "2007-03-28T01:39:50-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10764#comments:id=58393",
        },
        {
            id = 50290,
            score = 21,
            author = "31550",
            text = "Deathforge Automatons will also work to fire your key mold. Tried this just now in my guilds raid group and it worked just fine.\n\nBeats trying to kite a Fel Reaver...",
            date = "2007-03-12T21:26:53-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10764#comments:id=50290",
        },
        {
            id = 922903,
            score = 11,
            author = "258919",
            text = "Was about to kite to Thrallmar when an 80 horde pally showed up and promptly annihilated it.\n\nWas still able to get the quest done, because, as mentioned, you do not have to actually make the kill to use the mold.\n\nUnfortunately, the paladin saw me making the key. We were on a PvP server. I was an Ally.",
            date = "2009-12-19T10:49:15-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10764#comments:id=922903",
        },
    },
    [10765] = {
        {
