    [10768] = {
        {
            id = 29267,
            score = 15,
            author = "13857",
            text = "Contrary to what the item page says, this is a 100% droprate.",
            date = "2007-02-02T02:22:08-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10768#comments:id=29267",
        },
        {
            id = 85889,
            score = 10,
            author = "20486",
            text = "These, of course, are dropped by the mobs along the Path of Conquest, so you're still in the same area as the previous quests in this chain.\n\nEasiest (with flying mount) place to begin your attack into their numbers is at, or around, 54, 69.",
            date = "2007-05-19T19:13:52-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10768#comments:id=85889",
        },
        {
            id = 107142,
            score = 8,
            author = "62033",
            text = "It is solo able.",
            date = "2007-06-19T12:06:37-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10768#comments:id=107142",
        },
        {
            id = 31294,
            score = 3,
            author = "13454",
            text = "Only 1 drops per mob, so only 1 person can recieve it. If you have 3 people you must farm 30 mobs.",
            date = "2007-02-05T14:18:04-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10768#comments:id=31294",
        },
        {
            id = 377714,
            score = 2,
            author = "Rammstein",
            text = "There is a mob Val'zareq the Conqueror (http://www.wowhead.com/?npc=21979) that drops an item that starts a chain q The Journal of Val'zareq (http://www.wowhead.com/?item=31345), that leads to the Illidari tabard.",
            date = "2008-09-16T04:32:28-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10768#comments:id=377714",
        },
    },
    [10769] = {
        {
            id = 2248458,
            score = 53,
            author = "Seniade",
            text = "This is still bugged. You can complete Lore Master without it, there are no more quests after this one in that chain.",
            date = "2015-09-08T22:30:32-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10769#comments:id=2248458",
        },
        {
            id = 24414,
            score = 32,
            author = "1987",
            text = "Mobs to kill: http://www.wowhead.com/?npc=19823\n\nThis is the end of this series: http://www.wowhead.com/?quest=10750",
            date = "2007-01-25T13:00:01-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10769#comments:id=24414",
        },
        {
            id = 57641,
            score = 32,
            author = "Swyfter",
            text = "The Windrider gives you a tabard that you must equip.\n\nBe aware that the tabard rots after 1 hour playtime. I discovered this to my horror after getting 4/5 kills because of flaky kill credit (and dinner).\n\nIf you leave the area or die, you lose the buff and must unequip and reequip the item.\n\nMy best advice is to reequip the item after you make each kill, just to keep the buff fresh. I noticed that I would randomly lose the buff every other kill, even though there was no buff timer.",
            date = "2007-03-26T17:00:26-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10769#comments:id=57641",
        },
        {
            id = 2213973,
            score = 29,
            author = "Tantrevalles",
            text = "Still bugged as of 7/14: at the Bug forum on Battlenet someone has started a thread, which you will find typing \"Dissension\" in the search box. I recommend you add your comments to that thread instead of starting a new one.",
            date = "2015-07-14T09:57:31-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10769#comments:id=2213973",
        },
        {
            id = 61196,
            score = 24,
            author = "21378",
            text = "If you don't finish the quest within an hour, you need to abandon it, fire off the flare gun, and pick it up again.  This will get you a new tabard.\n\nTanked it with my (hunter) pet and a healer.  Mend Pet couldn't keep up, but the healer could.  The giants take forever to kill, so you're going to need a way to heal.\n\nThe giants are immune to poison, but not to arcane or (non-poison) nature.",
            date = "2007-04-02T16:43:41-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10769#comments:id=61196",
        },
    },
    [10770] = {
        {
            id = 24429,
            score = 27,
            author = "14102",
            text = "These are located near 72, 23.",
            date = "2007-01-25T13:15:27-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10770#comments:id=24429",
        },
        {
            id = 28476,
            score = 25,
            author = "3217",
            text = "Pair with this quest: http://www.wowhead.com/?quest=10771",
            date = "2007-01-31T18:17:08-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10770#comments:id=28476",
        },
        {
            id = 1060519,
            score = 18,
            author = "133694",
            text = "Wait... The questgiver says the Burning Legion burned his home forest away centuries ago...\n\nBut the Burning Legion didn't even find Draenor until 40-60 years ago...",
            date = "2010-06-18T19:45:32-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10770#comments:id=1060519",
        },
        {
            id = 286404,
            score = 5,
            author = "jerodast",
            text = "Personally, absolutely hated this quest as a rogue. The searing elementals have annoying wandering patrol paths and even the imps can be clustered too tightly. I was a total slave to the random movements of mobs in terms of getting one of them alone, cuz of course we could never let sap work on anything but humanoids. And these guys do a LOT of damage so you definitely don't want to be fighting 2 or three; I got burned down FAST. Watch out for searing elementals that are hiding in the flamey areas. Oh yeah also the location bug came up now and then where the imp would be slightly off from where it appeared to be, making it difficult to stun/kick them as they were casting.",
            date = "2008-05-11T21:43:43-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10770#comments:id=286404",
        },
        {
            id = 114827,
            score = 4,
            author = "TheRealAzoth",
            text = "Be sure to  kill a few Searing Elementals (http://www.wowhead.com/?npc=20514) that are in the area while doing this quest. They drop Mote of Fire at a rather decent rate that sell very well on AH or you can bank them for future enchants, etc...",
            date = "2007-07-03T06:41:27-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10770#comments:id=114827",
        },
    },
    [10771] = {
        {
            id = 23456,
            score = 61,
            author = "8508",
            text = "Southern, 71, 22\nCentral, 71, 20\nNorthern, 71, 18 (up a little hill)\n\nThere are a lot of elementals and imps here, be prepared for a significant amount of fire damage. Consider bringing a friend.",
            date = "2007-01-24T02:51:03-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10771#comments:id=23456",
        },
        {
            id = 19705,
            score = 27,
            author = "Lustral",
            text = "All three soil samples can be found around coordinates 72, 22, north of Forge Camp: Anger.  Once you've found the southern sample, the two others are just north.\n\nYou'll know you're in the right place when you see the fire elementals and scorched imps, in an region called Skald.",
            date = "2007-01-07T16:17:08-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10771#comments:id=19705",
        },
        {
            id = 24396,
            score = 16,
            author = "3209",
            text = "Probably soloable by all classes, but as a 67 Warrior I found this quest a real pain. The Fire Elemental's \"Immolation\" hits you for 135 fire damage every second while in melee range, much like the Night Elf Hero (Demon Stalker) / Illidan look-alike from Warcraft III.\n\nAn extreme pain if several mobs are pulled, be careful!",
            date = "2007-01-25T12:45:17-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10771#comments:id=24396",
        },
        {
            id = 31012,
            score = 9,
            author = "20486",
            text = "These mobs are a decent source of Motes of Fire for those of you who want to farm Primal Fire.",
            date = "2007-02-05T03:11:56-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10771#comments:id=31012",
        },
        {
            id = 28233,
            score = 6,
            author = "5883",
            text = "The soil disappears for a little while after someone uses it, so if you can't seem to find them, consider waiting a minute or two for them to respawn.",
            date = "2007-01-31T11:45:47-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10771#comments:id=28233",
        },
    },
    [10772] = {
        {
            id = 32708,
            score = 36,
            author = "jackhunter64",
            text = "You can use the gun anywhere, as long as you've got the Path of Conquest discovered. I found the place and got swarmed by the blood elves, but I used the flare gun at the graveyard and it still completed properly.",
            date = "2007-02-08T14:41:19-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10772#comments:id=32708",
        },
        {
            id = 2548529,
            score = 18,
            author = "Drougen",
            text = "Be aware that if you use the flare gun and the NPC gets attacked, she'll fly away and tell you to contact her when you're at a safe location. You'll have to wait 2 minutes to re-summon her. This means make sure there's no enemy NPCs around when you use it.",
            date = "2018-01-26T13:03:15-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10772#comments:id=2548529",
        },
        {
            id = 130670,
            score = 16,
            author = "49861",
            text = "I was having trouble soloing this one because I couldn't get past all the mobs. Then I discovered that at 50, 62, above the path with all the mobs, the quest completes. The only mobs here are dragonhawks, and no flying mount required.",
            date = "2007-08-01T19:42:17-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10772#comments:id=130670",
        },
        {
            id = 52276,
            score = 12,
