        },
        {
            id = 2300256,
            score = 1,
            author = "Aurleis1",
            text = "Video Guide: https://www.youtube.com/watch?v=jJQB5j5j0IA\n\n1.  https://www.wowhead.com/quest=10775\n•\009Travel to the Path of Conquest, in [zone=3520].\n•\009Use the https://www.wowhead.com/item=31310, that was given to you by https://www.wowhead.com/npc=21773, at Wildhammer Stronghold (coords: 36.2, 56.8).\n•\009Accept the quest, https://www.wowhead.com/quest=10775, from https://www.wowhead.com/npc=19382.\n•\009Kill Illidari and Eclipsion mobs at The Path of Conquest, looting 10 https://www.wowhead.com/item=31278 from their corpses.\n•\009Use the https://www.wowhead.com/item=31310, and turn in the quest to the https://www.wowhead.com/npc=19382.",
            date = "2016-01-20T14:28:25-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10775#comments:id=2300256",
        },
        {
            id = 111552,
            score = 0,
            author = "10315",
            text = "if you're in a grp of 3 like the quest suggested, you'll going to have to kill 30 all up since the tabards are not party loots",
            date = "2007-06-26T23:03:54-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10775#comments:id=111552",
        },
    },
    [10776] = {
        {
            id = 2203184,
            score = 68,
            author = "1484391",
            text = "I can  not complete this quest on patch 6.2. The tabard is up, buff up and when i kill the mobs i have still 0/5. What can i do or is the quest bugged?",
            date = "2015-06-28T11:34:32-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10776#comments:id=2203184",
        },
        {
            id = 2212079,
            score = 41,
            author = "Sniperlock",
            text = "For those of you that are not getting credit for the kills, and therefore are unable to complete the quest as of patch 6.2 - it is not necessary for Shadow of the Betrayer (http://www.wowhead.com/achievement=1195/shadow-of-the-betrayer). For me, to complete 90 Shadowmoon Valley quests, completing the questline beginning with Borak, Son of Oronok (http://www.wowhead.com/quest=10546/borak-son-of-oronok) enabled me to get exactly to 90 quests. I had tried everything to complete to complete this quest, made sure my pet was on passive; dismissing pet; killing them as quickly as possible; killing them as slowly as possible (with a lower level weapon and melee'ing them); trying to kill them all around the same time (when they turn to multiple smaller ones); killing the one needed for the quest last; abandoning the quest and grabbing it again; finishing other quests around the zone (I had to go and finish my green fire questline, which is started by Sealed Tome of the Lost Legion (http://www.wowhead.com/item=92426/sealed-tome-of-the-lost-legion)); logging out and back in again; deleting cache, WTF and Interface folders. So for anyone stressing they can't get to 90 quests, it is possible without this! Also, I imagine there isn't going to be priority fixing bugs like this due to WoD.",
            date = "2015-07-12T01:34:29-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10776#comments:id=2212079",
        },
        {
            id = 28063,
            score = 38,
            author = "Dalindra",
            text = "Make sure a pet does not get the killing blow...we learned that the hard way.",
            date = "2007-01-31T03:02:05-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10776#comments:id=28063",
        },
        {
            id = 29069,
            score = 28,
            author = "snownova",
            text = "You can find the giants at 42,70 and the area south of that.",
            date = "2007-02-01T17:42:35-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10776#comments:id=29069",
        },
        {
            id = 51550,
            score = 19,
            author = "15292",
            text = "Duo'd this as a prot warrior with my holy priest friend.\n\nThey are easy to kill, but have a LOT of hit points. If you have a DPS friend bring them along. Remember these giants spawn small rock creature adds which I didnt see mentioned, like the Rock Giants in Hellfire Peninsula",
            date = "2007-03-15T10:02:55-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10776#comments:id=51550",
        },
    },
