            author = "9877",
            text = "The key is found off of any of the Blood Elves there - just kill them until you find it.\n\nThen use the key to open the Lianthe's Strongbox found at (48, 72) to the left of Grand Commander Ruusk.",
            date = "2006-12-25T21:44:46-06:00",
