    [10797] = {
        {
            id = 890518,
            score = 28,
            author = "jsanchez",
            text = "Do not go straight to kill Dorgok in order to get the item to start this quest, without having the quest A Date with Dorgok (http://www.wowhead.com/?quest=10795) in your Questlog, because I did that and it didn't let me acept the quest. It said: \"You don't meet the requirements to do that quest\", so I have to go back to Evergrove to speak with  Commander Haephus Stonewall (http://www.wowhead.com/?npc=22149), get the quest, slain Dorgok again and turn in the quest before it let mi accept the quest from the item Gorgrom's Favor.",
            date = "2009-11-14T07:30:41-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10797#comments:id=890518",
        },
        {
