    [10799] = {
        {
            id = 29963,
            score = 14,
            author = "14436",
            text = "Loc near 45,48. entrance is directly west of the questgiver as SSdraken said",
            date = "2007-02-03T10:05:10-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10799#comments:id=29963",
        },
        {
            id = 37099,
            score = 13,
            author = "ecartman",
            text = "Got drops from both little guys and big worms. Little guys seem easier to kill, no aggro problems and plenty of them.",
            date = "2007-02-16T15:44:20-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10799#comments:id=37099",
        },
        {
            id = 24162,
            score = 7,
            author = "6850",
            text = "Large worms do not have a 100% to drop rate, as the previous poster mentioned, it's high but not 100%.",
            date = "2007-01-25T03:02:08-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10799#comments:id=24162",
        },
        {
            id = 121675,
            score = 5,
            author = "Rawbert",
            text = "Keep in mind that the Young Crust Bursters evade after about 20-30 yards, so make sure you pull closely while you kill them.  Pulling at max range (as an Aff Lock) got all my dots whiped by the time they reached me.\n\nOn the flipside, casting Howl of Terror when you get 2 or more on you absolutely removes you from combat after a couple seconds.  This could also work for priests.",
            date = "2007-07-16T14:31:05-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10799#comments:id=121675",
        },
        {
            id = 38275,
            score = 3,
            author = "24224",
            text = "It was on my 15th mob (4th Greater, and after 11 of the lessers) that I got my first drop, after that they started to flow nicely, though it still took about 35 total mobs to finish.  Don't get discouraged if your experience is slower than those reported above...",
            date = "2007-02-18T17:37:05-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10799#comments:id=38275",
        },
    },
    [10800] = {
        {
            id = 33472,
            score = 41,
            author = "632",
            text = "This is how I did when I finally completed it:\n1) Get close enough to use the powder and use the first charge.\n2) Run close enough to grab the bag, and use the second charge.\n3) Grab the bag and use the third charge.\n4) Run away.\n5) ???\n6) Profit!",
            date = "2007-02-10T05:52:15-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10800#comments:id=33472",
        },
        {
            id = 22422,
            score = 34,
            author = "13645",
            text = "You will find Grulloc at 60, 47.  Use the Sablemane's Sleeping Powder to put him to sleep and grab his sack.  He will only sleep for a few seconds so grab it and run away!",
            date = "2007-01-21T14:27:51-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10800#comments:id=22422",
        },
        {
            id = 30712,
            score = 9,
            author = "4629",
            text = "He can also resist the powdercast! And he hits clothies for 1200-1800.",
            date = "2007-02-04T16:50:45-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10800#comments:id=30712",
        },
        {
            id = 27112,
            score = 4,
            author = "17772",
            text = "Well, its easy for a priest;) mind soothe him and go close, then cast the powder and woalla!",
            date = "2007-01-29T12:26:18-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10800#comments:id=27112",
        },
        {
            id = 180029,
