            author = "56707",
            text = "He resisted the powder TWICE and i died.  rez'd back, tried it again and the last one worked, grabbed the sack and ran away.  easy, except this bastard owes me a repair bill for that 3 hit death.",
            date = "2007-11-06T10:56:40-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10800#comments:id=180029",
        },
    },
