    [10802] = {
        {
            id = 22701,
            score = 64,
            author = "13072",
            text = "Coords are 30, 21. Should also do the quest \"Slaughter at Boulder'mok\" together.",
            date = "2007-01-22T04:54:43-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10802#comments:id=22701",
        },
        {
            id = 27106,
            score = 51,
            author = "16588",
            text = "It's worth to mention that you need 3 Grisly Totems, which drops of the ogrees. After Gorgrom walked into the trap, you need to plant the totems there. It's done by simply clicking on them in your backpack.\n\nIt seems to be possible to plant the totems a short while after the corpse of Gorgrom vanished, incase you forget to plant them (like I did). But play it safe, and plant them as soon as possible.",
            date = "2007-01-29T12:13:44-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10802#comments:id=27106",
        },
        {
            id = 22620,
            score = 28,
            author = "Aevorn",
            text = "There is a level 72 elite bear near the Altar. Keep your distance from it.\n\nThe key to this quest, is to keep a suitable distance from the Altar and not interfere with the script. After you place the trap, Gorgrom will appear in the large clearing on the north side of the Altar, walk to it and get killed by the trap.\n\nVery easy, if you don't interfere. Very painful, if you do.",
            date = "2007-01-21T23:51:26-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10802#comments:id=22620",
        },
        {
            id = 126140,
            score = 11,
            author = "zwuckel",
            text = "30,22 for altar",
            date = "2007-07-24T16:39:12-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10802#comments:id=126140",
        },
        {
            id = 206331,
            score = 11,
            author = "72738",
            text = "I recommend clearing the ogres all around the camp fire since they'll attack you.\nGrogrom, when summoned, will walk straight to the altar and fall. Then you must put your totems that you gathered all around his body.\nAnd just incase you think that scene is sad look at the ogre near the forge who will be dancing better than any charcater in the game. :P",
            date = "2007-12-24T01:50:11-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10802#comments:id=206331",
        },
    },
