            author = "1019447",
            text = "I can confirm that you can only pick up this quest after completing [quest=10552 domain=www]; which, in turn, requires: [quest=10210 domain=www] and [quest=10211 domain=www].",
            date = "2012-08-04T09:52:20-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10807#comments:id=1695941",
