    },
    [10808] = {
        {
            id = 26785,
            score = 143,
            author = "16903",
            text = "Go to Cthun summoning place at 41.60 (around), kill all the guards and try to use the staff. It requires an \"unguarded place\", which I found a bit hard to find. I killed all the summoners and then at the site of the last kill, used the staff and it worked. So the correct place is by the pond where the cthun is being summoned. Keep trying at various locations around it if you get the error message.",
            date = "2007-01-29T00:39:35-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10808#comments:id=26785",
        },
        {
            id = 22907,
            score = 92,
            author = "13988",
            text = "Cthun wannabe 41.60",
            date = "2007-01-22T18:00:13-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10808#comments:id=22907",
        },
        {
            id = 55025,
