    [10810] = {
        {
            id = 1050485,
            score = 43,
            author = "rudini",
            text = "Don't be dumb like me and are killing hundreds of fel corruptors to get this drop.  First check with Wildlord Antelarion at Evergrove in Ruuan Weald to see if you've already looted this item and never finished the quest line.  He will provide you with another mask if you already had it and stupidly got rid of it.",
            date = "2010-06-01T21:48:37-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10810#comments:id=1050485",
        },
        {
            id = 156975,
            score = 41,
            author = "87797",
            text = "This item is a drop from a Fel Corruptor. They roam around in pairs of 2 around 70,35 in blade's edge mountain.",
            date = "2007-09-23T04:49:01-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10810#comments:id=156975",
        },
        {
            id = 327271,
            score = 24,
            author = "Travy",
            text = "If you are like me and doing this chain for the necklace in the end, you might as well pick up Culling the Wild (http://www.wowhead.com/?quest=10753), for the extra gold and rep as you will be maiming monsters in the same area anyways.",
            date = "2008-07-15T19:15:56-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10810#comments:id=327271",
        },
        {
            id = 41874,
            score = 18,
