            text = "Almost 2000 Cenarion Expedition Rep for the entire quest line. More for us humans ;)\n\nDecent money maker if you are a level 70 (86g 39s 73c if you sell rewards too)",
            date = "2007-02-25T02:15:52-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10810#comments:id=41874",
