    [10819] = {
        {
            id = 24502,
            score = 343,
            author = "15528",
            text = "This gas mask only has a duration of 60 minutes in your backpack.  It's recommended you run your butt off to use this item, or chance not having it in your pack when you decide to do it.\n\nTo get another mask, talk to Wildlord Antelarion (http://www.wowhead.com/?npc=22127).\n\nFurthermore, you must have the mask on to be able to interact with the communicator.  It's between 2 green floating pylons to the left of the entrance (if you're facing it from the outside).",
            date = "2007-01-25T15:35:01-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10819#comments:id=24502",
        },
        {
            id = 25195,
            score = 92,
            author = "10938",
            text = "Dont equip the mask while on a mount - you won't get the buff you need for this quest.",
            date = "2007-01-26T16:14:19-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10819#comments:id=25195",
        },
        {
            id = 21546,
            score = 56,
            author = "ubermonkey",
            text = "Legion Communicator - 73.3,40",
            date = "2007-01-19T01:48:06-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10819#comments:id=21546",
        },
        {
            id = 22368,
            score = 45,
            author = "13233",
            text = "For some reason i can't click it :(\n\nEdit: Check that you have the buff from the head, otherwise you won't be able to use the Communicator.",
            date = "2007-01-21T01:33:45-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10819#comments:id=22368",
        },
        {
            id = 1564903,
            score = 34,
            author = "362863",
            text = "As the quest text clearly explains, the gas mask has a self-destruct timer so you must hurry to do this quest.  Wait, what?  No, the quest text fails to mention this nor explain any reason why it would be this way.  I assume Blizzard did this because having to run back to the quest-giver to pick up a necessary item that has no logical reason to spontaneously vaporize provides the kind of frustrating experience Blizzard players love from a game, greatly enhancing their enjoyment by having to engage in illogical, pointless, and tedious running around for no apparent reason.  Wait, what?  Does anyone have a theory for why this is the way it is that doesn't make Blizzard quest designers sound like complete idiots?  I'm drawing a blank...",
            date = "2011-11-06T16:45:49-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10819#comments:id=1564903",
        },
    },
