    [10821] = {
        {
            id = 140637,
            score = 87,
            author = "45224",
            text = "Don't worry. In a few levels, they'll want you back (http://www.wowhead.com/?quest=10186).",
            date = "2007-08-19T14:34:33-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10821#comments:id=140637",
        },
        {
            id = 23705,
            score = 53,
            author = "9857",
            text = "If you read the quest, its handed in at the nearby cenarion camp, not at the communicator. Therefore you can allow the time to expire. After reading your commend wuddersup I hurried to complete the quest, but actually there is no need.\n\nCollect 5 keys and quickly click all 5 obelisks. A green line will connect it to a nearby floating crystal to show it is activated. Once all 5 are connected, a level 68 elite demon will walk down from the floating crystal. She is relatively easy to kill with 2 level 67's.",
            date = "2007-01-24T12:24:43-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10821#comments:id=23705",
        },
        {
            id = 2329123,
            score = 36,
            author = "Zaynah",
            text = "This quest is only available when you are wearing a Felsworn Gas Mask  (item=31366).\n\nIf you lose your Felsworn Gas Mask  (item=31366) and you need to pick up this quest chain at a later stage, you can talk to Wildlord Antelarion (npc=22127) in Ruuan Weald and he will give you a new one.",
            date = "2016-05-08T21:16:18-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10821#comments:id=2329123",
        },
        {
            id = 2281523,
            score = 30,
            author = "1341720",
            text = "It appeared broken for me because as I was clicking the pillars and nothing seemed to be happening.\n\nSo, after running around like an idiot for a while, I just started clicking on random pillars and one of them worked.\n\nI ran to each of the 5 pillars, clicking, and only two of them worked.  After those two, though, all 5 pillars lit up with their beams and the boss came out.\n\nI think the \"short duration\" is gone, and if someone else clicks and leaves, the pillars stay activated, waiting for someone to finish the quest.\n\nIf the pillars don't seem to work, just click all of them anyways and after you've hit the last one that's not active, the boss will come.",
            date = "2015-11-28T15:58:22-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10821#comments:id=2281523",
        },
        {
            id = 142225,
