        {
            id = 670351,
            score = 4,
            author = "67095",
            text = "It seems like turning in a single mark instead of 10 will decrease the dereputation with the aldor by 0.5 per mark, or it could just be a hidden 0.5",
            date = "2009-04-08T22:27:13-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10822#comments:id=670351",
