    [10830] = {
        {
            id = 29140,
            score = 376,
            author = "15689",
            text = "[1] Kill Dire Ravens  to get 5 x Dire Pinfeather  drops. Drop rate is high, so less than 10 kills needed.\n[2] Collect 5 x Grishnath Orb . These are near the Grishnath huts to the North East.\n[3] Combine (click) the Dire Pinfeathers and Grishnath Orb to get 5 x Exorcism Feather\n[4] Find a Raven's Wood Leafbeard . Get within range and click Exorcism Feather, this will spawn a Koi-Koi Spirit . Kill the Spirit (not Leafbeard) and the Leafbeard will turn friendly. Kill 5 x Koi-Kois. No XP and no loot from Koi-Koi kills.",
            date = "2007-02-01T20:41:51-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10830#comments:id=29140",
        },
        {
            id = 22670,
