            text = "If you're in a group, only one person needs to collect the mats for the exorcism feathers.  Can complete for all.",
            date = "2007-01-24T01:16:15-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10830#comments:id=23416",
        },
