        },
        {
            id = 20937,
            score = 57,
            author = "ceemeeir",
            text = "Use the shard at ~ 44,51 (http://www.wowhead.com/?maps=3483:440510). Sometimes a Hellfire warding spawns, kill it, continue this until 4 shards appear next to the scryer. Sometimes an Orc spawns with add, but easily soloable as any lvl 60 char. (If you are a healer maybe you should team up with a DPS, I'm not sure about that you can do it alone. Read other's comment too, maybe you can find some other helpfull information.",
            date = "2007-01-17T02:03:23-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10838#comments:id=20937",
        },
        {
            id = 34625,
            score = 45,
            author = "21378",
            text = "Use the shard at the base of Hellfire Citadel, near the PvP area.  There's a nice monster-free area there.\n\nIt will summon a lot of monsters for you, mostly easy imps.  When it's done, talk to it to get a report.\n\nMake sure to read the report all the way through before turning this in.  It's some good lore and the change of tone near the end is delightfully jarring.",
            date = "2007-02-12T11:01:08-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10838#comments:id=34625",
        },
        {
            id = 86236,
            score = 21,
            author = "11780",
            text = "You *might* want to doublecheck your surroundings... as I was happily finishing this quest with my 62 warrior (really easy), suddenly Fulgorge emerged next to me ( http://www.wowhead.com/?npc=18678 ) - that was the end of my easy quest...",
            date = "2007-05-20T11:14:59-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10838#comments:id=86236",
        },
        {
            id = 3242141,
            score = 17,
            author = "Nyxcera",
            text = "When the four ''portals'' are visible, when shadow magic is flowing out of the ground: talk to the pillar to finish this quest.\nHad to do it twice. Don't do that to yourself :)",
            date = "2020-10-25T07:03:53-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10838#comments:id=3242141",
        },
    },
    [10839] = {
        {
            id = 17829,
            score = 99,
            author = "10162",
            text = "Darkstone of Terrok - (tloc 30,42)",
            date = "2006-12-23T02:09:47-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10839#comments:id=17829",
        },
        {
            id = 49431,
            score = 63,
            author = "Riven",
            text = "The Arrakoa race, their capital and this questline is a reference to Jim Henson's awesome film The Dark Crystal. ( http://en.wikipedia.org/wiki/The_Dark_Crystal )\n\nDarkstone = Dark Crystal\nSkettis = Skesis\n\netc.\n\nI have always loved that movie since I was little; subsequently the Arrakoa are one of my favorite new races in the Burning Crusade. I keep looking around for more subtle references to the film that are hidden within the quests and Arrakoa villages.\n\nJust a little bit of trivia for you all. :)",
            date = "2007-03-11T04:07:13-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10839#comments:id=49431",
        },
        {
            id = 22624,
            score = 51,
            author = "bprater",
            text = "It's the floating stone in the center of the village.",
            date = "2007-01-22T00:11:19-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10839#comments:id=22624",
        },
        {
            id = 59749,
