    [10842] = {
        {
            id = 1035904,
            score = 44,
            author = "458613",
            text = "So here's how to complete this quest as of 10:13PM EST on 5/9/2010\n\nEnter the Tomb of Lights.\n\nKill 5 Vengeful Souls.\n\nReturn to quest giver at the Caravan.\n\nNo summoning. No nothing. Vengeful Souls are just wandering around the place.\n\nSlay five.\nGive in Quest.\nGet Exp.\n\nBe happy.",
            date = "2010-05-09T21:15:42-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10842#comments:id=1035904",
        },
        {
            id = 21493,
            score = 39,
            author = "11009",
            text = "The Quest is not broken: might be a bug on it though.\nEnd of the tomb is a round room. You shall activate the quest given object here and defend ;)\n\nAlthough, it is possible to find a strange glowing ball of energy: this means script is bugged :(",
            date = "2007-01-18T21:05:41-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10842#comments:id=21493",
        },
        {
            id = 1003511,
            score = 14,
            author = "iburley",
            text = "This quest has now been renamed in patch 3.3.3 to Vengeful Souls, you now finish at High Priest Orglum instead of the Draenei Ascendant in the room, the quest has changed but it is unclear from the quest log where it is supposed to be turned in, all you need to do is kill 5 of the Vengeful Spirits in the room whilst the Tomb Guardian does his routine. Rewards at level 80 are 66 silver, 250 Lower City rep and either Ancient Draenei Arcane Relic (http://www.wowhead.com/?item=31615) or Ancient Draenei War Talisman (http://www.wowhead.com/?item=31617)",
            date = "2010-03-23T14:19:50-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10842#comments:id=1003511",
        },
        {
            id = 1004146,
            score = 9,
            author = "525708",
            text = "This quest has turned into a quest called \"Vengeful Souls\" the quest description goes as follows\n\n\"The Tomb of Lights has become corrupted by the Shadow Council and the draenei dead have become cursed spirits, angry and confused with a burning hatred for the living.\n\nEnter the tomb and seek out these tragic victims. Give them the rest that they deserve.\"\n\nThe objective of the quest is to kill 5 Vengeful Draenei.\n\nReward remains the same.",
            date = "2010-03-24T09:34:51-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10842#comments:id=1004146",
        },
        {
            id = 2298866,
            score = 9,
            author = "Aurleis1",
            text = "Video Guide: https://www.youtube.com/watch?v=3-eaI2opWxc\n\n1.  https://www.wowhead.com/quest=10842\n•\009Accept the quest, https://www.wowhead.com/quest=10842, from https://www.wowhead.com/npc=22278 at coords 37.4, 50.8 (Refugee Caravan).\n•\009Travel east, to the Tomb of Lights, to coords 47.0, 55.1.\n•\009Enter the Tomb of Lights, by entering its underground passageways.\n•\009Kill 5 https://www.wowhead.com/npc=21636.\n•\009Exit the Tomb of Lights.\n•\009Travel west, to the Refugee Caravan, to coords 37.4, 50.8\n•\009Turn in the quest to https://www.wowhead.com/npc=22278.",
            date = "2016-01-16T10:18:26-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10842#comments:id=2298866",
        },
    },
