            author = "Crazie",
            text = "First you must obtain 5 Condensed nether gas from the Gan'arg Mekgineer's.(37,27)\n after go and \"speak\" to the inactive fel reaver. (38.26/37,25/36,29)",
            date = "2007-09-16T04:21:34-05:00",
