        },
        {
            id = 2298510,
            score = 3,
            author = "Aurleis1",
            text = "Video Guide: https://www.youtube.com/watch?v=RiiIp9YZ3Us\n\n1.  https://www.wowhead.com/quest=10855\n•\009Accept the quest, https://www.wowhead.com/quest=10855, from https://www.wowhead.com/npc=20471 at coords 44.6, 34.8 (Stormspire).\n•\009Travel northwest, to Forge Base: Oblivion, to the vicinity of coords 37, 26.\n•\009Kill https://www.wowhead.com/npc=16949, in the area, and loot 5 https://www.wowhead.com/item=31653 from their corpses.\n•\009Go to the https://www.wowhead.com/npc=22293, to feed it the 5 https://www.wowhead.com/item=31653, you had collected.\n•\009Travel southeast, back to Stormspire, to coords 44.6, 34.8.\n•\009Turn in the quest to https://www.wowhead.com/npc=20471.",
            date = "2016-01-15T15:22:11-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10855#comments:id=2298510",
        },
    },
