        {
            id = 226625,
            score = 17,
            author = "qhiiyr",
            text = "Don't start the next quest until you have your group ready; Zuluhead comes out and a bunch of archers start shooting at you.",
            date = "2008-01-30T01:10:24-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10858#comments:id=226625",
        },
        {
            id = 47267,
            score = 7,
            author = "31094",
            text = "Very easy to do if you bring a friend who's already done the quest\n\nas long as they still have the key from killing Zuluhed, just bring them with you, let them use the key on karynaku after you have taken the original quest to release her, then just quickly turn in the quest once it is completed and done, took me about 30 seconds once i got to the ledge (gotta love the help of friends)",
            date = "2007-03-06T17:54:30-06:00",
