    [10859] = {
        {
            id = 26833,
            score = 310,
            author = "17534",
            text = "Go stand at 67,41 at the northern entrance of Razaan's Landing and keep dropping the totem on a little hill... worked perfectly for me.",
            date = "2007-01-29T02:09:01-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10859#comments:id=26833",
        },
        {
            id = 26568,
            score = 29,
            author = "16172",
            text = "They are the little pink things flying around... just at the camp entrance and all over. Just put your totem down and dont get to close... then they fly into the totem it's actually kinda cool You dont have to kill anything really to accomplish this quest just get the pink flying things.",
            date = "2007-01-28T18:16:27-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10859#comments:id=26568",
        },
        {
            id = 2587790,
            score = 12,
            author = "Courren",
            text = "the little pink orbs have a spawn point at the southern most entrance of Razaan's landing (65.5, 46.5).\n\nA few mobs to clear and you're good to go.",
            date = "2018-08-04T14:45:24-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10859#comments:id=2587790",
        },
        {
            id = 129738,
            score = 7,
            author = "Rimwalker",
            text = "If you have a flying mount, you can just park on top of one of the pink towers and cast your totem from up there. Quest took like 30 seconds.",
            date = "2007-07-31T09:56:10-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10859#comments:id=129738",
        },
        {
            id = 53890,
            score = 6,
            author = "24732",
            text = "I captured all my purple orbs at around 68,43. They seem to be created by the circular devices on the poles that are generating the purple electricity. The only annoying thing is that after capturing an orb, the totem will disappear, so you have to put in down after each capture (good idea to temporarily put the totem on your quickbar for this)",
            date = "2007-03-19T18:11:53-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10859#comments:id=53890",
        },
    },
    [10860] = {
        {
            id = 186203,
            score = 29,
            author = "100667",
            text = "These can be bought from Xerintha Ravenoak at Evergrove in BE. Limited supply.\nThe crunchy and short ribs recipes, that is.",
            date = "2007-11-17T07:36:43-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10860#comments:id=186203",
        },
        {
            id = 84523,
            score = 28,
            author = "36412",
            text = "UPDATE:\n\nEven though the quest rewards only show the 3g70s, when you turn it in, she gives you all 4 items: (i just did this, so I know)\n\nMok'Nathal Shortribs\nCrunchy Serpent\nRecipe: Mok'Nathal Shortribs\nRecipe: Crunch Serpent\n\nThere is no time limit, its just a poorly written quest reward.",
            date = "2007-05-17T11:22:56-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10860#comments:id=84523",
        },
        {
            id = 23414,
            score = 24,
            author = "14716",
            text = "Kill the Scalewing Serpents, and Daggermaw Lashtail's around 65,58 for these items",
            date = "2007-01-24T01:07:31-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10860#comments:id=23414",
        },
        {
            id = 50534,
            score = 14,
            author = "15213",
            text = "WARNING: If you wait too long to turn in this quest, these rewards DISAPPEAR.  Notice the quest text:\n\n\"I may even teach you how to cook them up for yourself, if you hurry.\"\n\nI kept this in my log for about an hour, and I noticed that the rewards changed from the 2 food and 2 recipes and ~3g to ONLY 3g.\n\nThis is solved easily by just abandoning the quest and picking it up again.  Since the items you need to collect aren't 'quest items', they will not disappear when you abandon the quest.\n\nYou can also collect the items without having the quest, so the easiest thing to do is find the 6 pieces of meat, then go get the quest and turn it in right away.",
            date = "2007-03-13T11:11:13-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10860#comments:id=50534",
        },
        {
            id = 185763,
            score = 12,
            author = "9549",
            text = "The Food and Drink vendor in Evergrove now sells both recipes in a limited quantity.",
            date = "2007-11-16T12:44:49-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10860#comments:id=185763",
        },
    },
    [10861] = {
        {
            id = 17682,
