        {
            id = 399761,
            score = 9,
            author = "Jakobud",
            text = "If you were already in Shattrath City and accepted The Eyes of Skettis (http://www.wowhead.com/?quest=10847), then you cannot get this quest from Rokag (http://www.wowhead.com/?npc=18386).\n\nSimply drop the The Eyes of Skettis (http://www.wowhead.com/?quest=10847) quest.  Then this quest will become available to you.  Then you can pick up The Eyes of Skettis (http://www.wowhead.com/?quest=10847) again once you are back in Shattrath.",
            date = "2008-10-08T00:34:34-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10862#comments:id=399761",
        },
        {
            id = 317833,
            score = 2,
            author = "66152",
            text = "I calculated the Reputation, the Gold, and the Experience you will earn from this whole quest chain from turn-ins (this does not include selling the rewards).\n\n86000 XP\n23 Gold, 64 Silver\n1575 Reputation with Lower City.\n\n(And at 70 you will receive a total of 38 Gold, 23 Silver, 50 Copper if you do not do this chain while leveling)\n\nnot a bad idea to do the whole chain.",
            date = "2008-07-01T23:15:37-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10862#comments:id=317833",
        },
