    [10876] = {
        {
            id = 217088,
            score = 69,
            author = "defektunge",
            text = "The quest \"The Foot of the Citadel\" requires the head of The Hand of Kargath...\n\nI doubt that's a coincidence ;)",
            date = "2008-01-12T04:01:55-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10876#comments:id=217088",
        },
        {
            id = 106147,
            score = 29,
            author = "29281",
            text = "Maybe it was a fluke, but when I tried the quest it was *gasp* FIXED!  Perish the thought, but the mobs were not just standing in the archway like they were in the past.  I actually had to use the banner on the corpse of the 'force commander' (that pats inside the base of the citadel, enter at 48, 50) and then wait for Kargath and his pals to pop.  As you can imagine, this makes it a much harder quest, since he is in an area dense with mobs.\n\nOnce you place the banner on the corpse of the force commander, the mobs will spawn (where they did before, under the archway at 48,50) but they now will run west into the small alcove to wherever the banner and YOU are.  I wiped on this, (since I was trying to solo it and trash was repopping)  and if you wipe on this you have about 60 seconds before Kargath despawns.  So unless you have a soulstone, you won't make it back in time from the graveyard.\n\nI'd suggest 2-3 people, head to 48, 50, clear the small alcove area west of the archway, then pull the force commander back to the fire and kill him there.  This will give you a couple seconds to heal up before Kargath and the two adds run in.  They charge like crazy, but you CAN outrange it.  (30 yards)",
            date = "2007-06-17T18:28:04-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10876#comments:id=106147",
        },
        {
            id = 132794,
            score = 27,
            author = "54182",
            text = "His location is 48, 49 this is a group quest lots of protection",
            date = "2007-08-05T20:06:30-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10876#comments:id=132794",
        },
        {
            id = 21351,
            score = 24,
            author = "dJe781",
            text = "At the moment, if you fail killing Hand of Kargath (elite mob which pops when you activate the banner on Gorax's corpse), it seems that you don't get back the banner. So, you'll have to give up the quest, take it again, then go to kill Gorax one more time.",
            date = "2007-01-18T12:28:38-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10876#comments:id=21351",
        },
        {
            id = 2453222,
            score = 13,
            author = "1730340",
            text = "For someone who is only doing this for Stormshroud chest transmog :\n\nHint: If you have done this quest on your main already, just start a Demon hunter and do the quest with it.\n\nOrder of quests to do on a fresh character:\n\n1. Bonechewer Blood (from Vurtok Axebreaker in Thrallmar)\n2. Apothecary Zelana\n3. Spinebreaker Post\n4. Boiling Blood\n5. Apothecary Antonivich\n6. A Burden of Souls\n7. The Demoniac Scryer\n8. Report to Nazgrel\n9. The Foot of the Citadel (make sure to choose Darkstorm Tunic as reward)",
            date = "2016-12-12T18:55:55-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10876#comments:id=2453222",
        },
    },
    [10877] = {
        {
