        {
            id = 2298869,
            score = 10,
            author = "Aurleis1",
            text = "Video Guide: https://www.youtube.com/watch?v=oOBwADQUnVw\n\n1.  https://www.wowhead.com/quest=10881\n•\009Accept the quest, https://www.wowhead.com/quest=10881, from https://www.wowhead.com/npc=22370 at coords 37.2, 50.6 (Refugee Caravan).\n•\009Travel west, to the Shadow Tomb, to coords 31.1, 52.7.\n•\009Enter the Shadow Tomb, by entering its underground passageways.\n•\009At the first four-way, turn right (east) to coords 32.1, 51.2.\n•\009Loot the https://www.wowhead.com/item=31709 from the https://www.wowhead.com/object=185226.\n•\009Turn around and travel straight ahead (west) to coords 29.7, 51.7.\n•\009Loot the https://www.wowhead.com/item=31710 from the https://www.wowhead.com/object=185225.\n•\009Exit the room and turn left (north), traveling down the stairs to coords 31.2, 46.7.\n•\009Loot the https://www.wowhead.com/item=31708 from the https://www.wowhead.com/object=185224.\n•\009Exit the Shadow Tomb.\n•\009Travel east, to the Refugee Caravan, to coords 37.2, 50.6.\n•\009Turn in the quest to https://www.wowhead.com/npc=22370.",
            date = "2016-01-16T10:20:05-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10881#comments:id=2298869",
        },
    },
