    [10884] = {
        {
            id = 41817,
            score = 55,
            author = "24541",
            text = "It should be stated that the 55-minute countdown does not start until you go through the second door in the Grand Warlock's room.  That is to say, once you kill the Grand Warlock (1st boss), and leave his room to continue onward, you receive a debuff - similar to 45 Baron runs - that shows you how much time you have remaining.",
            date = "2007-02-24T22:59:51-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10884#comments:id=41817",
        },
        {
            id = 32067,
            score = 43,
            author = "19158",
            text = "Heroic mode is pretty tough and there is a 55 minute time limit to save the npcs that are being executed (Must save them to complete the quest). It's done easily after learning the pulls so probably not your first time through on heroic put should be able to do it the 2nd or 3rd try.",
            date = "2007-02-07T06:16:11-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10884#comments:id=32067",
        },
        {
            id = 53882,
            score = 30,
            author = "Izichial",
            text = "When you kill Kargath on heroic, a Shattered Hand Executioner and the prisoners spawn in the small area after Kargath's. This npc drops the Unused Axe of the Executioner. The quest NPC for the 'Imprisoned in the Citadel' also spawns here, being one of the prisoners.",
            date = "2007-03-19T17:56:44-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10884#comments:id=53882",
        },
        {
            id = 229554,
            score = 25,
            author = "107368",
            text = "May be a dumb question but no one else said...If you die do you fail the quest??",
            date = "2008-02-04T19:27:01-06:00",
