    [10896] = {
        {
            id = 22121,
            score = 76,
            author = "dJe781",
            text = "Try to find a Rotting Forest-Rager (http://www.wowhead.com/?npc=22307) which looks like a big walking tree. When it dies, there's *MUCH* more termites spawning than with usual treants.",
            date = "2007-01-20T15:26:46-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10896#comments:id=22121",
        },
        {
            id = 21070,
            score = 43,
            author = "1966",
            text = "Wood mites will spawn from the treants around the edges of the Bone Wastes. They won't always spawn when you kill the treants, but when they do there will be around five or so mites. The mites are very easy to kill; they'll pretty much die in one hit to anything i.e. a hunter's explosive trap.",
            date = "2007-01-17T14:54:05-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10896#comments:id=21070",
        },
        {
            id = 128825,
            score = 36,
            author = "Jereno",
            text = "Hunters have to get the killing blow (as opposed to their pets) in order for the mites to spawn, not be in melee range as previously stated by another posted.",
            date = "2007-07-29T18:27:40-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10896#comments:id=128825",
        },
        {
            id = 99788,
            score = 20,
            author = "Khabal",
            text = "If you are in a group with someone who has already completed this quest, the mites will not come out of the trees.  We tested this a few times by joining and dropping group.\n\nIf the person who has completed this drops group, the mites start appearing; there is no need to abandon the quest and re-take it.\n\nThis happened on 6/6/07.  This was the first time I have done this quest, so I'm not sure if it has always been this way, or if it started recently.",
            date = "2007-06-06T21:14:22-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10896#comments:id=99788",
        },
        {
            id = 1660939,
            score = 13,
            author = "denter2008",
            text = "Any class that has a battle pet of any kind, you must put your pet on passive to get the mites to spawn.",
            date = "2012-04-30T16:39:00-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10896#comments:id=1660939",
        },
    },
    [10898] = {
        {
            id = 60450,
            score = 47,
            author = "20775",
            text = "You can find him around 53,72 to start the quest.  If he's not there then somebody is currently on the quest or failed it.",
