    [10909] = {
        {
            id = 17649,
            score = 54,
            author = "5417",
            text = "Gor'gaz Outpost can be found at coords 45,76.  Just slightly north of the Warp Fields.  There are not a lot of Orcs in the area, though they respawn fast enough, so there will be competition for the spirits.",
            date = "2006-12-20T18:17:41-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10909#comments:id=17649",
        },
        {
            id = 2027343,
            score = 24,
            author = "Endinglife",
            text = "It seems since 6.0.2 was implemented this quest is 'bugged' in a sense where you do about a 1/3 of your normal amount of damage. The quest item mechanics are still the same, but you deal considerably less damage to the enemy.",
            date = "2014-11-10T10:48:45-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10909#comments:id=2027343",
        },
        {
            id = 53959,
            score = 23,
            author = "TegoZanduba",
            text = "Completing this enables The Exorcism of Colonel Jules (http://www.wowhead.com/?quest=10935)",
            date = "2007-03-19T22:07:30-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10909#comments:id=53959",
        },
        {
            id = 53201,
            score = 18,
            author = "qhiiyr",
            text = "The spirits will die on their own if you avoid fighting them for too long, and you won't get credit for the kill. Found this out by polymorph-chaining to regen mana, and the spirit eventually just dropped dead.\n\nAlso, don't be distracted by the fact that you can click on the Anchorite Relics. Despite Blizzard's mistake of making your cursor change to the gear icon on them, clicking on the relics doesn't do anything.\n\nAnd to reinforce what Gandalug said, only the berserkers will release spirits upon death.",
            date = "2007-03-18T14:14:46-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10909#comments:id=53201",
        },
        {
            id = 21179,
            score = 9,
            author = "5027",
            text = "It may have been an error on my part, but only the Shattered Hand Beserkers would reveal fel spirits when they died. Not the other kind. So keep that in mind if you want to move to a less crowded area.",
            date = "2007-01-17T22:22:48-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10909#comments:id=21179",
        },
    },
    [10910] = {
        {
