            score = 23,
            author = "12462",
            text = "Death's Door is a cave located at 65,70",
            date = "2007-01-24T20:35:39-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10910#comments:id=24010",
        },
        {
            id = 41614,
            score = 10,
            author = "Artio",
            text = "Actually, the flare can be used in the entire region after the tunnel.\nSo don't run back to the tunnel. The druid you call gives you a quest to collect canonballs. I ended up at the 2nd Fell canon you needed for the next part of the quest chain. So no repops because of running to the tunnel.",
            date = "2007-02-24T13:59:50-06:00",
