    [10922] = {
        {
            id = 57144,
            score = 131,
            author = "37091",
            text = "I'll echo that this quest is easily soloable.  The five dwarf NPCs can easily handle any roaming mobs, and the boss, with your help alone.  All you have to do is stay in the middle of the circle (so that they get aggro before you) and help with anything they go after.\n\nThe dialogue from the quest is priceless, though, and worth transcribing.\n\nChief Archaeologist Letoll says: Aright, listen up! Form a circle around me and move out!\nChief Archaeologist Letoll says: Aright, , just keep us safe from harm while we work. We'll pay you when we return.\nChief Archaeologist Letoll says: The dig site is just north of here.\n(The team moves out to the dig site.)\nChief Archaeologist Letoll says: We're here! Start diggin'!\n(The team spreads out and starts digging.)\nChief Archaeologist Letoll says: I think there's somethin' buried here, beneath the sand!\nChief Archaeologist Letoll says: Almost got it!\nChief Archaeologist Letoll says: By Brann's brittle bananas! What is it?! It... It looks like a drum.\nExplorer's League Researcher: Wow... a drum.\nExplorer's League Researcher: This discovery will surely rock the foundation of modern archaeology.\nExplorer's League Researcher: Yea, great. Can we leave now? This desert is giving me hives.\nChief Archaeologist Letoll says: Have ye gone mad? You expect me to leave behind a drum without first beatin' on it? Not this son of Ironforge! No sir!\nExplorer's League Researcher: This reminds me of that one time where you made us search Silithus for evidence of sand gnomes.\nExplorer's League Researcher: Or that time when you told us that you'd discovered the cure for the plague of the 20th century. What is that even? 20th century?\nExplorer's League Researcher: I don't think it can top the one time where he told us that he'd heard that Arthas's \"cousin's\" skeleton was frozen beneath a glacier in Winterspring. I'll never forgive you for that one, Letoll. I mean honestly... Arthas's cousin?\nExplorer's League Researcher: Explorer's League Researcher: I dunno. It can't possibly beat the time he tried to convince us that we're all actually a figment of some being's imagination and that they only use us for their own personal amusement. That went over well during dinner with the family.\nChief Archaeologist Letoll says: Shut yer yaps! I'm gonna bang on this drum and that's that!\n\nChief Archaeologist Letoll says: IN YOUR FACE! I told you there was somethin' here!\nChief Archaeologist Letoll says: Don't just stand there! Help him out!\n\nChief Archaeologist Letoll picks up the drum.\nChief Archaeologist Letoll says: You've been a tremendous help, ! Let's get out of here before more of those things show up! I'll let Dwarfowitz know you did the job asked of ya' admirably.",
            date = "2007-03-25T19:41:13-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10922#comments:id=57144",
        },
        {
            id = 198402,
            score = 57,
            author = "59513",
            text = "Am I the only one to see this?\n\nLetoll - Leto II - God Emperor of Dune.",
            date = "2007-12-09T07:21:56-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10922#comments:id=198402",
        },
        {
            id = 1884798,
            score = 24,
            author = "willowsauce",
            text = "I love the dialogue on this quest",
            date = "2013-08-07T16:03:02-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10922#comments:id=1884798",
        },
        {
            id = 957124,
            score = 15,
            author = "496052",
            text = "Anyone seen that these helpers carry a shovel too instead of only a pickaxe? When mining they just smack their shovels on the hard ground. Waste of good equipment, Letoll.",
            date = "2010-01-26T09:01:22-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10922#comments:id=957124",
        },
        {
            id = 221983,
            score = 6,
            author = "120581",
            text = "I saw at least 2 movie references there. 1 from The Mummy (I think there's somethin' buried here, beneath the sand!) and 1 from Medicine Man (Or that time when you told us that you'd discovered the cure for the plague of the 20th century.)\n\nI love how Blizzard adds this stuff. It's fun to find.",
            date = "2008-01-21T22:47:42-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10922#comments:id=221983",
        },
    },
    [10923] = {
        {
            id = 22179,
            score = 50,
            author = "4776",
            text = "Coords: 48, 67",
            date = "2007-01-20T17:24:38-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10923#comments:id=22179",
        },
        {
            id = 48047,
            score = 25,
            author = "29008",
            text = "Easily soloed a 65 Feral Druid\n\nHeres how I did it:\nAll I did was start his little summoning sequence, then when he landed, switched into bear and played it from there. Switched out and healed when I needed to (one time) and also a frenzied regeneration. Ended up with about 90% hp left and 60% mana. I dont't know about other classes but a druid can easy solo this. Let me add in that this mob is snarable and stunable.",
            date = "2007-03-08T04:15:32-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10923#comments:id=48047",
        },
        {
            id = 26384,
            score = 18,
            author = "17237",
            text = "When you summon him it takes all of the doomskulls so be sure you are ready or else you will have to farm them again. Also a lot of people dont know what these skulls are, and you don't have to have the quest to get them to drop. Usually you can ask around and get 20.\n\nI soloed this as a LvL 65 Warlock with Warlords. I am Affliction with imp HS and imp Fel Armor. I sacced the void and and dotted him up then just cast shadow bolts. I had to pot once, use a healstone that healed for something around 1700 and also Death Coil for the healing. It was a VERY close fight, but I didn't get a lot of nightfall procs so I would imagine a buffed up hunter / mage could do this.\n\nA word of warning - there are guys around the summoning portal, if you kill them then wait too long (1 minute) and summon the dragon, they will spawn before the dragon lands and cause problems. As a warlock I just shadow warded through all their damage when they did because all they do is cast Shadow Bolts. Also Teribus goes nutso is you don't get aggro on him. I have seen him wonder from the mound and go pretty far south.",
            date = "2007-01-28T12:59:09-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10923#comments:id=26384",
        },
        {
            id = 33930,
            score = 18,
            author = "Vlad",
            text = "A movie clip of the kill at the location 48,66\nhttp://media.putfile.com/Teribus-the-Cursed-kill\nSolo able (for sure)! :P",
            date = "2007-02-11T05:05:54-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10923#comments:id=33930",
        },
        {
            id = 113396,
            score = 12,
            author = "26858",
            text = "Dont know when changed, but the doom skulls are no longer tradeable.... :(",
            date = "2007-06-30T13:51:03-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10923#comments:id=113396",
        },
    },
    [10924] = {
        {
            id = 25555,
            score = 95,
            author = "ishvonrask",
            text = "Don't forget to summon Zeppit so he can collect the blood!",
            date = "2007-01-27T07:39:27-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10924#comments:id=25555",
        },
        {
            id = 383042,
            score = 51,
            author = "106847",
            text = "No one tells the CORRECT way to collect the vial.\nAs mentioned above, you need to summon the imp first.\nAND YOU NEED TO BE HIT BY THE WARP CHASER.\nThen you will get a 100% drop rate.\nYou never realize it if you are a melee class. You will think its 100% drop rate.\nYou will get frustrated if you are a ranged dps who kills them without being single hit. You get 0% drop rate unless you get charged by them.\nMy hunter killed 20+ and got none. I made a lot of experiment to find it out after cursing Blizz for a couple of minutes. :-P",
            date = "2008-09-21T08:04:45-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10924#comments:id=383042",
        },
        {
            id = 43165,
            score = 21,
            author = "25495",
            text = "And for those who are long range, you will have to get close to the Warp Chases for the imp to collect the blood.",
            date = "2007-02-27T03:55:04-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10924#comments:id=43165",
        },
        {
            id = 118326,
            score = 11,
            author = "68792",
            text = "If some are stressing with the drop rate, It's not the rate that messes with you!\nYou actually need to stand on the corpse, for about 2 secs, and the imp will take the blood!",
            date = "2007-07-09T22:23:05-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10924#comments:id=118326",
        },
        {
            id = 2198116,
            score = 10,
            author = "xedd",
            text = "What's the point of this quest?\nIt doesn't unlock any other quest.\nI got no quest sending me to Sab'oth or to Cosmowrench\nI got no other quest in Cosmowrench either.\nThis quest is quite unusual, it's not like the rest of the WoW quests, which are linked to other quests in a way or other.\n\nIs it a reference to something like a TV show or a book or smth?",
            date = "2015-06-23T20:07:43-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10924#comments:id=2198116",
        },
    },
