    [10929] = {
        {
            id = 24324,
            score = 157,
            author = "15689",
            text = "Easily compelted:\n\nGo to the edge of Refugee Caravan and The Bone Wastes (any side). Keep NPCs to your back and use the fumper. If gnome spawns, run back towards NPCs, they will kill him.\n\nWhen Sifter spawns fight him until he goes underground. He will always reappear behind you, which should be closer to NPCs. Keep your back to NPCs at all times and he'll quickly be in the Caravan camp where NPCs will finish him off.",
            date = "2007-01-25T10:12:13-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10929#comments:id=24324",
        },
        {
            id = 212975,
            score = 31,
            author = "45703",
            text = "Possible reference:\nFumping sounds suspiciously like thumping, a method used to distract/lure sandworms to a given location (the area where you used the thumper (http://en.wikipedia.org/wiki/Thumper_%28Dune%29#T)) in the Dune (http://en.wikipedia.org/wiki/Dune_%28novel%29) universe.",
            date = "2008-01-04T20:42:50-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10929#comments:id=212975",
        },
        {
            id = 799938,
            score = 29,
            author = "85313",
            text = "The Sand gnomes are mentioned in the previous quest...guess they really DO exist!",
            date = "2009-08-05T21:57:04-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10929#comments:id=799938",
        },
        {
            id = 22134,
            score = 19,
            author = "10807",
            text = "48,73 area, drop rate is 100% :) .. Drum either spawns a gnome or the Sifter u need. Sifter's do around 900-1000 poison dmg.",
            date = "2007-01-20T16:04:12-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10929#comments:id=22134",
        },
