    [10930] = {
        {
            id = 87162,
            score = 120,
            author = "29640",
            text = "Easiest Method Ever, Kill him in 1 shot. (Sound impossible? Its not =) )\n\nYou may need a timer mod, he will despawn 3 minutes after he is spawned regardless of his current health or if he is in combat.\n\nSummon him, wait 2 minutes 50 seconds, shoot him.\n\nSurvive the next 10 seconds and he dies and is lootable if you have him tagged.",
            date = "2007-05-22T01:47:00-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10930#comments:id=87162",
        },
        {
            id = 19051,
            score = 96,
            author = "11009",
            text = "Very nice reference to Frank Herbert's Dune series: All 3 names refer to main chars...",
            date = "2007-01-02T03:45:27-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10930#comments:id=19051",
        },
        {
            id = 23499,
            score = 62,
            author = "7524",
            text = "Look around 44,77 for the Kodo like things u need to kill to summon.",
            date = "2007-01-24T04:50:27-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10930#comments:id=23499",
        },
        {
            id = 75738,
            score = 62,
            author = "13494",
            text = "Was able to easily solo this with a 68 Hunter and I imagine it can be done with any other ranged class as well.\n\nThe trick is to use the east tunnel that leads into the Auchindoun.  Kill the clefthoof near the tunnel so you don't have to travel far to get there once the worm spawns.  Once it spawns, you want to run down the ramp and get positioned so that you can quickly strafe behind the wall out of line of sight once he begins casting his ranged poison attack.\n\nIf you are positioned correctly, you will not take any damage whatsoever because he can not pop up from under you if you are deep enough inside the tunnel.\n\nYou get a few seconds in between each ranged poison attack to do some damage.  It took me about a minute to finish him off using this method.",
            date = "2007-04-30T20:42:21-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10930#comments:id=75738",
        },
        {
            id = 21130,
            score = 53,
            author = "10440",
            text = "Using the drums either gets 3 sand gnomes, 3 of the mature worms, or the elite worm.  It took us about twenty summons to get the big worm, though I don't know if that's regular or not. Two things to take note of. Make sure you stay at full hp for summons.  Our T2 paladin got 1-shot by three 1.3k poison bolts since he wasn't at 100%.  Secondly, assign one person to summon.  If two people place the drums at the exact same time, bad things will happen (we got a spawn of six worms).",
            date = "2007-01-17T19:22:46-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10930#comments:id=21130",
        },
    },
    [10935] = {
        {
            id = 22418,
            score = 49,
            author = "7036",
            text = "Anchorite Barada is in the room next to the quest giver.",
            date = "2007-01-21T14:17:39-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10935#comments:id=22418",
        },
        {
            id = 383690,
            score = 48,
            author = "gpdoyon",
            text = "They KEY here is to talk to Colonel Jules, the guy laying in the bed, right after the exorcism! I must have done this silly quest four times before everything I read here made sense.",
            date = "2008-09-21T19:49:26-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10935#comments:id=383690",
        },
        {
            id = 53960,
            score = 30,
            author = "TegoZanduba",
            text = "I loved this quest on my Paladin.\n\nI just kept consecrating the ground and quoting from The Exorcist (http://us.imdb.com/title/tt0070047/): \"The Power of /The Light/ Compels You\"",
            date = "2007-03-19T22:10:56-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10935#comments:id=53960",
        },
        {
            id = 21244,
            score = 29,
            author = "11299",
            text = "The Ritual Prayer Beads which you have to use here say \"target Anchorite Barada or the fiends released during the exorcism\".\n\nWhen you target iti at Barada, the beads heal him a bit. It's better to just target the fiends, it'll banish them from the room. Keep in mind the beads have a cooldown :)",
            date = "2007-01-18T05:09:30-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10935#comments:id=21244",
        },
        {
            id = 32155,
            score = 29,
            author = "Amethyst",
            text = "There are a set of pre-requisite quests to this chain, starting with:\nhttp://www.wowhead.com/?quest=10484",
            date = "2007-02-07T09:38:14-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10935#comments:id=32155",
        },
    },
    [10936] = {
        {
            id = 136145,
            score = 4,
            author = "Oktex",
            text = "Enter the big castle in HH, the cords for the entrance are 56,65.\nWhen you are going in, take first turn left, right, right again, then left and up for the stairs, then left and right, then you finally are in the room where you can end the quest.\n\nIf that was hard to read and understand I can say that he stands upstairs in the castle, you have to go up for the stairs.\n\nForce Commander Danath Trollbane stands in cords 57,67.",
            date = "2007-08-11T22:24:22-05:00",
            sourceUrl = "https://www.wowhead.com/quest=10936#comments:id=136145",
        },
        {
