            text = "57,67 - coords for the commander",
            date = "2007-01-28T14:12:01-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10936#comments:id=26435",
        },
        {
            id = 2285843,
            score = 1,
            author = "Aurleis1",
            text = "Video Guide: https://www.youtube.com/watch?v=msUag7C8xiM\n\n1.  https://www.wowhead.com/quest=10936\n•\009Accept https://www.wowhead.com/quest=10936 from https://www.wowhead.com/npc=22430 at coords 54.2, 63.6 (Upstairs of Honor Hold Inn).\n•\009Exit the Honor Hold Inn, travel southeast, and enter Honor Hold Barracks at coords 56.3, 65.9.\n•\009Go upstairs and turn in the quest to https://www.wowhead.com/npc=16819 at coords 56.6, 66.6.",
            date = "2015-12-09T20:21:16-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10936#comments:id=2285843",
        },
    },
    [10937] = {
        {
            id = 21128,
            score = 34,
            author = "11863",
            text = "I found out how to get it! It's the [Cursed Talisman] Quest line that you get at Expedition Point. It starts with the quest Ill Omens and goes up to Drill the Drillmaster. To get to him, you need to jump off the bridge that leads to the meeting stone, he's on the ground level where the Orcs are (48,55). Make sure you check before you cross the bridge that leads to the meeting stone. At the starting point of the bridge, jump down on to glory road and he is at the end facing west. Be sure to get some help as he's a very tough elite to solo.\n\nGood hunting!",
            date = "2007-01-17T19:08:54-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10937#comments:id=21128",
        },
        {
            id = 21031,
            score = 24,
            author = "12160",
            text = "He's underneath Hellfire Ramparts, lvl 62 elite.  Whirlwinds, but that's about all.  Did it with a group of 3.",
            date = "2007-01-17T11:40:16-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10937#comments:id=21031",
        },
        {
            id = 21063,
            score = 18,
            author = "kadaan",
            text = "Heading west down the path of glory, I found him at the camp inside the walls on the left. He was easy to solo as a 60 frost mage. Slowable and rootable with a decent amount of hit points.",
            date = "2007-01-17T14:29:33-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10937#comments:id=21063",
        },
        {
            id = 21104,
