            date = "2007-01-17T17:16:32-06:00",
            sourceUrl = "https://www.wowhead.com/quest=10937#comments:id=21104",
        },
        {
            id = 1950207,
            score = 14,
            author = "wowheadizmydaddy",
            text = "Quests to unlock this quest, in order\n\nKnow Your Enemy\nFel Orc Scavangers\nIll Omens\n\nCursed Talismans\nWarlord of the Bleeding Hollow\nReturn to Honor Hold\n\nDigging for Prayer Beads & Fel Spirits\nExorcism of Colonel Jules\nTrollbane is Looking For You (oh sh*t)\n\nDrill the Drillmaster",
            date = "2014-03-11T21:01:23-05:00",
