        {
            id = 2339640,
            score = 16,
            author = "Aldristavan",
            text = "After Supremus, go directly east until you reach the platform with the 4 Seers (vendors). Do NOT kill Shade of Akama! I found out the hard way that the *next* quest in the chain is to kill the Shade of Akama, which you can't do if you've already killed him. 0/10, Blizz.",
            date = "2016-06-12T18:21:54-05:00",
