            score = 1,
            author = "303898",
            text = "Quest turn-in *WARNING SPOILERS*:\n\nNazgrel (http://www.wowhead.com/?npc=3230)\n\nFor the first time - in as long as I can remember - there is silence.\n\nThis defeat is not only a blow to Illidan, .  The Legion too reels... A pit lord commander has been defeated.  The siege of Hellfire Citadel now holds no purpose for the Burning Legion.  All of their efforts will undoubtedly be turned upon the Black Temple.\n\nRedemption comes for Illidan... and soon.",
            date = "2010-04-04T06:52:54-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11003#comments:id=1012137",
        },
        {
            id = 140885,
            score = -1,
            author = "7075",
            text = "Can anyone confirm is this NOT repeatable, like the Onyxia head?",
            date = "2007-08-20T00:59:10-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11003#comments:id=140885",
        },
        {
            id = 141796,
            score = -1,
            author = "61287",
            text = "Is the head lootable by the entire raid or can only one person loot it? Sounds like only one person can loot it but I want to confirm that.",
            date = "2007-08-21T16:14:35-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11003#comments:id=141796",
        },
    },
    [11004] = {
        {
            id = 88099,
            score = 17,
            author = "54494",
            text = "Leads to : http://www.wowhead.com/?quest=11005 (Secrets of the Shadow Preists) from Sky Commander Adaris",
            date = "2007-05-23T06:31:07-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11004#comments:id=88099",
        },
        {
            id = 1021382,
            score = 15,
            author = "350413",
            text = "Does not count towards the Terror of Terrokar achievement.",
            date = "2010-04-17T18:58:49-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11004#comments:id=1021382",
        },
        {
            id = 144848,
            score = 14,
            author = "73254",
            text = "They drop off any arakoa. Any. It doesn't have to be soulcallers or anything else, just kill whatever you see because there's most likely a few other players doing the same quest, killing the mobs you need. I killed 12 and got my 6, the drop rate isn't that bad, but as with any drop quest, there is the potential for badluck.",
            date = "2007-08-27T12:53:38-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11004#comments:id=144848",
        },
        {
            id = 159088,
            score = 9,
            author = "jamesisgreat",
            text = "You now get 150 rep for handing this in rather than 75, since patch 2.2.",
            date = "2007-09-26T23:47:07-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11004#comments:id=159088",
        },
        {
            id = 665948,
            score = 4,
            author = "abnorml",
            text = "As a warlock with talents in Improved Shadow Bolt (http://www.wowhead.com/?spell=17803#comments) it will look like it is proc'd because it shares the same icon as the spell (http://www.wowhead.com/?spell=47740) cast on you to complete this quest. Not a huge deal, just an FYI to my lock buddies out there.",
            date = "2009-04-04T18:47:00-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11004#comments:id=665948",
        },
    },
    [11005] = {
        {
            id = 87717,
            score = 201,
            author = "SaltLick",
            text = "Ishaal 68,78  up top in the tree\n\nZellek  69, 74 up top in the tree\n\nSkizzik 69, 82  in the hut\n\nFor this quest you have 15 minutes to do it before the buff that allows you to see them wears off.  They are all surrounded by a few guys but everything is easily soloable.",
            date = "2007-05-22T21:41:46-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11005#comments:id=87717",
        },
        {
            id = 87803,
            score = 41,
            author = "6660",
            text = "If you run out of time you'll need need another elixir from Serevin, who will require 6 more Shadow Dust to make it.",
            date = "2007-05-22T23:27:05-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11005#comments:id=87803",
        },
        {
            id = 91079,
            score = 39,
            author = "19253",
            text = "As you're doing this quest you will pick up Ishaal's Almanac which gives you another quest http://www.wowhead.com/?quest=11021",
            date = "2007-05-26T14:11:20-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11005#comments:id=91079",
        },
        {
            id = 105410,
            score = 36,
            author = "13800",
            text = "And a good hint is to NOT drink the pot at the location of where the Talonpriests are supposed to be. :P\nNoobish me did that and instantly had 5 of High Priests on me.",
            date = "2007-06-16T11:12:52-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11005#comments:id=105410",
        },
        {
            id = 90278,
            score = 25,
            author = "55140",
            text = "As a protection Warrior this was quite hard.  The first two priests, Ishaal and Zellek were not too bad but Skizzik proved to be a royal pain in the behind! :-)\n\nDue to all the other \"hidden\" mobs getting to him was fairly difficult because of their large aggro range, however I have found a good technique now:\n\nOnly use the Elixir of Shadow when you are inside the hut that he occupies (once you have killed the normal mob inside first).  This means you won't pull any other mobs to you and you can kill him with ease.\n\n:-)",
            date = "2007-05-25T13:09:00-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11005#comments:id=90278",
        },
    },
    [11006] = {
        {
            id = 159441,
            score = 26,
            author = "59863",
            text = "Awards 150 reputation with Sha'tari Skyguard as of patch 2.2",
            date = "2007-09-27T14:27:11-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11006#comments:id=159441",
        },
        {
            id = 1508429,
            score = 4,
            author = "cmgdeath",
            text = "as of 4.2.2 and being human (+10 % rep gain) and with the guild perk \"Mr.Popularity\" (further 10% rep gain) = 20% rep gain, i get 180 rep each time i hand in this quest. but not sure if those come into the equation or if its 180 rep gain for everyone",
            date = "2011-09-01T21:31:55-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11006#comments:id=1508429",
        },
        {
            id = 194552,
            score = 2,
            author = "20383",
            text = "Now what do you do with these Elixirs? Go off and kill the same 4 mobs repeatedly just like the quest leading to it? Or is it just a dumb reward for turning in the dust for rep?\n\nPretty much what i'm asking in plain terms:\nWhat purpose do the elixirs have after doing the original quest?",
            date = "2007-12-01T18:20:52-06:00",
            sourceUrl = "https://www.wowhead.com/quest=11006#comments:id=194552",
        },
        {
            id = 227423,
            score = 1,
            author = "Ormeon",
            text = "You must know if you are using the method of \"dots\" to get Reputation, that you ALSO get reputation for killing the mobs. so if you get 1560 dusts, you have too much already, because the reputation from killing guys is 5-10. you need about 1300 dusts, when you also kill 1300 mobs. and sometimes they don't even drop de dusts, so it comes to a total of:\n\n1200 Shadow Dust,\n1400 Skettis Mobs.",
            date = "2008-01-31T14:53:44-06:00",
            sourceUrl = "https://www.wowhead.com/quest=11006#comments:id=227423",
        },
        {
            id = 643367,
            score = 1,
            author = "265487",
            text = "Never leave the Skettis area without at least one turn in, it saves a hell of a lot of time when it comes to grinding them..",
            date = "2009-03-15T15:02:30-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11006#comments:id=643367",
        },
    },
    [11007] = {
        {
            id = 106297,
            score = 55,
            author = "esoterikpunk",
            text = "The item that begins this quest drops from Kael'thas.\n\nChoose your reward from:\nThe Sun King's Talisman http://www.wowhead.com/?item=30015\nThe Darkener's Grasp http://www.wowhead.com/?item=30007\nLord Sanguinar's Claim http://www.wowhead.com/?item=30018\nTelonicus's Pendant of Mayhem http://www.wowhead.com/?item=30017",
            date = "2007-06-18T02:03:51-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11007#comments:id=106297",
        },
        {
            id = 190049,
            score = 21,
            author = "60096",
            text = "Usually in any major instance there's an endboss drop starting a quest, which confirms the Boss' lore status, such as:  http://www.wowhead.com/?item=21221\nhttp://www.wowhead.com/?item=22520\nor the Verdant Sphere we're curenly discussing.\n\nSo for example the Eye of C'thun confirms C'thun's demise, while The Phylactery of Kel'Thuzad  or the Verdant Sphere confirm Kel and Kael aren't dead.\n\nI'm sure Blizzard will implement a similar item for Kil'jaeden to confirm his lore status.",
            date = "2007-11-23T17:17:23-06:00",
            sourceUrl = "https://www.wowhead.com/quest=11007#comments:id=190049",
        },
        {
            id = 123093,
            score = 20,
            author = "60087",
            text = "http://www.wowhead.com/?spell=39953\n\nThat's the buff everyone in Shattrath gets when the quest is completed.",
            date = "2007-07-19T01:40:52-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11007#comments:id=123093",
        },
        {
            id = 204921,
            score = 14,
            author = "60096",
            text = "Newest info on the Sunwell storyline zone and both instances, released yesterday(thanks to wowinsider and worldofraids).\n\n* Sunwell Isle is a new zone, north of Silvermoon City\n\n* The 5-man wing of the instances is called Magister's Terrace featuring normal and heroic difficulty\n\n* The raid wing is called Sunwell Plateau, players can fight 6 raidbosses here and the one of the main stories of Burning Crusade continues here\n\n* Outside the instances there will be lots of quests (daily quests too), wrapping up the story of Tempest Keep\n\n* The questhub of the zone will be interactive, as players complete quests, the activity in the town will increase more and more, eventually growing into a big town, similar to how Silithus prepared for the Qiraji war, on a smaller scale though\n\n* The quests and instances introduce a new faction called \"Shattered Sun Offensive\", the Aldors and Scryers unite under this name to stop Kael'thas from summoning Kil'Jaeden (upd)\n\n* One of the bosses in the Magister's Terrace will be Kael'thas, whose story continues the Verdant Sphere quest. He'll have a large green crystal attached to his chest ^^\n\n* Kil'jaeden will be featured in the 25-man instance, and the EPICness of the fight will be on par with Illidan's. There are 5 more bosses: Brutalicus, a pit lord; Kalecgos, the blue dragon from the Sunwell Trilogy (who is enslaved by Kil'jaeden); a Fel Dragon; female Eredar twins; and a Dark Naaru!\n\n* The raidinstance is designed for players with Tier 6 equipment and it will be slightly more difficulty than Black Temple (upd)\n\n* There won't be a Tier 7 raidset, however there are sets in the loottables (upd)\n\n* The raidinstance doesn't have an attunement requirement, but players of the entire realm must complete a certain amount of daily quests on the Sunwell Isle, to unlock the last 3 bosses (upd)",
            date = "2007-12-21T07:23:16-06:00",
            sourceUrl = "https://www.wowhead.com/quest=11007#comments:id=204921",
        },
        {
            id = 1857900,
            score = 10,
            author = "Aranx",
            text = "As a Blood Elf, A'dal ends this quest text with\n\n\"Rest. Your brothers and sisters will retake Tempest Keep now.\"\n\nDon't know if this is for Blood Elves only, but if so, that's pretty awesome.",
            date = "2013-05-25T19:20:03-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11007#comments:id=1857900",
        },
    },
    [11008] = {
        {
            id = 111998,
            score = 139,
            author = "29281",
            text = "You need to complete the mini-chain \"Threat from Above\" ( http://www.wowhead.com/?quest=11096 ) before you can do this quest.",
            date = "2007-06-27T18:12:07-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11008#comments:id=111998",
        },
        {
            id = 87758,
            score = 83,
            author = "gamepin126",
            text = "While you're flying on your mount, use the Blasting Charge on the wiggling eggs (they look like spider eggs) on the tops of the towers.",
            date = "2007-05-22T22:32:07-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11008#comments:id=87758",
        },
        {
            id = 87824,
            score = 50,
            author = "21092",
            text = "Watch out for the birds flying around, they can hamstring you, and if they do enough damage they can knock you off your mount, where you fall to almost certain death.",
            date = "2007-05-22T23:57:06-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11008#comments:id=87824",
        },
        {
            id = 88153,
            score = 27,
            author = "21092",
            text = "This is also one of the Skettis Daily Quests, which you can repeat on a daily basis. You can do 10 Daily Quests a day. Not only do you get rep every time you do this quest, you get gold as well, so it's a easy little money maker each day.\n\nAlso, when bombing the eggs, besides the birds you also need to worry about some of the Arakkoa patting around the eggs, as they can cast shadowbolts so try not to get within their range.",
            date = "2007-05-23T07:41:02-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11008#comments:id=88153",
        },
        {
            id = 89400,
            score = 25,
            author = "Carkasjak",
            text = "Flight form can't be dismounted by the birds.\nPretty neat advantage for us druids :]",
            date = "2007-05-24T10:02:17-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11008#comments:id=89400",
        },
    },
    [11009] = {
        {
            id = 107445,
            score = 23,
            author = "47168",
            text = "on a slightly sillier note, once you're neutral with the ogres, if you do certain emotes with them, they will do some in response. I know at least the bladespire ogres outside of Gruul's Lair will /Dance with you and laugh at your /Silly.",
            date = "2007-06-19T19:54:49-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11009#comments:id=107445",
        },
        {
            id = 1152015,
            score = 13,
            author = "Hallrik",
            text = "I don't think people notice that Ogri'la is a reference to Shang'rila both considered a heaven, or haven-like place",
            date = "2010-10-24T11:11:21-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11009#comments:id=1152015",
        },
        {
            id = 87748,
