    [11020] = {
        {
            id = 87543,
            score = 165,
            author = "54274",
            text = "First you have to kill any sort of wildlife in Shadowmoon(boars, diemetradons, etc) to loot the Fel Glands that drop.  Drop rate for me was about 1/3.\n\nOnce you have 12, go back to Netherwing Ledge and combine it with the mutton the quest giver gives you near any of the Peon camps.  Watch out for the 72 elites that patrol around the area because they hurt.",
            date = "2007-05-22T16:17:48-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11020#comments:id=87543",
        },
        {
            id = 97541,
            score = 62,
            author = "EvilDeathCrab",
            text = "Some useful tips to avoid bugging:\n- Don't drop food by the ones that are standing in a big clump and not mining (you don't see the picks moving).\n- Make sure that there's at least two or three peons in each camp, so don't put one by a solitary peon because that's probably someone who did the booterang quest.\n- Drop the meat an equal distance away from all peons (see note below)\n\nNote: I'm pretty sure the \"bug\" lies in the position of the little haunch of meat relative to the peons.  The \"event\" that occurs to give you credit for the camp is only started when ALL the peons in that camp (two or three of them) have run up to the mutton.  If you place the mutton to close to one of the peons in the group, all the other peons will run towards the mutton except for the one that's already \"close enough.\"  Unfortunately, it seems that the \"I'm close enough\" check doesn't trigger the \"I'm at the meat\" check, and that peon never moves.  The other two peons will typically clump on top of that peon, creating the \"bugged groups\" that you often see.\n\nSolution:  Make sure there's a decent gap between any given peon and the mutton you drop.  You can stand a few yards away and still get them all to run.  Just don't be hasty and drop mutton on top of a peon, because that will probably result in the bug.\n\nI've done a little testing, but if anyone feels like wasting some glands to test this, feel free :D",
            date = "2007-06-03T17:20:44-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11020#comments:id=97541",
        },
        {
            id = 90667,
            score = 61,
            author = "13177",
            text = "You find Felfire Diemetradons wish drops Fel Glands at 47,60. Kinda good place.",
            date = "2007-05-26T00:20:51-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11020#comments:id=90667",
        },
        {
            id = 2363182,
            score = 43,
            author = "Frostaphim",
            text = "Really good alternative spot to farm those feels like 100% droprate from them. Killed 12 and got 12 fel glands\n\n/way 59 42",
            date = "2016-08-08T11:24:40-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11020#comments:id=2363182",
        },
        {
            id = 146412,
            score = 21,
            author = "71441",
            text = "\"A Slow Death\" describes what it feels like to do this quest. After spending way too much time farming trash mobs on the mainland of SMV (which do not drop crystals or eggs) you get to look forward to getting a 11/12 completion when one camp bugs out on you. I avoid the camps that look buged, and still have at least one bug on me more often then not. The least they could do to make up for poor programming is allow us to pick up 13 or 14 just to be safe. But nope.\n\nI'm with the other people. This quest is a collosal waste of time. The worst daily quest I've done so far.",
            date = "2007-08-30T04:56:50-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11020#comments:id=146412",
        },
    },
    [11021] = {
        {
