    [11022] = {
        {
            id = 147476,
            score = 29,
            author = "34072",
            text = "Part of the quest chain to open up the Ogri'la daily quests.  You have to kill five different elite Sons of Gruul.  They are VERY tough and you must have a proper 5-man party to handle them (Tank, Healer, 3 DPS).  You might even want to bring along some extra people that can help out of party.\n\nQuest Chain:\nSpeak with the Ogre (http://www.wowhead.com/?quest=10984)\n... Mog'dorg the Wizened (http://www.wowhead.com/?quest=10983)\n...... Grulloc Has Two Skulls (http://www.wowhead.com/?quest=10995) (Grulloc)\n...... Maggoc's Treasure Chest (http://www.wowhead.com/?quest=10996) (Maggoc)\n...... Even Gronn Have Standards (http://www.wowhead.com/?quest=10997) (Slaag)\n......... Grim(oire) Business (http://www.wowhead.com/?quest=10998) (Vim'gol the Vile)\n............ Into the Soulgrinder (http://www.wowhead.com/?quest=11000) (Skulloc Soulgrinder)\n.............. Speak with Mog'dorg (http://www.wowhead.com/?quest=11022)",
            date = "2007-09-01T05:10:30-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11022#comments:id=147476",
        },
        {
            id = 3214097,
            score = 27,
            author = "Beace",
            text = "Couple of notes, if you are trying to do this for quest completionist purposes.\n\n1) Wowhead has it noted as a Night Elf quest. This is incorrect. I was able to do it on my Lightforged Draenei, and I'm pretty sure it's available for any race.\n\n2) It is a breadcrumb and acts like all breadcrumbs do. You want to make sure you complete https://www.wowhead.com/quest=11000, but not the followup. Instead go down the tower and move along the Supplicants. This breadcrumb quest did not show up immediately for some reason, but after about a minute I found it: https://i.gyazo.com/985b40f95ed78da993949a4b8633443f.jpg",
            date = "2020-06-24T10:57:23-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11022#comments:id=3214097",
        },
        {
            id = 225194,
            score = 15,
            author = "95606",
            text = "They respond to emotes when you turn king/queen!\nSo far they respond to /kiss, /point, /dance, /laugh and /roar.\nReally amusing :D",
            date = "2008-01-27T16:37:11-06:00",
            sourceUrl = "https://www.wowhead.com/quest=11022#comments:id=225194",
        },
        {
            id = 92073,
            score = 13,
            author = "53826",
            text = "The quest giver is at Shattrah, he sends you to Mog'Dorg who gives you the 3 first pre-req\n\nPre-req are:\nhttp://www.wowhead.com/?quest=10995\nhttp://www.wowhead.com/?quest=10997\nhttp://www.wowhead.com/?quest=10996\n\nalso the f/u which are:\n\nhttp://www.wowhead.com/?quest=10998\nhttp://www.wowhead.com/?quest=11000\n\nWhen all those prereq are done, it gives you Ogre Heaven",
            date = "2007-05-27T22:48:18-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11022#comments:id=92073",
        },
        {
            id = 158080,
            score = 12,
            author = "43768",
            text = "It's odd, after you do this, all ogres in blades edge become neutral to you, it has nothing to do with org'rila faction.  Very funny if your being chased by someone of the opposite faction, you can find saftey in a cluster of ogres if they aren't neutral also..... some funny moments to be had....",
            date = "2007-09-25T10:20:16-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11022#comments:id=158080",
        },
    },
    [11023] = {
        {
            id = 1597021,
            score = 278,
            author = "Leilanis",
            text = "Ok, for those of you that need to do this for the achievement https://www.wowhead.com/achievement=1282 for https://www.wowhead.com/achievement=1692 follow this and you only have to do 4 quests to get to the daily \"Bomb them again!\" I would recommend you turn on you low level quest tracker so you can see the ! marks.\n\nHappy questing, and Merry Christmas!\n\nhttps://www.wowhead.com/quest=11025 from https://www.wowhead.com/npc=23233\n\nhttps://www.wowhead.com/quest=11030 from https://www.wowhead.com/npc=23316\n\nhttps://www.wowhead.com/quest=11062 from https://www.wowhead.com/npc=23233\n\nhttps://www.wowhead.com/quest=11010 from https://www.wowhead.com/npc=23120\n\nThen you can get [quest=https://www.wowhead.com/quest=11023\n\nPs..on a side note if you like achievements be sure to do https://www.wowhead.com/quest=11023 in less than\n 2 minutes and 15 seconds while not in a group and get https://www.wowhead.com/achievement=1276",
            date = "2011-12-16T01:55:04-06:00",
            sourceUrl = "https://www.wowhead.com/quest=11023#comments:id=1597021",
        },
        {
            id = 513447,
            score = 74,
            author = "Sinius",
            text = "* Mog'dorg the Wizened\n-> [70+] Even Gronn Have Standards\n-> [70+] Grulloc Has Two Skulls\n-> [70+] Maggoc's Treasure Chest\n--> [70+] Grim(oire) Business\n---> [70+] Into the Soulgrinder\n----> Ogre Heaven\n-----> The Crystals\n-------> An Apexis Relic\n--------> The Relic's Emanation\n---------> Our Boy Wants To Be A Skyguard Ranger\n----------> The Skyguard Outpost\n\nThis is the chain.",
            date = "2008-12-16T07:23:56-06:00",
            sourceUrl = "https://www.wowhead.com/quest=11023#comments:id=513447",
        },
        {
            id = 3277090,
            score = 53,
            author = "Mypciscraze",
            text = "Hi all\n\nOn This Christmas Achievement https://www.wowhead.com/achievement=1282 Do in Order:\n\nSee My Video if need it - https://youtu.be/VfuAHgz7zSk\n\n1. Get https://www.wowhead.com/item=21212 from Winter Reveler use /kiss on Her ( i done it in Dalaran WOTLK 43 63 as well She can give you 2 other items https://www.wowhead.com/item=21519 or https://www.wowhead.com/item=34191 ) or https://www.wowhead.com/item=21213 from https://www.wowhead.com/item=21327.\n\n2. Fly To Blade's Edge Mountains in TBC ( use portal in Stormwind to [zone=3703] ) And take Quest https://www.wowhead.com/quest=11025 from https://www.wowhead.com/npc=23233 29 57, go collect 5 https://www.wowhead.com/item=32569 ( is drop from all mobs around or pick up from crystals ).\n\n3. Do Quest https://www.wowhead.com/quest=11030 from https://www.wowhead.com/npc=23316 28 57 in Blade's Edge Mountains. Get 10 https://www.wowhead.com/item=32569 then fly to https://www.wowhead.com/object=185919 32 40 and create https://www.wowhead.com/item=32598 and go back to https://www.wowhead.com/npc=23316.\n\n3. Pick up quest https://www.wowhead.com/quest=11062 from https://www.wowhead.com/npc=23233 29 57, Fly to see https://www.wowhead.com/npc=23334 27 52 in Blade's Edge Mountains.\n\n4. Pick Up Quest https://www.wowhead.com/quest=11010 from https://www.wowhead.com/npc=23120 27 52. Fly north around 33 40 and use https://www.wowhead.com/item=32456 on a pile of cannon balls. YOU NEED TO BY ON FLY MOUNT\n\n5. Use https://www.wowhead.com/item=21212 then Pick Up Quest https://www.wowhead.com/quest=11023 from https://www.wowhead.com/npc=23120 27 52. Fly north around 33 40 and use https://www.wowhead.com/item=32456 on a pile of cannon balls. YOU NEED TO BY ON FLY MOUNT\n\nHope that Help You :)",
            date = "2020-12-19T09:58:41-06:00",
            sourceUrl = "https://www.wowhead.com/quest=11023#comments:id=3277090",
        },
        {
            id = 98038,
            score = 28,
            author = "58802",
            text = "If you want to have some real fun, just dive bomb them like you see in the movies.\n\nPick your target and dive in anywhere at about a 45* angle, release the bomb when in range, do 90* upwards and then circle back out of range. No dodging back forth upward etc, just that simple pattern and once you get it pat down, you'll not only have a 100% success rate ... you'll feel like you're on an honest to goodness dive bombing mission.\n\nMind you, this is using an epic with a riding crop. Not sure if it works with any less.",
            date = "2007-06-04T12:37:39-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11023#comments:id=98038",
        },
        {
            id = 511315,
            score = 25,
            author = "NMMRG",
            text = "Finished this quest instantly by doing a barrel roll.",
            date = "2008-12-15T08:39:34-06:00",
            sourceUrl = "https://www.wowhead.com/quest=11023#comments:id=511315",
        },
    },
