    [11025] = {
        {
            id = 322671,
            score = 29,
            author = "34301",
            text = "Guys, try farming the apexis shards at bash'ir's  landing. I got about 7 from the ethereals in 5 minutes.",
            date = "2008-07-08T14:17:20-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11025#comments:id=322671",
        },
        {
            id = 105968,
            score = 20,
            author = "63064",
            text = "No need to go to 54,13 they drop from apexis flayers right next to him.",
            date = "2007-06-17T11:42:44-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11025#comments:id=105968",
        },
        {
            id = 100947,
            score = 8,
            author = "mattous",
            text = "After completing this quest can pick up the quest \"Our Boy Wants To Be A Skyguard Ranger\" off of Torkus in Ogri'la - http://www.wowhead.com/?quest=11030",
            date = "2007-06-08T19:00:16-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11025#comments:id=100947",
        },
        {
            id = 921284,
            score = 5,
            author = "381050",
            text = "Can  anybody tell me HOW you mine them out of the ground?  I don't see anything twinkling or lighting up to tell me where to dig... and even if I did find a spot I don't know what I have to do to actually mine it!  And I'm a miner by profession!\n\nEDIT:  I finally figured it out.  What threw me off was that Chu'a'lor specifically said, \"In addition to the creatures here having them, they can sometimes be found where the flayers dig at the larger crystals.\" (Emphasis added.)\n\nSo I ran around looking for the biggest honkin' crystals I could find.  My mistake.  I wasn't supposed to be looking at the big ones.  The mineable ones are mostly man-sized with 2 or 3 smaller ones clustered around the base.  These in turn are found either at the base of the really big clusters or occasionally out in the open.  To further complicate things, the mineables can also be found as a cluster of 4 or 5 gnome-sized crystals.  (See screenshots.)\n\nOnce I had this dialed in it was a lot easier to mouse over the bigger clusters and find the mineables.  Too bad I didn't figure it out until I was almost done grinding out the 55 I wanted (5 for the quest, 50 for a pair of gloves I got off the AH).",
            date = "2009-12-17T16:44:32-06:00",
            sourceUrl = "https://www.wowhead.com/quest=11025#comments:id=921284",
        },
        {
            id = 1565822,
            score = 5,
            author = "Zeribus",
            text = "I found it easier to just wave my cursor over the shard formations to find places to mine. Also if you kill the Gan'arg Analyzer's in the area an Apexis Shard or 2 will drop with every mob.",
            date = "2011-11-07T17:02:19-06:00",
            sourceUrl = "https://www.wowhead.com/quest=11025#comments:id=1565822",
        },
    },
    [11026] = {
        {
            id = 114068,
            score = 112,
            author = "33604",
            text = "You need to be honored to get this quest.",
            date = "2007-07-01T20:33:30-05:00",
