            score = 83,
            author = "Innoruuk",
            text = "Collect 10 Apexis shards from the Bash'ir guys at Bash'ir Landing in Blade's Edge (51,14). Once you get those, fly down to Forge Camp Terror and turn them in to the Fel Crystalforge (29,81).",
            date = "2008-03-15T12:55:09-05:00",
