            author = "341583",
            text = "Hello everyone,\n\n#1 - Go to Forge Camp: Terror\n#2 - Farm 10 apexis shards\n#3 - In middle of camp, theres a machine that looks like a steam engine, besides it theres a small pot looking thing with green bubbles coming out of it, click on it and get your beast blood.\n\nEnjoy!",
