    [11038] = {
        {
            id = 217056,
            score = 32,
            author = "40287",
            text = "It's not a bug - this quest is part of a group of quests, only one of which can be taken. These are the others:\n\nOff To Area 52\nOut of This World Produce!\nA Strange Vision\nParts for the Rocket-Chief\nA Mystifying Vision\n\nI had this one in my log and was unable to pick op any of the others. When I abandoned it they became available. All are merely a way of getting you to area 52 for the first time.",
            date = "2008-01-12T02:19:19-06:00",
            sourceUrl = "https://www.wowhead.com/quest=11038#comments:id=217056",
        },
        {
            id = 828838,
            score = 13,
            author = "Bullet123",
            text = "This quest is only attainable when you chose side to the Aldor. I wasn't able to get it until I did the City of Light quest and chose for the Aldor after.",
            date = "2009-09-01T06:07:44-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11038#comments:id=828838",
        },
        {
            id = 168981,
            score = 12,
            author = "49229",
            text = "you dont need to do this part u can start directly on the second , you can talk to that guy in the Inn of area 52 .",
            date = "2007-10-15T09:57:43-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11038#comments:id=168981",
        },
        {
            id = 216174,
            score = 11,
            author = "33464",
            text = "I believe this quest is an optional prerequisite for the second one, Distraction at Manaforge B'naar (http://www.wowhead.com/?quest=10241).  If you have done that, you will no longer be offered this one, regardless of your level.\n\nI further believe that Distraction at Manaforge B'naar will not be offered until you have worked your way through the Manaforge quest chain from Anchorite Karja (http://www.wowhead.com/?npc=19467) and are at Shutting Down Manaforge B'naar (http://www.wowhead.com/?quest=10299) - so you'll get two quests for B'naar at the same time.  The same applies to the later quests at Manaforge Coruu.",
            date = "2008-01-10T12:14:46-06:00",
            sourceUrl = "https://www.wowhead.com/quest=11038#comments:id=216174",
        },
        {
            id = 89206,
            score = 6,
            author = "4971",
            text = "This quest can apparently be given by two different NPCs, Vindicator Aeus (Aldor bank) and Vindicator Kaan (Aldor rise, open courtyard area).\n\nBoth were added in patch 2.1.  I'm assuming the quest result is identical regardless of which NPC you pick, but I don't know for sure.",
            date = "2007-05-24T05:58:07-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11038#comments:id=89206",
        },
    },
    [11039] = {
        {
            id = 868932,
            score = 19,
            author = "crmarr",
            text = "Just a note to say that you MUST complete the City of Light quest in order to get the quest from the Scryers - even if you are friendly/honored/revered you will not get this quest without completing City of Light.\n\nTook a GM to work that out for me :(",
            date = "2009-10-17T18:11:25-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11039#comments:id=868932",
        },
        {
            id = 120930,
            score = 16,
            author = "17155",
            text = "You can't get this quest if you have the \"A Strange Vision\" quest from the horde town in Nagrand, I just had to abandon it for the exclamation mark to appear over the NPC's head.\n\nThis is the quest...\nhttp://www.wowhead.com/?quest=11037\n\nI assume you can't have any one of the other 4 quests in your log either to get this one. I suggest doing this quest and dropping the others since this one gives some Scryer rep, even though it's a small amount every little bit helps. :)",
            date = "2007-07-15T06:57:53-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11039#comments:id=120930",
        },
        {
            id = 269490,
            score = 10,
            author = "81638",
            text = "If you have chosen scryers already and cant get the quest from this guy, then you need to go to Netherstorm and skip this step of the quest, his name is Spymaster Thalodien and is located in Area 52.\n\nIf still not possible, try abandon the quest for sunfury signs.\n\nHope it helps, it did for me!",
            date = "2008-04-10T03:26:03-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11039#comments:id=269490",
        },
        {
            id = 1875036,
            score = 7,
            author = "Silvansaria",
            text = "I just reversed my standing from the Aldor to the Scryer - and after all my turn-ins I am Honored with them and ready to begin questing.\n\nThis quest in question - was NOT available to me at all - neither was the \"City of Light\" from Khadgar.  Maybe I already did it with the Aldor back in the day - I can't remember.  I also don't have any of the other quests mentioned that would be blocking me from getting THIS quest.\n\nHOWEVER..........................................\n\nI wanted to see what would happen if I just flew to Area 51 - and sure enough THIS quest was already ready and waiting for me.  So the point is - if you don't see the quest on the Scryer Tier from Arcanist Savan - go to Area 51 and it might already be activated for you.",
            date = "2013-07-09T02:24:39-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11039#comments:id=1875036",
        },
        {
            id = 1634262,
            score = 5,
            author = "696346",
            text = "I achieved https://www.wowhead.com/achievement=1205 and this quest appears to be unavailable. I assume this is because I already completed the Aldor version of it. The follow up quest was still available though.",
            date = "2012-03-02T16:11:37-06:00",
            sourceUrl = "https://www.wowhead.com/quest=11039#comments:id=1634262",
        },
    },
    [11040] = {
        {
            id = 105841,
            score = 6,
            author = "43758",
            text = "Rocket-Chief Fuselage is located in Netherstorm at AREA 52 (32.8 x 64.9)\n\nFollow the road all the way to Area 52.\nStart by heading EAST from Ruuan Weald in BEM then follow the road North at the fork. It will lead you to Netherstorm. Staying on the road & it will lead you to Area 52.\n\nWhile at Area 52 you may want to visit:\nFlight Master  33.8 x 64.0\nBanker  32.8 x 67.9",
            date = "2007-06-17T06:59:55-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11040#comments:id=105841",
