    [11041] = {
        {
            id = 87859,
            score = 55,
            author = "Redcrosse",
            text = "The quest starter drops from Arvoar the Rapacious http://www.wowhead.com/?npc=23267 who pats around in a small circle around 74,86.\n\nYou get 250 Netherwing rep on completion.",
            date = "2007-05-23T00:37:32-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11041#comments:id=87859",
        },
        {
            id = 199900,
            score = 19,
            author = "Slimwit",
            text = "I think it is worth noting that you must be Netherwing Neutral for the item to drop.  This means you must have 300 Flying Skill (Elite Flying)  It mentions that in the note for the dropped item that starts the quest, but that's easy to miss (as I did).",
            date = "2007-12-11T21:44:41-06:00",
            sourceUrl = "https://www.wowhead.com/quest=11041#comments:id=199900",
        },
        {
            id = 2570981,
            score = 10,
            author = "Aerynsun8449",
            text = "Yet another damn quest, tied to the achievement, that has a \"random\" drop rate. Way to go Blizzard. I've got flying, I've got neutral status with Netherwing, yet I've killed https://www.wowhead.com/npc=23267 three times and https://www.wowhead.com/item=32621 has yet to drop. This is the last chain I need for Lore master, not only in Shadowmoon Valley, but ALL of Outland as well. This has been the most frustrating experience I've had with this game. As I posted elsewhere, I used to think Blizzard programmers where just on some really good drugs when they designed some of these quests. After going for Lore master here, I believe they're just sadistic jerks. Gating Lore master quests on \"random\" drops is ludicrous at best.\n\nThere seems to be a LOT of misinformation regarding this quest. No, you don't just have to have flying and be neutral with Netherwing. You ALSO have to have 310 flying. Even if you have 280 flying, you can still get the quest https://www.wowhead.com/quest=11013, but the npcs over there will still be hostile to you until you have 310 flying. As soon as you have 310 flying, when you fly over there ALL of the npcs are friendly and offer daily quests. So, the https://www.wowhead.com/item=32621 ISN'T a random drop, it dropped right away, after I got 310 flying and the quest  https://www.wowhead.com/quest=11013. There might be another quest as I picked up a couple prior to going back to kill https://www.wowhead.com/npc=23267 for the fourth time. That time https://www.wowhead.com/item=32621 dropped right away.",
            date = "2018-05-30T16:43:45-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11041#comments:id=2570981",
        },
        {
            id = 3121962,
            score = 9,
            author = "Shadanah",
            text = "As of 8.1.5:\n\nYou kill Arvoar the Devourer, pick up the item drop, and then complete the quest that triggers (this one). This will complete Netherwing Ledge. Nothing sent me to kill Arvoar so I assume it's an oversight in design, as players today would have no reason to go kill it.",
            date = "2019-05-08T11:53:04-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11041#comments:id=3121962",
        },
        {
            id = 896796,
            score = 8,
            author = "chailey",
            text = "Does count toward the Shadow of the Betrayer Achievement, however, the daily quests do not count, even the first time.",
            date = "2009-11-21T16:17:02-06:00",
            sourceUrl = "https://www.wowhead.com/quest=11041#comments:id=896796",
        },
    },
