    [11045] = {
        {
            id = 406050,
            score = 5,
            author = "Cleptor",
            text = "Tested with 2.4.3 just a few minutes ago. An other party member accepted this quest and I already had Visions of Destruction (http://www.wowhead.com/?quest=11044) in my log.\n\nAccepting this quest excludes you from accepting Visions of Destruction (http://www.wowhead.com/?quest=11044) and vice versa. The NPCs won't even show you an exclamation mark.\n\nAlso you won't be able to share this quest with someone who has Visions of Destruction (http://www.wowhead.com/?quest=11044) and vice versa. As soon as I removed Visions of Destruction (http://www.wowhead.com/?quest=11044) from my log, my party member could share his quest with me and I was also able to accept this quest from the NPC.\n\nBoth quest give 1150 experience so it won't matter which one you do.",
            date = "2008-10-14T17:44:52-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11045#comments:id=406050",
        },
        {
            id = 217632,
            score = 4,
            author = "114876",
            text = "[35.57]\n\nJust another one of those quests that lead to a new questing hub - Wildhammer stronghold is to your right just a little while after entering Shadowmoon valley from terrokar, past Legion hold.  If your alliance you probably have the flight path for Allerian Stronghold - if you haven't been to SMV bfr this is the fastest way to get there",
            date = "2008-01-13T06:56:55-06:00",
            sourceUrl = "https://www.wowhead.com/quest=11045#comments:id=217632",
        },
        {
