    [11046] = {
        {
            id = 222596,
            score = 8,
            author = "120999",
            text = "Not confirmed but I think it is mutually exclusive along with some other quests ending in Shadowmoon. I know one of these mutually exclusive quests is: An Apprentice Request (http://www.wowhead.com/?quest=11047).\nAnother is: Kroghan's Report (http://www.wowhead.com/?quest=11048).\nSo if you have done any one of these quests, or the quests following them, you probably can't get any of the others.",
            date = "2008-01-23T00:44:01-06:00",
            sourceUrl = "https://www.wowhead.com/quest=11046#comments:id=222596",
        },
        {
            id = 336416,
            score = 6,
            author = "OhTeeSee",
            text = "There is no Pre-Req, however if you have accepted Kroghan's Report (Garadar) you will be unable to receive this quest in Shattrath, likewise, if you have this quest, you will be unable to recieve Kroghan's Report.\n\nThe reasoning for this is simple, the quest is not a true \"chain\" its merely a quest to send you on to the next zone, in this case, Shadowmoon Valley.",
            date = "2008-07-26T00:05:41-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11046#comments:id=336416",
        },
