    [11051] = {
        {
            id = 95856,
            score = 80,
            author = "57954",
            text = "You must be honored with Ogri'la to accept the quest \"Banish the Demons\" http://www.wowhead.com/?quest=11026 . Once that has been completed, this quest becomes a daily quest.",
            date = "2007-06-02T08:43:44-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11051#comments:id=95856",
        },
        {
            id = 105661,
            score = 33,
            author = "Bengarion",
            text = "Just to be clear...\n\nYou can have only one Kronk's Grab Bag in your inventory.\n\nYou can have only one Crystalforged Darkrune in your inventory.\n\nYou can have only one Darkrune in your inventory.\n\nYou may have one of each of the above in your inventory.\n\nIf you have a Darkrune in your inventory you won't be able to open the Kronk's Grab Bag - because it may contain yet another Darkrune.\n\nIf your inventory is 'full' you'll have to use the Crystalforged Darkrune then convert the Darkrune to a Crystalforged Darkrune before you can open another Kronk's Grab Bag.\n\nSee the quest \"A Crystalforged Darkrune\" http://www.wowhead.com/?quest=11060\n\nGood Luck",
            date = "2007-06-16T20:55:12-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11051#comments:id=105661",
        },
        {
            id = 125982,
            score = 11,
            author = "Mechanical",
            text = "Guys if you have this quest, and are out killing your 15 demons at one of the camps, lookout for other faction members on the quest and invite them to your group.\nThere are many advantages:\n1. Mobs die faster\n2. You waste less shards creating portals as 1 portal per group is enough to get credit for mobs.\n3. You got some backup in case you pull too many mobs or get the humanoids to agro you (the shadowbolt spam is very annoying)\n4. There are less outsiders killing demons, so there's more for you to kill and you finish the quest much faster.\nThe only disadvantage -> You dont get the full loot off mobs (as if they drop anything worth it...)\nOn my realm the forge camps (especially the northern one) are heavily farmed with people doing the quest, and it could so easily be avoided if we just grouped up.",
            date = "2007-07-24T10:20:31-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11051#comments:id=125982",
        },
        {
            id = 2370885,
            score = 9,
            author = "dillybar",
            text = "If you get the following comment when attemptinng to turn in the quest:\n\nBanish More Demons failed: Duplicate item found.\n\nYou have a \"Kronk's Grab Bag\" in your inventory.  Open it and you can complete the quest.  You can only have one of Kronk's Grab Bag in your inventory at any given time.",
            date = "2016-08-19T21:44:27-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11051#comments:id=2370885",
        },
        {
            id = 160148,
            score = 7,
            author = "16717",
            text = "The demons milling around the apexis monuments count for this quest if you get them near a portal.  The boar do not.",
            date = "2007-09-29T03:51:18-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11051#comments:id=160148",
        },
    },
