        },
        {
            id = 1100390,
            score = 13,
            author = "641037",
            text = "I'd just like to mention that these items ARE, in fact, vendorable. I ended up not reading the quest text and selling two of them before I realized I'd just wasted half an hour of blowing through these damn things because I wasn't paying attention and accidentally bumped them off my buyback tab selling netherweave and feathers.",
            date = "2010-08-14T00:24:07-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11074#comments:id=1100390",
        },
        {
            id = 805822,
