    [11075] = {
        {
            id = 89673,
            score = 5,
            author = "Classic",
            text = "The Mistress Of The Mines ,  65.90",
            date = "2007-05-24T15:47:08-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11075#comments:id=89673",
        },
        {
            id = 1599592,
            score = 3,
            author = "162721",
