    [11080] = {
        {
            id = 89684,
            score = 247,
            author = "55008",
            text = "The best way to do this is to open a chat box and whisper yourself the sequence, using r g b y for the colors.  Much easier than getting a paper and trying to read your own frantic writing.",
            date = "2007-05-24T15:57:00-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11080#comments:id=89684",
        },
        {
            id = 88283,
            score = 180,
            author = "14581",
            text = "You need 8 right sequences to complete the quest. need a Apexis Shard.",
            date = "2007-05-23T09:59:00-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11080#comments:id=88283",
        },
        {
            id = 2358817,
            score = 157,
            author = "Wesi",
            text = "Since the Legion Pre Patch (7.0.3) there is a new mechanic. After the 3-4 round of clicking there will be a fire-nova which, if you click to fast, will interrupt you and the sequence ends and you have to start over.\n\nTo solve this just Click the right colour and wait 1 Second for the fire-nova and only click the next colour when the fire-nova animation is over.\n\nUse the Addon ogri-lazy (https://mods.curse.com/addons/wow/ogri-lazy)",
            date = "2016-07-30T08:11:43-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11080#comments:id=2358817",
        },
        {
            id = 126979,
            score = 99,
            author = "48141",
            text = "While I downloaded Ogri'lazy, I found an easy method that doesn't require key bindings and the effort.\n\n1. Stand in the middle of the X and move your camera view so that it's literally looking straight down. Zoom in so that it takes up much of the screen.\n2. Align the cross so that each colour is aligned top, bottom, left and right.\n3. Type /s as if you're going to say something then press num lock so you're ready to type numbers on the keypad\n\nWhat you're going to do here is use the number key pad on your keyboard as if it represents the cross.\n\nLook now at your keyboard and you'll see four arrows on numbers.\n8 is UP\n4 is LEFT\n6 is RIGHT\n2 is DOWN\n\n4. Insert your crystal and type out the colours on the number keypad as they occur. You might not need it for the first few, but when it gets harder you don't even need to concentrate.\n5. Watch and type on pad at the same time, pressing enter at the end of each sequence\n6. Press the colours with mouse as they were typed out:\n\nExample:\nTyping away, if I had typed: 84662486\nThen I could press the colours TOP, LEFT, RIGHT, RIGHT, BOTTOM, LEFT, TOP, RIGHT.\n\nI hated this quest, but now it's very simple.",
            date = "2007-07-26T05:07:15-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11080#comments:id=126979",
        },
        {
            id = 921868,
            score = 62,
            author = "154866",
            text = "LMFAO my last sequence was:\nU U D D L R L R\n\nFor those of you who don't get it (or too young to remember):\nhttp://en.wikipedia.org/wiki/Konami_Code",
            date = "2009-12-18T07:51:22-06:00",
            sourceUrl = "https://www.wowhead.com/quest=11080#comments:id=921868",
        },
    },
