    [11082] = {
        {
            id = 159933,
            score = 108,
            author = "pabasa",
            text = "It's kinda sad to see the sacrifice those murkblood made for the sake of the netherflight. Dying and activating the dormat creatures in the mines and stuff. And the overseer willingly giving his own hand as proof made me feel very guilty, even though I've cut plenty of other people's heads before.\n\nI hope all their sacrifices are not in vain. So far all I'm seeing is that I get to have my own netherdrake.",
            date = "2007-09-28T14:26:21-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11082#comments:id=159933",
        },
        {
            id = 90719,
            score = 95,
            author = "13537",
            text = "The overseers can be found in the same area of the mine as the flayers. They are 'hiding' behind digging machines.\n\n500 Netherwing rep upon completion.",
            date = "2007-05-26T02:52:15-05:00",
