    [11085] = {
        {
            id = 89456,
            score = 91,
            author = "asaphelps",
            text = "I've completed this several times and each time I have received 11g and 99s, along with the option of selecting either 2 Volatile Healing Potions or 2 Unstable Mana Potions. Since this is a daily and repeatable quest, this is an excellent source of getting potions if you need them. As other people have stated, he has multiple spawns which so far have included:\n\n60,75\n75,86\n68,71\n\nSo he can spawn on either side of the lake, and is in an elevated hut inside a cage. An easy way to find him is to fly around and use /target skywing until he comes up. His respawn time doesn't seem too bad, just keep in mind he has multiple spawns. The escort self is very easy, and any class (i'm a holy pally) can even do it since it just involves killing two spawned level 71 skettis and takes literally 2 minutes. You get 350 rep with Sha'tari Skyguard upon completion as well as each time you repeat it.",
            date = "2007-05-24T11:09:09-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11085#comments:id=89456",
        },
        {
            id = 105707,
            score = 23,
            author = "TehDang",
            text = "60,75\n75,86\n68, 74\n\nJust restating Asaphelps's with Jmdbcool's correction. Because I hate scrolling between two comments to /waypoint with Cartographer.",
            date = "2007-06-16T23:41:24-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11085#comments:id=105707",
        },
        {
            id = 88910,
            score = 20,
            author = "20028",
            text = "This NPC is a static Spawn. He can spawn in a few places. I found him @ 75,86.\n\nHe looks like a Draenei Broken caged up.\n\nThe quest is relaativley short if you clear up to him. All you have to do is walk him out of one of the high perches and you are set. The quest indeed does count as a 'Daily' quest.\n\nThe quest is repeatable with gold (as of the second day, and attempt) being given as a reward instead of the potions.",
            date = "2007-05-23T21:49:01-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11085#comments:id=88910",
        },
        {
            id = 107302,
            score = 17,
            author = "13796",
            text = "In the new 2.1.2 patch, this quest now gives you the choices between 2 Volatile Healing Potion or 2 Unstable Mana Potion.\n\nVolatile restores 1075 to 1750 health\n\nUnstable mana restores 1350 to 2250 Mana",
            date = "2007-06-19T15:22:58-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11085#comments:id=107302",
        },
        {
            id = 248748,
            score = 14,
            author = "douglasadams",
            text = "As of patch 2.4:\n\nThe daily quest Escape from Skettis has had its reward tuned down.",
            date = "2008-03-05T23:50:27-06:00",
            sourceUrl = "https://www.wowhead.com/quest=11085#comments:id=248748",
        },
    },
    [11086] = {
        {
            id = 89286,
            score = 60,
            author = "22738",
            text = "Just kill 20 deathshadow agents in Nagrand at twilight ridge. You can reach this place only flying.\n\nSuggestions:\n- Start this quest @ 13,35 (Nagrand)\n- Agent types are: archon, spellbinder, warlock and acolyte (all orcs).\n- Better to avoid Deathshadow overlord (ogre lvl 71 elite, 32k hp, hits cloths for 1300, cast fireball or shadowbolt for 2k, not immune to crowd control).\n- Better to avoid Reth'hedron the Subduer (demon lvl 73 elite).\n\nThis quest is available at honored with Netherwing.",
            date = "2007-05-24T07:45:21-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11086#comments:id=89286",
        },
        {
            id = 108180,
            score = 26,
            author = "44336",
            text = "Easy way to do it:\n\nGo to the area, you'll see a big purple Arc.\nLand in the center.\nPull. Theres 6 or 7 mobs on both sides. They will not aggro until you attack them\n\nFrom the West side be careful, as the mob will run around the Arc.",
            date = "2007-06-20T19:57:01-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11086#comments:id=108180",
        },
        {
            id = 101538,
            score = 20,
            author = "60629",
            text = "something that may help out, (especially for warriors out there..since this is what I use to do this daily) at roughly coords 8, 43, there is a arch - like structure where roughly 8 to 10 spellbinders are connected to it via their little \"energy-streams\". the arch way runs fairly north to south with the mobs on the east and west side. on the east side, there is a stairway which climbs up onto the platform of the arch (not far off the ground, just a bit). I killed the mobs on the east side, usually hitting one would aggro a second, but not always, until the east side was clear. once it was, i would climb the stairs and hit with ranged one of the mobs on the west side. these ones have to run all the way around to the east and get to the stairs before they would try casting on you. also, they would only aggro one at a time (so far that i have encountered). killing the mobs here gets you away from the patrolling elites, which means less ghost walks. (yes, trial and error meant i have done too many ghost walks here already). i hope this helps someone out there...it is one of the more frustrating daily quests for myself, mainly because of the elite pats.",
            date = "2007-06-09T19:29:30-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11086#comments:id=101538",
        },
        {
            id = 269788,
            score = 10,
            author = "lcarnegie",
            text = "a heads up if you die. If you can't figure out how to get back look for the cave at 18 33 and follow it. Took me way to damn long to figure this out.",
            date = "2008-04-10T16:27:25-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11086#comments:id=269788",
        },
        {
            id = 161308,
            score = 7,
            author = "Grados",
            text = "This quest awards 500 reputation, making this and The Deadliest Trap Ever Laid (Scryer) (http://www.wowhead.com/?quest=11097) or The Deadliest Trap Ever Laid (Aldor) (http://www.wowhead.com/?quest=11101) the best daily quests to do for getting Exalted reputation and a Nether Drake as quickly as possible.",
            date = "2007-10-01T11:02:48-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11086#comments:id=161308",
        },
    },
    [11089] = {
        {
            id = 89320,
            score = 215,
            author = "22738",
            text = "Felsteel Bar x 2 (done with smelting) = 12 fel iron ore + 8 eternium ore\nAdamantite Frame (done with engineering) = 8 adamantite ore + 1 primal earth\nKhorium Power Core (done with engineering) = 6 khorium ore + 1 primal fire\n\nOres required: 12 fel iron, 8 eternium, 8 adamantite, 6 khorium.\nPrimals required: 1 primal earth, 1 primal fire.\n\nFor the Flawless Arcane Essence just go in Terokkar and speak to Sar'this, he's in a tent at 44.7,42.2 kill the 4 elementals and the last one will drop the essence. There you go.",
            date = "2007-05-24T08:19:22-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11089#comments:id=89320",
        },
        {
            id = 110675,
            score = 82,
            author = "Mzbehavin",
            text = "this npc for the essence is above stone breaker hold  44, 42  quite easy to solo this...\n\nfor the adamantite frame these are sold by\n\nDealer Najeeb based at 44.8 36.6\n   60 - Netherstorm\009A H\009Humanoid base on Stormspire  and\n\nQiff based at 32.6 66.6  just across the bridge from the inn\n Area 52  -  4g\n\nand khorium power core\n\nQiff\n Area 52 for 4g -  80\n\nplesae note these npc's have a cool down timer for these items so you may go and they may not have them so check the other as well..",
            date = "2007-06-25T02:09:24-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11089#comments:id=110675",
        },
        {
            id = 2461973,
            score = 74,
            author = "Taraezor",
            text = "Be warned, this was designed as a gold sink, back in the day. It is absolutely not required to get https://www.wowhead.com/achievement=1195. It is absolutely not required to get your [faction=1015] reputation up to exalted.\n\nIt will be quite a hassle too for obtaining all the items given that players rarely linger in Outlands content and/or push through the relevant professions. Multiple trips to https://www.wowhead.com/npc=19575, all the way over in Netherstorm, will be required if gold is a bit tight and/or the Auction House is unable to provide.\n\nThat time is better spent farming https://www.wowhead.com/item=32506. Hey, The Netherwing Eggs AddOn, by yours truly, and available at Curse (https://www.curseforge.com/wow/addons/handynotes_netherwingeggs) might be helpful!\n\nEdit: Assuming gold is not a problem and you were very lucky to obtain the items on the AH, the next step in the quest chain has you over in Nagrand and then back here for the same amount of Netherwing rep gain. A time sink as well. Better to just push on with the other quest chains.\n\nEdit: Farm smart. Strategically farm eggs every few hours / as per my advice elsewhere. Don't fly around getting frustrated.",
            date = "2017-01-11T20:18:13-06:00",
            sourceUrl = "https://www.wowhead.com/quest=11089#comments:id=2461973",
        },
        {
            id = 980376,
            score = 62,
            author = "536062",
            text = "While this quest is expensive and/or boring it does lead to a quest where you sit on your flying mount and blast a guy with a laser cannon.  I say it's totally worth it.",
            date = "2010-02-19T09:01:33-06:00",
            sourceUrl = "https://www.wowhead.com/quest=11089#comments:id=980376",
        },
        {
            id = 750711,
            score = 52,
            author = "52491",
            text = "The hardest part of this quest is actually staying there while Sar'this walks around, the elementals are just normal mobs at lvl 70. Not to fall asleep is the true test.",
            date = "2009-06-18T18:33:38-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11089#comments:id=750711",
        },
    },
    [11090] = {
        {
            id = 2013930,
            score = 102,
            author = "coronaas",
            text = "i was having problems with the gun killing him in three hits at level 90, but I was able to complete the quest after all.\n\nAfter removing my armor and weapons I was able to lower him below 10%hp and then trigger the gun to complete the quest.\n\nHope this helps in a post 6.0 world",
            date = "2014-10-16T04:55:05-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11090#comments:id=2013930",
        },
        {
            id = 89185,
            score = 76,
            author = "35519",
            text = "Really easy one. Drain his health down while you are in the air with your flying mount. Avoid meteors/fireballs.\nThe tactic I used is basicly staying in range, above him, flying around him clockwise while draining his soul. This way you will only take the shadow bolt damage (800ish). If you get cripple on you start going anti clockwise, so you dont run into the fireballs. The fireballs really hurt also dismounts you, and you die. Will take you a while till you suck his soul out, once hes on 1% hes starting to walk to the portal and leaves the place.\nIf you seem to take too much damage during an attempt you can flee away by just flying far from him.\nFun quest, good luck on it!",
            date = "2007-05-24T05:34:04-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11090#comments:id=89185",
        },
        {
            id = 2021536,
            score = 53,
            author = "jaymoney",
            text = "For level 90s:\n\n1. First thing you will want to know is it does pop up on screen when this quest is completed.\n\n2. Take off all your gear and get resurrection sickness.\n\n3. Cancel the channel of the Soul Cannon by pressing escape when Reth' Hedron is at 1% health (really small sliver of health).\n\n4. Allow him to walk away into the portal",
            date = "2014-10-31T11:35:26-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11090#comments:id=2021536",
        },
        {
            id = 2295630,
            score = 49,
            author = "ForestNymph",
            text = "EASY TO DO AS LVL 100. Portal in Western Nagrand (Outland) is located at 8.3 44.3. Fly there and land on top of the portal. You do NOT have to be mounted no matter what you may have read. Undress completely...all clothing, jewelry, weapons, etc. Stand on the edge at the top of the portal and wait for Reth'hedron the Subduer to walk by. Target him with the soul cannon. He will try to run away but will then give up and come back to the portal. He should go on through without you having to do anything else except to get dressed again and go turn in the quest. Easy-peasy! (And I'm *extremely* 'gaming-challenged'.)",
            date = "2016-01-06T20:35:06-06:00",
            sourceUrl = "https://www.wowhead.com/quest=11090#comments:id=2295630",
        },
        {
            id = 95216,
            score = 46,
            author = "21672",
            text = "Easiest way to do this quest after it took me about 4 maybe 5 tries to do it is to wait until hes is close to the portal. Activate the cannon and hide behind the pillar ( i found the right side if your behind the portal to be the easiest one to use) Make sure you have LOS on him or your be subject to his attacks. He will stand there while you drain him and you wont take damage. But you have to make sure  LOS is the issue the cannon will still work however",
            date = "2007-06-01T08:42:55-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11090#comments:id=95216",
        },
    },
