    [11097] = {
        {
            id = 133491,
            score = 66,
            author = "Skulver",
            text = "The quest becomes available when you reach revered with the netherwing.",
            date = "2007-08-06T21:59:45-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11097#comments:id=133491",
        },
        {
            id = 93455,
            score = 25,
            author = "5286",
            text = "I soloed this as a Priest (as Scryers) I just spammed Greater Heal and fought for aggro, once I succeeded in that I ran straight to the grphyon master and kept myself up.\nThe flying guys will multi shot you, thus hitting anything around you. Hitting the grphyon master spawns level 65 elite and 65 non-elite that will kill the attackers.",
            date = "2007-05-30T05:42:34-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11097#comments:id=93455",
        },
        {
            id = 283481,
            score = 20,
            author = "29641",
            text = "If you die, the quest wont fail, just ress imediately and continue.",
            date = "2008-05-06T14:33:43-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11097#comments:id=283481",
        },
        {
            id = 300472,
            score = 18,
            author = "Golite",
            text = "Possibly a pop culture reference to the song Home by Depeche Mode.\n\nHere is a page\nFrom the emptiest stage\nA cage or the heaviest cross ever made\nA gauge of the deadliest trap ever laid",
            date = "2008-06-06T03:16:13-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11097#comments:id=300472",
        },
        {
            id = 316590,
            score = 7,
            author = "113739",
            text = "My question is, what exactly is it you have to do in order to defeat the Dragonmaw?  Several times this quest has failed for me with Commander Hobb still alive and with ~30% health.  So apparently there's more to it than just keeping Hobb alive; this is obviously a timed quest, so do you have to kill a certain number of Dragonmaw or do a certain amount of damage during the time allotted, or might this actually be a bug?",
            date = "2008-06-30T06:22:26-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11097#comments:id=316590",
        },
    },
    [11098] = {
        {
