    [11099] = {
        {
            id = 251495,
            score = 19,
            author = "63454",
            text = "you must be revered",
            date = "2008-03-11T00:56:09-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11099#comments:id=251495",
        },
        {
            id = 649007,
            score = 9,
            author = "155256",
            text = "As a level 80 Death Knight i just found out you need to be friendly with either the Scryers or Aldor. I went through BC content and didn't pick my faction, and being a blood elf and going aldor (for when i was leveling jc) you start at neutral. I got revered with netherwing and wasn't able to collect the quest. Just got friendly with Aldor today and was able to pick up the quest.\n\nIn short... make sure you are friendly with your faction.",
            date = "2009-03-20T09:43:11-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11099#comments:id=649007",
        },
        {
            id = 99904,
            score = 6,
            author = "LoKHor",
            text = "Just take the flare gun to Anchorite Ceyla at the Altar of Sha'tar (62,28).",
            date = "2007-06-07T03:06:00-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11099#comments:id=99904",
        },
        {
            id = 1685722,
            score = 6,
            author = "1012730",
            text = "READ THIS!\n\nBe sure to talk to the \"War Veteran\" outside the building in Shattrath!\nAfter talking to him, you can get the quest from A'dal which leads you to Khadger!\n\nI struggled for 2 hours finding this out..",
            date = "2012-07-07T17:37:50-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11099#comments:id=1685722",
        },
        {
            id = 1314971,
            score = 5,
            author = "SapAuthor",
            text = "NOTE:\nYou can't get this quest unless you are unfriendly with one of the two factions, Aldor's Rise or Scryers.  We couldn't figure it out for the longest time until i looked at our reps, i had unfriendly, and my wife didn't, after turning in a fell armament she could pick up the quest.",
            date = "2011-01-29T21:13:11-06:00",
            sourceUrl = "https://www.wowhead.com/quest=11099#comments:id=1314971",
        },
    },
    [11100] = {
        {
            id = 1006681,
            score = 2,
            author = "Elorivan",
            text = "Leads to The Deadliest Trap Ever Laid (http://www.wowhead.com/?quest=11101).",
