    [11101] = {
        {
            id = 257753,
            score = 34,
            author = "65708",
            text = "Thought this might be hard... was drinking my wine and didn't know what to expect.  Started event, got hit, ran away towards Maddix the flight master, healed, ran back out... rinse repeat... quest done.\n\nT6 geared shadow priest and I didn't do any damage... just sipped my wine and ran back and forth.  Easy quest.\n\nI suggest either a Merlot or a Rioja for this quest.",
            date = "2008-03-22T23:05:08-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11101#comments:id=257753",
        },
        {
            id = 100377,
            score = 28,
            author = "Strike",
            text = "Must be revered. Then you take a quest in Netherwing Ledge that leads you to either Scryers or Aldor base in Shadowmoon to start that.",
            date = "2007-06-07T19:36:06-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11101#comments:id=100377",
        },
        {
            id = 93046,
            score = 16,
            author = "28853",
            text = "You can let the NPCs take most of the damage, just try to kill as many as you can while minimizing your damage taken. You can hide behind the wall and pillars of the aldor base when you need to bandage or even eat. Me and my warrior friend duo:ed this without much trouble, we just focus fired down as many as we can and ran off to bandage when we needed.\n\nAny group composition with a healer class would make this quest absolutely trivial even with 2man. The mobs do very weak damage aside from the occasional aimed shot for 1500ish on plate.",
            date = "2007-05-29T10:35:39-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11101#comments:id=93046",
        },
        {
            id = 1441215,
            score = 13,
            author = "urfurf",
            text = "Take these Aldor medals. Mor'ghor will need proof of \"victory\" once this is over.\nHe will recognize them as coming from the corpses of fallen Aldor soldiers.\n\nOkay, sounds like a good plan, but there's also that thing about... you know, the whole army of drake-riding raiders who won't be returning to Mor'ghor? Don't you think that will raise suspicion?\n\n... kk, you don't have to yell at me. You're the boss, fine, let's do it your way. Whatevs. I'm just here for the rep.",
            date = "2011-06-14T07:12:37-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11101#comments:id=1441215",
        },
        {
            id = 139406,
            score = 11,
            author = "Torabloodscalp",
            text = "Yay! There is finally a use for the second most useless tool in the Shaman Arsenal (behind the sentr...screenshot totem) Windwall Totem cuts the incoming damage from these chaps by about half on mail.",
            date = "2007-08-17T07:48:37-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11101#comments:id=139406",
        },
    },
