    [11108] = {
        {
            id = 174782,
            score = 409,
            author = "58582",
            text = "Before accepting this quest, you may want to pop in a movie or go to the store.  By the time the movie's over, you MIGHT be back in Shat.  That flight took forever!",
            date = "2007-10-25T14:44:29-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11108#comments:id=174782",
        },
        {
            id = 2453003,
            score = 125,
            author = "Vath",
            text = "My conversation was ruined by some random guy continuously yelling \"MULVERICK\" over and over.",
            date = "2016-12-11T21:33:01-06:00",
            sourceUrl = "https://www.wowhead.com/quest=11108#comments:id=2453003",
        },
        {
            id = 105802,
            score = 100,
            author = "27529",
            text = "Overlord Mor'ghor says: Come, . Lord Stormrage awaits.\nOverlord Mor'ghor yells: Warriors of Dragonmaw, gather 'round! One among you has attained the rank of highlord! Bow your heads in reverence! Show your respect and allegiance to Highlord !\nOverlord Mor'ghor says: Lord Illidan will be here shortly.\nIllidan Stormrage appears.\nOverlord Mor'ghor yells: All hail Lord Illidan!\nOverlord Mor'ghor says: Lord Illidan, this is the Dragonmaw that I, and others, have told you about. He will lead us to victory!\nIllidan Stormrage says: What is the meaning of this, Mor'ghor?\nOverlord Mor'ghor says: But... My lord, I do not understand. ... He is the orc that has...\nIllidan Stormrage says: SILENCE!\nIllidan Stormrage says: Blathering idiot. You incomprehensibly incompetent buffoon...\nIllidan Stormrage says: THIS is your hero?\nIllidan Stormrage says: You have been deceived, imbecile.\nIllidan Stormrage says: This... whole... operation... HAS BEEN COMPROMISED!\nIllidan Stormrage says: I expect to see this insect's carcass in pieces in my lair within the hour. Fail and you will suffer a fate so much worse than death.\nOverlord Mor'ghor says: It will be done, my lord.\nIllidan Stormrage takes his leave.\nOverlord Mor'ghor says: So you thought to make a fool of Mor'ghor, eh? Before you are delivered to Lord Illidan, you will feel pain that you could not know to exist. I will take pleasure in exacting my own vengeance.\nYarzill the Merc says: You will not harm the boy, Mor'ghor! Quickly, , climb on my back!\n\nIn this event Yarzill the Merc, a goblin quest giver located in Dragonmaw Base Camp, reveals his true nature: Yarzill is actually one of the older dragons of Netherwings.\n\nThe quest leads to these six, giving an option to select the color of a Netherwing Drake of your very own.\nhttp://www.wowhead.com/?quest=11109\nhttp://www.wowhead.com/?quest=11110\nhttp://www.wowhead.com/?quest=11111\nhttp://www.wowhead.com/?quest=11112\nhttp://www.wowhead.com/?quest=11113\nhttp://www.wowhead.com/?quest=11114",
            date = "2007-06-17T04:35:14-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11108#comments:id=105802",
        },
        {
            id = 567700,
            score = 97,
            author = "53205",
            text = "\"You're all so cute, I want to take all of you!\"\n\"Too bad, you'll have to fly all the way back to Netherwing Ledge and buy us from the evil orc dude.\"",
            date = "2009-01-18T08:29:12-06:00",
            sourceUrl = "https://www.wowhead.com/quest=11108#comments:id=567700",
        },
        {
            id = 1178012,
            score = 88,
            author = "kharth",
            text = "The extremely long flight back will give you plenty of time to look at all the mounts on wowhead and decide what color you like best.",
            date = "2010-11-22T20:59:06-06:00",
            sourceUrl = "https://www.wowhead.com/quest=11108#comments:id=1178012",
        },
    },
    [11109] = {
        {
            id = 749086,
            score = 12,
            author = "145736",
            text = "After getting exalted with the Netherwing (http://www.wowhead.com/?faction=1015), and completing Lord Illidan Stormrage (http://www.wowhead.com/?quest=11108) you can pick a quest for a free netherdrake of whichever color you like, and buy the other colors for 200g each.",
            date = "2009-06-17T08:58:32-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11109#comments:id=749086",
        },
        {
            id = 1051472,
            score = 6,
            author = "Roscoe426",
            text = "Level 70 players will begin their journey to exalted reputation by picking up the quest chain offered by Mordenai, a blood elf wandering the surface of the Netherwing Fields, in the southeast corner of Shadowmoon ValleyGrind the daily quests for the rep, takes a few  weeks but quests are fast when u know them. Bit of gold from doing them too. Players are introduced to the Netherwing faction at 0/36000 hated reputation, and must be exalted to receive a Netherwing Drake. The quest chain and reputation grind is a mostly solo endeavor involving quests that can only be completed once daily, a 5-player group quest on the way to neutral, and daily 3-player group quests after reaching revered. A flying mount is required for this reputation grind, and 300 riding skill is necessary to advance past neutral. . The quest chain begins with the quest Kindness. Completion of this quest line will provide an instant reputation boost to neutral. The eggs found in the caves (mostly) and outside the area (rarely) are worth 250-300 rep points each.",
            date = "2010-06-03T13:02:04-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11109#comments:id=1051472",
        },
        {
            id = 1638076,
            score = 5,
            author = "963496",
            text = "It takes about a week or two to get exalted and once exalted you pick one drake as a reward for free then if you want to buy the others you go back to Shadowmoon Valley to purchase them :) And they're only 180 gold each :D",
            date = "2012-03-11T05:08:11-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11109#comments:id=1638076",
        },
        {
            id = 2312691,
            score = 5,
            author = "BadArea52",
            text = "After getting your Free Netherwing Drake from reaching exalted, you can fly back to the daily spot in shadowmoon valley and buy the other drakes for 200g normal vendor price from \"Drake Dealer Hurlunk\" at coordinates 65.6 / 86",
            date = "2016-03-07T16:35:01-06:00",
            sourceUrl = "https://www.wowhead.com/quest=11109#comments:id=2312691",
        },
        {
            id = 320308,
            score = 4,
            author = "159774",
            text = "Jorgus himself is located in Shattrath City (Lower City) at 65, 18. This quest allows you to get a free Netherdrake mount. This paticular mount is the Cobalt Netherwing Drake (http://www.wowhead.com/?item=32859). For details on getting the reputation to obtain this mount check out the faction page (http://www.wowhead.com/?faction=1015). You must have epic flying; this is a 280% mount.",
            date = "2008-07-05T03:45:32-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11109#comments:id=320308",
        },
    },
