    [11111] = {
        {
            id = 685186,
            score = 24,
            author = "146076",
            text = "Yes you do need to be exalted with the Netherwing to be able to get a Nether Drake (in reply to Vcast and Kruzty).\n\nFortunately it is a lot easier than it used to be, at least in terms of player competition and time spent doing the dailies (all drop-dependant dailies like the Fel Glands and Netherwing Relic are 100% drops now). You do still need 5000g spent on your Epic Flying up front to be able to advance past neutral, but a regular flying mount will serve you just fine for the dailies themselves apart from the Dragonmaw Race questline.",
            date = "2009-04-19T19:35:16-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11111#comments:id=685186",
        },
        {
            id = 1402068,
            score = 8,
            author = "794336",
            text = "you must find Mordenai..he wanders around in the netherwing fields..look for all the drakes flying overhead..he starts all the netherwing quests.",
            date = "2011-04-27T21:39:43-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11111#comments:id=1402068",
        },
        {
            id = 2258958,
            score = 8,
            author = "TaliesinC",
            text = "Quick Summary:  Quest line to get Netherwing Drakes begins with \"Mordenai\", a dragonkin in Shadowmoon Valley-Outland.  He usually can be found in the western portion of \"Netherwing Fields\".  Netherwing Fields are just east of The Scryers base \"Sanctum of the Stars\".  Netherwing Fields are also just south and west of The Black Temple.\nFaction Requirement for quest to actually get your first Netherwing Drake from \"Shattrath-Outland\" and to purchase Netherwing Drakes from \"Drake Dealer Hurlunk\" back at \"Netherwing Ledge\" is \"Netherwing - Exalted\".",
            date = "2015-09-30T08:56:10-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11111#comments:id=2258958",
        },
        {
            id = 292905,
            score = 6,
            author = "154356",
            text = "You have to get the Epic (300) Flying mount training before you can even start gaining rep with Netherwing beyond neutral.",
