        },
        {
            id = 1370095,
            score = 6,
            author = "787923",
            text = "Complete requirements:\n\n- level 70\n- Riding at 300\n- Exalted with Netherwing\n\nIt is not \"only\" 5000 gold for the riding skill. You also will need to raise your reputation with Netherwing, which will take approx 3-4 weeks (2 hours a day doing daily's).",
            date = "2011-03-18T13:33:32-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11111#comments:id=1370095",
        },
    },
