    [11451] = {
        {
            id = 196331,
            score = 226,
            author = "51566",
            text = "It is a very moving poem, however the original version is by Mary Frye who supposedly wrote it for a friend who felt unable to visit her mother in Germany because of the anti-Semantic feelings there...\n\nDo not stand at my grave and weep,\nI am not there, I do not sleep.\nI am in a thousand winds that blow,\nI am the softly falling snow.\nI am the gentle showers of rain,\nI am the fields of ripening grain.\nI am in the morning hush,\nI am in the graceful rush\nOf beautiful birds in circling flight,\nI am the starshine of the night.\nI am in the flowers that bloom,\nI am in a quiet room.\nI am in the birds that sing,\nI am in each lovely thing.\nDo not stand at my grave and cry,\nI am not there. I do not die.\n\nI",
            date = "2007-12-05T08:24:18-06:00",
            sourceUrl = "https://www.wowhead.com/quest=11451#comments:id=196331",
        },
        {
            id = 187033,
            score = 152,
            author = "26532",
            text = "This quest is a tribute to a player who died of leukemia.  For more information, see the entry on https://www.wowhead.com/npc=24727.",
            date = "2007-11-18T12:59:00-06:00",
            sourceUrl = "https://www.wowhead.com/quest=11451#comments:id=187033",
        },
        {
            id = 592174,
            score = 107,
            author = "315810",
            text = "Greetings... As I was travelling to Stormwind to check out some items, I noticed this exclamation point in the courtyard, so I went to investigate.  I found this little girl and it puzzled me at first.  I took the quest and the poem and wondered what it was all about.  I checked here and WOW.  After reading the posts, I immediately used Astral Recall and went right to Caylee.\n\nIt was also my 1000th quest turn in.  I had to post this, because its very moving, being a survivor of Cancer twice at the age of 32.\n\nAnd even though I did not know the player personally or in game, I teared up knowing that a company such as Blizzard has done such a beautiful thing.\n\nLife isn't about what you can get out of it, it's what you put into it.",
            date = "2009-02-02T08:51:39-06:00",
            sourceUrl = "https://www.wowhead.com/quest=11451#comments:id=592174",
        },
        {
            id = 191355,
            score = 89,
            author = "102817",
            text = "The quest is to see Caylee Dak who is a memorial for Dak Krause who died of leukemia in August.  His character was named Caylee, and his pet, Dusky, appears with him(well, her and the character was female).\nThe poem was written by a guildie of Dak's named Alicia.\nAlicia went on to petition Blizzard for the memorial and succeeded in gettting herself and her poem into the game as well as Caylee.",
            date = "2007-11-26T02:54:01-06:00",
            sourceUrl = "https://www.wowhead.com/quest=11451#comments:id=191355",
        },
        {
            id = 249745,
            score = 46,
            author = "Baelof",
            text = "I wish Horde could do the quest. :(",
            date = "2008-03-07T16:47:01-06:00",
            sourceUrl = "https://www.wowhead.com/quest=11451#comments:id=249745",
        },
    },
    [11481] = {
        {
            id = 235921,
            score = 21,
            author = "Seregon",
            text = "Aldor starting quest for the Isle of Quel'Danas-quests and a questline leading up to killing Kael'Thas (yes! again!) in the new 5-man instance, The Magister's Terrace.\n\nUpon completion you will receive a Mount Hyjal/BT quality socket gem and be allowed access into the heroic version of the dungeon.",
            date = "2008-02-14T10:32:34-06:00",
            sourceUrl = "https://www.wowhead.com/quest=11481#comments:id=235921",
        },
        {
            id = 261182,
