    [11482] = {
        {
            id = 235922,
            score = 29,
            author = "Seregon",
            text = "Scryer starting quest for the Isle of Quel'Danas-quests and a questline leading up to killing Kael'Thas (yes! again!) in the new 5-man instance, The Magister's Terrace.\n\nUpon completion you will receive a Mount Hyjal/BT quality socket gem and be allowed access into the heroic version of the dungeon.",
            date = "2008-02-14T10:33:09-06:00",
            sourceUrl = "https://www.wowhead.com/quest=11482#comments:id=235922",
        },
        {
            id = 267572,
            score = 21,
            author = "Stompa",
            text = "It may not be clear to everyone; the \"Sunwell Plateau\" is basically the starting area on the Isle of Quel'Danas.  Get there through the portal in the center area of Shattrath, or you can take the flight path that starts from outside Silvermoon City.",
            date = "2008-04-06T19:41:02-05:00",
