    [11496] = {
        {
            id = 234841,
            score = 23,
            author = "MrGorun",
            text = "Collect (4 * Mana Remnants - http://www.wowhead.com/?item=34338), this drop from Wretched Fiend and Wretched Devourer (around /tloc 43,30)\n\nThen go to any Crystal Ward (one of them /tloc 46.4,35.2) and use Mana Remnants (click on it in your bag)\n\nQuest complete on PTR\n\nReceived 9 Gold, 10 Silver.\nReputation with Shattered Sun Offensive increased by 150.",
            date = "2008-02-13T02:53:58-06:00",
            sourceUrl = "https://www.wowhead.com/quest=11496#comments:id=234841",
        },
        {
            id = 262518,
            score = 10,
            author = "Miyari",
            text = "Upon recovering the Sun's Reach Sanctum (completion of phase 1), this quest is replaced by Arm the Wards! (?quest=11523), which has the same objective but is a permanent daily quest that can be completed for reputation and reward, and will always be available once it is unlocked.\n\nFor more information regarding the Shattered Sun Offensive (http://www.wowhead.com/?faction=1077) daily quests and the \"phases\" of reclamation, check out this guide (http://www.wowhead.com/?forums&topic=17960#p155565) on the Wowhead forums! :)",
            date = "2008-03-29T10:32:48-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11496#comments:id=262518",
        },
        {
            id = 261329,
            score = 3,
            author = "Lorielle",
            text = "This quest is pretty simple. The Mana Remnants drop from either the wretched fiend or wretched devourer.\nPersonally, I found the Devourer's had a higher drop rate.\n\nYou can get things done quicker if you do this quest along with\n~Erratic Behavior.~ http://www.wowhead.com/?quest=11524\nBoth mobs needed are found in the same areas, 43, 31.\nOnce you've gathered the 4 mana remnants head over to one of the crystals, big red crystal out side of buildings.\nThe one I use is at 46, 33.\nClick on the remnants in your bag close to the crystal and presto, your finished! =)\n( when you charge it, it does zap you for  a small amount but nothing to really worry about unless you intend on standing there while everyone charges. )\n\nAlexendra~ Detheroc BE Spriest~",
            date = "2008-03-27T17:12:54-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11496#comments:id=261329",
        },
        {
            id = 367144,
            score = 2,
            author = "79592",
            text = "can be found at [46,35]",
            date = "2008-09-01T23:51:15-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11496#comments:id=367144",
        },
        {
            id = 260576,
            score = 0,
            author = "132849",
            text = "Thank you for the guide, very helpful.",
            date = "2008-03-26T20:02:33-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11496#comments:id=260576",
        },
    },
