    [11502] = {
        {
            id = 1440304,
            score = 45,
            author = "733706",
            text = "Previous comments talk about trying to bomb the NPC's, attacking them on the ground, etc.\n\nI killed every guard in this place solo and took control after the longest series of fights I have ever seen in this game.  NONE of that counted toward this quest.  Apparently, unlike similar quests, you have to kill 10 live players to complete it.  That would be impossible on my server. As was previously mentioned, \"no one does Halaa anymore.\"  There is no way to que up for Halaa and it not very likely that you would find any enemy faction players there unless they are trying to take control, as I did, or are turning in the Oshu' crystals.\n\nThe quest needs to be removed or revamped in some way. As it is now, as far as I can see, it is pretty much a dead quest.",
            date = "2011-06-12T23:45:30-05:00",
