    [11505] = {
        {
            id = 921914,
            score = 10,
            author = "11300",
            text = "If the pvp tower icon says time remaining then the towers cannot be capture till the time lapses.  When the towers are capturable it will show red and blue tower icons with a number next ti it.\n\nAlso i believe the towers are only capturable 4 times a day cause the highest time remaining i have seen was 5 hrs 50ish minutes so i am guessing they open for capture bout every 6hrs and only stay capturable for 30 minutes.  If none are capped the tower icon will be grey for 6 hours.",
