    [11515] = {
        {
            id = 3123024,
            score = 76,
            author = "HazardLenz",
            text = "I'm use https://www.wowhead.com/item=97919 for this quest (120 lvl). Don't need die.",
            date = "2019-05-18T05:18:36-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11515#comments:id=3123024",
        },
        {
            id = 3286389,
            score = 67,
            author = "Dervacus",
            text = "I wanted to compile all the good and current information from previous posts into one post as well as my personal experience, so here goes;\n\nRead the whole post before you start to save yourself time and trouble!\n\nNotes:\n\nIf you are overpowered or at level cap please be aware that you must have the toy, Whole-Body Shrinka' (https://www.wowhead.com/item=97919/whole-body-shrinka)\n\nSoft Foam Sword (https://www.wowhead.com/item=137663/soft-foam-sword) will not work and I am not aware of any other way to complete this quest aside from using a character that is closer to the intended level of level 30\n\nFelblood Initiates (https://www.wowhead.com/npc=24918/felblood-initiate) have an extremely long respawn time if killed incorrectly (if killed correctly, they have a respawn time of about 8-15 minutes). To make matters worse, if an overpowered player comes through they may wipe them all out from not knowing how to appropriately do this quest\n\nCompleting this quest may also take considerable time because the effect from Whole-Body Shrinka' (https://www.wowhead.com/item=97919/whole-body-shrinka) only lasts for 3 minutes, makes your running speed much slower and it has a cooldown time of 30 minutes\n\nYou should not have to take Resurrection Sickness (https://www.wowhead.com/spell=15007/resurrection-sickness) or strip your gear for this method to work properly\n\nSteps:\n\nKill Wrath Heralds (https://www.wowhead.com/npc=24919/wrath-herald) and loot 4 Demonic Bloods (https://www.wowhead.com/item=34259/demonic-blood)\n\nAttempt to find 4 Felbood Initiates (https://www.wowhead.com/npc=24918/felblood-initiate) close to each other. This may not be possible\n\nUse Whole-Body Shrinka' (https://www.wowhead.com/item=97919/whole-body-shrinka)\n\nTarget a Felblood Initiate (https://www.wowhead.com/npc=24918/felblood-initiate) and use Fel Siphon (https://www.wowhead.com/item=34257/fel-siphon). Wait for it to channel completely\n\nFelblood Initiate (https://www.wowhead.com/npc=24918/felblood-initiate) will transform into an Emaciated Felblood (https://www.wowhead.com/npc=24955/emaciated-felblood)\n\nKill Emaciated Felblood (https://www.wowhead.com/npc=24955/emaciated-felblood)\n\n While the effect from Whole-Body Shrinka' (https://www.wowhead.com/item=97919/whole-body-shrinka) is still active, run and repeat steps 4 through 6 until you have killed 4 Emaciated Felbloods (https://www.wowhead.com/npc=24955/emaciated-felblood)\n\nTurn in quest\n\nYou may find that you cannot kill all 4 Emaciated Felbloods (https://www.wowhead.com/npc=24955/emaciated-felblood) in one run",
            date = "2021-01-06T02:39:18-06:00",
            sourceUrl = "https://www.wowhead.com/quest=11515#comments:id=3286389",
        },
        {
            id = 2286776,
            score = 65,
            author = "Grammie",
            text = "As of this moment there are no Felblood Initiates - none - NONE - they are all dead and scattered everywhere...no one respawns...",
            date = "2015-12-11T20:36:25-06:00",
            sourceUrl = "https://www.wowhead.com/quest=11515#comments:id=2286776",
        },
        {
            id = 236709,
            score = 58,
            author = "33464",
            text = "Felblood Initiates (70+) spawn at the Throne of Kil'jaeden around the Suspended Terrorguards.  Kill nearby Wrath Heralds for the Demon Blood needed to \"Use\" the Fel Siphon on the Initiates\n\nStart your attack with a damage spell or dot and then \"use\" the siphon - this stuns them for several seconds, and they then become non-elite Emaciated Felbloods.",
            date = "2008-02-15T13:26:31-06:00",
            sourceUrl = "https://www.wowhead.com/quest=11515#comments:id=236709",
        },
        {
            id = 2583407,
            score = 53,
            author = "1892254",
            text = "As of BFA pre patch the only way to complete the q was to take of all gear and get ress sicknes so i dont instantly kill the npc",
            date = "2018-07-22T03:32:15-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11515#comments:id=2583407",
        },
    },
    [11516] = {
        {
            id = 237400,
            score = 95,
            author = "39608",
            text = "Magistrix Seyla is located at 58,18.\n\nShe gives you the item called Sizzling Embers, right click it to summon the quest pet. Then go kill the Fel Sparks in the surrounding area and as you do, the quest pet will continue to grow larger.\n\nEventually the pet will turn into am Unstable Fel Spark which is the same color as the Fel Sparks. When you reach this point, go and stand in the gateway new Magistrix Seyla and the pet will slowly move to the gateway and blow up which will complete the quest.",
            date = "2008-02-16T13:04:43-06:00",
            sourceUrl = "https://www.wowhead.com/quest=11516#comments:id=237400",
        },
        {
            id = 260510,
            score = 60,
            author = "54527",
            text = "Some quick things to note about this quest:\n\nTo complete the quest, you need to take the Unstable Living Flare to the gate at 58,18, where you got teleported as part of the initial quest The Missing Magistrix (http://www.wowhead.com/?quest=11526).\nIt takes about eight kills of Incandescent Fel Sparks for the Living Flare (http://www.wowhead.com/?npc=24916) to be fully charged to its Unstable Living Flare (http://www.wowhead.com/?npc=24958) state.\nYou do not need to land the killing blow, nor have tagged the Fel Spark to get the kill to register on your flare.  You just need to be within ten yards or so.\nThe flare will not despawn if you mount on either a land or flying mount.  You also do not need to dismount for the flare to trigger the explosion at the gate.\nThe flare will despawn and lose all charges when you get killed and you will need to start again.\nThe flare will also despawn and lose all charges if you summon a different minipet or one of the JCing trinket pets.  My shaman uses Nightseye Panther, and the little panther it summons when I use the trinket was causing the pet to despawn.",
            date = "2008-03-26T18:31:38-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11516#comments:id=260510",
        },
        {
            id = 241378,
            score = 36,
            author = "Norrec",
            text = "Please note that you don't need to have the kill count on those mob, standing near a dying Fel-spark (http://www.wowhead.com/?npc=22323) is sufficient to growth your Living flare (http://www.wowhead.com/?npc=24916)",
            date = "2008-02-22T11:56:54-06:00",
            sourceUrl = "https://www.wowhead.com/quest=11516#comments:id=241378",
        },
        {
            id = 258699,
            score = 23,
            author = "voodoo",
            text = "Be careful with your charged Living Flare - I lost mine twice and had to start over. If you have to re-summon it, it is uncharged again.\n\nThe first time I lost it because I used my flying mount (it sticks around for a while, probably while you're close to the ground, but don't fly too high). The second time I aggroed Kazzak because a Nightmare Vine was too close :)",
            date = "2008-03-24T13:45:45-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11516#comments:id=258699",
        },
        {
            id = 1419870,
            score = 18,
            author = "130064",
            text = "The gateway is RIGHT BESIDE Magistrix Seyla. *sigh* The arrow on the mini map was sending me to the wrong place. I spent 15 minutes trying to find the portal.",
            date = "2011-05-15T22:40:30-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11516#comments:id=1419870",
        },
    },
    [11517] = {
        {
            id = 261190,
            score = 11,
            author = "Telex",
            text = "This quest leads you to Exarch Nasuun (http://www.wowhead.com/?npc=24932). He then gives you a new daily quest -- Intercepting the Mana Cells (http://www.wowhead.com/?quest=11513).",
            date = "2008-03-27T14:09:46-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11517#comments:id=261190",
        },
    },
    [11520] = {
        {
            id = 244853,
            score = 110,
            author = "GoGoGodzilla",
            text = "This is a very odd but fun quest.\n\nRazorthorn Rise is located just north of Razorthorn Shelf between Terokkar Forest and Hellfire Peninsula.  Razorthorn Shelf was the location of the level 60 quest where players had to pick up Razorthorn eggs.\n\nThe goal of this quest is the razorthorn plant, which is buried beneath mounds of dirt (both pictured).  You have to get under the dirt to get to the root, but to do so, you need the Razorthorn Ravagers in the area to dig it up for you.\n\nTo get the Razorthorn Ravagers, you must obtain a Razorthorn Flayer Gland (http://www.wowhead.com/?item=34255) from the Razorthorn Flayers (http://www.wowhead.com/?npc=24920) which are in the area.\n\nHow does all this work?\n\nYou must kill the Flayer, loot the gland, use the gland on the Ravager and suddenly you're a hunter, with your own ravager pet.  Use the pet abilities (which appear above your hot bars like a normal hunter pet) to dig up the dirt, then loot the root.  It works like a normal hunter pet, too, so CTRL-1 will cause the pet to attack whatever you target.\n\nThe pet will stick with you for a while.  I was able to get all my roots with only one pet (and therefore only one gland) and have plenty of time to spare.  Once you fly out of the area, the pet will despawn (else, follow you on the ground and die or just follow you until you reach the edge of the area).\n\nTotally easy quest.\n\nI should add that the coordinates for the flayers are at about 31.5, 84.0 if you're on the Hellfire Peninsula map or 60.0, 11.0 if you're on the Terokkar Forest map; the whole ridge along this section is covered in them.  I also strongly suspect (I am a shaman and therefore cannot prove this) that if you're a hunter your pet will have to be put away.\n\nA question to a hunter:\nI'm curious if there is a hunter out there who could answer this question.\n\nIf you tame this pet, does it retain its ability to dig up the roots? - Answer (by Frostfel) - No!  You do not get the ability.\n\nThanks, Frostfel!",
            date = "2008-02-28T03:11:57-06:00",
            sourceUrl = "https://www.wowhead.com/quest=11520#comments:id=244853",
        },
        {
            id = 262549,
            score = 39,
            author = "Miyari",
            text = "Upon completed construction of the alchemy lab (during phase 4), this quest is replaced by Rediscovering Your Roots (?quest=11521), which has the same objective but is a permanent daily quest that can be completed for reputation and reward, and will always be available once it is unlocked.\n\nFor more information regarding the Shattered Sun Offensive (http://www.wowhead.com/?faction=1077) daily quests and the \"phases\" of reclamation, check out this guide (http://www.wowhead.com/?forums&topic=17960#p155565) on the Wowhead forums! :)",
            date = "2008-03-29T11:01:24-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11520#comments:id=262549",
        },
        {
            id = 274429,
            score = 24,
            author = "27601",
            text = "Terokkar Forest: Razorthorn Rise (47, 7)",
            date = "2008-04-19T20:06:19-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11520#comments:id=274429",
        },
        {
            id = 276349,
            score = 23,
            author = "70039",
            text = "A Flying Mount is a MUST!  There is no way to get to the Flayers w/o one",
            date = "2008-04-23T15:28:15-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11520#comments:id=276349",
        },
        {
            id = 275561,
            score = 8,
            author = "105251",
            text = "These ravagers act just like a normal hunter pet, for the most part. As a Beast Master hunter, I was able to use The Beast Within/Bestial Wrath, as well as Intimidate while controlling the ravager. Very nice!\n\nThe only normal skill that didn't seem to work was Kill command.",
            date = "2008-04-22T01:41:07-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11520#comments:id=275561",
        },
    },
    [11521] = {
        {
            id = 256879,
            score = 498,
            author = "yumari",
            text = "Razorthorn Rise is just north of Veil Reskk, between Hellfire Peninsula and Shattarah. (53,13)\n\nIn order to do this quest you must first kill the https://www.wowhead.com/npc=24920s until a https://www.wowhead.com/item=34255 drops.  Use the gland on a https://www.wowhead.com/npc=24922.  The https://www.wowhead.com/npc=24922 will then become \"charmed\" and act as a pet.\n\nYou will get a pet bar with an ability called https://www.wowhead.com/spell=44935.  You can find these roots by getting close to a Razorthorn Dirt Mound and clicking the ability.\n\nThe Razorthorn Dirt Mounds look like the Un'Goro Dirt Piles (http://www.wowhead.com/?object=157936), except they're lighter.\n\nRate up if this post helped you.",
            date = "2008-03-21T08:42:42-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11521#comments:id=256879",
        },
        {
            id = 262550,
