    [11535] = {
        {
            id = 262533,
            score = 17,
            author = "Miyari",
            text = "Upon completed construction of the forge and anvil (during phase 3), this quest is replaced by Don't Stop Now... (?quest=11536), which has the same objective but is a permanent daily quest that can be completed for reputation and reward, and will always be available once it is unlocked. Also, it is at this point that Smith Hauthaa will start selling her coveted Badge of Justice (?item=29434) rewards.\n\nFor more information regarding the Shattered Sun Offensive (http://www.wowhead.com/?faction=1077) daily quests and the \"phases\" of reclamation, check out this guide (http://www.wowhead.com/?forums&topic=17960#p155565) on the Wowhead forums! :)",
            date = "2008-03-29T10:46:12-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11535#comments:id=262533",
        },
        {
            id = 267729,
            score = 12,
            author = "18330",
            text = "The Myrmidons and the Sirens share spawn points.  If there are no myrmidons nearby kill the sirens for more respawns.",
            date = "2008-04-07T03:01:54-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11535#comments:id=267729",
        },
        {
            id = 266888,
            score = 7,
            author = "108241",
            text = "Keep in mine that onle the Darkspine Myrmidons not the  Darkspine Sirens drops the keys! They're easy to tell apart. (Only the 'male' naga drops the keys, not the females)\nSo if you're camping a spawn, make sure its a myrmidon. x_X\n\nI learned this the hard way.\n\nOn edit: I learned something else the hard way.. If you open a chest, but you don't get the thing inside it (So far, it's been 100% on the ore for me), you'll still lose a key. So make sure you're inventory isn't full on opening + looting ><",
            date = "2008-04-05T15:30:17-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11535#comments:id=266888",
        },
        {
            id = 269951,
            score = 4,
            author = "ceviz",
            text = "Personal experience:\n\nBlizz should spread their area and add more of them cause lots of peeps farming them.\nDrop rate is too low\n\nI wonder if rogues can open that lockboxes:S",
            date = "2008-04-11T01:25:43-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11535#comments:id=269951",
        },
        {
            id = 270083,
            score = 4,
            author = "67767",
            text = "My personal expirience is that the area at the beggining of the shore is overfarmed while the western part of it is totally crowdless.So my advice is to go west and there you will find lots of myrmidons.Good luck in your daily!",
            date = "2008-04-11T08:37:00-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11535#comments:id=270083",
        },
    },
    [11536] = {
        {
            id = 262532,
            score = 23,
            author = "Miyari",
            text = "Upon completed construction of the forge and anvil (during phase 3), this quest replaces Making Ready (?quest=11535), and has the same objective but is a permanent daily quest that can be completed for reputation and reward, and will always be available once it is unlocked. Also, it is at this point that Smith Hauthaa (?npc=25046) will start selling her coveted Badge of Justice (?item=29434) rewards.\n\nFor more information regarding the Shattered Sun Offensive (http://www.wowhead.com/?faction=1077) daily quests and the \"phases\" of reclamation, check out this guide (http://www.wowhead.com/?forums&topic=17960#p155565) on the Wowhead forums! :)",
            date = "2008-03-29T10:45:58-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11536#comments:id=262532",
        },
        {
            id = 288276,
            score = 12,
            author = "117045",
            text = "You need to visit Greengill Coast, so do this quest with Disrupt the Greengill (http://www.wowhead.com/?quest=11541) Coast and Know Your Ley Lines (http://www.wowhead.com/?quest=11547) (I mean taking the Shrine Reading).",
            date = "2008-05-14T17:48:32-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11536#comments:id=288276",
        },
        {
            id = 272957,
            score = 8,
            author = "11141",
            text = "kill Darkspine Myrmidon (http://www.wowhead.com/?npc=25060) starting around [59, 42] and go south. after you collect 3 keys, use them to open the small lock boxes around the trees. i found mine at [59, 51] , [61, 49] and [63, 50]",
            date = "2008-04-16T20:55:35-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11536#comments:id=272957",
        },
        {
            id = 886098,
            score = 7,
            author = "468940",
            text = "Anyone notice how suggestive this quest sounds, especially coming from a female Draenei?",
            date = "2009-11-08T17:34:14-06:00",
            sourceUrl = "https://www.wowhead.com/quest=11536#comments:id=886098",
        },
        {
            id = 319408,
            score = 5,
            author = "Geoff",
            text = "For any protection paladins out there finding some of the SSO dailies to be a pain, I just discovered a nifty little trick for this and Disrupt The Greengill Coast (http://www.wowhead.com/?quest=11541)\n\nSince the murloc slaves have more HP than you would expect, and as cruel as it would seem (gonna get some hate off some of you murloc lovers out there), put consecration down to get the murlocs attacking you while you fight the nagas with a decent 2-hander, as they will help to proc reckoning. :]\n\nFound that this kinda helped speed things up a tiny bit. :]",
            date = "2008-07-03T22:39:36-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11536#comments:id=319408",
        },
    },
