    [11538] = {
        {
            id = 251412,
            score = 24,
            author = "134734",
            text = "If you can find an Emissary corpse just lying around, you can impale that one instead of summoning your own after killing enough demons around the portal.",
            date = "2008-03-10T20:26:48-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11538#comments:id=251412",
        },
        {
            id = 236486,
            score = 20,
            author = "47687",
            text = "Emissary of hate can be found at 49,45; near the portal",
            date = "2008-02-15T05:55:50-06:00",
            sourceUrl = "https://www.wowhead.com/quest=11538#comments:id=236486",
        },
        {
            id = 261347,
            score = 18,
            author = "Lorielle",
            text = "This quest shouldn't take more then 5 minutes to complete.\n\nKill any demons you find near the portal, spawn times are very fast. Coords are 49, 45.\nOnce you've killed the six then keep an eye out for the Emissary of hate. You do NOT have to kill him to impale him.\n( I was out there for half an hour trying to get him as he spawned unaware I could just impale him when he was killed )\n\nJust find him corpse and impale him, then your done.\n\nThis daily is not available until phase 2.\n\nAlexendra ~ Detheroc BE Spriest ~",
            date = "2008-03-27T17:33:36-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11538#comments:id=261347",
        },
        {
            id = 260961,
            score = 14,
            author = "wingman",
            text = "Just the clarify, for the 6 slains, they can be any type of demons around the portals.",
            date = "2008-03-27T08:26:48-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11538#comments:id=260961",
        },
        {
            id = 262526,
            score = 12,
            author = "Miyari",
            text = "Upon recovering the Sun's Reach Armory (completion of phase 2), this quest is replaced by The Battle Must Go On (?quest=11537), which has the same objective but is a permanent daily quest that can be completed for reputation and reward, and will always be available once it is unlocked.\n\nFor more information regarding the Shattered Sun Offensive (http://www.wowhead.com/?faction=1077) daily quests and the \"phases\" of reclamation, check out this guide (http://www.wowhead.com/?forums&topic=17960#p155565) on the Wowhead forums! :)",
            date = "2008-03-29T10:39:15-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11538#comments:id=262526",
        },
    },
    [11539] = {
        {
            id = 260499,
            score = 11,
            author = "31780",
            text = "From the very beginning, there are five Outlands dailies that can be done for the Offensive. Those dailies should always be available. I don't know if they assist in reclaiming the various areas in Sun's Reach.\n* http://www.wowhead.com/?quest=11875 - Gaining the Advantage\n* http://www.wowhead.com/?quest=11877 - Sunfury Attack Plans\n* http://www.wowhead.com/?quest=11880 - The Multi-Whatever Something-or-Other Survey\n* http://www.wowhead.com/?quest=11515 - Blood for Blood\n* http://www.wowhead.com/?quest=11516 - Blast the Gateway\n\nFor the actual reclamation project and the dailies associated with each phase. Note that some of the dailies can still be completed after they finish, replacements are marked with a ---\n\nPhase 1 - Recovering Sun's Reach Sanctum\n* http://www.wowhead.com/?quest=11524 - Erratic Behavior\n* http://www.wowhead.com/?quest=11496 - The Sanctum Wards\n\nPhase 2 - Recovering Sun's Reach Armory\n* http://www.wowhead.com/?quest=11525 - Further Conversions (Replacing Erratic Behavior)\n* http://www.wowhead.com/?quest=11523 - Arm the Wards (Replacing The Sanctum Wards)\n* http://www.wowhead.com/?quest=11532 - Distraction at the Dead Scar\n* http://www.wowhead.com/?quest=11538 - The Battle of the Sun's Reach Armory\n\nPhase 2a - Building the portal to the Sunwell from Shattrath\n* http://www.wowhead.com/?quest=11513 - Intercepting the Mana Cells\n--- http://www.wowhead.com/?quest=11514 - Maintaining the Sunwell Portal\n--- http://www.wowhead.com/?quest=11547 - Know Your Ley Lines - This is logically where the quest would go, but it is unknown at the moment.\n\nPhase 3 - Recovering the Sun's Reach Harbor (All of this is speculation)\n* http://www.wowhead.com/?quest=11533 - The Air Strikes Must Continue (Replacing Distraction at the Dead Scar)\n* http://www.wowhead.com/?quest=11537 - The Battle Must Go On (Replacing The Battle of the Sun's Reach Armory)\n* http://www.wowhead.com/?quest=11542 - Intercepting the Reinforcements\n* http://www.wowhead.com/?quest=11539 - Taking the Harbor\n* http://www.wowhead.com/?quest=11535 - Making Ready - Creates the blacksmith and armor/weapons vendor.\n--- http://www.wowhead.com/?quest=11536 - Don't Stop Now\n\nPhase 4 - Finishing the City\n* http://www.wowhead.com/?quest=11543 - Keeping the Enemy at Bay (Replaces Intercepting the Reinforcements)\n* http://www.wowhead.com/?quest=11540 - Crush the Dawnblade (Replaces Taking the Harbor)\n* http://www.wowhead.com/?quest=11520 - Discovering Your Roots - Creates a reagent/special items vendor\n--- http://www.wowhead.com/?quest=11521 - Rediscovering your Roots\n* http://www.wowhead.com/?quest=11546 - Open for Business - Is unlocked when Discovering Your Roots is completed\n* http://www.wowhead.com/?quest=11541 - Disrupt the Greengill Coast\n* http://www.wowhead.com/?quest=11545 - A Charitable Donation - Helps build a monument\n--- http://www.wowhead.com/?quest=11548 - Your Continued Support\n\nhttp://www.wowhead.com/?quest=11549 - A Magnanimous Benefactor can only be done during the \"A Charitable Donation\" portion. For a 1000 gold, and probably an Exalted reputation requirement, the \"of the Shattered Sun\" title can be obtained.\n\n(Thank you Copernicus of Tichondrius)",
            date = "2008-03-26T18:19:53-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11539#comments:id=260499",
        },
        {
            id = 262541,
            score = 7,
            author = "Miyari",
            text = "Upon recovering the Sun's Reach Harbor (completion of phase 3), this quest is replaced by Crush the Dawnblade (?quest=11540), which has the same objective but is a permanent daily quest that can be completed for reputation and reward, and will always be available once it is unlocked.\n\nFor more information regarding the Shattered Sun Offensive (http://www.wowhead.com/?faction=1077) daily quests and the \"phases\" of reclamation, check out this guide (http://www.wowhead.com/?forums&topic=17960#p155565) on the Wowhead forums! :)",
            date = "2008-03-29T10:55:06-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11539#comments:id=262541",
        },
        {
            id = 269880,
            score = 4,
            author = "43524",
            text = "I'd suggest going to the building in Dawnstar Village where you take the Bloodcrystal reading.\n\nOn the second level of this building there are four Dawnblade Summoners who spawn without imp companions, which makes them less of a pain to kill.\n\nPlus there are Marksmen and Blood Knights around here too.",
            date = "2008-04-10T21:32:45-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11539#comments:id=269880",
        },
        {
            id = 367140,
            score = 2,
            author = "79592",
            text = "[50,34] and [43,37] is the best place's for this daily",
            date = "2008-09-01T23:45:23-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11539#comments:id=367140",
        },
        {
            id = 267354,
            score = 1,
            author = "6969",
            text = "The mobs are all over the place, inhabiting the buildings and such.",
            date = "2008-04-06T11:27:43-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11539#comments:id=267354",
        },
    },
