    [11541] = {
        {
            id = 262130,
            score = 60,
            author = "aetius",
            text = "Saving murlocs goes against everything I stand for!",
            date = "2008-03-28T17:47:44-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11541#comments:id=262130",
        },
        {
            id = 248832,
            score = 26,
            author = "134734",
            text = "The item the Sirens drop is called the Orb of Murloc Control. To free the murlocs, you need to \"bomb\" the orb on the murlocs, pretty much like aerial bombing, but on foot. Then the best part...they run over to the nearest Myrmidon and start attacking him.",
            date = "2008-03-06T03:56:57-06:00",
            sourceUrl = "https://www.wowhead.com/quest=11541#comments:id=248832",
        },
        {
            id = 262547,
            score = 14,
            author = "Miyari",
            text = "Upon beginning construction of the alchemy lab (during phase 4), this quest becomes available and is a permanent daily quest that can be completed for reputation and reward, and will always be available once it is unlocked.\n\nFor more information regarding the Shattered Sun Offensive (http://www.wowhead.com/?faction=1077) daily quests and the \"phases\" of reclamation, check out this guide (http://www.wowhead.com/?forums&topic=17960#p155565) on the Wowhead forums! :)",
            date = "2008-03-29T10:59:39-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11541#comments:id=262547",
        },
        {
            id = 288279,
            score = 9,
            author = "117045",
            text = "You need to visit Greengill Coast, so do this quest with Don't Stop Now.... (http://www.wowhead.com/?quest=11536) and Know Your Ley Lines (http://www.wowhead.com/?quest=11547) (I mean taking the Shrine Reading).",
            date = "2008-05-14T17:52:00-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11541#comments:id=288279",
        },
        {
            id = 274366,
            score = 8,
            author = "Liquids",
            text = "The item used in this quest is Orb of Murloc Control (http://www.wowhead.com/?item=34483) and drops from Darkspine Siren (http://www.wowhead.com/?npc=25073). It appears to be a 100% drop.\n\nYou can carry 10 orbs at a time so it is possible to collect a few and then go and release the murlocs, if you prefer.\n\nDepending on how many murlocs you hit with each orb you will need between 2 and 5 orbs for this quest. So the quest is quite quick to complete.",
            date = "2008-04-19T17:34:53-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11541#comments:id=274366",
        },
    },
    [11542] = {
        {
            id = 267070,
            score = 20,
            author = "56884",
            text = "Here's how to complete the quest:\n\n-Go over to the Dragonhawk flight master (the same one you start the bombing run over The Dead Scar).\n\n-Select the bombing run option.\n\n-Make sure you have the bomb in your bag and ready to fire.\n\n-You fly by each ship (as seen in the screenshot). Throw one bomb onto each ship. One bomb will give you credit for the ship.\n\n-Once you land, start killing the Reservists on the ship. If one ship is entirely full, try one of the other two.\n\n-Once done, go back to the original ship you landed on. There will be a Dragonhawk there. Talk to it, and select \"Take me back\".\n\n-Turn it in and enjoy the rewards.",
            date = "2008-04-05T20:51:07-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11542#comments:id=267070",
        },
        {
            id = 262544,
            score = 14,
            author = "Miyari",
            text = "Upon recovering the Sun's Reach Harbor (completion of phase 3), this quest is replaced by Keeping the Enemy at Bay (?quest=11543), which has the same objective but is a permanent daily quest that can be completed for reputation and reward, and will always be available once it is unlocked.\n\nFor more information regarding the Shattered Sun Offensive (http://www.wowhead.com/?faction=1077) daily quests and the \"phases\" of reclamation, check out this guide (http://www.wowhead.com/?forums&topic=17960#p155565) on the Wowhead forums! :)",
            date = "2008-03-29T10:56:42-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11542#comments:id=262544",
        },
        {
            id = 251408,
            score = 8,
            author = "134734",
            text = "If there are too many people on the middle ship, just swim over to one of the other 2 ship and walk up their side ramps to kill the Reservists. Then swim back to use the Dragonhawk to fly back. Like many other DQs in the area, this one should be quick.",
            date = "2008-03-10T20:14:33-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11542#comments:id=251408",
        },
        {
            id = 268140,
            score = 5,
            author = "4334",
            text = "Feel free to group with anybody in your faction that you see doing the part where you kill guys on the boat. It will go faster.",
            date = "2008-04-07T16:38:01-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11542#comments:id=268140",
        },
        {
            id = 267073,
            score = 4,
            author = "121353",
            text = "Take a dragonhawk from NPC Ayren Cloudbreaker at the dock. It will fly you over the 3 ships to bomb the sails, then it will land you on the middle ship. Then kill 6 Dawnblade Reservist's on any of the 3 ships. You can swim back, or go back to the middle ship where there is a Dragonhawk who will offer to fly you back to Sun's Reach Harbor's dock.",
            date = "2008-04-05T20:55:25-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11542#comments:id=267073",
        },
    },
    [11543] = {
        {
            id = 278969,
            score = 32,
            author = "147080",
            text = "Ayren Cloudbreaker is at 48.5 25.3",
            date = "2008-04-28T22:09:04-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11543#comments:id=278969",
        },
        {
            id = 248442,
            score = 16,
            author = "50792",
            text = "You will fly on a predetermined path over 3 blood elf boats, activate the quest item to target the sails and  to set them on fire. Your mount will then land on one of the boats allowing you to kill Belfs on them. The number of Belfs is limited, so you may need to swim to the other boats to get your kill quota. Conviniently the boats have outriggers that allow you to board them from the water. You can then retun to the island by way of the dragon hawk in the boat you land on, you wont be able to do this if you are in combat.",
            date = "2008-03-05T11:58:47-06:00",
            sourceUrl = "https://www.wowhead.com/quest=11543#comments:id=248442",
        },
        {
            id = 262543,
            score = 15,
            author = "Miyari",
            text = "Upon recovering the Sun's Reach Harbor (completion of phase 3), this quest replaces Intercept the Reinforcements (?quest=11542), and has the same objective but is a permanent daily quest that can be completed for reputation and reward, and will always be available once it is unlocked.\n\nFor more information regarding the Shattered Sun Offensive (http://www.wowhead.com/?faction=1077) daily quests and the \"phases\" of reclamation, check out this guide (http://www.wowhead.com/?forums&topic=17960#p155565) on the Wowhead forums! :)",
            date = "2008-03-29T10:56:34-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11543#comments:id=262543",
        },
        {
            id = 3222816,
            score = 8,
            author = "greenfuneral",
            text = "I saw a comment saying you have to be in the boats' respective zones to get the quest to register your progress. I found this to be untrue (at least in 8.3) because even when I would be in the right zone, the quest would still not register my progress all the time. So here is what I have figured out after a couple of days of frustratingly having to fly over the boats like 3 times:\nTake the quest requirement literally and hit the actual sails of the boats. Put that green circle on the sail and not the deck. You don't have to be in the specific zone and it will still register.",
            date = "2020-08-13T02:08:47-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11543#comments:id=3222816",
        },
        {
            id = 555579,
            score = 4,
            author = "300776",
            text = "please correct me if im wrong but it would seem that the boat that the dragon hawk takes you to has exactly 6 Dawnblade Reservist's on it. at least it was that way for me. maybe diffrent of someone did it just before you but otherwise there should be just enough of them to complete the quest.",
            date = "2009-01-10T01:13:27-06:00",
            sourceUrl = "https://www.wowhead.com/quest=11543#comments:id=555579",
        },
    },
    [11544] = {
        {
            id = 239688,
            score = 134,
            author = "Discover",
            text = "As the quest says, you can find the Ata'mal Armaments (http://www.wowhead.com/?item=34500) off of the Shadowmoon Valley orcs (http://www.wowhead.com/?npcs=7&filter=na=Shadowmoon;ta=Servant+of+Illidan;cr=6:12;crs=3520:1;crv=0:1) in Ata'mal Terrace all around 70,40.\n\nAfter you are finished gathering 5, go to the anvil located at 50,40 on Isle of Quel'Danas (next to the quest giver) and use the item.",
            date = "2008-02-19T18:11:31-06:00",
            sourceUrl = "https://www.wowhead.com/quest=11544#comments:id=239688",
        },
        {
            id = 262535,
            score = 37,
            author = "Miyari",
            text = "Upon completed construction of the forge and anvil (during phase 3), this quest becomes available and is a permanent daily quest that can be completed for reputation and reward, and will always be available once it is unlocked. Also, it is at this point that Smith Hauthaa will start selling her coveted Badge of Justice (?item=29434) rewards.\n\nFor more information regarding the Shattered Sun Offensive (http://www.wowhead.com/?faction=1077) daily quests and the \"phases\" of reclamation, check out this guide (http://www.wowhead.com/?forums&topic=17960#p155565) on the Wowhead forums! :)",
            date = "2008-03-29T10:47:14-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11544#comments:id=262535",
        },
        {
            id = 272144,
            score = 10,
            author = "Dallmine",
            text = "The weapon coating will not be able to be used in conjunction with WF.",
            date = "2008-04-15T09:35:35-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11544#comments:id=272144",
        },
        {
            id = 6026028,
            score = 10,
            author = "thePurplePack",
            text = "Head to Outland, Shadowmoon Valley to gather 5 x Ata'mal Armaments (https://www.wowhead.com/item=34500/atamal-armament) then return to  Isle of Quel'Danas and use the cleans the items at the anvil\n\n/way #104 70 40 Orcs drop Ata'mal Armaments\n/way #122 50.58 40.73 Anvil\n\nStay kind!",
            date = "2024-12-13T05:18:28-06:00",
            sourceUrl = "https://www.wowhead.com/quest=11544#comments:id=6026028",
        },
        {
            id = 296874,
            score = 7,
            author = "MoonLite",
            text = "Beware the big Shadowsworn Drakonid (http://www.wowhead.com/?npc=22072) patrolling the area, they're doable 1 on 1, but you don't want them joining a fight already going on.\nThey have quite large patrol routes so you'll have about 2minutes before it goes from one end to the other and back.\n\nAlso, as protection paladin, I find I can go to SMV (66.6,38.4) , wait for the big drakonid to move up towards the stairs, then mount up, run south down the ramp from there (towards the naaru below), pulling 9 Shadowmoon Slayer (http://www.wowhead.com/?npc=22082) .\nPut up Blessing of Sanctuary and keep Holy Shield and Consecration up and you'll have them all down in about 30seconds, and get all your 5 armaments in just 1 fight.\n\nI only just turned 70 in mostly green/blue gear (half Crusader's Ornamented Battlegear set, easy to get early) to pull this off without much risk.",
            date = "2008-05-30T01:13:05-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11544#comments:id=296874",
        },
    },
    [11545] = {
        {
            id = 262554,
            score = 24,
            author = "Miyari",
