    [11546] = {
        {
            id = 262546,
            score = 33,
            author = "Miyari",
            text = "Upon completed construction of the alchemy lab (during phase 4), this quest becomes available and is a permanent daily quest that can be completed for reputation and reward, and will always be available once it is unlocked.\n\nFor more information regarding the Shattered Sun Offensive (http://www.wowhead.com/?faction=1077) daily quests and the \"phases\" of reclamation, check out this guide (http://www.wowhead.com/?forums&topic=17960#p155565) on the Wowhead forums! :)",
            date = "2008-03-29T10:58:43-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11546#comments:id=262546",
        },
        {
            id = 248830,
            score = 19,
            author = "134734",
            text = "Took me about 3 minutes to do this quest, got all 5 on the northern area of the Isle of Quel'Danas. Where it says it grows all over Azeroth may be ambiguous though. Easily supplements the Sanctum Wards and Erratic Sentries quests.",
            date = "2008-03-06T03:42:09-06:00",
            sourceUrl = "https://www.wowhead.com/quest=11546#comments:id=248830",
        },
        {
            id = 273361,
            score = 11,
            author = "54558",
            text = "Where it says it grows all over Azeroth may be ambiguous though\n\nIf you read the quest, it says that the berries grow across Azeroth, but the Sunwell mutates the berries. I guess these are the same ones as you can find in The BE starting area, just the level 70 version",
            date = "2008-04-17T17:35:02-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11546#comments:id=273361",
        },
        {
            id = 291320,
            score = 8,
            author = "Vandamme",
            text = "If you happen to be an herbalist these show up on your minimap for easy finding.",
            date = "2008-05-20T02:32:06-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11546#comments:id=291320",
        },
        {
            id = 318367,
            score = 4,
            author = "113672",
            text = "I recommend getting this quest at the same time you get the first two Erratic Behavior (http://www.wowhead.com/?quest=11524) and The Sanctum Wards (http://www.wowhead.com/?quest=11496). You can easily complete this with those to save yourself some time.",
            date = "2008-07-02T17:13:23-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11546#comments:id=318367",
        },
    },
    [11547] = {
        {
            id = 240118,
            score = 123,
            author = "Null",
            text = "Portal: 48,44\nShrine: 61, 62\nBloodcrystal: 42,35\n\nReward is consumed after one use.",
            date = "2008-02-20T11:31:48-06:00",
            sourceUrl = "https://www.wowhead.com/quest=11547#comments:id=240118",
        },
        {
            id = 262537,
            score = 47,
            author = "Miyari",
            text = "Upon completion of the Sunwell Portal (a portal from Shattrath City (?zone=3703) to the Isle of Quel'Danas (?zone=4080)) during phase 2, this quest becomes available and is a permanent daily quest that can be completed for reputation and reward, and will always be available once it is unlocked.\n\nFor more information regarding the Shattered Sun Offensive (http://www.wowhead.com/?faction=1077) daily quests and the \"phases\" of reclamation, check out this guide (http://www.wowhead.com/?forums&topic=17960#p155565) on the Wowhead forums! :)",
            date = "2008-03-29T10:50:32-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11547#comments:id=262537",
        },
        {
            id = 266793,
            score = 19,
            author = "141455",
            text = "You can only posess one Darnarian's Scroll of Teleportation at a time. If you already have one (even if it's in the bank) you will be unable to turn in the quest.",
            date = "2008-04-05T11:22:38-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11547#comments:id=266793",
        },
        {
            id = 270011,
            score = 13,
            author = "24364",
            text = "Here you have a handy map of the points needed to read:\nhttp://www.wowhead.com/?maps=4080:418353485450616619",
            date = "2008-04-11T04:45:45-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11547#comments:id=270011",
        },
        {
            id = 625284,
