            text = "FYI, this does not count towards the Loremaster of Eastern Kingdoms achievement.",
            date = "2009-02-27T12:50:25-06:00",
            sourceUrl = "https://www.wowhead.com/quest=11547#comments:id=625284",
        },
    },
    [11548] = {
        {
            id = 385720,
            score = 43,
            author = "126544",
            text = "i dont do for rep i do for the orpahns",
            date = "2008-09-23T19:28:21-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11548#comments:id=385720",
        },
        {
            id = 262210,
            score = 31,
            author = "1646",
            text = "This quest will increase your reputation with Shattered Sun Offensive by 150. With the high rate of reputation gain with the Shattered Sun it is suggested that you hold on to your gold. Completing this quest every day for 2 weeks would still not even give as much reputation as a single day’s worth of the 10 Isle daily quests.",
            date = "2008-03-28T21:24:46-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11548#comments:id=262210",
        },
        {
            id = 366848,
            score = 22,
            author = "170695",
            text = "Neutral to Friendly- 20 days and 200 gold.\nFriendly to Honored- 40 days and 400 gold.\nHonored to Revered- 80 days and 800 gold.\nRevered to Exalted- 140 days and 1400 gold.\nTotal- 280 days and 2800 gold\n\nIt is quite possible to get Exalted doing only this, but it would take almost a whole year. I suggest you don't try this.",
            date = "2008-09-01T14:16:17-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11548#comments:id=366848",
        },
        {
            id = 269188,
            score = 18,
            author = "Lycentia",
            text = "From WoWWiki (http://www.wowwiki.com/Quest:Your_Continued_Support): Players who are exalted with the Offensive will not see this quest.",
            date = "2008-04-09T13:18:41-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11548#comments:id=269188",
        },
        {
            id = 262552,
            score = 15,
            author = "Miyari",
            text = "Upon completed construction of the monument to the fallen (during phase 4), this quest replaces A Charitable Donation (?quest=11545), and has the same objective but is a permanent daily quest that can be completed for reputation and reward, and will always be available once it is unlocked.\n\nFor more information regarding the Shattered Sun Offensive (http://www.wowhead.com/?faction=1077) daily quests and the \"phases\" of reclamation, check out this guide (http://www.wowhead.com/?forums&topic=17960#p155565) on the Wowhead forums! :)",
            date = "2008-03-29T11:04:08-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11548#comments:id=262552",
        },
    },
    [11549] = {
