            author = "1334664",
            text = "I was Exalted since BC completely forgot it existed.\nCan confirm that it still works as of Warlords 6.2.\n\nNOTE: Title won't appear is your list until you Hearthstone/get out of the Isle of Quel'Danas. Might just save yourself and the GM some time.",
            date = "2015-08-31T23:50:58-05:00",
