        },
        {
            id = 234911,
            score = 70,
            author = "Bury",
            text = "Completing this quest (new for 2.4) will give you the title  of the Shattered Sun. Note that you can only display one title at a time, so this will replace your Champion of the Naaru, Gladiator, Stone Guard, or other similar title.\n\nSource: http://www.wowwiki.com/Quest:A_Magnanimous_Benefactor",
            date = "2008-02-13T05:03:05-06:00",
            sourceUrl = "https://www.wowhead.com/quest=11549#comments:id=234911",
        },
