    [11554] = {
        {
            id = 260161,
            score = 16,
            author = "alexiel",
            text = "The packages contain Marks of Sargeras (Aldor rep) or Sunfury Signets (Scryer rep) depending on which you choose.\nEdit: Has other goodies like scrolls and gold too ^^",
            date = "2008-03-26T11:56:09-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11554#comments:id=260161",
        },
        {
            id = 243724,
            score = 12,
            author = "Raiking",
            text = "Obtainable once you reach Friendly with the Shattered Sun Offensive (http://www.wowhead.com/?faction=1077).\n\nThe same goes for:\nHonored by Your Allies (http://www.wowhead.com/?quest=11555) when you reach Honored with the Shattered Sun Offensive.\nRevered in the Field of Battle (http://www.wowhead.com/?quest=11556) when you reach Revered with the Shattered Sun Offensive.\nExalted Among All Combatants (http://www.wowhead.com/?quest=11557) when you reach Exalted with the Shattered Sun Offensive.\n\nI believe these quests are comparable with the Netherwing (http://www.wowhead.com/?faction=1015) quests, such as Rise, Overseer! (http://www.wowhead.com/?quest=11053) and Stand Tall, Captain! (http://www.wowhead.com/?quest=11084), which you also obtain when you reach friendly/honored/revered/exalted.",
            date = "2008-02-26T07:28:55-06:00",
            sourceUrl = "https://www.wowhead.com/quest=11554#comments:id=243724",
        },
        {
            id = 625266,
            score = 5,
            author = "320059",
            text = "Counts towards the Loremaster of Eastern Kingdoms achievement.",
            date = "2009-02-27T12:33:37-06:00",
            sourceUrl = "https://www.wowhead.com/quest=11554#comments:id=625266",
        },
        {
            id = 298586,
            score = 2,
            author = "Slash",
            text = "It is best to pick the Aldor Supplies package (http://www.wowhead.com/?item=34583) regardless of faction. Due to the massive amounts of players actively farming mobs in the Isle of Quel'Danas, the price of Scryer turn-ins (Arcane Tomes (http://www.wowhead.com/?item=29739) and Sunfury Signets (http://www.wowhead.com/?item=30810)) has dropped sharply on nearly every server.The Fel Armaments (http://www.wowhead.com/?item=29740) and Marks of Sargeras (http://www.wowhead.com/?item=30809) can be sold in the Auction House for almost double what their Scryer counterparts sell for, and the money can be spent to buy more Scryer items than you would've gotten in the Scryer Supplies Package (http://www.wowhead.com/?item=34584).\n\nEither way, you still get several potions, scrolls, and foodstuffs.",
            date = "2008-06-02T07:57:32-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11554#comments:id=298586",
        },
        {
            id = 313727,
            score = 0,
            author = "Granak",
            text = "Oddly enough on Tichondrius(Horde side- US) Arcane Tomes are selling for a WHOLE lot more than they had been in past months.\n\nAs for the supplies package? I was stoked. Nothin' beats some gold, some potions and even some rep-based items. It was as though Santa had come early.",
            date = "2008-06-26T11:45:52-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11554#comments:id=313727",
        },
    },
    [11555] = {
        {
            id = 298584,
            score = 6,
            author = "Slash",
            text = "It is best to pick the Aldor Supplies package (http://www.wowhead.com/?item=34587) regardless of faction. Due to the massive amounts of players actively farming mobs in the Isle of Quel'Danas, the price of Scryer turn-ins (Arcane Tomes (http://www.wowhead.com/?item=29739) and Sunfury Signets (http://www.wowhead.com/?item=30810)) has dropped sharply on nearly every server.The Fel Armaments (http://www.wowhead.com/?item=29740) and Marks of Sargeras (http://www.wowhead.com/?item=30809) can be sold in the Auction House for almost double what their Scryer counterparts sell for, and the money can be spent to buy more Scryer items than you would've gotten in the Scryer Supplies Package (http://www.wowhead.com/?item=34585).\n\nEither way, you still get several potions, scrolls, and foodstuffs.",
