    [11557] = {
        {
            id = 269208,
            score = 12,
            author = "18330",
            text = "This quest can be recived after achiveng Exalted reputation with the Shattered Sun Offensive.  It is a one time only reward quest.\n\nSimilar rewards are available as you progress in reputation levels, each containing progressively more gold, random potions/elixirs and reputation items for the faction selected.",
            date = "2008-04-09T14:09:23-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11557#comments:id=269208",
        },
        {
            id = 298582,
            score = 5,
            author = "Slash",
            text = "It is best to pick the Aldor Supplies package (http://www.wowhead.com/?item=34595) regardless of faction. Due to the massive amounts of players actively farming mobs in the Isle of Quel'Danas, the price of Scryer turn-ins (Arcane Tomes (http://www.wowhead.com/?item=29739) and Sunfury Signets (http://www.wowhead.com/?item=30810)) has dropped sharply on nearly every server.The Fel Armaments (http://www.wowhead.com/?item=29740) and Marks of Sargeras (http://www.wowhead.com/?item=30809) can be sold in the Auction House for almost double what their Scryer counterparts sell for, and the money can be spent to buy more Scryer items than you would've gotten in the Scryer Supplies Package (http://www.wowhead.com/?item=34594).\n\nEither way, you still get several potions, scrolls, and foodstuffs.",
            date = "2008-06-02T07:55:33-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11557#comments:id=298582",
        },
        {
            id = 1611554,
            score = 1,
            author = "Unforgvn",
            text = "Even  though this is suppose to be a one time only quest it seems to have reset at some point.  I know I completed this back in TBC and now as of patch 4.3 I am able to complete it again.",
            date = "2012-01-15T06:42:31-06:00",
            sourceUrl = "https://www.wowhead.com/quest=11557#comments:id=1611554",
        },
    },
    [11875] = {
        {
            id = 260153,
            score = 60,
            author = "82273",
            text = "If you haven't read the quest description... this quest is only available to miners, herbalists and skinners.",
            date = "2008-03-26T11:49:14-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11875#comments:id=260153",
        },
        {
            id = 259805,
            score = 19,
            author = "128242",
            text = "For miners, I would suggest simply mining fel iron nodes in Hellfire after you finish up with the dailies on Kil'jaeden's throne.  I say this because not only are they extremely easy to find (not to mention largely ignored) but appear to have the same drop rate as adamantium ore, which unless you're actively searching it out for money it causes the quest to go by much slower due to its high demand.\n\nPS, you can get these on the Isle of Quel'danas also, despite it saying Outland only...primarily because they have Outland ore there.  Got mine from just doing the Shattered Sun dailies, didn't need to take a single detour.",
            date = "2008-03-26T01:55:00-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11875#comments:id=259805",
        },
        {
            id = 234563,
            score = 14,
            author = "127591",
            text = "Herbalists will find Nether Residue in all BC-herbs all over outland.\nI needed about 30 herb nodes  to get all 8 - so roughly 25% drop chance for me.\n\nWill give  250 reputation  @ Shattered Sun Offensive",
            date = "2008-02-12T17:54:08-06:00",
            sourceUrl = "https://www.wowhead.com/quest=11875#comments:id=234563",
        },
        {
            id = 237842,
            score = 10,
            author = "11502",
            text = "I killed & skinned 24 mobs to get my 8 residue. Pretty generous reward for a daily quest to do something which is already profitable for you.",
            date = "2008-02-17T05:37:07-06:00",
            sourceUrl = "https://www.wowhead.com/quest=11875#comments:id=237842",
        },
        {
            id = 457806,
            score = 6,
            author = "177789",
            text = "Please note that becoming a \"Grand Master\" in your gathering profession makes you ineligible for this quest.\n\nI don't know if you can still finish the quest or not once you train your profession, but I do know that you can't get the quest again if you drop it.  I found this out the hard way =)",
            date = "2008-11-20T05:25:59-06:00",
            sourceUrl = "https://www.wowhead.com/quest=11875#comments:id=457806",
        },
    },
    [11877] = {
        {
            id = 261945,
            score = 78,
            author = "91817",
            text = "Some ideas for those completing this quest on a daily basis. Depending on your profession, many of the Sunfury Blood Elves you have to hunt in Netherstorm have some form of semi-rare recipe drop. Click the NPCs name to find out where to find them.\n\nBlacksmithing\nSunfury Bloodwarder (http://www.wowhead.com/?npc=18853) drops Plans: Greater Ward of Shielding (http://www.wowhead.com/?item=23639).\n\nEnchanting\nSunfury Researcher (http://www.wowhead.com/?npc=20136) drops Formula: Enchant Weapon - Major Intellect (http://www.wowhead.com/?item=22551).\n\nEngineering\nSunfury Archer (http://www.wowhead.com/?npc=19707) drops Schematic: Adamantite Arrow Maker (http://www.wowhead.com/?item=33804).\nSunfury Bowman (http://www.wowhead.com/?npc=20207) drops Schematic: Khorium Scope (http://www.wowhead.com/?item=23808).\n\nTailoring\nSunfury Arcanist (http://www.wowhead.com/?npc=20134) and Sunfury Arch Mage (http://www.wowhead.com/?npc=20135) drop Pattern: Spellfire Bag (http://www.wowhead.com/?item=21911).\n\nThese guys appear to have no special drops.\nSunfury Astromancer (http://www.wowhead.com/?npc=19643), Sunfury Blood Knight (http://www.wowhead.com/?npc=21089), Sunfury Captain (http://www.wowhead.com/?npc=19453), Sunfury Centurion (http://www.wowhead.com/?npc=20140), Sunfury Conjurer (http://www.wowhead.com/?npc=20139), Sunfury Flamekeeper (http://www.wowhead.com/?npc=20221), Sunfury Geologist (http://www.wowhead.com/?npc=19779), Sunfury Guardsman (http://www.wowhead.com/?npc=18850), Sunfury Magister (http://www.wowhead.com/?npc=18855), Sunfury Nethermancer (http://www.wowhead.com/?npc=20248), Sunfury Warp-Engineer (http://www.wowhead.com/?npc=18852), and Sunfury Warp-Master (http://www.wowhead.com/?npc=18857).",
            date = "2008-03-28T12:27:36-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11877#comments:id=261945",
        },
        {
            id = 259769,
            score = 60,
            author = "119414",
            text = "Shared drop if you happen to be in a group.",
            date = "2008-03-26T01:01:14-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11877#comments:id=259769",
        },
        {
            id = 234570,
            score = 52,
            author = "127591",
            text = "Any sunfury blood elf in Netherstorm can drop these plans.\nMy gulid mate found them in the first mob he killed, I needed 9 kills.\n\nCombine this quest with the ones that teleports you to the Throne of Kil'Jaeden to save\ntraveling time. From there you can head north to Manaforge Coruu and kill some BE.\n\nWill give  250 reputation  @ Shattered Sun Offensive",
            date = "2008-02-12T18:06:06-06:00",
            sourceUrl = "https://www.wowhead.com/quest=11877#comments:id=234570",
        },
        {
            id = 259633,
            score = 40,
            author = "24351",
            text = "Just to keep this page clean, can we just say that the drop rate varies and try not to get discouraged if the plans don't drop within the first 10 kills? Remember, these guys also drop Scryer rep items. It's some decent money.",
            date = "2008-03-25T21:09:37-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11877#comments:id=259633",
        },
        {
            id = 254083,
            score = 17,
            author = "136340",
            text = "The quest is given out by Lord Torvos, who stands right pretty much right next to the Shattrath flight point. Talk to him to get this really easy quest.\n\nThe drop rate seems to be fairly high for the quest item. I got mine on the first go at Manaforge Coruu, but I'm guessing killing any of the Blood Elves in Netherstorm will do (seeing as that's what the quest log says anyway, go figure.)\n\nCombine this quest with Blast the Gateway (http://www.wowhead.com/?quest=11516) to make your life a little easier; that way you can simply head towards Manaforge Coruu and kill two birds with one stone.\n\nEasiest 10g 10s I ever earned.\n\n--EDIT--\n\nScratch that about the gold. The other dailies are just as easy. Ten dollars say they get ridiculously tedious ridiculously fast, just like the previous dailies (though I can't really complain, it's darn decent money for minimal time and effort...  epic flyer, here I come!)",
            date = "2008-03-16T01:12:42-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11877#comments:id=254083",
        },
    },
    [11880] = {
        {
            id = 234046,
            score = 161,
            author = "33449",
            text = "To do this quest, you must find the red clouds and use the goggles to capture their essence. The red clouds can be found anywhere in the Nagrand Spirit Fields, usually the closer to the middle the better your chance of finding one.\n\nPeople have complained that they are not able to see the clouds. This is caused by equipping the goggles in another zone (Shatt usually), and then going to the Spirit Fields. Simply re-equip your goggles and you should be able to see the clouds just fine.",
            date = "2008-02-12T03:52:21-06:00",
            sourceUrl = "https://www.wowhead.com/quest=11880#comments:id=234046",
        },
        {
            id = 236767,
            score = 51,
            author = "Archangel",
            text = "The Spirit Fields are surrounding Oshu'gun and are littered with Demons, Wildlife, and some Ethereals. The flames are pretty easy to see. I submitted a screenshot, should anyone not know what to look for.",
            date = "2008-02-15T14:52:54-06:00",
            sourceUrl = "https://www.wowhead.com/quest=11880#comments:id=236767",
        },
        {
            id = 247182,
            score = 21,
            author = "133788",
            text = "If you can't see the clouds the first time, try reequipping your goggles. It worked for me.",
            date = "2008-03-03T07:27:49-06:00",
            sourceUrl = "https://www.wowhead.com/quest=11880#comments:id=247182",
        },
        {
            id = 260303,
            score = 21,
            author = "70532",
            text = "Druids can take the readings in Travel Form without being \"unshifted\".",
            date = "2008-03-26T14:47:59-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11880#comments:id=260303",
        },
        {
            id = 262682,
            score = 20,
            author = "James",
            text = "You must have the goggles in order to turn in the quest!  Don't make the same mistake I did and destroy them for inventory space.",
            date = "2008-03-29T14:37:27-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11880#comments:id=262682",
        },
    },
    [11885] = {
        {
            id = 718043,
            score = 107,
            author = "306388",
            text = "First you need to have on you the Elixir of Shadows http://www.wowhead.com/?item=32446 for what you need to deliver 6 Shadow Dust http://www.wowhead.com/?quest=11006 .\nPut it on.\nWill expire in 15 minutes so probably you will need 2 of them.\nThe quest item you need is http://www.wowhead.com/?item=32620 witch ONLY drops from the Time-Lost Skettis Reaver/Priest/Worshipper ( the ghost NPC's )\nYou need 40 Time - Lost Scrolls to complete the quest.\nAfter you have them all go at each SKULL BONE PILE in Skettis (4) to summon each of the 4 Elites.\nBe careful what you summon, if you miss click you will need to get 10 Scrolls again.\n\nGood luck!",
            date = "2009-05-16T13:44:47-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11885#comments:id=718043",
        },
        {
            id = 2011337,
            score = 39,
            author = "Aydwen",
            text = "If you are trying to farm Terokk for the item Time-Lost Figurine for your Toy Box before 6.0/WoD this is a mini-guide explaining how to do so.\n\nHere are the steps you must take to be able to summon Terokk:\n\n1.) Get the quest Adversarial Blood from Hazzik at the Skettis quest hub.\n\n2.) Go south and farm Shadow Dust from the Arakkoa in the area (I suggest farming atleast 30 dust). Every 6 dust you get can be turned in to receive an Elixir of Shadows. You need to use an Elixir of Shadows to be able to see the Arrakoa that drop the Time-Lost Scrolls. Time-Lost Scrolls are what you need to summon the 4 'mini-bosses' that you must kill to complete this quest. You need 10 scrolls to summon each mini-boss.\n\n3.) Once you have 30 or so Shadow Dust go and turn them in to Severin at the Skettis quest hub to the north of where all the Arakkoa are. If you farmed 30 you will get 5 Elixir of Shadows. Each Elixir lasts 20 minutes.\n\nWARNING: Make sure you have this quest (Adversarial Blood) before continuing step 4.\n\n*Tip for step 4:* From my experience, the majority of the shadowy Arakkoa are in the tree-house area's and near the ruins on the ground.\n\n4.) Now that you have a few Elixir of Shadows you can go back to where the Arakkoa are and pop your Elixir. You will now be able to see shadowy Arakkoa as well as all the regular Arakkoa. The shadowy Arakkoa are the ones that drop the Time-Lost Scrolls.\n\n5.) Once you have farmed your 40 scrolls you are ready to summon the 4 mini bosses. When farming your Shadow Dust and Time-Lost Scrolls you likely saw some purple/pink ruins on the ground. In the middle of the ruins there will be a pile of skulls. If you right click on the skulls you will be able to choose between 4 different mini-bosses. Summon the top one and kill him. Then find another skull pile, and kill the 2nd one on the list and so on. After you kill all 4 of them you can turn this quest in to Hazzik. You will be awarded with a Time-Lost Offering.\n\nYou might be asking why this quest is necessary for farming Time-Lost Figurine from Terokk. Each of these 'mini-bosses' drop an item that you will need to summon Terokk. After you complete this quest \"Adversarial Blood\" you will receive a Time-Lost Offering. This is the item you need to summon Terokk. Now you can head to the little island in the center of the lake near in Skettis. There will be a big purple/pink ruin with a skull pile in the middle. Click on it, and you can use your Time-Lost Offering to summon Terokk. According to Wowhead Terokk has a 9% chance to drop the Time-Lost Figurine. In the case that he doesn't drop it on your first kill you will need more Time-Lost Offerings. After you complete Adversarial Blood the quest giver will have a repeatable quest that asks you to farm the 4 items which dropped by the mini-bosses (Gezzarak's Claw, Akkarai's Talons, Karrog's Spine, and Vakkiz's Scale). Completing this repeatable quest will reward you with another Time-Lost Offering.\n\nThe skull pile that is used to summon Terokk seems to respawn approximately every 15 minutes or so.\n\nI am new to writing short 'guide' comments on Wowhead so I apologize if it is more 'wordy' than necessary. And I apologize for any typo's there might be. I hope this guide saves you some time. Please share your opinion on this mini-guide by up or down voting it and feel free to leave a comment on how I might be able to improve in the future.\n\nThank you.",
            date = "2014-10-10T06:38:55-05:00",
            sourceUrl = "https://www.wowhead.com/quest=11885#comments:id=2011337",
        },
        {
            id = 523361,
            score = 32,
            author = "soulzek",
            text = "You get to choose which boss to summon at any bone pile, but the pile disappears when you summon one. The bone piles can be easily spotted by their blue circles.\n\nLocs of the 4 bone piles I used:\n61,74\n61,78\n70,83\n70,79\n\nBe aware that A LOT of mobs pat through the bone piles, so clear them up good. Each boss drops a blue BoP item. If you collect all 4, you can turn them in for a Time-Lost Offering which is required to summon a big boss later on.",
            date = "2008-12-21T17:45:19-06:00",
            sourceUrl = "https://www.wowhead.com/quest=11885#comments:id=523361",
        },
        {
            id = 246129,
            score = 29,
            author = "118464",
            text = "You will need 40 Time Lost Scrolls to summon all of the NPCs.  That is, if you dont die while fighting them, then of course, you will need more to summon them again.",
            date = "2008-03-01T10:33:40-06:00",
            sourceUrl = "https://www.wowhead.com/quest=11885#comments:id=246129",
        },
        {
            id = 241563,
            score = 23,
            author = "35454",
            text = "It looks like they've changed it so while 1 person needs to summon, the remaining people can get credit for the \"slaying\". Before you had to collect a drop off the mobs.\n\nGood change. I'll finally do this quest.",
            date = "2008-02-22T17:48:47-06:00",
            sourceUrl = "https://www.wowhead.com/quest=11885#comments:id=241563",
        },
    },
