    [13411] = {
        {
            id = 1037583,
            score = 12,
            author = "107862",
            text = "I believe THIS version is only obtained if you are a Death Knight.\n\nFor any other class, she will also award you with an Insignia of the Horde so you can also get credit for the achievement.\n\nDeath Knights, if you don't know, start off with an Insignia of the Scourge from their starter zone, and it's the same thing as an Insignia of the Horde.",
            date = "2010-05-12T14:01:04-05:00",
