    [13507] = {
        {
            id = 1764197,
            score = 13,
            author = "sephyre",
            text = "Here is a list of the quests required to unlock this quest assuming you haven't been in Darkshore yet. It's nearly all the quests you'll encounter up to this quest, but this gives you an idea of what to expect. Also, there are optional quests available, usually seen while doing the main quest chain, but I did not include them in this list:\n\n1)\nhttps://www.wowhead.com/quest=13522 from https://www.wowhead.com/npc=32971\nhttps://www.wowhead.com/quest=13518 from https://www.wowhead.com/npc=32973\n\n2)\nhttps://www.wowhead.com/quest=13520 from https://www.wowhead.com/npc=32972\nhttps://www.wowhead.com/quest=13521 from https://www.wowhead.com/npc=32977\n\n3)\nhttps://www.wowhead.com/quest=13527 from https://www.wowhead.com/object=194105\n\n4)\nhttps://www.wowhead.com/quest=13528 from https://www.wowhead.com/npc=32977\n\n5)\nhttps://www.wowhead.com/quest=13554 from https://www.wowhead.com/object=194122\nhttps://www.wowhead.com/quest=13529 from https://www.wowhead.com/npc=32978\n\n6)\nhttps://www.wowhead.com/quest=13562 from https://www.wowhead.com/npc=32971\nhttps://www.wowhead.com/quest=13563 from https://www.wowhead.com/npc=32959\nhttps://www.wowhead.com/quest=13564 from https://www.wowhead.com/npc=32960\n\n7)\nhttps://www.wowhead.com/quest=13598 from https://www.wowhead.com/npc=33048\nhttps://www.wowhead.com/quest=13566 from https://www.wowhead.com/npc=33048\nhttps://www.wowhead.com/quest=13565 from https://www.wowhead.com/npc=33126\n\n8)\nhttps://www.wowhead.com/quest=13569 from https://www.wowhead.com/npc=33048\n\n9)\nhttps://www.wowhead.com/quest=13599 from https://www.wowhead.com/npc=33048\n\n10)\nhttps://www.wowhead.com/quest=13589 from https://www.wowhead.com/npc=32971\n\n11)\nhttps://www.wowhead.com/quest=13504 from https://www.wowhead.com/npc=32965\nhttps://www.wowhead.com/quest=13505 from https://www.wowhead.com/npc=32966\n\n12)\nhttps://www.wowhead.com/quest=13507 from https://www.wowhead.com/npc=32965",
            date = "2012-11-18T08:35:33-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13507#comments:id=1764197",
        },
        {
            id = 1553226,
            score = 10,
            author = "10857",
            text = "Loremaster Tip: Stay at max range to avoid their instant charge when you hit them. They will charge you even if you oneshot them.",
            date = "2011-10-25T06:49:25-05:00",
            sourceUrl = "https://www.wowhead.com/quest=13507#comments:id=1553226",
        },
        {
            id = 1511182,
            score = 2,
            author = "146544",
            text = "I did this with my level 23 Wogen-Hunter-Marks and pet. I went to the very back of the camp by the seas. my Wow map showed these and Q=\"War Supplies\" to be close together. I did so, as fewer to deal with. Once I started to move into the area of operations, my quest targets came one at a time very quickly. IE...Horde Enforcer, then a Mystic, and the burn \"War Supplies\", repeat and rinse again! The \"War Supplies\" were respawning almost right after I burned them so they came quickly. I hope this is a good help! Level up!",
            date = "2011-09-06T01:51:37-05:00",
            sourceUrl = "https://www.wowhead.com/quest=13507#comments:id=1511182",
        },
        {
            id = 6153667,
            score = 1,
            author = "Anjanti",
            text = "I was doing the Loremaster achievement while I was leveling.  When I hit level 50 in switched timelines on me and I was unable to progress through the quests I was working on.  It took me a minute before I realized I need to talk to Zindormi (Darkshore 48, 24), to switch back to the earlier timeline.\n\nSide Note:  My main goal was finishing the Loremaster achievement.  This is in no way a good way to level when you're well over 5+ levels of the recommended.  You do get some very minor experience when completing quests but nothing for kills.",
            date = "2025-08-04T07:21:46-05:00",
            sourceUrl = "https://www.wowhead.com/quest=13507#comments:id=6153667",
        },
    },
    [13508] = {
        {
            id = 1185598,
            score = 3,
            author = "513530",
            text = "Alanndarian Nightsong is at 63,6.  Go through the camp to what appears to be an exit on the other side.  She's at the ruins.",
