        },
    },
    [13509] = {
        {
            id = 1193427,
            score = 7,
            author = "432819",
            text = "This quest is best done alongside Denying Manpower (http://www.wowhead.com/quest=13507), as the mobs are in the same location as these crates.\n\nIt is possible to torch the same box of armaments several times--they don't go away after you torch them the first time. The boxes take about 20 seconds to burn, then just rinse and repeat until you've done it 12 times.",
            date = "2010-11-28T13:16:08-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13509#comments:id=1193427",
        },
        {
            id = 1213583,
            score = 5,
            author = "fredd13",
            text = "Agreed. And in the quarry at 62,10 there are a pair of them a few yards apart. I just ran backwards and forwards between the two, relighting them as they went out. Average wait time was about 6 seconds.",
            date = "2010-12-08T01:25:46-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13509#comments:id=1213583",
        },
        {
            id = 2317835,
            score = 1,
            author = "cephadex",
            text = "Just in case anyone is confused: you don't click on the crates to burn them. You have to click on the Sentinel Torch in your inventory.",
            date = "2016-03-29T08:13:26-05:00",
            sourceUrl = "https://www.wowhead.com/quest=13509#comments:id=2317835",
        },
        {
            id = 5715003,
            score = 1,
            author = "Light19",
            text = "https://youtu.be/a_IzwqtAgo4",
            date = "2023-11-02T13:33:49-05:00",
            sourceUrl = "https://www.wowhead.com/quest=13509#comments:id=5715003",
        },
    },
    [13510] = {
        {
            id = 1515094,
            score = 24,
            author = "Starmaiden",
            text = "Must pick up Reason to Worry (http://www.wowhead.com/quest=13506) which is started from dropped Overseer's Orders (http://www.wowhead.com/item=44979) dropped by... you guessed it Shatterspear Overseer (http://www.wowhead.com/npc=32863) :)",
            date = "2011-09-11T00:44:16-05:00",
            sourceUrl = "https://www.wowhead.com/quest=13510#comments:id=1515094",
        },
        {
            id = 1868582,
            score = 12,
            author = "crazycooky77",
            text = "This quest worked fine for me today. However I failed it (damn NPC ran ahead and didn't stop to help fight...) and when I abandoned the quest and went back to accept it again, I had the same problem. Open cage, nothing to accept - even after killing Rit'ko and getting the key again.\n\nRelog helped to resolve the problem, immediately the cage was closed with the NPC inside, I could open it up and accept the quest again. Hope it helps.",
            date = "2013-06-20T16:32:13-05:00",
            sourceUrl = "https://www.wowhead.com/quest=13510#comments:id=1868582",
        },
        {
            id = 2553869,
            score = 7,
            author = "connordk",
            text = "If, somehow like me you lose the https://www.wowhead.com/item=45040, you can simply kill https://www.wowhead.com/npc=32970 again to get another. Apparently I dodged this quest when doing Loremaster and came back later to find myself needing a key.",
            date = "2018-02-19T13:12:35-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13510#comments:id=2553869",
        },
        {
            id = 1203017,
            score = 3,
            author = "Alamandaros",
            text = "This quest is currently bugged. You can get the key, but the cage is already open and not usable.",
            date = "2010-12-02T21:28:30-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13510#comments:id=1203017",
        },
        {
            id = 2560390,
            score = 3,
            author = "bunganga",
            text = "So everyone seems to think this quest is bug. I think we are just dealing with a long respawn rate. When I headed into the area where Rit'ko (https://www.wowhead.com/npc=32970/ritko) was, another player was heading out, escorting the sentinel. Rit'ko (https://www.wowhead.com/npc=32970/ritko) was dead, and the cage was open. I waited for Rit'ko (https://www.wowhead.com/npc=32970/ritko) to respawn and got the key (https://www.wowhead.com/item=45040/shatterspear-torturers-cage-key), but the sentinel wasn't back yet. I just decided to leave and turn in my other quests and come back afterwards. Sure enough when I returned, the cage was locked, and Sentinel Aynasha (https://www.wowhead.com/npc=32964/sentinel-aynasha) was in the cage. Unlocked the cage, she came out, and the quest became available.\n\nNote: When doing this quest, if you can keep her alive, fall behind the sentinel, and allow her to aggro the mobs AND make sure she takes the first hit. Once she's hit, she will stop and fight (more stopping than fighting, tbh) until that mob is dead. Otherwise, she will keep running for the docks while you are left to get attacked by every mob she aggro'd.\n\nHope this helps! Don't let the easy mode of this game make you forget to be patient :)",
            date = "2018-03-30T11:41:07-05:00",
            sourceUrl = "https://www.wowhead.com/quest=13510#comments:id=2560390",
        },
    },
    [13511] = {
        {
            id = 1185023,
            score = 29,
            author = "153992",
            text = "it's just hard to take trolls seriously I guess\n\nIsn't it?",
            date = "2010-11-25T14:01:26-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13511#comments:id=1185023",
