            author = "Jagex",
            text = "After killing Rit'ko (http://www.wowhead.com/npc=32970), he drops a Shatterspear Torturer's Cage Key (http://www.wowhead.com/item=45040#dropped-by). Use this key on the Shatterspear Cage (near Rit'ko) with Sentinel Aynasha inside. She will give you a (escort) quest Timely Arival (http://www.wowhead.com/quest=13510).",
            date = "2010-11-26T09:07:38-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13511#comments:id=1187201",
        },
    },
    [13512] = {
        {
            id = 1169380,
            score = 24,
            author = "TegoZanduba",
            text = "You need to shoot them with the Dryad Spear (http://cata.wowhead.com/item=44995) until they get to about 50% and then they'll jump down and you can attack them normally.",
            date = "2010-11-12T20:55:40-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13512#comments:id=1169380",
        },
        {
            id = 1204093,
            score = 8,
            author = "165655",
            text = "Tego is right, if you shoot them with the spear eventually they jump down.  If you have a ranged character, however, that isn't necessary; I had a mage take out both of them and he just shot them each once with the spear just in case, then nuked.",
            date = "2010-12-03T12:14:09-06:00",
