    [13514] = {
        {
            id = 1270739,
            score = 54,
            author = "Thexwarlord",
            text = "You have to use the purple Vangeful Protectors in the water to destroy the buildings.",
            date = "2011-01-01T03:58:48-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13514#comments:id=1270739",
        },
        {
            id = 1179726,
            score = 34,
            author = "238963",
            text = "This quest broke my heart. Many a flight path have I spent flying from Moonglade to Darnassus and watching as the Dancing Trolls rolled by beneath me.\n\nForgive me, Boogie Trolls. I only harm you for Loremaster credit. I shall come and dance with you again! *tear*",
            date = "2010-11-24T00:23:08-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13514#comments:id=1179726",
        },
        {
            id = 5977069,
            score = 8,
            author = "theladyjuniper",
            text = "Despite there being a rideable Kaldorei Hippogryph right in front of you when you pick up this quest, and despite the fact that the UI changes to have attacks available, this is not the npc you need to ride for the quest. Instead there are two big purple tree dudes, Vengeful Protectors, who are the ones to use. They are the ones mentioned in the quest text, but if you are like me and only skimmed the text, you may not realise because of how front and centre the Hippogryph is.",
            date = "2024-10-07T01:34:45-05:00",
            sourceUrl = "https://www.wowhead.com/quest=13514#comments:id=5977069",
        },
        {
            id = 1427500,
            score = 7,
            author = "grauwyler",
            text = "Be sure to dismiss your pet/minion before mounting the ancient. I didn't do that the first time I tried this quest. It let me mount and ride the ancient around but I couldn't kill any trolls or destroy any buildings. I couldn't even dismount the vehicle. I had to log out. When I logged back in I was standing in the nearest graveyard, which happened to be another long walk away.\n\nI dismissed my minion before trying it the 2nd time and it worked fine.\n\nYMMV",
            date = "2011-05-25T19:19:34-05:00",
            sourceUrl = "https://www.wowhead.com/quest=13514#comments:id=1427500",
        },
        {
            id = 1206234,
            score = 5,
            author = "426955",
            text = "Now I know how Pippin and Merry must have felt riding on Treebeard's shoulders! Sort of ;)",
            date = "2010-12-04T14:04:10-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13514#comments:id=1206234",
        },
    },
    [13515] = {
        {
            id = 1204062,
            score = 21,
            author = "wharris",
            text = "When you kill Jor'kil, he drops Hellscream's Missive (http://www.wowhead.com/item=46318) which starts Disturbing Connections (http://www.wowhead.com/quest=13591)",
            date = "2010-12-03T11:53:06-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13515#comments:id=1204062",
        },
        {
            id = 2014186,
            score = 13,
            author = "FrostWolf219",
            text = "I have started having issues with this quest.  I would have the attack start and would try and kill the troll but I would not get credit for the kill or be able to loot him.  I did finally get through by basically standing in front of his face and when his shield is dropped pull him to the back of his cave so the other elves weren't attacking him.",
            date = "2014-10-16T14:56:22-05:00",
            sourceUrl = "https://www.wowhead.com/quest=13515#comments:id=2014186",
        },
        {
            id = 1900063,
            score = 7,
            author = "Jacob9624",
            text = "What you will need to do to get to this quest:\n\nIt's possible to do these quests first, before the main chain. They may be required to unlock some of the others below though.\n\nWritings of the Void\nThreat from the Water\nReason to Worry\n  Swift Response\n    One Bitter Wish\n      (+)Timely Arrival\n\nThe main quest chain:\n\nThe Last Wave of Survivors\n  The Boon of the Seas\n  Buzzbox 413\n    No Accounting for Taste\n      Buzzbox 723\n\009  A Cure In The Dark\009      +\n\009  (?)The Corruption's Source  +\n\009    (+)Bearer of Good Fortune +\n          A Troubling Prescription    +  completion of these 4 unlocks:\n                                      ||\n+-------------------------------------+\n||\n+ The Final Flame of Bashal'Aran\n    (?)Solace for the Highborne\n  A Love Eternal\n  A Lost Companion\n    Twice Removed     +\n    Unsavory Remedies +\n    Ritual Materials  +\n                      ||\n+---------------------+\n||\n+ The Ritual Bond\n    Spirit of the Stag          \\\n    Spirit of the Moonstalker    } can only do 1/3\n    Spirit of the Thistle Bear  /\n      Grimclaw's Return\n        An Ocean Not So Deep (not required for the chain, but it unlocks)\n        The Shatterspear Invaders\n          Remnants of the Highborne\n            Denying Manpower     +\n          Shatterspear Laborers  ||\n            War Supplies         +\n                                 ||\n+--------------------------------+\n||\n+ On the Brink\n    Strategic Strikes\n      The Looting of Althalaxx\n        The Front Line\n        (?)The Ancients' Ire\n          Ending the Threat\n            Disturbing Connections\n\nDon't forget this one for the pet ;)\n\n              Remembrance of Auberdine",
            date = "2013-09-19T04:07:08-05:00",
            sourceUrl = "https://www.wowhead.com/quest=13515#comments:id=1900063",
        },
        {
            id = 1916336,
            score = 4,
            author = "agardin",
            text = "if you don't turn in the previous quest (with the vengeful protector), this one can't be finished. So if you can't loot the boss and can't end this quest, that may be the problem.",
            date = "2013-11-09T18:01:40-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13515#comments:id=1916336",
        },
        {
            id = 1194860,
            score = 1,
            author = "257700",
            text = "This may be obvious but you can talk to Huntress Sandrya Moonfall (http://www.wowhead.com/npc=33178) and choose the \"I am ready. Begin the attack.\" option. He's much easier to defeat without his Aegis of the Shatterspear (http://www.wowhead.com/spell=64549) buff. Afterwards you can use the Nightsaber Rider near the Shatterspear Pass cave entrance to catch a ride back to Lor'danel.",
            date = "2010-11-29T03:04:06-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13515#comments:id=1194860",
        },
    },
    [13518] = {
        {
            id = 1186702,
            score = 152,
            author = "487521",
            text = "The dead, and who they were prior to the Shattering. ( patch 4.0.3a)\nMavralyn (http://www.wowhead.com/npc=4186) Leather gear vendor and leather working supplies.\nTerenthis (http://www.wowhead.com/npc=3693) A quest giver. Lead you to Volcor eventually.\nGwennyth Bly'Leggonde (http://www.wowhead.com/npc=10219) Started the dead animals on the shore quest set and always lived on the Flight Path Dock.\nAllyndia (http://www.wowhead.com/npc=4191) The food and drink vendor.\nGondral Moonbreeze (http://www.wowhead.com/npc=4193) Your Darkshore Tailoring Trainer.\nBarithras Moonshade (http://www.wowhead.com/npc=3583) Giver of a cave mushroom quest.\nDalmond (http://www.wowhead.com/npc=4182) General goods vendor\n\nI think I'll miss Gwen the most.  *sniffles*\n\nThe survivors, and who they once were.\n\nVolcor (http://www.wowhead.com/npc=3692) Fella in the cave that you rescue.  Directed to him by a whimpering white bear, Grimclaw (http://www.wowhead.com/npc=3695)\nGershala Nightwhisper (http://www.wowhead.com/npc=8997) Sent you after brains stems from the naga dungeon.\nCerellean Whiteclaw (http://www.wowhead.com/npc=3644)  The sad and lonely Nelf on the end of the dock who was just looking for love.\nShaldyn (http://www.wowhead.com/npc=4185) Clothier, better known as, Cloth gear vendor.\n\nDoing this quest was making me too sad.  So I took the effort to memorialize the fallen and the wounded.  I feel a little better.\n\nAlso dead, near the quest giver:   Laird (http://www.wowhead.com/npc=4200)  He was the fish vendor that sent you back to Nessa Shadowsong (http://www.wowhead.com/npc=10118)  to talk about the different sort of wildlife in darkshore vs tedressil.  Was a quest to promote the travel options, hippogryph or boat.",
            date = "2010-11-26T04:21:01-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13518#comments:id=1186702",
        },
        {
            id = 1253424,
            score = 51,
            author = "Flitzy",
            text = "\"So this.. is what it feel like.. to be mortal?\"\n\nDarn you, Blizzard! :<\n\nI shed a tear :(",
            date = "2010-12-22T22:13:42-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13518#comments:id=1253424",
        },
        {
            id = 1184727,
            score = 49,
            author = "CMKCot",
            text = "This quest was so sad to do... after leveling 5 alts back in oldworld doing the darna lvling route, i kinda got to know the NPCs.\n\nseeing them dead for good in the sand... :(\n\nIt is too late for me. We earned our fate with our pride. Go... others may have made it. Save any that you can.\n\nGwennyth was the nelf girl that gave those long quest to investigate the dead creatures surrounded by murlocs. :(",
            date = "2010-11-25T11:42:41-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13518#comments:id=1184727",
        },
        {
            id = 1220233,
            score = 22,
            author = "725458",
            text = "I never really played alliance or Night elves much at all so i didnt really know many of the Npcs but even still this quest brought a tear to my eye :'(",
            date = "2010-12-09T23:25:19-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13518#comments:id=1220233",
        },
        {
            id = 2575946,
            score = 20,
            author = "BJJB",
            text = "Is this quest still available under Battle for Azeroth ? I have been looking everywhere and there is no npc offering this quest, however it still shows up as a ! on the larger map",
            date = "2018-06-24T15:42:23-05:00",
            sourceUrl = "https://www.wowhead.com/quest=13518#comments:id=2575946",
        },
    },
    [13519] = {
        {
            id = 1470005,
            score = 12,
            author = "aphixx",
