    [13522] = {
        {
            id = 1277360,
            score = 12,
            author = "755390",
            text = "There are more vile sprays further down the coast that don't spawn from a vile terror, they're just roaming around where the grass meets the sand (see npc map).",
            date = "2011-01-04T16:24:35-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13522#comments:id=1277360",
        },
        {
            id = 1277224,
            score = 5,
            author = "Abiwho",
            text = "Having kind of a hard time with this quest. The vile sprays spawn from the lvl 10 elite Vile Terror. There are five sentinels that are fighting off the elite, when he dies he spawns 4 or 5 of the vile sprays. The sprays usually spawn right on top of you, but the sentinels are killing them off so quickly that I'm not able to kill more than one per spawn. The elite respawns pretty quickly, but it is time-consuming nonetheless.\nAs a side note, you don't have to fight the elite for the sprays to spawn, but the fight will go faster if you do. Look out that you don't grab aggro from the sentinels though, he hits pretty hard.\nEdited because I can't type and play wow at the same time (not legibly anyway).",
            date = "2011-01-04T15:01:15-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13522#comments:id=1277224",
        },
        {
            id = 1310038,
            score = 5,
            author = "402434",
            text = "Regarding both comments above - there are more of the Vile Sprays further down the beach that you don't need to have spawn from the elite; but you should make sure that you aren't near any of the Lor'danel Sentinels when you attack them, otherwise they'll run in and \"help\" you. Since they're a much higher level they kill the sprays much faster and you don't get credit for the kill since you haven't done most of the damage.",
            date = "2011-01-26T00:01:51-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13522#comments:id=1310038",
        },
        {
            id = 1366010,
            score = 3,
            author = "34796",
            text = "On other thing to note: as a worgen I hit Lor'danel at level 16 (between guild exp buffs and whatever else) so there was no Exclamation over her head since this quest is level 10. She's easy enough to find, but you won't see her as a quest giver on your minimap unless you track low-level quests.",
            date = "2011-03-13T16:23:29-05:00",
            sourceUrl = "https://www.wowhead.com/quest=13522#comments:id=1366010",
        },
        {
            id = 2870006,
            score = 1,
            author = "Zefram",
            text = "Not seeing her anywhere around Auberdine, and I have trivial quests on.  Then I thought of the time twist, gotta talk to Zidormi.\nI was doing the Darkshore warfront, and the quest shows on the map.",
            date = "2019-02-06T04:34:41-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13522#comments:id=2870006",
        },
    },
    [13523] = {
        {
            id = 1256285,
            score = 16,
            author = "743933",
            text = "okay this drove me crazy for a few minutes. Here's the detail the earlier posts left out.  Even if the loot appears and you don't take it, the orb & character will go through the motions of channeling but nothing happens. Not looting is not the key. Kill the elemental and a bunch of twinkling stars appear among the remains. LEFT click on this, then go over and RIGHT click on the \"orb of elune\". the \"spirit\" will appear and fade away. Afterward you can loot as normal. Kind of an awkward sequence but that's how it works.",
            date = "2010-12-24T07:51:07-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13523#comments:id=1256285",
        },
        {
            id = 1649218,
            score = 5,
            author = "JeromeBeckett",
            text = "Anyone STILL having trouble, go to the game menu (Esc), click on interface, go to controls and turn off 'Interact on Left Click' at the bottom. This will let you left click without looting.",
            date = "2012-04-05T15:51:59-05:00",
            sourceUrl = "https://www.wowhead.com/quest=13523#comments:id=1649218",
        },
        {
            id = 1669346,
            score = 5,
            author = "APS72",
            text = "Using the https://www.wowhead.com/item=52662 as my fishing alt's cloak. its the only low lvl cloak that's has any \"water\" in its name.",
            date = "2012-05-21T13:52:29-05:00",
            sourceUrl = "https://www.wowhead.com/quest=13523#comments:id=1669346",
        },
        {
            id = 1662950,
            score = 4,
            author = "810995",
            text = "After trying all the suggestions previously mentioned and most of them not working. maybe due to recent patch updates. This is what worked for me:\n\n1. Kill Elemental.\n2. Loot the Elemental. (yes you have to loot it, kinda dumb i know)\n3. Click on the dead elemental\n4. Click on the Orb of Elune.\n5. Finish the rest of the stupid Quest.",
            date = "2012-05-05T09:52:28-05:00",
            sourceUrl = "https://www.wowhead.com/quest=13523#comments:id=1662950",
        },
        {
