    [13529] = {
        {
            id = 1580769,
            score = 18,
            author = "81303",
            text = "To get this quest to become available, I did the following:\n\nhttps://www.wowhead.com/quest=13522 - I don't know that you actually need this, but I did it first.\nhttps://www.wowhead.com/quest=13518 - This opens up these quests:\n\nhttps://www.wowhead.com/quest=13520\nhttps://www.wowhead.com/quest=13537\nhttps://www.wowhead.com/quest=13521\n\nThe https://www.wowhead.com/quest=13521 quest turns into this chain:\n\nhttps://www.wowhead.com/quest=13527\nhttps://www.wowhead.com/quest=13528\nhttps://www.wowhead.com/quest=13554\n\nhttps://www.wowhead.com/quest=13529 opens after Buzzbox 723 is turned in. You do not have to do https://www.wowhead.com/quest=13554.",
            date = "2011-11-25T20:54:57-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13529#comments:id=1580769",
        },
        {
            id = 1203141,
            score = 11,
            author = "610048",
            text = "When you go into the cave go down the path.  There is another quest you can pick up if you go to the left.  You'll find Zenn Foulhoof if you take the path to the right.",
            date = "2010-12-02T23:12:36-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13529#comments:id=1203141",
        },
        {
            id = 1303407,
            score = 8,
            author = "noora",
            text = "For those like me who had trouble finding the location:\n\nFrom Lor'danel, take the bridge near the flightmaster that leads South. At the road, turn left (East). Then you will cross a small bridge. After the small bridge turn right (North) and proceed overland (watching out for the bears). Proceed to 56.2, 27.2, where there are two torches, and a path going up a cliff and to the right. Follow this path as it leads along the cliff to the right until you come to some crates with two torches beside them (56.2, 29.6). The path turns left there and takes you further up to the cave and waterfall, which are at 56.8, 31.2. You will see a Grell or two as you approach.\n\n[Edit] Here's a  map (http://www.wowhead.com/maps?data=148:562272) to show approximately where you find the trail up the cliff:",
            date = "2011-01-21T17:42:48-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13529#comments:id=1303407",
        },
        {
            id = 1832433,
            score = 4,
            author = "1094310",
            text = "Lore behind this quest:\nAfter an Alliance hero gives Zenn a \"snack\", he still goes for his evil ways. One day, he was caught casting perverse magic and was driven here to taint all of Darkshore and corrupt its wildlife, too. So the hero yet again most likely, is tasked to dealing with Zenn once and for all. This quest was added with the Cataclysm expansion during the levels 1-60 major revamp. He is also located in Teldrassil as a level 7 friendly Alliance player who has them kill harmless animals and is given a poisonous fruit.",
            date = "2013-03-21T16:28:43-05:00",
            sourceUrl = "https://www.wowhead.com/quest=13529#comments:id=1832433",
        },
        {
            id = 1593722,
            score = 3,
            author = "921262",
            text = "Inside the waterfall is a cave. There's vile grells there that drop foul ichor. Also Zenn Foulhoof is in there.",
            date = "2011-12-10T08:53:30-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13529#comments:id=1593722",
        },
    },
    [13537] = {
        {
            id = 1544462,
            score = 102,
            author = "657455",
            text = "\"Yeah, I can see we just had a near armageddon, and there are people drowning and dying all around me.  Sure this place stinks of decaying flesh, but I'm hungry.\n\n\"If you're not busy saving everyone, can you fish me up some lunch? Oh me, no I'm not doing anything, I'll stand and watch you!\n\n\"Oh no no no.  No way I'm eating that Albacore, or Mackerel.  What do I look like some mangy mutt?\n\n\"Oh thank you so much!  I see you've been fishing with an epic pole crafted by the worlds finest Walruses whom you saved from total annihilation, but here have my fishing pole.  It's got +3 fishing skill.  It's not like I'm going to use it!\"",
            date = "2011-10-16T12:44:23-05:00",
            sourceUrl = "https://www.wowhead.com/quest=13537#comments:id=1544462",
        },
        {
            id = 1179757,
            score = 69,
            author = "707383",
            text = "Had to start this one from level 1 fishing. Just did it right beside the guy who gives you the quest.\n\nCaught my first Darkshore Grouper at Fishing lvl 26.\nGot the last one at Fishing lvl 45.\n\nEasy quest, especially if you plan to level fishing anyways.",
            date = "2010-11-24T00:35:52-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13537#comments:id=1179757",
        },
        {
            id = 1320989,
            score = 59,
            author = "Daniera",
            text = "You must have fishing trained or the NPC won't have a quest for you.",
            date = "2011-02-03T23:34:13-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13537#comments:id=1320989",
        },
        {
            id = 1187442,
            score = 41,
            author = "uzziel",
            text = "Must complete Threat from the Water (http://www.wowhead.com/quest=13522) before Staats offers this quest.",
            date = "2010-11-26T11:00:50-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13537#comments:id=1187442",
        },
        {
            id = 1418880,
            score = 27,
            author = "Zuril",
            text = "This quest gets you one fish closer to https://www.wowhead.com/achievement=5479.",
            date = "2011-05-14T20:00:13-05:00",
            sourceUrl = "https://www.wowhead.com/quest=13537#comments:id=1418880",
        },
    },
    [13542] = {
        {
