    [13543] = {
        {
            id = 1845906,
            score = 2,
            author = "1088365",
            text = "This is taken from the post by jorshiac. I did this to make it more easy and so the post it was in reply to can not be shown as it can confuse people.\n\nSkylord Braaz @ 39.1, 38.3\nCloudtamer Wildmane @ 40.8, 41.5\nWindmaster Tzu-Tzu @ 37.8, 42.8",
            date = "2013-04-22T13:09:32-05:00",
            sourceUrl = "https://www.wowhead.com/quest=13543#comments:id=1845906",
