        {
            id = 1850432,
            score = -1,
            author = "oakpack4",
            text = "Windmaster Tzu-Tzu's name is very likely a reference to the Tcho-Tcho people of the Cthulhu Mythos (http://en.wikipedia.org/wiki/Tcho-Tcho), the same source of the Old Gods",
            date = "2013-05-05T22:51:14-05:00",
            sourceUrl = "https://www.wowhead.com/quest=13543#comments:id=1850432",
        },
        {
