            date = "2010-12-29T17:02:40-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13544#comments:id=1266419",
        },
        {
            id = 3178670,
            score = 35,
            author = "Ragath",
            text = "Tom Tom\n/way Darkshore 45.66 79.07 Fleetfoot\n/way Darkshore 45.31 76.74 Bear Statue",
            date = "2019-12-27T21:21:58-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13544#comments:id=3178670",
        },
        {
            id = 1242930,
            score = 11,
            author = "56373",
            text = "Kill the yellow bird named Fleetfoot for feathers. Then use the item at the Bear Statue.",
            date = "2010-12-18T10:43:27-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13544#comments:id=1242930",
        },
        {
            id = 1541732,
            score = 10,
            author = "826316",
            text = "For people without cords, the statue is just south of the grove and the bird is a little more south from the statue. I found the bird next to the corrupted watering hole.",
            date = "2011-10-13T09:14:06-05:00",
            sourceUrl = "https://www.wowhead.com/quest=13544#comments:id=1541732",
        },
        {
            id = 1541741,
            score = 8,
            author = "826316",
            text = "Slight correction to my previous statement. It is not south of the grove of the ancients. The tallstrider and the bear statue are in the southern part of the grove.. They are out of the colorful circle of trees. but the mini map says you are in the grove. The bird and the watering hole are visible from the statue. Wisps are found easily around any trees in the area. a little fast and hard to catch though. Hope this helps someone.",
            date = "2011-10-13T09:24:54-05:00",
            sourceUrl = "https://www.wowhead.com/quest=13544#comments:id=1541741",
        },
    },
    [13545] = {
        {
            id = 1237603,
            score = 14,
            author = "leddy",
            text = "For rogues:\nYou can sap the furbolgs before using the herb bundle on them, kill the corrupt slime thingy, and they'll come out of sap as friendly.",
            date = "2010-12-16T06:08:03-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13545#comments:id=1237603",
        },
        {
            id = 1265738,
            score = 6,
            author = "748907",
            text = "For druids:\nHit them with your herb bundle then quickly hit them up with entangling roots. Get some distance from the burbolg while you focus on the slime. You will probably need to run a rejuvenation spell half way through to make sure you'll make it, but that's not so bad.",
            date = "2010-12-29T09:46:19-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13545#comments:id=1265738",
        },
        {
            id = 1274120,
            score = 6,
            author = "66148",
            text = "If you use fear on the furbolg, it will not turn friendly when the slime is killed.",
            date = "2011-01-02T22:35:43-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13545#comments:id=1274120",
        },
        {
            id = 1224735,
            score = 5,
            author = "712483",
            text = "How this works if when you used the Blessed Herb Bundle (http://www.wowhead.com/item=44889) the furbolg and the Spirit of Corruption at the same time. Just focus down the Spirit of Corruption and the furbolg will go friendly. Be careful, if you sheep the furbolg it will not turn friendly and will come out for vengeance.",
            date = "2010-12-11T13:06:14-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13545#comments:id=1224735",
        },
        {
            id = 1228316,
            score = 3,
            author = "Core",
            text = "This quest sucks for druids, using the Blessed Herb Bundle knocks you back to caster form.",
            date = "2010-12-12T17:07:45-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13545#comments:id=1228316",
        },
    },
    [13546] = {
        {
            id = 1390913,
            score = 5,
            author = "Wownomo",
            text = "Not true. Perhaps it's changed since your post, but I was on my way to Ashenvale to get some Warsong Gulch gear on my lvl 20. I bypassed all the quest givers from Lor'Danel on until I saw none other than Malfurion Stormrage at The Eye of the Vortex with a shiny yellow \"!\" above his head. I stopped and started questing in Darkshore from there which lead me to this quest.\n\nYa go ahead a down rate this comment then go do those 90 quests instead of just starting this chain rtards.",
            date = "2011-04-14T03:19:45-05:00",
            sourceUrl = "https://www.wowhead.com/quest=13546#comments:id=1390913",
        },
        {
