    [13554] = {
        {
            id = 1372452,
            score = 15,
            author = "Engrelled",
            text = "I made the mistake of killing a couple of corrupted duskrats in the cave and got a poison or disease which killed me (hunter with 367 max health).  It seems to drop just from the rats and really kicks away the health points, so if you're tempted to kill rats - resist the temptation.",
            date = "2011-03-21T09:04:59-05:00",
            sourceUrl = "https://www.wowhead.com/quest=13554#comments:id=1372452",
        },
        {
            id = 1181600,
            score = 13,
            author = "putyondaritz",
            text = "Ok, this was a bit tricky for me, the only waterfall I had seen was the mini malestrom, this is the wrong waterfall! Instead you'll go to 56.26 and you'll be facing the right path up to the Vile Grell(For the corrupted source as well). Hope this helps!",
            date = "2010-11-24T13:08:56-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13554#comments:id=1181600",
        },
        {
            id = 1226417,
            score = 11,
            author = "728821",
            text = "57.31 is the actual cordinates. The cave is hidden behind a small waterfall. When you get to some metal crates you are really close.",
            date = "2010-12-12T02:26:44-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13554#comments:id=1226417",
        },
        {
            id = 1203457,
            score = 8,
            author = "717038",
            text = "East of the Whirlpool for 'Ghosts in the Dark' is a cave, the mobs required are in / around the cave.\nYou will pass a questgiver to kill the boss in the cave and 8 mobs around / in the cave.\nKilling the mobs in the cave I looted \"Corruptor's Master Key' Quest to unlock / free mobs from boxes inside the cave.\nAlso found a quest inside (from a lab table) 'A troubling prescription' Simple loot / hand in quest.",
            date = "2010-12-03T04:27:30-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13554#comments:id=1203457",
        },
        {
            id = 2450289,
            score = 7,
            author = "Dooteranopia",
            text = "Further clarification (with coordinates):\n\nHead to 55.97, 26.85 (you will not cross any water to get there).\n\nLook directly southeast and you will see two torches marking the bottom of a path.\n\nAt the top of the hill, there will be two more torches.  You will see three metal boxes ahead, but head east up the hill instead, toward the exclamation mark on the minimap.  Continue up the path next to him and you will again see two torches next to the waterfall.  The entrance is through the waterfall.",
            date = "2016-12-02T09:47:52-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13554#comments:id=2450289",
        },
    },
