    [13565] = {
        {
            id = 1186916,
            score = 37,
            author = "378236",
            text = "At first I thought this was buggy.  The way it works is head to 48 40 ish  (lady Janira is about 35 yards east of there)  kill a naga.  near the naga that you killed, click the Petrified root.  An ent will come out from the corpse, and run off and kill another naga.   /repeat\nWorked fine once I realized what it wanted me to do.",
            date = "2010-11-26T06:21:18-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13565#comments:id=1186916",
        },
        {
            id = 1387903,
            score = 5,
            author = "806469",
            text = "I was wondering if there is a Chain of quests that will unlock this one.  I went to the NPC Seraphine and there was no quest available.",
            date = "2011-04-09T20:37:13-05:00",
            sourceUrl = "https://www.wowhead.com/quest=13565#comments:id=1387903",
        },
        {
            id = 1365075,
            score = 4,
            author = "194448",
            text = "Kill the quest target Janira.  Use the Petrified Root in your inventory while standing next to her corpse to call an ent.  The ent will go for a Naga, kill the naga with the ent.  While standing next to that Naga corpse use the Petrified Root again.  Repeat this process until you've called forth 6 ents.",
            date = "2011-03-12T14:42:51-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13565#comments:id=1365075",
        },
        {
            id = 1193024,
            score = 3,
            author = "56896",
            text = "It is possible to use the Petrified Root on Lady Janira also. Not only the Darkscale Scout.",
            date = "2010-11-28T10:19:50-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13565#comments:id=1193024",
        },
    },
    [13566] = {
        {
            id = 1092757,
            score = 135,
            author = "tutti",
            text = "None of these drop from animals you've killed.\n\nThe doe hair is easiest to collect, just find three does and right click them to loot them.\n\nFor moonstalker whiskers, find the neutral (yellow) moonstalkers near the ruins of Auberdine and do the same. These will go red and attack you, however.\n\nThe bears can be tricky, as they are aggressive (red), and there can be a lot of people trying to kill them for the quest item. This is wrong, do NOT kill the bears. Watch one from afar, it will eventually turn neutral, when it does walk up to it and right click it like you did the other two. Then walk far enough away that it won't attack you when it turns aggressive again, and repeat.",
            date = "2010-07-31T06:24:43-05:00",
            sourceUrl = "https://www.wowhead.com/quest=13566#comments:id=1092757",
        },
        {
            id = 1362217,
            score = 32,
            author = "Shaitan051",
            text = "He wants you to not harm the animals, but have you ever seen what happens to a cat when it loses its whiskers? Poor Moonstalkers.",
            date = "2011-03-09T11:28:36-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13566#comments:id=1362217",
        },
        {
            id = 1196825,
            score = 25,
            author = "367872",
            text = "Finally figured the bears out...they're hungry! :) Target one and wait...eventually, you'll see the emote \"Hungry Thistle Bear catches a fish!\" and it will go yellow. Run up and loot.",
            date = "2010-11-30T00:26:55-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13566#comments:id=1196825",
        },
        {
            id = 1240799,
            score = 15,
            author = "Shirlnha",
            text = "Tip for Warlocks: Dismiss your demon for this quest. My Felguard would attack the bears and moonstalkers after I looted them, even if they didn't actually aggro me.\n\nI'm not sure if the mage elemental and hunter pets are also affected by this.",
            date = "2010-12-17T12:40:03-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13566#comments:id=1240799",
        },
        {
            id = 1198783,
            score = 8,
            author = "227157",
            text = "Tip for hunters with the bears. Turn on Track Beasts, then once you notice the dot go yellow, that bear can now be gathered from.",
            date = "2010-11-30T20:53:39-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13566#comments:id=1198783",
        },
    },
    [13567] = {
        {
            id = 1272250,
            score = 17,
            author = "Salus",
            text = "Spirit of the Moonstalker (http://www.wowhead.com/quest=13568) gives Blessing of the Moonstalker (http://www.wowhead.com/spell=64340)\nSpirit of the Thistle Bear (http://www.wowhead.com/quest=13597) gives Blessing of the Thistle Bear (http://www.wowhead.com/spell=64329)\nSpirit of the Stag (http://www.wowhead.com/quest=13567) gives Blessing of the Stag (http://www.wowhead.com/spell=64341)",
            date = "2011-01-01T23:21:54-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13567#comments:id=1272250",
        },
        {
            id = 1170533,
            score = 14,
            author = "Ravendwyr",
            text = "You are only able to complete one of the three \"ritual bond\" quests.\nSo if you complete this quest you will not be able to accept Spirit of the Moonstalker (http://cata.wowhead.com/quest=13568) or Spirit of the Thistle Bear (http://cata.wowhead.com/quest=13597).",
            date = "2010-11-14T04:57:42-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13567#comments:id=1170533",
        },
        {
            id = 1162195,
            score = 10,
            author = "696905",
            text = "Increases movement speed by 10% in Darkshore, and the stags are now neutral instead of hostile.",
            date = "2010-11-04T20:03:32-05:00",
            sourceUrl = "https://www.wowhead.com/quest=13567#comments:id=1162195",
        },
        {
