    [13576] = {
        {
            id = 1201161,
            score = 8,
            author = "705845",
            text = "Kill the Unbound Fire Elementals (http://www.wowhead.com/npc=32999) then use the totem on their corpses",
            date = "2010-12-01T22:03:22-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13576#comments:id=1201161",
        },
        {
            id = 1204433,
            score = 7,
            author = "165655",
            text = "Note that standing in the fires around the Blazing Strand does not cause any damage and does not break stealth.  The Unbound Fire Elementals will also take regular damage from fire spells.  New players should try NOT to learn from this, as standing in fire is usually a rapid way to certain death and fire creatures often are immune or resistant to fire spells.",
            date = "2010-12-03T15:01:21-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13576#comments:id=1204433",
        },
        {
            id = 1314739,
            score = 4,
            author = "ethicaodini",
            text = "I believe you can get 2 of these per kill.. It seemed like it was working for me.  When I was leveling my warlock I would hit the quest item a lot when the fire elemental was nearing death.  I would sometimes be able to get 2 counts in one kill.",
            date = "2011-01-29T17:29:50-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13576#comments:id=1314739",
        },
        {
            id = 1398089,
            score = 4,
            author = "Rooibos",
            text = "Probably the most positive thing about this quest is that you don't need to dismount to use Soothing Totem on the corpses.\n\nIt so happened that with all those heirlooms and XP from gathering professions I outleveled the zone. And when doing this quest I killed like 4-5 of the mobs needed before I realized I was also supposed to place the totem on each and every corpse. So I mounted up and easily did the job from a saddle.",
            date = "2011-04-23T23:48:36-05:00",
            sourceUrl = "https://www.wowhead.com/quest=13576#comments:id=1398089",
        },
        {
            id = 1787836,
            score = 1,
            author = "1068578",
            text = "This may have been obvious to others, but it wasn't to me. I needed to search the elementals before I could put down the totem. Hope this helps :)",
            date = "2012-12-26T19:12:35-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13576#comments:id=1787836",
        },
    },
