    [13578] = {
        {
            id = 1094079,
            score = 20,
            author = "152202",
            text = "You know... having done Darkshore in the past a few times, I always remember muttering, \"Stupid Wildkin are EVERYWHERE\" and killing them whenever they got in my way. Its like they were big pigeons.\n\nHow is it now, this quest can make me feel GUILTY about it!\n\nMy hat goes off to you Blizzard. You made me cry.",
            date = "2010-08-02T09:17:39-05:00",
            sourceUrl = "https://www.wowhead.com/quest=13578#comments:id=1094079",
        },
        {
            id = 1188672,
            score = 18,
            author = "710448",
            text = "The feathers are scattered around on the ground.  They can be a little hard to see, so just keep an eye out for the sparkle.",
            date = "2010-11-26T19:38:49-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13578#comments:id=1188672",
        },
        {
            id = 1371587,
            score = 11,
            author = "Karmandie",
            text = "Just wanted to mention that you don't actually have to kill the spirits to get their feathers. That should assuage your guilt a little bit. The feathers are lying on the ground, mostly near trees and rocks, and they're hard to see, so I recommend zooming in like the poster above mentioned. It really helps.\n\nThis really is a sad quest. Reminds me a bit of Old Whitebark (http://www.wowhead.com/quest=8474) in Eversong. I felt like such a jerk after killing him.",
            date = "2011-03-20T10:24:55-05:00",
            sourceUrl = "https://www.wowhead.com/quest=13578#comments:id=1371587",
        },
        {
            id = 1815469,
            score = 1,
            author = "1021255",
            text = "All I can say is if you love this quest so much....get Aroom!",
            date = "2013-02-19T00:54:10-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13578#comments:id=1815469",
        },
        {
            id = 2298202,
            score = 1,
            author = "Krakatua",
            text = "You need the quest https://www.wowhead.com/quest=13577 to be able to get Aroom's quests. The first you get from Aroom is https://www.wowhead.com/quest=13578 and from it you can get https://www.wowhead.com/item=55133 as a reward (which is part of the [transmog-set=134] set). Have fun!",
            date = "2016-01-14T16:07:31-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13578#comments:id=2298202",
        },
    },
