    [13580] = {
        {
            id = 1189075,
            score = 90,
            author = "710572",
            text = "Place the totem behind the altar, the side opposite the sea",
            date = "2010-11-26T23:15:43-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13580#comments:id=1189075",
        },
        {
            id = 1221072,
            score = 21,
            author = "725836",
            text = "Im a druid and i couldn't place the totem. I was in cat form. When i shapeshifted back to my worgen form i could place the totem and finish the quest.\n\nJust a tip, if it dosen't work while shapeshifted try with your normal form.",
            date = "2010-12-10T06:44:58-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13580#comments:id=1221072",
        },
        {
            id = 1301033,
            score = 16,
            author = "Sagmon",
            text = "Look for a large crystal suspended above a temple/altar on the high point across the Blazing Strand.  This is visible from the Questgiver position, or a bit south of it.  Move SW from Questgiver, cross the water where the cliff on the other side is low, then move S to your left, uphill, near cliff edge, past the burning trees and the temple, and out to the very tip and highest point of the cliff (39.7, 62.7).  Drop totem.  Defend.  Note that the quest may be satisfied while some attacking flame elementals are still alive.",
            date = "2011-01-19T21:03:55-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13580#comments:id=1301033",
        },
        {
            id = 1183599,
            score = 10,
            author = "365125",
            text = "I was unable to drop on the slope down from it.  I had to drop on the upward side 39.6, 62.3",
            date = "2010-11-25T02:21:35-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13580#comments:id=1183599",
        },
        {
            id = 1460574,
            score = 9,
            author = "Valder",
            text = "Funny thing about this quest... the totem you drop is the same level as the person dropping it, with equivalent health.  At 85, the totem has over 14k health, meaning you can literally just place it and walk away.  The ritual will finish before the elementals can do even 500 damage to it.",
            date = "2011-07-04T16:37:27-05:00",
            sourceUrl = "https://www.wowhead.com/quest=13580#comments:id=1460574",
        },
    },
