    [13591] = {
        {
            id = 1199894,
            score = 58,
            author = "Cierona",
            text = "What you will need to do to get to this quest:\n\nIt's possible to do these quests first, before the main chain.  They may be required to unlock some of the others below though.\n\n[pre]\nWritings of the Void (http://www.wowhead.com/quest=28529)\nThreat from the Water (http://www.wowhead.com/quest=13522)\nReason to Worry (http://www.wowhead.com/quest=13506)\n  Swift Response (http://www.wowhead.com/quest=13508)\n    One Bitter Wish (http://www.wowhead.com/quest=13511)\n      (+)Timely Arrival (http://www.wowhead.com/quest=13510)\n[/pre]\n\nThe main quest chain:\n[pre]\nThe Last Wave of Survivors (http://www.wowhead.com/quest=13518)\n  The Boon of the Seas (http://www.wowhead.com/quest=13520)\n  Buzzbox 413 (http://www.wowhead.com/quest=13521)\n    No Accounting for Taste (http://www.wowhead.com/quest=13527)\n      Buzzbox 723 (http://www.wowhead.com/quest=13528)\n\009  A Cure In The Dark (http://www.wowhead.com/quest=13554)\009      +\n\009  (?)The Corruption's Source (http://www.wowhead.com/quest=13529)  +\n\009    (+)Bearer of Good Fortune (http://www.wowhead.com/quest=13557) +\n          A Troubling Prescription (http://www.wowhead.com/quest=13831)    +  completion of these 4 unlocks:\n                                      ||\n+-------------------------------------+\n||\n+ The Final Flame of Bashal'Aran (http://www.wowhead.com/quest=13562)\n    (?)Solace for the Highborne (http://www.wowhead.com/quest=13561)\n  A Love Eternal (http://www.wowhead.com/quest=13563)\n  A Lost Companion (http://www.wowhead.com/quest=13564)\n    Twice Removed (http://www.wowhead.com/quest=13565)     +\n    Unsavory Remedies (http://www.wowhead.com/quest=13598) +\n    Ritual Materials (http://www.wowhead.com/quest=13566)  +\n                      ||\n+---------------------+\n||\n+ The Ritual Bond (http://www.wowhead.com/quest=13569)\n    Spirit of the Stag (http://www.wowhead.com/quest=13567)          \\\n    Spirit of the Moonstalker (http://www.wowhead.com/quest=13568)    } can only do 1/3\n    Spirit of the Thistle Bear (http://www.wowhead.com/quest=13597)  /\n      Grimclaw's Return (http://www.wowhead.com/quest=13599)\n        An Ocean Not So Deep (http://www.wowhead.com/quest=13560) (not required for the chain, but it unlocks)\n        The Shatterspear Invaders (http://www.wowhead.com/quest=13589)\n          Remnants of the Highborne (http://www.wowhead.com/quest=13505)\n            Denying Manpower (http://www.wowhead.com/quest=13507)     +\n          Shatterspear Laborers (http://www.wowhead.com/quest=13504)  ||\n            War Supplies (http://www.wowhead.com/quest=13509)         +\n                                 ||\n+--------------------------------+\n||\n+ On the Brink (http://www.wowhead.com/quest=13513)\n    Strategic Strikes (http://www.wowhead.com/quest=13512)\n      The Looting of Althalaxx (http://www.wowhead.com/quest=13844)\n        The Front Line (http://www.wowhead.com/quest=13590)\n        (?)The Ancients' Ire (http://www.wowhead.com/quest=13514)\n          Ending the Threat (http://www.wowhead.com/quest=13515)\n            Disturbing Connections (http://www.wowhead.com/quest=13591)\n[/pre]\n\nDon't forget this one for the pet ;)\n\n[pre]\n              Remembrance of Auberdine (http://www.wowhead.com/quest=13570)\n[/pre]\n\n(?) = quest giver is on the path to the above quest, and may be available seperately\n(+) = item to start this quest drops off the objective of the previous quest (may not require previous quest)",
            date = "2010-12-01T09:51:02-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13591#comments:id=1199894",
        },
        {
            id = 1909829,
            score = 20,
            author = "silkfire",
            text = "Cierona's list shows ALL quests that are available on your way towards Disturbing Connections.\n\nHere's a list of the least amount of quests you need to complete, if you want to finish this long quest chain faster:\n\nAt Lor'danel:\nhttps://www.wowhead.com/quest=13522\nhttps://www.wowhead.com/quest=13518\n-->https://www.wowhead.com/quest=13521\n---->https://www.wowhead.com/quest=13527\n------>https://www.wowhead.com/quest=13528\n-------->https://www.wowhead.com/quest=13554\n-------->https://www.wowhead.com/quest=13529\n\nAt Withering Thicket/Ruins of Lornesta (southwest of Lor'danel)\nhttps://www.wowhead.com/quest=13564\n-->https://www.wowhead.com/quest=13565\n-->https://www.wowhead.com/quest=13598\n-->https://www.wowhead.com/quest=13566\n---->https://www.wowhead.com/quest=13569\n------>https://www.wowhead.com/quest=13567 or https://www.wowhead.com/quest=13568 or https://www.wowhead.com/quest=13597\n\nAt Ruins of Mathystra/Shatterspear War Camp/Tower of Althalaxx (east of Lor'danel)\nhttps://www.wowhead.com/quest=13589\n-->https://www.wowhead.com/quest=13505\n-->https://www.wowhead.com/quest=13504\n---->https://www.wowhead.com/quest=13507\n---->https://www.wowhead.com/quest=13509\n------>https://www.wowhead.com/quest=13513\n------>https://www.wowhead.com/quest=13512\n------>https://www.wowhead.com/quest=13844\n\nAt Shatterspear Vale (east of Lor'danel)\nhttps://www.wowhead.com/quest=13590\n-->https://www.wowhead.com/quest=13515\n\nLoot https://www.wowhead.com/item=46318 from https://www.wowhead.com/npc=32862 and you will get https://www.wowhead.com/quest=13591.",
            date = "2013-10-18T13:19:53-05:00",
            sourceUrl = "https://www.wowhead.com/quest=13591#comments:id=1909829",
        },
        {
            id = 1981218,
            score = 11,
            author = "Grayy",
            text = "So I noticed that there are a lot of Quest lists that show how to get to Disturbing Connections (http://www.wowhead.com/quest=13591). They pretty much list all the quests in the zone. I don't want to do all the quests so, I'm going to clear up what unlocks what and what is needed to finish this chain.\n\nTo start I'm on a druid that has only done the quest Writings of the Void (http://www.wowhead.com/quest=28529/writings-of-the-void). This is a pretty easy quest and awards two achievements, going down and Ghosts in the Dark (http://www.wowhead.com/achievement=5453).\n\nNext I did The Last Wave of Survivors (http://www.wowhead.com/quest=13518). When I finished there were no new quests so I did Threat from the Water (http://www.wowhead.com/quest=13522) and that unlocked Buzzbox 413 (http://www.wowhead.com/quest=13521). After finishing  Buzzbox 413 (http://www.wowhead.com/quest=13521) do the follow ups: No Accounting for Taste (http://www.wowhead.com/quest=13527) and Buzzbox 723 (http://www.wowhead.com/quest=13528).\n\nNow do The Corruption's Source (http://www.wowhead.com/quest=13529) and A Cure In The Dark (http://www.wowhead.com/quest=13554).\n(A Cure In The Dark (http://www.wowhead.com/quest=13554) might not be reqired because it didn't unlock anything when I finished it.)\n\nDoing The Corruption's Source (http://www.wowhead.com/quest=13529) unlocks The Final Flame of Bashal'Aran (http://www.wowhead.com/quest=13562), A Love Eternal (http://www.wowhead.com/quest=13563) and A Lost Companion (http://www.wowhead.com/quest=13564).\n\nTurning in A Lost Companion (http://www.wowhead.com/quest=13564) unlocks Twice removed (http://www.wowhead.com/quest=13565), Unsavory Remedies (http://www.wowhead.com/quest=13598) and Ritual Materials (http://www.wowhead.com/quest=13566). Do all three.\n\nThe next step is The Ritual Bond (http://www.wowhead.com/quest=13569). To do this quest you need to pick an animal. That animal will give you a preeminent buff that you will have when ever you are in Darkshore.\n\nYour choices are:\nIf you choose Moonstalkers you get Blessing of the Moonstalker (http://www.wowhead.com/spell=64340)\nIf you choose the Bears you get Blessing of the Thistle Bear (http://www.wowhead.com/spell=64329)\nIf you choose the Stags you get Blessing of the Stag (http://www.wowhead.com/spell=64341)\n\nThen I did Grimclaw's Return (http://www.wowhead.com/quest=13599) but I dont think it's required because The Shatterspear Invaders (http://www.wowhead.com/quest=13589) was unlocked before I turned it in.\n\nDo The Shatterspear Invaders (http://www.wowhead.com/quest=13589) and you are now where you want to be. Do the follow up quests Remnants of the Highborne (http://www.wowhead.com/quest=13505) and Shatterspear Laborers (http://www.wowhead.com/quest=13504). Now do Denying Manpower (http://www.wowhead.com/quest=13507) and War Supplies (http://www.wowhead.com/quest=13509).\n\nSide note on Denying Manpower (http://www.wowhead.com/quest=13507). In my opinion, the reward from this quest, Tysha's Chestguard (http://www.wowhead.com/item=52597), is the best black leather you can get from quests at lvl 20 and that makes it good F2P mog gear.\n\nNow do:\nOn the Brink (http://www.wowhead.com/quest=13513) and Strategic Strikes (http://www.wowhead.com/quest=13512).\n\nPick up The Front Line (http://www.wowhead.com/quest=13590). Go over to the night elf mounted on a dark saber. She can give you a ride to your quest turn in.\n\nThe Ancients' Ire (http://www.wowhead.com/quest=13514) is not needed but it gives you a ride to the next step as well as an easy way to clear the path.\n\nNow pick up Ending the Threat (http://www.wowhead.com/quest=13515). You will need to talk to the quest giver again so she shoots Jor'kil and makes him weak for you. Make sure you loot Jor'kil as he drops Hellscream's Missive (http://www.wowhead.com/item=46318). The Missive starts the quest Disturbing Connections (http://www.wowhead.com/quest=13591).\n\nRemembrance of Auberdine (http://www.wowhead.com/quest=13570) opens up after this quest and rewards Withers (http://www.wowhead.com/item=46325).",
            date = "2014-07-16T18:52:40-05:00",
            sourceUrl = "https://www.wowhead.com/quest=13591#comments:id=1981218",
        },
        {
            id = 1207376,
            score = 2,
            author = "splunk",
            text = "I needed 4 more quests in Darkshore for the quest achievement, and I had no idea where to look. I thought I had done this, but I for some reason hadn't actually looted the item after killing him (http://www.wowhead.com/npc=32862) the first time for a quest.\n\nAnyways, this opens up 3 (http://www.wowhead.com/quest=13519) more (http://www.wowhead.com/quest=13596) quests (http://www.wowhead.com/quest=13570). The last quest linked also rewards a vanity pet (http://www.wowhead.com/item=46325), for all you pet collectors out there.",
            date = "2010-12-05T02:46:07-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13591#comments:id=1207376",
        },
        {
            id = 5199089,
            score = 2,
            author = "BlackHalo66",
            text = "If you attack and defeat the trolls by yourself, you will not be offered the Disturbing Connections quest.\nMake sure to speak to Huntress Sandrya Moonfall first, to initiate the attack.",
            date = "2021-06-18T23:26:46-05:00",
            sourceUrl = "https://www.wowhead.com/quest=13591#comments:id=5199089",
        },
    },
    [13594] = {
