    [13597] = {
        {
            id = 1272248,
            score = 15,
            author = "Salus",
            text = "Spirit of the Moonstalker (http://www.wowhead.com/quest=13568) gives Blessing of the Moonstalker (http://www.wowhead.com/spell=64340)\nSpirit of the Thistle Bear (http://www.wowhead.com/quest=13597) gives Blessing of the Thistle Bear (http://www.wowhead.com/spell=64329)\nSpirit of the Stag (http://www.wowhead.com/quest=13567) gives Blessing of the Stag (http://www.wowhead.com/spell=64341)",
            date = "2011-01-01T23:21:13-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13597#comments:id=1272248",
        },
        {
            id = 1170534,
            score = 13,
            author = "Ravendwyr",
            text = "You are only able to complete one of the three \"ritual bond\" quests.\nSo if you complete this quest you will not be able to accept Spirit of the Moonstalker (http://cata.wowhead.com/quest=13586) or  Spirit of the Stag (http://cata.wowhead.com/quest=13567).",
            date = "2010-11-14T04:58:19-06:00",
