    [13599] = {
        {
            id = 1119176,
            score = 40,
            author = "99010",
            text = "Wow, the ending text for this quest made me cry a little.",
            date = "2010-09-12T10:58:32-05:00",
            sourceUrl = "https://www.wowhead.com/quest=13599#comments:id=1119176",
        },
        {
            id = 1182341,
            score = 22,
            author = "457013",
            text = "In all honesty my heart skipped a beat when i read what had happened... that was a legitimately surprising, sad, and interesting quest line.",
            date = "2010-11-24T16:51:00-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13599#comments:id=1182341",
        },
        {
            id = 1197888,
            score = 16,
            author = "714139",
            text = "Grimclaw's Return\n\nYou've returned! It is good to see you again. I suppose we have you to thank for Grimclaw's return?\n\nI'm afraid... I have some bad news. I've been unable to purge the toxin... their conditions worsen. Gershalla died shortly after you left, and Volcor... Volcor passed just before you came back.\n\nHe lived long enough to see Grimclaw come back safely, so he died with a smile on his face. I'm just sorry that I couldn't do more.\n\nFor now, I'm doing everything I can to save Shadlyn, so please excuse me.\n\n========================\nluckily, the 'Print Screen' button comes in handy ;-)\nIn all my years of playing WoW, I probably have never cried till I did this quest *sniffles*. R.I.P. Volcor and all those who have passed. May you find peace in the embrace of the goddess.",
            date = "2010-11-30T13:14:38-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13599#comments:id=1197888",
        },
        {
            id = 1396480,
            score = 4,
            author = "451872",
            text = "I wish I´ve never completed this one T_T *cry*",
            date = "2011-04-21T16:37:35-05:00",
            sourceUrl = "https://www.wowhead.com/quest=13599#comments:id=1396480",
        },
        {
            id = 1180371,
            score = 1,
            author = "605737",
            text = "Anyone know what the completion text was? I rushed through it and didn't notice Volcor until I had.",
            date = "2010-11-24T05:32:37-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13599#comments:id=1180371",
        },
    },
    [13601] = {
        {
            id = 1251219,
            score = 6,
            author = "735720",
            text = "If you, like me, got to the refugee camp and did all the quests before this quest was offered, and went back to finish the rest of northern Darkshore, there's no need to worry about missing out on the quest.\nShe will offer this quest once you complete the two Twilight's Hammer quests and will still offer it even if you did all the refugee camp quests beforehand.\nHappy questing! ~CharrShaman",
            date = "2010-12-21T22:19:15-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13601#comments:id=1251219",
        },
        {
            id = 1186447,
            score = 2,
            author = "436668",
            text = "Does anyone know how to \"unlock\" this NPC? I am missing this quest, and the 2 Twilight quests she has, and she has no interaction for me, no way to pickup the quests. Stuck at 88/90 in Darkshore because of this.",
            date = "2010-11-26T01:25:52-06:00",
