            date = "2011-01-03T23:04:32-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13626#comments:id=1276010",
        },
        {
            id = 1308033,
            score = 8,
            author = "193729",
            text = "I stupidly interpreted the cloak's \"while peaceful\" use to mean I would remain stealthed so long as I wasn't in combat (you know, so long as I was peaceful!), when it actually means you just can't initiate its use during combat. I came running out of the tower, jumped gleefully off a tiny hill, took about 3 damage and immediately became visible to the six trillion horde surrounding me.",
            date = "2011-01-24T13:29:08-06:00",
