    [13628] = {
        {
            id = 1859496,
            score = 359,
            author = "burningglove",
            text = "This had a bug when I did it.  I got the reins from Kadrak as instructed, but then couldn't mount Brutusk.  To fix it I dropped the quest and then went straight to Brutusk, mounted easily and completed the quest, no reins needed.",
            date = "2013-05-29T04:59:50-05:00",
            sourceUrl = "https://www.wowhead.com/quest=13628#comments:id=1859496",
        },
        {
            id = 1945525,
            score = 84,
            author = "Urkberserk",
            text = "After you accept the quest and speak to Kadrak (http://www.wowhead.com/npc=34006), you'll receive Kadrak's Reins (http://www.wowhead.com/item=45051), which gives you a buff that will allow you to ride Brutusk (http://www.wowhead.com/spell=62885). The beast, Brutusk (http://wowhead.com/npc=33374), stands a few yards away waiting for you to jump aboard, but if the quest is bugged you can't mount. If that happens, simply /reload your UI.",
            date = "2014-02-21T12:33:57-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13628#comments:id=1945525",
        },
        {
            id = 1685471,
            score = 35,
            author = "Princeofchaos",
            text = "Must complite quests:\n\n1. [quest=13613 domain=www]\n2. [quest=13618 domain=www]\n3. [quest=13619 domain=www]\n4. [quest=13620 domain=www]\n5. [quest=13621 domain=www]\n\nThen go to Truun for your quest. Dont forget to take Kadrak's Reins from Kadrak.",
            date = "2012-07-07T06:36:44-05:00",
            sourceUrl = "https://www.wowhead.com/quest=13628#comments:id=1685471",
        },
        {
            id = 1421978,
            score = 20,
            author = "255851",
            text = "You need to talk to Kadrak to get Kadrak's Reins to ride Brutus.",
            date = "2011-05-18T18:49:07-05:00",
            sourceUrl = "https://www.wowhead.com/quest=13628#comments:id=1421978",
        },
        {
            id = 2318303,
            score = 18,
            author = "LiriellGarrosh",
            text = "Here we are, well into WoD, and this quest is still bugged. I was able to complete it by following instructions here to abandon (didn't hear the sound file for an abandoned quest, and there was no yellow text saying it had been abandoned) and pick it up again. The reins stay in your bags, and you will be able to right click Brutusk to mount him.\n\nEDIT:  Once again, I am doing this quest on an alt. However, this time, I was able to pick up the quest, get the reins from Kadrak, but did not need to abandon the quest. I sat at Brutusk and logged out. Upon logging in again, I was able to mount Brutusk.",
            date = "2016-03-30T16:07:29-05:00",
            sourceUrl = "https://www.wowhead.com/quest=13628#comments:id=2318303",
        },
    },
    [13630] = {
        {
            id = 1245560,
            score = 21,
            author = "Duendelstein",
            text = "Thank you, .\n\nWith the moonstones of Ordil'Aran deactivated, we should not need to worry about any further incursions of furbolg here.\n\nHowever, my scouts have returned with disturbing news from the furbolg village. There is an imminent danger massing there.\n\nI wonder, might I entice you to carry a warning to Astranaar for me?\n\nIs there ever a follow up to carry a warning to Astranaar?  Haven't seen one yet...",
            date = "2010-12-19T11:58:38-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13630#comments:id=1245560",
        },
        {
            id = 1183337,
            score = 4,
            author = "238963",
            text = "The Moonstones will have an aura around them if they are able to be deactivated. There is a short cooldown between deactivations (it seems to be a few minutes at most). If you can't click on them, kill some mobs or wait until the glow shows up.",
            date = "2010-11-25T00:10:14-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13630#comments:id=1183337",
        },
        {
            id = 1341854,
            score = 4,
            author = "667568",
            text = "Evidently, when you've got a few thousand Horde staring at you from a hundred feet away, clearly the furbolgs are a more important matter.",
            date = "2011-02-19T05:56:54-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13630#comments:id=1341854",
        },
        {
            id = 2869659,
            score = 1,
            author = "Tigronn",
            text = "Because it's red.",
            date = "2019-02-04T05:09:21-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13630#comments:id=2869659",
        },
    },
