    [13635] = {
        {
            id = 3207982,
            score = 7,
            author = "Arrassi",
            text = "Quest giver will not give me the quest. I have completed A Pilot's Revenge, but before I worked on the South Gate Pass quests I had completed the Valley of Kings quests which includes: In Defense of the King's Lands, A Decisive Strike and Out of Gnoll-where. The quests I can't complete are South Gate Status Report, The Captured Mountaineer and Onward to Thelsamar.",
            date = "2020-05-22T09:03:16-05:00",
            sourceUrl = "https://www.wowhead.com/quest=13635#comments:id=3207982",
        },
        {
            id = 1182807,
