        {
            id = 1180902,
            score = 7,
            author = "skevans",
            text = "This quest was added in patch 4.03a on 24 Nov 2010 just prior to cataclysm.\n\nThe quest is obtainable from Mountaineer Kadrell (http://www.wowhead.com/npc=1340) in Thelsamar, Loch modan. (co-ords 35 46) .\n\n Deliver the orders to Mountaineer Stormpike (http://www.wowhead.com/npc=1343) who can be found at Algaz station (http://www.wowhead.com/zone=925/algaz-station) north west of Thelsamar. Coordinates 25 17.",
            date = "2010-11-24T09:35:43-06:00",
