            author = "483979",
            text = "When I reached the caravan there was no ambush, just Huldar and Miran standing around without Saean or any Dark Irons in sight. Does this new version not have an ambush event, or was it bugged? Quest completed just fine, however.",
            date = "2010-11-28T13:48:12-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13639#comments:id=1193509",
        },
        {
            id = 2501313,
            score = 1,
            author = "Karadine",
            text = "If you just completed this quest and aren't sure where to go next:\n\nMake sure you have completed https://www.wowhead.com/quest=13639, https://www.wowhead.com/quest=309, https://www.wowhead.com/quest=13650, and https://www.wowhead.com/quest=26961.\n\nIf you completed quests in this area prior to Cataclysm (patch 4.0.3), then there is a bug preventing the next quest, https://www.wowhead.com/quest=13647, from appearing.  If you want to proceed, just head to Farstrider Lodge.",
            date = "2017-06-15T14:19:21-05:00",
            sourceUrl = "https://www.wowhead.com/quest=13639#comments:id=2501313",
        },
    },
    [13640] = {
        {
            id = 1076432,
            score = 18,
            author = "447186",
            text = "When you have finished talking to Gorka find yourself a Demoralized Peon to talk to. If they agree to chop wood for you follow them and stick close by. They will be attacked by Ashenvale Stalkers (Nightelves). Your job is to kill them before they kill your poor frightened peons. If you are successfull your peon will provide you with a bundle of \"Freshly Cut Wood\". It will be lying on the ground next to your peon. Your peon will then despawn and you will have to find another one to do it all over again.\n\nWhen you have your five bundles of wood, hand the quest in to Gorka.\n\nLance\nBeta tester for;\nWrath of the Litch King\nCataclysm",
            date = "2010-07-09T00:47:14-05:00",
            sourceUrl = "https://www.wowhead.com/quest=13640#comments:id=1076432",
        },
        {
            id = 1184098,
            score = 13,
            author = "99869",
            text = "Note that as of the current patch if you are mounted you will not receive the wood.",
            date = "2010-11-25T07:17:38-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13640#comments:id=1184098",
        },
        {
            id = 1193206,
            score = 6,
            author = "Innuendo",
            text = "If you attack the Stalker before it attacks the Peon, it will not drop wood.",
            date = "2010-11-28T11:40:22-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13640#comments:id=1193206",
        },
        {
            id = 1580503,
            score = 6,
            author = "nelsoncs",
            text = "This quest seems to have been fixed/changed.\nI was able to loot the wood when killing the stalker before it attacked.\nLooting the wood dismounts you.",
            date = "2011-11-25T11:41:56-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13640#comments:id=1580503",
        },
        {
            id = 1590439,
            score = 5,
            author = "634661",
            text = "Of course if you don't read the quest before doing it you might think this is just a simple gathering quest where it's laying there waiting for you to pick it up, well not that much so. You have got to walk around the camp and look for Orcs(Female and Male both) that are shaking is fear of the Night Elf's lurking around. Talk to the Orc and they'll tell you to just watch their back while they cut wood for you to gather for the quest and for me prob about 4/5 times a Elf came Invis up to the worker, just kill ASAP.",
            date = "2011-12-05T11:42:57-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13640#comments:id=1590439",
        },
    },
    [13642] = {
        {
            id = 1379329,
            score = 19,
            author = "Euphemia",
            text = "If you're \"half blind\", like me, then here's an explanation for those who don't use coords. If you stand with Keeper Heartwise and look towards the tilted remains of a nightelf lightwell - a bit further away, you will see the beams of light coming through the tree branches. Inside those beams is where you want to use the Unbathed Concoction (http://www.wowhead.com/item=45066).\n\n/cheers",
            date = "2011-03-29T15:45:18-05:00",
            sourceUrl = "https://www.wowhead.com/quest=13642#comments:id=1379329",
        },
        {
            id = 1200503,
