            author = "Elivran",
            text = "Had the same problem.  Quest is not given by NPC.\nQuest may have been removed with Patch 4.1 or 4.2",
            date = "2011-07-19T01:38:32-05:00",
            sourceUrl = "https://www.wowhead.com/quest=13647#comments:id=1473796",
        },
        {
