    [13648] = {
        {
            id = 1182255,
            score = 122,
            author = "708194",
            text = "You need to climb the mountain. The path begins in (40.4, 66.8).\n\nThe cave entrance is in (37.7,62.4).\n\nHe's got 494 HP.\n\nThere's also a new quest in the cave, given by an Stolen Explore's League Document.",
            date = "2010-11-24T16:28:15-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13648#comments:id=1182255",
        },
        {
            id = 1179102,
            score = 44,
            author = "businesscats",
            text = "There's a path up the hill on the East side.",
            date = "2010-11-23T20:15:33-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13648#comments:id=1179102",
        },
        {
            id = 1180821,
            score = 15,
            author = "skevans",
            text = "This quest was added in patch 4.03a on 24 Nov 2010 just prior to cataclysm.\n\nThe quest is obtainable from a wanted poster in Thelsamar at co-ordinates 37.31 46.49, and it's objective is to kill Gorick Guzzledraught (http://www.wowhead.com/npc=33456).\n\nGorick can be found by heading to 40 57 and climbing the mountain path. If you are not using coordinates then stand facing the front of the wanted poster and the start of the path is a few hundred yards ahead to your eleven o'clock position.\n\nGorick is a level 12 non elite dwarf hiding in a cave, the entrance to which is at 37 62.\n\nHe has 494 health and has a respawn of less than two minutes.\n\nWhilst there be sure to grab explorer's league document (1 of 6) (http://www.wowhead.com/quest=13656).\n\nOnce you have completed the quest head to Magistrate Bluntnose (http://www.wowhead.com/npc=1139) at 34 44 in Thelsamar to hand it in.",
            date = "2010-11-24T09:12:21-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13648#comments:id=1180821",
        },
        {
            id = 2858154,
            score = 13,
            author = "Ocyron",
            text = "This quest is awkward when you're playing as a Dark Iron Dwarf.",
            date = "2018-12-12T18:28:37-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13648#comments:id=2858154",
        },
        {
            id = 1988554,
            score = 8,
            author = "MDiane",
            text = "When heading to this quest go all the way through the Trogg camp and at the cave go right and follow all the way around the mountain.  Eventually you will find another path that leads to the top of the mountain and a second cave.  The Dark Iron Spy is sitting just inside the cave near a campfire.",
            date = "2014-08-05T17:29:43-05:00",
            sourceUrl = "https://www.wowhead.com/quest=13648#comments:id=1988554",
        },
    },
