        {
            id = 1688126,
            score = 17,
            author = "Marzen",
            text = "To find these three artifacts:\n\nBroken Tablet is in the South East area of the dig\n\nOverdressed Woman is in the East central area of the dig\n\nUpturned Giant is in the North central area of the dig\n\nIf you start at Ironbeard's tent, face the ruins to the East and travel along the trench to the right. Then follow the same trench as it curves around to the East and then North.\n\nThe quest cues on Blizzard's map weren't all that helpful.",
            date = "2012-07-14T16:23:44-05:00",
            sourceUrl = "https://www.wowhead.com/quest=13650#comments:id=1688126",
