            text = "A macro to check what quests you have not done:/run for k,v in pairs{One=13656,Two=13655,Three=13657,Four=13658,Five=13660,Six=13659}do print(format(\"%s: %s\",k,IsQuestFlaggedCompleted(v)and\"\\124cff00ff00Yes\\124r\"or\"\\124cffff0000No\\124r\"))end",
