    [13661] = {
        {
            id = 1473836,
            score = 41,
            author = "Ashkir",
            text = "You obtain this quest after you collect and turn in all six stolen Explorer's League documents.\n\nclick here (http://www.wowhead.com/search?q=explorer%27s+league+document) for a list.",
            date = "2011-07-19T02:22:34-05:00",
            sourceUrl = "https://www.wowhead.com/quest=13661#comments:id=1473836",
        },
        {
            id = 2852653,
            score = 18,
            author = "Zyland",
            text = "Came up with a small line of code to list out your current progress and coordinates to missing documents.\n\n/run local t,w={13656,13655,13657,13658,13660,13659},{\"36.8,61.2\",\"41.3,39.1\",\"61.6,73.1\",\"68.1,66.0\",\"53.7,38.2\",\"73.1,35.9\"}for i=1,6 do f=IsQuestFlaggedCompleted(t); print(i,\"is\",f and \"\\124cFF00FF00DONE\" or \"\\124cFFFF0000NOT DONE(\" .. w..\")\")end\n\nSpecial thanks to Nightswifty (https://www.wowhead.com/user=Nightswifty) for his comment on Lucid Nightmare which helped me figure out how to color color the output. And thanks to CleonanTehGnome (https://www.wowhead.com/user=CleonanTehGnome), for posting the coordinates to the documents in one place.",
            date = "2018-11-12T20:10:33-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13661#comments:id=2852653",
        },
        {
            id = 5533081,
            score = 1,
            author = "Gwnyfar",
            text = "After I turned in the sixth Explorer's League document, this quest became available. When I accepted this quest, I got the message \"You don’t meet the requirements for that quest\", then this quest auto-completed.",
            date = "2023-01-22T12:00:55-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13661#comments:id=5533081",
        },
        {
            id = 1507525,
            score = -10,
            author = "644392",
            text = "this is a very easy to do quest.",
            date = "2011-08-31T14:36:18-05:00",
            sourceUrl = "https://www.wowhead.com/quest=13661#comments:id=1507525",
        },
    },
    [13662] = {
        {
            id = 1492804,
            score = 44,
            author = "864585",
            text = "Sadly, https://www.wowhead.com/quest=7722 has been deleted by Blizzard.  Now the path to go to get to these repeatable quests is, start out Thorium Advance (71, 53) in [zone=51].  Completing those quests will lead you to Thorium Point (37, 27), which will lead you through a series of quests by Iron Summit (40, 69) and The Cauldron (55, 44).  After you've completed this chain (all in [zone=51]) you will be lead back to Thorium Point, where there will be a repeatable quest above https://www.wowhead.com/npc=14624, where you can turn all the https://www.wowhead.com/item=18945 in to get exalted.",
            date = "2011-08-11T19:05:00-05:00",
            sourceUrl = "https://www.wowhead.com/quest=13662#comments:id=1492804",
        },
        {
            id = 1516872,
            score = 32,
            author = "778141",
            text = "If you're on this page because you're looking to farm rep with the Thorium Brotherhood take my advice please. Check out your auction house for the prices of: Lava Cores (http://www.wowhead.com/item=17011/lava-core),  Fiery Cores (http://www.wowhead.com/item=17010/fiery-core),  Dark Iron Ore (http://www.wowhead.com/item=11370/dark-iron-ore) and  Core Leather (http://www.wowhead.com/item=17012/core-leather). When the prices are right for your budget buy them and stock up on them. Turn them in for rep with the Thorium Brotherhood at this  NPC  (http://www.wowhead.com/npc=12944). He's at the Grim Guzzler in Blackrock Depths (http://www.wowhead.com/zone=1584/blackrock-depths). If you don't know how to get to the Grim Guzzler this video (http://www.youtube.com/watch?v=_cHGEKddGAI) is great! You should especially look to stock up on Lava Cores (http://www.wowhead.com/item=17011/lava-core) and  Fiery Cores (http://www.wowhead.com/item=17010/fiery-core) because they're usually pretty cheap ( about 20g ) and they will give you 2000 rep for each turn in ( 2200 with  Mr. Popularity (http://www.wowhead.com/spell=78634/mr-popularity) guild perk and 2400 if you're a human ). Including the jog to the Grim Guzzler and assuming you've bought the necessary mats getting to exalted should take you 30 mins max.\n\nI really hope this helps.",
            date = "2011-09-13T05:38:00-05:00",
            sourceUrl = "https://www.wowhead.com/quest=13662#comments:id=1516872",
        },
        {
            id = 1659915,
            score = 30,
            author = "779824",
            text = "To get this quest to open up, I did exactly 35 quests, which gave me https://www.wowhead.com/achievement=4910. I did all the quests at Thorium Advance, including Lunk's quests. I then went to Thorium Point where I completed all the quests which then sent me to Iron Summit. At Iron Summit, I only completed https://www.wowhead.com/npc=47393's quest line, which returned me to Thorium Point. There was only one quest available there. This quest will then bring you into the Slag Pit. After finishing my quests there, I received the quest https://www.wowhead.com/quest=28064, which returned me to Thorium Point. After turning this quest in, I was able to turn in my https://www.wowhead.com/item=18945.\n\nThese are the quests I did.\nNote: Thorium Advance & Thorium Point quests may be a little out of order but if you complete all these quests, you should be able to open up https://www.wowhead.com/quest=13662. FYI, I also did this Horde side.\n\nBadlands\nhttps://www.wowhead.com/quest=28512 (This quest will start you off if you have not picked up the quest from the command/call board in the city.)\n\nThorium Advance\nhttps://www.wowhead.com/quest=27962\nhttps://www.wowhead.com/quest=27961\nhttps://www.wowhead.com/quest=27960\nhttps://www.wowhead.com/quest=27963\nhttps://www.wowhead.com/quest=27964\nhttps://www.wowhead.com/quest=27958\nhttps://www.wowhead.com/quest=27956\nhttps://www.wowhead.com/quest=27957\nhttps://www.wowhead.com/quest=27959\n\nhttps://www.wowhead.com/quest=27965 (Lead-in to Thorium Point quests)\n\nThorium Point\nhttps://www.wowhead.com/quest=27983\nhttps://www.wowhead.com/quest=27976\nhttps://www.wowhead.com/quest=27979\nhttps://www.wowhead.com/quest=27981\nhttps://www.wowhead.com/quest=27977\nhttps://www.wowhead.com/quest=28099\nhttps://www.wowhead.com/quest=27980\nhttps://www.wowhead.com/quest=27982\nhttps://www.wowhead.com/quest=27984 (You probably don't need to do this quest. I did it on accident.)\n\nhttps://www.wowhead.com/quest=27986 (Lead-in to Iron Summit quests)\n\nIron Summit (Do https://www.wowhead.com/npc=47393 quests/questline.)\nhttps://www.wowhead.com/quest=28028\nhttps://www.wowhead.com/quest=28029\nhttps://www.wowhead.com/quest=28030\nhttps://www.wowhead.com/quest=28033\nhttps://www.wowhead.com/quest=28034\nhttps://www.wowhead.com/quest=28035 (You turn in this quest at Thorium Point)\n\nhttps://www.wowhead.com/quest=28052 (This will fly you to the Slag Pit and you can pick up the Slag Pit Questline once inside.)\n\nSlag Pit (Quest Line)\nhttps://www.wowhead.com/quest=28054\nhttps://www.wowhead.com/quest=28055\nhttps://www.wowhead.com/quest=28056\nhttps://www.wowhead.com/quest=28057\nhttps://www.wowhead.com/quest=28060\nhttps://www.wowhead.com/quest=28062\nhttps://www.wowhead.com/quest=28064\n\nCongratulations, you are done!",
            date = "2012-04-28T16:19:42-05:00",
            sourceUrl = "https://www.wowhead.com/quest=13662#comments:id=1659915",
        },
        {
            id = 1640499,
            score = 10,
            author = "829438",
            text = "These quests are not available once Exalted.  Suppose, like me, you are pathological about filling up your rep bar.  If you are close to 21000, do not make the mistake of scrimping and turning in 4 at a time!  You appear to get the full reward for whatever you turn in, but 4 at a time will leave you with a nearly empty bar when the quest goes away.\n\nOnce you're up above 20500/21000 (or even sooner if you have rep bonuses), just do a stack of 100 and whammo.\n\nFortunately, if you blow it (like I did) you can still turn in items at the Grim Guzzler, including https://www.wowhead.com/item=11370 which drops from some of the construct mobs in [zone=1584].",
            date = "2012-03-17T04:47:39-05:00",
            sourceUrl = "https://www.wowhead.com/quest=13662#comments:id=1640499",
        },
        {
            id = 802028,
            score = 9,
            author = "Khezef",
            text = "You need to have completed What the Flux? (http://www.wowhead.com/?quest=7722) and be Friendly with Thorium Brotherhood in order to do this quest.",
            date = "2009-08-07T04:59:26-05:00",
            sourceUrl = "https://www.wowhead.com/quest=13662#comments:id=802028",
        },
    },
