        {
            id = 1650372,
            score = 22,
            author = "886000",
            text = "Here are the list of quests I had to complete to unlock this quest (in order of completion):\n1. Npc: https://www.wowhead.com/npc=8582 , Quest: https://www.wowhead.com/quest=13618\n2. Npc: https://www.wowhead.com/npc=33294 , Quest: https://www.wowhead.com/quest=13619\n3. Npc: https://www.wowhead.com/npc=8582 , Quest: https://www.wowhead.com/quest=13620\n4. Npc: https://www.wowhead.com/npc=33263 , Quest: https://www.wowhead.com/quest=13621\n5. Npc: https://www.wowhead.com/npc=33284 , Quest: https://www.wowhead.com/quest=13628\n6. Npc: https://www.wowhead.com/npc=33421 , Quest: https://www.wowhead.com/quest=13640\n7. Npc: https://www.wowhead.com/npc=33421 , Quest: https://www.wowhead.com/quest=13651\n8. Npc: https://www.wowhead.com/npc=33421 , Quest: https://www.wowhead.com/quest=13653\n\nBug Warning\nThe following quest https://www.wowhead.com/quest=13712 is bugged (as of the patch this was posted, Patch 4.3.3).\n\nWork around\nFollow skarpethinn's intructions in the comments on https://www.wowhead.com/quest=13712 . This method has been tested successfully by myself.\n\n9. Npc: https://www.wowhead.com/npc=8582 , Quest: https://www.wowhead.com/quest=13712\n10. Npc: https://www.wowhead.com/npc=33837 , Quest: https://www.wowhead.com/quest=13803\n\nAfter completing https://www.wowhead.com/quest=13803 , The first quest in this series (Npc: Splintertree Demolisher https://www.wowhead.com/npc=33726 , Quest: https://www.wowhead.com/quest=13730 ) will be unlocked.\nHope this helps :) , Please excuse the wall of text and let me know if I need to change anything.",
            date = "2012-04-07T23:30:13-05:00",
            sourceUrl = "https://www.wowhead.com/quest=13798#comments:id=1650372",
        },
    },
    [13801] = {
        {
            id = 1076475,
            score = 6,
            author = "447186",
            text = "The night elf ghosts Pixel is talking about are the Severed Keepers (http://cata.wowhead.com/npc=3803) and Severed Druids (http://cata.wowhead.com/npc=3799) that can be found both outside and inside the Dor'Danil Barrow Den. Easy to get your 15 kills when doing the other quest around the area.\n\nLance\nBeta tester for;\nWrath of the Litch King\nCataclysm",
            date = "2010-07-09T02:33:25-05:00",
            sourceUrl = "https://www.wowhead.com/quest=13801#comments:id=1076475",
        },
        {
            id = 1319742,
            score = 6,
            author = "724683",
            text = "is there a prerequisite for this quest?",
            date = "2011-02-02T20:17:21-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13801#comments:id=1319742",
        },
        {
            id = 1886479,
            score = 1,
            author = "waiteman",
            text = "I'm fairly certain this quest should give Warsong Outrider (http://www.wowhead.com/faction=889) rep instead of Warsong Offensive (http://www.wowhead.com/faction=1085) .. probably just a typo or assignment error, unless they are really being clever with the lore and it's way over my head!\n\nI noticed because when I turned this quest in, I discovered the remaining Horde Expedition (http://www.wowhead.com/factions=1097.1052) factions and showed a little bit of rep with each (89 into Neutral):\n\nThe Taunka (http://www.wowhead.com/faction=1064)\nThe Sunreavers (http://www.wowhead.com/faction=1124)\nThe Hand of Veneance (http://www.wowhead.com/faction=1067)",
            date = "2013-08-12T12:03:50-05:00",
            sourceUrl = "https://www.wowhead.com/quest=13801#comments:id=1886479",
        },
        {
            id = 2326682,
            score = 1,
            author = "GetOverHere93",
            text = "Anybody notice The Green Mile reference? =)",
            date = "2016-04-27T18:45:58-05:00",
            sourceUrl = "https://www.wowhead.com/quest=13801#comments:id=2326682",
        },
    },
    [13803] = {
        {
            id = 1076459,
            score = 26,
            author = "447186",
            text = "Durak is located inside the Splintertree Mine. The mine entrance is at the back of Splintertree Post. Go inside and follow the mineshaft down. When you come to the branch to the left, take it. Durak is at the back under an awning. Co-ords are 52,57.\n\n Lance\nBeta tester for;\nWrath of the Litch King\nCataclysm",
            date = "2010-07-09T01:49:15-05:00",
            sourceUrl = "https://www.wowhead.com/quest=13803#comments:id=1076459",
        },
    },
    [13805] = {
        {
            id = 1076471,
            score = 102,
            author = "447186",
            text = "Enter the Dor'Danil Barrow Den and you will see red glowing dots on the floor. These lead the way to the Forest Heart, which is a big brown spiky egg shaped thing suspended in mid air. It's in the middle of one of the platforms with pathways off it. See the screenshot.\n\nLance\nBeta tester for;\nWrath of the Litch King\nCataclysm",
            date = "2010-07-09T02:19:54-05:00",
            sourceUrl = "https://www.wowhead.com/quest=13805#comments:id=1076471",
        },
        {
            id = 1285637,
            score = 20,
            author = "Noobiedoobie",
            text = "As Dawnraid said, look for the little + on your minimap when you get near the co ords. Also, when the blood drops inside the cave end do not (I repeat DO NOT) jump down the bottom of the platform.\n\nThe heart was directly above my head so I didn't see it initially.\n\nHope the screenshots I took help.",
            date = "2011-01-09T10:47:21-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13805#comments:id=1285637",
        },
        {
            id = 1391608,
            score = 20,
            author = "Gethe",
            text = "the alliance gets https://www.wowhead.com/quest=13796 to restore the heart after the horde character corrupts it.",
            date = "2011-04-15T00:17:25-05:00",
            sourceUrl = "https://www.wowhead.com/quest=13805#comments:id=1391608",
        },
        {
            id = 1730505,
            score = 15,
            author = "1036949",
            text = "I had trouble finding the location of this quest; here's some help. There's a three-way meeting of roads at 74.6, 76.4. Take the road running east-northeast, you'll find the mine almost immediately. (Mine entrance coordinates are 75.8, 75.4.) As mentioned above, from that point forward you have to follow the little red dots on the floor. You'll go deep into the mine until you find a circular room with a giant floating spore in it; use the given item on the spore, boom, done.",
            date = "2012-10-03T22:15:10-05:00",
            sourceUrl = "https://www.wowhead.com/quest=13805#comments:id=1730505",
        },
        {
            id = 1184173,
            score = 12,
            author = "507338",
            text = "Make sure to stay clear of the Alliance NPC, Gaivan Shadewalker, on your way into the den.",
            date = "2010-11-25T08:08:08-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13805#comments:id=1184173",
        },
    },
    [13806] = {
        {
            id = 1186171,
            score = 10,
            author = "29634",
            text = "Must complete Diabolical Plans (http://www.wowhead.com/quest=26447) and Never Again! (http://www.wowhead.com/quest=26449) before Locke Okarr (http://www.wowhead.com/npc=11820) will display this quest.",
            date = "2010-11-25T22:53:51-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13806#comments:id=1186171",
        },
        {
            id = 1076773,
            score = 8,
            author = "447186",
            text = "Just collect the glowing purple gems hovering in the air. I managed to find all that I needed in Satyrnaar. Checkout the screenshot to see what they look like.\n\nLance\nBeta tester for;\nWrath of the Litch King\nCataclysm",
            date = "2010-07-09T14:57:10-05:00",
            sourceUrl = "https://www.wowhead.com/quest=13806#comments:id=1076773",
        },
        {
            id = 1188885,
