            text = "Pulsing purple crystals hovering over purple runes.  You'll be able to find all you need in Satyrnaar.",
            date = "2010-11-26T21:21:27-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13806#comments:id=1188885",
        },
    },
    [13808] = {
