    [13815] = {
        {
            id = 2071366,
            score = 25,
            author = "1417241",
            text = "I have issues completing the quest. https://www.wowhead.com/npc=33889 Doesn't appear to complete it. I have in total 2 quest to complete trough him, ( https://www.wowhead.com/quest=13815 and https://www.wowhead.com/quest=13865 )",
