    [13831] = {
        {
            id = 1437753,
            score = 16,
            author = "Hemlock",
            text = "You can find this Quest inside the very same cave that A Cure In The Dark (http://www.wowhead.com/quest=13554) and The Corruption's Source (http://www.wowhead.com/quest=13529) take you.\n\nJust go straight as soon as you enter the cave and walk down the spiral pathway.  When you reach the bottom, head left into the next area and you should find Apothecary Furrows (http://www.wowhead.com/npc=33980) and his Disgusting Workbench (http://www.wowhead.com/object=194714#starts)!",
            date = "2011-06-09T11:45:05-05:00",
            sourceUrl = "https://www.wowhead.com/quest=13831#comments:id=1437753",
        },
        {
            id = 2260968,
