        },
        {
            id = 1713732,
            score = 7,
            author = "Atratzu",
            text = "To elaborate in my own fashion:\n*The book is near Teegan\n*Second floor (you only go up stairs inside of the building once)\n*The book is laying flat on the ground on the South-Eastern platform\n\nHopefully that will help out anyone else with the same mind-twist as myself. :)",
            date = "2012-09-14T19:56:15-05:00",
            sourceUrl = "https://www.wowhead.com/quest=13844#comments:id=1713732",
        },
        {
            id = 2100498,
