    [13849] = {
        {
            id = 1892814,
            score = 20,
            author = "1121421",
            text = "I love how none of the Sentinels are even bothering to attempt putting out the fires...\nJust nonchalantly walking around.",
            date = "2013-09-04T11:51:41-05:00",
            sourceUrl = "https://www.wowhead.com/quest=13849#comments:id=1892814",
        },
        {
            id = 1435226,
            score = 12,
            author = "martychonks",
            text = "It would sure be nice to have this quest's bucket of water during Hallow's End...",
            date = "2011-06-06T00:02:27-05:00",
            sourceUrl = "https://www.wowhead.com/quest=13849#comments:id=1435226",
        },
        {
            id = 1382432,
            score = 8,
            author = "810690",
            text = "Easy quest. You left click at the bucket, point it out in the fire and when you see the green circle, you'll right click, so your character will throw the bucket to extinguish the fire. You can only do the roofs and you don't have to be really near/close to it. It gives really good XP.",
            date = "2011-04-02T12:48:38-05:00",
            sourceUrl = "https://www.wowhead.com/quest=13849#comments:id=1382432",
        },
        {
            id = 1237070,
            score = 5,
            author = "734648",
            text = "Its not a bad quest.. quite easy for the xp.. go for the roofs though.. doesnt seem to work on trees, poles or grass..",
            date = "2010-12-16T00:09:29-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13849#comments:id=1237070",
        },
        {
            id = 1515598,
            score = 5,
            author = "Liri",
            text = "If your having trouble go to your game menu / options.  Turn particle density all the way up, even if you have to turn the rest down temporarily.  It makes the fires MUCH easier to see so you can identify the base and only have to make one throw.",
            date = "2011-09-11T14:54:35-05:00",
            sourceUrl = "https://www.wowhead.com/quest=13849#comments:id=1515598",
        },
    },
    [13850] = {
        {
            id = 761912,
            score = 196,
            author = "303838",
            text = "It seems that you only get splashed if you are HITTING the revasaurs. Best thing to do is to unequip your weapon and beat on em with your fists while AFK",
            date = "2009-06-29T00:58:45-05:00",
            sourceUrl = "https://www.wowhead.com/quest=13850#comments:id=761912",
        },
        {
            id = 849421,
            score = 97,
            author = "242379",
            text = "If you're like me and you're lvl 80, you might have a problem with, \"Oh CRAP, i keep killing them in 3 or 4 hits even when i'm unarmed!\" I found the best thing to do if you're lvl 80 (or in the 70s) is to take off all your gear and the attack the mobs, you shouldn't do very much damage and you should be able to get the 20 splashes really quickly. If that doesn't work, you can also try letting them kill you and getting res sickness.",
            date = "2009-09-23T15:34:01-05:00",
            sourceUrl = "https://www.wowhead.com/quest=13850#comments:id=849421",
        },
        {
            id = 2320966,
            score = 89,
            author = "1399908",
            text = "To all the other level 100's and future 110's...\n\nGet the Goblin Dragon Gun, Mark II from the AH (generally about 500g), and use that as this has worked for me as of 6.2.4.\n\nTip: Since it does damage in a cone, it will be better if you can group multiple venomhides near each other to maximise your potential for getting the credit. Hope this helps! :)",
            date = "2016-04-09T13:09:59-05:00",
            sourceUrl = "https://www.wowhead.com/quest=13850#comments:id=2320966",
        },
        {
            id = 669229,
            score = 67,
            author = "135079",
            text = "\"This\" - the whole ravasaur mystery - was THE hot-topic back in Vanilla-WoW for a long period. I'm suprised how many people have simply lost any recollection of the huge petition threads, or the few hilarious \"theory-threads\" that spawned left and right caused lack of official responses :)\n\nThere where two NPC's; Arin'Sor and Mor'Vek who resided within Un'Goro that were part of the horde-aligned faction\nAs of Patch 2.0, they went missing without a trace\nSomewhere inbetween the thousands of threads dedicated to these trainers, I believe blizzard admitted its original intent.\n\nThe most plausible rumour was that blizzard \"disabled\" the quests in fear of Un'Goro being flooded end-game players while it was considered a leveling-zone. Alliance farms for 'their' special mount in Winterspring, which was an end-game zone anyway.\n\nWhat I remembered/could dig up from archives :)",
            date = "2009-04-07T21:06:34-05:00",
            sourceUrl = "https://www.wowhead.com/quest=13850#comments:id=669229",
        },
        {
            id = 5356216,
            score = 64,
            author = "Polesz",
            text = "Hi!\nThis quest is not a condition for Un'Goro Crater Quests (https://www.wowhead.com/achievement=4939/ungoro-crater-quests) and Loremaster of Kalimdor (https://www.wowhead.com/achievement=1678/loremaster-of-kalimdor).",
            date = "2022-04-16T09:02:36-05:00",
            sourceUrl = "https://www.wowhead.com/quest=13850#comments:id=5356216",
        },
    },
