    [13882] = {
        {
            id = 1138169,
            score = 78,
            author = "286346",
            text = "The seed of earth is easy enough, you get it by talking to Onu, the ent, in the camp where you got the quest.\nFor the seed of the sky, you have to 'catch' one of the small wisps flying around the forest nearby. They can be quite hard to get, but once one of them flies low to the ground, loot it\nFor the seed of the sea, you obviously have to go down to the sea, and dive in. It can be picked up from one of the seashells in the sand (a crawler-thing will emerge as well, and you will have to kill it)",
            date = "2010-10-09T04:51:42-05:00",
            sourceUrl = "https://www.wowhead.com/quest=13882#comments:id=1138169",
        },
        {
            id = 1641085,
            score = 12,
            author = "stenova",
            text = "I highly recommend finding a wisp circling a tree, so if you miss it, it will be right back. Not entirely sure about the coords, but I believe it was west of the lake, got it pretty fast and easy. I also recommend disabling click-to-move if it's on.",
            date = "2012-03-18T12:53:20-05:00",
            sourceUrl = "https://www.wowhead.com/quest=13882#comments:id=1641085",
