    [13903] = {
        {
            id = 2545471,
            score = 23,
            author = "ClickNut",
            text = "You farm them in The Slithering Scar (//http://www.wowhead.com/zone=540/the-slithering-scar), south in Un'Goro Crater (http://www.wowhead.com/ungoro-craterUn). They drop both inside and outside og the cave from Gorishi Stinger (//http://www.wowhead.com/npc=6554/gorishi-stinger), Gorishi Worker (http://www.wowhead.com/npc=6552/gorishi-worker), and Gorishi Tunneler (http://www.wowhead.com/npc=6555/gorishi-tunneler).",
            date = "2018-01-14T02:38:56-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13903#comments:id=2545471",
        },
        {
            id = 1024196,
            score = 9,
            author = "456634",
            text = "Not sure why there are 2 Horde listings for this Quest, but THIS is the one that shows up in Lightheaded, so here is where I'm posting. The insects needed for the Quest are specifically Insects with \"Gorishi\" in their name somewhere, and, far as I can tell, only in the Slithering Scar (Quest Text!). Tried some insects in Tanaris and no drops. Went to the scar, and other than some annoying mobs that dropped nothing (I'm 80, so a little overpowered for the Quest) I got a meat from everything I killed (Gorishi Worker, Gorishi Mailbox Repairman... ok... not that last one... etc.). Took a few minutes to complete.",
            date = "2010-04-22T06:37:08-05:00",
            sourceUrl = "https://www.wowhead.com/quest=13903#comments:id=1024196",
        },
        {
            id = 829821,
            score = 7,
            author = "Spac3Rat",
            text = "You'll have to do this quest 20 times to get the 20 Venomhide Baby Tooth (http://www.wowhead.com/?item=47196) for the quest They Grow Up So Fast (http://www.wowhead.com/?quest=13906), which will allow you to ride your new mount with Whistle of the Venomhide Ravasaur (http://www.wowhead.com/?item=46102).\n\nThis all starts at Mor'vek (http://www.wowhead.com/?npc=11701) when he gives you the quest Toxic Tolerance (http://www.wowhead.com/?quest=13850).\n\nThe full chain quest is:\n- Toxic Tolerance (http://www.wowhead.com/?quest=13850)\n- Venomhide Eggs (http://www.wowhead.com/?quest=13887)\n\nThen the following quests for 20 days (it's a random quest each day)\n\n- Hungry, Hungry Hatchling (http://www.wowhead.com/?quest=13915)\n- Gorishi Grub (http://www.wowhead.com/?quest=13903)\n- Poached, Scrambled, Or Raw? (http://www.wowhead.com/?quest=13904)\n- Searing Roc Feathers (http://www.wowhead.com/?quest=13905)\n\nAnd finally you will finish They Grow Up So Fast (http://www.wowhead.com/?quest=13906) and get your new raptor mount.",
            date = "2009-09-02T08:49:33-05:00",
            sourceUrl = "https://www.wowhead.com/quest=13903#comments:id=829821",
        },
        {
            id = 6184963,
            score = 5,
            author = "callusmarty",
            text = "/way 50.11 80.50\n\nthere's a cave with bugs needed",
            date = "2025-09-17T15:45:35-05:00",
            sourceUrl = "https://www.wowhead.com/quest=13903#comments:id=6184963",
        },
        {
