    [13911] = {
        {
            id = 1564650,
            score = 49,
            author = "326762",
            text = "Instead of saving the world from the evil Twilight forces or Wildlife, we now take an alzheimer-patient for a walk.\n\nNice idea for a quest though :D",
            date = "2011-11-06T11:20:13-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13911#comments:id=1564650",
        },
        {
            id = 1292087,
            score = 34,
            author = "Soldier45",
            text = "This quest is so stupid it made me laugh. However I did get upset when I realized we were just going in a circle.",
            date = "2011-01-13T12:39:28-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13911#comments:id=1292087",
        },
        {
            id = 1179762,
            score = 25,
            author = "Katarinea",
            text = "A very simple, humorous quest. The prospector walks around the perimeter of the dig site and makes a few funny comments before returning to the camp you started from.\n\nThe only mobs that are fought are the murloc lining the wreckage of the dig.\n\nHowever, I failed this quest once -- when walking around, near the Master's Glaive, he aggroed a \"Spawn of Soggoth\" and it was not visible to me. I was certain it was a phasing error, and it was -- later on there is a phased quest in the Master's Glaive. If he aggros this, just run forward into the Master's Glaive, and hopefully it will be visible. It didn't happen the second time, so it may or may not be rare.\n\nThis quest would not be hard for someone at level.",
            date = "2010-11-24T00:37:08-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13911#comments:id=1179762",
        },
        {
            id = 1180141,
            score = 6,
            author = "Diwtay",
            text = "I had the same error when he suddenly aggroed something I could not see. He stood there swinging away at nothing until he died. >_< Had to drop the quest and pick it up again.",
            date = "2010-11-24T03:38:09-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13911#comments:id=1180141",
        },
        {
            id = 1318496,
            score = 4,
            author = "624617",
            text = "To avoid the confusion of invisible mobs, make sure you are on the quest The Battle for Darkshore (http://www.wowhead.com/quest=13897) (allowing you to see the Spawns of Soggoth) before starting this escort quest.",
            date = "2011-02-01T17:54:10-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13911#comments:id=1318496",
        },
    },
