            author = "Fyonella",
            text = "I'm sure all this 'reference' stuff is useful to some, but what might be more useful is information relevant to the quest itself.\n\nThe two gnomes and the guy you have to kill (Thundrak) are on the wagon that is being towed through the camp by a Kodo. Target Thundrak and he'll leap off the wagon allowing you to kill him. The gnomes are automatically freed as he dies.",
            date = "2010-12-05T18:37:53-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13913#comments:id=1208879",
