        },
        {
            id = 1191160,
            score = 6,
            author = "splunk",
            text = "Standing at the entrance to the cave for this quest and Twisted Hatred (http://www.wowhead.com/quest=932) at 54.5, 46.2, just above Dolanaar, for 4.0.3.",
            date = "2010-11-27T17:52:07-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13946#comments:id=1191160",
        },
        {
            id = 1374966,
            score = 6,
            author = "803789",
            text = "Bah...the quest language should be more specific.  I could have done this while in the cave.  But I suppose sending me to the quest giver who asks for the boss's head should have been a tip off.\n\nFYI: you can use the pods after you kill 12 of the things, so you can use it to get in and out of the cave without fighting the sprites for the most part if you want to.  I cleared the cave, save for respawn, on the way in and out the FIRST time when I went after the boss.  The second time in, I just used the pods.  The sprites mostly just drop copper and eyes....um...gross.",
            date = "2011-03-24T11:50:18-05:00",
            sourceUrl = "https://www.wowhead.com/quest=13946#comments:id=1374966",
        },
    },
    [13947] = {
        {
            id = 1076928,
            score = 195,
            author = "447186",
            text = "Go see Thraka the Windrider Master inside the camp at 38,42. Tell her that you have been ordered to bomb Astranaar and she will give you a windrider to attack with. You will see the familiar vehicle controls come up and key 1 is for your bombs. Key 3 turns your mount around and heads back to camp. You will fly back and forth across Astranaar until you have managed to destroy enough vehicles and people. Easy quest and back to Captain Goggath to hand it in.\n\nLance\nBeta tester for;\nWrath of the Litch King\nCataclysm",
            date = "2010-07-09T18:49:50-05:00",
            sourceUrl = "https://www.wowhead.com/quest=13947#comments:id=1076928",
        },
        {
            id = 2867509,
            score = 57,
            author = "amymicaela",
            text = "Talk to wind rider master \"Thraka\" to begin quest, don't run to quest area.",
            date = "2019-01-22T14:11:02-06:00",
