    [13948] = {
        {
            id = 1181360,
            score = 51,
            author = "Squiji",
            text = "If you move to the high land above the excavation, you will come to a place where you will be facing the long snakelike structure coming down from the top of the thing they are working on.  Move then to your right and you will see a ramp going up into the works; it appears to be made of metal plates and it twists up over open air.  Follow that ramp up to a platform above; you will see several of the cultists grouped there.  Pause to listen to their conversation and you will complete the quest.  Beware of roaming Faceless Ones, they can detect stealth.",
            date = "2010-11-24T11:46:44-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13948#comments:id=1181360",
        },
        {
            id = 2397485,
            score = 23,
            author = "IBPwNin",
            text = "I completed the prequel quest and a quest window popped up to begin this one but I accidentally closed the window before accepting it and it wasn't added to my log like usual.\n\nAll you need to do is go back to Balren of the Claw (http://www.wowhead.com/npc=34402/balren-of-the-claw) to get another chance at beginning this quest.\n\nstupid GUI window limits - forcing one closed to open another.",
            date = "2016-09-11T11:55:04-05:00",
