        },
        {
            id = 5373008,
            score = 21,
            author = "Sylicaa",
            text = "Need to stand where the platform connects to the ramp in order to trigger this quest! I stood right next to them for so long and it didn't trigger till I started walking away and hit that spot",
            date = "2022-05-12T14:08:36-05:00",
            sourceUrl = "https://www.wowhead.com/quest=13948#comments:id=5373008",
