    [13958] = {
        {
            id = 1969770,
            score = 2,
            author = "1077781",
            text = "FYI- dont try to run up the front ramp! Ally guards are pvpd. If you are looking at the ramp, take the path to the left and go up behind raynewood. Thagg is up behind the tower.",
            date = "2014-06-02T21:45:09-05:00",
            sourceUrl = "https://www.wowhead.com/quest=13958#comments:id=1969770",
        },
        {
            id = 2471175,
            score = 1,
            author = "swedengamer",
            text = "Did this quest as of patch 7.1.5. Keep an eye out for Shadumbra, a cat that prowls the area. This cat drops a quest with some nixe xp rewards.\n\nThis cat is one of several creatuers in Ashenvale that drops an item that leads to a quest. It used to be part of the old classic quest, The Ashenvale Hunt, but no more. Also there was an NPC that offered tips on where to locate these beasts, but no more. The NPC still exist, Senani Thunderheart, a female tauren, but she doesn't offer any tips anymore. She has also been moved from Splintertree Post to Silverwind Refuge during the remake of this zone for Cataclysm. But you can still do these quests, but not the followup that existed once you did all of these back in the days.\n\nThe other creatures that drop are as following:\n\nUrsangous - you will most likely run into this bear during the two quests They're Out there! and Building Your Own Coffin.\n\nTideress - part of the quest Simmer Down Now.\n\nSharptalon - a bird that you will most likely run into during the quest Rotting Slimes during the beginning quests of this zone.",
            date = "2017-02-10T04:44:34-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13958#comments:id=2471175",
        },
    },
    [13961] = {
        {
            id = 1187289,
            score = 127,
            author = "181947",
            text = "If anyone forgets where Togrik is located after you have captured your quillboar...\n\nTogrik is at the building on the far right, standing by the wagon.",
            date = "2010-11-26T09:50:23-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13961#comments:id=1187289",
        },
        {
            id = 1205612,
            score = 59,
            author = "717966",
            text = "So just to make it clear, you need to throw the net and then speak to the Quilboar who should now have turned green/passive. When you speak to him, you will see an option come up to pounce him.\n\nAfter pouncing, you can drag him back to the quest giver.\n\nI hope this helps.\n\nCheers,\n\nChee",
            date = "2010-12-04T06:53:03-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13961#comments:id=1205612",
        },
        {
            id = 1283439,
            score = 23,
            author = "faia",
            text = "wish this was able to become a vanity pet....",
            date = "2011-01-08T04:43:46-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13961#comments:id=1283439",
        },
        {
            id = 1267980,
            score = 17,
            author = "RaQin",
            text = "I absolutely love the fact that you can MOUNT, DISMOUNT, run around, grab other quests, engage in battle, eat... etc and this thing will stay attached to you as you run amuck through the Northern Barrens.  I try to grab this quest BEFORE grabbing any others just so I can drag this thing around.\n\nIt does seem to have a time-limit on it though.  If I had to guess I'd estimate the ability to drag it around for something like 15-20 minutes before it disappears.  And I'd gather that you can't drag it out of the Northern Barrens either.  But then you just go grab another one if you're in the mood.\n\nI love this quest.",
            date = "2010-12-30T12:54:01-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13961#comments:id=1267980",
        },
        {
            id = 1340301,
            score = 16,
            author = "satarell",
            text = "So far have walked my unwilling quilboar to ratchet he seems uninterested in the places i take him  ; >",
            date = "2011-02-17T21:45:03-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13961#comments:id=1340301",
        },
    },
