    [13967] = {
        {
            id = 1188759,
            score = 20,
            author = "643457",
            text = "Apparently furbolgs only have one ear.",
            date = "2010-11-26T20:17:00-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13967#comments:id=1188759",
        },
        {
            id = 1268348,
            score = 17,
            author = "corvis9",
            text = "The respawn rate on the furblogs is way too low given how few there are. 15min of waiting, still no love.\n\nThe foulweald corpses just north of silverwind are scenery masquerading as mobs, they will never respawn. Head east of them for the actual mobs. The in game quest helper is a little inaccurate in its placing of the blue area markers sometimes.",
            date = "2010-12-30T17:11:05-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13967#comments:id=1268348",
        },
        {
            id = 1259662,
            score = 5,
            author = "540613",
            text = "Frustrating quest to say the least.\n\n- The 'rare' spawn, Oakpaw, does not drop ears.\n\n- There is a 100% droprate of only 1 ear per mob.\n\n- You can't have more than 10 ears so you will need 2 bagspace for this quest.",
            date = "2010-12-26T08:46:16-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13967#comments:id=1259662",
        },
        {
            id = 1181347,
            score = 4,
            author = "236466",
            text = "The ears seem to be a 100% drop rate from the Foulweald furbolgs, levels 23-25 or so, immediately to the east, and slightly north, from where you pick up the quest.\n\nThe furbolgs put a debuff on you decreasing either strength or agility for three seconds, nothing to worry about really but thought I'd mention it anyway.",
            date = "2010-11-24T11:42:38-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13967#comments:id=1181347",
        },
        {
            id = 1468117,
            score = 4,
            author = "854558",
            text = "This quest was especially annoying to me on my rogue, killing and looting 15 furbolgs? alright, no problem. Except going near them applies a debuff that removes you from stealth, it's not game-breaking, but it's sort of annoying to have to wait for it to wear off and restealth after trying to sap or pickpocket each mob.",
            date = "2011-07-12T14:24:12-05:00",
            sourceUrl = "https://www.wowhead.com/quest=13967#comments:id=1468117",
        },
    },
    [13968] = {
        {
            id = 1185643,
            score = 4,
            author = "671553",
            text = "Pretty easy to kill, just knock him off of his mount, and you'll be fine.\n\nThing is, he has a skill called \"Quillboar Rush\" which knocks you back. Just kite him around, clearing the area first, and he'll be an easy solo.\n\nHope this helps.\n\nP.S. - Rooting abilities make this extremely easy for any casters.",
            date = "2010-11-25T18:21:30-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13968#comments:id=1185643",
        },
        {
            id = 1103307,
