    [13992] = {
        {
            id = 1074971,
            score = 4,
            author = "447186",
            text = "A new quest added in Cataclysm. Nothing special, just kill the Kolkar that can be found in abundance all around The Forgotten Pools.\n\nThe quest giver is a troll called Ta'Jarl and he is located next to The Forgotten Pools at 37,45.\n\nLance\nBeta tester for;\nWrath of the Litch King\nCataclysm",
            date = "2010-07-07T02:23:40-05:00",
