        },
    },
    [13995] = {
        {
            id = 1208207,
            score = 24,
            author = "476825",
            text = "This quest is glitched.\n\nYou have to make sure that some of the Centaurs that show up are still alive when Kurak shows up. If you don't he will evade and vanish. I had to abandon and restart the quest 3 times because I tried to ranged attack him before he engaged in combat with the NPC and then I tried to run up and melee him. He vanished each time. He cannot be alone when he comes onto the mountain.",
            date = "2010-12-05T12:45:09-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13995#comments:id=1208207",
        },
        {
            id = 1074993,
            score = 6,
            author = "447186",
            text = "The quest giver is Gorgal Angerscar and he is located next to The Stagnant Oasis. When you accept the quest he will lead you up the little mountain next to the pool and drop a Horde Banner at 54,78. You will then get a three waves of Kolkar that will attack you both. These are easy to deal with before Kurak shows up. He is easy to deal with also.\n\nAt completion go back down the mountain and had it in to the other guy, a troll called Shoe.\n\nLance\nBeta tester for;\nWrath of the Litch King\nCataclysm",
            date = "2010-07-07T03:04:41-05:00",
            sourceUrl = "https://www.wowhead.com/quest=13995#comments:id=1074993",
        },
        {
            id = 1226070,
            score = 4,
            author = "728676",
            text = "I did this quest more times then I'd like to think. It's glitched but not in a consistent way. The Kolkar who run up and attack before Kurak shows up would randomly disappear; only one or two would appear then nothing else would happen; Kurak would appear then disappear around a 100 hp from death. Random crazy things like that. Finally, after saying it would be my last try, Kurak just appeared and I was able to finish the quest.\n\nIf you're going to attempt this one, I have a couple of pieces of advice. Firstly, follow LunarMyst's advice, put the NPC as your focus and be prepared to drop everything and use a bandage on him because he will randomly loose health even if you have full aggro from all the Kolkar attacking. Beware the Kolkar Storm guy, he has a tendency of really killing that NPC easily. Oh and have a ton of patience.\n\n-Rowen",
            date = "2010-12-11T23:03:47-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13995#comments:id=1226070",
        },
        {
            id = 1307888,
            score = 3,
            author = "512409",
            text = "Kurak did not arrive once, killed me once and disappeared before he could be killed twice.\n\nReported the problem and will try again after Tuesday.",
            date = "2011-01-24T11:36:09-06:00",
            sourceUrl = "https://www.wowhead.com/quest=13995#comments:id=1307888",
        },
        {
            id = 1511006,
            score = 3,
            author = "878161",
            text = "Easy one try.\nKeep healing Gorgal until Kurak arrives, hit him once or twice and then go back to healing Kurak.",
            date = "2011-09-05T18:46:24-05:00",
            sourceUrl = "https://www.wowhead.com/quest=13995#comments:id=1511006",
        },
    },
