    [14005] = {
        {
            id = 1180329,
            score = 12,
            author = "Breakability",
            text = "This is definitely an improvement on the original quest. Very fun to run around and Starfall everything to death :D",
            date = "2010-11-24T05:15:54-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14005#comments:id=1180329",
        },
        {
            id = 1184488,
            score = 10,
            author = "477031",
            text = "super easy quest.\n\nhead to 40,69 (sw corner)\n\nignore everything, make your way to that coordinate, then use your starfall (#3) when you are right on top of the big tree looking NPC named bough of corruption. It'll destroy anything you dragged along, including him (if he doesn't die right click him to manually hit him for whatever amount of HP you have left).\n\nif you get low on HP, hit moonlight (#1) and put it on the ground right where you stand and stand in it till it heals you.",
            date = "2010-11-25T10:18:33-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14005#comments:id=1184488",
        },
        {
            id = 1272009,
            score = 9,
            author = "jennybrett39",
            text = "I had to disable my addons to see the in-game action bar.",
            date = "2011-01-01T20:23:16-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14005#comments:id=1272009",
        },
        {
            id = 1225516,
            score = 8,
            author = "585305",
            text = "I would just like to note how amusing it is to have 20% of your HP healed every .5 seconds while in the Moonlight ability's radius, and a 20% damage buff to boot.\n\nI think the Goddess should be present for the Deathwing encounter, if that's the kinda stuff she can pull out.\n\nAlso, given the anim for it, I really wish the Starfall one wouldn't dismount you. It's a perfect PotM replica.\n\nAnyway, basking in epic abilities aside, this quest is fun at-level or not. I have yet to turn it in on my main simply to come back now and then. Just run through them and pop Moonlight whenever you get a few too many agro'd. You can pretty much let that burn them out, or Starfall to make it go faster. Get to the corrupted ancient, use the mass deathgrip, Moonlight+Starfall, home before dinner.\n\nThis quest was more for the sheer BAMF factor than to actually challenge. Enjoy it.",
            date = "2010-12-11T18:07:10-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14005#comments:id=1225516",
        },
        {
            id = 1180294,
            score = 7,
            author = "DELsh1van",
            text = "Can't say it was all that amazing as a level 80 hunter, but pretty epic quest at the appropriate level I reckon!",
            date = "2010-11-24T04:58:37-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14005#comments:id=1180294",
        },
    },
    [14006] = {
        {
            id = 1181697,
