        {
            id = 1185224,
            score = 26,
            author = "639420",
            text = "After you turn in the quest a little dialogue starts up.\n\nSputtervalve says: Let's get this samophlange operational!\nSputtervalve says: All I have to do is resequence the oscilating coolant pressure valves...\nBrak Blusterpipe says: It's beautiful! ...have we figured out what it does yet?\nSputtervalve says: No idea. But it's doing it perfectly!\nNozzlepot says: Is that a working samophlange? Throttle it up! MAX POWER!\n(the samophlange explodes)\nNozzlepot says: Sputtervalve, you're a genius! I'll take 30.\nSputtervalve says: Right away, Noz.\n\nGotta love Goblins. ;D",
            date = "2010-11-25T15:25:06-06:00",
