    [14034] = {
        {
            id = 1075326,
            score = 18,
            author = "447186",
            text = "Chief Engineer Foote is sitting down at a table in the Broken Keel Tavern. Co-ords are 66,74. Clicking on the character will allow you to interact with the character. You are given an option to club the guy unconscious. Doing so starts a bar fight as the alliance soldiers in the bar come to his aid. However, other Horde NPC's will come to your aid and fight the Alliance NPC's for you.  Click on the now unconscious engineer and rifle through his pockets for the schematics.\n\nLance\nBeta tester for;\nWrath of the Litch King\nCataclysm",
            date = "2010-07-07T13:02:38-05:00",
            sourceUrl = "https://www.wowhead.com/quest=14034#comments:id=1075326",
        },
        {
            id = 1213911,
            score = 4,
            author = "75738",
            text = "Anyone else feel kinda bad about doing this quest?\n\nDude was just enjoying a quiet drink (or seven), and he even waves at you.",
            date = "2010-12-08T04:36:30-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14034#comments:id=1213911",
        },
        {
            id = 1473099,
            score = 3,
            author = "FuryWar",
            text = "This is a great quest that has a classic event that you'd see in an old Western like one of the \"Trinity\" movies!  :-)  It's classic:  Orc wants schematics from drunk guy at bar so he walks up to him, gets smiled at, he hates Humans, so he clubs drunk guy upside the head!",
            date = "2011-07-18T06:27:54-05:00",
            sourceUrl = "https://www.wowhead.com/quest=14034#comments:id=1473099",
        },
        {
            id = 1185740,
            score = 1,
            author = "530770",
            text = "No reputation gain with Ratchet,etc. with this quest",
            date = "2010-11-25T19:15:08-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14034#comments:id=1185740",
        },
        {
            id = 1205173,
            score = 1,
            author = "136377",
            text = "Cords 67.0 74.7",
            date = "2010-12-03T23:48:38-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14034#comments:id=1205173",
        },
    },
    [14038] = {
        {
            id = 1075427,
            score = 157,
            author = "447186",
            text = "Go over to the ship at 72,85. If you swim it is quicker but you will encounter a couple of makrura along the way. Go to the back of the ship near the paddlewheel. You will see a fairly large wooden section underwater. If you run your cursor over it the tooltip will indicate it to be the thinnest part of the ship.\n\nClick on the Limpet mine in your inventory and your done. After your done Gazlowe can give you your next quest immediately.\n\nLance\nBeta tester for;\nWrath of the Litch King\nCataclysm",
            date = "2010-07-07T15:50:41-05:00",
            sourceUrl = "https://www.wowhead.com/quest=14038#comments:id=1075427",
        },
        {
            id = 1182752,
            score = 74,
            author = "Amberlee",
            text = "For those unfamiliar with ship configuration (like myself), don't bother going onto the top of the ship itself via the dock - nothing is there!  You can find the thinnest part of the hull by physically swimming underneath the ship!",
            date = "2010-11-24T19:32:52-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14038#comments:id=1182752",
        },
        {
            id = 1592998,
            score = 24,
            author = "Luhka",
            text = "For definitions sake, a limpet mine is a type of naval mine attached to a target by magnets; they are so named because of their superficial similarity to the limpet, a type of mollusk.",
            date = "2011-12-09T03:21:14-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14038#comments:id=1592998",
        },
        {
            id = 1375212,
            score = 18,
            author = "Daedelus",
            text = "Ironically, the \"thinnest part of the hull\" actually looks like the thickest part of the hull.",
            date = "2011-03-24T18:49:56-05:00",
            sourceUrl = "https://www.wowhead.com/quest=14038#comments:id=1375212",
        },
        {
            id = 1255503,
            score = 11,
            author = "460450",
            text = "I was given this quest twice. I initially completed the quest, and the follow up quest, Ammo Kerblammo (http://www.wowhead.com/quest=14042). I also go the achievement Northern Barrens Quests (http://www.wowhead.com/achievement=4933/northern-barrens-quests). Then, I came back at level 47 while working on Well Read (http://www.wowhead.com/achievement=1244) and I noticed the ! above the quest giver's head. I took the quest, thinking it might be a different boat I have to blow up. I blew up the same boat, completed the quest.\n\nThen I saw another ! on the map, by Barron Longshore. I got the quest to free him from his shackles again, The Baron's Demands (http://www.wowhead.com/quest=14046). I did not pay attention to see if these 2 quest repeats counted twice towards my total quests done.\n\nEdit: I also got to repeat the quests Investigate the Wreckeage (http://www.wowhead.com/quest=14066) and To Track a Thief (http://www.wowhead.com/quest=869). This time I did pay attention to my total quest count, and it increased by two!\n\nEdit: I also noticed all these duplicate quests are marked as \"weekly\" on wowhead. If they are weekly, I'm wondering what their purpose is, and why they count towards the total quests done.",
            date = "2010-12-23T19:59:48-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14038#comments:id=1255503",
        },
    },
    [14039] = {
        {
            id = 1399620,
            score = 14,
            author = "820377",
            text = "This drove me nuts until I wandered around inside the Temple of the Moon. I had to deliver a filled vial to Tyrande Whisperwind. The problem was, when I followed my map inside the Temple of the Moon, I couldn't find her. I went directly to the spot where the ? ended. Where I was standing is where she should have been standing, according to my map. It was really frustrating.\n\nI asked other players who came into the temple. Unfortunately most of them ignored me. Guess they forgot what it's like being new.\n\nBUT one player did answer. He didn't know but I was grateful that he or she didn't just ignore me.\n\nI did find her. For anyone else who needs to hand Tyrande Whisperwind the vial to finish the quest.. wander around the inside of the temple of the moon, near the wall until you find a ramp. Go up the ramp and you will eventually see her with the ? above her head.\n\nAnd to those who ignored me when I asked for help, and who ignore's everyone who asks for help in the game.. I HOPE WHEN YOU NEED HELP THAT THE PERSON YOU ASK FOR HELP WILL NOT DO WHAT YOU DO TO THOSE WHO ASKED YOU! IE: I HOPE THEY HELP YOU. Believe me, even a 'No, sorry, don't know' would be appreciated!",
            date = "2011-04-25T23:08:06-05:00",
            sourceUrl = "https://www.wowhead.com/quest=14039#comments:id=1399620",
        },
        {
            id = 1422300,
            score = 1,
            author = "Kishka",
            text = "Thank you, Nightborn. I wandered around forever trying to find her. The ramp led me to the quest end. Yes, I do try to respond to those asking, even if it's a simple, \"sorry, no clue here.\" Thank you so much for taking the time to respond. Best wishes.",
            date = "2011-05-19T05:34:10-05:00",
            sourceUrl = "https://www.wowhead.com/quest=14039#comments:id=1422300",
        },
        {
            id = 1843242,
            score = 1,
            author = "1067608",
            text = "Thanks SOOO much!  I was having the hardest time with this quest!  You're the best!  :)",
            date = "2013-04-14T22:46:16-05:00",
            sourceUrl = "https://www.wowhead.com/quest=14039#comments:id=1843242",
        },
        {
            id = 1486320,
            score = 0,
            author = "AMAVERICK",
            text = "I agree that players should return requests for help even if it is just to acknowledge the request and you can not help; however some of us are a little older and just might not be paying attention to the little box in the lower left corner so did not see the request.\n I know I fall into that group and I do a lot of solo playing and get focused on the middle of the screen and don't see bunches of requests - My appologies if I missed replying to anyone.",
            date = "2011-08-03T11:01:26-05:00",
            sourceUrl = "https://www.wowhead.com/quest=14039#comments:id=1486320",
        },
        {
            id = 2018450,
            score = 0,
            author = "JezebelJay",
            text = "NightBorn, thank you SO much for that. I was in exactly the same situation. Your help was invaluable.",
            date = "2014-10-24T14:04:33-05:00",
            sourceUrl = "https://www.wowhead.com/quest=14039#comments:id=2018450",
        },
    },
    [14042] = {
        {
            id = 1075429,
            score = 12,
            author = "447186",
            text = "The ammo carts are located near the shore and three are not far from the ship of the previous quest. They respawn fairly fast so those three should do you. They are located near trees and in the small camps. They are all guarded so a little combat is to be expected.\n\nLance\nBeta tester for;\nWrath of the Litch King\nCataclysm",
            date = "2010-07-07T15:55:16-05:00",
            sourceUrl = "https://www.wowhead.com/quest=14042#comments:id=1075429",
        },
        {
            id = 1185753,
            score = 4,
            author = "530770",
            text = "There is no reputation gain with Ratchet, etc for completion",
            date = "2010-11-25T19:20:49-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14042#comments:id=1185753",
        },
        {
            id = 1368748,
            score = 2,
            author = "GriffinMaverick",
            text = "You can avoid combat fairly easily if you are a rogue or a hunter. I did this on a rogue and avoided fighting anybody.\nEdit:Corrected a spelling mistake.",
            date = "2011-03-16T20:30:49-05:00",
            sourceUrl = "https://www.wowhead.com/quest=14042#comments:id=1368748",
        },
        {
            id = 1851967,
            score = 1,
            author = "1118796",
            text = "Fairly easy for a Panda hunter!  Remember that the enemy respawns almost as quickly as the ammo dumps...watch out for that!  But you can collect five times from two dumps pretty fast.  If there is another player in the area, help each other a bit with the enemy.  Keep them down, and work the dumps!  :)",
            date = "2013-05-10T21:37:19-05:00",
            sourceUrl = "https://www.wowhead.com/quest=14042#comments:id=1851967",
        },
        {
            id = 3127265,
            score = 1,
            author = "colinstu",
            text = "Strangely you can destroy these while mounted",
            date = "2019-06-18T00:03:53-05:00",
            sourceUrl = "https://www.wowhead.com/quest=14042#comments:id=3127265",
        },
    },
    [14045] = {
        {
            id = 1358744,
            score = 19,
            author = "Korwynd",
            text = "Notice the two pirates in the nearby cage offering a bone to the dog?  This looks like a scene from \"Pirates of the Caribbean, Curse of the Black Pearl\".  A couple of locked up pirates tired to bride a dog who had the jailers key into approaching them so they could get the key.",
