            author = "Kabookiejoe",
            text = "could have sworn i have his head somewhere",
            date = "2010-11-30T22:35:16-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14045#comments:id=1198957",
        },
        {
            id = 1075360,
            score = 5,
            author = "447186",
            text = "As of Cataclysm Baron Longshore has been captured by the Alliance and held in the stockade at 69,85. Likely to be executed he will bargain for your assistance. He no longer moves about between locations and now stays in the one place.\n\nLance\nBeta tester for;\nWrath of the Litch King\nCataclysm",
            date = "2010-07-07T13:45:34-05:00",
            sourceUrl = "https://www.wowhead.com/quest=14045#comments:id=1075360",
        },
        {
            id = 1299197,
            score = 5,
            author = "csdani84",
            text = "Is this still working? Or is it possibly horde only?",
            date = "2011-01-18T13:26:48-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14045#comments:id=1299197",
        },
        {
            id = 1351573,
            score = 4,
            author = "yarko",
            text = "As soon as I picked up this quest in Ratchet, it was complete. In the quest watch frame, it said \"Click to complete.\" I did. I as able to complete it and the quest The Baron's Demands was offered to me. And all without actually leaving the goblin hut where I got it.\n\nAs it turns out, I didn't accept The Baron's Demands, so I will check, to see if I can still get it from the guy when I find him. I assume I will.\n\nEDIT TO ADD: I was able to get the quest The Baron's Demands directly from Baron Longshore.",
            date = "2011-02-27T02:54:42-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14045#comments:id=1351573",
        },
    },
    [14046] = {
        {
