    [14063] = {
        {
            id = 1075408,
            score = 24,
            author = "447186",
            text = "Just go up to the Maiden's Dagger, Cap'n Garvey's old flagship and once you are on the deck use the pirate signal. Tony and his men will appear and proceed to take out all the other pirates. Just follow him and assist him if you feel like doing so.\n\nHe will make his way down to the captains quarters and engage Alicia Cuthbert. After the fight you need to follow him into the actual captains cabin to get the quest complete notice.\n\nLance\nBeta tester for;\nWrath of the Litch King\nCataclysm",
            date = "2010-07-07T15:10:59-05:00",
            sourceUrl = "https://www.wowhead.com/quest=14063#comments:id=1075408",
        },
        {
