    [14134] = {
        {
            id = 1181741,
            score = 9,
            author = "Astralen",
            text = "To avoid an error message while trying to gather Try gathering the logs from the \"side of the pile\" and it should work, or just stand on the pile itself.",
            date = "2010-11-24T13:50:35-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14134#comments:id=1181741",
        },
        {
            id = 1632086,
            score = 4,
            author = "Shikuto",
            text = "Captain's Log, Stardate 43125.8.",
            date = "2012-02-26T14:04:26-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14134#comments:id=1632086",
        },
        {
            id = 1383273,
            score = 3,
            author = "811728",
            text = "I cannot pick up any of the logs.  There is no gear that pops up over the logs. The shredder does not have any abilities besides the Leave Vehicle tab, and I have been standing on, around, and over the logs and cannot pick one up.",
            date = "2011-04-03T16:33:44-05:00",
