    [14135] = {
        {
            id = 1191593,
            score = 20,
            author = "461389",
            text = "You'll know you have the right kind of tree when you can actually target it. There are a few in the same area that look similar, but cannot be cut down. When you get to a tree, hit the \"Buzzsaw\" option, this will be number 1 on your action bar. If nothing happens, try moving around to the other side of the tree. You'll know when there are snipers in the tree when the tree starts to tilt and fall over. A total of 3 snipers will jump down and land in front of you as the tree falls (it will disappear). Start spamming your \"Fling Blade\" button, which will be number 2 on your action bars. Make sure you kill all of the Scouts in the area before you attack a tree, because you can become very easily overwhelmed, and all of the mobs on your machine will be on you once your machine dies.\n\nGood luck!\n\n-Bloodfyré of Twisting Nether",
            date = "2010-11-27T20:58:31-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14135#comments:id=1191593",
        },
        {
            id = 2855200,
            score = 19,
            author = "Drunkion",
            text = "Since Blizzard decided to level scale, this quest is quite annoying. I used to be able to complete this quest in just one shredder. Apparently now, the elves that fall out the trees that you cut down do significantly more damage to the shredder.",
            date = "2018-11-27T05:10:22-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14135#comments:id=2855200",
        },
        {
            id = 1711782,
            score = 7,
            author = "cheriea99",
            text = "Don't forget if you're using a toolbar addon like say Bartender 4 you will most likely have to disable it to complete these quests or check the box w/in the BT4 configs to permit \"Blizzard's Vehicle UI\".",
            date = "2012-09-10T07:56:25-05:00",
            sourceUrl = "https://www.wowhead.com/quest=14135#comments:id=1711782",
        },
        {
            id = 2844883,
            score = 7,
            author = "1935392",
            text = "This quest is surprisingly annoying to complete at 120. Your own damage is minor, so more often than not your shredder will be destroyed before you get a chance to progress. Found it easier to cut down a tree and manually eject from the shredder to kill the hostile NPCs myself.",
            date = "2018-11-10T17:26:52-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14135#comments:id=2844883",
        },
        {
            id = 1184987,
            score = 3,
            author = "707108",
            text = "Walk up to one of the smaller trees and use the Buzzsaw (first key on your actionbar). A few of the mobs will spawn that you need to kill. Just spawn Buzzsaw until they all die.",
            date = "2010-11-25T13:45:42-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14135#comments:id=1184987",
        },
    },
    [14146] = {
        {
            id = 1209136,
            score = 12,
            author = "anhsieh",
            text = "No need to use the Shredder to kill folks-- it's slow and unwieldy, at least for me it was. I just got out and smashed 'em with my mace.",
            date = "2010-12-05T21:10:16-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14146#comments:id=1209136",
        },
        {
            id = 1187910,
            score = 5,
            author = "248913",
            text = "Thanks for the help Cronollo and Tzieq, that was the problem.  I was using TomTom quest 2 and when I disabled it I got the button for quest turn in and was instantly able to acquire the next quest in the chain; \"Arboricide\"",
            date = "2010-11-26T14:26:33-06:00",
