    [14162] = {
        {
            id = 1842323,
            score = 2,
            author = "945326",
            text = "Once you get to this area, go ahead and stop for a second.\n\nRide the elevator up to the rocketway, talk to the guy and go for a ride to the northern terminus.  You'll get about a quarter of a level of xp just \"discovering\" things on the way.  You'll also get a new flight path once you get to the northern terminus.\n\nThen ride the rocketway back to the SOUTHERN terminus, and you'll get 10 achievement points for riding the full length.  (\"Joy Ride\")\n\nYou'll also gain another flight path at the southern end.\n\nThen ride the rocketway back to Orgrimmar Exchange (there is never a cost to ride the rocketway) and continue questing.",
            date = "2013-04-12T15:15:32-05:00",
            sourceUrl = "https://www.wowhead.com/quest=14162#comments:id=1842323",
        },
