    [14193] = {
        {
            id = 1131710,
            score = 8,
            author = "15688",
            text = "Ah, Blizzard, the big fans of pop culture (http://www.wowhead.com/npc=18756), Nintendo references (http://www.wowhead.com/item=11902) and poorly disguised *ahem* jokes. (http://www.wowhead.com/quest=13003)\n\nReferring to the quest name, they're right, of course. (http://tvtropes.org/pmwiki/pmwiki.php/Main/DistractedByTheSexy) Here's the Horde version (http://cata.wowhead.com/quest=14360), so they won't feel left out.",
            date = "2010-09-30T18:06:29-05:00",
            sourceUrl = "https://www.wowhead.com/quest=14193#comments:id=1131710",
        },
        {
            id = 1227568,
            score = 7,
            author = "729438",
            text = "1. loot the melons under the trees in Sargeron, you will need 8 of them.\n2. head to Cup of Elune at 77,18.  Will need to go up a lil ramp.\n3. combine melons in cup.",
            date = "2010-12-12T12:46:16-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14193#comments:id=1227568",
        },
        {
            id = 1202895,
            score = 6,
            author = "40966",
            text = "the melons are scattered all around the area.  it would be best to get the other quests as there is overlap and you can collect all of the quest items at once.  you will be 8 collecting melons, 10 satyr flesh, and 20 satyr sabers.\n\ncollect the melons then go back to the fountain and click on the 8 melons in inventory. the other quests are similar.\n\ncheck your map cause you have to complete the quest at 69.3,29.2.  it's southwest of sargeron.",
            date = "2010-12-02T20:01:23-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14193#comments:id=1202895",
        },
