    [14194] = {
        {
            id = 1515893,
            score = 12,
            author = "InnaSkadi",
            text = "When you release them, Mountainfoot Miner says:\n\n\"Give that woman a raise!\"\n\n\"I can still clock in for the time I was petrified, right?\"\n\n\"That was surprisingly restful.\"\n\n\"I'm free!\"\n\n\"I'm outta here...\"\n\n\"I quit, I QUIT!\"\n\n\"The nightmare is over!\"\n\n\"No job is worth this!\"",
            date = "2011-09-11T21:55:10-05:00",
            sourceUrl = "https://www.wowhead.com/quest=14194#comments:id=1515893",
        },
        {
            id = 1564139,
            score = 3,
            author = "nelsoncs",
            text = "Completing this quest opens up Another Warm Body (http://www.wowhead.com/quest=14468) from Private Worcester (http://www.wowhead.com/npc=36752).",
            date = "2011-11-05T23:32:04-05:00",
            sourceUrl = "https://www.wowhead.com/quest=14194#comments:id=1564139",
        },
        {
            id = 1099921,
            score = 2,
            author = "473214",
            text = "Unfortunately, only the miners that would also qualify for \"Stone Cold\" will qualify for this quest as well. You cannot just go zap any miner. For beta purposes, I didnt drop this quest, I saw it through.. but if this were Live I would not have wasted 10-15 min wandering around waiting for the special miners to respawn. Maybe this will turn out to be part of a chain with an awesome reward (which as far as I can tell it does not).. otherwise, unless Blizz ups the amount of usable miners, I don't see many ppl completing this on Live. It's just too tedious for too little reward.",
            date = "2010-08-12T21:56:28-05:00",
            sourceUrl = "https://www.wowhead.com/quest=14194#comments:id=1099921",
        },
        {
            id = 1181907,
            score = 1,
            author = "232139",
            text = "If you're getting the error \"You need to be in Storm Cliffs\" when you attempt to use the Refleshifier, don't spend your time running around looking for a subzone called \"Storm Cliffs.\" The problem is, in fact, that the first few miners you come across as you into the mine area from the direction of Orgrimmar aren't deep enough into the strip mine to be considered in the proper area for this quest; this is probably just a tiny bug. Just go deeper into the strip mine and try some other miners; it will work just fine.",
            date = "2010-11-24T14:36:07-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14194#comments:id=1181907",
        },
        {
            id = 1185040,
            score = 1,
            author = "707108",
            text = "Just target a Mountainfoot Miner and right click the item. Return is back at the Orgrimmar Rocketway Exchange.",
            date = "2010-11-25T14:06:21-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14194#comments:id=1185040",
        },
    },
