    [14198] = {
        {
            id = 1180465,
            score = 486,
            author = "551326",
            text = "\"Nijel's Point Ruin\" is the archway in the entrance at the bottom of the hill, which you can see when you mouse over it.\n\nThe storm will carry you in circles around Nijel's Point as many times as you need. Use your Flashfire (http://www.wowhead.com/spell=67523) ability to burn down guards and merchants where they stand, or just let the storm run them over to see them get launched extremely high and catch fire in the air. Either method produces a lot of screaming, so turn up your speakers and enjoy.\n\nButton 4 will carry you back to Furien's Post when you're done.",
            date = "2010-11-24T06:20:42-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14198#comments:id=1180465",
        },
        {
            id = 1185898,
            score = 133,
            author = "Contay",
            text = "Considering that you likely had just completed the quests for Stonetalon Mountain before this quest chain and had Garrosh Hellscream drill into your head the importance of not slaughtering civilians, does anyone else find it a bit odd that the final step of this chain has you going out of your way to kill merchants?  Merchants that likely had nothing to do with shooting down a blood elf carelessly (http://www.wowhead.com/quest=14184) flying into an Alliance base's airspace?\n\nI mean, I understand the killing of the guards, but .... yeesh.\n\nGarrosh probably can't portal out to every single time someone screws up and give a \"WHAT HAVE YOU DONE\" speech, though.\n\nedit:  I'm not saying or even trying to claim that the Horde alone is guilty of killing civilians, it's just.... come on now. You just got lectured by a huge brown Orc that was >yeh< close to grabbing you by the neck and pitching you off of a cliff.  Can't you (your character) be the bigger guy, or at least demonstrate you've learned something?  (then again I really wasn't impressed by the questing in Desolace, so I go to South Barrens -- I guess that resolves that).",
            date = "2010-11-25T20:35:36-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14198#comments:id=1185898",
        },
        {
            id = 1192046,
            score = 129,
            author = "497644",
            text = "Even after five years and the introduction of the map markers, Blizzard is still pants at quest directions.\n\nThank goodness for Wowhead, eh? :P",
            date = "2010-11-28T01:18:27-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14198#comments:id=1192046",
        },
        {
            id = 1137623,
            score = 82,
            author = "415332",
            text = "There is not a place called Nijel's Point Ruin that i could find. I went to the entrance at the base of the hill before it leads you up to the main Nijel's Point area. There will be two guards standing down there. You start your vortex there. If you go up any higher, at your level the guards will nuke you.",
            date = "2010-10-08T09:35:24-05:00",
            sourceUrl = "https://www.wowhead.com/quest=14198#comments:id=1137623",
        },
        {
            id = 1463332,
            score = 82,
            author = "Tristanhawke",
            text = "I must say I agree with you.  What have you learned form Stonetalon mountain?  No, indeed the Alliance are not innocent either... but somewhere someone has to be willing to say... this madness ends with me or it just keeps perpetuating itself.\n\nI'm playing a Blood-elf Paladin, I try to play him as heroically as I can.  Yes, Elune may be the Night Elf goddess... but why would I have any particular hatred of her worshipers... or her for that matter?  Especially the spirits of her disciples who are long dead?  Those disciples did not kill Furian... I'd much rather feed the Gem the life energies of the Satyrs who are certainly in leagues with the REAL ENEMY of \"AZAROTH'S PEOPLE\"...THE BURNING LEGION!\n\nAs a paladin I think respect for people of faith even the 'enemy', and reverence for the dead should hold some importance!\n\nThe Horde/Alliance war is foolish...as it focuses attention on those who are just as interested in saving Azaroth, when we should really be fighting the BURNING LEGION and the SCOURGE!\n\nNow:  All RPing aside ... yes this quest chain seemed interesting enough to begin with but fell short of the mark.  I was hoping it would also be a morale story where you found out in the end her brother had been seeking a peaceful solution and was unfortunately felled.  I was hoping you would get the chance to show his sister that the path of vengeance was not the way that out of respect for the work her brother devoted his research and life to was not in vain.\n\nSadly I was wholly disappointed, this was nothing more than another bout of mindless destruction and dogmatic 'FOR THE HORDE' sloganry.  I guess I expected too much.\n\nFor the record.. I'm not completing this chain... and keeping the Gem, neat toy.  Its not the first quest chain I have abandoned ... I doubt it will be the last.  But I'm still level 85 with no signs of stopping...  My main character Tristanhawke has behaved honorably, and heroically, avoiding the use of torture, senseless violence or petty vengeance in all his actions... there should be a achievement other than the satisfaction in my own heart, but in the end... does any achievement other than how you feel matter anyways?",
            date = "2011-07-07T08:22:49-05:00",
            sourceUrl = "https://www.wowhead.com/quest=14198#comments:id=1463332",
        },
    },
    [14201] = {
