    [14202] = {
        {
            id = 1248891,
            score = 40,
            author = "harbor",
            text = "When you pick up the quest, use your quest item to Summon a little surveyor friend. They will follow you while mounted / flying.\n\nRun to the lake.\n\nFind a beacon looking pole thingy on the ground.\n\nWalk up to it.\n\nProtect the surveyor from a few mobs while it does it's business.\n\nIf they bug out...Right Click off they buff you have called \"Escorting a Surveyor,\" log out, and try again. It took me a few tries to get this one finished.",
            date = "2010-12-20T21:02:22-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14202#comments:id=1248891",
        },
        {
            id = 2088301,
            score = 24,
            author = "1245720",
            text = "Had some problems getting the https://www.wowhead.com/npc=35485 to interact with the Markers, however right-clicking the https://www.wowhead.com/spell=67570 debuff and resummoning them with your character standing right next to a marker did the trick.",
            date = "2015-01-14T05:58:11-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14202#comments:id=2088301",
        },
        {
            id = 1382011,
            score = 7,
            author = "Songi",
            text = "Much like the alliance quest where you turn into a furbolg using https://www.wowhead.com/item=5462 anywhere, the https://www.wowhead.com/item=48665 can summon a Goblin Surveyor Jr. Grade anytime, anyplace.\n\nIt's a lot of fun running around an instance with your very own Goblin buddy  :)\n\nTo save the beacon you can't turn in the quest and you will miss out on two other quests. Not to worry however as these quests aren't part of a chain of any importance.",
            date = "2011-04-01T22:22:35-05:00",
            sourceUrl = "https://www.wowhead.com/quest=14202#comments:id=1382011",
        },
        {
