    [14215] = {
        {
            id = 1358749,
            score = 181,
            author = "718251",
            text = "I found this one really confusing.  Thanks to all who've posted - I could never have done it without you.\nTo sum it up:\n1. The directions in the quest are a lie.  The Spirit of Kalytha is NOT located on east of the lake -  she walks around a bit  on the Northeast side, around 36,72.\n\n2. You can only talk to her if you have a buff that looks like a ring (which you got from the quest)\n\n3. The quest text lies again when it says \"Speak to the others.....\"  If, after you've talked to Kalytha,  you run around trying to speak to the ghosts,  it's possible you'll run right out of the phased area (like I did) and get killed,have to run back, and then figure out how to get the ring buff and find Kalytha again.\n\n4. After you talk to Kalytha, just head directly south along the east side of the lake.  At around 37,74 you'll see a dude standing in a shaft of light.  That's Archamage Selwyn, and he's your turn-in for this quest and gives the next step in the quest line.",
            date = "2011-03-05T23:13:58-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14215#comments:id=1358749",
        },
        {
            id = 1163356,
            score = 50,
            author = "697607",
            text = "She is found on the north side of the lake, when you have talked to her you will see why it says east.",
            date = "2010-11-06T06:34:27-05:00",
            sourceUrl = "https://www.wowhead.com/quest=14215#comments:id=1163356",
        },
        {
            id = 1189710,
            score = 17,
            author = "346",
            text = "Archamage Selwyn - East side of the lake with a light on her, 37:74",
            date = "2010-11-27T06:15:37-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14215#comments:id=1189710",
        },
        {
            id = 1183932,
            score = 15,
            author = "233652",
            text = "She is found north of the lake as mentioned before, and once you talked to her and entered her world, go back to the east part of the lake to talk with an NPC who's name I forgot. But a level 30 NPC. That's where you complete the quest.",
            date = "2010-11-25T05:21:03-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14215#comments:id=1183932",
        },
        {
            id = 1533560,
