            id = 1541531,
            score = 28,
            author = "Pahaa",
            text = "Upon completing this quest (when you locate the chest), a follow up quest [quest=14227 domain=www] appears. If you (like me) accidentally lose this quest pop-up before accepting (by opening your quest log, map, etc.), you can pick up the quest from [npc=35298 domain=www] at Furien's Post.",
            date = "2011-10-12T23:42:47-05:00",
            sourceUrl = "https://www.wowhead.com/quest=14225#comments:id=1541531",
        },
        {
            id = 1182328,
            score = 18,
            author = "262388",
            text = "You'll find it in the side building just above where you killed Kohor.  Little chest in center of the room.",
            date = "2010-11-24T16:46:30-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14225#comments:id=1182328",
        },
        {
            id = 1199002,
            score = 16,
            author = "Vexas",
            text = "7 minute and 45 second respawn time.",
            date = "2010-11-30T23:14:57-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14225#comments:id=1199002",
        },
        {
            id = 1206580,
            score = 12,
            author = "Thorzon157",
            text = "It's worth noting that I did not know it when I saw it. That's why I came here, because I had no clue WTF I was supposed to do.",
            date = "2010-12-04T17:37:49-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14225#comments:id=1206580",
        },
        {
            id = 1351456,
            score = 8,
            author = "779241",
            text = "Box spawns as 52.9, 29.0.",
            date = "2011-02-27T00:27:47-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14225#comments:id=1351456",
        },
    },
    [14226] = {
        {
            id = 1182910,
            score = 150,
            author = "277869",
            text = "For those of us who couldn't figure out how to make the pet shapeshift targets.\n\n2 button come up on top of your bars at the middle and to the right of the screen.  Middle one is to transform your target, and the on at the right will teleport you back to the quest giver.\n\nDoesn't matter who transformed the demons, whoever hits it first gets credit.",
            date = "2010-11-24T20:29:30-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14226#comments:id=1182910",
        },
        {
            id = 1205243,
            score = 66,
            author = "TwistingPlanets",
            text = "Make sure to talk again to the Image of Archmage Xylem to pick the pet up.",
            date = "2010-12-04T00:46:26-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14226#comments:id=1205243",
        },
        {
            id = 1201632,
            score = 42,
            author = "635889",
            text = "Still cannot see the buttons? Using Bartender4?\n\nYou must enable Pet Bar!\n\nYou will see Polymorph Insect (http://www.wowhead.com/spell=67794) on the left and Return to Camp (http://www.wowhead.com/spell=68945) on the right.\n\nIf you accidentally lose buttons: Abandon and take quest again.\n\nIf your Personal Arcane Assistant dies: Speak to quest giver to get a new one.",
            date = "2010-12-02T04:48:53-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14226#comments:id=1201632",
        },
        {
            id = 1188991,
            score = 27,
            author = "223290",
            text = "If you are mounted you cannot command the Assistant to transform the target. I thought the assistant was broken for almost 10 minutes because of this.",
            date = "2010-11-26T22:30:33-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14226#comments:id=1188991",
        },
        {
            id = 1318494,
            score = 26,
            author = "358663",
            text = "A perhaps important distinction, if you are lazy and don't read the quest text:\n\nYou are killing creatures that have been polymorphed into cockroach form, not, in fact, a cockroach that has been polymorphed.",
            date = "2011-02-01T17:49:24-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14226#comments:id=1318494",
        },
    },
    [14227] = {
        {
            id = 2093900,
            score = 20,
            author = "Random0532",
            text = "To complete this quest, do the following:\n\nCollect 100 https://www.wowhead.com/item=48953s from the https://www.wowhead.com/object=195535s.\nGo to the big building at 55, 26 (map (http://www.wowhead.com/maps?data=405:550266)).\nGo to the Summoning Circle in the middle of the building and click on your https://www.wowhead.com/item=48953s (https://www.wowhead.com/spell=67829).\nhttps://www.wowhead.com/npc=35647 will be summoned. Kill him.",
            date = "2015-01-24T11:20:09-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14227#comments:id=2093900",
        },
        {
            id = 2021158,
            score = 8,
            author = "1389831",
            text = "After 5 tries, i'm now sure, this quest is currently (patch 6.0.3) bugged. Nothing happens when you place the skulls.",
            date = "2014-10-30T15:33:26-05:00",
            sourceUrl = "https://www.wowhead.com/quest=14227#comments:id=2021158",
        },
        {
            id = 1300632,
            score = 7,
            author = "oedura",
            text = "Once you get all the skulls, the summoning circle is in the center of the main keep. It's not in the same building you got the ritual letter from.",
            date = "2011-01-19T14:47:29-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14227#comments:id=1300632",
        },
        {
            id = 2202922,
            score = 7,
            author = "vexis58",
            text = "I found this quest to be really disappointing. Whenever my character gets a bright idea to give herself a quest, I always expect it to backfire terribly. That goes double for a quest like this where my character goes \"oh, they're summoning a demon? The best way to solve this problem would be to summon the demon myself!\"\n\nI was expecting the demon I decided to summon to be way too strong for me, and I'd go report back to the NPCs, and they'd say \"You did WHAT?\" and then I'd have to clean up the mess I just made. Like it turned out they were waiting for reinforcements before going to stop the summoning themselves or something.\n\nThis zone is just full of my character having the worst ideas ever and then having it all work out well for me in the end.",
            date = "2015-06-28T00:54:29-05:00",
            sourceUrl = "https://www.wowhead.com/quest=14227#comments:id=2202922",
        },
        {
            id = 1188197,
            score = 6,
            author = "Zeebs",
            text = "The skulls are found inside the main base. They give random amounts, most I got from a pile was 22. So it's pretty easy.",
            date = "2010-11-26T16:19:49-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14227#comments:id=1188197",
        },
    },
    [14230] = {
        {
            id = 1184658,
            score = 42,
            author = "139938",
            text = "I found my manual on the higher platform at 55.3, 25.2",
            date = "2010-11-25T11:17:30-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14230#comments:id=1184658",
        },
        {
            id = 1076014,
            score = 35,
            author = "533061",
            text = "The manual you are looking for is green, all of the others do little goofy effects but will not give you the quest item.",
            date = "2010-07-08T11:18:46-05:00",
            sourceUrl = "https://www.wowhead.com/quest=14230#comments:id=1076014",
        },
        {
            id = 1194352,
            score = 15,
            author = "rbuffetta",
            text = "The bad books remind me of Evil Dead when Ash opened the wrong ones.",
            date = "2010-11-28T20:12:21-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14230#comments:id=1194352",
        },
        {
            id = 1179885,
            score = 14,
            author = "420211",
            text = "This is part of a quest chain in which the player aids Kalecgos (the new blue dragon aspect) in finding Azuregos and protecting him from the black dragonflight. It spans much of the land of Azshara and is composed of many quests, several of which are completely original in their concepts.\n\n1.)Azshara Blues (http://www.wowhead.com/quest=14407)\n2.)Friends Come In All Colors (http://www.wowhead.com/quest=14130)\n\nHelping out Ergll:\n3.)A Little Pick-me-up (http://www.wowhead.com/quest=14131)\n4.)Absorbent (http://www.wowhead.com/quest=14323)\n---5.)Full of Hot Water (http://www.wowhead.com/quest=14324)\n6.)That's Just Rude! (http://www.wowhead.com/quest=14132)\n\nFinding Archmage Xylem:\n7.)The Way to a Mage's Heart (http://www.wowhead.com/quest=14133)\n8.)Wash Out (http://www.wowhead.com/quest=14345)\n9.)Dressed to Impress (http://www.wowhead.com/quest=14340)\n\nHelping Xylem and his Apprentices:\n10.)Shear Will (http://www.wowhead.com/quest=14249)\n11.)Waste of Thyme (http://www.wowhead.com/quest=14263)\n12.)Renewable Resource (http://www.wowhead.com/quest=14250)\n\n13.)Manual Labor\n14.)Trouble Under Foot (http://www.wowhead.com/quest=14226)\n\nGetting to Xylem's Trials\n15.)The Pinnacle of Learning (http://www.wowhead.com/quest=14413)\n16.)Watch Your Step (http://www.wowhead.com/quest=14296)\n\nXylem's Trials\n17.)The Trial of Fire (http://www.wowhead.com/quest=14300)\n---Achievement: Glutton for Fiery Punishment (http://www.wowhead.com/achievement=5448)\n18.)The Trial of Frost (http://www.wowhead.com/quest=24478)\n---Achievement: Glutton for Icy Punishment (http://www.wowhead.com/achievement=5546)\n19.)The Trial of Shadow (http://www.wowhead.com/quest=24479)\n---Achievement: Glutton for Shadowy Punishment (http://www.wowhead.com/achievement=5547)\n\nFinding Azuregos\n20.)Xylem's Asylum (http://www.wowhead.com/quest=14299)\n21.)Wasn't It Obvious? (http://www.wowhead.com/quest=14389)\n22.)Easy is Boring (http://www.wowhead.com/quest=14390)\n23.)Turning the Tables (http://www.wowhead.com/quest=14391)\n\nThe Final Battle\n24.)Fade to Black (http://www.wowhead.com/quest=24467)",
            date = "2010-11-24T01:30:34-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14230#comments:id=1179885",
        },
        {
            id = 1518697,
            score = 13,
            author = "InnaSkadi",
            text = "Apparently there's only one green book at 55.2, 25.1. Besides the other books have a different effect when you read then according with the color:\n\nBlue - eyeball shooting a blue pulse beam\nRed with brown pages - a jet of fire\nRed with black pages - a beam of black light\nBlack - black clawed hand\nWhite - a beam of white light",
            date = "2011-09-15T14:12:40-05:00",
            sourceUrl = "https://www.wowhead.com/quest=14230#comments:id=1518697",
        },
    },
