    [14246] = {
        {
            id = 1193898,
            score = 23,
            author = "Dracomortis",
            text = "Once you place the egg (http://www.wowhead.com/item=49014) in one of the nests, you will have to fight off 2 to 4 non-elite mobs that spawn one at a time and run towards the egg, attempting to destroy it. (It should be noted that the regular mobs that roam the area will also start attacking the egg if they happen to wander close enough to \"aggro\" it). Each spawned mob will be either a Famished Bonepaw (http://www.wowhead.com/npc=35811) hyena or a Snapjaw Basilisk (http://www.wowhead.com/npc=35750). Once you've fought off the mobs, a Defiant Swoop (http://www.wowhead.com/npc=35752) will appear and carry off the egg.",
            date = "2010-11-28T16:24:50-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14246#comments:id=1193898",
        },
        {
            id = 1300844,
            score = 14,
            author = "325953",
            text = "Even though it says Thunk is part of the Cenarion Circle, you do not get their reputation for this quest.",
            date = "2011-01-19T18:05:26-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14246#comments:id=1300844",
        },
        {
            id = 1182263,
            score = 10,
            author = "262388",
            text = "Takes a while for this quest to register each egg.  You have to wait for 3 waves of 1 mob each to try and steal the egg and there's a healthy gap between each wave.  After this, a swoop will come and take the egg.  This will register the egg watched and you need to do it 3 times.",
            date = "2010-11-24T16:29:50-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14246#comments:id=1182263",
        },
        {
            id = 2514064,
            score = 8,
            author = "Modinstaller",
            text = "Just did the quest now (on a 110 character, mind you, doing loremaster), and was curious to see what'd happen if you didn't fight the predators.\n\nWell, nothing happens. You get completion nevertheless, the eggs are just too tanky.\n\nDon't think it had anything to do with my level as the egg was still lvl 30.\n\nQuite fun to see how easy the game has become at low levels !",
            date = "2017-08-17T18:58:28-05:00",
            sourceUrl = "https://www.wowhead.com/quest=14246#comments:id=2514064",
        },
        {
            id = 2469968,
            score = 7,
            author = "Galaxas",
            text = "Can't protect 2 nests at a time, sadly. One egg will disappear if you place a second one.",
            date = "2017-02-05T13:50:57-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14246#comments:id=2469968",
        },
    },
    [14247] = {
    },
    [14249] = {
        {
            id = 1179870,
            score = 18,
            author = "420211",
            text = "This is part of a quest chain in which the player aids Kalecgos (the new blue dragon aspect) in finding Azuregos and protecting him from the black dragonflight. It spans much of the land of Azshara and is composed of many quests, several of which are completely original in their concepts.\n\n1.)Azshara Blues (http://www.wowhead.com/quest=14407)\n2.)Friends Come In All Colors (http://www.wowhead.com/quest=14130)\n\nHelping out Ergll:\n3.)A Little Pick-me-up (http://www.wowhead.com/quest=14131)\n4.)Absorbent (http://www.wowhead.com/quest=14323)\n---5.)Full of Hot Water (http://www.wowhead.com/quest=14324)\n6.)That's Just Rude! (http://www.wowhead.com/quest=14132)\n\nFinding Archmage Xylem:\n7.)The Way to a Mage's Heart (http://www.wowhead.com/quest=14133)\n8.)Wash Out (http://www.wowhead.com/quest=14345)\n9.)Dressed to Impress (http://www.wowhead.com/quest=14340)\n\nHelping Xylem and his Apprentices:\n10.)Shear Will\n11.)Waste of Thyme (http://www.wowhead.com/quest=14263)\n12.)Renewable Resource (http://www.wowhead.com/quest=14250)\n\n13.)Manual Labor (http://www.wowhead.com/quest=14230)\n14.)Trouble Under Foot (http://www.wowhead.com/quest=14226)\n\nGetting to Xylem's Trials\n15.)The Pinnacle of Learning (http://www.wowhead.com/quest=14413)\n16.)Watch Your Step (http://www.wowhead.com/quest=14296)\n\nXylem's Trials\n17.)The Trial of Fire (http://www.wowhead.com/quest=14300)\n---Achievement: Glutton for Fiery Punishment (http://www.wowhead.com/achievement=5448)\n18.)The Trial of Frost (http://www.wowhead.com/quest=24478)\n---Achievement: Glutton for Icy Punishment (http://www.wowhead.com/achievement=5546)\n19.)The Trial of Shadow (http://www.wowhead.com/quest=24479)\n---Achievement: Glutton for Shadowy Punishment (http://www.wowhead.com/achievement=5547)\n\nFinding Azuregos\n20.)Xylem's Asylum (http://www.wowhead.com/quest=14299)\n21.)Wasn't It Obvious? (http://www.wowhead.com/quest=14389)\n22.)Easy is Boring (http://www.wowhead.com/quest=14390)\n23.)Turning the Tables (http://www.wowhead.com/quest=14391)\n\nThe Final Battle\n24.)Fade to Black (http://www.wowhead.com/quest=24467)",
            date = "2010-11-24T01:23:32-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14249#comments:id=1179870",
        },
        {
            id = 1072689,
            score = 5,
            author = "Chilela",
            text = "Each hippogryph drops 1 feather as of 7/3/10, so you have to kill 80 hippogryphs to complete this quest. As it turns out, you get more XP from the kills on this quest than you do for completing this quest.\n\nEDIT: As stated in the reply, the above status is no longer correct.",
            date = "2010-07-04T07:43:51-05:00",
            sourceUrl = "https://www.wowhead.com/quest=14249#comments:id=1072689",
        },
        {
            id = 1192598,
            score = 5,
            author = "62029",
            text = "- Now, every hippogryph drops 5-12 feathers.\nBlizzard seems to understand that killing 80 hippogryphs doesn't really make sense.",
            date = "2010-11-28T06:56:19-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14249#comments:id=1192598",
        },
        {
            id = 1514669,
            score = 5,
            author = "Jozroz",
            text = "I'm not getting a single one after 7+ kills. And I DID accept the quest before anybody says I didn't.\n\nEDIT: I think it is an absolute requirement to wear the [item=49201 domain=www] to collect the quest items. I am sure about this because the same problem occurred when I tried to get the items off Balboa. I blew his chunks off but wasn't allowed to loot the mounds. So word of advice, keep the [item=49201 domain=www] of you decide to drop the quest line in case you change your mind in the future and want to get the [item=53057 domain=www] . So for all you losers (like me) who destroyed the hat before completing these quests, no shape-shifting hat for you.",
            date = "2011-09-10T12:13:02-05:00",
            sourceUrl = "https://www.wowhead.com/quest=14249#comments:id=1514669",
        },
        {
            id = 1613810,
            score = 3,
            author = "31866",
            text = "Reference to the old Ironfeather set, which took 200 feathers to craft. He equips it when you complete the quest.",
            date = "2012-01-20T04:27:57-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14249#comments:id=1613810",
        },
    },
