            author = "708028",
            text = "You will see a large brown walkway. This is the path that Balboa patrols. Wait on the pathway until Balboa appears, then use the item to place a charge and run. When Balboa strikes it, he will let lose 5 chunks of Basalt you can pick up to complete the quest.",
            date = "2010-11-24T21:19:46-06:00",
