    [14254] = {
        {
            id = 1182275,
            score = 15,
            author = "262388",
            text = "Little glowing rocks scattered about near the fissure.  I found them more on the tiny hills nearby than on flat ground for reference.  If you dont find them nearby, head towards Thunderaxe Fortress.  All kinds near the road by there and the turn in location is just outside the fortress too.",
            date = "2010-11-24T16:32:42-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14254#comments:id=1182275",
        },
        {
            id = 1689514,
            score = 14,
            author = "1015399",
            text = "I love the embedded pun here.  Element 116, prior to being formally named, was known as ununhexium.  This metal is preventing the restoration of Desolace, and is thus \"un\"unhexing the land. Genius, Blizzard, pure genius.",
            date = "2012-07-18T13:33:29-05:00",
            sourceUrl = "https://www.wowhead.com/quest=14254#comments:id=1689514",
        },
        {
            id = 1768168,
            score = 13,
            author = "921728",
            text = "While kchunter86 in this thread mentioned it, here is more info. To start this quest you must pick up the quest Stubborn Lands (http://www.wowhead.com/quest=14247) from Cenarion Embassador Thunk (http://www.wowhead.com/npc=35661) who is located in Desolace at (oddly enough) Thunk's Abode, which also has a neutral (Cenarion Circle (http://www.wowhead.com/faction=609)) flight master (Thunk's Wyvern (http://www.wowhead.com/npc=35556)). Thunk can be found at 70.4,33.0 or near a dry wadi, south of Sargeron but north of the Magram Territory hills. This quest sends you to a large, charcoal grey, smoldering stone at 69.3, 21.4 or due west of Sargeron (from the words on the Desolace world map) and due south of Nijel's Point (from the words on the Desolace world map.\n\nNote: you do not need Thunk's quests to complete the Desolace quest achievement, but they do count towards Loremaster but oddly enough not towards Cenarion Circle rep.",
            date = "2012-11-26T12:05:25-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14254#comments:id=1768168",
        },
        {
            id = 1186626,
            score = 11,
            author = "206788",
            text = "You cannot turn in this quest when you are hated by Ratchet!",
            date = "2010-11-26T03:24:41-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14254#comments:id=1186626",
        },
        {
