    [14256] = {
        {
            id = 1196964,
            score = 70,
            author = "242813",
            text = "To complete this quest, speak to the quest giver again and click 'I am ready to be shown this threat you speak of, Korrah.'\n\nHe will send you on a hippogryph ride around the nearby shores and allow you to turn the quest in after you land.",
            date = "2010-11-30T02:04:26-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14256#comments:id=1196964",
        },
        {
            id = 1441629,
            score = 18,
            author = "421814",
            text = "Note that as a higher-level player with your own mount, you can trigger all four of Korrah's quotes by following the quest's flight path, but you cannot complete the quest unless you ride Korrah's hippogryph.",
            date = "2011-06-14T20:15:13-05:00",
            sourceUrl = "https://www.wowhead.com/quest=14256#comments:id=1441629",
        },
        {
            id = 2451290,
            score = 4,
