    [14263] = {
        {
            id = 1173578,
            score = 63,
            author = "Blackspirit",
            text = "They're little yellow flowers that are hard to see on the amber color of the grass. They're only found near trees though as far as I can tell, so finding them won't be too hard. They don't show up as herbs for tracking purposes either. Every time you pick one you get a debuff called Living Ire that increases damage done and damage taken by 20% and turns you red for 1m (good to use in conjunction with the collect 80 feathers quest in the same area).",
            date = "2010-11-17T15:53:35-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14263#comments:id=1173578",
        },
        {
            id = 1177388,
            score = 20,
            author = "Ayvalen",
            text = "If, like me, you enjoy playing your game on Ultra these little plants can be VERY difficult to spot due to how lush Blizzard has now made the environments. If you go to the Video settings and turn the \"Ground Clutter Density\" to the lowest possible setting it makes these things extremely easy to find. Once finished you can go back to your regular setting and keep on playing. Good luck!",
            date = "2010-11-22T03:20:41-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14263#comments:id=1177388",
        },
        {
            id = 1179871,
            score = 16,
            author = "420211",
            text = "This is part of a quest chain in which the player aids Kalecgos (the new blue dragon aspect) in finding Azuregos and protecting him from the black dragonflight. It spans much of the land of Azshara and is composed of many quests, several of which are completely original in their concepts.\n\n1.)Azshara Blues (http://www.wowhead.com/quest=14407)\n2.)Friends Come In All Colors (http://www.wowhead.com/quest=14130)\n\nHelping out Ergll:\n3.)A Little Pick-me-up (http://www.wowhead.com/quest=14131)\n4.)Absorbent (http://www.wowhead.com/quest=14323)\n---5.)Full of Hot Water (http://www.wowhead.com/quest=14324)\n6.)That's Just Rude! (http://www.wowhead.com/quest=14132)\n\nFinding Archmage Xylem:\n7.)The Way to a Mage's Heart (http://www.wowhead.com/quest=14133)\n8.)Wash Out (http://www.wowhead.com/quest=14345)\n9.)Dressed to Impress (http://www.wowhead.com/quest=14340)\n\nHelping Xylem and his Apprentices:\n10.)Shear Will (http://www.wowhead.com/quest=14249)\n11.)Waste of Thyme\n12.)Renewable Resource (http://www.wowhead.com/quest=14250)\n\n13.)Manual Labor (http://www.wowhead.com/quest=14230)\n14.)Trouble Under Foot (http://www.wowhead.com/quest=14226)\n\nGetting to Xylem's Trials\n15.)The Pinnacle of Learning (http://www.wowhead.com/quest=14413)\n16.)Watch Your Step (http://www.wowhead.com/quest=14296)\n\nXylem's Trials\n17.)The Trial of Fire (http://www.wowhead.com/quest=14300)\n---Achievement: Glutton for Fiery Punishment (http://www.wowhead.com/achievement=5448)\n18.)The Trial of Frost (http://www.wowhead.com/quest=24478)\n---Achievement: Glutton for Icy Punishment (http://www.wowhead.com/achievement=5546)\n19.)The Trial of Shadow (http://www.wowhead.com/quest=24479)\n---Achievement: Glutton for Shadowy Punishment (http://www.wowhead.com/achievement=5547)\n\nFinding Azuregos\n20.)Xylem's Asylum (http://www.wowhead.com/quest=14299)\n21.)Wasn't It Obvious? (http://www.wowhead.com/quest=14389)\n22.)Easy is Boring (http://www.wowhead.com/quest=14390)\n23.)Turning the Tables (http://www.wowhead.com/quest=14391)\n\nThe Final Battle\n24.)Fade to Black (http://www.wowhead.com/quest=24467)",
            date = "2010-11-24T01:24:13-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14263#comments:id=1179871",
        },
        {
            id = 1182553,
            score = 4,
            author = "292516",
            text = "Turn your environment video settings to low. They stick out nicely then.",
            date = "2010-11-24T18:18:01-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14263#comments:id=1182553",
        },
        {
            id = 1189037,
            score = 3,
            author = "452103",
            text = "Cannot be tracked with herbs.\n-Ihack Anetheron US.",
            date = "2010-11-26T22:58:44-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14263#comments:id=1189037",
        },
    },
    [14264] = {
        {
            id = 1191081,
            score = 27,
            author = "253120",
            text = "Tangle the elementals first and then throw the tridents.\n\nOther Naga in the area will help you fight them, they will count towards your five.\n\nBeware of Hammerhead sharks, they are elite and will knock you out of your disguise. Very dangerous.",
            date = "2010-11-27T17:25:31-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14264#comments:id=1191081",
        },
        {
            id = 1349423,
            score = 22,
            author = "zacke10",
            text = "If you cannot find the quest NPC (Valishj) it is most likely that she has been killed. On my server she got a very slow respawn. Had to wait 5-10 minutes.",
            date = "2011-02-25T07:19:49-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14264#comments:id=1349423",
        },
        {
            id = 2139631,
            score = 15,
            author = "kdegnan",
            text = "I abandoned this quest when I was leveling, but came back to get it for the Desolace Quests achievement so I could get the Loremaster Achievement. I was ready to start ripping out my hair for not being able to find the questgiver who would actually give this quest!\n\nIt turns out, you need to go to Cenarion Researcher Korrah (38.8, 27.0) on the north side of the tower that is east of Furien's Post. Get the Slitherblade Charm and go to Slitherblade Shore. If you're higher level and can fly, that's the fastest way to get there. DON'T KILL LADY VALISHJ! (You need her and she has a very slow re-spawn rate) Once on the island, use the Slitherblade Charm and now Lady Valishj has the quest for you, enabling you to get back on the chain and on your way to the achievement.",
            date = "2015-03-17T13:28:32-05:00",
            sourceUrl = "https://www.wowhead.com/quest=14264#comments:id=2139631",
        },
        {
            id = 1442951,
            score = 9,
            author = "829373",
            text = "Few things about this quest.\n\nFirst off, the actual attack you use is pretty weak. Luckily, it and the web ability you are given can both be used while on  the move.\n\nSecondly, if for some reason, when you return to Valishj she is marked as hostile, simply re-use the quest item to transform into a naga.",
            date = "2011-06-16T20:55:33-05:00",
            sourceUrl = "https://www.wowhead.com/quest=14264#comments:id=1442951",
        },
        {
            id = 1299786,
            score = 8,
            author = "480306",
            text = "Please Note:  Llotus said, \"then throw the tridents.\" In order for the tridents to work you need about  20 yards to throw... If you fight them point blank it doesn't work....Hope that helps...",
            date = "2011-01-18T23:21:42-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14264#comments:id=1299786",
        },
    },
    [14267] = {
        {
            id = 1808693,
            score = 11,
            author = "Bl4cky",
            text = "I can confirm, that you have to complete Mortar the Point (http://www.wowhead.com/quest=14258) from Bombardier Captain Smooks (http://www.wowhead.com/npc=35817) (who apparently has 2 positions in the game, one at Talrendis Point, Azshara (http://www.wowhead.com/npc=36785), where he hands out 2 other quests in a different questline and one at the Southern Rocketway, Azshara (http://www.wowhead.com/npc=35817), where he hands out the above mentioned quest) before you can start this questline.",
            date = "2013-02-03T16:42:42-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14267#comments:id=1808693",
        },
    },
    [14268] = {
        {
            id = 1182196,
            score = 138,
            author = "262388",
            text = "For those wondering, the marking on the map is wrong.  It's much farther north in the ruins all around Ranazjar Island.  Little rocks like the picture above you use the stick on.  You then loot the items that pop out of the rock and hope for fragments.  And expect to be at it a while.  Very low drop rate.  For reference, I had 77 of the Illegiable versions and about 3-4 tablets drop per site.  Add swim time (though as a naga is much faster) and finding the spots and it's quite annoying for a non-kill based quest.",
            date = "2010-11-24T16:10:04-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14268#comments:id=1182196",
        },
        {
            id = 1186596,
            score = 79,
            author = "316590",
            text = "Definitely map is marked wrong - it is anywhere from the southeast of the isle to the mainland shore.\n\nSomething that makes this quest CONSIDERABLY less annoying is that the staff a) has a range and b) can be used while moving.  The rubbles are somewhat hard to pick out, but if you just swim around and spam the staff use, it'll shoot a big blue bolt and find the rubble for you.",
            date = "2010-11-26T03:01:07-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14268#comments:id=1186596",
        },
        {
            id = 1351086,
            score = 70,
            author = "Bangbangbang",
            text = "Lol, I love this quest now, my RL friend all of a sudden calls me on skype and he's new to WoW so he's like \"OMFG! I've spend 3 !@#$ing hours on this lame-ass quest\" and I have already explained to him if he has a problem, he should go to wowhead, and when I asked him about that he said he didn't know how to use it. So I go on Wowhead for him to check out this quest, and I find out he only needs 4 of thoose fragments, and I ask him \"So, how many did you collect? Because you just need four to make the quest\".. Then he went quiet for a moment before telling me he had collected 80 of the *!@#ing things.. I laughed so much I fell of my chair. Litterally :D",
            date = "2011-02-26T17:08:17-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14268#comments:id=1351086",
        },
        {
            id = 1189425,
            score = 40,
            author = "61037",
            text = "If you want to save time looting, either I'm extremely luck (or unlucky) but I only got the runes I needed out of the runes that had the yellow symbol on them.",
            date = "2010-11-27T02:58:39-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14268#comments:id=1189425",
        },
        {
            id = 1263182,
            score = 36,
            author = "293598",
            text = "HIT #4 on your KEYBOARD! don't try and use the staff out of your bag, it wont work.",
            date = "2010-12-28T03:11:44-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14268#comments:id=1263182",
        },
    },
