    [14271] = {
        {
            id = 1253838,
            score = 4,
            author = "734502",
            text = "You will get a blue orb around you and the quest text says \"a magical barrier pulses around you, chilling your bones. You feel secure behind this enchanted wall.\"...\n\nDON'T BELIEVE IT! I ran through a ton of Naga assuming that this was some kind of protection to make the run back a little less of a pain. Nope -- it doesn't protect you at all. Needless to say I died. Don't make the same mistake and use normal precautions when heading back.",
            date = "2010-12-23T03:19:09-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14271#comments:id=1253838",
        },
    },
    [14282] = {
        {
            id = 1188661,
            score = 9,
            author = "435875",
            text = "Completing this quest will delete the Slitherblade Charm (http://www.wowhead.com/item=49064).",
            date = "2010-11-26T19:34:05-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14282#comments:id=1188661",
        },
        {
