            text = "This is the only quest in the chain given by this questgiver that gives Cenarion Expedition rep.  I haven't figured out why, but I think it may be an anomaly.",
            date = "2010-12-02T13:17:54-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14282#comments:id=1202172",
        },
    },
    [14284] = {
        {
            id = 1260198,
            score = 88,
            author = "Aletto",
            text = "\"Hydronis wants you to mount him and defeat Priestess Valishj.\"\n\nMount him? But I hardly know him!",
            date = "2010-12-26T14:57:37-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14284#comments:id=1260198",
        },
        {
            id = 1182241,
            score = 46,
            author = "262388",
            text = "Tip 1: you fight here right in front of where you get on the water elemental.  I mistakenly thought Id just run off to where I first saw/spoke to the naga priestess, but it dismounts you out in the water off the island.\n\nTip 2: you can auto attack and afk to win this fight if you want.  Otherwise, iceblock will restore hpa nd mana and has a low cooldown if you want to just spam spells.  Dismount to turn in the quest.",
            date = "2010-11-24T16:22:22-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14284#comments:id=1182241",
        },
        {
            id = 1183509,
            score = 40,
            author = "Cornnelius",
            text = "If you are high enough level its faster to just leave the vehicle as soon as the priestess shows up and kill her.",
            date = "2010-11-25T01:39:02-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14284#comments:id=1183509",
        },
        {
            id = 1193529,
            score = 28,
            author = "141924",
            text = "I wish my ice block restored mana and health...",
            date = "2010-11-28T13:58:21-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14284#comments:id=1193529",
        },
        {
            id = 1248031,
            score = 20,
            author = "240259",
            text = "This guy seem to suffer from self-esteem problems, because the auto-attack is enough to defeat her.",
            date = "2010-12-20T13:29:29-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14284#comments:id=1248031",
        },
    },
    [14292] = {
        {
            id = 1197399,
            score = 47,
