    [14295] = {
        {
            id = 1212697,
            score = 7,
            author = "721619",
            text = "As of 4.0.3a it appears that you must either deal the killing blow or fight the sisters solo.  Had to do this one thrice since I was in a group.",
            date = "2010-12-07T17:21:40-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14295#comments:id=1212697",
        },
        {
            id = 1196493,
            score = 3,
            author = "clavarnway",
            text = "You don't need to destroy the stones behind them to get credit for killing them, despite what the quest text says.  Though if you're appropriate level for the quest you probably should, since it \"de-elites\" them.",
            date = "2010-11-29T20:16:16-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14295#comments:id=1196493",
        },
        {
            id = 1893543,
            score = 3,
            author = "evlyxx",
            text = "I had to log out and back in after killing the sisters for the quest tracker to register the credit, seems to be a common bug lately as I have to do the same when doing the Argent Tournament dailies in Icecrown.",
            date = "2013-09-07T11:04:41-05:00",
            sourceUrl = "https://www.wowhead.com/quest=14295#comments:id=1893543",
        },
        {
            id = 1075174,
            score = 1,
            author = "549359",
            text = "Manged to solo These 2 bosses with an Goblin Rogue lvl 17 Spec: 0/5/2",
            date = "2010-07-07T08:43:49-05:00",
            sourceUrl = "https://www.wowhead.com/quest=14295#comments:id=1075174",
        },
        {
            id = 1250278,
            score = 0,
            author = "Xiamaru",
            text = "...I didn't even know it de-elited them >_> Just killed them with a level 14 Hunter, only to find the crystal and destroy them. When I couldn't figure out what the point of destroying them were, I read the quest, dropped on here on WoWhead, and figured out why...\n\nSeriously, if they make these kinds of things, they should at least make it so you almost HAVE to destroy them. Otherwise, these \"empowerments\" lose the effect quite fast. Why should I spend time running up the alter to destroy it, when I could just as well kill her off, spending the same amount of time? I would much rather dish out pain, than purposely run past a mob, letting it attack me several times before I even begin to attack.\n\nElites aren't what they used to be...",
            date = "2010-12-21T11:46:55-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14295#comments:id=1250278",
        },
    },
    [14296] = {
        {
            id = 1297591,
            score = 95,
            author = "Paladin666",
            text = "There is a little cheat in this quest the Energy Conduit next to Image of Archmage Xylem at the beginning of the quest can be clicked on multiple times and you won't get blown off. All you need to do is click the first one six of times and all you need to do is refresh the buff by touching the other ones.",
            date = "2011-01-17T09:24:04-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14296#comments:id=1297591",
        },
        {
            id = 1179888,
            score = 33,
            author = "420211",
            text = "This is part of a quest chain in which the player aids Kalecgos (the new blue dragon aspect) in finding Azuregos and protecting him from the black dragonflight. It spans much of the land of Azshara and is composed of many quests, several of which are completely original in their concepts.\n\n1.)Azshara Blues (http://www.wowhead.com/quest=14407)\n2.)Friends Come In All Colors (http://www.wowhead.com/quest=14130)\n\nHelping out Ergll:\n3.)A Little Pick-me-up (http://www.wowhead.com/quest=14131)\n4.)Absorbent (http://www.wowhead.com/quest=14323)\n---5.)Full of Hot Water (http://www.wowhead.com/quest=14324)\n6.)That's Just Rude! (http://www.wowhead.com/quest=14132)\n\nFinding Archmage Xylem:\n7.)The Way to a Mage's Heart (http://www.wowhead.com/quest=14133)\n8.)Wash Out (http://www.wowhead.com/quest=14345)\n9.)Dressed to Impress (http://www.wowhead.com/quest=14340)\n\nHelping Xylem and his Apprentices:\n10.)Shear Will (http://www.wowhead.com/quest=14249)\n11.)Waste of Thyme (http://www.wowhead.com/quest=14263)\n12.)Renewable Resource (http://www.wowhead.com/quest=14250)\n\n13.)Manual Labor (http://www.wowhead.com/quest=14230)\n14.)Trouble Under Foot (http://www.wowhead.com/quest=14226)\n\nGetting to Xylem's Trials\n15.)The Pinnacle of Learning (http://www.wowhead.com/quest=14413)\n16.)Watch Your Step\n\nXylem's Trials\n17.)The Trial of Fire (http://www.wowhead.com/quest=14300)\n---Achievement: Glutton for Fiery Punishment (http://www.wowhead.com/achievement=5448)\n18.)The Trial of Frost (http://www.wowhead.com/quest=24478)\n---Achievement: Glutton for Icy Punishment (http://www.wowhead.com/achievement=5546)\n19.)The Trial of Shadow (http://www.wowhead.com/quest=24479)\n---Achievement: Glutton for Shadowy Punishment (http://www.wowhead.com/achievement=5547)\n\nFinding Azuregos\n20.)Xylem's Asylum (http://www.wowhead.com/quest=14299)\n21.)Wasn't It Obvious? (http://www.wowhead.com/quest=14389)\n22.)Easy is Boring (http://www.wowhead.com/quest=14390)\n23.)Turning the Tables (http://www.wowhead.com/quest=14391)\n\nThe Final Battle\n24.)Fade to Black (http://www.wowhead.com/quest=24467)",
            date = "2010-11-24T01:31:59-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14296#comments:id=1179888",
        },
        {
            id = 1179707,
            score = 30,
            author = "707324",
            text = "Make sure you don't miss the charge that is right next to the guy who starts the quest.",
            date = "2010-11-24T00:15:16-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14296#comments:id=1179707",
        },
        {
            id = 1253588,
            score = 23,
            author = "svict4",
            text = "If you have a flying mount - you can just just keep clicking the Energy Conduits next to Xylem until 6 stacks and just fly up :D",
            date = "2010-12-23T00:16:32-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14296#comments:id=1253588",
        },
        {
            id = 1361687,
            score = 19,
            author = "RemusCDLupin",
            text = "It took me about five tries to finally get the hang of this. First off, do as other posters have suggested and pick up all six charges right off the bat.   Keep moving and just right click the other posts as you pass by them. As you come up to the jump pads pause next to or on them, it takes them just a sec to activate.  When you land you are facing the right direction so just move as soon as you land. If you can keep your cool you'll get it quickly.  Mind if you're doing it for rep and have a flying mount, by all means, just pick up your six charges right on the beginning stand and fly up to the top.",
            date = "2011-03-08T20:51:48-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14296#comments:id=1361687",
        },
    },
