    [14304] = {
        {
            id = 1274451,
            score = 37,
            author = "708220",
            text = "Quests like this is what still keep Desolace so desolate...\n\nAvoid using any AoE attacks when killing the infested kodos. The leeches are targetable and have only 42 life; they'll die to your AoE attacks if they continue after the kodo has died. Also they seem to despawn as soon as another leech spawns, so you can only do one kodo at a time.",
            date = "2011-01-03T03:36:34-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14304#comments:id=1274451",
        },
        {
            id = 1260254,
            score = 36,
            author = "Aletto",
            text = "\"The Cenarion Circle has worked hard to restore life to Desolace.\n\nThere are some kodo nearby that seem to be rejuvenated with newfound life!\n\n...now throw these blood-sucking parasites onto the kodo, then slaughter the beasts.\"",
            date = "2010-12-26T15:33:43-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14304#comments:id=1260254",
        },
        {
            id = 1197859,
            score = 22,
            author = "254881",
            text = "Cast bottle (http://www.wowhead.com/item=49138) on Rejuvenated Thunder Lizard (http://www.wowhead.com/npc=35412), then kill it and loot Blood-filled Leec (http://www.wowhead.com/npc=36059)h on ground.. Done!",
            date = "2010-11-30T13:00:52-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14304#comments:id=1197859",
        },
        {
            id = 1448852,
            score = 10,
            author = "712867",
            text = "Bottle of Leeches (http://www.wowhead.com/item=49138) has a 30yrd range.  Using this item on the Rejuventated Thunder Lizard (http://www.wowhead.com/npc=35412) will cause it to aggro.",
            date = "2011-06-23T13:22:42-05:00",
            sourceUrl = "https://www.wowhead.com/quest=14304#comments:id=1448852",
        },
        {
            id = 5826657,
            score = 9,
            author = "Ilgaten",
            text = "Well, it's 2024, and I might be the only person going to Desolace all year, but maybe this will help someone.\nIf you damage the leech after you kill the lizard -- even a tiny amount of damage -- you won't be able to loot the leech. The leech should have a \"loot\" tooltip after you kill the lizard. If you damage it, it will have a \"knife\" icon, and you're out of luck. Once I realized how I was damaging the leech, looting it was 10 for 10.\nAre you a warlock? Dismiss your minion for this quest. Are you Affliction? Switch your talents so you don't have Soul Flame -- sixth row on the Affliction side during the Dragonflight expansion.",
            date = "2024-04-13T15:36:55-05:00",
            sourceUrl = "https://www.wowhead.com/quest=14304#comments:id=5826657",
        },
    },
