    [14308] = {
        {
            id = 1180413,
            score = 51,
            author = "Trem123",
            text = "Dont be in catform, druids",
            date = "2010-11-24T05:50:26-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14308#comments:id=1180413",
        },
        {
            id = 1416526,
            score = 20,
            author = "Gilthanas11",
            text = "And don't be in wolf form, shammys.",
            date = "2011-05-12T04:07:39-05:00",
            sourceUrl = "https://www.wowhead.com/quest=14308#comments:id=1416526",
        },
        {
            id = 1180008,
            score = 8,
            author = "189805",
            text = "A reference to the first Half Life game, in which Gordon Freeman (a scientist proficient in the field of Crowbars) creates a \"resonance cascade\", which starts the events of the game.\n\nIt could quite possible reference the new Portal game (Portal 2), with the use of \"hypercooled, pressurised liquigel\" although I think I might be reading too much into that one.\n\nResonance Cascade (http://half-life.wikia.com/wiki/Resonance_Cascade)",
            date = "2010-11-24T02:31:47-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14308#comments:id=1180008",
        },
        {
            id = 1335961,
            score = 8,
            author = "729828",
            text = "The Research interns say some funny things when rescued, such as:\n\n\"Make a note: Fire bad.\"\n\"I'm gonna go find some ointment.\"\n\"Whew, thanks! I'm going to check and see if these results are repeatable.\"\n\"That wasn't as bad as it looked.\"",
            date = "2011-02-14T11:52:49-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14308#comments:id=1335961",
        },
        {
            id = 1564306,
            score = 7,
            author = "chexmixultimate",
            text = "When they're running around, they say things like:\n\n\"I'm on fire. Note that in the logs.\"\n\"The goggles! They do nothing!\" (I especially like this one, and the idea of putting on goggles to protect yourself from being on fire)\n\"The whole place is gonna blow!\"\n\"This is one of our less productive colossal disasters.\"\n\"Again with the flames and the hurt.\"\n\"Fire... FIRE!\"",
            date = "2011-11-06T02:55:32-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14308#comments:id=1564306",
        },
    },
