    [14310] = {
        {
            id = 1127481,
            score = 50,
            author = "231954",
            text = "WE MUST PUSH LITTLE CART!",
            date = "2010-09-25T09:01:09-05:00",
            sourceUrl = "https://www.wowhead.com/quest=14310#comments:id=1127481",
        },
        {
            id = 1187281,
            score = 39,
            author = "kurohoshi",
            text = "In fact, it is also a computer science reference:\nSegmentation Fault (http://en.wikipedia.org/wiki/Segmentation_fault)\nIn short, Segmentation fault is an error caused when programs try to access memory zones they are not allowed to.\n\nCore Dump (http://en.wikipedia.org/wiki/Core_dump)\nCore dump is some program's state record.\n\nIt's common that when OS gives a Segmentation fault to any process, it will also save the state of the process (perform a Core Dump), should be reviewed later. Therefore, the error given is \"Segmentation Fault: Core Dumped\"",
            date = "2010-11-26T09:47:13-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14310#comments:id=1187281",
        },
        {
            id = 1364381,
            score = 27,
            author = "717575",
            text = "Trying to do this in Travel Form (and probably the other shapeshift forms) gives the warning \"Requires Opposable Thumbs.\"",
            date = "2011-03-11T18:42:44-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14310#comments:id=1364381",
        },
        {
            id = 1180061,
            score = 19,
            author = "189805",
            text = "I believe there are two references to TF2 (Team Fortress 2) in this quest.\n\nFirst, the big Goblin says \"We must push little cart!\" when he wheels it along. When playing a Cart map in TF2, the Heavy will periodically say this when the cart stops.\n\nThe second reference is in the text as you end it; Assistant Greely refers to Azharite as;\n\n\"Azharite is a complex mystery wrapped in a velvety enigma of danger.\"\n\nThe description for the spy class reads as follows;\n\n\"He is a puzzle, wrapped in an enigma, shrouded in riddles, lovingly sprinkled with intrigue, express mailed to Mystery, Alaska, and LOOK OUT BEHIND YOU! But it is too late. You're dead. For he is the Spy — globetrotting rogue, lady killer (metaphorically) and mankiller (for real). \"\n\nIt may not be a direct homage to the Spy, but that was the first thought that popped into my head when I read it.",
            date = "2010-11-24T02:59:49-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14310#comments:id=1180061",
        },
        {
            id = 1223134,
            score = 19,
            author = "611800",
            text = "Whoever thought it was a good idea to have a quest use A CHANNELED EFFECT ON A MOVING OBJECT needs to be slapped.",
            date = "2010-12-10T22:41:13-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14310#comments:id=1223134",
        },
    },
