    [14312] = {
        {
            id = 1635154,
            score = 44,
            author = "sephyre",
            text = "You need to complete these two quests to unlock this quest chain:\n\nhttps://www.wowhead.com/npc=36060 in Karnum's Glade, Desolace (58.2, 50.0)\nhttps://www.wowhead.com/quest=14305\nhttps://www.wowhead.com/quest=14306\nhttps://www.wowhead.com/quest=14311\n\nAlso there is no prereq for her quests, so you can go straight to her when you enter Desolace.\n\nJust to add a more descriptive list of the quests in this chain:\n\nhttps://www.wowhead.com/npc=36052 in Karnum's Glade\nhttps://www.wowhead.com/quest=14312 (you must turn this in to Khan Leh'Prah before you can pick up his second one)\nhttps://www.wowhead.com/quest=14316 Since the objectives are next to each other, you might as well do this and Khan Leh'Prah's follow up quest https://www.wowhead.com/quest=14314  at the same time.\n\nhttps://www.wowhead.com/npc=36056 Next to Garren Darkwind in Karnum's Glade\nhttps://www.wowhead.com/quest=14314\nhttps://www.wowhead.com/quest=14318 You will turn this in to https://www.wowhead.com/npc=36163\n\nhttps://www.wowhead.com/npc=36163 Magram Territory (71.6, 45.6), he shows up after you complete the objective for https://www.wowhead.com/quest=14318\nhttps://www.wowhead.com/quest=14325\nhttps://www.wowhead.com/quest=14327\n\nhttps://www.wowhead.com/npc=36056 in Karnum's Glade\nhttps://www.wowhead.com/quest=14328 This will be turned in to https://www.wowhead.com/npc=36185\n\nhttps://www.wowhead.com/npc=36185 He is inside the cave in the southern area of the Gelkis Village (40.4, 95.6)\nhttps://www.wowhead.com/quest=14329 Valley of Spears (32, 60.4)\n\nHaving this final quest will allow https://www.wowhead.com/item=38567 to drop from https://www.wowhead.com/npc=4656, and so start the new quest chain starting with https://www.wowhead.com/quest=14330.",
            date = "2012-03-04T18:40:49-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14312#comments:id=1635154",
        },
        {
            id = 1070491,
            score = 4,
            author = "614836",
            text = "It's very nice to see Blizzard taking some of the quests in the game that had a lot of potential such as the centaur quests in Desolace and flushing them out. As I can already tell, they've most definitely made these one's worth doing. As I recall, the centaur never really got much love from Blizz is terms of quests. Sure there were the one's in the Barrens, but it was just grinding them away to take their territory away and killing their leaders.\n\nHopefully this is the beginning of Blizz actually caring about lore in their game again :D",
            date = "2010-07-01T14:23:34-05:00",
            sourceUrl = "https://www.wowhead.com/quest=14312#comments:id=1070491",
        },
        {
            id = 1329955,
            score = 3,
            author = "dafez",
            text = "I just did the 3 quests Botanist Ferrah gives, and unlocked this quest.  I am 1732/3000 Neutral with Cenarion Circle, so Friendly is not a requirement.",
            date = "2011-02-10T05:58:18-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14312#comments:id=1329955",
        },
        {
            id = 1683296,
            score = -2,
            author = "mhfwayne",
            text = "Lol! When I read the text by the centaur, \"Be not afraid...\" I was immediately reminded of the episode of House, where Wilson played a centaur like creature  in a college movie and the rights were sold to a porn director.",
            date = "2012-07-01T12:28:57-05:00",
            sourceUrl = "https://www.wowhead.com/quest=14312#comments:id=1683296",
        },
    },
    [14314] = {
        {
            id = 1199792,
            score = 16,
            author = "cribby",
            text = "Do this (http://www.wowhead.com/quest=14316) quest at the same time or he won't give you the follow up.",
            date = "2010-12-01T08:25:07-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14314#comments:id=1199792",
        },
        {
            id = 1193826,
            score = 5,
            author = "antioch",
            text = "The camp is located at 71.5, 55.5.  You'll have to defeat a Magram Warden and two Magram Wranglers concurrently.",
            date = "2010-11-28T15:54:14-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14314#comments:id=1193826",
        },
        {
            id = 1270275,
            score = 2,
            author = "362863",
            text = "It would appear that this is the last quest in the chain that gives Cenarion rep, so if you were just in it to score points with the Circle, you can stop here.\n\nEdit: Hmm, actually, you may need to do the rest of it in order to eventually get [quest=14330 domain=www] which leads to [quest=14332 domain=www] and [quest=14394 domain=www] (can anyone confirm/deny?)...",
            date = "2010-12-31T20:06:47-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14314#comments:id=1270275",
        },
        {
            id = 1572946,
            score = 2,
            author = "586159",
            text = "Before cataclysm it was possible to get positive Magram clan reputation at cost of Gelkis clan. I've chosen Gelkis so my Magram reputation was hated already, but I was wondering - how does this quest look like if you are friendly with Magram? Can you kill those guards, and if so do you loose rep with Magram?",
            date = "2011-11-15T15:27:57-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14314#comments:id=1572946",
        },
        {
            id = 1631651,
            score = 1,
            author = "teranosouras",
            text = "All 3 mobs will aggro when you pull one of them. You have to actually only kill the Magram Warden though and then the prisoners will escape and you can run for it too.\nThe Wranglers need not be killed.",
            date = "2012-02-25T15:56:54-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14314#comments:id=1631651",
        },
    },
