        },
        {
            id = 1760345,
            score = 18,
            author = "1053744",
            text = "OK, this tribe deserves to die a horrible death. I accept the quest to help feed them.  Then I have to kill 3 of them to get to the food.  I collect the food, and I have to kill a dozen or so to find their leader.  Then, after I've given them food.  I have to kill three right outside the leader's tent.\n\nCentaurs are very dim.",
            date = "2012-11-10T13:13:56-06:00",
