    [14328] = {
        {
            id = 1193661,
            score = 75,
            author = "141924",
            text = "\"Well, they just killed my three sons, so I guess they're pretty wise and I should listen to what they have to say, because they sound reasonable.\"",
            date = "2010-11-28T15:02:24-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14328#comments:id=1193661",
        },
        {
            id = 1207755,
            score = 55,
            author = "300365",
            text = "Khan is actualy in the cave, you need to use the ropebridge to get to him",
            date = "2010-12-05T08:03:50-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14328#comments:id=1207755",
        },
        {
            id = 1944359,
            score = 29,
            author = "bellsong",
            text = "This is one of those quests that I just don't get. Its like, Ok, you just killed my children, you must be pretty badass so of COURSE I'll help you! Doesn't quite make sense to me.",
            date = "2014-02-18T02:53:08-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14328#comments:id=1944359",
        },
        {
            id = 1237589,
            score = 11,
            author = "493620",
            text = "The Three Princes are each in huts around the fissure that runs thru the Gelkis encampment.\nRight side huts, Sherik is @ 35,81 - Jorreth is in last hut on right side @ 35,92\nLeft side huts, Rhoho is at 41,82\nAfter killing these guys, work your way into cave and fight your way down to lowest level.\nKhan Shodo is on lowest path @ 40,95\nAfter completing this part of quest, Khan Shodo will give you another quest.\nThe point here is that at this point the Gelkis become neutral and you won't have to fight your way all the way back to the entrance. Hope this helps.",
            date = "2010-12-16T05:55:40-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14328#comments:id=1237589",
        },
        {
            id = 1549078,
            score = 10,
            author = "Silden",
            text = "Alas, if pre Cataclysm you increased your rep to Friendly or above, you will not be able to attack the Princes, and hence will not be able to complete this quest, even when selecting \"At War\" with this race.",
            date = "2011-10-20T03:23:45-05:00",
            sourceUrl = "https://www.wowhead.com/quest=14328#comments:id=1549078",
        },
    },
    [14329] = {
        {
            id = 1195557,
            score = 23,
            author = "cribby",
            text = "This questline ends rather abruptly. Since you're in the area, pop into Maraudon and find a \"Broken Relic (http://www.wowhead.com/object=196393)\" which starts a quest (http://www.wowhead.com/quest=14333). It's not the instance you're entering, just the ... foyer. So no need for a group.\n\nWhile you're killing the Maulers, one of them will likely drop a quest (http://www.wowhead.com/item=38567#dropped-by) item. This will lead you to Kherrah who is caged, handily, right beside your broken relic which starts another questline (http://www.wowhead.com/quest=14330). Note: Kherrah questline is also do-able by Horde.\n\nAnd since you're in the area ... Melizza Brimbluzzle (http://www.wowhead.com/quest=6132) is also caged and requires an escort.\n\nbusy busy busy!\n\nAn excellent point that was unfortunately downvoted:\nSchnoodledorfer on 2012/09/11 (Patch 5.0.5)\nOP: \"This questline ends rather abruptly.\" Don't pay too much attention to the way Wowhead breaks it into questlines.  Behind Closed Doors should logically be considered part of the same line. After all, the text for this one says, \"You are to search their corpses for clues to Kherrah's whereabouts.\" The \"clue\" you find when you do that gives you  Behind Closed Doors, so it continues. But yes, it's not the same quest giver as the previous turn-in, so Wowhead doesn't make the connection.",
            date = "2010-11-29T11:38:55-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14329#comments:id=1195557",
        },
        {
            id = 1396660,
            score = 7,
            author = "Hinahina",
            text = "Loot the Maulers! They will drop an item that will continue the chain for you!",
            date = "2011-04-21T23:28:05-05:00",
            sourceUrl = "https://www.wowhead.com/quest=14329#comments:id=1396660",
        },
        {
            id = 1635155,
            score = 5,
            author = "sephyre",
            text = "This questline is a prerequisite for the quest chain starting with https://www.wowhead.com/quest=14330.\n\nHaving this final quest will allow https://www.wowhead.com/item=38567 to drop from https://www.wowhead.com/npc=4656, and so start the new quest chain.",
            date = "2012-03-04T18:46:58-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14329#comments:id=1635155",
        },
        {
            id = 2497769,
            score = 4,
            author = "Kobzol",
            text = "Riiight, so you kill his three sons and then he orders you to find and save his daughter. Father of the year.",
            date = "2017-06-01T05:39:14-05:00",
            sourceUrl = "https://www.wowhead.com/quest=14329#comments:id=2497769",
        },
        {
            id = 5392129,
            score = 3,
            author = "rogermw",
            text = "KHAN: \"Let him leave peacefully, he's on a mission to save my daughter.\"\nADVISOR: \"How do you know you can trust him?\"\nKHAN: \"Well, he killed my sons.  If that doesn't make him trustworthy, I don't know what does!\"",
            date = "2022-07-04T11:36:50-05:00",
            sourceUrl = "https://www.wowhead.com/quest=14329#comments:id=5392129",
        },
    },
    [14330] = {
        {
            id = 1635151,
            score = 129,
            author = "sephyre",
            text = "I did this today, and it was not bugged, for those who are worried about that.\n\nAs it states, this quest chain starts by having https://www.wowhead.com/item=38567 drop from https://www.wowhead.com/npc=4656. However, there are some quests you have to do before it will drop.\n\nAssuming someone has not done any of the Desolace quests, this is what you need to do to unlock this quest chain:\n\nhttps://www.wowhead.com/npc=36060 in Karnum's Glade, Desolace (58.2, 50.0)\nhttps://www.wowhead.com/quest=14305\nhttps://www.wowhead.com/quest=14306\nhttps://www.wowhead.com/quest=14311\n\nhttps://www.wowhead.com/npc=36052 in Karnum's Glade\nhttps://www.wowhead.com/quest=14312 (you must turn this in to Khan Leh'Prah before you can pick up his second one)\nhttps://www.wowhead.com/quest=14316 Since the objectives are next to each other, you might as well do this and Khan Leh'Prah's follow up quest https://www.wowhead.com/quest=14314  at the same time.\n\nhttps://www.wowhead.com/npc=36056 Next to Garren Darkwind in Karnum's Glade\nhttps://www.wowhead.com/quest=14314\nhttps://www.wowhead.com/quest=14318 You will turn this in to https://www.wowhead.com/npc=36163\n\nhttps://www.wowhead.com/npc=36163 Magram Territory (71.6, 45.6), he shows up after you complete the objective for https://www.wowhead.com/quest=14318\nhttps://www.wowhead.com/quest=14325\nhttps://www.wowhead.com/quest=14327\n\nhttps://www.wowhead.com/npc=36056 in Karnum's Glade\nhttps://www.wowhead.com/quest=14328 This will be turned in to https://www.wowhead.com/npc=36185\n\nhttps://www.wowhead.com/npc=36185 He is inside the cave in the southern area of the Gelkis Village (40.4, 95.6)\nhttps://www.wowhead.com/quest=14329 Valley of Spears (32, 60.4)\nOnce you have this quest in your log https://www.wowhead.com/npc=4656 will drop https://www.wowhead.com/item=38567 which starts https://www.wowhead.com/quest=14330.\n\nEdit:\nIf you already completed the quest chain before this reputation change, then talk to https://www.wowhead.com/npc=36034 in Karnum's Glade, and he should grant you the reputation",
            date = "2012-03-04T18:32:46-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14330#comments:id=1635151",
        },
        {
            id = 2582335,
            score = 35,
            author = "Mitroden",
            text = "For those here after Neryssa's post (http://www.wowhead.com/news=285727/gelkis-magram-clan-centaur-reputation-changes-exalted-now-achievable) to get both Gelkis and Magram reputation to Exalted in 1 go during BFA Patch 8.01, here are some of my experiences:\n\nI ran Neryssa's scripts (i.e. Behind Closed Doors: /script print(IsQuestFlaggedCompleted(14330)) ) and found I hadn't completed any of the 4 final quests on the way to completing Death to Agogridon (http://www.wowhead.com/quest=14394).\n\nI followed sephyre's comments for Maraudine Prisoner Manifest (http://www.wowhead.com/item=38567/maraudine-prisoner-manifest#comments), and searched for any of the quests in the quest chain starting with A Time to Reap (http://www.wowhead.com/quest=14305/a-time-to-reap), but couldn't find any of the quests.\n\nI decided to see if I could run the script Neryssa gave, but with the quest ID's found in the URL on Wowhead - i.e. for A Time to Reap (http://www.wowhead.com/quest=14305/a-time-to-reap) this quest has an ID of 14305 seen in the Wowhead URL - something I never knew) I could track each quest to see what I had finished. Lo and behold I had finished the quest chain up to Not So Fast (http://www.wowhead.com/quest=14329/not-so-fast), probably in 2011 when doing Loremaster.\n\nI took a pot shot and went over to Maraudon where Maraudine Prisoner Manifest (http://www.wowhead.com/item=38567/maraudine-prisoner-manifest#comments) drops, and the manifesto dropped on the first kill of a Maraudine Mauler (http://www.wowhead.com/npc=4656/maraudine-mauler)!\n\nI finished up the last 4 quests killing Agogridon (http://www.wowhead.com/npc=36442/agogridon), handed in the quest Death to Agogridon (http://www.wowhead.com/quest=14394) and immediately dinged Exalted for both Gelkis and Magram reps! Happy days!\n\nGood luck peep! Lets hope blizzard doesn't recall this rep ;)",
            date = "2018-07-19T11:56:42-05:00",
            sourceUrl = "https://www.wowhead.com/quest=14330#comments:id=2582335",
        },
        {
            id = 3125639,
            score = 24,
            author = "antoniop23",
            text = "If you're unable to remember what or how many of these Desolace quests you may have done over times gone by, rather than going through each step outlined in other posts here, try starting off by talking to Karnum Marshweaver (57.5, 47.7) in Karnum's Glade. For me, simply right-clicking this NPC immediately put the Margram Clan and the Gelkis Clan factions to a full Exalted standing -- very nice!",
            date = "2019-06-06T13:10:14-05:00",
            sourceUrl = "https://www.wowhead.com/quest=14330#comments:id=3125639",
        },
        {
            id = 2582617,
            score = 12,
            author = "insectKR",
            text = "/run local q={14330,14332,14393,14394}for k,v in ipairs(q)do print(\"#\"..k,\"\\124cffFFFF00\\124Hquest:\"..v..\"\\124h[\"..v..\"]\\124h\\124r\",IsQuestFlaggedCompleted(v)and COMPLETE or INCOMPLETE)end",
            date = "2018-07-20T01:52:57-05:00",
            sourceUrl = "https://www.wowhead.com/quest=14330#comments:id=2582617",
        },
        {
            id = 5949012,
            score = 11,
            author = "Meemo",
            text = "If you're looking for the war within content.. you might want to start here  (sojourner of the isle of dorn)\n\n[quest=79530 domain=www]",
            date = "2024-09-07T08:25:46-05:00",
            sourceUrl = "https://www.wowhead.com/quest=14330#comments:id=5949012",
        },
    },
    [14332] = {
        {
