    [14333] = {
        {
            id = 1188204,
            score = 165,
            author = "466912",
            text = "You pick up this quest inside Maraudon but prior to entering the actual instance.  Found it while I was looking for the turn in to Behind Closed Doors (which is not completeable at this time).\n\nYou have to pick up 6 defiled relics.  These are scattered throughout the Maraudine camp just outside of Maraudon.  Once you have all 6 relics right click to destroy.",
            date = "2010-11-26T16:21:57-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14333#comments:id=1188204",
        },
        {
            id = 1184729,
            score = 62,
            author = "570312",
            text = "Go back out of the tunnels and they are up top within the Gelkis Camps, Remember you need 6 not 1 :D",
            date = "2010-11-25T11:44:56-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14333#comments:id=1184729",
        },
        {
            id = 2288691,
            score = 33,
            author = "1022676",
            text = "Next to the caged centaur, you will find a statue on a shelf that gives the quest. Free the centaur if you are on that quest and go back outside. Suddenly, on the ground outside the dungeon entrance and inside the centaur tents you will see shimmering statues lying on the ground. Collect 6 of them then right-click the stack in your bag.\n\n\"Job's done!\"",
            date = "2015-12-16T11:31:40-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14333#comments:id=2288691",
        },
        {
            id = 2588516,
            score = 26,
            author = "CaptainWater",
            text = "I got the Loremaster of Desolace achievement without completing this quest, so despite what Wowhead says this quest is not needed for the Loremaster achievement.",
            date = "2018-08-06T15:37:23-05:00",
            sourceUrl = "https://www.wowhead.com/quest=14333#comments:id=2588516",
