    [14334] = {
        {
            id = 5219095,
            score = 69,
            author = "EXPERIMENTONGOD",
            text = "As of 9.1/Chromie Time:\n\nYou HAVE to stand at the end of the pier for Blubbergut to spawn. It will NEVER spawn if you're in the air or in the water.\n\nIn other words, there's an invisible trigger that spawns Blubbergut and if you don't step in that area it doesn't spawn. I think the game assumes you will drop into the water running on the ground from the pier, but in Chromie Time you can go there flying and drop directly from the air to the water and that will NOT make it spawn.\n\nAs you will most likely be completely alone in the \"Chromie Time Desolace instance\" it's extremely unlikely that Blubbergut is already spawned because if another player stood at the end of the pier before you got there they most likely already killed it",
            date = "2021-07-11T15:49:54-05:00",
            sourceUrl = "https://www.wowhead.com/quest=14334#comments:id=5219095",
        },
        {
            id = 1185526,
            score = 66,
            author = "236466",
            text = "Patrols a complete loop that takes him close to the dock in Shadowprey Village near the surface of the water. He's on about a one minute respawn timer give or take.",
            date = "2010-11-25T17:29:50-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14334#comments:id=1185526",
        },
        {
            id = 1786198,
            score = 28,
            author = "tarc",
            text = "I was about ready to scream doing this just now.  I got on the pier, he spawns, I jump in and begin to kill. A few seconds in, Blubbergut just...dies, and I get no quest credit.  Tried again, same thing, and a few more times. Same.\n\nOn the next try I happen to barely notice a projectile before it dies, so I figure its some cross-faction d-baggery going on.  Log out, come back 10 mins later, try again same thing.\n\nThen I notice a https://www.wowhead.com/npc=51841 on the pier.\n\nWith a bow.\n\nHe \"helps\" you since you're being \"attacked\".\n\nSo, don't tap Blubbergut til you're out of the guard's range.",
            date = "2012-12-23T12:30:42-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14334#comments:id=1786198",
        },
        {
            id = 1670909,
            score = 16,
            author = "995499",
            text = "An 85 guardian just killed the damn thing! TWICE! (they seem to be handling the situation just fine!)",
            date = "2012-05-27T18:55:54-05:00",
            sourceUrl = "https://www.wowhead.com/quest=14334#comments:id=1670909",
        },
        {
            id = 1515568,
            score = 9,
            author = "800781",
            text = "This is definately the coolest underwater mob. It looks so nice.",
            date = "2011-09-11T14:23:05-05:00",
            sourceUrl = "https://www.wowhead.com/quest=14334#comments:id=1515568",
        },
    },
    [14335] = {
        {
            id = 1625138,
            score = 25,
            author = "DrAwkward",
            text = "Fish in a Bucket  (/script DEFAULT_CHAT_FRAME:AddMessage(\"\\124cffffff00\\124Hquest:5421:34\\124h[Fish in a Bucket) and Blubbergut (/script DEFAULT_CHAT_FRAME:AddMessage(\"\\124cffffff00\\124Hquest:14334:35\\124h[Blubbergut) are prerequisites to this quest.",
            date = "2012-02-11T22:16:09-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14335#comments:id=1625138",
        },
        {
            id = 1614080,
