        },
        {
            id = 3239119,
            score = -1,
            author = "Rayni",
            text = "Here is how to get to this quest .\n\nGo to the Maraudon entrance /way 29.47, 62.48\n\nClick the doors to enter and go down a bit. Can't really go a wrong way as there is only one way.\n\nIt is near the escort quest in the cage.",
            date = "2020-10-16T13:45:47-05:00",
            sourceUrl = "https://www.wowhead.com/quest=14335#comments:id=3239119",
