    [14337] = {
        {
            id = 1928240,
            score = 4,
            author = "1070257",
            text = "While you're in Shadowprey Village, sell your trash and see what the locals have for sale. https://www.wowhead.com/npc=12033 sells cooking supplies. If you don't already have them. You can pick up https://www.wowhead.com/item=21219, https://www.wowhead.com/item=17062, https://www.wowhead.com/item=6369, and https://www.wowhead.com/item=21099. Less than 1g for all 4 recipes.\nhttps://www.wowhead.com/npc=12045 sometimes sells (1) https://www.wowhead.com/item=12250 and (1) https://www.wowhead.com/item=12249 (it's not listed as an item she sells, but I have bought one from her).",
            date = "2013-12-22T08:04:28-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14337#comments:id=1928240",
        },
        {
            id = 2064935,
            score = 3,
            author = "Wyr3d",
            text = "Does not appear to be available currently, as of 6.0.3. As far as I can ascertain, there are no prerequisite quests, but the Karnum (http://www.wowhead.com/npc=36034) refused to give out this quest for my orc DK.\n\nI will check back again later, as there is one of two Cenarion quest available that I have not pickedup. Perhaps they might be hitherto unknown prerequistes?\n\nEDIT\n\nOkay, so I continued through the storyline, and this quest does not show up as available until after you have completed the quest My Word is My Bond (http://www.wowhead.com/quest=14327). You may need to have accepted the quest Three Princes (http://www.wowhead.com/quest=14328) also - it directly follws on from My Word is My Bond..",
            date = "2014-12-09T21:47:34-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14337#comments:id=2064935",
        },
    },
    [14338] = {
        {
            id = 1372571,
            score = 11,
            author = "Zoazta",
            text = "I was going for the https://www.wowhead.com/item=55922 and was not able to pic this quest from the quest giver. So I went and checked if https://www.wowhead.com/quest=14339 (second quest in chain) was avaible. And it was, so second quest is first in this chain. Because I have for sure not done any quests in Desolace.",
            date = "2011-03-21T11:05:40-05:00",
            sourceUrl = "https://www.wowhead.com/quest=14338#comments:id=1372571",
        },
        {
            id = 1767529,
            score = 10,
            author = "Jauque",
            text = "After I completed Taking Part (http://www.wowhead.com/quest=14311) this breadcrumb quest became available.  I do believe there are other quests you will need to complete from Botanist Ferrah (http://www.wowhead.com/npc=36060) first however, but I can confirm this quest is still active as of patch 5.0.5",
            date = "2012-11-25T05:54:42-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14338#comments:id=1767529",
