    [14339] = {
        {
            id = 1191477,
            score = 25,
            author = "ArgentSun",
            text = "Here is a map location for all of you who are having problems with the spawn rate: [48.2, 60.3]. I found a Dying Kodo here, and as soon as I killed it another one spawned. They kept respawning instantly until I killed something like 10-12 Dying Kodos - which was enough for my quest.",
            date = "2010-11-27T20:01:32-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14339#comments:id=1191477",
        },
        {
            id = 1910716,
            score = 14,
            author = "coolkingler1",
            text = "A fitting name for the mob type you need, these beasts are more elusive than the Ashes of Al'ar.\nTo add insult to injury, they don't always drop the horns.",
            date = "2013-10-21T10:06:51-05:00",
            sourceUrl = "https://www.wowhead.com/quest=14339#comments:id=1910716",
        },
        {
            id = 1191266,
            score = 8,
            author = "keltuk",
            text = "The droprate is indeed terrible (its 1 in 2-3 kills) compared to the ammount of dying kodo's that spawn.\nHowever clearing the area from ancient and aged kodo's does help the dying kodo respawns.",
            date = "2010-11-27T18:28:27-06:00",
