            author = "176334",
            text = "Who doesn't love macros? This one looks for a kodo of the appropriate name and marks it with a skull.\n\n/targetexact Dying Kodo\n/stopmacro [noexists][dead]\n/script SetRaidTargetIcon(\"target\",8)",
            date = "2012-07-02T22:53:02-05:00",
