    [14358] = {
        {
            id = 1880476,
            score = 6,
            author = "ghostiron",
            text = "after completing this quest it becomes repeatable (quest name changes to https://www.wowhead.com/quest=14359), the yellow exclamation mark will appear again over the object but only turning this quest (https://www.wowhead.com/quest=14358) counts towards https://www.wowhead.com/achievement=4930, not sure why it's not a blue question mark after completing it once like other repeatable quests",
            date = "2013-07-25T02:26:42-05:00",
            sourceUrl = "https://www.wowhead.com/quest=14358#comments:id=1880476",
        },
        {
            id = 1387996,
            score = 5,
            author = "733706",
            text = "The quest appears to be bugged in that once you collect the 10 pieces of flesh (ugh), the quest mobs still appear with red wording above them. When you get to the brazier at 78, 23 and click on the 10 pieces of flesh in your bags, a short animation appears and you get the yellow question mark. When you click on it to complete the quest, you get a yellow exclamanation point and the quest appears again, even though there was no previous indication that the quest was repeatable (no blue exclamation point).\n\nSo I accepted the quest again and went out and wacked mobs to get 10 more of the quest item.  They started to really thin out in that area. Got 10 more, turned them in and the yellow (not blue) exclamation point appeared again.",
            date = "2011-04-10T00:02:32-05:00",
            sourceUrl = "https://www.wowhead.com/quest=14358#comments:id=1387996",
        },
        {
            id = 1416841,
            score = 2,
            author = "StansDad",
            text = "I also wondered at first whether it was simply a bug, as the exclamation mark is as you say, not the usual blue colour indicating a repeatable quest.\nHowever, I believe it may be repeatable simply because the buff awarded (\"Divine Endowment\", a 15% increase in base health whislt in Desolace) is limited to one hour, so it can be renewed by doing this easy quest again.",
            date = "2011-05-12T13:01:50-05:00",
            sourceUrl = "https://www.wowhead.com/quest=14358#comments:id=1416841",
        },
        {
            id = 1674606,
            score = 1,
            author = "nectarine",
            text = "counts towards https://www.wowhead.com/achievement=4930",
            date = "2012-06-08T10:32:13-05:00",
            sourceUrl = "https://www.wowhead.com/quest=14358#comments:id=1674606",
        },
        {
            id = 1677070,
            score = 1,
            author = "768475",
            text = "Most likely a reference to Shylock from The Merchant of Venice by Shakespeare, who demands a pound of flesh from Antonio as a security for a loan.",
            date = "2012-06-15T20:21:23-05:00",
            sourceUrl = "https://www.wowhead.com/quest=14358#comments:id=1677070",
        },
    },
    [14359] = {
        {
            id = 1187150,
            score = 139,
            author = "671328",
            text = "Don't bother with this one if you're going for Loremaster. It's a repeatable (even though it's a yellow exclamation mark) and will not count for Desolace Quests.",
            date = "2010-11-26T08:41:35-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14359#comments:id=1187150",
        },
        {
            id = 1201840,
            score = 35,
            author = "20379",
            text = "Ten Pounds of Flesh (http://www.wowhead.com/quest=14358) is the quest that counts for Desolace Quests (http://www.wowhead.com/achievement=4930).\n\nThis quest does not count.  Ever.  The first quest the Brazier gives you is a totally different quest.  Both quests have the exact same objectives, but Blessings From Above is not the quest that you get when you first visit the Brazier.\n\nSanderZammy is 100% correct and should not be downranked.  Isshin is 100% incorrect and should be downranked.",
            date = "2010-12-02T07:50:17-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14359#comments:id=1201840",
        },
        {
            id = 1552465,
            score = 19,
            author = "503971",
            text = "This quest is a Repeatable quest.\n\nRepeatable quests are quests that can be completed more than once. It's possible that any experience or reputation rewards are only rewarded the first time this quest is completed, but nevertheless, completing this quest will not make it appear as completed in the Wowhead quest tracker, and it can therefore be safely excluded if you're a completionist.\n\nExamples of Repeatable quests:\n\nBuff quests.\nMost common example. You collect certain items that can be gathered even after completing the associated buff quest once. Turning them in may grant a buff. These quests are repeatable so that you can refresh the buff anytime, by completing the quest again.\nItem quests.\nUncommon. Quests that reward you an item which, for example, is required in another quest. Sometimes these quests are repeatable so that you can get more of these items if necessary.",
            date = "2011-10-24T09:43:15-05:00",
            sourceUrl = "https://www.wowhead.com/quest=14359#comments:id=1552465",
        },
        {
            id = 1866490,
            score = 19,
            author = "wilosoft",
            text = "This quest must be fixed, it must turn blue once it's completed for the first time!",
            date = "2013-06-14T05:57:31-05:00",
            sourceUrl = "https://www.wowhead.com/quest=14359#comments:id=1866490",
        },
        {
            id = 1495527,
            score = 4,
            author = "855181",
            text = "So right or wrong  - this quest is a waste of time.\nBlizzard should fix it (perhaps)?\n\nGood place to practice new macros though",
            date = "2011-08-15T11:22:03-05:00",
            sourceUrl = "https://www.wowhead.com/quest=14359#comments:id=1495527",
        },
    },
    [14360] = {
