    [14364] = {
        {
            id = 1229610,
            score = 28,
            author = "628651",
            text = "If you somehow forget to accept this quest on completion of You'll Know when you see it (http://www.wowhead.com/quest=14363), like i did, then in order to retake it you must travel back to Nigels Point, the Captain will have it there, for some reason it took me sometime to work out lol",
            date = "2010-12-13T04:24:58-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14364#comments:id=1229610",
        },
        {
            id = 1184940,
            score = 9,
            author = "Ripture",
            text = "The skulls are looted from piles located at Thunder Axe Fortress.  There are also many piles within the summoning room (the eastern-most building).",
            date = "2010-11-25T13:23:41-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14364#comments:id=1184940",
        },
        {
            id = 2018579,
            score = 7,
            author = "emeraldenvy",
            text = "I had an issue with this quest getting Nazargen to spawn. After recollecting the skulls I discovered if you are standing inside the circle when you use your skulls he won't spawn. When I stood just outside the pit, I was able to summon Nazargen.",
            date = "2014-10-24T19:02:56-05:00",
            sourceUrl = "https://www.wowhead.com/quest=14364#comments:id=2018579",
        },
        {
            id = 1645184,
            score = 4,
            author = "Creaky",
            text = "The biggest building, the central building is indeed the one you want to head to. Not only best spot for collecting the skulls, but also the spot where you summon the demon.\n\nThough who the hell would try to work against demons by summoning a demon? What if it would of summoned some Demon Lord? I would of $%^&ted my pants then! >.>",
            date = "2012-03-27T02:43:46-05:00",
            sourceUrl = "https://www.wowhead.com/quest=14364#comments:id=1645184",
        },
        {
            id = 2093894,
            score = 4,
            author = "Random0532",
            text = "To complete this quest, do the following:\n\nCollect 100 https://www.wowhead.com/item=48953s from the https://www.wowhead.com/object=195535s.\nGo to the big building at 55, 26 (map (http://www.wowhead.com/maps?data=405:550266)).\nGo to the Summoning Circle in the middle of the building and click on your https://www.wowhead.com/item=48953s (https://www.wowhead.com/spell=67829).\nhttps://www.wowhead.com/npc=35647 will be summoned. Kill him.",
            date = "2015-01-24T11:15:02-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14364#comments:id=2093894",
        },
    },
    [14365] = {
        {
            id = 1206714,
            score = 25,
            author = "718527",
            text = "This quest opend up only after finishing Lay of the Land (http://www.wowhead.com/quest=14387) and Elune's Gifts (http://www.wowhead.com/quest=14354), which in turn opened up after Rerouted! (http://www.wowhead.com/quest=14384) from Officer Jankie (http://www.wowhead.com/npc=36410).",
            date = "2010-12-04T18:54:32-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14365#comments:id=1206714",
        },
        {
            id = 1911531,
            score = 1,
            author = "legionfalls",
            text = "For some reason this NPC was not speaking to me, even though the WoW \"?\" was on the map. I tried to figure out what was the problem, only to come up empty. At a last ditch effort, I went to get my Cenarion Circle rep up, from neutral to friendly. Took one clear of AQ20, came back and suddenly this NPC wanted to speak to me.\n\nSo if you can't  turn in your quest, try this. Worked for me.",
            date = "2013-10-24T01:16:31-05:00",
            sourceUrl = "https://www.wowhead.com/quest=14365#comments:id=1911531",
        },
        {
            id = 2552370,
