            date = "2018-02-13T01:41:05-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14365#comments:id=2552370",
        },
    },
    [14370] = {
        {
            id = 1188148,
            score = 10,
            author = "Ca1ypso",
            text = "The azsharite samples have a couple different looks. One looks like crystals sticking up out of the ground. The other looks like a person turned into crystal (I have seen troll and human forms, but other races may be frozen as well). Either of these forms counts as a sample.\n\nAfter completing the quest line you find out that the azsharite samples are really Giant droppings. Which brings to mind the question why some of the droppings look like frozen people?",
            date = "2010-11-26T16:03:26-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14370#comments:id=1188148",
        },
        {
            id = 1707711,
            score = 7,
            author = "Emarelda",
            text = "The Crystallized Note you may find reads this:\n\n'To Whom It May Concern:\n\nIf you are reading this note, then you are in one of two places:\n\n(1) On the southern peninsula of Azshara.\n\n(2) Inside the belly of a Cliff Giant.\n\nBoth are equally undesirable.\n\nIt should be noted that I was the former at one time and as of the writing of thise note, the latter.\n\nPAGE TWO\n\nBeing inside the belly of a giant gives one time for reflection.\n\nAs my body slowly crystallizes, I recall my days in Eversong, contemplating a life of adventure on the savage frontiers across the great sea. I was young. And stupid. If I somehow get out of here, I'm taking up gardening or whittling instead.\n\n- Windan Shay'\n\nI thought this would interest some people. I keep this note in my bank for keepsakes.",
            date = "2012-09-01T17:35:02-05:00",
            sourceUrl = "https://www.wowhead.com/quest=14370#comments:id=1707711",
        },
        {
            id = 1361586,
            score = 5,
            author = "148897",
            text = "I'm not sure if this has been said anywhere else but the entire quest line hints at it and throws little jokes in about what Azsharite really is. When you are escorting the hot Azsharite, the giant, Gormungan, comments on what a load you have there. Assistant Greely says she will be up to her neck in it. There are more but I've forgotten what they were. I think the Blizz devs might have been running low on ideas considering the number of excrement related quests and jokes in Cata.",
            date = "2011-03-08T18:17:16-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14370#comments:id=1361586",
        },
        {
            id = 1356661,
            score = 3,
            author = "ankorafeonix",
            text = "I had the most luck following the top of the southern cliffs while killing the Mistwing Cliffdwellers.",
            date = "2011-03-03T19:21:37-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14370#comments:id=1356661",
        },
        {
            id = 1317181,
            score = 2,
            author = "777519",
            text = "i didnt get any notes when i did the quest, but if you read the quests, it tells you whats the haps",
            date = "2011-01-31T15:34:46-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14370#comments:id=1317181",
        },
    },
