    [14381] = {
        {
            id = 1190137,
            score = 39,
            author = "661924",
            text = "For the ones that like me went straight to the fissure tying to show those nagas how awesome we are... it's a bombardment quest, just use the hypogriph behind the quest giver instead of wandering why you don't have the concoction.",
            date = "2010-11-27T10:10:42-06:00",
