    [14388] = {
        {
            id = 1180471,
            score = 201,
            author = "h44mm00",
            text = "Just for those who don't read quest text like me the first time:\n\n\"... Mount a Rocketway Rat...\"\n\nWhen not mounted on a rat you move very slowly (takes about 3 minutes to get to the giant which is about 20 metres). It was frustrating, then I actually read the quest properly. D:",
            date = "2010-11-24T06:25:11-06:00",
