    [14389] = {
        {
            id = 2511118,
            score = 38,
            author = "Wonderbreadd",
            text = "Joanna will be at the top of the tower for a player who's done the Legion artifact upgrade quests involving Archmage Xylem, but the portal to the spirit realm/location of Azuregos isn't behind her it's down at the bottom of the tower where her original location was.",
            date = "2017-07-30T17:25:16-05:00",
            sourceUrl = "https://www.wowhead.com/quest=14389#comments:id=2511118",
        },
        {
            id = 1195214,
            score = 15,
            author = "Fondling",
            text = "The death must be scripted in, even after casting Levitate you still die when you contact the ground.  An interesting tidbit, if you simply jump off the cliff and land in the area where Azuregos is you won't take even 1hp of fall damage.",
            date = "2010-11-29T08:10:06-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14389#comments:id=1195214",
        },
        {
            id = 1208804,
            score = 14,
            author = "anhsieh",
            text = "Oh boy, this is a beautiful quest. I love the dialogue between Azuregos and the player.\n\n\"I know, I know, it could never work out ... a Dragon and a Spirit Healer.\"",
            date = "2010-12-05T17:52:05-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14389#comments:id=1208804",
        },
        {
            id = 1179897,
            score = 10,
            author = "420211",
            text = "This is part of a quest chain in which the player aids Kalecgos (the new blue dragon aspect) in finding Azuregos and protecting him from the black dragonflight. It spans much of the land of Azshara and is composed of many quests, several of which are completely original in their concepts.\n\n1.)Azshara Blues (http://www.wowhead.com/quest=14407)\n2.)Friends Come In All Colors (http://www.wowhead.com/quest=14130)\n\nHelping out Ergll:\n3.)A Little Pick-me-up (http://www.wowhead.com/quest=14131)\n4.)Absorbent (http://www.wowhead.com/quest=14323)\n---5.)Full of Hot Water (http://www.wowhead.com/quest=14324)\n6.)That's Just Rude! (http://www.wowhead.com/quest=14132)\n\nFinding Archmage Xylem:\n7.)The Way to a Mage's Heart (http://www.wowhead.com/quest=14133)\n8.)Wash Out (http://www.wowhead.com/quest=14345)\n9.)Dressed to Impress (http://www.wowhead.com/quest=14340)\n\nHelping Xylem and his Apprentices:\n10.)Shear Will (http://www.wowhead.com/quest=14249)\n11.)Waste of Thyme (http://www.wowhead.com/quest=14263)\n12.)Renewable Resource (http://www.wowhead.com/quest=14250)\n\n13.)Manual Labor (http://www.wowhead.com/quest=14230)\n14.)Trouble Under Foot (http://www.wowhead.com/quest=14226)\n\nGetting to Xylem's Trials\n15.)The Pinnacle of Learning (http://www.wowhead.com/quest=14413)\n16.)Watch Your Step (http://www.wowhead.com/quest=14296)\n\nXylem's Trials\n17.)The Trial of Fire (http://www.wowhead.com/quest=14300)\n---Achievement: Glutton for Fiery Punishment (http://www.wowhead.com/achievement=5448)\n18.)The Trial of Frost (http://www.wowhead.com/quest=24478)\n---Achievement: Glutton for Icy Punishment (http://www.wowhead.com/achievement=5546)\n19.)The Trial of Shadow (http://www.wowhead.com/quest=24479)\n---Achievement: Glutton for Shadowy Punishment (http://www.wowhead.com/achievement=5547)\n\nFinding Azuregos\n20.)Xylem's Asylum (http://www.wowhead.com/quest=14299)\n21.)Wasn't it Obvious?\n22.)Easy is Boring (http://www.wowhead.com/quest=14390)\n23.)Turning the Tables (http://www.wowhead.com/quest=14391)\n\nThe Final Battle\n24.)Fade to Black (http://www.wowhead.com/quest=24467)",
            date = "2010-11-24T01:33:55-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14389#comments:id=1179897",
        },
        {
            id = 1632072,
            score = 10,
            author = "taimi",
            text = "Of interest to anyone attempting to level without dying - your transition to the spirit world in this quest (via falling to your death!) is entirely scripted and does not count as a death in the statistics so the quest is safe to do.",
            date = "2012-02-26T13:26:03-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14389#comments:id=1632072",
        },
    },
    [14390] = {
        {
            id = 1186481,
            score = 53,
            author = "684218",
            text = "You:\nKalecgos sent me...\n\nAzuregos:\nKalecgos? That's your good foot forward?\n\nGood luck with that one, buddy.\n\nYou:\nNo no no, you don't understand. I'm here to help.\n\nAzuregos:\nOf course you are. Here to save big blue from himself, spending all his time in the spirit world, obsessing over magical artifacts. Kalec doesn't understand, though. I've turned a new leaf.\n\nI've met someone.\n\nYou:\nMet someone? I didn't know there were any other dragons out here.\n\nAzuregos:\nA dragon? Hah! Don't be ridiculous.\n\nYou know , you're awfully rude. She's standing right here!\n\nYou:\n...the spirit healer?\n\nAzuregos:\nShe has a name, you know. Anara. You'd do well to treat her with the respect she deserves.\n\nHow many times have she and her sisters brought you back from the grip of death itself? You're just all kinds of inconsiderate, aren't you?\n\nYou:\nI'm sorry, I didn't mean to be rude, I just...\n\nAzuregos:\nI know. I KNOW. We could never be, right? Dragon and Spirit Healer...two different worlds! Not to mention the physiological problems.\n\nBut you're wrong. We have a deeper connection than that. Anara and I, we're involved.\n\nBesides, I kind of like it here. No adventurers to poke and prod me with no provocation.\n\nYou:\nThat's not what I was saying at all.\n\nAzuregos:\nWell get to it then. You're the one veering off onto all these unnecessary topics.\n\nYou:\nI'm the...forget it. I'm here to warn you that the black dragonflight is here hunting you.\n\nAzuregos:\nOh. That? Thought I hadn't noticed the scorched earth and senseless slaughter that usually give them away? I'm not THAT old.\n\nYou:\nYou already knew? Why don't you go stop them then?\n\nAzuregos:\nWhy bother? It's not like they actually have even the slightest clue where I am. They're not going to do any harm to the already-found artifacts around here.\n\nAnyway, one of the amusingly convenient things about evil and destruction is that they tend to just evilly destruct each other eventually.\n\nYou:\nBut Kalecgos is already out there trying to stop them. He needs your help.\n\nAzuregos:\nHe's going after them? And he sent you to ask me for help? Was there begging? Were there tears?\n\nYou know, if I came to his rescue, there's no way he could ever live it down. Maybe he'd make me one of those little Sunwell girls of my very own.\n\nNo offense, Anara.\n\nYou:\nYou'll come then?\n\nAzuregos:\nYeah yeah, I'll come to his rescue.\n\nDon't you fall into his little center-of-the-world hero bit though! He just likes the attention. I swear, he thinks he's going to be the next Aspect. It's laughable.\n\nYou:\nI'm going to let him know right away. Meet us at Sable Ridge.\n\nAzuregos:\nYeah yeah. I'm on my way. Don't get your chain  panties in a bunch.",
            date = "2010-11-26T01:50:08-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14390#comments:id=1186481",
        },
        {
            id = 1422818,
            score = 38,
            author = "717646",
            text = "The conversation is hilarious. Never would've seen the day of a full-grown dragon and a spirit healer having a relationship.",
            date = "2011-05-19T20:58:08-05:00",
            sourceUrl = "https://www.wowhead.com/quest=14390#comments:id=1422818",
        },
        {
            id = 1215950,
            score = 17,
            author = "40952",
            text = "You'll turn in the quest 'Wasn't it Obvious?' to Anara, the guardian spirit. She will then give you this quest, 'Easy is Boring', which must be completed while you're still a ghost. You can complete 'Easy is Boring' by speaking with the Spirit of Azuregos, who is standing to the right of Anara.\n\nIf you accidentally talk to Anara and have her restore you to life before completing 'Easy is Boring', you'll have to ascend Xylem's tower and go back through the portal in order to \"die\" again.",
            date = "2010-12-08T18:56:17-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14390#comments:id=1215950",
        },
        {
            id = 1197786,
            score = 13,
            author = "Balgair",
            text = "So, I'm curious - as a lowbie goblin (troll/orc/whoever) who's quite clearly never been to Northrend or Sunwell Isle... how exactly do I know that this strange blue-haired human named Kalec is really a dragon called Kalecgos? Seems I know it by the time I talk to Azuregos, but I've no idea how I came by that bit of information! Unless I missed something along the chain somewhere?",
            date = "2010-11-30T12:22:11-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14390#comments:id=1197786",
        },
        {
            id = 1179898,
            score = 10,
            author = "420211",
            text = "This is part of a quest chain in which the player aids Kalecgos (the new blue dragon aspect) in finding Azuregos and protecting him from the black dragonflight. It spans much of the land of Azshara and is composed of many quests, several of which are completely original in their concepts.\n\n1.)Azshara Blues (http://www.wowhead.com/quest=14407)\n2.)Friends Come In All Colors (http://www.wowhead.com/quest=14130)\n\nHelping out Ergll:\n3.)A Little Pick-me-up (http://www.wowhead.com/quest=14131)\n4.)Absorbent (http://www.wowhead.com/quest=14323)\n---5.)Full of Hot Water (http://www.wowhead.com/quest=14324)\n6.)That's Just Rude! (http://www.wowhead.com/quest=14132)\n\nFinding Archmage Xylem:\n7.)The Way to a Mage's Heart (http://www.wowhead.com/quest=14133)\n8.)Wash Out (http://www.wowhead.com/quest=14345)\n9.)Dressed to Impress (http://www.wowhead.com/quest=14340)\n\nHelping Xylem and his Apprentices:\n10.)Shear Will (http://www.wowhead.com/quest=14249)\n11.)Waste of Thyme (http://www.wowhead.com/quest=14263)\n12.)Renewable Resource (http://www.wowhead.com/quest=14250)\n\n13.)Manual Labor (http://www.wowhead.com/quest=14230)\n14.)Trouble Under Foot (http://www.wowhead.com/quest=14226)\n\nGetting to Xylem's Trials\n15.)The Pinnacle of Learning (http://www.wowhead.com/quest=14413)\n16.)Watch Your Step (http://www.wowhead.com/quest=14296)\n\nXylem's Trials\n17.)The Trial of Fire (http://www.wowhead.com/quest=14300)\n---Achievement: Glutton for Fiery Punishment (http://www.wowhead.com/achievement=5448)\n18.)The Trial of Frost (http://www.wowhead.com/quest=24478)\n---Achievement: Glutton for Icy Punishment (http://www.wowhead.com/achievement=5546)\n19.)The Trial of Shadow (http://www.wowhead.com/quest=24479)\n---Achievement: Glutton for Shadowy Punishment (http://www.wowhead.com/achievement=5547)\n\nFinding Azuregos\n20.)Xylem's Asylum (http://www.wowhead.com/quest=14299)\n21.)Wasn't It Obvious? (http://www.wowhead.com/quest=14389)\n22.)Easy is Boring\n23.)Turning the Tables (http://www.wowhead.com/quest=14391)\n\nThe Final Battle\n24.)Fade to Black (http://www.wowhead.com/quest=24467)",
            date = "2010-11-24T01:34:13-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14390#comments:id=1179898",
        },
    },
    [14391] = {
        {
            id = 1201812,
            score = 17,
            author = "716301",
            text = "Just take the portal to his retreat, then the portal to the Arcane Pinnacle. After that you activate the frost portal, go there and just drop down the ledge. Very close.",
            date = "2010-12-02T07:31:19-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14391#comments:id=1201812",
        },
        {
            id = 1179899,
            score = 16,
            author = "420211",
            text = "This is part of a quest chain in which the player aids Kalecgos (the new blue dragon aspect) in finding Azuregos and protecting him from the black dragonflight. It spans much of the land of Azshara and is composed of many quests, several of which are completely original in their concepts.\n\n1.)Azshara Blues (http://www.wowhead.com/quest=14407)\n2.)Friends Come In All Colors (http://www.wowhead.com/quest=14130)\n\nHelping out Ergll:\n3.)A Little Pick-me-up (http://www.wowhead.com/quest=14131)\n4.)Absorbent (http://www.wowhead.com/quest=14323)\n---5.)Full of Hot Water (http://www.wowhead.com/quest=14324)\n6.)That's Just Rude! (http://www.wowhead.com/quest=14132)\n\nFinding Archmage Xylem:\n7.)The Way to a Mage's Heart (http://www.wowhead.com/quest=14133)\n8.)Wash Out (http://www.wowhead.com/quest=14345)\n9.)Dressed to Impress (http://www.wowhead.com/quest=14340)\n\nHelping Xylem and his Apprentices:\n10.)Shear Will (http://www.wowhead.com/quest=14249)\n11.)Waste of Thyme (http://www.wowhead.com/quest=14263)\n12.)Renewable Resource (http://www.wowhead.com/quest=14250)\n\n13.)Manual Labor (http://www.wowhead.com/quest=14230)\n14.)Trouble Under Foot (http://www.wowhead.com/quest=14226)\n\nGetting to Xylem's Trials\n15.)The Pinnacle of Learning (http://www.wowhead.com/quest=14413)\n16.)Watch Your Step (http://www.wowhead.com/quest=14296)\n\nXylem's Trials\n17.)The Trial of Fire (http://www.wowhead.com/quest=14300)\n---Achievement: Glutton for Fiery Punishment (http://www.wowhead.com/achievement=5448)\n18.)The Trial of Frost (http://www.wowhead.com/quest=24478)\n---Achievement: Glutton for Icy Punishment (http://www.wowhead.com/achievement=5546)\n19.)The Trial of Shadow (http://www.wowhead.com/quest=24479)\n---Achievement: Glutton for Shadowy Punishment (http://www.wowhead.com/achievement=5547)\n\nFinding Azuregos\n20.)Xylem's Asylum (http://www.wowhead.com/quest=14299)\n21.)Wasn't It Obvious? (http://www.wowhead.com/quest=14389)\n22.)Easy is Boring (http://www.wowhead.com/quest=14390)\n23.)Turning the Tables\n\nThe Final Battle\n24.)Fade to Black (http://www.wowhead.com/quest=24467)",
            date = "2010-11-24T01:34:30-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14391#comments:id=1179899",
        },
        {
            id = 1196905,
            score = 7,
            author = "449883",
            text = "Despite what the quest says, it's not necessary to talk to Anara. During this quest you are not, in fact, dead - the phasing mechanic merely makes it look like death. Simply running far away enough will put you back into the main, \"living\" phase.",
            date = "2010-11-30T01:11:37-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14391#comments:id=1196905",
        },
        {
            id = 1704826,
            score = 7,
            author = "1025314",
            text = "Interestingly enough, if you talk to Anara and 'return' to the land of the living, you'll find your original body where you landed and 'died'. You're now a clone of yourself.",
            date = "2012-08-27T03:42:26-05:00",
            sourceUrl = "https://www.wowhead.com/quest=14391#comments:id=1704826",
        },
        {
            id = 1184779,
            score = 6,
            author = "139938",
            text = "After you talk to Anara to resurrect, head south to the Gallywix Rocketway Exchange, then take the trip to the Northern Rocketway Terminus.",
            date = "2010-11-25T12:10:14-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14391#comments:id=1184779",
        },
    },
    [14392] = {
        {
            id = 1359061,
            score = 178,
            author = "Vylyss",
            text = "If you are having troubles getting this quest (Azuregos is still flying above the sky, not lying on the ground next to Bitter Reaches goblin rocket tower) and you are max level player (or close), and you did complete other goblin quests at the tower, you probably did Fade to Black (http://www.wowhead.com/quest=24467) killing Malicion in \"normal\" way. All you have to do is repeating the whole event (even if you turned the quest to Kalec):\n\nwait for Twilight Lord Katrana and Malicion to respawn\nengade Katrana and let Malicion to fly up\nkill Katrana\nwait for Malicion to grab you into the air and watch the show. :)\n\nThen, when you come back to goblin tower, Azuregos should wait for you to hand you new quest. Enjoy!",
            date = "2011-03-06T08:27:47-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14392#comments:id=1359061",
        },
        {
            id = 2009635,
            score = 156,
            author = "Aydwen",
            text = "If you are looking to get the Faded Wizard Hat for your Toy Box come 6.0 then you are in for more than you probably thought. It takes a 24 quest long chain plus 2 other quests to get the quest to obtain this item. But it took me less than an hour to complete all 24 + 2 other quests and finally Farewell, Minnow so don't fret. This is a Horde only quest chain.\n\n1.)Azshara Blues (https://www.wowhead.com/quest=14407)\n2.)Friends Come In All Colors (http://www.wowhead.com/quest=14130)\n\nHelping out Ergll:\n3.)A Little Pick-me-up (http://www.wowhead.com/quest=14131)\n4.)Absorbent (http://www.wowhead.com/quest=14323)\n---5.)Full of Hot Water (http://www.wowhead.com/quest=14324)\n6.)That's Just Rude! (http://www.wowhead.com/quest=14132)\n\nFinding Archmage Xylem:\n7.)The Way to a Mage's Heart (http://www.wowhead.com/quest=14133)\n8.)Wash Out (http://www.wowhead.com/quest=14345)\n9.)Dressed to Impress (http://www.wowhead.com/quest=14340)\n\nHelping Xylem and his Apprentices:\n10.)Shear Will (http://www.wowhead.com/quest=14249)\n11.)Waste of Thyme (http://www.wowhead.com/quest=14263)\n12.)Renewable Resource (http://www.wowhead.com/quest=14250)\n\n13.)Manual Labor (http://www.wowhead.com/quest=14230)\n14.)Trouble Under Foot (http://www.wowhead.com/quest=14226)\n\nGetting to Xylem's Trials\n15.)The Pinnacle of Learning (http://www.wowhead.com/quest=14413)\n16.)Watch Your Step (http://www.wowhead.com/quest=14296)\n\nXylem's Trials\n17.)The Trial of Fire (http://www.wowhead.com/quest=14300)\n---Achievement: Glutton for Fiery Punishment (http://www.wowhead.com/achievement=5448)\n18.)The Trial of Frost (http://www.wowhead.com/quest=24478)\n---Achievement: Glutton for Icy Punishment (http://www.wowhead.com/achievement=5546)\n19.)The Trial of Shadow (http://www.wowhead.com/quest=24479)\n---Achievement: Glutton for Shadowy Punishment (http://www.wowhead.com/achievement=5547)\n\nFinding Azuregos\n20.)Xylem's Asylum (http://www.wowhead.com/quest=14299)\n21.)Wasn't It Obvious? (http://www.wowhead.com/quest=14389)\n22.)Easy is Boring (http://www.wowhead.com/quest=14390)\n23.)Turning the Tables (http://www.wowhead.com/quest=14391)\n\nThe Final Battle\n24.)Fade to Black (http://www.wowhead.com/quest=24467)\n\nWhen you turn in Fade to Black there is 2 quests you can see in your mini map. Complete them and then see Azuregos for Farewell, Minnow. The 2 quests are Ice Cold and Pro-liberation.\n\nShout-out to Ch3wy for getting together all the original info. I added a bit of information that was necessary to avoid confusion in finding 2 quests that must also be done to get this achieve that were not listed in the original post. My apologies for not having links like the original post, I am unaware of how to do so.",
            date = "2014-10-03T23:22:00-05:00",
            sourceUrl = "https://www.wowhead.com/quest=14392#comments:id=2009635",
        },
        {
            id = 1175700,
            score = 117,
            author = "607323",
            text = "Likely, a nice throwback to the Shifting Sands Quest where Azuregos put the Blue shard in a minnow.\n\n\"Ok, let me get this straight. You put the scepter entrusted to your Flight by Anachronos on a minnow of your own making and now you expect me to build an... an arcanite buoy or something... to force your minnow out of hiding? AND potentially incur the wrath of an Elemental Lord? Did I miss anything? Perhaps I am to do this without any clothes on, during a solar eclipse, on a leap year?\"\n\n\"If I did not know better I would think that you were mocking me, mortal; but yes, that is mostly correct. You may remain fully clothed.\"",
            date = "2010-11-20T04:34:48-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14392#comments:id=1175700",
        },
        {
            id = 1183731,
            score = 72,
            author = "Powersupply",
            text = "So I did the whole quest chain to get this hat, but after I finished up he wasn't offering the quest to me? What's the problem, is it glitched?\n\nEDIT: Okay, to get the Farewell Minnow quest from Azuregos, you must complete the two quests from the two goblins to the East.\n\nPro-Liberation\n[quest=14297 domain=www]\n\nIce Cold\n[quest=14261 domain=www]",
            date = "2010-11-25T03:18:19-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14392#comments:id=1183731",
        },
        {
            id = 1198233,
            score = 56,
            author = "265233",
            text = "Not to be the ever-hated Grammar-Nazi, buuuuut....\"throws of love\"? Unless Azuregos likes to toss his women around, I think he means \"throes of love'",
            date = "2010-11-30T15:43:19-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14392#comments:id=1198233",
        },
    },
    [14393] = {
        {
            id = 1417313,
            score = 56,
            author = "831607",
            text = "I didn't realize you could have a centaur vehicle, so I just killed mobs on my own. The Doomguards were pretty tough on my level 37 warrior - I was at almost 0 health after killing them with the help of the NPCs. Didn't even try to engage one by myself.",
            date = "2011-05-12T23:17:57-05:00",
            sourceUrl = "https://www.wowhead.com/quest=14393#comments:id=1417313",
        },
        {
            id = 1509624,
            score = 21,
            author = "bigearlx",
            text = "Buttons 2 and 6 don't appear to do anything. Well, button 2 makes a hunter's mark on your target and taunts it to attack you, but it doesn't appear to affect the behavior of your squad at all. They attack what and when they feel like. Button 3 is the only button that appears to work as you'd expect, and is absolutely essential if you want to get any utility out of your squad at all. Button 4 does work (although it's a very weak heal, maybe 5% of your health), until your caster inevitably gets herself killed that is. As I said, button 6 does absolutely nothing - no replacement NPCs, that's it, enjoy your death and corpse run, DIAS.",
            date = "2011-09-03T17:24:11-05:00",
            sourceUrl = "https://www.wowhead.com/quest=14393#comments:id=1509624",
        },
        {
            id = 2518378,
            score = 6,
            author = "Zuljid",
            text = "When you dismount after killing your enemies, your troops will die for no seemingly reason.\n\nTalk about abandonment issues!",
            date = "2017-09-02T09:13:13-05:00",
            sourceUrl = "https://www.wowhead.com/quest=14393#comments:id=2518378",
        },
        {
            id = 1186495,
            score = 5,
            author = "caramelle10",
            text = "Pretty straightforward...Use action number 2 to send in your group of centaurs on a target then press action 1 to throw a spear at them till they die.  The mobs are all around you.  Apparently there is no specific place for the priestess to spawn, but i found her wandering around the middle camp.  Shes a bigish demon walking around.  Being a hunter i tracked demons and found her quite well.  Hope this helps :)",
            date = "2010-11-26T01:56:35-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14393#comments:id=1186495",
        },
        {
            id = 1195995,
            score = 5,
            author = "Gambolputty",
            text = "After accepting the quest, speak to Leh'Prah again. He will give you the option to ride with the centaur into battle. If you take it, you will mount a centaur commander and get three centaur soldiers; 2 warriors and a caster.\n\nYour action bar has the following options:\n1 - Throw (Throw your weapon at an enemy, inflicting 300% of normal weapon damage)\n2 - Attack Order (Orders your centaur units to attack the target)\n3 - Return Order (Orders your centaur units to leave combat)\n4 - Request Healing (Orders your centaur casters to heal you)\n6 - Call for Reinforcements (Calls for aditional centaur units to assist you in battle)",
            date = "2010-11-29T15:27:44-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14393#comments:id=1195995",
        },
    },
    [14394] = {
        {
            id = 2582397,
            score = 116,
            author = "Kohtlyr",
            text = "If you'd going back as a high level toon to do this quest make sure you do not insta-kill him. Wait for the event to play out and reinforcements to arrive and have their conversation otherwise the quest glitches out and you cannot hand your quest in.\n\nIf you do insta-kill you'll either have to restart the quest or, wait until someone else kills him slowly then the quest giver will appear for you.",
            date = "2018-07-19T15:11:13-05:00",
            sourceUrl = "https://www.wowhead.com/quest=14394#comments:id=2582397",
        },
        {
            id = 1201767,
            score = 115,
            author = "414797",
            text = "So, end result of this chain...\n\nThanks to the actions of the Cenarion Circle and Horde/Alliance mercenaries, you have united the Kolkar, Magram and Gelkis Clans into a single Centaur Clan led by the three Khans.\n\n... It's at this point you realise that they never agreed to actually serve the Horde or Alliance and now have their land back, with renewed vigour.\n\n... Then you remember that they nearly wiped out the Tauren years ago and still constantly attack Horde and Alliance holdings in Kalimdor.\n\nNice job breaking it, hero. (http://tvtropes.org/pmwiki/pmwiki.php/Main/NiceJobBreakingItHero)",
            date = "2010-12-02T06:52:19-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14394#comments:id=1201767",
        },
        {
            id = 1635158,
            score = 91,
            author = "sephyre",
            text = "I posted this on the first quest of this chain, but just in case people want to know how to get these items from the beginning, here is a list of the prerequisite quest chains:\n\nHere is a list of prerequisite quests:\n\nAssuming someone has not done any of the Desolace quests, this is what you need to do to unlock this quest chain:\n\nhttps://www.wowhead.com/npc=36060 in Karnum's Glade, Desolace (58.2, 50.0)\nhttps://www.wowhead.com/quest=14305\nhttps://www.wowhead.com/quest=14306\nhttps://www.wowhead.com/quest=14311\n\nhttps://www.wowhead.com/npc=36052 in Karnum's Glade\nhttps://www.wowhead.com/quest=14312 (you must turn this in to Khan Leh'Prah before you can pick up his second one)\nhttps://www.wowhead.com/quest=14316 Since the objectives are next to each other, you might as well do this and Khan Leh'Prah's follow up quest https://www.wowhead.com/quest=14314  at the same time.\n\nhttps://www.wowhead.com/npc=36056 Next to Garren Darkwind in Karnum's Glade\nhttps://www.wowhead.com/quest=14314\nhttps://www.wowhead.com/quest=14318 You will turn this in to https://www.wowhead.com/npc=36163\n\nhttps://www.wowhead.com/npc=36163 Magram Territory (71.6, 45.6), he shows up after you complete the objective for https://www.wowhead.com/quest=14318\nhttps://www.wowhead.com/quest=14325\nhttps://www.wowhead.com/quest=14327\n\nhttps://www.wowhead.com/npc=36056 in Karnum's Glade\nhttps://www.wowhead.com/quest=14328 This will be turned in to https://www.wowhead.com/npc=36185\n\nhttps://www.wowhead.com/npc=36185 He is inside the cave in the southern area of the Gelkis Village (40.4, 95.6)\nhttps://www.wowhead.com/quest=14329 Valley of Spears (32, 60.4)\nThis quest will allow https://www.wowhead.com/item=38567 to drop from https://www.wowhead.com/npc=4656, and so start the first quest in this chain, https://www.wowhead.com/quest=14330.\n\nEdit:\nIf you already completed the quest chain before this reputation change, then talk to https://www.wowhead.com/npc=36034 in Karnum's Glade, and he should grant you the reputation",
            date = "2012-03-04T18:59:08-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14394#comments:id=1635158",
        },
        {
            id = 2582872,
            score = 87,
            author = "Hastyrain",
            text = "If you already completed the quests in the past without getting any reputation, you will have to talk to Karnum Marshweaver (http://www.wowhead.com/npc=36034/karnum-marshweaver) and he will give it to you.\n\nCheck if you've already completed the quests with /script print(IsQuestFlaggedCompleted(14394))",
            date = "2018-07-20T18:55:23-05:00",
            sourceUrl = "https://www.wowhead.com/quest=14394#comments:id=2582872",
        },
        {
            id = 1271727,
            score = 57,
            author = "750237",
            text = "I found the previous info vague and not overly helpful.  Here's my input to completing the quest.\n\nFollow NE side of water to the path leading to Shadowbreak Ravine.  Take a right inside the camp, through the stables, kill mobs and follow path up to Agogridon.  There is no million rep or anything - regular rep received (700 with Cenarion Circle), received Blue item Kolkar Cleaver, 75 Silver and 4100 XP.  There is a brief moment when you see a questgiver as you return from killing Agogridon -\nas mentioned, go to the \"island\" in Shok'thokar to obtain the quest from Khan Shodo.",
            date = "2011-01-01T17:11:37-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14394#comments:id=1271727",
        },
    },
    [14407] = {
        {
            id = 1179850,
            score = 145,
            author = "420211",
            text = "This is a quest chain in which the player aids Kalecgos (the new blue dragon aspect) in finding Azuregos and protecting him from the black dragonflight. It spans much of the land of Azshara and is composed of many quests, several of which are completely original in their concepts.\n\n1.)Azshara Blues\n2.)Friends Come In All Colors (http://www.wowhead.com/quest=14130)\n\nHelping out Ergll:\n3.)A Little Pick-me-up (http://www.wowhead.com/quest=14131)\n4.)Absorbent (http://www.wowhead.com/quest=14323)\n---5.)Full of Hot Water (http://www.wowhead.com/quest=14324)\n6.)That's Just Rude! (http://www.wowhead.com/quest=14132)\n\nFinding Archmage Xylem:\n7.)The Way to a Mage's Heart (http://www.wowhead.com/quest=14133)\n8.)Wash Out (http://www.wowhead.com/quest=14345)\n9.)Dressed to Impress (http://www.wowhead.com/quest=14340)\n\nHelping Xylem and his Apprentices:\n10.)Shear Will (http://www.wowhead.com/quest=14249)\n11.)Waste of Thyme (http://www.wowhead.com/quest=14263)\n12.)Renewable Resource (http://www.wowhead.com/quest=14250)\n\n13.)Manual Labor (http://www.wowhead.com/quest=14230)\n14.)Trouble Under Foot (http://www.wowhead.com/quest=14226)\n\nGetting to Xylem's Trials\n15.)The Pinnacle of Learning (http://www.wowhead.com/quest=14413)\n16.)Watch Your Step (http://www.wowhead.com/quest=14296)\n\nXylem's Trials\n17.)The Trial of Fire (http://www.wowhead.com/quest=14300)\n---Achievement: Glutton for Fiery Punishment (http://www.wowhead.com/achievement=5448)\n18.)The Trial of Frost (http://www.wowhead.com/quest=24478)\n---Achievement: Glutton for Icy Punishment (http://www.wowhead.com/achievement=5546)\n19.)The Trial of Shadow (http://www.wowhead.com/quest=24479)\n---Achievement: Glutton for Shadowy Punishment (http://www.wowhead.com/achievement=5547)\n\nFinding Azuregos\n20.)Xylem's Asylum (http://www.wowhead.com/quest=14299)\n21.)Wasn't It Obvious? (http://www.wowhead.com/quest=14389)\n22.)Easy is Boring (http://www.wowhead.com/quest=14390)\n23.)Turning the Tables (http://www.wowhead.com/quest=14391)\n\nThe Final Battle\n24.)Fade to Black (http://www.wowhead.com/quest=24467)",
            date = "2010-11-24T01:17:22-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14407#comments:id=1179850",
        },
        {
            id = 1208110,
            score = 39,
            author = "paddymew",
            text = "\"My master, Kalec wants to see you. He's beneath a bridge, in the slums.\"\n\n*walks down to the harbor*\n\n\"THE FATE OF THE WORLD HANGS IN THE BALANCE\"",
            date = "2010-12-05T12:00:24-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14407#comments:id=1208110",
        },
        {
            id = 2252041,
            score = 12,
            author = "spoonymog",
            text = "This is a Horde only quest chain that requires the following quests to get the toy https://www.wowhead.com/item=53057.\n\nFind the following quest start with Teemo (http://www.wowhead.com/npc=36999)\nAzshara Blues (http://www.wowhead.com/quest=14407/azshara-blues#comments:id=1179850)\n\nFind the following quest starts at Egril (http://www.wowhead.com/npc=35142)\nFriends Come In All Colors (http://www.wowhead.com/quest=14130)\nA Little Pick-me-up (http://www.wowhead.com/quest=14131/a-little-pick-me-up)\nAbsorbent (http://www.wowhead.com/quest=14323)\nFull of Hot Water (Full of Hot Water)\nThat's Just Rude! (http://www.wowhead.com/quest=14132)\nWash Out (http://www.wowhead.com/quest=14345)\n\nFind the following quest start at Sorata Firespinner (http://www.wowhead.com/npc=36210)\nDressed to Impress (http://www.wowhead.com/quest=14340/dressed-to-impress)\n\nFind the following quest starts with Image of Xylem and his Apprentices (http://www.wowhead.com/npc=35187)\nShear Will (http://www.wowhead.com/quest=14249)\nWaste of Thyme (http://www.wowhead.com/quest=14263)\nRenewable Resource (http://www.wowhead.com/quest=14250)\nManual Labor (http://www.wowhead.com/quest=14230)\nTrouble Under Foot (http://www.wowhead.com/quest=14226)\nThe Pinnacle of Learning (http://www.wowhead.com/quest=14413)\nWatch Your Step (http://www.wowhead.com/quest=14296)\n\nThe following quests start at Xylem in this location (http://www.wowhead.com/npc=36361)\nThe Trial of Fire (http://www.wowhead.com/quest=14300)\nBonus - Achievement: Glutton for Fiery Punishment (http://www.wowhead.com/achievement=5448)\nThe Trial of Frost (http://www.wowhead.com/quest=24478)\nBonus - Achievement: Glutton for Icy Punishment (http://www.wowhead.com/achievement=5546)\nThe Trial of Shadow (http://www.wowhead.com/quest=24479)\nBonus - Achievement: Glutton for Shadowy Punishment (http://www.wowhead.com/achievement=5547)\nXylem's Asylum (http://www.wowhead.com/quest=14299)\n\nFind the start of this quest with Joanna (http://www.wowhead.com/npc=36372)\nWasn't It Obvious? (http://www.wowhead.com/quest=14389)\n\nFind these quests with the Spirit of Azuregos (http://www.wowhead.com/npc=36436)\nEasy is Boring (http://www.wowhead.com/quest=14390)\nTurning the Tables (http://www.wowhead.com/quest=14391)\n\nFind this quest with Kalec (http://www.wowhead.com/npc=35867)\nFade to Black (http://www.wowhead.com/quest=24467)\n\nComplete these two quests with Feno (http://www.wowhead.com/npc=37064) & Jellix (http://www.wowhead.com/npc=37061)\nIce cold (http://www.wowhead.com/quest=14261/ice-cold)\nPro-liberation (http://www.wowhead.com/quest=14297/pro-liberation)\n\nComplete the final quest from Azuregos (http://www.wowhead.com/npc=36676)\nFarewell, Minnow (http://www.wowhead.com/quest=14392/farewell-minnow)\n\nNotes:\n\nThe Way to a Mage's Heart (http://www.wowhead.com/quest=14133) is no longer available.\nYou can find the NPC coordinates without an addon by creating a macro -\n\n/script px,py=GetPlayerMapPosition(\"player\")\n/script DEFAULT_CHAT_FRAME:AddMessage(format(\"( %s ) %i,%i\",GetZoneText(),px *100,py *100));",
            date = "2015-09-13T15:13:11-05:00",
            sourceUrl = "https://www.wowhead.com/quest=14407#comments:id=2252041",
        },
        {
            id = 1272127,
