    [14408] = {
        {
            id = 1072436,
            score = 104,
            author = "Mokushi",
            text = "At first, this quest was confusing me greatly, as I could not find the Lab Director or the plans.  After a bit of time searching, I noticed that there was a Buzzer outside the second most-eastern building of the Secret Lab (It is the one with a bank vault lock as a door).  You will want to click this Buzzer in order to spawn the Lab Director, whom you kill for the plans.  As of now, the Director will only drop one set of plans per kill, so if you are grouped be sure to spawn him once per person.  There does not appear to be a respawn timer on the Lab Director.",
            date = "2010-07-03T23:38:52-05:00",
            sourceUrl = "https://www.wowhead.com/quest=14408#comments:id=1072436",
        },
        {
            id = 1177145,
            score = 30,
            author = "theblade1959",
            text = "I found this to be a funny nod to the B sci fi flick, \"Plan Nine From Outer Space.\" Except here, Nine's Plan FOR Outer Space.",
            date = "2010-11-21T20:04:33-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14408#comments:id=1177145",
