            date = "2010-10-17T17:32:32-05:00",
            sourceUrl = "https://www.wowhead.com/quest=14408#comments:id=1145614",
        },
        {
            id = 1189175,
            score = 7,
            author = "Deriol",
            text = "The \"Buzzer\", torch, is not down in the pit area itself, but just on the outskirts above the pit area.  Just follow the rail tracks east and you will see the building with the safe door on your right hand side.  45.93 76.08 are the coords of the torch :)",
            date = "2010-11-27T00:07:31-06:00",
