    [14413] = {
        {
            id = 1179887,
            score = 17,
            author = "420211",
            text = "This is part of a quest chain in which the player aids Kalecgos (the new blue dragon aspect) in finding Azuregos and protecting him from the black dragonflight. It spans much of the land of Azshara and is composed of many quests, several of which are completely original in their concepts.\n\n1.)Azshara Blues (http://www.wowhead.com/quest=14407)\n2.)Friends Come In All Colors (http://www.wowhead.com/quest=14130)\n\nHelping out Ergll:\n3.)A Little Pick-me-up (http://www.wowhead.com/quest=14131)\n4.)Absorbent (http://www.wowhead.com/quest=14323)\n---5.)Full of Hot Water (http://www.wowhead.com/quest=14324)\n6.)That's Just Rude! (http://www.wowhead.com/quest=14132)\n\nFinding Archmage Xylem:\n7.)The Way to a Mage's Heart (http://www.wowhead.com/quest=14133)\n8.)Wash Out (http://www.wowhead.com/quest=14345)\n9.)Dressed to Impress (http://www.wowhead.com/quest=14340)\n\nHelping Xylem and his Apprentices:\n10.)Shear Will (http://www.wowhead.com/quest=14249)\n11.)Waste of Thyme (http://www.wowhead.com/quest=14263)\n12.)Renewable Resource (http://www.wowhead.com/quest=14250)\n\n13.)Manual Labor (http://www.wowhead.com/quest=14230)\n14.)Trouble Under Foot (http://www.wowhead.com/quest=14226)\n\nGetting to Xylem's Trials\n15.)The Pinnacle of Learning\n16.)Watch Your Step (http://www.wowhead.com/quest=14296)\n\nXylem's Trials\n17.)The Trial of Fire (http://www.wowhead.com/quest=14300)\n---Achievement: Glutton for Fiery Punishment (http://www.wowhead.com/achievement=5448)\n18.)The Trial of Frost (http://www.wowhead.com/quest=24478)\n---Achievement: Glutton for Icy Punishment (http://www.wowhead.com/achievement=5546)\n19.)The Trial of Shadow (http://www.wowhead.com/quest=24479)\n---Achievement: Glutton for Shadowy Punishment (http://www.wowhead.com/achievement=5547)\n\nFinding Azuregos\n20.)Xylem's Asylum (http://www.wowhead.com/quest=14299)\n21.)Wasn't It Obvious? (http://www.wowhead.com/quest=14389)\n22.)Easy is Boring (http://www.wowhead.com/quest=14390)\n23.)Turning the Tables (http://www.wowhead.com/quest=14391)\n\nThe Final Battle\n24.)Fade to Black (http://www.wowhead.com/quest=24467)",
            date = "2010-11-24T01:31:36-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14413#comments:id=1179887",
        },
        {
