    [14433] = {
        {
            id = 1301404,
            score = 8,
            author = "665279",
            text = "From the Northern Rocketway Exchange, go south past the Blackmaw Scar to the main entrance of Blackmaw Hold.  There are 2 main entrances.  Take the left-hand entrance, and go straight up the hill.  The documents are directly across from the entrance, (29,38) sitting on top of a wicker crate.\nThere are 2 ambassadors guarding the documents; kill them both, and and one of them will drop the robes.\n\nI took screenshots, with luck, Wowhead will approve them.",
            date = "2011-01-20T04:53:54-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14433#comments:id=1301404",
        },
        {
            id = 1222755,
            score = 5,
            author = "252133",
            text = "You will find the Meeting Agenda around (29.00, 37.00). The robes drop from the ambassador just north of there.",
            date = "2010-12-10T19:09:56-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14433#comments:id=1222755",
