    [14461] = {
        {
            id = 1202813,
            score = 15,
            author = "Callidus2",
            text = "To tame a flaming boar with the torch from this quest:\n\nStep 1; Either get a friend or another account to make a tauren and go through the intro quests. You are aiming for the quest \"Feed of Evil\"\nStep 2; Get your hunter to the boar pit in Mulgore involved in the quest \"Feed of Evil\".\nStep 3; Begin taming the boar. They die after 7 seconds ON THE DOT, so figure out how long your tame takes before trying.\nStep 4; Spam Revive Pet near the end of the tame.\n\nIf successful; You'll see a pet bar for a split second, but no level-up animation. The pet will despawn, and you'll have a blank whistle instead of a boar face. Log out and back in, select the newly shown boar picture, and you now have bacon!\n\nIn unsuccessful;\n- The mob will run out of range and die later.\n- The pet dies, and you see a ding.\n- The pet is tamed, then dies.\n- The pet dies before being tamed.\n\nTaken from Petopia forums and slightly edited to improve accuracy and readability.",
            date = "2010-12-02T19:13:45-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14461#comments:id=1202813",
        },
        {
            id = 1289627,
            score = 9,
            author = "669207",
            text = "If you do this quest and The Battleboars at the same time, you can aggro a boar (or a bunch of boars), kite them to a trough, and use the torch to set them running. Each aggroed boar killed by fire rewards kill credit twice, meaning that you can aggro 5 boars and complete the quest in one shot.",
            date = "2011-01-11T19:20:52-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14461#comments:id=1289627",
        },
        {
            id = 1387817,
            score = 5,
            author = "Zalmon",
            text = "I am having a really hard time taming this guy. How vital is it to spam Revive Pet near the end of the cast? I tried the \"/script PetAbandon()\" macro, and all that does is literally abandon my pet, no matter what pet i have out.\n\nAny tips?",
            date = "2011-04-09T18:03:32-05:00",
            sourceUrl = "https://www.wowhead.com/quest=14461#comments:id=1387817",
        },
        {
            id = 1412651,
            score = 5,
            author = "495203",
