    [14468] = {
        {
            id = 1190159,
            score = 7,
            author = "344586",
            text = "You need to complete the quest line from Horzak Zignibble (npc=35091) before this becomes available.  The full quest line is;\n\nStone Cold (quest=14165)\nThe Perfect Prism (quest=14190)\nPrismbreak (quest=14192)\nRefleshification (quest=14194)",
            date = "2010-11-27T10:22:18-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14468#comments:id=1190159",
        },
        {
            id = 1185044,
            score = 3,
            author = "707108",
            text = "Small camp to the north.",
            date = "2010-11-25T14:08:52-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14468#comments:id=1185044",
        },
        {
            id = 1957937,
            score = 2,
            author = "Fledhyris",
            text = "I had the devil of a time with this quest and ended up missing a huge chunk of the Azshara quest chain, so I'm just commenting in case it happens to anyone else and they run around bewildered for hours same as I did. Though if you're here, you're already on the right track - finding the quest you don't realise you're missing is the stumper!\n\nI completed the Horzak Zignibble quest line then Another Warm Body, but Molotov didn't have any new quests for me after welcoming me to the Bilgewater Battalion. I thought it a little odd but wandered off and found some more quests to do elsewhere - I ended up completing the whole of the Secret Lab and Sea Shrine chains, the Blackmaw Doublecross and the hunt for Azuregos. It was only when I got stuck at 69/100 quests completed that I realised I was missing (a lot!) Eventually I worked out that I needed to come back to Forlorn Ridge and lo and behold, suddenly there are 3 quest givers standing around demanding my attention - where were they back when I was at the right point in the quest chain?\n\nSorry if this seems blindingly obvious to anyone who has done all these quests, but it's the first time I've had a quest chain 'break' like this and surely I can't be the only person it has happened to? I work my way methodically through quest chains as I enjoy the storylines, so this isn't a case of rushing and missing obvious clues, something really went awry at this point - if I knew exactly what, I wouldn't have had a problem :)",
            date = "2014-04-12T13:07:15-05:00",
            sourceUrl = "https://www.wowhead.com/quest=14468#comments:id=1957937",
        },
    },
    [14469] = {
        {
            id = 2608113,
            score = 22,
            author = "Orpartlu",
            text = "The damage from the mines didn't get squished with the stat squish. 2-3 of these will kill you now instead of just harmlessly bouncing you around. Each one deals 450-550 damage at level 14.",
            date = "2018-08-31T23:56:29-05:00",
