    [14470] = {
        {
            id = 1185049,
            score = 21,
            author = "707108",
            text = "Northwest at 27,51.  Kill Warlord Krellian, don't forget to also pick up the item next to him.",
            date = "2010-11-25T14:11:13-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14470#comments:id=1185049",
        },
        {
            id = 1192114,
            score = 16,
            author = "FeyGyrl",
            text = "I found him to be a bit annoying to find, possibly because I was doing Hand-me-downs at the same time as Military Breakthrough. For Hand-me-downs, you're retrieving items from dead guys in the mine field, near the quest givers. I continued on down into the ruins, because there were other Spitelash mobs visible from there. They're all level 15 mobs, running about in groups of 3 - generally a spellcaster & 2 fighters. As a trio, they hit hard & fast - at least for a level 13 troll druid. LOL\nHowever.......\nWarlord Krillian isn't down there; he's on the ridge overlooking the mine field from the other side of the mine field. He's up on a ledge overlooking the field, with 2-3 spellcasters ranged around him. He's an easy level 13 kill. Don't forget to grab the quest item, on the ground next to him. Of note, if you run up after someone else has killed him, you can still loot the item, then kill him when he respawns.\nSo in this case, knowing he was at 27,51-ish wasn't terribly helpful; that's why I've posted this additional more descriptive post, in case anyone else is having the same issues as I did.",
            date = "2010-11-28T02:03:30-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14470#comments:id=1192114",
        },
        {
            id = 1700202,
            score = 4,
            author = "iFitzGerald",
            text = "I think the weapon we collect (the SFG) might be a reference to to the BFG from the Doom and Quake video games. It's known as the BFG 9000 on the Doom series and as BFG10k on the Quake series.\nBFG stands for Big F***ing Gun, so SFG might be Small F***ing Gun although I think the idea would be making a reference to the acronym (SFG -> BFG) and not to the whole name...",
            date = "2012-08-15T10:33:42-05:00",
            sourceUrl = "https://www.wowhead.com/quest=14470#comments:id=1700202",
        },
        {
            id = 1777060,
            score = 3,
            author = "ukkan",
            text = "If you play a hunter and love to move your pet on those mines and see them fly around, wellcome to the club!: )",
            date = "2012-12-07T06:13:43-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14470#comments:id=1777060",
        },
        {
            id = 1685668,
