    [14471] = {
        {
            id = 1185123,
            score = 63,
            author = "Vothul",
            text = "If you're facing Commander Molotov, the mortar guns that you can mount are directly to your right. There's a dirt path. You do not have to go kite the naga mobs to the mines.\n\nTook me forever to figure out.\n\nRemember! Look for mountable mortar guns!",
            date = "2010-11-25T14:40:37-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14471#comments:id=1185123",
        },
        {
            id = 1377254,
            score = 49,
            author = "xylotism",
            text = "These seem to be bugged for me right now. I've done the quest before on at least 2 toons with no issue, but right now when I hop in the mortars and try to aim them (right mouse drag) it aims straight down, not able to hit any of the naga. It's happening with every mortar in the area.\n\nI found one that I can jump in and it aims into the valley where the naga are, and I can use the turn keys to move side to side, but if go up and down it bugs out again.\n\nLong story short, if the cannons are aiming straight down, jump in one and DON'T use the mouse, just turn side to side or simply spam at wherever the default target is.\n\nNer'zhul US, if that makes any difference.",
            date = "2011-03-27T05:43:19-05:00",
            sourceUrl = "https://www.wowhead.com/quest=14471#comments:id=1377254",
        },
        {
            id = 1251597,
            score = 46,
            author = "741414",
            text = "The mortars are at 31,58 for those of you who want coords. :)",
            date = "2010-12-22T03:04:47-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14471#comments:id=1251597",
        },
        {
            id = 1900186,
            score = 31,
            author = "Akhrod",
            text = "Still bugged in 5.4. Even if it LOOKS like you can adjust the range, you'll end shooting at your feet more times than not.",
