    [14472] = {
        {
            id = 1181965,
            score = 30,
            author = "232139",
            text = "This quest seems finicky. If you're having issues completing it, make sure of the following:\n\n-You're shooting a giant that's walking TOWARD you--that is, you're shooting him \"In The Face!\"\n-You're shooting from the minefield path as instructed in the quest text.\n\nAs a level 80, figuring I could just steamroll over this one, I shot from the bottom of the minefield path on a giant that was walking away from me. The giant died, but I didn't get credit and had to abandon the quest to pick up a new SFG (consumed on-use). The second time, I positioned myself around (31,60) so the minefield entrance picket signs were between the giants and I, and I made sure to shoot one that was walking toward me. This gave me credit properly.",
            date = "2010-11-24T14:52:47-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14472#comments:id=1181965",
        },
        {
            id = 1182789,
            score = 13,
            author = "702799",
            text = "I pulled it so it was facing me shot it and completed.",
            date = "2010-11-24T19:45:50-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14472#comments:id=1182789",
        },
        {
            id = 1184698,
            score = 8,
            author = "668742",
            text = "After trying to kill the Giants twice with the SFG and not getting credit, I decided to try pulling one of them first and then using the SFG. It worked. So if you're having trouble getting credit, go ahead and try pulling one first.",
            date = "2010-11-25T11:28:59-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14472#comments:id=1184698",
        },
        {
            id = 1193566,
            score = 8,
            author = "712497",
            text = "As a feral druid, I killed it the first two times while in cat form, as you could still shoot the SFG. I didn't get credit for it either time. The second time, I made sure to switch out of cat form and got credit for it.",
            date = "2010-11-28T14:17:08-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14472#comments:id=1193566",
        },
        {
            id = 1080294,
            score = 7,
            author = "troelala",
            text = "From the quest giver, take the mine field entrance at the right side, where the giants walk up and down the ramp.",
            date = "2010-07-14T09:41:14-05:00",
            sourceUrl = "https://www.wowhead.com/quest=14472#comments:id=1080294",
        },
    },
