    [14478] = {
        {
            id = 1640760,
            score = 20,
            author = "sephyre",
            text = "Here is a list of the quests and quest chains you need to do for this quest to show, assuming you haven't done any in Azshara:\n\nYou need to do all the quests at Orgrimmar Rocketway Exchange\n\nhttps://www.wowhead.com/npc=35085 (29.2, 66.6) gives you:\nhttps://www.wowhead.com/quest=14197\n\nhttps://www.wowhead.com/npc=35091 (29.0, 66.2) gives you 2 quests\nhttps://www.wowhead.com/quest=14165 and https://www.wowhead.com/quest=14161\nThe first starts a chain which leads to:\nhttps://www.wowhead.com/quest=14190\nhttps://www.wowhead.com/quest=14192\nhttps://www.wowhead.com/quest=14194\n\nThese will unlock https://www.wowhead.com/npc=36752's quest, https://www.wowhead.com/quest=14468 which will send you to the next chain.\n\nYou need to do the quests for everyone at this new outpost on Forlorn Ridge (north of the rocketway exchange)\n\nhttps://www.wowhead.com/npc=36749 (29.4, 57.6)\nhttps://www.wowhead.com/quest=14469\n\nhttps://www.wowhead.com/npc=36746\nhttps://www.wowhead.com/quest=14471\n\nhttps://www.wowhead.com/npc=36744\nhttps://www.wowhead.com/quest=14470\nhttps://www.wowhead.com/quest=14472\n\nhttps://www.wowhead.com/npc=36749\nhttps://www.wowhead.com/quest=24452\nhttps://www.wowhead.com/quest=24453 (I'm not sure if this last quest is required, but it's a quick turn in)\n\nNow you can pick up this quest chain from https://www.wowhead.com/object=201578 at Bilgewater Harbor.",
            date = "2012-03-17T17:31:11-05:00",
            sourceUrl = "https://www.wowhead.com/quest=14478#comments:id=1640760",
        },
        {
            id = 1201023,
            score = 9,
            author = "702502",
            text = "the quest text is hilarious, really sounds like something a goblin would say =D",
            date = "2010-12-01T20:43:17-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14478#comments:id=1201023",
        },
        {
            id = 1419482,
            score = 9,
            author = "infamousmax",
            text = "You need to complete This quest.\n\nProfitability Scouting ID 24452\n\nOnce completed a Poster will be on the wall in the inn keepers building.\n\nHope this helps. Was stuck on it for a while. :)",
            date = "2011-05-15T12:32:41-05:00",
            sourceUrl = "https://www.wowhead.com/quest=14478#comments:id=1419482",
        },
        {
            id = 1192257,
            score = 8,
            author = "59993",
            text = "This is NOT class limited.  I don't know why Wowhead seems to think that it is.\n\nAlso, Chaos 5061's list really helped me out.  The recruitment posters did indeed not become active until after I'd completed Profitability Scouting (http://www.wowhead.com/quest=24452).  And it makes sense: the quest giver for Profitability Scouting is from the Bildgewater Battalion, which this posted is recruiting for.  And doing that quest softens up the Nagas enough to make this operation possible.",
            date = "2010-11-28T03:27:24-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14478#comments:id=1192257",
        },
        {
            id = 1182175,
            score = 6,
            author = "694191",
            text = "I've looked in the inn on the poster board and this quest is not there. Has it been moved?",
            date = "2010-11-24T16:02:01-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14478#comments:id=1182175",
        },
    },
    [14479] = {
        {
            id = 1374526,
            score = 29,
            author = "JetsetRM",
            text = "The rocket is at 58,52.",
            date = "2011-03-23T20:49:58-05:00",
            sourceUrl = "https://www.wowhead.com/quest=14479#comments:id=1374526",
        },
        {
            id = 1317543,
            score = 25,
            author = "HelloKitty",
            text = "... But this one is mine.",
            date = "2011-01-31T22:40:44-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14479#comments:id=1317543",
        },
        {
            id = 1222532,
            score = 15,
            author = "xylotism",
            text = "If you didn't pay attention to the quest text and have trouble finding the rocket [as I did, because there are a million rockets in the town], drop the quest and look around until you see the questgiver on your minimap again.\n\nThe rocket he's talking about is a \"vehicle\" sitting on a platform/ramp next to him.",
            date = "2010-12-10T17:24:22-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14479#comments:id=1222532",
        },
        {
            id = 1685424,
            score = 10,
            author = "Freaktoy",
            text = "Quite probably a reference to the Rifleman's Creed.\nThis is my rifle. There are many like it, but this one is mine.\nMy rifle is my best friend. It is my life. I must master it as I must master my life.\nMy rifle, without me, is useless. Without my rifle, I am useless. I must fire my rifle true. I must shoot straighter than my enemy who is trying to kill me. I must shoot him before he shoots me. I will...\nMy rifle and myself know that what counts in this war is not the rounds we fire, the noise of our burst, or the smoke we make. We know that it is the hits that count. We will hit...\nMy rifle is human, even as I, because it is my life. Thus, I will learn it as a brother. I will learn its weaknesses, its strength, its parts, its accessories, its sights and its barrel. I will keep my rifle clean and ready, even as I am clean and ready. We will become part of each other. We will...\nBefore God, I swear this creed. My rifle and myself are the defenders of my country. We are the masters of our enemy. We are the saviors of my life.\nSo be it, until victory is America's and there is no enemy, but peace!\n\nAlso, the Shattered Strand is Normandy all over again. Except with naga and goblins.",
            date = "2012-07-07T04:18:45-05:00",
            sourceUrl = "https://www.wowhead.com/quest=14479#comments:id=1685424",
        },
        {
            id = 1235597,
            score = 9,
            author = "734042",
            text = "It's not necessary to take the rocket.  You can just hand the quest straight in to Lieutenant Drex (at 41.5, 53.5).",
            date = "2010-12-15T11:12:46-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14479#comments:id=1235597",
        },
    },
    [14480] = {
        {
            id = 1264621,
            score = 9,
            author = "748320",
            text = "1. Check your bag and you'll find a rocket\n2. Go to the Naga area\n3. Fire the rocket and and the Gob Squad appears",
