        {
            id = 2472945,
            score = 3,
            author = "Saro",
            text = "To get this quest (and others from the same guy), you need to first do the other quests from the camp, and then pick up another quest from Wrenchmen Recruitment Poster (http://www.wowhead.com/object=201578) in Bilgewater Harbour. I found a comment by Saphyre when looking up the questgiver, see that for more information about the whole chain.\nI was going nuts, trying to figure out how to get that awesome goblin-shield - but now, onwards to Bilgewater Harbor! :-)",
            date = "2017-02-18T23:36:59-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14480#comments:id=2472945",
        },
