    [14482] = {
        {
            id = 1081049,
            score = 157,
            author = "ZehelFenris",
            text = "The ship comes in on the dock where the ship to borean normally comes since your phased as soon you accept the quest.\nYou need to wait on the roleplay event before the ship comes in.",
            date = "2010-07-15T10:34:05-05:00",
