    [14484] = {
        {
            id = 1087826,
            score = 10,
            author = "darknesscalls",
            text = "The boss is very similar to the first boss of Black Temple - Warlord Najentus (I believe that's what his name was).\n\nThe model almost identical, and when you fight him, he tosses spikes on the ground that you can pick up and use against him, similar to the Black Temple fight.\n\nGreat reference, and the fight is a lot of fun :)",
