        },
        {
            id = 1192307,
            score = 7,
            author = "Paper",
            text = "It might just be coincidence, but I was doing this quest and every single level 7 Earth Spirit would be displeased and attack.. I came across a level 6 one and it did not do this.. so I found another level 6.. fine again. Did 3 more level 6 Spirits. Found a level 7.. it attacked.. finished with another level 6. Once done, I tried it again on a level 7 for kicks and it attacked.. level 6 again and it did not. I was getting frustrated with this quest, that's for sure!",
            date = "2010-11-28T03:56:20-06:00",
            sourceUrl = "https://www.wowhead.com/quest=14491#comments:id=1192307",
        },
        {
            id = 1541965,
            score = 4,
            author = "Darnag",
            text = "Noticed couple of things.\n\nIf you attack them, they turn red and you won't get any credit.\nIf you don't attack them but still cast some spells, they chase you twice as long.\nSo better just pick them and run down the hill.",
            date = "2011-10-13T15:48:55-05:00",
            sourceUrl = "https://www.wowhead.com/quest=14491#comments:id=1541965",
        },
    },
