    [24428] = {
        {
            id = 1043936,
            score = 33,
            author = "Eraza",
            text = "We discussed this new quest in guild chat and we have come up with a theory. Remember the undead model of Onyxia that was found in the Cataclysm screenshots? We're thinking this is probably how she got resurrected. Turning the quest into a warlock that infuses her with fel energies and brings her back. If you look at the undead model of her, you can even see giant stitches on her neck.",
            date = "2010-05-22T14:18:24-05:00",
            sourceUrl = "https://www.wowhead.com/quest=24428#comments:id=1043936",
        },
        {
            id = 851071,
            score = 30,
            author = "94239",
            text = "You turn this quest in at  Zardeth of the Black Claw.  (http://www.wowhead.com/?npc=1435) Took me a while to find him so figured this might be helpful to some of you.",
            date = "2009-09-25T00:43:50-05:00",
            sourceUrl = "https://www.wowhead.com/quest=24428#comments:id=851071",
        },
        {
            id = 1819555,
            score = 26,
            author = "998490",
            text = "Simply put for those who don't know:  He's in the basement of the inn (The Slaughtered Lamb) in the mage quarters in Stormwind.",
            date = "2013-03-01T06:45:38-06:00",
            sourceUrl = "https://www.wowhead.com/quest=24428#comments:id=1819555",
        },
        {
            id = 849507,
            score = 24,
            author = "Lorade",
            text = "This is the quest you are sent on once acquiring Onyxia's Head (at level 80).\nKeep in mind, that unlike the level 60 quest, which took you to King Varian Wrynn, and then Major Mattingly, this quest directs you to Zardeth of the Black Claw in the basement of The Slaughtered Lamb in Stormwind.\nCompletion of this quest differs from the level 60 hand in, as it does not give a city wide buff, or result in a city wide yell announcing your name and Onyxia's defeat.",
            date = "2009-09-23T16:53:51-05:00",
            sourceUrl = "https://www.wowhead.com/quest=24428#comments:id=849507",
        },
