        },
    },
    [24434] = {
        {
            id = 1201232,
            score = 11,
            author = "336987",
            text = "Although it might be obvious, the path the portal takes as you reorient it is as follows.\n\nTeldrassil\nSulfuron Spire\nMount Hyjal\nWinterspring\nFrostwhisper Gorge\nValormok",
