            text = "Andorel Sunsworn says in the quest journal: \"We can use this to our advantage (playername). If you can compromise their summoning stone, we can teleport a crack team of commandos behind enemy lines.\n\nThis is obviously a reference to the strategy game : \"Commandos: Behind Enemy Lines\".",
            date = "2018-07-09T16:40:04-05:00",
