    [24436] = {
        {
            id = 1070604,
            score = 20,
            author = "Noxaparti",
            text = "More than likely taken from the term used by the US military for a High Altitude-Low Opening parachute jump, also known as a \"HALO drop\" (http://en.wikipedia.org/wiki/HALO_jump).",
            date = "2010-07-01T16:46:59-05:00",
            sourceUrl = "https://www.wowhead.com/quest=24436#comments:id=1070604",
        },
        {
            id = 1227011,
            score = 20,
