        },
        {
            id = 1282961,
            score = 11,
            author = "Ydrann",
            text = "The Sanctified Flaregun (http://www.wowhead.com/item=49679) can be used while mounted.",
            date = "2011-01-07T20:30:22-06:00",
            sourceUrl = "https://www.wowhead.com/quest=24436#comments:id=1282961",
        },
        {
            id = 2604510,
            score = 3,
            author = "Gwiez",
            text = "Do the prereqs for https://www.wowhead.com/quest=14478, then go do that quest, which shortly leads to the hub with Sergeant Hort. He's right next to the undead guy you turn your quest in to.",
            date = "2018-08-26T12:02:22-05:00",
            sourceUrl = "https://www.wowhead.com/quest=24436#comments:id=2604510",
        },
        {
            id = 1852824,
            score = 2,
            author = "mollygo",
            text = "For anyone trying to figure out how to get this quest, there are a few you have to finish first. You must complete the quests around southern rocket way terminus till you get a quest called Hello to Arms that send you to Bilgewater Harbor. Once there, find the wanted poster that offers Operation Fishgut. It starts a chain quest, after which Halo Drops is available.  Still debating whether it was worth suffering through the puns just to find a green cape to match my Gladiator xmog set.",
            date = "2013-05-13T20:32:59-05:00",
            sourceUrl = "https://www.wowhead.com/quest=24436#comments:id=1852824",
        },
    },
    [24437] = {
        {
            id = 1123346,
            score = 13,
            author = "124958",
            text = "The flags have to be placed in a specific place.\n\nThere will be a colourful area on the ground, usually a blue coloured circle. That would be where the flags are placed.",
            date = "2010-09-19T18:54:46-05:00",
            sourceUrl = "https://www.wowhead.com/quest=24437#comments:id=1123346",
        },
        {
            id = 1197221,
            score = 9,
            author = "FeyGyrl",
            text = "Make sure you've also grabbed Halo Drops (http://www.wowhead.com/quest=24436) & Mop Up (http://www.wowhead.com/quest=24435), because they're a breeze to do at the same time. (BTW....When you finish Mop Up, you'll get Field Promotion as the next quest in that chain. If you do, and haven't finished First Come, I'd recommend finishing this one, first. You can turn this one in & then hit Field Prom right after, as they're closer to each other.)\n\nAs noted above, each spot has a blue area - it's more of a glowing blue miasma marking the spot, rather than a defined \"spot\", just to clarify. Just plant the flag in that marked area.\n\nTo make it easier...here are the coordinates I noted at each blue area:\n\nSouthern Pagoda at 43.90/59.91 - reddish roof, right near water, with a few Spitelash flags by it, near the questgivers for the other two quests area, in their ruins - they're at 41.43/53.85, for reference\nBig ol' Tower at 43.61/43.41 - as it says, it's a big ol' tower, hard to miss. ;)\nNorthern Vista at 45.47/38.47 - little Grecian looking ruin, tucked into base of a small group of rocks\nAll are, by definition, beach front property, so follow the coast & keep the water in site. :)\n\nEach spot has 1-3 mobs you'll probably want to clear to get safely to the spots. They're level 15-16 spitelash naga.",
            date = "2010-11-30T05:00:01-06:00",
            sourceUrl = "https://www.wowhead.com/quest=24437#comments:id=1197221",
        },
        {
            id = 1209417,
            score = -1,
            author = "707511",
            text = "This quest gives rep with Bilgewater Cartel and also counts towards Loremaster of Kalimdor.",
            date = "2010-12-06T01:43:24-06:00",
            sourceUrl = "https://www.wowhead.com/quest=24437#comments:id=1209417",
        },
    },
    [24439] = {
        {
            id = 1195171,
            score = 30,
            author = "Zhett",
            text = "Commander Jarrodenus casts a spell called \"Hadouken\", he even announces it like the Street Fighter characters do:\n\nCommander Jarrodenus says: Haaadoouuu....\nCommander Jarrodenus yells: ...KEN!\n\nOh, and to add something worthwhile:\nThe spell has a strong knockback. Make sure not to fly out of the building.",
            date = "2010-11-29T07:10:30-06:00",
            sourceUrl = "https://www.wowhead.com/quest=24439#comments:id=1195171",
        },
        {
            id = 1261064,
            score = 17,
            author = "Siatia",
            text = "To get this quest, you have to first do Chawg's two quests, Where's My Head? (http://www.wowhead.com/quest=14462) and Let them Feast on Fear (http://www.wowhead.com/quest=24433).\nOnce you've done those, you open up one given by Jr. Bombadier Hackel, called Blacken the Skies (http://www.wowhead.com/quest=24430).\n\nThe completion of that one, opens this quest. :)",
            date = "2010-12-27T00:55:38-06:00",
