            author = "3467",
            text = "I found the heart by walking by 32, 50, near the statues in the center.",
            date = "2010-11-24T20:15:03-06:00",
            sourceUrl = "https://www.wowhead.com/quest=24452#comments:id=1182872",
        },
        {
            id = 1317074,
            score = 12,
            author = "466035",
            text = "Remember to dissmiss any pet you have.. :P",
            date = "2011-01-31T13:28:41-06:00",
            sourceUrl = "https://www.wowhead.com/quest=24452#comments:id=1317074",
        },
        {
            id = 1181973,
            score = 11,
            author = "232139",
            text = "For a little low-brow toilet humor, hang around the spot where the naga and giant appear to be chatting. The giant occasionally farts out a noxious-looking green gas bubble, turns around, pops it with his finger, and then waves the smell away.\n\n@lumastus below: Indeed, I figured it may not be a new animation, but giants in the past have always seemed to be in constant motion, never getting a chance to use their idle animation. :)",
            date = "2010-11-24T14:56:16-06:00",
            sourceUrl = "https://www.wowhead.com/quest=24452#comments:id=1181973",
        },
    },
    [24453] = {
