    [24455] = {
        {
            id = 1422853,
            score = 8,
            author = "833749",
            text = "The map shown (as of May 19 2011) for this quest identifies the wrong start location. Commander Molotov starts it, but the map is showing the wrong phase of commander molotov. At certain points, you will have commander molotov appearing simutaneously at the point marked on the map here (forlorn ridge, [29.5, 57.7]) and also inside the building at the top of the hill in Bilgewater Harbor ([60.6, 50.6]).\n\nRapid Deployment is given by the phase of commander molotov in Bilgewater, even though the forlorn ridge phase is somehow capable of accepting the turn-in for \"Operation Fishgut\". If you try to turn it in to him, you'll be shown the screen to accept \"Rapid Deployment\" for just a moment before you get an error sound and \"You do not meet the requirements for that quest.\"",
            date = "2011-05-19T22:36:44-05:00",
            sourceUrl = "https://www.wowhead.com/quest=24455#comments:id=1422853",
        },
    },
