            text = "if you have Warchief's Command: Ashenvale! (http://www.wowhead.com/quest=28493) this quest does not show up, they appear to be linked",
            date = "2010-11-25T15:20:25-06:00",
            sourceUrl = "https://www.wowhead.com/quest=24463#comments:id=1185215",
        },
