    [24467] = {
        {
            id = 1179901,
            score = 59,
            author = "420211",
            text = "This is part of a quest chain in which the player aids Kalecgos (the new blue dragon aspect) in finding Azuregos and protecting him from the black dragonflight. It spans much of the land of Azshara and is composed of many quests, several of which are completely original in their concepts.\n\n1.)Azshara Blues (http://www.wowhead.com/quest=14407)\n2.)Friends Come In All Colors (http://www.wowhead.com/quest=14130)\n\nHelping out Ergll:\n3.)A Little Pick-me-up (http://www.wowhead.com/quest=14131)\n4.)Absorbent (http://www.wowhead.com/quest=14323)\n---5.)Full of Hot Water (http://www.wowhead.com/quest=14324)\n6.)That's Just Rude! (http://www.wowhead.com/quest=14132)\n\nFinding Archmage Xylem:\n7.)The Way to a Mage's Heart (http://www.wowhead.com/quest=14133)\n8.)Wash Out (http://www.wowhead.com/quest=14345)\n9.)Dressed to Impress (http://www.wowhead.com/quest=14340)\n\nHelping Xylem and his Apprentices:\n10.)Shear Will (http://www.wowhead.com/quest=14249)\n11.)Waste of Thyme (http://www.wowhead.com/quest=14263)\n12.)Renewable Resource (http://www.wowhead.com/quest=14250)\n\n13.)Manual Labor (http://www.wowhead.com/quest=14230)\n14.)Trouble Under Foot (http://www.wowhead.com/quest=14226)\n\nGetting to Xylem's Trials\n15.)The Pinnacle of Learning (http://www.wowhead.com/quest=14413)\n16.)Watch Your Step (http://www.wowhead.com/quest=14296)\n\nXylem's Trials\n17.)The Trial of Fire (http://www.wowhead.com/quest=14300)\n---Achievement: Glutton for Fiery Punishment (http://www.wowhead.com/achievement=5448)\n18.)The Trial of Frost (http://www.wowhead.com/quest=24478)\n---Achievement: Glutton for Icy Punishment (http://www.wowhead.com/achievement=5546)\n19.)The Trial of Shadow (http://www.wowhead.com/quest=24479)\n---Achievement: Glutton for Shadowy Punishment (http://www.wowhead.com/achievement=5547)\n\nFinding Azuregos\n20.)Xylem's Asylum (http://www.wowhead.com/quest=14299)\n21.)Wasn't It Obvious? (http://www.wowhead.com/quest=14389)\n22.)Easy is Boring (http://www.wowhead.com/quest=14390)\n23.)Turning the Tables (http://www.wowhead.com/quest=14391)\n\nThe Final Battle\n24.)Fade to Black",
            date = "2010-11-24T01:34:59-06:00",
            sourceUrl = "https://www.wowhead.com/quest=24467#comments:id=1179901",
        },
        {
            id = 1182237,
            score = 34,
            author = "387361",
            text = "For everyone having trouble with the dragon evade bugging, all you have to do is when you engage the orc don't kill her asap. You have to give the dragon a few moments to fly overhead then the event should happen as scripted.",
            date = "2010-11-24T16:20:46-06:00",
            sourceUrl = "https://www.wowhead.com/quest=24467#comments:id=1182237",
        },
        {
            id = 1184871,
            score = 22,
            author = "308922",
            text = "Note that there is a follow-up from this quest called  Farewell, Minnow (http://www.wowhead.com/quest=14392) which gives you Faded Wizard Hat (http://www.wowhead.com/item=53057) that turns you into a goblin!  Tremendous!\n\nHowever, to get the quest from Azuregos you first need to complete the quests from the nearby goblins:\n\nPro-liberation (http://www.wowhead.com/quest=14297)\nIce Cold (http://www.wowhead.com/quest=14261)",
            date = "2010-11-25T12:53:55-06:00",
            sourceUrl = "https://www.wowhead.com/quest=24467#comments:id=1184871",
        },
        {
            id = 2281948,
            score = 17,
            author = "myrddinwylt",
            text = "To complete this if your level is too high (level 100 as an example),  you must aggro the https://www.wowhead.com/npc=36638, and wait for https://www.wowhead.com/npc=36649 to lift off and start throwing fireballs on the ground.  Once this is done, (wait a few more seconds if you want to be sure) kill https://www.wowhead.com/npc=36638.  DO NOT KILL https://www.wowhead.com/npc=36649.  You must take note that this is a level 15 zone and quest line, and as such, https://www.wowhead.com/npc=36649 as a level 83 elite is not required to be killed by the player.  Kalecygos will kill him after he picks you up, but he will not pick you up if you just rush in and kill.\n\nRushing in and killing https://www.wowhead.com/npc=36638 results in  https://www.wowhead.com/npc=36649 aggroing on you and never lifting off.\n\nRushing in and killing https://www.wowhead.com/npc=36649 results in you needing to wait for them to respawn in order to progress as https://www.wowhead.com/npc=36649 is required to pick you up.\n\nThis quest requires a bit of patience.  Like ... a whole 30 seconds of it  :)",
            date = "2015-11-29T15:00:33-06:00",
            sourceUrl = "https://www.wowhead.com/quest=24467#comments:id=2281948",
        },
        {
            id = 1919720,
            score = 14,
            author = "Berronaxwins",
            text = "Malicion says: You may have saved Azuregos, Searing Totem, but your life ends here.",
            date = "2013-11-19T20:45:29-06:00",
            sourceUrl = "https://www.wowhead.com/quest=24467#comments:id=1919720",
        },
    },
