    [24486] = {
        {
            id = 1193278,
            score = 8,
            author = "139511",
            text = "\"Make hay while the sun shines\" is an English idiom that basically means that if there's something to be done, you need to do it when the opportunity arises instead of avoiding or postponing it.",
