    [24489] = {
        {
            id = 1138448,
            score = 23,
            author = "620394",
            text = "Best. Quest name. Ever.",
            date = "2010-10-09T13:32:29-05:00",
            sourceUrl = "https://www.wowhead.com/quest=24489#comments:id=1138448",
        },
        {
            id = 1182945,
            score = 15,
            author = "Talvanor",
            text = "The only search result with the word \"trolling\" in it in the Wowhead database, so far.\n\nThe more you know...!",
            date = "2010-11-24T20:49:54-06:00",
            sourceUrl = "https://www.wowhead.com/quest=24489#comments:id=1182945",
        },
        {
            id = 1121902,
            score = 12,
            author = "Ketho",
            text = "Soothsayer Shi'kala (http://cata.wowhead.com/npc=37108)\nDa spirits be angry with us.\nI don' know why the spirits be rejectin' us so.\nDon' worry, child.  Grik'nir (http://www.wowhead.com/npc=808) gonna help us get through this.\nSoothsayer Rikkari  (http://cata.wowhead.com/npc=37108)\nWhat we gon' do now, you ask?  We wait.\nGrik'nir (http://www.wowhead.com/npc=808) says he gon' talk to the elemental (http://cata.wowhead.com/npc=37112), get it to fight on our side.\nSoon enough we take over dis valley.  Soon enough.\nSoothsayer Mirim'koa (http://cata.wowhead.com/npc=37174#comments:id=1121901)\nOur land be a land of ice an' snow.\nBut beneath the earth, child, there always be fire.\nDe spirit come from deep down to talk with Grik'nir (http://www.wowhead.com/npc=808).",
            date = "2010-09-16T19:11:59-05:00",
            sourceUrl = "https://www.wowhead.com/quest=24489#comments:id=1121902",
        },
        {
            id = 1180846,
            score = 10,
            author = "700073",
            text = "First two are inside the huts just west of the encampment where you pick up the quest, and then the last one is just outside of the cave south of the encampment...all you need to do is just stand right next to them to tell their story, takes about 5 sec.",
            date = "2010-11-24T09:21:05-06:00",
            sourceUrl = "https://www.wowhead.com/quest=24489#comments:id=1180846",
        },
        {
            id = 1430619,
            score = 10,
            author = "795703",
            text = "I just realized something.  I was back in Northrend and soloed Drak'Theron because I had Drakuru's quest line left open; after that, I switched to some of my alts because I needed some support characters for things like tailoring, blacksmithing, etc... and my Dwarf just did this quest, and then I saw the connection.\n\nAfter Drakuru sells out the Drakkari to the Lich King, the Drakkari turn against their loa and steal their power in order to fight back against the scourge.  The loa were none too pleased by this—one of them blew himself up in defiance—and players work with the Zandalari to free the loa from the Drakkari.  The Frostmane trolls are an offshoot of the Drakkari, and probably worship the same loa; what's left of those loa are shunning them.",
            date = "2011-05-30T07:28:41-05:00",
            sourceUrl = "https://www.wowhead.com/quest=24489#comments:id=1430619",
        },
    },
    [24490] = {
