    [24493] = {
        {
            id = 1989765,
            score = 9,
            author = "DoomsdayEx",
            text = "I am going to have to check again with my alts, but it seems to me you can not get this mission, less you are in the middle of the mission, Pack your Bags. Will confirm when I can.",
            date = "2014-08-08T21:22:29-05:00",
            sourceUrl = "https://www.wowhead.com/quest=24493#comments:id=1989765",
        },
        {
            id = 1121947,
            score = 8,
            author = "Ketho",
            text = "Milo Geartwinge (http://cata.wowhead.com/npc=37518) + Milo's Gyro (http://cata.wowhead.com/npc=37198) accompany you\n\nIs this thing on?  Hello?\nAhh, there you are.  Hello!  I figured that, while you're flying to Kharanos, I'd give you some data about what's going on outside of Coldridge Valley (http://www.wowwiki.com/Coldridge_Valley).\nIt seems you Coldridge folks are dreadfully under-informed about the events of the last few days.\nIf you thought you had problems with trolls in Coldridge, wait 'til you get to Kharanos!  That big cataclysm got the trolls all stirred up out here.\nAnd if you'll look to your left, you'll see that the gnomes have retaken Gnomeregan (http://www.wowwiki.com/Gnomeregan).  Hooray for us!\nThere's plenty else going on out here, too.  We've opened up the path to the airport, there's rumors of Dark Irons (http://www.wowwiki.com/Dark_Iron_clan) in the east... oh, and I think something weird is going on with that dwarf king, Magni (http://cata.wowhead.com/npc=2784).  Might want to check it out.\nAnd here we are!  Welcome to Kharanos (http://www.wowwiki.com/Kharanos)!  Watch your step on the way out.",
            date = "2010-09-16T20:30:57-05:00",
            sourceUrl = "https://www.wowhead.com/quest=24493#comments:id=1121947",
        },
        {
            id = 1532164,
            score = 1,
            author = "734474",
            text = "The boar meat is on a table in the main room.  The flagon of beer is in the kitchen just walk in and look to your left.  The cloak is in a box up by the shaman trainer.",
            date = "2011-10-01T04:55:57-05:00",
            sourceUrl = "https://www.wowhead.com/quest=24493#comments:id=1532164",
        },
    },
