    [24504] = {
        {
            id = 1273783,
            score = 3,
            author = "Seithu",
            text = "From the questgiver, just follow the road up the hill. There should be scouts patrolling between the questgiver and Hunter's Hill.",
            date = "2011-01-02T18:12:53-06:00",
