        },
        {
            id = 1514313,
            score = 2,
            author = "EixieFrost",
            text = "I accepted this quest but at the time I was still doing quests in Stonetalon Mountains. I came back to this quest at a later time I flew from Orgrimmar to Hunter's Hill. When I got there I ran down the path and I couldn't find any mobs along the path. When I reached the original quest giver again I abandoned quest and re-accepted quest. I went up the path again and there were finally mobs to kill!",
            date = "2011-09-10T01:34:43-05:00",
