    [24512] = {
        {
            id = 1287853,
            score = 13,
            author = "719793",
            text = "I armed all 5 at once...and watch them as they rushed gloriously in a group toward the first alliance guard they saw...\n\nThey all died =_=",
            date = "2011-01-10T16:56:35-06:00",
            sourceUrl = "https://www.wowhead.com/quest=24512#comments:id=1287853",
        },
        {
            id = 1188132,
            score = 10,
            author = "710231",
            text = "Be careful of the guards while doing this quest, they will flag you, and kill you unless you run like mad.\n\nThe prisoners are in the first tower you see, not the one being built.\n\nThese are along the sides of the tower, the top of the tower, and the huts near the tower itself.",
            date = "2010-11-26T15:54:31-06:00",
            sourceUrl = "https://www.wowhead.com/quest=24512#comments:id=1188132",
        },
        {
            id = 1950968,
            score = 8,
            author = "984218",
            text = "Whilst completing this for South Barrens Quests (http://www.wowhead.com/achievement=4981) I discovered a novelty - the NPCs you arm will happily charge at any hostile mob they see - including player characters of the opposite faction..\n\nThe level 33 druid (http://us.battle.net/wow/en/character/saurfang/Comgetit/simple) who'd chosen to AFK inside the tower didn't stand a chance.\nSorry, bro.",
            date = "2014-03-14T06:11:10-05:00",
            sourceUrl = "https://www.wowhead.com/quest=24512#comments:id=1950968",
        },
        {
            id = 1556713,
            score = 4,
            author = "207078",
            text = "Completion\nWe will never let up.\nWe will never give in.\n\nWell played, Blizz, well played.",
            date = "2011-10-29T10:22:48-05:00",
            sourceUrl = "https://www.wowhead.com/quest=24512#comments:id=1556713",
        },
        {
            id = 1726021,
            score = 4,
            author = "243447",
            text = "Completed quest at lvl 34 using a DPS  Windwalker Monk. - Doing the quest took some trial and error. Died once when I attacked a lvl 40 that was near the tower, avoid them if you are a low level toon. - The rope takes you from the cliff down to the tower below. If you can't find it it's because it does not look like a rope at all. There will be a mound of dirt on the ground and it will be sparkling. Clicking on it creates the rope. - Once you've used it to get \"behind\" the tower, kill the mobs (low level) behind the tower and go the left. - Avoid going right cause that is where the level 40 mob killed me. - The prisoners are in the completed tower. Not the one under construction and the weapons you need to give them are located both outside the tower and one is up on top of tower. You will need to get one weapon at a time and give it to ONE soldier at a time, then go get another weapon and repeat. In the tower you will find a quest giver sitting on the steps, that lead to the top of the tower. Accept his quest and kill the mob he asks you to kill. He is at the top of the tower. If he is not there, wait. He re-spawns in about 2 minutes. - Hope this helps. Peace!",
            date = "2012-09-30T12:09:07-05:00",
            sourceUrl = "https://www.wowhead.com/quest=24512#comments:id=1726021",
        },
    },
    [24513] = {
        {
            id = 1189442,
            score = 27,
            author = "244380",
            text = "Shouldn't you have to get 2xCaptain Peake's Eyeball (singular) or 1xhttps://www.wowhead.com/item=49771(plural) rather than 2xhttps://www.wowhead.com/item=49771? What, does he have 4 eyes?",
            date = "2010-11-27T03:05:21-06:00",
            sourceUrl = "https://www.wowhead.com/quest=24513#comments:id=1189442",
        },
        {
            id = 1185779,
            score = 19,
            author = "116589",
            text = "HE KICKED ME BLIND?\n\nWow. I know the games name is warcraft, but thats pretty violent.",
            date = "2010-11-25T19:35:16-06:00",
            sourceUrl = "https://www.wowhead.com/quest=24513#comments:id=1185779",
        },
        {
            id = 1403178,
            score = 10,
            author = "358417",
            text = "Read the quest text.\n\nPeake is a monster. If his superiors knew, they would thank the Horde for ending him.\n\nThe quest explicitly states that Peake's actions were not sanctioned by the Alliance, and the questgiver shows awareness of the fact that the Alliance wouldn't approve of his actions.\n\nIncidentally, what do you think of Karga Rageroar?",
            date = "2011-04-28T18:08:53-05:00",
            sourceUrl = "https://www.wowhead.com/quest=24513#comments:id=1403178",
        },
        {
            id = 1536845,
            score = 8,
            author = "836935",
            text = "It looks like he eats the eyes after you deliver them to him...",
            date = "2011-10-06T22:42:43-05:00",
            sourceUrl = "https://www.wowhead.com/quest=24513#comments:id=1536845",
        },
        {
            id = 1266274,
            score = 6,
            author = "746183",
            text = "He is at the top of the tower where the orc soldiers are being kept. When i got there, it was just him and a level 30 melee soldier.\nThe captain was level 31, 2028 hp; had two abilites that i saw:\n1) Blind; confused my character, perhaps 4-6 seconds duration.\n2)A poision ability, not a big problem.",
            date = "2010-12-29T15:45:28-06:00",
            sourceUrl = "https://www.wowhead.com/quest=24513#comments:id=1266274",
        },
    },
