    [24534] = {
        {
            id = 1195204,
            score = 8,
            author = "526007",
            text = "After bringing him down to a certain percentage of health, he will become immune and then say:\n\"you,  you are strong . But...\nStrong enough for THE BOURPOCALYPSE?\"\nHe will then summon 10 or more boars that you must kill before he becomes kill-able.\nBeing as it is Blizzard and how they have a unnatural love for puns and references, it could be a reference to the final level of the popular Iphone store shooting game, BATTLE BEARS: Zombies!. As the Final level is called zompocalypse, where you must face wave after wave of undead zombies.",
            date = "2010-11-29T08:01:40-06:00",
            sourceUrl = "https://www.wowhead.com/quest=24534#comments:id=1195204",
        },
        {
            id = 1352790,
            score = 3,
            author = "NozE8",
            text = "For some reason I was unable to select a quest reward to complete the quest. I tried restarting my client and disabling all my addons to no avail. After some digging I found you could force the quest completion with a small script:\n\n/script CompleteQuest()\n/script GetQuestReward(3)\n\nI pasted that into a macro and it selected reward three which was the ring.",
            date = "2011-02-28T05:09:53-06:00",
            sourceUrl = "https://www.wowhead.com/quest=24534#comments:id=1352790",
        },
        {
            id = 1290976,
