    [24540] = {
        {
            id = 1180529,
            score = 57,
            author = "466615",
            text = "'It took a coward's poison and the fury of Hellscream to bring my father down.'\n\n'WHAT CHANCE HAVE YOU?'\n\nBaine is such a badass.",
            date = "2010-11-24T07:01:08-06:00",
            sourceUrl = "https://www.wowhead.com/quest=24540#comments:id=1180529",
        },
        {
            id = 1180587,
            score = 40,
            author = "469943",
            text = "Now THIS is one EPIC quest for Mulgore. Orno has 990 health and is a Level 10 Elite. But don't let this scare you. Once you get him down to below 800, Baine will come to assist you. Orno calls for 2 Grimtotem Ambushers to hold Baine back who can be killed by you but aren't compulsory. If they aren't dead after a few seconds, Baine will kill them for you. Baine then finishes Orno off for you after some speech between them.\n\nQuite nice voice acting IMO here, pretty damn epic for a level 8 quest! I recommend you check this one out ASAP.\n\nHere's the script;\n\n-Gets Orno down to below 800 health-\nOrno Grimtotem: I've had enough of this!\n-Baine appears-\nBaine Bloodhoof: So have I, Grimtotem.\nOrno Grimtotem: Baine! You've shown yourself! GET HIM!\n-2 Grimtotem Ambushers spawn-\nOrno Grimtotem: -laugh- You will die in shame like your pathetic father.\nBaine Bloodhoof: It took a coward's poison and the fury of Hellscream to bring my father down.\nBaine Bloodhoof: WHAT CHANCE HAVE YOU?\n-Baine warstomps, killing any remaining Grimtotem Ambushers and charges into Orno, knocking him back, depleting his health to 1-\nOrno Grimtotem: This isn't over, Baine...\nBaine Bloodhoof: It is for you.\n-Baine takes one final swing at Orno, finishing him off.\nBaine Bloodhoof: We're done here. Mulgore will no longer suffer the hatred of the Grimtotem.\nBaine Bloodhoof: I will meet you again in Thunder Bluff.\n\nMy opinion on Baine has increased. Alot.",
            date = "2010-11-24T07:34:05-06:00",
            sourceUrl = "https://www.wowhead.com/quest=24540#comments:id=1180587",
        },
        {
            id = 1193799,
            score = 25,
            author = "Solarax",
            text = "It appears that this quest is only available for Tauren characters.",
            date = "2010-11-28T15:46:27-06:00",
            sourceUrl = "https://www.wowhead.com/quest=24540#comments:id=1193799",
        },
        {
            id = 1074406,
            score = 9,
            author = "447186",
            text = "There is a path leading up to Stonetalon Pass starting at 38,14. Orno Grimtotem is an elite and is located at 37,12. When you start the fight Blaine Bloodhoof shows up to take over from you and kills Orno for you. You must then travel back to Thunder Bluff to hand in quest.\n\nLance\nBeta tester for;\nWrath of the Litch King\nCataclysm",
            date = "2010-07-06T10:57:07-05:00",
            sourceUrl = "https://www.wowhead.com/quest=24540#comments:id=1074406",
        },
        {
            id = 1685810,
