            date = "2012-06-02T02:49:17-05:00",
            sourceUrl = "https://www.wowhead.com/quest=24543#comments:id=1672545",
        },
    },
    [24546] = {
        {
            id = 1480107,
            score = 56,
            author = "Dureal",
            text = "I had the same problem. There was no flag next to the point but as you probably noticed other faction has the same quest so you can go across the road and voila! They have exactly the same tower with the flag we need :) You can capture it and finish the quest.",
            date = "2011-07-26T12:07:23-05:00",
            sourceUrl = "https://www.wowhead.com/quest=24546#comments:id=1480107",
        },
        {
            id = 1192166,
            score = 36,
            author = "Borelia",
            text = "\"I told you guys, fight ON THE FLAG!\"",
            date = "2010-11-28T02:35:58-06:00",
            sourceUrl = "https://www.wowhead.com/quest=24546#comments:id=1192166",
        },
        {
            id = 1764440,
            score = 33,
            author = "243447",
            text = "If you can't find the flag at the location where it is marked go south on the main road and you will see another tower just south of the Ruins Of Taurajo, on the right hand side.\n\nTomTom Coords are: /way 46.26 56.74 - South Tower Flag\n\nThere are four waves of fighters. Focus on the ones trying to cap the flag. The defenders will take care of the rest. Stay next to flag till quest is completed. - and have fun dammit! :)",
            date = "2012-11-18T17:25:44-06:00",
            sourceUrl = "https://www.wowhead.com/quest=24546#comments:id=1764440",
        },
        {
            id = 1343057,
            score = 15,
            author = "korby",
            text = "Make sure you are on the hill when the event is over and the \"Success! The hill is yours!\" message is shown.\nI ran off to get a herb, received the message, but I didn't get the quest completed.",
            date = "2011-02-20T04:33:49-06:00",
            sourceUrl = "https://www.wowhead.com/quest=24546#comments:id=1343057",
        },
        {
            id = 3239742,
            score = 9,
            author = "Oceandust",
            text = "I struggled to find both of the \"Point Captured\" locations because the blue outline circles on the minimap are incorrect. After flying around for a bit I found the correct flag locations as it took a while for the flags to spawn.\n\nNorth East Waypoint: /way 49.36, 54.01\nSouth West Waypoint: /way 46.26 56.73\n\nEdit: I was not in warmode, nor did I have to cross realm group to get the flags to spawn. They just seem to be on a long respawn timer if someone does the event before you.\n\nHopefully this info helps!",
            date = "2020-10-18T00:52:13-05:00",
            sourceUrl = "https://www.wowhead.com/quest=24546#comments:id=3239742",
        },
    },
