        {
            id = 874163,
            score = 4,
            author = "228232",
            text = "i doubt that because of the last part of the quest text : \"It may be best to entrust the weapon to the Argent Crusade, where it will serve as a symbol to unite the Lich King's enemies.\"  as this is the Argent Crusade part of the quest..it sais that its better to give the sword to the crusade, that kinda means ure not gonna get it...\n\nwhilst the alliance part of the quest \"If you are to wield it, as Thalorien said, it will bond itself to you.\" is more like \"we're gonna bind it to you, fo sho!\"",
            date = "2009-10-24T08:03:01-05:00",
