    [24603] = {
        {
            id = 1343423,
            score = 63,
            author = "293841",
            text = "Just a small town boar, livin in razorfen kraul\nShe took the midnight path going anywhere.......\nJust a city orc, born and raised by the horde\nHe took the midnight path going anywhere.....\n\nAvenger in a smokey plain\nSmell of wine and guts and pain\nFor his wife they can bleed all night\nIt goes on and on and on and on!\n\n(yes, it sucks. Ive had my fun)",
            date = "2011-02-20T12:25:35-06:00",
            sourceUrl = "https://www.wowhead.com/quest=24603#comments:id=1343423",
        },
        {
            id = 1098179,
            score = 35,
            author = "Chuffy",
            text = "The quest name is a reference to the song \"Don't stop believin'\" by Journey as well as a reference to Mankrik's ongoing battle with the Quilboar in revenge for the death of his wife from the classic quest \"Lost in Battle\".\n\nThe original quest to seek out Mankrik's wife is part of the reason why sites like Wowhead exist. Mankrik's wife was notoriously difficult to find as there were no instructions to her location with the question \"Where is Mankrik's wife?\" entering into Barren's chat and WoW legend.",
            date = "2010-08-09T20:42:25-05:00",
            sourceUrl = "https://www.wowhead.com/quest=24603#comments:id=1098179",
        },
        {
            id = 1209873,
            score = 26,
            author = "Eskaejay",
            text = "Jus' a smor town girr,\nRivin' in a ronery world,\nShe took the midnight train goin' anywhere...\n\n... into a bunch of Quilboar, and the rest is history.",
            date = "2010-12-06T08:46:32-06:00",
            sourceUrl = "https://www.wowhead.com/quest=24603#comments:id=1209873",
        },
        {
            id = 1190749,
            score = 16,
            author = "315138",
            text = "I've been singing \"Don't stop bereavin'\" to my wife for the last two days.  She looks at me like I'm from Mars.\n\nAnyways - I think Mankrik is gonna hook up with a new Shaman wife:\n\n[npc=37812 domain=www]",
            date = "2010-11-27T14:58:59-06:00",
            sourceUrl = "https://www.wowhead.com/quest=24603#comments:id=1190749",
        },
        {
            id = 1183402,
            score = 14,
            author = "425291",
            text = "I gotta say that I am truly delighted to know that Mankrik is still alive and he has even taken up his Blademaster blade and that banner.. Awesome!",
            date = "2010-11-25T00:45:59-06:00",
            sourceUrl = "https://www.wowhead.com/quest=24603#comments:id=1183402",
        },
    },
