    [24624] = {
        {
            id = 1295998,
            score = 5,
            author = "765878",
            text = "For this quest your going to need to go North West from the quest giver.\n    What the quest fells to tell you is you're going to the island of Zalazane's Fall !\nSwim across and you're on  Zalazane's Fall island. The raptors you want are all over the island. They show up with a yellow (neutral) name.\nThe raptors have faint black mist radiating from their midsection .\nAlso, if you mouse over them the pointer will let you see quest info and the quest you're on.\nThe island is located at coordinates  60,39/89,74. That is the middle of the island.\n As a bonus that is also where you'll find  Naj'tess.",
            date = "2011-01-16T07:11:31-06:00",
            sourceUrl = "https://www.wowhead.com/quest=24624#comments:id=1295998",
        },
        {
            id = 1604848,
