    [24626] = {
        {
            id = 1181892,
            score = 35,
            author = "12652",
            text = "He spawns when you accept the quest. If you pick up the quest and don't do it for a bit, he might be gone - just drop and re-fetch the quest to respawn him.",
            date = "2010-11-24T14:31:11-06:00",
            sourceUrl = "https://www.wowhead.com/quest=24626#comments:id=1181892",
        },
        {
            id = 2089529,
            score = 25,
            author = "DragaFireHawk",
            text = "I don't know if anyone else is, or has had this issue, but as of 6.0, everytime I auto accepted the quest due to Kijara walking away from me before I had the chance to hit accept, Swiftclaw wouldn't spawn. At first I thought maybe someone else was on the quest, because when I initially got to the island, Swiftclaw was running around. I did my prerequisites for this quest, came back, ended up auto accepting the quest, and he was gone.\n\nAfter having Kijara walk away from me three more times, (and auto accepting the quest again -.-), I finally got her to stand still long enough so I could actually hit the darned \"accept\" button. Needless to say, the first time I got to hit \"accept\" it worked and Swiftclaw spawned.",
            date = "2015-01-16T08:53:36-06:00",
            sourceUrl = "https://www.wowhead.com/quest=24626#comments:id=2089529",
        },
        {
            id = 1178953,
            score = 20,
            author = "48535",
            text = "Swiftscale is on the same island that you get the quest on.  He runs around the island.\n\nHe isn't a red one, but a black/grey one with some stripes on him.",
            date = "2010-11-23T19:12:25-06:00",
            sourceUrl = "https://www.wowhead.com/quest=24626#comments:id=1178953",
        },
        {
            id = 1178934,
            score = 14,
            author = "707108",
            text = "He runs around the small island that the quest giver is on. Use the item on him and you will be able to ride him. Just take him across the north bridge to the pen and it you'll be done.",
            date = "2010-11-23T19:04:29-06:00",
            sourceUrl = "https://www.wowhead.com/quest=24626#comments:id=1178934",
        },
        {
            id = 1202896,
            score = 13,
            author = "384133",
            text = "All you have to do is catch him and ride him to the mainland then dismount and just walk to the raptor pens at your own leisure.  And the raptor pens are at co ords 66.1, 88.6 BTW.",
            date = "2010-12-02T20:01:30-06:00",
            sourceUrl = "https://www.wowhead.com/quest=24626#comments:id=1202896",
        },
    },
