            author = "703510",
            text = "This same quest, though obviously much higher lvl, is done in Twilight Higlands.\n\nQuest, also a daily after finishing all Dragonmaw Quests (http://www.wowhead.com/quest=28874)",
            date = "2011-01-14T01:04:42-06:00",
