    [24633] = {
        {
            id = 1326752,
            score = 112,
            author = "Meridwyn",
            text = "After Mankrik follows you, he has this conversation with Mahka:\n\nMahka: Look at this land, Mankrik. The Horde and Alliance tear the earth apart just to claw at each other in spite.\nMahka: Such hatred is only bringing us destruction. I can see it in you as you fight the quilboar... your anger does nothing but wear you away.\nMahka: You're destroying yourself, Mankrik.\nMankrik: There is nothing left for me. I seek a warrior's death. Is that wrong?\nMahka: You seek escape, not glory. It's suicide.\nMankrik: So what if it is? Why do you even care?\nMahka: Because...\nMahka: Because despite what you think, there may be people in this world who would mourn your passing.\nMankrik: Mahka...\nMahka: Please, Mankrik. Let go. Set down your blade.\nMankrik: This hatred has burned in me for years, Mahka. Your words cannot lift it from me so easily.\nMahka: Then... you do not need to bear it alone. Just sit next to me and forget your troubles, if only for a while.\nMahka: Come see me whenever you are weary.\nMankrik nods.\nMankrik: ...thank you, Mahka.",
            date = "2011-02-08T09:44:25-06:00",
            sourceUrl = "https://www.wowhead.com/quest=24633#comments:id=1326752",
        },
        {
            id = 1361552,
            score = 97,
            author = "770275",
            text = "Seems to be the beginning of a happy ending. Except for the fact that after I completed the quest Deathwing came and killed everyone :/",
