    [24687] = {
        {
            id = 1242004,
            score = 17,
            author = "40089",
            text = "Needless to say, this is not the most fun quest for hunters.\n\n...Which I guess is kind of made up for by the fact that every other quest in the game is the most fun quest for hunters.",
            date = "2010-12-18T00:14:08-06:00",
            sourceUrl = "https://www.wowhead.com/quest=24687#comments:id=1242004",
        },
        {
            id = 1280646,
            score = 13,
            author = "757388",
            text = "Ok i have a Solution for all Hunters doing this quest & it worked pretty well for me...\nHere r the steps u need to follow...\n\n1)Put pet on passive\nNote : if u r doing this quest...i assume u'r at lvl 50+ & have the ability MultiShot\n\n2)Pick any group of juvenile bloodpetals & u will notice a pattern where the entire group spreads out & congregates together again...\n\n3)Here u have to get the timing right...Just when the juveniles group together...u target any 1 juvenile & fire multi shot...if u've done this step right it should hit all of the juveniles in the group...this step is impt as multi shot has a range limit of 8 yrds around the target so it is absolutely necessary to get every mob in the group together & in 1 shot...\n\n4)Now the entire group will come after u....Ensure that all the mobs attacking u have a bit of their hp nicked off...if not do melee dmg to make sure every member of the group is down by atleast 1 hp...if u have carried out Step 3 properly Step 4 is redundant...the whole point is that the quest requires u to get 1st hit on every mob in the grp to be awarded the credit...\n\n5) Once absolutely sure every juvenile is hit....put pet on defensive & finish the job...use of traps will also work...\n\nI tried it out my self & finished the quest...the best method so far\n\nEnjoy =)",
            date = "2011-01-06T14:26:43-06:00",
            sourceUrl = "https://www.wowhead.com/quest=24687#comments:id=1280646",
        },
        {
            id = 1370366,
            score = 9,
            author = "GrooCT",
            text = "This quest is a pain in the ass for shadow priests, as we don't have a single aoe spell :(",
            date = "2011-03-18T21:24:43-05:00",
            sourceUrl = "https://www.wowhead.com/quest=24687#comments:id=1370366",
        },
        {
            id = 1183554,
            score = 5,
            author = "704030",
            text = "am i disturbed or is this quest buggy? i can't seem to get credit for this quest even though i'm killing the gangs.  is there something i'm missing?",
            date = "2010-11-25T02:03:45-06:00",
            sourceUrl = "https://www.wowhead.com/quest=24687#comments:id=1183554",
        },
        {
            id = 1565156,
            score = 5,
            author = "estroBiologist",
            text = "This quest really seems to be \"Screw Hunters: The quest\"\nLet's count why!\n1. Pet kills don't count. You know all that fun of having a crocolisk aggro them and using Bad Attitude? Nothin'!\n2. Traps count as Pet kills. There's half your AoE!\n3. Multi-shot won't target the others (meaning you didn't kill half the group, meaning the credit isn't applied)\n4. They leash at an INCREDIBLY short distance (I'd wage about 45-50 yards).\n5. They rush into melee, like all mobs, in a situation where your pet can't help, your traps don't help, and you have an incredibly tight radius.\n\nWhat a wonderfully awful quest.\n\nIf you aren't a Hunter looking for Loremaster, don't even bother.",
            date = "2011-11-06T22:15:19-06:00",
            sourceUrl = "https://www.wowhead.com/quest=24687#comments:id=1565156",
        },
    },
