    [24690] = {
        {
            id = 1246214,
            score = 13,
            author = "Brightstar",
            text = "Very sad that Blazerunner has been neutered to a simple quest mob after a 2 part quest from the epic chain for Linken...they could have left him in and simplified it a bit at least...R.I.P. Linken quest.",
            date = "2010-12-19T17:37:06-06:00",
            sourceUrl = "https://www.wowhead.com/quest=24690#comments:id=1246214",
        },
        {
            id = 1542033,
            score = 9,
            author = "892445",
            text = "The path to the top begins at approx. 52.8 41.4 .\n\nIf you don't use coordinates, look at the crator on your map and notice a gap in the red near top (North side of crator). That gap represents a log bridge. You must cross that log bridge to reach the top. That log is broad and flat on top, unlike another log bridge elsewhere on the crator (which is a dead end). It's also connecting you to a well worn trail unlike the other.\n\nThe Blazerunner is a level 53 Elemental, located in the entrance to a tiny cave.\n\nGood luck.\nTrac\nAvatrac on Medivh",
            date = "2011-10-13T17:24:28-05:00",
            sourceUrl = "https://www.wowhead.com/quest=24690#comments:id=1542033",
        },
        {
            id = 1209279,
            score = 5,
            author = "718591",
            text = "Location 49.2, 49.1\n\nFollow the path out of camp all the way to the top of the mountain.  He is inside a cave.\n\nLevel 53 with 3925 health.\n\nUnlocks quests:  The Fledgling Colossus and Peculiar Delicacies",
            date = "2010-12-05T23:14:01-06:00",
            sourceUrl = "https://www.wowhead.com/quest=24690#comments:id=1209279",
        },
        {
            id = 1550531,
            score = 4,
            author = "CaptainCrowbar",
            text = "When you turn in the quest after killing Blazerunner, Williden Marshall says, \"Thanks for dispatching him, he was driving me batty!\". In the movie Blade Runner, the character played by Rutger Hauer is named Roy Batty.",
            date = "2011-10-21T16:30:12-05:00",
            sourceUrl = "https://www.wowhead.com/quest=24690#comments:id=1550531",
        },
        {
            id = 2000117,
