            author = "1347823",
            text = "Does anyone know the spawntimer on this thing? I've been waiting for nearly half an hour and he still hasn't spawned.",
            date = "2014-09-06T19:20:41-05:00",
            sourceUrl = "https://www.wowhead.com/quest=24690#comments:id=2000117",
        },
    },
    [24691] = {
        {
            id = 1090607,
            score = 32,
            author = "darknesscalls",
            text = "The bugs drop 6 legs each time you kill one.\n\nSo by using the power of MATH, I have concluded that you need to kill 16 of these mobs in order to complete the quest.",
            date = "2010-07-28T00:40:09-05:00",
            sourceUrl = "https://www.wowhead.com/quest=24691#comments:id=1090607",
        },
        {
            id = 1391158,
            score = 12,
            author = "Eillesthis",
            text = "I'm pursuing Steamwheedle rep, so I wanted to do the minimum number of quests to get to https://www.wowhead.com/quest=24737.  I hadn't quested in Un'Goro since the Cataclysm, and had credit for only one quest from before (https://www.wowhead.com/quest=12547...odd...).  Anyway, I did:\n\nhttps://www.wowhead.com/quest=24740\nhttps://www.wowhead.com/quest=24690\nThat opened up\nhttps://www.wowhead.com/quest=24691\n\nPerhaps there's another trigger as well.\n\nEdit: fixed formatting",
            date = "2011-04-14T11:36:40-05:00",
            sourceUrl = "https://www.wowhead.com/quest=24691#comments:id=1391158",
        },
        {
            id = 2351306,
            score = 3,
            author = "mazzler",
            text = "For Loremaster grind\n\n*straight forward, kill the bugs\n*don't go into any tunnels, just fly around and kill/loot bugs",
            date = "2016-07-14T23:07:12-05:00",
            sourceUrl = "https://www.wowhead.com/quest=24691#comments:id=2351306",
        },
    },
    [24692] = {
        {
            id = 1184956,
            score = 63,
            author = "Icarium",
            text = "Entrance path is at coords 50,80. Take the right path, then left and left. It's a level 53 Elite, with 9.8k HP. Like said above, avoid Poison Explosion, and it's nnot hard.\n\nDid it as a level 54 Rogue.  **Don't use Vanish! It will bug and reset!  :S",
            date = "2010-11-25T13:30:25-06:00",
            sourceUrl = "https://www.wowhead.com/quest=24692#comments:id=1184956",
        },
        {
            id = 1574090,
            score = 29,
            author = "453636",
            text = "No-one seems to have noted the pre-req in order to get this quest: There's a 2-part quest chain offered by her brother (http://www.wowhead.com/npc=9270) standing right next to her involving killing fire elementals at Fire Plume Ridge that, once completed, unlocked this quest for me. (The only other quest in Un'goro I've completed was this grab/deliver (http://www.wowhead.com/quest=24866) quest which I confused to be the pre-req since it is delivered to her.)\n\nEDIT: I realize how vague I am with my pronouns x.x Anytime I said \"her\" I meant the quest giver (http://www.wowhead.com/npc=9271).",
            date = "2011-11-17T05:43:54-06:00",
            sourceUrl = "https://www.wowhead.com/quest=24692#comments:id=1574090",
        },
        {
            id = 1181362,
            score = 12,
            author = "707898",
            text = "You will find Gorishi Fledgling Colossus in a cave under the earth.\nEntrance is right above the text \"The Slithering Scar\".\n\nI soloed this quest at lvl 50 as a Retpala. Quite easy.\nJust beware that Poision Explosion might hurt you badly.\nJust cover behind a wall. A stone. Or simply get away from the mob.\n\nHave fun.",
            date = "2010-11-24T11:46:57-06:00",
            sourceUrl = "https://www.wowhead.com/quest=24692#comments:id=1181362",
        },
        {
            id = 1331549,
            score = 10,
            author = "Trilok",
            text = "Entrance is not through mountain, but in jungle at Slithering Scar -  (50.5, 78.5)\nAlso Elder here.",
            date = "2011-02-11T07:33:28-06:00",
            sourceUrl = "https://www.wowhead.com/quest=24692#comments:id=1331549",
        },
        {
            id = 2198144,
            score = 10,
            author = "NeinnaWR",
            text = "In order to get this quest for the uniquely colored gloves, you have to first do Williden Marshal's two quests about the fire elementals. When you turn the last in, Hol'aynee will give you this quest. I don't know if you have to turn in  the abandoned research camp quest (http://www.wowhead.com/quest=24866/an-abandoned-research-camp) but I did anyway.",
            date = "2015-06-23T20:59:03-05:00",
            sourceUrl = "https://www.wowhead.com/quest=24692#comments:id=2198144",
        },
    },
    [24693] = {
        {
