    [24694] = {
        {
            id = 1528822,
            score = 31,
            author = "Sharting",
            text = "lol make sure you read the part where is says \"Speak with the Un'Goro Examinant to teleport to The Shaper's Terrace', stupid me walked over there and tried getting up there",
            date = "2011-09-27T12:51:11-05:00",
            sourceUrl = "https://www.wowhead.com/quest=24694#comments:id=1528822",
        },
        {
            id = 1206342,
            score = 26,
            author = "CalaelenDT",
            text = "This quest opens up after you have completed the following quests:\n\n- The Eastern Pylon (http://www.wowhead.com/quest=24721), given by Ithis Moonwarden (http://www.wowhead.com/npc=38263) who is located below the letter \"S\" of Shaper's Terrace on the map\n- The Nothern Pylon (http://www.wowhead.com/quest=24722), given by Gremix (http://www.wowhead.com/npc=38275#.) at Mossy Pile\n- The Western Pylon (http://www.wowhead.com/quest=24723), given by Spark Nilminer (http://www.wowhead.com/npc=9272) at Marshal's Stand\n- Crystals of Power (http://www.wowhead.com/quest=24720), given by J.D. Collie (http://www.wowhead.com/npc=9117) at Marshal's Stand\n\nNote that all the above quests are part of quest chains or require other random quests to have been completed before unlocking the quests above. You will pretty much have to finish the majority of the quests in Un'Goro Crater if you wish to do this quest, though it's very much worth it if you are into Titan lore.\n\nOnce you turn in the last of the 4 quests mentioned above, a quest giver will spawn at Marshal's Stand, who will give you this quest, as well as teleport you to the Shaper's Terrace if you ask it.",
            date = "2010-12-04T15:10:37-06:00",
            sourceUrl = "https://www.wowhead.com/quest=24694#comments:id=1206342",
        },
        {
            id = 1356320,
            score = 9,
            author = "Jacobstx",
            text = "Seeing the questgiver (Being a starry constallation that he is) mention a patron, and seeing data being transmitted from all the pylons as I examined them. I immediately went\n\n\"Oh crap... I just activated another Algalon-distress-signal, didn't I? *sadface*\"\n\nFortunately, I'm not that unlucky.",
            date = "2011-03-03T12:41:50-06:00",
            sourceUrl = "https://www.wowhead.com/quest=24694#comments:id=1356320",
        },
        {
            id = 1555156,
            score = 2,
            author = "cayleb",
            text = "This area is green, and looks more shapely than your average ledge or terrace.",
            date = "2011-10-27T12:48:55-05:00",
            sourceUrl = "https://www.wowhead.com/quest=24694#comments:id=1555156",
        },
        {
            id = 5332956,
            score = 1,
            author = "Wolkenrenner",
            text = "So this part about biting the humanoids on Marshall's Stand? What's the pattern? Armor, bite; or armor, bite, auto-attack? No matter which order I try, I can't seem to satisfy the quest requirements. Help, please?",
            date = "2022-03-01T15:57:35-06:00",
            sourceUrl = "https://www.wowhead.com/quest=24694#comments:id=5332956",
        },
    },
    [24695] = {
        {
            id = 1334480,
            score = 129,
            author = "Leone",
            text = "A summary for completion:\nFor Bloodpetal Observation: Kill a bloodpetal\nFor Diemetradon Observation: Bite 5 NPC's\nFor Gorilla Observation: Speak to each of the race's: Un'Goro Gorilla, Un'Goro Stomper, Un'Goro Thunderer\nFor Pterrordax Observation: Simply fly up and it's done.",
            date = "2011-02-13T09:52:02-06:00",
            sourceUrl = "https://www.wowhead.com/quest=24695#comments:id=1334480",
        },
        {
            id = 1194637,
            score = 108,
            author = "43327",
            text = "Note that while doing the gorilla section, you are considered hostile to members of your own faction. Yes, I was ganked... by a member of my own guild no less while doing it.",
            date = "2010-11-28T23:35:53-06:00",
            sourceUrl = "https://www.wowhead.com/quest=24695#comments:id=1194637",
        },
        {
            id = 1355358,
            score = 97,
            author = "184128",
            text = "If you talk to A-Me 01 during the Gorilla observation, you get\n\nCRASH REPORT XX1-017\n\nCHECKSUM ERROR 0081\n\nFLUID LEVELS DANGEROUSLY LOW\n\nMISSION FAILURE\n\nNEVER GOT A CHANCE TO SEE OUTLANDS",
            date = "2011-03-02T15:33:07-06:00",
            sourceUrl = "https://www.wowhead.com/quest=24695#comments:id=1355358",
        },
        {
            id = 1192044,
            score = 86,
            author = "133091",
            text = "In addition to the gorillas for the quest, as a hunter I could also speak with my gorilla pet.\n\nHey, did you hear the one about the orc hunter? OK, here goes:\n\nA orc hunter walks into a cave and starts fighting gorillas. The leader of the gorillas says, \"Hey, why are you doing that?\" So then the orc hunter says, \"A goblin told me to.\"\n\nThe gorilla leader says, \"Do you do everything that goblins tell you to do?\" And the orc hunter says, \"Yes, because I'm stupid and smelly and I walk on two legs.\"\n\nPretty funny, huh? Hmm... maybe it needs some work...",
            date = "2010-11-28T01:17:06-06:00",
            sourceUrl = "https://www.wowhead.com/quest=24695#comments:id=1192044",
        },
        {
            id = 1198741,
            score = 57,
            author = "Grados",
            text = "Believe it or not, there's a Chrono Trigger reference in this quest.\n\nDuring the Gorilla Observation part, when you speak to an Un'Goro Thunderer he states \"Thunder stuns all dinosaurs, you know.\"\nIn Chrono Trigger, a random caveman in 65,000,000 BC states the exact same quote (but with worse grammar), and sure enough thunder spells in that game stunned dinosaurs and removed their defenses.",
            date = "2010-11-30T20:18:41-06:00",
            sourceUrl = "https://www.wowhead.com/quest=24695#comments:id=1198741",
        },
    },
    [24697] = {
        {
