        },
        {
            id = 1387926,
            score = 11,
            author = "512576",
            text = "My first casual thought was that the real Dimetrodon is a pelycosaur, and the quest asked for me to lure a dinosaur, so I passed over them without even thinking about it and tried to lure some raptors.\n\nThen I remembered that this is just a game, and isn't meant to be scientifically accurate.",
            date = "2011-04-09T21:35:21-05:00",
