    [24701] = {
        {
            id = 1560132,
            score = 20,
            author = "Arenvalde",
            text = "In order to unlock this quest, you need to first complete:\n\nhttps://www.wowhead.com/quest=24740\nhttps://www.wowhead.com/quest=24690\nhttps://www.wowhead.com/quest=24691\nhttps://www.wowhead.com/quest=24693",
            date = "2011-11-01T22:36:50-05:00",
            sourceUrl = "https://www.wowhead.com/quest=24701#comments:id=1560132",
        },
        {
            id = 1420378,
            score = 10,
            author = "617575",
            text = "Oh, and be on the lookout for whatever it was that made them leave...\n\nApparently, Stone Guardians (http://www.wowhead.com/npc=6560) made them leave. Also, be sure to bring 10 Bloodpetal Sprouts (http://www.wowhead.com/item=11315/bloodpetal-sprout) for Here Lies Dadanga (http://www.wowhead.com/quest=24702). :)",
            date = "2011-05-16T14:22:14-05:00",
            sourceUrl = "https://www.wowhead.com/quest=24701#comments:id=1420378",
        },
        {
            id = 1483469,
            score = 7,
            author = "400357",
            text = "Something interesting I kind of \"accidentally\" found out on my hunter:\n\nIf you aggro more than one stone guardian while looting a crate, they'll eventually turn on each other. To achieve this, all you have to do is let them wail on you (they really don't hit all that hard at around 54-ish) until one of them casts Shockwave. Once this happens, they'll all start fighting each other until there's only one left, which will then attack you. I somehow managed to aggro four of them in the cave, but I survived thanks to this trick.\n\nHope this helps you guys!",
            date = "2011-07-30T19:07:26-05:00",
            sourceUrl = "https://www.wowhead.com/quest=24701#comments:id=1483469",
        },
        {
            id = 1204370,
            score = 5,
            author = "smbender",
            text = "Two reasons to proactively destroy the guardians: They don't assist if you initiate combat, but you may get more than one from opening a crate; They are neutral so you can use a big opener or easily position yourself for an attack from behind.",
            date = "2010-12-03T14:29:43-06:00",
            sourceUrl = "https://www.wowhead.com/quest=24701#comments:id=1204370",
        },
        {
            id = 2559177,
            score = 5,
            author = "Aernath",
            text = "A big part of making money is shamelessness. You have to be willing to profit off of the misfortune of others. It all ends up boiling down to one question: How much do you love money?\n\nLearn it from a Goblin ;)",
            date = "2018-03-23T01:46:36-05:00",
            sourceUrl = "https://www.wowhead.com/quest=24701#comments:id=2559177",
        },
    },
    [24702] = {
        {
            id = 1071187,
            score = 168,
            author = "Lokann",
            text = "Poor Dadanga...\n\nDamn you Blizz, what have these poor mounts done to deserve your scorn? First Old Blanchy, now Dadanga... When will it all end?",
