    [24703] = {
        {
            id = 1203300,
            score = 34,
            author = "Tesriel",
            text = "When you are given the options of \"Yes, sir.\" or \"This is ridiculous! I don't have to put up with this!\" he continues on training you in the ways of the squire regardless of what you choose.",
            date = "2010-12-03T01:42:15-06:00",
            sourceUrl = "https://www.wowhead.com/quest=24703#comments:id=1203300",
        },
        {
            id = 1924812,
            score = 10,
            author = "entropicdragon",
            text = "Squire Training\n\nHere is the lesson you must learn before becoming Maximillian's squire.\n\nStay your sword and loosen your cap. Before we do battle with our blades, I first have prepared an assault to unleash upon your ears.\n\nAre you prepared?\n\nAlright, I'm ready.\n\nA squire is the right hand of the knight. As you are already fully aware, hands are especially good at carrying things, and thus your first duty will be to carry my sundries, knickknacks, and other miscellaneous paraphernalia while I dispense justice across the land. To lug around such etcetera is a job unbefitting of a knight.\n\nUnderstandable.\n\nVery good. Secondly, you must know that a knight embraces no tenet more tightly than that of chivalry. He clings to his generosity as he clings to his lance. His valor shines as brightly as his armor. And while his smallsword may be sharp, his manner among allies is soft and courteous.\n\nNow tell me , do you give your oath to hold to the teachings of chivalry and gallantry?\n\nI give you my oath.\n\nHa! Did I not just say, good , chivalry and gallantry are the charge of the KNIGHT? You seek only to be a SQUIRE. The colossal burden of chivalry is unfit for the squire, for as I mentioned before, the only colossal burden that you are to bear is that of my belongings.\n\nYes, sir.\nThis is ridiculous! I don't have to put up with this!\n\n(Both responses take you to the same next page.)\nMoving on! As chivalry is the way of the knight, and I am a knight, you must know then that my own intentions are indeed valorous. It is true, I fight for my Lady Doloria, to proclaim her beauty and majesty across all the lands. Any who question her beauty are without a doubt the most vile of enemies, and must be brought to justice.\n\nAs I speak, it occurs to me that I am a failure. We have come quite far in the squiring ceremony, and I have not yet ascertained whether or not you deserve my charity or my righteous fury.\n\nI must know, now, do you agree that my Lady Doloria is unquestionably the fairest Lady across all of Azeroth?\n\nUmm... yes, yes she is. Unquestionably.\n\nI'm rather glad to hear that.\nCongratulations, , for you have completed your training. You may now ride beside me into the fray.\n\nWoo hoo!",
            date = "2013-12-09T21:53:15-06:00",
            sourceUrl = "https://www.wowhead.com/quest=24703#comments:id=1924812",
        },
        {
            id = 1992842,
            score = 8,
            author = "agnasg",
            text = "Maximillian of Northshire is a reference to Don Quixote of La Mancha and other similar characters of the  chivalric novels. Lady Doloria is like  Dulcinea del Toboso, Don Quixote's lady. His horse's name was Rocinante. It was fun to play this quest because our role is like Sancho Panza, the squire of Don Quixote. The \"dragons\"that Maximillian is trying to defeat are like the windmills that Don Quixote think all the time that are giants enemies.",
            date = "2014-08-17T22:33:03-05:00",
            sourceUrl = "https://www.wowhead.com/quest=24703#comments:id=1992842",
        },
        {
            id = 1442703,
            score = 6,
            author = "Kailayla",
            text = "What ho, traveler!\nHaha, this just made me laugh.\n\nIt's a very easy quest. Talk to him, answer him, complete quest.",
            date = "2011-06-16T13:05:06-05:00",
            sourceUrl = "https://www.wowhead.com/quest=24703#comments:id=1442703",
        },
        {
            id = 2534997,
            score = 6,
            author = "TegoZanduba",
            text = "If you complete this quest chain (ending in https://www.wowhead.com/quest=24706) you'll be able to recruit him in your order hall as:  [champion=1001].\nAfter you have earned https://www.wowhead.com/achievement=11846 and recruit [champion=1000], he'll send you a https://www.wowhead.com/item=143900 in the mail which still start https://www.wowhead.com/quest=45561.",
            date = "2017-11-15T15:36:12-06:00",
            sourceUrl = "https://www.wowhead.com/quest=24703#comments:id=2534997",
        },
    },
