            text = "Upon killing a spirit he's praying to:\n\nSquire!  I understand you are newly trained, but must I tell you not to kill the spirits of the Light?",
            date = "2011-09-29T19:19:26-05:00",
            sourceUrl = "https://www.wowhead.com/quest=24706#comments:id=1531091",
        },
        {
            id = 1197508,
