    [24715] = {
        {
            id = 1180683,
            score = 169,
            author = "Voxxel",
            text = "1. Look for Un'Goro Coconut (http://www.wowhead.com/item=50237) at the bottom of the palm trees nearby\n2. Crack it on the rock next to A-Me 01\n3. Open the looted cracked coconut (http://www.wowhead.com/item=50238)\n4. Loot the coconut milk (http://www.wowhead.com/item=50236)\n5. Hand in the quest.",
