    [24736] = {
        {
            id = 1216190,
            score = 9,
            author = "225343",
            text = "I will admit, seeing the drop requirement of \"35\" made me shout a large \"NOPE\".\n\nThis quest isn't nearly as horrific as it use to be.  Many people recall spending hours trying to hunt down Pteradox for the very low chance of getting a single drop.  It ranked right up there with collecting Mountain Lion Blood and fishing for boar livers back in the day before leveling changes let you skip a lot of quests.\n\nThis time around, the Pteradox are literally everywhere, and you'll only have to hoof a few steps out to start collecting scales.  Every Pteradox will drop 2-5 scales, and it shouldn't take more than seven minutes for the entire quest.",
            date = "2010-12-08T20:20:19-06:00",
            sourceUrl = "https://www.wowhead.com/quest=24736#comments:id=1216190",
        },
        {
            id = 1286340,
            score = 6,
            author = "760439",
            text = "Every great vehicle needs a name... I was thinking I'd call it... Pwned!Nice quest quote. Makes this game very much modern fun... that is if you even read the quests. Again, nice one there. Just my opinion... and every comment I make.",
            date = "2011-01-09T18:29:42-06:00",
            sourceUrl = "https://www.wowhead.com/quest=24736#comments:id=1286340",
        },
        {
            id = 1700565,
            score = 4,
            author = "ahua",
            text = "Abandon this quest if you didn't complete [quest=24794 domain=www] chains.\nBecause if you completed this quest before [quest=24794 domain=www] (or just have this quest) , it becomes not to appear.",
            date = "2012-08-16T12:12:58-05:00",
            sourceUrl = "https://www.wowhead.com/quest=24736#comments:id=1700565",
        },
    },
    [24737] = {
        {
            id = 1391155,
            score = 90,
            author = "Eillesthis",
            text = "I'm pursuing Steamwheedle rep, so I wanted to do the minimum number of quests to get to Super Sticky.  I hadn't quested in Un'Goro since the Cataclysm, and had credit for only one quest from before (https://www.wowhead.com/quest=12547...odd...).  Anyway, I did:\n\nhttps://www.wowhead.com/quest=24740\nhttps://www.wowhead.com/quest=24690\nThat opened up\nhttps://www.wowhead.com/quest=24691\nhttps://www.wowhead.com/quest=24693\nAnd that opened up\nhttps://www.wowhead.com/quest=24737\nhttps://www.wowhead.com/quest=24699\nI did this last one since I was already talking to Tara and had the scraper.\n\nPerhaps there's another path as well.  Oddly only Super Sticky gives rep, even though there are lots of Goblin quests (including four above).\n\nEdit: fixed formatting",
            date = "2011-04-14T11:33:11-05:00",
