    [24747] = {
        {
            id = 1099636,
            score = 112,
            author = "634321",
            text = "a little guide to finding the bomb, since I found I had trouble.\n\nFrom the room where the goblin is, go out as if you were going to the front of the bunker. however, take a right before you reach the entrance. You should find yourself in a room with a couple of dwarven tanks. Go into the room, and head to where there are 2 doorways pretty much right next to each other. Go through one of the doors (doesn't matter which), and look at the wall. There should be a fairly large blue bomb there. Right click it and GTFO of there",
            date = "2010-08-12T03:34:29-05:00",
            sourceUrl = "https://www.wowhead.com/quest=24747#comments:id=1099636",
        },
        {
            id = 5904878,
            score = 44,
            author = "KuripuGao",
            text = "Not sure if this is a recent thing or if its been an issue, but for the life of me I cannot get this quest to trigger properly. I've tried arming one shell and two shells, I've tried both escape routes, I've sat and waited in the keep for a minute or two to see if that was the issue, I've dropped and reacquired this quest several times, but no matter what I do the explosion will not proc.\n\nCurious if anyone else is having this issue. I'll report it as soon as I'm able.",
            date = "2024-07-25T12:26:48-05:00",
