    [24814] = {
        {
            id = 1178978,
            score = 63,
            author = "707108",
            text = "They are on TOP of the cave for anyone wondering. Just talk to the guy and it will start the event. Sometimes she will draw power from the fires, just right click them. If the event is already in progress, you will still get credit for it if you help.",
            date = "2010-11-23T19:23:07-06:00",
            sourceUrl = "https://www.wowhead.com/quest=24814#comments:id=1178978",
        },
        {
            id = 1917186,
            score = 45,
            author = "Turpentine",
            text = "Do not attack Zar'jira.  She will one shot kill you, even at level 5 or 6.   Just sit there and listen to the event between her and Vol'jin and kill the level 4 adds and stomp on the braziers when prompted.",
            date = "2013-11-11T13:02:41-06:00",
            sourceUrl = "https://www.wowhead.com/quest=24814#comments:id=1917186",
        },
        {
            id = 1183563,
            score = 41,
            author = "676520",
            text = "I had the same problem but I came back later and could launch the small event by asking Vol'jin.\nHere is his dialogue with Thrall :\n\n* Talking to the player *\n\nVol'jin: I've no love for Garrosh, dat much is for sure, but leavin' tha Horde is not a decision I be takin' lightly.\n\nVol'jin: Dere's only one with tha answers I seek. Ya can stay and watch if ya like.\n\n* Thrall arrives *\n\nThrall: Vol'jin. It is good to see you, brother.\n\nVol'jin: Thrall! I am glad ya be well. Dere were rumors otherwise.\n\nThrall: Indeed. Someone did try to kill me, but that is not my greatest concert at the moment. The world itself calls for my aid.\n\nVol'jin: I must beg ya council, my friend. I can't be standin' by Garrosh while he be turnin' our people against each other for the sake of war. My respect for ya does not extend to dis new Horde... I am thinkin' of leadin' my people away.\n\nThrall: Vol'jin, I chose Garrosh because he has the strength to lead our people through these trying times.\n\nThrall: For all my supposed wisdom, there have been moments that I've barely been able to hold the Horde together. The Wrath Gate and Undercity displayed that clearly.\n\nThrall: The Horde cries for a hero of old. An orc of true blood that will bow to no human and bear no betrayal. A warrior that will make our people proud again. Garrosh can be that hero.\n\nThrall: I did not make this decision lightly, Vol'jin. I know our alliances will suffer from it. I know the Horde will be irreversibly changed. But I made this choice with confidence that Garrosh is exactly what the Horde needs.\n\nThrall: I'm trusting you and the other leaders to not let this divide our people. You are stronger than that.\n\nVol'jin: I understand, brotha, I will tink on this and be troublin' ya no furtha. You have a world to be savin'.\n\nThrall: Throm'ka, old friend.\n\n* Thrall leaves. Vol'jin is now talking to the player *\n\nVol'jin: Ya are strong and proud, youngsblood. The Darskpear will be honored ta have you fight beside d'em.\n\nVol'jin: Thrall's word are true, as dey always be. The Horde is much more den a few old stubborn leaders and a handful of heroes from Northrend. The people be cryin' Garrosh's name... at least for now.\n\nVol'jin: Still I be hopin' Thrall will return to us one day. That future right now be lookin' very grim and bloody.\n\nVol'jin: Go now. Make tha Darkspear proud. Dere are many wars ahead of us. I'm sure ya be havin' a part to play in all of dem.",
            date = "2010-11-25T02:07:12-06:00",
            sourceUrl = "https://www.wowhead.com/quest=24814#comments:id=1183563",
        },
        {
            id = 1070501,
            score = 37,
            author = "614836",
            text = "This quest is a direct reference to Warcraft III: The Frozen Throne, where during the Orc missions where you earn the trust and eventually ally with the Darkspear Tribe, their original leader Sen'jin was killed by the Sea Witch.\n\nSeems as though she wasn't killed, as was suggested by the campaign (it was a setback), and Vol'jin is back to finish the job and bring honor to his father.",
            date = "2010-07-01T14:36:23-05:00",
            sourceUrl = "https://www.wowhead.com/quest=24814#comments:id=1070501",
        },
        {
            id = 1179245,
            score = 33,
            author = "kesami",
            text = "As you're looking at the cave, go to the right, up to the top of the cave.  Speak to Vol'jin when you're ready.\n\nBe sure to stay for the entire thing, when Vanira tries to heal Zuni.  She'll teleport you back to Darkspear Hold.",
            date = "2010-11-23T21:09:25-06:00",
            sourceUrl = "https://www.wowhead.com/quest=24814#comments:id=1179245",
        },
    },
