    [24861] = {
        {
            id = 1186183,
            score = 17,
            author = "452400",
            text = "When you accept this quest, Chief Hawkwind will say the following:\n\n\"Earth Mother, into your arms we give one of our own. She is Unaya Hawkwind, my mother, and Greatmother to us all; the wisest of our tribe.\n\nMay her spirit fly to you swiftly; may the winds carry her gently, and the grass whisper her name.\n\nWatch over her as she has watched over us; let her look down on us with joy, through the eternal gaze of An'she and Mu'sha, until we join her in death.\n\nFor we are all born of you, and shall all return to you.\"",
            date = "2010-11-25T23:01:06-06:00",
            sourceUrl = "https://www.wowhead.com/quest=24861#comments:id=1186183",
        },
        {
            id = 1452347,
            score = 11,
            author = "343147",
            text = "I was in hardcore quest mode. trying to get to lv 15 within the hour so that i could heal on my shaman. i didnt bother to read the quest text... until i saw the water jug. i instantly remembered greatmother hawkwind and her annoying little quest with the water jug. that quest that i did about 100 times whenever i made a new tauren. that same quest i didnt do this time. instantly a sense of dread overcame me. i read the quest text, and my horror was confirmed. i cant believe im saying this... but i cried over a video game npc.\n\n RIP greatmother hawkwind i will always remember you and your water jug.",
            date = "2011-06-28T00:37:30-05:00",
            sourceUrl = "https://www.wowhead.com/quest=24861#comments:id=1452347",
        },
        {
            id = 1178938,
            score = 9,
            author = "46661",
            text = "Simply use the pitcher near the funeral stand.\n\nRIP Greatmother, thanks for the water.",
            date = "2010-11-23T19:06:00-06:00",
            sourceUrl = "https://www.wowhead.com/quest=24861#comments:id=1178938",
        },
        {
