        {
            id = 1714883,
            score = 3,
            author = "QuickBASIC",
            text = "https://www.wowhead.com/item=8827 will allow you to walk across the water.\nhttps://www.wowhead.com/item=78883 or https://www.wowhead.com/item=6662 will make you big enough to walk along the bottom.\nhttps://www.wowhead.com/spell=61447 is tall enough to walk along the bottom.",
