    [24910] = {
        {
            id = 1228082,
            score = 35,
            author = "716334",
            text = "If you have not done any \"vehicle\" quests before this may seem a bit strange so here is what to do - go to the zeppelin northeast of gadgetzan and click it - you will mount it and it will set off - you should see a new action bar with the abilities mentioned by Rinor - these are not usable straight away - watch for them lighting up -to aim these abilities use right mouse button and move mouse to steer the point they will land near - the zeppelin will go to the goblins for rescue first - out where steamwheedle port used to be - aim near them and use button/ability 1 - there are lots so no need to spam - just aim near and fire 1 till you get 5/5 - the zeppelin will then head to the pirates - time for button 2 - aim near them  and spam button 2 - again not that difficult - use right mouse to move the aim area so you get them all - when you get 40/40 use button 3 for a quick rocket pack back to gadgetzan - have fun and kill/rescue them all",
            date = "2010-12-12T15:56:03-06:00",
            sourceUrl = "https://www.wowhead.com/quest=24910#comments:id=1228082",
        },
        {
            id = 2581728,
            score = 33,
            author = "gabrielbernuss",
            text = "In patch 8.0, there's a bug where most of them are immune to the bomb",
            date = "2018-07-18T11:57:00-05:00",
            sourceUrl = "https://www.wowhead.com/quest=24910#comments:id=2581728",
        },
        {
            id = 1433939,
