    [24911] = {
        {
            id = 1207918,
            score = 17,
            author = "Navaros",
            text = "You can't take this quest if you have taken Warchief's Command: Un'Goro Crater! (http://www.wowhead.com/quest=28526). Interestingly enough, even if you've already taken this quest and then take the Warchief's Command, this quest gets replaced by the Warchief one. Make sure you take this one since (at level 49) it awards 4380 experience whereas the Warchief's Command quest only awards 810.\n\nEDIT: Fixed link.",
