    [24927] = {
        {
            id = 2189798,
            score = 16,
            author = "1046937",
            text = "To get https://www.wowhead.com/npc=38703 to show up,\nyou must first complete the following quests in Gadgetzan,\nfrom the other https://www.wowhead.com/npc=38534:\n\nhttps://www.wowhead.com/quest=24906 and https://www.wowhead.com/quest=24907\nfollowed by\nhttps://www.wowhead.com/quest=24910\nand finally\nhttps://www.wowhead.com/quest=24947 which directs you to meet her in Lost Rigger Cove.",
            date = "2015-06-02T17:12:35-05:00",
            sourceUrl = "https://www.wowhead.com/quest=24927#comments:id=2189798",
        },
        {
            id = 1207114,
            score = 9,
            author = "491283",
            text = "Classes that regularly use AOE effects, be warned that the gnomes can and will beat you down if you're not careful. Very easy to pull more than expected.",
            date = "2010-12-04T23:37:36-06:00",
            sourceUrl = "https://www.wowhead.com/quest=24927#comments:id=1207114",
        },
        {
            id = 1204627,
            score = 4,
            author = "cryoflash",
            text = "A reference to the sea shanty \"Dead Man's Chest\" from the novel Treasure Island, or the movie \"Pirates of the Caribbean: Dead Man's Chest\" (which is probably a reference to the shanty itself).",
            date = "2010-12-03T16:41:41-06:00",
            sourceUrl = "https://www.wowhead.com/quest=24927#comments:id=1204627",
        },
        {
            id = 3208427,
            score = 1,
            author = "Harukam",
            text = "I can confirm the comments about gnome aggro. It killed me the first time I ran through this quest series (before I read the advice here). The flip side of that is that the gnomes will ignore you completely as long as don't damage them. So will any pirate as long as they are fighting either a gnome or a goblin. This means that you have a lot of freedom for shenanigans as long as you're careful.\n\nAvoid AOE as much as possible. That means pet AOE as well as your own.\nGo around behind the buildings. You'll find a few pirates there, and they will aggro normally, but you don't have to worry about pulling the gnomes here.\nTake all three quests from Megs Dreadshredder. You can pick up pirate booty and set the buildings on fire from behind them. Note that there are pirates in the buildings, and they may attack you when you light the buildings up.\nWhen you have to attack the pirates in front of the buildings, attack only those that are fighting goblins. The goblins will help you kill them. If you attack a pirate that's fighting a gnome, the gnome will attack you as well.",
            date = "2020-05-24T04:29:00-05:00",
            sourceUrl = "https://www.wowhead.com/quest=24927#comments:id=3208427",
        },
    },
