            text = "Just completed this quest, at first the rowboats didn't spawn, I waited 30~ seconds and they started appearing, although not all of them appeared, some were still invisible that I managed to hit with random shots.\n\nKeep trying :D",
            date = "2014-11-08T11:50:30-06:00",
