    [24941] = {
        {
            id = 1300752,
            score = 27,
            author = "648382",
            text = "For those of who, like me, go the the wrong places first: it is the tower at 67.6 46.5.\nThe one you're standing in front of while accepting the quest. I know, I should actually read the quest before rushing into it. One day I will. Really.",
            date = "2011-01-19T16:30:49-06:00",
            sourceUrl = "https://www.wowhead.com/quest=24941#comments:id=1300752",
        },
        {
            id = 1183169,
            score = 9,
            author = "708409",
            text = "Completing this quest rewards some spillover rep with Alliance faction even if you are exalted with Stormwind.\n\nOpens up:\n\nBack in the Fight (http://www.wowhead.com/quest=24944)\nRe-Take the Courtyard (http://www.wowhead.com/quest=24943)",
            date = "2010-11-24T22:38:53-06:00",
            sourceUrl = "https://www.wowhead.com/quest=24941#comments:id=1183169",
        },
        {
            id = 1424393,
            score = 8,
            author = "Rizzatto",
            text = "This is a really easy quest.  The quest items respawn almost immediately and they're 3 per loot.  All I did was sit on the very bottom of the tower, grab the two spawn spots there to get all 15.  Easy as could be.",
            date = "2011-05-22T03:40:08-05:00",
            sourceUrl = "https://www.wowhead.com/quest=24941#comments:id=1424393",
