            author = "708409",
            text = "This quest actually *increases* rep with Gilneas by 250.\nCurrent reward here lists -250.\n\nPrerequisite: Langridge Shot (http://www.wowhead.com/quest=24941)",
            date = "2010-11-24T22:42:27-06:00",
