        {
            id = 2532384,
            score = 3,
            author = "Loreza",
            text = "You need to complete https://www.wowhead.com/quest=24941 to be able to accept this quest",
            date = "2017-10-30T05:30:25-05:00",
            sourceUrl = "https://www.wowhead.com/quest=24944#comments:id=2532384",
        },
        {
            id = 1192198,
            score = -5,
            author = "304599",
            text = "During this quest, when you heal the wounded, many of them state that the bandages \"Smell like wet dog.\"\nThis is a reference to a Role-player on the Argent Dawn server that ran a guild called \"Northwatch Hold\" pre-Cata, and was known for awful rumours involving her and a Dog. She was thought to often ERP (erotic role-play) with her members, and support dark corners of our WoW universe like Darknest.",
            date = "2010-11-28T02:57:47-06:00",
            sourceUrl = "https://www.wowhead.com/quest=24944#comments:id=1192198",
        },
    },
    [24947] = {
        {
            id = 1084041,
            score = 5,
            author = "ragemachina",
            text = "The beta is having some issues showing where this is but for those that need this, the goblin is through a cave which goes through to another beach.  On your map it is the middle of the map, where there is land that sticks out furthest into the ocean.  Northern side of the mountain that is also there......Same place you complete the quest Southsea Shakedown on the pre Cataclysm WoW. [quest=8366 domain=www]",
            date = "2010-07-19T02:25:52-05:00",
