    [24948] = {
        {
            id = 1182427,
            score = 12,
            author = "644871",
            text = "You MUST go outside the gates to the north. There'll be some grunts there, and once you get through them there's a few islands to the north-west. On these islands are the catapults.\n\nIt's a good idea to pair this quest with [quest=24956 domain=www], Silencing Rageroar, since the lieutenants are in the same place as the weapons that you have to burn, and the 'boss' isn't too far away. Up near the 'boss' there's a large machine which is the knife thrower",
            date = "2010-11-24T17:22:17-06:00",
            sourceUrl = "https://www.wowhead.com/quest=24948#comments:id=1182427",
        },
        {
            id = 1306555,
            score = 5,
            author = "Waylo",
            text = "68.38 are the coordinates of the BladeThrower and Catapults. It's also a joint quest with Silencing Rageroar (http://www.wowhead.com/quest=24956).\n\nThey do not highlight with a description. You need to toss them while standing in front of them.",
            date = "2011-01-23T16:45:10-06:00",
            sourceUrl = "https://www.wowhead.com/quest=24948#comments:id=1306555",
