    [24950] = {
        {
            id = 1186868,
            score = 23,
            author = "117905",
            text = "\"and NOT the one we've been suicidally bum-rushing for the better part of several hours\"\n\nI put in my vote for best quest text ever.",
            date = "2010-11-26T05:56:55-06:00",
            sourceUrl = "https://www.wowhead.com/quest=24950#comments:id=1186868",
        },
        {
            id = 1666631,
            score = 5,
            author = "reamaree",
            text = "Boarded the ship and the Cpt and Giant spawned, then my dungeon Q came up! Entered the dungeon and when I came out, the Cpt was sitting on the Giant's shoulders under the boat and I couldn't get them to aggro again.  Dropped/Picked up the quest a couple times and Logged In/Out, they stayed in the same position.  Finally jumped down into the water and got right up inside the Giant and it aggroed, killed it then the Cpt aggroed on me and I killed him. Wouldn't aggro on me until I got right up in the Giant, attempted to DoT both mobs from a distance but it wouldn't take.\n[85 SPriest working on Loremaster]",
            date = "2012-05-13T22:36:49-05:00",
            sourceUrl = "https://www.wowhead.com/quest=24950#comments:id=1666631",
        },
        {
            id = 1192408,
            score = 3,
            author = "Hmmster",
            text = "If you're having troubles, you can bug it by standing on the plank you get to the ship on.\nIf you stand there, the captain won't move, and you can ranged kill him without getting damaged.",
