    [24951] = {
        {
            id = 1564333,
            score = 229,
            author = "sandyra",
            text = "Simple steps to completing this quest:\n\nGo into the bug area at the bottom of the cliffs (occasionally you may need to venture towards the mouth of the gaping chasm).\nLook for a flat blue bug (Hazzali Swarmer (http://www.wowhead.com/npc=5451)).\nUse your https://www.wowhead.com/item=52031 near the bug - it will come at you.\nDo not mount - just walk it back to the quest giver.\nHand in.",
            date = "2011-11-06T03:55:44-06:00",
            sourceUrl = "https://www.wowhead.com/quest=24951#comments:id=1564333",
        },
        {
            id = 1096277,
            score = 103,
            author = "Nulgar",
            text = "After you turn in this quest, Narain Soothfancy comes to the swarmer and touches it:Narain Soothfancy says: It's afraid.\nNarain Soothfancy yells: It's afraid!Great Starship Troopers reference.",
            date = "2010-08-05T16:02:24-05:00",
            sourceUrl = "https://www.wowhead.com/quest=24951#comments:id=1096277",
        },
        {
            id = 1182104,
            score = 71,
            author = "166836",
            text = "Don`t mount to bring it back, it`ll despawn.",
            date = "2010-11-24T15:38:58-06:00",
            sourceUrl = "https://www.wowhead.com/quest=24951#comments:id=1182104",
        },
        {
            id = 1309591,
            score = 44,
            author = "624511",
            text = "As a priest you can cast Levitate (http://www.wowhead.com/spell=1706) on the swarmer once its leashed to create your very own Bug Balloon™.",
            date = "2011-01-25T15:28:12-06:00",
            sourceUrl = "https://www.wowhead.com/quest=24951#comments:id=1309591",
        },
        {
            id = 1186812,
            score = 39,
            author = "nagayoshi",
            text = "You actually have to go down to the mouth of the hole in the gaping chasm to find them.  South of Bootlegger Outpost.  Big beetle looking guys.\n\nedit: I did this quest on an alt and the bugs DID spawn right below - on my main, however - the bugs did NOT spawn below and I had to go to the mouth.  Different people may experience different results.",
            date = "2010-11-26T05:24:16-06:00",
            sourceUrl = "https://www.wowhead.com/quest=24951#comments:id=1186812",
        },
    },
    [24953] = {
        {
            id = 1263558,
            score = 163,
            author = "dangerseed",
            text = "This quest took me a while to do as I could not find where the center of the cave was in order to explode the payload. I came here hoping for some help but only found what the quest references to.\nI managed to eventually find the correct area and detonate the bomb.\nSo if anyone else is having trouble like I did here is the information to help you find the right place to detonate.\n\nFirst make your way to The Gaping Chasm and as you go down the spiral ramp take the first entrance you come to, this should be on your left as you descend (if you face the entrance you should be facing west).\nOnce inside take the next left when you can and follow this path down and you will come to a fairly large cavernous room full of Silithid's and what looks like a grey rock sticking up out the ground.\nRun very close to this rock and you will be able to detonate the payload there.\n\nThere may be other places that work but I know for sure that this place was successful.\nThe specific coords that worked for me were (54.5, 72.1)\n\nGood luck, I hope this helps.",
            date = "2010-12-28T07:41:54-06:00",
            sourceUrl = "https://www.wowhead.com/quest=24953#comments:id=1263558",
        },
        {
            id = 1814650,
            score = 47,
            author = "162269",
            text = "For anyone who may not be aware of this:\n\nOnce you have accepted this quest, remember to talk to Narain Soothfancy, to get your bug with explosions.\n\nNarain is the Gnome, who gave you the quest Gazer Tag.",
            date = "2013-02-17T06:49:57-06:00",
            sourceUrl = "https://www.wowhead.com/quest=24953#comments:id=1814650",
        },
        {
            id = 1193853,
            score = 35,
            author = "366196",
            text = "The bug is not attacked by red npcs. I walked it to Gadgetzan without loosing control of it, spamming the first ability for fun animations. In gagdetzan ppl could read my /emotes and attack it (to be killed by guards).\nEdit: Lost control of it when trying to leave tanaris. Also, when killed by a horde you \"get ejected\" from the vehicle and watch yourself fly all the way back to the camp at top speed.",
            date = "2010-11-28T16:04:12-06:00",
            sourceUrl = "https://www.wowhead.com/quest=24953#comments:id=1193853",
        },
        {
            id = 1205864,
            score = 33,
            author = "Maerlim",
            text = "What a great quest.\nA mind-controlled insect loaded with bombs being brought by pheromones to the hive for a big class A explosion.\nThis is Warcraft.",
            date = "2010-12-04T10:35:51-06:00",
            sourceUrl = "https://www.wowhead.com/quest=24953#comments:id=1205864",
        },
        {
            id = 2540565,
            score = 26,
            author = "Snagrat",
            text = "You need to go here:\n\nhttps://i.imgur.com/MQEFMjS.jpg\n\nThe little hill in the middle of the big chasm with the single bug on to. you cant get ontop of it while you are inside the bug so just try climb up as high as you can, then detonate the bombs",
            date = "2017-12-15T08:03:48-06:00",
            sourceUrl = "https://www.wowhead.com/quest=24953#comments:id=2540565",
        },
    },
