    [24956] = {
        {
            id = 1385877,
            score = 25,
            author = "783759",
            text = "When I first saw this quest, I thought the helm had some sort of power to it that Tolliver wanted for himself. After he explained that Rageroar used his brother's scalp as a trophy, I felt so bad...\n\nMoving on, the fight was very easy for me on my level 30 shaman, despite his 2k health.",
            date = "2011-04-07T00:22:23-05:00",
            sourceUrl = "https://www.wowhead.com/quest=24956#comments:id=1385877",
        },
        {
            id = 1250510,
            score = 22,
            author = "740839",
            text = "based on the flavor text surrounding this quest, it would appear as if Rageroar made a hat out of one of the questgiver's worgen friends.",
            date = "2010-12-21T14:17:59-06:00",
            sourceUrl = "https://www.wowhead.com/quest=24956#comments:id=1250510",
        },
        {
            id = 1887906,
            score = 10,
            author = "Rainnea54",
            text = "Quest is bugged as of 8/17/2013. Bastoon isn't there so the shield stays up and Karga is unattackable. Sad day.",
            date = "2013-08-17T18:59:25-05:00",
            sourceUrl = "https://www.wowhead.com/quest=24956#comments:id=1887906",
        },
        {
            id = 1182433,
            score = 8,
            author = "644871",
            text = "The lieutenants are outside the north gate, and on island to the northeast of the gate. Pretty easy kills.\n\nKarga is a little bit harder. There's a shaman that seems to be controlling him (Karga's in a purple bubble beside him, and the shaman seems to be questioning him) that you need to kill before you can attack Karga. Karga has about 1.6k health and hits fairly hard. It's a good idea to kite him as a clothie.\n\nEdit: It's a good idea to pair this quest with Lifting the Siege ([quest=24948 domain=www]). The requirements for that quest are right by the lieutenants on the islands.",
            date = "2010-11-24T17:25:08-06:00",
            sourceUrl = "https://www.wowhead.com/quest=24956#comments:id=1182433",
        },
        {
            id = 1891721,
            score = 5,
            author = "Ambrus",
            text = "Ladies and Gentlemen,\n\nIf it is bugged as mentioned above. Have a friend(real id) that is part of your circle log in on a different character that exists on another realm and invite you to a group. This will phase you to their realm, which hopefully this quest is not bugged there as well, and allow you to complete the quest by killing the needed troll.\n\nNote: If you have multiple accounts you will not need the friend part of this. This may also indicate that you dont have very many friends, a relationship to speak of or much of a life outside this game....I should know.",
            date = "2013-08-31T10:07:59-05:00",
            sourceUrl = "https://www.wowhead.com/quest=24956#comments:id=1891721",
        },
    },
    [24957] = {
        {
            id = 1180345,
            score = 15,
            author = "551326",
            text = "On completion of previous quest:\n\nMegs Dreadshredder says: Hey, ogre. Now that your tribe's signed the proper paperwork, what can we do to actually convince all of them to come do work for us?\nDunemaul \"Emissary\" says: ...me not know what you say.\nMegs Dreadshredder sighs.\nMegs Dreadshredder says: WHAT OGRE LIKE. WHAT GOOD FUN FOR GIVE OGRE.\nDunemaul \"Emissary\" says: Oh. Ogre like eat bug. Get bug from west.\nMegs Dreadshredder says: The silithid? Those things are disgusting and completely inedible...oh, whatever.",
            date = "2010-11-24T05:20:18-06:00",
            sourceUrl = "https://www.wowhead.com/quest=24957#comments:id=1180345",
        },
        {
            id = 1457508,
