    [24960] = {
        {
            id = 1166445,
            score = 34,
            author = "518829",
            text = "Marshal Redpath - formerly at Southshore, presumably died when it was destroyed by the Forsaken\nValdred Moray - formerly at the refugee camp of Greymane Wall, gets killed by an Orc, presumably\n                            for his adultering hands\nLilian Voss - new character with a very interesting history that appears throughout Tirisfal",
            date = "2010-11-09T14:34:32-06:00",
            sourceUrl = "https://www.wowhead.com/quest=24960#comments:id=1166445",
        },
        {
            id = 1748897,
            score = 25,
            author = "336850",
            text = "\"I'll invent my own forsaken with elbows!\"\n          -Marshal Redpath",
            date = "2012-10-23T18:04:44-05:00",
            sourceUrl = "https://www.wowhead.com/quest=24960#comments:id=1748897",
        },
        {
            id = 1392261,
            score = 10,
            author = "Mormolyce",
            text = "Sigh. I'm unable to complete this on my main, the three mobs are already in the next phase (Lillian is in the inn, Redpath is in the rotbrain encampment etc). Presumably because I completed these quests pre-cata.\n\nThird time I've had this problem so far, the Mulgore quest chains terminated too soon and I couldn't do the Highborne chain in Feralas either. Somehow old quests are marking me as further along in the phasing than I should be, or just preventing me from accepting quests.\n\nMy guess is I'm the first to have this problem with this quest because I'm Forsaken and the quests that are giving me issues are previously Forsaken-only.",
            date = "2011-04-15T23:24:10-05:00",
            sourceUrl = "https://www.wowhead.com/quest=24960#comments:id=1392261",
        },
        {
            id = 1187690,
            score = 9,
            author = "g0urra",
            text = "If you talk to Marshal Redpath then abandon the quest and take it again you'll be unable to talk to him since he has despawned. This can luckily be fixed by relogging.",
            date = "2010-11-26T13:04:34-06:00",
            sourceUrl = "https://www.wowhead.com/quest=24960#comments:id=1187690",
        },
        {
            id = 1974494,
            score = 9,
            author = "1270145",
            text = "I find it interesting that they really seem to have a policy of letting the new recruits go wherever they want to go, and do respect that to a degree.",
            date = "2014-06-23T15:07:17-05:00",
            sourceUrl = "https://www.wowhead.com/quest=24960#comments:id=1974494",
        },
    },
    [24961] = {
