            author = "512707",
            text = "All items are in Tirisfal Glades.\nThe Marrowpetal is in the Stillwater Pond at Coordinates 49.8-54.0.\nThe Xavren's Thorn is on the shore next to the Murloc's north of Scarlet Palisade/Solliden Farmstead 34.8-42.9.\nThe Briny Sea Cucumbers are under the water (they look like little green and purple slugs moving around).  33.0-41.3.",
            date = "2010-11-25T22:33:31-06:00",
            sourceUrl = "https://www.wowhead.com/quest=24976#comments:id=1186131",
        },
        {
            id = 1232121,
            score = 6,
            author = "anhsieh",
            text = "Found a whole bunch of Briny Sea Cucumbers under some rocks in the ocean at [34.7, 41.0].",
            date = "2010-12-14T02:28:30-06:00",
            sourceUrl = "https://www.wowhead.com/quest=24976#comments:id=1232121",
        },
        {
            id = 1200482,
            score = 5,
            author = "567037",
            text = "I just wanted to mention that if your character has herbalism, you will be able to see the Marrowpetal and Xavren's Thorn on your mini map if you have Find Herbs activated. The Briny Sea Cucumbers are in the water, and although you \"collect\" them like an herb, they will not appear on your mini map.",
            date = "2010-12-01T15:19:40-06:00",
            sourceUrl = "https://www.wowhead.com/quest=24976#comments:id=1200482",
        },
