    [24979] = {
        {
            id = 1830191,
            score = 27,
            author = "mads535i",
            text = "It's funny how she say's \"be quiet!\" And you just stand there before Gebler while he doesn' seem to notice you. The first time i did this quest i just jumped off the f***ing tower and panicked :P",
            date = "2013-03-17T12:57:51-05:00",
            sourceUrl = "https://www.wowhead.com/quest=24979#comments:id=1830191",
        },
        {
            id = 1196682,
            score = 23,
            author = "208249",
            text = "Lilian Voss: What are you doing here? Get out of here!\nPlayer: I'm here to rescue you.\nLilian Voss: First of all, I don't need to be rescued. Second of all, I'd never allow myself to be rescued by an abomination like you!\nPlayer: Why did the Scarlet Crusade put you in a cage? They usually kill the undead on sight.\nLilian Voss: I'm NOT undead! Not for long, anyway. My father will rescue me, I know it...\nPlayer: Your father?\n\nChat text after you click through Lilian's text:\n\nLilian Voss says: Yes, my... wait, be quiet! I hear the lieutenant approaching.\nScarlet Lieutenant Gebler says: The time has come, my little captive... word has come back from your father.\nLilian Voss says: Gebler, you came! What did he say?\nScarlet Lieutenant Gebler says: High Priest Voss denounces you as a daughter. He's ordered that you be executed immediately.\nLilian Voss says: What? NO! This can't be! Gebler, you know me... we were friends once!\nScarlet Lieutenant Gebler says: The High Priest sends his regrets. He had hoped that one day you would be a powerful weapon against our enemies.\nScarlet Lieutenant Gebler says: Unfortunately, you were too dangerous in life, and you're far too dangerous in undeath. I will enjoy killing you, you Scourged witch...\nLilian Voss says: Gebler, father, why would you...\n[At this point, Gebler attempts to kill Lilian, but she presses through her prison bars and kills him instead.]\nLilian Voss says: The world of the living may have turned its back on me, but I'm no damned Scourge. Just go.",
            date = "2010-11-29T22:51:37-06:00",
            sourceUrl = "https://www.wowhead.com/quest=24979#comments:id=1196682",
        },
        {
            id = 1646406,
            score = 7,
            author = "DJParticle",
            text = "Do you have to be Forsaken to do this quest?  I and my partner tried it with 2 Blood Elves (she was sick of Quel'thalas, so she moved to Tirisfal to quest there), and we can get the quest, but we can't talk to Voss.\n\nUPDATE: Tried with Forsaken character.  Quest is borked, at least on Wyrmrest Accord server - ticket filed by my partner.",
            date = "2012-03-29T23:38:14-05:00",
            sourceUrl = "https://www.wowhead.com/quest=24979#comments:id=1646406",
        },
        {
            id = 1081401,
            score = 6,
            author = "ShakeNBake",
            text = "Obviously a reference to the book \"The Scarlet Letter.\"",
            date = "2010-07-15T20:22:18-05:00",
            sourceUrl = "https://www.wowhead.com/quest=24979#comments:id=1081401",
        },
        {
            id = 1404377,
            score = 6,
