            id = 3209393,
            score = 1,
            author = "patti221",
            text = "If you happen to pick this quest up and you have gone through the Battle of Lordaeron, make sure you talk to Zidormu to go back into time to complete it. The cage with Lillian Voss shows up once you go back into time.",
