    [24992] = {
        {
            id = 1181629,
            score = 184,
            author = "Ethanol",
            text = "As a level 80 approaching this exploring all the new quests I had some trouble picking this one up. I ran around one shotting the Cursed Darkhounds, as I had done for the quest [quest=24990 domain=www] figuring I had just been unlucky getting this to spawn. However after killing bunches of hounds I then came to the conclusion that I was killing them too quickly (I wasn't sure if they transformed mid fight, or after death, or howled for help etc).\n\nI equipped a low level gun (I'm a warrior) and began blasting, getting the hound low and then let it attack me for a moment. It cast a knockback on me and then straight after that, whilst the hound was still alive, a stealthed worgen crept up behind me and appeared warning me off and this quest was instantly accepted as a 'Discovered Quest' on the tracker.",
            date = "2010-11-24T13:15:50-06:00",
            sourceUrl = "https://www.wowhead.com/quest=24992#comments:id=1181629",
        },
        {
            id = 1908435,
            score = 53,
            author = "SargonStarblade",
            text = "Do not kill the https://www.wowhead.com/npc=1548 right away if you are a high level let it beat on you a while. I did this and the Worgen spawned after about 10 sec.",
            date = "2013-10-14T02:43:52-05:00",
            sourceUrl = "https://www.wowhead.com/quest=24992#comments:id=1908435",
        },
        {
            id = 1180315,
            score = 26,
            author = "4513",
            text = "A worgen seems to appear randomly when you kill a Cursed Darkhound. This starts the quest",
            date = "2010-11-24T05:06:10-06:00",
            sourceUrl = "https://www.wowhead.com/quest=24992#comments:id=1180315",
        },
        {
            id = 2583759,
            score = 25,
            author = "WinRate7982",
            text = "I've noticed a lot of comments on this Quest about it being bugged or methods to trigger it that are a bit long winded.\n\nThe quest is no longer bugged!\n\nOnce i'd completed most quests in the area an exclamation point appeared on the map near Cold Hearth Manor. I went there to find no quest. I then searched WoWhead for the quest to find many explainations as to what is happening here.\n\nWhat to do:\n- Let a hound auto attack you in this area (Don't one-shot it if you're a max level, just leave it auto-attacking)\n- A worgan should appear promptly\n- When the hound knocks you back (or you kill the hound being a low level this will take time) the worgen will say something\n- You should now have a new quest\n\nAnd that's all there is to this quest.",
            date = "2018-07-23T07:42:15-05:00",
            sourceUrl = "https://www.wowhead.com/quest=24992#comments:id=2583759",
        },
        {
            id = 5363964,
            score = 24,
            author = "Hearthwood",
            text = "Good afternoon ladies and gentlemen, and everyone else!\n\nThis quest is a bit iffy, but you can get there. When you are within the area, you need to locate a Cursed Darkhound, just let it bite you till a Worgen appears, you don't need to hit it as long as you can aggro it, and the quest pops up.\n\nUpdate: It now looks like you are needed to be on, or have completed the quest, 'Darkhound Pounding'\nSecond Update: It now looks like you are able to trigger the Worgen NPC by bringing the Darkhound to low HP, for example use, 'Soft Form Sword  (https://www.wowhead.com/item=137663/soft-foam-sword)toy.'",
            date = "2022-04-27T06:26:11-05:00",
            sourceUrl = "https://www.wowhead.com/quest=24992#comments:id=5363964",
        },
    },
    [24993] = {
