    [25006] = {
        {
            id = 1368512,
            score = 11,
            author = "Destler",
            text = "Lore: If anyone remembers the quest letter (\"A Letter to Yvette\" written by Thurman Agamand) that could be found on Rattlecage skeletons or the sorcerers, Devlin Agamand was the one who betrayed the Agamand family when the Scourge attacked, allowing them inside the perimeter and even murdering a few of the farm hands. The letter describes Devlin as being a selfish, weak man who readily threw his allegiance with the Scourge, who rewarded him with undeath. He was scum all around and it's no surprise he attacks you when his spirit is resurrected.",
            date = "2011-03-16T15:06:23-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25006#comments:id=1368512",
        },
        {
            id = 1186152,
            score = 7,
            author = "593472",
            text = "I did the quest for this guy on my 80 Rogue, and he spawned as L81.  Wasn't hard to kill, just a curious thing I noticed.  Anyone else have a similar experience?",
            date = "2010-11-25T22:42:52-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25006#comments:id=1186152",
        },
        {
            id = 1209284,
            score = 7,
            author = "Devanika",
            text = "For anybody whose powers of observation are as awful as mine, please note that he appears as a spectre floating several feet above the bed in front of Malia after she yells for him to show his ugly mug.",
            date = "2010-12-05T23:16:19-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25006#comments:id=1209284",
        },
        {
            id = 1183041,
            score = 6,
            author = "MintySinty",
            text = "Shadow Priestess Malia yells: Devlin Agamand! Listen to my voice! Your mortal remains have been gathered, here in this place where you spent your childhood! Resist the Lich King's will, Devlin! Come to us!\nSpirit of Devlin Agamand yells: DIE, YOU WRETCHES!\n\nSince 4.0.3a, I've heard this about 20 times per day.",
            date = "2010-11-24T21:35:25-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25006#comments:id=1183041",
        },
        {
            id = 1210384,
            score = 5,
