        {
            id = 1945935,
            score = 2,
            author = "Eido",
            text = "This quest, as stated above, requires that you collect 6 https://www.wowhead.com/item=52072.\nThese quest items are drops from the two types of Sandfury Zombies in front of [zone=1176]:\nNOTE: It appears these quest items do NOT drop from the trolls (zombie or otherwise) in said instance.\n\nhttps://www.wowhead.com/npc=44557 - which are most likely the zombies above-ground, either standing idle or hunched over, preforming an eating animation.\nhttps://www.wowhead.com/npc=38909 - which are probably the zombies which spawn when you click on the https://www.wowhead.com/object=205057s in the same area.",
            date = "2014-02-23T03:52:45-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25026#comments:id=1945935",
        },
        {
            id = 2548814,
