    [25027] = {
        {
            id = 1204637,
            score = 31,
            author = "favrebites",
            text = "This refers to the song \"Lucille\" made famous by Kenny Rogers in 1977, when you needed to by a console from Sears and hook it up to the UHF screws on the back of your TV in order to play the ultimate video game of the time, Pong.  (Yes, TVs used to have screws on the back.)\n\nIn the song, Lucille's husband says, \"You picked a fine time to leave me, Lucille, with four hungry children and a crop in the field.\"  Although, we preferred to sing it as \"with four hundred children and a crotch that won't heal\".",
            date = "2010-12-03T16:46:34-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25027#comments:id=1204637",
        },
        {
            id = 1685610,
            score = 8,
            author = "1012663",
            text = "The camp where Corporal Teegan is found can be a bit tricky to find if you are coming from Forward Command. Basically, it is about half way between The Great Divide and the \"r\" in Forward Command on the world map.  My suggestion is to walk along the ridge of The Great Divide and look south when you are above the \"r\". You should be able to see the camp from there.\n\nNote that you must have completed quests https://www.wowhead.com/quest=25015 and https://www.wowhead.com/quest=25022 before this one becomes available.",
            date = "2012-07-07T12:59:40-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25027#comments:id=1685610",
        },
        {
            id = 1394071,
            score = 5,
            author = "bazzio",
            text = "@Jouii\nI came here for the reference too,\nNot everyone here comes for directions when you have an in-game quest helper which shows you the exact spot.",
            date = "2011-04-18T07:33:03-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25027#comments:id=1394071",
        },
        {
            id = 1503169,
