    [25039] = {
        {
            id = 1250031,
            score = 10,
            author = "457614",
            text = "I assume this quest is another version of https://www.wowhead.com/quest=24992 that may or may not have been taken out of the game.",
            date = "2010-12-21T09:22:50-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25039#comments:id=1250031",
        },
        {
            id = 1210164,
            score = 7,
            author = "161879",
            text = "If you complete https://www.wowhead.com/quest=24992, wowhead will also list this quest as completed.\nTo actually get this quest, you have to first abandon https://www.wowhead.com/quest=24992.\n\nHowever, you won't get a chance to complete both of the quests.\nRewards are the same and both quests will be marked as completed if you complete either.",
            date = "2010-12-06T12:16:55-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25039#comments:id=1210164",
        },
        {
            id = 1565931,
            score = 2,
            author = "Rhynchelma",
            text = "Following from RayEmery's explanation.\n\nThis quest is still in the game.\n\nWhen you auto accept Escaped From Gilneas ( http://www.wowhead.com/quest=24992), the invisible quest FLAG - Worgen Attacked ( http://www.wowhead.com/quest=25040) is set.\n\nIf you abandon Escaped From Gilneas ( http://www.wowhead.com/quest=24992) then this quest is made available.\n\nRe-tested using 4.2.2.",
            date = "2011-11-07T20:14:55-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25039#comments:id=1565931",
        },
        {
            id = 2522840,
            score = 1,
            author = "Wyr3d",
            text = "Escaped from Gilneas (http://www.wowhead.com/quest=24992/escaped-from-gilneas) is a quest you are supposed to get while on the quest Darkhound Pounding. (http://www.wowhead.com/quest=24990/darkhound-pounding) Howevr, those of you who are over-leveled, or over-powered enough this quest will not be offered. The reason is that Escaped from Gilneas requires that you be fighting a Darkhound, and have it down to low health. At this point a worgen will spawn, steal your kill and threaten you about their apparent wrath, and the quest ill auto-offer/accept in your log. (You can still loot the corpse)\n\nHave You Seen Anything Weird Out There? (http://www.wowhead.com/quest=25039/have-you-seen-anything-weird-out-there)> is offered to those who complete Darkhound Pounding without a worgen spawning - either due to one-shotting, or simply doing enough damage to kill them before they reach low health. This quest is offered by Ratslin Maime after meeting one of the following conditions:\n\n1. Completing enough other quests in the area that would otherwise send you further out\n2. Attack or are attacked by and of the stealthed worgen in the area.\n\nIt can also be offered after abandoning the quest Escaped from Gilneas\n\nPlease note: For those of you who are overpowered, you can instantly trigger the event for Escaped from Gilneas by using the Soft Foam Sword (http://www.wowhead.com/item=137663/soft-foam-sword) toy, or similar method.",
            date = "2017-09-12T23:50:45-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25039#comments:id=2522840",
        },
        {
            id = 5959021,
            score = 1,
            author = "Mathianas",
            text = "You do not have to kill or weaken the darkhound to spawn the worgen, just be in combat long enough for it to appear.",
            date = "2024-09-15T04:05:51-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25039#comments:id=5959021",
        },
    },
