    [25046] = {
        {
            id = 1274193,
            score = 54,
            author = "753485",
            text = "Hint: If you see \"?\" level mobs, you're going the wrong way! You're a bit too far East and are actually heading to the Scarlett Monastery. Lilian will hardly do any damage to these guys and you're sure to wipe. The route you want to take is not on the path/road and your destination is actually that little broken tower icon to the West of the Monastery on the map.\n\nMight have been obvious to some, but it took me longer than I'd care to admit to figure this out. Hope that helps.",
            date = "2011-01-02T23:34:08-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25046#comments:id=1274193",
        },
        {
            id = 1694899,
