    [25057] = {
        {
            id = 2428062,
            score = 146,
            author = "483172",
            text = "Came to check the comments as I was having trouble on my 110 Druid doing this quest for loremaster. I tried the Rez sickness trick but I was still hitting too hard. But then I was thinking if only blizz had a false swipe mechanic, and decided to review my toybox. Well apparently they finally gave us this:https://www.wowhead.com/item=137663 You can buy it from the toy shop in dalaran. Once you have it you use it like a spell on those fragile low level mobs, and it leaves em with 10% health.",
            date = "2016-10-14T17:17:54-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25057#comments:id=2428062",
        },
        {
            id = 1564396,
            score = 41,
            author = "sandyra",
            text = "Tricky to do as a max level character, especially since the release of Mists of Pandaria.  Here are some tips:\n\nGet nekked (this one's a must) - throw down your weapons too.\nSwap into your least smack-y spec (ie. as a fury warrior I dropped back to protection).\nYou may need to go further with this if you're too quick to kill them despite the measures above...  We're talking https://www.wowhead.com/spell=15007 people.\nSlap 'em a few times till they get below 35% health.\nSpin around to turn your back on them so you're not laying in any more auto-attacking hits.\nUse the https://www.wowhead.com/item=52271 (you may need to turn back around and smack them again to touch up their health if it isn't quite low enough).\nWash, rinse and repeat five times successfully to complete the quest.\n\nIt's worth noting, that because of MoP, you may be accidentally and unintentionally killing them in two to three hits or less despite being naked and unarmed.  A sacrificial suicide is recommended with the goal of gaining resurrection sickness mentioned above.  Once your stats take a 75% reduction for 10 minutes, this should allow you to knock their health down without any accidental deaths and complete the quest.",
            date = "2011-11-06T05:12:30-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25057#comments:id=1564396",
        },
        {
            id = 2509760,
            score = 32,
            author = "rcuosukgi42",
            text = "Anyone doing this or any other low level \"wound the mob\" quest in patch 7 or later use the https://www.wowhead.com/item=137663 which is purchasable in Stormwind, it works perfectly and doesn't require any rez-sickness or other trouble.",
            date = "2017-07-23T14:15:03-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25057#comments:id=2509760",
        },
        {
            id = 1473909,
            score = 30,
            author = "Shikuto",
            text = "It's a little weird running around naked chasing looters.",
            date = "2011-07-19T06:12:16-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25057#comments:id=1473909",
        },
        {
            id = 3221889,
            score = 14,
            author = "Maravec",
            text = "As archknightjakio said, the Soft Foam Sword (https://www.wowhead.com/item=137663/soft-foam-sword) works well if you're one-shotting the mobs. It's sold by Jepetto Joybuzz (https://www.wowhead.com/npc=96483/jepetto-joybuzz) in New Dalaran for about 40 gold. I found a page for Jepetto that said he was in The Underbelly, but I did not find him there.",
            date = "2020-08-08T18:18:12-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25057#comments:id=3221889",
        },
