    [25063] = {
        {
            id = 1236578,
            score = 19,
            author = "Sariko",
            text = "I believe this quest title is a play on words. Terrapins are a type of turtle, and trepanation is the process of drilling a hole in the skull to alleviate pressure and supposedly alleviate insanity, which is relevant in this quest chain.",
            date = "2010-12-15T19:16:55-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25063#comments:id=1236578",
        },
        {
            id = 1204548,
            score = 6,
            author = "398146",
            text = "Easy quest. Only took about 5 kills to get the key.\n\nIf you're a Duke fan, it's probably best you fear the turtle.",
            date = "2010-12-03T16:04:31-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25063#comments:id=1204548",
        },
        {
            id = 1683426,
            score = 6,
            author = "faerogue",
            text = "Kelsey has 2 quests before she offers you this one, killing Bilgewater survivors and finding the journal she's talking about in the quest text.",
            date = "2012-07-01T19:40:47-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25063#comments:id=1683426",
        },
        {
            id = 1698622,
            score = 2,
            author = "1020909",
            text = "Took me a minute to find the turtles, but then it only took 2 kills to get the key.",
            date = "2012-08-11T09:27:34-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25063#comments:id=1698622",
        },
        {
            id = 1615242,
            score = 1,
            author = "698549",
            text = "It isn't completely necessary to go past the goblin camp to get the key from a turtle. There are two turtles just off shore before you get to the camp. With a little luck you can kill one or both and the key will drop, saving you the trip back and forth through the hostiles.\n\nThe two turtles path off-shore around 49.0, 90.5.",
            date = "2012-01-22T16:54:29-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25063#comments:id=1615242",
        },
    },
    [25064] = {
