    [25070] = {
        {
            id = 2359428,
            score = 19,
            author = "Giovith",
            text = "Bugged as of latest patch as the guardian no longer spawns.",
            date = "2016-07-31T11:50:33-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25070#comments:id=2359428",
        },
        {
            id = 3284831,
            score = 14,
            author = "badgehunter",
            text = "This may not effect that many people but: be warned if you do this quest as lvl 15-20 because even though you entered this place from tanaris lvl 15-30 zone, the boss from this quest will follow uldum's level range. aka its minimum lvl is 30 and not 15. since uldums level range is lvl 30-35. I personally was able to kill the mob as lvl 20 since it had fairly low damage output, but i have access to self heal with regrowth which helped me to survive as moonfires damage over time dealt damage, as i just spammed moonfire followed by starsurge, i spammed moonfire since he was ? lvl to me, which meant most of my attacks were going to miss. so be warned if you don't have access to self heal and dont see the level of the boss. edit: you will see that he will follow uldum's lvl range since if you open map at chest, you will see that it defaults to uldum and while you were running to chest, the game showed areas you were in following order: ruins of uldum to tanaris to finally Uldum (contested territory) final edit: if you can deal with mobs in uldum without self heals like mage, you can most likely deal with this quest boss without self heals. this comment was meant to be for like lvl 15-24 accounts that dont see this bosses level. alternatively you can just grab a friend to heal/help you during fight.",
            date = "2021-01-03T07:02:33-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25070#comments:id=3284831",
        },
        {
            id = 5687316,
            score = 7,
            author = "xLunacyx",
            text = "Despite being in Chromie Time, the big guy who spawns when you loot the chest comes in at lv30, no matter what level you are.  Was wondering why I was getting slapped so hard to realize my lv20 was getting crushed by a lv30.",
            date = "2023-09-13T21:56:22-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25070#comments:id=5687316",
        },
        {
            id = 1211505,
            score = 6,
            author = "406368",
            text = "This quest is still bugged as of this posting.\n\nChest is still located outside of the ruins, yet nothing happens when you examine the chest or accept the quest.\n\nTested this several times while dropping quest, logging out, trying again.  I'd say the links to the next part of the quest are broken...\n\n*Laughing Skull (US)*",
            date = "2010-12-07T07:26:20-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25070#comments:id=1211505",
        },
        {
