    [25072] = {
        {
            id = 1618719,
            score = 36,
            author = "622035",
            text = "Ok, so I learned something while trying to do this quest trying to get the belt. If you haven't done any of the quests in this zone, then you can't just fly to the quest giver and pick up the quest.\nPick up the chain given by either Kelsey Steelspark or Megs Dreadshredder. Then pick up the quest chain with Momentum (both sides have the same quest name). After doing a handful of quests in the Lost Rigger Cove, you will get a quest that takes you to Zeke. Took me a while to figure it out as no one has pointed out the needed quest to open this quest up. Hope this helps! :3",
            date = "2012-01-29T21:55:23-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25072#comments:id=1618719",
        },
        {
            id = 1283932,
            score = 19,
            author = "Lorrain",
            text = "Deep purple and wiggly, they target in red (attackable) and are located all around the top surface of the hive (ground level) on the little purple hills with the claws, south of the questgiver.\nThis may seem a bit redundant to some, but after I cleared all the hives twice, finding nothing, then finding them by accident, I felt alittle clarity was in order.",
            date = "2011-01-08T11:27:54-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25072#comments:id=1283932",
        },
        {
            id = 1303848,
            score = 15,
            author = "698680",
            text = "Gives you 250 [faction=169] rep and no loss in [faction=87] rep.",
            date = "2011-01-22T04:49:47-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25072#comments:id=1303848",
        },
        {
            id = 1188266,
            score = 12,
