    [25073] = {
        {
            id = 1604853,
            score = 15,
            author = "304770",
            text = "Since there are no [class=2] or [class=6] versions of the quest chain that begins with https://www.wowhead.com/quest=24776, none of the Echo Isles quests unlock for these two classes.",
            date = "2011-12-31T19:42:32-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25073#comments:id=1604853",
        },
        {
            id = 1326629,
            score = 9,
            author = "lordmada",
            text = "as a tauren druid i got all of them and the orc starters too but it seems i can't get this one because I got the orc version",
            date = "2011-02-08T07:30:52-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25073#comments:id=1326629",
        },
        {
            id = 1996529,
            score = 7,
            author = "1361840",
            text = "I was able to do this quest yesterday as an Orc.  Here is how I did it:\n1. Did all the quest in the Valley of Trials to get the quest https://www.wowhead.com/quest=25133.  Turn it in to Master Gadrin.\n2. After you turned it in don't accept any further quest from him (I also didn't accept any other quest from Sen'jin Village).\n3. Head over to Echo Isles and do all the quest there leading up to https://www.wowhead.com/quest=24814.  After completing that quest I was able to pick up https://www.wowhead.com/quest=25073 from Vol'jin.\nI did all this as a fresh new character, so I don't know how it will work for a high level character.  Also, by the time I picked up the quest I was level 7.",
            date = "2014-08-26T15:12:35-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25073#comments:id=1996529",
        },
        {
            id = 1178990,
            score = 4,
            author = "707108",
            text = "West of Echo Isles across the water.",
            date = "2010-11-23T19:28:06-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25073#comments:id=1178990",
        },
        {
            id = 1219329,
            score = 4,
            author = "724683",
            text = "As a Blood Elf Paladin, I could not get any of the Echo Isles starter quests",
            date = "2010-12-09T17:42:56-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25073#comments:id=1219329",
        },
    },
    [25074] = {
        {
            id = 1200846,
            score = 27,
            author = "714139",
            text = "*spoiler*\n\nSad what happened to him. If anyone had the chance to hear his story about the attack on Camp Taurajo, you'll see that he tried to spare as many of the towns' civilians from the fray, despite his superiors' initial plan of attack. Here is part of the dialogue I managed to capture:\n\n\"...Taurajo had a significant civilian population. I wanted to ensure that they could escape the fighting, and many did, finding refuge in the north.\n\nThere are some, even in Alliance High Command, who argued that I let an opportunity slip away. That I should [have] taken hostages. But I don't see the value in those sort of terror-tactics.\n\nHear me out, [Player]: I want this war to end someday. It won't ever stop if we butcher or imprison civilians.\n\nI just pray that there are those on the other side who see things as I do.\"\n\nR.I.P, General. /salute",
            date = "2010-12-01T18:46:59-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25074#comments:id=1200846",
        },
        {
            id = 1219246,
            score = 24,
            author = "Sebiale",
            text = "The worst part is how the Alliance malign his memory by declaring a push against the Horde in his name, exactly what he WOULDN'T have wanted.",
            date = "2010-12-09T17:12:10-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25074#comments:id=1219246",
        },
        {
            id = 1207484,
            score = 19,
            author = "226304",
            text = "*Spoilers, of course.*\n\nYou'll be approached by Triumph Messenger when you near the first set of saluting guards.\n\n\"! You're alive! Have you heard?\"\n\n\"They killed him! General Hawthorne - he was ambushed on the road by Horde assassins.\"\n\nFurther down the road, which can easily be missed if you outpace the Messenger, he'll say an additional comment.\n\n\"His body was found strung up from a tree. Those animals... Those filthy animals!\"\n\nPretty brutal stuff they did to him.",
            date = "2010-12-05T04:08:15-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25074#comments:id=1207484",
        },
        {
            id = 1240868,
            score = 13,
            author = "wharris",
            text = "*spoilers*\n\nWhen I learned of Hawthorne's death, I suspected that he might have been killed by Ambassador Gaines instead of the Horde (what happened to him, anyway?).\n\nBut The Butcher of Taurajo (http://www.wowhead.com/quest=24637).",
            date = "2010-12-17T13:31:03-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25074#comments:id=1240868",
        },
        {
            id = 1516660,
            score = 9,
            author = "Liri",
            text = "Barton Trask says: Were he still alive to avenge himself, General Hawthorne would have no doubt ordered a retaliatory massacre of biblical proportions.\nCommander Roberts says: You are quite right, Trask.",
            date = "2011-09-12T22:52:26-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25074#comments:id=1516660",
        },
    },
