    [25094] = {
        {
            id = 1287779,
            score = 7,
            author = "terylbrat42",
            text = "I had the same thing happen to me as carfieldily. Does anyone know if this is a bug or if you only get one try?\n\nEdit: I logged out and when I logged back in I could get the quest again.",
