    [25107] = {
        {
            id = 1249970,
            score = 12,
            author = "mineka",
            text = "These hieroglyphs are undoubtedly titan, but the markings below it...\n\nIf I had to hope, this is the same passage written over and over again in an entire assortment of ancient languages. We might be able to use this to decipher the hieroglyphs!\n\nThis quest, and the rewards (Rosy Tablet belt (http://www.wowhead.com/item=56899)) are a reference to Rosetta Stone (http://en.wikipedia.org/wiki/Rosetta_Stone), an inscribed stone who permitted to dechiper hieroglyphs.\n\nThe text on the stone was written three times, in three different \"languages\" (hieroglyphs, egyptian demotic script and ancient greek).",
            date = "2010-12-21T08:44:50-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25107#comments:id=1249970",
        },
    },
