    [25112] = {
        {
            id = 1122495,
            score = 44,
            author = "Lysanna",
            text = "The Butcherbot is my new favorite NPC.  The things he says while he works are incredible.\n\n\"I want the arterieeeeeeeeees!\"\n\"Butcherbot will harvest meat, tra la la la la.\"\n\"Hooray for meat!  HIP HIP HOORAY!\"\n\nAnd my personal favorite:\n\"VWHHHHHRRRRRRRRRRRRHHHHHHMNNGHHHGH\"\n\nJust imagining the robot making that sound completely made my day.  When the Cataclysm comes, I won't be going to Vash'jir or Hyjal - I'll be headed to Gadgetzan.",
            date = "2010-09-18T00:59:46-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25112#comments:id=1122495",
        },
        {
            id = 1252459,
            score = 38,
            author = "bigearlx",
            text = "You know, I wish they would make a vanity pet of this guy. When there's a beast corpse nearby, he could have a chance to \"harvest\" it, which the blood and squelchy noises startling passersby, and say one of his hilarious lines and maybe hand you a low-value grey item of a random animal part with funny flavor text or something. The lines are the big thing, though - too hilarious to be confined to one brief quest chain...",
            date = "2010-12-22T12:29:56-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25112#comments:id=1252459",
        },
        {
            id = 1191242,
            score = 25,
            author = "585648",
            text = "Gives 250 rep for Gadgetzan and 150 rep for Booty Bay, Everlook and Ratchet.\nNo negative rep with Bloodsail though. Bonus!",
            date = "2010-11-27T18:19:23-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25112#comments:id=1191242",
        },
        {
            id = 1260985,
            score = 17,
            author = "567472",
            text = "For anyone else who doesn't figure out how to deploy the bot on the first try...here's how:\n\nSlay basilisk; loot; then be sure basilisk is still 'targeted' (highlighted), then left click the remote icon for the bot.",
            date = "2010-12-26T23:52:59-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25112#comments:id=1260985",
        },
        {
            id = 1329927,
            score = 16,
            author = "783367",
            text = "After doing this quest and reading the quotes, I can't help but be reminded of Gir from Invader Zim. While I was doing the quest I kept thinking to myself \"Man, this guy reminds me of someone.\"\n\nThen it said \"VWHHHHHRRRRRRRRRRRRHHHHHHMNNGHHHGH\" and I instantly shouted \"GIR!\"\n\nI mean seriously, you can't not see the similarities (http://www.youtube.com/watch?v=r258Jca9e0A#t=1m15s)",
            date = "2011-02-10T05:16:47-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25112#comments:id=1329927",
        },
