            author = "fawkesfire",
            text = "As of 7.3.5 I am unable to pick up this quest after having completed https://www.wowhead.com/quest=25129. I believe I do recall seeing the available quest icon before completing it, though it was no longer available after turning it in.",
            date = "2018-01-19T12:55:47-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25128#comments:id=2547018",
        },
        {
