    [25133] = {
        {
            id = 1996633,
            score = 3,
            author = "1361840",
            text = "As an Orc I was able to do this quest and https://www.wowhead.com/quest=25073(which is labled for BE, Trolls, and Taurens only).  Heres how I did it:\n1. Turn in this quest to Master Gadrin.\n2. After you turned it in don't accept any further quest from him (I also didn't accept any other quest from Sen'jin Village).\n3. Head over to Echo Isles and do all the quest there leading up to https://www.wowhead.com/quest=24814. After completing that quest I was able to pick up https://www.wowhead.com/quest=25073 from Vol'jin.\nI did all this as a fresh new character, so I don't know how it will work for a high level character. Also, by the time I picked up the quest I was level 7.",
            date = "2014-08-26T19:51:00-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25133#comments:id=1996633",
        },
        {
