    [25135] = {
        {
            id = 1192578,
            score = 23,
            author = "690501",
            text = "It's located at 43.73, 53.78.\nFor those without coords, follow the water to the top. The axe is shed in a holy light; hard to miss.",
            date = "2010-11-28T06:39:25-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25135#comments:id=1192578",
        },
        {
            id = 1734369,
            score = 9,
            author = "djsdjs",
            text = "After having done this quest too many times across many characters, something occurred to me with my monk character... just what business did Foreman Thazz'ril have being in that cave? Is he actually a secret member of the Burning Blade Coven, scouting for fresh, young, & naive orcs with malleable minds that might be  persuaded to join? There's something sinister in there somewhere.",
            date = "2012-10-07T10:13:46-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25135#comments:id=1734369",
        },
        {
            id = 1395335,
            score = 8,
            author = "Sunreaver",
            text = "Apparently you have to complete Vile Familiars (http://www.wowhead.com/quest=25131) before this will appear.",
            date = "2011-04-19T23:46:11-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25135#comments:id=1395335",
        },
        {
            id = 1371227,
            score = 4,
            author = "Pypode",
            text = "Cave in Valley of Trials, entrance at 45.56. Vile Familiars (L-3) all around the area.",
            date = "2011-03-19T22:56:02-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25135#comments:id=1371227",
        },
        {
            id = 1954708,
            score = 3,
            author = "Krastopic",
            text = "To add a bit of clarity.  You will go to the cave as indicated.  You will be doing other quests inside.  There are Vile Familiars and Felstalkers inside.  It is also where you will kill Yarrog Baneshadow for collection of a medallion (Quest: Burning Blade Medallion Part 1).  This is a cave you should have already been to with the quest progression provided.  While in the cave, you will have noticed a stream running downhill toward the base with your killed Baneshadow for the Medallion.   If you follow the stream up-river (it easier if you run in the stream part of the way), it will eventually end with a small waterfall.  A few steps north of that you will see the pick basking in light and pick-me-up-I-am-treasure sparklies.  Quest complete.\n\nKrastopic",
            date = "2014-03-29T23:28:20-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25135#comments:id=1954708",
        },
    },
    [25136] = {
        {
            id = 1684022,
            score = 3,
            author = "859843",
            text = "Now son, don't touch that cactus!",
            date = "2012-07-03T11:09:49-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25136#comments:id=1684022",
        },
        {
            id = 5825043,
            score = 1,
            author = "2555006",
            text = "It took me about 10 minutes after accepting the quest before the apples started to spawn. Being the only player in the area this was really a surprise and maybe related to the character being a Blood Elf. So if you see no apples, wait for a while and they just might appear.",
            date = "2024-04-12T00:48:03-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25136#comments:id=5825043",
        },
        {
