    [25151] = {
        {
            id = 1181209,
            score = 42,
            author = "378236",
            text = "Tapped from a keg.\n\nenter, go right,  make a left, follow hall to the end. (don't go down into the basement)  Keg is on the table.",
            date = "2010-11-24T11:03:25-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25151#comments:id=1181209",
        },
        {
            id = 1905273,
            score = 16,
            author = "CantThinkOfOne",
            text = "Poor guy didn't even finish his entire mug. :c",
            date = "2013-10-03T20:39:02-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25151#comments:id=1905273",
        },
        {
            id = 1676099,
            score = 13,
            author = "Comickhazi",
            text = "Gah.. The writing in this quest really struck me.\nI think I got a little something in my eye..",
            date = "2012-06-12T18:57:23-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25151#comments:id=1676099",
        },
        {
            id = 1306287,
            score = 8,
            author = "cynberly",
            text = "I found it at 50, 85 behind a little bar.\n\nFacing the Keep, go LEFT into the keep.\nTurn right.\nStraight ahead, don't go down, just straight ahead was the little bar.  The keg was behind the bar for me, on the ground.  Not sure if this has several spawn locations.\nIt's on the opposite side of where you go to find the dead goblin body, if that helps get your bearings.",
            date = "2011-01-23T13:49:54-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25151#comments:id=1306287",
        },
        {
            id = 1931418,
