        },
        {
            id = 1457453,
            score = 4,
            author = "cephadex",
            text = "When you go into the building, head RIGHT, then an immediate left. He is a goblin lying on the floor next to a block of cheese. Note: going into this building causes you to take damage rather quickly so be quick or have some sort of protection. As of July 1, 2011, I did not have a bug with this quest on Chamber of Aspects EU.",
            date = "2011-07-01T19:10:05-05:00",
