    },
    [25165] = {
        {
            id = 2255150,
            score = 54,
            author = "MADmanSpins",
            text = "EASIEST workaround for hunters or high lvl toons to complete this:\n(Need a mount)\nNo need to get naked or stable your pet.\nRide directly up to scorpion on your mount, DO NOT dismount.\nLet scorpion start attacking you until prompt for totem appears then place it down.\nVoila!\n\nHope this helps, happy questing! =)",
            date = "2015-09-21T14:50:12-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25165#comments:id=2255150",
        },
        {
            id = 1179195,
            score = 27,
            author = "DarthEnder",
            text = "This quest is hard to do at level 80...",
            date = "2010-11-23T20:50:11-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25165#comments:id=1179195",
        },
        {
            id = 1194196,
            score = 20,
            author = "262388",
            text = "Can't seem to do this quest as a lvl 6 troll hunter.  I have no pet bar or ability to dismiss the pet until lvl 10, so cannot stop it from killing the scorpion or pulling aggro.  I'd have to put it in combat and run away and hope it gets auto dismissed in order to even get this to work, but it kills too damn fast.  Ended up dropping the quest and moving on.",
            date = "2010-11-28T18:40:29-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25165#comments:id=1194196",
        },
        {
            id = 1179007,
            score = 12,
            author = "707108",
            text = "Attack a Clattering Scorpid, at about 50% health it will start casting Envenom. Drop your totem and when the cast is over you will get credit for 1 sample of venom.",
            date = "2010-11-23T19:40:03-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25165#comments:id=1179007",
        },
        {
            id = 1361368,
            score = 11,
            author = "marabean",
            text = "Just completed this quest with my level 50 druid, and it seems they've changed the way envenom works: the mob no longer needs to be at 50% health to cast it.  I aggroed the scorpid, let it wail on me for about 8-10 secs (without damaging it) and it cast its poison just fine.  I dropped the totem before the cast went off, and got credit each time.\n\nOne tip: try to fight these scorpids away from Sen'jin Village, as the overzealous lvl 85 guards will aggro and one-shot them before you have a chance to extract the poison.",
            date = "2011-03-08T15:27:24-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25165#comments:id=1361368",
        },
    },
    [25166] = {
        {
            id = 1186958,
            score = 7,
            author = "629371",
            text = "Found on the ship at 70.96, 55.25.\n\nAlso summons a non-elite Tidecrusher. Easily soloable.",
            date = "2010-11-26T06:45:39-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25166#comments:id=1186958",
        },
        {
            id = 1578108,
            score = 4,
            author = "438574",
            text = "Dreadbeard is Level ? (Boss), but don't let that scare you, he IS Boss level, but scaled for 45s (His base level is ~48 ish.) and he's very soloable. It's funny though to watch an 85 try this and get a string of missed attacks. (And then get burned by Deathwing as he burns Tanaris TO THE GROUND again)",
            date = "2011-11-22T04:20:29-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25166#comments:id=1578108",
        },
        {
            id = 1878682,
            score = 3,
            author = "taraad",
            text = "to get this quest you have to start with Kelsey Steelspark in Gadgetzan.",
            date = "2013-07-19T16:59:27-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25166#comments:id=1878682",
        },
        {
            id = 1687872,
            score = 2,
            author = "SoupyTwist",
            text = "Upon quest turn-in:\n\nHe was controlling a sea giant? Fascinating. If we'd managed to investigate further...\n\nOh, I mean, wow, that's totally crazy! But thank goodness he's gone, hooray! Mister Noggenfogger will be so pleased.\n\nHere's a big reward, you!",
            date = "2012-07-14T02:23:33-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25166#comments:id=1687872",
        },
        {
            id = 1304103,
            score = 1,
            author = "687273",
            text = "Oh wow, easiest guy to kill ever.\n\nWas on my mage, had a Fingers of Frost proc running out, so naturally I didn't want to waste it.\nIce Lance this guy while I'm on the plank, I start running down, water elemental starts shooting off at him.\nHe gets on the giant, but the giant doesn't aggro onto me or the water elemental.\nNuked him while he was on top of the giant, he dies, quest complete, giant despawns.",
            date = "2011-01-22T10:16:08-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25166#comments:id=1304103",
        },
    },
    [25167] = {
        {
            id = 1157607,
            score = 4,
            author = "Rotab",
            text = "If you attack the crate which only one is lugging, it falls down and kills the lugger.",
            date = "2010-10-31T12:11:23-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25167#comments:id=1157607",
        },
        {
            id = 1226211,
            score = 4,
            author = "TrooperOfDrenden",
            text = "On servers with lots of lowbies, this one takes quite a while to complete. Earlier I had witnessed 7 or 8 people crowded around these spawns with the mobs pretty much instantly dying.\n\nMy recommendation is to go for the crates first (if you're ranged), and then go for the humans, though it may take a bit. If you're melee, I dunno what to tell you, camp one of the particular spawns, as they spawn from two places, and try to get the crates first, though it may be a little more tricky.\n\nGood luck if you're on one of the New Player servers! You will need it...",
            date = "2010-12-12T00:21:13-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25167#comments:id=1226211",
        },
        {
            id = 1179022,
            score = 3,
            author = "707108",
            text = "South of Sen'jin village there is a small alliance camp. Northwatch Lug's will spawn carrying a crate. Just kill everything.",
            date = "2010-11-23T19:45:22-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25167#comments:id=1179022",
        },
        {
            id = 1998468,
            score = 3,
            author = "Droidem",
            text = "I don't know how I feel as a Main Alliance doing this quest. I've always thought that Thrall's Horde and even Vol'jin's Horde wouldn't have you attack a medical supply route. That sounds more like a Garrosh's Horde.",
            date = "2014-09-01T22:57:02-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25167#comments:id=1998468",
        },
        {
            id = 3292088,
            score = -3,
            author = "2201631",
            text = "Here is the full storyline quest and broadcast text, played as a [race=27] [class=8].\n\nStoryline Overview:\n>https://www.wowhead.com/quest=25167\nhttps://www.wowhead.com/quest=25168\nhttps://www.wowhead.com/quest=25169\nhttps://www.wowhead.com/quest=25171\n\nLocation: Sen'jin Village in [zone=14]\n\nhttps://www.wowhead.com/npc=3188:Aw man, this ain't good. Not one bit, mon.\n\nThrall's off to sea, Vol'jin's taking care of business in Echo Isles, and old Master Gadrin is left behind to take care of Sen'jin. And then what happens? Those humans come outta Northwatch Hold and set up camp in our backyard!\n\nLucky for us, they just got here, and they're still setting up their base. You can help out old Gadrin by destroying those big supply crates they carry, and by killing the laborers carryin' them. You'll find'm to the southwest.\n\nLocation: [zone=14]\n\n[Destroy 3 https://www.wowhead.com/npc=39251s and kill 10 https://www.wowhead.com/npc=39245s.]\n\nLocation: Sen'jin Village in [zone=14]\n\nhttps://www.wowhead.com/npc=3188:Well, we've stymied their efforts for now, but they're still here.  We'll have to press on, .\n\nNorthwatch is a highly-defended stronghold southwest of here, across the harbor. It's a strategically-located stronghold that the Horde still struggles to overtake. We don't need the humans setting up another Northwatch here in Durotar.\n\nSweep through the valley to the west and slay these humans, . Let them know the power and the fury of Sen'jin.\n\nLocation: Northwatch Foothold in [zone=14]\n\n[Defeat 12 Northwatch troops in Northwatch Foothold.]\n\nLocation: Sen'jin Village in [zone=14]\n\nhttps://www.wowhead.com/npc=3188:A battle well-fought, , but I still have my doubts about our effectiveness.  These humans don't seem to be going anywhere.\n\nYou, however, have done more than could reasonably be asked of any loyal member of the Horde.  Thank you.\n\nhttps://www.wowhead.com/npc=3140:These humans in the west, they don't just wanna camp out in Durotar, mon. They got bigger plans, and those plans involve takin' our home and leavin' our skulls on pikes.\n\nWell I'm not havin' it. Nope! Not Lar! I've got family here in Sen'jin, and I'll be damned if I let one of those brutes put my Tai'tasi's head on a stick!\n\nThey've got their plans written down in there, mon. Big scrolls, real important-lookin'. We gonna burn those scrolls before they burn us.\n\nLocation: Northwatch Foothold in [zone=14]\n\n[Destroy the 3 sets of Attack Plans held within Northwatch Foothold.]\n\nLocation: Sen'jin Village in [zone=14]\n\nhttps://www.wowhead.com/npc=3140:Good work, hero.  You done good for Sen'jin today.  No... you done good for all of Durotar.\n\nhttps://www.wowhead.com/npc=3188:We gotta pass the word on to Razor Hill. These humans may be defeated today, but tomorrow they'll come again, and when they do, we'll need help from the orcs.\n\nSpeak with Jhash, outside the gates of Sen'jin. He'll give you a ride to Razor Hill. His wolves know the path well.\n\nhttps://www.wowhead.com/npc=10676:Need something?\n\nPlayer Character:Can I catch a ride to Razor Hill?\n\n[Speak to https://www.wowhead.com/npc=10676 to get a ride to Razor Hill. Once there, speak with https://www.wowhead.com/npc=3139.]\n\nLocation: Razor Hill in [zone=14]\n\nhttps://www.wowhead.com/npc=3139:That troll wants us to send help?  Bah, he can forget it.  I've got my own human problems to worry about, and even those are the least of my worries right now.\n\nSen'jin Village is right next to Echo Isles and the Valley of Trials.  Old Gadrin should find plenty of youngbloods to help him with his human infestation.",
            date = "2021-01-18T02:56:48-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25167#comments:id=3292088",
        },
    },
    [25168] = {
        {
            id = 1908287,
            score = 8,
            author = "Ztrikes",
            text = "\"..Is a highly-defended, strategically placed stronghold southwest of here that the horde still struggles to overtake.\"\n\nThey send a newblood that barely knows how to fight to do this?",
            date = "2013-10-13T15:18:43-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25168#comments:id=1908287",
        },
        {
            id = 1181107,
            score = -1,
            author = "odilon29",
            text = "Old centaur place at 49.79.\nTerrible respawn rate.",
            date = "2010-11-24T10:30:03-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25168#comments:id=1181107",
        },
        {
            id = 3292089,
            score = -3,
            author = "2201631",
            text = "Here is the full storyline quest and broadcast text, played as a [race=27] [class=8].\n\nStoryline Overview:\nhttps://www.wowhead.com/quest=25167\n>https://www.wowhead.com/quest=25168\nhttps://www.wowhead.com/quest=25169\nhttps://www.wowhead.com/quest=25171\n\nLocation: Sen'jin Village in [zone=14]\n\nhttps://www.wowhead.com/npc=3188:Aw man, this ain't good. Not one bit, mon.\n\nThrall's off to sea, Vol'jin's taking care of business in Echo Isles, and old Master Gadrin is left behind to take care of Sen'jin. And then what happens? Those humans come outta Northwatch Hold and set up camp in our backyard!\n\nLucky for us, they just got here, and they're still setting up their base. You can help out old Gadrin by destroying those big supply crates they carry, and by killing the laborers carryin' them. You'll find'm to the southwest.\n\nLocation: [zone=14]\n\n[Destroy 3 https://www.wowhead.com/npc=39251s and kill 10 https://www.wowhead.com/npc=39245s.]\n\nLocation: Sen'jin Village in [zone=14]\n\nhttps://www.wowhead.com/npc=3188:Well, we've stymied their efforts for now, but they're still here.  We'll have to press on, .\n\nNorthwatch is a highly-defended stronghold southwest of here, across the harbor. It's a strategically-located stronghold that the Horde still struggles to overtake. We don't need the humans setting up another Northwatch here in Durotar.\n\nSweep through the valley to the west and slay these humans, . Let them know the power and the fury of Sen'jin.\n\nLocation: Northwatch Foothold in [zone=14]\n\n[Defeat 12 Northwatch troops in Northwatch Foothold.]\n\nLocation: Sen'jin Village in [zone=14]\n\nhttps://www.wowhead.com/npc=3188:A battle well-fought, , but I still have my doubts about our effectiveness.  These humans don't seem to be going anywhere.\n\nYou, however, have done more than could reasonably be asked of any loyal member of the Horde.  Thank you.\n\nhttps://www.wowhead.com/npc=3140:These humans in the west, they don't just wanna camp out in Durotar, mon. They got bigger plans, and those plans involve takin' our home and leavin' our skulls on pikes.\n\nWell I'm not havin' it. Nope! Not Lar! I've got family here in Sen'jin, and I'll be damned if I let one of those brutes put my Tai'tasi's head on a stick!\n\nThey've got their plans written down in there, mon. Big scrolls, real important-lookin'. We gonna burn those scrolls before they burn us.\n\nLocation: Northwatch Foothold in [zone=14]\n\n[Destroy the 3 sets of Attack Plans held within Northwatch Foothold.]\n\nLocation: Sen'jin Village in [zone=14]\n\nhttps://www.wowhead.com/npc=3140:Good work, hero.  You done good for Sen'jin today.  No... you done good for all of Durotar.\n\nhttps://www.wowhead.com/npc=3188:We gotta pass the word on to Razor Hill. These humans may be defeated today, but tomorrow they'll come again, and when they do, we'll need help from the orcs.\n\nSpeak with Jhash, outside the gates of Sen'jin. He'll give you a ride to Razor Hill. His wolves know the path well.\n\nhttps://www.wowhead.com/npc=10676:Need something?\n\nPlayer Character:Can I catch a ride to Razor Hill?\n\n[Speak to https://www.wowhead.com/npc=10676 to get a ride to Razor Hill. Once there, speak with https://www.wowhead.com/npc=3139.]\n\nLocation: Razor Hill in [zone=14]\n\nhttps://www.wowhead.com/npc=3139:That troll wants us to send help?  Bah, he can forget it.  I've got my own human problems to worry about, and even those are the least of my worries right now.\n\nSen'jin Village is right next to Echo Isles and the Valley of Trials.  Old Gadrin should find plenty of youngbloods to help him with his human infestation.",
            date = "2021-01-18T02:57:42-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25168#comments:id=3292089",
        },
    },
    [25169] = {
        {
            id = 1109279,
            score = 13,
            author = "Kyuudo",
            text = "This quest's name is a reference to the phrase \"The War of Northern Aggression\", which is a name used predominantly by certain Southerners to describe the Civil War.\n\nThe Valley of Trials plans spawn in the camp to the immediate left of entering Northwatch Foothold, in between the navy blue tent in the back and a canvas one. The Sen'jin plans spawn on a crate in a camp further into the valley on the right, and the Orgrimmar plans spawn in the very last camp, inside the navy blue tent.",
            date = "2010-08-27T22:42:43-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25169#comments:id=1109279",
        },
        {
            id = 1803818,
            score = 8,
            author = "317714",
            text = "If you're having trouble finding Attack Plan: Orgrimmar, it is on the ground inside the blue tent in the area marked on the map above (on the right as you enter tent).",
            date = "2013-01-25T04:33:54-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25169#comments:id=1803818",
        },
        {
            id = 5552393,
            score = 7,
            author = "ThatOneSPriest",
            text = "should be noted that the fire traps the marksmen are placing out *can kill you*. Happened to me a couple of times >.<",
            date = "2023-02-19T14:40:04-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25169#comments:id=5552393",
        },
        {
            id = 1183385,
            score = 5,
            author = "darknesscalls",
            text = "First they had level 8 centaurs wanting to invade Orgrimmar.\n\nNow level 6 northwatch humans are going to attempt the very same thing?\n\nThese poor fools....",
            date = "2010-11-25T00:36:24-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25169#comments:id=1183385",
        },
        {
            id = 1938751,
            score = 3,
            author = "69027",
            text = "Spawntimer on these are about 10 seconds.. (Started counting since another player got to 'em just before me..)",
            date = "2014-01-28T13:30:44-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25169#comments:id=1938751",
        },
    },
    [25170] = {
        {
            id = 1178998,
            score = 4,
            author = "707108",
            text = "The crabs are on the coastline of Sen'jin Village.",
            date = "2010-11-23T19:34:49-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25170#comments:id=1178998",
        },
        {
            id = 2306603,
            score = 1,
            author = "Zerion123",
            text = "Cleaning Up the Coastline https://youtu.be/97KTwwLMVAg",
            date = "2016-02-14T12:57:46-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25170#comments:id=2306603",
        },
        {
            id = 3292014,
            score = 1,
            author = "2201631",
            text = "Here is https://www.wowhead.com/npc=10578's storyline quest text, played as a Nightborne Mage.\n\nStoryline Overview:\n>https://www.wowhead.com/quest=25170\nhttps://www.wowhead.com/quest=25165\n\nLocation: Sen'jin Village in [zone=14]\n\nhttps://www.wowhead.com/npc=10578:Heya mon! Bom'bay be workin' on some new mojo. You wanna try a piece of it? Well, before ya do, Bom'bay's gonna need ya to pick up some jujus.\n\nFirst, Bom'bay needs ya to get some o' the goop from the crabs down by the water. Let me see your hands!\n\nBom'bay gonna need 5 handfuls. Go on now!\n\nLocation: Darkspear Strand in [zone=14]\n\n[Obtain 5 handfuls of https://www.wowhead.com/item=4888.]\n\nLocation: Sen'jin Village in [zone=14]\n\nhttps://www.wowhead.com/npc=10578:You bring the jujus, I show you my mojo.\n\nYa mon, that's tha stuff.  Now we get the other jujus.\n\nNext, we gonna get some poison from the scorpions that be runnin' around here. But don't you worry, Bom'bay's not gonna let you get hurt!\n\nBom'bay's got a big totem that you gonna stick in the ground when the scorpion strikes. The totem gonna suck up all the poison, and you gonna walk away still breathing. Sound good?\n\nLocation: Sen'jin Village Outskirts in [zone=14]\n\n[Obtain 6 samples of Scorpid Venom by placing the https://www.wowhead.com/item=52505 near a https://www.wowhead.com/npc=3125.]\n\nLocation: Sen'jin Village in [zone=14]\n\nhttps://www.wowhead.com/npc=10578:This is it!  The scorpid juju Bom'bay been waitin' for!  Now we gonna fix you right up, .\n\nYou come back to Bom'bay when you be needin' a pickup.  Bom'bay got the spells to fix ya!",
            date = "2021-01-17T22:25:02-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25170#comments:id=3292014",
        },
    },
    [25171] = {
        {
