        {
            id = 1703494,
            score = 11,
            author = "xepla",
            text = "Here's what she says if you're playing a female character:\n\nDescription\nWhat're you looking at, ugly? I've seen you walking around Razor Hill, trying to steal MY men from me!\n\nListen, I've got something for you to do. I hear Gar'Thok's got you headed over to Tiragarde. While you're there, think you could find some abandoned Kul Tiras knicknacks?\n\nDon't ask why, just get to it!\n\nProgress\n\nCompletion\nAbout time you showed up. Don't even think about stealing that treasure... it's worthless here in Kalimdor, anyhow.",
            date = "2012-08-23T15:31:43-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25176#comments:id=1703494",
        },
        {
            id = 1426288,
            score = 10,
            author = "809756",
            text = "To open this quest line you need to do these quests from: Master Gadrin in Sen'Jin Village:\n1-Breaking the Chain\n2-Purge the Valley\n\nThen you need this quest from Lar Prowltusk called:\n3-The War of Northwatch Aggression\n\nThis opens another quest from Gadrin again called:\n4-Riding On\n\nwhich will take you to Razor Hill.\n\nOnce you hand in 'Riding On' to Gar'Thok, you can then do Gail Nozzywig's quests (among others).",
            date = "2011-05-24T13:05:29-05:00",
