    [25178] = {
        {
            id = 1357647,
            score = 28,
            author = "169059",
            text = "this is the first time ive seen a quest text change so drastically depending on what your charactors gender was.",
            date = "2011-03-04T19:23:07-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25178#comments:id=1357647",
        },
        {
            id = 1703501,
            score = 8,
            author = "xepla",
            text = "IF FEMALE:\n\nDescription:\nYou! Stop right there, you tramp! I'm not finished with you yet.\nI hear you're headed off to the shore east of here. The beach is filled with crashed ships, and those ships have gnomish tools in them... tools that I can use.\nGet cracking, missy!\n\nProgress:\nWell?\n\nCompletion:\nWell, I suppose you're not completely useless. Now stay away from my men!",
            date = "2012-08-23T15:44:45-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25178#comments:id=1703501",
        },
        {
            id = 1269846,
            score = 5,
            author = "zingar",
            text = "\"You really know how to treat a girl, you know that?  If you ever need anything... \"\n\ndoes she say that to girl characters as well?",
            date = "2010-12-31T14:38:31-06:00",
