    [25183] = {
        {
            id = 1349879,
            score = 19,
            author = "Vyola",
            text = "To do this quest you need first complete the following group of quests:\n1. Digsite Status (http://www.wowhead.com/quest=25104) that send you to Marley Twinbraid (http://www.wowhead.com/npc=39155).\n\n2. Then complete all Marley's quests\nFeegly the Exiled (http://www.wowhead.com/quest=25108)\nHands Off Me Dig! (http://www.wowhead.com/quest=25106)\nMarley's Final Flight (http://www.wowhead.com/quest=25120)\n\n3. After complete the final flight quest, Wounded Bael'dun Officer will open a small chain of 3 quests, the second step will send you back to General Twinbraid\nWho did this? (http://www.wowhead.com/quest=25163)\nTwinbraid Needs to Know (http://www.wowhead.com/quest=25174)\nKill 'em All! (http://www.wowhead.com/quest=25182)\n\nAfter complete Twinbraid Needs to Know, you finally will see available the quest ...And Bury the Rest.",
            date = "2011-02-25T15:11:15-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25183#comments:id=1349879",
        },
