    [25190] = {
        {
            id = 1179423,
            score = 13,
            author = "330986",
            text = "Good, good.  One step closer to eliminating those beady-eyed, basket-wearing, hog-nosed, two-toed...\n\n...hunchbacked, squealing, prickly... no-good... gnome-loving... GREEEAAAAGH! Quillboar!",
            date = "2010-11-23T22:19:10-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25190#comments:id=1179423",
        },
        {
            id = 1799400,
            score = 6,
            author = "984218",
            text = "Low-level players should keep an eye out for Captain Flat Tusk (http://www.wowhead.com/npc=5824) during this quest, as one of his spawn locations is quite close to the mobs you are sent to kill.",
            date = "2013-01-16T09:23:59-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25190#comments:id=1799400",
        },
        {
            id = 2375005,
            score = -1,
            author = "Aliandrin",
            text = "The quest dialogue reads thus:\n\n\"The Quillboar are a stain on the land that not even the river can wash away. They told me to evacuate, but I told them that my job was not yet done.\"\n\nEmphasis added. Very poor use of the word they. Here is how I read this:\n\nThe Quillboar tell Raggaran to evacuate.\n\nRaggaran refuses.\n\nRaggaran's house is destroyed in the flood.\n\nRaggaran now seeks vengeance against the Quillboar.\n\nIt's all perfectly logical if you're a stubborn Orc. They should have tried to save him. All they did was use those \"words\" things. How was he supposed to know they were serious?",
            date = "2016-08-29T00:27:31-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25190#comments:id=2375005",
        },
    },
