    [25196] = {
        {
            id = 5310394,
            score = 26,
            author = "DCCXVIII",
            text = "If you're wondering why you can't find the NPC to complete this quest, it's because the Legion intro quest phase is interfering and de-phasing him when you get near. You need to complete the Legion intro quests outside of Org to revert the area back to a phase where you can see this NPC.\n\nAnd yes, the Legion intro quest will still de-phase him despite not picking it up to begin with. So go pick it up from the calling board and complete it.",
            date = "2022-01-17T09:47:45-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25196#comments:id=5310394",
        },
        {
            id = 5618240,
            score = 12,
            author = "Polygoncoke",
            text = "It's 2023. Why are these phasing issues persisting? Can't they just set up a Zidormi NPC and be done with it?\n\nI've chosen Cata (read: Classic) Timewalking campaign, so why do I still have to see any of these Legion NPCs anyway?\n\nFor the record, I am on a level 11 character. I'm guessing you might not have this problem if you've not yet hit 10.\n\nAs others have said, you have to clear the legion quests to unphase the NPC you need for this quest. You need to be in Legion timewalking campaign to do that.",
            date = "2023-05-27T18:55:53-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25196#comments:id=5618240",
        },
        {
            id = 1198017,
