    [25199] = {
        {
            id = 1049102,
            score = 6,
            author = "thelaks",
            text = "Drill Sergeant is on the right as you came into camp, with a bunch of recruits. Stand and listen to him, he will ask you to emote a salute, roar, dance and cheer at him",
            date = "2010-05-30T18:09:38-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25199#comments:id=1049102",
        },
        {
            id = 983912,
            score = 5,
            author = "Zorie",
            text = "Seems like this is the quest for gnomes to recapture Gnomeregan (Gnomes old capital)",
            date = "2010-02-23T19:36:01-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25199#comments:id=983912",
        },
        {
            id = 1006354,
            score = 3,
            author = "Trolian",
            text = "I'm warning you though, it's tough over there.\nHow is saluting, roaring, cheering and dancing tough?\nI'm just sayin'.",
            date = "2010-03-27T10:01:09-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25199#comments:id=1006354",
        },
        {
            id = 1115889,
            score = 3,
            author = "error10",
            text = "Start by picking up the quest A Few Good Gnomes (http://www.wowhead.com/quest=25229) from High Tinker Mekkatorque (http://www.wowhead.com/npc=7937) in Tinker Town, Ironforge.\n\nPart of this quest chain can be completed at level 1. The final two quests, which involve retaking the surface of Gnomeregan, require level 75. Turning in the final quest (http://www.wowhead.com/quest=25393) grants the achievement Operation: Gnomeregan (http://www.wowhead.com/achievement=4786), which is listed as a Feat of Strength.\n\nThe full quest chain is:\n\nA Few Good Gnomes (http://www.wowhead.com/quest=25229)\nBasic Orders (http://www.wowhead.com/quest=25199)\nIn and Out (http://www.wowhead.com/quest=25285)\nOne Step Forward... (http://www.wowhead.com/quest=25289)\nPress Fire (http://www.wowhead.com/quest=25295)\nVent Horizon (http://www.wowhead.com/quest=25212)\nPrepping the Speech (http://www.wowhead.com/quest=25283)\nWords for Delivery (1) (http://www.wowhead.com/quest=25500)\n\nGoing forward requires level 75:\n\nWords for Delivery (2) (http://www.wowhead.com/quest=25287)\nOperation: Gnomeregan (http://www.wowhead.com/quest=25393)",
            date = "2010-09-08T04:34:22-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25199#comments:id=1115889",
        },
        {
            id = 1116195,
            score = 3,
            author = "malfu",
            text = "/salute\n/roar\n/cheer\n/dance\n\nuse those emotes when the PNJ is asking you to",
            date = "2010-09-08T11:31:17-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25199#comments:id=1116195",
        },
    },
    [25205] = {
        {
            id = 1121019,
            score = 87,
            author = "TwistedRoses",
            text = "Do NOT make the same mistake I did. I looked on my map and went to the spot it shows on the map thinking that is where the quest starts but it is NOT. The Orc next to the one that gives you the quest is who you talk to to then, run to the spot on your map.\n\nHope this helps!",
            date = "2010-09-15T04:17:16-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25205#comments:id=1121019",
        },
        {
            id = 1320309,
            score = 37,
            author = "444904",
            text = "This is the story of the stealthed rogue ready to pounce on the duel winner only to be ganked himself.\n\nYou've been warned.",
            date = "2011-02-03T10:02:09-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25205#comments:id=1320309",
        },
        {
            id = 1200747,
            score = 24,
            author = "283693",
            text = "One of the many quests that indirectly talks about the struggle between the old Thrall Horde and new Garrosh Horde. These tensions are more explained in the novel The Shattering, and are trickling into the player storyline as well.\n\nIf you're new to wow and interested in lore and story, pay attention to these little bits! It's all based on a large theme that will expand from now until a few content patches ahead!",
            date = "2010-12-01T17:46:09-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25205#comments:id=1200747",
        },
        {
            id = 1209447,
            score = 22,
            author = "entropicdragon",
            text = "(Spoiler Alert!)\nHere is the story of The Wolf and the Kodo, which is told, uh, interactively.\n It starts with a standard dialog box of\nCan you tell me your fable, Shin?\nbut continues on in raid-warning style alerts as you journey eastward as The Wolf:\n\nOne day, The Wolf was very hungry, so he ran east to look for some food.\nThe Wolf found scorpid meat to be too bitter.\nHe scoured the sands of Durotar, hunting for his prey.\nThe Wolf ran and ran, looking for an easy meal.\nThe Wolf did not care for raptor meat.\nThe Wolf was lazy, and didn't want to work for his meal.\nThe Wolf had grown tired of eating boar meat.\nThe more he ran, the more his stomach growled.\nHe happened upon a pair of battling kodos.\nClever as he was, The Wolf decided to wait for one to defeat the other.\nWhen the weaker Kodo died, The Wolf approached and tried to eat it.\nThe remaining Kodo, angry at The Wolf's impetuousness, swiftly killed The Wolf before he had a chance to eat.\n\nYou are then returned to Shin.",
            date = "2010-12-06T02:03:51-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25205#comments:id=1209447",
        },
        {
            id = 1817566,
            score = 20,
            author = "stonegirl11",
            text = "The moral here is, \"Wait until the victor leaves BEFORE you start eating the loser\".",
            date = "2013-02-24T04:36:47-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25205#comments:id=1817566",
        },
    },
