    [25229] = {
        {
            id = 984172,
            score = 12,
            author = "Mudskipper",
            text = "Reference to movie \"A few good men\" ?",
            date = "2010-02-24T05:33:42-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25229#comments:id=984172",
        },
        {
            id = 1115885,
            score = 11,
            author = "error10",
            text = "Start by picking up the quest A Few Good Gnomes (http://www.wowhead.com/quest=25229) from High Tinker Mekkatorque (http://www.wowhead.com/npc=7937) in Tinker Town, Ironforge.\n\nPart of this quest chain can be completed at level 1. The final two quests, which involve retaking the surface of Gnomeregan, require level 75. Turning in the final quest (http://www.wowhead.com/quest=25393) grants the achievement Operation: Gnomeregan (http://www.wowhead.com/achievement=4786), which is listed as a Feat of Strength.\n\nThe full quest chain is:\n\nA Few Good Gnomes (http://www.wowhead.com/quest=25229)\nBasic Orders (http://www.wowhead.com/quest=25199)\nIn and Out (http://www.wowhead.com/quest=25285)\nOne Step Forward... (http://www.wowhead.com/quest=25289)\nPress Fire (http://www.wowhead.com/quest=25295)\nVent Horizon (http://www.wowhead.com/quest=25212)\nPrepping the Speech (http://www.wowhead.com/quest=25283)\nWords for Delivery (1) (http://www.wowhead.com/quest=25500)\n\nGoing forward requires level 75:\n\nWords for Delivery (2) (http://www.wowhead.com/quest=25287)\nOperation: Gnomeregan (http://www.wowhead.com/quest=25393)",
            date = "2010-09-08T04:27:07-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25229#comments:id=1115885",
        },
        {
            id = 984035,
            score = 10,
            author = "ZookCloak",
            text = "The initial quest in an Alliance chain that involves the long-awaited recapture of Gnomeregan for the Gnomeregan Exiles.\n\nIt is unclear at this point whether or not this means Gnomes will have their own capital city and/or starting zone, however.\n\nThe Horde-equivalent chain involves retaking the Echo Isles for the Darkspear Trolls.\n\nAll of these quest chains, plus more, are part of the Pre-Cataclysm launch event.",
            date = "2010-02-24T00:29:36-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25229#comments:id=984035",
        },
        {
            id = 1115613,
            score = 7,
            author = "Zinza",
            text = "this quest starts with you getting a note in your mail to talk to High Tinker Mekkatorque in IF in Tinkertown. he'll be standing on the big sprocket. accept the quest and then open your bags. you'll find a Motivate-A-Tron device. drag that out to an open place on one of your bars. find a common gnome, target gnome, then click the Motivate-A-Tron device. do this as many times as necessary to get 5 gnomes following you. i had 2 gnomes turn into a rat. once you get 5 gnomes, mount up and leave IF. the gnomes will mount up as well and follow you. go down the big hill outside IF and hang a right. go straight until you see all the new gnomes hanging around. i went to 50, 48 and waited a couple of seconds and then the 5 gnomes ran off. now complete the quest by talking to Captain Tread Sparknozzle right in front of you. accept the next quest of Basic Orders.",
            date = "2010-09-07T19:44:26-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25229#comments:id=1115613",
        },
        {
            id = 1141088,
            score = 6,
            author = "krilvyn",
            text = "Seems to be deactivated in patch 4.0.1 :(",
            date = "2010-10-12T21:02:45-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25229#comments:id=1141088",
        },
    },
    [25230] = {
        {
            id = 2258847,
            score = 10,
            author = "bmtphoenix",
            text = "If you go around the lake, especially the north side, you'll hit a bunch of them that are well outside of the area that Blizz indicates on the map, which is where everyone and their uncle will be waiting for more to spawn.",
            date = "2015-09-29T21:10:17-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25230#comments:id=2258847",
        },
        {
            id = 1194290,
            score = 8,
            author = "Mozedo",
            text = "After the completion of this quest, the following event takes place.\n\nKonu Runetotem says: I am at a loss. Perhaps only the Earth Mother herself knows the cause of this. But we must do something before this continues...\n\nYsondre says: Your sincerity is moving, druid.\nKonu Runetotem says: You are no night elf...this is the guise of a green dragon! By the Earth mother, I...\n\nYsondre says: I deserve no such respect or reverance, druid. I have betrayed my own kind. The illness of this land is my fault.\nYsondre says: The sickness is born of the Nightmare within the Emerald Dream, and the dragon Taerar spreads it. He is but a crazed shade of his former self, but will see this land devoured.\nYsondre says: I cannot face him myself. To even approach him would risk letting the same corruption overtake me once more.\nKonu Runetotem says: What must we do?\nYsondre says: The earth itself weeps in its suffering. Gather its tears, and use them to seal the portal at the Great Tree. The connection to the Dream must be cut.\nYsondre says: Be brave, heroes.",
            date = "2010-11-28T19:39:59-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25230#comments:id=1194290",
        },
        {
            id = 6096903,
            score = 1,
            author = "JetGaren",
            text = "https://www.wowhead.com/achievement=4932\nSome Feralas quests are reported [icondb=2175464] Horde but i did these on an [icondb=2173919] Alliance character:\nhttps://www.wowhead.com/quest=25341,https://www.wowhead.com/quest=25252,https://www.wowhead.com/quest=25342,https://www.wowhead.com/quest=25344,https://www.wowhead.com/quest=25645,\nhttps://www.wowhead.com/quest=25210,https://www.wowhead.com/quest=25230,https://www.wowhead.com/quest=25237,https://www.wowhead.com/quest=25241,https://www.wowhead.com/quest=25250.",
