    [25232] = {
        {
            id = 1182568,
            score = 111,
            author = "386392",
            text = "As you go through the northern exit of Razor Hill, go immediately right and follow the path that takes  you above the ravine. You'll see the cave in the distance as soon as you're above the ravine. This took me a long time to find.  Thanks everyone for posting ahead of me.\n\nP.S. It's a long run back from the graveyard if you die.  :)",
            date = "2010-11-24T18:22:19-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25232#comments:id=1182568",
        },
        {
            id = 3243618,
            score = 31,
            author = "superwario15",
            text = "As of the Shadowlands pre-patch, approaching this quest as normal is inadvisable due to a severe overtuning of the Felblood (https://www.wowhead.com/spell=80174/felblood) debuff that is acquired with every kill for the NPCs involved for this quest. At any more than 2 stacks, this debuff will add so much damage to the fire and shadow spells casted by the mobs for this quest that your character will just get nuked.",
            date = "2020-10-29T22:29:14-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25232#comments:id=3243618",
        },
        {
            id = 1699064,
            score = 21,
            author = "911955",
            text = "not sure why but in all the comments there are no map coordinates. ( if you need an add on that lets you use coordinates I use Carbonite which can be found on the Curse web sight) the coordinates are....52.9 30.1\nIf you stand in the middle of the village there is a road to the left. follow it out and follow the hills on your right around until you come to the cliffs. look for one of the cliffs on your side that touch another on the opposite side, they make a bridge. go across the bridge and follow the plateau to the right\n\nif you've wasted your time in the valley ( as I did) I hope this helps.",
            date = "2012-08-12T13:18:30-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25232#comments:id=1699064",
        },
        {
            id = 1225138,
            score = 20,
            author = "728151",
            text = "To find Duskwind Cave head north out of Razor Hill but stop at the fence. Turn right (east) and follow the fence to the next opening. Turn left (north) and go up the path to the hill. Stay to the right so you don't fall in the chasm to Orgrimmar. If you do you will have to go back to Razor Hill. You will see a hut on your right and the entrance to the cave on your left.",
            date = "2010-12-11T15:43:50-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25232#comments:id=1225138",
        },
        {
            id = 1403607,
            score = 20,
            author = "816388",
            text = "Its up on top of the ridge, not down in the valley. if you make the same mistake I did and assume its in the valley you will find a bunch of harpy instead.",
            date = "2011-04-29T03:28:21-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25232#comments:id=1403607",
        },
    },
    [25235] = {
        {
            id = 1501600,
            score = 27,
            author = "Roman215",
            text = "For some reason, this quest seems to be linked with the starting breadcrumb quest chain leading into the Wetlands. I experimented by dropping the quests I had and this quest became available when I dropped https://www.wowhead.com/quest=26137.",
            date = "2011-08-23T08:41:03-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25235#comments:id=1501600",
        },
        {
            id = 2585524,
            score = 14,
            author = "dimestorecandy",
            text = "Looks like the latest patch untangled some of the buggy quest progression lines.  If you lost access to this quest in the past, try giving Watcher Dodds another visit.",
            date = "2018-07-28T13:12:06-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25235#comments:id=2585524",
        },
        {
            id = 1806370,
            score = 4,
            author = "328437",
            text = "For as long as this quest is mutually exclusive with Checking on the Boys (http://www.wowhead.com/quest=26137), doing that quest and it's follow up The Stolen Keg yields a larger combined award. ( 18s vs 14s, 2330 exp vs 1750 exp, and 325 rep Ironforge vx 250 rep Stormwind). This is however offset by the fact that you are required to kill 15 ogres for Vulgar Vul'Gol which will bump up the xp and silver gains for that quest.\n\nIn the end once the kill gains are tallied, it's more profitable to do Vulgar Vul'Gol, just note that not being able to do Checking on the Boys also prevents you from being offered the follow up, you just skip ahead to Keg Run (http://www.wowhead.com/quest=25770)\n\nAnd to add further confirmation of various comments, abandoning either Checking on the Boys or Vulgar Vul'Gol immediately renders the other obtainable.",
            date = "2013-01-29T15:27:57-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25235#comments:id=1806370",
        },
        {
            id = 1818218,
            score = 4,
            author = "Aquril",
            text = "It's interesting to note that when you've accept this quest,\n\nthere's a bug  that appear  when  you look on the map of    [zone=357] ,  in Kalimdor,\nthat makes it look like as if it takes place there. O_o",
            date = "2013-02-25T20:37:57-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25235#comments:id=1818218",
        },
        {
            id = 1821729,
            score = 4,
            author = "1104211",
            text = "I can confirm that this quest is still linked to wetlands breadcrumb quest. I dropped hero's call - wetlands while standing in front of Watcher Dodds and the quest became available for me. This is on Patch 5.2.",
            date = "2013-03-05T20:32:11-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25235#comments:id=1821729",
        },
    },
    [25236] = {
        {
            id = 1490756,
            score = 8,
            author = "225109",
            text = "It might be inappropriate to post this; as what I'm going to post is a bug or a glitch of the system to make this quest faster.\n\nThe rope is attached to the last target you click after you cast the rope item.\n\nYou can start casting the rope on the dead thunderlizard in front of you but if you click the other dead thunderlizard far away from you before casting is over, the rope will be attached to the thunderlizard that is far away from you but you will still get credit for doing the quest.\n\nAs a result, the dead thunderlizard in front of you won't despawn, thus you can complete the quest without moving.\n\nWhat makes this more buggy is that the rope can be attached to the fish as well using this method. You will still get credit for doing the quest even if the rope is attached to the fish.\n\nedit: grammar",
            date = "2011-08-09T06:31:00-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25236#comments:id=1490756",
        },
        {
            id = 1180520,
            score = 6,
