    [25263] = {
        {
            id = 1187461,
            score = 25,
            author = "SquireKel",
            text = "Contrary to what the map indicates, Neeru is still in the Cleft of Shadow in Org",
            date = "2010-11-26T11:10:51-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25263#comments:id=1187461",
        },
        {
            id = 1297073,
            score = 15,
            author = "Tychox",
            text = "For players new to Orgrimmar and the Horde... like me... the Cleft of Shadow is an underground area in the center of Org. I found him by asking directions to the mage trainers. One of the entrances to this area is at 46, 67.",
            date = "2011-01-16T23:12:47-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25263#comments:id=1297073",
        },
        {
            id = 1466422,
            score = 14,
            author = "Adelenne",
            text = "Neeru Fireblade is located in the hut facing Ragefire Chasm in the Cleft of Shadows area of Orgrimmar.",
            date = "2011-07-10T16:17:43-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25263#comments:id=1466422",
        },
        {
            id = 2382552,
            score = 5,
            author = "1695328",
            text = "I ran in circles for a while, checking the map, asking my friend Google, even asking in gen chat (don't do that last one, everyone will jump down your throat to check Wowhead or Google) where Arnak was.\n\nDon't listen to your map - it lies to you. Go down into the Cleft of Shadows, and turn into the hut right outside of the entrance to RFC. Happy questing!",
            date = "2016-09-02T14:20:19-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25263#comments:id=2382552",
        },
        {
            id = 1491201,
            score = 4,
            author = "856975",
            text = "You need to do https://www.wowhead.com/quest=25262 and its prerequisites of course to unlock this quest.",
            date = "2011-08-09T19:12:38-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25263#comments:id=1491201",
        },
    },
    [25264] = {
        {
            id = 1200834,
            score = 42,
            author = "283693",
            text = "This quest has been tweaked from it's previous pre-cata form. Instead of being told to destroy the demon seed, he tells you that they have more pressing matters (shattered barrens) to attend to and shrugs you off without a follow up quest.",
            date = "2010-12-01T18:41:18-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25264#comments:id=1200834",
        },
        {
            id = 5607741,
            score = 3,
            author = "dorkshore",
            text = "As the other comment on here points out, this quest used to lead straight into Demon Seed (https://www.wowhead.com/quest=29112/demon-seed), which is still in the game! And you will encounter it towards the end of Northern Barrens.\n\nIt’s a real bugbear of mine that the investigation you do into the Burning Blade in Durotar doesn’t ever directly pay off, but rest assured you haven’t missed anything if you’re here and drawing a blank.",
            date = "2023-05-12T20:00:19-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25264#comments:id=5607741",
        },
    },
