    [25267] = {
        {
            id = 1222707,
            score = 34,
            author = "315859",
            text = "Look at the name of those items.\n\nUnwelcome. Binding. Servitude.\n\nShows well enough what awaits goblins under the rule of Garrosh...",
            date = "2010-12-10T18:48:05-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25267#comments:id=1222707",
        },
        {
            id = 2076361,
            score = 26,
            author = "Elistrasza",
            text = "So now, after the Cataclysm just happened and Deathwing was running around wreaking havoc on Kezan—and after numerous mentions of Warchief Garrosh—Vol'jin is now suddenly Warchief and the new end of this quest. This WoD expansion is messing with more than one timeline. XD",
            date = "2014-12-25T23:02:09-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25267#comments:id=2076361",
        },
        {
            id = 1217950,
            score = 24,
            author = "Merylyan",
            text = "I expected to swore the Blood Oath of the Horde (http://www.wowhead.com/item=35784)...\n\nEven if Garrosh is not the best warchief...",
            date = "2010-12-09T09:15:58-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25267#comments:id=1217950",
        },
        {
            id = 1292659,
            score = 19,
            author = "93332",
            text = "I may just be a bit dense, but why is Garrosh so taken aback by this insignificant little item (http://www.wowhead.com/item=52581)?\n\nI understand the meaning of this all too well, goblin.\n\nWhat is the meaning of it exactly?  Why exactly is it that Garrosh just automatically \"welcomes\" the goblins into the horde just cos a little green guy with funny ears gave him a badge and said it was from Thrall?",
            date = "2011-01-13T21:38:03-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25267#comments:id=1292659",
        },
        {
            id = 2045489,
            score = 19,
            author = "duskmay",
            text = "As of Warlords, you're taken to Orgrimmar by  Darkspear Loyalist and her Raptor mount...which makes wolf noises.\n\nThey should probably address that.",
            date = "2014-11-23T04:55:12-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25267#comments:id=2045489",
        },
    },
    [25275] = {
        {
            id = 1196234,
            score = 19,
            author = "Solarax",
            text = "This quest is part of a larger line in which characters play a pivotal part in the Bilgewater Cartel joining the Horde. Non-Goblin characters can only complete Warchief's Command: Azshara (http://www.wowhead.com/quest=28496) onwards.\n\nTherefore this quest is only available to Goblins.",
            date = "2010-11-29T17:56:37-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25275#comments:id=1196234",
        },
        {
            id = 5791071,
            score = 10,
            author = "Tyrsenus",
            text = "Quest is for goblins only.\n\nComplete https://www.wowhead.com/quest=25267 (starts at the docks outside Ogrimmar).\nEitrigg will then offer https://www.wowhead.com/quest=25275.\n\nThese two quests are technically a continuation of the Kezan & Lost Isles intro quests. Goblins who did not start on Kezan can only complete these two.",
            date = "2024-02-23T16:33:37-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25275#comments:id=5791071",
        },
        {
            id = 2588686,
            score = 1,
            author = "solitha",
            text = "When I turned in \"Message for Saurfang\", I got an error \"You don't meet the requirements for that quest.\" Saurfang had no mark above his head at all. After coming here to read, I went back inside and noticed that \"Report to the Labor Captain\" is now offered by Eitrigg. So it's just been shuffled around a bit.",
            date = "2018-08-07T05:17:05-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25275#comments:id=2588686",
        },
        {
            id = 2614921,
            score = 1,
            author = "txngurl25",
            text = "Thanks @bebita  The only thing I cared to know was how to get to the rear gate.   The rest of the information in comments is no longer relevant with changes to quests and leveling that have been made from MoP to the current BFA expansion.",
            date = "2018-09-14T17:25:28-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25275#comments:id=2614921",
        },
        {
            id = 1432242,
            score = 0,
            author = "slamb1",
            text = "I just noticed tonight on my level 13 goblin rogue that the quest, once entering Orgrimmar, was greyed out over Garrosh's head. So I did a BG, dinged 14, and it was still grey. On the way in to see Garrosh, I grabbed https://www.wowhead.com/quest=28496. When I abandoned it, the grey ! turned yellow and I could pick this quest up. So it seems that you can get one, but not both, of these quests.",
            date = "2011-06-01T16:18:27-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25275#comments:id=1432242",
        },
    },
    [25283] = {
        {
            id = 1115569,
            score = 16,
            author = "Valdan",
            text = "Ozzie (http://www.wowhead.com/npc=1268) Speech:\nHigh Tinker Mekkatorque says: What I want out of each and every one of you is a hard-target search of every refuelling station, residence, warehouse, farmhouse, henhouse, outhouse and doghouse in his area.\nYour fugitive's name is Mekgineer Thermaplugg (http://www.wowhead.com/npc=7800)\nGo get him.\n\nThis was originally quoted by: Tommy Lee Jones (http://en.wikipedia.org/wiki/Tommy_Lee_Jones) in the 1993 movie \"The Fugitive (http://www.imdb.com/title/tt0106977/)\" \"(Deputy Marshal Samuel Gerard): Your fugitive's name is Dr. Richard Harrison Ford (Dr. Richard Kimble): What I want out of everyone of you is a hard-target search, of every gas station, residence, warehouse, farmhouse, henhouse, outhouse and doghouse in that area! \"\n\nYou get this message when using \"Gnomish Playback Device (http://www.wowhead.com/item=52709)\" on this NPC during quest \"Prepping the Speech (http://www.wowhead.com/quest=25283)\". (Although the quest isnt linked in wowhead the guide is here (http://www.wowhead.com/guide=cataclysm&prelaunch)!)\n\nNotice: This is during the Event prior to the gnomes taking back Gnomergan (http://www.wowhead.com/guide=cataclysm&prelaunch).\n\nMilli (http://www.wowhead.com/npc=7955#comments) Speech:\nHigh Tinker Mekkatorque says: \"They may take our lives, but they'll never take...\"\n\"... our INNOVATION!\"\n\nThis was originally quoted by: Mel Gibson (http://en.wikipedia.org/wiki/Mel_Gibson) as William Wallace in the 1995 film \"Braveheart (http://www.imdb.com/title/tt0112573/)\": Aye, fight and you may die. Run, and you'll live... at least a while. And dying in your beds, many years from now, would you be willin' to trade ALL the days, from this day to that, for one chance, just one chance, to come back here and tell our enemies that they may take our lives, but they'll never take... OUR FREEDOM!\n\nYou get this message when using \"Gnomish Playback Device (http://www.wowhead.com/item=52709)\" on this NPC during quest \"Prepping the Speech (http://www.wowhead.com/quest=25283)\".\n\nNotice: This is during the Event prior to the gnomes taking back Gnomergan (http://www.wowhead.com/guide=cataclysm&prelaunch).\n\nTog Rustsprocket (http://www.wowhead.com/npc=6119)\nHigh Tinker Mekkatorque says:\nWe Will not go quietly into the night!  We will not vanish without a fight!\nWe're going to live on!  We're going to survive!  Today we celebrate...\n...our Autonomy Day!\n\nThis was quoted from the 1996 movie \"Independence Day (http://en.wikiquote.org/wiki/Independence_Day)\" or here (http://www.imdb.com/title/tt0116629/).\nActor name in movie: President Thomas J. Whitmore\nActor's real name: Bill Pullman (http://www.imdb.com/name/nm0000597/)\nWhat was said (http://www.imdb.com/title/tt0116629/quotes):\nGood morning. In less than an hour, aircraft from here will join others from around the world. And you will be launching the largest aerial battle in the history of mankind. \"Mankind.\" That word should have new meaning for all of us today. We can't be consumed by our petty differences anymore. We will be united in our common interests. Perhaps it's fate that today is the Fourth of July, and you will once again be fighting for our freedom... Not from tyranny, oppression, or persecution... but from annihilation. We are fighting for our right to live. To exist. And should we win the day, the Fourth of July will no longer be known as an American holiday, but as the day the world declared in one voice: \"We will not go quietly into the night!\" We will not vanish without a fight! We're going to live on! We're going to survive! Today we celebrate our Independence Day!\n\nYou get this message when using \"Gnomish Playback Device (http://www.wowhead.com/item=52709)\" on this NPC during quest \"Prepping the Speech (http://www.wowhead.com/quest=25283)\". (Although the quest isnt linked in wowhead the guide is here (http://www.wowhead.com/guide=cataclysm&prelaunch)!)",
            date = "2010-09-07T17:57:44-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25283#comments:id=1115569",
        },
        {
            id = 1116479,
            score = 12,
            author = "141922",
            text = "Ozzie Togglevolt is in a building at 45.98, 48.72 - on the way out of town or into it, is on the after Millie.\nTog Rustsprocket is at 47.30, 53.84, up a hill near the vendor tents.\nMillie Featherwhistle isn't far  from quest giver 49.13, 47.99\n\nHope it helps.",
            date = "2010-09-08T19:13:34-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25283#comments:id=1116479",
        },
        {
            id = 1047709,
            score = 8,
            author = "Stagen",
            text = "The speech given to Tog Rustsprocket (http://ptr.wowhead.com/npc=6119) is a reference to the movie Independence Day (http://www.imdb.com/title/tt0116629/).",
            date = "2010-05-28T13:22:40-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25283#comments:id=1047709",
        },
        {
            id = 983593,
            score = 7,
            author = "cayleb",
            text = "The quest-giver here is a reference to the West Wing TV series character, Toby Ziegler (http://en.wikipedia.org/wiki/Toby_Ziegler). ««Link contains West Wing plot SPOILERS»»",
            date = "2010-02-23T11:11:20-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25283#comments:id=983593",
        },
        {
            id = 1048484,
            score = 5,
            author = "Spectrezh",
            text = "The one given to Ozzie is a reference to the movie The Fugitive (http://www.imdb.com/title/tt0106977/)\n\n\"Dr. Richard Kimble!\"",
            date = "2010-05-29T20:06:44-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25283#comments:id=1048484",
        },
    },
