        {
            id = 993524,
            score = 4,
            author = "402147",
            text = "\"In and Out\"...\n\"Ejection System\"...\nThat's all I need to know...",
            date = "2010-03-08T15:12:37-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25285#comments:id=993524",
