    [25338] = {
        {
            id = 1307611,
            score = 11,
            author = "toxoplasmosis",
            text = "I remember doing this quest a few years ago and nearly pulling out my hair in frustration while riding around Feralas (on the original level 40 standard (i.e. slow) mount) trying to find any of the only three Wandering Forest Walkers (http://www.wowhead.com/npc=7584) in the entire zone.\n\nImagine my immense relief when, upon questing in this zone once again, I found that the Shattering seems to have summoned up dozens and dozens of these wooden spirits. To whoever at Blizzard decided to make this change: THANK YOU!",
            date = "2011-01-24T07:54:17-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25338#comments:id=1307611",
        },
        {
            id = 6045584,
            score = 1,
            author = "geekySmurfer",
            text = "you have to click on the https://www.wowhead.com/item=9606 the same time you are damaging or it won't count.",
            date = "2025-01-10T10:41:30-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25338#comments:id=6045584",
        },
        {
            id = 6153232,
            score = 1,
            author = "Futrid",
            text = "There's a weird bug with this quest.  Every previous quest in this chain you could simply kill the enemy, right click to loot, right click again and you would get the quest item.  I tried doing it on this one and it was only giving me grey vendor trash items.  So I killed one, targeted the enemy, then clicked the item in my quest list and it gave me the quest item.  After that the quest started working properly like the previous ones in the chain.",
            date = "2025-08-02T18:35:45-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25338#comments:id=6153232",
        },
        {
            id = 1572678,
            score = 0,
            author = "Adela",
            text = "now it much better, you can find these mobs (Wandering forest walker) together with Corrupted Dryad for same quest",
