    [25341] = {
        {
            id = 6096896,
            score = 1,
            author = "JetGaren",
            text = "https://www.wowhead.com/achievement=4932\nSome Feralas quests are reported [icondb=2175464] Horde but i did these on an [icondb=2173919] Alliance character:\nhttps://www.wowhead.com/quest=25341,https://www.wowhead.com/quest=25252,https://www.wowhead.com/quest=25342,https://www.wowhead.com/quest=25344,https://www.wowhead.com/quest=25645,https://www.wowhead.com/quest=25645,\nhttps://www.wowhead.com/quest=25210,https://www.wowhead.com/quest=25230,https://www.wowhead.com/quest=25237,https://www.wowhead.com/quest=25241,https://www.wowhead.com/quest=25250.",
            date = "2025-04-15T16:29:17-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25341#comments:id=6096896",
        },
        {
            id = 1298094,
            score = 0,
            author = "342915",
            text = "The quest is somewhat unclear in that it seems to suggest the item is found only on a Warlock. While Warlocks may drop the quest item, I got mine from a Shaman.",
            date = "2011-01-17T16:56:42-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25341#comments:id=1298094",
        },
