    [25342] = {
        {
            id = 1952468,
            score = 2,
            author = "751311",
            text = "He is not located in the cave as it appears on the quest tracker. You have to run around to the right of the cave and go up the hill. He is in the top of a tower located on top of the hill directly over the cave.",
            date = "2014-03-20T18:11:20-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25342#comments:id=1952468",
        },
        {
            id = 6096898,
            score = 1,
            author = "JetGaren",
            text = "https://www.wowhead.com/achievement=4932\nSome Feralas quests are reported [icondb=2175464] Horde but i did these on an [icondb=2173919] Alliance character:\nhttps://www.wowhead.com/quest=25341,https://www.wowhead.com/quest=25252,https://www.wowhead.com/quest=25342,https://www.wowhead.com/quest=25344,https://www.wowhead.com/quest=25645,https://www.wowhead.com/quest=25645,\nhttps://www.wowhead.com/quest=25210,https://www.wowhead.com/quest=25230,https://www.wowhead.com/quest=25237,https://www.wowhead.com/quest=25241,https://www.wowhead.com/quest=25250.",
            date = "2025-04-15T16:31:18-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25342#comments:id=6096898",
        },
    },
    [25344] = {
        {
            id = 2362871,
            score = 174,
            author = "CaptainCranium",
            text = "After about thirty or so minutes of running around naked with no weapons or miscellaneous equipment on, I almost gave up. But I decided to try out my new toy, the soft foam sword (you can buy for a few gold in Orgimmar/Stormwind toy vendors) and it brings the ogre close enough to death to capture it. So no more naked run arounds or killing yourself for the debuff! Hope people find this useful.",
            date = "2016-08-07T18:28:58-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25344#comments:id=2362871",
        },
        {
            id = 2018767,
            score = 63,
            author = "Tarjin",
            text = "After one-shotting the Gordok Ogre-Mages (http://www.wowhead.com/npc=11443) with even the weakest spell or melee attack, wearing no gear, I deemed this quest impossible to do for a max level character after 6.0.2.\n\n...But I found a solution that is available to all classes - and it spells Resurrection Sickness (http://www.wowhead.com/spell=15007). This will enable you to steadily reduce the HP of an Ogre Mage to the threshold which lets you capture it using the quest item.\n(To easily get yourself killed, remove all your gear, ascend into the air on your favorite mount and drop down on the stone patio.)",
            date = "2014-10-25T04:55:30-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25344#comments:id=2018767",
        },
        {
            id = 1398469,
            score = 19,
            author = "Amidakilla",
            text = "If you wait a bit after handing in the quest to Swar'jan, he interrogates the ogre you captured and ignites him. After the captured ogre talks Swar'jan tells him to throw himself off and the ogre jumps down to the pond with boars. And the boars eat him. Such a lovely and reasonable ending for a questline :3",
            date = "2011-04-24T11:28:34-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25344#comments:id=1398469",
        },
        {
            id = 2238266,
            score = 8,
            author = "IgneusViscus",
            text = "ENGINEER ONLY WAY! (WITHOUT SICKNESS) So there is another way than doing it with https://www.wowhead.com/spell=15007 at Level 100, Sadly it is only possible for Engineers with Skill level 105 with https://www.wowhead.com/item=4370! (I believe at level 110 we will be able to use https://www.wowhead.com/item=4360)",
            date = "2015-08-25T18:07:26-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25344#comments:id=2238266",
        },
        {
            id = 1278286,
            score = 7,
            author = "haylen",
            text = "At 85 I tried doing it taking my weapon out but still would one shot them. Took off my weapon and all gear, which still left me with nearly 50k health..just whacking at him with my fist I easily took him down slow enough that I could capture him without one-shotting him.\n\nSo..get naked and capture that ogre?",
            date = "2011-01-05T05:12:47-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25344#comments:id=1278286",
        },
    },
    [25345] = {
        {
            id = 1265761,
            score = 34,
            author = "soulhammer",
            text = "To complete this quest you must use Faerie Dragon Muisek Vessel (http://www.wowhead.com/item=9620) to claim Faerie Dragon Muisek (http://www.wowhead.com/item=9596) from Sprite Darters (http://www.wowhead.com/npc=5278). In order to do this, kill the creature, right click on the Faerie Dragon Muisek Vessel (http://www.wowhead.com/item=9620) when targeting the corpse. Ensure you have sufficient bag space when using this item and that you're targeting the correct corpse (you must be targeting it)\n\nAt present (4.0.3 13329 - 29/12/2010) The quest currently tells you to kill Faerie Dragons (http://www.wowhead.com/npc=39921) at around 67, 46 which is incorrect these No longer exist. The correct NPC's are Sprite Darters which spawn around the 71, 41  in quite a large area. These are Neutral to both Horde and Alliance.\n\nHope this helps.",
            date = "2010-12-29T10:07:26-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25345#comments:id=1265761",
        },
        {
            id = 1928701,
            score = 17,
            author = "1204820",
            text = "The highlighted area is incorrect.\n\nTry slightly more east around (72, 42). Kill those dragons and play musik for their soul.",
            date = "2013-12-24T01:09:05-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25345#comments:id=1928701",
        },
        {
