            text = "For anyone who doesn't have coordinates, you need to get off the road and circle around to the back of the hill to find the road up.  It's pretty obvious when you get there, but it's not visible from the road.",
            date = "2012-01-31T01:58:42-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25350#comments:id=1619201",
        },
    },
    [25356] = {
        {
            id = 1554173,
            score = 11,
            author = "Explicity",
            text = "I had trouble completing this quest because I didn't actually TALK to the flight master -- an addon bypassed the chat option and took me straight to the map when I right clicked on the flight master after picking up the quest from Nyse in Mudsprocket. I flew twice to the summit without completing the quest. I worked around this problem by holding down SHIFT when right clicking the flight master.  That let me see the chat option and when I took off the quest completed.",
            date = "2011-10-26T11:43:02-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25356#comments:id=1554173",
        },
        {
            id = 1362034,
            score = 10,
            author = "Oogzy",
            text = "If you've passed the level to get the quest from the quest board in the major cities, this will be the first quest you'd take to start questing in 1k needles.\n\nYou can also get this quest from https://www.wowhead.com/npc=40344 in Thunder Bluff to start doing the quests as well.",
            date = "2011-03-09T06:59:10-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25356#comments:id=1362034",
        },
        {
            id = 1701847,
            score = 4,
            author = "197042",
            text = "As mentioned by a few people in the comments for https://www.wowhead.com/npc=40131, this quest currently seems to be counting for Feralas also.  I was stuck at 44/45 quests for Feralas, so I did as others have  mentioned--completing this and relogging--and sure enough, the Feralas Quests achievement then showed as complete.",
            date = "2012-08-19T17:11:33-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25356#comments:id=1701847",
        },
        {
            id = 2035830,
            score = 4,
            author = "TheRealSaiph",
            text = "This quest is a junction point in the questlines. I received it as soon as I arrived in Camp Mojache, along with several other quests for the Feralas area. If you still have Feralas quests left to do when you receive it, leave it until last, as it transfers you to the Thousand Needles questline. And if you're looking for the https://www.wowhead.com/achievement=4979 achievement, you might find that it counts as the 45th quest, and gives you the reward.",
            date = "2014-11-17T05:14:17-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25356#comments:id=2035830",
        },
