    [25368] = {
        {
            id = 1283469,
            score = 33,
            author = "442479",
            text = "Unholy crap, I was not prepared for those cutscenes.\n\n/shudder",
            date = "2011-01-08T05:11:01-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25368#comments:id=1283469",
        },
        {
            id = 1695141,
            score = 17,
            author = "anubalabeloralon",
            text = "Verinias says: I love you, Sensiria, but I must leave here.\nVerinias says: I will leave to follow Dath'remar and the others. The Shen'dralar have gone too far. To traffic with demons...we're giving ourselves over to corruption.\nSensiria says: Oh, Verinias. You poor fool. You should have left earlier.\nSensiria says: It's too late to stop them. Let me show you their glory.\n*Turns into terrorguard*\n\nSensiria says: You've been so nice, %name. I've been trapped here so long thanks to Verinias. That young elf was the first soul I've tasted in ages.\n*Turns into succubus*\nSensiria says: Even after I gifted him with that form, he insisted on keeping me trapped. He even hoarded all the souls just so I couldn't have any...so stubborn.\nSensiria says: I owe you a favor, darling...someday I'll be back to repay it.",
            date = "2012-08-02T06:50:52-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25368#comments:id=1695141",
        },
        {
            id = 2273147,
            score = 16,
            author = "Fayelin",
            text = "So, does anyone know if eventually Sensiria fulfills her promise sometime later in the game? Does this quest have a follow-up somewhere?",
            date = "2015-11-08T09:01:58-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25368#comments:id=2273147",
        },
        {
            id = 1368231,
            score = 12,
            author = "746107",
            text = "Completed it OK, just a a bit of a hard time finding the tree, thanks Phyllaina for the guidance.\nScreen shot included of tree",
            date = "2011-03-16T07:10:45-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25368#comments:id=1368231",
        },
        {
            id = 1195572,
            score = 6,
            author = "KerynTB",
            text = "For those without coordinates, if you go directly north from the questgiver, you go through the ruins with columns, past the little tent, and the tree will be directly in front of you.  The questgiver, columned area, tent and tree all line up along the north-south axis of the subzone.\n\nThe tree looks pretty much like all the other trees, no tooltip or mouseover indicator.  It's maybe a bit more rounded on top than the others.",
            date = "2010-11-29T11:53:09-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25368#comments:id=1195572",
        },
    },
    [25369] = {
        {
            id = 1194819,
            score = 23,
            author = "87757",
            text = "Make sure to check both hives. He's usually in the one next to the marked hive.",
            date = "2010-11-29T02:34:50-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25369#comments:id=1194819",
        },
        {
            id = 1602501,
            score = 9,
            author = "Brielle",
            text = "There are TWO hives. One has a spiral entrance with three holes, and the other (to the east of that one) has a straight entrance with one hole. I found him in the 2nd hive, that had the straight entrance. I searched around the other one seeing as though the quest helper marker was placed atop that hive, but he is not located in this. Make sure you do not use the quest helper marker area, but to the east of it. He was right at the entrance of this hive.",
            date = "2011-12-27T01:52:35-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25369#comments:id=1602501",
        },
        {
            id = 2345683,
            score = 7,
            author = "Little",
            text = "To unlock this quest you must do the following quests from the same NPC:\nhttps://www.wowhead.com/quest=25363\nhttps://www.wowhead.com/quest=25365\nhttps://www.wowhead.com/quest=25366\nNo other quests needed.",
            date = "2016-06-28T04:49:44-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25369#comments:id=2345683",
        },
        {
            id = 1390261,
            score = 4,
            author = "733502",
            text = "For you hunters out there, he is tameable and makes a very unique pet.",
            date = "2011-04-13T04:15:53-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25369#comments:id=1390261",
        },
        {
            id = 1412538,
            score = 4,
            author = "784161",
            text = "Found him at 76,61. The quest map icon was off by a bit. For those without coordinates, I found him At the eastern hive instead of the western one indicated by your map.",
            date = "2011-05-07T21:37:35-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25369#comments:id=1412538",
        },
    },
