        },
        {
            id = 2182251,
            score = 5,
            author = "1442032",
            text = "There is a path that starts at 74.9, 35.3 just to the east of the waterfall/pool. Follow the torches and ogres up this path until you get to a large clearing with a group of ogres around a fire. Bigfist is at the north side of this clearing at 74.8, 28.4.",
            date = "2015-05-12T18:28:37-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25374#comments:id=2182251",
        },
        {
            id = 1361589,
            score = 2,
            author = "139938",
            text = "Bigfist is standing in front of the cave at the back of the ogre encampment.",
            date = "2011-03-08T18:23:02-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25374#comments:id=1361589",
        },
        {
            id = 1361594,
