        },
    },
    [25375] = {
        {
            id = 1709953,
            score = 5,
            author = "1017142",
            text = "Travel uphill and avoid caves and paths that spiral up the mounts. Just follow the path that breaks between the stone and then cuts to the left. You'll come to a small valley where the tamers are located. At the back is a brown one named Bigfist (who you kill for the quest Sasquatch Taming.)\n\nI made the mistake of just slaughtering Gordunni, assuming that eventually I'd kill the right ones. I practically went through their whole population without finding them. I had to leave and reenter to find the way. I kept thinking they'd be in caves or high up on the mounts, but instead they're tucked away in the back with an easy trail to get to them (avoiding all the others that I wasted my time slaughtering lol)",
            date = "2012-09-05T23:45:41-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25375#comments:id=1709953",
        },
        {
            id = 1361592,
            score = 2,
            author = "139938",
            text = "You can do this quest alongside Sasquatch Sighting (http://www.wowhead.com/quest=25374).",
            date = "2011-03-08T18:24:03-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25375#comments:id=1361592",
        },
    },
    [25378] = {
        {
