        {
            id = 1431825,
            score = 26,
            author = "blupache",
            text = "Based off the comments on the alliance quest page, Ysondre's presumably meant to appear and say:\n\nYsondre says: Taerar has not fled Feralas. He acts as a conduit to the nightmare through his own form.\nYsondre says: I will run no longer. Seek me atop the peak to the east.\n\nShe didn't appear for me and hence the quest text seemed slightly disjointed.",
            date = "2011-06-01T04:15:04-05:00",
