    },
    [25379] = {
        {
            id = 1449832,
            score = 72,
            author = "Nirem",
            text = "I found what may be a bug. As a hunter I find that if you are engaged by Taerar and your pet attacks before you do, Taerar will bug out and you will fail the quest, even though you still have to fight him. Ysondre won't engage.\n\nWhat worked for me was setting my pet to passive and just letting Taerar get 2-3 hits off then attack him and Ysondre should engage.",
            date = "2011-06-24T20:42:57-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25379#comments:id=1449832",
        },
        {
            id = 1765974,
            score = 31,
            author = "whquaint",
            text = "Confirmed other comments.  If you start fighting first, Ysondre does not engage and quest fails in middle of fight.  Just stand there with Ysondre, pets on passive, until Ysondre starts fighting.  Then you can start fighting.",
            date = "2012-11-21T21:00:39-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25379#comments:id=1765974",
        },
        {
            id = 1206069,
            score = 26,
            author = "196807",
            text = "On quest acceptance, Ysondre summons Taerar:\n\nYsondre yells: Come forth, Taerar! I stand before you!\nTaerar yells: I knew you'd return, Ysondre...It was only a matter of time...\nYsondre says: I've returned only to end this, Taerar. This land will finally have peace.\nTaerar says: Peace? PEACE?\nTaerar yells: Peace is but a fleeting dream! Let the NIGHTMARE reign!\n\nYou need to engage Taerar in the next 15 seconds otherwise he despawns and you have to take the quest again. When he dies:\n\nTaerar yells: My essence...will...persist...\n\nAnd then Ysondre gives the next quest Ysondre's Farewell (http://www.wowhead.com/quest=25438) (Alliance) or Ysondre's Farewell (http://www.wowhead.com/quest=25383) (Horde), stating that she cannot rejoin the green dragonflight.",
            date = "2010-12-04T12:19:27-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25379#comments:id=1206069",
        },
        {
            id = 1319142,
            score = 13,
            author = "741034",
            text = "This quest takes a bit of TLC if you're a high-level toon doing Loremaster (I was lvl 85). If you just attack (killing him with first hit, natch), the boss despawns.\n\nRather, engage him with a nerf hit that won't do much damage in order to let Ysondre do some damage first. THEN it's ok to wipe him out. (I used Arcane Torrent to engage without doing too much damage).",
            date = "2011-02-02T08:48:48-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25379#comments:id=1319142",
        },
        {
            id = 1195737,
            score = 10,
            author = "Vonara",
            text = "Alliance players: to reach this quest, you must accept War on the Woodpaw (http://www.wowhead.com/quest=25426) from Adella (http://www.wowhead.com/npc=39725) at Shadebough, and go on to finish Alpha Strike (http://www.wowhead.com/quest=25427). Turning in this quest will grant you Zukk'ash Infestation (http://www.wowhead.com/quest=25429) and Stinglasher (http://www.wowhead.com/quest=25431).\nOnce you complete those two quests, in addition to the side-quest: It's Not \"Ogre\" Yet (http://www.wowhead.com/quest=25432) you will be sent back to the Gordunni Camp to complete Sasquatch Sighting (http://www.wowhead.com/quest=25433) and Taming the Tamers (http://www.wowhead.com/quest=25434). At this point, with both the Writhing Deep and Gordunni Outpost chains completed,  Spiteful Sisters (http://www.wowhead.com/quest=25436) becomes available from Adella (http://www.wowhead.com/npc=39725), which chains into this quest.\n\nNiether Dreamer's Rest, Feathermoon Stronghold, nor Tower of Estulan are pre-requisites, although actions performed at Dreamer's Rest are mentioned.",
            date = "2010-11-29T13:04:46-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25379#comments:id=1195737",
        },
    },
    [25383] = {
        {
            id = 1425888,
            score = 18,
            author = "717646",
            text = "This explains why the portal dragons aren't showing up anymore.\nI'm going to miss Emeriss.",
            date = "2011-05-24T00:25:01-05:00",
