        {
            id = 1384224,
            score = 13,
            author = "ladytremere",
            text = "You have to do [quest=25349 domain=www] which will lead to this quest.  Hope it helps!",
            date = "2011-04-04T19:47:27-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25383#comments:id=1384224",
        },
        {
            id = 1661953,
            score = 12,
            author = "976310",
            text = "For those that don't know, each of the quest rewards are named after one of the world dragon bosses, the Dragons of Nightmare. The four dragons were Lethon, Emeriss, Taerar, and Ysondre. Obviously because the quest centers around and starts with Ysondre, her chain is not included.\n\nI really wish they would bring back the world dragon bosses; Cataclysm ruined so many great things.",
            date = "2012-05-02T22:53:10-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25383#comments:id=1661953",
        },
        {
            id = 2543519,
            score = 9,
            author = "Leandra7",
            text = "Poor Ysondre... If she only knew that Xavius would abuse all four of them again in Legion... Makes me sad, I really wished her peace.",
            date = "2018-01-01T13:55:05-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25383#comments:id=2543519",
        },
        {
            id = 1083274,
            score = 5,
