            text = "Amusing\nI killed Ysondre yesterday (and was killed by Lethon in return)\nAnd yeah, so i find this today.\nYeah, amusing.\n\nGotta go take revenge. 'cuse me.",
            date = "2010-07-18T03:27:24-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25383#comments:id=1083274",
        },
    },
    [25386] = {
        {
            id = 1206603,
            score = 12,
            author = "Warrok",
            text = "This quest wasn't offered to me after completing Sealing the Dream (http://www.wowhead.com/quest=25250).",
