    [25391] = {
        {
            id = 1270930,
            score = 39,
            author = "642241",
            text = "Amusingly, not a single one of these weapons offers Spirit.",
            date = "2011-01-01T07:56:26-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25391#comments:id=1270930",
        },
        {
            id = 1640779,
            score = 12,
            author = "933205",
            text = "Some of the weapons rewarded here have uncommon models- the average person questing in Feralas won't see the model on the Hippogryph again until they run Heroic Old Hillsbrad quite a few levels in the future. The Treant staff is the opposite--its model was dropped in Wailing Caverns. So if not for the stats on these items, the quest chain might be worth it to you for the transmogging potential.",
            date = "2012-03-17T18:41:09-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25391#comments:id=1640779",
        },
        {
            id = 2854560,
            score = 6,
            author = "1939538",
            text = "What a repetitive, monotonous slog this quest chain was. I thought it was never going to end.",
            date = "2018-11-23T09:52:28-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25391#comments:id=2854560",
        },
        {
            id = 2361867,
            score = 4,
            author = "byne",
            text = "Did this quest today on my survival hunter. Didnt even get to choose a weapon.",
            date = "2016-08-05T11:06:25-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25391#comments:id=2361867",
        },
        {
            id = 1911366,
            score = 0,
            author = "Hairband",
            text = "Disappointing quest reward.  I started drooling at all those when first offered, as an elemental shaman.  Nothing for my class, and even worse, the item I had already from about 10 levels ago from a dungeon was better.  So I picked the staff and sold it.  This quest chain is so long, I hoped for something nicer.  I even think those who are benefited by the weapons (1H stam, 2H str/stam... etc.) aren't even that good.  Revamp the quest rewards, please.",
            date = "2013-10-23T09:49:51-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25391#comments:id=1911366",
        },
    },
    [25393] = {
        {
            id = 983646,
            score = 49,
            author = "Jaxor",
            text = "Two weeks after Gnomer is retaken, at the suggestion of a few key Night Elves, the King decides that testing a new form of power station is a great way to secure the new power base.\n\nTwo and a half weeks later, green ooze starts to appear around the edges of the city\n\nThree weeks later, They're back in Ironforge again.",
            date = "2010-02-23T13:08:14-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25393#comments:id=983646",
        },
        {
            id = 1115563,
            score = 40,
            author = "458613",
            text = "So a few quick and simple suggestions to quickly and easily complete this quest:\n\nStay with the King.\n\nStay with the King.\n\nStay with the King.\nSTAY WITH THE KING!\n\nThree times we had to deal with folks who either ran into gnomer before the tankbusters were done or ran into gnomer before the tunnel boss was done.\n\nThe King ended up glitching and just sitting there and then reset.\n\nWith 20 or so or us behind enemy lines.\n\nSaid enemy lines were highly antagonized elite gnomes.\n\nIt hurt.....\n\nSo please.....for the kittens....stay with the King.",
            date = "2010-09-07T17:47:00-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25393#comments:id=1115563",
        },
        {
            id = 1003022,
            score = 24,
            author = "258919",
            text = "Don't look so smug! I know what you're thinking, but Gnomeregan-5 was merely a set back. Did you honestly believe I would trust the future to some weak, irradiated lepers? Oh no, they were merely an instrument, a stepping stone to a much larger plan! It has all led to this, and this time, you will not interfere!",
            date = "2010-03-22T21:42:12-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25393#comments:id=1003022",
        },
        {
            id = 1115765,
            score = 20,
            author = "156551",
            text = "Admiral Ackbar: \"Take evasive action. Green Group, stay close to holding sector MD-7.\"\nCrewman: \"Admiral, we have enemy ships in sector 47!\"\nAckbar: \"It's a trap!\"",
            date = "2010-09-08T00:22:42-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25393#comments:id=1115765",
        },
        {
            id = 1031902,
            score = 13,
            author = "Quilan",
            text = "(@ Amrun) *starts B5 music* It was the dawn of the 3rd age of Gnome-kind, 10 yrs after the Trogg-Gnome war. The Gnomeregan Project was a dream given form a place were gnomes and others could work out their diffrences peacfuly, given the port-of-call \"Home away from home\" for diplomats, entrepenuers and wanderers. Gnomes and others wraped in 2,500,000 tons of spinning metal, all alone in the cold. It can be a dangerous place, but its our last best hope for peace. This is the story of the last of the Gnomeregan cities, the year is 2010, the name of the place is Gnomeregan-5.",
            date = "2010-05-03T14:41:44-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25393#comments:id=1031902",
        },
    },
    [25394] = {
        {
            id = 2236820,
            score = 18,
            author = "Pypode",
            text = "Move north by northeast around the lake shore, beyond the blue map area, if others are also hunting the whelps.",
            date = "2015-08-22T16:42:52-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25394#comments:id=2236820",
        },
        {
            id = 1205701,
            score = 16,
            author = "196807",
            text = "When you turn in the quest, Ysondre appears and begins a conversation with Telaron Windflight.\n\nTelaron Windflight says: This is truly grave. We must find the true cause of this illness, for the sake of the land.\nYsondre says: Your sincerity is moving, druid.\nTelaron Windflight says: A green dragon in mortal guise! I never thought I would receive the honor of...\nYsondre says: I deserve no such respect or reverance, druid. I have betrayed my own kind. The illness of this land is my fault.\nYsondre says: The sickness is born of the Nightmare within the Emerald Dream, and the dragon Taerar spreads it. He is but a crazed shade of his former self, but will see this land devoured.\nYsondre says: I cannot face him myself. To even approach him would risk letting the same corruption overtake me once more.\nTelaron Windflight says: What must we do?\nYsondre says: The earth itself weeps in its suffering. Gather its tears, and use them to seal the portal at the Great Tree. The connection to the Dream must be cut.\nYsondre says: Be brave, heroes.\n\nTelaron Windflight then gives 2 followup quests: Tears of Stone (http://www.wowhead.com/quest=25396) and The Land, Corrupted (http://www.wowhead.com/quest=25397).",
            date = "2010-12-04T07:56:48-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25394#comments:id=1205701",
        },
        {
            id = 2452754,
            score = 6,
            author = "NeVeRLiFt",
            text = "You must first complete the \"Signs of Change\" quest before you can take this quest.",
            date = "2016-12-11T00:08:02-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25394#comments:id=2452754",
        },
    },
