    [25420] = {
        {
            id = 2104342,
            score = 5,
            author = "salvo1",
            text = "To get to this questline, you have to fulfill the prerequisite quests, which begin all the way back in Gadgetzan with this (http://www.wowhead.com/npc=38535/kelsey-steelspark) version of Kelsey Steelspark.  I figured this out the hard way while looking for the second (phased) Kelsey that only appears at Land's End Beach when you've completed her Gadgetzan questline.  It's a long questline too with multiple stops along the way, FYI.\n\nI'm just writing this for the people here to grab one of these quest items for Transmog purposes. For me, it was the leather shoulders.",
            date = "2015-02-12T23:23:59-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25420#comments:id=2104342",
        },
        {
            id = 1312840,
            score = 4,
            author = "Freedomage",
            text = "Easy quest with 2000-2100hp Sandstone Golems.\nFirst one dropped [Vanadium Loop of Spirit].\nTotal loot for me from Quest and 10-Golems was 1g 61s 71c\n\np.s. of course you only need 6 of them.\n\n\"But what's done is done, and the entrance to Uldum is revaled.\"\n\"revealed\" from proofreader  lol :)",
            date = "2011-01-28T05:17:47-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25420#comments:id=1312840",
        },
        {
            id = 1838729,
            score = 2,
            author = "1021255",
            text = "While you do this quest go inside the Ruins of Uldum to the far side of the big cavernous room (or as https://www.wowhead.com/npc=40109 calls it the Antechamber of Uldum) and pick up https://www.wowhead.com/quest=25421 quest. There are no mobs to kill or traps of any kind. When you return to Prospector Gunstan he will declate that you and he together have \"made the find of the century!\"\n\nOr you can wait and pick it up while you are there doing https://www.wowhead.com/quest=25566. You will have to kill the https://www.wowhead.com/npc=39077. But this way you can \"kill two birds with one stone\" so to speak.",
            date = "2013-04-03T21:57:27-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25420#comments:id=1838729",
        },
    },
    [25421] = {
        {
            id = 1249969,
            score = 15,
            author = "mineka",
            text = "These hieroglyphs are undoubtedly titan, but the markings below it...\n\nIf I had to hope, this is the same passage written over and over again in an entire assortment of ancient languages. We might be able to use this to decipher the hieroglyphs!\n\nThis quest, and the rewards (Rosy Tablet belt (http://www.wowhead.com/item=56899)) are a reference to Rosetta Stone (http://en.wikipedia.org/wiki/Rosetta_Stone), an inscribed stone who permitted to dechiper hieroglyphs.\n\nThe text on the stone was written three times, in three different \"languages\" (hieroglyphs, egyptian demotic script and ancient greek).",
            date = "2010-12-21T08:44:37-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25421#comments:id=1249969",
        },
        {
            id = 1539456,
            score = 10,
            author = "Aviendha09",
            text = "Dont take this quest unlees prospector gunstan sends u. The pre quest is called: The Secrets of Uldum and pops up after u finish the 3 quests from prospector gunstan.",
            date = "2011-10-10T05:36:30-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25421#comments:id=1539456",
        },
        {
            id = 1684236,
            score = 10,
            author = "Catriona",
            text = "Am I the only person who said, that's it?\nDid I miss some grand end to Tanaris questing somehow? This was kinda anti-climactic.",
            date = "2012-07-04T00:14:51-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25421#comments:id=1684236",
        },
        {
            id = 1451027,
            score = 5,
            author = "254118",
            text = "This quest, like a few that went with it and various quests from around the WoW world, appear to have a gold background.  I've been playing WoW for a long time and I still don't know what that means.  Lol!  I have even seen some with silver backgrounds.  Is there a reason or purpose behind this?  Thanks!",
            date = "2011-06-26T10:22:38-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25421#comments:id=1451027",
        },
    },
    [25422] = {
        {
            id = 1751872,
            score = 12,
            author = "mecheye",
            text = "For some reason I am unable to start this quest.\n\nI completed https://www.wowhead.com/quest=25643, which gave me https://www.wowhead.com/quest=25645. After that, Sage Palerunner gave me nothing further with that quest line.",
            date = "2012-10-27T14:24:38-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25422#comments:id=1751872",
        },
        {
            id = 1185775,
            score = 9,
            author = "Diwtay",
            text = "Some of the Loose Soil mounds are in the water. They are hard to see.",
            date = "2010-11-25T19:32:08-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25422#comments:id=1185775",
        },
        {
            id = 3221061,
            score = 9,
            author = "Lizardo221",
            text = "For any old players who can't see the NPC, I found a modern workaround I used to fix the problem. Simply level sync with someone in the area and rework through the quest chain. I flew my little buddy all around for an hour until we got to the part in the chain, and there she was! Did the quests, and as far as I can tell from my 2 trackers and the giant exclamation no longer on my map, the quest has been finished. Unfortunately Blizzard in 2020 has yet to fix this issue, but the sync looks like a real work around!",
            date = "2020-08-04T01:35:46-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25422#comments:id=3221061",
        },
        {
            id = 6004892,
            score = 8,
            author = "Goblinaire",
            text = "As of 11.0.5, the easiest way to pick up this quest if https://www.wowhead.com/npc=40131 is phased out for you is this:\n\n1) Party sync with another character who hasn't completed quests in Feralas.\n2) Fly straight to https://www.wowhead.com/npc=5390 in Camp Mojache.\n3) Pick up https://www.wowhead.com/quest=25643 and complete Sensiria's quest chain.\n\nDo not drop Party Sync until you've completed all https://www.wowhead.com/npc=40131 quests. Otherwise you have to start over.",
            date = "2024-11-11T10:01:05-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25422#comments:id=6004892",
        },
        {
            id = 1182732,
            score = 6,
            author = "707128",
            text = "Anyone else cant see this chick to turn in the quest?",
            date = "2010-11-24T19:25:00-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25422#comments:id=1182732",
        },
    },
