    [25436] = {
        {
            id = 1200995,
            score = 19,
            author = "NFalcon",
            text = "Here are the things the sisters say upon aggro.  (All in Darnassian.)\n\n\"Join us!  Join us!\"\n\"The nightmare reigns!\"\n\"Hear his voice...\"\n\"The strands of life...\"",
            date = "2010-12-01T20:21:49-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25436#comments:id=1200995",
        },
        {
            id = 1197127,
            score = 13,
            author = "Catriona",
            text = "I was hoping that Blizzard had quit with the \"okay go here and kill this and come back... Okay, now go back to the exact same spot and kill this and come back... okay, now go slightly north of there and kill this and come back...\" quests but this not-quite-chain proves that this is far from true.",
            date = "2010-11-30T04:01:42-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25436#comments:id=1197127",
        },
        {
            id = 1206036,
            score = 11,
            author = "196807",
            text = "When you turn in the quest, Ysondre appears and says the following:\n\nYsondre says: Taerar has not fled Feralas. He acts as a conduit to the nightmare through his own form.\nYsondre says: I will run no longer. Seek me atop the peak to the east.\n\nAdella then gives the quest Ysondre's Call (http://www.wowhead.com/quest=25437)",
            date = "2010-12-04T12:01:44-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25436#comments:id=1206036",
        },
        {
            id = 1329805,
            score = 5,
            author = "yarko",
            text = "The dryads act strangely when I fight them. They seem to wander about aimlessly while I try to knock them around. That corruption really messes with ya, I guess. They also cast a buff on themselves that heals them when struck with melee attacks.",
            date = "2011-02-10T03:38:20-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25436#comments:id=1329805",
        },
        {
            id = 3194220,
            score = 1,
            author = "Bunnyhugs",
            text = "Kudos to you if you're still going through the quest chains at this point. It's still nothing like vanilla/classic, but there aren't many areas left in the post-cata zones where you're just constantly running back and forth from one side of the map to the other with no flight points or innkeepers anywhere useful. So in case anyone's wondering if there's any way to group up these quests and save some time, NOPE! But I DID keep my hearth at feathermoon and fly back to Shadebough when I needed a break.",
            date = "2020-03-11T21:32:10-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25436#comments:id=3194220",
        },
    },
    [25437] = {
        {
            id = 1204191,
            score = 8,
            author = "102402",
            text = "Did I miss something? Perhaps I started quests in the wrong area of the zone, but I don't get how this quest starts....did the Ysondre request me to go at some point and I missed it? All the quests Adella gives before this one doesn't seem to have much to do with anything Emerald Dream related. I just don't get where the dragons pop into this chain.",
            date = "2010-12-03T13:14:44-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25437#comments:id=1204191",
        },
        {
            id = 5581461,
            score = 1,
            author = "auryunderground",
            text = "The comments about the seemingly abrupt shift to this quest are completely understandable. Usually Blizzard will include any \"extra\" RP lore in a quest right after a player has accepted it. But in this case, unless players are paying close attention, they could easily miss the fact that after turning in https://www.wowhead.com/quest=25436, you suddenly see https://www.wowhead.com/npc=39407 in the magical basin right beside https://www.wowhead.com/npc=39725. She will physically turn towards this basin while she listens to the message, which is as follows:\n\nYsondre says: Taerar (https://wowpedia.fandom.com/wiki/Taerar) has not fled [zone=357]. He acts as a conduit to the nightmare (https://wowpedia.fandom.com/wiki/Emerald_Nightmare) through his own form.\n\nYsondre says: I will run no longer. Seek me atop the peak to the east.",
            date = "2023-04-01T05:38:13-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25437#comments:id=5581461",
        },
    },
