    [25451] = {
        {
            id = 1422436,
            score = 12,
            author = "488162",
            text = "For those who are trying to complete the Feralas Quests achievement: pick up the Rage Yeti quest from Pratt in the northern part of Feathermoon Stronghold.  After you finish that he will give you a quest to go and kill Feral Scar Yetis for THEIR hides.  The Pristine Hide will drop as you have this quest.",
            date = "2011-05-19T09:12:19-05:00",
