        },
    },
    [25452] = {
        {
            id = 1193087,
            score = 15,
            author = "311571",
            text = "The Rage Scar Yeti (http://www.wowhead.com/npc=40224) are in an open area just on the west side of the mountains, so you will want to take the trail back north (toward Desolace).\n\nAdditionally, in killing 6 yeti I received 4 Thick Yeti Hide (http://www.wowhead.com/item=8973) as drops and 6 from skinning, so it could be that it's a 100% skinning rate for the quest item.",
            date = "2010-11-28T10:44:23-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25452#comments:id=1193087",
        },
        {
            id = 1209705,
            score = 3,
            author = "Koviko",
            text = "Yes, the Perfect Yeti Hide (item=18972) does still drop. However, I've found that it only drops from the Feral Scar Yeti (npc=39896)s that you must kill in the follow-up to this quest (quest=25453).",
            date = "2010-12-06T06:21:35-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25452#comments:id=1209705",
        },
        {
            id = 1653008,
            score = 3,
            author = "onlymeaz",
            text = "Correction to the previous posts:\nThere are enough Yeti in the area.  There is also a hidden cave at 53.0/31.7 where there are more and a bunch hanging around 52.2/31.5.  Make sure to circle the area identified on the map as it is accurate and there are enough.  You might have to \"climb\" a little but the Yeti are there.  This should help those who are not skinners.  The drop is about one every other kill.",
            date = "2012-04-12T21:00:17-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25452#comments:id=1653008",
        },
        {
            id = 2428006,
            score = 3,
            author = "EmperorsFinest",
            text = "Upon completion of this quest the NPC says:\nAh, excellent!  These hides, when given a special treatment, are as resilient as iron I tell you!  It will take many tries in order to get the right mix down for the tanning, but I am confident they will bring my mark of quality to the next level.\n\nAs for you, ... your assistance has proven invaluable to me.  Please take your choice from these items I have crafted.\nBut as an Arms warrior I did not get to choose any item. Only got 40silvers.",
            date = "2016-10-14T14:38:02-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25452#comments:id=2428006",
        },
        {
