    [25453] = {
        {
            id = 1193200,
            score = 7,
            author = "311571",
            text = "Upon completion of this quest, Jangdor sends you a letter in the mail.  It contains a Rugged Armor Kit (http://www.wowhead.com/item=15564) and the following message:\n\nGreetings once again - I just wanted to send you word that things here in Camp Mojache are going well.  I've managed to make several new pieces of leather items, thanks in no small part to your aid!\n\nI had some extra bits of leather left over, so I thought I'd send you something extra as a way of saying thank you once more.  If you're ever by the Camp again, be sure to visit!\n\nPeace to you and your ancestors,\nJangdor\n\nHe still says Camp Mojache despite having been moved to Stonemaul Hold in 4.0.3a.",
            date = "2010-11-28T11:38:33-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25453#comments:id=1193200",
        },
        {
            id = 1262648,
            score = 3,
