    [25465] = {
        {
            id = 1687777,
            score = 21,
            author = "Mormolyce",
            text = "In MoP they should replace this quest with yet another one called \"Enough With The Zapped Giants Already\".",
            date = "2012-07-13T20:02:30-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25465#comments:id=1687777",
        },
        {
            id = 1206728,
            score = 15,
            author = "Warrok",
            text = "The flavor text for quest progress is a reference to earlier versions of WoW, where Zorbin's Ultra-Shrinker (http://www.wowhead.com/item=18904) could be used to shrink other giants as well, which made killing them considerably easier.",
            date = "2010-12-04T19:00:01-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25465#comments:id=1206728",
        },
        {
            id = 1874659,
            score = 5,
            author = "JohnPWest",
            text = "This quest now give Ratchet, Booty Bay, Everlook, and Gadgetzan faction.. For what it's worth!\n\nFaeder",
            date = "2013-07-07T22:30:06-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25465#comments:id=1874659",
        },
        {
            id = 1182286,
            score = 3,
            author = "349565",
            text = "These don't seem repeatable anymore, this one counted towards the completed Feralas Quests Achievement.",
            date = "2010-11-24T16:35:58-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25465#comments:id=1182286",
        },
        {
            id = 1383881,
            score = 2,
            author = "Zoomar",
            text = "Zorbin Fandazzle gives 2 quests that I'm aware of.... the other of which is called (Even more Fuel for the zapping)\nAfter completing both quests, I received for each quest:\n350 rep with Ratchet\n350 rep with Gadgetzan\n350 rep with Everlook\nand 350 reputation increase with Booty Bay\nand of course 2 rep with guild.  For each quest turned in....of course that means a total of 700 rep for each faction listed and 4 for the guild total.  Very nice I think.  I also received a one handed axe called \"Zorbin's Megachopper\" and 40 silver.\nThe second quest he gave, I received a leather item called \"Zorbinn's Weather Resistant Hat\" and more silver.\nPlus I Confirm with the above with being part of the \"completing quests for Feralas\" Achievement, as I did receive it once I had finished the 2 quests at the end of all my questing in Feralas.\n\nNow, being on the Horde side, I thought I might mention there are two ways to enter the area for this quest without having to leap off the high cliff or possibly having to deal with the \"Alliance entrance\" and accidentally putting you into PVP.   (and for those who aren't as \"quick\"-like me) :P\nIf I load them right, and they are approved, I have 2 screen shots to help.\n1. If you take the path near the quest giver that leads to the Alliance's Feathermoon Sronghold, you can jump to the left into their graveyard to avoid dealing with them as I did.  Cross over the Forgotten Coasts water and you can begin with the elementals there.\n2. Or you can take the main road passed the bridge, and head east a little past the Stonemaul Hold, until approximate coords of 53.76, 51.35 where there will be a path (south of road) which leads you straight to the beach areas.\nHope this helps a bit.  Happy Questing!",
            date = "2011-04-04T11:26:02-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25465#comments:id=1383881",
        },
    },
    [25466] = {
        {
