    [25470] = {
        {
            id = 1048183,
            score = 17,
            author = "FuxieDK",
            text = "Keep Ability 3 up to reduce damage..\nKeep 3 stacks of Ability 2 up as a DoT.\nSpam Ability 1 as attack.\n\nPS, yes I'm lousy at remembering the names of your abilities.. ;)",
            date = "2010-05-29T08:55:07-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25470#comments:id=1048183",
        },
        {
            id = 1048395,
            score = 10,
            author = "structure",
            text = "You need to do the quest Trolling For Volunteers (http://www.wowhead.com/quest=25461/trollin-for-volunteers) for this to become aviavible.",
            date = "2010-05-29T15:43:09-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25470#comments:id=1048395",
        },
        {
            id = 1115572,
            score = 10,
            author = "274426",
            text = "The tiger you're looking for is on the island directly above the \"E\" in \"Echo Isles\" on your map.",
            date = "2010-09-07T17:59:32-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25470#comments:id=1115572",
        },
        {
            id = 1115766,
            score = 8,
            author = "98777",
            text = "The Tiger Matriarch is located at 59, 82.\nHere is a map (http://www.wowhead.com/maps?data=14:598823) for those not using coordinates.",
            date = "2010-09-08T00:36:26-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25470#comments:id=1115766",
        },
        {
            id = 1115886,
            score = 6,
            author = "Morthred",
            text = "The mentioned Tiger Matriarch is actually the very first Troll Druid, Zen'tabra, and she'll give a basic hint to the introduction of the new race/class combo.\n\nQuest starts by turning you into a Tiger Spirit, granting new abilities and water walking.\n\n1 - Claw - Basic melee attack to be spammed when other abilities are on cooldown.\n2 - Bloody Rip - DoT like bleed effect.\n3 - Spinning Rake - Powerful ability that slows target attack speed.\n\nUse 3 and 2 every cooldown, and spam 1 in between. She Pounces occasionally, so be ready to turn and face her when she does.\n\nShe does not hang in any specific point in the island, and will be randomly spawned by the player is it enters the land area.\n\nThis may cause a bug that can make her spawn multiple times if you go too far into the island, or too fast, inevitably leading to the Tiger Spirit's demise (which is a dramatic way to saying you'll have to swim back to the quest giver to get a new Tiger buff).\n\nThe trick is to explore the area slowly to avoid multiple spawns. Defeat her, and the quest is done.",
            date = "2010-09-08T04:32:16-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25470#comments:id=1115886",
        },
    },
    [25475] = {
        {
            id = 1564183,
            score = 77,
            author = "sandyra",
            text = "For those trying to hunt down:\n\nhttps://www.wowhead.com/item=8704 from The Hinterlands (Personal stats: Killed some stalkers, some trolls, some owlbeasts (about 20 all told)... Then killed my first ooze at Skulk Rock, and it dropped)\nhttps://www.wowhead.com/item=8623 from Tanaris (Personal stats:  Went into Zul'Farrak like all other posters recommend, killed some twenty or thirty trolls and scarabs, and it dropped from one of the troll corpses)\nhttps://www.wowhead.com/item=8705 from Feralas  (Personal stats:  As recommended by many other posters, Feral Scar Yetis - dropped on my first kill)\n\nOnly available if you have not already completed the quest.\nYes these still drop in Mists of Pandaria.\nYes it can drop off ANY mob in the respective zone, however https://www.wowhead.com/item=8705 has the highest drop rate from https://www.wowhead.com/npc=5292 IF you haven't already done the quest.\nIt WILL eventually drop - some days RNG is your best friend, other days you want to repeatedly punch a kitten (or other obscenely fluffy creature) just to illustrate how cruel the universe can be.\nThe command to check if you have completed ANY of the distress beacon quests is here (special thanks to MrsSushi (http://www.wowhead.com/user=MrsSushi) for locating the updated version of this as of 5.0.3):\n\n/run local z={\"Tanaris\",\"Hinterlands\",\"Feralas\"}for k,v in pairs({{351,648},{485,836},{25475,25476}})do print(z[k])for i,q in pairs(v)do print(\" #\"..i,\"\\124Hquest:\"..q..\"\\124h[\"..q..\"]\\124h\" ,IsQuestFlaggedCompleted(q)and COMPLETE or INCOMPLETE)end end\n\nYou will see lines of dialogue that look like this:\nTanaris\n#1 [351] Complete\n#2 [648] Complete\nHinterlands\n#1 [485] Complete\n#2 [836] Complete\nFeralas\n#1 [25475] Incomplete\n#2 [25476] Incomplete\n\nAfter completing all three escorts, you can then acquire the quest https://www.wowhead.com/quest=3721 and get your https://www.wowhead.com/item=10398.\n\nHappy hunting!",
            date = "2011-11-06T00:32:30-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25475#comments:id=1564183",
        },
        {
            id = 1198630,
            score = 10,
            author = "336100",
            text = "Note that, even after many of the new goblin quests in Kalimdor no longer decrease your Bloodsail reputation, this one still does!  If you already turned this in and hurt your Bloodsail rep, be careful not to turn in the escort portion of this chain - that will set you back another 350.",
            date = "2010-11-30T19:14:40-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25475#comments:id=1198630",
        },
