    [25481] = {
        {
            id = 1329900,
            score = 10,
            author = "yarko",
            text = "I don't understand. Do I not get this quest if I have the Hero's Call quest? When I finished Ysondre's Farewell, there were no more quests to get. Falfindel even says \"We're staging a relief effort at New Thalanaar for all of the survivors of Thousand Needles. We need your help now!\" in chat, but he has no quest to give me. I would really like a hippogryff ride too.\n\nGuess I will ride over there myself.\n\nEDIT: I figured it out. If you have the Hero's Call quest, you don't get this breadcrumb quest. I think that's silly. Especially since you can't get the helpful hippogryff flight without it.",
            date = "2011-02-10T04:52:54-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25481#comments:id=1329900",
        },
        {
            id = 1868956,
            score = 5,
            author = "328437",
            text = "As with all other breadcrumb quests, this quest is mutually exclusive with To New Thalannar (http://www.wowhead.com/quest=25479/to-new-thalanaar) (Dustwallow Marsh version) and Hero's Call: Thousand Needles (http://www.wowhead.com/quest=28503).  This quest offers greater xp.  If you cannot pick up this quest you have either completed one of the other quests or have it in your quest log.  To pick this quest up simply abandon the other breadcrumb quest.\n\nIn order to turn this quest in you MUST take the hippogryph ride to New Thalanaar.  Speak to the flighmaster.  She provides an option for a free ride.",
            date = "2013-06-21T11:00:04-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25481#comments:id=1868956",
