        {
            id = 1115644,
            score = 7,
            author = "573744",
            text = "To complete this quest you have to travel to 64.4, 71.1, and WAIT until Vol'jin arrives; once he arrives, you can turn in quest and get the following one, Zalazane's Fall, then you'll have to wait about 6 mins to get going.",
            date = "2010-09-07T20:25:42-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25495#comments:id=1115644",
        },
        {
            id = 1048495,
            score = 4,
            author = "FuxieDK",
            text = "The complete chain as of PTR build 12124\n1: Da Perfect Spies (http://ptr.wowhead.com/quest=25444)\n2: Frogs Away! (http://ptr.wowhead.com/quest=25446)\n3: Lady Of Da Tigers (http://ptr.wowhead.com/quest=25470)\n4: Dance Of De Spirits (http://ptr.wowhead.com/quest=25480)\n5: Trollin' For Volunteers (http://ptr.wowhead.com/quest=25461)\n6: Preparin' For Battle (http://ptr.wowhead.com/quest=25495)\n7: Zalazane's Fall (http://ptr.wowhead.com/quest=25445)",
            date = "2010-05-29T20:49:17-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25495#comments:id=1048495",
        },
    },
    [25500] = {
        {
            id = 1115897,
            score = 8,
            author = "error10",
            text = "Start by picking up the quest A Few Good Gnomes (http://www.wowhead.com/quest=25229) from High Tinker Mekkatorque (http://www.wowhead.com/npc=7937) in Tinker Town, Ironforge.\n\nPart of this quest chain can be completed at level 1. The final two quests, which involve retaking the surface of Gnomeregan, require level 75. Turning in the final quest (http://www.wowhead.com/quest=25393) grants the achievement Operation: Gnomeregan (http://www.wowhead.com/achievement=4786), which is listed as a Feat of Strength.\n\nThe full quest chain is:\n\nA Few Good Gnomes (http://www.wowhead.com/quest=25229)\nBasic Orders (http://www.wowhead.com/quest=25199)\nIn and Out (http://www.wowhead.com/quest=25285)\nOne Step Forward... (http://www.wowhead.com/quest=25289)\nPress Fire (http://www.wowhead.com/quest=25295)\nVent Horizon (http://www.wowhead.com/quest=25212)\nPrepping the Speech (http://www.wowhead.com/quest=25283)\nWords for Delivery (1) (http://www.wowhead.com/quest=25500)\n\nGoing forward requires level 75:\n\nWords for Delivery (2) (http://www.wowhead.com/quest=25287)\nOperation: Gnomeregan (http://www.wowhead.com/quest=25393)",
            date = "2010-09-08T04:39:04-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25500#comments:id=1115897",
        },
        {
            id = 1115323,
            score = 7,
            author = "deathbybunnies",
            text = "Good news, everybody!  A number of the quests for Operation Gnomeregan count towards Loremaster of the Eastern Kingdoms and 3000 Quests Completed!",
            date = "2010-09-07T13:08:38-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25500#comments:id=1115323",
        },
        {
            id = 1115405,
            score = 7,
            author = "dipiddy",
            text = "Simply click on the Helicopter to the left after accepting this quest. Wait for the event to respawn and talk to Mekkatorque. If he's not there, just wait a few minutes.",
            date = "2010-09-07T14:43:53-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25500#comments:id=1115405",
        },
        {
            id = 1115404,
            score = 6,
            author = "658218",
            text = "it seems that if your under 80 this is where it ends for you. I did this as a 52 shammy got the Gnomeregan pride item and that was it.",
            date = "2010-09-07T14:41:31-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25500#comments:id=1115404",
        },
        {
            id = 1116080,
            score = 4,
            author = "Aislinge",
            text = "If the event has started and you didn't see Mekko with a ? right when you got off the helicopter, don't bother with the event, you won't get the quest hand in at the end. Just wait for it to restart - better to do it once properly than 3 times over :O\n\nAs other's have mentioned, do NOT go in the tunnel and pass the Trogg Boss - this will bug the quest for some.\n\nAside from that, hang back and enjoy!\n\nEdit - now on my 4th attempt due to bugging *sigh*",
            date = "2010-09-08T09:21:36-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25500#comments:id=1116080",
        },
    },
