    [25513] = {
        {
            id = 1200032,
            score = 51,
            author = "442287",
            text = "Note that (for alliance) you must complete Kelsey Steelspark's quests, from [quest=25048 domain=www] through [quest=25065 domain=www], before this quest becomes available.",
            date = "2010-12-01T11:18:02-06:00",
