        {
            id = 2020966,
            score = 35,
            author = "CAXAPrus",
            text = "as of 6.0.3 Patch this quest is bugged, if you want to do this quest, you have to kill the big mechanical boss from 100% health to 0% in 1-2 seconds, otherwise yout faction's fighter will begin running around arena and killling the mechanical boss will not make your fighter to stop running, he will just disappear and enemy faction's fighter will stay in middle, but final dialogue between fighters will not happen and later you get \"quest failed\", again, you have to kill mechanical boss BEFORE your fighter begins running around.\n\nsomeone report it to Blizzard (GMs), please",
            date = "2014-10-30T05:19:38-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25513#comments:id=2020966",
