    [25515] = {
        {
            id = 1188187,
            score = 7,
            author = "Anthellis",
            text = "In order to get the next quest in the chain, you have to do the quest underwater where you rescue the guy from the outhouse. Be sure to do it while you are collecting parts on the ocean floor.",
            date = "2010-11-26T16:16:32-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25515#comments:id=1188187",
        },
        {
            id = 1255499,
            score = 6,
            author = "Hackensack",
            text = "BTW this suit works all over 1K needles. So if you like farming Mithril Ore, gems and iron, with no competition (for now) accept the quest but never turn it in.",
            date = "2010-12-23T19:56:59-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25515#comments:id=1255499",
        },
        {
            id = 2341652,
            score = 1,
            author = "1663627",
            text = "Ok. So I did Down in the Deeps. Was not able to get the next quest. Went to find the quest for the Bar Fight. Quest still did not pop up. Then I found the outhouse and killed some treasure hunters for their crowbar to get the dude out. Then the Quest popped up. So I don't think you have to do the Bar Fight but you do have to rescue the man from the porta potty. Hope this helps sort out the confusion.",
            date = "2016-06-18T02:35:57-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25515#comments:id=2341652",
        },
    },
    [25516] = {
        {
            id = 1192201,
            score = 12,
            author = "bluspacecow",
            text = "Prior to the Shattering (4.0.3) there was a quest similar to this.\n\nThose who have done that quest before know what to look for :  various assorted machine parts like cogwheels and the like.\n\nExcept this time you do it on the ocean floor beneath the barge.\n\nNo need to find or equip under water breathing stuff - just jump off the boat and you get it :)",
            date = "2010-11-28T02:59:24-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25516#comments:id=1192201",
        },
        {
            id = 1204165,
            score = 8,
            author = "368519",
            text = "Not only do the flippers give you a swim speed boost, they also allow you to run on the sea floor.",
            date = "2010-12-03T12:57:37-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25516#comments:id=1204165",
        },
        {
            id = 1393162,
            score = 8,
            author = "816934",
            text = "I found the issue. you have to do the side quest 'bar fight' for horde, and submerged outhouse quest below water before he gives you the next quest for the boat thing.\n\nAfter first landing on the Speedbarge, this side quest opens up from Rizzle out on deck. Head to the stern of the ship, southwest, but before going up the ramp upstairs, take a left and enter the bar. Daisy, the bartender, is serving plenty of gnomishω δ and goblinω δ bar patrons.\nA [Bottle of Grog] costs 20 , so buy one and smash it over the head of a nearby goblin!\n\nOn starting the fight:\n\nGoblin Bar patron yells: !\nBAR FIGHT!\nDaisy lets the fight go on for a minute or so as the Brute Squad is called in!\nDaisy yells: Break it up! The Brute Squad is coming!",
            date = "2011-04-17T04:08:02-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25516#comments:id=1393162",
        },
        {
            id = 1187728,
            score = 7,
            author = "parazyte",
            text = "If you hand in this quest do you loose the flippers and diving helmet? I'm reluctant to hand in...",
            date = "2010-11-26T13:21:05-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25516#comments:id=1187728",
        },
        {
            id = 1393158,
            score = 7,
            author = "816934",
            text = "I'm having the same issue of not getting the next quest. I'm 85 horde and the chain just ends after down in the deeps. Hoping someone can shed some light on the situation as I need this boat thing for a project we're doing.",
            date = "2011-04-17T04:02:01-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25516#comments:id=1393158",
        },
    },
    [25517] = {
        {
