            score = 36,
            author = "Raincloud",
            text = "Ground floor of the barge go into the bar and left and speak to Daisy [npc=40832 domain=www] and buy a bottle of grog [item=54746 domain=www] then target a goblin and use the iem",
            date = "2010-11-29T14:32:56-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25517#comments:id=1195920",
        },
        {
            id = 1281399,
