    [25518] = {
        {
            id = 1207901,
            score = 29,
            author = "Inexorability",
            text = "I was up and down all over the barge looking for her, so if you also have trouble finding her: from the questgiver, go through the door into the main \"building\" and turn left. Follow that until you see a human female behind the bar. She's also an innkeeper, so you can track her.",
            date = "2010-12-05T09:51:51-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25518#comments:id=1207901",
        },
        {
            id = 1296638,
