            author = "Orentis",
            text = "This quest is horribly un-commented on here! By far one of the funnier Cata quests! Everyone going ape s--- on each other in the pub was AWESOME.",
            date = "2011-01-16T16:32:33-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25518#comments:id=1296638",
        },
        {
