            author = "698680",
            text = "Gives you 250 [faction=369] rep, 125 with the other 3, and no loss in [faction=87] rep.",
            date = "2011-01-22T05:40:53-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25522#comments:id=1303887",
        },
        {
            id = 1197133,
            score = 13,
            author = "Azrilar",
            text = "When you complete the quest the NPC reveals that Chelsea was actually under food poisoning and was never stung by a scorpion/scorpid.",
            date = "2010-11-30T04:06:17-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25522#comments:id=1197133",
        },
        {
            id = 1564405,
            score = 13,
            author = "Aamunkajo",
            text = "To do this quest you have to do I'm With Scorpid (http://www.wowhead.com/quest=25521) from the same questgiver first. No other quests required.\n\nA fast way to get one of the first intellect or strength trinkets in the game.",
            date = "2011-11-06T05:34:31-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25522#comments:id=1564405",
        },
        {
            id = 1283867,
            score = 11,
            author = "Sketchie",
            text = "After you turn in the quest, the following happens:\n\nGus Rustflutter says: Chelsea, baby, sit up! I've got it! This is gonna cure you!\nChelsea Rustflutter says: Urgh. Gus, I ain't drinking that, I can smell it from here. Just lemme sleep the food poisoning off, okay?\nGus Rustleflutter says: ...food poisoning? Wait, you mean those basilisk steaks? That's all it is?\nChelsea Rustflutter says: Blech! Don't even say it. Of course it was, those were so undercooked...what'd you think poisoned me?\nGus Rustflutter says: Nothing, honey. I'm just glad you're okay...\n\nIf you idle around Gus and Chelsea, they will periodically say the following:\nChelsea Rustflutter says: Gus... you gotta... get me one of them gnome medics...\nGus Rustflutter says: Chelsea, baby, that's crazy talk! You're delirious! Just hold on a while longer...",
            date = "2011-01-08T10:51:47-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25522#comments:id=1283867",
        },
        {
            id = 1175819,
            score = 7,
            author = "sacreddevil",
            text = "Ally can get this quest too.",
            date = "2010-11-20T09:49:39-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25522#comments:id=1175819",
        },
    },
    [25524] = {
        {
            id = 1541169,
            score = 11,
            author = "Layla170",
            text = "You will kick yourself when you realise how easy this was to miss. Go to the outhouse that is underwater - then move forwards towards the gully, there is another one in there with the quest giver. Then kill 2 or 3 of the divers and you should get the crowbar, check your inventory each time otherwise you will just keep killing. Then go back to the outhouse and click the crowbar, you should then be able to complete the quest.",
            date = "2011-10-12T12:01:50-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25524#comments:id=1541169",
        },
        {
            id = 1442134,
            score = 9,
            author = "Rooination",
