    [25532] = {
        {
            id = 1180461,
            score = 37,
            author = "287123",
            text = "For Alliance you must complete In the Outhouse (http://www.wowhead.com/quest=25524) and rescue Drag Master Miglen (http://www.wowhead.com/npc=40598) in order for Jinky Twizzlefixxit (http://www.wowhead.com/npc=40475) to give you this quest.\n\nEdited to be more accurate.",
            date = "2010-11-24T06:18:15-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25532#comments:id=1180461",
        },
        {
            id = 1322222,
            score = 21,
            author = "274176",
            text = "Just did this quest....I noticed the fires on the deck didn't go out when I sprayed them. However, aiming the water at the fires on the buildings worked almost every time. Hope this helps.",
            date = "2011-02-05T02:35:22-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25532#comments:id=1322222",
        },
        {
            id = 1186344,
            score = 17,
            author = "Diwtay",
            text = "Mazzer Stripscrew is at [78,75] on the goblin side barge.",
            date = "2010-11-26T00:19:11-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25532#comments:id=1186344",
        },
        {
            id = 1847653,
            score = 12,
            author = "lastbornnobody",
            text = "There are 2 NPCs named Mazzer Stripscrew. If the one you are talking to doesn't offer you a boat you are talking to the wrong one. You want the one on the south end.",
            date = "2013-04-27T15:33:08-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25532#comments:id=1847653",
        },
        {
            id = 1438176,
            score = 11,
            author = "StansDad",
            text = "A really annoying quest; maddeningly difficult due to the fact that aiming water onto most of the fires does nothing!\nSome people have found that aiming at the fires in the buildings is a more productive tactic, but I found that any fire near the edge of any structure can easily be extinguished by aiming the water jet not directly onto the fire, but directly onto the timbers along the outer edge of the structure where the fire is.\nOnce I discovered that it was a piece of cake!\n\nn.b. riinuka's post lower down makes the same point with rather less superfluous verbosity and rather more clarity... Aim for the outside edges, that's the trick!",
            date = "2011-06-10T00:28:44-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25532#comments:id=1438176",
        },
    },
    [25533] = {
        {
            id = 1182397,
            score = 37,
            author = "509570",
            text = "Griznak is located south of the main barge on the smaller of the two platforms!",
            date = "2010-11-24T17:13:49-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25533#comments:id=1182397",
        },
        {
            id = 1187234,
            score = 34,
            author = "707541",
            text = "Bar Fight! (http://www.wowhead.com/quest=25518), In the Outhouse (http://www.wowhead.com/quest=25526) and Down in the Deeps (http://www.wowhead.com/quest=25516) must be done before this is available.",
            date = "2010-11-26T09:25:06-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25533#comments:id=1187234",
        },
        {
            id = 1392794,
            score = 16,
            author = "176962",
            text = "It took me a while to figure this one out.  Your movement keys (right, left) swing your character around on the gunner chair.  So the \"in front of you\" means when your gunner chair faces the ship, not looking towards the prow of your own boat.  It still took a while since a lot of fires didn't seem to react, but I finally got it done.",
            date = "2011-04-16T15:46:26-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25533#comments:id=1392794",
        },
        {
            id = 1206559,
            score = 13,
            author = "Talvanor",
            text = "\"> GET BOAT\n\nYou can't imagine what you'd do with a boat, as you are in the desert, but you resolve to keep this firmly in mind - when you next encounter a boat, you will attempt to get it.\"",
            date = "2010-12-04T17:22:38-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25533#comments:id=1206559",
        },
        {
            id = 1181530,
            score = 11,
            author = "wereowl",
            text = "You also have to do the quest from the Submerged  outhouse below the ship, so turn on your lowbie quest tracking.",
            date = "2010-11-24T12:48:28-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25533#comments:id=1181530",
        },
    },
    [25534] = {
        {
            id = 1182034,
            score = 9,
            author = "166836",
            text = "He`s on the first ship on the lower deck where the canons are going off (sorry, i`m not english ^^) I guess his respwantimer has something around 3 minutes.",
            date = "2010-11-24T15:12:38-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25534#comments:id=1182034",
        },
        {
            id = 1242050,
            score = 4,
            author = "125070",
            text = "Getting onto the ship without aggroing a million people was difficult, as this quest is kinda glitched atm. Whenever you run up the gangplank, the sailors on the deck as well as below will aggro. But then I remember I was a hunter. So I used Feign Death when I got onto the ship, and once I was on there was no glitchy aggro issues.\n\ntl;dr hunters use Feign Death, rogues/druids stealth onto the boat, locks can soulstone once they die, and shaman can Rebirth. Nelfs can shadowmeld, and everyone else would be best off dying and rezzing on the ship.\n\n:)",
            date = "2010-12-18T00:47:10-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25534#comments:id=1242050",
        },
        {
            id = 1274742,
            score = 2,
            author = "643730",
            text = "Definitely a bugged quest. In addition to the aggroing everybody, every mob has an AOE attack that was hitting my level 46 hunter for about 100 HP every tick and my pet crab for about 70 every tick; it's the first time I've seen his health drop so quickly.",
            date = "2011-01-03T08:34:34-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25534#comments:id=1274742",
        },
        {
            id = 1294054,
            score = 2,
            author = "266982",
            text = "Everything posted so far is true.  I too am a hunter.  I ran to the dock.  You can't just stand and casually take out the mobs on the dock (2 or 3 of them) because of the cannons firing at you.  You need to rush them.  Your pet will NOT go up the ramp.  If you run up, you will agro at least 5 mobs all throwing a most anoying AOE and beating the heck out of you.  Alone. No pet.\n\nSo, I mounted up, ran up the ramp, agro'ed the 5 mobs (three from cabin and two from on deck) and ran to the bow of the ship to the right.  When in the bow, I feigned death.  This left only 2 mobs for my pet to deal with.  I came back and helped him.  Then we attacked the 3 mobs in the cabin on the other side (left) of the ship.  At the bottom of the stairs there were 3 more mobs.  Killed them.  Then the Taskmaster.",
            date = "2011-01-14T20:13:45-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25534#comments:id=1294054",
        },
        {
            id = 1310766,
            score = 2,
            author = "Klarizza",
            text = "As a priest...I used Power Word: Shield and killed all the mobs on the top deck and in the stairs room plus the mob on the gun deck with the taskmaster...Then easily killed the taskmaster...you do have to re-up Power Word: Shield a time or two during the process...!",
            date = "2011-01-26T13:41:54-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25534#comments:id=1310766",
        },
    },
    [25541] = {
        {
            id = 1192403,
            score = 3,
            author = "Hmmster",
            text = "If you find yourself killing the mobs at the small camp, move right to get to (70.00 53.00) and you'll have alot more mobs to kill.",
            date = "2010-11-28T04:49:12-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25541#comments:id=1192403",
        },
        {
            id = 1223524,
            score = 1,
            author = "472145",
            text = "Couldn't loot the mobs. would just lock up in looting animation and stand there until cancelled.",
            date = "2010-12-11T02:40:55-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25541#comments:id=1223524",
        },
        {
            id = 2548683,
            score = 1,
            author = "svend97",
            text = "Both the Musketeers and the Strongarms respawn very quick (we're talking about 15 seconds). Don't try to pull too many, because before you know it you're surrounded by five of them.",
            date = "2018-01-27T06:52:19-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25541#comments:id=2548683",
        },
        {
            id = 1200197,
            score = 0,
            author = "488143",
            text = "cant complete this quest neither on wednesday(Pathc day) cos the npc is still missing... this is takin ages to fix",
            date = "2010-12-01T12:54:13-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25541#comments:id=1200197",
        },
        {
            id = 1332467,
            score = 0,
            author = "468152",
            text = "Does Blizzard not want people to do these quests at all?  First is the Bugging Dock of Doom, and now there's the Deadly Camp of Death Knight Pirates?\n\nThe first 2 times I tried to kill some pirates for this quest, they chain-\"grip\"ed me (Southsea Strongarm, Impaling Pull), causing me to aggro 5-6 of them at a time.  And I'm a clothie.  So it was insta-death.  Thanks to that little session of trial-and-error, I realized a good strategy for casters: Hit and run.\n\nSpecifically, cast your opener, then move away, so they have to chase after you to \"grip\" you.  This way you can keep from aggroing more than 1 at a time, and make inroads on an encampment of pirates.\n\np.s.   Fortunately, there are also musketeers, who are easy pickings.  I had a bad mob selection.",
            date = "2011-02-11T22:10:00-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25541#comments:id=1332467",
        },
    },
    [25542] = {
        {
            id = 1204621,
            score = 47,
            author = "46662",
            text = "If you are like me and foolishly departed your boat after putting out 15 fires during the previous quest, you'll likely be wondering right now just where the heck the cannons are.\n\nThe cannons are on the same boat you just left. If you are back on the barge, go find Mazzer Stripscrew again (the guy who put you on the boat during the previous quest). He'll put you back on board your boat, ready to sink those lousy pirates.",
            date = "2010-12-03T16:37:56-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25542#comments:id=1204621",
        },
        {
            id = 2304613,
            score = 6,
            author = "DeliaDelilah",
            text = "The most natural thing to do when u FINALLY get the fires out is to disembark....NOPE Do Not do it!\nPart of quests like these instructions should read.\n\"Go to wowhead after getting the quest so u can figure out what we are up to here at Bliz.!\"",
            date = "2016-02-05T15:54:19-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25542#comments:id=2304613",
        },
        {
            id = 1493957,
            score = 5,
            author = "mikeywest",
            text = "i think everyone else will agree this was 100% easier than the previous quest",
            date = "2011-08-13T09:38:03-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25542#comments:id=1493957",
        },
        {
            id = 1406152,
            score = 3,
            author = "822739",
            text = "My thanks to Daco and mb7756. Having left the boat, I was completely confused. Killed all the pirates on the three ships, but the cannonballs kept coming.\n\nJust now, I spoke to Mazzer Stripscrew, because I found him before Griznak, and he did get me back on the boat. Perhaps both of them will do it.",
            date = "2011-05-01T10:58:40-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25542#comments:id=1406152",
        },
        {
            id = 1195322,
            score = 2,
            author = "bluspacecow",
            text = "Griznak is on one of the floating islands to the right of the barge facing outwards from the inn. He will be by the tent on the ramp you come in on when your sent to the barge by the little breadcrumb quest you do when sent to the Barrens.\n\nAlso I've found the key to getting credit bombing the boats is to aim at the prow or front of the ship. Aim at the sides or back and by the time your projectile gets to the boat it misses.",
            date = "2010-11-29T09:33:55-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25542#comments:id=1195322",
        },
    },
