    [25566] = {
        {
            id = 3187291,
            score = 121,
            author = "Lesja",
            text = "As of 8.3 this quest is bugged at max level. When you enter building you can see the chest, but when you approach the chest it disappear. After some initial cursing I realized that the inner part of the building is inside Uldum, so I guess we can blame N'Zoth.\n\nSo what you need to do is go to Ramkahen and talk to Zidormi and request to be sent to another point in Uldum's history.",
            date = "2020-01-30T11:45:50-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25566#comments:id=3187291",
        },
        {
            id = 5155227,
            score = 5,
            author = "strokess",
            text = "I'm trying to do the [The Secrets of Uldum] quest and it keeps porting the treasure chest away due to crossing over to Uldum. What's the secret to having this stop?",
            date = "2021-04-18T06:43:10-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25566#comments:id=5155227",
        },
        {
            id = 1884346,
            score = 4,
            author = "lonedove",
            text = "Go back to the area where you fought the Sandstone Guardians. Entrance to the Ruins at map coordinates 37, 78. Enter and go straight to chest.",
            date = "2013-08-05T23:00:06-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25566#comments:id=1884346",
        },
        {
            id = 1179956,
            score = 3,
            author = "460502",
            text = "Everytime I try to approach the object with the ? over it I get teleported to the entrance of the cave.\n\nI'm assuming this is because Cataclysm hasn't launched yet.",
            date = "2010-11-24T02:03:18-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25566#comments:id=1179956",
        },
        {
            id = 1206969,
            score = 3,
            author = "earwinrocks",
            text = "Hi all. I was just running around on the water near tanaris and saw a new looking building . When I went to check it out I ended up in Uldum right next to the chest and was able to complete the quest line.",
            date = "2010-12-04T21:46:51-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25566#comments:id=1206969",
        },
    },
    [25585] = {
        {
            id = 1429070,
            score = 7,
            author = "127222",
            text = "at least u can find your boat. I did the put out the fire quest, left the boat  - picked up the new quests and now i cant get on the boat again, well i see it and i can fly to it but everyone on  the crew ignores me and i have no control. I do notice some sort of jet pack on my back but its not reflected in my gear or bag or quest objectives. any suggestions?\n\npost note:the jet pack thing was to enable me to breathe underwater and  i was able to complete all the quests without the boat (something easy to do if u can fly, wouldn't want to think how long it would take without it)\n\npost note 2: just discovered a 'pirate hat' in my bag. u click on it to summon your boat. It may look different depending on the reward u picked from dousing the fires as the hat looks like the icon from the gear reward and its placed in the trinket section of my bags (add on bag sorter) not with the regualr quest items. the neat thing is ive done most of the quests here now and the 'boat' is still with me. The items says i can summon it anytime while in thousand needles so it looks like it may be a permanent item u get while questing which is a blessing for those at the proper lvl and no flying mount. Also just a tip - try to walk along the river floor when questing as u move much faster if your feet are touching the ground and not swimming.",
            date = "2011-05-28T02:21:58-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25585#comments:id=1429070",
        },
        {
            id = 1283094,
            score = 6,
            author = "babeblu86",
            text = "since no one seemed to mention just in case someone needs to know...the cannons are on shore up a hill NOT on the boats...i figured this out after running around for a few minutes trying to destroy the boat cannons. you can also destroy these cannons while mounted.",
            date = "2011-01-07T22:35:12-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25585#comments:id=1283094",
        },
        {
            id = 2543282,
            score = 6,
            author = "Hargir",
            text = "Adding this note because it is not at all obvious:\n\nYou need to be in the water - then you right-click the pirate hat in your inventory to summon your boat. Saves you a lot of time getting to the shore.",
            date = "2017-12-31T04:18:54-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25585#comments:id=2543282",
        },
        {
            id = 1335087,
            score = 4,
            author = "geniusdude",
            text = "Yeeeeeeeeeaaaaaaaaaaah!\nwe need some bad puns here",
            date = "2011-02-13T19:06:26-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25585#comments:id=1335087",
        },
        {
            id = 1423450,
            score = 3,
            author = "578800",
            text = "Dumb noob question, I know. HOW do you leave/exit the dam*&d boat once you get IN it? Currently, I'm on the boat, landlocked (stuck) and cannot Hearth, or anything else to try and get out of the boat!",
            date = "2011-05-20T20:22:48-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25585#comments:id=1423450",
