    [25586] = {
        {
            id = 1203735,
            score = 19,
            author = "194296",
            text = "I thought it was also unclear what to do for this quest. But I figured it out after I completed it.\n\nYou get a hat in your inventory that when you right click on it, it will summon a boat that you can drive there yourself. It would have been useful but its all the same if you just swim to the pirate ships 90, 76.",
            date = "2010-12-03T08:16:35-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25586#comments:id=1203735",
        },
        {
            id = 1192422,
            score = 17,
            author = "311745",
            text = "It is not immediately clear what to do for this quest. Swim/Hop in your boat and head over to the shore next to the pirate ships at 90, 76. Go up the shore and click the cannons to destroy them.",
            date = "2010-11-28T05:03:17-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25586#comments:id=1192422",
        },
        {
            id = 1250462,
            score = 11,
            author = "702724",
            text = "I ran around and around looking for \"my boat\" or anyone that might give me one. The previous boat quest catapults you off your boat into the air, parachuting onto the barge so you don't just \"park it\". That previous quest also gave you the \"River Boat\" item, which is NOT a highlighted quest item. As previously pointed out, it looks like a black pirate hat.\n\nRiver boat - Use: Summon your river boat on the water's surface within 20 yards. May only be used in Thousand Needles (1 sec. cooldown)\n\nJust rightclick on it to start the quest boatwise.\n\nYou actually get to drive the boat around, it's not an autoboat. If you run into ANYTHING on the water's surface, the boat disappears and it puts you on top of whatever you ran into, even a plank of wood. You can summon this boat FROM the water too. (Thankfully!) There's a dock up by the pirate ships that you can drive the boat ONTO. LOL\n\nIf you want to save some trips, Make sure you get the \"A Little payback\" and \"Where's Synge?\" quests before going over here.",
            date = "2010-12-21T13:40:48-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25586#comments:id=1250462",
        },
        {
            id = 1294152,
            score = 8,
            author = "174766",
            text = "(puts on glasses) Yeeeeeeeeeaaaaaaaaaaah!",
            date = "2011-01-14T21:42:02-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25586#comments:id=1294152",
        },
        {
            id = 1369456,
            score = 7,
            author = "360853",
            text = "The canons that you have to destroy are on the shore, not on the boat!",
            date = "2011-03-17T17:43:19-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25586#comments:id=1369456",
        },
    },
    [25588] = {
        {
            id = 1282112,
            score = 9,
            author = "164286",
            text = "To start this quest from Miglen after rescuing him (http://www.wowhead.com/quest=25524) and collecting your boat parts (http://www.wowhead.com/quest=25515), you first have to finish the two (http://www.wowhead.com/quest=25532) quests (http://www.wowhead.com/quest=25542) on the speedboat. After you sink 15 pirates, you have to manually leave your vehicle; it will fire you back onto the speedbarge.",
            date = "2011-01-07T09:26:42-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25588#comments:id=1282112",
        },
        {
            id = 1605285,
            score = 1,
            author = "212703",
            text = "The hut south of where Wizzle Brassbolts is held has two Southsea Pirates in it. The one in the far corner is dancing away and only stops to drink from a bottle, (and as a pirate it has to be rum,) or to perform a \"technicolour yawn\". Yes, he falls to his knees and proceeds to projectile vommit...brilliant, my respects to the Blizzard programmer who got this into the game.",
            date = "2012-01-01T15:33:42-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25588#comments:id=1605285",
        },
        {
            id = 1853772,
            score = -1,
            author = "1121074",
            text = "has anyone noticed that the goblin southsea sailors are doing the soldier boy dance? XD",
            date = "2013-05-17T08:08:55-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25588#comments:id=1853772",
        },
    },
