    [25591] = {
        {
            id = 1469206,
            score = 95,
            author = "Freeaze",
            text = "You have to complete the quests at Dunmaul Compund to start the final arena-quest.\nI tried it and it worked :)\nIt's 4 simple quests that have to be done: First get 8 signatures, then kill about 20 insects at the Noxious Lair, then feed 8 orges and last and easiest kill the Ogre standing in the cave :)\nThen run up to Gadgetzan and keep doing the arena quests!\n\n(Thumb me up to make it easier to track for those wondering how to start the quest)",
            date = "2011-07-13T20:15:55-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25591#comments:id=1469206",
        },
        {
            id = 1190169,
            score = 51,
            author = "300191",
            text = "Found a fix for this bug. When the match starts, let the goblin and the gnome attack each other until the gnome summons her pounder. Kill the pounder like normal. After about 10 different methods and 20 attempts, this one worked for me.",
            date = "2010-11-27T10:25:43-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25591#comments:id=1190169",
        },
        {
            id = 1380319,
            score = 33,
            author = "57437",
            text = "Best bug ever!\n\nKilled the robot with 47 fury warrior, but still couldn't attack Kelsey Steelspark after. So I just ran around avoiding the lightning bold spider she casts. Kelsey ended up kill the other guy, quest failed like normal, but the lightning spider ran around Gadgetzan for 30 minutes chasing and killing people.\n\nWas awesome.",
            date = "2011-03-30T18:40:41-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25591#comments:id=1380319",
        },
        {
            id = 1205054,
            score = 11,
            author = "scr00chy",
            text = "I tried to do this twice and failed both times for no reason after killing the robot. I thought maybe the objective was bugged and the quest was copied from alliance side so that Megs had to die to complete. I let Megs die on my third attempt and failed again.\n\nThen, remembering other quests that were bugged in a similar fashion, on my fourth attempt I made sure that when I obtained aggro on the gnome, I pulled her a significant distance away from her spawning location instead of attacking her where she started. This time after killing the robot I got an objective complete.\n\nThanks so much for the tip! This worked like a charm. I just pulled the gnome away when she became attackable and then I was able to complete it just fine.",
            date = "2010-12-03T21:53:18-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25591#comments:id=1205054",
        },
        {
            id = 2020969,
            score = 8,
            author = "CAXAPrus",
            text = "as of 6.0.3 Patch this quest is bugged, if you want to do this quest, you have to kill the big mechanical boss from 100% health to 0% in 1-2 seconds, otherwise yout faction's fighter will begin running around arena and killling the mechanical boss will not make your fighter to stop running, he will just disappear and enemy faction's fighter will stay in middle, but final dialogue between fighters will not happen and later you get \"quest failed\", again, you have to kill mechanical boss BEFORE your fighter begins running around.\n\nsomeone report it to Blizzard (GMs), please",
            date = "2014-10-30T05:21:06-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25591#comments:id=2020969",
        },
    },
    [25596] = {
        {
            id = 1428929,
            score = 10,
            author = "Sindail",
            text = "I had a similar problem. I went looking for this quest chain cuz i wanted the gloves for my hunter as the end reward. I went straight there and no quests were available to me. I looked here and didnt see any replies so i went looking. I decided to go back to org and do the  Warchief's Command: Thousand Needles!\n  (http://www.wowhead.com/quest=28504). At this point i tried to see if it opened up yet and it still hadn't. So I went back and did  To the Summit  (http://www.wowhead.com/quest=25478). (availabl from the same NPC u turened the previous quest in to. After doing that one  Two if by boat  (http://www.wowhead.com/quest=25488) opened up (Thousand needles version) Upon completion of this quest  Where's Synge?  (http://www.wowhead.com/quest=25596) Finally becomes available! It sounds time comsuming but all it really is, is travel time and killing 7 mobs. Hope this helps future seekers.",
            date = "2011-05-27T20:07:45-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25596#comments:id=1428929",
        },
        {
            id = 1869448,
            score = 6,
            author = "581733",
            text = "Step-by-step: You can skip prereqs and start with The Grimtotem are Coming (http://www.wowhead.com/quest=25487), once on barge, follow the questline there (also have to complete In the Outhouse (http://www.wowhead.com/quest=25526) while you're doing Down in the Deeps (http://www.wowhead.com/quest=25516), and Bar Fight! (http://www.wowhead.com/quest=25518) anytime). After the \"Circle the wagons\" quests in the automated boat, Where's Synge (http://www.wowhead.com/quest=25596) will open up, allowing access to yer twink loot. Approx. 30 minutes from beginning to end of Synge quests. Happy hunting! (Since MoP 5.3)",
            date = "2013-06-22T13:08:36-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25596#comments:id=1869448",
        },
        {
            id = 1201548,
            score = 4,
            author = "Roshamboe",
            text = "Any ideas on what the prerequisites are to make this quest available?",
            date = "2010-12-02T03:15:54-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25596#comments:id=1201548",
        },
        {
            id = 1283691,
            score = 4,
            author = "306101",
            text = "Hey, , you haven't seen our gunsmith, Wizzle, have you?\n\nI was a little confused on this. Shouldn't the name be Synge instead of Wizzle? Especially since Wizzle is a no-good gnome.",
            date = "2011-01-08T08:43:53-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25596#comments:id=1283691",
        },
        {
            id = 1666305,
            score = 4,
            author = "ankorafeonix",
            text = "Just in case others have trouble figuring out how to get up onto the cliffs, go north to where the lake meets the ocean, and there is a dock with a slope you can walk up to get up there.",
            date = "2012-05-13T04:17:46-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25596#comments:id=1666305",
        },
    },
