    [25609] = {
        {
            id = 1196738,
            score = 3,
            author = "spriint",
            text = "The chests are located around the body of the big dead whale at 78;63",
            date = "2010-11-29T23:27:41-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25609#comments:id=1196738",
        },
        {
            id = 1197849,
            score = 1,
            author = "671328",
            text = "Had been looking for them for over 10 minutes without spotting a single chest, and then finally I found it: many, many chests in the chasm south of the Whale Shark (if you can't find that one, you really haven't taken a second to look before visiting Wowhead =P). There should be more than enough chests here for you to finish the quest.",
            date = "2010-11-30T12:56:03-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25609#comments:id=1197849",
        },
        {
            id = 1206350,
            score = 1,
            author = "favrebites",
            text = "Oh yeah! Look at all that booty.",
            date = "2010-12-04T15:13:32-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25609#comments:id=1206350",
        },
        {
            id = 1863033,
            score = 1,
            author = "Endek",
            text = "Another good location to start searching for the sunken treasure chests is deep down in the chasm around (78.8 , 67.4) which is just North of Fizzle and Pozzik's Speedbarge.  You'll find the sparkly chests scattered mostly along the chasm walls around half way down.\n\nJust keep an eye or two open for those pesky Southsea Treasure Hunters patrolling the abyss... sneaky they are and very protective of those chests!",
            date = "2013-06-05T08:01:16-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25609#comments:id=1863033",
        },
        {
            id = 2337370,
