        {
            id = 2878259,
            score = 3,
            author = "Bunnyhugs",
            text = "Can anyone confirm whether this quest, or however many involved in this chain, are needed to satisfy the \"Stardust Spire\" portion of https://www.wowhead.com/achievement=4925? The way the quests pop up on the map make it seem like they would be, but then they keep taking you way into Stonetalon.\n\nEDIT: Alright, can confirm myself that it's definitely not necessary, what's needed is a short chain that starts around the Shrine of Aessina with https://www.wowhead.com/quest=13976.",
            date = "2019-03-22T21:08:17-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25640#comments:id=2878259",
        },
        {
            id = 1337481,
            score = 0,
            author = "ayrwen",
            text = "The trick is to kill the oil canisters on their backs, then they'll explode and kill the elite.\nQuest is completed in half the time.",
            date = "2011-02-15T16:19:04-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25640#comments:id=1337481",
        },
    },
    [25641] = {
        {
            id = 1580652,
            score = 2,
            author = "535979",
            text = "Until you do this part of the quest, Uzer'i wont have anything to say to you, not even greyed out quests so its imperative to do the first 2 parts first, as they lead to many more.",
            date = "2011-11-25T16:17:29-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25641#comments:id=1580652",
        },
    },
