        {
            id = 1185041,
            score = 4,
            author = "244101",
            text = "As a level 80 warrior, I just used demoralizing shout to agro them and get them to toss the quest items rather than taking off all my armour.  So, any other classes out there with any non-damaging abilities could easily do the same.",
            date = "2010-11-25T14:07:43-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25642#comments:id=1185041",
        },
        {
            id = 1190595,
            score = 4,
            author = "Malekchoron",
            text = "As a level 80 rogue, you can use Feint to get them to throw the ore. They yell \"You no take ore!\" as they... throw it at you. No one ever said peons were smart.",
            date = "2010-11-27T13:48:12-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25642#comments:id=1190595",
        },
        {
            id = 1189064,
            score = 3,
            author = "Xaerjin",
            text = "Confirmed: One shotting the orcs before they drop their ore will cause the ore to disappear.",
            date = "2010-11-26T23:10:21-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25642#comments:id=1189064",
        },
    },
    [25643] = {
        {
            id = 1653461,
            score = 7,
            author = "onlymeaz",
            text = "To get to the Darkmist Ruins, I entered the Ruins of Isildien at 61.8/54.7 with a bunch of ogres whom I had to either kill or go around.  From there I followed the path to 62.0/64.1 where there are a bunch of \"Highborne Poltergeists\" in the area.  The amulet is in a small building at 65.9/62.8 where you will pick up another few quests from Sensiria (a demon in disguise).",
            date = "2012-04-13T18:46:36-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25643#comments:id=1653461",
        },
        {
            id = 2270618,
            score = 4,
            author = "Brienna",
            text = "You can also enter the ruins at about 68, 60 on the other side of the mountain.  It's south of the area where all the Woodpaw Alphas are for https://www.wowhead.com/quest=25364/https://www.wowhead.com/quest=25427  and from within the Woodpaw Alpha area at 64.9, 54.5.",
            date = "2015-11-01T08:54:44-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25643#comments:id=2270618",
        },
        {
            id = 1210808,
            score = 1,
            author = "Koviko",
            text = "The \"dead\" Lost Apprentice by the empty pedestal can be targeted and re-killed.",
            date = "2010-12-06T21:07:43-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25643#comments:id=1210808",
        },
        {
            id = 1848733,
            score = -1,
            author = "379501",
            text = "This and the Ally quest The Lost Apprentice (http://www.wowhead.com/quest=25350) are essentially bread-crumb quests to The Darkmist Legacy (http://www.wowhead.com/quest=25422) and Ancient Suffering (http://www.wowhead.com/quest=25423) from Sensiria (http://www.wowhead.com/npc=40131). Once you've finished her chain, be sure to get the finishing quest from the amulet: Horde's Return to Sage Palerunner (http://www.wowhead.com/quest=25645) and Ally's Return to Vestia (http://www.wowhead.com/quest=26401).",
            date = "2013-04-30T20:21:33-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25643#comments:id=1848733",
        },
    },
    [25645] = {
        {
            id = 6096900,
            score = 1,
            author = "JetGaren",
            text = "https://www.wowhead.com/achievement=4932\nSome Feralas quests are reported [icondb=2175464] Horde but i did these on an [icondb=2173919] Alliance character:\nhttps://www.wowhead.com/quest=25341,https://www.wowhead.com/quest=25252,https://www.wowhead.com/quest=25342,https://www.wowhead.com/quest=25344,https://www.wowhead.com/quest=25645,https://www.wowhead.com/quest=25645,\nhttps://www.wowhead.com/quest=25210,https://www.wowhead.com/quest=25230,https://www.wowhead.com/quest=25237,https://www.wowhead.com/quest=25241,https://www.wowhead.com/quest=25250.",
            date = "2025-04-15T16:34:03-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25645#comments:id=6096900",
        },
        {
            id = 1848734,
            score = 0,
            author = "379501",
            text = "This is the Horde ending to Sensiria (http://www.wowhead.com/npc=40131)'s quest chain. It began with the breadcrumb quest The Darkmist Ruins (http://www.wowhead.com/quest=25643), also from Sage Palerunner (http://www.wowhead.com/npc=5390).",
            date = "2013-04-30T20:24:06-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25645#comments:id=1848734",
        },
    },
