            score = 12,
            author = "708409",
            text = "The Huntress Jalin questline that leads you into Stonetalon is almost certainly a prerequisite for this.\nAt the very least you would need to free Boog the \"Gear Whisperer\".\n\nYou will find the letter that starts this quest during the natural course of completing Windshear Mine Cleanup (http://www.wowhead.com/quest=25646).",
            date = "2010-11-25T09:23:07-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25647#comments:id=1184353",
        },
        {
            id = 1471268,
            score = 6,
            author = "CWR03",
            text = "You should get the \"Illegible Orc Letter\" from the first kill for the Windshear Mine Cleanup quest.  You'll want to go right back outside and turn it in for the next part in the series to avoid a lot of backtracking.",
            date = "2011-07-16T03:42:36-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25647#comments:id=1471268",
        },
