    [25649] = {
        {
            id = 1210612,
            score = 30,
            author = "AmberD",
            text = "I had a great deal of difficulty finding the above npc with the current directions, so I will try and clarify. From the entrance, proceed straight along to the large central chamber. As you enter,you will see a large piece of machinery with logs hanging from it. The tunnel you want is just behind it. She is straight ahead from there standing on a wooden scaffold.",
            date = "2010-12-06T17:58:41-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25649#comments:id=1210612",
        },
        {
            id = 1256470,
            score = 21,
            author = "Kreemer",
            text = "Please be aware that there is an upper and a lower entrance.  She is in the upper entrance that is to the right of the quest giver as you face him.  Then follow AmberD's directions.",
            date = "2010-12-24T10:23:04-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25649#comments:id=1256470",
        },
        {
            id = 1354990,
