    [25654] = {
        {
            id = 1242429,
            score = 23,
            author = "737032",
            text = "there's a path that heads north up hill slightly.  The path will have some lanterns.  At the end of the short path there is a stone with a hole in it.  It should blink when moused over.  This is where you blow the horn.",
            date = "2010-12-18T05:08:46-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25654#comments:id=1242429",
        },
        {
            id = 1828281,
            score = 19,
            author = "1021255",
            text = "The place where you need to blow the https://www.wowhead.com/item=9530 is actually the vortex between 3 stones. (coordinates 40.6, 8.5) Two tall stones of equal height that stand across from each other on either side of the path and one short stone (hollowed in the middle with glowing yellowish lights) that stands at the end of the path. If you mouse over any of the three proper stones you will get a visual confirmation. (The stones glow with a whitish hue.)\n\nRemember that the horn is in your inventory because it drops from the first harpy that you kill.",
            date = "2013-03-13T23:11:52-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25654#comments:id=1828281",
        },
        {
            id = 3145131,
            score = 16,
            author = "Netspook",
            text = "The horn will still have a 100% drop rate from the first harpy you kill in the area, but pay attention!\n\nThere's no message showing you got it, and there will not be any clickable button anywhere to use it like most other such quests have. You must find it in your inventory and right-click to use it.",
            date = "2019-08-03T08:32:50-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25654#comments:id=3145131",
        },
        {
            id = 1302080,
            score = 10,
            author = "674982",
            text = "The path that another user speaks of is very short and starts at 41.4, 9.4 and the stones are at coords 40.5, 8.6",
            date = "2011-01-20T16:59:02-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25654#comments:id=1302080",
        },
        {
            id = 1456997,
            score = 4,
            author = "767073",
            text = "So Where Would I find the horn? I Have looked all around and did not find anything?",
            date = "2011-07-01T10:45:15-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25654#comments:id=1456997",
        },
    },
    [25660] = {
        {
            id = 1201537,
            score = 15,
            author = "Roshamboe",
            text = "Sooo.... How do you make this quest available? anyone?",
            date = "2010-12-02T03:06:07-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25660#comments:id=1201537",
        },
        {
            id = 3233147,
            score = 11,
            author = "CubKnight",
            text = "If you're like me and can't get the Spirit of Tony Two-Tusk to spawn, leave the zone. As soon as you go back in he should spawn next to you. Took me way too long to figure this out.",
            date = "2020-09-26T06:19:42-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25660#comments:id=3233147",
        },
        {
            id = 2315130,
            score = 6,
            author = "thlayliroo",
            text = "The lead-ups to this quest are https://www.wowhead.com/quest=25596 and https://www.wowhead.com/quest=25590, for Horde and Alliance respectively.\n\nHowever, to unlock that quest, you need to complete the https://www.wowhead.com/quest=25487 and https://www.wowhead.com/quest=25745 quest chains. Make sure you grab https://www.wowhead.com/quest=25526 while you're doing https://www.wowhead.com/quest=25516. You also have to complete https://www.wowhead.com/quest=25518 once it becomes available.",
            date = "2016-03-18T14:07:18-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25660#comments:id=2315130",
        },
        {
            id = 1565119,
            score = 4,
            author = "Kyeld",
            text = "be prepared to kill about a thousand pirates if you accept this quest chain... there's no shortcut to Ajamon that I could find, so unless you're flying, you've got to reclear the entire camp for each turn-in along the way.",
            date = "2011-11-06T20:59:40-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25660#comments:id=1565119",
        },
        {
            id = 1308818,
            score = 2,
            author = "turtlegodkame",
            text = "can I keep Tony two-tusks?  like the haunted momento spirit?",
            date = "2011-01-25T01:51:45-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25660#comments:id=1308818",
        },
    },
    [25661] = {
        {
            id = 1181838,
            score = 50,
            author = "244193",
            text = "Dolly is on the docked ship.\n\nThen going south, Fajardo is on the next ship.\n\nAnd Lilly is on the last.\n\nTo reach Fajardo and Lilly, you have to USE the rope ladder on the left side of each ship(action icon will pop up when you get close to them)",
            date = "2010-11-24T14:20:01-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25661#comments:id=1181838",
        },
        {
            id = 1307854,
            score = 27,
            author = "214503",
            text = "This Tony Two-Tusk guy is awesome. He keeps talking to you when you're doing this quest. One of the things he says is ''Didn't take me long to build a pirate empire out of almost nothing. Ah, the barrens. Now those were the days. Hey, did anyone ever find out what happened to Mankrik's wife?''",
            date = "2011-01-24T11:10:22-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25661#comments:id=1307854",
        },
        {
            id = 1367871,
            score = 16,
            author = "Borelia",
            text = "...from my friends",
            date = "2011-03-15T19:55:13-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25661#comments:id=1367871",
        },
        {
            id = 1322292,
            score = 15,
            author = "silin",
            text = "Spirit of Tony Two-Tusk says: That whole thing with Ajamon's sister was a big misunderstanding.  I didn't do it, I swear!  I think it was https://www.wowhead.com/npc=41081.  The little brat kinda looks like him.",
            date = "2011-02-05T04:39:14-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25661#comments:id=1322292",
        },
        {
            id = 1193649,
            score = 13,
            author = "Borelia",
            text = "Did....did I just turn on Jerry Springer when I accepted this quest?",
            date = "2010-11-28T14:55:53-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25661#comments:id=1193649",
        },
    },
    [25662] = {
        {
            id = 1184396,
            score = 15,
            author = "708409",
