    [25667] = {
        {
            id = 2492474,
            score = 4,
            author = "whxskers",
            text = "For those of you like me who can get lost with even the simplest of quests....\n\nThis quest, along with the other quests you'll get from the surrounding quest givers, take place in The Grizzled Den behind Kharanos. If you walk straight forward from the Flight Master towards the NPC Mountaineer Dolf, you can hop down the cliff and you'll be there. Or, you can exit Kharanos at 53.48, 48.92 and then go left. The slope down to the den area starts 51.45, 49.79.",
            date = "2017-05-05T14:12:24-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25667#comments:id=2492474",
        },
        {
            id = 1195740,
            score = 3,
            author = "Carnagefiend",
            text = "These guys have a decently sized aggro range. While this isn't so much of a problem outside the cave, be expected to kill every single wendigo you run across. Failing to do so will often cause multiple mobs to aggro on you at once.\n\nI would recommend setting your Hearthstone to Kharanos asap so that you can just escape the cave easily. Barring that, kill 'em all.",
            date = "2010-11-29T13:05:46-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25667#comments:id=1195740",
        },
        {
            id = 2296719,
            score = 3,
            author = "942396",
            text = "Prerequisite: https://www.wowhead.com/quest=25724",
            date = "2016-01-10T08:50:03-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25667#comments:id=2296719",
        },
    },
