        },
        {
            id = 1193450,
            score = 7,
            author = "513530",
            text = "You have to talk to Illiona while she is still locked inside her cage.  She will complete the quest Free Our Sisters and then give you this one.  When you accept it, Roktrog spawns behind you.  Kill him, loot the key and free her.",
