        {
            id = 1202851,
            score = 2,
            author = "Whiterock",
            text = "Quest talk:\n\nStarting quest.\n\nWarlord Roktrog (http://www.wowhead.com/npc=41063) yells: Now you all die!\n\nAfter Warlord Roktrog (http://www.wowhead.com/npc=41063)'s death.\n\nHuntress Illiona (http://www.wowhead.com/npc=41071) says: Well done, ! Return to Windshear Hold and notify Lord Fallowmere (http://www.wowhead.com/npc=40896) of the Horde's intentions. I will venture to the Thal'darah Overlook and warn our soldiers.",
            date = "2010-12-02T19:36:08-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25669#comments:id=1202851",
        },
        {
            id = 1972251,
            score = 1,
            author = "1211235",
            text = "To complete this quest you need to kill Warlord Roktrog and loot a key. You need to talk to Huntress Illiona to make the Warlord Roktrog appear.",
            date = "2014-06-13T22:51:18-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25669#comments:id=1972251",
        },
    },
