        {
            id = 1197096,
            score = 7,
            author = "713673",
            text = "This is a good quest to combo with \"Mr. P's Wild Ride (http://www.wowhead.com/quest=25728)\".    If you're working on Darnassus rep, then consider not turning in this quest so you can have access to Mr. P for the daily quest and the 250 rep.",
            date = "2010-11-30T03:43:02-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25671#comments:id=1197096",
        },
        {
            id = 1318862,
            score = 6,
            author = "183073",
            text = "if your like me and exalted with darnassus don't bother coming to get this quest because it won't be available to u",
            date = "2011-02-02T02:12:02-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25671#comments:id=1318862",
        },
        {
            id = 1244820,
            score = 3,
            author = "658754",
            text = "I don't know if it's my level(34), my reputation with Darnassus(exalted) or the fact that I've passed on from Stonetalon to Barrens, but I attempted to return to pick up this quest for the A Simple Re-Quest (http://www.wowhead.com/achievement=31) achievement, and couldn't, Lord Darrowmere didn't have it any more.\nMight be any combination of the above, but if you want to do this repeatedly, then I would suggest not 'getting away' from it, so to speak.",
            date = "2010-12-19T03:47:16-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25671#comments:id=1244820",
        },
    },
    [25672] = {
        {
            id = 1181584,
            score = 164,
            author = "Lightor",
            text = "Found a bunch around 78.0, 54.7.  Be sure to check not only the bottom of the water but the surface as well for floating carcasses.",
            date = "2010-11-24T13:05:33-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25672#comments:id=1181584",
        },
        {
            id = 1278447,
            score = 33,
            author = "Bungalow",
            text = "A tip when you are underwater, run on the ground. You will actually move faster.",
            date = "2011-01-05T08:26:13-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25672#comments:id=1278447",
        },
        {
            id = 1303675,
            score = 26,
            author = "155329",
            text = "Another good way to find these if you're not using coordinates is to remember The Legend of Zelda: Wind Waker - look for flocks of seagulls flying around! They usually circle around a large pack of turtle corpses.",
            date = "2011-01-21T23:31:42-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25672#comments:id=1303675",
        },
        {
            id = 1186558,
            score = 19,
            author = "Diwtay",
            text = "Lots at [82, 54] on the ocean floor. Dead turtles",
            date = "2010-11-26T02:38:24-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25672#comments:id=1186558",
        },
        {
            id = 1244955,
            score = 17,
            author = "615648",
            text = "If you spent a lot of time grinding here pre-cataclysm, this quest is quiet easy.  Any of the areas that used to have regular zone trash now contain the corpses used for this quest.\n\nEssentially, from Fizzle and Pozzik's Speedbarge just swim or epicly underwater drive north.    If you remember how it used to be,  this area has a crater filled with basalisks,  salt plains with scorpids and what not, then north along the ridge line were groupings of turtles.   It's all the same, the mobs are still there (albiet not as alive as they used to be), everything is just under water.\n\nSo just swim around the old grinding areas, collect some corpses, done.",
            date = "2010-12-19T05:27:20-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25672#comments:id=1244955",
        },
    },
    [25673] = {
        {
            id = 1201057,
            score = 98,
            author = "525646",
            text = "Mechanized Air in hut at 59.9, 64.2\nMechanized Fire at 63.1, 56.7 on top of Harvester.\nMechanized Ice on top of tower at 66.1, 50.0\nHelmet (BD-816 War Apparatus) 63.0, 45.7 on platform on West side of Water Wheel, North side of Cragpool lake (climb path up hill on east side of lake).",
            date = "2010-12-01T21:10:47-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25673#comments:id=1201057",
        },
        {
