            score = 18,
            author = "356696",
            text = "An obvious reference to Bioshock.  Alice being a Little Sister, and Big Papa being a Big Daddy.",
            date = "2010-08-08T04:21:27-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25673#comments:id=1097027",
        },
