            score = 11,
            author = "251660",
            text = "Take note, the helm is on the platform above; not underwater.\n\nYou'll see that there is a path to the right of the platform to the mountains, that's the way. On the way, a gnome will communicate with you; don't forget to take that quest.\n(Assuming you did the gnomerecorder chain)",
            date = "2010-11-25T09:54:25-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25673#comments:id=1184426",
