    [25674] = {
        {
            id = 1534005,
            score = 12,
            author = "170326",
            text = "This \"old orc city\" that he mentions is most probably Rockard, the twin city of nearby Stonard, which together were two of the first orc settlements in Azeroth that were established after they came through the Dark Portal from Draenor.",
            date = "2011-10-03T13:40:38-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25674#comments:id=1534005",
        },
        {
            id = 1389488,
            score = 9,
            author = "FeyGyrl",
            text = "Make sure you go right outside the gate - still technically within Dreadmaul Hold, but far enough out that the Okril'lon defenders don't come & help you kill your ambusher, or you won't get the credit for the kill. I killed about half a dozen within the gates, with no credit for it, because they kept defending me too well. LOL",
            date = "2011-04-12T00:37:21-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25674#comments:id=1389488",
        },
        {
            id = 1893611,
            score = -3,
            author = "Bumpitup11",
            text = "Tough quest.",
            date = "2013-09-07T16:35:08-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25674#comments:id=1893611",
        },
    },
    [25675] = {
        {
            id = 1414367,
            score = 14,
            author = "3209",
            text = "There are no follow-ups to this quest, so you may continue doing A Bloodmage's Gotta Eat Too &\nThe First Step without worrying about other quests to do together with these.",
            date = "2011-05-09T23:05:26-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25675#comments:id=1414367",
        },
        {
            id = 2013079,
            score = 5,
            author = "1304315",
            text = "It is the night after the 6.0.2 patch, I'm doing the pre-WoD release Blasted Lands Invasion event, and one task is to retrieve Master Aitokk's axe from Nethergard Keep (which is currently in Iron Horde hands). The toon I am running never did Blasted Lands quests. Master Aitokk's corpse (not obvious at the time that he was dead, not dying) offered the https://www.wowhead.com/quest=25675. Near as I can tell, the target mobs are gone and the quest can no longer be done, and commensurate with the low level of the quest, AWOL mobs, and rewards, this was not intended to be a part of the Blasted Lands Invasion event. Blizzard forgot to turn him off when he died.",
            date = "2014-10-15T01:52:37-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25675#comments:id=2013079",
        },
        {
            id = 1262178,
            score = 2,
            author = "Grim32",
            text = "Fairly easy quest though this is my second character to do this quest & there seems to be a noticeable lack of Dreadmaul Maulers.",
            date = "2010-12-27T15:03:29-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25675#comments:id=1262178",
        },
        {
            id = 1979255,
            score = 2,
            author = "Nenthil",
            text = "You need to complete https://www.wowhead.com/quest=25674 to unlock it.",
            date = "2014-07-09T20:37:57-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25675#comments:id=1979255",
        },
        {
            id = 1920036,
            score = 1,
            author = "919169",
            text = "in this  Q i the longest I waited to respawn Mauler",
            date = "2013-11-21T03:10:03-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25675#comments:id=1920036",
        },
    },
    [25676] = {
        {
            id = 2333637,
            score = 77,
            author = "Jbishhh",
            text = "After Hours of frustration reloading, relogging, disabling addons etc...etc.. I found out 2 things.\n\n1. To do the old quests for loremaster you have to talk to Zidormi at the zone entrance to swamp od sorrows.\n\n2. If you leave the zone for any reason, you have to go back and talk to Zidormi AGAIN or you wont be able to do your quests.\n\nI had flown out of the zone looking for Rofilian Dane before I realized he was in the mine. This reset Blasted lands to the pre-cata phase.",
            date = "2016-05-23T23:59:50-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25676#comments:id=2333637",
        },
        {
            id = 1193959,
            score = 15,
            author = "89046",
            text = "Entrance to the mines is at 50.10 and Dane is at 60.3 on the tracks.  It's the same layout as the Netherwing mine.  Pretty easy to maneuver around in",
            date = "2010-11-28T16:47:14-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25676#comments:id=1193959",
        },
        {
            id = 1208977,
            score = 7,
            author = "362539",
            text = "Directions to the mine:\n\nRide east and then north on the road which heads to the Swamp of Sorrows.  It's about 50ft to your right 1/2 way up this path.\n\nIt's also the most northern cave entrance in the zone.",
            date = "2010-12-05T19:11:28-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25676#comments:id=1208977",
        },
        {
            id = 1405409,
            score = 4,
            author = "Grans",
            text = "2 simple follow-up quests:\n\nPick Your Fate (quest=25678)\nIt's All Mine (quest=25677)\n\nWhich leads to chain:\n\nInto the Mountain (quest=25679)",
            date = "2011-04-30T18:52:24-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25676#comments:id=1405409",
        },
        {
            id = 5555482,
            score = 2,
            author = "JetGaren",
            text = "Get into the mine and find Rofilian Dane.\n/way 54.18 13.11 Mine Entrance\n/way 59.6 3.4 Rofilian Dane",
            date = "2023-02-26T06:31:01-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25676#comments:id=5555482",
        },
    },
    [25677] = {
        {
            id = 3284020,
            score = 48,
            author = "Britomart",
            text = "Strangely long spawn rate remains.  Also seems like relatively few spawn to begin with.  I'm alone in the mine and it's still taking me 15+ minutes to get just 6 needed for the quest.",
