    [25679] = {
        {
            id = 1267590,
            score = 16,
            author = "496669",
            text = "I believe you must complete the quest Futile Pride for Okrilla at Dreadmaul Hold in Blasted Lands.  After that, Okrilla should send you on the quest to talk to Roflian Dane, called Heartstrike.  That is the end of a 5-part chain starting with the quest With Dying Breath.",
            date = "2010-12-30T08:39:01-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25679#comments:id=1267590",
        },
        {
            id = 1775894,
            score = 1,
            author = "885261",
            text = "The first four quests of this chain take place in Nethergarde Mines, which is a great setting; looks really awesome. The only problem is that you cannot use mounts in there, even though the mine is actually a huge cave. So there will be a lot of running around, but it is still fun.",
            date = "2012-12-05T05:53:17-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25679#comments:id=1775894",
        },
    },
    [25680] = {
        {
            id = 1198216,
            score = 40,
            author = "35048",
            text = "Head to the right. Illycor is in the end.",
            date = "2010-11-30T15:34:49-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25680#comments:id=1198216",
        },
        {
            id = 1179103,
            score = 19,
            author = "491283",
            text = "This quest is much easier if you don't go in swinging your axe wildly. The Terrified Nethergarde Miners do not aggro unless attacked. The Reassuring Foremen do, however. You can actually sneak past them all if you hug the right wall all the way to the beholder.",
            date = "2010-11-23T20:15:36-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25680#comments:id=1179103",
        },
        {
            id = 1221630,
            score = 6,
            author = "717492",
            text = "Illycor is on a two minute spawn timer. I got there literally as a shammy was running out. So don't despair if you're worried that you'll have a long wait; he's nice and fast.",
            date = "2010-12-10T11:19:43-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25680#comments:id=1221630",
        },
        {
            id = 1616284,
            score = 5,
            author = "939432",
            text = "Wtf! how did he come in...",
            date = "2012-01-24T12:08:47-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25680#comments:id=1616284",
        },
        {
            id = 2551586,
            score = 4,
            author = "Aerynsun8449",
            text = "Of all the years I've been doing these quests, many of them do not make sense in an immersion type of thing. I mean, IF we were actually the characters and we're asked to go into the mine and kill whatever has the miners frightened. I understand the miners are hostile to us before. But, you'd think, even if they're not singing our praises and doling out money for saving them, they'd NOT try to kill us as we are leaving the monster we just killed to save them.\n\nThen again, I'm wondering why, since the miners are Alliance and we're Horde, why did we care to go into the mine and kill the thing that had them too frightened to mine the ore they use to kill us. I mean, neither aspect makes any sense for the characters to do. As Horse, we would want the monster to keep frightening them and killing them so they can't mine the ore. As Alliance miners they should show a modicum of gratitude that we saved them from the monster. Maybe not so grateful as to invite us home to diner and meet the misses. But grateful enough, at least for that day, that hour, not to try to kill us. Especially right after we saved them.",
            date = "2018-02-09T00:07:30-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25680#comments:id=2551586",
        },
    },
