    [25688] = {
        {
            id = 1245427,
            score = 71,
            author = "580934",
            text = "Ignore the rest of these comments. They're confusing a simple issue. Lets assume you've just left the cave of the quest giver. Turn right and run a short distance. You'll see a wide path leading up guarded by pairs of enemies. Kill them as you ascend.\n\nKill all the mobs at the top, then mount the altar and right click on it. Then get off the altar and start circling it. Kill each mob as it appears. Im a mage and I two-shotted all of them. Easy kills.\n\nIf you remain on the altar it is too difficult to get line of sight as they keep moving.\n\nI lost Loramus once, then started circling the altar and it was very easy",
            date = "2010-12-19T10:41:36-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25688#comments:id=1245427",
        },
        {
            id = 2526033,
            score = 21,
            author = "Tilra",
            text = "If you do this as a Demon Hunter you can see what he is saying in demonic.\nParn rakir is \"Holy Moley\"\nand Zila il amanalar is \"This is horrible\"",
            date = "2017-09-25T15:53:21-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25688#comments:id=2526033",
        },
        {
            id = 1330607,
            score = 7,
            author = "285271",
            text = "Alter is on the spine in the middle. If you have your camera at just the wrong angle (like I did)  the alter will look like just another bone in the spine. When you get about half way up rotate the camera to the side and the alter is easy to see.",
            date = "2011-02-10T15:01:32-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25688#comments:id=1330607",
        },
        {
            id = 2368392,
            score = 7,
            author = "Magus2002",
            text = "This quest is indeed, as of now, before Legion launches, bugged and uncompletable, due to Dalaran-over-Karazhan being present and dragging players into a different phase.. as you look up you can see it.",
            date = "2016-08-15T17:24:11-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25688#comments:id=2368392",
        },
        {
            id = 1402434,
            score = 5,
            author = "617575",
            text = "Go around the mountain and up the hill. The altar is in the middle of the rib cage. There's a small stone bench that is clickable. Click it, then run around the outside of the rib cage killing everything. I put my voidwalker on aggro and let him take care of everything.\n\nIf you fail, wait a minute and then the stone bench will be clickable again. After he's resurrected, he'll leave and head back to the cave. You don't have to escort him or anything.",
            date = "2011-04-28T04:32:02-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25688#comments:id=1402434",
        },
    },
