    [25699] = {
        {
            id = 1179387,
            score = 13,
            author = "181947",
            text = "Undead worgen roam the Shattershore.\n\nThere are 3 shipwrecks here, the quest objective is in the middle ship, which sits further back from the shore.\n\nSwim through a window, and at the bow is a skull pile with Grol's head on a pike. When you take the broken amulet from the head, the spirit of Grol appears behind you. Kill him, and loot the intact amulet.",
            date = "2010-11-23T22:02:40-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25699#comments:id=1179387",
        },
        {
            id = 1990514,
            score = 11,
            author = "1059507",
            text = "How to \"find\" Loramus so you can get the https://www.wowhead.com/quest=25699 quest.....\n\nFirst you must complete a series of quests that starts with https://www.wowhead.com/quest=25674 at Dreadmaul Hold. This leads you through a longer chain starting with https://www.wowhead.com/quest=25679 with following quests from https://www.wowhead.com/npc=7506 and https://www.wowhead.com/npc=7505. Then Loramus will be in the cave with the Bloodmage duo. After completing several quests from https://www.wowhead.com/npc=41159 at Loramus' request, Loramus will offer the 3 amulet quests.",
            date = "2014-08-11T04:31:40-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25699#comments:id=1990514",
        },
        {
            id = 1859148,
            score = 4,
            author = "wrakky",
            text = "If you can activate the skull pile but nothing happens, check you don't have https://www.wowhead.com/item=56007 in your bag already.\n\nI looted the skull but someone else tapped the spirit so I had to wait and try again. Attempting to loot the skull pile again to summon the spirit appeared to activate it but nothing else happened until I removed the broken amulet from my bag.",
            date = "2013-05-28T09:27:43-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25699#comments:id=1859148",
        },
        {
            id = 1960472,
            score = 4,
            author = "Dovzhenko",
            text = "To unlock this quest you must complete https://www.wowhead.com/npc=41159's 3 quests around the Dark Portal. https://www.wowhead.com/quest=25692, https://www.wowhead.com/quest=25691 and https://www.wowhead.com/quest=25693",
            date = "2014-04-22T19:30:26-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25699#comments:id=1960472",
        },
        {
            id = 3148529,
            score = 4,
            author = "Reanimate",
            text = "Still broken as of 8/19/2019. My character just says \"I can't loot that right now.\"\nI guess this quest is never getting fixed.\n\nEDIT: I abandoned the quest, did some other quests, and came back to it, and it looted the pile of bones. So the quest works, but is still bugged.",
            date = "2019-08-19T15:54:37-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25699#comments:id=3148529",
        },
    },
    [25700] = {
        {
            id = 1625232,
            score = 4,
