            author = "bwappo",
            text = "This quest requires a series that starts with Futile Pride (http://www.wowhead.com/quest=25674), takes you through a longer chain that begins with Into the Mountain (http://www.wowhead.com/quest=25679), has you do a couple of quests for Watcher Wazzik (http://www.wowhead.com/npc=41159), then returns you to Loramus Thalipedes (http://www.wowhead.com/npc=7783) to do this quest.",
            date = "2012-05-28T11:47:08-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25700#comments:id=1671104",
