    },
    [25701] = {
        {
            id = 1178973,
            score = 63,
            author = "707120",
            text = "You have to talk to the Ghost at the bottom, north side of the hill.. Deathy Usher. He will port you up to face Razelikh. Remember to use the knife you get to finish of Loramus when he gets Corrupted.",
            date = "2010-11-23T19:21:54-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25701#comments:id=1178973",
        },
        {
            id = 1347277,
            score = 57,
            author = "769627",
            text = "If you're high lvl like me (85 lock) when doing this q, make sure you don't nuke Rakh'likh down too fast.\n\nI didn't get credit for the kill, altough I got credit for the soul imprisonment and had to start over again.\n\nTook me 2 more tries before I figured I just kill him slow with my sword. The fight was also a lot more fun that way because Rakh'likh's ability will blast you off the cliff. Fortunately Loramus is looking after you and death grip's you back on him while flying in midair. Wee...\n\nJust use your weakest dmg ability when high lvl or just have fun doing this fight twice. :D",
            date = "2011-02-23T13:46:04-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25701#comments:id=1347277",
        },
        {
            id = 1186263,
            score = 26,
            author = "tarax",
            text = "Deathy Usher is located at 46,21",
            date = "2010-11-25T23:36:14-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25701#comments:id=1186263",
        },
        {
            id = 1858674,
            score = 23,
            author = "Taishigi",
            text = "When Loramus is beaten in his demon form he yells \"[Demonic]: The pain! Oh, sweet sassy molassey, the pain!\"\nHad to be in Dark Apotheosis form to see it.",
            date = "2013-05-27T08:39:30-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25701#comments:id=1858674",
        },
        {
            id = 1179432,
            score = 14,
            author = "181947",
            text = "This is the updated quest, from the old-world version.\n\nSpeak to the deathly usher to be ported to the top of the mesa.\n\nLoramus Thalipedes joins you, and summons the demon.\n\nRazelikh is a level 57 elite. After dialogue, he becomes attackable. Loramus helps you in the fight.\n\nDuring the battle, the demon possesses Loramus, and you have to fight him.\n\nWhen his health is low, he says \"Quickly! Use the knife on me! Time runs short!\" Then you use the Stone knife of Stealing on him.\n\nEdit: Return to the goblin at the Dark Portal to turn in the quest.",
            date = "2010-11-23T22:23:28-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25701#comments:id=1179432",
        },
    },
