    [25706] = {
        {
            id = 1312455,
            score = 23,
            author = "92763",
            text = "I found it disappointing that although you go in and kill some of the naga, nothing changes.  The murloc march and slave-fighting pits remain in place, unaffected by your actions.  It's anti-climactic and a little depressing.",
            date = "2011-01-27T20:18:23-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25706#comments:id=1312455",
        },
        {
            id = 1192286,
            score = 14,
            author = "wlrob312",
            text = "I'm as far from being an RPer as the next guy but did anyone get a kick out of enacting revenge on the naga for putting the murloc tribe into that \"trail of tears\" march?",
            date = "2010-11-28T03:46:36-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25706#comments:id=1192286",
        },
        {
