    [25707] = {
        {
            id = 1196975,
            score = 118,
            author = "220156",
            text = "Nobody has mentioned that this is in fact a really touching quest!\n\nWatching the baby murlocs float out into the Forbidding Sea, those little tadpoles the only chance of a future for the Rockpool Murlocs, really balances out the zone-wide killing spree all the other quest givers have been sending you on ^-^",
            date = "2010-11-30T02:12:19-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25707#comments:id=1196975",
        },
        {
            id = 1182411,
            score = 76,
            author = "aelox",
            text = "Maybe it's one of those grass is greener type things since we have available quests displayed on the minimap...\n\n..but I was really excited to 'discover' a quest again by interacting with the world and not just beelining towards an exclamation point on the map.",
            date = "2010-11-24T17:18:16-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25707#comments:id=1182411",
        },
        {
            id = 1188870,
            score = 60,
            author = "Inexorability",
            text = "So you have to either drag them out to sea or leave them to their fate? I'd like to adopt them, please.",
            date = "2010-11-26T21:10:30-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25707#comments:id=1188870",
        },
        {
            id = 1255676,
            score = 49,
            author = "743613",
            text = "Just in case this helps anyone: I took this quest from a crate right at the cave entrance and was unable to drag it anywhere.  Only one rope was connecting me to it and the rope would elongate until I was out of range with the crate going nowhere.  I was about to give up when I found another crate in the hills to the right as you face the cave entrance.  That one worked fine.\n\nIt looks like people took the quest then tried to go into the cave, and the chests bugged out.  Don't be fooled, use the one in the hills!",
            date = "2010-12-23T22:22:13-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25707#comments:id=1255676",
        },
        {
            id = 1318027,
            score = 27,
            author = "dermadark",
            text = "Amazing quest.../salute to little murlocks!",
            date = "2011-02-01T09:13:43-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25707#comments:id=1318027",
        },
    },
    [25708] = {
        {
            id = 1973998,
            score = 4,
            author = "1268444",
            text = "This quest has brought me some kind of sadness while doing it. Especially the fact that the spirits of those people were bowing to me and rising up in the sky when I killed them. Good job, Blizzard.",
            date = "2014-06-21T15:50:52-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25708#comments:id=1973998",
        },
        {
            id = 2616812,
            score = 2,
            author = "Ellsi",
            text = "I did this quest as a higher level character.  I discovered if you speak to the NPC at 48.2 / 7.3 and ask to see the zone before the invasion, and then log out, the area reverts to the newer version next time you log in.  You will need to speak to the NPC each time you log in to the zone to see the correct version to complete the quest. At least, that is what happened to me.",
            date = "2018-09-19T13:29:28-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25708#comments:id=2616812",
        },
        {
            id = 1296949,
