            date = "2011-01-16T21:04:03-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25708#comments:id=1296949",
        },
    },
    [25709] = {
        {
            id = 1095440,
            score = 52,
            author = "Vlad",
            text = "Use this macro and spam it while on the beach, it helps target and shoot them down for you:\n#showtooltip\n/use item:57119\n/tar Darktail Bonepicker\n/cleartarget [dead]\nRevision 2 of the macro.",
            date = "2010-08-04T09:11:17-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25709#comments:id=1095440",
        },
        {
            id = 1196727,
            score = 24,
            author = "220156",
            text = "Oh god. They're in the sky. Not on land. Don't ask me how long i was looking for them because I will never tell you it took 10 minutes.",
            date = "2010-11-29T23:23:52-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25709#comments:id=1196727",
        },
        {
            id = 1225037,
            score = 20,
            author = "541207",
            text = "These arrows used to work EVERYWHERE and you could use them on ANYTHING!  The arrows have since been modified to work only in the Blasted Lands and apparently only on the birds.  These were great \"arrows\"!  They had super long range, didn't even need line-of-sight and did NO damage but make the mobs mad.  Imagine you're in Heroic Halls of Lightning, you just killed the first boss and you shoot Volkhan (the blacksmith boss) with the arrows.  Yes the \"arrows\" did reach that far!  He gets mad and comes to the first boss's room bringing a TON of the adds with him!  The Leeroy Jenkins party lasted longer than your party lasts against this onslaught!  I soooo miss those \"arrows\"...",
            date = "2010-12-11T15:08:47-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25709#comments:id=1225037",
        },
        {
            id = 1386584,
            score = 16,
            author = "Impact009",
            text = "The arrows sometimes miss.",
            date = "2011-04-07T23:19:21-05:00",
