    [25710] = {
        {
            id = 1315904,
            score = 25,
            author = "0123456",
            text = "Facing the 'Keep' when coming up the front road entrance past the supply camps. On your left, behind the spikey fencing is the large, spear-chucking machine. Near there is the hidden Scouts. Don't worry... they'll find you.",
            date = "2011-01-30T14:29:08-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25710#comments:id=1315904",
        },
        {
            id = 3196911,
            score = 15,
            author = "Prodigalwow",
            text = "So I'm trying for Loremaster achievement and returned to blasted lands to complete the required quests.\n\nThis thread needs an update for 2020 in case players, like me, just forget time and time again that any ! or ? in the zone might in fact be where the NPC is but....in a previous version of the zones history which means there is always a chat bubble somewhere which is the NPC you go to in order to travel back in time where amazingly the quests will actually be where the ! and ? say they are located.",
            date = "2020-03-30T00:34:11-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25710#comments:id=3196911",
        },
        {
            id = 1179603,
            score = 5,
            author = "664880",
            text = "Forget the one on the road that the infantry are fighting. There are two, both hidden, up the hill near the large ballistas.",
            date = "2010-11-23T23:34:15-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25710#comments:id=1179603",
        },
