    [25711] = {
        {
            id = 1179627,
            score = 3,
            author = "664880",
            text = "Do this with Nethergarde Reigns (http://www.wowhead.com/quest=25712) and Remove Their Arms (http://www.wowhead.com/quest=25713).\n\nGo kill 9 of the Okril'lon Infantry in the camp west of Nethergarde Keep. Fight the ones that the friendly infantry are fighting; you should get credit. The grenades for Remove Their Arms (http://www.wowhead.com/quest=25713), nor did the blast from the exploding weapon crates.",
            date = "2010-11-23T23:45:53-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25711#comments:id=1179627",
        },
    },
    [25712] = {
        {
            id = 1179632,
            score = 13,
            author = "664880",
            text = "Captain Metlek patrols along the road a bit further west of the main Okril'lon camp. I found him up on a hill. He has a large Horde banner and rides a wolf.",
            date = "2010-11-23T23:50:43-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25712#comments:id=1179632",
        },
        {
            id = 1483605,
            score = 4,
            author = "FuryWar",
            text = "I found Metlek riding his wolf up and down the side of the hill at about 51.14.",
            date = "2011-07-30T23:24:42-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25712#comments:id=1483605",
        },
    },
    [25713] = {
        {
            id = 1285768,
            score = 5,
            author = "273749",
            text = "There are a few places where the grenades won't work.  Move somewhere else and try another crate if this happens.",
            date = "2011-01-09T12:22:17-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25713#comments:id=1285768",
        },
        {
            id = 1179629,
            score = 4,
            author = "664880",
            text = "Do this with Nethergarde Reigns (http://www.wowhead.com/quest=25712) and Eliminate the Okril'lon (http://www.wowhead.com/quest=25711). You get them all from the guestgivers in the keep.\n\nVery easy, just lob a grenade at any sparkling crate in the Okril'lon camp just west of Nethergarde Keep. Works like any AoE. Note that there is a minimum range, you can't just drop it on a crate you are standing next to.",
            date = "2010-11-23T23:48:52-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25713#comments:id=1179629",
        },
        {
            id = 1193858,
            score = 3,
            author = "Sargeant",
            text = "You can keep the grenades from the quest if you dont complete the quest. They are usable everywhere.",
            date = "2010-11-28T16:06:19-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25713#comments:id=1193858",
        },
        {
            id = 1483610,
            score = 3,
            author = "FuryWar",
            text = "Doing this quest just now, I couldn't figure out why it wouldn't et me throw my grenades at the crates, then, when I aimed at another crate that was a bit further away, it finally worked.  So, looks like you can only toss the grenades if the crates are at least a certain distance from you.  To see what your range is with your grenade, just click it and move your cursor away from you.  When you see the green circle, you're good to throw.  Once you learn the range, it's pretty easy to go to each crate and blast them apart!",
            date = "2011-07-30T23:34:36-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25713#comments:id=1483610",
        },
        {
            id = 1947199,
            score = 1,
            author = "lannisteryn0",
            text = "Blowing those crates aren't that tricky.You just gotta click it right hand side then hover over the crate until it's greenish circle thingy:)lol then left click it.Hope that helps.",
            date = "2014-02-27T11:29:59-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25713#comments:id=1947199",
        },
    },
