    [25719] = {
        {
            id = 1179532,
            score = 44,
            author = "181947",
            text = "Need 20 crushed Nightstalker Legs. Spiders drop Nightstalker Legs. Zero-four legs per kill. Crush the legs into 1 powder per leg.\n\nNeed 2 Screecher Brains. Bats drop 0-1 brain per kill. Mash the brain into a paste.\n\nNeed 4 Tainted Hides. Bears drop the hides. 0-1 per kill.\n\nMix the crushed spider legs and bat brain paste together, and sew the bear hides into a pouch (no thread required). Then combine the mixture and pouch to complete your demoniac vessel.\n\n(For clarification, all you have to do is right-click the items in your bag)",
            date = "2010-11-23T23:02:11-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25719#comments:id=1179532",
        },
        {
            id = 1377940,
            score = 29,
            author = "chibee",
            text = "This quest basically says:\n\n\"Hey, remember classic WoW? Me too! Have fun in Outland!\"",
