            author = "520718",
            text = "The part of this quest that took longest for me was when Deathwing decided to drop by and scorch the whole field.\n\nOn the bright side, I did get Stood in the Fire. :)",
            date = "2011-05-01T20:28:33-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25719#comments:id=1406678",
        },
        {
