            date = "2010-12-06T22:08:01-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25719#comments:id=1210877",
        },
        {
            id = 1850515,
            score = 5,
            author = "IvikN",
            text = "One problem with this quest.\nWhen you gather every item u need for it. If you joining together those items before gather ll that u need. and IF you will get one-two above needed items. AND IF you will destroy any of not needed items from your inventory - this will automatically abandon the quest. I lost freaking hour of my life to gather all loot. But since I was joining them together right after I got it. I'v got brain from bats that i couldn't use. Right click on it was telling me that you have already many of this item in ur bag. And when I delete it - quests just freaking abandon itself. But this Demonic Vessel as complete quest item is still in my bag. I wonder what happens if I will retake it... will it disappear?",
            date = "2013-05-06T06:59:43-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25719#comments:id=1850515",
        },
    },
    [25720] = {
        {
            id = 6240275,
            score = 11,
            author = "Vive",
            text = "If you're looking to pick up the decor item, I was able to pick up The Demons and The Druid quest and finish the last bit of this chain, having not previously done any blasted lands quests at all.",
