        {
            id = 1372199,
            score = 10,
            author = "312232",
            text = "I don't like co-ordinates because my pc is laggy enough without add ons.\n\nSo for those like me -  just past the bridge at the bottom of Ironforge turn north the trail up to the frostmane village can be found from there.",
            date = "2011-03-20T23:51:05-05:00",
