        },
        {
            id = 1646718,
            score = 4,
            author = "Khayos",
            text = "It use to be at (45,39) approximately before the cataclysm. I just found this out that it was changed since I haven't leveled a gnome since before Cataclysm. So..definitely not where the entrance to the hill used to be. Go to (52, 40)!",
            date = "2012-03-30T17:26:08-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25724#comments:id=1646718",
        },
        {
            id = 2573474,
            score = 3,
            author = "Gymlea",
            text = "From the Quest Giver in Kharanos, go due north up the road and over the bridge. You will immediately come to the road from the entrance to Ironforge. There is a signpost. If you continueturn left, behind the signpost, there is a snow-covered, slope-up, with torches, to the Frostmane village where the Seers, and Snowstriders are. The Seers also drop Shimmerweed (https://www.wowhead.com/item=2676) needed for the Perfect Stout (https://www.wowhead.com/quest=315) quest. In addition Shimmerweed can be found in Shimmerweed Baskets (https://www.wowhead.com/object=276) which are all over the village.",
            date = "2018-06-11T08:01:07-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25724#comments:id=2573474",
        },
    },
    [25725] = {
