    [25726] = {
        {
            id = 1185633,
            score = 30,
            author = "Darillion",
            text = "You need to kill Silty Oozelings (http://www.wowhead.com/npc=41145) Until the Dumpy Level (http://www.wowhead.com/item=55234) drops.\nThe drop rate is rather low.",
            date = "2010-11-25T18:17:10-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25726#comments:id=1185633",
        },
        {
            id = 1473663,
            score = 26,
            author = "362863",
            text = "To be fair, I looked it up as well.\n\nWell of course!  It says right in the quest instructions, \"Go look it up!\"  Anyone who didn't, failed to follow the instructions.  ;)\n\nThat said, he lies.  Not about the name, but he said one of the oozes took it.  I killed all of them, and none of them had it.  I eventually abandoned the quest.  I suspect he pawned it off to buy ale and doesn't want to admit it...",
            date = "2011-07-18T21:11:54-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25726#comments:id=1473663",
        },
        {
            id = 1451451,
            score = 22,
            author = "19742",
            text = "Well, I guess I shouldn't mention that I got it on the first try...\n\nAnd, btw, it really is called that: Wikipedia: Dumpy Level (http://en.wikipedia.org/wiki/Dumpy_level)",
            date = "2011-06-26T20:51:53-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25726#comments:id=1451451",
        },
        {
            id = 1187468,
            score = 12,
            author = "Terbovus",
            text = "I actually did look it up, as he suggested, and they do exist. You learn something every day!",
            date = "2010-11-26T11:16:37-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25726#comments:id=1187468",
        },
        {
            id = 1316062,
            score = 3,
            author = "ziggy29",
            text = "Very frustrating quest to say the least based on how low the drop rate is on these things.  I killed over 20 of them and got nothing - I did manage to get the 15 fenberries I needed on another quest because this one is taking so long that I can keep going back to the same bushes I picked a few minutes earlier, so it's not all bad.",
            date = "2011-01-30T16:57:50-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25726#comments:id=1316062",
        },
    },
