    [25728] = {
        {
            id = 1203908,
            score = 52,
            author = "Ashtranza",
            text = "Have some ice cream.",
            date = "2010-12-03T10:15:32-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25728#comments:id=1203908",
        },
        {
            id = 1098968,
            score = 45,
            author = "Linty",
            text = "After helping the mildly disturbed girl known as a little sister Alice repair her giant diving mask protector known as  the Big Daddy Mr. P. You help her fight fight splicers Goblins armed with their powerful plasmids shredders. ultimately you are rewarded with ADAM Ice Cream.\n\nedit: crossed out and replaced incorrect information",
            date = "2010-08-11T01:40:30-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25728#comments:id=1098968",
        },
        {
            id = 1184911,
            score = 28,
            author = "462295",
            text = "Alice whispers: Break their bones, papa!\nAlice whispers: Make 'em sorry for hurting you, Mr. P!\nAlice whispers: Get 'em, Mr. P!\nAlice whispers: BAD, BAD, HORDIE!\n\nThis quest is so funny. :)",
            date = "2010-11-25T13:13:08-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25728#comments:id=1184911",
        },
        {
            id = 1182446,
            score = 23,
            author = "Architekt",
            text = "This quest is a reference to the game Bioshock. \"Big Papa\" refers to the \"Big Daddy\", and the man standing next to her, \"Anderov Ryon\", is a reference to the main bad (or good) guy, Andrew Ryan. Alice says permutations on quotes from the game, such as \"Wake up, Mr. P!\".\n\nYou can mash both the fire and ice skills as fast as their cooldowns allow, both can be deployed simultaneously. If you use the grabber skill, make sure to press it again to release/chuck the goblins to kill them (you can't use other skills until you do so).",
            date = "2010-11-24T17:30:24-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25728#comments:id=1182446",
        },
        {
            id = 1333719,
            score = 13,
            author = "Sleepichick",
            text = "I absolutley loved this quest, I havent played Bioshock so I dont really get the reference but the little girls enthusiasm for killing the horde really cheered up my night.\n\nI found that she stayed with me after I was done which was both disturbing and awesome. I cant wait to see how long she sticks around.",
            date = "2011-02-12T19:41:25-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25728#comments:id=1333719",
        },
    },
    [25729] = {
