        {
            id = 1184431,
            score = 12,
            author = "708409",
            text = "You \"discover\" this quest by having the \"Gnomecorder (http://www.wowhead.com/quest=25621)\" equipped and venturing near the Cragpool Lake water wheel.",
            date = "2010-11-25T09:55:15-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25729#comments:id=1184431",
        },
        {
            id = 1709878,
            score = 6,
            author = "808808",
            text = "For those low level toons that do not fly here is how you do it.\n\nAre Cragpool lake, this is the narrow point (68.2,46.5) you will see wooden fence on the lefthand side, that's the trail that will take you to the top. You will have some wooden beams to walk on.\n\nAt 65.8, 44.0 you will turn to the right and the water wheel is a short distance.",
            date = "2012-09-05T18:13:16-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25729#comments:id=1709878",
        },
        {
            id = 1485844,
            score = 4,
            author = "bradgamer",
            text = "How do you get the gnomecorder if you have already completed the other quests?\n\nUPDATE:  It looks like it is something you \"always have,\" rather than something that is in your bags.  It turns out I had done the quest already a long time ago.  The gnomecorder came on when I finished the quest to kill the guy at the top of this area.\n\n(I am working on Loremaster.)",
            date = "2011-08-02T18:25:53-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25729#comments:id=1485844",
        },
    },
