    [25756] = {
        {
            id = 1186192,
            score = 7,
            author = "629371",
            text = "Located near Splithoof Heights; he is in the tent at 90.74, 53.28.\n\nLevel 41 non-elite, becomes stunned at 139/3170 health, allowing you to steal the proposal.\n\nThe Ancient Brazier (http://www.wowhead.com/quest=25762) is also available nearby.",
            date = "2010-11-25T23:06:18-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25756#comments:id=1186192",
        },
        {
            id = 1715177,
            score = -2,
            author = "892367",
            text = "Currently bugged, for me at least.... I've done this quest multiple times on other toons without issue. But, for whatever reason, today Zherin won't spawn. Tried abandoning and reaccepting quest. Tried logging out and back in. Left Thousand Needles and came back... nothing. I'm not going for Loremaster on this toon, so I'll skip it... was just hoping for some easy exp.",
            date = "2012-09-17T17:11:29-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25756#comments:id=1715177",
        },
    },
    [25757] = {
        {
            id = 1206215,
            score = 7,
            author = "Warrok",
            text = "Would have been 100x more awesome if they gave Koalbeard the first name Stephen.",
            date = "2010-12-04T13:52:21-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25757#comments:id=1206215",
        },
        {
