    [25762] = {
        {
            id = 1094232,
            score = 307,
            author = "196277",
            text = "It's definitely a trick to find, and the yellow dot that's placed on the world map for this quest only shows the entrance to the cave, not the location of the brazier itself.  When you enter the cave, the passage curves left into a room with three exits.  Take the left one and follow it around to the big room.  This room contains the brazier where you use the quest torch.",
            date = "2010-08-02T14:26:49-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25762#comments:id=1094232",
        },
        {
            id = 1186312,
            score = 106,
            author = "629371",
            text = "The brazier's co-ordinates are 41.97, 31.65\n\nEntrance to the cave is at 43.98, 37.43",
            date = "2010-11-26T00:03:34-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25762#comments:id=1186312",
        },
        {
            id = 1204974,
            score = 35,
            author = "ecksit1",
            text = "The brazier is in the underwater cave, just go to the end of the cave and you should see it. Coords for the cave's entrance are 43.9 37.6",
            date = "2010-12-03T21:04:28-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25762#comments:id=1204974",
        },
        {
            id = 1207651,
            score = 34,
            author = "EchoOff",
            text = "Appears to be plenty of Needles Pyrite Ore in the cave too, so this is a good place to take care of the quest Fool's Gold (http://www.wowhead.com/quest=25774) at the same time.  As waytofailself remarked above, there are also several actual gold nodes in the cavern.  I mined three while I was in there.",
            date = "2010-12-05T06:41:51-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25762#comments:id=1207651",
        },
        {
            id = 2418133,
            score = 27,
            author = "Chrispine",
            text = "the entrance to the underwater cave is at coords 44.13 36.97.\n\nEnter the cave, turn left and keep following the wall.\nLight the brazier, kill Aquarian (http://www.wowhead.com/npc=41236/aquarian), get the sacred flame (http://www.wowhead.com/item=55979/the-sacred-flame) and your done.",
            date = "2016-09-30T07:03:34-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25762#comments:id=2418133",
        },
    },
    [25765] = {
