    [25766] = {
        {
            id = 1119479,
            score = 108,
            author = "Norolas",
            text = "Throw the device at the Highborne mobs in the Ruins of Eldre'thar and sometimes you get an angry spirit attack you and sometimes you'll get a bound spirit (they look like wisps). I had a real streak of bad luck when I did this quest and the first 10 minutes all I got was angry aggro spirits, but eventually I got the bound spirits. My advice is to keep trying if all you're getting is angry spirits.",
            date = "2010-09-12T18:31:08-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25766#comments:id=1119479",
        },
        {
            id = 1193887,
            score = 19,
            author = "SubjectV",
            text = "Before killing groups with named Highborn, stay back and listen to their \"roleplaying\". If you're a lore nerd, are interested in quests, or have enjoyed past Warcraft books, you'll enjoy some of the scenes the named mobs in this fallen city act out. Once they're done talking, they're fair game! :)",
            date = "2010-11-28T16:19:56-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25766#comments:id=1193887",
        },
        {
