        {
            id = 1442195,
            score = 8,
            author = "Apolocyntosis",
            text = "I discovered that if i attacked the enemy a little bit before i threw it at them, I had around an 80% of getting a bound spirit, as opposed to the...well..0% i was getting throwing it at ones i didn't attack. This may have been just dumb luck, but it wouldn't hurt to whack the enemy once or twice before throwing it, just, you know, in case....",
            date = "2011-06-15T16:05:52-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25766#comments:id=1442195",
        },
    },
