    [25770] = {
        {
            id = 1287798,
            score = 19,
            author = "Irayna",
            text = "This is a breadcrumb to Slabchisel's Survey.  It appears as though it is not available if you pick up Fight the Flood first.\n\nI kind of went the wrong way around Wetlands and wanted to make sure that I didn't miss any quests I could possibly pick up.  I was able to pick up the first two quests in the chain, but not this one. :)",
            date = "2011-01-10T16:20:42-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25770#comments:id=1287798",
        },
        {
            id = 1542260,
            score = 5,
            author = "hawkmb",
            text = "Correct, if you have Fight the Flood you have to drop it to get the Keg Run quest.",
            date = "2011-10-14T01:03:04-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25770#comments:id=1542260",
        },
        {
            id = 2550125,
            score = 1,
            author = "questionauthity",
            text = "Well, crud. I already did Fight the Flood; abandoned all other Wetlands quests; Rharen still won't give me Keg Run. So,will I get the Accomplishment for the series or am I screwed?",
            date = "2018-02-02T14:41:11-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25770#comments:id=2550125",
        },
        {
            id = 6087367,
            score = 1,
            author = "nairesiga",
            text = "If you missed this quest because you completed \"Fight the Flood\" before 'Keg Run\" here is the only solution you have. Stand next to the quest giver Mounteneer Rharen and get ready.From the Group Finder -Premade groups-Questing pick up any group and apply to join. When they accept you in the group open your map and at the bottom enable party sync.If you can't see this option leave party and select another one. Once you find a group and party sync you can see the quest (or the previous one) .If you can't see them it means no one in the party has done it. Leave the party and find another one. Repeat the process until you finally see the quests. Go and complete them. Leave the party and happy days.",
            date = "2025-03-24T20:40:05-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25770#comments:id=6087367",
        },
    },
    [25771] = {
        {
            id = 2016312,
            score = 42,
            author = "Velfar",
            text = "You can still do these quests, but if you see the phased version of Blasted Lands after the Iron Horde invasion, you have to talk to Zidormi (http://www.wowhead.com/npc=63546/zidormi) near the entrance to the zone to view the old Blasted Lands.",
            date = "2014-10-20T05:37:30-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25771#comments:id=2016312",
        },
        {
            id = 1204293,
            score = 25,
            author = "42337",
            text = "It does NOT count towards the Blasted Lands Quest Achievement or the Loremaster Achievement.\n\nThe quest is repeatable, you can go turn it in every time you find a fragment, although it might not be worth doing it multiple times.\n\nThe reward bag contains a green item, iLvl 49-52, so the only reason for doing the quest is if you want a few greenies for sharding or have really shabby gear.",
            date = "2010-12-03T13:56:24-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25771#comments:id=1204293",
        },
        {
            id = 2022078,
            score = 8,
            author = "Konarc",
            text = "As of 6.0.2 it seems that this quest is still obtainable, but you are not able to complete it (but keep reading).\n\nThe new version/instance of the Blasted Lands has replaced https://www.wowhead.com/npc=7363  with a different group NPCs. You're not going crazy.\n\nBut rejoice! https://www.wowhead.com/npc=7363 indeed was not removed. You need to speak to https://www.wowhead.com/npc=88206 at then entrance of the Blasted Lands (from the Swamp of Sorrows) and \"go back in time\" and then you can turn in the quest to https://www.wowhead.com/npc=7363. Remember to go back to https://www.wowhead.com/npc=88206 and \"return to the present.\"\n\nI hate abandoning quests, and I'm sure that there are others out there that feel the same way. Good luck!",
            date = "2014-11-01T10:29:08-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25771#comments:id=2022078",
        },
        {
            id = 1193511,
            score = 6,
            author = "ricster8",
            text = "This quest starts from Imperfect Draenethyst Fragment (http://www.wowhead.com/item=10593) which has a chance to drop from any mob in the Blasted Lands.\n\nIt is an updated version of an old world quest, the only difference being the level requirements.",
            date = "2010-11-28T13:48:42-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25771#comments:id=1193511",
        },
        {
            id = 1438953,
            score = 4,
            author = "StansDad",
            text = "You're likely to pick up quite a few of these as you quest in Blasted Lands, but you won't want to trek back to hand them in each time you find one; fortunately, you can stack them in one inventory slot and turn a bunch in in one go. With the rewards in \"Kum'isha's Junk\" bag being uncommon items of level 48-53 I certainly found it worth it.",
            date = "2011-06-11T01:07:49-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25771#comments:id=1438953",
        },
    },
