            score = 12,
            author = "106814",
            text = "Don't miss the ram like I did.\nAccept the quest and click que ram near the flight master ( like a vehicle ) and get a free ride to Menethil.",
            date = "2010-12-01T22:26:17-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25777#comments:id=1201206",
        },
        {
            id = 1951381,
            score = 6,
            author = "CrittinRogue",
            text = "If anyone is a high level, and doing these quests for transmogrification, it may bug out on you. The quest \"Onwards to Menethil\" may not show up for you, but just go there and talk to Captain Stoutfist, you will still get the last quest to this chain. Just did it on my level 49 Affliction Warlock for the wand transmog.",
            date = "2014-03-16T00:45:30-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25777#comments:id=1951381",
        },
        {
            id = 1523365,
            score = 5,
            author = "Nappa",
            text = "The speed of the ram ride was more entertaining than I expected.\n\nhttp://www.youtube.com/watch?v=Sfqt1EzRtTA (http://)",
            date = "2011-09-20T21:45:08-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25777#comments:id=1523365",
        },
        {
            id = 1417406,
            score = 4,
            author = "FuryWar",
            text = "Yes, another reason it's a good idea to read every quest text before you try to charge off to get it done!  As the quest says, hop on the ram named \"Brisket\" nearby, and he'll give you a quick ride to Menethil where you can talk to Captain Stoutfist..",
            date = "2011-05-13T02:06:38-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25777#comments:id=1417406",
        },
        {
            id = 1287804,
            score = 3,
            author = "Irayna",
            text = "This is a breadcrumb to Menethil Harbor.  It appears as though it is not available if you pick up Assault on Menethil Keep first.\n\nI kind of went the wrong way around Wetlands and wanted to make sure that I didn't miss any quests I could possibly pick up.  I was able to complete other quests in this chain after I did that quest, but not this (or Keg Run). :)",
            date = "2011-01-10T16:22:35-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25777#comments:id=1287804",
        },
    },
    [25778] = {
        {
            id = 1355859,
            score = 7,
            author = "794585",
            text = "I had some reservation with this quest.  Lore-wise, it makes you look very bad.  If WoW ever keeps a player level alignment of good and evil then this would definitely not be a good.  However, with the questline so linear, I would be missing out on a lot if this wasn't finished.\n\nAlso even though they turned aggro, it doesn't matter after 10 levels, it's still a walk in the park through their camp.  :)",
            date = "2011-03-03T02:11:18-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25778#comments:id=1355859",
        },
        {
            id = 1519017,
            score = 5,
            author = "556068",
            text = "After you turn this in he yells to his people to kill you for trying to give them fake gold.  Obviously Skycaller Vrakthris doesn't pay any mind to that, as he still lets you turn in the Fake Gold for Black Gold quest, even though the rest of the village is hostile to you.",
            date = "2011-09-16T00:46:33-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25778#comments:id=1519017",
        },
        {
            id = 1272999,
            score = 4,
            author = "Swifteye",
            text = "Be warned that completing this quest will turn all of the centaur on the crag (with the exception of the khan you turn the quest into) from Neutral to Hostile.\n\nThere are no spawns in range of the questgiver, i.e. you will not be attacked immediately upon turning in as long as you don't exit the tent... but be prepared to fight your way out; there will be no more breezy, aggro-free sauntering through the area. Unless you're a Rogue like me. ;-)",
            date = "2011-01-02T09:59:00-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25778#comments:id=1272999",
        },
        {
            id = 1415109,
            score = 2,
            author = "Luminasita",
            text = "Agreed.  It is a bit odd that right after this chain, it sends you to help some druids..",
            date = "2011-05-10T15:24:06-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25778#comments:id=1415109",
        },
    },
    [25779] = {
        {
            id = 1425056,
            score = 11,
            author = "troyam",
            text = "If you are running around picking the sungrass and liferoot there, hold off on completing this quest, as it turns the Galaks aggressive.",
            date = "2011-05-22T23:08:23-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25779#comments:id=1425056",
        },
        {
