    [25780] = {
        {
            id = 2297485,
            score = 0,
            author = "785293",
            text = "This quest has NO prerequisites.\n\nDespite being part of a chain, if you go straight to Menethil Harbor without doing any prior quests, you can still get this one directly.",
            date = "2016-01-12T14:09:56-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25780#comments:id=2297485",
        },
        {
            id = 5300537,
            score = 0,
            author = "Ehayen",
            text = "That's weird. The first 3 times I killed Horghast he just disappeared leaving no corpse and no loot. Then the 4th time the corps appeared behind me and to the left and I was able to loot it.\n\nIt seems to depend on where the mob is standing when you kill it, whether it appears behind you or disappears.\n\nAlso, unlike many other named mobs, you can loot this one repeatedly (for a whole 9 silver). So you could make this a very slow gold farm.",
            date = "2021-12-18T13:39:58-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25780#comments:id=5300537",
        },
        {
            id = 1462931,
            score = -1,
            author = "733706",
            text = "This quest is bugged as of the date of this comment.  Its a simple quest-just go in the keep behind the questgiver, fight your way to the main room (its laid out just like many of the keeps in the game) and slay the quest mob. My level 21 warlock had no trouble at all.\n\nBUT!  This guy respawns seconds after you slay him. After I killed him the second time, there were two corpses of his to loot.  This seems to be a common problem after the Cata release-many quest mobs respawn right after you kill them. Wrote another ticket.",
            date = "2011-07-06T22:04:16-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25780#comments:id=1462931",
        },
    },
