            text = "Got so mixed up in here that I ended up having to fight my way out through the Alliance entrance and emerged at 71, 77. Time to trek it all the way back to Krom'gar Fortress...",
            date = "2019-05-10T14:24:16-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25793#comments:id=3122210",
        },
    },
    [25796] = {
        {
            id = 1293425,
            score = 21,
            author = "Naenthos",
            text = "This calls to mind the oil companies and several other times in human history when greedy and selfish people tried to take what wasn't theirs. First they try to bribe (and deceive) them, and when that fails, they resort to violence.",
            date = "2011-01-14T11:23:55-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25796#comments:id=1293425",
        },
        {
            id = 1885214,
            score = 15,
            author = "1137275",
            text = "Whilst I agree with the comments made about the morality of this quest, I think something has been glossed over here. This chain drops the cutest leather top in the game ...... and so .... a few stray horses and their oil v fashion ..... sorry, but their are priorities in life",
            date = "2013-08-08T14:17:03-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25796#comments:id=1885214",
        },
        {
            id = 1190794,
            score = 8,
            author = "462295",
            text = "The oil must flow!\n\"The spice must flow.\"\n\nDune reference. :)",
            date = "2010-11-27T15:18:37-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25796#comments:id=1190794",
        },
        {
            id = 1527126,
