    [25798] = {
        {
            id = 1778358,
            score = 9,
            author = "PriestessAur",
            text = "The centaurs you kill while defending the drill will count towards https://www.wowhead.com/quest=25796",
            date = "2012-12-09T11:52:21-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25798#comments:id=1778358",
        },
        {
            id = 1358596,
            score = 8,
            author = "680560",
            text = "Their lines of speech were great.\n\nGalak Stormer yells: Junk shot that thing!\nGalak Wrangler yells: No gold for oil!\nGalak Stormer yells: Cap it!",
            date = "2011-03-05T18:46:27-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25798#comments:id=1358596",
        },
        {
            id = 1232115,
            score = 5,
            author = "Handlebar605",
            text = "You get to take the given drill to an oil point (those Black Bubbles) and then defend it thru just two waves of Centaurs",
            date = "2010-12-14T02:26:17-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25798#comments:id=1232115",
        },
        {
            id = 1677907,
            score = 3,
            author = "822734",
            text = "Reference to a movie. Really good movie.",
            date = "2012-06-18T02:23:50-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25798#comments:id=1677907",
        },
        {
            id = 1637157,
            score = 1,
            author = "721249",
            text = "Some folks have expressed moral difficulties with the 'torture' quest in Northrend's Borean Tundra. I had problems with this series.\n\nWe began by trying to swindle the locals, hijacking the negotiations by means of armed robbery. Then we tried to cheat them with painted Fool's Gold. When that didn't work, we proceeded to murder the natives and to take the oil rights by force. Next we're to destroy their local deity.\n\nI guess this is supposed to be some sort of reflection on the bad actions of \"Big Oil\", but it's not. Rather it's a parody of how the environmentalists and anti-capitalists claim to see the world.",
            date = "2012-03-08T21:59:58-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25798#comments:id=1637157",
        },
    },
