        {
            id = 1833364,
            score = 10,
            author = "dIggl3r",
            text = "If you get that quest and you get an error telling you you are required to mouthpiece, it means it's bugged.  I just had that problem, and I fixed it by logging off (closed WoW) and relogged back in, and the mouthpiece miraculously appeared!\n\n(before that I was killing centaurs for 30 mins, thinking it would drop... duh!)",
            date = "2013-03-23T18:02:37-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25814#comments:id=1833364",
