            author = "HookTwineThinker",
            text = "If you have any level toon which has not done the \"Menethil Harbor\" starter quests then bring them here.\nFirst Mate Fitzsimmons gives you a quest to get him beer from the basement of the Inn.\nAfter you complete it then the \"Cursed To Roam\" quest comes up.\nBe mindful completing the quests will give you a chance to obtain 1 of 5 mail drops.",
            date = "2023-01-30T13:57:13-06:00",
