    [25818] = {
        {
            id = 1207858,
            score = 36,
            author = "Dioblique",
            text = "It's hell when the yellow question mark is right on the screen and you can't find it, especially for blonde mages. After you kill 'him' and get the key, jump ship toward the open sea to the north, turn and swim to the bottom, on the north side  of the ship there's a hole you can swim through and viola, \"work complete\".",
            date = "2010-12-05T09:23:40-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25818#comments:id=1207858",
        },
        {
            id = 1486662,
