    [25819] = {
        {
            id = 1193570,
            score = 122,
            author = "Vothul",
            text = "Honestly. I found this creepy. Thought it was same ole, same ole quest.\n\nThen they pull the rug from right under you.\n\nWell done, Blizz.",
            date = "2010-11-28T14:19:01-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25819#comments:id=1193570",
        },
        {
            id = 1184390,
            score = 95,
            author = "196807",
            text = "On quest completion, Glorin says this:\n\nGlorin Steelbrow says: The Eye of Paleth was retrieved and cleansed a long time ago, mage. We thought the curse lifted.\nGlorin Steelbrow says: Not a year ago, poor old Fitzsimmons passed on, his body ruined by drink.\nGlorin Steelbrow says: Ever since, now and then, people claim he's spoken to them and told them to get the eye...\nGlorin Steelbrow says: Cursed to roam the earth forever...not even poor Fitzsimmons could escape.\nGlorin Steelbrow says: Don't ask me what you actually brought me, mage. You're better off forgetting this ever happened.",
            date = "2010-11-25T09:36:36-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25819#comments:id=1184390",
        },
        {
            id = 1189700,
            score = 87,
            author = "Spring",
            text = "Don't ask me what you actually brought me, class. You're better off forgetting this ever happened.\n\nThis line right here has so far made this one of the eeriest new quests. I dig it.",
            date = "2010-11-27T05:56:03-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25819#comments:id=1189700",
        },
        {
            id = 1194695,
            score = 72,
            author = "185117",
            text = "Directed by M. Night Shyamalan.",
            date = "2010-11-29T00:16:37-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25819#comments:id=1194695",
        },
        {
            id = 1493909,
            score = 68,
            author = "Zealguard",
            text = "This is officially the best edited vanilla WoW quest chain in Cataclysm.\n\nIt completely blew my mind when I turned this final quest in.",
            date = "2011-08-13T07:36:12-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25819#comments:id=1493909",
        },
    },
    [25820] = {
        {
            id = 1196681,
            score = 9,
            author = "Chancakes",
            text = "Anyone else find it a bit strange that her 'son' is a darker-skinned human child, despite the fact that her apparent husband (http://www.wowhead.com/npc=1452\") is a dwarf as well?\n\n/cough",
            date = "2010-11-29T22:51:33-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25820#comments:id=1196681",
