        {
            id = 1200631,
            score = 2,
            author = "713717",
            text = "I'm unable to obtain the quest \"Free Freewind Post\" after completing Deliver the Goods & other quests in this chain.  I have not completed other side quests at the Speedbarge.  I'm a Night Elf Hunter.  Is there a reason anyone knows of... that I can't get the quest?  Ticket times are a little high now, I'm guessing the community can answer before a GM ;p",
            date = "2010-12-01T16:38:31-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25835#comments:id=1200631",
        },
    },
    [25836] = {
