            id = 1198829,
            score = 21,
            author = "Soldier45",
            text = "It doesn't look like you get a free ride to the post so you'll have to go through barrens, into RFK and then take the bridges leading to Freewind.\n\nThe quest ender is located on a Mesa you can reach with your River Boat (http://www.wowhead.com/item=55121). Do not take the long away through RFK.",
            date = "2010-11-30T21:26:01-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25836#comments:id=1198829",
        },
        {
            id = 1201960,
