    [25839] = {
        {
            id = 1183157,
            score = 14,
            author = "Talvanor",
            text = "The VLD system is probably a reference to the military's HALO (High Altitude Low Opening) combat parachuting, in which paratroopers are dropped from extremely high altitudes and open their chutes as low as is safe.\n\nThe technique was first used in Vietnam to drop SOG troopers into zones too dangerous for helicopter insert, and has been used by special operations groups ever since.\n\nhttp://en.wikipedia.org/wiki/High_Altitude_Low_Opening",
            date = "2010-11-24T22:35:14-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25839#comments:id=1183157",
        },
