        {
            id = 1186286,
            score = 6,
            author = "708409",
            text = "Quest chain continues with Grimtotem Supremacy (http://www.wowhead.com/quest=25847).",
            date = "2010-11-25T23:48:04-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25846#comments:id=1186286",
        },
        {
            id = 1444750,
            score = 4,
            author = "nexxius2",
            text = "Have the same problem right now, all mobs are hostile so can't hand in the weapons, trying to log out and back in.\nPassing close to the guy i fed earlier shows me \"Grundig is nearby. Look there\" but Grundig is still hostile, but friendly :)\n\nSeems when i left the zone and came back bit later the quest was okey again.",
            date = "2011-06-19T06:44:10-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25846#comments:id=1444750",
        },
        {
            id = 1409232,
            score = 3,
            author = "817700",
            text = "This quest was bugged for me. Grundig Darkcloud and all the Grimtotem appeared hostile (with red names). He had the question mark above his head, but I could not turn it in. I also could not attack these NPCs even though the attack icon appeared with mouseover. I tried leaving my group, abandoning and getting the quest again, and logging out and back in, but none of these worked. I finally got it to work by quitting the game completely and then logging in.",
            date = "2011-05-04T09:26:41-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25846#comments:id=1409232",
        },
        {
            id = 1420477,
            score = 3,
            author = "718446",
            text = "I adressed the problem rasai451 described and after about ten minutes i've got a response from a GM, I explained the issue and he asked me several things (move out of the area and move back in, relog, quit the game, etc), he also temporarely ''removed'' the NPC and did some funky stuff I could't see. After half an hour of trouble shooting he wasn't able to solve it and forwarded it further. Let's all hope this will get hotpatched soon! :)",
            date = "2011-05-16T17:01:28-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25846#comments:id=1420477",
        },
        {
            id = 1553436,
            score = 2,
            author = "898732",
            text = "I solved this by going to Camp Aparaje (just to the south), kill the npc and a second will appear, dispatch him and the general will appear; once you kill him, he drops a horde chest and Grundig becomes friendly. You will hace to do this again afterwards as the next quest.",
            date = "2011-10-25T12:55:01-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25846#comments:id=1553436",
        },
    },
