        {
            id = 2580574,
            score = 9,
            author = "Bergelmir",
            text = "Can I just say how much I hate these kind of quests that immediately puts you on a mount and sends you off without you having any say in it? I had other quests to turn in, dang it!",
            date = "2018-07-14T09:27:37-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25880#comments:id=2580574",
        },
        {
            id = 1608984,
            score = 3,
            author = "913874",
            text = "If you are doing this for the Flowing Waters set you went the wong way.  It seems like the entire zone is one huge chain quest and these 6 hours of play into it.  Pardon me while scream.",
            date = "2012-01-09T00:07:29-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25880#comments:id=1608984",
        },
        {
            id = 3228176,
            score = 1,
            author = "GibbleFenwick",
            text = "I happened to be mounted when I accepted the quest, and was not immediately put on a flight to the overlook.\nI've tried abandoning and reaccepting the quest, and cannot get a flight there.\nI don't have the destination flight point flagged, and now have to hoof-it there. :(",
            date = "2020-09-07T06:35:50-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25880#comments:id=3228176",
        },
    },
    [25882] = {
        {
