    [25889] = {
        {
            id = 1182628,
            score = 55,
            author = "Diwtay",
            text = "1. Use the whistle to call a hippogryph.\n2. Fly south past the Battlescar Valley, to Thal'darah Grove [41, 45]\n3. Chase after the Helpless Young Druid's and pick them up on the mount.\n4. Fly back to [40, 31] and drop off your passenger next to the hippogryph master Teloren.\n5. Repeat until you have rescued 5 of the Helpless Young Druid's.\n\nIf you want to check out the Night Elf town in Thal'darah Grove's do it now, because the next quest destroys the area.",
            date = "2010-11-24T18:41:53-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25889#comments:id=1182628",
        },
        {
            id = 1205844,
            score = 14,
            author = "Whiterock",
            text = "Quest talk:\n\nScared druids on ground:\nHelpless Young Druid (http://www.wowhead.com/npc=41528) says: HELP!\nHelpless Young Druid (http://www.wowhead.com/npc=41528) says: Orcs everywhere!\nHelpless Young Druid (http://www.wowhead.com/npc=41528) says: We're all going to die!\nHelpless Young Druid (http://www.wowhead.com/npc=41528) says: Where is Master Thal'darah (http://www.wowhead.com/npc=41482)!\nHelpless Young Druid (http://www.wowhead.com/npc=41528) says: Won't somebody help us?\n\nRescue Young Druid (http://www.wowhead.com/spell=77628):\n says: Get on!\n says: Get on my hippogryph (http://www.wowhead.com/npc=41529). We heavn't much time!\n says: Master Thal'darah (http://www.wowhead.com/npc=41482) has sent me to rescue you. Climb on!\n says: Take my hand, young one.\n says: The whole place is going to blow up! Let's go!\n\nDuring flight:\nHelpless Young Druid (http://www.wowhead.com/npc=41528) says: All of Darnassus (http://www.wowhead.com/zone=1657) will know what you have done for us.\nHelpless Young Druid (http://www.wowhead.com/npc=41528) says: Could we fly higher?\nHelpless Young Druid (http://www.wowhead.com/npc=41528) says: I thought I was done for!\nHelpless Young Druid (http://www.wowhead.com/npc=41528) says: I will never forget this act of kindness.\nHelpless Young Druid (http://www.wowhead.com/npc=41528) says: I will repay you one day.\nHelpless Young Druid (http://www.wowhead.com/npc=41528) says: Thank you, friend.\nHelpless Young Druid (http://www.wowhead.com/npc=41528) says: You are a hero.\n\nDrop Off Young Druid (http://www.wowhead.com/spell=77629):\nHelpless Young Druid (http://www.wowhead.com/npc=41528) says: I am forever indebted to you, friend.\nHelpless Young Druid (http://www.wowhead.com/npc=41528) says: May Elune (http://www.wowwiki.com/Elune) watch over you.\nHelpless Young Druid (http://www.wowhead.com/npc=41528) says: Our world needs more heroes like you.\nHelpless Young Druid (http://www.wowhead.com/npc=41528) says: Thank you. You saved my life.",
            date = "2010-12-04T10:24:55-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25889#comments:id=1205844",
        },
        {
            id = 1438745,
            score = 13,
            author = "839945",
            text = "By far is the best quest , so far....loved it...i wanna fly as soon i can..lol...just inspires you to reach level  60....",
            date = "2011-06-10T18:22:56-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25889#comments:id=1438745",
        },
        {
            id = 1406472,
            score = 11,
            author = "Luminasita",
            text = "Give the grove a good look before going to the next quest.",
            date = "2011-05-01T16:04:05-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25889#comments:id=1406472",
        },
        {
            id = 2626586,
            score = 11,
            author = "CWR03",
            text = "Return the Druid children to the flight master at Thal'darah Overlook.\n\n(Provided for those who don't use coordinate addons, I had forgotten where I picked up the quest and kept getting knocked off hippogryph while looking for it)",
            date = "2018-10-27T12:20:04-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25889#comments:id=2626586",
        },
    },
    [25891] = {
        {
            id = 1557061,
            score = 29,
            author = "Flitzy",
            text = "My angry face towards the Horde after doing this quest = >:||\n\nAnyone who still thinks they're honourable after this..... /sigh",
            date = "2011-10-29T19:52:14-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25891#comments:id=1557061",
        },
        {
            id = 1567869,
            score = 25,
            author = "Dekkion",
            text = "@Flitzy:\n\nAs always there are both sides to the story.\n\nIf you play the Horde quest chain you will find out that the Horde did not approve of this bomb at all.\nIn fact, when Hellscream finds out it was created and used, he dismisses warlord Krom'Gar from duty by throwing him off a cliff. But not before he gives him a speech saying no member of the Horde kills innocent druids and murders children. He tells Krom'Gar that his behaviour is without honour, and Hellscream would have never approved of it if he'd known beforehand.\n\nHellscream may be a warmongerer, but he still has honour, as do other members of the Horde.\nExcept the Forsaken, they are downright evil, and a disgrace to the Horde, as Hellscream himself finds as well.",
            date = "2011-11-09T14:28:44-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25891#comments:id=1567869",
        },
        {
            id = 1205968,
            score = 9,
            author = "Whiterock",
            text = "Quest talk:\n\nMaster Thal'darah (http://www.wowhead.com/npc=41547) says: Look there! The Krom'gar baloon (http://www.wowhead.com/npc=41551) is heading towards the grove! We must hurry!\nMaster Thal'darah (http://www.wowhead.com/npc=41547) says: We're too late. The grove is destroyed and with it our hopes and dreams.\nMaster Thal'darah (http://www.wowhead.com/npc=41547) says: The Horde will pay for this atrocity. Hellscream (http://www.wowhead.com/npc=39605) must answer for this crime!\n\nP.S.: I choosed this Baloon link becose:\n\nBoth Baloon and Bomb should have been seen only as Alliance. So \"React: A(yellow)\"\nBaloon - 28650hp, Bomb - 955hp\nnpc id of those 2 must be close numbers. Aswell as Master and Hippogryph.\n[npc=41534 domain=www] Thal'darah's Hippogryph\n[npc=41547 domain=www] Master Thal'darah\n[npc=41551 domain=www] Krom'gar Hot Air Balloon\n[npc=41552 domain=www] The Bomb",
            date = "2010-12-04T11:38:33-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25891#comments:id=1205968",
        },
        {
            id = 1186092,
            score = 7,
            author = "708409",
            text = "Completing this quest appears to open up a couple new ones in the area:\n\nSeen Better Days (http://www.wowhead.com/quest=25912)\nPutting Them to Rest (http://www.wowhead.com/quest=25913)\nBack to the Depths (http://www.wowhead.com/quest=25914)",
            date = "2010-11-25T22:19:25-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25891#comments:id=1186092",
        },
