    [25905] = {
        {
            id = 1195768,
            score = 45,
            author = "139511",
            text = "I find it humorous how this quest basically consists of you running around whistling at rams in a flirtatious manner.\n\nCold mountain nights...",
            date = "2010-11-29T13:17:33-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25905#comments:id=1195768",
        },
        {
            id = 1131406,
            score = 41,
            author = "49555",
            text = "Just go south to the \"Stolen Rams\" and do the emote /whistle when you are near them.",
            date = "2010-09-30T09:20:41-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25905#comments:id=1131406",
        },
        {
            id = 1194790,
            score = 16,
            author = "torin23",
            text = "You need to be more than near them.  You have to have them targeted and near them and the /whistle.\nBe careful you don't get both a raider and a bear, they're both nearby.",
            date = "2010-11-29T02:01:09-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25905#comments:id=1194790",
        },
        {
            id = 1451641,
            score = 14,
            author = "Gadoink4",
            text = "I like that they've put in a quest to teach newbies how to use emotes. I remember when I first starting playing, I could NOT figure out how to emote. Thanks, Blizzard!",
            date = "2011-06-27T03:27:16-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25905#comments:id=1451641",
        },
        {
            id = 2287791,
            score = 12,
            author = "rmalheiros",
            text = "When you get this quest, type /m to open macro window.\nPress new button, choose any name and any icon, ok\n\nMacro text:\n/tar Stolen Ram\n/whistle\n\nSave it, drag and drop this macro to your actionbar.\nIf you keybind it, you can just spam this macro while passing by those rams.",
            date = "2015-12-14T14:19:58-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25905#comments:id=2287791",
        },
    },
    [25912] = {
        {
            id = 1186093,
            score = 13,
