        {
            id = 1292107,
            score = 6,
            author = "648382",
            text = "Harbinger Aph'lass is at 41.25 23.15\nHe is surrounded by the tendrils.",
            date = "2011-01-13T12:52:03-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25914#comments:id=1292107",
        },
        {
            id = 1620107,
            score = 4,
            author = "Allyosaugh",
            text = "There are two types of tentacles that you can kill, if you're melee DPS and you try to kill the invading tendrils, then chances are you'll be grabbed by them and thrown up in the air, taking massive damage. If you're ranged and you stay out of melee range, however, you'll be fine.\nMelee will want to try and kill the Invading Crushers, which won't do the fall damage attack.",
            date = "2012-02-02T01:16:41-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25914#comments:id=1620107",
        },
    },
    [25925] = {
        {
            id = 1269016,
            score = 9,
            author = "Esilenna",
            text = "The Glaive Throwers are the purple and green machines located just outside the inn: 38.7,32.3.\nMount one and drive it down the cliff, using the south-west path.",
            date = "2010-12-31T02:25:34-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25925#comments:id=1269016",
        },
        {
            id = 1186124,
            score = 8,
            author = "708409",
            text = "Completing this quest unlocks:\n\nWorld First: Gnomegen (http://www.wowhead.com/quest=25934)\nHungry Pups (http://www.wowhead.com/quest=25935)",
            date = "2010-11-25T22:31:32-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25925#comments:id=1186124",
        },
        {
            id = 1192365,
            score = 5,
            author = "CMKCot",
            text = "At least on the current patch the glaive thrower is kinda bugged, in a funny/good way.\n\nthe first skill (glaive throw) triggers no GCD, has no CD, and consumes no energy...\n\nGlaive minigun?",
            date = "2010-11-28T04:27:15-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25925#comments:id=1192365",
        },
        {
            id = 1214887,
            score = 4,
            author = "Yaushee",
            text = "Upon completion, the NPC says: \"We witnessed the detonation of the bomb. Terrible, terrible destruction...\"\nA funny reference to Dustin Browder's \"Terrible, terrible damage\" (http://starcraft.wikia.com/wiki/Terrible_terrible_damage) :)",
            date = "2010-12-08T12:20:25-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25925#comments:id=1214887",
        },
        {
            id = 1208664,
            score = 2,
