    [25926] = {
        {
            id = 1320463,
            score = 8,
            author = "750237",
            text = "Fun quest for a farming quest.\n\nTIP:  Keep moving around while fighting each beast though as the Mirebeasts will spawn mushrooms that grow and release an \"Unstable Cloud\" which inflicts Nature Damage over time.  think of them in the same way a mob can cast a totem or such.  If able, shoot them to destroy, or move outside the blast zone when they release the cloud.\n\nImage provided.",
            date = "2011-02-03T12:52:16-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25926#comments:id=1320463",
        },
    },
    [25927] = {
        {
            id = 1190674,
            score = 92,
            author = "170618",
            text = "The elementals and oozes share a respawn!   So if you are short on elementals, start killing oozes!",
            date = "2010-11-27T14:26:46-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25927#comments:id=1190674",
        },
        {
            id = 1193821,
            score = 55,
            author = "Bowien",
            text = "If you're doing this quest along with For Peat's Sake (http://www.wowhead.com/quest=25939), note that hitting a Rampant Fire Elemental (http://www.wowhead.com/npc=41449) with the Blessed Floodlily (http://www.wowhead.com/item=56134) will turn them into a Doused Fire Elemental (http://www.wowhead.com/npc=41462). It cuts their HP in half, but you will not get quest credit for the kill.",
            date = "2010-11-28T15:52:46-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25927#comments:id=1193821",
        },
        {
            id = 2551945,
            score = 42,
            author = "craptola",
            text = "You know those things there are only five of? Yeah, go kill eight of them.",
            date = "2018-02-10T15:28:26-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25927#comments:id=2551945",
        },
        {
            id = 3147532,
            score = 14,
            author = "edvilon",
            text = "Found more Northwest of the circle than in the circle.",
            date = "2019-08-15T13:06:37-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25927#comments:id=3147532",
        },
        {
            id = 1186530,
            score = 8,
            author = "709647",
            text = "The elementals you need do not seem to pop up nearly as frequently as the Smouldering Oozes do. It's a good thing you only need 8 of them. Keep doing laps until they respawn - they are in the area as marked in the map.",
            date = "2010-11-26T02:23:14-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25927#comments:id=1186530",
        },
    },
