    [25937] = {
        {
            id = 1603920,
            score = 7,
            author = "930194",
            text = "These are scattered throughout the cave, all the way to the end, so if for some reason you're sharing the cave with someone else, don't worry, there will be plenty for everyone.\n\nWhile you're working on this quest in the cave, if you want to work your way all the way to the back/end of the cave, there will most likely be a rare spawn, https://www.wowhead.com/npc=1119.",
            date = "2011-12-29T23:39:21-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25937#comments:id=1603920",
        },
        {
            id = 1753807,
            score = 3,
            author = "730303",
            text = "The Frozen Artifacts appear to be bugged at the moment (5.0.5). Multiple attempts to loot them using various methods (right clicking, using the item from the inventory and from the quest helper) have proved fruitless, causing the ice block to fade away, and no loot window appear, when I move they simply re-appear. Dropping the quest and picking it back up, and logging in and out did not solve the issue either.",
            date = "2012-10-30T12:11:13-05:00",
