        },
    },
    [25938] = {
        {
            id = 1552461,
            score = 28,
            author = "503971",
            text = "This quest is a Breadcrumb quest.\n\nBreadcrumb quests are quests that, even though you did not complete them and they were available at some point, have become unavailable permanently after certain conditions were met. If this happens to you, and you're a completionist, this quest can be marked as excluded in the Wowhead quest tracker if you are no longer able to complete it.\n\nThis quest becomes unavailable permanently, if either of the following conditions are met:\nhttps://www.wowhead.com/quest=28531 is completed.\nThis is a hero's call quest leading to this zone. You can only complete this quest, or the hero's call quest, not both. Completing the hero's call quest will therefore make this quest unavailable.\nhttps://www.wowhead.com/quest=14384 is completed.\nThis is one of the quests available in the quest hub that this quest points to, and is also considered a follow-up to this quest. Completing this quest will make all zone introductory quests leading to this npc, including this one, unavailable.\n\nExamples of Breadcrumb quests and conditions making them unavailable:\n\nHero's call quests.\nThey become unavailable if your character's level is too high, and the hero's call board sends you to a different npc/zone.\nZone introductory quests.\nThis also includes hero's call quests. These quests are often started in a certain lower level zone, and they direct you to the next zone. If there are several of these, including the hero's call, directing you to the same zone/npc, completing one will mean the others become unavailable.\nQuest hub introductory quests.\nThese are quests that direct you to the next quest hub in a zone. If you've already completed the quests in that quest hub, the quest directing you to it may become unavailable.\nFollow-up quests.\nThese are uncommon, but still appear in older zones that have not been changed much in recent expansions. Sometimes a follow-up quest of quest X is available before you complete quest X. If you complete that follow-up quest and go back to the quest X giver, you may encounter the error 'You do not meet the requirements for that quest', leaving you unable to start it or turn it in.\n\nNote: A quest being unavailable does not necessarily mean it's unavailable permanently. If you have not met the aforementioned conditions, and the quest is still unavailable, then you may have missed certain required quests that precede this one, or you do not meet the requirements in some other way. Always verify this before excluding this quest.",
            date = "2011-10-24T09:32:22-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25938#comments:id=1552461",
        },
        {
            id = 3303614,
            score = 11,
            author = "Koviko",
            text = "To be perfectly clear, if you want to complete both breadcrumbs you need to:\n\nPick up https://www.wowhead.com/quest=28531 from a Hero's Call Board or the Adventure Guide\nGo to https://www.wowhead.com/npc=36410 in Desolace\nTurn in the quest without picking up the follow-up quest\nGo north into Stonetalon Mountains and go to Farwatcher's Glen\nPlayers without flying mounts who were already questing in Stonetalon will want to keep the quests that give them https://www.wowhead.com/item=56221 as this allows them to traverse the mountain quickly instead of having to go around\n\nPick up https://www.wowhead.com/quest=25938\nTurn in the quest to the same NPC as before",
            date = "2021-02-24T01:02:02-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25938#comments:id=3303614",
        },
        {
            id = 1220145,
            score = 4,
            author = "Rhynchelma",
            text = "This quest should be listed under Desolace, not Stonetalon to be consistent.",
            date = "2010-12-09T22:42:35-06:00",
            sourceUrl = "https://www.wowhead.com/quest=25938#comments:id=1220145",
        },
        {
            id = 1691127,
            score = 1,
            author = "244865",
            text = "Counts towards https://www.wowhead.com/achievement=4936.",
            date = "2012-07-22T17:13:07-05:00",
            sourceUrl = "https://www.wowhead.com/quest=25938#comments:id=1691127",
        },
        {
            id = 2579193,
            score = 1,
            author = "EmJii",
