    [26024] = {
        {
            id = 1190727,
            score = 63,
            author = "72565",
            text = "She's behind the house, not inside, not upstairs.",
            date = "2010-11-27T14:49:31-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26024#comments:id=1190727",
        },
        {
            id = 2318078,
            score = 6,
            author = "1532881",
            text = "Don't go up into the keep.  Take the first left hand path/street under the bridge, follow it to the end house and go behind it.  There is a bloody table at 23.1, 64.8 and she will spawn near it.",
            date = "2016-03-29T21:01:58-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26024#comments:id=2318078",
        },
        {
            id = 1642205,
            score = 5,
            author = "qon91",
            text = "Take the first path to the left when you enter Stromgarde Keep, then follow it all the way untill you face the house. there's a small opening at the left side (between the wall and the house).",
            date = "2012-03-21T13:45:39-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26024#comments:id=1642205",
        },
        {
            id = 1829463,
            score = 2,
            author = "1052302",
            text = "This is confirmed as of this date.  BEHIND the house.  Thanks for the tip, it took me forever before I read this :(",
            date = "2013-03-16T04:05:23-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26024#comments:id=1829463",
        },
        {
            id = 1854164,
            score = 2,
            author = "Hairband",
            text = "I put a target on her head and couldn't locate her.  FINALLY I found her behind the house.  I thought I looked but I didn't.  I went in the house and cleared it twice and meanwhile pulled every able-bodied Syndicate mob and his minion on both upper and lower right.  What a pain!\n\nAnd how sad, no there weren't any dwarf skeletons!",
            date = "2013-05-18T20:11:20-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26024#comments:id=1854164",
        },
    },
    [26025] = {
        {
            id = 1185935,
            score = 58,
            author = "139938",
            text = "Marez Cowl isn't actually in the house, but behind it.  You can get to her by squeezing between the left side of the house and the city wall.",
            date = "2010-11-25T20:55:28-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26025#comments:id=1185935",
        },
        {
            id = 1191975,
            score = 10,
            author = "Kyrgune",
            text = "At 24,65 to be a bit more exact.  Take a left under the bridge when you first enter the keep and stay by the right wall.  There will be a house at the end, then take the small area south behind it.",
            date = "2010-11-28T00:25:32-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26025#comments:id=1191975",
        },
        {
            id = 1641974,
            score = 7,
            author = "57893",
            text = "Blizzard never changed the quest text from the original quest to kill Marez Cowl, and I don't think it makes as much sense coming from a Dark Ranger as the original troll shaman.",
            date = "2012-03-20T19:05:01-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26025#comments:id=1641974",
        },
        {
            id = 1618263,
            score = 2,
            author = "759689",
            text = "He's around 23.64. He is not in the building, he is being it, SE side...",
            date = "2012-01-29T02:23:52-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26025#comments:id=1618263",
        },
        {
            id = 3373644,
            score = 1,
            author = "MustafaOnur",
            text = "If you have no idea how to accept this quest, or cant find the quest. You need to do First Blood (https://www.wowhead.com/quest=26022/first-blood) then you will able to get quest from Dark Ranger Alina.",
            date = "2021-04-04T06:45:29-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26025#comments:id=3373644",
        },
    },
    [26026] = {
        {
            id = 1102577,
            score = 65,
            author = "473214",
            text = "You can pick up most of the 4 items just by simple questing in the area. One is on top of a big shreddar/robot-like machine that you can simply ride up the ramp to get. Another is in a small hut near the alliance tent quest. Another is on top of a wooden ramp near the middle of the zone.\n\nThe last item is the only one that presents any difficulty. You need to ride around the right side of Cragpool lake, and when the path dead ends into the lake, take another right up the path and across all the scaffolding. At the giant wheel, continue left around it and the item looks like a big diving helmet at the end of the path.",
            date = "2010-08-17T16:41:35-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26026#comments:id=1102577",
        },
        {
            id = 1108770,
            score = 35,
            author = "634960",
            text = "The quest giver (A little Blood elf girl) and the shredder laying on the ground near her called Large Daddy are both a tribute to Bioshock. (Big Daddy and the Little Sister) I was amused when I saw it ;)\n\nAnd I'm not entirely sure but I think the quest name also refers to Rapture. I might be wrong though.",
            date = "2010-08-27T03:51:30-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26026#comments:id=1108770",
        },
        {
            id = 1243986,
            score = 17,
            author = "737787",
            text = "Would you kindly bring Mr. D's stuff back so he can teach those baddies in the Alliance a lesson?\nThis so creeped me out.",
            date = "2010-12-18T18:58:57-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26026#comments:id=1243986",
        },
        {
            id = 1181247,
            score = 13,
            author = "707852",
            text = "Mechanized fire is at 63, 56. It was on top of a tank with a shredding arm.\n\nMechanized ice is at 66, 50, near Cragpool Lake.\n\nMechanized water was in a colorful little hut near the tent quest, but I forgot to write down the coordinates.",
            date = "2010-11-24T11:12:57-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26026#comments:id=1181247",
        },
        {
            id = 1515933,
            score = 12,
            author = "733706",
            text = "Some further clarification:  To get the apparatus, go to the east end of Cragpool Lake any way you can.  There is a  27 elite fish in there that is the subject of another quest, so be careful if you swim.\n\nWhen you get to the east end of the lake, walk a few steps and you will see rails on your left. This is the start of the path up into the scaffolding where you continue walking and killing mobs until you finally see the quest item (a big helment) sparkling.  The rails that start the path can be found at 68, 46 for those who have coords.\n\nNow about getting on the back of the tank, others have mentioned a ramp. There is no ramp, you actually climb up one of the treads from the rear, located at 63, 57.  I will admit it does look like a ramp.\n\nObviously this quest has changed since people began posting comments. The comments talk about looking for fire, ice, water and the apparatus.  When I did this quest, water had been replaced by air.\n\nThe air is located in a fancy green house located at 60, 63, on the west side of the area where all the tents are, pretty much straight south of Windshear Hold. If you have the quest \"Ashes to Ashes,\" all these tents will be sparkling because you have to burn them.\n\n.",
            date = "2011-09-11T22:44:03-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26026#comments:id=1515933",
        },
    },
    [26027] = {
        {
            id = 1661098,
            score = 17,
            author = "dakota3",
            text = "Instructions for the directionally challenged - like myself.\nWhen you enter Stromgarde, take your first right as soon as you pass under the low stone bridge immediately inside the entrance.\nThen take your first left. You'll know you're at the correct corner when you see two mutilated bodies impaled on spikes, mounted on a low stone pillar.\nFollow the  walled path down the slope and when you get to the bottom, bear to the right and the mobs you want are in the courtyards directly in front of you.",
            date = "2012-05-01T01:03:30-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26027#comments:id=1661098",
        },
        {
            id = 1694868,
            score = 6,
            author = "sitecow09",
            text = "after you finish the quest, Alina says this: \"Cleared out properly? Good. I doupt we'll even bother to lurk in Stromgarde. That ramshackle hole needs to be razed into dust. The land would make a decent spot for a new Undercity in its place.\"\nNEW Undercity? Whats wrong with the old one?",
            date = "2012-08-01T12:54:44-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26027#comments:id=1694868",
        },
        {
            id = 1504264,
            score = 3,
            author = "276278",
            text = "Entrance @ 18.0, 62.3\n\nOpening in wall @ 14.5, 72.3",
            date = "2011-08-26T23:29:14-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26027#comments:id=1504264",
        },
        {
            id = 1192311,
            score = 2,
            author = "simbic",
            text = "They are in the west part of Stromgarde Keep.",
            date = "2010-11-28T03:57:35-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26027#comments:id=1192311",
        },
        {
            id = 1396909,
            score = 2,
            author = "simorie",
            text = "Note: there is no apparent way to sneak into the \"back\" of the Keep where the Boulderfist are on foot, and if you're not careful you'll fall off and have to swim a bit, going out of your way to get back. You'll have to just go in the front of the Keep and fight your way to that southwest corner.",
            date = "2011-04-22T10:10:02-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26027#comments:id=1396909",
        },
    },
    [26028] = {
        {
            id = 1180606,
            score = 62,
            author = "ranu",
            text = "Most. Awesome. Quest text. EVER.\nYou even learn something that can be applied to real life; If you kill lots of people, you'll get ice cream!",
            date = "2010-11-24T07:42:26-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26028#comments:id=1180606",
        },
        {
            id = 1185077,
            score = 49,
            author = "599610",
            text = "A possible Bioshock refrence?  There is a little girl following you, and you are in a large daddy, a.k.a. a big daddy.",
            date = "2010-11-25T14:20:27-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26028#comments:id=1185077",
        },
        {
            id = 1250553,
            score = 36,
            author = "Toldry",
            text = "The alliance version of this quests' completion text goes as follows:\n\nThis is awkward...\n\nGood job out there with the robot. You caught me a little off guard. I didn't realize the little girl was so...\n\nSpecial...\n\nWell, whatever gets the job done, right? Am I right?\n\nProbably.\n\nHave some ice cream.",
            date = "2010-12-21T14:38:26-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26028#comments:id=1250553",
        },
        {
            id = 1194262,
            score = 35,
            author = "Alasdair",
            text = "Such a wonderful Bioshock influenced quest!\nHowever Clarissa scares me a bit. here are some of the whispers I saw while killing mobs during this quest:\nClarissa whispers: Make 'em sorry for hurting you, Mr. D!\nClarissa whispers: Break their bones!\nClarissa whispers: Hurt 'em some more! MORE!\nClarissa whispers: Yay!",
            date = "2010-11-28T19:23:01-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26028#comments:id=1194262",
        },
        {
            id = 1197534,
            score = 25,
            author = "Zuljid",
            text = "The ending speech of Overlord Krom'gar (http://www.wowhead.com/npc=41023) also made me chuckle for a while:\n\n*POSSIBLE SPOILER ALERT*\n\nI am - perhaps for the first time in my life - at a loss for words.\n\nI am really not sure where Clarissa (http://www.wowhead.com/npc=40907) even came from...",
            date = "2010-11-30T09:45:57-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26028#comments:id=1197534",
        },
    },
    [26029] = {
        {
            id = 1208414,
            score = 9,
            author = "Kciroj",
