    [26033] = {
        {
            id = 1186460,
            score = 308,
            author = "mortey",
            text = "Some written directions follow:\n\nFollow the road into Stromgard Keep. Make your immediate first right towards the Stromgard defenders. Make your first immediate right after that. Continue straight across the bridge you walk under when you first enter into the keep. Continue forward across the bridge until you reach a garden like area. Head towards the right of the chapel under a wooden fence of sorts. Continue straight into the Crypt. This is where the tomb is and where you get the quest item.\n\nHope that helps!",
            date = "2010-11-26T01:37:37-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26033#comments:id=1186460",
        },
        {
            id = 1179581,
            score = 36,
            author = "187343",
            text = "http://www.wowhead.com/maps?data=45:194572194584194596194607194619194631185642176642167644164633165617169601176594213594220601221613226625226638191557194541199530202516\n\nI made a map to where to find this, it was a little tricky for me.. follow the path starting at the road",
            date = "2010-11-23T23:22:44-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26033#comments:id=1179581",
        },
        {
            id = 1387481,
            score = 12,
            author = "785317",
            text = "For those with a flying mount, the crypt entrance is at 22.7, 60.7.",
            date = "2011-04-09T07:41:38-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26033#comments:id=1387481",
        },
        {
            id = 1205708,
            score = 7,
            author = "630585",
            text = "NOTE: If you have quite a big mount (like a kodo), when you enter Stromgarde and go under the bridge, you can jump along the left side of the bridge to get up it and skip quite a lot of mobs.",
            date = "2010-12-04T08:03:27-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26033#comments:id=1205708",
        },
        {
            id = 1889264,
            score = 1,
            author = "1094211",
            text = "I really appreciate your comment.  I was struggling trying to go to the left, not knowing the entrance to the bridge was to the right.  Awesome post.  Thanks.",
            date = "2013-08-22T16:18:53-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26033#comments:id=1889264",
        },
    },
