    [26038] = {
        {
            id = 1208355,
            score = 14,
            author = "278023",
            text = "All three objects are within the tower at different heights.\n\nThe phylactery was lowest , in my case, it spawned a Shaman and 2 Lords when I opened it. This ma have been coincidence or it may happen every time.\n\nProceeding vertically the other two objects are in cases higher in the tower. No additional spawns were encountered.",
            date = "2010-12-05T14:13:00-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26038#comments:id=1208355",
        },
        {
            id = 1367027,
            score = 9,
            author = "Spoonzilla",
            text = "The first one for me was the Phylactery.  It spawned a mauler and two shamans.\n\nNext was the Ember Agate, which spawned one mauler and one shaman.\n\nFinally, the Orb, which spawned one lord and one shaman.\n\nI was able to avoid aggro of the spawned mobs on the last two, but not on the first one.",
            date = "2011-03-14T18:33:45-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26038#comments:id=1367027",
        },
        {
            id = 1539123,
            score = 7,
            author = "657455",
            text = "It seems like there should be a follow up quest somewhere, but I can't find it.  Seems like only part of this quest line was updated for cataclysm.",
            date = "2011-10-09T16:46:39-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26038#comments:id=1539123",
        },
        {
            id = 1211906,
            score = 5,
            author = "169335",
            text = "I had trouble finding the footlocker the phylactory was in, namely because there was a dead ogre on top of it.  It's at the top of the first ramp.\n\nFor me, it spawned one Lord and one Shaman.",
            date = "2010-12-07T11:25:19-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26038#comments:id=1211906",
        },
        {
            id = 1922638,
            score = 2,
            author = "Xarnius",
            text = "The spawntimes are long on these.. Me and my friend opened them at the same time, but I couldn't loot the last one, because it had no loot. I abandoned the quest and picked them up again, and now I can't loot any of them.",
            date = "2013-12-01T08:58:50-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26038#comments:id=1922638",
        },
    },
    [26039] = {
        {
            id = 1368213,
            score = 26,
            author = "716234",
            text = "If you can't find the pathway up to the cave, try finding a tree at 71,41 and then face the hills. There will be your path up to the cave.  Watch out for kobold hiding behind bushes and ambushing you. There are plenty of kobold outside in the hills if you can't find enough in the caves.",
            date = "2011-03-16T06:27:58-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26039#comments:id=1368213",
        },
        {
            id = 1329665,
            score = 24,
            author = "753180",
            text = "Wow, the drop rate in this quest sucked. If I wanted to grind I'd grind, instead I'm questing, maybe someone should fix this.",
            date = "2011-02-10T00:54:25-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26039#comments:id=1329665",
        },
        {
            id = 1354209,
            score = 20,
            author = "yossarian",
            text = "Old school RNG!",
            date = "2011-03-01T13:41:44-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26039#comments:id=1354209",
        },
        {
            id = 2514792,
            score = 12,
            author = "onlymeaz",
            text = "This quest is kind of a pain but if you want to complete it, the best way to the cave (there are kobolds in various areas around the hillside and cave - you can always kill them off for the drop albeit the drop rate is somewhat low, although I think somewhat improved from prior): Go to the 1st tree at 71/41 then face East, walk East to the second tree at 76/41 still headed/facing East.  Keep heading East and the path turns towards the North and cave is at 78/38.  The path itself is not very obvious and there there are other path like areas that could throw you off.  The quest turn in is this crystal thing (think Dark Crystal) only pinkish in color.  Silly...but there ya go.",
            date = "2017-08-22T14:32:22-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26039#comments:id=2514792",
        },
        {
            id = 1256903,
            score = 10,
            author = "718591",
            text = "Work your way toward back of cave since that is where the turn in is.  Path up starts around [74, 41] The cave entrance is at [77.6, 37.1]\n\nInside cave take left path which will wrap around to ledge with crystal.  Killed about 30 to get the 12 motes.",
            date = "2010-12-24T15:53:30-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26039#comments:id=1256903",
        },
    },
    [26041] = {
        {
            id = 1257101,
            score = 12,
            author = "718591",
            text = "Cresting key [61.67, 30.45]\nThundering key [46.43, 52.17]\nBurning key [18.84, 30.84]\n\nAt the centers of the circles of binding.  Turn in is at [30, 59]",
            date = "2010-12-24T18:23:43-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26041#comments:id=1257101",
        },
        {
            id = 1534041,
            score = 4,
            author = "Pypode",
            text = "I didn't see the little rock with the quest mark over it at Circle of Inner Binding. Yeah. I know. But I was fixated on the center floating pillar. Little rock looks like a short summoning stone, of course with a quest mark over it.\nsigh.",
            date = "2011-10-03T14:56:04-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26041#comments:id=1534041",
        },
        {
            id = 1244125,
            score = 2,
            author = "737780",
            text = "The last key which is the Burning Key is on the other side of Arathi Highlands. its eadier to go to Hammerfall and fly to Galen's Fall then get the Burning Key the place to turn the quest in is not far from there.",
            date = "2010-12-18T20:12:34-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26041#comments:id=1244125",
        },
        {
            id = 1819521,
            score = 1,
            author = "924646",
            text = "If you didn't buy a mount before this one, it'll be an all day walk thru the highlands. Plan on bein dead at least once also. All the stones are guarded by multi-mobs n they're kinda testy lettin these things go. But, if you have patience and a good amount of dps, you'll do fine. 29 Dwarf Rogue. (with mount lol) Peace!",
            date = "2013-03-01T04:19:28-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26041#comments:id=1819521",
        },
        {
            id = 1243981,
            score = -5,
            author = "737780",
            text = "They all are around stone hinges and have elementals guarding them. Use quest helper to find the locations.",
            date = "2010-12-18T18:54:56-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26041#comments:id=1243981",
        },
    },
    [26042] = {
        {
            id = 1262948,
            score = 23,
            author = "toxoplasmosis",
            text = "You need to find and slay the once-elite rock elemental that used to wander the whole zone with his little kobold buds and is now, thankfully, stationary and alone: Fozruk (http://www.wowhead.com/npc=2611/fozruk)\n\nOnce you get the Rod of Order (http://www.wowhead.com/item=4469) from him, you turn it in to the Keystone (http://www.wowhead.com/object=2688), at which point this big ugly jerk (http://www.wowhead.com/npc=2763) spawns and tries to smoosh you. Rude! Kill him a lot.\n\nAfter you deal with that unpleasant business, you will notice that the Stone of Inner Binding (http://www.wowhead.com/object=2702) has a quest available:\n\nHorde: Myzrael's Tale (http://www.wowhead.com/quest=26911) - turn in to Zaruk (http://www.wowhead.com/npc=2787) at Hammerfall\nAlliance: Myzrael's Tale (http://www.wowhead.com/quest=26346) - turn in to Skuerto (http://www.wowhead.com/npc=2789) (what a name!) at Refuge Point\n\nWhen you turn in Myzrael's Tale, you'll get to find out that, probably not for the first time, you did a bad, bad thing.\n(srsly, Zenn's Bidding (http://www.wowhead.com/quest=488), anyone? yes, we were naïve to trust someone with a last name like Foulhoof, but he seemed so sincere! and they probably deserved it anyway. also, the sun was in my eyes...yeah)",
            date = "2010-12-27T23:41:00-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26042#comments:id=1262948",
        },
        {
            id = 1257105,
            score = 10,
            author = "718591",
            text = "When turned in an elemental lvl 29 spawns.\n\nA nearby rock gives you a quest to talk to Zaruk in Hammerfall for Horde",
            date = "2010-12-24T18:30:56-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26042#comments:id=1257105",
        },
        {
            id = 1186366,
            score = 3,
            author = "567746",
            text = "The quest changed a bit in 4.0.  He's now standing at 48,57.  Go kill him, then come back and turn in the quest.",
            date = "2010-11-26T00:38:12-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26042#comments:id=1186366",
        },
        {
            id = 1195330,
            score = 3,
            author = "699415",
            text = "So no followup?",
            date = "2010-11-29T09:37:23-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26042#comments:id=1195330",
        },
        {
            id = 1502309,
            score = 3,
            author = "821910",
            text = "shake the very foundations of the earth\n\nHahahahaha, NICE foreshadowing of bad shiznit for those of us who remember just exactly how the whole 'this kingdom shall fall' speech in that one WCIII cinematic runs. Not quiiiiiiiiiiiiiite the same context, yeah, but that phrase as a portent of 'oh crap' is a nice little grin-and-elbow-nudge.",
            date = "2011-08-24T08:44:31-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26042#comments:id=1502309",
        },
    },
    [26043] = {
        {
            id = 1317512,
            score = 24,
            author = "725354",
            text = "This quest cannot be started until you complete https://www.wowhead.com/quest=26004.",
            date = "2011-01-31T21:53:52-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26043#comments:id=1317512",
        },
        {
            id = 1355899,
            score = 23,
            author = "Novawolf",
            text = "He ate my fire totem.\n\nHe ate...\nMy fire totem.\n\nMight be because it's 2 AM, but that was the funniest thing I'd seen all night, and it saved my life. I was preparing for the fight to get harder when he devoured me, but he snatched up my fire totem and wandered off with it, allowing me to finish the job.",
            date = "2011-03-03T03:17:06-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26043#comments:id=1355899",
        },
        {
            id = 1580309,
            score = 19,
            author = "LuchadorRex",
            text = "For those who are curious and are at level cap, to obtain this quest, you must go to Ashenvale and pick up the quest https://www.wowhead.com/quest=25945.  Ride the wagon, do the quests at The Fold and once you get sent to Krom'gar's Fortress, you'll be able to see the Quest on the Sign.",
            date = "2011-11-25T04:51:04-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26043#comments:id=1580309",
        },
        {
            id = 1189260,
            score = 8,
            author = "94091",
            text = "Does a move called that deal 5% of health per second. Fyi, You can still attack him while inside his mouth. I didn't realize this when i was 27, when I almost killed him. He hits for about 100-120 physical.",
            date = "2010-11-27T01:03:34-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26043#comments:id=1189260",
        },
        {
            id = 1231934,
            score = 8,
            author = "726160",
            text = "I did this as a Level 28 hunter and had no problems at all.  I didn't even realize he could 'eat' you!  Extremely soloable, I don't think I took a single hit from him and my pet still had 1/3 or so health left.",
            date = "2010-12-14T01:01:50-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26043#comments:id=1231934",
        },
    },
    [26044] = {
        {
            id = 1151576,
            score = 104,
            author = "432258",
            text = "Entrance to cave at 66.60\n\nright at the bottom of the path from the fortress",
            date = "2010-10-23T21:07:26-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26044#comments:id=1151576",
        },
        {
            id = 1533926,
            score = 39,
            author = "44374",
            text = "There are two paths that lead up to the fortress - the entrance to the mine is between them.\n\nLook down from flightmaster and you'll see it.",
            date = "2011-10-03T11:10:58-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26044#comments:id=1533926",
        },
        {
            id = 1188500,
            score = 24,
            author = "234469",
            text = "The cave you want is directly below the fortress, and it is not marked on the map as a cave. Don't go to the cave marked on the map. The one you want has a bunch of Horde banners hanging outside and inside it.",
            date = "2010-11-26T18:17:14-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26044#comments:id=1188500",
        },
        {
            id = 1512074,
            score = 12,
            author = "Jdekik",
            text = "For those without coords this is where you want to go >>> Entrance (http://www.wowhead.com/maps?data=406:665615)",
            date = "2011-09-07T12:38:04-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26044#comments:id=1512074",
        },
        {
            id = 1186384,
            score = 8,
            author = "wuphonsreach",
            text = "Note that the current WoWHead link to part 4 is partially incorrect.  When you go into the mine, you will pickup an additional (3) quests.\n\nBetween a Rock and a Hard Place (http://www.wowhead.com/quest=26046)\nI Got Your Parts Right Here... (http://www.wowhead.com/quest=26045)\nAnd That's Why They Call Them Peons... (http://www.wowhead.com/quest=26047)\n\nThe mine is very large and easy to get lost in.  There is an alliance side and a horde side that offer similar quests.  The 3 horde-side quests all take place within throwing distance of the 3 quest NPCs.",
            date = "2010-11-26T00:48:31-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26044#comments:id=1186384",
        },
    },
    [26045] = {
        {
            id = 1303154,
            score = 15,
            author = "742103",
            text = "I had a hard time locating any of these. At first, I went to the right to kill Elementals and talk to Peons for the other two quests. I never saw a spare part lying around.\n\nThen I went to the left of the quest givers and found 6 spare parts right away. Just thought I'd mention that, in case they only spawn on that side of the cave. Or maybe these items just have an insanely long re-spawn rate? Either way, there are no enemies to fight if you go left, so that should help you along.",
            date = "2011-01-21T14:07:01-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26045#comments:id=1303154",
        },
        {
            id = 1196725,
            score = 10,
            author = "Rauven",
            text = "I'm choosing the third option, do nothing. So far, so good.\n\nI had to give a loud laugh when i came to this. You gotta hand it to Blizzard, reading the quests is getting funnier by the patch!",
            date = "2010-11-29T23:21:57-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26045#comments:id=1196725",
