    [26051] = {
        {
            id = 1190735,
            score = 188,
            author = "711071",
            text = "You have to be wearing the goggles they should be in your inventory.",
            date = "2010-11-27T14:53:06-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26051#comments:id=1190735",
        },
        {
            id = 1192042,
            score = 57,
            author = "SuperBurritoz",
            text = "Let me save you 30 minutes for those of you blowing through quests- EQUIP THE GOGGLE HE GIVES YOU.\n\nI totally blew this the fist time around before figuring it out.",
            date = "2010-11-28T01:16:18-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26051#comments:id=1192042",
        },
        {
            id = 1666960,
            score = 34,
            author = "Hvitur",
            text = "Equip the goggles and watch your minimap. As an 85 herbalist going through old quests for Loremaster, I was ignoring the yellow dots on my minimap because I thought they were stranglekelp or some other herb, and ended up swimming around for a while before realizing the yellow dots are the treasure. Derp!",
            date = "2012-05-14T16:40:36-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26051#comments:id=1666960",
        },
        {
            id = 1269433,
            score = 22,
            author = "zapr",
            text = "Also watch out for going into the wetlands territorial water and losing your swimming buff.\n\nMaybe a warning would be good there, Blizz?\n\nPS: thanks for the tips to equip the goggles!",
            date = "2010-12-31T09:09:25-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26051#comments:id=1269433",
        },
        {
            id = 2569325,
            score = 15,
            author = "sixfootgiant",
            text = "#1 equip your goggles, do not forget to do this or you cannot see the nodes. The nodes appear as a yellow dot on your minimap. It is not Stranglekelp. ;)\n\n#2 do not zone into the Wetlands, you will lose your Blackwater Boon buff (water breathing and swim speed.)\n\n#3 this quest is awful, especially now because of CRZ. There is so many people fighting for one node and they are NOT shareable. The best way I completed it was to sit in one spot and wait for the node to respawn. They all have designated spawn points and aren't random. It took me about 10 minutes to complete. It took me 5-10 minutes to collect the first node by trying to swim faster before someone else got to it.\n\nGodspeed.",
            date = "2018-05-22T00:23:07-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26051#comments:id=2569325",
        },
    },
    [26052] = {
        {
            id = 2555508,
            score = 14,
            author = "dopeyslowpoke",
            text = "Note that only ONE person (yes, even if they're not in your party) can \"Speak to Shakes\". So outdated, so annoying. There were a line of people waiting for the yellow ? to appear above Shakes's head so we can turn in the quest and progress.",
            date = "2018-02-28T19:01:10-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26052#comments:id=2555508",
        },
        {
