    [26055] = {
        {
            id = 1202862,
            score = 9,
            author = "567037",
            text = "This quest now (post Shattering) gives you a swim speed/underwater breathing buff that lasts for 30 minutes.\n\nHowever, be careful you don't stray too far in the ocean because if you go into a different zone (like I did going after some stranglekelp), you will LOSE the buff and the NPC's will not grant it to you again unless you abandon the quest and re-accept it.",
            date = "2010-12-02T19:44:00-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26055#comments:id=1202862",
        },
        {
            id = 1687782,
            score = 3,
            author = "Fluffmeister",
            text = "I died in the water in this quest, and when my ghost returns to it, he walks on water and can't go into the ocean to resurrect. I can see the coffin symbol, but can't get to it. Any ideas?",
            date = "2012-07-13T20:14:35-05:00",
