    [26068] = {
        {
            id = 1184071,
            score = 87,
            author = "636906",
            text = "Coordinates for the quest spot is (73,78)  but you'll have to go around all the way towards east. The start of the path is located at  (79,81) near a bunch of Krom'gar Marauders fighting with Grimtotem Mercenaries.",
            date = "2010-11-25T06:56:15-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26068#comments:id=1184071",
        },
        {
            id = 1190288,
            score = 35,
            author = "cribby",
            text = "There's a horde banner at the Unearthed Grounds, 73, 78. This is where you release the Kobold Army. To get there - There's a nice safe path in Greatwood Vale - 78, 81.\n\nFrom Camp Aparaje - or where you enter Stonetalon from the Barrens - it's called Stonetalon Pass. As you continue, it turns into Greatwood Vale. Eventually you'll hit Camp Aparaje.\n\nThere's a path to the right that leads you thru a bunch of alliance/horde battling. Northeast of the fighting is a path that leads you to the Unearthed Grounds. Keep following the path(s) up and eventually you'll reach the banner.",
            date = "2010-11-27T11:26:50-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26068#comments:id=1190288",
        },
        {
            id = 1251972,
            score = 12,
            author = "325700",
            text = "The kobold army will attack Alliance players, even if they are not pvp flagged haha :)\n\nThere was this NE fighting some mobs near the Horde banner, when I used the horn, all the kobolds spawned and killed him in no time ... priceless :)",
            date = "2010-12-22T07:24:04-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26068#comments:id=1251972",
        },
