        {
            id = 1843833,
            score = 9,
            author = "Droxie",
            text = "So a little fun fact:\n\nGetting too close to the Alliance encampment will result in you getting one-shotted by the guards and taking a durability hit. When doing the quest, make sure to not go past the line of Alliance soldiers after the Kobolds have been summoned.\n\nThe guards have an uncanny sense of level thirties.",
            date = "2013-04-16T13:10:33-05:00",
