    [26069] = {
        {
            id = 1383587,
            score = 16,
            author = "157775",
            text = "If you've previously completed Clear The High Road (http://www.wowhead.com/quest=24504), this breadcrumb quest into Southern Barrens will not be obtainable.",
            date = "2011-04-04T02:01:36-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26069#comments:id=1383587",
        },
        {
            id = 2004589,
            score = 13,
            author = "1361840",
            text = "You can do both this quest and https://www.wowhead.com/quest=28549.  To do that you need to:\n1. Get the Warcief's Command quest and hand that in FIRST (it won't work the other way around).\n2. After you hand it in, don't accept any further quest from Nura Pathfinder.\n3. Now you can go to Witch Doctor Jin'Zil and get this quest.",
            date = "2014-09-20T16:31:15-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26069#comments:id=2004589",
        },
        {
            id = 2495430,
            score = 6,
            author = "1764127",
            text = "She is located at 31,13 in the Southern Barrens.  Path up begins at 30,10.  Because I had no Southern Barrens flight paths yet, I had to fly to Crossroads, then take the west road out, then walk around the north side of the giant ravine. Hunters Hill is the closest flight path. So, if you already have it, that's much faster.",
            date = "2017-05-19T23:44:54-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26069#comments:id=2495430",
        },
        {
            id = 1645113,
