    [26074] = {
        {
            id = 1196786,
            score = 13,
            author = "220871",
            text = "In order to escort the bomb you have to actually ride it to the next base.  So just get close enough until it allows you to jump in.",
            date = "2010-11-30T00:00:49-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26074#comments:id=1196786",
        },
        {
            id = 2435623,
            score = 5,
            author = "Kraelyn",
            text = "The rope ladder and bomb for this quest disappeared before I could complete it. I've tried abandoning the quest and restarting it. I've even left the zone and come back. Nothing seems to be working. Any advice?",
            date = "2016-10-27T10:01:15-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26074#comments:id=2435623",
        },
        {
            id = 1394240,
            score = 3,
            author = "50527",
            text = "I totaly missed the balloon at the quest starting point and went to the Sludgewerks first... there is a balloon there too, which lights up, but that's it... Then i read back the quest :(.\nTook the balloon at Krom'gar Fortress (66.7,63.5) , that one goes to the Sludgewerks...\nAfter landing, go to Jibbly Rakit (npc=42033) (52.9,39.2), he will let you do 2 other quests before you can go onto theFinal Delivery (quest=26077)  (with the balloon again)",
            date = "2011-04-18T12:34:37-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26074#comments:id=1394240",
        },
        {
            id = 1820272,
            score = 1,
            author = "1102692",
            text = "Do note that you need to ride in the Hot Air Balloon that is INITIALLY AT Krom'gar. Even though the map may tell you to go to the flightmaster, you need to fly in the air baloon.",
            date = "2013-03-03T01:39:30-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26074#comments:id=1820272",
        },
        {
            id = 2538557,
            score = 1,
            author = "Wyr3d",
            text = "BE AWARE:\n\nThis quest is bugged, and has a chance for the rope ladder to either vanish too quickly, or not appear at all. The devs have known about this issue since 2013 (see links below) but as yet the quest is NOT fixed. If the quest is bugged for you, submit a ticket asking that your character have the quest flagged as \"completed\" so you can carry on with the zone story-line. Some people have reported that the rope ladder has a chance to appear \"after the next day\" (possibly after maintenance?) so if your ticket isn't answered quickly, you may want to check if this has happened for you \"the next day\".\n\nPlease note, this issue also applies to the Alliance counterpart, Commandeer That Balloon (http://www.wowhead.com/quest=25652/commandeer-that-balloon)\n\nlinks:\n\nUS SERVERS (2013 - current): https://us.battle.net/forums/en/wow/topic/8874477804?page=1\n\nEU SERVERS (May 2017 - current): https://eu.battle.net/forums/en/wow/topic/17615631716\n\nAddendum: Not entirely sure what fixed this, but I played on another char for a couple hours, got to the same zone, and during the Mr D quest, the balloon's rope appeared. After completing the Mr D quest on this alt character, I quickly switched to bugged character, and the rope was still visible - so I grabbed it, and voila. Sorted.\n\nPlease note - this quest is still bugged, but can fix itself apparently, provided some unexplained circumstances occur. My guess is, it's something to do with the volume of characters questing in the area. Last time I went through here I had no issues",
            date = "2017-12-03T03:23:51-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26074#comments:id=2538557",
        },
    },
