    [26077] = {
        {
            id = 1690763,
            score = 17,
            author = "cjmarsh",
            text = "Balloon is hanging out at that base in the middle of the lake.",
            date = "2012-07-21T16:56:32-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26077#comments:id=1690763",
        },
        {
            id = 1195895,
            score = 14,
            author = "111593",
            text = "Blizzard is getting into politics now!\n\nThe orc and tauren, during their dialogue, are complaining about whether the night elves actually do house \"Weapon's of Mass Destruction\".\n\nMiddle East conflict anyone?\n\nI found this quest very humorous and witty on Blizzard's part",
            date = "2010-11-29T14:24:28-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26077#comments:id=1195895",
        },
        {
            id = 1210505,
            score = 10,
            author = "Deth",
            text = "***SPOILERS***\n\nHigh Chieftain Cliffwalker says: Your claims are outrageous, General.\nHigh Chieftain Cliffwalker says: The only thing you will find at Thal'darah Grove are terrified young druids. They have no weapon of mass destruction.\nGeneral Grebo says: Careful, tauren, your words could be construed as treason.\nGeneral Grebo says: My scouts have informed me that the grove holds a powerful weapon. A weapon that the Alliance will use against us if they are not stopped.\nGeneral Grebo says: Furthermore, I am here by the authority of Overlord Krom'gar, who was himself appointed by our Warchief, Garrosh Hellscream. You will do his bidding or suffer the consequences.\nHigh Chieftain Cliffwalker says: I have sent my boy to Thal'darah Grove to fetch you proof. You will soon see that they pose no threat to us.\n\nWhen you are about to finish the quest General Grebo says this:\n\nChieftain Cliffwalker and his tauren seek to commit treason against the Horde! They claim that the ancient tree at the heart of Battlescar Valledy is merely a school for druids. They are blind to the fact that desperate measures are taken during was time. My scouts have assured me that the night elves hide a weapon of great power within that tree. We're going to end this now!",
            date = "2010-12-06T16:12:33-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26077#comments:id=1210505",
        },
        {
            id = 5364596,
            score = 3,
            author = "DaemoniKira",
            text = "...has anyone else noticed that the 2 little elevators in Cliffwalker Post --off the narrow, wooden piers right next to where the hot air balloon landed--  are functioning seemingly by pure magic? There's no pulley system, no balance system (even though it looks like it would be, with one elevator descending at the same rate exactly opposite of when/where the other is ascending), not even any cables or poles or literally anything. The elevators are just totally free and unsupported, floating up and down.\n\nI know there's magic in the game, but this is like, arcane/Kirin Tor/Dalaran -esque magical f**kery. And I've never seen Taurens use this kind of magic.\n\nHere, (https://imgur.com/a/XvBHDmU) I uploaded a couple screenshots of what I'm referring to.\nDon't mind the moose, she's sightseeing. (But she's just as perplexed as I am about the elevators...)",
            date = "2022-04-27T23:08:31-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26077#comments:id=5364596",
        },
    },
