    [26094] = {
        {
            id = 1204990,
            score = 58,
            author = "405756",
            text = "Just did this quest. Logged out  (not exit all the way out) and back in and it worked.\n\nbomber is at 70,18\n\nYou mean 77, 18. At the northern end of the runway, below the \"flight path\".",
            date = "2010-12-03T21:14:03-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26094#comments:id=1204990",
        },
        {
            id = 1182623,
            score = 28,
            author = "679915",
            text = "Is this quest bugged for anyone else? Kept getting the 'You are busy and can't use the taxi service right now' error message when I tried to board the Repaired Bomber...",
            date = "2010-11-24T18:41:02-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26094#comments:id=1182623",
        },
        {
            id = 2122442,
            score = 20,
            author = "391205",
            text = "Decided to roll a new alt since the heirloom tab came out today, but hit a brick wall with this quest.  You hop in the plane, it goes a few feet, then ejects you.\n\nCostumes granted from toys don't seem to fix this, nor did relogging and disabling addons.\n\nWhat did work was I just ran to where you are supposed to bomb them, but dispatched them 1 at a time with my sword and still was able to complete the quest.",
            date = "2015-02-25T04:51:39-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26094#comments:id=2122442",
        },
        {
            id = 2465504,
            score = 12,
            author = "ciocolici95",
            text = "As of today (7.1.5), the quest's still bugged.\n\nWhile most of you might already know how to workaround this bug, it might still be useful to say that the \"workaround\" still works in 7.1.5.\n\nI took the quest, went to the plane. clicked on it, got the \"busy, cannot use a taxi at this time\". Went behind it, clicked again and got the same error. Then logged out of the character, logged in back and clicked it and it now worked. Tho it looked like I was really riding a \"taxi\", so it might be a good idea to put the item on your spell bar to use it easier.\n\nHope it helped. Thumb up for people to see!",
            date = "2017-01-21T10:00:12-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26094#comments:id=2465504",
        },
        {
            id = 1267910,
            score = 10,
            author = "Pypode",
            text = "12/30 Quest working fine. Walk away from Commamder Stonebreaker; bomber is to the right. You make two circuits, plenty of time to kill all you need. You don't control bomber, only your view from the air.",
            date = "2010-12-30T12:05:40-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26094#comments:id=1267910",
        },
    },
