        },
        {
            id = 1544253,
            score = 21,
            author = "Qoko",
            text = "Take note that this quest ends in the IF Throne Room for a reason, on your way out https://www.wowhead.com/npc=1959 offers you the entry quest to Loch Modan. I did that quest before completing this chain, and had to fly to the quarry and walk.",
            date = "2011-10-16T08:52:57-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26118#comments:id=1544253",
        },
        {
            id = 1255360,
            score = 17,
            author = "724683",
            text = "this quest is part of a chain and does not become available until after you complete Grimaxe's demise.",
            date = "2010-12-23T18:33:49-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26118#comments:id=1255360",
        },
        {
            id = 1183800,
            score = 13,
            author = "196807",
            text = "When you use the quest item on Ambassador Slaghammer:\n\nAmbassador Slaghammer says: I go willingly, mage. My purpose in my master's plan is fulfilled.\n\nWhen you bring him to the High Seat:\n\nIronforge Guard says: Glad to see that Dark Iron scum is finally getting what he deserves!\nIronforge Guard says: Quiet! Moira's in a foul mood and if she hears you, she'll have your head...\n\nAfter Ambassador Slaghammer walks in:\n\nMoira Thaurissan says: If we were in Shadowforge City, I would have you tossed into the Ring of Law for your transgressions, Ambassador. The darkest dungeons of Ironforge will have to do for now.\nAmbassador Slaghammer says: Do as you will with me. I am not afraid. That halfbreed runt will never be my emperor! Long live Twilight's Hammer!\n\nA guard then walks over from the side:\n\nIronforge Guard says: I'll escort you to your new 'accomodations', Your Excellency.\n\nAnd escorts him off to the side before despawning.",
            date = "2010-11-25T03:50:33-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26118#comments:id=1183800",
        },
        {
            id = 1926405,
            score = 13,
            author = "67904",
