    [26131] = {
        {
            id = 1256963,
            score = 16,
            author = "6423",
            text = "This quest offers a free ride to Loch Modan, compared to Hero's Call: Loch Modan! (http://www.wowhead.com/quest=28567) which DOESN'T.",
            date = "2010-12-24T16:39:25-06:00",
