        },
        {
            id = 1181161,
            score = 12,
            author = "Rhynchelma",
            text = "This quest is picked up from William Pestle (http://www.wowhead.com/npc=253).\n\nThis seems to be available after handing in Kobold Candles quest (http://www.wowhead.com/quest=60) and not before.\n\nThe next quest in the chain, Young Lovers (http://www.wowhead.com/quest=106) was available before handing in Kobold Candles quest (http://www.wowhead.com/quest=60) .",
            date = "2010-11-24T10:49:00-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26150#comments:id=1181161",
        },
        {
            id = 2189398,
            score = 6,
            author = "Taraezor",
            text = "A long time ago in Vanilla WoW players came across https://www.wowhead.com/npc=251 and https://www.wowhead.com/npc=252 in Elwynn Forest. A sad mini quest chain with no real closure, originally commencing with https://www.wowhead.com/quest=106. Finally, in Warlords of Draenor we meet up again with https://www.wowhead.com/npc=88126 and https://www.wowhead.com/npc=84795. Now married and living happily ever after. Thank you Blizzard!",
            date = "2015-06-01T08:10:53-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26150#comments:id=2189398",
        },
