            score = 6,
            author = "806774",
            text = "Ok did this on my level 57 gnome mage arcane, the trick on the mobs is NOT to loot after the kill, doesn't respawn and go slowly...lol gl once you get the transporter not so bad going back and forth.",
            date = "2011-06-15T11:36:55-05:00",
