        {
            id = 1179704,
            score = 5,
            author = "664880",
            text = "He is at the back of Serpent's Coil, right under Nethergarde Keep. Eventually you will top a rise in the mine and see a small hut; that's Kasim's camp.",
            date = "2010-11-24T00:14:56-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26157#comments:id=1179704",
        },
        {
            id = 1411038,
            score = 3,
            author = "146544",
            text = "Anyone reported this quest: Kasim Sharim. If for the quest creator this is a sick joke. probably same one who wanted to drop felcloth. They must hate cloth toons.",
            date = "2011-05-06T03:51:40-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26157#comments:id=1411038",
        },
        {
            id = 1367302,
            score = 2,
            author = "228976",
            text = "As of March 14 2011, this quest is extremely hard for a cloth wearing class of appropriate level for the zone to do solo because the respawn rates are absolutely ridiculous.\nI tried 4 times with my mage and could not get past the first bend in the tunnel because the mobs behind me were respawning before I'd killed the ones in front of me. Every time I ended up with 5-7 mobs on me.\n\nsuggestions? lol",
            date = "2011-03-15T02:56:28-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26157#comments:id=1367302",
        },
    },
    [26158] = {
        {
            id = 1445662,
            score = 7,
            author = "LadyFox",
            text = "https://www.wowhead.com/npc=42298 is looking directly at the teleporter that stands a couple feet away. Just use it and then outside the one there, too.\nYou can use it afterwards for teleporting in and out for the following quests.",
            date = "2011-06-20T13:38:42-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26158#comments:id=1445662",
        },
        {
            id = 1643952,
            score = 3,
            author = "mk657",
            text = "if you are looking at the front of the hut, there are crates/prisions to the right. behind those is a red crystal. that is a portal. click that and it should transport you to Kasim. he will be located behind you. that is the quickest way to get to him, unless you want to kill all the guys in the front of the hut.\n\nit took me three tries to locate him before i found the portals. and using the portals is another quest he gives you as well.\n\nbest of luck!",
            date = "2012-03-24T11:08:42-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26158#comments:id=1643952",
        },
        {
            id = 1804385,
