    [26161] = {
        {
            id = 1256647,
            score = 100,
            author = "164835",
            text = "Ok....if any of you out there are like me & don't really read the quest log, here's what I threw together for you:\n\nLegs:   Cave entrance - 45.8 x 38.7  Very small cave, only 1 ogre in front of it.  Chest is right inside, you can't miss it.\n\nTorso:   Cave entrance - 41.7 x 33.3 - Standard cave set up - steer to your left -  It's in the back, of course.  Coords there are 40.0 x 37.1\n\nHead:   Cave entrance - 45 x 31 - Another standard cave set up - in the back.  Coords there are 46.7 x 27.0\n\nHope this helps someone else out.",
            date = "2010-12-24T12:45:30-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26161#comments:id=1256647",
        },
        {
            id = 1412592,
            score = 26,
            author = "Sunreaver",
            text = "Coordinates are good, but not all of us have 'em. Here's a more visual description for those that don't. If you're coming down into the ogre area from directly north, the first cave (head) is on your left at the bottom of the large mountain (the map area is 'Rise of the Defiler'). Inside, go straight back at the fork and the chest is right up ahead at the back, with only 2 or 3 ogres in the way.\n\nAs you're coming out of the first cave, the second cave (legs) is straight ahead with a couple of ogres between them. It's a small one-room cave, and the chest is right there. When you're at the entrance, the map area should show 'Bloodmaul Post'.\n\nWhen you come out of the second cave, look across the ogre area to the west. Just to the right of the path leading upwards into the mountains is the third cave (torso). The map area at the entrance shows 'Bloodmaul Furnace'. This cave is a little unique - when you come in, head down the ramp on the left side and hug the left wall around into a little niche, which is where the chest is at. There are 3-4 ogres along the way.\n\nHope that helps.",
            date = "2011-05-07T23:29:30-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26161#comments:id=1412592",
        },
        {
            id = 1205471,
            score = 10,
            author = "Angaurwen",
            text = "This quest thoroughly threw me when I read it.\nMaybe it's a bug, maybe it's only on my screen, but Loramus is standing right there in the cave next to the gnome.  I can talk to him.  And I'm being told to go collect his head from a different cave?\nSo trippy.",
            date = "2010-12-04T04:11:49-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26161#comments:id=1205471",
        },
        {
            id = 1626474,
            score = 5,
            author = "640084",
            text = "Reminds me of the old Beatles song, Help! (http://www.youtube.com/watch?v=TU7JjJJZi1Q)",
            date = "2012-02-14T17:37:51-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26161#comments:id=1626474",
        },
        {
            id = 1195949,
            score = 4,
            author = "388145",
            text = "the map is a little off.\n\nThe Legs are in the cave at 46.39\n\nThe Torso is in the cave at 42.34, to the left in the next cave.\n\nThe Head is in the cave at 45.30, to the left.\n\nthe caves are within sight of each other.",
            date = "2010-11-29T14:52:59-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26161#comments:id=1195949",
        },
    },
    [26162] = {
        {
            id = 1770769,
            score = 60,
            author = "283660",
            text = "If you are a warlock in Metamorphosis or Dark Apotheosis form during this quest, you can understand what he says in demonic.\n\nThe first thing he yelled for me was \"Holy moley!\"\n\nIn a later part of the quest-chain he yells \"The pain! Oh, sweet sassy molassey!\"\n\nGotta love Blizzard's humor.",
            date = "2012-11-28T23:47:03-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26162#comments:id=1770769",
        },
        {
            id = 1246870,
            score = 51,
            author = "herlzinger",
            text = "The path leading to the Altar of Storms is due south of the cave entrance on your map (http://www.wowhead.com/maps?data=4:405361).  The path is guarded by two Shadowsworn Enforcers (http://www.wowhead.com/npc=6007).\n\nWhen you get to the Altar, there are some gigantic bones with a little altar on top of those bones.  When you roll your mouse over the altar, you should get a cogwheel that you can right click.  This will begin the ritual.\n\nDuring the ritual, Shadowsworn Obstructors (http://www.wowhead.com/npc=41191) with very low hit points spawn all around the altar and start channeling a spell called Disrupt Ritual  (http://www.wowhead.com/spell=77129)which will draw a green lightning bolt from the NPC to Loramus.  Kill the demons before they finish channeling and you will complete the quest objective.\n\nThe quest is then turned in back at the Serpent's Coil near Kasim Sharim (http://www.wowhead.com/npc=42298).",
            date = "2010-12-20T00:45:10-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26162#comments:id=1246870",
        },
        {
            id = 1492083,
            score = 29,
            author = "Cantras",
            text = "Can't find Loramus? he's under the tent. If your camera angle's high enough, his name and ? are hidden, and that makes you feel a bit noobish when you come here looking for him.",
            date = "2011-08-10T23:05:19-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26162#comments:id=1492083",
        },
        {
            id = 1488925,
            score = 24,
            author = "181893",
            text = "It's worth noting that, if you're really up on your Azeroth geography, there are at least two Altars of Storms. If you go to the one by Blackrock Mountain, you will not be able to complete this quest. STAY IN the BLASTED LANDS.",
            date = "2011-08-06T21:41:23-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26162#comments:id=1488925",
        },
        {
            id = 1310455,
            score = 19,
            author = "717175",
            text = "Seems like Loramus is quite flexible.",
            date = "2011-01-26T09:00:08-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26162#comments:id=1310455",
        },
    },
