    [26166] = {
        {
            id = 2536724,
            score = 12,
            author = "StrictMode",
            text = "Alliance Notes\n\nThis series of quests is much longer than what's listed here, and may have been reworked somewhat. You will not be able to get this quest just by talking to Grimeo.\n\nStart with https://www.wowhead.com/npc=9540 and do these 4:\n\nhttps://www.wowhead.com/quest=25715\nhttps://www.wowhead.com/quest=25709\nhttps://www.wowhead.com/quest=25708\nhttps://www.wowhead.com/quest=25714\n\nThen you'll talk to https://www.wowhead.com/npc=5385 and do:\n\nhttps://www.wowhead.com/quest=25716\nhttps://www.wowhead.com/quest=26157\n\nWhich sends you to https://www.wowhead.com/npc=42298. You'll be on a long quest series starting with https://www.wowhead.com/quest=26172 and https://www.wowhead.com/quest=26158. Eventually Kasim will give you a rune to take to Grimeo in https://www.wowhead.com/quest=26163. At that point Grimeo will finally talk to you.\n\nEventually this will lead you to https://www.wowhead.com/quest=26162 and https://www.wowhead.com/quest=26171 via the rest of Kasim's quests.",
            date = "2017-11-24T10:59:22-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26166#comments:id=2536724",
        },
        {
            id = 1209402,
            score = 5,
            author = "neogia",
            text = "Reminds me of one of my favorite childhood movies, Romancing the Stone (http://www.imdb.com/title/tt0088011/). The quest text really has no relation to the story of the movie, but it still rhymes :D",
            date = "2010-12-06T01:30:14-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26166#comments:id=1209402",
        },
        {
            id = 1493943,
            score = 3,
            author = "748088",
            text = "Is this a Draenei-only quest? I'm after rep with a BE but Grimeo is minimally conversational and doesn't want to offer up any quests. Did I miss a prequest?",
            date = "2011-08-13T09:00:55-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26166#comments:id=1493943",
        },
    },
