    [26169] = {
        {
            id = 3140423,
            score = 12,
            author = "Timuri",
            text = "As of today, this quest is bugged.  At the very least it is on the Winterhoof server.  Trying to interact with the Head of Grol brings up the error message that the item is already in use.  I had tried logging out and back in, exiting the game entirely, and abandoning and retaking the quest.  The normal troubleshooting steps.\n\nIn the end, I found that there were three other people (just on Ally side) in the zone having the same issue.  Not sure if any Horde players were having the same issue, as I didn't run into any Horde pandas to translate.",
            date = "2019-07-16T20:34:25-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26169#comments:id=3140423",
        },
        {
            id = 1890553,
            score = 10,
            author = "Vishine",
            text = "Also, to get to this quest you have to get the hero's call quest for blasted lands, he will then give you the https://www.wowhead.com/quest=25710 questline, then do the quests in the keep ( https://www.wowhead.com/quest=25711 , https://www.wowhead.com/quest=25712 and https://www.wowhead.com/quest=25713 ), then you'll get a quest to the mage tower ( https://www.wowhead.com/quest=25714 ) to kill cultists ( https://www.wowhead.com/quest=25716 ), after that you get the questline to this guy ( https://www.wowhead.com/quest=26157 ).\n\nAfter you have done his initial quest ( https://www.wowhead.com/quest=26158 ) you only have to do the ( https://www.wowhead.com/quest=26159 ) (and the very quick followup https://www.wowhead.com/quest=26160 ) one to unlock this quest.",
            date = "2013-08-26T23:52:15-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26169#comments:id=1890553",
        },
        {
            id = 1625395,
            score = 8,
            author = "Ziggyplum",
            text = "For those without coords, there are several ships, or partial ships, in the water and on the land.  This one is not touching the shore at all.  It's the front half of a ship with the nose pointed toward the land.  The pile of skeletons is under the water in the chamber with the canon.  It's toward the front / raised part of the ship, but still under the water.",
            date = "2012-02-12T12:05:46-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26169#comments:id=1625395",
