    [26173] = {
        {
            id = 1191125,
            score = 11,
            author = "504420",
            text = "This is a brand new quest added with the shattering.\n\nShahandana is a fel mistress located northeast of the portal at (59, 43). She is surrounded by some worshipping cultists, but she is on top of the small hill.\n\nGomegaz is a large core hound that patrols just northeast of the portal around (51, 42).\n\nJarroc Torn-Wing is a terrorfiend demon on a hill at (43, 47) surrounded by Oath-Chained Infernals.",
            date = "2010-11-27T17:41:32-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26173#comments:id=1191125",
        },
        {
            id = 2485223,
            score = 5,
            author = "ZoLatKam",
            text = "For all of you who weren't around pre-WoD, post Cata or didn't come through Blased Lands while leveling:\n\nIf you're attempting to find Watch Commander Relthorn Netherwane (http://www.wowhead.com/npc=16841/watch-commander-relthorn-netherwane) to start this quest chain in order to learn what's up with that small Gilnean village in Souther Blasted Lands, you must first visit Zidormi (http://www.wowhead.com/npc=88206/zidormi#comments) at the entrance to the Blasted Lands from Swamp of Sorrows & have her \"Show me the Blasted Lands before the invasion.\"\n\n/way Blasted Lands 48.2 7.2 Zidormi\n\nOnce you've done this, you can find the desired NPC here:\n\n/way Blasted Lands 54.66 50.45 Watch Commander Relthorn Netherwane\n\nHe will have Protecting Our Rear (http://www.wowhead.com/quest=26173/protecting-our-rear#see-also) which begins the aforementioned quest chain.\n\nJust remember to go back to Zidormi (http://www.wowhead.com/npc=88206/zidormi#comments) once you're done & have her \"Take me back to the present.\"\n\nUnfortunately, you don't retain use of the Surwich Flight Path after doing the quest chain, but you do net 1175 rep {1293 for Humans} with Gilneas.",
            date = "2017-04-10T06:10:55-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26173#comments:id=2485223",
        },
        {
            id = 1264892,
            score = 3,
            author = "526110",
            text = "They were all easy kills.  You only have to clear what is in the way to them.",
            date = "2010-12-28T21:46:16-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26173#comments:id=1264892",
        },
        {
            id = 1475320,
            score = 2,
            author = "488162",
            text = "Its possible that Commander Relthorn is referring to Teremus the Devourer (http://www.wowhead.com/npc=7846), a rare Dragonkin that flies around the edges of the Dark Portal.",
            date = "2011-07-20T17:52:44-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26173#comments:id=1475320",
        },
        {
            id = 5159010,
            score = -5,
            author = "Veradas",
            text = "As of the release of Shadowlands xpac I can confirm that this and the following quests are no longer available and have been removed: Protecting Our Rear, The Charred Granite of the Dark Portal (I had 15 out of 25 chips and they are no longer in my bags), The Vile Blood of Demons, and Atrocities.  All the npc targets for these quests, Felhounds, Felguards and other Demons have been removed and replaced with Ironmarch orcs.  I was not able to play WoW until recently, and have been noticing some quests in my toons' logs are no longer highlighted in bright yellow on my Carbonite addon.",
            date = "2021-04-22T13:12:07-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26173#comments:id=5159010",
        },
    },
