        {
            id = 2258254,
            score = 19,
            author = "Sunreaver",
            text = "When everyone says \"stand in the barrels\", they're talking about the high stack of barrels & crates next to the tent. I kept trying to stand by the two barrels on the ground and getting caught. Whether it's a bug or by design, when you stand on top of that high pile (it's as high as the tent), the guards don't notice you examining the paper.",
            date = "2015-09-28T00:38:50-05:00",
