    [26179] = {
        {
            id = 6111943,
            score = 1,
            author = "Manbearcow",
            text = "Supervisor Fizsprocket & The Venture Co. Quest Guide - https://www.youtube.com/watch?v=oQ-igFavKpc\n\nPick up the quests Supervisor Fizsprocket & The Venture Co from Morin Cloudstalker, both quests can be done together.\n\nYou may need to complete The Ravaged Caravan first. Also picked up from Morin Cloudstalker.\n\nHead to the cave entrance along the hills Northeast of Bloodhoof Village. Inside and outside the cave, you will find Venture Company workers and Supervisors ranging from level 7-10.\n\nDon't waste your time killing the venture company mobs outside of the cave. Instead, make your way inside the cave while eliminating any mobs along the way. This will help you make progress on The Venture Company.\n\nFollow the cave wall to your right and you will find Supervisor Fizsprocket standing near the back of this chamber. He is level 12 and he doesn't hit too hard, but what can make this fight difficult are the surrounding enemies. It can be difficult to fight him alone without pulling aggro from other enemies.\n\nHardcore difficulty for the Venture Co is moderate due to the enemies running away at low health. However, this particular quest can be completed by killing enemies outside of the cave. Supervisor Fizsprocket may be difficult for Hardcore players because he is inside the cave, and as they say in Hardcore, \"If you can't see sky, you're gonna die.\" Fortunately, he is not very deep inside the cave.\n\nAfter defeating Supervisor Fizsprocket, loot his body for make your way back out of the cave while cleaning up any remaining Venture Company Workers and Supervisors along the way.\n\nReturn to Morin Cloudstalker for your reward.",
            date = "2025-05-13T21:49:11-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26179#comments:id=6111943",
        },
        {
            id = 1862723,
            score = -1,
            author = "Drkgodz",
            text = "go team venture!",
            date = "2013-06-04T13:04:50-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26179#comments:id=1862723",
        },
    },
    [26180] = {
        {
            id = 1260114,
            score = 13,
            author = "RaQin",
            text = "1) Get this additional quest \"The Venture Co.\" BEFORE you do Supervisor Fizsprocket and kill everything standing outside the cave BEFORE going in then...\n\n2) Enter the cave at 61,47\n\n3) Follow a STRAIGHT line (according to your mini-map) through the mine. Do NOT go down ANY side shafts (if you're looking for Supervisor Fizsprocket).\n\n4) Supervisor Fizsprocket is either right near the front entrance or he's in the room at the very end of the hallway you followed in from the entrance, near a small wooden wall/structure.\n\nADVICE: Do not wander around in the cave trying to complete your counts for \"The Venture Co.\" quest. There are plenty of those mobs outside the cave to complete it quickly without the frustration of getting lost in this semi-huge mine.\n\nDoing anything else will end up making this one of the most frustrating quests you will have dealt with up to this point (at-level).",
            date = "2010-12-26T14:03:28-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26180#comments:id=1260114",
        },
