        {
            id = 1311172,
            score = 3,
            author = "MintySinty",
            text = "Video of this quest chain:\nPart One (http://www.youtube.com/watch?v=_kUds9aeikw)\nPart Two (http://www.youtube.com/watch?v=74RMAmjYKpc&feature=related)",
            date = "2011-01-26T20:05:22-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26184#comments:id=1311172",
