    [26205] = {
        {
            id = 2142226,
            score = 21,
            author = "Timbeon",
            text = "If you're like me and managed to lose your multi-bot, you can get a replacement by talking to Engineer Grindspark, at 40.6, 28.0.",
            date = "2015-03-23T20:05:51-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26205#comments:id=2142226",
        },
        {
            id = 1190615,
            score = 12,
            author = "Donnovan",
            text = "The robot will fill its tanks when it touches a green pond.  What to do next took me a few minutes to figure out.  There are spots of scum floating on the ponds.  Take your robot to those.  Simple once you spot the scum.  Enjoy!",
            date = "2010-11-27T13:56:17-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26205#comments:id=1190615",
        },
        {
            id = 1436005,
            score = 5,
            author = "309256",
            text = "Make sure to pick up What's Left Behind (http://www.wowhead.com/quest=26264) while doing this quest, from Tock Sprysocket (http://www.wowhead.com/npc=42611) to the northwest of Engineer Grindspark. Then head southwest to get Dealing with the Fallout (http://www.wowhead.com/quest=26265), from Corporal Fizzwhistle (http://www.wowhead.com/npc=42630), behind the building with the mailbox outside.\n\nThen simply run around The Toxic Airfield, dragging your Multi-Bot to the \"spots of scum floating on the pond\" as noted by Donnovan, killing all the Living Contamination (http://www.wowhead.com/npc=43089) and Toxic Sludge (http://www.wowhead.com/npc=42184) you encounter.\n\nIf you lose your GS-9x Multi-Bot, return to Engineer Grindspark for a new one.\n\nThis quest has no followup, but turning in Dealing With the Fallout leads to What's Keeping Jessup? (http://www.wowhead.com/quest=26316) from Captain Tread Sparknozzle (http://www.wowhead.com/npc=42489), located by High Tinker Mekkatorque.\n\nAlso, by the time you get this quest - or maybe after turning it in, you should hopefully be level 3. Make sure to visit your class trainer to pick up their next quest and train your new ability.\n\nMage: The Arts of a Mage (http://www.wowhead.com/quest=26198)\nPriest: The Arts of a Priest (http://www.wowhead.com/quest=26200)\nRogue: The Arts of a Rogue (http://www.wowhead.com/quest=26207)\nWarlock: The Power of a Warlock (http://www.wowhead.com/quest=26201)\nWarrior: The Arts of a Warrior (http://www.wowhead.com/quest=26204)\n\nEach class-specific quest has a Star Wars-themed weapon reward:\n\nMage: Electro-Staff (http://www.wowhead.com/item=59042)\nPriest: Staff of the Force (http://www.wowhead.com/item=59040)\nRogue: Death Star (http://www.wowhead.com/item=59043)\nWarlock: Vibro Knife (http://www.wowhead.com/item=59041)\nWarrior: Very Light Sabre (http://www.wowhead.com/item=59039)",
            date = "2011-06-07T01:26:11-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26205#comments:id=1436005",
        },
        {
            id = 1685689,
            score = 3,
            author = "Tigronn",
            text = "Surprised nobody mentioned multibotting yet..\nOh well",
            date = "2012-07-07T15:58:30-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26205#comments:id=1685689",
