    [26211] = {
        {
            id = 1198639,
            score = 24,
            author = "151462",
            text = "As with the old version of this quests, the turtles are found all along the shore.\n\nHowever, if you did the pre-cata version of this quest, you cannot complete it again if you still have your original Nat Pagle's Extreme Angler FC-5000. (Ye old duplicate found message stops you upon attempted turn in.)\n\nIf you want to complete this quest simply to count toward your Hinterlands quest achievement, you must first nuke your old Nat Pagle's Extreme Angler FC-5000.\n\nHappy turtle slayin'!",
            date = "2010-11-30T19:22:50-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26211#comments:id=1198639",
        },
        {
            id = 2194550,
            score = 6,
            author = "Taraezor",
            text = "Hinterlands is not the most exciting of zones. So long as you are the correct level you can go straight to this NPC as per the map. A single quest with no prerequisite quests, reward is yours and then get yourself hearthed out of there. Hinterlands done!\n\nExcept of course if you are on farm for the https://www.wowhead.com/item=8704 as the first stage of the quests giving a pet reward.",
            date = "2015-06-16T06:53:25-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26211#comments:id=2194550",
        },
        {
            id = 3270422,
            score = 3,
            author = "Techhead7890",
            text = "This quest was not part of the storyline required to go on to Jintha'Alor or Hiri, but you will still need it for the Revantusk Village step for the https://www.wowhead.com/achievement=4897 achievement.",
            date = "2020-12-08T18:26:14-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26211#comments:id=3270422",
        },
        {
            id = 2246361,
