    },
    [26212] = {
        {
            id = 1255997,
            score = 14,
            author = "743763",
            text = "This confused me for a bit, but it's really stupid easy, actually.\n\nJust swim up to the island, and click the basket. Two mobs should spawn and attack you. Just kill them, (Very easy to kill. I solo'ed them in a matter of seconds on a 31 Warlock.) Then, loot the bodies and you should get Lard's Lunch. The basket will still be clickable though, and clicking it will spawn two more mobs again, but they don't drop anything. You just need to do it once, than run back up and turn it in. ;D",
            date = "2010-12-24T03:10:23-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26212#comments:id=1255997",
        },
        {
            id = 1392600,
            score = 12,
            author = "tailsandy",
            text = "Pizza guy knocked on my door just as I delivered Lard his lunch.\n\nI was just as happy as Lard.",
            date = "2011-04-16T10:56:20-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26212#comments:id=1392600",
        },
        {
            id = 1188979,
            score = 4,
            author = "710553",
            text = "As of 4.03b, it worked fine for me. Click basket, couple of Vilebranch Kidnappers comes, beat them up, loot Lard's lunch from corpse.",
            date = "2010-11-26T22:23:29-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26212#comments:id=1188979",
        },
        {
            id = 1506266,
            score = 4,
            author = "rfrisk",
            text = "The basket doesn't give Lard's Lunch.  It's on one of the mobs you kill.\n\nI killed a bunch of mobs clicking on the basket until I figured it out. ahhhhhhhh!",
            date = "2011-08-29T19:24:42-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26212#comments:id=1506266",
        },
        {
            id = 1235685,
            score = 1,
            author = "734084",
            text = "I went to the island and when I clicked on the box, it acted like it was going to open it up but when the loading bar finished it didn't pop up to loot it and nothing was chasing me when I swam back to the mainland. I can't get the box and I can't finish the quest.",
            date = "2010-12-15T12:02:57-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26212#comments:id=1235685",
        },
    },
    [26213] = {
        {
            id = 1178825,
