    [26228] = {
        {
            id = 1261053,
            score = 53,
            author = "kites",
            text = "You don't even have to enter the cave to complete this quest.\n\nThere's a pile of bones with an axe stuck in it on the outside hill of the cave, just behind the shed at Furlbrow's Pumpkin Farm, just use your box there and listen to the convo with your ear to the ground.",
            date = "2010-12-27T00:51:23-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26228#comments:id=1261053",
        },
        {
            id = 1138472,
            score = 15,
            author = "Xicon",
            text = "During this quest, a conversation between Glubtok the Foreman and a Shadowy Figure occurs.\n\n    Glubtok says: What little humie want? Why you call Glubtok?\n    Shadowy Figure says: Sad... Is this the life you had hoped for, Glubtok? Running two-bit extortion operations out of a cave?\n    Glubtok says: Glubtok crush you!\n    Shadowy Figure says: Oh will you? Do you dare cross that line and risk your life?\n    Shadowy Figure says: You may attempt to kill me - and fail - or you may take option two.\n    Glubtok says: What option two?\n    Shadowy Figure says: You join me and I shower wealth and power upon you.\n    Glubtok says: So Glubtok have two choices: die or be rich and powerful?\n    Glubtok says: Glubtok take choice two.\n    Shadowy Figure says: I thought you'd see it my way.\n    Shadowy Figure says: I will call for you when the dawning is upon us.",
            date = "2010-10-09T14:13:20-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26228#comments:id=1138472",
        },
        {
            id = 1246897,
            score = 9,
            author = "52272",
            text = "BWEE!\n\n~Miner turns around with a Exclamation point overhead~ Hmm....guess it was nothing.....\n\nMetal Gear Craft",
            date = "2010-12-20T01:01:31-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26228#comments:id=1246897",
        },
        {
            id = 1179341,
            score = 7,
            author = "554409",
            text = "It might not have been made of cardboard, but it's good enough for me. Just wish I could keep it...",
            date = "2010-11-23T21:45:42-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26228#comments:id=1179341",
        },
        {
            id = 1208994,
