            text = "If you can't find the crate, it is in your bags.  It is given to you upon accepting this quest.",
            date = "2010-12-05T19:23:30-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26228#comments:id=1208994",
        },
    },
