    [26230] = {
        {
            id = 1166837,
            score = 64,
            author = "535805",
            text = "Yeah, Because y'know, I couldn't just bring back a full coyote for you to eat, I'll just get the tails",
            date = "2010-11-10T01:46:23-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26230#comments:id=1166837",
        },
        {
            id = 1361926,
            score = 54,
            author = "Apolocyntosis",
            text = "Today, I'd like to perform, for your enjoyment, a one act play I like to call \"Feast or Famine: The Story of One Man's Quest to Herp the Derp.\"\n\nQuest Giver: Go collect dirt and coyote tails so we can eat!\nHapless Adventurer: Okay!\nHapless Adventurer: *kills coyotes*\nHapless Adventurer: *collects coyote tails and coyote meat*\nHapless Adventurer: *turns in coyote tails for hobos to eat*\nHapless Adventurer: *throws out coyote meat to save bag space*\n\n~Fin~",
            date = "2011-03-09T03:49:09-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26230#comments:id=1361926",
        },
        {
            id = 1205406,
            score = 46,
            author = "423774",
            text = "Possibly one of the most illogical quests in the game.",
            date = "2010-12-04T03:16:31-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26230#comments:id=1205406",
        },
        {
            id = 1184707,
            score = 37,
            author = "519724",
            text = "Well atleast she asked for fresh dirt. Wouldn't wanna eat a pie with old dirt in it, would you?",
            date = "2010-11-25T11:30:47-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26230#comments:id=1184707",
        },
        {
            id = 1380040,
            score = 35,
            author = "292031",
            text = "She's probably following a traditional recipe (the coyote tail seasoning added to the classic mud pie), and she's not going to ruin that with things like meat and vegetables and things with nutritional value. Mama Celeste has more integrity than that.",
            date = "2011-03-30T12:32:42-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26230#comments:id=1380040",
        },
    },
    [26232] = {
        {
            id = 1188261,
            score = 54,
            author = "GenXCub",
            text = "I was having trouble getting credit for Eavesdropping.  It only gave it to me when I killed all four thugs.  Other people were crowding around trying to do the quest as well.  When I listened and we all killed thugs, I didn't get any credit.  So do this in a group if there are others waiting... or try to do it while no one is there.",
            date = "2010-11-26T16:53:37-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26232#comments:id=1188261",
        },
        {
            id = 2872636,
            score = 33,
            author = "nairesiga",
            text = "Not the sleeping thugs inside the house.... go around the back of the house.",
            date = "2019-02-23T08:41:34-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26232#comments:id=2872636",
        },
        {
            id = 1817500,
            score = 23,
            author = "941372",
            text = "With CRZ, this quest is a pain to finish. It seems as if everyone and their brother quests in Westfall and since you have to kill EACH and EVERY one of the thugs, this quest takes considerably longer.",
            date = "2013-02-23T19:37:25-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26232#comments:id=1817500",
        },
        {
            id = 1352891,
            score = 19,
            author = "89813",
            text = "Walk past the guys. Wait for them to finish the discussion per Xicon post above. Don't bother trying to hide to eavesdrop. They will then attack you. Kill all 4 of them; they have only about 74 health  so killing all 4 is about the same as killing 1 or 2 enemies at this level.\n\nExample of health for enemies:\nLevel 10: 198\nLevel 11: 222\nThugs: 74",
            date = "2011-02-28T07:47:34-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26232#comments:id=1352891",
        },
        {
            id = 1722074,
            score = 18,
            author = "804504",
            text = "FORM A PARTY!\n\nI tried this quest at least half a dozen times with no success; too many other Pandarans trying to do the quest at the same time.  I was starting to get seriously pissed at Blizzard when, finally, someone had the brilliant idea of forming a party; lo and behold, we all got credit on the next go!",
            date = "2012-09-27T19:57:53-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26232#comments:id=1722074",
        },
    },
    [26236] = {
        {
            id = 1179728,
            score = 14,
            author = "707380",
            text = "The quest chain suddenly ends here. Just complete the quests here: Times are Tough (http://www.wowhead.com/quest=26237), Westfall Stew (http://www.wowhead.com/quest=26241), Heart of the Watcher (http://www.wowhead.com/quest=26252) (The item to start this quest is a heart which drops from a Watcher, go figure) and you'll get the next step from Saldean: You Have Our Thanks (http://www.wowhead.com/quest=26270).",
            date = "2010-11-24T00:24:32-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26236#comments:id=1179728",
        },
        {
            id = 1184369,
            score = 7,
            author = "Kodago",
            text = "LISTEN UP! Its not the end! I was relieved when i entered DeadMines and found out that its continues in there! GO if u wanna find out who killed Azeroths Favorite horse!",
            date = "2010-11-25T09:29:45-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26236#comments:id=1184369",
        },
        {
            id = 1186787,
            score = 5,
            author = "709709",
            text = "Ok Folks,\n\nWhen the trail goes cold at Saldean's, nip to the deadmines and meet the 3rd incarnation of Lieutenant Horatio Laine.\n\nThe quest chain continues there.",
            date = "2010-11-26T05:04:11-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26236#comments:id=1186787",
        },
        {
            id = 1274111,
            score = 5,
            author = "439253",
            text = "Way to go, you're making me do my least favorite pre-Cataclysm quests to get to the good stuff.  I like phasing but the real downside is that you have to follow things in such a linear fashion it's crazy.",
            date = "2011-01-02T22:23:26-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26236#comments:id=1274111",
        },
    },
