    [26241] = {
        {
            id = 1178916,
            score = 8,
            author = "286335",
            text = "The Okra (http://www.wowhead.com/object=203982) can be found on the farm land directly in front of the building that the quest giver is in.  They appear as sparkling bushes.  The Goretusk  (http://www.wowhead.com/npc=157)near that same area can be looted for the Goretusk flanks (http://www.wowhead.com/item=57788).  The Fleshripper (http://www.wowhead.com/npc=1109)'s can be found all around the area near the farm and can be looted for the Stringy Fleshripper Meat (http://www.wowhead.com/item=57786)",
            date = "2010-11-23T18:53:51-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26241#comments:id=1178916",
        },
        {
            id = 1204248,
            score = 6,
            author = "123042",
            text = "post event\nSalma Saldean yells: Dinner's ready! Come and get it!\nOrphan says: I'm so happy. Thank you, mama and thank you, .\nOrphan cries.\nOrphan says: YAY FOR !",
            date = "2010-12-03T13:35:23-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26241#comments:id=1204248",
        },
        {
            id = 2142752,
            score = 1,
            author = "biggleman",
            text = "It seems with the new patch the drop rate for the Goretusk Flanks and Fleshripper Meats were increased.",
            date = "2015-03-25T09:14:13-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26241#comments:id=2142752",
        },
        {
            id = 2330383,
            score = 1,
            author = "Ghouls",
            text = "Okay she didn't even use a fire. She didn't cook the meat! She's feeding raw meat to kids!",
            date = "2016-05-12T20:13:01-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26241#comments:id=2330383",
        },
        {
            id = 2342276,
            score = 1,
            author = "probablykenma",
            text = "A single tear rolls down my cheek, my expression in a twinge of sorrow and fear... \"They took the okra.\" I say, a tone of sadness clear in my voice, \"Not the okra...\" My expression turns to fear. The okra is gone, I can't believe my eyes. I still, to this day, an unable to wrap my head around the fact...\nThe okra is still gone.",
            date = "2016-06-19T15:51:49-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26241#comments:id=2342276",
        },
    },
    [26252] = {
        {
