    [26257] = {
        {
            id = 1178946,
            score = 21,
            author = "286335",
            text = "First, find the Overloaded Harvest Golem (http://www.wowhead.com/npc=42381) around 49 33 (Here's a map (http://www.wowhead.com/maps?data=40:492332)) You should have the Harvest Watcher's Heart (http://www.wowhead.com/item=57954) in your inventory by now, just use it near one of the Golems to take control of it.\n\nOnce you have control, go to the Molsen Farm (Here's a map (http://www.wowhead.com/maps?data=40:448353))\n\nThere you will find Energized Harvest Reapers (http://www.wowhead.com/npc=42342)  You'll need to kill 25 of these guys.\n\nWhile controlling the Reaper, you'll have access to the following skills:\nSkill 1: Reaping Blows is a standar Melee attack.\nSkill 2: Rocket Boost will speed you up and give you a buff which allows you to just plow through the Energized Harvest Reaper.\n\nThe Rocket Boost skill will make quick work of the Reapers, just spam that and it'll go pretty quick.",
            date = "2010-11-23T19:09:59-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26257#comments:id=1178946",
        },
        {
            id = 5891474,
            score = 17,
            author = "AnySpy",
            text = "Blizzard must have broken the scaling. As a level 12 Fury Warrior, Rocket Boost did not one shot the Energized Harvest Reapers as it normally does. Reaping Blows didn't do any damage that I noticed.\n\nThey chunked me for about a fifth of my health bar each hit in the Harvest Golem.\n\nThe easiest way I found to complete it was to just AOE them down on foot rather than using the Harvest Golem.",
            date = "2024-07-02T17:47:49-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26257#comments:id=5891474",
        },
        {
            id = 1343717,
            score = 10,
            author = "478719",
            text = "it's alive! it's alive!\n\n-Dr Frankenstein",
            date = "2011-02-20T16:33:15-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26257#comments:id=1343717",
        },
        {
            id = 2555236,
            score = 9,
            author = "Tilra",
            text = "with the scaling do not bother with the golem. They take too long to kill with it. So kill them normally.",
            date = "2018-02-27T02:45:37-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26257#comments:id=2555236",
        },
        {
            id = 2529221,
            score = 5,
            author = "pozdeady",
            text = "Don't bother with controlling a golem if you are stacked with heirlooms. Just plunge into a crowd of mobs and start mowing, this way you will complete quest in a minute. Don't forget to use quest item on a way back and you're good.",
            date = "2017-10-12T05:11:16-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26257#comments:id=2529221",
        },
    },
    [26263] = {
        {
            id = 2021612,
