        },
    },
    [26264] = {
        {
            id = 1182005,
            score = 7,
            author = "Jrubzjeknf",
            text = "The part after finishing this quest is absolutely hilarious.\n\nTock Sprysprocket is able to bring a small gnome (yes, its possible!) back to life, who walks off before the quest giver can take readings and than spontaneously causes one of the biggest explosion I've ever witnessed in WoW.",
            date = "2010-11-24T15:04:12-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26264#comments:id=1182005",
        },
        {
            id = 1436008,
            score = 2,
            author = "309256",
            text = "Do this quest with A Job for the Multi-Bot (http://www.wowhead.com/quest=26205) from Engineer Grindspark (http://www.wowhead.com/npc=42553), if you don't already have it. Then head southwest to get Dealing with the Fallout (http://www.wowhead.com/quest=26265), from Corporal Fizzwhistle (http://www.wowhead.com/npc=42630), behind the building with the mailbox outside.\n\nThen simply run around The Toxic Airfield, dragging your Multi-Bot to the toxic geysers, killing all the Living Contamination (http://www.wowhead.com/npc=43089) and Toxic Sludge (http://www.wowhead.com/npc=42184) you encounter.\n\nStick around after turning the quest in for the amusing interlude described above.\n\nThis quest has no followup, but turning in Dealing With the Fallout leads to What's Keeping Jessup? (http://www.wowhead.com/quest=26316) from Captain Tread Sparknozzle (http://www.wowhead.com/npc=42489), located by High Tinker Mekkatorque.\n\nAlso, by the time you get this quest - or maybe after turning it in, you should hopefully be level 3. Make sure to visit your class trainer to pick up their next quest and train your new ability.\n\nMage: The Arts of a Mage (http://www.wowhead.com/quest=26198)\nPriest: The Arts of a Priest (http://www.wowhead.com/quest=26200)\nRogue: The Arts of a Rogue (http://www.wowhead.com/quest=26207)\nWarlock: The Power of a Warlock (http://www.wowhead.com/quest=26201)\nWarrior: The Arts of a Warrior (http://www.wowhead.com/quest=26204)\n\nEach class-specific quest has a Star Wars-themed weapon reward:\n\nMage: Electro-Staff (http://www.wowhead.com/item=59042)\nPriest: Staff of the Force (http://www.wowhead.com/item=59040)\nRogue: Death Star (http://www.wowhead.com/item=59043)\nWarlock: Vibro Knife (http://www.wowhead.com/item=59041)\nWarrior: Very Light Sabre (http://www.wowhead.com/item=59039)",
            date = "2011-06-07T01:34:07-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26264#comments:id=1436008",
        },
        {
            id = 5766572,
            score = 1,
            author = "Ehayen",
            text = "Reference to the 2018 Star Trek documentary \"What We Left Behind: Looking Back at Star Trek\"",
            date = "2024-01-16T22:19:22-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26264#comments:id=5766572",
        },
        {
            id = 5766574,
            score = 1,
            author = "Ehayen",
            text = "This is not an escort quest. You don't actually follow anyone. You just fly to the turn-in point.",
            date = "2024-01-16T22:19:56-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26264#comments:id=5766574",
        },
        {
            id = 2245043,
            score = 0,
            author = "Leeony",
            text = "What's Left Behind : https://youtu.be/aiqcC6PClBE\nGood luck !",
            date = "2015-09-03T07:11:09-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26264#comments:id=2245043",
        },
    },
    [26265] = {
        {
            id = 1436010,
            score = 4,
            author = "309256",
            text = "Do this quest with A Job for the Multi-Bot (http://www.wowhead.com/quest=26205) from Engineer Grindspark (http://www.wowhead.com/npc=42553), if you don't already have it, and What's Left Behind (http://www.wowhead.com/quest=26264), from Tock Sprysocket (http://www.wowhead.com/npc=42611). Both of these NPCs are located northeast of High Tinker Mekkatorque's camp.\n\nThen simply run around The Toxic Airfield, dragging your Multi-Bot to the toxic geysers, killing all the Living Contamination (http://www.wowhead.com/npc=43089) and Toxic Sludge (http://www.wowhead.com/npc=42184) you encounter.\n\nThis quest opens up What's Keeping Jessup? (http://www.wowhead.com/quest=26316) from Captain Tread Sparknozzle (http://www.wowhead.com/npc=42489), located by High Tinker Mekkatorque.\n\nAlso, by the time you get this quest - or maybe after turning it in, you should hopefully be level 3. Make sure to visit your class trainer to pick up their next quest and train your new ability.\n\nMage: The Arts of a Mage (http://www.wowhead.com/quest=26198)\nPriest: The Arts of a Priest (http://www.wowhead.com/quest=26200)\nRogue: The Arts of a Rogue (http://www.wowhead.com/quest=26207)\nWarlock: The Power of a Warlock (http://www.wowhead.com/quest=26201)\nWarrior: The Arts of a Warrior (http://www.wowhead.com/quest=26204)\n\nEach class-specific quest has a Star Wars-themed weapon reward:\n\nMage: Electro-Staff (http://www.wowhead.com/item=59042)\nPriest: Staff of the Force (http://www.wowhead.com/item=59040)\nRogue: Death Star (http://www.wowhead.com/item=59043)\nWarlock: Vibro Knife (http://www.wowhead.com/item=59041)\nWarrior: Very Light Sabre (http://www.wowhead.com/item=59039)",
            date = "2011-06-07T01:39:03-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26265#comments:id=1436010",
        },
        {
            id = 2244732,
            score = -1,
            author = "Leeony",
            text = "Dealing with the Fallout, quest : https://youtu.be/I092jC8td1U\nGood luck!",
            date = "2015-09-02T19:17:23-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26265#comments:id=2244732",
        },
    },
