    [26268] = {
        {
            id = 1185920,
            score = 9,
            author = "Ethanol",
            text = "These crates inside the cave are a little on the small side, especially with the green slimes distracting you,  so keep your eye peeled. Generally sticking to a wall and following that will help you find them easily.",
            date = "2010-11-25T20:49:03-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26268#comments:id=1185920",
        },
        {
            id = 1200194,
            score = 4,
            author = "690489",
            text = "You will be looking for small wooden crates with red horde symbols on them.\nThey are found inside the Skulk Rock cave.\n\nWatch out for the occasional Jade Ooze (level 31-32) that live in and around the cave.\n\nCrates respawn within a minute or two.\n\nScreenshot added.",
            date = "2010-12-01T12:53:16-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26268#comments:id=1200194",
        },
        {
            id = 1570730,
            score = 2,
            author = "kimyushin",
            text = "Cave entrance by the riverside, 57,38.  It is covered over by the \"Prime Slime\" quest objective number on the map.  You can see it if you click off the \"Show quest objectives\" on the map.",
            date = "2011-11-12T22:10:58-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26268#comments:id=1570730",
        },
        {
            id = 2612527,
            score = 1,
            author = "KnockKnock",
            text = "Make sure you go to the undergoing cave. You'll be able to complete Skull Rock Supplies, Skull Rock Cleanup and Prime Slime in there. Don't waste your time in the surrounding area or top floor.",
            date = "2018-09-08T21:15:00-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26268#comments:id=2612527",
        },
        {
            id = 3236181,
            score = 1,
            author = "eKatherine",
            text = "The crates are easy to see now, as they have a glow on them. If you're looking for jade oozlings, which are a pet that drops off the jade oozes, there are capturable ones within the cave. The Direglob is in the bottom of the cave. Make sure you have that quest too before you start clearing the cave.",
            date = "2020-10-08T02:35:56-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26268#comments:id=3236181",
        },
    },
    [26269] = {
        {
            id = 1379824,
            score = 56,
            author = "741591",
            text = "I think this quest is meant to partially be a joke about how it was always just that one last page you couldn't find...",
            date = "2011-03-30T06:26:42-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26269#comments:id=1379824",
        },
        {
            id = 1186400,
            score = 41,
            author = "nirces",
            text = "you cannot use the \"old\" page 14 to complete this, has to be a freshly dropped one",
            date = "2010-11-26T00:54:43-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26269#comments:id=1186400",
        },
        {
            id = 1310820,
            score = 40,
            author = "488863",
            text = "I remember the first time doing the older version of this quest: finding 16 damn pages and mostly getting duplicates of ones I already had. Then I made some decent money selling these duplicate pages in the auction house, as well as finding whatever pages I was missing from there.\n\nThen I do this quest on a new character, and I find out you need just one page? Okay fine, maybe it'll be a rare drop!\n\n*Gets page within the first 3 mobs killed*\n\nWow, the new players have no idea how tedious this quest used to be.",
            date = "2011-01-26T14:37:50-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26269#comments:id=1310820",
        },
        {
            id = 1319368,
            score = 26,
            author = "740032",
            text = "i love the relevant locations map for this lol.  Take 2 steps and you'll trip over it! :D",
            date = "2011-02-02T13:25:46-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26269#comments:id=1319368",
        },
        {
            id = 1658428,
            score = 24,
            author = "57893",
            text = "This quest was originally designed to teach players to use the neutral auction house and trade amongst themselves. In the process of questing through Stranglethorn Vale a player was likely to gather most of the pages, and if unlucky or impatient, the player could buy the missing ones, and sell the extras to boot.\n\nThis was back in the days when a journey (without a mount) from Nesingwary's camp to Booty Bay and back wasn't considered \"too long\" to expect of players, and they frequently traveled several times up and down the length of the entire Stranglethorn Vale (it wasn't divided into two zones like it is today).\n\nAs WoW aged, and the leveling rate quickened, this quest became more and more annoying to complete due to the time commitment involved. Even with earlier mounts, players would out-level the quest before completing it if they didn't pretty much immediately buy the pages.\n\nIt was probably the most abandoned quest in the game.",
            date = "2012-04-25T01:56:03-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26269#comments:id=1658428",
        },
    },
    [26270] = {
        {
            id = 1178957,
            score = 5,
            author = "286335",
            text = "Very simple, just go inside the building behind the quest giver and turn the quest in to Salma Saldean  (http://www.wowhead.com/npc=235)",
            date = "2010-11-23T19:13:55-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26270#comments:id=1178957",
        },
        {
            id = 1315166,
            score = 5,
            author = "Sunreaver",
            text = "I wasn't offered this quest after doing Times are Tough. Is there another requirement somewhere?",
            date = "2011-01-30T01:04:34-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26270#comments:id=1315166",
        },
        {
