    [26277] = {
        {
            id = 3304988,
            score = 16,
            author = "Cadiencie",
            text = "You can turn this quest in, even if you have progressed to the point that Vol'jin has died, by quest synching with a fresh character (preferably a troll) who is working through the Echo Isles quests.\n\nThis is from the response to my ticket:\n\nI am Gromnaskod, High Warlord of the Horde, and Game Master of these lands. We have been busy, fighting off the Black Dragonflight of Blackwing lair, so I appreciate your patience during the wait.\n\nI understand that you're having trouble with the quest More Than Expected and not being able to turn it in.\n\nThis is due to the progress you have already made in the story and as a result Vol'jin is no longer there.\n\nWhile it is true that the quest is not needed and can be safely abandoned if you truly must have it complete you can use the party sync feature with a low lvl troll and that way you will be in their phasing and you should be able to turn it in then.\n\nI hope this helps you out.\n\nWishing you luck and hoping you have a good day.\nGromnaskod.",
            date = "2021-02-28T18:45:37-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26277#comments:id=3304988",
        },
        {
            id = 3127133,
            score = 10,
            author = "Slavrix",
            text = "For anyone who cannot hand this in at a higher level.\nThis was the official response from a GM\n\nIssue ID: #67654139\n\nYour ticket has received the following response:\n\nHeya! How is it going?\nGame Master Eciaya here. Thank you so much for your patience today, mate! I hope this message finds you well. :)\n\nIf you cannot see Vol'jin on the Echo Isles (Troll starting area) - this is because your character has progressed too far in the game's story, to the point where Vol'jin is killed. You will not be able to hand the quest in due to that.\nAs the Echo Isles quests are not necessary for Loremaster, so you may abandon the quest to continue your adventure. :)\n\nIf you have no other questions, please help us to mark this case as resolved on this page: https://us.battle.net/support/en/case/ and fill up the following survey! We are really appreciated hearing any feedback or suggestions from you.^^\n\nMay life bestow you with epic loots and legendary journeys!\nGame Master Eciaya\nBlizzard Entertainment",
            date = "2019-06-16T20:47:45-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26277#comments:id=3127133",
        },
        {
            id = 1678866,
            score = 8,
            author = "Pandoras",
            text = "When completed Vol'jin says: I have sometin' to show ya. It be easier to understand if ya see it yourself.\n\n(A vision appears in front of Vol'jin)\n\nVision of Garrosh Hellscream says: Don't talk back to me, troll.  You know who was left in charge here.  Haven't you stopped to ask yourself why Thrall chose me instead of you?\nVision of Vol'jin says: Dere be no question why, Garrosh.  He gave ya tha title because ya be Grom's son and because tha people be wantin' a war hero.\nVision of Vol'jin says: I tink ya be even more like ya father den ya thought, even witout da demon blood.\nVision of Garrosh Hellscream says: You are lucky that I don't gut you right here, whelp.  You are foolish to think that you can speak to your Warchief in such ways.\nVision of Vol'jin says: Ya be no Warchief of mine.  Ya not earned my respect and I'll not be seein' tha Horde destroyed by ya foolish thirst for war.\nVision of Garrosh Hellscream says: And what exactly do you think that you are going to do about it?  Your threats are hollow.  Go slink away with the rest of your kind to the slums, I will endure your filth in my throne room no longer.\nVision of Vol'jin says: I know exactly what I'll be doin' about it, son of Hellscream.  I'll watch and wait as ya people slowly become aware of ya ineptitude.  I'll laugh as dey grow ta despise ya as I do.\nVision of Vol'jin says: And when tha time comes dat ya failure is complete and ya \"power\" is meaningless, I will be dere to end ya rule swiftly and silently.\nVision of Vol'jin says: Ya will spend ya reign glancin' over ya shoulda and fearin' tha shadows, for when tha time comes and ya blood be slowly drainin' out, ya will know exactly who fired tha arrow dat pierced ya black heart.\nVision of Garrosh Hellscream says: You have sealed your fate, troll.\nVision of Garrosh Hellscream spits at Vol'jin's feet.\nVision of Vol'jin says: And you yours, \"Warchief.\"",
            date = "2012-06-20T20:38:52-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26277#comments:id=1678866",
        },
        {
            id = 1534519,
            score = 3,
            author = "Aiue",
            text = "I did not expect this.",
            date = "2011-10-04T06:25:35-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26277#comments:id=1534519",
        },
    },
    [26278] = {
        {
            id = 1408991,
            score = 42,
            author = "Glowyrm",
            text = "How to obtain the Lashtail Hatchling (http://www.wowhead.com/item=69251) companion as Horde\n\nTo see the Lashtail Hatchling inside the Zul'Gurub instance after killing Bloodlord Mandokir (http://www.wowhead.com/npc=52151) you must first complete a series of small quest lines in Northern Stranglethorn.\n\nAs a member of the Horde this entire ordeal starts with The Defense of Grom'gol: Raptor Risk (http://www.wowhead.com/quest=26278) given by Commander Aggro'gosh (http://www.wowhead.com/npc=2464) in Grom'gol.\n\nAfter completing that quest, you will automatically receive the quest A Lashtail Hatchling (http://www.wowhead.com/quest=26317) and the Lashtail Raptor Egg Fragment (http://www.wowhead.com/item=58165).\nReturn with the hatchling to Far Seer Mok'thardin (http://www.wowhead.com/npc=2465) in Grom'gol.\n\nNext he will send you on a quest called I Think She's Hungry (http://www.wowhead.com/quest=26321) to feed the baby raptor murloc meat. Make sure your raptor is summoned so she can take bites out of the corpses as you kill them.\n\nNow take the hatchling to the Bal'lal Ruins @ 33.7, 37.2 (http://www.wowhead.com/maps?data=33:338372) where you will find a pile of skulls on the ground, Your hatchling will run up to the pile and grab a skull from it. Now he will give you the quest Favored Skull (http://www.wowhead.com/quest=26323) which needs you to return to Nimboya (http://www.wowhead.com/npc=2497) in Grom'gol.\n\nThe cauldron near Nimboya will now offer the quest A Nose for This Sort of Thing (http://www.wowhead.com/quest=26325).\n\nNext you get the quest Who's a Big Troll? (http://www.wowhead.com/quest=26330) then Skullsplitter Mojo (http://www.wowhead.com/quest=26332)\n\n***SPOILER AHEAD***\n\nAfter completing the above quest line, Bloodlord Mandokir (http://www.wowhead.com/quest=26334) will spawn and offer a \"quest\" of the same name. He really just wants to steal the raptor from you because it's special.\n\nNimboya will now give you a quest to speak to Priestess Hu'rala (http://www.wowhead.com/quest=26350).\n\nShe will lead you on a chain to try and save your new raptor hatchling friend from her terrible fate of becoming the Bloodlord's new raptor slave. This is all your fault! But maybe you can do something about it...\n1) Mind Vision (http://www.wowhead.com/quest=26351), 2) See Raptor (http://www.wowhead.com/quest=26359), 3) Mind Control (http://www.wowhead.com/quest=26360), 4) Be Raptor (http://www.wowhead.com/quest=26362), 5) Surkhan (http://www.wowhead.com/quest=26386)\n\nAfter that really cool and fun quest chain from the Priestess you are read to enter the 85 Heroic Dungeon of Zul'Gurub and face the Bloodlord Mandokir. It's time to undo the mistake you made by bringing him back to life, and you must save your new friend from a world of torture and evil. Once the Bloodlord falls at your hands, you will see An Old Friend (http://www.wowhead.com/quest=29208#comments:id=1408932).\n\nHow to obtain the Lashtail Hatchling (http://www.wowhead.com/item=69251) companion as Alliance (Credit to user: Madwolf)\n\nFor Alliance this chain starts with the quest Bad Medicine (http://www.wowhead.com/quest=26732) given by Brother Nimetz (http://www.wowhead.com/npc=739) at the Rebel Camp.\n\nUpon completion of Bad Medicine you will automatically obtain the quest Just Hatched (http://www.wowhead.com/quest=26738) and the Lashtail Raptor Egg Fragment (http://www.wowhead.com/item=58165). Return to Corporal Sethman (http://www.wowhead.com/npc=1422) at the Rebel Camp with the new hatchling.\n\nHe will then send you on the quest I Think She's Hungry (http://www.wowhead.com/quest=26739) to feed the baby raptor some basilisk meat. Make sure you have the hatchling summoned while killing basilisks so she may take bites from the corpses as you kill them.\n\nNext you must do The Fate of Kurzen (http://www.wowhead.com/quest=26735) given by Lieutenant Doren (http://www.wowhead.com/npc=469) in the Rebel Camp. Continue on his chain and do Spared from Madness (http://www.wowhead.com/quest=26736) next.\n\nAt this point you must log out and in to spawn an NPC that will be required in the next step.\n\nNow take the hatchling to the Bal'lal Ruins @ 33.7, 37.2 (http://www.wowhead.com/maps?data=33:338372) where you will find a pile of skulls on the ground. Your hatchling will run up to the pile and grab a skull from it. Now he will give you the quest Favored Skull (http://www.wowhead.com/quest=26745). Return to Osborn Obnoticus (http://www.wowhead.com/npc=43884) at the Rebel Camp (This is the NPC that you must have logged out then back in to see according to some Alliance players).\n\nOsborn will then give you A Nose for This Sort of Thing (http://www.wowhead.com/quest=26746) to start trying to figure out who that skull belonged to.\n\nAfter that do the next quest in the chain, A Physical Specimen (http://www.wowhead.com/quest=26747).\n\n***SPOILER AHEAD***\n\nAfter completing the above quest line, Bloodlord Mandokir (http://www.wowhead.com/quest=26748) will spawn and offer a \"quest\" of the same name. He really just wants to steal the raptor from you because it's special. Do not chase  him when he runs off. There is more to do, you must now embark on a chain to try and save your new raptor friend from her fate.\n\nOsborn will give you a quest to go talk to Priestess Thaalia (http://www.wowhead.com/quest=26749) at Fort Livingston.\n\nShe will lead you on a chain to try and save your new raptor hatchling friend from her terrible fate of becoming the Bloodlord's new raptor slave. This is all your fault! But maybe you can do something about it...\n1) Mind Vision (http://www.wowhead.com/quest=26772), 2) See Raptor (http://www.wowhead.com/quest=26773), 3) Mind Control (http://www.wowhead.com/quest=26774), 4) Be Raptor (http://www.wowhead.com/quest=26775), 5) Ghaliri (http://www.wowhead.com/quest=26776)\n\nAfter that really cool and fun quest chain from the Priestess you are read to enter the 85 Heroic Dungeon of Zul'Gurub and face the Bloodlord Mandokir. It's time to undo the mistake you made by bringing him back to life, and you must save your new friend from a world of torture and evil. Once the Bloodlord falls at your hands, you will see An Old Friend (http://www.wowhead.com/quest=29208#comments:id=1408932).",
            date = "2011-05-04T01:29:32-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26278#comments:id=1408991",
        },
        {
            id = 1580794,
            score = 13,
            author = "916021",
            text = "Technically, you must also get the quest  https://www.wowhead.com/quest=26416 from  https://www.wowhead.com/npc=43063 in Ashenvale in order to be able to get the quest from Bort.  She starts the questline.  Otherwise, Bort won't have the quest.",
            date = "2011-11-25T22:50:51-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26278#comments:id=1580794",
        },
        {
            id = 1442958,
            score = 10,
            author = "823376",
            text = "If you are dumb like me, and wonder why you can't get this quest to start this questline, make sure you have talked to Bort near the zep towers in Orgrimmar and gotten his quest to go to Grom'gol. I wasted a lot of time and bothered a GM to figure out why the commander had nothing to say to me :(",
            date = "2011-06-16T21:16:41-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26278#comments:id=1442958",
        },
