    [26295] = {
        {
            id = 1179170,
            score = 44,
            author = "286335",
            text = "Informational Pamphlet (http://www.wowhead.com/item=58113): Inside Building, all the way at the back (41.61, 66.42)\nIssue of the Moonbrook Times (http://www.wowhead.com/item=58114): On the ground (43.28,  69.89)\nSecret Journal (http://www.wowhead.com/item=58115): In the Inn-like building, second floor (43.43, 66.63)\nMysterious Propaganda (http://www.wowhead.com/item=58116): Side of building (43.58, 68.69)\n\nMap (http://www.wowhead.com/maps?data=40:549438415664433699433667436687)",
            date = "2010-11-23T20:38:47-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26295#comments:id=1179170",
        },
        {
            id = 1183144,
            score = 32,
            author = "cntrstrk14",
            text = "Did anyone else read the newspaper? It has a tidbit about your own character from an earlier quest. Blizzard is really pushing for an immersible experience with these new quests and they are nailing it!",
            date = "2010-11-24T22:28:14-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26295#comments:id=1183144",
