            sourceUrl = "https://www.wowhead.com/quest=26295#comments:id=1181287",
        },
        {
            id = 1358689,
            score = 6,
            author = "749526",
            text = "I found the newspaper and pamphlet in the town hall (first building on the right) in the back room, and the propaganda was on the ground by the fountain. The secret journal I found in the back back room of the top floor of the inn (first building on the left). So apparently they can spawn in a few places.",
            date = "2011-03-05T21:40:39-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26295#comments:id=1358689",
