        {
            id = 1841430,
            score = 5,
            author = "1088365",
            text = "It looks like this has a bug in it. one of the items just does not show up as clickable at the moment. I am a rogue and I am told it could have something to do with being stealthed... Not 100% sure on this though.\n\nI am able to find all apart from Mysterious Propaganda which I can see but am unable to click. I reported it but no reply for 24hs :(\n\nI have abandoned it 3 times now and get the same result. I have done this quest with other alts and had no issues.",
            date = "2013-04-10T13:21:17-05:00",
