    [26296] = {
        {
            id = 1181637,
            score = 10,
            author = "Nineave",
            text = "Actually, Red Bandana will drop off any Moonbrook Thug (http://www.wowhead.com/npc=42677) in Moonbrook. No need to go to the Deadmines.",
            date = "2010-11-24T13:18:16-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26296#comments:id=1181637",
        },
        {
            id = 1684222,
            score = 5,
            author = "sephyre",
            text = "You need to pick up https://www.wowhead.com/quest=26295 in order for the bandana to drop off of the mobs.\n\nJust to explain how I confirmed this for the sake of the skeptical ^_~, I repeatedly went to Moonbrook between quests in the investigation quest chain to see if they would drop off https://www.wowhead.com/npc=42677. Before I picked up this quest it did not drop. After I picked the quest up it was a 100% drop rate.\n\nAlso, https://www.wowhead.com/npc=42677 can be found hiding just behind the buildings in Moonbrook.",
            date = "2012-07-03T23:11:02-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26296#comments:id=1684222",
        },
        {
            id = 2549412,
            score = 5,
            author = "radicarl",
            text = "Interestingly, this quest's completion dialogue contradicts the official timeline (though the official timeline is bonkers, and five years would've made way more sense).",
            date = "2018-01-30T22:06:59-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26296#comments:id=2549412",
        },
        {
            id = 1191793,
            score = 2,
            author = "steelangel",
            text = "Is this quest doable if you have already finished the series with Vanessa?",
            date = "2010-11-27T22:36:06-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26296#comments:id=1191793",
        },
        {
            id = 1687257,
            score = 1,
            author = "1013439",
            text = "You can do this quest with https://www.wowhead.com/quest=26295  if mobs already spawned and ready as follows;\n\n1. Get in Moonbrook from the flight point. Take the first house on the right. 2 thugs inside. Kill the first one loot the quest item. Accept the quest and kill the other thug. Get the 2 quest items.\n2. Go outside the house turn right and take the other quest item near the center of the fountain.\n3. Go inside the inn. Kill 1 thug at the inn and 1 thug at the kitchen.\n4. Go upstairs and kill 1 thug accross the room. and kill the other thug in the room where the last quest item is. Loot the quest item.\n5. Go outside the inn. Just go to stables where only 1 thug is wandering around kill him. (Other houses have 2 thugs in them. not necessary to do an extra fight.)\n\n6. And turn in the quests.",
            date = "2012-07-12T06:03:44-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26296#comments:id=1687257",
        },
    },
    [26297] = {
        {
            id = 1296848,
            score = 20,
            author = "766376",
            text = "Some of what she said started to make a lot of sense!",
            date = "2011-01-16T19:31:18-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26297#comments:id=1296848",
        },
        {
            id = 1204373,
            score = 19,
            author = "123042",
            text = "The speech addressed:\n\nThe rally is about to begin!\n\nShadowy Figure yells: Gather, brothers and sisters! Come, all, and listen!\nShadowy Figure yells: Brothers. Sisters. We are ABANDONED - the orphaned children of Stormwind.\nShadowy Figure yells: Our \"king\" sits atop his throne made of gold and shrugs at our plight!\nShadowy Figure yells: Meanwhile, our children die of starvation on these very streets!\nShadowy Figure yells: HIS war, not ours, cost us our livelihood. WE paid for the Alliance's victories with our blood and the blood of our loved ones!\nShadowy Figure yells: The time has come, brothers and sisters, to stop this injustice!\nShadowy Figure yells: The government of Stormwind, of the ALLIANCE, must be made accountable for what it has done to us!\nShadowy Figure yells: Today, we are reborn! Today, we take a stand as men and women, not nameless, faceless numbers!",
            date = "2010-12-03T14:31:02-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26297#comments:id=1204373",
        },
        {
            id = 2363459,
            score = 13,
            author = "smtips",
            text = "All the instructions here aren't precise and I didn't want to watch a video just to complete a simply quest. I had to abandon and re-take it twice til I figured it out. ALL the text would show, but it wasn't completing and I never saw a shadowy figure. I was standing in FRONT of the wagon by the tongue of the wagon. Don't do that.\n\nStand directly BEHIND the wagon, in front of the two girls standing there and it completes, and the shadowy figure shows up on top of the wagon.\n\nHope this works for you.\n\nBTW, I think it's really dumb to have to type in a Captcha code to make a post here, when I'm already logged in with a user name and password to post.",
            date = "2016-08-09T01:49:09-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26297#comments:id=2363459",
        },
        {
            id = 1356223,
            score = 12,
            author = "548372",
            text = "This entire questline made me laugh, how is ANYONE starving in Azeroth let alone westfall? unless the entire mage tower went somewhere, a single mage could conjure food for armies.\n\nUnless they didnt train for it...",
            date = "2011-03-03T11:08:34-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26297#comments:id=1356223",
        },
        {
            id = 1607727,
            score = 10,
            author = "933266",
            text = "I noted something interesting. When the shadowy figure spawns, TWO humanoids pop up on tracking. One is named \"VanCleef Test Dummy\" and one is named \"Shadowy Figure\". When the shadowy figure disappears, however, the \"Vancleef Test Dummy\" Still appears on my mini-map. Can someone explain?",
            date = "2012-01-06T17:18:38-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26297#comments:id=1607727",
        },
    },
