    [26305] = {
        {
            id = 1183287,
            score = 29,
            author = "69472",
            text = "All you have to do is use the soul gem on Yenniku and it will stun him and put the filled soul gem in your bags.\nBe careful though, because if your bags are full it will NOT put the soul gem in your bag, nor will it tell you that your inventory is full (the usual telltale sign that you need to clear some bag space). I used the gem on him 4 times before I realized what was going on.",
            date = "2010-11-24T23:37:08-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26305#comments:id=1183287",
        },
        {
            id = 1209075,
