    [26320] = {
        {
            id = 1476104,
            score = 124,
            author = "833385",
            text = "It's south, but not immediately south.\n\nIf you are in the right house you will see a label The Deadmines - Defias Hideout pop up as you enter.  As for the advice \"follow the homeless\" it was meaningless to me - there was no pattern to the movements of the homeless here or inside the mines that I could work out.  Perhaps this was a bug and others see a stream of homeless making their way to the entrance.  Whatever.\n\nFrom the house, you go up the stairs, and this will get you to the the entrance to the mine.\nIt all gets twisty at this point, but I went to the southernmost area of the dungeon - lots of undead\nand with a different colour on the minimap.  I was wrong - go south but before you reach the undead part turn west, that's where the instance portal is.  After entering the portal, light the incense.\n\nThere are dungeon quests following this one if you need/want them.",
            date = "2011-07-21T15:17:48-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26320#comments:id=1476104",
        },
