    [26343] = {
        {
            id = 1549622,
            score = 10,
            author = "Neocoolzero",
            text = "Just in case of doubt,since this guy is Booty Bay faction,this quest rewards no bb rep and takes no Bloodsail rep away.",
            date = "2011-10-20T15:40:42-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26343#comments:id=1549622",
        },
        {
            id = 1345163,
            score = 4,
            author = "apocalypsetc",
            text = "Riddlevox, kinda sounds like Riddlebox, the third Joker's card.  Nothing at all like Magnets, How Do They Work, right?",
            date = "2011-02-21T18:04:48-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26343#comments:id=1345163",
        },
        {
            id = 2562778,
            score = 2,
            author = "RandomWindowArt",
            text = "Even though the maps show a very small area by the camp, the crocolisks can be found along the river going east from the camp and into the lake.",
            date = "2018-04-14T08:55:34-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26343#comments:id=2562778",
        },
        {
            id = 1671700,
            score = 0,
            author = "980147",
            text = "I'm a lvl 85 rogue, but I'm going back through to get all the zone quest/exploration achievements, and of course I'm getting \"The Green Hills of Stranglethorn\" achievement while I'm in Stranglethorn questing. But, I was just doing the Northern Stranglethorn quests and something odd was happening that i couldn't quite figure out until now, and I thought it would be something that other people might have had an issue with so here I am letting everyone know!\n\nFirst off, I have the Zygor's Guides AddOn. (which by the way, in my opinion, is a really great questing AddOn, even though you REALLY don't need it anymore since the patch where the waypoints for quests were automatically on your map lol, still great AddOn and I love using it and believe it or not it really does make things much smoother.)\n\nSo, at the very beginning of the N. Stranglethorn quests at Nesingwary's Expedition, you talk to Drizzlik and get the quest \"Supply and Demand\" at the same time when you get all the first hunting quests right? Of course. WELL, to my surprise Drizzlik was not offering this quest to me.. and since I had done ALL these quests many times before without a hitch I was pretty confused as to why.. I kept questing for a bit, just not worrying about it, but I wasn't sure if the crockolisk quests not being completed would affect the end result in being able to get the finishing quest for the \"Green Hills of Stranglethorn\". So, I decided to figure out what was going on.\n\nI simply tracked back through Zygor's guides, (which made it a hell of alot easier to figure out since searching on the internet for the order in which all the quest's just before this happen in would be a real pain in the ass... lol) and towards the end of the Duskwood quests you accept a quest from Sister Elsington in Raven Hill called \"Soothing Spirits\" THEN she is supposed to give you the quest \"Rebels Without a Clue\" which you turn into Lieutenant Doren at the Rebel Camp to start you off in N. Stranglethorn.\n\nSo when I went to Raven Hill I WAS able to accept \"Soothing Spirits\" and completed it and turned it in, but she did not off the \"Rebels Without a Clue\" quest. I'm assuming because I had not completed the tons of other Duskwood quests.. But that doesn't matter, because when I went back to Nesingwary's Expedition, Drizzlik now offered the quest \"Supply and Demand\", the one I had been worried would somehow affect being able to finish the chain to get the achievement.\n\nWELL! I don't know if anyone else might have had the problem of not being able to get \"Supply and Demand\" or not. But, hopefully if you did have this problem just like I did, you stumbled across this post and it helped you out! Thanks for reading my post everyone! lol =]",
            date = "2012-05-30T09:24:06-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26343#comments:id=1671700",
        },
    },
    [26344] = {
