    [26346] = {
        {
            id = 1367031,
            score = 8,
            author = "Spoonzilla",
            text = "Follow-up quest to this one (http://www.wowhead.com/quest=26042).  Begin this quest by killing the guy who spawns when you turn in that quest and a quest starting rock will appear.",
            date = "2011-03-14T18:37:34-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26346#comments:id=1367031",
        },
        {
            id = 1800304,
            score = 1,
            author = "806894",
            text = "So apparently this seems like it can be locked out.  I was turning in the keystone and spawned the giant.  Other players right next to me (90s) killed it before I could even notice it spawned.  No quest from the rock, though I do get the follow-up from the Dwarf at Refuge Point to kill the giant you first started the quest chain from.\n\nEdit, ok my mistake.  Once I abandoned the quest, I could then pick up the Myzrael's Tale starter from the stone at the circle.\n\nAs a note if this happens and you don't see the quest available from the stone at the circle, go back to Refuge Point, accept the quest to fight the Princess, cancel the quest, and then the original stone's turn-in should be available.  Apparently the giant itself doesn't carry anything necessary.",
            date = "2013-01-17T23:35:52-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26346#comments:id=1800304",
        },
        {
            id = 5505718,
            score = 1,
            author = "Woyster",
            text = "If you cannot find Skuerto to hand in the quest: go to the bottom of Arathi Highlands to Zidormi (speech buble on the map) and speak to her to see the area before the war. Then fly back to where he is on the quest marker, he should be there now.",
            date = "2022-12-17T14:31:55-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26346#comments:id=5505718",
        },
    },
