    [26348] = {
        {
            id = 1687201,
            score = 3,
            author = "1013439",
            text = "You need to kill the tidehunters and oracles which are mainly on the coastal area.\n\nIn the coast below the lighthouse there are more tidehunters then oracles generally. If you kill all the murlocs and you still need some oracles for quests, you can either wait the murlocs to spawn in the same area or go north a little along side the coast to find new oracles.\n\nUsually oracles are found in the water.",
            date = "2012-07-12T02:02:03-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26348#comments:id=1687201",
        },
    },
