    [26353] = {
        {
            id = 1802262,
            score = 27,
            author = "Tantrevalles",
            text = "\"At this level range you'll be walking all the way and the entire chain takes around 20 minutes to complete. It's simply not worth it for a measly 2275XP.\"\n\nAh, my friend. Not every quest is there specifically to provide the player with better stats and XP. Some of them are there simply to be entertaining, or for those of us who enjoy doing a bit of character building with our toons.\n\nAlso, this quest rewards you with one of the game's coolest shirts for fishermen: https://www.wowhead.com/item=3342. That would be worth the time even without an XP gain, but I'm a WOW fishing enthusiast, so I'm probably also crazy.\n\nEDIT: Discovered this by happy accident last night: for extra fun, if you can access the Escape From Durnholde (http://www.wowhead.com/quest=29599/escape-from-durnholde) instance, go to the inn at Southshore before you leave. Pay attention to the two pirates who eventually talk at the bar. Then, follow them . . .",
            date = "2013-01-22T00:13:05-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26353#comments:id=1802262",
        },
        {
            id = 1207102,
            score = 21,
            author = "Derren",
            text = "The description is wrong: Horde can loot and do that quest.",
            date = "2010-12-04T23:28:23-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26353#comments:id=1207102",
        },
        {
            id = 2582323,
            score = 11,
