    [26356] = {
        {
            id = 1191199,
            score = 9,
            author = "Rhynchelma",
            text = "If you are doing this new version of the quest and have done the old version then make sure you have got rid of \"duplicate items\".",
            date = "2010-11-27T18:05:54-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26356#comments:id=1191199",
