    [26358] = {
        {
            id = 1235836,
            score = 11,
            author = "heliconius",
            text = "Do not underestimate this quest! It is one of the preliminary quests, which will lead you to Twilight Highlands, upon reaching level 84.\n\nI needed badly to do the chain, due to fact that I needed the enchanthing rod recipe to be able to craft highest level enchanthing (above 500) which is sold by a belf vendor there, whom you won't get any acces, unless you are directed there by this chain.",
            date = "2010-12-15T13:08:21-06:00",
