    [26367] = {
        {
            id = 1667890,
            score = 16,
            author = "724724",
            text = "For easy access, talk to Kotonga (http://www.wowhead.com/npc=42624) in the village at the base of Jintha'Alor, and he will port you to the top, to the Totem of Akil'Darah (http://www.wowhead.com/object=204002#comments) @ 58, 67. The Totem will port you back to Kotonga when you need to go back.\nI've run this quest chain on 3 toons now, and only on my third go did I find this. I really wish I had known about this before!",
            date = "2012-05-17T17:11:48-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26367#comments:id=1667890",
        },
        {
            id = 1682555,
