    [26369] = {
        {
            id = 1191981,
            score = 51,
            author = "zingar",
            text = "really annoying chain that sends you up and down again",
            date = "2010-11-28T00:29:24-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26369#comments:id=1191981",
