    [26378] = {
        {
            id = 2461756,
            score = 7,
            author = "BlizzardCS",
            text = "Hey all!\n\nJust wanted to inform you that there’s an issue with this quest at the moment. Some players are not able to interact with https://www.wowhead.com/npc=42308, and our developer team is already investigating this.",
            date = "2017-01-11T11:48:21-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26378#comments:id=2461756",
        },
        {
            id = 1542208,
            score = 5,
            author = "TheWoWExp",
            text = "So, Westfall has fallen to hard times and has a lot of homeless residents. I confronted Deputy Rainer (http://www.wowhead.com/npc=963) for this quest. The Deputy tells you that the crime rate has risen as people fight for food and shelter and--gasp--murder! Well, Deputy, sometimes when crime rises, and things become scarce, there's going to be some bloodshed. Wouldn't you stab that person who is eyeballing that last piece of Funnel Cake (http://www.wowhead.com/item=33246) when the only thing you've been gnawing on all week is a Kodo Bone (http://www.wowhead.com/item=13703)?\n\nLogic, Deputy. Logic!\n\nAnyway, head over to Westfall and turn in the quest.",
            date = "2011-10-13T23:13:07-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26378#comments:id=1542208",
        },
        {
            id = 2509137,
            score = 1,
            author = "Taoshix",
            text = "https://www.wowhead.com/npc=42308 is only visible to humans, but if you are another race, just relog where he stands, and you will be able to see him for a short moment and turn the quest in.\nAfter that, he will remain visible and you can start questing in Westfall.",
            date = "2017-07-20T11:06:23-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26378#comments:id=2509137",
        },
        {
            id = 1889601,
            score = -2,
            author = "239242",
            text = "With the threat of the Defias extinguished, the region has become a haven for the homeless and downtrodden. The crime rate of the area has skyrocketed\n\nSo... After the alledged crime syndicate was defeated the crime rate 'skyrocketed'? Yes, that makes sense. With all what's going on in Westfall, Duskwood and Redridge you are beginning to wonder what in the hell 'King' Varian is DOING. Probably having more heart to heart talks with his son.",
            date = "2013-08-24T01:35:05-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26378#comments:id=1889601",
        },
    },
