    [26383] = {
        {
            id = 1552490,
            score = 21,
            author = "503971",
            text = "This quest is a Breadcrumb quest.\n\nBreadcrumb quests are quests that, even though you did not complete them and they were available at some point, have become unavailable permanently after certain conditions were met. If this happens to you, and you're a completionist, this quest can be marked as excluded in the Wowhead quest tracker if you are no longer able to complete it.\n\nThis quest becomes unavailable permanently, if either of the following conditions are met:\nhttps://www.wowhead.com/quest=28490 is completed.\nThis is a hero's call quest leading to this zone. You can only complete this quest, or the hero's call quest, not both. Completing the hero's call quest will therefore make this quest unavailable.\nhttps://www.wowhead.com/quest=26385 (Worgen) is completed.\nThis is a zone introductory quest leading to this zone. You can only complete this quest, or the zone introductory quest, not both. Completing the zone introductory quest will therefore make this quest unavailable.\nhttps://www.wowhead.com/quest=13518 is completed.\nThis is one of the quests available in the quest hub that this quest points to, and is also considered a follow-up to this quest. Completing this quest will make all zone introductory quests leading to this npc, including this one, unavailable.\n\nExamples of Breadcrumb quests and conditions making them unavailable:\n\nHero's call quests.\nThey become unavailable if your character's level is too high, and the hero's call board sends you to a different npc/zone.\nZone introductory quests.\nThis also includes hero's call quests. These quests are often started in a certain lower level zone, and they direct you to the next zone. If there are several of these, including the hero's call, directing you to the same zone/npc, completing one will mean the others become unavailable.\nQuest hub introductory quests.\nThese are quests that direct you to the next quest hub in a zone. If you've already completed the quests in that quest hub, the quest directing you to it may become unavailable.\nFollow-up quests.\nThese are uncommon, but still appear in older zones that have not been changed much in recent expansions. Sometimes a follow-up quest of quest X is available before you complete quest X. If you complete that follow-up quest and go back to the quest X giver, you may encounter the error 'You do not meet the requirements for that quest', leaving you unable to start it or turn it in.\n\nNote: A quest being unavailable does not necessarily mean it's unavailable permanently. If you have not met the aforementioned conditions, and the quest is still unavailable, then you may have missed certain required quests that precede this one, or you do not meet the requirements in some other way. Always verify this before excluding this quest.",
            date = "2011-10-24T10:34:37-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26383#comments:id=1552490",
        },
        {
            id = 1568640,
            score = 14,
            author = "910479",
            text = "Available if you complete https://www.wowhead.com/quest=28490\nNot available if https://www.wowhead.com/quest=13518 is in questlog or completed",
            date = "2011-11-10T09:40:43-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26383#comments:id=1568640",
        },
        {
            id = 1405820,
            score = 11,
            author = "Solarax",
            text = "You can only complete one of these breadcrumb quests.\n\nFor example, if you have already completed Hero's Call: Darkshore! (http://www.wowhead.com/quest=28490) then you will not be able to pick up this quest.",
            date = "2011-05-01T04:31:08-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26383#comments:id=1405820",
        },
        {
            id = 2579185,
            score = 6,
            author = "EmJii",
            text = "As of Patch 7.3.5 you can do two breadcrumb quests that lead you to Darkshore.\n\nYou have to keep the order to be able to do both.\n\n1.https://www.wowhead.com/quest=26383 (for every alliance race) or https://www.wowhead.com/quest=26385 (for Worgen only)\n\n2.https://www.wowhead.com/quest=28490 (can be found on every Hero's Call board)",
            date = "2018-07-07T10:12:44-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26383#comments:id=2579185",
        },
        {
            id = 1194323,
            score = 5,
            author = "snugglebutt",
            text = "Relogging will sort out the flight path not appearing when you try to fly to Lor'Danel.",
            date = "2010-11-28T19:56:45-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26383#comments:id=1194323",
        },
    },
