    [26402] = {
        {
            id = 1699375,
            score = 6,
            author = "997975",
            text = "Confirmed that this Quest is still available in the game, if you have done the previous quests and cant pick this one up it is because you have picked quests up already in feathermoon stronghold..... to pick this quest up you must not have any other quests in your log or completed from fetahermoon stronghold before hand or this quest wont show up.\nTook me a while to figure it out but i just abandoned all my other feralas quests and this one appeared.\n\nDiamondtetra of Lightbringer.",
            date = "2012-08-13T09:30:28-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26402#comments:id=1699375",
        },
        {
            id = 5578956,
            score = 3,
            author = "auryunderground",
            text = "There is a short roleplay as soon as this quest is turned in:\n\nhttps://www.wowhead.com/npc=39723, https://www.wowhead.com/npc=39653 and https://www.wowhead.com/npc=39725 appear in front of https://www.wowhead.com/npc=3936 and kneel.\n\nShandris Feathermoon says: Your training has progressed well, sisters. It won't be long before you lead your own people, with no further need of my teaching.\n\nShandris Feathermoon says: It is time for you to show me that leadership. Tambre, you will spearhead the offensive on Sardor Isle (https://wowpedia.fandom.com/wiki/Sardor_Isle). Your ferocity will be needed there.\n\nShandris Feathermoon says: Silvia, I'm sending you to the Tower of Estulan (https://wowpedia.fandom.com/wiki/Tower_of_Estulan) to drive out the Gordunni (https://wowpedia.fandom.com/wiki/Gordunni) ogres. Your diplomacy and strategy will both be put to the test.\n\nShandris Feathermoon says: Adella, you will strike out far to the east. Our forces must retake the eastern wilds, and observe the Horde unseen. May your judgment be as keen as your marksmanship.\n\nShandris Feathermoon says: I expect much of you. Do not fail me. Dismissed!",
            date = "2023-03-29T02:43:34-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26402#comments:id=5578956",
        },
        {
            id = 1647122,
