    [26477] = {
        {
            id = 1275416,
            score = 20,
            author = "752459",
            text = "The chest is at 55.0, 40.6. The small rock tunnel that leads there begins at 54.5, 36.6. It is guarded loosely by 2 Crazed Ancients that you can kill to randomly drop the Wooden Key.",
            date = "2011-01-03T15:38:48-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26477#comments:id=1275416",
        },
        {
            id = 1456493,
            score = 8,
            author = "cephadex",
            text = "Key drops from Crazed Ancients/Withered Ancients. Go down the road until you see a short stone pillar to your left (on the map this area is indicated by a dotted path to the left of the main road). Turn left, keep hanging left down a dirt path in half a circle till you go upward into a cave. Go through the cave, many more crazed ancients/withered ancients on your way, then you'll wind up in a little outdoor area depicted in the screenshots on this page. The box is on a bench to your right. Using the key open the box and inside is your item.",
            date = "2011-07-01T02:39:53-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26477#comments:id=1456493",
        },
        {
            id = 1657428,
            score = 6,
            author = "974325",
            text = "If you have done (part of) this questline pre-cataclysm, you might have the key already.\nAfter killing a lot of Crazed Ancients/Withered Ancients I remembered having some keys in the bank from when the keyring dissapeared, got it out of the bank and opened the chest",
            date = "2012-04-22T15:27:35-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26477#comments:id=1657428",
        },
        {
            id = 1191058,
            score = 4,
            author = "liseerik",
            text = "The chest is at 55,40.\n\nWithout coords: Run through the tunnell north of Raynewood Retreat. The path should lead you directly to the chest.",
            date = "2010-11-27T17:17:30-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26477#comments:id=1191058",
        },
        {
            id = 1222588,
            score = 2,
            author = "cuirmichael",
            text = "I didn't see any tunnel but ran through trees and down rocks to a 4-tier square tower on the edge of The Howling Vale.\n\nThe wooden key dropped from a Withered Ancient near the foot of the tower. The key lets you open the Worn Chest containing the key.\n\nAll this at 54,40.",
            date = "2010-12-10T17:48:42-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26477#comments:id=1222588",
        },
    },
    [26478] = {
        {
            id = 1230682,
            score = 14,
            author = "Metzae",
            text = "All you have to do is get inside the cave and loot the chest. Playing possum is just to keep the elite from aggroing on you. If you're OP, you can just walk in there, kill him, and loot the chest.",
            date = "2010-12-13T14:53:00-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26478#comments:id=1230682",
        },
        {
            id = 2552680,
            score = 10,
            author = "Wowzir",
            text = "https://www.wowhead.com/quest=26478\n\n/way Ashenvale 62.4, 612 Cave ENTR\n\nhttps://www.wowhead.com/npc=34499 guards the entrance patrolling to approximately (62, 62), and https://www.wowhead.com/npc=34500s inhabit the area.\n\n/way Ashenvale 62.6 60.3 Oso's Chest",
            date = "2018-02-14T12:17:11-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26478#comments:id=2552680",
        },
        {
            id = 2028554,
            score = 7,
            author = "Tantrevalles",
            text = "For those who like a little rough-and-tumble when questing, note that Oso hits like a freaking truck and takes a lot of damage. I downed him as a ret pally yesterday: level 25 geared in quest reward gear from Redridge and Ashenvale (with the exception of the 2-hander I got from Shadowfang, and the goggles I made from crafting).\n\nIt was a long fight and I spent at least half of it spamming my self-heals just to stay in the game. Most satisfying melee in months, I dare say. Very enjoyable.\n\nEdit: By long, of course, I mean \"longer than three seconds,\" which can feel like an eternity in this age of nerfed content. Figure the fight went on for 20 seconds, which is a by-gosh relative epoch in quest-melee years.",
            date = "2014-11-12T17:28:53-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26478#comments:id=2028554",
        },
        {
            id = 1191637,
            score = 5,
            author = "cchunbong",
            text = "after this quest Shael'dryn casts Conjure Food to combine the rod",
            date = "2010-11-27T21:22:16-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26478#comments:id=1191637",
        },
        {
            id = 1200535,
            score = 4,
            author = "Whiterock",
            text = "Playing Possum (http://www.wowhead.com/quest=26478) is one or the only quest needed to open Check in on the Edunes (http://www.wowhead.com/quest=13965) and To the Spire (http://www.wowhead.com/quest=13964). Need more investigation, becose by the time I been doing the Rod quests I have done all other in Astranaar :< Maybe the burning of Astranaar quests are needed for second one.",
            date = "2010-12-01T15:44:57-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26478#comments:id=1200535",
        },
    },
