    [26514] = {
        {
            id = 1182895,
            score = 24,
            author = "554409",
            text = "Humans finally let slip how we feel about gnomes.",
            date = "2010-11-24T20:23:45-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26514#comments:id=1182895",
        },
        {
            id = 1353090,
            score = 13,
            author = "LadySkyelar",
            text = "The best part was that I did this quest on my gnome priest. :]",
            date = "2011-02-28T11:35:33-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26514#comments:id=1353090",
        },
        {
            id = 1421183,
            score = 7,
            author = "Apolocyntosis",
            text = "Some day, you tall, humanoid sons-of-orcs, we Gnomes will have our revenge....\n\nNobody said it better than the great gnome, Walter Cogvacs, when he said,\n\n\"Stormwind City is afraid of me. I have seen its true face. The streets are extended canals and the canals are full of muck and when the drains finally clog up, all the vermin will drown. The accumulated filth of all their cybering and player killing will foam up about their waists and all the humans and night elves will look down and shout \"Save us!\"... and I'll look up and whisper 'No.'\"",
            date = "2011-05-17T16:23:47-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26514#comments:id=1421183",
        },
        {
            id = 1519144,
            score = 6,
            author = "760439",
            text = "Something is missing on the completion part:\n\nI've transferred a few silver over to you for the gnome, erm, gnoll kills.Wow. The gnomecorder can transfer physical money, huh?",
            date = "2011-09-16T05:37:06-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26514#comments:id=1519144",
        },
        {
            id = 1746426,
