    [26517] = {
        {
            id = 1203377,
            score = 24,
            author = "Neka",
            text = "OK in the end it was simple but it took awhile to figure out. When you get to the area with all the dead bodies next to the spider cave click on the bodies you'll come up with  loot  symbol -  the bodies have the spider idols. I ran past them forever not realizing it!",
            date = "2010-12-03T03:06:31-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26517#comments:id=1203377",
        },
        {
            id = 1189053,
            score = 17,
            author = "360925",
            text = "Basically just take the gryphon that the guy to the right of the quest giver is. the gryphon will take you to the top, enter the cave, and make a right when you exit. all you do here is loot 8 corpses. each one should give you an idol. then make your way back. and turn it in.",
            date = "2010-11-26T23:05:38-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26517#comments:id=1189053",
        },
        {
