        {
            id = 1182325,
            score = 55,
            author = "15542",
            text = "Very small spiders that are all over Jintha'Alor.  To make spotting them easier, press V to see their health bars.",
            date = "2010-11-24T16:45:45-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26523#comments:id=1182325",
