        {
            id = 1262205,
            score = 11,
            author = "468011",
            text = "use macro:\n\n/tar skitter\n\n...and bind this a button.\n\nEasy. :)",
            date = "2010-12-27T15:25:44-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26523#comments:id=1262205",
        },
        {
            id = 2327260,
            score = 11,
            author = "1608018",
            text = "Very tiny spiders you have to loot (not kill). I did a few things to make finding them much easier:\n\n1.) Hit V - this allows the spider's yellow health bar to show\n2.) Type /Tar Skit and it'll target the nearest one to you\n3.) Right click on the spiders frame and click Set Focus. This will put a yellow dot on your mini map so you can see the exact location of the spider\n\nHope this helps! Happy Spider Hunting :)",
            date = "2016-04-29T19:16:26-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26523#comments:id=2327260",
        },
    },
    [26524] = {
        {
            id = 1189022,
            score = 43,
            author = "476083",
            text = "You will be looking for very small cauldrons sitting on the ground next to the trolls in Jintha'alor. You can find most of them by going to the very top of the settlement inside of the tan rooms.",
            date = "2010-11-26T22:49:36-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26524#comments:id=1189022",
        },
        {
            id = 1186547,
            score = 15,
            author = "695019",
            text = "The vessels are much smaller than they were before the Shattering, so keep an eye out! There appear to be more on the upper levels than the lower ones, despite the spawn range dictated by the in-game quest tracker.\n\nThere also aren't as many of them, or otherwise have quite a long respawn timer now. A player came through doing the quest shortly before I did, and it took me about thirty minutes to find five for my quest.",
            date = "2010-11-26T02:35:27-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26524#comments:id=1186547",
        },
        {
            id = 1510894,
            score = 15,
            author = "873503",
            text = "Found at these coordinate, all on the top level:\n57, 71\n57, 69\n58, 76\n59, 79\n61, 82",
            date = "2011-09-05T15:18:20-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26524#comments:id=1510894",
        },
        {
            id = 1363232,
            score = 5,
            author = "152049",
            text = "After completing this quest, you will get a message saying, \"You don't meet the requirements for that quest.\"  I came here to find out why.  Look at the next quest in the chain, it's a HORDE quest, from an ally quest giver.  @_@  (Venemous Secrets)",
            date = "2011-03-10T13:28:18-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26524#comments:id=1363232",
        },
        {
