    [26532] = {
        {
            id = 1299650,
            score = 8,
            author = "768033",
            text = "Tamed as Level 36 BM Hunter.\nTo Tame Shadra, go across the lake to the purple alter with the candles on it.  You can except the quest from there as well as from the lookout NPC.  Except the quest, and open fire with Arcane Shot until you have agro, then start Tame Beast.  If she goes to the opposite side of the lake and starts fighting the NPC’s that spawn, abandon the quest finish her off and try again.",
            date = "2011-01-18T21:10:44-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26532#comments:id=1299650",
        },
        {
            id = 1179324,
            score = 5,
            author = "648135",
            text = "I did a lot of running around trying to figure this out. I couldn't find any info on where to get it or anything. You pick the quest up at Quel'Danil Lodge. I did some chains outside of Jintha'Alor. Still couldn't pick up the starter for this. Went back to Aerie Peak and Wind Master something or another inside the building by the flight master there had a quest to go to Quel'Danil lodge. You pick up two quests there, get phased, do those quests, and then you're able to pick the starter to this up.\n\nI'm not sure if the Wind Master dude has this quest at first or whatnot, or if there's a specific chain to unlock it, but once you get the Quel'Danil quest it leads to this. Hopes this somehow helps anyone curious even though it's kind of vague. :3",
            date = "2010-11-23T21:40:05-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26532#comments:id=1179324",
        },
