    [26535] = {
        {
            id = 1192133,
            score = 29,
            author = "42715",
            text = "The quest item Zanzil's Formulation (http://www.wowhead.com/item=58901) drops from the Zanzil Witch Doctors (http://www.wowhead.com/npc=1490).\n\nOn my first pass through the ruins, I didn't see any mobs marked as dropping a quest item, but when I went back, about three witch doctors had spawned. The mobs in the ruins may share a spawn so I'd suggest killing everything to make sure some witch doctors show up.\n\nAlso, unlike me, do this before you take the ZG portal so you don't have to come back.",
            date = "2010-11-28T02:14:15-06:00",
