    [26542] = {
        {
            id = 1633622,
            score = 23,
            author = "Qoko",
            text = "For max level players going for Loremaster: Hero's Call is the only breadcrumb quest for the Hinterlands, offered by both the Hero's Board and Nials in Arathi, but with a max level of 33. As such, when you finish Arathi you will not be able to do this quest and have to go to Aerie Peak directly to continue.",
            date = "2012-03-01T04:09:29-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26542#comments:id=1633622",
        },
        {
            id = 1401014,
            score = 22,
            author = "Umbrosangre",
            text = "If you are coming into Arathi Highlands from the Wetlands, there will be a new road going north from the main road that goes between Refuge Point and Stormgarde Keep. It will take you through a tunnel north into the Hinterlands. After that, just go west, following the mountain range, until you reach Aerie Peak.",
            date = "2011-04-27T06:54:41-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26542#comments:id=1401014",
        },
        {
            id = 1970711,
            score = 7,
            author = "Wyr3d",
            text = "Owing to the issues raised about Captain Nials quest being a direct copy of the Hero's Callboard quest of the same name, I have submitted a suggestion to Blizzard that they write a proper one for him. The lvl 33 cut-off for this quest is unreasonable given the revamp of previous zones, and all the perks from guilds, gear and rested XP which are available.\n\nAs there is no level cut-off for hero's call based breadcrumb quests in other areas, I can only assume the level cut off here is an oversight - especially since the changes they did make which restricts the Stone Shards (http://www.wowhead.com/quest=26341) questline (and it's consequent quests) to just this zone.\n\nAdditionally, the Horde has two quests which lead easily into Hinterlands without a problem. The first is Revantusk Village (http://www.wowhead.com/quest=26430) and the second is the Hero's Callboard counterpart - Warcheif's Command (http://www.wowhead.com/quest=28574) which does not suffer from this level cut-off.\n\nIf more people also suggest this, perhaps they will fix the problem for us Alliance.",
            date = "2014-06-07T11:54:33-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26542#comments:id=1970711",
        },
        {
            id = 1436609,
            score = 6,
            author = "martychonks",
            text = "The cave to get to The Hinterlands from Arathi Highlands is at 37.00, 29.36 (you can see the cave icon on the map north-northwest from Refuge Point.) Exercise caution once out of the tunnel, as there are level 35 wolves along the road.\nIf coming from Hillsbrad Foothills, there is a path leading to The Hinterlands at 70.90, 55.59, between \"e\" and \"K\" in Durnholde Keep on the map. Do not follow the river; this leads into the Western Plaguelands and can cause a swift death.",
            date = "2011-06-07T22:52:28-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26542#comments:id=1436609",
        },
        {
            id = 5525122,
            score = 6,
            author = "nihiru",
            text = "I received this quest from Adventure Guide at level 37, while Chromie Time was activated for Cataclysm. As of Patch: 10.0.2.47213",
            date = "2023-01-11T14:44:08-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26542#comments:id=5525122",
        },
    },
    [26544] = {
        {
            id = 1190334,
            score = 9,
            author = "IpKonfig",
            text = "Cave entrance is at 21.27.",
            date = "2010-11-27T11:55:31-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26544#comments:id=1190334",
        },
        {
            id = 1208958,
            score = 7,
            author = "wharris",
            text = "Guide to Redridge Quests:\n\nDo these at any time:\nNida's Necklace (http://www.wowhead.com/quest=26508)\nAn Unwelcome Guest (http://www.wowhead.com/quest=26509)\nLake Everstill Cleanup (http://www.wowhead.com/quest=26511)\nWanted: Redridge Gnolls (http://www.wowhead.com/quest=26504)\nFranks and Beans (http://www.wowhead.com/quest=26506)\nThreat to the Kingdom (http://www.wowhead.com/quest=26761) (from Westfall chain)\n\nOptional prequest: Hero's Call: Redridge (http://www.wowhead.com/quest=26365) or Hero's Call: Redridge (http://www.wowhead.com/quest=28563)\nThen a long chain:\nStill Assessing the Threat (http://www.wowhead.com/quest=26503)\nParker's Report (http://www.wowhead.com/quest=26505)\nWe Must Prepare!  (http://www.wowhead.com/quest=26510) (available earlier)\n        Completing the above enables: Like a Fart in the Wind (http://www.wowhead.com/quest=26513)\nTuning the Gnomecoder (http://www.wowhead.com/quest=26512)\nCanyon Romp (http://www.wowhead.com/quest=26514)\n       A gnoll drops dirt-stained scroll (http://www.wowhead.com/item=58898) which allows for He Who Controls the Ettins (http://www.wowhead.com/quest=26519) and Saving Foreman Oslow (http://www.wowhead.com/quest=26520)\nThey've Wised Up (http://www.wowhead.com/quest=26544)\nYowler Must Die! (http://www.wowhead.com/quest=26545)\nJohn J Keeshan (http://www.wowhead.com/quest=26567)\nThis Ain't My War (http://www.wowhead.com/quest=26568)\nWeapons of War (http://www.wowhead.com/quest=26571)\n       Accepting this enables  Render's Army (http://www.wowhead.com/quest=26570) and Surveying Equipment (http://www.wowhead.com/quest=26569)\nHis Heart Must Be In It (http://www.wowhead.com/quest=26573)\nIn Search of Bravo Company (http://www.wowhead.com/quest=26586)  (I'm not sure what the exact prerequisties are)\nBreaking out is hard to do (http://www.wowhead.com/quest=26587)\nJorgensen (http://www.wowhead.com/quest=26560)\nKrakauer (http://www.wowhead.com/quest=26561)\nAnd Last but not Least...Danforth (http://www.wowhead.com/quest=26562)\nReturn of the Bravo Company (http://www.wowhead.com/quest=26563)\nThey Drew First Blood (http://www.wowhead.com/quest=26607)\nIt's Never over (http://www.wowhead.com/quest=26616)\n\nThen do these together:\nBravo Company Field Kit: Camouflage (http://www.wowhead.com/quest=26636)\nBravo Company Field Kit: Chloroform (http://www.wowhead.com/quest=26637)\nHunting the Hinters (http://www.wowhead.com/quest=26638)\nPoint of Contact: Brubake (http://www.wowhead.com/quest=26639)r and Unspeakable Atrocities (http://www.wowhead.com/quest=26640)\n\n(Main chain Continues)\nPrisoners of War (http://www.wowhead.com/quest=26646)\nTo Win a War, You Gotta Become War (http://www.wowhead.com/quest=26651)\nDetonation (http://www.wowhead.com/quest=26668)\n    (Shadowhide Extinction (http://www.wowhead.com/quest=26692) now available)\nThe Dark Tower (http://www.wowhead.com/quest=26693)\nThe Grand Magus Doane (http://www.wowhead.com/quest=26694)\nAHHHHH! AHHHHHHHHHHHH! (http://www.wowhead.com/quest=26708)\nShowdown at Stonewatch (http://www.wowhead.com/quest=26713)\nDarkblaze, Bood of the Worldbreaker (http://www.wowhead.com/quest=26714)\nTriumphant Return (http://www.wowhead.com/quest=26726)\n\nA truly epic chain!",
            date = "2010-12-05T19:07:32-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26544#comments:id=1208958",
        },
        {
            id = 1458399,
            score = 2,
            author = "485320",
            text = "Shortly before this quest, one of the questgivers in this room comments that these gnolls must be allied with the (I've forgotten their name) forces to the East.  Does that comment say \"Shadowhide\"?  Or was it something else?\n\nIf they are Shadowhide auxiliaries, so to speak, AND allied with the blackrock orcs, then why are all the orcs at the edge of the Shadowhide area proper dead?",
            date = "2011-07-02T16:45:07-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26544#comments:id=1458399",
        },
        {
            id = 1753311,
            score = 1,
            author = "saildocva1",
            text = "Where do you get the coordinates?",
            date = "2012-10-29T16:44:17-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26544#comments:id=1753311",
        },
    },
    [26545] = {
        {
            id = 1193752,
            score = 12,
            author = "196807",
            text = "When you turn in the quest, the following conversation occurs between Magistrate Solomon and Colonel Troteman.\n\nMagistrate Solomon says: We're finished! I might as well call for an evacuation now and clear out Lakeshire before the orcs march.\nMagistrate Solomon says: And right when we finally finished building that damned bridge! What hope is there, Xinhuan?\nColonel Troteman says: There is hope, Solomon.\nMagistrate Solomon says: What hope, colonel? What could possibly save us from the impending assault?\nColonel Troteman says: He served 248 consecutive tours of duty across the First, Second and Third Wars.\nColonel Troteman says: Captured five years ago by a battalion of filthy, pig sucking Blackrocks, five clicks out from the southern DMZ.\nColonel Troteman says: Tortured and kept alive as a urinal for young orc warriors. For FIVE YEARS.\nColonel Troteman says: JOHN J. KEESHAN.\nMagistrate Solomon says: Keeshan's alive? I thought he died.\nColonel Troteman says: He's alive alright, and been living like an outcast in Lakeshire for the past five months. Or hadn't you noticed? Now enough chatter. We've got people to save!\n\nColonel Troteman than gives the quest John J. Keeshan (http://www.wowhead.com/quest=26567) as the followup.",
            date = "2010-11-28T15:35:46-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26545#comments:id=1193752",
        },
        {
            id = 1184657,
            score = 8,
            author = "169039",
            text = "Don't let the fact that he's marked as \"Elite\" freak you out. He is easily soloed. He hits like a wet noodle. This has since been changed - Yowler is no longer an elite mob.",
            date = "2010-11-25T11:16:48-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26545#comments:id=1184657",
        },
