    [26551] = {
        {
            id = 1294772,
            score = 4,
            author = "bam187",
            text = "''It only works within Stranglethorn, but it will transport you back here to me should you need to return switfly.''\n\nI'm sure they mean 'swiftly' instead of 'switfly' but I do not know how to let Blizzard know that. It's not just a typo here, it is also in-game. I'm sure they would want to know.",
            date = "2011-01-15T09:59:14-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26551#comments:id=1294772",
        },
        {
            id = 1354953,
            score = 3,
            author = "406368",
            text = "Apparently since the latest patches post-Cataclysm, they have removed the NPC named https://www.wowhead.com/npc=43245 from the game until they finish renovating Zul'gurub into a refurbished level 85 heroic dungeon.\n\nAbout the quest:  Now all players need to do is stand in the same walls that Zanzil stood and you automagically get a 'click to complete quest' box in the top-right on your screen.  Once you click and finish quest, it will then also automagically give you the next quest in this chain, https://www.wowhead.com/quest=26552.",
            date = "2011-03-02T07:22:53-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26551#comments:id=1354953",
        },
        {
            id = 1304859,
            score = 2,
            author = "Xoleras",
            text = "My friend is having trouble with this quest; where exactly are you suppose to turn it in? Or how?",
            date = "2011-01-22T20:50:46-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26551#comments:id=1304859",
        },
        {
            id = 1593856,
            score = 2,
            author = "jtbalogh",
            text = "Stand at location 61,44, near portal",
            date = "2011-12-10T14:06:05-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26551#comments:id=1593856",
        },
        {
            id = 1691578,
            score = 1,
            author = "1016717",
            text = "Stand at location 61,44, near portal\n\nStanding there, nothing happens.",
            date = "2012-07-24T04:09:04-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26551#comments:id=1691578",
        },
    },
    [26552] = {
        {
