        {
            id = 1256228,
            score = 21,
            author = "81657",
            text = "No one mentioned anything about this guy. He's been around since launch; he was an escort quest before 4.0.3a in that blackrock cave up north, where you picked him up, pick up his weapons, kill a few -hundred- orcs to make your way back to Lakeshire.",
            date = "2010-12-24T07:06:35-06:00",
