    [26592] = {
        {
            id = 1179595,
            score = 40,
            author = "675091",
            text = "Don't get all excited if you have the insanity title and all the pirates are friendly!\n\n----The Sapphire/Ruby are just out laying around on top of crates or along the ground!",
            date = "2010-11-23T23:29:54-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26592#comments:id=1179595",
        },
        {
            id = 1189362,
            score = 13,
            author = "474158",
            text = "Almost definitely a reference to the Pre-Shattering [quest=4243 domain=old], which required a Mithril Casing made by an engineer and was fiendishly annoying to get, requiring a trek (If you were alliance in early vanilla) all the way over to Ironforge to grab one off of the Auction House. Even when AH's were instituted in all cities, a painfully long trek was necessary: to fly all the way up to Darnassus, which could take 15 minutes, each way.",
            date = "2010-11-27T02:16:30-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26592#comments:id=1189362",
        },
        {
            id = 1797835,
            score = 9,
            author = "784002",
            text = "If you went down to the coordinates and saw zombie trolls, just go back a little bit.  The pirates are up the hillside slightly.",
            date = "2013-01-13T11:20:38-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26592#comments:id=1797835",
        },
        {
            id = 1374649,
