            text = "You need to do The Holy Water of Clarity (http://www.wowhead.com/quest=26433) to unlock Primal Reagents of Power (http://www.wowhead.com/quest=26434) and Diffractory Chromascope (http://www.wowhead.com/quest=26592).",
            date = "2011-03-24T01:32:29-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26592#comments:id=1374649",
        },
        {
            id = 1207090,
            score = 7,
            author = "718684",
            text = "Confirmed both the sapphire and ruby can be found at the coordinates shown on the Relevant Locations map. Note that these are items to be picked up and not drops!",
            date = "2010-12-04T23:23:30-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26592#comments:id=1207090",
        },
    },
    [26593] = {
