            author = "JezebelJay",
            text = "Would just like to add a tip here - while you are collecting the giblets, also grab a gorilla fang - you will need one for Heart of Mokk, the follow-on.\n\nJust saves you going back out and having to kill more.",
            date = "2016-02-17T13:08:51-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26593#comments:id=2307357",
        },
        {
