    [26595] = {
        {
            id = 1339639,
            score = 80,
            author = "762202",
            text = "The quest name pretty much sums up World of Warcraft..",
            date = "2011-02-17T09:59:26-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26595#comments:id=1339639",
        },
        {
            id = 1243852,
            score = 36,
            author = "wharris",
            text = "When you return the items...\n\n\"Sea Wolf\" MacKinley says: Alright, let's try cracking this thing open!\n\"Sea Wolf\" MacKinley tries opening Maury's Clubbed Foot...\n\"SeaWolf\" MacKinley says: Aha! It opened! I expected that to be harder. Thanks for your help, !\n\n[Reference to the now-removed Cracking Maury's Foot (http://old.wowhead.com/quest=613)]",
            date = "2010-12-18T17:44:42-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26595#comments:id=1243852",
        },
        {
            id = 1252350,
            score = 13,
            author = "733583",
            text = "Found Juntz on the shore around 57.xx, 54.xx\nFound Ephram near the apes at 56.xx, 50.xx\nFound Maury on the shore at 59.xx, 49.xx",
