    [26597] = {
        {
            id = 1188003,
            score = 32,
            author = "niisama",
            text = "I was a little thrown off by this quest.  It requires you have a Gorilla Fang for starters, and the quest marker is a little misleading.  When you get to the valley the marker is placed in, there is a cave north of the quest marker with a Troll Witch Doctor (the one mentioned in the quest text) that starts an event where different Gorilla's charge up the trail and attack you leading up to Mokk himself.",
            date = "2010-11-26T15:04:54-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26597#comments:id=1188003",
        },
        {
            id = 1206971,
            score = 23,
            author = "Pwnzoar",
            text = "I could've sworn I cured this guy a couple years back. And then again a couple months later, and I think a third time. And I know my friend cured him again later. Shouldn't he have built up an immunity to this by now?",
            date = "2010-12-04T21:47:42-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26597#comments:id=1206971",
        },
        {
            id = 1669755,
            score = 21,
            author = "Lovestar",
            text = "...technically... CAPE of Stranglethorn Fever....\n\nThat's cute. They added this line in Cataclysm, since Stranglethorn Vale got split into two zones, Northern Stranglethorn and Cape of Stranglethorn.",
            date = "2012-05-22T23:04:16-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26597#comments:id=1669755",
        },
        {
            id = 1663689,
