            author = "Soeroah",
            text = "Pretty specific cure. I'd hate to be the second guy to contract Stranglethorn Fever.",
            date = "2012-05-07T02:28:13-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26597#comments:id=1663689",
        },
        {
            id = 1201111,
            score = 8,
            author = "albacore",
            text = "Witch Doctor Unbagwa (http://www.wowhead.com/npc=1449) is located in a cave at (54.2, 46.5) in The Cape of Stranglethorn.  You'll need one Gorilla Fang (http://www.wowhead.com/item=2799) to start the event, after which three gorillas appear one at a time.  The last gorilla will be Mokk the Savage (http://www.wowhead.com/npc=1514), who will drop the item needed to complete the quest.",
            date = "2010-12-01T21:37:15-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26597#comments:id=1201111",
        },
    },
