    [26613] = {
        {
            id = 1424871,
            score = 26,
            author = "MelindaTX",
            text = "I have the same problem  (patch 4.1) - the Bloodsail Raiders (and the rest of the Bloodsail mobs in the area) are all green to me - even though my rep says I'm \"Hated\". GM says he'll open a ticket with QA regarding the issue.\n\nI tried:\n\n1. Deleting the quest, logging out/in, and getting the quest again.\n2. AOE'ing the mobs since I couldn't attack them directly (no effect)\n\nNow, here's what worked for me:\n\nGo get quest \"https://www.wowhead.com/quest=26634 (hopefully you've not done it yet)\nCollect Bushel of Limes (boxes are near trees surrounding the ship)\nEach time you collect a Bushel of Limes, a Lime Thief will pop and attack you.\nThere's a small chance (10%? 20%?) that the Lime Thief will drop snuff.\n\nYou'll collect your 5 crates of limes way before you get enough snuff (15 pieces) so you can just delete your limes from inventory and go collect some more to keep trying. Rinse, repeat until you have 15 pieces of snuff. Hopefully they'll fix this quest next patch.",
            date = "2011-05-22T17:36:09-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26613#comments:id=1424871",
        },
        {
            id = 1198779,
            score = 14,
            author = "84334",
            text = "If you haven't done The Bane of Many A Pirate (http://www.wowhead.com/quest=26634) and you want to keep your Bloodsail (http://www.wowhead.com/faction=87) rep as high as possible, wait until you're doing that quest to get Snuff, as the mobs that spawn when you collect limes drop Snuff, but don't drop your Bloodsail rep.  You can get the lime quest after you finish Seeing Where Your Loyalties Lie (http://www.wowhead.com/quest=26629) - look at that quest for the chain it's in.",
            date = "2010-11-30T20:49:18-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26613#comments:id=1198779",
        },
        {
            id = 1639058,
            score = 10,
            author = "corilan75",
            text = "If you are trying to keep as much of your Bloodsail rep as possible, you can also kill Brutus (http://www.wowhead.com/npc=2551) for the snuff. He has a pretty quick respawn rate, usually drops 2-3 snuff every other kill, and you don't lose any Bloodsail rep for killing him. He also seems to have a high drop rate for Dizzy's Eye (http://www.wowhead.com/item=3897), for the quest Keep An Eye Out (http://www.wowhead.com/quest=26614).",
            date = "2012-03-13T13:20:28-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26613#comments:id=1639058",
        },
        {
            id = 1243801,
            score = 9,
            author = "wharris",
            text = "This quest becomes available when you start Details of the Attack (http://www.wowhead.com/quest=26612)",
            date = "2010-12-18T17:17:27-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26613#comments:id=1243801",
        },
        {
            id = 1425509,
            score = 9,
            author = "726197",
            text = "At about 45/60 I got stuck with quests and also not able to kill the bloodsail pirates. I realized there must be some sort of phasing and went back to the three ships south east. There I was able to pick up a follow up quest from captain Keelhaul. Attracting Attention (http://www.wowhead.com/quest=26644) brought me back in business.",
            date = "2011-05-23T14:15:19-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26613#comments:id=1425509",
        },
    },
    [26614] = {
        {
            id = 1429973,
            score = 27,
            author = "662504",
            text = "There's an elemental type mob (looks more like a mechanical, but it goes as elemental) at the steering wheel of one of the Bloodsail ships off the eastern coast. His/her/its name is Brutus (http://www.wowhead.com/npc=2551) and killing him/her/it did not make me lose any Bloodsail rep. Also according to the wowhead comments on the pre-shattering version of this quest he used to have a 100% or at least very high drop rate for the eye. After one kill I cannot tell if it's still that high but he did drop the eye for me immediately (after I lost like 200 Bloodsail rep for killing pirates without getting the quest item, sigh. So if you want to do those quests and keep the Bloodsail rep damage as low as possible go straight for Brutus.)",
            date = "2011-05-29T09:38:29-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26614#comments:id=1429973",
        },
        {
            id = 1970366,
            score = 13,
            author = "Hildur",
            text = "If you find yourself having this quest while doing the bloodsail quest chain, and the npcs are friendly, there's a quest in the chain https://www.wowhead.com/quest=26664 that lets you attack bloodsail corsairs, and I had the eye drop this way.\n\nHowever, completing the quest decreased my bloodsail rep and did not open any more quests for me in booty bay.",
            date = "2014-06-05T21:08:47-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26614#comments:id=1970366",
        },
        {
            id = 1243803,
            score = 9,
            author = "wharris",
            text = "This quest becomes available when you start Details of the Attack (http://www.wowhead.com/quest=26612)",
            date = "2010-12-18T17:18:33-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26614#comments:id=1243803",
        },
        {
            id = 1248738,
            score = 9,
            author = "37743",
            text = "Uh...\n\nAn enchanted glass orb from Menethil, that's used as an eye?\n\nLike... The Eye of Paleth (http://www.wowhead.com/quest=25819)?",
            date = "2010-12-20T19:44:33-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26614#comments:id=1248738",
        },
        {
            id = 1385657,
            score = 6,
            author = "Nikai",
            text = "Currently, if your reputation with Bloodsail Buccaneers is Friendly or better those NPCs cannot be directly attacked even if you set yourself to be \"At War\" with them.\n\nThere are two ways I found that will let you get around this.\n\nFirst, you can group with someone else and let them kill them for you. You will still get credit for  the \"Slay X\" quests and be able to loot them for quest drops. Note that you will still take the reputation loss for the NPCs killed even though you did not help kill them.\n\nSecond, you can use an AoE ability to kill them and they will still take damage even though you cannot directly attack them.",
            date = "2011-04-06T16:18:56-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26614#comments:id=1385657",
        },
    },
    [26616] = {
        {
            id = 1280745,
            score = 24,
            author = "757448",
            text = "The boat is located at 34.4 45.9",
            date = "2011-01-06T15:19:43-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26616#comments:id=1280745",
        },
        {
            id = 1365370,
            score = 13,
            author = "402208",
            text = "I was having a hard time figuring out how to do this quest, but mostly because I play on a pvp server and kept getting ganked by a shaman at the time. :P\n\nThe boat that you are suppose to take is on the left side of the bridge close to where you would do the quest to kill the murlocs. Just head outside of the Inn and keep walking to your left past the boulder that the villagers are trying to move. You'll be able to spot the boat that they all are in in no time. :) Hope this was helpful.",
            date = "2011-03-12T22:38:37-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26616#comments:id=1365370",
        },
        {
            id = 1205456,
            score = 12,
            author = "123042",
            text = "John J. Keeshan says: Looks like we got a war to win.\nDanforth says: PAIN TRAIN INCOMING!\nKrakauer says: JOHNNY'S BACK, BABY! YEA!\n\nJohn J. Keeshan says: Take us out, Messner.\nMessner says: You got it, Johnny!\n\nJohn J. Keeshan says: We're here, everybody out!\nJohn J. Keeshan says: Danforth, report.\nDanforth says: The Blackrock orcs blew up the bridge leading to Stonewatch Keep. Frontal assault is out of the question.\nJohn J. Keeshan says: Krakauer?\nKrakauer says: Two ways to get behind enemy lines, Johnny. Three if you count bein' dead.\nKrakauer says: North through Alther's Mill, but we'd have to cut through an army of bloodthirsty worgs or south through Render's Valley.\nJohn J. Keeshan says: Jorgensen, what do you have on Render's Valley?\nJorgensen says: Blackrocks all over the damned place, Johnny. One main tower at the choke and two smaller huts. It's a death trap.\nJohn J. Keeshan says: Death trap, eh? Messner, I got a plan. Gonna need some seaforium.\nMessner says: Seaforium? Where the hell am I gonna get seaforium from, Johnny?\nJohn J. Keeshan says: Not my problem, Messner. Make it happen.\nJohn J. Keeshan says: , get your crap ready. I'm sending you out into the field.",
            date = "2010-12-04T03:52:59-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26616#comments:id=1205456",
        },
        {
            id = 2073971,
            score = 12,
            author = "sivla",
            text = "They are in a boat next to the pier right before you get to the murlocs, the pier is to the left of the bridge as you come out of the townhall or from the inn",
            date = "2014-12-21T20:20:25-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26616#comments:id=2073971",
        },
        {
            id = 1470896,
            score = 10,
            author = "202790",
            text = "I like how Messner the mage blasts flame to drive the boat fast like a skiff.",
            date = "2011-07-15T16:09:30-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26616#comments:id=1470896",
        },
    },
    [26617] = {
        {
            id = 1371218,
            score = 28,
            author = "weirdunclebob",
            text = "He said he'd pay me it's worth in gold then gave me 65 silver, the cheapskate! lol",
            date = "2011-03-19T22:32:56-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26617#comments:id=1371218",
        },
        {
            id = 1270239,
            score = 21,
            author = "136440",
            text = "Dropped by the worgen pirate \"Good Boy\" Bruce.\n\nWhen you turn in the coin, Seahorn walks to the edge of the deck he and the Baron are standing on and casts the coin into the sea.  Then he salutes and stares out into the water for a short while.",
            date = "2010-12-31T19:31:21-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26617#comments:id=1270239",
        },
        {
            id = 1515928,
            score = 7,
            author = "662029",
            text = "When turning this in - I also got rep with Ratchet, Gadgetzan, and Everlook. I got 82/83 with them. I have the guild rep perk, so I would assume that those each are rewarding about 75 rep w/o perk.",
            date = "2011-09-11T22:38:32-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26617#comments:id=1515928",
        },
        {
            id = 1810419,
