            author = "Spose",
            text = "You are not able to turn this quest in if you're Unfriendly or At War with Booty Bay.",
            date = "2013-02-07T15:01:41-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26617#comments:id=1810419",
        },
        {
            id = 1708504,
            score = 4,
            author = "1017142",
            text = "He's a Tauren pirate with a white shirt. If approaching from sea or air you'll see him standing on a ship's hull used as a balcony high up on the far right side of the town. If entering on foot, look for the Salty Sailor Tavern and go to its highest level.\n\nEasiest directions on foot: Entering Booty Bay, walk straight along its lowest level until you see a green bamboo platform. Walk up it and go straight, circling around Fin Fizracket (lying in his little shack.) Past him you'll see two Goblins standing on either side of an alley, above which is a sign that says \"Salty Sailor Tavern.\" Enter and keep heading up the stairs until you finally arrive at the hull balcony.\n\nNote: When arriving by wind rider, he's just a turn of a corner away.",
            date = "2012-09-02T23:51:56-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26617#comments:id=1708504",
        },
    },
    [26618] = {
        {
            id = 1208433,
            score = 6,
            author = "123042",
            text = "While The Night Watch (http://www.wowhead.com/quest=26645) is the direct next step of this quest, completing this quest also unlocks The Hermit (http://www.wowhead.com/quest=26627) and (confusingly) Look To The Stars (http://www.wowhead.com/quest=26683).\nYou can take Supplies from Darkshire (http://www.wowhead.com/quest=26653) directly from the NPC without The Hermit (http://www.wowhead.com/quest=26627) though.",
            date = "2010-12-05T14:57:06-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26618#comments:id=1208433",
        },
        {
            id = 1341509,
            score = 4,
            author = "242813",
            text = "Do this quest alongside Seasoned Wolf Kabobs (http://www.wowhead.com/quest=26620). Kill two birds quests with one stone mob.",
