    [26627] = {
        {
            id = 1523441,
            score = 10,
            author = "225109",
            text = "Whoever plans to explore the lores of Duskwood (questing), get all the quest from Darkshire, but do this quest first as soon as you get it.\n\nAfterwards, place your priorities on the quest offered by Abercrombie (http://www.wowhead.com/npc=289). (i.e. get the quest from Abercrombie, finish the quest, then come back to turn it in)\n\nThis is because Abercrombie's quest will send you everywhere the townsfolk from Darkshire will send you to do quest. If you follow Abercrombie's quest line you will be able to finish all the quest offered in Darkshire on the way.\n(if you do the quest from Darkshire first, you will end up coming back to the same place to do Abercrombie's quest)",
            date = "2011-09-20T23:19:39-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26627#comments:id=1523441",
        },
        {
            id = 1519634,
            score = 7,
            author = "553695",
            text = "After completion Abercrombie offers you Supplies from Darkshire decent questline.",
            date = "2011-09-16T19:45:14-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26627#comments:id=1519634",
