            text = "This quest is unobtainable if you went to see Abercrombie (http://www.wowhead.com/npc=289/abercrombie) and accepting the Supplies from Darkshire (http://www.wowhead.com/quest=26653/supplies-from-darkshire) Quest before talking to Commander Althea Ebonlocke (http://www.wowhead.com/npc=264/commander-althea-ebonlocke).",
            date = "2017-02-28T21:16:28-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26627#comments:id=2474901",
        },
    },
