        {
            id = 2866784,
            score = 92,
            author = "alvinleong",
            text = "I found it interesting that I had absolutely no qualms butchering dozens of sentient beings in other quests, but when it came to a single cow, I came to Wowhead to see if there was a workaround.",
            date = "2019-01-19T02:49:17-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26630#comments:id=2866784",
