        },
    },
    [26633] = {
        {
            id = 1320827,
            score = 70,
            author = "779407",
            text = "As it turns out,  \"Pretty Boy\" Duncan now has a gossip option allowing players to complete the quest by paying him 1g. yay!",
            date = "2011-02-03T19:33:12-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26633#comments:id=1320827",
        },
        {
            id = 1590471,
            score = 27,
            author = "QuickBASIC",
            text = "You can pay https://www.wowhead.com/npc=2545 (just outside the door from the lower decks) 1g to swab the decks for you if you don't want to do the minigame.",
            date = "2011-12-05T12:19:16-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26633#comments:id=1590471",
        },
        {
            id = 1250700,
            score = 24,
            author = "stevenj",
            text = "I was having a terrible time with this quest. Having trouble targeting running around, everything people are complaining about.  Worse, I have a mac with a one-button mouse, so right-clicking requires me to hold down a key, so it is hard to do that and move at the same time.\n\nThe solution was to set up two key bindings:\n\n1) create a macro for \"/target deck stain\" and drag it onto your button bar for key 1\n\n2) in key bindings, bind key 2 to \"interact with target\"\n\nThen you just run around and hit \"1 2\" over and over again.  No need to stop moving, no need to target.  Becomes fairly easy.\n\nI hope this helps a few other people.",
            date = "2010-12-21T17:27:43-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26633#comments:id=1250700",
        },
        {
            id = 1179737,
            score = 20,
            author = "126504",
            text = "You have to finish the side quests on the boat (the cannonballs for Duncan and the bushels of lime for Garr) as well for this to lead to attracting attention.",
            date = "2010-11-24T00:28:00-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26633#comments:id=1179737",
        },
        {
            id = 1711712,
            score = 10,
            author = "bookworm13",
            text = "Did anyone else think while they were running around like crazy that it would be much easier to murder that *$!<?@ vulture flying around?",
            date = "2012-09-10T04:28:55-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26633#comments:id=1711712",
        },
    },
    [26634] = {
        {
            id = 1179817,
            score = 11,
            author = "379829",
            text = "Crates are by trees over on Wild Shore.  Once looted a mob comes out to attack you.",
            date = "2010-11-24T01:03:34-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26634#comments:id=1179817",
        },
        {
            id = 1389321,
            score = 7,
            author = "Bu66ie",
            text = "I experienced the same issue as above while multiboxing my 37 Warrior and 36 Rogue, but only on my Warrior, weird. After submitting a ticket to GM, I got the standard \"thank you, this issue has been elevated to our QA department\" reply.\n\nAfter trying to logout from the game in several locations, with no success, I flew to Northern STV, which caused me to loose the \"Piracy\" buff. Upon return to Cape STV, the \"Piracy\" buff returned and reset. The Bloodsail mobs now appeared friendly, allowing me to turn in \"Cannonball\" and \"Bane Of Every Pirate\" quests.\n\nIt appears that a work around for this issue is to leave the Cape STV area completely and then return, until Blizz can correct the issue.\n\nOh, once you have reset the buff, I would recommend not logging out, as I did, because logging appears to re-create the issue, again, and the Bloodsail mobs will once again turn unfriendly. I had to leave the area and fly back in to reset the \"Piracy\" buff (p.i.t.a.).",
            date = "2011-04-11T18:28:26-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26634#comments:id=1389321",
        },
        {
            id = 1562494,
            score = 7,
            author = "littlewener",
            text = "If you have a flying mount, just fly straight out to sea until you leave the area (Fatigue starts and then you leave cape of STV and are in STV as a whole).  Turn around and fly back and it is fine.",
            date = "2011-11-04T03:35:58-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26634#comments:id=1562494",
        },
        {
            id = 1960620,
            score = 5,
            author = "nahkhaz",
            text = "Dead men steal no limes!\n\nNo truer words were ever spoken.",
            date = "2014-04-23T09:44:47-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26634#comments:id=1960620",
        },
        {
