    [26641] = {
        {
            id = 1622177,
            score = 8,
            author = "943866",
            text = "In order to get any of the quests at Quel'Danil Lodge, you have to pick up the quest trail from Tracker Yoro at the Steelwing Camp near Jintha'alor.",
            date = "2012-02-05T20:27:12-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26641#comments:id=1622177",
        },
        {
            id = 1468804,
            score = 2,
            author = "317852",
            text = "Seems like there are some prerequisites. I came to Gilda today as lvl 35 and she wouldn't give me any quests.\nI hadn't done any quests in the Hinterlands beforehand.",
            date = "2011-07-13T10:32:57-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26641#comments:id=1468804",
        },
        {
            id = 1670611,
            score = 2,
            author = "Zylostout",
            text = "Before you can pick up the quest from Tracker Yoro you have to complete a series of quests for Fraggar Thundermantle and Doran Steelwing, ending with \"Hunt the Keeper\".  Fraggar Thundermantle and Doran Steelwing are also in Steelwing camp. (64, 60)",
            date = "2012-05-26T18:00:07-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26641#comments:id=1670611",
        },
        {
            id = 1120177,
            score = 1,
            author = "447186",
            text = "Eggs can be collected all around (45.6 39.2). You may as well do the quest \"The Eye of Shadra (http://cata.wowhead.com/quest=26381#comments:id=1120175)\" while you're there.",
            date = "2010-09-13T18:40:38-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26641#comments:id=1120177",
        },
    },
    [26642] = {
