            author = "mishii",
            text = "If you are having problems finding this quest, and have not completed any quests that would block you (Warchief's Command: Northern Barrens, or the followup quests for the Conscript Breadcrumb - Defense of Far Watch and Far Watch Offensive), you have a possible solution.\n\nChange your Chromie Time to CATACLYSM and he should have the quest for you! (as well as a few others in that room you might not have picked up).",
            date = "2023-04-07T08:12:09-05:00",
