    [26644] = {
        {
            id = 1195130,
            score = 92,
            author = "Rhynchelma",
            text = "I had to do Cannonball Swim (http://www.wowhead.com/quest=26635) and The Bane of Many A Pirate (http://www.wowhead.com/quest=26634) before I could get Attracting Attention (http://www.wowhead.com/quest=26644).\n\nAfter completing Ol'Blasty (http://www.wowhead.com/quest=26647) and its follow-up and Our Mortal Enemies (http://www.wowhead.com/quest=26648), Fleet Master Firallon (http://www.wowhead.com/npc=2546)  gives you The Damsel's Luck (http://www.wowhead.com/quest=26650).",
            date = "2010-11-29T06:36:08-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26644#comments:id=1195130",
        },
        {
            id = 1183176,
            score = 9,
            author = "Sygmoral",
            text = "Leads to Ol' Blasty (http://www.wowhead.com/quest=26647) (from the orc Ironpatch (http://www.wowhead.com/npc=2547) a few yards away) and Our Mortal Enemies (http://www.wowhead.com/quest=26648) (from the dwarf \"Dead-Eye\" Drederick McGumm (http://www.wowhead.com/npc=43556) on the deck).",
            date = "2010-11-24T22:40:20-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26644#comments:id=1183176",
        },
        {
            id = 1495107,
            score = 7,
            author = "InfiniteIce",
            text = "Confirming that you must do https://www.wowhead.com/quest=26634 and https://www.wowhead.com/quest=26635 before you can open https://www.wowhead.com/quest=26644\n\nAs of 4.2.0",
            date = "2011-08-14T18:28:18-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26644#comments:id=1495107",
        },
        {
            id = 1511498,
            score = 5,
            author = "SockPuppet",
            text = "I hearthed after picking up this quest, and when I went back to the boats, the pirates were all red again (although they didn't aggro and were unattackable, I couldn't interact with them at all). I opened a ticket and the response was to reset my entire UI. To avoid dealing with this, I suggest you don't hearth in the middle of this quest chain as I suspect it's more bug than individual UI issue.",
            date = "2011-09-06T15:09:04-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26644#comments:id=1511498",
        },
        {
            id = 1514740,
