    [26646] = {
        {
            id = 2547684,
            score = 184,
            author = "Neverknow",
            text = "This quest has become infuriatingly annoying to finish as of 7.3.5. The orcs will spot you from a long distance, the distraction usually can't pull them far away enough to properly sneak past them, and when you get pulled into combat you can't get rid of the kit to even try and fight your way out. Expect to die a lot of times. In fact it might just be easiest to bring a level 60+ to just kill everything instead. I suspect these problems arise due to scaling.",
            date = "2018-01-21T14:24:59-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26646#comments:id=2547684",
        },
        {
            id = 1449577,
            score = 95,
            author = "Kodel",
            text = "Entrance to the cave is 68,74.",
            date = "2011-06-24T12:44:52-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26646#comments:id=1449577",
        },
        {
            id = 1706117,
            score = 33,
            author = "1025314",
            text = "It seems as of 5.0.4, using Distraction near the cave at the south end of the zone results in a No Path Available error. Good luck getting into the cave -- those orcs ain't gonna move, nor will cholorforming them work, as their backs are against the cave mouth's wall. And that Drake Rider is affected as well.",
            date = "2012-08-30T03:11:09-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26646#comments:id=1706117",
        },
        {
            id = 2550646,
            score = 28,
            author = "Tarkovsky",
            text = "This is the worst quest in the entire game. I died a total of 47 times (yes, you read that right) trying to get into the cave. The guy inside is supposed to be facing in so you can chloroform him, but using the distraction ability on the two in the front means he faces out. I tried placing it innumerable places and it would not work.\n\nI finally decided to position my ghost in the cave, then log in a level 110 character and come and kill all the orcs, then log in and loot the key. Except, whoops, my 110 character is in a different phase and the cave is not even there!\n\nScrew this quest. I've never hated anything in a video game this much until now. I am deeming it literally uncompletable.",
            date = "2018-02-04T14:41:25-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26646#comments:id=2550646",
        },
        {
            id = 1189988,
            score = 24,
            author = "4318",
            text = "Awesome quest, we need more like this in the game.\n\nAfter you start the quest, follow the instructions and use the Kit they give you and immediatly go into Stealth mode via the Camouflage key.\n\nInstructions:\n1.  Go to the Cave and use your new DISTRACT ability pull the Guard on the Dragon and the two Orcs guarding the Cave entrance away.\n\n2.  Go into the Cave, use your new \"Chloroform\" ability on the guard who is at the back of the cave.\n\n3.  Get the key.\n\n4.  Leave the Cave, but don't forget to cast DISTRACTION again to get the guys away from the door.\n\n5.  Then go to where the Prisoners are held and free them.",
            date = "2010-11-27T08:57:48-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26646#comments:id=1189988",
        },
    },
    [26647] = {
        {
            id = 1188623,
            score = 16,
            author = "Sygmoral",
            text = "Prerequisite for this quest is the chain that starts with the quest The Bloodsail Buccaneers (http://www.wowhead.com/quest=26609).",
            date = "2010-11-26T19:14:58-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26647#comments:id=1188623",
        },
        {
            id = 1258490,
            score = 12,
            author = "Aletto",
            text = "This quest is bugged on my server, and it might be on yours too.\n\nIf you see the target dummy (Smilin' Timmy Sticks) just sticking out of the water, and an empty rowboat moving around, it's bugged.\n\nI'm guessing the dummy is supposed to be on the rowboat moving around with it.\n\nI tried hitting the rowboat, but the hits didn't register. I also tried hitting the dummy, and found that the hits only registered when the rowboat was very near to the dummy.\n\nI had to wait for the rowboat to come around three times, since you can average only two hits before the rowboat gets too far away and hitting the dummy no longer registers.",
            date = "2010-12-25T15:58:30-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26647#comments:id=1258490",
        },
        {
            id = 1618303,
            score = 8,
            author = "weirdunclebob",
            text = "On completion, Ironpatch says, \"I like the cut of your gib, . It should be 'jib' as in the type of headsail. It's an old nautical saying. Sailors would recognise the nationality of other ships by the shape of the jib so to say you liked the cut of someone's jib meant you considered them worthy of being an ally.\n\nBy the way, gib has many meanings, none of which really make sense in this instance. There is a bit of humour in the meaning: 'A castrated male cat or ferret' but I think that's a bit too obscure!",
            date = "2012-01-29T04:18:30-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26647#comments:id=1618303",
        },
        {
            id = 1358526,
            score = 4,
            author = "Valcake",
            text = "When doing these quests, I had logged out to get some food (most important thing in life, keep that in mind! =P)\n\nWhen I logged back, they were all hostile to me. The quest giver did have a yellow questionmark for completing the quest but I couldnt talk with them because they were all hostile to me :)\n\nHow did I solve the problem?\n\nFirst of all, I talked with a GM, asked for help... we tried a lot of things, from letting him turn in the quest and other things.\n\nAt the end, I got myself killed by L35 crabs... :( , and retrieved my corpse, that helped luckily :)\n\nSo, if you get the problem that they are hostile to you, try to get killed and the problem might be solved when you retrieved back your body! :)",
            date = "2011-03-05T17:07:40-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26647#comments:id=1358526",
        },
        {
            id = 1693094,
            score = 3,
            author = "Takata",
            text = "Keep the boat trained with holding the right mouse button, load the cannon with 1, as long as the arrows aren't too far away from the boat, quickly press 2 then spam 3. I've fired off at least two but seemed to only hit with one cannon ball.",
            date = "2012-07-28T06:31:42-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26647#comments:id=1693094",
        },
    },
