    [26650] = {
        {
            id = 1188624,
            score = 9,
            author = "Sygmoral",
            text = "Prerequisite for this quest is the chain that starts with the quest The Bloodsail Buccaneers (http://www.wowhead.com/quest=26609), and completing its two followups.\n\nCompleting this quest will spawn three more quests:\n\nThe Brashtide Crew (http://www.wowhead.com/quest=26662)\nSinking From Within (http://www.wowhead.com/quest=26663)\nMaking Mutiny (http://www.wowhead.com/quest=26664)",
