    [26651] = {
        {
            id = 1433211,
            score = 103,
            author = "djkroo",
            text = "I just want to point out that in the tower you do not have to go INSIDE the top part of the tower to plant the explosives, you can just come very close to the wall click your seaforium and you are done.",
            date = "2011-06-03T05:44:54-05:00",
