    [26670] = {
        {
            id = 1303088,
            score = 9,
            author = "629754",
            text = "At the end of this cave is a mound of dirt that is clickable.  when you do click on it it summons a vision of Velinde Starsong who you cannot interact with, but wails and says the following:\n\nVelinde Starsong says: I have failed... I have failed in my duty... failed my people... The worgen run rampant, and the Scythe of my goddess is lost.\nVelinde Starsong says: This evil I have unleashed... In whose hand does the power my goddess granted to me now lie... By whose hand is it directed?\n\nIs this her grave?",
            date = "2011-01-21T13:05:18-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26670#comments:id=1303088",
        },
        {
            id = 1354596,
            score = 7,
            author = "765645",
            text = "The area is a reference to the first Fire Emblem game. One of the last levels of the Main campaign is in a catacomb filled with the lost souls of the damned, all who protect a sword wielded by a legendary warrior named Roland. The warrior Velinde used the legendary weapon that could bring forth the Worgen, or cursed druids attempting to harness the power of the weapon known as the Sycthe of Elune, the weapon Velinde carries.",
            date = "2011-03-01T22:34:09-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26670#comments:id=1354596",
        },
