    [26692] = {
        {
            id = 1208947,
            score = 11,
            author = "wharris",
            text = "Guide to Redridge Quests:\n\nDo these at any time:\nNida's Necklace (http://www.wowhead.com/quest=26508)\nAn Unwelcome Guest (http://www.wowhead.com/quest=26509)\nLake Everstill Cleanup (http://www.wowhead.com/quest=26511)\nWanted: Redridge Gnolls (http://www.wowhead.com/quest=26504)\nFranks and Beans (http://www.wowhead.com/quest=26506)\nThreat to the Kingdom (http://www.wowhead.com/quest=26761) (from Westfall chain)\n\nOptional prequest: Hero's Call: Redridge (http://www.wowhead.com/quest=26365) or Hero's Call: Redridge (http://www.wowhead.com/quest=28563)\nThen a long chain:\nStill Assessing the Threat (http://www.wowhead.com/quest=26503)\nParker's Report (http://www.wowhead.com/quest=26505)\nWe Must Prepare!  (http://www.wowhead.com/quest=26510) (available earlier)\n        Completing the above enables: Like a Fart in the Wind (http://www.wowhead.com/quest=26513)\nTuning the Gnomecoder (http://www.wowhead.com/quest=26512)\nCanyon Romp (http://www.wowhead.com/quest=26514)\n       A gnoll drops dirt-stained scroll (http://www.wowhead.com/item=58898) which allows for He Who Controls the Ettins (http://www.wowhead.com/quest=26519) and Saving Foreman Oslow (http://www.wowhead.com/quest=26520)\nThey've Wised Up (http://www.wowhead.com/quest=26544)\nYowler Must Die! (http://www.wowhead.com/quest=26545)\nJohn J Keeshan (http://www.wowhead.com/quest=26567)\nThis Ain't My War (http://www.wowhead.com/quest=26568)\nWeapons of War (http://www.wowhead.com/quest=26571)\n       Accepting this enables  Render's Army (http://www.wowhead.com/quest=26570) and Surveying Equipment (http://www.wowhead.com/quest=26569)\nHis Heart Must Be In It (http://www.wowhead.com/quest=26573)\nIn Search of Bravo Company (http://www.wowhead.com/quest=26586)  (I'm not sure what the exact prerequisties are)\nBreaking out is hard to do (http://www.wowhead.com/quest=26587)\nJorgensen (http://www.wowhead.com/quest=26560)\nKrakauer (http://www.wowhead.com/quest=26561)\nAnd Last but not Least...Danforth (http://www.wowhead.com/quest=26562)\nReturn of the Bravo Company (http://www.wowhead.com/quest=26563)\nThey Drew First Blood (http://www.wowhead.com/quest=26607)\nIt's Never over (http://www.wowhead.com/quest=26616)\n\nThen do these together:\nBravo Company Field Kit: Camouflage (http://www.wowhead.com/quest=26636)\nBravo Company Field Kit: Chloroform (http://www.wowhead.com/quest=26637)\nHunting the Hinters (http://www.wowhead.com/quest=26638)\nPoint of Contact: Brubake (http://www.wowhead.com/quest=26639)r and Unspeakable Atrocities (http://www.wowhead.com/quest=26640)\n\n(Main chain Continues)\nPrisoners of War (http://www.wowhead.com/quest=26646)\nTo Win a War, You Gotta Become War (http://www.wowhead.com/quest=26651)\nDetonation (http://www.wowhead.com/quest=26668)\n    (Shadowhide Extinction (http://www.wowhead.com/quest=26692) now available)\nThe Dark Tower (http://www.wowhead.com/quest=26693)\nThe Grand Magus Doane (http://www.wowhead.com/quest=26694)\nAHHHHH! AHHHHHHHHHHHH! (http://www.wowhead.com/quest=26708)\nShowdown at Stonewatch (http://www.wowhead.com/quest=26713)\nDarkblaze, Bood of the Worldbreaker (http://www.wowhead.com/quest=26714)\nTriumphant Return (http://www.wowhead.com/quest=26726)\n\nA truly epic chain!",
            date = "2010-12-05T19:05:02-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26692#comments:id=1208947",
        },
        {
            id = 1334177,
            score = 1,
            author = "192408",
            text = "You dont have to finish this quest to continue the redridge chain.",
            date = "2011-02-13T04:23:28-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26692#comments:id=1334177",
        },
        {
            id = 1620834,
            score = 1,
            author = "Keril",
            text = "A truly epic chain! - Wharris\n\nCouldn't agree more, one of the best in WoW today!",
            date = "2012-02-03T17:39:13-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26692#comments:id=1620834",
        },
        {
            id = 1309731,
            score = 0,
            author = "773529",
            text = "not sure it this matters, but I did all the quests through Darkblaze & couldn't turn this quest in b/c npc was no longer living.",
            date = "2011-01-25T18:03:17-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26692#comments:id=1309731",
        },
        {
            id = 1943487,
            score = 0,
            author = "Pastoral",
            text = "Danforth survives the encounter with Darkblaze. I didn't actually complete this particular quest before defeating Darkblaze and completing Triumphant Return. Then one day, I happened by Redridge and landed at Keeshan's Post. Troteman was still there, staring through his telescope at the place where Bravo Company met its apparent demise under the fiery breath of Darkblaze. I then went through and effortlessly slaughter the remaining gnolls required to complete the mission. And Danforth paged me through the gnomecorder to complete the mission. Keeshan's voice was also heard in the background.\n\nPerhaps one day, I shall see Danforth again. Is it also possible that Messner, Jorgensen and Krakauer similarly survived?",
            date = "2014-02-15T07:35:28-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26692#comments:id=1943487",
        },
    },
    [26693] = {
        {
            id = 1332287,
            score = 18,
            author = "jtunis",
            text = "I cannot believe Stephen King's epic series has yet to be mentioned here. This page should be covered in Stephen King quotes.",
            date = "2011-02-11T19:00:50-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26693#comments:id=1332287",
        },
        {
            id = 1482435,
            score = 11,
            author = "818594",
            text = "Quest giver John J.Keeshan [ coords 77.73, 65.43]  Shalewind Canyon ,East of Renders Valley.\n\nGnoll General 'Fangore' : Alcove in Galardell Valley ,standing alone in a small cave.\n\n*You can take out the 20 gnolls required for quest  'The Shadowhide extinction'  along the way*\n\nGo North  through the camp behind the quest giver. Follow the torch lined path above Stonewatch Falls. Hugging the wall continue North past a large stone Lion statue. Just past a very large tree you will come upon a lone gnoll standing on a  grassy hill guarding the alcove in the valley where the cave is 'hidden'.   [ coords 67.55 ,30.52 ] Make him take a dirt nap.\nKill Gen.Fangore [ health 866 ] .The key is located in a pouch hanging on a stalagmite nearby. The tower is located directly across from the cave.",
            date = "2011-07-29T12:15:31-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26693#comments:id=1482435",
        },
        {
            id = 1208951,
            score = 6,
            author = "wharris",
            text = "Guide to Redridge Quests:\n\nDo these at any time:\nNida's Necklace (http://www.wowhead.com/quest=26508)\nAn Unwelcome Guest (http://www.wowhead.com/quest=26509)\nLake Everstill Cleanup (http://www.wowhead.com/quest=26511)\nWanted: Redridge Gnolls (http://www.wowhead.com/quest=26504)\nFranks and Beans (http://www.wowhead.com/quest=26506)\nThreat to the Kingdom (http://www.wowhead.com/quest=26761) (from Westfall chain)\n\nOptional prequest: Hero's Call: Redridge (http://www.wowhead.com/quest=26365) or Hero's Call: Redridge (http://www.wowhead.com/quest=28563)\nThen a long chain:\nStill Assessing the Threat (http://www.wowhead.com/quest=26503)\nParker's Report (http://www.wowhead.com/quest=26505)\nWe Must Prepare!  (http://www.wowhead.com/quest=26510) (available earlier)\n        Completing the above enables: Like a Fart in the Wind (http://www.wowhead.com/quest=26513)\nTuning the Gnomecoder (http://www.wowhead.com/quest=26512)\nCanyon Romp (http://www.wowhead.com/quest=26514)\n       A gnoll drops dirt-stained scroll (http://www.wowhead.com/item=58898) which allows for He Who Controls the Ettins (http://www.wowhead.com/quest=26519) and Saving Foreman Oslow (http://www.wowhead.com/quest=26520)\nThey've Wised Up (http://www.wowhead.com/quest=26544)\nYowler Must Die! (http://www.wowhead.com/quest=26545)\nJohn J Keeshan (http://www.wowhead.com/quest=26567)\nThis Ain't My War (http://www.wowhead.com/quest=26568)\nWeapons of War (http://www.wowhead.com/quest=26571)\n       Accepting this enables  Render's Army (http://www.wowhead.com/quest=26570) and Surveying Equipment (http://www.wowhead.com/quest=26569)\nHis Heart Must Be In It (http://www.wowhead.com/quest=26573)\nIn Search of Bravo Company (http://www.wowhead.com/quest=26586)  (I'm not sure what the exact prerequisties are)\nBreaking out is hard to do (http://www.wowhead.com/quest=26587)\nJorgensen (http://www.wowhead.com/quest=26560)\nKrakauer (http://www.wowhead.com/quest=26561)\nAnd Last but not Least...Danforth (http://www.wowhead.com/quest=26562)\nReturn of the Bravo Company (http://www.wowhead.com/quest=26563)\nThey Drew First Blood (http://www.wowhead.com/quest=26607)\nIt's Never over (http://www.wowhead.com/quest=26616)\n\nThen do these together:\nBravo Company Field Kit: Camouflage (http://www.wowhead.com/quest=26636)\nBravo Company Field Kit: Chloroform (http://www.wowhead.com/quest=26637)\nHunting the Hinters (http://www.wowhead.com/quest=26638)\nPoint of Contact: Brubake (http://www.wowhead.com/quest=26639)r and Unspeakable Atrocities (http://www.wowhead.com/quest=26640)\n\n(Main chain Continues)\nPrisoners of War (http://www.wowhead.com/quest=26646)\nTo Win a War, You Gotta Become War (http://www.wowhead.com/quest=26651)\nDetonation (http://www.wowhead.com/quest=26668)\n    (Shadowhide Extinction (http://www.wowhead.com/quest=26692) now available)\nThe Dark Tower (http://www.wowhead.com/quest=26693)\nThe Grand Magus Doane (http://www.wowhead.com/quest=26694)\nAHHHHH! AHHHHHHHHHHHH! (http://www.wowhead.com/quest=26708)\nShowdown at Stonewatch (http://www.wowhead.com/quest=26713)\nDarkblaze, Bood of the Worldbreaker (http://www.wowhead.com/quest=26714)\nTriumphant Return (http://www.wowhead.com/quest=26726)\n\nA truly epic chain!",
            date = "2010-12-05T19:06:20-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26693#comments:id=1208951",
        },
        {
            id = 1528418,
            score = 3,
            author = "endersblade",
            text = "I noticed something while doing the quest today.  There's supposed to be a purple 'magic door' covering the entrance to this tower.\n\nI was on my level 85 mage, helping my F2P 20 war do this quest.  Mage wasn't on the quest, War was.  I was on my way to where I remembered Fangore being, eons ago, the last time I was in this area.  We went by the tower, and I saw the purple door.  I switched over to my war to read the quest...and noticed the door was not there.  Indeed, I could run up into the tower, kill the guy at the top, all that jazz, without getting the key.  However, that isn't part of THIS particular quest.  You still have to get the key to get in.\n\nI understand this isn't that big of a deal.  But it's still a bug.  There are LOTS of people who don't read quests, and might think all they need to do is get to the top of the tower and kill the mage.  That's the next quest, not this one.  I put in a GM ticket about it, and the GM said he would report it further along.  Hopefully this minor annoyance will get fixed.",
            date = "2011-09-27T01:35:07-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26693#comments:id=1528418",
        },
        {
            id = 1185961,
            score = 1,
            author = "678312",
            text = "OK, I'm sorry, I know I've posted several other places, and I don't want to be a pain. But some of the info here is really odd to me. It's listed as Night Elf race quest? Why? And the followup quest, where once you've got the key to the tower of Ilgalar, lists as Horde?\n\nWhere do I input information for database updates? I promise I'm running the wowhead client and profiler every time I log off for the night!",
            date = "2010-11-25T21:05:08-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26693#comments:id=1185961",
        },
    },
