    [26697] = {
        {
            id = 1191642,
            score = 78,
            author = "711373",
            text = "40,73 as Calhoun said, he's right by the horde FP.\n\nAlso as a side note I have to say that the changes they have made to this entire quest line are awesome.  So much more interesting to play and a good use of the phasing quest approach.  Good job Blizz.",
            date = "2010-11-27T21:24:51-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26697#comments:id=1191642",
        },
        {
            id = 1281547,
            score = 34,
            author = "Adornius",
            text = "this questline is obtainable after doing \"Sea Wolf\" MacKinley's quest chain.",
            date = "2011-01-07T00:30:00-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26697#comments:id=1281547",
        },
        {
            id = 1369321,
            score = 31,
            author = "Islorren",
            text = "This one was a bit hard to find for any Alliance members not familiar with the Horde FP.  After you pick up the quest from Baron Revilgaz, turn back around as if to go back into the ship from where you came - but go to the right instead (there's a tiny pathway).  This pathway loops around to the Horde flight master, as well as two goblins shuddering in fear next to him - the goblin on the left is Kebok.  Speak to him and he will fly you around so that you can sink the boats and collect the 75 kills.",
            date = "2011-03-17T14:06:35-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26697#comments:id=1369321",
        },
        {
            id = 1306441,
            score = 15,
            author = "657979",
            text = "By saltedfish 3 days ago (Patch 4.0.3)\nCorrection, \"Sea Wolf\" MacKinley has absolutely nothing to do with this questline, as near as I can tell. You need to go to First Mate Crazz and start the lengthy quest chain stated with The Bloodsail Buccaneers. I just spent the past hour or so completing the various Bloodsail quests (swabbing decks, killing things, etc.) and was sent back to Baron Revilgaz. There, I found some more quests, ultimately leading to this one and the ones after it.\n\nActually, I wasn't able to pick this quest up until after I'd done the seawolf quest, but it's only 2 quests, and it's easy.",
            date = "2011-01-23T15:24:56-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26697#comments:id=1306441",
        },
        {
            id = 5171040,
            score = 11,
            author = "dsiacono",
            text = "Kebok  (npc=737/kebok) was so hard to find but he was actually just a few steps away next to Gringer (npc=2858/gringer). If you have coordinates, go to (40.5,73.2) just around the outside corner from where you picked up the quest.\n\nOnce you find  Kebok (npc=737/kebok), click on him to chat. He'll say \"You sure picked an interesting time to chat with Ol' Kebok.\"\nClick on the section \"Sorry, not here to chat. I need a wind rider to take on a special mission.\" This is a horde wind rider & you'll have to press buttons 1 to throw handbombs & 2 to return back to  Kebok  (npc=737/kebok). The ride is so slow & gentle like riding with your grandmother while flying over the ships filled with Brashtide Crewmen. Kill 85 crewmen & 6 boats to turn in your quest.\n\nIf it helps any, https://www.youtube.com/watch?v=0qIcUqSziNA shows where Kebok is a few seconds after getting the quest.\n\nThe following quest is Bloodsails End (quest=26703/bloodsails-end\\) to kill Fleet Master Furallon (https://www.wowhead.com/npc=2546/fleet-master-firallon)",
            date = "2021-05-06T18:51:51-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26697#comments:id=5171040",
        },
    },
    [26698] = {
        {
            id = 1511126,
            score = 3,
            author = "eskilajnen",
            text = "After turning in this quest Fleet Master Seahorn will offer you https://www.wowhead.com/quest=26700 and https://www.wowhead.com/quest=26699.",
            date = "2011-09-05T23:10:45-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26698#comments:id=1511126",
        },
        {
            id = 1572048,
            score = 2,
