    [26722] = {
        {
            id = 1187733,
            score = 78,
            author = "710125",
            text = "The catacombs are the same environment as every other one in the game. Where to find and kill Morbent Fel:\n\n1. Descend into the Catacombs.\n2. Turn left and go across the wide-open room.\n3. Turn left again to the smaller room.\n4. Go to the northwest corner of the smaller room, and look for a gap in the wall.\n5. Go through the gap and follow the tunnel until you get to the lab room (shown on the dungeon map of the east to the smaller room).\n6. Kill any mobs on your way to Morbent, but don't worry about the ones behind him - as soon as you kill him, they'll all fall over dead.",
            date = "2010-11-26T13:21:26-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26722#comments:id=1187733",
        },
        {
            id = 1219833,
            score = 40,
            author = "Freedomage",
            text = "The hole in the wall is directly behind the big stone block that's right behind the mound you check.",
            date = "2010-12-09T20:44:57-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26722#comments:id=1219833",
        },
        {
            id = 2558044,
            score = 29,
            author = "Wowzir",
            text = "https://www.wowhead.com/quest=26722\n\nThanks to Masatsoki for instructions.   SEE that comment.\n\nThere are TWO Entrances to the Catacombs:\n\n/way Duskwood 23.6, 35.5 Eastern Entr\009\009Dawning Woods Catacombs\n/way Duskwood 20.4, 27.0 GAP in wall\n\nReference ONLY, not the recommended route:\n/way Duskwood 16.2, 38.8 Western Entr   {Morbidus  guards entrance}\n\n;)",
            date = "2018-03-15T13:02:46-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26722#comments:id=2558044",
        },
        {
            id = 1335386,
            score = 8,
            author = "39127",
            text = "You can bring Bravo Company (http://www.wowhead.com/quest=26563#comments:id=1335293) with you through the tunnel, but they will not enter Morbent Fel's room.",
            date = "2011-02-14T00:40:13-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26722#comments:id=1335386",
        },
        {
            id = 6279699,
            score = 2,
            author = "Noctula",
            text = "Ignore the mini map, the crypts ARE connected. Right behind the target of the quest before (The Halls Of The Dead) is a hole in the wall!",
            date = "2026-02-09T10:23:54-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26722#comments:id=6279699",
        },
    },
    [26723] = {
        {
            id = 1187772,
            score = 40,
            author = "albacore",
            text = "The objective is located upstairs in the house at (17.0, 33.4) in Duskwood.  Click on the Bloodsoaked Hat (http://www.wowhead.com/object=204816) and the objective will be complete.",
