    [26725] = {
        {
            id = 1374535,
            score = 6,
            author = "Pypode",
            text = "Go down, turn to your right into large room. Run thru room into far room. L-24 Corpses abound. Far back alcove, small mound of dirt.  Pick up piece. Enter and follow tunnel at back of alcove. L-25 Writhing Terrors lurk in tunnel. Three, when i went through.\nFinal piece. Continue thru to find Morbent Fel (25) (couple of more Terrors in tunnel) L-24 humanoids inside room at the end. Morbent has two L23 guards, didnt agro when I killed each one--use the Bane to weaken and defeat Morbent.\nHOWEVER, behind Morbent, upstairs is a mob of L-24 & 25  undead. Killing one drew 3. Remember Rotted Ones alo have those worms attack after R.O. dies. After Morbent dies, all undead in crypts die. Run out safely into cemetery.",
            date = "2011-03-23T20:54:01-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26725#comments:id=1374535",
        },
        {
            id = 1640380,
            score = 5,
            author = "716234",
            text = "Hope this doesn't sound like rambling but I got a little confused going in so thought I might describe it my way.  There is a pile of dirt at a crypt. It will tell you to go down into the crypt.   When you get to the first area turn left and go through the next two rooms til you get to the left back wall where there is a door at 23.6 27.9, go thru that room to the back right wall at 20.3 27.5. It will give you the next quest and you must go through a chink in the wall behind it. I couldn't see it on my computer but it is there more towards the back right.  Then you will wind through a tight tunnel where it is difficult to see the mobs that attack you.  But it is only one at a time and I had no problems handling them with my lvl 28 Pali or Priest. The next end of the quest is at 18.1 25.3  You will get another quest Morbent's Bane. Continue on in the tunnel til you get to a big room.  You will have to kill a few mobs to make sure you are not attacked when you kill Morbent. Be careful there are a bunch of mobs behind Morbent so it is best if you can get him down to the ground floor to kill him.",
            date = "2012-03-16T18:57:11-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26725#comments:id=1640380",
        },
        {
            id = 1191941,
            score = 2,
            author = "707268",
            text = "Leads to The Halls of the Dead (http://www.wowhead.com/quest=26753).",
            date = "2010-11-28T00:09:35-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26725#comments:id=1191941",
        },
