    [26727] = {
        {
            id = 1195742,
            score = 57,
            author = "TDSunryzeX",
            text = "Sorry, but Abercrombie & Stitch?\n\nBAD joke..",
            date = "2010-11-29T13:08:13-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26727#comments:id=1195742",
        },
        {
            id = 1421431,
            score = 44,
            author = "Neverknow",
            text = "And this proves us that were you to give players a load of experience and gold plus some epics as reward, and all you ask them to do is start the Apocalypse, they would quite certainly do it.",
            date = "2011-05-18T00:18:18-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26727#comments:id=1421431",
        },
        {
            id = 1182867,
            score = 31,
            author = "Seprest",
            text = "This is the updated quest for cataclysm.  Instead of stitches attacking the town head on and allowing anyone to kill him, and without risk of him killing npc's, (s)he now simply spawns outside a phased version of the town hall in with the nightwatch attacking him.  It is important to note that there is NO rush in fighting him, he will neither take damage or deal damage from and to the nightwatch npcs.  This also means that he can't be \"taken care of\" by the npc's either :)\n\nAbercrombie is also sitting on his shoulder in his full necromantic attire!",
            date = "2010-11-24T20:13:49-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26727#comments:id=1182867",
        },
        {
            id = 1528385,
            score = 27,
            author = "112951",
            text = "I'm reading comments not that much helpful so, to the ones who are planning to do this quest, better to clear some points.\n\nThe https://www.wowhead.com/npc=43903s won't tank https://www.wowhead.com/npc=43862 but only take him 'busy'. There is no aggro table, just touch the abomination with a finger and he start hitting you. This also mean that if you die fighting with https://www.wowhead.com/npc=43862 the https://www.wowhead.com/npc=43903s don't let him evade neither reset his health.\nIn few words: you don't need any sort of twink gear and don't have to waste pots in this fight.\nOnly hit him as hard as you can and if you die, just die, corpse res and fight again, https://www.wowhead.com/npc=43862 will be there in the same point and with the same health he have when you died.\n\nEnjoy the fight!",
            date = "2011-09-27T00:19:24-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26727#comments:id=1528385",
        },
        {
            id = 1184332,
            score = 20,
            author = "208835",
            text = "Blizzard makes good use of phasing on this one.  In addition to Stitches you'll find the town on fire.  It was quite the scene.",
            date = "2010-11-25T09:16:03-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26727#comments:id=1184332",
        },
    },
    [26728] = {
        {
            id = 2257367,
            score = 9,
            author = "Wyr3d",
            text = "Reposted as a post instead of a reply.\n\nThere is a level limit/cap on this quest, although there's no mention of one. It may stop becoming available at lvl 25 or 26. It was there for my char at lvl 24. I think it was still there at 25, but now it's gone. So either that, or one of the other quests in the chain makes it unavailable - which is stupid since there is no other breadcrumb out of the zone.\n\nAnother quest like this is:\n\nHero's Call: Redridge Mountains (http://www.wowhead.com/quest=26365/heros-call-redridge-mountains) available from either Captain Danuvin (http://www.wowhead.com/npc=821/captain-danuvin) in Sentinel Hill, or King Varian Wrynn (http://www.wowhead.com/npc=29611/king-varian-wrynn) in Stormwind. This quest has a cap of lvl 18, after which it becomes unavailable. However there does exist another leading quest from Westfall to Redridge, unlike the Duskwood one.",
            date = "2015-09-26T09:25:41-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26728#comments:id=2257367",
        },
        {
            id = 1541800,
            score = 6,
            author = "168278",
            text = "This quest gives more XP and Rep than the Board one: worth the 3 minutes flight and little run!",
            date = "2011-10-13T11:49:56-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26728#comments:id=1541800",
        },
        {
