    [26732] = {
        {
            id = 1408488,
            score = 36,
            author = "462634",
            text = "Posting this here so that it is visible because I want people to be able to get their pet without the confusion I had. As these are not listed as a chain and truthfully you wont be finishing all the quests chains, rather these are the just quests required to get your raptor. This is for the Alliance, Horde you have a guide lower down the page.\n\n1.a.  https://www.wowhead.com/quest=26732\n    1.a.1.  https://www.wowhead.com/quest=26738\n    1.a.2.  https://www.wowhead.com/quest=26739\n1.b.  https://www.wowhead.com/quest=26735\n    1.b.1.  https://www.wowhead.com/quest=26736\n\nAt this point you must log out, and log back in inorder to spawn a npc that will be required in the next step.\n\n2.  https://www.wowhead.com/quest=26744 Make certain your pet raptor is out while doing this quest as it will give you the next step here.\n\n3.  https://www.wowhead.com/quest=26745 If you did not complete 1.a.2. you will not be offered this quest as there will be no npc to turn it in. If you have not logged out and back in the npc will not be at the Rebel Camp yet.\n\n4.  https://www.wowhead.com/quest=26746\n5.  https://www.wowhead.com/quest=26747\n6.  https://www.wowhead.com/quest=26748 Don't bother chasing him, he runs the farthest I've ever seen an npc go, all the way to 54.5, 43.3 where he claims to have lost you and despawns. This chasing him is what got me confused because I thought I was done and so went and did Zul'Gurub and wondered why I didn't get my pet.\n\n7.  https://www.wowhead.com/quest=26749\n8.  https://www.wowhead.com/quest=26772\n9.  https://www.wowhead.com/quest=26773\n10. https://www.wowhead.com/quest=26774\n11. https://www.wowhead.com/quest=26775\n12. https://www.wowhead.com/quest=26776 It is after you complete this quest that killing https://www.wowhead.com/npc=52151 you get your 'aka back.",
            date = "2011-05-03T13:59:42-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26732#comments:id=1408488",
        },
        {
            id = 1221532,
            score = 25,
            author = "519467",
            text = "the drop rate is atrocious. had to kill like a hundred of these stupid mobs.",
            date = "2010-12-10T10:33:10-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26732#comments:id=1221532",
        },
        {
            id = 1436260,
            score = 19,
            author = "Shadock",
            text = "Bad Medicine is what I need!",
            date = "2011-06-07T10:23:37-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26732#comments:id=1436260",
        },
        {
            id = 1207728,
            score = 7,
            author = "58215",
            text = "If you had Jungle Remedy (http://www.wowhead.com/item=60265#see-also) in your bank or inventory before 4.0.3a they have disappeared.  It has since become a quest item.\n\nThe problem I ran into is that the game still thinks I had those old potions in my bank, and wouldn't allow me to pick up more to finish the quest.\nAbandoning and accepting the quest again seems to fix this issue.\n\nHope it helps (:",
            date = "2010-12-05T07:45:08-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26732#comments:id=1207728",
        },
        {
            id = 1531922,
            score = 7,
            author = "Nightshine067",
            text = "I just did all the quests in that series mentioned above by Madwolf. I got to Ghaliri and turned in quest but that was the end no pet. I then read in this thread\n\n[quest=26776 domain=www]\n\nthat you could kill mandokir in the level 85 dungeon and get the pet. I did just that and returned to Ghaliri but no pet or anything. I noticed ghaliri is neutral to me, wondered if that mattered but did not think it should.\n\nSo, I still have no pet and not sure if there is a way to get it now.",
            date = "2011-09-30T23:54:07-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26732#comments:id=1531922",
        },
