    [26737] = {
        {
            id = 1906864,
            score = 18,
            author = "sitecow09",
            text = "Im somewhat worried about what the lieutenant says after you turn in the quest: \"With Kurzen out of the picture, we may be able to continue our original expedition here in Stranglethorn, which was... ahh... no matter!\"\nIts more than likely just that hes been fighting so long that he just forgot, but if Kurzen and his troops fell into madness by being in the jungle so long, the same may be happening to the lieutenant and the others in the Rebel Camp...\n\nedit: looks like Doren's bit of mania wasn't enough to keep him from being promoted to Captain by the time of Mists of Pandaria... where his mania caused him to be consumed by the Sha of Doubt... oops.",
            date = "2013-10-08T20:16:44-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26737#comments:id=1906864",
        },
        {
            id = 1793079,
            score = 12,
            author = "769220",
            text = "I completed this quest on 2013/01/03.  All the mobs are in the cave.  Entrance to the cave is @ 59.25, 18.59.  Cave is called The Stockpile Mine. Seems like there are a zillion lesser mobs in the passage ways that can be easily dispensed but be careful to clear out the area before attacking the designated mobs as some of these lesser ones can come back on you and all of sudden you are fighting two at once. That can be a problem. So know your character well and utilize your cooldowns.\n\nThere are many forks in there.  As accurately as I can remember, if you take the immediate right fork, Anders is at 63.71, 16.73.  If you take the left fork and then bear right, Miranda is located at 65.82, 17.41 (diagonally to the right, far back). Gaulus can be located at 62.42, 14.12,  taking the left fork and going down and all the way around the moat.  I did not get an accurate read for Esquivel but in contrasting my locations for the others with the locations given initially by reiahart, they are all pretty close so you are not that far off in using the location of 66.11 for Esquivel.  Just follow your waypoint arrow or minimap arrow.  If your melee, be careful as these mobs have tendencies to quickly go in back of you when you least expect it.  Good Hunting!",
            date = "2013-01-05T12:52:11-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26737#comments:id=1793079",
        },
        {
            id = 1794238,
            score = 3,
            author = "769220",
            text = "As a further update, I did this quest again on Saturday morning (prox 3:30 am) to help a guild mate and won the roll for Parrot Cage (Hyacinth Macaw).  It was dropped by one of the mobs outside of the cave, near the front.",
            date = "2013-01-07T11:13:00-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26737#comments:id=1794238",
        },
        {
            id = 2009080,
            score = 3,
            author = "Zidaniel",
            text = "For those that use TomTom for coordinates:\n\n/way 60.7 19.5 Cave Entrance\n/way 63.73, 16.71 Chief Anders\n/way 62.48, 14.05 Chief Gaulus\n/way 65.81, 17.05 Chief Miranda\n/way 66.09, 11.72 Chief Esquivel",
            date = "2014-10-01T21:43:23-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26737#comments:id=2009080",
        },
        {
            id = 1570455,
            score = 2,
            author = "reiahart",
            text = "Chief Miranda is at (65, 17)\nChief Esquivel is at (66, 11)\nChief Gaulus is at (62, 14)\nChief Anders is at (63, 66)\n\nAll chief's are throughout the cave near Kurzen's Compound at (60, 23). Don't worry about having to kill every mob in here because these mobs have a higher chance of dropping they Parrot Cage (Hyacinth Macaw) (http://www.wowhead.com/item=8494). Which is great if you are going for this.",
            date = "2011-11-12T13:20:00-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26737#comments:id=1570455",
        },
    },
    [26738] = {
        {
            id = 1179937,
            score = 42,
            author = "Spoonzilla",
            text = "If your inventory is full and you get the message saying you failed it, don't worry!  You'll notice a cute little lashtail hatchling following you.  Just return to Rebel Camp and you'll notice a yellow ! above the same guy this quests ends at.  Talking to him will start the same quest as if your inventory hadn't been full.",
            date = "2010-11-24T01:53:56-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26738#comments:id=1179937",
        },
        {
            id = 1321240,
            score = 11,
            author = "289471",
            text = "This quest is an auto-accept quest. While doing Bad Medicine, once you obtain your 7th Jungle Remedy you will get the pop-up to start Just Hatched and an Lashtail Raptor Egg Fragment will be added to your inventory.",
            date = "2011-02-04T06:18:02-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26738#comments:id=1321240",
        },
        {
            id = 1391649,
            score = 4,
            author = "243011",
            text = "Our guild has a few jungle remedies left in the guild bank. I picked seven up using mobile banking and suddenly had this quest. Made me a bit confused.",
            date = "2011-04-15T02:01:46-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26738#comments:id=1391649",
        },
        {
            id = 1105971,
            score = 3,
            author = "202793",
            text = "Killed the Kurzen mobs randomly for awhile and nothing happened, then I went back to Rebel Camp and picked up the quests to kill them and it dropped off one of the Medicine men while doing the quest to get Jungle Antidote.  In fact, got it on the 7th drop, which is the amount you need.  Well, drop is a bit misleading.  It just kind of hops into your inventory.  If you have room, it's all good and you move on to the next level.  If you don't, seems you just fail the quest.\n\nIn this early stage of beta, you get an item in your inventory to keep summoning the pet, but it isn't an official pet yet.\n\nHorde gets it as well, through a quest given by Commander Aggro'gosh in Grom'Gol base Camp to destroy 12 lashtail eggs.  Little guy hopped in my Warlock's bag when I killed the last egg.",
            date = "2010-08-22T21:08:41-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26738#comments:id=1105971",
        },
        {
