    [26742] = {
        {
            id = 1207104,
            score = 33,
            author = "419521",
            text = "Note that the Bloodscalp Shamans (http://www.wowhead.com/npc=697) you loot the totems from seem to share spawn points with the Bloodscalp Warriors (http://www.wowhead.com/npc=587) and Bloodscalp Axe Throwers (http://www.wowhead.com/npc=694) who are in the same area. If you don't see any Shamans in the area, try clearing some of the npcs and waiting for respawns.\n\nEverything respawns very quickly, and the Shamans have a reasonable drop rate.\n\nEdit, yay for helpful and accurate information being randomly downrated? Oh well...",
            date = "2010-12-04T23:29:35-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26742#comments:id=1207104",
        },
        {
            id = 1316419,
            score = 8,
            author = "taurolyon",
            text = "https://www.wowhead.com/npc=697 shares spawn locations with https://www.wowhead.com/npc=587 and https://www.wowhead.com/npc=694, so don't be surprised if you need to kill a few trolls to get your shaman. Also, the https://www.wowhead.com/item=23679 is not 100% drop.",
            date = "2011-01-30T23:18:12-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26742#comments:id=1316419",
