    [26743] = {
        {
            id = 1328804,
            score = 4,
            author = "Royi",
            text = "All three of these Icons are relating to the corresponding lvl 28 rare beast of the same name that exist in Northern STV:\n\nTsul'Kalu:  [npc=51661 domain=www]\nhttp://www.wow-petopia.com/look/gorillaskinwhite.html\n\nMahamba: [npc=51662 domain=www]\nhttp://www.wow-petopia.com/look/crocodilecataclysmblue.html\n\nPogeyan:  [npc=60272 domain=www]\nhttp://www.wow-petopia.com/look/tigergemskinbrown.html\n\nPossible Spawn Locations of the 3 STV Spirits:  http://forums.wow-petopia.com/viewtopic.php?f=3&t=9605\n\n*Edit* Sorry at the time the post the new rare npcs were not loaded into wowhead yet.  These 3 rares are not associated in any way with actually completing this quest.  Just the icons needed for this quest references these 3 new rare spawns.  Thanks for clarifying Sterling",
            date = "2011-02-09T14:17:51-06:00",
