    [26745] = {
        {
            id = 1408100,
            score = 26,
            author = "joker102877",
            text = "In order to acquire and turn in this quest, one must:\n\nComplete Spared from Madness (http://www.wowhead.com/quest=26736).\nStart Deep Roots (http://www.wowhead.com/quest=26744).\nHave Lashtail Raptor Egg Fragment (http://www.wowhead.com/item=58165) in inventory.\nHave Lashtail Hatchling (http://www.wowhead.com/npc=42736) present while standing in the Bal'lal Ruins.\n\nWhen all these criteria have been met, approach the quest item object for Deep Roots (http://www.wowhead.com/quest=26744) and acquire Bloodscalp Lore Tablet (http://www.wowhead.com/item=60295).  At this time you may notice your Lashtail Hatchling run up to a pile of skulls.  After doing this, he will have a miniature skull \"in\" his mouth and Favored Skull (http://www.wowhead.com/quest=26745) will be available from your hatchling.  If this is a low level quest, the \"!\" will not show up unless you have \"Low Level Quests\" turned on so be sure to click your hatchling to acquire the quest.",
            date = "2011-05-03T06:20:47-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26745#comments:id=1408100",
        },
        {
            id = 1439353,
            score = 9,
            author = "Zarac",
            text = "If you din't pick the quest while doing https://www.wowhead.com/quest=26744 and now wonders where it is located, it's at 33.37, in Bal'lal Ruins (http://www.wowhead.com/maps?data=33:330370), by the https://www.wowhead.com/object=57.",
            date = "2011-06-11T13:57:30-05:00",
