        {
            id = 1967843,
            score = 3,
            author = "Vycount",
            text = "Just to help those who are used to clicking on a gear icon or a sparkly in order to pick it up, you need do nothing to get the fetishes your hatchling finds. He will find them on his own, and within a few seconds toss them to you of his own accord. You need not even be right next to him. I was going mad trying to click all around him to loot the fetishes before he ran off. :)",
            date = "2014-05-26T02:41:47-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26746#comments:id=1967843",
        },
