    [26748] = {
        {
            id = 1292630,
            score = 57,
            author = "NFalcon",
            text = "Go ahead--kill the gnome.  I want the raptor.",
            date = "2011-01-13T21:06:42-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26748#comments:id=1292630",
        },
        {
            id = 1407355,
            score = 53,
            author = "462634",
            text = "Posting this here so that it is visible because I want people to be able to get their pet without the confusion I had. As these are not listed as a chain and truthfully you wont be finishing all the quests chains, rather these are the just quests required to get your raptor. This is for the Alliance, Horde I can't help you.\n\n1.a.  https://www.wowhead.com/quest=26732\n    1.a.1.  https://www.wowhead.com/quest=26738\n    1.a.2.  https://www.wowhead.com/quest=26739\n1.b.  https://www.wowhead.com/quest=26735\n    1.b.1.  https://www.wowhead.com/quest=26736\n\nAt this point you must log out, and log back in inorder to spawn a npc that will be required in the next step.\n\n2.  https://www.wowhead.com/quest=26744 Make certain your pet raptor is out while doing this quest as it will give you the next step here.\n\n3.  https://www.wowhead.com/quest=26745 If you did not complete 1.a.2. you will not be offered this quest as there will be no npc to turn it in. If you have not logged out and back in the npc will not be at the Rebel Camp yet.\n\n4.  https://www.wowhead.com/quest=26746\n5.  https://www.wowhead.com/quest=26747\n6.  https://www.wowhead.com/quest=26748 Don't bother chasing him, he runs the farthest I've ever seen an npc go, all the way to 54.5, 43.3 where he claims to have lost you and despawns. This chasing him is what got me confused because I thought I was done and so went and did Zul'Gurub and wondered why I didn't get my pet.\n\n7.  https://www.wowhead.com/quest=26749\n8.  https://www.wowhead.com/quest=26772\n9.  https://www.wowhead.com/quest=26773\n10. https://www.wowhead.com/quest=26774\n11. https://www.wowhead.com/quest=26775\n12. https://www.wowhead.com/quest=26776 It is after you complete this quest that killing https://www.wowhead.com/npc=52151 you get your 'aka back.",
            date = "2011-05-02T13:35:27-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26748#comments:id=1407355",
        },
        {
            id = 1196195,
            score = 22,
            author = "80976",
            text = "The Embalmer reincarnates Stitches out of pure evil.\n\nThis guy reincarnates Mandokir out of pure stupidity.",
            date = "2010-11-29T17:31:13-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26748#comments:id=1196195",
        },
        {
            id = 1761238,
            score = 18,
            author = "willmatic",
            text = "Having never done this quest before, I almost sh*t my pants thinking he was talking about my ZG raptor mount I was currently riding.   O.o\n\nEdit:  Ironically, I think I looted that mount from him about 6 years ago!",
            date = "2012-11-12T04:43:37-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26748#comments:id=1761238",
        },
        {
            id = 1184616,
            score = 17,
            author = "Belzebutinov",
            text = "Nooo, my Baby Raptor!\n\n*shakes fist*\n\nCurse you, Mandokir, curse you!\n\nEdit: oh, and naturally: In Soviet Russia, Mandokir takes raptor from you!\nEdit 2: we get her back in Zul'Gurrub \\o/ -> An Old Friend (http://www.wowhead.com/quest=29208)",
            date = "2010-11-25T11:03:50-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26748#comments:id=1184616",
        },
    },
    [26749] = {
        {
            id = 1700274,
            score = 5,
            author = "821994",
            text = "To get to this quest that opens some other Exodar Rep quests, you must first do a group of quests offered by https://www.wowhead.com/npc=739 and https://www.wowhead.com/npc=469 at the Rebel Compound in N Stranglethorn.  (These will also give you the opportunity to get a raptor companion.)\n\nAfter you rescue Osborn Obnoxious and two others in https://www.wowhead.com/quest=26736 you will have to log off and relog on to make him appear at the compound.  A couple of quests later he will give you this quest.\n\nSee the comment by Madwolf under https://www.wowhead.com/quest=26748;  he does a nice job explaining the details.",
            date = "2012-08-15T15:38:45-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26749#comments:id=1700274",
        },
        {
            id = 1449067,
            score = 2,
            author = "327014",
            text = "Do not chase Mandokir, just stand there..but once you have completed quest with Mandokir, the gnome will give  you the quest.",
