            author = "330953",
            text = "I can't see the gnome for some reason, yet i have completed the quest chain up to this point. Anyone mind helping me out? :)",
            date = "2011-07-07T10:18:34-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26749#comments:id=1463415",
        },
