    [26753] = {
        {
            id = 1264705,
            score = 44,
            author = "166187",
            text = "There are two entrances to the Catacombs actually.\n\nIf you want to go in guns blazing, murder 2 elites and 59812741 ghouls the front entrance at 16,39 that gmc mentioned is for you.\n\nIf you want to sneak in the back way there is another entrance at 24,35.\n\nYou will find the back way is pretty straight forward and linear as far as completing the quest chain.",
            date = "2010-12-28T19:21:58-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26753#comments:id=1264705",
        },
        {
            id = 2879411,
            score = 8,
            author = "SlySnake",
            text = "Looking at the mini-map it looks like there's no connection between 2 sections, but there is (black on the mini-map) where you turned the quest in (hole in the wall) (20,27) when entering from east entrance.",
            date = "2019-03-29T18:33:26-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26753#comments:id=2879411",
        },
        {
            id = 1299893,
            score = 7,
            author = "553012",
            text = "So, if you are like me looking for \"awesome\" loot and are like, \"wtf? warez teh quest?\" then you are in luck. Well kinda. Wowhead says the quest chain starts at the beginning of the catacombs with \"Lightforged Rod\", but it really starts back at the quest \"The Yorgen Worgen\"\n\n[quest=26717 domain=www]\n\nBasically, if you don't finish that quest chain, followed by Sven's quest or two, then you don't get access to this one.",
            date = "2011-01-19T02:02:41-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26753#comments:id=1299893",
        },
        {
            id = 2557083,
            score = 6,
            author = "Wowzir",
            text = "/way Duskwood 16, 39 FRONT Entr\n\n/way Duskwood  24, 35 BACK Entr\n\n;)",
            date = "2018-03-10T10:18:52-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26753#comments:id=2557083",
        },
        {
            id = 1207240,
            score = 4,
            author = "718737",
            text = "The catacombs are in Raven Hill Cemetary in case you miss them.  If you just follow the question mark without going into the catacombs first you'll be way off where you need to be.",
            date = "2010-12-05T01:07:11-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26753#comments:id=1207240",
        },
    },
    [26754] = {
        {
            id = 6226969,
            score = 48,
            author = "Quistinie",
            text = "If you want Small Gilnean Table (https://www.wowhead.com/beta/item=256905/small-gilnean-table), you can start at The Yorgen Worgen (https://www.wowhead.com/quest=26717/the-yorgen-worgen)",
            date = "2025-11-16T15:54:18-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26754#comments:id=6226969",
        },
        {
            id = 1578810,
            score = 19,
            author = "915268",
            text = "Was just leveling an alt in Duskwood for the first time, doing \"The Fate of Morbent Fel\", and wondered why my level 30 prot warrior was having such a hard time with the quest, how any non-tank was supposed to survive fighting endless swarms of ghouls, and why, upon killing Morbent, he didn't drop his own remains.\n\nThen I realized I was in the wrong place. :D",
            date = "2011-11-23T01:08:35-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26754#comments:id=1578810",
        },
        {
            id = 2369346,
            score = 13,
            author = "CandyKills",
            text = "In case anyone does a dum dum like I did today and runs off to the  spot on the map...which is the back entrance and significantly more difficult...the co ords to the original catacomb where you get to Morbent Fel are 23,7 by 35,5",
            date = "2016-08-17T02:44:50-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26754#comments:id=2369346",
        },
        {
            id = 1201837,
            score = 11,
            author = "716309",
            text = "The actual secret to this one is to not leave the tunnels where you pick up the various pieces of the quest..it is a chain.  If you keep going forward, you'll come into the other crypt behind that wall of ghouls and just take out some lesser liches before taking down the big man.  Then to agro Morbent, just jump up behind him and agro him, use the disenchanter thingy (morbent's bane), and beat him down, when he dies all of the ghouls die.",
            date = "2010-12-02T07:48:11-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26754#comments:id=1201837",
        },
        {
            id = 1303996,
            score = 11,
            author = "VonNegga",
            text = "As a hunter, I encountered a bug during the course of this quest where my pet would not cross the threshold between the underground tunnel and the crypt where Morbent Fel is.  Imagine my dismay while crossing over said threshold, when my pet just froze and about 3 undead were casting frost shock on me.  To circumvent this oddity, I had to dismiss my pet, cross over into the crypt and call my pet after the mobs were aggroed.  Not fun.",
            date = "2011-01-22T08:11:14-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26754#comments:id=1303996",
        },
    },
    [26760] = {
        {
            id = 1204243,
            score = 134,
            author = "Metzae",
            text = "In case you seem to be having trouble completing this quest, just drop it, find the questgiver, and then just wait around. I ran off and missed the event because I was speed questing. Just watch the guillotine.",
            date = "2010-12-03T13:32:37-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26760#comments:id=1204243",
        },
        {
            id = 6237922,
