            author = "Grissu",
            text = "If you want to collect decors by completing this quest, but you don't have any here, you need to complete a very small quest chain starting at https://www.wowhead.com/npc=43738 with https://www.wowhead.com/quest=26717.\nThen he will send you to the https://www.wowhead.com/npc=43730 and you will have the quest https://www.wowhead.com/quest=26720 available, that is one quest behind this one.",
            date = "2025-12-03T17:36:48-06:00",
