    [26761] = {
        {
            id = 1681402,
            score = 64,
            author = "Pwnzoar",
            text = "....You guys sure you don't want my help stopping the town from burning down and stuff?",
            date = "2012-06-26T13:15:01-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26761#comments:id=1681402",
        },
        {
            id = 1183811,
            score = 29,
            author = "Shibang909",
            text = "So when does he \"get back to you?\"\n\nRunning through the zones on my 80 shammy exploring the new quests and I just finished Redridge and there's no follow up yet. I mean yeah I've run the new Deadmines (which is awesome) but I'm still waiting for the actual follow up :S",
            date = "2010-11-25T03:56:03-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26761#comments:id=1183811",
        },
        {
            id = 1193857,
            score = 23,
            author = "362402",
            text = "You have to go into the Deadmines and Horatio will give you the next chain.'\n\nAnd Sentinel Hill does burn still.",
            date = "2010-11-28T16:05:59-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26761#comments:id=1193857",
        },
        {
            id = 1184502,
            score = 16,
            author = "458414",
            text = "I found this very odd and confusing too.\n\nWhen I left for Redridge, Sentinel Hill was still on fire ( phased that way, but outside the sky was blue ).  I then did all the Redridge quests, got sent to Darkshire...\n\nI guess it makes sense that we face her at lvl 85 ( ie. she did flee and go into hiding, and set Cookie up for the fall ).\n\nStill, Sentinel Hill being left on fire for 60-70 some levels is strange, seeing as you leave Redridge in perfect condition, far far better then it was before you showed up.\n\nAnd nothing links this to the stockades anymore?  Or did I miss a loot item?",
            date = "2010-11-25T10:23:04-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26761#comments:id=1184502",
        },
        {
            id = 1545774,
            score = 14,
            author = "evlyxx",
            text = "Seems having done this quest phases out the Inn and makes it impossible to get the Candy Bucket in Westfall and therefore unable to complete  Tricks and Treats of The Eastern Kingdoms (http://www.wowhead.com/achievement=966)\n\n**EDIT** Seems I was actually wrong on this one, if you phased out Sentinel Hill the Candy Bucket gets moved to the Tower there. So a big thumbs up to the devs for getting this one in before idiots like me complain too much.",
            date = "2011-10-17T20:33:56-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26761#comments:id=1545774",
        },
    },
    [26763] = {
        {
