    [26765] = {
    },
    [26769] = {
        {
            id = 1360404,
            score = 23,
            author = "567560",
            text = "These were a nerve-wracking 20 seconds. I kept thinking something was going to happen, and then like he was reading my mind, Horton goes, \"This is where you'd expect something to go wrong on a beautiful trip like this.\" That alleviated my fears. Nothing like reversed reverse psychology.",
            date = "2011-03-07T15:59:48-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26769#comments:id=1360404",
        },
        {
            id = 1179998,
            score = 17,
            author = "Liri",
            text = "Note dont try to walk onto the ship (you fall through it) or talk to him.  Click on the ship.\n\nHorton Hornblower says: You're , right? Gazlowe told me to take ya up the river! Hop in when you're ready to go.\nHorton motions to the rickety riverboat nearby.\nHorton Hornblower says: There's nothing quite like the smell of Durotar on a warm, comfortable boat ride.\nHorton Hornblower says: This is where you'd expect something to go wrong on a beautiful trip like this.\nHorton Hornblower says: We're pulling up near your stop. Head due west along the road to reach Nozzlepot's Outpost.",
            date = "2010-11-24T02:27:00-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26769#comments:id=1179998",
        },
        {
            id = 1346813,
            score = 14,
            author = "ZJPV1",
            text = "Another quote from the ride (my favorite):\n\nEveryone always says, \"Horton, why do you drive a boat up and down the river?\" I ask them, \"Why don't you?\" ... that's usually where I run out of witty retorts.",
            date = "2011-02-23T04:30:28-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26769#comments:id=1346813",
        },
        {
            id = 1297986,
            score = 7,
            author = "Chetti",
            text = "To clarify a little about where to board the boat, Horton is sitting up the rocks a little.. not down by the water.  Blizzard's in-game quest tracker puts the spot in the water, where it looks like you could wait for a boat. He's actually a up on the rocks above that spot.",
            date = "2011-01-17T15:20:24-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26769#comments:id=1297986",
        },
        {
            id = 1187363,
            score = 5,
            author = "Waerjak",
            text = "While doing this quest on my hunter, after taking the riverboat-ride, I noticed that all of my \"Call Pet\" abilities had been (temporarily) renamed to \"Call Riverboat\". *chuckle*",
            date = "2010-11-26T10:22:51-06:00",
