    [26774] = {
        {
            id = 1181439,
            score = 11,
            author = "ladywolfxo",
            text = "Head south, and check out the big brain on Braddok is a Pulp Fiction reference \"Check out the big brain on Brad!\"",
            date = "2010-11-24T12:20:31-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26774#comments:id=1181439",
        },
        {
            id = 1711789,
            score = 5,
            author = "cheriea99",
            text = "Not sure why my previous comment here was deleted by someone as it had useful info...\n\nThere is a trail you can hop on to about 98 yds from the North entrance/exit of Ft. Livingston. Hook a right on that trail, and head up/into the Ruins of Zul'Mamwe. Make sure you grab the quest Zul'Mamwe Mambo from Ghaliri 'Emissary of Rastakhan' in Ft. Livingston as you'll be killing lots of Skullsplitter Trolls on the way up. Also grab 'Nightime in the Jungle' from Kinnel in the same area. At approx coords of 61.4,73.7, if graphics card allows you to see a good distance, you will see Braddok walking back and forth in a corner of the maze you've been trekking through. You might also find a rare leet there by the name of Mogh the Dead.",
            date = "2012-09-10T08:15:56-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26774#comments:id=1711789",
        },
        {
            id = 1182783,
            score = 4,
            author = "Sygmoral",
            text = "Her quest text was probably taken from the Horde version. Because you don't need to go south; you neast to go east (there's a fast path, no need to go north and follow the road).",
