    [26780] = {
        {
            id = 1298253,
            score = 14,
            author = "Duendelstein",
            text = "The Horde version of this quest gives a much darker background to your quest: One year ago, my mother - that is, the troll who took care of me - was taken by the Skullsplitters of Zul'Mamwe. Young and headstrong, I ran in after her, only to see her being pushed toward a burning brazier by a dozen of their warriors. I hid behind a tree and watched as they grabbed her and... and...\n\nAt nighttime, the lights from their braziers reflect off the treetops and keep me awake. Please, ... travel south into Zul'Mamwe and put them out.\n\nSo you're also helping a troll sleep at night...",
            date = "2011-01-17T19:27:06-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26780#comments:id=1298253",
