    [26800] = {
        {
            id = 1407712,
            score = 16,
            author = "tegarasil",
            text = "This quest shows in the list for non-Forsaken characters.  When walking up to a corpse, I have no means of \"starting\" this quest.  The first quest that I can pick up is the last (http://www.wowhead.com/quest=26801) one in the sequence.\n\nI am playing a Blood Elf Mage, trying to complete Loremaster Achievement.",
            date = "2011-05-02T20:28:05-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26800#comments:id=1407712",
        },
        {
            id = 1202668,
            score = 11,
            author = "Polegara",
            text = "The quest instructions say \"point at them so Darnell can pick them up\".\n\nDo NOT do this. Or you'll waste quite a few minutes like I did, /pointing at them and trying to get it to work.\n\nLike most quest items in the world, they are interactable with by right clicking on them, which will then animate your character to point at them while Darnel runs to pick them up.\n\nI guess this is the opposite of those /cheer /dance quests that Blizz have been making recently.",
            date = "2010-12-02T17:33:29-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26800#comments:id=1202668",
        },
        {
            id = 1179720,
            score = 8,
            author = "495957",
            text = "Currently (11/24/10) this quest seems to be slightly broken.  The requirements of the quest are that you collect six Scarlet Corpses; however, with the massive influx of new characters in Deathknell the corpses don't have adequate time to respawn, leaving many players one or two corpses short of their goal.\n\nOn the other hand if one doesn't complete the quest Darnell; the NPC tasked with accompanying and assisting you, will not disappear, leaving you with a rather large zombie vanity pet that no one else can see.  How long Darnell keeps will keep the player company I cannot yet say, though he has joined me as far as Brill.\n\nEnjoy your invisible giant flesh eating friend!\n\n*An addendum to the above information: If you complete the remainder of the quests in Deathknell while leaving Recruitment incomplete Darnell will; on at least two occasions, meet his future self, which is worthy of the lulz.",
            date = "2010-11-24T00:20:35-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26800#comments:id=1179720",
        },
        {
            id = 1253247,
            score = 6,
            author = "127599",
            text = "Here, take one of these.  We deathguards have piles of these things just sitting around.",
            date = "2010-12-22T20:04:29-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26800#comments:id=1253247",
        },
        {
            id = 1181093,
            score = 3,
            author = "189872",
            text = "I found I was having a bug with this since Darnell kept constantly despawning and respawning on me. I was able to fix this by right-clicking on the corpse as soon as Darnell respawned, causing him to pick up the body before he despawned again. It was a bit annoying, but it's an easy workaround for now.",
            date = "2010-11-24T10:25:39-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26800#comments:id=1181093",
        },
    },
