    [26802] = {
        {
            id = 3184456,
            score = 3,
            author = "GibbleFenwick",
            text = "The quest text clearly indicates you should receive an item reward.\nThis armor should help you out.\nHowever, as a warrior, you get nothing.\nThis is because the game only shows \"valid\" armour types for your class; and there are no plate items to choose from.\nThis is a throwback (no doubt unintentional) to the earlier versions of WoW, in which warriors would start out wearing mail and only later obtain the ability to wear plate (low level plate gear did not exist at all).\nSince the change to simplify gearing, and warriors no longer needing to bother with mail: most quests have been updated to to include plate items where necessary.\nIronically this one was evidently missed.",
            date = "2020-01-21T13:20:05-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26802#comments:id=3184456",
        },
        {
            id = 1080960,
