    [26809] = {
        {
            id = 1207375,
            score = 126,
            author = "165524",
            text = "While the in-game quest tracker points you to the Ruins of Aboraz, you'll actually find the bat totem at the Ruins of Jubuwal (where you got the Zanzil's Mixtures from). You'll be transported to the Ruins of Aboraz to get quest credit, then transported back.",
            date = "2010-12-05T02:45:44-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26809#comments:id=1207375",
        },
        {
            id = 1220399,
            score = 102,
            author = "1405",
            text = "Located at [54.23, 31.42].\n\nClick on the totem and you'll witness a short in-game cutscene.",
            date = "2010-12-10T00:47:52-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26809#comments:id=1220399",
        },
        {
            id = 3169705,
            score = 55,
            author = "cephrongaming",
            text = "You might get confused about this quest as you get it at the same time you get the quest for Zanzil Mixtures. There will be a circle at the Ruins of Aboraz (RoA) but this is not where you want to go. Moreover, the map wrongly indicates the Ruins of Jubuwal (where the totem is) as right near the RoA.\n\nYou'll find the totem on the East side of the Ruins of Jubuwal.\n\nWith TomTom, /way 54.2, 31.4\nWithout, just a rock throw SouthEast of the Gurubashi Arena.",
            date = "2019-11-06T08:19:29-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26809#comments:id=3169705",
        },
        {
            id = 2027010,
