    [26810] = {
        {
            id = 1193053,
            score = 3,
            author = "4318",
            text = "INSTRUCTIONS TO FINISH THIS QUEST:\n\nThe problem with this quest is that for some reason, Quest Guru is not showing the \"Quest Complete\" button to the top right, under the radar.  This is the button you click on to finish your existing quest and start the next quest, using Blizzard's new dynamic quest chain system.\n\nWhat you need to do is this:\n-Disable Quest Guru TRACKER.\n-Click on the quest in your Panel.\n-Click the \"Complete Quest\" bar and the next one will start.\n\nLeave Quest Guru TRACKER disabled until the quest line is entirely complete.\n\nI will edit this post if I find a toggle in Quest Guru that allows this to work properly.",
            date = "2010-11-28T10:30:25-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26810#comments:id=1193053",
        },
        {
            id = 1701300,
            score = 3,
            author = "Farzeer",
            text = "Do you have to kill anything to complete this? Because i just walked near the portal with my level 85 and got quest completed :s",
            date = "2012-08-18T09:23:23-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26810#comments:id=1701300",
        },
        {
            id = 1190458,
            score = 2,
            author = "gamerunknown",
            text = "I also had a problem with this quest, but disabling Quest Guru fixed it... Hope this helps. It also works with any of the \"communications\" quests, so completely uninstalling QuestGuru might be more beneficial than keeping it.",
            date = "2010-11-27T12:49:38-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26810#comments:id=1190458",
        },
        {
            id = 1488590,
            score = 2,
            author = "818594",
            text = "To get to the Ruins of Aboraz  [ coords 61.19,  43. 77 ] follow a path through the hills slightly east then south east of the quest giver, the ruins are on the beach.\nThere are several level 31 undead Naga, level 32 running and leaping Zombie hunters and level 31 undead Witch doctors on the path, in and around the ruins.\nKill the witch doctor(s)  to get Zanzils' formulation ,which resembles a buff scroll, for the quest 'Recipe for Disaster ' given by horde: Mixmaster Jasper /Alliance : Dask 'The Flask' Gobfizzle .\nEnter the ruins through a crumbled wall section. Near the bonfire a pop up to complete 'Eliminate the Outcast 'and to get the follow up quest \"Through the Troll hole\" ( the portal in the south eastern corner ) should appear.",
            date = "2011-08-06T11:09:03-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26810#comments:id=1488590",
        },
        {
            id = 1200316,
