            text = "The same applies to the experimental version of QuestHelper2, since it also replaces the built in quest tracker, it needs to be disabled to complete this quest chain. I have opened a ticket for QuestHelper2 at http://wow.curseforge.com/addons/questhelper2/tickets/4-unable-to-complete-quest-when-qh2-is-active/",
            date = "2010-12-01T13:52:26-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26810#comments:id=1200316",
        },
    },
