    [26812] = {
        {
            id = 2364744,
            score = 16,
            author = "Dekes",
            text = "Lvl 100 Rouge. Can't find her due to phasing problem. I believe Daralan at DeadWind Pass is the cause of this. Guess I'm gonna have to wait till Blizz remove Daralan or when Legion hits.\n\nEdit 8/30/2016:\nFinally able to complete this quest. Daralan have been moved by one of the Legion quest. It strange I put the Legion expansion quest on pause to finish this Lore.",
