    [26813] = {
        {
            id = 2176231,
            score = 5,
            author = "Takata",
            text = "Same little annoying bug applies to the first quest, when you first accept it, it continues to pop up so just press esc. Also same formula applies. You attack the outcast, then attack the priestess when the outcast says \"I can't take much more of this.\" As you continue to attack the outcast and almost kill him, he'll \"choke, stun\" you with a spell and a shadowy figure will appear and will threaten to kill you, quickly look behind you and you'll see a step ladder rope flying towards you. As it gets closer to you messages will appear on your screen to grab the rope. Do so of course or you'll die.",
