        {
            id = 1681438,
            score = 3,
            author = "HalfPintGnome",
            text = "After completing this quest, Dask will mix the basilisk glue and pure water and apply the potion to the sample of mysterious Mosh'ogg rocks that you sent from Fort Livingston.  He then says:\n\nWe just mix these two together...\n...give a little swirl...\n...alchemy, alchemy, alchemy...\n...and, we put the potion on the sample...\nThere we go.  The substance that you have brought me is approximately... 150,000 years old?  What!?  I'm going to have to run another test.",
            date = "2012-06-26T15:22:29-05:00",
