        },
        {
            id = 1724980,
            score = 12,
            author = "725539",
            text = "To unlock this quest, you must go to daddy Bronwyn Hewstrike (http://www.wowhead.com/npc=44082) and pick up Dask \"The Flask\" Gobfizzle (http://www.wowhead.com/quest=26825), which will just send you to the gnome (http://www.wowhead.com/npc=44099) across the firepit.\n\nComplete one measly little quest (http://www.wowhead.com/quest=26823) for the 'little' man by going into a dark, wet cave and draining the lizard.\n\nImpressed by your prowess, Linzi grant you full access (http://www.wowhead.com/quest=26820) to her (http://www.wowhead.com/quest=26818) every desire (http://www.wowhead.com/quest=26819).\n\nHappy spelunking!",
            date = "2012-09-29T18:05:39-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26818#comments:id=1724980",
        },
