            date = "2012-07-26T16:49:48-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26821#comments:id=1692415",
        },
    },
    [26822] = {
        {
            id = 1238013,
            score = 10,
            author = "Toyotacamry",
            text = "To get to the cave with the basilisks, you have to go northwest out of the Explorers League Outpost.  Once you get to Gurubashi Arena, go directly east (past the Ruins of Jubuwal) and there they are.\n\nAlso, slither-dogs.",
            date = "2010-12-16T10:14:48-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26822#comments:id=1238013",
