        {
            id = 1410164,
            score = 9,
            author = "shadow85",
            text = "For anyone still struggling to find/get to these guys (if you're near Fort-Livingston that is) - you need to get round the big whirl-pool. Follow the path south of Fort Livingston, and follow the cliff-edge path right down (the cliff-path starts around 51,71).\n\nDon't go up the path to the goblin cave, there's no way through/over from there.\n\nYou should now have the basillisks right in a clearing in front of you, and the cave round to your left for the dude with the Ironjaw Humour.",
            date = "2011-05-05T06:02:16-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26822#comments:id=1410164",
        },
    },
