    [26843] = {
        {
            id = 1105722,
            score = 36,
            author = "64622",
            text = "\"Commander\" Nazrim seems to be a reference to Nazrin from Touhou Project.\n\nEdit: To explain what I am talking about:\n\nNazrin is a character from Touhou Project, a series of Japanese shmups. She is a mouse youkai and is depicted as a leader of her kind. Her theme song is 小さな小さな賢将, translated as 'A Tiny, Tiny, Clever Commander'.\n\n\"Commander\" Nazrim is the objective of the quest 'A Tiny, Clever Commander'. The NPC in question is a kobold, which are, as everyone knows, rat-like in appearance. This NPC is also acting as a sort of leader of its kind.",
            date = "2010-08-22T13:35:47-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26843#comments:id=1105722",
        },
        {
            id = 1196273,
            score = 20,
            author = "Lansiron",
            text = "No matter what, Touhou inevitably touches all things.\n\nIt's one o' them \"Rules of the Internet\".",
            date = "2010-11-29T18:17:02-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26843#comments:id=1196273",
        },
        {
            id = 1207054,
            score = 13,
            author = "315859",
            text = "It's a reference many, many years in the making. But at long last, here it is. A fine, clear reference to Touhou in WoW. No long stretches or anything.\n\nNow that there is one, there may be more. An idiotic gnome ice mage? A witch with the power to fire massive lasers? A perpetually poor priestess able to become intangible and use sealing amulets?\n\nThe possibilities are infinite, and I will be waiting for them impatiently...\n\n...since I'm Nazrin. (http://danbooru.donmai.us/post/show/550148/)\n\nPS: the confirmation code to post this message is \"precious Thaoniu\". It's not quite Marisa Stole the Precious Thing, but hey, close enough. XD",
            date = "2010-12-04T22:52:17-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26843#comments:id=1207054",
        },
        {
            id = 1180952,
            score = 12,
            author = "skevans",
            text = "This quest is obtainable from Mountaineer Stormpike (http://www.wowhead.com/npc=1343) at Algaz station (http://www.wowhead.com/zone=925/algaz-station), Loch Modan. Coordinates 25 17.\n\nCommander Nazrim is found in a cave due south of mountaineer stormpike, the entrance to which is at 25 30.\n\nHe is level 13, non elite and has 546 health points.\n\nIf you are lucky like me you will find Kubb (http://www.wowhead.com/npc=1425) at the entrance to the cave also.\n\nReturn to mountaineer stormpike to hand in the quest once Nazrim is dead.\n\nMountaineer stormpike will then allow you to progress on to Kobold and Kobolder (http://www.wowhead.com/quest=26844).",
            date = "2010-11-24T09:49:42-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26843#comments:id=1180952",
        },
        {
            id = 1148283,
            score = 7,
            author = "685648",
