    [26854] = {
        {
            id = 1274345,
            score = 10,
            author = "753561",
            text = "To find this go from quest giver and turn around.\nGo through the tunnel directly behind you.\nOnce you come out turn right.  If you see a white bear sitting on a small hill you are in the right area.",
            date = "2011-01-03T01:49:42-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26854#comments:id=1274345",
        },
        {
            id = 2534198,
            score = 8,
            author = "Taraezor",
            text = "For those needing information on how this was played way back in Vanilla / Classic, I'll drip feed you for the sake of those who don't like being spoonfed:\n\n(1)  the NPC you are looking for is in fact deceased and is in the same area as the quest giver.\n\n(2) From the quest giver try an \"about face\" of 180 degrees.\n\n(3) Bear north-west from the quest giver. The body and his belongings are on the slope of a mound.\n\nThe next step involves taking out a difficult to solo NPC. Difficult if you are playing Vanilla/classic and thus are wearing questing commons. Aim to be at least level 10. You will need to take out two snow leopards one by one before you encounter the next quest NPC.\n\nALL other location information on this web page and in YouTube is totally WRONG for Vanilla/Classic as Blizzard have moved things around and altered the map somewhat.",
            date = "2017-11-11T06:17:19-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26854#comments:id=2534198",
        },
        {
            id = 5903540,
