            text = "Can no longer finish this quest in chromie time and party sync because Blizzard does not know how to Q/A after world within pre patch. xd",
            date = "2024-07-24T13:36:50-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26854#comments:id=5903540",
        },
    },
