    [26864] = {
        {
            id = 1181191,
            score = 2,
            author = "skevans",
            text = "This quest is obtainable from Mountaineer Stormpike (http://www.wowhead.com/npc=1343) at Algaz station (http://www.wowhead.com/zone=925), Loch Modan (Coordinates 25 17), upon completion of Kobold and Kobolder (http://www.wowhead.com/quest=26844).\n\nSimply deliver Foreman Sharpsneers head (http://www.wowhead.com/item=60404) to Mountaineer Kadrell (http://www.wowhead.com/npc=1340) at 35 46 in Thelsamar, Loch Modan.\n\nCompletion of this quest will allow you to progress on to Suddenly, Murlocs! (http://www.wowhead.com/quest=26927)\n\nCompletion of this quest also granted me 68 rep with alliance and 68 with Gilneas (http://www.wowhead.com/faction=1134).",
            date = "2010-11-24T10:58:17-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26864#comments:id=1181191",
        },
        {
            id = 1203766,
            score = -1,
            author = "Tenjen",
            text = "hhehehe...gnoll-edge...that was painful blizzard.\n\noh and \"Gnolls and kobolds, and troggs? Oh my.\"\n\niam really loving these new quests XD\n\ncookie for those who know the above reference of \"xx&xx&xx, oh my!\"",
            date = "2010-12-03T08:41:48-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26864#comments:id=1203766",
        },
    },
    [26865] = {
        {
            id = 1904421,
            score = 3,
            author = "Azurics",
            text = "Very ironic that Garrosh becomes exactly what he is trying to fight against.\n\nHE becomes the threat to the (real) Horde beneath the city. He hides through Ragefire and enlists the Dark Shamans he sought to be rid of here. It is a shame that Hellscream was so overcome with foul Old God wisperings.\n\nIt's also worth noting that while WoWHead has this quest marked as unobtainable, it is still available in a different form here:  https://www.wowhead.com/quest=31034.",
            date = "2013-10-01T01:21:43-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26865#comments:id=1904421",
        },
        {
            id = 1765178,
            score = 2,
            author = "Netspook",
            text = "Kurjcak is not in the instance, so you cannot complete this quest.\n\n@Selket:\nIt's not possible to turn this quest in to Bagran. Are you sure you're on the correct version? This quest has 6 different IDs, depending on:\n\n- who are you supposed to speak with, Kurjack or Bagran?\n- where did you accept the quest, Org, UC or TB?\n\nThis page is the Org/Kurjack version.\n\nWhat is really odd about this, is that according to wowhead, the Kurjack versions were added in patch 4.01, and the Bagran versions in 5.01. So I don't understand why, as of today, I was offered the old (Kurjack) version, which makes no sense at all.\n\nThe 6 versions are listed here (http://www.wowhead.com/search?q=enemies+below), or just simply search the questname.",
            date = "2012-11-20T06:28:40-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26865#comments:id=1765178",
        },
        {
            id = 1711577,
            score = 0,
            author = "Selket",
            text = "Does not hand into Stone Guard Kurjack (http://www.wowhead.com/npc=44217), as he is not in the instance anymore - reset instance, waited to see if he spawned - had to drop, retake and turns out the hand-in is to Commander Bagran (no wowhead page).",
            date = "2012-09-09T17:35:40-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26865#comments:id=1711577",
        },
        {
            id = 1814927,
            score = 0,
            author = "Stalyn",
            text = "I'm very much tempted to do this quest just so he won't try to give me it every time I turn in a quest to him.",
            date = "2013-02-17T20:12:51-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26865#comments:id=1814927",
        },
    },
    [26866] = {
        {
            id = 1334316,
            score = 4,
            author = "161879",
            text = "This quest cannot be accepted if you are already on the Orgrimmar version of the quest.",
