    [26868] = {
        {
            id = 1353166,
            score = 146,
            author = "avonar",
            text = "For those who are blind (like me) all the quest items are in a bag \"Canary's Cache\", which contains Skin of Dwarven Sout, Clever Plant Disguise and Potent Murloc Pheromones.",
            date = "2011-02-28T13:06:25-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26868#comments:id=1353166",
        },
        {
            id = 6240229,
            score = 93,
            author = "ZulTabris",
            text = "For those wanting the decor item the quest chain is\nA Tiny, Clever Commander (https://www.wowhead.com/quest=26843/a-tiny-clever-commander)\nKobold and Kobolder (https://www.wowhead.com/quest=26844/kobold-and-kobolder)\nWho's In Charge Here? (https://www.wowhead.com/quest=26845/whos-in-charge-here)\nThe Bearer of Gnoll-edge (https://www.wowhead.com/quest=26864/the-bearer-of-gnoll-edge)\nAxis of Awful",
            date = "2025-12-06T10:20:55-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26868#comments:id=6240229",
        },
        {
            id = 1094284,
            score = 37,
            author = "186827",
            text = "Funny quest.\n\nIf you're a Firefly fan, I'd suggest sticking out listening to the conversation that happens after you \"tag\" the Mosshide Representative.",
            date = "2010-08-02T16:06:54-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26868#comments:id=1094284",
        },
        {
            id = 1353169,
            score = 28,
            author = "avonar",
            text = "Firefly reference:\n\nWash: Everything looks good from here.\n[imitating Dino 1]\nWash: Yes... Yes... This is a fertile land and we will thrive. We will rule over all this land and we will call it... This Land.\nWash: [imitating Dino 2] I think we should call it your grave!\nWash: [imitating Dino 1] Ah, curse your sudden but inevitable betrayal!\nWash: [imitating Dino 2] Ha ha ha, mine is an evil laugh, now die!\nWash: [imitating Dino 1] Ahh, no God. Oh, dear god in heaven.\n[sirens start blaring as Wash stares to a radar console]\nWash: Oh, motherless, son of a b...\n\nhttp://www.youtube.com/watch?v=znxFrgql5dc",
            date = "2011-02-28T13:08:46-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26868#comments:id=1353169",
        },
        {
            id = 1182424,
            score = 26,
            author = "226304",
            text = "The provided cache comes with a handy Skin of Dwarven Stout for any other troubles you may be having. Now that's dwarven thinking ahead!",
            date = "2010-11-24T17:20:16-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26868#comments:id=1182424",
        },
    },
