    [26873] = {
        {
            id = 1288395,
            score = 13,
            author = "korokoro",
            text = "Also, it should be noted that once you defeat Mutanus and wake up Naralex at the end, everything else in the instance despawns, allowing you free access to roam about the place and find any Serpentbloom your party may have left behind.",
            date = "2011-01-11T01:58:26-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26873#comments:id=1288395",
        },
        {
            id = 1187265,
            score = 9,
            author = "Nyito",
            text = "There doesn't appear to be enough plants in the instance for more than 1 or 2 people to complete the quest in one go, which I find rather annoying. Doubly so if you plan to only run the instance once just for the quests. It's possible my group didn't run past a certain area filled with enough of these to complete it for everyone, but for an average group running towards bosses only, you won't find enough.",
            date = "2010-11-26T09:39:56-06:00",
