        },
        {
            id = 1302753,
            score = 4,
            author = "540613",
            text = "No longer seem to spawn in the cave outside the instance. However, as someone suggested above, wait until the instance is 'over' and then look at the wowhead map. The dots seemed to be correct for every one I saw.",
            date = "2011-01-21T06:54:50-06:00",
