    [26912] = {
        {
            id = 1438182,
            score = 14,
            author = "Deepfriar",
            text = "This entire quest chain has gotten way, way easier, but this final fight really stands out. I tried as a level 30 Disc priest, and despite thinking I would lose given my experiences pre-Cata, had no problems whatsoever: shield, DOT, HF, Penance, Mind Blast, Smite, repeat. As long as you keep the shield up, you shouldn't even have to heal.\n\nKinda have mixed feelings about the nerfing of this chain. I was glad to see the quests given by the dwarf were eliminated, but I missed the challenge of the original fights.",
            date = "2011-06-10T00:45:22-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26912#comments:id=1438182",
        },
        {
            id = 1937096,
            score = 1,
            author = "964410",
            text = "As an Ice spec Mage I had some trouble with this last fight of the chain solo. It was a nice skill check for the class and spec. I ended up using the Water Elemental as a tank and healing it with Ice Blast. This draws agro from the many elemental minions that get summoned. Two Arcane Blasts takes them down, as they are much weaker than a normal elemental. Just make sure you are far enough away from the main mob to avoid drawing her agro.\n\nWhen the mob gets down to 10% health or so she summons a large number of minions. Heal the Water Elemental through this until you draw the minion agro, then blast away.\n\nSo yea, as a solo quest this can be a great skill check. Very fun rendition of a classic quest chain with the annoying bits thrown out :)",
            date = "2014-01-23T14:13:14-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26912#comments:id=1937096",
        },
        {
            id = 2548971,
            score = 1,
            author = "Habu64",
            text = "Even with the 7.3.5 scaling, this quest line is still very easy to complete.",
            date = "2018-01-28T16:13:54-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26912#comments:id=2548971",
        },
        {
            id = 1401921,
            score = -4,
            author = "simorie",
            text = "Soloed this as a lvl 33 frost mage using a combo of the basic frost bolt, arcane explosion (good on whatever the guys with her are), and ice lance (esp w/ fingers of frost).",
            date = "2011-04-27T18:58:42-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26912#comments:id=1401921",
        },
        {
            id = 1438881,
            score = -4,
            author = "683633",
            text = "Just soloed on my lvl 34 BE Shadow Priest. Finished lvling with the completion of it. Just Shadow word: Pain - Shadow Word: Death - Devouring Plague - Mind Blast - Mind Flay (repeat as spells cool down). If it wasn't for my level up, I would have died by the guardians. But didn't, as Lifebloom (from herbalism) helped.",
            date = "2011-06-10T22:43:06-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26912#comments:id=1438881",
        },
    },
