        },
        {
            id = 1270421,
            score = 5,
            author = "WowheadEnjoyer",
            text = "Run in throw the bomb in the hole quickly then get back outside and AoE down the mobs that follow you. Don't try to fight them inside because they respawn immediately after you kill them, and could overwhelm you if you're around level 34-36.\nGood luck.",
            date = "2010-12-31T22:19:14-06:00",
