        },
        {
            id = 1396897,
            score = 5,
            author = "lucyliu",
            text = "If you're a hunter command your pet to the opposite side of the ramp you are going to run up so all of the skeletons attack your pet not you.Then just wait 2 or 3 seconds (for them all to attack the pet) then just run inside and simply blow up the Scourge Bone Animus.\n\nI was caught by a Opengut Behemoth chain grab and pulled away from the skeletons, so had to fight it off leaving my pet swarmed. One of my pets was killed but on a second attempt with a good tanking pet (eg. a bear) they survive long enough for you to destory the Scourge Bone Animus.",
            date = "2011-04-22T09:48:41-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26922#comments:id=1396897",
        },
