    [26927] = {
        {
            id = 1082680,
            score = 14,
            author = "Toldry",
            text = "Thousands of them!",
            date = "2010-07-17T10:17:07-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26927#comments:id=1082680",
        },
        {
            id = 1181294,
            score = 2,
            author = "skevans",
            text = "This quest was introduced on 24 Nov 2010 as part of patch 4.03a\n\nThis quest is obtained from Mountaineer Kadrell (http://www.wowhead.com/npc=1340) on completion of The Bearer of Gnoll-Edge (http://www.wowhead.com/quest=26864).\n\nThe objective of the quest is to speak with Cannary caskshot (http://www.wowhead.com/npc=44345) who can be found in the stoutlager inn, Thelsamar, next to the bar.\n\nUpon completion you can progress on to smells like a plan (http://www.wowhead.com/quest=26928).",
            date = "2010-11-24T11:29:09-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26927#comments:id=1181294",
        },
        {
            id = 1865569,
            score = 1,
            author = "Aquril",
            text = "I've always wondered how those gnolls & bluegill murlocs got from Wetlands to Loch Modan..?\n\nI mean, look at the map, did they invade and temporarily took over the tunnel passages between the two zones or somehow managed to climb up the rather massive cliffs at the dam?\n\nIf you ask me, i'd bet the tunnels, but who knows, maybe they got wings and flew all the way there!",
            date = "2013-06-12T05:23:03-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26927#comments:id=1865569",
        },
        {
            id = 1981104,
            score = 1,
            author = "936971",
            text = "Suddenly, pineapp-...Murlocs!",
            date = "2014-07-16T09:50:25-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26927#comments:id=1981104",
        },
    },
    [26928] = {
        {
            id = 1181398,
            score = 4,
            author = "skevans",
            text = "This quest was added during patch 4.03a on 24 Nov 2010.\n\nIt is obtained from Cannary Caskshot (http://www.wowhead.com/npc=44345) who can be found in the Stoutlager Inn, Thelsamar, Loch Modan. She is next to the bar at co-ords 34 49.\n\nThe objective of the quest is to obtain 7 Murloc scent glands (http://www.wowhead.com/item=60511/murloc-scent-gland) from Bluegill wanderers (http://www.wowhead.com/npc=44176), Bluegill mudskippers (http://www.wowhead.com/npc=44292) or if your lucky enough Whitefin (http://www.wowhead.com/npc=45401).\n\nOnce complete return to the quest giver to hand in.\n\nI also gained 69 rep with the Alliance and 69 rep with Gilneas (http://www.wowhead.com/faction=1134) on completion of this quest.\n\nCompletion of this quest leads on to Axis of awful (http://www.wowhead.com/quest=26868).",
            date = "2010-11-24T12:00:05-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26928#comments:id=1181398",
        },
        {
            id = 1663023,
            score = 3,
            author = "955759",
            text = "One of the most disturbing quests in WoW. You have to kill the daddy murlocs / mamma murlocs as their kids are watching you.\n\nSometimes I wake up in the middle of the night screaming and I see those baby murlocs watching me. Always watching me with those innocent eyes...",
            date = "2012-05-05T13:14:47-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26928#comments:id=1663023",
        },
    },
    [26929] = {
        {
            id = 1181495,
            score = 5,
            author = "skevans",
            text = "This quest was added on 24 Nov 2010 as part of patch 4.03\n\nThe quest is obtained from Cannary Caskshot (http://www.wowhead.com/npc=44345) who can be found next to the bar in the Stoutlager Inn, Thelsamar, Loch Modan. Her co-ords are 34 49.\n\nLoch crocolisks (http://www.wowhead.com/npc=1693) can be found around the shoreline of Loch Modan.  I attacked ones on the southern edge.\n\nOnce complete head back to the questgiver to hand it in.\n\nIn addition to the published ironforge rep I received 69 rep with both the Alliance and Gilneas (http://www.wowhead.com/faction=1134).",
            date = "2010-11-24T12:37:39-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26929#comments:id=1181495",
        },
        {
            id = 1186637,
