    [26932] = {
        {
            id = 1203775,
            score = 10,
            author = "Tenjen",
            text = "I dont think blizzard knows how buzzards work.\n\nThey eat up the corpses and stop \"all manner of filth and disease\" from spreading and arent quite known to spread it themselves.\n\ninfact the corpses just lying around everywhere will spread to the water.\n\nthen again, dwarf's arent known for knowledge about the ecology",
            date = "2010-12-03T08:51:05-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26932#comments:id=1203775",
        },
        {
            id = 1202411,
            score = 7,
            author = "ShadowHMF",
            text = "Weird, level 15 Gnome Mage standing in front of this fellow and he wont give me his quest, is there another requirements other than being level 13 to get this quest?\n\n/EDIT\nI just went inside the inn and turned a quest in and accepted some others, they were the following quests:\nTurned in; Suddenly, Murlocs!\nAccepted; Smells like A Plan & A Load of Croc\n\nAfter that I was able to pick of this quest called Buzz Off, hope that helps others :)",
            date = "2010-12-02T15:04:21-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26932#comments:id=1202411",
        },
        {
            id = 1185942,
            score = 2,
            author = "321861",
            text = "The Buzzards can also be found flying in the air above the area above, so don't forget to look up every now and then~",
            date = "2010-11-25T20:58:39-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26932#comments:id=1185942",
        },
    },
    [26933] = {
        {
            id = 1082679,
            score = 60,
            author = "Toldry",
            text = "But not before bros.",
            date = "2010-07-17T10:15:41-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26933#comments:id=1082679",
        },
        {
            id = 1669058,
            score = 20,
            author = "993579",
            text = "And when my Shadow Bolt struck him square in the chest, the ninth Alliance Laborer fell... But not before he tossed up his pair of boots into the air. NO! Not again! Fear and disbelief filled my eyes as I watched the boots hurtle toward my head. How did he manage to take them off his feet so quickly? Or did he have an extra pair of boots that he always carried with him, ready to heave at any intruder who crossed his path? It didn't matter though. None of this mattered anymore.\n\nI turned on my heel and ran. I ran until my muscles burned and my veins pumped battery acid. Then I ran some more. I chanced a look over my shoulder to see if gravity had got the better of the flying footwear... But there they were, still airborne. H-HOW? The boots change direction in mid-flight, following my every step... By what ungodly force are they able to defy natural law? And then I realize. These were no mere boots. They were demonic agents of Sargeras; the Destroyer of Worlds himself. There was no escape.\n\nBut there is a bit of distance between us. It's a gamble, but I might have enough time to summon my Felsteed and ride to safety. With haste but firm concentration, I exerted my entire being into reaching into the Nether to call my faithful mount to my rescue. I tremble with exhaustion, but force myself to finish the summoning. I must hurry! I... I hear galloping! My Felsteed has almost entered this plane! Maybe I can get away! Maybe I can actua---\n\n*BONK!*\n\n... The Holy Light has abandoned us all.",
            date = "2012-05-20T14:04:18-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26933#comments:id=1669058",
        },
        {
            id = 1283151,
            score = 15,
            author = "758685",
            text = "For this quest, you have to kill 9 alliance laborers. But what the log doesn't tell you is that they are, bar none, one of the most obnoxious mobs you will come across in this entire game.\nThey will regularly throw a pair of boots at you that make this very cartoony bonking sound, but it knocks you down and interrupts your casting. They do it about every other second. This is kind of the quest from hell for casters, when paired with the other one that has you dropping cannisters around the area.\n\nEdit for clarity: it isn't the boots that does the spell interrupt, it's this kung-fu kick. So there's just more to love about this quest and the follow-up.",
            date = "2011-01-07T23:23:49-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26933#comments:id=1283151",
        },
        {
            id = 1925749,
            score = 14,
            author = "Dongolev",
            text = "Ha ha!  I hope that they come back as zombies.\n\nThe Forsaken military strategy, ladies and gentlemen.",
            date = "2013-12-13T20:58:33-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26933#comments:id=1925749",
        },
        {
            id = 5282690,
            score = 6,
            author = "ThelMi",
            text = "Somehow I doubt the quest name is going to survive much longer",
            date = "2021-11-17T00:09:18-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26933#comments:id=5282690",
        },
    },
