    [26952] = {
        {
            id = 1534444,
            score = 29,
            author = "871628",
            text = "For this quest to appear you first have to do the quest series from Shadow Priestess Vandis. The first one is Foxes and Hounds (http://www.wowhead.com/quest=26931)",
            date = "2011-10-04T03:58:00-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26952#comments:id=1534444",
        },
        {
            id = 5412095,
            score = 2,
            author = "HushGlowie",
            text = "To be eligible to begin this quest you must first complete the two quests that can be obtained from Shadow Priestess Vandis (https://www.wowhead.com/npc=11055/shadow-priestess-vandis) who is in the same camp as Argent Officer Garush (https://www.wowhead.com/npc=10839/argent-officer-garush) but just slightly south.\n\nThe quests in order:\n\nFoxes and Hounds (https://www.wowhead.com/quest=26931/foxes-and-hounds) from Vandis\nFoes Before Hoes (https://www.wowhead.com/quest=26933/foes-before-hoes) from Vandis\nThe Menders Stead (https://www.wowhead.com/quest=26952/the-menders-stead) from Garush",
            date = "2022-08-06T00:18:25-05:00",
            sourceUrl = "https://www.wowhead.com/quest=26952#comments:id=5412095",
        },
