    [26998] = {
        {
            id = 1182985,
            score = 16,
            author = "303769",
            text = "Please go to the bat handler first... I ended up swimming across the lake, and eventually killing off the 50 murlocks, one by one (dying only 3 times when they would flee and run into another pack of murlocks). Only after I killed the 50 murlocks did I realize I had to go to the bat handler, and then fly over the islands and blow them up with bombs.  Also, when you're done killing with bombs, there's a button to \"go home\"... otherwise, you just keep flying around.\nHope this helps!",
            date = "2010-11-24T21:08:02-06:00",
            sourceUrl = "https://www.wowhead.com/quest=26998#comments:id=1182985",
        },
        {
            id = 1651772,
