    [27026] = {
        {
            id = 1964228,
            score = 14,
            author = "MisterCrow",
            text = "According to Blizzard designer Jeremy Feasel (@Muffinus):\n\nFun fact: The quest Defcon  Bobcat in Loch M. was based on a bobcat invading the Blizz lot, major alarm 'till we found out bobcats are cute\n\nSource: https://twitter.com/Muffinus/status/464923833724444672",
            date = "2014-05-09T19:37:18-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27026#comments:id=1964228",
        },
        {
            id = 1637107,
            score = 3,
            author = "Thognus",
            text = "Opening Text:\n\nStop everything!  It's come to my attention that there's been bobcat sightings near the lodge.  Bobcats!\n\nNow mind you, I've never seen a bobcat, but they're surely dangerous.They're like mountain lions or something.  I don't want anyone leaving until the area is secure!\n\nAnyone but you, that is.  I'll pay you to help secure the area, .  But don't get your face ripped off.\n\nEnding text:\n\nOkay, yes, I have already been informed that bobcats are much smaller than I was assuming.  But that's still pretty dangerous for gnomes!\n\nYou've done a good thing for the safety of this lodge, !",
            date = "2012-03-08T19:23:39-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27026#comments:id=1637107",
        },
        {
            id = 2312446,
            score = 1,
            author = "Atratzu",
            text = "the real story behind the name of this quest is hilarious, but honestly the first thing that came to mind mind was \"This sounds like some pun Bubsy Bobcat would think up\".",
            date = "2016-03-06T12:42:49-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27026#comments:id=2312446",
        },
        {
            id = 1203957,
            score = 0,
            author = "Tenjen",
            text = "somehow this doesnt sound very ecological secure. The world is screwed up enough without screwing up the ecology more so that everythings say..covered in rabbits which destroy the plant life and turn the not lakeless loch in a grassless desert",
            date = "2010-12-03T10:47:50-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27026#comments:id=1203957",
        },
    },
    [27028] = {
        {
            id = 1914905,
            score = 1,
            author = "885261",
            text = "Hornets can be found on the eastern shore and dried out lake bed of the Loch. The drop rate for the wings is around 33%.\nOther creatures of interest in the area are Mudbelly Boars which are the targets of The Joy of Boar Hunting (http://www.thottbot.com/quest=27016).\nIf you are lucky, you can run into Nix (http://www.thottbot.com/npc=45402) who also has a 33% chance of dropping a wing.\nAnd of course, Ando Blastenheimer (http://www.thottbot.com/npc=44870) is standing there next to a crashed biplane. He has three quests for you if you follow the quest chain starting with Wing Nut (http://www.thottbot.com/quest=27031).",
            date = "2013-11-04T12:50:49-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27028#comments:id=1914905",
        },
    },
