    [27033] = {
        {
            id = 1425998,
            score = 7,
            author = "Aislinge",
            text = "On collecting this quest from Farstrider Lodge, you head to Ironwing cave - the entrance looks onto Ironbrand's Excavation.\n\nOnce inside, you fight mechanical striders and chickens to reach the Rusted Skystrider.\n\nHowever, although the quest text reads as if there's an item, it doesn't give you one and there isn't one to find - the Supermechanical Robo-Widget doesn't exist as an item. In spite of this, the quest will still turn in no problems.\n\nA few bonus things to watch for when completing this quest (and being in this area in general). I stumbled across 3 elites:\n\nhttps://www.wowhead.com/npc=14268\nhttps://www.wowhead.com/npc=45399\nhttps://www.wowhead.com/npc=14266\n\nVery nice XP to be earnt from these for the level, so keep an eye out!",
            date = "2011-05-24T04:19:57-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27033#comments:id=1425998",
        },
    },
    [27034] = {
        {
            id = 1364775,
            score = 3,
            author = "TheDash",
            text = "A Gnome having teenage moodiness sounds like an odd concept, I thought they didn't hit puberty until their mid twenties?",
            date = "2011-03-12T07:08:20-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27034#comments:id=1364775",
        },
        {
            id = 3168774,
            score = -1,
            author = "Larlard",
            text = "\"Not even for gnomekind. I want my son to be the one to fly it.\" That is legitimately the worst phrasing I've ever seen in a WoW quest. He could have simply said, \"I'm not making the Skystrider for me. I want my son to be the one to fly it out, but it's not even meant for gnomekind.\" I always assumed he adopted a dwarf or something, but lo and behold, his son is a gnome. They really should have worked out the dialogue before putting it into game, because if anyone is like me, they would have assumed his son is not a gnome.",
            date = "2019-11-02T15:12:49-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27034#comments:id=3168774",
        },
    },
    [27035] = {
        {
            id = 1196838,
