    [27037] = {
        {
            id = 1439580,
            score = 12,
            author = "360859",
            text = "I accepted this quest from NPC Daryl the Youngling (http://www.wowhead.com/npc=1187). The item Ol' Sooty's Head (http://www.wowhead.com/item=2713) was placed in my inventory immediately.\n\nI turned in this quest to nearby NPC Vyrin Swiftwind (http://www.wowhead.com/npc=1156) mere moments later. The quest text implied I had hunted and killed a bear, removed its head, then scared Daryl the Youngling with it.\n\nAll I did was:\n\nAccept quest, receive head immediately.\n\nComplete quest by turning in head to nearby NPC. Chose my reward and that was all. (http://www.wowhead.com/npc=1187)",
            date = "2011-06-11T22:22:46-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27037#comments:id=1439580",
        },
        {
            id = 1647295,
            score = 10,
            author = "pellmell",
            text = "If you completed the preceding quest, https://www.wowhead.com/quest=27036, prior to Cataclysm, you will not be able to repeat it.  However, this quest will be available for you regardless of if you completed it before Cataclysm or not.\n\nSo if you find yourself being congratulated for killing a bear with no (recent) memory of having done so, just roll with it, accept the rewards, and move on. :)",
            date = "2012-04-01T03:06:26-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27037#comments:id=1647295",
        },
        {
