    [27045] = {
        {
            id = 1287966,
            score = 91,
            author = "571252",
            text = "If you skip the cinematic of the meeting between the two Worgen you will not get completion credit for the quest and will have to go to the outhouse to summon Yorick again.",
            date = "2011-01-10T18:28:44-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27045#comments:id=1287966",
        },
        {
            id = 1179249,
            score = 29,
            author = "626418",
            text = "Be sure to talk to the outhouse again once you've accepted the quest to start the event.",
            date = "2010-11-23T21:10:35-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27045#comments:id=1179249",
        },
        {
            id = 1185698,
            score = 28,
            author = "139511",
            text = "If someone's not familiar with the word, \"exsanguination\" basically means bleeding out.",
            date = "2010-11-25T18:55:01-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27045#comments:id=1185698",
        },
        {
            id = 1182683,
            score = 27,
            author = "708316",
            text = "The completion quest text is in reference to Shakespeare's Hamlet, Yorick being the deceased court jester.\n\nAlas, poor Yorick! I knew him, Horatio: a fellow of infinite jest, of most excellent fancy.",
            date = "2010-11-24T19:01:25-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27045#comments:id=1182683",
        },
        {
            id = 1326259,
            score = 16,
            author = "Sketchie",
            text = "When you receive the quest, you will then have to go to the Outhouse next to a House in the Ivar Patch to actually start the quest. When you start the quest, the following happens.\n\nDeathstalker Rane Yorick says: We haven't got much time. Crowley will be arriving shortly. Let's go!\n\nShe will then lead you to the second floor of the house next to the outhouse.\n\nDeathstalker Rane Yorick says: THERE! Hide in the armoire! I'll hide in the shadows next to you.\n\nExamine the armoire and you will automatically enter. Yorick will go into stealth mode next to the armoire. Lord Darius Crowley and Packleader Ivar Bloodfang will then enter the room.\n\nLord Darius Crowley says: Have you given any more thought to my proposal, Ivar?\nPackleader Ivar Bloodfang says: Why trust you now, Crowley? You abandoned us. Left us to die.\nLord Darius Crowley says: If we're to win the war we will need your help. Our packs must unite! The Forsaken will destroy us otherwise.\nLord Darius Crowley says: You are the alpha male, Ivar. The rest of the ferals in Silverpine will do as you command.\nPackleader Ivar Bloodfang says: I don't care about your war, Crowley.\nPackleader Ivar Bloodfang says: But...\nPackleader Ivar Bloodfang says: I have seen firsthand what the Forsaken are capable of doing. It is true. They hunt us... slaughter the defenseless.\nLord Darius Crowley says: So you will help?\nPackleader Ivar Bloodfang says: Aye, I will gather my pack... we...\n\nPackleader Ivar Bloodfang will then walk towards you while sniffing the air.\n\nPackleader Ivar Bloodfang sniffs at the air.\nPackleader Ivar Bloodfang says: It would appear we are being watched, Crowley. You have grown soft... Likely Greymane's fault.\n\nPackleader Ivar Bloodfang then howls and snatches Deathstalker Rane Yorick out of the shadows and holds her up.\n\nPackleader Ivar Bloodfang says: Treacherous little pup!\nPackleader Ivar Bloodfang says: What say you now, spy?\nDeathstalker Rane Yorick says: I live... and die... for the Banshee Queen.\nPackleader Ivar Bloodfang says: I was hoping you'd say that...\n\nI'm not sure what exactly happens here, but Packleader Ivar Bloodfang then throws Yorick across the room and it's enough to kill her.\n\nPackleader Ivar Bloodfang says: I will prepare the pack. It will take some time to gather them all, but we will join... for now.\n\nPackleader Ivar Bloodfang and Lord Darius Crowley departs.",
            date = "2011-02-07T23:36:58-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27045#comments:id=1326259",
        },
    },
