    [27069] = {
        {
            id = 1185771,
            score = 43,
            author = "139511",
            text = "The boxes were too heavy, so my Orc Pup harnessed his inner power and ended up carrying the crates with nothing but his sheer force of will.\n\nhttp://i.imgur.com/vXw0d.jpg\n\nHe is truly in balance. You can see the focused expression, the wisdom in his eyes...",
            date = "2010-11-25T19:31:11-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27069#comments:id=1185771",
        },
        {
            id = 1181471,
            score = 37,
            author = "Zenodice",
            text = "I love the comments in this quest from the pup, they are hilarious, as is the way the sea pup leans forward when he's carrying the boxes.\n\nOrc Pup Says: OOF! Maybe trow little softer, captain?        (1/5 boxes)\nOrc Pup Says: Maybe captain carry one box too?    (2/5 boxes)\nOrc Pup Says: Dis giving me a hernia. Captain, what is hernia? (3/5 boxes)\nOrc Pup Says: ME NO SIGN UP FOR DIS! WAIT!  Yes, me did sign up for dis. (4/5 boxes)\nOrc Pup Says: Dis hurt so bad. Like da time poop came out sideways. (5/5 boxes)\n\nI lol'd, poor, poor sea pup and his sideways poops.\n\nThen once you hand it in, he says Orc Pup Says: Where to put? Dey Falling! HELP!",
            date = "2010-11-24T12:29:17-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27069#comments:id=1181471",
        },
        {
            id = 1181740,
            score = 27,
            author = "tmptfate",
            text = "The dialog appears to be different a little for everyone, my helper said different stuff:\n\nOrc Pup Says: Dis not so bad. Maybe little heavy, but me ok.\nOrc Pup Says: Heavy... me no can see notin.\nOrc Pup Says: Captain, pup need help!\nOrc Pup Says: CAN NO SEE! WHERE TO GO? WHAT DOING?\nOrc Pup Says: Please... Kill... Me...\n\nLines 4 and 5 are hilarious, this is definitely one of my favorite quests now, haha.",
            date = "2010-11-24T13:50:34-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27069#comments:id=1181740",
        },
        {
            id = 1210937,
            score = 19,
            author = "Bahthalend",
            text = "The sideways poop comment made me lol pretty damn hard, it just came out of nowhere.",
            date = "2010-12-06T22:59:03-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27069#comments:id=1210937",
        },
        {
