    [27084] = {
        {
            id = 1607888,
            score = 8,
            author = "jjanchan",
            text = "This is a fairly straightforward quest.  The item you get once you accept it, https://www.wowhead.com/item=60815 releases a gargoyle at the location you specify with the targeting reticle.  Immediately south of where you picked up the quest is a field where seemingly infinite numbers of https://www.wowhead.com/npc=44944 are attacking the Opengut Behemoths.  Simply use the item and target the ground in the general vicinity of one of the https://www.wowhead.com/npc=44944 six times to complete the quest.\n\nYou will not actually see any gargoyles until you release them with the item, so don't go looking for them!\n\nThis quest is part of a chain that culminates in a very neat cutscene, revealing some plot points for the Horde.  As there are some spoilers, mouseover to read more!\n\n[spoiler]\nBelow is the quest progression you will follow:\n\nhttps://www.wowhead.com/quest=27083\nhttps://www.wowhead.com/quest=27084\nhttps://www.wowhead.com/quest=27086\nhttps://www.wowhead.com/quest=27087\nhttps://www.wowhead.com/quest=27089\nhttps://www.wowhead.com/quest=27090\nhttps://www.wowhead.com/quest=27144\n\n[/spoiler]",
            date = "2012-01-07T01:56:09-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27084#comments:id=1607888",
        },
        {
            id = 2127321,
            score = 6,
            author = "1022826",
            text = "Today, all of the human bugged out, stacking one another. I was still able to use gargoyles on them.  Weird",
            date = "2015-03-02T22:38:14-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27084#comments:id=2127321",
        },
        {
            id = 1199328,
            score = 3,
            author = "Skalbunk",
            text = "Can only Undead do this? If so, can you get it if you're exalted?\n\nI dont see it on Koltira when I talk to him..unless there's a follow up quest?",
            date = "2010-12-01T03:23:26-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27084#comments:id=1199328",
        },
        {
            id = 1184612,
            score = 2,
            author = "celinamuna",
            text = "If you want cheap fast xp, just stand in front of abominations and do any aoe to tag them, just dropping my explosive trap there, would give me about 1k xp each wave, which is kind of fast for not really doing anything.",
            date = "2010-11-25T11:02:48-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27084#comments:id=1184612",
        },
        {
            id = 1360718,
            score = 2,
            author = "800279",
            text = "Did anyone get a reply on this?  I don't see this on Koltira either and would definitely like to get this series of quests completed.  It's all I need to complete Zone quests for all of Eastern Kingdom.  Any help would be greatly appreciated.\nThanks!",
            date = "2011-03-07T23:13:59-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27084#comments:id=1360718",
        },
    },
    [27085] = {
        {
            id = 1969881,
            score = 5,
            author = "PunterHunter",
            text = "To do this quest you'll have to do https://www.wowhead.com/quest=26921, https://www.wowhead.com/quest=26925, https://www.wowhead.com/quest=26922, https://www.wowhead.com/quest=27117 and https://www.wowhead.com/quest=26924. https://www.wowhead.com/quest=26926 will lead you to The Bulwark . Complete the Quests there and you should receive https://www.wowhead.com/quest=26979, after that the quest giver will tell you to head to \"the Mender's Stead\" once there speak with https://www.wowhead.com/npc=45013 who will give you the quest https://www.wowhead.com/quest=27083, once back in Andorhal https://www.wowhead.com/quest=27085 and a couple other quests should be available :3",
            date = "2014-06-03T16:54:19-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27085#comments:id=1969881",
        },
        {
            id = 1692535,
            score = 4,
