    [27094] = {
        {
            id = 1428425,
            score = 21,
            author = "Shirohibiki",
            text = "I think I had a mini-heart attack when doing this quest. I went through the tunnel, and when I got to the end, I expected to see her there waiting for me. I didn't, so I figured someone had killed her and I had to wait for her to respawn.\n\nNope.\n\nShe slowly came down from the ceiling, and I practically fell out of my chair. It scared me half to death. Blizz did a great job with this quest; it was a uniquely nice touch to have her lurking on the ceiling. :)",
            date = "2011-05-27T01:01:54-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27094#comments:id=1428425",
