    [27107] = {
        {
            id = 1275261,
            score = 61,
            author = "271529",
            text = "If you're doing this instance to complete all the quests in Dire Maul you must talk to this guy and chase him through the instance before you can kill him.\n\nHe is to the left of the main entrance standing where the pathway is broken, you'll have to talk to him 4 times before he runs up a set of stairs to the area where you talk to him a final time and he summons about 6 imps to attack you.\n\nIf you chose not to talk to him, you won't be able to kill him and get the quest item needed.",
            date = "2011-01-03T13:57:47-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27107#comments:id=1275261",
        },
        {
            id = 1185878,
            score = 9,
            author = "Diwtay",
            text = "Ooooo I hate this little guy! The only thing more satisfying than punting a gnome would be punting this brat. After picking up the quest he's to your immediate left. Talk to him. He gives you lip and then runs away. When he stops, talk to him again. Rinse and repeat. At the end he summons \"friends\" to attack you. It might help to mark him with a raid marker.",
            date = "2010-11-25T20:23:58-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27107#comments:id=1185878",
        },
        {
            id = 1274926,
            score = 8,
            author = "Species3259",
            text = "For anybody who wonders what that key is hes talking about all the time.\n\nPusilling used to be the holder of the Crescent Key (http://www.wowhead.com/item=18249/crescent-key), needed to enter the West and North part of Dire Maul (plus back entrance).\n\nApperently Blizzard found new use for him with this quest but could not be bothered (?) to change his dialogue.",
            date = "2011-01-03T10:26:21-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27107#comments:id=1274926",
        },
        {
            id = 1817704,
            score = 7,
            author = "Kilroy7456",
            text = "What is it with tanks being so damn pissy about skipping this quest? I typically only run dungeons once as I'm leveling, and it still seems like every alt I try to bring through here has to have at least one experience where a tank tries to skip this then initiates a vote kick when I suggest we do it. It's free freaking exp, get over yourself.\n\nand sadly all the dps immediately click yes without thinking each time. ._.",
            date = "2013-02-24T12:16:43-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27107#comments:id=1817704",
        },
        {
            id = 1606564,
            score = 5,
            author = "Etreum",
            text = "If you lose him, he will eventually lead you to the Hidden Reach.  Once you talk to him at the main floor of the Hidden Reach, he will go up the ramp where you will talk to him one last time.  He will then turn to an elite and have some adds.  Kill him and you will get the Book of Incantations.\n\nI pretty much did all the other quests/bosses and left him for last.",
            date = "2012-01-04T16:38:35-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27107#comments:id=1606564",
        },
    },
    [27108] = {
