    [27109] = {
        {
            id = 1961186,
            score = 18,
            author = "noxcrucifix",
            text = "This NPC can be killed by players in your group. It's unfortunate and annoying but fear not, he will respawn. I'm unsure of his respawn time, but from personal experience I witnessed my group's hunter kill the watcher when we zoned in and by the time we had finished the dungeon and returned to the beginning he was back up. You can still turn in your quests :)",
            date = "2014-04-25T22:18:41-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27109#comments:id=1961186",
        },
        {
            id = 1579610,
            score = 16,
            author = "680985",
            text = "You can find Tendris Warpwood in Dire Maul West. (Capital Gardens for those using Dungeon Finder)",
            date = "2011-11-24T03:36:55-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27109#comments:id=1579610",
