        {
            id = 1914285,
            score = 13,
            author = "Bogdanov89",
            text = "This NPC can easily be killed by players - and if u do kill him, you can not take his quest...\n\nReally really stupid...",
            date = "2013-11-02T13:17:40-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27109#comments:id=1914285",
        },
        {
            id = 2301891,
            score = 7,
            author = "LiriellGarrosh",
            text = "For those needing to turn in this quest after queuing via dungeon finder, the entrance is located inside Dire Maul Broken Commons on the west wall. The good news is, you don't have to fight anything to get to him, so you can enter by yourself and discretely exit with no trouble.",
            date = "2016-01-26T14:55:02-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27109#comments:id=2301891",
        },
    },
    [27110] = {
        {
            id = 1206267,
            score = 45,
            author = "708174",
            text = "The 5 pylons are:\n\n1 is in the eastern courtyard (right by the entrance).\n2 are on the upstairs balcony above Tendris Warpwood.\n2 are in the Prison of Immol'thar area, on the eastern side.\n\nTo disable them you just kill the elementals around them. Once you've disabled all 5 you'll see:\n\n\"Highborne Summoner yells: The demon is loose! Quickly we must restrain him!\"\n\nImmol'thar is in middle of Prison of Immol'thar and Prince Thortheldrin is in the Athenaeum, below the stairs.",
            date = "2010-12-04T14:22:36-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27110#comments:id=1206267",
        },
        {
            id = 1589794,
            score = 9,
            author = "hypehuman",
            text = "For help with this quest, see the comments on the old version of the quest (the comments still apply): https://www.wowhead.com/quest=7461",
            date = "2011-12-04T21:01:15-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27110#comments:id=1589794",
        },
        {
            id = 1312954,
            score = 7,
            author = "136440",
            text = "Leads to The Treasure of the Shen'dralar (http://www.wowhead.com/quest=27111).",
            date = "2011-01-28T07:33:35-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27110#comments:id=1312954",
        },
        {
            id = 5761565,
            score = 3,
            author = "Kewlzilbot",
            text = "ALL pylons are inside the West side dungeon (starting map, Capital Gardens).\nClear Pylons by killing the mana-type mobs around it.\n1st pylon in courtyard at entrance\nTo get to 2nd/3rd pylons, go up (by going thru far-right arch), then go thru next arch on walkway to the right to get to the Court of the Highborne map area. Take the ramp in front of you to get to the top-floor level of the Capital Gardens map - this is where pylons 2 and 3 are - same level as boss Illyanna Ravenoak.\nJump back down to the courtyard\nTake the middle arch to go down, and kill Tendris Warpwood.\nTo get to the last 2 pylons, to the RIGHT of where you killed Tendris is an interactive door, click it to get to the Prison of Immolthar area.\nLast 2 pylons are in the outer ring of the prison area; map will show you how to get to Prince Tortheldrin to finish the quest.\nNote that the exit is back the way you came.",
            date = "2024-01-07T22:41:59-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27110#comments:id=5761565",
        },
        {
            id = 1204152,
            score = -5,
            author = "488143",
            text = "no one of the quest inside dire maul west count towards feralas quests achievement, but u will get +1 just getting inside the dungeon lol :P",
            date = "2010-12-03T12:51:29-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27110#comments:id=1204152",
        },
    },
    [27111] = {
        {
            id = 1231509,
            score = 47,
            author = "Alanoor",
            text = "Alanoor\nSkywall\n\nIt's in Dire Maul West.  Right after entering the instance, you go straight across the Capital Gardens to the Court of the Highborne; fighting the usual mobs.  You are gonna go to the center archway where you see a gold statue on the far side.  This will lead you to Tendris Woodwarp, kill the boss and open the wooden door on the right corner.  Go through the door and down the corridor, fight the usual crits.  You are going to end up in a large circular room, go to your right and there will be another corridor along the same wall.  Go down the corridor, and at the end you will come to a room, go to your right and go down the staircase.  Make a left U-turn, and the treasure will be in an ark underneath the stair case.\n\nGood luck.",
            date = "2010-12-13T21:21:00-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27111#comments:id=1231509",
        },
        {
            id = 1575854,
            score = 12,
            author = "805362",
            text = "All of the quest rewards have pretty cool models, by the way. Worth running, if you like nice-looking weapons.",
            date = "2011-11-19T12:58:17-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27111#comments:id=1575854",
        },
        {
            id = 1343535,
            score = 11,
            author = "729499",
            text = "Really wanna know how to get this quest.\n\nThe 1h would be BiS for 39 twinks if you didn't get Mallet of ZF.",
            date = "2011-02-20T14:09:24-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27111#comments:id=1343535",
        },
        {
            id = 1329662,
            score = 2,
            author = "alexp",
            text = "Hi, I found the NPC who gives the quest but he gave a couple of other ones instead. Do I have to finish them before i get this?",
            date = "2011-02-10T00:50:16-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27111#comments:id=1329662",
        },
        {
            id = 2423925,
            score = 2,
            author = "Cthulhu",
            text = "If you see no reward when trying to hand it in and are here to check why, it's because your spec has no equippable rewards from this quest, and you can no longer choose what you get - the game chooses for you.\n\nHunters, switch to Survival then hand in and you'll get a trident, which will at least vendor for some gold. Rogues, you'll have to go Outlaw to get the mace. Warriors, go to either of your non-Protection specs, and Pallies go Retribution, to get the axe. Frost DKs, what are you even doing here?",
            date = "2016-10-07T21:45:18-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27111#comments:id=2423925",
        },
    },
    [27112] = {
        {
            id = 1231154,
            score = 1,
            author = "Alanoor",
            text = "Alanoor\nSkywall\n\nThis is located in Dire Maul West.  If you are facing the archway that leads down to Tendris Warpwood, there is another archway to your right that leads to the balcony above Warpwood.  On the first level of the balcony area you can find Illyana Ravenoak roaming around.  When you go up on the 2nd level of the balcony area you can find Magister Kalendris roaming around.",
            date = "2010-12-13T18:33:41-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27112#comments:id=1231154",
        },
    },
