    [27116] = {
        {
            id = 1184895,
            score = 19,
            author = "Naris17",
            text = "It's official: We need rocket boosted mechanostriders.\n\nIf only to get the fun reaction from the Dwarvish Mountaineers:\n\n\"What in the blazes WAS that?  A flying mechanostrider?\n\nYou know what, I don't want to know.  I'm just going to pretend that it didn't happen, and we'll be all nice and businesslike.\"\n\nPriceless.",
            date = "2010-11-25T13:07:37-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27116#comments:id=1184895",
        },
        {
            id = 1190733,
            score = 13,
            author = "tritium4ever",
            text = "If you're on a PvP server, the flight will get you flagged for PvP since it briefly takes you into the Wetlands before looping back to Algaz Station.",
            date = "2010-11-27T14:51:40-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27116#comments:id=1190733",
        },
        {
            id = 1522973,
            score = 6,
            author = "Nappa",
            text = "Quite the fun ride! The sunset didn't hurt either :)\n\nhttp://www.youtube.com/watch?v=81OvOklhkRI (http://www.youtube.com/watch?v=81OvOklhkRI)",
            date = "2011-09-20T13:22:35-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27116#comments:id=1522973",
        },
        {
            id = 2482397,
            score = 3,
            author = "StriderRyu",
            text = "I was a little disappointed that there wasn't a quest to take me by what's left of the damn or one that would prompt me to head through the tunnel to the Wetlands.  According to Wholly, I completed all the quests that began in Loch Modan.",
            date = "2017-04-02T14:14:56-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27116#comments:id=2482397",
        },
        {
            id = 2069846,
            score = 2,
            author = "736173",
            text = "I cannot be the only one concerned about that fact that this kid says he was going to become an Adventurer like us, ride his \"Prototype fly mechano-strider\" off into the sunset and never been seen or heard from again?\n\nI know it's not Goblin engineering so chances of mid-air explosion is low, but most Gnome engineered planes I see in the world had a... Rough landing. I hope you made your dream come true kid, also hoping you are not a red smear somewhere.",
            date = "2014-12-15T16:27:55-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27116#comments:id=2069846",
        },
    },
