    [27119] = {
        {
            id = 1170716,
            score = 85,
            author = "Meepmeep",
            text = "This appears to be the new way to get Gordok Ogre Suits (Excluding Tailoring/Leatherworking) in Cataclysm\n\nIt has both advantages and disadvantages over the pre-Cata version\n\nAdvantage is that you no longer need to supply Bolts of Runecloth, Rugged Leather or Rune Thread\n\nHowever, the Disadvantage is that it appears to no longer grant 75 Steamwheedle Cartel Rep\n\nEdit: Just cleared it up a little bit\n\nSecond Edit: Why was i marked down?",
            date = "2010-11-14T10:21:45-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27119#comments:id=1170716",
        },
        {
            id = 2504590,
            score = 68,
            author = "jdmaddison",
            text = "The entrance to the Gordok Commons is located at\n/way Feralas 62.31 24.92\nWith two other instances nearby, things can get kind of confusing.",
            date = "2017-06-27T22:35:46-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27119#comments:id=2504590",
        },
        {
            id = 1498518,
            score = 42,
            author = "273434",
            text = "The https://www.wowhead.com/item=18240 is on the floor right above where the goblin was, though there's only one per instance from what I've seen from the basket though. It can also be found in https://www.wowhead.com/object=179501 which you need https://www.wowhead.com/item=18250 to unlock the goblin. The key has a instance zone drop basically.\n\n*edit - Forgot to mention https://www.wowhead.com/npc=14351 spawns when you open the basket  :x",
            date = "2011-08-19T11:09:41-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27119#comments:id=1498518",
        },
        {
            id = 1186393,
            score = 31,
            author = "Valdan",
            text = "No longer gives rep",
            date = "2010-11-26T00:50:56-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27119#comments:id=1186393",
        },
        {
            id = 1689336,
            score = 18,
            author = "1015149",
            text = "Though it has yet gone untested the new setup for this quest makes it impossible to do during random dungeon finder. Specifically, only one https://www.wowhead.com/object=179499 exists per instance, as most people already know. For those that end up in a lot of random groups that don't read instructions, the idea of the quest is to make a disguise and sneak past the next boss: https://www.wowhead.com/npc=14325\n\nConsidering only 1 tanin is available per instance, only one person would be able to sneak by. Prepare for a rush to see who can be the only person in your group to complete the quest, and then have fun fighting the boss because the whole group will never be able to sneak by. Only way to finish the quest as intended seems to be if you return and solo it later.\n\nFor the record the above boss is in a hall and spawns adds/uses fear. I recommend kiting him to the end of the hall you came in and tanking him there to prevent fear-aggroing the next room. Just Saiyan.",
            date = "2012-07-18T00:15:24-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27119#comments:id=1689336",
        },
    },
    [27120] = {
        {
            id = 1186396,
            score = 18,
            author = "Valdan",
            text = "No longer gives rep",
            date = "2010-11-26T00:51:29-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27120#comments:id=1186396",
        },
        {
            id = 1416743,
            score = 14,
            author = "Armyboy44",
            text = "With or without reputation it still puts the lotion on it's skin\n\nPatch 4.1 run\nThe basket still spawns once!\nIt is found at the far corner of the balcony.  Kill the mobs and only one person can pick up the Ogre Tannin.  That person goes back to Knot Thimblejack (28.4, 55.4)  and turns in quest to get the suit.  That person will wear it to fool Captain Kromcrush and avoid this fight. The loot that would normally drop off him is added to the tribute chest.",
            date = "2011-05-12T10:17:00-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27120#comments:id=1416743",
        },
        {
            id = 1797568,
            score = 7,
            author = "Giltho",
            text = "After you pick up the quest, kill everyone and head up the ramp. Look for a basket on the floor before you head up the next ramp. The basket is the Ogre Tannin you need to turn in. GOOD LUCK",
            date = "2013-01-13T00:05:01-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27120#comments:id=1797568",
        },
        {
            id = 1498520,
            score = 5,
            author = "273434",
            text = "The https://www.wowhead.com/item=18240 is on the floor right above where the goblin was, though there's only one per instance from what I've seen from the basket though, also https://www.wowhead.com/npc=14351 spawns once you open the basket. It can also be found in https://www.wowhead.com/object=179501 which you need https://www.wowhead.com/item=18250 to unlock the goblin. The key has a instance zone drop basically.",
            date = "2011-08-19T11:12:06-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27120#comments:id=1498520",
