    [27144] = {
        {
            id = 1554141,
            score = 71,
            author = "807418",
            text = "Under the Undercity? A city that is already named for being under another city?\n\nYo dawg...",
            date = "2011-10-26T10:53:24-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27144#comments:id=1554141",
