    [27154] = {
        {
            id = 1199060,
            score = 13,
            author = "beckiesuedalton",
            text = "He's not in the Mage Tower (the one with the sadisticly-architected interior rampways); he's in the watchtower (the one with the single spiraling staircase).",
            date = "2010-12-01T00:04:54-06:00",
