    [27159] = {
        {
            id = 1209154,
            score = 6,
            author = "328410",
            text = "Any of the Scourge in the area will count for the quest. It doesn't matter if they are in combat with a faction NPC, when you target and hit them, you will get aggro and the kill will count. The faction NPCs do not hit them very hard at all so don't count on their help.\n\nThe big hulking things have a chain that will pull you to them if you try to attack from range. Just be aware. It will interrupt any spell casting.",
            date = "2010-12-05T21:23:17-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27159#comments:id=1209154",
        },
        {
            id = 3190292,
            score = 1,
            author = "Fluffmeister",
            text = "If you're quite low level (I'm 37), watch out for Felbats with a strength of 130K that will kill you instantly. If you resurrect, they'll kill you again.",
            date = "2020-02-14T14:47:19-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27159#comments:id=3190292",
        },
    },
    [27160] = {
        {
            id = 1209996,
            score = 9,
            author = "Jrubzjeknf",
            text = "Abominations... strong.\n\n... stronger.\n\nThis guy is smart!",
            date = "2010-12-06T10:07:37-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27160#comments:id=1209996",
        },
        {
            id = 1209181,
            score = 7,
            author = "328410",
            text = "These mobs have a nasty chain that they use to pull you into melee range if you attack from afar. It interrupts your spells. Otherwise, they don't hit that hard, lol.",
            date = "2010-12-05T21:43:30-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27160#comments:id=1209181",
        },
    },
    [27161] = {
        {
            id = 1188882,
            score = 149,
            author = "iamcal",
            text = "The Scourge Bone Animus is a pile of bones on the floor in the tower, not a mob",
            date = "2010-11-26T21:18:24-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27161#comments:id=1188882",
        },
        {
            id = 1209176,
            score = 42,
            author = "328410",
            text = "This is a neat quest.\n\nGo northeast from the quest giver and you will see a tower. Between you and it there are about 3-4 sets of faction NPCs fighting Scourge. You can either stop and battle all of them on the way or do as I did and just run past them to the tower. As long as they are in combat with the faction NPC they will not aggro you.\n\nWhen you get to the bottom of the tower ramp you will get skeletons jumping all over you. I think there were about 15 on me. But one grenade and they were gone. Boom!\n\nAfter you kill the first group you will see the big pile of bones inside the tower lobby. Hit it next, and again, one grenade will do the trick. Once the bone pile is gone you can use one final grenade on the few mobs that spawned between the first grenade and hitting the bone pile.\n\nBe sure to leave quickly. The respawn on the bone pile is about 15 seconds. I had to kill it twice.\n\nDon't let the number of skeletons intimidate you. They are lightweights and don't hit hard. But the bones spew them at a rate of about 1 every second until there are 15 or 20 there.\n\nFun quest.",
            date = "2010-12-05T21:38:45-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27161#comments:id=1209176",
        },
        {
            id = 1558223,
            score = 16,
            author = "FuryWar",
            text = "Step 1:  Find tower at 42.66\nStep 2:  Toss grenades at skeletons.\nStep 3:  Toss grenade at flaming bones up inside tower.\nStep 4:  Return to claim reward and have a pint of Ale!",
            date = "2011-10-31T04:01:32-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27161#comments:id=1558223",
        },
        {
            id = 1859810,
            score = 7,
            author = "1065792",
            text = "Thanks for pile of bones tip.\np.s. there is nothing at top of tower even if you battle your way all the way up there",
            date = "2013-05-29T23:14:05-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27161#comments:id=1859810",
        },
        {
            id = 1934574,
            score = 5,
            author = "m00nchild313",
            text = "ok so ... i killed all 5 berserkers but i can't find an animus ... am i doing something wrong? not looking in the right place? been wandering around here for like 40 mins trying to find one of these things ...",
            date = "2014-01-14T14:18:50-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27161#comments:id=1934574",
        },
    },
    [27162] = {
        {
            id = 1181548,
            score = 12,
            author = "447168",
            text = "When you get Gandling to about 50% hp, he will lift you in the air, and Koltira and Thassarian will come and finish him off, after he teleports away, Koltira and Thassarian will have the following conversation:\n\nThassarian: Koltira! I had heard rumours that you were here in Lordaeron.\nKoltira Deathweaver: You had heard correctly, Thassarian. I wanted to give you a chance to kill me again.\nThassarian; It looks like it may have to come to that.\nKoltira Deathweaver: Yes, it may... but not today. with the scourge out of the way, I plan to pull my troops back and regroup.\nThassarian: I see. Then I will do the same.\nThassarian: But you must be aware, Koltira: we are brothers no longer. You are a member of the horde now, and I of the Alliance.\nThassarian: Eventually we will fight this battle for Andorhal, and only one of us can walk off of this battlefield victorious.\nKoltira Deathweaver: Yes, I know. And don't think I'll go easy on you.\n\nThassarian says: Very well. I look forward to it.\n\nKoltira Deathweaver whispers: You are not to speak to ANYONE about the agreement that was made today, . Consider this an order from your direct superior.\n\n(note: this is the horde version, missed the '500 reputation with stormwind', and wowhead was/is showing '?' at side)",
            date = "2010-11-24T12:54:53-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27162#comments:id=1181548",
        },
        {
            id = 1198757,
            score = 11,
            author = "168407",
            text = "It's good that Thassarian and Koltira command you not to reveal their torrid love affair, as Don't Ask Don't Tell has not yet been repealed. They could get in huge trouble!",
            date = "2010-11-30T20:35:59-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27162#comments:id=1198757",
        },
        {
            id = 1209146,
            score = 4,
            author = "328410",
            text = "This is one of the 3 quests you get that take you deeper into the town. There are battles between NPCs (your faction) and the soon-to-be-routed Scourge mobs.\n\nYou should get all three of these quests together--Araj, Gandling, and Rattlegore.\n\nThis is important: if the faction NPCs are fighting the Scourge mob you can run past and not aggro them. If the mob is not in combat or kills the faction NPC while you are in proximity you will be targeted.\n\nFairly challenging for me as a L36 Resto Shaman to burn him down to halfway. Idk if he has a nature resistance or some sort of healing convention, but it seemed like it took a very long time. He has higher health than the other two mini bosses but you also only have to get him to 1/2 health.",
            date = "2010-12-05T21:19:31-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27162#comments:id=1209146",
        },
        {
            id = 2314946,
            score = 1,
            author = "Renti",
            text = "As a hunter/warlock or any other class with a minion you can skip him pulling you up because if your pet has aggro then he gets pulled",
            date = "2016-03-17T15:31:34-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27162#comments:id=2314946",
        },
        {
            id = 2870692,
            score = 1,
            author = "Akushalah",
            text = "When watching the dialogue between Koltira and Thessarian, back away a bit. Because there's a good chance Gandling will respawn just at the end and force you to fight him again. Unless you want to fight him twice, give some room.",
            date = "2019-02-11T00:05:21-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27162#comments:id=2870692",
        },
    },
    [27163] = {
        {
            id = 1207177,
            score = 9,
            author = "470454",
            text = "I cant get thru the first archway after entering the building, Curse my Drenai's height, pretty sure theres something invisible blocking my way >:(",
            date = "2010-12-05T00:20:08-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27163#comments:id=1207177",
        },
        {
            id = 1209141,
            score = 9,
            author = "328410",
            text = "Must be part of the new phasing system. Very cool.\n\nThis is one of the 3 quests you get that take you deeper into the town. There are battles between NPCs (your faction) and the soon-to-be-routed Scourge mobs.\n\nYou should get all three of these quests together--Araj, Gandling, and Rattlegore.\n\nThis is important: if the faction NPCs are fighting the Scourge mob you can run past and not aggro them. If the mob is not in combat or kills the faction NPC while you are in proximity you will be targeted.\n\nRattlegore has about 2300 health. When you enter the house he will not immediately attack. You have a few seconds to cast defensive spells if you need to. Once you move another 3-4 steps inside he will begin to charge.\n\nBurn him down, fairly easy fight.",
            date = "2010-12-05T21:15:16-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27163#comments:id=1209141",
        },
        {
            id = 1198442,
            score = 6,
            author = "265027",
            text = "Can be found at 43.53,68.88 inside the building",
            date = "2010-11-30T17:23:09-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27163#comments:id=1198442",
        },
        {
            id = 1916070,
            score = 1,
            author = "ChubaChuba",
            text = "Seems like there is a bug, on the Argent Dawn realm at least, where Rattlegore isn't spawning.\nBlizz told me I hadn't progressed the quest far enough, but I've cleared all other quests in the area.\nWaiting on another response.",
            date = "2013-11-09T03:04:33-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27163#comments:id=1916070",
        },
    },
    [27164] = {
        {
            id = 1209137,
            score = 6,
            author = "328410",
            text = "This is one of the 3 quests you get that take you deeper into the town. There are battles between NPCs (your faction) and the soon-to-be-routed Scourge mobs.\n\nYou should get all three of these quests together--Araj, Gandling, and Rotface (or whatever his name is). You push into the town and fight through the mobs to the house where Rotface is.\n\nThis is important: if the faction NPCs are fighting the Scourge mob you can run past and not aggro them. If the mob is not in combat or kills the faction NPC while you are in proximity you will be targeted.\n\nWhen you fight Araj he/she will summon skeletons periodically. Be sure you still have the hand grenades and just blow up the skeletons. If you don't have the grenades you will be in for a hurtin'.\n\nAraj has about 2200 health, and besides the skeleton summons, uses a nasty Frostbolt, but that can be interrupted. Get into melee range and interrupt whenever your action is off cooldown.",
            date = "2010-12-05T21:10:31-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27164#comments:id=1209137",
        },
        {
            id = 1435042,
            score = 5,
            author = "762466",
            text = "It wasn't hard to defeat. Just pound away close-range, and use the handgrenade if the skeletons show up.\n\nHOWEVER... Don't hang around figuring out where you're going next. It's a quick respawn, and when the skeletons are summoned, you no longer have a grenade.",
            date = "2011-06-05T17:20:20-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27164#comments:id=1435042",
        },
        {
            id = 1647915,
            score = 5,
            author = "sorsa",
            text = "MoP beta: This seems currently bugged, I turned in the 15 scourge kill quest, the grenade quest and the opengut behemot kill quest, after which I went for Araji.. but he -never- spawns, waited 10 minutes. Must be a phasing bug.",
            date = "2012-04-02T13:35:38-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27164#comments:id=1647915",
        },
        {
            id = 1442454,
            score = 3,
            author = "FuryWar",
            text = "Just finished this quest with my 37 Rogue.  Snuck up behind Araj to Ambush.  When the fight started I did my best to interrupt his spellcasting, but when his first batch of Berserkers were summoned, I tossed a grenade, killing them all, and he had died at the same moment.  Wasn't near as tough as I was expecting!  (MUCH easier than the old-school quest to kill him back in Vanilla was!)",
            date = "2011-06-16T02:19:03-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27164#comments:id=1442454",
        },
        {
            id = 1767523,
            score = 1,
            author = "455621",
            text = "After you kill him, wait for 5-10 seconds for the phylactery to spawn. Quest says 'get the phylactery', not 'kill the lich', which I noticed when I return to the questgiver :)",
            date = "2012-11-25T05:33:43-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27164#comments:id=1767523",
        },
    },
