    [27170] = {
        {
            id = 1387585,
            score = 5,
            author = "StansDad",
            text = "Is there a prior quest which needs to be done to activate this one? A particular procedure? A bug? Because I tracked down High Priest Thel'danis only to find he has nothing to say to me! No \"!\" or anything!)",
