        },
        {
            id = 1318869,
            score = 4,
            author = "156138",
            text = "This is a a good quest and gives another sight into the new phasing in WoW. Getting to the crypt you come across no mobs. However as soon as you turn this quest in at the bottom of the crypt the mobs appear and you have to fight your way out (with the next quest) and when you get out of the crypt there are lots of them around this area. Not hard Q though.",
            date = "2011-02-02T02:17:46-06:00",
