    [27171] = {
        {
            id = 1209188,
            score = 7,
            author = "328410",
            text = "Interesting twist on the old theme, \"fight your way to the bottom of the crypt, get the treasure, and fight your way out again because everything respawned\".\n\nYou run in unopposed. When you grab the \"?\" box, complete the quest, you get the \"!\" for this quest. As soon as you accept it mobs appear. Two in the basement with you at roughly 10:00 and 2:00, both out of aggro range. You can take them one at a time. From there, fight your way out, and there are more on the ground outside the crypt.\n\nNice revamp of an old, bad quest mechanic.",
            date = "2010-12-05T21:49:20-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27171#comments:id=1209188",
        },
        {
            id = 1932240,
            score = 6,
            author = "Gaminghadou",
            text = "The phased area of this quest is the only (because the skeletons are only in the phase) where you can farm this recipe https://www.wowhead.com/item=9296 and its only Alliance so if you see this on AH, Buy it  because the drop chance are very low even if you do the quest with 11 characters\n\nSry for my bad english",
            date = "2014-01-06T13:04:47-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27171#comments:id=1932240",
        },
        {
            id = 1339546,
