    [27181] = {
        {
            id = 1319139,
            score = 21,
            author = "152049",
            text = "This is the first, and possibly only, quest I've ever seen where the mobs have a red exclamation mark over their heads.  When you kill one, you are offered a quest to kill 9 more of them.  It was sureal to see it, and a google search shows that noone is talking about it.  I think it's quite a cool feature and hope to see more of it in the future.\n\nAlso, the quest \"Honor the Dead\" is listed as a prerequisite.  It may be the case that you need to have accepted \"Honor the Dead\", but I can confirm that you need not complete it before accepting \"Excising the Taint\".",
            date = "2011-02-02T08:42:54-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27181#comments:id=1319139",
