    [27188] = {
        {
            id = 1189236,
            score = 14,
            author = "11173",
            text = "As with the old version of this quest, make sure you (not your pet, party member etc.) get the killing blow on the zombies/ghosts to get the information from them.",
            date = "2010-11-27T00:50:24-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27188#comments:id=1189236",
        },
        {
            id = 1320940,
            score = 5,
            author = "545027",
            text = "As a demonology warlock, these quests are extremely hard. Not because the mobs are hard to kill, infact they go down quite easy, but because we rely on our pets so much the pet will often score the KB and we wont get credit, same on the frogs.\nMy advice is to put pet to passive and just take it slow and steady.",
            date = "2011-02-03T22:14:16-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27188#comments:id=1320940",
        },
        {
            id = 1673078,
            score = 5,
            author = "922032",
            text = "For any demonology warlock looking to do this in MoP, things just got even more difficult due to Wild Imps. This may change later on, but for now the imps seemingly do not go onto passive but stay on defensive. Since Incinerate is now destro only, you will have to find a way of killing the risen mobs without using your SB so that you don't end up summoning any imps (trust me, 5+ imps makes getting the killing blow nigh impossible). I used Soul Fire instead. Irritating as hell, but not game breaking.",
            date = "2012-06-03T12:28:22-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27188#comments:id=1673078",
        },
        {
            id = 1703647,
            score = 5,
            author = "276651",
            text = "The Restless Apparitions (http://www.wowhead.com/npc=23861) spawned during this quest will say things like:\n\n\"Go away, whoever you are! Witch Hill is mine... mine!\"\n\"It was... terrible... the demon...\"\n\"The darkness... the corruption... they came too quickly for anyone to know...\"\n\"The manor... someone else... will soon be consumed...\"\n\"The darkness will consume all... all the living...\"\n\"It is too late for Jarl... its hold is too strong...\"\n\"It is too late for us, living one. Take yourself and your friend away from here before you both are... claimed...\"\n\"Why have you come here, outsider? You will only find pain! Our fate will be yours...\"",
            date = "2012-08-24T00:46:13-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27188#comments:id=1703647",
        },
        {
            id = 1302052,
            score = 2,
            author = "648382",
            text = "Note that the tool tip when targeting one of these \"ghosts and corpses shambling\" doesn't mention the quest. At least, it didn't with me. Tool tips of the frogs needed for Marsh Frog Legs (http://www.wowhead.com/quest=27183), which conveniently can be done at the same time, were fine.",
            date = "2011-01-20T16:35:01-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27188#comments:id=1302052",
        },
    },
