    [27190] = {
        {
            id = 1194238,
            score = 74,
            author = "239542",
            text = "You can't summon Zelfrax while Mordant and Jarl are in the middle of their little \"I brought you a housewarming gift, Jarl\"-event. So wait for them to be done with their talking before using the Witchbane Torch or you'll have to wait for the cooldown.",
            date = "2010-11-28T19:09:00-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27190#comments:id=1194238",
        },
        {
            id = 1703663,
            score = 5,
            author = "276651",
            text = "When you place the torch, Zelfrax yells:\n\"This land was mine long before your wretched kind set foot here.\nAll who venture here belong to me, including you!\"",
            date = "2012-08-24T01:15:28-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27190#comments:id=1703663",
        },
        {
            id = 2270873,
            score = 4,
            author = "PrettyInPink",
            text = "This quest was glitched for me today as a level 100, as well as for the level 35-40 players I saw try to complete it. Once https://www.wowhead.com/item=33113 was used at the end of the dock, Zelfrax (http://www.wowhead.com/npc=23864/zelfrax) wouldn't yell or move. I tried abandoning the quest and picking it back up and I also waited until the NPCs were done talking, and nothing worked. I submitted a bug report, but skipped the quest, and was still able to get Dustwallow Marsh Quests (http://www.wowhead.com/achievement=4978/dustwallow-marsh-quests) without it.",
            date = "2015-11-01T20:27:03-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27190#comments:id=2270873",
        },
        {
            id = 6133816,
