    [27191] = {
        {
            id = 1631589,
            score = 30,
            author = "805063",
            text = "In order to open this quest, you must complete the two quests https://www.wowhead.com/quest=27183 and https://www.wowhead.com/quest=27184.  He gives them one at a time. and upon completing Jarl Needs Eyes, this one opens up.",
            date = "2012-02-25T13:37:45-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27191#comments:id=1631589",
        },
        {
            id = 1202071,
            score = 26,
            author = "109740",
            text = "Not all murlocs have a head. No, really.",
            date = "2010-12-02T12:16:00-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27191#comments:id=1202071",
        },
        {
            id = 1466204,
            score = 23,
            author = "Carnagefiend",
            text = "To quote the questgiver:\n\n\"Don't crush those heads now. It makes them sad. Sad heads aren't good eating.\"\n\nWhen you don't get a head for loot, your character effectively destroyed it. There are several ways to imagine how your particular character did it, so be creative ;)",
            date = "2011-07-10T10:24:33-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27191#comments:id=1466204",
        },
        {
            id = 1807861,
            score = 3,
            author = "Species3259",
            text = "I am not sure since when but the drop rate on the heads have considerably increased.\n\nMust have done this quest on numerous alts and always 'cursed' the drop rate. Usually you had to purge the little peninsula twice and then some to complete the quest.\n\nBut not anymore!\n\nOnly had to kill 10 Mirefin (mix of Coastrunners/Murlocs) to get all the 8 heads.",
            date = "2013-02-01T19:27:50-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27191#comments:id=1807861",
        },
        {
            id = 1203860,
            score = 1,
            author = "Thortok2000",
            text = "This quest replaces the previous version of this quest which offered the best quest reward ever (http://www.wowhead.com/quest=1177#comments:id=708968).  Now the quest reward isn't nearly as good.",
            date = "2010-12-03T09:51:06-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27191#comments:id=1203860",
        },
    },
    [27192] = {
