    [27193] = {
        {
            id = 1180279,
            score = 28,
            author = "Starfury",
            text = "The log book drops from Caretaker Smithers.  He is in the barn, up on top of the entryway.",
            date = "2010-11-24T04:51:25-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27193#comments:id=1180279",
        },
        {
            id = 1194342,
            score = 20,
            author = "593557",
            text = "If you run into the farmhouse scouring the floor for the logbook in vain like I did, look up. The guy that drops it is above the entrance, so run to the back of the farmhouse and you'll see him. Of course, if you're not doing this at 80 like I am then you will probably aggro him and not have this problem :/",
            date = "2010-11-28T20:09:12-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27193#comments:id=1194342",
        },
        {
            id = 1384112,
            score = 17,
            author = "508963",
            text = "if u r lvl 85 like me just stand under him and jump up and down without having target on him then ull get aggro and he will jump down and u kan kill him after he landed ! if u kill him on the shelf or in mid air he cant be looted !",
            date = "2011-04-04T16:30:43-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27193#comments:id=1384112",
        },
        {
            id = 1766871,
            score = 9,
            author = "jjanchan",
            text = "The quest text says to search the farmhouses, but in fact https://www.wowhead.com/npc=45219 is in the barn/stable at (45,54).\nAs a high level character completing this quest, here are some tips (some of them apply to low levels too!):\n- https://www.wowhead.com/npc=45219 is standing on a beam near the roof, so you will miss him unless you look up.  He drops the quest item (namely, https://www.wowhead.com/item=60867) once killed.\n- I would highly advise not attacking him (as a high level character) with any ability/spell as there is the potential to one shot him and not being able to reach him and loot him.\n- The caveat to the above point is if you are an engineer and possess a https://www.wowhead.com/item=60854 - in that case it doesn't matter that he is out of range!\n- If you are a priest, levitate should bring you into range of his corpse.\n- Some classes can go to the target (e.g. Rogues with https://www.wowhead.com/spell=36554) or bring the target to them (e.g. Death Knights with https://www.wowhead.com/spell=49576)\n-  A non-engineer can jump at the bottom of the wall he is standing on to aggro him and cause him to come down.\n- Alternatively, any ranged/AoE attack that does no damage (e.g. debuffs the target, interrupts) can aggro him down so you can kill him.  Some examples include https://www.wowhead.com/spell=57994 and https://www.wowhead.com/spell=2139\n- If you kill him out of range, and are not an engineer or a priest, you can jump on the barrel up against the wall, and then on to the shelf on the wall, and will be within range to loot.\n- Another alternative is to pull another mob from outside, into the room and kill it.  AoE looting will allow you to access the loot table for https://www.wowhead.com/npc=45219.",
            date = "2012-11-23T15:54:34-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27193#comments:id=1766871",
        },
        {
            id = 1211379,
            score = 8,
            author = "413791",
            text = "I like the way Blizzard did this!\n\nYou go into the farmhouse...round the bend of the entryway...and look into an empty room.\n\nSuddenly from above you (and most likely BEHIND you) this huge Worgen (Caretaker Smithers) jumps down on you and attacks!\n\nYes...it startled me too!  LOL\n\nHe is also holding a lantern that breaks when he swings it at you...and this sets the inside of the farmhouse on fire (more for effect...you won't burn).\n\nUpon killing him...you get his logbook.\n\nNice!",
            date = "2010-12-07T05:50:01-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27193#comments:id=1211379",
        },
    },
    [27194] = {
        {
            id = 1922292,
            score = 9,
            author = "Shashos",
            text = "This quest seems to have become quite buggy since about April 2013 or somewhere about then.\n\nMaster Forteski is not spawning in on some servers thus the quest cannot be completed and this blocks questing through basically the rest of the zone's quests. Big problem for those trying to level an alt through Silverpine.\n\nHaven't seen any method of fixing the quest, so most likely it requires a server restart, ie maintenance.",
            date = "2013-11-30T02:01:42-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27194#comments:id=1922292",
        },
        {
            id = 1944527,
            score = 4,
            author = "BlizzardCS",
            text = "UPDATE 28/10/2014: We didn't get any further report, so it seems like the issue is indeed totally fixed. Thanks all for your patience and understanding while we were working on it.\n\nUPDATE 14/10/2014: This issue should be fixed by now. Please, if you are still experiencing this issue let us know so we can look into it. :)\n\nHello there!\nJust wanted to let you know that there’s a known issue at the moment affecting couple of quests: https://www.wowhead.com/quest=27194 and https://www.wowhead.com/quest=27195. In some occasions it’s not possible to interact with the NPC https://www.wowhead.com/npc=45228, so it can be that he doesn’t offer quests to you, or that you don’t even see him. We are already investigating this issue and hope to find a solution as soon as possible. However, this issue is not always present. If you find that you can’t interact with https://www.wowhead.com/npc=45228 and can’t continue levelling your character because of this, please contact our Game Masters. They might be able to help you in some cases. :)",
            date = "2014-02-18T11:17:20-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27194#comments:id=1944527",
        },
        {
            id = 1357370,
            score = 3,
            author = "777074",
            text = "Just did this quest and those of you who are being confused by the Carbonite addon, the map above shows the correct position of the quest end, as opposed to turning in to Lady Sylvanas like Carbonite suggests.",
            date = "2011-03-04T13:16:08-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27194#comments:id=1357370",
        },
        {
            id = 1497043,
            score = 2,
            author = "479454",
            text = "For those of you with coordinates, Master Forteski  is at 55.9, 46.4 : Deep Elem Mine. That's where you have to turn this quest in.",
            date = "2011-08-17T12:25:09-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27194#comments:id=1497043",
        },
    },
    [27195] = {
        {
            id = 1202457,
            score = 38,
            author = "712199",
            text = "\"Remember this day as the day Forteski saved your hide.\"\n\n\"You will always remember this day as the day that you almost caught Captain Jack Sparrow\"",
            date = "2010-12-02T15:30:30-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27195#comments:id=1202457",
        },
        {
            id = 1185601,
            score = 26,
            author = "Vsin",
            text = "IT'S A TRAP!\n\n...should that get spoiler tagged?",
            date = "2010-11-25T18:02:59-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27195#comments:id=1185601",
        },
        {
            id = 1188615,
            score = 17,
            author = "67034",
            text = "\"Remember this day as the day Forteski saved your hide.\"\nNo, because I was already running and well outside the blast radius before the worgen guy even spawned. It yanks you back in so he can 'save you' anyway, unfortunately.",
            date = "2010-11-26T19:11:59-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27195#comments:id=1188615",
        },
        {
            id = 1562288,
            score = 17,
            author = "126815",
            text = "So many lives could have been saved if only Admiral Ackbar were with them..",
            date = "2011-11-03T21:17:55-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27195#comments:id=1562288",
        },
        {
            id = 1944534,
            score = 11,
            author = "BlizzardCS",
            text = "UPDATE 28/10/2014: We didn't get any further report, so it seems like the issue is indeed totally fixed. Thanks all for your patience and understanding while we were working on it.\n\nUPDATE 14/10/2014: This issue should be fixed by now. Please, if you are still experiencing this issue let us know so we can look into it. :)\n\nHello there!\nJust wanted to let you know that there’s a known issue at the moment affecting couple of quests: https://www.wowhead.com/quest=27194 and https://www.wowhead.com/quest=27195. In some occasions it’s not possible to interact with the NPC https://www.wowhead.com/npc=45228, so it can be that he doesn’t offer quests to you, or that you don’t even see him. We are already investigating this issue and hope to find a solution as soon as possible. However, this issue is not always present. If you find that you can’t interact with https://www.wowhead.com/npc=45228 and can’t continue levelling your character because of this, please contact our Game Masters. They might be able to help you in some cases. :)",
            date = "2014-02-18T11:19:36-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27195#comments:id=1944534",
        },
    },
    [27197] = {
        {
            id = 1191640,
            score = 3,
            author = "228309",
            text = "Leads to Ashes to Ashes (http://www.wowhead.com/quest=27199#see-also)",
            date = "2010-11-27T21:23:10-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27197#comments:id=1191640",
        },
        {
            id = 1199460,
            score = 2,
            author = "Smaragd",
            text = "Indirect follow-up of the Uther's Blessing (http://www.wowhead.com/quest=27169) chain, ending with Combat Training (http://www.wowhead.com/quest=27174). Further opens up more quests in the battle for Andorhal, resulting in a blue item of choice from Alas, Andorhal (http://www.wowhead.com/quest=27206).",
            date = "2010-12-01T04:48:37-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27197#comments:id=1199460",
        },
        {
            id = 1921940,
            score = 1,
            author = "Rynd",
            text = "Been trying to complete this quest but it won't let me. I've logged out/in, dropped the quest and even did a /reload but it's not letting me. Has anyone else had a problem with it?",
            date = "2013-11-28T13:00:54-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27197#comments:id=1921940",
        },
    },
    [27198] = {
        {
            id = 1378809,
            score = 59,
            author = "Trolled",
            text = "Judging by the Captain to Deathguard ratio, Andorhal might be a bit too generous on the promotions.",
            date = "2011-03-29T00:13:40-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27198#comments:id=1378809",
        },
        {
            id = 1602511,
            score = 45,
            author = "614435",
            text = "The prerequisites for this quest involve a few quest chains.\n\n1. In Andorhal, start with Scourge First... Horde Later (http://www.wowhead.com/quest=27159) and The Endless Flow (http://www.wowhead.com/quest=27161) (you can optionally be lead into these quests via the Hero's Call (http://www.wowhead.com/quest=28576), a quest and gryphon ride in the Hinterlands (http://www.wowhead.com/quest=28505), a quest and teleportation in Booty Bay (http://www.wowhead.com/quest=28749), or just down the road at Chillwind Camp (http://www.wowhead.com/quest=27158)).\n2. Follow up with Scholomancer (http://www.wowhead.com/quest=27162), Brute Strength (http://www.wowhead.com/quest=27163), and Araj the Summoner (http://www.wowhead.com/quest=27164).\n3. Victory, For Now (http://www.wowhead.com/quest=27165) ends round 1 in Andorhal and leads you to Chillwind Camp.\n4. A Mighty Hunger (http://www.wowhead.com/quest=27167) and Go Fletch! (http://www.wowhead.com/quest=27166) are offered at Chillwind Camp (these are available without prerequisites and may be completed at any time prior to the next step).\n5. Next comes a quest chain: Uther's Blessing (http://www.wowhead.com/quest=27169); The Abandoned Crypt (http://www.wowhead.com/quest=27170); Ambushed! (http://www.wowhead.com/quest=27171); The Writhing Haunt (http://www.wowhead.com/quest=27172); This is Our Army (http://www.wowhead.com/quest=27173); Combat Training (http://www.wowhead.com/quest=27174).\n6. Optionally, you can pick up the quest The Menders' Stead (http://www.wowhead.com/quest=27175) in Chillwind Camp from Argent Officer Pureheart (http://www.wowhead.com/npc=10840) which leads to the Mender's Stead.\n7. The quest to return to Andorhal for round 2 is found in the Menders' Stead.  Durnt Brightfalcon (http://www.wowhead.com/npc=45012) gives you the quest The Battle Resumes! (http://www.wowhead.com/quest=27197)  You may need to gain a level or two before it becomes available.\n8. Supporting the Troops (http://www.wowhead.com/quest=27198) as well as Ashes to Ashes (http://www.wowhead.com/quest=27199) should now be available in Andorhal.\n\nI hope this helps any of you wondering about prerequisites.",
            date = "2011-12-27T02:19:49-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27198#comments:id=1602511",
        },
        {
            id = 1377289,
            score = 30,
            author = "269035",
            text = "Not sure if anyone else has encountered this, but I found the Deathguards to be completely phased out while I was in Andorhal and this quest was available. I could spot a few on the outskirts while I wasn't in the area limits, but as soon as I approached them, they vanished.\n\nI could do the sister quest, https://www.wowhead.com/quest=27199 with no issues.\n\nEdit: It seems that some adds do appear in the Andorhal area, but they are either on a very long respawn time, or fade in and out seemingly randomly. I finally finished the quest, took me about 35 minutes to get them all though.\n\nEdit: As of 4.2, reports say this is now working normally.",
            date = "2011-03-27T07:00:15-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27198#comments:id=1377289",
        },
        {
            id = 1197821,
            score = 17,
            author = "vsavatar",
            text = "Don't get near the bat handler in the horde camp.  She will attack from a huge distance without any provocation and will send her level ? bats to utterly destroy you in one shot.",
            date = "2010-11-30T12:43:19-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27198#comments:id=1197821",
        },
        {
            id = 1412428,
            score = 8,
            author = "blizzarius",
            text = "i found the bug. it makes the Deathguards phase out when your in Andorhal. i found eight spawn points, but only two of them are workable. the first one is at 48.0, 71.1, but you have to stand on the bridge where your mini-map says Sorrow Hill. the second one is at 41.4, 65.2, but you need to stand where your mini-map says Western Plaguelands. i'm playing a priest, so using an instant damage spell like Shadow Word: Pain and Devouring Plague make it so the Deathguard won't phase out and after you kill it, some of them are allowed to be looted. i hope this helps anyone who is having trouble with this quest.",
            date = "2011-05-07T18:14:34-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27198#comments:id=1412428",
        },
    },
    [27199] = {
        {
            id = 1199274,
            score = 5,
            author = "80976",
            text = "Though there's some War-Captains in and around the Forsaken base, avoid them because the horde flight master nearby WILL one-hit kill you, and has a large aggro range for players of this level.",
            date = "2010-12-01T02:42:51-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27199#comments:id=1199274",
        },
        {
            id = 1191643,
            score = 4,
            author = "228309",
            text = "Next in the Andorhal line is The Depravity of the Forsaken. (http://www.wowhead.com/quest=27205)",
            date = "2010-11-27T21:25:18-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27199#comments:id=1191643",
        },
        {
            id = 1603494,
            score = 3,
            author = "Jayhawk",
            text = "Even though Thassarian says \"they do not fight\" they will attack you when you're attacking one their own. I was attacked by a moving War-Captain, as I was attacking a standing one.",
            date = "2011-12-29T06:11:58-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27199#comments:id=1603494",
        },
        {
            id = 1539870,
            score = 2,
            author = "Engrelled",
            text = "@Thalassicus: and the Enraged Fel Bats will also one-shot you.\nThe moving War-Captains are still around, but there are now stationary War-Captains, not only in the Forsaken base, but also down where the Deathguards are fighting - much easier.",
            date = "2011-10-10T17:00:06-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27199#comments:id=1539870",
        },
    },
    [27201] = {
        {
            id = 1202659,
            score = 4,
            author = "46662",
            text = "These guys are not too hard for this level, although you may need a ranged attack to pull some of them.\n\nSince you'll likely be doing Brother Against Brother (http://www.wowhead.com/quest=27202) at the same time, you'll have several farmers/militia with you, complete with a pet bar with which to control them. If you leave them on defensive, they'll attack whatever you attack. Otherwise, pick a target and hit Ctrl-1 to get them to attack.",
            date = "2010-12-02T17:26:31-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27201#comments:id=1202659",
        },
        {
            id = 1204786,
            score = 1,
            author = "653998",
            text = "It's quests like this that make me wonder why the forsaken were allowed to join the horde",
            date = "2010-12-03T18:36:44-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27201#comments:id=1204786",
        },
        {
            id = 2587070,
            score = 1,
            author = "neurocase",
            text = "\"To think that Sylvanas is stooping to such levels for the sake of the Forsaken...\"\n\nHey, Thassarian, coming to you with an update nearly eight years on...\n\nYou ain't seen nothin' yet, brother.",
            date = "2018-08-01T23:31:01-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27201#comments:id=2587070",
        },
    },
    [27202] = {
        {
            id = 2184791,
            score = 8,
            author = "Faelda",
            text = "So, technically there isn't a lead in to this quest, but since this is a heavily phased zone you have to do quite a bit before this guy will appear. And he actually gives you the quest in Andorhal, not The Writhing Haunt.\n\nStart in Chillwind Camp and do all the quests you can there. Go to Andorhal and do all the quests you can there. You will be sent back to Chillwind Camp. Keep questing until you get one to go to The Writhing Haunt. Go there and do the quests. Next, go to Mender's Stead and pick up The Battle Resumes from the dwarf there (You can skip the rest of the Mender's Stead quests). This will take you back to Andorhal. Do a few more quests and Thurman Grant will finally appear with this quest. It's quite a bit more work than it seems like on this page, but you can get there.",
            date = "2015-05-19T12:26:30-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27202#comments:id=2184791",
        },
        {
            id = 1202666,
            score = 3,
            author = "46662",
            text = "You get several farmers/militia to help you. They come complete with a pet bar. Leave them on defensive and they'll attack whatever you attack. Otherwise, pick a target and hit Ctrl-1 to get them to attack.\n\nThe target mobs are in packs of four. Easiest way to take them down is to focus fire: pick one, send you \"pets\" in and attack it yourself. They'll go down pretty quickly this way, but watch your health; the other three will be doing decent damage at the same time. The militia didn't seem able to tank. When I sent them after one mob, the other three in the pack seemed to automatically aggro on me.\n\nYou'll likely be doing Val'kyr Incursion (http://www.wowhead.com/quest=27201) at the same time. Your militia can help with that one as well.",
            date = "2010-12-02T17:31:38-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27202#comments:id=1202666",
        },
        {
            id = 1506454,
            score = 2,
            author = "bbbrasil",
            text = "Good for farming silk cloth. The 4-mob groups respawn decently. Just don't finish the quest until you have your bags full!",
            date = "2011-08-30T03:35:23-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27202#comments:id=1506454",
        },
        {
            id = 2075291,
            score = 2,
            author = "Ninosai",
            text = "So, I was doing this quest for the bracers to complete my Discovery armor transmog and I was at a loss trying to find Thurman Grant at the Writhing Haunt as the map clearly indicates he is but I couldn't see him.\n\nI decided (after realizing the other options for the bracers required massive quest chains) to clear the quests in Andorhal just to try and because some comments were un-clearly referencing Val'kyr Incursion (http://www.wowhead.com/quest=27201) and sure enough Thurman Grant showed up right there and the farmers spawned automatically.\n\nHis coordinates are 39.8 69.7",
            date = "2014-12-23T22:55:30-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27202#comments:id=2075291",
        },
        {
            id = 1684403,
            score = 1,
            author = "LazyFansu",
            text = "Weird glitch on this one: if you aggro a group of the mobs and drag them back to the farmers where you picked up the quest, the ones lying down will remain lying down as they slide over to the mobs and start attacking them! Pointless yet amusing glitch.",
            date = "2012-07-04T11:52:40-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27202#comments:id=1684403",
        },
    },
    [27204] = {
        {
            id = 1370231,
            score = 7,
            author = "721249",
            text = "Yup, you'd think a 40-elite would be more trouble, but those farm boys with the pitchforks are enough to do the trick.\n\nLevel 40 worgen affliction warlock -- no problem.",
            date = "2011-03-18T16:46:19-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27204#comments:id=1370231",
        },
        {
            id = 1202671,
            score = 3,
            author = "46662",
            text = "In pre-4.0 WoW, this would've been a group quest. Instead, you get several militia just like with the previous quest. Aradne has 8000+ health, but I did this as a level 38 druid in cat form, and she didn't seem to be doing too much damage to me. Didn't have to heal, just did my dps rotation while my militia attacked and she went down pretty reasonably. Just took a bit longer than the other mobs in this area.",
            date = "2010-12-02T17:36:01-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27204#comments:id=1202671",
        },
        {
            id = 1937733,
            score = 3,
            author = "1211829",
            text = "a prerequisite for this quest in the chain seems to be \"brother against brother\"",
            date = "2014-01-25T10:55:17-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27204#comments:id=1937733",
        },
        {
            id = 2619499,
            score = 3,
            author = "Akushalah",
            text = "My minutemen ran back down the tower, and I fought her alone. Definitely would've lost if I wasn't a guardian druid. Healed like four times, and it took FOREVER to kill her though. So BEWARE you might lose your army.",
            date = "2018-09-27T23:52:20-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27204#comments:id=2619499",
        },
        {
            id = 1406982,
            score = 1,
            author = "812974",
            text = "She never even reached me as a Worgen hunter lvl 40.\n\nSomething about having a trap, slow and 5 pets made me feel rather OP.",
            date = "2011-05-02T05:33:41-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27204#comments:id=1406982",
        },
    },
    [27205] = {
        {
            id = 1626987,
            score = 41,
            author = "Yinxy",
            text = "Before I was able to pick up this quest I had to finish the following quests first:\n\nFollow ups:\nhttps://www.wowhead.com/quest=27169\nhttps://www.wowhead.com/quest=27170\nhttps://www.wowhead.com/quest=27171\nhttps://www.wowhead.com/quest=27172\nhttps://www.wowhead.com/quest=27173\nhttps://www.wowhead.com/quest=27174\n\nAt that points your able to pick up https://www.wowhead.com/quest=27197.\nWhen handing in at Thassarian you can pick up https://www.wowhead.com/quest=27199 & https://www.wowhead.com/quest=27198\nWhen handing these in, you can pick up this quest https://www.wowhead.com/quest=27205",
            date = "2012-02-15T11:03:16-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27205#comments:id=1626987",
        },
        {
            id = 1353150,
            score = 14,
            author = "bluechipps",
            text = "I first had to complete both Supporting the Troops (http://www.wowhead.com/quest=27198) and Ashes to Ashes (http://www.wowhead.com/quest=27199) (alliance) for this quest line to show up.",
            date = "2011-02-28T12:44:41-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27205#comments:id=1353150",
        },
        {
            id = 1197743,
            score = 10,
            author = "714133",
            text = "If you were stuck at 37/45 quests, with Uther's Blessing unable to complete in early 4.0.3a, it's working now, as of Nov 30th.  Turn that it, follow the chain, make a visit to Mender's Stead when it runs out, and pick up the rest of the chain that leads back to this.",
            date = "2010-11-30T12:01:26-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27205#comments:id=1197743",
        },
        {
            id = 1191915,
            score = 3,
            author = "Ssateneth",
            text = "How do you get this questline to open? I went to talk to Thassarian but he doesn't give this quest.",
            date = "2010-11-27T23:56:51-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27205#comments:id=1191915",
        },
        {
            id = 1408298,
            score = 3,
            author = "Dragonrose",
            text = "To open up this quest, you have to complete both Supporting the Troops (www.wowhead.com/quest=27198) and Ashes to Ashes (www.wowhead.com/quest=27199). Of course, with Supporting the Troops (www.wowhead.com/quest=27198) phasing out the mobs needed for some people, that's gonna take a while.",
            date = "2011-05-03T10:34:46-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27205#comments:id=1408298",
        },
    },
    [27206] = {
        {
            id = 5349150,
            score = 99,
            author = "Enatheldra",
            text = "For me, this quest was bugged. When I was trying to turn it in, I realized that everything was missing. All NPCs, mobs and even resource deposits (herbs, ore, fish) outside of Andorhal were gone. Even when I left Western Plaguelands, there was still nothing.\n\nI solved the issue by going to Stormwind (the gryphon master in Andorhal was still there) and while 90% of the NPCs and all of the portals inside the Mage Tower were missing, the portal to Darnassus at the Harbor was still there. Took it, took the portal back and everything was back in place. Took the gryphon to Chillwind Camp and voilà: I could turn in the quest. Maybe closing the game and turning it back on would've worked as well, but I only tried reloading, which did nothing.",
            date = "2022-03-31T02:37:40-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27206#comments:id=5349150",
        },
        {
            id = 1313061,
            score = 65,
            author = "Avish",
            text = "You know it's bad when my Horde for Life ass is rooting for Thassarian. I would much rather have lost the town than have what happened to Koltira, happen to Koltira. I even knew the outcome before starting on the quest, but it was so much worse watching the cut scene. I've always preferred the Kalimdor Horde, but now I'm getting to where I hate The Forsaken. I swear, if the Alliance on my server attacks UC, I am going to zip over as fast as I can...so I can stand there and cheer them on.",
            date = "2011-01-28T09:31:38-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27206#comments:id=1313061",
        },
        {
            id = 1259049,
            score = 50,
            author = "Carnane",
            text = "The quest title is a reference to the original quest to kill Araj, pre-Cataclysm.\n\nOn a side note, I was surprised by the effectiveness of Blizzard's storytelling with this zone.  It was short, to be honest, but it REALLY showed how evil the Forsaken are becoming.",
            date = "2010-12-25T23:37:54-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27206#comments:id=1259049",
        },
        {
            id = 1191928,
            score = 45,
            author = "186733",
            text = "Completing this quest phases out the flight path for alliance. Its not really vital but if you want it don't hand it in.",
            date = "2010-11-28T00:05:22-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27206#comments:id=1191928",
        },
        {
            id = 1264336,
            score = 36,
            author = "Aletto",
            text = "I don't know if this changes after level 40, but after leveling both an Alliance and Horde character after the Shattering, the Alliance is getting absolutely destroyed.\n\nThe only place they've made any headway is Southern Barrens, it seems.\n\nI think Vanilla WoW handled conflict rather well - both factions fought, but the endings to the battles were inconclusive. If you were Alliance, the quests made it seem like Alliance won. If you were Horde, the quests made it seem like the Horde won.\n\nBut in Cata they seem to have taken out all uncertainty. Now, when there's a battle between the Alliance and Horde, there are two possible outcomes - a draw, or the Horde wins. :(",
            date = "2010-12-28T15:29:19-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27206#comments:id=1264336",
        },
    },
    [27208] = {
        {
            id = 1980638,
            score = 5,
            author = "sitecow09",
            text = "Dawnbringer's words after the quest is complete finally confirm what many long suspected: Dreadlords are immortal. When they die, they just respawn later in the nether. Ergo, the next time the Burning Legion launches another invasion, we can count on seeing Balnazzar, Detheroc, and Varinmathras, along with the other dreadlords back in full form unless we find a way to finish them for good.\n\nEDIT: An update from Legion. Demons can only reform in Antorus the Burning Throne on Argus, unless they are killed either in the Twisting Nether or in a place highly saturated with fel energy (like Argus itself).",
            date = "2014-07-14T16:56:11-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27208#comments:id=1980638",
        },
    },
    [27210] = {
        {
            id = 5207222,
            score = 20,
            author = "KaneTheBoom",
            text = "sus",
            date = "2021-06-30T00:08:41-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27210#comments:id=5207222",
        },
        {
            id = 1692029,
            score = 9,
            author = "anubalabeloralon",
            text = "And it ends up these \"traitors\" are right...\nGood thing is we didnt kill them all.",
            date = "2012-07-25T10:40:31-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27210#comments:id=1692029",
        },
        {
            id = 1198231,
            score = 5,
            author = "rmp135",
            text = "Yea, these can flag you for PvP. I found that if you're a rogue and you stealth up after clicking the dialogue button they won't attack you but you still get the credit.",
            date = "2010-11-30T15:42:25-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27210#comments:id=1198231",
        },
        {
            id = 1293273,
            score = 4,
            author = "thebadmf",
            text = "Just completed this quest (priest), and it no longer flags you at any point.",
            date = "2011-01-14T09:19:12-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27210#comments:id=1293273",
        },
        {
            id = 1433458,
            score = 3,
            author = "299678",
            text = "\"These people will know Admiral Proudmoore for the true hero he was\"\n\n\"You can't stop us from exposing the truth about Jaina's cowardice\"\n\n\"It's people like you who weaken the Alliance and invite the Horde to take away all we've fought for\"\n\nI've done this quest on many characters over many years, and I completely agree with the Agitators. That Thrall-loving @#$% Jaina needs to be deposed, the men-at-arms of Theramore turned to valiant deeds against the animals of Orgrimmar, and this pretense of peace with the green-skins done away with once and for all.\n\nEvery time I do this quest, I die a little inside. These guys are the only ones in the Alliance who have it right. I hate that I have to work against them.",
            date = "2011-06-03T14:29:00-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27210#comments:id=1433458",
        },
    },
