    [27220] = {
        {
            id = 1290844,
            score = 261,
            author = "70130",
            text = "You need to put the paste on before entering Tidefury Cove, or the shark will not trigger properly.\n\nIf you put the paste on in the Cove, swim back to Nat's Landing and then back into the Cove. This should trigger the shark.",
            date = "2011-01-12T15:40:06-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27220#comments:id=1290844",
        },
        {
            id = 1442372,
            score = 33,
            author = "Palahniuk",
            text = "After rubbing the bait on yourself, swim into the cove BEHIND Nat. BEHIND HIM!",
            date = "2011-06-15T22:18:32-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27220#comments:id=1442372",
        },
        {
            id = 1446147,
            score = 30,
            author = "DuskVictoria",
            text = "I just did this quest just moment ago,  I swam to the deepest part of the water in Cove, smeared myself in that stuff... waited... and waited.. for 30 minutes... so I came on here and looked what I need to do exactly.\n\nI'm going to say that you gonna smear yourself BEFORE you leaving Nat's Landing, swim behind Nat [heading west on the map (or rather, go left on the map)], do not go forward from him; just head to where shark should be at. I did this and he swam right at me, so you gonna put it on before you go in water, and it'll work rather than sitting around wait for it to come to you.\n\nThe Shark is only level 37 non-elite, it's easy to solo and all.",
            date = "2011-06-21T00:58:49-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27220#comments:id=1446147",
        },
        {
            id = 2795507,
            score = 25,
            author = "mckenzie2k1",
            text = "Be aware that if you swim to the quest region, THEN apply the paste, you'll have a difficult time spawning the shark.  The easiest way to complete this is to add the paste while standing next to Nat, then simply walk toward the quest area, swimming along the sea floor.  It shouldn't take long for the shark to appear and attack.",
            date = "2018-11-03T09:54:19-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27220#comments:id=2795507",
        },
        {
            id = 1699680,
            score = 17,
            author = "203685",
            text = "If done correctly the shark will sit at the bottom of the sea at 56, 63.5.\n\nJust remember to have the paste buff on you before swimming into the Tidefury Cove so that you trigger the shark to spawn.",
            date = "2012-08-14T01:28:01-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27220#comments:id=1699680",
        },
    },
    [27221] = {
        {
            id = 1991983,
            score = 1,
            author = "1186699",
            text = "Is completion of this quest line necessary for anything down the line with fishing?  That is, is it required for any achievements, reputation or rewards other than the ones from the quests themselves?   From my reading about Nat Pagle's friendship and Extreme Angler, I don't see that it is...",
            date = "2014-08-15T12:44:13-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27221#comments:id=1991983",
