    [27222] = {
        {
            id = 2458569,
            score = 53,
            author = "whimsy82",
            text = "If you fail this quest, abandon it, leave Theramore and come back. Major Mills will be waiting on the docks by the cannons offering the quest again.",
            date = "2017-01-02T16:36:17-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27222#comments:id=2458569",
        },
        {
            id = 1377336,
            score = 16,
            author = "bomaya",
            text = "Re-doing the quest at level 85 it is of course now easier to just jump in the water and kill him yourself. :)",
            date = "2011-03-27T08:31:11-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27222#comments:id=1377336",
        },
        {
            id = 2574931,
            score = 16,
            author = "catsniffer99",
            text = "There seems to be a number of issues with this quest currently.  Getting on a flying mount automatically causes the quest to fail.  Also, killing the boss too quickly (without using cannons as a high level) seems to glitch the quest to not give credit for the kill.  Recommend being patient and doing the quest the way it was intended (using the cannons and not mounting up) so you don't have to run out of the zone to reset the quest like I did multiple times.",
            date = "2018-06-19T13:46:40-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27222#comments:id=2574931",
        },
        {
            id = 1206944,
            score = 13,
            author = "262755",
            text = "Simply click the cannons once they become active. I just mounted up and ran between the 3 of them. None of the marksmen died by the time I was done. Turn in quest for lootz!",
            date = "2010-12-04T21:29:00-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27222#comments:id=1206944",
        },
