    [27227] = {
        {
            id = 1177394,
            score = 37,
            author = "Darthdavo",
            text = "Start: Bloodfen Screecher\n\nWait, what?",
            date = "2010-11-22T03:26:25-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27227#comments:id=1177394",
        },
        {
            id = 1555511,
            score = 11,
            author = "LoKHor",
            text = "You hand this in at the end of the dungeon, just outside the Baron's ziggurat. Don't teleport out and back in to the entrance. The map shows question marks but the NPCs are not there.",
            date = "2011-10-27T23:39:15-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27227#comments:id=1555511",
        },
        {
            id = 1703886,
            score = 8,
            author = "Gadoink4",
            text = "Upon the defeat of Aurius Rivendare, Eligor will tell you the following:\nCrusade Commander Eligor Dawnbringer says: Your actions were pivotal in successfully reclaiming the city. Rivendare's death signifies the beginning of a new era for the Plaguelands. The few remaining Scourge should fall easily, and the land will at last be reborn.\nCrusade Commander Eligor Dawnbringer says: Stratholme may take quite some time to be rebuilt and fully cleansed, but it is an effort I will take great pleasure in watching unfold. Perhaps one day we will see the next great defender of the Light armed in the Bastion of the Silver Hand, or ordained in Alonsus Chapel. No matter the outcome, our work here will bear great fruit one day.\nCrusade Commander Eligor Dawnbringer says: Thank you, brave heroes. Thank you for showing Azeroth that no matter how overhwelming [sic] the darkness becomes, a single Light can pierce through.",
            date = "2012-08-24T14:47:54-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27227#comments:id=1703886",
        },
        {
            id = 1630002,
            score = 6,
            author = "Schnoodledorfer",
            text = "Before you do this one, you will have to kill all of the abominations in front of the slaughterhouse. Once you do that,  Rivendare yells: So you see fit to toy with the Lich King's creations? Ramstein, be sure to give the intruders a proper greeting. Then https://www.wowhead.com/npc=10439 (the objective of https://www.wowhead.com/quest=27228) yells:Ramstein hunger for flesh!After Ramstein comes out to fight and you kill him, a bunch of https://www.wowhead.com/npc=11030 attack. Then a https://www.wowhead.com/npc=10394 yells:Who dares disturb our master?Then four of them come out and attack. Finally, get a chance to kill Rivendare.\n\nThere are pauses in between the attacks that allow you to heal and get mana. You may see where you will eventually be able to turn in quests on your minimap, but the quest givers won't phase in before you are done.",
            date = "2012-02-21T15:49:38-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27227#comments:id=1630002",
        },
        {
            id = 1673604,
            score = 4,
            author = "986858",
            text = "To open the final gate I found that I had to kill the 3 mini bosses (which are in the doorway of  the green buildings on map) AND the mobs inside the structures, ALL of them. Then kill the abominations outside building through gates and Lord Aurius Rivendare will eventually unlock door, and BOOM! Done!",
            date = "2012-06-05T07:46:11-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27227#comments:id=1673604",
        },
    },
    [27228] = {
        {
            id = 1194759,
            score = 11,
            author = "PaulertheMauler",
            text = "Reference to Mann gegen Mann (Man against Man) by the German rock band Rammstein!",
            date = "2010-11-29T01:31:51-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27228#comments:id=1194759",
        },
        {
            id = 1243938,
            score = 6,
            author = "Brightstar",
            text = "Spelling error in the quest text.  \"I cannot bare to tell you\"...should be bear.   Silly Blizzard.  Spellcheck doesn't always catch grammarcheck!  :)",
            date = "2010-12-18T18:31:55-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27228#comments:id=1243938",
        },
        {
            id = 1629991,
            score = 4,
            author = "Schnoodledorfer",
            text = "Ramstein and https://www.wowhead.com/npc=45412 will be locked inside the slaughterhouse at first. To get Ramstein to appear, you must kill all of the abominations in the area. Once you do that,  Rivendare yells: So you see fit to toy with the Lich King's creations? Ramstein, be sure to give the intruders a proper greeting. Then Ramstein yells:Ramstein hunger for flesh! and comes out to fight. After you kill him, a bunch of https://www.wowhead.com/npc=11030 attack. Then a https://www.wowhead.com/npc=10394 yells:Who dares disturb our master?Then four of them come out and attack. Finally get a chance to complete https://www.wowhead.com/quest=27227 by killing him.\n\nThere are pauses in between the attacks that allow you to heal and get mana. You may see where you will eventually be able to turn in quests on your minimap, but the quest givers won't phase in before you kill Rivendare.",
            date = "2012-02-21T15:13:52-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27228#comments:id=1629991",
        },
        {
            id = 1844015,
            score = 2,
