    [27237] = {
        {
            id = 1194254,
            score = 183,
            author = "239542",
            text = "Open the box he gives you.  Run or swim out to one of the floating \"shipwreck debris\" and use your salvage kit on the debris.",
            date = "2010-11-28T19:18:08-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27237#comments:id=1194254",
        },
        {
            id = 1667983,
            score = 54,
            author = "TimeTraveler",
            text = "This is the worst written quest...first it doesn't tell you that you can't just find the strongbox, you need to \"salvage\" it with the salvage kit that is hidden in a box that has been dumped into your bag without telling you.  Also in this box is the helmet that you also don't understand why it is not on your head after you accept the quest (like many others do).......so, go in your bag, click the box that you find, put on the helmet.\n\nThe salvage kit will now show next to the quest.  Next it says \"locate pieces of the wreckage on the bottom\".....they are not on the bottom, but floating up on the top of the water, go on/by/under them and use the salvage kit.  Not all have strongbox, but you only need one as stated so just keep going until you find one.  You will be attacked by one murloc right after each the salvage attempt, so be prepared.",
            date = "2012-05-17T23:09:47-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27237#comments:id=1667983",
        },
        {
            id = 1702900,
            score = 27,
            author = "1023109",
            text = "If you are actually looking on the sea bed for the Box, like the instructions say, you will be looking for along time! maybe that is why the other divers haven't found anything yet :/ you have to use the salvage kit on the floating debris.",
            date = "2012-08-22T04:26:09-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27237#comments:id=1702900",
        },
        {
            id = 1637956,
            score = 10,
            author = "258432",
            text = "Leads to https://www.wowhead.com/quest=27238",
            date = "2012-03-10T19:43:28-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27237#comments:id=1637956",
        },
        {
            id = 2172823,
            score = 7,
            author = "Stephen3337",
            text = "Funny story, I thought the debris were fishing platforms.  They were boards lashed together with barrels to float and had little cooking fires on them. And fishing pods under most.  I fished off them.  Then I found an actual shipwreck- mast torn sails- broken ship- tattered flag against some rocks in the area and couldn't use the salvage on it.  I'm in the middle of a shipwreck and it says needs a shipwreck..\n\nThanks guys for pointing out the floating things were the shipwreck debris.  I got it on the first try after that, saw no murlochs.  Didn't use the helmet.  Azure silk belt gives 15% swimming speed boost and is nice to have in watery areas even if you're a leather ore mail class.",
            date = "2015-04-26T16:09:09-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27237#comments:id=2172823",
        },
    },
