    [27241] = {
        {
            id = 1694909,
            score = 40,
            author = "Karadine",
            text = "For a reusable teleport from Theramore to Stormwind Keep, keep the previous https://www.wowhead.com/quest=27240 and speak to https://www.wowhead.com/npc=4968.\nFor a reusable teleport from Mage Quarter (Stormwind) to Theramore, keep https://www.wowhead.com/quest=27241 and speak to https://www.wowhead.com/npc=2708.\n\nAnd yes, after you've done the https://www.wowhead.com/achievement=7467 scenario, using the dialog to teleport makes you arrive high above ground, where the top floor of the tower used to be. You should be ready for that plunge with a Slow Fall effect.  You can also visit Zidormi at the far end of the western bridge out of Theramore and return to the pre-destruction phase, if you wish to avoid the fall.",
            date = "2012-08-01T14:45:15-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27241#comments:id=1694909",
        },
        {
            id = 1715172,
            score = 35,
            author = "Kaerathas",
            text = "After completing https://www.wowhead.com/achievement=7467, Malin will still teleport you to the same location he used to... the top floor of the tower.\n\n*splat*",
            date = "2012-09-17T16:57:25-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27241#comments:id=1715172",
        },
        {
            id = 1368019,
            score = 18,
            author = "Rhaeda",
            text = "Does this questline lead anywhere? Seems like an abrupt ending.",
            date = "2011-03-16T00:25:05-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27241#comments:id=1368019",
        },
        {
            id = 1438568,
            score = 13,
            author = "Vlad",
            text = "Long ago they fixed this by setting a \"max level\" to the teleport to avoid high levels from using this as a quick transport to Theramore -now with Cataclysm launched it again works like before their level fix, thus at 85 you can keep this quest and use the teleport when ever you need to get to Theramore asap. ;)",
            date = "2011-06-10T13:07:00-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27241#comments:id=1438568",
        },
        {
            id = 1717345,
            score = 10,
            author = "Taoma",
            text = "As of 5.0.5, you can still use this quest to teleport to Theramore, however you might want to use slow fall or levitate, because it teleports you exactly on the same spot it used to before - high up the tower :D",
            date = "2012-09-23T00:53:24-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27241#comments:id=1717345",
        },
    },
    [27242] = {
        {
            id = 2498055,
