        {
            id = 1714765,
            score = 5,
            author = "75955",
            text = "Before handing in this quest. Drop it and go talk to Smiling Jim near the town inn for a quick breadcrumb ONLY available if you do not have Inspecting the Ruins in your log.",
            date = "2012-09-16T21:30:07-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27249#comments:id=1714765",
        },
        {
            id = 1645293,
            score = 1,
            author = "Qoko",
            text = "Note for anyone going for current Loremaster: this quest and it's chain are the key in getting North Point Tower and Tabetha's farm as quest hubs in Dustwallow. Get this chain going and do all the quests you get in combation with this chain's quests and you'll only have to visit every place once.\n\nI made the mistake of going to the aforementioned places and doing the unrelated quests there first, having to revisit the quests areas again for this chain.",
            date = "2012-03-27T08:48:38-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27249#comments:id=1645293",
        },
        {
            id = 1818563,
            score = 1,
            author = "LukeOwens",
            text = "No one seems to have noticed this: The Shady Rest Hotel was the main setting for the old TV series \"Petticoat Junction\". It was run by Kate Bradley and her daughters Billie Jo, Bobbie Jo, and Betty Jo, with the unhelpful help of Uncle Joe (who moves kinda slow, according to the show's theme song).\n\nSo it's another pop culture reference by the programmers.",
            date = "2013-02-26T17:30:32-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27249#comments:id=1818563",
        },
    },
