    [27291] = {
        {
            id = 1350131,
            score = 47,
            author = "385800",
            text = "I'm glad Blizz left this one intact.  It's about the best short story line in the game.  Shows that a there are consequences to things that happen.\n\nJust wish there was a way to converse with Jim after you have completed the quest line.  You know something like buying him a mead.  Or even better, maybe doing something to help him get back on his feet - like helping him find a purpose again or something.\n\nAnyway, still like this one!",
            date = "2011-02-25T19:49:25-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27291#comments:id=1350131",
        },
        {
            id = 1366509,
            score = 22,
            author = "Ashik",
            text = "Here is what you hear from Lynn (npc=23768) and Jimmy (npc=23769) when you put the wreath on their faily monument:\n\nLynn Hyal says: James? James... No, you're not James, but I know who you are...\nLynn Hyal says: You're the one who tracked down the brutes who did this to us.\nLynn Hyal says: I tried so hard to tell Jim... to tell anyone... who was behind this, but I couldn't find a way...\nLynn Hyal says: Thank you for helping us and for helping Jim. If you see him, tell him little Jimmy and I love him and that we're waiting for him.\nJimmy Hyal says: Mommy, when will we see Daddy again?\nLynn Hyal says: I don't know when we'll see Daddy again, Jimmy, but I know he loves you and he misses you very much.\n\n(taken from this comment (quest=11152#comments:id=186876) from old version of the same quest)\n\nP.S. James is Smiling Jim (npc=4895) at the local inn.",
            date = "2011-03-14T06:38:27-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27291#comments:id=1366509",
        },
        {
            id = 1638982,
            score = 17,
            author = "442479",
            text = "I didn't expect this to get to me again, but it did. Whoever wrote this deserves a medal.",
            date = "2012-03-13T09:02:48-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27291#comments:id=1638982",
        },
        {
            id = 1366506,
            score = 10,
            author = "Ashik",
            text = "There are quite a few good heart-touching comments in the old version (quest=11152#comments) of the same quest.",
            date = "2011-03-14T06:24:14-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27291#comments:id=1366506",
        },
        {
            id = 1717368,
            score = 9,
            author = "1022978",
            text = "Theramore's Fall went live and Mists is 2 days away but I've been waiting to do the event until I redid all of the Theramore questlines. This happened to be the last quest I did, and it made me sadder than ever to know Blizz is getting rid of this place. I can't believe something as iconic and awesome as the one human foothold in Kalimdor we all remember since vanilla is going to just be blown up permanently like this. I'll miss Theramore, and these quests greatly.",
            date = "2012-09-23T02:05:45-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27291#comments:id=1717368",
        },
    },
