    [27311] = {
        {
            id = 1204410,
            score = 12,
            author = "195360",
            text = "Most likely a reference to \"The Soup Nazi\" in the TV show Seinfeld, in one of the most memorable episodes ever.\n\nThe character ran a soup shop with extreme discipline, and whenever someone didn't perform to his unusually high standards he would yell \"No soup for you!\" and kick them out.",
            date = "2010-12-03T14:50:55-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27311#comments:id=1204410",
        },
        {
            id = 1708810,
