            author = "960102",
            text = "I had problems to find her to turn this quest in, she was at cave in 39, 26.",
            date = "2012-09-03T15:23:16-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27311#comments:id=1708810",
        },
        {
            id = 1499354,
