    [27314] = {
        {
            id = 1336288,
            score = 4,
            author = "716722",
            text = "Posting this here because it applies to the entire quest chain, and I'm not sure if it's a problem from the server I'm on or just in general.\n\nIf you are a feral cat druid, or rogue, \"Feralas Sentinel\" does not hold stealth as she should. She turns stealth while in combat, and as soon as you are out, she hops out. Probably just a programming issue, but it makes the whole idea of playing a rogue character (both options) a bit harder since you really have to take on the mobs as they come.\n\nThat said, it's an amazing questline that will get you a level and a half and is worth the effort.",
            date = "2011-02-14T17:09:22-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27314#comments:id=1336288",
        },
        {
            id = 2868716,
            score = 4,
            author = "Valrysha",
            text = "This quest hasn't gone well with the scaling from 8.0, it is a little overtuned. The mob kills your Sentinel within moments and then demolishes you. I got close to killing her but it's pretty difficult. Bring a healing potion.",
            date = "2019-01-28T23:01:38-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27314#comments:id=2868716",
        },
        {
            id = 1282096,
            score = 3,
            author = "braneman",
            text = "very worthwhile quest chain, should get you a level, and plenty of gold, especially if you don't need any of the quest gear, all of the objectives are in the same general area and you get a helper, its like a 2 man dungeon.",
            date = "2011-01-07T09:14:21-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27314#comments:id=1282096",
        },
        {
            id = 1346780,
            score = 3,
            author = "794585",
            text = "I find the Feralas Sentinel to be an excellent tank and somehow is able to take all the mobs from me (I'm a feral cat)  Especially ALL the bosses.  They simply turn their backs on me and focus on her.  Compared to if I do a solo run - my HP just drains like wtf and I cannot last even this one.",
            date = "2011-02-23T03:36:05-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27314#comments:id=1346780",
        },
    },
    [27315] = {
