    [27317] = {
        {
            id = 1354766,
            score = 2,
            author = "727888",
            text = "Starts from a stationary object: https://www.wowhead.com/npc=48208.\n\nIt's located in plain sight just to the left of the entrance of Isha Gloomaxe's tent. You should definitely see it during https://www.wowhead.com/quest=27315, given by the Freewind Brave.",
            date = "2011-03-02T02:14:54-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27317#comments:id=1354766",
        },
        {
            id = 1997824,
            score = 1,
            author = "1075918",
            text = "Take what you will, but don't rattle me bones!",
            date = "2014-08-30T19:49:47-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27317#comments:id=1997824",
        },
    },
    [27318] = {
        {
            id = 1936320,
            score = 8,
            author = "lizardo",
            text = "The whole questline for these guys start with Caryssia Moonhunter (http://www.wowhead.com/npc=39946) at the border of Feralas and Thousand Needles. From what I have seen, you have to do all of the barge quests. Once done there you have to go to Fizzle Brassbolts (http://www.wowhead.com/npc=40027). He will give a bread crumb quest to go to Freewind post, and you can finally start the quest to get  Save the Sentinel (http://www.wowhead.com/quest=25871) which starts this quest line.",
            date = "2014-01-20T18:32:25-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27318#comments:id=1936320",
        },
        {
            id = 1194644,
            score = 6,
            author = "Xaerjin",
            text = "Just did this quest at lvl 80 while farming through the zone for my quest achievement. I decided to melee him barehanded so I could see how the real fight looked, and was glad I did. Very cool fight! Just FYI for those of you doing it at the level it's supposed to be done at: Since I was just doing barehand melee, the Ferelas Sentinel carried agro pretty much the whole time and tanked without any problem at all. No need to try to taunt.. this isn't your run-of-the-mill weenie escort quest type of NPC that can't take hits. :)",
            date = "2010-11-28T23:41:55-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27318#comments:id=1194644",
        },
        {
            id = 1978343,
            score = 3,
            author = "Simonds22",
            text = "Don't forget to use the Horn of the Traitor that you should have just gotten from the quest of the same name. Summon Longhorn to fight for you as soon as Stormhoof transforms into the cliff giant and it makes all the difference.",
            date = "2014-07-06T17:32:25-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27318#comments:id=1978343",
        },
        {
            id = 1201924,
            score = 1,
            author = "Vivallion",
            text = "I cant seem to pick up this quest from anywhere, do you need to kill the elder to get the quest?",
            date = "2010-12-02T08:36:55-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27318#comments:id=1201924",
        },
        {
            id = 1922435,
            score = -5,
            author = "BCGiant",
            text = "This quest is a joke. How can you solo a 42 Elite that has over 30k HP more than you and is immune to all Stuns and interupts? This should be a group quest and journal says nothing about needing others. Sure the Brave helps till the elder changes into a Giant Stone Beast. Then he dies and then you die.",
            date = "2013-11-30T13:48:58-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27318#comments:id=1922435",
        },
    },
