    [27327] = {
        {
            id = 1194658,
            score = 5,
            author = "Xaerjin",
            text = "The Ferelas Sentinel can tank pretty much ALL of the mobs for almost the ENTIRE fight. She died when Arnak was at about 4.5% and had held agro on everything just fine. All you have to do is quickly finish off Arnak when she dies (save your cooldowns for the end!).\n\n** If the Sentinel dies during the fight, she will reappear again after a moment. No quests will turn up \"failed\" due to her death.",
            date = "2010-11-28T23:49:18-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27327#comments:id=1194658",
        },
        {
            id = 1277163,
            score = 3,
            author = "spriint",
            text = "she never died when i did this. Just nuke the boss and don't worry about the adds they all disappear once the boss is dead",
            date = "2011-01-04T14:25:06-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27327#comments:id=1277163",
        },
        {
            id = 1345035,
            score = 3,
            author = "ziggy29",
            text = "In reality, once you get the sentinel, all you need to do is work on the bosses.  Just avoid taking a lot of hits from the other Grimtotems and she can tank it all on her own.  With a level 44 priest, I mostly shot a wand at the Grimtotems and saved the mana for hitting the bosses hard, letting her tank all the other guys into oblivion.  For Arnak, the sentinel used her healing potion and died as I was starting to throw a mind blast.  I had Arnak and five goons chasing me after her death, but just as she was resurrecting and taking the aggro away, my mind blast finished off Arnak.  That was cutting it close!",
            date = "2011-02-21T16:02:32-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27327#comments:id=1345035",
        },
        {
            id = 1657899,
            score = 2,
            author = "SockPuppet",
            text = "Arnak went into Evade mode and reset twice before I was able to get him down. Apparently I pulled him too far from his tent, although it wasn't like I was kiting him across the map or anything -- he was not even halfway across the platform. I ended up starting from nowhere near max range (hunter) and was finally able to kill him before he reset.",
            date = "2012-04-23T16:15:06-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27327#comments:id=1657899",
        },
        {
            id = 1764094,
            score = 2,
            author = "1054233",
            text = "Man, this is the first real killer challenge I've encountered since I started playing a couple of months ago. My level 44 Fire Mage has died nine times trying to kill Arnak. My Tauren tank dies when Arnak is down to the last 10%, and immediately I am clobbered to death by Arnak and his gang of ruffians.\n\nI've tried attacking him from the front, the rear of the tent, the cave mouth, and even resurrected myself inside his tent - but it ended in similar fashion each time around.\n\nI'm going to level up and return for him later.\n\nEdit: Needed three more levelling before I was able to kill Arnak - and that was by the skin of my teeth.",
            date = "2012-11-18T03:37:31-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27327#comments:id=1764094",
        },
    },
    [27328] = {
        {
            id = 1201997,
            score = 30,
            author = "dreamwvr",
            text = "This guy is a 43 elite that hits hard, but the adds he spawns are the real problem.  If you focus just on him, he will spawn 9 adds that will kill you.  In this quest you get a tauren warrior to help you fight.  Let him fight chief while you take out the adds.  When there are no adds, pound on him, but always make the adds a priority.  Easy quest if you do this.  Will kill you many times if you don't.\n\nHave a great day, and happy hunting.",
            date = "2010-12-02T09:35:54-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27328#comments:id=1201997",
        },
        {
            id = 1556593,
