    [27348] = {
        {
            id = 1202926,
            score = 16,
            author = "Koviko",
            text = "You're commenting on the new version of the quest. It is still in-game and still possible to complete.\n\nA tip for finding the cargo crates:\nIn your Video settings, set Ground Clutter to \"Low.\"",
