    [27367] = {
        {
            id = 1190431,
            score = 22,
            author = "177789",
            text = "The entire questline:\nGidwin Goldbraids (http://www.wowhead.com/quest=27367)\nJust Encased\n (http://www.wowhead.com/quest=27368)Greasing the Wheel (http://www.wowhead.com/quest=27369)\n\nTarenar Sunstrike (http://www.wowhead.com/quest=27370)\nWhat I Do Best (http://www.wowhead.com/quest=27371)\nA Gift For Fiona (http://www.wowhead.com/quest=27372)\nOnward, to Light's Hope Chapel (http://www.wowhead.com/quest=27373)\n\nMr. Grubbs (http://www.wowhead.com/item=66076) can now drop if you get the lucky charm (http://www.wowhead.com/quest=27555) buff from the caravan.\n\nTraveling Companions (http://www.wowhead.com/quest=27381)\n\nRough Roads (http://www.wowhead.com/quest=27382)\n\nThe Trek Continues (http://www.wowhead.com/quest=27448)\nBoys Will Be Boys (http://www.wowhead.com/quest=27455)\nA Boyhood Dream (http://www.wowhead.com/quest=27463)\nArgent Call: The Trial of the Crypt (http://www.wowhead.com/quest=27464)\nArgent Call: The Noxious Glade (http://www.wowhead.com/quest=27465)\n\nCompleting \"The Trial of the Crypt\" will put you at revered with the Argent Dawn\nCan now complete the repeatable quests [quest=28755 domain=www] and [quest=28756 domain=www] for additional dawn rep.\n\nGathering Some Grub(s) (http://www.wowhead.com/quest=27456)\nAn Opportune Alliance (http://www.wowhead.com/quest=27457)\n(the previous two quests are only required if you want the achievement (http://www.wowhead.com/achievement=5442))\n\nArgent Call: Northdale (http://www.wowhead.com/quest=27466)\nIx'lar the Underlord (http://www.wowhead.com/quest=27487)\n\nImpatience (http://www.wowhead.com/quest=27488)\nNobody to Blame but Myself (http://www.wowhead.com/quest=27489)\nBeat it Out of Them (http://www.wowhead.com/quest=27522)\nBlind Fury (http://www.wowhead.com/quest=27524)\nGuardians of Stratholme (http://www.wowhead.com/quest=27525)\n\nThe Baroness' Missive (http://www.wowhead.com/quest=27551)\nGidwin's Fate Revealed (http://www.wowhead.com/quest=27526)\nJourney's End (http://www.wowhead.com/quest=27527)\n\nKeep in mind you only need to do the first half of the questline to get Argent Dawn rep and the pet.  The rest is only for the achievement or to see the end of the story =)\n\n*under construction* more achievement info coming soon.",
            date = "2010-11-27T12:39:49-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27367#comments:id=1190431",
        },
        {
            id = 1206794,
            score = 13,
            author = "84555",
            text = "Best way to reach him is to swim up the Thondroril River or take the path that follows the river which starts near 13.8,60.9 (http://www.wowhead.com/maps?data=139:1386091265961165841045720945610825410725160625060514910464770384600364440364310374070333840333579).\n\nAlternatively, you can go through the Terrorweb Tunnel if you happen to be in the north-western part of EPL, but that will make you go through the spiders you'll have to kill a few minutes later for the first quest Gidwin gives you.",
            date = "2010-12-04T19:37:03-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27367#comments:id=1206794",
        },
        {
            id = 1478510,
            score = 10,
            author = "718691",
            text = "I love this quest chain so much that I've done it on every character of mine: thus far a blood elf, human, and a worgen - all males. As I began to go for number four, I noticed something interesting.\n\nWhen I started the quest with my female worgen, when I found Gidwin he asked \"Fiona, is that you?\" instead of asking for Tarenar like with my other characters. Sounds like his question changes depending on what gender your character is.",
            date = "2011-07-24T15:41:48-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27367#comments:id=1478510",
        },
        {
            id = 1463113,
            score = 5,
            author = "FuryWar",
            text = "When I found him, he was being guarded by a 41- rare spawn Nebian Overseer.",
            date = "2011-07-07T02:55:01-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27367#comments:id=1463113",
        },
        {
            id = 1208719,
            score = 4,
            author = "334124",
            text = "The starting location for the quest was incorrect for me.  I found Fiona at 9,66, near the Thondroril River flight point (Alliance).  I've not done any other quests in Eastern Plaguelands (since 4.0.3), so this may be a phasing issue.",
            date = "2010-12-05T17:06:14-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27367#comments:id=1208719",
        },
    },
