        {
            id = 1390983,
            score = 15,
            author = "93331",
            text = "There are some IN the water, along the shore, in the path and even one or two partly up the mountain, although hard to see, the glimmer should give it away even those ones in the water. Just zigzag your way down the path and you should get them all without to much trouble.",
            date = "2011-04-14T05:36:31-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27369#comments:id=1390983",
        },
        {
            id = 1186180,
