            author = "421845",
            text = "Herbologists can find quest nodes by using their herb tracking feature.\n\nIt's easy either way. Just look along the path area.",
            date = "2010-11-25T22:59:10-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27369#comments:id=1186180",
        },
        {
