    [27371] = {
        {
            id = 1182710,
            score = 28,
            author = "412275",
            text = "is it me, or is this \"lovely\" traveling companion the epitome of loladin facerolling?\nhe opens combat with an aoe to just rip threat off the \"tank\" and keeps aoeing when theres 1 mob left, stands in void zones, uses seal of truth for aoe, and refuses to heal himself when he is at half health.\n\nalso, stop following me while i am in stealth you nubadin!",
            date = "2010-11-24T19:14:59-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27371#comments:id=1182710",
        },
        {
            id = 1194073,
            score = 18,
            author = "Talvanor",
            text = "Quest dialog aside, this guy doesn't seem to know his lore. He says \"When I was young, I used to sneak away and beat up on zombies for fun.\"\n\nProblem is, Blood Elves are considered adults at 60 years old, and the Scourge invaded Quel'Thalas a little less than 8 years prior to Cataclysm, so... The timeline just doesn't really fit.",
            date = "2010-11-28T17:35:21-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27371#comments:id=1194073",
        },
        {
            id = 1188016,
            score = 11,
            author = "502547",
            text = "For those having trouble completing, try disabling all your addons.  You actually don't have to talk to the quest NPC to complete the quest.  With no addons enabled, just click the gigantic question mark on your quest tracker and it will complete itself.",
            date = "2010-11-26T15:10:52-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27371#comments:id=1188016",
        },
        {
            id = 1180854,
            score = 9,
            author = "265396",
            text = "I wasn't able to complete the quest in the first place. The NPC was just following as a companion/guardian and only appeared on my Minimap as a question mark.\nEven leaving and returning to him didn't work: Just as I arrived he despawned as a quest NPC and respawned as a guardian-type.\nI had to leave the zone (up to Fiona's Caravan) until he was dismissed, then hurried back and quickly clicked on him and then the \"Complete\"-button.\nThis way I could accept the follow-up quest.",
            date = "2010-11-24T09:23:51-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27371#comments:id=1180854",
        },
        {
            id = 1261730,
            score = 7,
            author = "708827",
            text = "The mobs killed him while I was doing the quest, but it still let me complete it.  And it gave me the next quest as if he was still alive.  He doesn't regen health and it wouldn't let me heal him, so he was a lost cause.",
            date = "2010-12-27T10:11:12-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27371#comments:id=1261730",
        },
    },
    [27372] = {
        {
