            text = "Drop rate on the Plaguehound Blood (http://www.wowhead.com/item=60986) seemed to be a bit higher than 50% (while the quest was active).",
            date = "2010-11-28T22:12:05-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27372#comments:id=1194514",
        },
        {
            id = 1283041,
            score = 5,
            author = "XLent1",
            text = "It starts from roughly 18.3 74.9",
            date = "2011-01-07T21:45:38-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27372#comments:id=1283041",
