    [27415] = {
        {
            id = 1204702,
            score = 26,
            author = "711738",
            text = "The eggs are inside of stumps that surround the outside of onixia's lair.  each stump has 3-4 eggs in it.  There are not that many stumps, but they are there.",
            date = "2010-12-03T17:32:20-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27415#comments:id=1204702",
        },
        {
            id = 1604672,
            score = 16,
            author = "231954",
            text = "Seems like this is the only quest which makes you choose between a common and a rare reward.",
            date = "2011-12-31T11:42:07-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27415#comments:id=1604672",
        },
        {
            id = 1409453,
            score = 7,
            author = "824915",
            text = "Just picked-up and completed this quest chain post-cata. Quest giver is located in Brackenwall (inside the cave with the innkeeper). The egg \"nests\" look like hollow tree stumps on either side of Onyxia's lair in the Dragonmurk. The eggs glittered like loot but no cog appeared when I moused-over. Just click each egg (there's 3 or 4 per nest) and they will be destroyed one at a time.",
            date = "2011-05-04T14:13:24-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27415#comments:id=1409453",
        },
        {
            id = 2552844,
            score = 7,
            author = "Nagamaki",
            text = "If, like me, you found the first two stumps to be empty from others completing the quest, there are two more stumps at the following coordinates: 53.5, 72.5 and 56.5, 75.",
            date = "2018-02-15T12:37:51-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27415#comments:id=2552844",
        },
        {
            id = 1312761,
            score = 5,
            author = "Tenolein",
            text = "Alphaaldridge is right.  The eggs are in busted up tree trunks / stumps between Onyxia's Lair and Mudsprocket.  I can confirm two of their locations at 48.5, 73.6 and 48.4, 76.   Each of the nests had 4 eggs in them, so you will in fact need to find 2 of the nests.\n\nHope this helps.",
            date = "2011-01-28T03:30:34-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27415#comments:id=1312761",
        },
    },
