    [27418] = {
        {
            id = 1548601,
            score = 81,
            author = "771449",
            text = "Ok for you who have want to get the gear here and not bother with other quests you only need to do the following.\n\n1. Talk to Draz'Zilb (http://www.wowhead.com/npc=4501) - he is located in camp inside the small cave and take the quest Identifying the Brood (http://www.wowhead.com/quest=27414)\n2.  Also take the quest from Overlord Mok'Morokk (http://www.wowhead.com/npc=4500) called Overlord Mok'Morokk's Concern (http://www.wowhead.com/quest=27424).\n3. Fastest way for me was to take the flight path to Mudsprocket.\n4. After completing (handing in) those you will need to accept The Brood of Onyxia (http://www.wowhead.com/quest=27416) and then run between Overlord Mok'Morokk (http://www.wowhead.com/npc=4500) and Draz'Zilb (http://www.wowhead.com/npc=4501) acting as mail man until Draz'Zilb (http://www.wowhead.com/npc=4501) gives you the final version of The Brood of Onyxia (http://www.wowhead.com/quest=27415).\n5. Take the flight path back to Mudsprocket as it is close by and go destroy the 5 eggs and head back to Draz'Zilb (http://www.wowhead.com/npc=4501) and complete the quest.\n6. At this point Overlord Mok'Morokk (http://www.wowhead.com/npc=4500) should have this quest for you.\n\nHope this helps any of you looking to start this quest chain.",
            date = "2011-10-19T16:36:10-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27418#comments:id=1548601",
        },
        {
            id = 1277215,
            score = 13,
            author = "108011",
            text = "Easily doable on your own now, he's not elite anymore.",
            date = "2011-01-04T14:58:43-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27418#comments:id=1277215",
        },
        {
            id = 5367814,
            score = 9,
            author = "DaemoniKira",
            text = "If you're curious like me and wondered where https://www.wowhead.com/npc=4500 ran off to after you whooped him in front of his whole tribe:\nHe runs down the path heading south out of Brackenwall Village, almost halfway to the trident in the road (one road splits into three) -- he stops on the path just short of where https://www.wowhead.com/npc=4503 is just chilling at a campfire, and then despawns.\n\nYa know, 'cause this is crucial information. :P\n\nDoes anyone else always follow NPCs when they run off, just to see how far they run? I do, every time -- I'm way too curious not to!",
            date = "2022-05-03T00:14:50-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27418#comments:id=5367814",
        },
        {
            id = 1196655,
            score = 4,
            author = "160411",
            text = "I picked up The Brood of Onyxia (http://www.wowhead.com/quest=27416) after completing this quest, not sure what to do with it now.",
            date = "2010-11-29T22:33:03-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27418#comments:id=1196655",
        },
        {
            id = 1316288,
            score = 0,
            author = "777045",
            text = "For anyone who failed at killing him, and are wondering what to do, listen here. I abandoned my quest, and couldn't find out how to retake it for a bit. I had to wait a little while, and then Mok'Morokk reappeared with an '!'. In order to kill him, as a balanced druid, I ensured that I used my items to give me health and/or mana. My staff was out of durability, so this was necessary as he kept \"stunning\" me, making it impossible to continuously heal myself or cast spells.\n\nSo, make sure you buy some foodstuffs from Mudsprocket (village south) in case you need to do that. I was lvl 40 when doing this. A level below may be a bit more difficult and I'd suggest getting a second person to help out.\n\nGood luck! :)",
            date = "2011-01-30T20:43:15-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27418#comments:id=1316288",
        },
    },
