    [27438] = {
        {
            id = 1193163,
            score = 25,
            author = "712283",
            text = "just confirmed if u dont have Belmont and the val'kir on ur side at the beach just abandon the quest and they will appear right infront of you.",
            date = "2010-11-28T11:21:44-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27438#comments:id=1193163",
        },
        {
            id = 1210461,
            score = 15,
            author = "138612",
            text = "79,75 is location, I got stuck here also and took me a while to find this guy.  On the south east side looking at the map of Ruins of Gilneas on a small beach left of the island connected with a bridge.",
            date = "2010-12-06T15:47:06-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27438#comments:id=1210461",
        },
        {
            id = 1756573,
            score = 15,
            author = "Schnoodledorfer",
            text = "https://www.wowhead.com/quest=27423 is a prerequisite for this one, but can be missed if you don't pass through a certain area. First, follow the zone's quest chain until https://www.wowhead.com/quest=27405 leads you to https://www.wowhead.com/npc=45312. Pick up https://www.wowhead.com/quest=27406 (the other prereq) from Belmont and follow the road that goes from the Emberstone Mine area past the east side of Gilneas City. Resistance is Futile will be automatically offered to you after you go down the road a little way. If you aren't offered The Great Escape because you didn't get Resistance is Futile, go back to where you started and make sure you stay on or at least close to the road.\n\nIf you loose Belmont and Arthura, try dismounting.\n\n(EDIT: Reworded)",
            date = "2012-11-03T23:23:52-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27438#comments:id=1756573",
        },
        {
            id = 1211574,
            score = 13,
            author = "721139",
            text = "So for some reason, I got the bright idea of hitting \"Leave vehicle\" whilst flying out. Word of advice... DON'T DO THAT.\n\nSeems obvious, but there are those as stupid as I that think, \"HUH? What does this do?\", only to find out that it makes you  take rez sickness, abandon the quest, and then makes you swim all the way around the damn peninsula thing to get back to the beach to pickup the quest again because you're too low level to get there through the elites... and if you have done this and you see where it ends, you will find out very quickly that going there on foot indeed does diddly squat.",
            date = "2010-12-07T08:17:23-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27438#comments:id=1211574",
        },
        {
            id = 1184673,
            score = 8,
            author = "363649",
            text = "This part of the quest bugged out on me. The Val'kir and undead guy that were following me around disappeared when I phased into this part. So now I can't fly back to Sylvanas, and when I run back I can't complete the quest because part of the requirement is to bring the undead buy back with you.\n\nCan't abandon the quest and retake it because the undead guy isn't around to give me the quest.",
            date = "2010-11-25T11:21:14-06:00",
