    [27447] = {
        {
            id = 1295678,
            score = 4,
            author = "765722",
            text = "There is actually a little 'cul-de-sac' at coords 74.95...take your boat from the speedbarge there and there's an uphill path that takes you right into Tanaris.",
            date = "2011-01-16T00:43:34-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27447#comments:id=1295678",
        },
        {
            id = 1362283,
            score = 2,
            author = "801425",
            text = "Orrrrrrrrr.....you can sail south of Speedbarge.\n\nreference: threadmeters . com/v-1but/How_do_you_get_to_Tanaris_now_horde [new comers can't share links unfortunately hence the spacing between the period above]\n\n\"Well the whole point is that you can easily get to Tanaris if you level in Kalimdor. The quest line sends you to the Speedbarge where you have quests to give you a river boat. Short of that you can swim which would take a couple minutes of your life and you just swim to where the old path from Shimmering Flats went into Tanaris. It's not like the zones completely were shifted and mangled, Thousand Needles is exactly like it was when you left it, just now under a couple hundred feet of water. \" ~Cloaknpoke\n\nThe text in bold is pertinent ;] Especially if you do not use coordinates [I prefer my map, to each their own].",
            date = "2011-03-09T12:47:26-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27447#comments:id=1362283",
        },
        {
            id = 1716909,
            score = 2,
            author = "715936",
            text = "No troubles if you cannot fly.  Look for the small bump in the middle of the curve at the bottom of your map - that is the beginning of the path through the hills.  There is also a road still on the lake bottom that runs north to south on the west side of the barge.  Just follow that south and you will be in Tanaris in no time.",
            date = "2012-09-22T00:42:57-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27447#comments:id=1716909",
        },
        {
            id = 1889271,
            score = 0,
            author = "WokkaD",
            text = "Please note : VERY IMPORTANT :\ndo NOT accept this quest until you have accepted the \"Free Freewind Post\" quest.\n\"Tanaris is calling\" is offered at level 43, BUT it is the LAST quest in the chain. Accepting it out of sequence breaks the quest chain !",
            date = "2013-08-22T17:01:41-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27447#comments:id=1889271",
        },
    },
    [27448] = {
        {
            id = 1191224,
            score = 15,
            author = "196807",
            text = "As you continue your journey on the caravan, the conversation between the 4 NPCs continues:\n\nGidwin Goldbraids says: This hardly seems fair!\nGidwin Goldbraids says: Why do I have to sit up top with all the stuff?\nFiona says: Because you're the bravest, dear.\nTarenar Sunstrike says: Because you're short.\nGidwin Goldbraids says: Hey!  I oughtta bounce one of these trunks off of your head, Tarenar.\nFiona says: I know I promised you the front seat, Giddy, but we have an elderly guest.  I'm sorry.\nTarenar Sunstrike says: Fiona, I must warn you: Gidwin only wants to sit in front because he wants to kiss you.\nGidwin Goldbraids says: Oh shut up, you dolt.  YOU probably want to kiss her a hundred times.\nTarenar Sunstrike yells: Do not!\nArgus Highbeacon says: Ahem!  I, ah, appreciate the ride, Madam Fiona.  It's nice to get off my feet for once.\nFiona says: Do you normally walk these roads alone?\nArgus Highbeacon says: Yes, I do, though it was easier when I was younger.  These days, I have to be more careful.\nGidwin Goldbraids says: If you don't mind my askin', what do you do that requires walking so much?\nArgus Highbeacon says: I service the five Argent towers.  Mostly repairs and maintenance, and some minor magical work.\nArgus Highbeacon says: Without proper upkeep, buildings within the plaguelands tend to... waste away.\nTarenar Sunstrike says: Noble work.\nArgus Highbeacon says: I find it satisfying.  I enjoy working with my hands.\nArgus Highbeacon says: By the way, if any of you need anything repaired, let me know.  I am at your service.\nGidwin Goldbraids says: So you're part of the Argent Crusade, eh?\nGidwin Goldbraids says: Think you can put in the good word for us?  We're looking to join the order.\nArgus Highbeacon says: Certainly.  I don't make it out to Light's Hope very often anymore, but when you arrive, tell Max Tyrosus that I sent you.\nTarenar Sunstrike says: Whoah... he lets you call him Max?\nArgus Highbeacon says: Ma'am, would you mind dropping me off at Light's Shield Tower, just up ahead?  I have to stop here.\nFiona says: Of course I'm not just going to drop you off, Master Highbeacon.  We'll be happy to wait for you.\nGidwin Goldbraids says: NOOOOOOO!  Stopped again!\nArgus Highbeacon says: Light's Hope isn't far, young paladin.  Might I suggest walking?\nGidwin Goldbraids says: Walking, eh...?",
            date = "2010-11-27T18:12:46-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27448#comments:id=1191224",
        },
        {
            id = 1192250,
            score = 10,
            author = "48446",
            text = "I bumped in to an issue yesterday doing this quest. I had done all quests except battle for darrowshire in Crown Guard Tower and was ready to move on. When I clicked on the caravan to move on both it and Fiona despawned and wouldn't come back even though I waited around. I tried looking for it at the next tower but it wasn't there either. Finally I tried relogging and that brought it back.\n\nThere was also a similar issue that my girlfriend ran into, she jumped on the caravan and after a little bit she got thrown off and the caravan despawned. Tried the same things as me and it was just gone. Relogging solved that issue as well.",
            date = "2010-11-28T03:22:48-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27448#comments:id=1192250",
        },
