    [27451] = {
        {
            id = 1361261,
            score = 9,
            author = "801017",
            text = "Not a very difficult quest if you're aware that there's a time limit. Once you collect your first living rot, the clock starts. If you donnot have the 7 required items (living rot) within 10 minutes, they're all gone. I had them in 3 minutes or so.",
            date = "2011-03-08T14:11:17-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27451#comments:id=1361261",
        },
        {
            id = 1532274,
            score = 9,
            author = "Farmbuyer",
            text = "Heh.  This used to be a Horde-only quest, given by a Forsaken with a seriously gritty temper (http://www.wowhead.com/npc=50609), back when that NPC was an outdoor questgiver (for the Horde) and raid boss (for the Alliance).  You still had to collect living rot and turn it into coagulated rot, and there was still a real-time expiration.  (The rot would then be fed to his pet hounds, which seem to have bred and taken over his previous house.)\n\nThe quest title came from the quest text at the time; the Blightcaller was teaching the player to kill with a specific goal instead of brainlessly slaughtering anything that moved.",
            date = "2011-10-01T09:00:34-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27451#comments:id=1532274",
        },
        {
            id = 1361139,
            score = 8,
            author = "750237",
            text = "Should be noted that the loot has a time limit!  You have 10 mins to complete the quest and make the rot.  And the drop rate is not 1:1 either so be sure to be ready to begin - full HP, buffs whatever you need.  Death does not stop the clock and it's a hefty run back considering the time factor.  If you cannot kill enough mobs to loot 7 items, the collected items disappear and you must start again.\n\nSo I had 6 items and was desperately trying to get the last drop but I was being \"mobbed\" (pun intended) by multiple attackers after my intended kill had called for help.  As a lvl 42 Rogue, I was unable to take on 4 at a time and died.  When I made it back and res'd, my loot was gone!\n\nDepending on the toon, this is a tricky and pain-in-the-butt quest.",
            date = "2011-03-08T11:42:47-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27451#comments:id=1361139",
        },
        {
            id = 2157430,
            score = 3,
            author = "Monatoet",
            text = "Note that you only get this from the undead. When you have 7, use the Mortar and Pestle.\nIf you loot too many Living Rot, you could try to split the stack? And then destroy what you have to much..",
            date = "2015-04-08T15:34:27-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27451#comments:id=2157430",
        },
        {
            id = 1348508,
            score = 1,
            author = "775338",
            text = "I noticed the quest is kind bugged.dont loot more then 7 quest items..all you need is 7 if you get more then 7 you will not be able to use Mortar and Pestle and sadly.you will have to delete and accept the quest again",
            date = "2011-02-24T12:52:31-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27451#comments:id=1348508",
        },
    },
