        {
            id = 2582840,
            score = 4,
            author = "1347703",
            text = "The cultists are indeed absorbing every attack, and immediately cast their shield again when it runs out. I'm a hunter, and nothing could damage them. I somehow got lucky and killed one of them. Blizz needs to fix them. The mob is https://www.wowhead.com/npc=8548 For now, just skip this questline and go to Light's Hope.",
            date = "2018-07-20T16:31:55-05:00",
