    [27454] = {
        {
            id = 1190922,
            score = 191,
            author = "Tygress",
            text = "To summarize -\n\nYou have three options for this quest. They each produce a different visual result, but ultimately the quest is completed by choosing any of the three.\n\n1 - Put in 1 drop (as recommended). This completes the quest with no excitement or pizazz.\n\n2 - Put in 1 flask. This causes a minor \"explosion\" which causes you to fall down (like when you are charged by something).\n\n3 - Put in 12 flasks. This causes a major explosion which knocks you back pretty far but does not cause you to take damage.",
            date = "2010-11-27T16:06:51-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27454#comments:id=1190922",
