    [27460] = {
        {
            id = 1313137,
            score = 7,
            author = "Sapho",
            text = "The quest doesn't tell you where in Tyr's Hand to find the flare. However, once you complete the kill 10 mobs bit, the built-in quest helper will point you in the right direction. Just in case: from the main entrance turn to the right. You don't want to go into any building, just keep going and it's at the end of the path near a wall.",
            date = "2011-01-28T10:56:43-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27460#comments:id=1313137",
        },
        {
            id = 1240554,
            score = 6,
            author = "725088",
            text = "Leads to:\n\nTo Take the Abbey (http://www.wowhead.com/quest=27461)\nTo Take the Barracks (http://www.wowhead.com/quest=27462)",
            date = "2010-12-17T10:22:26-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27460#comments:id=1240554",
        },
        {
            id = 1434968,
            score = 4,
            author = "733706",
            text = "Its just a simple quest where you kill 10 mobs and turn in at the yellow question mark to get follow up quests....right?   Not quite so simple.  As you enter Tyr's Hand and clear the 10 mobs, ones you have cleared will respawn behind and around you.\n\nI found this out the hard way-as a hunter, I naturally try to kite the mobs and make sure I don't back into anything as I keep my distance. To my surprise, as I was backing up, I ran into one I had already cleared!\n\nThe respawn rate is really fast in this area-seems to be more common since Cata.",
            date = "2011-06-05T15:34:13-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27460#comments:id=1434968",
        },
        {
            id = 1530480,
            score = 2,
            author = "885364",
            text = "This quest SUCKS.   I died at least half a dozen times trying to get to the flare.   The mobs come out of nowhere, they swarm you, their aggro range is huge.    I finally got discouraged and just took the rez sickness and took a break, then abandoned it and did something else.     The mobs do drop lots of silver, that's the only good thing about it.\n\nOnly 4600 xp for this quest, not great for this level.   You don't even get a crappy soulbound item.    Don't waste your time on this.   Lots of better quests in east plaguelands.    Try Fiona's caravan.   Now that's a fun series of quests that will get you lots of xp.",
            date = "2011-09-29T01:22:41-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27460#comments:id=1530480",
        },
        {
            id = 1557188,
            score = 2,
            author = "903147",
            text = "ok so the turn in is to the side on the right after the fist little round about looking area. after that its behind the church looking building",
            date = "2011-10-29T23:07:29-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27460#comments:id=1557188",
        },
    },
