    [27465] = {
        {
            id = 2354049,
            score = 15,
            author = "Zaydene",
            text = "Legion pre-patch, https://www.wowhead.com/npc=11034 seems to be gone. Logging out/in and restarting my client didn't fix anything. Other players are reporting that he's gone for them as well. GM just told me to wait for an unknown update because they're \"patching things\"\n\nEDIT:  Currently bugged (http://us.battle.net/wow/en/forum/topic/20747804640?page=1#3)\n\nSECOND EDIT: Still not fixed after \"Patch 7.0.3 Hotfixes - July 20\" where it was claimed to be fixed - the quest before Noxious Glade was fixed in this update, thank you SashaNekosune for pointing this out to me\n\nTHIRD EDIT: Blizzard is aware that Noxious Glade is still bugged (https://twitter.com/WoW_Feral/status/756176979905294336). This quest was not previously fixed in July 20th's update, I made a mistake in reading the patch notes when I tweeted and made my second edit.\n\nFINAL EDIT: FIXED",
            date = "2016-07-20T19:16:40-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27465#comments:id=2354049",
        },
        {
            id = 1799950,
            score = 9,
            author = "359013",
            text = "\"Did you see that Tarenar?\"  \"I can't believe we're fighting for the Argent Crusade!\"\n\nIf you're getting spammed by this, you're not alone.  Unfortunately, https://www.wowhead.com/spell=115080 does not work on this NPC.  I've already tried.  Twice.",
            date = "2013-01-17T07:17:43-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27465#comments:id=1799950",
        },
        {
            id = 1301774,
            score = 5,
            author = "534520",
            text = "The quest text says to return to Light's Hope Chapel if either of the companions is slain (I accidentally got whacked by Garginox), but returning to LHC only gives me back one of the two (the dwarf). I even went all the way into the chapel itself, and none of the NPCs had an option to resurrect or otherwise bring back the other. I talked to every NPC I could find :/\n\nAny ideas?",
            date = "2011-01-20T12:31:55-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27465#comments:id=1301774",
        },
        {
            id = 1482873,
            score = 5,
            author = "359594",
            text = "I did this with a 42 enhancement shaman and got ganked by the giant also.  Once I resurrected and got back to the area I watched his patrol pattern for a minute and realized that he patrols around the cauldron in the middle.  So I focused on the mobs and dead skeletons just around the cauldron, keeping the cauldron between myself and the giant, and had no more problems from him.",
            date = "2011-07-30T02:29:45-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27465#comments:id=1482873",
        },
        {
            id = 1428427,
            score = 4,
            author = "733706",
            text = "The big mob mentioned previously caused serious problems for me in this quest as even though  I made sure to stay away from him he regularly came to where I was and wiped me out.\n\nThen I got killed again after rezzing because there are so many mobs in the area. My \"escorts\" didn't appear after I rezzed and stealth was the only way I could get out of that mess.\n\nWhen I got back to Light's Hope Chapel they returned and we fought our way back to finally complete the quest. I really had to face the big guy (or the direction I had last seen him) while killing the mobs so as to avoid him and get the job done.",
            date = "2011-05-27T01:10:41-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27465#comments:id=1428427",
        },
    },
