    [27469] = {
        {
            id = 1468146,
            score = 42,
            author = "3ICE",
            text = "I did it at level 59 as horde.\n\nSteps:\nDon't forget to strip naked! (To avoid unnecessary repair costs, you perv...)\nRun towards Ragged John\n     Get killed by level 85 guard\nResurrect and continue running\n             Get killed by level 85 guard\nResurrect, continue running and arrive at Ragged John\n                                              Get killed by level 85 guard\nResurrect and try taking the quest as quickly as you can\n                                                  Get killed by level 85 guard\nTry again, now even faster!\n      Get killed by level 85 guard\nUse a quest accept macro ... Success!\n                        Get killed by level 85 guard\nResurrect as far away from Ragged John as possible (40 yards)\n                                                           Get killed by level 85 guard\nResurrect again (80 yards)\n\nCongratulations, you got away successfully. Now go turn in the quest in LBRS, realize it was just a breadcrumb, and bang your head against the wall.\nThen do some research on Wowhead, find (quest=27469) three (quest=27470) similar (quest=27471) quests, one of which is available to horde: A Potential Ally (quest=27470)\nBang head against wall harder.\n\nI might have exaggerated the number of deaths you have to endure, but it was for the comical effect.\n\nMacro: /click GossipTitleButton1\n/click QuestFrameAcceptButton\n\ntl;dr Resurrect on top of quest giver, use macro or addon (e.g.: Carbonite) to accept quest before dying. Or do A Potential Ally (quest=27470) instead.",
            date = "2011-07-12T15:17:58-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27469#comments:id=1468146",
        },
        {
            id = 1207555,
            score = 18,
            author = "446464",
            text = "this quest does NOT count towards Burning Steppes Quests (http://www.wowhead.com/achievement=4901)",
            date = "2010-12-05T05:08:34-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27469#comments:id=1207555",
        },
