    [27512] = {
        {
            id = 1410765,
            score = 13,
            author = "617575",
            text = "Take the path out of the Forsaken camp and turn south. If you look closely on your map, south of the mountain that the quest marker appears in, you'll see a series of small dots. Follow those dots off of the road, through the Dalaran flags, up the mountain, and into the cave entrance.\n\nThere are Level 18 non-elite mobs stationed through the cave, and one Level 18 non-elite that wanders. :)",
            date = "2011-05-05T19:30:39-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27512#comments:id=1410765",
        },
        {
            id = 1202588,
            score = 9,
            author = "avonar",
            text = "Since the entrance on the map looks like it's in the middle of a mountains, here's a tip to get to the entrance.\n\nFrom the Forsaken Front, go south down the road. On your left you'll see a wagon and two Alliance flags, just off the road. In there is the portal.",
