    [27513] = {
        {
            id = 1184140,
            score = 5,
            author = "Corporatus",
            text = "Once you get teleported to the Town Hall you will be shrouded by a pinkish \"dreamglow\", much like the mist you'll get when you enter the Kvaldir areas in Borean Tundra for example.\n\nWhat was odd that when I got teleported it totally screwed up the graphics. Everything was a bit too blurry and looked like the resolution was off a bit. /realod didn't help. The quest was also extremely buggy . The mobs were evading all the time and they had seemingly large aggro range. There was no gimmick for killing the mobs. Just plain 20 mobs kill quest.\n\nThis stood out as the only boring quest I encountered in the new Undead starting area. Fixing the bugs and maybe dropping a few mobs required for the kill would help this quest be on par with the others.",
            date = "2010-11-25T07:44:29-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27513#comments:id=1184140",
        },
        {
            id = 1666716,
            score = 3,
            author = "Vylyss",
            text = "Even at 85 level I aggroed these guys from over 5 yards. Did not expect taking close range screenshots would be so difficult!",
            date = "2012-05-14T03:59:40-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27513#comments:id=1666716",
        },
        {
            id = 1208982,
            score = 2,
            author = "167068",
            text = "Yes, the aggro range was farther than usual, and i'm not talking about being a lower level than them. I was level 18 and i got ganked by three mobs. 1 i attacked, and another came from each side, but they were both far enough away to make me think that i wouldn't aggro them. i died.\n\nvery important side note: If you die while inside of the portal, YOU WILL NOT be able to enter the portal as a ghost. you must res at the gy and suffer res sickness and durability loss. only then can you go back and re-enter the portal.",
            date = "2010-12-05T19:13:31-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27513#comments:id=1208982",
        },
        {
            id = 1680675,
            score = 1,
            author = "silkfire",
            text = "I've had this horrible experience with this quest as well and I think I know what causes it. Well it's a bug of course, but I've found a work around.\n\nBefore entering the portal, change your DirectX in game settings to 9 instead of 11.\nIf you go to the Kvaldir area you will also notice that the cloud effect is back; it actually doesn't work properly with DX 11.\n\nGood luck everyone, hope this helped you.",
            date = "2012-06-24T16:10:17-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27513#comments:id=1680675",
        },
        {
            id = 2135441,
            score = 1,
            author = "1043898",
            text = "Counts towards https://www.wowhead.com/achievement=4894.",
            date = "2015-03-12T05:08:43-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27513#comments:id=2135441",
        },
    },
