    [27522] = {
        {
            id = 1203259,
            score = 22,
            author = "32411",
            text = "Just incase anyone thought the same as I did: As a high level character, you do not have to do slow dps to beat it out of them. You can just one shot them with any spell and the siege engineers will give you the information upon death.",
            date = "2010-12-03T01:10:39-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27522#comments:id=1203259",
        },
        {
            id = 1290872,
            score = 12,
            author = "Hobgoblin",
            text = "I \"found\" Gidwinn's captor here\n\nhttp://www.wowhead.com/maps?data=139:559168\n\nAll I did was go to that spot, then while I was trying to figure out where he was, I killed one more skeleton, then bam I got the quest.",
            date = "2011-01-12T15:59:45-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27522#comments:id=1290872",
        },
        {
            id = 2467619,
            score = 6,
            author = "AySz88",
            text = "This quest has Progress text too, and the skeletons say stuff as you defeat them:\nFiona: I wish I could join you, but I'm not much for fighting. I've protected Gidwin as much as I could... he needs you to protect him now, .\n\nScourge Siege Engineer says: I will tell you nothing, -pig!\nScourge Siege Engineer says: I do not fear death at your hands, !\nScourge Siege Engineer says: The dwarf belongs to our kind now, not yours!\nScourge Siege Engineer says: She will never return the dwarf to you!\n\nScourge Siege Engineer says: The Plaguewood is too big! Your friend is gone! You will never find him!\nScourge Siege Engineer says: Foolish ! You seek the dwarf? Baroness Anastari has hidden him well!\n\n(from Wikia just to avoid re-typing.) (http://wowwiki.wikia.com/wiki/Quest:Beat_it_Out_of_Them)",
            date = "2017-01-27T20:32:28-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27522#comments:id=2467619",
        },
        {
            id = 2558944,
            score = 3,
            author = "Aerynsun8449",
            text = "This is for the programmers. I fail to understand why in quests like this, in a group, each group member must beat different Engineers to get https://www.wowhead.com/npc=45428's location. While multiboxing, on the character that had focus I got his location, didn't think to look at my other character. I went to turn the quest in and discovered the second character still didn't know where he is being held. Really? You don't think people on the same team won't think to talk to their mates? IDK, I'm retired military and I can't think of a single mission I was on that I didn't share important information (such as the location of the person we were looking for) with my team mates.\n\nI can understand if we needed to collect something, such as skulls or toothpicks or whatever. But the location? Each person really needs to find out themselves? It's mind boggling, especially considering quests that share things like https://www.wowhead.com/quest=43445 where only one group member needs to kill all 100 Nightborne.",
            date = "2018-03-21T11:02:19-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27522#comments:id=2558944",
        },
        {
            id = 1184490,
