    [27531] = {
        {
            id = 2490969,
            score = 134,
            author = "gastyne",
            text = "To make the arm glitter instead of glow (making it much easier to spot them)\nGo to System, Graphics, Outline Mode (bottom-right) and disable it.\nI ran around for a long time and only found one, when I disabled outline-mode, I found the other four arms nigh instantly.",
