            sourceUrl = "https://www.wowhead.com/quest=27531#comments:id=2490969",
        },
        {
            id = 1181974,
            score = 44,
            author = "708103",
            text = "[item=61364 domain=www]\nCan be found around in the plaguewood area. Small green bushes with red berries.\n\n[item=61365 domain=www]]\nGlittering arms sticking up from the ground, can be hard to spot, so look carefully.\n\n[item=61366 domain=www]\nCan be found south of Plaguewood as syth stated. Coords: 25.34",
