    [27536] = {
        {
            id = 1192526,
            score = 29,
            author = "mritchey",
            text = "Ford Prefect wrote a lengthy article about the planet Earth after 15 years of painstaking research. The editor's at the Hitchhiker's Guide to the Galaxy determined it was too long and pared it down to\nMostly Harmless.\nThis was quite an improvement over the previous article in The Guide which simply said:\nHarmless\nWhat, if anything, that has to do with this quest is unknown to me.",
            date = "2010-11-28T06:10:38-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27536#comments:id=1192526",
        },
        {
            id = 1597612,
            score = 20,
            author = "Kuroryo",
            text = "This quest is unavailable until one completes the quest \"Maliciously Delicious\" as well.",
            date = "2011-12-17T01:11:54-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27536#comments:id=1597612",
        },
        {
            id = 1808913,
