            text = "Also the name of the fifth and last book of the' Hitchhiker's Guide to the Galaxy' trilogy [sic!]\nIt refers to Earth",
            date = "2010-11-09T14:42:24-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27536#comments:id=1166450",
        },
        {
            id = 1256491,
