            text = "This quest is disappointing. When I saw its name and \"I'm sure they're perfectly safe and disarmed. Every single one. Yup.\" from a friggin goblin, I thought some mines would blow up and deal damage/DoT/knockback. But all 8 mines were safe. Damnit.",
            date = "2010-12-24T10:40:46-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27536#comments:id=1256491",
        },
    },
    [27539] = {
        {
            id = 1204318,
            score = 24,
            author = "80976",
            text = "Kevin: I've been collecting the skulls of the skeletons I defeat. I've amassed a small pile of them.\nPlayer: What pile?\nKevin: If you come across any skulls, you are welcome to add them to my pile. The huge pile of skulls seems to keep the waves of undead at bay and...\nPlayer: It does?\nKevin: Well... it also just makes me happy to look at it.\nPlayer: O...kay... I'll help you make your... skull pile bigger... anything you say Kevin.",
            date = "2010-12-03T14:04:47-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27539#comments:id=1204318",
        },
        {
            id = 1367493,
            score = 20,
            author = "Schpex",
            text = "SKULLS FOR THE SKULL THRONE!\nIt had to be said.",
            date = "2011-03-15T09:47:22-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27539#comments:id=1367493",
        },
        {
            id = 1203285,
            score = 8,
            author = "32411",
            text = "When doing this quest, you will very likely have the quest The Plaguewood Tower (http://www.wowhead.com/quest=27532) in your quest log. I would highly recommend finishing that and then picking up the follow-up quest Counter-Plague Research (http://www.wowhead.com/quest=27531) as both require you to run around the Plaguewoods and it could save you some time to do them together.",
            date = "2010-12-03T01:31:44-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27539#comments:id=1203285",
        },
        {
            id = 1383262,
            score = 7,
            author = "DArcMattr",
            text = "If you're a caster who's on this quest, and you can't dispel a curse, don't bother fighting the https://www.wowhead.com/npc=8524 mobs They slap https://www.wowhead.com/spell=16567 on you on death, a 10 minute debuff that reduces your Intellect by 20%.",
            date = "2011-04-03T16:20:42-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27539#comments:id=1383262",
        },
        {
            id = 2562184,
            score = 5,
            author = "Xoxotl",
            text = "When doing this, do yourself a favor and hunt down the https://www.wowhead.com/npc=8523.  Try to avoid aggroing https://www.wowhead.com/npc=8524 if you can help it, especially if you are a spell-caster.  Upon death, https://www.wowhead.com/npc=8524 casts https://www.wowhead.com/spell=16567 which is instant and unavoidable.\n\nhttps://www.wowhead.com/spell=16567 is a 10-minute debuff that reduces any spell-casting (damage and healing) by 20%.",
            date = "2018-04-10T03:06:51-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27539#comments:id=2562184",
        },
    },
    [27542] = {
        {
            id = 1283073,
            score = 66,
            author = "47151",
            text = "If you can't see the NPCs to give you the followup quests, do the following:\n\nDismount.\n\nThat is all.",
            date = "2011-01-07T22:16:12-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27542#comments:id=1283073",
        },
        {
            id = 1198188,
            score = 2,
            author = "714329",
            text = "I used my mount to run into the city, and saw another player walking around with the quest NPCs.\n\nSo you can either grab the quests from someone else wandering around, or you can dismount and the NPCs will spawn for your character.\n\nThis one had me puzzled for a bit as well.",
            date = "2010-11-30T15:21:50-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27542#comments:id=1198188",
        },
        {
            id = 1189318,
            score = 1,
            author = "710352",
            text = "Same thing happened to me, but without being mounted. One solution to the problem seems to be to die. Then when you resurrect, the questgivers will spawn.",
            date = "2010-11-27T01:41:18-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27542#comments:id=1189318",
        },
        {
