    [27547] = {
        {
            id = 1263886,
            score = 41,
            author = "525656",
            text = "Yeah it was kind of funny how sadistic this quest was. The best coincidental dialogue I came across was actually my final \"rescue\":\n\nCowering Trooper says: Is it safe?\nLord Godfrey pulls out his rifle and shoots.\nLord Godfrey says: He died in battle. Bow your heads...\n\nI cackled at that.",
            date = "2010-12-28T11:02:13-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27547#comments:id=1263886",
        },
        {
            id = 1220763,
            score = 17,
            author = "503968",
            text = "\"He died in battle.\n\nBow your head.\"",
            date = "2010-12-10T04:09:42-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27547#comments:id=1220763",
        },
        {
            id = 1348824,
            score = 17,
            author = "slamb1",
            text = "I was running through the quests in Silverpine on my 54 hunter. When I got to this one, there were no quest givers anywhere near me, nothing in the area of Sylvanas. But when I talked to the flight master (was going to fly to Undercity for stuff to do), the trio suddenly appeared. Just an FYI if it might help someone.",
            date = "2011-02-24T17:28:12-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27547#comments:id=1348824",
        },
        {
            id = 1429663,
            score = 17,
            author = "Liri",
            text = "Cowering Trooper says: They struck from the shadows. We didn't stand a chance.\nLord Godfrey says: These cowering troopers should die in shame. This is an embarassment.\nCowering Trooper says: Is it safe?\nLord Godfrey says: The Dark Lady lets these mongrels live? Useless...\nCowering Trooper says: They're EVERYWHERE! WATCH OUT!\n\n19:09:35 Lord Godfrey says: He died in battle. Bow your heads...\nCowering Trooper says: They struck from the shadows. We didn't stand a chance.\nLord Godfrey says: Get out of my sight before I execute you!\nCowering Trooper says: They struck from the shadows. We didn't stand a chance.\n\nLord Godfrey says: This is a mercy killing.\nCowering Trooper says: I thought I was done for!\nLord Godfrey says: The Dark Lady lets these mongrels live? Useless...\nCowering Trooper says: Are... are they all dead?\nLord Godfrey says: Get out of my sight before I execute you!\nCowering Trooper says: You must be the hero that everyone is talking about. Thank you.\n\nLord Godfrey says: She died in battle. Bow your heads...\n\nEspecially the last makes me hope I get to kill him.",
            date = "2011-05-28T21:21:17-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27547#comments:id=1429663",
        },
        {
            id = 1183430,
            score = 11,
            author = "TheBob",
            text = "This quest is quite hilarious, depending on how sadistic you are.\n\nYou see, the trio following you doesn't really approve of fellow soldiers cowering, so about half the time you talk to a survivor, they'll promptly aim a pistol and shoot said survivor in the head.",
            date = "2010-11-25T01:00:37-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27547#comments:id=1183430",
        },
    },
    [27548] = {
        {
            id = 1225378,
            score = 9,
            author = "anhsieh",
            text = "How odd that Lord Walden indicates that only Humans are able to be reanimated as Forsaken. Actually, I had never really thought about it until now-- why is it that the only non-Human Undead are Death Knights? How useful is magical reanimation if it only works on Humans?\n\nIn WarCraft III, Raise Dead worked for any and all corpses. Perhaps Skeletons, though, aren't considered part of the Scourge? Or Forsaken?",
            date = "2010-12-11T17:16:13-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27548#comments:id=1225378",
        },
        {
            id = 2623176,
            score = 5,
            author = "Melllvar",
            text = "As of patch 8.1 Val'kyr can resurrect night elves, no questions asked, resulting in forsaken night elves fighting there old allies.\n\nWhat an insulting and obvious retcon, thanks blizz.",
            date = "2018-10-13T05:41:33-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27548#comments:id=2623176",
        },
        {
            id = 2590504,
            score = 3,
            author = "Bombkirby",
            text = "The mobs you have to kill are stealthed. If you don't see any, search the outside of buildings and the nearby woods for them.",
            date = "2018-08-10T13:45:11-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27548#comments:id=2590504",
        },
        {
            id = 2472539,
            score = 1,
