    [27569] = {
        {
            id = 1635873,
            score = 26,
            author = "958438",
            text = "The Lock is in the first floor where you will see huge wheels hanging from the wall, just below them, on the floor you will see a sort of command center, press the middle of it and wheels will start to turn and will unlock the door in the upper floor between the east and the west, took me a lot of time to find this out, as usual be accident,",
            date = "2012-03-06T14:43:37-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27569#comments:id=1635873",
        },
        {
            id = 1992381,
            score = 10,
            author = "865143",
            text = "When are you supposed to do this quest? Everyone leaves after Interrogator when you queue for BRD-Detention Block and that boss signifies the \"end\" of that dungeon so you can't get more members through LFG, and Upper City queue puts you well past it. I'm having a hard time figuring out exactly WHEN this quest is supposed to be done.",
            date = "2014-08-16T14:19:36-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27569#comments:id=1992381",
        },
        {
            id = 1184083,
            score = 9,
            author = "ZeGaL",
            text = "She is to the Right Befour you enter The \"BAR\" Arena, with all the Dwarf are,",
            date = "2010-11-25T07:06:44-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27569#comments:id=1184083",
        },
        {
            id = 1881693,
            score = 8,
            author = "Schnoodledorfer",
            text = "The quest text doesn't really explain the purpose of the \"Shadowforge Lock\" in the design of the dungeon. The lock is on a huge overhead wheel and holds a door open. (To find the lock, look for the wheel inside the garrison -- see screenshot (http://wow.zamimg.com/uploads/screenshots/normal/376164.jpg).) The wheel is connected, via a chain, to one of the massive doors across the Dark Iron Highway. Clicking on the Shadowforge Lock lowers the locking mechanism, and that allows the wheel to spin and the chain to move and the door to close. Having both doors closed would stop any invaders who tried to enter Shadowforge City via the Dark Iron Highway. Also, with the doors closed, passageways running lengthwise inside the doors would align with each other and with ones in the surrounding rock walls. Defenders could then use these passageways to cross as needed between the East and West Garrisons. They also could shoot down from windows and platforms along the passageway at any invaders that were attacking the doors. You can look out of the windows and see the highway below from inside the doors.\n\nWhen you first enter the instance, the western door is already closed, but the eastern door is partially open, so the passageways don't line up. If you try going down the passageway, you are blocked at the door hinge. You can look through a gap there, but you can't get inside the door until you unlock the wheel and the door closes and the passages line up better. If you go down to the highway first and look up at the other edge of the door (or look carefully at the dungeon loading screen), you can clearly see (http://wow.zamimg.com/uploads/screenshots/normal/376168.jpg) the other end of the passageway inside the door. You can also see the windows in the garrisons and the defensive platforms on the doors while you are down there.\n\nOnce the door is closed, you can cross the highway and reach the West Garrison and the parts of the dungeon beyond it (including the Grim Guzzler) but you won't be able to walk up the Dark Iron Highway to the Dark Anvil or https://www.wowhead.com/npc=9017 anymore. They can still be reached by going down through Shadowforge City or jumping down, though.\n\nPersonally, I think the locking mechanism and doors are neat features and I think it's a shame that many players don't appreciate what the instance designers hoped to convey with them. BTW, https://www.wowhead.com/quest=27585 is the equivalent quest for Horde players.",
            date = "2013-07-28T14:08:04-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27569#comments:id=1881693",
        },
        {
            id = 1679331,
            score = 2,
            author = "1001857",
            text = "The unlock mechanism is on the SECOND floor - East Garrison - (41,88) --- just below two large gears.",
            date = "2012-06-21T18:38:08-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27569#comments:id=1679331",
        },
    },
    [27571] = {
        {
            id = 1883955,
            score = 42,
            author = "Thebe2",
            text = "to get there on foot: from the instance entrance go thru the first gate on your left, then the next gate\\door on your right. Take the door to the East Garrison on your left by Prospector Seymour. Straight ahead left of the stairs turn on the gear to open the upper door to Shadowforge City . Go back and go up the stairs. At the top of the first flight, turn left and go between 2 groups of Fireguards and follow that hall around to the left where you will see the door you opened with the gear take that corridor to the West Garrison and stay to the left. Go down the stairs to the right into the Manufactory. Turn right after the 3rd set of pillars lining this hallway. Take that doorway to a bridge back to Shadowforge City, thru that door and you are there.",
            date = "2013-08-04T15:21:20-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27571#comments:id=1883955",
        },
        {
            id = 1979934,
            score = 16,
            author = "176962",
            text = "[npc=9537 domain=www] will spawn when you break 3 barrels located in a small room off of the lower level of the Grim Guzzler.  He has friends.\n\n[npc=9499 domain=www] is on the upper level of the Grim Guzzler.  Before you kill him, buy 6 ale if you want to open the back door, sell off anything you want, buy stuff, including patterns.\n\n [npc=9543 domain=www] is on the lower level of the Grim Guzzler.  He is surrounded by friends.  Speak to him to get him from friendly to, well, not friendly at all.",
            date = "2014-07-12T09:13:50-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27571#comments:id=1979934",
        },
