    [27574] = {
        {
            id = 1179847,
            score = 18,
            author = "707413",
            text = "If you're like me, you probably skipped killing the crocs along the way due to the awesomeness of the story line or was distracted by something else and chose not to fight them. This, however is a mistake. If you finish the storyline quest progression for Silverpine Forest w/o getting this item AND turning it in w/ the finished quest it gives, you'll be out of luck for the 60/60 quests completed achievement and locked out of getting the Loremaster as well.\n\nI currently have a ticket in for this and will report back on it.\n\nUpdate: My darling wife just finished Silverpine with 3 quests to spare and got the achievement. Going to compare her list to mine and see what I missed.",
            date = "2010-11-24T01:14:54-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27574#comments:id=1179847",
        },
        {
            id = 1675390,
            score = 16,
            author = "jtbalogh",
            text = "It is too late to do this quest if you turned in the quest Sowing Discord (http://www.wowhead.com/quest=27580) and never got the head. Killing the crocs was useless now. Grouping with someone else that had Lord Godfrey also did not help, because only they were able to loot the quest item, not me. The quest can not be shared and the crocs drop the quest item only for the person that is able to summon godfrey. Lord Godfrey had to be *my* companion to finish the quest line with, I Never Forget a Face (http://www.wowhead.com/quest=27574), and From the Belly of the Beast (http://www.wowhead.com/quest=27575).\n\nThe problem is worse if you turned in Cities in Dust (http://www.wowhead.com/quest=27601) and never got the head, because the zone phases out the mobs in the area. No crocs are seen to even kill and get the head.",
            date = "2012-06-10T21:24:34-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27574#comments:id=1675390",
        },
        {
            id = 2330845,
            score = 13,
            author = "r3fund",
            text = "You basically have to do the whole Silverpine quest line, ultimately going to Gilneas to rez Godfrey in https://www.wowhead.com/quest=27406, and finally being on the https://www.wowhead.com/quest=27550 quest with Godfrey by your side.",
            date = "2016-05-14T09:23:16-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27574#comments:id=2330845",
        },
        {
            id = 3237705,
            score = 13,
            author = "Dahustler",
            text = "1 day before Shadowlands prepatch and the GM sent me to this URL https://eu.battle.net/support/en/article/000271364\n which reports this information:\n\nThe two quests \"I Never Forget a Face\" and \"From the Belly of the Beast\" are optional quests, and they are only available just before the end of the Silverpine Forest questline.\nOnce you complete the entire zone (ending with \"Empire of Dirt\"), you'll be locked out of those optional quests.\n\nIf this happens, you'll have two options:\n    You can use another character to go through Silverpine Forest and complete the quest.\nor\n    You can group up with a friend who's on the questline and use the Party Sync feature to complete it with them.\n\nSo basically, we are fu*ked.",
            date = "2020-10-13T12:14:38-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27574#comments:id=3237705",
        },
        {
            id = 1179333,
            score = 10,
            author = "Gesikafree",
            text = "do this quest while you still have Lord Godfrey as your follower.  Around the time you're doing this quest since you're right by the crocs http://www.wowhead.com/quest=27577.",
            date = "2010-11-23T21:42:30-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27574#comments:id=1179333",
        },
    },
