    [27577] = {
        {
            id = 1203773,
            score = 13,
            author = "151462",
            text = "Look for an elite dwarf to drop the plans. (I found her over by the marshy area full of crocs.) You can find others in the camp with General Marstone.\n\n(His repop rate is pretty high, btw. Don't worry if you wander by just as he's being killed.)\n\nWhen you're wandering by the marsh crocolisks, don't forget to pop one. It should drop a head that begins a new quest.\n\nOnly the Forsaken would send you killin' crocs for people parts. I feel like Dr. Frankenfurter.\n\nMmm giblets.",
            date = "2010-12-03T08:49:54-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27577#comments:id=1203773",
        },
        {
            id = 1828112,
            score = 6,
            author = "JezebelJay",
            text = "Many elite mobs in the area. I died 3 times before I realised I could target one (a few come rushing in to help). then , let Gregory et al deal with them while you run off to safety. They will kill them. You may have problems with Marstone, he respawns quickly.\n\nAs previously mentioned, one of the dwarven infantry will drop the plans eventually, but it's very doable, and very enjoyable. I think Forsaken warlock has to be my favourite all-time character.",
            date = "2013-03-13T15:50:23-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27577#comments:id=1828112",
        },
        {
            id = 2867585,
            score = 4,
            author = "Aszun",
            text = "Tried to do this quest on a lvl 46 arms warrior. I had 3.2k HP, and the healer NPC that follows you only heals for 100. General Marstone hits me for over 1k with stormstrike, which he uses frequently. Unfortunately as it is, it was impossible for me to finish this quest even with full heirlooms, enchants, and potions.",
            date = "2019-01-22T20:00:32-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27577#comments:id=2867585",
