    [27585] = {
        {
            id = 1881520,
            score = 21,
            author = "Schnoodledorfer",
            text = "The quest text doesn't really explain the purpose of the \"Shadowforge Lock\" in the design of the dungeon. The lock is the locking mechanism on a huge wheel. (To find the lock, look for the overhead wheel inside the garrison -- see screenshot (http://wow.zamimg.com/uploads/screenshots/normal/376164.jpg).) The wheel is apparently connected, via a chain, to one of two massive doors across the Dark Iron Highway. Activating the Shadowforge Lock lowers it, allowing the wheel to spin and the door to close. Having both doors closed would stop any invaders trying to enter Shadowforge City via the Dark Iron Highway. Also, passageways built inside the doors would align with each other and with ones in the surrounding rock walls. Defenders could then use these passageways to cross as needed between the East and West Garrisons. They also could shoot down from windows and platforms along the passageways at any invaders that were attacking the doors.\n\nWhen you first enter the instance, the eastern door is partially open so the passageways don't line up. As a result, you you can only get as far as the upper door hinge on the east side. You can look through a gap there, but you can't get inside the door until you unlock the wheel and the door closes. If you go down to the highway first and look up at the other edge of the door (or look carefully at the dungeon loading screen), you can clearly see (http://wow.zamimg.com/uploads/screenshots/normal/376168.jpg) the other end of the passageway through the east door. You can also see the windows in the garrisons and the defensive platforms on the doors from the highway.\n\nOnce the east door is closed, you can cross the highway and reach the West Garrison and the parts of the dungeon beyond it (including the Grim Guzzler) but you won't be able to walk up the Dark Iron Highway to the Dark Anvil or https://www.wowhead.com/npc=9017 anymore. They can still be reached by going down through Shadowforge City or jumping down, though.\n\nPersonally, I think the locking mechanism and doors are a neat features and I think it's a shame that so few players appreciate what the instance designers hoped to convey with them. BTW, https://www.wowhead.com/quest=27569 is the equivalent quest for Alliance players.",
            date = "2013-07-28T03:00:52-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27585#comments:id=1881520",
        },
        {
            id = 1355773,
            score = 17,
            author = "625429",
            text = "Hierophant turn in is a bit tricky. Just hiding just off to the right hand side in her own alcove precisely at the entrance to the Grim Guzzler. Once you cross the bridge from the Manufactory, she is just before the ramp that leads into the bar proper.",
            date = "2011-03-03T00:37:04-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27585#comments:id=1355773",
        },
        {
            id = 1499837,
            score = 12,
            author = "tridentaddict",
            text = "Can't get to the west garrison through the corridor that links it to the east garrison. There's a door that's blocking it part ways - anyone know how this opens up?",
            date = "2011-08-21T03:42:32-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27585#comments:id=1499837",
        },
        {
            id = 1196119,
            score = 5,
            author = "Draconax",
            text = "Take notice that this quest is *not* handed in back at the start, but across the bridge before the Grim Guzzler, to a different NPC.  Took my group a while to notice that the first time we ran it.",
            date = "2010-11-29T16:54:17-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27585#comments:id=1196119",
        },
        {
            id = 1766340,
            score = 5,
