            text = "The Shadowforge Lock is located on the north side of the room, down the stairs: is marked \"East Garrison\" and no longer requires a key.\n\nCoordinates for Shadowforge Lock in Shadowforge City are 41,87",
            date = "2012-11-22T14:45:24-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27585#comments:id=1766340",
        },
    },
    [27587] = {
        {
            id = 1199749,
            score = 8,
            author = "124958",
            text = "Be aware that the underwater walking potion you get (Silversnap Swim Tonic) only works within Swamp of Sorrows. If you cross the border while underwater into Redridge Mountains you end up losing the potion buff.",
            date = "2010-12-01T07:52:41-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27587#comments:id=1199749",
        },
        {
            id = 1190467,
            score = 5,
            author = "Schadow",
            text = "This quest is in Swamp of Sorrows in Bogpaddle and you get it from Trade Baron Silversnap.\n\nYou can combine this with Drinks on the Rocks, which you get in the same town from Brono Goodgroove on the beach.\n\nYou get with this quest the potion Silversnap Swim Tonic, a one-time use, that allows you to breathe and let's you walk (!) in the water 60% faster (Note: walk, not swim). You can mount underwater and the speed increase stays in effect. As soon as you go swim, you swim normally.\n\nThe effect is for 15 minutes, more then you need. Drinks on the Rocks has a 100% droprate, Maliciously Delicious around 40-50%. If you do need more, you can ask for another one from Trade Baron Silversnap. It does not give Steamwheedle Cartel/Booty Bay rep.\n\nEdit: added town's name.",
            date = "2010-11-27T12:55:46-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27587#comments:id=1190467",
        },
        {
            id = 1303602,
            score = 5,
            author = "Earthproxy",
            text = "Name could be a loose spin of Lucky Charms, \"Magically Delicious!\"",
            date = "2011-01-21T21:53:40-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27587#comments:id=1303602",
        },
        {
            id = 1306377,
            score = 2,
            author = "snub999",
            text = "Definitely DEFINITELY don't forget that he gives you a water walking/swim speed potion.  Speeds up this quest and Drinks on the Rocks (http://www.wowhead.com/quest=27592) tremendously.  You get the drink quest on the beach.",
            date = "2011-01-23T14:47:46-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27587#comments:id=1306377",
        },
        {
            id = 1631736,
            score = 2,
            author = "14690",
            text = "Low drop rate, mobs flee when low on health, annoying underwater combat, plenty of aggro from the frenzy fish, mobs scattered over a wide area, sometimes plenty of competition.. all equals a real pest of a quest.",
            date = "2012-02-25T21:31:47-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27587#comments:id=1631736",
        },
    },
    [27589] = {
        {
            id = 1638001,
            score = 35,
            author = "Cordana",
            text = "Alright this is oldskool for you youngins out there:\n\nYou'll see Ribbly right in front of you when you walk in... talk to him to pick a fight and kill him.\nSummon Hurley by destroying the brew barrels in the room next door (same room as brewfest boss, or coming up from the entrance, the empty room to your left)... click on the three barrels to break them open and he'll come running in with his crew.\nPlugger is on the level above walking on the bar table... next to are two tables with stuff you can pickup.  Pickup the stuff and Pluggy wants to fight.\n\nOh, and after you kill Plugger the patrons of the bar have a nice surprise for you. You'll turn in the quest outside the bar if you keep turning left.",
            date = "2012-03-10T22:43:16-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27589#comments:id=1638001",
        },
        {
            id = 1940676,
            score = 3,
            author = "1070257",
            text = "I recommend checking out https://www.wowhead.com/npc=9499's wares before you steal stuff off his tables and kill him. He sells https://www.wowhead.com/item=11325 which is needed for https://www.wowhead.com/quest=7946, and some other goodies as well. Rogues have a good chance of pickpocketing a key to the joint. Have fun... kill and swill.",
            date = "2014-02-04T13:10:08-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27589#comments:id=1940676",
        },
        {
            id = 1680296,
            score = 2,
            author = "royalite",
            text = "In LFD, we had someone summon Hurley and pick a fight with Ribbly.  Resulting in a party wipe.  We couldn't re-summon Hurley.  So careful when pulling these guys.",
            date = "2012-06-23T17:56:46-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27589#comments:id=1680296",
        },
        {
            id = 1682344,
