    [27593] = {
        {
            id = 1265263,
            score = 14,
            author = "748624",
            text = "Make sure you turn this quest in during the same run that you kill the Emperor, as it is near impossible to return and turn in the quest alone since the questgiver is behind a locked door which requires that you defeat all seven dwarves of the Summoner's Tomb to open.",
            date = "2010-12-29T02:57:58-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27593#comments:id=1265263",
        },
        {
            id = 1591668,
            score = 9,
            author = "456634",
            text = "Can't figure out where the Torches come from. No named mob is listed as a Flamekeeper. Near as I can tell it's the Fireguard Destroyers on the brazier platforms and down at the Molten Bridge, but no torches seem to be dropping. Hmm...\n\nEdit: So to answer my Own Question The Shadowforge Torch (http://www.wowhead.com/item=11885#comments) is dropped by the Shadowforge Flamekeepers (http://www.wowhead.com/npc=9956#.) mobs who are mixed in with the bazillion and a half Dwarven Infantry who populate the Lyceum. Basically. Run around killing or trying to avoid infantry troops till you find them. Kill Two Shadowforge Flamekeepers (http://www.wowhead.com/npc=9956#.). Get a torch from each, and light the braziers on the platforms to the left and right of the big iron door (R-Click each brazier, as long as you have a torch unused, it'll ignite the Brazier). The Doors open without any sound or fanfare, so once the Braziers are lit, just go on through. Beyond is a court with plenty of courtiers to kill, a Captain or two, and finally the King and his Dwarven Queen who \"appears visibly shaken\" by his death (once you kill him), but who otherwise failed to interact with me even though she was green to me (Horde) throughout the fighting. Eventually she despawned after the king had been dead a while. Turn in Quest where you got it back on the other side of The Lyceum at the top of the entry ramp.",
            date = "2011-12-06T23:46:35-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27593#comments:id=1591668",
        },
        {
            id = 1258462,
            score = 2,
            author = "485531",
            text = "I love how this dungeon is timewarped since a dwarf rolled post Cata would have been told of Dagran's death long before coming here.",
            date = "2010-12-25T15:39:39-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27593#comments:id=1258462",
        },
        {
            id = 1430629,
            score = 2,
            author = "Kuja",
            text = "Flawed quest. You have to run past LOADS of dwarves if you want to complete this quest, and you're usually the only one that wants to return it :/ No bursty aoe or self heals, you're pretty much abandoning the quest unless others in your group have the quest aswell.",
            date = "2011-05-30T07:47:32-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27593#comments:id=1430629",
        },
        {
            id = 6068614,
            score = 1,
            author = "silkfire",
            text = "K.E.F. stands for Kargath Expeditionary Force.",
            date = "2025-02-24T03:58:57-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27593#comments:id=6068614",
        },
    },
    [27594] = {
        {
            id = 2550276,
            score = 37,
            author = "AtlasConclave",
            text = "Quick update on this quest - it's still a little buggy, you do not 'collect' Lorna unless she goes down within a few yards of her starting position and she's attacking one of your NPC followers; Iet Ashbury and Walden keep aggro on her for the fight, with the 7.3.5 changes to scaling, this makes for a pretty long fight - just wait it out and it triggers properly.",
            date = "2018-02-03T08:22:02-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27594#comments:id=2550276",
        },
        {
            id = 3120258,
            score = 13,
            author = "labhaoise",
            text = "Blizzard really need to sort the scaling out on this quest. I've failed for the last 2 hours to kill her as a fire mage decked in heirlooms . Her and the worgen should not be elites at this level",
            date = "2019-04-25T05:51:21-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27594#comments:id=3120258",
        },
        {
            id = 1114308,
            score = 7,
            author = "darknesscalls",
            text = "The quest name is in reference to the Bond film of the same name",
            date = "2010-09-05T19:32:18-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27594#comments:id=1114308",
        },
        {
            id = 3243606,
            score = 7,
            author = "ayokayy",
            text = "If you're here from the Reddit speedrunning guide - this quest is extremely buggy and seems to break any time anyone zones in near her. It's very sketchy and almost not worth the effort.",
            date = "2020-10-29T21:30:03-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27594#comments:id=3243606",
        },
        {
            id = 1704357,
            score = 6,
            author = "478970",
            text = "Be very careful while running - if you accidentally cross over the greymane wall, your \"helpers\" (Baron Ashbury, Lord Walden, and Godfrey) will disappear.  Running back into Silverpine Forest territory does not make them re-appear, and if you approach Lorna she will simply stare at you, and is not attack-able. Abandoning the quest and running back to the Forsaken Front will also make them not re-appear.  Reloading UI and logging out also do not make them re-appear.  As of this moment, I cannot locate them anywhere and sadly, am unable to re-obtain the quest.  Will update this post if I am able to find them again.\n\nEdit - after opening a ticket, I frustratedly ran to the flight path guy and flew on to Hillsbrad, as that was my next questing hub.  As soon as I was in flight, I saw them reappear below me on the ground with a quest icon above their heads. I flew back and was able to accept and successfully complete the quest for my first ring!  Woohoo!",
            date = "2012-08-25T19:14:02-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27594#comments:id=1704357",
        },
    },
    [27596] = {
        {
            id = 1870675,
            score = 59,
            author = "lhug",
            text = "You need 12 Relic coffer keys to get this Item. Loot those from the arena spectators and the dwarves within the prison block. Should easily yield 12 or more.\n\nDO NOT leave the instance under any circumstance, your keys will be lost.\n\nShould you have trouble finding the room, go back to the entrance, enter the mole machine and go to the domicile. Exit the room, turn right and right again, down the ramp, through the door and you should be on a platform with a nice view of the shadowforge. Follow the platform and look to the first door on your right.\n\nIn there are a group of mobs, and in the room behind that two bosses (a guard and his dog) and several golems. That is where you need to go.\n\nYou do NOT need to kill the Dark Keeper. It is entirely optional.",
            date = "2013-06-25T19:11:22-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27596#comments:id=1870675",
        },
        {
            id = 1261238,
            score = 47,
            author = "168809",
            text = "Just completed this, you only need 12 Relic Coffer Keys (http://www.wowhead.com/item=11078) to open the 12 Relic Coffers (http://www.wowhead.com/?object=160836).\n\nThis leads to Watchman Doomgrip (http://www.wowhead.com/npc=9476) spawning, when he dies a small chest and The Heart of the Mountain (http://www.wowhead.com/object=165554) appear below the Dark Coffer.",
            date = "2010-12-27T03:21:30-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27596#comments:id=1261238",
        },
        {
            id = 1345228,
            score = 46,
            author = "358692",
            text = "Quite surprised nobody has mentioned this yet, but this is probably a reference to the Arkenstone from J.R.R. Tolkien's The Hobbit. It was also known as the Heart of the Mountain, and was uncovered from Erebor, the Lonely Mountain. The only difference is that the Arkenstone was white, not red.",
            date = "2011-02-21T19:05:34-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27596#comments:id=1345228",
        },
        {
            id = 1592095,
            score = 30,
            author = "494629",
            text = "As of 4.3, you will need all of the keys again to open the vaults and get the Heart of the Mountain.  Blizzard has fixed the exploit allowing you to loot through the walls, making it necessary to do things the right way again.",
            date = "2011-12-07T15:20:39-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27596#comments:id=1592095",
        },
        {
            id = 1982304,
            score = 27,
            author = "807801",
            text = "\"Do you have the Heart of the Mountain?  To me, its value is without limit. \"\n\"Please, take this as payment! \"\n\nWell... that was generous!",
            date = "2014-07-19T21:51:32-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27596#comments:id=1982304",
        },
    },
