    [27612] = {
        {
            id = 1206912,
            score = 32,
            author = "667471",
            text = "In order to unlock \"Victory from Within\" you must first complete:\n\nThe Brotherhood of Light\nSoft Landing\nTo Take the Abbey\n\nThe quest \"To Take the Barracks\" is required to unlock:\nScarlet Salvage\nThe Wrathcaster\nThe Huntsman\nThe Commander\n\nOn my level 39 I completed these three first, before this chain would unlock.\n-ooch-",
            date = "2010-12-04T21:08:38-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27612#comments:id=1206912",
        },
        {
            id = 1117276,
            score = 19,
            author = "ArashikageClan",
            text = "It would seem that this entire questline has you killing all the old scarlet crusade npcs that used to be at Light's Hope Chapel. That is, all the npcs that you could turn Naxx 40 tokens into for pieces of Tier 3.\n\nKind of sad, seems that tier 3 will continue to be a gap in the tier line unless Blizzard adds some other way for players to get it.",
            date = "2010-09-10T00:18:59-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27612#comments:id=1117276",
        },
        {
            id = 1191567,
            score = 17,
            author = "433572",
            text = "I can't see the portal in the Library...I smell a bug.",
            date = "2010-11-27T20:43:28-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27612#comments:id=1191567",
        },
        {
            id = 1366356,
            score = 9,
            author = "292346",
            text = "Despite the quest text indicating that you would be using a \"keystone\", the portals are merely just executable. I have no idea if this is intentional or a difference between an earlier version of the quest and later, but there's no actual item needed for the portals.",
            date = "2011-03-14T01:57:54-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27612#comments:id=1366356",
        },
        {
            id = 1684870,
            score = 7,
            author = "LazyFansu",
            text = "You'd think that after opening the portals, the Argent Crusaders pouring through them would give you a hand clearing up the mobs. Alas, this is not the case, so don't do what I did and run straight for the portals and tailing all the mobs in the abbey in the process. Learn from my mistake!",
            date = "2012-07-05T16:12:48-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27612#comments:id=1684870",
        },
    },
    [27613] = {
        {
            id = 1191291,
            score = 89,
            author = "268219",
            text = "Go in the Abbey and turn right, after a second or two you'll come to a round-topped arched entrance and thru it a long flight of stairs.  Go up the stairs and just keep going til you get to a room with a big wooden platform in the middle.  He's in there stealthed.",
            date = "2010-11-27T18:40:42-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27613#comments:id=1191291",
        },
        {
            id = 1186256,
            score = 23,
            author = "dlbert2000",
            text = "Hes up in the bell tower, behind the pedestal, in stealth mode so you cant see his name or healthbar.",
            date = "2010-11-25T23:31:05-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27613#comments:id=1186256",
        },
        {
            id = 1285927,
            score = 19,
            author = "752459",
            text = "Like the other posts say go into the Abbey right near where you got the quest. Turn right, then up the stairs that have a rounded top. It will tell you you're in the Hand Abbey. Go up all the stairs (they are spirals stairs) until you see the wooden platform with stairs that go up to the platform. On minimap you should see the boss skull indicator. Rohan is crouched BEHIND the wooden platform, stealth-mode. I walked right up to him and he didn't aggro, so I had to attack first.",
            date = "2011-01-09T13:55:46-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27613#comments:id=1285927",
        },
        {
            id = 1415385,
            score = 8,
            author = "292744",
            text = "Noo, I don't want to have to kill this guy. He was my favorite back in vanilla.\n\nStill, I like what blizz did here. Getting to see all of these Scarlet goons in their undead versions, and then getting to KILL them, was quite fun. Good job, Blizzard!",
            date = "2011-05-10T22:03:15-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27613#comments:id=1415385",
        },
        {
            id = 1248597,
            score = 4,
            author = "718694",
            text = "I was about to run back out, until I decided I'll run around the platform... found the guy to the left, stealthed as someone else mentioned... good part is he doesn't aggro that easily! I nearly walked right on top of him and I didn't aggro him... good note for the clothies!",
            date = "2010-12-20T18:33:41-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27613#comments:id=1248597",
        },
    },
    [27614] = {
        {
            id = 1207432,
            score = 39,
            author = "kumalo",
            text = "Basically, the four corner rooms of the first floor.",
            date = "2010-12-05T03:31:05-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27614#comments:id=1207432",
        },
        {
            id = 1251931,
            score = 23,
            author = "228364",
            text = "This quest should be unobtainable as Forsaken. How do they expect you to go and return the holy artifacts when you are undead yourself?",
            date = "2010-12-22T06:58:42-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27614#comments:id=1251931",
        },
        {
            id = 1186339,
            score = 13,
            author = "150104",
            text = "Some observations that might help you to find them\n\nEach artifact is in a ground level room as you enter the barracks.\n\nAll 4 artifact chests look exactly the same.\n\nEach Room that has an Artifact chest is guarded by 1 -- 2 Scarlet Warders.\n\nMost of the Chests are near the back wall or in a corner area of the room.",
            date = "2010-11-26T00:17:22-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27614#comments:id=1186339",
        },
        {
            id = 1444896,
            score = 9,
            author = "Deathbang",
            text = "Doing this on a Death Knight or Forsaken toon gives additional rewards. Since as the quest states undead hands cannot touch the objects, you can then sue the Crusade for discrimination by assigning you a painful task they knew you could not complete!\n\nNote: This is a joke. Do not expect actual additional rewards, besides getting to giggle at the contradictions of this quest.",
            date = "2011-06-19T11:33:16-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27614#comments:id=1444896",
        },
        {
            id = 2426105,
            score = 7,
            author = "Enderverse",
            text = "Uther (http://wow.gamepedia.com/Uther_the_Lightbringer) was the first paladin on Azeroth ever. Killed by Arthas, his protege, during the fall of Lordaeron (in WC3).\nGavinrad  (http://wow.gamepedia.com/Gavinrad) was also one of the first of five paladins. You also kill him as Arthas in WC3.\nI don't know the significance of Lihanna's Shroud or the Crimson Boar however. Probably just random lore.",
            date = "2016-10-11T08:27:40-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27614#comments:id=2426105",
        },
    },
    [27615] = {
        {
            id = 1353449,
            score = 42,
            author = "691812",
            text = "Previous directions are a bit off. You go in, turn right and then turn LEFT towards the sleeping area with the bunk beds and LEFT again. The entrance to the basement is just through the archway. It is a bit dark and hard to see. If you get to the stairs you have gone too far.\n\nOr another way of explaining it, is if you are standing facing the stairway to the second floor the entry to the basement is on your right just inside the arch that heads back to the area with the beds.",
            date = "2011-02-28T18:10:32-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27615#comments:id=1353449",
        },
        {
            id = 1361639,
            score = 8,
            author = "716234",
            text = "It really helped to know there was a basement to find him.  If you dont get all the turns right, just look to the right of the room with the green carpet.  It is basically under the stairs going up to 2nd floor. Look to the left of the arched doorway to the next walkway before you go thru.",
            date = "2011-03-08T19:32:15-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27615#comments:id=1361639",
        },
        {
            id = 1260583,
            score = 7,
            author = "746177",
            text = "go inside, turn right, turn right again facing the sleeping area, turn left were u are at centre of house (before the sleeping area)  just after the arch way look down to your right its there! just as u hit the centre room!\n\nSorry if its hard to understand :) hope this helps!",
            date = "2010-12-26T18:55:17-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27615#comments:id=1260583",
        },
        {
            id = 1255214,
            score = 4,
            author = "rkeen",
            text = "seriously, I feel like a retard cause I've been running around for 20 minutes and I still can't find the basement! :/",
            date = "2010-12-23T17:17:45-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27615#comments:id=1255214",
        },
        {
            id = 1273376,
            score = 4,
            author = "753026",
            text = "Just did this.\nGo inside.\nTurn right, turn left, turn left.\nJust before the center of the room with the green carpet, look to the right.\nIf you are facing the green carpet, then back up to the wall and look to the front right just before the arch.",
            date = "2011-01-02T14:02:38-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27615#comments:id=1273376",
        },
    },
