        {
            id = 1377297,
            score = 13,
            author = "Luminatti",
            text = "Enter building turn left. A right when you are staring at the wall and another immediate right when you are starring at two NPC's and a long table.  Turn left in the first room you come to and head up the stairs.  Turn left and go through doorway, then a quick right up a short ramp.  Top of ramp you will only be able to turn right and that takes you right into the big room with the NPC you need to kill.\n\n(other routes might also get you to this room)",
            date = "2011-03-27T07:21:01-05:00",
