    [27620] = {
        {
            id = 1179514,
            score = 41,
            author = "192476",
            text = "Spoiler alert:\n\nThis quest contains yet another \"merely a setback\" joke.",
            date = "2010-11-23T22:53:56-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27620#comments:id=1179514",
        },
        {
            id = 2027458,
            score = 8,
            author = "JasperKazai",
            text = "I like how she gives credit to Eligor and Korfax for clearing out the abbey and barracks even though that was you, and then continues to do nothing herself while commanding you to do yet another task. Grade A delegation.",
            date = "2014-11-10T16:24:19-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27620#comments:id=2027458",
        },
        {
            id = 2625379,
            score = 8,
            author = "Eraclitus",
            text = "Attention enchanters!\n\nThe https://www.wowhead.com/npc=9451 around the cathedral in Tyrs Hand are the only source of the formula https://www.wowhead.com/item=16252 in the game. After handing in this quest at the Light's Hope Chapel the scarlet archmages will become unreachable for your character thus also the formula because the area of Tyrs Hand will change due to phasing. After finishing the quest there won't be any enemies around the cathedral anymore.\n\nIf you have already finished the quest you can either try to get the formula with another character (no need to be an enchanter, drops for everyone) which hasn't finished the quest yet or buy it at the auction house because the formula is not BOP.",
            date = "2018-10-22T12:06:33-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27620#comments:id=2625379",
        },
        {
            id = 1196051,
            score = 1,
            author = "519724",
            text = "While I can't agree with their methods, I can't argue with their results.\nYes... yes, that seems to make sense.",
            date = "2010-11-29T16:18:06-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27620#comments:id=1196051",
        },
        {
            id = 2576031,
            score = 1,
            author = "Arbron",
            text = "This quest is a perfect example of how badly the pre-WoD stat squish was handled combined with the idiotic 7.3.5 leveling changes.\n\nI'm leveling an arms warrior, currently 51. This quest is not doable. I have 8k health, he has 21k. His aura gives him 1700 armor, which is INSANE at this point (and wasn't squished with WoD because the idiot devs overlooked these buffs). He has a spammable Hammer of Justice which can easily buy him lots of time to beat you down while you do little damage in return.\n\nThis quest should be marked group now, because that's what it requires.",
            date = "2018-06-24T23:04:55-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27620#comments:id=2576031",
        },
    },
    [27625] = {
        {
            id = 1934957,
            score = 7,
            author = "533861",
            text = "There's no follow up quest, but go to the nearby building overlooking the lake for the next quests in the series.",
            date = "2014-01-16T03:18:28-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27625#comments:id=1934957",
        },
        {
            id = 1659042,
            score = 3,
            author = "Gurluas",
            text = "What is the pre-req to this?",
            date = "2012-04-26T12:09:41-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27625#comments:id=1659042",
        },
        {
            id = 3187465,
            score = 1,
            author = "BerettaNEWarrior",
            text = "So wait, this shares a quest name with the Blood Elf heritage armor quest chain?\n\nAnd in the Alliance version Forsaken try to slaughter High Elves?\n\nOh I'm dying. That's amazing.\n\nIn the Heritage Armor quest chain we've just seen Sylvanus die in futility and be made into a Banshee by Arthas after seeing a High Elven mother and daughter be killed by the Scourge.\n\nAnd yet here this quest is. Sylvanus corpse-stooges, her useful idiots, attempting to finish what she died fighting as they attack a High Elven refuge.\n\nThank you Blizz. You truly have no idea what you're doing.",
            date = "2020-01-31T06:11:49-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27625#comments:id=3187465",
        },
        {
            id = 1506137,
            score = 0,
            author = "Mosati",
            text = "Truly one of the best means to farm silk cloth and a lesser amount of wool. The Deathstalker Invaders (http://www.wowhead.com/npc=43541) are a simple grind kill for higher level players and the re-spawn is so fast that you have effectively no wait. In 15 minutes I had six and a half stacks of silk cloth to send to my tailor.",
            date = "2011-08-29T15:22:01-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27625#comments:id=1506137",
        },
    },
    [27626] = {
        {
            id = 1208165,
            score = 14,
            author = "258432",
            text = "Highvale Records (http://www.wowhead.com/item=61973) - 32, 47 - Inside building, turn right, end of hall.\nHighvale Notes (http://www.wowhead.com/item=61974) - 30,49 - Outside of building on West side, beside small well and barrel.\nHighvale Report (http://www.wowhead.com/item=61972) - 29, 46 - West of lake, in the middle of gazebo.",
            date = "2010-12-05T12:24:57-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27626#comments:id=1208165",
        },
        {
            id = 1184621,
            score = 12,
            author = "penguin1989",
            text = "Doing this quest for loremaster and the Highvale Records didnt show on my Blizzard Style Questhelper, figured Id post where it is.\n\n31.8 , 46.9.\n\nIts in the Quel'Danil Lodge, as you enter the building go right and its at the end of the room, on the left.",
            date = "2010-11-25T11:06:37-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27626#comments:id=1184621",
        },
        {
            id = 1934958,
            score = 12,
            author = "533861",
            text = "There's no follow up quest, but go to the nearby building overlooking the lake for the next quests in the series.",
            date = "2014-01-16T03:22:36-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27626#comments:id=1934958",
        },
        {
            id = 1189199,
            score = 5,
            author = "cheriea99",
            text = "If you're using Carbonite 4.030109 beta verson don't be mislead where the turn in is for this quest.  At the time of this posting Carbonite had the ? turn in all the way over by the Aerie Peak inn/FP area where you would find the NPC 'Ambassador Rualeth'.  The turn in is defintely back with the same NPC you got the quest from in that small cottage that's behind the Quel'Danil Lodge.  I'm sure in time Carbonite will work out the misrepresentation.  At least I hope they will, otherwise, I've only wasted my time posting the error to their developers.",
            date = "2010-11-27T00:20:52-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27626#comments:id=1189199",
        },
        {
            id = 1531075,
            score = 5,
            author = "610726",
            text = "To get the quests from Anchorite Traska, you must first be sent there from https://www.wowhead.com/npc=46476, who'll send you after you've done quests from the two dwarves nearby. https://www.wowhead.com/npc=43156 is one of them, not sure if quests from both dwarves must be done, or just his, but I was unable to do this quest until I'd run around Jintha'Alor for a while.",
            date = "2011-09-29T18:45:28-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27626#comments:id=1531075",
        },
    },
