    [27672] = {
        {
            id = 1413707,
            score = 23,
            author = "esk27",
            text = "Since patch 4.1 the key is no longer needed to summon Ironaya.\nHowever, the quest text hasn't changed as it still points to the parts for the key. The parts for the key will not drop from Revelosh or from Baelog's chest. There's a grey item in the chest instead.\n\nSimply go to the Map Chamber and use the cogwheel on the keystone. The key will 'automagically' appear and Ironaya will be summoned.",
            date = "2011-05-09T06:56:21-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27672#comments:id=1413707",
        },
        {
            id = 1205783,
            score = 5,
            author = "Illinger",
            text = "Hmm...  Nice to see they kept the mechanics to unlock this boss the same.\nBut, that now leads me to the same problem I couldn't figure out before.\nWhere the heck is the Gni'kiv Medallion?\n\nBeen playing since Classic, and never found it or had it drop.\nAlways get the rod, and that's it.\n\nEdit:\nI had seen before that a blue answered this here http://www.wowhead.com/npc=7228#comments (http://www.wowhead.com/npc=7228#comments).\nWhat he/she leaves out is the chest is on the table with the book, which I must have rolled over a million times and only saw the read icon :(",
            date = "2010-12-04T09:20:28-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27672#comments:id=1205783",
        },
        {
            id = 1370039,
            score = 4,
            author = "805077",
            text = "The  Baelog Chest  is  on the table in Dig Two on the map. Open  chest  and  get  the  Gni'kiv Medallion.  There is also a book on the table.",
            date = "2011-03-18T12:07:49-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27672#comments:id=1370039",
        },
        {
            id = 1596070,
            score = 4,
            author = "806196",
            text = "Just to make this absolutely clear for those of us who are somewhat slow to catch on: esk27's comment is correct and:\nthe keystone is on one of the buildings in the toy town in the Map Chamber (see the screenshots) and\nby using the cogwheel esk27 means use the cogwheel cursor that opens other things for you, and\nbe patient it takes a bit of time for Ironaya to appear.",
            date = "2011-12-14T12:57:01-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27672#comments:id=1596070",
        },
    },
