        {
            id = 1435977,
            score = 9,
            author = "309256",
            text = "You can either ride the elevator up, or talk to Torben Zapblast, the gnome standing about 5 paces away, for a transport directly to the next quest NPC in the chain, your old friend Nevin Twistwrench... who has somehow made his way to the surface ahead of you.\n\nLeads to the quest that introduces you to your first class trainer.\n\nMage: The Future of Gnomeregan (http://www.wowhead.com/quest=26197)\nPriest: The Future of Gnomeregan (http://www.wowhead.com/quest=26199)\nRogue: The Future of Gnomeregan (http://www.wowhead.com/quest=26206)\nWarlock: The Future of Gnomeregan (http://www.wowhead.com/quest=26202)\nWarrior: The Future of Gnomeregan (http://www.wowhead.com/quest=26203)",
            date = "2011-06-07T00:22:56-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27674#comments:id=1435977",
        },
