            date = "2015-09-02T09:07:46-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27674#comments:id=2244356",
        },
    },
    [27675] = {
        {
            id = 1350967,
            score = 71,
            author = "419521",
            text = "When you turn this in, the NPC will usually give you some kind of response. The responses tend to be humorous, and highlight the immorality of this quest and your character's presumed ethics for doing such a thing:\n\nMaster Mathias Shaw (http://www.wowhead.com/npc=332) (the chief spy):\nMaster Mathias Shaw eyes you suspiciously.\nMaster Mathias Shaw says: Her bag of gold should be in the mail!  It's insulting she sends someone to collect from me while I'm working.\n\nMaster Mathias Shaw eyes you suspiciously.\nMaster Mathias Shaw says: I could swear I just paid a fine like this...\n\nMaster Mathias Shaw eyes you suspiciously.\nMaster Mathias Shaw says: This is a dangerous game you play... take your gold for now, but know that I'm watching you.\n\nDarlene Stokx (http://www.wowhead.com/npc=43693) (the riding trainer):\nDarlene Stokx says: I can't be held responsible every time someone falls off their mount.  I don't know how you got the official seal on this, but take your payment and don't question my horses again!\n\nDarlene Stokx says: I must have been pretty tipsy the night I promised you a pony.  Take your money and no hard feelings, okay?\n\nField Marshal Stonebridge (http://www.wowhead.com/npc=14721) (the chief dragon-head-putter-upper):\nField Marshal Stonebridge says: You honor us by delivering this information.  It seems as if we've finally found the spy in the city... a homeless man whom we will execute shortly.  Take your reward, you've done well!\n\nField Marshal Stonebridge says: These documents implicate several troll spies.  Consider their heads forfeit.  Take your compensation and spend it wisely; it's drawn from the taxpayers of Stormwind.\n\nField Marshal Stonebridge says: These documents implicate several orcish spies.  Our best assassins will be dispatched for this treachery.  Take your compensation and spend it wisely; it's drawn from the taxpayers of Stormwind.\n\nThomas Miller (http://www.wowhead.com/npc=3518) (the baker):\nThomas Miller says: Oh my... someone became ill from my bread?  How can this be?  Please, I hope my meager earnings are enough to help out.\n\nThomas Miller says: I've heard of mice trapped in ale bottles before, but never in bread.  P-p-please take everything and don't speak of this to anyone.\n\nJelinek Sharpshear (http://www.wowhead.com/npc=29142) (the barber):\nJelinek Sharpshear says: I don't usually give refunds for haircuts, but I must admit I did a terrible job on yours.  My apologies.\n\nJelinek Sharpshear says: Oh... I think I'm going to be sick.  How could I have cut off someone's ear and not have noticed?  Please take this money to a healer and have it reattached.\n\nAnnoyingly, Auctioneer Chilton (http://www.wowhead.com/npc=8670) says nothing when you turn this in to him.\n\nWhen I get more responses, I'll edit them in.",
            date = "2011-02-26T14:48:57-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27675#comments:id=1350967",
        },
        {
            id = 1242365,
            score = 52,
            author = "imizael",
            text = "Field Marshal Stonebridge is also a turn-in:\nField Marshal Stonebridge says: These documents implicate several orcish spies.  Our best assassins will be dispatched for this treachery.  Take your compensation and spend it wisely; it's drawn from the taxpayers of Stormwind.\n\n... Oops.",
            date = "2010-12-18T04:24:24-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27675#comments:id=1242365",
        },
        {
            id = 1313677,
            score = 35,
            author = "Catriona",
            text = "Darlene Stokx: I must have been pretty tipsy the night I promised you a pony. Take your money and no hard feelings, okay?\n\n...so who wants to hit Ghostcrawler up for some gold?",
            date = "2011-01-28T20:10:21-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27675#comments:id=1313677",
        },
        {
            id = 1236491,
            score = 29,
            author = "Merylyan",
            text = "Blackmailing is the gift that keeps on giving! :D",
            date = "2010-12-15T18:29:02-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27675#comments:id=1236491",
        },
        {
            id = 1658089,
            score = 22,
            author = "35361",
            text = "My results from Bulging Sack of Gold (http://www.wowhead.com/item=62062):\n\nDay 1 - Auctioneer Chilton - 20g85s24c\nDay 2 - Jelinek Sharpshear - 26g2s5c\nDay 3 - Darlene Stokx - 22g42s96c\nDay 4 - Thomas Miller - 25g88s44c\nDay 5 - Master Mathias Shaw - 17g50s76c\nDay 6 - Auctioneer Chilton - 13g95s33c\nDay 7 - Auctioneer Chilton - 24g54s7c\nDay 8 - Darlene Stokx - 16g49s32c\nDay 9 - Auctioneer Chilton - 24g60s32c\nDay 10 - Jelinek Sharpshear - 10g21s19c",
            date = "2012-04-24T07:10:32-05:00",
