    [27683] = {
        {
            id = 1630347,
            score = 25,
            author = "Eillesthis",
            text = "Optional breadcrumb quest to https://www.wowhead.com/npc=45417.\nhttps://www.wowhead.com/quest=27683 from the Western Plaguelands\nhttps://www.wowhead.com/quest=27684 from Light's Hope Chapel\nhttps://www.wowhead.com/quest=28578 from Alliance cities\nhttps://www.wowhead.com/quest=28577 from Horde cities\nare all optional, exclusive, and unavailable one you progress through her quest chain.",
            date = "2012-02-22T12:44:47-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27683#comments:id=1630347",
        },
        {
            id = 1183577,
            score = 14,
            author = "Liri",
            text = "I wonder.... Into the Woods (http://en.wikipedia.org/wiki/Into_the_Woods)?\n\nBernadette Peters was pretty amazing.",
            date = "2010-11-25T02:15:59-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27683#comments:id=1183577",
        },
        {
            id = 1368697,
            score = 12,
            author = "632821",
            text = "This quest is also given by Argent Officer Pureheart (http://www.wowhead.com/npc=10840) at Chillwind Camp, strangely to both Alliance and Horde.\n\nMy lower-level Goblin saw a quest marker in the Alliance Camp and just had to pick it up. None of the NPC's around her were to happy to see a Horde toon in their camp, btw.",
            date = "2011-03-16T19:18:22-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27683#comments:id=1368697",
        },
        {
            id = 1639462,
            score = 12,
            author = "sapristoire",
            text = "(This is speaking of situation for Alliance side. For Horde fellows, the logic shouldn't be very different though.)\n\nThe various breadcumb quests for https://www.wowhead.com/npc=45417 are not completely mutually exclusive:\n\nhttps://www.wowhead.com/quest=27683 and https://www.wowhead.com/quest=27684 are mutually exclusive; players can't obtain the other if they finish one of them.\nhttps://www.wowhead.com/quest=28578 would not exclude either quest above, and the order of completion is not important. However, a restriction apply: if Hero's call is active in quest log, players can't obtain any other breadcumb quest, so they must turn in Hero's call first before obtaining other breadcumb quests. The reverse is not true.\n\nTherefore, for maximum benefit, Alliance players can:\n\nHead back to [zone=1519] or [zone=1537] to obtain https://www.wowhead.com/quest=28578\nFly to https://www.wowhead.com/npc=45417 to turn in Hero's call.\nHead to either [zone=28] or to Light's Hope Chapel to obtain remaining breadcumb quest.\nGo back to https://www.wowhead.com/npc=45417 to finish turn it in.\n\nThe order of (3,4) and (1,2) can be exchanged.",
            date = "2012-03-14T11:54:39-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27683#comments:id=1639462",
        },
        {
            id = 1277675,
            score = 7,
            author = "57252",
            text = "I've finished every quest in WP, but this one was never available for me.",
            date = "2011-01-04T20:12:24-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27683#comments:id=1277675",
        },
    },
    [27684] = {
        {
            id = 1639463,
            score = 18,
            author = "sapristoire",
            text = "(This is speaking of situation for Alliance side. For Horde fellows, the logic shouldn't be very different though.)\n\nThe various breadcumb quests for https://www.wowhead.com/npc=45417 are not completely mutually exclusive:\n\nhttps://www.wowhead.com/quest=27683 and https://www.wowhead.com/quest=27684 are mutually exclusive; players can't obtain the other if they finish one of them.\nhttps://www.wowhead.com/quest=28578 would not exclude either quest above, and the order of completion is not important. However, a restriction apply: if Hero's call is active in quest log, players can't obtain any other breadcumb quest, so they must turn in Hero's call first before obtaining other breadcumb quests. The reverse is not true.\n\nTherefore, for maximum benefit, Alliance players can:\n\nHead back to [zone=1519] or [zone=1537] to obtain https://www.wowhead.com/quest=28578\nFly to https://www.wowhead.com/npc=45417 to turn in Hero's call.\nHead to either [zone=28] or to Light's Hope Chapel to obtain remaining breadcumb quest.\nGo back to https://www.wowhead.com/npc=45417 to finish turn it in.\n\nThe order of (3,4) and (1,2) can be exchanged.",
            date = "2012-03-14T11:55:13-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27684#comments:id=1639463",
        },
        {
            id = 1268439,
            score = 14,
            author = "Tarinae",
            text = "This quest apparently counts for Loremaster but once you have already started the Fiona questline and escorted the two paladins to Lord Maxwell Tryrosus, this quest doesn't seem to be available so do it beforehand.",
            date = "2010-12-30T18:09:45-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27684#comments:id=1268439",
        },
        {
            id = 1630349,
            score = 8,
            author = "Eillesthis",
            text = "Optional breadcrumb quest to https://www.wowhead.com/npc=45417.\nhttps://www.wowhead.com/quest=27683 from the Western Plaguelands\nhttps://www.wowhead.com/quest=27684 from Light's Hope Chapel\nhttps://www.wowhead.com/quest=28578 from Alliance cities\nhttps://www.wowhead.com/quest=28577 from Horde cities\nare all optional, exclusive, and unavailable one you progress through her quest chain.",
            date = "2012-02-22T12:45:21-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27684#comments:id=1630349",
