    [27686] = {
        {
            id = 1338793,
            score = 93,
            author = "Camron",
            text = "How to actually complete the quest: (For those as simple minded as me)\n\nDon't bother opening your big Map and looking for a question mark like I did, that won't work.\nRunning around Orgrimmar like a headless chicken and talking to random NPCs probably won't work either.\n\nI spent a good 5 minutes doing so until I realised that I should probably look at my minimap.\nYou'll see the ordinary, yellow colored, question mark in your minimap at places where an NPC is willing to accept your Forged Documents. Talking to NPCs other than those revealed by your minimap is useless.\n\nRun around and keep an eye on your minimap and you'll find an NPC you can fool with your almost legit documents.\nAs of right now, it also seems like the only NPCs you can use to complete the quest are located in Valley of Strength, atleast I couldn't find anyone in other places in Orgrimmar.\n\nHope this'll help somebody equally stupid to myself.",
            date = "2011-02-16T16:43:09-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27686#comments:id=1338793",
        },
        {
            id = 1248406,
            score = 32,
            author = "664982",
            text = "...\"Orgimmar\"?\n\nC'mon Blizz, you gotta get your own spellings correct!",
            date = "2010-12-20T16:32:52-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27686#comments:id=1248406",
        },
        {
            id = 1182671,
            score = 11,
            author = "Solarax",
            text = "This appears to be a money making scheme (the Bulging Sack Of Gold (http://www.wowhead.com/item=62062) contains around 10g) for high level characters who have maxed out Inscription, allowing them to create the Forged Documents (http://www.wowhead.com/item=63276) required to begin the quest.\n\nI imagine further details concerning whether the quest is repeatable or daily will become available once Cataclysm launches.",
            date = "2010-11-24T18:57:44-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27686#comments:id=1182671",
        },
        {
            id = 1226244,
            score = 10,
            author = "323714",
            text = "there are (at least for horde) several possible turn ins, i suggest not to the cook as turning in to others offers same reward and interesting text that they say as you turn them in",
            date = "2010-12-12T00:43:09-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27686#comments:id=1226244",
        },
        {
            id = 1883891,
