    [27705] = {
        {
            id = 1180754,
            score = 40,
            author = "Ubik",
            text = "From the Hall of Masks, while facing the dungeon entrance, go to the right, then again to the right, down the stairs and to the left into the Chamber of Blood. The Priestess is at the back of the room.",
