    [27713] = {
        {
            id = 1106615,
            score = 308,
            author = "Elfhippie",
            text = "Best. Quest. Ever.",
            date = "2010-08-23T19:19:08-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27713#comments:id=1106615",
        },
        {
            id = 1109938,
            score = 259,
            author = "549382",
            text = "Walking down into the badlands great scar,\nMy pac filled with eye, toes, dead hearts in jars,\nI came to a dwarf who offered a drink\n\"I'll tell you a story!\" He said with a wink.\n\nIt was sunny that day\" he said with a smirk on his face,\nI was minding my business, starring into blue space.\nWhen suddenly he came flying overhead\n\"Deathwing is back!\", Said my comrades with dread!\n\nI made a solem promise, upheld to deaths embrace\nI said, I'm gonna punch that dragon in the face!\nThe dragon had knocked loes a ton of foes\nOnly dang rocks waiting to be disposed!\n\nFists filled with blood, I charged right on in\nPunches that bursts those rocks from within\nHundreds of them with mindset to kill\nEach one falling, fists like steel drills!\n\nI stood before him, his eyes open wide\nTheres no where to run, no where to hide!\nFists wound up, jumped up with grand grace\nLanding a blow right onto his face!\n\nHe finished with his fist rased up in the air\nHis heroic pose, wind blowing in hair\nTo this day I remember Theldurin's tale\nTo a next adventure onward, on this grand boat at sail.\n\nOH GOD GIANT SQUID THING\nOH GOD PEOPLE ARE DROWNING\nOH GOD NAGA\nHELP",
            date = "2010-08-28T21:12:11-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27713#comments:id=1109938",
        },
        {
            id = 1193782,
            score = 146,
            author = "CzechMirco",
            text = "Please Blizzard, make this quest chain a repeatable one - no loot, no money, nothing, just the quest itself. I swear I'd do it at least once a week and Im pretty sure I wont be the only one.",
            date = "2010-11-28T15:41:32-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27713#comments:id=1193782",
        },
        {
            id = 1181160,
            score = 135,
            author = "Harson",
            text = "I just made the connection between the weird shaped scar Deathwing made in Badlands and the name of this quest.\n>:",
            date = "2010-11-24T10:48:42-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27713#comments:id=1181160",
        },
        {
            id = 1396055,
            score = 106,
            author = "771190",
            text = "Stumbled upon this quest after trying out https://www.wowhead.com/item=64457. Turned out it indeed was exactly where I wanted to go.",
            date = "2011-04-21T00:47:33-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27713#comments:id=1396055",
        },
    },
    [27714] = {
