        {
            id = 6178591,
            score = 77,
            author = "Kaynos",
            text = "If you can't grab the sun (grey gear), exit the vehicle and do the following steps.\n\n1-Ask him to retell the story.\n\n2-Grow yourself only ONCE (Important).\n\n3-Search ONE cloud, the Sun will appear above you.\n\n4-Grab the sun.\n\nIf you only grew yourself ONCE you should be able to grab it.",
            date = "2025-09-03T07:48:49-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27714#comments:id=6178591",
        },
        {
            id = 1212421,
            score = 72,
            author = "25986",
            text = "If the sun doesn't show up after collecting the clouds, click the eject button to get out of the story, then ask the gnome to tell you the story again. You'll still get credit for searching the clouds and the sun should appear as well.",
            date = "2010-12-07T15:13:16-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27714#comments:id=1212421",
        },
        {
