    [27756] = {
        {
            id = 1188334,
            score = 5,
            author = "psxchelly",
            text = "Leads to:\n\nThe Carpenter\nhttp://www.wowhead.com/quest=27758 (http://www.wowhead.com/quest=27758)\n\nPS: dont forget to use the transporter thingy to prevent \"some\" running back and forth.",
            date = "2010-11-26T17:23:12-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27756#comments:id=1188334",
        },
        {
            id = 1436263,
            score = 4,
            author = "635216",
            text = "I always had a hard time with the Deadmines now, as I have to go back at least 4 times to do the entire quest chain. For some reason when I complete one quest I do not get the auto accept for the other one, and after Ripsnarl is killed Captain Cookie is automatically spawned",
            date = "2011-06-07T10:27:04-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27756#comments:id=1436263",
        },
        {
            id = 1573282,
            score = 3,
            author = "912510",
            text = "Werid quest ;D",
            date = "2011-11-16T02:43:06-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27756#comments:id=1573282",
        },
        {
            id = 1193873,
            score = 1,
            author = "309256",
            text = "I was running my level 12 Priest through Deadmines with my level 80 Druid. With the Druid, I initially picked up the first quest, The Foreman (http://www.wowhead.com/quest=27756), but abandoned it because my Priest was not high enough (level 15 requirement) and figured I would come back and do them both together.\n\nWhen my Priest entered the Mast Room, the quest The Carpenter (http://www.wowhead.com/quest=27758) was automatically offered, even though he does not meet the level requirements and does not have the Stormwind Communicator Mk. II (http://www.wowhead.com/item=62334), yet my Druid got no quest.\n\nUpon entering the Goblin Foundary area, the same thing happened with the quest The Machination (http://www.wowhead.com/quest=27781); offered to my ineligible Priest just for walking through the door, but not to my eligible Druid.\n\nOnce walking onto the dock in the Ironclad Cove area, I was given the quest The Admiral (http://www.wowhead.com/quest=27785), but upon completion, I was NOT given the follow-up quest, The Defias Kingpin (http://www.wowhead.com/quest=27790).\n\nI ran through the dungeon again, this time doing the quest line with my Druid, starting from the beginning, and was given every quest normally as I progressed through the dungeon, without incident.\n\nOnce my Priest reached level 15, I zoned back into Deadmines and Lieutenant Horatio Lane (http://www.wowhead.com/npc=46612) offered me both The Foreman (http://www.wowhead.com/quest=27756) and The Defias Kingpin (http://www.wowhead.com/quest=27790) at once.\n\nTL;DR - Even if you are below level 15, it seems you can still do every quest in this chain except the first and the last.",
            date = "2010-11-28T16:10:53-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27756#comments:id=1193873",
        },
        {
            id = 5422239,
            score = 1,
            author = "Chaindog",
            text = "SL S4\n\nSOLUTION TO QUEST PROBLEM: Heroic turn-in problem still exists in 2022!\n\n1 - You need to EXIT dungeon,\n2 - RESET to Normal mode,\n3 - re-enter and you'll be able to turn this in to https://www.wowhead.com/npc=46612 not too far inside.\n\nEnjoy your loot!",
            date = "2022-08-23T03:50:47-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27756#comments:id=5422239",
        },
    },
