    [27772] = {
        {
            id = 1208589,
            score = 25,
            author = "violetta",
            text = "\"my cover has quite clearly been blown\"\nwell yes, this is what happens when you reveal your true form in the middle of a group of black dragons rather than somewhere more private or just whispering in your friends ear \"hey I'm really a red dragon, thanks for helping me\"\n\nit was blatantly obvious however that she wasn't really a goblin since neither of her quests involved exploding the dragons",
            date = "2010-12-05T16:23:30-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27772#comments:id=1208589",
        },
        {
            id = 1953548,
            score = 5,
            author = "nmb3000",
            text = "If you are Alliance, be a little cautious when you're riding from Rheastrasza to Agmond's End.  Bloodwatcher Point is right in the path and if you get a little too close the Reliquary Overseer guards will take you down, hard and posthaste.  They seem to have an absolutely insane (40+ yards) detection range (even against stealthed mid-40s), probably because they're supposed to go after the buzzards that fly around the area.\n\nWhatever the reason, the end result is the same: \"Oh what's this camp up ahead...\" -- *dead*.  Run back and resurrect far away.  \"Wow that guy smashed my face...\" -- *more dead*.",
            date = "2014-03-24T23:52:39-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27772#comments:id=1953548",
        },
        {
            id = 2464830,
            score = 2,
            author = "1730593",
            text = "For People with Carbonite telling them his at 18.0 / 30.4.\nFirst he is at Agmonds's End at 47.0 / 56.6.",
            date = "2017-01-19T06:46:44-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27772#comments:id=2464830",
        },
    },
    [27773] = {
        {
            id = 1180817,
            score = 77,
            author = "Ubik",
            text = "From the Butchery, where you killed Gomora, go back out and to the left and follow the corridor untill you reach the Den of the Caller. Here you can pick the corridor to the left side. Follow it untill you reach the Hall of Bones. This is a room and from it's balcony you can see the Prophet right below you.",
            date = "2010-11-24T09:09:24-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27773#comments:id=1180817",
        },
        {
            id = 1297819,
            score = 32,
            author = "738486",
            text = "In case you are confused like I was at first, this quest is NOT completed in the instance.  When I picked this quest up I remembered that one of the bosses in Sunken Temple is named Jammal'an the Prophet.  The target for this quest is NOT the same NPC.  To complete this quest you need to continue to follow the hallway past the room with Gomora. You will go down several staircases and then come to a room where this NPC is.  Target is non-elite.\n\nThere is still a boss in Sunken Temple by the exact same name.  There is a separate quest from an NPC just inside the instance for this boss.  Very confusing to have two quest targets by the exact same name.",
            date = "2011-01-17T13:06:03-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27773#comments:id=1297819",
        },
        {
            id = 1306760,
