    [27781] = {
        {
            id = 1188357,
            score = 7,
            author = "psxchelly",
            text = "Leads to:\n\nThe Admiral\nhttp://www.wowhead.com/quest=27785 (http://www.wowhead.com/quest=27785)",
            date = "2010-11-26T17:31:24-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27781#comments:id=1188357",
        },
        {
            id = 1193894,
            score = 2,
            author = "309256",
            text = "I was running my level 12 Priest through Deadmines with my level 80 Druid. With the Druid, I initially picked up the first quest, The Foreman (http://www.wowhead.com/quest=27756), but abandoned it because my Priest was not high enough (level 15 requirement) and figured I would come back and do them both together.\n\nWhen my Priest entered the Mast Room, the quest The Carpenter (http://www.wowhead.com/quest=27758) was automatically offered, even though he does not meet the level requirements and does not have the Stormwind Communicator Mk. II (http://www.wowhead.com/item=62334), yet my Druid got no quest.\n\nUpon entering the Goblin Foundary area, the same thing happened with the quest The Machination (http://www.wowhead.com/quest=27781); offered to my ineligible Priest just for walking through the door, but not to my eligible Druid.\n\nOnce walking onto the dock in the Ironclad Cove area, I was given the quest The Admiral (http://www.wowhead.com/quest=27785), but upon completion, I was NOT given the follow-up quest, The Defias Kingpin (http://www.wowhead.com/quest=27790).\n\nI ran through the dungeon again, this time doing the quest line with my Druid, starting from the beginning, and was given every quest normally as I progressed through the dungeon, without incident.\n\nOnce my Priest reached level 15, I zoned back into Deadmines and Lieutenant Horatio Lane (http://www.wowhead.com/npc=46612) offered me both The Foreman (http://www.wowhead.com/quest=27756) and The Defias Kingpin (http://www.wowhead.com/quest=27790) at once.\n\nTL;DR - Even if you are below level 15, it seems you can still do every quest in this chain except the first and the last.\n\n-- SPECIFIC INFORMATION ABOUT THIS FIGHT --\n\nThe Foe Reaper 5000 becomes active after you kill the harvest golem-type enemies - Defias Reaper (http://www.wowhead.com/npc=47403) and Defias Watcher (http://www.wowhead.com/npc=47404) - surrounding him. After taking enough damage, the Reapers and Watchers get zapped by the Foe Reaper 5000 and become controllable vehicles for a few seconds. If you are farming rep, you may just want to kill them; they give +15 rep and some xp when killed before the transformation (but no loot).",
            date = "2010-11-28T16:22:37-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27781#comments:id=1193894",
        },
        {
            id = 5422240,
            score = 1,
            author = "Chaindog",
            text = "SL S4\n\nSOLUTION TO QUEST PROBLEM: Heroic turn-in problem still exists in 2022!\n\n1 - You need to EXIT dungeon,\n2 - RESET to Normal mode,\n3 - re-enter and you'll be able to turn this in to https://www.wowhead.com/npc=46612 not too far inside.\n\nEnjoy your loot!",
            date = "2022-08-23T03:51:29-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27781#comments:id=5422240",
        },
    },
    [27785] = {
        {
            id = 1193815,
            score = 5,
            author = "309256",
            text = "I was running my level 12 Priest through Deadmines with my level 80 Druid. With the Druid, I initially picked up the first quest, The Foreman (http://www.wowhead.com/quest=27756), but abandoned it because my Priest was not high enough (level 15 requirement) and figured I would come back and do them both together.\n\nWhen my Priest entered the Mast Room, the quest The Carpenter (http://www.wowhead.com/quest=27758) was automatically offered, even though he does not meet the level requirements and does not have the Stormwind Communicator Mk. II (http://www.wowhead.com/item=62334), yet my Druid got no quest.\n\nUpon entering the Goblin Foundary area, the same thing happened with the quest The Machination (http://www.wowhead.com/quest=27781); offered to my ineligible Priest just for walking through the door, but not to my eligible Druid.\n\nOnce walking onto the dock in the Ironclad Cove area, I was given the quest The Admiral (http://www.wowhead.com/quest=27785), but upon completion, I was NOT given the follow-up quest, The Defias Kingpin (http://www.wowhead.com/quest=27790).\n\nI ran through the dungeon again, this time doing the quest line with my Druid, starting from the beginning, and was given every quest normally as I progressed through the dungeon, without incident.\n\nOnce my Priest reached level 15, I zoned back into Deadmines and Lieutenant Horatio Lane (http://www.wowhead.com/npc=46612) offered me both The Foreman (http://www.wowhead.com/quest=27756) and The Defias Kingpin (http://www.wowhead.com/quest=27790) at once.\n\nTL;DR - Even if you are below level 15, it seems you can still do every quest in this chain except the first and the last.\n\n-- SPECIFIC INFORMATION ABOUT THIS FIGHT --\n\nI kept killing him too quickly to see if there are any more changes as the fight progresses, but it seems that as you damage him, he will disappear, and the area becomes shrouded in mist, out of which appear some mist-elemental-type creatures. After killing a certain number, or after a certain length of time progresses, Admiral Ripsnarl reappears. I got him to disappear and reappear twice before accidentally killing him.\n\nIf you are rep farming, it is worth noting that the elementals (as well as all of the targetable cannons in the zone) give +3 rep.\n\nEDIT: I came back and tried this again. I got Admiral Ripsnarl to just above 50% health, and stopped damaging him. It seems the \"Vapor\" elemental adds will spawn indefinitely. It became nearly imposible to count the number of them by eye after 18 or so. They continued to spawn for well after that, until I grew bored and killed them all. Calculating by the rep gain, there turned out to have been 35 of them total.",
            date = "2010-11-28T15:51:05-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27785#comments:id=1193815",
        },
        {
            id = 1953271,
            score = 3,
            author = "1191285",
            text = "As a lvl 20 paladin, I got to the door leading to the Admiral, but the door is locked.  Where's the key?",
            date = "2014-03-23T19:41:03-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27785#comments:id=1953271",
        },
        {
            id = 5422236,
            score = 1,
            author = "Chaindog",
            text = "SL S4\n\nSOLUTION TO QUEST PROBLEM: Heroic turn-in problem still exists in 2022!\n\n1 - You need to EXIT dungeon,\n2 - RESET to Normal mode,\n3 - re-enter and you'll be able to turn this in to https://www.wowhead.com/npc=46612 not too far inside.\n\nEnjoy your loot!",
            date = "2022-08-23T03:49:25-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27785#comments:id=5422236",
        },
    },
    [27789] = {
        {
