        },
    },
    [27790] = {
        {
            id = 1369780,
            score = 8,
            author = "Serenn",
            text = "If you forget to turn this quest in before leaving your party and being transported out (like I did), you can run back into the instance (the old school way!). Horatio Laine will be at the beginning of the instance right after you zone in and there are no unfriendly mobs to deal with to get to him.",
            date = "2011-03-18T04:41:06-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27790#comments:id=1369780",
        },
        {
            id = 1426833,
            score = 6,
            author = "Freedomage",
            text = "Cookie came out and attacked before I got the quest, after accepting it, I waited for 10 minutes for Cookie to rerez but no luck.\nHad to reset and go through again.",
            date = "2011-05-25T08:20:46-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27790#comments:id=1426833",
        },
        {
            id = 1188410,
            score = 4,
            author = "psxchelly",
            text = "Don't be so quick to kill Cookie.. eat the food he throws for a *massive* buff.  Especially helpful for lower levels.\n\nHowever there may be a glitch.. because Cookie came out and attacked before I received the quest.",
            date = "2010-11-26T17:49:02-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27790#comments:id=1188410",
        },
        {
            id = 5422234,
            score = 4,
            author = "Chaindog",
            text = "DF S1\n\nSOLUTION TO QUEST PROBLEM: Heroic turn-in problem still exists in 2022!\n\n1 - You need to EXIT dungeon,\n2 - RESET to Normal mode,\n3 - re-enter and you'll be able to turn this in to https://www.wowhead.com/npc=46612 not too far inside.\n\nEnjoy your https://www.wowhead.com/item=65983!",
            date = "2022-08-23T03:46:30-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27790#comments:id=5422234",
        },
        {
            id = 1193824,
            score = 3,
            author = "309256",
            text = "I was running my level 12 Priest through Deadmines with my level 80 Druid. With the Druid, I initially picked up the first quest, The Foreman (http://www.wowhead.com/quest=27756), but abandoned it because my Priest was not high enough (level 15 requirement) and figured I would come back and do them both together.\n\nWhen my Priest entered the Mast Room, the quest The Carpenter (http://www.wowhead.com/quest=27758) was automatically offered, even though he does not meet the level requirements and does not have the Stormwind Communicator Mk. II (http://www.wowhead.com/item=62334), yet my Druid got no quest.\n\nUpon entering the Goblin Foundary area, the same thing happened with the quest The Machination (http://www.wowhead.com/quest=27781); offered to my ineligible Priest just for walking through the door, but not to my eligible Druid.\n\nOnce walking onto the dock in the Ironclad Cove area, I was given the quest The Admiral (http://www.wowhead.com/quest=27785), but upon completion, I was NOT given the follow-up quest, The Defias Kingpin (http://www.wowhead.com/quest=27790).\n\nI ran through the dungeon again, this time doing the quest line with my Druid, starting from the beginning, and was given every quest normally as I progressed through the dungeon, without incident.\n\nOnce my Priest reached level 15, I zoned back into Deadmines and Lieutenant Horatio Lane (http://www.wowhead.com/npc=46612) offered me both The Foreman (http://www.wowhead.com/quest=27756) and The Defias Kingpin (http://www.wowhead.com/quest=27790) at once.\n\nTL;DR - Even if you are below level 15, it seems you can still do every quest in this chain except the first and the last.\n\n-- SPECIFIC INFORMATION ABOUT THIS FIGHT --\n\nCookie also throws \"spoiled\" food types on the ground, which, when eaten, give you a stacking Nature damage debuff. So be careful about what food you eat after picking it up off the ground (which goes without saying, I suppose).\n\nReminds me of the \"Found Cake\" fetched by your dog in Dragon Age: Origins. \"I'm not eating any Found Cake!\"",
            date = "2010-11-28T15:53:45-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27790#comments:id=1193824",
        },
    },
    [27791] = {
        {
            id = 1785813,
            score = 3,
            author = "Ballybog",
            text = "Just behind the site, and up the hill a bit, there's a crypt of interest. Inside the room, you'll find a small campfire burning, and skeletal remains. One skeleton in particular stands out. It is seated, and is holding a sword in it's hand. Clearly a reference to the scene from Conan the Barbarian, where he's given his freedom and is chased into a cave/crypt by wild dogs. It's where he finds a seated skeleton and takes the sword it's holding.\n\nIf you go inside, you might also find a rare:\nhttp://www.wowhead.com/npc=51018#comments:id=1785807",
            date = "2012-12-22T18:09:27-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27791#comments:id=1785813",
        },
    },
    [27792] = {
        {
            id = 1190921,
            score = 68,
            author = "berdan",
