        {
            id = 1327379,
            score = 21,
            author = "632548",
            text = "What's this?  I've never seen trogg craftsmanship of this caliber!  You've stumbled upon something rare indeed, Nozzivix.\nmade my day",
            date = "2011-02-08T17:21:58-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27792#comments:id=1327379",
        },
        {
            id = 1213747,
            score = 13,
            author = "722029",
            text = "Multiple quest items can drop from a single mob, the first mob I killed dropped 3 of the 4 required items.",
            date = "2010-12-08T02:47:05-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27792#comments:id=1213747",
        },
        {
            id = 1211188,
            score = 9,
            author = "664415",
            text = "In order to get this quest you first have to do the chain quest \"A Hero's Call: Badlands\". [quest=28579 domain=www] (or Horde equivalent \"Warchief's Command: Badlands!\") Which will lead you to Rhea, and the chain quest \"First Sample: Wild Eggs\" also \"Second Sample: Wild Whelps. http://www.wowhead.com/quest=27765. This Chain will then lead you to Dr. Hieronymus Blam and the chain quest \"Dustwind Dig\" [quest=27791 domain=www]",
            date = "2010-12-07T03:25:44-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27792#comments:id=1211188",
        },
        {
            id = 1352944,
            score = 8,
            author = "192408",
            text = "There are 4 of them, if you are unlucky and have to wait for them to respawn like I do dont go too close to horde camp, overseer (http://www.wowhead.com/npc=51536#abilities) will one shot you. You are warned.",
            date = "2011-02-28T08:54:23-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27792#comments:id=1352944",
        },
    },
    [27793] = {
        {
            id = 1216000,
            score = 8,
            author = "720258",
            text = "This is pretty simple.\n\nGo to either the Sentinel or the Warden, they appear friendly. Talk with one of them (at a time), it takes maybe a couple of seconds for the quest to to its thing, and then they attack you. Defeat them, and it will say \"____ is investigated.\" Then do the same thing to the other NPC.",
            date = "2010-12-08T19:16:57-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27793#comments:id=1216000",
        },
        {
            id = 1284709,
            score = 6,
            author = "jamowbeck",
            text = "The auto-quest box seems to be bugged at this point. Left-click on the quest list and it will show the panel for completion. Click 'Complete quest'. At that time you will be able to open the box and continue as normal from there.",
            date = "2011-01-08T19:52:00-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27793#comments:id=1284709",
        },
        {
            id = 1279033,
            score = 2,
            author = "TwiztidMantis",
            text = "Kill them both and could not open the chest.... any suggestions?",
            date = "2011-01-05T15:24:16-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27793#comments:id=1279033",
        },
    },
    [27794] = {
        {
            id = 1199008,
            score = 16,
            author = "196807",
            text = "The artifact retrieved from the previous quest The Titans' Trove (http://www.wowhead.com/quest=27912) turns out to be an active Eye of the Watchers. It starts to fly when Blam activates it and purifies the tainted dragon eggs retrieved earlier from Third Sample: Implanted Eggs (http://www.wowhead.com/quest=27771) (Nyxondra's Eggs).\n\nDr. Hieronymus Blam says: Hey, look!  It's flying!\nEye of the Watchers says: Boot-up protocol completed.  Scanning for objective...\nEye of the Watchers says: Objective identified.  Scanning...\nEye of the Watchers says: Anomaly detected.  Probable source: Azerothian Old God.  Attempting to excise anomaly...\nEye of the Watchers says: Anomaly excised.  Repeating sub-protocol...\nEye of the Watchers says: Anomaly excised.  Repeating sub-protocol...\nEye of the Watchers says: Anomaly excised.  Re-assembling remaining material...\nEye of the Watchers says: Viable subject compiled.  No anomalies detected.\nEye of the Watchers says: User-objective protocol complete.  Stasis protocol re-enabled.\n\nBlam then gives you the quest Into the Dragon's Mouth (http://www.wowhead.com/quest=27826) to bring the purified egg(s) to Rhea.",
            date = "2010-11-30T23:20:13-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27794#comments:id=1199008",
        },
        {
            id = 1211204,
            score = 6,
            author = "664415",
            text = "In order to get this quest you first have to do the chain quest \"A Hero's Call: Badlands\". [quest=28579 domain=www] (or Horde equivalent \"Warchief's Command: Badlands!\") Which will lead you to Rhea, and the chain quest \"First Sample: Wild Eggs\" also \"Second Sample: Wild Whelps. http://www.wowhead.com/quest=27765. This Chain will then lead you to Dr. Hieronymus Blam and the chain quest \"Dustwind Dig\" http://www.wowhead.com/quest=27791. Which leads to Lead Prospector Durdin and the Chain quest \"The Sentinel's Pawn\" and \"The Warden's Pawn\"  [quest=27796 domain=www], and this quest.",
            date = "2010-12-07T03:36:43-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27794#comments:id=1211204",
        },
        {
            id = 5656213,
            score = 2,
            author = "Gadoink4",
