    [27796] = {
        {
            id = 1958621,
            score = 8,
            author = "jdmaddison",
            text = "If you are reading this, you no doubt have noticed that The Warden's Pawn (http://www.wowhead.com/quest=27796) is not initially available from Lead Prospector Durdin (http://www.wowhead.com/npc=46760). The real start of the quest chain is one or both of the quests that start in Fuselight, Easily Swayed (http://www.wowhead.com/quest=27774) or When the Going Gets Tough, Cheat (http://www.wowhead.com/quest=27775).\n\nBy the time you get through it all, you will be close to the Badlands questing achievement, so you might as well finish the zone.",
            date = "2014-04-14T22:26:09-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27796#comments:id=1958621",
        },
        {
            id = 1407651,
            score = 7,
            author = "537143",
            text = "Copied from Shadowbliss' post on the Horde version of this quest\n\nAs of today, with patch 4.1, I can confirm that this quest is _visually_ bugged.\n\n(Yes, I have tried with disabling addons etc, no dice).\n\nThe issue, shortly put, is that once you move a piece, it will - regardless of its original facing - now _visually_ be facing the wall. The quest is still doable, assuming you do it in the simplest way.\n\n1 2 3\n4 X 5\n6 7 8\n\nAll of these are facing outwards from the beginning, and with one free space to move, it's simply a case of getting the pairs sorted.\n\nIE, activate piece number1, then 8, then 1. These two figures have now swapped sides, and are correctly faced.\nThen piece 2, piece 7, piece 2. And so on.\n\nThis helped me do it without having the benefit of the visual heading of them.\n\nSource: http://www.wowhead.com/quest=27885#comments\n\nFigured it would be of use here too, if you found it useful make sure to vote his comment on the original up :)",
            date = "2011-05-02T19:05:00-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27796#comments:id=1407651",
        },
        {
            id = 1322164,
            score = 6,
            author = "299458",
            text = "The entrance to the Tomb of the Watchers is at 50.4 / 48.4.",
            date = "2011-02-05T00:44:30-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27796#comments:id=1322164",
        },
        {
            id = 1254312,
            score = 4,
            author = "TheLetterA",
            text = "As a clarification, this is not a sliding boxes puzzle. Whichever statue you click will teleport to the empty square. I just spent a long time trying to solve it by moving them to adjacent squares before I realized this >:(",
            date = "2010-12-23T09:03:19-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27796#comments:id=1254312",
        },
        {
            id = 1401159,
            score = 2,
            author = "Lucidic",
            text = "I attempted this quest on 26APR2011 (that's 4.1 patch day) and all the statues changed direction to face the wall when clicked.  This of course made the quest impossible to finish and blocked a huge amount of Badlands content.\n\nI got a druid friend to teleport to moonglade, fly to Winterspring, and \"Have Group, Will Travel\" me there to continue leveling.",
            date = "2011-04-27T09:02:33-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27796#comments:id=1401159",
        },
    },
    [27797] = {
        {
            id = 1204651,
            score = 6,
            author = "zukeithat",
            text = "Basically, when you click on the first statue (A) it sends a beam out that connects to another statue (statue b).  When you click on the next statue (b), if the beam doesn't redirect to another statue, click on it again.  If it never clicks on another statue, that particular statue is invalid, so in that case you need to go back to statue A and find a new statue b. ( I believe that only statue A points to a wrong statue b.)   Keep doing this (statue b to statue c, statue c to statue d, etc.) until you connect with the final statue to the left side of the room.  Since there is no fighting here, I advise do a quick check on where the final statue is so as to know what you are doing.",
            date = "2010-12-03T16:53:05-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27797#comments:id=1204651",
        },
        {
            id = 1215959,
            score = 6,
            author = "720258",
            text = "It is inside The Tombwatcher's Tomb. You'll see a friendly NPC named the Sentiel. As you walk in, take a right and go straight. You'll see the marble slab needed for this quest.",
            date = "2010-12-08T19:02:24-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27797#comments:id=1215959",
        },
        {
            id = 1199308,
            score = 4,
            author = "494323",
            text = "I had a hard time doing this because my quest was bugged and missing a statue. Drop it and re-do it if you have this same bug I did.\n\nYou will end up not using 1 statue completely (the first one that connects).",
            date = "2010-12-01T03:08:02-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27797#comments:id=1199308",
        },
        {
            id = 1660850,
            score = 1,
            author = "201712",
            text = "This quest is based on a ZX Spectrum old game called Deflektor. On that game you had to rotate lasers and mirrors to make a light path.\n\nGood memories from the game (http://www.worldofspectrum.org/infoseekid.cgi?id=0001327).",
            date = "2012-04-30T11:24:38-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27797#comments:id=1660850",
        },
        {
            id = 1677126,
            score = 1,
            author = "jtbalogh",
            text = "This quest is not the game. First turn this in to get, The Sentinel's Game (http://www.wowhead.com/quest=27709)\n\nGoal: turn each sentinel toward another sentinel so that the line can reach the last orange sentinel on the other side of room against the wall at 47,53",
            date = "2012-06-16T00:32:00-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27797#comments:id=1677126",
        },
    },
    [27818] = {
        {
            id = 1198005,
            score = 5,
            author = "Neocoolzero",
            text = "Beeing a overachiever on my main,and working atm on Bloodsail rep on him,i came here with my dk wich is neutral with Steamwheedle Cartel to test if this quest would give any goblin or negative Bloodsail rep,i can confirm that this doesnt give any positive goblin rep and no negative Bloodsail rep.",
            date = "2010-11-30T14:10:02-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27818#comments:id=1198005",
        },
        {
            id = 2476280,
            score = 1,
            author = "TamiayTheGnome",
            text = "We have quests to get teeth from lions, and hooves from Zevhras... Beaks from plainstriders! Perfectly ordinary things... But here we have to find intact hearts, which in itself can be quite difficult to find sometimes... But we are burning these things with holy light, fire, shadow magic, swords, axes, hammers... And ripping their hearts out of their corpses... And it seems to be a 100% drop rate. I find myself quite baffled, Not to complain, but, really, it's surprising!",
            date = "2017-03-08T05:34:36-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27818#comments:id=2476280",
        },
    },
