    [27823] = {
        {
            id = 1194085,
            score = 34,
            author = "417088",
            text = "Dwarf A: \"Blast, we're outta beer!\"\n\nDwarf B: \"Don't worry, I gots an idea... Hey, you, Draenei!\"\n\nPlayer: \"Me?\"\n\nDwarf B: \"Yeah! Tell ya what, over the next ridge, there's a bunch of evil dwarves. You can tell they're evil 'cause they're black. You're a do-gooder, ain'tcha? You should go kill them.\"\n\nPlayer: \"Uhh... ok...\"\n\nDwarf B: \"And while you're at it, why not bring us their beer. No sense letting good ale go to waste.\"\n\nPlayer: \"Wait, are you just getting me to murder people so you can steal their beer?\"\n\nDwarf B: \"...\"\n\nDwarf A: \"...\"\n\nDwarf B: \"...\"\n\nPlayer: \"...\"\n\nDwarf B: \"...No?\"\n\nPlayer: \"Ok, brb. You prefer bottles or cans?\"",
            date = "2010-11-28T17:42:25-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27823#comments:id=1194085",
        },
        {
            id = 2190834,
            score = 5,
            author = "Taraezor",
            text = "The Badlands of Khaz Modan was reworked for Cataclysm and now contains an epic quest chain along with a very humorous side quest chain.\n\nThe Rhea quest chain, if a further incentive is required, contains a cinematic at its conclusion. It is not to be missed.\n\nThe quest chain commences with https://www.wowhead.com/quest=27774. Players need only fly directly to the top of Fuselight to pick up the quest. https://www.wowhead.com/quest=27775 will also be offered but can be ignored.\n\nSeveral quests prior to that are offered, including faction city noticeboards and a fun rocket flight from the Eastern Plaguelands https://www.wowhead.com/quest=27762. They are unnecessary.\n\nWhile flying around the optional https://www.wowhead.com/quest=27823 (A) and https://www.wowhead.com/quest=27877 (H) are available and can be ignored if you are in a hurry. Anyhow, you will be taken to the locations where these quests are offered if you progress in the Rhea quest chain.\n\nhttps://www.wowhead.com/quest=27927 will be offered as you fly around. This is optional and functions merely to to get you to the location of https://www.wowhead.com/npc=2785 at location 26.2, 62.3, who offers https://www.wowhead.com/quest=27713. This is a very funny quest chain and not to be missed. A great counterpoint to the epic Rhea saga.",
            date = "2015-06-06T16:48:18-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27823#comments:id=2190834",
        },
        {
            id = 2515573,
            score = -4,
            author = "Lintian",
            text = "This quest is just such a perfect illustration of so many problems with Cataclysm writing: shallow stereotypes, casual sociopathy, and inconsistency. We're killing people we're given no good reason to hate except for them being an \"evil\" race — and who are actually supposed to be our allies, considering the Dark Iron dwarves joined the Alliance and got a council seat in Ironforge in this very same expansion — just so the questgiver can act out his racial stereotype. All for the same of cheap \"comedy\".",
            date = "2017-08-27T04:09:40-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27823#comments:id=2515573",
        },
        {
            id = 1342811,
            score = -5,
            author = "oncmonkey",
            text = "ok epix funny and also ez quest u just kill them one at a time and loot them simple...",
            date = "2011-02-19T22:58:22-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27823#comments:id=1342811",
        },
    },
