    [27825] = {
        {
            id = 1202199,
            score = 3,
            author = "travisdead1",
            text = "at 11,70 in the southwest Badlands. A cave that is shown on world map.\n\nThe silk is in sparkling chests on the floor of the cavern. The meat hangs from meat-hooks from the ceiling of the cavern.",
            date = "2010-12-02T13:32:50-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27825#comments:id=1202199",
        },
        {
            id = 1976362,
            score = 1,
            author = "obadelia",
            text = "I had a problem with this quest. Just an FYI for anyone else who gets hung up like I did.\n\nI was able to easily collect Dustbelcher Silk (10), but the Dustbelcher Meat (6) was not clickable.\n\nIf this happens to you abandon the quest and return to the quest giver, https://www.wowhead.com/npc=46930 at the Dragon's Mouth outpost, and pick it up again. The kink should be worked out, allowing you to complete the quest.",
            date = "2014-06-29T23:50:57-05:00",
