    [27827] = {
        {
            id = 1204903,
            score = 5,
            author = "TULOA",
            text = "I dont think anyone may have noticed but I liked this quest.\n\nYou basically get the three from The Lost Vikings from the Super Nintendo and they kinda worked them after it. They don't work exactly the same but close enough.",
            date = "2010-12-03T20:17:04-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27827#comments:id=1204903",
        },
        {
            id = 1368605,
            score = 3,
            author = "518829",
            text = "Also probably a reference to the Western classic \"The Good, the Bad and the Ugly\" (1966)",
            date = "2011-03-16T17:00:07-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27827#comments:id=1368605",
        },
        {
            id = 1434660,
            score = 2,
            author = "gajackson",
            text = "nobody mentioned it here, but after you get the 3, you can 'roam' with them a fair bit away from camp/the stated objectives; just tap a mob, and let them do all the cleanup.\n\nIf you are a gatherer and/or looking for fast Exp grind, having 3 guardians is NOT a bad deal! (similar to the 2 pallies you can get in EPL)",
            date = "2011-06-05T06:13:13-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27827#comments:id=1434660",
        },
        {
            id = 5473590,
            score = 1,
            author = "Wintword",
            text = "Anyone else having problems with taking this quest? I have it on the map, NPC has the quest but when I click on the NPC it doesn't react, so the quest cannot be taken... My guess is because of the world event happening... But mayhaps someone has a solution? Or do I just wait out until the event ends?",
            date = "2022-11-19T13:54:02-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27827#comments:id=5473590",
        },
        {
            id = 5473839,
            score = 1,
            author = "Neatforce",
            text = "There is a common issue with this quest since the new prepatch.\n\nYou can take this quest from https://www.wowhead.com/npc=46654 by moving into the new storm phase and moving back to the \"clear\" phase several times, trying different distances from her. The quest will guide you to https://www.wowhead.com/npc=46852 where you are supposed to take the https://www.wowhead.com/quest=27828 quest but you can't even interact with the NPC at all.\n\nI hope Blizzard will solve this issue soon.",
            date = "2022-11-20T03:36:05-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27827#comments:id=5473839",
        },
    },
    [27828] = {
        {
            id = 1798008,
            score = 64,
            author = "687730",
            text = "If you don't want to bother with those guys' abilities, then spamming a macro\n/cast Eric's Charge\n/cast Eric's Pocket Potion\n/cast Baelog's Valhalla Shot\n/cast Baelog's Warcry\n/cast Olaf's Shield Wall\n/cast Olaf's Mighty Shout\ndoesn't hurt at all.",
            date = "2013-01-13T16:43:35-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27828#comments:id=1798008",
        },
        {
            id = 1200915,
            score = 30,
            author = "Adelorna",
            text = "After completing this quest along with Baelog, the Glass Cannon (http://www.wowhead.com/quest=27834) and Olaf, the Big Fella' (http://www.wowhead.com/quest=27835), several tips.\n\nAt the time of writing this, several bar modification add-ons like Bartender etc aren't compatible with these vikings' abilities. So, before you accept these quests, turn your action bar related addons off.\nOnce you accept the quest(s), the NPCs' abilities will appear to the right of your screen.\nYou can do all three quests at the same time.\nIf you accept the three quests, all the abilities will appear on the single action bar to the right.\nWhen you're ready to actually complete the quest, you have to tag the mob with some spell before the NPCs' abilities become active for use. Simply aggro-ing the mob via proximity won't do.\nOnce the abilities light up, you can use all six on a single mob if you want to complete the three quests.\n\nHope this helps.",
            date = "2010-12-01T19:32:19-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27828#comments:id=1200915",
        },
        {
            id = 1520376,
            score = 21,
            author = "Mormolyce",
            text = "All this quibbling about addons and action bars and abandoning quests... IT'S THE LOST VIKINGS PEOPLE! BASK IN THE AWESOMENESS!",
            date = "2011-09-17T21:08:46-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27828#comments:id=1520376",
        },
        {
            id = 1201123,
            score = 18,
            author = "EchoOff",
            text = "I currently use Dominos, and this worked fine for me as soon as I realized the actions are on a pet bar.  I hardly even noticed that they were there until I took a good look at my bars.",
