    [27834] = {
        {
            id = 1968693,
            score = 46,
            author = "speedtycoon",
            text = "Was able to get this quest completed by using his Valhalla Shot to pull the mobs.  I found using it in combat gave no credit.",
            date = "2014-05-30T12:00:25-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27834#comments:id=1968693",
        },
        {
            id = 1942486,
            score = 25,
            author = "695025",
            text = "I've been having Baelog's Valhalla Shot glitching on me. If it doesn't work the first time, try opening with that ability on the next mob, and hopefully it will give you credit.",
            date = "2014-02-11T14:42:55-06:00",
