        },
        {
            id = 1187864,
            score = 19,
            author = "tumtum73",
            text = "You'll find an action bar with Baelog's Valhalla Shot and Baelog's war cry that are usable.  Click those while in a fight to complete the quest.",
            date = "2010-11-26T14:11:14-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27834#comments:id=1187864",
        },
        {
            id = 1200966,
            score = 16,
            author = "Adelorna",
            text = "After completing this quest along with  Eric, the Utility Dwarf (http://www.wowhead.com/quest=27828) and Olaf, the Big Fella' (http://www.wowhead.com/quest=27835), several tips.\n\nAt the time of writing this, several bar modification add-ons like Bartender etc aren't compatible with these vikings' abilities. So, before you accept these quests, turn your action bar related addons off.\nOnce you accept the quest(s), the NPCs' abilities will appear to the right of your screen.\nYou can do all three quests at the same time.\nIf you accept the three quests, all the abilities will appear on the single action bar to the right.\nWhen you're ready to actually complete the quest, you have to tag the mob with some spell before the NPCs' abilities become active for use. Simply aggro-ing the mob via proximity won't do.\nOnce the abilities light up, you can use all six on a single mob if you want to complete the three quests.\n\nHope this helps.",
            date = "2010-12-01T20:01:04-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27834#comments:id=1200966",
        },
        {
            id = 5466290,
            score = 5,
            author = "Edellis",
            text = "All 6 of their abilities are on the Pet Bar! With the introduction of the new Interface in Dragonflight Prepatch, make sure you go into Edit Mode and move your pet bar to a location that it can be toggled.\n\nAlso, when you've finished the quest, it looks like the question mark isn't updating properly, just click on them like you'd talk to them regularly and you'll be able to finish the quests.",
            date = "2022-11-07T11:53:44-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27834#comments:id=5466290",
        },
    },
    [27835] = {
