    [27850] = {
        {
            id = 1294422,
            score = 18,
            author = "Prasiatko",
            text = "This quest explains that Garrosh is pure idiot. Yes, it isn´t given directly by him, but the questline clearly indicates that Kaghta is under Garrosh command, rather than operating on her own.\nWhy? Beacause if Garrosh had more IQ than under-avarege kobold, he would actually ally with Defias instead of fighting them.\n\nYou know, Defias are a solid army. They just lack some proper training, but I believe Horde IS able to provide it. What more, they are the very architects and builder of Stormwind, they should know every its sterngts and weaknesses. And they could also provide treir machines and resources, that Garrosh wants so badly. And because they hate Stormwind by their very guts, there is practically no chance for any betrayal.\n\nBut nooo, that wouldn´t be our Garrosh. Why to buy/borrow the ship, when he can conquer it? Why to ally with a band of humans, when he can destroy it (and actually lose some of his forces in battle), and greatly help his enemy?\n\nYes, I know, Defias don´t have good relations with Horde, but they have the same enemy. Horde and Alliance battle each other, but they DID cooperate in Icecrown (even thouhgt only slightly, but they did)",
            date = "2011-01-15T03:29:39-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27850#comments:id=1294422",
        },
        {
            id = 1164271,
            score = 6,
            author = "139841",
            text = "Well this is cool, the Horde will also be getting quests in DM (Take note of who the reutation is for, Org)",
            date = "2010-11-07T06:57:55-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27850#comments:id=1164271",
        },
