    [27852] = {
        {
            id = 1409559,
            score = 61,
            author = "seahen",
            text = "These two races make a great study in contrasts. On the one hand, we have Blizzard's incarnation of one of the most cruel and barbaric races of monsters found in modern literature. On the other, we have a bunch of green people from Draenor.",
            date = "2011-05-04T16:50:16-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27852#comments:id=1409559",
        },
        {
            id = 1103558,
            score = 34,
            author = "Nulgar",
            text = "Reference to Warcraft: Orcs & Humans (http://www.wowpedia.org/Warcraft:_Orcs_%26_Humans), the first game in the Warcraft universe. According to reports on MMO-Champion forums (http://www.mmo-champion.com/threads/748915-Swamp-of-Sorrows-Old-School-Warcraft-SPOILERS), this quest, along with others in Swamp of Sorrows (even one called \"Tides of Darkness\" (http://www.wowpedia.org/Warcraft_II:_Tides_of_Darkness) - quest not on Wowhead yet) mimics/repeats the events of the first two Warcraft games, at first it's just \"Orcs and Humans\" battling, later aided by ogres and knights.",
            date = "2010-08-19T07:32:43-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27852#comments:id=1103558",
        },
        {
            id = 1425854,
            score = 23,
            author = "estroBiologist",
            text = "Wow.\nIt's finally happened.\nBlizzard has become self-referential.\n\nI look forward to Rock n Roll Racing jokes.\n\nOr maybe a Hyjal daily called Diablo, Too!",
            date = "2011-05-23T22:58:20-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27852#comments:id=1425854",
        },
    },
