    [27857] = {
        {
            id = 1306638,
            score = 18,
            author = "Boristus",
            text = "As with many of the quest names in this chain, this quest name refers back to one of the Warcraft RTS games. Specifically, it refers to Warcraft 3, in which when an Orcish player's base was attacked, an Orcish voice (similar to the voice you hear when your character in Wow can't click on something, or is out of mana, etc) would yell \"We're under attack!\" at the player who owns the base, warning them that they are, indeed, under attack.",
            date = "2011-01-23T17:30:36-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27857#comments:id=1306638",
        },
        {
