        {
            id = 1208867,
            score = 32,
            author = "violetta",
            text = "come back Deathwing! I helped her, kill me too! I want to get the Stood In The Fire (http://www.wowhead.com/achievement=5518) achievement!",
            date = "2010-12-05T18:30:44-06:00",
