    [27859] = {
        {
            id = 1179841,
            score = 193,
            author = "315117",
            text = "The most heartbreaking quest I have ever done.\nFor those of you who want to know how this questline ends, Rhea goes to hide the egg in a cave, but Deathwing shows up to eliminate the purified egg and Rhea herself.\nRhea begs that Deathwing show mercy on the egg but he torches them both and flies away.\nYou investigate the cave and discover that the egg was not the black dragon egg you've worked so hard to purify, but rather one of Rhea's own eggs. Rhea chose to lose one of her own children rather than sacrifice the black dragon egg, which is hidden somewhere not mentioned.\nThe quest reward is Rhea's last egg in the form of a trinket that summons a red dragon whelp to defend you.\nAbsolutely heartwrenching.",
            date = "2010-11-24T01:11:46-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27859#comments:id=1179841",
        },
