    [27882] = {
        {
            id = 1299474,
            score = 26,
            author = "425699",
            text = "Upon reading the completion, I see we are either dealing with a very very very smart person, or a very very very stupid person.\nOr a sarcastic person.",
            date = "2011-01-18T17:40:34-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27882#comments:id=1299474",
        },
        {
            id = 1386008,
            score = 7,
            author = "Termaq",
            text = "All the items drops from the mobs around there and not beneath the \"cave\"",
            date = "2011-04-07T04:57:44-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27882#comments:id=1386008",
        },
        {
            id = 1591662,
            score = 7,
            author = "cynisca",
            text = "The Alliance version is All's Fair in Love, War, and Archaeology (http://www.wowhead.com/quest=27792/alls-fair-in-love-war-and-archaeology).\n\nI think what I like best about these two quests, in addition to the minor flavour-changing comments that Durdin and Bloodwatcher make (\"stubby-fingered hands\" is such a male blood elf insult), is the fact that in both cases the story lines up, namely that the Reliquary is off stealing loot and robbing graves and generally causing trouble. We know so little about this organisation, but I think it's pretty clear that the phrase \"ethical investigative methods\" has a substantially different meaning for them. As in, a nonexistent meaning.",
            date = "2011-12-06T23:30:29-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27882#comments:id=1591662",
        },
        {
            id = 1869019,
            score = 7,
            author = "Diverdave333",
            text = "This quest reminds me of \"The Lost Ark\", if only because the Blood Elves seem to be following the Nazis' line of thinking...\n\nHope they don't get their faces melted off by some ancient Titan artifact.",
            date = "2013-06-21T13:36:45-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27882#comments:id=1869019",
        },
        {
            id = 1188458,
            score = 5,
            author = "113193",
            text = "You can get multiple items from a single mob.\n\nIn my case, The Broken Chalice, Earthen Hieroglyph and the Trogg Tool.",
            date = "2010-11-26T18:04:08-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27882#comments:id=1188458",
        },
    },
    [27883] = {
        {
            id = 1403940,
            score = 7,
            author = "Emalethx2",
            text = "If you are like me, you cannot find the opening to the tomb (yes, I am Blonde!) coords are (50, 48)",
            date = "2011-04-29T11:21:01-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27883#comments:id=1403940",
        },
        {
            id = 1187887,
            score = 4,
            author = "blupache",
            text = "Just move one of the side pieces - North, East, South or West, doesn't matter - into the middle.\n\nThen keep rotating all the other pieces around in a \"circle\" - clockwise or counter-clockwise, doesn't matter - until they're in position. You're basically just rotating the lot of them halfway around the \"circle\".\n\nOnce they're rotated into position you can then move the first piece back out of the centre and it'll slot into its position & complete the puzzle.",
            date = "2010-11-26T14:18:29-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27883#comments:id=1187887",
        },
        {
            id = 1677117,
            score = 3,
            author = "jtbalogh",
            text = "This quest is not the game. First turn this in to get, The Warden's Game (http://www.wowhead.com/quest=27885).\n\nGoal: move them until they all face the center and end with none in the center.",
            date = "2012-06-16T00:04:03-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27883#comments:id=1677117",
        },
        {
            id = 1702764,
            score = 3,
            author = "FlavourfulJakk",
            text = "I found this a little challenging, until I accidently clicked one that couldn't move into an adjacent square, and found out they could move diagonally. It was quite easy to solve after that, and with my second character (RAF) I managed to go through it in a minute or two.\n\nI'd like more quests like this, an option to make it easier by looking it up, or solving it yourself.",
            date = "2012-08-21T20:37:49-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27883#comments:id=1702764",
        },
        {
            id = 1403962,
            score = 2,
            author = "Emalethx2",
            text = "I don't think it's a glitch, I think it's supposed to be a combination of memory and slide... you must remember where each golum was facing initially and move them accordingly. You will get the quest finished if you do.",
            date = "2011-04-29T11:39:16-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27883#comments:id=1403962",
        },
    },
    [27884] = {
        {
            id = 1205807,
            score = 5,
            author = "330339",
            text = "The Sentinel that you are trying to connect is on the same side of the room to your left if you are looking at the starting Sentinel.\n\nSimply \"point\" each sentinel to the next until you have your connecting lines touching the other \"Red\" Sentinel.\n\nSimple process of elimination is all it takes. If your last sentinel will not reach the next, go back a step and try again.",
            date = "2010-12-04T09:42:39-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27884#comments:id=1205807",
        },
        {
            id = 1519974,
            score = 3,
            author = "Kactus04",
            text = "If you are like me, you thought that both quests gave you an item and that this one was broken. This quest does NOT give you an item, only the Warden's quest gives you an item.",
            date = "2011-09-17T07:37:40-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27884#comments:id=1519974",
        },
        {
            id = 1403942,
            score = 2,
            author = "Emalethx2",
            text = "If you are like me, you cannot find the opening to the tomb (yes, I am Blonde!) coords are (50, 48)",
            date = "2011-04-29T11:21:33-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27884#comments:id=1403942",
        },
        {
            id = 1677118,
            score = 1,
            author = "jtbalogh",
            text = "This quest is not the game. First turn this in to get, The Sentinel's Game (http://www.wowhead.com/quest=27886)\n\nGoal: turn each sentinel toward another sentinel so that the line can reach the last orange sentinel on the other side of room against the wall at 47,53",
            date = "2012-06-16T00:17:33-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27884#comments:id=1677118",
        },
        {
            id = 1973198,
            score = 1,
            author = "1254693",
            text = "For those of you who get here looking to start this quest line and don't know where to start, this is probably what you're looking for: https://www.wowhead.com/quest=27763",
            date = "2014-06-17T19:51:08-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27884#comments:id=1973198",
        },
    },
    [27885] = {
        {
            id = 1181226,
            score = 161,
            author = "409",
            text = "After I realized you can move pieces diagonally, it was easy.  Before that it was not :)",
            date = "2010-11-24T11:08:45-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27885#comments:id=1181226",
        },
        {
            id = 1189227,
            score = 93,
            author = "wbalmung",
            text = "When looking at it, this seemed like a sliding puzzle, but it's not. You can teleport any piece to any spot, not just \"sliding\" adjacent statues into the holes.",
            date = "2010-11-27T00:44:49-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27885#comments:id=1189227",
        },
        {
            id = 1198934,
            score = 53,
            author = "611800",
            text = "If you're having trouble solving this, here is a simple solution video :)\nhttp://www.youtube.com/watch?v=2pw7PFxxlTg&hd=1\n\nReposted cos some people are downrating an EXCELLENT guide to this.\n\nAlso, to DeadMAX up there: Phbbbbt.\n\nI don't think puzzles are fun. I want to play WoW. Not Puzzlemania. Or Turret Defense. Or Plants and frickin' Zombies. Or Simon Says. And there will be plenty of people who agree with me. So leave the people who want to get done with the quest alone and enjoy your $15 a month your way, while we do likewise.\n\nSo there! :D",
            date = "2010-11-30T22:23:15-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27885#comments:id=1198934",
        },
        {
            id = 1694243,
            score = 24,
            author = "998134",
            text = "Something important to note:\nUnlike traditional slider games, you CAN move a corner piece to the middle by clicking on it.  Thus, the solution becomes very simple:\n-Begin by clicking a corner piece, moving it into the center\n-Click each piece on the outside in turn, moving the outer ring either clockwise or counter-clockwise, until they all face inwards as required (there should be a corner empty, and it's piece should be in the center..\n-Click the piece you put into the center (a corner), and it will jump to the empty space.",
            date = "2012-07-30T22:24:36-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27885#comments:id=1694243",
        },
        {
            id = 1401423,
            score = 18,
            author = "370491",
            text = "As of today, with patch 4.1, I can confirm that this quest is _visually_ bugged.\n\n(Yes, I have tried with disabling addons etc, no dice).\n\nThe issue, shortly put, is that once you move a piece, it will - regardless of its original facing - now _visually_ be facing the wall. The quest is still doable, assuming you do it in the simplest way.\n\n1 2 3\n4 X 5\n6 7 8\n\nAll of these are facing outwards from the beginning, and with one free space to move, it's simply a case of getting the pairs sorted.\n\nIE, activate piece number1, then 8, then 1. These two figures have now swapped sides, and are correctly faced.\nThen piece 2, piece 7, piece 2. And so on.\n\nThis helped me do it without having the benefit of the visual heading of them.",
            date = "2011-04-27T12:11:57-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27885#comments:id=1401423",
        },
    },
    [27886] = {
        {
