            author = "wbalmung",
            text = "You get this quest after completing both \"The Warden's Game\" and \"The Sentinel's Game.\"\nGo back into the main chamber of the ruins, with both statues. Talk to each, and they will come online and attack you. Once you fight both of them, a chest spawns in the back of the room, open it to complete the quest.",
            date = "2010-11-27T00:47:43-06:00",
