    [27889] = {
        {
            id = 1318799,
            score = 2,
            author = "fwcain",
            text = "How can I get this quest?  I've looked and looked, but this NPC quest giver (Dr. Blam) is not at the indicated location.  All I find there are the ruins of \"old\" Kargath, patrolled by a high-flying dragon and a score of whelps.  Since this specific NPC (Dr. Blam) is listed as being at two different locations (here in the northwest, for this quest, as well as near Agmond's End for another quest), I presume this NPC is \"phased.\"  Can anyone please confirm this?\n\nUpdate: Per chat with the GM who responded to my in-game ticket, we first need to finish https://www.wowhead.com/quest=27789.",
            date = "2011-02-02T00:41:09-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27889#comments:id=1318799",
        },
        {
            id = 1687876,
            score = 1,
            author = "902975",
            text = "The visual on the map is incorrect. Dr. Hieronymus Blam is found there at some point, but as a quest-giver for this particular quest, he is located at 47.0, 56.6.\n\nPretty linear for people already on the quest line, but if you're like me and randomly dropped your quests off at this point, it's helpful to know this!",
            date = "2012-07-14T02:37:07-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27889#comments:id=1687876",
        },
    },
    [27890] = {
        {
