    [27898] = {
        {
            id = 1411938,
            score = 23,
            author = "493920",
            text = "The cut scene was horribly bugged for me - the camera stayed pointed squarely at the cave wall the entire time and half the dialogue didn't even appear on screen. Here's a video (http://www.youtube.com/watch?v=8vmyKQwY1rk) of the correct cut scene if you too are wondering what just happened.",
            date = "2011-05-07T04:45:00-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27898#comments:id=1411938",
        },
        {
            id = 1483279,
            score = 8,
            author = "AudibleKnight",
            text = "I had no issues with the cut scene while doing this in 4.2. Here's the text from the cut scene for those who missed it:\n\nRhea says: I'll just leave this right here\nRhea says: How's my little baby doing?\nRhea says: No... it's... it's you! NO!\nDeathwing says: You impetous little whelp... I know exactly what you and mortal are up to.\nAre you ready to die, dragon?\nRhea says: Yes... just show mercy to the egg.\nDeathwing yells: Mercy!\nDeathwing yells: THERE IS NO MERCY! YOU WILL BURN FOR THIS DRAGON!",
            date = "2011-07-30T14:54:32-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27898#comments:id=1483279",
        },
        {
            id = 1652575,
