    [27906] = {
        {
            id = 2356152,
            score = 5,
            author = "ekrietlow",
            text = "If you're like me and enjoy a great quest line, this is for you.\n\n\"Still a better love story than Titanic\"",
            date = "2016-07-24T10:48:13-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27906#comments:id=2356152",
        },
        {
            id = 1592978,
            score = 3,
            author = "304770",
            text = "Need to complete all of https://www.wowhead.com/npc=7623 quests, from https://www.wowhead.com/quest=27853 to https://www.wowhead.com/quest=27857, before this becomes available. If you complete https://www.wowhead.com/quest=27907 or https://www.wowhead.com/quest=27908 first, this will not be available.",
            date = "2011-12-09T02:35:01-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27906#comments:id=1592978",
        },
        {
            id = 2345159,
            score = 3,
            author = "jjanchan",
            text = "I received this quest after completing https://www.wowhead.com/achievement=4904 already.  As such, my only motivation was to continue questing in the zone on the off chance that there may be transmog gear I would get for the new transmog wardrobe in Legion.\n\nBelow is the chain of quests I pursued after https://www.wowhead.com/quest=27906; in essence, there was no transmog gear rewarded by any of them.  As such, there is not much of a point to pursuing them unless you are interested in some meager gold, a bit of story, or have yet to complete https://www.wowhead.com/achievement=4904.\n\nhttps://www.wowhead.com/quest=27906\nhttps://www.wowhead.com/quest=27907\nhttps://www.wowhead.com/quest=27908\n\nhttps://www.wowhead.com/quest=27909\nhttps://www.wowhead.com/quest=27910\n\nhttps://www.wowhead.com/quest=27911 (Rewards the trinket https://www.wowhead.com/item=64627)\nhttps://www.wowhead.com/quest=27916",
            date = "2016-06-26T16:16:15-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27906#comments:id=2345159",
        },
    },
    [27907] = {
        {
            id = 2345160,
            score = 1,
            author = "jjanchan",
