    [27920] = {
        {
            id = 1227325,
            score = 11,
            author = "Freedomage",
            text = "Having trouble turning in quest 'Armed to the Teeth'.\nBloodfang is standing on Baron Silverlain's desk, but without the question mark on him.\nThe minimap shows it up on the West wall near a locked 'Large Iron Bound Chest', but nobody's there.\n\n1. Abandoned the quest, reset the instance and ran it again, same thing.\n2. Left Instance, reset and entered with Bloodfang at the entrance, this worked!\n\np.s. he also gave part 3 of 4 here.",
            date = "2010-12-12T11:09:02-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27920#comments:id=1227325",
        },
        {
            id = 3246531,
            score = 4,
            author = "toxoplasmosis",
            text = "If you're having trouble turning this in (e.g. Bloodfang is standing on Silverlain's desk with no question mark, but it looks like that's where you're supposed to be), just keep progressing through the dungeon. When you pass through Springvale's chamber and up onto the roof, Bloodfang will appear again, this time with the question mark to turn in the quest.",
            date = "2020-11-07T22:02:21-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27920#comments:id=3246531",
        },
        {
