    [27957] = {
        {
            id = 1807565,
            score = 35,
            author = "Karsciyin",
            text = "Trust me Lunk, I would LIKE more quests where we didn't have to kill, kill, kill. I would LIKE to collect herbs without the frickin' deer chasing me for the my blood. I would LIKE to be able to walk for five seconds in any direction without needlessly pissing off a mob.\n\nBut I can't.\nSo kill kill kill kill kill kill....",
            date = "2013-02-01T06:36:43-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27957#comments:id=1807565",
        },
        {
            id = 1909014,
            score = 24,
            author = "Traxus4",
            text = "As angry as he is with you, he still gives you 70 silver.",
            date = "2013-10-15T22:23:20-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27957#comments:id=1909014",
        },
        {
            id = 2464558,
            score = 2,
            author = "swedengamer",
            text = "Heh. I always thought it was weird that in every rpg you play, you have to kill stuff in order to progress, even if you want to play the nicest guy ever. Kill, kill, kill!\nJust slaughter everything in your way and still be called the greatest hero that ever lived!\n\nOn a serious note, I think rp players would like that they can do stuff without killining anyone or anything,",
            date = "2017-01-18T14:52:45-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27957#comments:id=2464558",
        },
        {
            id = 1889907,
            score = -2,
            author = "MABGamer6407",
            text = "Thats Ogre rage for you. An best be lucky that he did't take a massive dump in your house or urinated in your swimming pool. Take Thunk for a example.",
            date = "2013-08-24T23:51:09-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27957#comments:id=1889907",
        },
        {
            id = 1321510,
            score = -6,
            author = "49773",
            text = "Lolwut?",
            date = "2011-02-04T11:31:24-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27957#comments:id=1321510",
        },
    },
    [27958] = {
        {
            id = 1634771,
            score = 4,
            author = "428831",
            text = "To get Prisanne to offer this quest, you have to complete Lunk's first quest, Lunk's Task",
            date = "2012-03-03T23:41:30-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27958#comments:id=1634771",
        },
        {
            id = 1194728,
            score = 3,
            author = "Zyland",
            text = "The best way to complete this quest is while doing this (http://www.wowhead.com/quest=27959) quest.\n\nYou obtain the quest around (59,59) in the Searing Gorge, or West of Grimesilt Digsite.\n\nWhenever Lunk rides a spider for that quest he comes back as a click able object, when clicked you receive two of the needed venom.\n\nLunk wants to ride seven spiders. So that means, 14 Glassweb Venom.",
            date = "2010-11-29T01:01:31-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27958#comments:id=1194728",
        },
        {
            id = 2538683,
            score = 1,
            author = "718098",
            text = "Hmmmm, I've got (14) Glassweb Venom in my pocket & unfortunately, Prisanne Dustcropper - - is no longer an active NPR, so she'll great you & that's it.  NOW, I don't recall if I was able to submit these with a Quest, if so, why would it allow me to OVER-collect them?  So, I'm going to see if it's possible to sell them on the A.H. - - I would guess you can not, because it's a \"non-vendorable\" item as well.",
            date = "2017-12-03T16:08:15-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27958#comments:id=2538683",
        },
    },
    [27959] = {
        {
            id = 2361724,
            score = 184,
            author = "devildog19",
            text = "High level players may want to try using the https://www.wowhead.com/item=137663 as it will take the spiders low enough for Lunk to ride them!",
            date = "2016-08-05T00:31:42-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27959#comments:id=2361724",
        },
        {
            id = 1187339,
            score = 75,
            author = "33023",
            text = "Doing this as a level 80, I had to take my gear off to be able to weaken the Spiders without killing them outright.\n\nSo I ended up naked in the middle of Searing Gorge punching spiders so a pacifist Ogre could jump on their backs and ride them around while yelling.\n\nQuite the surreal experience. :D",
            date = "2010-11-26T10:11:56-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27959#comments:id=1187339",
        },
        {
            id = 1255056,
            score = 43,
            author = "snuzzle",
            text = "Some of the adorable things Lunk says when he spider-surfs:\n\nLunk will ride you now!\n\nSpider tummy time!\n\nLunk ride spider now!\n\nYou hold still, spider!\n\nHa ha ha!\n\nWhen this quest is done at the same time as  A Proper Antivenom (http://www.wowhead.com/quest=27958), Lunk will come back with a large green blob on his stomach. Click it to get a few drops of venom. He will remind you, saying:\n\nHere, you can scrape venom off Lunk's tummy.\n\nHere, I got you this.\n\nLunk got you some venom with his tummy.\n\nSpider left venom on Lunk's tummy. You want?\n\nIf you accidentally kill the spider, or aggro something else and kill it, Lunk gets sad and says:\n\nPlease, no kill when Lunk is around.\n\nLunk, I love you.",
            date = "2010-12-23T15:26:08-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27959#comments:id=1255056",
        },
        {
            id = 2023263,
            score = 40,
            author = "1380320",
            text = "As a level 90 hunter I was able to complete this quest by removing all gear AND spirit rezzing for the Resurrection Sickness.  Worked like a charm.",
            date = "2014-11-02T22:16:18-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27959#comments:id=2023263",
        },
        {
            id = 1242711,
            score = 24,
            author = "698260",
            text = "\"Spider left some venom on Lunk's tummy. You want?\"\n\nlol",
            date = "2010-12-18T08:43:09-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27959#comments:id=1242711",
        },
    },
