    [27964] = {
        {
            id = 1180756,
            score = 180,
            author = "Ainasni",
            text = "Just kill Dark Iron Excavators and Dark Iron Footman until he spawns.\nHe will yell when he spawns:\n\nWhat in hell's name is going on out here?",
            date = "2010-11-24T08:50:54-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27964#comments:id=1180756",
        },
        {
            id = 1181938,
            score = 129,
            author = "Lilithdrff",
            text = "He spawns after about 11-12 kills of the dwarfs in the cauldron area. He emotes when he spawns, and he comes riding in on a black Ram. The amber needed for the quest is lootable from the ground, not from his corpse. I killed him on my 80 Belf priest, and then a lower level Alliance warlock came by and was able to loot the item without having killed Dinwhisker himself.",
            date = "2010-11-24T14:45:43-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27964#comments:id=1181938",
        },
        {
            id = 2138395,
            score = 71,
            author = "mudplayerx",
            text = "After you kill him for the quest, look carefully on the ground next to him and a tiny little red gem will spawn. Easy to overlook and kill these dwarves over and over for an hour if you don't realize it.",
            date = "2015-03-15T13:16:07-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27964#comments:id=2138395",
        },
        {
            id = 5754943,
            score = 38,
            author = "Duck9999",
            text = "This quest is somewhat buggy and can be incredibly frustrating. Here are some tips to ensure you're able to complete it:\n\n1. Enter the Cauldron from the East path leading down. If you enter the zone by jumping down/flying, the game may not properly detect that you've entered the killing zone.\n\n2. It should only take 4-8 kills to spawn the guy, so if you find yourself killing more than that try re-entering the zone.\n\n3. The quest item is not a drop, but rather a clickable item that spawns on the ground after Dinwhisker's death. Pick it up quickly, it despawns after about 30 seconds.\n\n4. If you fail to pick up the quest item, it is unlikely that Dinwhisker will spawn again. Drop the quest and pick it up again from the giver, if you need to take another attempt.",
            date = "2023-12-23T13:07:26-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27964#comments:id=5754943",
        },
        {
            id = 6051613,
            score = 18,
            author = "geekySmurfer",
            text = "DO NOT FLY INTO THE AREA.  You need to fly to the following\nlocation and then walk down killing dwarves until he spawns.\n/way 64.34 37.77\nYou do not need to drop the quest and pick it up again if you fly in.",
            date = "2025-01-19T18:03:53-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27964#comments:id=6051613",
        },
    },
