    [27968] = {
        {
            id = 1890263,
            score = 2,
            author = "92AtRex175",
            text = "If anyone wants MORE c hallenge out of this dungeon, try it by yourself. I have a lvl 33 balance druid worgen , and Godfrey is impossible to defeat. If anyone has any suggestions, I am ALL ears:):)I dont have much money for weapons, tho.So.....",
            date = "2013-08-26T04:01:50-05:00",
