        },
        {
            id = 2190589,
            score = 2,
            author = "1482119",
            text = "I'm trying to twink a starter combat rogue and there's just no way of beating this alone. I only managed to do it by getting in with a group and surviving the enemies. This was also the same with the Eyepatch in the Stormwind dungeon, I recommend people get into a group and just trying your best to contribute.",
            date = "2015-06-05T23:53:07-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27968#comments:id=2190589",
        },
        {
            id = 2538344,
            score = 0,
            author = "navagrey",
            text = "Just got WoW. Level 36 Night Elf Druid. Took about 3 hours to solo this (my first dungeon). I forgot my armor's durability was degrading every time I died. Used Moonglade teleport, repaired armor, used Moonglade teleport again (which teleported me back to the dungeon), and beat it on my first try back. It was tough as hell to solo Godfrey, though.",
            date = "2017-12-02T02:53:58-06:00",
            sourceUrl = "https://www.wowhead.com/quest=27968#comments:id=2538344",
        },
        {
            id = 1519513,
            score = -9,
            author = "692994",
            text = "In order to get credit for killing this guy (and the other guys in the quest chain) you want to hit/tag them first OR do a lot of damage during the fight. On my third try going through the dungeon, I finally figured that out. You can still get credit if you didn't tag the guy first, just go all out with damage and you'll get credit for killing him. He's the last boss, at the end of the dungeon.",
            date = "2011-09-16T16:44:32-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27968#comments:id=1519513",
        },
    },
    [27974] = {
        {
