        {
            id = 2044975,
            score = 156,
            author = "Zidaniel",
            text = "Made a Tom Tom macro.\nFinister is the only one not in the cave.\n\n/way #32 22.4 36.7 Cave Entrance\n/way #32 24.66 26.22 Minister Finister\n/way #32 14.58 36.79 Minister Letherio\n/way #32 17.44 42.81 Minister Kiyuubi",
            date = "2014-11-22T18:56:39-06:00",
