    [27983] = {
        {
            id = 2353923,
            score = 166,
            author = "Zaydene",
            text = "Doesn't appear https://www.wowhead.com/item=137663 work on this quest, unfortunately.\n\nAlthough, casting Moonfire as a druid didn't instantly kill them and if Lunk is close enough he'll put them to sleep.",
            date = "2016-07-20T15:43:45-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27983#comments:id=2353923",
        },
        {
            id = 2372660,
            score = 93,
            author = "Wowzir",
            text = "Shame on you Blizzard... WTF was the https://www.wowhead.com/item=137663 created for?... seems pretty damned LAME that a toy just issued during the pre-patch can't even be used DURING the pre-patch on very low level quests from (what 4?) many Xpacks ago.\n\nOn my ilevel 705 BMH, I found that equipping https://www.wowhead.com/item=4565, running up to the Dwarves (also works for Spiders in https://www.wowhead.com/quest=27959) and giving them a single hit worked fine.  Since I had Auto Attack already on my action bar, I clicked it on and then IMMEDIATYELY off again.\n\nFYI:  the https://www.wowhead.com/item=4565 is sold by a plethora of vendors, but the most convenient might be Gnimo who can be found on the https://www.wowhead.com/spell=61447.  This is still ONE advantage that mount has over the bloated-priced Grand Expedition Yak!",
            date = "2016-08-23T16:49:13-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27983#comments:id=2372660",
        },
