    [27989] = {
        {
            id = 1556795,
            score = 22,
            author = "Kyeld",
            text = "pre-req: https://www.wowhead.com/quest=28100",
            date = "2011-10-29T12:29:50-05:00",
            sourceUrl = "https://www.wowhead.com/quest=27989#comments:id=1556795",
        },
        {
            id = 1182751,
            score = 19,
            author = "181947",
            text = "OMG BEES!\n\nSeriously though...\n\nThe totem gives you a stick to use on the glowing honey pots. The pots are hanging on poles like lanterns. Occasionally when you swipe a pot, a swarm of bees will attack you. There is a pond just inside the front entry to Deadwood Village. Jump into the pond to get the swarm off of you.",
            date = "2010-11-24T19:31:38-06:00",
