    [28035] = {
        {
            id = 6244032,
            score = 8,
            author = "Silvansaria",
            text = "Okay...\nJust hold on............................................................................ This isn't just s simple 'go talk to this dude, grab the quest and voila...'\n\nIf you are like ME - he wasn't offering the quest - which ALSO means - you can't get the house decor items. So what's wrong?\nIt's NOT a phasing issue or a time-phase issue.\n\nIt's a \"quest\" issue...\nSo here is how to solve this problem and gain the 2 house decor items for your house:\n\nDo the quests. ALL the quests - for the Thorium Brotherhood (you can ignore the big ogre quest where he wants to ride spiders and all that jazz. Just ignore him). The quests will take you all over the zone - but only THAT zone. Once you go through them you'll complete THIS quest which unlocks the first item. If you want the second house decor item - you guessed it. Do the rest of the quests - which will end with an achievement for completing Searing Gorge quests and unlock the item for your house.\n\nSo - hope this helps someone with knowing what's going on and enjoy decorating your house with the new items :)",
            date = "2025-12-10T22:42:42-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28035#comments:id=6244032",
