    [28049] = {
        {
            id = 1148728,
            score = 58,
            author = "221044",
            text = "DO THE IMPOSSIBLE (http://cata.wowhead.com/quest=28000), SEE THE INVISIBLE (http://cata.wowhead.com/quest=28049)\nROW ROW FIGHT THE POWAH (http://cata.wowhead.com/quest=28102)\nTOUCH THE UNTOUCHABLE (http://cata.wowhead.com/quest=28044), BREAK THE UNBREAKABLE (http://cata.wowhead.com/quest=28113)\nROW ROW FIGHT THE POWAH (http://www.youtube.com/watch?v=wxX3JkGHmDI)",
            date = "2010-10-20T18:38:59-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28049#comments:id=1148728",
        },
        {
            id = 1632220,
            score = 13,
            author = "motafina",
            text = "To get this quest giver to appear you must complete the quest Do the Imp-Possible (http://www.wowhead.com/quest=28000).",
            date = "2012-02-26T20:38:20-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28049#comments:id=1632220",
        },
        {
            id = 1443380,
            score = 6,
            author = "Tantojutsu",
            text = "FYI Rogues: The https://www.wowhead.com/item=62918 can be pick-pocketed from the ooze mobs (oddly enough).  I obtained two this way.  However, it seems if an ooze has been pick-pocketed, the NPC will not drop another when killed.",
            date = "2011-06-17T13:37:02-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28049#comments:id=1443380",
        },
        {
            id = 2463685,
            score = 4,
            author = "Akitnaya",
            text = "SO...i'm on my 110 hunter main when I did this & this is what happened -\n\nI got there did \"Do the Imp-Possible (http://www.wowhead.com/quest=28000/do-the-imp-possible)\" no problem. Turned it in & Impsy wasn't showing up. I flew all over Felwood hoping it was a phasing thing. After about 10mins, I got on an alt. Did the quest & same thing. No Impsy. A 110 DK came to where Impsy is & grabbed the 2nd quest See the Invisible (http://www.wowhead.com/quest=28049/see-the-invisible)....& I l know he did cuz he started killing oozes as you're suppose to. So I thought maybe if I reload, Impsy will appear. Nope...NADA! Sooo I just closed out of WoW completely, closed on my bnet desktop & everything. Restarted it, signed in & whatd'ya know? That little ^&*! Impsy showed up, wasn't phased & had a quest for me. So I finished the 2nd quest, then 3rd (Touch the Untouchable (http://www.wowhead.com/quest=28044/touch-the-untouchable),) then 4th (Break the Unbreakable (http://www.wowhead.com/quest=28113/break-the-unbreakable),) & lastly the 5th (Open Their Eyes (http://www.wowhead.com/quest=28288/open-their-eyes),) which gives you the Rainbow Generator (http://www.wowhead.com/item=133998/rainbow-generator) that we're all obviously going thru all this trouble for.\n\nThought i'd share in case someone has the same issue. Hope this helped! Thanks.",
            date = "2017-01-16T04:52:04-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28049#comments:id=2463685",
        },
        {
            id = 2550730,
            score = 2,
            author = "Itsversayce",
            text = "If you picked up https://www.wowhead.com/quest=4512 in Ironforge, this is the time to get the Cursed Ooze half of it done.",
            date = "2018-02-05T00:09:29-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28049#comments:id=2550730",
        },
    },
    [28051] = {
        {
            id = 1367019,
            score = 38,
            author = "Jpec07",
            text = "You actually have to work your way up to this quest, as it's part of the series in [zone=400] that you have to go through in Cata as Alliance. It goes as follows:https://www.wowhead.com/quest=25486\nhttps://www.wowhead.com/quest=25504\nhttps://www.wowhead.com/quest=25515\nhttps://www.wowhead.com/quest=25532\nhttps://www.wowhead.com/quest=25542\nhttps://www.wowhead.com/quest=25585\nhttps://www.wowhead.com/quest=28031\nhttps://www.wowhead.com/quest=28045\nAll of these quests are right around level 40, and seem to be pretty straightforward. If you're 85, you'll have no difficulty at all.\n\nJust thought I'd share, 'cause I had the same question (was farming the belt for an armorset).",
            date = "2011-03-14T18:23:10-05:00",
