    [28053] = {
        {
            id = 1245697,
            score = 23,
            author = "162216",
            text = "This quest made me bawwww... :-)",
            date = "2010-12-19T13:22:55-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28053#comments:id=1245697",
        },
        {
            id = 1377725,
            score = 22,
            author = "428831",
            text = "I wanted to get this quest and item for my prot pally and, from what I can figure out, you have to finish Lunk's first quest at Thorium Advance([quest=27956 domain=www]) then the follow-up([quest=27957 domain=www]).\n\nLunk will disappear and then appear as you kill mobs to offer you his adventure quests which are:\n[quest=27959 domain=www]\n[quest=27983 domain=www]\nThese can be completed while doing other quests offered by other NPCs.\n\nHe also has an adventure quest that is part of the main quest line in Searing Gorge\n[quest=28034 domain=www]\nThat chain will open up from the quests in Thorium Point.\nI'm not sure if you need to complete the chain to get the trinket or just up until Lunk's quest in the chain as I had to go back and find the Spider quest after completing the chain to get Lunk to show up. He'll be at Thorium Point for the final trinket quest, not Iron Summit as the map shows.",
            date = "2011-03-27T17:14:04-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28053#comments:id=1377725",
        },
        {
            id = 1321559,
            score = 17,
            author = "49773",
            text = "You know, when I finished all of the quests and got to the banish part and got the \"welcome to the brotherhood\" quest I thought to myself that its all nice and all but what I really liked about this zone is lunk and it is a shame I can't have a memento from him like with Rambo.\n\nAnd then I saw this quest, I was the happiest boy in the world",
            date = "2011-02-04T12:34:36-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28053#comments:id=1321559",
        },
        {
