    [28055] = {
        {
            id = 1188189,
            score = 52,
            author = "Kalila",
            text = "If you kill the slaves that are freed and do not initially attack you, you get double credit.",
            date = "2010-11-26T16:17:16-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28055#comments:id=1188189",
        },
        {
            id = 1187100,
            score = 35,
            author = "173963",
            text = "However, sometimes you will find that slaves are resistant to being freed. It's a strange phenomenon, often called \"Durnholde Syndrome\".\n\nIn our world, this behavior is called Stockholm Syndrome (http://en.wikipedia.org/wiki/Stockholm_syndrome).",
            date = "2010-11-26T08:11:20-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28055#comments:id=1187100",
        },
        {
            id = 1583759,
            score = 16,
            author = "Nasha",
            text = "The slaves say various things when you attempt to free them:\n\nIntruder! The intruder is trying to save me!\nIt's about time! I'm sick of being a slave!\nNever! I love working for the Dark Iron!\nI'll never leave! I wouldn't know what to do outside!\nOh, thank you! Thank you!\nI knew the Thorium Brotherhood would come through!",
            date = "2011-11-29T20:57:11-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28055#comments:id=1583759",
        },
        {
            id = 1646006,
            score = 7,
            author = "Lovestar",
            text = "If you're a ranged class, I find it significantly more efficient to just kill every single slave. Talking to them risks being attacked right in melee range while you're trying to cast.\n\nSimply killing everyone in sight allows you to operate at a nice, safe distance. It's somewhat evil, but honestly, after all the horrible things your character has done in their life — what's a little more evil, especially when it's so convenient?\n\nAlthough you do give up the chance to be told \"Thank you, thank you!\" by surprisingly well-spoken Gnolls.",
            date = "2012-03-29T02:48:31-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28055#comments:id=1646006",
        },
        {
            id = 1687155,
            score = 6,
            author = "Smittles",
            text = "When I was doing this quest, I talked to one slave and then it attacked me. I dragged it over (while beating on it) to the next slave, and freed it. Instead of it turning running away and thanking me, the slave that ALREADY started attacking me did so. And the second slave kept on hitting me. I am bewildered yet amused.",
            date = "2012-07-11T23:00:11-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28055#comments:id=1687155",
        },
    },
    [28056] = {
        {
            id = 1204960,
            score = 22,
            author = "waxxyy",
            text = "Don't get confused guys: Obsidion and Lathoric are inside the quarry, underground.",
            date = "2010-12-03T20:57:38-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28056#comments:id=1204960",
        },
        {
            id = 1383645,
            score = 9,
            author = "elmertar",
            text = "Just go straight ahead and take the door to your left ( if your lucky , there is a rare mob guarding it).\njust go straight to the back of the corridor and there is an open space with a stone in the middle, just touch it and be prepared to kill both mobs at once...",
            date = "2011-04-04T04:26:35-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28056#comments:id=1383645",
        },
        {
            id = 1301285,
            score = 8,
            author = "412874",
            text = "Obsidion was laying down and wouldn't let me aggro to complete quest.  You have to touch stone and wait for the other boss to call him up otherwise you just kill the one boss and can't kill Obsidion.",
            date = "2011-01-20T02:03:27-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28056#comments:id=1301285",
        },
        {
            id = 1633126,
            score = 4,
            author = "959900",
            text = "This quest was REAL bugger. Died 3 times but finally got it as a Lvl 50 Lock. Anyway, Evonice Smootsmoker is up a ramp to the right (with the altar on your left) in the same room where Obsidion and Lathoric are. Coords are: 43.8, 28.5.",
            date = "2012-02-28T23:58:35-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28056#comments:id=1633126",
        },
        {
            id = 1646758,
            score = 4,
            author = "929109",
            text = "After picking up the quests, take the first door to the left. After taking care of the slavers, taskmasters and freeing the slaves, continue inward. A large stone will be there that you need to touch. You should be able to see Obsidion on the floor. After destroying these two, take the ramp up on the opposite side of the room. There you will find Evonice Sootsmoker for your quest turn-ins.",
            date = "2012-03-30T19:38:44-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28056#comments:id=1646758",
        },
    },
