    [28058] = {
        {
            id = 1239209,
            score = 78,
            author = "552706",
            text = "That's what she said.",
            date = "2010-12-16T20:27:00-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28058#comments:id=1239209",
        },
        {
            id = 1261458,
            score = 62,
            author = "wharris",
            text = "When you first loot a pillow, a timer starts. After a few minutes a group of sleepy dark iron workers spawn. A few minutes later, a second group spawns. A few minutes after that, the chambermaid spawns. Of course, by this time most players have long since turned in the quest and moved on.\n\nDeleting and re-looting pillows is not necessary -- the only thing it accomplishes is keeping you in the area while the timer continues to run.",
            date = "2010-12-27T06:43:10-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28058#comments:id=1261458",
        },
        {
            id = 2536648,
            score = 32,
            author = "CronoLink",
            text = "If you, like me, haven't completed this quest for whatever reason:\n-Go to Searing Gorge\n-49.9, 46.1 enter the cave\n-Go straight, keeping to your right, then take the 1st right; the tunnel should now look like where the dwarves rest, with bedrolls and stuff. Aside from regular mobs, this is where the maid spawns.\n-If she's not spawned, check the other comments here that talk about it. Once you kill her, she physically drops a blue, square pillow. Just click on it to get the quest.\n-Go outside the quest to Thorium Point to deliver quest.\n\nHope this helps.",
            date = "2017-11-24T02:04:10-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28058#comments:id=2536648",
        },
        {
            id = 2500399,
            score = 22,
            author = "glassleo",
            text = "According to my chat log:\n\n24 seconds after looting the first Pillow, the first group of Sleepy Dark Iron Workers spawned.\n4 minutes and 42 seconds after that, the second group spawned.\n4 minutes and 39 seconds after that, Chambermaid Pillaclencher spawned.",
            date = "2017-06-12T22:25:13-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28058#comments:id=2500399",
        },
        {
            id = 3120966,
            score = 21,
            author = "PhotoGruffer",
            text = "As someone who enjoys following up with missed quests, I really wanted to do this one. But because I handed in the quest called \"Kill 'em With Sleep Deprivation (https://www.wowhead.com/quest=28057/kill-em-with-sleep-deprivation)\", this pillow won't spawn now.  So, make sure when you are doing the quest where you collect dark iron pillows, to wait around for awhile for a few waves of dwarf spawns before you leave to hand in.\n\n...or maybe get a friend to come do the quest and you both can loot the pillow then.",
            date = "2019-05-01T16:18:58-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28058#comments:id=3120966",
        },
    },
    [28060] = {
        {
            id = 1195447,
            score = 14,
            author = "Vesper",
            text = "Well Hansel did punch Twilight-Lord Arkkus over the side but I did not get credit for the kill, as caster I was at max range and engaged Maltorius.\n\nAfter waiting for respawns I did kill them both and got credit for the kill this time.\nSo stay close to Hansel when he engages Arkkus",
            date = "2010-11-29T10:40:23-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28060#comments:id=1195447",
        },
        {
            id = 1639280,
            score = 11,
            author = "chexmixultimate",
            text = "The corridor the quest mentions is the one OPPOSITE the two guys you just killed. Just follow that all the way through.",
            date = "2012-03-14T02:43:06-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28060#comments:id=1639280",
        },
        {
            id = 1511659,
            score = 10,
            author = "567472",
            text = "Despite the above comments, I had trouble finding him at first to turn in this quest.  He is INSIDE the slag pit, but you must go back out the way you came in (unless there's an inside path I didn't find).  The coordinates for the entry to the slag pit you must enter to be able to reach him are:  47.5/47.0\n\nEnter the pit and turn right.  He'll be standing on a ledge not far from the entry point.",
            date = "2011-09-06T19:45:20-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28060#comments:id=1511659",
        },
        {
            id = 1185960,
            score = 4,
            author = "227735",
            text = "Pretty straight forward.  Hansel humorously punches the nightelf twilight ambassador over the side. While Maltorius did bubble and polymorphed Hansel.",
            date = "2010-11-25T21:05:04-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28060#comments:id=1185960",
        },
        {
            id = 1187635,
            score = 4,
