            text = "Look left as you cross the se bridge and you will see Oilfist.  jump  down or use your new shinny trinket to reach him quickly.",
            date = "2010-11-26T12:38:20-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28060#comments:id=1187635",
        },
    },
    [28061] = {
        {
            id = 1196517,
            score = 5,
            author = "195183",
            text = "You don't turn it in, it will auto complete for you upon completion.\n\nUnfortunately, I killed Archduke at 49 (for the quest), but this quest didn't open up for me until level 50. Blizzard should fix this because most people are going to just have to go back down there unless they are 50 or higher and just now doing this quest chain.\n\nThe fact the quest to kill Archduke is open at level 49, but the quest to kill the things standing between you and him are only available at level 50 tells you it needs to be reevaluated to smooth out leveling.",
            date = "2010-11-29T20:30:37-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28061#comments:id=1196517",
        },
        {
            id = 1908875,
