    [28064] = {
        {
            id = 1418856,
            score = 27,
            author = "212274",
            text = "For those of you looking for the start of this very long questline, I finally found the start at the little camp called Thorium Advance on the eastern edge of Searing Gorge.  If you start there, it will eventually lead you to Mountain Lord Rendan and his quests which end with this one.\n\nAfter this quest you can turn in dark iron residue for Thorium rep.",
            date = "2011-05-14T19:13:29-05:00",
