    [28069] = {
        {
            id = 5370461,
            score = 3,
            author = "Kamraten",
            text = "This quest popped up for me suddenly in Burning Steppes, surprisingly since I was sure I had done every quest in Eastern Kingdom a couple of years back.\nI found out the reason it popped up now was that some quests was level-locked, meaning they disappeared once you reached a certain level (in this case I think lvl 61). With the new level squish in Shadowlands, the quest like this became available for max level players.\n\nIf you want to complete this quest as completionist, make sure to do so before you level beyond lvl 60 in upcoming expansions, although should be possible to complete with Party Sync feature.",
            date = "2022-05-06T16:39:15-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28069#comments:id=5370461",
        },
    },
