    [28114] = {
        {
            id = 1185537,
            score = 122,
            author = "246278",
            text = "This is the most disgusting Quest I've ever seen.",
            date = "2010-11-25T17:32:37-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28114#comments:id=1185537",
        },
        {
            id = 1182355,
            score = 65,
            author = "blupache",
            text = "Kill the bears, the eggs are the infestation on their back & need to be looted separately from the bear corpse.\n\nI've gotta admit, I never thought Bliz would add something quite this grotesque into game. I'm somewhere between nauseated & intrigued. This one'll certainly have any arachnophobes running screaming to another quest zone.",
            date = "2010-11-24T16:58:23-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28114#comments:id=1182355",
        },
        {
            id = 1193863,
            score = 37,
            author = "106952",
            text = "Yes, this is grose and disgusting, but! After I overcame that initial \"eeeeuwww\" feeling, I tamed one of those bears, being a forsaken hunter after all. To my sadness, when you tame the bear, the eggs dissappear, else this would have been the ultimate psychological warfare pet for Pvp!",
            date = "2010-11-28T16:08:15-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28114#comments:id=1193863",
        },
        {
            id = 1193161,
            score = 30,
            author = "Catcubus",
            text = "I think the thing that grossed me out about this quest the most was, not the fact you had to scrape eggs off a bears ass. Nah. It was the fact the egg clusters on the bear's ass looked like botfly larva clusters.\n\nHere's a fun image for you to get the picture!\nhttp://dailyparasite.blogspot.com/2010/06/june-29-gasterophilus-intestinalis.html\n\nFun!",
            date = "2010-11-28T11:21:30-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28114#comments:id=1193161",
        },
        {
            id = 1513852,
            score = 29,
            author = "rowaasr13",
            text = "You can loot https://www.wowhead.com/item=3173 from them. Bon appétit!",
            date = "2011-09-09T11:59:49-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28114#comments:id=1513852",
        },
    },
    [28115] = {
        {
            id = 1202705,
            score = 28,
            author = "233551",
            text = "Absolutely 100% the grossest quest in the game.\nKill them and then collect the eggs off their back.\nGAG!  /vomit",
            date = "2010-12-02T18:03:54-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28115#comments:id=1202705",
        },
        {
            id = 1204847,
            score = 19,
            author = "407365",
            text = "Bears are soulless beasts put upon this earth to torment us.\n\nBears are GODLESS KILLING MACHINES!",
            date = "2010-12-03T19:37:44-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28115#comments:id=1204847",
        },
        {
            id = 1187252,
            score = 16,
            author = "467137",
            text = "This is disturbing on so many levels, though I have to wonder why it is deemed necessary to put the bears down when they are considered \"soulless beasts\". It seems more logical for them to just be killed off by the horrific infestation they have to live through.\n\nDefinitely not a quest for the squeamish. I felt sorry for the bears and destroyed eggs on carcasses that weren't my own kills ... This quest? Do not want.",
            date = "2010-11-26T09:34:29-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28115#comments:id=1187252",
        },
        {
            id = 1360862,
