            text = "Ewwwwwwwwwwwwwwwwwwwwwwwwwwwwwwwwwwwwwwwwwwwwwwwwwwwwwwwwwww.\n\nDisgusting bubble butt bear asses!\n\nGross.",
            date = "2010-11-24T13:45:07-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28115#comments:id=1181726",
