    },
    [28116] = {
        {
            id = 1424274,
            score = 24,
            author = "cameroncorner",
            text = "If you have Carbonite Addon don't go by the area it shows on the Carbonite map.  Alt + M and look at the normal WOW map for the location.  They are really easy to spot once you are in the correct area. LOL\n\nNow to vacuum up the hair on the floor that I pulled out...",
            date = "2011-05-21T23:30:39-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28116#comments:id=1424274",
