    [28119] = {
        {
            id = 1461671,
            score = 37,
            author = "Brokinarrow",
            text = "Quest text on this one should really read \"Hey, turn around and go into that green moonwell behind you and fill this thing up for me\".  Seemed like my map marker was off a bit and made me think the moonwell was actually in Shadow Hold.",
