    [28121] = {
        {
            id = 1190732,
            score = 14,
            author = "389430",
            text = "This guest sucks due to the limited spawn, and the longer spawn time.  If two or more people are in the area, better have come cooking or bandages to make to pass the time.\n\nEdit: If your looking for the majority of the adepts and cultists, check the Shrine of the Devicer, it's immediatly  on your left when you enter the area.   Spawn time sucks there too though.",
            date = "2010-11-27T14:51:20-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28121#comments:id=1190732",
        },
        {
            id = 6231790,
            score = 1,
            author = "Florentpraha",
            text = "At this moment Andalar Shadevale is not visible due to content in Jaedenar for 80 lvl. So there is no way how to return quest and go forward.",
            date = "2025-11-23T06:46:53-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28121#comments:id=6231790",
        },
        {
            id = 1633673,
            score = -1,
            author = "Rhynchelma",
            text = "This quest should be done with Crying Violet (http://www.wowhead.com/quest=28116).\n\nThey are both turned in to  Andalar Shadevale (http://www.wowhead.com/npc=51664) at 36.36,58.26.\n\nThe NPC gives you Purity From Corruption (http://www.wowhead.com/quest=28119) and when you turn that in he gives The Demon Prince (http://www.wowhead.com/quest=28129), The Inner Circle (http://www.wowhead.com/quest=28128), Dousing the Flames of Protection (http://www.wowhead.com/quest=28126).\n\nNow enter Shadow Hold and continue the chain.\n\nTwin Temptresses (http://www.wowhead.com/quest=28131).\nShadow Lord Fel'dan (http://www.wowhead.com/quest=28153).\nLord Banehollow (http://www.wowhead.com/quest=28155).\n\nThen exit through the portal.\n\nTurn in Lord Banehollow (http://www.wowhead.com/quest=28155), Dousing the Flames of Protection (http://www.wowhead.com/quest=28126) and The Inner Circle (http://www.wowhead.com/quest=28128) and you are then offered The Fate of Bloodvenom Post (http://www.wowhead.com/quest=28305) unless you have accepted A Slimy Situation (http://www.wowhead.com/quest=28207) previously.",
            date = "2012-03-01T07:05:06-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28121#comments:id=1633673",
        },
    },
    [28124] = {
