    [28126] = {
        {
            id = 1835949,
            score = 46,
            author = "Zylostout",
            text = "Entrance to Shadow Hold: 36, 58\n\n1. Pain, same room as Prince Xavalis, 36.96, 55.89\n2. Hatred, up the ramp behind the Prince, 37.17, 54.89\n3. Suffering, 37.40, 53.05, if you get to the red pool with the Vile Ooze you have gone too far, look in the room just before that pool\n4. Malice, 38.25, 52.55, same room as Suffering\n\nAll of the braziers are before Salia & Moora",
            date = "2013-03-28T19:41:42-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28126#comments:id=1835949",
        },
        {
            id = 1346336,
            score = 17,
            author = "Jacko",
            text = "The first one is in the first room, where the prince is. The 2nd is just up the stairs. The 3rd is in the room with a small pond of water, and yeah, the 4th aswell.",
            date = "2011-02-22T17:35:03-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28126#comments:id=1346336",
        },
        {
