    [28128] = {
        {
            id = 1470265,
            score = 24,
            author = "Jadeshade",
            text = "Just in case anyone else got sidetracked and couldn't find this place here the cords.\nCords: 36.2; 58.3\nThe entrance is next to Andalar Shadevale ([npc=51664 domain=www]) the quest starter.\nThis is a ultra casual comment, but I got sidetracked and couldn't find this place for like 20mins.",
            date = "2011-07-14T23:11:14-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28128#comments:id=1470265",
        },
        {
            id = 1614847,
            score = 14,
            author = "939194",
            text = "Before this quest becomes available, you must have completed:\n\nForces of Jaedenar https://www.wowhead.com/quest=28121\nCrying Violet https://www.wowhead.com/quest=28116\nPurity from Corruption https://www.wowhead.com/quest=28119",
            date = "2012-01-22T05:36:25-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28128#comments:id=1614847",
        },
        {
            id = 1367389,
            score = 2,
            author = "771379",
            text = "I think they tweaked it.  Cause before the Twin Temptresses room I had this complete.  Good luck to everyone!\n\ndrew",
            date = "2011-03-15T06:34:09-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28128#comments:id=1367389",
        },
        {
            id = 1604144,
            score = 2,
            author = "93453",
            text = "This quest has changed a bit with Cataclysm - it's now part of a fairly straightforward chain that takes place inside a cave complex.\n\nKill anything in the complex for The Inner Circle (http://www.wowhead.com/quest=28128) and make sure to check for braziers for Dousing the Flames of Protection (http://www.wowhead.com/quest=28126) while going through the cave. Along the way you'll go through this chain killing named mobs:\nThe Demon Prince (http://www.wowhead.com/quest=28129)\nTwin Temptresses (http://www.wowhead.com/quest=28131)\nShadow Lord Fel'dan (http://www.wowhead.com/quest=28153)\nLord Banehollow (http://www.wowhead.com/quest=28155)\n\nAfter you're all done, there's a port out to the quest givers, and then you pick up The Fate of Bloodvenom Post (http://www.wowhead.com/quest=28305) to move on with the zone.",
            date = "2011-12-30T11:53:20-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28128#comments:id=1604144",
        },
        {
            id = 2859814,
            score = 1,
            author = "mudplayerx",
            text = "This quest shows up on your map if you are in the Darkshore Warfront in the Battle for Azeroth expansion if you have \"trivial quests\" checked on your minimap. This quest has nothing to do with the Warfront and cannot be completed.",
            date = "2018-12-17T02:07:10-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28128#comments:id=2859814",
        },
    },
    [28129] = {
        {
            id = 1198344,
            score = 10,
            author = "237274",
            text = "You must finish the quest Forces of Jaedenar (http://www.wowhead.com/quest=28121) to be able to enter Shadow Hold -- once you've killed the required mobs, you'll automatically be able to turn in the quest from your current location and pick up the follow up in that chain.  Once you've done that, you'll be in the correct phase and able to see Shadow Hold.",
            date = "2010-11-30T16:39:50-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28129#comments:id=1198344",
        },
        {
            id = 1347289,
            score = 4,
            author = "794832",
            text = "As of now, you have to turn all the quests and stuff to Greta's field assistant.",
            date = "2011-02-23T13:55:59-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28129#comments:id=1347289",
        },
        {
            id = 1191452,
            score = 3,
            author = "466912",
            text = "He is located inside Shadow Hold, the first open area after you get inside.  Coords - 36.55",
            date = "2010-11-27T19:47:53-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28129#comments:id=1191452",
        },
        {
            id = 1604146,
            score = 3,
            author = "93453",
            text = "This quest is part of a family of quests in this same cave complex.\n\nKill anything in the cave for The Inner Circle (http://www.wowhead.com/quest=28128) and make sure to check for braziers for Dousing the Flames of Protection (http://www.wowhead.com/quest=28126) while going through the cave. Along the way you'll go through this chain killing named mobs:\nThe Demon Prince (http://www.wowhead.com/quest=28129)\nTwin Temptresses (http://www.wowhead.com/quest=28131)\nShadow Lord Fel'dan (http://www.wowhead.com/quest=28153)\nLord Banehollow (http://www.wowhead.com/quest=28155)\n\nAfter you're all done, there's a port out to the quest givers, and then you pick up The Fate of Bloodvenom Post (http://www.wowhead.com/quest=28305) to move on with the zone.",
            date = "2011-12-30T11:56:12-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28129#comments:id=1604146",
        },
        {
            id = 1195792,
