            text = "I cannot do this quest on my Tauren paladin because I get stuck in the doorway... no joke. Did anyone else get stuck?",
            date = "2010-11-29T13:30:21-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28129#comments:id=1195792",
        },
    },
