        },
        {
            id = 1208425,
            score = 56,
            author = "423555",
            text = "Be sure to talk to some of the guards while in the disguise, some lines are hilarious:\n - \"There's a little blood on your armor, are you okay?\"\n - \"Keep your eyes peeled, they say that freak that was attacking people earlier might still be around.\"",
