            sourceUrl = "https://www.wowhead.com/quest=28136#comments:id=1208425",
        },
        {
            id = 1353320,
            score = 30,
            author = "16212",
            text = "One of the 'chats' the defenders have will ask where Grom-grom is, describing him as \"an orc, about this tall\".  Most likely, they are referring to the dead orc Lakota killed to get her gear.",
            date = "2011-02-28T15:42:23-06:00",
