    [28140] = {
        {
            id = 1279504,
            score = 26,
            author = "Scotia",
            text = "Why the heck are we freeing her? If you're Horde, I think you know by now that she's responsible for Cairne's death.  If you're Alliance, well... you just fought a bunch of Grimtotems on your way to get here, and they were hell bent on killing you.\n\nShe's evil. She should stay tied up. I don't get it. What am I missing?",
            date = "2011-01-05T22:57:43-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28140#comments:id=1279504",
        },
        {
            id = 1691045,
            score = 13,
            author = "Sooba",
            text = "I don't want to free her :( She killed Cairne (and she used Garrosh Hellscream for it!), she tried to murder Baine, she tried to take over the entire tauren community...\n\nBlegh. I want the loremaster but I just don't like these kinds of quests.",
            date = "2012-07-22T11:50:38-05:00",
