            text = "If you've removed this quest, but come back later to get the tmog. (Like I did)\nHere is where u get the quest back at \"https://www.wowhead.com/npc=10646\"\nHer location for me was Twilight Bulwark at the \"harbor\" location, north of the world map text.",
            date = "2020-05-06T11:44:35-05:00",
