    [28144] = {
        {
            id = 1340117,
            score = 36,
            author = "Apolocyntosis",
            text = "With Garrosh putting the squeeze on Sylvanas not to use the plague anymore, the Forsaken have completely shut down their plague production and distribution operations, right? Right.",
            date = "2011-02-17T18:32:02-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28144#comments:id=1340117",
        },
        {
            id = 1308452,
            score = 32,
            author = "cribby",
            text = "What are these \"supplies\" you speak of? To add to the mystery, the tooltip reads \"The \"supplies\" look empty.\" The icon (http://www.wowhead.com/item=63082) is a barrel with green ..  goo. I had to look it up.\n\nThe breadcrumb (http://www.wowhead.com/quest=28111) to get this quest comes from from Darthalia (http://www.wowhead.com/npc=2215). Pre Cataclysm, she was under the direct command of Vaimathras who was pretty much Sylvana's 2nd in command, albeit a sketchy one. Of course, we now know that he (http://www.wowhead.com/npc=2425/varimathras) and Putress (http://www.wowhead.com/npc=31530) were the controlling force of the ambush at the wrathgate (http://www.wowhead.com/quest=13242/darkness-stirs).\n\nLysander (http://www.wowhead.com/npc=24126) once said: \"Not long after Arthas condemned us to this wretched existence, we in the Royal Apothecary Society endeavored to create a plague of our own. A plague that would devour all flesh: living, dead or undead.\"\n\nThis quest looks to be yet another link in our clueless involvement of plague quality testing.\n\nHere's a fun, happy read: http://www.wowpedia.org/New_plague\n\nHave a nice day!",
            date = "2011-01-24T19:10:55-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28144#comments:id=1308452",
        },
        {
            id = 2222117,
            score = 1,
            author = "BloodMage2020",
            text = "\" Moving 'supplies' like this around is a risky proposition. You never know who is going to open their big fat mouth.\"\n\nYou got something to say Keyton?",
            date = "2015-07-28T11:19:16-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28144#comments:id=2222117",
        },
        {
            id = 2510444,
            score = -1,
            author = "Kaerfemagsh",
            text = "these \"supplies\" were full of methane gas, then the murlocs stole them & released the gas so they filled them with their own methane gas...",
            date = "2017-07-26T23:56:53-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28144#comments:id=2510444",
        },
    },
    [28146] = {
        {
            id = 2553711,
            score = 17,
            author = "Ryazan",
            text = "STILL a bit buggy the better part of a decade later... While your spider doesn't need to get the killing blow, it does appear to have to attack the murloc. One of the spider's attacks looks like a shadowbolt-type thing, and sometimes I would kill the murlocs before it got a cast off if I wasn't careful. This could account for the kills it didn't eat before I started paying closer attention.\n\nJust keep an eye on the spider and make sure it gets a couple of attacks in and you should be good to go.",
            date = "2018-02-18T21:29:31-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28146#comments:id=2553711",
        },
        {
            id = 1196071,
            score = 14,
            author = "wbalmung",
            text = "I don't know about anyone else, but this quest was a bit buggy for me. My spider wouldn't eat certain murlocs, even if I stood right next to it. And yes, I killed them myself, your spider won't eat other peoples murlocs.",
            date = "2010-11-29T16:30:54-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28146#comments:id=1196071",
        },
        {
            id = 1890504,
            score = 12,
            author = "Locclo",
            text = "If any hunters are having issues with this quest like I did, dismiss your pet first. For some reason, the spider will only sometimes eat the corpses if your pet is out.",
