    [28153] = {
        {
            id = 1912049,
            score = 5,
            author = "764313",
            text = "Wish I knew how to get this guy's outfit.",
            date = "2013-10-25T20:00:58-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28153#comments:id=1912049",
        },
        {
            id = 1350649,
            score = 4,
            author = "780917",
            text = "Fastest way:\n\nOnce you kill the girls and obtain the quest, leave their room via a little down-spiraling passageway. Kill the dog-demon at the end, go left and pass the knight directly on your right. You'll have to kill a couple of mages in that ramp that leads to his room.\n\nSoloed with a lvl 51 mage using a fishing pole. :-)",
            date = "2011-02-26T09:20:10-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28153#comments:id=1350649",
        },
        {
            id = 1604148,
            score = 1,
            author = "93453",
            text = "This quest is part of a family of quests in this same cave complex.\n\nKill anything in the cave for The Inner Circle (http://www.wowhead.com/quest=28128) and make sure to check for braziers for Dousing the Flames of Protection (http://www.wowhead.com/quest=28126) while going through the cave. Along the way you'll go through this chain killing named mobs:\nThe Demon Prince (http://www.wowhead.com/quest=28129)\nTwin Temptresses (http://www.wowhead.com/quest=28131)\nShadow Lord Fel'dan (http://www.wowhead.com/quest=28153)\nLord Banehollow (http://www.wowhead.com/quest=28155)\n\nAfter you're all done, there's a port out to the quest givers, and then you pick up The Fate of Bloodvenom Post (http://www.wowhead.com/quest=28305) to move on with the zone.",
            date = "2011-12-30T11:57:24-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28153#comments:id=1604148",
        },
        {
            id = 6193929,
            score = 1,
            author = "Raincloud",
            text = "Kill the NPC, go to the end and kill Banelow and then get the portal out. Quickest way to get out",
            date = "2025-10-03T13:31:21-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28153#comments:id=6193929",
        },
    },
    [28154] = {
        {
            id = 1196185,
            score = 70,
            author = "414797",
            text = "Little did Captain Keyton know, but in an alternate future where Muckgill was never killed, he united the disparate murloc bands into an almighty empire.  Using them, he forced the savage Makrura into submission to the Empire and assaulted the Naga, slaying Queen Azshara and bringing the surviving Naga under his flipper (or something).\n\nHe then turned his attentions to Neptulon, slaying the great Elemental Lord and taking his trident, empowering himself to become Muckgill, Elemental Lord of Water.  With his great army of murloc, Naga, Makrura and elementals, he swept over Azeroth in an unstoppable tide, mightier than the Scourge had ever been, and submerged Kalimdor, Northrend and the Eastern Kingdoms beneath the Great Sea.\n\n... Or something.",
            date = "2010-11-29T17:28:06-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28154#comments:id=1196185",
        },
        {
            id = 1185851,
            score = 38,
            author = "101807",
            text = "We didn't need that fourth wall anyway.",
            date = "2010-11-25T20:04:26-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28154#comments:id=1185851",
        },
        {
            id = 1181384,
            score = 29,
            author = "499453",
            text = "This is the very first quest in WoW that actually made me laugh out loud. Just the same thing we've been wondering forever, amplified.",
            date = "2010-11-24T11:55:45-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28154#comments:id=1181384",
        },
        {
            id = 1188665,
            score = 20,
            author = "zingar",
            text = "he doesn't seem to care but he still rewards you ^^",
            date = "2010-11-26T19:35:32-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28154#comments:id=1188665",
        },
        {
            id = 1338380,
            score = 17,
            author = "Kendrubbin",
            text = "This quest requires you to kill Muckgill, found on the south-western Hillsbrad Coast... Or something.",
            date = "2011-02-16T10:34:06-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28154#comments:id=1338380",
        },
    },
    [28155] = {
        {
            id = 2514074,
            score = 122,
            author = "Aldristavan",
            text = "As of the date of this comment, the portal to Wildheart Point still doesn't work.",
            date = "2017-08-17T20:42:46-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28155#comments:id=2514074",
        },
        {
            id = 2858665,
            score = 68,
            author = "Sydni",
            text = "On killing Fel'dan, the quest popped up but automatically removed itself from my log when trying to Accept it. Killing Banehollow did nothing, so it wasn't a hidden flag quest either.\nHad to hearth instead of backtracking through the entire den as there was no return portal to pick it up from Andalar again.\n\nThe Wildheart Point portal acts very strangely.\nOn killing Banehollow, the portal (or any Arcanist NPC) will not spawn if you just sit by his spawn. The portal only appears if you seemingly run across the North-West bridge and back in a short amount of time (as Banehollow respawns in about a mintue).\nYou have to run nearly all the way to the little wooden hovel and back again for it to spawn, and even that seems to be random. Kiting him to the middle of this bridge gives you some time.\n\nAfter all that? As of 8.1 you cannot click the Wildheart Point portal even if you get it to spawn. There is no Arcanist NPC or anything.\n\nTrying to go across the bridge back to the Felguards has no \"no time limitation\" portal as mentioned in another comment. Your options after killing this boss are to either hearth and fly back to Jaedenar, or suffering backtracking through the entire hollow.",
            date = "2018-12-13T21:59:40-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28155#comments:id=2858665",
        },
        {
            id = 2562204,
            score = 44,
            author = "Kelindre",
            text = "Going through this quest again on the allied races. Still F'd up after all these years.  Can't believe it.",
            date = "2018-04-10T06:22:26-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28155#comments:id=2562204",
        },
        {
            id = 3238138,
            score = 42,
            author = "sk4p",
            text = "Portal still broken in 9.0.1.",
            date = "2020-10-14T07:49:12-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28155#comments:id=3238138",
        },
        {
            id = 5253162,
