    [28168] = {
        {
            id = 1634398,
            score = 7,
            author = "ercanrua",
            text = "Had to complete Coastal Delicacies (http://www.wowhead.com/quest=28146) from Spider-Handler Sarus before Keyton gave me this quest.",
            date = "2012-03-03T02:40:14-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28168#comments:id=1634398",
        },
        {
            id = 1188175,
            score = 6,
            author = "Earthproxy",
            text = "This area used to be the site of \"The Battle for Hillsbrad\", a long questchain from Tarren Mill. Many of the undead NPCs were human quest targets.",
            date = "2010-11-26T16:13:17-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28168#comments:id=1188175",
        },
        {
            id = 1989460,
            score = 4,
            author = "Worgarix",
            text = "This place is the aushwitz of wow. I went there once to quest and i still got the chills of seeing humans planted in the fields with their heads popping out and the ghouls eating. Hillsbrad isnt what it used to be thats for sure. This place is feking horrific and it is the reason i hat and always will hate the forsaken.",
            date = "2014-08-07T18:57:13-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28168#comments:id=1989460",
        },
        {
            id = 3190035,
            score = 3,
            author = "Isolte",
            text = "I believe that completing https://www.wowhead.com/quest=28138 is necessary before https://www.wowhead.com/npc=47554 will give you this quest. I can't personally confirm this sadly because https://www.wowhead.com/quest=28138 requires you to get the mobs down to 35% health before using the quest item to \"capture\" them, and doing this as a level 120, you just one-shot kill them even if you're completely naked. (So I can't complete this quest without recruiting help from a lowbie.)",
            date = "2020-02-13T02:13:11-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28168#comments:id=3190035",
        },
        {
            id = 1187877,
