            score = 5,
            author = "309256",
            text = "As soon as you accept this quest, a S.A.F.E. Operative spawns and starts moving quickly to the south. If you aren't paying attention, you might not see him. Just head straight south along the main pathway, go up the stairs, and veer slightly to the east and you'll reach the Loading Room.\n\nThis quest leads to Decontamination (http://www.wowhead.com/quest=27635).",
            date = "2011-06-07T00:10:27-05:00",
