    [28172] = {
        {
            id = 1698119,
            score = 29,
            author = "metal80sguy",
            text = "There are no green in the first area you come to.  Go to the next valley over and there are several.  (In and around the cave)",
            date = "2012-08-09T23:02:05-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28172#comments:id=1698119",
        },
        {
            id = 1204179,
