        {
            id = 1710483,
            score = 3,
            author = "QuickBASIC",
            text = "The drop rate is not so good on these... expect to kill at least 20 https://www.wowhead.com/npc=9691. Circle around the back side of the hill where they're thicker. Combine with https://www.wowhead.com/quest=28178 there's tons of https://www.wowhead.com/npc=9690 behind the hill too.",
            date = "2012-09-07T06:48:21-05:00",
