    [28189] = {
        {
            id = 1190487,
            score = 149,
            author = "Guzz",
            text = "Not that it's a difficult quest in the first place but you can speed it up ever so slightly.\n\nSimply right-click on a \"seedling\" to remove the trapped human from the dirt. Once he's out, right click on your shovel to kill him.\n\nCredit for 2 \"saved\" humans, for the low price of one!",
            date = "2010-11-27T13:05:18-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28189#comments:id=1190487",
        },
        {
            id = 1202825,
            score = 124,
            author = "5605",
            text = "This quest isn't available until you do No One Here Gets Out Alive (http://www.wowhead.com/quest=28192), which itself is a chain starting from the beginning of the zone starting from Welcome to the Machine (http://www.wowhead.com/quest=28096). (About ~6 quests)",
            date = "2010-12-02T19:22:52-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28189#comments:id=1202825",
        },
        {
            id = 1191108,
