            author = "139511",
            text = "Hah!\n\nAnd I thought Northrend quests were dark. You even hear them screaming. Not to mention their heads explode if you hit them with the shovel.\n\nOverall the entire Forsaken questline is really grim stuff even by non-WoW standards. Not that that's a bad thing.",
            date = "2010-11-27T17:35:38-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28189#comments:id=1191108",
        },
