            sourceUrl = "https://www.wowhead.com/quest=28189#comments:id=1187906",
        },
        {
            id = 1184399,
            score = 66,
            author = "314933",
            text = "To the best of my knowledge at the time of this posting this is the only quest in all of WoW that gives players a choice between doing good or evil, much like a traditional RPG. Blizzard once again proves that, when it comes to quests, there is virtually no limit to what they can and are willing to do.",
            date = "2010-11-25T09:40:23-06:00",
