    [28192] = {
        {
            id = 1299444,
            score = 15,
            author = "Drillakilla",
            text = "Totally surprised no one has recognized that the quest title is the title of Jim Morrison's biography \"No One Here Gets Out Alive (http://en.wikipedia.org/wiki/No_One_Here_Gets_Out_Alive)\". My age is showing, I guess.",
            date = "2011-01-18T17:13:58-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28192#comments:id=1299444",
        },
        {
            id = 1811571,
            score = 8,
            author = "Frostybolts",
            text = "The way this quest works is you accept it, then you watch a cool video automatically\n\n... UNLESS you're on a multi-person mount, in which case you accept the quest, then you get an objective, \"Assess the situation\".  Then you ride around for a few minutes, looking at everything going on, and the objective doesn't get fulfilled, until you abandon the quest and re-accept it while not mounted.",
            date = "2013-02-09T22:33:16-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28192#comments:id=1811571",
