            text = "Draenei  - (4,1,3)\n\n4Hides\n1Mud\n3 Threads\n\nNight Elves - (3,2,1)\n\n3Hides\n2Muds\n1Thread\n\nDwarfs - (4,2,2)\n\n4Hides\n2Muds\n2Threads\n\nHuman - (2,4,2)\n\n2Hides\n4Muds\n2Threads\n\nGnomes - (1,3,4)\n\n1Hides\n3Muds\n4Threads",
            date = "2010-12-02T06:59:56-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28205#comments:id=1201774",
        },
        {
            id = 1737804,
            score = 20,
            author = "1044636",
            text = "For a panda monk you need\n4,hide\n1,mud\n3,Thread",
            date = "2012-10-10T18:27:50-05:00",
