    [28217] = {
        {
            id = 1629032,
            score = 29,
            author = "Azerious",
            text = "\"I'll pay top bounty for proof of this murderer's death.\"\n\nQuest rewards: 70 silver\n\ntop bounty, huh?",
            date = "2012-02-19T14:18:38-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28217#comments:id=1629032",
        },
        {
            id = 1209127,
            score = 15,
            author = "204493",
            text = "The quest is not immediately accessible for anyone just wanting to swing through.\n\nYou have to begin with several quests down in Emerald Sanctuary. The quests will lead upward through Felwood's quest hubs until you come to Whisperwind Grove.\n\nComplete Tender Puregrove's 3 quests to phase in Huntress Selura.",
            date = "2010-12-05T21:00:36-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28217#comments:id=1209127",
        },
        {
            id = 1609483,
            score = 13,
            author = "Niamh",
            text = "How to get to those nice  blue rewards:\n\n1) https://www.wowhead.com/quest=28360 & https://www.wowhead.com/quest=28361\n2) https://www.wowhead.com/quest=28374 (https://www.wowhead.com/item=65289, https://www.wowhead.com/item=65308, https://www.wowhead.com/item=65327, https://www.wowhead.com/item=65340)\n\n3) https://www.wowhead.com/quest=28229\n4) https://www.wowhead.com/quest=28219 & https://www.wowhead.com/quest=28220 (https://www.wowhead.com/item=65286)\n5) https://www.wowhead.com/quest=28221 & https://www.wowhead.com/quest=28222\n6) https://www.wowhead.com/quest=28224\n7) https://www.wowhead.com/quest=28228 (https://www.wowhead.com/item=65287, https://www.wowhead.com/item=65306, https://www.wowhead.com/item=65325)\n\n8) https://www.wowhead.com/quest=28217\n9) https://www.wowhead.com/quest=28218\n10) https://www.wowhead.com/quest=28256\n11) https://www.wowhead.com/quest=28257 (https://www.wowhead.com/item=65284, https://www.wowhead.com/item=65304, https://www.wowhead.com/item=65323)\n12) https://www.wowhead.com/quest=28261\n13) https://www.wowhead.com/quest=28264 (https://www.wowhead.com/item=65285, https://www.wowhead.com/item=65305, https://www.wowhead.com/item=65324)\n\n14) https://www.wowhead.com/quest=28381\n15) https://www.wowhead.com/quest=28382 (https://www.wowhead.com/item=65341, https://www.wowhead.com/item=65290, https://www.wowhead.com/item=65309, https://www.wowhead.com/item=65328) & https://www.wowhead.com/quest=28383\n16) https://www.wowhead.com/quest=28384\n17) https://www.wowhead.com/quest=28337\n\n18) https://www.wowhead.com/quest=28385 & https://www.wowhead.com/quest=28386 (https://www.wowhead.com/item=65342, https://www.wowhead.com/item=65291, https://www.wowhead.com/item=65310, https://www.wowhead.com/item=65329)\n19) https://www.wowhead.com/quest=28388 & https://www.wowhead.com/quest=28387\n20) https://www.wowhead.com/quest=28389 (https://www.wowhead.com/item=65292, https://www.wowhead.com/item=65311, https://www.wowhead.com/item=65330)\n\nNote: 3) https://www.wowhead.com/quest=28229 and 8) https://www.wowhead.com/quest=28217 can be picked up simultaneously.\n\n(moved from reply to normal post, as the new system displays larger replies rather weird)",
            date = "2012-01-10T01:59:32-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28217#comments:id=1609483",
        },
        {
            id = 2417625,
            score = 10,
            author = "Demiona",
            text = "Now after the release of Legion, this feels like a pleasant little Easter egg. Feronas yells, \"Blind fool! You have no idea what you are doing!\" and he's most definitely right. If you want some nice flavourful quests to give more depth to your DH's backstory, I recommend picking up this chain :)",
            date = "2016-09-29T14:31:44-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28217#comments:id=2417625",
        },
        {
            id = 1188698,
            score = 9,
            author = "708409",
            text = "This starts off a quest chain that is not well linked because each time you finish a quest Feronas despawns and respawns with the next quest.\n\nEventually it leads to Navarax's Gambit (http://www.wowhead.com/quest=28264).",
            date = "2010-11-26T19:50:01-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28217#comments:id=1188698",
        },
    },
    [28218] = {
        {
            id = 1184260,
            score = 83,
            author = "lynchsta",
            text = "Cool and interesting quest, unfortunately the quest text doesn't really tell you what to do.  You get to watch Illidan and Arthas fight.  Pretty cool.  I sat back and read the dialogue and took some screen shots.  When the battle ended, I got a \"quest failed\" message.  Huh?   I didn't know I was supposed to do anything.\n\nSo I grabbed the quest again and this time, I engaged Arthas.  Once his health gets down to a certain point, there is more dialogue and the quest completes.\n\nIf you want to watch the battle a couple of times, feel free.  If you just want to do the quest and get it over with, start beating up on Arthas.   Nice little piece of lore here.  :-)",
            date = "2010-11-25T08:52:14-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28218#comments:id=1184260",
        },
        {
            id = 1202307,
            score = 32,
            author = "Umega",
            text = "I love it when Blizzard show some cutscenes from Warcraft 3. I'm dissapointed that they didn't add the speech files from it though.\nYou can see the actual WC3 campaign here (http://www.youtube.com/watch?v=RVxOrlBe5Us) that references this quest chain.",
            date = "2010-12-02T14:13:09-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28218#comments:id=1202307",
        },
        {
            id = 1209635,
            score = 25,
            author = "196807",
            text = "Illidan and Arthas appear and face off each other.\n\nIllidan Stormrage says: I am free after ten thousand years, yet still my own brother thinks I am a villain! I'll show him my true power! I'll show him that the demons have no hold over me!\nArthas says: Are you certain of that, demon hunter? Are you certain your will is your own?\nIllidan Stormrage says: You reek of death, human. You'll regret approaching me.\nArthas says: Come then. You'll find that we're evenly matched.\n\nAfter you help to bring Arthas health down (if Illidan dies, you fail the quest and have to restart):\n\nIllidan Stormrage says: We could go on fighting like this forever. What is it you truly want?\nArthas says: The dreadlord who commands this undead army is called Tichondrius.  He controls a powerful warlock artifact called the Skull of Gul'dan.  It is responsible for corrupting these forests.\nIllidan Stormrage says: And you wish for me to steal it. Why?\nArthas says: Let's just say that I have no love for Tichondrius, and the lord I serve would... benefit from the Legion's downfall.",
            date = "2010-12-06T05:06:25-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28218#comments:id=1209635",
        },
        {
            id = 1423787,
            score = 16,
            author = "celixi",
            text = "Would also make the whole cinematic more epic if they added in the voice chat like they were in wc3 during the quest",
            date = "2011-05-21T09:37:38-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28218#comments:id=1423787",
        },
        {
            id = 1504359,
            score = 15,
            author = "391278",
            text = "Quests like this have always struck me as a little strange. If we're there to witness a past event; what sense does it make that we are required to engage it? How the heck am I \"attacking\" a manifestation of Arthas? Why would I need to?",
            date = "2011-08-27T04:19:18-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28218#comments:id=1504359",
        },
    },
    [28219] = {
        {
            id = 1419719,
            score = 12,
            author = "719456",
            text = "Great! another companion to pour my heart into! Damn you blizz!",
            date = "2011-05-15T18:08:59-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28219#comments:id=1419719",
        },
        {
            id = 1688487,
            score = 6,
            author = "512738",
            text = "When you kill a buzzer, the seedling will eject a very thick vine from itself (from it's face?) and attach it to the buzzer, much like a frog's tongue shooting out to kill a fly. A little creepy.",
            date = "2012-07-15T15:22:08-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28219#comments:id=1688487",
        },
        {
            id = 1464565,
            score = 4,
            author = "853106",
            text = "You can grow these to huge size, by continue to kill Buzzers.",
            date = "2011-07-08T13:47:51-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28219#comments:id=1464565",
        },
        {
            id = 1201269,
            score = 3,
            author = "Zyland",
            text = "Worth noting is that you don't actually need to wait for the seedling to eat the mobs.\n\nAll that matters is the mob dieing.\n\nYou can just nuke 10 down quickly and finish the quest just the same.\n\nUpon completion, the seedling turns into a Sapling.\n\nEdit: Spelling.",
            date = "2010-12-01T23:26:12-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28219#comments:id=1201269",
        },
        {
            id = 1427866,
            score = 2,
            author = "78590",
            text = "The way this thing feeds scares the ^&*! out of me.\n\nAnyone that's seen the movie \"The Ruin\" will agree.",
            date = "2011-05-26T07:52:21-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28219#comments:id=1427866",
        },
    },
    [28220] = {
        {
            id = 5155135,
            score = 39,
            author = "PrairieChicken",
            text = "It is hard to see but look in the dark patches (parts without the grass).\n\nOr if you are feeling lazy and annoyed just copypasta:\n\n/way 49.37 28.99\n/way 50.21 28.02\n/way 47.63 28.84\n/way 48.03 27.54\n/way 48.82 28.17\n/way 49.38 29.00\n/way 50.01 30.19\n/way 48.10 31.19\n/way 49.34 30.68\n/way 48.31 29.17",
            date = "2021-04-18T03:15:43-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28220#comments:id=5155135",
        },
        {
            id = 1217729,
            score = 34,
            author = "infrarett",
            text = "You can resummon the Seedling Protector (and his later iterations) if you die, abandon the quest, or hearthstone out of the area; just go back to the hilly island with the \"petrified\" watchers where you initially picked up the quest, and the little guy reappears and is ready to go again.",
            date = "2010-12-09T07:33:29-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28220#comments:id=1217729",
        },
        {
            id = 5737438,
            score = 12,
            author = "snaeks",
            text = "If you're having trouble seeing the piles of soil amidst all the grass you can turn the slider for Ground Clutter all the way to the left to remove all grass sprites. This makes the soil stand out much, much more.\n\nOpen the game's options\nClick Graphics near the bottom in the options window\nScroll down to Ground Clutter in the Graphics Quality section",
            date = "2023-11-28T07:53:03-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28220#comments:id=5737438",
        },
        {
            id = 1856451,
            score = 9,
            author = "1122360",
            text = "where start the quest? i have abandon it but i can't find it again",
            date = "2013-05-23T09:29:45-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28220#comments:id=1856451",
        },
        {
            id = 1581289,
            score = 8,
            author = "Djsedj",
            text = "I find this little guy so cute :B",
            date = "2011-11-26T18:08:47-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28220#comments:id=1581289",
        },
    },
    [28221] = {
        {
            id = 1186613,
            score = 15,
            author = "238581",
            text = "As you kill the Stompers, your treant will grow... and there's nothing stopping you from killing a couple hundred in order to take up a good portion of your view. Unfortunately, it phases out when you leave this area of Felwood, so you can't really impress your friends with the size of your wood.",
            date = "2010-11-26T03:10:05-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28221#comments:id=1186613",
        },
        {
            id = 1195892,
            score = 9,
            author = "LifeWillEnd",
            text = "These boots we're made for walkin'!\nThats just what they'll do!",
            date = "2010-11-29T14:23:40-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28221#comments:id=1195892",
        },
        {
            id = 1197818,
            score = 7,
            author = "695181",
            text = "The title of the quest is a reference to Nancy Sinatra's \"These Boots Are Made For Walking\" (1966)\n\n (http://www.youtube.com/watch?v=yRkovnss7sg)",
            date = "2010-11-30T12:43:05-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28221#comments:id=1197818",
        },
        {
            id = 1358084,
            score = 3,
            author = "194639",
            text = "And that's just what they'll do!\nOne of these days these roots are gonna stomp all over you!",
            date = "2011-03-05T07:30:37-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28221#comments:id=1358084",
        },
        {
            id = 1677882,
            score = 1,
            author = "Rumbuddy",
            text = "I really thought the completion text was adorable.",
            date = "2012-06-18T00:16:42-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28221#comments:id=1677882",
        },
    },
    [28222] = {
        {
            id = 1354121,
            score = 39,
            author = "Haphasto",
            text = "If you're like me, and hearthed out of the area before attempting this quest and can't get your sapling back, simply go to the hill in the middle of the petrified trees, log out then log back in, within a few seconds of logging back in your sappling should appear.",
            date = "2011-03-01T12:15:27-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28222#comments:id=1354121",
        },
        {
            id = 1708306,
            score = 25,
            author = "CptAwesome771",
            text = "My sapling was doing something really strange as well:\nHe'd follow me into the sunbeam, and then start running away from me -- always running directly to 50.2, 28\nOnly then would he stop to cast his spell, and only then would I get the credit. Weird.",
            date = "2012-09-02T15:45:24-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28222#comments:id=1708306",
        },
        {
            id = 1274131,
            score = 9,
            author = "ryanbarr",
            text = "My Sapling Protector decided he would sit near a lake and stop following me after three beams. After getting fed up with trying to make him follow me, I continued on to the other two sunbeams which, for whatever reason, were still registered to complete the quest.",
            date = "2011-01-02T22:41:32-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28222#comments:id=1274131",
        },
        {
            id = 1705944,
            score = 8,
            author = "TheSonicGod",
            text = "Do this quest separately from \" http://www.wowhead.com/quest=28221#. \"\n\nFor some reason, they interfere with each other, generating two Saplings, which confounds the script.\n\nWhat I did is I finished the first quest, logged out, deleted my caches, logged back in, then accepted the quest Singin' in the Sun. After which, my sapling followed me to the sunlight where I took him. He instantly turned direction. FOLLOW the Sapling down south a few paces. He will stop and wave his arms in the air (casting a spell). This will give you credit for the quest. Repeat this 4 more times.\n\nThis quest is a weird one... not sure if a bug or something bizarre.",
            date = "2012-08-29T21:01:01-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28222#comments:id=1705944",
        },
        {
            id = 1256151,
            score = 7,
            author = "RappScallion",
            text = "The title of the quest is obviously a reference to the classic musical \"Singin' in the rain\" from 1952.",
            date = "2010-12-24T05:43:43-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28222#comments:id=1256151",
        },
    },
    [28224] = {
        {
