        {
            id = 1930663,
            score = 14,
            author = "scott",
            text = "I don't understand why https://www.wowhead.com/npc=48126 can't walk 2 yards into the Moonwell himself to fill the https://www.wowhead.com/item=63332 before giving this quest to adventurers.  He's standing right there!  He should have a nice supply of https://www.wowhead.com/item=63387 ready to go!",
            date = "2014-01-01T00:04:03-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28229#comments:id=1930663",
        },
        {
            id = 1200244,
            score = 2,
            author = "jespa",
            text = "I had the same missing turn-in problem using QuestGuru.  You need to abandon the quest, logoff and disable the QuestGuru Tracker part of the addon, then re-do the quest.  The addon cannot currently handle the new auto-complete quest functionality that is built into the standard Blizzard quest objective UI.\n\nSince most of the quests in this chain use this feature, I would advise just leaving the addon disabled for the whole chain, up to Rejoining The Forest (http://www.wowhead.com/quest=28228)",
            date = "2010-12-01T13:21:52-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28229#comments:id=1200244",
        },
    },
