            text = "This quest is currently bugged. If Quartermaster Kaoshin is not there, you'll most likely have to ask a GM to complete the quest for you.",
            date = "2016-07-25T13:36:42-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28239#comments:id=2356812",
