    [28246] = {
        {
            id = 1201281,
            score = 4,
            author = "715998",
            text = "If you miss the discovery quest for some reason, you can obtain the quest from Colonel Troteman in Chiselgrip - right across the way from The Pillar of Ash",
            date = "2010-12-01T23:36:03-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28246#comments:id=1201281",
        },
        {
            id = 1197067,
            score = 3,
            author = "ziberia",
            text = "This quest \"pops\" up while you are doing Grunt Work (http://www.wowhead.com/quest=28245). You don't have to talk to anyone.",
            date = "2010-11-30T03:16:50-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28246#comments:id=1197067",
        },
        {
            id = 1197760,
            score = 3,
            author = "141466",
            text = "Gorlop was not immediately there when I arrived at his spot (the lava pool + altar behind Worgmistress Othana). I walked around between the pool and altar a few times and he appeared toward the east and came running over.",
            date = "2010-11-30T12:09:22-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28246#comments:id=1197760",
        },
        {
            id = 1246887,
            score = 2,
            author = "524964",
            text = "You need to stay in the disguise for this one. It's cake.",
            date = "2010-12-20T00:54:59-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28246#comments:id=1246887",
        },
        {
            id = 1238272,
            score = 1,
            author = "267562",
            text = "Make sure you use the quest item (http://www.wowhead.com/item=63350)!  I hadn't died questing in about 30 levels, and after meleeing down Gorlop and Voodooist Timan on my feral druid I tried to clear out a few worgs and then pull Worgmistress Othana, but the other worgs always came and they hit hard since they have to kill her after you stab her with the quest item.  So unless you are high enough level, use the quest item on at least her.",
            date = "2010-12-16T12:36:50-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28246#comments:id=1238272",
        },
    },
