        {
            id = 2305244,
            score = 3,
            author = "1456400",
            text = "I don't know about Horde but, in Alliance, in order to accept this quest, you need to be wearing https://www.wowhead.com/item=63357.\n\nIf you don't have it in your bags, go to Chiselgrip and find https://www.wowhead.com/npc=48001 at 45.4, 46.1.\n\nRight next to him, there's a table and you must click on it. Take 4 hides, 1 mud and 3 threads, and talk to him.\nHe will give you your disguise.\n\nUse it, and then you can accept this quest at 45.3,51.4.\n\nSome of the kodos will attack you.",
            date = "2016-02-08T11:21:04-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28252#comments:id=2305244",
        },
    },
