    [28256] = {
        {
            id = 1209639,
            score = 18,
            author = "196807",
            text = "Illidan appears and looks at the Skull of Gul'dan (http://www.wowhead.com/item=32483) in the distance.\n\nIllidan Stormrage says: That is where the skull of Gul'dan is being kept! These paltry demons will not prevent me from claiming it!\n\n3 waves of demons spawn. Illidan defeats them.\n\nIllidan Stormrage says: Now at least the demons will no longer corrupt the forests. But, if I claim this power as my own, I will become stronger than any of Archimonde's lieutenants.\nIllidan Stormrage says: Yes... the power should be mine!\n\nIllidan picks up the skull and transforms into a demon.\n\nIllidan Stormrage yells: Now I am complete!",
            date = "2010-12-06T05:11:05-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28256#comments:id=1209639",
        },
        {
            id = 1191896,
            score = 14,
            author = "Tsaza",
            text = "Next quest: The Fall of Tichondrius (http://www.wowhead.com/quest=28257)",
            date = "2010-11-27T23:43:48-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28256#comments:id=1191896",
        },
        {
            id = 1254778,
            score = 8,
            author = "516760",
            text = "In this quest I helped fight the deamons and the quest completed.",
            date = "2010-12-23T12:59:47-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28256#comments:id=1254778",
        },
        {
            id = 1369194,
            score = 3,
            author = "Dawnrider",
            text = "Great quest, but unfortunately for people like me Blizz ruined it. Arthas is shown in full Lich King armor, but at the time he told Illidan of the skull he was still just a Death Knight, and didnt have the Lich Kings armor on yet.",
            date = "2011-03-17T10:49:45-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28256#comments:id=1369194",
        },
        {
            id = 1904106,
            score = 3,
            author = "735486",
            text = "One of those things where they were making a quest too high-tech and ruined it.  I fought the demons, saw him turn evil, blah blah blah said skull obtained (complete).  I walked back to talk to the quest guy and he turned around and started fighting somebody else who was just starting the quest chain.  I didn't quite know what to do and since I didn't want to stand around all day waiting, I started riding away.  As soon as I got a few yards away it said failed.  Now I have a quest in my log complete and failed.",
            date = "2013-09-29T23:07:55-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28256#comments:id=1904106",
        },
    },
    [28257] = {
        {
            id = 1209648,
            score = 57,
            author = "196807",
            text = "Illidan and Tichondrius appear and face off each other.\n\nTichondrius says: What? Who are... you?\nIllidan Stormrage says: Let's see how confident you are against one of your own kind, dreadlord.\n\nAfter you help to defeat Tichondrius, Malfurion and Tyrande appear.\n\nMalfurion Stormrage says: Foul demon! What have you done with my brother?\nIllidan Stormrage says: It is I, Malfurion. This is what I've become.\nTyrande Whisperwind says: No! Illidan, how could you?\nIllidan Stormrage says: The leader of the undead has been destroyed, and the forests will heal in time.\nMalfurion Stormrage says: At the cost of your soul? You are no brother of mine! Begone from this place, and never set foot in our lands again!\nIllidan Stormrage says: So be it... brother.",
            date = "2010-12-06T05:25:03-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28257#comments:id=1209648",
        },
        {
            id = 1169933,
            score = 53,
            author = "Baracuda",
            text = "Excuse me a moment *Leaves room*\nF**********CK YEEEEEEEEEAAAAAAAAH!",
            date = "2010-11-13T11:38:02-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28257#comments:id=1169933",
        },
        {
            id = 1169780,
            score = 32,
            author = "Suzaku",
            text = "A recreation of the battle from A Destiny of Flame and Sorrow (http://www.wowpedia.org/A_Destiny_of_Flame_and_Sorrow), the penultimate mission of the Night Elf Campaign in Warcraft III: Reign of Chaos, taking place shortly before the Battle for Mount Hyjal. Following this encounter, Illidan was exiled from the night elf lands by his brother, Malfurion.",
            date = "2010-11-13T08:26:41-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28257#comments:id=1169780",
        },
        {
            id = 1610788,
            score = 26,
            author = "892984",
            text = "To all who wonders, Tichondrius was appointed as 'leader of Scourge' by Archimonde in the middle of WC3. Archimonde believed, seeing that the Legion has already begun the invasion, that he wouldn't need Ner'Zhul anymore.\n\nNobody cared about that, of course >,>",
            date = "2012-01-13T12:48:52-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28257#comments:id=1610788",
