        {
            id = 1372910,
            score = 8,
            author = "perculia",
            text = "Consider holding onto this quest if you are a cloth-wearer and can spare the XP. The quest item gives the effect of wearing the Cursed Vision of Sargeras (http://www.wowhead.com/item=32235) from Black Temple, which cloth-wearers cannot equip. While it only activates in Jadefire Run, it's definitely a unique look your mage, priest, or warlock can't find elsewhere.",
            date = "2011-03-21T17:30:37-05:00",
