    [28264] = {
        {
            id = 1204952,
            score = 35,
            author = "313171",
            text = "If you are Tauren, you will need pygmy oil to get through the door, as it is too small.  Thanks, Blizzard!",
            date = "2010-12-03T20:52:42-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28264#comments:id=1204952",
        },
        {
            id = 1451750,
            score = 33,
            author = "336631",
            text = "This quest opens the possibility for Demon Hunters becoming available as a class. There will most likely be a Burning Legion expansion, and cases like this one could become more frequent then, and the Demon Hunters would be required to see through the disguises.\n\nWhile at that, it doesn't mean Demon Hunters will ever become a playable class, it just opens the possibility for it, should Blizzard want to grab it.",
            date = "2011-06-27T05:37:42-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28264#comments:id=1451750",
        },
        {
            id = 1365225,
            score = 25,
            author = "746012",
            text = "Umm, as a warning to others doing this quest... do NOT stand by the door when he turns aggro, he'll knock you right through it (and in my case, out of the tree entirely.) Had to run all the way back up and wait for him to respawn (he despawns if you don't kill him right away.) Arrgh.",
            date = "2011-03-12T18:05:41-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28264#comments:id=1365225",
        },
        {
            id = 1188686,
            score = 13,
            author = "708409",
            text = "Unlocks The Denmother (http://www.wowhead.com/quest=28381).\n\nStart of this quest chain is actually Wanted: The Demon Hunter (http://www.wowhead.com/quest=28217).\nIt doesn't get linked together very well here because the questgiver despawns and respawns in between each quest.",
            date = "2010-11-26T19:46:31-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28264#comments:id=1188686",
        },
        {
            id = 1283611,
            score = 11,
            author = "Strudels",
            text = "Xaravan is enslavable, and will not respawn until whoever Enslaved him dismisses him or he is killed.\n\nTips on enslaving:\n\nTo keep him permanently, you will not be able to turn in the quest. If you want to turn in the quest and enslave him, simply kill him the first time and then Enslave him on respawn - only then can you turn in the quest (he'll then become unenslavable).\n\nXaravan is a large Satyr creature, level 48, with 3 main abilities:\n- Sinister Strike (Instant, melee): 110% weapon damage. Requires a weapon\n- Curse of Agony (Instant, 30yd range): Shadow damage over 15 seconds. Costs 226 mana\n- Claw Swipe (instant, melee): Does melee damage and knocks nearby enemies away.\n\nOddly enough, he can't use the first two abilities (he has no weapons and no mana). He spams Claw Swipe, which has a roughly 6 second cooldown. His melees hit for around 70 damage each.\n\nTL;DR - NOT worth enslaving, Kroshius from a previous quest chain is a much better (and cooler) pet who actually does a decent amount of damage.",
            date = "2011-01-08T07:19:43-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28264#comments:id=1283611",
        },
    },
    [28265] = {
        {
            id = 1426661,
            score = 28,
            author = "537739",
            text = "So again, if you lose your disguise look in your bag. It's a red swatch of cloth called Blackrock Disguise. It's not at the tailoring table or with the tailor. You have to check your inventory. =)",
            date = "2011-05-25T02:31:01-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28265#comments:id=1426661",
        },
        {
            id = 1949196,
            score = 8,
            author = "Real2Reel",
            text = "If you can't use the table and the disguise isn't in your bags, make sure you haven't put it in your bank.",
            date = "2014-03-07T20:47:29-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28265#comments:id=1949196",
        },
        {
            id = 1238262,
            score = 7,
            author = "267562",
            text = "I had to complete the 3 quests given by Stebben Oreknuckle nearby (Prove Yer Allegiance (http://www.wowhead.com/quest=28225) and Scrapped Golems (http://www.wowhead.com/quest=28226) together and then Golem Training (http://www.wowhead.com/quest=28227)) for this to become available, even though I had done the previous quests in this chain.",
            date = "2010-12-16T12:32:49-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28265#comments:id=1238262",
        },
        {
            id = 1262498,
            score = 7,
            author = "wharris",
            text = "Guide to Burning Steppes quests:\n\nOptional breadcrumbs:\nHero's Call: Burning Steppes (http://www.wowhead.com/quest=28666) or Mouton Flamestar (http://www.wowhead.com/quest=28514)\n\nDo anytime before leaving to Chiselgrip:\nDone Nothing Wrong (http://www.wowhead.com/quest=28172)\n\nKeeshan is back with either:\n    Burning Vengeance (http://www.wowhead.com/quest=28416) if you did the Redridge chain or Burning Vengeance (http://www.wowhead.com/quest=28174) if you did not.\n\nThese three at once:\n  Stocking Up (http://www.wowhead.com/quest=28177)\n A Future Project (http://www.wowhead.com/quest=28178)\n Mud Hunter (http://www.wowhead.com/quest=28179)\n\nThen:\nThe Sand, the Cider, and the Orb (http://www.wowhead.com/quest=28180)\n\nThese two at once: Warlocks Have the Neatest Stuff (http://www.wowhead.com/quest=28181) and Shadow Boxing (http://www.wowhead.com/quest=28182)\n\nThen:\nReturn to Keeshan (http://www.wowhead.com/quest=28183)\nChiselgrip, the Heart of the Steppes (http://www.wowhead.com/quest=28184)\n\nEnables these quests, which must be completed before General Thor'izog in the main chain:\nProve Yer Allegiance (http://www.wowhead.com/quest=28225)\nScrapped Golems (http://www.wowhead.com/quest=28226) (leads to Golem Training (http://www.wowhead.com/quest=28227))\n\nMain chain continues:\nA Needle in a Hellhole (http://www.wowhead.com/quest=28254)\nA Perfect Costume (4 versions) Read the quest carefully. What creature disguise do you need?\n  --->    Orc (http://www.wowhead.com/quest=28202) (given to Humans and Dwarves): 2 Hides, 4 muds, 2 thread\n  --->    Goblin (http://www.wowhead.com/quest=28204) (given to Gnomes): 1 hide, 3 mud, 4 thread\n  --->    Troll (http://www.wowhead.com/quest=28205) (given to Night Elves): 3 Hides, 2 mud, 1 thread\n  --->    Ogre (http://www.wowhead.com/quest=28203) (given to Draenei and Worgen): 4 Hide, 1 Mud, 3 thread\n\nThen:\nInto the Black Tooth Hovel (http://www.wowhead.com/quest=28239)\nGrunt Work (http://www.wowhead.com/quest=28245)\n  Look in your quest log -- Strategic Cuts (http://www.wowhead.com/quest=28246) has silently appeared\nThe Kodocaller's Horn (http://www.wowhead.com/quest=28252)\nTaking the Horn for Ourselves (http://www.wowhead.com/quest=28253)\nUntil Blizzard fixes it, when you turn in this quest, you will get a failed quest sound\n  with \"You don't meet the requirements for that quest\". Don't panic.\n\nYou must by this time have finished Stebben's quests, listed above.\nGeneral Thorg'izog (http://www.wowhead.com/quest=28265)\nTrial by Magma (http://www.wowhead.com/quest=28266)\nI Am the Law and I am the Lash (http://www.wowhead.com/quest=28278) [I think this completing this one is optional]\n  When you accept the above, look for Abuse of Power (http://www.wowhead.com/quest=28279) in your quest log\n\nThen:\nEnough Damage for One Day (http://www.wowhead.com/quest=28286)\nMorgan's Vigil (http://www.wowhead.com/quest=28310)\n\nCompleting that quest allows for these four together:\nSEVEN! YUP! (http://www.wowhead.com/quest=28415) [rewards Tiny Flamefly (http://www.wowhead.com/item=66080)]\nBlackened Ashes (http://www.wowhead.com/quest=28311)\nA Heap of Delicious Worg (http://www.wowhead.com/quest=28313)\nLatent Demons of the Land (http://www.wowhead.com/quest=28312)\n\nThen these three together:\nBlood Tour (http://www.wowhead.com/quest=28314)\nDraconic Vanguard (http://www.wowhead.com/quest=28315)\nA Deal with a Dragon (http://www.wowhead.com/quest=28316)\n\nGiven when third one above is completed: Placing the Pawns (http://www.wowhead.com/quest=28326)\n\nThen these three:\nA Delivery for Thorg'izog (http://www.wowhead.com/quest=28317)\nA Delivery for Neeralak (http://www.wowhead.com/quest=28318)\nA Delivery for Zi'lun (http://www.wowhead.com/quest=28319)\n\nAuto-accepted when above three are done:\n Locked and Loaded (http://www.wowhead.com/quest=28327)\n\nAnd the epic conclusion:\nAssault on Dreadmaul Rock (http://www.wowhead.com/quest=28320)\nGlory Amidst Chaos (http://www.wowhead.com/quest=28321)\nThe Spoils of War (http://www.wowhead.com/quest=28322)",
            date = "2010-12-27T18:07:26-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28265#comments:id=1262498",
        },
        {
            id = 1346048,
            score = 7,
            author = "794077",
            text = "Abandon quest and go to the table to make the costume again.",
            date = "2011-02-22T12:22:03-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28265#comments:id=1346048",
        },
    },
