    [28278] = {
        {
            id = 1955239,
            score = 25,
            author = "JanisS",
            text = "I had the error message \"you can't do that yet\" and after reading the comments, I reapplied my disguise, and then you have to go up the troops and right click on the cudgel in your backpack or it won't allow you to hit anyone.",
            date = "2014-04-01T07:05:57-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28278#comments:id=1955239",
        },
        {
            id = 1401746,
            score = 18,
            author = "entropicdragon",
            text = "Time-saving tip: if you get the \"You've been spotted!\" message, you will receive an \"Unmask (http://www.wowhead.com/spell=89596)\" buff that counts down the seconds till you are unmasked.\n\nYou can simply right-click on the \"Unmask\" buff icon in the upper-right hand corner to remove it--and the unmasking will be cancelled.",
            date = "2011-04-27T16:20:32-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28278#comments:id=1401746",
        },
        {
            id = 1196130,
            score = 12,
            author = "336610",
            text = "One of the funnier quests since 4.0.3!  You can cudgel any of the orcs multiple times very fast. About 5-6 swings will kill them. The sound effects that accompany it are great. Boink! Boink! Bop!",
            date = "2010-11-29T17:00:30-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28278#comments:id=1196130",
        },
        {
            id = 1277355,
            score = 10,
            author = "createdbyx",
            text = "I had this quest in my log but never completed it. I did all the quests up to The Spoils of War (http://www.wowhead.com/quest=28322) but when I came back to do this quest I did not have the disguise in by inventory.\n\nI returned to the guy that gives you the disguise used the table and he gave me another one. But now when I try to use the disguise it just says \"You can't do that right now.\"\n\nSo I think you need to complete this quest before completing all the quests in the area. Preferably right after you get it.",
            date = "2011-01-04T16:22:14-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28278#comments:id=1277355",
        },
        {
            id = 1322290,
            score = 8,
            author = "215030",
            text = "It is in your inventory. It's icon of a piece of torn red cloth. I totally forgot about it, thank you other people for telling me that :)",
            date = "2011-02-05T04:35:25-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28278#comments:id=1322290",
        },
    },
    [28279] = {
        {
            id = 1810353,
            score = 64,
            author = "363646",
            text = "On Ally side this quest is indeed bugged got also the message \" you can't do that yet\", i tried to kill them the normal way, this did not do the trick for me.\nAfter that, i found out i needed to unwear the mask and put it on again, that did the trick for me.\nSo my guess is, that it got bugged, once you held on the mask accepting the quest, something like that.",
            date = "2013-02-07T12:22:35-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28279#comments:id=1810353",
        },
        {
            id = 1193705,
            score = 45,
            author = "lisaroxy",
            text = "This quest becomes available while you do the quest \"I am the law and I am the lash\" which is given to you by General Thorg'izog (http://www.wowhead.com/npc=48133).  Abuse of Power is the \"beginning\" of the quest chain needed to get the Tiny Flamefly (http://www.wowhead.com/item=66080) pet but in reality you must start many steps prior.  The actual beginning of the chain that allows you to take Abuse of Power is at John J. Keeshan (http://www.wowhead.com/npc=47811), at (17.28, 52.04) Flamestar Post in Burning Steppes.  You must do all the quests available at Flamestar, then move with Keeshan to Chiselgrip and do all the quests there, which will finally send you to talk to Thorg'izog.  The entire chain took me a couple of very enjoyable hours at level 80.\n\nAlso - this area is a miner's paradise!  In the time I spent on these quests I gained over 80 mithril and 10 gold ore as a nice bonus to my flamefly.",
            date = "2010-11-28T15:20:59-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28279#comments:id=1193705",
        },
        {
            id = 1262478,
            score = 36,
            author = "wharris",
