            text = "THIS QUEST IS BUGGED!\n\nIf you're having trouble with this quest or \"I am the law and I am the lash\" all you have to do is remove the Blackrock Orc Disguise and put it back on. Hope this helps!",
            date = "2021-02-24T21:33:40-06:00",
