        {
            id = 1496253,
            score = 0,
            author = "165543",
            text = "There are 2 ways to do this quest. The first way is the normal way and the second one is the way the quest giver actually wants you to do the quest. The quest giver wants to ressurect these guys so they can cause mayhem being the lines. So you should get the corpses by causing mayhem.\n\nThis is compounded with the fact that the only loot you get from them is their corpses so the true method of doing this quest is obvious. You pull one of the quest mobs (whelptamer akumi is my favourite for this) into a crowd of flamekins, drop aggro (on my pally I just died) and watch the show, then pick up the bodies after.",
            date = "2011-08-16T10:44:31-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28312#comments:id=1496253",
        },
    },
    [28313] = {
        {
