            text = "They really should increase the spawn rate or amount of worgs in the area....",
            date = "2010-12-30T11:04:24-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28313#comments:id=1267806",
        },
        {
            id = 1571445,
            score = 2,
