            text = "I am disappointed that no one on here has made a comment about the fact that you get to chop up these worgs with a CHAINSAW!",
            date = "2011-11-13T18:40:05-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28313#comments:id=1571445",
        },
    },
    [28314] = {
        {
            id = 1246060,
            score = 6,
            author = "Toyotacamry",
            text = "For those who enjoyed Keeshan's Redridge quests, you'll be happy to know that he sporadically yells \"AHHHHHHHHH\" while killing dragons for this quest.",
            date = "2010-12-19T16:28:13-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28314#comments:id=1246060",
        },
        {
            id = 2006664,
            score = 6,
            author = "tyharris01",
            text = "Do not turn in [A Deal With a Dragon] ([A Deal With a Dragon) without John J. Keeshan present. If you do that you will not be able to turn in the other two quests until someone else comes along and has Keeshan following them around. I made the mistake of leaving the Burning Steppes, logging off for a while and then came back and completed this quest without help from the NPC. If you leave the zone abandon this quest and pick this up again before proceeding. This triggers Keeshan to follow you around, without him you are stuck.",
            date = "2014-09-28T18:03:55-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28314#comments:id=2006664",
        },
