        {
            id = 3241590,
            score = 1,
            author = "Slothcat",
            text = "Johnny is a damn maniac.  As a rogue, I snuck around towards Terromath the Seared, killing him without alerting anything else, but just after that Johnny went on a rampage killing all of the dragonkin that I had just avoided.",
            date = "2020-10-23T14:35:34-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28315#comments:id=3241590",
        },
        {
            id = 6349705,
            score = 1,
            author = "FanaticWebster",
            text = "Siferiax, who left a reply to a comment left by tyharris01 in this thread is correct.\n\nToday, 5-3-2026, I encountered what tyharris01 did with the quest https://www.wowhead.com/quest=28316 and losing access to Ariok to turn in this quest.\n\nUpon seeing these comments, I logged out for a few hours and came back. Ariok appeared next to me as he should when I logged in while standing in Flame Crest. I'm not sure if logging out and then back in quickly would make the NPC follow you again or if there is an amount of time that needs to transpire.\n\nI hope this helps.",
            date = "2026-05-03T10:31:33-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28315#comments:id=6349705",
        },
    },
