            date = "2011-03-12T09:08:00-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28319#comments:id=1364830",
        },
        {
            id = 2361551,
            score = 8,
            author = "NessieMo",
            text = "https://www.wowhead.com/npc=48312 is NOT in Skull Rock, for the quest https://www.wowhead.com/quest=28319 at this time he's in a shallow cave accessed over a rope bridge. The rope bridge is at 64.33 37.55, the entrance to his cave is at 69.01 43.95 and he's just inside.\n\nPrecise coordinates for TomTom / Paste users are below:\n\n/way Burning Steppes 64.33 37.55 Rope bridge, follow twisting path up from here\n/way Burning Steppes 69.01 43.95 Entrance to High Warlock Xi'lun's cave\n/way Burning Steppes 69.62 42.91 High-Warlock Xi'lun",
            date = "2016-08-04T14:28:03-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28319#comments:id=2361551",
        },
