            text = "Currently as of 9.0.1 if you use the https://www.wowhead.com/item=63426 from https://www.wowhead.com/quest=28324 it takes enemies to 1HP. Enjoy the easiest quest ever.",
            date = "2020-10-15T15:53:35-05:00",
