    [28334] = {
        {
            id = 5739060,
            score = 176,
            author = "switchxa",
            text = "I ran into an issue where I was zoned to just \"Felwood\" (no subzone name) for most of the quest area and I was unable to use the quest item. If this happens to you, fly to Darkshore and use Zidormi to change Darkshore to before Battle For Azeroth. Then the zoning in Felwood will be correct and you can use the item anywhere in the quest area.",
            date = "2023-11-29T20:12:47-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28334#comments:id=5739060",
        },
        {
            id = 1374879,
