    [28335] = {
        {
            id = 1650877,
            score = 11,
            author = "976192",
            text = "This quest took me a longer time than it should've. Glad to see I'm not the only one who couldn't find it right away.\nThe cave is located at 55.3, 18.8. If you go into the cave, do not go straight down the path, there's a part that goes off on the right. Go down that, continue on...the pathway almost makes a S shaped. At the end of the path there is the machine, its location is 60, 22.",
            date = "2012-04-08T20:58:55-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28335#comments:id=1650877",
        },
        {
            id = 1564846,
