    [28345] = {
        {
            id = 1202001,
            score = 35,
            author = "Kciroj",
            text = "Darthalia about Orkus in Welcome to the Machine (http://www.wowhead.com/quest=28096):\nHigh Executor Darthalia says: Here's to hoping he never returns. Maybe he'll drown?\nHeh.",
            date = "2010-12-02T09:37:06-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28345#comments:id=1202001",
        },
        {
            id = 1233773,
            score = 27,
            author = "161879",
            text = "Kingslayer Orkus:\nI will not survive!\n\n*GULP*\n\nHELP ME!\n\nYou:\nYour feet are touching the ground, Orkus. This is shallow water. Just stand up and walk to shore.\n\nKingslayer Orkus:\nOh... OH! YES! Orkus has regained his senses! The foul human mage must have cursed Orkus' mind. Quickly we must get to shore! Kasha is hurt!\n\nKingslayer Orkus yells:\nKasha! Come to me! I am fine!\n\nafter his frostwyrm Kasha falls down:\nKingslayer Orkus yells: KASHA! NO!",
            date = "2010-12-14T17:51:26-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28345#comments:id=1233773",
        },
        {
            id = 1187276,
            score = 23,
            author = "tmptfate",
            text = "Haha, best short quest ever.",
            date = "2010-11-26T09:45:15-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28345#comments:id=1187276",
        },
        {
            id = 1387844,
            score = 14,
            author = "378236",
            text = "Nice dig at kingslayers. hehe (by the end of wrath everyone and their alts had it) cute little tongue in cheek there by blizz.",
            date = "2011-04-09T18:53:18-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28345#comments:id=1387844",
        },
        {
            id = 1219768,
            score = 13,
            author = "360206",
            text = "When I found him in the water splashing about, I looked over the quest he offered.\n\nI declined it and went on my merry way.",
            date = "2010-12-09T20:24:21-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28345#comments:id=1219768",
        },
    },
    [28348] = {
        {
            id = 1233783,
            score = 24,
            author = "161879",
            text = "I had just finished making use of the facilities on the docks when...\nKingslayer Orkus says: Ugh, the lok'tar must have been cooking up a turd - which would explain the smell.\nKingslayer Orkus says: By Hellscream's axe!\nVanndar Stormpike says: Oy, 'Linda, where are we meetin' up with this Ivar Bloodfang fella? An' what in Bronzebeard's name is that terrible smell?\nCaptain Balinda Stonehearth says: They are massing at Purgation Isle, just west of us here, off the coast. We are to meet them there, general.\nCaptain Balinda Stonehearth says: As for the smell... *Balinda sniffs at the air* I think it's coming from over there...\nVanndar Stormpike says: Look there, 'Linda! What in the...\nKingslayer Orkus says: You face Kingslayer Orkus now, dwarf!\nKingslayer Orkus yells: KASHA! Your master needs you!\nVanndar Stormpike yells: ENOUGH TOYIN' AROUND!\nVanndar Stormpike says: Let's get outta here, 'Linda. We dun wanna draw any unwanted attention!\nCaptain Balinda Stonehearth says: Aye, general!",
            date = "2010-12-14T17:56:05-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28348#comments:id=1233783",
        },
        {
            id = 1192628,
            score = 5,
            author = "116561",
            text = "This quest seems to bug from time to time. At least it did for me. When Orkus's dragon landed, nothing happened afterwards, the dragon just stood there and Orkus and the dwarf went on to swing at each other forever.\nAfter growing bored of that, I skipped the cinematic and lo' and behold, there on the shore stood Balinda as in the cinematic, a hostile skull level elite. She then proceeded to throwing a frostbolt at me that hit me for 36k.",
            date = "2010-11-28T07:16:14-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28348#comments:id=1192628",
        },
        {
            id = 1527708,
            score = 4,
            author = "233948",
            text = "Oh!  How I wish I could get my mounts to fight for me like Kasha does for silly Orkus ^_^",
            date = "2011-09-26T03:03:36-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28348#comments:id=1527708",
        },
    },
