    [28356] = {
        {
            id = 1974590,
            score = 5,
            author = "1269354",
            text = "Apparently, the naga have \"some balls\" on them to contemplate an invasion (according to Helcular), which is about as non-PG as I've seen WoW get.",
            date = "2014-06-24T01:09:27-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28356#comments:id=1974590",
        },
        {
            id = 3175379,
            score = 1,
            author = "arturhns",
            text = "3 quests in Hillsbrad Foothills appears to have a level requirement higher than 15 to be initiated.\n\nPreemptive Strike (https://www.wowhead.com/quest=28356/preemptive-strike)\nMuckgill's Flipper or Something... (https://www.wowhead.com/quest=28154/muckgills-flipper-or-something)\nTerrible Little Creatures (https://www.wowhead.com/quest=28355/terrible-little-creatures)\n\nOn a XP off character locked at level 15, I spent some time trying to get these quests to start, but without success. Once I came back, locked at level 21, the quests started instantaneously.\n\nThis might explain some comments about leaving the area and coming back later fixing problems, as they probably leveled up in this time.",
            date = "2019-12-06T17:21:12-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28356#comments:id=3175379",
        },
        {
