    [28374] = {
        {
            id = 1609482,
            score = 11,
            author = "Niamh",
            text = "How to get to those nice  blue rewards:\n\n1) https://www.wowhead.com/quest=28360 & https://www.wowhead.com/quest=28361\n2) https://www.wowhead.com/quest=28374 (https://www.wowhead.com/item=65289, https://www.wowhead.com/item=65308, https://www.wowhead.com/item=65327, https://www.wowhead.com/item=65340)\n\n3) https://www.wowhead.com/quest=28229\n4) https://www.wowhead.com/quest=28219 & https://www.wowhead.com/quest=28220 (https://www.wowhead.com/item=65286)\n5) https://www.wowhead.com/quest=28221 & https://www.wowhead.com/quest=28222\n6) https://www.wowhead.com/quest=28224\n7) https://www.wowhead.com/quest=28228 (https://www.wowhead.com/item=65287, https://www.wowhead.com/item=65306, https://www.wowhead.com/item=65325)\n\n8) https://www.wowhead.com/quest=28217\n9) https://www.wowhead.com/quest=28218\n10) https://www.wowhead.com/quest=28256\n11) https://www.wowhead.com/quest=28257 (https://www.wowhead.com/item=65284, https://www.wowhead.com/item=65304, https://www.wowhead.com/item=65323)\n12) https://www.wowhead.com/quest=28261\n13) https://www.wowhead.com/quest=28264 (https://www.wowhead.com/item=65285, https://www.wowhead.com/item=65305, https://www.wowhead.com/item=65324)\n\n14) https://www.wowhead.com/quest=28381\n15) https://www.wowhead.com/quest=28382 (https://www.wowhead.com/item=65341, https://www.wowhead.com/item=65290, https://www.wowhead.com/item=65309, https://www.wowhead.com/item=65328) & https://www.wowhead.com/quest=28383\n16) https://www.wowhead.com/quest=28384\n17) https://www.wowhead.com/quest=28337\n\n18) https://www.wowhead.com/quest=28385 & https://www.wowhead.com/quest=28386 (https://www.wowhead.com/item=65342, https://www.wowhead.com/item=65291, https://www.wowhead.com/item=65310, https://www.wowhead.com/item=65329)\n19) https://www.wowhead.com/quest=28388 & https://www.wowhead.com/quest=28387\n20) https://www.wowhead.com/quest=28389 (https://www.wowhead.com/item=65292, https://www.wowhead.com/item=65311, https://www.wowhead.com/item=65330)\n\nNote: 3) https://www.wowhead.com/quest=28229 and 8) https://www.wowhead.com/quest=28217 can be picked up simultaneously.\n\n(moved from reply to normal post, as the new system displays larger replies rather weird)",
            date = "2012-01-10T01:58:12-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28374#comments:id=1609482",
        },
        {
            id = 1204976,
            score = 7,
            author = "116881",
            text = "Unlocks Wanted: The Demon Hunter (http://www.wowhead.com/quest=28217) and Nature and Nurture (http://www.wowhead.com/quest=28229)",
            date = "2010-12-03T21:05:13-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28374#comments:id=1204976",
        },
        {
            id = 1965190,
            score = 6,
            author = "JuliaHB",
            text = "To expand on post by Niamh (as the quests he lists are Alliance) ...if you are Horde here are your quests to get your blues.\n\nDo steps 1 - 13 as listed (Whisperwind Grove is neutral). Then...\n14. Report to https://www.wowhead.com/npc=48127 at 56.33, 8.15 in Irontree Clearing.\n15. Pick up https://www.wowhead.com/quest=28333 & https://www.wowhead.com/quest=28334.\n16. Head back to https://www.wowhead.com/npc=48127.\n17. Turn in both & select reward from https://www.wowhead.com/quest=28333: https://www.wowhead.com/item=65344, https://www.wowhead.com/item=65347, https://www.wowhead.com/item=65350, or https://www.wowhead.com/item=65353.\n18. Pick up https://www.wowhead.com/quest=28357 & https://www.wowhead.com/quest=28370.\n19. When complete, head back & turn in both. Then pick up https://www.wowhead.com/quest=28336 & https://www.wowhead.com/quest=28339.\n20. Turn both in & pick reward from https://www.wowhead.com/quest=28336: https://www.wowhead.com/item=65345, https://www.wowhead.com/item=65348, https://www.wowhead.com/item=65351, or https://www.wowhead.com/item=65354.\n21. Pick up https://www.wowhead.com/quest=28380.\n22. Head to 54.68, 18.42 in Irontree Clearing and talk to https://www.wowhead.com/npc=48333.\n23. Pick up https://www.wowhead.com/quest=28335 & https://www.wowhead.com/quest=28340.\n24. When you \"shut off\" the https://www.wowhead.com/object=207104 at the end of the cave for https://www.wowhead.com/quest=28335, it will give you https://www.wowhead.com/quest=28368.\n25. Head out of cave and back to https://www.wowhead.com/npc=48333 to turn in https://www.wowhead.com/quest=28340.\n26. Head to approx 55.59, 22.24 and kill https://www.wowhead.com/npc=48352.\n27. Head back to https://www.wowhead.com/npc=48127 and pick your reward: https://www.wowhead.com/item=65346, https://www.wowhead.com/item=65349, or https://www.wowhead.com/item=65352!\n\nCongratz! ^_~",
            date = "2014-05-13T18:24:06-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28374#comments:id=1965190",
        },
