        {
            id = 5907838,
            score = 13,
            author = "xarmar",
            text = "I feel like the explanation for this quest needs to be simplified since the comments are making this seem a little more complex than it is.\n\nThe fact is that there are 4 versions of this quest and which one you get depends on your race. The hide/mid/thread ratio is fixed according to the version you got.\n\nRead the quest text a little and find out what race the giver wants to make you into.\n\nIf he wants to...\n\nDisguise you as an orc: 2/4/2\n\nDisguise you as an ogre:  4/1/3\n\nDisguise you as a goblin: 1/3/4\n\nDisguise you as a troll:  3/2/1",
            date = "2024-07-29T21:15:24-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28428#comments:id=5907838",
        },
    },
