    [28431] = {
        {
            id = 1181228,
            score = 74,
            author = "Ainasni",
            text = "I got 3,2,1, and that worked. Don't know if this counts for everyone, or if it's random.\n\nI'm a female Belf. (Thanks for the tip izuul)\n\n*edit*\n\nBelf 3,2,1\nDraenei 4,1,3\nDwarf 2,4,2\nGnome 1,3,4\nGoblin 1,3,4\nHuman 2,4,2\nOrc 2,4,2\nPandaren 4,1,3\nTauren 4,1,3\nTroll 3,2,1\nUndead 2,4,2\nWorgen 4,1,3\n\n+1 for everyone that helped!\n\n*edit*: Seems like it doesn't matter if you have a male or female character.",
            date = "2010-11-24T11:08:50-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28431#comments:id=1181228",
        },
        {
            id = 1202212,
            score = 24,
            author = "meeshy",
            text = "So, for those of you who didn't have this quest available right out of the gate and spent hours running around trying to find the starter quests to get over here to do the precursors to get the new flamefly pet here are a few tips.\n\nFirst you must do all the quests at Flamestar Posts.  Alllll of them, even the ones with the little goblin up the road a bit.  After you do all of them you will get a quest to kill mobs on your way to Chiselgrip post.\n\nOnce you are at Chiselgrip you will need to talk to Stebben Oreknuckle.  After doing so you can talk to Eitrigg\n\nTalk to Eitrigg and he will have to go talk to Thelaron Direneedle and he will give you this quest.\n\nThere will be a little table next to him with some glittery fabric on top of it.  Click on the fabric and for a BE I used the 3 hides -> 2 mud -> 1 thread as suggested above and it worked like a charm.\n\nGood luck farmers ^_^",
            date = "2010-12-02T13:41:11-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28431#comments:id=1202212",
        },
        {
            id = 1432605,
            score = 8,
            author = "darthamyus",
            text = "Why disguise a troll... as a troll?",
            date = "2011-06-02T06:06:39-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28431#comments:id=1432605",
        },
        {
            id = 1366553,
            score = 5,
