    [28435] = {
        {
            id = 1185459,
            score = 13,
            author = "55557",
            text = "At about 48, 58 (http://www.wowhead.com/npc=48111) (SE of Blacktooth Hovel) you'll see a dozen Blackrock War Kodo (http://www.wowhead.com/npc=48111). Simply use Horn of the Callers (http://www.wowhead.com/item=63356)  on one to send it back to camp. You can use the horn while mounted to speed up the process.\n\nIF it turns hostile, damage it until around 50-55% and it will turn friendly and run back to camp, giving you credit.",
            date = "2010-11-25T16:58:38-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28435#comments:id=1185459",
        },
        {
            id = 1350576,
            score = 5,
            author = "Landon",
            text = "Stay mounted on your flying mount:  you call the kodo, if he becomes hostile lift off and out of combat and move on to the next kodo.  Rinse, repeat, profit.",
            date = "2011-02-26T07:41:55-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28435#comments:id=1350576",
        },
        {
