        {
            id = 1472336,
            score = 4,
            author = "856196",
            text = "The general and minions were all Red to me, even tho I was wearing the disguise.\nI couldn't remove the disguize to re-apply it to reset the flag either (kept getting error message \"you can't do that yet\" when trying to remove the disguise).\n\nFound a workaround:\n1) abandon the quest\n2) fly to another map zone, and the disguize gets removed automatically, then fly back\n3) re-accept the quest\n4) re-apply the disguise from your inventory only after accepting this quest\n5) then the general will be green to you and it will work.",
            date = "2011-07-17T10:03:50-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28437#comments:id=1472336",
