        {
            id = 1683438,
            score = 2,
            author = "jtbalogh",
            text = "Do not turn in this quest if you want to keep the [Blackrock Disguise] and farm Mithril mining nodes.",
            date = "2012-07-01T21:14:06-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28453#comments:id=1683438",
        },
        {
            id = 1428289,
            score = 1,
            author = "Leone",
            text = "First I was a bit confused that I didn't get a quest after completing the delivery quests but apparently this is accepted with out text or sound (at least for me). It is good that you can see the questionmark on the map :)\n\nAnd here are the delivery quest that you need to complete (Horde and Alliance):\n\nA Delivery for Neeralak (http://www.wowhead.com/quest=28451) (A (http://www.wowhead.com/quest=28318))\nA Delivery for Thorg'izog (http://www.wowhead.com/quest=28450) (A (http://www.wowhead.com/quest=28317))\nA Delivery for Xi'lun (http://www.wowhead.com/quest=28452) (A (http://www.wowhead.com/quest=28319))",
            date = "2011-05-26T19:26:01-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28453#comments:id=1428289",
        },
    },
    [28454] = {
        {
            id = 1284726,
            score = 37,
            author = "156420",
            text = "High Warlock Xi'lun says: We are nearly prepared to start this battle, brothers.  Thorg'izog, what is the matter? Why are you covering your butt like that?\n\nGeneral Thorg'izog says: WHAT? No reason... it's just... something is very wrong with my stomach. I think it's something I ate.\n\nHigh Warlock Xi'lun says: Can you still lead your troops? Do you need to promote one of your sergeants?\n\nGeneral Thorg'izog says: Timan fell from the Pillar of Ash. Othana was eaten by wolves. Gorlop fell in lava. And most of my sergeants were killed in a freakish cudgelling accident.\n\nHigh Warlock Xi'lun says: I see. Well, do the best you can. And Neeralak, why are you all black and smoky?\n\nDragon-Lord Neeralak says: Those imps you had delivered... they woke up and started shooting fireballs at everybody! It was chaos!\n\nHigh Warlock Xi'lun says: Delivered? Woke up? What are you even talking about? Were you attacked by flamekin?\n\nDragon-Lord Neeralak says: Imps, flamekin, whatever! I don't know warlock crap. Demons all look the same to me!\n\nDragon-Lord Neeralak says: Besides, I've been busy dealing with other issues.  Dozens of my dragons died when those two enemies swept through the front lines.\n\nHigh Warlock Xi'lun says: You're both failures. But it doesn't matter; with a pit lord on our side, we won't need foot soldiers OR dragons. Behold!\n\nHigh Warlock Xi'lun says: [Demonic] Zar zar refir zenn X zennshi x buras daz!\n\nHigh Warlock Xi'lun says: And now to quickly use the Orb of Domination, before the pit lord turns on us.\n\nGeneral Thorg'izog says: The pit lord's loose! We're doomed! Retreat!\n\nGeneral Thorg'izog says: Quickly, everyone run toward those dragons! All troops, towards the dragons! The dragons will save us!\n\nDragon-Lord Neeralak says: I never called any dragons...\n\nI rofl'd in real life when Neeralak walked into view, completely blackened.  I don't get this warlock crap!",
            date = "2011-01-08T19:59:18-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28454#comments:id=1284726",
        },
        {
            id = 1713263,
            score = 32,
            author = "1032072",
            text = "With https://www.wowhead.com/spell=63303 active you can understand High Warlock Xi'lun when he speaks in Demonic. He says:\n\n\"High Warlock Xi'lun says: [Demonic] One, two, three, four, I declare a thumb war!\"\n\nIt looks like a thumb war can summon a big Pit Lord, so...",
            date = "2012-09-13T18:37:12-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28454#comments:id=1713263",
        },
        {
            id = 1519525,
            score = 24,
            author = "488143",
            text = "if you skip the cinematic the quest bugs and mobs arent killable",
            date = "2011-09-16T16:57:22-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28454#comments:id=1519525",
        },
        {
            id = 1203318,
            score = 23,
            author = "233551",
            text = "Love the emote actions from your toon while you are bombing the hapless enemy :P",
            date = "2010-12-03T01:58:29-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28454#comments:id=1203318",
        },
        {
            id = 1193787,
            score = 17,
            author = "528708",
            text = "Sit back and enjoy this great in game cinematic. Once the actuall quest part starts simply spam 1 and enjoy the caos. You can also fly back to the quest giver on the drake. If you are lucky like I was this will be your 40th quest for the zone quest achievment.",
            date = "2010-11-28T15:42:01-06:00",
