    [28460] = {
        {
            id = 1286269,
            score = 1,
            author = "557195",
            text = "This awarded 1,400 reputation at level 83. No guild perk buff or racial. (Current reputation is Revered)",
            date = "2011-01-09T17:42:17-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28460#comments:id=1286269",
        },
        {
            id = 2535503,
            score = 1,
            author = "Wyr3d",
            text = "\"Did you find anything of interest at the Winterfall camp?\"\n\nRefers to a drop item  (http://www.wowhead.com/item=12771/empty-firewater-flask)that was possible to obtain during the old version (http://www.wowhead.com/quest=5082/deprecated-threat-of-the-winterfall) of this quest. The item is no longer obtainable, nor is the quest it unlocked (http://www.wowhead.com/quest=28462/winterfall-firewater) The next quest (http://www.wowhead.com/quest=28464/falling-to-corruption) in the chain is now available without having to complete the removed quest..",
            date = "2017-11-17T13:34:43-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28460#comments:id=2535503",
        },
    },
    [28461] = {
        {
            id = 2333211,
            score = 31,
            author = "ItalianGoat",
            text = "This really screwed me up for about an hour after I queued in Blackrock Depths: Upper Spire.\nI know not many people do this quest anymore, but I'm writing this in case, like myself, someone else wants to attempt this.\n\nThere's a mole machine pretty much wherever you spawn. Use it to go to the entrance, if you're not already there. Go left, then take the right (you should have needed to go through two gates). On the left side of the corridor you just entered, there's a troll named https://www.wowhead.com/npc=45820 standing next to a closed door. Open the door and head through.\nAs you walk in, you're faced with a ramp on the right and just a room of mobs on the left. To get to where you need to be for the quest, you need to click \"The Shadowforge Lock\" which is in the middle of all the mobs. Once you've clicked that key, it will open the door you need to go through. Head up the ramp, turn left and follow the corridor. This leads you to another room. Don't bother with that boss, and just enter the next room.\n\nFor the quest: kill 5 of the Golems, and then proceed to kill the boss located at the far north of this room.\n\nHope this helps others!",
            date = "2016-05-22T04:31:57-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28461#comments:id=2333211",
        },
        {
            id = 1184451,
            score = 8,
            author = "Solarax",
            text = "This is the Horde version of the Hunter Only quest given by Ormak Grimshot (http://www.wowhead.com/npc=3352), an Orgrimmar Hunter Trainer.\n\nThere is an optional breadcrumb quest that preceeds it called Meet With Ormak Grimshot (http://www.wowhead.com/quest=28297) which is received when a player hits level 50.",
            date = "2010-11-25T10:04:37-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28461#comments:id=1184451",
        },
        {
