        {
            id = 5199848,
            score = 1,
            author = "Seby",
            text = "I have managed to partysync this for completion.\n\nInitially, if you faction transfer, both Ormak or Tamanji won't offer this quest anymore.\n\nBut, if you partysync with a low level, and then pick up Meet with Tamanji (for example from Undercity from Apolos), then Tamanji will offer this quest. You can safely leave the partysync so that you can solo the mobs needed.",
            date = "2021-06-20T02:58:16-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28461#comments:id=5199848",
        },
        {
            id = 5552166,
            score = 1,
            author = "finntosh",
            text = "This page lists Ormak Grimshot as the quest giver but its not, its actually Tamanji (73,43). I had done the breadcrumb but not this one, and was having trouble finding it.",
            date = "2023-02-18T21:49:03-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28461#comments:id=5552166",
