    [28463] = {
        {
            id = 1195119,
            score = 22,
            author = "aryon",
            text = "Pretty easy to solo at level 50 if you don't mind repair costs.\n\nStealth all the way, vanish when you need to, and make sure you're not in the fiery mobs' line of sight.\n\nTo get to the grain sacks go into the instance past  the friendly guys, then when you get into the large room go for the first passageway on the left.\nThere's a friendly guy guarding a small door on the right, which is unlocked. Go in and you'll see sacks of grain lying about the place. Find ones that aren't close to the dark iron dwarves and poison them.\n\nWhen you die now it's only a one second corpse run, unlike before patch 4.0.3a when it used to take ages. Thanks Blizzard.",
            date = "2010-11-29T06:27:29-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28463#comments:id=1195119",
        },
        {
            id = 1184169,
            score = 5,
            author = "Solarax",
            text = "This is the Horde version of the Rogue Only quest given by Gordul (http://www.wowhead.com/npc=47233), an Orgrimmar Rogue Trainer.\n\nThere is an optional breadcrumb quest that preceeds it called Meet With Gordul (http://www.wowhead.com/quest=28298) which is received when a player hits level 50.",
            date = "2010-11-25T08:05:02-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28463#comments:id=1184169",
        },
        {
            id = 1574939,
            score = 3,
            author = "Etreum",
            text = "The door you are looking for is the East Garrison Door (solid), not the very first gate to the left..  It is guarded by a Razal'blade.\n\nAlso, be careful of bloodhounds, as they will see past stealth and attack you.\n\nOther than that, very easy.  Had to vanish once and sprint out of the instance once, but managed to do it without dying.\n\n8,500 experience\n350 reputation with Orgrimmar",
            date = "2011-11-18T08:30:21-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28463#comments:id=1574939",
        },
