    [28470] = {
        {
            id = 1195314,
            score = 8,
            author = "625429",
            text = "He stands alone at his own camp just south of the road, and he has a blizzard spell channel that will do a fair amount of damage. Easily avoided by simply stepping out of the channeling area or interrupting his cast. Be sure to loot, he drops a quest item.",
            date = "2010-11-29T09:29:50-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28470#comments:id=1195314",
        },
        {
            id = 1491970,
            score = 7,
            author = "653998",
            text = "The reasoning for this is just ridiculous.Their leader must be telling them to attack people so killing the leader will make them stop. Wouldn't it be more likely that it would make him into a martyr and make them even more aggressive?",
            date = "2011-08-10T18:40:41-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28470#comments:id=1491970",
        },
        {
            id = 1381980,
