            author = "139938",
            text = "Drops quest item Crudely-Written Log (http://www.wowhead.com/item=12842).  This starts the quest the Final Piece (http://www.wowhead.com/quest=28471), the first in a long quest chain.",
            date = "2011-04-01T21:26:11-05:00",
