    [28471] = {
        {
            id = 1188108,
            score = 24,
            author = "710253",
            text = "Ok the above is completely wrong at the moment and can be confusing until you realize it is, so here is the way the \"quest line\" works.\n\n1.  The Ruins of Kel'Theril quest is actually a completely seperate quest line that can be picked up from an NPC near the outside of the ruins themselves.  From what I remember, all other quests listed above, are apart of that quest chain, but the FIRST TWO are not.\n\n2.  You cannot just kill the High Chief in order for the Crudely-written Log to drop.  You must be on a quest called, High Chief Winterfall, in order for it to drop.  Trust me, I tried to kill him randomly, the item didn't drop, thought it was one from Pre-Cata and said oh well, came back while on the quest to kill him, and the item dropped.\n\nGood Luck!",
            date = "2010-11-26T15:45:28-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28471#comments:id=1188108",
        },
        {
            id = 1188578,
            score = 13,
            author = "Cracked",
            text = "You will not get the following quest if you have accepted The Ruins of Kel'Theril quest in Felwood. If you have, simply abandon it for an extra quest.",
            date = "2010-11-26T18:55:57-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28471#comments:id=1188578",
        },
        {
            id = 1193583,
            score = 5,
            author = "704796",
            text = "If you do any of the quests in the Ruins of Kel'Theril chain, you can no longer finish the Timbermaw chain. Crappy, but there it is.",
            date = "2010-11-28T14:29:01-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28471#comments:id=1193583",
        },
        {
            id = 2043595,
            score = 3,
            author = "1205711",
            text = "Not to be confused with https://www.wowhead.com/quest=33976.",
            date = "2014-11-21T18:00:39-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28471#comments:id=2043595",
        },
        {
            id = 1759071,
            score = 2,
            author = "1020729",
            text = "#$%^..I had the journal, but wasn't sure where it came from, when I tried doing anything with it a message said I had finished that quest already, and I eventually needed bag space..at this point I hadnt even been to Lake Kel'Theril to get the new quests..now I'm at teh dwarf again and she cant give Words of the High Chief to me again..lames..\nI needed trinkets, too, have none...\nNow I'm on an angry murder spree...",
            date = "2012-11-08T02:14:29-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28471#comments:id=1759071",
        },
    },
    [28472] = {
        {
            id = 1648758,
            score = 42,
            author = "Spoonzilla",
            text = "If you deleted the book don't panic.  Just abandon the quest and go to  Donova Snowden (http://www.wowhead.com/npc=9298).  She'll have a quest available that gives you the book and the quest.",
            date = "2012-04-04T12:32:00-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28472#comments:id=1648758",
        },
        {
            id = 1390250,
            score = 22,
            author = "84986",
            text = "If you are here for Everlook rep (hello, fellow Insane wannabe) and how to get this quest, here is the step by step guide:\n\nStep 1: check if you have the quest The Ruins of Kel'Theril (http://www.wowhead.com/quest=28479) in quest log, if yes abandon it and go to Step 3. If not, go to Step 2.\n\nStep 2: go to NPC Kelek Skykeeper (http://www.wowhead.com/npc=10920) (near The Ruins of Kel'Theril in Winterspring) and check if you can get the quest The Ruins of Kel'Theril (http://www.wowhead.com/quest=28479) from him. If not tough luck, you' ve already done it and can't get Words of the High Chief (wowhead.com/quest=28472) any more. DO NOT take the The Ruins of Kel'Theril (http://www.wowhead.com/quest=28479) quest, as it will prevent you from getting Words of the High Chief (wowhead.com/quest=28472).\n\nStep 3: grabd the quest Mystery Goo (http://www.wowhead.com/quest=28467) from the cauldron in the Winterfall camps north of Donova Snowden (http://www.wowhead.com/npc=9298) and go to her to turn it in.\n\nStep 4: Now grab the quests Winfertall Runners (http://www.wowhead.com/quest=28469) from Donova Snowden and do it (the mob you need can easily be found on the road from Timbermaw Hold to Everlook)\n\nStep 5: Grab High Chief Winterfall (http://www.wowhead.com/quest=28470) from Donova Snowden.  When you kill High Chief Winterfall (http://www.wowhead.com/npc=10738), he will drop Crudely-Written Log (http://www.wowhead.com/item=12842) that starts The Final Piece (http://www.wowhead.com/quest=28471). This is the only way to get the item, it will not drop if you are not on the High Chief Winterfall (http://www.wowhead.com/quest=28470) quest.\n\nStep 6: Go back to Donova Snowden, the next quest in the chain is finally Words of the High Chief (wowhead.com/quest=28472). Enjoy your extra (and easily earned) goblin rep :)\n\nNote: the next step in the chain is The Ruins of KelTheril (http://www.wowhead.com/quest=28479) which you can now complete safely if you so wish.",
            date = "2011-04-13T03:51:37-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28472#comments:id=1390250",
        },
        {
            id = 1579857,
            score = 18,
            author = "canyoneagle",
            text = "Post shattering update:\nHere is the quest chain to get either trinket.\nYou no longer need to get the empty vial.\n\n1. It all starts with Falling To Corruption (http://www.wowhead.com/quest=28464) , which then directs you to the cauldron in the Furlbog camp.\n2. Mystery Goo (http://www.wowhead.com/quest=28467)\n3. Winterfall Runners (http://www.wowhead.com/quest=28469)\n4. High Chief Winterfall (http://www.wowhead.com/quest=28470)\n5. The Final Piece (http://www.wowhead.com/quest=28471)\n6. Words of the High Chief (http://www.wowhead.com/quest=28472)",
            date = "2011-11-24T11:08:32-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28472#comments:id=1579857",
        },
        {
            id = 1194700,
            score = 4,
            author = "PaulertheMauler",
            text = "You will only get this quest once you complete The Final Piece (http://www.wowhead.com/quest=28471) and have not started the quest chain that starts with The Ruins of Kel'Theril (http://www.wowhead.com/quest=28479) from Kelek Skykeeper (http://www.wowhead.com/npc=10920). Not sure if this is a oversight by Blizzard, but he can be found in Felwood at the Emerald Sanctuary and in Winterspring west of Lake Kel'Theril.",
            date = "2010-11-29T00:27:59-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28472#comments:id=1194700",
        },
        {
            id = 1380172,
            score = 4,
            author = "zigguratei",
            text = "Upon completion he says:\n\n\"Yes, if you let me examine this for a while, I might be able to translate it for you.\n\nWhen I am able to look over this fully, I will send word to you.\"\n\nI am trying to get Timbermaw rep, has anyone seen any continuation of this questline about the Timbermaw or has Bliz dropped the ball?",
            date = "2011-03-30T15:24:10-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28472#comments:id=1380172",
        },
    },
    [28473] = {
        {
            id = 1528736,
            score = 75,
            author = "355455",
            text = "For those of you who are still new to the game, Apolocyntosis is referring to the True Masters of the Light (http://www.wowhead.com/quest=9737) quest line, which was how Blood Elf paladins previously obtained their tabards, along with the epic ground mount. In the quest line, players procured a number of expensive materials for Lady Liadrin (or, later, Solanar Bloodwrath), stole some holy water from Tyr's Hand, turned it into an extinguishing mixture, and used it to douse the eternal flame in the chapel in Stratholme, which was the one building left in the city unharmed by the Scourge. The act of defilement was meant as a defiant gesture to prove that the Blood Knight ideology of \"mastering\" the Light was superior to the Silver Hand's serving the Light; by removing the chapel's protection and burning it to the ground, they would show once and for all who were the stronger paladins.\n\nI feel torn about the removal myself; the original quest line, while being ridiculously simple compared to the Silver Hand one, was really well executed. I remember being kind of shocked when Liadrin told me to burn down that chapel, and it really drove home how ruthless the Blood Knights were. The thing is, the order's being led in a new direction now, since the Sunwell was restored, and lore-wise it was probably a good thing they removed it. But it does make me sad, because Blood Knights won't get the feeling of accomplishment and what it really meant to be a member of the order.\n\nOTOH, maybe this feeling itself is paralleled in lore, as what it means to be a Blood Knight has very much changed from the inception of the order. Now there's a generation of Blood Knights coming up who never siphoned from M'uru. And surely not everyone from the first generation has had Liadrin's born-again epiphany. I really hope this is explored when Blizzard finally bothers to get off their duff and update the Blood Elf areas, because otherwise the Blood Knights are just going to turn into a boring, palette-swapped clone of the Silver Hand. Homogenizing the class quests like this across racial lines is contributing to the problem, imo.",
            date = "2011-09-27T10:25:08-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28473#comments:id=1528736",
        },
        {
            id = 3244889,
            score = 60,
            author = "ladycarnage",
            text = "For anyone that is wondering about the Tabard, I just ran the quest and got the tabard.  Some things have changed, the quest is given by Avaros Dawnglaive, Paladin Trainer.  He is located in the Barracks, in The Valley of Honour.  Everything else is the same.",
            date = "2020-11-02T19:34:28-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28473#comments:id=3244889",
        },
        {
            id = 1891243,
            score = 37,
            author = "irpk",
            text = "To clear up some stuff for new Tauren Paladins:\nCompletion of the quest \"Weapons of Darkness\" IS needed to get the https://www.wowhead.com/item=25549.\nAfter completing the quest you will be able to buy the tabard from Garyl in the Valley of Strength (Org).\nThe quest can be picked up from Sunwalker Atohmo in the Valley of Wisdom (Org).\n\nThe quest is realy easy:\n\n1 - Get to Blackrock Depths (The instance right by the \"Molten Core-Elf\").\n2 - Kill 5 Dark Iron Dwarfs either outside of the instance or just inside.\n3 - Click the \"Abandoned Mole Machine\", and choose \"Into the Domicile\".\n4 - Run RIGHT\n5 - Run straight down the stairs and go through the small door right infront of you.\n6 - Jump down (it's on the left after the door).\n7 - The the Black Anvil shod be on your right.\n\nIf that that was too hard then just click this youtube link:\n (http://www.youtube.com/watch?v=7v4th3Popjg)",
            date = "2013-08-29T16:45:00-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28473#comments:id=1891243",
        },
        {
            id = 1187675,
            score = 26,
            author = "Liri",
            text = "This quest is 'easily' soloable.\n\nGet the weapons off the dwarves outside the instance, enter, use the 'Abandoned Mole machine' to go to the destination 'just past the grim guzzler'.\n\nJump down and start hammering.  The boss will kill you a time or two but the weapon smashing can only be interrupted by his knockbacks.\n\nProfit!",
            date = "2010-11-26T12:58:18-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28473#comments:id=1187675",
        },
        {
            id = 1471988,
            score = 25,
            author = "Apolocyntosis",
            text = "I will say that it's nice that it's easy to get the tabard now (no buying materials for the charger or assembling a group to go into Strat), but I really feel bad for you young paladins that will never get the chance to do the old quest line. There was a sense of pride you got from putting the time and effort in to get that unique paladin mount and tabard; it was a real rite of passage, of sorts.",
            date = "2011-07-16T23:22:46-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28473#comments:id=1471988",
        },
    },
    [28474] = {
        {
            id = 1184224,
            score = 3,
            author = "Solarax",
            text = "This is the Horde version of the Undead Priest Only quest given by Dark Cleric Cecille (http://www.wowhead.com/npc=45339), an Orgrimmar Priest Trainer.\n\nThere is an optional breadcrumb quest that preceeds it called Meet With Dark Cleric Cecille (http://www.wowhead.com/quest=28304) which is received when a player hits level 50.",
            date = "2010-11-25T08:34:49-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28474#comments:id=1184224",
        },
        {
            id = 1622338,
            score = 2,
            author = "13930",
