        {
            id = 6438425,
            score = 1,
            author = "Roxtoni",
            text = "WARNING for completionists!\n\nDo NOT accept https://www.wowhead.com/quest=28479 too early.\n\nFirst, obtain the item that starts https://www.wowhead.com/quest=28471, turn https://www.wowhead.com/quest=28471 in to https://www.wowhead.com/npc=9298, and then complete https://www.wowhead.com/quest=28472.\n\nSafe order:\n\nhttps://www.wowhead.com/quest=28471 → https://www.wowhead.com/quest=28472 → https://www.wowhead.com/quest=28479\n\nAccepting https://www.wowhead.com/quest=28479 before completing https://www.wowhead.com/quest=28472 can cause https://www.wowhead.com/quest=28472 to become unavailable.\n\nIf you already accepted https://www.wowhead.com/quest=28479, abandon it before turning in https://www.wowhead.com/quest=28471, then complete https://www.wowhead.com/quest=28472 first.",
            date = "2026-09-29T16:35:22-05:00",
