        },
        {
            id = 1185892,
            score = 41,
            author = "Smaktat",
            text = "Not to be confused, this quest is inside of the yeti cave down below, not on top of the Stormpike camp above.  Also, make sure to do this in conjunction with:\n\n[quest=28484 domain=www]\n\nThe three pieces are in the three separate sections of the cave.  There's really no efficient way to get this done.",
            date = "2010-11-25T20:32:13-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28487#comments:id=1185892",
        },
        {
            id = 1187261,
            score = 16,
            author = "195360",
            text = "Why does this dude just keep losing his stuff? Someone should just nail it to him, not like he's gonna feel anything as a walking corpse....\n\nFor those who don't know, this is the SECOND time we have to get his sword back: [quest=547 domain=www]\n\nAnd now his pants and armor to boot....\n\nNot counting that his pants and armor were old BoE greens....",
            date = "2010-11-26T09:39:00-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28487#comments:id=1187261",
