    [28489] = {
        {
            id = 1902914,
            score = 58,
            author = "Umiamz",
            text = "Not convinced this quest is worth it - it took around 30 minutes to complete. The Stalkers far outweigh the stags and the respawn rate of Stalkers is ridiculous. About half the time I couldn't loot the stags (even ones that hadn't been attacked by Stalkers). The only upside was that I got some lion meat (enough for +5 cooking skill) and 2 stacks each of light and medium leather.",
            date = "2013-09-26T08:30:38-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28489#comments:id=1902914",
        },
        {
            id = 3219137,
            score = 29,
            author = "FlibbitSC",
            text = "Building on what many others have said - the quest is not broken, but it *is* poorly implemented and could stand some revisions.\n\nYes, you need to find Hill Stags that have not yet been tapped by any nearby hostiles. The quickest way to complete this (<10 minutes) is to stand roughly around 48.6, 54.4, kill any cats in the area. You'll see groups of stags spawn right around this spot which contain *TWO* Hill Stags and 0-4 Hill Fawns. These are the ones you want - they are located in an area with very few intersecting hostiles (1-2 at most), so you have more time to get them before they get tapped. The drop rate of the quest item from these is *nearly* 100% (just the stags, not the fawns - the drop rate was 100% for me, doing this quest twice, but YMMV). It doesn't look like there are ever more than 2 of these groups up at once at this location, but they respawned fast enough that I killed 4 groups in about 6-8 minutes with no fuss.",
            date = "2020-07-24T19:30:42-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28489#comments:id=3219137",
        },
        {
            id = 1955822,
            score = 28,
            author = "Garrath",
            text = "Still broken.  I dropped the quest.  I found when I killed the stalkers in the area and the stags respawned, I couldn't loot any stags I killed, and they were not skinnable.",
            date = "2014-04-04T11:23:32-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28489#comments:id=1955822",
        },
        {
            id = 2587210,
            score = 20,
            author = "ShamrockSoup",
            text = "Blizzard really needs to have improved spawn times for mobs involved in quests. Especially farming quests such as this. Quests like this can take over 20 minutes simply due to the spawn times if there's even just 2 players doing at the same time.",
            date = "2018-08-02T12:17:51-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28489#comments:id=2587210",
        },
        {
            id = 1954490,
            score = 18,
            author = "L34F",
            text = "If you see a Foothill Stalker and a Hill Stag fighting, kill the Foothill Stalker first. Otherwise the Hill Stag may have no loot.",
            date = "2014-03-29T04:08:13-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28489#comments:id=1954490",
        },
    },
    [28490] = {
        {
            id = 1552458,
            score = 13,
            author = "503971",
            text = "This quest is a Breadcrumb quest.\n\nBreadcrumb quests are quests that, even though you did not complete them and they were available at some point, have become unavailable permanently after certain conditions were met. If this happens to you, and you're a completionist, this quest can be marked as excluded in the Wowhead quest tracker if you are no longer able to complete it.\n\nYour character is level 19 or higher, at which point this quest is replaced on the Hero's Call Board, by https://www.wowhead.com/quest=28492.\nhttps://www.wowhead.com/quest=26383 or https://www.wowhead.com/quest=26385 (Worgen) is completed.\nThis is a zone introductory quest leading to this zone. You can only complete this quest, or the zone introductory quest, not both. Completing the zone introductory quest will therefore make this quest unavailable.\nhttps://www.wowhead.com/quest=13518 is completed.\nThis is one of the quests available in the quest hub that this quest points to, and is also considered a follow-up to this quest. Completing this quest will make all zone introductory quests leading to this npc, including this one, unavailable.\n\nExamples of Breadcrumb quests and conditions making them unavailable:\n\nHero's call quests.\nThey become unavailable if your character's level is too high, and the hero's call board sends you to a different npc/zone.\nZone introductory quests.\nThis also includes hero's call quests. These quests are often started in a certain lower level zone, and they direct you to the next zone. If there are several of these, including the hero's call, directing you to the same zone/npc, completing one will mean the others become unavailable.\nQuest hub introductory quests.\nThese are quests that direct you to the next quest hub in a zone. If you've already completed the quests in that quest hub, the quest directing you to it may become unavailable.\nFollow-up quests.\nThese are uncommon, but still appear in older zones that have not been changed much in recent expansions. Sometimes a follow-up quest of quest X is available before you complete quest X. If you complete that follow-up quest and go back to the quest X giver, you may encounter the error 'You do not meet the requirements for that quest', leaving you unable to start it or turn it in.\n\nNote: A quest being unavailable does not necessarily mean it's unavailable permanently. If you have not met the aforementioned conditions, and the quest is still unavailable, then you may have missed certain required quests that precede this one, or you do not meet the requirements in some other way. Always verify this before excluding this quest.",
            date = "2011-10-24T09:26:26-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28490#comments:id=1552458",
        },
        {
            id = 2579186,
            score = 7,
            author = "EmJii",
            text = "As of Patch 7.3.5 you can do two breadcrumb quests that lead you to Darkshore.\n\nYou have to keep the order to be able to do both.\n\n1.https://www.wowhead.com/quest=26383 (for every alliance race) or https://www.wowhead.com/quest=26385 (for Worgen only)\n\n2.https://www.wowhead.com/quest=28490 (can be found on every Hero's Call board)",
            date = "2018-07-07T10:13:19-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28490#comments:id=2579186",
        },
        {
            id = 5552270,
            score = 6,
            author = "FoxyOwl",
            text = "I went to the general entry for the Hero's Board and found the comment that helped me. Keep in mind that I had not yet done https://www.wowhead.com/quest=13518. The Hero's Board only shows three quests at a time but you can keep accepting them to see lower-level ones. As long as you have not done the subsequent quest that cuts you off from the breadcrumb. I think I had to accept 34 other quests before I could see this one. If you have an addon like All The Things, you should miss fewer quests like this. I hope this helps someone!",
            date = "2023-02-19T06:20:03-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28490#comments:id=5552270",
        },
        {
            id = 2004022,
            score = 5,
            author = "Liike",
            text = "Once you get the quest, head back to the dome with the purple lights and it well take you back to Ruth'theran Village. Then, since there are no more boats that take you to Darkshore, you must talk to the Flight Master and fly there. Good luck!",
            date = "2014-09-18T23:47:19-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28490#comments:id=2004022",
        },
        {
            id = 1190067,
            score = 4,
            author = "Korwynd",
            text = "Getting this quest also gives you the flight point to Darkshore if you didn't already have it.",
            date = "2010-11-27T09:45:12-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28490#comments:id=1190067",
        },
    },
    [28491] = {
        {
            id = 1201616,
            score = 124,
            author = "310680",
            text = "HORDE QUESTLINE\nFOR TINY FLAMEFLY COMPANION PET\nBegin in Burning Steppes\n\nThinking of it as a questline is a bit misleading as the quests dead end at a couple points and you need to know where to go to continue. Here are my notes that I used to get the pet on 3 different toons. Good luck!\n\nMouton Flamestar ( 17.1, 51.3)\n- Done Nothing Wrong (http://www.wowhead.com/quest=28417) (free 4 chained whelps)\n\nAriok (17.5, 51.7)\n- Burning Vengeance (http://www.wowhead.com/quest=28418) (kill 5 orcs, kill 5 whelps)\n- Stocking Up (http://www.wowhead.com/quest=28419) (kill/loot 5 scorpids)\n- A Future Project (http://www.wowhead.com/quest=28420) (kill/loot 11 worgs)\n- Mud Hunter (http://www.wowhead.com/quest=28421) (pick up 9 piles of mud)\n- The Sand, The Cider, and the Orb (http://www.wowhead.com/quest=28422) (visit  some goblin)\n\nGorzeeki Wildeyes (8.3, 35.9)\n- Warlocks have the Neatest Stuff (http://www.wowhead.com/quest=28423) (pick up two items and kill an orc for loot)\n- Shadow Boxing (http://www.wowhead.com/quest=28424) (kill a fancy orc)\n- Return to Ariok (http://www.wowhead.com/quest=28425) (go back to first orc)\n- Chiselgrip, the Heart of the Steppes (http://www.wowhead.com/quest=28426) (kill 15 orcs)\n\nStebben Oreknuckle (46.7, 44.2)\n- Prove Yer Allegiance (http://www.wowhead.com/quest=28225) (kill 10 dwarves)\n- Scrapped Golems (http://www.wowhead.com/quest=28226) (kill golems and collect specific pieces on the ground near them)\n- Golem Training (http://www.wowhead.com/quest=28227) (click on 4 golems in camp)\n\nEltrigg (44.6, 44.5)\n- A Needle in a Hellhole (http://www.wowhead.com/quest=28427) (talk to Thelaron Direneedle)\n- A Perfect Costume (http://www.wowhead.com/quest=28428) (click on the table next to you)\n- Into the Black Tooth Hovel (http://www.wowhead.com/quest=28432) (talk to some orc while in disguise)\n\nQuartermaster Kaoshin (45.6, 51.9)\n- Strategic Cuts (http://www.wowhead.com/quest=28434) (use item to stab 3 specific mobs)\n- Grunt Work (http://www.wowhead.com/quest=28433) (click on shoes in front of buildings)\n- The Kodocaller's Horn (http://www.wowhead.com/quest=28435) (use an item on 7 kodo)\n- Taking the Horn for Ourselves (http://www.wowhead.com/quest=28436) (return to Eltrigg)\n\nEltrigg (44.6, 44.5)\n- General Thorg'izog (http://www.wowhead.com/quest=28437) (talk to a fancy orc)\n\nGeneral Thorg'izog ( 30.7, 33.8)\n- Trial by Magma (http://www.wowhead.com/quest=28438) (click on a goblin next to you and kill fire dude)\n- Abuse of Power (http://www.wowhead.com/quest=28440) (use item to kill 5 orcs)\n- Enough Damage for one Day (http://www.wowhead.com/quest=28441) (return to Eltrigg)\n\nEltrigg (44.6, 44.5)\n- Flame Crest (http://www.wowhead.com/quest=28442) (visit Kibler)\n\nKibler (54.9, 22.7)\n- Not Fireflies, Flameflies (http://www.wowhead.com/quest=28491) (click on 7 Flameflies)\n\n CONGRATS! NOW YOU HAVE YOUR FLAMEFLY <3\nNotes on time: After doing this line on one lvl 80 toon, the second lvl 80 took me about an hour. The biggest time sink is Scrapped Golems until you get the hang of it. Would appreciate a time estimate on the level if anyone has one.",
            date = "2010-12-02T04:37:47-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28491#comments:id=1201616",
        },
        {
            id = 1186563,
            score = 44,
            author = "206732",
            text = "In order to unlock the chain that grants this pet as a reward, you must first go to Flamestar Post and speak to Ariok who will ask you to kill black whelps and their trainers (Burning Vengeance (http://www.wowhead.com/quest=28418)). Then he will request you to bring him Scorpid Barbs (http://www.wowhead.com/quest=28419), Worg Hides (http://www.wowhead.com/quest=28420), and Obsidian Flecked Mud (http://www.wowhead.com/quest=28421).\n\nAfter these tasks are complete, he will send you to talk to a goblin, he needs some more items, specifically, The Sand, the Cider, and the Orb (http://www.wowhead.com/quest=28422).\n\nOnce he has his items, he will want to accompany you to Chiselgrip (http://www.wowhead.com/quest=28426) and of course fight along the way.\n\nAt Chiselgrip, his father has some jobs for you. You'll have to wear a disguise (http://www.wowhead.com/quest=28202) for this part. Follow all directions, and when you get back, accept and complete every quest in Chiselgrip. DO NOT get rid of your disguise! Once you've completed them (it's only a few, won't take you long) Eitrigg will have more work for you.\n\nThis time you're back in your disguise, and you're off to see the General (http://www.wowhead.com/quest=28437). He'll have a few things for you to do, fighting (http://www.wowhead.com/quest=28438), and keeping the soldiers in line (http://www.wowhead.com/quest=28439).\n\nEitrigg will also have a task (http://www.wowhead.com/quest=28440) for you over there.\nOnce you get back, Eitrigg and his son will accompany you to Flame Crest, where Kibler (http://www.wowhead.com/npc=10260) will FINALLY give you this quest.\n\nEnjoy your Tiny Flamefly!",
            date = "2010-11-26T02:40:01-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28491#comments:id=1186563",
        },
        {
            id = 1200417,
            score = 15,
            author = "715531",
            text = "[quest=28442 domain=www] Flame Crest quest requires you to be friendly with Booty Bay. so if you did the Bloodsail Admiral thing, dont waste your time trying to do the questline for the pet.",
            date = "2010-12-01T14:43:50-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28491#comments:id=1200417",
        },
        {
            id = 1181334,
            score = 13,
            author = "Ainasni",
            text = "You also get a pet as questreward: Tiny Flamefly (http://www.wowhead.com/item=66080)",
            date = "2010-11-24T11:38:45-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28491#comments:id=1181334",
        },
        {
            id = 1429183,
            score = 12,
            author = "Vlad",
            text = "To quickly figure out how far you got in the chain for the awesome https://www.wowhead.com/item=66080 companion, simply run this macro (pick the one for [acronym=\"I put both factions on here in case you are visiting the wrong quest on Wowhead.\"]your faction[/acronym]):\n\nAlliance\n/run local i=0 for q in(\"514416172178179177180181182183184254205226225227239246245252253265266278279286310415\"):gmatch(\"%d%d%d\")do q=\"28\"..q i=i+1 print(i,\"\\124Hquest:\"..q..\":0\\124h[#\"..q..\"]\\124h\",IsQuestFlaggedCompleted(q)and COMPLETE or INCOMPLETE)end\n\nHorde\n/run local i=0 for q in(\"417418419420421422423424425426225226227427428432434433435436437438440441442491\"):gmatch(\"%d%d%d\")do q=\"28\"..q i=i+1 print(i,\"\\124Hquest:\"..q..\":0\\124h[#\"..q..\"]\\124h\",IsQuestFlaggedCompleted(q)and COMPLETE or INCOMPLETE)end\n\nI hope this helps you backtrack where to go next! :)",
            date = "2011-05-28T06:40:29-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28491#comments:id=1429183",
        },
    },
    [28492] = {
        {
            id = 1530218,
            score = 16,
            author = "Bengarion",
            text = "Be aware that if you accept/complete this quest you will not be able to accept/complete the quest Ashes in Ashenvale (http://www.wowhead.com/quest=26408). The Ashes quest offers more exp/rep/silver than this one.\n\nAshes in Ashenvale gives 390 exp/25 Darnassus rep/3 silver v. Heros's Call 155 exp/10 Darnassus rep/0 silver.\n\n(The Ashes quest is the end of a quest chain - with The Battle for Darkshore (http://www.wowhead.com/quest=13897) being required before the Ashes quest will be offered.)\n\nSeveral of these Hero's Call quests have a breadcrumb quest counterpart that usually offers more exp/rep/silver. I, as yet, know of no easy way to find out these breadcrumb quests other than to check Wowhead to see if someone has posted that there is a quest available.\n\nLuck!",
            date = "2011-09-28T17:12:57-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28492#comments:id=1530218",
        },
        {
            id = 1542898,
            score = 9,
            author = "MaxTheDragon",
            text = "This quest is a Breadcrumb quest.\n\nBreadcrumb quests are quests that, even though you did not complete them and they were available at some point, have become unavailable permanently after certain conditions were met. If this happens to you, and you're a completionist, this quest can be marked as excluded in the Wowhead quest tracker if you are no longer able to complete it.\n\nThis quest becomes unavailable permanently, if either of the following conditions are met:\nYour character is level 24 or higher, at which point this quest is replaced on the Hero's Call Board, by https://www.wowhead.com/quest=28539.\nhttps://www.wowhead.com/quest=26408 is completed.\nThis is a zone introductory quest leading to this zone. You can only complete this quest, or the zone introductory quest, not both. Completing the zone introductory quest will therefore make this quest unavailable.\nhttps://www.wowhead.com/quest=13594 is completed.\nThis is one of the quests available in the quest hub that this quest points to, and is also considered a follow-up to this quest. Completing this quest will make all zone introductory quests leading to this npc, including this one, unavailable.\n\nExamples of Breadcrumb quests and conditions making them unavailable:\n\nHero's call quests.\nThey become unavailable if your character's level is too high, and the hero's call board sends you to a different npc/zone.\nZone introductory quests.\nThis also includes hero's call quests. These quests are often started in a certain lower level zone, and they direct you to the next zone. If there are several of these, including the hero's call, directing you to the same zone/npc, completing one will mean the others become unavailable.\nQuest hub introductory quests.\nThese are quests that direct you to the next quest hub in a zone. If you've already completed the quests in that quest hub, the quest directing you to it may become unavailable.\nFollow-up quests.\nThese are uncommon, but still appear in older zones that have not been changed much in recent expansions. Sometimes a follow-up quest of quest X is available before you complete quest X. If you complete that follow-up quest and go back to the quest X giver, you may encounter the error 'You do not meet the requirements for that quest', leaving you unable to start it or turn it in.\n\nNote: A quest being unavailable does not necessarily mean it's unavailable permanently. If you have not met the aforementioned conditions, and the quest is still unavailable, then you may have missed certain required quests that precede this one, or you do not meet the requirements in some other way. Always verify this before excluding this quest.",
            date = "2011-10-14T16:26:43-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28492#comments:id=1542898",
        },
        {
            id = 2579188,
            score = 9,
            author = "EmJii",
            text = "As of Patch 7.3.5 you can do two breadcrumbs that lead you to Ashenvale.\n\nYou have to keep the order to be able to do both of them.\n\n1.https://www.wowhead.com/quest=28492 (can be found on every Hero's Call board)\n\n2.https://www.wowhead.com/quest=26408 (you have to quest through Darkshore and complete https://www.wowhead.com/quest=13897, in order to make this quest available)",
            date = "2018-07-07T10:22:31-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28492#comments:id=2579188",
        },
        {
            id = 1432695,
            score = 5,
            author = "766072",
            text = "Shouldnt it be Tyrande who issues the call for able-bodied Allies to help protect Ashenvale? The Horde I can understand Garrosh issueing the commands (and even then I think it should be Sylvanas when the quests in a zone are more Forsaken oriented), but the leadership of the Alliance isn't centralized like it is in the Horde.\n\nWhy is Varian the only one issueing orders/requests for heroes to help the Alliance wareffort?",
            date = "2011-06-02T10:23:23-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28492#comments:id=1432695",
        },
        {
            id = 2854601,
            score = -2,
            author = "Thranduel",
            text = "If like me you start a new level 20 toon post BFA and decide to pick this up from the board in Stormwind, there is a portal to Darnassus on the Southernmost dock (where the boat to Boralus now is).\n\nIt actually takes you to Rut'theran Village before Darnassus was destroyed and you can talk to the flight-master: https://www.wowhead.com/npc=3838 to catch a flight down to Blackfathom Camp in Ashenvale",
            date = "2018-11-23T15:20:35-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28492#comments:id=2854601",
        },
    },
    [28493] = {
        {
            id = 1494395,
            score = 8,
            author = "856975",
            text = "This is a level 20 quest, once you are higher level you wont be able to get it anymore (I abandoned it at level 25 and could not get it again), and https://www.wowhead.com/quest=28876 has been removed from game.",
            date = "2011-08-13T21:44:25-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28493#comments:id=1494395",
        },
        {
            id = 1709390,
