        {
            id = 1196242,
            score = 3,
            author = "Solarax",
            text = "This is a breadcrumb quest leading low level characters to Azshara.\n\nIt appears that if you are already over a certain level or have already discovered Azshara, then this quest will not be available any more.",
            date = "2010-11-29T17:58:20-06:00",
