        },
        {
            id = 1197047,
            score = 3,
            author = "68438",
            text = "20 quest at that board and I cant get any of this\nand worse . I am stuck at 72/80 quests in Ashenvale, and that scout report which is folow up\nwill bring 3 quest...",
            date = "2010-11-30T03:04:02-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28496#comments:id=1197047",
        },
        {
            id = 1281347,
            score = 3,
            author = "726332",
            text = "Forget the old Azshara, this one has (literally) been reworked to be a symbol of the Horde.\n\nAll the quests have been updated, the area looks fairly different, there's the giant face of a goblin looming in the side of a cliff. A connecting road allows for easy access of the entire zone for a toon with no mount.\n\nIt was made for goblins.",
            date = "2011-01-06T21:38:09-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28496#comments:id=1281347",
        },
        {
            id = 1449060,
            score = 3,
            author = "587315",
            text = "You can also get this quest in Orgrimmar",
            date = "2011-06-23T19:52:47-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28496#comments:id=1449060",
        },
    },
    [28503] = {
        {
            id = 1967736,
            score = 18,
            author = "Lovestorybro",
            text = "Don't pick up this quest and start running trying to figure out how to get to Thousand Needles.  There is another quest that will give you a flight from Mudsprocket in Dustwallow Marsh to where you are supposed to start in Thousand Needles, but you can't have both quests at once.  Drop the Hero's Call quest and head to Mudsprocket in Dustwallow Marsh.  Talk to Thyssiana and get the quest To New Thalanaar which will give you a free flight to where you should be going.\n\nDo 1 quest there and you will get another free ride to the Speedbarge quest hub.",
            date = "2014-05-25T14:21:21-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28503#comments:id=1967736",
        },
        {
            id = 1203382,
            score = 17,
            author = "355167",
            text = "Picking this up at the appropriate level leaves us no way to get there.\n\nHero's call quests were a good idea but some of them don't quite work out for new players. You need a deep understanding of locations within the game to find them.",
            date = "2010-12-03T03:12:26-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28503#comments:id=1203382",
        },
        {
            id = 2795549,
            score = 9,
            author = "Mortimerty",
            text = "As of Patch 8.0 you CAN NOT complete these three breadcrumb quests which lead you to Thousand Needles, unlike another breadcrumb quests which you can if do Hero's Call one first.\n\nI've done https://www.wowhead.com/quest=28503 first, and after that both https://www.wowhead.com/quest=25479, https://www.wowhead.com/quest=25479 dissappear and marked as completed.",
            date = "2018-11-03T13:30:37-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28503#comments:id=2795549",
        },
        {
            id = 1255155,
            score = 4,
            author = "582551",
            text = "Here is how I got there at level 40:\n\nFrom Stormwind, I flew to Booty Bay. Then I caught the boat to Ratchet and from there I flew to Dustwallow Marsh (was the only FP I had to consider). I rode to the Great Lift, realized that the quest was on the other side of Thousand Needles ( -_- ), and jumped into the water below.\n\nI swam my way over to where the quest was located, searched through the fighting Night Elves and Tauren a bit, and finally found her.\n\nIf there was a better way (and there probably was), I doubt I had the flight points for it. =/ But at least this is one way to consider if you are lost on how else to get there.\n\nEDIT: Once you complete this quest and the next, you'll be sent somewhere there's a flight path so all is good. =)",
            date = "2010-12-23T16:42:18-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28503#comments:id=1255155",
        },
        {
            id = 3191583,
            score = 3,
            author = "Fluffmeister",
            text = "If you take the portal in the Mage Quarter in Stormwind (you don't have to be a mage, I'm a paladin and it worked) to the Caverns of Time, turn round (so don't go into the caverns) and you're in Tanaris. A couple of quests there, and it's an easy ride (not flight) to Gadetzan, and there's a footpath to Thousand Needles from there. OK, you have to swim to the barge, and swim to the shore, but it's doable.",
            date = "2020-02-22T14:10:03-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28503#comments:id=3191583",
        },
    },
