    [28509] = {
        {
            id = 5787172,
            score = 27,
            author = "Alderwhim",
            text = "Seems to be bugged these days? It is the only one I have left available to me on the command board, I can click it, get the quest pop up and hit accept - but it never appears in my questlog and just remains in my command board. Questlist is nearly empty so definitely not just it being full. Haven't done any quests in Tanaris either on the characters I have tried to accept it on.",
            date = "2024-02-16T05:01:19-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28509#comments:id=5787172",
        },
        {
            id = 2265979,
            score = 9,
            author = "Huuwas",
            text = "If you haven't done any quests in 1k needles, I think the fastest way to get there is from Dalaran.\n\n1. Fly from Orgrimmar to Borean Tundra.\n2. From there take the flightpath to Dalaran (as of WoD?, everyone has that one).\n3. Go to the violet citadel and up the stairs. On the left side you will find a portal to the Caverns of Time (Tanaris).\n4. From there on it's just a minute to Gadgetzan.\n\nHope that helps.\n\nAs of Patch 8.1.5 and the removal of most of the portals, there isn't a good way to get to Tanaris.\n\nBut: If you have https://www.wowhead.com/item=150744 and use it, you will get the flightpath to Gadgetzan.\n\nJust use the portal to Caverns of Time, in Orgrimmar.",
            date = "2015-10-20T17:15:27-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28509#comments:id=2265979",
        },
