    [28510] = {
        {
            id = 1363132,
            score = 25,
            author = "treehstn",
            text = "Route to Feralas from TB hoofin' it without flying mount or flightpaths and no areas with high level mobs:\n\nGo north from Thunderbluff to Stonetalon Pass.  Take the pass into Stonetalon Mountains.  Head towards the coast.  Head south on the road at 35, 79 into Desolace.  Travel through Desolace to the road east of Gelkis Village.  That road takes you into Feralas.  There are flight paths on this route so be sure to pick them up.",
            date = "2011-03-10T11:40:38-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28510#comments:id=1363132",
        },
        {
            id = 2005406,
            score = 10,
            author = "1361840",
            text = "You can do both this quest and https://www.wowhead.com/quest=26589\n1. Pick up https://www.wowhead.com/quest=28510 and hand it in first.\n2. Don't pick up any further quest from Konu Runetotem.\n3. Now you can pick up https://www.wowhead.com/quest=26589",
            date = "2014-09-23T14:13:45-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28510#comments:id=2005406",
        },
        {
            id = 1646764,
            score = 5,
            author = "Prettzel",
            text = "This quest is a Breadcrumb quest.\n\nBreadcrumb quests are quests that, even though you did not complete them and they were available at some point, have become unavailable permanently after certain conditions were met. If this happens to you, and you're a completionist, this quest can be marked as excluded in the Wowhead quest tracker if you are no longer able to complete it.\n\nThis quest becomes unavailable permanently, if either of the following conditions are met:\n\nhttps://www.wowhead.com/quest=25237 is completed.\nThis is one of the quests available in the quest hub that this quest points to, and is also considered a follow-up to this quest. Completing this quest will make all zone introductory quests leading to this npc, including this one, unavailable.\nhttps://www.wowhead.com/quest=28510 is completed.\nThis is a Warchief's Command quest leading to this zone. You can only complete this quest, or the Warchief's Command quest, not both. Completing the Warchief's Command quest will therefore make this quest unavailable.\nExamples of Breadcrumb quests and conditions making them unavailable:\nWarchief's Command quests.\nThey become unavailable if your character's level is too high, and the Warchief's Command board sends you to a different npc/zone.\nZone introductory quests.\nThis also includes Warchief's Command quests. These quests are often started in a certain lower level zone, and they direct you to the next zone. If there are several of these, including the Warchief's Command, directing you to the same zone/npc, completing one will mean the others become unavailable.\nQuest hub introductory quests.\nThese are quests that direct you to the next quest hub in a zone. If you've already completed the quests in that quest hub, the quest directing you to it may become unavailable.\nFollow-up quests.\nThese are uncommon, but still appear in older zones that have not been changed much in recent expansions. Sometimes a follow-up quest of quest X is available before you complete quest X. If you complete that follow-up quest and go back to the quest X giver, you may encounter the error 'You do not meet the requirements for that quest', leaving you unable to start it or turn it in.\nNote: A quest being unavailable does not necessarily mean it's unavailable permanently. If you have not met the aforementioned conditions, and the quest is still unavailable, then you may have missed certain required quests that precede this one, or you do not meet the requirements in some other way. Always verify this before excluding this quest.\n\nbased on MaxTheDragon's post",
            date = "2012-03-30T19:51:15-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28510#comments:id=1646764",
        },
        {
            id = 1196488,
            score = 2,
            author = "624744",
            text = "I can't seem to be able to access any of the \"war boards\", I know there is a min lvl requirement concerning each zone, but is there a max as well? Any 80's have an idea?",
            date = "2010-11-29T20:12:44-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28510#comments:id=1196488",
        },
        {
            id = 1281327,
            score = 2,
            author = "726332",
            text = "Feralas is more or less the same in terms of quests and scenery; however, there is a new quest chain which takes you inside a pit located at Dire Maul (not inside the instance) which is hosted by Cho'Gall. Radical for those looking for something a little offbeat while they level.\n\nYou recieve the quest from Orhan Ogreblade (http://www.wowhead.com/npc=39656#comments).",
            date = "2011-01-06T21:26:54-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28510#comments:id=1281327",
        },
    },
    [28511] = {
        {
            id = 1557986,
            score = 16,
            author = "503971",
            text = "This quest is a Breadcrumb quest.\n\nBreadcrumb quests are quests that, even though you did not complete them and they were available at some point, have become unavailable permanently after certain conditions were met. If this happens to you, and you're a completionist, this quest can be marked as excluded in the Wowhead quest tracker if you are no longer able to complete it.\n\nThis quest becomes unavailable permanently, if either of the following conditions are met:\nYour character is level 39 or higher, at which point this quest is replaced on the Hero's Call Board, by https://www.wowhead.com/quest=28503.\nhttps://www.wowhead.com/quest=14410 is completed.\nThis is a zone introductory quest leading to this zone. You can only complete this quest, or the zone introductory quest, not both. Completing the zone introductory quest will therefore make this quest unavailable.\nhttps://www.wowhead.com/quest=25447 is completed.\nThis is one of the quests available in the quest hub that this quest points to, and is also considered a follow-up to this quest. Completing this quest will make all zone introductory quests leading to this npc, including this one, unavailable.\n\nExamples of Breadcrumb quests and conditions making them unavailable:\n\nHero's call quests.\nThey become unavailable if your character's level is too high, and the hero's call board sends you to a different npc/zone.\nZone introductory quests.\nThis also includes hero's call quests. These quests are often started in a certain lower level zone, and they direct you to the next zone. If there are several of these, including the hero's call, directing you to the same zone/npc, completing one will mean the others become unavailable.\nQuest hub introductory quests.\nThese are quests that direct you to the next quest hub in a zone. If you've already completed the quests in that quest hub, the quest directing you to it may become unavailable.\nFollow-up quests.\nThese are uncommon, but still appear in older zones that have not been changed much in recent expansions. Sometimes a follow-up quest of quest X is available before you complete quest X. If you complete that follow-up quest and go back to the quest X giver, you may encounter the error 'You do not meet the requirements for that quest', leaving you unable to start it or turn it in.\n\nNote: A quest being unavailable does not necessarily mean it's unavailable permanently. If you have not met the aforementioned conditions, and the quest is still unavailable, then you may have missed certain required quests that precede this one, or you do not meet the requirements in some other way. Always verify this before excluding this quest.",
            date = "2011-10-30T20:19:54-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28511#comments:id=1557986",
        },
        {
            id = 1531476,
            score = 5,
            author = "Bengarion",
            text = "Not yet verified but...\n\nIf you accept/complete this quest you will more than likely be unable to accept/complete the more profitable breadcrumb quest The Wilds of Feralas (http://www.wowhead.com/quest=14410).\n\nHero's Call: Feralas! - 330 exp, 10 rep Darnassas, 0 silver\nThe Wilds of Feralas - 2450 exp, 0 rep, 25 silver",
            date = "2011-09-30T08:42:00-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28511#comments:id=1531476",
        },
