    [28514] = {
        {
            id = 1296834,
            score = 20,
            author = "142804",
            text = "Completion:\n\"Oh, Oilfist sent you?  Hah!\nDid he ever tell you how he got the name Oilfist?  You'll have to ask him about that one sometime. \"\nlulz",
            date = "2011-01-16T19:19:46-06:00",
