    [28517] = {
        {
            id = 1396580,
            score = 15,
            author = "katora",
            text = "When you land, it will automatically set your hearth to the Howling Oak, to prevent you returning to the phased Gilneas.  The upside of this is that you can just hearth on landing at Rut'theran Village, and it will take you right to the quest turn-in.",
