        },
        {
            id = 1281371,
            score = 3,
            author = "726332",
            text = "Quests were only slightly different, nothing much new to report. There's a new chain involving a crazy knight who takes you under his wing, and it ends up with you riding a horse while throwing rocks at a t-rex.\n\nClassic.",
            date = "2011-01-06T21:47:28-06:00",
