            date = "2015-12-01T20:47:35-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28526#comments:id=2282624",
        },
        {
            id = 1593930,
            score = 2,
            author = "Yagamimoon",
            text = "Why is my Warchief sending me to help a puny human? D:",
            date = "2011-12-10T16:21:48-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28526#comments:id=1593930",
        },
        {
            id = 1766361,
            score = 1,
            author = "487694",
            text = "Damnedest thing, but this quest completely disappeared from my quest log the moment I hit level 51 (it had been my intention to complete the quest after I finished the pet battle that tipped me over to 51), and although I visited all the city boards I couldn't pick it up again, yet at level 53 I noticed it had re-appeared. During this time I also had problems with all my equipment sets disappearing (and re-appearing) from my profile as the server kept on chucking me out and letting me back in. Patch bugs or Account bugs?",
            date = "2012-11-22T15:47:38-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28526#comments:id=1766361",
        },
    },
    [28527] = {
        {
            id = 1191683,
            score = 5,
            author = "109170",
            text = "Meh Silithus hasn't changed at all since the shattering. However this quest can lead to another in cenarion hold, which has a portal to the blasted lands which is a nicer questing area",
            date = "2010-11-27T21:43:50-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28527#comments:id=1191683",
        },
        {
            id = 1362263,
            score = 3,
            author = "597835",
            text = "As a lvl 58 goblin hunter, I recieved the quest from the board (some time earlier, and finally made it up there), and got to the turn in, I clicked on her, and her and the 2 NPCs next to her killed me. So, apparently you need to have had some contact with their faction (cenarion Circle) before attempting to turn this in. I tried just accepting a quest and doing it, and when I got to THAT turn inafter completing the requirement, I ran into the same problem that I could not turn it in.",
            date = "2011-03-09T12:27:12-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28527#comments:id=1362263",
        },
        {
            id = 1709470,
            score = 2,
            author = "QuickBASIC",
            text = "List of all the Warchief's Command breadcrumbs and the required level. Remember that none of these count for https://www.wowhead.com/achievement=7520 or associated achievements and are unavailable as soon as you start any chain in the zone it indicates.\n\nAs of 5.0.4 though, these quests give 60,000 guild exp (as does any level appropriate quest) so it may be worth while to come back and grab them as you are leveling when they come availible.\n[hr]\n\n[table]\n[tr][td align=left]Quest[/td][td align=left]Level[/td][/tr]\n[tr][td align=left]https://www.wowhead.com/quest=28496[/td][td align=left]9[/td][/tr]\n[tr][td align=left]https://www.wowhead.com/quest=28560[/td][td align=left]9[/td][/tr]\n[tr][td align=left]https://www.wowhead.com/quest=28494[/td][td align=left]9[/td][/tr]\n[tr][td align=left]https://www.wowhead.com/quest=28568[/td][td align=left]9[/td][/tr]\n[tr][td align=left]https://www.wowhead.com/quest=26964 (given by https://www.wowhead.com/npc=1515)[/td][td align=left]9[/td][/tr]\n[tr][td align=left]https://www.wowhead.com/quest=28493[/td][td align=left]19[/td][/tr]\n[tr][td align=left]https://www.wowhead.com/quest=28571[/td][td align=left]19[/td][/tr]\n[tr][td align=left]https://www.wowhead.com/quest=28089 (given by https://www.wowhead.com/npc=44640)[/td][td align=left]19[/td][/tr]\n[tr][td align=left]https://www.wowhead.com/quest=28572[/td][td align=left]24[/td][/tr]\n[tr][td align=left]https://www.wowhead.com/quest=28619 (given by https://www.wowhead.com/object=207279 in Hillsbrad)[/td][td align=left]24[/td][/tr]\n[tr][td align=left]https://www.wowhead.com/quest=28688[/td][td align=left]24[/td][/tr]\n[tr][td align=left]https://www.wowhead.com/quest=28532[/td][td align=left]24[/td][/tr]\n[tr][td align=left]https://www.wowhead.com/quest=28548[/td][td align=left]29[/td][/tr]\n[tr][td align=left]https://www.wowhead.com/quest=28549[/td][td align=left]29[/td][/tr]\n[tr][td align=left]https://www.wowhead.com/quest=28704[/td][td align=left]2