    [28531] = {
        {
            id = 1552460,
            score = 21,
            author = "503971",
            text = "This quest is a Breadcrumb quest.\n\nBreadcrumb quests are quests that, even though you did not complete them and they were available at some point, have become unavailable permanently after certain conditions were met. If this happens to you, and you're a completionist, this quest can be marked as excluded in the Wowhead quest tracker if you are no longer able to complete it.\n\nThis quest becomes unavailable permanently, if either of the following conditions are met:\nYour character is level 34 or higher, at which point this quest is replaced on the Hero's Call Board, by https://www.wowhead.com/quest=28511 and https://www.wowhead.com/quest=28552.\nhttps://www.wowhead.com/quest=25938 is completed.\nThis is a zone introductory quest leading to this zone. You can only complete this quest, or the zone introductory quest, not both. Completing the zone introductory quest will therefore make this quest unavailable.\nhttps://www.wowhead.com/quest=14384 is completed.\nThis is one of the quests available in the quest hub that this quest points to, and is also considered a follow-up to this quest. Completing this quest will make all zone introductory quests leading to this npc, including this one, unavailable.\n\nExamples of Breadcrumb quests and conditions making them unavailable:\n\nHero's call quests.\nThey become unavailable if your character's level is too high, and the hero's call board sends you to a different npc/zone.\nZone introductory quests.\nThis also includes hero's call quests. These quests are often started in a certain lower level zone, and they direct you to the next zone. If there are several of these, including the hero's call, directing you to the same zone/npc, completing one will mean the others become unavailable.\nQuest hub introductory quests.\nThese are quests that direct you to the next quest hub in a zone. If you've already completed the quests in that quest hub, the quest directing you to it may become unavailable.\nFollow-up quests.\nThese are uncommon, but still appear in older zones that have not been changed much in recent expansions. Sometimes a follow-up quest of quest X is available before you complete quest X. If you complete that follow-up quest and go back to the quest X giver, you may encounter the error 'You do not meet the requirements for that quest', leaving you unable to start it or turn it in.\n\nNote: A quest being unavailable does not necessarily mean it's unavailable permanently. If you have not met the aforementioned conditions, and the quest is still unavailable, then you may have missed certain required quests that precede this one, or you do not meet the requirements in some other way. Always verify this before excluding this quest.",
            date = "2011-10-24T09:31:26-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28531#comments:id=1552460",
        },
        {
            id = 3303615,
            score = 8,
            author = "Koviko",
            text = "To be perfectly clear, if you want to complete both breadcrumbs you need to:\n\nPick up https://www.wowhead.com/quest=28531 from a Hero's Call Board or the Adventure Guide\nGo to https://www.wowhead.com/npc=36410 in Desolace\nTurn in the quest without picking up the follow-up quest\nGo north into Stonetalon Mountains and go to Farwatcher's Glen\nPlayers without flying mounts who were already questing in Stonetalon will want to keep the quests that give them https://www.wowhead.com/item=56221 as this allows them to traverse the mountain quickly instead of having to go around\n\nPick up https://www.wowhead.com/quest=25938\nTurn in the quest to the same NPC as before",
            date = "2021-02-24T01:02:45-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28531#comments:id=3303615",
        },
        {
            id = 2579192,
            score = 4,
            author = "EmJii",
            text = "As of Patch 7.3.5 you can complete two breadcrumb quests which lead you to Desolace.\n\nYou have to keep the order to be able to do both of them.\n\n1.https://www.wowhead.com/quest=28531 (this quest can be found on every Hero's Call Board)\n\n2.https://www.wowhead.com/quest=25938 (you don't have to complete any further quests in order to accept this quest)",
            date = "2018-07-07T10:32:57-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28531#comments:id=2579192",
        },
