    [28537] = {
        {
            id = 1302781,
            score = 27,
            author = "239778",
            text = "How-To:\n\nStart at the questgiver. (46.9 , 53.8)\nGo south to the beginning of the path that leads to the waterfall. (47.0 , 58.7)\nContinue straight until you get to three trees. This is the frozen waterfall. (49.3 , 60.0)\nFollow the waterfall up for a few yards, then turn left when you see the lighter-looking ice. (49.9 , 60.9)\n\nMake sure to avoid the https://www.wowhead.com/npc=48681s; they will push you back.\n\nKeep going up the waterfall. The quest target, https://www.wowhead.com/npc=48678, is at the top. (50.7 , 63.6)\nKill him, loot https://www.wowhead.com/item=64463, and return to https://www.wowhead.com/npc=10920. (46.9 , 53.8)\n\nHere is a link to a map showing all the coordinates I mentioned. (http://www.wowhead.com/maps?data=618:469538470587493600499609507636)",
            date = "2011-01-21T07:19:20-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28537#comments:id=1302781",
        },
        {
            id = 1195933,
            score = 17,
            author = "460308",
            text = "You cant climb up the first bit of the waterfall, something I spent 10 minutes trying to do!    You need to go back out and round (to the right of the waterfall) and you can climb up the middle part of the waterfall to the shade of the spiritspeaker.",
            date = "2010-11-29T14:38:34-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28537#comments:id=1195933",
        },
        {
            id = 1188153,
            score = 16,
            author = "Ainasni",
            text = "Don't go in the cave, he's up the mountain (50,63)\n\nShade of the Spiritspeaker is his name.\nHe rolls \"Arcane rollers\" down the frozen waterfall, which knock you back and do some damage.",
            date = "2010-11-26T16:05:27-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28537#comments:id=1188153",
        },
        {
            id = 1812071,
            score = 6,
            author = "Gymlea",
            text = "1) go due west from the quest giver;\n2) when you come to the road, go left (south)\n3) when you come to the lamp at the ruins, go forward through the ruined door, behind which you will see the Arcane Rollers sliding down the Frozen Waterfall;\n4) get on the frozen waterfall, go right up the waterfall, avoid the Arcane Rollers.",
            date = "2013-02-10T20:10:44-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28537#comments:id=1812071",
        },
