    [28549] = {
        {
            id = 1347542,
            score = 20,
            author = "Macilles",
            text = "The entrance to South Barrens is located in Stonetalon Mountain (http://www.wowhead.com/zone=406) around 78;91 and the ramp that leads to Nura Pathfinder (http://www.wowhead.com/npc=37135) is at 30.6;11.0 in South Barrens (http://www.wowhead.com/zone=4709).\n\nFor people without coords:\nThe entrance to South Barrens is in the South-East corner of the Stonetalon Mountain map (http://www.wowhead.com/maps?data=406:777899) and the ramp is up to the right as you enter South Barrens. (map (http://www.wowhead.com/maps?data=4709:306112))\n\ngl",
            date = "2011-02-23T18:52:19-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28549#comments:id=1347542",
        },
        {
            id = 2004592,
            score = 11,
            author = "1361840",
            text = "You can do both this quest and \"Nura Pathfinder\".\n1. Get this quest and hand it in FIRST (it won't work the other way around).\n2. After you hand it in, don't accept any further quest from Nura Pathfinder.\n3. Now you can go to Witch Doctor Jin'Zil and get the quest \"Nura Pathfinder.\"",
            date = "2014-09-20T16:37:06-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28549#comments:id=2004592",
        },
