    [28550] = {
        {
            id = 3249017,
            score = 36,
            author = "Niixten",
            text = "If you are doing ATT and want this quest, you need to accept it from the adventure guide and not the hero's call board.",
            date = "2020-11-14T12:48:25-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28550#comments:id=3249017",
        },
        {
            id = 2572607,
            score = 11,
            author = "EmJii",
            text = "As of patch 7.3.5, this quest is no longer obtainable. Only one Hero's Call leads you now to Southern Barrens.\n\nI have to stay corrected.\n\ntoday i found out that you have 3 breadcrumb quests, including 2 Hero's Calls, that lead you to Soutern Barrens.\n\nYou have to keep the order to be able to do all 3:\n\n1.https://www.wowhead.com/quest=28551 (this one only appears in the adventurers guide, once you hit lvl 25)\n\n2.https://www.wowhead.com/quest=28550 (this one can be found on every Hero's Call Board, as long as you are lvl 25-60)\n\n3.https://www.wowhead.com/quest=25852 (this quest only appears once you quested through stonetalon mountains and completed https://www.wowhead.com/quest=25851)\n\nDon't accept any further quest in Southern Barrens, to be able to do all breadcrumbs.",
            date = "2018-06-06T16:26:41-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28550#comments:id=2572607",
        },
        {
            id = 5632152,
            score = 5,
            author = "Warmech60",
            text = "well I don't see anything in my adventure guide that shows this. Any help would be great",
            date = "2023-06-20T14:54:11-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28550#comments:id=5632152",
        },
        {
            id = 1905577,
            score = 4,
            author = "wgrinolds",
            text = "This quest seems to be equivalent to this one: https://www.wowhead.com/quest=25852",
            date = "2013-10-04T20:59:02-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28550#comments:id=1905577",
        },
        {
            id = 1498912,
            score = 2,
            author = "826336",
            text = "If you are looking for this quest and do not have it for some reason, try just going there and try continuing with this quest Survey the Destruction (http://www.wowhead.com/quest=25191).\n\nI had all zones done except for Southern Barrens and Dustwallow Marsh. After hours of searching to get the quest and a GM ticket, I was able to pick up the above quest and continue the chain and still get the Southern Barrens Quests (http://www.wowhead.com/achievement=4937) Achievement.",
            date = "2011-08-19T21:48:29-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28550#comments:id=1498912",
        },
    },
    [28551] = {
        {
            id = 1465923,
            score = 27,
            author = "239242",
            text = "If Blizzard had organized D-Day, the soldiers would probably have had to swim the channel...",
            date = "2011-07-10T03:03:24-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28551#comments:id=1465923",
        },
        {
            id = 1187785,
            score = 19,
            author = "423555",
            text = "I think there was supposed to be a boat going to Northwatch, but it go cut out, or something :/\nThe NPC ending this quest is a *dockmaster*, he asks you if you're \"fresh off the boat\", and the directions in the quest description that tell you to \"traveling south along the coast\" are just plain stupid.",
            date = "2010-11-26T13:42:27-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28551#comments:id=1187785",
        },
        {
            id = 1293133,
            score = 16,
            author = "olania",
            text = "I got there by porting to Theramore and riding north. Though the mass of lvl 35-37 undead and murlocs very nearly ate my lvl 32 mage alive. I did manage to get there by popping Darkflight and hitting Blink on every cooldown.\n\nWas at about half health, but I made it. Though my Water Elemental... gave his life so that I might survive... *sniff*",
            date = "2011-01-14T06:34:03-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28551#comments:id=1293133",
        },
        {
            id = 1637809,
            score = 9,
            author = "WeeRyza",
            text = "I flew from SW to Booty Bay (Cape of Stranglethorn) got the boat to Ratchet then flew to Northwatch Hold, where you need to be :)",
            date = "2012-03-10T11:21:21-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28551#comments:id=1637809",
        },
        {
            id = 5776768,
            score = 9,
            author = "entropicdragon",
            text = "This quest is only available from the Hero's Call Board.\nThere is another version of this quest, https://www.wowhead.com/quest=28550, which is only available from the Adventure Guide.\nYou can only have one of them in your quest log at a time. However if you complete one, someone can subsequently share the other one with you.",
            date = "2024-01-31T22:01:25-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28551#comments:id=5776768",
        },
    },
    [28552] = {
        {
            id = 1386197,
            score = 11,
            author = "473253",
            text = "Another way to get to Theramore is by picking up this quest (http://www.wowhead.com/quest=26596#comments) in Booty Bay, Cape of Stranglethorn and take the boat to Ratchet. You will be offered a free flight trip to Theramore, without the usual requirement of having to know the destination flight path.\nEspecially handy if you've been questing in STV, rather than the Wetlands, and you don't have the fp to get close to Menethil Harbour.\n\nI know this quest is shown in the series list at the top right as well, but I thought I should point out the difference between the two and why this one could be handier. :)",
            date = "2011-04-07T11:17:55-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28552#comments:id=1386197",
        },
        {
            id = 1511153,
            score = 2,
            author = "338957",
            text = "This quest cannot be picked up in Ironforge.",
            date = "2011-09-06T00:35:17-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28552#comments:id=1511153",
        },
        {
            id = 1531486,
            score = 2,
            author = "Bengarion",
            text = "Apparently the Hero's Call quests parallel usually more profitable breadcrumb quests. If you accept/complete one you can't accept the other.\n\nHero's Call: Dustwallow Marsh! - 330 exp, 10 rep Stormwind, 0 silver\n\nFlight to Theremore (http://www.wowhead.com/quest=26702) - 330 exp, 10 rep Alliance, 3.5 silver\n\nBefore picking up a Hero's Call quest you might want to check to see if there is a breadcrumb quest available. The breadcrumbs generally offer much more exp, rep, and silver. This Hero's Call quest isn't that much different from the breadcrumb.",
            date = "2011-09-30T09:01:58-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28552#comments:id=1531486",
        },
        {
            id = 2514862,
            score = 1,
            author = "Lintian",
            text = "So now as of Legion, King Anduin's orders send you to Theramore... which was destroyed before he became king.\n\nAh, WoW questing and its time paradoxes.",
            date = "2017-08-23T02:43:07-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28552#comments:id=2514862",
        },
        {
            id = 3131443,
            score = 1,
            author = "carsono311",
            text = "I would like to know if this quest can be completed first and then accept and complete https://www.wowhead.com/quest=26702 sequentially?  I know some breadcrumbs are overlapping now, so I was hoping someone else has tried it and could let me know?  Thanks.",
            date = "2019-06-28T21:11:10-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28552#comments:id=3131443",
        },
    },
    [28553] = {
        {
            id = 2101483,
            score = 45,
            author = "dominath92",
            text = "If you're unable to see https://www.wowhead.com/npc=41124, you just have to swap phase in Blasted Lands... To do that, you must speak with https://www.wowhead.com/npc=88206 and after that you probably can find https://www.wowhead.com/npc=41124.",
            date = "2015-02-08T15:09:18-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28553#comments:id=2101483",
        },
        {
            id = 1222444,
            score = 2,
            author = "Clajjan",
            text = "This quest sends you to the \"Hot new orc fortress!\"",
            date = "2010-12-10T16:57:04-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28553#comments:id=1222444",
        },
        {
            id = 2333926,
            score = 2,
            author = "Deltethnia",
            text = "This quest is mutually exclusive with the quest: Warchief's Command: Blasted Lands! (http://www.wowhead.com/quest=28671/warchiefs-command-blasted-lands)",
            date = "2016-05-25T01:07:11-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28553#comments:id=2333926",
        },
        {
            id = 6439526,
            score = 1,
            author = "Roxtoni",
            text = "WARNING for completionists!\n\nThis is the order I tested on Retail:\n\n1. Complete https://www.wowhead.com/quest=28671 and turn it in to https://www.wowhead.com/npc=41124. Do NOT accept any normal quests yet.\n2. Return to https://www.wowhead.com/npc=7623 in Swamp of Sorrows and complete https://www.wowhead.com/quest=28553, and turn it.\n\nIMPORTANT: https://www.wowhead.com/quest=28553 and https://www.wowhead.com/quest=28858 are mutually exclusive. Completing one makes the other unavailable. https://www.wowhead.com/quest=28858 is picked up from https://www.wowhead.com/npc=11118 in Winterspring.\n\n3. https://www.wowhead.com/quest=28865 was still available after that. Pick it up from https://www.wowhead.com/npc=50587 in Silithus and turn it.\n\nThe route that worked for me was: https://www.wowhead.com/quest=28671 → https://www.wowhead.com/quest=28553 → https://www.wowhead.com/quest=28865.\n\nNOTE: I was also able to complete https://www.wowhead.com/quest=28858 afterward by using Party Sync with another character that still had the quest available.",
            date = "2026-10-01T19:15:34-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28553#comments:id=6439526",
        },
        {
            id = 5447380,
            score = 0,
            author = "pimcha17",
            text = "If you currently have the Mag'har Orc unlock questline in your quest log, you will be in your own phase of the blasted lands and won't see Okrilla until you finish the Mag'har orc quests",
            date = "2022-10-06T18:03:12-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28553#comments:id=5447380",
        },
    },
