    [28556] = {
        {
            id = 1179778,
            score = 64,
            author = "214302",
            text = "You must be inside the Captain's tent on Corrahn's Dagger to place the nuke, despite what the item says about campsites. The Headland has it placed at the single tent near the base of the finger, while Gavin's Naze is under the giant gear near the tip.",
            date = "2010-11-24T00:42:42-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28556#comments:id=1179778",
        },
        {
            id = 1193895,
            score = 32,
            author = "wutru",
            text = "Where to place these.\n\nCampsite at Sofera's Naze.\nCaptain Iceheart's tent, right in the middle, at Corrahn's Dagger.\nThe tent in The Headland.\nThe big cogwheel next to pipe at Gavin's Naze.",
            date = "2010-11-28T16:22:47-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28556#comments:id=1193895",
        },
        {
            id = 1437125,
            score = 13,
            author = "pezz",
            text = "The parallel quest chain to this quest from the banshee Melisara has you alternatively slaughtering, assassinating, and poisoning your way through the camps, despite the fact that the main reason you're up there is to plant NUCLEAR BOMBS at all of the camps. Evidently the process of being turned into a banshee eliminates one's memory of anachronistic WoW WMDs.\n\n\"By the time they figure out it was you you'll be long gone\" or whatever. No, Lillith, by the time they figure out it was me the men I just poisoned will be VAPOR.",
            date = "2011-06-08T14:47:32-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28556#comments:id=1437125",
