        {
            id = 1671856,
            score = 12,
            author = "jtbalogh",
            text = "55,38 Sofera's Naze and campsite\n49,46 Corrahn's Dagger and Captain Iceheart's tent in the middle\n43,48 The Headland and tent with sleeping soldiers\n39,48 Gavin's Naze and big cogwheel near pipe\n\nI was able to use the Goblin Pocket-Nuke near or behind the tents, and did not have to be in them. Also Captain Iceheart wanders so ignore him and just focus on his tent.",
            date = "2012-05-30T22:51:02-05:00",
