            text = "Tip for rogues and kitties : placing the pocket-nuke does not break stealth, which makes this quest pretty easy.",
            date = "2010-11-27T18:21:45-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28556#comments:id=1191249",
