    [28559] = {
        {
            id = 1537336,
            score = 14,
            author = "434735",
            text = "The quest \"Elekks are Serious Business\" also gives more XP, rep and silver (220, 25 and 1 respectively)  than this quest. Grab that one instead. It's given at the top of the entrance.",
            date = "2011-10-07T14:34:39-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28559#comments:id=1537336",
        },
        {
            id = 3307852,
            score = 6,
            author = "Slackluster",
            text = "This quest cannot be picked up from the Hero's Call Board. However, when enabling Chromie Time Cataclysm you can pick it up from the Adventure Guide.",
            date = "2021-03-11T09:46:36-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28559#comments:id=3307852",
        },
        {
            id = 2455551,
            score = 5,
            author = "TheFharaoh",
            text = "For some Hero's Call quests you can complete the Hero's Call quests and the other breadcrumb quest if you pick the Hero's Call quest FIRST and turn it in, but don't accept any other quests in the new zone. You can then go back and pick the other breadcrumb quest. That way you can complete both breadcrumb quests.\n\nThat does not work with this breadcrumb quest though. I tested it with two characters. You can only complete one of the breadcrumbs so I suggest you ignore this one and take Elekks Are Serious Business (http://www.wowhead.com/quest=9625/elekks-are-serious-business) since this one gives less experience and reputation.",
            date = "2016-12-21T14:15:26-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28559#comments:id=2455551",
        },
        {
            id = 2856276,
            score = 5,
            author = "mindaz3",
            text = "It seems that after the new zone scaling and adventure board update, this quest can no longer be obtained by regular means from adventure board.\n\nIt only appears in the adventure guide in-game page after reaching level 11 and disappears before reaching level 15, never to be seen again, and can only be started from that.\n\nStrangely enough, any low level player who can get this quest in time, can share it with any higher level characters.",
            date = "2018-12-04T04:14:05-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28559#comments:id=2856276",
        },
        {
            id = 3250470,
            score = 3,
            author = "VintageGC",
            text = "since the latest lvl changes you can not pick it up at lvl 1,2,3,4,5 I even went so far as to get to lvl 11 its not there even went to the draenei starting zone to see if its now just a quest giver who gives it. However, I think blizzard forgot to readd it back in.",
            date = "2020-11-18T05:43:48-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28559#comments:id=3250470",
        },
    },
