    [28565] = {
        {
            id = 2623599,
            score = 5,
            author = "Mortimerty",
            text = "As of Patch 7.3.5 you can complete two breadcrumb quests which lead you to Wetlands.\n\nYou have to keep the order to be able to do both of them.\n\n1. Hero's Call: Wetlands! (https://wowhead.com/quest=28565) (this quest can be found on every Hero's Call Board)\n\n2. Checking on the Boys (https://wowhead.com/quest=26137) (you don't have to complete any further quests in order to accept this quest)",
            date = "2018-10-14T15:50:00-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28565#comments:id=2623599",
        },
        {
            id = 1473375,
            score = 3,
            author = "Kayaku",
            text = "This Quest will NOT be available to you if you have accepted or completed its twin quest Checking on the Boys (http://www.wowhead.com/quest=26137), or if you already meet the requirements for the following \"Hero's Call\" Quest, which is in this case reaching level 24 or higher.",
            date = "2011-07-18T13:41:05-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28565#comments:id=1473375",
        },
        {
            id = 5797459,
            score = 1,
            author = "talonzor",
            text = "So, I completed the Loch Modan quests including the Checking on the Boys quest (turned in), didn't took The Stolen Keg quest, went to IF and took the heroes call: wetlands from the board and could turn it in. Then I continued with The Stolen Keg.",
            date = "2024-03-09T01:21:10-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28565#comments:id=5797459",
        },
    },
