    [28569] = {
        {
            id = 1202069,
            score = 23,
            author = "sasosi",
            text = "She is located at 78.3, 59.0 (http://www.wowhead.com/maps?data=46:783590).",
            date = "2010-12-02T12:12:41-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28569#comments:id=1202069",
        },
        {
            id = 1690698,
            score = 7,
            author = "72516",
            text = "This NPC is located to the right of the road that exits Burning Steppes in the far southeastern corner. She's stationed on a small raised area where the valley begins. On the map, the road is shown entering the Redridge Mountains and is the road east of Morgan's Vigil.",
            date = "2012-07-21T12:28:49-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28569#comments:id=1690698",
        },
        {
            id = 5457487,
            score = 7,
            author = "MarcellusWa",
            text = "This breadcrumb quest appeared for me after completing the Hero's Call: Swamp of Sorrows and running back to Oralius.\nBefore that he did not offer any quest at all.",
            date = "2022-10-25T09:44:12-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28569#comments:id=5457487",
        },
        {
            id = 1259752,
            score = 5,
            author = "745733",
            text = "If you got your Bloodsail Admiral title, and still havent paid your way back to friendly with the goblins, dont get on that rocket.",
            date = "2010-12-26T09:56:47-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28569#comments:id=1259752",
        },
        {
            id = 1314689,
            score = 5,
            author = "Hemingray",
            text = "Completing this quest, and all the ones to follow in Bogpaddle, do not increase Booty Bay rep, nor do they decrease Bloodsail Buccaneers rep.",
            date = "2011-01-29T16:37:47-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28569#comments:id=1314689",
        },
    },
    [28570] = {
        {
            id = 1202068,
            score = 43,
            author = "sasosi",
            text = "She is located at 78.3, 59.0 (http://www.wowhead.com/maps?data=46:783590). Oh, and her rocket is perfectly safe.",
            date = "2010-12-02T12:11:49-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28570#comments:id=1202068",
        },
        {
            id = 1576205,
            score = 10,
            author = "304770",
            text = "If you do https://www.wowhead.com/quest=28677 you cannot do this quest. Just to check, I flew to Flame Crest, abandoned it, and https://www.wowhead.com/npc=10260 then offered me this one. I assume the reverse is also true but didn't verify it.",
            date = "2011-11-19T21:11:45-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28570#comments:id=1576205",
        },
        {
            id = 2335270,
            score = 4,
            author = "poozer",
            text = "Seriously?  You can't stick a pin in that map to show where the actual rocket is?",
            date = "2016-05-29T09:17:26-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28570#comments:id=2335270",
        },
        {
            id = 5720005,
            score = 1,
            author = "Featherblood",
            text = "If you cant accept or turn in any quest from the two NPCs you need to start this questline, it might be because your reputation with the goblin factions is too low.\n\nYou can donate 40 Silk Cloth and 4 Red Dye multiple times to the Bloodsail Traitor in cape of Stranglethorn to raise the reputations to neutral. It's super cheap to do.",
            date = "2023-11-06T12:26:56-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28570#comments:id=5720005",
        },
        {
            id = 6401324,
            score = 1,
            author = "Roxtoni",
            text = "I just confirmed it: YES, you can complete both quests!\n\nI’m currently in Chromie Time. First, accept https://www.wowhead.com/quest=28677. You’ll notice that https://www.wowhead.com/npc=10260’s quest will disappear, but don’t worry. Turn in https://www.wowhead.com/quest=28677, and do not complete any other quests in the Swamp of Sorrows.\n\nAfter that, go back to the goblin https://www.wowhead.com/npc=10260, pick up https://www.wowhead.com/quest=28570, get the rocket, you need to go to 78.3, 59.0 (https://www.wowhead.com/maps?data=46:783590) and turn it in.",
            date = "2026-08-17T16:27:53-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28570#comments:id=6401324",
        },
    },
    [28571] = {
        {
            id = 1317526,
            score = 9,
            author = "noora",
            text = "If you pick up this quest in Silvermoon City, use the Orb of Translocation (49.5, 14.8) in Sunfury Spire in Silvermoon City to get to Undercity. From there you can either \"follow the road south\" as described in the quest text, or you can go inside Undercity , find the bat handler, and take a flight to  The Sepulcher in Silverpine Forest. (Even though my character had never been there before, the flight was available to me.) From The Sepulcher you can run into Hillsbrad to complete the quest. You can also run all the way from Undercity to Hillsbrad if you prefer.",
            date = "2011-01-31T22:12:59-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28571#comments:id=1317526",
        },
        {
            id = 1883983,
            score = 4,
            author = "tarc",
            text = "One thing to note now is that with flightpaths no longer automatic as they were for a time, you'll have to hoof it the old-fashioned way.  So once you take the orb to Undercity, head south to towards the \"Forsaken High Command\" in SIlverpine and wait for the https://www.wowhead.com/npc=44731 to spawn and hitch a ride south.",
            date = "2013-08-04T17:19:33-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28571#comments:id=1883983",
        },
