    [28573] = {
        {
            id = 2866109,
            score = 8,
            author = "Mortimerty",
            text = "As of Patch 8.1 you can complete two breadcrumb quests which lead you to Arathi.\n\nYou have to keep the order to be able to do both of them.\n\n1. https://www.wowhead.com/quest=28573 (this quest can be found on every Hero's Call Board)\n\n2. https://www.wowhead.com/quest=26139 (you have to complete https://www.wowhead.com/quest=26128 in order to accept this quest)",
            date = "2019-01-15T07:41:02-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28573#comments:id=2866109",
        },
        {
            id = 5372952,
            score = 3,
            author = "Antyvas",
            text = "If you're on a high-level character going back and completing these, you may need to speak to [npc=141649 domain=www] to change phase.",
            date = "2022-05-12T11:32:23-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28573#comments:id=5372952",
        },
        {
            id = 1563819,
            score = -9,
            author = "martychonks",
            text = "Would that you were a company, but we'll have to make do with with what we have.\nEasily the worst grammar I have ever seen from Blizzard. I'm not even sure what it's trying to say. That's a plus 50 EKP (English Kill Points).",
            date = "2011-11-05T15:25:50-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28573#comments:id=1563819",
        },
    },
    [28574] = {
        {
            id = 1295243,
            score = 35,
            author = "139445",
            text = "Need to get here?  Do the few quests at the entrance of Arathi Highlands and they'll eventually take you to Hammerfall of the same zone.  There Drum Fel will also give you quest to go to Revantusk Village, and he'll direct you to the flightmaster in Hammerfall, who in turn will fly you straight to the village for free.  GL",
            date = "2011-01-15T17:11:24-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28574#comments:id=1295243",
        },
        {
            id = 1614163,
            score = 6,
            author = "abexy",
            text = "You can do both this quest and Revantusk Village (http://www.wowhead.com/quest=26430).",
            date = "2012-01-21T00:14:19-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28574#comments:id=1614163",
        },
        {
            id = 1596013,
            score = 1,
            author = "martinb714",
            text = "I got the Q in UC, and explored as I went, opening up that toons map and gathering. I went to hinterlands via chillwind/darrowmere lake/plaguemist ravine and elder was awol. It may be the route that is bugging the quest, but the coast of darrowmere is killer place to lvl gathering.",
            date = "2011-12-14T10:40:11-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28574#comments:id=1596013",
        },
