    [28576] = {
        {
            id = 1372061,
            score = 43,
            author = "iranou",
            text = "Easiest way to get to Western Plaguelands (if you haven't got flight path to Arathi) is by portal via this quest (http://www.wowhead.com/quest=28749) in Booty Bay, which is easier to reach from Stormwind, or by boat from Ratchet.",
            date = "2011-03-20T19:29:38-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28576#comments:id=1372061",
        },
        {
            id = 2512837,
            score = 16,
            author = "llangevi",
            text = "Wow added a path from the Hinterlands to the Western Plaguelands called \"Plaguemist Ravine\" Follow the path at 17,49, it will go a short way and turn a bit to the left. It is a well marked path. It makes it easier for us alliance folks!",
            date = "2017-08-09T03:01:37-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28576#comments:id=2512837",
        },
        {
            id = 3144500,
            score = 8,
            author = "Mortimerty",
            text = "It's possible to complete all breadcrumb quests which lead you to Western Plaguelands.\n\nYou have to keep the order to be able to do both of them.\n\n1. https://www.wowhead.com/quest=28576 (this quest can be found on every Hero's Call Board)\n\n2. https://www.wowhead.com/quest=27158 or https://www.wowhead.com/quest=28505 or https://www.wowhead.com/quest=28749 (they are all mutually exclusive, but all marked as completed after completing one of them)",
            date = "2019-07-31T08:34:41-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28576#comments:id=3144500",
        },
        {
            id = 2542924,
            score = 2,
            author = "Sharemydread",
            text = "This was pretty high on the Google Search on how to get the Western Plaguelands.\n\nIf your running alts with heirlooms I highly recommend https://www.wowhead.com/item=150746 for Alliance and https://www.wowhead.com/item=150745 for Horde. It will give you a flight path right to Andorhal, Plaguelands where the Hero's Call is. It will save you a lot of time and you can fly there cause you probably didn't make it to booty bay.\n\nIf this is your main the booty bay work well if you took that path.",
            date = "2017-12-28T18:55:38-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28576#comments:id=2542924",
        },
        {
            id = 3131461,
            score = 1,
            author = "carsono311",
            text = "I would like to know if you can complete this quest and then accept and complete https://www.wowhead.com/quest=27158, and/or https://www.wowhead.com/quest=28505, and/or https://www.wowhead.com/quest=28749 sequentially?  I know some breadcrumb quests overlap a bit now and I was wondering if anyone has done/tried it yet?  Thanks.",
            date = "2019-06-28T21:43:54-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28576#comments:id=3131461",
        },
    },
    [28577] = {
        {
            id = 1630353,
            score = 6,
            author = "Eillesthis",
            text = "Optional breadcrumb quest to https://www.wowhead.com/npc=45417.\nhttps://www.wowhead.com/quest=27683 from the Western Plaguelands\nhttps://www.wowhead.com/quest=27684 from Light's Hope Chapel\nhttps://www.wowhead.com/quest=28578 from Alliance cities\nhttps://www.wowhead.com/quest=28577 from Horde cities\nare all optional, exclusive, and unavailable one you progress through her quest chain.",
            date = "2012-02-22T12:49:01-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28577#comments:id=1630353",
        },
        {
            id = 1358311,
            score = 5,
            author = "RyokoLam",
            text = "Believe you'll miss this quest if you've continued questing through Western Plaguelands into Eastern Plaguelands, gaining a quest in Western plaguelands that leads you onwards to the location.\n\nWhich should result in you missing this quest and unable to complete it also if you taken the above mentioned quest line.",
            date = "2011-03-05T13:14:40-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28577#comments:id=1358311",
        },
        {
            id = 1558843,
            score = 5,
            author = "Eatmypie",
            text = "It says so up top, but it's important to note that you CANNOT obtain this quest from the call boards in Org or Thunder Bluff.",
            date = "2011-10-31T19:21:06-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28577#comments:id=1558843",
        },
