    [28587] = {
        {
            id = 1192741,
            score = 23,
            author = "707511",
            text = "This quest is picked up from High Warlord Cromush located in the middle of Tarren Mills.\n\nDo note that this quest will not be available until you have done the questline starting with Kingslayer Orkus. He is in the Ruins of Southshore, south of the town at the docks. He can be found splashing around in the water, drowning. He will give you the first quest \"*gurgle*Help!*gurgle*\"\n\nIf you continue doing the quests given by Orkus, you will eventually end up in Tarren Mills handing in the last quest to High Warlord Cromash. He will then make this quest available.\n\nA fun questline to do :)",
            date = "2010-11-28T08:13:49-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28587#comments:id=1192741",
        },
    },
    [28600] = {
        {
            id = 1186414,
            score = 41,
            author = "139938",
            text = "You'll pop into a cinematic and listen to Drek'Thar's speech:\n\nSo you have come seeking our aid?\n\nI... *cough* I have been alive for a very long time.  In that time I have seen and done terrible things.\n\nThings that still keep me awake at nights.\n\nBut these terrible things that I have done and the people that I have harmed - I know them... I face them... and I feel remorse for them.\n\nBut the Forsaken.  *cough*  What do they feel?\n\nThey ravage the land and destroy everything that they touch.  How many lives have been lost to their vile poisons?\n\nHow many innocents have fallen before the Forsaken war machine?\n\nCountless... countless lives... *cough*\n\nYes... I have done terrible things, but nothing could ever be as terrible as lending aid to the Forsaken.\n\nYou go back to that spineless orc who would not come see me and you tell him that the Frostwolf clan will not aid the Forsaken.  Not now, not ever!\n\nBEGONE!",
            date = "2010-11-26T01:01:44-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28600#comments:id=1186414",
        },
        {
            id = 1429841,
            score = 23,
            author = "Liri",
            text = "Sometimes the enemy of my enemy...is simply their enemy.",
            date = "2011-05-29T03:53:27-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28600#comments:id=1429841",
        },
        {
            id = 1841563,
            score = 8,
            author = "1114037",
            text = "The cinematic kind of reminded me of The Godfather, not sure why.",
            date = "2013-04-10T18:02:23-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28600#comments:id=1841563",
        },
        {
            id = 1545208,
            score = 5,
            author = "894060",
            text = "I can't see Garrosh tolerate any insubordination seeing the way he runs the Horde, which leads to the question, will Frostwolf Clan be branded traitors and exiled? Since WoW is an mmo I find it hard to believe that Blizzard is willing to remove a pvp faction (or maybe replace it) but story wise it would make sense and be an interesting move by Garrosh. If it does happen it would make Thrall's (possible) return to the Horde as Warchief that more difficult since he is a part of the Frostwolves.",
            date = "2011-10-17T10:25:46-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28600#comments:id=1545208",
        },
        {
            id = 1937940,
            score = 3,
