    [28617] = {
        {
            id = 1181367,
            score = 24,
            author = "149601",
            text = "As the screenshot indicates, the zombies in this wave will only spawn in the center three rows. Don't waste your sunlight by building shooters on the edge rows.",
            date = "2010-11-24T11:48:18-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28617#comments:id=1181367",
        },
        {
            id = 1190228,
            score = 15,
            author = "wye43",
            text = "The use of Sunflowers:\n\nThe tooltip says: \"Creates a Sunflower, which concentrates Sun Power from the sky. Sun Power is used to create other plants.\"\n\nThe effect of building Sunflowers is that the \"Solar Power\" units (not Sun Power!) drop more often on the field. Solar Power look like glowing orbs.\n\nYou still have to pick up the Solar power youself(by right clicking on them), the sunflowers do not generate any solar power.\nAlso they do not lower the cool-down on building plants.\n\nSolar Power is a energy-like resource that you can use to build other units, like \"Plant Spitter\", \"Plant Freezya\" or \"Plant Rocknut\". You can see the current amount(0-100) as a power bar under your character frame.",
            date = "2010-11-27T10:54:37-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28617#comments:id=1190228",
        },
        {
            id = 1345820,
            score = 12,
            author = "784024",
            text = "I made a video of the entire chain. Here's a link to this one:\nFlower Power (http://www.youtube.com/watch?v=fWB1-LgJLXs)",
            date = "2011-02-22T08:20:56-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28617#comments:id=1345820",
        },
        {
            id = 2296389,
            score = 1,
            author = "Waterfuzz",
            text = "Don't put anything in the last rightmost row (where the enemies come out) to avoid getting the whole thing bugged.\nNot even the pumpkin.",
            date = "2016-01-09T13:44:18-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28617#comments:id=2296389",
        },
        {
            id = 1178787,
