    [28629] = {
        {
            id = 1282970,
            score = 27,
            author = "rowaweb",
            text = "Once you accepted this quest (http://www.wowhead.com/quest=28627), Are We There, Yeti? (http://www.wowhead.com/quest=28629) is available.\n\nAll pre-quests start with Hammer Time (http://www.wowhead.com/quest=28609)",
            date = "2011-01-07T20:37:56-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28629#comments:id=1282970",
        },
        {
            id = 1933225,
            score = 26,
            author = "361005",
            text = "If you are an engineer seeking to learn the tranquil mechanical yeti pattern, this quest series will no longer teach it.  Upon completing Yetiphobia, one will no longer get offered the follow \"quest\" to learn the actual pattern\n\nThe quest has been confirmed by the GM as being removed. So, completing the Yeti quest chain will not get you this pattern any longer per Scagarrde, Customer Service Representative\n\n\"Hey there!\n\nI sincerely apologize that I was unable to speak with you directly, and for the wait you have had. >.. Others will be able to see your posts and openly chat about them. Sometimes this may lead to a more constructive idea, as others would be able to brainstorm along with you about the changes you would like to see! Just choose the forum that relates to what you would like to see changed and post your thoughts and ideas there.\n\nThe decision making process and all the changes that happen to the game is done by our developers, sadly not game masters. If you want more information about this new system check this out >\n\nI hope you have a great rest of the day!\"",
            date = "2014-01-09T23:29:29-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28629#comments:id=1933225",
        },
        {
            id = 1316505,
            score = 7,
            author = "Dyzek",
            text = "Wow, they really improved the drop rate of those furs!  Compared to a lot of other quests in Cata, a fur every 2-4 may seem like a big deal, but for those who did this back in vanilla, you could easily kill a couple dozen yeti per drop.",
            date = "2011-01-31T01:19:01-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28629#comments:id=1316505",
        },
        {
            id = 1418750,
            score = 4,
            author = "StriderRyu",
            text = "I've read elsewhere that if you've done some of these quests pre-Cata, some parts of the chain won't be available to you now.  Seems a bit disjointed.  Why is this quest still available?",
            date = "2011-05-14T16:31:28-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28629#comments:id=1418750",
        },
        {
            id = 1429171,
            score = 4,
            author = "835990",
            text = "One you get the quest called \"Fresh From The Hills\" from Seril Scourgebane, this quest (Are We There, Yeti?) becomes available.",
            date = "2011-05-28T06:10:13-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28629#comments:id=1429171",
        },
    },
    [28630] = {
        {
            id = 1179015,
            score = 38,
            author = "244380",
            text = "Quest is a reference to Star Wars - Episode Five - The Empire Strikes Back. Luke is caught by a Wampa and wakes in a cave hanging upside down. Also Echo Three was the callsign of Luke Skywalker while acting as a scout prior to the Battle of Hoth.\n\nhttp://www.youtube.com/watch?v=OOvJOV0PxHg",
            date = "2010-11-23T19:42:06-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28630#comments:id=1179015",
        },
        {
            id = 1226291,
            score = 20,
            author = "208337",
            text = "\"Echo three to Echo seven; Han ol' buddy, do ya read me?\"\n-Luke Skywalker, Star Wars Episode V\n\nThis quest made me sooooo happy. The nerd inside me was just flippin' out during the next part.\n\nWas anyone else like \"Where's my lightsaber in the snow below me, and why am I not trying to force-pull it?\"\n\nA+, Blizzard, well done.",
            date = "2010-12-12T01:14:07-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28630#comments:id=1226291",
        },
        {
            id = 1182215,
            score = 19,
            author = "181947",
            text = "Echo Three is a box that is sitting right outside the yeti cave. When you interact with the box, it teleports you into the depths of the cave. You will be hanging upside down in a chunk of ice. A \"raid warning\" will appear telling you to chop the ice to free yourself. When you do, you drop to the floor and there is a huge yeti named Icewhomp who you have to kill.\n\nI did this quest on my warlock, and when I freed myself from teh ice, my pet was gone and I had to resummon (don't know if other pet classes have the same issue).\n\nAfter killing Icewhomp, don't dawdle in the center of the room, because he respawns very quickly.",
            date = "2010-11-24T16:16:53-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28630#comments:id=1182215",
        },
        {
            id = 1379240,
            score = 5,
            author = "350446",
            text = "This bugged for me, too, though differently.\n\nI turned in the Echo Three quest, and it told me something was approaching.  Well, that yeti ambusher appeared, was unattackable by me (which I guess it is supposed to be) but then nothing at all happened until the ambusher suddenly just dropped dead without teleporting me in.  Because this is triggered by turning in the quest, I can't abandon and retry.",
            date = "2011-03-29T13:41:18-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28630#comments:id=1379240",
        },
        {
            id = 1180250,
            score = 4,
            author = "462955",
            text = "Was there supposed to be a quest after this? I think I might have not gotten the quest to kill the yetti due to a glitch. I was shapeshifted into a iron dwarf at the time and it might have screwed with the quest progression.",
            date = "2010-11-24T04:36:49-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28630#comments:id=1180250",
        },
    },
    [28631] = {
        {
            id = 1339494,
            score = 30,
            author = "787383",
            text = "For the quest The Perfect Horns, don't waste your time specifically looking for Icewhomp. Instead, when you complete the quest Echo Three, you'll be teleported directly to him, and in an Empire Strikes Back reference, you'll find yourself hanging upside down from ice from the roof of the cave.",
            date = "2011-02-17T07:16:48-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28631#comments:id=1339494",
        },
        {
            id = 1236354,
            score = 15,
            author = "258687",
            text = "This is a blatant reference to star wars when luke gets suddenly knocked out by a yeti and wakes up hanging upside down with his legs stuck in ice. Then he kills the yeti.\n\nEdit: Apparently its not the same yeti, the one he kills is the other yeti's mate",
            date = "2010-12-15T17:07:53-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28631#comments:id=1236354",
        },
        {
            id = 1226060,
            score = 14,
            author = "Porcupinez",
            text = "If you did the quest before the  cataclysm changes to scare her friends you won't be able to do this quest",
            date = "2010-12-11T22:58:14-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28631#comments:id=1226060",
        },
        {
            id = 6045460,
            score = 4,
            author = "geekySmurfer",
            text = "/way 66.81 54.48",
            date = "2025-01-10T05:47:56-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28631#comments:id=6045460",
        },
        {
            id = 1209943,
            score = 3,
            author = "286399",
            text = "To find Icewhomp (http://www.wowhead.com/npc=49235#comments:id=1180965), and save some time with other quests in the same area, see my comment on his page.",
            date = "2010-12-06T09:27:34-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28631#comments:id=1209943",
        },
    },
    [28632] = {
        {
            id = 1429055,
            score = 78,
            author = "810483",
            text = "Entrance to the cave is 67.54, in case anyone has trouble finding it.",
            date = "2011-05-28T01:25:02-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28632#comments:id=1429055",
        },
        {
            id = 1182240,
            score = 56,
            author = "181947",
            text = "I did this quest on my Warlock, and in order to be able to collect the ice chunks, I had to do two things:\n\n1) Put pet on passive. The demon would attack the ice blocks when I attacked, and when the block was broken, I could not loot any ice.\n\n2) Use melee attcks to chop the ice blocks.",
            date = "2010-11-24T16:21:24-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28632#comments:id=1182240",
        },
        {
            id = 1307925,
            score = 28,
            author = "piderman",
            text = "One of these blocks dodged me once -.-",
            date = "2011-01-24T12:07:16-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28632#comments:id=1307925",
        },
        {
            id = 1456530,
            score = 17,
            author = "db997c",
            text = "Best to do this with quests Echo Three (http://www.wowhead.com/quest=28630), Are We There, Yeti? (http://www.wowhead.com/quest=28629) and The Perfect Horns (http://www.wowhead.com/quest=28631).\n\nGo to the sensor for the Echo Three quest first -- this will complete the quest and teleport you into the back of the cave where Icewhomp is.\n\nDefeat Icewhomp to complete The Perfect Horns, then you can work the Fresh From the Hills & Are We There, Yeti? quests as you have to fight your way out of the cave.\n\nAny yeti pelts you still need for Are We There, Yeti? can be mopped up going down the hillside as you head back to Everlook.\n\nP.S. Decent reward items for arms classes, but nothing for spellcasters.",
            date = "2011-07-01T03:21:48-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28632#comments:id=1456530",
        },
        {
            id = 3143910,
            score = 14,
            author = "TheSkullpitter",
            text = "Two possibilities exist: the person who designed this area has never been stunned in World of Warcraft, or the person who designed this area has been stunned in World of Warcraft, and it gave them sexual pleasure. All of these damn yetis can stun you for two seconds, and they will, every single time, and you have to kill about three hundred thousand of them to do the quests in this area. Have fun watching the game play with itself! They can even cast the stun through being stunned themselves, making me think possibility #2 is more of a definitely.\n\nAlso, because this zone is poorly designed, three more yeti-related quests pop into existence once you accept this one. If the zone has properly trained you to expect only one quest at a time, which has been the case since you arrived, you might not notice them. In that case you'll be forced to stage two consecutive yeti genocides in a row, and even if that totally sounds like your kind of fun, let me tell you, it totally is not.",
            date = "2019-07-28T15:57:18-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28632#comments:id=3143910",
        },
    },
    [28634] = {
        {
            id = 1318331,
            score = 25,
            author = "Aramaru",
            text = "I think this quest is supposed to illustrate the.. instability of the guy giving you the task, since the local owlbeasts aren't organized or more predatory then any other beast. They don't appear to be guarding anything or have a reason to be here either, so.. you're basically killing them for existing.\n\nAs for completing this quest, I suggest looking around Durnholde Keep's northern and eastern walls. South of Eastpoint Tower, although marked as an area where they spawn, mostly has bears and wild horses instead.",
            date = "2011-02-01T14:54:51-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28634#comments:id=1318331",
        },
        {
            id = 2579035,
            score = 9,
            author = "sonofabear85",
            text = "It's not mentioned here but you will not complete the Eastpoint Towerhttps://www.wowhead.com/achievement=4895 without the following quests completed:\n\nhttps://www.wowhead.com/quest=28643\nhttps://www.wowhead.com/quest=28644\nhttps://www.wowhead.com/quest=28645\nhttps://www.wowhead.com/quest=28646\nhttps://www.wowhead.com/quest=28647",
            date = "2018-07-06T21:20:17-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28634#comments:id=2579035",
        },
        {
            id = 1671831,
            score = 7,
            author = "Yofi",
            text = "Since the questgiver is apparently some sort of psychologist, it may not just be a coincidence that \"extinction\" is also a psychological term (http://en.wikipedia.org/wiki/Extinction_(psychology)), meaning when a stimulus no longer triggers a learned response. This term is used in the treatment of anxiety disorders, which this paranoid questgiver might suffer from…",
            date = "2012-05-30T19:58:08-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28634#comments:id=1671831",
        },
        {
            id = 1632259,
            score = 4,
            author = "868988",
            text = "Something to get a good 'Lol' at. As the reason he wants them dead is he thinks they are planning an attack, however, I found them spaced out atleast about 100 or 200 yards away from each other. Needless to say, they probably aren't organizing an attack; they're just doing what owl-beasts do. You know... /hoot",
            date = "2012-02-26T23:09:23-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28634#comments:id=1632259",
        },
        {
            id = 1857717,
            score = 1,
            author = "rehlyihmah",
            text = "Made me giggle because of this:\nhttps://www.youtube.com/watch?v=XfpDiyqiil8\n\nThe song is called Extinction. See what I mean?\nCoincidences!",
            date = "2013-05-25T11:59:47-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28634#comments:id=1857717",
        },
    },
