        {
            id = 1187744,
            score = 2,
            author = "710102",
            text = "This seems kinda bugged for me.\nAfter finishing the 2 pre-q it does not pop up for me, and the npc does not offer the quest.\nSame bug with the Brumeran chain too.",
            date = "2010-11-26T13:24:36-06:00",
