        },
        {
            id = 1359622,
            score = 2,
            author = "483979",
            text = "I suspect the colorful descriptions of the bear meat are a nod to Bear Grylls, the star of Discovery Channel's survival show Man vs. Wild. He often has to eat whatever he can find, and perhaps the most entertaining part of the show is watching him eat and describe various terrible things, explaining that they taste like old cheese and dirt wrapped in a used sweatsock and left in the sun for a week, or something equally disgusting.",
            date = "2011-03-06T21:16:32-06:00",
