    [28640] = {
        {
            id = 1526448,
            score = 13,
            author = "rogermw",
            text = "The Frostsabers and Frostsaber Stalkers in the area count toward the quest, but the Young Frostsabers and Frostsaber Huntresses don't.\n\nThe Young Frostsabers don't count because they're only level 51 (even though they have ~600 more health than the level 53 Frostsabers).\nThe Frostsaber Huntresses don't count because they're the objective of the follow-up quest.",
            date = "2011-09-24T11:35:56-05:00",
