    [28643] = {
        {
            id = 1161959,
            score = 12,
            author = "83214",
            text = "Ah, yes. You gotta love the way Blizzard gives us the ring of blood style quest chains in Cataclysm!",
            date = "2010-11-04T14:33:49-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28643#comments:id=1161959",
        },
        {
            id = 1250870,
            score = 9,
            author = "693459",
            text = "Very easily soloable as a mage (or any other ranged class, I guess).\n\nRun in circles around the eastern edge of the ruined keep of which he spawns on top of. As a mage, you can blink away from range when he casts his cyclone/tornado, but you can't silence him at all.\n\nDone with no potions, Lifeblood, Bandages, or anything else.",
            date = "2010-12-21T19:00:03-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28643#comments:id=1250870",
        },
        {
            id = 1191012,
            score = 7,
            author = "116738",
            text = "Soloable as a 27 Combat Rogue completely in questing gear.\n\nSimply open with cheap shot, evasion when it is about to wear out, keep slice and dice up, and when evasion wears off put a 2 or 3-point recuperate up (you shouldnt have needed it much during evasion). Eviscerate when possible (probably will only happen once).\n\nThere's not much you can do about his cyclone,  but the damage is minimal so just bear through it.\n\nUsed lifebloom and one potion outside of rogue skills.",
            date = "2010-11-27T16:56:26-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28643#comments:id=1191012",
        },
        {
            id = 2566081,
            score = 6,
            author = "1596626",
            text = "With autoleveling, looks like I'll have to skip this one. :(",
            date = "2018-05-05T16:57:45-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28643#comments:id=2566081",
        },
        {
            id = 2796142,
            score = 5,
            author = "1933989",
            text = "Not really worth doing.",
            date = "2018-11-06T11:49:17-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28643#comments:id=2796142",
        },
    },
    [28644] = {
        {
            id = 1191020,
            score = 5,
            author = "116738",
            text = "Soloed as a 27 Combat Rogue completely in questing gear. See my post on the Zephyrus leg of this chain for spell rotation.\n\nHowever, make sure to avoid the spell \"Split Earth\". Don't interrupt it; you can simply dodge it by running around him after he casts it (takes 2 seconds for the spell to erupt). Kicking the spell not only wastes energy, but makes him spend more time attacking and less time casting useless spells ;)\n\nAgain, lifebloom and healing potion used.",
            date = "2010-11-27T16:59:45-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28644#comments:id=1191020",
        },
        {
            id = 1250875,
            score = 4,
            author = "693459",
            text = "Soloed as a 27 mage.\n\nWhen he casts spikes, freeze him with your Nova and blink away. You can kite him back and forth on the pathway without any trouble. Unless you have a decent amount of mana, you WILL need Evocation.",
            date = "2010-12-21T19:01:53-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28644#comments:id=1250875",
        },
        {
            id = 1188034,
            score = 1,
            author = "710231",
            text = "This quest is the second part of a 'Ring of Blood' style quest chain in Hillsbrad Foothills, the new level 20-28 zone. In order to do this quest, it is worth considering getting some help for this, as it is a chain. Each boss in the chain is a level 25 elite with around 5,000 health. Not easily soloable.",
            date = "2010-11-26T15:20:17-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28644#comments:id=1188034",
        },
        {
            id = 1204998,
            score = 1,
            author = "207563",
            text = "Successfully cheetah kited them all as a 26 hunter (quest greens & blues, no heirlooms)... it went rather well.\n\nThis one was the easiest of the bunch, as he stopped to cast quite often, meaning I could always be at range shooting horrible, pointy arrows into his head.\n\nStarted with Serpent Sting + Explosive Shot + Concussive Shot, and dragged him towards where the D-1000 is held. I ran around the outside edge, stopping every now and again to pelt him with arrows and refresh my SS & CS.",
            date = "2010-12-03T21:17:32-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28644#comments:id=1204998",
        },
        {
            id = 2362133,
            score = 1,
            author = "Mimiworkslave",
            text = "struggling as a L30 rogue.  not much in the way of spells, not a part of any groups :( frustrated",
            date = "2016-08-06T05:51:13-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28644#comments:id=2362133",
        },
    },
    [28645] = {
        {
            id = 1188036,
            score = 22,
            author = "710231",
            text = "This quest is the third in a 'Ring of Blood' style quest chain in Hillsbrad Foothills, the new level 20-28 zone. In order to do this quest, it is worth considering getting some help for this, as it is a chain. Each boss in the chain is a level 25 elite with around 5,000 health. Not easily soloable.",
            date = "2010-11-26T15:20:49-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28645#comments:id=1188036",
        },
        {
            id = 1538819,
            score = 8,
            author = "132990",
            text = "Quite easy to solo as Shadow Priest, i started nuking him on top of the wall, it took him quite some time to get to the wall due to Mind Flay, had him at about 50% and just jumped down when he got to me and kept on nuking. Simple enough for any caster with a slowing ability.",
            date = "2011-10-09T10:00:55-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28645#comments:id=1538819",
        },
        {
            id = 1450175,
            score = 5,
            author = "Savalina",
            text = "Playing as a combat rogue -- this is another high movemnt fight (as I'm finding they all have been thus far) .... if you don't keep moving around you'll simple be dead if you are soloing at or near level.\n\nAs rogue I'm opening with cheap shot I do eviscerate often and I'm constantly hitting recuperate (and generally I never stop moving)....\n\nThis seems to work although I'm cutting it close to dying (within 200 hp) but haven't had to use a pot either so I guess its not that bad.",
            date = "2011-06-25T08:34:16-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28645#comments:id=1450175",
        },
        {
            id = 3204914,
            score = 3,
            author = "KrS14",
            text = "Good luck as a Shaman.\n\nHe melee'd me for 250 non crit, I had heirlooms and only 2.1k HP\n\nAbandoned quest and moved on, ridiculous.",
            date = "2020-05-07T15:23:27-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28645#comments:id=3204914",
        },
        {
            id = 1204995,
            score = 2,
            author = "207563",
            text = "Successfully cheetah kited them all as a 26 hunter (quest greens & blues, no heirlooms)... it went rather well.\n\nUnloaded on him from above with Serpent Sting + Explosive Shot + Concussive Shot, and he went slowly towards the fallen tree to get up to me. When he got within range, he popped me with a water spout that knocked me up & dazed me (<3 cheetah), so I jumped down and continued to let him have it. Then it was just a matter of keeping the SS & CS on him and kite him around the buildings until he died.",
            date = "2010-12-03T21:15:46-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28645#comments:id=1204995",
        },
    },
    [28646] = {
        {
            id = 1186224,
            score = 7,
            author = "Kaaosa",
            text = "This guy can disorient, which makes him an annoyance for hunters/warlocks attempting to solo this quest chain, as he'll switch to you while your pet is disoriented.",
            date = "2010-11-25T23:17:30-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28646#comments:id=1186224",
        },
        {
            id = 1214289,
            score = 6,
            author = "524268",
            text = "Can be soloed as a 31 Arcane Mage (full heirlooms).  After failing more than half-a-dozen times and plenty of \"Evade(s)\", I finally found a doable kite path.  You can kite him by standing on the railing of the overhanging bridge, causing him to loop back up the opposite ramp.  Before he gets close enough for a conflag shot, hop down in the pit and strafe back towards the spawn point (while keeping in range for instant procs).  Once he closes in down the ramp you'll prob get hit with a conflag.  Once the disorient wears off, Frost Nova to root him in place and use Improved Blink to dash towards the ramp and back up towards the beginning bridge. If the timing doesn't go your way, just reset the mob, eat/drink, try again.\n\n1) Keep up a slowing effect from Frost Bolt.\n2) Use instant procs.\n3) Use good timing of Frost Nova and Blink to keep distance and out of LoS for his conflag\n\nBy far the hardest of the gauntlet.  Save yourself some trouble and grab another comrade.\n\nHope this helps :-)",
            date = "2010-12-08T08:01:44-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28646#comments:id=1214289",
        },
        {
            id = 1386559,
            score = 4,
            author = "813471",
            text = "The whole chain can be soloed at 25 as a Disc priest. This guy was the toughest to cast against but if you keep up shield and renew/flash heal when you need to he goes down fine. The last one may or may not get ya. I only had 400 health left and had to Torrent to get enough mana for one last killing shot.\n\nI only have the Cape and main hand hammer BoA. Everything else is pretty normal for a couple dungeon runs or some crafting.",
            date = "2011-04-07T22:14:19-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28646#comments:id=1386559",
        },
        {
            id = 1238782,
            score = 3,
            author = "anhsieh",
            text = "Soloed as 29 Ret Paladin in quest greens, though without kiting (never been too great at that) and with about six or seven deaths. Mainly just had to keep all my cooldowns up-- needed that Lay of Hands-- and use Hand of Protection liberally. Liberally, meaning not what I did the first five or six times, and wait for an \"opportune\" time to do it. Infernus, regrettably enough, knows just when those opportune times are, and I pretty much always got Conflagration'd right when I hit the HoP button.",
            date = "2010-12-16T16:31:24-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28646#comments:id=1238782",
        },
        {
            id = 1247409,
            score = 3,
            author = "ddbinha",
            text = "Soloed the whole chain as a frost mage lvl 29 (30 at the last boss) with heirlooms. This one was the easiest one, since he didn't attack me during it which gave me time to gain back health, just remember to stay away from your pet so he doesn't get hit with the AoE from conflagration. I had to use my frost nova and my pet's at every cooldown, lifebloom and health potions and kited them in circles. I only managed to down the last boss thanks to ice block and finished that fight with  50 health.",
            date = "2010-12-20T07:32:21-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28646#comments:id=1247409",
        },
    },
    [28647] = {
        {
            id = 1183559,
            score = 20,
            author = "537090",
            text = "It is clearly a reference to Terminator and to be more precise to T2, take note of rings flavor text, is almost what terminator says to John about T-1000, the axe is called of Judgment day as per the title of Terminator 2. The 3rd item is a pun from what i can think to the producers of 3rd and 4th installments of the franchise which kinda failed in what 1st and 2nd movies set as a standard.",
