    [28671] = {
        {
            id = 1281289,
            score = 5,
            author = "726332",
            text = "Don't bother taking the Blasted Lands portal from a major city, it doesn't work for characters below level 58.\n\nWalk there from Swamp of Sorrows.\n\nSavor the last taste of a revamped Cataclysm zone before the 58-68 grind in Nowhereland and the 68-80 trawl through Icerend. I hope your Exp% BOA gear is ready.",
            date = "2011-01-06T21:02:01-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28671#comments:id=1281289",
        },
        {
            id = 1709467,
            score = 2,
            author = "QuickBASIC",
