    [28673] = {
        {
            id = 1696216,
            score = 7,
            author = "Adamsm",
            text = "Strangely, unlike most other flight points which appear at intervals of 5's, this one pops up for you at level 54.",
            date = "2012-08-05T02:15:30-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28673#comments:id=1696216",
        },
        {
            id = 2878175,
            score = 6,
            author = "Mortimerty",
            text = "As of Patch 8.1 you can complete two of three breadcrumb quests which lead you to Blasted Lands.\n\nYou have to keep the order to be able to do both of them.\n\n1.   https://www.wowhead.com/quest=28673 (this quest can be found on every Hero's Call Board) OR  https://www.wowhead.com/quest=28857 (both have same reward, mutually exclusive, but both are marked as completed if one of them is completed)\n\n2.   https://www.wowhead.com/quest=28867",
            date = "2019-03-22T10:32:31-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28673#comments:id=2878175",
        },
        {
            id = 3216088,
            score = 6,
            author = "Foxkitty",
            text = "I do not believe this quest can be completed anymore.  I am there now, and Netherguard Keep has no Alliance characters.  Quartermaster Lungertz is nowhere to be found. Please correct me if I am wrong.",
            date = "2020-07-05T19:11:57-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28673#comments:id=3216088",
        },
        {
            id = 1673438,
            score = 2,
            author = "994699",
            text = "Just to clarify for any new players out there who are wondering where Nethergarde Keep is  :) Just take a griffon from your major city to the BLASTED LANDS (nethergarde is the name of the post).\n\nHappy Adventuring! :)",
            date = "2012-06-04T13:53:45-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28673#comments:id=1673438",
        },
        {
            id = 2071800,
            score = 1,
            author = "Fluffmeister",
            text = "You can get there by going to the river (I had to jump down a few mountain edges and lost a bit of health) and swimming to Shattershore - couple of level 56 mobs to fight en route, but it gets you to Nethergarde Keep.",
            date = "2014-12-18T13:25:22-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28673#comments:id=2071800",
        },
    },
