    [28675] = {
        {
            id = 1913035,
            score = 12,
            author = "Sowsix",
            text = "When you have this quest fly to the Burning Steppes to Morgan's Vigil and go talk to https://www.wowhead.com/npc=48948\n\nShe will lend you her rocket which will take you directly to Bogpaddle in Swamp of Sorrows",
            date = "2013-10-29T07:50:28-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28675#comments:id=1913035",
        },
        {
            id = 1433431,
            score = 4,
            author = "616859",
            text = "Despite the advice given in the text of the quest description,  I think it is easier and quicker to get to Swamp of Sorrows by flying to Darkshire and traveling Northeast through Deadwind Pass",
            date = "2011-06-03T13:23:17-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28675#comments:id=1433431",
        },
        {
            id = 1245937,
            score = 2,
            author = "721541",
            text = "I got this quest from Stormwind City (without completing Step 1 as listed here), but was unable to share it with my levelling buddy.\n\nWe were the same level and had completed all the same quests, and we weren't able to figure it out. Not having this quest, however, didn't mean he missed out on any of the quests - we got and completed all the same ones in the Swamp of Sorrows.",
            date = "2010-12-19T15:33:37-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28675#comments:id=1245937",
        },
        {
            id = 1312567,
            score = 2,
            author = "388917",
            text = "The series means (and confirmed) you cannot get this quest if you have The Bogpaddle Bullet quest in your quest book.",
            date = "2011-01-27T22:48:31-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28675#comments:id=1312567",
        },
        {
            id = 1834968,
            score = 1,
            author = "1109107",
            text = "I followed the path through Darkshire and it was perfect. Only ran into two unfriendly things once I was in the Swamp.",
            date = "2013-03-26T22:36:52-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28675#comments:id=1834968",
        },
    },
