    [28701] = {
        {
            id = 2076158,
            score = 94,
            author = "Stompa",
            text = "OK, I got so lost in this cave, trying to find the quest turn-in because the yellow    ?    looks like it is in there somewhere.  A reminder: the turn in for this is back OUTSIDE the cave, at Starfall Village.",
            date = "2014-12-25T13:50:28-06:00",
