        {
            id = 2089982,
            score = 19,
            author = "Takata",
            text = "For anyone having trouble, yes the quest turn in is back to the Night Elf NPC at starfall village, Wynd Nightchaser.",
            date = "2015-01-17T08:55:22-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28701#comments:id=2089982",
        },
        {
            id = 1290100,
            score = 6,
            author = "SkrunchBoy",
            text = "The entrance to Ban'Thallow Barrow Den is behind Starfall Village, up a path to the right. (Map (http://www.wowhead.com/maps?data=618:471400)). Its layout is the same as the cave you enter in Teldrassil, to slay Oben Rageclaw. You will find Rinno Curtainfire inside for a couple of quests. The relics are scattered through the cave.\n\nEnjoy!",
            date = "2011-01-12T03:53:13-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28701#comments:id=1290100",
        },
        {
            id = 1278976,
