        },
    },
    [28702] = {
        {
            id = 1282828,
            score = 12,
            author = "368332",
            text = "For anyone that is having issues getting across to the cape, there is a very skinny ledge to the left you need to cross. i had a hard time finding it.",
            date = "2011-01-07T18:26:17-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28702#comments:id=1282828",
        },
        {
            id = 3229341,
            score = 3,
            author = "Kyrpis20",
            text = "Run down to Fort Livingston and talk to Wulfred Harris, he'll give you the quest \"To the Cape!\".\n\nThen talk to the flightmaster and you can fly down there",
            date = "2020-09-11T17:42:16-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28702#comments:id=3229341",
        },
    },
    [28703] = {
        {
            id = 1953737,
            score = 6,
            author = "BoSoxFan08",
            text = "The entirety of the quest is completed in Ban'Thallow Barrow at 47,40.  The Coldlurk Creeper (http://wowhead.com/?npc=49346) are everywhere.  The Coldlurk Burrower (http://wowhead.com/?npc=49347) are further down the barrow beneath the quest giver (there are a couple \"halls\" to go down, about 2 of them per hall).  Found a place at 47,41 (within the cave where there are ample Burrowers).  Also make sure you have the Out of Harm's Way (http://www.wowhead.com/quest=28701) where you get the Starfall Relic (http://wowhead.com/?item=64675)s\n\nHope this helps! This is my first quest guide.",
            date = "2014-03-25T20:09:35-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28703#comments:id=1953737",
        },
        {
            id = 2550828,
            score = 5,
            author = "Wyler",
            text = "Spawn rate for this cave doesn't properly respond to increased traffic...\n\nThere were 3-4 of us running around looking for creepers for WAY too long.",
            date = "2018-02-05T11:37:37-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28703#comments:id=2550828",
        },
        {
            id = 2006028,
            score = 1,
            author = "Sounder",
            text = "Rinno is directly below the spiral entrance, on the west side of the Barrow.",
            date = "2014-09-26T08:06:57-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28703#comments:id=2006028",
        },
    },
