    [28710] = {
        {
            id = 1199096,
            score = 30,
            author = "714789",
            text = "You're looking for a particular arch bridge which leads into an alcove with a worm, this alcove has two feature rocks with an urn in between.  This particular alcove has an opening to the left which will lead you to the balcony where Sana Curtainfire stands.  I'm sure the Barrow Den layout has not changed in a long while, however this quest appears new to cata.",
            date = "2010-12-01T00:32:50-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28710#comments:id=1199096",
        },
        {
            id = 1873019,
            score = 15,
            author = "1130594",
            text = "Yes! Once you see her on the balcony: face her, go on the bridge to your right. In that alcove, make a left and you'll find her. Took me forever.",
            date = "2013-07-02T18:24:41-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28710#comments:id=1873019",
        },
        {
            id = 1637594,
