    [28713] = {
        {
            id = 5667341,
            score = 43,
            author = "Yetiuprising",
            text = "While searching the map for dragonriding races in Kalimdor, it shows this quest is available to me as horde...",
            date = "2023-08-15T22:56:42-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28713#comments:id=5667341",
        },
        {
            id = 1198620,
            score = 24,
            author = "75955",
            text = "After handing in \"The Balance of Nature\", DO NOT GO GRAB \"Demonic Thieves (http://www.wowhead.com/quest=28715)\" wait until after you do \"Fel Moss Corruption (http://www.wowhead.com/quest=28714)\" or you will miss the breadcrumb quest \"A Favor for Melithar (http://www.wowhead.com/quest=28734)\"!",
            date = "2010-11-30T19:06:20-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28713#comments:id=1198620",
        },
        {
            id = 5485251,
            score = 12,
            author = "Sunreaver",
            text = "When doing the quests at the Temporal Conflux in Thaldraszus, one of them sends you back to your original starting area. If you're a Night Elf, you end up back in front of this questgiver. Accepting the quest will prompt the Timekeeper questgiver to show up and take you back, but afterwards you still have this quest in your log... even if you completed it waaaay back in classic.\n\nLong story short, if that happens, just abandon the quest.",
            date = "2022-12-02T14:16:17-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28713#comments:id=5485251",
        },
        {
            id = 1647594,
            score = 9,
            author = "945282",
            text = "Those  inserts can be pretty funny:\n\"My purpose in Shadowglen is to train young Death Knights like you and to ensure that the balance of nature is maintained.\"",
            date = "2012-04-01T17:36:14-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28713#comments:id=1647594",
        },
        {
            id = 5508751,
            score = 5,
            author = "soukougnan",
            text = "Oh, the memories...starting out as a young NELF priest in 2007.\n\"Journey forth, young priest, and thin saber populations so that nature's harmony will be preserved.\"\nIf he would have known what he started.\nStill same priest, still thinning populations....not so many sabers nowadays.\nNow, I guess he, like many others perished in the destruction of Teldrassil.\n\nI managed to get the quest, again(!), while trying to get Chromie back to the current time in Dragonflight. Version 10.",
            date = "2022-12-20T13:04:22-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28713#comments:id=5508751",
        },
    },
    [28714] = {
        {
