    [28716] = {
        {
            id = 3238387,
            score = 75,
            author = "GeneralRhinox",
            text = "So we are in 9.0.1 now on the live version. I am taking my Mechagnome through Cataclysm areas, and the first quest for Twilight Highlands is Hero's Call: Twilight Highlands. However, when you go to the throne room to talk with him, he's been replaced with High Exarch Turalyon and there is nobody in the throne room to continue the quest line, you're stuck there. Has anyone found a way to work around this?",
            date = "2020-10-14T19:30:49-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28716#comments:id=3238387",
        },
        {
            id = 2526735,
            score = 27,
            author = "MoarHeroisms",
            text = "Due to changes made to Stormwind heralding Legion, the original questline has been removed. Now you simply talk to Fargo for a plane ride. No more detective work with young Anduin (http://www.wowhead.com/quest=27064), exploring the ruined park district (http://www.wowhead.com/quest=27072), rescuing Jack Bauden (http://www.wowhead.com/npc=50049) on the longest day of his life, facing off against The Black Bishop (http://www.wowhead.com/npc=44816), defusing a bomb beneath the cathedral (http://www.wowhead.com/quest=27092), and exposing a Twilight cultist (http://www.wowhead.com/quest=27106) in the throne room Onyxia-style. The Horde version (http://www.wowhead.com/quest=26830) remains albeit with a few revisions.",
            date = "2017-09-28T20:31:10-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28716#comments:id=2526735",
        },
