    [28729] = {
        {
            id = 1202746,
            score = 15,
            author = "Polegara",
            text = "The moonwell is at (59, 28).\n\nAs you approach it, Shade of the Kaldorei (http://www.wowhead.com/npc=34574) will spawn, and deliver the first of several lectures on recent night elf history.\n\nShade of the Kaldorei fades into existence as you approach, nodding a subtle greeting.\nShade of the Kaldorei says: Much has changed for our people since the Battle of Mount Hyjal.\nShade of the Kaldorei says: Nordrassil lies a pale shadow of what it once was, its power used to defeat Archimonde and drive back the Burning Legion.\nShade of the Kaldorei says: Our immortality - the very essence of our beings! - was lost.\nShade of the Kaldorei says: The Betrayer was freed from his prison, and Shand'do Stormrage disappeared into the emerald dream.\nShade of the Kaldorei says: A dark time for all.\nThe Shade of the Kaldorei closes its eyes and fades away.",
            date = "2010-12-02T18:35:20-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28729#comments:id=1202746",
        },
        {
            id = 1189140,
            score = 8,
            author = "146819",
            text = "Thank God, we no longer have to run all the way up the ^&*!ing tree twenty times now!",
            date = "2010-11-26T23:50:20-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28729#comments:id=1189140",
