    [28731] = {
        {
            id = 2012290,
            score = 156,
            author = "liquidraver",
            text = "If you somehow get this quest years after you left Teldrassil, as I do, and can't find https://www.wowhead.com/npc=3515 at Dolanaar, just go to the crossroads front of Darnassus, he will be there (41,45)\n\nmaybe it's something about the cataclysm, that changed the quests, and you can re-do old ones with a little modification in it.",
            date = "2014-10-13T06:36:42-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28731#comments:id=2012290",
        },
        {
            id = 1505586,
            score = 20,
            author = "Kabookiejoe",
            text = "jumping off the top of the tree with winds embrace will grant you  \"going down\" achievement",
            date = "2011-08-28T19:41:51-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28731#comments:id=1505586",
        },
        {
            id = 1202820,
            score = 15,
            author = "Polegara",
            text = "When you hand in this quest to Corithras, the Shade of the Kaldorei (http://www.wowhead.com/npc=34586) will spawn and continue the story.\n\nShade of the Kaldorei smiles at you knowingly as it approaches.\nShade of the Kaldorei says: With Malfurion Stormrage gone, the druids were left in disarray and in desperate need of a new leader.\nShade of the Kaldorei says: Arch Druid Fandral Staghelm roused the druids and convinced the Circle of Ancients in Darkshore that it was time for our people to rebuild.\nShade of the Kaldorei says: In an effort to regain immortality for our people, and with the approval of the Circle, Staghelm and the most powerful druids grew Teldrassil, upon whose boughs you now stand.\nShade of the Kaldorei says: Though we have our new home, our immortal lives have not been restored.\nThe Shade of the Kaldorei closes its eyes and fades away.\n\nThere are five of these lore quests in total.\n\nTeldrassil: Crown of Azeroth (http://www.wowhead.com/quest=28729)\nTeldrassil: Passing Awareness\nTeldrassil: The Refusal of the Aspects (http://www.wowhead.com/quest=929)\nTeldrassil: The Burden of the Kaldorei (http://www.wowhead.com/quest=7383)\nTeldrassil: The Coming Dawn (http://www.wowhead.com/quest=933)",
            date = "2010-12-02T19:20:57-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28731#comments:id=1202820",
        },
        {
            id = 1189158,
            score = 13,
            author = "146819",
            text = "It seems Blizzard has finally realized how many people end up dying trying to take the shortcut down from Tenaron; he now casts the Wind's Embrace (http://www.wowhead.com/spell=65453) buff on you once you accept this quest.",
            date = "2010-11-27T00:01:06-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28731#comments:id=1189158",
        },
        {
            id = 2512482,
            score = 2,
            author = "Dissectional",
            text = "Wowhead has incorrect data for this chain.\nThe chain now starts at Priestess of the Moon (http://www.wowhead.com/quest=28723/priestess-of-the-moon) and is available to all Alliance races.\n\nWowhead currently lists two quests at the beginning of the chain which have been removed from the game:\nHallowed Sigil (http://www.wowhead.com/quest=3119/hallowed-sigil)\nLearning the Word (http://www.wowhead.com/quest=26949/learning-the-word)",
            date = "2017-08-07T03:08:05-05:00",
