            text = "Great NES/Arcade reference.",
            date = "2010-12-23T15:58:07-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28837#comments:id=1255100",
        },
        {
            id = 1188238,
            score = 10,
            author = "Ainasni",
            text = "Critter-sized animals in different forms, hopping around in the area of the questgiver.",
            date = "2010-11-26T16:42:01-06:00",
