        },
    },
    [28838] = {
        {
            id = 1388601,
            score = 16,
            author = "Engrelled",
            text = "On your way down to get the dreamcatcher, you will see an orc lying just off to the left of the road. He is surrounded by feathers and has a quest for you to kill owlbeasts. DO NOT do this before you get the dreamcatcher. When you pick up the dreamcatcher, you get a quest completion box and the next quest is to get three essences - for which you have to kill the SAME owlbeasts.",
            date = "2011-04-10T18:43:30-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28838#comments:id=1388601",
        },
        {
