    [28839] = {
        {
            id = 1182404,
            score = 184,
            author = "181947",
            text = "Go up the hill. There are 4 caves.\n\nFirst totem is in the cave to your left.\nSecond totem is in the cave straight ahead.\n\nTo your right , will be a slope upwards. There is a 5th cave at the top of the slope with the 3rd totem.",
            date = "2010-11-24T17:15:34-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28839#comments:id=1182404",
        },
        {
            id = 2584789,
            score = 127,
            author = "Tomcatbear",
            text = "The minimap highlights the wrong location for the Moon Totem, ignore your minimap and go to: /way 64.8 81",
            date = "2018-07-26T02:07:16-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28839#comments:id=2584789",
        },
        {
