    [28840] = {
        {
            id = 1867846,
            score = 16,
            author = "briyan",
            text = "To reach this quest, you'll need to do some prerequisites starting with The Ruins of Kel'Theril (http://www.wowhead.com/quest=28479)",
            date = "2013-06-18T01:19:36-05:00",
