        },
        {
            id = 1438252,
            score = 3,
            author = "686655",
            text = "I would recommend setting your hearthstone to everlook with this quest, the walk in and out of the Gorge is a long one.  Also, Frostilicus drops 2 each time and has a decent respawn time.  4 kills on him and your done.",
            date = "2011-06-10T03:18:41-05:00",
