    [28858] = {
        {
            id = 2016217,
            score = 7,
            author = "PerryCS",
            text = "EDIT:  You can UNPhase the place and turn in the quest.  In 6.0.2, Zidormi (NPC) will allow you to switch between phased/low-level and Warlords/level-90+ versions of the Blasted Lands. Very useful when trying to find the Blasted Lands Candy Buckets!  Her location is at 48.2, 7.2\n\n(Old post) If you have started patch 6.02 and the area is now phased you can't turn it in anymore unless eventually it's unphased.  You can see the ? but you can not see the quest giver.  Maybe once this is unphased (if it ever does) you can turn this in.  Till then... I could not find the NPC in Blasted Lands around where the ? was.\n\nHope this helps someone :)\n\n[npc=88206 domain=www]",
            date = "2014-10-20T01:36:53-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28858#comments:id=2016217",
        },
        {
            id = 1184093,
            score = 4,
            author = "124958",
            text = "Since you obtain this in Winterspring you maybe wondering if this gives credit towards the Winterspring Quests achievement - However it does not.\n\nStill lacking one quest for completion of that achievement, but i haven't yet found it.",
            date = "2010-11-25T07:12:47-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28858#comments:id=1184093",
        },
        {
