    [28865] = {
        {
            id = 1248273,
            score = 15,
            author = "730118",
            text = "I believe this quest should be synonymous with all (http://www.wowhead.com/quest=28858) of (http://www.wowhead.com/quest=28553) these (http://www.wowhead.com/quest=28671)..",
            date = "2010-12-20T15:25:59-06:00",
            sourceUrl = "https://www.wowhead.com/quest=28865#comments:id=1248273",
