        },
        {
            id = 3208919,
            score = 10,
            author = "Ehall671",
            text = "Breadcrumb steps:\n\n1) Complete all Swamp of Sorrows Quests.\n2) Complete all Silithus Quests.\n3) Turn in https://www.wowhead.com/quest=28671 to Okrilla in Deadmaul Hold in Blasted Lands. Do not pick up any other quests.\n4) Travel to Silithus and pick up https://www.wowhead.com/quest=28865. Take the portal from the mage and turn in to Okrilla at Deadmaul Hold.\n5) Travel to Stonard in Swamp of Sorrows and pick up https://www.wowhead.com/quest=28553.",
            date = "2020-05-26T16:17:51-05:00",
            sourceUrl = "https://www.wowhead.com/quest=28865#comments:id=3208919",
        },
        {
            id = 2086857,
            score = 6,
            author = "Malachi68",
            text = "I can't find Okrilla...\n\nWhen I arrived at Dreadmaul Hold, the place is crawing with Iron Horde guys and Orkilla is nowhere to be seen.\n\nMaybe this is a dead quest now?",
            date = "2015-01-11T15:47:09-06:00",
