    [28876] = {
        {
            id = 1644144,
            score = 6,
            author = "968976",
            text = "This quest has indeed been removed from the game. It has been replaced with https://www.wowhead.com/quest=13866 out of Azshara if you want Zone to Zone, or https://www.wowhead.com/quest=28493 if you're into using the board.",
            date = "2012-03-24T19:19:11-05:00",
