    [29083] = {
        {
            id = 3229593,
            score = -1,
            author = "TheWoWExp",
            text = "As of 8.3\n_____________________________________________________________________\n¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\nhttps://youtu.be/y2Norpj-EzI\n_____________________________________________________________________\n¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n\nStarts: https://www.wowhead.com/npc=823 (35.73,40.27)\nEnds: https://www.wowhead.com/npc=197 (33.39,53.32)\n\nThe quest is a simple one--you just have to walk from Willem to McBride in order to turn in the quest. But it won't hurt to kill a few enemies along the way, right?\n_____________________________________________________________________\n¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\nHappy questing,\nTGEXP (https://tgexp.com/the-rear-is-clear/)",
