            author = "spyropurple",
            text = "Real nice of the quest to not make you immune to damage from any wandering hostile mobs that are in the way. They don't drop aggro while you're riding and will kill you before you even make it to your destination (unless you hop off).",
            date = "2021-03-10T04:27:26-06:00",
