    [29111] = {
        {
            id = 1416578,
            score = 9,
            author = "63052",
            text = "As of today, May 12th, a hotfix has been deployed allowing everybody to turn in the \"Mor'shan Caravan Delivery\" quest at Kadrak. Whoever has not been able to do so so far should be looking for him at the Mor'shan Ramparts in Northern Barrens (Source (http://blue.mmo-champion.com/topic/171803/))",
            date = "2011-05-12T05:48:36-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29111#comments:id=1416578",
        },
        {
            id = 1603167,
            score = 6,
            author = "323697",
            text = "All of the quests listed above are definitely not prerequisites for this quest.\n\nI always do https://www.wowhead.com/quest=875 and https://www.wowhead.com/quest=876 with alts for the ring.  Since I always do them, I'm not certain if they're required for https://www.wowhead.com/quest=29095 or if it is always available at level 14 whether those two have been completed or not. (https://www.wowhead.com/quest=867 is completely optional.)\n\nSo the prerequisite quests begin either with https://www.wowhead.com/quest=875 or https://www.wowhead.com/quest=29095.  Fortunately they're from the same quest giver, so if you hadn't done the harpy quests earlier and they turn out to be necessary for https://www.wowhead.com/quest=29095 it won't be much of an inconvenience to do them.",
            date = "2011-12-28T13:07:51-06:00",
            sourceUrl = "https://www.wowhead.com/quest=29111#comments:id=1603167",
        },
        {
            id = 3164610,
            score = 6,
            author = "Nannaki",
            text = "These 'protect the kodo' quests are trivialized by using Tab to alternate or select targets as they spawn.  You can kill them pretty much right as they enter by spamming Tab, 1, Tab, 1, etc.\nFor some reason the second escort quest doesn't mark the mobs as selectable or readily hostile when using tab, so you have to physically click on them.  but that one's easy anyway.\nthe final escort quest i usually finish with over 90%hp, by spamming Tab, 1 2 3, Tab, 1 2 3 etc, quickly.  this way you don't have to pay attention to what weapon to use, whether they're flying or grounded, or on the kodo attacking you.",
            date = "2019-10-16T11:15:47-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29111#comments:id=3164610",
        },
        {
            id = 1459682,
            score = 5,
            author = "wisket",
            text = "just fyi...you have to complete all quests at nozzlepot's outpost INCLUDING miner's fortune to be able to get the short way home.",
            date = "2011-07-03T21:17:49-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29111#comments:id=1459682",
        },
        {
            id = 1565898,
            score = 5,
            author = "Bullfrogg",
            text = "If the quest is working, you'll be chased down by Burning Blade members on both wolves and wind riders. You get a special rocket to shoot down the wind riders. The wolf riders can be shot with your gun or punched off your kodo just like you did before.\n\nIt's a pretty awesome quest, provided it's working properly.",
            date = "2011-11-07T19:06:04-06:00",
            sourceUrl = "https://www.wowhead.com/quest=29111#comments:id=1565898",
        },
    },
    [29112] = {
