        {
            id = 2338072,
            score = 4,
            author = "Puliver",
            text = "In order to get to this quest, you need to do Mor'shan Caravan quests first.\n\nMor'shan Caravan Pick-Up (http://www.wowhead.com/quest=29109/morshan-caravan-pick-up)\nMor'shan Caravan Rescue (http://www.wowhead.com/quest=29110/morshan-caravan-rescue)\nDemon Seed (http://www.wowhead.com/quest=29112/demon-seed)\nMor'shan Caravan Delivery (http://www.wowhead.com/quest=29111/morshan-caravan-delivery)",
            date = "2016-06-07T16:09:19-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29112#comments:id=2338072",
        },
        {
            id = 5607709,
            score = 1,
            author = "dorkshore",
            text = "If you completed Durotar quests up to being sent to talk to  Ak'Zeloth (https://www.wowhead.com/quest=25264/akzeloth), you may have been confused when that chain ran dry.\n\nThis is the reworked version of the culmination of that chain, where you deal a significant blow to the Burning Blade in Northern Barrens.\n\nNot sure why they didn't find a smoother way of connecting the Burning Blade in Durotar to the Burning Blade in the Barrens, but there you go.",
            date = "2023-05-12T19:04:27-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29112#comments:id=5607709",
        },
