            date = "2012-10-13T05:58:51-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29420#comments:id=1740201",
        },
        {
            id = 1656291,
            score = 3,
            author = "selvin",
            text = "Am I the only one who was happy to see a new design for a cave? This looked so awesome when I stepped in for the first time.",
            date = "2012-04-19T22:28:45-05:00",
