    [29421] = {
        {
            id = 1808970,
            score = 50,
            author = "Tripax",
            text = "\"Lets make a quest where people have to spam Lightning Bolt or whatever single ability they have for five minutes\"",
            date = "2013-02-04T07:01:47-06:00",
            sourceUrl = "https://www.wowhead.com/quest=29421#comments:id=1808970",
        },
        {
            id = 1733860,
            score = 22,
            author = "1036949",
            text = "Master Fei has about 12,000 hit points, but you're granted absurd regeneration for the duration of combat -- so much so that you can win by turning Auto Attack on and walking away from the keyboard for fifteen minutes. (I just did.)",
            date = "2012-10-06T21:58:57-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29421#comments:id=1733860",
        },
        {
            id = 1873264,
            score = 8,
            author = "783503",
            text = "If you are lazy, just stand with your back against the wall and keep pushing 1 and 2. He won't be able to teleport behind you and so you won't have to turn around.",
            date = "2013-07-03T14:07:43-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29421#comments:id=1873264",
        },
        {
            id = 1901973,
            score = 4,
            author = "945326",
            text = "You will be given the \"blessings\" of the three flames you just lit with your torch.  They will heal you as fast as Master Li Fei inflicts damage.\n\nSo all you need to do is spam one ability at him for ages.   The only other thing you may need to do is turn around occasionally when he ports behind you but, if you stand with your back against a wall, he won't even be able to do that.",
            date = "2013-09-23T15:24:03-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29421#comments:id=1901973",
        },
        {
            id = 1657442,
            score = -8,
            author = "Krastopic",
            text = "The only thing hard about this quest is that Master Li Fei is partially faded and hard to see.\n\nCast a frost nova or set a trap, snare whatever to freeze him for an easier kill.  Eventually he will get behind you and this makes it easier for the kill.\n\nI had hoped that the quests by this point would become a little harder.",
            date = "2012-04-22T16:11:08-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29421#comments:id=1657442",
        },
    },
    [29422] = {
        {
            id = 1726341,
            score = 5,
            author = "243923",
            text = "Glare? Warming up to you?  Har har, Blizzard, you're so punny.\n\nIn more important information, the brazier Huo is floating above is NOT an actual brazier-- that is, it does not do any burn damage from standing near/on it.  So don't be afraid to get close and use your quest item!",
            date = "2012-09-30T16:57:07-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29422#comments:id=1726341",
        },
        {
            id = 1657445,
            score = 2,
            author = "Krastopic",
            text = "Yet another Noob quest.\nThere was a firewall you could not pass at the top of the stairs behind Master Li Fei.  That wall is now gone and you can pass.  (Remember from \"Only the Worthy Shall Pass\").\n\nYou now have a pack in your bags.  Go to the ghostly looking Huo, the Ancient Spirit of Fire and use the pack in your bag to light the fire pit below him.  After a few seconds of audio effects and you waving your hands - he will appear and accept your completed quest and assign you a new one.\n\nMay the Panda be with you!",
            date = "2012-04-22T16:16:16-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29422#comments:id=1657445",
        },
    },
    [29423] = {
        {
            id = 1657448,
            score = 7,
            author = "Krastopic",
            text = "Wait for a moment until Huo changes and reforms.  As you start to exit he will appear behind you.  Exit the cave and go Southeast and across the bridge.  You will see a brick structure near where you battled the air elemental earlier.  You will eventually find a long stone stair called the Dawning Stair (worth 10 XP for discovery) and you will take it to the top.\n\nWhen you get to the top of the stairs, you will see an entrance and when you go through it you will get 45 xp for entering the Temple of the Five Dawns.\n\nGo up one more short set of stairs and quest complete.  Turn in with Master Shang Xi.",
            date = "2012-04-22T16:25:13-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29423#comments:id=1657448",
        },
        {
            id = 1726359,
            score = 6,
            author = "243923",
            text = "For easy reference, here is the dialogue spoken aloud at the end of the quest:\n\nMaster Shang Xi says:  Welcome, Huo.  The people have missed your warmth.\nMaster Shang Xi says:  You have conquered every challenge I put before you, .  You have found Huo and brought him safely to the temple.\nMaster Shang Xi says:  There is a much larger problem we face now, my students. Shen-zin Sun is in pain. If we do not act, the very land on which we stand could die, and all of us with it.\nMaster Shang Xi says:  We need to speak to Shen-zin Su and discover how to heal it. And to do that, we need the four elemental spirits returned.  Huo was the first.\nMaster Shang Xi says:  Ji, I'd like you to go to the Dai-Lo Farmstead in search of Wugou, the spirit of earth.\nJi Firepaw says: On it!\nMaster Shang Xi says:  Aysa, I want you to go to the Singing Pools to find Shu, the spirit of water.\nAysa Cloudsinger says: Yes master.\nMaster Shang Xi says:  And , you shall be the hand that guides us all. Speak with me for a moment before you join Aysa at the Singing Pools to the east.\n\nHe then offers the next quest in the chain: The Singing Pools (http://www.wowhead.com/quest=29521).",
            date = "2012-09-30T17:17:30-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29423#comments:id=1726359",
        },
        {
            id = 1653276,
            score = 5,
            author = "Rred26",
            text = "MOP Beta:\n\nI accepted this quest and didn't see Huo following me. I left the cave anyways and traveled south-east to the Temple. If your map is undiscovered, the temple is right smack in the middle. Follow the 'Dawning Stairs' up to the temple from the north. I reached Master Shang Xi and received quest completion.",
            date = "2012-04-13T11:52:26-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29423#comments:id=1653276",
        },
        {
            id = 1654454,
            score = 4,
            author = "Syrong",
            text = "Just wait for the Bleesing of Huo and then he will follow you. Plus you get a faster movement buff from him.",
            date = "2012-04-15T15:07:07-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29423#comments:id=1654454",
        },
        {
            id = 2133284,
            score = 4,
            author = "Neutralagent",
            text = "As long as this quest is incomplete you gain a +50% movement speed buff (http://www.wowhead.com/spell=102630/blessing-of-huo).",
            date = "2015-03-08T23:18:49-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29423#comments:id=2133284",
        },
    },
    [29424] = {
        {
            id = 1812121,
            score = 3,
