    [29521] = {
        {
            id = 1720881,
            score = 24,
            author = "Pandecio",
            text = "Too too tragic story of a panda that drowned there thousands of years ago, now whoever falls into spring turns into a panda",
            date = "2012-09-26T22:22:13-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29521#comments:id=1720881",
        },
        {
            id = 1719277,
            score = 22,
            author = "218169",
            text = "This is most likely a reference to the manga Ranma 1/2:\n\n\"The story begins when Ranma Saotome and his father Genma return home from a martial arts training expedition in China, where they fell victim to a cursed set of hot springs at a training ground named Jyusenkyo. During a training session there, one must avoid the cursed pools by balancing on bamboo poles while engaging in combat. Unfortunately, Ranma fell into the pool of a \"Young Girl.\" Hundreds of these pools exist at Jyusenkyo, and their curses exist because at some point in time within each pool an animal or human drowned. So, every time one comes in contact with cold water, he or she will turn into whatever animal or human form of the cursed pool they had been immersed in. The only way to reverse the effect is immersing oneself in hot water.\"\n\nhttp://www.clas.ufl.edu/users/murphy7312/JPT3500file/JPT.Projectfile/Jpt/Ranma.html",
            date = "2012-09-25T22:31:37-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29521#comments:id=1719277",
        },
        {
            id = 1666156,
            score = 9,
            author = "mariosa",
            text = "The text when you complete the quest reminds me of the Jusenkyo cursed ponds from Ranma ½... the premise is the same: someone (or something) drowned in a pond, and now, whenever someone falls in that pond, they transform into that. Ranma, the protagonist, turns into a woman when in contact with cold water, and into a man when the water is hot. Gender bender confusion ensues!",
            date = "2012-05-12T21:11:42-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29521#comments:id=1666156",
        },
        {
            id = 1657449,
            score = 5,
            author = "Krastopic",
            text = "Mists Beta\n\nAfter picking up the quest, proceed to your left and take the first exit from the building you come across.\n\nTwo small Pandarians will be following and spouting messages of meaningless Pandarisums.\n\nFollow the path under the arch.  Go down the hill (staying on the stone pathway).  At the end of the path, keep going a bit further and you will see a pool below you.  In the middle is an island with the quest receiver.",
            date = "2012-04-22T16:29:37-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29521#comments:id=1657449",
        },
        {
            id = 1745996,
            score = 4,
            author = "Shirubia",
            text = "By chance this place has a pool where a yeti holding an eel and crane while riding an ox drowned?",
            date = "2012-10-19T21:41:50-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29521#comments:id=1745996",
        },
    },
