    [29524] = {
        {
            id = 1653933,
            score = 5,
            author = "Zillions",
            text = "Inside the building, you will find many pairs of Huojin Trainees in combat with each other. Simply enter combat with one, and bring his health to 10% or less.",
            date = "2012-04-14T16:13:02-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29524#comments:id=1653933",
        },
        {
            id = 1743023,
            score = 4,
            author = "75886",
            text = "Kind of amusing how this is supposed to be a training exercise, and the fight stops when you get them to low health, yet they will beat you to death if you let them.",
            date = "2012-10-16T03:00:34-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29524#comments:id=1743023",
        },
        {
            id = 1657474,
            score = 3,
            author = "329137",
            text = "This works with either Huojin Trainees or Tushui Trainees.\n\nYou'll find them not only inside the nearby Temple on the training grounds (on all floors), but on the verandas, on the hill outside the Temple, and down the hill along the slopes at the foot of the temple.",
            date = "2012-04-22T17:38:39-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29524#comments:id=1657474",
        },
    },
    [29527] = {
