    [29555] = {
        {
            id = 1699017,
            score = 62,
            author = "Diwtay",
            text = "The 3 Clues are:\n\n1. Dead body on the deck of the ship.\n2. Alliance Banner inside ship.\n3. Journal inside the ship.\n\nThe \009Encoded Captain's Log drops from a Hozen Diver swimming inside the sunken ship. He's wearing a diving helmet.",
            date = "2012-08-12T11:28:18-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29555#comments:id=1699017",
        },
        {
            id = 1787408,
            score = 57,
            author = "724847",
            text = "When you pick up the Fine Leather Journal, be sure you have inventory space because you \"create\" Partially Soaked Pages when you do.  If you are unable to create the pages then you will not be able to complete the quest.  A little FYI I learned after a few moments of bewilderment.",
            date = "2012-12-25T19:11:02-06:00",
            sourceUrl = "https://www.wowhead.com/quest=29555#comments:id=1787408",
        },
        {
            id = 1669715,
            score = 14,
            author = "PriestessAur",
            text = "This quest also rewards a book called \"Partially Soaked Pages\". The book reads:\n\nThe battle is more fearsome then I could have imagined.\nAll around us, I hear the booming of Horde artillery.\nTheir shells rain upon the deck above, and the screams of the crew are drowned out only by the roar of return fire.\n Admiral Taylor bade me hide here, in the hold, until the fighting ceases.\nThey have posted guards outside my door.\nI feel restless, I should be out there, helping them!\n\nThose that did not perish in the initial battle were lost in the ensuing storm.\nAs our battered ships fought their way through rain and fog, the most critically injured succumbed to their injuries.\nI did what I could to staunch their wounds, but it was not enough.\nWhy am I always too late to save my friends?\n\nI awoke in the middle of the night to the sound of a great, loud noise, like thunder.\nThe ship was running aground on the rocks.\nThe ship groaned and listed, and shouts and screams erupted on deck.\nI rushed to the door of my cabin, but my bodyguard locked me inside.\nThere is nothing I can do now but wait.\n\nThe Sapphire has washed up on an unfamiliar shore. The ship is still, and all around me, I hear silence.\nNo one has come for me and I fear that the crew is dead.\nThe cabin is filling with water, so I must find a way out soon.\nIf any Alliance soldier finds this, know that I, Prince Anduin Wrynn, am alive.\nI am going to travel inland and search of food and aid.\nPlease tell my father that I am well.\n\nThis is a lore item only, and it may be safely deleted once you are finished with it.",
            date = "2012-05-22T19:06:04-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29555#comments:id=1669715",
        },
        {
            id = 1798810,
            score = 9,
            author = "entropicdragon",
            text = "This quest becomes available after completing Onward and Inward (quest=31745).",
            date = "2013-01-15T02:17:38-06:00",
            sourceUrl = "https://www.wowhead.com/quest=29555#comments:id=1798810",
        },
        {
            id = 1793181,
            score = 8,
            author = "1071155",
            text = "This quest might be a bit confusing at first but right when you notice what you have to do it's simple.\n\nIt's like those quest's where you have to loot stuff but it's shown out a different way.\n\nInstead of collect item's, it's \"clues\". (One item a hozen diver drop's)\n\nWhere you do the quest when you kill the hozen. There is a shipwreck. Search around the boat (inside and outside) till you find the clues. The Clue's would have a gear on top of it.\n\nThe Clue's you are looking for are :\n1. A Dead Alliance solider on the shipwreck\n2. A Banner representing the alliance inside the ship hanging from the ceiling.\n3. A Journal also inside the ship.\n4. The Encoded Captain's log is dropped from a Hozen Diver wearing a helmet.\n\nHope that helped! (:",
            date = "2013-01-05T17:00:17-06:00",
            sourceUrl = "https://www.wowhead.com/quest=29555#comments:id=1793181",
        },
    },
    [29556] = {
        {
            id = 1729282,
            score = 13,
            author = "312183",
            text = "The title of this quest seems to be in reference to the Ludacris song \"Ho\" where he says \"Hos are your friends, hos are your enemies.\"\n\nForgive what may be foul language to some... WoW did it not me!",
            date = "2012-10-02T22:56:54-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29556#comments:id=1729282",
        },
        {
            id = 1718365,
            score = 7,
            author = "398298",
            text = "The Hozen out of the water do a Banana Toss (http://www.wowhead.com/spell=130803) - making you slip in a banana peel basically. Since they attack in small hordes, this can be dangerous, as slipping in a banana peel is like a two or three second stun.\nYou can sidestep bananas, fortunately.",
            date = "2012-09-25T06:16:30-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29556#comments:id=1718365",
        },
        {
            id = 1753179,
