            author = "entropicdragon",
            text = "This quest becomes available after completing The Missing Admiral (quest=29553).",
            date = "2013-01-15T02:22:03-06:00",
            sourceUrl = "https://www.wowhead.com/quest=29558#comments:id=1798814",
