    [29573] = {
        {
            id = 1588995,
            score = 3,
            author = "406368",
            text = "https://www.wowhead.com/quest=29573 and https://www.wowhead.com/quest=29575 are two new quests added in patch 4.3 to the [zone=3519] area, and can be acquired from and returned to https://www.wowhead.com/npc=54692 inside of the [zone=3792] dungeon instance, which is a representative for [faction=933].  He is located in the northern-most instance portal, inside of the [zone=3792] itself.  It is highly suggested to pick up https://www.wowhead.com/quest=29574 from https://www.wowhead.com/npc=54694 right next to https://www.wowhead.com/npc=54692 before clearing this dungeon.\n\nIn https://www.wowhead.com/quest=29573, players must happily kill 10 Ethereal Crypt Raiders, 5 Ethereal Sorcerers, 5 Nexus Stalkers, and 5 Ethereal Spellbinders (links to each inside of the quest link) in [zone=3792].  All of these are mobs that are usually packed in mixed groups of 2-5 together, so if players are near the level for this zone, they should be careful of mixing pulls from other close groups as they may end up pulling 10-15 mobs in a single room at once.  Some of the mobs are only located in the room just before https://www.wowhead.com/npc=18344.\n\nFor https://www.wowhead.com/quest=29575 players must acquire https://www.wowhead.com/item=28490 by killing anti-Consortium leader https://www.wowhead.com/npc=18344 in [zone=3792].\n\nPlayers DO NOT need to be in Heroic mode in order to complete this quest.\n\nWith both guild perks https://www.wowhead.com/spell=78635, players will receive 275 reputation with [faction=933], and 1 guild rep (2 with https://www.wowhead.com/item=69210) per quest.\n\nProgress text:  \"Done already?  You blood elfs continue to fascinate me.\"\n\nNOTE:  As of this time few of the tooltips, quests, or Quick Facts have been updated linking items/NPCs/quests together.  These are single quests and as yet do not have any associated chains or quests thereafter.  Will continue to scan for changes and update as needed.",
            date = "2011-12-04T06:46:08-06:00",
            sourceUrl = "https://www.wowhead.com/quest=29573#comments:id=1588995",
        },
        {
            id = 1690397,
            score = 3,
            author = "Eillesthis",
            text = "This quest replaced https://www.wowhead.com/quest=10216.  https://www.wowhead.com/npc=19671, his friends, and the old followup https://www.wowhead.com/quest=10218 have been removed and not replaced.  The https://www.wowhead.com/object=183877 is still there, but now serves no purpose.",
            date = "2012-07-20T15:14:17-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29573#comments:id=1690397",
        },
    },
    [29574] = {
        {
            id = 1588972,
            score = 5,
            author = "406368",
            text = "https://www.wowhead.com/quest=29574 is a new quest added in patch 4.3 to the [zone=3519] area, and can be acquired from and returned to https://www.wowhead.com/npc=54694 inside of the [zone=3792] dungeon instance, which is a representative for [faction=933].  He is located in the northern-most instance portal, inside of the [zone=3792] itself.  It is highly suggested to pick up https://www.wowhead.com/quest=29573 and https://www.wowhead.com/quest=29575 from https://www.wowhead.com/npc=54692 right next to https://www.wowhead.com/npc=54694 before clearing this dungeon.\n\nhttps://www.wowhead.com/item=72127 is acquired from killing crystal colossus boss https://www.wowhead.com/npc=18343.\n\nhttps://www.wowhead.com/item=72126 is acquired from killing giant voidwalker boss https://www.wowhead.com/npc=18341.\n\nPlayers DO NOT need to be in Heroic mode in order to complete this quest.\n\nWith both guild perks https://www.wowhead.com/spell=78635, players will receive 165 reputation with [faction=933], and 1 guild rep (2 with https://www.wowhead.com/item=69210).\n\nNOTE:  As of this time few of the tooltips, quests, or Quick Facts have been updated linking items/NPCs/quests together.  This is a single quest and as yet does not have any associated chains or quests thereafter.  Will continue to scan for changes and update as needed.",
            date = "2011-12-04T06:24:39-06:00",
            sourceUrl = "https://www.wowhead.com/quest=29574#comments:id=1588972",
        },
    },
