    [29591] = {
        {
            id = 1589147,
            score = 10,
            author = "406368",
            text = "Quest-giver is https://www.wowhead.com/npc=54698 in the [zone=3790].  The skeletons in this quest are easily found in the Chamber of the Restless located not long after crossing the Bridge of Souls and killing https://www.wowhead.com/npc=18371.  Further along in the Crypt of Remembrance there are all of the [npc=18700 your dog can buffet on, along with the https://www.wowhead.com/npc=18702s needed.  Attacking any one mobster in a group will excite ALL of that mob's members, so pick your targets wisely w/o getting aggro on yet another mob group unless you can handle them easily enough.  Suggestion is to range target the https://www.wowhead.com/npc=18702, as the bones are pretty weak without them.\n\nA good Hunter with Explosive Trap can pretty much kite them around in circles inside the trap and watch them fry quickly.\n\nNOTE:  This quest is available to BOTH Factions and DOES NOT require Heroic to complete.\n\nProgress text:  \"Don't speak to me again until the deed is done.\"\n\nWhen your quest is ready for turn-in, the https://www.wowhead.com/npc=54698 walks from hiding in the shadows to stand in the doorway of her room so that players can turn-in without forgetting about her.",
            date = "2011-12-04T09:30:44-06:00",
            sourceUrl = "https://www.wowhead.com/quest=29591#comments:id=1589147",
        },
    },
    [29593] = {
        {
