    [29596] = {
        {
            id = 1983735,
            score = 4,
            author = "309039",
            text = "It is no longer necessary to complete the Ha'lei questlines to unlock this quest as of 4.3.",
            date = "2014-07-23T18:41:08-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29596#comments:id=1983735",
        },
    },
    [29598] = {
        {
            id = 1589468,
            score = 284,
            author = "Stone",
            text = "There is an issue with the quest.  It's not necessarily bugged, however, you MUST be quick on the draw.  On completion, you need to turn the quest in to Thrall before someone else talks to him and allows him to escape the cell.\n\nOnce Thrall has escaped the cell you will not be able to turn the quest in until the next time you're in the instance.\n\nEdit: Why is this being rated down?  This is definitely valuable information I wish I and my group had known before we got in there.  One of our group had already been in here and completed his quest in a previous instance... he allowed Thrall to escape not realizing the rest of us who were new to the quest could never turn it in.",
            date = "2011-12-04T15:16:40-06:00",
            sourceUrl = "https://www.wowhead.com/quest=29598#comments:id=1589468",
        },
        {
            id = 1629784,
            score = 103,
            author = "Zeror",
            text = "You have to burn down the 5 cottages by clicking on a https://www.wowhead.com/object=182589 inside them. These cottages can be found in the lower part of Durnholde where those https://www.wowhead.com/npc=18598 are.",
            date = "2012-02-21T08:51:33-06:00",
            sourceUrl = "https://www.wowhead.com/quest=29598#comments:id=1629784",
        },
        {
            id = 3126692,
            score = 50,
            author = "Berbe",
            text = "For those seeking QUEST HAND IN =>  It can be done only before Thrall exits its prison. If he gets out, you need to either let him die to reset him or hand in the quest on your next visit to the dungeon.  To be clear => You CAN NOT hand in the quest after you finish the dungeon.",
            date = "2019-06-13T15:03:30-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29598#comments:id=3126692",
        },
        {
            id = 1845839,
            score = 38,
            author = "Mormolyce",
            text = "I really wish they would do something about this quest. Out of five people at least one will always start Thrall before you cash the quest.",
            date = "2013-04-22T09:22:46-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29598#comments:id=1845839",
        },
        {
            id = 2497232,
            score = 21,
            author = "Gymlea",
            text = "In the Caverns of Time you can do the Durnholde instance. When you enter the instance, talk to the humanoid Erozion, he will give you these Incendiary Bombs. If for any reason you lose them, go back to him and get more.\n\nEach one of the buildings in the pit at Durnholde has a darker-brown barrel. Place one Incendiary Bomb on each. You will need to kill the guards to do this.\n\nThe fires they cause will call Lieutenant Drake.\n\nThen go into the basement of the hold. The basement entrance is under the stairs up.\n\nFree Thrall, and as you leave the gate Captain Skarloc will appear.\n\nYou must speak, right click, Thrall to get him to move out of the basement, and again to get him to leave Durnholde for Tarren Mill. Taretha is upstairs in the Inn, which you will reach after Thrall searches the barn, and the church. You must kill the mobs to get Thrall to move on. Click on Thrall to get to the next segment after he finds Taretha.",
            date = "2017-05-29T10:52:20-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29598#comments:id=2497232",
        },
    },
    [29599] = {
        {
            id = 1629789,
            score = 92,
            author = "Zeror",
            text = "If you ever lose Thrall on your way towards Tarren Mill, then he is waiting for you on the southeastern side of Tarren Mill on a hill (east of the barn there).",
            date = "2012-02-21T09:08:26-06:00",
            sourceUrl = "https://www.wowhead.com/quest=29599#comments:id=1629789",
        },
        {
            id = 1751902,
            score = 42,
            author = "Loremastertappa",
            text = "Neat little Easter egg.  You can see how Commander Mograine obtained the crystal for Ashbringer.   When you get done with the dungeon, look on the map and you should see a road that runs south close to the river.  If you follow it, you come to Southshore.  Go to the second house on the left which should be an Inn.  There, Commander Mograine is sitting at a table conversing with others about a crystal he found.  It is fascinating to watch if you're into the Lore.",
            date = "2012-10-27T15:10:24-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29599#comments:id=1751902",
        },
        {
            id = 2497231,
            score = 33,
            author = "Gymlea",
            text = "In the Caverns of Time you can do the Durnholde instance. When you enter the instance, talk to the humanoid Erozion, he will give you these Incendiary Bombs. If for any reason you lose them, go back to him and get more.\n\nEach one of the buildings in the pit at Durnholde has a darker-brown barrel. Place one Incendiary Bomb on each. You will need to kill the guards to do this.\n\nThe fires they cause will call Lieutenant Drake.\n\nThen go into the basement of the hold. The basement entrance is under the stairs up.\n\nFree Thrall, and as you leave the gate Captain Skarloc will appear.\n\nYou must speak, right click, Thrall to get him to move out of the basement, and again to get him to leave Durnholde for Tarren Mill. Taretha is upstairs in the Inn, which you will reach after Thrall searches the barn, and the church. You must kill the mobs to get Thrall to move on. Click on Thrall to get to the next segment after he finds Taretha.",
            date = "2017-05-29T10:51:59-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29599#comments:id=2497231",
        },
        {
            id = 1585422,
            score = 16,
            author = "dRAEMtYGER",
            text = "Accepting the quest does not start the escort.  So you will have to talk to Thrall twice to start the escort portion of the dungeon.\n\nAt 85 completing this quest gave me 1050 rep (+5% guild rep bonus), 1 gold 44 silver and 600 guild experience.\n\nEdit:  It should be obvious but you'll want to make sure everyone has turned in the previous and accepted the current quest before starting the escort.  And if you've accidentally started the escort before everyone turned in the quest you can reset Thrall by letting him die.  He'll reappear in the cell if he dies before you kill the next boss.",
            date = "2011-11-30T21:46:40-06:00",
            sourceUrl = "https://www.wowhead.com/quest=29599#comments:id=1585422",
        },
        {
            id = 1602341,
            score = 12,
            author = "Netspook",
            text = "The \"?\" on the map is somewhat at the wrong place. You turn in the quest in Tarren Mills after the scene that occurs when last boss is down.\n\nYou *can* turn it in where the map shows, in the tunnel opening, but not in the same instance run as when you do the quest.\n\nBtw, at lvl 67, this quest gives 30,000 exp.",
            date = "2011-12-26T16:50:01-06:00",
            sourceUrl = "https://www.wowhead.com/quest=29599#comments:id=1602341",
        },
    },
    [29600] = {
        {
            id = 1654853,
            score = 1,
            author = "Cielos",
            text = "You pick up this quest from https://www.wowhead.com/npc=56802 in the Pools of Purity in the Valley of the Four Winds.  The turtles are located right up the hill near the quest giver and only have about 37k health, so they can be taken out easily.\n\nMake sure to pick up https://www.wowhead.com/quest=29757 from Yan and https://www.wowhead.com/quest=29871 (it leads to https://www.wowhead.com/quest=29581 ) in New Cifera.  These quests will need to be completed in the same area.",
            date = "2012-04-16T12:12:50-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29600#comments:id=1654853",
        },
