    [29611] = {
        {
            id = 2278279,
            score = 37,
            author = "Wowzir",
            text = "For Patch 6.2.3 or higher with a low level character on which you used the instant upgrade to level 100, you still get to Pandaria by using this quest chain.\n\nI was definintely able to get https://www.wowhead.com/quest=29611 from the Warchief's Command Board in Orgrimmar (I used the board in the Valley of Honor after trying to find the portal to Pandaria there).\n\nThe best board to go to is the one in the Valley of Strength immediately outside of Grommash Hold, Orgrimmar.\n\nAs soon as you enter Grommash Hold, the cinematic will start assuming you picked up the quest.\n\nOnce you turn in this quest to https://www.wowhead.com/npc=54870, he will offer you https://www.wowhead.com/quest=31853.\n\nI imagine it will be similar for the other skipped Expansion Packs.",
            date = "2015-11-21T17:09:52-06:00",
            sourceUrl = "https://www.wowhead.com/quest=29611#comments:id=2278279",
        },
        {
            id = 1718558,
            score = 19,
            author = "Cynddrela",
            text = "I made Garrosh wait! :D",
            date = "2012-09-25T10:02:39-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29611#comments:id=1718558",
        },
        {
            id = 1951624,
            score = 14,
            author = "zomgname",
            text = "This quest, as well as the other starting Panderia quest, are auto-completed for you when you boost a character to level 90. There is no way to go and do them, and no way to get the items from them other than the old raids that share the models.\n\nI spoke with a GM that said there would be \"many many\" problems if this was not done. The GM said, despite being able to clearly see the quest were auto-completed and we got nothing from them, they cannot grant the items, \"their system won't allow it\". I was told that \"it sucks but I get a level 90 with 2 max profressions\". I informed the GM that I didn't get max profressions because I boosted from level 1, and they asked me if I had professions at level 1. I had to explain to the GM how their boost system works, and that you only get boosted profressions if you are level 60.",
            date = "2014-03-17T01:20:37-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29611#comments:id=1951624",
        },
        {
            id = 2019226,
            score = 13,
            author = "WoolferRU",
            text = "As of patch 6.0.2 you can get this quest on Alliance char, but cann't complete it (Nazgrim won't talk with you)",
            date = "2014-10-26T03:28:46-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29611#comments:id=2019226",
        },
        {
            id = 1718691,
            score = 12,
            author = "jojopojo64",
            text = "More for RP than anything, there's two versions of this quest, the other being http://www.wowhead.com/quest=29612#comments\n\nBasically, if you've never completed the Vash'jir questline, you'll get this version, with Nazgrim commanding you to see Ogrelord Overlord Hellscream at once, while the other one greets you with slightly friendlier fanfare.\n\nEither way, it's best not to keep Garrosh waiting, Pandaria (and a pretty exciting pre-cinematic) awaits!",
            date = "2012-09-25T12:15:03-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29611#comments:id=1718691",
        },
    },
    [29612] = {
        {
            id = 1718550,
            score = 27,
            author = "Cynddrela",
            text = "I made Garrosh wait.",
            date = "2012-09-25T09:57:46-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29612#comments:id=1718550",
        },
        {
            id = 1656230,
            score = 20,
            author = "981730",
            text = "It looks as though this is the quest that you get if you complete Vashj'ir, where you aid Nazgrim in assaulting the Throne of the Tides.\n\nThat is why he calls you 'Old Friend,' and says he is pleased you made it out of the depths.\n\nI can't wait to help Nazgrim again! He's a boss. Wreckin' Naga like they nothin'.",
            date = "2012-04-19T17:58:50-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29612#comments:id=1656230",
        },
        {
            id = 1718697,
            score = 14,
            author = "jojopojo64",
            text = "More for RP than anything, there's two versions of this quest, the other being http://www.wowhead.com/quest=29611#comments:id=1718691\n\nBasically, if you've never completed the Vash'jir questline, you'll get the other version, with Nazgrim commanding you to see Ogrelord Overlord Hellscream at once, while this one greets you with slightly friendlier fanfare.\n\nEither way, it's best not to keep Garrosh waiting, Pandaria (and a pretty exciting pre-cinematic) awaits!",
            date = "2012-09-25T12:17:11-05:00",
