            text = "The Alliance version of this quest is The King's Command (http://www.wowhead.com/quest=29547)",
            date = "2012-11-18T08:46:17-06:00",
            sourceUrl = "https://www.wowhead.com/quest=29612#comments:id=1764209",
        },
        {
            id = 1693606,
            score = 6,
            author = "ldene",
            text = "Quest actually leads to https://www.wowhead.com/quest=31853. As mentioned in the post above, theres actually 2 versions of \"The Art of War\" quest - one for those who've completed Vashj'ir and one for those haven't. The quest chain after this can be found here https://www.wowhead.com/quest=29611.",
            date = "2012-07-29T11:50:01-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29612#comments:id=1693606",
        },
    },
    [29613] = {
        {
            id = 1601056,
            score = 59,
            author = "462533",
            text = "I was having problems untill I found out that there is a machine behind each of the two minor bosses. Click on the machine and after the second the door opens allowing access to the last boss.",
            date = "2011-12-23T18:42:55-06:00",
            sourceUrl = "https://www.wowhead.com/quest=29613#comments:id=1601056",
        },
        {
            id = 1673282,
            score = 4,
            author = "908758",
            text = "You have to kill the other two bosses first. Hydromancer Thespia is to the north (coords 53, 13). Behind her will be a Main Chambers Access Panel. Once you've killed her, click on the panel.\n\nMekgineer Steamrigger is to the south-west (coords 31, 83), and once you've killed him, you'll have to click on the Main Chambers Access Panel behind him. If you've successfully used both access panels, in the chat box it'll say:\n\nYou hear a faint echo....\nYou hear a loud rumble of metal grinding on stone....\n\nSo head around to Warlord Kalithresh's chamber, and you'll find the door is now open (coords 76, 44). There are about a dozen naga, plus the Warlord.",
            date = "2012-06-04T02:01:36-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29613#comments:id=1673282",
        },
    },
    [29614] = {
    },
    [29615] = {
    },
    [29616] = {
        {
