    [29617] = {
        {
            id = 1725062,
            score = 60,
            author = "776458",
            text = "Bit of a heads up, if you've done all the quests and still don't get the monastery for the \"Upjade Complete\" achievement, it is a glitch and just sign out and back in again and it should fix it. It's not the easiest place to navigate especially when you're new to the area so I was running around trying to find some hidden quest I'd miss, trying to remember where I'd already checked then I just signed out and when I signed back in it was done.",
            date = "2012-09-29T19:26:19-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29617#comments:id=1725062",
        },
        {
            id = 1723405,
            score = 37,
            author = "994699",
            text = "If you're like me and you are running around on your ground mount, stuck on the East Side of the Mountains were the Tian Monastery is located, your probably thinking, \"how the heck do I get to the top of this mountain?\" since your surrounded by a mountain edge you can't climb :( But at last i have found the path! :)\n\nThe path up to the Monastery (on the East side of the Mountain Ridge) is just WEST of the Greenstone Quarry (you can go into a mine tunnel to do some quests). Head directly west from there, and stop at around 45.15, 31.49. You should find yourself at the base of a small mountain side.. Look Up, Look way up! ;-) You can see the Monastery and the path is pretty clear... oh ya, and there are lots of those tigers around (Forest Huntress (http://www.wowhead.com/npc=59102)) at the base of the hill (for those that don't have coordinates). Hope this helps! :o)",
            date = "2012-09-28T18:20:57-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29617#comments:id=1723405",
        },
        {
            id = 1723637,
