    [29620] = {
        {
            id = 1718527,
            score = 62,
            author = "1036362",
            text = "When you hand in the quest and get the follow up to talk to High Elder Cloudfall, he also appears up in the tower right in front of you. Don't go there. Go to the banquet grounds as described by Lastkaii in the above:\n\nrun down the stairs you just came up and go up the second set of stairs on your right. Run straight ahead to find High Elder Cloudfall",
            date = "2012-09-25T09:30:50-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29620#comments:id=1718527",
        },
        {
            id = 1759355,
            score = 27,
            author = "Sketchie",
            text = "When you first talk to High Elder Cloudfall, you will have two options: To be introduced to several NPCs, or just skip right to the fun part. It is highly advisable to watch the introductions, they can be quite hilarious. If you ask him to introduce you, the following happens:\n\nHigh Elder Cloudfall says: Let us start with the three who sit behind me.\nHigh Elder Cloudfall says: Before you sits Instructor Myang. She will be responsible for teaching you the most practical fighting techniques.\nHigh Elder Cloudfall says: It is said that, before she joined the monastery, Myang defeated one hundred ravaging hozen in a single melee.\nInstructor Myang says: You flatter me, High Elder. Those hozen were weak, young, and unskilled. Any other pandaren would have done the same.\nHigh Elder Cloudfall says: Flatter you? You were eight years old.\nInstructor Myang says: ...and a half. Sir.\n\nInstructor Myang blushes and High Elder Cloudfall gives out a hearty chuckle. They then bow to each other.\n\nHigh Elder Cloudfall says: Next, we have Master Stone Fist. He will be leading your sparring exercises.\nHigh Elder Cloudfall says: Master Stone Fist is nearly unmatched in single combat. He once defeated nine hundred and ninety-nine challengers in a row.\nMaster Stone Fist says: The thousandth challenger cheated.\nHigh Elder Cloudfall yells: What? Cheated!\n\nHigh Elder Cloudfall jumps onto Master Stone Fist's table and punches Master Stone Fist.\n\nHigh Elder Cloudfall yells: I never cheat!\n\nHigh Elder Cloudfall steps off the table, bows to Master Stone Fist, and then and introduces you to the NPC next to Master Stone Fist.\n\nHigh Elder Cloudfall says: Finally, Instructor Xann. His mastery of the very basics of combat has given him a nearly perfect fighting form.\nHigh Elder Cloudfall says: Xann, how many practice strikes do your students perform daily?\nInstructor Xann says: Ten thousand strikes, every day.\nHigh Elder Cloudfall says: And how many do YOU perform?\nInstructor Xann smiles.\nInstructor Xann says: Ten thousand and one.\nHigh Elder Cloudfall says: Luckily, High Elders no longer have to perform basic training. I find that I am happier when I am not exercising.\nHigh Elder Cloudfall says: Walk and drink with me, .\n\nHe then leads you down to one of the tables where there is a big grey pandaren male walking up and down on it topless.\n\nHigh Elder Cloudfall says: Ah! Upon this table, you see Spirit-Sage Gaoquan, the oldest member of our monastery.\nHigh Elder Cloudfall says: He has seen many high elders come and go. He also tends to take these celebrations very seriously.\n\nHigh Elder Cloudfall then leads you down the banquet, pointing out various NPCs sitting on the tables, especially the Hozen and Jinyu.\n\nHigh Elder Cloudfall says: You may have noticed the hozen and jinyu among us. All are welcome here at the monastery, as long as they have the desire to learn.\n\nLastly, he leads you to a NPC on the ground, obviously drunk.\n\nHigh Elder Cloudfall says: Finally, this is Groundskeeper Wu.\nHigh Elder Cloudfall yells: WU!\nGroundskeeper Wu says: Ye... yes, high  elder?\nHigh Elder Cloudfall says: Wu, this is . He/she will be joining the other trainees.\nGroundskeeper Wu says: Oh... ... hello... sszzhhhh...\nHigh Elder Cloudfall says: Wu will be asking you to perform a few chores. Nothing complex, just some tasks relating to the maintenance of our monastery.\n\nHigh Elder Cloudfall starts walking back to the spot where he originally was in the front of the banquet with a few more notes.\n\nHigh Elder Cloudfall says: We are all responsible for maintaining our home. Even the Higher Elder must occasionally lend a hand.\nHigh Elder Cloudfall says: See? I'm helping by picking up this full mug of ale that someone left on the ground.\nHigh Elder Cloudfall says: Now you are caught up. And would you look at that? My cup is full again! It is good to be the High Elder.",
            date = "2012-11-08T14:50:12-06:00",
            sourceUrl = "https://www.wowhead.com/quest=29620#comments:id=1759355",
        },
        {
            id = 1671229,
            score = 13,
            author = "231785",
            text = "The introduction is quite lengthy in the minute+ range. If you don't care for it chose \"I don't need any introductions, old man. Let's skip ahead to the good part.\" He then asks you if you are certain, and the quest is completed.",
            date = "2012-05-28T20:17:23-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29620#comments:id=1671229",
        },
        {
            id = 1653371,
            score = 11,
            author = "262772",
            text = "Once you accept the quest from Lin Tenderpaw, run down the stairs you just came up and go up the second set of stairs on your right. Run straight ahead to find High Elder Cloudfall. To complete the quest, just go through his dialogue options. He will then walk around and introduce you to some of the residents of the Monastery, and the quest will complete.",
            date = "2012-04-13T15:19:38-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29620#comments:id=1653371",
        },
        {
            id = 1719858,
            score = 10,
            author = "916353",
            text = "This still appears to be confusing, the npc and the speech bubble is located directly above the quest giver but at that location you cant progress, you need to go to the banqueting area in the town, where the elder should then respawn with the necessary dialogue options to complete the quest.",
            date = "2012-09-26T08:26:27-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29620#comments:id=1719858",
        },
    },
    [29622] = {
        {
            id = 1813360,
