    [29628] = {
        {
            id = 1658120,
            score = 66,
            author = "Bethenal",
            text = "Once you gather the Boiling Cauldron, it will follow you like a pet.  You CAN mount up to return the cauldron, it will still follow you.  Just be sure to not travel too far ahead of it, or it will despawn.  I lost it several times because I wasn't giving it time to catch up.\n\nBeta Build 15589",
