        },
        {
            id = 1731254,
            score = 43,
            author = "Aluin",
            text = "For those of you who returned to quickly and lost your cauldron on the way back, the coordinates of the cauldron are 37,17.\n\nSince the map doesn't show you where the cauldron is after the first part of the quest is complete, I had some trouble remembering where it was when I had to go retrieve it again.",
            date = "2012-10-04T13:46:12-05:00",
