    [29632] = {
        {
            id = 1671230,
            score = 15,
            author = "231785",
            text = "You can challenge as many pupils as you wish at once. However defeating one won't give you any killing blow perks such as the warriors victory rush.",
            date = "2012-05-28T20:24:41-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29632#comments:id=1671230",
        },
        {
            id = 1851707,
            score = 8,
            author = "Gadoink4",
            text = "Let's see how you hold up against my \"slow, weak punches\" technique!\n\nDang, these guys are just too powerful.",
            date = "2013-05-10T03:37:12-05:00",
