        },
        {
            id = 1788385,
            score = 5,
            author = "Grasst",
            text = "If you are a class that can take some punishment, challenge many at a time. As a pally tank, I easily could take the damage of all eight that I needed to beat at once. As Lancestalker said, it was like a scene from an epic fight movie....",
            date = "2012-12-27T22:04:47-06:00",
            sourceUrl = "https://www.wowhead.com/quest=29632#comments:id=1788385",
