        {
            id = 1653614,
            score = 3,
            author = "262772",
            text = "Once you accept the quest from Master Stone Fist, you will notice that the \"Monastic Pupil\" mobs are right in front of you. You are able to challenge them by right clicking on them and requesting a fight. They have 158K health, and respawn fairly quickly.\n\nOnce you complete your 8 duels, head back to Master Stone Fist to complete the quest.",
            date = "2012-04-14T01:53:47-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29632#comments:id=1653614",
