            text = "For some reason I did not receive credit for this quest even though I did get the defeated dialogue. After defeating him a 2nd time it finally completed.",
            date = "2012-10-28T21:51:48-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29633#comments:id=1752845",
        },
