    [29634] = {
        {
            id = 1731810,
            score = 10,
            author = "Merum",
            text = "As a side note, don't fall into the water. There's no way back up.",
            date = "2012-10-05T01:15:56-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29634#comments:id=1731810",
        },
        {
            id = 1653618,
            score = 5,
            author = "262772",
            text = "Once you accept the quest from Master Stone Fist, run east to the river area. Husshun is standing by the river, and is a friendly mob until you challenge him. He has 316K health, and will give up once he reaches zero health.\n\nAfter defeating Husshun, return to Master Stone Fist to complete this quest.",
            date = "2012-04-14T02:02:28-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29634#comments:id=1653618",
        },
        {
            id = 1874566,
            score = 5,
            author = "SpectrusLegend",
            text = "\"I knew I would lose. The rivers told me so.\"\n\nThat's right, the rivers themselves are on my side.",
            date = "2013-07-07T15:29:17-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29634#comments:id=1874566",
        },
        {
            id = 1747591,
            score = 3,
            author = "969422",
            text = "If you cant find him he's not on the path. Look directly across from the spirit sage and through the buildings in the grass. I kept running up steps and in circles before I finally tried not using the path.",
            date = "2012-10-22T01:08:27-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29634#comments:id=1747591",
        },
        {
            id = 1744016,
            score = 1,
            author = "280442",
            text = "\"Husshun says: I knew I would lose. The rivers told me so.\"\n\n6 months earlier...\nI have studied for years for this moment and the day has come for me to commune with the waters and learn their wisdom.\nQ: I can only ask that you provide me wisdom in my time of need. What would you have me to know?\nA: You're a loser.",
            date = "2012-10-17T11:06:53-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29634#comments:id=1744016",
        },
    },
    [29635] = {
        {
            id = 1744017,
            score = 11,
            author = "280442",
            text = "And sometimes these mobs just bug and show grey like someone else tagged them.\nJust run out of his range down the stairs or something and let him reset if you don't want to fight him twice. Come back in range after his reset and immediately start combat again. No talking necessary.",
            date = "2012-10-17T11:11:52-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29635#comments:id=1744017",
        },
        {
            id = 1874569,
            score = 7,
            author = "SpectrusLegend",
            text = "Did anyone else notice he made feminine sounds when you hit him?",
            date = "2013-07-07T15:32:53-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29635#comments:id=1874569",
        },
        {
            id = 1653621,
            score = 6,
            author = "262772",
            text = "Once you accept the quest from Master Stone Fist, head up the short staircase to the north and you should see Xiao near the tables. He is a friendly mob until he is challenged. He has 474K health, and will give up once he reaches zero health.\n\nAfter defeating Xiao, return to Master Stone Fist to complete this quest.",
