    [29636] = {
        {
            id = 1653625,
            score = 2,
            author = "262772",
            text = "Once you accept the quest from Master Stone Fist, proceed west through the archway behind him. Go down the stairs, and continue to follow the path across the bridge. Continue to follow the path, until you see Instructor Myang in the distance, right beside The Rumpus Pit.",
            date = "2012-04-14T02:29:29-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29636#comments:id=1653625",
        },
        {
            id = 1875931,
            score = 1,
            author = "Cipherr",
            text = "If you have a tank specced character with no dps offspec and nothing but Tanking avoidance gear from the Cata days, this quest will take a long time.\n\nThey forgot about tanks on this quest, its totally built for DPS classes. It took me forever to whittle those bags down.",
            date = "2013-07-11T23:19:15-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29636#comments:id=1875931",
        },
    },
    [29637] = {
        {
            id = 1653626,
            score = 15,
            author = "262772",
            text = "Once you accept the quest from Instructor Myang, run down into The Rumpus Pit which is directly in front of the quest giver. Once you are inside The Rumpus Pit, use your \"Monastery Fireworks\". This will give you a buff called \"In the Rumpus\" which lasts for two minutes.\n\nYou will need to stay alive in The Rumpus Pit until the buff runs out to complete the quest. There are a large amount of mobs that will attack you, however they only have 20K health each and go down fairly quickly.\n\nAfter you have completed the two minutes, return to Instructor Myang to complete the quest.",
            date = "2012-04-14T02:35:57-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29637#comments:id=1653626",
        },
        {
            id = 1721805,
            score = 11,
            author = "885808",
            text = "FYI:\nI don't know if it will help much, but I died with about 6 seconds left of the 2 minutes. I just stayed there dead and didn't go to the cemetery. I got the question mark from the quest giver then went to the cemetery. I ran back, resurrected, and turned it in.\n\nI'm not sure how close you'll have to be to the 2 minutes...so it may be worth it stick around until time runs out.",
            date = "2012-09-27T15:08:26-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29637#comments:id=1721805",
        },
        {
            id = 2561462,
            score = 5,
            author = "shihni",
            text = "You can use the item while mounted, then just hover above the arena on your flying mount.",
            date = "2018-04-05T16:00:28-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29637#comments:id=2561462",
        },
        {
            id = 1731327,
            score = 4,
            author = "idlebyte",
            text = "I was mounted when I started the Rumpus using the fireworks.  I stayed mounted and saw what was coming.  So I ran back and forth between the two sides with posts.  If you run behind the posts you won't loose your rumpus buff.  I kept dragging the group back and forth like a clock, getting them tangled in the poles.  I kept this up for 1.50 minutes only occasionally getting hit (not enough to get dismounted) until the real flood started.  I got knocked off but used an ice block to survive the last few seconds.  Super Easy!  Lost 2K health in total as an ice mage.",
            date = "2012-10-04T15:00:02-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29637#comments:id=1731327",
        },
        {
            id = 1747598,
            score = 4,
            author = "969422",
            text = "my reps not high enough to up the comment but shortcuddy THANK YOU! I mounted and ran around for bit but got knocked off. Then summoned my doom guard and had my void out and just rain of fire'd everybody. Eventually I died but didn't rez. You can still see Myang speaking and she lets you know when times up. I got the complete and the ? then rez'd and ran back to my body to be alive. Turned it in and voila!",
            date = "2012-10-22T01:24:47-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29637#comments:id=1747598",
        },
    },
    [29639] = {
        {
            id = 1718578,
