    },
    [29640] = {
        {
            id = 1634816,
            score = 3,
            author = "638983",
            text = "Spy To'gun can be seen through a hole in the wall on the right hand side of the first room, just after entering the Shadow Labyrinth (www.wowhead.com/zone=3789) instance in Terokkar Forest (www.wowhead.com/zone=3519).\n\nYou will find him by following the semi circular path on the left hand side of the first room, running straight across the second room and then down another semi circular path.",
            date = "2012-03-04T02:54:39-06:00",
            sourceUrl = "https://www.wowhead.com/quest=29640#comments:id=1634816",
        },
        {
            id = 1689029,
            score = 2,
            author = "Barleduq",
            text = "In particular, you have to kill https://www.wowhead.com/npc=18731, thus completing https://www.wowhead.com/quest=29645, before you can get to the other semi-circular pathway that leads to https://www.wowhead.com/npc=18891. It was not clear to me if this ended up turning into an escort quest or not - he just stood outside the cell and didn't move. Eventually I gave up and went on. (Soloing this on my L84 Draenei Hunter, for the daily https://www.wowhead.com/quest=11376 from https://www.wowhead.com/npc=24370.)",
            date = "2012-07-17T03:09:15-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29640#comments:id=1689029",
        },
    },
    [29641] = {
        {
            id = 1634825,
            score = 29,
            author = "638983",
            text = "These items are found around the instance. There are some inside the purple tents in third room and some around the outskirts of the fourth room.\n\nThey look like large cricket stumps with 2 purple glowing orbs and a green lantern, on top of them.\n\nThey do not drop from mobs, etc.",
            date = "2012-03-04T03:18:39-06:00",
            sourceUrl = "https://www.wowhead.com/quest=29641#comments:id=1634825",
        },
        {
            id = 3202223,
            score = 5,
            author = "Naommi",
            text = "I did not pick up this quest until after I had cleared the dungeon on a farming run (fel armaments for rep)\n\nI did not have to exit and reset the dungeon to be able to pick up the \"soul devices\" and complete the quest.\n\nThey became interactive and \"usable\" immediately after I picked up the quest.",
            date = "2020-04-25T10:19:50-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29641#comments:id=3202223",
        },
    },
    [29642] = {
        {
            id = 1632612,
            score = 25,
            author = "Qoko",
            text = "Wowhead's quest log and Wholly/Grail flag this quest as incomplete, and I can't accept or complete it. It is probably related to the fact that for most dungeon breadcrumb quests a new one was implemented when the dungeon system changed in 4.3. Some are doable, some are considered identical. This is one of the latter; you can move to Shadow Labyrinth directly to do all the new quests there.\n\nIt might actually be related to quests that involve reputation gains, in order not to gain from the same quest twice. This I haven't tested or investigated thus far.\n\nEDIT: on my new alt I had actually done all four Auchidoun dungeons and all quests inside before checking up on this quest. When I flew into Shatt at 70, this quest was available to me. So for players for which this quest is not available, it is very likely related to the fact you have done the previous quest and gained the rep before, therefore it is locked out.",
            date = "2012-02-27T17:19:28-06:00",
            sourceUrl = "https://www.wowhead.com/quest=29642#comments:id=1632612",
        },
        {
            id = 2184963,
            score = 4,
            author = "1406519",
            text = "Does not count towards Terror of Terokkar or Loremaster.",
            date = "2015-05-19T23:41:30-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29642#comments:id=2184963",
        },
    },
    [29643] = {
        {
            id = 1627704,
            score = 4,
            author = "473517",
            text = "The quest is completed by clicking on the book, The Codex of Blood (http://www.wowhead.com/object=182947) behind the boss, Grandmaster Vorpil (http://www.wowhead.com/npc=18732) after he is dead. It is easy to miss and forget to do this while running Shadow Labyrinth (http://www.wowhead.com/zone=3789) because there is no yellow question mark (at least when I ran it last, Blizzard may have changed that by now) so take a look at the screenshot to familiarize yourself with what the scene will look like.\n\nThe book reads;\n\nThe musty pages of the codex seem to magically turn themselves, guiding your attention to a specific chapter past horrors no mortal eyes should ever perceive.\n\nThe book opens to a page that somehow feels \"right\" yet so very wrong.\n\nRead on, if you dare...\n\nLong ago, in a dimension of the cosmos unfathomable to mortal minds, there was born - if such a term can be used for it - a being of such unbelievable power that it's very entrance into existence shattered all reality around it.\n\nKnown only as Murmur, it was the essence of sound, and to hear it speak was to hear death eternal!\n\nRead on, if you dare...\n\nExisting only for chaos, it's slightest whisper meant the destruction of whole worlds!\n\nYet still, there were those that would try to worship this mindless being. There were even those more insane who dared to think to control it!\n\nRead on, if you dare...\n\nAnd lo, how the mighty fell trembling at it's feet, fearful that it might direct it's words upon them.\n\nBut still these charlatans, these worshiping pretenders to a non-existent religion, rail against the inevitable in a vain attempt to control their \"god.\" Uncaring, and likely not even noticing them, Murmur yawned and they knew oblivion.\n\nYet one somehow managed to survive, and in his insanity found a way to bring Murmur into the world.\n\nRead on, if you dare...\n\nA mortal possessed of arcane and dark knowledge that none could surpass, he devised a method to enhance his summoning through the capture and use of souls untold.\n\nWhole civilizations were brought to extinction through his soul devices to fuel the ritual through which he and his conspirators would bring Murmur into their world.\n\nRead on, if you dare...\n\nAnd summon forth Murmur they did.\n\nPowerful magics of containment and silencing were employed, held together by the constant supply of souls being fed into them. Yet still they could not control the beast, could not bend it to their will.\n\nThese mortals began to devise different strategies, and one after the other they all failed. And in so doing, they weakened the rituals, accidentally giving Murmur the slightest modicum of freedom.\n\nIt was all that was needed.\n\nRead on, if you dare...\n\nOnly this book survived the cataclysm that destroyed their world. Those proud and foolish men who thought to control a cosmic being of untold power.\n\nWould you, the possessor of the codex, do the same?\n\nHave you devised a foolproof method to summon forth Murmur, or any of the other entities cautiously whispered of in these unhallowed pages?\n\nWe shall see.",
            date = "2012-02-16T23:24:09-06:00",
            sourceUrl = "https://www.wowhead.com/quest=29643#comments:id=1627704",
        },
