    [29661] = {
        {
            id = 1720533,
            score = 20,
            author = "druunah",
            text = "The poles are like any \"vehicle\" on WoW. Simply mouse over them until you see the green arrow, then click to \"jump\" your toon from pole to pole until you reach the bell. Once you are close to the bell, you are auto dismounted from the pole and you will land near the bell. Click on the bell.\n\nBeware of falling in as the cranes will attack you! The quest warns to not fall off the pole or you will have to restart, however the one time I \"fell off\" i was easily able to jump back on the poles and finish the quest with no problem.",
            date = "2012-09-26T16:52:13-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29661#comments:id=1720533",
        },
        {
            id = 1718437,
            score = 13,
            author = "723243",
            text = "OMG.  Don't be stupid like me.  This quest is easy.  Don't go in the water.  The water turns you into a frog and the cranes think of you as a tasty snack.  Instead, there are shorter poles on either end of the bridge.  They're called \"Exit Poles\".  You can click on them when you're out of the water.  The water isn't your friend.\nIf you happen to be in the water, you can try and jump on the reeds sticking out, turning you back into normal form.  During that split second, click on one of the balancing poles.",
            date = "2012-09-25T07:50:50-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29661#comments:id=1718437",
        },
        {
            id = 1723573,
            score = 8,
            author = "780529",
            text = "[quest=29661 domain=www] confirmed!  Incredibly easy but never would've figured it out.  Leave the quest giver and stay in the pond.  Go under the bridge and when you mouse over the pillars they will have a green \"mount\" arrow.",
            date = "2012-09-28T21:05:03-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29661#comments:id=1723573",
        },
        {
            id = 1767492,
            score = 7,
            author = "938446",
            text = "For this quest you have to use the exit poles that are near \"shore.\" you cannot go in the middle of the water and start from there, then you jump from pole to pole until you reach the bell. Ring the bell and you're finished. (See screenshots for exit poles if you are unsure.)\n\nIf you're clever you wouldve picked up the quests: Stronger than reeds & The lesson of the balanced rock.\nSo you finish off 6 of the tushui monks and then jump in water to pick reeds. Voila. You're done with 3 quests.",
            date = "2012-11-25T04:01:07-06:00",
            sourceUrl = "https://www.wowhead.com/quest=29661#comments:id=1767492",
        },
        {
            id = 1718158,
            score = 6,
            author = "807017",
            text = "This quest cant complete if you play it in trial version! When you try to jump to the palisade, the game asks you for cata...:-(\nHope Blizz fix it soon, coz i am stuck in 6th lvl....\n\nHmm...and it seems there is not any other quest to continue. I searched the hole area. Max lvl is 6-7, unless you wanna kill randomly  anything that walks and fly's there to lvlup :(",
            date = "2012-09-24T23:28:43-05:00",
