    [29675] = {
        {
            id = 1531792,
            score = 98,
            author = "543083",
            text = "Hey there Dalliah, what's it like in Arcatraz\nI'm a guy who doesn't know your ways\nbut lady you look so pretty, yes you do\nA'dal can't shine as bright as you, I swear it's true\n\nHey there Dalliah, don't you worry about adventurers\nI have a wormhole generator that'll take me sorta to you\nDon't close your eyes because they are coming for you\nI'll make the group wipe\n\nOh it's what you do to me\nOur first meeting was a whirlwind\nOh it's what you do to me\nWhen you first gave me a gift\nOh it's what you do to me\nWhen you shadow wave farewell\nWhat you do to me\n\nHey there Dalliah, I know times are getting hard\nPlayers run in and rofl-stomp just for rep and transmog items\nJust believe me lady, I'll find a way to buff you\nWe'll have the life we should\n\nHey there Dalliah, I've go so much left to /say\nIf my simple letter I write to you\nDoesn't end up dumped in the Nether\nI'll know 'Thrates can't aggro anymore\n\nOh it's what you do to me\nOur first meeting was a whirlwind\nOh it's what you do to me\nWhen you first gave me a gift\nOh it's what you do to me\nWhen you shadow wave farewell\nWhat you do to me\n\nAnother world seems pretty far\nBut they've got portals, mounts, and mages\nI'd walk to you if I had no other way\nMy friends are looking at me strangely\nI laugh a lot because I know\nYou and I are special this way\n\nDalliah I can promise you\nThat by the time I get through to you\nOutlands will never be the same\nAnd you're to blame\n\nHey there Dalliah\nYou heal yourself while you wait for me\nI'm going to fight and slay Deathwing\nand I'll be making history like I do\n\nYou know it's all because of you\nI want the gear so I can protect you\nHey there Dalliah here's to you\nThis one's for you\n\nOh it's what you do to me\nOur first meeting was a whirlwind\nOh it's what you do to me\nWhen you first gave me a gift\nOh it's what you do to me\nWhen you shadow wave farewell\nWhat you do to me\n.\n.\n.\napologies to Plain White T for the poor parody of \"Hey There Delilah\"",
            date = "2011-09-30T18:42:32-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29675#comments:id=1531792",
