    [29678] = {
        {
            id = 1657537,
            score = 24,
            author = "Krastopic",
            text = "A short distance northeast of the quest giver is a pool.  You will see little swirling circles on the stones.  Jump/step on one and it will hop you to the next following a progression up to the Pool of Reflection.\n\nStep into the pool and click on the Sun Pearl in your bags.\n\nQuest complete.  Click the \"?\" for the next quest in the chain.",
            date = "2012-04-22T21:05:35-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29678#comments:id=1657537",
        },
        {
            id = 1720133,
            score = 9,
            author = "seattlegamer",
            text = "Iwas told to stand in the blue water spouts five timesto complete this. After doing this ten times or so nothing happens.quest log says complete but cant turn it in. Is this a bug or am I doing something wrong?",
            date = "2012-09-26T12:39:57-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29678#comments:id=1720133",
        },
        {
            id = 1753411,
            score = 5,
            author = "1050734",
            text = "Had to turn off my Carbonite addon in order to complete this quest. Worked just fine after that.",
            date = "2012-10-29T20:06:47-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29678#comments:id=1753411",
        },
        {
            id = 1719117,
            score = 3,
            author = "Teiresias911",
            text = "If you are like me and got ahead of yourself, you might have jumped out of the Pool of Reflection after already using your Sun Pearl...  and the little rocks that hopped you up there in the first place are no longer cooperating. That means you can no longer use them to get back up the unclimbable cliff to finish the next quest, https://www.wowhead.com/quest=29679.\n\nGood news for you - I found the only spot to get back onto the cliff and into the Pool of Reflection again.  It is a spot located along the east bank at 82.1, 42.7.  Once you climb up, retrack north and to the west to finish up your quest.  Hope this helps!",
            date = "2012-09-25T19:14:16-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29678#comments:id=1719117",
        },
        {
            id = 6144012,
            score = 2,
            author = "nefox30",
            text = "The addon blocking this is Questie so all you got to do is disable that",
            date = "2025-07-16T08:05:11-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29678#comments:id=6144012",
        },
    },
    [29679] = {
        {
            id = 1657540,
            score = 7,
            author = "Krastopic",
            text = "You found the Pool of Reflection from the previous quest.  There is a little spirit running around on top of the rocks - but he really has very little if nothing to do with the quest.\n\nAround the pool you will see water spouts shooting into the air.  The trick of the quest is to get on one of these spouts before it is formed.\n\nYou will see an area of the water start to glow and boil.  A moment after that water will shoot into the air.\n\nThe best way to complete this is to stand near the single oblong stone to your right and wait for the water to glow and bubble.  Quickly stand on it before it erupts.  If you miss the chance, nothing happens.  If you get there in time, the water spout will shoot you into the air and you will get one credit toward finishing the quest.",
            date = "2012-04-22T21:11:11-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29679#comments:id=1657540",
        },
        {
            id = 5662834,
            score = 7,
            author = "maryalice",
            text = "I could NOT see the water spouts until I went to Options -> Graphics -> and changed \"Particle Density\" from Disabled to \"Good\".  Only then could I see the water spouts and complete the quest.\n\nNote: I'm on a Mac",
            date = "2023-08-04T18:53:13-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29679#comments:id=5662834",
        },
        {
            id = 1793814,
