        {
            id = 1583472,
            score = 15,
            author = "Ashkir",
            text = "In 4.3 this quest is given by T'shu (http://www.wowhead.com/npc=54674) in Underbog. You do not need any prior reputation with Sporeggar (http://www.wowhead.com/faction=970) to do these. Shrubberies are still obtained by normal means, as drops or looted from flowers through the dungeon.",
            date = "2011-11-29T16:54:28-06:00",
