    [29716] = {
        {
            id = 1701111,
            score = 34,
            author = "13930",
            text = "The pandaren cubs you need to save are not inside the Jade Witch's garden, instead they're outside, stuck to the tree barks.",
            date = "2012-08-17T20:15:13-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29716#comments:id=1701111",
        },
        {
            id = 1718597,
            score = 17,
            author = "Kemaria",
            text = "Well, I was looking up high in the trees at first, but these chubby little panda kids can't climb far or fast, it seems.  They're clinging to the tree trunks at the bottom of the trees, and sparkle faintly.  Also, look at the lamp posts along the road - some of the cubs apparently got confused and climbed those, too. :)",
            date = "2012-09-25T10:32:03-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29716#comments:id=1718597",
        },
        {
            id = 1763931,
            score = 12,
            author = "1023410",
            text = "These cubs learned what we players have known since BC when we all got flying mounts, if you're more than 3 feet off the ground, monsters leave you alone =)",
            date = "2012-11-17T19:20:00-06:00",
            sourceUrl = "https://www.wowhead.com/quest=29716#comments:id=1763931",
        },
        {
            id = 1910437,
            score = 11,
            author = "810295",
            text = "I like how the villagers are all like, \"Don't cause trouble in our peaceful village, stranger,\" and the guy you're with is like, \"Why don't you go ask around and see if anyone needs anything? *shrug*\" Meanwhile, OH YEAH, ALL OUR KIDS GOT KIDNAPPED BY A PSYCHOPATHIC WITCH.",
            date = "2013-10-20T11:39:48-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29716#comments:id=1910437",
        },
        {
            id = 1720489,
            score = 7,
            author = "bestsaif",
            text = "An Windfur:\nSo the other kids, not me, dared Shin to knock on the jade witch's front door.\nShin backed out for that but then someone, not me, double hozen dared him. And not even Shin can get out of a double hozen dare.\nHe went and knocked on that door but we didnt see what happened. Jade monster came at us and we ran away.\nI never should have dared Shin...\n\nLMFAO",
            date = "2012-09-26T16:22:53-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29716#comments:id=1720489",
        },
    },
    [29717] = {
        {
