            text = "Scared Pandaren Cub says: I tried to boot a jade monster in the head but hurt my paw.\n\nPlus a https://www.wowhead.com/item=88704 as a reward.  This is probably the most unbelievably cute quest in all of WoW-dom.",
            date = "2014-06-12T20:58:07-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29717#comments:id=1972036",
        },
    },
