    [29725] = {
        {
            id = 1657935,
            score = 99,
            author = "StansDad",
            text = "Amber will be positioned to shoot at mobs wherever you are, so don't just stand at the first shrine lighting up tigers to kill until they stop attacking or you will be there forever! Just go to each of the shrines in the area, pausing only to light up mobs who you attack along the way, and the whole scenario will play out and finish upon your return.\n\np.s. Poor Gizmo...",
            date = "2012-04-23T18:21:18-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29725#comments:id=1657935",
        },
        {
            id = 1719101,
            score = 60,
            author = "Iheartbeer",
            text = "You will run to each of the three locations, marking tigers for Amber to kill along the way.\n\nLocations of the camps:\n\nSouth East 49.61\nNorth 47.58\nSouth West 46.61\n\nCamp is at 50.63",
            date = "2012-09-25T18:56:20-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29725#comments:id=1719101",
        },
