        },
        {
            id = 1739568,
            score = 38,
            author = "Dranes",
            text = "\"I found no sign of the White Pawn at the southwestern shrine.\nHowever, I did find a friendly raccoon, who began to follow me.\nI decided to name him Gizmo.\nSully: Hey there, little buddy! I'm gonna name you Gizmo.\nGizmo: Squeak! *Gets sniped by Amber*\nSully: NO! GIZMO!\nSully: AMBER, WHY! I DIDN'T EVEN SHINE MY DAMN LIGHT!\nShortly afterward, another raccoon befriended me.\nI named him Socks, and quickly moved on.\"",
            date = "2012-10-12T12:42:47-05:00",
