        },
        {
            id = 1654955,
            score = 37,
            author = "Xarthat",
            text = "It's one of those quests where you just HAVE TO have view distance set to at least fair. If you don't, then similarly to that daily in northern Uldum, you won't see your quest objectives - which are far away enough to not register with \"poor\" distance view.\n\n(Yes, I know it says as much in the quest text now, but it won't on retail, while this comment will remain)",
            date = "2012-04-16T16:00:11-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29727#comments:id=1654955",
        },
        {
            id = 5812784,
