            author = "LucinaColford",
            text = "If you accidentally leave vehicle during this quest or otherwise disconnect, it will break with Sully falling through the floor instead of walking after clearing the first screen. Abandoning and relogging normally does nothing, but this is fixable!\n\nAfter much trial and error, i've found that clearing the first screen, logging out mid-quest, logging back in, abandoning the quest, and re-accepting fixes it.",
            date = "2024-03-29T06:28:10-05:00",
