    [29744] = {
        {
            id = 1720427,
            score = 7,
            author = "443168",
            text = "This is the first quest in the chain \"Ruins of Gan-Shi\", needed for the Jade Forest quest achievement.\n\nThis quest is obtained in the ruins slightly to the west of Sri-La village from a stone head on the ground called \"Shattered Destroyer.\"\n\nIt is surrounded by Shan'ze Spiritbinders and Stonebound Destroyers, both level 85.\n\nIt does appear as a quest on your minimap given that you are in range of it.",
            date = "2012-09-26T15:45:49-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29744#comments:id=1720427",
        },
        {
            id = 1737762,
            score = 6,
            author = "201738",
            text = "As of 10/10/12, this quest is not available. The head that starts the quest cannot be interacted with, and there are no other quest-givers in the area (beyond the Sprite corpse that gives \"The Sprites' Plight\")",
            date = "2012-10-10T17:35:37-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29744#comments:id=1737762",
        },
        {
            id = 1720638,
            score = 3,
