            text = "Starts at 48, 20 in Jade Forest",
            date = "2012-09-26T18:24:12-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29744#comments:id=1720638",
        },
        {
            id = 1753090,
            score = 3,
            author = "123042",
            text = "I think this quest doesn't make to live. The apparent evidence is\nbut you can't find any NPC named Weng in wowhead Live database.\n\nBased on the description I speculate that this NPC existed around Greenstone Village on beta; on live we don't really walk around there except 1 jade collecting quest. So I guess they moved the breadcrumb directly to the passage where we usually walk through.\n\nThe (48.7, 24.9) mentioned by rampantVyn is where the corpse of \"Outcast Sprite\" is, the corpse object starts \"The Sprites' Plight\" quest, which seems become the first step of this chain.\n\nThe (48.6, 20.6) mentioned by thenuts is where the \"Shattered Destroyer\" is, this object now seems only start the \"Simulacrumble\" quest, which is a later step in this chain.",
            date = "2012-10-29T09:21:02-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29744#comments:id=1753090",
        },
        {
            id = 1734441,
            score = 0,
            author = "1042027",
            text = "I found the quest at 48.7, 24.9",
            date = "2012-10-07T11:30:49-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29744#comments:id=1734441",
        },
    },
    [29745] = {
        {
            id = 1721524,
            score = 9,
            author = "110896",
            text = "Be careful, for some reason these neutral Outcast Sprites (http://www.wowhead.com/npc=55438) will sometimes attack you after you take down a Stonebound Destroyer (http://www.wowhead.com/npc=55288).\n\nI'm not sure if it is the reason or not, but it seems to have only happened to me when I had to work to steal aggro from them. If my first attack on a Destroyer caused them to attack me immeadiately, the Sprites left me alone. If I had to attack a few times, then they did attack me. Who knows, maybe they got mad because I stole their kill. Or it could be completely random.",
            date = "2012-09-27T08:22:16-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29745#comments:id=1721524",
