    [29747] = {
        {
            id = 1731727,
            score = 3,
            author = "sildani",
            text = "I also missed the Ruins of Gan-Shi portion for the Upjade Complete meta. This was the last quest I had completed. The next one - Simulcrumble - can be retrieved by clicking on some rubble on the ground - and broken statue. It will have an exclamation point and will be right in the same area.",
