    [29748] = {
        {
            id = 1712271,
            score = 24,
            author = "750725",
            text = "They are grey stone statues that are placed around the Terrace of Ten Thunders.  Warning, in beta - they did not sparkle, so don't ride around looking for things that sparkle.  When you mouse over them, it merely states \"Vacant Destroyer\", click on it - it will dismount you & you will destroy it.  You don't have to type /kick and target it, just right click on the vacant destroyer & you will get credit for this.",
            date = "2012-09-11T13:12:45-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29748#comments:id=1712271",
        },
        {
            id = 1718486,
            score = 24,
            author = "LifeWillEnd",
            text = "Terrible spawn rate.",
            date = "2012-09-25T08:57:26-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29748#comments:id=1718486",
        },
        {
            id = 1696819,
            score = 6,
            author = "xnihilo",
            text = "The item you get this quest from is https://www.wowhead.com/object=214871, located on the Terrace of Ten Thunders.\nIt is a stone head lying on the floor.",
            date = "2012-08-06T14:20:47-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29748#comments:id=1696819",
        },
        {
            id = 1719190,
            score = 5,
            author = "642882",
            text = "Ok guys, here is how you have to do this quest in highly populated servers and not die (bored) trying\n\nFirst of all, excuse my bad English. Ok? Let's continue...\n\nKnow the quest: The target is click on grey stone statues that are placed around the Terrace of Ten Thunders. They do not sparkle, so don't ride around looking for things that sparkle. When you mouse over them, it merely states \"Vacant Destroyer\", click on it - it will dismount you & you will destroy it. You don't have to type /kick and target it, just right click on the vacant destroyer & you will get credit for this. (ty flypnay704 for this).\n.\nMake a Group: When you click a \"Vacant Destroyer\" and get credit for this, nearby people from the group also gets credit, then it's a smart decision to have a group to distribute tasks and have greater chances of getting a \"click\".\n.\nLooking for spawning points: How to detect a spawning point? Easy, look where people are stacked. Once you have it, gathered some information about the point. Is it always the same people? Possibly they are in a group, the statue will be hard to catch unless you also stack your group right in the spawning time. Is there a group of the opposing faction? (PVP servers) They will defend their position at all costs. Be more intelligent and calculate the time to attack just before spawn, no need to win the point, just click and run.\n.\nControlling the spawn rate: The statues have 6 min (approximate) of spawn rate. Knowing this gives you and your group some control about when a statue is next to appear, when it is \"safe\" to explore for more spawning points, when attacking such opposing faction group that monopolizes a spawning point, etcetera.\n.\nMonopolize and stack: Coordinated and informed groups finish this quest in less time. If you monopolize one spawning point, the quest will take ~36 min to be complete. With two points would be 18 minutes, and 12 minutes if you control 3 points.\nBest thing to monopolize a spawning point is to stack your entire group, so you will have 5 hands and 10 eyes alert and ready for the spawn.\n\nHope this help someone!",
            date = "2012-09-25T20:44:37-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29748#comments:id=1719190",
        },
        {
            id = 1719303,
            score = 5,
            author = "278357",
            text = "How I completed this quest:\n\n1: Set alarmclock\n2: Go to sleep\n3: Wake up at 5:30\n4: Knock statues\n5: Profit\n6: Go back to sleep",
            date = "2012-09-25T23:07:46-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29748#comments:id=1719303",
        },
    },
