    [29753] = {
        {
            id = 1659759,
            score = 21,
            author = "941372",
            text = "When you throw the bottles, 1 of 3 Spirit beasts come out. Arcturis (http://www.wowhead.com/npc=38453), Ban'thalos (http://www.wowhead.com/npc=54320#comments), or Ankha. (http://www.wowhead.com/npc=54318#comments)",
            date = "2012-04-28T09:00:10-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29753#comments:id=1659759",
        },
        {
            id = 1831909,
            score = 12,
            author = "Barleduq",
            text = "These beasts aren't tameable, alas.\n\n(I did the entire quest before thinking about it, and then abandoned/redid to double check. The beast spirits can't be targetted by Beast Lore - clicking on them or their portrait does not change the mouse-hand, it still has the glow of 'spell in holding'.)\n\n(Putting the info into a top level comment because I have problems finding things in replies, so maybe other people do, too)",
            date = "2013-03-20T16:49:39-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29753#comments:id=1831909",
        },
        {
            id = 1725114,
            score = 8,
            author = "37419",
            text = "The spirit beasts will either come out friendly (green) or aggressive (red) and you need not kill the target creature first and it does not use the creature up (you can continually hit the same mob/corpse with the bottles for all eight).\n\nEdit:\nThere is no need to hit any creature/corpse with the AoE.  Just break it in the area.",
            date = "2012-09-29T20:09:17-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29753#comments:id=1725114",
        },
        {
            id = 3245208,
            score = 5,
            author = "Snowflake272",
            text = "As of Nov 3rd 2020, these are still not tamable. Even though undead can now be tamed, these can not. (Dam - I was looking forward to this) You can Beast Lore them, but comes up not tamable. Tested on my undead hunter, and tested all three possible spirits.",
            date = "2020-11-03T15:01:11-06:00",
            sourceUrl = "https://www.wowhead.com/quest=29753#comments:id=3245208",
        },
        {
            id = 1713978,
            score = 4,
            author = "Arnage",
            text = "If you throw the bottle up, in the trunk of the tree, the creature will stay there and won't be able to attack you and will evade your attacks. Useful if you want to avoid confrontation.",
            date = "2012-09-15T11:47:54-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29753#comments:id=1713978",
        },
    },
    [29754] = {
        {
            id = 1694790,
            score = 91,
            author = "1018698",
            text = "The quest bugged for me when the meter reached 100 - there were 2 npcs - one still casting and the second one took his role in cut scene - after abandoning and reacquiring the quest all was fine. As a reward you receive blue 410 ilvl gloves.",
