        {
            id = 3243737,
            score = 19,
            author = "lukesmithkaz",
            text = "This bugged for me. I'm a level 26 Hunter using Chromie Time to level. This quest should only take about two minutes to finish. If the NPC \"Shan Jitong\" appears before the quest is finished, go ahead and abandon it and try again. Shan Jitong should only appear after you get credit for finishing the quest.\n\nAbandoning the quest and restarting worked for me. Make sure there's a gold floating \"orb\" above the altar before you run back to restart the quest. Mine wasn't there the first time, and I suspect that was the issue. It appeared shortly after I abandoned the quest.",
            date = "2020-10-30T09:45:54-05:00",
