    [29755] = {
        {
            id = 2419881,
            score = 224,
            author = "Rydiak",
            text = "For high level people doing this quest for transmog purposes, if you one-shot the Stonebound Colossus you will not be able to progress in the quest.  Instead, use the Soft Foam Sword toy to greatly damage the Stonebound Colossus (without killing it), complete the mini-event, and THEN you will be able to kill Shan Jitong.",
            date = "2016-10-02T06:53:11-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29755#comments:id=2419881",
        },
        {
            id = 1719606,
            score = 60,
            author = "Sharkon",
            text = "Shan Jitong will rip your spirit out of your body and drag you to him. When this happens, you need to run back to your body and click to return to it. However, if you're quick, you can click on your body in the moment between being ripped out of it and being dragged to Shan.\n\nThe statue monster will start channeling a self-heal when you're removed from your body. Interrupt this as soon as you're back in control.\n\nShan Jitong will lose his damage immunity after a short Rp following the death of the statue.",
            date = "2012-09-26T04:09:36-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29755#comments:id=1719606",
        },
        {
            id = 1876302,
            score = 51,
            author = "ItalianGoat",
            text = "Okay here's exactly what you do, as many comments confused me.\nYou go to the area where the quest number on your map is, the temple where the Stonebound Colossus wanders. To activate the quest, begin killing the Stonebound Colossus. Shan Jitong will appear shortly after, and begin ripping your spirit out of your body. ASAP return to your body and interrupt the big guy from regenerating and kill him, and ignore Shan Jitong. Pull the Colossus toward the steps as soon as you're able, meaning Shan Jitong cannot reach you therefore he cannot pull away your spirit. Focus on killing Stonebound Colossus, and when he's a corpse, Pei-Zhi would be released, and then Jitong will exclaim, then you start attacking him; an easy kill. The quest is completed.\n\nLong story short:\n1. Go to the temple.\n2. Hit the Stonebound Colossus.\n3. ONLY attack the Stoundbound Colossus for now.\n4. Return to body asap if ripped from it.\n5. Pull the Colossus toward the steps, continue to kill.\n5. Attack Shan Jitong, kill.\n\nQuest Complete.",
            date = "2013-07-12T22:36:01-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29755#comments:id=1876302",
        },
        {
            id = 5791925,
            score = 28,
            author = "Axofa",
            text = "Make sure you use your Soft Foam Sword on this one!",
            date = "2024-02-25T20:39:00-06:00",
            sourceUrl = "https://www.wowhead.com/quest=29755#comments:id=5791925",
        },
        {
            id = 2542697,
            score = 24,
            author = "Malachi68",
            text = "No need to get rez sickness or take off your armor at high levels, just use the Soft Foam Sword (http://www.wowhead.com/item=137663/soft-foam-sword).",
            date = "2017-12-27T14:58:35-06:00",
            sourceUrl = "https://www.wowhead.com/quest=29755#comments:id=2542697",
        },
    },
