    [29757] = {
        {
            id = 1654862,
            score = 60,
            author = "Cielos",
            text = "'Now when the kids ask, \"Do you have Bottletoads?\" I can say YES!'\n\nThis quest is based off the NES game Battletoads.  Many like to prank call their local GameStop and ask if they have Battletoads, which is met with confusion or rage, depending on the frequency of the calls.",
            date = "2012-04-16T12:32:13-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29757#comments:id=1654862",
        },
        {
            id = 1696902,
            score = 59,
            author = "retro",
            text = "The Toad Eggs are from the Bubbles in The Pools of Purity, simply right click them to acquire them.\n\nIn current Build, you can do it mounted, if you can avoid the rampant Razorback Snapper (http://mop.wowhead.com/npc=56832) in the water, this can be done in less then 30seconds.",
            date = "2012-08-06T19:25:44-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29757#comments:id=1696902",
        },
        {
            id = 1719762,
            score = 25,
            author = "906980",
            text = "You are supposed to click on the bubbles that glitters in the water, can be tricky to find.",
            date = "2012-09-26T06:52:22-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29757#comments:id=1719762",
        },
        {
            id = 1719988,
            score = 24,
            author = "Dongolev",
            text = "\"Hi, this is Gamestop.\"\n\"Do you have Mists of Pandaria?\"\n\"Yes, of course.\"\n\"Great. Also, do you have Battletoads for Wii?\"\n\"Let me check my catalog... no, and screw you, kid.\"",
            date = "2012-09-26T10:21:03-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29757#comments:id=1719988",
        },
        {
            id = 1684051,
            score = 9,
            author = "Vorona",
            text = "What you have to look for is bubbling white \"air bubbles\" which you click on, the problem is that the little turtles keep aggroing on you and the spawn rate is hideously slow.\n\nA very painful quest.",
            date = "2012-07-03T12:07:58-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29757#comments:id=1684051",
        },
    },
