    [29759] = {
        {
            id = 1836650,
            score = 17,
            author = "Underwriter",
            text = "Paladins who want to find an easy-to-get match for their Tier 9 set will want to switch to their Holy spec before turning in this quest. The https://www.wowhead.com/item=90371 are a perfect match for [itemset=875].",
