    [29765] = {
        {
            id = 1718422,
            score = 35,
            author = "169714",
            text = "Well gee whizz, it didn't take long in the Jade Forest before I stumbled upon this heartstring-tugger quest...\n\nSnuff :'(\n\nedit : spelling",
            date = "2012-09-25T07:26:30-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29765#comments:id=1718422",
        },
        {
            id = 1747975,
            score = 33,
            author = "671293",
            text = "If you can't attack the mobs for this quest than you're probably friendly, honored, revered, or exalted with the Forest Hozen faction. You'll need to visit your reputation window and check the \"at war\" box for that faction in order to treat them as enemies.",
            date = "2012-10-22T13:01:15-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29765#comments:id=1747975",
        },
        {
            id = 1653863,
            score = 20,
            author = "Zillions",
            text = "Zin'Jun follows you for this quest, and comments as you complete.\nSimply kill nearby Hozen.  They have a chance of dropping the required pieces for this quest.\n\nCompleting the quest:\n\nDey done killed Snuff...\nWhat'd 'ol Snuff ever do ta dem?",
            date = "2012-04-14T14:17:45-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29765#comments:id=1653863",
        },
        {
