            text = "Quest is no longer available / possible to complete (removal of fishcatcher / skullthomper) as of build 15589.\n\nRecommend you continue the Loremaster Cho questline to finish saving Hozen from hungry crocs.",
            date = "2012-04-27T03:35:13-05:00",
