        {
            id = 1653904,
            score = 1,
            author = "Zillions",
            text = "Mobs for this quest are located south of Hellscream's Reach.\nMudflingers and Fishcatchers are found closer to Serenity Falls, while Skullthumpers are located closer to the quest hub.\n\nWhile you are doing this quest, also work on https://www.wowhead.com/quest=29821 and https://www.wowhead.com/quest=29815 to be more efficient.",
            date = "2012-04-14T15:20:24-05:00",
