    },
    [29768] = {
        {
            id = 1727374,
            score = 18,
            author = "Jollygood",
            text = "The Vermin \"boss\" at the door to the temple has a lot of health for that level.\n\nHe sends out a trail of bubbling rubble that can cause damage. If you see him burrowing, watch for that. It's an early-in-leveling introduction to the concept of Stay Out Of The Bad.\n\nIf you are alone, one way to get \"help\" is to kite him to the two villagers standing a little further down the road. They will distract him (in my case, finished him off) while you can get the mallet (a cogwheel shows you) atop a barrel near the door.",
            date = "2012-10-01T11:36:18-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29768#comments:id=1727374",
        },
        {
            id = 1748218,
            score = 13,
            author = "1048650",
            text = "In case anyone is looking for the best way to beat Raggis, start a fight with him and lead him back to the 2 guards (63.7, 75.1), and they will help you.",
            date = "2012-10-22T19:40:39-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29768#comments:id=1748218",
        },
        {
            id = 1743787,
            score = 7,
            author = "FuryWar",
            text = "Raggis doesn't actually drop the mallet you're after, but you'll want to kill him in order to get to it sitting on some boxes nearby!",
            date = "2012-10-17T03:18:49-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29768#comments:id=1743787",
        },
        {
            id = 1656854,
            score = 3,
            author = "480051",
            text = "I like the fact that your reward depends on your class. and you can only get what actually benefits you.",
            date = "2012-04-21T12:10:54-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29768#comments:id=1656854",
        },
        {
            id = 1658819,
            score = 2,
            author = "Krastopic",
            text = "Take the path southwest away from the quest giver.  Head for the brewery which is a building with a water wheel on the side.\n\nHe spawned about every 60 to 70 seconds - looks like a giant rabbit.  Group up with people - not because he is hard - but so you are not waiting forever for a crack at the beasty.\n\nEnjoy",
            date = "2012-04-25T22:50:37-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29768#comments:id=1658819",
        },
    },
    [29769] = {
        {
            id = 1774059,
            score = 4,
            author = "979563",
            text = "kill them faster.\n\nMakes sense to me",
            date = "2012-12-02T15:08:01-06:00",
            sourceUrl = "https://www.wowhead.com/quest=29769#comments:id=1774059",
        },
        {
            id = 1658816,
            score = 1,
            author = "Krastopic",
            text = "Make sure you pick up the quest under the pavillion next to the carrot patch called \"Still Good!\" - do them both at the same time.\n\nSimple quest - just kill any vermin - they are not tough unless you agro more than one and are a clothy.",
            date = "2012-04-25T22:44:06-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29769#comments:id=1658816",
        },
        {
            id = 1809076,
            score = 1,
            author = "1088524",
            text = "Most of carrots are in the Teeming Burrow (75.0, 70.8). on the Northeast side of The Rows dirt area",
            date = "2013-02-04T12:54:44-06:00",
            sourceUrl = "https://www.wowhead.com/quest=29769#comments:id=1809076",
        },
        {
            id = 5153173,
            score = 1,
            author = "DaemoniKira",
            text = "If you look behind Ji Firepaw (the person who gives you this quest) to the waterfall/pond area that https://www.wowhead.com/npc=60918 (the Water Spirit you just played with) ran off to...\n\n...you'll see that Shu is now occupying himself by using Water Spout on the https://www.wowhead.com/npc=54134 that's in the pond, shooting it high into the air just like Shu did with you in the last quest! The toad seems to enjoy the game too, as it keeps swimming to the Water Spout location! :3\n\nEdit: Upon walking closer to Shu during https://www.wowhead.com/quest=29774, I also realized that Shu is actually giggling every time the Water Spout shoots the Toad into the air! xD",
            date = "2021-04-15T19:29:29-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29769#comments:id=5153173",
        },
    },
    [29770] = {
        {
            id = 1657060,
            score = 42,
            author = "Felicat",
            text = "For those confused, as I was, you need to go through the verming den in the middle of the carrot field to reach the pumpkins.",
            date = "2012-04-21T23:34:27-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29770#comments:id=1657060",
        },
        {
            id = 1656581,
            score = 9,
            author = "Gralorn",
            text = "I found lots of carrots in the Teeming Burrow - this has 3 entrances, one  in the middle of the carrot field, one in the middle of the pumpkin field and one in the Vermin Grotto which is where you can find the pumpkins.\n\nThe turnips I found lying on the ground near... the turnip field (this is the grey field on the map).",
            date = "2012-04-20T16:49:47-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29770#comments:id=1656581",
        },
        {
            id = 1658814,
            score = 7,
            author = "Krastopic",
            text = "Before you start this Quest - make sure you have also picked up https://www.wowhead.com/quest=29769Rascals and you can complete them at the same time.\n\nAfter you pick up the quest - go straight through the building and you will see the carrot patch.  The carrots can be either picked up or by killing a Plump Carrotcruncher.  While I did find a stray Plump Carrotcruncher running around outside the burrow, most will be inside the teaming burrow.\n\nNext do the turnips which are in the next field southeast of the Teaming Burrow.  Then head east and you will find south of the pumpkin patch - the Vermin Grotto - you can farm the pumpkins there.\n\nKill any vermin along the way and you also complete \"Rascals\".",
            date = "2012-04-25T22:42:02-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29770#comments:id=1658814",
        },
        {
            id = 1656041,
            score = 3,
            author = "937612",
            text = "The carrots are also dropped from one specific type of Vermin",
            date = "2012-04-19T07:19:18-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29770#comments:id=1656041",
        },
    },
    [29771] = {
        {
            id = 1793828,
            score = 5,
            author = "Aros",
            text = "At the completion of this quest Jojo will (just like with the quest Stronger Than Reeds (http://www.wowhead.com/quest=29662)) demonstrate that he can break the planks. He will also say:\nOur crafters build the finest wooden planks. They would weather the most brutal of storms. But they are as water before the storm of my crushing skull.\nNothing made by pandaren hands can withstand me.\nHe then walks away all the way up to Mandori Village where he despawns in one of the houses. (coordinates 55,56)",
            date = "2013-01-06T18:54:30-06:00",
            sourceUrl = "https://www.wowhead.com/quest=29771#comments:id=1793828",
        },
        {
            id = 1658822,
            score = 1,
            author = "Krastopic",
            text = "Just a note for whomever is editing this.\nThis quest is part of the quest chain starting with \"The Sting of Learning\" and is given after Raucous Rousing.\n\nIt was noted in the question chain Quick Facts",
            date = "2012-04-25T23:01:38-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29771#comments:id=1658822",
        },
        {
            id = 1658823,
            score = 1,
            author = "Krastopic",
            text = "Head back to the Brewery where you killed the giant rabbit (Raggis).\nThe \"Discarded Wooden Planks\" are all around the Brewery.\n\nYou will harvest the planks two at a time.",
            date = "2012-04-25T23:04:24-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29771#comments:id=1658823",
        },
    },
    [29772] = {
