            author = "844837",
            text = "You got the second chance to\n\nBang\n\nA\n\nGong! (http://www.wowhead.com/object=180717)",
            date = "2013-10-08T04:23:17-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29772#comments:id=1906658",
        },
        {
            id = 1658821,
            score = -1,
