    [29775] = {
        {
            id = 1726480,
            score = 16,
            author = "40403",
            text = "The way you take to the Temple of Five Dawns isn't back the way you came, it's further around  the Isle. The cart is waiting at 67.8,67.2 pulled by this https://www.wowhead.com/npc=59499",
            date = "2012-09-30T19:26:25-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29775#comments:id=1726480",
        },
        {
            id = 1730062,
            score = 16,
            author = "pqee",
            text = "Shu never got in the cart. The poor guy had to walk the whole way.   Not cool Blizzard, not cool.",
            date = "2012-10-03T13:49:32-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29775#comments:id=1730062",
        },
        {
            id = 1726553,
            score = 5,
            author = "243923",
            text = "For reference, here is the dialogue spoken aloud at the end of this quest:\n\nMaster Shang Xi says:  You've returned with the spirits of water and earth. You make an old master proud.\nMaster Shang Xi says:  Wugou and Shu are welcome here. We will care for them well.\nMaster Shang Xi says:  The only remaining spirit is Dafeng, who hides somewhere across the Dawning Span to the west.\nMaster Shang Xi says:  I can carry you to the top of the temple. Ji awaits you there to lead the way.",
            date = "2012-09-30T20:44:39-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29775#comments:id=1726553",
        },
        {
            id = 1658828,
            score = 1,
            author = "Krastopic",
            text = "The cart works fine now.\n\nThe cart is sitting to the NE of the Quest Giver on the grass by the fork in the road.  It has a yack looking creature pulling it.  Takes you to Mandori Village.\n\nWheeeee fun ride....",
            date = "2012-04-25T23:15:17-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29775#comments:id=1658828",
        },
        {
            id = 6144533,
            score = 1,
            author = "Haxan",
            text = "Do I have to take the cart? I set my HS to the temple, will the quest complete if I HS there instead?",
            date = "2025-07-17T08:12:17-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29775#comments:id=6144533",
        },
    },
    [29776] = {
        {
            id = 1719108,
            score = 23,
            author = "916574",
            text = ", give me a hug! Our parting was not so long this time - I quite prefer it that way!\n /hug him and he hugs you back :D",
            date = "2012-09-25T19:04:21-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29776#comments:id=1719108",
        },
        {
            id = 1719286,
            score = 16,
            author = "raistlyn",
            text = "I always respond to NPCs, whether they bow, salute me, laugh, etc. I respond with what they were doing back to them.\n\nSo imagine my delight when he says, \"give me a hug!\" and I do so, and I see Ji Firepaw warmly hugs you back. I had never seen anything so interactive, so I sat and smiled for quite some time.",
            date = "2012-09-25T22:41:57-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29776#comments:id=1719286",
        },
        {
            id = 1658834,
            score = 9,
            author = "Krastopic",
            text = "You get a free ride up the building to the top.  Exit to the west and follow the path over the bridge.  Go past a building (on your left) and the road turns slight right and you pass over a second bridge.  If you want stand on top of the bridge and oooo and ahhh about the beautiful vistas in Pandaria.\n\nOnce over the bridge, you will Discover the \"Ridge of the Laughing Winds\"\nStay on the path when it forks and go under the archway.  You are now in Morning Breeze Village.\n\nGo past the well, and take the dirt path to the left down to the lake and the dock.  The quest giver is on the dock.",
            date = "2012-04-25T23:22:46-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29776#comments:id=1658834",
        },
        {
            id = 1925872,
            score = 2,
            author = "1114048",
            text = "Is there any way to get back to Morning Star Village or the upper part of the temple after you've taken the balloon ride to talk the turtle and been dropped off?  The whirwind / torando no longer exists, and nobody's offering a ride.  There was an NPC up there I meant to check out, a trainer or something, I didn't realize I was taking a one-way exit out - wasn't done exploring yet!  Any way to get back?",
            date = "2013-12-14T11:22:33-06:00",
            sourceUrl = "https://www.wowhead.com/quest=29776#comments:id=1925872",
        },
        {
            id = 5265246,
            score = 2,
            author = "Handsomfreddy",
            text = "If you've forgotten how to get to Morning Breeze Village, there is a square teleportation pad to the left of the artifact forge, right by the door that leads to tak-tak, that will transport you; wish we could fly in this zone :(",
            date = "2021-10-11T19:39:21-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29776#comments:id=5265246",
        },
    },
