    [29778] = {
        {
            id = 1718897,
            score = 61,
            author = "940955",
            text = "Peel banana first, eat second.\nWet fur not fun to sleep on.\nDon't roll in own poo unless you want to smell like poo all day.\nSteal a banana from a hozen, expect an angry hozen.\nPoo not good to eat, but very good to throw.\nMouth only hole that banana go in.\nDon't throw banana peel where going to walk.\nFirecracker for throwing, banana for eating.\nDon't pull own tail when there are other tails to pull.\n\n(I will try and compile whatever I see on this page)",
            date = "2012-09-25T15:25:14-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29778#comments:id=1718897",
        },
        {
            id = 1654348,
            score = 56,
            author = "Easo",
            text = "\"Mouth only hole that banana go in.\"\nOh, Blizzard...",
            date = "2012-04-15T11:46:47-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29778#comments:id=1654348",
        },
        {
            id = 1726463,
            score = 18,
            author = "Kurasu",
            text = "\"Don't pull own tail when there are other tails to pull.\"\n\nI kinda liked that one. It's got a weird sort of wisdom!",
            date = "2012-09-30T19:00:59-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29778#comments:id=1726463",
        },
        {
            id = 1657922,
            score = 7,
            author = "941372",
            text = "Oh, yea? Here's one I came across: Poo not good to eat, but very good to throw.",
            date = "2012-04-23T17:35:34-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29778#comments:id=1657922",
        },
        {
            id = 2292345,
