    [29800] = {
        {
            id = 1663931,
            score = 19,
            author = "Krastopic",
            text = "Head North North East of the quest giver to find the cart to take you back to the temple.  Beats walking I guess.\n\nThe cart is straight east from the quest giver on the stone road near the alliance tent.\n\nI suppose you could walk back too if you like - but the cart is noticably faster than walking.\n\nThe cart drops you off in front of a long set of stairs - climb to the top and turn in the quest.\n\nAn important event happens at this point - you get to decide as a Pandarin whether to join the Alliance or the Horde.",
            date = "2012-05-07T14:33:25-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29800#comments:id=1663931",
