    [29821] = {
        {
            id = 1752407,
            score = 123,
            author = "Elysianphoenix",
            text = "In order to save everyone a headache:\n\nThis\n (http://img.photobucket.com/albums/v652/LunaMorgana/WoWScrnShot_102812_133113.jpg) is where you use the boots at 24:27 near the lowest waterfall.\n\nAlternate view (http://img.photobucket.com/albums/v652/LunaMorgana/WoWScrnShot_102812_133501.jpg)",
            date = "2012-10-28T07:36:03-05:00",
