        },
        {
            id = 1734935,
            score = 17,
            author = "Smallfoot",
            text = "No comments on the reference (http://www.youtube.com/watch?v=oPwrodxghrw)?\n\nIt took me no more than half a second to get the reference in the title of this quest.  Would you believe it (http://www.youtube.com/watch?v=0Hd2e_tRBlY)?  Half a second!\n...\nWould you believe half a minute?\n...\nHalf an hour?\n.....\nWhat if I told you I only realized it after playing through this area on my second alt?",
            date = "2012-10-07T20:36:02-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29821#comments:id=1734935",
