    [29822] = {
        {
            id = 1825775,
            score = 54,
            author = "CallMeNoa",
            text = "If you're a troll, Lorewalker Cho has an extra line of dialogue when he shows up:\n\n\"As I live and breathe - an actual troll! You look just as the stories describe.\"\n\nThis is, of course, because the Zandalari trolls were ancient allies of the old mogu empire that had enslaved the pandaren.",
