        {
            id = 1671811,
            score = 37,
            author = "Zillions",
            text = "To do this quest, first find the NPC https://www.wowhead.com/npc=55622 and kill him.  He is quite easy to kill; make sure you move out of the way of the Barrel Toss and Bananarang.\n\nWhen killed, he grants the buff https://www.wowhead.com/spell=124013. All hozen in the Jade Forest now tremble at the sight of you; making the remaining objectives of this quest quite easy!",
            date = "2012-05-30T18:40:35-05:00",
