    [29823] = {
        {
            id = 1718964,
            score = 80,
            author = "610294",
            text = "way better love story than twilight",
            date = "2012-09-25T16:17:17-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29823#comments:id=1718964",
        },
        {
            id = 5903203,
            score = 68,
            author = "Daemonette",
            text = "Remix pandaria, War within prepatch, 11.0.0.55818.\n\nRico is again almost one-shotted down. I have leveled 5 horde chars in pandaria remix and this quest was an eezy breezy, but now after war within prepatch, it is once again really difficult due to Rico being paper.\n\nSo check all previous comments and tips about using max range, kiting, and avoiding getting hit even once.\n\nI tried doing this 5 times, was not able to finish. Abandoned and moved on. Every time I could not even finish the mob before next one appeared.",
            date = "2024-07-24T07:23:03-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29823#comments:id=5903203",
        },
        {
            id = 1672575,
            score = 41,
            author = "Zillions",
            text = "For this part of the quest, you should immediately be given special \"vehicle\" abilities: https://www.wowhead.com/spell=80182 and https://www.wowhead.com/spell=83012. (If you do not have a special abilities bar, abandon the quest).\n\nOnce you yell \"I'll save you, Kiryn!\" then run up the path ahead of you to the net.  Speak to Kiryn, and it will start the encounter.\nUse your #3 ability once the mob gets in melee range to knock them back.\nUse your #4 ability as a ranged attack.\n\nThe quest text at the end is priceless:\nWhen I was done fightin', I went up to Kiryn to ask for my... reward.\nShademaster Kiryn says: \"Riko, you... you saved my life.\"\nRiko says: \"So... uh... can Riko get a kiss?\"\nKiryn says: \"Of course. Let me just take off my mask...\"\nRiko yells: WHAT THE OOK IS WRONG WITH YOUR FACE? YOU'RE... YOU'RE JEEKIN' DEAD? AHHHHHH!\n\nWhen you speak to him to turn in, he says \"Yeah, I ran away. So blikkin' what? If it weren't for me, Kiryn would be dead. Oh, wait... she's already dead... already...  Go away! Riko's head hurts!\"",
            date = "2012-06-02T04:25:58-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29823#comments:id=1672575",
        },
        {
            id = 1735020,
            score = 31,
            author = "Smallfoot",
            text = "I actually zoomed into first person for the end of the quest to see her face.  The hilarity of Riko's reaction was bumped up a good 100% in that point of view as the whole screen picked up and ran.",
            date = "2012-10-07T23:17:27-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29823#comments:id=1735020",
        },
        {
            id = 1718700,
            score = 20,
            author = "Vallix",
            text = "Kiryn is in the net next to the plane (49, 70)",
            date = "2012-09-25T12:18:41-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29823#comments:id=1718700",
        },
    },
    [29824] = {
        {
            id = 1718217,
            score = 138,
            author = "426474",
            text = "This quest is unusual for wow player.\n\nOn first scene screen you see some marks above targets head.\n\nOn second scene screen there are another seven targets to hit by, so make sure you got all of them. There is one hidden at top middle by some tree leafs.\n\nOn third screen you have to shoot 3 barrels: left of the temple (bottom), one middle screen fountain and last top building right side of entrance.\n\nAfter that there will be lovely \"hit as fast as you can\" all the targets game.\n\nDo not abandon the quest, just try to strain your eyes :)",
            date = "2012-09-25T02:33:18-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29824#comments:id=1718217",
        },
        {
            id = 1727650,
            score = 108,
            author = "Trogthor",
            text = "\"I on way, Kiryn! And I don't care about you weird dead face!\"\n\nI melted. Who'da thunk a corpse and giant monkey could be so sweet together?",
            date = "2012-10-01T15:36:01-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29824#comments:id=1727650",
        },
        {
            id = 1759773,
            score = 106,
            author = "1053797",
            text = "So I made an account specifically to comment on this quest.  This is for anyone having trouble taking out all the onslaught of Jinyu after Riko goes over to Kiryn while she is in the net.  Two easy steps you can finally beat this quest!  First, turn on enemy nameplates.  This makes finding the hidden jinyu that could take you out so much easier.  Second, go into \"Interface\", find where it says \"interact with mouseover\", and assign it to a key on your keyboard.  I used F1 because it was never assigned to anything else.  After doing this, I finished the quest in one try.\n\nSimply move your mouse over all the Jinyu (which you can now see since you have nameplates turned on) and spam the crap out of whatever button you assigned \"interact with mouseover\" (F1 in my case).  After dying countless times during the final showdown, this worked the first time I tried it.  I hope this helps someone who might be having as much trouble as I did!",
            date = "2012-11-09T11:41:16-06:00",
            sourceUrl = "https://www.wowhead.com/quest=29824#comments:id=1759773",
        },
        {
            id = 1713516,
            score = 55,
            author = "NobodyYouKnow",
            text = "So. This quest says the alliance recruited Fishmen while horde recruited monkeys, and worse yet, the horde are outnumbered 30 to one. I guess the horde has to stop... *puts on sunglasses* monkey'ing around. YEAH!",
            date = "2012-09-14T09:51:54-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29824#comments:id=1713516",
        },
        {
            id = 1718592,
            score = 49,
            author = "895707",
            text = "I had a similar problem with Riko not showing up, and the whole event getting stuck. Relogging fixed the issue nicely.\n\nJust make sure to quit out of the event first before relogging, otherwise you will log in right by where the event was supposed to be happening.",
            date = "2012-09-25T10:27:36-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29824#comments:id=1718592",
        },
    },
    [29827] = {
        {
            id = 3179912,
            score = 31,
            author = "Weleen",
            text = "this quest is currently bugged,in order to do it dont interrupt cinematic and turn off addons that skip cinematics auto",
            date = "2020-01-04T16:39:53-06:00",
            sourceUrl = "https://www.wowhead.com/quest=29827#comments:id=3179912",
        },
        {
            id = 1659066,
            score = 21,
            author = "Zillions",
            text = "After accepting the quest, exit the building and look to your left.  There should be a crate (Recovered Supplies) that is attached to a https://www.wowhead.com/npc=55676.\nWhen you mouse over the crate, you get an 'enter vehicle' command that does a brief cinematic, then you can work on the quest objectives.\n\nIn the drone, you have 2 abilities:\nhttps://www.wowhead.com/spell=104463\nhttps://www.wowhead.com/spell=104527\n\nThe first, https://www.wowhead.com/spell=104463 is attached to #1 key binding, and is the single-target ability. Use this to 'pick off' Hozen one by one.\nThe second, https://www.wowhead.com/spell=104527 is attached to #2 key binding, and is your AOE on a 12-second cooldown.\n\nTo most easily complete this quest, single-target until you automatically fly into an encampment, then use your AOE ability when you are flying through the very center.\n\nGood luck!",
            date = "2012-04-26T13:17:23-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29827#comments:id=1659066",
        },
        {
            id = 1912397,
            score = 20,
            author = "911103",
            text = "If you can't enter into https://www.wowhead.com/npc=55674, disable \"Hide in-game cinematics\" option in Deadly Boss Mods addon (type \"/dbm\" in chat -> Options -> Hide Blizzard -> Hide in-game cinematics -> Disable) ;)",
            date = "2013-10-27T04:26:06-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29827#comments:id=1912397",
