    [29887] = {
        {
            id = 1845530,
            score = 27,
            author = "Boonie01",
            text = "Just did this on my 3rd toon (the first 2 taking in excess of 500 kills between them to complete the quest) and noticed the mobs have a cast called Loot Toss (http://www.wowhead.com/spell=116226#). I was intrigued and starting interrupting it and found the mobs dropped the quest items first go, only had to kill 5 or 6 of them.\n\nNeed some people to confirm but this may take the pain out of this particular quest.",
            date = "2013-04-21T11:28:44-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29887#comments:id=1845530",
        },
        {
            id = 1657176,
