    [29890] = {
        {
            id = 1719049,
            score = 191,
            author = "Vlad",
            text = "If you have issues with some addon, you can use this code (when the vehicle bar is visible) and it will tell you to push the left or right buttons, indicating this by \"\" arrows in the chat, it's pretty easy and you don't have to relog and disable/enable your addons, hurray!\n/run if not FYC then FYC=CreateFrame\"Frame\"end local i,p,m=0,\"player\"FYC:SetScript(\"OnUpdate\",function(s,e)i=i+e if i>1 then i=0 m=UnitPowerMax(p,10)if m>0 then print(UnitPower(p,10)/m\"or\"<\")else s:SetScript(\"OnUpdate\",nil)end end end)\nIt will automatically disable the messages when the power used by the quest is no longer present, you have to paste the script again if you have to do it again (or paste it too early).",
            date = "2012-09-25T17:55:40-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29890#comments:id=1719049",
        },
        {
            id = 1653398,
            score = 41,
            author = "TheBobZ",
            text = "Upon starting this quest your normal action bar should dissapear and you'll gain the \"vehicle\" bar; you'll have a left arrow and a right arrow, essentialy you will use these to try and keep your 0 -100 bar as close to 50 as possible; if you do reach 0 or 100 you will fail",
            date = "2012-04-13T16:18:14-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29890#comments:id=1653398",
        },
        {
            id = 1723243,
            score = 24,
            author = "1037501",
            text = "The quest is not very clear about how to turn it in. After completing your meditation, you enter a dream sequence where you see Prince Anduin flee up a hill. If you check your map, you will see instructions to turn in the quest to Prince Anduin at the Cave of Sorrows. Do NOT go into the cave. The path the Prince took is about 10 feet to the left of the cave entrance. Follow that path up and behind the cave, turn in your quest and pick up three more quests that require you to go into the cave.",
            date = "2012-09-28T15:15:42-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29890#comments:id=1723243",
        },
        {
            id = 5663703,
            score = 20,
            author = "Gobbogossip",
            text = "If you are having UI issues, you will need to ensure you have the VEHICLE BAR and ENCOUNTER BAR enabled (these are 2 separate bars).\n\nI had my ENCOUNTER bar layered behind the VEHICLE bar and couldn't see it.  You can reposition these bars (even if using an addon like Bartender) using default UI Edit mode.",
            date = "2023-08-07T06:04:15-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29890#comments:id=5663703",
        },
        {
            id = 1913414,
            score = 17,
            author = "934836",
            text = "\"I am sorry, that did not alarm you, did it?\"\n\nI CAN'T DO THAT YET. THAT SPELL IS RECHARGING. I CAN'T DO THAT YET.",
            date = "2013-10-30T17:26:28-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29890#comments:id=1913414",
        },
    },
    [29891] = {
        {
            id = 1770375,
            score = 238,
            author = "241109",
            text = "If you can't get the Mist Horror to spawn here's the solution:\n\n1. First leave the zone and come back\n\n2. When you enter the area with the Mist Creepers you should get a buff and the edges of your screen should glow orange. If not, disable all your addons and repeat step 1.\n\n3. There are sections of orange cloud that can be right clicked (your cursor should change and have an orange border). Right click one of these cloud nodes and the Mist Horror should spawn.",
            date = "2012-11-28T15:58:38-06:00",
            sourceUrl = "https://www.wowhead.com/quest=29891#comments:id=1770375",
        },
        {
            id = 1777517,
            score = 49,
            author = "DarkNomad",
            text = "\"This appears to be a known issue at the moment and our QA department is looking into it. For now, once you have killed the 8 required Mist Creepers, leave the Amberfly Bog area then go back.\n\nOnce you enter the Amberfly Bog area again you'll have the Gathering Mist buff which will allow you to see and interact with the Inconspicuous Mist and summon the Mist Horror to complete the quest.\"\n\nBlue post by Vrakthris. This worked for me.",
            date = "2012-12-08T02:36:08-06:00",
            sourceUrl = "https://www.wowhead.com/quest=29891#comments:id=1777517",
        },
        {
            id = 1777967,
            score = 18,
            author = "924679",
            text = "If you are having trouble locating the Mist Horror here's what you need to do.\n\nHearth or leave the zone.\nCome back into the zone and you should get the quest buff \"Gathering Mist\".\nKill the 8 Creepers and then the Horror will spawn.\n\n** Steps for if you have already killed the 8 Creepers WITHOUT the buff**\n\nHearth or leave the zone\nCome back into the zone and you should get the quest buff \"Gathering Mist\".\nKill 1 Creeper which should then immediately spawn the Horror.\nDrop Horror.\n?\nProfit.\n\nHope this helps.",
            date = "2012-12-08T20:04:59-06:00",
            sourceUrl = "https://www.wowhead.com/quest=29891#comments:id=1777967",
        },
        {
            id = 1790837,
            score = 13,
            author = "988712",
            text = "I have ran into the issue where the Mist Horror fails to spawn a few times now. Each time all I do is go and turn in the other 2 quests and when I walk back out to kill a Mist Creeper it appears.\n\nThis has worked for multiple people that I have played with.",
            date = "2013-01-01T18:49:00-06:00",
            sourceUrl = "https://www.wowhead.com/quest=29891#comments:id=1790837",
        },
        {
            id = 1793379,
            score = 9,
            author = "Nekrotik",
            text = "Very poor quest text on this one. To summarize how to do this quest:\n\n1) Kill 8 mist creepers. You should see a \"mist\" effect fill your screen.\n2) If you don't see the mist, don't bother killing more creepers. Instead, run back to the quest giver and then return to the bog.\n3) This will force the mist effect to appear. Move your cursor to the small spot in the center of your screen where your hand cursor turns yellow.\n4) Click and the Mist Horror will appear. He is an easy kill and the heart has a 100% drop chance.\n\nGood luck!",
            date = "2013-01-06T00:15:56-06:00",
            sourceUrl = "https://www.wowhead.com/quest=29891#comments:id=1793379",
        },
    },
    [29892] = {
        {
            id = 1978683,
            score = 7,
            author = "868994",
            text = "Tip: There's a group of 5 Bog Crocolisks just South of Cho's home, on the shore. Might be a place to farm them for the eyes if the main area is full of other people.",
            date = "2014-07-07T15:45:11-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29892#comments:id=1978683",
        },
        {
            id = 1723739,
            score = 5,
            author = "mortey",
            text = "This part of 3 quests is terrible compared to \"Potency\" and \"Hue\". The other took less than 5 minutes for me to complete...combined while \"Body\" is taking quite a while since the drop rate is so low.",
            date = "2012-09-28T23:34:46-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29892#comments:id=1723739",
        },
        {
            id = 2363002,
            score = 3,
            author = "kerrymayall",
            text = "Just when you thought quests with low drop rates were a thing of the past.",
            date = "2016-08-08T04:19:54-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29892#comments:id=2363002",
        },
        {
            id = 1844543,
            score = 2,
            author = "Endek",
            text = "I combined the https://www.wowhead.com/quest=29892 quest with two other quests, https://www.wowhead.com/quest=29893 and https://www.wowhead.com/quest=29891 as the quests are all located in the same area.\n\nYou are looking for the Bog Crocolisk's https://www.wowhead.com/npc=54558 which can be found around coordinate 55:89 (slightly N.E. of the quest giver https://www.wowhead.com/npc=56287 )\n\nWhen the Crocolisk's are located, take them down and some of them will drop the  https://www.wowhead.com/item=76107 which you need 5 of to complete the quest.\n\nThe drop rate for our little group seemed to be around 40% (2 to 3 Crocolisk's taken down per 1 drop), so when you combine all three quests, you will most likely complete Hue and Potency first if taking down the relevant quest mobs as you move around the area.\n\nIf you are in a group, it seems that other group members can also loot the Pristine Crocolisk Eye's from the Crocolisk.\n\nHave fun out there :)",
            date = "2013-04-18T07:32:54-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29892#comments:id=1844543",
        },
        {
            id = 1846491,
            score = 1,
            author = "Mormolyce",
            text = "\"Do you have crocolisks where you're from?\"\n\nYes, somehow they are absolutely everywhere. Even Draenor.",
            date = "2013-04-24T06:57:14-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29892#comments:id=1846491",
        },
    },
