    [29900] = {
        {
            id = 1657978,
            score = 19,
            author = "StansDad",
            text = "After spending some time searching around for a small sparkling scroll I could pick up and put in my pocket I finally realised it was actually a huge (non-sparkly) banner thingy hanging on the right hand wall at the top of the cave, so big it looks more like a tapestry than a \"scroll\".",
            date = "2012-04-23T22:15:48-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29900#comments:id=1657978",
        },
        {
            id = 2252723,
            score = 13,
            author = "423524",
            text = "The first thing to remember is that the entirety of the quest objectives are inside of the cave.\n\nThe cave entrance is /way 66.15 82.17 on the ground facing the east direction\n\nAfter using the gears on the first fountain after entering the cave then face the south direction and proceed up further into the cave to get the rest of the fountains and the scroll.",
            date = "2015-09-15T18:50:19-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29900#comments:id=2252723",
        },
        {
            id = 1657209,
            score = 9,
            author = "Catixie",
            text = "Located in the back of Den of Sorrow.\n\nKill the shade and then loot the Song of the Vale scroll that is located on the cave wall.",
            date = "2012-04-22T06:17:50-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29900#comments:id=1657209",
        },
        {
            id = 1862486,
            score = 8,
            author = "849382",
            text = "The scroll reads:\n\nThere is a valley where dreamers sleep,\nWhere flowers bloom and willows weep,\nWhere loamy earth springs life anew,\nAnd waters sparkle, clear and blue,\nWhere every hearth brings peaceful ease,\nAnd beauty sings on every breeze.\n\nHere the Sacred Pools spring pure\nHere, seek any who desire cure\nHoly, nature, powers divine,\nTurn death to life, death to life.",
            date = "2013-06-03T21:51:26-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29900#comments:id=1862486",
        },
        {
            id = 1718301,
            score = 5,
            author = "edessa",
            text = "You have to kill the Shade of Ling Heartfist (http://www.wowhead.com/npc=56441) for the wall scroll to spawn.  It's big and white.",
            date = "2012-09-25T04:54:39-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29900#comments:id=1718301",
        },
    },
    [29901] = {
        {
            id = 1675968,
            score = 37,
            author = "selvin",
            text = "*This is not the prince you were looking for* /jedi prince hand wave",
            date = "2012-06-12T11:58:07-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29901#comments:id=1675968",
        },
        {
            id = 1721826,
            score = 15,
            author = "Berrenger",
            text = "There is a small error in the tracking text for this quest:\n\n\"Return to Admiral Taylor at Glassfin Village in the Jade Forest.\"\n\nGlassfin Village is actually Pearlfin Village. It was likely renamed in the beta after Jade Forest was removed and revamped.",
            date = "2012-09-27T15:36:23-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29901#comments:id=1721826",
        },
        {
            id = 1792157,
            score = 7,
            author = "DASD6",
            text = "Can anyone tell me where or how this chain begins?",
            date = "2013-01-03T23:01:07-06:00",
            sourceUrl = "https://www.wowhead.com/quest=29901#comments:id=1792157",
        },
        {
            id = 1837527,
            score = 6,
            author = "NikNovi",
            text = "This quest exists, but quest chain is incorrect. Quest is autogiven at Den of Sorrow after completing the quests in the cave.",
            date = "2013-04-01T09:05:48-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29901#comments:id=1837527",
        },
        {
            id = 1880105,
            score = 6,
            author = "365918",
            text = "This is the dialogue exchanged in the little roleplay event as you pick up this quest...\n\nAnduin: I am sorry but I cannot go back just yet. I've decided to search for the vale. I must find the Sacred Pools and study their healing powers.\nSully: Prince Anduin, we've come to take ye home. Come quietly, now.\nAnduin I'm sorry, but I won't. I'm sure you understand my reasons.\n*Anduin Mind Controls Sully*\nSully: Eh? Oh... uh... you're absolutely right, Prince Anduin. You are free to go as you please.\nAnduin (to his Pandaren friends): Come on, let's go.\n*Anduin and his friends leave*\nAmber: Sully! How could you just let him go?\nSully (snapping out of it): Eh? What happened?\nAmber: You silly dwarf, he mind-controlled you! Now he's gone!\nSully: Whaaa? I can't believe he did that ta me.\nAmber: I hope you're ready to explain this to Admiral Taylor.\nSully: Cheeky little bugger. Didn't think he had it in him.",
            date = "2013-07-24T01:00:16-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29901#comments:id=1880105",
        },
    },
    [29903] = {
        {
            id = 1674324,
            score = 27,
            author = "Meili",
            text = "A quick tip for this quest;\n\nLook at the weapons the Aqualytes have.\n\nDaggers: Give him a dagger\nSword: Give him a shield\nRed Staff: Give him a healing prayer\nBlue Staff: Give him a staff\n\nThat way you won't have to try all the weapons and it makes the quest go by so much quicker :)\nG'luck!",
            date = "2012-06-07T10:40:52-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29903#comments:id=1674324",
        },
        {
            id = 1675973,
            score = 13,
            author = "selvin",
            text = "Apparently the alliance is skimping out on these guys since all they're doing is giving them cast off level 60 gear that's been sitting in the attic for years.",
            date = "2012-06-12T12:13:12-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29903#comments:id=1675973",
        },
        {
            id = 2258975,
            score = 13,
            author = "1533794",
            text = "I had way too much fun giving them the wrong weapons.\n\n\"This isn't a weapon! It's just a book!\"\n\"How do I swing this thing? Ouch!\"\n\"Ow... that was an eye. Yes, definitely an eye.\"",
            date = "2015-09-30T10:39:51-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29903#comments:id=2258975",
        },
        {
            id = 1839859,
            score = 10,
            author = "Johnnycakes13",
            text = "Random NPCs found around Pearlfin Village. Look for chat bubbles on your mini map.\n\nDaggers:\n\"I'm quick and fast. Put me behind and enemy, and they won't even see me coming.\"\n\"I never meet an enemy head on. I prefer to use my wit.... and a number of stealthy tricks\"\n\"Being small has its advantages, I can sneak just about anywhere\"\n\nBook of Healing Prayers:\n\"In your land, is it true that healers accompany warriors onto the battlefield? If only I had better tools, perhaps I could do the same\"\n\"From a young age, I have been drawn to the healing arts\"\n\"There are too few who care for the wounded from battle. If I had the skill I would certainly join them.\"\n\nShield:\n\"I am a strong jinyu. I can take the brunt of many attacks without fear\"\n\"My duty is to protect my people. If I must be on the front lines, then I will gladly do so.\"\n\"My sword is quick and my feet steady. My enemies must deal with me first before attacking my allies\"\n\nSpellcaster's Staff:\n\"I have had basic warrior training, But no one knows that I have more skill with spellcasting\"\n\"I prefer to shape the properties of water and unleash them against my enemies\"\n\"I am terrible with a spear. I much prefer ranged combat.\"",
            date = "2013-04-06T16:58:30-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29903#comments:id=1839859",
        },
        {
            id = 2361603,
            score = 6,
            author = "Pandaku1500",
            text = "After giving the healer a staff and him saying \"I know we all look alike to you, but I'm a healer, not a mage\" and \"how will this weapon heal the injured?\" and also having a lack of spell casters, I got curious, so:\nTanks:\n\"I would prefer sturdier weapons than this.\" \"I need something for protection, not this.\" \"that would be for a healer, not me.\" \"How do I swing this thing? Ouch!\" \"This... this is a weakling's weapon! I want something bigger!\"\n\"This shield is just what i need, thank you.\"\n\nHealers:\n\"I can't use that, I'm looking to expand my healing knowledge.\" \"How will this weapon heal the injured\" \"I don't think this shield is for me.\" \"I know we all look alike to you, but I'm a healer not a mage.\" \"Ouch! Those blades are sharp!/ Ow, that was an eye. Yes, definitely an eye.\"\n\"So much knowledge, I must study this imidiately.\"/ \"Such a sacred text. I will waste no time\"\n\nMage:\n\"I cannot use this, (race).\" \"This object is useless to me.\" \"My skills are better for offense, not defense\"\"I'm sorry, but i do not heal.\" \"These daggers are little use to me.\"\n\"I should begin training immidiately.\"\n\nDPS:\n\"How will I stab my enemies with this?\" \"No no, no nearly sharp enough\" \"How can I stealth around carrying a giant shield?\" \"This isn't a weapon, it's just a book!\" \"Too big, not pointy enough, I need something small and sharp\"\n\"These daggers are perfect for stabbing.\"",
            date = "2016-08-04T17:00:34-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29903#comments:id=2361603",
        },
    },
    [29904] = {
        {
            id = 1658410,
            score = 16,
            author = "xnihilo",
            text = "The quest is quite simple: kill 24 wildlife in the forest while you 'teach' the Jinyu how to fight. In practice this just means you have to kill wildlife. The Jinyu will assist in fighting and level up every time you kill something. After a couple of kills a different Jinyu class will come and be trained by you. This goes on until you've killed 24 wildlife.\n\nThe Mistweave Adept (healer) says:\nGreetings, ! Before I join my brothers in battle, I must practice the healing arts.\nHow do I use this thing?\nHey, I think I'm getting the hang of this.\nHey, this isn't so bad.\nI feel stronger than before.\nThank you, . I have had enough training.\n\nTidestriker Adept (Rogue) says:\nMy blades are sharp, but my skill is unhoned. I am ready to learn, .\nI think I learned something new!\nHey, we're not doing so bad.\nThe fight isn't over yet!\nI feel stronger than before.\nFight hard! Press onward!\nThank you for your help, . My daggers will cut through my enemies.\n\nWaveguard Adept (Tank) says:\nLet me lend you my shield, . Allow me to protect you, so that I may better protect my village!\nThis training is really helping.\nI think I understand now.\nI'm ready for anything!\nWith this shield and sword, I will protect my friends and family.\n\nWatershaper Adept (Mage) says:\nTeach me, ! I will bend the forces of water to destroy our foes!\nI feel stronger than before.\nThe secrets of the waters are now known to me. I will use these gifts to help the village.\n\nIf only the average player learned to play their class so quickly ;)",
            date = "2012-04-25T00:51:00-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29904#comments:id=1658410",
        },
        {
            id = 1851338,
            score = 14,
            author = "Kaelynath",
            text = "So, I decided to embark upon this quest and thankfully, a few Jinyu happened to group up with me for it. But I have to be honest, they're fairly awful groupmates to have.\n\nThe Rogue and Mage do awful DPS.\n\nThe healer doesn't cast until you're almost dead, or not at all.\n\nThe tank can't hold threat.\n\nI feel like I just carried all four of them, and that they only used me to level!\n\n0/10, WOULD NOT GROUP AGAIN.",
            date = "2013-05-08T20:41:10-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29904#comments:id=1851338",
        },
        {
            id = 1675969,
            score = 5,
            author = "selvin",
            text = "Annoyingly, for hunters right now when ever a new trainee comes your pet is dismissed.",
            date = "2012-06-12T12:04:04-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29904#comments:id=1675969",
        },
        {
            id = 1747543,
            score = 3,
            author = "Catalyst8487",
            text = "Fastest way to do this quest is to attack the mobs in the caves.  Typically there is 2-4 of them in each cave, making this very quick.",
            date = "2012-10-21T23:59:16-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29904#comments:id=1747543",
        },
        {
            id = 2233807,
            score = 1,
            author = "Coffeegirl",
            text = "For some reason my guardian \"waveguard Adept\" kept leveling up with every second creature i killed. He will level from 83 to 85 and then he will look like he levels again, but he actually resets to lvl 83 and it keeps happening again and again. So strange :P",
            date = "2015-08-17T16:06:10-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29904#comments:id=2233807",
        },
    },
    [29905] = {
        {
            id = 1781243,
            score = 7,
            author = "1064301",
            text = "This is good for finishing another quest, too. The 4 Jinyu that team with you remain after the conditions of this quest are met.  This is ideal for remaining in the field of combat, not only to farm green drops, cooking items, and windwool cloth (as well as some nice coin along the way), but also to complete the monthly Darkmoon Faire quest \"Test Your Strength\".  I was able to clear 250 kills for the quest in a relatively short amount of time.\n\nI'm tempted to not turn in the quest, so that I can return later to farm and run the quest monthly for the quest, but I think that might inhibit the storyline progress.",
            date = "2012-12-14T10:28:00-06:00",
            sourceUrl = "https://www.wowhead.com/quest=29905#comments:id=1781243",
        },
        {
            id = 1663828,
            score = 1,
            author = "959726",
            text = "Where does this continue to? I'm assuming you don't just leave Anduin out on some strange island with strange people and never see him again. Does anyone know where I can pick up the rest of Anduin (alliance) quest chain?",
            date = "2012-05-07T11:25:56-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29905#comments:id=1663828",
        },
        {
            id = 1675983,
            score = 1,
            author = "selvin",
            text = "Note that AOE is really good here. As a hunter I just went along multishotting, and I never even got close to low. The dudes they send with you do a decent job tanking.",
            date = "2012-06-12T12:31:11-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29905#comments:id=1675983",
        },
        {
            id = 1800729,
            score = 1,
            author = "98367",
            text = "I should add this is also a very good quest to grind on a jewelcrafter upon first entering pandaria to collect all the blue recipes. Since the guys spawn quickly, you can get just about all of them to drop inside of about 4 hours of farming it (I did it across multiple nights and have all but one of them now). Plus the mote drop rate is reasonably high if you group pull them and grind so you can get more motes for training or other profs.",
            date = "2013-01-18T21:59:38-06:00",
            sourceUrl = "https://www.wowhead.com/quest=29905#comments:id=1800729",
        },
        {
            id = 1731432,
            score = 0,
            author = "PhaetonHolt",
            text = "Before handing in the quest I thought I might keep my loyal little army of fishmen and quest elsewhere with them. Alas they disappear if you move too far away from Pearlfin Village, so don't bother.",
            date = "2012-10-04T16:43:07-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29905#comments:id=1731432",
        },
    },
