        {
            id = 1784840,
            score = 8,
            author = "Rustman",
            text = "After trying a few different methods in disgust I attacked and then ran out of range to let the NPCs handle it.  My intent was to rush in at the end to make sure I got the credit for  the kill but then a couple Hozen spawned where I was.. while I dealt with them the NPCs  killed him but still got credit for it  ;)",
            date = "2012-12-20T20:32:17-06:00",
            sourceUrl = "https://www.wowhead.com/quest=29906#comments:id=1784840",
        },
        {
            id = 1934041,
            score = 5,
            author = "Eido",
            text = "If you are wondering if you already completed this quest, the following script can be copied and pasted into your chat. Once the script has run (hit enter after pasting it), it will tell you if you have completed the quest or not:\n\n/run local c = IsQuestFlaggedCompleted(29906)print(\"You have \"..(c and \"\" or \"not\")..\"done this quest.\")",
            date = "2014-01-12T21:39:06-06:00",
            sourceUrl = "https://www.wowhead.com/quest=29906#comments:id=1934041",
        },
        {
            id = 1738548,
            score = 4,
            author = "awrhody",
            text = "Level 85 mage as well.  My \"buddies\" do a lousy job tanking as well.  Even if I spell absorb the bananas and stay out of the red he still comes after me.  Going to wait until I'm 87 or so.",
            date = "2012-10-11T13:41:38-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29906#comments:id=1738548",
        },
        {
            id = 1773169,
            score = 4,
            author = "303633",
            text = "If you are a JC and want to easily farm meta recipes and some greens you can kill all the hozen that are visible in this quest phase. The good thing is that the jinyu soldiers around can tank and aoe the hozen in the area, if you have a good aoe you can farm them a lot in an easy way.\n\nI got nine meta recipes, lots of greens items and windcloth.\n\nbut be careful, if you complete or abandon this quest, you can no longer see this area with the hozen and the jinyu around.",
            date = "2012-12-01T15:15:46-06:00",
            sourceUrl = "https://www.wowhead.com/quest=29906#comments:id=1773169",
        },
    },
    [29907] = {
        {
            id = 1719733,
            score = 32,
            author = "251382",
            text = "As of 26/09/12 simply abandoning and reacquiring the quest works",
            date = "2012-09-26T06:23:44-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29907#comments:id=1719733",
        },
        {
            id = 1802043,
            score = 10,
            author = "304770",
            text = "For completionists, you may want to go back and pick up either  https://www.wowhead.com/quest=32018 or https://www.wowhead.com/quest=32019 before picking up this as they become unavailable otherwise.",
            date = "2013-01-21T14:13:05-06:00",
            sourceUrl = "https://www.wowhead.com/quest=29907#comments:id=1802043",
        },
        {
            id = 1719014,
            score = 5,
            author = "534766",
            text = "At the moment this quest is bugged on live servers; every time someone accepts it, the quest npcs for the previous person despawn. This causes people not to be able to advance in the quest line and having to search for other quest hubs in the mean time.\n\nAlso, of course there's a lot of angry ganking and mammoth standing over the quest npc at the moment. I can only imagine it clearing up when Blizzard either fixes it or the first couple of days of the expansion have passed so less people will attempt the quest.",
            date = "2012-09-25T17:05:53-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29907#comments:id=1719014",
        },
        {
