    [29912] = {
        {
            id = 1653586,
            score = 318,
            author = "Cielos",
            text = "This is how I completed the quest:\n\nTurnip: Hit it with average power\n\nWatermelon: Hit it softly\n\nExtra-spicy tofu: Hit it as hard as possible\n\nAfter this, you should talk to Miss Fanny again to launch yourself.  I haven't tried it with any other race besides Pandarian, but I launched myself at average power and landed safely on the farm.",
            date = "2012-04-13T23:31:06-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29912#comments:id=1653586",
        },
        {
            id = 1653722,
            score = 66,
            author = "pixila",
            text = "Miss Fanny is the elite Mushan Dinossaur standing on the side of the house, next to the monkey called Muno the Farmhand.\n\nYou can pick up the quest items (turnip, watermelon and extra-spicy tofu right in front of where the NPC questgiver is.\n\nConfirmed order as the previous comment;\n\n- Turnip: Average power\n-Watermelon: Softly\n-Extra-Spicy Tofu: Hard as possible",
            date = "2012-04-14T09:21:10-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29912#comments:id=1653722",
        },
        {
            id = 1657313,
            score = 57,
            author = "littlefox",
            text = "Blizzard seem intent on causing hilarity for their British players.  In Cataclysm we had Find Fanny which made me giggle because I'm just an overgrown schoolgirl at heart and this expansion we have this quest.\n\nParticularly amusing was the quest text when you hit a watermelon:\n\n'Good bonk, Miss Fanny! You got nice control!'\n\nLets's put it this way it's not a phrase you would use in front of your grandma...",
            date = "2012-04-22T10:39:30-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29912#comments:id=1657313",
        },
        {
            id = 3244769,
            score = 51,
            author = "lukesmithkaz",
            text = "Chromie Time and Shadowlands Prepatch Bug\n\nIf you're like me, a dwarven hunter enjoying his days in the land of Pandaria, you might come across this quest and get frustrated when you can't loot more Extra-Spicy Tofu!\n\nIf this happens to you, what worked for me was abandoning the quest, picking it back up, getting the watermelon and the pink turnip, launching them down the hill first, and then finally I was able to get more tofu. Here's the correct option for each item:\n\nTurnip: Hit it with average power\n\nWatermelon: Hit it softly\n\nExtra-Spicy Tofu: Hit it as hard as possible\n\nHappy leveling!",
            date = "2020-11-02T13:35:58-06:00",
            sourceUrl = "https://www.wowhead.com/quest=29912#comments:id=3244769",
        },
        {
            id = 1825599,
            score = 41,
            author = "1102404",
            text = "Turnip: Average power\nWatermelon: Softly\nExtra-Spicy Tofu: Hard as possible\n\nSimple! :)",
            date = "2013-03-09T20:07:03-06:00",
            sourceUrl = "https://www.wowhead.com/quest=29912#comments:id=1825599",
        },
    },
