    [29917] = {
        {
            id = 3243199,
            score = 11,
            author = "PUFF",
            text = "I think Blizzard messed this one up with the squish, he kills me in 3 hits...",
            date = "2020-10-28T13:42:00-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29917#comments:id=3243199",
        },
        {
            id = 1738808,
            score = 10,
            author = "167868",
            text = "Lupello counts as a Thieving Wolf kill for the other quest (http://www.wowhead.com/quest=29916) Francis gives.",
            date = "2012-10-11T18:53:58-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29917#comments:id=1738808",
        },
        {
            id = 2586628,
            score = 9,
            author = "Ylnevaeh",
            text = "Ok, so in 8.0 he may not have been balanced out with the stat squish we got. I know I'm a squishy mage at L88, but if he hits you, he's hitting you with 1600 every hit back to back, even ice barrier was failing this. I did get it solo'd the 2nd attempt, but just a word of caution.",
            date = "2018-07-31T23:23:24-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29917#comments:id=2586628",
        },
        {
            id = 2621075,
            score = 4,
            author = "295591",
            text = "I was able to solo this as a warrior. The key is to not get feared. If he fears you he'll jump on you afterwards and that's where the damage comes from. His howl, which is what fears you, has a long wind up so you have plenty of time to use whatever fear mitigation skill you have.",
            date = "2018-10-04T07:53:10-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29917#comments:id=2621075",
        },
        {
            id = 3138451,
            score = 3,
            author = "Jeff0253",
            text = "On my 87 Shammy, it took 3 tries before I finally got him. Earth elemental to help tank (the fear also chases away the elemental!), bloodlust, fire elemental, astral shift to hold down damage, healing surge about four times. and a lucky crit on earth shock. I really didn't think I could kill him at first, lol. So my advice: make a plan, don't give up, go and execute. Try stuff in a different order if it doesn't work at first. My max crit is only about 4k, so if I can do it so can you. Shammy Power!",
            date = "2019-07-11T16:14:34-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29917#comments:id=3138451",
        },
    },
    [29918] = {
        {
            id = 1654922,
            score = 35,
            author = "Cielos",
            text = "After you complete Francis' quests, Master Shang will appear and give you this quest.\n\nThe Great White Plainshawks are in the air and you will need to use the lasso provided by Master Shang in order to jump on its back.  After a few moments, you will be flung off its back and into its sharp talons, which you need to get out of quickly because you take damage.\n\nOnce you are in the talons, a button should appear on your screen (much like in the Ultraxion/Deathwing fight in Dragon Soul) that you need to click in order to jump on the back again.\n\nRinse and repeat until the plainshawk is dead. https://www.wowhead.com/npc=56338 can be found down the path and to the right tending to his gigantic watermelon behind his hut in Shang's Stead.",
            date = "2012-04-16T14:55:07-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29918#comments:id=1654922",
        },
        {
            id = 1746686,
            score = 23,
            author = "233948",
            text = "Note: If you, like me, use an addon like Dominos, and do not see the UI button to get back onto the bird's back, you can use the \"Extra Action Button\" macro (this button worked during the Ultraxion fight in Dragon Soul, as well as many other cases where you need to use a special action button).\n\nThe macro is very simple.  Create it, and pull it to a button on your action bar.\n\n/click ExtraActionButton1\n\nThat's it!\n\nGood luck :)",
            date = "2012-10-20T18:57:30-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29918#comments:id=1746686",
        },
        {
            id = 1932519,
            score = 18,
            author = "Grimnarl",
            text = "Thank the gods for WowHead : )\n\nFirst time on this quest I rode the hawk... saw the button appear to jump back on top of it... and rode it for like 5 minutes... and couldn't see the point. I was like WTF is the point of this? Eventually it dropped me to my death and I came here and found that you could target the hawk while on its back. So you click on it and at that point you can attack it. Give it everything you've got and keep jumping on its back when it claws you, and eventually you'll kill it and it'll drop to the ground and you'll survive the fall.",
            date = "2014-01-07T12:30:00-06:00",
            sourceUrl = "https://www.wowhead.com/quest=29918#comments:id=1932519",
        },
        {
            id = 1759900,
            score = 12,
            author = "SpareSimian",
            text = "You'll encounter Chen Stormstout on the way to turn in the quest. He tells you, \", we meet again! You looking for Shang? I think he's in back, polishing his melon.\"",
            date = "2012-11-09T16:00:26-06:00",
            sourceUrl = "https://www.wowhead.com/quest=29918#comments:id=1759900",
        },
        {
            id = 1938434,
            score = 11,
            author = "Kurasu",
            text = "For hunters, while on this quest, you are able to tame the Great White Plainshawk while you are mounted on it. However, be aware: you're high enough in the air that doing so means you'll probably plummet to your death, and you won't get credit; you'll still have to lasso  a second plainshawk. But you have to admit: that's a tame with *style*.",
            date = "2014-01-27T13:17:07-06:00",
            sourceUrl = "https://www.wowhead.com/quest=29918#comments:id=1938434",
        },
    },
    [29919] = {
