    [29920] = {
        {
            id = 1752815,
            score = 12,
            author = "lisaroxy",
            text = "If you finish this and still don't have credit for Dawn's Blossom for the achievement, go to the Arboretum and check with the Inkmasters there.  They have two quickie little quests to collect petals and wasp stingers, and that was what I was missing after finishing all the main questlines.",
