    [29922] = {
        {
            id = 1835876,
            score = 8,
            author = "872107",
            text = "When you /wave at the curious cubs, they will run off. Pretty cute.",
            date = "2013-03-28T16:25:00-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29922#comments:id=1835876",
        },
        {
            id = 5392931,
            score = 3,
            author = "HushGlowie",
            text = "This quest is only obtainable after completing the first four chapters in the Jade Forest main quest line.\n\nThe Jade Forest quest line is actually the first one you obtain upon entering Pandaria, so this begins in Stormwind with The King's Command (https://www.wowhead.com/quest=29547/the-kings-command) which can either be picked up on a character in Pandaria Timewalking (you must be level 1-49 and talk to Chromie (https://www.wowhead.com/npc=167032/chromie) to start this) or you can pick up Hero's Call: Jade Forest! (https://www.wowhead.com/quest=49556/heros-call-jade-forest) from the Hero's Call Board (https://www.wowhead.com/object=206294/heros-call-board) on any character level 50 or higher. If it doesn't show up right away try picking up some other quests from the call board until the one you want appears. You can just discard the extra quests and pick them back up anytime. Once you have that quest you can just simply follow the quest chain up to this one.\n\nYou will need to complete these four chapters:\n\nPaw'don Village\nThe Waterspeaking Ceremony\nThe White Pawn\nPearlfin Village",
            date = "2022-07-07T09:49:15-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29922#comments:id=5392931",
        },
        {
            id = 1675992,
            score = 2,
            author = "selvin",
            text = "When you arrive you get some curious panda kids that follow you around, proudly declaring \"I'm not afraid of you!\"",
            date = "2012-06-12T12:37:41-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29922#comments:id=1675992",
        },
        {
            id = 5861142,
            score = 1,
            author = "Meleamee",
            text = "Pandaria Remix:\nAfter I got this quest I couldn't see Kitemaster Ut-Nam (https://www.wowhead.com/npc=56737/ut-nam) anywhere.\nI had gotten the flightpath earlier on so thought it was bugged but a relog phased him back.",
            date = "2024-05-21T11:43:43-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29922#comments:id=5861142",
        },
        {
            id = 1869923,
            score = 0,
            author = "Bengarion",
