    [29928] = {
        {
            id = 1654819,
            score = 61,
            author = "murphmanfa",
            text = "A reference, of course, to Harlan Ellison's horror/sci-fi short story \"I Have No Mouth, and I Must Scream\".\n\nThe whole thing can be found here (http://www.surfturk.com/endoftheworld/ihavenomouth.html).  One broken image contains AM's monologue which can be found here (http://www.youtube.com/watch?v=EddX9hnhDS4), read by the author himself for the computer game based on the story.\n\nIt's one of my favorite short stories, despite being so bleak and disturbing... definitely NSFW.",
            date = "2012-04-16T10:46:04-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29928#comments:id=1654819",
        },
        {
            id = 1749527,
            score = 34,
            author = "Allyosaugh",
            text = "Jade. Let me tell you how much I've come to mine jade since I began to live. There are 387.44 million miles of jade in Pandaria. If the word 'jade' was engraved on each nanoangstrom of those hundreds of miles it would not equal one one-billionth of the jade I have in my pockets at this micro-instant. For you. Jade. Jade.",
            date = "2012-10-24T14:03:37-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29928#comments:id=1749527",
        },
        {
            id = 1676153,
            score = 23,
            author = "darksoul019",
            text = "For those who dont want to read a short story or watch a video, just travel southwest like the quest says and at the Green Stonemasons Quarry kill the Pucksih Sprites, they drop 2-3 pieces each when you kill them, for some reason when you mouse over them the quest objectives dont appear in the mouseover.",
            date = "2012-06-12T22:43:55-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29928#comments:id=1676153",
        },
        {
            id = 2373875,
            score = 9,
            author = "Mezzalt",
            text = "“I am a great hard jade thing. Smoothly rounded, with no mouth, with pulsing green holes filled by mist where my eyes used to be. Stony appendages that were once my arms; rock rounding down into legless mounds of hard green mineral. I leave a green trail when I move. Blotches of diseased, evil green come and go on my surface, as though light is being beamed from within. Outwardly: dumbly, I shamble about, a thing that could never have been known as orc, a thing whose shape is so alien a travesty that orckind becomes more obscene for the vague resemblance. Inwardly: alone. Here. Living over the sea, over the earth, in the land full of pandas, whom the Titans created because their time was badly spent and they must have known unconsciously that pandas could do it better. At least the four of them are safe at last. will be all the madder for that. It makes me a little happier. And yet ... The Jade Witch has won, simply ... she has taken his revenge ...\n\nI have no jade, and I must scream.\"",
            date = "2016-08-26T16:14:16-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29928#comments:id=2373875",
        },
        {
            id = 1940149,
            score = 7,
            author = "tdotcspot",
            text = "The quest \"All We Can Spare\" must be completed before being able to accept this quest.\n[quest=29925 domain=www]",
            date = "2014-02-02T13:40:40-06:00",
            sourceUrl = "https://www.wowhead.com/quest=29928#comments:id=1940149",
        },
    },
