    [29967] = {
        {
            id = 1767235,
            score = 24,
            author = "Sketchie",
            text = "There is a line of Grookin Dookers leading down to a outhouse with a table of... ominous green stuff and bombs. Once they have done their business in the outhouse, he will jump out, throw their \"ook\" into the glowing green bowl and then run off.\n\nRivett Clutchpop is next to the table, crafting \"bombs\" with their \"ook\". He can only craft one bomb at a time and it takes a while for him to craft one, as he needs the \"ammo\" from the Grookin Dookers.\n\nIf you stand around them long enough, you can get pretty amusing quips from the Grookin Dookers and Rivett Clutchpop.\n\nRivett Clutchpop\nRivett Clutchpop says: Oh, the things I do for the Horde...\nRivett Clutchpop says: Okay, . I can only make these so fast... you gotta make every shot count!\nRivett Clutchpop says: Careful, ! Methane labs like these can be extremely volatile.\nRivett Clutchpop says: Come on, come on, come on! They'll be here any moment!\nRivett Clutchpop says: Assuming this works, I'll need a name for my invention. How 'bout... Grookin Grenade?\nRivett Clutchpop says: So if I just substitute the powder with compressed...fuel, we could be business! So to speak.\nRivett Clutchpop says: Woohwee! Smells like Dalaran Sharp!\n\nGrookin Dooker\nGrookin Dooker says: Ook! Dookin' praire-doggin'!\nGrookin Dooker says: Ugh... I think I mighta ooked my dookers.\nGrookin Dooker says: Oogh... grooked me bad slickies...\nGrookin Dooker says: Ookin's what hozen do best!",
            date = "2012-11-24T13:49:59-06:00",
            sourceUrl = "https://www.wowhead.com/quest=29967#comments:id=1767235",
