    [29984] = {
        {
            id = 1719260,
            score = 27,
            author = "303661",
            text = "So, no one told me this is the coolest quest in the game so far, because - let's face it - it HAS to be!\n\nKarate montage? I DIED laughing. This is incredible. Way to go, Blizz. <3",
            date = "2012-09-25T22:14:24-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29984#comments:id=1719260",
        },
        {
            id = 1719872,
            score = 26,
            author = "Vlad",
            text = "If you by any case have issues with your addons and the meter that is supposed to be shown, you can use this script to tell you when you strike:\n/run if not TB then TB=CreateFrame\"Frame\"end local i,p,m=0,\"player\"TB:SetScript(\"OnUpdate\",function(s,e)m=UnitPower(p,10)if i==0 and m>=80 then i=1 print\"Strike!\"elseif m<80 then i=0 end if not UnitInVehicle(p)then s:SetScript(\"OnUpdate\",nil)end end)\nPaste it in the chat when you are in the \"vehicle\", it automatically stops when you aren't anymore, you have to paste again in case you exit and enter it again.",
            date = "2012-09-26T08:43:01-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29984#comments:id=1719872",
        },
        {
            id = 1722481,
            score = 25,
            author = "Sharkon",
            text = "The hour's approaching to give it your best\nAnd you've got to reach your prime\nThat’s when you need to put yourself to the test\nAnd show us a passage of time\nWe're going to need a montage (Montage!)\nOoh, it takes a montage (Montage!)\n\nShow lot of things happing at once\nRemind everyone of what’s going on (What’s going on!)\nAnd with every shot show a little improvement\nTo show it all will take to long\nThat’s called a montage (Montage!)\nGirl, we want montage (Montage!)\n\nIn anything if you want to go\nFrom just a beginner to a pro\nYou need a montage (Montage!)\nEven Rocky had a montage (Montage!)\n\nAlways fade out in a montage... (Montage!)\nIf you fade out it seem like more time has passed in a montage... (Montage!)\nMontage... (Montage!)",
            date = "2012-09-28T02:39:35-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29984#comments:id=1722481",
        },
        {
            id = 1726382,
            score = 21,
            author = "Rammstein",
            text = "You can talk to the Master if you want to see your training again.",
            date = "2012-09-30T17:35:07-05:00",
            sourceUrl = "https://www.wowhead.com/quest=29984#comments:id=1726382",
        },
        {
            id = 1820668,
            score = 10,
            author = "Farmbuyer",
            text = "\"Elan, never underestimate the strategic value of a good Training Scene Montage.  It could save your life someday.\" (http://www.giantitp.com/comics/oots0391.html)",
            date = "2013-03-03T22:24:14-06:00",
            sourceUrl = "https://www.wowhead.com/quest=29984#comments:id=1820668",
        },
    },
    [29985] = {
        {
            id = 1813055,
            score = 9,
            author = "Cutthroat",
            text = "You have to complete Stemming the Swarm (http://www.wowhead.com/quest=29981) (given by Lin Tenderpaw (http://www.wowhead.com/npc=56111)) and Evacuation Orders (http://www.wowhead.com/quest=29982) (given by Loon Mai (http://www.wowhead.com/npc=56720)), both located at Stoneplow in Valley of the Four Winds (roughly [19.7, 57.0]).\nLoon Mai will then send you on to find The Hidden Master (http://www.wowhead.com/quest=29983), Master Bruised Paw.",
            date = "2013-02-13T09:02:02-06:00",
            sourceUrl = "https://www.wowhead.com/quest=29985#comments:id=1813055",
