    [29990] = {
        {
            id = 1819621,
            score = 24,
            author = "Xzerqces",
            text = "The reason you arent seeing the Cinematic and cannot continue the quest is likely not related to some quest you haven't done in Valley of the Four Winds, but in not having completed the Krasarang Wild Quests. One of the final quests in Krasarang is \"Warn Stoneplow\" and is given by Sunwalker Dezco. It is a quest given after completing the main questlines in Krasarang and takes you back to Loon Mai in the Valley of the Four Winds.\n\nIf you have not completed the quest Warn Stoneplow. You will not see the cinematic or be able to complete the questline in Stoneplow, Valley of the Four Winds.",
            date = "2013-03-01T10:53:15-06:00",
            sourceUrl = "https://www.wowhead.com/quest=29990#comments:id=1819621",
        },
        {
