    [30002] = {
        {
            id = 2582719,
            score = 22,
            author = "vitor210",
            text = "As of today in patch 8.0, this quest no longer works if you jump on them. Don't be like me that wasted 5min trying to jump on them for several times, doing it DOES NOT work.\n\nThe only way to complete the quest is if you dps them down, that way works.",
            date = "2018-07-20T08:35:12-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30002#comments:id=2582719",
