    [30005] = {
        {
            id = 1657915,
            score = 32,
            author = "533704",
            text = "[Beta]\nIf you happen to walk out of the place like i accidentally did don't turn around and run back.\nYou will end up in the instance instead of where you should be.\n\nAt the bottom of the stairs to the left of the temple you'll find an NPC called Elder Sage Wind-Yi.\nSpeak to her, she'll give you the option to go to the temple.\nAnd port you right back to where you should be.\n\nHope this helps",
            date = "2012-04-23T16:57:12-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30005#comments:id=1657915",
        },
        {
            id = 1660576,
            score = 3,
            author = "rossm1983",
            text = "Containers of fireworks are spread all over the outside area of the temple. clicking on them will set them off.",
            date = "2012-04-29T20:05:03-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30005#comments:id=1660576",
