        {
            id = 1871350,
            score = 1,
            author = "1006364",
            text = "Something no one is mentioning...\nWhere is a little girl getting the money to pay us for this?",
            date = "2013-06-27T18:20:46-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30005#comments:id=1871350",
