    [30031] = {
        {
            id = 1751783,
            score = 15,
            author = "582893",
            text = "I think it's quite funny that Li Li claims to have \"never drank a drop of beer in [her] life\" when it clearly states in Quest for Pandaria, Part 2, page 2, that \"she slurped her beer.\" Not sure what the Pandaren drinking age is ... but she is cleary trying to hide her drinking problem from the player ...",
            date = "2012-10-27T12:40:45-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30031#comments:id=1751783",
        },
        {
