    [30032] = {
        {
            id = 1718842,
            score = 57,
            author = "insanyac",
            text = "The NPC (Shai Cliffwatcher (http://www.wowhead.com/npc=59224)) and the Rappeling Rope you need to use to get to the cave are at (51, 77). The cave is 100 yards east of where you drop (53, 76). Once you loot the barley (http://www.wowhead.com/item=77034) a Cave Horror (http://www.wowhead.com/npc=57257) spawns with roughly 180k hp. You can climb back up from the same location you dropped down (the \"rope up\" is on a small table near the ground).",
            date = "2012-09-25T14:43:54-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30032#comments:id=1718842",
        },
        {
            id = 1681186,
            score = 20,
            author = "10171",
            text = "Note that you acually have to use the \"Rappelling Rope\" to fulfill the \"Use the Cliff Harness\" objective, meaning you can't just jump, fly, slowfall, etc.",
            date = "2012-06-25T23:48:56-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30032#comments:id=1681186",
        },
        {
            id = 1720611,
            score = 16,
            author = "206009",
            text = "Hopefully this will help someone.  When you're looking to \"climb\" back up, don't look up for a rope hanging down.  I didn't realize that there's a table on the ground with rope that needs to be clicked to get back up.",
            date = "2012-09-26T17:55:39-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30032#comments:id=1720611",
        },
        {
            id = 1942784,
            score = 15,
            author = "Turpentine",
            text = "Again, for those who play without coordinates, the place to use the rope to get back up to the top level of the Valley of the Four Winds is found in the same spot (http://i.imgur.com/dwhRdtZ.jpg) where you land after you used the rope to drop down (http://i.imgur.com/0MvCpQ2.jpg). Click the coiled rope on the table (silver glove on mouse-over) and enjoy the ride up.\n\nThe drop-down spot is directly north of the second A in Krasarang Wilds, right on the edge of the cliff, when you open your world map (M - default) while in the [zone=5805] zone.\n\nThe back-to-top spot is directly south of the last S in Valley of the Four Winds, to the left of the cave where you just got the barley, when you open your world map (M - default) while in the [zone=6134] zone.",
            date = "2014-02-12T20:41:52-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30032#comments:id=1942784",
        },
        {
            id = 1797658,
            score = 11,
            author = "1062573",
            text = "The question half the people coming here below level 90 are probably coming back here for:\n\nThe rope to get back up, which is not tracked by the quest, is located at 48.64, 27.03 Krasarang Wilds coordinates.\n\nNote that the quest takes place RIGHT on the border between Krasarang Wilds and Valley of Four Winds; these coordinates are for if you're in Krasarang wilds, but if you go to the edge of the cliff you'll cross into Valley of Four Winds.",
            date = "2013-01-13T04:03:51-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30032#comments:id=1797658",
        },
    },
    [30033] = {
        {
            id = 1653928,
            score = 1,
            author = "Zillions",
            text = "2nd quest available to new Pandaren.  The name of the quest is dependent on your class.  Casters will receive this quest, instructing them to loot and equip a Trainee's staff.",
            date = "2012-04-14T16:03:46-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30033#comments:id=1653928",
        },
        {
            id = 3200813,
            score = 1,
            author = "GibbleFenwick",
            text = "Hmmm. Nice set of starter quests to get you into the game; but very poorly thought out for caster classes.\n\nAll the emphasis on \"weapons\" and we get a \"spell blade\" that is utterly pointless: caster should not use it; and it gives zero benefit to caster.\nThere's not even so much as a clue to use your spells in the quest text.\n\nIt turns out that if you follow the quest text literally; i.e. equip the your \"weapons\" and use them to attack the targets in the follow-up quest: it takes longer to destroy them than if you attacked bare fisted!\n(Of course the correct thing to do as a caster is sell the useless gear and cast your spells.)",
            date = "2020-04-19T02:47:03-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30033#comments:id=3200813",
        },
        {
            id = 6354641,
            score = 1,
            author = "gongling",
            text = "I'm pretty sure this quest is both Mage and Warlock linked, I've tried with a newly created Mage Pandaren and also with a Warlock Pandaren.",
            date = "2026-05-12T09:49:46-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30033#comments:id=6354641",
        },
    },
