    [30048] = {
        {
            id = 1724882,
            score = 14,
            author = "455223",
            text = "It's Li Li and the Grain,\nLi Li and the Grain,\nOne is Pandaren, the other is grain,\nTo prove her panda worth.\nShe'll end her uncle's mirth,\nIt's Li Li. it's Li Li and the grain, grain, grain, grain, grain...",
            date = "2012-09-29T16:47:33-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30048#comments:id=1724882",
        },
        {
            id = 1767413,
            score = 4,
            author = "233928",
            text = "There was a jade squash wearing a pilgrim's hat in the dirt under the front steps of the granary today.\n\nA Thanksgiving's day thing?",
            date = "2012-11-24T23:46:53-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30048#comments:id=1767413",
        },
        {
            id = 1720008,
