        },
        {
            id = 1772594,
            score = 2,
            author = "vizoere",
            text = "Fly to the Halfhill FP and run along the road to the South.\n\nLi-Li is at The Imperial Granary at 52.7, 62.8.",
            date = "2012-11-30T22:10:59-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30048#comments:id=1772594",
        },
        {
            id = 5561169,
            score = 1,
