        },
    },
    [30049] = {
        {
            id = 1724691,
            score = 6,
            author = "GustoGA",
            text = "The Gilded Fan is not a building NOR is it marked on this map (above).\n\nIts along the road directly north of Halfhill @ 54, 39.  There is a fence and cart along the side of the road.  Guys hangin out there drinking up a storm:)",
