    [30050] = {
        {
            id = 1720000,
            score = 97,
            author = "453960",
            text = "Water my huge melons",
            date = "2012-09-26T10:34:38-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30050#comments:id=1720000",
        },
        {
            id = 1720994,
            score = 40,
            author = "549635",
            text = "First off, this quest can be quite confusing.\n\n-You can do this while mounted\n-The vegetable she wants you to go to is USUALLY glowing\n-If it isn't glowing and/or don't know what she wants watered, just wait for her to say a new one. There's no penalty. You can also only water in the proper spot, so spamming the button doesn't hurt you if it's the wrong crop anyways.\n-Use the big button to water, when watering just ride through the crops spamming it until you have to change. Easily 15+ per vegetable for quest progress.\n-Take extra care when watering her big melons",
            date = "2012-09-27T00:29:32-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30050#comments:id=1720994",
        },
        {
            id = 1668408,
            score = 23,
            author = "Steelforge",
            text = "Watering can be done while mounted.",
            date = "2012-05-18T19:40:30-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30050#comments:id=1668408",
        },
        {
            id = 1789958,
            score = 20,
            author = "540613",
            text = "Had some trouble finding her huge melons, they are behind the sugar beets.",
            date = "2012-12-31T00:29:49-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30050#comments:id=1789958",
        },
        {
            id = 1684917,
            score = 14,
            author = "Eralson",
            text = "This quest can be done much faster if you keybind the watering button. It's the \"Extra Action Button 1\" keybind under \"Action Bar Functions.\"\n\nOnce you have this keybound, you can use the mouse to run around while spamming the watering key, rather than keyboard turning while spamming the watering button with your mouse. Using this approach, I was able to water each group of vegetables 20+ times before she called out the next, allowing me to finish the quest on the third group of vegetables.",
            date = "2012-07-05T19:03:56-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30050#comments:id=1684917",
        },
    },
