    [30053] = {
        {
            id = 1764739,
            score = 18,
            author = "deathbybunnies",
            text = "To be able to talk to Chen Stormstout (http://www.wowhead.com/npc=56133) and move on to The Emperor (http://www.wowhead.com/quest=30073), you need to complete all the quests in all the hubs you are sent to while asking NPCs for hops during Hop Hunting (http://www.wowhead.com/quest=30053).    You also need to complete the quest chain associated and beginning with Li Li's Day Off (http://www.wowhead.com/quest=29950).\n\nDon't forget to complete Gardener Fran and Her Watering Can (http://www.wowhead.com/quest=30050)!\n\nOnce you have completed all the quests in all the hubs, Stormstout's Hops (http://www.wowhead.com/quest=30055) will automatically pop up for acceptance and send you back to Chen at Halfhill.  Visually, you'll know you're ready when Chen is surrounded by the all the ingredients he needs: water barrels, hop baskets, and a grain basket.\n\nIf you don't see all of these ingredients, go back to the Hop Hunting (http://www.wowhead.com/quest=30053) quest hubs and look for more quests to complete.",
            date = "2012-11-19T09:35:08-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30053#comments:id=1764739",
        },
        {
            id = 1728581,
            score = 7,
            author = "star416",
            text = "found Gai Lan at 38.61, 51.66",
            date = "2012-10-02T10:04:43-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30053#comments:id=1728581",
        },
        {
            id = 1754619,
            score = 4,
            author = "cernowyth",
            text = "Den Mudclaw is at 44.3, 34.3.",
            date = "2012-10-31T21:08:18-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30053#comments:id=1754619",
        },
        {
            id = 5433735,
            score = 3,
            author = "Moreite8462",
            text = "She's down the hole just below Mung-Mung and her dad, Den. For those coming here trying to find Mina Mudclaw after scouring the countryside..... she's down the hole. Those stupid evil bunnies fill the walkway, which is big enough if you just stick to the wall and clean a path you can get to Mina and walk her back along the same path pretty quickly. Finally, an NPC escort that doesn't walk into the mobs. Thanks Mina.",
            date = "2022-09-14T03:19:31-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30053#comments:id=5433735",
        },
        {
            id = 1803669,
            score = 2,
            author = "Wabefuhon",
            text = "Mina Mudclaw is the hardest part of the quest because I get attacked by several of those Springtails and I die because they flee.\nI'm using an Orc Warrior, I have Impending Victory, which I can use anytime and after killing an enemy, but the fact that they retreat makes it hard to heal up when I need to.",
            date = "2013-01-24T18:52:13-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30053#comments:id=1803669",
        },
    },
    [30054] = {
        {
            id = 1737143,
            score = 27,
            author = "223389",
            text = "You will die here many times.  The vermin will flee at low health and bring a few friends back with him.  The area is pretty crowded. Also there are wandering packs of three mini-vermin that will attack you.\n\nMost annoying quest I've dealt with so far.\n\nI am a rogue so I can't handle AOE very well.  Also they apply a bleed so I couldn't vanish/stealth.",
            date = "2012-10-10T03:09:10-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30054#comments:id=1737143",
        },
        {
            id = 1720920,
            score = 11,
            author = "Brielle",
            text = "This quest blows...pulls so much crap when they run away.",
            date = "2012-09-26T23:03:02-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30054#comments:id=1720920",
        },
        {
            id = 1777244,
            score = 6,
            author = "Foxpaw",
            text = "Its vanilla WoW Moonbrook Defias Mages all over again. These guys are BRUTAL. Be VERY cautious when pulling, use CC if you have it, and slow down mobs before they can run. Hamstring, crippling poison, disable, whatever you can do to stop them getting away before you can finish them off. Its entirely possible to do without dying, you just have to either be very cautious, or if all else fails, just get some friends to do it with you.",
            date = "2012-12-07T15:07:01-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30054#comments:id=1777244",
        },
        {
            id = 1735794,
            score = 5,
            author = "Farmbuyer",
            text = "Pretty straightforward quest, just watch out for the wandering elite.  If you're pairing it with the quest to find the farmer's daughter press-ganged into dancing for rabbits, the virmen underground count towards the quest too.\n\nAlso, \"So many teeth! Maybe Mung-Mung will glue them together to make a tiny rake.\" is creepy as hell.",
            date = "2012-10-08T15:04:14-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30054#comments:id=1735794",
        },
        {
            id = 1850989,
            score = 3,
            author = "941372",
            text = "It seems that the easiest way to complete the quest is to pull the mobs One at a time into the empty fields where there are no other mobs around. When they start to run away, they won't run to the others to agro more.",
            date = "2013-05-07T16:53:18-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30054#comments:id=1850989",
        },
    },
    [30055] = {
        {
            id = 1764728,
            score = 6,
            author = "deathbybunnies",
            text = "To be able to talk to Chen Stormstout (http://www.wowhead.com/npc=56133) and move on to The Emperor (http://www.wowhead.com/quest=30073), you need to complete all the quests in all the hubs you are sent to while asking NPCs for hops during Hop Hunting (http://www.wowhead.com/quest=30053).    You also need to complete the quest chain associated and beginning with Li Li's Day Off (http://www.wowhead.com/quest=29950).\n\nDon't forget to complete Gardener Fran and Her Watering Can (http://www.wowhead.com/quest=30050)!\n\nOnce you have completed all the quests in all the hubs, Stormstout's Hops (http://www.wowhead.com/quest=30055) will automatically pop up for acceptance and send you back to Chen at Halfhill.  Visually, you'll know ready when Chen is surrounded by the all the ingredients he needs: water barrels, hop baskets, and a grain basket.\n\nIf you don't see all of these ingredients, go back to the Hop Hunting (http://www.wowhead.com/quest=30053) quest hubs and look for more quests to complete.",
