    [30056] = {
        {
            id = 1712361,
            score = 161,
            author = "Krastopic",
            text = "There are three entrances to the cave.  The entry closest to the quest giver is the easiest to access.  The coordinates are 43.6, 35.0.\n\nGo down into the cave, stick to the right side of the wall.  You will likely have to kill at least one maybe two mobs.  Turn right at the bottom of the grade and you will see Mina Mudclaw standing on top of the giant carrot.",
            date = "2012-09-11T18:24:19-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30056#comments:id=1712361",
        },
        {
            id = 5858557,
            score = 61,
            author = "MyloraX",
            text = "Hi timer runners! You need to find the underground tunnel entrance which is at  43 40.  Follow it down and find her standing on a carrot",
            date = "2024-05-18T12:32:50-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30056#comments:id=5858557",
