    [30059] = {
        {
            id = 1719647,
            score = 11,
            author = "Auriaya6",
            text = "The 'Tiny Mutated Silkmoths' are little packs of flying moths. I found a pack at 65,54",
            date = "2012-09-26T04:54:31-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30059#comments:id=1719647",
        },
        {
            id = 1720517,
            score = 3,
            author = "834735",
            text = "The little moths involved in this quest do spawn on their own - they just have a SLOW respawn timer. They have nothing to do with the coccoons spread around the grounds or the grubs. They spawn where the normal sized moths spawn. So if you don't see any, run around to the north and south of the silk farm and be patient.\n\nThis has been a problematic quest during early MoP due to the high number of players killing them!",
            date = "2012-09-26T16:42:02-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30059#comments:id=1720517",
        },
        {
            id = 1730076,
            score = -1,
            author = "Dudash",
            text = "Taken from the list of October 2nd hotfixes:\n\nMutated Silkmoths and Tiny Mutated Silkmoths are now more abundant.\n\nWell it seems that blizzard cares about whether or not we are forced to sit around and wait for things to respawn for quests due to their mistakes. But as for caring about things that are much more important, thats a totally different story.",
            date = "2012-10-03T14:00:23-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30059#comments:id=1730076",
        },
    },
    [30063] = {
        {
            id = 1744519,
            score = 38,
            author = "andreicmello",
            text = "Do NOT do this quest in front of the temple. The loot option hardly shows up. Do it on the other placees, further away, and you won't get as frustrated as I got.",
            date = "2012-10-18T01:54:29-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30063#comments:id=1744519",
        },
        {
            id = 1745042,
            score = 20,
            author = "Stealthfire13",
            text = "Looting the https://www.wowhead.com/item=77419 needed for the quest gives you a 30 minute debuff called, appropriately, Mask of Doubt. Visually all that it seems to do is make you glow purple, however I was both in cat form and wearing a Hallow's End mask at the time, so it's possible that you're supposed to be wearing an actual mask and mine just bugged. Additionally, the debuff causes your character to start whispering you with his or her \"doubts\".\n\nSome that I've seen:\n\nWhy do I always feel so alone? Is it because...I'm alone?\nWhat are people saying about me?\nDoes this armor look a little tight on me?\nOf course my worst fears are going to come true.\nNothing is ever going to change.\nEveryone around me only pretends to like me.\nI keep hearing voices in my head. Should I be worried?\n\nTurning the quest in removes the debuff as the questgiver blesses you, and you gain Fortitude (10% stam).",
            date = "2012-10-18T17:03:15-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30063#comments:id=1745042",
        },
        {
            id = 1747357,
            score = 11,
            author = "992329",
            text = "My huge, ugly as hell Tauren Shaman says: Does this armor look a little tight on me?\nMe: No sweetheart, you look as beautiful as ever.",
            date = "2012-10-21T17:19:08-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30063#comments:id=1747357",
        },
        {
            id = 1787729,
            score = 1,
            author = "Pandecio",
            text = "As far as I've seen, the best place to complete most of the quests in the Jade Temple Grounds is where you can find the sutras for the Saving the Sutras (http://www.wowhead.com/quest=30064) quest.\n\nYou can find the Sutras easily in the rocks surrounding the clearing; plus it seems to have an abundance of arrows for Arrows of Fortune (http://www.wowhead.com/quest=30065). The three Guardians there can be used for both the Hidden Power (http://www.wowhead.com/quest=30066) quest and as tanks/support for The Darkness Around Us (http://www.wowhead.com/quest=30006) and Behind the Masks (http://www.wowhead.com/quest=30063) quests, specially if they are empowered by the scrolls.\n\nPretty much all daily quests for this particular place can be completed in 4-5 minutes at good pace.",
            date = "2012-12-26T14:31:29-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30063#comments:id=1787729",
        },
        {
            id = 1835583,
            score = 1,
            author = "704410",
            text = "There is a good collection of doubts that spawn pretty nicely at...\n60.2, 63.3\n\nIf you run out of doubts to kill then fly through the crevice to other side at...\n61.4, 58.7\nwhere there are more.\n\nBoth locations are on the grassy banks at water's edge.",
            date = "2013-03-27T23:59:46-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30063#comments:id=1835583",
        },
    },
    [30064] = {
        {
            id = 1748559,
            score = 35,
            author = "Crimsonlord",
            text = "Everyone,\n\nIt doesn't matter what your realm / faction you belong to - please, please, PLEASE send blizzard a suggestion to increase the spawn rates of these books!\n\nMy suggestion message to blizzard was:\n\n\" Hello,\n\nThe spawn rate of [Ancient Sutra] in the quest [Saving the Sutras] is too low.\n\nPlease increase the spawn rates and preferably increase the amount of locations available for this quest item to spawn.\n\nThank you. \"",
            date = "2012-10-23T08:56:21-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30064#comments:id=1748559",
        },
        {
            id = 1755850,
            score = 32,
            author = "78414",
            text = "I have to give Blizzard credit for creating an immersive experience here.  Between the over-camping and the abysmal spawn rates, it really does feel like I'm being consumed by the Sha of Doubt...",
            date = "2012-11-02T18:30:36-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30064#comments:id=1755850",
        },
        {
            id = 1857151,
            score = 6,
            author = "Azshen",
            text = "The Blizzard Gods must have heard the complaints about the spawn rates because as of 24/05/13, I had NO problem collecting these tomes :)",
            date = "2013-05-24T12:19:03-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30064#comments:id=1857151",
        },
        {
            id = 5857649,
            score = 5,
            author = "Monotonex",
            text = "If the quest giver is missing when you go to turn in just log out and login to fix",
            date = "2024-05-16T23:15:53-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30064#comments:id=5857649",
        },
        {
            id = 1737142,
            score = 4,
            author = "sorceressdee",
            text = "These are little books laying around on the ground around 56:52. If you don't want to have to fight any mobs to get them, look for the ones near already-fighting Adepts.",
            date = "2012-10-10T03:05:08-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30064#comments:id=1737142",
        },
    },
    [30065] = {
        {
            id = 1799970,
            score = 6,
            author = "Lannister",
            text = "This quest can bug out where you click on the arrow, go through the motion of collecting it and nothing happens at the end -- no arrow to loot. Tried several different nodes to no avail, handing in the other quests, logging in/out, abandoning the quest, zoning in/out of the area, dismissing pet and none of that worked. Then I tried getting in to combat with one of the small sha, killing it, and clicking on an arrow after and it worked perfectly; I was able to loot them after that.\n\nSo if what happened to me happens to you, it would be worth trying getting back in to combat and see if that resolves it for you as well.",
            date = "2013-01-17T08:16:36-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30065#comments:id=1799970",
        },
        {
            id = 1748515,
            score = 4,
            author = "Znuff",
            text = "Try to look for them on the \"exteriors\" of the questing area, they seem to spawn more there and not a lot of people will be looking.\n\nMost people will look for them right in the middle of the questing area.",
            date = "2012-10-23T07:24:07-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30065#comments:id=1748515",
        },
        {
            id = 1782356,
            score = 3,
            author = "Jayrai",
            text = "The arrows can be found all over the place, in the same area as the Sha invaders (at the Temple of the Jade Serpent).\n\nThey glitter quite bright, and are hard to miss.\n\nThey can be in rocks, on paths, in the grass etc.",
            date = "2012-12-16T07:40:57-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30065#comments:id=1782356",
        },
        {
            id = 1787725,
            score = 2,
            author = "Pandecio",
            text = "As far as I've seen, the best place to complete most of the quests in the Jade Temple Grounds is where you can find the sutras for the Saving the Sutras (http://www.wowhead.com/quest=30064) quest.\n\nYou can find the Sutras easily in the rocks surrounding the clearing; plus it seems to have an abundance of arrows for Arrows of Fortune (http://www.wowhead.com/quest=30065). The three Guardians there can be used for both the Hidden Power (http://www.wowhead.com/quest=30066) quest and as tanks/support for The Darkness Around Us (http://www.wowhead.com/quest=30006) and Behind the Masks (http://www.wowhead.com/quest=30063) quests, specially if they are empowered by the scrolls.\n\nPretty much all daily quests for this particular place can be completed in 4-5 minutes at good pace.",
            date = "2012-12-26T14:29:07-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30065#comments:id=1787725",
        },
        {
            id = 1776343,
            score = -2,
            author = "edgeblade",
            text = "This seems to be bugged now. I click them and nothing happens.",
            date = "2012-12-05T22:03:46-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30065#comments:id=1776343",
        },
    },
    [30066] = {
        {
            id = 1737138,
            score = 14,
            author = "sorceressdee",
            text = "I found these guys a little hard to see or click since they're mostly swarmed by the Doubt elementals around them, so pressing ctrl+V should help with that.  If you're clicking the item and it's not giving you credit, check that they don't already have the buff \"Transcendance\" and that you aren't trying to click an Elder\n\nAlso a great quest to do while on The Darkness Around Us (http://www.wowhead.com/quest=30006)",
            date = "2012-10-10T03:00:11-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30066#comments:id=1737138",
        },
        {
            id = 1768286,
            score = 6,
            author = "1051443",
            text = "I found the easiest way to target these guys is to target a mob, then click its target. Once you have done that , simply use the item in your bag that looks like a open book.",
            date = "2012-11-26T17:01:16-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30066#comments:id=1768286",
        },
        {
            id = 1782954,
            score = 4,
            author = "SvartStillhet",
            text = "Conveniently, there are four Yu'lon Guardians standing right outside the building where you get this quest, and the buff placed on them after using the Stack of Mantras only lasts 45 seconds, making it quite easy to complete in less than 2 minutes.",
            date = "2012-12-17T08:11:56-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30066#comments:id=1782954",
        },
        {
            id = 1751646,
            score = 3,
            author = "gotic",
            text = "You have to look after Yu'lon Adept or Yu'lon Guardian. They are in the middle of the fight with Final Doubt or Lingering Doubt. You can make also this macro: /tar Yu'lon\n\nWhen you are near them click on them after the scroll \"Stack of Mantras\".",
            date = "2012-10-27T09:23:18-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30066#comments:id=1751646",
        },
        {
            id = 1761276,
            score = 3,
            author = "anthem47",
            text = "This may be a result of my poor latency, but I find if you spam the item, you can get a second item in the air before the buff from the first one registers, allowing you to get double credit per NPC.",
            date = "2012-11-12T06:26:06-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30066#comments:id=1761276",
        },
    },
    [30067] = {
        {
            id = 1737147,
            score = 43,
            author = "sorceressdee",
            text = "The mob you need to kill has about 9.6M health and is at 57:62, but using the bell weakens and stuns it, so your hits do about 10x more damage. You can click the bell more than once in a fight, but there's a cooldown on it during which it won't be clickable. Should be very easy to survive for that time though.",
            date = "2012-10-10T03:12:24-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30067#comments:id=1737147",
        },
        {
            id = 1857915,
            score = 3,
            author = "Darneas",
            text = "I didn't know about the bell the first time I did this fight. I saw it the third time I had to take him down and pushed on it. It will save you a lot of headache since it weakens and stuns him for a period. So, hit the bell as often as you can.",
            date = "2013-05-25T20:17:12-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30067#comments:id=1857915",
        },
        {
            id = 1864266,
            score = 3,
            author = "360683",
            text = "Ok come out of the building where the quest giver is, turn right and fly down hill, you see boss do not attack, behind him is the bell fly to that and click on it, I did that and got him to half health before a thing came up on screen and then you click bell again...two rings and Quasimodo was down.",
            date = "2013-06-08T12:35:39-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30067#comments:id=1864266",
        },
        {
            id = 1938436,
            score = 3,
            author = "Wimbleton",
            text = "Good to know about the Bell. Why didn't the quest giver mention something? Oh yes, \"an ancient instrument of power...\" So for us literal-minded people, ancient means ancient, which means \"not contemporary\" instrument of power, hence useless in the fight.\n\nOh wait, it's a puzzle to be solved, right? I guess. But now that we've solved it (many thanks to all the posters here, by the way), what's left? Wait, what was that grinding noise?\n\nActually the part I really liked best is that when the Sha kills you, you get sent to a graveyard from which you can't get back to your corpse, so you'll need to take a 65G armor repair bill. That was well-thought-out. Like icing on the cake.\n\nNevertheless, once you learn about the Bell, this is worth doing. 420 rep vs. 300 for the other three quests. That rings my bell!",
            date = "2014-01-27T13:24:11-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30067#comments:id=1938436",
        },
        {
            id = 1803912,
            score = 2,
            author = "1084124",
            text = "I am revered with the golden lotus and I can do all the other quests, but am unable to pick this one up.  Not sure if there is something else that I have to do.",
            date = "2013-01-25T10:07:59-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30067#comments:id=1803912",
        },
    },
    [30068] = {
        {
            id = 1735562,
            score = 217,
            author = "lightclaw",
            text = "This is a daily from the Temple of the Jade Serpent.  Your job is to put out fires using a dragon (found to the left of the door as you exit) that spits water.  There are a couple of quirks in the quest.\n\nThe fires are sha-colored, silver and white, rather than red in any way.  They look like evil magic swirling around the base of trees.\n\nThe dragon can only breathe water that it has collected, so you must find a pure spring of water for it to gather before you can put out a fire.  The springs are easy to find, they are bright blue pools in any of the water in the Temple area.  However, collecting them can be glitchy.  When you get close to them, they burst upward and the dragon collects the water.  In order for this to happen, the water has to hit you, the player, rather than the dragon's mouth.  If the water hits the dragon's head, you won't be able to use your ability.  Instead, aim for the dragon's belly and the quest will proceed more smoothly.\n\nYou can take multiple shots per pool if you quickly use the water ability and then, before it finishes casting, hit the fire button again.  You get the targeting mark and can fly around a bit looking for another fire to put out as long as you don't click anything (use arrow keys to move, I mean.)  If you're very fast you can get three shots out of one pool, but two is more reasonable.",
            date = "2012-10-08T11:11:39-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30068#comments:id=1735562",
        },
        {
            id = 1739418,
            score = 65,
            author = "Avareal",
            text = "In case you missed it, you need to hop on the War Serpent right outside of the little hut you get the quest.\n\nWhen putting out the flames, make sure you are not trying to douse the black/grey circles on the ground that the Lingering Doubts spawn out of.  Those aren't the fire.  The fire is whitish/bluish/greyish/blackish flames that flicker and are relatively large and easy to spot.\n\nAlso, you can only hold one water blast before you can get another.  So get one and use it.  Rinse and repeat.",
            date = "2012-10-12T09:36:36-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30068#comments:id=1739418",
        },
        {
            id = 1752179,
            score = 24,
            author = "61320",
            text = "You can actually spit the mouthwash twice, and here's how: move to a location with two sha fires, spit on one and, while the mouthwash is in the air, target and spit at another one.\nOr, you can target while already spitting elsewhere, but spit again once the first \"load\" is already in the air.\nThis way you only need to collect the water from the pools 3 times, instead of 6.\nThis double spitting is possible because the dragon loses the pool water from its mouth only when the first \"watery missile\" hits the ground.\nMaybe, if you fly high enough, you can hit 3 sha fires, I haven't tested that.",
            date = "2012-10-27T23:09:10-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30068#comments:id=1752179",
        },
        {
            id = 1759634,
            score = 9,
            author = "andreicmello",
            text = "You only lose the water \"charge\" when the spit hits the flame, so if you're fast enough you can use the same water charge in 2 or even 3 flames!",
            date = "2012-11-09T05:15:08-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30068#comments:id=1759634",
        },
        {
            id = 1747313,
            score = 8,
            author = "Catalyst8487",
            text = "I found that flying over them then walking/riding backwards into the water worked really well when trying to collect it.",
            date = "2012-10-21T15:46:46-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30068#comments:id=1747313",
        },
    },
    [30069] = {
        {
            id = 5884304,
            score = 5,
            author = "Yagi",
            text = "Panderia REMIX\n\nIf you get ported back to the boat and can't get back down, GO TO THE EDGE AND MOUNT UP....FLY STRAIGHT OUT AND THEN DOWN....good luck!\n\nHope this helps from someone who deleted a few toons.",
            date = "2024-06-20T04:08:56-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30069#comments:id=5884304",
        },
        {
            id = 1698605,
            score = 0,
            author = "slayer50513",
            text = "A reference to the book written by a German Field Marshal - Moltke the Elder - which is titled \"Theory of War\" in which the summarized thesis contains the famous following line: \"No plan survives contact with the enemy.\"",
            date = "2012-08-11T08:20:45-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30069#comments:id=1698605",
        },
        {
            id = 1715498,
            score = 0,
            author = "dipiddy",
            text = "Gear-Greasers (Goblin NPCs) are all over, typically hammering away (listen for the mining sound). They'll be the first bottleneck in Pandaria.\n\nThe NPC to turn in the quest has been bugged on and off throughout beta. If you're by the yellow question mark but you can't see him or click on him, you'll probably have to relog.",
            date = "2012-09-18T10:19:53-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30069#comments:id=1715498",
        },
    },
    [30070] = {
        {
            id = 1720797,
            score = 34,
            author = "callenture",
            text = "The trick to this one is to click on the portals ASAP after Ga'trul does. This will send you flying across the room right after him and you won't get hit by all of the spells that he starts casting.",
            date = "2012-09-26T21:15:22-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30070#comments:id=1720797",
        },
        {
            id = 1719217,
            score = 20,
            author = "591906",
            text = "After Ga'trul dies-\n\nRell Nighwind says: King's mercy - what happened here? What WAS that thing?\nTaran Zhu says: Your foe was overwhelmed by a dark energy we call the \"Sha.\" It thrives on negative emotions, such as doubt.\nTaran Zhu says: It has been many years since I have seen it manifest so dramatically.\nRell Nighwind says: I am not surprised. The Horde are monsters!\nRell Nighwind says: We are here on a peaceful rescue mission - will you help us?\nTaran Zhu says: I have seen your Sky-fortress. Your people have an interesting notion of \"peace.\"\nRell Nighwind says: Left to their own devices, the Horde will overwhelm your land. Will you not help us fight them?\nTaran Zhu says: We are not afraid to fight. Our warriors, while few in numer, are extremely skilled.\nTaran Zhu says: But we will not participate in this... genocidal... bloodbath of yours.\nTaran Zhu says: Your conflict will have immense consequences here. Do NOT bring your war to these shores!",
            date = "2012-09-25T21:05:02-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30070#comments:id=1719217",
        },
        {
            id = 1718341,
            score = 16,
            author = "sandyra",
            text = "In order to complete this quest:\n\nKill https://www.wowhead.com/npc=66276 in the room at the top of the keep\nRead the book https://www.wowhead.com/object=215878 on the altar next to where he is slain (if you don't read this, you can't hand in the quest!)\nHand this in to https://www.wowhead.com/npc=66581 who spawns just inside the doors of the room you're in",
            date = "2012-09-25T05:40:38-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30070#comments:id=1718341",
        },
        {
            id = 1981119,
            score = 14,
            author = "luxnova",
            text = "Might be worth noting that when he transforms and stuns you, the stun effect is actually a buff and can simply be clicked off.",
            date = "2014-07-16T11:03:05-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30070#comments:id=1981119",
        },
        {
            id = 1752112,
            score = 10,
            author = "PriestessAur",
            text = "It is no longer necessary to read the book https://www.wowhead.com/object=215878 in order to complete the quest. You only need to kill Ga'trul.\n\nAfter Ga'trul dies, the area is phased until you complete the turn-in to Rell so you don't need to worry about Ga'trul respawning on you.",
            date = "2012-10-27T21:08:15-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30070#comments:id=1752112",
        },
    },
    [30072] = {
