        {
            id = 1942047,
            score = 7,
            author = "Ainmhi",
            text = "Quest was bugged for me. Could get the quest but couldn't loot the Raw Silk. Basket and building showed properly, but when I \"used\" the basket, nothing was added to my inventory. Checked my mail at Halfhill a few minutes later to find a Raw Silk in the mail from the Postmaster for every loot attempt  I made.\n\nIf you don't get the Raw Silk in your inventory from looting the basket, run to Halfhill and check your mail. Should be there!",
            date = "2014-02-09T23:35:02-06:00",
