        {
            id = 1747470,
            score = 1,
            author = "Fluffmeister",
            text = "Once you get hit by a barrel, you're stunned, and stay stunned for ages, and can't do a thing. Then before you recover, you get hit by another barrel, and stay stunned for ages again, and die.\n\nSo avoid getting hit by a barrel!",
            date = "2012-10-21T21:16:51-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30075#comments:id=1747470",
        },
