        {
            id = 1758891,
            score = 5,
            author = "Demonae",
            text = "Screw you Blizzard, I don't care if people down-vote this comment, this quest is just horrible!\n\nI normally have my sound off, but I just happened to be listening to the new MoP music when I did this, and the damn things cry out in pain and distress. They even have more than one soundtrack!\n\nI tried skipping it, but you have to complete it as one of the three quests to go to the next step.\n\nFeels like kicking puppies or something, I really find it inappropriate, even in a game setting.",
            date = "2012-11-07T18:01:20-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30076#comments:id=1758891",
        },
    },
