    [30081] = {
        {
            id = 1720187,
            score = 30,
            author = "Ulgoth",
            text = "The salt drops off the Weeping Horrors.\n\nThe fish are in the bottom of the dry pool. They're a bit hard to make out because of the Sha effect going on there.\n\nThe honeycombs are in the trees around the area, as in the screenshots.",
            date = "2012-09-26T13:29:02-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30081#comments:id=1720187",
        },
        {
            id = 1721192,
            score = 9,
            author = "Tenjen",
            text = "how in hell did he think a SUPER laxative was gonna help them?\n\nhe tests it on one sad panda and the dude charges into the bushes, groaning and moaning while in there.\n\n\" It's the ONE thing that can ruin his day... \"\n\n/facepalm\n\nhe thought they were all suffering from...well ya know..",
            date = "2012-09-27T03:52:47-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30081#comments:id=1721192",
        },
        {
            id = 1767958,
            score = 8,
            author = "Sketchie",
            text = "After turning in Materia Medica, a scene will occur.\n\nKen-Ken says: Alright, now we need someone to test this on...\nKen-Ken says: You! Get over here, mopesy. Ken-Ken got just the thing for you!\n\nDespondent Warden of Zhu wanders up to Ken-Ken slowly, obviously filled with despair.\n\nDespondent Warden of Zhu says: Who, me?\nDespondent Warden of Zhu says: Sure, it's not like things could get any worse...\nKen-Ken says: Here, drink this.\n\nKen-Ken hands Despondent Warden of Zhu a potion. Despondent Warden of Zhu drinks the potion.\n\nDespondent Warden of Zhu's gut churns violently.\n\nDespondent Warden of Zhu says: Oh... ughh... what have you done with me?\n\nDespondent Warden of Zhu quickly runs behind the tree across from Ken-Ken.\n\nKen-Ken yells: Hahaha! it worked! Ken-Ken KNEW it would work! You feelin' better now?\nDespondent Warden of Zhu yells: Ughh... urrggg...\nDespondent Warden of Zhu yells: NO!\n\nSeeing how it was a mixture of fish, honey and salt, I wouldn't be surprised with Despondent Warden of Zhu's reaction to the potion. ^^;",
            date = "2012-11-25T23:02:27-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30081#comments:id=1767958",
        },
        {
            id = 1728316,
            score = 7,
            author = "cephadex",
            text = "I've been wondering when they'd get to the \"and that makes me a sad panda\" jokes =)",
            date = "2012-10-02T05:38:33-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30081#comments:id=1728316",
        },
        {
