            sourceUrl = "https://www.wowhead.com/quest=30081#comments:id=1938673",
        },
    },
    [30082] = {
        {
            id = 1720041,
            score = 87,
            author = "178479",
            text = "They see me rollin'...",
            date = "2012-09-26T11:14:56-05:00",
