        {
            id = 1722149,
            score = 71,
            author = "Auryan",
            text = "\"Don't give up, thunderbirds! Come back for me.\"   >_< Yeah, I've had days like that too Yi-Mo.",
            date = "2012-09-27T21:02:24-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30082#comments:id=1722149",
        },
        {
            id = 1767061,
            score = 71,
            author = "442479",
            text = "For the avoidance of doubt: please don't kick or roll depressed people, pandaren or otherwise. It's barely acceptable here because we know the Sha is causing the problems; in the real world there's no monster to kill to fix things for them.",
            date = "2012-11-24T03:23:24-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30082#comments:id=1767061",
        },
        {
            id = 1734070,
            score = 59,
            author = "Rizzatto",
            text = "I saw the quest pop up and I groaned, thinking it was going to be another one of those annoying escort quests.  I was wrong.  This is now one of my favorite quests ever.",
            date = "2012-10-07T03:21:21-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30082#comments:id=1734070",
        },
        {
            id = 1684906,
            score = 52,
            author = "DarkElfIT",
            text = "The goal of this quest is to cheer up a depressed Panda, sadly we are out of anti-depressants in Pandaria. It doesn't matter which of the two first options you pick, just pick this as the second;\n\"I don't have time for this. Move your ass or I'll move it for you\"\nAfter that, you do exactly as you said, you get behind him and move his ass...by kicking it.",
            date = "2012-07-05T18:15:13-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30082#comments:id=1684906",
        },
    },
