    [30084] = {
        {
            id = 1661136,
            score = 9,
            author = "yoshimo",
            text = "Memorial Flame of Zhu: 72.74/18.07\nMemorial Flame of Po:  75.14 /17.23\nMemorial Flame of Rin:  71.26/17.68",
            date = "2012-05-01T03:51:25-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30084#comments:id=1661136",
        },
        {
            id = 1662402,
            score = 8,
            author = "Draugar",
            text = "Memorial Flame of Zhu: is found along the path leading southwest out of Zhu's Watch\nMemorial Flame of Rin: while standing at Memorial Flame Zhu look due west and you should see it just to the side and past the big tree.\nMemorial Flame of Po: while standing at Memorial Flame Zhu look due east, between the row of trees you will see a rock, it is on this rock",
            date = "2012-05-03T23:54:40-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30084#comments:id=1662402",
        },
        {
            id = 1832899,
            score = 3,
            author = "431581",
            text = "If you have TomTom, you can use the following commands to find the fire pits:\n/way 72.74 18.07 Memorial Flame of Zhu\n/way 73.91 16.79 Memorial Flame of Po\n/way 71.26 17.68 Memorial Flame of Rin",
            date = "2013-03-22T17:11:02-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30084#comments:id=1832899",
        },
        {
            id = 1788624,
            score = 2,
            author = "myrkat",
            text = "I've done this quest on two other characters, but the last time I did it, the flame of Po was not spawned on the rock.  No problems with the other two memorials or lighting them.  Po was not to be found, nor did attempting to use the flame quest item (http://www.wowhead.com/item=78928) in the right spot seem to work.\n\nI even quit to desktop / re-launched WoW, logged in... and it still was not spawning on the rock (75,17).\n\nUPDATE:  I found the Memorial Flame of Po at coordinates 73.9, 17.0 (West-North-West from the \"old\" rock, behind a tree).",
            date = "2012-12-28T13:04:11-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30084#comments:id=1788624",
        },
        {
            id = 1967569,
            score = 1,
            author = "chronofusion",
            text = "In case anyone is getting lost or confused.  The precise location of the Memorial of Po is 74,17 but NOT in \" Valley of the Four Winds \"  ( state or province as I call it in the COUNTRY of Pandaria), but in the \"state\" of Krasarang Wilds\".\n\nIt is MOSTLY directly SOUTH of Zhu's Watch Village with a tad bit of WEST.  thus 74,17.\n\nI'm submitting a screen shot showing ALL three Memorials after I lit them up within view if your \" View Distance\" in Enviroment/system graphical in game settings are set to either High or Ultra.\n\nMy toon is at precisely 72.8,16.  Hope this helps.",
            date = "2014-05-24T19:59:28-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30084#comments:id=1967569",
        },
    },
    [30085] = {
