    [30086] = {
        {
            id = 5303021,
            score = 6,
            author = "climber",
            text = "I’ve completed the ‘Chen and LiLi’, ‘A Seemingly Endless Nuisance’ and ‘A Poor Grasp Of The Basics’ quests, but Xiao no longer exists so this quest can’t be acquired.",
            date = "2021-12-29T02:19:26-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30086#comments:id=5303021",
        },
        {
            id = 1802520,
            score = 5,
            author = "512749",
            text = "I had a bug where after the completion of Chen and Li Li (http://www.wowhead.com/quest=29907) (with no difference in quests complete) my friend was able to obtain this quest and the following ones and I was not able to. I talked to a GM about it. If you have this same bug you must complete the quests: A Seemingly Endless Nuisance (http://www.wowhead.com/quest=29908) and A Poor Grasp of the Basics (http://www.wowhead.com/quest=29877) in order for Xiao to finally offer this quest and his following quests.",
            date = "2013-01-22T14:26:30-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30086#comments:id=1802520",
        },
        {
            id = 1759923,
            score = 4,
            author = "Sketchie",
            text = "Once you accept the quest, a brief scene will occur with Xiao, Lin Tenderpaw, Clever Ashyo, Kang Bramblestaff and Ken-Ken.\n\nLin Tenderpaw says: So... do any of you know where the hidden master lives?\nXiao says: I'm pretty sure that's why he's called the hidden master, Lin.\nLin Tenderpaw says: Oh. Sorry.\n\nLin Tenderpaw blushes.\n\nLin Tenderpaw says: So, where should we search first?\nClever Ashyo says: I can try asking the streams for guidance...\n\nClever Ashyo is almost immediately interrupted by Kang Bramblestaff.\n\nKang Bramblestaff: Ask the streams? You're no elder, Ashyo. You're not even a jinyu grown yet. It would be a waste of your time.\nKen-Ken says: Ken-Ken thinks we split up. Follow the four winds.\nKang Bramblestaff says: That's a much better idea, Ken-Ken. I volunteer to travel south, into the jungle.\n\nKang Bramblestaff departs.\n\nClever Ashyo says: I will follow the north wind.\nKen-Ken says: Ken-Ken go chase east wind. Shortest walk.\nLin Tenderpaw says: I... I suppose I'll go west, then.\nXiao says: Very well. As the oldest and fattest among us, I will wait here for each of you to return.\nXiao says: Good luck, friends. Once we find the Hidden Master, we can continue our training.\n\nClever Ashyo, Ken-Ken and Lin Tenderpaw all depart.",
            date = "2012-11-09T17:21:45-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30086#comments:id=1759923",
        },
        {
            id = 1753492,
            score = 1,
            author = "noamchomsky",
            text = "Anyone know the prerequisite quests to get this quest?",
            date = "2012-10-29T22:52:45-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30086#comments:id=1753492",
        },
        {
            id = 1844472,
            score = 1,
            author = "1106580",
            text = "Does anyone know if you can get the other three to the Hidden Master? I know Lin finds him, and then I told the others about him and they said they'd head over there soon, but they didn't leave their respective areas. Do they ever go over there?",
            date = "2013-04-18T02:34:50-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30086#comments:id=1844472",
        },
    },
