        {
            id = 2224629,
            score = 10,
            author = "Hypathia",
            text = "The warden of Zhu's Watch actually reference Eeyore (from Winnie-the-Pooh) when you talk to them for this quest:\n\nWarden: \"Not much of a day. Just right for not much of a life.\"\nEeyore: \"Not much of a house. Just right for not much of a donkey.\"\n\nWarden: \"It's raining still. And freezing. At least we haven't had a typhoon lately.\"\nEeyore: \"“It's snowing still. And freezing. However, we haven't had an earthquake lately.”",
            date = "2015-08-03T13:40:54-05:00",
