    [30090] = {
        {
            id = 1661575,
            score = 94,
            author = "StansDad",
            text = "After you have used your mask on the villagers that are wandering around, Ken-Ken the monkey will tell you to use your mask on Yi-Mo, who will spawn by the well.\n\nYi-Mo will despawn after a while if you do not complete the task, but can be re-spawned by going back to Ken-Ken the monkey and speaking with him.",
            date = "2012-05-02T00:47:34-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30090#comments:id=1661575",
        },
        {
            id = 1684877,
            score = 23,
            author = "642587",
            text = "This quest is the culmination of the Zhu's Watch chain. It is a reference to Zhu's Hope, a space colony in the videogame series Mass Effect, where the inhabitants are driven to madness by a mysterious alien presence.",
            date = "2012-07-05T16:33:12-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30090#comments:id=1684877",
        },
        {
            id = 1663485,
            score = 18,
            author = "979234",
            text = "When you used mask on the 8 first ones, head back to Ken-Ken and speak with him, he will then phase into another phase and you will put mask on the Yi-Mo.",
            date = "2012-05-06T14:56:13-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30090#comments:id=1663485",
        },
        {
            id = 1767971,
            score = 14,
            author = "Sketchie",
            text = "Once you accept Zhu's Despair, the following happens:\n\nKen-Ken says: What the... Sha nasties are poppin' out everywhere! We gotta take care of them first!\n\nYou will then need to kill 8 Essence of Despair, but you will not be alone - Ken-Ken will accompany and fight the essences with you. If you try to put the mask on Yi-Mo Longbrow without killing 8 essences, Ken-Ken will remind you that you still have to kill the essences. So do so. The Essences of Despair are very easy to kill - they only have about 92k health.\n\nOnce you have killed 8 Sha Essences, go to Yi-Mo and put the mask on him. It will cause a Quintessence of Despair to pop out. He has about 327k health and doesn't hit hard, but he can stun you for a few seconds. It is a very easy fight overall.\n\nAfter you've defeated the Quintessence of Despair, you will be knocked out. The screen fades to black.\n\nKen-Ken says: ! Are you okay? Wake up!\n\nThe screen then fades back to normal.\n\nYi-Mo Longbrow says: He's coming to!\nYi-Mo Longbrow says: ... To think you'd risked your life to save me - twice now - and I'd only treated you with disdain.\nYi-Mo Longbrow says: I am shamed beyond comprehension. Please forgive me - my mind was not my own.\nYi-Mo Longbrow says: Should you ever need aid of any kind, from a handful of turnip seeds to a volley of arrows, know that Zhu's Watch will provide it.\nYi-Mo Longbrow says: For now, I must direct my attention to rebuilding the village. There is much to be done. You may rest here if you like, but we'll not accept any more help.\n\nYi-Mo Longbrow departs.\n\nKen-Ken says: We did it, ! That was some good butt-punchin' back there!\nKen-Ken says: Something tells Ken-Ken that's not the last of the sads, though...\n\nKen-Ken jogs back to his usual spot at Zhu's Watch where you can turn in the quest with him.",
            date = "2012-11-25T23:30:30-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30090#comments:id=1767971",
        },
        {
            id = 1691572,
            score = 8,
            author = "602730",
            text = "If you get curious like I did and enter the inn to see what's inside (or just generally go out of the questing area for whatever reason), you will exit the phase and be unable to see the essences of despair.  But like a previous commenter mentioned, you can talk with Ken-Ken again and re-enter the phase.",
            date = "2012-07-24T03:35:28-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30090#comments:id=1691572",
        },
    },
