    [30124] = {
        {
            id = 1743580,
            score = 10,
            author = "raistlyn",
            text = "It is interesting to note here that Kor calls the Sunwalkers \"pacifist sun spirit filth,\" while on the Alliance side of this same quest, Lyalia calls the Sunwalkers the \"most militant branch of the tauren armies within the Horde.\"\n\nWhich can only make me wonder what on earth the least militant branch would look like and what Kor would call that.",
            date = "2012-10-16T19:01:54-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30124#comments:id=1743580",
        },
        {
            id = 1859724,
            score = 10,
            author = "torin23",
            text = "As a tauren paladin, I wanted to just not do this quest.  But the quest chain doesn't move forward if I don't.  Grr.  Want to smack Kor up the head with my Hammer of Justice...",
            date = "2013-05-29T17:30:51-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30124#comments:id=1859724",
        },
        {
            id = 1687411,
            score = 4,
            author = "ldene",
            text = "Offered by Kor Bloodtusk at Thunder Cleft in Krasarang Wilds. The mob u need is patrolling on a saber mount a little south of the village. Both saber and rider will attack you but the saber will dispawn when the rider is dead.",
            date = "2012-07-12T15:54:05-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30124#comments:id=1687411",
        },
        {
            id = 1724593,
            score = 2,
            author = "884267",
            text = "I can't say I approve of his opinion of the tauren..",
            date = "2012-09-29T13:35:10-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30124#comments:id=1724593",
        },
        {
            id = 1986847,
            score = 1,
            author = "405918",
            text = "Not sure if this is recent, but now the Darnassian Outrider is followed by four lvl 86-90 Nightsabers. Not really that difficult to kill them with an AoE, but it's something I hadn't noticed before.",
            date = "2014-07-31T15:56:05-05:00",
