    [30137] = {
        {
            id = 1980034,
            score = 21,
            author = "Engrelled",
            text = "I encountered the \"can't pick up the eggs\" problem and came here. Then I re-read the quest text which says: \"Unless you're crazy enough to sneak into the saurok camp to the east and retrieve some stolen cloud serpent eggs, I'm afraid I can't help you.\"  For THIS quest, you have to get them from the Slitherscale camp on the East side of the island where the ground is brown - no grass.  As of today they were gold, green, or blue, just like the serpents, and are sparkling like mad.",
