    [30138] = {
        {
            id = 1696491,
            score = 410,
            author = "retro",
            text = "The color variations are as follows, for reference in color choice.\n\nBlue Serpent Egg (http://mop.wowhead.com/item=78962) will look like Hyacinth (http://mop.wowhead.com/npc=58517) and rewards you with Reins of the Azure Cloud Serpent (http://mop.wowhead.com/item=85430)\nGreen Serpent Egg (http://mop.wowhead.com/item=78960) will look like Li Ying (http://mop.wowhead.com/npc=58518) and rewards you with Reins of the Jade Cloud Serpent (http://mop.wowhead.com/item=79802)\nYellow Serpent Egg (http://mop.wowhead.com/item=78961) will look like Sun (http://mop.wowhead.com/npc=58519) and rewards you with Reins of the Golden Cloud Serpent (http://mop.wowhead.com/item=85429)\n\nAfter you have completed the chain, earned Exalted and obtained your Serpent, you will be able to purchase the other 2 colors from San Redscale (http://www.wowhead.com/npc=58414) for 2100g/ea(Exalted Price)\n\nYou may also save yourself some gold if you have other level 90 alts and would rather do this questline (and reach Exalted with them) for each different color.",
            date = "2012-08-05T18:10:10-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30138#comments:id=1696491",
        },
        {
            id = 1727906,
            score = 114,
            author = "glycereth",
            text = "Choose your Pokemon:\n1. Charmander - Yellow Serpent Egg\n2. Bulbasaur - Green Serpent Egg\n3. Squirtle - Blue Serpent Egg",
            date = "2012-10-01T20:42:30-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30138#comments:id=1727906",
        },
        {
            id = 1733512,
            score = 53,
            author = "784507",
            text = "After choosing your egg, you speak to Instructor Tong (http://www.wowhead.com/npc=58225) again to get a new quest. At this time, you are given the option to change your egg. Just in case. Once you accept the next quest, this option is no longer available.",
            date = "2012-10-06T14:40:08-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30138#comments:id=1733512",
        },
        {
            id = 1932466,
            score = 41,
            author = "KillashandraRee",
            text = "This is what you get from each egg....(credit goes to liyluh from this post Blue Serpent Egg (http://www.wowhead.com/item=78962#comments))\n\nBlue Serpent Egg (http://www.wowhead.com/item=78962#comments) awards Azure Cloud Serpent (http://www.wowhead.com/item=85430)\nYellow Serpent Egg (http://www.wowhead.com/item=78961) awards Yellow Cloud Serpent (http://www.wowhead.com/item=85429)\nGreen Serpent Egg (http://www.wowhead.com/item=78960) awards Jade Cloud Serpent (http://www.wowhead.com/item=79802)\n\nAs previously stated by others, you can get one egg on one toon and the other two eggs on alt toons, and save yourself the cost of buying the other two eggs.\n\nCheers \\o/",
            date = "2014-01-07T08:26:55-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30138#comments:id=1932466",
        },
        {
            id = 1868954,
            score = 8,
            author = "1128569",
            text = "OK, I ran /run print(IsQuestFlaggedCompleted(30138)) and it returned \"1\", meaning I have done this quest, but for the life of me I can't find my egg nor can I remember what color I chose. Instructor Tong does not offer \"The Rider's Journey\" nor a option \"Help! I've lost my egg.\" I'm currently doing OotCS dailies and am 10170/12000 - Honored. Also, I read about the Onyx Eggs and their benefits to grinding rep, so I went out today and found 8 in 15-20 minutes, turning them in for 550 rep each.  My questions are:\n\n1) Where is the default storage location of these eggs?\n\n2) Where should I be looking for mine?\n\n3) If I still can't find my egg, can I somehow figure out which color I chose?",
            date = "2013-06-21T10:53:13-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30138#comments:id=1868954",
        },
    },
    [30139] = {
        {
            id = 1845365,
            score = 5,
            author = "735486",
            text = "I had turned in Choosing the One and I had this quest.  I noticed the quest guy had a bubble to change my egg so I wasn't worried.  Suddenly I thought, \"I'd better log out and check which colors my rogue and shaman took\" because I wanted to do all 3 colors.  Well it turned out I had picked a duplicate color.  I went back and the quest guy wouldn't let me change my egg.\n\nI abandoned the quest.  When I took the quest again, he didn't ask me what egg I wanted.  There was just a bubble that said I lost my egg.  I picked that and he scolded me and gave me the same color egg again.  After that I came here to look for info.  When I went back to wow again, he was suddenly giving me the choice to change my egg.\n\nI guess the moral is -- if you want to change your egg color, just come to wowhead and the wow gods will smile upon you!",
            date = "2013-04-20T22:26:59-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30139#comments:id=1845365",
        },
    },
