    [30145] = {
        {
            id = 1770707,
            score = 145,
            author = "543619",
            text = "\"Keep straying and I will not hesitate to fail you\"\n\n-Instructor Windblade randomly dismounts and plummets into ocean-\n\nMe - \"Now who's failing, &*%^?\"",
            date = "2012-11-28T22:32:36-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30145#comments:id=1770707",
        },
        {
            id = 1731003,
            score = 134,
            author = "amgyn",
            text = "Worked for me on Oct 4, 2012.\n\nJust gotta keep at least 1-3 buffs on yourself and you will keep up with her no problem.\n\nNot sure what makes her despawn for others.",
            date = "2012-10-04T08:53:41-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30145#comments:id=1731003",
        },
        {
            id = 1755975,
            score = 58,
            author = "cinb40",
            text = "Tried this several times and got totally frustrated with it..... came here and read all the comments about what a horrid quest it was..... IT'S ALL TRUE!\n\nSimple way to beat it...... mount dragon.... fly thru as many of the cloud rings as you can or Instructor Windblade will out distance you and you have to start again. No matter what rate flying you have if you don't use the cloud rings you'll never get this quest completed",
            date = "2012-11-03T00:41:40-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30145#comments:id=1755975",
        },
        {
            id = 1728370,
            score = 47,
            author = "Daedelus",
            text = "As of 2nd Oct 2012 this quest appears to be bugged.  After following Instructor Windblade half way round the course she despawns just after saying \"You must fly through all 10 checkpoints before you can finish the race.\"\n\nI have tried it several times and she always despawns in exactly the same place.  Completing the course does not give you credit for the quest.",
            date = "2012-10-02T07:01:32-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30145#comments:id=1728370",
        },
        {
            id = 1730597,
            score = 35,
            author = "930321",
            text = "Alright I was having problems with this quest but as was said she despawns when you barely make any distance on her.\n\nI did log out and then I made sure to go through some cloud hoops and that seemed to do it.\n\nIn fact I went really far away from her to go into a hoop and she didn't despawn.\n\nLogic? There is none but that seems to work.",
            date = "2012-10-04T00:40:20-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30145#comments:id=1730597",
        },
    },
    [30146] = {
        {
            id = 1721594,
            score = 78,
            author = "lightclaw",
            text = "As the quest text reads, you can catch these from any fresh or salt water in Pandaria, both from pools and open water.  I was able to catch them in multiple zones as well.  They are a 100% drop rate item from any successful catch.  If you're catching trash items, you will not get minnows.  For people with low level fishing, just fish from any pool and you'll be done in no time.\n\nI wasn't  able to check in Dread Wastes or Townlong, but Sugar Minnows were not dropping from the sha-touched water at Inkgill Mere in Kun Lai.  Makes sense, as it's neither fresh nor salt.",
            date = "2012-09-27T09:13:44-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30146#comments:id=1721594",
        },
        {
            id = 1859508,
            score = 38,
            author = "Oogzy",
            text = "If you are of low fishing skill, such as I was when doing this quest, be sure to fish in pools instead of open water. If you're fishing in open water, it will take a very, very long time (I went from 75 fishing to 210 while doing it that way.) If you fish in pools, however, you will catch them 100% of the time.",
            date = "2013-05-29T05:47:10-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30146#comments:id=1859508",
        },
        {
            id = 1814512,
            score = 9,
            author = "875326",
            text = "While on this quest, any time you fish up an actual fish, you will also get a Sugar Minnow. Don't do what I did and go 100+ casts without seeing a single one and filling your bags with junk. If you are on this quest, fish in schools. Every cast is guaranteed to get you two fish- a cooking ingredient and a Sugar Minnow.\n\nEdit: I see a lot of people getting pool and school confused. To clarify, a pool is any fishable water, and a school is a clump of fish with mouseover text telling you what kind it is. The Sugar Minnows are 100% drop rate from schools, but have an abysmal drop rate from pools. You need not have any fishing skill to catch fish from schools, so seriously, fish those.",
            date = "2013-02-16T20:52:01-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30146#comments:id=1814512",
        },
        {
            id = 3191290,
            score = 9,
            author = "blizzard60",
            text = "Sri-la village on the pier (/way 56, 22). I caught one almost every cast. GL! /bow",
            date = "2020-02-20T18:47:34-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30146#comments:id=3191290",
        },
        {
            id = 1838911,
            score = 8,
            author = "821994",
            text = "Even if your fishing skill is high, 'always' FISH SCHOOLS for the https://www.wowhead.com/item=79046.  Buy your carp (see \"A Feast for the Senses\") inexpensively on the AH and use or sell the schooled fish you've caught.\n\nThis will prove you more intelligent than even a schooled fish /wink\n\nSome have commented that this isn't worth doing because of its low rep.  If you leave some carp in your mailbox (btw, these won't smell) and fish the school of your choice (you can sit on the q for a day until you're at your favorite fishing hole); getting 20G and 125+ rep for fishing something you need is worthwhile.\n\nPS - If you don't have Argent Squire/Gruntling mail . . . there's a box in Sri La.  It's also not a bad hearthstone location while farming this rep.",
            date = "2013-04-04T10:10:22-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30146#comments:id=1838911",
        },
    },
    [30147] = {
