    [30149] = {
        {
            id = 1696482,
            score = 67,
            author = "retro",
            text = "Can be done the same time as https://www.wowhead.com/quest=30146.\n\nFish for 10x https://www.wowhead.com/item=74866 in the area near The Arboretum.\n\nYou are taught Fish Cake (http://www.wowhead.com/spell=104297) from https://www.wowhead.com/npc=64231, the Cooking Trainer in Halfhill. The recipe requires Cooking: 300.",
            date = "2012-08-05T17:58:13-05:00",
