    [30157] = {
        {
            id = 1727389,
            score = 17,
            author = "QuickBASIC",
            text = "As always with these kind of quests Shift-V is your friend. Gather up 6 of these buggers and run up the little hill with the hut on it and straight into the nests (surrounded by green rocks).\n\nhttps://www.wowhead.com/item=78947 will dismount you, it can't be cast in https://www.wowhead.com/spell=100205 but can be cast in https://www.wowhead.com/spell=783.\n\nLuckily, https://www.wowhead.com/item=78947 is off the GCD.\n\n#showtooltip Silken Rope\n/tar Winward Hatchling\n/cast Silken Rope\n/cast Albino Drake\n\nLand while mounted, if you stay outta combat for about 1sec, it's safe to assume you can get a 1.5sec mount cast off so click the macro and it will cast the rope and start mounting in the same GCD.\n\nDruid's can replace the mount with:\n\n/cast Swift Flight Form\n\nfor an instant cast rope cast to bird form.",
            date = "2012-10-01T11:53:07-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30157#comments:id=1727389",
        },
        {
