    [30183] = {
        {
            id = 1784311,
            score = 4,
            author = "TegoZanduba",
            text = "Hemet Nesingwary (http://www.wowhead.com/npc=58421) (and Jr. (http://www.wowhead.com/npc=58422)) makes their return in Pandaria in the southwest of the Valley of the Four Winds, and you are tasked with the following masteries:\n\nStalker Mastery (http://www.wowhead.com/quest=30183) -> Fox Mastery (http://www.wowhead.com/quest=30182)\nMushan Mastery (http://www.wowhead.com/quest=30181) -> Mushan Mastery: Darkhide (http://www.wowhead.com/quest=30184)\nTortoise Mastery (http://www.wowhead.com/quest=30185) -> Parental Mastery (http://www.wowhead.com/quest=30186)\n\nFor those curious, there is no Achievement itself for this, and it isn't added to The Collected Quests (http://www.wowhead.com/achievement=941/hemet-nesingwary-the-collected-quests) meta either.  It is though a criteria of Rally in the Valley (http://www.wowhead.com/achievement=6301).\n\nAs your travel near the watery pit outside camp, don't worry about the Ominous Presence (http://www.wowhead.com/spell=110740) that you sense.  It only means that The Beast is Near (http://www.wowhead.com/spell=110845).\n\nAs you progress through the quests, Mr. Pleeb  (http://www.wowhead.com/npc=63825) stuffs your best kills and puts them on display for you on the south side of camp.",
            date = "2012-12-19T21:10:38-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30183#comments:id=1784311",
        },
        {
            id = 1655809,
            score = 2,
            author = "Cielos",
            text = "These beasts are located near the Nesingwary camp in the south west region of the Valley of the Four Winds.",
