    [30184] = {
        {
            id = 1754127,
            score = 6,
            author = "698549",
            text = "While this beast is an elite, and over 600K HPs, it is soloable.\n\nMy lvl 88 rogue with quest greens and blues stealthed up behind him with all my cool downs ready. Ambush, Garotte, Revealing Strike, SnD, Combat Readiness and then Evasion and Killing Spree.\n\nAfter this, Darkhide was down almost 50%, but was beginning to channel his dangerous attack, something called Ground and Pound, as I recall. You will know it is happening when you see rocks and dust fly up around you.\n\nThe natural urge is to fight through it, which I found suicidal, or to run in a straight line away. This is better, but you still take a ton of damage. Instead, run in a circle around the mob so it can't get a chance to face you until he stops channelling and the dust settles, then go back in and fight some more.\n\nBy the end of the battle my 219K HP rougue was still over 50% with no heals, health pots or even using Recuperate. It's the circling motion that made the difference.",
            date = "2012-10-31T00:06:22-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30184#comments:id=1754127",
        },
        {
            id = 1724771,
            score = 3,
            author = "Ezmaroo",
            text = "found him at 26.60,74.83",
            date = "2012-09-29T15:36:09-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30184#comments:id=1724771",
        },
        {
            id = 1751771,
            score = 3,
            author = "Sleutel",
