    [30186] = {
        {
            id = 1663999,
            score = 689,
            author = "StansDad",
            text = "Perhaps I missed some of the preliminary speech, but the quest text gives no indication of actually how to find the place you are looking for.\n\nIf you go to where the \"?\" is indicated on the map you will find yourself in the middle of a grassy plain, and you may even be enveloped in a blue haze - that would be because you are standing over the cave where you need to go.\nThis cave is accessed by diving into the water of the nearby Torjari Pits, where the entrance is located underwater.",
            date = "2012-05-07T18:28:22-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30186#comments:id=1663999",
        },
        {
            id = 5863394,
            score = 196,
            author = "Bathrezz",
            text = "In Panda Remix.\n\nIf you skip the RP and go straight to the quest zone marker, you will entirely miss the secret cave entrance at the bottom of the pond XD",
            date = "2024-05-23T03:08:10-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30186#comments:id=5863394",
        },
        {
            id = 1967931,
