        },
    },
    [30187] = {
        {
            id = 1838940,
            score = 123,
            author = "821994",
            text = "Slow Down!  Have you purchased your https://www.wowhead.com/item=93229 to double your rep gains?\n\nGet it from https://www.wowhead.com/npc=58414 located at 56.7, 44.4 before doing anymore quests.",
            date = "2013-04-04T11:12:19-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30187#comments:id=1838940",
        },
        {
            id = 1756960,
            score = 70,
            author = "168688",
            text = "Here are my coords, formatted for flying *through* the hot air balloons. These coords were also from Carbonite. I have also tried to arrange them in the most direct route.\n\n/way 60.7, 39.4\n/way 59.7, 31.5\n/way 61.3, 25.3\n/way 66.3, 35.9\n/way 66.1, 42.4\n/way 66.8, 51.5\n/way 64.1, 51.0\n/way 61.8, 54.5\n/way 60.4, 52.8\n/way 58.8, 46.8\n\nEDIT: Corrected the 6th point. I had a comma instead of a period in the first number resulting in the point being plotted way north.",
            date = "2012-11-04T11:47:29-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30187#comments:id=1756960",
        },
        {
            id = 1727786,
            score = 47,
            author = "uriahworld",
            text = "This quest seems bugged to me, I can only find 9 Checkpoints (Flags), even the Wowhead map indicates only 9. However, you can go and get a new mount from the quest guy and simply pickup your tenth from a new set of Checkpoints.",
            date = "2012-10-01T18:49:37-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30187#comments:id=1727786",
        },
        {
            id = 1740084,
            score = 31,
            author = "Lolygag7",
            text = "These Checkpoints are not in any special order, just the order I was going at the time. Here are all ten coordinate locations:\n\nCheck Point 1: (60,39)\nCheck Point 2: (59,31)\nCheck Point 3: (61,25)\nCheck Point 4: (66,35)\nCheck Point 5: (66,42)\nCheck Point 6: (66,51)\nCheck Point 7: (64,51)\nCheck Point 8: (61,54)\nCheck Point 9: (60,52)\nCheck Point 10: (58,46)\n\nHope this helps! <3\n\n*I'm not sure if the checkpoints randomize, but so far my checkpoints have all been in the same place every time.",
            date = "2012-10-13T02:32:35-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30187#comments:id=1740084",
        },
        {
            id = 1763784,
            score = 25,
            author = "hootstwo",
            text = "For those of you that have come here after getting most (but not all) of the flags and who don't feel like searching through the coordinates of all the flags for the one(s) you've missed, you can simply dismount and go get your serpent again. All flags are reset and you can simply snag a number to get you up the number you were missing.  Much easier than searching for the one(s) you've missed.",
            date = "2012-11-17T12:48:31-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30187#comments:id=1763784",
        },
    },
    [30188] = {
        {
            id = 1758734,
            score = 69,
            author = "frankly",
            text = "If you are like me and rushed throuh daily's to get revered, then hunting  onyx eggs (http://http://www.wowhead.com/item=89155) to get exalted and end up wondering why this quest isn't popping up: You must have done Flight Training: Full Speed Ahead (http://www.wowhead.com/quest=30145) and Flight Training: In Due Course (http://www.wowhead.com/quest=30187) to make Elder Anli (http://www.wowhead.com/npc=58564) give you this quest.",
            date = "2012-11-07T12:54:24-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30188#comments:id=1758734",
        },
        {
            id = 1786295,
            score = 27,
            author = "138867",
            text = "As an added bonus, you are able to sell your cloud serpent mount back to the vendor if you've already learned it on another toon  :)  750g ka-ching!",
            date = "2012-12-23T16:33:08-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30188#comments:id=1786295",
        },
        {
            id = 1730119,
            score = 12,
            author = "PriestessAur",
            text = "The Cloud Serpent mounts are account-wide but https://www.wowhead.com/spell=130487 needed to ride them is currently not.\n\nhttp://us.battle.net/wow/en/forum/topic/6794349419#18\nCloud Serpent mounts are indeed account-wide. However they require the Cloud Serpent Riding skill, which is a faction requirement and character specific. Characters that meet the faction requirement will see the mount as account-wide. I’ll bring this up with our developers to see if that’s intended.",
            date = "2012-10-03T14:28:56-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30188#comments:id=1730119",
        },
        {
            id = 1736363,
            score = 6,
            author = "dudu2k",
            text = "how do we get this quest?",
            date = "2012-10-09T05:37:28-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30188#comments:id=1736363",
        },
        {
            id = 1872923,
            score = 6,
            author = "obeahshamman",
            text = "You do not require the Wisdom of the Four Winds (http://www.wowhead.com/spell=115913) flight skill in order to use your Cloud Serpent mount in Pandaria once you complete this quest and receive Cloud Serpent Riding (http://www.wowhead.com/spell=130487)",
            date = "2013-07-02T11:33:46-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30188#comments:id=1872923",
        },
    },
    [30189] = {
        {
            id = 1736810,
            score = 30,
            author = "519815",
            text = "Out of all the gifts you can give to all the Tiller's, this is the only one where you get an item as a reward.\n\nReading this quest made me smile.\n\nElla's pretty awesome.",
            date = "2012-10-09T17:10:37-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30189#comments:id=1736810",
        },
        {
            id = 1757192,
            score = 5,
            author = "jcollier",
            text = "This quest is no longer available once you reach \"Best Friend\", so if you wish to max out the bar you will have to wait until one of the dailies that rewards reputation with this NPC comes up in the rotation. The food turn-in quests stop working at \"Best Friend\" too.",
            date = "2012-11-04T18:36:37-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30189#comments:id=1757192",
        },
    },
    [30190] = {
        {
            id = 1729673,
            score = 28,
            author = "jojopojo64",
            text = "One does not simply gather up these NPCs and AoE them down. While they hit for a pathetic amount of damage, the danger with these sprites lies in their Shin Kick (http://www.wowhead.com/spell=127434) ability that stuns quite often and leaves them scampering off to throw more rocks at you. If you're a tank trying to AoE pull, forget it. Their low damage means low Vengeance, and chain stuns mean you can spend literally 10 minutes trying to chase em down if you pull too many at a time.\n\nIn essence, they're the bratty children throwing rocks from your front lawn you've always wanted to strangle, or even more aptly (as someone put it), the murlocs of Pandaria.\n\nEdit: Forgot to note. One of the easier ways of dealing with this quest is simply picking off the Sprites as they're kicking braziers and starting fires. They gain a DoT that burns them down quite fast (burn, wretches, burn!) and simply tagging them at any percentage will count towards the quest objective. Helps to scream your favorite Ragnaros quote while doing so.\n\nBy fire, be purged!\n\nEdit: As of a few days before this post, they hotfixed Sprites so that they no longer Shin Kick as much. May your bruised shins rejoice!",
            date = "2012-10-03T07:16:54-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30190#comments:id=1729673",
        },
        {
            id = 1722353,
            score = 16,
            author = "uriahworld",
            text = "Do NOT fight these NPCs close to each other, they will build in numbers as they call out for help constantly from others. They can move random and sporadic so good luck trying to keep them in place.",
            date = "2012-09-28T00:43:02-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30190#comments:id=1722353",
        },
        {
            id = 1725869,
            score = 12,
            author = "545034",
            text = "Anyone having problems not seeing a single mob of these in the town?",
            date = "2012-09-30T09:40:13-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30190#comments:id=1725869",
        },
        {
            id = 1800669,
            score = 3,
            author = "Banana9526",
            text = "If the rotation of daily quests has this quest and https://www.wowhead.com/quest=30192 just run around the village and look out for the braziers. There are sprites running and kicking the them, getting themselves on fire. Wait for them to get on fire and then just kill them. The fire debuff on them deals pretty high damage to them and the quest is completed really quickly.",
            date = "2013-01-18T18:35:55-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30190#comments:id=1800669",
        },
        {
            id = 1769150,
            score = 2,
            author = "Gardakan18",
            text = "As of today (patch 5.1), the quest requires to kill 8 Slateskin Troublemakers, down from 12.",
            date = "2012-11-27T19:23:40-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30190#comments:id=1769150",
        },
    },
    [30191] = {
        {
            id = 1742210,
            score = 8,
            author = "783541",
            text = "Totally get it why its called Stolen Mistfall Keg, someone always comes and steals the keg when you attack the Slateskin Troublemakers lol!",
            date = "2012-10-15T08:39:00-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30191#comments:id=1742210",
        },
        {
            id = 1745843,
            score = 3,
            author = "Tockley",
            text = "This should probably be called \"Steer Clear of the Beer Up There\", the area on the rise to the east of the inn is littered with corpses and I found out why... I picked a fight with one of them and didn't get out of it for over five minutes until I ran away. Stay close to the village unless you have company or are really confident.",
            date = "2012-10-19T16:40:17-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30191#comments:id=1745843",
        },
        {
            id = 1754097,
            score = 1,
            author = "673336",
            text = "Easily the most obnoxious quest so far this expansion.  The adds drop their keg so that anyone who wanders by can take it, then run away from you and chain-stun you by throwing bricks.  If you're melee, you spend half your non-stunned time chasing them.  They don't have a lot of health, but you'll spend longer killing them than you will on the big, elite quest mobs.  And don't aoe unless you want to aggro all the random ones running by!",
            date = "2012-10-30T23:02:09-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30191#comments:id=1754097",
        },
        {
            id = 1798341,
            score = 1,
            author = "Himela",
            text = "If by any chance you are alone doing the quest, don't try killing 10 mobs in a row and then loot the kegs, it seems that they disappear after some time. Other than that, there is always someone stealing your kegs, so try to use some aoe crowd control to keep the mobs occupied while you take your kegs. I found myself fighting with people for the kegs, so just try to be calm: you will steal one and they will steal one :P",
            date = "2013-01-14T07:26:01-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30191#comments:id=1798341",
        },
        {
            id = 1744854,
            score = -2,
            author = "380942",
            text = "If you have troubles with this quest on a retardedly populated server(or for any other reason) - go inside the tavern, stay close to ladder. Every 30 seconds or so a sprite spawns carrying beer, smack him and loot. Worked for me on Twisting Nether.",
            date = "2012-10-18T12:17:25-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30191#comments:id=1744854",
        },
    },
    [30192] = {
