        },
        {
            id = 1728748,
            score = 1,
            author = "PirateGoesYar",
            text = "I'm having the exact same issue, plenty of buckets, but no pillagers and definitely no fires. I think I saw some of the adds earlier, but since I didn't see any fires, I completed the rest of my dailies, now nothing at all. Is this perhaps a phasing issue?",
            date = "2012-10-02T12:45:10-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30192#comments:id=1728748",
        },
        {
            id = 1743001,
            score = 1,
