    },
    [30196] = {
        {
            id = 1688412,
            score = 5,
            author = "Calesta",
            text = "Looting the lushrooms buffs you with Lushroom Dust (http://mop.wowhead.com/spell=124427).  Stacks up to 5 times.",
            date = "2012-07-15T11:44:24-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30196#comments:id=1688412",
