    [30200] = {
    },
    [30204] = {
        {
            id = 1733147,
            score = 32,
            author = "adavis",
            text = "To do this daily you have to look out for egg sacs on the ground that look like stones. Not the actual hatchlings you might find running about the place. When you find a stone, use your torch quest item on it and you will get credit for killing the hatchlings.",
            date = "2012-10-06T07:21:44-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30204#comments:id=1733147",
        },
        {
            id = 1749828,
            score = 7,
            author = "MarsJenkar",
            text = "That's no rock.\n\nIt's a space station.",
            date = "2012-10-24T23:08:50-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30204#comments:id=1749828",
        },
        {
            id = 1743981,
            score = 3,
            author = "Fonzy",
            text = "It's probably worth mentioning, too, that if you should happen to see a pack of spiderlings that someone else spawned, or run over a rock yourself by accident, using the torch to kill them doesn't seem to work.  In my experience, you either need to spawn the spiderlings by hitting the rock with the torch, or just outright killing the spawned spiderlings.",
            date = "2012-10-17T09:57:52-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30204#comments:id=1743981",
        },
        {
            id = 1751200,
            score = 3,
            author = "deathtrap",
            text = "A word of warning to players on Normal/RP servers: It seems that if a member of the opposing faction is flagged and runs into the flame from the torch, you will get flagged for PvP. Some classy people were exploiting this today on my server.",
            date = "2012-10-26T19:34:15-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30204#comments:id=1751200",
        },
        {
            id = 1750629,
            score = 2,
            author = "Anieu",
            text = "You might be tempted to think these egg sacs are the ones inside the Halls near the spider mini-boss, but they are not.  These \"egg sacs\" are small, typically round, rocks found in the ruins outside the halls, they can be difficult to spot as they don't sparkle much and there is no mouseover indication that it's anything other than normal terrain.",
            date = "2012-10-26T03:37:33-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30204#comments:id=1750629",
        },
    },
    [30205] = {
        {
            id = 1729659,
            score = 127,
            author = "Avareal",
            text = "Edit:  It appears the Artifact Box has different spawn locations.  What you're looking for is glowing blue circles.  If you see them, than you are near the container.  You can target the container box as well:  /tar Ancient Mogu Artifact.  You do not need to Dismount to clear the runes or loot the artifact.\n\nGo to around 26, 20 and you will see a box with artifact\n\nTo unlock this box, simply walk over all the blue runes on the ground in the surrounding area.  Than you will be able to loot the artifact.",
            date = "2012-10-03T06:56:34-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30205#comments:id=1729659",
        },
        {
            id = 1733195,
            score = 58,
            author = "Changaiz",
            text = "for those wondering, its not underground",
            date = "2012-10-06T08:31:35-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30205#comments:id=1733195",
        },
        {
            id = 1728516,
            score = 19,
            author = "Feylix",
            text = "For those that wonder what to look for - there are circular containers around the area.\n\nEach container opens up by walking over blue patterns close by.",
            date = "2012-10-02T08:57:07-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30205#comments:id=1728516",
        },
        {
            id = 1731287,
            score = 12,
            author = "126940",
            text = "If you have trouble finding https://www.wowhead.com/npc=63273, use a targeting macro such as:\n\n/tar Ancient Mogu Artifact\n\nAlso the artifact will have a stacked buff called https://www.wowhead.com/spell=123613 which will tell you how many more blue runes you have to step on in order to activate/unlock the container. My artifact started with 4 stacks, 2 of the runes on the ground were not visible (possible display bug?) so I had to walk around and stop on each tile trying to guess where the runes were until all 4 stacks were removed.",
            date = "2012-10-04T14:21:03-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30205#comments:id=1731287",
        },
        {
            id = 1725891,
            score = 9,
            author = "630282",
            text = "for me, the artifact was a bit northwest of where it showed on the default blizzard quest objective tracker",
            date = "2012-09-30T10:01:11-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30205#comments:id=1725891",
        },
    },
    [30206] = {
        {
            id = 1736612,
            score = 37,
            author = "921364",
            text = "This quest makes me want to shoot myself!",
            date = "2012-10-09T11:44:49-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30206#comments:id=1736612",
        },
        {
            id = 1734625,
            score = 20,
            author = "Itsversayce",
            text = "These runes look identical to the https://www.wowhead.com/item=22682s that were once along the walls of [zone=3456].",
            date = "2012-10-07T14:16:50-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30206#comments:id=1734625",
        },
        {
            id = 1762111,
            score = 16,
            author = "ronaldscott",
            text = "I hope that whoever made this quest gets leprosy.",
            date = "2012-11-14T00:21:17-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30206#comments:id=1762111",
        },
        {
            id = 1728573,
            score = 15,
            author = "1037509",
            text = "The runes are small and can be hard to spot, as they are also grayish like the walls they are on. They spawn pretty scarce, so you might have to fly around a bit to get them all. The sparkling is also small and is easy to not notice.",
            date = "2012-10-02T09:57:33-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30206#comments:id=1728573",
        },
        {
            id = 1753657,
            score = 12,
            author = "243447",
            text = "Note: These spawn mostly on the stone walls, not the ground and if you find one, camp there. They seem to spawn every 2 to 3 mins. This is important if you are surrounded by other players all trying to complete the same quest and they refuse to group up. (edit): It took me exactly 25 minutes to complete and I was able to do https://www.wowhead.com/quest=30200 while I camped the one spawn site.",
            date = "2012-10-30T07:47:01-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30206#comments:id=1753657",
        },
    },
    [30225] = {
        {
            id = 1737531,
            score = 57,
            author = "Caladynus",
            text = "The spiders can bite you causing a poison debuff I think.  The more that actually bite you, the worse the damage is.  I noticed that one time i was taking over 20k per tick and then died after killing the Matriarch.\n\nTHIS PART IS FOR THOSE THAT TICK OVER TO REVERED DOING DAILYS AFTER ACQUIRING THIS QUEST BUT BEFORE FINISHING IT:\n\nIf you acquire this quest and hit revered before killing the matriarch, you will not be able to see the Matriarch in the halls.  This is due to the fact you receive a new questline upon  hitting revered.  Go back to the Golden Pagoda and you will find an npc with a yellow ! over it's head.  There will be three total quests you have to complete from this npc:\n\nBattle Spear of the Thunder King([quest=30640 domain=www])\nBattle Helm of the Thunder King([quest=30641 domain=www])\nBattle Axe of the Thunder King([quest=30642 domain=www])\n\nAfter finishing these quests, the halls will phase back into the correct phase and you should be able to complete The Ashweb Matriarch with no issues :).",
            date = "2012-10-10T12:52:23-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30225#comments:id=1737531",
        },
        {
            id = 1728839,
            score = 13,
            author = "uriahworld",
            text = "This Spider is found down in the Guo-Lai Halls, the entrance is marked with Green Circles near the outside -- look for them.",
            date = "2012-10-02T14:15:33-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30225#comments:id=1728839",
        },
        {
            id = 1820254,
            score = 9,
            author = "1102672",
            text = "Here's a trick: After doing the first round of dailies in the ruins of Guo-Lai, don't turn in the quest \"That's Not A Rock\". You will get to keep the torch which downs the hatchlings in Guo-Lai Halls instantly.\n\nYou can still get the \"Halls\" quests without turning it in.",
            date = "2013-03-03T00:41:03-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30225#comments:id=1820254",
        },
        {
            id = 1827052,
            score = 7,
            author = "aoeu",
            text = "Here's the deal..  The 1st thing you want to do is kill the pat group of little spiders that is circling the room first.  The first time I did this I had no idea there was a pat group.. obviously, it spawned since someone must have recently cleared it.\n\nStart by hitting Bloodtip and kite him to just past the entrance door to his room.  Unfortunately, his baby spider packs will still come.. but it will take them time to get to you.  However, you must aoe these little guys ASAP.. they have very little health but those bites suck ass and will kill you.  If you kill Bloodtip fast enough, you'll have the little ones still coming towards you.. you can run away or just finish them off.\n\nEdit:  I'll also try Tekie's tip next time.. unfortunately, I had turned in the previous quest before doing this one.",
            date = "2013-03-11T20:08:33-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30225#comments:id=1827052",
        },
        {
            id = 1732037,
            score = 4,
