    [30227] = {
        {
            id = 1736671,
            score = 59,
            author = "Catriona",
            text = "If you pick up this quest just after you've gotten revered but before you've done the revered quests, the Guo-Lai Halls will phase and nothing will be there. Once you finish the short chain, you will be phase back into the normal version and Wulon will be waiting.",
            date = "2012-10-09T13:26:58-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30227#comments:id=1736671",
        },
        {
            id = 1744040,
            score = 13,
            author = "athika",
            text = "If you have a phasing issue with that quest, it´s because you have to finish the following quest chain first. Otherwise you are in a different quest phasing. You have to finish this quest chain:\n\nhttps://www.wowhead.com/quest=30639\nhttps://www.wowhead.com/quest=30630\nhttps://www.wowhead.com/quest=31512\nhttps://www.wowhead.com/quest=30631\nhttps://www.wowhead.com/quest=30632\nhttps://www.wowhead.com/quest=30633\nhttps://www.wowhead.com/quest=30634\nhttps://www.wowhead.com/quest=30635\nhttps://www.wowhead.com/quest=30636\nhttps://www.wowhead.com/quest=30654\nhttps://www.wowhead.com/quest=30638\nhttps://www.wowhead.com/quest=30639\nhttps://www.wowhead.com/quest=30640\nhttps://www.wowhead.com/quest=30641\nhttps://www.wowhead.com/quest=30642\nhttps://www.wowhead.com/quest=30277\nhttps://www.wowhead.com/quest=30643\nhttps://www.wowhead.com/quest=30644\nhttps://www.wowhead.com/quest=30645\nhttps://www.wowhead.com/quest=30646\n\nIf you have finished it, you are out of phase and you can finally finish the quest https://www.wowhead.com/quest=30227.",
            date = "2012-10-17T11:47:35-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30227#comments:id=1744040",
        },
        {
            id = 1737365,
            score = 12,
            author = "Emagehttsoli",
            text = "There is a small typo in the quest description. Wrong 'their'. :)",
            date = "2012-10-10T09:46:33-05:00",
