    [30229] = {
        {
            id = 1724894,
            score = 3,
            author = "philcolwill",
            text = "Its a good idea to pay attention to your surroundings, the https://www.wowhead.com/npc=58784 packs a mean punch if you venture a little to close to the Sentinel Basecamp.",
