        },
        {
            id = 2879844,
            score = 1,
            author = "Elitecookie",
            text = "To the north of this quest is the Sentinel Basecamp and the Incursion Huntress (https://www.wowhead.com/npc=58784/incursion-huntress) seem to aggro from about 90-100 yd away. With full view distance, they aggrod without me seeing them.\n\nBut they seem to have a normal range when mounted.",
            date = "2019-04-01T17:18:37-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30229#comments:id=2879844",
        },
    },
