    [30231] = {
        {
            id = 1723850,
            score = 40,
            author = "Karadine",
            text = "For this quest, you don't need to use the https://www.wowhead.com/item=79344 nor do you even have to dismount.  Just get on your flying mount and look for the sparkling green fruits up in the branches around the village.  Saves a lot of time!",
            date = "2012-09-29T00:51:25-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30231#comments:id=1723850",
        },
        {
            id = 1733316,
            score = 9,
            author = "tikki100",
            text = "The fruit is not very big, and spawn on trees. You can use the https://www.wowhead.com/item=79344 which will fire a little spark into the air. Follow it, and it'll explode on a nearby tree. Go to that tree and pick up the fallen fruit :P\n\nNote: You'll be able to pick the fruit up directly on the tree, without using the https://www.wowhead.com/item=79344, although it is easier to collect/find them if you use it :)",
            date = "2012-10-06T11:17:01-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30231#comments:id=1733316",
        },
        {
            id = 1746663,
            score = 3,
            author = "Vger",
            text = "You can often do this quest right in the village before you even head out to do the rest of the quests at Mistfall Village and it'll just take a couple seconds.  Many of the trees in the village will have five or more apples on them so you can finish the quest almost immediately and not have to fly all over the place looking for the next tree with one apple left on it.",
            date = "2012-10-20T18:19:00-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30231#comments:id=1746663",
        },
        {
            id = 1854567,
            score = 2,
            author = "kerrymayall",
            text = "\"How'd ya like them apples?\"",
            date = "2013-05-20T01:48:47-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30231#comments:id=1854567",
        },
        {
            id = 1723472,
            score = 1,
            author = "uriahworld",
            text = "Sometimes the fruit appears bugged, you cannot loot some that has already fallen to the ground. Use your Pomharvest Firework to make new fruit fall from the tree.",
            date = "2012-09-28T19:07:37-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30231#comments:id=1723472",
        },
    },
    [30232] = {
        {
            id = 1735772,
            score = 8,
            author = "il0vewowhead",
            text = "I find it much easier if you fly into the trees and kill the birds from standing in the branches so as to avoid all the wandering wolf packs below.",
            date = "2012-10-08T14:33:08-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30232#comments:id=1735772",
        },
        {
            id = 1846155,
            score = 1,
            author = "Peter4730",
            text = "There's no need to pull the Silkfeather Hawks OUT of the sky (unless you are so inclined).  I found many perched on top of boulders at ground level.  I even found one in combat with a friendly NPC and took over the fight, for the loot.  These hawks drop up to 18 feathers at a time, so a total of 80 didn't take long.",
            date = "2013-04-23T07:33:31-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30232#comments:id=1846155",
        },
    },
    [30233] = {
        {
            id = 1725281,
            score = 37,
            author = "395728",
            text = "When you see him getting ready to do Devastating Arc (he rears his head back), get behind him Immediately.",
            date = "2012-09-29T23:23:44-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30233#comments:id=1725281",
        },
        {
            id = 1730399,
            score = 25,
            author = "976259",
            text = "Best reason to kill a monster ever.",
            date = "2012-10-03T19:46:49-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30233#comments:id=1730399",
        },
        {
            id = 1723394,
            score = 21,
            author = "Chariotlolpro",
            text = "it's a Dark Souls reference.",
            date = "2012-09-28T18:03:10-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30233#comments:id=1723394",
        },
        {
            id = 1755601,
            score = 9,
            author = "1051329",
            text = "Its possible to kite him to the road that circles around Whitepetal Lake, there will be some Golden Lotus Outriders that can help you finish him off.",
            date = "2012-11-02T11:41:21-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30233#comments:id=1755601",
        },
        {
            id = 1749772,
            score = 3,
            author = "515283",
            text = "Easily soloable? By whom? An OP pally? Not by this mage, that's for sure. All he DID was Devastating Arc. Constantly. Even when I Blinked, I couldn't get behind him fast enough and I never had time to get off a single cast. Pretty annoying quest. If it weren't for a random nelf hunter I couldn't have completed this myself.",
            date = "2012-10-24T20:44:18-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30233#comments:id=1749772",
        },
    },
    [30234] = {
        {
            id = 1701134,
            score = 91,
            author = "Cielos",
            text = "Vicejaw cannot be attacked from the front and he does a lot of damage, so you need to kite him over the Paleblade Flesheater bodies in the area until he gets full.  When he starts to channel https://www.wowhead.com/spell=126126, you have 13 seconds to do as much damage from behind as you can.  Then just rinse and repeat until he's dead.",
            date = "2012-08-17T22:18:47-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30234#comments:id=1701134",
        },
        {
            id = 1751363,
            score = 10,
            author = "1049900",
            text = "It seems like sometimes when he uses Upchuck, he will appear to turn around, leading you to believe you can attack, but attacks will still be deflected.  This happened for me multiple times--if he does this, try to go in front of him to attack.  Worked for me!",
            date = "2012-10-27T01:34:24-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30234#comments:id=1751363",
        },
        {
            id = 1751427,
            score = 5,
            author = "Coldtusk",
            text = "if you time this right, and get him and the pack of Golden Lotus Outriders patting around, and get them all in place when he Upchucks, you can use the Outriders to help you kill him faster.",
            date = "2012-10-27T03:05:06-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30234#comments:id=1751427",
        },
        {
            id = 1800773,
            score = 5,
            author = "1082619",
            text = "For those of us not so fortunate as to be a warlock or other ranged class...\nAs a rogue I just threw my daggers at him to get him to aggro onto me and then just stayed a safe distance out until he nommed enough of the bodies around him to upchuck. I then proceeded to sprint in, pop some CD's and run out when upchuck ended. I had to get him to upchuck twice before he grabbed me in his jaws. He doesn't do much damage when doing this ability, so don't freak out ;)",
            date = "2013-01-19T00:56:28-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30234#comments:id=1800773",
        },
        {
            id = 1747171,
            score = 4,
            author = "515283",
            text = "Pretty annoying quest for this Pandaren Mage. Oh sure, he debuffs with Upchuck after he's eaten his fill and he's easy enough, if mind-numblingly tedious, to kite through the corpses - he did it like 8 times during the 10 minutes I attempted this quest. But after the first 2-3 Upchucks of taking damage, he would not budge from 51% health. The debuff showed in his portrait every time, but no \"Upchuck\" message appeared onscreen after the first 2-3 and whether I targeted/hit him from the front, the side, or from behind, the onscreen message \"Deflect\" was all the satisfaction I got from hitting him. Grrrrrrr. Please, someone, tell me this quest is bugged or how to get past 51%.",
            date = "2012-10-21T12:09:25-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30234#comments:id=1747171",
        },
    },
    [30235] = {
        {
            id = 1751727,
            score = 8,
            author = "asloversgo",
            text = "\"Quid Pro Quo\" means \"This for that\" in Latin. \"A favor for a favor\", if you will.",
            date = "2012-10-27T11:17:26-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30235#comments:id=1751727",
        },
        {
            id = 1783983,
            score = 8,
            author = "998027",
            text = "If you're a mediocre-geared Shadow Priest, let me give you some advice.\n\n1: Only use Silence when he is about to use Hydrolance - do not bother silencing his normal spells. Hydrolance does around 80K Damage, so always silence that when Silence is up.\n\n2: Do NOT use Halo - it will hit all the fish in the entire pond, and will make your time killing him much tougher. I figured this out the hard way and barely got away alive.\n\n3: Once Silenced, use Void Tendrils (If applicable) and back up to prevent taking damage for the duration of Silence.\n\n4: When Silence is not up, and he is about to use Hydrolance, pop Shadowfiend + Fade, so that your Shadowfiend tanks the big hit from Hydrolance.\n\n5: If you have no other CDs, you can also use Spectral Guise to tank the Hydrolance.\n\n6: Keep PW:S up as often as possible (Especially when he is haphazardly shooting water).\n\nI have not checked if he is Fear-able, I've never needed to use Fear. I would caution against it, since you may Fear one of the fish beneath the water and aggro them.\n\nTreasure of The Vale has so far only given me Coins and Great Pandaren Banquets.",
            date = "2012-12-19T07:38:14-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30235#comments:id=1783983",
        },
        {
            id = 1760770,
            score = 4,
            author = "Chaix",
            text = "if you've fought one of the rare jinyu champions, quid fights just like they do, just with the difficulty turned down a bit.\n\ninterrupt hydrolance\nrun around during water blossom",
            date = "2012-11-11T08:56:17-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30235#comments:id=1760770",
        },
        {
            id = 1751699,
            score = 3,
            author = "NYTEMODE",
            text = "As of this morning, 11:35 am EST, I was able to help a Horde Shadow Priest kill him after he had already tagged. I still received credit for the kill even though it was not me who did the tagging.",
            date = "2012-10-27T10:38:09-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30235#comments:id=1751699",
        },
        {
            id = 1723631,
            score = 1,
            author = "axhawk",
            text = "Unlike many \"Kill X boss\" quests, you actually need to tag Quid in order to get credit for defeating him.  This makes trying to complete this daily somewhat annoying on high-population servers, with a dozen or more people all trying to tag him first when he spawns.  Grouping up helps, though.",
            date = "2012-09-28T21:49:23-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30235#comments:id=1723631",
        },
    },
    [30236] = {
        {
            id = 1738055,
            score = 6,
            author = "arkensis",
            text = "When you accept this quest, you will be granted a temporary waterwalking ability that allows you to take damage and walk on water, unlike the Shaman spell.\n\nIn order to defeat Aetha for the Golden Lotus quest, engage her, and continue to move around the outside of the area as she casts Tornado (be careful not to accidentally walk off the waterfall!). Give yourself enough space between the moving tornadoes, and you should easily be able to defeat her, so long as you don't stand in the winds for too long.\n\nAs noted in the quest text, this mob is not killable - you \"subdue\" her, and she runs away.",
            date = "2012-10-11T02:40:52-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30236#comments:id=1738055",
        },
        {
            id = 1780111,
            score = 6,
            author = "Dust",
            text = "This NPC makes the cutest sounds when attacked.  It's adorable.  You'll want to hug it instead of hit it.",
            date = "2012-12-12T10:44:59-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30236#comments:id=1780111",
        },
        {
            id = 1720610,
            score = 4,
            author = "202683",
            text = "some alliance ganked me while i was killing her... now i rezz near the graveyard down on the valley how the hell i go up again as a ghost to get my body?",
            date = "2012-09-26T17:55:30-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30236#comments:id=1720610",
        },
        {
            id = 1782826,
            score = 3,
            author = "ithilyn",
            text = "Kite her around the lake, avoiding the tornadoes, using the water walk buff the quest giver gives you. This is key. If you die, abandon the quest, and go back and re-accept it to get the buff again.",
            date = "2012-12-17T00:31:22-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30236#comments:id=1782826",
        },
        {
            id = 1799177,
            score = 3,
            author = "Eighjan",
            text = "Simple question that has evaded comment - what rep. level is this quest available at?\n\nI'm as good as Exalted w/ Golden Lotus (283 to go) & have never seen this Quest.\nI did, however see this mob & fought it w/o the quest & got the fight credit for it towards https://www.wowhead.com/achievement=7317 - don't want to guarantee it will always happen, though.",
            date = "2013-01-15T19:47:26-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30236#comments:id=1799177",
        },
    },
    [30237] = {
        {
            id = 1797317,
            score = 3,
            author = "BarlowTheSeeker",
            text = "If you have just reached exalted with Golden Lotus and you are on the final quest series, beginning with https://www.wowhead.com/quest=30643, a bunch of quests will be phased out. You can grab this quest, but none of the mobs will be there until you complete https://www.wowhead.com/quest=30646.\n\nHope this helps!",
            date = "2013-01-12T13:26:39-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30237#comments:id=1797317",
        },
        {
            id = 1764702,
            score = 2,
            author = "168688",
            text = "What's the point of being able to turn this quest in through the quest log when you STILL have to go all the way back to turn in the other dailys?",
            date = "2012-11-19T08:06:12-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30237#comments:id=1764702",
        },
        {
