            author = "pherkier",
            text = "I knew those quest chain before but I got exalted with golden lotus then I couldn't find those mobs out, If you got the same problem with completing the new quest will make the mobs appear >-",
            date = "2012-11-23T08:13:39-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30237#comments:id=1766662",
        },
    },
    [30238] = {
        {
            id = 1756958,
            score = 2,
            author = "881584",
            text = "Found at:\n53, 66\n52, 53\n51, 65\n49, 67\n51, 68\n51, 67\n47, 70",
            date = "2012-11-04T11:44:31-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30238#comments:id=1756958",
        },
        {
            id = 1804757,
            score = 1,
            author = "941150",
            text = "These are the shrine-looking things with 4 gravestones each, not the individual gravestones you see sitting around.  When you hover over it, it should have a \"use\" icon plainly visible.  No quest items or anything to deal with.",
            date = "2013-01-27T00:30:30-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30238#comments:id=1804757",
        },
    },
    [30239] = {
        {
            id = 1729672,
            score = 5,
            author = "2Lan",
            text = "You will get this quests automaticaly after completing https://www.wowhead.com/quest=30237\n\nLao-fe the Slavebinder is inside the cave atop the same place where the previous quest took place. The entrance coords are 47,67 at tu-shen burial ground. Just follow the path up the mountain into the cave and kill him, pretty straight forward to complete.\n\nHe's a L91 npc with 1,630,128hp who casts https://www.wowhead.com/spell=126471\n\nIf you cant find the cave's entrance, just follow the https://www.wowhead.com/npc=58669, as they will run directly into the cave to engage Lao-fe.\n\nEDIT :  as Nulgar stated below, once you are honored, you will be sent  to the https://www.wowhead.com/quest=30385 if you completed https://www.wowhead.com/quest=30639 instead of getting to kill Lao-fe. However, you ll still get this daily once in a while.",
            date = "2012-10-03T07:16:10-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30239#comments:id=1729672",
        },
        {
            id = 1814527,
            score = 3,
            author = "998027",
            text = "Quest Giver: \"Did you kill Lao-Fe yet?\"\n\nMe: \"Why would I have killed a famous Frenchman?\"",
            date = "2013-02-16T21:59:03-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30239#comments:id=1814527",
        },
        {
            id = 1823212,
            score = 1,
            author = "721249",
            text = "Straight forward, huh? I must have missed the memo. I keep getting hit and stunned by four or five ancient mogu spirits all at once when I attack Lao-Fe.  There must be some other trick that I'm missing.",
            date = "2013-03-06T22:39:20-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30239#comments:id=1823212",
        },
        {
            id = 1739120,
            score = 0,
            author = "Kratfrotz",
            text = "I'm honored with golden lotus and didn't get this follow up after completing https://www.wowhead.com/quest=30237. Another player that's friendly with them tried to share it, but I wasn't eligible.",
            date = "2012-10-12T02:53:36-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30239#comments:id=1739120",
        },
        {
            id = 1755016,
            score = 0,
            author = "42102",
            text = "This is so random. Me and my better half are at the same point in progression and it seems completely random to me if we get this followup or not. I've gotten it once but she didn't. We were in different areas.\n\nIs it supposed to be just.. random, or is there a deciding element?",
            date = "2012-11-01T13:14:37-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30239#comments:id=1755016",
        },
    },
    [30240] = {
        {
            id = 1757451,
            score = 76,
            author = "rzzr",
            text = "Remember that if you are going for the achievement and you fail you have to abandon the quest and start again. It is not enough just to run out and re-set the timer.",
            date = "2012-11-05T04:57:31-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30240#comments:id=1757451",
        },
        {
            id = 2540226,
            score = 60,
            author = "15885",
            text = "This worked for me today, on like my third attempt. I simply ran counterclockwise around the circle, just inside each stone pillar on the perimeter of the field, brushing each with my right shoulder as I passed by. I never stopped, and I just ran from pillar to pillar for 60 secs. Good luck!",
            date = "2017-12-13T02:12:11-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30240#comments:id=2540226",
        },
        {
            id = 1821033,
            score = 33,
            author = "LuckyGhoul",
            text = "Did this flawlessly today on a hunter.\n\nMy pet was less than flawless.\n\nI did not get credit for the achievement.\n\nWill try without my pet out next time.",
            date = "2013-03-04T20:53:20-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30240#comments:id=1821033",
        },
        {
            id = 1888249,
            score = 31,
            author = "pellmell",
            text = "If you're wondering why the quest timer isn't showing up when you are in the circle, try dismounting. :)",
            date = "2013-08-19T04:50:24-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30240#comments:id=1888249",
        },
        {
            id = 1894851,
            score = 20,
            author = "FrostWolf219",
            text = "The updated version of this quest is a tad harder than the pre 5.4 one (and I have now done both).  Before 5.4 you had a black circle that told you where to avoid.  Now you have a small smoke ring that expands when hit and sometimes you have little time to leave.  As usual, just stay on your toes and if you are doing this quest for \"Ready for Raiding III\" drop the quest and pick it up again if you get hit.\n\nAlso, I can only speak to this instance today but the NPC that offers this quest, Yumi Goldenpaw, is now located at the bottom of the stairs that lead from the survival ring to the battle ring.  Also, again for this instance today, there was no quest chain to do before the Setting Sun Garrison quests.  Just go there and do the quest.",
            date = "2013-09-10T21:09:45-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30240#comments:id=1894851",
        },
    },
    [30241] = {
        {
            id = 1728229,
            score = 14,
            author = "894060",
            text = "Here is how I got this quest:\n\nCompleted everything in Valley of the Four Winds, excluding: a quest that sends you to Kun Lai Summit, 2 quests that start in Valley of the Four Winds but send you to find NPCs in Krasarang and Nesingwary Safari.\n\nWhen Loon Mai gave me a free flight path ride I took it to Zhu's Watch to find the hozen. After that I have done everything in Krasarang Wilds and quest chains have eventually sent be back to Stoneplow where I got the cutscene and battle against mantid began.\n\nAlso, Sunwalker Dezco didn't give me this quest in Dawnchaser Retreat, I found him on the road west of it, that leads into Valley of the Four Winds, after the Mogu ruins.",
            date = "2012-10-02T03:35:33-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30241#comments:id=1728229",
        },
        {
            id = 1921043,
            score = 10,
            author = "yoshimario40",
            text = "To unlock this quest, you need to help\n\nhttps://www.wowhead.com/npc=56312 and the farmers at Thunderfoot Fields\nhttps://www.wowhead.com/npc=56133, https://www.wowhead.com/npc=56138, https://www.wowhead.com/npc=56474 and their journey across Valley of the Four Winds\nhttps://www.wowhead.com/npc=56113 and his vision of the Vale\nhttps://www.wowhead.com/npc=56111 and her search for the Hidden Master\nhttps://www.wowhead.com/npc=56115, https://www.wowhead.com/npc=58410 and the despair-ridden Zhu's Watch\nhttps://www.wowhead.com/npc=56112 and his efforts to help the Horde/Alliance\n(Alliance)https://www.wowhead.com/npc=58745, https://www.wowhead.com/npc=58821 or (Horde)https://www.wowhead.com/npc=58607, https://www.wowhead.com/npc=58114 and the pools of youth\nhttps://www.wowhead.com/npc=59138 and the battle to take back the Temple of the Red Crane\n\nThis is because in the fight against the mantids, everyone you helped comes back to help you fight back.\n\nBy the time you get this quest, you'll have almost done all of https://www.wowhead.com/achievement=6536 and https://www.wowhead.com/achievement=6301 except for the out of the way quests at Nesingwary's Safari and Nayeli Lagoon.",
            date = "2013-11-25T00:44:25-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30241#comments:id=1921043",
        },
        {
            id = 1723457,
            score = 6,
            author = "Qoko",
            text = "To reconcile what's the stated in the previous comment: if you do Krasarang Wilds before you finish up the Stormstout and other main quests in the Valley, this quest and the ally counterpart are not available. Once you finish the Stormstout chain in the Valley and turn the keg to Stoneplow, the cutscene for the final battle in the Valley begins without having you turned in this quest.\n\nSurprisingly though, knowing about this quest (the ally version, that aside), I went back to the questgiver of the Ally version of this quest, could accept it, took the fp to Stoneplow and turned it in: the cutscene occured again with all the npcs already in place!\n\nWas funny to watch, but something in the combination of these quests is wrong.",
            date = "2012-09-28T18:57:06-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30241#comments:id=1723457",
        },
        {
            id = 1778606,
            score = 3,
            author = "Hairband",
            text = "The cutscene after this quest, Stoneplow Final Scene, was pretty epic.  Worth the Loremaster of Pandaria!  This quest (Warn Stoneplow) was the final quest after I earned the Loremaster of Pandaria.  I had done every other quest chain prior to this quest.  Yes, that means I had done every other zone except Krasarang Wilds... and when I eventually got that done, it sent me to Stoneplow for this cutscene.\n\nAfter I watched the cutscene, I obtained 3 more quests to do.",
            date = "2012-12-09T19:52:23-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30241#comments:id=1778606",
        },
        {
            id = 1732484,
            score = 2,
            author = "Karadine",
            text = "The following quests lead to the https://www.wowhead.com/achievement=7502 \"big finale\" that wraps up the storylines of Krasarang Wilds and Valley of the Four Winds. You will only be able to complete one of these:\n\nhttps://www.wowhead.com/quest=30376\nhttps://www.wowhead.com/quest=30360 (Alliance) / https://www.wowhead.com/quest=30241 (Horde)",
            date = "2012-10-05T16:30:28-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30241#comments:id=1732484",
        },
    },
    [30242] = {
        {
            id = 1738436,
            score = 219,
            author = "543619",
            text = "Blizzard. I can forgive the drop rate on the Succulent Turtle Meat.\n\nI may be able to forgive the daily quest where we use fireworks to knock fruit out of trees only to have other players bag them.\n\nHell, I will even forgive the quest in Hyjal where we had to try and bag scrambling critters.\n\nKickin' Nass!\n\nVics Keys!\n\nAll of this, can be forgiven!\n\nBut this....\n\nThis.\n\nWhat were you thinking? What were you smoking?",
            date = "2012-10-11T11:05:21-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30242#comments:id=1738436",
        },
        {
            id = 1733555,
            score = 80,
            author = "541085",
            text = "It's actually quite easy to complete this quest without taking any damage at all.\n\nThe trick is to stand in the gap in between two blades (as opposed to in the center of four), which means that only one Trainer is a potential threat at any one time. Choose a gap close to the edge of the arena, dodge into another gap diagonally when the Trainer in that channel has just run past, and dodge back again when the first Trainer has run past you and turned around as well.",
            date = "2012-10-06T15:36:37-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30242#comments:id=1733555",
        },
        {
            id = 3214228,
            score = 64,
            author = "vsimmons",
            text = "I don't see it mentioned here, but @taurenbeak's comment on the meta achievement https://www.wowhead.com/achievement=7319 suggested using https://www.wowhead.com/item=141879 which worked like a charm!  Just make sure you're inside the ring and see the progress bar before you pop it (like I didn't do the first time in my excitement) or you'll be waiting an hour before the item is usable again.",
            date = "2020-06-25T07:54:20-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30242#comments:id=3214228",
        },
        {
            id = 1774074,
            score = 50,
            author = "847245",
            text = "http://i49.tinypic.com/1kqqe.png\n\nMy position for this quest, no hits or damage taken whatsoever. It's in front of a line of blade spinners, so no warrior coming up to me vertically, and it's far enough forward for the warriors going around my sector of the perimeter to not be able to reach me.\n\nIf you can't see me or tell where my position is, look at my minimap, and I'm the tall thin blotch of red.\n\nBasically I stood inside the spinner's range, the backed out until I was just barely far enough to not get hurt.",
            date = "2012-12-02T15:23:40-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30242#comments:id=1774074",
        },
        {
            id = 1768854,
            score = 48,
            author = "ToviValdora",
            text = "As of 5.1, standing on the pots/pillars (whatever you want to call them) no longer works. I did it anyways even after I got the achievement to be lazy. Got knocked off several times (wanted to make sure before posting.)",
            date = "2012-11-27T15:18:40-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30242#comments:id=1768854",
        },
    },
    [30243] = {
        {
            id = 1755109,
            score = 27,
            author = "250743",
