            author = "uriahworld",
            text = "Kill any of the Krik'thik along the top of wall for credit.",
            date = "2012-10-08T00:48:04-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30244#comments:id=1735071",
        },
        {
            id = 1778247,
            score = 2,
            author = "Thaag",
            text = "A word of caution:\n\nDon't bite off more than you can chew in this quest.  If you die, there is no way to run back to your corpse.  You will have to take rez sickness and wait 10 minutes.  I thought I was going to be a big bad bear and just take on 8 at a time like I normally do on other quests....I spent my rez sickness time discovering that's a very, very effective wall on the Townlong side.",
            date = "2012-12-09T08:03:52-06:00",
