    },
    [30245] = {
        {
            id = 1731988,
            score = 39,
            author = "357803",
            text = "you have to find a scout that's fighting a mogu and kill the mogu to get credit.",
            date = "2012-10-05T05:51:52-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30245#comments:id=1731988",
        },
        {
            id = 1744229,
            score = 9,
            author = "791176",
            text = "/target Shado-Pan Scout\n/run SetRaidTarget(\"target\", 4)\n\nMight help a bit for those people on high pop servers fighting to talk with the scouts.",
            date = "2012-10-17T17:04:18-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30245#comments:id=1744229",
        },
        {
            id = 1748782,
            score = 5,
            author = "365918",
            text = "An interesting note: this quest shares speech credit with people, even if not grouped, so long as you are near enough to hear the speech the scout gives when talked to. Noticed this on my horde shaman when an alliance druid and I approached a scout at the same time. The druid was going to get there first so I turned to fly away and, much to my surprise, got credit for talking to the scout, anyway.",
            date = "2012-10-23T14:51:39-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30245#comments:id=1748782",
        },
        {
            id = 1732656,
