    [30248] = {
        {
            id = 1750899,
            score = 4,
            author = "984594",
            text = "He's outside the Guo-Lao Hall to the left in a small glade.",
            date = "2012-10-26T12:23:57-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30248#comments:id=1750899",
        },
        {
            id = 1754567,
            score = 4,
            author = "Rachel01",
            text = "He has 1528K hits, Decimate does approx 50% of total health damage, also has another big knock-back attack (Decapitate?). He can cast Decimate repeatedly, and he isn't rooted while he casts either Decimate or Decapitate. If you don't have enough interrupts, and a lot of DPS, this will hurt. I silenced his first Decimate cast and he did it three more times before Silence came off cool down (45 seconds).",
            date = "2012-10-31T18:34:24-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30248#comments:id=1754567",
        },
        {
            id = 1762414,
            score = 1,
            author = "Triannad",
            text = "Just soloed this as a destro lock. After dying several times i summoned a void lord to take the brunt of the decimate spell. Worked like a charm. Downed him the 1st time I tried this tactic.",
            date = "2012-11-14T16:21:45-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30248#comments:id=1762414",
        },
        {
            id = 1776213,
            score = 1,
            author = "1052767",
            text = "Definitely not a pleasant fight. Almost died as a retribution pally, even with potions, heals & bandaging half-way through. Grab a friend, preferably a rdps.",
            date = "2012-12-05T16:37:40-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30248#comments:id=1776213",
        },
        {
            id = 1784907,
            score = 1,
            author = "1051312",
            text = "Very tough for my Prot Pally. Admittedly he’s not all that good! I wouldn’t have wasted time on it but he wanted Treasures Of The Vale so he could make another card. So I waited till someone else came along.\n\nA very easy kill for my hunter though.",
            date = "2012-12-21T00:40:21-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30248#comments:id=1784907",
        },
    },
    [30249] = {
        {
            id = 1675848,
            score = 45,
            author = "746315",
            text = "Drag him over near the Oil Kegs and point him so that he hits said kegs with his AoE (http://mop.wowhead.com/spell=127601) attack (http://mop.wowhead.com/spell=126275). If he destroys an Oil Keg it will debuff him with https://www.wowhead.com/spell=126369. Once he's debuffed attack him with fire damage to inflict https://www.wowhead.com/spell=126528 (if you don't have a fire damage spell, wait till the Shadow-Pan Rangers ignite him). The debuff will inflict alot of damage as well as causing him to take 50% more damage in addition to the Rangers attacking him. Rinse and repeat till dead.",
            date = "2012-06-12T02:43:15-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30249#comments:id=1675848",
        },
        {
            id = 1858799,
            score = 3,
            author = "wschlichtman",
            text = "As an poorly geared pally, just walk backwards in a circle, kiting him and beating the heck out of him. You'll avoid all of its special attacks.",
            date = "2013-05-27T14:16:49-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30249#comments:id=1858799",
        },
        {
            id = 1765817,
            score = 0,
            author = "269715",
            text = "The first time I got this quest I came upon someone else's fight and helped them finish him off. He was down to ~500k, so it only took a few seconds to finish, and I was given credit for the quest. I was not, however, given credit for the https://www.wowhead.com/achievement=7317 achievement. So I went back and killed him again. Apparently you either have to either tag him or do a large enough percentage of damage for it to count for the achievement, even though you can get quest credit for doing very little damage.",
            date = "2012-11-21T12:52:58-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30249#comments:id=1765817",
        },
    },
    [30251] = {
        {
            id = 1765692,
            score = 14,
            author = "Jjokkey",
            text = "Vyraxxis's combination of https://www.wowhead.com/spell=126337 plus https://www.wowhead.com/spell=126336 is his most dangerous move - periodically, during the fight, he'll toss you behind him from wherever you are and coat the ground with a damaging goo that slows you down enough that it's hard to escape.\n\nSince the fight starts on a raised platform, a good way to handle him is to lure him to the edge of the stairs and fight there.  The caustic pitch can only cover a flat area, so stepping up or down the stairs lets you easily get out of its area.",
            date = "2012-11-21T08:22:21-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30251#comments:id=1765692",
        },
        {
            id = 1675147,
            score = 4,
            author = "Vacc",
            text = "It's not really clear and not marked on the map, at least at this point in beta, but he's stood on top of the wall to the north of where you shoot the turrets on the pre quests.",
            date = "2012-06-10T07:03:29-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30251#comments:id=1675147",
        },
        {
            id = 1747515,
            score = 2,
            author = "RobDBlackwolf",
            text = "Vyraxxis drops Caustic Pitch on a larger area of the floor. To escape quicker one has to jump out of it, just running won't work as well, as the player gets slowed by it.",
            date = "2012-10-21T23:01:06-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30251#comments:id=1747515",
        },
    },
    [30252] = {
        {
            id = 1703681,
            score = 29,
            author = "lloviosa",
            text = "This is the beginning quest line to unlock farming.\n\nA Helping Hand  (http://mop.wowhead.com/quest=30252)\nLearn and Grow I: Seeds (http://mop.wowhead.com/quest=30535)\nLearn and Grow II: Tilling and Planting (http://mop.wowhead.com/quest=30254)\nLearn and Grow III: Tending Crops (http://mop.wowhead.com/quest=30255)\nLearn and Grow IV: Harvesting  (http://mop.wowhead.com/quest=30256)\nLearn and Grow  V: Halfhill Market (http://mop.wowhead.com/quest=30257)\n*Learn and Grow VI: Gina's Vote (http://mop.wowhead.com/quest=31945)\n\n*You may have to do this last quest the following day. Crops ripen when dailies reset so unless its slightly before that time, you'll need to come back after they do, or any time the next day.\n\nThe good news is that if you have your crops planted even moments before reset, they will be ready very soon! This applies for regular farming too, not just this quest. I've tested and tried this method myself and was able to harvest within 8 min. after planting and tending.\n\nEdit: updated for patch 5.1. Crops no longer ripen at midnight server time.",
            date = "2012-08-24T02:41:23-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30252#comments:id=1703681",
        },
        {
            id = 1847551,
            score = 19,
            author = "863833",
            text = "...Aaaand that's how an era of freeloading and watching some stranger doing all the work for him begins for Farmer Yoon.\n\nThis guy should become politician.\n\n...Wait, he ACTUALLY becomes one.",
            date = "2013-04-27T08:23:53-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30252#comments:id=1847551",
        },
        {
            id = 1724670,
            score = 18,
            author = "Sagira",
            text = "The first thing most players did in the old SNES game Harvest Moon was spend the first night (since night lasted forever; until you went to bed) clearing the rocks from their farm.\n\nProbably not a sneaky underhanded reference, but I'm going to pretend it is :)",
            date = "2012-09-29T14:28:36-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30252#comments:id=1724670",
        },
        {
            id = 1787099,
            score = 13,
            author = "TheWheatOne",
            text = "\"Its easy\" he said. \"The Tillers are hardly a grind!\" he said.",
            date = "2012-12-25T02:09:14-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30252#comments:id=1787099",
        },
        {
            id = 5858869,
            score = 13,
            author = "phaiz",
            text = "Quest doesn't seem to be available at level 59 in Remix. Will update when/if this changes.\n\nedit: Still not available even at 70. After some searching it seems the entire Tillers/farm thing is disabled for remix.",
            date = "2024-05-19T00:32:52-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30252#comments:id=5858869",
        },
    },
    [30254] = {
        {
            id = 1718653,
            score = 39,
            author = "McKizz",
            text = "Make sure you actually CLICK / SELECT the tilled soil, otherwise you won't be able to plant your seeds.",
            date = "2012-09-25T11:36:15-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30254#comments:id=1718653",
        },
        {
            id = 1719821,
            score = 9,
            author = "Nekrotik",
            text = "If you're standing in front of him, the tilled soil mounds are immediately to your left, just to the left of the stairs. I mention this because they can be a little hard to notice. Don't go wandering off looking for them like I did.",
            date = "2012-09-26T07:52:26-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30254#comments:id=1719821",
        },
        {
            id = 1720694,
            score = 3,
            author = "515518",
            text = "Before you waste a bunch of time as a druid.  Shift to human form, its one of the few things you can't do in shapeshift form.\n\nAlso the Watering can is by the chopped tree with the axe on it.  Along with the rusty shovel.",
            date = "2012-09-26T19:18:44-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30254#comments:id=1720694",
        },
        {
            id = 1703685,
            score = 2,
            author = "lloviosa",
            text = "This is the third quest in the chain to unlock farming.\n\nA Helping Hand  (http://mop.wowhead.com/quest=30252)\nLearn and Grow I: Seeds (http://mop.wowhead.com/quest=30535)\nLearn and Grow II: Tilling and Planting (http://mop.wowhead.com/quest=30254)\nLearn and Grow III: Tending Crops (http://mop.wowhead.com/quest=30255)\nLearn and Grow IV: Harvesting  (http://mop.wowhead.com/quest=30256)\nLearn and Grow  V: Halfhill Market (http://mop.wowhead.com/quest=30257)\n*Learn and Grow VI: Gina's Vote (http://mop.wowhead.com/quest=31945)\n\n*You may have to do this last quest the following day. Crops ripen when dailies reset so unless its slightly before that time, you'll need to come back after they do, or any time the next day.\n\nThe good news is that if you have your crops planted even moments before reset, they will be ready very soon! This applies for regular farming too, not just this quest. I've tested and tried this method myself and was able to harvest within 8 min. after planting and tending.\n\nEdit: updated for patch 5.1. Crops no longer ripen at midnight server time.",
            date = "2012-08-24T02:48:29-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30254#comments:id=1703685",
        },
        {
            id = 1806434,
            score = 1,
            author = "1086797",
            text = "Maybe this will help some of you. I spent 15 min zooming in and out and just randomly clicking on the ground to the left of the door... There was no soil that could be tilled. I abandoned and reaquired the quest and like magic there they were. just an FYI",
            date = "2013-01-29T18:18:44-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30254#comments:id=1806434",
        },
    },
    [30255] = {
        {
            id = 1724319,
            score = 72,
            author = "sk4p",
            text = "If you're a dope like me and water the crops before accepting this quest, you will go \"oh crap!  my crops aren't parched anymore!  I'm doomed!\"\n\nSimply drop this quest, and your cabbages will become parched again, then take the quest again and water them.",
            date = "2012-09-29T10:04:52-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30255#comments:id=1724319",
        },
        {
            id = 1764861,
            score = 24,
            author = "30584",
            text = "My grandfather used to say \"Yoonie, a cabbage is like a woman: ignore her and she'll turn rotten. Pamper her and she'll grow big and plump and you can put a ribbon on her and take her to market to show her off to your frie-\" look, he was from a different time, okay?\nLove this guy.",
            date = "2012-11-19T15:12:21-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30255#comments:id=1764861",
        },
        {
            id = 1720832,
            score = 14,
            author = "1036935",
            text = "If you are an idiot like me, you may look for the watering can for quite some time with no success after the \"tutorial\" quests.\n\nThe items disappear from the ground when they are in your inventory. The watering can will still be in yours following the first chain, as it is the only one they make you pick up...",
            date = "2012-09-26T21:43:33-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30255#comments:id=1720832",
        },
        {
            id = 1703686,
            score = 5,
            author = "lloviosa",
            text = "This is the fourth quest in the chain to unlock farming.\n\nA Helping Hand  (http://mop.wowhead.com/quest=30252)\nLearn and Grow I: Seeds (http://mop.wowhead.com/quest=30535)\nLearn and Grow II: Tilling and Planting (http://mop.wowhead.com/quest=30254)\nLearn and Grow III: Tending Crops (http://mop.wowhead.com/quest=30255)\nLearn and Grow IV: Harvesting  (http://mop.wowhead.com/quest=30256)\nLearn and Grow  V: Halfhill Market (http://mop.wowhead.com/quest=30257)\n*Learn and Grow VI: Gina's Vote (http://mop.wowhead.com/quest=31945)\n\n*You may have to do this last quest the following day. Crops ripen when dailies reset so unless its slightly before that time, you'll need to come back after they do, or any time the next day.\n\nThe good news is that if you have your crops planted even moments before reset, they will be ready very soon! This applies for regular farming too, not just this quest. I've tested and tried this method myself and was able to harvest within 8 min. after planting and tending.\n\nEdit: updated for patch 5.1. Crops no longer ripen at midnight server time.",
            date = "2012-08-24T02:50:34-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30255#comments:id=1703686",
        },
        {
            id = 1956785,
            score = 4,
            author = "1243684",
            text = "I'm having trouble locating the Rusty Watering Can for this quest. I see something that looks like a watering can, but I can't select it. Any suggestions?",
            date = "2014-04-07T15:42:17-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30255#comments:id=1956785",
        },
    },
    [30256] = {
        {
            id = 1870167,
            score = 10,
            author = "Affirmation",
            text = "This quest bugged out for me. I planted the cabbages and made them happy. They weren't ready to be harvested immediately (that should've been my first clue that something was wrong, duh), so I came back the next day to harvest, but they were still \"growing\". Came back the next day and they were still growing. I tried relogging, flying far away and coming back, zoning, etc., no luck.\n\nWhat fixed it for me is I abandoned the quest, and dug up the cabbages. Then I re-took the quest, and a few seconds later, ripe cabbages suddenly appeared! If your crops are stuck at growing (not tangled or parched or anything else), try this and save yourself a few days.",
            date = "2013-06-24T13:25:25-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30256#comments:id=1870167",
        },
        {
            id = 1876826,
            score = 5,
            author = "Firelocked",
            text = "My cabbages grew, and ripened. But I picked them and POOF! Nothing. I abandoned the quest several times, each time I'd pick them, POOF! Nothing. Finally I realized I had to have room in my full bags to receive the cabbages! Duh! Worked fine the next time I made room and accepted the quest, lol.",
            date = "2013-07-14T11:36:29-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30256#comments:id=1876826",
        },
        {
            id = 1772120,
            score = 4,
            author = "lloviosa",
            text = "This is the fifth quest in the chain to unlock farming.\n\nThe cabbage is unique in that it will ripen immediately. Other crops planted will take more time. When you plant scallions for Gina, you'll only need to plant and harvest one. For the other slots, you can plant whatever you like.\n\nA Helping Hand  (http://mop.wowhead.com/quest=30252)\nLearn and Grow I: Seeds (http://mop.wowhead.com/quest=30535)\nLearn and Grow II: Tilling and Planting (http://mop.wowhead.com/quest=30254)\nLearn and Grow III: Tending Crops (http://mop.wowhead.com/quest=30255)\nLearn and Grow IV: Harvesting  (http://mop.wowhead.com/quest=30256)\nLearn and Grow  V: Halfhill Market (http://mop.wowhead.com/quest=30257)\n*Learn and Grow VI: Gina's Vote (http://mop.wowhead.com/quest=31945)\n\n*You may have to do this last quest the following day. Crops ripen when dailies reset so unless its slightly before that time, you'll need to come back after they do, or any time the next day.\n\nThe good news is that if you have your crops planted even moments before reset, they will be ready very soon! This applies for regular farming too, not just this quest. I've tested and tried this method myself and was able to harvest within 8 min. after planting and tending.\n\nEdit: updated for patch 5.1. Crops no longer ripen at midnight server time.",
            date = "2012-11-30T11:03:52-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30256#comments:id=1772120",
        },
        {
            id = 1720448,
            score = 3,
            author = "970123",
            text = "I plant the 4 scallions and I cannot figure out what to do to help the one out with insects buzzing all around it. THe other 3 I took care of just fine.",
            date = "2012-09-26T15:56:39-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30256#comments:id=1720448",
        },
        {
            id = 1862919,
            score = 2,
            author = "1029550",
            text = "If your plant gets \"tangled\" grab it with the highlighted hand and walk backwards pulling a long vine.  The vine will break and the plant will be fine.  Sometimes it takes more than one pull :)",
            date = "2013-06-05T00:51:45-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30256#comments:id=1862919",
        },
    },
    [30257] = {
