        },
        {
            id = 1736288,
            score = 5,
            author = "941150",
            text = "This leads to https://www.wowhead.com/quest=31946, even though it isn't currently listed, which requires you to plant and harvest 10 https://www.wowhead.com/item=74841 (two seeds gives you 10 carrots), then bring them back to this guy.",
            date = "2012-10-09T03:23:10-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30259#comments:id=1736288",
        },
        {
            id = 1813475,
            score = 5,
            author = "Tenjen",
            text = "i wonder if the \"teeth marks too small\" bit indicates Mina's kidnapping and being made to mess around with carrots",
            date = "2013-02-14T07:41:34-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30259#comments:id=1813475",
        },
        {
            id = 1744572,
            score = 3,
            author = "260805",
            text = "There are two entrances to a little cave where you'll find it much easier to find pieces of chewed up carrots.\n\nOne entrance is just northwest above the little farmer's house and one a little bit further down at 42,40.\n\nYou can find the chewed up bitw of carrots scattered around outside aswell, however I found them much easier to spot inside the little \"rabbit hole\".",
            date = "2012-10-18T04:19:38-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30259#comments:id=1744572",
        },
        {
            id = 1783007,
