            text = "Any one else spotted the mistake? Mung Mung asks you to collect 8 Chewed Up Carrots, yet the requirements ask you to collect 10....",
            date = "2012-12-17T10:23:50-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30259#comments:id=1783007",
        },
    },
    [30260] = {
        {
            id = 1696806,
            score = 204,
            author = "edwallols",
            text = "After completing the task for Gai Lan, he will meet you at Sunsong Ranch, where he will spend several minutes spraying weed killer on the westernmost corner of the irrigable land, creating new space for you to plant 4 vegetables.\n\nWhile he is killing the weeds, you will get a buff that tells you how many minutes are remaining.",
            date = "2012-08-06T13:54:59-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30260#comments:id=1696806",
        },
        {
            id = 1723467,
            score = 60,
            author = "lightclaw",
            text = "Finishing this quest line upgrades your farm and allows you to buy the \"Jinyu Princess\" Irrigation System (http://www.wowhead.com/item=89812) from Gina Mudclaw (http://www.wowhead.com/npc=58706).\n\nThe improvements to your farm take 15 minutes.  You receive a buff called Growing the Farm (http://www.wowhead.com/spell=114431) that shows how long you have before they will be completed.  The buff is not applied until you enter the farm plot phase.  During this time Gai Lan sprays the herbicide you just helped him make onto the weeds in your field.\n\nAlso note that since this is a buff, you must be logged into the game for 15 minutes before the buff falls off and the change takes effect.\n\nOnce the irrigation system is installed, you must leave your farm and return before the irrigation system will appear.",
            date = "2012-09-28T19:04:10-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30260#comments:id=1723467",
        },
        {
            id = 1729615,
            score = 57,
            author = "Roaning",
            text = "To actually get this quest you have to be honored with The Tillers faction.",
            date = "2012-10-03T06:06:59-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30260#comments:id=1729615",
        },
        {
            id = 1853221,
            score = 13,
            author = "Twinsen01",
            text = "This quest is part of a series of three quests that expand your farm.\nEach quest adds 4 more soil patches.\n\nhttps://www.wowhead.com/quest=30260 (Available when you are honored)\nhttps://www.wowhead.com/quest=30523 (Available when you are revered)\nhttps://www.wowhead.com/quest=30529 (Available when you are exalted and have collected all the votes)",
            date = "2013-05-15T06:07:52-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30260#comments:id=1853221",
        },
        {
            id = 1781805,
            score = 9,
            author = "AnrDaemon",
            text = "You need to be Honored with the [faction=1272] and reached https://www.wowhead.com/achievement=6193 to accept this quest.\nEven though none of the quests leading to ranch expansion require you to be able to fly in Pandaria...",
            date = "2012-12-15T11:58:39-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30260#comments:id=1781805",
        },
    },
    [30261] = {
        {
            id = 1745390,
            score = 105,
            author = "Taxmaster",
            text = "1st RULE: You do not talk about ROLL CLUB.\n2nd RULE: You DO NOT talk about ROLL CLUB.\n3rd RULE: If someone says \"stop\" or goes limp, taps out; the roll is over.\n4th RULE: Only one guy to a roll.\n5th RULE: One roll at a time.\n6th RULE: No cushioned padding, no safety gear.\n7th RULE: Rolls will go on as long as they have to.\n8th RULE: If this is your first night at ROLL CLUB, you HAVE to roll.",
            date = "2012-10-19T04:46:52-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30261#comments:id=1745390",
        },
        {
            id = 1738928,
            score = 100,
            author = "Hean",
            text = "Best ....daily quest...EVER!",
            date = "2012-10-11T21:49:07-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30261#comments:id=1738928",
        },
        {
            id = 1740249,
            score = 70,
            author = "eresin",
            text = "It's worth noting that even after you have handed the quest in you can speak to Kelari to roll whenever you like!\n\nLet the good times roll.",
            date = "2012-10-13T07:11:57-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30261#comments:id=1740249",
        },
        {
            id = 1703582,
            score = 66,
            author = "Calesta",
            text = "Completing this quest in under 70 seconds awards the Roll Club (http://mop.wowhead.com/achievement=7322) achievement.\n\nRoll over the boots which increase your speed while avoiding the black puddles which slow you.",
            date = "2012-08-23T20:23:46-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30261#comments:id=1703582",
        },
        {
            id = 1763743,
            score = 47,
            author = "BrightBrown",
            text = "It is possible that those missing this one may not realize the quest giver is not located close to the other 2 quest givers. Once you've completed several from those 2, another quest will come up sending you elsewhere... I happened to be looking at my mini-map while I was flying and spotted another blue \"!.\" Dropped down and found this roll club one!\n\nDefinitely a good change of pace kind of daily... just wish Gnomerobliteration (Uldum) was also a daily!",
            date = "2012-11-17T11:10:31-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30261#comments:id=1763743",
        },
    },
    [30263] = {
    },
    [30264] = {
        {
            id = 1739644,
            score = 7,
            author = "kaze950",
            text = "When I clicked the War Serpent, it was clearly Gold, but upon mounting, it had turned green!\n\nAre we, *snort*, to believe this is some sort of \"magic\" War Serpent?",
            date = "2012-10-12T14:48:35-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30264#comments:id=1739644",
        },
        {
            id = 1736497,
            score = 6,
            author = "lightclaw",
            text = "In addition to counting toward the Mantid Under Fire quest, the Hivelings killed in this quest can also grant the achievement Spreading the Warmth (http://www.wowhead.com/achievement=7321/spreading-the-warmth), which requires you to kill 60 Hivelings in a short period of time.\n\nThis can be done by launching cluster bombs at several groups of hivelings, starting with far away groups and moving closer.  Since the bombs take longer to travel to the distant groups, they all go off at more or less the same time and you get the achievement.",
            date = "2012-10-09T09:20:32-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30264#comments:id=1736497",
        },
        {
            id = 1678208,
            score = 5,
            author = "746315",
            text = "https://www.wowhead.com/npc=63972 killed during this quest will also count towards https://www.wowhead.com/quest=30243.",
            date = "2012-06-18T23:20:02-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30264#comments:id=1678208",
        },
        {
            id = 1816514,
