            author = "Kaelynath",
            text = "The name of this quest is a clear reference to the World War II movie of the same name, documenting the legendary Russian sniper by the name of Vasily Zaytsev.",
            date = "2013-02-21T14:10:02-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30264#comments:id=1816514",
        },
        {
