    [30265] = {
        {
            id = 1746385,
            score = 9,
            author = "oozie",
            text = "\"You have saved me some awkwardly wet robes with your generous aquatic ways. \"\n\nreally is some lovely little bits of writing in a lot of these quest texts :)",
            date = "2012-10-20T10:34:38-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30265#comments:id=1746385",
        },
        {
            id = 1746383,
            score = 7,
            author = "1047794",
            text = "Prying  https://www.wowhead.com/item=84646 from a mogu statue head?\n\nThis quest is reminiscent of the cover of the AD&D 1st Edition Players Handbook, where two rogues pry the giant ruby eyes from a monstrous statue.  LOL, good times.\n\nNote that you can get both eyes separately from each head.",
            date = "2012-10-20T10:28:30-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30265#comments:id=1746383",
        },
        {
            id = 1741030,
            score = 5,
            author = "ankorafeonix",
            text = "The Ruby eyes are in the eye sockets of heads lying around the sides of the lake pool. Can require a bit of patience, especially on busy servers, so I'd advise sitting at a head and camping it. I found the respawn to be about ~50 secs per eyesocket, so camping took me about 5-6 minutes total. Worth the wait, rather than swimming around watching others take my rubies.",
            date = "2012-10-14T02:32:17-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30265#comments:id=1741030",
        },
        {
            id = 1754554,
            score = 1,
            author = "Sonofargo",
            text = "Anybody else get reminded of aladdin while doing this quest? Even the quest name is a play from the movie. A diamond in the rough.",
            date = "2012-10-31T18:07:38-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30265#comments:id=1754554",
        },
        {
            id = 1829689,
            score = 1,
