    [30271] = {
        {
            id = 1709575,
            score = 51,
            author = "Sophos",
            text = "If this quest doesn't work for you, it is because Anduin should be following you. Try relogging or abandoning the quest and getting it again. A light should explode from you when you kill a sha near a pandaren.",
            date = "2012-09-05T01:44:49-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30271#comments:id=1709575",
        },
        {
            id = 1720570,
            score = 44,
            author = "1036868",
            text = "I can't seem to find how to start this quest.  I am fairly sure I have done all other quest hubs in between, but Anduin has no quests for me.",
            date = "2012-09-26T17:17:38-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30271#comments:id=1720570",
        },
        {
            id = 1933340,
            score = 40,
            author = "auslanderplates",
            text = "Wanted to finish this quest chain for quick August Celestials reputation, but it ended up taking me a while to be able to start this quest so I'll link what's necessary here.\n\nFirst, complete Into the Wilds (http://www.wowhead.com/quest=30462) by finishing all of the quests at Zhu's Watch. You'll then get an escort quest, Unsafe Passage (http://www.wowhead.com/quest=30269), which takes you to Crane Wing Refuge.\n\nIn Crane Wing Refuge, you'll need to complete these three quests before Anduin will offer you Sha Can Awe:\n\nThe Murksweats (http://www.wowhead.com/quest=30268)\nBlinding the Riverblades (http://www.wowhead.com/quest=30270)\nTread Lightly (http://www.wowhead.com/quest=30694)\n\nHope this helps!",
            date = "2014-01-10T08:48:51-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30271#comments:id=1933340",
        },
        {
            id = 1718456,
            score = 28,
            author = "Luckystar",
            text = "In order to get credit for this quest, you need to kill the mobs next to a monk with a Sha-Struck (http://www.wowhead.com/spell=129572) debuff. Otherwise, killing the mobs won't do anything.",
            date = "2012-09-25T08:21:20-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30271#comments:id=1718456",
        },
        {
            id = 1665492,
            score = 16,
            author = "HelsRike",
            text = "Just kill the NPC:s named \"Haunt of Despair\" close to the despairing pandaren and you'll get credit.",
            date = "2012-05-11T10:29:36-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30271#comments:id=1665492",
        },
    },
    [30272] = {
        {
            id = 1720634,
            score = 1,
            author = "mp3dk",
            text = "Kill the Sha Manifestations near the https://www.wowhead.com/npc=58968 or https://www.wowhead.com/npc=58969 to complete the quest https://www.wowhead.com/quest=30271.\n\nYou will also obtain a buff giving you additional haste and movement speed.",
            date = "2012-09-26T18:18:50-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30272#comments:id=1720634",
