    [30273] = {
        {
            id = 2605043,
            score = 72,
            author = "Seeley",
            text = "If after all the help you got from these comments, you still can't beat the boss. Here is the easiest way to beat the boss.\nEvery class can do it this way.\nJust fight the boss untill he goes back to the middle of the room.\nThat is your queue to move back up the stair you came from. When you are on the first flight of stairs the AoE attack won't hit you.\nRepeat this 3 times.\nMost of the small mobs will stay on the outer rim of the room so won't even attack you. You don't even need to bother about them.\nI ensure you, this will help you.",
            date = "2018-08-27T07:01:31-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30273#comments:id=2605043",
        },
        {
            id = 1718889,
            score = 67,
            author = "Brainsnack",
            text = "Remember, killing the echoes this Sha summons will replenish your health, because of Aura of Hope (http://www.wowhead.com/spell=114644).",
            date = "2012-09-25T15:20:41-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30273#comments:id=1718889",
        },
        {
            id = 1724676,
            score = 44,
            author = "1014647",
            text = "I died twice as a shadow priest since I could not recoup enough health by killing the adds to survive the massive AoE move the thing does.  I tried hiding in a few places in the room but could not survive through it after being hit once previously.  After a few attempts I used the stairs to escape some of the damage and made it though.\n\nSo kill all the adds (pulling them toward the stairs as you go) and then go up a few stairs to make the AoE manageable.",
            date = "2012-09-29T14:31:30-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30273#comments:id=1724676",
        },
        {
            id = 1740089,
            score = 27,
            author = "899614",
            text = "An interesting side note, as a member of the horde on this quest, I was hit by an alliance aoe (barely any dmg), and Anduin Wrynn turned hostile towards him and chased him down for a good two minutes trying to kill him.\nIf you were not aware, Anduin Wrynn is the son of King Varian Wrynn, the leader of the Alliance.",
            date = "2012-10-13T02:44:48-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30273#comments:id=1740089",
        },
        {
            id = 1783090,
            score = 17,
            author = "Cissy44",
            text = "I am a lvl 88 hunter, my pet with me was Loque and I died 3 times trying to finish this quest and my gear was pretty much all yellow so I decided to go collect my remains and gate home. When I got back downstairs there was a lvl 87 warrior battling the big guy. I sent in Loque and helped him finish off the Sha. Well lo and behold, I got credit as well. I was one happy camper. And made a new friend as well. So if you see someone else on their way in, help them...and you both will get credit. Merry Christmas and Happy New Year.",
            date = "2012-12-17T14:02:46-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30273#comments:id=1783090",
        },
    },
    [30274] = {
        {
            id = 1795401,
            score = 10,
            author = "Boomerasp",
            text = "Simple quest !  1st--don't try to enter sphere.  It'll just kick you out.  2nd--as you face the sphere, look to your left, and you'll see a small glowing shard just outside of sphere.  Clicking will kill it.  3rd-- go back to your right til you see another small red shard.  Kill it.  4th--go left around the big tree and you'll hit the 3rd and last shard.  When you click on it the sphere will disappear, and you can enter the area and collect your reward.",
            date = "2013-01-09T15:20:02-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30274#comments:id=1795401",
        },
        {
            id = 1949422,
