    [30275] = {
        {
            id = 1742835,
            score = 100,
            author = "GQuard",
            text = "In order to begin this quest, you must slaughter a non-aggressive baby crocolisk who is happily munching away on its meal in order to put its mother in a distraught state of rage and sorrow, as to get her to attack you in defense of her fallen young. Then you must kill her as well, tearing a mother and baby apart for all eternity. And then you lop the tail off her corpse to begin this line.\n\nThis quest has been on my conscience for the past 5 days. I don't think I can recover from this one.",
            date = "2012-10-15T20:33:14-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30275#comments:id=1742835",
        },
        {
            id = 1725663,
            score = 18,
            author = "HordeSkorp",
            text = "To start this quest you must first kill Manglemaw in the Guilded Fan to the left of the Pools of Purity its a non agressive crocolisk however when you kill it its mother appears from the water shes an easy to kill non elite with 645k health and when you kill her she drops the tail which begins the quest. Hope this helps.",
            date = "2012-09-30T06:31:13-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30275#comments:id=1725663",
        },
