        {
            id = 1774960,
            score = 1,
            author = "Crusader411",
            text = "For level 90s:\n\nThe Golden Lotus quest \"A Thousand Pointy Teeth\" at Whitepetal Lake is a great method to farm Grisly Trophies. The Knifetooth Swarmers only have about 40k health and can be found in groups of 3-5.",
            date = "2012-12-03T18:01:00-06:00",
