    [30291] = {
        {
            id = 1720707,
            score = 14,
            author = "HGFenn85",
            text = "The quest giver is throwing fire balls to the lake, when they hit, they will stun the fish, collect them. Make sure you collect the stunned ones, if they're moving it won't count.",
            date = "2012-09-26T19:35:23-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30291#comments:id=1720707",
        },
        {
            id = 1743587,
            score = 9,
            author = "Naxius112358",
            text = "You can pick up the fish while mounted.  So you can fly around, if you want to try and get close to the water.  Or, you can use a sea turtle if you have one.  A the very least you can outrun the other players.\n\nI preferred the use of the turtle as with flying mounts I had a tendency to overshoot where the fish were.  Not good when there's a dozen people questing.\n\nEdit: I also recommend using a water strider if you have one, this is by far the most optimal way of picking up the fish.",
            date = "2012-10-16T19:12:15-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30291#comments:id=1743587",
        },
        {
            id = 1818136,
            score = 7,
            author = "sitecow09",
            text = "\"As an added bonus, my method ensures they're already cooked! If that's not a marvel of modern efficiency, I don't know what is.\"\n-Ren Firetongue, leveling up fishing AND cooking at the same time!",
            date = "2013-02-25T14:58:09-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30291#comments:id=1818136",
        },
        {
            id = 1817372,
            score = 3,
            author = "Henderman",
            text = "The water strider (http://www.wowhead.com/item=81354) mount from Angler's rep is excellent for this quest. Keeps you on top of the water and you can easily see the fish.",
            date = "2013-02-23T12:28:20-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30291#comments:id=1817372",
        },
        {
            id = 1892714,
            score = 3,
            author = "829438",
            text = "If you have it, the best thing to ride for this quest - bar none - is https://www.wowhead.com/item=85500.  You stay closer to the water than you would on a mount, which means you can reach farther; also, there is less screen clutter, so you can see more fish.  Best of all, since the raft won't fly, you don't have to worry about z-axis control.",
            date = "2013-09-03T23:00:08-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30291#comments:id=1892714",
        },
    },
