    [30300] = {
        {
            id = 1736206,
            score = 24,
            author = "Ahi808",
            text = "The Shao-Tien Torturers have a better chance of dropping the key.\nhttps://www.wowhead.com/npc=63641\nIt's probably a good idea to get the key first before doing any quests in this area that involve killing. The prisoners you release will follow you for a bit and auto-aggro any mobs nearby. Should you not want any followers just fly up and they will disappear when you get high enough.",
            date = "2012-10-09T01:00:59-05:00",
