        {
            id = 1813767,
            score = 4,
            author = "505467",
            text = "If you are having a hard time finding a Shao-Tien Torturer (http://www.wowhead.com/npc=63641) for a Shao-Tien Cage Key (http://www.wowhead.com/item=85582) for the Golden Lotus daily (The Key to Success (http://www.wowhead.com/quest=30300)). I made a useful little macro to find one with ease\n/target Shao-Tien Torturer\n\nPut it on your action bar and spam away till you find one!",
            date = "2013-02-15T01:05:16-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30300#comments:id=1813767",
