    [30302] = {
        {
            id = 1734737,
            score = 22,
            author = "waccoe",
            text = "If you, like me, didn't read the quest info good enough he's down in the halls. So don't spend 10 minutes above the halls waiting for him to spawn.",
            date = "2012-10-07T16:54:42-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30302#comments:id=1734737",
        },
        {
            id = 1738832,
            score = 22,
            author = "LucidityAxel",
            text = "As soon as you hit Revered with Golden Lotus, a new quest line spawns for you; this causes certain parts of the Vale of Eternal Blossoms go into a different phase and has the unfortunate side effect of making the target mob for this quest completely unreachable.\n\nThe only way to correct this issue is to return to the Golden Pagoda (the place underneath the big panda statues with crossed spears where you always start the daily quests for this zone) and complete the newly spawned line that starts with this quest:\n\n[quest=30640 domain=www]\n\nOnce this line is completed, the zone will return to normal phasing and you will once again be able to complete this quest.\n\nThis is as of patch 5.0.5; the issue may be patched by the time you read this comment and this workaround may no longer be applicable.",
            date = "2012-10-11T19:25:41-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30302#comments:id=1738832",
        },
        {
            id = 1735392,
            score = 6,
            author = "Deathstreak",
            text = "There would seem to be a phasing issue with this. Cause the moment i enter the halls, the runes and mobs disappear. Tested this by pulling 2 other mobs outside of the halls, moment i enter, they despawn. GG blizz GG",
            date = "2012-10-08T08:06:22-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30302#comments:id=1735392",
        },
        {
            id = 1752213,
            score = 5,
            author = "hanco007",
            text = "For me he spawned to the north (still underground) of where the quest marks that he will spawn.  He spawns where the pool is (nice in case you get the debuff).  This is also where the giant spider spawns from.",
            date = "2012-10-28T00:39:51-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30302#comments:id=1752213",
        },
        {
            id = 1737410,
            score = 3,
            author = "1037507",
            text = "It also helps if someone else in party who has not yet reached revered kills whatever is inside the halls, you will still complete the quest.",
            date = "2012-10-10T10:26:00-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30302#comments:id=1737410",
        },
    },
