    [30305] = {
        {
            id = 1743125,
            score = 5,
            author = "1040929",
            text = "The traps look exactly like the hunter snake traps + they are glimmering so they are very visible and easy to find -> Just keep ya' eyes open :) Then you simply pull and enemy and take him through the trap! That's it!",
            date = "2012-10-16T06:34:33-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30305#comments:id=1743125",
        },
        {
            id = 1752392,
            score = 3,
            author = "thebdc",
            text = "The traps have an AOE effect, so you get credit for multiple enemies when they are close enough. Just pull a couple mobs, let them group up in melee range and then run over the trap. You don't trigger it yourself.",
            date = "2012-10-28T07:18:36-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30305#comments:id=1752392",
        },
    },
    [30306] = {
        {
            id = 1725634,
            score = 16,
            author = "Ampdk",
            text = "This is working now.",
            date = "2012-09-30T06:01:31-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30306#comments:id=1725634",
        },
        {
            id = 1762411,
            score = 14,
            author = "Jeolene",
            text = "So, I found the quickest way to deal with this quest is to have the G91 Landshark, [spell=127127 domain=www]\n\nYou get them from engineers or in my case, Blingtron.  These nasty little cousins of sharks with lasers deal a whopping 37,500 damage in one hit.  Just stand there and let them come to you and beat on you, by the time you can do this quest, you should have decent armor, they only do minor damage anyway.\n\nWhen you have them all around you, lay down an AoE and then the landshark, it will decimate them all in nearly one shot and your AoE should be good enough to pick up the rest of the health in just a couple seconds.\n\nNow, before you say \"but what about other people?\", there is an achievement tied to this to defeat 10 of them in 10 seconds, so you may as well do it anyway and get the achievement.  Plus, it's funny to watch the entire group get blasted like fishing by dropping dynamite in water :P",
            date = "2012-11-14T16:17:13-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30306#comments:id=1762411",
        },
        {
            id = 1946618,
            score = 6,
            author = "Jaxcomet",
            text = "As a Hunter you can basically just stand there and let your pet one shot each trainee as they run in.",
            date = "2014-02-25T09:06:38-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30306#comments:id=1946618",
        },
        {
            id = 1734176,
            score = 4,
            author = "eresin",
            text = "No longer bugged however as a hunter I found that if my pet landed the killing blow I did not get credit, so put your pets on passive for this one, or just be sure that you get the killing blow",
            date = "2012-10-07T05:51:42-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30306#comments:id=1734176",
        },
        {
            id = 1763574,
            score = 4,
