    [30312] = {
        {
            id = 1747305,
            score = 8,
            author = "Naxius112358",
            text = "I noticed that each hit with a cannon damages you for about 30k (at least on my rogue).\n\nEach wounded defender starts with 281k/1,378k health.\n\nMeaning they took about 1.1 million damage.\n\nSo each defender was hit about 37 times...each.\n\nSomeone isn't ready for raiding....",
            date = "2012-10-21T15:35:30-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30312#comments:id=1747305",
        },
        {
            id = 1727480,
            score = 4,
            author = "764019",
            text = "If you are a shadow priest, and I suspect any other healing class, just cast Halo and heals others up. You still have to use the bandages but anyone hit by the halo and healed by other players will count towards you! This is helpful if there are lots of people doing the quest.",
            date = "2012-10-01T13:11:22-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30312#comments:id=1727480",
        },
        {
            id = 1866012,
            score = 3,
            author = "Archaix",
            text = "I pretended I was Yao from Mulan, running through the cannon blasts from one end to the other while humming the inspirational part of \"I'll Make a Man Out of You\".",
            date = "2013-06-13T02:18:40-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30312#comments:id=1866012",
        },
        {
            id = 1736658,
            score = 2,
            author = "883209",
            text = "/target Wounded Defender\n/use Shado-Pan Bandages",
            date = "2012-10-09T13:05:30-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30312#comments:id=1736658",
        },
        {
            id = 1746707,
            score = 2,
            author = "774111",
            text = "These can be healed without the bandages. But it takes longer than healing with the bandages at current gear levels. Given how frustratingly slow dailies already are as a healer, you'd think they'd give this one little nod to us, but no :-)",
            date = "2012-10-20T19:32:49-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30312#comments:id=1746707",
        },
    },
    [30313] = {
