    [30317] = {
        {
            id = 1770134,
            score = 152,
            author = "darkanima270",
            text = "Wing Nga (/npc=60231) Is a Female Pandaren NPC, she can be found outside the inn keeper in Halfhill, approximately 30 yard on the left side of the mail box",
            date = "2012-11-28T13:00:33-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30317#comments:id=1770134",
        },
        {
            id = 1723536,
            score = 130,
            author = "950640",
            text = "Oddly, this quest is available in all weathers. Even storms.\nNot only are you flying a kite in a storm, you're riding on it.\nThrowing buckets of water to water the plants. In the rain.",
            date = "2012-09-28T20:03:31-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30317#comments:id=1723536",
        },
        {
            id = 1695870,
            score = 77,
            author = "746315",
            text = "If you are \"buddies\" with Farmer Fung, Wing Nga offeres you a \"high-altitude kite\" for this quest: this gives you a better vantage point. You can see ALOT more of the heartland with the special kite which lets you finish the quest much faster.\nIf you are \"good friends\" with Farmer Fung, you can use the \"swift yellow kite\" which is about twice as fast as the ordinary kite. You see the same area, but cover ground very fast.\nIf you are \"best friends\" with Farmer Fung, you can use the \"dancing green kite\" for this quest. This kite will make your toon dance the whole time while on the quest.",
            date = "2012-08-04T05:16:38-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30317#comments:id=1695870",
        },
        {
            id = 2018192,
            score = 72,
            author = "ggregt",
            text = "As of 6.0.2 to be able to see the circles you have to water you have to have video setting (System/Graphics) \"Projected Textures\" set to Enabled, otherwise this quest is a nightmare. New hassle of 6.0 for those of us with terribad video cards.",
            date = "2014-10-24T00:08:20-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30317#comments:id=2018192",
        },
        {
            id = 1654804,
            score = 51,
            author = "murphmanfa",
            text = "Actually, the quest title is a reference to the Rime of the Ancient Mariner by Samuel Taylor Coleridge- particularly this bit:\n\nDown dropped the breeze, the sails dropped down,\n'Twas sad as sad could be;\nAnd we did speak only to break\nThe silence of the sea!\n\nAll in a hot and copper sky,\nThe bloody sun, at noon,\nRight up above the mast did stand,\nNo bigger than the moon.\n\nDay after day, day after day,\nWe stuck, nor breath nor motion;\nAs idle as a painted ship\nUpon a painted ocean.\n\nWater, water, every where,\nAnd all the boards did shrink;\nWater, water, every where,\nNor any drop to drink.\n\nFor those curious, the full poem can be found here (http://www.online-literature.com/coleridge/646/).",
            date = "2012-04-16T10:24:21-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30317#comments:id=1654804",
        },
    },
    [30318] = {
        {
            id = 1790601,
            score = 62,
            author = "louied777",
            text = "I've slain an Old God, Yogg-Saron.\nI've slain the Firelord, Ragnaros.\nI've seen the fall of Thrall and the unfortunate rise of Garrosh Hellscream.\nI've slain almost 60,000 Alliance.\nI've adventured through hundreds, maybe thousands, of dungeons and plundered gold and treasures....\nNow, I get to dip amorous roosters in water to soothe their passions.",
            date = "2013-01-01T09:53:31-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30318#comments:id=1790601",
        },
        {
            id = 1751825,
            score = 45,
            author = "321140",
            text = "So far, We've encountered chickens with the following names:\n1. Egga.\n2. Mantidsbane\n3. Thunderpeck\n4. Stumbleflutter\n5. Madam Specklebottom\n6. Mother Clucks\n7. Bucka-Bucka Betty.\n\nThanks for the contributions.\nFeel free to add more when you see them.",
            date = "2012-10-27T13:18:03-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30318#comments:id=1751825",
        },
        {
            id = 1755385,
            score = 40,
            author = "Aaygo",
            text = "If you're Best Friends with Old Hillpaw you can do this quest in Sunsong Ranch with the chickens he gives you.\nThis just removes the hike up to the Heartland if anything else...\n\nWhy downrate correct info? How can this be annoying to people?\n\nLater edit:\nAs of 5.2 I believe this is no longer possible. The chickens are either killable neutral or you cannot interract with them with the quest. Will do the quest a few more times to be sure, but it's pretty much clear... oh well",
            date = "2012-11-02T05:34:13-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30318#comments:id=1755385",
        },
        {
            id = 1723547,
            score = 34,
            author = "pixila",
            text = "For this quest, you fly to The Heartland and there you will find lots and lots of sparkling chickens. Click on one, and a yellow text should appear, as well as an action button. There are 2 kinds of 'fake' chickens you can get:\n\nAmorous Chicken, which needs to be dunk in water nearby and;\n\nLost Chicken that needs to be returned to the nearest chicken coop.\n\nTook me about 10 or so fake chickens to get the prize one.\n\nIt's a very easy and fast quest to complete and rewards a good amount of reputation with Old Hillpaw.",
            date = "2012-09-28T20:30:35-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30318#comments:id=1723547",
        },
        {
            id = 1737239,
            score = 25,
            author = "xSaix",
            text = "\"Don't worry, I'll make sure she's punished later.\"\n\nO...kay...\n\nI'm just gonna go over here now...",
            date = "2012-10-10T06:27:29-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30318#comments:id=1737239",
        },
    },
    [30319] = {
        {
            id = 1723560,
            score = 26,
            author = "126940",
            text = "Technically, you don't have to click on each marmot to stomp them .\nMy warrior heroic leaped into a group of 6 marmots and aoe stomped them.\nLooks like any AOE damage will give you credit.",
            date = "2012-09-28T20:50:15-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30319#comments:id=1723560",
        },
        {
            id = 1750368,
            score = 22,
            author = "Interest",
            text = "Not only do AoE abilities kill the Marmots as posted above, but AoEs can also kill the Insect Swarms. Just be careful not to walk through any dead Insect Swarms because they'll still slow you down.\n\nHere's what I recommend doing for each class to make life easier when doing this daily as well:\n\nDeath Knight: https://www.wowhead.com/spell=43265 and either https://www.wowhead.com/spell=48721 or https://www.wowhead.com/spell=49184\nDruid: Use https://www.wowhead.com/spell=16914, https://www.wowhead.com/spell=88747, and/or https://www.wowhead.com/spell=106785.\nHunter: Just drop an https://www.wowhead.com/spell=13813 on the cart where the Hozen is at and proceed to afk for 24-30 seconds. Rinse and repeat as needed.\nMage: As mentioned above, use https://www.wowhead.com/spell=1449 with the glyph (http://www.wowhead.com/item=42736).\nMonk: Spam https://www.wowhead.com/spell=107270 relentlessly.\nPaladin: Use https://www.wowhead.com/spell=26573 or whack/judge marmots with https://www.wowhead.com/spell=20154 up.\nPriest: The easiest way is to glyph https://www.wowhead.com/spell=132157 and use that. Otherwise just use https://www.wowhead.com/spell=124469.\nRogue: As mentioned above, spam https://www.wowhead.com/spell=51723.\nShaman: Drop a https://www.wowhead.com/spell=8190. Supplement with other spells.\nWarrior: Use https://www.wowhead.com/spell=6544 (preferably glyphed to increase usage) and an AoE talent (http://www.wowhead.com/talent#w1||) of your choice (preferably https://www.wowhead.com/spell=46968)\nWarlock: Use either https://www.wowhead.com/spell=1949 or https://www.wowhead.com/spell=5740. Using the https://www.wowhead.com/spell=108508 talent is recommended.",
            date = "2012-10-25T16:53:34-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30319#comments:id=1750368",
        },
        {
            id = 1730069,
            score = 21,
            author = "Kakashi11",
            text = "Whenever i do this quest, I always think of This (http://www.youtube.com/watch?v=k76IGLi6jWI)",
            date = "2012-10-03T13:57:24-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30319#comments:id=1730069",
        },
        {
            id = 1825022,
            score = 13,
            author = "590573",
            text = "D.E.H.T.A would not approve of this",
            date = "2013-03-09T02:28:43-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30319#comments:id=1825022",
        },
        {
            id = 1748067,
            score = 12,
            author = "Sharkon",
            text = "Faces filled with joy and zest,\nWhat a magical daily quest,\nHowdy Ho! It's Marmot Stomping Day!\n\nPut your Tillers straw hat on,\nGo find Wika-Wika on the lawn,\nDon't you know it's Marmot Stomping Day?\n\nAll the little girls and boys,\nLove that wonderful squealing noise!\nYou'll know what this day's about,\nWhen you stomp a marmot's guts right out.\n\nSo, come along and have a laugh,\nSnap their marmot spines in half!\nEquip your boots and stomp your cares away!\nHip hip hooray, it's Marmot Stomping Day!\n\nPeople from both red and blue,\nCrushing marmots into goo!\nWhy we do it? 'cause we're paid!\nAnd it's such a festive holiday!\n\nSo let the stomping fun begin,\nBash their marmot skulls right in,\nIt's a quest, so that makes it okay!\nHey everyone, it's Marmot Stomping...\nWe'll have some fun on Marmot Stomping...\nPut down your gun, it's Marmot Stomping...\nHip Hip Hooray, it's Marmot Stomping Day!\n\nMarmot Stomping Day, hey!",
            date = "2012-10-22T15:15:47-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30319#comments:id=1748067",
        },
    },
    [30320] = {
        {
            id = 1721748,
            score = 66,
            author = "737683",
            text = "If you're on your flying mount when in the spirit realm, landing near the tormentors (the banshee ghosts) briefly (I only touched down and jumped back into the air) causes them to aggro, and when they can't reach you, instead of going back to where they were they temporarily despawn.\n\nUse this to get those big groups of spirits that are guarded by the ghoasts.",
            date = "2012-09-27T13:40:16-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30320#comments:id=1721748",
        },
        {
            id = 1690404,
            score = 56,
            author = "Cielos",
            text = "In order to see the spirits in The Golden Stair, you have to click on one of the purple spirit vortexes around the area.",
            date = "2012-07-20T15:26:47-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30320#comments:id=1690404",
        },
        {
            id = 1750105,
            score = 32,
            author = "901632",
            text = "Quite simply , this quest was a pain in the ass until i entered one of the vortices whilst on my Flying Cloud mount.  This enabled me to simply fly around and tag the Pandaren spirits without aggroing any of the banshees.  Will do it this way from now on ....\n\nedit :   whilst on your flying mount , IF you do cop a bit of aggro from the banshees , simply fly straight up to lose the aggro , and i have now noticed that the aggro'd banshee will despawn :)\n\nedit 2 : please regard the comment from cropz -  copied below\n\nAttention Hunters, Warlocks and other pet classes: your pet does not phase out with you, so dismiss it while doing this quest unless you want to aggro everything you come across.",
            date = "2012-10-25T09:05:40-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30320#comments:id=1750105",
        },
        {
            id = 1732055,
            score = 26,
            author = "894407",
            text = "Attention Hunters, Warlocks and other pet classes: your pet does not phase out with you, so dismiss it while doing this quest unless you want to aggro everything you come across.",
            date = "2012-10-05T07:34:54-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30320#comments:id=1732055",
        },
        {
            id = 1856973,
            score = 14,
            author = "1122512",
            text = "This used to be my favorite Golden Lotus daily. But as of patch 5.3 it takes 5 times longer to completed due to dismounting you every time you free one pandaren spirit. hope its not intentional change",
            date = "2013-05-24T03:54:47-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30320#comments:id=1856973",
        },
    },
    [30321] = {
        {
            id = 1804726,
            score = 9,
            author = "stickshift",
            text = "Owners of the Jade Tentacle (http://www.wowhead.com/item=89686#reward-from-a) can mess with people's head in this daily.\n\n* Do this at peak hours (like a daily reset on Saturday) when there is a group of people and serious confusion.\n\n* For best results feed your companion a Magical Pet Biscuit (http://www.wowhead.com/item=71153#reward-from-q) and hide behind something.\n\n* Give your companion an enticing name like \"Daily Reward\" or something exotic then give it that quest tingle with a Pet Grooming Kit (http://www.wowhead.com/item=43352#screenshots).\n\n*Won't fool anyone paying half attention, esp. pet collectors, but I've laughed myself sick a few times watching some hapless victim stop cold on the daily and you know they're frantically trying to get the drop on \"something special\".",
            date = "2013-01-26T23:04:29-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30321#comments:id=1804726",
        },
