    [30322] = {
        {
            id = 1740149,
            score = 154,
            author = "804246",
            text = "i like how she pay you 20g for collecting 4g debts",
            date = "2012-10-13T04:28:07-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30322#comments:id=1740149",
        },
        {
            id = 1740106,
            score = 134,
            author = "Stealthfire13",
            text = "This quest is obviously bugged, as I received no Light Side/Open Palm/Paragon or Dark Side/Closed Fist/Renegade points from it.",
            date = "2012-10-13T03:18:36-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30322#comments:id=1740106",
        },
        {
            id = 1729644,
            score = 88,
            author = "jojopojo64",
            text = "Judging from comments and speaking with other players, seems there's no true advantage (yet) to either paying off the two debtors or threatening them and may just be there for RP purposes. However, Blizzard's been known for off-kilter rewards and perhaps these NPCs may later send you stuff in the mail as thanks like various NPCs from the Tillers do. I'll update once more's known - personally, I paid off the 2g (which in Pandaria, seems to be a drop in a very large bucket).\n\nEdit: As I've hit revered and received this quest four times already with nothing different happening, seems it's just a little bit of RP you can choose to do.",
            date = "2012-10-03T06:39:37-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30322#comments:id=1729644",
        },
        {
            id = 1732306,
            score = 87,
            author = "615183",
            text = "for just two gold a day, you can save a couple pandas!",
            date = "2012-10-05T12:51:56-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30322#comments:id=1732306",
        },
        {
            id = 1736025,
            score = 79,
            author = "Snoipah",
            text = "Doing this quest today, innkeeper paid happily, the grommle paid but noted i was intimidating(even though last time i paid for him), lolo lio said he was saving his money to leave the town and said i was an adventurer so i should understand, and I did so I paid for him.\n\nHowever...\n\nhttps://www.wowhead.com/npc=59581\n\nThe only comment on that page(at the time of this post) is about him saying he'd pay if she did a \"favor\". I didn't have that experience, instead he laughed in my face and said if she wants the payment she should come there herself and they could find an \"agreement\".\n\nBasically, in my humble opinion, threatening this jerk is OK.\n\nBecause Gina will be -my- harvest moon wife!",
            date = "2012-10-08T20:02:09-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30322#comments:id=1736025",
        },
    },
    [30323] = {
        {
            id = 1722402,
            score = 18,
            author = "mournerslament",
            text = "Burrow entrances are in the mountains, located at:\n47.00, 20.97\n43.88, 22.36\n39.38, 20.39",
            date = "2012-09-28T01:20:34-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30323#comments:id=1722402",
        },
        {
            id = 1730936,
            score = 15,
            author = "1036362",
            text = "If you fly over the marked quest area and can't find the vermin, it's because you have to look for holes in the ground. You know, kind of like a rabbit's hole, only a vermin hole. :)",
            date = "2012-10-04T07:52:23-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30323#comments:id=1730936",
        },
        {
            id = 1821968,
            score = 8,
            author = "842273",
            text = "Once 5.2 hit today I must have killed over 100 vermin until I finally dropped the quest since I could not get the bracelet to drop.  I used to get all 3 within the first 5-6 kills.  Wasted over 20 minutes as there were several horde and alliance killing these mobs experiencing the same problem.  I'd stay clear of this quest until they fix this.",
            date = "2013-03-05T23:28:15-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30323#comments:id=1821968",
        },
        {
            id = 1834666,
            score = 7,
            author = "962667",
            text = "You need to be able to fly to reach Springtail Crag.",
            date = "2013-03-26T09:15:58-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30323#comments:id=1834666",
        },
        {
            id = 1946256,
            score = 5,
            author = "736775",
            text = "They don't even fit. (https://www.cfa.harvard.edu/~mbayliss/dog_shoes_comic.jpg)",
            date = "2014-02-24T04:02:32-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30323#comments:id=1946256",
        },
    },
    [30324] = {
        {
            id = 1745116,
            score = 3,
            author = "Nekrotik",
            text = "You tik-digglin' jook-mankers!",
            date = "2012-10-18T19:25:29-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30324#comments:id=1745116",
        },
        {
            id = 1741386,
            score = 1,
            author = "992022",
            text = "Easiest if you can land in the middle of the little Rockflingers (usually groups of 4, only 59K HP) and AOE them. The Collectors (256K HP) hit hard, and then there's the Ravager elites.... :)",
            date = "2012-10-14T12:27:23-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30324#comments:id=1741386",
        },
        {
            id = 1795120,
            score = 1,
            author = "982813",
            text = "For the bigger mobs, if you line them up with Stolen Brew Kegs (http://www.wowhead.com/npc=66529), then use an AoE effect, the kegs explode and apply a debuff that causes the mobs to take extra damage. Just make sure that you're not within the explosion radius too! Otherwise... ow.",
            date = "2013-01-09T01:26:43-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30324#comments:id=1795120",
        },
        {
            id = 1853763,
            score = 1,
            author = "Anok8",
            text = "It's easier if you kill https://www.wowhead.com/npc=59120s. Some groups will do the job :D!\nGood Luck.",
            date = "2013-05-17T06:48:19-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30324#comments:id=1853763",
        },
    },
    [30325] = {
        {
            id = 1706358,
            score = 13,
            author = "sakera",
            text = "To find the area, look for a large green statue with fiery \"laser beams\" shooting from its eyes.  Statue is found in the Skyrange plateau of Valley of the Four Winds.\n\nThe blazing embers appear in and around the area after the fiery \"laser eye-beams\" from the giant statue passes over the ground.  They spawn for about 15 seconds.  The fire beams don't WILL harm you.\n\nThe candles are scattered around the same area and the Kunzen Ritualist is usually sitting on a rock.\n\nThe candles and the burning embers will both show clickable gears when you hover over them.",
            date = "2012-08-30T09:49:25-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30325#comments:id=1706358",
        },
        {
            id = 1892930,
            score = 7,
            author = "Jayfan34",
            text = "Is it really our place to interfere with these peoples religious beliefs?  Tsk-tsk.",
            date = "2013-09-04T22:40:12-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30325#comments:id=1892930",
        },
        {
            id = 1882233,
            score = 5,
            author = "Yogilaw",
            text = "Nice quest, just stay out of the fire beam when stomping on the embers. Ritualist is an easy kill, candles can kicked where you have no danger.\n\nBTW - If you can't fly do other quests until you can. None of the ridge based Hozen or Vermin can be reached without flight ability.",
            date = "2013-07-30T04:47:09-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30325#comments:id=1882233",
        },
        {
            id = 1795655,
            score = 3,
            author = "DFENS",
            text = "You can kite the Kunzen Ritualist into the path of the eye beams for an easy kill.",
            date = "2013-01-10T01:25:56-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30325#comments:id=1795655",
        },
    },
    [30326] = {
        {
            id = 1749583,
            score = 9,
            author = "Kiputytto",
            text = "To the right of your quest log is a portrait of the Legend-Chief and below it it says:\n\"I don't know what his name will be - they regularly elect new legend-chiefs.\"\n\nThere are five of them that you'll see each cast https://www.wowhead.com/spell=128543 and https://www.wowhead.com/spell=9672.\n\nhttps://www.wowhead.com/npc=59133\nhttps://www.wowhead.com/npc=59131\nhttps://www.wowhead.com/npc=59135\nhttps://www.wowhead.com/npc=59132\nhttps://www.wowhead.com/npc=59134\n\nThey spawn in the same spot (31, 28) sitting on a rock with two hai-pus next to them.\n\"Beware the jinyu\n\nThey are a bunch of dookers\n\nOok'em in the jerb.\"\n\n\"A slicky in hand\n\nIs worth two in the dooker\n\nSo says chief Ee Ee!\"",
            date = "2012-10-24T15:18:40-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30326#comments:id=1749583",
        },
        {
            id = 1758089,
            score = 4,
            author = "kissji",
            text = "Fish says:\nWow! Look at this! It's...\n\nOh, I think that's a dirty picture. But the rest of this is very interesting! I just love learning how other creatures think.\nThanks,",
            date = "2012-11-06T06:45:01-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30326#comments:id=1758089",
        },
        {
            id = 1817201,
            score = 4,
            author = "347538",
            text = "I completed this quest.  The map show that the quest turn in is in halfhill market, but Fish is not there.  She is not on the dock.  She is on my farm, and when I speak with her, I cannot turn in the quest.\n\nHelp.",
            date = "2013-02-23T02:04:58-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30326#comments:id=1817201",
        },
        {
            id = 1787698,
            score = 3,
            author = "333762",
            text = "Just step out of his rain of flaming rocks, or whatever he calls them.  If someone else is already whooping up on him when you get there, join right in - I think multiple players can loot him off of a single kill.",
            date = "2012-12-26T13:29:30-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30326#comments:id=1787698",
        },
        {
            id = 1814202,
            score = 3,
            author = "Tenjen",
            text = "Nothing like learning about a peoples culture by killing their cultural leader (who's smart enough to be a powerful caster for a hozen) and stealing their races records and stories, forever destroying that culture as it can now not be passed on to future generations.",
            date = "2013-02-16T04:04:44-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30326#comments:id=1814202",
        },
    },
    [30327] = {
        {
            id = 1693682,
            score = 46,
            author = "lordkarthas",
            text = "The name of this quest is a reference to the Flash game You Have To Burn The Rope (http://www.kongregate.com/games/Mazapan/you-have-to-burn-the-rope).",
            date = "2012-07-29T15:36:43-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30327#comments:id=1693682",
        },
        {
            id = 1744897,
            score = 34,
            author = "902462",
            text = "So... I have this daily. I have my weapon, and I have a torch. The torch is on fire. There's a rope in front of me. What do I do? I've tried cutting the rope, undoing the rope, stealing the rope. Nothing works. The torch is really, really hot. Like, fire hot. And the rope is really dry. What am I supposed to do? The quest name is so confusing and the dialogue isn't much help. Can someone tell me what I need to do to complete this daily?",
            date = "2012-10-18T13:26:12-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30327#comments:id=1744897",
        },
        {
            id = 1801045,
            score = 20,
            author = "1011285",
            text = "Congratulations\nyou managed to kill that boss you see\nthe Grinning Colossus\nyou're the hero we all wish we could be\nYou made it through the tunnel\nthen you grabbed that fire on the wall\nyou jumped up above\nthen you burned the rope and saved us all\n\n(No downvoting just because you don't get it)",
            date = "2013-01-19T12:07:15-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30327#comments:id=1801045",
        },
        {
            id = 1731434,
            score = 12,
            author = "Avvara",
            text = "Rope locations:\n31.5, 43.2\n31.5, 39.5\n32.2, 38.2\n33.3, 35.5\n33.6, 32.2\n34.0, 31.3",
            date = "2012-10-04T16:43:42-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30327#comments:id=1731434",
        },
        {
            id = 1728774,
            score = 9,
            author = "150104",
            text = "The rope is coiled up on the small platforms leading up to Kunzen Village.\n\nSubmitted a Screenshot for clarification of what to look for.",
            date = "2012-10-02T13:06:31-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30327#comments:id=1728774",
        },
    },
    [30333] = {
        {
            id = 1720540,
            score = 34,
            author = "Zaevul",
            text = "You can find her in a cave.  The entrance is just south west of where the quest shows to go.",
            date = "2012-09-26T16:54:41-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30333#comments:id=1720540",
        },
        {
            id = 1725823,
            score = 25,
            author = "60723",
            text = "The entrance is the hole at 46,21",
            date = "2012-09-30T08:56:39-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30333#comments:id=1725823",
        },
        {
            id = 1733390,
            score = 9,
            author = "Talyrius",
            text = "The https://www.wowhead.com/npc=59516 can sometimes become permanently evade bugged if she is pulled out of her burrow or her target is no longer within line of sight. If this happens, you can ask a Game Master for assistance in respawning her, wait for a realm restart, or try killing her slowly with AoE damage.",
            date = "2012-10-06T12:35:31-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30333#comments:id=1733390",
        },
        {
            id = 1829991,
            score = 4,
            author = "621687",
            text = "Do you need to fly to get to that place? or what?",
            date = "2013-03-17T03:07:17-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30333#comments:id=1829991",
        },
        {
            id = 1753326,
            score = 3,
            author = "88866",
            text = "Slightly southwest of where the quest marker on the map is up in the hills at coordinates 46.95, 20.99 is the entrance to the tunnel to reach the springtail warren-mother.",
            date = "2012-10-29T17:07:48-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30333#comments:id=1753326",
        },
    },
    [30334] = {
        {
            id = 1726823,
            score = 10,
            author = "144220",
            text = "It took me a bit to figure this one out, since my server was completely overfarmed.\n\nThere are small mounds of 3-5 \"vegetables\" of differing types clustered around the small yellow huts, protected by packs of Kunzen Collectors https://www.wowhead.com/npc=59124 and Kunzen Rockflingers https://www.wowhead.com/npc=59120.\n\nI found it useful to turn off Enemy Name Plates (by default: 'v' key) so I could more easily see the vegetables.",
            date = "2012-10-01T02:18:33-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30334#comments:id=1726823",
        },
        {
            id = 1727139,
            score = 5,
            author = "Henderman",
            text = "You have to loot each vegetable separately, you won't get the whole stack with a single loot.",
            date = "2012-10-01T07:51:59-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30334#comments:id=1727139",
        },
        {
            id = 3205869,
            score = 4,
            author = "drpimento",
            text = "if you kill some hozen and die, you cant get back up there from the graveyard without rez sickness. On the other hand you have less agro so it's a tad easier to get the rest of the veg",
            date = "2020-05-11T13:13:13-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30334#comments:id=3205869",
        },
        {
            id = 1732072,
            score = 3,
            author = "amgyn",
            text = "Some of the veggies are Under the huts and are hard to see until you are next to them.",
            date = "2012-10-05T08:02:26-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30334#comments:id=1732072",
        },
        {
            id = 1735366,
            score = 3,
            author = "Beviselynt",
            text = "If you're a druid, you can loot the vegetables in Flight Form without aggroing the mobs. Just stay close, but do not land on the ground.",
            date = "2012-10-08T07:38:10-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30334#comments:id=1735366",
        },
    },
    [30335] = {
        {
            id = 1696488,
            score = 5,
            author = "GustoGA",
            text = "Mount Up!\n\nThey are on the hill that requires a flying mount;  \"to the west\" as he says.\n\nBEWARE:\n\nThere are level 90 regular hunters (350K health) that are easy picking on the sides of the mountain.  If you venture farther in toward the village you can run into packs of 3-4 roaming.  Worst yet there are a few Elite 90s that are in teams of 2.\n\nSo be careful flying in and just picking fights when you first hit 90.\n\nThere are quest up here too so mobs (alive) are hard to find.",
            date = "2012-08-05T18:07:35-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30335#comments:id=1696488",
        },
        {
            id = 1853761,
            score = 4,
            author = "Anok8",
            text = "It's easier if you kill https://www.wowhead.com/npc=59120s. Some groups will do the job :D!\nGood Luck.",
            date = "2013-05-17T06:47:25-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30335#comments:id=1853761",
        },
        {
            id = 1741100,
            score = 3,
            author = "Aisenfaire",
            text = "In that part of the map thick with kozen (http://www.wowhead.com/quest=30335#map), you'll find https://www.wowhead.com/npc=59120 in packs of 4-5.  Some of them pat, while the others squat on little cliff edges--to fling rocks, of course.  They have only 59k HP and are easily AOE'd down.  Kill 3 packs and you're done.",
            date = "2012-10-14T04:21:50-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30335#comments:id=1741100",
        },
        {
            id = 1740278,
            score = 2,
            author = "MagisterSJHC",
            text = "If you are lazy like me, goto Skyrange and visit the spot where the ritual takes place (the place with the Truffels). There look up the Ritualists.\n\nThey spawn fast, are easy to kill (low hp) and best of all, multiple people can tag them and they will count for all as a kill (because they are also targets for the quest Where it Counts).",
            date = "2012-10-13T08:07:37-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30335#comments:id=1740278",
        },
        {
            id = 1842960,
            score = 2,
            author = "Robbie",
            text = "This is the easiest and fastest way to complete this quest:\n\nThe rockflingers are the easiest to kill, they group up in bunches of 5-8 meaning you only need to nuke down three groups (which can be done in about 3 seconds as a mage) and you are done.\n\nThe best groups to kill that don't pull any other higher-health mobs are:\n\n29.87, 28.80 Group 1 - On top of a small rock, easy to AOE without pulling any other patrolling Hozen.\n30.60, 26.96 Group 2 - Same as above.\n33.16, 23.84 Group 3 - These guys are at the edge of a cliff, be careful not to fall off!\n\nTomTom Co-ords\n/way 29.87, 28.80 Group 1\n/way 30.60, 26.96 Group 2\n/way 33.16, 23.84 Group 3",
            date = "2013-04-14T06:30:18-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30335#comments:id=1842960",
        },
    },
    [30336] = {
        {
            id = 1729927,
            score = 15,
            author = "850778",
            text = "You have to put your back against the wall and try not to let him get at an angle that throws you off the mountain.",
            date = "2012-10-03T11:29:08-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30336#comments:id=1729927",
        },
        {
            id = 1818271,
            score = 10,
            author = "chimeras",
            text = "Was absolutely not prepared for this the first time I did it, and went flying off the mountain a couple of times. Tried coaxing him down the mountain...doesn't work.\nYou have to fight him on the mountain.\nStand against the mountain as mentioned earlier, but try to stay directly in front of him. He'll still throw you somewhat to the side, but not far, if you're as close as possible square in the middle of him.\n\nAnd note to self: do not stay standing there typing on wowhead, thinking he won't re-spawn for a bit. He re-spawns almost instantaneously and will un-ceremoneously boot you off the mountain while you're sharing your new found tactic. (not sure how I came to know that little pearl of wisdom xD)",
            date = "2013-02-26T00:25:16-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30336#comments:id=1818271",
        },
        {
            id = 3238528,
            score = 10,
            author = "Difdi",
            text = "As of patch 9.0 the quest for him, and the other hozen up there, is a level 15 quest.  A quest you can get long before you can fly.  Does anyone know how to get up there as a low level?  I can't find any way.",
            date = "2020-10-15T05:35:18-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30336#comments:id=3238528",
        },
        {
            id = 1797956,
            score = 7,
            author = "933624",
            text = "You can do this quest with people outside of your group. I found him at half heath with a shadow priest & a hunter, and still got credit for helping kill him.",
            date = "2013-01-13T15:12:23-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30336#comments:id=1797956",
        },
        {
            id = 1871420,
            score = 7,
            author = "Catoria",
            text = "I hate this quest with the burning passion of 1000 fiery suns.",
            date = "2013-06-27T22:38:31-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30336#comments:id=1871420",
        },
    },
    [30337] = {
        {
            id = 1720824,
            score = 367,
            author = "950428",
            text = "Some of the markers are wrong. Here are the real locations of the stolen goods\n\nStolen weapons  [30.4, 28.2]\nStolen tools  [32.7, 30.6]\nStolen beer  [32.2, 26.1]\nStolen grain  [34.9, 21.9]",
            date = "2012-09-26T21:35:43-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30337#comments:id=1720824",
        },
        {
            id = 3192082,
            score = 209,
            author = "Anaksu",
            text = "If you are trying to do this quest in BFA you will have to talk to Zidormi (81/32) and have her turn back the time to before the Assaults. Otherwise its  going to just tell you that you are in the wrong zone when placing the fireworks.",
            date = "2020-02-25T14:27:14-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30337#comments:id=3192082",
        },
        {
            id = 1729850,
            score = 127,
            author = "1036362",
            text = "If you're looking for the Pile of Grain, don't look at the quest marker. The Pile of Grain is in the northern tip of the Kunzen village, the the right of that little cave on your map (on the northern border).",
            date = "2012-10-03T10:13:21-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30337#comments:id=1729850",
        },
        {
