            text = "/way 30.4, 28.2 Stolen Weapons\n/way 32.7, 30.6 Stolen tools\n/way 32.2, 26.1 Stolen beer\n/way 34.9, 21.9 Stolen grain",
            date = "2012-10-05T04:20:56-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30337#comments:id=1731915",
        },
        {
            id = 1723554,
