    [30341] = {
        {
            id = 1733862,
            score = 13,
            author = "Chaix",
            text = "these guys will appear on your minimap if you're a hunter with track hidden active",
            date = "2012-10-06T22:00:27-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30341#comments:id=1733862",
        },
        {
            id = 1725002,
            score = 4,
            author = "Afzal",
            text = "You can use your https://www.wowhead.com/item=89366 while mounted. I found the easiest way to complete this quest to fly around the lake and spam https://www.wowhead.com/item=89366 whenever the cooldown was off.",
            date = "2012-09-29T18:24:19-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30341#comments:id=1725002",
        },
        {
            id = 1742368,
            score = 4,
