    [30346] = {
        {
            id = 1935736,
            score = 7,
            author = "Thumdrive",
            text = "The easy way - In the Deep Wild, follow the path to 50.0 / 32.5 and face east towards the rock hill. Facing east up the hill you will see a cleft (a sort of path in and up the rock hill; you'll see a red shaft of light and a brown block wall up at the top.) Go up the hill, head right a few feet and the Pools of Youth are right there on your left. The chained water sprite is there as are 4 statue temple dogs. Pass them all for now and continue east and cross over a small foot bridge and head to the right after crossing. You will see a red floor rune which is too big to jump over; walking on it will reduce your health a bit but ya gotta cross. As soon as you cross the rune, you next victim is at your left; Dojani Dominator. It helps to clear the floor of the 2 or 3 marching mobs and then kill the Dominator. He'll drop a document which you take back over the little foot bridge to the Water Spirit. Immediately after you deliver the document, all 4 temple dogs will attack you but you and your \"companion\" \"Kang Bramblestaff\" who has been with you all this time, will pretty easily kill the 4 dogs. The water sprite is freed and leaves behind dark blue / black puddles in the pool. Get some and that's the quest!",
            date = "2014-01-18T20:12:09-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30346#comments:id=1935736",
        },
        {
            id = 1755580,
            score = 5,
            author = "Vonbam",
            text = "I did not receive this quest after handing in 'The Lost Dynasty' quest.  It did not become available until I handed in another quest at The Incursion.\n\nI handed in 'Squirmy Delight' and this quest and several others became available.  So either Squirmy Delight is a prerequisite too or you need at least 2 quests handed in from The Incursion quest givers to qualify for the second tier of quests.",
            date = "2012-11-02T11:04:35-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30346#comments:id=1755580",
        },
        {
            id = 1857374,
            score = 1,
            author = "1122665",
            text = "I found it difficult to get to the dominator guy (as a lvl 87) i ended up dying near the entrance (because of an elite) and Resurrected in the top level right above my body to easily get to him. but i found out later there was an easier way at 50:33 there is a back entrance where you dont have to fight anything to get to the guy and you pass thru the pool of youth for the next quest!\nhope this helps :)",
            date = "2013-05-24T20:00:34-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30346#comments:id=1857374",
        },
        {
            id = 5376184,
