        {
            id = 1736323,
            score = 20,
            author = "1042979",
            text = "hey just try to kill tigers in smaller area on north(aroud 71.22). there is realy good droprate almost any tiger drop it and if you find two ho did not third one drop two pieces of blood. before i find that out i kill about ten tigers and got one piece of blood... good hunt.",
            date = "2012-10-09T04:32:38-05:00",
