        {
            id = 1792489,
            score = 13,
            author = "998027",
            text = "Astoundingly, the Pandaria Wildlife Foundation found in a recent survey that 3 out of 4 Tigers have no blood.\n\nTo show how low their drop rates for the blood vials are, I got two https://www.wowhead.com/item=81212, which are 5% drops, and a https://www.wowhead.com/item=82030, a .2% drop, before completing the quest.\n\nPretty crazy, huh?",
            date = "2013-01-04T13:38:47-06:00",
