    [30355] = {
        {
            id = 2218683,
            score = 3,
            author = "AngelaO",
            text = "This quest is actually given at the Sentinel Basecamp; not The Incursion. Kang Bramblestaff is located at 25.15 34.55 at the Sentinel Basecamp. However, I think you have to do the quest chain(s) to clear the incursion first.\nThere is no options to choose your rewards for these quests. It looks like you'll be given the reward appropriate for your class.",
            date = "2015-07-22T17:33:06-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30355#comments:id=2218683",
        },
        {
            id = 2534659,
            score = 3,
            author = "ZiLaK",
            text = "Depending on how you do quests in this area of MoP this quest will be phased out.\n\nI just got help from a GM about this, I was phased out from the quest giver.\nOnly had http://www.wowdb.com/quests/30462-into-the-wilds Quest to do, but even the NPC to turn that quest in to was not available for me at all.\nI had done all other quests in this area that I could find.\n\nThe GM made some magic after a ticked and pushed the into the wilds quest as complete and possible something else as well and the npc's popped back up.\nAlso asked if I had started to quest partways through the area before I switched faction (very likely, don't remember)\nBut it can have something to do with it as well.\nAnyways a ticket to GM is recommended if you got phased out like me and unable to complete the achievement.\n\nAnd now..... World Domination!",
            date = "2017-11-13T11:24:01-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30355#comments:id=2534659",
        },
        {
            id = 1991098,
            score = 2,
            author = "461030",
            text = "As of this moment I am unable to complete this quest, along with a few others in this zone due to phasing bugs.\n\nA ticket was no help as I was told that \"this is a problem on the developer side\". No Loremaster for me.",
            date = "2014-08-12T15:33:14-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30355#comments:id=1991098",
        },
        {
            id = 1673040,
            score = 1,
            author = "231785",
            text = "Various artifacts found scattered across the ground in the Ruins of Korja.",
            date = "2012-06-03T09:58:45-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30355#comments:id=1673040",
        },
    },
    [30356] = {
        {
            id = 1925384,
            score = 2,
            author = "taintedbunny",
            text = "The next steps are actually  The Mantid (http://www.wowhead.com/quest=30361) and The Stoneplow Convoy (http://www.wowhead.com/quest=30357). Only after completing these, will you then be offered The Lord Reclaimer (http://www.wowhead.com/quest=30359).",
            date = "2013-12-12T05:38:44-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30356#comments:id=1925384",
        },
    },
    [30357] = {
        {
            id = 1894149,
            score = 22,
            author = "Nicolu",
            text = "Okay so, I came here to find the cloak that this quest gives, since it's a one of a kind pattern/color. Once I got here I was beyond confused so here's a little step by step for anyone else who needs to do it.\n\n1.Fly to the druids in the bubble, 67,32 ish.\n2. Do every quest there, including the other NPCs (Only like 4 or 5 total)\n3. Get the dead Nelf's scout paperwork, and take it to 24,34 camp.\n4. Do the quests there until you get Mantid!\n5. Don't have to finish Mantid, but pick it up and then Lorekeeper Vaeldrin will be at the stoneplow guys at about 15,37.",
            date = "2013-09-09T12:06:37-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30357#comments:id=1894149",
        },
        {
            id = 1792700,
            score = 5,
            author = "iffy",
            text = "This quest is received and completed where the dots are on the map, not where the quest pickup and completion markers are.  The Lorekeeper and his party move to the area with the dots, and you should find them when you're doing the quest \"The Mantid\" ([quest=30361 domain=www]).",
            date = "2013-01-04T21:34:30-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30357#comments:id=1792700",
        },
        {
            id = 1809378,
            score = 3,
            author = "Mondoblasto",
            text = "As far as I can tell, these cloaks are the only ones in this pattern that are green.",
            date = "2013-02-05T04:23:39-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30357#comments:id=1809378",
        },
        {
            id = 1901248,
            score = 1,
            author = "JohnPWest",
            text = "One thing I was surprised by. I pulled the flying Mantid (same sort as for \"The Mantid\") and it was joined by 3 \"Mantid Vanguards\". Ouch.. Mirror Image, Polymorph, blast away, healing potion..\n\nSecond time I pulled a guarding Mantid, same deal. I did my best Mage imitation of a Rogue after that, and snuck in while the guarding Mantid wasn't watching to heal the Envoy.\n\nBarudain the sneaky",
            date = "2013-09-21T20:01:16-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30357#comments:id=1901248",
        },
        {
            id = 1853836,
            score = -4,
            author = "Anok8",
            text = "By definition a convoy is a small or medium group of people or units that may escort something...\nWell... by the number of https://www.wowhead.com/npc=58955 I've seen in the forest.. this hasn't been a convoy at all... This looked like a whole legion! =))\nAfter I revived them, they were like newborns... running in all possible directions full of energy, without looking where they were heading... I guess that's why they died in such numbers...",
            date = "2013-05-17T13:42:55-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30357#comments:id=1853836",
        },
    },
    [30359] = {
        {
            id = 1721595,
            score = 4,
            author = "Rikeus",
