    [30360] = {
        {
            id = 1755057,
            score = 24,
            author = "Zephymetheus",
            text = "Since this quest is pretty elusive, I'd like to share the (presumably cumulative) circumstances under which I was able to obtain it:\n\n- Training and Discipline (http://www.wowhead.com/quest=29990#) was completed in Valley of the Four Winds.\n- In the House of the Red Crane (http://www.wowhead.com/quest=30273) was completed in Krasarang Wilds.\n- The Waters of Youth (http://www.wowhead.com/quest=30445) was completed in Krasarang Wilds.\n- The Mantid invasion event has commenced, but no quests (such as The Swarm Begins (http://www.wowhead.com/quest=30622)) were picked up.\n\nIn the case above, I was able to pick up either Hope Springs Eternal (http://www.wowhead.com/quest=30376) or Warn Stoneplow (http://www.wowhead.com/quest=30360) (these are mutually exclusive). I chose the former, but after handing it in, Warn Stoneplow (http://www.wowhead.com/quest=30360) was no longer available. Presumably it's the case vice versa as well.",
            date = "2012-11-01T14:44:12-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30360#comments:id=1755057",
        },
        {
            id = 1732493,
            score = 12,
            author = "Karadine",
            text = "The following quests lead to the https://www.wowhead.com/achievement=7502 \"big finale\" that wraps up the storylines of Krasarang Wilds and Valley of the Four Winds. You will only be able to complete one of these:\n\nhttps://www.wowhead.com/quest=30376\nhttps://www.wowhead.com/quest=30360 (Alliance) / https://www.wowhead.com/quest=30241 (Horde)",
            date = "2012-10-05T16:34:50-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30360#comments:id=1732493",
        },
        {
            id = 1921040,
            score = 9,
            author = "yoshimario40",
            text = "Instead of looking at what quests to complete, it might be more useful to look at the people you help instead. You need to help\n\nhttps://www.wowhead.com/npc=56312 and the farmers at Thunderfoot Fields\nhttps://www.wowhead.com/npc=56133, https://www.wowhead.com/npc=56138, https://www.wowhead.com/npc=56474 and their journey across Valley of the Four Winds\nhttps://www.wowhead.com/npc=56113 and his vision of the Vale\nhttps://www.wowhead.com/npc=56111 and her search for the Hidden Master\nhttps://www.wowhead.com/npc=56115, https://www.wowhead.com/npc=58410 and the despair-ridden Zhu's Watch\nhttps://www.wowhead.com/npc=56112 and his efforts to help the Horde/Alliance\n(Alliance)https://www.wowhead.com/npc=58745, https://www.wowhead.com/npc=58821 or (Horde)https://www.wowhead.com/npc=58607, https://www.wowhead.com/npc=58114 and the pools of youth\nhttps://www.wowhead.com/npc=59138 and the battle to take back the Temple of the Red Crane\n\nThis is because the fight against the mantids has everyone you helped coming back to help you fight back.\n\nBy the time you get this quest, you'll have almost done all of https://www.wowhead.com/achievement=6535 and https://www.wowhead.com/achievement=6301 except for the out of the way quests at Nesingwary's Safari and Nayeli Lagoon.",
            date = "2013-11-25T00:27:40-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30360#comments:id=1921040",
        },
        {
            id = 1731554,
            score = 8,
            author = "517661",
            text = "If you have problems picking up the quest, just pick this quest up instead: Stoneplow Thirsts (http://www.wowhead.com/quest=30117/stoneplow-thirsts#.)\n\nIt has the same effect and will let you complete the quest chain.",
            date = "2012-10-04T18:41:33-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30360#comments:id=1731554",
        },
        {
            id = 1744199,
            score = 8,
            author = "cechjakpoleno",
            text = "This quest did not show up for me until I did [quest=30273 domain=www]",
            date = "2012-10-17T16:05:42-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30360#comments:id=1744199",
        },
    },
