            sourceUrl = "https://www.wowhead.com/quest=30406#comments:id=1757419",
        },
        {
            id = 1852523,
            score = 0,
            author = "Xaphireftw",
            text = "If you're here to look for a macro for quest turnins to gain reputation with this faction, use the following after targeting the NPC:\n\n/run SelectGossipAvailableQuest(1);CompleteQuest();GetQuestReward()\n\nNote:\nIf you have different items, and you want (for example) to turn in the third quest on the list, make the \"1\" a \"3\".\n\nExample:\n/run SelectGossipAvailableQuest(3);CompleteQuest();GetQuestReward()",
            date = "2013-05-12T15:24:04-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30406#comments:id=1852523",
        },
    },
