        {
            id = 1811092,
            score = 1,
            author = "1089495",
            text = "Part of the quest is to find Zhu's Watch Courier.  You must \"loot\" the courier and then talk to Koro Mistwalker.  The courier lays just a few steps away from Koro at 43,43 and is identified when one highlights the body as the Incursion Sentinel.  It is hard to tell from the instructions where the courier/sentinel is so hope this helps.",
            date = "2013-02-09T01:37:09-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30461#comments:id=1811092",
