    [30462] = {
        {
            id = 1815353,
            score = 32,
            author = "1084007",
            text = "If you're looking for the achivement https://www.wowhead.com/achievement=6926 - This quest line will lead you to the https://www.wowhead.com/npc=59651.\n\nThis quest line takes around 1->1½ hour. Depends on the different drops.",
