            text = "I can't complete this quest after Faction Changing. Koro isn't showing up for me so I'm stuck with this on my questlog. :/",
            date = "2024-09-09T01:00:46-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30462#comments:id=5951047",
        },
    },
