    [30465] = {
        {
            id = 1751258,
            score = 10,
            author = "620618",
            text = "No one's commented yet so I will....\n\nGetting to this quest involves a long chain starting at Zhu's Watch, and questing through to The Incursion.  After you've turned in Threat from Dojan, Lyalia offers you this one which starts another chain that should lead back to Stoneplow in Valley of 4 Winds, ending with the wall getting smashed.  I went through Valley of 4 Winds with my second toon and couldn't figure out why I hadn't seen the wall breakthrough even though a ride through 4 Winds didn't turn up any more quests to do.  I didn't realize how far I had gotten in Krasarang before being sent back up to 4 Winds.\n\nsorry about no links----don't know how to do em and just wanted to get this info up.",
            date = "2012-10-26T21:14:34-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30465#comments:id=1751258",
        },
        {
            id = 3308782,
            score = 1,
