            text = "About https://www.wowhead.com/npc=59273, when she gives you https://www.wowhead.com/quest=30468:\n\n............. Oh yeah?\nThen what're all those round, black circles around every panda's eyes?\nWait... am I the only one who can see them?\n*le gasp*",
            date = "2022-06-11T23:45:27-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30468#comments:id=5383735",
        },
