    [30469] = {
        {
            id = 1719569,
            score = 14,
            author = "899879",
            text = "If you're having trouble finding them they are a green box. It doesn't sparkle well so hover over everything and look for the cog.",
            date = "2012-09-26T03:35:34-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30469#comments:id=1719569",
