    [30475] = {
        {
            id = 1721849,
            score = 58,
            author = "Izichial",
            text = "The birds that drop the quest item you need will still be highlighted after you pick it up because what you'll actually need to do is to bring the item to another npc (Kol Ironpaw, the Master of the Grill) and have him cook it for Fung before it turns completed, as stated in the quest description.\n\nSo if you're farming forever for the item like I did, chances are you just didn't notice it in your bags.",
            date = "2012-09-27T15:54:33-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30475#comments:id=1721849",
        },
        {
            id = 1693956,
            score = 18,
            author = "Necromorta",
            text = "Don't bother yourself with the brown Plainshawk (http://mop.wowhead.com/npc=58910) killing. The white Monstrous Plainshawk (http://mop.wowhead.com/npc=59641) drops the quest item. You will find it around The Heartland.\n\n*Wrote in beta. In beta Plainshawk groups flew around Halfhill, not Monstrous ones. It was a common mistake to kill it furiously, 'til we realized, the white one is the quest npc. However this could be tricky today too.*",
            date = "2012-07-30T08:29:09-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30475#comments:id=1693956",
        },
