    [30482] = {
        {
            id = 1760557,
            score = 6,
            author = "805283",
            text = "Very tough for a feral Druid - or any melee class. 'Skull Bash' does not appear to be an effective interrupt, and movement to avoid 'Spirit Cage' can put you in the water where it's hard to navigate due to the lily pads. Attacking from underwater does not seem to work -- not sure why not.\n\nBring a friend. Tag 'Shadowmaster' first, then let your friend jump in to help. Best luck.",
            date = "2012-11-10T22:33:00-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30482#comments:id=1760557",
        },
        {
            id = 1776973,
            score = 6,
            author = "LionsMike",
            text = "There has to be a lot more than that. I have a warrior an I cannot  in any way shape manner or form bring him down by much more than 125K before he kills me. So if you know a way to  give me 15 times as muck kill power it will still not be enough.\n\nI see messages indicating that I should move but any movement at all assures death because once I leave the lilly pad and enter the water all I can do is wait for enough rage to trip my Thundert Clap I cannot tell where I am with respects to him get messages like the target must be in front of you, you cannot do that, and all kinds of others\n\nIs there a way to  bing him onto the shore where a warrior  can fight him.\n\nAs it is now if it was an important part of a quest chain it would be a game breaker.\n\nSeveral hours  lots of need to repair full yellow/reds and still never getting  much better than about 5 to 10% I resorted to waiting to see a group attack him and I got in one charge which wa enough to qualify for the kill. I picked up my beads and turnedthe quest in.  THAT JUST SEEMS WRONG",
            date = "2012-12-07T01:26:07-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30482#comments:id=1776973",
        },
        {
            id = 1753562,
            score = 5,
            author = "f07gano",
            text = "https://www.wowhead.com/spell=78675 is effective against Shadowmaster Sydow, and it makes the fight go a bit faster.",
            date = "2012-10-30T03:00:11-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30482#comments:id=1753562",
        },
        {
            id = 1736297,
            score = 4,
            author = "ruxp1n",
            text = "Move out of the Spirit Cage (http://www.wowhead.com/spell=126466) when cast on ground underneath you.  Just keep moving until he's down.  Super easy to kill over time.\n\nAs for the other comment, I was able to turn in the quest no problem as of date of this post.",
            date = "2012-10-09T03:34:21-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30482#comments:id=1736297",
        },
