    [30485] = {
        {
            id = 1718714,
            score = 38,
            author = "111755",
            text = "The quest is given by Lorewalker Cho at the Grookin Hill in The Jade Forest (28.2, 46.7).\nAfter accepting the quest talk to his pet Mishi next to him to reach Serpent's Overlook.\nWARNING: You can't get there on foot at this point.",
            date = "2012-09-25T12:28:26-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30485#comments:id=1718714",
        },
        {
            id = 1722331,
            score = 27,
            author = "SexyBoBo",
            text = "Be sure to pick up the flight path from  https://www.wowhead.com/npc=64310 while you are at serpent's overlook if you forget to you wont be able to get back until you hit 90 and can fly.",
            date = "2012-09-28T00:18:10-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30485#comments:id=1722331",
        },
        {
            id = 1671909,
            score = 14,
            author = "231785",
            text = "After accepting the quest DON'T RUN THERE. Talk to the serpent next to him for a flight.",
            date = "2012-05-31T04:07:15-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30485#comments:id=1671909",
        },
        {
            id = 3278531,
            score = 8,
            author = "cxarli",
            text = "If you wish to keep [zone=5785] as green and beautiful as it was when you arrived. DO NOT TURN IN THIS QUEST! Instead, after the cinematic concludes, abandon the quest.  If you are going for https://www.wowhead.com/achievement=6534, pick one character to complete it, so that your other characters can keep it unblemished. After you abandon the quest, all the destruction will vanish and the zone will look like it did when you first arrived in Pandaria.  You can then travel by road or flight path to Pang's Stead in [zone=5805] to meet up with Chen Stormstout and begin questing there.",
            date = "2020-12-22T00:44:11-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30485#comments:id=3278531",
        },
        {
            id = 1725177,
            score = 6,
            author = "OldWolf2",
            text = "For me, as Horde, this quest did not unlock until the first 7 objectives of Upjade Complete! were all done. (Temple of the Jade Serpent being the 7th). It then sends you back to Grookin for a couple of pre-quests from Nazgrim, and then this quest comes available.",
            date = "2012-09-29T21:02:48-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30485#comments:id=1725177",
        },
    },
