        {
            id = 1994504,
            score = 1,
            author = "Discoverer",
            text = "The best, or shall I say the fastest way to smack some https://www.wowhead.com/npc=59718 is to find those who mounted a yak (they will be running all over the field with a https://www.wowhead.com/spell=5782 spell animation above them). When you pull a Despoiler it will take time for him to get off his yak and strike you back. That's when you kick in some chunky burst damage with no retaliation ;) Good luck",
            date = "2014-08-21T08:55:41-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30490#comments:id=1994504",
        },
    },
