    [30495] = {
        {
            id = 1726668,
            score = 15,
            author = "jtbalogh",
            text = "You can only see the cool pack while in the area and nowhere else.",
            date = "2012-09-30T23:25:57-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30495#comments:id=1726668",
        },
        {
            id = 1661180,
            score = 8,
            author = "Bethenal",
            text = "Surveyor Sawa and Kitemaster Shoku are around the base of the statue, Historian Dinh is to the southeast a little bit, and you talk to Kitemaster Shoku to get a lift to the top of the statue to deliver to Taskmaster Emi.\n\n[Beta Build 15650]",
            date = "2012-05-01T05:56:06-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30495#comments:id=1661180",
        },
        {
            id = 1723725,
            score = 4,
            author = "769227",
            text = "Task master Emi  is at the top of the statue. You can get a ride to the top from Kitemaster Shoku who is at 48.2/ 60.0",
            date = "2012-09-28T23:25:49-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30495#comments:id=1723725",
        },
        {
            id = 1851360,
            score = 3,
            author = "grodon909",
            text = "This is one of the quests in the Jade Serpent questline of The Jade Forest. I'm about to mention some things about the storyline, so I'll preface by saying SPOILER ALERT.\n\nThis is a very simple quest, right? Just deliver stuff to NPCs around you, no tricks or anything. With some thought, it becomes plainly obvious that the point of this quest was to get you to look at the Jade serpent, and give you a sense that people have been working on it. Blizz probably worked hard on this model and wanted to show it and the surrounding area to players, and give them a sense of awe (at least, in their first playthrough).\n\nAnother thing is that the quest is called Love's Labor. This might be a subtle nod to Shakespere's Love's Labour's Lost, in that, as you know and your character will soon find out, this labor is lost due to the strife caused by our factions. END SPOILERS",
            date = "2013-05-08T22:14:33-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30495#comments:id=1851360",
        },
        {
            id = 1920654,
            score = 2,
            author = "945326",
            text = "You can get a ride to the top from Kitemaster Shoku.\n\nAnd you get a ride back down from Kitemaster Inga at the top of the statue.",
            date = "2013-11-23T12:36:43-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30495#comments:id=1920654",
        },
    },
