    [30499] = {
        {
            id = 1720571,
            score = 7,
            author = "880445",
            text = "Ginsa is also the regular flight master - look for the flight icon underneath the temple of the jade serpent on your map.\n\nThrew me off a little as I was expecting to see a separate NPC with a kite in the temple just for me!",
            date = "2012-09-26T17:17:54-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30499#comments:id=1720571",
        },
        {
            id = 1839569,
            score = 3,
            author = "509976",
            text = "Your bag will contain a Horde Missive (\"A hastily written and violently sealed letter\"):\n\n\"Enough frolicking about, Itzakiri!\n\nHave you forgotten our directive?\n\nFinal preparations must be made for our offensive, and I need you here.\n\nPut an end to whatever distractions you're engaged in and return to Grookin' Hill at once.\n\n-General Nazgrim\"\n\n... which amuses the hell out of me as I imagine big orc men like Nazgrim frolicking in the park.",
            date = "2013-04-05T23:08:46-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30499#comments:id=1839569",
        },
        {
            id = 1962509,
            score = 2,
            author = "SoooWhoCares",
            text = "Currently there's something wrong while we're about to turn in the quest:\nThe quest preview window (the thing attached to the questlog that shows quest-relevant NPCs) will show General Nazgrim, wearing Sergeant Gorrok's armor.",
            date = "2014-05-01T17:01:33-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30499#comments:id=1962509",
        },
        {
            id = 5667309,
            score = 1,
            author = "FluffiestSpore",
            text = "-You may want to look at the quest board in \" The Honeydew Village\" in The Jade Forest to start the Jade Forest questline, that's when you first land in Pandaria. I'm sure that leads to this quest we are all looking at. Will update when I find out!\n- go here https://www.wowhead.com/quest-completion-tracker to track what quests you have done\n-I am confirming that this leads you to \"Get Back Here\"",
            date = "2023-08-15T21:20:25-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30499#comments:id=5667309",
        },
    },
    [30500] = {
        {
            id = 1726143,
            score = 8,
            author = "Ascened",
            text = "You need to pick up Celestial Jade to weaken the Sha Remnants.",
            date = "2012-09-30T13:54:51-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30500#comments:id=1726143",
        },
        {
            id = 1746692,
            score = 6,
            author = "athika",
            text = "The https://www.wowhead.com/object=210921 is everywhere on the ground and you can pick them up to shrink the elite to non-elite mobs. Much easier to kill them. ^^",
            date = "2012-10-20T19:05:04-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30500#comments:id=1746692",
        },
        {
            id = 1727120,
            score = 5,
            author = "Soeroah",
            text = "Be sure to look up at the sky while doing these quests.",
            date = "2012-10-01T07:37:48-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30500#comments:id=1727120",
        },
    },
    [30502] = {
        {
            id = 1671916,
            score = 87,
            author = "231785",
            text = "Pick up https://www.wowhead.com/object=210921 scattered across the inner area of Serpent's Heart. Then use each one to weaken the Sha Remnant elites.",
            date = "2012-05-31T04:38:22-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30502#comments:id=1671916",
        },
        {
            id = 1830419,
            score = 26,
            author = "481610",
            text = "If you're like me and never bother to read quests, you're gonna have a bad time here.",
            date = "2013-03-17T22:26:51-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30502#comments:id=1830419",
        },
        {
            id = 1720845,
            score = 9,
            author = "Sixsixty",
            text = "The Sha Remnants are mostly outside the little island bit, Where you get the quest, if you cross the boarder, and follow the edge around, you'll be done in no time.\n\nDon't forget to pick up the little pieces of Jade!",
            date = "2012-09-26T21:53:40-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30502#comments:id=1720845",
        },
        {
            id = 1718752,
            score = 3,
            author = "951274",
            text = "For some reason it is possible to miss with the quest item. It shrinks the Sha Remnant, but doesn't do the damage if it says miss. :)",
            date = "2012-09-25T13:02:43-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30502#comments:id=1718752",
        },
        {
            id = 1727263,
            score = 3,
            author = "lionsofmercy",
            text = "I recommend completing the other quests before finishing this one. Unlike some other mobs of this type, they will remain aggressive when you're out of jade. You can outrun them; unless you're big on the sense of accomplishment of soloing an 86 elite, I wouldn't bother engaging them, because they still only give a few hundred XP.",
            date = "2012-10-01T09:46:14-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30502#comments:id=1727263",
        },
    },
    [30504] = {
        {
            id = 1695251,
            score = 9,
            author = "rambler",
            text = "Turn on friendly name plates.",
            date = "2012-08-02T12:13:56-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30504#comments:id=1695251",
        },
        {
            id = 1672087,
            score = 7,
            author = "Nakae",
            text = "When you accept and highlight this quest, grey-blue dots appear on the mini-map.  Stand close to one and click the fireworks.  The subjects of the rescue don't show up until after you've rescued them, sadly, so if you don't know this you'll run around like a headless chicken for a while.",
            date = "2012-05-31T17:58:44-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30504#comments:id=1672087",
        },
        {
            id = 1733416,
            score = 7,
            author = "summermoo",
            text = "Coordinates for each NPC below:\nGeneral Nazgrim - 48:61\nShademaster Kiryn - 47:62\nShokia - 46:60\nRivett Clutchpop - 47:59",
            date = "2012-10-06T12:58:32-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30504#comments:id=1733416",
        },
        {
            id = 1674775,
            score = 2,
            author = "Alexsatia",
            text = "You can find them easily by jumping on a mount and running around clicking on the firework.",
            date = "2012-06-08T23:51:22-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30504#comments:id=1674775",
        },
        {
            id = 1695103,
            score = 2,
            author = "920573",
            text = "I was running around spamming the fireworks near the large structures w/o finding a single one. I read on forums that the quest npc's are bugged and that logging out/in would refresh the name tags. That didn't work and so I mounted up ran through all angry frustrated spamming the fireworks, picked up a bunch of elites and ended up dying. When I rezzed I could see all the quest npc name tags in green and sparkling. Hope it works for everyone too!",
            date = "2012-08-02T04:01:08-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30504#comments:id=1695103",
        },
    },
    [30506] = {
        {
            id = 2433493,
            score = 15,
            author = "thisguyyouknow",
            text = "Before you can access this quest you must first complete 3 prequests\n\nMayor Bramblestaff (http://www.wowhead.com/npc=59073/mayor-bramblestaff#starts)\nstarts\nCall Out Their Leader (http://www.wowhead.com/quest=30457/call-out-their-leader)\n\nApothecary Cheng  (http://www.wowhead.com/npc=59077/apothecary-cheng#starts)\nstarts\nHit Medicine (http://www.wowhead.com/quest=30460/hit-medicine)\n\nCommander Hsieh (http://www.wowhead.com/npc=59076/commander-hsieh#starts)\nstarts\nAll of the Arrows (http://www.wowhead.com/quest=30459/all-of-the-arrows)\n\nThen all of these quest givers start\nAdmiral Taylor has Awakened (http://www.wowhead.com/quest=30507/admiral-taylor-has-awakened#comments)\nAdmiral Taylor has Awakened (http://www.wowhead.com/quest=30508/admiral-taylor-has-awakened#comments)\nAdmiral Taylor has Awakened (http://www.wowhead.com/quest=30506/admiral-taylor-has-awakened#comments)\nPick anyone it does not matter.",
            date = "2016-10-24T09:55:24-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30506#comments:id=2433493",
        },
        {
            id = 1720353,
            score = 11,
            author = "Whiterock",
            text = "The Road to Kun-lai Quest Tree From Whiterock\n[pre][ins]#[/ins])Robbing Robbers of Robbers (http://www.wowhead.com/quest=31286) [ins]#[/ins])Educating Saurok (http://www.wowhead.com/quest=31287) [ins]#[/ins])The Spring Drifter (http://www.wowhead.com/quest=31285)(The Veiled Stair)\n\n[ins]#[/ins])The Road to Kun-Lai (http://www.wowhead.com/quest=31254){H} (http://www.wowhead.com/quest=31255)(Multiple zones)\n\n[ins]+[/ins])Hit Medicine (http://www.wowhead.com/quest=30460) [ins]+[/ins])All of the Arrows (http://www.wowhead.com/quest=30459) [ins]+[/ins])Call Out Their Leader (http://www.wowhead.com/quest=30457)\n ├─────┬────────┴───────────────────┘         ||\n ||     ||                                    Turnabout (http://www.wowhead.com/quest=30670)*\n || The Defense of Shado-Pan Fallback (http://www.wowhead.com/quest=30665)*\n ||\n ├──────────────────────────────────────┐\na)Admiral Taylor has Awakened (http://www.wowhead.com/quest=30506)(A,v2 (http://www.wowhead.com/quest=30507),v3 (http://www.wowhead.com/quest=30508)) a)General Nazgrim has Awakened (http://www.wowhead.com/quest=30509)(H,v2 (http://www.wowhead.com/quest=30510),v3 (http://www.wowhead.com/quest=30511))\nb)Westwind Rest (http://www.wowhead.com/quest=30512)(A)                     b)Eastwind Rest (http://www.wowhead.com/quest=30513)(H)\n ||                   ┌──────────────────┘\nb)Challenge Accepted (http://www.wowhead.com/quest=30514){H} (http://www.wowhead.com/quest=30515)\n || ||                 └───────────┬>c)Blue Dwarf Needs Food Badly (http://www.wowhead.com/quest=30583)(A)\n || ├>c)Round 'Em Up (http://www.wowhead.com/quest=30575){H} (http://www.wowhead.com/quest=31256)           ├>c)Best Meals Anywhere! (http://www.wowhead.com/quest=31251)(H)\n || └>d)Profiting off of the Past (http://www.wowhead.com/quest=30595) └>d)Deanimate the Reanimated (http://www.wowhead.com/quest=30593){H} (http://www.wowhead.com/quest=30594)\n ||\n ├───────────────────────────┐\nd)Mogu? Oh No-gu! (http://www.wowhead.com/quest=30619){H} (http://www.wowhead.com/quest=30620)    e)Trouble on the Farmstead (http://www.wowhead.com/quest=30569){H} (http://www.wowhead.com/quest=30570)\n ||                        /     \\\n ||       e)Farmhand Freedom (http://www.wowhead.com/quest=30571)     e)... and the Pot, Too!  (http://www.wowhead.com/quest=30581)\n ||                       └─┬───┬─┘\n || e)Back to Westwind Rest (http://www.wowhead.com/quest=31252)(A) e)Back to Eastwind Rest (http://www.wowhead.com/quest=31253)(H)\n ├─────────────────────────┴───┴─┬───────────────────┐\n ||                               ||                   ||\nf)In Tents Channeling (http://www.wowhead.com/quest=30652){H} (http://www.wowhead.com/quest=30657)        f)Barrels of Fun (http://www.wowhead.com/quest=30651){H} (http://www.wowhead.com/quest=30656) f)Pandaren Prisoners (http://www.wowhead.com/quest=30650){H} (http://www.wowhead.com/quest=30655)\nf)The Ordo Warbringer (http://www.wowhead.com/quest=30660){A2 (http://www.wowhead.com/quest=30662),H1 (http://www.wowhead.com/quest=30661),H2 (http://www.wowhead.com/quest=30663)}  ||                   ||\n ||                           └─┬─┴─────────────────┬─┘\nMuskpaw Ranch (http://www.wowhead.com/quest=31456){H} (http://www.wowhead.com/quest=31457)*              ├>The Shado-Pan (http://www.wowhead.com/quest=31455){H} (http://www.wowhead.com/quest=31453)* ├>The Missing Merchant (http://www.wowhead.com/quest=31452){H} (http://www.wowhead.com/quest=31451)*\n                               └>Beyond the Wall (http://www.wowhead.com/quest=31695)*  └>Cho's Missive (http://www.wowhead.com/quest=31460){H} (http://www.wowhead.com/quest=31459)*\nLegend:\n+ means Can start anytime, prequests not needed.\n# means Other Zones\n(A)/(H) means Alliance/Horde only.\n{H} means Quest Have Horde Variant, click {H} for it.\n* means another Quest Tree.[/pre]\nAdditionall info:\n\nYes, Shado-pan questline have such weird prequests :D\nAwakened quests have 3 version of quests each starting from NPC that gave you previous quests.\nOrdo Warbringer have quest that starts via pop-up after Channelers and backup from Taylor/Nazgrim if you abandon first.",
            date = "2012-09-26T15:12:34-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30506#comments:id=1720353",
        },
        {
            id = 5383073,
            score = 1,
            author = "DaemoniKira",
            text = "When you walk into the building where the Alliance and Horde groups are for https://www.wowhead.com/quest=30506, you will start hearing and seeing various short outbursts from both https://www.wowhead.com/npc=59441 and https://www.wowhead.com/npc=59442, every 1-30 seconds or so (sometimes they get really chatty...). They don't seem to really be connected to each other, like a conversation or anything. It's more just one-sentence taunts and machismo BS \"Alliance sux\" \"no Horde sux\".\nSometimes https://www.wowhead.com/npc=59442 gets overzealous and says his quips back-to-back-to-back, with https://www.wowhead.com/npc=59441 occasionally speaking over him. Even more amusing is when https://www.wowhead.com/npc=59442 says the same exact quip back-to-back, almost always interrupting himself in the process lol. He's wont to do that...\n\nHere's most, if not all, of what they say:\n\nhttps://www.wowhead.com/npc=59441:\nThese people shall not be enslaved by your cruel Horde. I will not allow it!\nLook at the peaceful, kind people of this land. They were born to belong to the Alliance.\nWe must gain a foothold here... away from these Horde dogs.\nHow many innocents have died at your hand, orc? Your Horde has no honor...\nOnly three Horde rats left. Shouldn't be a problem to finish you off once and for all.\nI'll wait until you're healed to finish you, Nazgrim. Let it not be said that the Alliance has no honor.\nI grow weary of these Horde cowards. There must be someplace else in this village to rest.\nKun-Lai Summit is where you're going to die, orc. I'm going to bury you.\n\nhttps://www.wowhead.com/npc=59442:\nMy axe will soon feast upon your blood, human.\nYour kind shall never build a foothold here. This is destined to be Horde land.\nI hope you have the courage to die bravely, human. I'm in the mood for a good fight.\nThese pandaren are a wise enough people. Sooner or later, they will side with the Horde.\nGoblin, find my axe! I'll separate this fool human's head from his neck! *grunts*\nYou... you escaped me in Vash'jir. You won't be so lucky here.\nSoon, you and your Alliance will only be found in Azeroth's history books.\nAs soon as I... can get up, I'm going to crush you!\n\nWell... https://www.wowhead.com/npc=59442 ends up as https://www.wowhead.com/npc=71515, and https://www.wowhead.com/npc=59441 ends up as https://www.wowhead.com/npc=82375...\nSo that's even.\nExcept then https://www.wowhead.com/npc=71515 ends up as https://www.wowhead.com/npc=171791, and https://www.wowhead.com/npc=82375 is, to my knowledge, still https://www.wowhead.com/npc=82375 becomes https://www.wowhead.com/npc=176267...\nSo... I guess https://www.wowhead.com/npc=59442 won in the end?",
            date = "2022-06-09T12:48:35-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30506#comments:id=5383073",
        },
        {
            id = 5456241,
            score = 1,
            author = "Mypciscraze",
            text = "Hi all\n\nOn This Achievement https://www.wowhead.com/achievement=7601 you need to finish quests with https://www.wowhead.com/object=208127 in 22 locations. All of them You can find in main Vilages/Cities in Northrend Zones. To get to Pandoria use Teleport in Stormwind in Wizard's Sanctum \"Portal to Jade Forest\" 45.5 87.4.\n\nSee My Video for this achievement with MAP and Quests if need it - https://youtu.be/jYQF3ggmmWM\n\nSee Locations in the order I did :\n\n1. Jade Forest, Paw'don Village 44.8 84.4\n2. Jade Forest, Pearlfin Village 59.6 83.2\n3. Jade Forest, Jade Temple Grounds 54.6 63.3\n4. Jade Forest, Dawn's Blossom 45.8 43.6\n5. Jade Forest, Greenstone Village 48.1 34.6\n6. Jade Forest, Sri-La Village 55.7 24.4\n7. Jade Forest, Tian Monastery 41.7 23.2\n8. Kun-Lai Summit, Binan Village 72.7 92.2\n9. Kun-Lai Summit, Westwind Rest 54.1 82.9 To unlock this https://www.wowhead.com/object=208127 You need to do 6 quests:\n[spoiler]\n1A. https://www.wowhead.com/quest=30457 from https://www.wowhead.com/npc=59073 72.2 91.9 Slay 10 Bataari mobs and https://www.wowhead.com/npc=59083\n1B. https://www.wowhead.com/quest=30460 from https://www.wowhead.com/npc=59077 71.6 92.8 Use https://www.wowhead.com/item=79819 on 8 https://www.wowhead.com/npc=59143\n1C. https://www.wowhead.com/quest=30459 from https://www.wowhead.com/npc=59076 70.8 90.4 Pick up from ground 12 arrows\n4. https://www.wowhead.com/quest=30506 after done quest 1A-1C You can pick up this quest from one of this three NPC. Speak with https://www.wowhead.com/npc=59441 He is inside bulding on 1st floor 71.5 93.1\n5. https://www.wowhead.com/quest=30512 Speak with https://www.wowhead.com/npc=63754 58.9 80.4 then speak with https://www.wowhead.com/npc=63542 56.3 84.4\n6. https://www.wowhead.com/quest=30514 first press on Yaungol Banner then slain https://www.wowhead.com/npc=59483 after finish this quest village will go up then You will be able to see https://www.wowhead.com/object=208127 54.1 82.9\n[/spoiler]\n10. Kun-Lai Summit, One Keg 57.5 60\n11. Kun-Lai Summit, The Grummle Bazaar 64.2 61.2\n12. Kun-Lai Summit, Zouchin Village 62.5 28.9\n13. Townlong Steppes, Longying Outpost 71.1 57.8\n14. Dread Wastes, Klaxxi'vess 55.9 32.3\n15. Dread Wastes, Soggy's Gamble 55.2 71.1\nFirst Speak with Zidormi 81 29.5\n16. Vale of Eternal Blossoms, Shrine of Seven Stars 37.1 66.5\n17. Vale of Eternal Blossoms, Mistfall Village 35.1 77.7\n18. The Veiled Stair, Tavern in the Mists 55 72.3\n19. Valley of the Four Winds, Pang's Stead 83.6 20.3\n20. Valley of the Four Winds, Stoneplow 19.8 55.9\n21. Krasarang Wilds, Marista 51.5 77.3\n22. Krasarang Wilds, Zhu's Watch 75.9 6.9\n\nWay points for Tomtom:\n\n[spoiler]\n\n/way Jade Forest 44.8 84.4\n/way Jade Forest 59.6 83.2\n/way Jade Forest 54.6 63.3\n/way Jade Forest 45.8 43.6\n/way Jade Forest 48.1 34.6\n/way Jade Forest 55.7 24.4\n/way Jade Forest 41.7 23.2\n/way Kun-Lai Summit 72.7 92.2\n/way Kun-Lai Summit 54.1 82.9 To unlock this https://www.wowhead.com/object=208127 You need to do 6 quests:\n/way Kun-Lai Summit 57.5 60\n/way Kun-Lai Summit 64.2 61.2\n/way Kun-Lai Summit 62.5 28.9\n/way Townlong Steppes 71.1 57.8\n/way Dread Wastes 55.9 32.3\n/way Dread Wastes 55.2 71.1\n/way Vale of Eternal Blossoms 81 29.5 First Speak with Zidormi\n/way Vale of Eternal Blossoms 37.1 66.5\n/way Vale of Eternal Blossoms 35.1 77.7\n/way The Veiled Stair 55 72.3\n/way Valley of the Four Winds 83.6 20.3\n/way Valley of the Four Winds 19.8 55.9\n/way Krasarang Wilds 51.5 77.3\n/way Krasarang Wilds 75.9 6.9\n\n[/spoiler]\n.\nHope That help You :).",
            date = "2022-10-22T12:00:53-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30506#comments:id=5456241",
        },
    },
