            text = "You will not be able to see the candy bucket for Hallows End if you have not completed https://www.wowhead.com/quest=57067 and the Mogu assault is up in Vale of Eternal Blossoms.",
            date = "2020-10-19T21:13:41-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30513#comments:id=3240464",
        },
    },
    [30514] = {
        {
            id = 3226454,
            score = 27,
            author = "ZorynSubZero",
            text = "If you are on the quest line for https://www.wowhead.com/quest=57067 it may be impossible to get the mob needed for this to spawn.\nI had to complete that chain before I could progress this - hope it helps someone in a similar boat.",
            date = "2020-08-29T17:40:52-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30514#comments:id=3226454",
        },
        {
            id = 3240093,
            score = 15,
            author = "Ozgin",
            text = "I am at a loss.  The boss wasn't triggering, I was literally on NO other quests.  I abandoned it to try and pick it up again but the quest giver is gone. Just gone, and has not come back.  I've reloaded several times, I've logged in and out, he's GONE.  I literally can't complete Hallow's End or Loremaster without this quest chain to open up this base and I don't know what to do.  Please help!\n\nEDIT: Okay, can confirm.  Even if you have not started Mogu at the Gates, you're gonna need to go down, pick it up, and finish the quest line.  As soon as I did, the quest giver popped back into existence and I was able to complete the quest.",
            date = "2020-10-18T19:01:06-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30514#comments:id=3240093",
        },
        {
            id = 1721464,
            score = 13,
            author = "212676",
            text = "This quest is going to be Legen...wait for it...dary!",
            date = "2012-09-27T07:38:22-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30514#comments:id=1721464",
        },
        {
            id = 1942758,
            score = 7,
            author = "1190860",
            text = "Oh, you wanna make a base? You should piss of the Yangoul first, that'll be totally rad. Never mind that the base you're after is f*cking burning behind me, we can fix that later.\n\nAlso, I like how they go all Age of Empires on the tents afterwards, fixing fires by hitting the ground. Only thing missing is the \"Wololoooo\" when they change from white to blue.",
            date = "2014-02-12T16:52:06-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30514#comments:id=1942758",
        },
