    [30515] = {
        {
            id = 3233660,
            score = 21,
            author = "AimbotOnMyX",
            text = "If the banner in this quest won't spawn the boss as of patch 8.3, make sure you've completed the storyline beginning with https://www.wowhead.com/quest=57067 first. Completing this storyline will phase the area back to MoP scaling and let you continue the quest. The storyline should only take 10-15 minutes at most.",
            date = "2020-09-28T03:19:59-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30515#comments:id=3233660",
        },
        {
            id = 1721831,
            score = 7,
            author = "817836",
            text = "Banner is at 58, 84.",
            date = "2012-09-27T15:40:29-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30515#comments:id=1721831",
        },
        {
            id = 1722215,
            score = 7,
            author = "908758",
            text = "Any banner guards alive when you burn the banner will come to put the banner out and probably aggro - right at the time that Ur-Bataar appears. While it is possible to kill them all and stay alive, it'd be easier to kill all four banner guards first, then burn the banner.",
            date = "2012-09-27T22:17:58-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30515#comments:id=1722215",
        },
        {
            id = 5271691,
            score = 7,
            author = "Tdminial",
            text = "If you can't see the npc to turn this quest in to, and the place is crawling with bfa mobs, you're going to have to do the questchain that starts with Mogu at the gates (https://www.wowhead.com/quest=57067/mogu-at-the-gates) (the quest giver is in mistfall village in Vale of eternal blossoms) - when you've done this (up to and including Return to Mistfall (https://www.wowhead.com/quest=57076/return-to-mistfall)) the bfa mobs will have disappeared and you can now see the pandas once more\nAs the cherry on top this complete waste of time, the mobs are level 50\n\n(Note: I had no problems getting the mob to spawn, quest completed as intended, the only thing I couldn't do was turn it in because the quest giver was gone)",
            date = "2021-10-28T08:33:54-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30515#comments:id=5271691",
        },
        {
            id = 5859026,
            score = 4,
            author = "datgrl",
            text = "I'm doing Pandaria Remix and I got this quest.  I have no idea where I stand in the quest chain.  When I hover over the tree in the comment by Whiterock, I can see my mains have completed it but my Remix alt doesn't show up anywhere.\n\nI went to the area and I could see the dialog as other people were completing the quest but the NPC wasn't there for me, even though the quest area was marked on the map.\n\nI ciouldn't find the NPC that starts Mogu at the Gates.  He's not at the gates and he's not in the Shadowlands area, either. will fix it, either.\n\nThe remix character I was playing was a Monk.  I hadn't been doing the training and decided to do that since I had hit this wall in questing.  After completing all the training available, I got a final quest to talk to Dezco (he's the Tauren Pally that you help in Karasang Wilds)  at the gates.  It was a monk specific quest and all of the spirits like the Crane, Tiger, etc. were there and they opened the gates.  Once I turned that in, I could go back and do Challenge Accepted.",
            date = "2024-05-19T11:23:35-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30515#comments:id=5859026",
        },
    },
    [30516] = {
        {
            id = 1722751,
            score = 164,
            author = "MietoxD",
            text = "After completing the quest, https://www.wowhead.com/npc=57385 will go to Sunsong Ranch and you'll receive a buff called https://www.wowhead.com/spell=114431 lasting 15 minutes after which your farm will expand by 4 crops.",
            date = "2012-09-28T06:42:01-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30516#comments:id=1722751",
        },
        {
            id = 1738456,
            score = 57,
            author = "919365",
            text = "Did you see all the chemicals he was using?  There goes my dream of organic farming.",
            date = "2012-10-11T11:26:09-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30516#comments:id=1738456",
        },
        {
            id = 1726851,
            score = 41,
            author = "SvartStillhet",
            text = "Looting Spideroot (http://www.wowhead.com/item=80122) will occasionally cause a few Spider Mites (www.wowhead.com/npc=59488) to spawn. You can avoid fighting them completely if you move away immediately after you loot.",
            date = "2012-10-01T02:37:50-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30516#comments:id=1726851",
        },
        {
            id = 1734980,
            score = 34,
            author = "Mi777",
            text = "This quest was available as soon as I got Honored rep with Tillers",
            date = "2012-10-07T22:05:37-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30516#comments:id=1734980",
        },
        {
            id = 1733382,
            score = 23,
            author = "sidelsky18",
            text = "You *can* log out while he upgrades your farm, but the 15 minute timer will not count down unless you are logged in.",
            date = "2012-10-06T12:29:46-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30516#comments:id=1733382",
        },
    },
    [30517] = {
        {
            id = 1732538,
            score = 187,
            author = "79637",
            text = "Just in case you do not find the npc because the wow map shows him at halfhill:\n\nThe npc is actually at 48, 34.",
            date = "2012-10-05T17:35:07-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30517#comments:id=1732538",
        },
        {
            id = 1739145,
            score = 48,
            author = "sorceressdee",
            text = "You get this quest at around 4500 rep into Revered with the Tillers. You find the yaks walking around in the area north west of Halfhill, but the location to take the yaks to in is NOT in Halfhill (which is where you might have picked up the quest).\n\nYou take the yaks to 50:35 where there is an entrance to a fenced area, with and some \"Prize Shagskin\" yaks inside the fence. You may find the map showing you that the turn in is a bit north west of this fenced area, but if you don't find Farmer Fung there, you can just go back to halfhill to hand in the quest. Similarly, if you don't find him at halfhill, you'll find him at 48:34.  See map  (http://www.wowhead.com/npc=57298)for his locations.",
            date = "2012-10-12T03:21:12-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30517#comments:id=1739145",
        },
        {
            id = 2551242,
            score = 16,
            author = "1841980",
            text = "To find one of the voting members check with Gina Mudclaw (Tillers Quartermaster). Click on \"Where does everyone live?\". It gets marked on your map. If you still cannot locate someone on her list, as Gina says \"you might want to have your eyes checked\".\nThis feature came in handy for finding Ella. I used it to locate her & bring her a gift that I found in a pile of dirt during a quest. I found a (x2) shiny apple and one jade cat statue. The item says so & so likes it. I checked the item on wowhead and found who you can get the max rep. with. But, any one will take it. Don't waste your time check the item out on Wowhead!",
            date = "2018-02-07T10:53:56-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30517#comments:id=2551242",
        },
        {
            id = 1837591,
            score = 12,
            author = "dartworth",
            text = "Found him @ 48 34 standing on top of a small pile of hay. This is in The Heartland next to the watertower.",
            date = "2013-04-01T11:09:40-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30517#comments:id=1837591",
        },
        {
            id = 1735359,
            score = 9,
            author = "ShlomiSapir",
            text = "Farmer Fung can be in 2 locations see Map (http://www.wowhead.com/npc=57298)",
            date = "2012-10-08T07:28:35-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30517#comments:id=1735359",
        },
    },
    [30518] = {
        {
            id = 1734089,
            score = 119,
            author = "Marchesi",
            text = "[ins] Once you've got the yak, head to 50,42, 34,98. If you use TomTom simply type /way 50,42, 34,98 and you are good.\nWhen you complete the quest, you will probably see the question mark at Heartland, and if you don't see Farmer Fung there, go to Halfhill and he will be there.\n\nBy completing this quest you will be able to get Farmer Fung's Vote III: Crazy For Cabbage (http://www.wowhead.com/quest=31947)",
            date = "2012-10-07T03:47:14-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30518#comments:id=1734089",
        },
        {
            id = 1919992,
            score = 23,
            author = "vizoere",
            text = "Mounted a Yak and don't know where to go? Don't have one of those fancy schmancy coordinate add-ons?\n\nJust head North. On the map, see the road that heads North out of Halfhill? The pen is right where the road changes direction to head back SW towards The Heartland. There's a little hut icon.",
            date = "2013-11-20T19:57:40-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30518#comments:id=1919992",
        },
        {
            id = 1734038,
            score = 19,
            author = "dipiddy",
            text = "Once you've got a yak, ride it north to the pen at ~50,36.",
            date = "2012-10-07T02:48:33-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30518#comments:id=1734038",
        },
        {
            id = 1796400,
            score = 10,
            author = "1075576",
            text = "It never ceases to amaze me how smug and self-superior rurals behave when everything that makes their occupation do-able beyond a subsistence level originates in cities. The rural electrification act, a government act before which less than twenty percent of farms had electricity, is just one of many examples. Then there is the little matter of how certain crimes have a higher per-capita rate in rural places than is the case in cities. This NPC is the first example of one in WOW I wanted to jump into the game TRON-style and murder.\n\nHaving said all of that, I just wanted to point out that you might want to keep at least three farm slots empty before doing this quest. The next one in the chain involves planting cabbages that you bring to this clown so he can feed his yaks. Funny how rurals are so much more polite and mannered to urban folk when they need something, no?",
            date = "2013-01-11T05:53:26-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30518#comments:id=1796400",
        },
        {
            id = 1709530,
            score = 7,
            author = "Zillions",
            text = "Fly to the Verdant Belt, which is immediately West of Halfhill.  I recommend going to the north portion, near the \"pen\" at Farmer Fung's farm.  You will be mounting the Yaks and riding at 100% movement speed to bring them to the pen.\n\nNote: Movement speed increasing buffs will work (AKA Aspect of the Cheetah) to increase your speed.",
            date = "2012-09-04T22:22:51-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30518#comments:id=1709530",
        },
    },
    [30519] = {
        {
            id = 1732542,
            score = 36,
            author = "rayramanoray",
            text = "Got this quest today after getting 8500/21000 into revered with the tillers",
            date = "2012-10-05T17:38:57-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30519#comments:id=1732542",
        },
        {
            id = 1738339,
            score = 10,
            author = "470888",
            text = "There is an alemental, Thousand-Year Guardian (http://www.wowhead.com/npc=66850)  that does 2 special abilities. The water spout can hit for a lot, so be careful. Once it's dead, just collect the water at 57,22 using the quest item.",
            date = "2012-10-11T09:24:35-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30519#comments:id=1738339",
        },
        {
            id = 1736243,
            score = 8,
            author = "1031642",
            text = "You actually receive this quest shortly before hitting 8500.\nIt became available to me once i turned a quest in and i only had 8450 (after turn-in)\nSo its probably somewhere between 8300 and 8400",
