    [30521] = {
        {
            id = 1736356,
            score = 67,
            author = "rayramanoray",
            text = "Received this quest today upon reaching 16,800/21,000 (revered) reputation with the Tillers",
            date = "2012-10-09T05:25:35-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30521#comments:id=1736356",
        },
        {
            id = 1736464,
            score = 27,
            author = "Netn",
            text = "This questchain consists of five quests.\n\nHaohan's Vote I: Bungalow Break-In (http://www.wowhead.com/quest=30521)\nHaohan's Vote II: The Real Culprits (http://www.wowhead.com/quest=30522)\nHaohan's Vote III: Pure Poison (http://www.wowhead.com/quest=30525)\nHaohan's Vote IV: Melons For Felons (http://www.wowhead.com/quest=30527)\nHaohan's Vote V: Chief Yip-Yip (http://www.wowhead.com/quest=30528)\n\nThe questchain seems to open up at around 16800/21000 into revered.\n\nThe first four quests will each give you 300 reputation. The last one will give you 1000 reputation.\n\nWithout human racial or guild perk that is: 2200\nWith either human racial or guild perk it's: 2420\nWith both human racial and guild perk it's: 2640\n\nHuman racial: Diplomacy (http://www.wowhead.com/spell=20599)\nGuild perk: Mr. Popularity (http://www.wowhead.com/spell=78635)",
            date = "2012-10-09T08:29:13-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30521#comments:id=1736464",
        },
        {
            id = 1761548,
            score = 9,
            author = "229269",
            text = "I was having trouble getting this quest and submitted a ticket. This was the response I got an should help everyone.\n\n\"The Tiller's vote quests have to be taken in order, each one unlocking the next. In order to finish up your farm, you will need to complete Farmer Fung's Vote, the Nana Mudclaw, and finally Haohan ^_^ It may take you a couple days as I believe some of them require planting and harvesting of items, but then you should be good ^_^ Hope this helps, and thank you for your patience.\"\n\n- Game Master Scrydaen",
            date = "2012-11-12T17:46:47-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30521#comments:id=1761548",
        },
        {
            id = 2338687,
            score = 4,
            author = "marcusant",
            text = "If you just hit 16,800/21,000 (Revered) reputation with the Tillers but do not see the quest, relogging should help",
            date = "2016-06-10T01:21:33-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30521#comments:id=2338687",
        },
        {
            id = 1759527,
            score = 3,
            author = "1053669",
            text = "While I am not best friends with Haohan, I hit exalted, and got nothing either to remove the boulder. From what I've been told, you don't need to be best friends with him, just exalted with Tillers. All I know is not being able to remove the boulder irks me.",
            date = "2012-11-08T23:03:23-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30521#comments:id=1759527",
        },
    },
    [30522] = {
        {
            id = 1735969,
            score = 14,
            author = "Caradnaur",
            text = "Traces can be found around the building coords 38/45",
