    },
    [30523] = {
        {
            id = 1731557,
            score = 80,
            author = "Bazzmann",
            text = "FYI,\n\nWhen you do this quest you have to remain online for the 15 minutes for her to fix the wagon,  you can leave the zone, but if you go offline the timer gets suspended and restarts when you come online again.\n\nYou will have this buff: https://www.wowhead.com/spell=114483 and a timer showing how much time is left for the wagon to be gone.\n\nMight save you some confusion and hassle if you log out and expect it to be done later when you come back online.",
            date = "2012-10-04T18:47:27-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30523#comments:id=1731557",
        },
        {
            id = 1736076,
            score = 63,
            author = "861589",
            text = "Worth to mention this quest becomes available right after you reach revered with The Tillers, Farmer Yoon will ask you to go to Fish Fellreed.",
            date = "2012-10-08T21:24:47-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30523#comments:id=1736076",
        },
        {
            id = 1718654,
            score = 24,
            author = "Mzbehavin",
            text = "quest is exactly as it says to go and talk to her (she is stood on the end of the pier by the pond, at the valley of farmland),\nyou interact with her and then she tells you to meet her back at the wagon on your farm..\nit takes her about 15 minutes to fix it and then off she goes.. you don't need to do anything at this time whilst she is working away, so run around kill stuff grab a drink and hey presto 15 mins later you have 4 more plots available..  (Growing the Farm  buff will be shown and a timer)",
            date = "2012-09-25T11:37:23-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30523#comments:id=1718654",
        },
        {
            id = 1853223,
            score = 12,
            author = "Twinsen01",
            text = "This quest is part of a series of three quests that expand your farm.\nEach quest adds 4 more soil patches.\n\nhttps://www.wowhead.com/quest=30260 (Available when you are honored)\nhttps://www.wowhead.com/quest=30523 (Available when you are revered)\nhttps://www.wowhead.com/quest=30529 (Available when you are exalted and have collected all the votes)",
            date = "2013-05-15T06:08:26-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30523#comments:id=1853223",
        },
        {
            id = 1789000,
            score = 11,
            author = "laserfloyd",
            text = "Tip: Do NOT delete \"extra\" planks if you have an overflow after collecting 100.  If you delete the smaller extra stack they will all disappear. You'll have to actually restart the quest by talking to the Fish Fellreed (http://www.wowhead.com/npc=58705).  Learned the hard way. ;)",
            date = "2012-12-29T07:22:53-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30523#comments:id=1789000",
        },
    },
    [30524] = {
        {
            id = 1710463,
            score = 134,
            author = "Mzbehavin",
            text = "as soon as you accept this quest all the crabs in the pond become hostile..so be warned!  picking up a few packs can hurt too.  by the way you are not fishing for the wood, it is in the pond sparkling , so you have to go up and click it :) if your dps is low goto the corner edges not direct the middle of the pond (or you will take a smashing) and collect the wood that way, it slower but a bit easier.\n\nOnce you have handed the quest in to Fish, you then meet her back at your farm, she will be fixing the wagon, it takes approximately about 15 mins (there is a buff on your screen with a timer)  for her to do this; then she will disappear and you will four new plots of land.  You do not need to stay around whilst she does this, just don't log out.\n\nYou can then go and buy the \"Thunder King Pest repellent' for your farm from Gina Mudclaw. and a scarecrow if you like ps the scarecrow is just a gimmick for your bag, it does nothing for your farm :).\n\n  you need to be revered with tillers to do these qst.\n\n15 mins to complete updated thanks avajulia  oh by the way don't log out during this time, you have to stay log on whilst it completes or when you log back in the timer will still be there :)",
            date = "2012-09-07T05:51:48-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30524#comments:id=1710463",
        },
        {
            id = 1764067,
            score = 66,
            author = "multiversekyle",
            text = "A note that may be particularly important for people weak in AoE: If you swim to the bottom, you will get attacked by A LOT of crabs. However, if you stay near the top along the edges of the lake, there should be several smaller groups of crabs, which guard enough wood to get the quest done after about four or five small mobs.",
            date = "2012-11-18T02:07:19-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30524#comments:id=1764067",
        },
        {
            id = 1731102,
            score = 47,
            author = "lightclaw",
            text = "Finishing this quest line upgrades your farm and allows you to buy the \"Thunder King\" Pest Repellers (http://www.wowhead.com/item=89813) from Gina Mudclaw (http://www.wowhead.com/npc=58706).\n\nRemoving the broken wagon from your farm takes Fish Fellreed 15 minutes to complete.  You receive a buff called Growing the Farm (http://www.wowhead.com/spell=114483) that shows how long you have before they will be completed.  The buff is not applied until you enter your farm plot phase.  During this time Fish Fellreed repairs the broken wagon and removes it from the farm plot, giving you an additional 4 spots to grow crops.\n\nAlso note that since this is a buff, you must be logged into the game for 15 minutes before the buff falls off and the change takes effect.\n\nOnce the farm is cleared a second irrigation barrel will appear, assuming you installed the first.  You are also eligible to install the pest repellers at this point.  One purchase installs two repellers.  In both cases, one piece of equipment covers two rows of crops.",
            date = "2012-10-04T10:30:53-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30524#comments:id=1731102",
        },
        {
            id = 1732173,
            score = 29,
            author = "950640",
            text = "The flavor text on the Waxed Plank indicates that it's bamboo\nIn which case it's not true wood, as bamboo is a grass and not a tree.\nIt's also quite odd that Fish sent you to 'fish' for a buoyant item on the lake bed, possibly indicating that it's waterlogged.",
            date = "2012-10-05T10:23:53-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30524#comments:id=1732173",
        },
        {
            id = 1789035,
            score = 27,
            author = "laserfloyd",
            text = "Do NOT delete any extra wood you might have prior to turning this in. Deleting an overflow stack deletes it all and you'll have to get the quest from Fish Fellreed (http://www.wowhead.com/npc=58705) over again.  Learned the hard way. ;)",
            date = "2012-12-29T09:17:12-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30524#comments:id=1789035",
        },
    },
    [30525] = {
        {
            id = 1744657,
            score = 78,
            author = "Zanno",
            text = "https://www.wowhead.com/item=80142 Found inside vermin caves around 39, 20\nhttps://www.wowhead.com/item=80140 Found inside vermin caves around 44, 22\nhttps://www.wowhead.com/item=80143 Found in grassy areas above ground in the vermin area.\nhttps://www.wowhead.com/item=80141 Found inside vermin caves around 47, 21",
            date = "2012-10-18T06:51:30-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30525#comments:id=1744657",
        },
        {
            id = 1736467,
            score = 23,
            author = "Netn",
            text = "This questchain consists of five quests.\n\nHaohan's Vote I: Bungalow Break-In (http://www.wowhead.com/quest=30521)\nHaohan's Vote II: The Real Culprits (http://www.wowhead.com/quest=30522)\nHaohan's Vote III: Pure Poison (http://www.wowhead.com/quest=30525)\nHaohan's Vote IV: Melons For Felons (http://www.wowhead.com/quest=30527)\nHaohan's Vote V: Chief Yip-Yip (http://www.wowhead.com/quest=30528)\n\nThe questchain seems to open up at around 16800/21000 into revered.\n\nThe first four quests will each give you 300 reputation. The last one will give you 1000 reputation.\n\nWithout human racial or guild perk that is: 2200\nWith either human racial or guild perk it's: 2420\nWith both human racial and guild perk it's: 2640\n\nHuman racial: Diplomacy (http://www.wowhead.com/spell=20599)\nGuild perk: Mr. Popularity (http://www.wowhead.com/spell=78635)",
            date = "2012-10-09T08:33:27-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30525#comments:id=1736467",
        },
        {
            id = 1704864,
            score = 22,
            author = "ProtagonistDB",
            text = "The four plants are found in specific locations around the virmen warren.  The Violet Lichens are found outside the burrows, while each of the three burrows contain one the other plants.  From east to west (or from right to left as you face the mountain cliffs) Cave Lilies, Blood Blooms, and Ghostcaps can be retrieved respectively.",
            date = "2012-08-27T08:24:59-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30525#comments:id=1704864",
        },
        {
            id = 1759195,
            score = 8,
            author = "oisian",
            text = "The virmen warrens on the cliffs are surrounded by birds and may be mistaken for nests from a distance. Low resolutions may compound this. I flew over them a couple of times before I got close enough to make them out.",
            date = "2012-11-08T08:36:12-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30525#comments:id=1759195",
        },
        {
            id = 1757490,
            score = 4,
            author = "973088",
            text = "As a rogue, I find his knowledge of poisons questionable, if not hilarious. A farmer pandaren -- mixing poisons?\n\nI'd mix my own for him... but, uh, family recipe and all. And the reagents cost quite a bit; gotta keep my bulging coin purse in check.",
            date = "2012-11-05T06:58:06-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30525#comments:id=1757490",
        },
    },
    [30526] = {
        {
            id = 1735458,
            score = 138,
            author = "sdkphoenix",
            text = "This quest becomes available at 12600/21k. I was unable to get it when i was at 12500.\n\nThe dog can be found between two boulders in the southern Heartland, just north of the pumpkins and a water tower.",
            date = "2012-10-08T09:21:00-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30526#comments:id=1735458",
        },
        {
            id = 1741578,
            score = 110,
            author = "Obuibo",
            text = "Heart strings tugged! Critical hit!",
            date = "2012-10-14T16:17:10-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30526#comments:id=1741578",
        },
        {
            id = 1736562,
            score = 85,
            author = "Aesiria",
            text = "Found this dog after getting revered with The Tillers. I don't know if you can get this quest earlier, but as I've been farming those Dark Soil items in the Heartland area for atleast an hour over several days prior to being revered, and never saw this dog, that's why I think you might need to be revered to see him.\n\nAfter I had turned in the quest, the dog despawned(or entered another phase).\n\nEdit: When I returned to my/Farmer Yoon's farm at Halfhill after completing this quest, there's a dog next to him just called \"Dog\".\nIf you do the /love emote to it, you will see the text \"Your dog loves you too!\", and if you do /pet you will see the text \"Your dog pushes its head under your hand.\"\nMaybe some other emotes will give a response too - I didn't try :)\n\nThe dog will also sometimes dig below the house on your farm... I'm thinking this dog might be needed to find that old map Fish Fellreed is talking about?\n\nEdit: Ok; so the dog is not connected to the old map it seems.",
            date = "2012-10-09T10:44:33-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30526#comments:id=1736562",
        },
        {
            id = 1809607,
            score = 75,
            author = "153089",
            text = "In all the time I've spent in Pandaria, I don't think I've ever slaughtered so many Mushan as quickly as I have for this dog.",
            date = "2013-02-05T16:27:14-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30526#comments:id=1809607",
        },
        {
            id = 1737236,
            score = 57,
            author = "eresin",
            text = "After you hand this quest in:\n\nLost Dog says: Woof!\nThe dog wags its tail happily.  It heads towards your farm.\n\nIf you do follow him he despawns part of the way there but does indeed turn up at your farm next to Farmer Yoon",
            date = "2012-10-10T06:23:55-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30526#comments:id=1737236",
        },
    },
    [30527] = {
        {
            id = 1743807,
            score = 122,
            author = "aryon",
            text = "On completion he says:\n\nI don't know how I would run this place without you, .\n\nHere's a clue, Yoon: you don't. You just stand there and watch me farm, then occasionally butt in and tell me to plant some worthless crop that I immediately destroy and replace with something worthwhile.\n\nGive me your farm.",
            date = "2012-10-17T03:46:35-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30527#comments:id=1743807",
        },
        {
            id = 1739124,
            score = 66,
            author = "Chuffy",
            text = "NOTE: Farmer Noob https://www.wowhead.com/npc=58646 sure takes his sweet time to give you the follow up quest https://www.wowhead.com/quest=30528. You must have 20,000 Revered with the Tillers to get the follow on quest. If you have the reputation and don't see the quest, move in and out of the farm if it isn't showing.\n\nIf you don't wish to wait a day for the crops to grow, an alternative is to plant and then remove the crops with your https://www.wowhead.com/item=89880 until you get Bursting crops. i.e. the lucky crops that grow and can be harvested immediately without weeds or pests. It took me about 300 seeds to get 4 Bursting crops.\n\nIf you are mad enough to follow my example...\n\nBuy a large stock of seeds and drag them to your action bar for quicker planting.\nPick up the https://www.wowhead.com/item=89880 and drag that to your action bar for quicker crop clearing.\nBy now you should already have the https://www.wowhead.com/item=89812 and https://www.wowhead.com/item=89813 installed, if not then buy them from https://www.wowhead.com/npc=58706 at the centre of Halfhill market. (As jaedia noted, the 2 non-repeatable quests these items start gives you some extra rep too)\nDon't rip up every plot on your farm, just stand in the centre of a plot of 4 and plant, deal with whatever thing blights your crop and then dig it up and replant until you have harvested 4 bursting crops. It's best to be in the plots nearest one of your https://www.wowhead.com/item=89812s because you'll be watering quite a bit.\nIf you're lucky and efficient you might get it complete in an hour or so.\n\nPro Tip: A cold beer or three makes the exercise more tolerable ;)\n\nHappy Grinding/Farming! :)",
            date = "2012-10-12T02:57:11-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30527#comments:id=1739124",
        },
        {
            id = 1744977,
            score = 34,
            author = "373521",
            text = "On a hilarious note, upon accepting this quest the melons at the 42,53 area become all sparkly and clickable with the little gear icon. When you attempt to do so, one of Mudclaw's Guard Dogs comes out and attacks you. I have killed a lot of his dogs with no melons as a reward or loot. After about 20 kills (lol), I figure that the Mudclaw family must have a VERY large kennel somewhere on GM isle with access to a mage port.",
            date = "2012-10-18T15:23:35-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30527#comments:id=1744977",
        },
        {
            id = 1784297,
            score = 30,
            author = "Stalyn",
            text = "Those are some big melons.\n\nWhy, thank you, I've been growing them all my life.",
            date = "2012-12-19T20:16:34-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30527#comments:id=1784297",
        },
        {
            id = 1736470,
            score = 28,
            author = "Netn",
            text = "This questchain consists of five quests.\n\nHaohan's Vote I: Bungalow Break-In (http://www.wowhead.com/quest=30521)\nHaohan's Vote II: The Real Culprits (http://www.wowhead.com/quest=30522)\nHaohan's Vote III: Pure Poison (http://www.wowhead.com/quest=30525)\nHaohan's Vote IV: Melons For Felons (http://www.wowhead.com/quest=30527)\nHaohan's Vote V: Chief Yip-Yip (http://www.wowhead.com/quest=30528)\n\nThe questchain seems to open up at around 16800/21000 into revered.\n\nThe first four quests will each give you 300 reputation. The last one will give you 1000 reputation.\n\nWithout human racial or guild perk that is: 2200\nWith either human racial or guild perk it's: 2420\nWith both human racial and guild perk it's: 2640\n\nHuman racial: Diplomacy (http://www.wowhead.com/spell=20599)\nGuild perk: Mr. Popularity (http://www.wowhead.com/spell=78635)",
            date = "2012-10-09T08:35:17-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30527#comments:id=1736470",
        },
    },
    [30528] = {
        {
            id = 1737974,
            score = 271,
            author = "445261",
            text = "Don't be confused by Yoon saying he needs more time to prepare the mixture or by not having anything in your bags for this quest.  Just head straight for the cave.  When you arrive, the extra action button will appear, even though you don't have any poisoned melons in your bag.\n\nAdditionally, he takes double dmg when he's stunned by eating the melons, so time your CDs accordingly.\n\nEdited to add: You need to pass 20k/21k revered with tillers (http://www.wowhead.com/faction=1272) before you can pick up this quest, which may required you to wait for another set of dailies between IV (http://www.wowhead.com/quest=30527) and V (http://www.wowhead.com/quest=30528) of this quest series.  However, once you pick up the quest, you can head straight to the cave.  Even though he seems to indicate that you need to wait at this point, you don't.",
            date = "2012-10-10T23:48:07-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30528#comments:id=1737974",
        },
        {
            id = 1714188,
            score = 100,
            author = "Zillions",
            text = "This is the final quest in the Haohan's Vote chain.  You receive this quest once harvesting your https://www.wowhead.com/item=74848 for the quest https://www.wowhead.com/quest=30527.\n\nYou will find https://www.wowhead.com/npc=59567 in Kunzen Cave, along the northern border of Valley of the Four Winds.\nThe NPC has over 11 Million health, but you are aided by a \"Throw Melon\" ability on your Extra Action bar, which will light up when Chief Yip-Yip is about to charge.  Simply click your action button to stun him.",
            date = "2012-09-15T18:14:19-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30528#comments:id=1714188",
        },
        {
            id = 1743489,
            score = 50,
            author = "Nekrotik",
            text = "To summarize this quest:\n\nWhen you get the quest, you won't find any melons in your bags. Just go to the cave at 33.3,20.2 and when you enter, the NPC will be spawned and you will acquire a special action button in the middle of your screen. When the button lights up it means he's about to charge and you should click it (or use your keybind if you've assigned one). I only had to use it twice. If you simply use the button whenever it's active, you can't fail to kill him as it pretty much turns him into a normal elite like the ones you kill every day while doing dailies.",
            date = "2012-10-16T16:51:29-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30528#comments:id=1743489",
        },
        {
            id = 1742075,
            score = 47,
            author = "Balgair",
            text = "After you hand this quest in, the five Tillers leaders visit your farm for a short scene:\n\n[10:52:41]Farmer Fung says: Ho, Yoon! Is it true? Did your plan work?\n[10:52:47]Mung-Mung says: Is that nasty Chief Yip Yip dead?\n[10:52:52]Farmer Yoon says: Yes, it's true! Thanks to  the Kunzen's leader is dead. Those monkeys shouldn't bother Mr. Mudclaw any more.\n[10:52:56]Haohan Mudclaw says: Well I'll be a hozen's uncle...\n[10:52:59]Haohan Mudclaw says: You know Yoon, maybe I was wrong about you.\n[10:53:05]Haohan Mudclaw says: I know I'm a stubborn old paw of the earth, but even I have to admit you've done me a great deed.\n[10:53:10]Haohan Mudclaw says: My farm was in real trouble because of those hozen, but it's saved thanks to you.\n[10:53:14]Haohan Mudclaw says: You've more'n earned my vote.\n[10:53:26]Haohan Mudclaw says: , this last spot's for you and Farmer Yoon. Why don't you do the honors?\n(You click the last bowl on the shrine)\n[10:53:32]Haohan Mudclaw says: There ya go!\n[10:53:33]Mung-Mung says: Nice job, Yoonie!\n[10:53:34]Gina Mudclaw says: Congratulations!\n[10:53:35]Haohan Mudclaw says: Yoon, , it's an honor to have you join us.\n[10:53:41]Haohan Mudclaw says: Welcome aboard... Tillers!\n\nThis also opens up https://www.wowhead.com/quest=30529, if by this time you have reached exalted with the Tillers.",
            date = "2012-10-15T04:59:30-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30528#comments:id=1742075",
        },
        {
            id = 1751940,
            score = 39,
            author = "tatorface",
            text = "As a hunter, I was standing slightly out of the cave when I pulled and my pet tanked him inside. When the game said to throw the melons, I clicked the action button but nothing would happen. I reset and tried again, but inside the cave this time. It works. Just remember, be INSIDE the cave.",
            date = "2012-10-27T16:04:08-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30528#comments:id=1751940",
        },
    },
    [30529] = {
        {
            id = 1739230,
            score = 284,
            author = "408995",
            text = "It takes 15 minutes for Haohan Mudclaw to upgrade the Sunsong Ranch to a 4x4 plot of land. A buff will appear to display how long is left on the upgrade.",
            date = "2012-10-12T05:15:23-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30529#comments:id=1739230",
        },
        {
            id = 1738194,
            score = 233,
            author = "Netn",
            text = "You actually need both exalted and have completed this quest: Haohan's Vote V: Chief Yip-Yip (http://www.wowhead.com/quest=30528) for it to show up.\n\nThe previous one with the melons bugged for me so i had to wait an additional day which lead me to hit exalted without finishing Haohan's Vote questchain. The quest to remove the boulder only showed up once i completed it.",
            date = "2012-10-11T06:27:32-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30529#comments:id=1738194",
        },
        {
            id = 1772442,
            score = 90,
            author = "Zaynah",
            text = "You need to be exalted with The Tillers (http://www.wowhead.com/faction=1272) and must have collected all the votes. Haohan's (http://www.wowhead.com/npc=59594) happens to be the last one. If you cannot buy the plow to initiate the quest, check that you have completed all the vote quests:\n\nLearn and Grow I: Seeds (http://www.wowhead.com/quest=30535)\nLearn and Grow II: Tilling and Planting (http://www.wowhead.com/quest=30254)\nLearn and Grow III: Tending Crops (http://www.wowhead.com/quest=30255)\nLearn and Grow IV: Harvesting (http://www.wowhead.com/quest=30256)\nLearn and Grow V: Halfhill Market (http://www.wowhead.com/quest=30257)\nLearn and Grow VI: Gina's Vote (http://www.wowhead.com/quest=31945)\n\nMung-Mung's Vote I: A Hozen's Problem (http://www.wowhead.com/quest=30258)\nMung-Mung's Vote II: Rotten to the Core (http://www.wowhead.com/quest=30259)\nMung-Mung's Vote III: The Great Carrot Caper (http://www.wowhead.com/quest=31946)\n\nFarmer Fung's Vote I: Yak Attack (http://www.wowhead.com/quest=30517)\nFarmer Fung's Vote II: On the Loose (http://www.wowhead.com/quest=30518)\nFarmer Fung's Vote III: Crazy For Cabbage (http://www.wowhead.com/quest=31947)\n\nNana's Vote I: Nana's Secret Recipe (http://www.wowhead.com/quest=30519)\nNana's Vote II: The Sacred Springs (http://www.wowhead.com/quest=31948)\nNana's Vote III: Witchberry Julep (http://www.wowhead.com/quest=31949)\n\nHaohan's Vote I: Bungalow Break-In (http://www.wowhead.com/quest=30521)\nHaohan's Vote II: The Real Culprits (http://www.wowhead.com/quest=30522)\nHaohan's Vote III: Pure Poison (http://www.wowhead.com/quest=30525)\nHaohan's Vote IV: Melons For Felons (http://www.wowhead.com/quest=30527)\nHaohan's Vote V: Chief Yip-Yip (http://www.wowhead.com/quest=30528)",
            date = "2012-11-30T18:00:09-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30529#comments:id=1772442",
        },
        {
            id = 1740135,
            score = 60,
            author = "eresin",
            text = "Poor Thunder must have one heck of a headache headbutting that boulder for 15 minutes!",
            date = "2012-10-13T04:03:25-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30529#comments:id=1740135",
        },
        {
            id = 1700569,
            score = 43,
            author = "Cielos",
            text = "This quest became available to me through Farmer Yoon after I had reached exalted status with [faction=1272].",
            date = "2012-08-16T12:22:26-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30529#comments:id=1700569",
        },
    },
    [30534] = {
        {
            id = 1742336,
            score = 346,
            author = "321961",
            text = "You must be exalted with the Tillers and Best Friends with the various people for them to come and loiter around your farm. There would appear to be only two who are actually useful - Gina (vendor) and Jogu (crop predictions). I personally go for Jogu because I have a traveller's tundra mammoth.\n\nhttps://www.wowhead.com/npc=58710\nHe'll come and sit by the side of your pond. This makes it a little more convenient to ask him about the crop forecast.\nSince he is only found at the market, he will come to your farm at any time, with the below exception.\n\nhttps://www.wowhead.com/npc=58706\nShe will stand next to Farmer Yoon and give you a repair vendor, as well as being the Tiller's Quartermaster with things like farm systems, vanity items, and goat mounts.\nSince she is only found at the market, she will come to your farm at any time, with the below exception.\n\nEdit: There seems to be an exception for the two npcs above - Gina and Jogu. If the npc is providing a daily quest that day, you are not offered the option to ask them to the farm. However, as long as you don't ask someone else to come to your farm, the next day that the npc isn't handing out a daily, they will appear on your farm once again.\n\n[br]\nhttps://www.wowhead.com/npc=57402\nHe will come and stand next to Farmer Yoon looking not-so-decorative, and doing nothing much.\nIf he's at the market he will not come to your farm and you must wait for a day when he is at home.\n\nhttps://www.wowhead.com/npc=58761\nShe will come and stand by Farmer Yoon and look decorative.\nIf she's at the market she will not come to your farm and you must wait for a day when she is inside her father's house.\n\nhttps://www.wowhead.com/npc=58707\nHe will come and stand about on your farm with several chickens near him (he's feeding them, but not really).\nIf he's at the market he will not come to your farm and you must wait for a day when he is at home.\n\nhttps://www.wowhead.com/npc=58709\nHe'll come and sit by your sheep, and do nothing much.\nIf he's at the market he will not come to your farm and you must wait for a day when he is at home.\n\nhttps://www.wowhead.com/npc=57298\nHe will come and stand by the bale of hay and the tree stump, near the watering can, looking not-so-decorative, and doing nothing much.\nIf he's at the market he will not come to your farm and you must wait for a day when he is at home on his haystack.\n\nhttps://www.wowhead.com/npc=58708\nShe'll come and lurk on top on the bale of hay near the watering can.\nIf she's at the market she will not come to your farm and you must wait for a day when she is at \"home\" ontop of the hozen ridge where so many dailies are completed.\n\nhttps://www.wowhead.com/npc=58647\nShe'll come and wander about your farm looking at things (and doing nothing really).\nIf she's at the market she will not come to your farm and you must wait for a day when she is at home with her cats.\n\nhttps://www.wowhead.com/npc=58705\nShe'll come and stand just inside the pen where the yak and the pig hang out. She doesn't appear to do anything.\nIf she's at the market she will not come to your farm and you must wait for a day when she is at \"home\" on her pier.",
            date = "2012-10-15T10:58:24-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30534#comments:id=1742336",
        },
        {
            id = 1741939,
            score = 307,
            author = "579240",
            text = "Oh man, I seriously need a best friend. I am so lonely I started to talk to the shrine at my farm.",
            date = "2012-10-15T00:37:50-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30534#comments:id=1741939",
        },
        {
            id = 1778558,
            score = 212,
            author = "815572",
            text = "A second hand?  Why doesn't Yoon get off his bear @$$ and do stuff?  :P",
            date = "2012-12-09T17:41:58-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30534#comments:id=1778558",
        },
        {
            id = 1741169,
            score = 88,
            author = "1045788",
            text = "Was hoping that Sho might help keep away or fight off vermin since her flavor text kind of suggests something to that intent, but that doesn't seem to be the case. Hopefully these helpers will be updated in the future, combat assistance would be nice when farming on a non-DPS character since it can be a little time consuming.",
            date = "2012-10-14T06:38:54-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30534#comments:id=1741169",
        },
        {
            id = 1740164,
            score = 70,
            author = "819618",
            text = "I asked Ella, my only best friend, to be a farm hand but it didn't count for the quest. Any ideas what's the problem?",
            date = "2012-10-13T04:52:27-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30534#comments:id=1740164",
        },
    },
    [30535] = {
        {
            id = 1722430,
            score = 11,
            author = "Myphindor",
            text = "You can literally see him from where you are standing.\n\nMade me chuckle. :)",
            date = "2012-09-28T01:57:51-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30535#comments:id=1722430",
        },
        {
            id = 1703684,
            score = 7,
            author = "lloviosa",
            text = "This is the second quest in the chain to unlock farming.\n\nA Helping Hand  (http://mop.wowhead.com/quest=30252)\nLearn and Grow I: Seeds (http://mop.wowhead.com/quest=30535)\nLearn and Grow II: Tilling and Planting (http://mop.wowhead.com/quest=30254)\nLearn and Grow III: Tending Crops (http://mop.wowhead.com/quest=30255)\nLearn and Grow IV: Harvesting  (http://mop.wowhead.com/quest=30256)\nLearn and Grow  V: Halfhill Market (http://mop.wowhead.com/quest=30257)\n*Learn and Grow VI: Gina's Vote (http://mop.wowhead.com/quest=31945)\n\n*You may have to do this last quest the following day. Crops ripen when dailies reset so unless its slightly before that time, you'll need to come back after they do, or any time the next day.\n\nThe good news is that if you have your crops planted even moments before reset, they will be ready very soon! This applies for regular farming too, not just this quest. I've tested and tried this method myself and was able to harvest within 8 min. after planting and tending.\n\nEdit: updated for patch 5.1. Crops no longer ripen at midnight server time.",
            date = "2012-08-24T02:45:32-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30535#comments:id=1703684",
        },
        {
            id = 2002808,
            score = 3,
            author = "SpakyTwo",
            text = "During this quest chain. You will be given a quest to plant https://www.wowhead.com/item=74843, then you may want to plant the next item in the \"votes\" list so that you won't have to wait for the dailes to reset (https://www.wowhead.com/item=74841 x2) and a soon as you hit 90 can start in earnest. It took me two days on a human to get exalted, with doing a Scenario, Heroic Scenario, and a Heroic Dungeon with Tillers selected as my preferred rep.\n\n I have compiled the five people and and what they want you to plant below.\n\nFor example: When you go to plant the https://www.wowhead.com/item=74843 for Gina, you also plant the https://www.wowhead.com/item=74841 x2 for Mung Mung. This will make it so that as soon as you hit honored you can do Mung Mung's questline all at once and not have to wait until the next day. If you have bought the https://www.wowhead.com/item=93226, you should be just over honored when you get to this quest.\n\nThe five people and their veggies to plant and their votes are as follows (including this quest)\n\n[quest=31945 ]\n\nPlant and harvest 1 https://www.wowhead.com/item=74843, then deliver 5 Scallions to Gina Mudclaw.\n\nhttps://www.wowhead.com/quest=31946 (Requires level 90)\n\nPlant and harvest 2 https://www.wowhead.com/item=74841, then deliver 10 Juicycrunch Carrots to Mung-Mung.\n\nhttps://www.wowhead.com/quest=31947\n\nPlant and harvest 3 https://www.wowhead.com/item=74840, then deliver 15 Green Cabbages to Farmer Fung.\n\nhttps://www.wowhead.com/quest=31949\n\nPlant and harvest 3 https://www.wowhead.com/item=74846, then deliver 15 Witchberries to Nana Mudclaw.\n\nhttps://www.wowhead.com/quest=30527\n\nPlant and harvest 4 https://www.wowhead.com/item=74848, then deliver 20 Striped Melons to Farmer Yoon.",
            date = "2014-09-15T00:17:58-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30535#comments:id=2002808",
        },
        {
            id = 1911388,
            score = 2,
            author = "namilea",
            text = "Merchant greenfield will not sell me anything, he just says \"my seeds grow the best veggies in the valley. Guaranteed! I have the quest learn and grow, I've tilled my 2 plots but can't buy the seeds. I'm lvl 88, do I need to be 90 to buy seeds?",
            date = "2013-10-23T11:24:32-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30535#comments:id=1911388",
        },
        {
            id = 1918473,
            score = 1,
            author = "dusty103",
            text = "The questline begins at level 87, not 85.  You can only have 4 plots until you reach level 90, and no specialty seeds until you hit Revered.",
            date = "2013-11-15T07:37:02-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30535#comments:id=1918473",
        },
    },
    [30565] = {
        {
            id = 1974586,
            score = 3,
            author = "Solstrike",
            text = "What are Grimleers?  Another word for a tribe of Hozen, or some kind of strange typo?  The word doesn't appear anywhere at all other than in this quest text.",
            date = "2014-06-24T00:47:45-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30565#comments:id=1974586",
        },
        {
            id = 1729968,
            score = 1,
            author = "Oxygoron",
            text = "It would appear that if you reach the border between the Bamboo Wilds and the Den of Sorrow, the Hozen Ambushers will appear as if they are there, but if you try to approach them, they will disappear, and the wildlife that occupied this space earlier will re-appear. As a warrior, this was a tad annoying, but simply pulling the Hozen back into the Bamboo Wilds will solve it.",
            date = "2012-10-03T12:22:35-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30565#comments:id=1729968",
        },
    },
    [30568] = {
        {
            id = 1753063,
            score = 15,
            author = "kayakira1",
            text = "You have to speak too Amber Kearnen first too defeat the captured Hozen.\n\nHe comes out his cage after you spoke to her and you will be able to attack him.",
            date = "2012-10-29T07:56:02-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30568#comments:id=1753063",
        },
        {
            id = 1727778,
            score = 12,
            author = "Shashos",
            text = "If you're not keen on PvP, be aware that challenging and fighting the Pearlfin Recruit will flag you. I didn't notice until I was leaving the village and started being chased by an opposite faction player.\n\nThere's no notice that this will happen in the quest text either, so keep this in mind if you decide to accept and complete this quest.",
            date = "2012-10-01T18:35:38-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30568#comments:id=1727778",
        },
        {
            id = 1773146,
            score = 10,
            author = "Kadenzza",
            text = "It appears that the quest no longer flags you for PvP when you duel the Pearlfin Recruit.",
            date = "2012-12-01T14:32:50-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30568#comments:id=1773146",
        },
        {
            id = 1718969,
            score = 6,
            author = "Duerma",
            text = "The guys to heal are to the east of the village, just up the hill past Mishka around a small pond. Amber & the hozen fighting pit are just northwest of the village.",
            date = "2012-09-25T16:24:11-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30568#comments:id=1718969",
        },
        {
            id = 1835595,
            score = 4,
            author = "994861",
            text = "I am trying to turn in this quest, but I don't see anyone to turn it in to. I've reloaded my UI just in case it was a glitch, but still no quest taker. My map shows that there should be someone in Pearlfin Village by the rafts at the water's edge.",
            date = "2013-03-28T01:12:11-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30568#comments:id=1835595",
        },
    },
    [30569] = {
        {
            id = 1720451,
            score = 2,
            author = "Whiterock",
            text = "The Road to Kun-lai Quest Tree From Whiterock\n[pre][ins]#[/ins])Robbing Robbers of Robbers (http://www.wowhead.com/quest=31286) [ins]#[/ins])Educating Saurok (http://www.wowhead.com/quest=31287) [ins]#[/ins])The Spring Drifter (http://www.wowhead.com/quest=31285)(The Veiled Stair)\n\n[ins]#[/ins])The Road to Kun-Lai (http://www.wowhead.com/quest=31254){H} (http://www.wowhead.com/quest=31255)(Multiple zones)\n\n[ins]+[/ins])Hit Medicine (http://www.wowhead.com/quest=30460) [ins]+[/ins])All of the Arrows (http://www.wowhead.com/quest=30459) [ins]+[/ins])Call Out Their Leader (http://www.wowhead.com/quest=30457)\n ├─────┬────────┴───────────────────┘         ||\n ||     ||                                    Turnabout (http://www.wowhead.com/quest=30670)*\n || The Defense of Shado-Pan Fallback (http://www.wowhead.com/quest=30665)*\n ||\n ├──────────────────────────────────────┐\na)Admiral Taylor has Awakened (http://www.wowhead.com/quest=30506)(A,v2 (http://www.wowhead.com/quest=30507),v3 (http://www.wowhead.com/quest=30508)) a)General Nazgrim has Awakened (http://www.wowhead.com/quest=30509)(H,v2 (http://www.wowhead.com/quest=30510),v3 (http://www.wowhead.com/quest=30511))\nb)Westwind Rest (http://www.wowhead.com/quest=30512)(A)                     b)Eastwind Rest (http://www.wowhead.com/quest=30513)(H)\n ||                   ┌──────────────────┘\nb)Challenge Accepted (http://www.wowhead.com/quest=30514){H} (http://www.wowhead.com/quest=30515)\n || ||                 └───────────┬>c)Blue Dwarf Needs Food Badly (http://www.wowhead.com/quest=30583)(A)\n || ├>c)Round 'Em Up (http://www.wowhead.com/quest=30575){H} (http://www.wowhead.com/quest=31256)           ├>c)Best Meals Anywhere! (http://www.wowhead.com/quest=31251)(H)\n || └>d)Profiting off of the Past (http://www.wowhead.com/quest=30595) └>d)Deanimate the Reanimated (http://www.wowhead.com/quest=30593){H} (http://www.wowhead.com/quest=30594)\n ||\n ├───────────────────────────┐\nd)Mogu? Oh No-gu