    [30581] = {
        {
            id = 1695393,
            score = 34,
            author = "retro",
            text = "The Cast Iron Pot (http://mop.wowhead.com/item=80230) is obtained from within the house on the farm, guarded by Cookie McYaungol (http://mop.wowhead.com/npc=59645)\n\nThe Root Vegetable (http://mop.wowhead.com/item=80227) is obtained in 2 ways, Wascally Wirmen (http://mop.wowhead.com/npc=59655) drop them in larger numbers (4+), or simply from picking them from the objects in the ground (1 per object ).",
            date = "2012-08-02T18:47:58-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30581#comments:id=1695393",
        },
        {
            id = 1764902,
            score = 13,
            author = "onlymeaz",
            text = "This quest is pretty funny if you watch your chat window.  The house is at 60/88 inside Chow Farmstead and the pot is right inside on the right being used by \"Cookie McYaungol\".  Cookie says a bunch of funny stuff but what had me really laughing was him saying \"this stew needs salt....and people meatballs.....bork! bork! bork!\" an obvious reference to the Swedish Chef from Sesame Street.",
