    [30589] = {
        {
            id = 1663888,
            score = -1,
            author = "Krastopic",
            text = "After you pick up the quest - follow the path west.  If you stay on the path until you cross the river, you will avoid the tigers.  You will continue west after you cross the river and you will see a Horde banner where Makael Bay will be.  He is a Goblin.\n\nIf you are careful on approach you can avoid the Darkened Horrors (aka Lizard men) patroling the area.",
            date = "2012-05-07T13:22:11-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30589#comments:id=1663888",
        },
        {
            id = 1912025,
            score = -3,
            author = "460595",
            text = "Stupid Michael Bay's gonna call the TMNT aliens! STUPID JERK",
            date = "2013-10-25T17:53:33-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30589#comments:id=1912025",
        },
    },
    [30590] = {
        {
            id = 1933988,
            score = 4,
            author = "780904",
            text = "Just a quick note: Doing these quests does not point you torwards picking horde when you get to pick faction.\nThis is just a part of a pretty big chain quest where you'll help both Alliance and Horde, and in the end of the chain you'll be able to chose which one to represent.",
            date = "2014-01-12T17:21:10-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30590#comments:id=1933988",
        },
        {
            id = 1663893,
            score = 3,
            author = "Krastopic",
            text = "Make sure to pick up the quest \"Evil from the Seas\" since you will be attacked by the Darkened Horrors you have to kill for that quest while completing this one.  Might as well get credit for the kills.\n\nYou will find packs of explosives in the immediate area, target them until the gear symbol shows up - them click.",
            date = "2012-05-07T13:30:46-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30590#comments:id=1663893",
        },
        {
            id = 1888790,
            score = 3,
            author = "1015212",
            text = "Hehe, has anyone else noticed that you have to pick up explosives  for Makael Bay. Well played Blizzard, well played.",
            date = "2013-08-21T02:46:34-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30590#comments:id=1888790",
        },
        {
            id = 1694426,
            score = 1,
            author = "455621",
            text = "If you can't find this quest, questgiver is in wrong phase. Leave the area of the camp and return.",
            date = "2012-07-31T10:12:11-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30590#comments:id=1694426",
        },
        {
            id = 1699123,
            score = 1,
            author = "dworkinss",
            text = "Remind that you can not obtain next quest until you're level 11. (It was trouble for me looking for entire map for next quest)",
            date = "2012-08-12T16:05:51-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30590#comments:id=1699123",
        },
    },
    [30591] = {
        {
            id = 1663884,
            score = 1,
            author = "Krastopic",
            text = "Very simple quest, the Tigers surround the quest area.  Kill 6 and you have completed the task.  The Tiger cubs do not count.\n\nTake care in that there are some areas where there will be three concealed tigers.  Make sure you are at full health before all three pounce on you.\n\nMake sure you are also doing the quest- \"Stocking Stalks\" as they will be all over the area where the tigers are.",
            date = "2012-05-07T13:12:47-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30591#comments:id=1663884",
        },
        {
            id = 1782069,
            score = 1,
            author = "1026168",
            text = "Wanna get this quest done in a jiffy? Find and attack one https://www.wowhead.com/npc=56174.",
            date = "2012-12-15T20:48:19-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30591#comments:id=1782069",
        },
        {
            id = 2345203,
            score = 1,
            author = "1653133",
            text = "\"Branches\" off into [quest=29795 domain=www]",
            date = "2016-06-26T20:33:49-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30591#comments:id=2345203",
        },
    },
    [30592] = {
        {
            id = 1720579,
            score = 42,
            author = "whsocko",
            text = "You have to wait for the convoy to spawn, which happens at One Keg.  Once it spawns, you'll see a yellow dot on the map which is the convoy's current location.  It will travel west, and groups of mobs will spawn and try to kill the convoy members.  You can heal the convoy leader, who is the only one fighting with you.  The escort ends about halfway to Kota Basecamp.",
            date = "2012-09-26T17:28:03-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30592#comments:id=1720579",
        },
        {
            id = 1913101,
            score = 36,
            author = "1186359",
            text = "Found a group of them frozen with fear, killed the Broketooth spear-heaverthat were attacking them, still frozen, then i started killing the broketooth tosser on the path in front of them and the one in the field next to them, and they unfroze.",
            date = "2013-10-29T14:17:00-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30592#comments:id=1913101",
        },
        {
            id = 3200553,
            score = 21,
            author = "Rayner",
            text = "If your Grummles are feared (You can find your Grummles on the map) go along the path a little and find the first group of Broken tooth spear-heavers. Kill all of them and that should help you along.\nAlso, if you have Warmode on, Be careful, you pass the Sha of Anger, and People from Both Factions show up.\nI had to do this twice because a High leveled person thought killing a 85 questing character is fair. (I know, don't go into Warmode if you don't want to PvP.)",
            date = "2020-04-17T22:03:46-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30592#comments:id=3200553",
        },
        {
            id = 1735688,
            score = 19,
            author = "KingChicken",
            text = "I waited quite a while for the convoy to come to One Keg.  I took a walk down the trail to the Waystation and found a single Trail Packer stuck with fear.  He was not going to move no matter how many Hozen you killed that were attacking him.\n\nYou have to let him be killed, don't try and make him move by killing off the attackers, it won't work.  Once he dies, the convoy resets at One Keg.",
            date = "2012-10-08T13:13:14-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30592#comments:id=1735688",
        },
        {
            id = 1725164,
            score = 13,
            author = "491283",
            text = "Note that the Sha of Anger will occasionally spawn near this route. If there is a group attacking it, the Sha will deal 80k damage every few seconds to a random target - a target not necessarily in combat with it. In other words, if you're escorting the grummles on this quest while the Sha is being attacked nearby, get ready to fail.",
            date = "2012-09-29T20:48:39-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30592#comments:id=1725164",
        },
    },
    [30593] = {
        {
            id = 1812517,
            score = 7,
            author = "553717",
            text = "Fortunately, Torquezzz was mistaken, they do not have to be killed while animated... simply jog around attacking those that have recently turned back to stone (this way you'll have the most time to kill them before they reanimate) and avoid the live ones.  I killed 75% of mine while in stone form.   Live ones do significant damage if you are in quest gear and at level (87, 88).",
            date = "2013-02-11T21:54:12-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30593#comments:id=1812517",
        },
        {
            id = 1727384,
            score = 4,
            author = "628557",
            text = "For this quest you need to kill the Terracotta statues located south of Moguija. They have two \"cycles\". They are frozen, passive mobs, but if a Mogu uses it magic on it (look at the shadow bolts coming from the top of the mountain) they will become hostile mobs, and they will deal 200% damage.\nI recommend doing this quest with Profiting off of the Past (www.wowhead.com/quest=30595).\nAlso, be on lookout for Terracotta Head (http://www.wowhead.com/item=86427) to get free 100g",
            date = "2012-10-01T11:49:06-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30593#comments:id=1727384",
        },
        {
            id = 5871165,
            score = 4,
            author = "zenithstorm",
            text = "If you see a bunch of blood elves in the quest area, instead of the expected mogu statues, you're probably in the middle of the Landfall campaign questline, and need to finish the quests on that first to switch the quest mobs in the area back for this quest.\n\nI had to complete this and the other quests after it: [quest=32193 domain=www]",
            date = "2024-05-31T16:24:27-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30593#comments:id=5871165",
        },
        {
            id = 1720432,
            score = 2,
            author = "Whiterock",
            text = "The Road to Kun-lai Quest Tree From Whiterock\n[pre][ins]#[/ins])Robbing Robbers of Robbers (http://www.wowhead.com/quest=31286) [ins]#[/ins])Educating Saurok (http://www.wowhead.com/quest=31287) [ins]#[/ins])The Spring Drifter (http://www.wowhead.com/quest=31285)(The Veiled Stair)\n\n[ins]#[/ins])The Road to Kun-Lai (http://www.wowhead.com/quest=31254){H} (http://www.wowhead.com/quest=31255)(Multiple zones)\n\n[ins]+[/ins])Hit Medicine (http://www.wowhead.com/quest=30460) [ins]+[/ins])All of the Arrows (http://www.wowhead.com/quest=30459) [ins]+[/ins])Call Out Their Leader (http://www.wowhead.com/quest=30457)\n ├─────┬────────┴───────────────────┘         ||\n ||     ||                                    Turnabout (http://www.wowhead.com/quest=30670)*\n || The Defense of Shado-Pan Fallback (http://www.wowhead.com/quest=30665)*\n ||\n ├──────────────────────────────────────┐\na)Admiral Taylor has Awakened (http://www.wowhead.com/quest=30506)(A,v2 (http://www.wowhead.com/quest=30507),v3 (http://www.wowhead.com/quest=30508)) a)General Nazgrim has Awakened (http://www.wowhead.com/quest=30509)(H,v2 (http://www.wowhead.com/quest=30510),v3 (http://www.wowhead.com/quest=30511))\nb)Westwind Rest (http://www.wowhead.com/quest=30512)(A)                     b)Eastwind Rest (http://www.wowhead.com/quest=30513)(H)\n ||                   ┌──────────────────┘\nb)Challenge Accepted (http://www.wowhead.com/quest=30514){H} (http://www.wowhead.com/quest=30515)\n || ||                 └───────────┬>c)Blue Dwarf Needs Food Badly (http://www.wowhead.com/quest=30583)(A)\n || ├>c)Round 'Em Up (http://www.wowhead.com/quest=30575){H} (http://www.wowhead.com/quest=31256)           ├>c)Best Meals Anywhere! (http://www.wowhead.com/quest=31251)(H)\n || └>d)Profiting off of the Past (http://www.wowhead.com/quest=30595) └>d)Deanimate the Reanimated (http://www.wowhead.com/quest=30593){H} (http://www.wowhead.com/quest=30594)\n ||\n ├───────────────────────────┐\nd)Mogu? Oh No-gu! (http://www.wowhead.com/quest=30619){H} (http://www.wowhead.com/quest=30620)    e)Trouble on the Farmstead (http://www.wowhead.com/quest=30569){H} (http://www.wowhead.com/quest=30570)\n ||                        /     \\\n ||       e)Farmhand Freedom (http://www.wowhead.com/quest=30571)     e)... and the Pot, Too!  (http://www.wowhead.com/quest=30581)\n ||                       └─┬───┬─┘\n || e)Back to Westwind Rest (http://www.wowhead.com/quest=31252)(A) e)Back to Eastwind Rest (http://www.wowhead.com/quest=31253)(H)\n ├─────────────────────────┴───┴─┬───────────────────┐\n ||                               ||                   ||\nf)In Tents Channeling (http://www.wowhead.com/quest=30652){H} (http://www.wowhead.com/quest=30657)        f)Barrels of Fun (http://www.wowhead.com/quest=30651){H} (http://www.wowhead.com/quest=30656) f)Pandaren Prisoners (http://www.wowhead.com/quest=30650){H} (http://www.wowhead.com/quest=30655)\nf)The Ordo Warbringer (http://www.wowhead.com/quest=30660){A2 (http://www.wowhead.com/quest=30662),H1 (http://www.wowhead.com/quest=30661),H2 (http://www.wowhead.com/quest=30663)}  ||                   ||\n ||                           └─┬─┴─────────────────┬─┘\nMuskpaw Ranch (http://www.wowhead.com/quest=31456){H} (http://www.wowhead.com/quest=31457)*              ├>The Shado-Pan (http://www.wowhead.com/quest=31455){H} (http://www.wowhead.com/quest=31453)* ├>The Missing Merchant (http://www.wowhead.com/quest=31452){H} (http://www.wowhead.com/quest=31451)*\n                               └>Beyond the Wall (http://www.wowhead.com/quest=31695)*  └>Cho's Missive (http://www.wowhead.com/quest=31460){H} (http://www.wowhead.com/quest=31459)*\nLegend:\n+ means Can start anytime, prequests not needed.\n# means Other Zones\n(A)/(H) means Alliance/Horde only.\n{H} means Quest Have Horde Variant, click {H} for it.\n* means another Quest Tree.[/pre]\nAdditionall info:\n\nYes, Shado-pan questline have such weird prequests :D\nAwakened quests have 3 version of quests each starting from NPC that gave you previous quests.\nOrdo Warbringer have quest that starts via pop-up after Channelers and backup from Taylor/Nazgrim if you abandon first.",
            date = "2012-09-26T15:50:09-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30593#comments:id=1720432",
        },
        {
            id = 1734455,
            score = 2,
            author = "351338",
            text = "Keep an eye out for which ones are statues, and which ones aren't. Look out for the effect that indicates which ones are gonna stop being statues.\n\nMages: You can polymorph them, even as statues for STONE SHEEP! :D. But seriously - if one of them becomes reanimated unexpectedly, it's a good idea to sheep it until you can deal with it. Assuming the polymorph isn't broken, it'll eventually turn back to stone.",
            date = "2012-10-07T11:42:49-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30593#comments:id=1734455",
        },
    },
    [30594] = {
