        {
            id = 2188179,
            score = 7,
            author = "836908",
            text = "This quest gives a 24 slot bag. Totally worth working the grummel Q line.",
            date = "2015-05-27T13:28:33-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30600#comments:id=2188179",
        },
        {
            id = 3254442,
            score = 5,
            author = "scharky",
            text = "if you're after the bag, remember you have to do all the quests in the camp (except the one inside the inn). that'll open up the short and sweet quest chain leading to the bag.\n\nthe camp is The Grummle Bazaar in Kunlai Summit, /way 65.00, 60.78 more or less.",
            date = "2020-11-25T05:33:25-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30600#comments:id=3254442",
        },
        {
            id = 1903081,
            score = 2,
            author = "141968",
            text = "There are a few packs around the camp - almost always an NPC fight to get one.   There are usually some in the huts - again, always a fight.   There are some also in the cave where the quest is to put Kak-Kak on his alter down in the bottom of the cave.",
            date = "2013-09-26T18:45:28-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30600#comments:id=1903081",
        },
    },
    [30601] = {
        {
            id = 1725123,
            score = 45,
            author = "Nightmyst",
            text = "the entrance is at (59,52) for those that get lost easily like i do :)",
            date = "2012-09-29T20:15:53-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30601#comments:id=1725123",
        },
        {
            id = 3174059,
            score = 18,
            author = "OptikRise",
            text = "The cave entrance is /way 59.55, 52.93 Howlingwind Cavern",
            date = "2019-11-28T11:07:54-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30601#comments:id=3174059",
        },
        {
            id = 1693798,
            score = 13,
            author = "Balgair",
            text = "It's worth leaving rescuing these grummles until after you've done the other two quests in this cave, or at least cleared your way in by some way, since they follow you and \"help\" you fight, or in other words, aggro everything. Given this cave has a lot of sprites hiding in piles of snow, which tend to cluster together, and every grummle goes for a different snow pile (and none of them can solo the sprites they dig out), this can quickly become one big mess if you aren't a strong aoe class.",
            date = "2012-07-29T21:21:28-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30601#comments:id=1693798",
        },
        {
            id = 1723125,
            score = 10,
            author = "Whiterock",
