    [30602] = {
        {
            id = 1721132,
            score = 15,
            author = "Eielais",
            text = "If you killed Mo Mo and got The Broketooth Ravage before this quest you have to drop it, other wise you won't be able to free him.",
            date = "2012-09-27T03:04:40-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30602#comments:id=1721132",
        },
        {
            id = 1737880,
            score = 12,
            author = "151802",
            text = "You have to do this:\n\n\"rescue\" Brother Rabbitsfoot\" first. He's @ 49,70\nYou then get the quest \"The Broketooth Ravage\". Kill Mo MO @ 52,70 (cave up the hill)\nTurn in BOTH quests @ 51,67\n\nYou may see a quest marker turn-in @ 45,63....this is false...51,67 is your target!",
            date = "2012-10-10T20:58:23-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30602#comments:id=1737880",
        },
        {
            id = 1760329,
            score = 9,
            author = "whsocko",
            text = "This quest will bug every time under the following conditions:\n\n- you are grouped\n- a member of your group rescues Brother Rabbitsfoot, then shares the quest he gives afterwards\n\nIf this happens, any group member who accepts the new quest will not be able to finish The Rabbitsfoot unless they first abandon the new quest (The Broketooth Ravage).\n\nI logged and relogged multiple times, deleted my WTF folder, etc. before figuring out what had happened.  Hope this helps someone.",
            date = "2012-11-10T12:37:10-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30602#comments:id=1760329",
        },
        {
            id = 1719773,
            score = 5,
            author = "trollied",
            text = "He's hanging upside-down from a tree at 49.0,70.3. He also gives another quest [quest=30603 domain=www]",
            date = "2012-09-26T07:06:57-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30602#comments:id=1719773",
        },
        {
            id = 1797697,
            score = 3,
            author = "fxkiller",
            text = "Cave entrance : 48,73\n\nJust kill Momo and loot it ;)",
            date = "2013-01-13T05:50:47-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30602#comments:id=1797697",
        },
    },
