    [30607] = {
        {
            id = 2447350,
            score = 161,
            author = "BlackHalo66",
            text = "I was having trouble getting the key to work when clicking on the ball. The clickable area is not where the gears appear, which is above the ball.\n\nIf you stand between the baskets to the left of Old Poot Poot and mouse over the ball's left outer edge, you'll find the clickable area between 7 and 11 o'clock.",
            date = "2016-11-22T15:59:12-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30607#comments:id=2447350",
        },
        {
            id = 1719813,
            score = 42,
            author = "trollied",
            text = "The button (spinning gears) to release the NPC is well above his head.\n\nHe gives you a lift back up to the quest reward NPC ;)",
            date = "2012-09-26T07:45:07-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30607#comments:id=1719813",
        },
        {
            id = 1721762,
            score = 26,
            author = "1036438",
            text = "The Key drops off https://www.wowhead.com/npc=60090 who is walking back and forth in front of the Yeti so you don't have to fight random mobs until the key drops.\n\nOnce you have the key the gears to release the yeti are above his head. After he is free he will give you a ride back to the Waystation.",
            date = "2012-09-27T13:59:03-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30607#comments:id=1721762",
        },
        {
            id = 1804087,
            score = 14,
            author = "mariesgrdn",
            text = "Hozen Treasure Chest in the little alcove at (49.4,59.4) behind the yeti gave me a little more than 99 gold :)",
            date = "2013-01-25T16:39:11-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30607#comments:id=1804087",
        },
        {
            id = 2295649,
            score = 9,
            author = "kdegnan",
            text = "This has been probably the most hilarious quest ever to myself and my wife. My pet name for my wife is \"Little Poot Poot.\" To then see that my wife is unintentionally in game as \"Old Poot Poot\" and is basically a massive, horned Yeti was delightful. I showed this to her and she immediately took a picture with her phone and asked me for a screenshot to share - she's very happy with it, too.\n\nThat I then rode \"Old Poot Poot\" out of a cave on a wave of destruction was just icing. Good job, Blizzard. Well done.",
            date = "2016-01-06T23:19:11-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30607#comments:id=2295649",
        },
    },
