            score = 10,
            author = "drLeend",
            text = "Seems like since patch with N'Zoth assaults to do this quest you have to finish Mogu at the Gates (https://www.wowhead.com/quest=57067/mogu-at-the-gates) quest chain to be able to see Ruqin Yaungols, otherwise you'll see 120 lvl calfs only.",
            date = "2020-05-14T20:45:58-05:00",
