        },
        {
            id = 2153159,
            score = 5,
            author = "Takata",
            text = "For anyone wondering who doesn't know exactly where, it is located right in between the Yaungol Advance and One Keg. Not inside One Keg like I was thinking. On your minimap it will be called, The Grummel Bazar.  Don't need to escort any of those Grummels. Hope this helps anyone who's still having trouble finding the quest.",
            date = "2015-04-04T09:01:17-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30616#comments:id=2153159",
        },
    },
    [30617] = {
        {
            id = 1725071,
            score = 11,
            author = "515518",
            text = "The incense pretty much looks like thin sticks.  They can be found on the road.",
            date = "2012-09-29T19:33:42-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30617#comments:id=1725071",
        },
        {
            id = 1788127,
            score = 7,
            author = "sickbox",
            text = "Head west out of The Grummle  Bazaar down the road.  Incense sticks will be along the road to either side along with others that look to have been burnt all the way up to Onekeg.  You do not need to dismount to use them.",
            date = "2012-12-27T12:29:18-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30617#comments:id=1788127",
        },
        {
            id = 1842339,
            score = 7,
            author = "1104738",
            text = "I didn´t have to do the quest for continuing the chain. Didn`t find it so think it`s removed, can anyone confirm? It seems that removing the quest was the best thing to do since many people have struggled doing it :P",
            date = "2013-04-12T16:24:57-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30617#comments:id=1842339",
        },
        {
            id = 1730466,
            score = 4,
            author = "alessandrouw",
            text = "The spawn rate of these incenses are extremely low, and the quest area is so tiny that it's unbelieveable. Don't bother looking for it (as I did in the past 20 minutes, and I'm almost pulling my hair). Just camp one incense spawn and keep using it while you do something else outside WoW... Or pray that Blizzard improve this quest in the future.",
            date = "2012-10-03T21:17:30-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30617#comments:id=1730466",
        },
        {
            id = 2334762,
            score = 3,
            author = "elzzipilf",
            text = "Did all the quests in The Grummle Bazaar that send you to Fire Camp Ruqin to get this quest to show up. If it still isn't enough, try doing The Burlap Trail: To Burlap Waystation as well.",
            date = "2016-05-28T01:15:25-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30617#comments:id=2334762",
        },
    },
    [30618] = {
        {
            id = 1803874,
            score = 13,
            author = "55742",
            text = "Cave entrance is 59.6, 53",
            date = "2013-01-25T07:28:32-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30618#comments:id=1803874",
        },
        {
            id = 1849045,
            score = 10,
            author = "1117721",
            text = "I'mma just leave this here. Response from the forums I found helpful. I was able to complete this quest no problem.\n\nYou're in the wrong cave. There shouldn't be Hozen in there. The cave you want is below the banshee area and has sprites in it. It's called Howlingwind Cavern, I think. You should have two other quests along with collecting the supplies. One to rescue hiding grummle dudes and the other to collect Ji-Lu's lost items. All three quests are done in the same cave.\n\nGo to Onekeg and face the flightmaster. There is a path that leads up to the flightmaster's left. Follow that path. It's called Howlingwind Trail. That will take you to the correct cave.",
            date = "2013-05-01T19:35:50-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30618#comments:id=1849045",
        },
        {
            id = 1876132,
            score = 7,
            author = "eisenkrieger",
            text = "I found a whole bunch of supplies at 55.2, 29.0, inside the cavern.  I hope that helps.",
            date = "2013-07-12T12:24:48-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30618#comments:id=1876132",
        },
        {
            id = 1919079,
            score = 7,
            author = "Kirska",
            text = "I couldn't find any supplies at all, gave up and turned in the other two quests. I came back to the sprite cave in a last ditch effort after turning in the other two and the supplies were everywhere, very easy to find. Not sure if it was just a coincidence but maybe this will help someone.",
            date = "2013-11-17T10:11:20-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30618#comments:id=1919079",
        },
        {
            id = 1723121,
            score = 3,
