    [30621] = {
        {
            id = 1784834,
            score = 42,
            author = "179907",
            text = "If you are having trouble finding the cave entrance it is at...\n\n59.5, 52.9",
            date = "2012-12-20T20:03:58-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30621#comments:id=1784834",
        },
        {
            id = 2508732,
            score = 32,
            author = "Alanor",
            text = "Ok, I had a hell of a time tracking this quest chain back to the quest I didn't do.. which was this one. Be aware that if you look for this quest you will not see it on the map unless you enter the One Keg's Tavern. I flew over the tavern, no sign of a quest.  I must say that I am 110 catching up quests I missed, but it may be an issue for lower level players as well. Just to make sure you don't get mad finding what quest you skipped in the quest chain (like I did).",
            date = "2017-07-18T17:03:49-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30621#comments:id=2508732",
        },
        {
            id = 1723137,
            score = 6,
            author = "Whiterock",
            text = "Two Empires Quest Tree From Whiterock\n[pre]Barrels of Fun (http://www.wowhead.com/quest=30651){H} (http://www.wowhead.com/quest=30656)* Pandaren Prisoners (http://www.wowhead.com/quest=30650){H} (http://www.wowhead.com/quest=30655)* The Ordo Warbringer (http://www.wowhead.com/quest=30660){A2 (http://www.wowhead.com/quest=30662),H1 (http://www.wowhead.com/quest=30661),H2 (http://www.wowhead.com/quest=30663)}*\n                \\      ||        ┌─────────┘\n                [ins]S[/ins])Cho's Missive (http://www.wowhead.com/quest=31460){H} (http://www.wowhead.com/quest=31459)\n                [ins]+[/ins])Path Less Traveled (http://www.wowhead.com/quest=30999)\n                /      ||           └─────┐\na)Resupplying One Keg (http://www.wowhead.com/quest=30618) a)Instant Courage (http://www.wowhead.com/quest=30601) a)They Stole My Luck! (http://www.wowhead.com/quest=30621)\n                \\      ||                 ||\n                b)Comin' Round the Mountain (http://www.wowhead.com/quest=30487)\n                b)One Traveler's Misfortune (http://www.wowhead.com/quest=30683)\n                b)Seeker's Folly (http://www.wowhead.com/quest=30684)\n                /               \\\nd)It Was Almost Alive (http://www.wowhead.com/quest=30797)           c)The Tongue of Ba-Shon (http://www.wowhead.com/quest=30829)\nf)The Tomb of Shadows (http://www.wowhead.com/quest=30799)           d)Staying Connected (http://www.wowhead.com/quest=30795)\ng)Breaking the Emperor's Shield (http://www.wowhead.com/quest=30798) d)An End to Everything (http://www.wowhead.com/quest=30796)\nh)Stealing Their Thunder King (http://www.wowhead.com/quest=30800)\nh)Lessons from History (http://www.wowhead.com/quest=30801)\nh)Chasing the Storm (http://www.wowhead.com/quest=30802)\ni)Fisherman's Tale (http://www.wowhead.com/quest=30935)────────────┬─>j)Make A Fighter Out of Me (http://www.wowhead.com/quest=30942)\n ||  ||    ||                    ||                 ||\n ||  ||   i)It Takes A Village (http://www.wowhead.com/quest=30944) j)Handle With Care (http://www.wowhead.com/quest=30943) ||\n ||  ||                       \\ ||                 ||\n || j)What's Yours Is Mine (http://www.wowhead.com/quest=30945)──>k)Enemies At Our Door (http://www.wowhead.com/quest=31011)\n ||                          k)Revelations (http://www.wowhead.com/quest=30946)\n[ins]S[/ins])Checking In (http://www.wowhead.com/quest=30816)               l)Prophet Khar'zul (http://www.wowhead.com/quest=31228)\n[ins]+[/ins])Emergency Care (http://www.wowhead.com/quest=30794)\n ||        \\    └───────────────┐\nm)Justice (http://www.wowhead.com/quest=30805) m)The Scent of Life (http://www.wowhead.com/quest=30806) n)By the Falls, For the Fallen (http://www.wowhead.com/quest=30807)\n ||        /           ┌────────┘\no)Preparing the Remains (http://www.wowhead.com/quest=30819)\np)A Funeral (http://www.wowhead.com/quest=30820)\n\nLegend:\nS means Skippable\n+ means Can start anytime, prequests not needed.\n{H} means Quest Have Horde Variant, click {H} for it.\n* means another Quest Tree.[/pre]",
            date = "2012-09-28T13:12:34-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30621#comments:id=1723137",
        },
        {
            id = 1784790,
            score = 2,
            author = "Noshbox",
            text = "The cave itself is the same layout as the Yeti cave in Winterspring, brought back some fond memories of framing leather haha.\n\nIf you make your way to the end of the cave as well, I noticed a chest at the end I could open, had a tidy sum of 104g in there. Could be worth killing a few extra mobs for this purse, they seem to drop a decent amount of wool and spirit of harmomies too :)",
            date = "2012-12-20T18:45:22-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30621#comments:id=1784790",
        },
        {
            id = 1879324,
            score = 2,
            author = "1133827",
            text = "Unlike every other Mob-Item-gathering quest... you cannot AoE a bunch of these buggers at once hoping to get all the items.  AoE'd 11 of the sprites and got 6 of the same quest item.",
            date = "2013-07-21T14:29:31-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30621#comments:id=1879324",
        },
    },
    [30622] = {
        {
            id = 1731858,
            score = 9,
            author = "257700",
            text = "Like lordcanyon said, you need to complete the chain ending with Warn Stoneplow (http://www.wowhead.com/quest=30360) in Krasarang Wilds.",
            date = "2012-10-05T02:58:21-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30622#comments:id=1731858",
        },
        {
            id = 1685358,
            score = 8,
            author = "kothar",
            text = "He is around the S in Stoneplow.  Took me forever to find him as wow had him at the wrong location.",
            date = "2012-07-07T00:12:04-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30622#comments:id=1685358",
        },
        {
            id = 1722961,
            score = 5,
            author = "Shamazon",
            text = "When doing this quest, you can go and find a group of friendly NPC's fighting the Ik'thalliks and just aoe near them to get the kills on the nearby Ik'thalliks. Even if one of the Ik'thalliks are less than quarter of their maximum health, if you can quickly damage them you will get the kill!",
            date = "2012-09-28T10:09:20-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30622#comments:id=1722961",
        },
        {
            id = 1736910,
            score = 1,
            author = "skadimundr",
            text = "I wasn't able to get credit from killing the mobs the NPCs were attacking, and I kept aggroing way too many mantids and dying. Near the southern edge of the town (16.6, 60) there's a field with several mantids which can be engaged and pulled away from the others using throw or some other ranged pull/attack.",
            date = "2012-10-09T19:41:54-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30622#comments:id=1736910",
        },
        {
            id = 1744111,
            score = 1,
            author = "153710",
            text = "Another spot at 15, 55 for easy kills NPC vs Mob action. Tag and collect.\n\nYou can also kite the Sha's that come from the commanders to these NPC spots and they will attack it.",
            date = "2012-10-17T13:54:58-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30622#comments:id=1744111",
        },
    },
    [30623] = {
        {
            id = 1722238,
            score = 12,
            author = "eddyjr",
            text = "Works best on Ik'thik Wing Commanders.  The ones casting a spell on the houses.  You just use the item on them and a little manifestation pops out.",
            date = "2012-09-27T22:45:08-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30623#comments:id=1722238",
        },
        {
            id = 1721909,
            score = 9,
            author = "Sunbendyr",
            text = "The mask has to be used on a mantid commander afflicted by fear, specifically. It will be a buff on it. Get close enough for the mask to be usable on it, you do not have to be in combat. After you right click on the mask in your bag (using the icon in the game's objective log didn't work for me, maybe an addon issue), the manifestation of fear will spawn, kill that. Watch out for the manifestation's channeled spell, it does nasty cone damage that ate 1/4 of my health. After killing the manifestation, the mantid commander flies away and you get credit.",
            date = "2012-09-27T17:24:58-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30623#comments:id=1721909",
        },
        {
            id = 1723808,
            score = 2,
            author = "515518",
            text = "It only works on Ik'thik Wing Commanders.  When you highlight them make sure they have the fear buff, its a purple icon of a sad face (weird way to describe it I know).  Use Ken-Ken's mask from your inventory and fight Manifestation of Fear to get credit.\n\nThe Commanders are elites btw.",
            date = "2012-09-29T00:18:40-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30623#comments:id=1723808",
        },
        {
            id = 1797030,
            score = 2,
            author = "Partyrocked",
            text = "Please tell me, WHAT ABOUT the fact that Ken-Ken's mask seems to automagically apply itself only to the original user? What about the fact that it has a 20 minute cooldown?\n\nYou are using the wrong mask, the mask you're talking about is a quest Reward https://www.wowhead.com/item=88580. The one you should be using is a quest item, highlighted in yellow https://www.wowhead.com/item=80337. Hope that clears it up.",
            date = "2013-01-12T02:39:53-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30623#comments:id=1797030",
        },
        {
            id = 1787001,
            score = 1,
            author = "901632",
            text = "I have found a good way to help with this quest , you get 3 quests at the same time involving the mantid at stoneplow , whilst delivering the beer ( other quest ) simply look for mantid commanders that are real close to the people you are delivering beer to , and apply the mask.\nthen simply pull the aberration that spawns to the people and they will help you to kill it :)",
            date = "2012-12-24T18:23:58-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30623#comments:id=1787001",
        },
    },
    [30624] = {
        {
            id = 1725324,
            score = 8,
            author = "hejiann",
            text = "Some comments when you deliver...\n\nCrane Wing Priests--\nKoro Mistwalker: Ah...beer. Just what my men needed. Thank you, [name].\n\nShado-pan--\nFo Sho Knucklebump: First we get into a fight, and then someone brings us beer! Can today get any better?\n\nNight Elf Settlers--\nLyalia: Beer delivery, in the middle of a battlefield? Perhaps Pandaria will make a good home after all...\n\nI missed what Zhu's Wardens dialogue was when delivered, sorry.",
            date = "2012-09-30T00:17:43-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30624#comments:id=1725324",
        },
        {
            id = 1727898,
            score = 5,
            author = "dpacman",
            text = "Completed the quest no problem; but Mudmug is still following me.",
            date = "2012-10-01T20:36:15-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30624#comments:id=1727898",
        },
        {
            id = 1750774,
            score = 3,
            author = "Malinke",
            text = "I somehow lost mudmug during this quest and couldnt deliver the final lot of beer, but you can jsut run back to him in the town and and get him to come with you again, no need to drop the quest.",
            date = "2012-10-26T08:53:27-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30624#comments:id=1750774",
        },
        {
            id = 1761068,
            score = 3,
            author = "Moneyshot",
            text = "I did the quest without a problem but Mudmug still followed me while I did the five student quest. So I went into the Dread Wastes and he disappeared.\n\nHope this is helpful.",
            date = "2012-11-11T20:33:52-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30624#comments:id=1761068",
        },
        {
            id = 1825907,
            score = 2,
            author = "lionsofmercy",
            text = "Stay out of combat if possible--those damn kegs block your vision, which can be a pain if you get double-jumped; you can make fairly wide end runs around the mantid.\n\nAlso, just running near the groups will deliver the beer automatically--don't bother trying to interact with them.\n\nLook for pandaren in combat; the night elves are on catback.",
            date = "2013-03-10T08:15:44-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30624#comments:id=1825907",
        },
    },
    [30625] = {
        {
            id = 1719054,
            score = 263,
            author = "shao",
            text = "you need to find the students, which roam around, on the map. They should call out to you if you get close to them but generally look for big groups of NPCs (enemy, and friendly) fighting.\n\nThe students may actually be dead. one of them will still call out to you if you get within range (about 100yds). If they are dead kill the group of mobs near them (usually normals, and 1 elite) and they will all be revive automatically.\n\nafter which follow them on their tour to take down the 4 listed enemies.",
            date = "2012-09-25T18:03:26-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30625#comments:id=1719054",
        },
        {
            id = 1726907,
            score = 48,
            author = "776800",
            text = "Numerous people having problems with the last fight (Ik'thik Tendon Slicer) despawning.  While I was fighting the Ik'thik Incubator on the hill,  I pulled the Ik'thik Wing Commander near the Tendon Slicer up the hill and killed him BEFORE downing the Incubator.  The Tendon Slicer did not despawn.",
            date = "2012-10-01T03:48:19-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30625#comments:id=1726907",
        },
        {
            id = 1729944,
            score = 41,
            author = "619728",
            text = "If you're tracking your quest completion with an addon, and wondering why you don't have access to this quest like I was.. This quest only becomes available after you've completed the quest chains in Krasarang Wilds. The new phase for the area starts upon completing \"Warn Stoneplow (http://www.wowhead.com/search?q=Warn+Stoneplow).\"",
            date = "2012-10-03T11:46:48-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30625#comments:id=1729944",
        },
        {
            id = 1723406,
            score = 36,
            author = "jjanchan",
            text = "If you are looking for the students (either dead or alive) their names are as follows:\nClever Ashyo\nKang Bramblestaff\nKen-Ken\nXiao\nLin Tenderpaw\n\nThis is useful if you are using a targeting macro.  If they are dead, you must wait for them to respawn; once they have respawned, you need to follow them around.  You cannot unfortunately go hunting for the mobs you need and kill them on your own - they will not be attackable until engaged by the five students.  The markers on your map that indicate where each of the 4 mobs can be found ARE accurate - they may not be there because you have to wait till the troupe of students reaches that area.\n\nHope that helps!",
            date = "2012-09-28T18:22:27-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30625#comments:id=1723406",
        },
        {
            id = 1754795,
            score = 18,
            author = "Namand",
            text = "I found the students dead, I killed nearby mobs, students revived and went through all needed mobs without problem; fun.",
            date = "2012-11-01T05:53:19-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30625#comments:id=1754795",
        },
    },
    [30626] = {
        {
            id = 1729053,
            score = 4,
            author = "takethislife",
            text = "Leads to The Savior of Stoneplow (http://www.wowhead.com/quest=30627/the-savior-of-stoneplow)",
            date = "2012-10-02T18:11:21-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30626#comments:id=1729053",
        },
    },
    [30627] = {
        {
            id = 1722412,
            score = 72,
            author = "ssjheero",
            text = "I had thought my finest hour came when I harpooned onto the back of a drake and threw the riders off while over a mile off the ground (/quest=12886/the-drakkensryd).\n\nThen I punched my way out of a hundred foot tall bug that had destroyed an enormous stone wall.\n\nHoly crap. This entire quest chain was incredible.",
            date = "2012-09-28T01:37:21-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30627#comments:id=1722412",
        },
        {
            id = 1723692,
            score = 48,
            author = "Calomel",
            text = "A few of my guildmates had some trouble finding this quest and the chain that earns you the  Savior of Stoneplow (http://www.wowhead.com/achievement=7502) achievement. If you are having trouble finding it, speak with Guard Captain Oakenshield (http://www.wowhead.com/npc=57198) up on the grassy hill to the right of the break in the wall, who will give you the quest Students No More (http://www.wowhead.com/quest=30625).\n\nComplete that quest. It takes some time to follow the students around and kill what needs to be killed. It's basically an escort quest. Once you're done, return to Oakenshield and he will send you back to Loon Mai (http://www.wowhead.com/npc=56720) with the quest Retreat! (http://www.wowhead.com/quest=30626)\n\nBe prepared for a short RP conversation with the Hidden Master who is sitting off to the right of the blockade, after which he will give you The Savior of Stoneplow. Grats on your achievement!",
            date = "2012-09-28T22:49:54-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30627#comments:id=1723692",
        },
        {
            id = 1721190,
            score = 47,
            author = "Cakechart",
            text = "If Miss Fanny throws you next to the colossus, simply ride back to her original location and repeat the whole process. After 2 tries she threw me right and the colossus devoured me.\n\nBTW: It's no use killing the huge (level 90) colossus at the wall. The one you have to kill is level 87 and will be damaged by your focused strikes only... Just like the training for The Hidden Master quest line.",
            date = "2012-09-27T03:51:01-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30627#comments:id=1721190",
        },
        {
            id = 1757886,
            score = 43,
            author = "Praetextus",
            text = "I looked everywhere for the breadcrumb for this. I found it with an NPC named Emmi (http://www.wowhead.com/npc=61026). She is located at the Stormstout Brewery.\n\nThis will open up\nThe Mantidote (http://www.wowhead.com/quest=30623)\nThe Swarm Begins (http://www.wowhead.com/quest=30622)\nIt Does You No Good In The Keg (http://www.wowhead.com/quest=30624) (Alliance)\nIt Does You No Good In The Keg (http://www.wowhead.com/quest=30653) (Horde)\n\nThe Mantidote and It Does You No Good In The Keg both have In-the-field turn ins and no apparent follow ups.\n\nTurning in The Swarm Begins will lead you too Students No More (http://www.wowhead.com/quest=30625). If the students appear dead when you reach them, simply pull a mantid to them, and kill it over the bodies. They should pop up and start an escort style quest.\n\nCompleting Students No More will lead to Retreat! (http://www.wowhead.com/quest=30626). When that is turned in Master Bruised Paw (http://www.wowhead.com/npc=59856), whom is across the path from the last turn in, will offer The Savior of Stoneplow (http://www.wowhead.com/quest=30627).  \"Talk\" to the Mushan Beast, \"Ms Fanny\" and she will lead you to a hill and whomp you into the Colossus' jaws. Punch your way out of the Colossus and you will get your achievement.\n\nOnce you have turned in Savior of Stoneplow, you will be given The Gratitude of Stoneplow (http://www.wowhead.com/quest=30628) which awards rare quality iLvL 419 relevant to your class/spec.",
            date = "2012-11-05T21:34:20-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30627#comments:id=1757886",
        },
        {
            id = 1715500,
            score = 36,
            author = "Whiterock",
            text = "When you are eaten, turn sound up, there are some echoing whispering O_o",
            date = "2012-09-18T10:23:24-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30627#comments:id=1715500",
        },
    },
    [30628] = {
        {
            id = 1804272,
            score = 11,
            author = "Mondoblasto",
            text = "After I happened to stop by here at lvl 90, I found a detail I totally missed when I had finished the quest: nailed to the stair support strut of the inn is a large note titled \"The Attack on Stoneplow\".  You can click on it to watch the cutscene when the mantid breached the wall.",
            date = "2013-01-26T02:05:12-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30628#comments:id=1804272",
        },
        {
            id = 1723835,
            score = 8,
            author = "515518",
            text = "It's in the building.  Coords: 19.8, 55.9.  Go to the 2nd floor and click on the chest.",
            date = "2012-09-29T00:40:11-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30628#comments:id=1723835",
        },
        {
            id = 1735504,
            score = 6,
            author = "ChilpeUrmas",
            text = "The end of this quest seems to lead to nothing else. So, to me, the next area to questing is Kun-Lai Summit (http://www.wowhead.com/zone=5841).",
            date = "2012-10-08T10:16:15-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30628#comments:id=1735504",
        },
        {
            id = 1925122,
            score = 5,
            author = "337422",
            text = "For anyone else that is wondering where to go next, Kun-Lai Summit is the next zone from what I've found on Wowpedia (see the very end of this article (http://wowpedia.org/Valley_of_the_Four_Winds_storyline) and the very beginning of this article (http://wowpedia.org/Kun-Lai_Summit_storyline)). Messenger Grummles show up at Stoneplow, Halfhill, and the Grassy Cline offering a message from Lorewalker Cho in the form of the breadcrumb quest The Road to Kun-Lai (Alliance) (http://www.wowhead.com/quest=31254) or The Road To Kun-Lai (Horde) (http://www.wowhead.com/quest=31255).",
            date = "2013-12-11T00:58:18-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30628#comments:id=1925122",
        },
        {
            id = 2287832,
            score = 1,
            author = "253840",
            text = "There are 12 boots that are part of the Brick Battleplate (Recolor) (http://www.wowhead.com/transmog-set=1503/brick-battleplate-recolor) and nine come from three quests. This comment will be cross-posted for the sake of transmog hunters.\n\nWisdom Has A Price (http://www.wowhead.com/quest=30671/wisdom-has-a-price) is the fastest and easiest source if you can't use Item Restoration. The four quest chain starts with Sudden, Unexpected Crocolisk Aggression (http://www.wowhead.com/quest=30666/sudden-unexpected-crocolisk-aggression) at Jay Cloudfall (http://www.wowhead.com/npc=60173/jay-cloudfall) at /way Krasarang Wilds 51.6, 76.8\n\nThe Gratitude of Stoneplow (http://www.wowhead.com/quest=30628/the-gratitude-of-stoneplow) (zone quests culmination)\n\nhttps://www.wowhead.com/item=81479\nhttps://www.wowhead.com/item=81483\nhttps://www.wowhead.com/item=81484\n\nMuddy Water (http://www.wowhead.com/quest=29951/muddy-water) (starts here (http://www.wowhead.com/quest=29877/a-poor-grasp-of-the-basics), 17 quests follow)\n\nhttps://www.wowhead.com/item=81781\nhttps://www.wowhead.com/item=81785\nhttps://www.wowhead.com/item=81786\n\nWisdom Has A Price (http://www.wowhead.com/quest=30671/wisdom-has-a-price)\n\nhttps://www.wowhead.com/item=88035\nhttps://www.wowhead.com/item=88036\nhttps://www.wowhead.com/item=88040\n\nhttps://www.wowhead.com/item=82901 and https://www.wowhead.com/item=101298 are not available to players.\nhttps://www.wowhead.com/item=86121 is a BoP 0.8% drop from a Krasarang Equipment Locker (http://www.wowhead.com/object=213651/equipment-locker)",
            date = "2015-12-14T15:41:25-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30628#comments:id=2287832",
        },
    },
    [30630] = {
        {
            id = 1758923,
            score = 4,
            author = "Irv384",
            text = "As iceeagle said.\n\nI just got exalted with [faction=1269] yesterday and completed the exalted quest chain (starting with https://www.wowhead.com/quest=30645).  I had a problem with not getting the 'The Golden Gate' portion of the https://www.wowhead.com/achievement=7315 achievement, but left it alone because I thought there might be something else I needed to do, or a hotfix coming at some point, but once I was done and had all the other requirements, still no achievement.\n\nA ticket in to Blizz (queue said I had a 2 day, 5 hour wait, but it was answered in just over a day - hurray!) and a chat with a GM revealed that it is in fact a known bug and they are working on a fix for it (the GM also mentioned that they, too, had the same error with the achievement, so he/she felt the pain).  Hopefully, they said, it will be corrected shortly and granted to everyone who is exalted and completed every step of the requirements.\n\nI suppose all we can do until then is wait and keep an eye on the PTR notes.  *shrug*",
            date = "2012-11-07T19:26:18-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30630#comments:id=1758923",
        },
    },
    [30631] = {
        {
            id = 1684641,
            score = 22,
            author = "Draugar",
            text = "Jaluu the Generous - is located in the lower pavilion in the lake at the base of Mogu'shan Palace.\n\nKuru the Light-Hearted - is located on the upper level of The Summer Terrace of the Shrine of the Seven Stars to the left of the tree.\n\nLucky Lin - is located on the lower level of The Summer Terrace of the Shrine of the Seven Stars on the right side.\n\nMatron Vi Vinh is the Innkeeper of the Golden Lantern, entrance is to the right on the upper level of The Summer Terrace of the Shrine of the Seven Stars.",
            date = "2012-07-04T23:40:55-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30631#comments:id=1684641",
        },
        {
            id = 1874558,
            score = 8,
            author = "skadimundr",
            text = "Before level 90 you cannot fly here, so getting to Jaluu the Generous can be frustrating if you try to take a shortcut. Make sure you take the northern path into Mogu'shan Palace. Go up the ramp then head right and down the stairs.",
            date = "2013-07-07T15:01:01-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30631#comments:id=1874558",
        },
        {
            id = 1730527,
            score = 4,
            author = "slither666",
            text = "Just a note from post MoP go live:  Lucky Lin is labeled Elder Lin.  /tar Lucky Lin does not find her, /tar Elder Lin does.  However, when you talk to her, it announces that Lucky Lin has been spoken to.",
            date = "2012-10-03T22:45:57-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30631#comments:id=1730527",
        },
        {
            id = 1890752,
