    [30634] = {
        {
            id = 1680303,
            score = 56,
            author = "PriestessAur",
            text = "The Explosive Keg may remain in your inventory even after you complete the quest \"Barring Entry\". It is safe to delete.",
            date = "2012-06-23T18:34:36-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30634#comments:id=1680303",
        },
        {
            id = 1722513,
            score = 19,
            author = "Skaree",
            text = "If you're doing this when you're 90 and have flying, don't bother waiting for the stealth.  You can fly right up to the cave entrance and plant the explosives.  You'll have to stay on the ground until it blows up, but the explosion won't dismount you and you can fly off after.",
            date = "2012-09-28T03:10:09-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30634#comments:id=1722513",
        },
        {
            id = 1730023,
            score = 10,
            author = "Dalylah",
            text = "Update: As of Oct 4, 2012 this has been hotfixed. Lao is at 33,22 and is easy to find now.\n\nAs of Oct 3, 2012 this quest is still bugged. Lao seems to be lost in phasing. I flew around with a targeting macro and he just isn't there. Confirmed by many others on the official forums.",
            date = "2012-10-03T13:17:18-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30634#comments:id=1730023",
        },
        {
            id = 1760647,
            score = 6,
            author = "pmakaro",
            text = "One of many quests in Pandaria that currently leaves the item in your bags after the quest is completed.\n\nHere is a list of some of the quests and their items that remain after completion.\n\nhttps://www.wowhead.com/item=80484 for https://www.wowhead.com/quest=30634\nhttps://www.wowhead.com/item=87394 for https://www.wowhead.com/quest=31487\nhttps://www.wowhead.com/item=87841 for https://www.wowhead.com/quest=31507\nhttps://www.wowhead.com/item=87400 for https://www.wowhead.com/quest=31496\nhttps://www.wowhead.com/item=89366 for https://www.wowhead.com/quest=30341 (Thanks Ungluck)\n\nIn addition to the above provided quest items that stick around the following are some quest items that can be over looted and extras may remain.\n\nhttps://www.wowhead.com/item=88855 for https://www.wowhead.com/quest=31713 (Thanks Eighjan)\nhttps://www.wowhead.com/item=79864 for https://www.wowhead.com/quest=30329\nhttps://www.wowhead.com/item=87401 for https://www.wowhead.com/quest=31502\n\nIn all these cases the provided item or the extra looted items are safe to delete after the quest is complete.",
            date = "2012-11-11T03:03:44-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30634#comments:id=1760647",
        },
        {
