            score = 4,
            author = "allikitten",
            text = "Make sure to complete the following quests before you turn this in:\nhttps://www.wowhead.com/quest=30635\nhttps://www.wowhead.com/quest=30636\n\nAs of this posting, it appears there is a phasing bug that if you turn this quest in before completing the two listed, you will no longer be able to complete the above two as the area will be phased.\n\nI found this out by accident when my friend needed me to help kill some things, and I turned this quest in along the way, not knowing it would hurt my progress on the other two.",
            date = "2012-11-16T13:36:12-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30637#comments:id=1763355",
        },
    },
    [30638] = {
        {
