    [30645] = {
        {
            id = 1678031,
            score = 79,
            author = "746315",
            text = "After killing your first mob you are buffed with https://www.wowhead.com/spell=115976 giving you a damage aura that hits all nearby enemy targets with https://www.wowhead.com/spell=115986.\nAfter killing enough mobs, the buff will fade and you will then be buffed with https://www.wowhead.com/spell=115903 allowing your attacks to proc https://www.wowhead.com/spell=115990 to deal a large amount of damage and stun mobs.\nAfter killing enough mobs, the buff will fade and you will then be buffed with https://www.wowhead.com/spell=116091 which grants a damage aura that hits all nearby enemy targets with https://www.wowhead.com/spell=116099.\n\nAfter killing all 100 mobs you return to normal so don't pull a large pack of mobs if you're almost done with the quest.",
            date = "2012-06-18T10:45:26-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30645#comments:id=1678031",
        },
        {
            id = 1746530,
            score = 36,
            author = "Meaux",
            text = "If anyone missed the Dancing Water Skimmer for the https://www.wowhead.com/achievement=6350 achievement, they once again appear in most any water during this quest.",
            date = "2012-10-20T15:06:01-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30645#comments:id=1746530",
        },
        {
            id = 1745193,
            score = 32,
            author = "Blazeflack",
            text = "Edit: Since a hotfix on October 25th, https://www.wowhead.com/npc=58408 will now offer https://www.wowhead.com/quest=30643. This should solve the issue of not being able to start the chain on the same day you reach exalted.\n\nAfter hitting exalted with Golden Lotus I was not able to get this quest at all. I ended up waiting until the dailies reset, and here is what I discovered:\n\nhttps://www.wowhead.com/npc=59905 will give you the quest https://www.wowhead.com/quest=30643. It is completed inside The Silent Sanctuary near Mistfall Village. The quest is then delivered to https://www.wowhead.com/npc=58468 at The Golden Pagoda, after which she will hand you the quest https://www.wowhead.com/quest=30645.\n\nIt would appear that you won't be able to start this quest line until the next daily reset after you hit exalted with Golden Lotus.",
            date = "2012-10-18T21:34:39-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30645#comments:id=1745193",
        },
        {
            id = 1756142,
            score = 24,
            author = "ghcoltsfan",
            text = "After reaching exalted(congrats to you btw) fly over to Setting Sun Garrison to pick up the quest from https://www.wowhead.com/npc=59340. I was not finished with the dailies, and was able to start this quest chain immediately(not having to wait till the next daily reset) Another option you may ride in style rather than flying over to Setting Sun Garrison by purchasing https://www.wowhead.com/item=87781, https://www.wowhead.com/item=87782, and last but not least https://www.wowhead.com/item=87783 from https://www.wowhead.com/npc=59908. I couldn't decide which to buy so i bought all three :)",
            date = "2012-11-03T08:53:29-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30645#comments:id=1756142",
        },
        {
