    [30646] = {
        {
            id = 1746386,
            score = 365,
            author = "Avareal",
            text = "A couple of tips for this quest:\n\n1)  Purple lightning will periodically come at you from your left, your right, or both sides.  You will need to jump over these purple lightning waves with the https://www.wowhead.com/spell=116252 buff you received when accepting the quest.\n\nEverytime you jump you will glide up into the air and a short distance forward.  The direction you will go is the direction you're facing when you jumped.  In other words, you will be going up and over the waves, not just up than down.\nYou will want to jump a bit early, don't wait until the lightning is right on top of you or you will take a good deal of lightning damage.  It's imperative you are facing the wall of lightning that is coming at you, as again, you will glide up and forward when you jump and the idea is to jump over the wave.\n\n2)  At times throughout the fight, https://www.wowhead.com/npc=60273 will throw his spear.  Pay attention to him as well as watching for the purple waves so as you don't miss him throwing the spear.\n When he throws the spear, simply run over and click it.  Once you've picked it up, your Extra Action Button will apear and hitting this button will hurl the spear back at the Warlord doing massive damage.\nIt's is important that you quickly, but safely get to the spear ASAP and hurl it back at him.  The reason for this is that if the spear is not handled in a somewhat timely manner, it will explode causing you massive damage.  From personal experience, there is more than enough time to properly get to, and hurl back, the spear if you go for it right when he throws it.  Keep in mind that he may throw the spear behind an incoming purple lightning wave.\nRinse and repeat.\n\n3)  Do not worry about going DPS crazy on this fight.  The majority of damage that comes from killing https://www.wowhead.com/npc=60273 comes from the aforementioned Hurl Spear attack.  However, if there are no purple waves coming, and he hasn't thrown his spear, feel free to lay into him.\n\nGood luck!",
            date = "2012-10-20T10:37:32-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30646#comments:id=1746386",
        },
        {
            id = 1746637,
            score = 198,
            author = "Koviko",
            text = "If you die and are wondering how to get back into the fight, there are roads on both sides of the Mogu'shan Palace. Take these roads and there will be steps leading up to Zhao-Jin. Resurrection Sickness affects the power of your spear throws, as well.",
            date = "2012-10-20T17:31:55-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30646#comments:id=1746637",
        },
        {
            id = 1753612,
            score = 140,
            author = "712794",
            text = "You can stay mounted this whole fight just fly down and click on the spear then throw it at him.. fly back up till he throws it again",
            date = "2012-10-30T05:30:31-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30646#comments:id=1753612",
        },
        {
            id = 1717221,
            score = 55,
            author = "Diwtay",
            text = "This quest is the second in a chain. The first quest is called The Might of Three.  NPC is Sun Tenderheart. She is sitting by the fire at (56,43) The Golden Pagoda in Vale of Eternal Blossoms. You must be Exalted with The Golden Lotus Faction to begin this quest.",
            date = "2012-09-22T15:36:59-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30646#comments:id=1717221",
        },
        {
            id = 1678036,
            score = 52,
            author = "746315",
            text = "Upon accepting the quest Chi-Ji will spawn and buff you with https://www.wowhead.com/spell=116252 which you'll need to fight the quest mob. While fighting https://www.wowhead.com/npc=60273, he will periodically spawn waves of shadow to your left, right, or both sides: with the enhanced jump you can easily avoid the waves. Also during the fight, the warlord will throw his spear into the ground nearby. Pick it up: if you don't get it in time, it'll explode and possibly kill you. Once you've picked it up, use the special button at the bottom of the screen to throw it back at him and deal ~500k damage. Rinse and repeat.",
            date = "2012-06-18T10:56:20-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30646#comments:id=1678036",
        },
    },
    [30648] = {
        {
            id = 1801494,
            score = 8,
            author = "304770",
            text = "For those who level lock like I do and forgot where to start upon leveling to 86, the flight ends at around 86,19 in the Valley of the Four Winds, just east of Pang's Stead.\n\nFor completionists, you may want to go back and pick up either https://www.wowhead.com/quest=32018 or https://www.wowhead.com/quest=32019 before picking up https://www.wowhead.com/quest=29907 as they become unavailable otherwise.",
            date = "2013-01-20T10:41:53-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30648#comments:id=1801494",
        },
        {
            id = 5897956,
            score = 8,
            author = "KeyboardWizard",
            text = "For those searching their maps for this quest, Fei is in The Jade Valley at /way 49.33 61.37",
            date = "2024-07-16T09:02:56-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30648#comments:id=5897956",
        },
        {
            id = 1729320,
            score = 7,
            author = "jtbalogh",
            text = "Amazing mount again (this time sitting by the shoulders instead of the neck)",
            date = "2012-10-02T23:43:28-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30648#comments:id=1729320",
        },
        {
            id = 5921169,
            score = 3,
            author = "agnasg",
            text = "If you forgot to talk again with Fei, and now you're in another zone but this quest is still in your quests log, you don't need to get back to Fei, click \"Track\" and click on the quest in the right listing. Profit.",
            date = "2024-08-18T09:37:56-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30648#comments:id=5921169",
        },
        {
            id = 1729339,
            score = 0,
            author = "jtbalogh",
            text = "If you want to ride the fun mount again later, then do not turn this quest in yet. This is the last quest in the chain and you can still get the loremaster achievement for the zone without turning in the quest.",
            date = "2012-10-03T00:14:10-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30648#comments:id=1729339",
        },
    },
    [30649] = {
        {
            id = 1721079,
            score = 24,
            author = "Mormodes",
            text = "Jaluu is over near Mogu'Shun Palace (the circle in the center of the lake) (74, 42).\n\nElder Liao is on the lower level of the shrine.\n\nThe other two are on the top level (one outside, one inside - go through the right entrance into the shrine)",
            date = "2012-09-27T02:08:59-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30649#comments:id=1721079",
        },
        {
            id = 1726608,
            score = 17,
            author = "praze",
            text = "Jaluu (http://www.wowhead.com/npc=59908) can be reached by heading east along the trail and up the stairs to the Mogu'shan Palace (http://www.wowhead.com/zone=6182). Once within the Palace walls, you can navigate to the structure Jaluu (http://www.wowhead.com/npc=59908) is standing on in the middle of the lake.",
            date = "2012-09-30T22:13:39-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30649#comments:id=1726608",
        },
        {
            id = 1803310,
            score = 7,
            author = "Karsciyin",
            text = "If the quest marker is confusing you, only Jalu is at the Temple. Everyone else is at the city, Shrine of the Two Moons - hence the quest name.",
            date = "2013-01-24T02:54:25-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30649#comments:id=1803310",
        },
        {
            id = 1725058,
            score = 6,
            author = "Austinisonfire",
            text = "After i turned this quest in i haven't gotten any dailies. Is it a bug or do i have to do something else ?",
            date = "2012-09-29T19:20:18-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30649#comments:id=1725058",
        },
        {
            id = 1791559,
            score = 2,
            author = "1070439",
            text = "So I wanted to level up my rep with the golden lotus to drop the price on the flight training at 90. Took me a LONG time but finally found out that you can't. You have to purchase https://www.wowhead.com/spell=115913 to unlock https://www.wowhead.com/quest=30632 which I guess then unlocks the dailies.\n\nIn the end you end up making enough money to not bother with the price drop.",
            date = "2013-01-03T01:01:28-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30649#comments:id=1791559",
        },
    },
