    [30652] = {
        {
            id = 1923734,
            score = 6,
            author = "1123465",
            text = "I did this quest twice because the UI pop up a box didn't come up to complete it.  I thought my logging out before finishing it messed it up but then I remembered there is a bug from Carbonite sometimes with the UI quest pop ups.  You can hit the L key and bring up your quest log and manually click complete quest.  In Carbonite you have to go under your options and under the Quest Module click the option \"Use Alt L instead of L for Carbonite Quests\"  From then on you can manually complete the quest if it doesn't pop up a complete quest box.",
            date = "2013-12-05T13:43:41-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30652#comments:id=1923734",
        },
