        {
            id = 1722290,
            score = 11,
            author = "staynight",
            text = "Cave entrance located at 49, 76.",
            date = "2012-09-27T23:39:48-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30660#comments:id=1722290",
        },
        {
            id = 1793827,
            score = 7,
            author = "love45acp",
            text = "This quest is buggy. I killed all the wolf adds, resulting in him disappearing, twice. The third time, I left one wolf alive. His shield does drop eventually, and this allowed me to kill him.",
            date = "2013-01-06T18:50:41-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30660#comments:id=1793827",
        },
        {
            id = 1909894,
            score = 5,
            author = "55493",
            text = "This quest kept bugging out on me.  He would put a shield up on himself then summon ghost wolfs.  I assuming that I had to kill the wolfs to get the shield down killed all three soon after killing the third wolf the shield went down and he disappears.\n\nI did this 4 times then check wowhead.com and saw love45acp post and his or her sulution worked.  Thank you love and thank you wowhead for having such an awesome website.",
            date = "2013-10-18T17:26:31-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30660#comments:id=1909894",
        },
        {
            id = 1983890,
            score = 4,
            author = "Pelontir",
            text = "If this quest keeps bugging even if you tried love45acp suggestion to let one wolf add alive, try to kill the magma totem he puts down at the beginning of the fight. After doing that the boss did not disappear for me and I was able to kill it.",
            date = "2014-07-24T06:10:24-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30660#comments:id=1983890",
        },
    },
    [30661] = {
        {
            id = 1746417,
            score = 20,
            author = "eresin",
            text = "I had this quest bug out on me twice, with his despawning after I killed the wolves.  I decided to move further inside the cave and try again and it worked.  Perhaps if you are too close to the entrance he despawns.  If this happens try to do this quest nearer the back of the cave where he initially stands.",
            date = "2012-10-20T11:22:10-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30661#comments:id=1746417",
        },
        {
            id = 1724380,
            score = 13,
            author = "34796",
            text = "Cave entrance is at 49,77 above the grazing yaks.",
            date = "2012-09-29T10:51:53-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30661#comments:id=1724380",
        },
        {
            id = 1851969,
            score = 6,
            author = "IMissThottbot",
            text = "As the NPC dies he said \"Our homes... destroyed... We did what we had to....\"\n\nAnother quest that makes the quester feel like poo, thanks Blizz :(",
            date = "2013-05-10T21:50:58-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30661#comments:id=1851969",
        },
        {
            id = 1897649,
            score = 6,
            author = "celestialchaser",
            text = "You must be inside the cave near where he spawns. MAKE SURE YOU KILL HIS TOTEM FIRST. If you don't, he will despawn after the wolves are summoned.\n\nSincerely, a person who killed him 3 times until I figured it out",
            date = "2013-09-14T05:56:52-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30661#comments:id=1897649",
        },
        {
            id = 1800768,
            score = 4,
            author = "882230",
            text = "From what I have found with this quest is that every time I have tried to kill him without destroying his flame totem BEFORE he casts the shield and summons the wolves, he has bugged and despawned after the wolves were killed.\n\nSo point being, kill the totem before he summons the wolves and casts the shield to avoid him bugging out and despawning. Worked for me on every toon that I have tried it on so far.",
            date = "2013-01-19T00:42:11-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30661#comments:id=1800768",
        },
    },
