    [30669] = {
        {
            id = 2554298,
            score = 11,
            author = "ShamrockSoup",
            text = "Not sure why but my raft came with a raccoon friend. I thought all of them did until I visited this page.",
            date = "2018-02-21T23:43:08-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30669#comments:id=2554298",
        },
        {
            id = 1720373,
            score = 10,
            author = "Terranell",
            text = "Once you take this quest you get the buff https://www.wowhead.com/spell=116032 (note the jump to go faster). Then after you \"pick up your raft\", your raft appears automatically anytime you walk out onto the water of the lake, and disappears when you walk back onto land.\n\nIf you abandon the quest and then when re-taking it can't get 'pick up your raft' to complete, re-log and a fresh raft to pick up will appear.",
            date = "2012-09-26T15:23:42-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30669#comments:id=1720373",
        },
        {
            id = 1731910,
            score = 7,
            author = "Quartermasters",
            text = "raft disappears if your feet are below water level when you head out, just go a bit further and then jump clear of the surface, raft appears and you're on your way:)",
            date = "2012-10-05T04:12:53-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30669#comments:id=1731910",
        },
        {
            id = 1737701,
            score = 7,
            author = "842530",
            text = "If you're having problems getting completion for the pickup task, disable/right-click the \"Rafting\" buff. This should allow you to click the raft when in the water. Additionally, you may have to relog and/or disable add-ons.\n\nIn any event, don't bother attempting rafting out into the lagoon until you get credit for this part.",
            date = "2012-10-10T16:40:32-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30669#comments:id=1737701",
        },
        {
            id = 1722345,
            score = 1,
            author = "hobbesmarcus",
            text = "You have to right click the raft to jump on it and get credit.  I just manually jumped on it, I could move around but it wouldn't give me credit for \"picking it up.\"",
            date = "2012-09-28T00:33:49-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30669#comments:id=1722345",
        },
    },
    [30670] = {
        {
            id = 1722571,
            score = 7,
            author = "2Lan",
            text = "Just kill https://www.wowhead.com/npc=61224 around 43,86 to get 5x https://www.wowhead.com/item=81713",
            date = "2012-09-28T04:13:44-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30670#comments:id=1722571",
        },
        {
            id = 1800062,
            score = 6,
            author = "Mingle",
            text = "When I tried to do this quest yesterday, https://www.wowhead.com/npc=60161 offered me both https://www.wowhead.com/quest=30665 and https://www.wowhead.com/quest=30670 at the same time. As a result, I didn't get credit for killing the Yaungol, and nor did I get any drops from the Sha.\n\nThis appears to be a bug — dropping both quests and just picking up https://www.wowhead.com/quest=30665 allowed me to get credit for the kills and then I turned in, picked up https://www.wowhead.com/quest=30670 and all was good.",
            date = "2013-01-17T11:54:53-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30670#comments:id=1800062",
        },
        {
            id = 1775646,
            score = 5,
            author = "1057704",
            text = "Located shortly West of the quest giver. Around 42,86, drop rate around 1 in 3.",
            date = "2012-12-04T19:49:58-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30670#comments:id=1775646",
        },
        {
            id = 1868527,
            score = 4,
            author = "Macamirunni",
            text = "Yaungol was spelled Yungol if anyone noticed",
            date = "2013-06-20T13:27:31-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30670#comments:id=1868527",
        },
        {
            id = 3246759,
