            text = "Requires at least part of the intro quests at Binan (like most of the zone does) up to Call Out Their Leader",
            date = "2020-11-08T16:14:15-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30670#comments:id=3246759",
        },
    },
    [30671] = {
        {
            id = 1726597,
            score = 6,
            author = "aliciana2",
            text = "I rode the raft from the previous quest, \"Lorewalker of the lake\" out to see Wise Ana Wu. I turned in that quest, and then Ana gives this quest. The only problem was that after I accepted this quest, then I couldn't get off the raft to dive in the water.\n\nWhile there is probably something really simple that I am missing, I could not get off the raft to dive into the water after I accepted this quest. I tried riding the raft back to the shore and getting off, but every time I tried to go in the water, it automatically put me back on the raft.\n\nThe only thing that worked was going into the water mounted and then dismounting in the water.",
            date = "2012-09-30T21:57:06-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30671#comments:id=1726597",
        },
        {
            id = 1754070,
            score = 6,
            author = "109740",
            text = "The idea that shark fillets are a 50% drop rate is just ridiculous. As if you can't manage to get 5 bits of meat off 1 shark?",
            date = "2012-10-30T22:13:15-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30671#comments:id=1754070",
        },
        {
            id = 1734869,
            score = 4,
            author = "Brainsnack",
            text = "The sharks can be pulled one by one, without aggroing the other shark, in the situation where there are two mobs together. This is if, for any reason, you don't want to, or can't, fight two mobs at the same time.",
            date = "2012-10-07T18:58:41-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30671#comments:id=1734869",
        },
        {
            id = 1754012,
            score = 4,
            author = "zharshoul",
            text = "no comments on the cinematic that follows?\n\nwith the crocodiles, starving because of competition with pandarens, sharks and hozens\n\nanother one bites the dust\n\ntake and take and take and take, and then we take some more. It has to come from somewhere.",
            date = "2012-10-30T19:13:42-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30671#comments:id=1754012",
        },
        {
            id = 1931089,
