    [30715] = {
        {
            id = 1676644,
            score = 12,
            author = "selvin",
            text = "Note that two are near the gate and easy to find. The third is north of the gate and up a zigzag path that won't be shown on the minimap when you're next to the other two corpses. Look west of the wooden tower and barrel and behind the west spear wall to find the path.",
            date = "2012-06-14T15:24:51-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30715#comments:id=1676644",
        },
        {
            id = 1849745,
            score = 10,
            author = "kerrymayall",
            text = "These Shado-Pan masters certainly exacted a heavy toll on the enemy before falling - bodies everywhere.",
            date = "2013-05-03T22:25:36-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30715#comments:id=1849745",
        },
        {
            id = 1724419,
            score = 6,
            author = "Whiterock",
            text = "Sha in the Monastery Quest Tree From Whiterock\n[pre]The Ordo Warbringer (http://www.wowhead.com/quest=30660){A2 (http://www.wowhead.com/quest=30662),H1 (http://www.wowhead.com/quest=30661),H2 (http://www.wowhead.com/quest=30663)}* Barrels of Fun (http://www.wowhead.com/quest=30651){H} (http://www.wowhead.com/quest=30656)* Pandaren Prisoners (http://www.wowhead.com/quest=30650){H} (http://www.wowhead.com/quest=30655)*\n                           └──────┼───────────────┘\nCall Out Their Leader (http://www.wowhead.com/quest=30457)* [ins]S[/ins])The Shado-Pan (http://www.wowhead.com/quest=31455){H} (http://www.wowhead.com/quest=31453) Hit Medicine (http://www.wowhead.com/quest=30460)* All of the Arrows (http://www.wowhead.com/quest=30459)*\n ||                  └────┐        ||       /             /\na)Turnabout (http://www.wowhead.com/quest=30670)             a)The Defense of Shado-Pan Fallback (http://www.wowhead.com/quest=30665)    [ins]+[/ins])Holed Up (http://www.wowhead.com/quest=30682)\na)Unmasking the Yaungol (http://www.wowhead.com/quest=30690)\nb)To Winter's Blossom (http://www.wowhead.com/quest=30699)\n ||                \\\nb)A Line Unbroken (http://www.wowhead.com/quest=30715) b)Honor, Even in Death (http://www.wowhead.com/quest=30723)\n    \\             /\n    b)To the Wall! (http://www.wowhead.com/quest=30724)\n    /             \\\nc)Off the Wall! (http://www.wowhead.com/quest=30750)   c)A Terrible Sacrifice (http://www.wowhead.com/quest=30751)\n ||                /\nd)Lao-Chin's Gambit (http://www.wowhead.com/quest=30994)\nd)Do a Barrel Roll! (http://www.wowhead.com/quest=30991)\nd)Finish This! (http://www.wowhead.com/quest=30992)──────>My Husband... (http://www.wowhead.com/quest=30768)*\n ||\nf)Where are My Reinforcements? (http://www.wowhead.com/quest=30993)\nf)Unbelievable! (http://www.wowhead.com/quest=30752)\n[ins]S[/ins])Into the Monastery (http://www.wowhead.com/quest=31030){backup version (http://www.wowhead.com/quest=31031)}(Shado-Pan Monastery)\n[ins]#[/ins])Lord of the Shado-Pan (http://www.wowhead.com/quest=30757)(Shado-Pan Monastery)\n\n[ins]#[/ins])The Path to Respect Lies in Violence (http://www.wowhead.com/quest=31342)(Shado-Pan Monastery)\n\nLegend:\nS means Skippable\n+ means Can start anytime, prequests not needed.\n{H} means Quest Have Horde Variant, click {H} for it.\n* means another Quest Tree.[/pre]\n\nYes, there are SUCH WEIRD prequests, even more weird that it have breadcumb with other prequests.",
            date = "2012-09-29T11:26:34-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30715#comments:id=1724419",
        },
        {
            id = 1801678,
            score = 5,
            author = "998027",
            text = "Surprised nobody has said this yet...\n\nThis quest is likely a reference to Lord of the Rings (III), where the spirits are released from their Oaths, and can only be released from their oaths from the King of Gondor, whose line was forgotten but unbroken.\n\nIt also is coupled with the quest \"https://www.wowhead.com/quest=30723\", of which is relevant to LOTR due to the army of gondor being dead before fighting.",
            date = "2013-01-20T18:01:54-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30715#comments:id=1801678",
        },
        {
            id = 1801962,
            score = 5,
            author = "Arikara",
            text = "The npc's float into the air once you interact with, similar to how Warcraft 3 Heroes did once killed.",
            date = "2013-01-21T10:25:38-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30715#comments:id=1801962",
        },
    },
    [30716] = {
        {
            id = 1733072,
            score = 84,
            author = "Tharama",
            text = "This quest is much like the Firelands daily https://www.wowhead.com/quest=29125 where you have to chase ghost stags except this time it is ghost cranes and they're much harder to see.\n\nYou can see the sheen of their body and neck and they move in set paths so you have to intercept or fly into them (which isn't hard, I caught up to them with 280% flying) to get credit.",
            date = "2012-10-06T05:29:00-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30716#comments:id=1733072",
        },
        {
            id = 1736641,
            score = 58,
            author = "ArgentSun",
            text = "While there is no easy way to get those, I found it convenient to prioritize this quest over the other two I got - so I would fly out and look for those spirits. When I found and caught one, I would \"camp\" that exact spot while gradually working towards the other quests I have.\n\nSince this is the first time I do August Celestials dailies, I am not sure how viable this strategy will be in the future. We'll see.\n\n---\n\n(35.5, 78.1) seems to be one place where three paths to cross. Two of them cross exactly (or almost exactly) on this location, and there is a third one less than one unit away. The downside to \"camping\" this spot (or any spot like that) is that you might miss a spirit if you are fighting.",
            date = "2012-10-09T12:34:08-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30716#comments:id=1736641",
        },
        {
            id = 1737690,
            score = 23,
            author = "kaze950",
            text = "Some tips for doing this:\n\nTurn shadows onto high and you can see them by their shadows.\nIf you're a hunter, turn track beasts on. They will be the only green dots on the island.\nThey tend to spawn in the same places, so if you find one you can usually just camp the spot.\n\nAlso, thankfully, all it takes is to land by them to receive credit for the quest. You don't have to click them or anything.",
            date = "2012-10-10T16:26:35-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30716#comments:id=1737690",
        },
        {
            id = 1804657,
            score = 5,
            author = "1047156",
            text = "This quest is about finding and following 3 spectral cranes. They are somewhat difficult to see, so be sure to look closely. As others have suggested, be sure to have shadows enabled as it will make them a bit easier to see.\n\nThe best place I found to camp these is 35.23, 75.00, on the steps facing the paths.",
            date = "2013-01-26T19:37:50-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30716#comments:id=1804657",
        },
        {
            id = 1849033,
            score = 5,
            author = "704410",
            text = "One of the most annoying quests in the game!",
            date = "2013-05-01T18:29:29-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30716#comments:id=1849033",
        },
    },
    [30717] = {
        {
            id = 1734082,
            score = 13,
            author = "Tharama",
            text = "Remember feather collecting quests? Well now it's a daily.\n\n I find a high amount (4-6) feathers around the crane statue fountain on the southern end of the island alone and they seem pretty plentiful in the south over the north side anyway.",
            date = "2012-10-07T03:40:33-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30717#comments:id=1734082",
        },
        {
            id = 1767471,
            score = 8,
            author = "834150",
            text = "There is an almost sufficient amount of feathers in and around the fountain-based statue of the Crane in the Western part of the isle, precisely at 32.77. I found 7 feathers there, could be more since another player was messing around at the same time.",
            date = "2012-11-25T03:07:28-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30717#comments:id=1767471",
        },
        {
            id = 1907806,
            score = 1,
            author = "Madr",
            text = "Don't be silly like me, and run around killing https://www.wowhead.com/npc=60616 thinking they'll drop the feathers needed for this quest.  The feathers you need are on the ground scattered around the island.  Look for the sparkles.",
            date = "2013-10-12T00:03:37-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30717#comments:id=1907806",
        },
        {
            id = 1930751,
            score = 1,
            author = "Lucrella",
            text = "These lovely little quest items can be found all around Cradle Of Chi-Ji.\n\n32,77 there is a crane statue that have 4-7 feathers around it. Other feathers are easily found around the base of the large trees.",
            date = "2014-01-01T09:52:52-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30717#comments:id=1930751",
        },
        {
            id = 2170402,
            score = 1,
            author = "1436362",
            text = "3 feathers at 36.09 71.72",
            date = "2015-04-22T12:58:59-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30717#comments:id=2170402",
        },
    },
    [30718] = {
        {
            id = 1766742,
            score = 34,
            author = "38749",
            text = "So, when \"dueling\" a student of Chi-Ji, if you're about to kill them, they graciously declare you the winner and you let them run away.  But, if they team up on you 7 on 1, and they kick the crap out of you, when you declare them the winner, they just finish the job and murder you.\n\nWhy am I helping the temple of Chi-Ji again?",
            date = "2012-11-23T10:48:15-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30718#comments:id=1766742",
        },
        {
            id = 1772333,
            score = 22,
            author = "992022",
            text = "As of 11/30 they get to one HP and keep on fighting, at least for me....bugged.",
            date = "2012-11-30T15:29:52-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30718#comments:id=1772333",
        },
        {
            id = 1772884,
            score = 21,
            author = "hurlyburly",
            text = "In Soviet Russia, quest objective kill you ten times.",
            date = "2012-12-01T06:59:56-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30718#comments:id=1772884",
        },
        {
            id = 1788065,
            score = 19,
            author = "Pzypro",
            text = "I had to make an account just to say how awesome I think these guys are:\n\n- They love to duel by aggroing onto you if you come anywhere close to them.\n- If you beat them they surrender and vanish.\n- If they beat you (or you let them to see what happens) you die and get to repair\n- They drop no loot\n- They don't count as honorable/exp kills so all the abilities that do X after kill (like restore health!) do nothing against them.\n- They love to chain pull each other and gang up on you.\n\nIn short, one of the most amusingly cheap mobs in the game :P.",
            date = "2012-12-27T10:03:55-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30718#comments:id=1788065",
        },
        {
            id = 1770880,
            score = 15,
            author = "Todesbote",
            text = "As of patch 5.1 the majority of the Students of Chi-Ji seem to be evading and unattackable for me.",
            date = "2012-11-29T02:41:59-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30718#comments:id=1770880",
        },
    },
