        {
            id = 1757016,
            score = 16,
            author = "Hemingray",
            text = "Adding to Calesta's comment: in the letter we receive, the word despair is currently misspelled as \"dispair\". Falric would be proud...\n\n\"Dis' pear... so delicious (http://www.wowhead.com/npc=38112/falric#comments).\"",
            date = "2012-11-04T13:12:48-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30727#comments:id=1757016",
        },
        {
            id = 1675392,
            score = 12,
            author = "Calesta",
            text = "After defeating Ellia the second time, you receive mail from Thelonius (http://mop.wowhead.com/npc=60506).\n\n\"Before your match today, Ellia Ravenmane swelled with hope and pride.  After your victory, she lost a lot of that hope.\n\nYour lesson for today is that hope can turn into despair in a heartbeat.  Ellia is learning this lesson the hard way.\"",
            date = "2012-06-10T21:25:50-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30727#comments:id=1675392",
        },
        {
