        {
            id = 1742848,
            score = 3,
            author = "Catriona",
            text = "This challenger frequently pops you up into the air a bit - I was casting too fast to notice if it interrupted, but I don't think so - and then casts a void zone named something like \"Still Waters Run Deep\". I was at half health just standing there nuking him save for moving from the void zone when the fight was finished.",
            date = "2012-10-15T21:06:23-05:00",
