        {
            id = 1764538,
            score = 20,
            author = "311006",
            text = "He's got a fairly powerful throw ability which takes you a distance away from him.\n\nAs a result, you'll probably want to go around and take out any of the Students of Chi-Ji in the area, to make sure they don't aggro on you during the fight.  This happened to me, and the joy of three students AND this guy on a mage cannot be described in words that are not mostly profanity.",
            date = "2012-11-18T22:28:10-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30734#comments:id=1764538",
        },
        {
            id = 1688379,
            score = 12,
            author = "Calesta",
            text = "After defeating Huck Wheelbarrow the first time, you receive mail from Thelonius.\n\n\"I am concerned about Ellia Ravenmane.  She has not appeared for her training in several days.  I fear she has crossed that narrow threshold from hope into despair.\n\nIf you see her, let me know\n\n-Thelonius.\"",
            date = "2012-07-15T09:56:38-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30734#comments:id=1688379",
        },
