    [30738] = {
        {
            id = 1660833,
            score = 34,
            author = "lunamoonraker",
            text = "Reference to the famous jazz pianist and composer Thelonious Monk (http://en.wikipedia.org/wiki/Thelonious_Monk).\n\nThelonius + Monk = win\nMiles’d got killed if he hit me...",
            date = "2012-04-30T10:24:23-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30738#comments:id=1660833",
