    [30746] = {
        {
            id = 2018602,
            score = 92,
            author = "993668",
            text = "I don't know if anyone else had this issue since the new patch... but I ran around and around trying to find the \"right cave\" since I couldn't find the NPC in the one that was marked (and the one I thought it was in). Turns out, it was in the cave, but there was a bit of a phasing glitch. If you can't find the NPC, go into the cave that has nothing in it, log out, then back in again. (It also fixes other quests where the NPCs are out of phase)",
            date = "2014-10-24T19:54:50-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30746#comments:id=2018602",
        },
        {
            id = 1672533,
            score = 85,
            author = "Cielos",
            text = "Make sure before you complete this quest, you have also completed https://www.wowhead.com/quest=30742, https://www.wowhead.com/quest=30743, and https://www.wowhead.com/quest=30745.  Kota Kon takes you all the way back down the mountain.",
            date = "2012-06-02T01:44:45-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30746#comments:id=1672533",
        },
        {
            id = 1723713,
            score = 68,
            author = "boxtor",
            text = "The turn in point is in the upper cave, not the lower cave.",
            date = "2012-09-28T23:06:58-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30746#comments:id=1723713",
        },
        {
            id = 5858630,
            score = 61,
            author = "Xozus",
            text = "On remix if you don't see the NPC's for turn in - do a /reload",
            date = "2024-05-18T14:11:26-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30746#comments:id=5858630",
        },
        {
            id = 5866681,
            score = 21,
            author = "Jeolene",
            text = "Blizz's inability to make things work properly causes you to go to the wrong place.  Yes, there is an \"empty\" cave you have to find at /way 37.38, 75,83\n\nThe problem is the ? shows a down arrow, indicating that the cave is on the ground level when it is not.  Go to the cave everyone here says and if it's empty, /reload (because after ten+ years, blizz still can't be bothered to fix these bugs).\n\nYou'll know you have the right cave because there will be a grummle and a large yeti with a bow on its horn.",
            date = "2024-05-26T14:26:45-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30746#comments:id=5866681",
        },
    },
    [30747] = {
        {
            id = 3186508,
            score = 89,
            author = "Dosantsu",
            text = "So basically this quest has become a nightmare after the scaling changes.\nBlizz seems to keep forgetting to check on how this impacts certain quests,Burning Crusade mobs and some other zone quests seems to suffer the most.\nI did this quest a long long time ago and it wasn't this bad.\nBut now all the Hozen hit poor Kota Kon like a truck.\nAll is not lost however.\nIf you don't feel like flying back to Kota Basecamp to pilot Kota Kon every time they waste her just take the quest slower than you usually would.\nIf you see a large group of Hozen, Leap Smash into the middle of them,making sure you don't miss any because it will kill them all if you aim right.\nUse Hozen Snack when off cooldown if there is only 1 Hozen remaining and if you see two or more face them and use Headbutt as it has a rather nice AoE and should take care of them.\nHozen Shamans should be taken care of ASAP because they hit 5-6k per Lightning Bolt but the melee range Hozen aren't a problem unless you can't Headbutt them.\n\nThis will teach me for not doing all the quests in the zone back when MoP first came out and instead jumping from zone to zone as I out leveled the area.",
            date = "2020-01-26T23:43:01-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30747#comments:id=3186508",
        },
        {
            id = 1750498,
            score = 80,
            author = "Jjokkey",
            text = "So, let me make sure I understand this.  We get a wild animal addicted to coffee then bribe it to wantonly slaughter local sentient life in a land where violence can make very bad things happen, then we come back the next day (http://www.wowhead.com/quest=30821) and do it all again.\n\nWe're the good guys here, right?",
            date = "2012-10-25T21:59:40-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30747#comments:id=1750498",
        },
        {
            id = 3215751,
            score = 66,
            author = "MHGaming",
            text = "Unfortunately, Blizzard was too stupid or lazy to scale this quest properly with the level scaling changes. The hozen deal MUCH more damage than they should, to the point that a group of them can kill the yeti in literal seconds. Prepare for a lot of flying back to the starting location to remount.",
            date = "2020-07-03T18:06:43-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30747#comments:id=3215751",
        },
        {
            id = 2862098,
            score = 33,
            author = "oozie",
            text = "ok - this quest used to be fun - but they did something recently so the poor creature loses health very quickly\n\nbasically - don't bother with this quest!",
            date = "2018-12-26T17:24:04-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30747#comments:id=2862098",
        },
        {
            id = 5863347,
            score = 25,
            author = "Pankakan",
            text = "DAMN SON those monkeys HURT @ 70 in MoP:R\n\nCant pull a big grp and kill them >.<",
            date = "2024-05-23T01:06:13-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30747#comments:id=5863347",
        },
    },
    [30750] = {
        {
            id = 1744473,
            score = 15,
            author = "MarsJenkar",
            text = "THIS!  IS!  PANDARIA!  *kick*",
            date = "2012-10-18T00:33:08-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30750#comments:id=1744473",
        },
        {
            id = 1785579,
            score = 9,
            author = "MASDERCHEEF",
            text = "As a Hunter, I liked to wait to kick them until their health was extremely low. Then, once they were in the air, I would hit them with a Kill Shot. Like skeet shooting.",
            date = "2012-12-22T08:34:21-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30750#comments:id=1785579",
        },
        {
            id = 1758191,
            score = 7,
            author = "DoraTE",
            text = "Lol, the quest where you become a flight master.\n\nWhen you mouseover a low health mob, you pointer changes to the flighmaster symbol, then click and away they fly. I did not want to hand this one in.",
            date = "2012-11-06T10:47:29-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30750#comments:id=1758191",
        },
        {
            id = 1887837,
            score = 5,
            author = "Berronaxwins",
            text = "Oh I bet gnomes just LOVED this quest..",
            date = "2013-08-17T13:02:53-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30750#comments:id=1887837",
        },
        {
            id = 1724368,
            score = 4,
            author = "537414",
            text = "It is not required to kick the mobs, but if you want to, hover your mouse cursor over the mob when his health is below 30% and left or right click on him. The game will inform you that it is time to kick. (\"Finish him! Boot him off the wall!\") The cursor changes to the same one used for flight masters.",
            date = "2012-09-29T10:45:55-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30750#comments:id=1724368",
        },
    },
    [30751] = {
        {
            id = 1825386,
            score = 7,
            author = "Raevenne",
            text = "One of the funniest things I've ever seen in this game:\n\nI was doing this quest on my death knight, and there was a mage there as well. She was so worried that I'd get to the barrels before she did, and she kept dashing in and stealing them while I was fighting the mobs to get to the barrels. Finally at one point, she used her Blink ability to get to one before I could get it, and she Blinked herself directly through one of the low parts of the crenelations  and right off the wall, falling to her death! I laughed until I nearly cried, and chalked another one up for Karma.\n\nNow every time I do this quest, I chuckle all over again about that selfish mage.\n\nEdit: constellations != crenelations.../sigh",
            date = "2013-03-09T13:25:05-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30751#comments:id=1825386",
        },
        {
            id = 1729903,
            score = 1,
            author = "751881",
            text = "It's all very good with a questline, but you already have that above the guiding screenshots. My problem here, was to get back on the wall, to finish the quest. And I found out that I had to seek to the camp up higher, with snow on the ground. When you follow the trail up, you go to the right in stead of the camp to the left.",
            date = "2012-10-03T10:56:54-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30751#comments:id=1729903",
        },
        {
            id = 1784749,
            score = 1,
            author = "chenahotspring",
            text = "The oil pots are atop the wall at 26, 60",
            date = "2012-12-20T17:39:32-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30751#comments:id=1784749",
        },
        {
            id = 1724463,
            score = 0,
            author = "Whiterock",
            text = "Sha in the Monastery Quest Tree From Whiterock\n[pre]The Ordo Warbringer (http://www.wowhead.com/quest=30660){A2 (http://www.wowhead.com/quest=30662),H1 (http://www.wowhead.com/quest=30661),H2 (http://www.wowhead.com/quest=30663)}* Barrels of Fun (http://www.wowhead.com/quest=30651){H} (http://www.wowhead.com/quest=30656)* Pandaren Prisoners (http://www.wowhead.com/quest=30650){H} (http://www.wowhead.com/quest=30655)*\n                           └──────┼───────────────┘\nCall Out Their Leader (http://www.wowhead.com/quest=30457)* [ins]S[/ins])The Shado-Pan (http://www.wowhead.com/quest=31455){H} (http://www.wowhead.com/quest=31453) Hit Medicine (http://www.wowhead.com/quest=30460)* All of the Arrows (http://www.wowhead.com/quest=30459)*\n ||                  └────┐        ||       /             /\na)Turnabout (http://www.wowhead.com/quest=30670)             a)The Defense of Shado-Pan Fallback (http://www.wowhead.com/quest=30665)    [ins]+[/ins])Holed Up (http://www.wowhead.com/quest=30682)\na)Unmasking the Yaungol (http://www.wowhead.com/quest=30690)\nb)To Winter's Blossom (http://www.wowhead.com/quest=30699)\n ||                \\\nb)A Line Unbroken (http://www.wowhead.com/quest=30715) b)Honor, Even in Death (http://www.wowhead.com/quest=30723)\n    \\             /\n    b)To the Wall! (http://www.wowhead.com/quest=30724)\n    /             \\\nc)Off the Wall! (http://www.wowhead.com/quest=30750)   c)A Terrible Sacrifice (http://www.wowhead.com/quest=30751)\n ||                /\nd)Lao-Chin's Gambit (http://www.wowhead.com/quest=30994)\nd)Do a Barrel Roll! (http://www.wowhead.com/quest=30991)\nd)Finish This! (http://www.wowhead.com/quest=30992)──────>My Husband... (http://www.wowhead.com/quest=30768)*\n ||\nf)Where are My Reinforcements? (http://www.wowhead.com/quest=30993)\nf)Unbelievable! (http://www.wowhead.com/quest=30752)\n[ins]S[/ins])Into the Monastery (http://www.wowhead.com/quest=31030){backup version (http://www.wowhead.com/quest=31031)}(Shado-Pan Monastery)\n[ins]#[/ins])Lord of the Shado-Pan (http://www.wowhead.com/quest=30757)(Shado-Pan Monastery)\n\n[ins]#[/ins])The Path to Respect Lies in Violence (http://www.wowhead.com/quest=31342)(Shado-Pan Monastery)\n\nLegend:\nS means Skippable\n+ means Can start anytime, prequests not needed.\n{H} means Quest Have Horde Variant, click {H} for it.\n* means another Quest Tree.[/pre]\n\nYes, there are SUCH WEIRD prequests, even more weird that it have breadcumb with other prequests.",
            date = "2012-09-29T12:05:28-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30751#comments:id=1724463",
        },
    },
    [30752] = {
        {
            id = 1718975,
            score = 131,
