    },
    [30767] = {
        {
            id = 1716476,
            score = 32,
            author = "dvation",
            text = "If you accepted the quest and talked to Asya, making her walk up the stairs without realizing it like I did, Asya is nowhere to be found. You'll have to abondon the quest and Asya will reappear instantly in front of the ship (roughly 39,83). You'll have to follow her up the stairs to have the video sequence start to complete the quest.",
            date = "2012-09-20T21:21:49-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30767#comments:id=1716476",
        },
        {
            id = 1663925,
            score = 4,
            author = "Krastopic",
            text = "Once you turn in the previous quest for kill Vordraka, you will be offered a quest from Aysa.  Once she provides this quest, be ready to follow her back into the ship.  She will climb the stairs to the top level of the ship where you will hear a dialog about blowing up the ship.\n\nThere must be an unfinished animation coming here because my screen went black and then the word Boom appeared (Mists Beta).  Once this is done, a new scene is revealed with the ship gone and Ji Firepaw standing there ready to accept your quest turn in.",
            date = "2012-05-07T14:21:26-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30767#comments:id=1663925",
        },
        {
            id = 1656479,
            score = 3,
            author = "selvin",
            text = "I was having a terrible time figureing out how to do this, I was wandering around looking for something I needed to toggle, then realized- just talk to the questgiver, Aysa. That starts a sequence so she and Ji can fight it out to complete the quest.",
            date = "2012-04-20T11:03:45-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30767#comments:id=1656479",
        },
        {
            id = 2010687,
            score = 3,
            author = "Foxpaw",
            text = "I find it increasingly difficult to sympathize with the Horde methodology.",
