            text = "In the cinematic after this quest, Ji's hair style and facial hair changes. Seems Blizz decided to change it after they done this cinematic.",
            date = "2013-10-12T14:08:22-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30767#comments:id=1907972",
        },
