    [30774] = {
        {
            id = 1747175,
            score = 37,
            author = "884267",
            text = "I cried a bit when I found Lin. :(",
            date = "2012-10-21T12:12:14-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30774#comments:id=1747175",
        },
        {
            id = 1756210,
            score = 25,
            author = "Xarthat",
            text = "(Spoilers below)\n\nI found Lin's situation very mirroring of one particular case from vanilla. A spouse in despair sends you in search of the other spouse. Upon looking for the spouse among the living (by which I mean both the living Pandaren and the other people in /1) you finally find the missing spouse, lying beaten and dead on the ground, killed by a race of savage animal-people. Once the news breaks, the remaining spouse swears vengeance against the people who killed her partner.\n\nR.I.P. Lin Silentstrike, a.k.a. Mankrik's Wife II.",
            date = "2012-11-03T11:36:15-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30774#comments:id=1756210",
        },
        {
            id = 1671272,
            score = 22,
            author = "42463",
            text = "Most of the cages are open. Search for closed cages inside tents, dont bother with those outside,  and you can complete the quest.",
            date = "2012-05-28T23:22:23-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30774#comments:id=1671272",
        },
        {
            id = 1721993,
            score = 6,
            author = "Roaning",
            text = "There are 2 other quests in this area along with this one and the freed prisoners will stay with you, they also do a decent amount of dps. It's a good idea to get the 4 prisoners first and then focus on the others.\n\nYou can also farm for a while as well if you like since the mobs drop a decent amount of cloth.",
            date = "2012-09-27T18:37:02-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30774#comments:id=1721993",
        },
        {
            id = 1664986,
            score = 4,
            author = "515790",
            text = "The spearguards, and the 3 named mini-bosses all have a chance to drop the stones to open the cages around the camp.\n\nThe body of Lin Silentstrike can be found just south of the tent containing Ku-Tong, under the pinkish tree in the camp centre. He is sprawled on the floor outside of an open cage.\n\nInteracting with him triggers a small set piece with Suna Silentstrike.",
            date = "2012-05-10T02:32:00-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30774#comments:id=1664986",
        },
    },
    [30775] = {
