            text = "As of 15913 -- Pick up the quest, banner is on my back, but no button comes up to put banner into the pile to start the fight. Abandoned and picked it back up repeatedly with the same result. Also tried with and without addons.",
            date = "2012-07-29T12:40:12-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30776#comments:id=1693627",
