    [30777] = {
        {
            id = 1740571,
            score = 8,
            author = "greystoker",
            text = "The \"Caravan\" is the wagon directly behind Ban Bearheart.",
            date = "2012-10-13T15:05:01-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30777#comments:id=1740571",
        },
        {
            id = 1848714,
            score = 5,
            author = "sitecow09",
            text = "While in the caravan, Yalia Sagewhisper the priest and Ban Bearheard the shaman have a conversation about Suna, her husband Lin's recent death and how she blames Ban for it due to his caution in dealing with the Yaungol:\nY: Ban, you look worried.\nB: Yes well... it's not like Suna to run off by herself.\nY: She must be torn by grief over here husband's death.\nB: She blames me, you know.\nY: That may be, but it was no one's fault.\nB: I should have taken the risk and sent the order to attack.\nY: You did what you thought was best. No commander has the foresight to see the future.\nB: But now... she hates me.\nY: You swore the Shado-Pan blood oath together, did you not? You are bound together by powers far stronger than hatred. No, she cannot hate you. At least not forever. Hahaha!\nB: I hope so, Yalia.",
            date = "2013-04-30T19:07:41-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30777#comments:id=1848714",
        },
        {
            id = 1907796,
            score = 5,
            author = "112088",
            text = "It wasn't mentioned so I figured I would lay out the quests in this chain.\n\nAfter turning this quest in Ban Bearheart (http://www.wowhead.com/npc=60687) will provide you with the quests Dust to Dust (http://www.wowhead.com/quest=30778) and Slaying the Scavengers (http://www.wowhead.com/quest=30779). In addition, Xiao Tu (http://www.wowhead.com/npc=60903) will provide Last Toll of the Yaungol (http://www.wowhead.com/quest=30781) and Yalia Sagewhisper (http://www.wowhead.com/npc=60864) provides Totemic Research (http://www.wowhead.com/quest=30780). Upon completing all four quests, Yalia Sagewhisper will provide What Lies Beneath (http://www.wowhead.com/quest=30827) which she follows up with Hatred Becomes Us (http://www.wowhead.com/quest=30783) and Ban Bearheart provides Spiteful Spirits (http://www.wowhead.com/quest=30782). Turning both of these quests in will result in Ban Bearheart providing the final quest in the chain, The Point of No Return (http://www.wowhead.com/quest=30784) which provides an item level 442 chest as a reward.",
            date = "2013-10-11T23:22:00-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30777#comments:id=1907796",
        },
        {
            id = 1803274,
            score = 4,
            author = "silveress",
            text = "The caravan is directly behind the quest giver, Ban Bearheart. You do not need to dismount to aboard the Shado-Pan Caravan wagon. You'll travel for about 30 seconds down a trail and be dropped off in Hatred's Vice in the center of a dirt path. The caravan will disappear a few seconds.\n\nIf your caravan is bugged, you can turn in the quest while avoiding it altogether.\n\nTo turn in the quest, walk 10 yards to Ban Bearheart behind the bonfire and earn 8 gold, 24 silver. After completing the quest, Yalia Sagewhisper, Ban Bearheart, and Xiao Tu will reveal new available quests.\n\nEasy breezy. Nothing difficult about this quest at all.",
            date = "2013-01-24T00:37:18-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30777#comments:id=1803274",
        },
        {
            id = 5866752,
            score = 3,
            author = "Wylsyn",
            text = "Yes, you can fly straight to the quest destination without having to ride the caravan.",
            date = "2024-05-26T16:48:34-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30777#comments:id=5866752",
        },
    },
    [30778] = {
        {
            id = 1818518,
            score = 3,
            author = "352773",
            text = "Attempting to use Corpse Explosion on the bodies yields the message \"Target is still alive\".\n\nOh god...",
            date = "2013-02-26T15:01:28-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30778#comments:id=1818518",
        },
        {
            id = 1868704,
            score = 3,
            author = "yzerman",
            text = "If you arrive at Hatred's Vice and there are no NPC's, you likely haven't completed the https://www.wowhead.com/quest=30776 questline. I spent an hour reloading my UI, disabling add ons and and filing a ticket before I figured this out.",
            date = "2013-06-21T01:07:05-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30778#comments:id=1868704",
        },
        {
            id = 1921833,
            score = 1,
            author = "yoshimario40",
            text = "It's too bad the undead forces are gone now otherwise Blizzard might've been able to do some sort of \"Burning-bodies-so-the-others-don't-take-them\" reference. You know, to keep with the Shado'pan |||| Night's Watch parallel.",
            date = "2013-11-28T02:25:22-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30778#comments:id=1921833",
        },
        {
            id = 2044346,
            score = 1,
            author = "braneman",
            text = "My favorite quest in the entire expansion, just seeing an entire village of dead yaungol that won't respawn, or patrol into me, no massive aggro distance either. I could actually quest through here without having to pull four mobs and a rare elite every time I so much as moved. Its therapeutic I almost don't want to kill Suna because of how much of a pain it was to quest in any area with yaungol in it.",
            date = "2014-11-22T09:21:52-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30778#comments:id=2044346",
        },
        {
            id = 2297711,
            score = 1,
            author = "Daedralia",
            text = "STOP\nPair them up\nDust to Dust (http://www.wowhead.com/quest=30778/dust-to-dust)\nand\nSlaying the Scavengers (http://www.wowhead.com/quest=30779/slaying-the-scavengers)\n\nDo your self a favor and do them together\nDon't complete the Dust to Dust (http://www.wowhead.com/quest=30778/dust-to-dust) before you finish Slaying the Scavengers (http://www.wowhead.com/quest=30779/slaying-the-scavengers)\n\nUsing the Shado-Pan Torch (http://www.wowhead.com/item=81356/shado-pan-torch)\ntarget ashfang-hyena  (http://www.wowhead.com/npc=60932/ashfang-hyena) you can group them up by agro run then hit them with the torch (http://www.wowhead.com/item=85261/shado-pan-torch) killing them\n\nIt appears the damage on this item was not changed when health was squished. This still does 10k per second, an instant kill for most creatures in the zone. Doesn't seem to work on the vultures in the zone however. It made that part of the quest chain relatively carefree for me :) A huge shout out to Credit Zoruman (http://www.wowhead.com/user=Zoruman)\nThis seems to be yet another item that accidentally gets left in your bags after you have completed the quest. you can delete it",
            date = "2016-01-13T11:04:41-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30778#comments:id=2297711",
        },
    },
    [30779] = {
        {
            id = 1793087,
            score = 1,
            author = "sweboy99",
            text = "The place is overcrowded with hyenas and vultures, so why Blizzard decided to make us kill only 8 is a mystery. 30 would be more of a fitting number, combined with https://www.wowhead.com/npc=66368.",
            date = "2013-01-05T13:15:56-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30779#comments:id=1793087",
        },
    },
    [30780] = {
    },
    [30781] = {
        {
            id = 1824945,
            score = 464,
            author = "sivla",
            text = "Make sure you have your companion with you, or you get no credit at all..if he dies or goes missing, go back to where the quest giver is, and pick him back up again.",
            date = "2013-03-08T23:26:23-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30781#comments:id=1824945",
        },
        {
            id = 1866458,
            score = 87,
            author = "Bogdanov89",
            text = "Do not forget to talk to the NPC so he follows you!\n\nYou only get quest credit if the NPC (Xiao Tu) follows you to the locations of the smoke!",
            date = "2013-06-14T03:45:04-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30781#comments:id=1866458",
        },
        {
            id = 5861314,
            score = 78,
            author = "estarianne",
            text = "If you're here in remix and can't figure out how to complete this quest make sure you spoke to Xiao Tu so he can follow you and  investigate the camp.\n\nHe also despawns if you leave the area or if you go into a dungeon using the queue so you'll have to go talk to him again.",
            date = "2024-05-21T14:59:45-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30781#comments:id=5861314",
        },
        {
            id = 1721822,
            score = 75,
            author = "919381",
            text = "Below are the coordinates:\n\nEastern Smoke Trail: 84.83 x 71.47\nWestern Smoke Trail: 81.10 x 71.98\nSouthern Smoke Trail: 83.47 x 78.55\nNorthwestern Smoke Trail: 83.94 x 70.79",
            date = "2012-09-27T15:30:13-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30781#comments:id=1721822",
        },
        {
            id = 1760114,
            score = 60,
            author = "theliterarygirl",
            text = "The southern smoke location is not where the marker shows it to be on the map. The marker points you to a hut up an incline on a hill, but it is actually directly downhill at a bonfire.",
            date = "2012-11-10T03:56:34-06:00",
