    [30793] = {
        {
            id = 1730654,
            score = 49,
            author = "g0urra",
            text = "This quest is so sad - [spoiler]seeing the two mistwalkers die, as well the guy at the end, broke my heart. :([/spoiler]",
            date = "2012-10-04T02:29:35-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30793#comments:id=1730654",
        },
        {
            id = 1735437,
            score = 33,
            author = "Draenors",
            text = "Upon engaging this mob on my Shaman, I instantly dropped a Searing Totem, causing him to yell the following before despawning:\n\n\"Searing Totem... you must be the one that's been helping these pitiful mistlurkers.\"\n\nI found that quite amusing.",
            date = "2012-10-08T09:02:11-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30793#comments:id=1735437",
        },
        {
            id = 1737256,
            score = 6,
            author = "CMKCot",
            text = "The objective NPC is currently bugged, if you kite him beyond his deagro distance, around 200yards, he wont deagro like he should and will instead become inmortal. if kited to the nearby shadopan base guards will spawn in hordes to kill him but he wont despawn, evadebug or die.\n\ni found this by accident when i was helping a lowbie warrior kill a 90 hunter who ganked him while he was on this quest. i drew healing agro from the mob and kited him as i was healing the warrior.\n\neventually the warrior killed the hunter near the shadopan base, by that time i had accidentally triggered this bug. i can verify that if you kite the mob to the shadopan base another copy WONT spawn, so people leveling will get really angry at you, and if you AVOID his own spawn location you can actually kite him all over pandaria.\n\nto debug him, run back to the NPC spawn location and he ill do his attack where he shields himself, then dies.",
            date = "2012-10-10T07:03:28-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30793#comments:id=1737256",
        },
        {
            id = 1817446,
            score = 6,
            author = "208249",
            text = "Dialogue during this quest-\n\n[fight begins]\nJahesh of Osul yells: [Class]... you must be the one that's been helping these pitiful mistlurkers.\n[Jahesh throws torches, becomes immune, and starts to channel a spell, focusing on Golgoss first]\nJahesh of Osul yells: That's enough!\nJahesh of Osul yells: I have enough torches to erase all three of you!\nJahesh of Osul yells: The elements shield me!\nJahesh of Osul yells: If you refuse to bend to the torch, you will die to the torch!\nGolgoss says: No...\n[Golgoss dies]\nJahesh of Osul yells: You're next, small one!\nArconiss says: Too... strong...\n[Arconiss dies]\nJahesh of Osul says: There's another mistlurker here... I can smell his stink.\nJahesh of Osul yells: Don't think I can't see you back there, hiding in the shadows...\nJahesh of Osul yells: You resist the power of the torch... why won't you die, beast?\n[Orbiss starts to move forward despite being the target of the deadly spell]\nOrbiss says: Because my will...\nOrbiss says: ...the will of my people...\nOrbiss says: ...is stronger than yours.\n[Orbiss summons something that stops Jahesh's spell and causes him to no longer be immune]\nJahesh of Osul yells: No... NO!",
            date = "2013-02-23T16:03:42-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30793#comments:id=1817446",
        },
        {
            id = 1735549,
            score = 5,
            author = "912282",
            text = "Something that I found useful for completion.\n\nStay with the group when Orbiss starts to leave the area, this will cause all three to go with you.\n\nI flew directly from the quest giver to the NPC mob and only Orbiss spawned (not the other two)",
            date = "2012-10-08T10:56:55-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30793#comments:id=1735549",
        },
    },
