    [30795] = {
        {
            id = 1724946,
            score = 14,
            author = "515518",
            text = "Talk to Mishi after getting this quest (unmounted) and you will fly to a new area.  Right click on the Tongue of Ba-Shon.  Hand in the quest.",
            date = "2012-09-29T17:37:26-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30795#comments:id=1724946",
        },
        {
            id = 1733358,
            score = 4,
            author = "920389",
            text = "After you dismount on Valley of Emperors, use the Tongue on the ground.\nIt will summon image of Lorewalker Cho, allowing you to turn in the quests.",
            date = "2012-10-06T12:07:55-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30795#comments:id=1733358",
        },
        {
            id = 1733610,
            score = 4,
            author = "Bonnyebrynn",
            text = "If you lose your tongue, talk to this Mishi! [npc=60887 domain=www]",
            date = "2012-10-06T16:40:25-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30795#comments:id=1733610",
        },
        {
            id = 2002548,
            score = 2,
            author = "Takata",
            text = "Just talk to Mishi, she will fly you down to where you need to be. No need to walk down there yourself!",
            date = "2014-09-14T06:48:55-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30795#comments:id=2002548",
        },
        {
            id = 1792079,
            score = 1,
            author = "1070670",
            text = "I declined the quest from Lorewalker Cho after I went inside the temple at the Valley of Emperors to complete the tablet. Turns out that I need that quest to be able to go on to Zouchin village. It keeps telling me that I'm not in the right zone when I try to summon him with the tongue of Ba-Shon and Mishi will not take me back to Valley of Emperors. Any suggestions?",
            date = "2013-01-03T19:54:00-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30795#comments:id=1792079",
        },
    },
    [30796] = {
        {
            id = 1797819,
            score = 19,
            author = "858226",
            text = "51.7, 46.5  - worked for me turning in the Tongue.",
            date = "2013-01-13T10:26:09-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30796#comments:id=1797819",
        },
        {
            id = 1694825,
            score = 12,
            author = "datgrl",
            text = "Tongue of Ba-Shon can only be used in certain areas. If you complete a quest where you must use the item to communicate with Cho, you should stay in the area of the quest before moving on to do something else.\n\nI had several other quests in the same general area. I moved on to do something else and then started looking around to try to turn in quests that required invoking the Tongue of Ba-Shon. I got a message about not being in the right zone. There are several quests in this chain that require you use the item, complete one and pick up next in the chain.",
            date = "2012-08-01T10:11:10-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30796#comments:id=1694825",
        },
        {
            id = 1739117,
            score = 8,
            author = "60302",
            text = "It seems that if you continue on to Zouchin Village before turning in this quest, Lorewalker Cho shows up in the village, and if you turn in the quest https://www.wowhead.com/quest=30935, you will lose the tongue. When this happens, you currently have no way to turn this quest in.\n\nThe moral of the story is: Don't forget to turn this quest in while you're in the Valley of the Emperor because if you wait until afterwards, you may not be able to complete it.",
            date = "2012-10-12T02:50:41-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30796#comments:id=1739117",
        },
        {
            id = 1751892,
            score = 4,
            author = "Black2u",
            text = "Valley of the Emperors is in Kun-Lai Summit and it is a small stair step spot where you will find an entrance to The Tomb of Shadows.  If you look at the npc map above where the spirits have to be slain that is where you can click the The tounge of Ba-shon and the NPC you are looking for will appear.  Just go to the areas indicated on the wowhead map for the spirits!  Hope that helps!",
            date = "2012-10-27T15:01:40-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30796#comments:id=1751892",
        },
