        {
            id = 1723702,
            score = 16,
            author = "Maurek",
            text = "If you can't find the NPC to turn in this quest to, go to 55,47 area and click [The Tongue of ba-Shon] from your bags and then he will appear for the turn in.",
            date = "2012-09-28T22:55:41-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30797#comments:id=1723702",
        },
        {
            id = 1691867,
            score = 4,
            author = "735486",
            text = "I accepted this quest but somehow I never got a page.  Then I noticed it's one of those weird little hands that appears when you mouse over the book; I didn't see it at first.",
            date = "2012-07-24T23:44:58-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30797#comments:id=1691867",
        },
        {
            id = 1724949,
            score = 4,
            author = "515518",
            text = "When you accept the quest make sure to right click on the book again to get the Torn Page.  The quest starts at 57.1, 47.9",
            date = "2012-09-29T17:38:56-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30797#comments:id=1724949",
        },
    },
    [30798] = {
        {
            id = 2016927,
            score = 49,
            author = "BlizzardCS",
            text = "UPDATE: We didn't get any further report, so it seems like the issue is indeed totally fixed. Thanks all for your patience and understanding while we were working on it.\n\nUPDATE 11/11/2014: This issue should be fixed by now. Please, if you are still experiencing this issue let us know so we can look into it. :)\n\nHello all!\n\nJust wanted to let you know that there’s a bug right now with this quest. https://www.wowhead.com/npc=60572 is despawning during the encounter, making it impossible to complete the quest. Our developers are already investigating this and looking for a solution. Thanks for your patience!",
            date = "2014-10-21T12:04:55-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30798#comments:id=2016927",
        },
        {
            id = 5858729,
            score = 28,
            author = "xLunacyx",
            text = "Nakk just stood there and did nothing.  Likely because I was already standing there as he respawned.\nYou just have to run out and back in to trigger his script.",
            date = "2024-05-18T17:18:56-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30798#comments:id=5858729",
        },
        {
            id = 1724351,
            score = 25,
            author = "Vallix",
            text = "Tomb entrance at 53.3, 49.2, engage Nakk'rakas and he sends a few statues at you, kill them then him and done.",
            date = "2012-09-29T10:30:53-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30798#comments:id=1724351",
        },
        {
            id = 2015361,
            score = 24,
            author = "j3nesis",
            text = "Just in case - at patch 6.0 this quest is bugged. Nakk'rakas just shields himself and despawns, along with the statues, when aggroed. Multiple threads on the official forums have confirmed this. If this happens to you and you cannot complete the quest, submit an ingame bug report.",
            date = "2014-10-18T15:32:09-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30798#comments:id=2015361",
        },
        {
            id = 1676280,
            score = 7,
            author = "232139",
            text = "The tomb is not actually on the \"highest rise.\" If you come to a small cave called Emperor Rikktik's Rest, you are too high up. Follow the path back to the north, then make the first two rights you come to.\n\nAs for the quest itself, in the current beta build it's quite dull. There is a named troll (Nakk'rakas (http://mop.wowhead.com/npc=60572)) in the tomb. You will only be able to hit him once to aggro him, then he will go immune and begin awakening the stone guardians around him one by one by one. I think I killed five before his shield dropped and I was able to finish him off.",
            date = "2012-06-13T10:15:40-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30798#comments:id=1676280",
        },
    },
    [30799] = {
        {
            id = 1724753,
            score = 90,
            author = "741980",
            text = "Note: you have to summon Image of Lorewalker Cho using  The Tongue of Ba-Shon in your inventory in the zone Valley of Emperors on order to turn this quest in.",
            date = "2012-09-29T15:21:13-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30799#comments:id=1724753",
        },
        {
            id = 1723962,
            score = 39,
            author = "Nyplock",
            text = "The Cave Entrance for Tomb of Shadows is at 56,46.\n\nThe artifacts can be found:\n\nOne in middle of room, and the other two, one on each side.",
            date = "2012-09-29T02:50:23-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30799#comments:id=1723962",
        },
        {
            id = 1724957,
            score = 13,
            author = "515518",
            text = "To go to the cave go to 55.9, 46.2, which is up the stairs from the quest give location.\n\nShen Dynasty Rubbing: 57.1, 43.5 on the right of the big statue.\n\nWay Dynasty Rubbing 56.3, 43.4 under the pillar, its half covered.\n\nQiang Dynasty Rubbing 57.1, 45.0 by a red chest.\n\nUse The Tongue of Ba-Shon to hand in the quest.",
            date = "2012-09-29T17:45:57-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30799#comments:id=1724957",
        },
        {
            id = 1703519,
            score = 12,
            author = "493853",
            text = "To reach the entrance of Tomb of Shadows, climb the only stairs you see around where https://www.wowhead.com/npc=61641 is. Turn right and you'll see a building with a narrow and high gateway. That is Tomb of Shadows.",
            date = "2012-08-23T17:04:22-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30799#comments:id=1703519",
        },
        {
            id = 1676427,
            score = 7,
            author = "selvin",
            text = "Note for all you people who skip quest text like me, you need to go inside the entrance to the tomb, not the ruins around you.",
            date = "2012-06-13T21:01:13-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30799#comments:id=1676427",
        },
    },
    [30800] = {
        {
            id = 1719066,
            score = 102,
            author = "324040",
            text = "Entrance to tomb of Conquerors is at 53 46.5",
            date = "2012-09-25T18:20:58-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30800#comments:id=1719066",
        },
        {
            id = 1676282,
            score = 59,
            author = "232139",
            text = "If you're having trouble finding the Tomb you need, from the location of the last quest, simply follow the path north. The path will turn sharply downhill and curve right until you come to an entrance southwest into the mountain.",
            date = "2012-06-13T10:20:37-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30800#comments:id=1676282",
        },
        {
            id = 1661783,
            score = 34,
            author = "124958",
            text = "Inside the Tomb of Elements is great fun. It's full of booby traps in certain areas, pay attention to the paving stones that you walk on, the ones which have images on them of elements (Air, Fire and Lightning)\n\nThe fire paving stone will go on fire, causing damage to you.\nThe air paving stone will knock you back giving you some slight damage.\nThe lightning paving stone will crackle with electricity.\nThere is also one other to look out for, which has 3 arrows on it. If you step on that one the sidewalls shoot fire out of them.",
            date = "2012-05-02T14:15:06-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30800#comments:id=1661783",
        },
        {
            id = 1665316,
            score = 23,
            author = "Draugar",
            text = "As you enter the tomb be aware of the stone tiles with patterns, they will harm you in some way.\n\nOnce in the tomb you will access a container, upon access the two stone lions on either side will attack. Once you have dispatched them you need to walk near the guardian. He will then attack.\nUpon killing the guardian travel further into the next room to locate the tablet.",
            date = "2012-05-10T22:46:28-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30800#comments:id=1665316",
        },
        {
            id = 1724141,
            score = 21,
            author = "ggregt",
            text = "I dropped this quest because I didn't have sound on and once cinematics start you can't turn on sound. Quest item disappeared from bags, rather than resetting and I couldn't see other's Chos, so now I have to figure out how to retake this quest.\n\nFrom GM Response to my ticket for this: Go back to the Entrance of the Valley of the Emperors and speak to Mishi. She will give you another one. And she did! Mishi is at 58,49 in the Valley of Emperors, Kun-Lai Summit.",
            date = "2012-09-29T06:40:16-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30800#comments:id=1724141",
        },
    },
    [30801] = {
        {
            id = 1724982,
            score = 163,
            author = "515518",
            text = "Entrance is at 53.0, 46.5.  Tablet is at 34.1, 61.8, you will see a gear in your minimap.  A cinematic will kick in which will open the door to the tomb.  Use the Tongue of Bo-Shan to hand in the quest.",
            date = "2012-09-29T18:06:45-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30801#comments:id=1724982",
        },
        {
            id = 2368218,
            score = 17,
            author = "Dougeh",
            text = "Now featuring Trolls doing the moon walk!",
            date = "2016-08-15T12:53:29-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30801#comments:id=2368218",
        },
        {
            id = 1746620,
            score = 8,
            author = "CallMeNoa",
            text = "Cutscene when you read it:\n\nLorewalker Cho says: Under Kun-Lai (http://www.wowhead.com/zone=5841) Thunder sleeps...\nLorewalker Cho says: The storm long spent there rests...\nLorewalker Cho says: But blood of brother kingdom keeps...\nLorewalker Cho says: Alive the dispossessed...\nLorewalker Cho says: By Zandalari (http://www.wowpedia.org/Zandalari) blood he will be taken...\nLorewalker Cho says: To Zandalari Voice he will awaken...\n\nZandalari troops led by Prophet Khar'zul (http://www.wowhead.com/npc=61541) run in.\n\nProphet Khar'zul says: Secure da remains, bruddahs!\nProphet Khar'zul says: Da Thunder King (http://www.wowpedia.org/Thunder_King) shall live again...\nProphet Khar'zul says: Hahahahaha!",
            date = "2012-10-20T17:04:12-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30801#comments:id=1746620",
        },
        {
            id = 1731215,
            score = 6,
            author = "HGFenn85",
            text = "If you lose the Item The Tongue of Ba-Shon get it from Mishi at the entrance where he/she dropped you off.",
            date = "2012-10-04T12:42:29-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30801#comments:id=1731215",
        },
        {
            id = 2024305,
            score = 6,
            author = "Warow",
            text = "The cutscene in this quest is bugged, the trolls walk backwards down the stairs as of   patch 6.0.3",
            date = "2014-11-04T11:04:15-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30801#comments:id=2024305",
        },
    },
    [30802] = {
        {
            id = 1720383,
            score = 41,
            author = "whsocko",
            text = "These guys are in the Tomb of Conquerors.  They were all dead the first time I went in, so I didn't see any, and went back out and rode all around for a long time looking for them  :(\n\nStay in the Tomb, they spawn there around the edges of the main room where the Tomb Watchers are.\n\nEdit: I had to kill 10 or more before the map dropped.",
            date = "2012-09-26T15:28:18-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30802#comments:id=1720383",
