    [30804] = {
        {
            id = 1729138,
            score = 10,
            author = "Sagira",
            text = "He must of made a very satisfying \"thump\" when he hit the ground.\n\nGYARR! Must have! Not must of!",
            date = "2012-10-02T19:49:30-05:00",
