    [30817] = {
        {
            id = 1753457,
            score = 3,
            author = "228976",
            text = "Do it with a group or else you'll take forever to finish it. You have to get 12 priests/druids etc to go to the wound and heal it BUT they will be attacked while you're trying to round up more. so best idea is to leave someone by the recruited healers to protect them while the rest go recruit more healers.\nVERY frustrating to try and solo.",
            date = "2012-10-29T21:42:45-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30817#comments:id=1753457",
        },
        {
            id = 1782112,
            score = 1,
            author = "1026168",
            text = "Truly, this is meant to be done as a group. The mobs spawn far too quickly to protect multiple healers on your own. If a mob even targets a 'freed' healer it's distracted until that mob is dead. That is, unless you'd like to practice grab-that-aggro footwork. Personally, I like the lazy questing route. See Focus Target and Follow Target for instance-healing (not recommended near cliff-edges).\n\nBut not all of us are so fortunate as to find groups for quests. So, if soloing:\n\nFind a healer only being attacked by one creature. I found one at (42.8, 85.2), by the water with the Copper Vein. (Frustration leads to Mining; who knew?) Surely there are more like him. Free your one healer from his/her attacker, and then park yourself right there. As the attacker respawns, it'll see you and leave your healer alone, and you'll kill it however you like, over and over and over. That healer will stay on the turtle permanently, effectively leaving you to deal with only one creature at a time for the entirety of this quest. The quest will last awhile, but it'll be easy, and you won't have to go running around headless-chicken style.\n\nAlthough that might be fun to watch.",
            date = "2012-12-15T22:19:01-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30817#comments:id=1782112",
        },
    },
