    [30821] = {
        {
            id = 1970000,
            score = 56,
            author = "Tigerfeli",
            text = "Not having quested at all in [zone=5841] I didn't see this available straight away.\n\nYou must complete https://www.wowhead.com/quest=30744 and https://www.wowhead.com/quest=30746 to open up https://www.wowhead.com/quest=30747 and the daily version of that quest (this page) to get https://www.wowhead.com/item=97980 needed to unlock the Brawlers Guild boss https://www.wowhead.com/npc=70677.\n\nWord of warning, you must keep killing Hozen even after completing the 100/100 kills required for the daily to get https://www.wowhead.com/item=97980. It will pop up on your screen like personal loot does in LFR/Flex. It's been reported to take 500+ kills or as little as 30, seems to be 100% RNG.\n\nHappy hunting!",
            date = "2014-06-04T10:18:20-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30821#comments:id=1970000",
        },
        {
            id = 1720768,
            score = 28,
            author = "BanicRhys",
            text = "For whatever reason, you must compete with other players for mob tags on this quest, despite the fact you are all mounted on the same yeti.",
            date = "2012-09-26T20:42:09-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30821#comments:id=1720768",
        },
        {
            id = 1820864,
            score = 27,
            author = "346630",
            text = "There's no grind here. Quest is repeatable because it's fun.\n\nIt is, in fact, pretty fun.\n\nThe daily rewards experience and gold every time, but no ongoing accumulation of rep or tokens or anything.",
            date = "2013-03-04T11:25:59-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30821#comments:id=1820864",
        },
        {
            id = 1723132,
            score = 21,
            author = "Jollygood",
            text = "This is a wildly entertaining quest and a nice change of pace. You mount a large female yeti and go King (Queen) Kong on enemies on the Burlap Road (nice play on Silk Road).\n\nThe three actions are to pound them, blow them back, or eat one to restore health.\n\nI suggest that each time the cooldown passes to eat one, do so. You get something like 450-500K health back on the yeti each time. Everything in Pandaria is pretty irritable, so you need to do that. The little guys are not just melee, but cast spells and they appear to alert each other.\n\nI was delighted this is a repeatable quest.\n\nI have not shared the quest, so I wonder if that is what BanicRhys is talking about above. I had to compete with other players to get the traders, but each of us was on a separate yeti. Kills are not shared like they are with quest NPCs (the ones where someone else will tap the NPC, but you get the kill too). As the population of players spreads out through the new content, the crowding problems and their attendant glitchiness will be less of a problem.",
            date = "2012-09-28T13:08:29-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30821#comments:id=1723132",
        },
        {
            id = 1734891,
            score = 15,
            author = "Marwan1584",
            text = "Is there any rep associated with this daily? It looks like there isn't, but I wanted to see if any knew for sure.",
            date = "2012-10-07T19:26:20-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30821#comments:id=1734891",
        },
    },
    [30823] = {
