    [30827] = {
        {
            id = 1724991,
            score = 5,
            author = "nosfas",
            text = "At this date this quest is still bugged.\nThe Totem of Serenity can't be clicked.\n\nBut I found a work-around.\n\nIt's very simple, find a key on your keyboard that isn't beeing used.\n\n- Press Esc\n- Select Key Bindings\n- Find the key binds group \"Targeting Functions\".\n- In this group, find \"Interact With Target\"\n- Click on the first \"not bound\" and press the unused key.\n- Close the menu.\n\nNow, type on your chat the following:\n/tar totem of serenity\n\nAnd press the key you just bounded to \"Interact With Target\".\nYou might get an error, asking you to approach your target, do so, and keep pressing the key.\n\nYou should now have started the event.\nKill the spawned NPC\n\nDone!\n\nI hope this helps someone. :)",
            date = "2012-09-29T18:14:26-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30827#comments:id=1724991",
        },
        {
            id = 1892531,
            score = 3,
            author = "Mirrodin",
            text = "You should be careful to either be very near to Yalia or very far away from her, i was like between near and far and one freekin totem spawn on me so i stucked inside it and i could not move, i was ready to use hearthstone but luckily i am a warlock so i used demonic gateway to teleport and unstuck.",
            date = "2013-09-03T06:20:40-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30827#comments:id=1892531",
        },
    },
