    [30855] = {
        {
            id = 1721526,
            score = 171,
            author = "Iheartbeer",
            text = "When Shai Hu goes immune, grab a nearby Explosive Hatred (http://www.wowhead.com/npc=61530), drag it into the bubble and kill it.",
            date = "2012-09-27T08:24:30-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30855#comments:id=1721526",
        },
        {
            id = 1946663,
            score = 30,
            author = "critter6206",
            text = "To kill Shai Hu you must pull one Enraged Hatred inside his shield and kill that before you may kill Shai Hu. Doing this will remove his shield.",
            date = "2014-02-25T11:43:01-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30855#comments:id=1946663",
        },
        {
            id = 1728334,
            score = 26,
            author = "1038799",
            text = "It is not necessary to wait for Shai Hu to go immune and then drag explosive sha into his shield. Another way to complete this quest (for a paladin and, I assume, for any other class with good AOE attacks) is to aggro about four or more of the explosive sha as you approach Shai Hu then his shield will not even go up and the kill becomes just a normal tank and spank with your AOEs to kill sha/damage Shai Hu and other attacks for more damage to Shai Hu.\nI did it this way by chance/accident and Shai Hu went down like a skittle. Hope this helps :)",
            date = "2012-10-02T06:10:55-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30855#comments:id=1728334",
        },
        {
            id = 5191574,
            score = 9,
            author = "Firelocked",
            text = "I know this is an old thread. And I am greatful for all of the helpful posts. But damn, why does Blizzard have to make it that difficult to make us go here in the middle of a fight to see what to do? I am just venting, but geeeze! That said, it was still a pretty clever quest. But we could have had a hint!",
            date = "2021-06-06T07:52:26-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30855#comments:id=5191574",
        },
        {
            id = 2424841,
            score = 7,
            author = "dsptchr68",
            text = "Seems silly after dieing twice, but as a mage, walk raight in and stand next to him pulling a couple of shadows with you.  then use Arcane explosion a couple of time and down he goes.",
            date = "2016-10-09T07:58:56-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30855#comments:id=2424841",
        },
