    [30880] = {
        {
            id = 1748497,
            score = 38,
            author = "775937",
            text = "This is a Chun Li Street fighter reference in case anyone missed it",
            date = "2012-10-23T07:02:42-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30880#comments:id=1748497",
        },
        {
            id = 1746655,
            score = 18,
            author = "586983",
            text = "You fight each fighter in a different location for this quest, if they aren't there, wait for them. It takes a moment for them to respawn after someone has defeated them already:\n\nhttps://www.wowhead.com/npc=60994 780k Health\n\nFight Location: The gazebo slightly northeast of where you got the daily, not the one directly within view.\nThe Fight: She has a spinning crane kick that does a bit of damage and slows movement, you can either move out of the way or just push through it. Chi Torpedo will knock you back if you're in front of her. She doesn't do much damage overall.\n\nhttps://www.wowhead.com/npc=60978 1.2M Health\n\nFight Location: Directly north of the last fight, inside the building.\nThe Fight: Has a standard whirlwind attack, also has a Death From Above attack where he simply jumps. Nothing notable.\n\nhttps://www.wowhead.com/npc=61013 1.2M Health\n\nFight Location: East of the Main Temple\nThe Fight: Throws heavy dynamite, does a little damage. Periodically 4 fuses will ignite and move towards the pile of dynamite in the center. When it ignites, it does damage and has a knockback. I stood near the edge of the ring when it happened, and I'm unsure if damage increases when you're closer. Standing on the edge, it was negligible.\n\nhttps://www.wowhead.com/npc=61013 2M Health\n\nFight Location: Main Temple\nThe Fight: Wind sword will do damage and knock you back quite a bit if you're in front of him. Windfur Punch will immobilize you and do some damage.",
            date = "2012-10-20T18:07:16-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30880#comments:id=1746655",
        },
        {
            id = 2021812,
            score = 8,
            author = "reidsb",
            text = "Seems to spawn Brewmaster Chani exclusively now, making this quest impossible to complete.",
            date = "2014-11-01T04:23:05-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30880#comments:id=2021812",
        },
        {
            id = 1817865,
            score = 6,
            author = "madmurdock",
            text = "Dont be confused, if some of the other fighters appear instead of this one. It is probably a bug. After defeating the other fighter the actual NPC spawns for the quest. Of course its quite annoying...",
            date = "2013-02-24T21:21:41-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30880#comments:id=1817865",
        },
        {
            id = 2055991,
            score = 6,
            author = "zilista",
            text = "Tried to complete this quest today.  No NPC will spawn in the area.  Can confirm you can not complete this quest.  I have submitted a bug.",
            date = "2014-12-01T19:45:06-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30880#comments:id=2055991",
        },
    },
    [30881] = {
        {
            id = 2546587,
            score = 31,
            author = "1130800",
            text = "Um... for some reason the door to the temple is closed. Other players were also having the same problem. Is there a key or something to get in?\n\nEdit: If the door to the temple is closed (bug) you can kill yourself near the door (>help >stuck >transport to nearest graveyard) then walk in using your spirit form before you resurrect. You can port out or repeat the stuck process. A pain, but it works.",
            date = "2018-01-17T23:55:44-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30881#comments:id=2546587",
        },
        {
            id = 1763247,
            score = 10,
            author = "173610",
            text = "If you're doing this quest at a time when there's other people around, while there's no need to secure the tag, you do need to deal some damage to each of the two at some point during the fight to get quest credit for both.",
            date = "2012-11-16T08:41:10-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30881#comments:id=1763247",
        },
        {
            id = 1741529,
            score = 5,
            author = "574644",
            text = "This quest has you fighting Ashyo & Ken-ken, two of the pupils seeking the Hidden Master from back in the Valley of the Four Winds (http://www.wowhead.com/quest=30086). It would seem they've reunited after splitting up on their search, although they still haven't learned to work together...",
            date = "2012-10-14T15:27:34-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30881#comments:id=1741529",
        },
        {
            id = 1744772,
            score = 4,
            author = "amgyn",
            text = "Another easy fight.\nWater spouts from the Jinyu and Whirlwind from the Hozen.",
            date = "2012-10-18T09:58:52-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30881#comments:id=1744772",
        },
        {
            id = 2563164,
            score = 4,
            author = "Malachi68",
            text = "Chadiwicker is correct. The way to do this quest (if you're stuck in front of a closed door) is to stand next to the door and then fly up fairly high. Then drop yourself to the ground (i.e. release the mount) in order to die. When you are at the graveyard, go to the right of the rez-angel and click your way up the mountain. It's not easy but it is do-able. When you get to the door, go through and then resurrect.\n\nAfter the fight, Xuen will be in the room so that you can turn in the quest and get the next round. Then your can hearthstone out of the room to wherever and repeat as necessary.",
            date = "2018-04-16T16:49:51-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30881#comments:id=2563164",
        },
    },
    [30882] = {
        {
            id = 1746814,
            score = 24,
            author = "Dongolev",
            text = "Amusingly, talk to Xuen before you defeat Kang. He'll say:\n\n\"I was once defeated in a match by a Bramblestaff. In my defense, he distracted me with a ball of yarn.\"",
            date = "2012-10-21T00:07:18-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30882#comments:id=1746814",
        },
        {
            id = 2551305,
            score = 19,
            author = "Babos1234",
            text = "I done it, u die near at Kang (near temple),just fly high and die, then res inside temple. But after that i picked up round 3 quest, u can't go outside because of the closed doors... so i just picked up round 3 quest, and used my hearthstone, but the problem is, when i arrived back quest lost......and still can't go in pick up next quest because doors ..",
            date = "2018-02-07T15:56:14-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30882#comments:id=2551305",
        },
        {
            id = 1753339,
            score = 9,
            author = "Genox113",
            text = "If this guy isn't where your quest arrow is pointing just wait a few moments and he will show up. He will be at 71,45.",
            date = "2012-10-29T17:38:07-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30882#comments:id=1753339",
        },
        {
            id = 2567496,
            score = 8,
            author = "Kanoxia",
            text = "I've been on this quest chain today, the only way I was able to complete it without hearthing and the quest bugging out on me was to do the following:\n\nKill your character outside the doors by flying into the air and unmounting as mentioned by Babos1234\n\nResurrect inside the building for your particular mob, then kill and accept the next quest from Xuen\n\nRather than Hearthing, use the Character Stuck option inside the Help Menu and select Teleport to Graveyard\n\nRun back res outside the building where your body is and continue on the chain.\n\nOnce you reach Round 4 Master Windfur, you have to run up to the gates then use the Character Stuck/Teleport to Graveyard option for the game to kill you, so that you can res inside the gates.\n\nThis is long winded as you have to do this each time, but its the only way I found that worked for me\n\nI hope this is of some use to others!\n\nEdit; I think if your hearthstone is not on cool down, selecting Teleport to Graveyard uses your hearthstone in the first instance so just to be sure the quest doesn't bug out, make sure to use your hearthstone before attempting to complete this chain.",
            date = "2018-05-14T17:03:17-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30882#comments:id=2567496",
        },
        {
            id = 2561433,
            score = 7,
            author = "Matiotwk",
            text = "If the doors are bugged, and are closed.\nWhat I did, after reading a comment reply from user Fc3sHightower (https://www.wowhead.com/user=Fc3sHightower) - Was to die as close to the doors as possible. Release spirit, go inside the middle of the door, facing outwards. Resurrected, and planted Zhevra Lounge Cushion (https://www.wowhead.com/item=116691/zhevra-lounge-cushion). Then when you are done with the quest, just click the cushion, and you will be out of the room again.\n\nSadly, you will have to do this on every door that is bugged. So there will still be some running from the graveyard.\n\nThis is also possible to do with other toy cushions:\nFuzzy Green Lounge Cushion (https://www.wowhead.com/item=116692/fuzzy-green-lounge-cushion)\nPineapple Lounge Cushion (https://www.wowhead.com/item=116689/pineapple-lounge-cushion)\nSafari Lounge Cushion (https://www.wowhead.com/item=116690/safari-lounge-cushion)\n\nThese are all obtainable from Stolen Present (https://www.wowhead.com/item=116762/stolen-present) during Feast of Winter Veil (https://www.wowhead.com/feast-of-winter-veil)",
            date = "2018-04-05T12:51:17-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30882#comments:id=2561433",
        },
    },
    [30883] = {
        {
            id = 1744775,
            score = 15,
            author = "amgyn",
            text = "3rd fight in the chain.\n\nTo make sure he doesn't grab you and throw you around, click on the chairs to stun him. Just time his current stun and throw another chair when he moves again.\n\nAgain, simple fight - he throws sweat at you - eew.",
            date = "2012-10-18T10:02:21-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30883#comments:id=1744775",
