            text = "If you are a [class=3], just send in your pet and head to the edge of the floor and chuck a chair at https://www.wowhead.com/npc=60997 whenever he is not stunned.",
            date = "2013-03-13T13:01:55-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30883#comments:id=1828044",
        },
    },
    [30884] = {
        {
            id = 1808143,
            score = 1,
            author = "bobahop",
            text = "My first instinct was to fight the mantids on the way to Taoshi. I discovered this was not the best plan as I got swarmed and overwhelmed. Once I decided to  avoid the mantids and reached Taoshi I received the quest Unwelcome Intruders (http://www.wowhead.com/quest=30887) to kill those same mantids with her help. Revenge was sweet.",
            date = "2013-02-02T13:14:35-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30884#comments:id=1808143",
        },
        {
            id = 1943116,
            score = 1,
            author = "Simonds22",
            text = "The word \"Burrow\" had me looking for a cave-like entrance or a hole in the ground but she is actually standing high up on the cliff at 76,78.",
            date = "2014-02-13T23:14:14-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30884#comments:id=1943116",
        },
        {
            id = 1962775,
