            text = "I did\n\nImprovised ammunition\nCutting the swarm\nTerror of the dread waste\nAlong the southern front\nEnraged by Hatred\nTaking Stock\nJoining the fight\nUp in flames\n\nQuest and seriously HE DIDN'T GAVE ME THE Behind the Battlefront quest.",
            date = "2014-05-02T20:44:36-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30884#comments:id=1962775",
        },
    },
    [30885] = {
        {
