            text = "When he does the jump to the middle and 4 fuses comes out, you're able to extinguish them by running over them and then the barrels won't explode.",
            date = "2012-12-31T06:28:11-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30885#comments:id=1790077",
        },
        {
            id = 2550684,
            score = 8,
            author = "1130800",
            text = "If the door to the temple is closed (bug) you can kill yourself near the door (>help >stuck >transport to nearest graveyard) then walk in using your spirit form before you resurrect. You can port out or repeat the stuck process. A pain, but it works.",
            date = "2018-02-04T18:08:40-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30885#comments:id=2550684",
        },
        {
            id = 1995447,
            score = 2,
            author = "369872",
            text = "The NPC you have to fight is in a small building to the left of the main building as you are facing it.  The coords are 66.7, 46.5",
            date = "2014-08-24T00:08:54-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30885#comments:id=1995447",
        },
        {
            id = 2573043,
            score = 1,
            author = "Erithmael",
            text = "Doors bugged? Simple instructions:\n\nSet your hearthstone to the Temple of the White Tiger.\nComplete quests as far as you can until you reach the closed doors.\nFly up, dismount, then fall to your death near the doors.\nResurrect inside the bugged room. You can ghost right through the doors.\nComplete the fight and accept new quest in the new room.\nHearth out.\nContinue questing.\n\nInnkeeper:\n/way 66.8 51.0 Master Lao\n\nDo not use any hearthstones or teleports that take you out of Pandaria after you resurrect inside. You will have to start over!",
            date = "2018-06-09T19:12:38-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30885#comments:id=2573043",
        },
    },
    [30887] = {
        {
            id = 1725625,
            score = 7,
            author = "Nulgar",
            text = "Like a true rogue, Taoshi only joins the fight when the enemy is already at low health.",
            date = "2012-09-30T05:55:20-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30887#comments:id=1725625",
        },
        {
            id = 1767813,
            score = 5,
            author = "alpanhell",
            text = "for some reason on my hunter Taoshi doesn't help if my pet hits mob first, just if I do.",
            date = "2012-11-25T16:44:57-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30887#comments:id=1767813",
        },
        {
            id = 1759975,
            score = 1,
            author = "challme",
            text = "Got bugged in this quest too, every time i was about to kill a mob, the rogue killed him and no kill for me, same with the polen i had to pick, i could even see the violet flowers sparkling",
            date = "2012-11-09T19:41:17-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30887#comments:id=1759975",
        },
        {
            id = 1790151,
            score = 1,
            author = "aoeu",
            text = "Wish I had a wingman like this all the time.  I must say the 1st time Taoshi helped me, it almost looked like a hunter was targeting me.",
            date = "2012-12-31T10:58:20-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30887#comments:id=1790151",
        },
        {
            id = 1801180,
            score = 1,
            author = "Daherado",
            text = "I see other people have noticed issues with this quest.\nI seem to have stumbled across a good one..\nWhen Taoshi joins you in combat she puts a debuff on the target, [spell=127662 domain=www]\n\nOn my feral druid, 5 combo points, no special trinket buffs or procs the best crit ferocious bite i had was 67k\nWith Taoshi's debuff that rocketed up to a whopping 145k, more than half of the mantids health.\nNow im not great at maths, but even i can see the difference between 67k and 145k is way more than 15%....",
            date = "2013-01-19T18:02:24-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30887#comments:id=1801180",
        },
    },
    [30888] = {
        {
            id = 1721605,
            score = 17,
            author = "slayer50513",
            text = "A few facts:\nThe mantid are stealthed, but leave a long orange trail behind them.\nDespite being marked as aggressive, they are passive and will only attack when they are assaulted first.\nThey can be one hit killed with the traps from this quest (http://www.wowhead.com/quest=30889) which you pick up at the same spot as this one.\n\nSo, to make this extremely easy, just look for an orange trail, arm a trap, then attack the mantid and run over the trap. Tada! +1 to this quest.",
            date = "2012-09-27T09:20:31-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30888#comments:id=1721605",
        },
        {
            id = 1722216,
            score = 10,
            author = "Guy19",
            text = "Protip: attack a https://www.wowhead.com/npc=61373, then lure them into a set https://www.wowhead.com/npc=61426 for a 1 hit kill - thus getting https://www.wowhead.com/quest=30889 & https://www.wowhead.com/quest=30888 very easily. Note that it seems to only kill one per trap.",
            date = "2012-09-27T22:19:57-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30888#comments:id=1722216",
        },
        {
            id = 1815035,
            score = 8,
            author = "98367",
            text = "Requires completion of Unwelcome Intruders to be seen.",
            date = "2013-02-18T02:15:26-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30888#comments:id=1815035",
        },
        {
            id = 1808708,
            score = 7,
            author = "935620",
            text = "Surprised to not see this comment here so let me add it: These guys have a NASTY stacking bleed.  You do not need to activate the flare, you can hit them with aoe damage.  The point is, be careful if you're not a strong healing class.  If you accidentally aoe a bunch of these guys that DOT can easily be the death of you. :)",
            date = "2013-02-03T17:45:02-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30888#comments:id=1808708",
        },
        {
            id = 1671678,
            score = 5,
            author = "95724",
            text = "The Krik'thik Scentlayers don't aggro until you attack them.",
            date = "2012-05-30T06:56:58-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30888#comments:id=1671678",
        },
    },
