            author = "grapnor",
            text = "Whenever you click on a Gao-ran solider some times the will quote the HBO show/book series Game of Thrones. Some of the quotes include:\n\"I am the sword in the darkness.\" and\n\"I am the watcher on the walls.\"",
            date = "2012-09-30T00:54:24-05:00",
