        {
            id = 1676710,
            score = 3,
            author = "selvin",
            text = "Note you need Injured gao-ran Blackguards, not defenders.",
            date = "2012-06-14T18:38:32-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30892#comments:id=1676710",
        },
        {
            id = 1726487,
            score = 3,
            author = "UtesDad",
            text = "For those wondering how to complete this quest, you're best bet is to go to the opposite end of the valley from where the defenses are set up.   Near the defenses there are Blackguards, but they are running away and you can't heal them.  Go to the opposite end and look for bodies on the ground.",
            date = "2012-09-30T19:32:07-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30892#comments:id=1726487",
        },
    },
    [30893] = {
        {
            id = 1750955,
            score = 21,
            author = "103837",
            text = "You will not get credit for kills when the mobs are hit by artillery. Since the artillery only hit in the quest area located on the map, the best option is to go outside of it, either to the west or south.\n\nIn this way you can also avoid pulling a lot of adds, since the mobs there are farther apart.",
            date = "2012-10-26T13:43:24-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30893#comments:id=1750955",
        },
        {
            id = 1735186,
            score = 7,
            author = "1042299",
            text = "Make sure to pick up https://www.wowhead.com/quest=30894 as the limbs for that drop off the attackers.",
            date = "2012-10-08T03:29:45-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30893#comments:id=1735186",
        },
        {
            id = 1747258,
            score = 7,
            author = "Hildur",
            text = "Killing these mobs seems to have a high rate of not counting, by which i mean not give quest credit or even xp. My best bet was going towards the dread wastes, where the guards weren't hit by bombs from the pandas, as it seems the boms made the mob not count.\n\nYou can also stay behind where the bombing rigs are and have them not be hit by them. That way you don't have to travel very far from the questgiver.",
            date = "2012-10-21T14:30:06-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30893#comments:id=1747258",
        },
        {
            id = 1736697,
            score = 3,
            author = "Totergott",
            text = "Careful with your AoE's or else you're just @#$%ed",
            date = "2012-10-09T14:11:23-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30893#comments:id=1736697",
        },
        {
            id = 1854734,
            score = -3,
            author = "708567",
            text = "I did a bit of experimenting to figure out why mobs weren't giving credit and I have figured it out. You will only get credit for these mobs if you deal the killing blow. Even if they only have 10 hp left as long as you hit them last you get the credit. So just stay in the quest assigned area and aim carefully!",
            date = "2013-05-20T13:58:01-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30893#comments:id=1854734",
        },
    },
    [30894] = {
