    [30895] = {
        {
            id = 1776112,
            score = 17,
            author = "SirNorek",
            text = "So I was working on this chain, when suddenly I was unable to get this next quest in the chain -\nImprovised Ammunition - turns out that at this point you need to finish the 3 quests from https://www.wowhead.com/npc=61470 at which point Taran will open up Improvised Ammunition!",
            date = "2012-12-05T13:40:23-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30895#comments:id=1776112",
        },
        {
            id = 1676719,
            score = 15,
            author = "selvin",
            text = "Make sure to grab Thieves and Troublemakers (http://mop.wowhead.com/quest=30896) and In the wrong hands (http://mop.wowhead.com/quest=30897) next to the quest area, as you have to farm the same mobs.",
            date = "2012-06-14T19:26:18-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30895#comments:id=1676719",
