        {
            id = 1793673,
            score = 4,
            author = "Alechs777",
            text = "Well, I was doing that quest. I saw something similar to these orbs (bah, I'm wearing glasses, so...). I have taken that. I was suprised - it wasn't an orb, but a gray item, called \"Amber Encased Moth\"...It's sell price was 105G.",
            date = "2013-01-06T12:26:12-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30895#comments:id=1793673",
        },
        {
            id = 1690979,
            score = 3,
            author = "Yinxy",
            text = "In the Ambermarsh is where you can find these orbs. You can either get them from:\n\n* Agitated Nettleskins whom can drop m\n* Picking them up. Most I found where attached to tree trunks.",
            date = "2012-07-22T07:57:57-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30895#comments:id=1690979",
        },
        {
            id = 5878234,
            score = 2,
            author = "Ehayen",
            text = "Odd thing about this quest: You cannot loot the orbs if the \"engaged in combat\" flag is on. So using a stun on a mob and then looting the orb will not work.",
            date = "2024-06-10T15:04:32-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30895#comments:id=5878234",
        },
    },
    [30896] = {
        {
            id = 1933984,
            score = 3,
            author = "forever1267",
            text = "Annoying little guys, and about half of them have the orbs.  Others can be found on the ground.    Also found https://www.wowhead.com/item=86472  buried in this area too, which goes towards the [hsachievement=7997] Riches of Panderia achievement.\n\n(My first post!)",
            date = "2014-01-12T16:57:07-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30896#comments:id=1933984",
        },
        {
            id = 1732673,
            score = -2,
            author = "353008",
            text = "Could be mistaken but i believe this is a Firefly reference.\n\nThe Firefly crew troublemakers and when you complete this quest the guy (Initiate Feng) yells \"Yeah, you better run!\" which is a quote from the show when Mal is left naked and having had something stolen from him (which he stole himself).\n\nOf course i could just be looking too hard for Firefly because i miss it.\n\n---\nStraight forward quest, follow the road down and they are all over the place :).",
            date = "2012-10-05T20:45:06-05:00",
