    [30900] = {
        {
            id = 1673075,
            score = 11,
            author = "Meili",
            text = "This is a phased fight. So if you still see many mobs, try relogging.\n\nHe does several abilities, now I don't remember the names.\n\nBurrows underground.\nDoes an ability that is similar to Atramedes; Sonar Pulse\n\nAvoid the Sonar Pulse[Not the correct name] ability. It deals a lot of damage.\n\nBut overall, he is an easy fight, even though he is considered elite.",
            date = "2012-06-03T12:20:56-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30900#comments:id=1673075",
        },
        {
            id = 1727654,
            score = 8,
            author = "Dorfie",
            text = "1/10/12 - Working at this moment.\n\nKilling him yield's, 100k xp with guild perks with no one else around fighting him (its a phased fight) - abandon quest, re pick up, wait 30secs - 1min for him to respawn - kill him for another 100k xp rinse and repeat.\n\nFaster then doing most quests:",
            date = "2012-10-01T15:40:06-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30900#comments:id=1727654",
        },
        {
            id = 1817946,
            score = 4,
            author = "553717",
            text = "As in most fights, watch for the circles denoting the aoe of his spells and run out of them.  Follow Taoshi's advice to get behind the barricades, use this for a quick heal or mana replen and the chance to kill another couple of bugs... they will come.  As others have stated, you can farm it for exp by killing, looting (Miners, don't forget to mine the corpse after looting, every little bit helps!),  abandoning the quest, and then retaking it.  Here's the good news: My main, fully rested, garnered 188k and change for xp at 95% of level 89.  As MatteoG says here \"just mob grinding in a cleverer way\"",
            date = "2013-02-25T04:06:44-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30900#comments:id=1817946",
        },
        {
            id = 1816259,
            score = 3,
            author = "1093608",
            text = "I use this method w/ all my lvl 88 toons but i do it w/ rested state so i get 210k exp per kill.  Also remember to loot the kill, sometimes cool stuff drops.",
            date = "2013-02-20T22:33:03-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30900#comments:id=1816259",
        },
        {
            id = 5878236,
            score = 2,
            author = "Ehayen",
            text = "Wait, why do the launchers become inert as soon as the boss mobs appear? Why can't I just use those on the worms?",
            date = "2024-06-10T15:14:02-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30900#comments:id=5878236",
        },
    },
    [30901] = {
        {
            id = 1749709,
            score = 53,
            author = "madmurdock",
            text = "It was bugging for me. Taoshi stuck half of the way and a yellow question mark wouldnt pop up. A relog helped me and i could turn in the quest.",
            date = "2012-10-24T18:27:24-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30901#comments:id=1749709",
        },
        {
            id = 1720885,
            score = 14,
            author = "Tyro",
            text = "The \"ride with\" part of this quest is not mandatory or a caravan you click on or anything like that.  You just mount up and ride along side with the two NPCs if you want to hear some RP.  Alternatively, you can just ride to the destination on your map at your own convenience and complete it just the same.",
            date = "2012-09-26T22:26:50-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30901#comments:id=1720885",
        },
        {
            id = 5863490,
            score = 14,
            author = "Jayfan34",
            text = "Still bugged in Remix.  Rode along with them the whole way, they just disappeared when they got to the tree nearby and didn't appear till I relogged.",
            date = "2024-05-23T07:43:25-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30901#comments:id=5863490",
        },
        {
            id = 2544721,
            score = 8,
            author = "wordslinger1919",
            text = "Update for 1/8/18: still bugged and I did ride along with the NPC's. Tried /reload and it did not work. Did a relogin and it DID work.",
            date = "2018-01-09T00:39:32-06:00",
