    [30902] = {
        {
            id = 1804224,
            score = 5,
            author = "313976",
            text = "After defeating Master Windfur, Xuen yells \"Well done! I name you the Champion of Strength! May your enemies tremble before your title.\" This is not an actual character title that you can use :(",
            date = "2013-01-25T23:33:39-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30902#comments:id=1804224",
        },
        {
            id = 2550685,
            score = 5,
            author = "1130800",
            text = "If the door to the temple is closed (bug) you can kill yourself near the door (>help >stuck >transport to nearest graveyard) then walk in using your spirit form before you resurrect. You can port out or repeat the stuck process. A pain, but it works.",
            date = "2018-02-04T18:22:17-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30902#comments:id=2550685",
        },
        {
            id = 1901928,
            score = 2,
            author = "DKilbourne",
            text = "A little more detailed information about the fight.\n\nHe casts whirlwind, a tornado-effect, and a gusting wind; the last two do a fair amount of knockback, which can be annoying for spellcasters.\n\nOtherwise, it's a pretty standard fight. I fought him as a Shadowpriest, and I used Void Tentacles to keep him in place, and simply went through my rotation. When VT stopped, I had a second or two of a cooldown period, but he didn't hit too bad.  Just drop the VT once more and continue spanking.",
            date = "2013-09-23T12:21:30-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30902#comments:id=1901928",
        },
        {
            id = 2561438,
            score = 2,
            author = "Matiotwk",
            text = "The doors where closed here as well. I Used my flying mount to get in. By the Temple entrance, I flew up as high as possible to the hallway ceiling. Then tilted my mount backwards (camera tilt) while flying forward and sticked myself to the ceiling. I was then dismounted pass the doors/gates. Discovered this by coincidence. So I tried this a few more times after, just to confirm.\nStill stuck getting outside again though.",
            date = "2018-04-05T13:09:53-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30902#comments:id=2561438",
        },
        {
            id = 2003965,
            score = 1,
            author = "jobjob",
            text = "This was somewhat odd. He was all like 'Wind is my ally!' as I was throwing pyroblasts and other forms of fire at him and that's when it hit me. I was running about with my 'Firelord' title fighting one of the only 'wind- /airbenders' in the game.\n\nYup.",
            date = "2014-09-18T18:33:14-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30902#comments:id=2003965",
        },
    },
    [30907] = {
        {
            id = 1697532,
            score = 145,
            author = "Hakunamatata",
            text = "Judging by the name (for those of you too PUGish to scroll up or look at the browser title, it'shttps://www.wowhead.com/quest=30907), you have to afk for a few seconds and let the team destroy itself.",
            date = "2012-08-08T12:58:16-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30907#comments:id=1697532",
        },
        {
            id = 1697604,
            score = 99,
            author = "SirGentleshark",
            text = "Tankiss seems to be, as his companions state, \"Too Squishy\" - he will consistently blame Healiss for not healing him (He does so by yelling at his companion).\n\nHealiss performs Priestly spells - those of a Shadow Priest while in Shadow Form - he insists on stating that he's being a good healer and that Tankiss is just \"Too Squishy\" - he mostly remains out of range of his companions to be able to cast anything of use on them.\n\nHackiss will talk (and complain) about loot throughout the fight - he'll also attempt to backstab the player for a fairly weak amount of damage - in fact, he seems to try to pickpocket you more often then he tries attacking you.\n\nSo they're pretty much your average P.U.G.",
            date = "2012-08-08T16:11:29-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30907#comments:id=1697604",
        },
        {
            id = 1741830,
