            author = "Kozzie",
            text = "the supplies are located 56.6, 54 - they are planted on the ground in a small growing area to the left of the steps of the first hut coming up the road.  Red arrows will be above them pointing down.  The weapons racks are located at 55.3, 53 - again small red arrows over the top of them are pointing down to identify them.",
            date = "2012-09-30T23:51:34-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30923#comments:id=1726682",
