        {
            id = 5864121,
            score = 66,
            author = "Zinovia",
            text = "In Pandaria Remix there are still no red arrows over the weapons. The target area at 55.3, 53 looks like a bunch of fence rails rather than weapons. Just blow up that area to finish. It's not at all obvious.",
            date = "2024-05-23T23:14:46-05:00",
