        },
        {
            id = 5877752,
            score = 49,
            author = "Cimegs5088",
            text = "In Panda remix, if you happened to complete all 5-6 quests together before coming back to turn in, chance are you will see an empty camp, just relog and you should be able to see the NPC to turn in them (probably need the quest surprise attack done where you help the npc attack on niuzhao temple)",
            date = "2024-06-09T16:08:33-05:00",
