    [30943] = {
        {
            id = 1801230,
            score = 3,
            author = "sidelsky18",
            text = "For some reason, if you collect more than 50 and try to delete the extras before you turn it in, it will actually delete all of them and abandon the quest.",
            date = "2013-01-19T20:23:10-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30943#comments:id=1801230",
        },
        {
            id = 1724145,
