        {
            id = 1924651,
            score = 1,
            author = "Tuub",
            text = "The terrible drop rate is a refreshing throwback to the old bad days when four basilisks shared one brain between them. The trolls attacking the village don't seem to drop any blades, only the ones lower in the valley.",
            date = "2013-12-09T07:02:50-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30945#comments:id=1924651",
        },
        {
            id = 1993742,
            score = 1,
            author = "shrikearghast",
            text = "Don't waste time on the Hexxers or the frost guys. These drop only from the Raptor Handlers (which are somewhat uncommon) and the Skull-Breakers. Expect about a 1-in-3 to 1-in-4 drop rate. I had to kill about 15 of both to finish, but I have had it take as many as 30 to get the job done. It's a frustrating quest in a rather strange sub-zone. The storyline doesn't really go anywhere beyond the next couple of quests, and a number of missions down in this valley are frustrating (the gnoll quests are a really cluster****, too).",
            date = "2014-08-19T15:56:13-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30945#comments:id=1993742",
        },
    },
