    [30953] = {
        {
            id = 1795743,
            score = 14,
            author = "GloriaCura",
            text = "Today this quests is bugged. A lot of players are complaining that there are no wounded Sentinels.\nIt's also not possible to find food for the other quest in the whole temple and outside.\nDid anyone had this problem before?",
            date = "2013-01-10T05:19:41-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30953#comments:id=1795743",
        },
        {
            id = 1775307,
            score = 6,
            author = "fredd13",
            text = "Most of the sentinels spawn in the lower portion of the area, close to the wall and behind swathes of Sra'thik (who are on a frustratingly short respawn if, like me, your DPS isn't all that hot). Stand on the wall above the sentinels to use the Yak's Milk (or healing spell of your choice) without aggroing the mobs below.",
            date = "2012-12-04T08:28:42-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30953#comments:id=1775307",
        },
        {
            id = 1744027,
            score = 5,
            author = "638512",
            text = "You can use your own healing spells which might be better and faster than the quest item given that heals 16k per tick.",
            date = "2012-10-17T11:29:49-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30953#comments:id=1744027",
        },
        {
            id = 1775271,
            score = 5,
            author = "Mairin",
            text = "If in a group, you can have 1 person start the heal and then stop and have another start and finish it and you both get double credit as if you'd healed seperate sentinels.",
            date = "2012-12-04T06:40:20-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30953#comments:id=1775271",
        },
        {
            id = 1739620,
            score = 1,
            author = "uriahworld",
            text = "Found around the quest area, use https://www.wowhead.com/item=82381 to heal NPCs.",
            date = "2012-10-12T14:05:07-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30953#comments:id=1739620",
        },
    },
    [30954] = {
        {
            id = 1764143,
            score = 14,
            author = "Aisenfaire",
            text = "The blades can be obtained in 2 ways:\n\n1) Spawns: Find them lying on the ground, always hugging the wall.\n2) Drops: Kill Sra'thik attackers (the bugs), and some will randomly drop these weapons on the ground.  You'll see them glittering.  It goes well with https://www.wowhead.com/quest=30952; you can do them together.\n\nImportant:  The weapons that drop from mobs:\n\n Are lootable by ANYONE --> try not to farm for them in an trafficked spot.  Also be nice and don't ninja weapons lying next to other people that they worked so hard to kill mobs for.\n Last only for about 10 seconds, and then despawn --> It is therefore pointless to AOE groups of more than 4 or 5 for these as you won't be able to loot all the weapons before they despawn (looting has a cast time)",
            date = "2012-11-18T06:17:33-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30954#comments:id=1764143",
        },
        {
            id = 1981837,
            score = 1,
            author = "Hirotoro",
            text = "Progress description:\n\"Our men are accustomed to fighting with maces and clubs. Unfortunatly, we have little time for customs.\"\n\nUnfortunately, the person who wrote the text here had little time for spell checkers.",
            date = "2014-07-18T13:55:19-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30954#comments:id=1981837",
        },
        {
            id = 1655172,
            score = -5,
            author = "Samaramon1",
            text = "60g? Oh my.",
            date = "2012-04-17T04:11:16-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30954#comments:id=1655172",
        },
    },
    [30955] = {
        {
            id = 1735351,
            score = 107,
            author = "541563",
            text = "If your niuzao strongarm does not appear you need to log out and log back in. Dropping and reaccepting the quest does not work and once your strongarm has disappeared he doesn't reappear until you've logged back in.\n\nEdit: The strongarm does not attack but he will draw aggro. be careful not to let him die.",
            date = "2012-10-08T07:16:56-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30955#comments:id=1735351",
        },
        {
            id = 1754749,
            score = 25,
            author = "RinnovaRaine",
            text = "You want a fun challenge, do this quest three separate times and only get one type of food each time (IE Bushels, Baskets, etc.)..  Hilarity ensures when he's loaded up with six bushels..\n\nShould be an achievement for doing it this way imo..",
            date = "2012-11-01T03:31:13-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30955#comments:id=1754749",
        },
        {
