    [30956] = {
        {
            id = 1742092,
            score = 12,
            author = "Fyonella",
            text = "25 seems like a lot if you have to kill them 'manually' as it were, but if you time it right, you can pull several packs, making sure you are in the centre of the upper pathway. Niuzao, the huge Yak that runs around will stomp them all as he passes. As long as you've done some damage to them prior to him running through you'll get full credit for the kills.",
            date = "2012-10-15T05:36:06-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30956#comments:id=1742092",
        },
        {
            id = 1763523,
            score = 8,
            author = "Mirrodin",
            text = "I don't know why but today i got this quest but Niuzao wasn't running around the temple, he was simply standing at his usual spot at the temple.\nI don't know if it matters but the other 3 quests were: the big guns, in battle's shadow and the overwhelming swarm.",
            date = "2012-11-16T21:06:37-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30956#comments:id=1763523",
        },
        {
            id = 1744006,
            score = 6,
            author = "QuickBASIC",
            text = "You can continue to us https://www.wowhead.com/item=82346 (from https://www.wowhead.com/quest=30959) even after that quest is complete to destory War Wagons to summon a swarm of 125k mobs at half health to complete this relatively quickly. Best thing to do is always start with the war wagons and pick up the last 2-3 you'll need after.",
            date = "2012-10-17T10:50:03-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30956#comments:id=1744006",
        },
        {
            id = 1813708,
            score = 3,
            author = "847245",
            text = "Also! IIRC this daily is picked up on the same day as https://www.wowhead.com/quest=30959, and the Sra'thik War Wagons, which are to be destroyed as a requirement for the aforementioned quest, house about 7 or 8 Sra'thik's who, once killed, actually give you credit for this quest. So doing the two quests in unison will get you the 3 War Wagons destructions AND the 25 Sra'thik attacker kills! It should be noted that the Sra'thik inside the wagons are significantly weaker and have about 1/3 the health of a normal Sra'thik attacker. Happy questing!",
            date = "2013-02-14T20:40:46-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30956#comments:id=1813708",
        },
        {
            id = 1813705,
            score = 1,
            author = "847245",
            text = "Idunno about anyone else but I just stood by the 4-5 guards in each corner and pulled 2 or 3 of them to the guards' vicinity so that they helped me kill them. It's not as nice as Niuzao himself, but he's not a reliable advantage compared to the guards. They make take some time for the aggro to register, but they do help.",
            date = "2013-02-14T20:30:38-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30956#comments:id=1813705",
        },
    },
