        {
            id = 2108914,
            score = 2,
            author = "781755",
            text = "The dailies at this hub are bugged.  When In Battle's Shadow, The Overwhelming Swarm, and The Big Guns are offered, the objects and NPCs for Fallen Sentinels and Paying Tribute are spawned and vice versa.  Just keep the quests in your log and go back another day to complete them so you can still get the rep gains.  It's a crappy solution, but Blizzard does not appear to be too keen on fixing this any time soon.  I hope this helps those of you who came here out of frustration like I have.",
            date = "2015-02-17T10:09:07-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30957#comments:id=2108914",
        },
    },
