    [30968] = {
        {
            id = 2292017,
            score = 103,
            author = "Jigro",
            text = "Aright so if you are like me and want to kill him for The tranquil master achievment but haven't done any quests at all in the zone then here's what ya need to do: You need to go to the Gao-Ran battlefront and speak with Taran Zhu. Pick up his quest and every other quest you can find there. Continue to do all the quests and as you progress in the storyline Taran Zhu will eventually travel west to the bridge. Continue to do the quests there and he will travel to Rensai's watchpost where he needs to be. After he is there do the quest that leads you to Hawkmaster Nurong a bit below the watchpost and then he will lead you back to Taran Zhu. After all that is done he will give you the quests to go down and kill the Sha of Hatred.\nSo basically just go to the Gao-Ran battlefront and do every quest you find - just progress through the story.\nDepending on how much you've quested in the zone Taran Zhu may already be at the bridge or at the watchpost, if that's the case just pick up the quests from there.\nAll the quests took me about 20-30 minutes to do.\nHope this helps",
            date = "2015-12-26T13:10:58-06:00",
            sourceUrl = "https://www.wowhead.com/quest=30968#comments:id=2292017",
        },
