    [30978] = {
        {
            id = 5275694,
            score = 61,
            author = "stef8950",
            text = "Hi Guys, so of patch 9.1.5 this quest has a bug that you can't shoot the klaxxi in the sky, don't know if it was there before, but i have been doing pandaria leveling when it launched. so i found a work around for this, if anyone is wondering and frustrated like i was about this, you have to shoot the klaxxi coming from the cliff right in front of the cannon, they are the only ones you can kill. you will know when you hit one :) also, when the boss spawns, select it with your mouse, and aim at the hit box (the circle beneath it) and you should be good :) hope this can help somebody :D",
            date = "2021-11-04T15:24:46-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30978#comments:id=5275694",
        },
        {
            id = 5858870,
