            id = 1747091,
            score = 34,
            author = "713689",
            text = "This quest does not have a map marker, so if you get distracted halfway through it may sit in your quest log for some time unfinished (I know, I know...).  To get back on track, return to the Serpent's Spine gate near Winter's Blossom in the South West of Kun-Lai Summit.  Suna Silentstrike is in the tower on the Northern side of the gate.",
            date = "2012-10-21T09:49:18-05:00",
            sourceUrl = "https://www.wowhead.com/quest=30994#comments:id=1747091",
        },
