    [31000] = {
        {
            id = 1720002,
            score = 30,
            author = "1034641",
            text = "If you have the flight path:\n\n1.Venture to \"The Sunset Brewgarden\" in the northern \"Dread Wastes\" zone.\n2.Go to the Flight Master.\n3.Fly to : \"Serpent's Spine\" flight path, in the \"Vale of Eternal Blossoms\" zone.\n\nShe will be at the left side of the flight path where you will land.\n\nIf you don't have the flight path :\n\n1.Visit the \"Dread Wastes\" zone via Townlong Steppes, go south past \"Dusklight Hollow\" across the tree bridge.\n2.Walk north-east towards \"Terrace of Gurthan\" in the upper right corner of the zone.\n3.There will be a shado pan rope on the ground, which will lift you up on the wall right before the quest NPC.",
            date = "2012-09-26T10:36:20-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31000#comments:id=1720002",
        },
        {
            id = 3206069,
            score = 23,
            author = "Morkhaine",
            text = "Due to the new black empire invasion, this NPC (and all the other ones around here, including the meeting stone) are phased out. I'm hoping the phase fixes itself when the Invasion moves to Uldum.",
            date = "2020-05-12T14:12:33-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31000#comments:id=3206069",
        },
        {
            id = 1720142,
            score = 13,
            author = "1003795",
            text = "Possible reference to the series \"Dead Space\"!",
            date = "2012-09-26T12:50:52-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31000#comments:id=1720142",
        },
        {
            id = 1948927,
            score = 6,
            author = "Teryx",
            text = "This quest must have a prerequisite, she does not offer it to me.",
            date = "2014-03-06T09:12:47-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31000#comments:id=1948927",
        },
        {
            id = 1722886,
            score = 4,
            author = "996871",
            text = "Actually, the \"rope beside her\" is for the next quest (Falling Down).  The flight master at Kor'vess should take you to Serpent's Spine.",
            date = "2012-09-28T08:55:11-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31000#comments:id=1722886",
        },
    },
    [31001] = {
        {
            id = 1749525,
            score = 29,
            author = "chrth",
            text = "The Truth Behind this Quest:\n\nAdventurer A comes up to Bowmistress Li due to one of the many breadcrumb quests.  \"A volunteer for Dread Wastes duty? I think you might be the first.  Pleased to meet you.  One of my best marksmen caught a blast of webbing around his leg and got pulled straight down!  Please save him!\"\n\nAdventurer A goes down the rope, where he rescues Marksman Lann.  Marksman Lann points him to the https://www.wowhead.com/quest=31003 fighting in the cave, and returns to his post, where he is greeted by Bowmistress Li.  \"Where is Adventurer A?\" she asks.  \"There were some Mantid fighting that he wished to investigate,\" Marksman Lann replies. \"I expect him back shortly.\"\n\nSeveral hours pass.\n\nBowmistress Li returns to Marksman Lann.  \"Did he indicate he had any other plans?\"  Marksman Lann shakes his head.  \"No ... I hope I did not lead him to his death.\"\n\"You know what you have to do, right?\"  Marksman Lann nods.  \"I'll head down to look for him.\"\n\nA few more hours pass.\n\nAdventurer B comes up to Bowmistress Li due to one of the many breadcrumb quests.  \"A volunteer for Dread Wastes duty? I think you might be the first *COUGH*.  Pleased to meet you.  One of my best marksmen caught a blast of webbing around his leg ...\"",
            date = "2012-10-24T14:03:23-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31001#comments:id=1749525",
        },
        {
            id = 1676498,
            score = 6,
            author = "adhseidh",
            text = "Marksman Lann is  down the terrace (2 level down I believe) outside a little cave, follow the wall south west and you should find him, leads to Psycho Mantid (http://mop.wowhead.com/quest=31003) after also handing in Nope (http://mop.wowhead.com/quest=31002)",
            date = "2012-06-14T03:39:36-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31001#comments:id=1676498",
        },
        {
            id = 1700669,
            score = 6,
            author = "Joana",
            text = "Michael Douglas anyone?",
            date = "2012-08-16T18:44:08-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31001#comments:id=1700669",
        },
        {
            id = 1807944,
            score = 5,
            author = "998027",
            text = "If you hit a Dreadspinner Tender with your Dragon Gun instead of the eggs, it will get a DoT that says:\n\n\"Burns for 3% of total HP over 10 seconds. Mostly just annoyed.\"",
            date = "2013-02-02T01:01:21-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31001#comments:id=1807944",
        },
        {
            id = 5376221,
            score = 2,
            author = "bratgirl",
            text = "If for some reason you cannot find Bowmistress Li at Serpent's Spine, and Visions of N'Zoth Assault is happening in Vale of the Eternal Blossoms, then visit Zidormi, who is standing on the balcony at the Mogu'shan Palace (upper right on the map - where the little speech bubble is), and ask her to show you what the area looked liked prior to the assault. Then when you fly back to Serpent's Spine Bowmistress Li should be there.",
            date = "2022-05-23T07:38:10-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31001#comments:id=5376221",
        },
    },
    [31002] = {
        {
