        {
            id = 1731942,
            score = 49,
            author = "1040799",
            text = "I was roasting the spider eggs near Marksman Lann and accidentally pointed the jet of fire right at him for a moment. He wasn't happy about it: \"Whoa, point that somewhere else!\"\n\nAfter I did the quest, I turned it in and had to laugh as he congratulated me on my performance with the dragon gun :P",
            date = "2012-10-05T04:50:02-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31002#comments:id=1731942",
        },
        {
