            text = "Nope. (http://www.youtube.com/watch?v=gvdf5n-zI14)",
            date = "2012-06-01T21:25:26-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31002#comments:id=1672486",
        },
        {
            id = 1698138,
            score = 17,
            author = "496978",
            text = "This is a quest to defeat spiders, spiderlings, and spider eggs with a flamethrower.  Need I say more?\n\nSadly, the big spiders take almost no damage, so my dreams of fending off giant spiders with a flamethrower is shattered.  That just makes them more scary, but at least Lava Burst still works.",
            date = "2012-08-10T01:13:57-05:00",
