    [31003] = {
        {
            id = 1722636,
            score = 95,
            author = "Ikayuro",
            text = "If he starts telling me what I have installed on my hardrive, I quit.",
            date = "2012-09-28T05:09:04-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31003#comments:id=1722636",
        },
        {
            id = 1678114,
            score = 65,
            author = "827202",
            text = "You like Castlevania, don't you? (http://metalgear.wikia.com/wiki/Psycho_Mantis)",
            date = "2012-06-18T16:18:36-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31003#comments:id=1678114",
        },
        {
            id = 1672490,
            score = 45,
            author = "Cielos",
            text = "https://www.wowhead.com/npc=62301 and https://www.wowhead.com/npc=62203 are are in the cave right behind Marksman Lann.\n\nThis is also the introductory quest for the Klaxxi reputation.  In order to reach this quest, you have to have already done the two quests given by Bowmistress Li Tsz-Wai on the Serpent's Spine.",
            date = "2012-06-01T21:40:17-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31003#comments:id=1672490",
        },
        {
            id = 1820192,
            score = 45,
            author = "123744",
            text = "Pre-Quests\nFrom Bowmaster Ku (http://www.wowhead.com/npc=64534)\ni. The Klaxxi (http://www.wowhead.com/quest=31391)\nFrom Bowmistress Li (http://www.wowhead.com/npc=62112)\nii. Nope (http://www.wowhead.com/quest=31002) & Falling Down (http://www.wowhead.com/quest=31001)\n\nFirst Quest in the Klaxxi Rep Chain.\n\n1. Psycho Mantid (http://www.wowhead.com/quest=31003)\n2. Preserved in Amber (http://www.wowhead.com/quest=31004)\nGives\n3a. Ancient Vengeance (http://www.wowhead.com/quest=31676)\n3b. Wakening Sickness (http://www.wowhead.com/quest=31005)\nThen he flies you to\n4. The Klaxxi Council (http://www.wowhead.com/quest=31006)\nwith a nice little dialog on the flight, then more dialog when you land.\n\n5a. The Dread Clutches (http://www.wowhead.com/quest=31007)\n5b. Not Fit To Swarm (http://www.wowhead.com/quest=31660)\nKor'tik gives you\n5c. Dead Zone (http://www.wowhead.com/quest=31009)\nAmbersmith Zikk gives you\n5d. Amber Arms (http://www.wowhead.com/quest=31008)\n6a. A Source of Terrifying Power (http://www.wowhead.com/quest=31661)\n6.b In Her Clutch (http://www.wowhead.com/quest=31010)\n\n7a. The Dreadsworn (http://www.wowhead.com/quest=31689)\n7b. Citizens of a New Empire (http://www.wowhead.com/quest=31107)\n7c. Concentrated Fear (http://www.wowhead.com/quest=31108)\n7d. A Cry From Darkness (http://www.wowhead.com/quest=31066)\n8a. Extending Our Coverage (http://www.wowhead.com/quest=31087)\n8b. Amber Is Life (http://www.wowhead.com/quest=31019)\n\nAlso given are these daily's\nEradicating the Zan'thik (http://www.wowhead.com/quest=31111)\nVess-Guard Duty (http://www.wowhead.com/quest=31505)\nSeeds of Fear (http://www.wowhead.com/quest=31603)\n\n9a. Living Amber (http://www.wowhead.com/quest=31021)\n9b. Feeding the Beast (http://www.wowhead.com/quest=31020)\n10.  Kypari Zar (http://www.wowhead.com/quest=31022)\n11. The Root of the Problem (http://www.wowhead.com/quest=31026)\n\nFind Kor'ik (http://www.wowhead.com/npc=65365)\nExtending our Coverage\n12a.Crime and Punishment (http://www.wowhead.com/quest=31088)\n12b. Better With Age (http://www.wowhead.com/quest=31088)\n13. By The Sea, Nevermore (http://www.wowhead.com/quest=31089)\nFind Kaz'Tik (http://www.wowhead.com/npc=62540)\n14. Reunited (http://www.wowhead.com/quest=31091)\n15a. The Kunchong Whisperer (http://www.wowhead.com/quest=31359)\n15b. Feed or Be Eaten (http://www.wowhead.com/quest=31092)\nTurn in Glowing Amber (http://www.wowhead.com/item=86533) for\n16. Falling to Pieces (http://www.wowhead.com/quest=31398)\n\nSkeer the Bloodseeker opened up after 7, but I was already Honored.  The second time I did it.\nFind Skeer the Bloodseeker (http://www.wowhead.com/npc=63071)\n17a. A Bloody Delight (http://www.wowhead.com/quest=31178)\n17b. A Strange Appetite (http://www.wowhead.com/quest=31176)\n17c. Fine Dining (http://www.wowhead.com/quest=31177)\n18. The Scent of Blood (http://www.wowhead.com/quest=31179)\n\nFind Rik'kal\n8c. Zanthik Dig (might be rep related)\nThe Dissector Wakens\n\nJust Hit revered and it opened up The final 2 paragons,\nHisek\n19. Dropping our Signal\n20. Corruption Runs Deap\n21a. Damage Control\n21.b Extracting Answers\n\nXaril\n22. Beneath the Heart of Fear\n23a. Venomous Intent\n23b. Dark Wings, Dark Things\n23c. A Shade of Dread\n\nmore to follow as I do the chain...  Please vote me up",
            date = "2013-03-02T21:07:17-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31003#comments:id=1820192",
        },
        {
            id = 1717818,
            score = 36,
            author = "449671",
            text = "\" From the moment we're thrown into this world, we're fated to bring each other nothing but pain and misery. \"\n\nFinally, the Metal Gear Solid series has left it's mark.  WoW is now complete :)",
            date = "2012-09-24T04:56:31-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31003#comments:id=1717818",
        },
    },
    [31004] = {
        {
            id = 3209196,
            score = 32,
            author = "Arheia",
            text = "amber is at 70.25, 25.73",
            date = "2020-05-28T09:24:07-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31004#comments:id=3209196",
        },
        {
            id = 1926414,
            score = 10,
            author = "40403",
            text = "The Ancient Amber Chunk is a chunk of yellow rock at the bottom of the Terrace of Gurthan. It's not in any cave, so if you're without flight at this stage then you must explore. The coordinates are 70.3,25.7",
            date = "2013-12-16T08:23:25-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31004#comments:id=1926414",
        },
        {
            id = 1931383,
            score = 4,
            author = "Pypode",
            text = "Without coords, Beginning where you first dropped down the rope:\n-go down right-hand staircase;\n-veer slightly right and down that set of stairs;\n-at that landing, go left and down three staircases.\nThe Amber is directly to your right, sitting on ice. The gears floating over the amber will show on your minimap when you are in the area.  Coordinates 70.25 are correct.",
            date = "2014-01-03T13:17:12-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31004#comments:id=1931383",
        },
        {
            id = 1756197,
            score = 2,
            author = "1052027",
            text = "Confirmed at 70.25",
            date = "2012-11-03T10:54:15-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31004#comments:id=1756197",
        },
        {
            id = 1931388,
            score = 1,
            author = "Pypode",
            text = "The amber is downhill. Without coordinates, you will have to fight all the way:\n Start where you first dropped down the rope from the wall,\n go down the right-hand staircase; then\n veer slightly to your right and go down that staircase;\n at the landing, go left down three staircases.\n\nThe amber is directly to your right, sitting on an ice pond. The gears floating over the amber will show on your minimap when you are in the area.   Coordinates 70.25 are correct. Hope you can fly.",
            date = "2014-01-03T13:27:54-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31004#comments:id=1931388",
        },
    },
    [31005] = {
        {
            id = 1729557,
            score = 10,
            author = "Elfgar",
            text = "The flies were in small swarms of five or six that were very easy to aoe down and with the new ability for all eligible loot to be extracted with one click the quest took about five minutes.",
            date = "2012-10-03T04:53:31-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31005#comments:id=1729557",
        },
        {
            id = 1767356,
            score = 3,
            author = "1038089",
            text = "After you accept the quest, go down the steps until you see a big tree and a small lake on your left. This spot as well as further down where there's two big trees on either side of the steps are the best places to farm these. Otherwise all the other groups are spread out and only contain 5-6 adds.",
            date = "2012-11-24T20:36:21-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31005#comments:id=1767356",
        },
        {
            id = 1780254,
            score = 1,
            author = "pogostick",
            text = "If you are doing this quest, be aware these flies are also the target of a daily quest @ lvl 90. So during busy hours on your server, be prepared to run around a lot looking for live ones.",
            date = "2012-12-12T16:13:05-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31005#comments:id=1780254",
        },
        {
            id = 1725688,
            score = -1,
            author = "XxiolaA",
            text = "This quest is a huge waste of time",
            date = "2012-09-30T06:51:48-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31005#comments:id=1725688",
        },
        {
            id = 1757740,
            score = -1,
            author = "athenerus",
            text = "Too easy quest, quick experience. Just look around and kill the swarms with any aoe spell. And loot it.",
            date = "2012-11-05T15:34:45-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31005#comments:id=1757740",
        },
    },
    [31006] = {
        {
            id = 1672499,
            score = 21,
            author = "Cielos",
            text = "For those interested, here is the entire conversation Kil'ruk the Wind-Reaver has with you as he takes you to Klaxxi'vess.\n\nI am Kil'ruk, a warrior from an era long passed.  In my time, this was a Mogu stronghold.  It was my honor to paint the walls with their blood.\n\nFor my deeds, I was named a Paragon.  A cultural hero, to be preserved in amber for a time when the empire would need... correcting.\n\nWakener, what power is this that burns our land and corrupts our trees?  This palace!  This is... not our way.  I see why the Klaxxi have been forced to act.   They are a council of our wisest cultural leaders.  They serve to check the power of the Empress.  Should her desire for conquest ever endanger our civilization, the Klaxxi are sworn to unseat her.\n\nThere are others like me.  Paragons of each era, frozen in time and buried safely beyond the whispers of the Empress.  We answer only to the council and we only rest when their will is done.",
            date = "2012-06-01T22:14:59-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31006#comments:id=1672499",
        },
        {
            id = 1858923,
            score = 7,
            author = "Gadoink4",
            text = "When you land at Klaxxi'vess, the following dialog occurs:\n\nKlaxxi'va Vor (http://www.wowhead.com/npc=62519) says: Wind-Reaver (http://www.wowhead.com/npc=62538). You have awakened. What of Klaxxi'va Tik (http://www.wowhead.com/npc=62203)?\nKlaxxi'va Set (http://www.wowhead.com/npc=62518) says: And what is this filth (http://www.wowpedia.org/Player_character) you've brought to our sanctuary (http://www.wowpedia.org/Klaxxi%27vess)?\nKil'ruk the Wind-Reaver says: The Klaxxi'va you sent has fallen to an adjunct (http://www.wowhead.com/npc=62301) of Her majesty (http://www.wowhead.com/npc=62837).\nKil'ruk the Wind-Reaver says: This... \"filth\" defeated the adjunct (http://www.wowhead.com/quest=31003) and saw to my Wakening (http://www.wowhead.com/quest=31004).\nKlaxxi'va Set says: We do not need help from the lesser races! Dispose of it!\nKil'ruk the Wind-Reaver says: Right away, Klaxxi'va.\nKlaxxi'va Vor says: No.\nKlaxxi'va Vor says: The Wakener may prove useful. One way or another.\nKlaxxi'va Set says: As fodder for the swarm, perhaps!",
            date = "2013-05-27T20:38:16-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31006#comments:id=1858923",
        },
        {
            id = 1859600,
            score = 3,
            author = "Magnacus",
            text = "After mounting the NPC to ride to Klaxxi'vess I dismounted, and was left with no NPC respawning, so I ran to Klaxxi'vess on foot.  When I arrived I was unable to speak o the NPC I needed to see to turn in the quest.  I waited for him to finish flying, but he must have despawned when I dismounted.  I retured to the spot where I broke him from the amber, but he was not there.  I waited and waited, but he wasn't there.  If this happens to you, you must log out and log back in and he will spawn, using /reload ui doesnt work. once you did, he will be waiting where the amber was broken.",
            date = "2013-05-29T10:26:39-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31006#comments:id=1859600",
        },
        {
            id = 1930533,
            score = 3,
            author = "620773",
            text = "As I sit here on New Year's Eve doing this quest on yet another alt and preparing to watch my favourite New Year's movie \"The Shining\", I start to wonder...\nIs Kil'ruk quoting \"The Shining\" when he says the empire would need...correcting?\nFrom the bar scene where Jack is talking to the former caretaker of the hotel, Mr. Grady:\n\nPerhaps they need a good talking to, if you don't mind my saying so. Perhaps a bit more. My girls, sir, they didn't care for the Overlook at first. One of them actually stole a pack of matches, and tried to burn it down. But I \"corrected\" them sir. And when my wife tried to prevent me from doing my duty, I \"corrected\" her.\n--Delbert Grady\n\nAnd by \"correcting\", he apparently means he chopped them into little bits.\n\nHappy New Year.\n\n-T.",
            date = "2013-12-31T11:03:43-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31006#comments:id=1930533",
        },
        {
            id = 1754664,
            score = -2,
            author = "355167",
            text = "You can talk to the quest giver to receive a ride.  But he travels very slow and takes the long way, quicker to ride there yourself.",
            date = "2012-10-31T23:27:03-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31006#comments:id=1754664",
        },
    },
