    [31010] = {
        {
            id = 1806978,
            score = 15,
            author = "Smallfoot",
            text = "So since I woke you and we're here behind enemy lines and all... I was wondering, can I get a lift back?  The guy before you did, and it was pretty cool of him.\n\nHey, I see you're kind of flying away now.  Does this mean no ride?  No?  That's....that's cool, I guess.  I'll just, you know, start walking back through hostile territory.   ...you're welcome, by the way.\n\n....jerk.",
            date = "2013-01-31T00:36:24-06:00",
