    [31011] = {
        {
            id = 1668022,
            score = 98,
            author = "yoshimo",
            text = "If you like me have issues with the [npc=63516 domain=mop]\nThere is a barricade northwest, towards the road to the beach, which is under attack.\nUse the explosive barrels which are marked with a green arrow until you killed 5 of them.",
            date = "2012-05-18T02:41:29-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31011#comments:id=1668022",
        },
        {
            id = 1725406,
            score = 37,
            author = "fai1",
            text = "Berserkers in the middle of the town.\nRiders at the barricade to the north east.\nBehemoths at the barricade to the north west.",
            date = "2012-09-30T01:40:09-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31011#comments:id=1725406",
        },
        {
            id = 1724181,
            score = 25,
            author = "Whiterock",
            text = "Two Empires Quest Tree From Whiterock\n[pre]Barrels of Fun (http://www.wowhead.com/quest=30651){H} (http://www.wowhead.com/quest=30656)* Pandaren Prisoners (http://www.wowhead.com/quest=30650){H} (http://www.wowhead.com/quest=30655)* The Ordo Warbringer (http://www.wowhead.com/quest=30660){A2 (http://www.wowhead.com/quest=30662),H1 (http://www.wowhead.com/quest=30661),H2 (http://www.wowhead.com/quest=30663)}*\n                \\      ||        ┌─────────┘\n                [ins]S[/ins])Cho's Missive (http://www.wowhead.com/quest=31460){H} (http://www.wowhead.com/quest=31459)\n                [ins]+[/ins])Path Less Traveled (http://www.wowhead.com/quest=30999)\n                /      ||           └─────┐\na)Resupplying One Keg (http://www.wowhead.com/quest=30618) a)Instant Courage (http://www.wowhead.com/quest=30601) a)They Stole My Luck! (http://www.wowhead.com/quest=30621)\n                \\      ||                 ||\n                b)Comin' Round the Mountain (http://www.wowhead.com/quest=30487)\n                b)One Traveler's Misfortune (http://www.wowhead.com/quest=30683)\n                b)Seeker's Folly (http://www.wowhead.com/quest=30684)\n                /               \\\nd)It Was Almost Alive (http://www.wowhead.com/quest=30797)           c)The Tongue of Ba-Shon (http://www.wowhead.com/quest=30829)\nf)The Tomb of Shadows (http://www.wowhead.com/quest=30799)           d)Staying Connected (http://www.wowhead.com/quest=30795)\ng)Breaking the Emperor's Shield (http://www.wowhead.com/quest=30798) d)An End to Everything (http://www.wowhead.com/quest=30796)\nh)Stealing Their Thunder King (http://www.wowhead.com/quest=30800)\nh)Lessons from History (http://www.wowhead.com/quest=30801)\nh)Chasing the Storm (http://www.wowhead.com/quest=30802)\ni)Fisherman's Tale (http://www.wowhead.com/quest=30935)────────────┬─>j)Make A Fighter Out of Me (http://www.wowhead.com/quest=30942)\n ||  ||    ||                    ||                 ||\n ||  ||   i)It Takes A Village (http://www.wowhead.com/quest=30944) j)Handle With Care (http://www.wowhead.com/quest=30943) ||\n ||  ||                       \\ ||                 ||\n || j)What's Yours Is Mine (http://www.wowhead.com/quest=30945)──>k)Enemies At Our Door (http://www.wowhead.com/quest=31011)\n ||                          k)Revelations (http://www.wowhead.com/quest=30946)\n[ins]S[/ins])Checking In (http://www.wowhead.com/quest=30816)               l)Prophet Khar'zul (http://www.wowhead.com/quest=31228)\n[ins]+[/ins])Emergency Care (http://www.wowhead.com/quest=30794)\n ||        \\    └───────────────┐\nm)Justice (http://www.wowhead.com/quest=30805) m)The Scent of Life (http://www.wowhead.com/quest=30806) n)By the Falls, For the Fallen (http://www.wowhead.com/quest=30807)\n ||        /           ┌────────┘\no)Preparing the Remains (http://www.wowhead.com/quest=30819)\np)A Funeral (http://www.wowhead.com/quest=30820)\n\nLegend:\nS means Skippable\n+ means Can start anytime, prequests not needed.\n{H} means Quest Have Horde Variant, click {H} for it.\n* means another Quest Tree.[/pre]",
            date = "2012-09-29T07:29:18-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31011#comments:id=1724181",
        },
        {
            id = 1791073,
            score = 25,
            author = "1070187",
            text = "Greetings, I would like to help the people that have difficulties with this quest\n\nThis is how you find the quest mobs you have to kill:\n\n1. Amani Berserkers - They spawn in the village right after you take the quest and the cinematic ends\n\n2. Amani Behemoths - They can be found on the left side of the village, on the path that goes down. You will see some barrels and you must click them to kill the behemoths.\n\n3. Gurubashi Bloodriders - On the road going towards the Troll encampment you will see some Pandaren hiding behind a wooden barricade, wait there until the Bloodriders come and kill them\n\nCloudfist",
            date = "2013-01-02T07:13:11-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31011#comments:id=1791073",
        },
        {
            id = 1744974,
            score = 7,
            author = "923931",
            text = "what quests do you have to do to GET to this quest? I go to the village and there are no quests available, i almost virtually dungeons through Kun-Lai so which quests do i need to do to unlock the quests in Zouchin Village? Can anyone please help me? :)",
            date = "2012-10-18T15:08:29-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31011#comments:id=1744974",
        },
    },
    [31012] = {
        {
            id = 1792614,
            score = 14,
            author = "1026168",
            text = "As you enter Orgrimmar, a guard (http://www.wowhead.com/npc=3296) exclaims, \"Never thought I'd see one of your kind walk through here.\"\nAfter a pause: \"Come on through. The Warchief's expecting you.\"\nJi Firepaw follows you around as if you know what you're doing. Guess who's the brains of this operation?\n\nFurther in, you pass by https://www.wowhead.com/npc=62195 who yells, \"Look! It's Ji Firepaw and ! They're the ones who helped https://www.wowhead.com/npc=64593 escape from the Alliance!\"\n\nNearing 'Emperor Hellscream' you find the https://www.wowhead.com/object=206109, wherein Ji runs ahead and exclaims, \"Look at this!\" After skimming: \"Well, that's good news. Once we join the Horde, we certainly won't run out of things to do.\" Assuming he survives long enough.\n\nEnter the building behind and you find Garrosh Hellscream, who notices you right away: \"Pandaren! Approach.\"\nYour companion runs ahead again and kneels before Garrosh. \"Emperor Hellscream, I am Ji...\"\nGarrosh yells: \"That's WARCHIEF Hellscream!\" Calming down, he practically growls, \"Now, rise. We should talk, pandaren.\"\n\nWelcome, Fodder. Time to serve the HORDE!",
            date = "2013-01-04T18:03:59-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31012#comments:id=1792614",
        },
        {
            id = 2019073,
            score = 10,
            author = "moblinman",
            text = "Interesting tidbit: if you had this quest in your logs from prior to 6.0, and proceed to Grommash Hold, both Garrosh AND Vol'jin are present. Talk about awkward.",
            date = "2014-10-25T19:09:13-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31012#comments:id=2019073",
        },
        {
            id = 1785344,
            score = 7,
            author = "Xexji",
            text = "Interestingly enough, Ji addresses Garrosh as \"Emperor Hellscream\"",
            date = "2012-12-21T22:17:32-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31012#comments:id=1785344",
        },
        {
            id = 2425518,
            score = 7,
            author = "staples575",
            text = "As of 7.0.3 if you join the alliance you now report to Anduin, oddly though choosing horde you STILL report to Garrosh, though the whole sequence of the fighting ring etc. is gone. Come on blizzard, where's the horde love?",
            date = "2016-10-10T10:10:53-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31012#comments:id=2425518",
        },
        {
            id = 3373521,
            score = 7,
            author = "Calyope",
            text = "Note for those who choose Horde during or after Shadowlands:  You cannot accept the \"Battle for Azeroth:  Mission Statement\" quest outside of Grommash Hold.  It will cause Garrosh Hellscream to not appear, but the quest marker still shows he's in the Hold.",
            date = "2021-04-03T21:25:33-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31012#comments:id=3373521",
        },
    },
    [31013] = {
        {
            id = 2020840,
            score = 28,
            author = "avalef",
            text = "In the WoD prepatch you turn this quest in to Garrosh who is standing to the right of Vol'jin. I thought this was a bit odd. xD",
            date = "2014-10-29T20:30:42-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31013#comments:id=2020840",
        },
        {
            id = 2183048,
            score = 24,
            author = "Ragahnsiir",
            text = "You can almost feel the regret in Ji's voice as Garrosh shows you around.",
            date = "2015-05-14T14:35:59-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31013#comments:id=2183048",
        },
        {
            id = 2469378,
            score = 21,
            author = "swedengamer",
            text = "As of patch 7.1.5, you turn this quest in to Garrosh who is standing next to the Warchief's seat in Orgrimmar. You don't even have to leave the room. I was a bit disapoointed because I was expecting to fight in that arena, but I guess that is no longer available.",
            date = "2017-02-03T08:31:09-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31013#comments:id=2469378",
        },
        {
            id = 1792652,
            score = 20,
            author = "1026168",
            text = "After belittling the Tauren and Blood Elf representatives in his presense, Warchief (who would not be your Emperor) Garrosh commands you to meet him in The Valley of Honor for a... 'gift' (http://www.wowhead.com/quest=31014). Along the way, you're greeted by new allies.\n\nhttps://www.wowhead.com/npc=62198 says: Welcome to Orgrimmar!\nhttps://www.wowhead.com/npc=3296 says: Have you come to serve the Horde?\nhttps://www.wowhead.com/npc=62194 says: Best move quickly through this area, stranger. The warchief doesn't take kindly to non-orcs loitering in this part of Orgrimmar.\nJi Firepaw, your companion, says: He... he segregates the city?\nhttps://www.wowhead.com/npc=62194: Move along, then. Hellscream's eyes are upon you.\n\nAlong your path you lay eyes for the first time upon some smallish big-eared things called Goblins.\nhttps://www.wowhead.com/npc=62199 says: Whoah.\nhttps://www.wowhead.com/npc=62200 says: Whoah.\nhttps://www.wowhead.com/npc=62199 says: Cool!\nhttps://www.wowhead.com/npc=62200 says: Cool!\nhttps://www.wowhead.com/npc=62196 says: Hey Zazzle! Look at these goofballs comin' through.\nhttps://www.wowhead.com/npc=62197 says: Pretty funny-lookin', if you ask me.\nhttps://www.wowhead.com/npc=62196 says: Yeah... pretty funny-lookin' alright.\n\nThey. Are. SO. Jealous!\n\nPassing https://www.wowhead.com/npc=62193 you hear, \"Zug zug. Me like fish.\"\nHey, me too! Dude you are so my new best friend. I fished by paw on my island home, and sometimes perhaps by net, but... oh... what's that you've got there? You're catching fish by just sitting lazily on the shoreline?\nBe sure to stop by https://www.wowhead.com/npc=3332 and https://www.wowhead.com/npc=3333 and pick up your first fishing pole.\n\nThese Horde fish won't know what hit them.",
            date = "2013-01-04T19:22:34-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31013#comments:id=1792652",
        },
        {
            id = 1735526,
            score = 11,
            author = "Anchorian",
            text = "Garrosh Hellscream: \"You've made a wise decision to join sides with my Horde.\nThere are some that would call us barbarians... the \"mongrel races\" of Azeroth.\nThey are ignorant, and blind to reality. Look around you, Pandaren.\"\n\n\"You will find no better partner in battle than an orc.\"\n\n\"The Tauren have made themselves useful. Look - this one is a shaman.\"\n\n\"Even a blood elf can hold a sword.\"\n\nMore than clear here which races Garrosh considers the 'mongrel' ones!",
            date = "2012-10-08T10:41:01-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31013#comments:id=1735526",
        },
    },
