    [31019] = {
        {
            id = 1679531,
            score = 392,
            author = "569787",
            text = "Mistblade Scale-Lord is under ground. Near the south-eastern corner of the lake is a tiny cave entrance that doesn't show up on the map. The cave entrance is in the middle of a rock, positioned under a tree, between 2 camp fires.\n\nAfter killing the Mistblade Scale-Lord you free Koven from the amber and after a few words he eventually gives you another 2 quests.",
            date = "2012-06-22T04:56:14-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31019#comments:id=1679531",
        },
        {
            id = 1726197,
            score = 38,
            author = "677326",
            text = "It is not underneath the lake as the quest text would have you believe. Don't look on the water, look on the beach for a hole running into the ground.",
            date = "2012-09-30T14:46:42-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31019#comments:id=1726197",
        },
        {
            id = 1842949,
