    [31021] = {
        {
            id = 1732451,
            score = 18,
            author = "883209",
            text = "Orange objects scattered on the bottom of the lake.",
            date = "2012-10-05T16:05:06-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31021#comments:id=1732451",
        },
        {
            id = 1674874,
            score = 16,
            author = "95724",
            text = "As you feed Korven the Prime each of the nine pieces of living amber, he tells you a bit of history:\n\nAh yes.  One does not forget the taste of amber.\nBack when the world was still young, the first kypari trees bloomed.\nFrom the trees, the amber flowed and nurtured us.  Kyparite, we called it, the lifeblood of the earth.\nIt healed our wounds and made us bold.  It tasted like sweetness and fire, and gave us strength to conquer all the lesser races.\nMany were the threats to our race after the usurpers remade the world.  Narrow was the path ahead.\nIt was I who suggested our greatest warriors be cast in amber to sleep, to be awakened at the swarm's greatest times of need.\nIt was the sleep from which one could never awake.  A great risk.  A great sacrifice.  But necessary.\nThus, I was the first Paragon.  This is why, I am the Prime.\nAnd now, the Klaxxi call us to battle.  Now, I am awakened.",
            date = "2012-06-09T07:49:10-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31021#comments:id=1674874",
        },
        {
            id = 1725672,
            score = 10,
            author = "CaptainWater",
            text = "For those of you with a dilemma on if you're supposed to feed him 8 or 9 living ambers, 9 is the correct answer.",
            date = "2012-09-30T06:37:45-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31021#comments:id=1725672",
        },
        {
            id = 1739695,
            score = 6,
            author = "gfxlight55",
            text = "There is a typo in the quest.\n\nIt says to collect 8 Living Amber, however to complete the quest requires 9.",
            date = "2012-10-12T15:49:06-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31021#comments:id=1739695",
        },
        {
            id = 1759466,
            score = 6,
            author = "dlbert2000",
            text = "You can right click the amber really quickly and feed 2-3 to him at once while only consuming 1 item",
            date = "2012-11-08T19:41:54-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31021#comments:id=1759466",
        },
    },
