    [31023] = {
        {
            id = 1756534,
            score = 10,
            author = "984218",
            text = "When I picked up this quest there were a fair few other players competing for relics.\nI know nobody actually likes swimming, but I found sucking it up and jumping in the lake supplied a large number of relics in a relatively small area (not to mention several ore nodes). The lake method also reduces the chance that you'll be ganked (but no promises).\n\nThat being said, they seem to spawn pretty rapidly, so getting your eight shouldn't be a big challenge.",
            date = "2012-11-03T21:45:43-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31023#comments:id=1756534",
        },
        {
            id = 1740888,
            score = 4,
            author = "Gnarfoz",
            text = "Ths was probably intended to be a daily quest, as suggested by the existence of this copy with the same name that is flagged as such (http://www.wowhead.com/quest=31273) but is completely unfinished otherwise.",
            date = "2012-10-13T22:55:55-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31023#comments:id=1740888",
        },
