    [31032] = {
        {
            id = 2020825,
            score = 22,
            author = "Karp7",
            text = "For anyone farming toys, you'll need to complete this quest to get https://www.wowhead.com/item=88589.\nI had a hard time trying to figure out how to unlock this quest hub. The best explanation I found I found was here (http://www.icy-veins.com/forums/topic/343-townlong-steppes-storyline-screenshots-quests-and-more/). You must complete https://www.wowhead.com/quest=30975 before you can pick up this quest.\nI hope this helped anyone that was as confused as I was!",
            date = "2014-10-29T19:39:29-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31032#comments:id=2020825",
        },
