    [31038] = {
        {
            id = 1740600,
            score = 27,
            author = "MilaPriest",
            text = "To start this quest, remember to talk to her behind the tent,\notherwise you wont be able to duel with her.\nShe is close to Fei Li.",
            date = "2012-10-13T15:40:12-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31038#comments:id=1740600",
        },
        {
            id = 1789931,
            score = 12,
            author = "610398",
            text = "Pain in the ass for casters.\n\nDied the first time (mage) thinking it would be like all the other challenger type quests. She killed me pretty quick.\n\nNext time around, I popped arcane power, mirror image, and time warp. Time Warp was my saving grace, if you're a mage, USE IT. Even if you don't think you need it, it just makes it so much easier and faster. She didn't get me below 95% HP.",
            date = "2012-12-30T23:11:45-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31038#comments:id=1789931",
        },
        {
            id = 1812534,
            score = 4,
            author = "featalene",
            text = "As a rogue I was finding her a bit difficult. I'm not the best player and I know it so no comments.\n\nThe break through came when I was almost finished with my dailies and still had the fire mage (Fei Lei?) with me. I took her on and the NPC joined the fray. That tipped the balance in my favor and she was down and I still had 30% of my health.",
            date = "2013-02-11T23:02:08-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31038#comments:id=1812534",
        },
        {
            id = 1742278,
            score = 3,
            author = "Epicskillz",
            text = "What is your favorite piece of pandaria lore/storyline? Did anything suprise you as you tested the expansion?\n\n-I really liked the Emperor Shouhou story Kosak came up with. Feels a lot like mythology in a good way. Surprise. Hmm. Maybe that Lili was fun to have around when she could have been annoying. Oh and for a time Snowblossom [sic] was probably unbeatable. We called her the Destoyer of Men.",
            date = "2012-10-15T09:57:52-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31038#comments:id=1742278",
        },
        {
            id = 1796028,
            score = 1,
            author = "998027",
            text = "This was actually a relatively difficult fight. As an ilv 469 Spriest, I went from 350k to 220k HP, lots lower than in any of the other challenges so far.\n\nI use Shadowfiend + Fade often in these fights for a tank, but I was pretty surprised to see that she Polymorphed me while she fought my shadowfiend.\n\nShe then proceeded to root me and blast me with frostbolts and such nonsense that reminded me of PvP.\n\nDespite only losing 1/3 of my HP, I only lost that little because the battle was so short. She does some mean DPS in the Challenger's Ring. She also burned through two PW:S.\n\nIn retrospect, I would suggest to other Spriests to use Shadowfiend, Fade, and then silence her while your fade is up. I neglected to Silence. She will not be able to Polymorph you for most of the time your shadowfiend is tanking. You may also want to fear her as an \"interrupt\" spell should she attempt to cast Polymorph afterwards.\n\nI also suggest not blowing your CDs immediately - in the case she does Polymorph you and attack your shadowfiend (Or other pet if you're a pet class), you will completely waste them.\n\nShe's pretty squishy, so as long as you stay alive you'll be fine.",
            date = "2013-01-10T14:58:54-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31038#comments:id=1796028",
        },
    },
    [31039] = {
    },
