    [31042] = {
        {
            id = 1754876,
            score = 23,
            author = "783506",
            text = "Onyx Stormclaws can be pulled without the Serpentbinders, who are always at their side.\nJust engage the group with your flying mount. If you stay a little bit above the ground, the Stormclaw will attack and follow you, whereas the Serpentbinder will ignore you. Draw the Stormclaw a bit away, dismount and kill it. You can also easily pull multiple Stormclaws this way.\n\nSince the Stormclaws are fairly weak and you don't have to kill the Serpentbinders now, you'll finish this rather annoying quest in no time.",
            date = "2012-11-01T08:49:59-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31042#comments:id=1754876",
        },
        {
            id = 1741080,
            score = 8,
            author = "Dreadlack",
            text = "The quest items drop from the Onyx Stormclaw that accompany the Shan'ze Serpentsbinders.\n\nI found the fastest way was to go to around 24,10, the north western part of the island, where a lot of them are somewhat gathered.",
            date = "2012-10-14T04:03:16-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31042#comments:id=1741080",
        },
        {
            id = 1822235,
