    [31043] = {
        {
            id = 1745295,
            score = 72,
            author = "jjanchan",
            text = "Hard way to do this quest:\nKill dozens of https://www.wowhead.com/npc=62293s till you kick your computer in frustration and curse Blizzard for making you do this.\n\nEasy way to do this quest:\nFly up to the top of the cliffs at Shan'ze Dao, where https://www.wowhead.com/npc=62530s are patrolling amongst many https://www.wowhead.com/npc=62266.  Loot 8 tablets off the ground and fly off satisfied.\n\nEssentially, while these tablets drop from the aforementioned mobs, the drop rate is dismal, and they have respectable health pools making them a pain to kill.  Looting them from the ground at the top of plateau takes a fraction of the time.\nHope this helps! =)",
            date = "2012-10-19T00:42:47-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31043#comments:id=1745295",
