        {
            id = 1779064,
            score = 4,
            author = "72757",
            text = "Even though the quest says 'Cloudriders' in the dialogue, the objective, and the emote thing when you release them, the dragons you free are actually Wild Cloudrunners (http://www.wowhead.com/npc=62599), not riders. If you have your UI set to only show mob names of quests you're on, only the blue version of these dragons names will light up, but you can free the green, gold, and pink ones for quest credit, as well.",
            date = "2012-12-10T13:53:33-06:00",
