        },
    },
    [31061] = {
        {
            id = 1736538,
            score = 90,
            author = "ShadowsDawn",
            text = "To get off of the last dragon you kill, just exit vehicle. You'll drop down to the floor but won't die.",
            date = "2012-10-09T10:06:34-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31061#comments:id=1736538",
        },
        {
            id = 1741089,
            score = 38,
            author = "Dreadlack",
            text = "Go to the small mountain drawn on the map at around 33,15.\n\nTarget a Cloudrider and use the item that you have been given along with the quest to jump on the serpent's back. Once there, start dpsing it down. When it reaches low enough health, it will transform.\n\nTarget another nearby serpent while you're still on the other's back, and use your Bronze Claws once again to jump from serpent to serpent. Continue this until you're done.\n\nAfter saving all 8, exit the last serpent and you will be dropped to the ground without harm.",
            date = "2012-10-14T04:09:15-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31061#comments:id=1741089",
        },
        {
            id = 1797686,
            score = 28,
            author = "238448",
            text = "Would just like to comment that completing this quest seems to cause your helper to disappear and you cannot get her again. Basically meaning this quest won't really help toward\nhttp://www.wowhead.com/achievement=7298.\n\nNot sure if anyone knows how to avoid that. I'm sitting at 14/15 on one of my helpers. Oh well, 1 more day i guess.",
            date = "2013-01-13T05:21:51-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31061#comments:id=1797686",
        },
        {
            id = 1763090,
