            author = "MarsJenkar",
            text = "https://www.wowhead.com/quest=12886 Lite.",
            date = "2012-11-15T23:06:03-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31061#comments:id=1763090",
        },
        {
            id = 1892049,
            score = 3,
            author = "athenerus",
            text = "it's easy but boring. using Bronze Claws (http://www.wowhead.com/item=83134) and jump the Shan'ze Cloudrunner (http://www.wowhead.com/npc=62586) and kill 8.\nAfter killing, just click the leave vehicle icon and jump down.  Don't be afraid, you don't die.",
