    [31068] = {
        {
            id = 1775725,
            score = 20,
            author = "1061642",
            text = "First of all you must have gotten https://www.wowhead.com/quest=31067 before you can see the scroll.  Once you get that quest in the Brewgarden, head over to the cave with the mob you have to kill in it.  At the bottom of the stairs in the entrance you'll see the scroll with a ! above it.  After returning the scroll to the brewgarden and turning in the quest, the scroll will appear on a barrel as seen in the screenshot.",
            date = "2012-12-04T22:29:23-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31068#comments:id=1775725",
        },
        {
            id = 1759570,
            score = 7,
            author = "EryChu",
            text = "Since I had some trouble finding it....\n\nYou're looking for a mantid \"hall\" towards the East of the Brewgarden.  It's a scroll case on the floor at the bottom of the stairway.  ^_^",
            date = "2012-11-09T01:26:58-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31068#comments:id=1759570",
        },
        {
            id = 5842974,
            score = 5,
            author = "Redcorvette",
            text = "The entrance to get this quest is at 53.60, 15.50.  Go in and down the stairs. Should be a scroll on the floor at the bottom of the stairs.  If you have trouble finding it, go to 53.77, 16.67 and look straight north. Should be in front of you.",
            date = "2024-04-28T20:44:08-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31068#comments:id=5842974",
        },
        {
            id = 1837380,
            score = 3,
            author = "339992",
            text = "If you're not sure which quests you've completed and can't find this one or any of it's prereqs, try visiting Lya of Ten Songs (http://www.wowhead.com/npc=62667) (I found her at 38.3, 17.1, at Rikkitun Village, north of Heart of Fear). If you've completed everything else, she should have the quest Fires and Fears of Old (http://www.wowhead.com/quest=31085) for you to continue this and unlock Iyyokuk the Lucid.",
            date = "2013-04-01T00:32:20-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31068#comments:id=1837380",
        },
        {
            id = 1847152,
            score = 3,
            author = "Quartermasters",
            text = "Have done this quest a dozen times on different Alts - today down the stairs, no recipe. Had Prereq quest on log, but no sign. Completed The Heavens Hum np, and checked again on leaving, still no scroll in the doorway. Handed in, went back, no joy. Logged and tried again - no sign. Exitted game completely, rebooted, disabled all addons and lo and behold, scroll was back. I suspect actually it's a not a glitch, someone was down with the MOB's as I entered, he may have just acquired the scroll, and it didn't respawn for a while - just a case of waiting. But in contradiction of an earlier post, you don't have to have \"THe Heavens Hum\" as an active quest - but you must have acquired it, can still pick up quest if you've completed and handed in prequest!",
            date = "2013-04-26T11:17:40-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31068#comments:id=1847152",
        },
    },
