    [31072] = {
        {
            id = 1720454,
            score = 13,
            author = "leaderavia",
            text = "Kz'Kzik patrols the road and is easy to notice. Ilikkaxx appears inside of an enclosed area at 51,21. He has a knockback.",
            date = "2012-09-26T15:59:14-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31072#comments:id=1720454",
        },
        {
            id = 1732052,
            score = 10,
            author = "SJPadbury",
            text = "Ilikkax also has an interrupt/silence, in addition to the previously mentioned knockback.\n\nNeedless to say, he's not going to be getting a Christmas card from me this year.",
            date = "2012-10-05T07:29:06-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31072#comments:id=1732052",
        },
        {
            id = 1768117,
            score = 9,
            author = "lionsofmercy",
            text = "I got Kz'kzik by standing in the little alcove at 54,21. It's far enough away from the other mobs that the bombs won't blow you there.\n\nIllikkaxx, on the other hand, was a bloody pain in the ass. It wasn't so much the Resonators as much as it was the herd of Frightened Mushan he kept knocking me into. I know they're frightened. I would be too if I lived there. But D.E.H.T.A. be damned--I ended up taking out a huge swath of them (don't loot bc they respawn fast) and then picking off the prowling Resonators.\n\nGet one of the ones hovering in his area first and then kite him from that spot; the Resonator on the other side won't aggro that way. You slaughtered the mushan, so just let him knock you back into the Horrid March all he likes. Bwah ha ha.",
            date = "2012-11-26T09:04:31-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31072#comments:id=1768117",
        },
        {
            id = 1747411,
            score = 3,
            author = "N0083rP00F",
            text = "Also be warned that the others that are in close proximity will agro, that agro will cascade to other units further out and they will beat you down.\n\nFortunately the area just towards the edge of the zone, outside the circle of black spires, has very little in the way anything wandering by so you should be able to pull and stomp without any outside interference.\n\nAs mentioned earlier the interrupt/knock-back can be troublesome but timing and some luck can counter that.",
            date = "2012-10-21T19:23:15-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31072#comments:id=1747411",
        },
        {
            id = 1758817,
            score = 3,
            author = "992607",
            text = "this quest can be a huge pain. i killed the first guy with no problem, but as i was killing the other one and getting knocked back into countless other mobs and getting pounded on, the first guy respawned and went at me too. i ran for my life spamming word of glory on myself and survived. but since i had to run i never looted my first dagger : /",
            date = "2012-11-07T15:23:27-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31072#comments:id=1758817",
        },
    },
    [31073] = {
        {
            id = 1724729,
            score = 21,
            author = "Tribunal",
            text = "You can loot them while mounted. If you're just finishing up the zone after leveling, doing it on your flying mount is trivial.",
            date = "2012-09-29T15:03:31-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31073#comments:id=1724729",
        },
        {
            id = 1720182,
            score = 18,
            author = "escapades",
            text = "These mobs are ALLREADY dead. their name (Withered Husk) appears in grey but the are lootable corpses. Located to the west of the questgiver and up the hill. The drop rate appears to be 100%",
            date = "2012-09-26T13:27:36-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31073#comments:id=1720182",
        },
        {
            id = 3224709,
            score = 17,
            author = "Nivius",
            text = "(still broken in 9.1, same solution still stands it seems.)\n\nAS OF 8.3 this quest is broken (atleast for 120 players), you get phased into the 120 version of the zone for a vale quest.\n\nGo to 44.0  7.0, on the oterside of the big log bridge, there is a small section that DOES NOT phase into 120.\nhere you can kill a bunch of Kor'thik Mantid for quest -> Kor'thik Aggression  (https://www.wowhead.com/quest=31133/korthik-aggression)\nhere you can loot 2 corpses for Fragrant Corewood for quest -> Bound With Wood (https://www.wowhead.com/quest=31073/bound-with-wood)\n\nyou might have to wait for respawns, its not IDEAL ofc, but its a temporary walkaround i found.\n\n(you can also complete the quest chain given by Taoshi (as in destroy the 5 crystals, and do the reconinace misson after), as that will then phase the area back to lvl 90)",
            date = "2020-08-22T06:19:13-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31073#comments:id=3224709",
        },
        {
            id = 5467190,
            score = 7,
            author = "Aserius",
            text = "(Broken since 8.3; still broken as of 10.0.0)\n\nYou're likely to get stuck on two quests because of phasing (https://www.wowhead.com/quest=31073 & https://www.wowhead.com/quest=31074).\n\nHead to [zone=5840] and make sure you're on the BFA timeline.\nFind https://www.wowhead.com/npc=155487 at 13.6 75.4 and take the quest https://www.wowhead.com/quest=56575.\nKeep taking https://www.wowhead.com/npc=155487's quests for the storyline [storyline=1009], up until you've completed https://www.wowhead.com/quest=56645, escaping the Dread Wastes.\n\nNow, once you go back to Dread Wastes for those two quests, phasing shouldn't be an issue :)",
            date = "2022-11-09T04:05:32-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31073#comments:id=5467190",
        },
        {
            id = 1724258,
            score = 5,
            author = "Makhunty",
            text = "This will make finishing this quest a lot quicker:\n\n1) For your Mini-Map selections(Magnifier Icon) check Target.\n\n2) Make a macro with the following\n/target withered\n\n3) Drag that macro to an action bar slot and keep spamming it as you go about.",
            date = "2012-09-29T08:39:31-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31073#comments:id=1724258",
        },
    },
