    [31077] = {
        {
            id = 1721779,
            score = 113,
            author = "QuickBASIC",
            text = "I never stop and read quest text and I was blazing through these quests... some dirt flew into my eye when I saw him carrying her away and my wife started cutting onions while I completed this quest.",
            date = "2012-09-27T14:17:54-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31077#comments:id=1721779",
        },
        {
            id = 1736214,
            score = 105,
            author = "Tensaiga",
            text = "I don't know why, but this quest really hit home for some reason.  I certainly didn't expect to actually care while hammering out quests in the wastes.  Just something about Chen being so curious to find his family, and finds this young woman, already dead.  He never met her, he knows nothing about her.  But he gives her a burial a says a few words nonetheless.\n\nIn this incredibly harsh wasteland, we are given a quest where we are just viewers.  We can't do anything, she is already dead, we can't save her.  We can't even help chen.  In fact, all it asks us to do is stand there with him and listen to his words for her, pay our respects.\n\nThe war against the mantid is never ending, existed centuries before we were born and will continue centuries into the future.  Countless pandaren have died and will die, and few will ever get a burial.  At least one did.",
            date = "2012-10-09T01:19:10-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31077#comments:id=1736214",
        },
        {
            id = 1723545,
            score = 63,
            author = "Xexji",
            text = "After you accept the next quest in the chain, Chen runs off, saying \"She looked like Li Li.\"\n\nI have never had such a chill run up my spine before. I don't envy the Mantid and Sha that did this.",
            date = "2012-09-28T20:29:24-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31077#comments:id=1723545",
        },
        {
            id = 1725456,
            score = 60,
            author = "515536",
            text = "You'll find Chen Stormstout to the West of the village (not inside). Once there you talk to him. I got confused the first time since I only saw the copy of him in the village which is not interact-able.",
            date = "2012-09-30T02:52:40-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31077#comments:id=1725456",
        },
        {
            id = 1676769,
            score = 51,
            author = "selvin",
            text = "The eulogy:\nThey say your name was Evie\nThey say you were a sweet girl.\nI never knew you... but you were family.\nMay your journey in the next world be filled with joy and beauty.\nFarewell, Evie Stormstout.",
            date = "2012-06-14T22:54:04-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31077#comments:id=1676769",
        },
    },
    [31078] = {
        {
            id = 1684896,
            score = 313,
            author = "Draugar",
            text = "You must enter the Morrowchamber (if you stand and look at the Flight Master the Morrowchamber is the entrance you see directly ahead).\n\nOnce in the chamber you will find Chen. If you speak to him he will tell you that he thinks he sees someone but cannot get past the streams.\n\nIf you enter the streams they will bounce you back, but, you do not need to go into the side chambers to get around. All you have to do is go far enough down the ramp to go under them.\n\nContinue doing this until you reach the side of the chamber directly across from Chen. here you will find a big block of Amber containing Han. You must kill the 2 mantids attending the block and then click on the block to complete the quest requirement. Then you need to make your way back to Chen to turn in the quest.",
            date = "2012-07-05T17:29:24-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31078#comments:id=1684896",
        },
        {
            id = 1697158,
