    [31085] = {
        {
            id = 1728650,
            score = 109,
            author = "staynight",
            text = "Go to 29, 30.\n\nClick the rocks to cause them to break down.\n\nEnter the revealed cave.\n\nUse fork on Iyyokuk.\n\nKill the three mobs.\n\nDone!",
            date = "2012-10-02T11:12:49-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31085#comments:id=1728650",
        },
        {
            id = 1737956,
            score = 37,
            author = "xSylvane",
            text = "To get this part of the questline to show up, you need to do the quests at The Sunset Brewgarden, north of Kor'vess, which include: the rest of https://www.wowhead.com/npc=62667's quests, the \"Brew\" themed quests of the NPCs around her, and Chen Stormstout's family quests.",
            date = "2012-10-10T23:06:37-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31085#comments:id=1737956",
        },
        {
            id = 1722369,
            score = 28,
            author = "xmanii",
            text = "Go to the platform at 29.48 30.93",
            date = "2012-09-28T00:52:29-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31085#comments:id=1722369",
        },
        {
            id = 1820513,
            score = 9,
            author = "Sketchie",
            text = "You will find Mama Stormstout being possessed by Iyyokuk encased in amber in The Amber Hibernal. You will need to use the Ruining Fork on Iyyokuk.\n\nOnce you have done so, 3 Adjuncts will appear: Okzyk, G'kkal and Pivvika. Once you start fighting each one of them, Iyyokuk will say something through Mama Stormstout.\n\nAfter starting the fight against the first Adjunct:\nMama Stormstout says: NO... YOU WILL NOT KEEP ME INSIDE THIS ABHORRENT PRISON...\n\nAfter starting the fight against the second Adjunct:\nMama Stormstout says: SET ME FREE... THE KLAXXI CALL...\n\nAfter starting the fight against the third and final Adjunct:\nMama Stormstout says: THE HATCHING HOUR IS NIGH... I MUST ANSWER TO THE SWARM...\n\nOnce you have defeated the final Adjunct, Iyyokuk will break free of the prison and release Mama Stormstout from his control, and a brief scene will occur.\n\nIyyokuk the Lucid says: Freedom...\nIyyokuk the Lucid says: For eight hundred and seventy-seven years, I waited in that crystal... watching shadows pass through the cracks, counting decades.\nIyyokuk the Lucid says: Now, I am needed elsewhere.\n\nIyyokuk dpearts. Chen Stormstout runs in.\n\nMama Stormstout says: I... wah... where? What is going on?\nChen Stormstout says: You were being mind-controlled by some sort of malevolent ancient insect creature.\nMama Stormstout says: Oh, that. Bah, I've been through worse. And who exactly are you?\nChen Stormstout says: I am Chen Stormstout. From the Wandering Isle.\n\nChen Stormstout bows to Mama Stormstout. Mama Stormstout cheers.\n\nMama Stormstout says: STORMSTOUT? No. You're foolin'. Really? A Wandering Isle Stormstout, here, on Pandaria! Where's the rest of the family?\nChen Stormstout says: I'll explain on the way back to the Sapmasters.\n\nChen and Mama Stormstout departs.\nIf you go back to where Evie Stormstout is, you will find Chen Stormstout, Mama Stormstout, Big Dan Stormstout and Li Li, the last of the Stormstout family that is still alive.\n\nHan Stormstout is still encased in amber next to the flight trainer at the Sunset Brewgarden, so it is possible that he is still \"alive\" as well - but as of right how he is just in stasis.",
            date = "2013-03-03T14:09:22-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31085#comments:id=1820513",
        },
        {
            id = 1970112,
            score = 7,
            author = "manveru",
            text = "The cave entrance is covered by rocks. Right click on the rocks and they will disappear, allowing you to go into the cave. Coordinates are 29.69, 31.21.\n\nFor TomTom users:\n/way 29.69 31.21 Cave Entrance",
            date = "2014-06-04T22:40:19-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31085#comments:id=1970112",
        },
    },
