    [31089] = {
        {
            id = 1759618,
            score = 14,
            author = "Jeolene",
            text = "So, what do you do when Korik doesn't show up to give you this quest after you turn in 'Crime and punishment' and 'Better with age'?  I can't get any answers anywhere and that is the only set of quests left in the entire zone\n\n---\n\nUpdate: 7/19/24 - Just a quick note, I was flying through Dread Wastes (not in Remix, btw) and I happened to notice the \"!\" on the map for a quest I had never done.  I actually got excited because I thought maybe blizz had fixed the bug... but no, for the third time now I had to repeat the two quests just before this to kill bugs and collect amber.  This happened once before many years ago and it looks like it's just going to keep happening, so that makes this quest 100% impossible to complete.\n\nGood work, blizz.  Your inability to make things work continues to shine bright.",
            date = "2012-11-09T04:10:14-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31089#comments:id=1759618",
        },
        {
            id = 1683454,
            score = 13,
            author = "dipiddy",
            text = "If the rocks don't spawn you can drop the quest and obtain it again. You can also just use the quest item on the east side of the hill with the bonfire on it.\n\nIf you do drop the quest you'll need to run all the way back to Amberglow Hollow for the quest giver.",
            date = "2012-07-01T21:45:25-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31089#comments:id=1683454",
        },
        {
            id = 1760899,
            score = 12,
            author = "228349",
            text = "Quest name is a reference to two different poems by Edgar Allan Poe.  The Raven and Annabel Lee.",
            date = "2012-11-11T14:25:07-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31089#comments:id=1760899",
        },
        {
            id = 1692582,
            score = 9,
            author = "903010",
            text = "The Hollow shows as a cave on your map, just above the Briny Muck flightpoint.",
            date = "2012-07-27T04:58:46-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31089#comments:id=1692582",
        },
        {
            id = 1690975,
            score = 4,
            author = "yoshimo",
            text = "the ocean .. rock is at 43.58/63.53 and can be highlighted by mousing over.",
