    [31091] = {
        {
            id = 1745144,
            score = 49,
            author = "Heddy",
            text = "If you fly beside/above Kaz'tik the Manipulator during the escort part, and out of reach of the \"attackers\", they wont attack you. This will make it incredibly faster and easier :)\nI was on my mount the whole time in the pre-quest where he was summoned.\n\nNote! These tactics can only be used if you have reached level 90 and learned the flying skill (Duh).",
            date = "2012-10-18T20:36:11-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31091#comments:id=1745144",
        },
        {
            id = 1689397,
            score = 22,
            author = "357803",
            text = "if you are trying to complete here's a bunch of things to look out for\n\nhe stops at 3 points to fight off mobs spawned by the quest\n\nhe doesn't fight with any patrols or lizards that just hang around the area normally so if you don't pull them you don't have to worry, I followed him while mounted and skipped a few mobs\n\nyou have to stay close to him though, if you get separated he will despawn, sometimes he decides to run off on his own, even while fighting quest mobs and will despawn, you have to stay with him if he does that and still fight off the mobs. Put a raid marker on him when you start the quest so you can follow him if he runs off mid-fight.\n\nsome of the bigger mobs can put a nasty bleed on you, so be careful, even after finishing the fight you can die from the bleed",
            date = "2012-07-18T04:55:46-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31091#comments:id=1689397",
        },
        {
            id = 1736766,
            score = 19,
            author = "Namue",
            text = "Any advice what to do if he despawns? He ran off while I was fighting and I can't find him anywhere -_-",
            date = "2012-10-09T15:58:15-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31091#comments:id=1736766",
        },
        {
            id = 1756473,
            score = 15,
            author = "939428",
            text = "Careful not to mine, or gather,  turn your head, or blink, or do anything other than watch him close or you will loose him and have to start over...this makes it my 3rd attempt now.",
            date = "2012-11-03T19:22:21-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31091#comments:id=1756473",
        },
        {
            id = 1747247,
            score = 7,
            author = "828598",
            text = "If you're like me and notice that you have this quest in your log, but there are no markers on your map to tell you where to go...\n\nHe is located at (43.3, 63.4).  Talk to him to start the escort.\n\nIf you're level 90 and are able to use a flying mount, you can fly right above Kaz'tik during the escort and you won't even have to fight any mobs - they'll just despawn and Kaz'tik will continue along the escort path until the quest is completed.",
            date = "2012-10-21T14:07:57-05:00",
