        },
    },
    [31104] = {
        {
            id = 1781921,
            score = 10,
            author = "100467",
            text = "Somewhat to my surprise, you can use the 'helpers' against each other, once you have one.\n\n1. Defeat at least 1 helper (H!) by yourself.\n2. The next day, recruit H1 to help you.\n3. Pick up the quest to defeat the next helper (H2).\n4. Challenge and defeat H2, with H1's help.\n\nMade it a lot easier for this healer who uses his undergeared dps spec only for questing and dailies",
            date = "2012-12-15T15:40:15-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31104#comments:id=1781921",
        },
        {
            id = 2018793,
            score = 8,
            author = "Robotusch",
            text = "Until a fix is put in, this quest will be nigh impossible to complete post-stat squish. The NPC has a Power World Shield effect that is worth 75,000 hp - or about 4 times her actual health pool! Fortunately it can be purged by players with such an ability.",
            date = "2014-10-25T05:58:31-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31104#comments:id=2018793",
        },
        {
            id = 1788161,
