            author = "170618",
            text = "As a Warlock the only interrupt we have is Fear... which she is immune to.\n\nThis fight is very challenging and I have not yet figured out a way to damage her faster than she kills me or my void-walker.",
            date = "2012-12-27T13:35:35-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31104#comments:id=1788161",
        },
