        },
        {
            id = 1781519,
            score = 17,
            author = "vizoere",
            text = "If you do the quest chains wrong, Kil'ruk may not fly you to the correct area for this quest. If that happens, you've got to run/fly over to the western/blue area yourself. If Kil'ruk flies you to the South/Southeast, you're not going to see any Shek'zeer anything and nothing you kill there will count for this quest.",
            date = "2012-12-14T23:59:58-06:00",
