            date = "2013-03-20T15:15:49-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31109#comments:id=1831876",
        },
    },
    [31110] = {
        {
            id = 1730573,
            score = 66,
            author = "Sahbe",
            text = "After completing this quest you can use the portal to travel between Shanze Dwo and Shado-Pan Garrison.",
            date = "2012-10-04T00:03:26-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31110#comments:id=1730573",
        },
        {
            id = 1738833,
            score = 51,
            author = "Charms",
            text = "In regards to Bonyfoot's comment - You do NOT need to kill the pixies in order to achieve completion for this quest. The Shan'ze Serpentbinders within the area drops them as well and, consequently, drops significantly more than the pixies.",
            date = "2012-10-11T19:26:29-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31110#comments:id=1738833",
        },
        {
            id = 1739116,
            score = 27,
            author = "967784",
            text = "The quest giver Moshu the Arcane (http://www.wowhead.com/npc=62810#comments) is located inside a cave at 28 22.\nDarkwoods Charmer and Shan'ze mobs past the barricade and up the path both drop the questitems\nAncient Arcane Powder (http://www.wowhead.com/item=84102)\nYou need to have unlocked Shadow-Pan dailys before you can pick up the quest (revered with golden lotus)\nUpon completion, you get 275 Shado Pan rep and have the portal between Moshu the Arcane (http://www.wowhead.com/npc=62810#comments) and Shado-pan Garrison open for use.",
            date = "2012-10-12T02:44:58-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31110#comments:id=1739116",
        },
        {
            id = 1738795,
            score = 24,
            author = "Ferlathin",
            text = "The quest requires Friendly with Shado-Pan, just in case anyone is wondering.",
            date = "2012-10-11T18:40:49-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31110#comments:id=1738795",
        },
        {
            id = 1800342,
            score = 23,
            author = "998027",
            text = "Many people like to kill Serpentbinders for this quest, but personally I love killing the https://www.wowhead.com/npc=62440 mobs. They give Black Prince Rep, and are very easy kills for anyone with AoE.\n\nThey Split into 5 different mobs standing at the corners of the main Illusionist, but when you AoE they all share HP. You do an easy 110K+ DPS (I've hit up to 145K DPS on them) and slay them in seconds.\n\nThey drop 50-100 Ancient Powders to boot for this quest, usually dropping 80-ish. Fun mobs to kill and good Black Prince rep.",
            date = "2013-01-18T01:52:23-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31110#comments:id=1800342",
        },
    },
    [31111] = {
