    [31114] = {
        {
            id = 1739949,
            score = 20,
            author = "Warlock82",
            text = "This may be one of the most annoying dailies I've done in awhile.  The NPC accompanying you (or at least, Protector Yi) will pull EVERY mob in sight, there are constant patrols that will walk close enough for the NPC to grab them, and the respawn rate is ridiculously quick here.\n\nBe prepared for massive pulls.  You may want to even dismiss the NPC.",
            date = "2012-10-12T22:17:07-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31114#comments:id=1739949",
        },
        {
            id = 1818830,
            score = 7,
            author = "Xoxotl",
            text = "Don't bother going out of your way to track down a https://www.wowhead.com/npc=62844.  You will end up pulling at least one when you go after the https://www.wowhead.com/npc=62677s, whether you want to or not.",
            date = "2013-02-27T11:01:47-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31114#comments:id=1818830",
        },
        {
            id = 1743622,
            score = 5,
            author = "Lorvolar",
            text = "Warlock82 is correct.  Furthermore, the shadow crash ability that the deadtalkers do targets people from 100+ yards away, even when they aren't in combat.  If you don't dodge it, you're pulled into combat...makes it almost impossible to mount up when you're done.  Your companion will leave almost immediately to go bash on someone else's spawns, too, so...fun times.  I recommend you do this one last and just run back to the garrison when you're done with it.",
            date = "2012-10-16T20:57:14-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31114#comments:id=1743622",
        },
        {
            id = 1774348,
            score = 3,
            author = "843021",
            text = "If you're going for Know Your Role (http://www.wowhead.com/achievement=7308), I wrote a melee guide for this and Spirit Dust (http://www.wowhead.com/quest=31116) on Know Your Role (http://www.wowhead.com/achievement=7308)'s page: http://www.wowhead.com/achievement=7308#comments:id=1774346",
            date = "2012-12-02T23:27:17-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31114#comments:id=1774348",
        },
        {
            id = 1797375,
            score = 3,
            author = "998027",
            text = "For some reason I am completely incapable of doing this quest without taking damage.\n\nNo, not because it's too hard. Because even when I don't take damage (Using recount to make sure I'm not taking any damage at all), it will not count towards my achievement.\n\nAs a Priest, it's not really hard to not take damage. PW:S will protect you from your dumb tank NPC's failure to hold aggro, and you can attack from 40 yards away.\n\nI'm not sure what on earth is triggering the invisible aura that you get when you accept the quest - but it is NOT damage. Perhaps there is a glitch with the homing Shadow Crashes (That do no damage so I'm not sure why they even exist) that will trigger it. Even if they did do damage, I have PW:S on the whole time.\n\n(EDIT: I have completed this achievement. Thanks to Marchen on the tip...couldn't imagine that absorption would take off the aura as well...took a while but I managed to get it off of dumb luck before getting Exalted with the Shado-Pan.)",
            date = "2013-01-12T15:53:43-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31114#comments:id=1797375",
        },
    },
    [31116] = {
        {
            id = 1735446,
            score = 68,
            author = "Davv",
            text = "Don't try to use q item on corpses. The goal is to collect 32 spirit dusts (4 items for each spirit).\nThen try to find something like quest items on the ground (it looks like bones of corpse).\n\nYou can click on them while flying on mount, so after collect spirit dusts just fly over area and get credits avoiding the fight with elites.",
            date = "2012-10-08T09:14:21-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31116#comments:id=1735446",
        },
        {
            id = 2090186,
