    [31120] = {
        {
            id = 1765747,
            score = 36,
            author = "Midgetpower",
            text = "In order to get credit towards https://www.wowhead.com/achievement=7308, you must currently also take no damage while doing the lead up quests of https://www.wowhead.com/quest=31119 and https://www.wowhead.com/quest=31113.\nIf you take damage while then trying to kill https://www.wowhead.com/npc=62554, you will be unable to get credit towards the achievement by abandoning it and reaquiring it.  You will just need to wait until the next time you have these dailies.",
            date = "2012-11-21T10:52:44-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31120#comments:id=1765747",
        },
        {
            id = 1758498,
            score = 24,
            author = "267232",
            text = "I dropped this quest because I failed at the achievement, and the companion did not give me the option of getting the quest back.  You have to go back to Master Snowdrift at the Shado-Pan Garrison to get the quest again.",
            date = "2012-11-07T02:13:09-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31120#comments:id=1758498",
        },
        {
            id = 1759135,
            score = 12,
            author = "1053464",
            text = "I am really annoyed of the \"knowing your role\"-achievement! I have had multiple attemps at it by now and today made sure not to take damage during \"the enemy of my enemy is still my enemy\" and the assault quests. I had to abandon and retake the assault quest and doing it carefully took an enormous amount of time. I am sure I did not take any damage killing Cheng Bo, but did not get credit for it again.\nIf this is not bugged - as it seems to give credit to others - the reason I did not get credit could be that my pet die take damge.",
            date = "2012-11-08T06:26:34-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31120#comments:id=1759135",
        },
        {
            id = 1796312,
            score = 11,
            author = "61548",
            text = "If you're trying to do this without taking damage, here's quick tips for ranged:\n\n1) Make sure you have Protector Yi as your companion.\n2) Pull from the mountain just above Cheng Bo's hut. There's a solo-pull Earthtalker you need to kill first - they're the danger for this achievement, since their instant-cast Earthquake is unavoidable. Pull him with something REAL small (e.g. Faerie Fire) and then run away until Protector Yi has aggro. Edge barely back into range of the Earthtalker and burn him down.\n3) Pull Cheng Bo's group the same way, up the mountain. If possible, pull with indirect damage - I used Wild Mushrooms set in the door of the hut. Again, run away till Yi rounds up aggro on all three. Then kill the Earthtalker, Yaungol (also max range - they charge), and finally Cheng Bo.",
            date = "2013-01-11T00:36:58-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31120#comments:id=1796312",
        },
        {
            id = 1760603,
            score = 7,
            author = "OdinTGE",
            text = "I've now done this 5 times without taking damage.  Once by having somebody in my party do everything while I flew near by.  Once by just tagging Cheng Bo while somebody not in my party was doing it.  Three other times I've just done it myself using Yi and Hex taking no damage and I have yet to get credit for it.",
            date = "2012-11-11T00:50:20-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31120#comments:id=1760603",
        },
    },
