    [31127] = {
        {
            id = 1776895,
            score = 16,
            author = "MisterRik",
            text = "This quest is cheating. Chao has 393k hit points when you challenge her, and when you fight her in the ring she suddenly has over 1.1 million.",
            date = "2012-12-06T20:37:19-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31127#comments:id=1776895",
        },
        {
            id = 1817884,
            score = 6,
            author = "1075244",
            text = "Very frustrating. She kicks my shadow priest's behind all over the place. Between shadowlocking me so I can't cast and my rooting not being able to hold her, I can't figure out a strategy to beat her.\n\nOh look, I'm dead again. ~sigh~\n\nSuggestions?",
            date = "2013-02-24T23:17:06-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31127#comments:id=1817884",
        },
        {
            id = 1848776,
            score = 6,
            author = "610726",
            text = "I've been checking the comments for these fights so I'll know what to expect, and since this one sounded like I might need some extra DPS or something on my Prot pally, I grabbed the nearest \"helper,\" who happened to be https://www.wowhead.com/npc=63906. I didn't remember him at all, and as it turned out I probably would have been fine on my own, she went down pretty quick -- but he seemed to be a suitable tank for this particular encounter. So two things: 1) the fight probably won't be any worse than other quest mobs, or even the rares, if you have decent gear and aren't squishy; and 2) if you are squishy, check to see if https://www.wowhead.com/npc=63906 is around, he could be useful for this.",
            date = "2013-05-01T00:59:26-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31127#comments:id=1848776",
        },
