    [31129] = {
        {
            id = 1777329,
            score = 3,
            author = "Snoipah",
            text = "He says \"! It is so great to see you healthy, and traveling so far. \" so I'm curious if you can do this quest before you meet chen in the brewery or four winds.",
            date = "2012-12-07T18:00:10-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31129#comments:id=1777329",
        },
        {
            id = 1989522,
            score = 3,
            author = "entropicdragon",
            text = "Here's what the Sunset Brewgardeners say when you ask them if they've seen any Stormstouts:\n\nLya of Ten Songs\n\nHave you seen any Stormstouts here in the Brewgarden?\n\nYou mean other than Lazy Dan over there? Sure!\n\nI spent some time with Evie before she went hunting up north. Such a sweet girl.\n\nAnd of course, who could forget Mama Stormstout?\n\nSapmaster Vu\n\nHave you seen anybody named Stormstout come through here?\n\nYes, a few of them. The biggest one, Han, last went out to fight at Kor'vess.\n\nHaven't seen him in a few days, actually. I hope everything's alright...\n\nBig Dan Stormstout\n\nIs your name really Stormstout?\n\nYeah... Stormstout alright...",
            date = "2014-08-08T02:00:18-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31129#comments:id=1989522",
        },
    },
    [31130] = {
        {
            id = 1720799,
            score = 129,
            author = "Coriam",
            text = "Look close; the painting that's originally on the wall is of the Emerald City of Oz.",
            date = "2012-09-26T21:18:30-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31130#comments:id=1720799",
        },
        {
            id = 1740110,
            score = 89,
            author = "Mondoblasto",
            text = "I really like how Cho's voice actor portrays him.  I dropped the quest three times to see all the options, but I liked hearing his wise and patient tone.",
            date = "2012-10-13T03:24:25-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31130#comments:id=1740110",
        },
        {
            id = 1723165,
            score = 88,
            author = "Luckystar",
            text = "This could be classified as spoiler I suppose, so don't read if you want to hear it for yourself in game. However, as you can only chose one option, I thought people would be interested to hear what Cho would've said for the other ones. So here it goes:\n\nIf you chose \"Paint something heroic\", you will paint a warrior, and the dialogue that follows is:\nLorewalker Cho says: I see - one of your great Alliance warriors, is it? You have chosen a lion as your crest.\nLorewalker Cho says: Your people are both stout and ferocious. But always remember, the lion kills only when hungry.\n\nIf you chose \"Paint a portrait of Prince Anduin\", you will obviously paint a portrait of Anduin (as a child, head only), and the dialog is as follows:\nLorewalker Cho says: Who is this? A prince, you say? A child. Ah, but he has had no childhood - you can see it in his eyes.\nLorewalker Cho says: I can see your people expect great things, even from your young.\n\nIf you chose \"Paint something abstract\":\n\nLorewalker Cho says: What have we here? Fields of red and blue, violently clashing in a green land.\nLorewalker Cho says: What could it mean? I can see a lot of turmoil in your heart, my new friend.",
            date = "2012-09-28T13:36:44-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31130#comments:id=1723165",
        },
        {
            id = 1846486,
            score = 54,
            author = "Mormolyce",
            text = "My character is such an awesome painter she even managed to paint a frame.",
            date = "2013-04-24T06:43:19-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31130#comments:id=1846486",
        },
        {
            id = 1788318,
            score = 52,
            author = "Valkyl",
            text = "The following option was removed in the MoP beta.\n\nLorewalker Cho says: Ah! Haha - I can see now what your Alliance fights for.\nLorewalker Cho says: I prefer a little more meat on my birds, of course, but I can see that your people and mine are not so different after all.\n\nThe sound file itself is still within the game code:\n/script PlaySoundFile(\"Sound/Creature/LorewalkerCho/VO_Jade_Forest_Cho_Ally_Intro_07b.OGG\")\n\nEdit 03/20/2020\nSince patch 8.2, play by file path is removed. So here is the alternate way to play it in game, cause funny sound files should be available for all!\n/script PlaySoundFile(\"645448\")",
            date = "2012-12-27T18:49:40-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31130#comments:id=1788318",
        },
    },
    [31131] = {
        {
            id = 1724739,
            score = 8,
            author = "846417",
            text = "As of 9/28/12 I see this bugged, anyone else having the same issue or find a way to fix it?",
            date = "2012-09-29T15:12:17-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31131#comments:id=1724739",
        },
        {
            id = 1725589,
            score = 3,
            author = "1038225",
            text = "Fix:\nGoing to sound stupid, but it worked for myself and a couple of guildies.\nIf you queue for and complete (win or lose) a pet battle while near He Softfoot, When you return he is now in phase allowing you to hand in the quest.\nHeck you probably don't even have to finish the battle..\nGoodluck!\n\nEdit:\nSince then i've had to repeat the process every time i return to the area.\nYou do not have to complete, just join-leave.",
            date = "2012-09-30T05:16:55-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31131#comments:id=1725589",
        },
        {
            id = 1725610,
            score = 2,
            author = "Zorkal",
            text = "Pet battles didn't work for me. I tried with multiple people with no luck. Finishing and leaving right away.",
            date = "2012-09-30T05:44:23-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31131#comments:id=1725610",
        },
        {
            id = 1726468,
            score = 2,
            author = "Mantrhax",
            text = "Still bugged... cant see the NPC ..\n\ncome on Blizzard...",
