    [31137] = {
    },
    [31139] = {
        {
            id = 1735593,
            score = 3,
            author = "Ludovico",
            text = "This is a human monk only quest.",
            date = "2012-10-08T11:37:04-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31139#comments:id=1735593",
        },
        {
            id = 5425877,
            score = 1,
            author = "glassleo",
            text = "This particular version of the quest is available for Human and Kul Tiran Monks, Death Knights, Shaman and Druids.\n\nThe other classes available to Humans have their own specific versions of all the early Northshire quests.\n\nNot sure when this was all changed, but I distinctly remember Human DKs not being able to do the Northshire quests at all a while ago. Seems like Blizzard finally added the missing classes to this quest ID.",
            date = "2022-08-30T09:21:15-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31139#comments:id=5425877",
        },
    },
