        {
            id = 5432961,
            score = 1,
            author = "glassleo",
            text = "There is a bug with this quest if you are not a Human. If you abandon it, then you might not be able to pick it up again. If you are stuck in this situation you'll have to Party Sync with someone below level 50 who have not completed the Northshire quests yet, and then redo the prerequisites. You'll get this quest automatically after turning in https://www.wowhead.com/quest=31143.",
            date = "2022-09-12T18:28:11-05:00",
