    [31152] = {
        {
            id = 1750421,
            score = 59,
            author = "254191",
            text = "If you do not complete the escort you must abandon the quest to force Lorewalker Cho to respawn at the Circle of Bone (31, 34) to continue.  Inopportune dungeon queue strikes again!",
            date = "2012-10-25T18:57:30-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31152#comments:id=1750421",
        },
        {
            id = 1730695,
            score = 27,
            author = "Electropow",
            text = "Anyone else notice that Chos front and center ancestor is wearing a Keepers of Time Tabard?",
            date = "2012-10-04T03:24:46-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31152#comments:id=1730695",
        },
        {
            id = 2087056,
            score = 23,
            author = "DemonicNinja",
            text = "Depending on your race, different people will appear and Cho will say something different.\n\nBlood elf: Ah, noble is your lineage! Your people possess GREAT power, and all the terrible burdens that come with it. Equally great has been your suffering. Now I see why you call yourself 'Blood' elves.\n\nGoblin: Well... that's interesting. It appears most of your ancestors died in a fire. Oh my. Your people put themselves at great personal risk in the name of progress! I wish more Pandaren had your initiative.\n\nOrc: Astounding! A lineage of great warriors... From a different world, no less! It is rare for a Pandaren to leave his or her homeland. You are rightly proud of who you are.\n\nTauren: \"Look at that. Your people revere their ancersors as well. And you cherish the land. We have much in common! Ah, but I see your ancestors were nomads, whereas we Pandaren prefer the comforts of hearth and home. You'll find few travellers among us.\n\nTroll: Oh my - as I suspected. Your ancestry dates back to the dawn of the world. Great were the ancient empires of the trolls. I see a spark in your eyes, a powerful will - you wish to be great again, yes?\n\nUndead: How fascinating. I thought you looked sickly - but now I see the truth. Your people suffer under the weight of a terrible darkness. What strength you must have, simply to press on forward.",
            date = "2015-01-12T01:21:45-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31152#comments:id=2087056",
        },
        {
            id = 1723935,
            score = 10,
            author = "Soeroah",
            text = "'Forebears'. Blizzarrrrd...",
            date = "2012-09-29T02:19:13-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31152#comments:id=1723935",
        },
        {
            id = 2575813,
            score = 9,
            author = "Runabou",
            text = "What makes this absolutely hysterical is that if you are playing one of the Allied Races that came out before the release of Battle for Azeroth, instead of receiving a bit of lore of your race's history, you instead get free experience with a lack of roleplay. The shadows are just humans in robes in random animations. A male and female walking before fading, three females in back performing random emotes such as talking, a random male off to the side in fighting stance, and a male and female in front kneeling. I found this out leveling a Nightborne fresh through Pandaria. I can't get the amused smirk off of my face because of it and I don't quite understand why.\n\nAnd I might also add, the shadows almost remind me of how Vanessa VanCleef exposed herself in the Westfall quest chain. An untargetable pitch black (albeit translucent in Pandaria) figure.",
            date = "2018-06-24T01:50:58-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31152#comments:id=2575813",
        },
    },
