    [31159] = {
        {
            id = 5426830,
            score = 7,
            author = "glassleo",
            text = "There are 9 class specific versions of this quest, and the following few quests; one for each of the classes available to Trolls, excluding Death Knights since they have a different starting zone.\n\nThat means that you sadly cannot complete any of the Echo Isles quests as a Death Knight, Demon Hunter, Paladin or Evoker.\n\nFun fact: completing one of these will also mark all of the other class-specific versions as completed for you, as well as all of the Gnome quests! So if you were to faction change from a Horde character to a Gnome after completing these, you will find all the Gnome starting area quests are already completed.",
            date = "2022-09-01T01:17:57-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31159#comments:id=5426830",
        },
        {
            id = 2278796,
