    [31163] = {
        {
            id = 2486415,
            score = 6,
            author = "Flloyd",
            text = "so as a lvl 100 UNDEAD monk i was able to grab and complete all the quests in this chain but cant turn in this one...no Vol'jin...hes dead...so now what? cant do other quests in the zone until this one is finished so im stuck",
            date = "2017-04-13T00:11:18-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31163#comments:id=2486415",
        },
        {
            id = 3304980,
            score = 6,
            author = "Cadiencie",
            text = "You can turn this quest in, even if you have progressed to the point that Vol'jin has died, by quest synching with a fresh character (preferably a troll) who is working through the Echo Isles quests.\n\nThis is from the response to my ticket:\n\nI am Gromnaskod, High Warlord of the Horde, and Game Master of these lands. We have been busy, fighting off the Black Dragonflight of Blackwing lair, so I appreciate your patience during the wait.\n\nI understand that you're having trouble with the quest More Than Expected and not being able to turn it in.\n\nThis is due to the progress you have already made in the story and as a result Vol'jin is no longer there.\n\nWhile it is true that the quest is not needed and can be safely abandoned if you truly must have it complete you can use the party sync feature with a low lvl troll and that way you will be in their phasing and you should be able to turn it in then.\n\nI hope this helps you out.\n\nWishing you luck and hoping you have a good day.\nGromnaskod.",
            date = "2021-02-28T18:43:32-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31163#comments:id=3304980",
        },
        {
            id = 2278800,
            score = 4,
            author = "Rhynchelma",
            text = "This is the Monk version.",
            date = "2015-11-22T15:57:58-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31163#comments:id=2278800",
        },
        {
            id = 3127125,
            score = 2,
            author = "Slavrix",
            text = "For anyone who cannot hand this in at a higher level.\nThis was the official response from a GM\n\nIssue ID: #67654139\n\nYour ticket has received the following response:\n\nHeya! How is it going?\nGame Master Eciaya here. Thank you so much for your patience today, mate! I hope this message finds you well. :)\n\nIf you cannot see Vol'jin on the Echo Isles (Troll starting area) - this is because your character has progressed too far in the game's story, to the point where Vol'jin is killed. You will not be able to hand the quest in due to that.\nAs the Echo Isles quests are not necessary for Loremaster, so you may abandon the quest to continue your adventure. :)\n\nIf you have no other questions, please help us to mark this case as resolved on this page: https://us.battle.net/support/en/case/ and fill up the following survey! We are really appreciated hearing any feedback or suggestions from you.^^\n\nMay life bestow you with epic loots and legendary journeys!\nGame Master Eciaya\nBlizzard Entertainment",
            date = "2019-06-16T20:22:08-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31163#comments:id=3127125",
        },
    },
    [31167] = {
        {
            id = 1660990,
            score = 284,
            author = "Wowvocate",
            text = "For Goblins -\n\nLorewalker Cho says: Well... that's interesting. It appears most of your ancestors died in a fire. Oh my. Your people put themselves at great personal risk in the name of progress! I wish more Pandaren had your initiative.\n\nIn the spirit haze, there are several goblins. About 1/3 are dead on the ground and on fire, 1/3 are running around also on fire, and the last 1/3 are cowering or standing in place.",
            date = "2012-04-30T18:29:24-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31167#comments:id=1660990",
        },
        {
            id = 1671817,
            score = 222,
            author = "Zillions",
            text = "For Trolls:\nOh my - as I suspected. Your ancestry dates back to the dawn of the world. Great were the ancient empires of the trolls. I see a spark in your eyes, a powerful will - you wish to be great again, yes?",
            date = "2012-05-30T19:03:21-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31167#comments:id=1671817",
        },
        {
            id = 1660452,
            score = 205,
            author = "Spotdot",
            text = "Undead:\n\"How fascinating. I thought you looked sickly - but now I see the truth. Your people suffer under the weight of a terrible darkness. What strength you must have, simply to press on forward!\"\n\nWill post a screenshot of the ghosts.",
            date = "2012-04-29T15:04:13-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31167#comments:id=1660452",
        },
        {
            id = 1718677,
            score = 201,
            author = "574644",
            text = "For Tauren:\n\nLook at that. Your people revere their ancestors as well. And you cherish the land. We have much in common! Ah, but I see that your ancestors were nomads, whereas we Pandaren prefer the comforts of hearth and home. You'll find few travellers among us.\n\nIn the spirit haze you can see eight Tauren kneeling before a chieftain, perhaps old Cairne Bloodhoof himself.",
            date = "2012-09-25T11:58:43-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31167#comments:id=1718677",
        },
        {
            id = 1660354,
            score = 192,
            author = "986920",
            text = "Blood Elves:\n\"Ah, noble is your lineage! Your people possess GREAT power, and all the terrible burdens that come with it. Equally great has been your suffering. Now I see why you call yourself 'Blood' elves.\"\n\n4 groups appear each with one male and one female blood elf, 3 groups standing in line behind the 4th group kneeling in front. I couldn't recognize any characters though the clothes each group wears varies greatly.\nBehind the Blood elves stand a male and a female Nightelf, both seem to were druidic clothes\n\nDunno what that could depict. Hope to hear about the other races, too.",
            date = "2012-04-29T12:09:58-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31167#comments:id=1660354",
        },
    },
    [31175] = {
        {
            id = 1700198,
            score = 767,
            author = "1018376",
            text = "cave entrance co-ords 26,54",
            date = "2012-08-15T10:21:24-05:00",
