    [31177] = {
        {
            id = 1721151,
            score = 42,
            author = "553106",
            text = "This quest has the most miserably low drop rate of any quest I've done in years. It's just horrendous. We've killed at least 30 of these things, and I have 4 tails and my leveling partner has one. One.  Be warned.  I think someone misplaced a digit in the drop rate.",
            date = "2012-09-27T03:24:52-05:00",
