            text = "Terrible respawn rate.\nTerrible drop rate.\n\nThis must be the worst quest ever.",
            date = "2012-09-30T15:46:21-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31177#comments:id=1726263",
        },
        {
