        },
        {
            id = 1785250,
            score = 4,
            author = "998027",
            text = "Seems this quest item is \"bugged\" in a way.\n\nVolatile Blood does not stack to 100 in your inventory unless you find a perfect 100 - it will store extra stacks of like 5 volatile blood in your bag. I dropped those extra 5 to save bag space and clicked \"Yes\" as a reflex, since a lot of items have a confirmation to drop - unbeknownst to me that doing so would drop the stack of 100 as well.\n\nI had to go pick the quest back up and kill them all over again since it deletes the quest from your log when you drop them.",
            date = "2012-12-21T19:03:47-06:00",
