    [31179] = {
        {
            id = 1731666,
            score = 19,
            author = "k0rBeL",
            text = "Cords for the entrance to the underwater cave 25.74, 54.46",
            date = "2012-10-04T21:25:58-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31179#comments:id=1731666",
        },
        {
            id = 1723366,
            score = 13,
            author = "Obuibo",
            text = "It's great that he is back in fine form and letting us know that he... \"has won a hundred wars? he, who stood alone against thousands and still shouted for my enemies to come?\"\n\nBut... then there is that awkward moment mid battle when Kil'ruk (http://www.wowhead.com/npc=62538) drops in all Angel of Death (http://www.wowhead.com/spell=131767) like and one shots all the enemies he has been working on.\n\nWelcome back mate.",
            date = "2012-09-28T17:28:31-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31179#comments:id=1723366",
        },
        {
            id = 1957168,
            score = 5,
            author = "984218",
            text = "When you commence the quest and while you remain in the cave afterwards, you're given a buff called 'Scent of Blood' which I can't seem to locate in the database.\n\nInterestingly, it reads\nFighting with Skeer the Destroyer,\nwhich grants the passive ability, Scent\nof Blood. Scent of Blood heals and\ngrants haste and movement speed\nupon killing an enemy while in\nSaltscale Grotto.\n\nThis is curious because it refers to 'Skeer the Destroyer'; not Skeer the Bloodseeker (http://www.wowhead.com/npc=63359), and 'Saltscale Grotto'; not Muckscale Grotto, where the quest takes place. Something missed during development cleanup, perhaps?",
            date = "2014-04-09T08:47:05-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31179#comments:id=1957168",
        },
        {
            id = 1720465,
            score = 4,
            author = "Fedyarogue",
            text = "The mobs to kill are in a cave. The entrance is in the water. There's a neutral NPC there chilling out, and the mobs come in waves of 2 until the mini boss spawns. Hardest part is finding the cave.",
            date = "2012-09-26T16:05:45-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31179#comments:id=1720465",
        },
        {
            id = 1835860,
            score = 1,
            author = "1050290",
            text = "Don't attack any incoming mobs before they reach Skeer the Bloodseeker or he won't help you kill them. This includes the boss.",
            date = "2013-03-28T16:05:36-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31179#comments:id=1835860",
        },
    },
    [31181] = {
        {
            id = 1689587,
            score = 26,
            author = "kasuturo",
            text = "FRESH POOOOOOOOOOOOOOOOOOOOOOOOOOOOOOTS",
            date = "2012-07-18T16:47:55-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31181#comments:id=1689587",
        },
        {
            id = 1749432,
            score = 14,
            author = "staramor",
            text = "Go to the Area west of the green penisula SE of the quest giver\n\n.. if you get in a current swim sideways against it.. you'll get out of it.\n\n.. Drop rate at that locationwas over 100%, from reading other comments it sounds like you might be better off not saving up to 20... i saved 4 or 5 at a time and used them (2per) to bait the traps spawing around me.  I'd guess killing 15 to 17 yellow fish total would be enough.\n\n... you should be able to complete the  feed-the-otters quest while focusing on waiting form more of the yellow fish(which drop the needed items) to come into range . To avoid the non-quest blue fish I didn't venture too far from the cliff, atlhough I could have gone farther without being washed away.\n\n.... you will likely need to kill a few of the blue groupers ...but they had a very small agro zone though for me at lvl 89 just a matter if you wanted to be patient or swim into danger to get the fish with the quest drops\n\n... of course,  as a holy pally all the fisht took almost minute each to kill with the Blue non quest fish taking longer...but thats the breaks of the class and spec",
            date = "2012-10-24T11:23:40-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31181#comments:id=1749432",
        },
        {
            id = 1783768,
            score = 12,
            author = "93783",
            text = "Don't delete your leftover fish chunk from your bags apparently after finishing this. I did and for whatever reason it removed the quest from my logs. Don't know if it was triggered by me deleting it or not but i never abandoned it and now I've gotta wait for respawns >.>",
            date = "2012-12-18T19:33:11-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31181#comments:id=1783768",
        },
        {
            id = 1736796,
            score = 5,
            author = "926754",
            text = "\"I dont have a coffee problem. My only problem is that there's not a fresh f****** pot!\"",
            date = "2012-10-09T16:47:28-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31181#comments:id=1736796",
        },
        {
            id = 1892959,
            score = 5,
            author = "694280",
            text = "I wasn't planning on questing with the Klaxxi as this was my 6th 90 and I already quested here with two characters, but I needed replacement shoulders to start raiding (and I was getting tired of waiting for them to drop in heroics), so I was going to do this quest chain because the final quest that gave me my new shoulders is The Mariner's Revenge https://www.wowhead.com/quest=31190). When I got to the Dread Wastes, though, the quest wasn't open.\n\nAt first, I thought that it would've been available because they weren't part of the Klaxxi -- they're the Anglers -- however, I remembered from questing on my other 90s that this chain actually unlocks one of the paragons, so I needed to unlock the other ones first. This info wasn't mentioned here, but I just wanted to say that in case anyone else was wondering.\n\nI kept checking after unlocking each paragon and these were the ones that unlocked Fresh Pots. Well, I'm not sure if both of these quests were required or just one -- I turned them in at the same time and forgot to see which one unlocked it -- but it was once I turned in Concentrated Fear https://www.wowhead.com/quest=31108 and A Cry From Darkness https://www.wowhead.com/quest=31066.",
            date = "2013-09-05T02:56:37-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31181#comments:id=1892959",
        },
    },
    [31182] = {
        {
            id = 1763799,
            score = 17,
            author = "Haxan",
            text = "Those otters are so cute! =)",
            date = "2012-11-17T13:32:55-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31182#comments:id=1763799",
        },
        {
            id = 1752040,
            score = 15,
            author = "Catriona",
            text = "The only way this quest could be more adorable is if they actually followed you around with the little hearts around their heads after you fed them.",
            date = "2012-10-27T18:40:29-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31182#comments:id=1752040",
        },
        {
            id = 1750290,
            score = 11,
            author = "Snailians",
            text = "The otters are friendly and will not aggro. Beware of hostile https://www.wowhead.com/npc=63375s swimming near the sea floor. You can generally avoid them by feeding the otters on the water's surface.\n\nAlso, I cannot even fathom how adorable these otters are. They're so happy!",
            date = "2012-10-25T14:25:30-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31182#comments:id=1750290",
        },
        {
            id = 1780329,
            score = 5,
            author = "seluca",
            text = "Can't believe nobody got the reference to Alanis Morissette \"You Oughta Know\"\nyoutube.com/watch?v=NPcyTyilmYY\nAwesome song! Awesome quest name :)",
            date = "2012-12-12T19:00:45-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31182#comments:id=1780329",
        },
        {
            id = 1674892,
            score = 2,
            author = "749406",
            text = "There are quite a few at the water's surface.\n\nHold onto your bag of clams until you are done with the other quests. If you accidentally aggro an otter, you can toss him a clam and he'll stop attacking.",
            date = "2012-06-09T08:54:12-05:00",
