    },
    [31183] = {
        {
            id = 1942559,
            score = 163,
            author = "forgottenring",
            text = "This quest doesn't open up until you do https://www.wowhead.com/quest=31265, https://www.wowhead.com/quest=31182, and https://www.wowhead.com/quest=31181 given by https://www.wowhead.com/npc=63349. The only way to start those quests is to get https://www.wowhead.com/quest=31727 from https://www.wowhead.com/npc=64599. And he won't give you that quest until you have done some of the Klaxxi paragon quest line. The starter quest for these is https://www.wowhead.com/quest=31847. Then up to https://www.wowhead.com/quest=31026, the ending part of Korven the Prime section. You don't have to go any further than that if you are just looking for the Anglers rep quests.",
            date = "2014-02-11T20:25:17-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31183#comments:id=1942559",
        },
