    [31184] = {
        {
            id = 1724496,
            score = 44,
            author = "Tribunal",
            text = "Here's what he reads off the charter to you:\n\nCaptain \"Soggy\" Su-Dao says: What the... ? This ain't the charter! It's a letter. In Arie's handwriting?\nCaptain \"Soggy\" Su-Dao says: \"Dear Soggy, if you are reading this it means you finally worked up the guts to send someone after the old charter. Well, you're too late.\"\nCaptain \"Soggy\" Su-Dao says: \"We know the Mist-Hopper wasn't hired to venture this far beyond the wall. We know it was supposed to be a routine job off the coast of Jade Forest.\"\nCaptain \"Soggy\" Su-Dao says: \"What should have been a week of easy fishing turned into a wild misadventure that ran us aground in the most dangerous place on the continent and nearly got us all killed, because you couldn't stop chasing your hunches.\"\nCaptain \"Soggy\" Su-Dao says: \"We just wanted to say: Thank you.\"\nCaptain \"Soggy\" Su-Dao says: \"Thank you for chasing fortune on the distant horizon. Thank you for dreaming. And most of all, thank you for bringing us along.\"\nCaptain \"Soggy\" Su-Dao says: \"We'll always be your crew, Soggy. Ship or no ship. We'd follow you anywhere.\"\nCaptain \"Soggy\" Su-Dao says: \"Sincerely, all of us. Even Dog.\"\nCaptain \"Soggy\" Su-Dao says: Wow...\nCaptain \"Soggy\" Su-Dao says: Would you excuse me for a moment, ? I've uh... got somethin' in both my eyes.\n\nVery sweet and detailed message, makes me wonder if it's a tribute to someone (maybe a father/grandfather?)",
            date = "2012-09-29T12:24:13-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31184#comments:id=1724496",
        },
        {
            id = 1739334,
            score = 40,
            author = "Cinnamontea",
            text = "Strange, I think I got something in my eyes too. ...*sniffle*",
            date = "2012-10-12T08:09:12-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31184#comments:id=1739334",
        },
        {
            id = 1687557,
            score = 10,
            author = "Emirio",
            text = "It's inside the ship, a box just by the stairs as you go in. Kinda hard to see.",
            date = "2012-07-13T05:09:25-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31184#comments:id=1687557",
        },
        {
            id = 1723661,
