    [31185] = {
        {
            id = 1722517,
            score = 48,
            author = "1037357",
            text = "Dog is anything but. He is actually a Lion Seal. You need to summon him using the provided shell. You should make sure you summon him before arriving at a location, otherwise the quest doesn't seem to correctly register that you have 'taken' him to each of the following locations:\n\nThe Silt Vents at 46,74\nThe Wreck of the Mist-Hopper at 44,78\nThe Whale Corpse at 39,78\n\nDog tends to be rather distracted around the wreck, rubbing up against it, so do any other quests involving him away from that location.",
            date = "2012-09-28T03:12:41-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31185#comments:id=1722517",
        },
        {
            id = 1727885,
            score = 28,
            author = "714274",
            text = "If you have problems with him \"discovering\" the areas, swim away from said area, de-summon him by clicking the shell and then re-summon him and swim back into the area.  Worked for me.",
            date = "2012-10-01T20:23:24-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31185#comments:id=1727885",
        },
        {
            id = 1691208,
            score = 22,
            author = "Cielos",
            text = "I have journeyed through Azeroth since before the Cataclysm and left a trail of bodies in my wake. I have torn through the halls of Icecrown Citadel to strike down Arthas with my axes and looked upon the face of Deathwing as he died.\n\nI am a Savior of Azeroth, but nothing will get me out of sifting through poop and walking the dog. T_T",
            date = "2012-07-22T23:36:40-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31185#comments:id=1691208",
        },
        {
            id = 1793963,
            score = 9,
            author = "metroboomkin",
            text = "\"dog looks around cautiously before leaving his mark on the whale corpse\"\n\n......good boy.",
            date = "2013-01-06T23:48:00-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31185#comments:id=1793963",
        },
        {
            id = 1679706,
            score = 7,
            author = "648077",
            text = "The whale looks a bit like a giant rock on the sea floor.  Also, it is directly west of where the wreck is drawn on the map.  It should be east and a little north of where the marker is pointing you.  This information is current as of beta patch 15781.",
            date = "2012-06-22T12:10:30-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31185#comments:id=1679706",
        },
    },
    [31186] = {
        {
            id = 5858567,
            score = 43,
            author = "MrAndross",
            text = "Just incase anyone is running into this issue during mop remix and found this post. If you some how got in the predicament I did.\nYou can abandon the quest if you dont have it already and find the dog near 45,78 ( near the sunken boat)\nThen if you lost the dog whistle you can get it from the npc [npc=63317 domain=www]\nThe quest for accepting it may show that port town but i found it near the sunken boat.",
            date = "2024-05-18T12:48:57-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31186#comments:id=5858567",
        },
        {
            id = 1722110,
            score = 38,
            author = "Tyro",
            text = "Two tips:\n\n1. Dog can eat Snapclaws that die even if they weren't tagged by you!  If you see someone else killing one, swim up and help finish it off.  Everyone's Dog will eat it and get credit.\n\n2. Make sure Dog is out next to you when the Rockshell Snapclaws (http://www.wowhead.com/npc=63369) die.  He can get stuck and despawn sometimes while you swim around.",
            date = "2012-09-27T20:33:57-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31186#comments:id=1722110",
        },
        {
            id = 1720702,
            score = 31,
            author = "Catriona",
            text = "Dog is slow and kind of dumb. Sometimes he'll get stuck at the last corpse you killed for no reason. If you're too close to one of his other quest objectives (like the whale) he'll run off and do that instead, even if he's already done it. Just unsummon and resummon and he'll be back at your side.\n\nI kited the Rockshell Snapclaws in circles around him until they died. He'll swim up and nom on them. The corpses don't disappear, so don't worry if you don't get to loot before he gets there.",
            date = "2012-09-26T19:31:52-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31186#comments:id=1720702",
        },
        {
            id = 3234937,
            score = 21,
            author = "DWRedgun",
            text = "I figured out a way to make this work. Aggro a Rockshell Snapclaw. Wait 1-2 seconds for the \"Dog\" to face him. Kill the Snapclaw, loot, and let him eat it. Once the dog is engaged it seems to work every time. Spent 15 minutes trying to figure out how to make this work.",
            date = "2020-10-03T00:29:12-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31186#comments:id=3234937",
        },
        {
            id = 1727702,
            score = 11,
            author = "Kam25",
            text = "Little tip on how to stay on top of the glitch that causes Dog to either disappear or stay at the last body killed, causing you to lose credit for SnapClaw kills.  Simply \"Set Focus\" to Dog by right clicking his portrait after targeting him and clicking Set Focus, that way when the focus target disappears you'll know you have to resummon him.",
            date = "2012-10-01T16:42:14-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31186#comments:id=1727702",
        },
    },
    [31187] = {
        {
            id = 1723176,
            score = 5,
            author = "Jollygood",
