            text = "Broken in build 5.0.4 (15913), crab pots aren't clickable :(",
            date = "2012-07-28T16:28:26-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31187#comments:id=1693280",
        },
        {
            id = 5886312,
