    [31188] = {
        {
            id = 1721175,
            score = 22,
            author = "Jollygood",
            text = "When you kill a shark and get a shark jaw, you only get one. You have to remember to dismantle it for the teeth. Otherwise, you're going to kill a lot of sharks and wonder why it's taking so long.\n\n--ETA\n\nGood news everyone!\n\nA bug fix report says you can now loot up to 10 unopened thresher jaws. http://us.battle.net/wow/en/blog/7207170/Patch_505_Hotfixes_-10_5_2012",
            date = "2012-09-27T03:42:39-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31188#comments:id=1721175",
        },
        {
            id = 1721211,
            score = 16,
            author = "chilblane",
            text = "This quest is like pulling teeth.",
            date = "2012-09-27T04:05:04-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31188#comments:id=1721211",
        },
        {
            id = 1731713,
            score = 4,
            author = "Random0584",
            text = "The sharks tend to swim at the surface of the ocean rather than lower with the rest of the quest items/objectives.\n\nMakes for a little bit o' frustration.",
            date = "2012-10-04T22:47:40-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31188#comments:id=1731713",
        },
        {
            id = 1745891,
            score = 4,
            author = "Mormolyce",
            text = "You know what makes people different from animals? We're the only species on Earth that observes Shark Week. Sharks don't even observe Shark Week!",
            date = "2012-10-19T17:58:51-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31188#comments:id=1745891",
        },
        {
            id = 1663800,
            score = 3,
            author = "943961",
            text = "I am extremely excited for this quest! Not only are sharks my favorite animal, but shark week happens to be my favorite week for television! Wicked pumped that there is a faction completely dedicated to fishing. Now this is definitely a win for Blizzard! :)",
            date = "2012-05-07T10:13:24-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31188#comments:id=1663800",
        },
    },
    [31189] = {
        {
            id = 1720716,
            score = 40,
            author = "Catriona",
            text = "Speak to Ju, then click on the racks/pole on his left and right to tug them. A little squid will come up and attack with each tug. Mine bugged out after two and I abandoned/reaccepted the quest, but after I tugged one fishing pole it autocompleted.",
            date = "2012-09-26T19:49:57-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31189#comments:id=1720716",
        },
        {
            id = 1723772,
            score = 9,
            author = "369872",
            text = "There is a fishing pole set up on each side of Master Angler Ju Lien at the edge of the water on some rocks.  I had to click on each pole twice and kill the catch that came up out of the water as a result.  After 4 clicks and kills, the quest completed.",
            date = "2012-09-28T23:55:32-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31189#comments:id=1723772",
        },
        {
            id = 1730510,
            score = 1,
            author = "442479",
            text = "Be ready to squeee your little heart out if you played Wind Waker.",
            date = "2012-10-03T22:20:18-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31189#comments:id=1730510",
        },
        {
            id = 1880741,
            score = 1,
            author = "adjensen",
            text = "Though it seems like it, it isn't bugged -- there is just a non-visible cool down on the fishing lines. Pull in two, fight the mobs, then wait a couple of minutes and the lines will re-activate and you can pull in the last two.",
            date = "2013-07-25T18:42:40-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31189#comments:id=1880741",
        },
        {
            id = 1953745,
            score = 1,
            author = "1143027",
            text = "Don't Mind Vision that leviathan...ugh...it's hideous.",
            date = "2014-03-25T21:19:27-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31189#comments:id=1953745",
        },
    },
    [31190] = {
        {
            id = 1722509,
            score = 48,
            author = "1037357",
            text = "The 'Mist Hopper Jr.' is at 56, 76",
            date = "2012-09-28T03:03:58-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31190#comments:id=1722509",
        },
        {
            id = 1730188,
            score = 28,
            author = "349565",
            text = "The quests for this chain are started by https://www.wowhead.com/npc=63349 with the quest https://www.wowhead.com/quest=31265. Most of these are underwater quests, and you are given a buff https://www.wowhead.com/spell=123709.\n\nPart 1:\nhttps://www.wowhead.com/quest=31181\nKill Sea Monarchs, and use two chunks to bait a trap. Drop rate is 1 - 2 per fish.\n\nhttps://www.wowhead.com/quest=31182\nThrow clams to Coldwhisker Otters, mostly swimming near the surface of the ocean.\n\nPart 2\nhttps://www.wowhead.com/quest=31183\nUnlocks the quests below.\n\nhttps://www.wowhead.com/quest=31184\nScroll is easy to find, and appears on your minimap as a cog icon.\n\nhttps://www.wowhead.com/quest=31187\nClick on 8 crab pots.\n\nhttps://www.wowhead.com/quest=31188\nKill Longfish Threshers to obtain a jaw. Each jaw contains 20-30 teeth.\n\nhttps://www.wowhead.com/quest=31185\nTake the \"dog\" to three different locations.\n\nhttps://www.wowhead.com/quest=31186\nDog has to be present at a kill in order to feed. Not necessarily your own kill.\n\nPart 3\nhttps://www.wowhead.com/quest=31189\nTug on the lines either side of the npc until a Leviathan spawns.\n\nhttps://www.wowhead.com/quest=31190\nRewards loot as above.",
            date = "2012-10-03T15:38:47-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31190#comments:id=1730188",
        },
        {
            id = 1793166,
            score = 20,
            author = "901509",
            text = "If you're sick and twisted like me you can use this opportunity to shoot the seagulls from out of the air.",
            date = "2013-01-05T16:38:54-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31190#comments:id=1793166",
        },
        {
            id = 1725106,
            score = 19,
            author = "Koolaider",
            text = "Much better than the Scooty Puff Jr. which sucks.",
            date = "2012-09-29T19:59:49-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31190#comments:id=1725106",
        },
        {
            id = 1730345,
            score = 14,
            author = "74972",
            text = "Couldn't help but think of this song when I saw the quest. (http://www.youtube.com/watch?v=t0CR1IJKMPo)",
            date = "2012-10-03T18:30:12-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31190#comments:id=1730345",
        },
    },
    [31194] = {
        {
            id = 1699487,
            score = 8,
            author = "selvin",
            text = "Has high health (just over 1 mill), but still fairly easy to solo. Has an Avatar ability (100% extra damage done, 25% damage taken reduced), but that's it. Even if you do get low on health while fighting him if you just hit 90 or something, he's not immune to CC, which can give you time to heal or bandage.\n\nHe's fairly far away from any other mobs so you shouldn't have aggro issues while fighting him.",
            date = "2012-08-13T13:48:17-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31194#comments:id=1699487",
        },
        {
            id = 1742258,
            score = 5,
            author = "Fonzy",
            text = "Killing this mob also gives credit towards https://www.wowhead.com/quest=30155.",
            date = "2012-10-15T09:35:47-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31194#comments:id=1742258",
        },
        {
            id = 1813915,
            score = 5,
            author = "998490",
            text = "He's on the SW corner of the island.  There is an outcropping of rocks surrounding him 1/2 around.\n\nI hope this helps someone.  :)",
            date = "2013-02-15T11:55:56-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31194#comments:id=1813915",
        },
        {
            id = 1804205,
            score = 2,
            author = "mariesgrdn",
            text = "He's on an out-cropping at (69.6,31.12).",
            date = "2013-01-25T22:25:06-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31194#comments:id=1804205",
        },
    },
    [31196] = {
        {
            id = 1799790,
            score = 3,
            author = "TJtsj",
            text = "This quest is part of the Wu Kao Assassins line of daily quests picked up at the Shado-Pan Garrison.\n\nA Morale Victory (http://www.wowhead.com/quest=31198#)\nFumigation (http://www.wowhead.com/quest=31200)\nDestroy the Siege Weapons! (http://www.wowhead.com/quest=31199)\nFriends, Not Food! (http://www.wowhead.com/quest=31201)\nSra’vess Wetwork (http://www.wowhead.com/quest=31196)\nThe Bigger They Come… (http://www.wowhead.com/quest=31197)\n\nWith one of these follow ups.\nTarget of Opportunity: Sra’thik Swarmlord  (http://www.wowhead.com/quest=31203)\nor\nTarget of Opportunity: Sra’thik Hivelord (http://www.wowhead.com/quest=31204)\n\nI found groups of 2 that were realativly easy to kill near 23.3, 55.3 or around the Southern Idol from the A Morale Victory (http://www.wowhead.com/quest=31198#) quest. Some of them were able to be pulled one at a time if necessary. Just be carefull of the patrols that are all over and have fast respawns, although the standing guards didn't respawn while I was still there.\nThe stealth worked fine for me although it wasn't necessary as I was pulling 1-2 at a time.",
            date = "2013-01-16T20:42:06-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31196#comments:id=1799790",
        },
        {
            id = 1817052,
            score = 2,
            author = "zlurgh",
            text = "With my mage I first clear the area of mobs that I might accidentally agro and then sheep the elite. Taking care of the two henchmen first and using all my my cd's I can do this quest without dying multiple times.\n\nI will say this. Blizzard should play test this quest with every class. If they did they'd come to the conclusion that it's NOT a fun quest...for the sake of reputation it isn't.",
            date = "2013-02-22T16:45:33-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31196#comments:id=1817052",
        },
        {
            id = 1886960,
            score = 2,
            author = "Yogilaw",
            text = "I have now made a conscious decision to avoid this pile of junk like the plague. It was possible to complete 'Wetwork' & 'Siege Engines' without getting mobbed & killed. Now it seems this is not the case.\nOnce 'Revered' with Shado-Pan avoid this place. You can get rep with the 2 other sets of dallies if you are desperate & you won't be corpse crawling for hours & losing tons of gold in the process. A total waste of time for paltry reward.\n\nQuite why Blizzard thought cramming an island with enemies was going to encourage enthusiastic game play I can't say, but it is a joke for melee classes.\n\nSorry to sound so negative about a game we all enjoy but by the look of other posts I am not the only one.\n\nSince 5.4 when Blizz made the decision to scrap Valor Points 4 gear ability there is no real need to sweat over this. Shado-Pan Q'master now only sells for Conquest Points. If you have a 400+ Stamina rating & have up-to-spec secondary stats head to TI & try your luck. It's frankly no harder than this over-mobbed heap.",
            date = "2013-08-14T10:06:00-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31196#comments:id=1886960",
        },
        {
            id = 1683235,
            score = 1,
            author = "Salroh",
            text = "Best suggestion for this, grab a friend or two to run this quest and then it'll be fun.",
            date = "2012-07-01T08:19:46-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31196#comments:id=1683235",
        },
        {
            id = 1815527,
            score = 1,
            author = "wolphie",
            text = "As other people already said, the daily quests in this area are a HUGE pain in the rear. Definitely something I am not enjoying and I am doing them only because of reputation. All the gadgets you get are useless, companions pull pack of mobs... I die very often here and I am hunter IL 477 which managed to stay alive very well in ALL the other quest areas for ALL other factions.",
            date = "2013-02-19T06:51:35-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31196#comments:id=1815527",
        },
    },
    [31197] = {
        {
            id = 1750174,
            score = 58,
            author = "643772",
            text = "To echo previous posters, this quest is a pain in the proverbial buttocks.  With evading mobs, randomly vanishing helpers, and a low spawn rate this quest is especially nasty for anyone without a tank spec.\n\nThe easiest way I found to do this as a non-tank character who can't afford to have a whole pack descend on you at once was to set up camp at 19,39.\n\nhttp://i.imgur.com/hGHlC.jpg (http://i.imgur.com/hGHlC.jpg)\n\n I clear the surrounding lesser mantids and there is a Deathmixer that pats by here.  I cc one of his sidekicks (In order of preference- regenerator > drone > cacophyte > any others) and then engage and kill.   He seems to respawn fairly quickly and it takes me about 15 minutes to get all four.   This is about the only spot on the island where I can get my back to the ocean, not worry about Taoshi pulling others around, and have room to dance around his mantid mines.\n\nThe Deathmixer is one of the easiest to deal with because he does not have any crazy fears, silences, or aerial raids- you simply need to move around his mines like most of the mantid dungeons require.\n\n I recommend doing this either when (a) it's an off-peak time and you're not competing for him or (b) grouping up with people and doing it to ensure you all get credit.",
            date = "2012-10-25T11:31:56-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31197#comments:id=1750174",
        },
        {
            id = 1740430,
            score = 23,
            author = "Beltane",
            text = "There are many elites in this area, and all are objectives of separate quests, however this quest only has four targets: https://www.wowhead.com/npc=63684s, https://www.wowhead.com/npc=63688s, https://www.wowhead.com/npc=63685s and https://www.wowhead.com/npc=63686s.\n\nCopy this into a macro to help you find them more easily, while also preventing you from being dismounted while flying around the feeding pit (if https://www.wowhead.com/quest=31201 is up):\n/cancelaura Swarming Insects\n/tar Sra'thik Will\n/tar Sra'thik Death\n/tar Sra'thik Swarm-L\n/tar Sra'thik Vess",
            date = "2012-10-13T12:05:26-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31197#comments:id=1740430",
        },
        {
            id = 1737979,
            score = 20,
            author = "balatro",
            text = "While the quest does say any elite, this isn't actually true.\n\nThe Sra'thik Swarmlords do not count for this quest (I suspected as such but wanted to test it).",
            date = "2012-10-11T00:08:02-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31197#comments:id=1737979",
        },
        {
            id = 1747696,
            score = 18,
            author = "godlessprayer",
            text = "Thx Blizzard for low spawn rates and tagable quest mobs...",
            date = "2012-10-22T04:24:13-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31197#comments:id=1747696",
        },
        {
            id = 1754918,
            score = 16,
            author = "Fonzy",
            text = "This quest has it all!\n\nLow spawn rates for relevant mobs.\nHigh spawn rates for irrelevant mobs.\nRelevant mobs surrounded by irrelevant mobs you must fight.\nMobs with fear abilities that send you running into other packs of mobs.\n\nAnd my personal favorite:\n\nEvade bugging.\n\nAlso take note that the elite that you were really hoping would count towards this quest - https://www.wowhead.com/npc=63696 - doesn't, because screw you, Love, Blizzard.",
            date = "2012-11-01T10:03:46-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31197#comments:id=1754918",
        },
    },
