    [31199] = {
        {
            id = 1743316,
            score = 29,
            author = "Eaglesight",
            text = "Here is a picture that might come to help. It is taken when looking down onto the eastern part of Sra'vess.\n\nhttp://localhostr.com/files/5YavojH/destroy-the-siege-weapons.jpg\nA second mirror if localhostr is down: http://img833.imageshack.us/img833/7956/destroythesiegeweapons.jpg",
            date = "2012-10-16T12:15:29-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31199#comments:id=1743316",
        },
        {
            id = 1751749,
            score = 19,
            author = "Witherin",
            text = "Here are the locations for the four siege weapons:\n\nSmall Southern Siege Weapon - 27.54, 54.72\nLarge Southern Siege Weapon - 25.75, 53.59\nSmall Northern Siege Weapon - 26.03, 39.94\nLarge Northern Siege Weapon - 27.14, 41.23",
            date = "2012-10-27T11:50:15-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31199#comments:id=1751749",
        },
        {
            id = 1884746,
            score = 7,
            author = "BigZZZ",
            text = "Hint: Dont get stuck under the things when they respawn, you cant click on them and have to use your hearthstone to escape.",
            date = "2013-08-07T12:53:20-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31199#comments:id=1884746",
        },
        {
            id = 1812983,
            score = 4,
            author = "Alexandrias",
            text = "I noticed no one said anything about the type of fight you're going up against.  As a squishy cloth priest, I find the Shado-Pan quests to be a bit daunting, these  NPCs in particular.  Of course, you are granted someone to fight with you.  The girl you get on this quest (Taoshi) seems a little squishy too.  I read one of the notes someone put in the comments about some of the Shado-Pan dailies and was lucky enough to not duel with the hunter Shado-Pan before I read the comments.  Taking him out of assistance rotation helped a lot.  The people who assist me now are for the most part strong fighters...except Taoshi.  Having said that, don't look for these siege weapons anywhere but the side closest to the bridge.  If you use the analogy that the bridge is south, the weapons are found as soon as you cross the bridge on the west side and on the east side (recommend looking at the picture referenced in earlier comment).  Taoshi will stealth you so you can move around, but don't walk too close to anyone.  Don't cast spells while you are stealthed and in the sight line of any of the NPCs.  I healed myself and stealth was removed. They immediately came after me.  Also, if you're squishy like me, the only problem I had was with the siege weapon on the right side of the area off the bridge.  There were too many NPCs - it was the only one I couldn't get out of clean.  Because of the number, Taoshi seemed to go down in EXP fast. If you are a squishy priest like me, I recommend Void Tendriling them and run for the cliff, cast levitate and jump into the water.  They don't follow you there, but Taoshi will.",
            date = "2013-02-13T04:23:01-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31199#comments:id=1812983",
        },
        {
            id = 1937839,
            score = 4,
            author = "Phemenator",
            text = "You can stay in flight form and destroy these as a druid :)",
            date = "2014-01-25T17:14:05-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31199#comments:id=1937839",
        },
    },
    [31200] = {
        {
            id = 1744466,
            score = 123,
            author = "xtina",
            text = "Here's a copy-paste for TomTom users from Moromasa's data (can only use within Townlong Steppes):\n\n/way 21.0, 45.9 Amber Vault\n/way 23.8, 47.3 Nutriment Cell\n/way 23.6, 44.7 Egg Chamber\n/way 22.0, 41.5 Torture Cell\n/way 21.2, 43.2 Slaughtering Pit",
            date = "2012-10-18T00:13:57-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31200#comments:id=1744466",
        },
        {
            id = 1739598,
            score = 80,
            author = "Moromasa",
            text = "Plant Shado-Pan Gas Bombs within the 5 structures on Sra'vess.\nAmber Vault  [21.0, 45.9]\nNutriment Cell  [23.8, 47.3]\nEgg Chamber  [23.6, 44.7]\nTorture Cell  [22.0, 41.5]\nSlaughtering Pit [21.2, 43.2]\n\nHint for TomTom users, use /way +the coords above (without the [ and ] to get them easily)",
            date = "2012-10-12T13:29:50-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31200#comments:id=1739598",
        },
        {
            id = 1752722,
            score = 49,
            author = "Elfgar",
            text = "Simple:  there are red hunter's marks dancing in the entrance of the targets. Place your bag of Shado-Pan bomb at that point.",
            date = "2012-10-28T17:25:29-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31200#comments:id=1752722",
        },
        {
            id = 1737065,
            score = 26,
            author = "Ondisen",
            text = "Just use the provided https://www.wowhead.com/item=86532 at the entrance to all the diffrent buildings around Sra'vess. There should be a red arrow indicating where you should use it if you're unsure.",
            date = "2012-10-10T00:18:39-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31200#comments:id=1737065",
        },
        {
            id = 1811774,
            score = 26,
            author = "lionsofmercy",
            text = "This confused the hell out of me until I realized that the reason the quest marker is on the Shado-Pan Garrison at first is because it expects you to pick up your buddy as the first part of the quest. Even if you have your buddy. Ignore it, and go to the coords listed here. It'll normalize as you approach Sra'vess.",
            date = "2013-02-10T08:03:44-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31200#comments:id=1811774",
        },
    },
    [31201] = {
        {
            id = 1735375,
            score = 18,
            author = "Netn",
            text = "When you fly over the feeding pits you will get surrounded by flies and dismounted after a few seconds. This is presumably to hinder you from just flying to the NPCs and click them.\n\nI would imagine the intent was to use the stealth ability given to you by your companion.\n\nThere is a flaw in that logic though. There is nothing to stop you from mounting up and flying for a few seconds inside the pits so once you have spoken to one NPC you can mount up, quickly get out of the feeding pits, and circle around to the next NPC. They are located very close to the feeding pit edges so its very easy to just land next to them before you get dismounted. Make sure the big bugs are not close when you land though.",
            date = "2012-10-08T07:52:32-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31201#comments:id=1735375",
        },
        {
            id = 1751187,
            score = 16,
            author = "470415",
            text = "I am a nice kunchong, not a mindless eating machine.\n\nIf I am to change this image, I must first change myself!\n\nShado-Pan Trainees are friends, not food! (http://www.youtube.com/watch?v=BN2doCD3YJw)",
            date = "2012-10-26T19:20:23-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31201#comments:id=1751187",
        },
        {
            id = 1849829,
            score = 5,
            author = "stickshift",
            text = "Anyone else find this pit \"by accident?\"",
            date = "2013-05-04T06:26:08-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31201#comments:id=1849829",
        },
        {
            id = 1815343,
            score = 4,
            author = "923022",
            text = "One more advantage to being a druid, Insect Swarm doesn't affect them in flight form.",
            date = "2013-02-18T16:50:55-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31201#comments:id=1815343",
        },
        {
            id = 1855813,
            score = 3,
            author = "299678",
            text = "Don't be part of my stupidity, there is only one \"Feeding Pit,\" but there are smaller \"feeding pits\" where the Shado-pan are found. \"Northern\" pit does not mean northern part of the island, etc. All the Shado-pan are in that one area - so no need to go flying around looking for the others.\n\nIn other words, they're all in one place - one is in the northern part of the place, one in the central, and one in the southern.",
            date = "2013-05-22T10:38:37-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31201#comments:id=1855813",
        },
    },
    [31203] = {
        {
            id = 3147587,
            score = 13,
            author = "KaiBo",
            text = "Entrance to Sra'vess Rootchamber is at: 27.43, 44.13",
            date = "2019-08-15T18:04:36-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31203#comments:id=3147587",
        },
        {
            id = 1800556,
            score = 12,
            author = "998027",
            text = "Little more up to date, his Empower Blades buff no longer snares him (Sorry ranged DPS), it instead will only half his movement speed. So, unless you've got some instant casts, you'll have to keep running till it ends.\n\nAlso important: The Will-Breaker Greater Mantid WILL patrol close to him. He comes up the ramp, but not all the way. So do NOT pull him backward, try to keep him near his spawn or around the hut he stands in front of.\n\nFinally, taking Taoshi for this quest is HIGHLY recommended. She puts the 15% damage increase debuff on him, and will allow you to take him down much quicker, before he has a chance to stack his haste too high. Blow CDs, have her put the debuff on, and he'll be downed in mere seconds. With Taoshi's help, I was able (Spriest) to do over 100K single-target DPS without having any shadow orbs at the start of the fight. He didn't really stand a chance.\n\nEdit: Apparently Wowhead has not made the Horde-side quest. It's exactly the same, I'm guessing the faction icon was a mistake, or they just never put any Horde side identical quests for any of the Targets of Opportunity. These now say \"Side: Both\".",
            date = "2013-01-18T13:22:06-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31203#comments:id=1800556",
        },
        {
            id = 1746379,
            score = 11,
            author = "rodalpho",
            text = "The Sra'thik Swarmlord looks like an easy fight, but due to his stacking haste buff he can deal a surprising amount of damage if you take too long. Blow all your cooldowns to get him down quickly.\n\nAdditionally, when he gets his Empower Blades buff, do what the screen says and run away. It doubles his damage and snares him for 8s.\n\nThere's no need to clear adds around him. Just kite around his little house.",
            date = "2012-10-20T10:13:13-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31203#comments:id=1746379",
        },
        {
            id = 1749821,
            score = 1,
            author = "Eachon",
            text = "Just dont forget to get your companion with you from the camp. I tried this guy as a Shadow Priest without getting the companion, and he destroyed me everytime. He hits like #$%^ when he has 5+ stack of frenzy.",
            date = "2012-10-24T23:00:00-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31203#comments:id=1749821",
        },
        {
            id = 1814815,
            score = 1,
            author = "lionsofmercy",
            text = "Maybe this was just me and I was on crack, but when I LoH, he went to his steps, took a little snooze (like Snorlax) and all his HP reset too.",
            date = "2013-02-17T14:26:09-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31203#comments:id=1814815",
        },
    },
    [31204] = {
        {
            id = 1734981,
            score = 345,
            author = "Ponkana",
            text = "Coordinates for the entrance is 27.1, 44.1, and also the cave looking entrance on the east edge of the island on your map.\n\nAs of the moment the Sra'thik Hivelord has 2757k health pool, and a level 90 elite.\nsummons packs of Sra'thik Workers, casts an interruptable spell, and summons bug swarms that deal 25k damage/second if you stand in them.",
            date = "2012-10-07T22:08:18-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31204#comments:id=1734981",
        },
        {
            id = 1899143,
            score = 74,
            author = "423524",
            text = "Coords to the entrance to the cave to get to Sra'thik Hivelord are 27.3, 44.1. The battle is fairly intense, be prepared, especially if you are going for Loner and a Rebel Achievement [achievement=7299 domain=www]",
            date = "2013-09-17T03:45:59-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31204#comments:id=1899143",
        },
        {
            id = 1761273,
            score = 58,
            author = "243447",
            text = "If you're having trouble with this quest wait outside till you see one or more players entering the cave and join them, or go inside and see if other players are already there. You don't need to be grouped to get credit.  Here's what happened to me. When I got there and went inside there were 2 players already attacking the Hivelord. All I did was hit it twice; it died and I got credit for it. I was in the cave literally 20 seconds, maybe less. ~ And yes the entrance is on the East side of the island. It's by the water!\n\nTomTom Coords:  /way 27.1 44.1 Hivelord Cave\n\nHope this helps!",
            date = "2012-11-12T06:12:38-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31204#comments:id=1761273",
        },
        {
            id = 1880251,
            score = 19,
            author = "Silvansaria",
            text = "Not very hard to kill - the hardest part is finding the damn cave...\n\nI must have went inside every house in the area - killed every Mantid I came across and was never able to find it until I looked on here and got the coordinates.\n\nThe entrance is HUGE - on the side of a cliff.\n\n27,44",
            date = "2013-07-24T12:06:32-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31204#comments:id=1880251",
        },
        {
            id = 1740733,
            score = 14,
            author = "Wash13",
            text = "For those of you who cannot burn this boss down fast, or use a slower strategy, the workers are all low health and aoe'd down pretty easily.  The damage they do is not deadly, but don't have more than one set up at a time if you can't self-heal easily.  The swarms he summons can be kited into sonic pools and destroyed.  Once they start spawning, stop interrupting the fields.\n\nEdit: It seems the swarms can no longer be destroyed; they expire after about 30 seconds.",
            date = "2012-10-13T18:26:40-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31204#comments:id=1740733",
        },
    },
    [31207] = {
        {
            id = 1726954,
            score = 259,
            author = "socalldimaginary",
            text = "In case you were confused:\n\nThis is an actual scenario.  You must open the scenario queue window and select it to enter.  It is not a place in Kun-Lai Summit.  Enter the area with Taniss and whoever will not help you.\n\nIt took me like 20 minutes to figure this out.  With help from an equally confused Game Master.  Learn from our inability to read correctly.",
            date = "2012-10-01T04:53:19-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31207#comments:id=1726954",
        },
        {
            id = 2036912,
            score = 88,
            author = "borian",
            text = "After patch 6.0 you need to speak to Lorewalker Fu (http://www.wowhead.com/npc=78709) in the \"Seat of Knowledge\" to enter Arena of Annihilation (http://www.wowhead.com/zone=6219)\n\nLorewalker Fu (http://www.wowhead.com/npc=78709) is located above the Mogu'shan Palace (http://www.wowhead.com/zone=6182) in the Vale of Eternal Blossoms (http://www.wowhead.com/zone=5840)",
            date = "2014-11-17T16:32:28-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31207#comments:id=2036912",
        },
        {
            id = 1690342,
            score = 49,
            author = "Cielos",
            text = "Another \"Ring of Blood\" type questline for Pandaria with those old familiar faces, https://www.wowhead.com/npc=63315 and https://www.wowhead.com/npc=63314.  They are located in the Kun-Lai Summit, down the steps from the Temple of the White Tiger.",
            date = "2012-07-20T12:08:41-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31207#comments:id=1690342",
        },
        {
            id = 1739437,
            score = 42,
            author = "madmurdock",
            text = "Ok. To get one of these weapons, you have to click on the \"i key\". The dungeonbrowser will open. Select Scenarios and chose the \"specific scenario\" Tab and click on \"The Arena of Annihilation\". A group will be created in seconds (at least now :) ). The quest giver is located in the instance (scenario).\n\nYou have to kill 5 opponents with your 3 man group. They were not hard, but if you have 2 bad players, it can be very tough. Good, that i am a hunter, so my turtle could easily tank the Mobs while i was solo dpsing the bosses. ^^ Other classes could get into trouble if your teammates are crap. Then you have to ask your guild members for support because this weapon is quite essential for a good start into raiding/dungeons. Well, no need to explain why ilvl 450 weapons are better than ilvl 410...",
            date = "2012-10-12T09:56:13-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31207#comments:id=1739437",
        },
        {
            id = 1762206,
            score = 28,
            author = "1055103",
            text = "First quest you should do when your character get lvl 90.\nHelps a lot til you find a better replacement in heroics.",
            date = "2012-11-14T06:55:31-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31207#comments:id=1762206",
        },
    },
