    [31232] = {
        {
            id = 1786989,
            score = 1,
            author = "998027",
            text = "Be mindful that the Vengeful Gurthani Spirits have a seemingly abnormally large aggro range. They also fly, so don't de-aggro so easily when you fly away.\n\nThe tablets on the floor are easily found around walls and Gurthani's Watchdogs.",
            date = "2012-12-24T18:01:05-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31232#comments:id=1786989",
        },
        {
            id = 1731478,
            score = -1,
            author = "Crimsonlord",
            text = "Captain Obvious states: You look these square tablets from the floor. They are often found around the sleeping lions. You can also find them next to http://www.wowhead.com/npc=65502 (Warlord Gurthan) for easy looting.",
            date = "2012-10-04T17:09:05-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31232#comments:id=1731478",
        },
    },
    [31233] = {
        {
            id = 1703137,
            score = 91,
            author = "ChrisKoe",
            text = "The extractors are small spider-like looking machines on trees that are surrounded by Sapflies.\n\nUpon activating the extractor (right click it), it will pour the sap in an amber pot below it and the sapflies will attack you. Just AOE the Sapflies, then loot the amber pot.",
            date = "2012-08-22T16:18:46-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31233#comments:id=1703137",
        },
        {
            id = 1719566,
            score = 72,
            author = "Ashvael",
            text = "If you have trouble finding the extractors because of the large quest area provided by Blizzard's Quest Helper, try looking slightly south of where the map says Mire (of Forgotten Mire). You should be able to complete the quest within 2 minutes there.",
            date = "2012-09-26T03:34:37-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31233#comments:id=1719566",
        },
        {
            id = 1775997,
            score = 6,
            author = "Kariyah",
            text = "If you feel lazy, you can obtain the sap without fighting the sapflies at all.\n\nHop on your flying mount and get into the air. Find an extractor and right click it. When the flies aggro onto you, fly straight upwards to de-aggro them. When you land back on the ground, the pot of amber sap should be waiting for you on the ground.\n\nNote, this method doesn't always work, but so far it seems to work the majority of the time.",
            date = "2012-12-05T10:15:00-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31233#comments:id=1775997",
        },
        {
            id = 1731904,
            score = 4,
            author = "NobodyYouKnow",
            text = "...and so, maple klaxxi syrup was created, and there was much cheering among the waffle and pancake fans.",
            date = "2012-10-05T04:03:24-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31233#comments:id=1731904",
        },
        {
            id = 1739964,
            score = 2,
            author = "795337",
            text = "I had a hard time finding these extractors. Just look for the small swarms of Sapfly, they're always right in front of an extractor. They're all over that questing area, but knowing to look for those flies makes it so much easier.",
            date = "2012-10-12T22:53:13-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31233#comments:id=1739964",
        },
    },
