        {
            id = 1729525,
            score = 41,
            author = "estroBiologist",
            text = "A reference to the internet meme \"Nope Nope Nope\", where one sees something so horrible, disgusting, or otherwise disturbing (such as spider eggs), and their only response is \"Nope\", out of complete refusal to accept the existence of such a thing.",
            date = "2012-10-03T04:17:50-05:00",
