        },
        {
            id = 1757516,
            score = 37,
            author = "Azaram",
            text = "If you talk to him after accepting but before completing the quest, you get this:\n\n\"I don't have to explain how to use it, do I?\n\nYou point the scary end at something that isn't burning and you FIX THE PROBLEM.\"\n\nI love this guy. 'More fire' fixes all problems except possibly 'too much fire'.",
            date = "2012-11-05T08:15:21-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31235#comments:id=1757516",
