    [31237] = {
        {
            id = 1728084,
            score = 191,
            author = "43030",
            text = "Any mobs you kill in the area give you a 20 second buff called Pheromone Tracking. Having this buff will show a red cloud/trail surrounding the Eyes of the Empress, even when you are too far away to target them. The Eyes of the Empress are small maggots crawling around on the ground. Click on the Eyes of the Empress to collect them.\n\nYou can also see the Eyes of the Empress when not having the buff, but only if you're really close. You don't see the red cloud then, just the maggots. Collecting an Eye of the Empress also gives you Pheromone Tracking.",
            date = "2012-10-02T00:06:40-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31237#comments:id=1728084",
        },
        {
            id = 1735714,
            score = 70,
            author = "177738",
            text = "I had to increase my view distance and particle density settings in order to see the clouds before the pheromone buff wore off. If I hadn't done that I would probably still be doing this quest.",
            date = "2012-10-08T13:33:30-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31237#comments:id=1735714",
        },
        {
            id = 2394045,
            score = 67,
            author = "AwScz",
            text = "Killing mobs for buff didn’t work for me. Instead slowly search the ground for small glowing insect. Take it and the buff will be now active. You can see the red clouds and complete the quest faster.",
            date = "2016-09-09T12:32:54-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31237#comments:id=2394045",
        },
        {
            id = 3300393,
