        {
            id = 1764580,
            score = 3,
            author = "1056477",
            text = "The name of the quest is a reference to Shakespeare's play, Romeo and Juliet, where Juliet's love for Romeo is forbidden due to only the fact that he is a Montague, whereas she is a Capulet. This makes Juliet ponder over \"what's in a name\" that makes something the way it is. How this is relevant to the quest, I don't know. I think it might have something to do with the fact that the Hozen attack the Jinyu merely because they are, well, Jinyu. Also, the fact that the title \"What's In A Name Name?\" has the word \"name\" repeated is a reference to how most Hozen have double names (such as Kah Kah, Eekle Eekle, Chi Chi, to name a few).",
            date = "2012-11-19T01:24:07-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31239#comments:id=1764580",
        },
