        },
        {
            id = 1726814,
            score = 3,
            author = "Noisome",
            text = "Sun Tenderheart is currently bugged, she is in another phase. In order to work around this bug, you must have pet battle training and a pet at level 5 to do the following:\n\nStand where the quest specifies, next to the wounded on the ground in front of the inn's entrance.\nOpen your pet journal (Shift-P by default), and queue for a pet battle at the bottom right corner.\nOnce your in the pet battle, your free to either battle or forfeit; it does not matter.\nWhen you come out of the pet battle, Sun should be unphased and next to you.\n\nWhen you enter the inn, she will become phased again. Just repeat the steps to make her reappear.",
            date = "2012-10-01T02:11:59-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31243#comments:id=1726814",
        },
