    [31256] = {
        {
            id = 1719021,
            score = 5,
            author = "Shadowbathed",
            text = "To clarify, the [Escaped Yak] isnt the Yak you are looking for.\n\nYou are looking for ones scattered around in the south.",
            date = "2012-09-25T17:14:58-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31256#comments:id=1719021",
        },
        {
            id = 1758966,
            score = 5,
            author = "Omac",
            text = "Double right-click on a Wild Plains Yak, and they will change from green to blue. A rope will appear connecting you to them. You can tow them back to Eastwind Rest; you can run or ride at your option, although I haven't tried using a flying mount. Take them to the middle of camp and you'll get a delivery confirmation message for each of the three yaks.\n\nAs far as I can tell, you can can only capture one yak at a time.",
            date = "2012-11-07T21:07:47-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31256#comments:id=1758966",
        },
        {
            id = 1930241,
            score = 1,
            author = "AniDanny",
            text = "I just finished this quest horde-side.  The quest-tracker showed me where to turn them in, so I ran to the objective.  I wasn't really paying attention, though, because the marker was in Westwind Rest (the alliance camp).  The yaks disappeared and I got all three credits, though.",
            date = "2013-12-30T07:55:23-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31256#comments:id=1930241",
        },
