    [31260] = {
        {
            id = 1670070,
            score = 15,
            author = "269214",
            text = "An obvious reference to Charlie Sheen.\n\nYou receive a quest item called [Ancient Tiger's Blood] with \"A valuable commodity to warlocks\" as flavor text.",
            date = "2012-05-23T22:33:17-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31260#comments:id=1670070",
        },
        {
            id = 1799341,
            score = 10,
            author = "digitalutopia1",
            text = "A tiger this size could easily eat two and a half men!",
            date = "2013-01-16T06:35:38-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31260#comments:id=1799341",
        },
        {
            id = 1686039,
            score = 7,
            author = "ldene",
            text = "This'll be the mob your looking for https://www.wowhead.com/npc=63767, found at 62.32.",
            date = "2012-07-08T16:28:21-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31260#comments:id=1686039",
        },
        {
            id = 1792498,
            score = 4,
            author = "998027",
            text = "It's a good idea to be Nesingwary of the Alliance Scout that travels near https://www.wowhead.com/npc=63767. If you're not a plate-user (Or a Shadow Priest), you might have difficulty taking them on at the same time.",
            date = "2013-01-04T13:56:01-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31260#comments:id=1792498",
        },
        {
            id = 1917712,
            score = 2,
            author = "Aliandrin",
            text = "Already waist-deep in Gob filth (and in this mini quest chain) the voice of Mylune (http://www.wowhead.com/npc=52671) calls you. It is distorted, but it is her. \"I beg of you, do not kill such a beautiful and ancient tigress. You do not want to do this. I pray you: Do not do this.\"\n\nA quest pops up. Warning: You will abandon Profit Master: Chasheen if you accept this quest.\n\nQuest Accepted: Enemy of the Wild.\n\nReturn to Daggle Bombstrider (http://www.wowhead.com/npc=58779) and fill her wretched vial with her own blood.\n\nThe voice of Mylune speaks once more. You can now barely hear her through the distortion. It is, however, very clear in your mind what she wants to be done. Daggle Bombstrider must die.\n\nShe must die... painfully. She must die in agony equal to that which her filth kin of the Nesingwary Safari have inflicted.\n\nOnce the Goblin is dead, her corpse is lootable. You receive item: Goblin Blood. Quest Completed: Enemy of the Wild. Another quest appears.\n\nThe voice of Mylune is almost incomprehensibly garbled now, but it seems she wishes you to bathe in the blood of the Goblin.\n\nThe blood is right-clickable, turning you red and giving you a buff called Fanatical Environmentalism. Due to the overwhelming urge to slaughter humanoids and preserve nature, your attack power against humanoids has been doubled. Your attack power against beasts has been halved.\n\nAnother Quest appears. Greatest Enemy of the Wild.\n\nWhat you were once sure was the voice of Mylune now sounds like lava roiling, earth breaking, wind howling, and a thousand souls sinking into oblivion forever. You are positive she wants you to slaughter Hemet Nesingwary (http://www.wowhead.com/npc=58421). Once you do this, suck out his soul, place it in this jar, and cast it into the rift that will open below you.\n\nYou Receive Item: Evil Soul Jar\n\nWhat? No, it's not an evil soul jar, it's an evil soul jar, for evil souls, you see.\n\nAfter slaughtering the greatest threat to the wild, the rift in Pandaria begins to open. The jar echos with the blood-curdling scream of the soul inside. The rift below you leads down into writhing flame and unspeakable terrors. You look away, for what you see could easily sear your soul to ash. You cast in the jar. Quest Completed: Greatest Enemy of the Wild.\n\nYour reputation with the Twilight's Hammer has increased by 36,000. You are now neutral with the Twilight's Hammer.\n\n(I can dream, can't I?)",
            date = "2013-11-12T23:23:17-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31260#comments:id=1917712",
        },
    },
