    [31270] = {
        {
            id = 1732059,
            score = 4,
            author = "Tharama",
            text = "I highly recommend Rik'kal the Dissector's Enhancement, https://www.wowhead.com/spell=127794 for this daily quest. It has a high chance of proccing and just one explosion will kill the rest of the scorpions.\n\nAlso, the daily https://www.wowhead.com/quest=31024 happens the same day making Children of the Grave even better. You can pull turtles into your soon-to-explode egg sacs to take down more then half their health before the fight even truly starts.",
            date = "2012-10-05T07:41:26-05:00",
