    [31288] = {
        {
            id = 1730356,
            score = 94,
            author = "911677",
            text = "I took a chance and handed this one in.  You do indeed lose your 20 fragments.\n\nIncredibly NOT worth it, until you have all of the possible Mogu results and don't even care about trying for pristines.",
            date = "2012-10-03T18:44:42-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31288#comments:id=1730356",
        },
        {
            id = 1723023,
            score = 13,
            author = "487723",
            text = "You need 20  Mogu Archaeology Fragment (http://www.wowhead.com/currency=677/mogu-archaeology-fragment)\n\nAcquired by archaeology digging.",
            date = "2012-09-28T11:20:07-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31288#comments:id=1723023",
        },
        {
            id = 1723645,
            score = 13,
            author = "24587",
            text = "Quest offered to Non-archeologists as well.. Oddly...",
            date = "2012-09-28T22:06:55-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31288#comments:id=1723645",
        },
        {
            id = 1799488,
            score = 12,
            author = "Eillesthis",
            text = "The [skill=794] quest varies daily between this and https://www.wowhead.com/quest=31291.  For some reason - probably error - https://www.wowhead.com/quest=31289 is not currently in the game.  You can tell what the daily is without going inside: just hover over the blue exclamation point on your mini map and see if the quest giver is https://www.wowhead.com/npc=63984 or https://www.wowhead.com/npc=63983.\n\nSave your Mogu Archaeology Fragments (http://www.wowhead.com/currency=677) to restore artifacts on the days when the daily quest is https://www.wowhead.com/quest=31291.  You can then crate them into https://www.wowhead.com/item=87399s and use them to buy Crates of other Races' Archaeology Fragments from https://www.wowhead.com/npc=64922.  Definitely not worth it even if you have completed all of the Mogu artifacts, unless maybe you have completed all artifacts of all races.",
            date = "2013-01-16T12:55:02-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31288#comments:id=1799488",
        },
        {
            id = 6280951,
            score = 1,
            author = "Punie",
            text = "1. You need [skill=794] for this. You can learn it from Brann Bronzebeard right next to the quest giver.\n2. Open map and fly to any Digsite in Pandaria. On the side of the map you have a feature called \"Map Legend\", click on the Digsites for them to be seen easier.\n3. Do https://www.wowhead.com/spell=80451 (archeology ability) on the Digsite spots across the map. If you are lucky the ability may spawn a sha creature https://www.wowhead.com/npc=62596 that drops the [currency=677]\n\nThe quest didn't reward any reputation.",
            date = "2026-02-11T13:36:54-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31288#comments:id=6280951",
        },
    },
