    [31303] = {
        {
            id = 1720215,
            score = 352,
            author = "515518",
            text = "This is a bombing quest.  Fly with Mishi again, once you hit the statue you will see grey smoke coming from the ground.  Press 1 and click on the grey smokes.  You will keep going in circles until you finish the quest.",
            date = "2012-09-26T13:43:01-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31303#comments:id=1720215",
        },
        {
            id = 5617783,
            score = 124,
            author = "Chuntah",
            text = "For people going back to do low level stuff.  You need to complete this quest on Mishi, who is hovering right next to Lorewalker Cho.  You cannot fly down to the sha on your own mount.",
            date = "2023-05-27T00:05:35-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31303#comments:id=5617783",
        },
        {
            id = 1723030,
            score = 52,
            author = "clarkeyboy",
            text = "A hotfix has now been applied:\n\nIf you have not yet completed this quest and fall down, you can return to Mishi at both Grookin Hill (Horde) and Pearlfin Village (Alliance).\n\nHope that helps!",
            date = "2012-09-28T11:25:00-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31303#comments:id=1723030",
        },
        {
            id = 1718373,
            score = 30,
            author = "Lopina",
            text = "Has anyone fallen down and does not know how to get up again?\n\nEdit:\nAfter trying to wall-jump and speaking to GM I found a way. Get inside that hut (house) in the base of the hill. Use \"Unstuck\" option, but make sure your HS is on cooldown, so you do NOT get ported to inn. You will die and your ghost will be up the hill, next to a spirit healer there. From there, resurect with spirit healer and res sickness :D",
            date = "2012-09-25T06:25:27-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31303#comments:id=1718373",
        },
        {
            id = 5858222,
