    [31322] = {
        {
            id = 1752460,
            score = 31,
            author = "6532",
            text = "For cooking https://www.wowhead.com/item=75037 need https://www.wowhead.com/item=74846 x5 and https://www.wowhead.com/item=74847 x5.\nhttps://www.wowhead.com/item=74846 x50 https://www.wowhead.com/item=74847 x50 for quest.\nNeed 550 [skill=980] for learn https://www.wowhead.com/item=75037 at https://www.wowhead.com/npc=58717. Cook https://www.wowhead.com/item=75026 for up your skill, https://www.wowhead.com/item=74845 for coocking sold by https://www.wowhead.com/npc=64231.",
            date = "2012-10-28T08:54:04-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31322#comments:id=1752460",
        },
        {
            id = 1724993,
            score = 20,
            author = "lightclaw",
            text = "Buying the ingredients for this quest requires 4 Ironpaw tokens.  The followup quest, Buy a Fish a Brewery (http://www.wowhead.com/quest=31323), requires 12 and is probably not worth doing unless you're really OCD about such things.  That said, having a yellow exclamation point sitting there for an entire expansion will drive me insane.\n\nFor people with a bigger farm and more patience, this quest can be farmed in a couple of days, depending on your yield and how many plots you want to devote to this quest.",
            date = "2012-09-29T18:18:10-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31322#comments:id=1724993",
