            score = 3,
            author = "Taraezor",
            text = "To assist you all with https://www.wowhead.com/object=210565 collecting, [faction=1272] reputation grinding and each farmer's reputation I made an AddOn which I put up at Curse (https://www.curseforge.com/wow/addons/handynotes-dark-soil-tillers).\n\nIt has almost all the Dark Soil locations plus all the help you need for finding each farmer, the correct gift to give, a few map markers for getting the questing underway and so on. Plus... recently I added Dog! Why? Well... because we all love Dog!\n\nI look forward to all your feedback - just follow the link above - on how I can continue to improve this AddOn. I hope that you found it useful!",
            date = "2023-01-15T03:07:00-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31322#comments:id=5527874",
        },
    },
    [31323] = {
        {
            id = 1722158,
            score = 212,
            author = "Ciel",
            text = "The guy is clearly as drunk as his name suggests. If he thinks a player is going to give him something that takes that much effort for a reward that !@#$ty, he is clearly the drunkest of drunkards.",
            date = "2012-09-27T21:13:36-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31323#comments:id=1722158",
        },
        {
            id = 1731892,
            score = 132,
            author = "Partyrocked",
            text = "You will get this quest when you are within 6000 rep of being his Best Friend. The gold reward seems to be wrong as mine only offered 19g 84s 50c for completion, more reason Not to do this quest. Best choice would be to make https://www.wowhead.com/item=74643 for his daily https://www.wowhead.com/quest=30439 as it only requires 10 https://www.wowhead.com/item=74841 and farm the https://www.wowhead.com/item=79267 for remaining rep needed.\n\nIf you dont have any carrots, you can purchase a https://www.wowhead.com/item=87707 for 1 token which contains 25, enough for 2 dish dailies.",
            date = "2012-10-05T03:49:47-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31323#comments:id=1731892",
        },
        {
            id = 1697341,
            score = 84,
            author = "sdkphoenix",
            text = "Unless you have the mats for this, I suggest not doing this quest and save yourself 4 ironpaw tokens. It is probably faster and cheaper to just farm the gifts than doing this quest.",
