        {
            id = 1795977,
            score = 65,
            author = "kakes",
            text = "Oh Sheepie, you wandering rapscallion you. All that wanderlust is going to get you into trouble one day, mark my words!\n\nThis quest is available when you hit Friendly reputation (the fourth of the reputation ranks) with Chee Chee, one of the few hozen Tillers. It's a cute and simple way to gain reputation with Chee Chee. If you have coordinates, Sheepie can be found at 47,37, at the east side of the Heartland where the purple cabbage grows.\n\nGo bring that silly muttonhead home!",
            date = "2013-01-10T13:17:47-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31339#comments:id=1795977",
        },
        {
            id = 1724560,
