    [31340] = {
        {
            id = 1734878,
            score = 182,
            author = "Lightbrand",
            text = "I was on my cloud serpent looking for sheepie when I think I noticed a white ball of fur.\n\nI swoop down anticipating myself to simply grab the little fella without even having to dismount as per what I did the previous two time, only to suddenly dismount in shock to seeing Sheepie's dead carcass...\n\nI can already feel the rage building within myself but before I could even closely examine what happened I was suddenly attacked by this monkey guy.\n\nWithout even confirming whether the culprit had just showed himself to me, All the rage and anger were released in that one instance.  Everything procced as if the stars were aligned, Colossus Smash, crit, Bloodthirst, crit, enraged, bloodsurge, Raging blow, crit, wild strikes, execute.\n\nBefore I came to my senses the monkey creature already stopped moving, lying next to Sheepie.  I looked around me, the sun was shining, it was such a nice day.  I gave Sho an apple, and went back to Chee-chee...",
            date = "2012-10-07T19:10:35-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31340#comments:id=1734878",
        },
        {
            id = 1725290,
