    [31372] = {
        {
            id = 1723171,
            score = 12,
            author = "Qoko",
            text = "Are these direction quests for Yoon live? I just started his chain till I noticed he ends these (this and the Horde version) breadcrumb quests as well. However, they have no quest starter, seem not to be live? Anyone have a definite answer on this?\n\nEDIT: the quest starter has now been added and is among the faction representatives in the Shrines in the Vale of Eternal Blossom. The quest is not available to me and is likely not when you do the first quest given to you by Yoon in the Valley of the Four Winds; anyone with cooking and passing by Halfhill will likely have done this quest before they are 90 and at their faction shrine, making this one of the few representative quests that is kind of obsolete.",
            date = "2012-09-28T13:46:00-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31372#comments:id=1723171",
        },
        {
            id = 2002332,
            score = 5,
            author = "123042",
            text = "This quest does exist on live, but is very hard to get.\n\nIt requires level 90, but at level 85-87 everyone gonna pass through Halfhill and very likely has contacted with someone of the Tillers. Apparently if one has completed the next step https://www.wowhead.com/quest=30252 one is unable to get this quest. In addition, it's likely (needs to be confirmed here) that either https://www.wowhead.com/quest=31281 or \"discover Yoon's farm\" or both are semi-exclusive to this quest\n-- the \"semi-exclusive\" means that if you have done you wont be able to get this quest (no yellow ! ), but if you have accepted this quest (in your Quest Log list) before you have done, they wont affect each other and can be done in any order.\n\nWhile this assumption needs to be verified, I can confirm that if you carefully keep yourself away from anyone of the Tillers, particularly those in the market, until ding 90, you will be able to see this quest downstairs of the Shrine. You can discover Halfhill and use its flight path though.",
            date = "2014-09-13T14:17:55-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31372#comments:id=2002332",
        },
        {
            id = 2556880,
            score = 5,
            author = "NikNovi",
            text = "The quest IS NOT available to my Demon Hunter, and he never did anyhing in Pandaria.\nIf it really exists, there must be some other requirement / restriction.\nI don't think there is max level restriction, at least Wholly addon doesn't show it.",
            date = "2018-03-09T00:23:39-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31372#comments:id=2556880",
        },
        {
            id = 5527190,
            score = 1,
            author = "Taraezor",
            text = "To assist you all with https://www.wowhead.com/object=210565 farming I made an AddOn which I put up at Curse (https://www.curseforge.com/wow/addons/handynotes-dark-soil-tillers).\n\nIt has almost all the Dark Soil locations. I threw in some other stuff too such as the NPC home locations and the gifts that they prefer as well as a brief guide to questing to help you get started.\n\nAnd... I didn't forget Dog!\n\nTo give me feedback on how to improve the AddOn so that it may better assist you then please click the above link. Many thanks for your support over the years!",
            date = "2023-01-14T00:13:51-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31372#comments:id=5527190",
        },
