            author = "137414",
            text = "I had trouble with where the quest marker showed up on my map.  The ? to turn this in was appearing by the mailbox at the lower level, but Elder Sage Tia-Feng was actually in the building at 54, 62; a bit north of where the ? was.",
            date = "2012-11-04T12:28:14-06:00",
