    [31386] = {
        {
            id = 1743857,
            score = 22,
            author = "neiljwd",
            text = "For anyone wondering how to get into Townlong Steppes, Entrance is the ox-Gate at 29,63 in the Westernish area of Kun Lai, east of Winters Blossom.\n\nBut if you travel to 45,90 in Kun-Lai, South west of Westwind Rest there is  the Shado-Pan Fallback, a tower with red doors you can enter, go up the stairs, and then you're on the wall, you can the just hop over into Townlong Steppes.",
            date = "2012-10-17T05:57:17-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31386#comments:id=1743857",
        },
        {
            id = 1793956,
            score = 10,
            author = "Dimikcz",
            text = "These 3 quests are concurrent. You can accept and complete only one of them.\n\nhttps://www.wowhead.com/quest=31386\nhttps://www.wowhead.com/quest=31695\nhttps://www.wowhead.com/quest=30768",
            date = "2013-01-06T23:37:44-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31386#comments:id=1793956",
        },
        {
            id = 1877088,
            score = 0,
            author = "1132718",
            text = "If you're trying get to Longying Outpost inTownlong Steppes from the Vale of Eternal Blossoms you'll need to go through Kun-Lai Summit by way of the Golden Stairs (same way you got in there in the first place before you could fly). Follow the road West/Northwest around the mountain ridge, just past Winter's Blossom you'll find the Ox Gate at 29,63. Continue South and you'll run into the Longying Outpost. I'll post some screenshots of the map for better reference.",
            date = "2013-07-15T08:10:03-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31386#comments:id=1877088",
        },
    },
