    [31394] = {
        {
            id = 2346055,
            score = 109,
            author = "SFFCorgi",
            text = "If you are doing this well into WoD, you might find the progression sticking on you.  After reading the comments here, I found that moving around during the fight - even if it's normally a one- or two-hit kill for you - will keep the sequence of tests moving along properly.  Pace your blows by the dialogue going on between the northerners, Pandaren, and Xuen.",
            date = "2016-06-28T23:53:24-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31394#comments:id=2346055",
        },
        {
            id = 1725127,
            score = 80,
            author = "cautious",
            text = "For this quest you must complete three tests, each involving the killing of a spirit:\n\nTest One: Spirit of Violence - Casts \"Sha Corruption\", creating a deadly cloud wherever you are standing. Make sure you are moving when it finishes casting so you are out of the way.\n\nTest Two: Spirit of Anger - Along with the previous spell, it casts \"Devastation\", creating bubbles all around your initial position. Move out of the way immediately to make sure you are not caught in it.\n\nTest Three: Spirit of Hate - Along with the previous two spells, it casts \"Whirlwind of Anger\". It takes a few seconds for him to warm up so make sure to move as far away from him as possible so that when he begins coming after you, you are out of range of his blades.\n\nRemember those simple rules and you should be able to pass the tests with no problem. Get caught in any of those attacks and you will likely lose 1/3 to 1/2 of your health very quickly.\n\nP.S. If there are others doing the quest at the same time, make sure to move away from them. The spirit will follow you and you will then be sure of not getting caught up in the attacks of someone else's spirit.",
            date = "2012-09-29T20:19:08-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31394#comments:id=1725127",
        },
        {
            id = 1737964,
            score = 33,
            author = "Sunreaver",
            text = "On the last part, the Sha of Hatred, be careful if you're kiting the mob around the room like I was. Apparently if you get too far from the center of the room, the mob runs back towards the center and disappears. This happened to me twice, but you can restart just that phase by talking to the tiger again.",
            date = "2012-10-10T23:18:58-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31394#comments:id=1737964",
        },
        {
            id = 5866595,
            score = 26,
            author = "Kamillah",
            text = "Just did this quest in Mists of Pandaria Remix and got stuck after passing the two first tests. Flying out of the room and back in again (changing zones) fixed it. I was able to speak to Xuen again and he started the third and last challenge.",
            date = "2024-05-26T10:55:37-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31394#comments:id=5866595",
        },
        {
            id = 2299921,
            score = 21,
            author = "360683",
            text = "So I tried this as a lvl 100 and it bugged after the first test. I left the temple and walked back in to Xuen and it continued where it bugged and it finished easily. A GM said it is because we kill too quickly at lvl 100. If it happens to you try walking out of the temple down the steps and back in again.",
            date = "2016-01-19T11:16:57-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31394#comments:id=2299921",
        },
    },
    [31395] = {
        {
            id = 2364208,
            score = 118,
            author = "1063987",
            text = "If this quest breaks for you, (a) make sure no one else in the room is doing the three trials. (b) If it still breaks, leave each Spirit alive until the dialogue finishes.",
            date = "2016-08-10T00:39:46-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31395#comments:id=2364208",
        },
        {
            id = 1731715,
            score = 69,
            author = "Syio",
            text = "Experienced players should have no problem dodging/ moving out of the bad stuff. Seems to be a concept Blizzard wants to enforce into new players.\n\nOne thing though; my characters -don't- hate Varian. The Spirit of Hate should have shown mages pwning me in PVP instead. That. Is. Real. Hate.\n\nYes, I am mad.",
            date = "2012-10-04T22:49:03-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31395#comments:id=1731715",
        },
        {
            id = 2447058,
            score = 59,
            author = "BlackHalo66",
            text = "The quest appears to have some bugs in it and it would not continue with each of the tests.\nAfter dropping and restarting the quest several times, what eventually worked for me was to:\n\nPick up the quest\nSpeak to Xuen the tiger\nWait for the first test to start\nWhen the test begins, run to Anduin and take a few hits\nKill the target mob\nRinse and repeat\n\nThis method seemed to keep the dialog moving and I was able to complete the quest.",
            date = "2016-11-21T20:19:15-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31395#comments:id=2447058",
        },
        {
            id = 1728751,
            score = 58,
            author = "814813",
            text = "I'm a (uh hmm) newer, more mature player (age 53) and this was kicking my butt on my LV 87 Paladin... badly!  So, I called in my 18 yr old son who has been RAIDing since he was 12, and he showed me how easy it can be with just some patience and not trying to man handle this.  With 200k health on my character, my son soloed all 3 and his health was never was below 170k (and he doesn't play a Paladin).  Boy did I feel silly.  He just \"kited\" like the previous poster stated, used spell interrupts and stuns effectively.  But, mostly, just move around and be patient.   Back to training for me.",
            date = "2012-10-02T12:49:51-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31395#comments:id=1728751",
        },
        {
            id = 1803273,
            score = 38,
            author = "Karsciyin",
            text = "Prove you are not a violent killer by violently killing!\n\nHonestly, I was hoping you'd conquer it by means different to just MOAR SPANK, especially since the problem with you in the first place is that your first response is MOAR SPANK. Like, conquer violence by not fighting back, after which it fades away. Conquer anger by clamly sitting down, or /hug, I don't know, and conquer hate by... some.. representation of forgiveness, I guess?\n\nPretty much anything except beating the crap out of it, which is exactly what we're supposed to do. Use your skill in angry combat to destroy the avatars of your... angry... combat?",
            date = "2013-01-24T00:33:46-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31395#comments:id=1803273",
        },
    },
    [31398] = {
        {
            id = 2082087,
            score = 46,
            author = "shylee",
            text = "If you have already started the quest line, but somehow got lost, try looking inside the Amberglow Hollow cave.\nI was looking for about an hour before I found Kor'ik inside with two new quests.\nIf you are traveling on ground above the cave, the quest indicator phases out very quickly, so it is easy to miss it. You have to go inside to be able to see the quest marker.\nThe cave entrance is at 46.4, 52.8.\nGood luck~!",
            date = "2015-01-04T01:19:39-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31398#comments:id=2082087",
        },
        {
            id = 1733465,
            score = 23,
            author = "dasbaum",
            text = "You need to have https://www.wowhead.com/quest=31092 AND https://www.wowhead.com/quest=31359 completed to be able to turn in this one.",
            date = "2012-10-06T13:48:06-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31398#comments:id=1733465",
        },
        {
            id = 1804469,
            score = 3,
