    [31439] = {
        {
            id = 1736058,
            score = 94,
            author = "Ralphius",
            text = "Must be revered with Klaxxi to get this quest.",
            date = "2012-10-08T20:56:12-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31439#comments:id=1736058",
        },
        {
            id = 1728571,
            score = 89,
            author = "KannoFire",
            text = "The NPC you need to set free is inside a small amber block, on the ground, behind a large root.  You'll see a gear icon on your minimap, and the amber block itself also has a small gear icon above it.  Targeting the block itself does nothing; you have to stand next to the block and use the quest item itself.\n\nCoordinates 56,58.",
            date = "2012-10-02T09:53:32-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31439#comments:id=1728571",
        },
        {
            id = 1789217,
            score = 45,
            author = "TakingMocha",
            text = "I had the same problem as anafielle's post (unable to see Hisek/ unable to complete quest).  I believe the \"possible glitch\" happens when you're doing the quest as a party, only the 1st person who uses tuning fork proceeds with the animation.  I saw the traitor sequence on my wife's screen but not mine.  I eventually had to abandon the quest and redo - phasing/ leaving zone did not work.  A second glitch happened even after I did the traitor sequence properly - I handed in quest but got no new quests (my wife received 2).  This time the phasing in/out of zone worked.  My guess is, don't do this quest grouped.",
            date = "2012-12-29T16:51:46-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31439#comments:id=1789217",
        },
        {
            id = 1760013,
            score = 33,
            author = "1051213",
            text = "The amber block is smaller than the ones the other paragons were in, only the top part shows. It's behind a root in an area sort of hidden at (56, 58) near the area with very shallow greenish water. You can't right click on the amber block either, you have to right click the tuning fork.",
            date = "2012-11-09T21:55:12-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31439#comments:id=1760013",
        },
        {
            id = 1818422,
            score = 32,
            author = "784906",
            text = "This NPC is not in the cave with the Crocolisk Mobs. He is over where the Fen Stalkers are to the west. He's in an alcove type area, in amber. Just go over to the amber with the gear icon over it and right click on your Klaxxi Tuning Fork that Kor'ik gave you.",
            date = "2013-02-26T09:43:37-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31439#comments:id=1818422",
        },
    },
    [31440] = {
        {
            id = 1676482,
            score = 36,
            author = "Cielos",
            text = "\"In the Shadow of the Light\" is in The Reliquary (First room)\n\n\"Kel'Thuzad's Deep Knowledge\" on a bookshelf to the left (or to the right) in the Hall of Illusions (Second room)\n\n\"Forbidden Rites and other Rituals Necromantic\" is in the Butcher's Sanctum to the right before the Flesh Horrors (or after and to the left) (Third room)\n\n\"The Dark Grimoire\" is on Professor Slate's table in the Viewing Room (Fourth room)\n\nEdit: Upon running this dungeon on live, it appears the spawn points may vary.  These are the spawn points it gave me.  If you're having trouble finding the Dark Grimoire, I've had it spawn in the back right of the room on a table.  The sparkles are barely visible, so you really have to look for it.",
            date = "2012-06-14T01:35:01-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31440#comments:id=1676482",
        },
        {
            id = 5858092,
            score = 7,
            author = "FlayOnDarkIron",
            text = "In Remix this book for some reason requires level 40 to click on.  I can't recall any other quest objective like this that was locked behind a level requirement but not the actual quest itself. Why didn't they just make the quest require level 40?",
            date = "2024-05-17T19:40:10-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31440#comments:id=5858092",
        },
        {
            id = 5866276,
            score = 3,
            author = "AlexL1118",
            text = "In \"Remix: Mists of Pandaria\" there is probably some bug with this quest: we can take this quest in Normal difficulty, but can advance it only on Heroic. Destroying a tome in Normal does not advance the quest.",
            date = "2024-05-25T20:23:38-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31440#comments:id=5866276",
        },
        {
            id = 5928754,
            score = 3,
            author = "cylvanis",
            text = "You need to complete this quest on normal difficulty. When I tried it on heroic difficulty, the books would spawn and burn when clicked, but I didn't receive any credit. Despite having different spawn points in the rooms, the books sparkle, making them very easy to find.",
            date = "2024-08-24T16:30:40-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31440#comments:id=5928754",
        },
        {
            id = 1743962,
            score = 1,
            author = "ayligerwolf",
            text = "it seems that dark Grimoire has a bug at it does not appear as it should for those whole have this quest. dark Grimoire did not appear for me either after 2 runs. Might have to drop quest, pick it up again or just forget it and move on. Not worth breaking your head over it.",
            date = "2012-10-17T09:25:26-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31440#comments:id=1743962",
        },
    },
    [31441] = {
        {
            id = 1728778,
            score = 352,
            author = "mysticalos",
            text = "Available after hitting revered and releasing Hisek\n\nWhen you get this quest, do NOT fly off. Wait for some RP, the objective is right here at questgiver.",
            date = "2012-10-02T13:12:49-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31441#comments:id=1728778",
        },
        {
            id = 1734340,
            score = 64,
            author = "817546",
            text = "After killing the traitor in this quest the quest giver just stood around and didn't give me the option to turn in however a relog fixed it straight away.",
            date = "2012-10-07T09:54:42-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31441#comments:id=1734340",
        },
        {
            id = 1733425,
            score = 51,
            author = "20187",
            text = "If you really fly off, go to 56.25, 58.00.\n\nDrop request, dude respawns, take it, wait about 20 seconds, kill new guy.",
            date = "2012-10-06T13:10:23-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31441#comments:id=1733425",
        },
        {
            id = 1768426,
            score = 37,
            author = "moonrai",
            text = "If you can't find Hisek, but you have this quest in your log, go to 56.2,58.2 (beneath the very large roots of the tree) and drop the quest and Hisek will appear with the quest again. Take it, and STAY with him for the turn-in.",
            date = "2012-11-26T22:54:55-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31441#comments:id=1768426",
