    [31442] = {
        {
            id = 1708248,
            score = 43,
            author = "801624",
            text = "In the Shadow of the Light is in the same room as the first boss, near the bottom of the stairs on the left side (coming from the entrance).\n\nKel'Thuzad's Deep Knowledge is in the Halls of Illusions on a shelf on the left side (this one is hard to miss).\n\nForbidden Rites and other Rituals Necromatic is in the southwest corner of the Butcher's Sanctum, on top of a table.\n\nThe Dark Grimore is in the viewing room, on the highest platform, in the corner on top of a stack of books.\n\nAnd now you've found all of the books! =D\n\nEdit: These are the locations for the non-heroic mode. I haven't run it on heroic yet, but once I do I will update.",
            date = "2012-09-02T14:01:59-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31442#comments:id=1708248",
        },
        {
            id = 1742353,
            score = 15,
            author = "1026332",
            text = "Just got the quest as part of a random heroic, and then the group was in a hurry so I only got 3 books. The rest of the party split and the remaining mobs were too tough for me to solo. Went back after dying, and the dungeon and epic was now regular level 43 - and couldn't finish the quest. Found the missing books and destroyed them, but the quest didn't seem to register them. So now, I have to basically put together a group at heroic level. Or just abandon, which I will probably do.\n\nAt least I got the heroic level 90 armor plate though.\n\nEdit: thanks to post below, found out I could change the level of dungeon before I entered. Thanks to androjeans for actually pointing out information rather than merely downvoting.",
            date = "2012-10-15T11:04:41-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31442#comments:id=1742353",
        },
        {
            id = 1739248,
            score = 8,
            author = "1045100",
            text = "The correct reward is 45 gold, 60 silver.",
            date = "2012-10-12T05:45:55-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31442#comments:id=1739248",
        },
        {
            id = 1758540,
            score = 4,
            author = "BJJB",
            text = "The viewing room not the hall of illusions has book shelves, but I couldn't find books in either place ! Where exactly are they ?",
            date = "2012-11-07T04:54:34-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31442#comments:id=1758540",
        },
        {
            id = 1799457,
            score = 4,
            author = "Fyerrkroch",
            text = "If you look on your map, it will tell you the location of each book in the rooms for this quest.\n\nEach book has a specific room/location they are assigned to at first:\n\n1. In the Reliquary, behind Instructor Chillheart on a table.\n\n2. In the Hall of llusions, the closest bookcase to Jandice Barov towards the middle in a shelf.\n\n3. In the Butcher's Sanctum, on a table in the southwest corner (yes, you have the pull more trash mobs).\n\n4. In The Viewing Room towards the back on a table (yes, more mobs need to be pulled).\n\nSomething to remember: If another member of your party got to the book first, and you did not receive credit for the quest (it happened to me), the book WILL RESPAWN in the SAME ROOM but NOT IN THE SAME EXACT LOCATION. I was missing the \"In the Shadow of the Light\" which was by Instructor Chillheart, and it respawned in the opposite side of the room. The map WILL NOT reflect the second location. Happy hunting!",
            date = "2013-01-16T11:41:00-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31442#comments:id=1799457",
        },
    },
    [31447] = {
        {
            id = 3185566,
            score = 2,
            author = "violetta",
            text = "annoyingly you cannot hand this in to Talking Skull at the beginning of the dungeon, so if you forget to hand it in at the end you have to do the whole thing again",
            date = "2020-01-24T14:36:07-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31447#comments:id=3185566",
        },
    },
    [31448] = {
        {
            id = 1917897,
            score = 3,
            author = "renegadelove",
            text = "I also had trouble with finding where i turned in this quest.\n\nYou actually do not turn the quest in to the skull. You will have to do the quest again. Do not rush out of the instance until you turn it in. You will find the NPC on the stairs after killing Darkmaster Gandling.",
            date = "2013-11-13T13:10:13-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31448#comments:id=1917897",
        },
        {
            id = 1915105,
            score = 2,
            author = "Heimdallen",
            text = "I don't know about the above question, but I've had this quest done in my log for like, a year, and today wanted to just turn it in and get rid of it to make space. So I zoned into Scholo, yes I had it on heroic mode, and the skull only offers to let me turn in the other quest he offers, to destroy the tomes. Apparently I cannot turn this quest in to him where he resides just inside the instance? Despite everything on Wowhead here pointing toward the fact that I should be able to?\n\nIs he also in another location, at which location I can turn in the quest? Maybe something like he is at the end in Darkmaster Gandling's room and because I didn't see him there when I did the quest and missed turning it in, now I'd have to run the whole dungeon again just to turn in the last quest from the very end of it? Sigh.\n\nI'm going to assume that's the case as I can't figure out what else the problem might be here. So, yeah, my advice is, when you kill Darkmaster, turn in the damn quest right away, otherwise you're screwed and can't just zone in the front door, turn it in, and leave again. Gotta finish the whole thing again I assume.",
            date = "2013-11-05T09:04:14-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31448#comments:id=1915105",
        },
        {
            id = 1915902,
            score = 1,
            author = "JoeDave",
            text = "I am having the same problem as  Heimdallen. Did the quest a few weeks ago. The talking skull is just inside, but the quest is not available to turn in.",
            date = "2013-11-08T08:49:23-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31448#comments:id=1915902",
        },
        {
            id = 1938758,
            score = 1,
            author = "EGoneStrong",
            text = "I too had the same issue, quest has been sitting in the log completed for months, decided to go turn in, and on heroic I cannot turn in to the skull as this listing suggests.  I decided to see what would happen if I dropped it to normal mode...and the skull offers me the same quest I'm trying to turn in (low level) so my assumption is also that you'd have to run the dungeon again and snag the npc at the end before zoning back out in order to turn in.  I will probably just abandon it, since it's taking up space *shrug*",
            date = "2014-01-28T13:41:44-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31448#comments:id=1938758",
        },
        {
            id = 5200838,
            score = 1,
            author = "AnnieSmokely",
            text = "For those having trouble turning this in\n\nThe floating skull is not the turnin. When the dungeon is over, it turns into the ghost of Alexei Barov (https://www.wowhead.com/npc=64683/spirit-of-lord-alexei-barov) that is the turnin.",
            date = "2021-06-21T22:36:24-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31448#comments:id=5200838",
        },
    },
    [31450] = {
        {
            id = 1750512,
            score = 29,
            author = "Sketchie",
            text = "On one side of Spirit of Master Shang Xi inside the Temple of Five Dawns will stand Delora Lionheart and Aysa Cloudsinger, and the other side will stand Ji Firepaw and Korga Strongmane.\n\nAfter turning in New Allies, a short scene will occur.\n\nSpirit of Master Shang Xi says: You've all accomplished a great thing in saving Shen-zin Su. You do us all proud.\nSpirit of Master Shang Xi says: It seems your journeys are not done. These new allies of ours come from a broken world that could use our help.\nAysa Cloudsinger says: Master Shang Xi, I would like to accompany the Alliance back to their home.\nSpirit of Master Shang Xi says: What of you, Ji? Will you join the Horde in their journey back?\nJi Firepaw says: Yes... perhaps that is for the best. I like what I've seen of them, and it sounds as though their world would use my help.\nSpirit of Master Shang Xi says: And you, my young student? Where will you go?\n\nYou can talk to Aysa, Delora and Ji before you decide as well.\n\nIf you talk to Aysa Sloudsinger, she says the following:\n\nI understand that the mind of the Tushui is not the only path to wisdom, but there are yet choices that should not be accepted. Risks that are too dangerous to ever be taken. Decisions that I cannot forgive...\n\nIt is time for me to leave Shen-zin Su. I have found respect for Delora Lionheart for her confidence and valor, and her people. I do not yet know if I will find a home there, but wherever my path may lead, I will find a way to help the world beyond this isle.\n\nDespite everything, I've enjoyed what little time we've had together, . I hope that you may join me, but I understand that this decision is not an easy one.\n\nIf you talk to Delora Lionheart, she will say the following:\n\nYou are our first turn of good fortune in several days. We're glad to have the help.\n\nOn the other hand, Ji Firepaw says this:\n\nThis day seems to be one full of hard decisions. Having the courage to make them is gravely important, for the sake of us all. I did what I had to do, and we may have all been doomed if I had not... but sadly, not all see it that way.\n\nIt is time for me to leave Shen-zin Su, that those here might be free from the burden of my difficult choice, and that I might fight on for the sake of a much larger world.\n\nI've only known Korga for a short time, but he and I could be brothers if he were born in a different skin - he possesses bravery and honor that I would gladly stand beside. You too could be my brother/sister, after all we've gone through together. I'm hoping you might join us, but I understand that there is much to consider.\n\nKorga Strongmane doesn't even have anything to say which was rather interesting. Maybe Blizzard forgot to put one in, or he's just a \"strong, silent type\" kind of person.\n\nTo make your decision, just talk to Spirit of Master Shang Xi. He will say this:\n\nThere's a broken world that could use your help, my student. Have you decided who you would like to accompany in your journey?\n\nI'm ready to decide.\n\nIf you click on I'm ready to decide, a pop-up will show up with a brief description for each faction and two very important buttons: Join the Alliance and Join the Horde. If you decide to join the Alliance, you will become Alliance along with Aysa Cloudsinger and Jojo Ironbrew. If you decide to join the Horde, Ji Firepaw will accompany you. You can change factions anytime but it would require you to buy a Faction Change from the Blizzard site, so make your choice wisely. You can back out of the screen by simply pressing ESC if you're not sure or you want to explore the island - once you've made your decision, you will never come back!\n\nIf anyone is curious, here's a brief description for each faction:\n\nThe Alliance\nThe noble races of the Alliance are bound together by proud traditions of nobility, honor, faith, justice and sacrifice.\n\nThe many different Alliance peoples all contribute their technical, arcane, and spiritual wisdom toward the goal of a peaceful and just world.\n\nTake up their banner to represent the high ideals of the Alliance throughout Azeroth and beyond.\n\nFor the Alliance!\n\nThe Horde\nThe proud nations of the Horde are loosely joined in an alliance of convenience against a hostile world that would see them destroyed.\n\nFocused, ferocious and sometimes monstrous, the Horde values strength and honor, but struggles to keep aggression in check.\n\nJoin the Horde and fight to build a world where their people can live free.\n\nFor the Horde!",
            date = "2012-10-25T22:25:14-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31450#comments:id=1750512",
        },
        {
            id = 2100304,
            score = 16,
            author = "MinisterJames",
            text = "Without picking a faction, you can...\n...wear any heirlooms you've collected.\n...level to level cap via herbalism and/or mining.\n...learn and level any primary professions to level 75. https://www.wowhead.com/npc=65043 and https://www.wowhead.com/npc=57620 are the trainers.\n...learn how to make up to 28 glyphs via inscription using herbs collected on the island.\n...learn how to make an additional 21 glyphs via inscription using mageroyal, which can be obtained with herbalism from https://www.wowhead.com/npc=55640.\n...have access to any of the 4 forges or 4 anvils on the island.\n...stow your pet with the 1 stable master so that you can tame more pets as a hunter. https://www.wowhead.com/npc=68986\n...summon vanity pets from either faction.\n...not ride any mount except https://www.wowhead.com/spell=64731.\n...not participate in player versus player activities.\n...not participate in pet battles.\n...not make nor join a guild.\n...not have access to a mailbox.\n...not learn any secondary professions, due to a lack of secondary profession trainers.\n...not change your spec once you pick one nor duel spec, due to the lack of class trainers.\n...not change your talents nor glyphs once you pick them, due to a lack of class trainers and access to items that can remove talents and glyphs.\n...not leave the island by any known means, this includes zen pilgrimage, mage teleports, glyphed astral recall, death location exploits, dungeon/battleground queues, graveyard exploits, and outside assistance from players in another faction, as all these means have been either hotfixed to not work or never worked to begin with.",
            date = "2015-02-06T16:25:38-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31450#comments:id=2100304",
        },
        {
            id = 1728929,
            score = 8,
            author = "druunah",
            text = "Click the choose option in the quest text. You will see a brief description of both Alliance and Horde with \"Join the Alliance\" and \"Join the Horde\" buttons below said descriptions. Think it over if you need to and then; Choose your destiny! (faction), Horde or Alliance...",
            date = "2012-10-02T15:49:22-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31450#comments:id=1728929",
        },
        {
            id = 1718979,
            score = 7,
            author = "Roaning",
            text = "Don't click on the twister next to him. You'll have to run outside and jump back down the mountain to get back.",
            date = "2012-09-25T16:33:28-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31450#comments:id=1718979",
        },
        {
            id = 1884363,
            score = 7,
            author = "Ryawy",
            text = "As relevant as it isn't, the first small Pandaren calligraphy character on the Alliance scroll (the one that looks like a X= ) is the same as the symbol on the icon of the Monk ability https://www.wowhead.com/spell=122470 and appears when the ability is used.\n\nEdit: According to this interesting picture (http://wow.gamepedia.com/File:Pandaren_%28language%29.png), the Alliance banner reads something like \"Transportation, shop, mail(?), (unknown), (unknown),\" and the Horde banner says \"(unknown), spirit, family, food, water.\" The second and third symbols are \"family graveyard\" backwards. AMAZING!",
            date = "2013-08-06T00:27:04-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31450#comments:id=1884363",
        },
    },
