    [31505] = {
        {
            id = 1726992,
            score = 14,
            author = "398298",
            text = "Vess-Guard Vik'az (http://www.wowhead.com/npc=64979#comments) is a fairly straightforward fight. He walks about in the open with little risk of running into adds. It's a movement fight for melee, though, so keep your head level.\nHe uses whirlwinds as his most common attack, but also sets down a Whirling Blade (http://www.wowhead.com/spell=127941). Its area of effect is actually a bit larger than the animation seems to indicate (at least so I thought), so until you get a feel for it, better stand an extra yard or two away. The effect doesn't move with him, so just get out of the area and don't go back in, as it lays down quite a whack over its duration.",
            date = "2012-10-01T05:28:20-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31505#comments:id=1726992",
        },
        {
            id = 1834929,
            score = 9,
            author = "572872",
            text = "He is NOT marked as a boss on the map.  You'll find him around coordinates 29, 75.  He doesn't move too far, just sticks around the houses.",
            date = "2013-03-26T20:48:35-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31505#comments:id=1834929",
        },
        {
            id = 1751937,
            score = 6,
            author = "toontown6969",
            text = "if he is disarmed when he casts whirling blade, he goes to cast it again and will repeat casting it until his weapon returns(the spell does not succeed).",
            date = "2012-10-27T15:56:41-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31505#comments:id=1751937",
        },
        {
            id = 1794492,
            score = 1,
            author = "725332",
            text = "He is easy to kill, I am hunter with pvp gear -lvl 90, with spirit bond.",
            date = "2013-01-07T21:39:29-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31505#comments:id=1794492",
        },
        {
            id = 3297555,
            score = 1,
            author = "Unixbeard",
            text = "Also note, while he doesn't pull the Impalers and Manipulators he does re-spawn quite quickly, so if you're still going after the other mobs I'd suggest doing it away from the buildings. Ending up having to kill him three times as the other two he appeared while I was taking out other mobs.",
            date = "2021-02-03T14:24:22-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31505#comments:id=3297555",
        },
    },
