    [31511] = {
        {
            id = 1720040,
            score = 28,
            author = "stevierg",
            text = "This quest turn in is under the gates that you see in the log in screen. Some times the ? on the map shows in the wrong place.",
            date = "2012-09-26T11:14:20-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31511#comments:id=1720040",
        },
        {
            id = 1897401,
            score = 16,
            author = "Smallfoot",
            text = "The dialogue has changed for 5.4:\n\nYu'lon says: Let us draw ourselves together to rebuild this sacred place, the first step toward healing a war-torn world.\nNiuzao says: These outsiders have brought chaos to this land. Can we trust them to set it right?\nChi-Ji says: I have faith in our friends from beyond the mists.\nXuen says: Their strength is an inspiration... and sorely needed. We must trust that their hearts are pure.",
            date = "2013-09-13T17:56:35-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31511#comments:id=1897401",
        },
        {
            id = 2311542,
            score = 15,
            author = "nicholberry",
            text = "No... you are not crazy - Sunwalker Dezco is no longer at the gates. Madame Vee Luo (innkeeper at the Shrine of Two Moons) is now the turn-in for this quest... through the gates, down the Golden Stair and hang a left. Shrine will be around the next corner on your left. Upstairs, through the door on the right - she's right in front of you. Don't forget to make the Shrine your hearth because it has all the portals needed to get where you need to go.",
            date = "2016-03-01T21:11:30-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31511#comments:id=2311542",
        },
        {
            id = 3205323,
            score = 13,
            author = "Nasyna",
            text = "In case you try this quest on a boosted 120 character you have to first finish a quest chain that starts with \"Mogu at the gates\" quest. If you still had the quest (A Witness to History) in your quest book, abandon it and go take it back to the Temple of the white tiger in Kun-Lai Summit (don't forget to talk to Zidormi (80.55, 31.99) to travel into the time before the BE Assault). After that Sunwalker Dezco will indeed spawn at the gates (56.07, 91.51). And once you are done with talking to him, you can go finish the quest at the Shrine of Two Moons (Horde).\n\n[quest=57067 domain=www]\n[npc=163463 domain=www]",
            date = "2020-05-09T09:15:19-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31511#comments:id=3205323",
        },
        {
            id = 1721518,
            score = 10,
            author = "Whiterock",
            text = "Kun-lai Side Story Quest Tree From Whiterock\n[pre]   [del]S[/del])Temple of the White Tiger (http://www.wowhead.com/quest=31392){H (http://www.wowhead.com/quest=31393)}(Multiple zones)\n   [ins]+[/ins])A Celestial Experience (http://www.wowhead.com/quest=31394)   {H (http://www.wowhead.com/quest=31395)}\n   a)A Witness to History (http://www.wowhead.com/quest=31512)     {H (http://www.wowhead.com/quest=31511)}\n   /                           ||\nThe Shrine of Seven Stars (http://www.wowhead.com/quest=30631)(A)* The Shrine of Two Moons (http://www.wowhead.com/quest=30649)(H)*[hr]\nThe Ordo Warbringer (http://www.wowhead.com/quest=30660){A2 (http://www.wowhead.com/quest=30662),H1 (http://www.wowhead.com/quest=30661),H2 (http://www.wowhead.com/quest=30663)}*   [ins]+[/ins])The Kun-Lai Kicker (http://www.wowhead.com/quest=31611)([zone=6426])\n ||\n[del]S[/del])Muskpaw Ranch (http://www.wowhead.com/quest=31456){H (http://www.wowhead.com/quest=31457)}\n[ins]+[/ins])The Missing Muskpaw (http://www.wowhead.com/quest=30488)            [ins]+[/ins])Fresh Needle Scent (http://www.wowhead.com/quest=30489)\n ||           \\\nb)Yakity Yak (http://www.wowhead.com/quest=30587) b)At the Yak Wash (http://www.wowhead.com/quest=30491)   [ins]+[/ins])The Late Mrs. Muskpaw (http://www.wowhead.com/quest=30582)\n ||           /                   b)The Fearmaster (http://www.wowhead.com/quest=30804)\nc)Back in Yak (http://www.wowhead.com/quest=30492)[hr]\nThe Ordo Warbringer (http://www.wowhead.com/quest=30660){A2 (http://www.wowhead.com/quest=30662),H1 (http://www.wowhead.com/quest=30661),H2 (http://www.wowhead.com/quest=30663)}* Barrels of Fun (http://www.wowhead.com/quest=30651){H (http://www.wowhead.com/quest=30656)}* Pandaren Prisoners (http://www.wowhead.com/quest=30650){H (http://www.wowhead.com/quest=30655)}*\n                          \\          ||            /\n                          [del]S[/del])The Missing Merchant (http://www.wowhead.com/quest=31452){H}