    [31512] = {
        {
            id = 1725681,
            score = 43,
            author = "Aros",
            text = "At the completion of this quest the gates to Vale of Eternal Blossoms (http://www.wowhead.com/zone=5840) will be opened which will gain you access to Shrine of Seven Stars (http://www.wowhead.com/zone=6142) which is the Alliance city hub in Pandaria.\n(Or if you are Horde to Shrine of Two Moons (http://www.wowhead.com/zone=6141).)\n\nIt has portals to Stormwind (http://www.wowhead.com/zone=1519), Ironforge (http://www.wowhead.com/zone=1537), Darnassus (http://www.wowhead.com/zone=1657), Exodar (http://www.wowhead.com/zone=3557), Shattrath  (http://www.wowhead.com/zone=3703)and Dalaran (http://www.wowhead.com/zone=4395).\n\nIt has bankers (http://www.wowhead.com/npc=63969) and auctioneer (http://www.wowhead.com/npc=65599) (for engineers only) and access to void storage (http://www.wowhead.com/npc=64574), reforging (http://www.wowhead.com/npc=64045) and transmogrification (http://www.wowhead.com/npc=64573).\n\nAnd it has a flight trainer (http://www.wowhead.com/npc=60166) which on level 90 will teach you to fly in Pandaria (http://www.wowhead.com/spell=115913).\n\nEdit: Updated auctioneer info.",
            date = "2012-09-30T06:44:59-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31512#comments:id=1725681",
        },
        {
            id = 1874280,
            score = 16,
            author = "123042",
            text = "After you start the cutscene, the Celestials gather, Yu'lon speaks to the people.\n\nYu'lon says: Children of Pandaria. The mists have fallen. A new era dawns for us all. Accept the healing powers of this Vale... but use these gifts wisely.\n\nAfter the cutscene, if you are not leaving in a hurry, you can hear Celestials talking.\n\nYu'lon says: We risk everything, allowing so many into the Vale.\n\nChi-Ji says: I have faith in our friends from beyond the mists.\n\nXuen says: Their strength is an inspiration... and sorely needed. We must trust that their hearts are pure.\n\nNiuzao: ......",
            date = "2013-07-06T17:25:24-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31512#comments:id=1874280",
        },
        {
            id = 1897771,
            score = 16,
            author = "Lillycat",
            text = "What the Celestials say now differs from what Everdreamer has posted. It now goes as follows:\n\nYu'lon says: Children of Pandaria. The mists have fallen. For good or for ill, our land is open to all.\n\nYu'lon says: Let us draw ourselves together to rebuild this sacred place, the first step toward healing a war-torn world.\n\nNiuzao says: These outsiders have brought chaos to this land. Can we trust them to set it right?\n\nChi-Ji says: I have faith in our friends from beyond the mists.\n\nXuen says: Their strength is an inspiration... and sorely needed. We must trust that their hearts are pure.",
            date = "2013-09-14T10:07:56-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31512#comments:id=1897771",
        },
        {
            id = 1721030,
            score = 11,
            author = "tilgare",
            text = "I managed to talk to Anduin right after joining a guild raid on the world bosses.  This meant I did not get quest credit, while the cinematic DID start.  I didn't think it was a big deal until I got around to Golden Lotus and could not start their chain.  I ended up abandoning the quest, heading back to Temple of the White Tiger to pick it back up, and it was all good. I was able to take the quest and talk to Anduin at the gates no problem.\n\nSomeone on the Horde page does mention that once you abandon the quest the gates seal closed again which was true, so if you do not have a flying mount, it is a good idea to wait until you're back out side in Kun-Lai Summit.",
            date = "2012-09-27T01:19:05-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31512#comments:id=1721030",
        },
        {
            id = 1721515,
            score = 11,
