    [31513] = {
        {
            id = 1705505,
            score = 76,
            author = "338953",
            text = "First one is found behind the first boss, Thalnos the Soulrender.\nThe second is in the pool on the lower terrace of the monastery (if you get to the second boss, Brother Korloff, you've gone too far).",
            date = "2012-08-28T23:57:18-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31513#comments:id=1705505",
        },
        {
            id = 2526052,
            score = 54,
            author = "Numidia",
            text = "Once you pick the first blade behind the first boss the minimap shows that you need to turn the quest where you picked the first blade when in reality you turn it at the second blade's location at the big fountain after the first area.",
            date = "2017-09-25T18:07:46-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31513#comments:id=2526052",
        },
        {
            id = 1748624,
            score = 11,
            author = "Farelf",
            text = "I was able to not only to collect the two blades, but complete the quest after completing the instance and everyone else had left.\n\nYou have to use the icon next to the quest description to use the two blades on the body.",
            date = "2012-10-23T11:14:46-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31513#comments:id=1748624",
        },
        {
            id = 1877014,
            score = 10,
            author = "MightyWarlord",
            text = "Picked up first quest and completed entire instance w/o getting swords..\nWent back found the first sword, behind the first boss lying on his coffin.\nReturned to cathedral court yard fountain.\nThere I received the second sword and received the quest to stick the corpse.\nWent in cathedral, Lilan Voss was waiting by the corpse.\nTwin Sword icon in objectives list would not activate when targeted on corpse.\nI got error: \"Requires the corpse of High Inquistor Whitemane\"\n\nSo not able to complete quest if High Inquisitor is already dead and you go back and get swords.",
            date = "2013-07-15T02:01:15-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31513#comments:id=1877014",
        },
        {
            id = 2387391,
            score = 10,
            author = "380141",
            text = "If anyone else in your group is doing the quest and stabs Inquisitor Whitemane, but you're not on the final step of the quest, you will be unable to complete it. The item will return an error stating that you need her corpse, even though you're standing right in front of it. Don't forget to pick up the blades and get the quest moving forward BEFORE the final fight.\n\nShe can only be stabbed with the blades once per run, and it only counts as completed for those who are on the final stage of the chain. If you forgot to move the quest forward prior to her death, you will need to queue for the dungeon a second time in order to complete the quest.",
            date = "2016-09-05T08:09:39-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31513#comments:id=2387391",
        },
    },
    [31514] = {
        {
