        {
            id = 1701585,
            score = 5,
            author = "1020453",
            text = "The title of this quest is a reference to the bible, especially to the old testament:\n\nGenesis, 3:19\n\"By the sweat of your brow you will eat your food until you return to the ground, since from it you were taken; for dust you are and to dust you will return.\"\n\nIt's quite a matching title - you have to kill Whitemane once and forever because she refuses to stay dead so she doesn't \"return to dust\" like she is supposed to be.",
            date = "2012-08-19T03:58:29-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31514#comments:id=1701585",
        },
        {
