    [31529] = {
        {
            id = 1979857,
            score = 19,
            author = "808808",
            text = "The small caves are on Springtail Crag and the location is 45.47,22.36 where lots of the vermin are located. The springtail littlewhisker counts as kills and quests drops to turn in as rep points. the other cave is at 46.48, 21.11",
            date = "2014-07-12T01:50:38-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31529#comments:id=1979857",
        },
        {
            id = 1735188,
            score = 13,
            author = "Qoko",
            text = "Aren't 100% sure but I think Sho offers you this quest once you turn acquintances in order to boost up your reputation near or into Buddy. She has similar quests with more rep. It might be that all the Tiller NPCs have something extra to get rep: I know of Jogu's brew quests, Tina's quest items found in the field and this quest for Sho.",
            date = "2012-10-08T03:30:09-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31529#comments:id=1735188",
        },
        {
            id = 1743563,
            score = 6,
            author = "capnbiff",
            text = "There are two types of vermin here: the big Burrowers (standard 393K HP) and groups of three Littlewhiskers (only 39K HP each).  There should be three sets of the little guys, one on the ledge and two in the burrow, so make it easy on yourself and go after them.  Watch out for the Burrowers knockback when you are on the ledge, as it's a lonnnng way down.  Also, look out for Dark Soil - I found one on the ledge on my way in.",
            date = "2012-10-16T18:25:40-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31529#comments:id=1743563",
        },
        {
            id = 1747779,
            score = 4,
            author = "hogue",
            text = "Look for small caves.",
            date = "2012-10-22T07:09:40-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31529#comments:id=1747779",
        },
        {
            id = 1809394,
            score = 2,
            author = "CaptainCrowbar",
            text = "Note that only the vermin in the three cliff burrows count for this quest. The ones down on the farmland do not.",
            date = "2013-02-05T05:32:38-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31529#comments:id=1809394",
        },
    },
