        {
            id = 1749833,
            score = 2,
            author = "backfire",
            text = "Sits in a nest at the top of the cliffs (see the map). Respawn time can be a little longer than expected, but you get credit for killing it with someone else as usual.\n\nShould finish off your reputation with Sho once you get it (mid-good friend).",
            date = "2012-10-24T23:16:52-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31532#comments:id=1749833",
