    [31534] = {
        {
            id = 1733058,
            score = 69,
            author = "Avareal",
            text = "If you can't find the NPCs you need in Halfhill, you can find them at the below locations:\n\nHaohan Mudclaw - 45, 34\nGina Mudclaw - 53, 52 (right across from quest giver)\nFish Fellreed - 41, 30\nFarmer Fung - 48, 34\n\nAll you need to do is go to them than talk to them.  One of the options to select is the item you need to complete quest.",
            date = "2012-10-06T05:06:00-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31534#comments:id=1733058",
        },
        {
            id = 1889650,
            score = 38,
            author = "fday",
            text = "https://www.wowhead.com/npc=58647 asks you to do this:\n\nask https://www.wowhead.com/npc=57298 for https://www.wowhead.com/item=87553\nask https://www.wowhead.com/npc=57402 for https://www.wowhead.com/item=87554\nask https://www.wowhead.com/npc=58706 for https://www.wowhead.com/item=87555\nask https://www.wowhead.com/npc=58705 for https://www.wowhead.com/item=87556\n\n/way 48.29 33.87 ask Farmer Fung for Red Radish\n/way 44.65 34.07 ask Haohan Mudclaw for Sweet Lakemelon\n/way 53.16 51.80 ask Gina Mudclaw for Fuzzy Peach\n/way 41.73 30.03 ask Fish Fellreed for Black Cherries\n\nExcept for https://www.wowhead.com/npc=58706, the others (https://www.wowhead.com/npc=57298, https://www.wowhead.com/npc=57402, https://www.wowhead.com/npc=58705) may not be at Halfhill Market (see NPC pages).",
            date = "2013-08-24T06:27:52-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31534#comments:id=1889650",
        },
        {
            id = 1727017,
