    [31537] = {
        {
            id = 1733472,
            score = 75,
            author = "Aamunkajo",
            text = "A bit misleading: these characters have the talk bubble on them as if you were supposed to talk to them. There isn't a chat option, though. You need to target the character and then use the drink (in your inventory or from the objectives list).",
            date = "2012-10-06T13:53:36-05:00",
