        {
            id = 1735409,
            score = 21,
            author = "Avareal",
            text = "After picking up this quest from Ella, take the Ella's Brew (http://www.wowhead.com/item=87763) quest item you are given and head to Halfhill.  You will need to click on the each NPC than \"Use\" the quest item, which has a 30 second cooldown.\n\nYogu the Drunk - 53.5, 52.5\nBobo Ironpaw - 53.1, 52.1\nFarmer Yoon - 52.3, 48.8\nNana Mudclaw - 54.7, 47.0\n\nThen fly back out to Ella to turn in.",
            date = "2012-10-08T08:29:19-05:00",
