    [31598] = {
        {
            id = 1733829,
            score = 48,
            author = "Tosuro",
            text = "This is one of the three daily \"hidden\" quests for Klaxxi.\nIt's either https://www.wowhead.com/quest=31598, https://www.wowhead.com/quest=31677 or https://www.wowhead.com/quest=31599 each day.",
            date = "2012-10-06T21:21:05-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31598#comments:id=1733829",
        },
        {
            id = 1750888,
            score = 21,
            author = "88767",
            text = "Info on where to find all the bonus dailies for Klaxxi in Dread Wastes.\n\nThe Briny Muck / Zan'vess. If you happen to be questing in the area, swing by and kill Kypa'rak. He will drop Massive Kyparite Core, which starts https://www.wowhead.com/quest=31598.\n\nThe Clutches of Shek'zeer. When questing in this area, you will be able to spot Karanosh. Same idea here - kill her, loot Enormous Kunchong Mandibles, start https://www.wowhead.com/quest=31599.\n\nTerrace of Gurthan / Forgotten Mire. Finally, if you get this quest hub, go kill Warlord Gurthan for his Ashes of Warlord Gurthan, which start https://www.wowhead.com/quest=31677.",
            date = "2012-10-26T12:10:42-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31598#comments:id=1750888",
        },
        {
            id = 1733734,
            score = 20,
            author = "lightclaw",
            text = "This daily quest comes from Massive Kyparite Core (http://www.wowhead.com/item=87871), which drops off of Kypa'rak (http://www.wowhead.com/npc=65229), a collosal ringworm found in the western end of The Briny Muck in the Dread Wastes.  Though the quest is a daily, Kypa'rak only spawns on those days when the questing hub is the island of Zan'vess.\n\nKilling Kypa'rak is fairly easy.  The ringworm has 2.4M health, but does relatively low damage.  It has a burrowing phase, during which time you can continue dps.  Easily avoided spikes will pop up from the ground periodically while burrowed.",
            date = "2012-10-06T19:17:16-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31598#comments:id=1733734",
        },
    },
    [31599] = {
        {
            id = 1733849,
            score = 45,
            author = "Tosuro",
            text = "This is one of the three daily \"hidden\" quests for Klaxxi.\nIt's either https://www.wowhead.com/quest=31598, https://www.wowhead.com/quest=31677 or https://www.wowhead.com/quest=31599 each day.",
            date = "2012-10-06T21:48:12-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31599#comments:id=1733849",
        },
        {
            id = 1727428,
            score = 15,
            author = "Zillions",
            text = "This quest begins off of a drop https://www.wowhead.com/item=87878 which drops off of https://www.wowhead.com/npc=64724, in the Clutches of Shek'zeer (At approx 41, 32).\nLevel 90 Elite - has approx 2.5 mil HP.\n\nRewards 24 Gold 72 Silver, 5 Valor Points, and 143 Reputation with The Klaxxi (with guild perk).",
            date = "2012-10-01T12:32:06-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31599#comments:id=1727428",
        },
        {
            id = 1750886,
            score = 3,
            author = "88767",
            text = "Info on where to find all the bonus dailies for Klaxxi in Dread Wastes.\n\nThe Briny Muck / Zan'vess. If you happen to be questing in the area, swing by and kill Kypa'rak. He will drop Massive Kyparite Core, which starts https://www.wowhead.com/quest=31598.\n\nThe Clutches of Shek'zeer. When questing in this area, you will be able to spot Karanosh. Same idea here - kill her, loot Enormous Kunchong Mandibles, start https://www.wowhead.com/quest=31599.\n\nTerrace of Gurthan / Forgotten Mire. Finally, if you get this quest hub, go kill Warlord Gurthan for his Ashes of Warlord Gurthan, which start https://www.wowhead.com/quest=31677.",
            date = "2012-10-26T12:08:14-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31599#comments:id=1750886",
        },
        {
            id = 1763791,
            score = 1,
            author = "2p1k3",
            text = "Do we do something special to summon Karanosh like we do for Gurthan?",
            date = "2012-11-17T13:08:42-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31599#comments:id=1763791",
        },
    },
    [31603] = {
        {
            id = 1723664,
            score = 118,
            author = "949777",
            text = "This quest is not yet worth farming for. The drop rates are too low and enemies are too damaging in large numbers. Unless you're a beastly plate class you're better off waiting for the next day of dailies.\n[ins]edit: quest has changed from requiring 20 shards to 5 shards. Significantly easier to farm now and with the buffs it's definitely worth it to farm.[/ins]",
            date = "2012-09-28T22:27:40-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31603#comments:id=1723664",
        },
        {
            id = 1768859,
            score = 61,
            author = "Cide2316",
            text = "As of Patch 5.1, This quest requires only 5 https://www.wowhead.com/item=87903 to complete. It is now much more viable.",
            date = "2012-11-27T15:21:51-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31603#comments:id=1768859",
        },
        {
            id = 1760523,
            score = 28,
            author = "Grim32",
            text = "If you are interested in farming the Dread Amber Shards (http://www.wowhead.com/item=87903), first of all, you can't beat a low droprate / high stack count required. But if you are set on getting that little extra rep, my advice is to:\n\n1. Have an ilvl ideally of at least 460+\n\n2. Get the following augmentations / enhancements (Revered with Klaxxi req):\nBattle Hymn (http://www.wowhead.com/spell=123219) from Skeer the Bloodseeker (http://www.wowhead.com/npc=63071) (Augmentation) - After killing a mob that grants exp/honor, for 10 seconds, all successful damaging spells or abilities will restore 1% of maximum health.\n\nRaining Blood (http://www.wowhead.com/spell=127370) from Xaril the Poisoned Mind (http://www.wowhead.com/npc=62151) (Enhancement)  - Upon reaching 5 injections of Raining Blood, take 138750 to 161250 Nature damage. In addition, all non-player enemies nearby will be stunned for 5 secs. (Rather large DPS increase)\n\n3. Do not worry about the size of packs, as with the above buffs, you will be rather hard to kill as well as do sufficient damage to make quick work of them.\n\n4. I have found the best place to get large packs of mobs to be the dread march, My ideal location to go between is 58, 46 & 67,49 (http://i.imgur.com/moYYe.jpg) - this provides sufficient mobs, sufficient respawn time & a good amount of shards.\n\n4a. If the dread march is taken, another prime location is Zan Vess (http://www.wowpedia.org/images/7/75/WorldMap-Tyrivess.jpg) (Used a old scenario map to illustrate Zan'Vess - It is on the lower left of the map) This again, has many packs/closely packed mobs which can simply be killed using the above buffs.\n\n5. Again, the drop rate may not be very high, and you do require a lot five shards for a single turn in, but this should help speed the rate up at which you get the  Dread Amber Shards (http://www.wowhead.com/item=87903) if you are intent on farming them.\n\nEdit: Updated to mention change to 5 shards",
            date = "2012-11-10T20:38:35-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31603#comments:id=1760523",
        },
        {
            id = 1722276,
            score = 27,
            author = "Vermitus",
            text = "By the looks of it, this quest is repeatable multiple times in one day.",
            date = "2012-09-27T23:24:41-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31603#comments:id=1722276",
        },
        {
            id = 1750058,
            score = 9,
            author = "Qoko",
            text = "Even though this quest gives more rep than the dailies, you would be wasting your time trying to repeat this to grind Klaxxi to Exalted. This quest at best would save you doing two dailies each time you get it done, saving a day or two in total. Upon reaching Exalted you can delete your remaining shards.",
            date = "2012-10-25T07:19:33-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31603#comments:id=1750058",
        },
    },
