    [31669] = {
        {
            id = 1722297,
            score = 10,
            author = "ghcoltsfan",
            text = "This quest can be very confusing, at least for me it was. This daily requires to plant in YOUR farm, not anywhere else.\n\n1. You must have an open spot to plant https://www.wowhead.com/item=79102\n2. Buy https://www.wowhead.com/item=79102 from https://www.wowhead.com/npc=58718 located in the halfhill market area\n3. Return to your farm and plant https://www.wowhead.com/item=79102\n4 Turn in the quest to https://www.wowhead.com/npc=58721\n\nNote: if you do not need https://www.wowhead.com/item=74840 you can use the dented shovel near the steps to the house to remove it and replant the cooking mat that you do need. Make sure to tend to your plants so they grow! if unsure how to treat the plant speak with https://www.wowhead.com/npc=58721 he'll know what to do!",
            date = "2012-09-27T23:46:56-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31669#comments:id=1722297",
        },
        {
            id = 1852038,
            score = 2,
            author = "Karsciyin",
            text = "Quest seems to be broken. I accepted it, planted TWO cabbage seeds I already had in my inventory, didn't work.\nSo I dug one of them up, this time BOUGHT seeds, planted THAT... still didn't work.\n\nWell screw you too Yoon, I didn't even what this thing.",
            date = "2013-05-11T04:48:36-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31669#comments:id=1852038",
        },
        {
            id = 1781800,
            score = 1,
            author = "827152",
            text = "Quest name probably a reference to the onion test, which is a test for a hypothesis in genetics.",
            date = "2012-12-15T11:53:23-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31669#comments:id=1781800",
        },
        {
            id = 1781912,
            score = 1,
            author = "AnrDaemon",
            text = "You may dig out the sprout to free the plot, once you've got a credit for the quest and turned it in.\nI.e., if you're maximizing your crops by listening to the drunk fish (http://www.wowhead.com/achievement=7295).\nThe quest does not require you to grow it.",
            date = "2012-12-15T15:28:26-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31669#comments:id=1781912",
