    [31673] = {
        {
            id = 1733263,
            score = 48,
            author = "MarsJenkar",
            text = "Ohhhhhhh, I'm gonna take seeds home tonight\nOhhhhhhh, plant them 'side my crops all right\nOhhhhhhh, they're gon' keep those gators out\nRed blossom leeks, you make the croc-in' world go down!",
            date = "2012-10-06T10:19:20-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31673#comments:id=1733263",
        },
        {
            id = 1680093,
            score = 26,
            author = "Samaramon1",
            text = "http://www.youtube.com/watch?v=VMnjF1O4eH0\n\nhad to be done.",
            date = "2012-06-23T08:25:06-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31673#comments:id=1680093",
        },
        {
            id = 1726975,
            score = 14,
            author = "Kenfuru",
            text = "I had to do a double take when I read this quest title. Still to this day in my top ten favorite songs of all times.",
            date = "2012-10-01T05:11:07-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31673#comments:id=1726975",
        },
        {
            id = 1930835,
            score = 12,
            author = "MusedMoose",
            text = "With apologies to Queen:\n\nOh, you gonna plant some seeds tonight!\nOh, risin' with that morning light!\nOh, you plow those virmen off your plot!\nRed blossom leeks, you make the croc-in' world go down!\n\nI came to Pandaria,\nland of pandas, yaks, and sha,\nwent to Halfhill where those farmers said to me...\nThat there's danger comin' soon,\nspoke the one called Farmer Yoon,\n\"There's crocs comin'!  You gotta plant red blossom leeks!\"\n\nI've been questing cross this land,\nsaving good guys from the bad,\ngrabbing loot and downing booze along the way...\nPriests and mages, rogues and 'locks,\ncan't save Halfhill from the crocs,\ngrab yourself some bright red seeds, works every time!\n\nOh, won't you plant some seeds tonight!\nOh, and the drunk fish knows what's right!\nOh, pull those weeds with all you've got!\nRed blossom leeks, you make the croc-in' world go down!\nRed blossom leeks, you make the croc-in' world go down!\n\nI've got mushan, I've got seeds,\nmelons like you can't believe,\nhuge crops risin' far as any eye can see...\nAnd those reptiles ain't scary,\nand my farm is legendary,\nno crocs comin', 'cause I planted red blossom leeks!\n\nOh, you gonna plant some seeds tonight!\nOh, risin' with that morning light!\nOh, you plow those virmen off your plot!\nRed blossom leeks, you make the croc-in' world go down!\nRed blossom leeks, you make the croc-in' world go down!\n\nGet on your yaks and ride!",
            date = "2014-01-01T16:12:41-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31673#comments:id=1930835",
        },
        {
            id = 1734487,
            score = 7,
            author = "Atratzu",
            text = "Dang it, everyone already took all the clever comments.\nI got this quest for the first time today; now i'll have Fat Bottomed Girls by Queen stuck in my head for the rest of the day.",
            date = "2012-10-07T12:14:54-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31673#comments:id=1734487",
