    [31677] = {
        {
            id = 1733834,
            score = 56,
            author = "Tosuro",
            text = "This is one of the three daily \"hidden\" quests for Klaxxi.\nIt's either https://www.wowhead.com/quest=31598, https://www.wowhead.com/quest=31677 or https://www.wowhead.com/quest=31599 each day.",
            date = "2012-10-06T21:24:40-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31677#comments:id=1733834",
        },
        {
            id = 1723795,
            score = 40,
            author = "Daetur",
            text = "This quest is from an item dropped from a \"secret\" mob in the Dread Wastes.\n\nIn the Terrace of Gurthan, there is a location with an altar, a large, broken Mogu statue, and a red and a green rune.\n\nThe tablet at the altar reads\n\n\"Warlord Gurthan, master of beasts and conquerer of men, waits here.\n\nHe waits for the Earth to Lay before him as beasts once did.\n\nHe waits for the Sun to Kneel before him as men once did.\"\n\nIf you have two people, one of whom will /lay on the Green \"earth\" rune, and the other /kneels on the Red \"sun\" rune, a level 90 elite will spawn. Killing him will cause him to drop the quest starter, provided you have the ability to do dailies for the Klaxxi.\n\nHe summons adds during the fight and is of low-to-moderate difficulty at level 89.",
            date = "2012-09-29T00:13:48-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31677#comments:id=1723795",
        },
        {
            id = 1725392,
            score = 33,
            author = "Calicia",
            text = "This quest only appears to be available when the dailies are all at the Terrace of Gurthan.",
            date = "2012-09-30T01:19:52-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31677#comments:id=1725392",
        },
        {
            id = 1750895,
            score = 19,
            author = "88767",
            text = "Info on where to find all the bonus dailies for Klaxxi in Dread Wastes.\n\nThe Briny Muck / Zan'vess. If you happen to be questing in the area, swing by and kill Kypa'rak. He will drop Massive Kyparite Core, which starts https://www.wowhead.com/quest=31598.\n\nThe Clutches of Shek'zeer. When questing in this area, you will be able to spot Karanosh. Same idea here - kill her, loot Enormous Kunchong Mandibles, start https://www.wowhead.com/quest=31599.\n\nTerrace of Gurthan / Forgotten Mire. Finally, if you get this quest hub, go kill Warlord Gurthan for his Ashes of Warlord Gurthan, which start https://www.wowhead.com/quest=31677.",
            date = "2012-10-26T12:18:01-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31677#comments:id=1750895",
        },
        {
            id = 1768420,
            score = 16,
            author = "Rosebud",
            text = "Today, I wanted to do this quest; however, I had no Horde buddies online to help.  Even though it is a bit unorthodox, I called upon an Alliance friend to assist me.  I /lay on the green, and he /kneel on the red.  It worked.  We were going to take turns tagging it and getting the quest item; however, to much delight, the quest item dropped for both of us on the first kill.\n\nBe sure to get in on the fight if someone is fighting him, or in my case, call upon a friend to help summon him, even if a different faction.",
            date = "2012-11-26T22:21:40-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31677#comments:id=1768420",
        },
    },
    [31679] = {
        {
            id = 3248174,
            score = 56,
            author = "1717213",
            text = "So if you're a weirdo completionist like me you're probably wondering how to get this quest because you've done the other one from Kor'ik a million times.\n\nThe trick to getting this version of the quest is basically to do the following:\n\n-Do the entry quests to the zone as usual until you're brought to Klaxivess\n-Do not accept ! Extending Our Coverage (https://www.wowhead.com/quest=31087/extending-our-coverage) at any point (obviously)\n-Continue to basically do any Paragon related quest in the zone including the quest chains at the dock, the quests at the Lake of Stars, etc. From time to time Kor'ik will have other quests on offer than Extending Our Coverage so make sure to do those as well.\n-Eventually this will lead to ! Dropping Our Signal (https://www.wowhead.com/quest=31439/dropping-our-signal) once you reach revered with The Klaxxi\n-Once you complete that quest and its follow up ! Corruption Runs Deep (https://www.wowhead.com/quest=31441/corruption-runs-deep) the version of ! Extending Our Coverage (https://www.wowhead.com/quest=31679/extending-our-coverage) you came for will be available from Zer'ik who will have taken Kor'ik's place in Klaxxivess.",
            date = "2020-11-11T21:32:32-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31679#comments:id=3248174",
        },
        {
            id = 1722086,
            score = 27,
            author = "reilyn",
            text = "Entrance is at 46.3, 53.1.\n\nYou need to jump down from the highest level of the area to get to the entrance. If you're at sea level and you end up by the flight path (42.5, 55.7), look towards the mountains and you'll see the entrance. It's northwest of the flight path.",
            date = "2012-09-27T20:06:35-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31679#comments:id=1722086",
        },
        {
            id = 1767888,
            score = 6,
            author = "lovelywarrior",
            text = "Entrance to Amberglow Hollow is located west of cog that appears on mini map.",
            date = "2012-11-25T19:10:27-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31679#comments:id=1767888",
        },
        {
            id = 1791187,
