            text = "http://www.youtube.com/watch?v=Rzkc3R1gWCs\nHelp video to this q.st",
            date = "2013-01-02T11:32:06-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31679#comments:id=1791187",
        },
        {
