            text = "I got https://www.wowhead.com/quest=31087, not sure what this version is.",
            date = "2013-01-14T20:04:44-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31679#comments:id=1798690",
        },
    },
    [31680] = {
