        },
        {
            id = 5403878,
            score = 37,
            author = "deiXide",
            text = "Seems like there is a race condition that causes this quest to bug and forever show the quest marker (!) even though it's been completed.  Hopefully someday they'll fix it.  Here is one of several bug reports (https://us.forums.blizzard.com/en/wow/t/crime-and-punishment-breadcrumb-showing-erroneously-2-years/1286681).",
            date = "2022-07-23T15:54:26-05:00",
