    [31681] = {
        {
            id = 1729188,
            score = 134,
            author = "jaykaywhy",
            text = "The turn-in NPC for this quest, and the accompanying quest Crime and Punishment, is found underground. The entrance is at 46, 53.",
            date = "2012-10-02T21:10:47-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31681#comments:id=1729188",
        },
        {
            id = 5858425,
            score = 65,
            author = "Aureldrin",
            text = "If you during Mist of Pandaria Remix run down to turn it in and you cannot? Simply just abandon the quests and restart it it goes for both\n\nCrime and Punishment & Better with Age!\nTo save you alot of research and what else! :)",
            date = "2024-05-18T07:58:54-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31681#comments:id=5858425",
        },
        {
            id = 1720477,
            score = 16,
            author = "trollied",
            text = "The jars are lootable - located on trees and cliff-sides.",
            date = "2012-09-26T16:15:14-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31681#comments:id=1720477",
        },
        {
            id = 1865303,
            score = 7,
            author = "Strokelock",
            text = "A Very easy way to locate these is to either make a macro that says:\n\n/tar Ringtail\n\nOr just copy that and paste into chat window. Every time it finds one, right click on the Ringtail Bandit's frame, select the Orange Circle Icon and Mark it. Then just fly up a bit until you see the Orange Circle and voila, the amber will be on the tree where he is!\nAlso, Zandalari Warscout  (http://www.wowhead.com/npc=69768) roams here on occasion so if you add this (if you decide on a macro) you may get lucky!\n\n/tar Ringtail\n/tar Zandalari Warscout\n\nHappy Hunting!",
            date = "2013-06-11T13:48:37-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31681#comments:id=1865303",
        },
        {
            id = 1723533,
            score = 1,
            author = "1037571",
            text = "These are object on trees, check them in marked places. you also can see Ik'thik Harvester's channeling them.",
            date = "2012-09-28T20:02:08-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31681#comments:id=1723533",
        },
    },
    [31682] = {
        {
            id = 1968320,
            score = 7,
            author = "Rixanne",
            text = "Zerik, who starts the quest line, is in a cave, which means you have to find the opening to the cave.  If you use his coordinates, you just stand on top of nothing.\n\nBegin phase-in quest chain CAVE ENTRANCE 46.0, 53.7 in Dread Wastes (see screen shot if you need a map).\n\nGo inside, he gives you two quests to complete.  Complete those quests, you get the tuning fork quest. Voila.\n\nAll the other comments did nothing to get me where I needed to go.",
            date = "2014-05-28T15:13:28-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31682#comments:id=1968320",
        },
        {
            id = 6023829,
            score = 5,
            author = "NeonShard",
            text = "So, for other fellow completionists... I was trying to get this quest variant yesterday with no luck. From what I gathered, there are 2 variants of several quests.\n\nFirst you want to start regular zone quest chain, starting with Falling Down (https://www.wowhead.com/quest=31001/falling-down).\nYou continue Dread Wastes quest chain (https://www.wowhead.com/storyline/dread-wastes-562) until you stumble upon Extending Our Coverage (https://www.wowhead.com/quest=31087/extending-our-coverage) offered by Kor'ik (https://www.wowhead.com/npc=64815/korik). At this point, you would normally follow quest chain with Kor'ik as your questgiver. This is version what 99% of players does:\n\nExtending Our Coverage (https://www.wowhead.com/quest=31087/extending-our-coverage) (variant A)\nCrime and Punishment (https://www.wowhead.com/quest=31088/crime-and-punishment) (variant A)\nBetter With Age (https://www.wowhead.com/quest=31090/better-with-age) (variant A)\nBy the Sea, Nevermore (https://www.wowhead.com/quest=31089/by-the-sea-nevermore) (variant A)\n\nIf you want to unlock alternative quest chain (quest objectives are the same, but quest ID differs) then DO NOT ACCEPT Extending Our Coverage (https://www.wowhead.com/quest=31087/extending-our-coverage) from Kor'ik (https://www.wowhead.com/npc=64815/korik). Instead, you have to finish Dropping Our Signal (https://www.wowhead.com/quest=31439/dropping-our-signal) and follow-up Corruption Runs Deep (https://www.wowhead.com/quest=31441/corruption-runs-deep). In this quest Kor'ik, your quest giver turns traitor and is killed. After completing this quest, there is different quest chain offered by new quest giver Zer'ik (https://www.wowhead.com/npc=65541/zerik).\n\nExtending Our Coverage (https://www.wowhead.com/quest=31679/extending-our-coverage) (variant B)\nCrime and Punishment (https://www.wowhead.com/quest=31680/crime-and-punishment) (variant B)\nBetter With Age (https://www.wowhead.com/quest=31681/better-with-age) (variant B)\nBy the Sea, Nevermore (https://www.wowhead.com/quest=31682/by-the-sea-nevermore) (variant B) -YOU ARE HERE-\n\nHowever for some reason, even that I did first 3 quests on variant B, my last quest offered was By the Sea, nevermore (https://www.wowhead.com/quest=31089/by-the-sea-nevermore) (variant A). Not sure if I misunderstood principles I described above, or quest is bugged and By the Sea, Nevermore (https://www.wowhead.com/quest=31682/by-the-sea-nevermore) (variant B) is currently impossible to complete. If you found the way to pop this quest, please share your experiences below! Hope this helps someone at least for first 3 quests.",
            date = "2024-12-08T14:04:19-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31682#comments:id=6023829",
        },
        {
            id = 1776969,
            score = 3,
            author = "Calentor",
            text = "I found that the icon for the Klaxxi Tuning Fork that was shown in my objectives list did nothing, but when I clicked on the icon in my bag it worked just fine.",
            date = "2012-12-07T00:57:49-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31682#comments:id=1776969",
        },
