            text = "This quest has a history of bugging. If you can't see the rocks, abandon the quest and try again.\n\nHere's a screenshot of the rocks' location:\n\nhttp://i.imgur.com/oCY54.jpg\n (http://i.imgur.com/oCY54.jpg)",
            date = "2012-07-07T05:48:12-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31682#comments:id=1685458",
        },
