    [31689] = {
        {
            id = 1810773,
            score = 12,
            author = "LoyMyrna",
            text = "I'm exalted with the Klaxxi, completed this quest, and am unable to do the turn-in since Malik is now dead. Oddly, I picked the up the quest from Halberd of the Unscathed (on the weapon rack) located behind Quartermaster Ambersmith Zikk, but can't do the turn in with Halberd. Unless there's a work around, better finish this quest line before you hit exalted.",
            date = "2013-02-08T12:44:24-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31689#comments:id=1810773",
        },
        {
            id = 1758721,
            score = 6,
            author = "1014684",
            text = "You need to stear clear of the Giant Fear things (shadow-like) that are wandering around this area.  Also, it helps to back-off when the dreadsworm starts twirling his sword. I died several times trying to complete this quest and drank potions like a conehead consuming six packs!",
            date = "2012-11-07T12:18:55-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31689#comments:id=1758721",
        },
        {
            id = 1763771,
            score = 3,
            author = "lionsofmercy",
            text = "Although they patrol the whole area, there are too many really nasty things to stay in Kypari Vor itself to take them out at the same time you gather eggs, etc.\n\nHere's the patient way: Instead, prowl the edge of the area in the Horrid March. 56,13 is a good place to start. (Take out the Frightened Mushan while you're camping so it doesn't get annoying.) The Dreadsworn patrol the perimeter; avoid the packs of Nagging Dreadlings and kite your guy out of Kypari Vor.\n\nThey're not the brightest bugs in the slums--while they're blade-flurrying, just step out of the way and he'll keep flailing away at the same spot, giving you a couple of seconds to whip off a distance spell. Easy peasy; a nice break from the rest of the area.",
            date = "2012-11-17T12:19:54-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31689#comments:id=1763771",
        },
        {
            id = 1728762,
            score = 1,
            author = "Eclipsegirl",
            text = "The Dreadsworn are not the little flying vermin that protect the eggs.\n\nThe are big walking mantids with swords or blades.",
            date = "2012-10-02T12:56:45-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31689#comments:id=1728762",
        },
    },
    [31695] = {
        {
            id = 1713663,
            score = 57,
            author = "673695",
            text = "This quest is mutually exclusive with My Husband... (http://mop.wowhead.com/quest=30768). If you have accepted or have completed one you will not be able to pick up the other.",
            date = "2012-09-14T16:03:02-05:00",
