    [31701] = {
        {
            id = 1762018,
            score = 10,
            author = "896670",
            text = "Does anybody else feel sad killing this mommy in front of her babies? :'(",
            date = "2012-11-13T18:56:57-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31701#comments:id=1762018",
        },
        {
            id = 1725584,
            score = 8,
            author = "Talaria",
            text = "This bad bro (http://www.wowhead.com/npc=63538) is found in a cave in the high peaked mountain, the entrance is at 64,25.",
            date = "2012-09-30T05:11:40-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31701#comments:id=1725584",
        },
        {
            id = 1782978,
            score = 7,
            author = "892035",
            text = "The way to do this as a SP:\n\n- Go for the mommy.\n- Put power shield on you\n- Put VT and SWP on the mommy\n- MB on the mommy\n- Then the cubs will come, let them come and stay on the mommy and keep your shield up\n- When the cubs are around you, put psyfiend out, stay on the mommy the whole time\n- The cubs will run away in fear for 30 sec, the mommy will run too but you do damage on her so she will return\n- Then you can kill her off, before the cubs return\n- After when the cubs return, you'll have to finish them off but that is easy then\n\nI used Desperate Prayer once, no flash heal or renew necassary.",
            date = "2012-12-17T09:10:15-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31701#comments:id=1782978",
        },
        {
            id = 1807695,
            score = 7,
            author = "1087795",
            text = "Since no one else has posted suggestions for balance druids, I'll share my experience here. I died 5 times on it this morning before getting it right.\n\n1) Stand in the mouth of the cave in a spot where you will not aggro the cubs if they repop during the fight with the mama, and where you won't be jumped on by tigers from behind.\n\n2) Hibernate the huntress.\n\n3) Dot the first cub.  You call kill it before the others attack but they will all come. Dot and aoe them down. Rejuv to keep health topped off.\n\n4) Re-hibernate huntress if necessary. You will want full health for this, so get all healed up.\n\n5) Burn the huntress down as quickly as you can. Keep dots rolling. Keep your health up as you can during the fight also.\n\n6) She will enrage. Use soothe to dispel it. Otherwise you will quickly become cat food as she hits for big numbers when in this state. This is why you want to keep health up during the fight. If she enrages while you have low health you might not get her soothed before you're dead.\n\nGood luck! - E.",
            date = "2013-02-01T12:14:44-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31701#comments:id=1807695",
        },
        {
            id = 1765731,
            score = 5,
            author = "Kholin",
            text = "I was finally able to solo her as a Discipline Priest after dying miserably about 7 times.\n\nFrom my experience, attacking any of her babies will aggro her as well. The only way I was able to actually kill her was to kill all of her babies right off the start. To do this, I threw Shadow Word: Pain on all of them and used Divine Star when it was availible while keeping Power Word: Shield up on me. I also summoned my Mindbender to help kill them faster until only the Dark Huntress was left.\n\nOnce it was down to just her, I made sure to keep Shadow Word: Pain up on her at all times and Power Word: Shield on myself. Keeping Renew and Prayer of Mending on myself also helped keep my health up, so I only had to use Desperate Prayer and my other heals near the end. The fight was long enough that I was able to summon my Mindbender again, which helped me kill her before her babies respawned. They come back fairly quickly and every time I died was due to her babies respawning too quickly for me to heal myself up and kill them again.\n\nThat was my experience with her, so good luck if anyone is still having trouble killing her alone! :)",
            date = "2012-11-21T10:03:50-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31701#comments:id=1765731",
        },
    },
    [31702] = {
        {
            id = 1770763,
            score = 11,
            author = "168688",
            text = "Ok, Seriously? This is the only \"boss\" mob I have trouble with during the Cloud Serpent dailys. So I come here and there is NOTHING said about how to fight him? Does no one else have any issues with him? Does no one else get repeatedly stunned by his pounce? The best I've gotten him down is to 40% (with my Rogue). Any help would be appreciated.",
            date = "2012-11-28T23:35:31-06:00",
