    [31703] = {
        {
            id = 1694036,
            score = 12,
            author = "yoshimo",
            text = "Shadowfae Madcapt is in a cave. Cave entry is at 62.70/26.69 on Windward Isle",
            date = "2012-07-30T11:32:12-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31703#comments:id=1694036",
        },
        {
            id = 1787635,
            score = 7,
            author = "1066134",
            text = "This mob gives you a debuff that slows your attack speed and casting speed by 6%. This debuff stacks. This also makes your character physically smaller. The debuff can be removed via cleanse/ dispell.\n\nThis mob has 787K health.\n\nHe also turns you into a sprite identical to him the moment you attack.",
            date = "2012-12-26T10:31:17-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31703#comments:id=1787635",
        },
