            author = "raymix",
            text = "You will have 2 items Golden Honey and Honeycomb. Don't get confused, use first one mentioned under the big hive",
            date = "2012-10-29T03:18:43-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31705#comments:id=1752978",
        },
        {
            id = 1801847,
            score = 7,
            author = "Tenolin",
            text = "You have to hit him with magic. You can't melee him because he stays up too high to hit. I did manage to kill him with my paladin, but it would be hard for a rogue or a warrior to kill.",
            date = "2013-01-21T04:49:28-06:00",
