        },
        {
            id = 1846354,
            score = 7,
            author = "1116215",
            text = "It doesn't work to set the bait, then fly up to the nearby ledge.  The wasp remains out of reach.\n\nI'm getting the impression this is not a quest for a melee toon.",
            date = "2013-04-23T19:41:41-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31705#comments:id=1846354",
