    [31707] = {
        {
            id = 1730547,
            score = 22,
            author = "232139",
            text = "As a warlock, I was getting a huge number of empty webs until I put my Void Lord on passive and took away all my /petattack macros. It seems like any pet damage on these causes it to be impossible to break anything out of the webs, even hostile mobs. Wild Imps didn't cause a problem, though.",
            date = "2012-10-03T23:37:23-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31707#comments:id=1730547",
        },
        {
            id = 1746148,
            score = 9,
            author = "Knitshade",
            text = "Here was a nasty surprise: You can't fly in The Widow's Wail.  This can be fatal if you discover it while coming at the cliffs from a large height!\n\nSo come in along the waterline from  The Mistveil Sea (the cave is at sea level) rather than taking umpty-bazillion points in falling damage because you've decided to explore along the cliffs from The Jade Forest.\n\n(Unfortunately, you probably won't be reading this until you've already died and come here with a WTF? look on your face -- same as me. At least you'll know you're not alone, though.)",
            date = "2012-10-20T03:01:00-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31707#comments:id=1746148",
        },
        {
            id = 1741086,
            score = 3,
            author = "785935",
            text = "The entrance to the cave is at 58.19 31.83. It's the cave with boats on the water and webbed people out front (as opposed to the cave with the Hozen in the front).",
            date = "2012-10-14T04:07:28-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31707#comments:id=1741086",
        },
