    [31710] = {
        {
            id = 1748674,
            score = 9,
            author = "Knitshade",
            text = "Here was a nasty surprise: You can't fly in The Widow's Wail -- the very small area between the Jade Forest cliffs and the Mistveil sea where the cave mouth is found. This can be fatal if you discover it from a large height!\n\nYour best option is to come in along the waterline from The Mistveil Sea (the cave is at sea level) rather than from the Jade Forest, because it's a long way down from those cliff-tops. Expecting to come over the top and circle down will lead to a nasty shock and umpty-many points in falling damage!\n\n(Unfortunately, you probably won't be reading this until you've already died and come here with a WTF? look on your face -- same as me. At least you'll know you're not alone, though.)",
            date = "2012-10-23T12:18:37-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31710#comments:id=1748674",
        },
        {
            id = 1747503,
            score = 8,
            author = "1048357",
            text = "I hit exalted before turning this quest into my hatchling.  And obtained my mount after completing  Riding the Skies  (http://www.wowhead.com/quest=30188).  The hatchling wasn't there after the cut scene.\n\nEither turn in all quests to your hatchling first or simply log out and back in to refresh the phasing in the area.",
            date = "2012-10-21T22:37:29-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31710#comments:id=1747503",
        },
