    [31712] = {
        {
            id = 1740051,
            score = 8,
            author = "Cantralian",
            text = "The Oona Hozen are in a cave, the entrance to which is at 58.06, 27.73.",
            date = "2012-10-13T01:26:58-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31712#comments:id=1740051",
        },
        {
            id = 1749620,
            score = 7,
            author = "SoloEverything",
            text = "Monkeys are the new Murlocs.  Nuff said.",
            date = "2012-10-24T15:59:42-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31712#comments:id=1749620",
        },
        {
            id = 1802005,
            score = 5,
            author = "ziggy29",
            text = "You'll probably kill 13 of them in the first few yards you go in that cave.  These hozen have an unreal respawning rate and you'll probably kill 50 of them (unless you can stealth) before you can get to the boss for another quest in this cave.  And when you kill that boss, you'll continue to kill them faster than you can get out because the respawn rate is so ridiculous -- at least unless you have 3-4 other people questing it at the same time.\n\nUntil they fix the respawning rate of the mobs in this cave, this quest chain is pure frustration and pain.",
            date = "2013-01-21T12:48:25-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31712#comments:id=1802005",
        },
        {
            id = 1907946,
            score = 5,
            author = "381467",
            text = "Kill 13 monkeys, is this a film ref to 12 Monkeys?",
            date = "2013-10-12T12:40:20-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31712#comments:id=1907946",
        },
        {
