    [31733] = {
        {
            id = 1718409,
            score = 24,
            author = "216674",
            text = "IF you somehow managed to miss the parachutes and plummeted to your death (thus killing not only yourself but the ability to complete this quest for the moment) - don't  fret/freak.\n\nReturn to SW and take the panda-portal to Paw'Don, once in that town an NPC should tell you to take the other portal (practically in front of you) back to the skyship.  (Thanks to Clarke from Arygos for pointing this out.)",
            date = "2012-09-25T07:07:00-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31733#comments:id=1718409",
        },
        {
            id = 1768888,
            score = 11,
            author = "dosiana",
            text = "As of patch 5.1, the parachutes no longer spawn in as they should at the edges of the ship. Currently waiting on a ticket response to finish the quest on my monk alt.\n\nEDIT: on 11/28, they restarted my server in the afternoon and I managed to get on right after it came up, and guess what, there were a couple parachutes on the side of the airship! Might have been a hotfix, or might have been the restart, who knows.",
            date = "2012-11-27T15:40:13-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31733#comments:id=1768888",
        },
        {
