    [31735] = {
        {
            id = 1718809,
            score = 24,
            author = "runaround",
            text = "There is a new flaregun in your bag.  You can't use the same flaregun as the previous quest.",
            date = "2012-09-25T14:04:37-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31735#comments:id=1718809",
        },
        {
            id = 1960230,
            score = 8,
            author = "Rumbuddy",
            text = "No one seems to mention the little cinematic between Rell and Taran Zhu at quest completion.\n\nSky Admiral Rogers: Nightwind, report!  What's going on down there?\nRell Nightwind: No sign of the flagship, and no sign of Admiral Taylor or Prince Anduin.\nSky Admiral Rogers: Horde troops are swimming towards your position.  Open fire at once.\nRell Nightwind: Admiral - I think they mean to surrender.  They're not armed - They're just trying not to drown!\n\n[shot of unmassed, single orcs swimming towards the dock.]\n\nSky Admiral Rogers: You don't think they'll hestitate to strangle you with their bare hands?  GUN THEM DOWN!\n\n[Orcs are fired upon in the water, killing all of them.]\n\nRell Nightwind: That's not right...this is a massacre...they were unarmed - ugh!  I don't feel well...\n\n[Rell completely transforms into a Sha.]\n\nRell Nightwind: Maybe they deserved to die.\n\n[Taran Zhu runs onto the scene, exorcises Rell.]\n\nTaran Zhu: You beasts!  What sort of madness is this?\nRell Nightwind: Men, stand down - this is one of the natives.\nRell Nightwind: We are from the Alliance, and mean you no harm.  Tell me, what was the shadow you drew out of me?\nTaran Zhu: This is not the place to explain.  In short, your own doubts have been made manifest, as a consequence of your actions.\nRell Nightwind: You don't understand - we're fighting a war here-\nTaran Zhu: Oh, I understand perfectly.  I have eyes.  But Pandaria is not like whatever land you came from; it lives and breathes.  You should be careful what kind of energy you bring here.  Now put those weapons away!",
            date = "2014-04-21T21:31:31-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31735#comments:id=1960230",
        },
        {
            id = 1718675,
            score = 6,
            author = "747408",
            text = "Make sure you turn in this quest right at the end of the dock where you complete it.  If you don't the barricades reappear and you no longer have the quest item to blow them up with.  So far, I've found now way to get back down the dock and turn in the quest.\n\nEven if another player comes along and they blow up the barricade, for me it remains.\n\nSolution: I was able to climb up onto the dock from the very eastern end of it, on the right hand cornder. There is a metal ring around the verticle dock support.  I was able to jump up on that, and then from there, jump the rest of the way onto the dock and deliver the quest. =D",
            date = "2012-09-25T11:56:18-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31735#comments:id=1718675",
        },
        {
            id = 1718848,
            score = 5,
            author = "zedub12",
            text = "If you fell off the dock. Swim under the quest ender, either drown or use \"I'm stuck\" and \"Go to Graveyard.\" Then you should be able to leap around the corner of the barricades in ghost form and resurrect yourself next to quest end guy on top of the dock.",
            date = "2012-09-25T14:48:53-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31735#comments:id=1718848",
