    [31757] = {
        {
            id = 1741659,
            score = 6,
            author = "Peppercorn",
            text = "This quest sucks!\n\nIt is almost impossible to get this quest done. I am on a high pop realm (Area 52), but still. It shouldn't be this difficult. It appears the Unleashed Spirits (http://www.wowhead.com/npc=65935) needed for this quest only spawn on the Spirit Vortexes or next to piles of bodies, and no where near frequently enough. There's always someone camping each spot.\n\nI hope Blizzard removes this one from the rotation or fixes the spawn rate.",
            date = "2012-10-14T17:54:04-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31757#comments:id=1741659",
        },
        {
            id = 1749281,
            score = 4,
            author = "Trogthor",
            text = "Waiting at (46,27) [the road coming down out of the Golden Stair] produces a pretty constant stream of these packs. Just set up your AoE and go =)",
            date = "2012-10-24T06:50:21-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31757#comments:id=1749281",
        },
        {
            id = 1761709,
            score = 1,
            author = "frailgesture",
            text = "Prot paladins, and probably other classes, can use this quest to easily get Black Prince rep up. The Spirits are worth 2 and sometimes 3 rep with Wrathion, but you can kill them very rapidly if you sit on the main entrance to the quest area; you'll probably be able to pop down 50 or so a minute if you simply use Holy Wrath, Consecration, Hammer of the Righteous, and Seal of Righteousness over and over. They deal minimal damage to my moderately-geared Paladin, although I was constantly popping Sacred Shield and had a Colossus-enhanced weapon.\n\nIt might not be needed since you'll probably get your rep with the Black Prince up naturally just by doing dailies, but you find yourself a few hundred points short of the next rep tier with him, this is a good way to get it quickly without having to deal with any elites.",
            date = "2012-11-13T04:03:56-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31757#comments:id=1761709",
        },
        {
            id = 1683975,
            score = -6,
            author = "magnusfn",
            text = "In MoP, you will be able to get valor points by doing dailies. The 25 daily quest cap will be removed, and there will be hundreds of new dailies to do. Now you won't have to farm it by doing dungeons anymore, if you prefer doing dailies instead.",
            date = "2012-07-03T09:54:21-05:00",
