    [31778] = {
        {
            id = 1847607,
            score = 21,
            author = "Gadoink4",
            text = "It's interesting, regardless of which side you play as, it's always the other one that's painted as the clear 'bad guys', doing horrible things etc, while your own faction is generally portrayed sympathetically, helping people and doing what's right, and so on. You have to wonder how much of it is actually happening, and how much is just events being filtered by your own character's perceptions...",
