    [31784] = {
        {
            id = 1701594,
            score = 172,
            author = "Ospreyfalcon",
            text = "I have been compiling screenshots for the egg locations on my blog and will add more as I come across them.\n\nOnyx Egg Locations (http://sneakysams.blogspot.com/p/onyx-egg-locations.html)",
            date = "2012-08-19T04:13:40-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31784#comments:id=1701594",
        },
        {
            id = 1722499,
            score = 78,
            author = "Pinkiepieisfly",
            text = "To everyone: You can find eggs, there is no quest for them until you obtain an egg first. My boyfriend and I were searching for eggs for a while before we finally saw one.\nIf you don't see eggs, /who the area and all the level 90s there would (most likely) be why. In fact, I saw two people with cloud serpents already from farming so much!\n\nGood luck, the eggs don't sparkle and their spawn rate seems terrible. But they are big, black eggs so you can see them easily, and also note that sometimes they can be hidden in grass on mountains or whatnot, so mousing over grass/trees/etc. helps!",
            date = "2012-09-28T02:55:34-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31784#comments:id=1722499",
        },
        {
            id = 1693204,
            score = 59,
            author = "Salroh",
            text = "Yes, this quest is similar to collecting Netherwing Eggs for a reputation boost.\n\nLike the Netherwing Eggs that were scattered around Shadowmoon Valley, the Onyx Eggs are scattered around Windward Isle.\n\nBut unlike the Netherwing Eggs the reputation gain for the Onyx Eggs doesn't change after the first turn in.\n\nHopefully a feature that will not change.\n\nEdit: Also forgot to mention that the rep changes with whether you're in a guild or not. If you have a guild with the Mr. Popularity rank 1 perk that gives a 5% rep bonus your turn-in is now worth 525. For a guild with Mr. Popularity rank 2 perk that gives a 10% rep bonus, your turn-in is now worth 550.",
            date = "2012-07-28T12:00:20-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31784#comments:id=1693204",
        },
        {
            id = 1685199,
            score = 35,
            author = "1005822",
            text = "I believe this will be similar to the Netherwing quest where you must bring the egg to them.                                                            Edit: Why downrate speculation?",
            date = "2012-07-06T13:54:31-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31784#comments:id=1685199",
        },
        {
            id = 1720978,
            score = 22,
            author = "1036973",
            text = "The eggs spawn mostly on mountains on Windward Isle. You can do this quest all the way up to exalted with Order of the Cloud Serpent.\n\nNote: The eggs will disappear when you hit revered so collect what you need before you turn them in.\n\nSorry about that. They are back up and lootable :)",
            date = "2012-09-27T00:11:01-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31784#comments:id=1720978",
        },
    },
