    [31810] = {
        {
            id = 1758736,
            score = 67,
            author = "frankly",
            text = "If you are like me and rushed throuh daily's to get revered, then hunting  onyx eggs (http://http://www.wowhead.com/item=89155) to get exalted and end up wondering why this quest isn't popping up: You must have done Flight Training: Full Speed Ahead (http://www.wowhead.com/quest=30145) and Flight Training: In Due Course (http://www.wowhead.com/quest=30187) to make Elder Anli (http://www.wowhead.com/npc=58564) give you this quest.",
            date = "2012-11-07T12:56:48-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31810#comments:id=1758736",
        },
        {
            id = 2863789,
            score = 21,
            author = "Errontrial",
            text = "Not sure if it's just me, but the cinematic seems to be bugged for me to where my character doesn't show up in it, just some random female Blood Elf. :(",
            date = "2019-01-03T11:43:06-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31810#comments:id=2863789",
        },
        {
            id = 1786296,
            score = 11,
            author = "138867",
            text = "As an added bonus, you are able to sell your cloud serpent mount back to the vendor if you've already learned it on another toon  :)  750g ka-ching!",
            date = "2012-12-23T16:34:12-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31810#comments:id=1786296",
        },
        {
            id = 1821007,
            score = 7,
            author = "Sketchie",
            text = "Once you have reached Exalted with the Order of the Cloud Serpent, Elder Anli will have a quest for you: Riding the Skies.\n\nOnce you have accepted the quest, you are immediately thrown into a brief scene.\n\nPan down through the cherry blossom trees, revealing your character kneeled in front of Elder Anli and several others, with your cloud serpent you have raised from a hatchling yourself by your side. An obscure amount of cherry blossom leaves falls throughout the entire event.\n\nElder Anli says: Today, your journey towards the Order of the Cloud Serpent ends. Today, a new rider joins our ranks.\nInstructor Skythorn says: Through thunder and storm, we fly together.\nInstructor Windblade says: Through sea and sky, we fly together.\nJenova Longeye says: Through wind and tide, we fly together.\nElder Anli says: Today, you forge an eternal bond with your cloud serpent.\nElder Anli says: Fly together with honor and courage. Now... rise as a serpent rider!\n\nYour character stands up and bows while everyone cheers and fires off fireworks.\n\nSuchi the Sweet says: I always knew you could do it!\nBig Bao says: Congratulations!\nAce Longpaw says: I'll drink to that!\nNote that the above event will always be the same regardless what colored serpent you have raised.\n\nOnce you turn in the quest, Elder Anli will say the following:\n\nElder Anli says: Well done, . The cloud serpent that you have raised is now yours. Your journey together... is just beginning.",
            date = "2013-03-04T18:40:14-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31810#comments:id=1821007",
        },
        {
            id = 1749246,
            score = 6,
            author = "1049036",
            text = "This question has a bug at the moment. If you are in a group or a raid sometimes you cannot end this quest, even you can watch the movie. You must abandon the quest and be alone when you take again this quest, see again the clip and finish the quest.",
            date = "2012-10-24T06:05:37-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31810#comments:id=1749246",
        },
    },
