    [31847] = {
        {
            id = 1727997,
            score = 44,
            author = "1037862",
            text = "[pre]The rope is there.  It does not glow.\n\nWall - - - - - - - - - - - - - - - - - - - - -\n                                             -\n                                             -\n                                             -\n                                             -\n                               Rope          -\n  Ground level                x Here         -\n                     - - - - - - - - - - - - -\n                    -         x Quest turn in on top off wall\n                    -\n                    -[/pre]",
            date = "2012-10-01T22:15:37-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31847#comments:id=1727997",
        },
        {
            id = 1741885,
            score = 30,
            author = "Karadine",
            text = "https://www.wowhead.com/npc=62112 ends several breadcrumb quests offered to players as soon as they reach level 89 in order for them to begin questing in Dread Wastes. For a lot of players, its not intuitive how to reach her because she is located on the Serpent's Spine and on the border between zone maps. Here is a full guide:\n\nFrom [zone=5841] (quest https://www.wowhead.com/quest=31847):\nTalk to the flightmaster https://www.wowhead.com/npc=61512 that gives this quest and fly to \"Serpent's Spine, Vale of the Eternal Blossoms\". Alternately, you can ride to Shado-Pan Fallback, enter the doors and ascend the staircase to the top of the wall, you can then ride southward to get there.\n\nFrom [zone=5842]:\nhttps://www.wowhead.com/quest=31895 - Return to Shado-Pan Garrison, talk to the flightmaster https://www.wowhead.com/npc=62909 and fly to \"Serpent's Spine, Vale of the Eternal Blossoms\".\nhttps://www.wowhead.com/quest=31656 - This quest seems to be bugged and might not give the correct flightpath (and the text doesn't even mention it). You can either drop it and take one of the alternate breadcrumbs listed here (closest is https://www.wowhead.com/quest=31000), or ride to the Dread Wastes, going to the northeast corner of the zone to the Terrace of Gurthan. Next to the wall is a very small coil of Shado-Pan Rope that you can click on to ascend to the Serpent's Spine where you can reach Bowmistress Li (and also learn that flight path).\n\nFrom [zone=5840] (quests https://www.wowhead.com/quest=31390/https://www.wowhead.com/quest=31391):\nTaking your faction's quest adds the flight path you need. Talk to the flightmaster in your city and fly to \"Serpent's Spine, Vale of the Eternal Blossoms\".\n\nFrom [zone=6138] (quest https://www.wowhead.com/quest=31000):\nTaking this quest adds the flight path you need. Talk to the flightmaster https://www.wowhead.com/npc=63500 at The Sunset Brewgarden and fly to \"Serpent's Spine, Vale of the Eternal Blossoms\".",
            date = "2012-10-14T23:27:26-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31847#comments:id=1741885",
        },
        {
            id = 1721184,
            score = 20,
            author = "Feyranna",
            text = "Flight path to Serpent's Spine, Vale of Eternal Blossoms to get there if you carried on questing in another area and couldn't find where to pick this line back up :)",
            date = "2012-09-27T03:46:50-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31847#comments:id=1721184",
        },
        {
            id = 1720882,
            score = 17,
            author = "entitium",
            text = "The rope to climb up the wall is very hard to see. It does not sparkle like other objects you can interact with. I found the rope at 14,77",
            date = "2012-09-26T22:22:23-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31847#comments:id=1720882",
        },
        {
            id = 1724580,
            score = 9,
            author = "1037900",
            text = "You will get this quest in Winter's Blossom, Kun-Lai Summit from the flightmaster (34,59). Then you could flight to Serpent's Spine.",
            date = "2012-09-29T13:21:02-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31847#comments:id=1724580",
        },
    },
    [31853] = {
        {
            id = 1718269,
            score = 254,
            author = "918749",
            text = "If you are having trouble finding the ship, just zoom out the World Map and click on Kalimdor: Azshara. You will see the yellow question mark there at the bottom of the map, it's quite high up in the sky.",
            date = "2012-09-25T03:50:59-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31853#comments:id=1718269",
        },
        {
            id = 1718028,
            score = 81,
            author = "Himani",
            text = "The ship where you need to go is above you, in the air. It's like a zepplin kind of thing.. Directly above the question mark on the map.. Hope this helps..",
            date = "2012-09-24T17:21:20-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31853#comments:id=1718028",
        },
        {
            id = 2140459,
            score = 48,
            author = "537090",
            text = "To avoid further confusion, this is how the MoP (Mists of Pandaria) quest line begins. Horde version.\n\nTo get the quest you need to relog if you somehow missed the quest.\nThe zeppelin for some reason says it's outside. It is not. The zeppelin can be found high above Orgrimmar.\n\nHappy leveling!",
            date = "2015-03-19T18:25:12-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31853#comments:id=2140459",
        },
        {
            id = 1875260,
            score = 41,
            author = "Daedaluz2005",
            text = "do NOT board this ship from the back side of orgrimmar, go from the dock in front of the city on bladesfist bay and then go up. if you do it the otherway, for some reason, the ship is empty. if you go from the dock in front of the city the npcs will appear.",
            date = "2013-07-09T19:30:26-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31853#comments:id=1875260",
