    [31894] = {
        {
            id = 1796694,
            score = 13,
            author = "slylabs13",
            text = "It should be mentioned here that you *can* pick up the quest chain without talking to this NPC. Orbiss, the NPC she sends you to will offer the quest without talking to Yalia Sagewhisper, but if you do, she will be phased out by the time you get to her and you will not be able to pick up her quest.",
            date = "2013-01-11T14:31:28-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31894#comments:id=1796694",
        },
    },
    [31895] = {
        {
            id = 1741895,
            score = 25,
            author = "Karadine",
            text = "https://www.wowhead.com/npc=62112 ends several breadcrumb quests offered to players as soon as they reach level 89 in order for them to begin questing in Dread Wastes. For a lot of players, its not intuitive how to reach her because she is located on the Serpent's Spine and on the border between zone maps. Here is a full guide:\n\nFrom [zone=5841] (quest https://www.wowhead.com/quest=31847):\nTalk to the flightmaster https://www.wowhead.com/npc=61512 that gives this quest and fly to \"Serpent's Spine, Vale of the Eternal Blossoms\". Alternately, you can ride to Shado-Pan Fallback, enter the doors and ascend the staircase to the top of the wall, you can then ride southward to get there.\n\nFrom [zone=5842]:\nhttps://www.wowhead.com/quest=31895 - Return to Shado-Pan Garrison, talk to the flightmaster https://www.wowhead.com/npc=62909 and fly to \"Serpent's Spine, Vale of the Eternal Blossoms\".\nhttps://www.wowhead.com/quest=31656 - This quest seems to be bugged and might not give the correct flightpath (and the text doesn't even mention it). You can either drop it and take one of the alternate breadcrumbs listed here (closest is https://www.wowhead.com/quest=31000), or ride to the Dread Wastes, going to the northeast corner of the zone to the Terrace of Gurthan. Next to the wall is a very small coil of Shado-Pan Rope that you can click on to ascend to the Serpent's Spine where you can reach Bowmistress Li (and also learn that flight path).\n\nFrom [zone=5840] (quests https://www.wowhead.com/quest=31390/https://www.wowhead.com/quest=31391):\nTaking your faction's quest adds the flight path you need. Talk to the flightmaster in your city and fly to \"Serpent's Spine, Vale of the Eternal Blossoms\".\n\nFrom [zone=6138] (quest https://www.wowhead.com/quest=31000):\nTaking this quest adds the flight path you need. Talk to the flightmaster https://www.wowhead.com/npc=63500 at The Sunset Brewgarden and fly to \"Serpent's Spine, Vale of the Eternal Blossoms\".",
            date = "2012-10-14T23:33:28-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31895#comments:id=1741895",
        },
        {
            id = 1719240,
            score = 24,
            author = "Eruionmel",
            text = "If you're coming here to figure out how to get to her, you might have missed it when you discovered a new flight path along with the quest. I was a bit confused as well. You can go back across the bridge and take a FP directly there.\n\nIncidentally, this is an alternative to the quest in Kun-lai Summit for getting into the Vale of Eternal Blossoms. It's not a bad idea to run over to your respective Shrine and grab the hearth and flight points there.",
            date = "2012-09-25T21:45:48-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31895#comments:id=1719240",
        },
        {
            id = 1719905,
            score = 13,
            author = "Espelyn",
            text = "I took the flight path to The Serpent's Spine from any flight path in Pandaria. The flight path is technically located in the Vale of Eternal Blossoms if that helps anyone.",
            date = "2012-09-26T09:21:15-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31895#comments:id=1719905",
        },
        {
            id = 1741192,
            score = 6,
            author = "1025329",
            text = "If you take the quest https://www.wowhead.com/quest=31390 you will not be able to take this quest.",
            date = "2012-10-14T07:17:20-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31895#comments:id=1741192",
        },
        {
            id = 1721708,
            score = 5,
            author = "Garatoth",
            text = "This quest is the easiest way into questing in Dread Wastes (http://www.wowhead.com/zone=6138). Starting it requires being level 89 and it's picked up at Niuzao Temple in Townlong Steppes (http://www.wowhead.com/zone=5842). It grants you a flight path, Serpent's Spine, that will take you up atop the great wall and quests there will send you down into Dread Wastes.\n\nIf you do not see the flight path, you may be missing a connecting point, like at your faction hub in the Valley of Eternal Blossoms, or you may simply be having an error that can be solved by reloading your UI or logging out and in.",
            date = "2012-09-27T11:16:32-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31895#comments:id=1721708",
        },
    },
    [31936] = {
        {
            id = 1728100,
            score = 79,
            author = "Nessephanie",
            text = "If the system doesn't initially load for you, just leave the farm till your crops disappear and go back.",
            date = "2012-10-02T00:26:32-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31936#comments:id=1728100",
        },
        {
            id = 1699307,
            score = 49,
            author = "Voxxel",
            text = "Handing in this quest to Farmer Yoon automatically installs a new sprinkler system to your farm.\nBy clicking the sprinkler device you can deal with each \"Parched\" type crops at once.",
            date = "2012-08-13T05:33:16-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31936#comments:id=1699307",
        },
        {
            id = 1731792,
            score = 15,
            author = "Brendensmall",
            text = "Actual quest reward amount is 19 gold 84 silver 50 copper, and 275 reputation with the tillers. This is at level 90 with guild rep perks included.\nIt is NOT 141 gold 60 silver as shown.\n\n reward amount is now correct, cheers wowhead :)",
            date = "2012-10-05T00:45:05-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31936#comments:id=1731792",
        },
        {
            id = 1796854,
            score = 14,
            author = "Mendric",
            text = "If you've already bought this and completed the quest associated with it, do not buy it again. It will allow you to buy it again, but you will not be able to do the quest again, nor will you be able to sell it back.",
            date = "2013-01-11T18:59:33-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31936#comments:id=1796854",
        },
        {
            id = 1735108,
            score = 9,
            author = "784507",
            text = "I purchased the Sprinkler System and turned in the quest, but nothing changed on my farm. I talked to Yoon and he indicated that we had a new sprinkler system. None was to be found. So I decided to leave the area and come back, essentially rephasing myself. I could see the sprinkler. However, there wasn't an interactive icon anywhere on it. I flew even farther away and came back to find a handy gear icon appear when I hover over the system.\n\nI had to rephase twice, but the change was instant each time. I didn't wait or do another quest in the mean time - just flew away and came right back.",
            date = "2012-10-08T01:26:01-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31936#comments:id=1735108",
        },
    },
    [31937] = {
        {
            id = 1734384,
            score = 66,
            author = "171672",
            text = "If you can't find this immediately after installing it you need to \"reset\" your farm's phase. Just move far enough away that you phase out of your farm (the inn at Halfhill is far enough), then go back and your Pest Repellers should be right in the middle of your plots.",
            date = "2012-10-07T10:33:44-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31937#comments:id=1734384",
        },
        {
            id = 1728742,
            score = 21,
            author = "Beltane",
            text = "You can buy this and use it after completing https://www.wowhead.com/quest=30523, which is available once you reach revered with the Tillers.",
            date = "2012-10-02T12:43:00-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31937#comments:id=1728742",
        },
        {
            id = 1699303,
            score = 13,
            author = "Voxxel",
            text = "Handing in this quest to Farmer Yoon automatically installs a new pest repeller system to your farm. By clicking the device you can deal with each \"Infested\" type crops at once.",
