    [31938] = {
        {
            id = 1739347,
            score = 84,
            author = "Henderman",
            text = "After completing the quest you have to leave the area to have the plow appear.\nThe Master Plow (http://www.wowhead.com/item=89815) moves in any direction, but always in a straight line.",
            date = "2012-10-12T08:28:54-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31938#comments:id=1739347",
        },
        {
            id = 1739904,
            score = 50,
            author = "Midgetpower",
            text = "Disappointed it does NOT have any effect on \"occupied soil\".  So still have to manually kill the vermin.  I would think a blade of that size would take care of them for you too.\n\n***As of 5.2, this will mow the vermin down to 30%  Makes them a lot easier to kill, but you'll still need to till that plot again.",
            date = "2012-10-12T20:45:43-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31938#comments:id=1739904",
        },
        {
            id = 1736829,
            score = 32,
            author = "Therax",
            text = "Farmer Yoon: Hello, I'm Master Plow. Are you tired of having your hands cut off by rotary tillers and the inevitable heart attacks that come with shoveling dirt?\n\nFarmer Yoon: Then call Pandaren-5-3226. Call now and receive a free T-shirt.\n\nLi Li: But I'm a real tightwad. Can I afford this remarkable system?\n\nFarmer Yoon: Absolutely. My prices are so low, you'll think I've suffered brain damage!\n\nAndi: You are fully bonded and licensed by the city, aren't you, Master Plow?\n\nFarmer Yoon: (through the side of his mouth) Shut up, boy.\n\nFarmer Yoon: So remember...\nCall Master Plow. That's my name.  That name again is Master Plow.\n\nShamelessly swiped, and adapted from: Mr. Plow (song) - Simpsons Wiki (http://simpsons.wikia.com/wiki/Mr._Plow_(song))",
            date = "2012-10-09T17:56:31-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31938#comments:id=1736829",
        },
        {
            id = 1763570,
            score = 20,
            author = "olania",
            text = "Do you have any idea how much time this will save us?\n\nUs? I don't see your fat ass killing those birds...",
            date = "2012-11-17T01:00:50-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31938#comments:id=1763570",
        },
        {
            id = 1794153,
            score = 11,
            author = "Mondoblasto",
            text = "I know it sounds stupid, but once I got the plow, I couldn't help thinking:  \"UPGRADE COMPLETE.\"",
            date = "2013-01-07T07:43:33-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31938#comments:id=1794153",
        },
    },
    [31941] = {
        {
            id = 1781888,
            score = 5,
            author = "AnrDaemon",
            text = "You may dig out the sprout to free the plot, once you've got a credit for the quest and turned it in.\nI.e., if you're maximizing your crops by listening to the drunk fish (http://www.wowhead.com/achievement=7295).\nThe quest does not require you to grow it.",
            date = "2012-12-15T14:47:38-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31941#comments:id=1781888",
        },
        {
            id = 1823101,
