    },
    [31942] = {
        {
            id = 1715654,
            score = 9,
            author = "Zillions",
            text = "One of several rotating daily quests offered by https://www.wowhead.com/npc=58646.\nSimply walk over to The Halfhill Market and purchase the https://www.wowhead.com/item=89329 from https://www.wowhead.com/npc=58718, then go back to your farm and plant the seed in tilled soil, and care for the newly planted crop until it is considered \"Growing\".\n\nAfter you plant it, you are free to use the https://www.wowhead.com/item=89880 to remove the crop, if you have a bigger priority for your planting needs.  (You are not required to harvest the item the next day).",
            date = "2012-09-18T19:07:00-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31942#comments:id=1715654",
        },
