    [31943] = {
        {
            id = 1733359,
            score = 8,
            author = "MarsJenkar",
            text = "And I thought my puns were bad.  ;-)",
            date = "2012-10-06T12:08:17-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31943#comments:id=1733359",
        },
        {
            id = 1734908,
            score = 4,
            author = "baldie80",
            text = "Just in case anyone was wondering, you only need to plant witchberries in ONE of your plots to complete this quest.  Very important to know if you're just starting out with the Tillers and are trying to get a stack of 50 of something for a banquet of some kind.\n\nYou only need to take up one spot for the quest and the rest can go for whatever you may actually WANT to grow.",
            date = "2012-10-07T19:46:59-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31943#comments:id=1734908",
        },
        {
            id = 1781939,
            score = 3,
            author = "AnrDaemon",
            text = "You may dig out the sprout to free the plot, once you've got a credit for the quest and turned it in.\nI.e., if you're maximizing your crops by listening to the drunk fish (http://www.wowhead.com/achievement=7295).\nThe quest does not require you to grow it.",
            date = "2012-12-15T16:15:37-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31943#comments:id=1781939",
        },
        {
            id = 1781794,
            score = 1,
            author = "827152",
            text = "Possibly a reference to the Australian bank slogan \"Which bank? Commonwealth.\" that made Australians start to refer to that bank as whichbank. So they started saying: \"Which bank? Whichbank.\"",
            date = "2012-12-15T11:47:46-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31943#comments:id=1781794",
        },
        {
            id = 1823110,
            score = 1,
            author = "rikapi",
            text = "This quest (along with all the \"plant this seed\" quests) becomes obsolete once you inherit the farm from Yoon - or rather, it gets replaced by the faction work orders.",
            date = "2013-03-06T19:38:02-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31943#comments:id=1823110",
        },
    },
    [31945] = {
        {
            id = 1720321,
            score = 290,
            author = "jjanchan",
            text = "An important note - you start with 4 patches of soil, but to complete this quest you only need to plant ONE scallion seed - you will get 5 scallions from each one planted!  I had to search high and low to find this information =)\n\nRarely, a vegetable will yield a plump crop, which yields an extra 2-3 vegetables when harvested.  Of note - if you speak to https://www.wowhead.com/npc=58710, he will tell you which veggies will yield a plump crop the next day (for a gold fee).",
            date = "2012-09-26T14:53:39-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31945#comments:id=1720321",
        },
        {
            id = 1900944,
            score = 137,
            author = "SpakyTwo",
            text = "You may want to plant the next item in the \"votes\" list so that you don't have to wait for the dailes to reset (in this case 2 Juicycrunch Carrots) .\n I have compiled the five people and their votes below.\n\nFor example: When you go to plant the scallion for Gina, you also plant the Juicycrunch Carrots for Mung Mung. This will make it so that as soon as you hit honored you can do Mung Mung's questline all at once and not have to wait until the next day. If you have bought the https://www.wowhead.com/item=93226, you should be just over honored when you get to this quest.\n\nThe five people and their veggies to plant and their votes are as follows (including this quest)\n\n[quest=31945 ]\n\nPlant and harvest 1 https://www.wowhead.com/item=74843, then deliver 5 Scallions to Gina Mudclaw.\n\nhttps://www.wowhead.com/quest=31946 (Requires level 90)\n\nPlant and harvest 2 https://www.wowhead.com/item=74841, then deliver 10 Juicycrunch Carrots to Mung-Mung.\n\nhttps://www.wowhead.com/quest=31947\n\nPlant and harvest 3 https://www.wowhead.com/item=74840, then deliver 15 Green Cabbages to Farmer Fung.\n\nhttps://www.wowhead.com/quest=31949\n\nPlant and harvest 3 https://www.wowhead.com/item=74846, then deliver 15 Witchberries to Nana Mudclaw.\n\nhttps://www.wowhead.com/quest=30527\n\nPlant and harvest 4 https://www.wowhead.com/item=74848, then deliver 20 Striped Melons to Farmer Yoon.",
            date = "2013-09-21T04:23:22-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31945#comments:id=1900944",
        },
        {
            id = 1755019,
            score = 67,
            author = "slagathor",
            text = "If you are leveling, this is the last quest you can do related to farming until you hit level 90. The rest of the chain starts back up once you hit 90. You can however, continue to use the 4 plots on the farm to grow veggies for your cooking, you just wont get any rep or quests until level 90.",
            date = "2012-11-01T13:22:18-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31945#comments:id=1755019",
        },
        {
            id = 1703687,
            score = 61,
            author = "lloviosa",
            text = "This is the final quest in the chain to unlock farming.\n\nWhen you plant scallions for Gina, you'll only need to plant one. For the other slots, you can plant whatever you like.\n\nA Helping Hand  (http://mop.wowhead.com/quest=30252)\nLearn and Grow I: Seeds (http://mop.wowhead.com/quest=30535)\nLearn and Grow II: Tilling and Planting (http://mop.wowhead.com/quest=30254)\nLearn and Grow III: Tending Crops (http://mop.wowhead.com/quest=30255)\nLearn and Grow IV: Harvesting  (http://mop.wowhead.com/quest=30256)\nLearn and Grow  V: Halfhill Market (http://mop.wowhead.com/quest=30257)\n*Learn and Grow VI: Gina's Vote (http://mop.wowhead.com/quest=31945)\n\n*You may have to do this last quest the following day. Crops ripen when dailies reset so unless its slightly before that time, you'll need to come back after they do, or any time the next day.\n\nThe good news is that if you have your crops planted even moments before reset, they will be ready very soon! This applies for regular farming too, not just this quest. I've tested and tried this method myself and was able to harvest within 8 min. after planting and tending.\n\nEdit: updated for patch 5.1. Crops no longer ripen at midnight server time.",
            date = "2012-08-24T02:53:08-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31945#comments:id=1703687",
        },
        {
            id = 1720706,
            score = 32,
            author = "515518",
            text = "If you are like me wondering what you need to do after you plant them talking to Farmer Yoon (he is right next to the crops) he will explain how everything is fixed.",
            date = "2012-09-26T19:33:49-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31945#comments:id=1720706",
        },
    },
    [31946] = {
        {
            id = 1875382,
            score = 56,
            author = "Iamnotsane",
            text = "What plants you will need for each quest.\n\nYou will need for the first quest 1 scallion plant for the next, 2 carrots plants, for the next 3 cabbages plants, for the next 3 witchberry plants, and for the last one 4 striped melon plants. But if you plant the ones you will need the day before you get the quest for them just remember not to harvest them without the quest. ;)\n\n(And sorry about mixing the witchberry and striped melons fixed it now thanks for telling me Wakharaa.) :)",
            date = "2013-07-10T05:19:34-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31946#comments:id=1875382",
        },
        {
            id = 1731600,
            score = 46,
            author = "Tribunal",
            text = "Mung-Mung says: Mung-Mung impressed, . You help me without asking for anything in return...\n\nYeah, sure I did.... *whistles*",
            date = "2012-10-04T20:01:54-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31946#comments:id=1731600",
        },
        {
            id = 1733201,
            score = 31,
            author = "253508",
            text = "Even if you did not follow ranu's advice, you can still complete the quest on the same day.\nAll you need to do is replant the carrots a couple of time. Each time you plant, there is a chance of getting an instant grown carrot. It took me 12 times to plant to get both harvests done.",
            date = "2012-10-06T08:40:01-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31946#comments:id=1733201",
        },
        {
            id = 1991774,
            score = 27,
            author = "1022520",
            text = "Next items to plant, in this exact order:\n\nhttps://www.wowhead.com/quest=31947\n\nPlant and harvest 3 https://www.wowhead.com/item=79102, then deliver 15 https://www.wowhead.com/item=74840 to https://www.wowhead.com/npc=57298.\n\nhttps://www.wowhead.com/quest=31949\n\nPlant and harvest 3 https://www.wowhead.com/item=89326, then deliver 15 https://www.wowhead.com/item=74846 to https://www.wowhead.com/npc=64597.\n\nhttps://www.wowhead.com/quest=30527\n\nPlant and harvest 4 https://www.wowhead.com/item=89329, then deliver 20 https://www.wowhead.com/item=74848 to https://www.wowhead.com/npc=58646.\n\nCredits go to SpakyTwo, for his comment at https://www.wowhead.com/quest=31945.",
            date = "2014-08-14T18:33:26-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31946#comments:id=1991774",
        },
        {
            id = 1733115,
            score = 20,
            author = "ranu",
            text = "If you plan this, the quest can be completed on the same day you get it. The day before you hit the reputation required you plant the seeds you will need for the quest. When you then get the quest, all you need to do is harvest the plants in your farm and plant new seeds (if you don't need the plants you can dig them up with the shovel after getting credit).",
            date = "2012-10-06T06:51:47-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31946#comments:id=1733115",
        },
    },
