    [31948] = {
        {
            id = 1746787,
            score = 42,
            author = "chrth",
            text = "There's a moss-covered rock where the falls split in front of the guardian.   I was able to get the water from that spot without aggroing the guardian.",
            date = "2012-10-20T23:04:42-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31948#comments:id=1746787",
        },
        {
            id = 1738980,
            score = 35,
            author = "144827",
            text = "Don't die here if you can help it...there is no way to return to your corpse at this time so it will be an expensive trip to the Spirit Healer.",
            date = "2012-10-11T23:25:42-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31948#comments:id=1738980",
        },
        {
            id = 1736316,
            score = 24,
            author = "1031642",
            text = "The 1000-Year Water flows all the way to Halfhill to Nana's home.\nIt remains a mystery why you have to collect it right where the guardian stands.",
            date = "2012-10-09T04:16:07-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31948#comments:id=1736316",
        },
        {
            id = 1737878,
            score = 24,
            author = "kharth",
            text = "Just a note, you don't have to kill the guardian for the quest, just use the pitcher where hes at. Bind, fear, all that good stuff works.",
            date = "2012-10-10T20:48:46-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31948#comments:id=1737878",
        },
        {
            id = 3279005,
            score = 17,
            author = "wowogamer",
            text = "Has anybody figured out how to complete this quest (without help from somebody with a 2-person flying mount) if you are doing it on a lower level toon that has not access to flying?\n\nEdit: I just figured out how. It is doable by using two packs of Goblin Glider Kit. The first pack of Goblin Glider Kit is to be used from the highest point you can find just outside the entrance to Terracy of Endless Spring, located close to Tawern in the Mists, /way 48.71, 60.27. From there, you can reach a mountain/cliff plateau on the rim of Valley of the Fourth Winds, /way 69.00, 18.00. Then you must wait for the second Goblin Glider Kit to be ready. The second Goblin Glider Kit can bring you to the quest location.",
            date = "2020-12-22T19:57:45-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31948#comments:id=3279005",
        },
    },
    [31949] = {
        {
            id = 1733130,
            score = 87,
            author = "ranu",
            text = "If you plan this, the quest can be completed on the same day you get it. The day before you hit the reputation required you plant the seeds you will need for the quest. When you then get the quest, all you need to do is harvest the plants in your farm and plant new seeds (if you don't need the plants you can dig them up with the shovel after getting credit).",
            date = "2012-10-06T07:05:28-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31949#comments:id=1733130",
        },
        {
            id = 1844826,
            score = 51,
            author = "SpareSimian",
            text = "Once you've completed this quest, you'll want to plant striped melons to prepare for https://www.wowhead.com/quest=30527.",
            date = "2013-04-19T04:18:14-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31949#comments:id=1844826",
        },
        {
            id = 1738817,
            score = 22,
            author = "Mortimer",
            text = "You can \"cheat\" these quests by taking out your shovel, dig up a few plants and plant new ones over and over until you get the ones called \"bursting \" which can be harvested right away. The chance seems to be quite low so it may take a while to complete it this way but it's a good way to do it if there's still some time left until the following midnight and you're desperate to get it done.",
            date = "2012-10-11T19:05:14-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31949#comments:id=1738817",
        },
        {
            id = 1741643,
            score = 14,
            author = "386717",
            text = "Upon completion of this quest, you get this little interaction:\n\nNana Mudclaw says: Anyone with such a talented green thumb needs to be a Tiller. I don't care what that hare-brained grandson of mine says! Haohan is wrong about Farmer Yoon. You have my vote, .\n\nFarmer Yoon says: Y-y-you're N-N-Nana Mudclaw! I n-never thought I'd get a visit from the m-m-matron herself!\nNana Mudclaw says: I had to come and see Old Yoon's cub with my own eyes.\nNana Mudclaw says: I knew your grandfather well. I was very sorry when he passed.\nNana Mudclaw says: You know, the two of you remind me of him.\nNana Mudclaw says: You were stubborn enough to keep tilling this soil even though you didn't have much experience.\nNana Mudclaw says: You were brave enough to stand up to my grandson, Haohan.\nNana Mudclaw says: And you two have shown quite the knack for growing delicious fruits and vegetables.\nNana Mudclaw says: For that, you have earned my respect, my gratitude, and my vote. Well done.\nNana Mudclaw says: Oh, and Farmer Yoon.\nNana Mudclaw says: I do believe your grandpa would be very proud of you.\n\nRather heartwarming, if you ask me. :)",
            date = "2012-10-14T17:32:39-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31949#comments:id=1741643",
        },
        {
            id = 1757492,
            score = 9,
            author = "1045333",
            text = "Here are the previous two parts to this, if you wound up coming straight here ;)\nhttps://www.wowhead.com/quest=30519\nhttps://www.wowhead.com/quest=31948\n\nAs a side note, the third part really needs to get marked as part of the series :p",
            date = "2012-11-05T06:59:09-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31949#comments:id=1757492",
        },
    },
    [31959] = {
        {
            id = 1789209,
            score = 63,
            author = "1041126",
            text = "Ok, for everyone who is wondering why they can't do this quest and they are exalted - you need to have completed all of the quests and unlocked all of the Paragons.\n\nThat means you need to have completed https://www.wowhead.com/achievement=7312 - that means more quests after you get https://www.wowhead.com/achievement=6540.\n\nIf you don't know where you are and what you have left, check which of the Paragons for https://www.wowhead.com/achievement=7312 and then check the page to see where the quest chains are.\n\nThe usual ones missed are the reputation dependant quests:\nhttps://www.wowhead.com/quest=31175 requires honored reputation\nhttps://www.wowhead.com/quest=31439 requires revered reputation\nhttps://www.wowhead.com/quest=31018 requires revered reputation\n\nNOTE\n\nIf you are reading ahead on this questline, make sure you do all of the branches for the Paragons - you'll get more dailies which means more reputation per day (and it's slow).  Make sure when you hit revered you pick up your https://www.wowhead.com/item=92522 - use it as soon as you hit revered then turn in any remaining quests since you'll get double experience straight off!\n\nHope I helped.",
            date = "2012-12-29T16:36:59-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31959#comments:id=1789209",
        },
        {
            id = 1741148,
            score = 35,
            author = "Karadine",
            text = "It's confirmed, this starts the finale quest chain for [faction=1337], given upon reaching exalted.",
            date = "2012-10-14T06:07:32-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31959#comments:id=1741148",
        },
        {
            id = 3242132,
            score = 29,
            author = "BlooMunKy",
            text = "For anyone wondering where you turn this quest in after watching the dialogue.\n\nYou can click the quest in the tracking drop down on the right of the screen, if you can't see this, then relog to get this option to show up.\n\nHope this helps someone.",
            date = "2020-10-25T06:17:49-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31959#comments:id=3242132",
        },
        {
            id = 1751805,
            score = 17,
            author = "975652",
            text = "Must be Exalted with the Klaxxi (http://www.wowhead.com/?faction=1337), and have completed all the Paragon quests.\nIf you've started this quest and it appears bugged, (like sending you back to Malik (http://www.wowhead.com/?npc=66875) and he's not there, or autocomplete is not available).\nJust go back to the quest in your log and select complete to get The Wrath of Shek'zeer (http://www.wowhead.com/?quest=31609) quest and continue on.",
            date = "2012-10-27T12:58:56-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31959#comments:id=1751805",
        },
        {
            id = 1747462,
            score = 15,
            author = "Thae",
            text = "I encountered a bug with this today on live:\n\nWhen you find Malik on the battlefield, if you speak to him and nothing happens try relogging. I was mounted and this may have caused it, but all I had to do was relog and try talking to him again dismounted and the RP event started immediately.",
            date = "2012-10-21T21:01:55-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31959#comments:id=1747462",
        },
    },
