    [31998] = {
        {
            id = 1777757,
            score = 4,
            author = "Black2u",
            text = "Well I put myself on challenge mode and did the heroic on this, and nothing, nada.. no completion of this quest.  I am completely confused.. I kept asking the group where is the Challengers Orb and no one seemed to know what I was talking about.",
            date = "2012-12-08T12:30:37-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31998#comments:id=1777757",
        },
        {
            id = 1726794,
            score = 3,
            author = "Fiamma",
            text = "Each day, https://www.wowhead.com/npc=64028 will offer one of the following quests:\n\nhttps://www.wowhead.com/quest=32007\nhttps://www.wowhead.com/quest=32005\nhttps://www.wowhead.com/quest=32006\nhttps://www.wowhead.com/quest=32003\nhttps://www.wowhead.com/quest=31998\nhttps://www.wowhead.com/quest=32001\nhttps://www.wowhead.com/quest=32004\nhttps://www.wowhead.com/quest=32002\nhttps://www.wowhead.com/quest=32000\n\nUpon completion, each will award 112g23s50c and 60 Valor Points (http://www.wowhead.com/currency=396).",
            date = "2012-10-01T01:53:22-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31998#comments:id=1726794",
        },
        {
            id = 1777697,
            score = 2,
            author = "Black2u",
            text = "What is the difference between challenge mode and the heroic?  I just completed the heroic mode, didn't realize that there was a difference.",
            date = "2012-12-08T09:49:03-06:00",
            sourceUrl = "https://www.wowhead.com/quest=31998#comments:id=1777697",
        },
        {
            id = 1750783,
            score = 1,
            author = "Benna1234",
            text = "As of 19/10/2012 this now gives 80 Valor Points instead of 60.\n\nNote that you only have to complete the required Challenge Mode dungeon, not obtain any medals.",
            date = "2012-10-26T09:14:23-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31998#comments:id=1750783",
        },
        {
            id = 1849491,
            score = 1,
            author = "704456",
            text = "To enter a Challenge Mode dungeon, you must assemble a group, the group leader will then select the difficulty of Challenge Mode (where you pick Normal or Heroic, by right-clicking on your own portrait.) Then, instead of using the RDF, you have to physically go (I know, what a drag) to the dungeon entrance.\n\nThen you run through, trying to beat the clock for some medals and eventually a full set of neat-o transmog gear. Completing the dungeon will net the daily completion.",
            date = "2013-05-03T04:13:47-05:00",
            sourceUrl = "https://www.wowhead.com/quest=31998#comments:id=1849491",
        },
    },
    [31999] = {
        {
            id = 1697924,
            score = 0,
            author = "250261",
            text = "after accepting the quest at flag, i walked around the airstip, and the general was no where to be seen.  probably because i'm doing the quest out of sequence, but he should still be available to turn in the quest somewhere!",
            date = "2012-08-09T10:22:08-05:00",
