    [32016] = {
        {
            id = 1724952,
            score = 46,
            author = "uriahworld",
            text = "What do Elder Charm of Good Fortune grant you? Currency (http://www.wowhead.com/currency=697)\nYou should always change the lesser charms into elder ones as they save no other purpose.\n\nIf you have one or more Charms of Good Fortune, then whenever you kill a raid boss (in Raid Finder, normal or heroic) then a new UI window will pop up asking if you want to spend your Charm on a bonus roll. If you click yes, then you’ll instantly get another shot at that boss’s loot table! You will always win something from the bonus roll, such as a pile of gold, gems, or flasks. However, you also have a small (but not miniscule) chance of receiving a piece of epic loot. As with the personal loot system, the item will always be something designed for your current spec.\nSource: http://us.battle.net/wow/en/blog/4736886/\n\nQ: Could you clarify about Charms of Good Fortune. Only usable in LFR or usable on normal/heroic mode raid bosses too?\nA: All. Boss dies. You decide whether to use a charm for bonus loot. Normal boss loot is distributed however your group does it.\nSource: http://www.mmo-champion.com/content/2928-Zone-Previews-Blue-Tweets-MoP-Design-Interview-Curse-Weekly-Roundup",
            date = "2012-09-29T17:43:07-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32016#comments:id=1724952",
        },
        {
            id = 1727115,
            score = 43,
            author = "Dreadlack",
            text = "This quest is available once every week to award you with 3 Elder Charms, which can be used to roll an extra time on a boss drop.\n\nYour currency tab can hold a maximum of 10 Elder Charms, and as such you will not receive anymore charms above this value.",
            date = "2012-10-01T07:34:09-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32016#comments:id=1727115",
        },
        {
            id = 1749313,
            score = 19,
            author = "Thereisone",
            text = "Can be used on Sha Of Anger https://www.wowhead.com/npc=60491\n\nUsed one today to receive Legplates of Resounding Rings https://www.wowhead.com/item=85330\n\nSo I guess the same could be said for https://www.wowhead.com/npc=62346",
            date = "2012-10-24T07:52:08-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32016#comments:id=1749313",
        },
        {
            id = 1764132,
            score = 17,
            author = "enslacked",
            text = "Widely known among Pandaran natives as \"Elder Charms of 28g\", these tokens are passed out to stupid foreigners in exchange for pulling weeds, collecting animal meat, and doing other tedious chores around the farm.",
            date = "2012-11-18T05:43:45-06:00",
            sourceUrl = "https://www.wowhead.com/quest=32016#comments:id=1764132",
        },
        {
            id = 1821808,
            score = 12,
            author = "Aquissya",
            text = "I have not been able to find this quest since 5.2 came out a few hours ago. It seems that they have been replaced with the Mogu charms for the Thunder King raids but the Elder Charm currency still shows up in the currency page, probably as a legacy item.",
            date = "2013-03-05T21:13:44-06:00",
            sourceUrl = "https://www.wowhead.com/quest=32016#comments:id=1821808",
        },
    },
    [32017] = {
        {
            id = 1705235,
            score = 64,
            author = "Cielos",
            text = "You can only complete this quest once a week.",
            date = "2012-08-28T12:17:16-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32017#comments:id=1705235",
        },
        {
            id = 1742499,
            score = 23,
            author = "Moosplauze",
            text = "It should be mentioned, that the purpose of the Elder Charm of good Fortune is to give you an extra roll for the chance on additional treasure each time you kill a world or raid boss. When the boss is defeated you recieve your normal reward and a little window pops up where you can chose to use an elder charm of good fortune for the extra roll or decline it. When you chose to do the extra roll one of the charms is consumed, so for 90 lesser charms you recieve 3 elder charms which gives you 3x the chance to roll for extra treasure. Also, like I said before, you should be aware, that the extra roll can also grant you the very item you already recieved as normal drop from the boss.",
            date = "2012-10-15T13:42:35-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32017#comments:id=1742499",
        },
        {
            id = 1822232,
            score = 21,
            author = "Memoryk",
            text = "This from official Blizzard post -  Elder Charms will continue to be used for bonus rolls on 5.0 raids and world bosses, and will now be acquired as item drops by killing enemies in the new 5.2 Thundering Isle outdoor zone. So that's it for question where to get them :-)",
            date = "2013-03-06T04:09:26-06:00",
            sourceUrl = "https://www.wowhead.com/quest=32017#comments:id=1822232",
        },
        {
            id = 1725408,
            score = 20,
            author = "DELValdregan",
            text = "I'm not sure if the displayed reward is correct because it gave me 45 Gold, 60 Silver.",
            date = "2012-09-30T01:43:33-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32017#comments:id=1725408",
        },
        {
            id = 1725682,
            score = 8,
            author = "davesurfer",
            text = "Good news is that the 3 Charms are in the currency tab.  I am running out of bag/bank space\n\nAlso only 46 Gold 60 Silver",
            date = "2012-09-30T06:46:16-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32017#comments:id=1725682",
        },
    },
