            score = 2,
            author = "kylector",
            text = "I too was stuck where I couldn't pick up this quest anywhere even though I had done the quests prior. So I did everything in Soggy's Gamble and then checked The Sunset Brewgarden where I was sent to Rikkitun Village. Once I did all those quests (only about 6), I went back to The Sunset Brewgarden and Lya of Ten Songs finally gave me this quest. I also got the achievement for the zone.",
            date = "2012-11-08T18:09:35-06:00",
            sourceUrl = "https://www.wowhead.com/quest=32030#comments:id=1759431",
        },
        {
            id = 1744975,
            score = 0,
            author = "139372",
            text = "Got a bug where this did not automatically show up for me.",
            date = "2012-10-18T15:16:47-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32030#comments:id=1744975",
        },
        {
            id = 1762313,
            score = 0,
            author = "752459",
            text = "I did the quest line to awaken Iyyokuk in pieces so I'm not sure if anyone else would have a problem -- I couldn't find this quest when I finally got around to trying to free all the paragons. It isn't given by Lya of Ten Songs in Sunset Brewgarden. I got it at 38.2, 17.2 (Rikkitun Village). Lya of Ten Songs is sometimes at Rikkitun and sometimes at Sunset Brewgarden.",
            date = "2012-11-14T12:48:34-06:00",
            sourceUrl = "https://www.wowhead.com/quest=32030#comments:id=1762313",
        },
    },
    [32035] = {
        {
            id = 1731664,
            score = 18,
            author = "Gwynydd",
            text = "DO NOT TAKE this directional until bug is fixed.  It will preclude you from getting \"Where Silk Comes From\"...happened to my 3rd toon through.  The first two didn't take the directional.  It's found in Halfhill, so don't be tempted if you end up there early looking for a mailbox >.<.",
            date = "2012-10-04T21:24:45-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32035#comments:id=1731664",
        },
        {
            id = 2019404,
            score = 13,
            author = "jerodast",
            text = "As @EbonAossi reports in a reply here, this quest and its follow-up was reset in 6.0.2, presumably to allow people who encountered the quest accessibility bug to complete the follow-up at last (but also allowing people who had NOT had the bug to complete both quests a second time).",
            date = "2014-10-26T10:10:59-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32035#comments:id=2019404",
        },
        {
            id = 1788828,
            score = 9,
            author = "1057174",
            text = "This quest title is a play on the saying, \"Got Milk?\" commonly found on nutritional posters (at my school anyway)",
            date = "2012-12-28T23:14:43-06:00",
            sourceUrl = "https://www.wowhead.com/quest=32035#comments:id=1788828",
        },
        {
            id = 1754023,
            score = 1,
            author = "10171",
            text = "Here's what's happening: when you turn in this quest, both this and Where Silk Comes From (http://www.wowhead.com/quest=30072) are flagged as complete in the database. You can confirm this using addons that query the server, like Quest Completist (http://www.curse.com/addons/wow/quest_completist).\n\nI opened a ticket and the GM confirmed it. But he can't be sure if it counted for The Seeker.\nGM words:\nWe can indeed confirm for you that you have Where Silk Comes From flagged as complete. I cannot for sure tell you if it counted for the Seeker, I can tell you as normal quest that it certainly should have. [...]\n\nEDIT: Tested today on another char, my \"The Seeker\" achievement jumped from 1317 to 1322 quests complete.",
            date = "2012-10-30T20:14:11-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32035#comments:id=1754023",
        },
        {
