    [32045] = {
        {
            id = 1736152,
            score = 18,
            author = "957528",
            text = "Succula is stealthed, so you may think it is not there. It's in the water at the very edge, feeding off a dead crane. If you still aren't sure where it is, it's right next to a little nick in the river and right where the farmland platform-hill ends. A fishing pool spawns near it.\n\nSuccula's name is probably a reference to \"suck\" (as in sucking blood) and Dracula.",
            date = "2012-10-08T23:17:57-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32045#comments:id=1736152",
        },
        {
            id = 1720055,
            score = 13,
            author = "1034741",
            text = "ok most these are easyto kill solo cords are\n\nkracor          [55.99][33.99]\n\nThundergill  [55.52][26.14]\n\nsuccula        [51.28][26.95]",
            date = "2012-09-26T11:23:47-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32045#comments:id=1720055",
        },
        {
            id = 1719648,
            score = 5,
            author = "Oxiegen",
            text = "Considering that Thundergill is a lvl 89 mob on a lvl 86 quest, he could be a bit tough.\nWhen you solo this quest, remember to use your cooldowns. Or else he will kick you a$$ from here to there.\n\nI died twice on this guy trying to solo him.\n\nIt helps if you are two or more players on the same quest.\nYou don't even have to be in group to get the completion.",
            date = "2012-09-26T04:54:31-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32045#comments:id=1719648",
        },
        {
            id = 1747429,
            score = 5,
            author = "Fluffmeister",
            text = "Is this quest bugged? I attacked him, got him down to about 1/3 of his strength, then he suddenly went back to full strength, and none of my attacks worked. He didn't try and attack me either - he was just suddenly invulnerable, and gave up attacking.",
            date = "2012-10-21T19:51:20-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32045#comments:id=1747429",
        },
        {
            id = 1833374,
