    [32189] = {
        {
            id = 2176203,
            score = 33,
            author = "SeriesSix",
            text = "Seems to be bugged.\n\nCan gain the quest and see the yellow quest marker but unable to see Barnaby due to phasing.",
            date = "2015-05-03T06:36:50-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32189#comments:id=2176203",
        },
        {
            id = 1772626,
            score = 18,
            author = "talaitha",
            text = "This quest is only available from Merchant Greenfield on days that Barnaby Fletcher is visiting the Market.",
            date = "2012-11-30T23:05:43-06:00",
            sourceUrl = "https://www.wowhead.com/quest=32189#comments:id=1772626",
        },
        {
            id = 1769791,
            score = 17,
            author = "iinyla",
            text = "This quest was not offered from Merchant Greenfield (/npc=58718) until I hit revered with The Tillers.",
            date = "2012-11-28T07:18:59-06:00",
            sourceUrl = "https://www.wowhead.com/quest=32189#comments:id=1769791",
        },
        {
            id = 2261653,
            score = 16,
            author = "Melandroso",
            text = "As Merduric writes on the https://www.wowhead.com/npc=67565 page:\nIf, while doing Tiller dailies, you get the quest \"A Shabby New Face\", and Barnaby Fletcher isn't in the market that day, try a realm hop in custom LFG. It may take a few hops, and others on this page say that you can do the quest while in a raid group. Easy peasy.",
            date = "2015-10-10T08:45:15-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32189#comments:id=2261653",
        },
        {
            id = 1768864,
            score = 13,
            author = "Emmaleah",
            text = "Follow up: One Magical, Flying Kingdom's Trash... (http://www.wowhead.com/quest=32198)\nresults in Unstable Portal Shard (http://www.wowhead.com/item=91806)\nwhich when planted at your farm can grow into a random portal shard such as:\nStormwind Portal Shard (http://www.wowhead.com/item=91860)\nThunder Bluff Portal Shard (http://www.wowhead.com/item=91861)\nUndercity Portal Shard (http://www.wowhead.com/item=91862)\nSilvermoon Portal Shard (http://www.wowhead.com/item=91863)\nIronforge Portal Shard (http://www.wowhead.com/item=91864)\nDarnassus Portal Shard (http://www.wowhead.com/item=91865)\nExodar Portal Shard (http://www.wowhead.com/item=91866)\nOrgrimmar Portal Shard (http://www.wowhead.com/item=91850)\n\nThese stack to 20 and are only useable on sunsong ranch.\nThe quest (or some variation of it) is repeatable, but I don't know on what schedule yet. (daily/weekly?)\n\nAfter you have done the quest, if you happen to see Barnaby Fletcher at Halfhill Market (he randomly shows up) you can buy portal seeds.\n\nQuoted from 5.1 patch notes\n•A new Seed has been added: Portal Shards\n•A mage who fell on hard times back in Dalaran has found a new home on Pandaria. (NPC #67565) will occasionally visit Halfhill Market to peddle a new type of seed – and take advantage of the Tillers’ hospitality.\n•Portal Shards grow into consumable items which can be used to open a portal from Sunsong Ranch to a major faction city.",
            date = "2012-11-27T15:24:09-06:00",
            sourceUrl = "https://www.wowhead.com/quest=32189#comments:id=1768864",
        },
    },
    [32198] = {
        {
            id = 1770506,
            score = 30,
            author = "Oriden",
            text = "As with all drug dealers, the first one is free.",
            date = "2012-11-28T18:24:06-06:00",
            sourceUrl = "https://www.wowhead.com/quest=32198#comments:id=1770506",
        },
        {
            id = 1762040,
            score = 19,
            author = "Chuffy",
            text = "https://www.wowhead.com/npc=67565 is occasionally present at Halfhill. On days when he is he'll be standing facing a table between https://www.wowhead.com/npc=58716 and https://www.wowhead.com/npc=64395. Testing on various characters at various rep levels suggests that you will not be able to get the quest, nor buy the shards until you are Revered with the Tillers. (Much like Songbell seeds)\n\nAt revered or higher https://www.wowhead.com/npc=58718 will give you the quest https://www.wowhead.com/quest=32189 asking you to speak with the visiting Mage.\n\nCompleting https://www.wowhead.com/quest=32198 with https://www.wowhead.com/npc=67565 awards an https://www.wowhead.com/item=91806 which you can plant on your farm in Halfhill to produce the following...\n\nhttps://www.wowhead.com/item=91850\nhttps://www.wowhead.com/item=91860\nhttps://www.wowhead.com/item=91861\nhttps://www.wowhead.com/item=91862\nhttps://www.wowhead.com/item=91863\nhttps://www.wowhead.com/item=91864\nhttps://www.wowhead.com/item=91865\nhttps://www.wowhead.com/item=91866\n\nYou will, of course, only be able to grow portals for your own faction.\n\nEvery shard you plant will take the normal amount of time to grow, just like other seeds. Each one will need to be clicked on to stabilise it resulting in a https://www.wowhead.com/npc=67543 appearing, once defeated the shard will be able to grow.\n\nQuoted from 5.1 patch notes\n•A new Seed has been added: Portal Shards\n•A mage who fell on hard times back in Dalaran has found a new home on Pandaria. https://www.wowhead.com/npc=67565 will occasionally visit Halfhill Market to peddle a new type of seed – and take advantage of the Tillers’ hospitality.\n•Portal Shards grow into consumable items which can be used to open a portal from Sunsong Ranch to a major faction city.\n\nNote the occasionally. You'll want to stock up on https://www.wowhead.com/item=91806s when https://www.wowhead.com/npc=67565 shows up to cover you for days when he doesn't, since https://www.wowhead.com/npc=58718 doesn't sell this type of 'seed'.",
            date = "2012-11-13T20:19:10-06:00",
            sourceUrl = "https://www.wowhead.com/quest=32198#comments:id=1762040",
        },
        {
            id = 1827354,
            score = 8,
            author = "285173",
            text = "...is a magical, mist-shrouded kingdom's trash, as well.",
            date = "2013-03-12T09:09:37-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32198#comments:id=1827354",
        },
        {
            id = 1809164,
            score = 6,
            author = "techkyle",
            text = "Okay, uh, guy. I'm here in Darnassus. I grew your shard and it worked, now what's the next part of the quest?\n\n...hello?",
            date = "2013-02-04T16:46:13-06:00",
            sourceUrl = "https://www.wowhead.com/quest=32198#comments:id=1809164",
