    [32208] = {
        {
            id = 1835281,
            score = 8,
            author = "515557",
            text = "The entrance to the mine is at 75.9 54.2\n\nMetal Lord Mono-Han is right outside the mine.  If he's not there, you may have to wait for a respawn.\n\nThe drills are inside, coords are:\n\nWestern:  48.0 30.5 (this one's tough kinda, keep heading west down a small tunnel and you'll find it)\n\nCentral:  49.2 26.8  (take a left on the way in and it's down that ramp on the right)\n\nEastern:  52.7 24.1 (just as you enter the mine on the right)\n\nEDIT: Go up the stairs behind Arcweaver Jor'guva located at 55.3 44.8",
            date = "2013-03-27T12:39:22-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32208#comments:id=1835281",
        },
