    [32209] = {
        {
            id = 1894641,
            score = 15,
            author = "Sasmina",
            text = "I can't be the only one to hate that you can't spin around while channeling the thing ._.",
            date = "2013-09-10T15:40:55-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32209#comments:id=1894641",
        },
        {
            id = 1851557,
            score = 12,
            author = "CannedJuice",
            text = "It seems to be that using the Arcane Emancipator will be interrupted if any changes are made to your character. Such as leaving combat, or buffs fading or being applied.",
            date = "2013-05-09T14:56:05-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32209#comments:id=1851557",
        },
        {
            id = 1993228,
            score = 8,
            author = "LeFortuneCookie",
            text = "The entirety of this quest happens in the Lightning Vein Mines.  The mine entrance is located at 49.19, 33.05\n\nOnce inside the scouts are easy to spot due to their chat bubbles. Stand underneath scouts and use your emancipator.",
            date = "2014-08-18T20:32:43-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32209#comments:id=1993228",
        },
        {
            id = 1796442,
            score = 7,
            author = "Snowwyte",
            text = "There doesn't appear to be quest markers for this on the map - but I found the Lord Mono-Han wandering around The Thunder Forges (just east of the Cave entrance on the map)\n\nThe scouts are in the cave (called Ghostly Veins) they appear to be hanging from chains on the ceiling, to free them you have to use the item uninterrupted for several seconds",
            date = "2013-01-11T07:38:58-06:00",
            sourceUrl = "https://www.wowhead.com/quest=32209#comments:id=1796442",
