        },
    },
    [32212] = {
        {
            id = 5879734,
            score = 15,
            author = "depthbomb",
            text = "When doing this quest during Remix on my monk, I noticed that when I got on the mount it flew extremely slowly. I left the scenario (with /run C_PartyInfo.LeaveParty() because I couldn't right-click my portrait to leave) to retry it a few times with the same results.\n\nI suspected it either had something to do with the https://www.wowhead.com/spell=157411 talent OR not waiting for dialogue to finish before hopping on the mount. So I removed the talent and waited for dialogue before hopping on the mount and it flew at normal speed.",
            date = "2024-06-12T14:53:32-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32212#comments:id=5879734",
        },
        {
            id = 1827593,
            score = 13,
            author = "guatafu",
            text = "You must complete this in a single run, logging out for more than 10 minutes will send you back to your Hearthstone and you have to start over from the ship.",
            date = "2013-03-12T16:41:57-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32212#comments:id=1827593",
        },
        {
            id = 1846138,
            score = 12,
            author = "Darneas",
            text = "Only did this once but Scout Captain Elsia was either bugged or is the worst helper of all time. She didn't do anything to help with fighting any bad guy and halfway through she just decides I'm going to just stand right here while you go and do the rest of the scenerio. Have fun because I'm not moving.",
            date = "2013-04-23T05:52:10-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32212#comments:id=1846138",
        },
        {
            id = 1826814,
            score = 8,
            author = "Taramina",
            text = "There are four phases to this. Use every opportunity for rest to regain health and allow your special attacks to cool down. The final phase: heed the warning to stay inside the bubble. The waves of light that the mask puts out are ferocious. You will take damage inside the bubble, but it's survivable. Time taking potions or using Life Spirits so that you can heal multiple times. If you die, allow your CDs to reset again before launching into the fight.",
            date = "2013-03-11T12:53:05-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32212#comments:id=1826814",
        },
        {
            id = 1829569,
            score = 7,
            author = "Secundus",
            text = "If you die, the NPC keeps fighting him, so run back fast - I died around 10% and she'd gotten him down to around 5% by the time I ran back, so I still managed to get the kill",
            date = "2013-03-16T09:26:57-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32212#comments:id=1829569",
        },
    },
    [32213] = {
        {
            id = 1931919,
            score = 4,
            author = "Rankkor",
            text = "This is one of those quests were I usually end up killing up to triple the quota of mobs required at no extra cost.\n\nMy only regret is that Jaina is phased out for horde players making her unkillable. Ohh well at least I got Vereesa (http://imgur.com/wVJFF6p) down. Its only a matter of time before I bring Jaina to justice too.",
            date = "2014-01-05T12:55:29-06:00",
            sourceUrl = "https://www.wowhead.com/quest=32213#comments:id=1931919",
        },
        {
            id = 1829563,
            score = 3,
            author = "222390",
            text = "Love the quest text on this one. Damn the Jaina!",
            date = "2013-03-16T09:14:38-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32213#comments:id=1829563",
        },
        {
            id = 2028158,
            score = 1,
            author = "DarkDestroyer",
            text = "As of 6.0.2, it appears that these PvP dailies no longer award honor points. So for those who wanted some old PvP transmogs without having to queue for BG's, it seems that you must queue for BG's now.",
            date = "2014-11-12T01:02:45-06:00",
