    [32216] = {
        {
            id = 2251611,
            score = 143,
            author = "ZeeStorm",
            text = "Don't kill the 4 Zandalari Arcweaver's too quickly. The Skycreamer needs to be \"caught\" by the Beastcaller on the roof for you to get credit. If you kill each one before \"engaging\", you will not get credit and have to wait again.",
            date = "2015-09-12T18:38:13-05:00",
