            author = "Pinkushitsu",
            text = "If you're high level and having trouble with this one try using the toy https://www.wowhead.com/item=137663 on the last https://www.wowhead.com/npc=69224 in able to trigger https://www.wowhead.com/npc=69266 to cast his beam. When the beam is active, kill the last https://www.wowhead.com/npc=69224.",
            date = "2020-01-09T14:40:57-06:00",
            sourceUrl = "https://www.wowhead.com/quest=32216#comments:id=3180676",
