    [32219] = {
        {
            id = 1811354,
            score = 5,
            author = "Calesta",
            text = "Some of the guardians simply crumble; others you have to fight.  If you're able to target them after 'destroying' the statue, then prepare for combat!",
            date = "2013-02-09T13:51:06-06:00",
            sourceUrl = "https://www.wowhead.com/quest=32219#comments:id=1811354",
        },
        {
            id = 1823249,
            score = 2,
            author = "Eillesthis",
            text = "This is the Horde version.  If you're having trouble finding enough of these guys, check around the elevated sides and back of the two large side by side crypts within the quest area.",
            date = "2013-03-06T23:27:49-06:00",
            sourceUrl = "https://www.wowhead.com/quest=32219#comments:id=1823249",
        },
        {
            id = 1823339,
            score = 2,
            author = "Karma99",
            text = "Another problem with finding the  guardians, they are not the size you are used to for Quillen, they're kind of tiny, smaller than your character. Throw in all the wandering mobs in the area and you will struggle to see them most of the time, the glow effect they have is similarly small.",
            date = "2013-03-07T02:03:39-06:00",
            sourceUrl = "https://www.wowhead.com/quest=32219#comments:id=1823339",
        },
        {
            id = 1907913,
            score = 2,
            author = "Vitesse",
            text = "Ignore the comments that say this quest is bugged, cause it's certainly not. Just be sure that you are NOT mounted or pacified from the moment you pick up the quest till you deliver it.\n\nPick up the quest > move a few yards to the mining area > click a stoned Goblin > deliver it > turn in the quest!",
            date = "2013-10-12T10:05:05-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32219#comments:id=1907913",
        },
        {
            id = 1837818,
            score = 1,
            author = "1107558",
            text = "Working as of 4/1/2013 on Horde at least, seems to no longer be bugged",
            date = "2013-04-01T22:01:07-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32219#comments:id=1837818",
        },
    },
    [32220] = {
        {
            id = 1834469,
            score = 4,
            author = "MilesMcStyles",
            text = "Screw you, Silver Covenant goons. Remember Dalaran when a mogu tears your tortured soul out of your screaming body.\n\nGood thing there will be alliance heroes to save the ones you dismissed, you hateful swine.",
            date = "2013-03-25T22:59:36-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32220#comments:id=1834469",
        },
        {
            id = 1833650,
            score = 2,
            author = "440396",
            text = "The quest does not discriminate between Sunreaver and Silver Covenant prisoners, which means you can save any mix of both and complete it.\n\nWhat's interesting is that, in the same way as https://www.wowhead.com/quest=30322, it offers you an opportunity to behave in-character without giving up the reward !\nHorde or Alliance, it matters not.\nWell, maybe it does to me...\n\nSo, to paraphrase my Blood Elf mage, who will rescue six Sunreaver scouts :\nScrew you, Silver Covenant goons. Remember Dalaran when a mogu tears your tortured soul out of your screaming body.",
            date = "2013-03-24T11:36:15-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32220#comments:id=1833650",
        },
    },
    [32224] = {
        {
            id = 1822597,
            score = 3,
            author = "wFPwnz",
            text = "There is a spot of these right around 35.00, 60.00 (Behind the temple) that 7 - 15 of these spawn at. People don't frequently go there so you can complete this quest in under a minute if you're lucky rather than having to compete for mobs with other players.\n\nI've uploaded a Video of the location on Youtube, check it out at http://www.youtube.com/watch?v=xjop55zX1OA",
            date = "2013-03-06T10:40:14-06:00",
            sourceUrl = "https://www.wowhead.com/quest=32224#comments:id=1822597",
        },
        {
            id = 1822580,
            score = 1,
            author = "BananaStalker",
            text = "Was unsure what to look for at first, but these guys resembles the Unleashed Spirits (http://www.wowhead.com/npc=65935) you kill for this Golden Lotus daily quest (http://www.wowhead.com/quest=31757) at the Golden Stairs in Vale of Eternal Blossoms. They seem to come in packs of 3-5 and are fairly easy to kill.",
            date = "2013-03-06T10:24:03-06:00",
            sourceUrl = "https://www.wowhead.com/quest=32224#comments:id=1822580",
        },
        {
            id = 1822598,
            score = 1,
            author = "Funkeeh",
            text = "Annoying quest for melee. They seem to mostly spawn at places, like on top of walls etc., where only ranged can reach them",
            date = "2013-03-06T10:40:17-06:00",
            sourceUrl = "https://www.wowhead.com/quest=32224#comments:id=1822598",
        },
    },
    [32225] = {
        {
            id = 1824569,
            score = 6,
            author = "752459",
            text = "The entrance to the western crypt is 34, 58.6 at the Court of Bones. Go all the way down the stairs and at 33, 56.4 you'll find the lightning rod. Kill the 4 Thundercallers and you should get credit for stopping the ritual.",
            date = "2013-03-08T12:51:43-06:00",
            sourceUrl = "https://www.wowhead.com/quest=32225#comments:id=1824569",
        },
        {
            id = 1822352,
            score = 5,
            author = "RobDBlackwolf",
            text = "The objective of this is at the basement of the Hall of Defamed (the western crypt), at the end of the hallway .\nHorde player can see it south of the Initial point, and only a short swim is needed to reach it, if such a shortcut is desired.",
            date = "2013-03-06T07:00:19-06:00",
            sourceUrl = "https://www.wowhead.com/quest=32225#comments:id=1822352",
        },
    },
    [32226] = {
        {
            id = 1821558,
            score = 43,
            author = "strickn",
            text = "The entrance to the Hall of the Exalted is located at:\n\n/way 36.33 58.85 Hall of the Exalted\n\nI found this YouTube Video (http://www.youtube.com/watch?v=QSnky7Jcoso) really helpful finding the entrance to this as well.",
            date = "2013-03-05T18:11:23-06:00",
            sourceUrl = "https://www.wowhead.com/quest=32226#comments:id=1821558",
        },
        {
            id = 1825035,
            score = 10,
            author = "aslaja",
            text = "Gura the Reclaimed is located in the Hall of the Exalted. On the Court of Bones, face south and go up the long stairs. There is a shrine on each side of the stairs - Hall of the Exalted on the left side and Hall of the Defamed on the right side. (On the map, the shrines (crypts) are depicted as two little square buildings, from this point of view the HoE is the on the right side, of course.)\n\nThe boss is summoned using the scroll at the very bottom of the crypt, you don't have to summon it yourself to get credit for the kill.",
            date = "2013-03-09T03:03:14-06:00",
            sourceUrl = "https://www.wowhead.com/quest=32226#comments:id=1825035",
        },
        {
            id = 1821461,
            score = 4,
            author = "Taliesen",
            text = "The quest marker is a little misleading. You need to go inside the Hall of the Exalted (entrance is enormous and within line of sight of the quest marker) and follow the stairs down into the last room. Use the item there and Gura will spawn.",
            date = "2013-03-05T17:22:35-06:00",
            sourceUrl = "https://www.wowhead.com/quest=32226#comments:id=1821461",
        },
        {
            id = 1916780,
            score = 4,
            author = "DELcroutonza",
            text = "This is the most important part of the quest:  As soon as you have summoned her, you must jump up on top of one of the many stone coffins laying around.  If you do this then her only attack -- electrify the ground -- will do zero damage to you.  If you do this it is a cakewalk, if you don't, you stand a good chance of dying.",
            date = "2013-11-10T14:00:11-06:00",
            sourceUrl = "https://www.wowhead.com/quest=32226#comments:id=1916780",
        },
        {
            id = 1821592,
            score = 3,
            author = "1010670",
            text = "Patch 5.2 - even though you use the Incantation of Gura, the boss seems to be on a timer so just wait for her to spawn, it is not bugged which is what we were thinking since she did not come out right away.",
            date = "2013-03-05T18:42:35-06:00",
            sourceUrl = "https://www.wowhead.com/quest=32226#comments:id=1821592",
        },
    },
    [32227] = {
        {
            id = 1825888,
            score = 8,
            author = "1075988",
            text = "You simply have to be in combat with a mob while being near an hatchling to scare them\n\ntook me a while to understand that, sadly there were no comments about that here, so here it is",
            date = "2013-03-10T07:57:09-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32227#comments:id=1825888",
        },
        {
            id = 1811324,
            score = 6,
            author = "Calesta",
            text = "Frightening a blue hatchling skyscreamer will reward you the Blue Response (http://ptr.wowhead.com/achievement=8112) achievement.",
            date = "2013-02-09T12:39:13-06:00",
            sourceUrl = "https://www.wowhead.com/quest=32227#comments:id=1811324",
        },
        {
            id = 1826096,
            score = 3,
            author = "ggregt",
            text = "You have to ride through them, or move through them. I only found success mounted. Fighting near them doesn't seem to do anything, so it's a lot of BMX trix on your sweet sweet mount.",
            date = "2013-03-10T13:39:18-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32227#comments:id=1826096",
        },
        {
            id = 1833170,
            score = 1,
            author = "schwinn125",
            text = "I just did this quest today and i didn't have to be in combat to frighten them, just get close enough to them and they run in fear.",
            date = "2013-03-23T09:04:38-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32227#comments:id=1833170",
        },
        {
            id = 1860979,
            score = 1,
            author = "JDLKY",
            text = "Getting to the right place can be a problem. The best way imo is to go thru the area where you find Zur'chaka the Bonecrafter. You will need to kill one skeletal dragon and and then proceed forward on the right side when the path is clear of skeletal anklebiters. Go halfway beteeen the elites on your right and Zur'chaka untill you hit the water swim right and you are there.",
            date = "2013-05-31T19:49:22-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32227#comments:id=1860979",
        },
    },
    [32228] = {
        {
            id = 1842479,
            score = 16,
            author = "MasterCaprius",
            text = "Simple solution. Drag him into the Shadow-Pan. They killed him for me.",
            date = "2013-04-13T03:40:26-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32228#comments:id=1842479",
        },
        {
            id = 1827213,
            score = 8,
            author = "LostDrewid",
            text = "A bit nonplussed that this is a daily; I hope it's just one quest from a large pool, but today is the first day it unlocked on my server happily, it is by no means guaranteed to come up daily.\n\nDied twice to the https://www.wowhead.com/npc=69406 so far.  Both times to https://www.wowhead.com/spell=140427.  The problem is, Acidic Regurgitation is a cone attack and leaves a graphic on the ground as he channels the attack... and neither time was I anywhere near that graphic.  The second time, he never even turned, but the attack followed me nonetheless.  Either way, it ticks for about 150k and will hit you several times if you stand in it, so if it *is* a bug [and not lag or anything else], then this daily is going to be difficult to solo.\n\nThankfully as Horde, I have a graveyard very close by.  {And if you're Alliance, why are you here? Your quest is thataway (http://www.wowhead.com/quest=32574) :D}\n\nETA: As I noted above, this daily doesn't show up every day.  As of this current edit today is day 5 of Stage 2 on my server, and we've seen this quest twice.  There are four hubs available during stage 2, of which only three are chosen; and even if Diremoor is one of today's hubs, there are other quests that can fill this daily's \"slot\".  And, given the information in EnviiThelnsane's post, as the Isle progresses we'll see even more hubs, reducing the chances even further.  As NeonKitten mentioned in a reply below, this quest is even harder for melee.  Unfortunately, if the quest *is* one of the day's dailies, you have to complete it if you wish to get the final reward bag... which among other things has a [low but non-existent] chance of dropping a https://www.wowhead.com/item=94222.  I can't speak for any server but my own, but there still seems to be a great deal of camaraderie on the Isle; hopefully it won't be hard to group up for this particular quest.\n\nOn a personal note, I am curious if anyone else is having the same problem I have with this quest, that the breath seems to follow me even when the Devilsaur does not turn in my direction.\n\nETA²: I was on hiatus for several months, and the first day I went back to the Isle, this was a daily.  I nearly cried, since it was late in the week and the Isle was pretty empty.  I thought about trying the kiting-to-the-Shado-Pan trick I'd read, but I figured, alright, lemme at least give him one chance first.  I didn't see any of the bugs I saw the first ten times I did this daily -- I never took unnecessary damage, so I'm willing to guess now that the damage zone and the visual for said zone actually line up finally!  Happy day!",
            date = "2013-03-12T03:17:34-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32228#comments:id=1827213",
        },
        {
            id = 1842230,
            score = 8,
            author = "1038791",
            text = "Best to skip this one if you're melee and alone. Not worth the aggravation and repair bills for a daily quest.",
            date = "2013-04-12T10:12:47-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32228#comments:id=1842230",
        },
        {
            id = 1845266,
            score = 6,
            author = "Garmheim",
            text = "I eventually abandoned this quest after 4 attempts to solo the Mighty Devilsaur. That had a great deal to do with the fact that it was 5:00 A. M. server time and I was very tired but the issue was really not any of his attacks. All of those attacks were relatively easy to avoid. In none of my attempts was I in danger of dying. The problem I encountered repeatedly was the Devilsaur resetting. His Vile Spit begs for kiting but as I kited him along the path he would simply turn around at some point and walk away. I followed, hitting him with Ice Lance but he never turned back to me and after 10 or 15 seconds was back at 100% health. I encountered these resets regardless of where I started the fight.\n\nThe Mighty Devilsaur tracks along the main circular path of Diremoor from southeast to northwest with the midpoint being the wide, paved avenue from the central temple into the Thunder King's Palace. The first time I picked him up I was close to the avenue on the northwest side and moved to the northwest. When he turned away and began tracking back to the southeast and then reset I figured that I may have kited him out of his zone so I restored my health and met him about half way in his path northwest of the avenue. This time he reset at about the midpoint of his track on the southeast side of the avenue well within his track. The next two attempts had the same result regardless of where I started the fight. He reset at 14%, 38%, 54% and 21% which didn't provide much information either. If I could establish a pattern I might have given the quest another try but I still have no idea what caused those resets. I suspect that there's a glitch which has been covered up by his being killed by groups who get his health to zero before the reset.",
            date = "2013-04-20T15:06:09-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32228#comments:id=1845266",
        },
        {
            id = 1852734,
            score = 3,
            author = "Draugrs",
            text = "Ok I solo'd this with my Ret Paladin using the Shado Pan Assault just outside the cave.  Kite him to the entrance of the cave and Shado Pan will start attacking him.  Do not go in the cave or he will reset.  All you have to do is stay out of his acidic regurg (yellow stuff in front of him).  I DPS'd him slightly and mainly just ran around staying away from his acidic stuff while Shado Pan did him in for me.  Extremely easy doing it this way.  Good luck everyone!",
            date = "2013-05-13T13:20:28-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32228#comments:id=1852734",
        },
    },
    [32230] = {
        {
            id = 1826996,
            score = 10,
            author = "318012",
            text = "Soloable. Don't be put off by the \"elite\" marking, level, or the health bar. Run behind him when he's casting, and obviously when the ground starts to rumble/smoke, clear out and return after the ground \"explodes\". If you avoid those two main spells you don't take much damage and can get it down quickly.",
            date = "2013-03-11T18:33:07-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32230#comments:id=1826996",
        },
    },
    [32232] = {
        {
            id = 1831995,
            score = 42,
            author = "Masterbiker",
            text = "If you don't have a dispel for Guardian Tak'u's heal (Waves of the Hydra (http://www.wowhead.com/spell=137465)), kill the Priest of the Hydra (http://www.wowhead.com/npc=69568) first.\n\n(edit: grammar)",
            date = "2013-03-20T19:48:30-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32232#comments:id=1831995",
        },
        {
            id = 1832712,
            score = 7,
            author = "unholydriver",
            text = "This quest is solo-able. Use whichever interrupt spell you have only when it tells you to or you will die. Bliz has set his major casts for all classes so you are allowed just enough time in between. If you're having a hard time use a flask like that your spec calls for and bring a good potion (healing (http://www.wowhead.com/item=76097) and maybe one with the 25 second buff like Vermin's Bite (http://www.wowhead.com/item=76089/virmens-bite)).\n\nHe is surrounded but four priests. I recommend killing the Priest of the Hydra first and it's a bit of pick-your-poison if you get the chance to attack another. The priests that were not pulled will disappear. After that, he comes to life and you can fight him.\n\nStay moving and do so especially if you see anything under you other than concrete. The reason why Guardian Tak'u (http://www.wowhead.com/npc=69336) is difficult is because of the fact that you have to constantly and quickly keep moving out of his casting areas.\n\nThese are the links to the priests and their corresponding buffs to Tak'u:\n\nPriest of the Hawk (http://www.wowhead.com/npc=69570) buffs Blessing of the Hawk (http://www.wowhead.com/spell=137293)\nPriest of the Serpent (http://www.wowhead.com/npc=69567) buffs Blessing of the Serpent (http://www.wowhead.com/spell=137290)\nPriest of the Direhorn (http://www.wowhead.com/spell=137291) buffs Blessing of the Direhorn (http://www.wowhead.com/spell=137291)\nPriest of the Hydra (http://www.wowhead.com/npc=69568) buffs Blessing of the Hydra (http://www.wowhead.com/spell=137292)\n\nTak'u, himself casts Gusts of the Hawk (http://www.wowhead.com/spell=137466), Lightning Strike (http://www.wowhead.com/spell=136730), Waves of the Hydra (http://www.wowhead.com/spell=137465), Wrath of the Direhorn (http://www.wowhead.com/spell=137464).\n\nGood luck and don't give up!",
            date = "2013-03-22T08:10:56-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32232#comments:id=1832712",
        },
        {
            id = 1834812,
            score = 7,
            author = "Azvolrien",
            text = "Hunters, I recommend killing the Hydra and Serpent priests first - you can avoid the Direhorn spell easily enough and the Hawk spell didn't seem to hit too hard, but the other two are annoying if you don't have Silencing Shot.",
            date = "2013-03-26T15:46:54-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32232#comments:id=1834812",
        },
        {
            id = 1836098,
            score = 1,
            author = "1017531",
            text = "This quest is technically soloable, but he does ridiculous damage and requires timing your interrupts at the exact right time, or you get killed.\n\nThe quest text really should include a warning about this guy and his buffs.  I went in having no idea what to do, and got completely obliterated.  SOmeone in my guild explained how it worked, which is nice because the quest text offered jack @#$%.",
            date = "2013-03-29T04:58:21-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32232#comments:id=1836098",
        },
        {
            id = 1847153,
            score = 1,
            author = "geekygirlish",
            text = "As  lock, I just thought this was a kill the casting dudes and he releases.  Managed to kill two and the fight was easy, just let big blue kill him and I stood up on the rocks, nuked him, and never took any damage. The tornados didn't reach me. Very simple.  Next day did again, two other random joined in, and couldn't figure out why he kept healing!  No dispels really with voidwalker so ran away and read this thread. Thank you!  I was just lucky the first time to pick the hydra priest by accident.  Kept thinking I swear I solo'd this guy easily yesterday and three of us can't take him down now.  Duh, easy when you know how",
            date = "2013-04-26T11:23:18-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32232#comments:id=1847153",
        },
    },
