    [32252] = {
        {
            id = 1821822,
            score = 8,
            author = "merpy",
            text = "Note that you're not looking for a mob called \"Harbinger of the Loa,\" you're looking for Zandalari Arcanitol (http://www.wowhead.com/npc=69281), Zandalari Spiritweaver (http://www.wowhead.com/npc=69285), or Zandalari Speaker (http://www.wowhead.com/npc=69136). They show up as skulls on your minimap and spawn at (33.2, 73.6) and (33.6, 71.2).\n\nETA: True, you don't have to kill two different ones, you can just wait for it to respawn. Right now, at the start of Patch 5.2, they respawn really quickly.",
            date = "2013-03-05T21:18:24-06:00",
            sourceUrl = "https://www.wowhead.com/quest=32252#comments:id=1821822",
        },
        {
            id = 1823294,
            score = 6,
            author = "CaptainCrowbar",
            text = "You don't have to kill both of them. Killing the same one twice will also successfully complete the quest. They respawn fairly quickly.",
            date = "2013-03-07T01:09:40-06:00",
            sourceUrl = "https://www.wowhead.com/quest=32252#comments:id=1823294",
        },
    },
    [32254] = {
        {
            id = 1821545,
            score = 15,
            author = "cogar",
            text = "Speak with Magister Arlan:\n45.0, 83.8\nI was looking for him in a cave but he was outside and the bubble appears as i ran over the area.\n\nSpeak with Magister Sarien:\n51.4, 85.12\nin a cave\n\nSpeak with Magistrix Vesara:\n51.8, 73.8\nup a ramp wandering around on the platform",
            date = "2013-03-05T18:02:53-06:00",
            sourceUrl = "https://www.wowhead.com/quest=32254#comments:id=1821545",
        },
        {
            id = 1794420,
            score = 7,
            author = "Calesta",
            text = "Magister Yalis - SW corner near (46.6, 81.0).\n\nMagister Lyanis - Cave on the south side with an entrance near (51.6, 84.4).\n\nMagistrix Sanal - Using the entrance closest to the Alliance base, take the first ramp to the right up.  You'll find a small area with several caves near (52.3,75.3).\n\nFor those who just quickly glance at the quest description, it's important to note that the shields used to cloak the magisters will remove your Saurok disguise.  The shield also silences you.  Be prepared for combat once you step outside the shield until your Saurok disguise is restored.",
            date = "2013-01-07T17:53:18-06:00",
            sourceUrl = "https://www.wowhead.com/quest=32254#comments:id=1794420",
        },
        {
            id = 1827695,
            score = 1,
            author = "seitori",
            text = "Daily Quest: The Sarien (http://www.wowhead.com/npc=69309) Encounter.",
            date = "2013-03-12T21:06:41-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32254#comments:id=1827695",
        },
    },
    [32255] = {
        {
            id = 1821502,
            score = 24,
            author = "Jmech1986",
            text = "Needs to be pointed out that even though you may see a gear icon on your mini map doesnt mean that there's anything there. I thought daily might have been glitchy because i was standing on top of the symbol on the map but didnt see anything. Maybe it's a red herring, idk, but if you follow the coordinates Calesta wrote above you'll get to the right locations.",
            date = "2013-03-05T17:38:44-06:00",
            sourceUrl = "https://www.wowhead.com/quest=32255#comments:id=1821502",
        },
        {
            id = 1795460,
            score = 19,
            author = "Calesta",
            text = "Disabled Construct - SW corner near where Magister Yalis patrols (44.1,81.7)\n\nBuried Construct - S beach (at or around 53.4, 90.6, seems to be multiple locations)\n\nDistressed Construct - Runs around the camp (near the pits, up to where Magistrix Sanal patrols, etc.)\n\nMalfunctioning Construct - NW Saurok camp near (46.6, 72)",
            date = "2013-01-09T17:43:07-06:00",
            sourceUrl = "https://www.wowhead.com/quest=32255#comments:id=1795460",
        },
        {
            id = 1824505,
            score = 10,
            author = "440396",
            text = "All constructs say a few lines when you recover them, some of them humorous.\n\nDisabled Sunreaver Construct says:\nPOWERING ON...\nLOCATION UNRECOGNIZED. RETURNING TO LAST KNOWN BASE LOCATION.\n\nEXECUTING GRATITUDE PROTOCOL.\n\"THANK YOU\"\n\nMalfunctioning Sunreaver Construct says:\nREBOOTING...\nSYSTEM ONLINE. FEELING MUCH BETTER NOW.\n\nATTEMPTING TO RECOVER FROM EMBARASSING MALFUNCTION...\nRECOVERY FAILED. INCREMENTING SHAME PARAMETER. RETURNING TO BASE.\n\nDistressed Sunreaver Construct says:\nATTEMPTING TO DESTROY MEMORY RECORDS OF PREVIOUS 6 HOURS.\nMEMORY RECORDS DESTROYED. WHO ARE YOU. RETURNING TO BASE.\n\nWARNING. MANA FLOW RATE STILL ELEVATED.\nATTEMPTING MANA FLOW RATE REDUCTION OVERRIDE PROTOCOL.\n\"EVERYTHING IS OK\"\n\"EVERYTHING IS ALRIGHT\"\n\" WILL MAKE IT ALL BETTER\"\nMANA FLOW RATE NOMINAL. RETURNING TO BASE.\n\nBuried Sunreaver Construct says:\nEXECUTING SANDS EXTRACTION PROTOCOL.\n*The construct proceeds to repeatedly blast the sand trapping it*\n\nLEG FAILURE LOOP BROKEN. RETURNING TO BASE.",
            date = "2013-03-08T11:15:55-06:00",
            sourceUrl = "https://www.wowhead.com/quest=32255#comments:id=1824505",
        },
        {
            id = 1823198,
            score = 7,
            author = "Snuggly",
            text = "Tom Tom way points thanks Calesta (http://www.wowhead.com/user=Calesta)\n\n/way Isle of Thunder 44.1 81.7 Disabled Construct\n/way Isle of Thunder 53.4 90.6 Buried Construct\n/way Isle of Thunder 51, 74 Distressed Construct\n/way Isle of Thunder 46.6 72 Malfunctioning Construct",
            date = "2013-03-06T22:06:29-06:00",
            sourceUrl = "https://www.wowhead.com/quest=32255#comments:id=1823198",
        },
        {
            id = 5452080,
            score = 5,
            author = "ekrietlow",
            text = "Doing dailies in 9.2.7 my Distressed Construct was at\n/way 49, 84 Distressed Construct\n\nand was half stuck in the ground not moving around at all.  When clicked, he dropped below the ground but did count.",
            date = "2022-10-15T08:01:18-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32255#comments:id=5452080",
        },
    },
    [32262] = {
        {
            id = 1828743,
            score = 14,
            author = "Chilblainrdm",
            text = "While you can free the captive while mounted this does not currently dismiss the rune trap.  Because the rune trap does not disappear the captive is not respawning.  I tested this on a few runes and by dismissing the rune trap it forced the captive respawn in about a minute.  Unfortunately you have to dismount to dismiss the rune.  This has been my experience and could use some more corroboration.",
            date = "2013-03-14T20:49:17-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32262#comments:id=1828743",
        },
        {
            id = 1840712,
            score = 3,
            author = "Rendran",
            text = "I have to laugh at how angry the Magister gets when they've got Kirin Tor captives stuck around their base too.",
            date = "2013-04-08T17:48:00-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32262#comments:id=1840712",
        },
        {
            id = 1827872,
