    [32265] = {
        {
            id = 1834759,
            score = 18,
            author = "Opher",
            text = "When you're close to a https://www.wowhead.com/object=218192 a cogwheel will appear on your minimap, therefore it might be easier to simply keep your eyes on the minimap since the item itself is rather small and easy to miss.\n\nThe https://www.wowhead.com/object=218192 is blue and shining.\n\nIf you're carrying the item and die, the item will disappear and you will have to find it again.\n\nUsing either https://www.wowhead.com/item=95568 or https://www.wowhead.com/item=95567 will not work, instead a message will tell you that \"the item is not ready\".\n\nMounting up works.",
            date = "2013-03-26T13:41:57-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32265#comments:id=1834759",
        },
        {
            id = 1827086,
            score = 10,
            author = "HelloKitty",
            text = "I don't think it's intentional, but today (3/11) when my realm unlocked this daily, I mounted with the Moganite and did not drop it.\n\nAlso, in order to 'complete' this quest you actually have to walk to ~melee range of the questgiver (in this case, https://www.wowhead.com/npc=67662).",
            date = "2013-03-11T21:04:37-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32265#comments:id=1827086",
        },
        {
            id = 1850530,
            score = 7,
            author = "Nandaria",
            text = "You can still use https://www.wowhead.com/item=95568 while carrying the Charged Moganite. To do so, pick up the moganite after you've finished the other quests or drop it (rightclick your buff or use /cancelaura) and pick it up again. While picking it up (which has a ~1 sec cast time), use the teleporter item. You just have to be fast enough.",
            date = "2013-05-06T08:00:17-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32265#comments:id=1850530",
        },
        {
            id = 1814678,
