    [32268] = {
        {
            id = 1830628,
            score = 18,
            author = "834801",
            text = "There are 3 alliance ships in the bay around the Violet Rise, 2 to the north and 1 to the south.  Each ship has the bomb placement located in different areas of their outer hull.\n\nThe northernmost one has it on the front left side (port bow), in the middle of the metal part.\n\nThe other ship on the north side, just to the east of the first, has the bomb placement on the back left (port stern). You can barely see it sticking out of the small metal band that runs around the waterline of the ship.\n\nThe easiest one to see is the southern ship. The bomb placement is clearly visible on the front right side (starboard bow) in the middle of the metal part.\n\nThe bomb for the construct ritual is easily seen on the back of the construct's left leg. When you enter the Violet Rise from the Northwest, it's the big blue construct with some alliance npcs channeling into it.\n\nThe one for the supply shipment is actually on the back side of a wall in the valley between the alliance quest-giving area and the mainland near all the peasants running around.  The wall is the chunk of rubble on the right if you're facing the stairs up to alliance quest-giving area.",
            date = "2013-03-18T11:18:38-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32268#comments:id=1830628",
        },
        {
            id = 1811589,
            score = 16,
            author = "Cielos",
            text = "The bomb on the Alliance ship was a little hard to see, but it is located on the front right metal part of the ship.",
            date = "2013-02-09T23:24:51-06:00",
            sourceUrl = "https://www.wowhead.com/quest=32268#comments:id=1811589",
        },
    },
