    [32278] = {
        {
            id = 1838770,
            score = 59,
            author = "deviouskat89",
            text = "On the stage where I had to locate Hu'seng, I walked right up to him, stood on top of him even, yet couldn't get credit.  I'm stuck; ideas?",
            date = "2013-04-04T01:12:44-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32278#comments:id=1838770",
        },
        {
            id = 1838457,
            score = 33,
            author = "243753",
            text = "On the second stage drop bombs along the middle, taking out those Sentry Totems.  That creates the easiest path.  Even if you have to skirt a Sentry zone it doesn't agro you immediately so this is only a minor consideration.\n\nOn the 3rd stage I was unsure what to do.  The action button did not appear, so I had no idea I had to 'sap' the targeted trolls.  I learned that here, and used the Extra Action macro to make an action button.\n\nIf you don't know this one; make a macro with this command\n\n/click ExtraActionButton1\n\nand place the button on your action bar.  When a target appears on a troll, get up close and hit the button.  Retreat to Taoshi's smoke if you don't get them the first time.",
            date = "2013-04-03T11:11:44-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32278#comments:id=1838457",
        },
        {
            id = 2863819,
            score = 26,
            author = "kimbodine",
            text = "You MUST do the stealth sapping with her or else you'll have to start the scenario over. Anyone overgeared, do NOT just one shot the trolls on the ship.",
            date = "2019-01-03T15:35:23-06:00",
            sourceUrl = "https://www.wowhead.com/quest=32278#comments:id=2863819",
        },
        {
            id = 1838541,
            score = 20,
            author = "darkyoshi87",
            text = "the names of the last three stages of the scenario are \"Keep Quiet\", \"Light up the Night\", and \"Breaking Out\" which are all names of songs by the band The Protomen.",
            date = "2013-04-03T13:42:36-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32278#comments:id=1838541",
        },
        {
