    [32304] = {
        {
            id = 2014182,
            score = 2,
            author = "130755",
            text = "If you're getting the chat message \"High Recognition failed.\" continually, zone out of the isle and back to it again. Should work after that.\n\nEDIT: \"High Recognition failed\" has been hotfixed.",
            date = "2014-10-16T14:40:42-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32304#comments:id=2014182",
        },
        {
            id = 1900981,
            score = 1,
            author = "567189",
            text = "This quest used to reward Conquest Points (http://www.wowhead.com/currency=390) above  your weekly Arena/BG cap of 1800 but looks like that has not stopped with the release of Season 14...\n\nNote:  You can do them before you hit 1800 for the week, but after that they are not rewarded.",
            date = "2013-09-21T07:25:29-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32304#comments:id=1900981",
