    [32305] = {
        {
            id = 1829156,
            score = 5,
            author = "415723",
            text = "For those looking for the right thing to click:\n\nThere are three things in this area that are clickable, a pylon with the Kirin Tor symbol, a blue rune on the ground and finally a blue orb placed in a setting about knee high.\n\nTo complete this quest click the knee high blue orbs, the others are not what you are looking for.\n\nThe picture shows a nice example.",
            date = "2013-03-15T11:46:49-05:00",
