    [32461] = {
        {
            id = 5239364,
            score = 13,
            author = "jewelking",
            text = "For those like me who like to do every quest they can on one character, you CAN get this if you already started the order questline,\n\nhow I did it\nExalted with shado-pan\nParty sync with fresh character\nAccept and complete mogu incursions\nAccept and complete Surprise attack!\nUpon completing this it WONT pup up as the questgivers other quests will override its window but will be added to your questlog\n(you can exit party sync here)\nIt will later pop up asking if you want to accept it even though its already in your log\n\n(wish I could credit the people who helped with info, you know who you are!)",
            date = "2021-08-19T16:11:13-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32461#comments:id=5239364",
        },
        {
            id = 2502692,
            score = 11,
            author = "Whiterock",
            text = "This quest is awarded upon looting Cloud Serpents on a character that didn't start [faction=1271] questline.\n\nConfirmed receiving quest upon looting:\nhttps://www.wowhead.com/item=87768\nhttps://www.wowhead.com/item=87775\nhttps://www.wowhead.com/item=87777",
            date = "2017-06-20T16:45:15-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32461#comments:id=2502692",
        },
        {
