    [32468] = {
        {
            id = 2549145,
            score = 22,
            author = "abratis",
            text = "The required quest items drops from Crystal Spine Matriarch.\n\nThe Matriarch is on the Yojamba Isle, at 12.03, 30.44. The mob scales with your level up to 100! I reckon it's easily soloable by any decently geared 110 character but for anyone lower better bring some friends because she's a tough one.\n\nOne thing to note in case you don't see the mob at specified coordinates: If you are on quest [quest=29219 domain=www], Bwemba's spirit will follow you everywhere while in Stranglethorn Vale and for some reason the Matriarch is not visible while Bwemba is around. After waiting for 30 minutes for a respawn for the Matriarch, I got the brilliant idea of abandoning Bwemba's quest and as soon as I did, the Matriarch appeared.",
            date = "2018-01-29T12:53:02-06:00",
            sourceUrl = "https://www.wowhead.com/quest=32468#comments:id=2549145",
        },
        {
            id = 2560262,
            score = 4,
            author = "Kamraten",
            text = "You hand in the quest to the same quest giver https://www.wowhead.com/npc=16926 in Valley of Spirits in the Western part of Orgrimmar.",
            date = "2018-03-29T10:55:06-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32468#comments:id=2560262",
        },
        {
            id = 5532937,
            score = 4,
            author = "daqman247",
            text = "This quest scales with level.\n\nJust received it on my Evoker, the mob to kill for the crystal was a Level 70 Elite with 903k HP.\n\nYou do not need to have Trivial Quests showing to find the NPC with the \"!\" for the Quest.",
            date = "2023-01-22T05:47:06-06:00",
            sourceUrl = "https://www.wowhead.com/quest=32468#comments:id=5532937",
        },
        {
            id = 2554066,
            score = 2,
            author = "l1nka",
            text = "Super easy to solo?  I was prot at the time (paladin), ilvl 928.  I can't figure out who to turn it into now that I'm back in Orgrimmar.",
            date = "2018-02-20T19:16:02-06:00",
            sourceUrl = "https://www.wowhead.com/quest=32468#comments:id=2554066",
        },
        {
            id = 3235060,
            score = 2,
            author = "shatime",
            text = "So if you're like me (i.e: an idiot) and didn't know, this quest not only gives you filters, but it also turns the camera into a proper toy instead of just a usable item...\n\ndon't be like me and run around for ages with this thing taking up a bag slot, just bc you decided you don't care about the filters...",
            date = "2020-10-03T13:22:27-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32468#comments:id=3235060",
        },
    },
    [32469] = {
        {
            id = 2547324,
            score = 10,
            author = "Allureana",
            text = "The \"Level\" for this says \"group\" and means it!  At least as of 7.3.5 with the new auto leveling features, every player who sees her (even while partied!) will be facing off with the matriarch leveled to match EACH PLAYER'S own level!   When you form a group to fight her, choose friends all about the same level so they can all fight her at the same level.  She will have her level matched to each and every player so they will ALL find themselves needing to fight fiercely, even with all heirloom gear. She is, after all, Elite.  Treat her like a dungeon boss and bring along a tank, a couple DPSers, and a healer or two.\nIf you manage to solo her (Paladins welcome to try), feel free to brag about it here, but be sure to ALSO confess how many times you died before you succeeded.",
            date = "2018-01-20T13:54:36-06:00",
            sourceUrl = "https://www.wowhead.com/quest=32469#comments:id=2547324",
        },
        {
            id = 3221202,
            score = 9,
            author = "LotusThorn",
            text = "i went there and saw Arielle Snapflash, she does not have the quest. What did i do wrong ?",
            date = "2020-08-04T21:04:23-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32469#comments:id=3221202",
        },
        {
            id = 5446409,
            score = 9,
            author = "NefariousV",
            text = "If you are unable to see the quest it is likely that you have the Mk 2 camera already and can go and obtain the other lenses from taking selfies with the bosses.\n\nArgus Filter (https://www.wowhead.com/spell=258803/argus-filter) - Argus the Unmaker in Antorus the Burning Throne\nSha Filter (https://www.wowhead.com/spell=258751/sha-filter) - Sha of Fear in the Terrace of Endless Spring.\nFrostmourne Filter (https://www.wowhead.com/spell=258750/frostmourne-filter) - Lich King in IceCrown Citadel\nFirelands Filter (https://www.wowhead.com/spell=258749/firelands-filter) - Ragnaros in Firelands.\nTwilight Filter (https://www.wowhead.com/spell=258752/twilight-filter) - Cho'Gall in the Bastion of Twilight.",
            date = "2022-10-05T16:34:40-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32469#comments:id=5446409",
        },
        {
            id = 2568117,
            score = 5,
            author = "gghf",
            text = "Killing the Matriarch is not that hard, but she is still an Elite a level below yours.\n\nIf you are a class with good sustain, you will have no issues whatsoever. I killed her in short order on my shadow priest without dropping below 90% health, due to Vampiric Touch and PW:Shield.\nHunters and Warlocks will have their pets and health regen, Paladins are unkillable with their cooldowns and selfheals.\n\nIf you do not have an effective way of protecting or sustaining yourself in a fight that will last about 30 to 60 seconds, you will want to bring at least one health potion of the highest quality you can use. Make certain to space out your defensive cooldowns for maximum efficiency. Try timing them such that you can always use one just as she turns back to you after a telegraphed attack.\n\nMake sure to dodge all the telegraphed moves, they give you several huge openings for easy damage, or if you need to cast heals on yourself.\nFinally, you'll want to have your hearthstone off cooldown. She's pretty far out and teleporting home is preferable to walking the entire way back.",
            date = "2018-05-17T02:30:34-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32469#comments:id=2568117",
        },
        {
            id = 2554401,
            score = 4,
            author = "Snikkerz",
            text = "I was able to solo it this morning on my lv 31 Hunter - was a bit tricky though.",
            date = "2018-02-22T16:59:37-06:00",
            sourceUrl = "https://www.wowhead.com/quest=32469#comments:id=2554401",
        },
    },
    [32471] = {
        {
            id = 2549440,
            score = 18,
            author = "1037524",
            text = "The belt is the Russet Belt (http://www.wowhead.com/item=3593/russet-belt) found at the cloth armor vendor Tor'phan (http://www.wowhead.com/npc=3315/torphan) at 60.8 x 59.6, and the scope is the Standard Scope (http://www.wowhead.com/item=4406/standard-scope) made by engineers or rarely found in Box of Assorted Parts (http://www.wowhead.com/object=19019/box-of-assorted-parts). The box meanwhile is the only quest exclusive item, in a crate near the north exit of the city at 61 x 19.6 per the map.\n\nIf you attempt to do this with a starter edition account, get to Bloodmyst, or repeatedly run Deadmines and Gnomeregan till you get the scope.",
            date = "2018-01-31T00:12:25-06:00",
            sourceUrl = "https://www.wowhead.com/quest=32471#comments:id=2549440",
        },
        {
            id = 2863908,
            score = 7,
            author = "Mike21daisu",
            text = "The best way for a starter edition account to get https://www.wowhead.com/item=4406 is to take the zeppelin from Orgrimmar to Stranglethorn Vale, use the Gnomeregan teleport there and just keep killing the trash or skipping them somehow to open the https://www.wowhead.com/object=19019.\n\nThe box is located in 2 places: First one is in the middle, right in front of you up there when you enter the dungeon, you'll usually see the box and a chest to open, not recommended for someone without a stealth or with high skill (if you figure out how to skip certain types of mobs). The 2nd one is the one you wanna go for, it is located right where Grubbis spawns, the first boss of the dungeon (but he's not there because you have to start the encounter, so you're good), go there, clear the trash (or not, depends what you're capable of) and keep opening the box. It took me 40-50 tries, it is 1% after all.\n\nAn efficient way to do this, is to kill the burrowers and skip the casters. You have to worry about 1st 4 encounters. Don't worry about the small non-elite patrolling mobs, those have low damage and die easily. So you're gonna encounter 4 elites. 1 + 1 + 2. first 2 mobs are alone, can pull them separately, the 3rd one is a group of 2, really rarely you can separate them, but don't rely on that. So kill first 2 mobs if either of them is a burrower. Kill all 4 of them if the 2 that are standing together are both burrowers.\n\nAfter this just run through everything and heal yourself on your way to the box, you can normally open the box if you time it well, doable even if 2-3 mobs are hitting you. The casters reset if you take them far way btw, so don't worry about that.",
            date = "2019-01-04T00:40:31-06:00",
            sourceUrl = "https://www.wowhead.com/quest=32471#comments:id=2863908",
        },
        {
            id = 5245003,
            score = 2,
            author = "kashiichan",
            text = "The Self-Enabling Low Focus Image Extractor (S.E.L.F.I.E.) was apparently first introduced in Warlords of Draenor as a garrison mission: \"The selfie camera is a drop from the garrison mission Field Photography (https://www.wowhead.com/mission=501/field-photography). The mission is level 100 and won’t show up until you have a least one level 100 follower. Unfortunately, missions spawn randomly; Field Photography could pop up the first day you have a level 100 follower, or it could take weeks of running missions to get it.\" Thankfully the selfie camera has allegedly moved to Stormwind City and Orgrimmar. For those who never owned it, Arielle Snapflash is supposed to offer the Light Camera Action quest (Alliance (https://www.wowhead.com/quest=32470/light-camera-action) / Horde (https://www.wowhead.com/quest=32471/light-camera-action)), which results in you getting the selfie camera. I left WoW after Cataclysm and came back just before Shadowlands; although I've checking in with Arielle Snapflash often, she doesn't ever have this quest available. Is there another requirement that I'm not aware of? Or am I going to have to play through Warlords of Draenor?",
            date = "2021-08-31T12:44:42-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32471#comments:id=5245003",
        },
        {
            id = 3193567,
            score = 1,
            author = "Wyr3d",
            text = "This quest was not available to my character since I already had both a S.E.L.F.I.E camera and the upgrade from an earlier expansion.  Not really sure when I got them to be honest. I think might have been a W.O.D mission or something? I dunno..\n\nAnyways, you can get this quest by either deleting the stuff, or mailing it to another character (they are account bound items)\n\nEDIT - This may be an account-wide quest, since my alts don't have the quest available either, even without the camera added as a toy.",
            date = "2020-03-06T19:47:39-06:00",
            sourceUrl = "https://www.wowhead.com/quest=32471#comments:id=3193567",
        },
        {
            id = 5795047,
            score = 1,
            author = "thulsadoom",
            text = "Looking to complete \"Take a S.E.L.F.I.E with a Tiara, Top Hat, or Monocle\" and she doesn't have anything for you?\nFind a toon with  head piece with a monocle transmog, and pull out your S.E.L.F.I.E Camera MkII, and snap a selfie. BAM!",
            date = "2024-03-02T17:55:04-06:00",
            sourceUrl = "https://www.wowhead.com/quest=32471#comments:id=5795047",
        },
    },
