    [32505] = {
        {
            id = 1831091,
            score = 457,
            author = "WizzardlordUK",
            text = "There are 4 Start points:\nCourt of Bones 39.11, 56.01 (Next to Tomb)\nZa'Tual 40.66, 71.43 (by tall conrete post)\nIhgaluk Crag 50.18, 85.91 (On Slope)\nConqueror's Terrace 57.45, 46.13 (Behind Tent)\n\nQuest Ends @ Hall of Grand Imperion - Entrance to hall can be found on beach 33.57, 63.14\n\nSpawn points seen so far (will update)\n\nTorso (Court of Bones)\nOn outside wall of building 33.52, 59,98\nOn outside wall of building 34.45, 59.92\nOn Floor 36.28, 48.87\nBack of the large building Mumta spawns atop of 34.90, 66.30\n\nShoulder (Ihgaluk Crag)\nOn Top of Mountain 45.50, 84.36 (get to it from 47.76, 82.82)\nOn Top of Mountain 50.93, 85.38 (get to it from 50.18, 87.44)\nOn Top of Mountain 52.27, 72.78 (get to it from 53.80, 76.28)\nOn Top of Mountain 53.80, 76.28 (get to it from 57.50, 81.45)\n47.57 75.01\n\nStaff ( Za'Tual)\nOn Top of Tent 39.10, 73.52\nOn Side of Mountain 36.91, 75.61 (get to it from 37.33, 76.14)\nOn Top of Tent 35.97, 75.22\nOn top of tent above Couldron 33.67, 67.09\n\nHair (Beast Pens/Conqueror's Terrace)\nOn top of Wall 53.26, 43.09 (get to it from 54.18, 44.40)\nOn Top of Tent round back on rim 53.04, 45.63\nIn Tent Behind Spiritbinder Tu'Chek 59.48, 56.80\nOn Ground 50.14, 40.84\n\nTomTom\n\n/way 39.11, 56.01 Chamberlain Quest Start - (Next to Tomb)\n/way 40.66, 71.43 Chamberlain Quest Start - (by tall conrete post)\n/way 50.18, 85.91 Chamberlain Quest Start - (On Slope)\n/way 57.45, 46.13 Chamberlain Quest Start - (Behind Tent)\n\n/way 33.57, 63.14 Quest End Entrance point on Beach - Turn right once inside (stone statue)\n\n/way 33.52, 59,98 Torso - On outside wall of building\n/way 34.90, 66.30 Torso - Back of the large building Mumta spawns atop of\n/way 34.45, 59.92 Torso - On outside wall of building\n/way 36.28, 48.87 Torso - On Floor\n\n/way 45.50, 84.36 Shoulder - On Top of Mountain\n/way 50.93, 85.38 Shoulder - On Top of Mountain\n/way 52.27, 72.78 Shoulder - On Top of Mountain\n/way 53.80, 76.28 Shoulder - On Top of Mountain\n\n/way 39.10, 73.52 Staff - On Top of Tent\n/way 36.91, 75.61 Staff - On Side of Mountain\n/way 35.97, 75.22 Staff - On Top of Tent\n/way 33.67, 67.09 Staff - On top of tent above Couldron\n\n/way 53.26, 43.09 Hair - On top of Wall\n/way  53.04, 45.63 Hair - On Top of Tent round back on the rim\n/way 59.48, 56.80 Hair - In Tent Behind Spiritbinder Tu'Chek\n/way 50.14, 40.84 Hair - On Ground\n\nYou may also refer to andreipop (Click to see post) (http://www.wowhead.com/quest=32505#comments:id=1834099). The reason i have not added these here is because some of the cords are slightly different to mine but will be the same place. I could test to see which ones overlap...but i dont want to plagurise someone elses work.",
            date = "2013-03-19T07:56:15-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32505#comments:id=1831091",
        },
        {
            id = 1807167,
            score = 436,
            author = "Calesta",
            text = "Upon completion, you'll need to visit the Chamberlain's broken statue in a cave beneath the Court of Bones.  The entrance can be found at 33.6, 63.1.",
            date = "2013-01-31T10:06:49-06:00",
            sourceUrl = "https://www.wowhead.com/quest=32505#comments:id=1807167",
        },
        {
            id = 1795833,
            score = 170,
            author = "Kayorisama",
            text = "These 4 items are spread in 4 areas around the Isle. They aren't always in the same spot and can sometimes be a little difficult to make your way to (i.e. on top of a tent or on top of a mountain). They have a gear over the top of the item so they should be relatively easy to spot, even if they aren't as easy to get to. You will also see a gear icon on your mini map when you are near the object.\n\nEdit:  Source (http://blue.mmo-champion.com/topic/257453-patch-52-hotfixes-march-21/) As of Mar 21, 2013 - Crumbled Chamberlain: Statue pieces now do not despawn when looted, allowing other players to loot the statue piece as well.",
            date = "2013-01-10T08:20:29-06:00",
            sourceUrl = "https://www.wowhead.com/quest=32505#comments:id=1795833",
        },
        {
            id = 2579782,
            score = 125,
            author = "Aladrias",
            text = "For those farming rep, no, this quest does not reward any - it only rewards a ritual stone.",
            date = "2018-07-10T02:38:14-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32505#comments:id=2579782",
        },
        {
            id = 1955657,
            score = 107,
            author = "415824",
            text = "To turn this in, you need to go down to a cave on the beach, whose entrance is at /way 33.59 63.17",
            date = "2014-04-03T13:48:26-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32505#comments:id=1955657",
        },
    },
    [32506] = {
        {
            id = 1826822,
            score = 104,
            author = "Fist",
            text = "There are 2 of them. Both fly in their own little circles to a spot and land for a few secs (TIME TO CLICK THEM), then fly and go to the next spot.\n\nResting spots:\n\n/way 54.7 57.4\n\n /way 45.2 48.7",
            date = "2013-03-11T13:23:00-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32506#comments:id=1826822",
        },
        {
            id = 1827688,
            score = 41,
            author = "Splendid2009",
            text = "I did a \"/tar wild\" and followed the guy until he landed.",
            date = "2013-03-12T20:30:54-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32506#comments:id=1827688",
        },
        {
            id = 1829273,
            score = 13,
            author = "126940",
            text = "The pterrorwings are phased and lootable by multiple people, so you won't have to worry about stealing or getting one stolen from someone nearby/in group.\n\nAlso look for one of the dead beavers (one you haven't killed or is tapped/greyed out) because that's where they land. It's a lot easier than chasing a flying one if you wait near a beaver corpse.",
            date = "2013-03-15T16:12:21-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32506#comments:id=1829273",
        },
        {
            id = 1828382,
            score = 12,
            author = "1106287",
            text = "Every minute one will land at 41.21, 50.10",
            date = "2013-03-14T04:33:04-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32506#comments:id=1828382",
        },
        {
            id = 1828336,
            score = 11,
            author = "701186",
            text = "Simply go to your interface>mouse and set \"click to move\" active. Then look at the sky and when you see him >clickClick. Quest is done :-)",
            date = "2013-03-14T02:36:20-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32506#comments:id=1828336",
        },
    },
    [32507] = {
        {
            id = 1835821,
            score = 23,
            author = "32124",
            text = "This one-time quest seems to appear only when you select the PvE branch, and if the https://www.wowhead.com/quest=32730 daily is available to you. The said daily requires you to go meet https://www.wowhead.com/npc=67660, hidden in a stealth bubble near Ihgaluk Crag.\n\nWhen I got there, I found https://www.wowhead.com/npc=69433 located in the same bubble (46.92, 66.90), and she had this quest available.\n\nNote: I had the same issue as the commenters on this thread: http://www.wowhead.com/quest=32507#comments:id=1831215\nI got back into WoW when Stage 4 just started. For Stage 4, I saw Magistrix Saia at the Sunreaver base, Dawnseeker Promontory (32.78, 32.65), but she didn't have this Skin of the Saurok quest made available. and the https://www.wowhead.com/quest=32730 daily wasn't available for that day.",
            date = "2013-03-28T14:46:58-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32507#comments:id=1835821",
        },
        {
            id = 1828533,
            score = 5,
            author = "NerdEsq",
            text = "Haha. You do not take fall damage when you're in this form. :3",
            date = "2013-03-14T11:33:41-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32507#comments:id=1828533",
        },
        {
            id = 1794712,
            score = 4,
            author = "Calesta",
            text = "This is a 'helper' quest that allows you to the dailies in Ihgaluk Crag a bit easier.  In disguise, mobs in the area will be neutral and not attack you.  You also have the ability to jump much further and higher.\n\nWhen you accept the quest, Mastistrix Saia casts a spell on you that will transform you into Saurok while in Ihgaluk Crag.  Using spells will remove the disguise. Shortly after you're out of combat, the disguise will return.\n\nIt appears you only need to complete this quest once.  The disguise is always available to you on subsequent visits to the Isle.",
            date = "2013-01-08T09:52:20-06:00",
            sourceUrl = "https://www.wowhead.com/quest=32507#comments:id=1794712",
        },
        {
            id = 1955359,
            score = 3,
            author = "698380",
            text = "The Saurok model uses the same animations/skeletal rig as the male Worgen. How you run in this disguise is how the worgen's 'mount' form should run, slowly with grace, not a million steps a second.",
            date = "2014-04-01T19:42:06-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32507#comments:id=1955359",
        },
        {
            id = 1823508,
            score = 2,
            author = "stonegirl11",
            text = "Just a heads up for druids, the disguise is not shapeshift friendly. When you shapeshift, you lose the disguise. When you get out of combat, the disguise will reapply and you will drop form.\n\nFortunately, the disguise reapplying does not break stealth.",
            date = "2013-03-07T07:34:41-06:00",
            sourceUrl = "https://www.wowhead.com/quest=32507#comments:id=1823508",
        },
    },
    [32517] = {
        {
            id = 1822138,
            score = 20,
            author = "569787",
            text = "Entrance to the Hall of the Grand Imperion at 35, 62\n\nStay on the ground floor until 4 Shan'ze Soulripper's spawn channeling energy into an Ancient Stone Conquer. Kill them, when all 4 are dead the Ancient Stone Conquer will crumble and the daily will complete.\n\nNote: If you go up the stairs on the left or right, Mumta the rare spawn is located on the top level (if not already killed).",
            date = "2013-03-06T01:55:26-06:00",
            sourceUrl = "https://www.wowhead.com/quest=32517#comments:id=1822138",
        },
    },
    [32520] = {
        {
