    [32521] = {
        {
            id = 1831655,
            score = 9,
            author = "998027",
            text = "For easy Horde solo:\n\nPull this guy basically straight back, toward Dawnseeker Promontory. At 42.8 42.2, there is a Mana Collector that will give you a Bloodlust buff.\n\nKill his raptor, probably while kiting him toward the mana collector, since it has 78K HP.\n\nOnce you reach the mana collector, use it and if you feel the need, charge the Sunreaver Ward. Also, ~2 horde-side guardians will attack him. Between all of this, the fight becomes trivial.\n\nThe Firespear/Icespear adds will follow you, but the Healer won't so don't worry. Stay out of the icespear/firespear's Line of Sight to avoid the 80K damage magic attacks (They will lock onto your position before firing, and stay locked in that LoS for a few seconds.).\n\nThey're fairly easy to avoid since they usually attack at the same time.",
            date = "2013-03-20T05:50:55-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32521#comments:id=1831655",
        },
        {
            id = 1833054,
            score = 2,
            author = "Snapper",
            text = "You face 5 mobs. 1 prophet (healer) 2 ranged dps, Nurkala, and his raptor.\nI dropped a frost trap on the healer and proceeded to dps Nurkala and his raptor with my pet tanking both. Keep moving out the the flames from the ranged dps. The raptor goes down quick. Nurkala is a tank and spank. If the prophet gets out of the trap he will heal Nurkala for about 25%.",
            date = "2013-03-23T03:12:48-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32521#comments:id=1833054",
        },
    },
    [32522] = {
        {
            id = 1846744,
            score = 1,
            author = "Draewind",
            text = "I was left with the debuff \"Thermal Collapse (http://www.wowhead.com/spell=139645#comments)\" after the fight.  The debuff was endless and did 20k damage per second.  I submitted a bug ticket (it is a bug).  The only way to get rid of it is to let it kill you.  It is gone once you rez.",
            date = "2013-04-25T05:19:21-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32522#comments:id=1846744",
