    [32526] = {
        {
            id = 1824891,
            score = 7,
            author = "1089937",
            text = "Alliance and Horde players can free prisoners of either faction be it sunreaver scouts or silver covenant scouts. Opposing faction escapees will be not very grateful but it still counts for the quest!  The prisoners are located in cages around the court of bones, the cages are the same color as the nearby stone and if u aren't looking you could miss them, but keep an eye out and they are easy to find then just click and FREEDOM!",
            date = "2013-03-08T21:32:57-06:00",
            sourceUrl = "https://www.wowhead.com/quest=32526#comments:id=1824891",
        },
        {
            id = 1824357,
            score = 5,
            author = "334587",
            text = "As horde, you can free either sunreaver or silver convent scouts. If you free silver convent ones, they throw insults at you once you free them. You can kill them, but showing that your not the ^&*!@#bag they claim you to be just shows them up as asshats.",
            date = "2013-03-08T07:12:10-06:00",
            sourceUrl = "https://www.wowhead.com/quest=32526#comments:id=1824357",
        },
        {
            id = 1826138,
            score = 2,
            author = "Crusaderwolf",
            text = "Sometimes, if you free the alliance scouts as horde, they will say things along the lines of \"I'll let you live for now\" and \"Even though we are enimies, I am thankful you saved me but don't expect mercy the next time we meet\".",
            date = "2013-03-10T14:41:52-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32526#comments:id=1826138",
        },
        {
            id = 1825063,
            score = -3,
            author = "968833",
            text = "When the Silver Covenant said \"Death to the horde\" and ran off i swore i will never free one of them ever again even if it means me having to take longer to do the daily!",
            date = "2013-03-09T03:52:27-06:00",
            sourceUrl = "https://www.wowhead.com/quest=32526#comments:id=1825063",
        },
    },
    [32527] = {
        {
            id = 1828586,
            score = 1,
            author = "Lovestorybro",
            text = "Try to fight the Shan'ze Gravekeepers for this quest.  They do an uninteruptable cast that spawns a blue rune on the ground.  Pull them a few yards away so they walk out of the rune and run into it yourself.  It gives you a buff that increases your critical chance by 100%.  If you have the other quest for this area to kill the Risen Ancestors, you can pull a Gravekeeper in order to get this buff to increase your dps against these mobs as well.",
            date = "2013-03-14T13:47:47-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32527#comments:id=1828586",
        },
    },
    [32528] = {
        {
            id = 1821557,
            score = 111,
            author = "strickn",
            text = "The entrance to the Hall of the Exalted is located at:\n\n/way 36.33 58.85 Hall of the Exalted\n\nI found this YouTube Video (http://www.youtube.com/watch?v=QSnky7Jcoso) really helpful finding the entrance to this as well.",
            date = "2013-03-05T18:10:46-06:00",
            sourceUrl = "https://www.wowhead.com/quest=32528#comments:id=1821557",
        },
        {
            id = 1821599,
            score = 35,
            author = "Itchy118",
            text = "Here is what the entrance to the Halls of the Exalted looks like:\nhttp://i.imgur.com/hgjaQhQ.jpg\n\nAnd here is where you can find her inside the halls:\nhttp://i.imgur.com/VUhqG1F.jpg",
            date = "2013-03-05T18:49:16-06:00",
            sourceUrl = "https://www.wowhead.com/quest=32528#comments:id=1821599",
        },
        {
            id = 1821952,
            score = 21,
            author = "Ashymer",
            text = "once you are downstairs remember to use \"Incantation of Gura\"  on the big tomb",
            date = "2013-03-05T23:12:22-06:00",
            sourceUrl = "https://www.wowhead.com/quest=32528#comments:id=1821952",
        },
        {
            id = 1830742,
            score = 4,
            author = "620618",
            text = "How to find it!\n\nThe image by itchy118 is great---but beware, there are 2 halls next to each other, and they both have identical looking entrances.  One is the Hall of the Defamed---you don't want this one.  Come out the door and turn right----go into that hall, the Hall of the Exalted.  Then:\n\n---Go down stairs, short left, and another short left, both of them a few stairs.\n\n----Turn right into a ruined hallway/tunnel (the floor paving ends).  The tunnel turns to the left and you find yourself in a long room with paving stones again.\n\n---In the room there is an exit to the right.  Go through this ---and stop.  You're looking right at the spot you need to summon the mob.",
            date = "2013-03-18T15:31:24-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32528#comments:id=1830742",
        },
        {
            id = 1873553,
            score = 2,
            author = "stickshift",
            text = "She's a caster and pretty easy with interrupts, here's her muscle (http://www.wowhead.com/npc=69241#abilities).",
            date = "2013-07-04T10:46:00-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32528#comments:id=1873553",
        },
    },
    [32529] = {
        {
            id = 1824468,
            score = 13,
            author = "1104954",
            text = "The entrance to The Hall of the Defamed is located at (34.01,59.01).  You ritual you need to interupt is at the end of this hall.",
            date = "2013-03-08T10:36:49-06:00",
            sourceUrl = "https://www.wowhead.com/quest=32529#comments:id=1824468",
        },
        {
            id = 1837338,
            score = 8,
            author = "Gymlea",
            text = "Go south from the quest giver. Then up the slope to the west and through the breech in the wall. Turn immediately right and go north to the end of the low wall on your left. Turn left. You are going to the second small building, shown on your mini-map as a light brown square. Go west past the steps to the first small building, across the plaza leading to the big building behind the small ones, and on to the second set of steps on your left. Turn left up the stairs and into the building. Down the stairs and through all rooms to the far end where there is a breech in corner with a pole. There will be 1 to 4 MOBs with lighting to the pole. Kill them all.",
            date = "2013-03-31T21:01:40-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32529#comments:id=1837338",
        },
        {
            id = 1828701,
            score = 5,
            author = "LuckyGhoul",
            text = "There is another daily \"kill summoners, stop ritual\" quest like this. Don't confuse the two because they don't take place in the same temple.",
            date = "2013-03-14T19:01:19-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32529#comments:id=1828701",
        },
        {
            id = 1826074,
            score = 3,
            author = "scottiegazelle",
            text = "Go down the stairs and wind your way through the hallway around the crumbled walls. There's a broken wall leading outside with a giant pole in the middle. If you are fortunate, you'll see the four guys you need to kill to interrupt the ritual channeling the pole; however, if it's the daily (which is probably why you're doing it), there's a good chance they've been killed. Just wait by the giant fancy pole.",
            date = "2013-03-10T12:59:04-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32529#comments:id=1826074",
        },
    },
    [32530] = {
        {
            id = 1801083,
            score = 6,
            author = "Calesta",
            text = "In the northernmost building in the Court of Bones.  Entrance at (35,49).",
            date = "2013-01-19T14:13:18-06:00",
            sourceUrl = "https://www.wowhead.com/quest=32530#comments:id=1801083",
