    [32531] = {
        {
            id = 1823365,
            score = 15,
            author = "243447",
            text = "This quest takes place on the first floor. There is no need to go upstairs. Kill the 4 Shan'ze Soulrippers performing the ritual on the giant statue and you are done. You will get credit for the quest even if you join another player who is already attacking them. You can also attack one Shan'ze Soulripper at a time and do this quest alone; just don't aggro the other mobs.",
            date = "2013-03-07T02:43:27-06:00",
            sourceUrl = "https://www.wowhead.com/quest=32531#comments:id=1823365",
        },
        {
            id = 1823073,
