            author = "Maregolden",
            text = "The entrance to the Hall of the Grand Imperion is at 35.11, 61.23 in the Court of Bones.",
            date = "2013-03-06T19:09:49-06:00",
            sourceUrl = "https://www.wowhead.com/quest=32531#comments:id=1823073",
        },
    },
    [32532] = {
        {
            id = 1822246,
            score = 5,
            author = "Linako",
            text = "Found it very hard to find them as all were killed alreday. A little tip - they walk mainly on the edges of the walls.",
            date = "2013-03-06T04:38:56-06:00",
            sourceUrl = "https://www.wowhead.com/quest=32532#comments:id=1822246",
        },
        {
            id = 1822579,
            score = 1,
            author = "BananaStalker",
            text = "Was unsure what to look for at first, but these guys resembles the Unleashed Spirits (http://www.wowhead.com/npc=65935) you kill for this Golden Lotus daily quest (http://www.wowhead.com/quest=31757) at the Golden Stairs in Vale of Eternal Blossoms. They seem to come in packs of 3-5 and are fairly easy to kill.",
            date = "2013-03-06T10:23:28-06:00",
            sourceUrl = "https://www.wowhead.com/quest=32532#comments:id=1822579",
        },
    },
    [32533] = {
        {
            id = 1826907,
            score = 11,
            author = "975146",
            text = "If you're having trouble finding these, a good spot is right outside the room where you summon Gura for https://www.wowhead.com/quest=32528 which is often but not always given along with this quest. There are three of the statues right outside the room in which you summon Gura and their respawn time is pretty quick.\n\nYou can also get a quick 55 rep with the Black Prince each time someone kills Gura by hitting her at least once.",
            date = "2013-03-11T15:41:13-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32533#comments:id=1826907",
        },
        {
            id = 1811352,
            score = 9,
            author = "Calesta",
            text = "Some of the guardians simply crumble; others you have to fight.  If you're able to target them after 'destroying' the statue, then prepare for combat!",
            date = "2013-02-09T13:50:18-06:00",
            sourceUrl = "https://www.wowhead.com/quest=32533#comments:id=1811352",
        },
        {
            id = 1823251,
            score = 9,
            author = "Eillesthis",
            text = "This is the Alliance version.  If you're having trouble finding enough of these guys, check around the elevated sides and back of the two large side by side crypts within the quest area.",
            date = "2013-03-06T23:28:31-06:00",
            sourceUrl = "https://www.wowhead.com/quest=32533#comments:id=1823251",
        },
        {
            id = 1831430,
            score = 9,
            author = "tworley210",
            text = "This thing must be glitched.  The grave guardians do nothing when clicked.  not multiple times not right, not left nothing.  They dont react.  Help!",
            date = "2013-03-19T19:01:13-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32533#comments:id=1831430",
        },
        {
            id = 2300043,
            score = 2,
            author = "Missy198501",
            text = "I just attempted this quest and I also had trouble \"Destroying\" the Guardians\n\nI found out my issue was I was always trying to attack them (to destroy them) , all I had to do was right click on the guardian and they would either crumble or turn hostile and then can easily be destroyed.\n\nHope it helps someone :)",
            date = "2016-01-19T23:07:35-06:00",
            sourceUrl = "https://www.wowhead.com/quest=32533#comments:id=2300043",
        },
    },
    [32535] = {
        {
            id = 1822377,
            score = 4,
            author = "hmrhead",
