            date = "2013-03-06T07:33:30-06:00",
            sourceUrl = "https://www.wowhead.com/quest=32535#comments:id=1822377",
        },
    },
    [32536] = {
        {
            id = 1821682,
            score = 23,
            author = "1045272",
            text = "Magistrix Sanal is not in the cave, although the white dialog icon seems to indicate he should be.  He is actually up above the cave.",
            date = "2013-03-05T19:52:37-06:00",
            sourceUrl = "https://www.wowhead.com/quest=32536#comments:id=1821682",
        },
        {
            id = 1822640,
            score = 7,
            author = "unpwnt",
            text = "Magister Yalis - Walking around the circle @ 46,81\nMagister Lyanis - Cave @ 51,84\nMagistrix Sanal - Walking around the circle (Above the cave) @ 52,75\n\nLook for the light beacons on the floor (About 10 foot wide), once you walk into them you can talk to the NPC.",
            date = "2013-03-06T11:22:25-06:00",
            sourceUrl = "https://www.wowhead.com/quest=32536#comments:id=1822640",
        },
        {
            id = 1793226,
            score = 6,
            author = "Calesta",
            text = "Magister Yalis - SW corner near (46.6, 81.0).\n\nMagister Lyanis - Cave on the south side with an entrance near (51.6, 84.4).\n\nMagistrix Sanal - Using the entrance closest to the Alliance base, take the first ramp to the right up.  You'll find a small area with several caves near (52.3,75.3).\n\nFor those who just quickly glance at the quest description, it's important to note that the shields used to cloak the magisters will remove your Saurok disguise.  The shield also silences you.  Be prepared for combat once you step outside the shield until your Saurok disguise is restored.",
            date = "2013-01-05T17:52:50-06:00",
            sourceUrl = "https://www.wowhead.com/quest=32536#comments:id=1793226",
        },
    },
    [32537] = {
