    [32538] = {
        {
            id = 3197727,
            score = 124,
            author = "Grimphog",
            text = "/way Isle of Thunder 33.9 76.1 Cha'lat's Altar\n/way Isle of Thunder 39.8 65.2 Tec'uat's Altar\n/way Isle of Thunder 38.7 78.6 Pa'Check's Altar",
            date = "2020-04-03T18:25:02-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32538#comments:id=3197727",
