    [32540] = {
        {
            id = 1821813,
            score = 12,
            author = "merpy",
            text = "Note that you're not looking for a mob called \"Harbinger of the Loa,\" you're looking for Zandalari Arcanitol (http://www.wowhead.com/npc=69281), Zandalari Spiritweaver (http://www.wowhead.com/npc=69285), or Zandalari Speaker (http://www.wowhead.com/npc=69136). They show up as skulls on your minimap and spawn at (33.2, 73.6) and (33.6, 71.2).\n\nETA: You don't have to kill two different ones, you can just wait for it to respawn. Right now, at the start of Patch 5.2, they respawn really quickly.",
            date = "2013-03-05T21:16:03-06:00",
            sourceUrl = "https://www.wowhead.com/quest=32540#comments:id=1821813",
        },
        {
            id = 1849943,
