    [32541] = {
        {
            id = 1811323,
            score = 13,
            author = "Calesta",
            text = "Frightening a blue hatchling skyscreamer will reward you the Blue Response (http://ptr.wowhead.com/achievement=8112) achievement.",
            date = "2013-02-09T12:38:23-06:00",
            sourceUrl = "https://www.wowhead.com/quest=32541#comments:id=1811323",
        },
        {
            id = 1823308,
            score = 6,
            author = "Dolorus",
            text = "To do this quest you simply run \"throught\" the birds while being in combat with the npcs there. Took me 1-2 mobs to get them all, then again there was no one questing at the time. Good luck.",
            date = "2013-03-07T01:29:44-06:00",
            sourceUrl = "https://www.wowhead.com/quest=32541#comments:id=1823308",
        },
        {
            id = 1823809,
            score = 3,
            author = "232709",
            text = "This quest is fairly easy if you just aggro one of the trolls in the area (or one of the nearby crabs if you can't find any trolls) and then just drag it to a hatchling and execute an attacking move.  You may need to be fairly close to a hatchling in order to frighten it, though for some of the ones perched above you, fighting below it will suffice to frighten it.",
            date = "2013-03-07T14:23:17-06:00",
            sourceUrl = "https://www.wowhead.com/quest=32541#comments:id=1823809",
        },
        {
            id = 1824181,
            score = 3,
            author = "230961",
            text = "Can be done when in Stealth, rogues are also able to use Shadowstep on the hatchlings that are flying and scare them.",
