    [32545] = {
        {
            id = 1829726,
            score = 9,
            author = "shoutingboy",
            text = "There's a priest who's outside on a wide ledge (EDIT: That's at 49.9,76.1)--that's much easier to kill than the ones in the caves. (You have room to maneuver,  so you can get away from the https://www.wowhead.com/spell=138481. Plus he doesn't have companions.)",
            date = "2013-03-16T15:23:47-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32545#comments:id=1829726",
        },
        {
            id = 1824490,
            score = 2,
            author = "Eclipsegirl",
            text = "I found the brute pretty easy, and did the sea dragon with another person, but it didnt seem too hard.\nOn the next day, I got the same quest, the same daily, the sea dragon and the brute are not difficult.\n\nThe saur-priest is not easy.\n\nThere are two adds protecting it.\n\nThe priest lifts you up and keep putting you in dangerous ?electricity.\n\nI died twice.\n\nAfter the first death, I was able to take down one add.\n\nIt made the fight a tad easier.\n\nI wish I had tactics to share, but at this point teaming with someone is my best advice.\n\n--------EDIT---------------------------------\nI have come across two caves where there is only one add protecting the priest.\nOne is a deep cave with two adds at the mouth of the cave.\n\nI can take the priest when there is only one add.\nI concentrate all my DPS on the preist.\nAfter the priest is gone, I then work on the add.",
            date = "2013-03-08T11:01:39-06:00",
            sourceUrl = "https://www.wowhead.com/quest=32545#comments:id=1824490",
        },
        {
            id = 1829557,
            score = 2,
            author = "Ringthane",
            text = "Just another horrible quest from the Blizzard designers.  Guess they forgot that melee classes exist in this game.  The priest is horribly difficult if you aren't ranged - you might as well just park yourself in the cave and wait for someone to come along.  It only took nine years, but Blizzard finally decided the Everquest \"camp it until there's more people\" way of designing mobs and quests was a good thing.\n\nJust skip it.",
            date = "2013-03-16T09:04:30-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32545#comments:id=1829557",
        },
        {
            id = 1826340,
            score = 1,
            author = "MarsJenkar",
            text = "When you kill these mobs, you share the kills with anyone who manages to do enough damage to tap them.  This is a very good thing.",
            date = "2013-03-10T22:24:06-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32545#comments:id=1826340",
        },
        {
            id = 1846847,
            score = 1,
            author = "795658",
            text = "The Saur-Priest that I found in a cave was guarded by a Filthmonger, a Scavenger and a Fleshripper at the front of the cave.  The Saur-Priest did not show up at first on the screen as it is further back in the cave.  Once you kill the three in the front of the cave, go just a bit further back in the cave and you'll find the Saur-Priest there guarded by another Skumblade.  This cave was on the first level of Ighaluk Crag as you enter, just to the west side of the \"lake,\" and close to a puddle with Quivering Filth.",
            date = "2013-04-25T12:19:48-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32545#comments:id=1846847",
        },
    },
    [32546] = {
        {
            id = 1826948,
            score = 11,
            author = "Maruset",
            text = "So, based on the animations while fighting these things, you are literally beating the S--t out of them...",
            date = "2013-03-11T17:12:01-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32546#comments:id=1826948",
        },
        {
            id = 1793231,
            score = 5,
            author = "Calesta",
            text = "There is a buff on each of the Quivering Filth that shows how many pieces of filth is carried by the mob. Elite mobs carry more filth.",
            date = "2013-01-05T17:59:16-06:00",
            sourceUrl = "https://www.wowhead.com/quest=32546#comments:id=1793231",
        },
        {
            id = 1821782,
            score = 2,
            author = "Aislinge",
            text = "The Elite carries 40-50 'filth' approximately.\n\nCan easily be killed by a 460 geared level 90.\n\nAs you need 75 'filth' to finish the daily, killing two of these is far quicker than killing the babies which only grant varying amounts of lower 'filth'.\n\nGenerally, the bigger the mob looks, the more filth it carries.",
            date = "2013-03-05T21:03:18-06:00",
            sourceUrl = "https://www.wowhead.com/quest=32546#comments:id=1821782",
        },
        {
            id = 1839539,
            score = 2,
            author = "unholydriver",
            text = "I'm not sure why the screenshot shows one that's a bit of a semi-translucent blue. They're an olive-y color and they have 'eyes' and a 'mouth.'",
            date = "2013-04-05T21:12:27-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32546#comments:id=1839539",
        },
    },
    [32547] = {
        {
            id = 1822903,
            score = 20,
            author = "Fizzbangree",
            text = "There are spots where 20-30 of these will spawn at a time and you can smoosh a bunch at once instead of hunting down singles.  Here's a couple waypoints I added to a roach macro to find 'em quick.  Good hunting!\n\n/way 51.96 78.86 roach1\n/way 50.38 83.56 roach2\n/way 54.47 81.28 roach3\n/way 47.24 80.61 roach4",
            date = "2013-03-06T15:52:47-06:00",
            sourceUrl = "https://www.wowhead.com/quest=32547#comments:id=1822903",
        },
        {
            id = 2016367,
            score = 17,
            author = "Danemy",
            text = "After patch 6.0.2 it seems like you have to step on the roaches more than once in order to kill them, and not all of them count towards the objective.",
            date = "2014-10-20T08:24:56-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32547#comments:id=2016367",
        },
        {
            id = 1824907,
