        {
            id = 3306742,
            score = 7,
            author = "nirv",
            text = "Don't remember doing this quest back in the day but still bugged as of 2021-03-07. For every 10-15 I crush I get credit for 1. Thanks Blizzard. You sure are the kings of time vampirism.",
            date = "2021-03-07T09:18:23-06:00",
