        },
        {
            id = 1793194,
            score = 6,
            author = "Calesta",
            text = "No need to target the roaches individually or attack.  Simply walk/run over them and you're credited for the 'crush'.\n\nNear the entrance, you'll find a few here and there scampering around.  As you get further into Ihgaluk Crag, you'll find large groups of them that make the quest go a lot faster.",
            date = "2013-01-05T17:19:18-06:00",
            sourceUrl = "https://www.wowhead.com/quest=32547#comments:id=1793194",
        },
