    [32549] = {
        {
            id = 1824644,
            score = 93,
            author = "Scolex",
            text = "YOU'RE A LIZARD, HARRY!",
            date = "2013-03-08T14:37:15-06:00",
            sourceUrl = "https://www.wowhead.com/quest=32549#comments:id=1824644",
        },
        {
            id = 1835677,
            score = 39,
            author = "32124",
            text = "This one-time quest seems to appear only when you select the PvE branch, and if the daily https://www.wowhead.com/quest=32732 is available to you. The quest requires you to go meet https://www.wowhead.com/npc=67996, hidden in a stealth bubble near Ihgaluk Crag.\n\nWhen I got there, I found https://www.wowhead.com/npc=69678 located in the same bubble (55.61, 74.13), and he had this quest available.\n\nNote: I had the same issue as the two commenters on this thread: http://www.wowhead.com/quest=32549#comments:id=1833669\nI got back into WoW when Stage 4 just started. For Stage 4, I saw Image of Archmage Vargoth at the Kirin Tor Assault base, Violet Rise (64.13, 73.91), but he didn't have this Skin of the Saurok quest made available.",
            date = "2013-03-28T06:55:58-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32549#comments:id=1835677",
        },
        {
            id = 1793201,
            score = 35,
            author = "Calesta",
            text = "This is a 'helper' quest that allows you to the dailies in Ihgaluk Crag a bit easier.  In disguise, mobs in the area will be neutral and not attack you.  You also have the ability to jump much further and higher.\n\nWhen you accept the quest, Archmage Vargoth casts a spell on you that will transform you into Saurok while in Ihgaluk Crag.  Using spells will remove the disguise. Shortly after you're out of combat, the disguise will return.\n\nIt appears you only need to complete this quest once.  The disguise is always available to you on subsequent visits to the Isle.",
            date = "2013-01-05T17:28:24-06:00",
            sourceUrl = "https://www.wowhead.com/quest=32549#comments:id=1793201",
        },
        {
            id = 1821510,
            score = 20,
            author = "979563",
            text = "You can talk to Saurok with this on, they're rather funny actually.",
            date = "2013-03-05T17:42:46-06:00",
            sourceUrl = "https://www.wowhead.com/quest=32549#comments:id=1821510",
        },
        {
            id = 1821440,
            score = 16,
            author = "941372",
            text = "For \"Pet Classes\" (Hunters, Locks, etc) if you have your pet out, they get Turned into a Blob.",
            date = "2013-03-05T17:08:28-06:00",
            sourceUrl = "https://www.wowhead.com/quest=32549#comments:id=1821440",
        },
    },
    [32550] = {
        {
            id = 1999632,
            score = 5,
            author = "1366759",
            text = "The quest turn in shows up on the left side of the beast pens but in fact you turn it in where Elisa is.",
            date = "2014-09-05T07:13:01-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32550#comments:id=1999632",
        },
        {
            id = 1794132,
            score = 3,
            author = "rodmin",
            text = "Just a tip for players who are new around these parts.\n\nDon't ever, EVER say / think / read this quest's title while Saurfang (http://ptr.wowhead.com/npc=25256) is around.\n\nTrust me on this one, unless you really want to die in a most gruesome, \"cleaving\" way.",
            date = "2013-01-07T06:31:57-06:00",
            sourceUrl = "https://www.wowhead.com/quest=32550#comments:id=1794132",
        },
        {
            id = 1832711,
            score = 1,
            author = "1046261",
            text = "Careful, the raptors hurt pretty bad (90-114kdamage on their leap), so I don't recommend aoeing them. Also, look out for the direhorns. if you accidentally agro one of them, there is a good chance your gonna die.",
            date = "2013-03-22T07:57:37-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32550#comments:id=1832711",
        },
        {
