        },
    },
    [32551] = {
        {
            id = 1832814,
            score = 11,
            author = "Mendric",
            text = "Current compy spawn rate makes this quest suck ball bags. Huge, hairy, ball bags.\nWhat? You were expecting tips for this quest? Nothing to say other than submit a suggestion to blizz to test their crap once in a while :)",
            date = "2013-03-22T13:14:56-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32551#comments:id=1832814",
        },
        {
            id = 1835841,
            score = 6,
            author = "StubMcBean",
            text = "If you are on this quest, don't confuse Trained Compy (http://www.wowhead.com/npc=58071) with Loa-Infused Compy (http://www.wowhead.com/npc=69311). They look identical, but the Loa-Infused version don't give credit for this quest. The Loa-Infused ones are only found with a Loa Speaker (http://www.wowhead.com/npc=69302).",
            date = "2013-03-28T15:40:34-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32551#comments:id=1835841",
        },
        {
            id = 1883470,
            score = 1,
            author = "torin23",
            text = "There are now lots and lots and lots of Trained Compies to kill.  I probably killed between 20 and 30 by the time I was done with the area.\n\nNote that the riding raptors (Tamed BladeTalon (npc=69180)) count for the Raptors slain as well.",
            date = "2013-08-03T01:55:43-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32551#comments:id=1883470",
        },
    },
    [32552] = {
        {
            id = 1832855,
            score = 13,
            author = "1108164",
            text = "Ignorance, at times, truly is bliss. Tried to kill him and got owned, lol. So I started on the other quests.\nAt co-ords 50,44 is another one, less his mount, and I didn't even know that I killed him until I got the \"Quest is Complete\" message.\n\nFor those without co-ords, that is the first tent on the left north west of the quest givers bubble.",
            date = "2013-03-22T15:04:50-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32552#comments:id=1832855",
        },
        {
            id = 1832069,
            score = 12,
            author = "Iceveiled",
            text = "The guy you want to kill is the loa speaker, riding his loa-infused bladetalon. He stalks around a small area by a small building. Clear the area of adds, especially the guy by the small building and his dino mini pets.\n\nSpeaking for hunters, he will ignore your pet's aggro and suddenly leap at you, hitting like a truck (I was 480 geared as of this writing and was being hit for more than 2/3 of my health - over 200,000k). I died 3 times trying to down him. Either bugged or in-line with a lot of the other 5.2 dailies: needlessly annoying. (I'm going with the latter as this is Troll content afterall)\n\nThere's probably some mechanic to make the fight easier (or not?), but I'm an impatient pew-pewer so after ONLY 3 attempts, of which I'm ashamed to admit,  I blew all my cooldowns, shouted some choice words at my screen, and killed him.\n\nThe ground was littered with the skeletons of others so I hung around for a few minutes and helped out some others and did my good deed for the day.\n\nGood Luck, and may you more cerebral adventurers add your strategies below. :)",
            date = "2013-03-20T23:59:24-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32552#comments:id=1832069",
        },
        {
            id = 1832143,
            score = 6,
            author = "821417",
            text = "If you are a ranged class. run up the stairs to the emperor's Gate to the landing where Archweaver Jor'guva is standing. run up to the ledge and position yourself at approx coords 53,45. Hang out for a about 20-30 sec and you should see the Speaker pat around and get within your striking distance. Without leaving the ledge attack his raptor first, the raptor will evade bug and freeze in place (this is so he doesnt jump on you) after that just target the Speaker and he goes down really easy.",
            date = "2013-03-21T03:36:50-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32552#comments:id=1832143",
        },
        {
            id = 1832128,
            score = 5,
            author = "fiannagarou",
            text = "I kited him, away from his direhorn. After dying probably 4 times.\nThe Direhorn's slow. So you shouldn't have any problems keeping ahead of it and moving the speaker to a better spot. Depending on where you are, I kited back toward the quest giver-bubble. So once I got the Loa Speaker down, I ducked into the bubble, and the Direhorn 'lost' me.\n\nGood luck!",
            date = "2013-03-21T03:09:09-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32552#comments:id=1832128",
        },
        {
            id = 1832838,
            score = 5,
            author = "1108155",
            text = "I got this quest for the first time on my mage today.  I think I have a 480ish ilvl, and don't play the toon often or well.  First time I tried to kill him somebody was already on him so I started casting from range.,  Seemed logical.  While I was running back I looked at the existing comments.\n\nInstead of trying to kite him, I blinked onto him immediately, then started my normal rotation.  As I guessed, he and his raptor never jumped at me, never hit me for a massive amount.  He only knocked me down about half way before I killed him and his mount.  I recommend running up to him before pulling.",
            date = "2013-03-22T14:04:01-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32552#comments:id=1832838",
        },
    },
    [32553] = {
        {
            id = 1833478,
            score = 29,
            author = "Gervahlt",
            text = "The Defiant Devilsaur (http://www.wowhead.com/npc=67477) is located at 53.88, 42.97 and the Defiant Direhorn (http://www.wowhead.com/npc=69277) is located at 52.08, 33.23.  The mission's objective is not to try to kill the dino; instead, it's to kill the NPCs around it.\n\nIf they do not spawn around the first one you go to, you need to go to the other one and you'll find them there.  They swap back and forth between the two.\n\nEdit: spelling",
            date = "2013-03-24T00:47:49-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32553#comments:id=1833478",
        },
        {
            id = 1831336,
            score = 8,
            author = "Eclipsegirl",
            text = "Go near the western steps and you will find a defiant direhorn or defiant devilsaur.\n\nI found the direhorn.\n\nKill the npcs.  It is easy to get them one by one.",
            date = "2013-03-19T15:17:59-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32553#comments:id=1831336",
        },
        {
            id = 1837370,
            score = 5,
            author = "1110132",
            text = "Is that alright to give the word \"NPCs\" directly in the description? Maybe kinda too Straightforward imo.",
            date = "2013-03-31T23:51:54-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32553#comments:id=1837370",
        },
        {
            id = 1840392,
            score = 3,
            author = "MarsJenkar",
            text = "As Li Li might put it, this can only end in comedy.  At the Zandalari's expense, of course.",
            date = "2013-04-08T00:06:13-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32553#comments:id=1840392",
        },
        {
            id = 1967031,
            score = 3,
            author = "Yogilaw",
            text = "This is pretty obvious to anyone who has been a 90 for some time, but anyway: DO NOT use aoe on this quest! You can pick off the single NPC's easily by just moving close to them. If you upset the big guy you is gonna get squished quicker than a bug at a barn dance.\nJust move round the targets one at a time, it's as easy as that. When the last one is killed the Dino will break free & rumble off.",
            date = "2014-05-22T11:31:54-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32553#comments:id=1967031",
        },
    },
    [32554] = {
        {
            id = 1831335,
            score = 10,
            author = "Eclipsegirl",
            text = "I hate not knowing what to do\n\nKill trolls in the area.\nSome of them drop saur fetishes\nWhen you come across a raptor, even with a rider, or other animals target the raptor and click on the fetish.\n\nIt is easiest to do after collecting 5 fetishes, and then go into the pens, and then use them on the raptors in the pens",
            date = "2013-03-19T15:15:11-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32554#comments:id=1831335",
        },
        {
            id = 1833096,
            score = 6,
            author = "AtroposZ",
            text = "While you *can* use these on the Adolescent Direhorns, dont :) They aggro every time, and theyre elite's with 3.5-ish million HP. If you have the quest to kill 10 trolls, do the ones the trolls are riding, otherwise just do the solo raptors in the pens, they're by far the easiest.",
            date = "2013-03-23T05:39:24-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32554#comments:id=1833096",
        },
        {
            id = 1832516,
            score = 5,
            author = "Skebs",
            text = "The Fetish's can be looted off any troll in the Beast pens. May drop one or 2 at a time but not at 100% drop rate. Seems to be closer to a 50-60% drop chance. They can also be found scattered on the ground through-out the zone as well if you have a keen eye.\n\nWhen used on a raptor it can cause several different effects. Can cause them to gain a damage buff, cause them to explode instantly, may cause them to become friendly and run away, etc. May be used on a lone raptor or raptors with a troll rider, doesnt matter.\n\nBe aware that if you try and delete any extra fetish's from your inventory before handing in the quest, it will delete the quest from your quest log!",
            date = "2013-03-21T20:30:07-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32554#comments:id=1832516",
        },
        {
            id = 1837341,
            score = 4,
            author = "Dianora",
            text = "if you don't like suprises, the Bladetalon hatchlings are very safe to use.  They don't turn hostile.",
            date = "2013-03-31T21:12:58-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32554#comments:id=1837341",
        },
        {
            id = 1832034,
            score = 3,
            author = "MarsJenkar",
            text = "I use my fetish on the 'saurs sometimes\nSaying ayo\nLet them all go\nI wanna set them free to live their lives\nSaying ayo\nYou can now go\n\nI'm gonna try my luck\nHope I get this right\nIf I do, I'll free\nLots of dino might\nTry each fetish once\n'Cause they won't work twice\nHope to rescue some\nOf their dino might",
            date = "2013-03-20T21:28:30-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32554#comments:id=1832034",
        },
    },
