        {
            id = 1826825,
            score = 29,
            author = "Mendric",
            text = "/tar wild\n\nBe sure to check your tracking options (the magnifying glass on your mini map) and check \"Target\". That way you can, well, track it after you've targeted it.\n\nJust like the quest area coverage shows. It flies for a few seconds and lands at many spots. If you miss it you can just wait at where you saw it land just as easily.",
            date = "2013-03-11T13:31:57-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32571#comments:id=1826825",
