    [32572] = {
        {
            id = 1827357,
            score = 7,
            author = "809449",
            text = "I found an easy and fast way to do this quest is to go to 49.66 on map, and you´ll find some Shado-Pan Veteran Marksmen. The animated warriors keep coming there in a steady stream, so just gather them up and you´ll get help killing the warriors by the NPC's. Be warned though, they do a body slam for a good bit of damage, so make sure you´ne not standing in front of them, keep moving.\n\nAnd keep your eyes open as well for the quest https://www.wowhead.com/quest=32571 since the https://www.wowhead.com/npc=94605 lands here occasionally.",
            date = "2013-03-12T09:11:54-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32572#comments:id=1827357",
        },
        {
            id = 1851170,
            score = 1,
            author = "skadimundr",
            text = "There is also a group of NPCs who will kill the Animated Warriors for you at 41,54 but they're a bit more scattered. When I went by, one of them was stuck on a rock next to the Court of Bones, and when I clicked him, he ran around and ran back to the group.",
            date = "2013-05-08T11:00:41-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32572#comments:id=1851170",
