    [32574] = {
        {
            id = 1835152,
            score = 18,
            author = "1109169",
            text = "I died a few times before I figured out an easy way to kill this guy. Wait till the devilsaur pats over to the cave and start killing him near the guards...bam...guards help you kill him and your golden. Avoid different spells and you should be ok.",
            date = "2013-03-27T06:56:15-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32574#comments:id=1835152",
        },
        {
            id = 1859323,
            score = 8,
            author = "Raz101",
            text = "For those who think \"the cave\" is a bit vague. I believe you can kite the Mighty Devilsaur (http://www.wowhead.com/npc=70591#drops) to the Bleak Hollow, coord 51.47. When I tried, the npc's took over and it died rather quickly but I didn't get credit for it.",
            date = "2013-05-28T17:08:06-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32574#comments:id=1859323",
        },
        {
            id = 1852496,
            score = 4,
            author = "dewald",
            text = "I concur. I happened to engage this fellow near the cave.  After taking a very\ndamaging hit I ran into the cave to heal up.  Next thing I know he goes down.\nI can only conclude that the guards fighting at the entrance to the cave brought\nhim down.",
            date = "2013-05-12T13:18:20-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32574#comments:id=1852496",
        },
        {
            id = 1891701,
            score = 3,
            author = "nightdragon76",
            text = "I just tried the cave trick as well, I kited him in there and the NPC's killed him while I was attacking him as well, but did not get the credit for it, so this no longer works.",
            date = "2013-08-31T09:01:23-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32574#comments:id=1891701",
        },
        {
            id = 1925199,
            score = 2,
            author = "610726",
            text = "Might wanna skip this one.\n\nAs other comments suggest, the devilsaur can be pulled over to Bleak Hollow, where the Shado-Pan Assault NPCs can help bring him down between fighting trolls. However, like other mobs on the isle, you need to do a notable amount of damage in order for the kill to count (possibly more than 50%, not sure, but definitely more than just one hit to tag him). That's where it can get aggravating.\n\nHe spams https://www.wowhead.com/spell=140476 and https://www.wowhead.com/spell=140427, two AoEs that severely limit safe spots in his general vicinity, especially for melee. He moves slow, so he's harder to kite. There are mogu and patrolling trolls to avoid. You're likely to be by yourself out there, or need to make extra effort to get help. He's definitely soloable by now even without the NPCs, it's just that the fight could be more trouble than seems worthwhile for some classes and specs. I can see pet classes having an easier time than I did as melee, maybe other ranged who can kite well.\n\n[e] At level 90 it'll probably still be annoying, especially for melee, but at 100 it's ridiculously easy as you'd probably expect.",
            date = "2013-12-11T10:25:51-06:00",
            sourceUrl = "https://www.wowhead.com/quest=32574#comments:id=1925199",
        },
    },
    [32575] = {
        {
            id = 1826994,
            score = 7,
            author = "318012",
            text = "Soloable.  Don't be put off by the \"elite\" marking, level, or the health bar.  Run behind him when he's casting, and obviously when the ground starts to rumble/smoke, clear out and return after the ground \"explodes\".  If you avoid those two main spells you don't take much damage and can get it down quickly.",
            date = "2013-03-11T18:32:15-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32575#comments:id=1826994",
        },
        {
            id = 1837355,
            score = 5,
            author = "1014684",
            text = "He may be soloable by certain classes (i.e. with strong pets or good ranged attacks) but melee is tough.  Running away from his casts works up to a point.  There are adds wandering around and if you accidentally pull those, you are toast!",
            date = "2013-03-31T22:30:15-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32575#comments:id=1837355",
        },
        {
