    [32606] = {
        {
            id = 1822581,
            score = 110,
            author = "339502",
            text = "If you're wondering where the Mogu weapons are, After you kill a Saurok it will appear as an extra action button.",
            date = "2013-03-06T10:24:55-06:00",
            sourceUrl = "https://www.wowhead.com/quest=32606#comments:id=1822581",
        },
        {
            id = 1829814,
            score = 15,
            author = "zeraveth89",
            text = "Spent a good 30 min today struggling with this quest as it seemed no matter how many I kept killing, I never got up the special action bar to spear the corpses. It would however to my amusement seem to be an easy fix of login out and back in.",
            date = "2013-03-16T18:42:44-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32606#comments:id=1829814",
        },
        {
            id = 1824003,
            score = 11,
            author = "tr1gger",
            text = "Just kill https://www.wowhead.com/npc=69210, https://www.wowhead.com/npc=69227 and https://www.wowhead.com/npc=69338 around the Jhgluk Crag (49,81). Once they die, you will get the extra button to Plant The Mogu Weapon. One button per NPC so you will have to kill 9.",
            date = "2013-03-07T18:12:47-06:00",
            sourceUrl = "https://www.wowhead.com/quest=32606#comments:id=1824003",
        },
        {
            id = 1823471,
            score = 10,
            author = "243447",
            text = "Kill the mob and loot it then select it and use the Action button that pops up to drive the weapon into its' corpse. ~ 99% of the mobs in the designated area will work fine.\n\nYou may find it easier to create a new macro (put it on an action bar) and assign a key binding to it using the following...\n\n/click ExtraActionButton1\n\nOnce you create the macro it can be used anytime the UI grants you access to the \"Action Button\"...\n\nPS... You can stack your kills and do this quest with one click of the button. Just make sure the mobs you kill are close to each other when they die.\n\nHappy hunting!",
            date = "2013-03-07T06:38:01-06:00",
            sourceUrl = "https://www.wowhead.com/quest=32606#comments:id=1823471",
        },
        {
            id = 1822804,
            score = 6,
            author = "1017617",
            text = "Just want to clarify an earlier post...yes there are arrows on dead ones and the icon pops in the bottom center of your screen, Blizz's new way of \"click this to use it\". I ran around for a long time looking for these arrows on the dead ones but it didn't happen. The easiest way to do this is to right click on your transform icon, upper right, and \"un-transform\" (?) from the saurok. Then you kill the mob and then the icon pops up. You will be able to loot, then you transform back and can hop around until you find another mob. Not all mobs qualify for the spear. I killed one that had a basilisk and no spear. There are only a few that don't work, and some are harder to kill than others but it will realistically only take a few minutes. The little cul-de-sac areas generally have a few mobs you can kill and get the spear credit. I suggest everyone get on the Isle dailies ASAP. There are a million people doing them so when you need to kill the elites or bosses or whatever the harder ones may be, there's plenty of help. Today was my first day doing them and it was pretty easy. There are also several rares available although I didn't see one. Chat was filled with rares showing up. Have fun with the new dailies!",
            date = "2013-03-06T14:08:08-06:00",
            sourceUrl = "https://www.wowhead.com/quest=32606#comments:id=1822804",
        },
    },
