    [32614] = {
        {
            id = 1821913,
            score = 20,
            author = "Ryawy",
            text = "It does look like these are repeatable. Also, doing this quest for the individual motes instead of https://www.wowhead.com/quest=32615 may be a better deal even though it takes longer to turn them in individually. Since it takes 9 bones for one https://www.wowhead.com/item=89112 and 10 motes for one https://www.wowhead.com/item=76061, you would be spending 90 bones for one spirit. If you do the other quest, you'll be spending 99 bones for a Spirit which could have been obtained 9 bones cheaper.\n\nEdit: Well... if you're patient, you can still turn them in for a better deal. This might not be the best option, seeing as now they can only be completed once per day.\n\nIs this the NPC's way of cheating you out of your bones, or have I completely missed something?",
            date = "2013-03-05T22:46:39-06:00",
            sourceUrl = "https://www.wowhead.com/quest=32614#comments:id=1821913",
        },
        {
