            author = "926587",
            text = "After completion of this quest, you will be able to make https://www.wowhead.com/item=94111, you need https://www.wowhead.com/item=72096 x10 for this; see https://www.wowhead.com/spell=138646.\n\nFor more information on all the new items you can build, see Wowheads post here (http://www.wowhead.com/news=210156/5-2-crafted-vanity-items-lightning-forged-weapons-engineering-pet).",
            date = "2013-03-02T12:24:43-06:00",
