            author = "perculia",
            text = "After completing the quest, you will get https://www.wowhead.com/spell=137262 which increases your run speed by 5% for 15 minutes.",
            date = "2013-02-17T09:17:01-06:00",
            sourceUrl = "https://www.wowhead.com/quest=32627#comments:id=1814677",
        },
        {
            id = 1827084,
            score = 15,
            author = "HelloKitty",
            text = "I don't think it's intentional, but today (3/11) when my realm unlocked this daily, I mounted with the Moganite and did not drop it.\n\nAlso, in order to 'complete' this quest you actually have to walk to ~melee range of the questgiver (in this case, https://www.wowhead.com/npc=67994).",
            date = "2013-03-11T21:04:04-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32627#comments:id=1827084",
        },
        {
            id = 1812879,
            score = 10,
            author = "308541",
            text = "This quest is similar to gathering Silithyst in old-time Kalimdor, or Element 115 in Venture Bay.  This item can be found in several places on Thunder Isle, and it's a bright tear-shaped rock, so just grab it on your way back from your other dailies.  I say \"back from\" because, like Silithyst and Element 115, mounting or dying will cause you to drop the Moganite.  This has different effects from those other items: it creates a bright beacon that makes the carrier easily noticed, but the carrier's attacks also have a chance to unleash a lightning bolt for additional damage.",
            date = "2013-02-12T19:55:31-06:00",
            sourceUrl = "https://www.wowhead.com/quest=32627#comments:id=1812879",
        },
        {
            id = 1850529,
            score = 5,
            author = "Nandaria",
            text = "You can still use https://www.wowhead.com/item=95567 while carrying the Charged Moganite. To do so, pick up the moganite after you've finished the other quests or drop it (rightclick your buff or use /cancelaura) and pick it up again. While picking it up (which has a ~1 sec cast time), use the teleporter item. You just have to be fast enough.",
            date = "2013-05-06T07:59:43-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32627#comments:id=1850529",
        },
    },
    [32628] = {
        {
            id = 1830231,
            score = 26,
            author = "590351",
            text = "For those who struggle to find the crystals, they are up on the hill to the right as you enter as face the two tents (the tents where you pick up the book for another daily), you will see HUGE crystals floating, and a little cogwheel below it (can be hard to miss) that is the Scrying Crystals.\n\nThe Boat is the north of the main horde base and the bridge is the first bridge you cross (down in the water) that goes towards the horde main base.",
            date = "2013-03-17T14:25:01-05:00",
