    [32632] = {
        {
            id = 1828321,
            score = 4,
            author = "cayleb",
            text = "For those used to completing the Horde version of this quest, the Alliance version is much more difficult by virture of it's placement in the middle of the only route in and out of the Horde base.  Prepare to be ganked... repeatedly... if you attempt this quest solo during high-traffic hours.\n\nDue to the nature of this fight—as well as it's high-traffic location—it is helpful (though not mandatory) to assemble a group.\n\nThe adds spawned by this quest mob have an AoE damage pulse.  If you destroy them, they grant you a 25% damage buff while standing near them, but you will likely take more damage this way.  You will likely finish the fight more quickly if you kite, as this means less time wasted on adds and self-healing/damage prevention.",
            date = "2013-03-14T01:55:30-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32632#comments:id=1828321",
        },
        {
            id = 1830436,
            score = 1,
            author = "Calesta",
            text = "Located just outside the main Horde encampment at Dawnseeker Promontory so you're able to engage the mob without having to deal with elite mobs.  While in combat, drops little arcane bombs much like Mechano-Lord Capacitus (http://www.wowhead.com/npc=19219) in The Mechanar (http://www.wowhead.com/zone=3849).",
            date = "2013-03-17T23:14:12-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32632#comments:id=1830436",
        },
        {
            id = 1866540,
            score = 1,
            author = "Herbol",
            text = "There's actually a way to exploit the location a bit and make the fight way easier, if you kite the mob into water right next to him, the adds he spawns spawn into the bottom of the water and the buff won't reach him.",
            date = "2013-06-14T09:19:11-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32632#comments:id=1866540",
        },
    },
    [32633] = {
        {
