            score = 10,
            author = "979563",
            text = "It'd be hillarious if both the quests had you stealing the same book from eachother over and over\n\nOn another note, book respawns pretty fast, so line-ups are uncommon.",
            date = "2013-03-18T17:14:28-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32633#comments:id=1830779",
        },
    },
    [32634] = {
