    [32636] = {
        {
            id = 1830026,
            score = 3,
            author = "1054498",
            text = "If you can't find captives, head north towards 39, 35. I have only noticed about 7 captives up at any given time when there are a good 20 different runes. Runes containing captives are often found to northern side of the quest area around 39, 35. This is across the other side of the road that divides the quest area. I assume it is because the southern area of the quest zone is much easier to access and avoids the main thoroughfare of horde players so more players start doing the dailies there. If you can't find any captives, head north, often the spawns on north most beaches around 39, 35 are occupied.\n\nI do these dailies using water walking (hunter waterstrider) entering the water at 45, 43 then I ride up to 39, 35. It hits the most commonly occupied spawns for this quest plus you can most of the other PVP dailies and you avoid the horde quest hub.",
            date = "2013-03-17T05:04:55-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32636#comments:id=1830026",
        },
        {
            id = 1827240,
            score = 2,
            author = "Cowoth",
            text = "The runes are in the Dawnseeker Promontory area on the Isle of Thunder ~ Coordinates 38, 38\n\nRunes are red circles on the ground and you need to click on them.\n,\nEmpty runes will not count towards the quest, the runes must contain a captive to count.  It can be quite annoying as there are sometimes no captives at all.",
            date = "2013-03-12T04:12:26-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32636#comments:id=1827240",
        },
        {
            id = 1830793,
            score = 1,
            author = "979563",
            text = "They tend to be near mana orbs, objective of another quest. Look around for one after you've just busted the other.",
            date = "2013-03-18T17:22:42-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32636#comments:id=1830793",
        },
    },
    [32637] = {
        {
            id = 1832476,
            score = 3,
            author = "1107986",
            text = "This can be done in stealth. They are small, dark red orbs spread around the Horde side of the Isle. They're hard to miss; they're sparkly. Use the quest item in your inventory when you are near them for credit.",
            date = "2013-03-21T18:20:25-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32637#comments:id=1832476",
        },
    },
