    },
    [32645] = {
        {
            id = 1821641,
            score = 12,
            author = "655806",
            text = "You get the work order quests from a post which replaces Farmer Yoon after he goes to join the tillers council.\n\nTo help him along, you need to talk to Nana Mudclaw and complete the https://www.wowhead.com/quest=32682 after you have opened all 16 plots and become exalted with the Tillers.\n\nOnce you complete the quest will also now a book the house on the farm allowing you to set it as your home location.",
            date = "2013-03-05T19:20:18-06:00",
            sourceUrl = "https://www.wowhead.com/quest=32645#comments:id=1821641",
        },
        {
            id = 1822346,
            score = 12,
            author = "Raevenne",
            text = "To see the Work Order quests for Operation: Shieldwall, you must have unlocked the daily quests for that faction.",
            date = "2013-03-06T06:47:56-06:00",
            sourceUrl = "https://www.wowhead.com/quest=32645#comments:id=1822346",
        },
        {
            id = 1835216,
            score = 12,
            author = "821994",
            text = "These seem of questionable value.\n\nthey tie up your quest log for two days\n400 rep and 20g for two quests and 40 (or 56) vegetables is NOT a good deal\nthey are glitchy and  picky (an instant harvest does not count toward your total)\nif you harvest before picking up the 2nd half of the quest you have to start over\n\nVegetables are pretty easily sold for 2.50g (and quite a bit more if you watch supply and demand) x 56 = 140G.  A net cost of 120g and a 2 day quest for 400 rep.\n\n  ∴ That means to get to exalted (42000 rep) it'll cost 12600G and 210 days.\n\nAre these a quest group needed to unlock other quests?  or am I missing something else?  Maybe they're worth it if done in conjunction with the weather prediction of a crop increase. . .\n\nPlease comment.",
            date = "2013-03-27T10:38:59-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32645#comments:id=1835216",
        },
        {
            id = 1823501,
            score = 8,
            author = "1104624",
            text = "Turned in this part of the quest today and didn't receive the second part, not sure if a bug or what, made a ticket to see if they could give it to me manually instead.",
            date = "2013-03-07T07:27:33-06:00",
            sourceUrl = "https://www.wowhead.com/quest=32645#comments:id=1823501",
        },
        {
            id = 1822758,
            score = 6,
            author = "817836",
            text = "If you're looking for the quest turn-in, it's on a wagon on the sw corner of the farm.  It did not show correctly on my mini-map and was not easily seen.  After the turn-in, part I (planting) becomes available again.",
            date = "2013-03-06T13:07:25-06:00",
            sourceUrl = "https://www.wowhead.com/quest=32645#comments:id=1822758",
        },
    },
    [32646] = {
        {
            id = 1822616,
            score = 8,
            author = "881230",
            text = "When you are finished harvesting the fruit/veg you planted, you'll find a little crate in the back of a wagon towards your mailbox on the farm. That's how you package them up to complete the quest (it took me a few minutes to realize it).",
            date = "2013-03-06T10:58:07-06:00",
            sourceUrl = "https://www.wowhead.com/quest=32646#comments:id=1822616",
        },
        {
            id = 1821880,
            score = 6,
            author = "yukonjack",
            text = "This and the other work order quests new in patch 5.2 become available after you complete the quest [quest=32682 domain=www] and are obtainable from a post newly installed in the vacated spot left by Farmer Yoon.",
            date = "2013-03-05T22:10:12-06:00",
            sourceUrl = "https://www.wowhead.com/quest=32646#comments:id=1821880",
        },
        {
            id = 1867838,
            score = 6,
            author = "Gwashington",
            text = "I was also unable to pick up the second half of the quest after turning in the first half.  I opened a ticket and this is the response from the GM:\n \nGreetings!\n\nI went ahead and looked through your character's questlog. I see that he completed the quests Work Order: Operation: Shieldwall I (quest=32645) and Work Order: Operation: Shieldwall II (quest=32646).\n\nI then went ahead and looked through your questlog to find the quest Work Order: Golden Lotus I (quest=32647) and Work Order: Golden Lotus II (quest=32648).\n\nI do see that the second part of both of those quests were completed way earlier in the day. But since it was still completed in that day, you were not able to complete it again after you completed the first part of the quests later that day.\n\nHope this helps!\n \nIt appears that one may be unable to pick up the second half of the quest until the next day - maybe after dailies reset.",
            date = "2013-06-18T00:48:52-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32646#comments:id=1867838",
        },
        {
            id = 1877391,
            score = 3,
            author = "Drokash",
            text = "The peasant that collects your Witchberries belongs to the Kirin Tor Offensive for some reason.",
            date = "2013-07-16T07:15:49-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32646#comments:id=1877391",
        },
        {
            id = 1878397,
            score = 1,
            author = "Schnoodledorfer",
            text = "Although it's not documented, Blizzard has now undone the changes made in a March 7, 2013 hotfix (http://us.battle.net/wow/en/blog/8953693): The way to obtain Work Order quests on the Sunsong Ranch farm has changed. The quests will be given while harvesting crops, or by interacting with the drop-off crate.\n\nNow, instead of starting with the https://www.wowhead.com/object=218765 or waiting until the crops are harvested, the Part II quest is automatically accepted as soon as the Part 1 quest  completes. That happens as soon as you plant enough crops and was the way these quests originally worked. Apparently due to an attempt to make it idiot-proof, it isn't even possible to avoid accepting Part II once you complete Part 1. (The window offering the quest opens automatically, there is no \"Decline\" button, and the \"X\" button to close the window is grayed out. I don't know if that part was true before March 7.) You won't see a blue exclamation point on the crate the second day because you will have already accepted the quest the first day. The exception is if you just completed the same Part II on the same day. In that case, you won't be offered the quest until the next day.\n\nIt still is possible to abandon the Part II quest and pick it up later. If you abandon the quest, the blue \"!\" will appear above the https://www.wowhead.com/object=218765. You can pick up the quest by clicking on the box, but again, you can't decline it once the window opens.",
            date = "2013-07-18T23:58:02-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32646#comments:id=1878397",
        },
    },
    [32647] = {
        {
            id = 1821639,
            score = 19,
            author = "655806",
            text = "You get the work order quests from a post which replaces Farmer Yoon after he goes to join the tillers council.\n\nTo help him along, you need to talk to Nana Mudclaw and complete the https://www.wowhead.com/quest=32682 after you have opened all 16 plots and become exalted with the Tillers.\n\nOnce you complete the quest will also now a book the house on the farm allowing you to set it as your home location.",
            date = "2013-03-05T19:19:41-06:00",
            sourceUrl = "https://www.wowhead.com/quest=32647#comments:id=1821639",
        },
        {
            id = 1822873,
            score = 11,
            author = "Aquifel",
            text = "If you have already completed https://www.wowhead.com/quest=32648 the same day and then start this one afterwards to do the whole process again, you don't seem to be offered https://www.wowhead.com/quest=32648 again, will it be offered tomorrow? i do not know :O.\n\nUPDATE: part 2 still hasn't shown, and can not get part 1 again.",
            date = "2013-03-06T15:19:25-06:00",
            sourceUrl = "https://www.wowhead.com/quest=32647#comments:id=1822873",
        },
        {
            id = 1825857,
            score = 8,
            author = "androjeans",
            text = "If you complete both the Work Orders I and Work Orders II on the same day, you will be offered Work Orders I the following day, but Work Orders II will not pop up until the following day. When you pick up your first, say, Red Blossom Leek, it will THEN pop up with the turn in at the cart near the Mailbox.\n\nIf you skip a day, you'll be able to get both Work Order quests on the same day.",
            date = "2013-03-10T07:09:42-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32647#comments:id=1825857",
        },
        {
            id = 1924689,
            score = 7,
            author = "182693",
            text = "Here is a list of what you would need to buy/plant/harvest for each faction in the daily \"Work Order:\" quests.\n\nFaction........................Plant/Harvest 8/40\nDominance Offensive..Red Blossom Leek\nKlaxxi...........................Mogu Pumpkin\nShado-Pan..................Green Cabbage\nAugust Celestials.........Striped Melon\nGolden Lotus...............White Turnip\nSunreaver Onslaught..Scallion\n\nBe sure to ask Jogu the Drunk (http://www.wowhead.com/faction=1273) which crop to plant/will be producing extra the next day.  Doing so gives you the knowledge so you can yield some extra veggies in addition to the ones you use in completing these quests.",
            date = "2013-12-09T10:13:05-06:00",
            sourceUrl = "https://www.wowhead.com/quest=32647#comments:id=1924689",
        },
        {
            id = 1822345,
            score = 6,
            author = "Raevenne",
            text = "To see the Work Order quests for Golden Lotus, you must have unlocked the daily quests for that faction.",
            date = "2013-03-06T06:47:18-06:00",
            sourceUrl = "https://www.wowhead.com/quest=32647#comments:id=1822345",
        },
    },
    [32648] = {
        {
            id = 1824910,
            score = 12,
            author = "Troo",
            text = "They hot patched the way these quests are picked up/turned in today (3/8/13). Once you have planted your crop for part 1 and come back the next day to harvest it, this quest will be a blue ! over a crate in the cart next to your farm. You'll want to pick this up before you harvest.",
            date = "2013-03-08T22:14:18-06:00",
            sourceUrl = "https://www.wowhead.com/quest=32648#comments:id=1824910",
        },
        {
            id = 1874461,
            score = 7,
            author = "735486",
            text = "Don't bother abandoning this quest.  I did the first part, then got exalted in the meantime.  I harvested the turnips and abandoned.  I clicked on the crate to finish a different quest; it gave me the turnip quest again.  I abandoned it.  I had some leftover seeds so I planted another turnip.  When I went to harvest it, boom it gave me the quest again.  Any time I click on the crate or havest a turnip from now until the end of wow, it will give me that quest.  I put in a ticket but the gm said I just had to do the quest, there was no way around it.  Forty turnips that sell for 2-5 g each vs. a dumb lesser charm and about 9 g.  What a cluster****.",
            date = "2013-07-07T08:32:58-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32648#comments:id=1874461",
        },
        {
