        },
        {
            id = 1835069,
            score = 5,
            author = "Vylyss",
            text = "Reputation earned in this quest is affected by bonuses, for example if you purchased and used https://www.wowhead.com/item=93215 you will get 800 reputation. It's a really nice alternative for dailies, since harvesting your crops takes much less time than doing Golden Lotus quests over and over again.",
            date = "2013-03-27T03:37:27-05:00",
