        },
    },
    [32650] = {
        {
            id = 1823645,
            score = 22,
            author = "rogermw",
            text = "If you turn in this quest, and then do \"Work Order: Shado-Pan I\" the same day, you will NOT get offered this quest as a follow up.\n\nDon't despair and dig up your crops, though!  You will get re-offered this quest on the following day the moment you harvest your first crop click on the Empty Crate with the blue ! over it.\n\n(EDIT: As of 5.4, the get-the-quest-automatically-by-harvesting-a-crop mechanism seems to be broken. You have to click on the empty crate with the blue ! over it instead.)\n\n(RE-EDIT: As of late November 2013, this seems to be fixed, and you will once again get this quest automatically the day after turning it in by harvesting a ripe or plump green cabbage.)",
            date = "2013-03-07T10:19:13-06:00",
            sourceUrl = "https://www.wowhead.com/quest=32650#comments:id=1823645",
        },
        {
            id = 1822761,
            score = 20,
            author = "817836",
            text = "If you're looking for the quest turn-in, it's on a wagon on the sw corner of the farm.  It did not show correctly on my mini-map and was not easily seen.  After the turn-in, part I (planting) becomes available again.",
            date = "2013-03-06T13:08:37-06:00",
            sourceUrl = "https://www.wowhead.com/quest=32650#comments:id=1822761",
        },
        {
            id = 1845600,
            score = 8,
            author = "Crotalidus",
            text = "If you get a Bursting Green Cabbage when doing part I of this quest line, don't harvest it until the rest of the crop is ready to harvest on the next farming day.  Harvesting Bursting veggies right away means they do not count the next day when you are trying to complete part II.",
            date = "2013-04-21T15:09:31-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32650#comments:id=1845600",
        },
        {
            id = 1852066,
