    [32652] = {
        {
            id = 2458078,
            score = 137,
            author = "765310",
            text = "If u stuck in the last stage (6/6 in the mines where you should open the door - can bug if u kill elite to fast and npc not open the door yet), you can just type /script LeaveParty() and you will be teleported to questgiver and quest is completed and rdy for next stage, took me a while to figure it out :)",
            date = "2016-12-31T08:16:21-06:00",
            sourceUrl = "https://www.wowhead.com/quest=32652#comments:id=2458078",
        },
        {
            id = 5885446,
            score = 46,
            author = "Cimegs5088",
            text = "If you doing this on Panda Remix and stuck at the last part where you need to unlock the Lightning Mine Door, just leave the scenario and it will show you have done the scenario",
            date = "2024-06-21T22:06:33-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32652#comments:id=5885446",
        },
        {
            id = 1834842,
            score = 39,
            author = "Intergalactic",
            text = "After you enter the solo scenario, Jaina will direct you attention upon the pterodactyl you collected during a daily in last stage. This mount, she says, is protected from the thunder, so it's safe to ride. Head towards the mount, Thunderwing, and get on it, it's big, it's blue, it's marked on minimap as a cogwheel. When you mount up it begins to fly towards the newly opened zone, and you get a new button on your screen in the middle. At some point trolls arrive, flying next to you. You target the trolls mount and press the new button, next thing you know, you jumped on his mount and you can kill him. After you kill the first troll, others arrive, no need to use the new button, your character will auto jump after every kill. When they are all dead, you auto jump back on Thunderwing. After landing be prepared for a fight with Beastmaster Horaki, a dual axe wielding hunter. He will attack within 10 seconds after you land. Occasionally he will cast Frost Shot, this will freeze you to the ground, so if you don't have many cc breaking skills, run away while he's casting it. The affected area will appear in a blue hue. After Frost Shot he always casts Hail of Arrows, which will be marked on the ground with a rather large red circle and arrows will fall continuously within that circle. These circles will remain there during the whole fight  and he will cast it more then 1 times, so plan your route carefully, always stopping at the very edge of the red circle. If you don't get out in time, you will get a debuff, which hits for 20k every few seconds. If you die at any time, you will be resurrected jus a bit downhill from the area where you landed. He cannot be interrupted, but he can be stunned, disoriented etc. After the fight, Taoshi will land near the blocked cave entrance, go talk to her. She blows the cave entrance, follow the cave and take the first right. There are some mogu electrocutioners on the way, after you kill them, a blue sphere will be over their body, walk over it to get a buff, which increases haste with 10% and lasts 6 sec, this buff stacks up to 10 and time increases gradually up to 2 minutes. So after 10 kills, you get 100% haste for 2 min, a great and amazing buff. Every new kill after that refreshes the 2 minutes. Down the hill in the cave is the second and last \"boss\", Slavemaster Shiaxu. He has 2 different frontal attacks, just run through him to his back when he casts. At some point you get tied with 3 chains, the idea is to run away from each chain in the opposite direction to break the link. He cannot be interrupted, but he can be stunned, disoriented etc.This fight seemed easier compared to Horaki. After he's down, Jaina appears and you can take the portal she opens. Have fun.",
            date = "2013-03-26T16:54:30-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32652#comments:id=1834842",
        },
        {
            id = 1835178,
            score = 24,
            author = "Myrli",
            text = "I ran this three times until I figured out that during the flying stage the buff your mount provides wouldn't sustain me through the final 3 mobs.  Some classes require some sort of healing during the flight while others may have no problems.\n\nI found a novel (possibly inappropriate) solution for my hunter.  When I was low on health (about when the final 3 mobs appeared) I popped Feign Death.  Then all 4 of us flew around the island a few times until my health was recovered (several minutes) then I took down the last three.  It was quite surreal.",
            date = "2013-03-27T08:25:24-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32652#comments:id=1835178",
        },
        {
            id = 1883060,
            score = 21,
            author = "Berronaxwins",
            text = "Can anybody refresh my memory... when exactly did we rescue this \"thunderwing\"?",
            date = "2013-08-01T18:20:33-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32652#comments:id=1883060",
        },
    },
