    [32657] = {
        {
            id = 1823641,
            score = 27,
            author = "rogermw",
            text = "If you turn in this quest, and then do \"Work Order: The August Celestials I\" the same day, you will NOT get offered this quest as a follow up.\n\nDon't despair and dig up your crops, though!  You will get re-offered this quest on the following day the moment you harvest your first crop.  (Or, according to axelia's report below, click on the empty crate.)\n\n(EDIT: As of 5.4, the get-the-quest-automatically-by-harvesting-a-crop mechanism seems to be broken. You have to click on the empty crate with the blue ! over it instead.)",
            date = "2013-03-07T10:17:48-06:00",
            sourceUrl = "https://www.wowhead.com/quest=32657#comments:id=1823641",
        },
        {
            id = 1844805,
            score = 14,
            author = "Hildur",
            text = "Why is the NPC picking up the melons in her underwear?",
            date = "2013-04-19T01:47:36-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32657#comments:id=1844805",
        },
        {
            id = 1822763,
            score = 5,
            author = "817836",
            text = "If you're looking for the quest turn-in, it's on a wagon on the sw corner of the farm.  It did not show correctly on my mini-map and was not easily seen.  After the turn-in, part I (planting) becomes available again.",
            date = "2013-03-06T13:09:16-06:00",
            sourceUrl = "https://www.wowhead.com/quest=32657#comments:id=1822763",
        },
        {
            id = 1822338,
            score = 3,
            author = "Raevenne",
            text = "It's worth noting that if you harvest melons on the same day--say if one of your crops is bursting right away--it will not count as harvesting striped melons for the quest. You will still have to wait until the next day to harvest the eight that are needed!\n\nETA: after the hotfix to the Work Order quests, this may no longer be an issue, as you don't automatically get part II of the Work Order upon completing part I.",
            date = "2013-03-06T06:41:33-06:00",
            sourceUrl = "https://www.wowhead.com/quest=32657#comments:id=1822338",
        },
        {
            id = 1878386,
            score = 2,
            author = "Schnoodledorfer",
            text = "Although it's not documented, Blizzard has now undone the changes made in a March 7, 2013 hotfix (http://us.battle.net/wow/en/blog/8953693): The way to obtain Work Order quests on the Sunsong Ranch farm has changed. The quests will be given while harvesting crops, or by interacting with the drop-off crate.\n\nNow, instead of starting with the https://www.wowhead.com/object=218765 or waiting until the crops are harvested, the Part II quest is automatically accepted as soon as the Part 1 quest  completes. That happens as soon as you plant enough crops and was the way these quests originally worked. Apparently due to an attempt to make it idiot-proof, it isn't even possible to avoid accepting Part II once you complete Part 1. (The window offering the quest opens automatically, there is no \"Decline\" button, and the \"X\" button to close the window is grayed out. I don't know if that part was true before March 7.) You won't see a blue exclamation point on the crate the second day because you will have already accepted the quest the first day. The exception is if you just completed the same Part II on the same day. In that case, you won't be offered the quest until the next day.\n\nIt still is possible to abandon the Part II quest and pick it up later. If you abandon the quest, the blue \"!\" will appear above the https://www.wowhead.com/object=218765. You can pick up the quest by clicking on the box, but again, you can't decline it once the window opens.",
            date = "2013-07-18T23:18:28-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32657#comments:id=1878386",
        },
    },
    [32658] = {
        {
            id = 1826938,
            score = 19,
            author = "Morzella",
            text = "I understand gameplay comes before lore and all, but the Klaxxi placing work orders with the Tillers is just odd.\n\nEven though the Klaxxi hate pandaren as much as any other mantid they decided to send a lone scout over the heavily deffended wall into the heart of a heavily deffended town (I've seen how hard those Halfhill Defender's hit gankers), to make an offcial request for pumpkins. They then send this guy back into the teeth of the enemy to collect them. Surely it would have been easier to just steal a few pumpkins in the midsts of the raveging and looting of the local farmland your fellow mantid are engaged in.",
            date = "2013-03-11T16:50:58-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32658#comments:id=1826938",
        },
        {
            id = 1803781,
            score = 17,
            author = "884267",
            text = "I can't imagine what's funnier... what the Klaxxi will do with the pumpkins that you give them, or what they'll do to you(r farm) if you don't.",
            date = "2013-01-25T02:21:02-06:00",
            sourceUrl = "https://www.wowhead.com/quest=32658#comments:id=1803781",
        },
        {
            id = 1822347,
            score = 17,
            author = "Raevenne",
            text = "To see the Work Order quests for the Klaxxi, you must have unlocked the daily quests for that faction.",
            date = "2013-03-06T06:48:52-06:00",
            sourceUrl = "https://www.wowhead.com/quest=32658#comments:id=1822347",
        },
        {
            id = 1821642,
            score = 10,
            author = "655806",
            text = "You get the work order quests from a post which replaces Farmer Yoon after he goes to join the tillers council.\n\nTo help him along, you need to talk to Nana Mudclaw and complete the https://www.wowhead.com/quest=32682 after you have opened all 16 plots and become exalted with the Tillers.\n\nOnce you complete the quest will also now a book the house on the farm allowing you to set it as your home location.",
            date = "2013-03-05T19:21:08-06:00",
            sourceUrl = "https://www.wowhead.com/quest=32658#comments:id=1821642",
        },
        {
