    [32676] = {
        {
            id = 1838618,
            score = 9,
            author = "svann",
            text = "10 years coding this game and they still cant make the ships run on time.",
            date = "2013-04-03T16:31:17-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32676#comments:id=1838618",
        },
        {
            id = 1838693,
            score = 7,
            author = "Marclivis",
            text = "So the Zandalari have mastered vessel cloaking eh? This has got to be a violation of the Treaty of Algeron.",
            date = "2013-04-03T20:10:21-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32676#comments:id=1838693",
        },
        {
            id = 1838310,
            score = 6,
            author = "1060098",
            text = "Re-logging kind of worked for me. Except the ship seemingly disappears and reappears based on where i am standing. I was right at the dock and I saw it. As soon as I tried to step on the boat, it vanished and I fell in the water.",
            date = "2013-04-03T02:20:35-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32676#comments:id=1838310",
        },
        {
            id = 1839167,
            score = 6,
            author = "830343",
            text = "The trick to boarding the boat (prior to the immanent hotfix) is to run as fast as you can off dock 9 and 1/2 and believe as hard as you can.",
            date = "2013-04-04T20:59:19-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32676#comments:id=1839167",
        },
        {
            id = 1838516,
            score = 4,
            author = "Kalthar",
            text = "This has to have a bugfix in the works, but here is what I've found for people who want to get it done before then. The ship suffers from pretty severe phasing issues. It only appeared for a few seconds for me as it pulled away from the dock, at which point it disappeared again. The window for the ship actually appearing was so small that you may have missed it just by alt-tabbing to look it up. Once the ship leaves the dock it stops at about 70,80 (East of Violet Rise) and does a siege attack. The ship doesn't have a ledge low enough to jump onto from the water. There was a jutting rock nearby, but I wasn't able to climb it to try my glider cloak.\n\nThe ship stayed there in the water for exactly 10 minutes and then disappeared without warning. I wasn't able to find it elsewhere in the water, so I headed back to the dock. Another 10 minutes after it vanished, it appeared back at the dock for the same short window as it pulled up. While it's sitting at the dock, it actually seems to phase out, only appearing again for the few seconds as it pulls away.\n\nTL;DR, the ship appears to make its round in about 20 minutes, but it was only in phase for me for the few seconds when it was pulling into or out of the dock. Re-logging to try to phase it didn't seem to do anything. The mob you need has a very quick 'quest mob' respawn time, so don't panic if someone gets him before you. Just don't jump off the ship! Good luck, and let's hope for a quick fix! :P\n\nUPDATE: As of the April 4 2013 hotfix, this quest has been removed from the daily quest rotation until the ship can be fixed. You should no longer be able to receive it for the moment.",
            date = "2013-04-03T13:02:49-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32676#comments:id=1838516",
        },
    },
    [32677] = {
        {
            id = 1838198,
            score = 115,
            author = "883209",
            text = "For those of you who despise adventure game puzzles as much as me - make a run across as far as you can, die (graveyard is very close), run back and rez on the other side. Takes less time than trying to win the little grid puzzle.",
            date = "2013-04-02T19:25:05-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32677#comments:id=1838198",
        },
        {
            id = 1841993,
            score = 57,
            author = "493853",
            text = "Entrance to Swollen Vaults is at 62,40. For those without coordinates, it is to the northwest of the ship you see on the map near Stormsea Landing.",
            date = "2013-04-11T16:58:39-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32677#comments:id=1841993",
        },
        {
            id = 1839447,
            score = 46,
            author = "668287",
            text = "Two platforms will be \"safe\" - no blueish haze on them - at a time, and they're always next to each other. One will become unsafe, and another will become safe next to one of the previous two. These snake about and progress like this:\n\n  1st           2nd           3rd           4th           5th           6th           7th\nx x 1 2 x     x x x 2 x     x x x x x     x x x x x     x x x x x     x x x x x     x x x x x\nx x x x x     x x x 3 x     x x x 3 x     x x x x x     x x x x x     x x x x x     x x x x x\nx x x x x     x x x x x     x x x 4 x     x x x 4 5     x x x x 5     x x x x x     x x x x x\nx x x x x     x x x x x     x x x x x     x x x x x     x x x x 6     x x x 6 7     x x x 7 x\nx x x x x     x x x x x     x x x x x     x x x x x     x x x x x     x x x x x     x x x 8 x\n\nTo do this exercise, watch for the two safe pillars. When one comes to the close edge, jump to it. Make sure you're on the lead pillar of the two-snake, and whenever a new pillar opens up, jump to it. It doesn't matter which direction the snake goes, you must follow it, and at some point it will get to the other side\n\nOnce you understand the progression, getting the achievement is trivial.",
            date = "2013-04-05T15:38:52-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32677#comments:id=1839447",
        },
        {
            id = 1841935,
            score = 39,
            author = "Misy",
            text = "That awkward moment when you finally manage to get on the other side, and you realize you forgot to loot the key -.-",
            date = "2013-04-11T14:47:23-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32677#comments:id=1841935",
        },
        {
            id = 1842609,
            score = 26,
            author = "785482",
            text = "For those of you wondering where the entrance is to The Swollen Vault, when you stand at the guy that gave you the quest, facing outwards, run forward and down the stairs and go left around the corner and through the door to your left.",
            date = "2013-04-13T09:18:39-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32677#comments:id=1842609",
        },
    },
    [32678] = {
        {
            id = 3199556,
            score = 53,
            author = "kevve420",
            text = "if you are like me and want to get into Throne of Thunder with a boosted 120 char for some xmog, you won't be able to get there without the introduction quest like mentioned earlier.\n\nHowever...\nWith the Assaults happening in Vale you are in a different phase and you won't see the quest giver!\nGo to Mogushan Palace and you will see a dialog bubble popping on your map, talk to this NPC called Zidormi and travel back in time. Once this is done, go back to the quest giver location and get the quest.\nNow go back to Zidormi and go back to the present to do the assaults when ever they are back up!\n\nBlizzard was absolutely no help on this since nothing indicated this ! Very poor customer care imo!\n\nHope this helps anyone.",
            date = "2020-04-13T13:52:22-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32678#comments:id=3199556",
        },
        {
            id = 5861739,
            score = 29,
