    [32710] = {
        {
            id = 1849396,
            score = 3,
            author = "Malvenue",
            text = "Quest is auto-offered in the sewers before Iron Qon.  He has an AOE cleave, move out of the way.  He puts a 5m stacking disease on everyone that does around 1400 per tic that can be easily dispelled and a period explosion that does 180kish to everyone in the raid.  Tank and spank, basically.  Very easy.",
            date = "2013-05-02T19:11:02-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32710#comments:id=1849396",
        },
        {
            id = 1855096,
            score = 3,
            author = "thegrimreefer",
            text = "Rare spawn in Throne of Thunder, right before https://www.wowhead.com/npc=68078 .\n\nPretty easy, just a lot of raid damage from https://www.wowhead.com/spell=140052 (disease) and it continues to stack.\nHeals himself from https://www.wowhead.com/spell=139311, so raid stack behind him.\nhttps://www.wowhead.com/spell=139314 requires a tank swap @ maybe 3 to 5 stacks.\n\nHealing can get a little intensive as disease stacks build up, so you might consider saving CDs until then.",
            date = "2013-05-21T13:46:26-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32710#comments:id=1855096",
        },
        {
            id = 1887636,
            score = 1,
            author = "1117686",
            text = "Since the boss itself is not on the way to Iron Qon, this quest is easily skippable.",
            date = "2013-08-16T18:31:45-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32710#comments:id=1887636",
        },
    },
    [32711] = {
        {
            id = 1846991,
            score = 3,
            author = "Malvenue",
            text = "This weekly raid quest is offered on the stairs right before the Dark Animus room.  Like other weekly quest mobs, he replaces a trash spawn, in this case the two annoying mobs that aggro when you open the room's door.  He casts an Extermination Beam that does stacking massive damage and needs to be interrupted.  Around 50% (or so) he gains an interrupt shield and can no longer be interrupted.  The shield is NOT an immunity shield (although it looks like one) so just burn him down fast as that stacking buff will start doing 250k per sec on anyone he focuses.",
            date = "2013-04-25T19:02:25-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32711#comments:id=1846991",
        },
        {
            id = 1825001,
            score = -3,
            author = "bigfoot1291",
            text = "We found this guy right before Dark Animus's room, coupled with the quest to kill him. He had a silver dragon on his nameplate, but it didn't really seem like he was a \"rare\" - It was extremely underwheming, as all any of us in the raid got for killing / completing the quest was a standard LFR / boss loot bag with your 28g, and that's it. He had around 29 million HP (10 man) and didn't really do much. We just burned him down.",
            date = "2013-03-09T01:36:32-06:00",
            sourceUrl = "https://www.wowhead.com/quest=32711#comments:id=1825001",
        },
    },
    [32712] = {
        {
            id = 1832615,
            score = 3,
            author = "928574",
            text = "Rare in Throne of Thunder for quest. Stay spread to avoid an AoE attack, dispell as needed. Was pretty simple to burn down once we stopped stacking and survived the first surge.",
            date = "2013-03-22T01:01:00-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32712#comments:id=1832615",
        },
    },
    [32713] = {
        {
            id = 1834977,
            score = 19,
            author = "937813",
            text = "The name of the quest is (probably) a reference to an early \"Something Positive\" strip (http://www.somethingpositive.net/sp05032002.shtml), although the phrase has become a common feature of Internet discussions, particularly as related to tabletop gaming.",
            date = "2013-03-26T23:03:19-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32713#comments:id=1834977",
        },
        {
            id = 1841161,
            score = 14,
            author = "Malvenue",
            text = "Quest is offered after killing Tortos on the way down to the trash packs.  Killing Rocky Horror involved simply out-ranging his \"Horrifying Roar\" fear and healing through his stalatite throw.  Just clear a little extra trash to give yourself room so feared raid members don't pull other mobs.\n\nP.S. We didn't HAVE to but it just seemed appropriate to cast Time-Warp. Again. :D",
            date = "2013-04-09T20:28:29-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32713#comments:id=1841161",
        },
        {
            id = 2533379,
            score = 10,
            author = "674897",
            text = "If you do not see him immediately at the spot shown on the minimap, it is because he pats around. You can wait or go and find him.",
            date = "2017-11-06T00:09:58-06:00",
            sourceUrl = "https://www.wowhead.com/quest=32713#comments:id=2533379",
        },
        {
            id = 3170089,
            score = 1,
