            text = "Let's do....bloodlust.....again!",
            date = "2013-03-17T00:22:31-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32713#comments:id=1829910",
        },
    },
    [32714] = {
        {
            id = 1838205,
            score = 3,
            author = "Malvenue",
            text = "No'ku Stormsayer is a rare spawn who appears in the last full room before Council.  Dodge his Waves of Fury and move him out of the Lightning Cracks and he's a very simple miniboss.",
            date = "2013-04-02T19:47:58-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32714#comments:id=1838205",
        },
        {
            id = 1838275,
            score = 3,
            author = "Elapsed",
            text = "Is a super easy boss, do as they say stay out of the fissures and keep him out of them, dodge the waves (fairly easy) puts stacking debuff on tank which for easy stack increases the nature damage they take by 10%, we taunted at 80%",
            date = "2013-04-03T00:16:09-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32714#comments:id=1838275",
        },
        {
            id = 1838234,
            score = 0,
            author = "1104486",
            text = "Also you shouldn't stand near the Lightning Cracks either, they'll hurt a bit.",
            date = "2013-04-02T21:59:15-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32714#comments:id=1838234",
        },
    },
    [32715] = {
        {
            id = 1832365,
            score = 85,
            author = "592915",
            text = "I wonder if DrGraevling knows...",
            date = "2013-03-21T13:04:52-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32715#comments:id=1832365",
        },
        {
            id = 1834897,
            score = 32,
            author = "Malvenue",
            text = "Monara is a \"rare spawn\" banshee that takes the place of the first mechanical trash mob in the instance, after the first windy bridge. The quest is auto-offered when you first reach the bridge. She has the same abilities as the other banshees but has a brutal shadow nova that will knock you off the platform or kill you outright. It cannot be interrupted. The only counter is to run out of its range.  Just kite her around the platform avoiding the blue-column mobs and run out of her shadow nova range and the quest will auto-complete when she dies.",
            date = "2013-03-26T19:22:55-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32715#comments:id=1834897",
        },
        {
            id = 1836487,
            score = 18,
            author = "109015",
            text = "Don't be dumb and release like I did because \"its only trash\" I ended up not receiving credit for killing her.",
            date = "2013-03-30T00:04:14-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32715#comments:id=1836487",
        },
        {
            id = 1834910,
            score = 10,
            author = "UtesDad",
            text = "Take note that she can be kited all the way back to Jin'rokh the Breaker's room.  It made killing her a lot easier.  You still have to avoid the Shadow Nova, but you don't have to dodge the guys with the blue columns at all.",
            date = "2013-03-26T20:06:26-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32715#comments:id=1834910",
        },
        {
            id = 1835845,
            score = 5,
            author = "Hawkyyy",
            text = "All the posts saying you need to kite her are really unnecessary, just have tanks tank her in the middle of the platform and ranged around the side, move out for Shadow Nova then move back in, she took less than 1 minute to kill, very easy. Can even use timewarp/blood lust as you have more trash to clear after her as well before Horridon.\n\nShame only got gold from the reward :(",
            date = "2013-03-28T15:51:54-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32715#comments:id=1835845",
        },
    },
    [32716] = {
        {
            id = 1844011,
            score = 18,
            author = "Malvenue",
            text = "This quest auto-appears when you kill the first set of Durumu's trash.  In 10 man Normal, 4 rare spawn eyes appeared.  When you aggro one, they all aggro and start spamming arcane bolts at raid members that do tremendous splash damage (200k+).  Just before the bolts hit an arcane glow will appear at the feet of the target, allowing JUST enough time to move off it before getting hit.\n\nJust watch your feet while you dps and move when you see the glow.  Not hard at all.",
            date = "2013-04-16T21:22:25-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32716#comments:id=1844011",
        },
        {
            id = 1844044,
            score = 2,
            author = "Tyro",
            text = "Your tanks can get aggro on them and take the squint damage, your raid has to keep moving to avoid the volley.  The damage is pretty crazy compared to normal trash.",
            date = "2013-04-16T22:45:36-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32716#comments:id=1844044",
        },
        {
            id = 1844761,
            score = 2,
            author = "WoWman95",
            text = "Fairly easy. As other have said stay spead (lil harder for 25 lol). Smoke bomb helps for the 5 seconds, but use during the barrage. Other than that it simple. Awards a bag (more than likely containing gold as always...)",
            date = "2013-04-18T22:04:56-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32716#comments:id=1844761",
        },
        {
            id = 2512165,
            score = 1,
            author = "Barringa",
            text = "When you kill Durumu after doing this quest, you can see the four eyes spinning around the room before flying off to freedom somewhere.",
            date = "2017-08-05T08:49:34-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32716#comments:id=2512165",
        },
        {
            id = 1844010,
            score = -5,
            author = "switch89a",
            text = "My guild had a bit of trouble with this weekly. The trick to these eyes is the damage is split across players in a small range. Simply stack up to prevent quick death while avoiding the blue circles on the ground.",
            date = "2013-04-16T21:21:18-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32716#comments:id=1844010",
        },
    },
