    [32724] = {
    },
    [32726] = {
        {
            id = 1848243,
            score = 7,
            author = "1070146",
            text = "From what I can tell this is not a good way to level BS from zero.\n\nMany of the lower level ores are all over the place and no reason to waste money in the AH or a reason to waste such a large amount of ghost iron on things you cant get any kind of return from (from say Disenchanting them and selling the mats).\n\nWhat is good, is that the cross realm thing has created a farming nightmare for things like fel iron. So since the price per stack was the same I just went out and farmed Ghost Iron for my second BS to burn past Fel Iron without the headache of looking for enough on my miner.\n\nIts case by case. Checking AH prices for what you need compared to how easy it is to mine, ect.\nSometimes it is, sometimes its not.",
            date = "2013-04-29T11:04:30-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32726#comments:id=1848243",
        },
        {
            id = 1812819,
            score = 3,
            author = "332172",
            text = "In this current form, this does not make a lot of sense. Could it be possible that Blizzard is trying to provide for Blacksmith a catch-up mechanism similar to Cooking ?\n\nAlso, IMHO, secondary professions should be account-wide. There, I said it. :)",
            date = "2013-02-12T16:13:56-06:00",
            sourceUrl = "https://www.wowhead.com/quest=32726#comments:id=1812819",
        },
        {
            id = 1851083,
            score = 3,
            author = "iDelorean",
            text = "I just want to say:\n\nDon't bother turning this quest in. The key is worth more than the quest reward. I expected as much, but I just figured what the hell why not? If I could do it over again, I wouldn't have turned it in.\n\n94 Silver + 125 Guild Reputation.",
            date = "2013-05-08T02:28:56-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32726#comments:id=1851083",
        },
        {
            id = 1887639,
            score = 3,
            author = "PhantomScourge",
            text = "I made a ghostly skeleton key (or rather a few dozen) and didn't get credit. I then abandoned the quest, expecting to be able to re-accept it, but it was no longer offered. WTF Blizz.",
            date = "2013-08-16T18:41:25-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32726#comments:id=1887639",
        },
    },
