    [32729] = {
        {
            id = 1821573,
            score = 30,
            author = "strickn",
            text = "Don't be alarmed if you can't see https://www.wowhead.com/npc=70520 from afar. I thought the marker on the map was off, but until you enter the bounds of the shield around him he will not appear.\n\n/way 36.85 64.80 Halduron Brightwing",
            date = "2013-03-05T18:25:45-06:00",
            sourceUrl = "https://www.wowhead.com/quest=32729#comments:id=1821573",
        },
        {
            id = 1821591,
            score = 15,
            author = "907542",
            text = "He's outside the building, not inside, in a bubble @ 36.77 64.77\nThese bubbles are invisible but for a feint circular wall of light.\nThere are more dailies beside him",
            date = "2013-03-05T18:42:34-06:00",
            sourceUrl = "https://www.wowhead.com/quest=32729#comments:id=1821591",
        },
        {
            id = 1823484,
