    [32942] = {
        {
            id = 1924704,
            score = 3,
            author = "182693",
            text = "Here is a list of what you would need to buy/plant/harvest for each faction in the daily \"Work Order:\" quests.\n\nFaction........................Plant/Harvest 8/40\nDominance Offensive..Red Blossom Leek\nKlaxxi...........................Mogu Pumpkin\nShado-Pan..................Green Cabbage\nAugust Celestials.........Striped Melon\nGolden Lotus...............White Turnip\nSunreaver Onslaught..Scallion\n\nBe sure to ask Jogu the Drunk (http://www.wowhead.com/faction=1273) which crop to plant/will be producing extra the next day.  Doing so gives you the knowledge so you can yield some extra veggies in addition to the ones you use in completing these quests.",
            date = "2013-12-09T10:57:07-06:00",
            sourceUrl = "https://www.wowhead.com/quest=32942#comments:id=1924704",
        },
    },
    [32943] = {
        {
            id = 1898814,
            score = 7,
            author = "rogermw",
            text = "If you turn in this quest, and then do \"Work Order: Sunreaver Onslaught I\" the same day, you will NOT get offered this quest as a follow up.\n\nDon't despair and dig up your crops, though! You will get re-offered this quest on the following day from the empty crate in one corner of Sunsong Ranch.  It will have a blue ! over it.\n\n(IMPORTANT NOTE: As of 5.4, the get-the-quest-automatically-by-harvesting-a-crop mechanism seems to be broken. You have to click on the empty crate with the blue ! over it instead.  If you accidentally harvest even one of your crops first, you won't be able to complete this quest that day!)",
            date = "2013-09-16T09:57:39-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32943#comments:id=1898814",
        },
    },
