    [32974] = {
        {
            id = 1880885,
            score = 215,
            author = "Voxxel",
            text = "The first clue is a mound of dirt at 49.4-69.4 (http://www.wowhead.com/maps?data=6757:494694). Get close to it and you will be able to hand-in the quest.\nAlso, don't forget to pick up the next part: https://www.wowhead.com/quest=32975.\n\nVideo guide: http://www.youtube.com/watch?v=wfeW1_WZvT8",
            date = "2013-07-26T04:43:24-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32974#comments:id=1880885",
        },
        {
            id = 1943916,
            score = 112,
            author = "yzerman",
            text = "Ok, so many videos, not enough text guides.\n\nFirst, to start this quest, you need to pickup the quest item called Rolo's Riddle (http://www.wowhead.com/item=102225). These can be found inside Glinting Sand (http://www.wowhead.com/object=222684) (about a 3% chance according to wowhead) which are dark piles of sand all around the Isle.\n\nOnce you start that, you need to go to a mound of dirt underneath the chest atop the 4 pillars at about 49,68. This is the first clue.\n\nOnce you pick that up, head behind the terrace where Archiereus of Flame is summoned. There is a large rock with another mound of dirt next to it at around 34,25. This is the 2nd clue.\n\nNext just head to the area in front of the celestials, and use a ranged attack on the Highwind Albatross. Once you are picked up by one, let it take you above the water at around 65,24. As soon as you are safely over the water, start killing the Albatross. This will stop it from moving, and it will not attack back. Once the Albatross is dead, it will drop you, hopefully over the water. Once you have landed safely, head behind the large tree to the north of the lake. You will see a large chest. This chest is Rolo's 3rd clue, and the final part of the quest.",
            date = "2014-02-16T13:00:43-06:00",
            sourceUrl = "https://www.wowhead.com/quest=32974#comments:id=1943916",
        },
        {
            id = 1905934,
            score = 88,
            author = "ghostiron",
            text = "if you want to know if you already did this quest on a particular character type (copy and paste):\n\n/run print(IsQuestFlaggedCompleted(32974))\n\nif the answer is \"nil\" you have not done it,\nif the answer is \"1\" you have done it",
            date = "2013-10-06T03:18:20-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32974#comments:id=1905934",
        },
        {
            id = 1894986,
            score = 68,
            author = "322702",
            text = "Because no one else has said it yet, it is right next to the jumping puzzle. Under the shortest pillar.",
            date = "2013-09-11T01:01:46-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32974#comments:id=1894986",
        },
        {
            id = 1897847,
            score = 68,
            author = "Bodomi",
            text = "First Clue: http://www.wowhead.com/maps?data=6757:492685\nCoords for Clue 1: 49.2, 68.5\nSecond Clue: http://www.wowhead.com/maps?data=6757:344258\nCoords for Clue 2: 34.4, 25.8\nThird Clue: http://www.wowhead.com/maps?data=6757:656233\nCoords for Clue 3: 65.6, 23.3\n\nI show in the video below how to get to the last Clue.\nIf you do not wish to use my way and use the ''Normal'' Albatross way, there is tons of videos on YouTube showing how.\n\nVideo guide I have made showing how to get to the last clue: http://www.youtube.com/watch?v=8wRIDgeVYjQ\n\nThere is also a rare spawn up at the point where the last cluse is called Garnia (http://www.wowhead.com/npc=73282/garnia) which drops a pet, SO GET TO THAT FARMING BOY!",
            date = "2013-09-14T12:52:52-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32974#comments:id=1897847",
        },
    },
    [32975] = {
        {
            id = 1880931,
            score = 165,
            author = "Voxxel",
            text = "The second clue is at 34.6 -26.7 (http://www.wowhead.com/maps?data=6757:346267) @ the Three-Breeze terrace.\n\nVideo guide: http://www.youtube.com/watch?v=wfeW1_WZvT8",
            date = "2013-07-26T07:53:06-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32975#comments:id=1880931",
        },
        {
            id = 1894674,
            score = 77,
            author = "10501",
            text = "TomTom:\n\n/way 34.5, 26.4 2nd Clue Rolo's Riddle\n\nMap:\nhttp://www.wowhead.com/maps?data=6757:341260",
            date = "2013-09-10T16:17:30-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32975#comments:id=1894674",
        },
        {
            id = 1902927,
            score = 52,
            author = "Bodomi",
            text = "First Clue: http://www.wowhead.com/maps?data=6757:492685\nCoords for Clue 1: 49.2, 68.5\nSecond Clue: http://www.wowhead.com/maps?data=6757:344258\nCoords for Clue 2: 34.4, 25.8\nThird Clue: http://www.wowhead.com/maps?data=6757:656233\nCoords for Clue 3: 65.6, 23.3\n\nI show in the video below how to get to the last Clue.\nIf you do not wish to use my way and use the ''Normal'' Albatross way, there is tons of videos on YouTube showing how.\n\nVideo guide I have made showing how to get to the last clue: http://www.youtube.com/watch?v=8wRIDgeVYjQ\n\nThere is also a rare spawn up at the point where the last cluse is called Garnia (http://www.wowhead.com/npc=73282/garnia) which drops a pet, SO GET TO THAT FARMING BOY!",
            date = "2013-09-26T09:28:06-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32975#comments:id=1902927",
        },
        {
            id = 1896391,
            score = 12,
            author = "945451",
            text = "it's behind the pillar on the other side of the entrance of the Three-Breeze terrace, so just go straight ahead round that big stone-pillar.",
            date = "2013-09-12T11:37:36-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32975#comments:id=1896391",
        },
        {
            id = 1961970,
            score = 7,
            author = "joeartguy",
            text = "For those classes and specs without some kind of stealth (like my Death Knight), there's an easy method.\n\nThe inlet just west of Three-Breeze Terrace has several Ancient Spineclaws (npc=72766) in it, as does the ocean right next to your faction base. Just kill the spineclaws -- they count toward the daily Path of the Mistwalker (quest=33374) of course -- until you get a Scuttler's Shell (item=104293). (The drop rate is about 10%, so you probably won't have to kill more than a dozen or so.)\n\nThe Scuttler's Shell (item=104293) reduces your aggro radius to around the size of your hitbox, so you can simply ride through Three-Breeze Terrace -- or anywhere else for that matter -- as though you were stealthed to the NPCs.",
            date = "2014-04-29T02:50:32-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32975#comments:id=1961970",
        },
    },
    [32976] = {
        {
            id = 1880920,
            score = 528,
            author = "Voxxel",
            text = "The final treasure you're looking for is high up at the bloody lake where https://www.wowhead.com/npc=73282 lives. (Coords: 64.5 - 27.5 (http://www.wowhead.com/maps?data=6757:645275))\n\nTo get there use the Albatross Taxi Service:  Move to 33.3 - 55.3 (http://www.wowhead.com/maps?data=6757:333553) (the entrance of Celestial arena). Once there, check the sky and wait for a https://www.wowhead.com/npc=73531 arriving. Hit the bird once then press Escape to stop autoattack. It will pick you up to the sky and transport above the whole isle.\nAt 64.5 - 27.5 (http://www.wowhead.com/maps?data=6757:645275) above the Ruby Lake (the reddish tarn on the map) begin to attack your Albatross again. The bird will instantly dive and releases you as you kill it. Swim out of the red pool and go up to the tree. You'll find the final treasure right there.\n\nVideo guide:\n\nIntended method: http://www.youtube.com/watch?v=JUTksV7Db5o\nAlbatross-free method: http://www.youtube.com/watch?v=wfeW1_WZvT8 - make sure you use https://www.wowhead.com/item=104346 instead of freefall if you don't want to look like an egg omelet.",
            date = "2013-07-26T07:16:39-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32976#comments:id=1880920",
        },
        {
            id = 1900175,
            score = 114,
            author = "WizzardlordUK",
            text = "TomTom\n\n/way 49, 69 - 1st Clue\n/way 34, 26 - 2nd Clue\n/way 66, 23 - Last Clue\n\nAlbatross\n/way 35, 56 - Albatross\n\nChests\n/way 26, 64 - Chest\n/way 28, 35 - Chest\n\nto get to last clue at the Ruby Lake (66, 26) you can use a https://www.wowhead.com/npc=73531 at the celestial grounds (best place to wait is on the right side of the steps 35, 56) just wait for one to be low enough for you to be able to hit it then stop attacking , it will then pick you up and fly you round the island (It's a bit of a slow ride). Attacking it while riding it will make it stop in mid air, you will probably find it easier to knock most of it's hp off before you get to the red lake leaving just enough for 1 or 2 hits. if you haven't been on an https://www.wowhead.com/npc=73531 before you will also notice you pass a chest on the peak of one of the hills (26, 64) there is also another chest after the red lake (28, 35) .\n\nnote: all clues are by trees,",
            date = "2013-09-19T11:51:34-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32976#comments:id=1900175",
        },
        {
            id = 1894874,
            score = 112,
            author = "Nyctalops",
            text = "Here's an albatross-free method:\n\nI went to the north east edge of the isle's coast--close to the red lake--and swam out just far enough to leave the zone into the Time-Lost Waters zone.  Fatigue should set in, but you'll have plenty of time to summon a flying mount and get high up in the air (the https://www.wowhead.com/spell=145389 buff may not drop, but I was able to fly anyhow). Then fly towards the lake. You'll get dismounted as you re-enter the zone, but you can use some form of slow fall (I used my incredibly handy https://www.wowhead.com/spell=126392) to float the rest of the way in.",
            date = "2013-09-10T22:06:58-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32976#comments:id=1894874",
        },
        {
            id = 1902928,
            score = 69,
            author = "Bodomi",
            text = "First Clue: http://www.wowhead.com/maps?data=6757:492685\nCoords for Clue 1: 49.2, 68.5\nSecond Clue: http://www.wowhead.com/maps?data=6757:344258\nCoords for Clue 2: 34.4, 25.8\nThird Clue: http://www.wowhead.com/maps?data=6757:656233\nCoords for Clue 3: 65.6, 23.3\n\nI show in the video below how to get to the last Clue.\nIf you do not wish to use my way and use the ''Normal'' Albatross way, there is tons of videos on YouTube showing how.\n\nVideo guide I have made showing how to get to the last clue: http://www.youtube.com/watch?v=8wRIDgeVYjQ\n\nThere is also a rare spawn up at the point where the last cluse is called Garnia (http://www.wowhead.com/npc=73282/garnia) which drops a pet, SO GET TO THAT FARMING BOY!",
            date = "2013-09-26T09:32:02-05:00",
            sourceUrl = "https://www.wowhead.com/quest=32976#comments:id=1902928",
        },
        {
            id = 2446285,
            score = 36,
            author = "Duxjan",
            text = "As of Legion it's pretty easy to get up there without the birds.\n\nBuy a https://www.wowhead.com/item=109076 from the Auction House.\n\nRun up the the road (Blazing Way) all up to the Crane statue. (it's right after you cross the bridge on left hand side).\nClick the statue.\nYou will get an option to \"touch the statue\".\nAfter been shot into mid-air, clear the buff by right clickin it.\n\nEDIT: You have to clear the buff, otherwise your glider will be slowed down and you won't make it to the top of the hill!\n\nImmediately after clearing the buff deploy your https://www.wowhead.com/item=109076 and glide to the Ruby Lake on top of the mountain (North East).\n\nDon't make the same mistake I made: complete the 2nd clue quest first! https://www.wowhead.com/quest=32975\nIf you don't, the treasure will not unlock.\n\nHappy flying!",
            date = "2016-11-19T15:47:05-06:00",
            sourceUrl = "https://www.wowhead.com/quest=32976#comments:id=2446285",
        },
    },
