        },
        {
            id = 2263517,
            score = 12,
            author = "LiriellGarrosh",
            text = "The quest from Elder Liao (and probably his Alliance counterpart) for 3 Warforged Seals is now repeatable as many times as you like (limited only by your stash of Lesser Charms of Good Fortune), and is no longer limited to once a week.",
            date = "2015-10-16T16:50:09-05:00",
