        },
        {
            id = 1875049,
            score = 7,
            author = "TheStatman",
            text = "Edit: As of the July 17th PTR patch this HAS changed to the new Bonus Coin for SoO and the Celestial World bosses.\n\nThis is a copy of a quest already available. Its possibly just a placeholder for the 5.4 version of the Bonus Loot Coin weekly quest, which likely rewards a new type of coin for the Siege of Orgrimmar.",
            date = "2013-07-09T04:06:47-05:00",
