            id = 1875048,
            score = 3,
            author = "TheStatman",
            text = "Edit: As of the July 17th PTR patch this HAS changed to the new Bonus Coin for SoO and the Celestial World bosses.\n\nThis is a copy of a quest already available. Its possibly just a placeholder for the 5.4 version of the Bonus Loot Coin weekly quest, which likely rewards a new type of coin for the Siege of Orgrimmar.",
            date = "2013-07-09T04:05:26-05:00",
            sourceUrl = "https://www.wowhead.com/quest=33134#comments:id=1875048",
        },
        {
            id = 1915079,
            score = 3,
            author = "Etreum",
            text = "Shrine of Seven Stars as shown in the map here, is Alliance only.  Go in, you die!\n\nYou should go to Shrine of Two Moons if you are Horde.",
            date = "2013-11-05T06:36:34-06:00",
