    [33138] = {
        {
            id = 1874853,
            score = 82,
            author = "Nulgar",
            text = "[table width=23em][tr][td]\nWhy do we fight?\nTo protect home, and family.\nTo preserve balance, and bring... harmony.\n\nFor my kind, the true question is:\nWhat is worth fighting for?[/td][/tr]\n[tr][td align=right]-Chen Stormstout (http://www.youtube.com/watch?v=wvYXoyxLv64)[/td][td] [/td][/tr][/table]",
            date = "2013-07-08T12:12:49-05:00",
            sourceUrl = "https://www.wowhead.com/quest=33138#comments:id=1874853",
        },
        {
            id = 1912369,
            score = 45,
            author = "Mormolyce",
            text = "And so now we know... why we fight.\n\nWonderfully bookends the expansion.\n\nP.S. I used to do a pet battle daily here... *sob*",
            date = "2013-10-27T02:06:23-05:00",
            sourceUrl = "https://www.wowhead.com/quest=33138#comments:id=1912369",
        },
        {
            id = 1906826,
            score = 39,
            author = "Whiterock",
            text = "After turning in https://www.wowhead.com/quest=33138:\n\nhttps://www.wowhead.com/npc=73136 says: Dear Emperor. It is done. The darkness that you once struggled against has been purged from Pandaria - forever.\nLorewalker Cho says: But the cost... such a terrible cost.\nEmperor Shaohao says: Do not despair the damage that was done here.\nEmperor Shaohao says: You triumphed over the darkness I had locked away.\nEmperor Shaohao says: You have shown Pandaria the power of a true hero.\nEmperor Shaohao says: But the question still remains... why do we fight?\nEmperor Shaohao says: I trust you have learned: to fight out of fear or anger is to fight a war that never ends.\nEmperor Shaohao says: Face your fears. Calm your hatreds.\nEmperor Shaohao says: find peace within yourself, so that you may share it with the world around you.\nEmperor Shaohao says: These are the greatest treasures in life.\nEmperor Shaohao says: Surely they... are worth fighting for.\nLorewalker Cho says: Thank you... emperor. Thank you.\n\nhttps://www.wowhead.com/npc=73136 says:\nWhat you have achieved today will shape the face of Pandaria for thousands of years to come.\n\nThank you, hero. The Lorewalkers shall pass your story down from generation to generation.",
            date = "2013-10-08T17:24:27-05:00",
            sourceUrl = "https://www.wowhead.com/quest=33138#comments:id=1906826",
        },
        {
            id = 1961668,
            score = 30,
            author = "Mist2489",
            text = "While I had already thought this was a great expansion from the get-go, I feel this really tied the whole storyline together with an epic conclusion. I applaud, Blizzard. Let's hope for an even better ending come Warlords of Draenor!",
            date = "2014-04-28T00:20:34-05:00",
            sourceUrl = "https://www.wowhead.com/quest=33138#comments:id=1961668",
        },
        {
            id = 1911433,
            score = 29,
            author = "941372",
            text = "After the cutscene, two headstones (one for Horde, the other for Alliance) appear. From these, you can watch the end Cutscene for each faction from Siege of Orgrimmar.",
            date = "2013-10-23T15:12:04-05:00",
            sourceUrl = "https://www.wowhead.com/quest=33138#comments:id=1911433",
        },
    },
    [33147] = {
        {
            id = 1911175,
            score = 46,
            author = "Deathnotez",
            text = "I got this today in LFR Siege of Orgrimmar. October 22, 2013. Whatever you do, DON'T leave without turning this in. You can only turn it in RIGHT AFTER you kill Garrosh, can't just give it to Loremaster Cho anytime during the raid.\n\nEdit; you don't really kill Garrosh but he is unconscious, as his health bar says. But you can use [item=90175 domain=www] and [item=88589 domain=www] on his body, technically killing him though!\n\nEdit #2: How embarrassing, forgot to say KILL Garrosh.",
            date = "2013-10-22T15:27:23-05:00",
            sourceUrl = "https://www.wowhead.com/quest=33147#comments:id=1911175",
        },
        {
            id = 3230405,
            score = 32,
            author = "cephadex",
            text = "If you soloed this raid on mythic difficulty (mythic SoO = what was called heroic SoO during MoP), and at the end stood there wondering how exactly you're meant to get back to the Inner Sanctum from Stormwind, in order to turn in the quest to Lorewalker Cho... then maybe you're like me, and Garrosh just happened to fall right on top of the portal that can take you back to the Inner Sanctum. This happened to me, and so Garrosh had obscured the portal-- so I had no idea that there was a portal and just kept running around trying to figure out how to get back. If you also can't see a portal anywhere, try hovering your cursor over Garrosh-- and eventually you will see a speech bubble (ie, your cursor will be over where the portal is, which is obscured by Garrosh). Click that and you will be transported back.",
            date = "2020-09-15T16:59:00-05:00",
            sourceUrl = "https://www.wowhead.com/quest=33147#comments:id=3230405",
        },
        {
            id = 1906504,
            score = 15,
            author = "alexeht",
            text = "If your raid leader is not a nice guy and destroy raid after killing Garrosh(or if you just leave), you will not be able to finish quest if you get away from instance as all NPC despawn (I go back to raid, and whole room was empty).",
            date = "2013-10-07T16:21:31-05:00",
            sourceUrl = "https://www.wowhead.com/quest=33147#comments:id=1906504",
        },
        {
