    [33160] = {
        {
            id = 3303111,
            score = 5,
            author = "auryunderground",
            text = "When turning in the quest a mini-dialogue plays out between https://www.wowhead.com/npc=72870 and https://www.wowhead.com/npc=73061.\n\nAnduin Wrynn says: What IS this place?\n\nKairoz says: A pandaren enigma, my young prince! A mystery in the mists.\n\nAnduin Wrynn says: I've been here for hours and the sun hasn't moved...\n\nKairoz says: Exactly. Time is frozen in perpetuity. Cause and effect - rendered all but meaningless.\n\nAnduin Wrynn says: What could create such a thing?\n\nKairoz says: I should like to find out! Perhaps it is related to the mists? Or the power that was unleashed in the sundering ten thousand years ago? We must investigate!\n\nAnduin Wrynn says: Is it dangerous?\n\nKairoz says: Indeed. This place overturns our very notion of time, and how it shapes the universe.\nKairoz says: Stranded on this island you will find the most dangerous creatures in all of Pandaria. Explore if you must, Prince Anduin. But be cautious.\n\nAnduin Wrynn says: I will.",
            date = "2021-02-22T02:13:27-06:00",
            sourceUrl = "https://www.wowhead.com/quest=33160#comments:id=3303111",
        },
        {
            id = 1899961,
            score = 3,
            author = "1135875",
            text = "If anyone has trouble finding it because your map isn't working the cords are 34.6, 53.5",
            date = "2013-09-18T21:04:14-05:00",
            sourceUrl = "https://www.wowhead.com/quest=33160#comments:id=1899961",
        },
    },
    [33161] = {
        {
            id = 2018739,
            score = 142,
            author = "sanastro",
            text = "As of 6.0.2, the Firewalker Ruins zone only consists of a single, thin strip of land at the gate leading up to the usual Firewalker Ruins.",
            date = "2014-10-25T03:58:55-05:00",
            sourceUrl = "https://www.wowhead.com/quest=33161#comments:id=2018739",
        },
        {
            id = 2351823,
            score = 51,
            author = "Peter4730",
            text = "FIREWALKER RUINS\nFrom the comments and video above, I finally worked out as follows.\n1) Approach from OldPijiu i.e. heading NorthEast\n2) You  come to a big stone gate, with a L91 guard at each side\n3) When you are, say, 10 yards from  the guards, get off your mount.  Approach on FOOT (I had tried this same route before while mounted, and did NOT get the ach)\n4) In my successful experience, I didn't even have to pass through the gate to get the achievement\n5) Naturally, by now you have got two L91 guards on you, so prepare to fight.\n6) So, all my previous attempts at running around inside the FW/R area, were in vain.\n\nHope this helps",
            date = "2016-07-16T23:35:31-05:00",
            sourceUrl = "https://www.wowhead.com/quest=33161#comments:id=2351823",
        },
        {
            id = 5868438,
            score = 34,
            author = "Jeolene",
            text = "Quest is STILL broken when trying to get credit for Firewalker Ruins, I only got credit when running AWAY from it through the main stone gate heading toward Old Pijiu",
            date = "2024-05-29T11:40:42-05:00",
            sourceUrl = "https://www.wowhead.com/quest=33161#comments:id=5868438",
        },
        {
            id = 1911568,
            score = 22,
            author = "Draewind",
            text = "Tom Tom:\nfrom above\n\n/way 41.8, 42.9 [Cavern of Lost Spirits]\n/way 29.4, 28.9 [Misty Strand]\n/way 67.6, 66.7 [Croaking Hollow]\n/way 53.7, 67.1 [Red Stone Run]\n/way 37.3, 72.2 [Old Pi'jiu]\n/way 47.2, 78.5 [Firewalker Ruins]",
            date = "2013-10-24T04:33:21-05:00",
            sourceUrl = "https://www.wowhead.com/quest=33161#comments:id=1911568",
        },
