    [33229] = {
        {
            id = 1895982,
            score = 38,
            author = "IhaveNoLife",
            text = "Copypasted from my previous comment on https://www.wowhead.com/quest=32892\n\nMishi will not offer you a quest until you have certain prerequisites. However, fear not! This strategy will allow you to get up to Chromie without flying in Pandaland or doing the annoying quest/rep grinds to talk to Mishi.\n\n1: Delete your hearthstone. (This step not necessary if your hearth is on cooldown already)\n2: Go to the Mogu'shan Palace instance portal. (Not inside of it)\n3: Use the auto-unstuck feature (Customer Support>Character Stuck!>Teleport to Graveyard. If you still have your hearthstone and it's off cooldown, the teleport to graveyard will simply use your hearthstone. This is why you delete your hearthstone.)\n4: Release your spirit. You will now be mounted on a spectral gryphon. See where I'm going with this?\n5: You can't go straight up to Lorewalker Cho, the distance between the balcony and your corpse is too great. However, you are able to resurrect on that little alcove above Mogu'shan. Resurrect here (the topmost ledge is probably too far to accept your corpse, so just resurrect on one of the lower shelves)\n6: Use the auto-unstuck feature again, preferably on the topmost shelf, but I'm not sure if that part is necessary.\n7: You're back on the spectral gryphon. Fly to balcony where Cho is, and accept your rez.\n8: Congratulations! You can now turn in this obnoxious quest. Don't forget to set your hearth back to your faction's shrine when you're done.\n\nJust as a note, using the auto-unstuck feature will NOT result in a repair bill.",
            date = "2013-09-11T23:38:30-05:00",
            sourceUrl = "https://www.wowhead.com/quest=33229#comments:id=1895982",
        },
        {
            id = 1894950,
            score = 11,
            author = "Shadowstaff",
            text = "For anyone who comes here asking why they didn't get this quest:\n\nI've received this quest on all of my characters, except the one character what went to the Timeless Isle FIRST before entering the Vale. I am assuming if you've entered the Timeless Isle by flying across the Fatigue area, you won't receive this quest.\n\nHowever, if I remember correctly, you still get the 100 Coins for meeting https://www.wowhead.com/npc=72870, because https://www.wowhead.com/npc=64616 gives you a quest to meet him.",
            date = "2013-09-11T00:07:21-05:00",
            sourceUrl = "https://www.wowhead.com/quest=33229#comments:id=1894950",
        },
        {
            id = 1932739,
            score = 8,
            author = "Stjimmy",
            text = "Funny, if you went to the Timeless Isle without turning in this quest beforehand, she'll mention something else than her usual dialog.\n\nChromie says: Ah! I was sent here to guide you to the Timeless Isle, but I see you have already made the voyage. I fear I have gotten tangled up in the timeways again.\nChromie pulls out a bronze timepiece, shakes it, and squints at the dial. She seems somewhat embarassed.",
            date = "2014-01-08T07:55:33-06:00",
            sourceUrl = "https://www.wowhead.com/quest=33229#comments:id=1932739",
        },
        {
            id = 3200963,
            score = 7,
            author = "mariekr",
            text = "Post BFA, in order to see Chromie you must speak to Zidormi (80.99, 29.50) and ask her to show you what the Vale was like before the Black Empire Assault.\nChromie will then appear near Mishi, around 80.7, 33.13 .\nYou can accept her quest, then talk to Zidormi to return to the present and head to the Timeless Isle.",
            date = "2020-04-19T17:27:15-05:00",
            sourceUrl = "https://www.wowhead.com/quest=33229#comments:id=3200963",
        },
        {
            id = 3192193,
            score = 5,
            author = "LaffiBoozegnome",
            text = "26.02.2020.\n\nI did NOT visited the Timeless Isle prior to entering Valley of Eternal Blossoms and Shrine of Seven Stars. I also had space in my questlog for any quests that would pop up. It did not.\n\nIt did not pop up on some other characters that visited the same zones/places either.\n\nIf someone can confirm that they got the quest automaticly after entering alley of Eternal Blossoms and Shrine of Seven Stars please write it in the comments.",
            date = "2020-02-26T09:05:02-06:00",
            sourceUrl = "https://www.wowhead.com/quest=33229#comments:id=3192193",
        },
    },
    [33230] = {
        {
            id = 1895978,
            score = 81,
            author = "IhaveNoLife",
            text = "Copypasted from my previous comment on https://www.wowhead.com/quest=32892\n\nMishi will not offer you a quest until you have certain prerequisites. However, fear not! This strategy will allow you to get up to Chromie without flying in Pandaland or doing the annoying quest/rep grinds to talk to Mishi.\n\n1: Delete your hearthstone. (This step not necessary if your hearth is on cooldown already)\n2: Go to the Mogu'shan Palace instance portal. (Not inside of it)\n3: Use the auto-unstuck feature (Customer Support>Character Stuck!>Teleport to Graveyard. If you still have your hearthstone and it's off cooldown, the teleport to graveyard will simply use your hearthstone. This is why you delete your hearthstone.)\n4: Release your spirit. You will now be mounted on a spectral gryphon. See where I'm going with this?\n5: You can't go straight up to Lorewalker Cho, the distance between the balcony and your corpse is too great. However, you are able to resurrect on that little alcove above Mogu'shan. Resurrect here (the topmost ledge is probably too far to accept your corpse, so just resurrect on one of the lower shelves)\n6: Use the auto-unstuck feature again, preferably on the topmost shelf, but I'm not sure if that part is necessary.\n7: You're back on the spectral gryphon. Fly to balcony where Cho is, and accept your rez.\n8: Congratulations! You can now turn in this obnoxious quest. Don't forget to set your hearth back to your faction's shrine when you're done.\n\nJust as a note, using the auto-unstuck feature will NOT result in a repair bill.",
            date = "2013-09-11T23:36:17-05:00",
