        },
        {
            id = 1895449,
            score = 32,
            author = "Stjimmy",
            text = "Funny, if you went to the Timeless Isle without turning in this quest beforehand, she'll mention something else than her usual dialog.\n\nChromie says: Ah! I was sent here to guide you to the Timeless Isle, but I see you have already made the voyage. I fear I have gotten tangled up in the timeways again.\nChromie pulls out a bronze timepiece, shakes it, and squints at the dial. She seems somewhat embarassed.",
            date = "2013-09-11T11:34:19-05:00",
            sourceUrl = "https://www.wowhead.com/quest=33230#comments:id=1895449",
        },
        {
            id = 1894494,
            score = 13,
            author = "Turpentine",
            text = "To get this quest you will have to travel to your faction respective capital in Pandaria and then the quest will be auto-accept (Horde:Shrine of 2 Moons, Alliance: Shrine of the 7 Stars).\n\nVisiting Stormwind or Orgimmar will not give you this quest.",
            date = "2013-09-10T13:08:18-05:00",
            sourceUrl = "https://www.wowhead.com/quest=33230#comments:id=1894494",
        },
        {
            id = 1894689,
            score = 10,
            author = "492004",
            text = "So, If you Don't have pandaland flying, how do you get to Chromie?\n\nMishi just looks at me inquisitively.\n\n-_-",
            date = "2013-09-10T16:36:50-05:00",
