    [33231] = {
        {
            id = 1894457,
            score = 21,
            author = "Henderman",
            text = "Use the Curious Bronze Timepiece (http://www.wowhead.com/item=104113) that Chromie gives you to teleport to the Timeless Isle.",
            date = "2013-09-10T12:36:44-05:00",
            sourceUrl = "https://www.wowhead.com/quest=33231#comments:id=1894457",
        },
        {
            id = 1974751,
            score = 5,
            author = "275792",
            text = "What the guy above is saying is that after you use the Timepiece to teleport to the Timeless Isle, you can abandon the quest and the next time you want to go to the Isle you'll just pick up the quest at the mogu'shan palace and you can teleport with it over and over, if you never turn the quest in. All you have to do is re-take the quest.",
            date = "2014-06-24T14:07:59-05:00",
            sourceUrl = "https://www.wowhead.com/quest=33231#comments:id=1974751",
        },
        {
            id = 2470337,
            score = 3,
            author = "1645903",
            text = "Haven't seen this debated yet, but I honestly don't think it's worth abandoning the quest just to get the teleporting item.   >_<\n\nAfter completing the quests you get a flight path to the island. If you wanted to retake the quest for the Curious Bronze Timepiece you're going to need to get to pandaria, then fly all the way to Shrine of Two Moons just to pick it up each time.",
            date = "2017-02-06T23:06:39-06:00",
            sourceUrl = "https://www.wowhead.com/quest=33231#comments:id=2470337",
        },
        {
            id = 2557721,
            score = 3,
            author = "Itsversayce",
            text = "As [zone=6757] now scales from 85-90, you can now pick this quest up at Level 85. However, https://www.wowhead.com/item=104113 requires Level 90. If you want to visit Timeless Isle before then, you'll have to fly there on your own.",
            date = "2018-03-13T14:33:06-05:00",
            sourceUrl = "https://www.wowhead.com/quest=33231#comments:id=2557721",
        },
        {
            id = 5910417,
            score = 3,
            author = "Frehk",
            text = "Players who don't want to bother with repeatedly visiting Chromie for the teleport quest can buy the [item=219222 domain=www] from [npc=73306 domain=www] at the Timeless Isle next to [npc=73303 domain=www].\n\nIn-Game script for location of Shaohao:\n\n/script DEFAULT_CHAT_FRAME:AddMessage(\"\\124cffffff00\\124Hworldmap:554:4280:5520\\124h[\\124A:Waypoint-MapPin-ChatIcon:13:13:0:0\\124a Emperor Shaohao (Timeless Isle) Map Pin]\\124h\\124r\");",
            date = "2024-08-01T11:45:28-05:00",
            sourceUrl = "https://www.wowhead.com/quest=33231#comments:id=5910417",
        },
    },
