    [33239] = {
        {
            id = 1896042,
            score = 24,
            author = "Alaurynn",
            text = "This repeatable quest is started by Pristine Firestorm Eggs (http://www.wowhead.com/item=104257) which can be found in various places around the northern cliffs of Timeless Isle (http://www.wowhead.com/zone=6757/timeless-isle). They also have a very small chance (1.65%) to drop off of Crimsonscale Firestorm (http://www.wowhead.com/npc=72876/crimsonscale-firestorm) serpents. Turn them in to Great Chef Woo (http://www.wowhead.com/npc=73657) at (41.8,63.7) in exchange for 500 Timeless Coins (http://www.wowhead.com/currency=777). She accepts four other items as well, but they are more common and give far fewer coins than the Pristine Firestorm Eggs.\n\nSome eggs are located in places that cannot be reached without a flying mount. Since flying is prohibited on the isle, you can catch a ride on a Highwind Albatross (http://www.wowhead.com/npc=73531) and then drop down to grab your egg. Read more about flying Albatross Airlines here (http://www.wowhead.com/npc=73531#comments).\n\nNOTE: Not to be mistaken for Quivering Firestorm Egg (http://www.wowhead.com/item=104286) which has the same icon, and is found in the same places.",
            date = "2013-09-12T01:05:02-05:00",
            sourceUrl = "https://www.wowhead.com/quest=33239#comments:id=1896042",
        },
    },
    [33250] = {
        {
            id = 1899089,
            score = 134,
            author = "Aliandrin",
            text = "I thought I was getting a mount (or at least a pet).\n\nThen that fat panda just ate that egg. All I got was a couple gold.\n\nWarning: If you are already exalted with the order of the Cloud Serpent, send the egg to another character on your account. You can do that. There is no reward for this quest except the reputation and the obligatory max-level gold.",
            date = "2013-09-17T00:51:42-05:00",
            sourceUrl = "https://www.wowhead.com/quest=33250#comments:id=1899089",
        },
        {
            id = 1884168,
            score = 39,
            author = "ED209",
            text = "A new way to gain additional reputation in the Siege of Orgrimmar patch. It drops from some mobs on the Blazing Way on the eastern section of the Timeless Isle (http://ptr.wowhead.com/zone=6757), specifically Crimsonscale Firestorms (http://ptr.wowhead.com/npc=72876) and Huolon (http://ptr.wowhead.com/npc=73167), a rare elite who can also drop a cloud serpent mount ( [item=104269 domain=www]).\nThis quest is a catch-up for Order of the Cloud Serpent (http://www.wowhead.com/faction=1271) reputation, and is essential for any alts that have just entered Pandaria, or for mains that just haven't bothered with the faction.",
            date = "2013-08-05T09:19:51-05:00",
            sourceUrl = "https://www.wowhead.com/quest=33250#comments:id=1884168",
        },
        {
            id = 1897691,
            score = 21,
