    [33341] = {
        {
            id = 1894542,
            score = 117,
            author = "Centrisian",
            text = "Data about active shrines\n\nWayshrines activate roughly every 10 minutes, and are clickable by only one person per activation. Being in a group (not raid) will grant credit for the quest if one person clicks the wayshrine.\n\nThese are used for this quest as well as https://www.wowhead.com/achievement=8724, granting one of four buffs, or causing a massive fire AoE that will pull nearby enemies.\n\nThe buffs and quotes for each are:\n\nhttps://www.wowhead.com/spell=147281 \"Though blood floods the ground, the mountain is unmoved.\"\nhttps://www.wowhead.com/spell=147282 \"The truth shines brightest in clouded times.\"\nhttps://www.wowhead.com/spell=147283 \"Hope's fire grows when the flames come together.\"\nhttps://www.wowhead.com/spell=147284 \"Strength and power are as different as sun and moon.\"\n\nThe AoE is\n\nhttps://www.wowhead.com/spell=147285 \"The shrine was corrupted by Ordos!\"\n\nLocations\n\nWayshrine Map (http://www.wowhead.com/maps?data=6757:350294280721267522581467498702434559375742228293302455662723639506530608) courtesy of halesgrim\n\nThree-Breeze Terrace 35.04, 29.45\nSoutheast of Tushui Landing 28.01, 72.08\nThe Timeless Shore 26.69, 52.15\nRed Stone Run 58.11, 46.66\nSouth of Mossgreen Lake 49.80, 70.15\nThe Celestial Court 43.41, 55.88\nOld Pi'jiu 37.52, 74.19\nThe Misty Strand 22.83, 29.31\nWest of Celestial Court 30.19, 45.53\nCroaking Hollow 66.18, 72.31\nWhispershade Hollow 63.89, 50.60\nEast of Mossgreen Lake 53.00, 60.79\n\nThanks to lichee for reminding me about TomTom,\n\nTomTom Coordinates in easy copy and paste form\n\n/way 35.04, 29.45 Three-Breeze Terrace\n/way 28.01, 72.08 Southeast of Tushui Landing\n/way 26.69, 52.15 The Timeless Shore\n/way 58.11, 46.66 Red Stone Run\n/way 49.80, 70.15 South of Mossgreen Lake\n/way 43.41, 55.88 The Celestial Court\n/way 37.52, 74.19 Old Pi'jiu\n/way 22.83, 29.31 The Misty Strand\n/way 30.19, 45.53 West of Celestial Court\n/way  66.18, 72.31 Croaking Hollow\n/way 63.89, 50.60 Whispershade Hollow\n/way 53.00, 60.79 East of Mossgreen Lake",
            date = "2013-09-10T13:50:12-05:00",
            sourceUrl = "https://www.wowhead.com/quest=33341#comments:id=1894542",
        },
        {
            id = 1896269,
            score = 42,
            author = "435859",
            text = "Wayshrine Map (http://www.wowhead.com/maps?data=6757:350294280721267522581467498702434559375742228293302455662723639506530608)",
            date = "2013-09-12T08:28:03-05:00",
            sourceUrl = "https://www.wowhead.com/quest=33341#comments:id=1896269",
        },
        {
            id = 1895213,
            score = 29,
            author = "effe",
            text = "I camped one Shrine and it got active\n14:06\n14:16\n14:26\nDont have seconds but it looks like its 10 min between each time it got active.",
            date = "2013-09-11T07:35:24-05:00",
            sourceUrl = "https://www.wowhead.com/quest=33341#comments:id=1895213",
        },
        {
            id = 1895732,
