    [33374] = {
        {
            id = 1896597,
            score = 48,
            author = "perculia",
            text = "This is going to be hotfixed soon to give +250 Shaohao rep:\n\nOne hotfix we're applying that should help a bit:\n\nCompleting the daily quest \"Path of the Mistwalker\" now awards a player with 250 reputation with Emperor Shaohao.\n\nSource (http://us.battle.net/wow/en/forum/topic/9948064799#2)",
            date = "2013-09-12T17:07:50-05:00",
            sourceUrl = "https://www.wowhead.com/quest=33374#comments:id=1896597",
        },
        {
            id = 1899113,
            score = 39,
            author = "Qoko",
            text = "Doing just this daily whilst killing the higher ranked Yaunghol elite (Ordos sanctuary) will net you 20*22 = 440 + 275 for the quest = 715 rep with the guild perk (humans 780). Counting from the base numbers you need 42000/715 = 58.8 days to get Exalted (54 for Humans). Considering the patch is the final installment for MoP and it is likely going to be main content for the  next 2/3 year you should consider not farm this to death besides doing the daily. The only exception to this would be getting to Honored in order buy the teleport trinket, as it makes your daily trips slightly shorter (you can both teleport to the isle and on the isle when you are done with the daily).\n\nhttps://www.wowhead.com/item=64399 can increase your rep gain, but they are not really reliable unless you have a guild member with you that has another one: even putting one down in the middle of the Ordos sanctuary will make it despawn if you move too far to the sides. Extra rep buffs work but aren't advisable because of the high death toll of the elites; if you find yourself at the DMF before going here you should get it, but don't focus on it if you die.\n\nADD: of course, another viable option to consider is using https://www.wowhead.com/item=103684 at the Three-Breeze Terrace and killing every Yaunghol that spawns there. Pros are that this should make the https://www.wowhead.com/item=64399 more reliable to use, and you don't have to move all the way to Ordos sanctuary in order to start killing. The cons would be that solely killing all spawned mobs is tricky and you do not exactly control whether other players kill or pull them away. The Archiereus does not give rep, but will refund most of the Scroll anyway.",
            date = "2013-09-17T02:38:49-05:00",
            sourceUrl = "https://www.wowhead.com/quest=33374#comments:id=1899113",
        },
        {
            id = 1885650,
            score = 25,
            author = "Voxxel",
            text = "So as it has been fixed recently, killing https://www.wowhead.com/npc=73704's elite crew has become the most effective way to do this quest, leaving the elite frogs behind. The reverse of the medal is that the ship can deplete way faster than frogs on overcrowded servers.",
            date = "2013-08-09T15:03:33-05:00",
            sourceUrl = "https://www.wowhead.com/quest=33374#comments:id=1885650",
        },
        {
            id = 1886454,
            score = 17,
            author = "Keltix",
            text = "The best place i found to do this quest is in the Croaking Hollow.\nAll the mobs there are Elites and are fairly easy, so it shouldnt take long to do.\n\nAlso the Primal Stalkers in the Red Stone Run right next to it, is a good place as well if you're waiting for the frogs to respawn\n\nHope this could help you!",
            date = "2013-08-12T09:51:04-05:00",
            sourceUrl = "https://www.wowhead.com/quest=33374#comments:id=1886454",
        },
        {
            id = 1895800,
            score = 14,
            author = "Velor55",
            text = "If you're having trouble finding mobs that won't blow you up, consider going to The Croaking Hollow (66, 70)\n\nThe https://www.wowhead.com/npc=72777s will give credit, are fairly easy to kill compared to the other mobs, and spawn fairly quickly.",
            date = "2013-09-11T18:44:32-05:00",
            sourceUrl = "https://www.wowhead.com/quest=33374#comments:id=1895800",
        },
    },
    [33375] = {
        {
            id = 1896783,
            score = 75,
            author = "Burzolog",
            text = "The idea behind the Vision of Time hourglass is that it has to be charged up with Epoch stones every week, which is why Empowering the Hourglass is a weekly quest. Technically this quest is not a weekly because you can only ever do it once, but you will be able to do the next \"Turn the Hourglass\" quest after collecting 50 Epoch stones each week. If you read the quest description, you can clearly tell that Kairoz is referring to fact that he has just finished recharging the hourglass with stones.",
            date = "2013-09-12T23:43:50-05:00",
            sourceUrl = "https://www.wowhead.com/quest=33375#comments:id=1896783",
        },
        {
            id = 1897501,
            score = 61,
            author = "TaylorSwift",
            text = "It appears that this quest is 1 of 6 quests you have to do, all with different names, all doing the same thing. On the right where it lists the next 5 quests (I don't know how to link stuff) it looks like a quest chain. All quests tell you to use the vision of time in Siege of Orgrimmar. If you read each one though the dialog is different. Since we know epoch stones are a weekly quest this quest can be done once a week which is why it appears the chain will take 6 weeks.\n\nThe last quest states \"This is the last time (or hopefully the last time, can't remember) time I will ask you to do this. Also looking at the last one, you receive 5,000 coins instead of 1,000.\n\nSo it looks like the same objective, different quest titles, 6 weeks in a row. Hopefully after the last one, some new kind of chain will start or something else will come of it.\n\nHopefully my 1st comment doesn't suck too bad. But not a lot of info there yet, and no other comment in all 6 quests had anyone even guessing why they weren't getting the next quest in the chain.",
            date = "2013-09-13T22:09:31-05:00",
            sourceUrl = "https://www.wowhead.com/quest=33375#comments:id=1897501",
        },
        {
            id = 1899891,
            score = 56,
