            id = 2012779,
            score = 6,
            author = "Alexxiis",
            text = "There are yellow glowing flags you need to click to claim it for the Alliance!\n\nCoordinates:\n1)  60, 16  -  At entrance walkway into the Keep building.\n2)  62.5, 28.5 - SW of the entrance to the Keep building\n3)  63, 23 - At the southern entrance/exit into Nethergarde Keep",
            date = "2014-10-14T16:06:38-05:00",
