            author = "Bengarion",
            text = "You do NOT get a flag to plant in your bag for this quest.\n\nThe flags are already planted but are glowing yellow. Just click on them and they turn into the blue Alliance flag.\n\nTheir locations are as listed in the quest except that the \"Entrance Flag\" is on the East side of the keep, not the entrance one would normally associate with being the front entrance. (The side facing the ocean.)",
            date = "2014-10-15T21:22:19-05:00",
