    [35494] = {
        {
            id = 2012781,
            score = 10,
            author = "Alexxiis",
            text = "https://www.wowhead.com/item=113395 is at 62, 15 in the Blacksmith building of NE Nethergarde Keep.\nhttps://www.wowhead.com/item=113396 is at 60, 20. (in the ruins part of southern Nethergarde Keep)\nhttps://www.wowhead.com/item=113397 is at 58, 19 (on a table)",
            date = "2014-10-14T16:13:15-05:00",
            sourceUrl = "https://www.wowhead.com/quest=35494#comments:id=2012781",
        },
        {
            id = 2012916,
            score = 8,
            author = "Ardy",
            text = "Sword is pulled from the corpse of the old Armorer, https://www.wowhead.com/npc=5508.\n\nKeri's Mug is on the table to the right when you enter Nethergarde Keep from the west. Used to belong to https://www.wowhead.com/npc=44324.\n\nShield is lying in the rubble of the ruined keep. Belonged to https://www.wowhead.com/npc=44985.\n\nSo sad!",
            date = "2014-10-14T20:32:28-05:00",
            sourceUrl = "https://www.wowhead.com/quest=35494#comments:id=2012916",
        },
        {
            id = 2014259,
            score = 1,
            author = "druunah",
            text = "Keri's mug is not inside the intact building, but outside sitting on a \"picnic table\" under a tent very near the western entrance. (Not that I looked inside the building for it myself...) Please see screenshots: [item=113397 domain=www]",
            date = "2014-10-16T17:08:43-05:00",
            sourceUrl = "https://www.wowhead.com/quest=35494#comments:id=2014259",
