    [35499] = {
    },
    [35500] = {
        {
            id = 1984794,
            score = 3,
            author = "1132639",
            text = "This seems to be the final quest in the quest chain.",
            date = "2014-07-26T09:37:47-05:00",
            sourceUrl = "https://www.wowhead.com/quest=35500#comments:id=1984794",
        },
        {
            id = 2016137,
            score = 3,
            author = "1070129",
            text = "If you have boosted to 90 - You will know this end quest is a PAIN because you have no flight ability :(\nI actually run my mount along the side of the mountain - until you get close to the tower and LEAP onto one of the (flame) side and then run in and up the stairs to kill him ( you will aggro 1-2 mobs  but it's better than trying to fight your way up the tower) . HTH",
            date = "2014-10-19T23:31:43-05:00",
            sourceUrl = "https://www.wowhead.com/quest=35500#comments:id=2016137",
        },
        {
            id = 2019901,
            score = 2,
            author = "1150532",
            text = "Second to the final of the quest chain.\n\nFastest way towards him is to fly to the 2nd floor from the outside to avoid the mobs in the ground floor.\n\nFinal Quest in the chain is to go back in Stormwind, turn-in the quest and get your pet.",
            date = "2014-10-27T13:03:30-05:00",
            sourceUrl = "https://www.wowhead.com/quest=35500#comments:id=2019901",
        },
        {
            id = 2014258,
            score = 1,
            author = "cmacord",
            text = "This guy was at the very top of the hold. He is a '!' guy like the last one. He had one companion, who I pulled first. I was surprised that Bladetwist didn't aggro when I did. When I pulled Bladetwist, an NCP appeared to help. He also held aggro (I'm a Mage), so it was a short and easy fight.",
            date = "2014-10-16T17:08:23-05:00",
            sourceUrl = "https://www.wowhead.com/quest=35500#comments:id=2014258",
        },
        {
            id = 2014681,
            score = 1,
            author = "Wimbleton",
            text = "This is pretty easy, since Vindicator Maraad is really a great help. Two things make it more interesting for squishies. You can fight your way in through the front door of the fort (don't loot those guys until you're on your way out) or you can just fly onto the terrace one floor below Bladetwist and run up the stairs. Bladetwist has a companion who jaunts behind you while you're trying to kill her, so until Maraad gets there (he arrives pretty quickly), you can be pretty busy. But I found Maraad will kill Bladetwist if you get tangled up with his secretary.\n\nThen of course, since you flew up to the terrace, you'll want to fly out, right? Uh no, because even though Blade & his assistant are dead, you're still in combat, so you can't mount up and fly away from the two guys who attack you on the terrace. Glitch? Latency problem? Who knows but just be prepared. Of course there is always the option of jumping off the terrace onto the entryway below. But if you flew up, you didn't kill the 6 - 9 guys on the first floor because you didn't go in that way and they're still there - not very happy with you either. No problem because you've still got 20% of your armor left from the fight with Blade, right? You're still in combat, so you're not regaining health. 20% cloth armor should be enough to handle 6 - 9 guys, right? Oh and if you die there, you can't rez in front of Okril'lon because there are about 273 defenders who are in a very bad mood because of all of your friends who killed them several times earlier in the day. They're not camping your corpse, they're lined up around it with evil anticipation.\n\n81G repair bill. A new record for my mage. But no problem; the rewards from the quests covered some of it.",
            date = "2014-10-17T13:48:27-05:00",
            sourceUrl = "https://www.wowhead.com/quest=35500#comments:id=2014681",
        },
    },
    [35608] = {
    },
    [35609] = {
    },
    [35613] = {
    },
    [35744] = {
        {
            id = 2014364,
            score = 1,
            author = "Krastopic",
            text = "This quest is picked up at Thrall in the Shattered Landing and is completed by killing Ironmarch Executioners who are holding Horder Prisoners who you will free to complete the quest.  In the area there are also Ironmarch Grunts and Ironmarch Leadspitters who will aggro on you as you get near.  Approaching the area from the Southeast and working to the Northwest is the easiest way to stop as many executions as possible running into the least number of mobs. I started at 61,36 and worked my way across.\n\nUnfortunately if there are two prisoners, you only get credit for stopping one execution.  Stop three executions and fly home.",
            date = "2014-10-16T21:54:18-05:00",
            sourceUrl = "https://www.wowhead.com/quest=35744#comments:id=2014364",
        },
    },
    [35745] = {
        {
            id = 5823940,
            score = 7,
            author = "GibbleFenwick",
            text = "You can pick up this quest from Thrall at Shattered Landing in this zone while time travelling to \"pre-invasion\" version of the zone.\nHowever, in that version the Iron Horde haven't actually invaded yet.\nSo you can't do the quest unless you return to Zidormi to switch the zone back to \"present day\".\n\nWhich is rather odd, and may cause some confusion.",
            date = "2024-04-11T05:16:38-05:00",
            sourceUrl = "https://www.wowhead.com/quest=35745#comments:id=5823940",
        },
        {
            id = 2013172,
            score = 4,
            author = "corruptbyte",
            text = "If you do these quests on a character with an ilevel less than 515 (mine was 504 at the time), you can receive loot in addition to gold. I received https://www.wowhead.com/item=118761, https://www.wowhead.com/item=118766, https://www.wowhead.com/item=118771, and https://www.wowhead.com/item=118776 for completing the whole quest chain, in addition to achievement/pet/title I received on other characters.",
            date = "2014-10-15T06:32:58-05:00",
            sourceUrl = "https://www.wowhead.com/quest=35745#comments:id=2013172",
        },
        {
