    [35746] = {
        {
            id = 3300294,
            score = 9,
            author = "Quotas",
            text = "I was able to pick up this quest today at 71, 48 in The Blasted Lands, along with Attack of the Iron Horde. It was weird to see Thrall just standing there, but I also cannot see the NPCs or siege engines required to complete this quest.",
            date = "2021-02-12T12:47:51-06:00",
