    [35751] = {
        {
            id = 2012750,
            score = 13,
            author = "albinoette",
            text = "When you get close to the respective areas (entrance: 62,22; center of keep: 61,18; main keep: 59,16), a flag outline will appear -- click on the outline to plant each flag.",
            date = "2014-10-14T15:02:23-05:00",
