    [35760] = {
        {
            id = 2012849,
            score = 1,
            author = "albinoette",
            text = "Patrols around 43, 36. Shares credit if already tagged by someone else, but has a fast respawn if he's dead when you get there.",
            date = "2014-10-14T18:24:31-05:00",
            sourceUrl = "https://www.wowhead.com/quest=35760#comments:id=2012849",
        },
        {
            id = 2015420,
            score = 1,
            author = "Krastopic",
            text = "This quest is best accomplished if you do it as a group of quests including:\n\nOkrilla's Revenge (http://www.wowhead.com/quest=35764)\nToothsmash the Annihilator (http://www.wowhead.com/quest=35760)\nDeath to the Dreadmaul (http://www.wowhead.com/quest=35762)\n\nToothsmash is not a hard fight, he is slow and easy to kite.  His best attack is Blade Storm which is a spinning melee attack.  Toothsmash does not move during this attack so just move away if you are a caster or have a ranged weapon.  Pay attention that you don't move backward into one of the mobs that rings the area, so pick a direction prior to starting the encounter.",
            date = "2014-10-18T17:23:43-05:00",
            sourceUrl = "https://www.wowhead.com/quest=35760#comments:id=2015420",
        },
    },
    [35761] = {
        {
            id = 1992688,
            score = 14,
            author = "Saberia",
            text = "Aitokk's Axe is located at 61,14. It is lying on the floor of blacksmith building in Nethergarde Keep.\n\nNeka's Poison Flask is located at 59,17. It is few feet south-east from Nethergarde Keep's west entrance lying on floor near tent.\n\nOverseer Struk's Shield is located at 60,20. It is in the middle of ruins of former largest building of the Nethergarde Keep.",
            date = "2014-08-17T13:19:20-05:00",
            sourceUrl = "https://www.wowhead.com/quest=35761#comments:id=1992688",
        },
        {
            id = 2012878,
            score = 7,
            author = "Etreum",
            text = "I found the axe on the frame to the North exit (not on the floor).",
            date = "2014-10-14T19:23:56-05:00",
            sourceUrl = "https://www.wowhead.com/quest=35761#comments:id=2012878",
        },
        {
            id = 2014385,
            score = 4,
            author = "Krastopic",
            text = "When you pick up this quest, also pick up the following quests to do at the same time:\n\nLunatic Lieutenants (http://www.wowhead.com/quest=35750)\nAttack on Nethergarde (http://www.wowhead.com/quest=35751)\n\nTo find Nethergrade Keep, fly to the northeast of where Thrall gives you the quest.  Assuming you are doing all of the quests at the same time, here is the order for all three quests:\n\nRukah's Battleplan, 57,18 - Pick Up off of Rukah after kill (Lunatic Lieutenants)\nNeka's Poison Flack, 59,18 - On the picnic table, highlighted (Ransacking Nethergrade)\nFlag Planted Outside Main Keep, 60,16 - Click on outline of flag (Attack on Nethergrade)\nOverseer Struk's Shield, 61,20 - laying on ground highlighted (Ransacking Nethergrade)\nFlag planted at Nethergarde entrance, 63,23 - Click on outline of flag (Attack on Nethergrade)\nFlag planted in the center of Nethergarde, 62,19 - Click on outline of flag (Attack on Nethergrade)\nAitokk's Axe, 62,15 - Inside building, in the door frame next to Aitokk's body. Axe is roughly at eye level for your toon. (Ransacking Nethergrade)\nMokrik's Battleplan, 63,13 - Pickup after the kill (Lunatic Lieutenants)\nGar's Battleplan, enter at 60,15 - Inside the building, go to the third floor Pickup after the kill (Lunatic Lieutenants)\n\nYou will note that the flags which you have to plant for the Attack on Nethergrade will have the new outline shading to help you find the spot to plant the flag.\n\nThe Overseer Struk's Shield is laying on a boot at a slight angle in the middle of the rubble of a building.\n\nNeka is already dead.  Her poison flask is on the table.  You do not have to kill her to pick up the flask.\n\nLike Neka, Master Aitokk is already dead.  You do not have to kill him to pick up the axe.  The axe is in the door frame next to the body.\n\nYou can pick up the bombs thrown by Mokrik at the start of the fight and an icon will appear and you can throw a bomb back at him doing reasonable damage.  Just run over the bomb to pick it up.",
            date = "2014-10-16T22:34:50-05:00",
            sourceUrl = "https://www.wowhead.com/quest=35761#comments:id=2014385",
        },
        {
            id = 2012747,
            score = 1,
            author = "albinoette",
            text = "As of 6.0.2's release, the axe is now in the doorframe of the workshop, not on the ground as it appears to have been in PTR. It's above Master Aitokk's corpse.\nOverseer Struk's shield is above her corpse in the southern collapsed building.\nThe poison flask is to the right on a table when you come in the west gate (not as glowy as the other items). If you stand at Neka's feet, her head points towards the flask.\n\nIf at any point you are having trouble, you can /target \"Overseer\", \"Neka\", or \"Master\" and the quest items you're trying to find will be nearby.",
            date = "2014-10-14T14:59:59-05:00",
            sourceUrl = "https://www.wowhead.com/quest=35761#comments:id=2012747",
        },
        {
            id = 2002306,
            score = 0,
            author = "piraka810",
            text = "\"We must not forget those that gave their lives at Nethergarde. If you find any mementos of the fallen, bring them back to me.\"\n\nWow, looks like that Horde and Alliance peace treaty actually did something after all!",
            date = "2014-09-13T12:29:55-05:00",
            sourceUrl = "https://www.wowhead.com/quest=35761#comments:id=2002306",
        },
    },
    [35762] = {
        {
            id = 2015426,
            score = 0,
            author = "Krastopic",
            text = "This quest is best accomplished if you do it as a group of quests including:\n\nOkrilla's Revenge (http://www.wowhead.com/quest=35764)\nToothsmash the Annihilator (http://www.wowhead.com/quest=35760)\nDeath to the Dreadmaul (http://www.wowhead.com/quest=35762)\n\nAs you get the poison pots for Okrilla's Revenge, you will find plenty of Dreadmaul Ogres to kill.  Some of the ogres will have Snickerfang Pups with them, which was easy to AOE down.  The Dreadmaul Crushers and Dreadmaul Flamebelcher are the easiest kills, slightly more difficult is the Dreadmaul Packmasters who are accompanied by Snickerfang pups - all easy to kill, but the pups increase the damage over time you will experience until you AOE or hack them down.\n\nThere are also Ironmarch Grunts, Ironmarch Forger and Ironmarch Stone-Singers in the area, just avoid them even though they are an easy kill, and stay on the ogres to complete the quest in the least amount of time.",
            date = "2014-10-18T17:27:56-05:00",
            sourceUrl = "https://www.wowhead.com/quest=35762#comments:id=2015426",
        },
        {
            id = 2021615,
            score = -1,
            author = "1349070",
            text = "https://www.wowhead.com/npc=82451 ended up being three of my kills for this quest.  He repopped twice while I was getting the two https://www.wowhead.com/object=232625 near him and killing off the other ogres.",
            date = "2014-10-31T15:40:59-05:00",
            sourceUrl = "https://www.wowhead.com/quest=35762#comments:id=2021615",
        },
    },
    [35763] = {
        {
            id = 2013421,
            score = 4,
            author = "Acaulis",
            text = "Could be an early patch bug, but on my rogue I sapped the add and engaged Gar'mak. Thrall sometimes never showed up, sometimes just ran down the stairs. Finally he decided to help my very un-geared rogue and we killed him. Thank goodness for Vanish!",
            date = "2014-10-15T11:06:42-05:00",
            sourceUrl = "https://www.wowhead.com/quest=35763#comments:id=2013421",
        },
        {
            id = 2013042,
            score = 1,
            author = "Krastopic",
            text = "Welcome to Warlords!  When I ran this it was not on a stock 90 character but a geared level 90 priest during the lead-up quests for the expansion pack.  You will find Gar'mik inside of Okril'lon Hold, third floor.  The entrance is located at 41,11.\n\nGar'mak was a simple kill.  You will go inside and have to battle a few mobs, there is nothing that can kill you on the first floor.  The second floor will only one one or two mobs depending on who went before you.  Kill them - BUT DO NOT GO through the arches and outside where you will find plenty of mobs to kill.  Instead, you will see a winding staircase to the third floor.  Climb to the top and there is Gar'mak and a single mob there.  Once you start the attack, Thrall will show up and help you finish him off.\n\nA tip for priests and any one with a pet.  Put your Mindbender (aka Shadowfiend) or pet on Gar'mak, hit your fade to drop aggro, then kill the mob, then kill Gar'mak.\n\nBladestorm is a primary attack,  but unlike some of the ogres outside, Gar'Mak will slowly follow you as you back away during this attack.  It is still easy to kite him.\n\nI am sure this will be harder for a stock level 90 leveling once the expansion pack is released, but easy for a geared 90 coming in from Mists.\n\nGet clear quick, because Gar'mak respawns fast.\n\nQuick escape tip.  If you go down to the second floor, inch just outside the door, and from there you can mount a flying mount and escape without having to fight your way out.  Kite the Ironmarch Pillager inside, kill him and they mount in the doorway.",
            date = "2014-10-15T00:25:48-05:00",
            sourceUrl = "https://www.wowhead.com/quest=35763#comments:id=2013042",
        },
        {
            id = 2566527,
            score = 1,
            author = "556068",
            text = "Did this quest yesterday after just returning to WoW after several years. Therefore, not the best at playing my mage currently (such as forgetting to use mage buffs, etc). CC'd the other dude in the room and attacked Gar'mak. Thrall shows up and is kinda helpful, but Gar'mak kills me in short order, though I managed to survive somewhat decently I think. Running back to rez while cursing out Thrall for not being very helpful, thinking I'll have to do the pull again. As I go up the stairs in ghost form, hear fighting & realize that they are still at it (yay!). At this point Thrall has full aggro, so I can go at it without super worrying about aggro (opened Omen though just to be sure, but I was nowhere near Thrall's aggro. Pew pew for a bit and then he's dead & Thrall goes back to wherever he goes & I finish off the mob. Phew!",
            date = "2018-05-08T15:38:58-05:00",
            sourceUrl = "https://www.wowhead.com/quest=35763#comments:id=2566527",
        },
        {
            id = 5236564,
            score = 1,
            author = "eKatherine",
            text = "I was farming mobs on my 20 for the pet prior to going to draenor to start a garrison after Rarity addon told me they dropped something. Killed these guys, Thrall showed up. It's not clear if the quest still exists, though Gar'mak is still marked as a quest mob. Thrall does not appear at the point marked on the map above.",
            date = "2021-08-13T20:55:34-05:00",
            sourceUrl = "https://www.wowhead.com/quest=35763#comments:id=5236564",
        },
        {
            id = 1992690,
            score = -1,
            author = "Saberia",
            text = "You can find him on top floor of main building at Okril'lon Hold.\n\nCoordinates: 40,10",
            date = "2014-08-17T13:25:46-05:00",
            sourceUrl = "https://www.wowhead.com/quest=35763#comments:id=1992690",
        },
    },
    [35764] = {
        {
            id = 1984834,
            score = 3,
            author = "Gotobetroll",
            text = "And here I was thinking she betrayed us Hordies",
