        },
        {
            id = 5606292,
            score = 3,
            author = "FancyFlamingo",
            text = "Initially, I thought this was bugged, but I had to perform the skill about 5 times or so before it was marked as complete. I think they want you to \"master it,\" like in the days when some games had you repeatedly cast to level a skill up.",
            date = "2023-05-11T17:06:51-05:00",
