        },
        {
            id = 6129128,
            score = 3,
            author = "Yorgl",
            text = "Another comment about if it's bugged or not to propose what might be the \"fix\" for a few class : try aggroing the wyrm by using the racial. Don't be in combat before, just go near them, and activate it.\nAfter several try  by taging them and then using the racial, I tried that just in case and it gave me credit immediately for the quest. So who knows ^^...",
            date = "2025-06-19T09:09:31-05:00",
