    [40168] = {
        {
            id = 2262364,
            score = 71,
            author = "Jaedaddy",
            text = "You can not turn in https://www.wowhead.com/item=129747 after the end of the Timewalking Event.  You will have to wait until it comes around again.\n\nSee this post (http://www.wowhead.com/npc=98685/cupri#comments:id=2244052) related to the vendor https://www.wowhead.com/npc=98685",
            date = "2015-10-12T14:40:12-05:00",
            sourceUrl = "https://www.wowhead.com/quest=40168#comments:id=2262364",
        },
        {
            id = 2267628,
            score = 42,
            author = "ClasscMalcontent",
            text = "Check your quest completion during the event. Useful for alts to quickly check status.\n\nThe Swirling Vial\n\n/script print(IsQuestFlaggedCompleted(40168))\n\nTRUE if completed.\nFALSE if you have not yet completed it during the current event.\n\nEdit: As noted by Nerravar (http://www.wowhead.com/npc=98685/cupri#comments:id=2230831), turn in the quest to https://www.wowhead.com/npc=98685 in [zone=3703], Outlands.\n\nSide note: This is a basic script to check quest completion. Run it from your chat window as you would any other command in the game. Similar, albeit more advanced scripts, also exist to check for NPCs killed each week such as the World Bosses in Draenor (http://www.wowhead.com/npc=94015/supreme-lord-kazzak#comments:id=2203432).\n\nYou can also substitute the 5-digit quest code above with other quest codes found on Battle.net (http://www.battle.net) and here on Wowhead (http://www.wowhead.com) to check their completion status.",
            date = "2015-10-23T16:05:52-05:00",
            sourceUrl = "https://www.wowhead.com/quest=40168#comments:id=2267628",
        },
        {
            id = 2487011,
            score = 34,
            author = "Arbatrus",
            text = "Blizzard should consider leaving the quest turn in npc active at all times.  I got this on the last day of the timewalking event and had no time to turn it in. Now, I'm stuck with this item in my inventory for three months because that's how long it takes Blizzard to cycle through all the timewalking events, pvp events and Legion dungeon events.  This is pointless, considering that most quest givers are active 24/7.",
            date = "2017-04-14T13:11:16-05:00",
            sourceUrl = "https://www.wowhead.com/quest=40168#comments:id=2487011",
        },
        {
            id = 2240761,
            score = 31,
            author = "Orivarro",
            text = "This quest can be obtained from the https://www.wowhead.com/item=129747 which drops by doing timewalking dungeons.\n\nEdit: The quest is turned in to https://www.wowhead.com/npc=98685 during the BC Timewalking event and 24 hours after it's ended.",
            date = "2015-08-28T13:49:54-05:00",
            sourceUrl = "https://www.wowhead.com/quest=40168#comments:id=2240761",
        },
        {
            id = 2296755,
            score = 14,
            author = "gmack28",
            text = "Use the below script to see if you toon has completed the weekly quest.\n\nTrue = Completed\nFalse = Not completed for current event\n\nOutland Timewalking - The Swirling Vial\n/script print(IsQuestFlaggedCompleted(40168))\n\nNorthrend Timewalking - The Unstable Prism\n/script print(IsQuestFlaggedCompleted(40173))\n\nCataclysm Timewalking - The Smoldering Ember A/H\nAlliance\n/script print(IsQuestFlaggedCompleted(40786))Horde\n/script print(IsQuestFlaggedCompleted(40787))\n\nAlliance\n/script print(IsQuestFlaggedCompleted(40168))\n/script print(IsQuestFlaggedCompleted(40173))\n/script print(IsQuestFlaggedCompleted(40786))\n\nHorde\n/script print(IsQuestFlaggedCompleted(40168))\n/script print(IsQuestFlaggedCompleted(40173))\n/script print(IsQuestFlaggedCompleted(40787))\n\nThank you Chanel for testing.\n\nAnd if anyone knows how to add within the script to list the event name and T/F, please let me know - thanks.",
            date = "2016-01-10T12:24:30-06:00",
            sourceUrl = "https://www.wowhead.com/quest=40168#comments:id=2296755",
        },
    },
    [40236] = {
        {
            id = 2584815,
            score = 21,
            author = "saillaw",
            text = "If like me, something comes up and you have to log out after accepting this quest, but before completing it, when you come back all the characters you need to talk too to complete it will be gone.   Just abandon the quest and the quest giver will appear again at the top of the stairs.",
