    [40517] = {
        {
            id = 2313907,
            score = 69,
            author = "EverGuardian",
            text = "My son, a terrible darkness has returned to our world. As before, it seeks to annihilate everything that we hold dear. I go to face it, knowing I may not return. All my life I have lived by the sword. I've seen kingdoms burn, and watched brave heroes die in vain. It's been difficult for me to trust after losing so much. But from you I have learned patience, tolerance, and faith. Anduin, I now believe as you do, that peace is the noblest aspiration. But to preserve it, you must be willing to fight -- For Azeroth! - King Varian Wrynn",
            date = "2016-03-13T10:23:04-05:00",
            sourceUrl = "https://www.wowhead.com/quest=40517#comments:id=2313907",
        },
        {
            id = 2321967,
            score = 47,
            author = "MithrilMercenary",
            text = "\"Dad? ...Dad, come on... You gotta get up. Dad. We gotta go home... HEEEELP! Somebody! anybody! help...\"",
            date = "2016-04-14T10:50:50-05:00",
            sourceUrl = "https://www.wowhead.com/quest=40517#comments:id=2321967",
        },
        {
            id = 2367814,
            score = 24,
            author = "CallMeNoa",
            text = "It bugs me a lot that Valeera Sanguinar and Broll Bearmantle aren't at the funeral. They're Varian's best friends!",
            date = "2016-08-14T19:18:04-05:00",
            sourceUrl = "https://www.wowhead.com/quest=40517#comments:id=2367814",
        },
        {
            id = 2370836,
            score = 20,
            author = "Zinovia",
            text = "This quest bugged for one of my characters on the live server. I went to deliver the letter to Anduin, heard all the advisors arguing, and then nothing. Could not turn it in, and had no item named \"letter\" in my inventory. Along with this, all the game sound had quit working after watching the big cinematic. Reloading my UI did not work, nor did quitting out. Abandoning the quest, and picking it up again from Greymane did work. I got a copy of the Letter to Anduin and turned it in.",
            date = "2016-08-19T19:48:33-05:00",
            sourceUrl = "https://www.wowhead.com/quest=40517#comments:id=2370836",
        },
        {
            id = 5385787,
            score = 13,
            author = "Fangforever",
            text = "There is a bug where the quest doesn't advance once you have talked to Anduinn. I submitted a ticket and got a random automated message.\nI finally found out where to retake it, it's from Genn Graymane, atop the flying battleship, you can board from a teleporter in the harbor of Stormwind.",
            date = "2022-06-18T20:39:18-05:00",
            sourceUrl = "https://www.wowhead.com/quest=40517#comments:id=5385787",
        },
    },
    [40518] = {
        {
            id = 3243002,
            score = 61,
            author = "Pungrasso",
            text = "How to skip the scenario while questing in Chromie Time:\n\nGrab your buffs and duel your old garrison follower that you forgot about for 5 years, and hand in \"To Be Prepared\" at Stone Guard Mukar to get a free ring.  Then accept the Battle for Broken Shore quest.   Don't talk to Captain Russo!   Go back to talk to Holgar Stormaxe at the gates of Orgrimmar with the quest still in your log, and he should have the dialogue for you to skip the scenario and teleport right to Dalaran.\n\nHappy questing!",
            date = "2020-10-27T17:45:09-05:00",
            sourceUrl = "https://www.wowhead.com/quest=40518#comments:id=3243002",
        },
        {
            id = 6244648,
            score = 9,
            author = "Delicious",
            text = "If you were losing your mind like me after transferring off legion remix and being stuck in phase Orgrimmar, here is how I finally managed to exit the phase.\n\nDo not skip any quests or steps. For me, the skips did not work and got rid of options to exit the phase.\n\nSpeak to Archivist Elysiana  (https://www.wowhead.com/npc=113873/archivist-elysiana)in the Violet Tower (near Khadgar in Dalaran). Click her prompt and complete the full scenario.\n\nOnce back in Orgrimmar, take “Fate of the Horde.” (https://www.wowhead.com/quest=40522/fate-of-the-horde) If the door is closed or Saurfang isn’t there, abandon the quest. Return and talk to Eitrigg (https://www.wowhead.com/npc=100453/eitrigg) outside on the dock, and pick it up again. Saurfang will now appear.\n\nContinue the chain until finishing “Demons Among Us” (https://www.wowhead.com/quest=40607/demons-among-us) from Sylvanas. After that, turn in “Keep Your Friends Close” (https://www.wowhead.com/quest=40605/keep-your-friends-close) inside Orgrimmar and you’ll already be in the correct Orgrimmar phase.",
            date = "2025-12-11T20:04:00-06:00",
            sourceUrl = "https://www.wowhead.com/quest=40518#comments:id=6244648",
        },
        {
            id = 5805375,
            score = 7,
            author = "pipehitter24",
            text = "As of today i'm running evoker through mostly for mog if there is any, but i'm stuck on stage 7, Tirion found. from what i read there suppose to be an ice bridge but .... they never casted it i assume. first time i've ever done on horde so wasn't sure if missing something simple",
            date = "2024-03-20T11:42:34-05:00",
            sourceUrl = "https://www.wowhead.com/quest=40518#comments:id=5805375",
        },
        {
            id = 2370437,
            score = 5,
            author = "zharshoul",
            text = "It was certainly different playing this raid styled scenario, not so much because it was a raid style scenario but because of the different interpretation of the legion that we see blizzard has given us.\n\nPrior to this scenario/expansion the legion were portrayed more like classic dnd for the EVULS  magic/hack and slash style demons. The kind of unreasoning, corrupting and destroying evil because they are evil kind of evil. The most Magitech they ever got to was pretty much making infernals and a few fel cannons. Most of the \"demon tech\" in  burning crusade came across as belonging to Illidan in my opinion and not really \"legion tech\" to me anyway.\n\nThis time or perhaps having slowly led up to this, they almost resemble the zerg to be honest, lots of \"species/types\" under the category of demon working under the cause of the \"legion\"\n\nThere is heavy use of magitech and just flat out tech, demons of all shapes types and sizes, many of whom really were already \"demons\". They work together in unity under a common cause of spreading their green tainty style land and killing off possible threats, converting the species/individuals they find useful into fellow \"demons\".\n\nHonestly they do not really sound like demons anymore, just another race/group that is expansionist and trying to get more territory to grow/raise their offspring on, we have yet to really see demon children, but already there is a mob called \"imp mother\" and a race like demons/zerg don't really have long childhoods anyway, they grow/morph fast to their chosen caste/unit type.\n\nI suspect they just humor larpers like Guldan, letting a megalomaniac act out his destruction fantasies is a small price to pay so that there is more territory to expand upon.",
            date = "2016-08-19T00:37:48-05:00",
            sourceUrl = "https://www.wowhead.com/quest=40518#comments:id=2370437",
        },
        {
            id = 2509719,
            score = 5,
            author = "WokkaD",
            text = "There's an easy way to do this one :\n1. If you're \"squishy\", then hang back and let everyone else & the NPC's do the work.\n2. If you're on your own, then you may want to hang back\n3. You need to trigger the initial attack at the landing, then trigger the Tyrian death.\n4. For stage 8 battle (Krosus) at the fel liquid pool, you can wait at the base of the ramp for it to finish.\n5. You can stay there for the final battle at the ridge.\n6. This scenario virtually plays itself.\n\nNOTE : All persons must be present for the final battle to complete. If anyone is offline, then kick them before you head up the ridge or the scenario won't complete. You can't kick them while in combat.\n\nThis scenario should take aroound 30 minutes to complete.",
            date = "2017-07-23T09:42:12-05:00",
            sourceUrl = "https://www.wowhead.com/quest=40518#comments:id=2509719",
        },
    },
    [40519] = {
        {
            id = 2395595,
            score = 95,
            author = "Xandraroes",
            text = "If you abandon this quest while in the special phased version of Stormwind Harbor, and then choose the option to skip the Legion intro quests from https://www.wowhead.com/npc=107934, you will be teleported to Dalaran but will be unable to start any of the Legion content.\n\nTo fix this, simply speak to https://www.wowhead.com/npc=113873 in the Violet Citadel. Choose the option to re-live past events, and this quest will re-appear in your quest log. You can now go back to Stormwind Harbor and either play through the intro or choose to skip the content again, but this time the follow-up quests will be there in Dalaran.",
            date = "2016-09-10T10:46:44-05:00",
            sourceUrl = "https://www.wowhead.com/quest=40519#comments:id=2395595",
        },
        {
            id = 5913996,
            score = 40,
            author = "Majestick",
            text = "If you are not able to see Recruiter Lee (https://wowhead.com/npc=107934) in Stormwind Harbor check your quest log for To the Dragon Isles (https://www.wowhead.com/quest=67700/to-the-dragon-isles) and abandon it. This fixed the phasing issue for an alt that never bothered to complete the quest.",
            date = "2024-08-07T13:31:44-05:00",
            sourceUrl = "https://www.wowhead.com/quest=40519#comments:id=5913996",
        },
        {
            id = 3237977,
            score = 35,
            author = "Menedemus",
            text = "Okay, if you are wanting to do the Legion expansion on Alliance through Chromie after the Shadowlands release, Recruiter Lee probably won't be visible. To get around this on my level 10 toon, I accepted the Kul Tiras quest from Anduin, met Jaina on the harbor, took the boat to Boralas and when I returned to Stormwind Recruiter Lee had phased in and i was able to continue the Legion questline.",
            date = "2020-10-13T23:29:38-05:00",
            sourceUrl = "https://www.wowhead.com/quest=40519#comments:id=3237977",
        },
        {
            id = 2364827,
            score = 30,
            author = "carldemor",
            text = "Apparently this quest is not for Demon Hunters, I guess since there is a whole chain quest regarding the invasion they are not included on this one.\n\nI even went to SW harbor and nothing.\n\nMakes sense due to the fact that when the Demon Hunters end their quest line Varian is already dead and they are at the funeral with Anduin as the King.",
            date = "2016-08-10T17:53:34-05:00",
            sourceUrl = "https://www.wowhead.com/quest=40519#comments:id=2364827",
        },
        {
            id = 2368933,
            score = 21,
            author = "minihai",
            text = "Pre Legion invasion quest chain - Alliance/Neutral after Calling the Council\n\nThe Legion Returns (http://www.wowhead.com/quest=40519/the-legion-returns)\nTo Be Prepared (http://www.wowhead.com/quest=42782/to-be-prepared)\nThe Battle for Broken Shore (http://www.wowhead.com/quest=42740/the-battle-for-broken-shore#comments)\nThe Fallen Lion (http://www.wowhead.com/quest=40517/the-fallen-lion)\nDemons Among Us (http://www.wowhead.com/quest=40593/demons-among-us)\nIllidari Allies (http://www.wowhead.com/quest=44120/illidari-allies)\nCalling the Council (http://www.wowhead.com/quest=40717/the-council-of-six)\nThe Diamond King (http://www.wowhead.com/quest=42970/the-diamond-king)\nHiding in the Stacks (http://www.wowhead.com/quest=40755) (Not available on Wowhead at this moment)\nCity Under Siege (http://www.wowhead.com/quest=44182/city-under-siege)\nAnomalous Anomalies (http://www.wowhead.com/quest=44421/anomalous-anomalies)\nAuthor! Author! (http://www.wowhead.com/quest=44500/author-author)\nIn the Blink of an Eye (http://www.wowhead.com/quest=44184/in-the-blink-of-an-eye#comments) (Not available until Legion release)",
            date = "2016-08-16T13:30:22-05:00",
            sourceUrl = "https://www.wowhead.com/quest=40519#comments:id=2368933",
        },
    },
    [40522] = {
        {
            id = 2332419,
            score = 38,
            author = "tooltip",
            text = "Darkspear nevah die!\n\n/salute",
            date = "2016-05-19T22:11:35-05:00",
            sourceUrl = "https://www.wowhead.com/quest=40522#comments:id=2332419",
        },
        {
            id = 2366938,
            score = 25,
            author = "CallMeNoa",
            text = "After the cinematic, don't forget to look for Vol'jin's friend Tyrathan Khort (http://www.wowhead.com/npc=112594/tyrathan-khort) in the ridge behind the crowd.",
            date = "2016-08-13T17:37:01-05:00",
            sourceUrl = "https://www.wowhead.com/quest=40522#comments:id=2366938",
        },
        {
            id = 6325385,
            score = 17,
            author = "GoblinChara",
            text = "Had a guildmate who was a Remix character and was stuck on this quest because Saurfang would not appear. After trying numerous things on his own, I found an alt of mine who was able to retake the Legion intro from Elysiana in Broken Isles Dalaran (despite having completed Legion content long ago). We finally got him to see Saurfang.\n\nI had that character complete the Legion intro through to the end of the Broken Shore scenario. I did not skip any part of the quest chain. Once I landed on the dock in Durotar at Eitrigg, I turned in the scenario quest. I then invited him back to the party (I could not queue for scenario with him in party). He was waiting in Orgrimmar at Grommash Hold. We did party sync, and I took this quest (Fate of the Horde) from Eitrigg, and rode back to Orgrimmar on a land mount. The moment I entered into Orgrimmar proper (fully through the outer and inner gates), Saurfang phased in right in front of him and he was able to complete the quest.\n\nSince \"customer support\" is referring people here for answers instead of, you know, supporting customers, I thought I'd post what worked for us. If you are struggling with this, I truly hope it works for you, too.",
            date = "2026-04-06T06:38:12-05:00",
            sourceUrl = "https://www.wowhead.com/quest=40522#comments:id=6325385",
        },
        {
            id = 2369973,
            score = 12,
            author = "zharshoul",
            text = "And so voljin, perhaps the mightiest darkspear shadow hunter to ever live passes on from this world.\n\nA greedy part of me wants him to come back as a loa spirit, as I think trolls can ascend to loa-dom, but I wish him happiness, not eternal servitude answering shaman/shadowhunter prayers forever bound to some pseudo life.\n\nYou always did what was right and not what was easy. A savage troll with more moral fortitude than many of us can claim in real life. May you find happiness and contentment in the afterlife that you earned Voljin.\n\n/tear\nso many tears",
            date = "2016-08-18T03:53:33-05:00",
            sourceUrl = "https://www.wowhead.com/quest=40522#comments:id=2369973",
        },
        {
            id = 2364412,
            score = 10,
            author = "Jacobstx",
            text = "As much as Sylvanas has done a lot of horrible things, Vol'jin was right to name her Warchief.\n\nThe Horde needs to stay focused on the Legion for it, and Azeroth, to stand a chance - and if there is one thing Sylvanas does better than anyone else, it is singleminded revenge.\n\nShe is not the Warchief the Horde deserves, but right now she is the one it needs.\n\nLet us hope she does not end up the way Garrosh did.",
            date = "2016-08-10T07:00:29-05:00",
            sourceUrl = "https://www.wowhead.com/quest=40522#comments:id=2364412",
        },
    },
