    [40605] = {
        {
            id = 2442926,
            score = 18,
            author = "Infinitii",
            text = "If you do not get the joining quest to Dalaran after completing this you can try a few things. First check your Adventure Guide to see if the quest is in there. Second try talking to Holgar Stormaxe [npc=4311 domain=www] and select begin your journey in dalaran. Third try logging out for 5 minutes then logging back in.\n\n      In my case the game was acting like it was still on Lords of Dreanor. I had no xp bar to lvl past 100 and my Adventure Guide only showed old quests from Lords of Dreanor. In this case logging out for 5 minutes reset the game and got it running correctly for me.",
            date = "2016-11-11T05:27:18-06:00",
            sourceUrl = "https://www.wowhead.com/quest=40605#comments:id=2442926",
        },
        {
            id = 3274252,
            score = 11,
            author = "criptoabi",
            text = "To anyone on 30+ lvl having troubles to get the next quest, u can use the portal to Azsuna, fly to Dalaran, and talk with Amisi (https://es.wowhead.com/npc=96806/amisi-mirada-azurhttps://) to get your Dalaran-Legion Heartstone. Apparently there is no blizz-solution to get the quest, but at least u can get stoned.",
            date = "2020-12-14T12:53:40-06:00",
            sourceUrl = "https://www.wowhead.com/quest=40605#comments:id=3274252",
        },
        {
            id = 2364405,
            score = 4,
            author = "Jacobstx",
            text = "Sylvanas Windrunner: \"I've gotten far more kills than you, Nathanos. You're slipping!\"\nNathanos Blightcaller: \"I'm your champion, Dark Lady. It's my job to make you look good.\"\nSylvanas Windrunner: \"A Champion at making excuses it would seem!\"\n\nAnd thus was born the Windcaller/Blightrunner ship.",
            date = "2016-08-10T06:41:52-05:00",
            sourceUrl = "https://www.wowhead.com/quest=40605#comments:id=2364405",
        },
        {
            id = 2349951,
            score = 1,
            author = "Zarrek",
            text = "I was checking to see how much exp would be lost if you skipped the introductory quests in Legion. In Warlords of Draenor, I was never bothered by doing the Tanaan introductory scenario because it was easily half a level and the quests were relatively quick and painless. (30-60m max)\n\nIn Legion, after you complete the introduction once, you can subsequently skip it, but I wanted to see how much exp was lost.\n\nQuests 1-5 don't even give experience and the introduction took me roughly 45 minutes with the beta bugs and knowing exactly what to do. At this time, I'd recommend skipping on subsequent characters based on exp/hour.\n\nAs a note, it appears that these quests don't even reward experience, so I'm not sure if that's a bug or not.\n\n1) The Legion Returns <- Option to skip presented here\n2) To Be Prepared (I believe you can turn this in and still skip.)\n3) The Battle for Broken Shore (Forced into a group for a scenario minimal exp -- 20-30 minute scenario)\n4) Fate of the Horde\n5) Emissary\n6) Demons Among Us (group kill exp, if swarmed) (15k exp)\n7) Keep Your Friends Close (3750 exp)\n8) In the Blink of an Eye (You skip to the turn in of this quest)",
            date = "2016-07-10T15:45:16-05:00",
            sourceUrl = "https://www.wowhead.com/quest=40605#comments:id=2349951",
        },
        {
            id = 3249317,
            score = 1,
            author = "Nitrie",
            text = "I got bugged and i could not continue with the quest chain, so i take Azsuna portal and got into Dalaran. Reloging, talking to Holgar Stormaxe nor Adventure Guide helped me. My case its interesting cause i was actually a 50(120) level and i just never used Legion Dalaran until now. I can assume that the bug is somewhere around that.",
            date = "2020-11-15T07:29:33-06:00",
            sourceUrl = "https://www.wowhead.com/quest=40605#comments:id=3249317",
        },
    },
