            score = 12,
            author = "Marlen00i",
            text = "Note, that this is not a once-per-event quest, but a WEEKLY quest. Which means, that if you complete your first dungeon before weekly reset (on European servers on wednesday between midnight and 3 am), you can complete it twice, for a total of 1000 badges.\n\n(True as of January 27, 2016)",
            date = "2016-01-27T05:16:10-06:00",
            sourceUrl = "https://www.wowhead.com/quest=40787#comments:id=2302018",
        },
        {
            id = 5197820,
            score = 6,
            author = "Nightwatcha",
            text = "Updated macro for The War Within and beyond to check whether you’ve completed the weekly Timewalking quest, for both Horde and Alliance and for all different Timewalking campaigns. If all the text appears red, you haven't completed this week's quest yet.\n\nAlliance:\n/run a={{\"Classic\",43117},{\"BC\",0},{\"WotLK\",5},{\"Cata\",619},{\"MoP\",5395},{\"WoD\",15330},{\"Legion\",24542},{\"BfA\",49054}}for i=1,#a do n,o=a[1],a[2]print(\"\\124cFF\"..(C_QuestLog.IsQuestFlaggedCompleted(40168+o)and\"00FF00\"or\"c51a20\")..n..\"\\124r\")end\nHorde:\n/run a={{\"Classic\",43117},{\"BC\",0},{\"WotLK\",5},{\"Cata\",618},{\"MoP\",5395},{\"WoD\",15330},{\"Legion\",24542},{\"BfA\",49055}}for i=1,#a do n,o=a[1],a[2]print(\"\\124cFF\"..(C_QuestLog.IsQuestFlaggedCompleted(40168+o)and\"00FF00\"or\"c51a20\")..n..\"\\124r\")end",
            date = "2021-06-17T11:56:16-05:00",
            sourceUrl = "https://www.wowhead.com/quest=40787#comments:id=5197820",
        },
    },
    [40982] = {
        {
            id = 2369209,
            score = 23,
            author = "actuallysmart",
            text = "For some reason, when I logged out and logged back in while I had this quest, I couldn't complete it. I had to drop it and get it again and then my spectral sight worked.",
            date = "2016-08-16T20:47:01-05:00",
            sourceUrl = "https://www.wowhead.com/quest=40982#comments:id=2369209",
        },
        {
            id = 6266240,
            score = 10,
            author = "Zarathel",
            text = "After remix ended, my belf DH was stuck in org with phasing issues. I tried every thing mentioned on here and reddit, but none of it worked. I was randomly flying around when I fixed it!\nWith dragon riding switched on, I flew onto the roof above the gate. I then rode downstairs (not flying) to where Saurfang was. Then I flew upwards, over the top of the gate, straight to the very end of the dock. When I got there, I noticed that there were no ships at the dock. I rode on the ground (again, no flying) from the dock towards the gates of org and the quest giver was there. I really hope this works for others but Blizz really need to fix this phasing problem.",
            date = "2026-01-21T06:00:07-06:00",
            sourceUrl = "https://www.wowhead.com/quest=40982#comments:id=6266240",
        },
        {
            id = 6222419,
            score = 6,
            author = "Beartalk",
            text = "While working on this quest chain for remix today I turned in Emissary (the quest that precedes this one) and then briefly saw Second Sight flash as an available quest option before it disappeared. I've tried reloading and exiting and re-entering the game but I can't get this quest to pop up for me again.",
            date = "2025-11-10T22:17:38-06:00",
            sourceUrl = "https://www.wowhead.com/quest=40982#comments:id=6222419",
        },
        {
            id = 6274075,
            score = 6,
            author = "Krynnyth",
            text = "I made a video capturing myself fixing my Lemix DH. Note - I did the BFA intro prior to this in an attempt to fix the phase.\n\nhttps://www.youtube.com/watch?v=TMmEcuw1TlY",
            date = "2026-01-30T13:36:30-06:00",
            sourceUrl = "https://www.wowhead.com/quest=40982#comments:id=6274075",
        },
        {
            id = 6267976,
            score = 4,
            author = "Dracomann",
            text = "For those that try to get to this quest to unphase their DH from remix i found a fast and reliable fix.\nif you can't see \"second sight\" quest go inside of orgrimmar and when looking towards sourfang to the left of him a character named warchiefs herald.\nwhen speaking with him he should give a quest thats called \"battle for azeroth: mission statement\" when i take that it have phased me to the normal phase every time DON'T COMPLETE IT.\nafter taking the quest go outside orgrimmar and the second sight quest should be doable.\nthen do second sight questline all the way to weapons of the horde quest. after that i abandon the battle for azeroth: mission statement and my phases are back to normal.\nno long senarios or anything takes like 2 minutes",
            date = "2026-01-23T06:57:45-06:00",
            sourceUrl = "https://www.wowhead.com/quest=40982#comments:id=6267976",
        },
    },
