        },
        {
            id = 2482757,
            score = 1,
            author = "Cinnamohn",
            text = "Just leaving this here in case anyone ever has the same issue as myself:\nIf you complete this quest and do not receive In the Blink of an Eye automatically afterwards, and have absolutely no means to acquire it via an npc, you must remake the character. I contacted customer support and they sent me an automated response 2 days later, telling me to visit this website to figure out my problem.",
            date = "2017-04-03T08:37:24-05:00",
            sourceUrl = "https://www.wowhead.com/quest=41002#comments:id=2482757",
        },
    },
