    [42740] = {
        {
            id = 2364169,
            score = 52,
            author = "ThomasDWell",
            text = "Just in case you were like me and wondered, you do get the appearances of the other weapons your class can wield.",
            date = "2016-08-09T23:10:19-05:00",
            sourceUrl = "https://www.wowhead.com/quest=42740#comments:id=2364169",
        },
        {
            id = 2374319,
            score = 50,
            author = "Purgatorywolf",
            text = "Just for the fun of it, here's a list of the Demon's in the final stage.\n\nWill add more as I spot them.\n\nArch Magus Velysra\nAzoran\nBalnazzar\nBlackfire Fel Lord\nBlerg\nBrogozog\nCordana Felsong\nDantalionax\nDestromath\nDoomlord Kazrok\nFelwing\nGeth'xun\nGrand Summoner Abraxeton\nGrand Warlock Alythess\nHakkar the Houndmaster\nImp Mother Fecunda\nKrosus\nLady Keletress\nLady Ran'zara\nLady Sacrolash\nLord Jaraxxus\nLord Kra'vos\nLord Perdition\nMakaan the Malevolent\nMal'ganis\nMalgalor\nMalinoth\nMephistroth\nOublion\nOverseer Lykill\nPhantomflame Infernal\nPilik\nSathrovarr the Corruptor\nSmashspite the Hateful\nSoulchaser\nTichondrius the Darkener\nVaredis Felsoul\nVaultwarden Umbra\n\nI noticed most of these are ones we've yet to meet, but there's also some familiar faces.",
            date = "2016-08-27T21:52:19-05:00",
            sourceUrl = "https://www.wowhead.com/quest=42740#comments:id=2374319",
        },
        {
            id = 2365374,
            score = 25,
            author = "Zaydene",
            text = "Since you get all of the weapon appearances that your class can use, I'd recommend doing this scenario on a Hunter & Druid in order to get all 9 looks.\n\nAdditionally, a warrior should be able to unlock all 9 unique appearances at once. (Thanks u/Nulgar!)",
            date = "2016-08-11T12:10:39-05:00",
            sourceUrl = "https://www.wowhead.com/quest=42740#comments:id=2365374",
        },
        {
            id = 2365300,
            score = 22,
            author = "1375880",
            text = "If you go through the scenario and you miss the treasure for the transmog, you have an opportunity to do it again if you don't complete the quest once the scenario is done, just abandon the quest and you can take it again and repeat the scenario.",
            date = "2016-08-11T09:46:45-05:00",
            sourceUrl = "https://www.wowhead.com/quest=42740#comments:id=2365300",
        },
        {
