        {
            id = 2367059,
            score = 19,
            author = "TegoZanduba",
            text = "The NPCs you get to duel are all possible garrison follower recruits brought back to Stormwind for the event.  They are:\n\nZelena Moonbreak (http://www.wowhead.com/search?q=Zelena+Moonbreak)\nAudra Stoneshield (http://www.wowhead.com/search?q=Audra+Stoneshield)\nRamall Trueoak (http://www.wowhead.com/search?q=Ramall+Trueoak)\nNiall Frostdrift (http://www.wowhead.com/search?q=Niall+Frostdrift)\nHaagios (http://www.wowhead.com/search?q=Haagios)\nCiarra Neil (http://www.wowhead.com/search?q=Ciarra+Neil)\nArctic Whitemace (http://www.wowhead.com/search?q=Arctic+Whitemace)\nKihra (http://www.wowhead.com/search?q=Kihra)\nTessa Wybroff (http://www.wowhead.com/search?q=Tessa+Wybroff)\nStormsinger Taalos (http://www.wowhead.com/search?q=Stormsinger+Taalos)\nLightshield Baetrix (http://www.wowhead.com/search?q=Lightshield+Baetrix)\nNavea the Purifier (http://www.wowhead.com/search?q=Navea+the+Purifier)\nAntone Sula (http://www.wowhead.com/search?q=Antone+Sula)\nLoranea (http://www.wowhead.com/search?q=Loranea)\nRorin Rivershade (http://www.wowhead.com/search?q=Rorin+Rivershade)\nBridgette Hicks (http://www.wowhead.com/search?q=Bridgette+Hicks)\nKymba Quickwidget (http://www.wowhead.com/search?q=Kymba+Quickwidget)\nFingall Flamehammer (http://www.wowhead.com/search?q=Fingall+Flamehammer)\nEunna Young (http://www.wowhead.com/search?q=Eunna+Young)\nFen Cinderpaw (http://www.wowhead.com/search?q=Fen+Cinderpaw)",
            date = "2016-08-13T22:55:46-05:00",
