    [44120] = {
        {
            id = 5410217,
            score = 34,
            author = "StoneLegion",
            text = "For those who are doing this in 2022. It ended here and this because it ended like this back before the expansion was out the pre-patch...\n\nWhat should happen is you would get a quest to go to Dalaran above Kara. That seems to auto complete when you use the script to check.\n\nSo now what you do is go to the Portal Room and go to Dalaran and talk to a Amisi Azuregaze in the Legerdemain Lounge and ask for the Hearthstone and your good to go... IDK why this whole thing was buggy, but it is what it is...",
            date = "2022-08-02T17:03:21-05:00",
            sourceUrl = "https://www.wowhead.com/quest=44120#comments:id=5410217",
        },
        {
            id = 6119266,
            score = 19,
            author = "gamergirlasuna",
            text = "If you're doing this in the ripe year of 2025 and get no follow up quest, talk to the Archivist Elysiana to the left when you enter violet citadel in Dalaran and you should get [quest=40717 domain=www] - there's no portal to Dalaran over Kara anymore you need to fly over there to continue.\n\n*Anytime after these quests that you don't get a follow up, she should have it for you.",
            date = "2025-05-29T10:41:12-05:00",
            sourceUrl = "https://www.wowhead.com/quest=44120#comments:id=6119266",
        },
        {
            id = 2369166,
            score = 5,
            author = "Eillesthis",
            text = "After this, and \"Protect the Home Front\" (https://www.wowhead.com/quest=40661, Defeat a Legion Invasion), at some seemingly random point, comes \"Calling of the Council\" (https://www.wowhead.com/quest=40717, Meet Khadgar in Dalaran at its new location above Deadwind Pass).  More weirdness with the outdated title and objective on wowhead.",
            date = "2016-08-16T19:12:01-05:00",
            sourceUrl = "https://www.wowhead.com/quest=44120#comments:id=2369166",
