    [44543] = {
        {
            id = 2364063,
            score = 20,
            author = "Thatsoureric",
            text = "For anyone wondering, yes, whatever class you complete the quest with, ALL\nthe remaining weapon rewards will be unlocked & added to your transmog tab.\n\nThis way you don't have to redo the same quest multiple times on different\nalts just to get every weapon for transmog purposes.",
            date = "2016-08-09T19:15:47-05:00",
            sourceUrl = "https://www.wowhead.com/quest=44543#comments:id=2364063",
        },
        {
            id = 2364564,
            score = 2,
            author = "Darthias",
            text = "I can confirm what Jetstream has said as well, that this is the case.  It just will take the servers a minute or two to confirm it.",
            date = "2016-08-10T11:50:00-05:00",
            sourceUrl = "https://www.wowhead.com/quest=44543#comments:id=2364564",
        },
        {
            id = 5203614,
            score = 1,
            author = "LentzRose",
            text = "How do you get this version of the quest I can pick up the other one but I can't figure out how to pick this one up. Never mind I used my class token apparently this is the class token version",
            date = "2021-06-24T21:31:43-05:00",
            sourceUrl = "https://www.wowhead.com/quest=44543#comments:id=5203614",
        },
        {
            id = 2370438,
            score = -1,
            author = "zharshoul",
            text = "It was certainly different playing this raid styled scenario, not so much because it was a raid style scenario but because of the different interpretation of the legion that we see blizzard has given us.\n\nPrior to this scenario/expansion the legion were portrayed more like classic dnd for the EVULS magic/hack and slash style demons. The kind of unreasoning, corrupting and destroying evil because they are evil kind of evil. The most Magitech they ever got to was pretty much making infernals and a few fel cannons. Most of the \"demon tech\" in burning crusade came across as belonging to Illidan in my opinion and not really \"legion tech\" to me anyway.\n\nThis time or perhaps having slowly led up to this, they almost resemble the zerg to be honest, lots of \"species/types\" under the category of demon working under the cause of the \"legion\"\n\nThere is heavy use of magitech and just flat out tech, demons of all shapes types and sizes, many of whom really were already \"demons\". They work together in unity under a common cause of spreading their green tainty style land and killing off possible threats, converting the species/individuals they find useful into fellow \"demons\".\n\nHonestly they do not really sound like demons anymore, just another race/group that is expansionist and trying to get more territory to grow/raise their offspring on, we have yet to really see demon children, but already there is a mob called \"imp mother\" and a race like demons/zerg don't really have long childhoods anyway, they grow/morph fast to their chosen caste/unit type.\n\nI suspect they just humor larpers like Guldan, letting a megalomaniac act out his destruction fantasies is a small price to pay so that there is more territory to expand upon.",
            date = "2016-08-19T00:39:36-05:00",
            sourceUrl = "https://www.wowhead.com/quest=44543#comments:id=2370438",
        },
        {
            id = 2366853,
            score = -6,
            author = "Aldristavan",
            text = "UPDATE: I had my loot set to Survival. *DERP*\n\nJust completed this as a marksmanship hunter. The reward was a polearm, not a bow. WTF. (And yes, I reported it as a bug)",
            date = "2016-08-13T14:16:33-05:00",
            sourceUrl = "https://www.wowhead.com/quest=44543#comments:id=2366853",
        },
    },
    [44557] = {
        {
            id = 2436749,
            score = 37,
            author = "grouchomarx",
            text = "If you went into the right side of the cave like me, you'll end up at a big green wall of blockage.  You will get a disguise later in the quest chain to open this barrier where you drink a potion, step on the little circle platform and then it will open it.  The disguise will also make you appear friendly to the mobs in the cave, so use it liberally.   You have to go to 48,78, down into the cellar and close the 4 portals, then you can proceed further into the quest chain to get the disguise.",
