            sourceUrl = "https://www.wowhead.com/quest=44686#comments:id=2456276",
        },
    },
    [44733] = {
        {
            id = 2436012,
            score = 93,
            author = "0rph3n",
            text = "After you kill the two demons, use again the Essence of Wyrmtongue, that is in your bags, so you don´t have to fight back to your exit from the cavern",
            date = "2016-10-28T00:12:18-05:00",
            sourceUrl = "https://www.wowhead.com/quest=44733#comments:id=2436012",
        },
        {
            id = 2436504,
            score = 90,
            author = "IsisSaurfang",
            text = "Entrance at (47.72, 78.25)\n\nI had to click off my disguise to attack quest mobs.",
            date = "2016-10-28T22:55:20-05:00",
            sourceUrl = "https://www.wowhead.com/quest=44733#comments:id=2436504",
        },
        {
            id = 2437626,
            score = 74,
            author = "derjarjarbinks",
            text = "If you are like me, you have to stand on the fire near the portal in the cave with your disguise, so you get the acces to the portal. I was standing next to it, but that didn't work.",
            date = "2016-10-30T16:08:39-05:00",
            sourceUrl = "https://www.wowhead.com/quest=44733#comments:id=2437626",
        },
        {
            id = 2453828,
            score = 54,
            author = "Alarien",
            text = "For those that prefer not watching too long videos, just go down to the bottom of the same cellar (the one closest to the quest giver) you did in the previous quest to where the glowing green fel curtain/door is and then step ON the little round green plate or brazier beside the curtain. There is no cogwheel to indicate that you can interact with it, but you must step on it and the curtain will disappear to allow you in. Kill bosses. Done.",
            date = "2016-12-15T00:19:10-06:00",
            sourceUrl = "https://www.wowhead.com/quest=44733#comments:id=2453828",
        },
        {
            id = 2540030,
            score = 37,
            author = "806196",
            text = "Let's clear up a few things:\ngo down the stairs where Archmage Leryda is standing at 74,80;\ngo clear to the bottom back of the cave until you find the green flame curtain;\njump up on the green thing to the right of the curtain;\nit will something like \"the chamber is open\" and the curtain will disappear;\ngo into the chamber and speak to Elux'ara (she's further back in the chamber near a portal);\nshe will remove your disguise;\nfight her and then Thar'zul;\nget out of the chamber quickly, stopping on the ramp out of the chamber (they respawn in seconds);\nreapply your disguise, Essence of Wyrmtongue is in your backpack;\nwalk out and turn the quest in.",
            date = "2017-12-11T21:58:04-06:00",
            sourceUrl = "https://www.wowhead.com/quest=44733#comments:id=2540030",
        },
    },
