    [45734] = {
        {
            id = 2547839,
            score = 3,
            author = "AddictedPoi",
            text = "The turn-in quests are good for levelling followers.\nFollowers get 1000 XP once they are level 110.\nI used Raw Clefthoof Meat (http://www.wowhead.com/item=109131/raw-clefthoof-meat), which can be bought using garrison resources. 20 meats for 1k XP.\n\nMacro for buying 50 meat at a time:\n/run  BuyMerchantItem(17,50)\nMacro for turning in:\n/script SelectGossipAvailableQuest(6)\n/script CompleteQuest()\n/script GetQuestReward()",
            date = "2018-01-22T05:01:52-06:00",
            sourceUrl = "https://www.wowhead.com/quest=45734#comments:id=2547839",
        },
