    [45785] = {
        {
            id = 2465722,
            score = 5,
            author = "rogermw",
            text = "This quest appears in your quest log automatically the moment you enter Silithus.",
            date = "2017-01-21T22:23:19-06:00",
            sourceUrl = "https://www.wowhead.com/quest=45785#comments:id=2465722",
        },
        {
            id = 3184580,
            score = 3,
            author = "iIIumnati",
            text = "Go to Rhonormu (right near the question mark on the map) or Zidormi\nnear Valor's Rest (/way 79 22) and ask him to show you what the World\nwas like before the wound in the world. Now go back to the question mark\non your map (/way 34 80.5) and Field Marshall Snowfall will complete the\nquest.",
            date = "2020-01-21T20:19:24-06:00",
            sourceUrl = "https://www.wowhead.com/quest=45785#comments:id=3184580",
        },
        {
            id = 5313719,
            score = 3,
            author = "Phasha",
            text = "To go to the old (pre-Legion) version of Silithus, you can either speak to https://www.wowhead.com/npc=128607 at 79,22 or https://www.wowhead.com/npc=133263 at 33,81 (near our quest's completion question mark): \"Can you show me what Silithus was like before the Wound in the World?\"",
            date = "2022-01-23T03:09:27-06:00",
            sourceUrl = "https://www.wowhead.com/quest=45785#comments:id=5313719",
        },
    },
    [45787] = {
        {
            id = 2547543,
            score = 38,
            author = "Pennywise87",
            text = "If you defeated Argus you must go back to the old Silithus to see him. You can go back with the help of Rhonormu or Zidormi (see Map).",
            date = "2018-01-21T04:32:06-06:00",
            sourceUrl = "https://www.wowhead.com/quest=45787#comments:id=2547543",
        },
        {
            id = 3185523,
            score = 16,
            author = "Hec80",
            text = "was this a one-day event ? I had the quest but didn't have time to do, came back to try today but there is no Field Marshall Snowfall waiting to speak to me either in present time or 'earlier, time ...",
            date = "2020-01-24T13:08:27-06:00",
            sourceUrl = "https://www.wowhead.com/quest=45787#comments:id=3185523",
        },
        {
            id = 3195934,
            score = 12,
            author = "jadedthoughts",
            text = "This is a quote from the PTR notes, pertaining to the Micro-Holiday.\n\nCall of the Scarab (January 21 - 23): \"On this date, the Scarab Gong was rung, opening the gates of Ahn'Qiraj. Represent your faction by gathering supplies or by slaying Twilight and Qiraji forces. The winning faction gets to fly their banner next to the Scarab Gong for the rest of the year!\"\n\nThe event will pit the Alliance and Horde against each other to earn the most credit: whoever wins can fly their faction flag in Silithus for a year. Learn more about the event by heading down to the Field Marshals by the gong in Silithus.\n\nThey may do this again next year, but you are probably better served to drop the quest and get it again when the NPCs are available for you to turn in the quest.",
            date = "2020-03-23T21:27:08-05:00",
            sourceUrl = "https://www.wowhead.com/quest=45787#comments:id=3195934",
        },
        {
            id = 2547400,
            score = 7,
            author = "Istimial",
            text = "EU - Anachronos, he's not there... Several people are there, and can't see him anywhere :( Relog didn't help.",
            date = "2018-01-20T18:28:46-06:00",
            sourceUrl = "https://www.wowhead.com/quest=45787#comments:id=2547400",
        },
        {
            id = 5313718,
            score = 3,
            author = "Phasha",
            text = "To go to the old (pre-Legion) version of Silithus, you can either speak to https://www.wowhead.com/npc=128607 at 79,22 or https://www.wowhead.com/npc=133263 at 33,81 (more convenient for this quest): \"Can you show me what Silithus was like before the Wound in the World?\"",
            date = "2022-01-23T03:08:40-06:00",
            sourceUrl = "https://www.wowhead.com/quest=45787#comments:id=5313718",
        },
    },
    [46727] = {
        {
            id = 5232844,
            score = 299,
            author = "Anshlun",
            text = "Unable to get this quest in Shadowlands? Talk to https://www.wowhead.com/npc=49748 near the Hero's Call Board at the Trade District in Stormwind to pick-up this quest.",
            date = "2021-08-05T17:22:37-05:00",
            sourceUrl = "https://www.wowhead.com/quest=46727#comments:id=5232844",
        },
        {
            id = 3201346,
            score = 99,
            author = "MrAramaki",
            text = "I faction changed to Alliance during Visions of N'zoth with my lvl 120 character and couldn't complete the quest at first. Here is how i solved the problem:\n\n1. Do the Furorion introduction quest. Get Magni's hammer etc. You will then get a quest that sends to to the Heart Chamber in Silithus.\n2. Set hearthstone in Stormwind\n3. Go through the Uldum portal in SW. Fly to the Heart chamber and hand in the quest.\n4. Abandon the Tides of War quest. Use hearthstone back to SW\n5. After the loading screen, Tides of War should plop up in your Questlog again, accept.\n6. Fly to the castle. You should now see Anduin surrounded by Jaina and Genn, ready to complete the quest.\n\nGood Luck : )",
            date = "2020-04-21T11:23:30-05:00",
            sourceUrl = "https://www.wowhead.com/quest=46727#comments:id=3201346",
        },
        {
            id = 2551329,
            score = 51,
            author = "Zanzari",
            text = "Pack your bags? Anduin, I don't know if anyone told you but we champions usually empty our bags before we go on adventure.",
            date = "2018-02-07T17:37:36-06:00",
            sourceUrl = "https://www.wowhead.com/quest=46727#comments:id=2551329",
        },
        {
            id = 3240004,
            score = 44,
            author = "BlizzardCS",
            text = "Greetings, all!\n\nWe can confirm that this quest is currently not working as intended and we're hoping to implement a solution as soon as possible. We recommend keeping an eye on the following Support article as we'll be updating it as soon as we have more information to share:\n\nhttps://us.battle.net/support/article/000275307",
            date = "2020-10-18T14:44:19-05:00",
            sourceUrl = "https://www.wowhead.com/quest=46727#comments:id=3240004",
        },
        {
            id = 3239505,
            score = 28,
            author = "Trabuco",
            text = "The quest is not appearing for my old 110 alters after skipping the Lordaeron scenario.\n\nI leveled to 50 on Draenor with one of them and I could use the portal to Boralus but the war campaign or the quests cannot be started.\n\nAt least, after doing the neck quest at level 50 you can unlock the World quests, but not the Nazjatar questline.",
            date = "2020-10-17T11:12:25-05:00",
            sourceUrl = "https://www.wowhead.com/quest=46727#comments:id=3239505",
        },
    },
    [46728] = {
        {
            id = 2879542,
            score = 37,
            author = "KYZ123",
            text = "For this quest, the Kul Tiras intro experience diverges if you are playing a Kul Tiran.\n\nInstead of the usual options (including the option to skip, which you should have if you've unlocked Kul Tirans), the dialogue you can say to Jaina is 'Take me home.' (https://i.imgur.com/3YEvypV.jpg)\n\nUsing the dialogue option skips some of the quests and teleports you to the Harbormaster's Office, where Taelia offers A Nation Divided (https://www.wowhead.com/quest=47189/a-nation-divided).",
            date = "2019-03-30T17:14:37-05:00",
            sourceUrl = "https://www.wowhead.com/quest=46728#comments:id=2879542",
        },
        {
            id = 2592730,
            score = 23,
            author = "Graysmith",
            text = "If you choose the skip option (given to you if you've previously completed the intro quests on another character) you will jump ahead to https://www.wowhead.com/quest=47099, skipping the Jaina cutscenes and the Tol Dagor jailbreak.",
            date = "2018-08-14T12:14:15-05:00",
            sourceUrl = "https://www.wowhead.com/quest=46728#comments:id=2592730",
        },
        {
            id = 2596449,
            score = 16,
            author = "sitecow09",
            text = "\"Ahoy, ahoy, sweet Daughter of the Seas.\nAhoy this child be mine.\nThe Admiral's world, his whole entire world, for as long as stars do shine.\n\n\"Beware, beware the Daughter of the Sea.\"\n\"Beware,\" I heard him cry.\nHis words carried upon the ocean breeze,\nAs he sank beneath the tide.\n\nThose blood-soaked shores of Kalimdor,\nWhere sailors fought and died.\nThe Admiral fell at Theramore,\nbecause she left his side.\n\nWhy this? Why this, oh Daughter of the Sea?\nWhy this? Did you forget your seaside days?\nAlways the pride of our nation's eyes,\nHow could she go astray?\n\nWhen she did flee across the ocean deep,\nthe Admiral followed west.\nWhat else but sail to save a daughter's life,\nand pray she still drew breath?\n\nBut there he found upon those distant shores,\nEnemies 'pon the rise!\nBut when he faced those savage foes\nHis daughter stood aside.\n\nAnd buried deep beneath the waves,\nBetrayed by family.\nTo his nation, with his last breath, cried,\n\"Beware the Daughter of the Sea.\"\n\nI heard, I heard, across a moonlit sea,\nThe old voice warning me,\n\"Beware, beware the Daughter of the Sea\",\n\"Beware, beware...\"\n...of me.",
            date = "2018-08-17T10:23:26-05:00",
            sourceUrl = "https://www.wowhead.com/quest=46728#comments:id=2596449",
        },
        {
            id = 2620017,
            score = 8,
            author = "Pallipwns",
            text = "If you skip this you miss out on several hundred rep, I would recommend not doing so. Not that hard/long of a quest chain.",
            date = "2018-09-29T21:49:51-05:00",
            sourceUrl = "https://www.wowhead.com/quest=46728#comments:id=2620017",
        },
