    [47663] = {
        {
            id = 2530137,
            score = 50,
            author = "Cheesecaker",
            text = "This quest is actually \"A Timely Summons from Shattrath\", available from https://www.wowhead.com/npc=111246 while Burning Crusade Timewalking (event=559) is active.  It is essentially a breadcrumb quest to https://www.wowhead.com/quest=47523, the Black Temple Timewalking quest.\n\nQuest Text:\nA Timely Summons from Shattrath\nThe blazing star holds a peculiar alignment this cycle, calling out across the heavens. Seek out the sage https://www.wowhead.com/npc=123252 in [zone=3703], and lend her your aid.\nQuest Objectives\nMeet with Vormu in Shattrath.\nRewards\nYou will receive: 1g94s\n\nNote that if you join a group to run Black Temple Timewalking while you have this quest in your log you will be unable to turn it in and will have to abandon it in order to pick up https://www.wowhead.com/quest=47523.  This quest is not flagged as a Raid quest, and therefore you cannot make any progress on it while in a raid group.",
            date = "2017-10-17T12:54:26-05:00",
