    [50130] = {
        {
            id = 3163763,
            score = 25,
            author = "Daggah666",
            text = "if a player reaches neutral or friendly reputation with Sporeggar prior to taking the quest it is no longer an avaialble quest and cannot be completed on that toon",
            date = "2019-10-13T08:05:21-05:00",
            sourceUrl = "https://www.wowhead.com/quest=50130#comments:id=3163763",
        },
        {
            id = 2582441,
            score = 13,
            author = "slumber",
            text = "it looks like these reputation quests were added in 7.3.5 to hold your hand through getting sporeggar rep.\n\nafter you complete https://www.wowhead.com/quest=9743 and https://www.wowhead.com/quest=9739, you get https://www.wowhead.com/quest=50131, which tells you to get to neutral.  this acts as a gentle nudge to do the repeatable quests offered by https://www.wowhead.com/npc=17923 (https://www.wowhead.com/quest=9742 and https://www.wowhead.com/quest=9744) until you reach neutral and can move on in the sporeggar quest chain... and it appears that these quests continue on from there, with this one being offered after you turn in https://www.wowhead.com/quest=9919.\n\nit seems overall like a very small quality-of-life improvement that makes it easier to figure out how to advance through the sporeggar reputation questline as well as the \"a trip with the sporelings\" criteria of https://www.wowhead.com/achievement=1190, since so much of it can be done through repeatable turn-in quests instead of one-time quests.",
            date = "2018-07-19T18:08:53-05:00",
            sourceUrl = "https://www.wowhead.com/quest=50130#comments:id=2582441",
        },
        {
            id = 6061360,
            score = 1,
            author = "Goblinaire",
            text = "Perhaps this has changed sometime in the past 6 years, but you can pick up this quest at Neutral as well. You must complete https://www.wowhead.com/quest=9919 first.\n\nIf you go into Friendly territory after completing https://www.wowhead.com/quest=9919, this quest will become unavailable.\n\nHOWEVER, you can open your Character->Reputation tab up, click on Sporeggar, select \"At War,\" then slaughter Sporeggar mobs until your rep falls back into Neutral. The quest will then become available once again.",
            date = "2025-02-07T08:56:32-06:00",
            sourceUrl = "https://www.wowhead.com/quest=50130#comments:id=6061360",
        },
    },
    [50131] = {
        {
            id = 3163764,
            score = 17,
            author = "Daggah666",
            text = "if a player reaches neutral or friendly reputation with Sporeggar prior to taking the quest it is no longer an avaialble quest and cannot be completed on that toon  Confirmed by GM ticket response",
            date = "2019-10-13T08:09:57-05:00",
            sourceUrl = "https://www.wowhead.com/quest=50131#comments:id=3163764",
        },
        {
            id = 5233562,
            score = 11,
            author = "dawn22868",
            text = "If you're a completionist and are looking for a way to complete this quest after reaching neutral, here's what you can do:\n\n1) Open up a group and activate party sync.\n2) Redo the quests https://www.wowhead.com/quest=9739 & https://www.wowhead.com/quest=9743 from https://www.wowhead.com/npc=17923. DON'T ACCEPT https://www.wowhead.com/quest=9919!\n3) Open your reputation tab and set yourself at war against Sporeggar.\n4) Go to Sporeggar and kill dem all. Each kill gave me -25 rep and -50 for Msshi'fn. Depending on your rep, this can take a while.\n5) Once you reach unfriendly status, go back to https://www.wowhead.com/npc=17923 and accept https://www.wowhead.com/quest=50131.\n\nThe Sporeggar guys take quite some time to respawn (2-5mins). Go farm https://www.wowhead.com/npc=21076 during the downtime.\nMake sure party sync stays active until you're done :)",
            date = "2021-08-07T19:13:06-05:00",
            sourceUrl = "https://www.wowhead.com/quest=50131#comments:id=5233562",
        },
        {
            id = 2562863,
            score = 5,
            author = "Tamzar",
            text = "This neutral quest is the lead-in for the \"Trip with the Sporelings\" section of https://www.wowhead.com/achievement=1190. Completing his two dailies will likely leave you with a short distance from the next reputation level. Kill some more bog lords, or wait for the daily to refresh in order to continue the quest chain into Sporregar itself.",
            date = "2018-04-14T18:58:22-05:00",
            sourceUrl = "https://www.wowhead.com/quest=50131#comments:id=2562863",
        },
        {
            id = 3178426,
            score = 3,
            author = "LaffiBoozegnome",
            text = "An Outside Perspective requires the two first quests completed from Fahssn, and unfriendly reputation with Sporeggar.\n\nIt's very simple. Do the first 2 quests, but don't hand in the one named Sporeggar.\nShould be just under neutral.",
            date = "2019-12-26T03:48:50-06:00",
            sourceUrl = "https://www.wowhead.com/quest=50131#comments:id=3178426",
        },
        {
            id = 5561595,
            score = 3,
            author = "Gobbogossip",
            text = "Often missed as many players may already possess enough bog lord tendrils from earlier trips to the Dead Mire to hand in the repeatable quest with Fahssn, pushing you over to neutral reputation even before this.quest becomes obtainable.",
            date = "2023-03-09T04:48:44-06:00",
            sourceUrl = "https://www.wowhead.com/quest=50131#comments:id=5561595",
        },
    },
