    [50769] = {
        {
            id = 2593151,
            score = 386,
            author = "cmdrnate",
            text = "If you have already done the whole Stormwind extraction scenario, don't pick up the potion and talk to Nathanos to skip right to the intro to Zandalar city.",
            date = "2018-08-14T18:04:35-05:00",
            sourceUrl = "https://www.wowhead.com/quest=50769#comments:id=2593151",
        },
        {
            id = 2566805,
            score = 32,
            author = "Cielos",
            text = "When you drink the https://www.wowhead.com/item=160251, you do die.  However, when you release, you resurrect in the same place where you died.  No long run from Elwynn Forest.",
            date = "2018-05-10T18:11:43-05:00",
            sourceUrl = "https://www.wowhead.com/quest=50769#comments:id=2566805",
        },
        {
            id = 2577699,
            score = 25,
            author = "AbductionEnt",
            text = "When following in stealth, be sure to dismiss pets, demons, minions, ectera, before jumping off the bridge into the water. If not, they will bring about 4 guards with them down the stairs to you and reset the part.",
            date = "2018-07-02T01:04:46-05:00",
            sourceUrl = "https://www.wowhead.com/quest=50769#comments:id=2577699",
        },
        {
            id = 2591878,
            score = 23,
            author = "Vger",
            text = "To get into the sewer grate in Stage 2, click on the two small padlocks.",
            date = "2018-08-13T19:21:28-05:00",
            sourceUrl = "https://www.wowhead.com/quest=50769#comments:id=2591878",
        },
        {
            id = 2618204,
            score = 19,
            author = "iIIumnati",
            text = "I discovered the trick to getting stuck at stage 7.\n\nI had to restart the scenario because I had aggroed Genn Greymane and his two guards. Once that happened Genn repeatedly kill me as I approached the dome. The next time I ran the scenario, when I got to stage 7, I realized that the NPCs are not stuck because of Greymane, but rather the non elite worgen that are trying to penetrate the dome. Once you kill all the worgen, the NPCs will \"unstick\" and let you progress through stage 7.\n\nI repeat ... do not attack Greymane or his two body guards, but instead kill all the worgen bouncing off the dome.",
            date = "2018-09-23T16:38:06-05:00",
            sourceUrl = "https://www.wowhead.com/quest=50769#comments:id=2618204",
        },
    },
    [51443] = {
        {
            id = 2621832,
            score = 94,
            author = "Healeos",
            text = "FYI.  Right before you take a potion after you meet your team, you can speak to Nathanos and take the option to skip the scenario!  YAY!",
            date = "2018-10-07T09:59:00-05:00",
            sourceUrl = "https://www.wowhead.com/quest=51443#comments:id=2621832",
        },
        {
            id = 2616916,
            score = 75,
            author = "Drayline",
            text = "If you have transferred your char/faction changed it and Sylvannas won't talk to you/you can't complete the mission statement and/or don't have any quest, you can;\na) Take a mage portal to Zuldazar.\nb) Take the Golden Skipper boat at the troll starting zone (Echo Isles).\nMeet Nathanos Blightcaller on the dock, get the quest, go back to Orgrimmar and complete 'Talk to Sylvannas' etc.",
            date = "2018-09-19T19:19:42-05:00",
            sourceUrl = "https://www.wowhead.com/quest=51443#comments:id=2616916",
        },
        {
            id = 6133049,
            score = 30,
            author = "Helpersson",
            text = "For those who have forgotten (i.e. your main did the intro questline ages ago and now you want an alt to have quick access to BfA for world quests or whatever):\n\n1) accept this quest, head into Grommash Hold. A cinematic will start (which you can, of course skip).\n2) head to the inn, wait for Nathanos to enter and then hand in the 'Battle for Azeroth: Mission Statement' quest to him.\n3) Nathanos will then offer you 'The Stormwind Extraction' quest. Accept it (but don't drink the poison!)\n4) speak to Nathanos again. He will now offer you the BfA intro skip.\n5) take the skip and, after another skippable cinematic, you will find yourself in the Port of Zandalar next to Nathanos.\n6) you can now hand in 'The Stormwind Extraction' quest to Nathanos.\n\nWelcome to BfA!\n\nFor those that want maximum speed, there is another little skip available after this:\n\n7) pick up 'Welcome to Zuldazar' from Princess Talanji (who will be just in front of you)\n8) you have to slowly escort her and listen to her speak (you can't fly ahead)\n9) hand in 'Welcome to Zuldazar' to General Jakra'zet.\n10) accept the quest, 'Rastakhan' from General Jakra'zet BUT DO NOT MOUNT THE PTERRORDAX OR FLY YOURSELF TO KING RASTAKHAN!\n11) instead, speak to Talanji and she will offer you another skip option. Take it.\n12) another cinematic will start (which you can, of course, skip).\n13) you will then find yourself next to King Rastakhan where you can hand him in the 'Rastakhan' quest and go on to establish your embassy. If you want, after speaking to the nearby NPC to start her walking and talking, you can fly down to the next level and wait for the Horde banner to appear instead of escorting her.\n\nWelcome to BfA, Speaker of the Horde!",
            date = "2025-06-25T19:38:20-05:00",
            sourceUrl = "https://www.wowhead.com/quest=51443#comments:id=6133049",
        },
        {
            id = 5305719,
            score = 27,
            author = "cinny",
            text = "if a fresh alt doesn't see this quest/is not eligible make sure to do the first quest(s) of the legion introduction questline (https://www.wowhead.com/quest=43926/legion-the-legion-returns)",
            date = "2022-01-06T07:25:40-06:00",
            sourceUrl = "https://www.wowhead.com/quest=51443#comments:id=5305719",
        },
        {
            id = 2565325,
            score = 14,
            author = "Ogait",
            text = "In order to complete the quest, you'll have to find your team (https://www.wowhead.com/npc=97140, https://www.wowhead.com/npc=120787 and https://www.wowhead.com/npc=112586) in The Broken Tusk.\nIt is the house next to the Innkeeper in Orgrimmar.\n\nNext quest is: https://www.wowhead.com/quest=50769.",
            date = "2018-05-01T04:55:53-05:00",
            sourceUrl = "https://www.wowhead.com/quest=51443#comments:id=2565325",
        },
    },
    [51795] = {
        {
            id = 3245909,
            score = 66,
            author = "jeian7",
            text = "For everyone like me, who comes here looking for the scenario, here's your answer. (https://us.battle.net/support/en/article/177115)\n\nThe quest has been removed from the game, but if you liked the scenario and want to relive it, you can visit https://www.wowhead.com/npc=174146 (Alliance) or https://www.wowhead.com/npc=174147 (Horde).\n\nTo get started on BfA, you should be able to get a war council quest from the herald at a Hero's Call/Warchief's Command board.",
            date = "2020-11-05T21:30:41-06:00",
            sourceUrl = "https://www.wowhead.com/quest=51795#comments:id=3245909",
        },
        {
            id = 2592793,
            score = 44,
            author = "wowogamer",
            text = "If you have done this quest/scenario on another toon it is now possible to skip the quest by talking to the woman, Captain Angelica, who is standing beside Mathias Shaw.",
            date = "2018-08-14T13:10:01-05:00",
            sourceUrl = "https://www.wowhead.com/quest=51795#comments:id=2592793",
        },
        {
            id = 2563805,
            score = 21,
            author = "Voxxel",
            text = "The Lordaeron scenario (Alliance) is the first quest in the introductory story chapter https://www.wowhead.com/achievement=12582, which leads the Alliance to Kul Tiras. Completing the questline unlocks the Scouting Map in Boralus, allowing players to begin questing in Tiragarde Sound, Drustvar and Stormsong Valley. Level 110 characters will auto-accept the first quest when BfA hits the servers on August 14. 2018.\n\n[pre][BR]┌────────────────┐\n│ COME SAIL AWAY │ Prerequisite: character level 110 (Alliance)\n└────────────────┘\n\n1.Hour of Reckoning (/quest=53370) (Auto Accept)\n\009||\n2.The Battle for Lordaeron (/quest=51795)\n\009||\n3.A Dying World (/quest=53026)\n\009||\n4.The Heart of Azeroth (/quest=51211)    rewards: https://www.wowhead.com/item=158075 + https://www.wowhead.com/achievement=12918\n\009||\n5.Infusing the Heart (/quest=52428)\n\009||\n6.The Speaker's Imperative (/quest=51403)\n\009||\n7.Infusing the Heart (/quest=52428)\n\009||\n8.Tides of War (/quest=46727)\n\009||\n9.The Nation of Kul Tiras (/quest=46728)    option to skip story at https://www.wowhead.com/npc=120590. Select the gossip: \"I've heard this tale before...\"\n\009||\n10.Daughter of the Sea (/quest=51341)\n\009||\n11.Out Like Flynn (/quest=47098)\n\009||\n12.Get Your Bearings (/quest=47099)\n\009||\n13.The Old Knight (/quest=46729)\n\009||\n14.Sanctum of the Sages (/quest=47186)    available quest: Ferry Pass (/quest=52128) (Reward: https://www.wowhead.com/spell=274724) from https://www.wowhead.com/npc=122370\n\009||\n15.A Nation Divided (/quest=47189)",
            date = "2018-04-21T17:21:42-05:00",
            sourceUrl = "https://www.wowhead.com/quest=51795#comments:id=2563805",
        },
        {
            id = 3239712,
            score = 10,
            author = "Tiredandabused",
            text = "Anyone had an issue with this since pre-patch? My sisters got a level 35 that can’t get the quest line, like can’t find the guy at the docks or anything, idk if she needs to do the legion stuff first? My toon went through it all when it went live so idk about it now lol  (Talking new pre-patch like 2020 lol)",
            date = "2020-10-17T22:16:37-05:00",
            sourceUrl = "https://www.wowhead.com/quest=51795#comments:id=3239712",
        },
        {
            id = 2570060,
            score = 6,
            author = "Boxofbeer",
            text = "https://www.wowhead.com/quest=51795 is the starting quest of Battle for Azeroth for Alliance Side.\nAs usually, quest adds into the quest log automatically as a character logged into the game.\nYou have to find Captain Angelica at Stormwind Harbor and tell that you're ready to start.\nThs scenario is long enough, takes around 20 minutes to do, but nothing hard as it's global scenario.\nIf you cant realise what to / where to go, see what others do.\n\nhttps://www.wowhead.com/quest=51795 - www.youtube.com/watch?v=40yziS6S6Uc",
            date = "2018-05-26T11:50:06-05:00",
            sourceUrl = "https://www.wowhead.com/quest=51795#comments:id=2570060",
        },
    },
    [51796] = {
        {
            id = 3239078,
            score = 29,
            author = "Aloeverra",
            text = "This scenario appears to have been removed with the Shadowlands pre-patch. When starting the quest for Battle for Azeroth, it will immediately send you through the prisoner rescue scenario leading to Zuldazar.\nBelow is a link to the Wowhead playthrough with no commentary in case you want to watch the event.\n\nIf you wish to start the quests for Battle for Azeroth you get it from the Warchief's Herald (49,76) standing next to the Warchief's Command Board. He will give you the quest \"Mission Statement.\"\n\nIf you do not see this quest, the starter quest for Legion will make it disappear. You will need to abandon \"The Legion Returns\" in order to see it again.\n\nEDIT: It appears you can experience old scenarios by talking with Archivist Sylvia located in Orgrimmar in the Valley of Wisdom (46, 48), someone had a picture of her offering the Battle for Lordaeron in a screenshot, but when I speak with her on my level 17 troll, she does not offer it.",
            date = "2020-10-16T11:54:52-05:00",
            sourceUrl = "https://www.wowhead.com/quest=51796#comments:id=3239078",
        },
        {
            id = 2589220,
            score = 16,
            author = "Bursi",
            text = "https://www.wowhead.com/quest=50476 popped up after first login with a level 110 toon one week after prepatch for BfA.\nIf you completed the story with one character (of the same faction), you can talk to Sylvanas  \"I have heard this tale before\" to skip the chain after accepting https://www.wowhead.com/quest=50642 (step 2). You'll get teleported to the south of Darkshore with access to World Quests.\nYou will need to complete the previous chapters to unlock the following ones (chapter 1 and https://www.wowhead.com/quest=51796 (chapter 3, step 2) can be skipped).\n\nChapter 1 (unlocked 07/24/2018):\n\nhttps://www.wowhead.com/quest=50476  - meet https://www.wowhead.com/npc=134554 in Undercity (use the middle doorway in the Apothecarium to reach her -> /way [zone=1497] 53.22 62.73 Entrance). Don't use the teleporter from Silvermoon to go to Uc, this might kill you\nhttps://www.wowhead.com/quest=50642 - travel to Crossroads and meet https://www.wowhead.com/npc=134574\nhttps://www.wowhead.com/quest=50646 - travel to Astranaar in Ashenvale and meet https://www.wowhead.com/npc=134573\nhttps://www.wowhead.com/quest=50647 - dismount and use your extrabutton to mark the guards\nhttps://www.wowhead.com/quest=50738 - meet https://www.wowhead.com/npc=135003\nhttps://www.wowhead.com/quest=50740 - fly to Zoram'gar Outpost and speak to the mentioned NPC. Return to Astranaar\nhttps://www.wowhead.com/quest=50772 - turn in at the border between Ashenvale and Darkshore\nhttps://www.wowhead.com/quest=50800 - kill 6 enemies\nhttps://www.wowhead.com/quest=50823 - return to Zoram'gar Outpost\nhttps://www.wowhead.com/quest=50837 - speak to https://www.wowhead.com/npc=135501 and kill wisps and trees\nhttps://www.wowhead.com/quest=50880 - return to the border to Darkshore, pass the wall and wait for Sylvanas. Reload, if she doesn't appear for you\nhttps://www.wowhead.com/quest=53605 - burn glaives with your https://www.wowhead.com/item=158937\nhttps://www.wowhead.com/quest=53604 - kill 7 elfs\nhttps://www.wowhead.com/quest=50878 - kill 8 owls and 10 furbolgs\nhttps://www.wowhead.com/quest=50879 - kill https://www.wowhead.com/npc=141365 (cinematic after turn in)\nhttps://www.wowhead.com/quest=52436 - kill 10 furbolgs\nhttps://www.wowhead.com/quest=53606 - place 3 banners\nhttps://www.wowhead.com/quest=52437 - return to Zoram'gar Outpost\nhttps://www.wowhead.com/quest=53609 - kill 10 elfs\nhttps://www.wowhead.com/quest=53608 - collect Azerite lying around\nhttps://www.wowhead.com/quest=53627 - turn in at the marked area\nhttps://www.wowhead.com/quest=52438 - click https://www.wowhead.com/npc=141847, it will transport you. Kill enemies\nhttps://www.wowhead.com/quest=52806 - return to Sylvanas and click her dialogue\nAfter that 4 World Quests (/darkshore-quests/type:109) in [zone=148] popped up.\n\nIt took around 40 minutes.\n\n[hr]\nChapter 2 (unlocked on 07/31/2018):\n\nhttps://www.wowhead.com/quest=52967 - find Saurfang (I got this quest after entering [zone=148])\nhttps://www.wowhead.com/quest=52970 - click 8 citizens\nhttps://www.wowhead.com/quest=52971 - kill 2 named NPC (https://www.wowhead.com/npc=142749 and https://www.wowhead.com/npc=144345)\nhttps://www.wowhead.com/quest=53610 - kill 15 defenders\nhttps://www.wowhead.com/quest=52981 - fly to the marked area, find Saurfang, watch roleplay and meet Sylvanas at the beach (45.52, 18.26). Click her dialogue (cinematic)\n\nIt took around 11 minutes, starting at Darkshore's south & without cinematic.\n\nYou will gain https://www.wowhead.com/item=163128 (teaches https://www.wowhead.com/spell=272472) at the end (reward from https://www.wowhead.com/quest=52981) and also get https://www.wowhead.com/spell=274610 (https://www.wowhead.com/item=163127) for the other faction at the same time. So you only need to complete the quest chain on one faction to get both mounts, but they are bound to their faction.\n\n[hr]\nChapter 3 (unlocked on 08/07/2018):\n 12.00\nhttps://www.wowhead.com/quest=53372 - meet https://www.wowhead.com/npc=14720 (popped up after login)\nhttps://www.wowhead.com/quest=51796 - speak to Isabella on the left side, click the dialoge to start the scenario (20 man) - you can skip this step, if you completed this before on an other character\n- kill enemies to fill the bar\n- follow Saurfang and help him to go to the middle of Undercity\n- click the dialogue of Uc's citizens to fill the bar\n- use https://www.wowhead.com/npc=131087 below the bank\n- follow Saurfang and kill all enemies in front of Undercity (3 waves) (cinematic when done)\n- speak to a https://www.wowhead.com/npc=133115 to get https://www.wowhead.com/spell=261724. Click https://www.wowhead.com/npc=127065 to fill the bar (cinematic)\n- follow https://www.wowhead.com/npc=133243\n- fight against the Alliance (cinematic)\n- follow https://www.wowhead.com/npc=133243 again\n- wait for her and follow https://www.wowhead.com/npc=130365 (cinematic). You'll get transported to Og after that\n\nIt took ca. 27 minutes, starting in Og at Saurfang (ca. 21 without cinematics)\n\n[hr]\nChapter 4 (unlocked on BfA Release):\n9.24\nhttps://www.wowhead.com/quest=53028 - travel to Silithus and meet Magni (popped up after login). Speak to Zidormi (npc=128607#map), if you changed the phasing in Silithus before\nhttps://www.wowhead.com/quest=51211 - follow Magni to the translocator and click the console's dialogue (cinematic). Speak to Magni\nYou will get https://www.wowhead.com/item=158075 and https://www.wowhead.com/achievement=12918\nhttps://www.wowhead.com/quest=52428 - use your extrabutton https://www.wowhead.com/spell=275825 at the azerite ores to fill the bar, go to the middle and click it again\nhttps://www.wowhead.com/quest=53031 - go to Orgrimmar (use the transporter behind Magni) and meet https://www.wowhead.com/npc=140176\nhttps://www.wowhead.com/quest=51443 - enter Grommash Hold (cinematic) and meet your team in the inn\nhttps://www.wowhead.com/quest=50769 - click https://www.wowhead.com/item=160251 on the table and go to the wall. Click https://www.wowhead.com/npc=135211, it will transport you to the solo scenario:\n- destroy the two padlocks and enter Stormwind's sewer\n- go to the marked area and meet https://www.wowhead.com/npc=134038\n- click the door, speak to https://www.wowhead.com/npc=134120 (wait for his dialogue is complete before you open the next door. Might bug otherwise)\n- go to the mark on the other side, click the door to free the Zandalaris. Follow and defend your team on the way to the northeastern part of the dungeon. Click https://www.wowhead.com/npc=139948\n- speak to https://www.wowhead.com/npc=134038 and follow him. Speak to him again after you jumped into the water, follow again\n- kill attackers and follow your team and speak to https://www.wowhead.com/npc=134039. Follow again\n- destroy https://www.wowhead.com/npc=134881\n- kill enemies on your way to the nothern dock. Enter your ship and speak to https://www.wowhead.com/npc=134092 (cinematic)\nhttps://www.wowhead.com/quest=46957 - follow https://www.wowhead.com/npc=132661\nhttps://www.wowhead.com/quest=46930 - click https://www.wowhead.com/npc=135438, it will transport you to the princess. Talk to her (cinematic)\nhttps://www.wowhead.com/quest=46931 - speak to https://www.wowhead.com/npc=135441 and follow her. Use the elevator and click https://www.wowhead.com/npc=121000 at the balcony\nRe-enter the building and visit the tree chambers. Turn in at the other room at the floor\nhttps://www.wowhead.com/quest=52139 - meet the princess\nhttps://www.wowhead.com/quest=52131  cinematic. You get https://www.wowhead.com/achievement=12555 after turning in\nQuest line done - now you can chose your preferred quest area at the map on the table\n\nIt took ca. 55 minutes (ca. 50 without cinematics)",
            date = "2018-08-08T05:32:33-05:00",
            sourceUrl = "https://www.wowhead.com/quest=51796#comments:id=2589220",
        },
        {
            id = 3245912,
            score = 7,
            author = "jeian7",
            text = "For everyone like me, who comes here looking for the scenario, here's your answer. (https://us.battle.net/support/en/article/177115)\n\nThe quest has been removed from the game, but if you liked the scenario and want to relive it, you can visit https://www.wowhead.com/npc=174146 (Alliance) or https://www.wowhead.com/npc=174147 (Horde).\n\nTo get started on BfA, you should be able to get a war council quest from the herald at a Hero's Call/Warchief's Command board.",
            date = "2020-11-05T21:31:26-06:00",
            sourceUrl = "https://www.wowhead.com/quest=51796#comments:id=3245912",
        },
        {
            id = 2570065,
            score = 4,
            author = "Boxofbeer",
            text = "https://www.wowhead.com/quest=51796 is the starting quest of Battle for Azeroth for Horde Side.\nAs usually, quest adds into the quest log automatically as a character logged into the game.\nYou have to find Isabella at Grommash Hold and tell that you're ready to start.\nThs scenario is long enough, takes around 20 minutes to do, but nothing hard as it's global scenario.\nIf you cant realise what to / where to go, see what others do.\n\nhttps://www.wowhead.com/quest=51795 - www.youtube.com/watch?v=7YessUSASyQ",
            date = "2018-05-26T13:05:14-05:00",
            sourceUrl = "https://www.wowhead.com/quest=51796#comments:id=2570065",
        },
        {
            id = 2580239,
            score = 3,
            author = "varenne",
            text = "Initial Battle for Azeroth scenario from Horde Side. Takes around 15-25 minutes\nIf you done it before, alt character on your account can skip the scenario by selecting second option\nhttps://www.youtube.com/watch?v=7Riy2gL8xDI\n\nTalk to Isabella (Mage Trainer in Orgrimmar Grommash Hold)\n/way Orgrimmar 48.13 71.34 Talk to Isabella\nStage 1: Under Siege\nGo to the left, near the gates and find Hight Overlord Saurfang there\nStage 2: Spines in our Midst\nKill mobs in the area and free some friendly npc\nStage 3: To the Heart\nFollow Saurfang to the Heart of the City (he is at 52.48 82.99)\nStage 4: Evacuate the Heart of the City\nSame as step 2, kill mobs, save friendly units\nStage 5: To Battle\nUse portal to the city walls and follow Saurfang to the battlefield\n\nStage 6: Push them Back\nKill mobs in the battle.\nStage 7: Defend the Azerite War Machine\nDefeat 3 waves of attackers\n\nStage 8: Our Secret Weapon\nTake a gas mask from Sludge Guard and kill more alliance players or heal friendly units\nStage 9: Like Wildfire\nFollow Nathanos to the keep.\nWait for the door left of him to open\nStage 10: Hold them back\nIntercept the Alliance\nStage 11: The King Piece\nDefeat King Anduin and his Allies\nStage 12: Cry Havoc\nFollow Nathanos to safety\nStage 13: The Dark Lady\nFollow Sylvanas Windrunner\n\nHorde PoV: https://www.youtube.com/watch?v=Qan84YpHS8o\nAlliance PoV: https://www.youtube.com/watch?v=ws3rqdImXuA\n\nMore questchain info is under the spoiler or in https://www.wowhead.com/achievement=12555 post\n[spoiler]\n[table border=2][tr][td]ID[/td][td]Quest[/td][td]Questgiver[/td][td]Zone[/td][td]Note[/td][td]Video[/td][/tr]\n[tr][td]1[/td][td]https://www.wowhead.com/quest=53372[/td][td]In Orgrimmar[/td][td]Orgrimmar[/td][td][/td][td]https://youtu.be/wmbP2V8KnOA[/td][/tr]\n[tr][td]2[/td][td]https://www.wowhead.com/quest=51796[/td][td]https://www.wowhead.com/npc=140176[/td][td]Orgrimmar[/td][td]Scenario[/td][td]https://youtu.be/Qan84YpHS8o[/td][/tr]\n[tr][td]3[/td][td] https://www.wowhead.com/quest=53029 [/td][td] https://www.wowhead.com/npc=142509 [/td][td] Orgrimmar [/td][td][/td][td]https://youtu.be/JFE6curIPlA[/td][/tr]\n[tr][td]4[/td][td] https://www.wowhead.com/quest=51211 [/td][td] https://www.wowhead.com/npc=130216 [/td][td] Silithus: The Wound [/td][td]https://www.wowhead.com/item=158075 https://www.wowhead.com/achievement=12918[/td][td]https://youtu.be/8pBHdowDb6M[/td][/tr]\n[tr][td]5[/td][td] https://www.wowhead.com/quest=52428 [/td][td] https://www.wowhead.com/npc=136907 [/td][td] Chamber of Heart [/td][td]275 Azerite gear[/td][td]https://youtu.be/BOD-e1ULDKI[/td][/tr]\n[tr][td]6[/td][td] https://www.wowhead.com/quest=53031 [/td][td] https://www.wowhead.com/npc=136907 [/td][td] Chamber of Heart [/td][td][/td][td]https://youtu.be/2ACOH5tujhY[/td][/tr]\n[tr][td]7[/td][td] https://www.wowhead.com/quest=51443 [/td][td] https://www.wowhead.com/npc=140176 [/td][td] Orgrimmar [/td][td][/td][td]https://youtu.be/U6FVVGj3iKo[/td][/tr]\n[tr][td]8[/td][td] https://www.wowhead.com/quest=50769 [/td][td] https://www.wowhead.com/npc=135205 [/td][td] Valley of Strength [/td][td]Scenario, save Talanji [/td][td]https://youtu.be/iIFlJzbvzZw[/td][/tr]\n[tr][td]9[/td][td] https://www.wowhead.com/quest=46957 [/td][td] https://www.wowhead.com/npc=132332 [/td][td] Zuldazar [/td][td][/td][td]https://youtu.be/sZCTVmnPrL0[/td][/tr]\n[tr][td]10[/td][td] https://www.wowhead.com/quest=46930 [/td][td] https://www.wowhead.com/npc=122661 [/td][td] Zuldazar [/td][td]King Rastakhan Cutscene[/td][td]https://youtu.be/baApBoPIpC0[/td][/tr]\n[tr][td]11[/td][td] https://www.wowhead.com/quest=46931 [/td][td] https://www.wowhead.com/npc=120740 [/td][td] Zuldazar [/td][td][/td][td]https://youtu.be/0SfPBouIL94[/td][/tr]\n[tr][td]12[/td][td] https://www.wowhead.com/quest=52139 [/td][td] https://www.wowhead.com/npc=120168 [/td][td] Dazar'alor [/td][td][/td][td]https://youtu.be/H1l61E2jhds[/td][/tr]\n[tr][td]13[/td][td] https://www.wowhead.com/quest=52131 [/td][td] https://www.wowhead.com/npc=133050 [/td][td] Dazar'alor [/td][td]Cutscene https://www.wowhead.com/achievement=12555[/td][td]https://youtu.be/2kVZ8rv0l6U[/td][/tr]\n[/table]\n[/spoiler]",
            date = "2018-07-12T16:06:24-05:00",
