    [53120] = {
        {
            id = 2620087,
            score = 68,
            author = "Kismat",
            text = "Complete this quest by visiting Xun Xun Sweetflower near Anyport flight point and she will give you 250 reputation with the Order of Embers and 2g34s for your trouble.  Don't forget:  while you are there make sure you buy 10 x Tirasreli Gourmet Chocolate!\n\nYou can use this chocolate to unlock a pet vendor at a treehouse (52.4, 31.5) in Drustvar. Inside the treehouse you can loot a chest which will give you Adventurer's Society Loot Stash. The first time you loot the chest you will receive Stolen Candy and for 1 hour you will receive the title %s, No Good, Dirty, Rotten, Candy Stealer! The second time you loot the chest the Tirasreli Chocolate will be used and you will unlock the pet vendor Nigel Rifthold who will appear outside.",
            date = "2018-09-30T05:24:01-05:00",
            sourceUrl = "https://www.wowhead.com/quest=53120#comments:id=2620087",
        },
        {
            id = 2607351,
            score = 9,
            author = "1370823",
            text = "this is not actually a \"quest\" it is a turn in much like the cooking materials from timeless isle. you can do this any number of times as long as you keep looting the item. i am assuming it was rep gated in order to hand it in, which is why people were experiencing issues.\n\nneedless to say, not actually a quest.  at one point it was a quest , but blizzard has since turned it into a multiple turn in instead of just a one time quest. not even part of the achievement Tell me a Tale  (https://www.wowhead.com/achievement=13127/tell-me-a-tale)",
            date = "2018-08-30T18:05:37-05:00",
            sourceUrl = "https://www.wowhead.com/quest=53120#comments:id=2607351",
        },
        {
            id = 2599711,
            score = 7,
            author = "Freesya",
            text = "As of now, 20-08 if you approach her and try to turn in the item called Exotic Spices (drop from Island expedition), although she has a blue question mark, the server responds that \"You do not meet the requirements for that quest\".\n\nAnyone found a solution?",
            date = "2018-08-20T10:25:30-05:00",
            sourceUrl = "https://www.wowhead.com/quest=53120#comments:id=2599711",
        },
        {
