        {
            id = 2865172,
            score = 9,
            author = "kelloggs9",
            text = "For those who are here for the Horde quest: the turn in is the NPC Isabella within Grommash Hold, Orgrimmar.\n\nIf you haven't finished the \"Fate Of Saurfang\" questline she will not be visible to you.\n\nCredit to @Exildur and his original post here (https://www.wowhead.com/quest=53127/the-lord-admirals-lament#comments), on the Horde version of the quest.",
            date = "2019-01-09T19:35:38-06:00",
