    [53129] = {
        {
            id = 2870465,
            score = 13,
            author = "Mathaylla",
            text = "I kept trying to figure out why I couldn't find Isabella in Orgrimmar, even though according to the map, she was supposed to be inside Grommash Hold.\n\nRealized that the entire Grommash Hold is phased if you are on the \"Fate of Saurfang\" questline starting with https://www.wowhead.com/quest=54097. If, when you enter Grommash Hold, there's an abomination guard in the doorway that says \"Me guard door\" - you are on this questline, and you need to complete it before you can see Isabella for this quest turn-in.",
            date = "2019-02-09T14:28:42-06:00",
            sourceUrl = "https://www.wowhead.com/quest=53129#comments:id=2870465",
        },
