            score = 1,
            author = "Rawsons",
            text = "I found it a bit annoying that the map does not show where they are exactly.\n\nRui of the sharpened blade: /way 54.06, 83.65 at Westwind rest\nPai the lifedrainer: /way 59.97, 87.84 just outside the burning buiding\nTi-Qiang the bulwark: /way 56.92, 76.49 inside the ruins\nHuo the Lightning-Fist: /way 62.25, 80.16 at Eastwind rest",
            date = "2020-08-23T07:48:01-05:00",
