        {
            id = 3192911,
            score = 10,
            author = "Nekrotik",
            text = "Similar to Things Left Behind (https://www.wowhead.com/quest=58782/things-left-behind#comments:id=3190636), this can eat up more time than it's worth. It's not uncommon to fly around for half an hour without finding any chests, even with the help of HandyNotes or some such. Take this quest at the beginning of your daily chores and hope you're lucky enough to stumble on 3 chests in the process.",
            date = "2020-03-01T12:53:59-06:00",
