    [58485] = {
        {
            id = 3184596,
            score = 71,
            author = "iIIumnati",
            text = "Go to the Ruins of Guo-Lai located in the mid west of Vale of Eternal Blossoms.\n\nStay on your mount, this can be completed without ever landing or fighting.\nHover in the air just about 20 yards above ground.\n\nFrom a birds eye view look down and notice the 1 yard by 1 yard square pedestals\nthat are arranged in various areas on the ground, especially near the wall structures.\n\nSimply hang out above those pedestals and wait for the statues to materialize\non those pedestals. Swoop down and knock over the statue. When you click\nto interact, it takes a few seconds to get credit. It is not instant.\n\nDo not be upset if someone else steals your statue.\nCongratulate them for being a better ninja than you are.",
            date = "2020-01-21T21:50:59-06:00",
            sourceUrl = "https://www.wowhead.com/quest=58485#comments:id=3184596",
        },
        {
            id = 3184569,
            score = 13,
            author = "iiSkelecat",
            text = "The big statue surrounded by runes in the center of Ruins of Guo-Lai does NOT relate to this quest! The statues for this quest spawn on the pedestals, and can be interacted with by clicking.",
            date = "2020-01-21T19:35:16-06:00",
            sourceUrl = "https://www.wowhead.com/quest=58485#comments:id=3184569",
        },
        {
            id = 3185016,
            score = 11,
            author = "BeerWolf",
            text = "They're not personal nor shared outside groups, so good luck doing this quest when it's crowded... so few of them in a tiny area with a long respawn time.\n\nAnother point for Blizzard...!\n\n@#$%s.",
            date = "2020-01-23T01:24:05-06:00",
            sourceUrl = "https://www.wowhead.com/quest=58485#comments:id=3185016",
        },
        {
            id = 3200106,
