            author = "Serenadas",
            text = "Yes, this quest is another headache when everyone has the same wa and the little spot outdoor is crowded.\n\nBUT! If you go inside of the palace (entrance /way 22.47, 25.20)\nyou see the first big room with a pillars and platform in the middle\n\nNow look to the LEFT and RIGHT - you will see 3 statues on square platforms each side - so it's exactly 6 that needed to complete this quest.\nRespawn is really quick, so if there are no statues, just wait about 1 min.",
            date = "2020-04-16T04:12:33-05:00",
