    [58908] = {
        {
            id = 3243467,
            score = 15,
            author = "ClasscMalcontent",
            text = "Update: Blizzard added a sidecar-drive to the quest to keep players nearby. If, for any reason that bugs out, you will need to abandon and retake the quest as before.\n\nPrior to the sidecar; and even still should it bug out:\nThe Alliance version has similar problems as the Horde version comments here (https://www.wowhead.com/quest=60344/finding-your-way#comments). Basically do not run ahead of the quest NPC \"Lindie\" or it will not complete. Even logging off and back on or heading directly to the stables yourself will not advance the quest. Abandoning the quest and restarting it is the only way to complete it if you did not remain close to Lindie.",
            date = "2020-10-29T11:51:19-05:00",
            sourceUrl = "https://www.wowhead.com/quest=58908#comments:id=3243467",
        },
        {
            id = 5675409,
            score = 2,
            author = "Ahjen",
            text = "Idiotic quest. Don't:\n\nTry to do anything else before letting Lindie take you here.\nRun off, you'll be teleported back into his side-cart or eventually Lindie will despawn.\nRun ahead to the stables on your much faster mount. Lizzie will not be there already like most quests in the game.\nLog off so you can send your character some gold from your main.\n\nIf you do any of these things, expect to have to abandon the quest and go back to Lindie on the bridge.\n\nIt would have been much better if Lindie just accompanied you and had some triggered dialog to direct players along the path. This is just more lazy quest design, with an attempt to \"fix\" the issue by teleporting the play back into the cart. For anyone playing an alt, it is just a waste of time.",
            date = "2023-09-02T11:33:56-05:00",
            sourceUrl = "https://www.wowhead.com/quest=58908#comments:id=5675409",
        },
