    [59583] = {
        {
            id = 6244128,
            score = 131,
            author = "TheBigDeeb",
            text = "I submitted a bug report about this issue, but there was no response from Blizzard. I tried  [zone=10424] with five different characters until I finally figured out how to fix this bug.\n\nCreate a [race=7] Level 1 [class=5]\nChoose [zone=10424]. Don’t forget to use your heirloom gear so you can one-shot everything with https://www.wowhead.com/spell=589 while in [zone=10424].\nDo not pick any talent specialization such as Shadow or Holy.\n\nAfter you queue inside the dungeon and finish it, you will get teleported to the Dragon Isles. ONLY deliver the quest https://www.wowhead.com/quest=55991 to https://www.wowhead.com/npc=238913, then do not take the new quest that gives you a flying mount.\n\nGo to the dock and wait for the Stormwind ship to take you there.\nNow fly to the Stormwind gate, where you will see https://www.wowhead.com/npc=154169. Pick up the quest “https://www.wowhead.com/quest=59583.”\nDo NOT click “Skip.” Deliver the quest to https://www.wowhead.com/npc=163095, and you will get the https://www.wowhead.com/item=248336.\n\nEnjoy! ^^\n\nNote:\nThe reason I told you to create a [race=7] is so you can buy https://www.wowhead.com/item=256330 from https://www.wowhead.com/npc=1247  :D",
            date = "2025-12-11T04:32:18-06:00",
            sourceUrl = "https://www.wowhead.com/quest=59583#comments:id=6244128",
        },
        {
            id = 6238796,
