    [63488] = {
        {
            id = 6274278,
            score = 23,
            author = "neareida",
            text = "If you are doing this after Midnight prepatch, the quest objectives and map display are currently broken, and don't show you were to go. The Thalassian Warstrider is located here  (https://www.wowhead.com/npc=176991/thalassian-warstrider)",
            date = "2026-01-30T18:36:06-06:00",
            sourceUrl = "https://www.wowhead.com/quest=63488#comments:id=6274278",
        },
        {
            id = 5381720,
            score = 22,
            author = "Raevenne",
            text = "Such a well designed quest, as usual for Blizzard. At the end of the Dead Scar, just before the quest turn in, I had a bunch of mobs around and the mount ability was on CD. I figured I'd get back into the opening of Deatholme  so as not to pick up any more mobs that might respawn while I killed the ones I already had on me. But no, as soon as I got into the Deatholme entrance (and not even close to the quest turn in point) the mount went away, and I was instantly killed by all the mobs. So yeah, super well designed quest there Blizzard. Thanks for that.",
            date = "2022-06-05T09:09:29-05:00",
            sourceUrl = "https://www.wowhead.com/quest=63488#comments:id=5381720",
        },
