    [64872] = {
        {
            id = 5427296,
            score = 141,
            author = "Ohnoudidnt",
            text = "It took me a minute to figure out, but you have to hold down the Fire Breath talent and release it when the bars are full at different stages to get each level of Empowered Fire Breath. (Edited to add after patch 9.2.7: Now you just have to click once and reclick when it's at the desired level you want it to go off at. Looks like they changed it since it first came out)",
            date = "2022-09-01T16:37:16-05:00",
            sourceUrl = "https://www.wowhead.com/quest=64872#comments:id=5427296",
        },
        {
            id = 5470830,
            score = 42,
            author = "booster363",
            text = "If the button doesn't work on your action bar when you press it, make a macro.\n\n#showtooltip\n/cast Fire Breath(Red)",
            date = "2022-11-16T02:06:29-06:00",
            sourceUrl = "https://www.wowhead.com/quest=64872#comments:id=5470830",
        },
        {
            id = 5477532,
            score = 26,
            author = "Emmistraza",
            text = "I had to click the cast button twice. The first time, just click (you don't have to hold the button down). This \"greys out\" the cast button and starts the 30 sec respawn countdown timer on the button, and it also brings up the cast bar display. Colors on the cast bar, from the left, are no color, red, orange, yellow. Watch the cast bar, and click the button again when you want to release it. Clicking in the red range casts Empowered I Fire Breath, clicking in the orange casts Empowered II Fire Breath, and clicking in the yellow casts Empowered III Fire Breath. Even though the cast button is greyed out and counting down from 30 to one, you can still click it the second time to make the spell work.",
            date = "2022-11-25T13:42:16-06:00",
            sourceUrl = "https://www.wowhead.com/quest=64872#comments:id=5477532",
        },
        {
            id = 5502785,
            score = 15,
            author = "camy011",
            text = "You have to cast the spell then hit the spell again at different intervals within the full cast in order to hit the different empowered 1/2/3 breakpoints.",
            date = "2022-12-15T12:10:25-06:00",
            sourceUrl = "https://www.wowhead.com/quest=64872#comments:id=5502785",
        },
