    [65613] = {
        {
            id = 5518781,
            score = 7,
            author = "Cowoth",
            text = "Nothing happened after picking up the quest and learning about the visage form.  Finally found out that there is a button that appears above the action bars.  Addons might block or conceal the button.  Also a bit misleading because it's not a choice; there is only 1 visage form to change into.",
            date = "2023-01-03T02:01:32-06:00",
            sourceUrl = "https://www.wowhead.com/quest=65613#comments:id=5518781",
        },
        {
            id = 5520094,
            score = 4,
            author = "vindurza",
            text = "This quest is so insulting as a horde player \"When I was a young dragon, I took on the mortal visage you now see. It allowed me to live among the tauren of Highmountain as an ally. \" he mentions he was allowed to pick a race that let him blend in with his people meanwhile horde are stuck choosing elves that look like they belong in the alliance one is even a human model as it's base and can not use all the horde armor.\n\nThey need to open the visages to all the races the code already exists to put the unique eyes and scale patterns on the other races this was show by dataminers in the alpha and they do not look out of place even on races like the vulpera and tauren(which might be the most requested horde visages and the most teased by blizzard seeing how many dragons are taking the forms of these races), all they would have to do is slightly modify horns and this would be golden.",
            date = "2023-01-04T17:37:09-06:00",
            sourceUrl = "https://www.wowhead.com/quest=65613#comments:id=5520094",
        },
    },
