    [65653] = {
        {
            id = 5379648,
            score = 24,
            author = "Maxmass",
            text = "If you are there and wondering why you can't see https://www.wowhead.com/npc=176796 like me, the reason is that you need to pick up the quest https://www.wowhead.com/quest=65653 from https://www.wowhead.com/npc=176796 in Oribos, you can find her near Orgrimmar portal then head to Silvermoon.",
            date = "2022-06-01T02:19:15-05:00",
            sourceUrl = "https://www.wowhead.com/quest=65653#comments:id=5379648",
        },
        {
            id = 5379925,
            score = 18,
            author = "Bursi",
            text = "Questline starts in Oribos at Lady Liadrin (/npc=176789#map) near the teleport to Orgrimmar.\n\nhttps://www.wowhead.com/quest=63479 - meet her in Silvermoon /way 88.75 37.58 entrance to Lady Liadrin\nhttps://www.wowhead.com/quest=63480 - watch dialogue\nhttps://www.wowhead.com/quest=63481 - click the portal next to you\nhttps://www.wowhead.com/quest=63482 - kill 15 enemies\nhttps://www.wowhead.com/quest=63483 - click https://www.wowhead.com/npc=176843 and defeat https://www.wowhead.com/npc=176856. Go west to 45.41 35.15 and repeat it. To north at 44.99 30.84 and again.\nhttps://www.wowhead.com/quest=63484 - leave the building, take the stairs on your right. Collect the weapon\n https://www.wowhead.com/quest=63485 - go to Bastion, you can take the teleport to Orgrimmar behind the quest giver\nhttps://www.wowhead.com/quest=63486 - go to Maldraxxus\n\nBastion:\nhttps://www.wowhead.com/quest=63522 - click dialogue to start the race. Start running and click the yellow bells on your way\nTravel to Maldraxxus, entrance at 45.88 45.07\nhttps://www.wowhead.com/quest=63519  - click dialogue to start the fight, defeat https://www.wowhead.com/npc=176917. Talk to https://www.wowhead.com/npc=176918 after that\nhttps://www.wowhead.com/quest=63487 - return to Tristessa (Oribos > Orgrimmar > Silvermoon)\nhttps://www.wowhead.com/quest=63488 - go to the marked area and mount the https://www.wowhead.com/npc=176991. Click your extra button https://www.wowhead.com/spell=367787 for aoe. You can also use your normal abilities. Fill the bar\nhttps://www.wowhead.com/quest=63489 - kill https://www.wowhead.com/npc=176864. Move him to the other crystal if the areas are growing too much. Click the extra button on his corpse and kill https://www.wowhead.com/npc=176865\nThis quest rewarded https://www.wowhead.com/item=191604, I guess this depends on your class\nhttps://www.wowhead.com/quest=63490 - return to Silvermoon and get you https://www.wowhead.com/item=191565 and https://www.wowhead.com/item=191566\n\nQuestline took about 40 minutes (incl. flight paths) with itemlevel 230.",
            date = "2022-06-01T10:42:17-05:00",
            sourceUrl = "https://www.wowhead.com/quest=65653#comments:id=5379925",
        },
