        {
            id = 5449642,
            score = 1,
            author = "kitkat2",
            text = "Did I miss something here?  As an alliance player I'm asked to go help the horde.  They are hostile against me to the point that I have to help them in a disguise so they don't know I'm an alliance player?  What is the end goal?  So the horde can recover, regroup and become stronger to burn down another of our trees or something equally important?  I don't see any other alliance complaints, so I'm pretty sure I missed something - what?",
            date = "2022-10-11T07:33:21-05:00",
            sourceUrl = "https://www.wowhead.com/quest=65657#comments:id=5449642",
        },
        {
            id = 6112583,
            score = 1,
            author = "Silden",
            text = "All three required NPCs are outside of the building.\nhttps://www.wowhead.com/npc=185793 and https://www.wowhead.com/npc=185794 need you to chat and say \"Time to meet with the other Forsaken\" to complete their steps\nhttps://www.wowhead.com/npc=185514 needs you to accept the quest https://www.wowhead.com/quest=65658 to complete the step. You'll need to complete the quest as well to progress the quest chain.",
            date = "2025-05-15T12:22:04-05:00",
            sourceUrl = "https://www.wowhead.com/quest=65657#comments:id=6112583",
        },
    },
