    [65660] = {
        {
            id = 5419844,
            score = 38,
            author = "Etreum",
            text = "I tried it twice and was not getting the action button needed to collect the sample and complete the quest.\n\nAt that point, I did a \"/reload gui\" and the action button came up allowing me to complete the quest.",
            date = "2022-08-18T13:56:04-05:00",
            sourceUrl = "https://www.wowhead.com/quest=65660#comments:id=5419844",
        },
        {
            id = 5379530,
            score = 10,
            author = "Bowserkills7",
            text = "There is an extra action button to interact with when Calia stops after facing a big named mob.\nDon't be like me and run through the blight to reset the quest thinking its bugged.",
            date = "2022-05-31T23:13:08-05:00",
            sourceUrl = "https://www.wowhead.com/quest=65660#comments:id=5379530",
        },
        {
            id = 5380765,
            score = 3,
            author = "Saxbeck",
            text = "Lilian does NOT stop walking before reaching the mob she need so casters have no time to stop and cast spells.   A tank pet is nice as you just need one shoot and the pet takes over.\n\nWhen quest is turned in I hearthed to Orgrimmar after picking up quest : Consulting our Allies  which sends you to Maldraxxus ...",
            date = "2022-06-03T09:08:42-05:00",
            sourceUrl = "https://www.wowhead.com/quest=65660#comments:id=5380765",
        },
        {
            id = 5892840,
            score = 3,
            author = "blizzard60",
            text = "BTW, if there are mobs beating on you while you're in the bubble at the prescribed location to collect the sample, the button will NOT show up while you're in combat mode. The mobs need to be killed BEFORE you're able to collect the sample. I kept doing /reload and it wouldn't work until all the mobs attacking me were dead.",
            date = "2024-07-05T17:33:52-05:00",
            sourceUrl = "https://www.wowhead.com/quest=65660#comments:id=5892840",
        },
