    [65661] = {
        {
            id = 5380027,
            score = 42,
            author = "bugzy2341",
            text = "at 74, 34 on the ground is a green teleport. take it and it takes you to Margrave. On the Map it's at the House of Rituals to the Northeast of the map.",
            date = "2022-06-01T13:24:35-05:00",
            sourceUrl = "https://www.wowhead.com/quest=65661#comments:id=5380027",
        },
        {
            id = 5386955,
            score = 19,
            author = "Turowai",
            text = "Sadly have to find your own way to the shadowlands (hearthstone there, or use the portal in capitol cities), no nice easy convenient story-portal taking you there this time (but there is a nice quick way back to Lordaeron once you're finished, in a few more quests... which is nice :) )",
            date = "2022-06-21T16:57:11-05:00",
            sourceUrl = "https://www.wowhead.com/quest=65661#comments:id=5386955",
        },
        {
            id = 5401641,
            score = 13,
            author = "Wyr3d",
            text = "So, head's up for those of you who bumped into the strumpet light-born undead after completing Revendreth Storyline, and just chosen your Covenant:\n\nSince you probably can't fly (unless you are on an alt) you will have to make your way through this unexplored zone on foot, encountering countless hostiles, most of which are  likely on equal footing with you, while others are elites whom you should probably avoid.\n\nOnce you've made your way to the designated area, take the portal up to the floating building, where the turn-in NPC resides. Most of the mobs in this area have been hostility-tweaked so they just don't like your face, as appose to wanting to tear it from you, but take note of the still hostile elite mob in the left hand corner of the building, Fal'zinge (https://www.wowhead.com/npc=177729/falzinge). This guy has a !\" embedded into his portrait becuase he is the target of a quest - but that has nothing to do with this chain, so you can just ignore him.",
            date = "2022-07-20T03:23:24-05:00",
            sourceUrl = "https://www.wowhead.com/quest=65661#comments:id=5401641",
        },
