    [65667] = {
        {
            id = 5380751,
            score = 15,
            author = "Helpersson",
            text = "Spam-drop the plague eaters anywhere it's green with plague. Use the bat-icon button on the marked targets.\n\nThe reticule targeting on this quest is very poorly implemented and awkward to use. I imagine that it must be the work of the same intern that Blizz used on most of the similarly awkward and unsatisfying-to-play Marasmius 'Let's Ride!' daily quests.\n\nCredit where it's due, however: overall, I found this questline to be well-paced and highly enjoyable.",
            date = "2022-06-03T08:19:31-05:00",
            sourceUrl = "https://www.wowhead.com/quest=65667#comments:id=5380751",
        },
        {
            id = 5731260,
            score = 13,
            author = "Arcaya",
            text = "This is a great example of how some people just shouldn't be allowed to make quests, especially vehicle quests. It's unnecessarily long, presents no challenge whatsoever and has a weirdly constrained area where you get to target things, so you just have to sit there doing 20 laps, occasionally dropping a bomb, when the game lets you. Great fun.",
            date = "2023-11-18T11:26:35-06:00",
            sourceUrl = "https://www.wowhead.com/quest=65667#comments:id=5731260",
        },
        {
            id = 5380064,
            score = 9,
            author = "CheesyDad",
            text = "When doing Drop Plague Eaters in Ruins of Lordaeron, just spam 1. I only targeted the ground that had arrow. You can target anyway so spam away.",
            date = "2022-06-01T14:24:47-05:00",
            sourceUrl = "https://www.wowhead.com/quest=65667#comments:id=5380064",
        },
        {
            id = 5460696,
            score = 8,
            author = "linda535",
            text = "This quest wins the award for Most Wasted Time and most Tedious of all WoW quests ever.",
            date = "2022-10-30T10:48:46-05:00",
            sourceUrl = "https://www.wowhead.com/quest=65667#comments:id=5460696",
        },
        {
            id = 5384530,
            score = 7,
            author = "Madr",
            text = "You cannot steer, you're just along for the ride. Once you have finished dropping the plague eaters (100%) using abilities 1 and 2 on the targets, then you have to target the monster Amalgam and use abilities 3 and 4 until he is dead.",
            date = "2022-06-14T10:29:55-05:00",
            sourceUrl = "https://www.wowhead.com/quest=65667#comments:id=5384530",
        },
    },
