    [65691] = {
        {
            id = 5456500,
            score = 239,
            author = "strickn",
            text = "Must start quest chain via https://www.wowhead.com/quest=65690 @ https://www.wowhead.com/npc=185627 to progress to this.\n\n/way The Waking Shores 39.45 48.33 Ingot (up on ledge)\n\nNeed to complete the following quests before this one unlocks:\n\n https://www.wowhead.com/quest=65690\nhttps://www.wowhead.com/quest=65687\nhttps://www.wowhead.com/quest=65782\n\nNotes\n\nUPDATE: As of 2022-11-02, this quest is finally working and can be successfully completed.\nAs-of 2022-10-23, this quest is still bugged and having phasing issues as noted on the other post\nRunning into cave full speed seems to cause https://www.wowhead.com/npc=185628 to disappear completely throughout the entire cave, and makes https://www.wowhead.com/npc=186118 just yell, \"Silence!\" before disappearing.\nWalking slowly into cave causes dialogue between https://www.wowhead.com/npc=185627 and https://www.wowhead.com/npc=185628, and you will get to see https://www.wowhead.com/npc=185628 all the way up until she's trapped, and then it bugs-out again.\nI tried going up the ramp on the right-hand side of cave, dropping down hole on-top of https://www.wowhead.com/npc=186118, and popping https://www.wowhead.com/spell=258920 to try and get aggro on https://www.wowhead.com/npc=186118 before he disappeared, but that did not work either.\nAttempted quest in a party w/ someone else, thinking that might affect things, but still bugged",
            date = "2022-10-23T07:21:50-05:00",
            sourceUrl = "https://www.wowhead.com/quest=65691#comments:id=5456500",
        },
        {
            id = 5496129,
            score = 91,
            author = "Mypciscraze",
            text = "Hi all\n\nI present You Storyline The Shadow of His Wings. This Storyline is part of https://www.wowhead.com/achievement=16401 which is criteria for https://www.wowhead.com/achievement=16585.\n\nSee My Video if need it - https://youtu.be/JAWWnv4XCzQ\n\nQuests in order I done:\n\n1a. https://www.wowhead.com/quest=65687 - Quest start from https://www.wowhead.com/npc=185627 39.47 48.33. Slay 12 https://www.wowhead.com/npc=185614.\n1b. https://www.wowhead.com/quest=65690 - Go to 37.45 46.67 stand next to cage.\n3. https://www.wowhead.com/quest=65782 - Slay mobs until https://www.wowhead.com/item=190612 will drop then open cage.\n4. https://www.wowhead.com/quest=65691 - Fly inside cave 35.80 47.92 and slay https://www.wowhead.com/npc=186118 35.12 45.48 then fly back to https://www.wowhead.com/npc=185627 39.47 48.33. after this quests storyline will finish.\n\nHope That help YOu :)",
            date = "2022-12-10T08:23:55-06:00",
            sourceUrl = "https://www.wowhead.com/quest=65691#comments:id=5496129",
        },
        {
            id = 5482190,
            score = 35,
            author = "qwerty31",
            text = "I'm not sure if it was the scaling as I approached max level (I did this quest at level 69), but the boss had a TON of HP. Enough that I assumed there was a 'trick' to the fight or he'd 'die' at half health or something. Nope, you gotta bring him all the way to 0.\n\nI ended up cheesing it a bit as a frost mage by starting the fight directly above him and raining down freezing doom. Got him to about half health by the time he'd slowly walked all the way up to me, and once he transforms at half health he's a lot easier.",
            date = "2022-11-30T15:47:21-06:00",
            sourceUrl = "https://www.wowhead.com/quest=65691#comments:id=5482190",
        },
        {
            id = 5517830,
            score = 15,
            author = "Darthias",
            text = "I am surpised that nobody has said about the fact that is a call back to Deathwing's narration during the Cataclysm Intro Cinematic:\n\n\"Pain...\n\nAgony...\n\nMy hatred burns through the cavernous deeps.\n\nThe world heaves with my torment.\n\nIts wretched kingdoms quake beneath my rage.\n\nBut at last, the whole of Azeroth will break, and all will burn beneath the shadow of my wing.\"",
            date = "2023-01-01T11:52:47-06:00",
            sourceUrl = "https://www.wowhead.com/quest=65691#comments:id=5517830",
        },
        {
            id = 5484191,
            score = 11,
            author = "YeahDaryl",
            text = "if you go into the cave too early (like flying in on your dragonriding mount) it can bug out and Ayasanth won't be there following you, meaning you can't confront Cygenoth. All you need to do is just run up to the entrance of the cave and Aysanth will respawn and then you can walk down and confront him.",
            date = "2022-12-01T21:42:35-06:00",
            sourceUrl = "https://www.wowhead.com/quest=65691#comments:id=5484191",
        },
    },
    [65701] = {
        {
