    [65709] = {
        {
            id = 5849774,
            score = 16,
            author = "Whitemere",
            text = "For those who may have missed the reply to another comment below - click the bag ONCE ONLY and then stop!  You will receive the bag after a few seconds. If you keep pressing the bag repeatedly - thinking that is what is meant by 'search through the bag' - it will take you an eternity.\n\nI only wish I'd realised this on the first dozen characters...",
            date = "2024-05-07T07:52:13-05:00",
            sourceUrl = "https://www.wowhead.com/quest=65709#comments:id=5849774",
        },
        {
            id = 5480169,
            score = 14,
            author = "rosierose",
            text = "If your quest is stuck at 0/1 Ley Scepter like mine, you can still use it on the ley lines at 39.57, 60.28 and 41.18, 62.25 and turn it in afterwards",
            date = "2022-11-29T01:20:27-06:00",
            sourceUrl = "https://www.wowhead.com/quest=65709#comments:id=5480169",
        },
        {
            id = 5480596,
            score = 12,
            author = "fhait",
            text = "For those without TomTom co-ordinates, if you follow the road west from the area on the map where you fetch the Ley Sceptre from the bag, you will see a purplish platform to the left of the road down in a depression. This is the Northern arcane field.\n\n/way 39.6, 60.3 as mentioned above.\n\nThe Eastern arcane field is a similarly purplish platform to the southeast of the Northern field.\n\n/way 41.2 62.2\n\nYou then return to the minimap area where you were/are required to fetch the Ley Sceptre from the bag to turn in.",
            date = "2022-11-29T12:15:05-06:00",
            sourceUrl = "https://www.wowhead.com/quest=65709#comments:id=5480596",
        },
        {
            id = 5485743,
            score = 10,
            author = "Lemai",
            text = "While searching into the bag you can a Thunderfury flying around xd",
            date = "2022-12-02T20:46:51-06:00",
            sourceUrl = "https://www.wowhead.com/quest=65709#comments:id=5485743",
        },
        {
            id = 5801721,
