            author = "Nogamara",
            text = "I've done this quest more than 10 times already and today I thought it was bugged because I spent a solid minute taking things out of the bag without success.\n\nI abandoned it, took it again, and continued clicking like 10 times until I got it. Maybe it's RNG, but that was definitely werird.",
            date = "2024-03-16T06:45:47-05:00",
            sourceUrl = "https://www.wowhead.com/quest=65709#comments:id=5801721",
        },
    },
