    [65784] = {
        {
            id = 5488218,
            score = 148,
            author = "pmakaro",
            text = "If https://www.wowhead.com/quest=66698 is the worst Dragonflight daily/WQ then I nominate this one for second place.  You regularly lose control of the otter using the \"Strengthen Grip\" command, which has a 7 sec CD, to regain control.  I've had times where I had uninterrupted control for 15 sec, and times where the otter would go nuts every 5 seconds.  During  these uncontrolled times the otter can backtrack or just run off a ledge.  If this wasn't frustrating enough just like https://www.wowhead.com/quest=66698 if you don't return the otter fast enough he will despawn and you get to start again.\n\nEdit: This is now probably the worst since Counting Argali now only requires one sheep and has marks for where to go.",
            date = "2022-12-04T17:51:54-06:00",
            sourceUrl = "https://www.wowhead.com/quest=65784#comments:id=5488218",
        },
        {
            id = 5508207,
            score = 114,
            author = "rozel",
            text = "Take them back to the center of the camp of the quest giver.",
            date = "2022-12-20T03:16:03-06:00",
            sourceUrl = "https://www.wowhead.com/quest=65784#comments:id=5508207",
        },
        {
            id = 5510665,
            score = 57,
            author = "Docjekyl73",
            text = "After many frustrating attempts, I finally figure out how to do this quest, It is fairly simple now and takes longer just to find the mounds. As soon as you get on otter, just push W always and hold right-mouse click to steer, only pressing the button when he goes crazy. It is very simple tbf, whole quest took about 2 minutes total for 3.\n\nHope this helps.",
            date = "2022-12-22T03:46:18-06:00",
            sourceUrl = "https://www.wowhead.com/quest=65784#comments:id=5510665",
        },
        {
            id = 5517267,
