    [65848] = {
        {
            id = 5482033,
            score = 14,
            author = "Currently",
            text = "For the people who dream about earning the https://www.wowhead.com/achievement=15310 achievement.",
            date = "2022-11-30T13:43:41-06:00",
            sourceUrl = "https://www.wowhead.com/quest=65848#comments:id=5482033",
        },
        {
            id = 5488315,
            score = 5,
            author = "CrimsonQuill157",
            text = "I am not mounted and the book will spawn, but almost immediately phases out. I've dropped the quest and retaken it and it happens again. Not sure what is going on.\n\nedit: If this happens to you, reload and try again. It finally worked.",
            date = "2022-12-04T19:58:12-06:00",
            sourceUrl = "https://www.wowhead.com/quest=65848#comments:id=5488315",
        },
        {
            id = 5644186,
            score = 5,
            author = "TheiaDarkHeart",
            text = "So, I kept getting disconnected trying to complete this quest. The solution is to not use your mouse to move around. Use the keyboard only. I got disconnected half a dozen times before trying the keyboard method to move around on the tome. That finally did the trick.",
            date = "2023-07-10T20:27:03-05:00",
            sourceUrl = "https://www.wowhead.com/quest=65848#comments:id=5644186",
        },
        {
            id = 5488395,
            score = 3,
            author = "jzkalika",
            text = "I got into a state where the last step to use the \"arcane spirit beam\" just didn't do anything. If that happens to you, simply:\n1. dismount the book (which will take you back to the beginning)\n2. re-mount it - and Kalecgos will talk about having to take out the shamans again but you don't have to\n3. spam 1 to travel forward - make sure you move as forward as possible before the spell changes, because it's possible to be close enough to trigger the next step in the quest (use arcane spirit beam to take down the giant), but you're actually out of range for the spell...\n4. click on the ancient and use ability '1'\n\nIf you failed #3, just dismount and repeat from step 1.",
            date = "2022-12-04T21:56:00-06:00",
            sourceUrl = "https://www.wowhead.com/quest=65848#comments:id=5488395",
        },
        {
            id = 5990500,
            score = 3,
            author = "Goodrune",
            text = "I follow the quest, jump on the book for a wild ride, kill the 3 shaman's, use the beam on the Giant, but its not enough, but it dies  and we rush to the cave.  One says rest now and they all fade, NO Quest turn in.\n\nAfter doing this quest about 10 times and not getting the turn in, I finally abandoned it and retook it.  after riding the book and killing the shamans, mostly by riding over them I was super near to the Giant and saw an outline.  Used the beam to kill it, and rode to the cave.  FINALLY KALECGOS ALLOWED ME TO TURN IT IN. PHEW",
            date = "2024-10-25T08:08:35-05:00",
            sourceUrl = "https://www.wowhead.com/quest=65848#comments:id=5990500",
        },
    },
    [65849] = {
        {
            id = 5485333,
            score = 52,
            author = "carcharoth84",
            text = "For everyone wondering where to get the quest (because you're receiving tuskarr renown but the faction is not unlocked in the menu): Just play the main campaign questline. It will appear there.\nI had my renown on level 3 when it finally unlocked.",
            date = "2022-12-02T15:00:21-06:00",
            sourceUrl = "https://www.wowhead.com/quest=65849#comments:id=5485333",
        },
        {
            id = 5481344,
            score = 12,
            author = "acciojackie",
            text = "On an alt, I was trying to find where Norukk was in Iskaara for the quest, Orientation: Iskaara (https://www.wowhead.com/quest=72435/orientation-iskaara) but he was not located in the Tuskarr village. If you do the Azure Span main story questline to \"unlock\" Iskaara, he'll end up there after the quest, To Iskaara (https://www.wowhead.com/quest=65849/to-iskaara).",
            date = "2022-11-30T00:17:57-06:00",
            sourceUrl = "https://www.wowhead.com/quest=65849#comments:id=5481344",
        },
        {
            id = 5508112,
            score = 12,
            author = "Janaq",
            text = "To get access to this quest, to open up the Tuskarr reputation, you must first complete the previous questline, Tuskar Troubles (https://www.wowhead.com/storyline/tuskarr-troubles-1317), which begins with Ask The Locals (https://www.wowhead.com/quest=66699/ask-the-locals), Catch the Caravan (https://www.wowhead.com/quest=65864/catch-the-caravan) etc.\n\nIf you follow the normal main Dragonflight questlines, you will be doing these quests. Along the way you will see your earning Tuskarr rep - even though the faction isn't \"opened\" yet. Don't stress, once you finally do open it, the rep is there and you'll be almost to level 3 or around there.",
            date = "2022-12-20T00:57:16-06:00",
            sourceUrl = "https://www.wowhead.com/quest=65849#comments:id=5508112",
        },
        {
            id = 5480620,
            score = 3,
            author = "R1p0ne0ut",
            text = "I'm guessing there is some type of pre-requisite to actually even find Brena. I've been up and down the road and in Iskaara and Brena is nowhere to be found. I am only lvl 63 and only came looking for this to hopefully open up some fishing quests. Unfortunately, there is no information online about this issue.",
            date = "2022-11-29T12:29:24-06:00",
            sourceUrl = "https://www.wowhead.com/quest=65849#comments:id=5480620",
        },
        {
            id = 5588561,
            score = 3,
            author = "BAnsMax",
            text = "If you're levelling an alt and you're looking to unlock the Iskaara Tuskarr (https://www.wowhead.com/faction=2511/iskaara-tuskarr) faction under the Dragon Isles Summary.\n\nAll you need to do is head to Iskaara in The Azure Span and click on the Flight Master. This will unlock them.\n\nNote: You must have completed all the zones story lines on your first character. You will know this is done by seeing World Quests on the map as well as the hook representing the the Iskaara Tuskarr.",
            date = "2023-04-13T01:26:09-05:00",
            sourceUrl = "https://www.wowhead.com/quest=65849#comments:id=5588561",
        },
    },
    [65850] = {
        {
            id = 5497528,
            score = 53,
            author = "Dimitrios82",
            text = "I was doing this quest on 10th of December 2022, sometime after midnight. After 18 years of WoW there is nothing new under the sun for me. So i was gathering some stuff, talking to some NPCs without paying much attention to the details....until i realized i was preparing a funeral.\n\nAs i watch the corpse being transported towards the sea, i am instantly reminded of my father who lies in hospital at that time. I start crying, push the cart into the sea and feel the spirit of my father leaving this world. One hour later, my father passed away.\n\nI can barely type, but wherever you are now papa, know that you will always be loved. Now and forever. If there is one thing i regret, it is not being there to hold your hand when you were about to leave the world of the living.\n\nRest in peace. You have earned it.",
            date = "2022-12-11T14:20:19-06:00",
            sourceUrl = "https://www.wowhead.com/quest=65850#comments:id=5497528",
        },
        {
            id = 5480865,
            score = 31,
            author = "Infiniti",
            text = "awwww",
            date = "2022-11-29T16:27:04-06:00",
            sourceUrl = "https://www.wowhead.com/quest=65850#comments:id=5480865",
        },
        {
            id = 5496205,
            score = 22,
            author = "Vaeevictiss",
            text = "someone cutting onions during this quest.\n\nthat was probably one of the most moving quests in the game for someone you never even met.",
            date = "2022-12-10T09:54:22-06:00",
            sourceUrl = "https://www.wowhead.com/quest=65850#comments:id=5496205",
        },
        {
            id = 5516336,
            score = 10,
            author = "alpanhell",
            text = "Kind of funny, for immortal dragons all deaths ARE violent...",
            date = "2022-12-29T13:48:47-06:00",
            sourceUrl = "https://www.wowhead.com/quest=65850#comments:id=5516336",
        },
        {
            id = 5484465,
