    [65916] = {
        {
            id = 5486520,
            score = 109,
            author = "Kaideleigh",
            text = "Entrance to the cave is to the NE at 51.6, 57.6 near ground level.  Is to the right of columns.",
            date = "2022-12-03T12:45:17-06:00",
            sourceUrl = "https://www.wowhead.com/quest=65916#comments:id=5486520",
        },
        {
            id = 5494221,
            score = 14,
            author = "1833958",
            text = "Apparently the mobs you have to kill first will respawn and kill you before you can finish him off. Made it unnecessarily hard to do alone despite not being recommended to be done in a group.",
            date = "2022-12-09T00:22:55-06:00",
            sourceUrl = "https://www.wowhead.com/quest=65916#comments:id=5494221",
        },
        {
            id = 5488307,
            score = 9,
            author = "Kamraten",
            text = "You need to wait until his two servent mobs will spawn besides him. Kill them and he becomes attackable.",
            date = "2022-12-04T19:42:30-06:00",
            sourceUrl = "https://www.wowhead.com/quest=65916#comments:id=5488307",
        },
        {
            id = 5505378,
            score = 9,
            author = "pcgneurotic",
            text = "You can pull his two friends - the rock and the water elementals - individually. As soon as the second one dies, Ko'jo comes wading in. Fight him to the side, because otherwise the elementals do respawn quite quickly and can snatch your impending victory away from you. :D None of the three are too difficult individually, but Ko'jo does spam a lot of AoE attacks right in front of himself.",
            date = "2022-12-17T07:17:24-06:00",
            sourceUrl = "https://www.wowhead.com/quest=65916#comments:id=5505378",
        },
        {
            id = 5528356,
            score = 7,
            author = "Doloria",
            text = "Two quests are located in a cave next to the tall temple to the left of the waterfall which contains the North Ward: https://www.wowhead.com/quest=65921 and https://www.wowhead.com/quest=65916. There are 2 cave entrances:\n\nmain entrance (51.9, 58.6). At ground level, face the temple columns and walk to your right. You'll quickly find the entrance.\nside entrance (52.9, 58.5). From the main cave entrance fly low toward the high waterfall.  There is a cave entrance at ground level to your left.  There are fewer mobs at the side entrance.\nInside the cave, look for a ramp that spirals upward on the right wall of the cave. It leads to https://www.wowhead.com/npc=186367 and the https://www.wowhead.com/item=193043. Beware -- the two adds respawn really fast.",
            date = "2023-01-16T03:21:00-06:00",
            sourceUrl = "https://www.wowhead.com/quest=65916#comments:id=5528356",
        },
    },
    [65918] = {
        {
            id = 5504188,
            score = 0,
            author = "Mypciscraze",
            text = "Hi all\n\nI present You Storyline Tyrhold Reservoir. This Storyline is part of https://www.wowhead.com/achievement=16398 which is criteria for https://www.wowhead.com/achievement=16585.\n\nSee My Video if need it - https://youtu.be/M3VTPp7dsNk\n\nQuests in order I done:\n\n1. https://www.wowhead.com/quest=72190 - Start from https://www.wowhead.com/npc=198349 /way #2112 25.32 39.26, Go to /way 49.25 58.87, to see https://www.wowhead.com/npc=190527.\n2. https://www.wowhead.com/quest=65913 - Go to see https://www.wowhead.com/npc=189045 is in bulding /way 48.03 59.40 enter, https://www.wowhead.com/npc=189045 is at the end of the room.\n3A. https://www.wowhead.com/quest=65918 - Kill 8 Unleashed Elementals\n3B. https://www.wowhead.com/quest=70139 - You need to press on 2 Ward Stones they are located at the end of the room enter is not on ground level you need to fly: /way 51.43 56.34 UP North /way 51.50 61.39 UP East\n5A. https://www.wowhead.com/quest=65921 - Go cave /way 51.70 57.55, Kill mobs until 100% + You need to rescue 4 https://www.wowhead.com/npc=193813 ( no all you can see you can save i save only this one with out circle on ground xD ) /way 52,99 57.63 /way 52.65 57.35 /way 52.16 56.99 /way 52.36 57.83\n5B. https://www.wowhead.com/quest=65916 - Go cave /way 51.70 57.55, Slay https://www.wowhead.com/npc=186367 53.23 57.39 first kill adds then him and at end take https://www.wowhead.com/item=193043.\n7. https://www.wowhead.com/quest=65920 - You need to reactivate 3 https://www.wowhead.com/object=377133 ( is same places where you was before:\n/way 48.03 59.40 West\n/way 51.43 56.34 UP North\n/way 51.50 61.39 UP East\nThen back to Quest giver and press on https://www.wowhead.com/object=378906. This Quest is finish Storyline.\n\nHope That Help You :).",
            date = "2022-12-16T07:55:55-06:00",
