        {
            id = 5485971,
            score = 35,
            author = "Rasmus",
            text = "I looked this up to complete the part for Loremaster named \"Tyrhold Reservoir\". This quest was not the starting point for me, I had not yet unlocked the ability to see or interact with Mara. That is the quest giver for most of the quest chain. The first quest that I found relevant to this chain was from the npc \"Zuttiki\" @ /way 49.53, 58.88. Quest is called \"Wotcher, Watcher?\"\nThe last quest in the chain was \"For the Ward\" given by Mara and turned into her as well. This quest ended up giving me credit for \"Tyrhold Reservoir\".",
            date = "2022-12-03T01:37:09-06:00",
            sourceUrl = "https://www.wowhead.com/quest=65920#comments:id=5485971",
