    [65956] = {
        {
            id = 5481554,
            score = 8,
            author = "Mypciscraze",
            text = "Hi all\n\nI present You Storyline [storyline=1301]. This Storyline is part of https://www.wowhead.com/achievement=16334 which is criteria for https://www.wowhead.com/achievement=16585.\n\nSee Video with Storyline if need it - https://youtu.be/fYGkvw-wBAA\n\nStoryline in order I done it:\n\n1. https://www.wowhead.com/quest=66079 - Fly 42.4 66.7 to see https://www.wowhead.com/npc=186274\n2. https://www.wowhead.com/quest=72241 - Speak with https://www.wowhead.com/npc=192795 Movie will start.\n3a. https://www.wowhead.com/quest=66078 - Test the skills of 8 Blacktalon Assassins. Just speak with noobs around and fight with them.\n3b. https://www.wowhead.com/quest=66048 - You need to:\n- Speak with https://www.wowhead.com/npc=187466 43.7 67.2 wait until conversation finish\n- Speak with https://www.wowhead.com/npc=186331 42.4 66 and after conversation press on https://www.wowhead.com/object=377106 in tent\n- Speak with https://www.wowhead.com/npc=186493 42.8 66.8\n- Speak with https://www.wowhead.com/npc=189507 42.3 69.3 then use Scouting Scope\n5a. https://www.wowhead.com/quest=65956 - Djaradin defenses disrupted until 100%\n5b. https://www.wowhead.com/quest=65957 - Kill 3 NPC: https://www.wowhead.com/npc=186511 35.5 68.5 on top of tower , https://www.wowhead.com/npc=181875 35 66.7 , https://www.wowhead.com/npc=186509 35.4 60.6 on top of tower.\n7. https://www.wowhead.com/quest=65939 - Speak with Wrathion then move on bridge until Movie will start. Then go inside Citadel and kill 12 mobs inside.\n8. https://www.wowhead.com/quest=66044 - When You enter Citadel You can pick up this quest. Now You need to Speak with https://www.wowhead.com/npc=186933 He will move you to 26.8 60.1 to destroy Siege He will do it 2 more times like that. After destroy last siege go kill https://www.wowhead.com/npc=186592 27.1 57.\n9. https://www.wowhead.com/quest=66049 - First speak with https://www.wowhead.com/npc=196265 the npress on https://www.wowhead.com/spell=369785 27.5 63.2\n10. https://www.wowhead.com/quest=66055 - Enter vaults beneath the Citadel 27.1 61.1 and collect 12 https://www.wowhead.com/item=191131.\n11. https://www.wowhead.com/quest=66056 - First go and press on https://www.wowhead.com/npc=194560 24.6 60.9 then collect from https://www.wowhead.com/npc=189875 mobs or pick up from https://www.wowhead.com/object=377012 6 https://www.wowhead.com/item=192548.\n12. https://www.wowhead.com/quest=66354 - First press on Forge and after few sec pick up from it https://www.wowhead.com/object=377026.\n13. https://www.wowhead.com/quest=66057 - Fly and speak with https://www.wowhead.com/npc=187495 27.3 62.6 movie will start. After jump on https://www.wowhead.com/npc=187495 ( in dragon mode ) when You land movie will start. Finishing this quest will finish storyline.\n\nHope That Help YOu :)",
            date = "2022-11-30T04:14:34-06:00",
            sourceUrl = "https://www.wowhead.com/quest=65956#comments:id=5481554",
        },
        {
            id = 5483538,
            score = 4,
            author = "Kinbear",
            text = "Go in from the bridge, and work your way through the complex, the cherry bomb will un-elite the 'leet mobs, making them easy to take down (including the three named mobs for 'No time for heroes').\n\nDont do what I did and dragon-fly into the towers for the 'named', My freshly moved UI (thanks to blizzard) dumped the dragon riding vigour-bar over the top of the 'cherry bomb' action-icon, and I got slaughtered before I knew what was going on.\n\nalso Watch out for Pierecer Gigra, he has a knock back that shots you off the tower, and probably to your death.\n\nHappy hunting. :D",
            date = "2022-12-01T13:08:13-06:00",
            sourceUrl = "https://www.wowhead.com/quest=65956#comments:id=5483538",
        },
    },
    [65957] = {
        {
            id = 5482273,
            score = 7,
            author = "MagickRed",
            text = "With Pierecer Gigra he casts a red circle on the ground that pushes you off the platform if you are not fast enough to move. The platform is kinda small so the red circle takes up most of the space. Put your back against one of the two pylons otherwise you fall to your death.",
            date = "2022-11-30T16:50:34-06:00",
            sourceUrl = "https://www.wowhead.com/quest=65957#comments:id=5482273",
        },
        {
            id = 5497848,
            score = 4,
            author = "Direlamb",
            text = "If you have any trouble finding Piercer Gigra (as I initially did), he's on top of tower (not inside it). There's a little spiral staircase on the outside going up (at 35, 69) that I walked right by at first.",
            date = "2022-12-11T21:47:33-06:00",
            sourceUrl = "https://www.wowhead.com/quest=65957#comments:id=5497848",
        },
        {
            id = 5483540,
            score = 3,
            author = "Kinbear",
            text = "Go in from the bridge, and work your way through the complex, the cherry bomb from 'TalonStrike' will un-elite the 'leet mobs, making them easy to take down including all three of our named mobs.\n\nDont do what I did and dragon-fly into the towers for the 'named', My freshly moved UI (thanks to blizzard) dumped the dragon riding vigour-bar over the top of the 'cherry bomb' action-icon, and I got slaughtered before I knew what was going on.\n\nalso Watch out for Pierecer Gigra, he has a knock back that shots you off the tower, and probably to your death.\n\nHappy hunting. :D",
            date = "2022-12-01T13:09:42-06:00",
            sourceUrl = "https://www.wowhead.com/quest=65957#comments:id=5483540",
        },
