    [65997] = {
        {
            id = 5497955,
            score = 6,
            author = "auryunderground",
            text = "The NPC dialogue associated with this quest:\n\nhttps://www.wowhead.com/npc=190155 says: Are you looking for the young cadet, Sendrax? She hasn't returned yet.\nCaretaker Azkra says: Cadet Sendrax is showing some real promise with her eager attitude.\nCaretaker Azkra says: She will be leading her own regiment if she continues this way.\n\nThe player heads down the path toward the Life-Binder Conservatory. As they approach the large statue in the center of the path, they can hear https://www.wowhead.com/npc=187406 calling to them.\n\nSendrax says: Over here! And stay low!\n\nThe textbox dialogue when players interact with Sendrax:\n\n! Thank the Aspects (https://wowpedia.fandom.com/wiki/Dragon_Aspects) you're here!\n\nI couldn't find the scouts... the Primalists (https://wowpedia.fandom.com/wiki/Primalists) are here... I don't know what to do.\n\nPlayers then ask, \"What is happening here?\", which prompts a cutscene featuring https://www.wowhead.com/npc=190484.\n\nKyrakka says: Our ambush was a success.\nKyrakka says: The convoy yielded enough eggs to begin.\nKyrakka says: Go now, infuse them with the elements.\nKyrakka says: Wash away the stain of Order.\nKyrakka says: Work quickly.\nKyrakka says: Outsiders have come ashore.\nKyrakka says: We cannot let them interfere!",
            date = "2022-12-12T01:31:28-06:00",
            sourceUrl = "https://www.wowhead.com/quest=65997#comments:id=5497955",
        },
        {
            id = 6255060,
            score = -1,
            author = "BobCompletes",
            text = "Hi, full quest video below for anyone needing it.\n\nhttps://youtu.be/Sfyt8S_sWHM",
            date = "2025-12-28T19:10:26-06:00",
            sourceUrl = "https://www.wowhead.com/quest=65997#comments:id=6255060",
        },
