    [66019] = {
        {
            id = 5414957,
            score = 192,
            author = "Steiner14512",
            text = "After picking up the Spiced Game Meat, go to one of the big stone ovens in the back and use the Extra Action Button to roast it. (ie. don't be like me and try interacting with the Campfire next to the meat for 5 minutes)",
            date = "2022-08-10T17:10:07-05:00",
            sourceUrl = "https://www.wowhead.com/quest=66019#comments:id=5414957",
        },
        {
            id = 5439844,
            score = 72,
            author = "Stariknight",
            text = "Apart from the meat in the first step. You do not need to click on anything. It’s all extra action bars. It wasn’t showing up for me at first. Going into edit mode and resetting fixed it for me.",
            date = "2022-09-23T23:43:24-05:00",
            sourceUrl = "https://www.wowhead.com/quest=66019#comments:id=5439844",
        },
        {
            id = 5482298,
            score = 58,
            author = "Aisenfaire",
            text = "*edit:  You can hit Ctrl+Z or Alt+Z to hide your UI and the quest item will sparkle.\n\n----\n\n1. Click meat in the collapsed cart behind quest NPC.  /way 59.4, 37.8\n     Then go back to the quest NPC and click the table in front of her.\n\n2. Click spice on the stone oven ledge to her right side.  /way 59.3, 37.3\n  Then go back to quest NPC and use the special action button.\n\n3. Click more spice at flat basket on a table also to her right, beside stone oven.  /way 59.4, 37.4\n   Then go back to quest NPC and use the special action button.\n\n4. Click biggest spice container between the struts of the collapsed cart on her left.   /way 59.0, 37.9\n   Then go back to quest NPC and use the special action button.\n\n5. Click meat on table at quest NPC.\n    Then go to the biggest stone oven in front of quest NPC.  /way 58.9, 37.3  Use special action button there.\n\n6. Click on the table to the right of the ovens you cooked at.  /way 59.2, 37.1",
            date = "2022-11-30T17:09:27-06:00",
            sourceUrl = "https://www.wowhead.com/quest=66019#comments:id=5482298",
        },
        {
            id = 5508068,
            score = 26,
            author = "ArcaneEther",
            text = "They should have given Dracthyr the ability to roast the meat with their Fire Breath.",
            date = "2022-12-19T23:38:02-06:00",
            sourceUrl = "https://www.wowhead.com/quest=66019#comments:id=5508068",
        },
        {
            id = 5506621,
            score = 21,
            author = "ahapka",
            text = "I lost 250 rep with Gordon Ramsay after burning that meat, but on the plus side he finally said I spiced something enough.",
            date = "2022-12-18T13:48:47-06:00",
            sourceUrl = "https://www.wowhead.com/quest=66019#comments:id=5506621",
        },
    },
