    [66038] = {
        {
            id = 5481536,
            score = 89,
            author = "qwerty31",
            text = "You might possibly think, like me, 'oh, a timed race. Gotta go fast; better mount up!' Don't do this. You'll go faster on foot than you will mounted up.",
            date = "2022-11-30T03:53:40-06:00",
            sourceUrl = "https://www.wowhead.com/quest=66038#comments:id=5481536",
        },
        {
            id = 5464878,
            score = 64,
            author = "Zaynah",
            text = "This quest is a race that happens in three stages, or locations. Each time you reach the portal at the end of a stage, you will get teleported to the next stage.\n\nIn order to find the portal, simply follow the trail of the winged boots.\n\nPicking up the boots will give you a speed up. Any white circles on the ground will slow you down. As long as you pick up some speed-ups and avoid the white circles, you shouldn't have any problems finishing the quest within the time limit.",
            date = "2022-11-04T22:30:19-05:00",
            sourceUrl = "https://www.wowhead.com/quest=66038#comments:id=5464878",
        },
        {
            id = 5484882,
            score = 43,
            author = "CallMeNoa",
            text = "I wish we got to explore these time periods more than just running through for a couple seconds.",
            date = "2022-12-02T09:39:53-06:00",
            sourceUrl = "https://www.wowhead.com/quest=66038#comments:id=5484882",
        },
        {
            id = 5497101,
            score = 27,
            author = "Demonface",
            text = "If you let the timer run out and the quest fails, Andantenormu will let you skip ahead regardless.\n\n\"We were close that time. I might be able to reach Ambassador Chronormu with my magic.\"",
            date = "2022-12-11T05:44:25-06:00",
            sourceUrl = "https://www.wowhead.com/quest=66038#comments:id=5497101",
        },
        {
            id = 5507569,
            score = 19,
