    [69923] = {
        {
            id = 5471108,
            score = 5,
            author = "Trojanhorse",
            text = "[item=192493 domain=www] is dropped from mobs in the area. Kill the mobs & loot (don't waste your time like I did clicking on everything on the ground!). Go to any of the region quest areas and you should get 10 motes within a 2-3 mins",
            date = "2022-11-16T11:05:13-06:00",
            sourceUrl = "https://www.wowhead.com/quest=69923#comments:id=5471108",
        },
        {
            id = 5471048,
            score = 3,
            author = "Bursi",
            text = "https://www.wowhead.com/quest=65435 popped up on login after patch 10.0.2 was life.\nThis is the horde version of the Dragonflight's prepatch event.\n\nhttps://www.wowhead.com/quest=65435 - travel to Orgrimmar\nhttps://www.wowhead.com/quest=65437 - talk to https://www.wowhead.com/npc=190239 (cinematic)\nhttps://www.wowhead.com/quest=65443 - find the marked 3 NPCs\nhttps://www.wowhead.com/quest=72256 - talk to https://www.wowhead.com/npc=198442\n- leave Orgrimmar and meet https://www.wowhead.com/npc=197279 outside\nhttps://www.wowhead.com/quest=65439 - talk to https://www.wowhead.com/npc=193450 (cinematic)\nhttps://www.wowhead.com/quest=66586 - Uldaman dungeon quest. You can queue up for the quest by looking at specific dungeons\nhttps://www.wowhead.com/quest=69944 - talk to https://www.wowhead.com/npc=195899 next to you (vendor)\nhttps://www.wowhead.com/quest=69923 - quest to collect items at the prepatch events.\nYou can find these events in Badlands, Northern Barrens, Tirisfal Glades and Un'goro Crater, marked on the world map\n\n Questline took about 5 minutes  (without dungeon).",
            date = "2022-11-16T09:11:26-06:00",
            sourceUrl = "https://www.wowhead.com/quest=69923#comments:id=5471048",
        },
    },
    [69925] = {
