    [72652] = {
        {
            id = 5615119,
            score = 31,
            author = "Talionus",
            text = "For those looking for the items (on the first busy day the quest was available) find them in the locations provided below:\n\nPlate on the table\nBag on the floor in front of the bed\nPlant in the left corner as one enters, across from the entranceway\nCrooked painting on the wall just inside the entrance way, on the left\nDust on the floor in the back right corner across from the entranceway, to the left of the bed, and next to the broom\n\nIt was quite crowded and people were being less than helpful with all the Pocket Fel Spredders.",
            date = "2023-05-23T18:19:39-05:00",
            sourceUrl = "https://www.wowhead.com/quest=72652#comments:id=5615119",
