    [72653] = {
        {
            id = 5618993,
            score = 11,
            author = "Jenstonedart",
            text = "Kai Wanderbrew:\n\"Ah! I have been expecting these. This batch of flowers matured well.\nLook at that blue... now that's a color of brew that pandaren from all ends of the land will be talking about.\"\n\nNi Gentlepaw:\n\"Speaking of fine notes, Kirygosa's flowers over yonder are a boon to my craft. When crushed with other ingredients, they increase the potency of the final potion.\nNot to mention how pretty they are!\"\n\nYol:\n\"These are prettier than I could have imagined! Look at the sheen of their velvety petals--as if they shimmer with magic. Kirygosa's blue magic beautifies our village.\nFor years, I had been looking for a garnish for my noodle dishes. I think I will keep a few in a vase at home, as well...\"\n\nOld Man Misteye:\n\"Kirygosa? Is that you?\nOh, you are her friend! She said she was going to visit me today... did you bring flowers?\n\nI can't see much anymore, so I try to indulge my remaining senses as best I can.  And Kirygosa has cultivated something  very special.\nWelcome to our humble home, friend.\"",
            date = "2023-05-29T14:04:55-05:00",
            sourceUrl = "https://www.wowhead.com/quest=72653#comments:id=5618993",
        },
        {
            id = 5625789,
            score = 8,
            author = "Kamraten",
            text = "One of the most feel good quests I've ever done in WoW.",
            date = "2023-06-09T23:58:24-05:00",
            sourceUrl = "https://www.wowhead.com/quest=72653#comments:id=5625789",
        },
        {
            id = 5650021,
            score = 8,
            author = "Dawnrider",
            text = "The dialogue between Kalec and Kiry here give me \"we're working on player housing\" vibes.",
            date = "2023-07-15T22:52:11-05:00",
            sourceUrl = "https://www.wowhead.com/quest=72653#comments:id=5650021",
        },
        {
            id = 5927668,
            score = 2,
            author = "Turowai",
            text = "Handing in the quest:\n[spoiler]\"Wonderful! By the way--if you like the flowers, I would love to give you a bunch from my next harvest.\"[/spoiler]\n\nAnyone else think she was going to hand you some new flower transmog like the old bunches you can hold in your offhand?",
            date = "2024-08-24T00:47:16-05:00",
            sourceUrl = "https://www.wowhead.com/quest=72653#comments:id=5927668",
        },
        {
            id = 5619058,
