    [75294] = {
        {
            id = 5667849,
            score = 1,
            author = "gnomeregannn",
            text = "If you're trying for gold, here are the things that helped me the  most for this race: get all of the vigor boosts, including the one under that dock toward the beginning. Spam surge other than that but for that 1 hairpin turn where you're wrapping to the right around the tree, hold onto a boost until you're coming out of the turn, then go back to spamming. You're going to need to get ALL of the boosts for this race (including that one at the ruins towards the end), but remember that you can skim the tops of some of the checkpoint rings if you're close to a hazard. Also try to utilize the skyward ascent trick when you're nearing the end going up those slopes. There's a few videos online that show how to do this trick, but basically you press skyward ascent and immediately face your camera back down to where you're going.\n\nAll of this may seem pretty basic to the average dragonriding champion but I'm still figuring out the best strats and tried to compile them all into this comment. Hope it's legible enough. Starting to get all the races mixed together in my head xD",
            date = "2023-08-16T22:34:45-05:00",
            sourceUrl = "https://www.wowhead.com/quest=75294#comments:id=5667849",
        },
    },
    [75310] = {
    },
    [75311] = {
        {
            id = 5672598,
            score = 1,
            author = "Oceandust",
            text = "If you're trying to get Gold on the Advanced course - I had success with surging through the first 3 rings, picking up the green Vigor orb on the left then surging right into the 4th ring. That gave me enough speed at the start of the race to hit Gold.",
            date = "2023-08-27T16:27:11-05:00",
            sourceUrl = "https://www.wowhead.com/quest=75311#comments:id=5672598",
        },
    },
