    [75386] = {
        {
            id = 5672632,
            score = 1,
            author = "Oceandust",
            text = "What helped me get Gold - Skyward Ascent at the very start, face downward and go through the 1st ring. Surge Forward through the 2nd and 3rd ring to pick up the Vigor orb. Skyward Ascent into the 4th ring and then you should have enough speed to keep up Vigor throughout the rest of the race.",
            date = "2023-08-27T18:38:02-05:00",
            sourceUrl = "https://www.wowhead.com/quest=75386#comments:id=5672632",
        },
    },
    [75387] = {
        {
            id = 5672636,
            score = 1,
            author = "Oceandust",
            text = "I found that spamming all of my vigor at the very start gets you the speed you want (roughly 7 Surge Forwards will clear the first 9 rings). After the 9th ring with the Vigor Orb just before the first stretch of water - this is where you'll stop spamming Vigor and allow you to recharge. I found that using one vigor after every ring through the trees area is sufficient to maintain your speed. When over the water you'll need to use 2 or 3 vigor to keep your speed. At the very last ring use Skyward Ascent to get up the mountain.",
            date = "2023-08-27T19:11:01-05:00",
            sourceUrl = "https://www.wowhead.com/quest=75387#comments:id=5672636",
        },
    },
