    [77194] = {
        {
            id = 5647907,
            score = 44,
            author = "Eddafred",
            text = "This is the new 10.1.5 version of the old obsolete quest of the same name, https://www.wowhead.com/quest=5525.\n\nThe reward, https://www.wowhead.com/item=208028 has a chance of containing these re-introduced Leatherworking recipes:\n\nhttps://www.wowhead.com/item=18514\nhttps://www.wowhead.com/item=18515\nhttps://www.wowhead.com/item=18516\nhttps://www.wowhead.com/item=18517\nhttps://www.wowhead.com/item=18518\nhttps://www.wowhead.com/item=18519\n\nThings to note:\nhttps://www.wowhead.com/item=18250 is a low chance drop off any Gordok Ogre in Dire Maul North. The key is also unique, so you'll only be able to carry one at a time.\nI'd recommend kiting as many ogres as you can as close to Knot as you can, to avoid having to run back and forth around the instance every time you loot a key.\nThe drop rate also sucks, I've been consistently only getting 1-3 keys per full clear of the North Wing.",
            date = "2023-07-13T22:38:17-05:00",
            sourceUrl = "https://www.wowhead.com/quest=77194#comments:id=5647907",
        },
        {
            id = 5650063,
            score = 17,
            author = "Beace",
            text = "Picked up 2 recipes from 7 boxes so far.",
            date = "2023-07-15T23:49:56-05:00",
            sourceUrl = "https://www.wowhead.com/quest=77194#comments:id=5650063",
        },
        {
            id = 5889681,
            score = 3,
            author = "remid0d0s0",
            text = "Knot is absolutely back and his cache does drop recipes.\n\nIt doesn't drop recipes frequently though (as you will quickly discover with some disappointment). Assuming you are starting from the north entrance (obviously?), two things to bear in mind:\n\nAny ogre can drop a key. I've had two drop (in one run!) before getting to Gordok and I'm sure some people have had runs with a half dozen. BOLO and if you get one before Gordok, get to Knot with as little combat as possible and turn it in. If you are planning to pull all the trash to Knot rather than kill it a bit at a time, you may miss out on a key, but, not a big deal in the scheme of things as long as you do check before you get to Knot.\n\nThe greens that drop can be valuable. I got a https://www.wowhead.com/item=14840 from one mob and then in the very next pack of trash, another one. Well, okay then. That made up for a lot of 2xhttps://www.wowhead.com/item=4234 caches.\n\nIt'll be a heck of a grind getting anything like all of Knot's patterns, but if you are an AH goblin, you'll probably get 5-20k of greens (realistic sale value) per hour in the process, and a little more from leather if you can skin.",
            date = "2024-06-28T23:50:12-05:00",
            sourceUrl = "https://www.wowhead.com/quest=77194#comments:id=5889681",
        },
        {
            id = 6148965,
            score = 3,
            author = "NiELkE",
            text = "Farmed DM north for 1 hour.\n\nGot 11 keys and 7 recipes from those keys.\n\nThe last boss seems to 100% drop a key.",
            date = "2025-07-25T11:43:17-05:00",
            sourceUrl = "https://www.wowhead.com/quest=77194#comments:id=6148965",
        },
    },
    [77205] = {
