    [77266] = {
        {
            id = 5772635,
            score = 1,
            author = "Oceandust",
            text = "I struggled so much with getting Gold on this one. Took me about 2 hours to figure out something that worked for me. You know how you're always like 1-3 seconds short every time and don't really know where you can actually gain speed to make up the time? What worked for me is by gaining speed right at the very start of the race and maintaining that speed throughout the rest of the course.\n\nAs soon as the timer ticks down. Back to back spam Surge Forward twice even before your wings unfold. This will take you through the first 2 rings. Immediately after hit Skyward Ascent when you grab the first green Vigor bubble in the second ring. This should give you enough speed to maintain throughout the rest of the race.\n\nNow that you have your speed, starting roughly around the 10th ring you WILL need to ground skim to get extra vigor bubbles so try to stay as low as you possibly can. Try to ground skim as much as possible throughout the rest of the race and just spam your Surge Forward.\n\nThis method is what got me gold. Hope this helps!",
            date = "2024-01-26T22:15:18-06:00",
            sourceUrl = "https://www.wowhead.com/quest=77266#comments:id=5772635",
        },
