    [77644] = {
        {
            id = 5712676,
            score = 17,
            author = "dillybar",
            text = "If you have successfully gotten yourself https://www.wowhead.com/item=7146, a keyring will appear at the top of the stairs as you head into The Grand Vestibule inside the outside world version of [zone=796] in Tirisfal Glades.\n\nThe first time you interact with the keyring, it will give you this quest https://www.wowhead.com/quest=77644, it's an immediate turn in at the same time.  This will give you account-wide access to the old version of Scarlet Monastery.\n\nTo gain access to the old version of Scarlet Monastery, simply click on the Old Keyring to toggle The Scarlet Key on and off. This will give you a buff on your character called \"The Scarlet Key - Retracing the steps of those who came before.\"\n\nWith the Scarlet Key buff active, the portals for Mists of Pandaria versions of Scarlet Halls and Scarlet Monastery will instead zone you into the old Scarlet Graveyard and Library, and the two doors that originally led to the Armory and Cathedral are once again open!",
            date = "2023-10-29T20:40:36-05:00",
            sourceUrl = "https://www.wowhead.com/quest=77644#comments:id=5712676",
        },
        {
            id = 5711564,
            score = 8,
            author = "bodhirana",
            text = "If you can't see the key chain and quest as soon as you walk up the steps in the entrance, you're in the wrong phase of Tirisfal. You need to talk to Zidormi and ask to see Tirisfal from before the Battle for Lordaeron. If you see the blight scar at Undercity, wrong phase.  The Thomas Hallows Eve quest line also requires you to be in the \"before the battle\" phase too.",
            date = "2023-10-26T23:20:02-05:00",
            sourceUrl = "https://www.wowhead.com/quest=77644#comments:id=5711564",
        },
        {
            id = 5706670,
            score = 4,
            author = "BananaBomb",
            text = "Looted the https://www.wowhead.com/item=208485 through trick and treating, the candy buckets at inns.\nQuest turned in at the old keyring at the entrance to Scarlet Monastery in Tirisfal Glades",
            date = "2023-10-18T04:38:09-05:00",
            sourceUrl = "https://www.wowhead.com/quest=77644#comments:id=5706670",
        },
        {
            id = 5707498,
            score = 4,
            author = "R1NN1",
            text = "You can buy it from AH as well.",
            date = "2023-10-19T08:49:26-05:00",
            sourceUrl = "https://www.wowhead.com/quest=77644#comments:id=5707498",
        },
        {
            id = 5707383,
            score = 3,
            author = "Chocomoose",
            text = "It can also be obtained in Doan's lockbox at the end of the Old Scarlet Monastery Library dungeon when using the keys (instance on the right of the doors)",
            date = "2023-10-19T04:24:26-05:00",
            sourceUrl = "https://www.wowhead.com/quest=77644#comments:id=5707383",
        },
    },
