    [78938] = {
        {
            id = 5908911,
            score = 8,
            author = "Naas",
            text = "update 8/1/2024:  After today's hotfix where memory rewards were buffed, the quests are now account-wide and daily instead of weekly. So you can only complete the 3 zone quests once per day for your account.\n\nAs of 7/30/2024, the weeklies are per character as opposed to account-wide. Also, Residual Memories are transferable between your characters.\n\nDo each of the 3 weeklies on all your alts if you want to earn Residual Memories more quickly.",
            date = "2024-07-30T23:04:18-05:00",
            sourceUrl = "https://www.wowhead.com/quest=78938#comments:id=5908911",
        },
        {
            id = 5909932,
            score = 8,
            author = "godded",
            text = "If you wanna quickly check which zone weeklies you've already done on that character.\n\n/run local quests={{id=78938,zone=\"Searing Gorge\"},{id=82676,zone=\"Dustwallow Marsh\"},{id=82689,zone=\"Dragonblight\"}} for _,q in ipairs(quests) do print(q.zone..\": \"..(C_QuestLog.IsQuestFlaggedCompleted(q.id) and \"Completed\" or \"Not Completed\")) end\n\nEdit: The script still works, but it seems like quests are now warband/account wide. No need to check on each character anymore.",
            date = "2024-07-31T20:51:05-05:00",
            sourceUrl = "https://www.wowhead.com/quest=78938#comments:id=5909932",
        },
        {
            id = 5911096,
            score = 5,
            author = "Dracon",
            text = "The Weekly's are now WARBAND/ACCOUNT wide. as of 1 Aug 2024. and the zones run continuously for an hour, no waiting any more or massive lag.",
            date = "2024-08-01T23:27:26-05:00",
            sourceUrl = "https://www.wowhead.com/quest=78938#comments:id=5911096",
        },
        {
            id = 5908526,
            score = 4,
            author = "dazhypher",
            text = "The turn-in is inside the portal to the quest area, Duke the water ele.",
            date = "2024-07-30T16:24:44-05:00",
            sourceUrl = "https://www.wowhead.com/quest=78938#comments:id=5908526",
        },
        {
            id = 5909661,
            score = 4,
            author = "Gorgar",
            text = "You would think that when you are trying to sell the new expansion by releasing early content, it would some how work. The Firelord will not spawn, the quest put you in a do loop. 40-50 people all waiting for the event, it times down and BOOM absolutely nothing. Must be Previews of Coming attraction for the new expansion.",
            date = "2024-07-31T16:08:41-05:00",
            sourceUrl = "https://www.wowhead.com/quest=78938#comments:id=5909661",
        },
    },
    [80310] = {
    },
    [80311] = {
        {
            id = 5856570,
            score = 15,
            author = "shoogen",
            text = "I picked up this quest from https://www.wowhead.com/npc=63900 wandering around Dawn's Blossom\n/way #371 49 46\n\nYou can probably use a character that hasn't done any of the Cloud Serpent questline, but I used party sync so that I was able to pick up the quest on my main.",
            date = "2024-05-15T12:56:02-05:00",
            sourceUrl = "https://www.wowhead.com/quest=80311#comments:id=5856570",
        },
        {
            id = 5890092,
            score = 3,
            author = "il0vewowhead",
            text = "It's possible you don't even get this quest but move on, skipping it, straight to the next in the series from Instructor Tong.",
            date = "2024-06-29T22:16:06-05:00",
            sourceUrl = "https://www.wowhead.com/quest=80311#comments:id=5890092",
        },
        {
            id = 5893263,
            score = 3,
            author = "Jonesy4",
            text = "There is something else needed to get this quest, just not sure what. Went here on a new alliance remix toon and can't get the quest. When I pick up Wild things quest, All the things addon says that completion of wild things will prevent completion of this quest. Not sure what is needed here. I did complete the entire order of the cloud serpent/exalted rep on a main remix toon without completion of this quest. Maybe only party sync is possible now to complete this.\n\nEdit: so it seems my theory was correct. If you've already completed the questline on a remix toon, all toons are locked from this quest, unless you use party sync with someone who hasn't completed the questline.",
            date = "2024-07-06T20:01:01-05:00",
