            author = "godded",
            text = "If you wanna quickly check which zone weeklies, you've already done on that character.\n\n/run local quests={{id=78938,zone=\"Searing Gorge\"},{id=82676,zone=\"Dustwallow Marsh\"},{id=82689,zone=\"Dragonblight\"}} for _,q in ipairs(quests) do print(q.zone..\": \"..(C_QuestLog.IsQuestFlaggedCompleted(q.id) and \"Completed\" or \"Not Completed\")) end\n\nEdit: The script still works, but it seems like quests are now warband/account wide. No need to check on each character anymore.",
            date = "2024-07-31T20:50:32-05:00",
            sourceUrl = "https://www.wowhead.com/quest=82676#comments:id=5909929",
