            sourceUrl = "https://www.wowhead.com/quest=86565#comments:id=6343811",
        },
        {
            id = 6328150,
            score = 5,
            author = "DocBronner",
            text = "The fragments are sitting on the ground in front of the quest givers; they look kind of like horseshoes.  To modify the fragments hover your pointer around until it shows something to click on and then click.  Arator and Alleria will then run up to the Sinew shredder on the platform above, follow them and kill it.  Watch the cutscene.  Then travel to 35.37 59.10 to turn in.",
            date = "2026-04-10T15:29:01-05:00",
