            id = 6198129,
            score = 391,
            author = "Guadah",
            text = "To the south, fight \"Spawn of Shadra\" and collect Bonecarapace Fangs.\nTo the east, go down a little set of stairs and fight \"Child of Hir'eek\" and collect Bloodvein Clot.\nPlace the Bonecarapace Fangs into the Vase on the left of the altar.\nPlace the Bloodvein Clot into the Vase on the right of the altar.\n- The door is open. Follow the path.\nIn the next room, you click on the discs (An image will appear) and match them to their corresponding color of another disc.  If you click on the center Disc, you are transformed into a frog for a short period of time.\n\nThen turn the quest in and continue your campaign!",
            date = "2025-10-07T13:28:31-05:00",
            sourceUrl = "https://www.wowhead.com/quest=86644#comments:id=6198129",
        },
        {
            id = 6291107,
