    [86829] = {
        {
            id = 6297722,
            score = 3,
            author = "F0XDAI",
            text = "Hey everyone!   It's said here that the events of Warcraft 2 were \"nearly\" 30 years ago. If this doesn't sit quite right with anyone else, I agree and I know it's lazy, but here's what Google AI says, editing the copy/paste for clarity.\n\nApproximately 38 to 39 years have passed between the start of the Second War in Warcraft II and the beginning of World of Warcraft: Midnight.\n\nIn the established Warcraft lore timeline, dates are measured from the opening of the Dark Portal (Year 0):\nWarcraft II: Tides of Darkness begins in Year 4. Its expansion, Beyond the Dark Portal, takes place in Year 8.\nThe War Within (the expansion immediately preceding Midnight) is set in Year 41.\n\nWorld of Warcraft: Midnight is scheduled to release on March 2, 2026. While the exact in-universe year for Midnight has not been definitively confirmed by Blizzard, it is widely estimated to be Year 42 or 43 based on the established \"one year per expansion\" lore cadence and the three-year time skip that occurred between Shadowlands and Dragonflight.\n\nTimeline Overview\nEvent \009                                            Lore Year (ADP)\009               Gap from Warcraft II (Start)\nWarcraft II: Tides of Darkness\009    Year 4\009—                                              Start\nWarcraft III: Reign of Chaos\009    Year 20\009                                           16 Years\nWorld of Warcraft (Vanilla)\009            Year 25\009                                           21 Years\nThe War Within\009                            Year 41\009                                           37 Years\nWorld of Warcraft: Midnight\009   ~Year 42-43\009                                  ~38-39 Years\n\n*There is also a \"significant\" skip between Shadowlands and Dragonflight that covers three years of relative peace. This brings the total gap between the start of Shadowlands and the start of Dragonflight to five years (two years for the events of Shadowlands plus the three-year skip).\n\nAI can make mistakes, so double-check responses",
            date = "2026-03-04T14:09:52-06:00",
            sourceUrl = "https://www.wowhead.com/quest=86829#comments:id=6297722",
        },
    },
    [86830] = {
        {
            id = 6332509,
            score = 1,
            author = "ercarp",
            text = "Surprisingly good XP farm if you wanna stay here and grind mobs for a bit. I was averaging 650-700k xp/hour in healer spec. I bet if you played Tank or DPS you could easily go up to 800-900k xp/hour with how quickly the mobs respawn (there was basically no downtime between spawns for me).\n\nFor reference, questing has typically been in the 200-270k xp/hour range for me as I've been going through the campaign. But I've also been reading the quests, so take that into account.",
            date = "2026-04-17T02:43:55-05:00",
            sourceUrl = "https://www.wowhead.com/quest=86830#comments:id=6332509",
        },
