    [86852] = {
        {
            id = 6296891,
            score = 11,
            author = "Triadne",
            text = "I'm sorry but why the hell is this so demoralising? I'm supposed to defend them and my character even has to say \"nothing will get past me\" and yet there are entire hordes of void already in there and frickin everything gets past me because I'm just one fricking person. Who the heck thought this was a good quest design?\n\nAlso, I'm supposed to stop the forces getting through this entrance but there is nothing trying to get through. Is this the kind of quality we are supposed to expect these days?",
            date = "2026-03-03T17:33:40-06:00",
            sourceUrl = "https://www.wowhead.com/quest=86852#comments:id=6296891",
        },
        {
            id = 6293494,
            score = 9,
            author = "Kalnazzar",
            text = "IF YOU ARE IN SILVERMOON CITY AND HAVING TROUBLE TURNING IN \"LIGHT'S LAST STAND\" [MIDNIGHT] QUEST.\n\nYou're in the wrong spot! Lady Liadrin's projection (her glowing sun energy / yellow energy hologram model) is visible in Silvermoon City, and the game/quest tracker misleadingly registers it as her \"physical\" presence there.\n\nAfter the epilogue, you land RIGHT at her physical body (NPC ID 241068)—turn in there before flying off excitedly to check out the new Silvermoon!\n\nShe's standing in front of the March on Quel'Danas raid entrance on the Isle of Quel'Danas. (/way #2424 52.7 84.9)\n\nQuick directions (Horde):\n\nHearth to Orgrimmar (or your bind spot).\nTake the portal to Silvermoon City.\nExit the city and fly east across the long bridge to the Isle of Quel'Danas.\nFly to the raid entrance at /way #2424 52.7 84.9—Lady Liadrin is standing right in front.\n\nQuick directions (Alliance):\n\nHearth to Stormwind (or your bind spot).\nGo to the Mage Tower portal room.\nTake the portal to Shattrath City.\nIn Shattrath (Aldor Rise), take the Portal to Isle of Quel'Danas (lands at Sun's Reach Harbor). Note: Not 100% sure if this gets you to the new Midnight Isle of Quel'Danas or the old one, but I know there's a portal there.\nFly south to the raid entrance at /way #2424 52.7 84.9—Lady Liadrin is standing right in front.\n\nTurn-in complete! Next: Silvermoon Negotiations.",
            date = "2026-02-28T18:50:37-06:00",
            sourceUrl = "https://www.wowhead.com/quest=86852#comments:id=6293494",
        },
        {
            id = 6211854,
            score = 6,
            author = "Spilledstars",
            text = "I have myself in a stuck situation where I did all the work all the way up to the end.    Sat for the epilogue, have a teleport that does double teleporting, now as I stand in my capitol city there is no way to turn it in...\n\n...Horde side.  Are Alliance faring any better?  Let me know. p.s. Turalyon is a mean dad.  I bugfiled that for you.  You're welcome.",
            date = "2025-10-24T12:19:06-05:00",
