        },
        {
            id = 6300977,
            score = 3,
            author = "Tweenkey",
            text = "To get credit for Hungering Lightroot (https://www.wowhead.com/npc=238495/hungering-lightroot)\nYou must OPEN the door first! Then fight.\nUse the Humming Core (https://www.wowhead.com/item=/humming-core) to open the door.\nYou WILL NOT get credit for Hungering Lightfoot\nUntil you complete the first part of the quest.\n\nOpen the door\nHungering Lightfoot Slain",
            date = "2026-03-07T13:35:22-06:00",
