    [88994] = {
        {
            id = 6298443,
            score = 67,
            author = "sarahlogic",
            text = "Stage 1: Click beetles or kill and loot marked mobs to collect pigment.\nStage 2: Enter the cave at 60.37, 19.08 to make your paintings. You do not have to use the action button arrows to move the paintbrush, you can just click the nodes in order with your mouse. You cannot go diagonally, so you will have to go left/right and up/down to connect the dots. Create a singular path from the paintbrush through the dots avoiding the dark stones. Once you click the last dot, it will move to the next puzzle. If you have any interface elements like party frames or cooldown bars, it may obscure parts of the puzzle.\nStage 3: Travel further into the cave and run over the animated paint to smash them, you do not have to attack them.\nStage 4: Take the path upstairs to the right at the back of the cave and use the extra action button around the paint blobs to collect them. Run to the cauldron on the same platform to deposit the blobs. It will teleport you out of the cave once successful.",
            date = "2026-03-05T09:52:58-06:00",
            sourceUrl = "https://www.wowhead.com/quest=88994#comments:id=6298443",
