    [89207] = {
        {
            id = 6295063,
            score = 11,
            author = "Elfizm",
            text = "Not sure if anyone else had this experience, but for a levelling quest, Magister Aradis was ridiculously OP.\n\nContinuously lobbed Chaos Bolts that landed like a truck. When he wasn't casting a curse or bolt, he was giving himself a nice shield.\n\nUnless you have various interrupts on short cooldowns, he effortlessly casts on you until you run out of mana, no time for cooldowns to reset, and he seemed to have almost 3 times the hp I did at the same level.",
            date = "2026-03-02T04:26:40-06:00",
            sourceUrl = "https://www.wowhead.com/quest=89207#comments:id=6295063",
        },
        {
            id = 6295800,
            score = 5,
            author = "Moonie1056",
            text = "He has a lot of health, took me some time to down him as a blood DK. Then I saw crumpled letter near Sarvi's dead body, realizing he had lured and killed her at least in part because we, as a player character, failed his mission.\nI  stayed a bit more and killed that scum Aradis 5 more times. Poor Sarvi, I was too late to save you, but I avenged you.",
            date = "2026-03-02T19:37:01-06:00",
            sourceUrl = "https://www.wowhead.com/quest=89207#comments:id=6295800",
        },
        {
            id = 6296571,
            score = 5,
            author = "Jacobstx",
            text = "\"Meet me upstairs after you take whatever you want from his corpse\"\n\nYou know me so well!",
            date = "2026-03-03T12:16:18-06:00",
            sourceUrl = "https://www.wowhead.com/quest=89207#comments:id=6296571",
        },
        {
            id = 6357817,
            score = 5,
            author = "Grothrill",
            text = "As an mage i spellstealed his shield when he cast it\nThat way i had his armor.\nthen its just a heal potion and use the  Gift of the Naaru healing effect once. Remember to Keep your own spell shield up all the fight. and spellsteal his shield.",
            date = "2026-05-18T12:40:22-05:00",
            sourceUrl = "https://www.wowhead.com/quest=89207#comments:id=6357817",
        },
        {
            id = 6337466,
            score = 1,
            author = "Oseliellic",
            text = "I had to switch to Preservation Evoker to defeat him",
            date = "2026-04-23T13:06:06-05:00",
            sourceUrl = "https://www.wowhead.com/quest=89207#comments:id=6337466",
        },
    },
    [89208] = {
        {
            id = 6295493,
            score = 23,
            author = "Samaramon1",
            text = "The dialogue afterwards is great.",
