        {
            id = 6295435,
            score = 24,
            author = "Chonar",
            text = "It's okay Kuri, I've done this twice before in the Vale of Eternal Blossoms, and Khaz Algar. I'll see you at the tail-end of the expansion.",
            date = "2026-03-02T14:20:58-06:00",
