            id = 6292279,
            score = 27,
            author = "Guadah",
            text = "Don't forget to pick up \"Leave Ashes in Your Wake\" and \"Executing the Blades\" before you head in.  Otherwise, doing this quest as a fresh 90 was a pain in the ass.  The addition of the two paladin NPC's is quite helpful.",
            date = "2026-02-27T19:32:52-06:00",
            sourceUrl = "https://www.wowhead.com/quest=90555#comments:id=6292279",
        },
        {
            id = 6308664,
            score = 19,
            author = "Jeolene",
            text = "All three of these quests are absolute BS... and I don't mean blacksmithing.\n\nNot only are all the mobs elites with massive health, but you have to kill 15 of them.\n\nAnd how in the hell are you traveling with two other paladins who can't even heal or do any damage?\n\nFFS, blizz, you're stupid.",
            date = "2026-03-16T11:34:24-05:00",
            sourceUrl = "https://www.wowhead.com/quest=90555#comments:id=6308664",
        },
        {
            id = 6309274,
            score = 15,
            author = "arisen1",
            text = "Why does Blizzard hate their playerbase? What an absolutely ridiculous quest.",
            date = "2026-03-16T22:14:13-05:00",
            sourceUrl = "https://www.wowhead.com/quest=90555#comments:id=6309274",
        },
        {
            id = 6319302,
            score = 4,
            author = "JimiDragon",
            text = "There is not enough CC that any character can do to survive this with a fresh 90. Mobs are packed together, so you get swarmed by 3 or 4 at a time.\n\nThe paladins along with you do not do enough damage or take ANY aggro from you, so expect to die unless you are a tank.",
            date = "2026-03-28T23:18:49-05:00",
            sourceUrl = "https://www.wowhead.com/quest=90555#comments:id=6319302",
        },
    },
