    [90573] = {
        {
            id = 6299540,
            score = 30,
            author = "frood88",
            text = "Don't do this quest the long way - Don't collect Misplaced Tomes around the zone for Latent Arcana!\nTL;DR - Use the coins from from Lord Sathriel to get quests from the guests - The quests reward 25 Latent Arcana per quest = the 100 Latent Arcana required for the Runestone!\n\nRead my full comment on https://www.wowhead.com/quest=90574 for details.",
            date = "2026-03-06T03:44:36-06:00",
            sourceUrl = "https://www.wowhead.com/quest=90573#comments:id=6299540",
        },
        {
            id = 6306430,
            score = 7,
            author = "Euphus",
            text = "The quest log recommends 5 people, but it appears to be soloable, with the boss scaling with players.",
            date = "2026-03-13T19:15:11-05:00",
            sourceUrl = "https://www.wowhead.com/quest=90573#comments:id=6306430",
        },
        {
            id = 6313670,
            score = 5,
            author = "Namariepat",
            text = "Adding my experience:\nI charged the runestone to 80%ish, wasn't enough so I went away to farm some more, when I came back someone else charged the thing to 100% and I couldn't participate in the small event of killing mobs and then the final boss (I tried killing them anyway but it didn't count for me). Then I looked for another runestone to charge and someone charged it to 100% while I was close to it and this time the thing started for me too even though I didn't contribute at all.\nSo I guess my take from this is: be close to the runestone when it gets to 100%.",
            date = "2026-03-21T14:22:12-05:00",
            sourceUrl = "https://www.wowhead.com/quest=90573#comments:id=6313670",
        },
        {
            id = 6363709,
            score = 3,
            author = "Unaffiliated",
            text = "This late into the first season and quests like these are still buggy as all hell.\n\nIt seems to be a public event, meaning your quest will point you to the next runestone available or something. I did the one the quest was pointing to, filled the mana, killed the mobs, killed the boss and had zero quest completion. So now the quest points me to the next runestone, but I've already spent all of my currency.\n\nGranted, world quests havent been as buggy as they were every single other patch across the last 2 expansions, but it still ticks me off that we pay such a premium for this slop.\n\n*Edit. Season 2 now and they seem to have cleaned up some of the bugginess with credit not being awarded for completion of an event (at least until you relog). The only bugs that still cause me problems is when you get phased out of your event mid boss fight. Ho hum.",
            date = "2026-06-04T10:13:49-05:00",
            sourceUrl = "https://www.wowhead.com/quest=90573#comments:id=6363709",
        },
    },
    [90574] = {
        {
            id = 6299425,
            score = 76,
            author = "frood88",
            text = "Don't do this quest the long way - Don't collect Coalesced Light orbs around the zone for Latent Arcana!\nTL;DR - Use the coins from from Lord Sathriel to get quests from the guests - The quests reward 25 Latent Arcana per quest = the 100 Latent Arcana required for the Runestone!\n\nIn contrast to other comments, this was a very easy and quick quest to complete solo (except for the very final kill - read on).\n\nEach week you select a sub-faction from Lord Sathriel, two of which offer a bonus coin (this week for me it showed the bonus coin for Blood Knights and Shades of the Row, not sure if this changes week to week)\n\nYou receive 3 coins by default, and an extra coin if you choose a faction with a bonus as above - This week, I chose Blood Knights, hence why I'm commenting on this quest.\n\nWith each coin, you speak to the four faction representatives in the same area (they have progress bars above their heads), and offer them a coin.\nIn return, they offer you a quest - Each quest rewards 25 Latent Arcana - 4 tokens (if you pick the bonus) = 100 Latent Arcana\nThese quests are very simple kill/collect quests around Eversong with minimal requirements.\n\nYou take your 100 Latent Arcana rewarded from the 4 quests to a Runestone and repeatedly click the button in the popup window - 100 Latent Arcana = 100% progress bar on the Runestone\n\nOnce the Runestone is at 100%, a heap of mobs will spawn, you kill a bunch of them to get another progress bar to 100%\n\nEverything has been easily and quickly solo-able so far\n\nNow an elite spawns - It is only for this final elite where a group would be handy, but in my case, there were a heap of players who happened to instantly turned up and it was all over in a few minutes.",
            date = "2026-03-05T23:57:48-06:00",
            sourceUrl = "https://www.wowhead.com/quest=90574#comments:id=6299425",
        },
        {
            id = 6298095,
            score = 39,
            author = "Tasseq",
            text = "This is probably the hands down worst event ive done in wow in my 20 years of playing the game. Good job blizzard.\nMaybe this is supposed to be done as a group thing and i did it early in the morning so i had to charge these stones totally by my self, which takes AGES.\nFor the record you have to collect those small yellow orbs around Eversong then go back to the runestone to charge it. One orb give you about 5% progress on the stone, and i think i have found one of these orbs every 10min or so.\nI will be humble and say that, maybe im just terrible at the game, but this is honestly just garbage quest/event design imo.\n\nedit: i have since writing calmed down a bit, and this is infinitely easier when there are players around.\nTLDR: Dont try to do this event alone in the middle of the night is my tip to others.",
            date = "2026-03-04T23:02:14-06:00",
            sourceUrl = "https://www.wowhead.com/quest=90574#comments:id=6298095",
        },
        {
            id = 6310313,
            score = 19,
