        {
            id = 6301458,
            score = 29,
            author = "apedosmil",
            text = "Aw, so you too are annoyed by the poopsockers ruining a fun little quest too!  Welcome to the club.  We have lemon squares and we zug to our own zug.",
            date = "2026-03-08T06:42:47-05:00",
