            id = 6271080,
            score = 2,
            author = "Shadmoon",
            text = "This quest text is actually different for warlocks! Enjoy!\n\nThe Cult of Twilight has long been dedicated to ending Azeroth. That they ally with Xal'atath is no surprise.\n\nIf the Twilight's Blade are indoctrinating citizens, we must stop them. Scout the Cleft of Shadows for cultists and end any you may find.\n\nThe cultist's rhetoric may appeal to you. Save your fraternizing with the Void for after we have destroyed Xal'atath and her Twilight's Blade.\n\nThe quest giver was also passive-aggressive and mentioned my character's void affiliation when I turned in the previous quest. Really love the flavor! :D",
            date = "2026-01-27T14:34:26-06:00",
            sourceUrl = "https://www.wowhead.com/quest=90760#comments:id=6271080",
        },
    },
    [90761] = {
