    [90819] = {
        {
            id = 6291465,
            score = 26,
            author = "Shanody",
            text = "Don't forget to click the dead mana wyrm next to the quest giver before you go flying off looking for something in Murder Row that isn't there yet... 🙄",
            date = "2026-02-27T04:17:08-06:00",
