        },
    },
    [90821] = {
        {
            id = 6297031,
            score = 12,
            author = "hawkengrey",
            text = "I'm getting my ass kicked as a squishy arcane mage in the Tarelin part of this fight. Feels a little overtuned for a quest, but also cool that there's some difficulty in these.",
            date = "2026-03-03T19:38:22-06:00",
            sourceUrl = "https://www.wowhead.com/quest=90821#comments:id=6297031",
        },
        {
            id = 6319891,
            score = 5,
            author = "Traach",
            text = "Incredibly overtuned damage dealt by the quest NPC as of this posting. leveled multiple alts. Mages and rogues will find this guy basically impossible to solo. plate wearers did ok. Warlock was fine because of pets. classes that have decent self heal will do fine as well.",
            date = "2026-03-30T00:50:09-05:00",
            sourceUrl = "https://www.wowhead.com/quest=90821#comments:id=6319891",
        },
        {
            id = 6334102,
            score = 3,
            author = "detanimationman",
            text = "Yep, still a crap quest for a mage at lv 88. Went in expecting the usual faceroll and died. Checked his health afterwards and it was like 588 000 to my 144 000. Basically burned all CDs....what else is there to say? Including the Draenei self heal racial and a healthpot. Killed him with 9% health left.\n\nContrary what others said....didn't feel like I was skilled or the fight was tuned to be a challenge. Mostly dumb luck...if you cannot snare / slow on your class, it is a !@#$ty design of  a fight. Got him on second try - if I would have failed I might have considered changing my specc or just abandon.\n\nBasically not worth the hassle on a levelling quest for a squishy dps.",
            date = "2026-04-19T15:52:03-05:00",
            sourceUrl = "https://www.wowhead.com/quest=90821#comments:id=6334102",
        },
        {
            id = 6373441,
