        {
            id = 6291879,
            score = 16,
            author = "Lucidify",
            text = "As a Draenei using the Man'ari Eredar (red skin) customisation the quest text is changed.\n\n\"We need to gather more evidence. Go around this area and see if you can find more hidden sources of fel. I have no fondness for what you are, demon--but if you will use your senses for good, then I have no quarrel with you.\"\n\nHe will also have a chat bubble saying \"Put your... affinities to use, demon. We will rendezvous shortly.\"\n\nAlong with you getting the same buff text as warlocks regardless of class: \"Fel Senses: Already attuned to the fel, you can effortlessly detect nearby fel magic.\"",
            date = "2026-02-27T12:41:44-06:00",
