    [90873] = {
        {
            id = 6292951,
            score = 18,
            author = "Chasavaqe",
            text = "This quest has unique text for draenei. Main quest text:\n\nThe domanaar capture us and others across worlds and force us to fight for their amusement. Their fascination with mortals is equal only to their sadism.\n\nI was able to improvise a device from a combination of my magic and the pure chaos of this world and use it to escape. It breaks shackles, both those literal and metaphysical. Using it just once takes a lot out of me.\n\nFree our kin and disrupt the gates they used to steal us to this world.\n\nI won't let anyone else be left behind. Never again.\n\nTurn in text:\n\nWhen we fight, it's on our terms.",
            date = "2026-02-28T10:28:18-06:00",
            sourceUrl = "https://www.wowhead.com/quest=90873#comments:id=6292951",
        },
        {
            id = 6292659,
