    [90874] = {
        {
            id = 6292952,
            score = 20,
            author = "Chasavaqe",
            text = "This quest has unique text for draenei. Main quest text:\n\nThe voidwalkers carry these, I've been able to use them as spell reagents, and they were helpful for my initial construction of the portal nexus. I presume that they'll help me attune it to our world.\n\nBesides that, they deserve death at your hands. Our suffering is their delight. Repay them the favor.\n\nTurn in text:\nThey want violence? You gave them violence. I savored the sight of it.\n\nThose runes look potent. That many should be enough.",
            date = "2026-02-28T10:29:22-06:00",
            sourceUrl = "https://www.wowhead.com/quest=90874#comments:id=6292952",
        },
        {
            id = 6300917,
            score = 6,
            author = "camerynmaru",
            text = "This quest \"Their Violent Ends\" and their companion quest \"These Violent Delights\" are an homage to the HBO series Westworld, where the phrase \"these violent delights have violent ends\" was a big part of the narrative during the first season. Very cool.",
