    [90924] = {
        {
            id = 6297241,
            score = 74,
            author = "MalenInsekt",
            text = "You see the blade being forged, and Blizzard couldn't even give us the correct model as a quest reward. All of the quest rewards are Silvermoon themed weapons, not void formed weapons.",
            date = "2026-03-04T01:58:12-06:00",
            sourceUrl = "https://www.wowhead.com/quest=90924#comments:id=6297241",
        },
        {
            id = 6302424,
            score = 50,
            author = "Dekabe",
            text = "They should've made this a renown quest to get a champion level weapon like the other factions or something like that. All that hype for a green questing weapon that doesn't even use the proper model is extremely disappointing.",
            date = "2026-03-09T14:49:23-05:00",
            sourceUrl = "https://www.wowhead.com/quest=90924#comments:id=6302424",
        },
        {
            id = 6304661,
            score = 47,
            author = "Demonface",
            text = "When you return to Decimus at the end of this quest, I'm pleasantly surprised that unique responses are given for every dialogue option for once.\n\nPlayer: I felt nothing.\n\nDecimus: Could that be? Was the flavor I tasted merely my own desire? Fascinating.\nI shall have to ponder my lack of insight.\n\nPlayer: (Lie) I felt nothing.\n\nDecimus: Now, now, . You can't lie to me. I tasted your pain.\nIt was delicious.\n\nPlayer: I have never felt deeper sorrow. I thought we were friends. How could you do this to me?\n\nDecimus: Yes, yes! So this is the flavor of your pain. How indulgent! Thank you.\n\nPlayer: (Lie) I have never felt deeper sorrow. I thought we were friends. How could you do this to me?\n\nDecimus: Interesting...so this is as deep as the flavor gets? I confess, I am disappointed.\nPerhaps the taste of bestial violence is better than mortal suffering after all.\n\nPlayer: I'm a little irritated, but don't really care.\n\nDecimus: Ah, so you do have a healthy emotional balance, do you? How boring.\nClearly, I must find myself someone more traumatized to torment.\n\nPlayer: I don't owe you the dignity of a response.\n\nDecimus: I suppose I cannot blame you.\nStill, it was a pleasant journey. For my part, at least.\n\nPlayer:\n\nDecimus: Easy, now. I understand your displeasure, but we must remain allies.\nFor the sake of Azeroth, right? Here, here, take the blade...",
            date = "2026-03-12T07:04:28-05:00",
            sourceUrl = "https://www.wowhead.com/quest=90924#comments:id=6304661",
        },
        {
            id = 6302860,
            score = 31,
            author = "Birja",
            text = "For how much talk about empowering this 'blade' throughout the quest line, this is a super lame reward.\nIt looks nothing like the model used during the quest, and it is a mace.",
            date = "2026-03-10T08:05:06-05:00",
            sourceUrl = "https://www.wowhead.com/quest=90924#comments:id=6302860",
        },
        {
            id = 6310206,
