    [91066] = {
        {
            id = 6187445,
            score = 204,
            author = "offspinner",
            text = "I'm baffled by the 'adding the hops' part of the quest. What are we supposed to do? The progress bar is entering the red zone whatever I do.\n\nedit: Here's how it works. Press and release the hop button once, then keep it pressed down until the bar enters the yellow zone.",
            date = "2025-09-23T03:33:07-05:00",
            sourceUrl = "https://www.wowhead.com/quest=91066#comments:id=6187445",
        },
        {
            id = 6187412,
            score = 20,
            author = "Seby",
            text = "- Grab the pretzel ingredients from https://www.wowhead.com/npc=245964 (talk to the cart :) ), then click a lot on the table to the right! Serve the pretzel in the middle.\n- Grab the soup ingredients again from the cart, stir left or right randomly (better than the Iskaara soup!), then serve the soup in the middle.\n- Grab the brew ingredients  again from the cart, smash a lot on the table to the left! Heat up the oven (I turned it to 10). When adding the hops, aim for the \"middle\" yellow bar, small medium or large will be different, so keep the button pressed and release on yellow, just like evoker skills! Serve the brew in the middle.",
            date = "2025-09-23T02:31:41-05:00",
            sourceUrl = "https://www.wowhead.com/quest=91066#comments:id=6187412",
        },
        {
            id = 6187786,
            score = 20,
            author = "Borlan",
            text = "If you're having trouble seeing the bar like I was, you're probably using ElvUI. Just disable the addon, and you should be able to complete the quest. Win!",
            date = "2025-09-23T15:04:25-05:00",
            sourceUrl = "https://www.wowhead.com/quest=91066#comments:id=6187786",
        },
        {
            id = 6189473,
            score = 15,
            author = "redsedalia",
            text = "If you are not able to see the bar, go into 'Edit Mode' by pressing 'Esc'. It is your \"cast bar\". Just move it to where you can see it. Also...\n\nThe bar has 4 colors! white, red, GOLD, and the yellow. The sweet spot is the GOLD color! To play it safe, click on the chosen bag (1, 2, or 3) and that should bring up the bar. Immediately press down on button because the bar is already moving! Hold the button down and release it when it is about half way into the red. What counts is where it is at when the bar stops. The first 'Bag' has the smallest amount of each color, thus making it harder to hit the spot. The second is a little more, and the third has the most, making it the easiest. You want GOLD...Not Yellow! It may take a little time to get the hang of it, but you will get it. And if it helps, you only have to do that quest one time...well...per toon...\n\nHave fun and hope this helps ♥",
            date = "2025-09-27T06:03:12-05:00",
            sourceUrl = "https://www.wowhead.com/quest=91066#comments:id=6189473",
        },
        {
