    [91084] = {
        {
            id = 6295772,
            score = 3,
            author = "Jakobi",
            text = "I logged out after finishing the Harandar questline and this quest next to the portal disappeared completely. The quest still showed there, which worried me that I couldn't access it. However, when I went to the Sanctum of Light, a dwarf NPC \"Koruth Mountainfist\" showed up out of nowhere with the quest. I completed it, but the quest still remains on my map of Silvermoon, so I think I got the Alliance version.\n\nEdit: I returned to the Haranir portal in Silvermoon where the quest marker remains and the Looming Shadows quest was actually there. I had also just completed the Zul'Aman. If you're having issues, just continue with the story and check back. The quest seems unimportant tot he campaign and just seems to trigger some dialogue at the Sanctum of Light before you move onto the next chapter.",
            date = "2026-03-02T18:58:37-06:00",
            sourceUrl = "https://www.wowhead.com/quest=91084#comments:id=6295772",
        },
        {
            id = 6280407,
