    [91382] = {
        {
            id = 6298103,
            score = 57,
            author = "Aeder",
            text = "You get him as a pet either way.\n\nI slew the Den-Gorger while Fidoficus cowered in fear.\n[spoiler] Ravenia says:\nHe WHAT?\nWhat a fool I was to waste my time investing in such a pathetic worm!\nI'd consume the beast myself if I thought it had any strength whatsoever for me to feast upon!\nNow begone, the both of you! You're no longer worthy of my presence.\n\n*Fidoficus cowers in fear*\n [/spoiler]\n\nHe was an avatar of terror and destruction.\n[spoiler] Ravenia says:\nI am pleased to hear that. It pains me to say it, but you have done well, mortal.\nIn time, Fidoficus will become a terrible horror to behold.\nBut in the meantime, keep him in your care. It may be the best way to cultivate his growth.\n\n*Fidoficus shows his affection* [/spoiler]",
            date = "2026-03-04T23:11:53-06:00",
            sourceUrl = "https://www.wowhead.com/quest=91382#comments:id=6298103",
        },
