        {
            id = 6292697,
            score = 15,
            author = "Galtak",
            text = "Speaking to Shadra after she hatches, she offered me three dialogues. Two of them I believe to be triggered from previous completed questlines in the Hinterlands and Ardenweald. I am unsure if the Hinterlands trigger was from Cataclysm or Classic as I did both.\n\nMe: Do you remember me from the Hinterlands?\n\nShadra: Yes... collecting my venom for some nefarious purpose, weren't you.\nI will let it slide, for now\n\n&\n\nMe: Do you rememeber me from Ardenweald?\n\nShadra: Of course. You aided me in Ardenweald to be reborn.\nWe are forever allies, Maw Walker",
            date = "2026-02-28T04:18:26-06:00",
            sourceUrl = "https://www.wowhead.com/quest=91412#comments:id=6292697",
        },
    },
