            id = 6307421,
            score = 9,
            author = "Ashbringer12",
            text = "If you are a blood elf, the quest text is quite different and reads (with a typo):\n\n\"\n\nI ask you, is it right that we ren'dorei were exiled from Silvermoon? By what right do you sin'dorei deny us access to our families? To our homes?\n\nBlood elves say we are a threat the Sunwell. This is a lie. The truth is, they are simply afraid of us. Of what they do not understand. Are you?\n\nWe're here to protect something of value. Kill any beasts that threaten those flowers for Hieron's tea. Silvermoon can save itself.\"",
            date = "2026-03-14T18:20:56-05:00",
            sourceUrl = "https://www.wowhead.com/quest=91536#comments:id=6307421",
        },
