    [92025] = {
        {
            id = 6293312,
            score = 44,
            author = "violetta",
            text = "after so many quests having to 'unwittingly' serve obviously evil people in order to reach the stages where they 'shockingly' betray us and then eventually get their comuppance, it's nice to see on of those subverted once in a while",
            date = "2026-02-28T15:52:01-06:00",
            sourceUrl = "https://www.wowhead.com/quest=92025#comments:id=6293312",
        },
        {
            id = 6296715,
            score = 31,
            author = "Anevay",
            text = "Vendor in Goldenmist - \"That magister has nefarious intentions!\"\nTalandra - \"I just wanted to have wine with my girlfriend...\"",
            date = "2026-03-03T14:25:41-06:00",
            sourceUrl = "https://www.wowhead.com/quest=92025#comments:id=6296715",
        },
        {
            id = 6305482,
            score = 19,
            author = "Stariknight",
            text = "She is in the uninstanced Windrunner Spire a short flight away. Don’t waste your time queuing the dungeon and trying to find her.",
            date = "2026-03-12T23:10:12-05:00",
            sourceUrl = "https://www.wowhead.com/quest=92025#comments:id=6305482",
        },
        {
            id = 6294698,
            score = 7,
            author = "BishaRampage85",
            text = "When you get to the quest spot, you find:\n\nAmalthea Dawnsprite which has a buff \"Incorporeal, unable to interact with the material plane\" and Talandra Dawnsprite\ntalking to Amalthea she says:\n\nOh? The adventurer speaks to the lowly banshee. No wonder Talandra took a liking to you.\"\n\nDialogue button: What happened to you?\n\nWhat happened to me? || should have thought it obvious. I died\nCountless Farstriders fell in the war against the traitor prince. More fell in the ensuing years, defending what was left of our home from the remnants of the Scourge. Some of us were granted the mercy of death. And some of us were not so lucky.\nTalandra was a Magister, once. But she has since dedicated herself to learning more profane arts, as a means of easing the suffering of those of us who remain.\n\nTalking to Talandra Dawnsprite before you turn in Flowers for Amalthea quest, she says:\n\nBefore you decide to get all\n\"overzealous adventurer\" on me, allow me a moment to explain.\nI am a necromancer, yes. I omitted key details of my plans for our shopping list in order to make it more likely that you would lend me your aid. But I promise you, my intentions are not nefarious.\nThe banshee you see before you was once a Farstrider--a hero of Quel 'Thalas.\nAnd now she is in pain.\nPlease, allow me to finish this ritual. You may arrest me or strike me down or do whatever it is you do once l am done.\nAre we agreed?\n\n(Quest) “Very well.”",
            date = "2026-03-01T18:44:51-06:00",
            sourceUrl = "https://www.wowhead.com/quest=92025#comments:id=6294698",
        },
        {
            id = 6308291,
            score = 6,
            author = "Defianse",
            text = "This NPC is NOT inside the Windrunner Spire instanced dungeon, she is behind it in the world.\nThis does not bring you into the dungeon at any stage.",
            date = "2026-03-15T19:06:52-05:00",
            sourceUrl = "https://www.wowhead.com/quest=92025#comments:id=6308291",
        },
    },
