    [92159] = {
        {
            id = 6383806,
            score = 1,
            author = "Peacemoon",
            text = "When you return to Lanlae Noxa back at camp, she has multiple of these creatures trapped. You can ask her \"Why are there so many creatues now?\"\n\n\"Good of you to check in on us.\nIt is a fun story. You see, I brought the creature along with me when I was investigating other cases of similar void disturbances. It drew out others to investigate it! They are quite curious, I think.\nOr malicious and they want to eat each other--I'm still looking into that.\nI may be on a very lucrative  business in removing hauntings, although my intention was to learn.\nSoon enough I'll have a whole collection of these creatures. I'll need to find a suitable place to keep them all!\"\n\nA coincidence the final quest is a reference to the Final Destination horror films? I don't think so!",
            date = "2026-07-20T06:06:40-05:00",
            sourceUrl = "https://www.wowhead.com/quest=92159#comments:id=6383806",
        },
    },
