    [92931] = {
        {
            id = 6394074,
            score = 13,
            author = "speter7949",
            text = "If you're having trouble completeing this quest (clicking on the guy won't work, no icon in the quest log)...\n\nThe item is in your bag.  Search for Cauterize and click on it while targeting Zul'jarra.",
