        {
            id = 6395368,
            score = 6,
            author = "kyfzsrjytdjtrsdk",
            text = "In order to talk with Dok'Zor you need to 'kill' the 'Beatin Man' dummy he's practicing on.",
            date = "2026-08-13T16:25:33-05:00",
