    [92934] = {
        {
            id = 6394342,
            score = 10,
            author = "Pluck123",
            text = "If your character was sitting (e.g. eating) while starting the quest, you won't be able to heal the npcs, even though the NPC you control is clearly standing up. You need to exit the vehicle and start again when standing up.",
            date = "2026-08-12T16:26:39-05:00",
            sourceUrl = "https://www.wowhead.com/quest=92934#comments:id=6394342",
        },
        {
            id = 6398176,
            score = 6,
            author = "ZosotheMage",
            text = "If you leave the witch doctor phase before you turn in the quest the quest givers will not be visible.  To correct this just go back to Orweyna in the temple behind the quest giver location and talk to her and ask the do the vision that turns you back into the witch doctor.  You can then turn in the quest without having to do it over.",
            date = "2026-08-14T22:02:38-05:00",
            sourceUrl = "https://www.wowhead.com/quest=92934#comments:id=6398176",
        },
