    [92946] = {
        {
            id = 6304073,
            score = 11,
            author = "Thrilling",
            text = "Tablet of Empire:\n\nOur great peoples...\n...the cities we built... untold grandeur... Shimmering in the Sky...\nPredacea... shone with knowledge... scholarship... our greatest weapon... in the wars to come.\n\nRiftwalker Alayshen says: Did you carve this tablet, specter? Your people... your civilization... were they lost to war?\nMysterious Specter says: Only my beautiful weapons could stop the bloodshed.\n\nTablet of Conquest:\n\nEmpire of... first strike...\n...City... lost... another. until no more...\n...They needed me. They asked me... great Akintunde...\n...make weapon... save them all...\n\nRiftwalker Alayshen says: Specter... You are Akintunde? Some sort of weaponsmith?\nAkintunde the Unstoppable says: My empire asked for a weapon to end the wars. I obliged.\n\nTablet of Annihilation:\n\nIn the wake of my weapon... War ended.\n...all ended... cities razed... no more war... no more...\nOnly... smallest life survived... evolved over eons... monsters, beasts now...\n...In the final wave... before the end... my...\nBETRAYED ME... LOCKED ME AWAY... PUNISHMENT... FOR GIVING WHAT THEY ASKED...\n\nRiftwalker Alayshen says: No, it cant be... your weapons ended all civilization on Predacea? How could you live with yourself? How do you linger?\nAkintunde the Unstoppable says: Only the strong survive. My people were weak. I overcame death itself! And now you will help my rebirth.\nRiftwalker Alayshen says: We'll see about that.",
            date = "2026-03-11T13:16:08-05:00",
            sourceUrl = "https://www.wowhead.com/quest=92946#comments:id=6304073",
        },
        {
            id = 6344706,
            score = 1,
            author = "Elevated11",
            text = "Is there any way to enter those caves outside doing quest?",
            date = "2026-04-26T20:14:23-05:00",
            sourceUrl = "https://www.wowhead.com/quest=92946#comments:id=6344706",
        },
    },
