    [93019] = {
        {
            id = 6408962,
            score = 5,
            author = "Veliore",
            text = "Fun fact: The name of this quest refers to sarcastic military slang acronym SNAFU - Situation Normal: All F**ked Up. The term describes a chaotic situation, mess, or an error where things go wrong, but implies that this level of dysfunction is completely typical or expected. The term originated in the United States military during WWII where soldiers used it to describe bureaucratic confusion, supply chain failures, general chaos and more. Nowadays you can use it as both a noun and a verb!",
            date = "2026-08-30T15:44:18-05:00",
            sourceUrl = "https://www.wowhead.com/quest=93019#comments:id=6408962",
        },
        {
            id = 6400346,
            score = 4,
            author = "SilianRail",
            text = "you need to make sure to pick up the other quest (The Serpent's Tail) otherwise this will take forever.",
            date = "2026-08-16T13:51:52-05:00",
            sourceUrl = "https://www.wowhead.com/quest=93019#comments:id=6400346",
        },
        {
            id = 6399362,
            score = 3,
            author = "Artemise",
            text = "Am I missing something, or is this one of the slowest quests to complete ever? Only 1 specific mob gives credit, and only gives 3%? So we have to fly around individually hunting 1 mob at a time 34 times?",
            date = "2026-08-15T16:33:06-05:00",
            sourceUrl = "https://www.wowhead.com/quest=93019#comments:id=6399362",
        },
        {
            id = 6403970,
            score = 3,
            author = "AQL1",
            text = "A friendly info:\n\nIf you do this quest, take the quest The Serpents Tail (https://www.wowhead.com/quest=95564/the-serpents-tail) at the same time!\n\nWhy? Otherwise you only get credit for this quest by one single target and you get only three (3) percent per kill. If you pick up the above mentioned quest, all mobs will be eligable and you will be in done in less than three minutes → https://youtu.be/QinCfwb_-_Y",
            date = "2026-08-21T15:01:10-05:00",
            sourceUrl = "https://www.wowhead.com/quest=93019#comments:id=6403970",
        },
