            author = "Alfa",
            text = "Here is improved macro that will show if you have the delve quest completed in your log OR if you have returned the quest already. It shows the title of the quest/delve and color coordinated completed vs not.\n\n/run local l,q=C_QuestLog,{93372,93384,93385,93409,93410,93416,93421,93427,93428,93386}for i,v in ipairs(q)do print((l.IsQuestFlaggedCompleted(v)or l.IsComplete(v))and\"\\124c0000FF00\"or\"\\124c11FF1100\",l.GetTitleForQuestID(v),\"\\124r\")end\n\nhttps://i.imgur.com/rwtslGm.png",
