    [93418] = {
        {
            id = 6402337,
            score = 63,
            author = "Angelx911",
            text = "So if you don't actually meet the NPCs outside of Gate of the Serpent's Eye, completing the raid doesn't give credit.\n\nJust a heads up unless this doesn't get changed/hotfixed.",
            date = "2026-08-18T23:18:09-05:00",
            sourceUrl = "https://www.wowhead.com/quest=93418#comments:id=6402337",
        },
        {
            id = 6406167,
            score = 53,
            author = "sarahlogic",
            text = "If you are doing this on story mode, it is currently very buggy. You will need to keep the button toggled for you to lead the followers since they don't know where to go. Continue forward (the only way to go) and kill trash in the winding hallway until you are able to reach the coiled alter platform. I can't recall if the miniboss is here or after the first boss, but he will prevent you from going forward either way, so keep that in mind. The map is a bit confusing and does not help navigate here.\n\nThe followers do not do mechanics on this fight, but mainly you run over the green glowy orbs and stand in the center of the platform until they drop and repeat. When the frontal is aimed at you, you want to try to hit the orbs. If you have a ghost chasing you, face it to freeze it in place. It will need to be hit with the frontal as well, but as currently designed, that may not be easy to do, just do your best to face it so it does not keep knocking you back. Don't stand in the purple pools for long, and move away from the NPCs when they get a gloombomb (big green ring), as they don't move out.\n\nAfter the first fight, continue forward. Click one of the drums on either the side of the platform of the large atrium. Jump down from the center ledge into the poison pool and swim forward to the lower platform. Make sure you have the extra action button toggled for you to lead. If the NPCs are on lead, they won't join you. The final boss will spawn here.\n\nThe followers ping where to stand on this fight and are much better at mechanics. Mainly focus on killing the eggs (the NPCs won't help you on these) and adds when they spawn, focus the heart when it's available to hit, stand in the soaks, dodge the poison waves from the front left and right and side of the platform. When he crashes into the center you can jump over the quadrant cracks to attack the eggs that spawn there.\n\nHopefully they fix the frustrating parts of this story mode by the time you are reading this, but if not, I hope this helped you.",
            date = "2026-08-25T18:38:52-05:00",
            sourceUrl = "https://www.wowhead.com/quest=93418#comments:id=6406167",
        },
        {
            id = 6403197,
            score = 39,
            author = "woofpuppy",
            text = "The campaign should not be gated to wait for LFR. Not everybody raids, Blizz.",
            date = "2026-08-20T10:13:58-05:00",
            sourceUrl = "https://www.wowhead.com/quest=93418#comments:id=6403197",
        },
        {
            id = 6403212,
            score = 32,
            author = "Pluck123",
            text = "So if you didnt enter the underground through the north entrance and you completed the raid, there is no way to complete it this week\nYou need to actually use the correct entrance before doing the raid.. 10/10 blizzard",
            date = "2026-08-20T10:52:15-05:00",
            sourceUrl = "https://www.wowhead.com/quest=93418#comments:id=6403212",
        },
