        {
            id = 6298152,
            score = 6,
            author = "MrGiblets",
            text = "I used the Dragonhawk loa, so I don’t know if this applies to the others: the first ability is a casted cone damage ability, the second is a channeled damage AOE (so don’t interrupt it by moving or casting something), the third is a area damage aura and you can use other abilities while it’s active, and the fourth ability gives 10 seconds of increased movement and attack speed, so use it often. Additionally, use right-click to melee, as it does decent damage.\n\nAfter killing the Raid Leader, you can exit (use the red arrow in the bottom right of the action bar) and fly back to the quest giver rather than run, if you want.",
            date = "2026-03-05T00:49:29-06:00",
            sourceUrl = "https://www.wowhead.com/quest=93437#comments:id=6298152",
        },
