    [93503] = {
        {
            id = 6347293,
            score = 4,
            author = "codin",
            text = "Some useful info about this quest. With this new expansion (Midnight) blizzard has changed their quest design. Weekly quests used to disappear from your quest log after the weekly reset (Tuesday 8am). This is no longer the case. Rather instead, you still have the quest BUT you cannot make progress since the week is over. Its a really stupid design change that needs looking into on their end. I've also seen where having the weekly prevents you from picking up the correct and current weekly that replaced said quest. This is not always the case. For instance; housing weekly's do not prevent you from picking up the new weekly, PvP is 50/50, and PvE content is all over the place. Poor game design.",
            date = "2026-04-30T08:16:28-05:00",
            sourceUrl = "https://www.wowhead.com/quest=93503#comments:id=6347293",
        },
        {
