    [96276] = {
        {
            id = 6403076,
            score = 15,
            author = "Mairin",
            text = "These seemed really infrequent to start with but, once you get your eye in, its pretty quick to get them all.\n\nFirstly, these aren't some little dots on the floor, they're full sized objects. The seem to take 2 forms (that I found), that being a spike sticking out of the ground (same graphic as the spikes that bind the 4 serpent rituals in the vaul activities) and the other being a smaller spike hanging from a rope.\n\nI collected all 20 just wandering around the central circle of the map (a few in the venom pits but mostly on the outer paths). I got 11 \"outside\" and the other 9 in the crypt at /way 39.37 48.18 .\n\nThey didn't seem to respawn, at least not in a timely manner, but there was plenty more visible than needed.\n\nGood luck!",
            date = "2026-08-20T02:58:56-05:00",
            sourceUrl = "https://www.wowhead.com/quest=96276#comments:id=6403076",
        },
