        {
            id = 6394297,
            score = 118,
            author = "fahsoder",
            text = "If you're stuck on this quest, here's what worked for me:\n\n* Go to the Vaults of Atal'Utek in the Coiled Isle.\n* Complete the Temple Patrols to progress the events.\n* The Temple Strikes seem to be bugged. If they aren't showing or progressing properly, join a Custom Group through the Group Finder. This made the Strikes appear correctly for me.\n* Complete 2 Temple Strikes.\n* About 5 minutes after completing the 2nd Strike, the Temple Incursion will appear.\n* Complete the Incursion, and the Ancient Foe will then appear.\n\nHope this helps anyone else stuck on this quest!",
            date = "2026-08-12T15:40:54-05:00",
            sourceUrl = "https://www.wowhead.com/quest=98515#comments:id=6394297",
        },
        {
            id = 6394115,
            score = 55,
            author = "Avafugl",
            text = "The \"Slay an Ancient Foe\" portion of the quest refers to the Eventboss \"Khu'tulak\" for anyone thats stuck. He spawns near the coords 52,22 at \"The Seal of Wrath\" once the event has progressed far enough.",
            date = "2026-08-12T11:53:34-05:00",
            sourceUrl = "https://www.wowhead.com/quest=98515#comments:id=6394115",
        },
